insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0002abf8-4a3f-4494-a446-abff3e8470ce', 'Biology', 'JAMB', null, 2002, null, 'The structures found only in plant cell are', null, '["cell membranes and cytoplasm","chromatin and nucleolus","cell wall and chloroplast","cell membrane and lysosome"]', 2, 'Plant cells possess a rigid cell wall and chloroplasts, which are absent in animal cells.', true, '2026-10-12 20:05:09.051', '2026-10-12 20:05:09.051', null, null, null, 'The structures found only in plant cell are', '["cell membranes and cytoplasm","chromatin and nucleolus","cell wall and chloroplast","cell membrane and lysosome"]', 'Plant cells possess a rigid cell wall and chloroplasts, which are absent in animal cells.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('00056846-71fd-4fee-963b-292b9b01a53a', 'Biology', 'JAMB', null, 2026, null, 'The scapula and ischium are part of the', null, '["pectoral girdle","pelvic girdle","appendicular skeleton","hind limb"]', 2, 'The scapula (shoulder blade) and ischium (lower part of the pelvis) are both parts of the appendicular skeleton. The scapula is part of the pectoral girdle (forelimb attachment). The ischium is part of the pelvic girdle (hindlimb attachment). Together, the appendicular skeleton includes all bones of the limbs and the girdles that attach them to the axial skeleton. The pectoral girdle alone includes the scapula and clavicle. The pelvic girdle includes the ilium, ischium, and pubis. The hind limb includes the leg bones, not the pelvic bones.', true, '2026-09-09 03:18:45.713', '2026-09-09 03:18:45.713', null, null, null, null, null, null, null);
