insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0009988a-a56e-4256-8f01-61044068c6e1', 'English Language', 'JAMB', null, 2024, null, 'Choose the word with the same vowel sound as the letter highlighted: Band<u>a</u>ge', null, '["cacophony","says","cage","kite"]', 0, 'The "a" in "bandage" sounds like /æ/, same as the "a" in "cacophony."', true, '2026-09-18 09:43:02.224', '2026-10-24 17:22:56.995', null, null, 'STANDALONE', null, null, null, null);
