insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('003785a3-c2f5-43b4-9fb6-72de408a317e', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). Kelechi <u>hardly ever</u> falls sick.', null, '["most often","very seldom","sometimes","frequently","occasionally"]', 1, '''Hardly ever'' = very seldom.', true, '2026-10-24 01:02:02.057', '2026-10-24 01:02:02.057', null, null, null, '(Choose the most appropriate interpretation). Kelechi <u>hardly ever</u> falls sick.', '["most often","<u>very seldom</u>","sometimes","frequently","occasionally"]', '''<b>Hardly ever</b>'' = <b>very seldom</b>.', '{}');
