insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('00bdee04-8cf6-45f9-87a6-76da3c33677d', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'The significance of the Passover in Israelite history is that it commemorates', null, '["their escape from Egypt","the giving of the law","crossing of the Jordan","conquest of Jericho"]', 0, 'The Passover commemorates the Israelites'' escape from slavery in Egypt. God struck down all the firstborn of Egypt but passed over the houses of the Israelites who had marked their doorposts with the blood of a lamb.', true, '2026-09-12 09:45:46.133', '2026-09-12 09:45:46.133', null, null, null, null, null, null, null);
