insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('025ed4b5-0ffd-45a5-89a1-9269ace5f92e', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). <u>A basic objective in this respect is the attainment of self-sufficiency in food in about a decade.</u>', null, '["Food will soon be sufficient for everybody","Mass production of food","We should aim at producing food for sale and consumption in ten years","We should be able to feed ourselves in five years","Our aim is to provide enough food for our needs in ten years"]', 4, 'Self-sufficiency in food in a decade = enough food in ten years.', true, '2026-10-24 01:02:01.687', '2026-10-24 01:02:01.687', null, null, null, '(Choose the most appropriate interpretation). <u>A basic objective in this respect is the attainment of self-sufficiency in food in about a decade.</u>', '["Food will soon be sufficient for everybody","Mass production of food","We should aim at producing food for sale and consumption in ten years","We should be able to feed ourselves in five years","<u>Our aim is to provide enough food for our needs in ten years</u>"]', '<b>Self-sufficiency in food in a decade</b> = <b>enough food in ten years</b>.', '{}');
