insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('026ddecf-0d73-4944-a6a9-bc97cc4296ca', 'Physics', 'JAMB', null, 1985, null, 'What is the number of neutrons in the Uranium isotope with mass number 238 and atomic number 92?', null, '["92","146","238","330","119"]', 1, 'Neutrons = mass number - atomic number = 238 - 92 = 146.', true, '2026-10-12 19:15:22.61', '2026-10-12 19:15:22.61', null, null, null, 'What is the number of neutrons in the Uranium isotope with mass number 238 and atomic number 92?', '["92","146","238","330","119"]', 'Neutrons = mass number - atomic number = 238 - 92 = 146.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('027d9b4a-b876-46b1-9fb0-65b5e83b4a05', 'Physics', 'JAMB', null, 1993, null, 'A weightless vessel of dimensions 4 m x 3 m x 2 m is filled with a liquid of density 1000 kg m⁻³ and sealed. What is the maximum pressure this container can exert on a flat surface? [g = 10 m s⁻²]', null, '["9 x 10⁴ N m⁻²","4 x 10⁴ N m⁻²","3 x 10⁴ N m⁻²","2 x 10⁴ N m⁻²"]', 1, 'Weight = ρVg = 1000 x 24 x 10 = 2.4 x 10⁵ N. Maximum pressure is when it rests on its smallest face (3 m x 2 m = 6 m²): P = 2.4 x 10⁵/6 = 4 x 10⁴ N m⁻².', true, '2026-10-12 19:15:37.324', '2026-10-12 19:15:37.324', null, null, null, 'A weightless vessel of dimensions 4 m x 3 m x 2 m is filled with a liquid of density 1000 kg m<sup>-3</sup> and sealed. What is the maximum pressure this container can exert on a flat surface? [g = 10 m s<sup>-2</sup>]', '["9 x 10<sup>4</sup> N m<sup>-2</sup>","4 x 10<sup>4</sup> N m<sup>-2</sup>","3 x 10<sup>4</sup> N m<sup>-2</sup>","2 x 10<sup>4</sup> N m<sup>-2</sup>"]', 'Weight = ρVg = 1000 x 24 x 10 = 2.4 x 10<sup>5</sup> N. Maximum pressure is when it rests on its smallest face (3 m x 2 m = 6 m<sup>2</sup>): P = 2.4 x 10<sup>5</sup>/6 = 4 x 10<sup>4</sup> N m<sup>-2</sup>.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
