insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('030c0da6-5bf9-45f7-8f75-61d9144ad9f9', 'Literature in English', 'JAMB', null, 2026, null, 'Mention one theme reflected in this extract', null, '["Disloyalty","Grief","Duty","Passion"]', 3, 'Passion is a theme reflected in this extract.', true, '2026-09-12 11:11:19.273', '2026-09-12 11:11:19.273', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('031cf10c-6a79-4dc8-9457-a8c3b3fcfdca', 'Literature in English', 'JAMB', null, 2026, null, 'In Still I Rise, the repetition of ''I rise'' is an example of', null, '["Alliteration","Anaphora","Euphemism","Irony"]', 1, 'The repetition of ''I rise'' is anaphora.', true, '2026-09-12 11:09:54.245', '2026-09-12 11:09:54.245', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0327b835-9864-4638-9193-2dc82250a85b', 'Financial Accounting', 'UTME', null, 2004, null, 'In a three-column cash book, the discount allowed is shown on the', null, '["debit side","credit side","both sides","neither side"]', 0, 'Discount Allowed is an allowance given to a debtor. It will be shown on the debit side of the cashbook. It is a reduction in the amount owed by a customer.', true, '2026-10-12 22:00:02.099', '2026-10-12 22:00:02.099', null, null, null, 'In a three-column cash book, the discount allowed is shown on the', '["<b>debit side</b>","credit side","both sides","neither side"]', 'Discount Allowed is an allowance given to a debtor. It will be shown on the <b>debit side</b> of the cashbook. It is a reduction in the amount owed by a customer.', '{"bold":["debit side"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('032bbbf5-d579-464d-af8f-1631bc8f67a1', 'Biology', 'JAMB', null, 2004, null, 'The eggs of birds contain relatively larger quantities of yolk than those of amphibians and reptiles because', null, '["birds are generally bigger in size","embryonic development is longer in birds","those of birds are fertilized internally","birds lay shelled eggs"]', 1, 'Embryonic development is longer in birds.', true, '2026-10-12 20:59:35.118', '2026-10-12 20:59:35.118', null, null, null, 'The eggs of birds contain relatively larger quantities of yolk than those of amphibians and reptiles because', '["birds are generally bigger in size","embryonic development is longer in birds","those of birds are fertilized internally","birds lay shelled eggs"]', 'Embryonic development is longer in birds.', '{"bold":["Embryonic development is longer in birds"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0342baea-977c-46d2-822a-27bfd4584fbc', 'Biology', 'JAMB', null, 2026, null, 'The process of deamination is essential for the', null, '["digestion of protein","secretion of bile","formation of urea","formation of antibody"]', 2, 'Deamination is the removal of an amino group (-NH₂) from amino acids, producing ammonia (NH₃). This process is essential for the formation of urea because ammonia is toxic and must be converted to urea in the liver through the urea cycle. Deamination occurs primarily in the liver during protein metabolism when excess amino acids are broken down. Digestion of protein is the breakdown of proteins into amino acids by proteases. Bile secretion and antibody formation are unrelated to deamination. The ammonia produced is converted to urea for safe excretion.', true, '2026-09-09 03:18:43.744', '2026-09-09 03:18:43.744', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('035d7560-fd4a-40c9-962e-6934ead60080', 'Christian Religious Studies', 'JAMB', null, 2026, null, '“…And they shall be my people, and I will be their God...” This covenant was made with Israel through Prophet...', null, '["Isaiah","Jeremiah","Amos","Hosea"]', 1, 'Jeremiah 31:33 and Jeremiah 32:38 highlight this formulation as part of the New Covenant promised through Jeremiah.', true, '2026-09-09 17:18:28.257', '2026-09-09 17:18:28.257', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0363c6c8-6a1b-441e-b759-ae292da1f768', 'Physics', 'JAMB', null, 1992, null, 'A wire of length 15 m made of a material of resistivity 1.8 x 10⁻⁶ Ω m has a resistance of 0.27 Ω. Determine the area of the wire.', null, '["1.5 x 10⁻⁴ m²","1.0 x 10⁻⁴ m²","2.7 x 10⁻⁵ m²","7.3 x 10⁻⁵ m²"]', 1, 'A = ρL/R = (1.8 x 10⁻⁶ x 15)/0.27 = 1.0 x 10⁻⁴ m².', true, '2026-10-12 19:15:36.412', '2026-10-12 19:15:36.412', null, null, null, 'A wire of length 15 m made of a material of resistivity 1.8 x 10<sup>-6</sup> Ω m has a resistance of 0.27 Ω. Determine the area of the wire.', '["1.5 x 10<sup>-4</sup> m<sup>2</sup>","1.0 x 10<sup>-4</sup> m<sup>2</sup>","2.7 x 10<sup>-5</sup> m<sup>2</sup>","7.3 x 10<sup>-5</sup> m<sup>2</sup>"]', 'A = ρL/R = (1.8 x 10<sup>-6</sup> x 15)/0.27 = 1.0 x 10<sup>-4</sup> m<sup>2</sup>.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('036d9bb6-a1b2-4385-b8d4-13988db24fbb', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. We all have both good and bad characteristics. Either is, however, easily <u>manifested</u> in times of crisis.', null, '["demanded","highlighted","submerged","determined"]', 1, 'Manifested = highlighted/shown.', true, '2026-10-24 01:03:58.35', '2026-10-24 01:03:58.35', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. We all have both good and bad characteristics. Either is, however, easily <u>manifested</u> in times of crisis.', '["demanded","<u>highlighted</u>","submerged","determined"]', '<b>Manifested</b> = <b>highlighted</b>/shown.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('03789e0d-c3d6-4514-8f0a-c1d58436ae03', 'Physics', 'JAMB', null, 1994, null, 'Which of the following has the lowest internal resistance when new?', null, '["Leclanché cell","Daniell cell","Accumulator","Torch battery"]', 2, 'A lead-acid accumulator has a very low internal resistance, which allows it to supply large currents.', true, '2026-10-12 19:15:40.183', '2026-10-12 19:15:40.183', null, null, null, 'Which of the following has the lowest internal resistance when new?', '["Leclanché cell","Daniell cell","Accumulator","Torch battery"]', 'A lead-acid accumulator has a very low internal resistance, which allows it to supply large currents.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('037f8942-d001-4db7-b970-e3dd457728b1', 'Hausa', 'JAMB', null, 2011, null, 'Rabo nawa wasan Shaihu Umar na U. Ladan da D. Lyndersay ya kunsa?', null, '["Biyu.","Uku.","Hudu.","Biyar."]', 0, 'Wasan Shaihu Umar ya kunsa rabo biyu.', true, '2026-10-13 10:37:23.018', '2026-10-13 10:37:23.018', null, null, null, 'Rabo nawa wasan Shaihu Umar na U. Ladan da D. Lyndersay ya kunsa?', '["Biyu.","Uku.","Hudu.","Biyar."]', 'Wasan Shaihu Umar ya kunsa rabo biyu.', '{"bold":["biyu"],"italic":[],"underline":[],"fillBlanks":[]}');
