insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('039cb044-28fc-4329-a787-2ac7cd2b11b9', 'Literature in English', 'JAMB', null, 2026, null, 'The rhyme scheme of the first stanza is', null, '["Aabb","Abab","Abcd","Abba"]', 1, 'The rhyme scheme is ABAB.', true, '2026-09-12 11:13:53.162', '2026-09-12 11:13:53.162', null, null, null, null, null, null, null);
