insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('03fd07c9-7418-4d50-95c5-7ac30ad06e9b', 'English Language', 'JAMB', null, 2007, null, 'We have to <u>iron out our differences</u> at once.', null, '["We must ensure that our problems are eliminated at all cost","We must clear up without delay our misunderstanding","We have to solve some problems for now","We have to settle our disagreement once and for all"]', 1, '''Iron out differences'' = clear up misunderstanding.', true, '2026-10-24 01:02:09.994', '2026-10-24 01:02:09.994', null, null, null, 'We have to <u>iron out our differences</u> at once.', '["We must ensure that our problems are eliminated at all cost","<u>We must clear up without delay our misunderstanding</u>","We have to solve some problems for now","We have to settle our disagreement once and for all"]', '''<b>Iron out differences</b>'' = <b>clear up misunderstanding</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0414f5ba-f6ee-42e9-a1a7-03f983df683d', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). Some men will continue to cause offenses until they are <u>given a taste of their own medicine</u>.', null, '["placated","recompensed for","revenged on","cured"]', 2, '''Given a taste of their own medicine'' = revenged on.', true, '2026-10-24 01:02:09.293', '2026-10-24 01:02:09.293', null, null, null, '(Choose the most appropriate interpretation). Some men will continue to cause offenses until they are <u>given a taste of their own medicine</u>.', '["placated","recompensed for","<u>revenged on</u>","cured"]', '''<b>Given a taste of their own medicine</b>'' = <b>revenged on</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0415c7de-7397-4fe7-a2fe-231ed1c74a1b', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. It would be difficult to defeat such a <u>highly motivated</u> team.', null, '["very immature","very demoralized","highly decided","completely disillusioned"]', 1, 'Highly motivated; opposite = very demoralized.', true, '2026-10-24 07:21:25.784', '2026-10-24 07:21:25.784', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. It would be difficult to defeat such a <u>highly motivated</u> team.', '["very immature","very demoralized","highly decided","completely disillusioned"]', 'Highly motivated; opposite = very demoralized.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0418518f-de93-41de-b446-422241cc3103', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The boxer <u>fizzled out</u> just in the sixth round.', null, '["became tired but fought on spiritedly","surrendered rather disappointingly","knocked out his opponent","showed off his talents"]', 1, 'Fizzled out = surrendered disappointingly.', true, '2026-10-24 01:01:53.64', '2026-10-24 01:01:53.64', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The boxer <u>fizzled out</u> just in the sixth round.', '["became tired but fought on spiritedly","<u>surrendered rather disappointingly</u>","knocked out his opponent","showed off his talents"]', '<b>Fizzled out</b> = <b>surrendered disappointingly</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('041a9e1b-972d-43a6-a3ed-90cc287cbe1c', 'Biology', 'JAMB', null, 2026, null, 'An onion is a bulb because it', null, '["has adventitious roots","bears many buds at the nodes","has a tuberous stem","has a reduced stem and thick fleshy leaves"]', 3, 'A bulb is a modified underground stem with a reduced, disc-like stem (basal plate) from which concentric layers of fleshy leaves (scales) arise. These fleshy leaves store nutrients and water, enabling the plant to survive adverse conditions. Adventitious roots grow from the base. A tuber (like a potato) is a swollen stem, while a corm (like cocoyam) is a swollen stem base without fleshy leaves. Rhizomes are horizontal underground stems.', true, '2026-09-09 03:18:15.883', '2026-09-09 03:18:15.883', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0422aaec-a3eb-4cd9-b3d2-894eec707c3c', 'English Language', 'JAMB', null, 2007, null, 'Neither the students nor the teacher <u>________</u> the words of the principal.', null, '["understand","understands","are understanding","is understanding"]', 1, 'Nearest subject ''teacher'' singular â†’ understands.', true, '2026-10-24 01:04:30.45', '2026-10-24 01:04:30.45', null, null, null, 'Neither the students nor the teacher <u>________</u> the words of the principal.', '["understand","<u>understands</u>","are understanding","is understanding"]', 'Nearest subject ''<b>teacher</b>'' singular â†’ <b>understands</b>.', '{}');
