insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('04280f93-d20f-4392-a70f-49878561b74e', 'English Language', 'JAMB', null, 2007, null, 'All the cattle on Lamidi''s farm <u>â€¦â€¦â€¦..</u>', null, '["is tick-free","are tick-free","is ticks-free","are ticks-free"]', 1, '''Cattle'' plural â†’ are tick-free.', true, '2026-10-24 01:04:28.129', '2026-10-24 01:04:28.129', null, null, null, 'All the cattle on Lamidi''s farm <u>â€¦â€¦â€¦..</u>', '["is tick-free","<u>are tick-free</u>","is ticks-free","are ticks-free"]', '''<b>Cattle</b>'' plural â†’ <b>are tick-free</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('04337653-28ed-4682-912b-6baf2ed29989', 'English Language', 'JAMB', null, 2024, null, 'Choose the correct emphatic stress: The new principal deals RUTHLESSLY with lazy teachers', null, '["does the new principal deal leniently with lazy teachers?","does the new principal deal ruthlessly with industrious teachers?","does the former principal deal ruthlessly with lazy teachers?","does the new principal deal ruthlessly with lazy students?"]', 0, 'The emphasis on "RUTHLESSLY" contrasts with "leniently."', true, '2026-09-18 09:43:02.686', '2026-09-18 09:43:02.686', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('043af884-0fd9-4502-b65d-66dc93b67d40', 'Biology', 'JAMB', null, 2026, null, 'A man with blood group A is married to a woman with blood group A. Which of the following group combinations is possible if the family has three children?', null, '["B, A, AB","O, A, B","B, AB, AB","A, O, A"]', 3, 'A, O, A is possible. If both parents are blood group A, they could have genotypes AO or AA. If both are AO, they could have children with blood groups A (AA or AO), O (OO), but not B or AB. The possible blood group combinations with two A parents are: A and O only. Therefore, ''A, O, A'' is the only option that fits. B and AB are impossible because neither parent has the B allele.', true, '2026-09-09 03:19:19.516', '2026-09-09 03:19:19.516', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('044332d6-358a-45dd-8fca-dc3ba19cfdf5', 'English Language', 'JAMB', null, 2024, null, 'The word utility, as used in the passage, means', null, '["difficulty","management","usefulness","attitude"]', 2, '"Utility" means usefulness.', true, '2026-09-18 09:43:02.753', '2026-09-18 09:43:02.753', null, null, 'COMPREHENSION', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('04569db0-e693-4004-977a-b1abff97919d', 'Biology', 'JAMB', null, 2003, null, 'An argument against Lamark''s theory of evolution is that', null, '["disuse of body part cannot weaken the part","disused part is dropped off in the offspring","acquired traits cannot be passed onto the offspring","traits cannot be acquired through constant use of body parts"]', 2, 'Acquired traits cannot be passed onto offspring.', true, '2026-10-12 20:59:33.998', '2026-10-12 20:59:33.998', null, null, null, 'An argument against Lamark''s theory of evolution is that', '["disuse of body part cannot weaken the part","disused part is dropped off in the offspring","acquired traits cannot be passed onto the offspring","traits cannot be acquired through constant use of body parts"]', 'Acquired traits cannot be passed onto offspring.', '{"bold":["Acquired traits cannot be passed onto offspring"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('04591a8a-b8f3-4585-9cf9-05b862fbd2b6', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'In order that Benjamin might be brought to Egypt, Joseph detained', null, '["Reuben","Levi","Judah","Simeon","Zebulun"]', 3, 'Joseph detained Simeon to ensure his brothers would bring Benjamin.', true, '2026-09-12 10:41:14.751', '2026-09-12 10:41:14.751', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('045d711f-f88f-482a-96ea-616b92498396', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The man preaches <u>egalitarianism</u> without matching it up with action.', null, '["salvation","dedication","kindness","equality"]', 3, 'Egalitarianism = equality.', true, '2026-10-24 01:01:49.551', '2026-10-24 01:01:49.551', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The man preaches <u>egalitarianism</u> without matching it up with action.', '["salvation","dedication","kindness","<u>equality</u>"]', '<b>Egalitarianism</b> = <b>equality</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('046d9597-914d-4aff-a58f-4b962bb0bf2f', 'Financial Accounting', 'UTME', null, 2003, null, 'Verifiability in accounting is only possible when there are', null, '["minutes of meetings","payment vouchers","source documents","audit Certificates"]', 2, 'Source Documents captured relevant details relating to financial transaction as they occurred, thus verifiability in accounting is possible with source documents.', true, '2026-10-12 21:59:59.288', '2026-10-12 21:59:59.288', null, null, null, 'Verifiability in accounting is only possible when there are', '["minutes of meetings","payment vouchers","<b>source documents</b>","audit Certificates"]', '<b>Source Documents</b> captured relevant details relating to financial transaction as they occurred, thus verifiability in accounting is possible with source documents.', '{"bold":["source documents"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('047542ef-0e16-4147-a68b-d9dfe9ac17fd', 'Biology', 'JAMB', null, 2026, null, 'An example of endospermous seed is', null, '["cashew","cotton","bean","maize"]', 3, 'Maize (corn) is an endospermous seed, where the endosperm tissue persists and provides nutrition to the germinating seedling. The endosperm makes up a large portion of the mature seed. In cashew, cotton, and bean, the endosperm is absorbed during seed development and the cotyledons serve as the primary food storage organs (exalbuminous or non-endospermous seeds). Endospermous seeds are characteristic of monocots like maize, wheat, and rice, while many dicots are non-endospermous.', true, '2026-09-09 03:18:27.078', '2026-09-09 03:18:27.078', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0476d57f-c3c0-498c-9533-df4cf6369f82', 'English Language', 'JAMB', null, 2024, null, 'Choose the option that best explains the information conveyed in the sentence: Ado is one of the backwoodsmen', null, '["he is one of the honest men that lived in the community","he is one of those that live in the most developed part of the city","he is one of the active members of the community","he is one of those that live in a distant and undeveloped area"]', 3, '"Backwoodsmen" refers to people who live in a distant and undeveloped area.', true, '2026-09-18 09:43:02.913', '2026-09-18 09:43:02.913', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('04772fe3-ac83-4f68-b81b-24fce73cf048', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. I would not like you to do the work <u>piecemeal</u>.', null, '["at meal time","bit by bit","badly","as a masterpiece"]', 1, 'Piecemeal = bit by bit.', true, '2026-10-24 01:03:55.861', '2026-10-24 01:03:55.861', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. I would not like you to do the work <u>piecemeal</u>.', '["at meal time","<u>bit by bit</u>","badly","as a masterpiece"]', '<b>Piecemeal</b> = <b>bit by bit</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('047bd423-d45c-4681-96ee-c8084cc20c68', 'English Language', 'JAMB', null, 2024, null, 'Choose the option opposite in meaning to the underlined word: The team lost the match because their goalkeeper was in a <u>haze</u> most of the time.', null, '["indisposed","confused","alert","sleeping"]', 2, '"Haze" here means a state of confusion or mental fog; the opposite is "alert."', true, '2026-09-18 09:23:08.471', '2026-10-24 17:25:08.359', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('047fc5e8-25d6-4086-b4fd-216e4de7681a', 'Physics', 'JAMB', null, 1992, null, 'A machine requires 1000 J of work to raise a load of 500 N through a vertical distance of 1.5 m. Calculate the efficiency of the machine.', null, '["80%","75%","50%","33%"]', 1, 'Useful work = 500 x 1.5 = 750 J. Efficiency = 750/1000 x 100 = 75%.', true, '2026-10-12 19:15:35.07', '2026-10-12 19:15:35.07', null, null, null, 'A machine requires 1000 J of work to raise a load of 500 N through a vertical distance of 1.5 m. Calculate the efficiency of the machine.', '["80%","75%","50%","33%"]', 'Useful work = 500 x 1.5 = 750 J. Efficiency = 750/1000 x 100 = 75%.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('048617f5-21f7-448b-9ea1-bfb778f762e6', 'Biology', 'JAMB', null, 2026, null, 'Low annual rainfall, sparse vegetation, high diurnal temperatures and cold nights are characteristic features of the', null, '["Tropical rainforest","Desert","Montane forest","Guinea savanna"]', 1, 'Low annual rainfall, sparse vegetation, high diurnal temperatures, and cold nights are characteristic features of the desert biome. Deserts receive less than 250 mm of rainfall per year. Temperatures can fluctuate widely from very hot during the day to cold at night. Vegetation is sparse and adapted to conserve water (xerophytes). Tropical rainforests have high rainfall, dense vegetation, and stable warm temperatures. Montane forests have high altitude and cooler temperatures. Guinea savanna has moderate rainfall and extensive grass cover.', true, '2026-09-09 03:18:59.921', '2026-09-09 03:18:59.921', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0486f889-b627-4ca7-a95b-1490d0ec8e9d', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The debtor''s husband is <u>liable</u> for his wife''s debts.', null, '["unanswerable","responsible","unquestionable","accountable"]', 0, 'Liable = responsible; opposite = unanswerable.', true, '2026-10-24 07:21:11.52', '2026-10-24 07:21:11.52', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The debtor''s husband is <u>liable</u> for his wife''s debts.', '["unanswerable","responsible","unquestionable","accountable"]', 'Liable = responsible; opposite = unanswerable.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('04a12ffd-5b7f-4774-91a7-d35b93916e8a', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The newly elected leader has <u>pledged</u> to ensure better life for the citizens.', null, '["vowed","agreed","undertaken","undertaking"]', 0, 'Pledged = vowed.', true, '2026-10-24 01:01:46.742', '2026-10-24 01:01:46.742', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The newly elected leader has <u>pledged</u> to ensure better life for the citizens.', '["<u>vowed</u>","agreed","undertaken","undertaking"]', '<b>Pledged</b> = <b>vowed</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('04b2d5a9-deb2-4458-bab1-531db000c07b', 'Physics', 'JAMB', null, 2026, null, 'What colour has the lowest frequency in the spectrum of white light?', null, '["Red","Yellow","Green","Violet"]', 0, 'Red has the lowest frequency in the spectrum of white light. The order of increasing frequency is: red, orange, yellow, green, blue, indigo, violet. Red light has the longest wavelength and lowest frequency.', true, '2026-09-10 10:56:39.729', '2026-09-10 10:56:39.729', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('04c0b529-60e6-45d7-8600-9ce085753cf7', 'Government', 'JAMB', null, 2026, null, 'The party system practised in Nigeria''s third republic was', null, '["zero-party","one-party","two-party","multi-party"]', 2, 'The third republic practised a two-party system.', true, '2026-09-12 11:24:11.433', '2026-09-12 11:24:11.433', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('04eb9601-9776-45a3-93ce-c829bb55c97b', 'Biology', 'JAMB', null, 2010, null, 'Which of the following is NOT a function of the nucleus of a cell?', null, '["It controls the life processes of the cell.","It translates genetic information for the manufacture of proteins.","It stores and carries hereditary information.","It is a reservoir of energy for the cell."]', 3, 'The nucleus is not a reservoir of energy for the cell.', true, '2026-10-12 20:59:38.653', '2026-10-12 20:59:38.653', null, null, null, 'Which of the following is NOT a function of the nucleus of a cell?', '["It controls the life processes of the cell.","It translates genetic information for the manufacture of proteins.","It stores and carries hereditary information.","It is a reservoir of energy for the cell."]', 'The nucleus is not a reservoir of energy for the cell.', '{"bold":["not a reservoir of energy"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('04eed74c-8eb7-4126-9036-dec150c05f57', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'According to John, he who does not believe in the only Son of God is', null, '["none His own","cast off as a branch","condemned already","not worthy of the Kingdom"]', 2, 'He who does not believe is condemned already (John 3:18).', true, '2026-09-12 10:41:54.021', '2026-09-12 10:41:54.021', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('04f36122-2abf-4ec1-9390-3e3bebba53d3', 'Yoruba', 'JAMB', null, 2002, null, 'Ìwé Ìwúre Níbi Àyèyç ni Ìbéèrè 29-31 dá lé. ‘Èyin bàbá wa tó wà níkàlé’ Nínú Ìwúre Níbi Àsè Ìjílé, çsç òkè yìí tòka sí àwòn', null, '["lòbalòba","irúnmòlé","Alára àti Ajerò","Alayé."]', 2, 'Çsç òkè yìí tòka sí Alára àti Ajerò.', true, '2026-10-13 13:22:39.671', '2026-10-13 13:22:39.671', null, null, null, 'Ìwé Ìwúre Níbi Àyèyç ni Ìbéèrè 29-31 dá lé. ‘Èyin bàbá wa tó wà níkàlé’ Nínú Ìwúre Níbi Àsè Ìjílé, çsç òkè yìí tòka sí àwòn', '["lòbalòba","irúnmòlé","Alára àti Ajerò","Alayé."]', 'Çsç òkè yìí tòka sí Alára àti Ajerò.', '{"bold":["Alára àti Ajerò"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('04fb91f0-c8b7-47d3-8c45-1d28e1e6e22f', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. You''re <u>impossible</u>; she said to me.', null, '["unreasonable","unforgiving","daft","strong"]', 0, 'Impossible = unreasonable.', true, '2026-10-24 01:04:08.803', '2026-10-24 01:04:08.803', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. You''re <u>impossible</u>; she said to me.', '["<u>unreasonable</u>","unforgiving","daft","strong"]', '<b>Impossible</b> = <b>unreasonable</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('050902e9-7702-4243-9053-0995afe2713b', 'Financial Accounting', 'UTME', null, 2004, null, 'Determine the accumulated fund value', 'https://res.cloudinary.com/kwi1uv0g/image/upload/v1791841912/questions/mqtwjs9qg12fxglmhbmu.jpg', '["N9 360","N6 320","N4 200","N3 000"]', 0, 'Accumulated fund is the same thing as Capital. In Accounting Equation Capital = Assets. Therefore, Capital / Accumulated fund = 9360.', true, '2026-10-12 22:00:03.182', '2026-10-12 22:00:03.182', null, null, null, 'Determine the accumulated fund value', '["<b>N9 360</b>","N6 320","N4 200","N3 000"]', 'Accumulated fund is the same thing as Capital. In Accounting Equation Capital = Assets. Therefore, Capital / Accumulated fund = <b>9360</b>.', '{"bold":["9360"],"italic":[],"underline":[],"fillBlanks":[]}');
