insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0583ecc9-932f-424c-8279-9e12c1154f6e', 'Biology', 'JAMB', null, 2011, null, 'In mammals, the exchange of nutrients and metabolic products occurs in the', null, '["lungs","oesophagus","trachea","lymph."]', 3, 'Exchange of nutrients and metabolic products occurs in the lymph.', true, '2026-10-12 20:59:42.203', '2026-10-12 20:59:42.203', null, null, null, 'In mammals, the exchange of nutrients and metabolic products occurs in the', '["lungs","oesophagus","trachea","lymph."]', 'Exchange of nutrients and metabolic products occurs in the lymph.', '{"bold":["lymph"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('05959224-ad56-42cc-bb5c-85baa820a8d5', 'English Language', 'JAMB', null, 2007, null, 'The sea waves continue to <u>__________</u> the cliff on the west coast constantly.', null, '["impair","rub","knock","erode"]', 3, 'Correct spelling: erode.', true, '2026-10-24 07:21:42.56', '2026-10-24 07:21:42.56', null, null, null, 'The sea waves continue to <u>__________</u> the cliff on the west coast constantly.', '["impair","rub","knock","erode"]', 'Correct spelling: erode.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('05a4fa08-0944-4496-a161-a875484ff662', 'English Language', 'JAMB', null, 2007, null, 'What were the <u>__________</u> served in the restaurant', null, '["species","desserts","diets","condiments"]', 1, 'Correct spelling: desserts.', true, '2026-10-24 07:21:40.178', '2026-10-24 07:21:40.178', null, null, null, 'What were the <u>__________</u> served in the restaurant', '["species","desserts","diets","condiments"]', 'Correct spelling: desserts.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('05bc1340-8f9c-484c-8cd5-b6f3fe6dcd4f', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The noise of the fans <u>unnerved</u> the star player.', null, '["calmed","confused","refreshed","helped"]', 0, 'Unnerved = made nervous; opposite = calmed.', true, '2026-10-24 07:21:24.526', '2026-10-24 07:21:24.526', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The noise of the fans <u>unnerved</u> the star player.', '["calmed","confused","refreshed","helped"]', 'Unnerved = made nervous; opposite = calmed.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('05c0d218-e7c6-4e28-aca2-825007a9134a', 'Physics', 'JAMB', null, 1994, null, 'When 100 g of liquid L₁ at 78 °C was mixed with X g of liquid L₂ at 50 °C, the final temperature was 66 °C. Given that the specific heat capacity of L₂ is half that of L₁, find X.', null, '["50 g","100 g","150 g","200 g"]', 2, 'Heat lost = heat gained: 100 c (78 - 66) = X (c/2)(66 - 50), so 1200 = 8X and X = 150 g.', true, '2026-10-12 19:15:39.479', '2026-10-12 19:15:39.479', null, null, null, 'When 100 g of liquid L<sub>1</sub> at 78 °C was mixed with X g of liquid L<sub>2</sub> at 50 °C, the final temperature was 66 °C. Given that the specific heat capacity of L<sub>2</sub> is half that of L<sub>1</sub>, find X.', '["50 g","100 g","150 g","200 g"]', 'Heat lost = heat gained: 100 c (78 - 66) = X (c/2)(66 - 50), so 1200 = 8X and X = 150 g.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('05ce4726-6fba-4a14-8fe0-83d9af756f94', 'Literature in English', 'JAMB', null, 2026, null, 'The setting of the stage entails', null, '["a bare room with cushioned table and chair","a bare room with a small table and chair","a room with typewriter, table and two chairs","a spacious room with necessary home appliances"]', 2, 'The setting is a room with a typewriter, table, and two chairs.', true, '2026-09-12 11:10:04.739', '2026-09-12 11:10:04.739', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('05e15250-207c-40f3-b97a-8b462f04096f', 'Physics', 'JAMB', null, 2001, null, 'A cell can supply currents of 0.4 A and 0.2 A through 4.0 Ω and 10.0 Ω resistors respectively. The internal resistance of the cell is', null, '["2.0 Ω","1.0 Ω","2.5 Ω","1.5 Ω"]', 0, 'E = 0.4(4 + r) = 0.2(10 + r). So 1.6 + 0.4r = 2 + 0.2r, giving 0.2r = 0.4 and r = 2.0 Ω.', true, '2026-10-12 19:15:52.17', '2026-10-12 19:15:52.17', null, null, null, 'A cell can supply currents of 0.4 A and 0.2 A through 4.0 Ω and 10.0 Ω resistors respectively. The internal resistance of the cell is', '["2.0 Ω","1.0 Ω","2.5 Ω","1.5 Ω"]', 'E = 0.4(4 + r) = 0.2(10 + r). So 1.6 + 0.4r = 2 + 0.2r, giving 0.2r = 0.4 and r = 2.0 Ω.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('05e54140-bd12-49a8-8398-2201c2ab454b', 'English Language', 'JAMB', null, 2024, null, 'The expression ''this call'' in the passage refers to', null, '["the annulment of the election","the freest and fairest election","the political restructuring of the country","the ''stepping aside'' of the military president"]', 0, '"This call" refers to the annulment of the election.', true, '2026-09-18 10:13:05.076', '2026-10-24 17:39:09.83', '2708c14b-deb6-44cd-a86f-ce8964db149f', 2, 'COMPREHENSION', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('05ffcc65-3367-40aa-a480-0ae930b30eba', 'Chemistry', 'JAMB', null, 2026, null, 'When carbon IV oxide is bubbled through lime water, the solution becomes milky due formation of', null, '["Ca(HCO₃)₂","CaCO₃","Ca(NO₃)₂","CaCl₂","CaSO₄"]', 1, 'CaCO₃ is formed, causing the milky appearance.', true, '2026-09-12 11:36:14.103', '2026-09-12 11:36:14.103', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0618a4fb-77c9-4ac4-b7c5-25f4e9fcc741', 'Physics', 'JAMB', null, 2026, null, 'Myopia can be corrected using', null, '["suitable converging lens","suitable diverging mirror","suitable converging mirror","suitable diverging lens"]', 3, 'Myopia (short-sightedness) is corrected using a suitable diverging (concave) lens. The concave lens diverges light rays before they enter the eye, moving the focal point back onto the retina.', true, '2026-09-10 10:56:42.819', '2026-09-10 10:56:42.819', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('062097dd-63fb-4b37-a66d-3371fbbb444e', 'Biology', 'JAMB', null, 2013, null, 'The absence of anti-diuretic hormone in humans results in', null, '["Eliminating dehydration","Increasing dehydration","Decreasing dehydration","Drastic dehydration"]', 3, 'The absence of anti-diuretic hormone results in drastic dehydration.', true, '2026-10-12 20:59:47.84', '2026-10-12 20:59:47.84', null, null, null, 'The absence of anti-diuretic hormone in humans results in', '["Eliminating dehydration","Increasing dehydration","Decreasing dehydration","Drastic dehydration"]', 'The absence of anti-diuretic hormone results in drastic dehydration.', '{"bold":["drastic dehydration"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0620f9b5-dcf3-4a0a-92ab-f27ee4131e05', 'Government', 'JAMB', null, 2026, null, 'Which of the following formalized colonial penetration into Africa?', null, '["Paris Treaty","Treaty of Wesphalia","Berlin Conference","Treaty of Versaile"]', 2, 'The Berlin Conference formalized colonial penetration into Africa.', true, '2026-09-12 11:24:58.846', '2026-09-12 11:24:58.846', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('06211f19-64d7-4428-92d2-32dad9b6c172', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The Federal Government approved a new salary structure as <u>an incentive</u> for the Nigerian workers.', null, '["a reward","an encouragement","a package","an advance"]', 1, 'Incentive = an encouragement.', true, '2026-10-24 01:04:01.781', '2026-10-24 01:04:01.781', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The Federal Government approved a new salary structure as <u>an incentive</u> for the Nigerian workers.', '["a reward","<u>an encouragement</u>","a package","an advance"]', '<b>Incentive</b> = <b>an encouragement</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('06253f38-5613-4a86-aa8f-a3084dec2864', 'Biology', 'JAMB', null, 2026, null, 'Which of the following requires the use of carbon dating to prove that evolution has occurred?', null, '["biochemical similarities","molecular records","comparative anatomy","fossil records"]', 3, 'Fossil records require the use of carbon dating to prove that evolution has occurred. Carbon dating determines the age of fossils and geological samples, allowing scientists to establish a chronological sequence of evolutionary changes. Biochemical similarities, molecular records, and comparative anatomy provide evidence for evolution but do not require dating. Fossil dating is essential for understanding the timeline of evolution.', true, '2026-09-09 03:19:26.739', '2026-09-09 03:19:26.739', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('063ca46a-2612-4301-9131-92501a49e379', 'Government', 'JAMB', null, 2026, null, 'What distinguishes a political party from other social institutions is the desire to', null, '["win elections and form a government","influence government policies in certain directions","promote the interest of party members","influence the international community on local issues"]', 0, 'What distinguishes a political party from other social institutions is the desire to win elections and form a government. This is the unique characteristic of political parties. While pressure groups seek to influence government policies, they do not seek to form government themselves. Political parties contest elections with the specific aim of winning power and governing. This distinguishes them from other organizations.', true, '2026-09-10 10:44:17.654', '2026-09-10 10:44:17.654', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('063cb100-6dbf-4ffd-a8cc-0ee3f1514994', 'English Language', 'JAMB', null, 2024, null, 'Tayo could have supplied the goods but it was ______ into two', null, '["splitted","splits","split","splitting"]', 2, '"Split" is the correct past participle.', true, '2026-09-18 09:43:02.816', '2026-09-18 09:43:02.816', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('063df9fd-cba7-4ba0-b9a7-99fdf1d61ae7', 'English Language', 'JAMB', null, 2024, null, 'Why did the school transfer Mr. Ayesoro to Stardom Hub?', null, '["to punish him for misconduct","to provide him with a better job opportunity","to reward him for his dedication","to retain Mrs Ladele''s children in the school"]', 3, 'Mr. Ayesoro was transferred to Stardom Hub specifically to retain Mrs. Ladele''s children in the school.', true, '2026-09-18 09:23:08.228', '2026-09-18 09:23:08.228', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('06495fa1-3eca-4dbc-bdda-ab7944802c18', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The lawmaker <u>heckled</u> the chairman during their last meeting.', null, '["cheered up","applauded","shouted down","restrained"]', 2, 'Heckled = shouted down.', true, '2026-10-24 01:04:11.545', '2026-10-24 01:04:11.545', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The lawmaker <u>heckled</u> the chairman during their last meeting.', '["cheered up","applauded","<u>shouted down</u>","restrained"]', '<b>Heckled</b> = <b>shouted down</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('064e346a-b095-4496-b0c8-1ea0a391a2a7', 'Biology', 'JAMB', null, 2002, null, 'In his theory of evolution, Darwin implied that', null, '["the struggle for existence among living organisms is sporadic","the most successful organisms are those that best adapt to their environment","organs of the body which are not regularly used by an organism will disappear","any traits acquired by an organism during its lifetime can be passed on to its offspring"]', 1, 'Darwin proposed that the most successful organisms best adapt to their environment.', true, '2026-10-12 20:59:30.804', '2026-10-12 20:59:30.804', null, null, null, 'In his theory of evolution, Darwin implied that', '["the struggle for existence among living organisms is sporadic","the most successful organisms are those that best adapt to their environment","organs of the body which are not regularly used by an organism will disappear","any traits acquired by an organism during its lifetime can be passed on to its offspring"]', 'Darwin proposed that the most successful organisms best adapt to their environment.', '{"bold":["the most successful organisms best adapt to their environment"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('064f6786-ced6-4277-8ded-ebda085164b2', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The greatness of the creator of the universe is always <u>inexpressible</u> to many adherents.', null, '["ineffable","unbearable","wonderful","inevitable"]', 0, 'Inexpressible = ineffable.', true, '2026-10-24 01:04:06.06', '2026-10-24 01:04:06.06', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The greatness of the creator of the universe is always <u>inexpressible</u> to many adherents.', '["<u>ineffable</u>","unbearable","wonderful","inevitable"]', '<b>Inexpressible</b> = <b>ineffable</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0667629b-b756-4570-a1d5-9be04b2581c0', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The task was <u>Herculean</u>.', null, '["irregular","related to Hercules","stimulating","demanding"]', 3, 'Herculean = demanding.', true, '2026-10-24 01:03:54.783', '2026-10-24 01:03:54.783', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The task was <u>Herculean</u>.', '["irregular","related to Hercules","stimulating","<u>demanding</u>"]', '<b>Herculean</b> = <b>demanding</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('066b758b-e4d1-434d-b740-084b5247a0f0', 'General Mathematics', 'JAMB', null, 2026, null, 'If f(x-2) = 3x² + 4x + 1, find f(1)', null, '["8","40","7","32","21"]', 0, 'To find f(1), set x - 2 = 1, so x = 3. Then f(1) = 3(3)² + 4(3) + 1 = 3(9) + 12 + 1 = 27 + 12 + 1 = 40. Wait, let me recalculate: 27 + 12 + 1 = 40. The answer is 40. But option (B) is 40. Let me check: f(1) = 3(3)² + 4(3) + 1 = 27 + 12 + 1 = 40. So the answer is (B) 40.', true, '2026-09-10 10:48:18.601', '2026-09-10 10:48:18.601', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('066cd703-7cbf-4665-ad77-c31c6d9c443c', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). The manager often quarrels with his staff because he goes around with <u>a chip on his shoulder</u>.', null, '["deformed shoulder","readiness to be angered","look of contempt","an air of superiority","search for gossip"]', 1, '''A chip on one''s shoulder'' = readiness to take offence.', true, '2026-10-24 01:02:01.951', '2026-10-24 01:02:01.951', null, null, null, '(Choose the most appropriate interpretation). The manager often quarrels with his staff because he goes around with <u>a chip on his shoulder</u>.', '["deformed shoulder","<u>readiness to be angered</u>","look of contempt","an air of superiority","search for gossip"]', '''A <b>chip on one''s shoulder</b>'' = <b>readiness to take offence</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('066e1589-f73f-475d-8861-0c29976d9c3b', 'Chemistry', 'JAMB', null, 2026, null, 'Which salt will turn blue litmus red?', null, '["NaCl","NH₄Cl","Na₂CO₃","KNO₃"]', 1, 'NH₄Cl is acidic and will turn blue litmus red.', true, '2026-09-12 11:32:55.589', '2026-09-12 11:32:55.589', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0689d70a-ee05-4ca2-8b93-7e0efe92345b', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). Many of the workers hired for firing the furnace <u>had themselves fired</u> as a result of the unfortunate accident.', null, '["got themselves burned accidentally","jumped into the fire themselves","got themselves sacked from their jobs","were sacked from their"]', 2, '''Fired'' here = sacked.', true, '2026-10-24 01:04:16.804', '2026-10-24 01:04:16.804', null, null, null, '(Choose the most appropriate interpretation). Many of the workers hired for firing the furnace <u>had themselves fired</u> as a result of the unfortunate accident.', '["got themselves burned accidentally","jumped into the fire themselves","<u>got themselves sacked from their jobs</u>","were sacked from their"]', '''<b>Fired</b>'' here = <b>sacked</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('068aee48-4b84-46e3-8c76-439f98ad94bc', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). He <u>took exception</u> to Ezenwa''s remark.', null, '["was delighted at","was excited by","got demoralized by","objected to","was perplexed by"]', 3, '''Take exception to'' = object to.', true, '2026-10-24 01:02:02.004', '2026-10-24 01:02:02.004', null, null, null, '(Choose the most appropriate interpretation). He <u>took exception</u> to Ezenwa''s remark.', '["was delighted at","was excited by","got demoralized by","<u>objected to</u>","was perplexed by"]', '''<b>Take exception to</b>'' = <b>object to</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('068b6111-f6c0-4eea-9ace-49e7038818f6', 'Biology', 'JAMB', null, 2026, null, 'The mode of nutrition of sundew and bladderwort can be described as', null, '["Saprophytic","Holozoic","Chemosynthetic","Autotrophic"]', 1, 'The mode of nutrition of sundew and bladderwort is holozoic (carnivorous/insectivorous). These plants capture and digest insects to obtain nitrogen and other nutrients from their prey. However, they also perform photosynthesis, so they are both autotrophic and heterotrophic. The description emphasizes their carnivorous (insectivorous) nature. Saprophytic nutrition involves feeding on dead organic matter. Chemosynthetic nutrition uses energy from chemical reactions. Autotrophic nutrition would not fully describe these plants because they supplement their nutrition through insect capture.', true, '2026-09-09 03:19:04.243', '2026-09-09 03:19:04.243', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('06975209-7910-4263-821d-30ea4a98b010', 'Chemistry', 'JAMB', null, 2026, null, 'The salt form when a weak acid and a strong base hydrolyze in water is?', null, '["A saturated solution","An acidic solution","A buffer solution","An alkaline solution"]', 3, 'A weak acid and strong base form an alkaline solution.', true, '2026-09-12 11:36:27.293', '2026-09-12 11:36:27.293', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('06b0d663-9efb-48d1-883e-8bbdccc4ad41', 'Literature in English', 'JAMB', null, 2026, null, 'Which imagery is present in: ''Her voice was a soft lullaby in the dark night''?', null, '["Auditory imagery","Visual imagery","Tactile imagery","Organic imagery"]', 0, 'Auditory imagery is present.', true, '2026-09-12 11:14:18.144', '2026-09-12 11:14:18.144', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('06b665ab-1af5-47e1-9a2c-d62f9a13bf99', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The manager''s knowledge of the strike is of the <u>utmost</u> importance.', null, '["basic","genuine","standard","paramount"]', 3, 'Utmost = paramount.', true, '2026-10-24 01:04:05.579', '2026-10-24 01:04:05.579', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The manager''s knowledge of the strike is of the <u>utmost</u> importance.', '["basic","genuine","standard","<u>paramount</u>"]', '<b>Utmost</b> = <b>paramount</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('06c458f0-7515-4d83-8e7b-eddc3ebff686', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Joseph was sold to the Ishmaelites for ___ shekels of silver', null, '["forty","thirty-five","thirty","twenty-five","twenty"]', 4, 'Joseph was sold to the Ishmaelites for twenty shekels of silver. His brothers sold him for twenty pieces of silver, and the Ishmaelites took him to Egypt.', true, '2026-09-12 09:45:58.606', '2026-09-12 09:45:58.606', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('06c51ae6-4348-4718-946e-f6b4fb7880cd', 'Physics', 'JAMB', null, 2026, null, 'A neutral charged body is brought near a gold leaf electroscope and the leaf is observed to diverge. What would one assume the charge of the electroscope to be?', null, '["Positive","negative","Neutral","None"]', 0, 'If a neutral body is brought near a charged electroscope and the leaf diverges more, the electroscope must be positively charged. The neutral body is attracted to the positive charge, causing charge redistribution that increases leaf divergence. Wait, a neutral body would cause induction, not increased divergence. The answer is likely positive based on the document.', true, '2026-09-10 10:56:45.091', '2026-09-10 10:56:45.091', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('06de7f29-63fc-43eb-8769-b9f36b111014', 'Physics', 'JAMB', null, 2001, null, 'The primary coil of a transformer has N turns and is connected to a 120 V a.c. power line. If the secondary coil has 1,000 turns and a terminal voltage of 1,200 volts, what is the value of N?', null, '["120","100","1,000","1,200"]', 1, 'N/1000 = 120/1200, so N = 100.', true, '2026-10-12 19:15:52.333', '2026-10-12 19:15:52.333', null, null, null, 'The primary coil of a transformer has N turns and is connected to a 120 V a.c. power line. If the secondary coil has 1,000 turns and a terminal voltage of 1,200 volts, what is the value of N?', '["120","100","1,000","1,200"]', 'N/1000 = 120/1200, so N = 100.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('06f45336-6ebb-4062-8158-795459d25e87', 'English Language', 'JAMB', null, 2024, null, '4', null, '["level","standard","class","wishes"]', 1, '"Standard of living" is the fixed expression.', true, '2026-09-18 10:17:48.773', '2026-09-18 10:17:48.773', '274e150d-fca1-4c72-9c33-e5e119534874', 4, 'CLOZE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('070bcedc-46e7-4ad8-86e3-200a4762bafa', 'English Language', 'JAMB', null, 2007, null, 'The accused is optimistic of regaining his freedom because there is no witness to <u>__________</u> his story', null, '["correct","challenge","corroborate","contradicts"]', 2, 'Correct spelling: corroborate.', true, '2026-10-24 07:21:44.468', '2026-10-24 07:21:44.468', null, null, null, 'The accused is optimistic of regaining his freedom because there is no witness to <u>__________</u> his story', '["correct","challenge","corroborate","contradicts"]', 'Correct spelling: corroborate.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('071541d4-8f76-4b4c-aa4a-7e69b9e46aef', 'Chemistry', 'JAMB', null, 2026, null, 'Increasing the temperature generally', null, '["decreases the solubility of a solid in a liquid but increases the solubility of a gas in a liquid","increases the solubility of a solid in a liquid but decreases the solubility of a gas in a liquid","increases the solubility of both a solid and a gas in a liquid","decreases the solubility of both a solid and a gas in a liquid"]', 1, 'Heating enhances the dissolution of most solid solutes in liquids while driving dissolved gas molecules out of solution.', true, '2026-09-09 17:12:47.601', '2026-09-09 17:12:47.601', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0727467a-a24d-41e8-ad8c-ef93096405df', 'Biology', 'JAMB', null, 2026, null, 'Which organism is typically found at the base of a food chain? I. Carnivore II. Herbivore III. Producer IV. Omnivore', null, '["I & II","II & III","III & IV","I"]', 1, 'Producers (III) and herbivores (II) are typically found at the base of food chains. Producers (plants, algae) form the first trophic level as they convert solar energy into chemical energy through photosynthesis. Herbivores (primary consumers) are the second trophic level as they eat producers. Carnivores (I) and omnivores (IV) are higher trophic levels (secondary, tertiary consumers) that feed on other animals. Every food chain must begin with a producer as the ultimate source of energy for all other organisms in the ecosystem.', true, '2026-09-09 03:18:36.344', '2026-09-09 03:18:36.344', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0727e30a-f308-42f6-aa59-8797c4c80f68', 'Physics', 'JAMB', null, 1988, null, 'A force of 10 N drags a mass of 10 kg on a horizontal table with an acceleration of 0.2 m s⁻². If the acceleration due to gravity is 10 m s⁻², the coefficient of friction between the moving mass and the table is', null, '["0.02","0.08","0.20","0.80"]', 1, 'F - f = ma gives f = 10 - 10 x 0.2 = 8 N. μ = f/(mg) = 8/100 = 0.08.', true, '2026-10-12 19:15:27.212', '2026-10-12 19:15:27.212', null, null, null, 'A force of 10 N drags a mass of 10 kg on a horizontal table with an acceleration of 0.2 m s<sup>-2</sup>. If the acceleration due to gravity is 10 m s<sup>-2</sup>, the coefficient of friction between the moving mass and the table is', '["0.02","0.08","0.20","0.80"]', 'F - f = ma gives f = 10 - 10 x 0.2 = 8 N. μ = f/(mg) = 8/100 = 0.08.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('072f4804-ebd9-4292-a1db-e52770f83951', 'Literature in English', 'JAMB', null, 2026, null, 'Define Caesura with the necessary key terms', null, '["A pause or break in a line of poetry, usually near the middle","A type of rhyme scheme","A figure of speech","A stanza form"]', 0, 'Caesura is a pause or break in a line of poetry, usually near the middle. It is a rhythmic break that can occur naturally at a punctuation mark or syntactically. Key terms: pause, break, midline, rhythm. It affects the flow and meaning of the verse. It is not a rhyme scheme, figure of speech, or stanza form.', true, '2026-09-10 10:47:55.247', '2026-09-10 10:47:55.247', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0739e626-eaa8-4cd8-841c-63ec31aa8bcd', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). The politician <u>played to the gallery</u> to win the election.', null, '["obeyed the people","sang a good song for the people","went to the gallery","went out of his way to appeal to the taste of the people"]', 3, '''Play to the gallery'' = appeal to popular taste.', true, '2026-10-24 01:04:19.647', '2026-10-24 01:04:19.647', null, null, null, '(Choose the most appropriate interpretation). The politician <u>played to the gallery</u> to win the election.', '["obeyed the people","sang a good song for the people","went to the gallery","<u>went out of his way to appeal to the taste of the people</u>"]', '''<b>Play to the gallery</b>'' = <b>appeal to popular taste</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('073b59e2-f1a7-4f88-a588-9deb314c1f78', 'Literature in English', 'JAMB', null, 2026, null, '''Faithful fellows fear falsehood'' shows', null, '["repetition","metaphor","simile","alliteration"]', 3, 'It shows alliteration.', true, '2026-09-12 11:14:03.413', '2026-09-12 11:14:03.413', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('07481fc2-782f-4722-bd89-1234e2bceca9', 'Literature in English', 'JAMB', null, 2026, null, '______ is the arrangement of stressed and unstressed syllables in a line of poem', null, '["rhythm","rhetorical arrangement","meter","ballad"]', 2, 'Meter is the arrangement of stressed and unstressed syllables.', true, '2026-09-12 11:12:10.848', '2026-09-12 11:12:10.848', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('07517ba9-5034-4518-a278-57de00e329ac', 'Government', 'JAMB', null, 2026, null, 'Which of the following is NOT a feature of a state?', null, '["Population","Clearly defined territory","Culture","Government"]', 2, 'Culture is not a feature of a state; population, territory, government, and sovereignty are.', true, '2026-09-12 11:24:18.149', '2026-09-12 11:24:18.149', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0757e327-babd-4560-87c8-690873e5f71a', 'Biology', 'JAMB', null, 2003, null, 'The experiment is used to demonstrate that', null, '["plants lose water through guttation","transpiration occurs through the leaves","water is necessary for photosynthesis","leaves are important to photosynthesis"]', 1, 'The experiment demonstrates transpiration through leaves.', true, '2026-10-12 20:59:32.674', '2026-10-12 20:59:32.674', null, null, null, 'The experiment is used to demonstrate that', '["plants lose water through guttation","transpiration occurs through the leaves","water is necessary for photosynthesis","leaves are important to photosynthesis"]', 'The experiment demonstrates transpiration through leaves.', '{"bold":["transpiration through leaves"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('076455b4-c33f-48be-9ea5-94c32d8ebd09', 'Government', 'JAMB', null, 2026, null, 'A country''s foreign policy is foremost driven by', null, '["Economy","Location","natural resources","national interest"]', 3, 'National interest is the foremost driver of a country''s foreign policy.', true, '2026-09-12 11:23:57.461', '2026-09-12 11:23:57.461', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('076d9e3d-9ead-4155-9dcd-d979021c3a0f', 'English Language', 'JAMB', null, 2007, null, 'The police came early enough to <u>__________</u> the bomb planted by the rioters.', null, '["diffuse","insulate","detonate","defuse"]', 3, 'Correct spelling: defuse.', true, '2026-10-24 07:21:38.287', '2026-10-24 07:21:38.287', null, null, null, 'The police came early enough to <u>__________</u> the bomb planted by the rioters.', '["diffuse","insulate","detonate","defuse"]', 'Correct spelling: defuse.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('07729c37-36e2-4a2e-b7d7-f68dc41f05d2', 'Biology', 'JAMB', null, 2013, null, 'The male reproductive organ of a flower is the', null, '["Petal","Sepal","Carpel","Stamen"]', 3, 'The stamen is the male reproductive organ of a flower.', true, '2026-10-12 20:59:47.637', '2026-10-12 20:59:47.637', null, null, null, 'The male reproductive organ of a flower is the', '["Petal","Sepal","Carpel","Stamen"]', 'The stamen is the male reproductive organ of a flower.', '{"bold":["stamen"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('077c6e31-bb71-4334-a07b-3ab511f65ea0', 'General Mathematics', 'JAMB', null, 2026, null, 'A bag contains 4 white balls and 6 red balls. Two balls are taken without replacement. What is the probability that they are both red?', null, '["1/3","2/9","2/15","3/5"]', 0, 'P(RR) = (6/10)(5/9) = 30/90 = 1/3.', true, '2026-09-12 11:44:19.103', '2026-09-12 11:44:19.103', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('07839152-c1df-4c35-889b-2fdd1de9e2a9', 'Biology', 'JAMB', null, 2026, null, 'In the theory of evolution, Darwin implied that', null, '["the struggle for existence among living organisms are those that best adapt to the environment","the most successful organisms are those that best adapt to their environment","organs of the body which are not regularly used by an organism will disappear","traits acquired by an organism during its lifetime can be passed on to its offspring"]', 1, 'Darwin implied that the most successful organisms are those that best adapt to their environment. This is the principle of natural selection. Organisms with favorable variations are more likely to survive and reproduce, passing on their advantageous traits. The struggle for existence (I) is part of Darwin''s theory but not the main idea. Use and disuse (III and IV) are Lamarckian concepts.', true, '2026-09-09 03:19:28.076', '2026-09-09 03:19:28.076', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0790bcd3-64ac-4b9d-a8ed-e3f7c9033044', 'Literature in English', 'JAMB', null, 2026, null, 'A poem of 4 lines is called', null, '["Sestet","Couplet","Sonnet","Quatrain"]', 3, 'A poem of 4 lines is called a quatrain. A quatrain is a stanza or poem consisting of four lines. It is one of the most common stanza forms in poetry. A couplet is two lines, a sestet is six lines, and a sonnet is fourteen lines. Quatrains can have various rhyme schemes such as AABB, ABAB, or ABBA.', true, '2026-09-10 10:45:33.591', '2026-09-10 10:45:33.591', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('07a1c1e4-cfdd-4ee3-a071-2a1983da2f10', 'Government', 'JAMB', null, 2026, null, 'A league of sovereign nation with a weak central is', null, '["unitary","state","federal","confederal"]', 3, 'A league of sovereign nations with a weak central is a confederation.', true, '2026-09-12 11:24:53.573', '2026-09-12 11:24:53.573', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('07a70202-da57-431a-90c6-247b7266e418', 'English Language', 'JAMB', null, 2007, null, 'The judge with his son <u>-------------</u> travelling to Lagos now.', null, '["were","was","is","are"]', 2, 'Singular ''judge'' present â†’ is.', true, '2026-10-24 01:02:14.618', '2026-10-24 01:02:14.618', null, null, null, 'The judge with his son <u>-------------</u> travelling to Lagos now.', '["were","was","<u>is</u>","are"]', 'Singular ''<b>judge</b>'' present â†’ <b>is</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('07ae423b-2791-4fd1-9f16-13c4209638e4', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. It is <u>inconceivable</u> that the rat devoured the cat.', null, '["contestable","credible","incomprehensible","unimaginable"]', 1, 'Inconceivable = unbelievable; opposite = credible.', true, '2026-10-24 07:21:22.557', '2026-10-24 07:21:22.557', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. It is <u>inconceivable</u> that the rat devoured the cat.', '["contestable","credible","incomprehensible","unimaginable"]', 'Inconceivable = unbelievable; opposite = credible.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('07b657c9-a0fe-4b93-9968-e3441406203b', 'English Language', 'JAMB', null, 2024, null, 'A large percentage of the harvested crops ______ been destroyed by the pests.', null, '["Have","Has","Is","Are"]', 0, '"A large percentage" takes a singular verb, so "has" is correct.', true, '2026-09-18 09:43:02.415', '2026-10-24 17:19:03.015', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('07cac8c8-649d-4387-a620-f1e679ab203e', 'Physics', 'JAMB', null, 2026, null, 'When a charged ebonite rod is brought near a charged glass rod, there will be', null, '["Attraction","repulsion","spark","no force experienced"]', 0, 'When a charged ebonite rod (negatively charged) is brought near a charged glass rod (positively charged), there will be attraction. Unlike charges attract each other. Ebonite rubbed with fur becomes negatively charged, while glass rubbed with silk becomes positively charged.', true, '2026-09-10 10:56:38.65', '2026-09-10 10:56:38.65', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('07da9dfb-d2cc-403c-9e2e-6ee065518345', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. <u>A conservative</u> estimate put the number of missing persons at forty', null, '["A rough","An accurate","A primitive","An incorrect"]', 1, 'Conservative = cautious/low; opposite = accurate.', true, '2026-10-24 07:21:24.425', '2026-10-24 07:21:24.425', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. <u>A conservative</u> estimate put the number of missing persons at forty', '["A rough","An accurate","A primitive","An incorrect"]', 'Conservative = cautious/low; opposite = accurate.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('07dcbc4b-10dc-4b03-87da-55c34209b393', 'Physics', 'JAMB', null, 2026, null, 'An object of 10kg is released into the air 50m high. Calculate the ratio between its potential energy at max height and kinetic energy before it hits the ground.', null, '["1:2","2:1","0:1","1:0","1:1"]', 4, 'By conservation of energy, potential energy at max height equals kinetic energy just before hitting the ground. So the ratio is 1:1.', true, '2026-09-10 10:56:44.549', '2026-09-10 10:56:44.549', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('07debb3b-fada-49c6-b20c-1e9889290512', 'Physics', 'JAMB', null, 1990, null, 'A body of mass 10 kg rests on a rough inclined plane whose angle of tilt θ is variable. θ is gradually increased until the body starts to slide down the plane at 30°. The coefficient of limiting friction between the body and the plane is', null, '["0.30","0.50","0.58","0.87."]', 2, 'At the point of sliding, μ = tan θ = tan 30° = 0.58.', true, '2026-10-12 19:15:30.601', '2026-10-12 19:15:30.601', null, null, null, 'A body of mass 10 kg rests on a rough inclined plane whose angle of tilt θ is variable. θ is gradually increased until the body starts to slide down the plane at 30°. The coefficient of limiting friction between the body and the plane is', '["0.30","0.50","0.58","0.87."]', 'At the point of sliding, μ = tan θ = tan 30° = 0.58.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('07e20f86-be08-4b5c-b64c-aa37c0a592ad', 'Government', 'JAMB', null, 2026, null, 'The 1960 Independence Constitution of Nigeria provided for the', null, '["Queen as head of State","Governor-General as head of state","Governor-General as head of government","President as head of government"]', 0, 'The 1960 Independence Constitution of Nigeria provided for the Queen as head of State. Nigeria became independent on October 1, 1960, as a constitutional monarchy with the Queen of England as head of state, represented in Nigeria by a Governor-General. The Prime Minister was the head of government. This arrangement changed in 1963 when Nigeria became a republic with a President as head of state.', true, '2026-09-10 10:44:19.199', '2026-09-10 10:44:19.199', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('07eaac6c-5f9e-4f4b-99f2-62b94f23ff78', 'Economics', 'JAMB', null, 2026, null, 'Scarcity in economics means: (i) a period of scarce things (ii) when things are costly to acquire (iii) monopolisation of available resources by a few (iv) nationalisation of natural resources such as petroleum in Venezuela (v) none of the above', null, '["I only","ii only","I, ii and iii only","V only"]', 3, 'Scarcity in economics means none of the above (v). Scarcity is the fundamental economic problem of limited resources relative to unlimited wants. It is not about a period of scarcity, costly acquisition, or monopolization. Scarcity necessitates choice and the allocation of resources.', true, '2026-09-10 10:41:20.563', '2026-09-10 10:41:20.563', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('07ed77ca-92ee-48f7-b33c-0aa878285be2', 'Chemistry', 'JAMB', null, 2026, null, 'Which of the following is the correct order of increasing reactivity of halogens?', null, '["I₂ < Br₂ < Cl₂ < F₂","F₂ < Cl₂ < Br₂ < I₂","Cl₂ < Br₂ < I₂ < F₂","Br₂ < I₂ < Cl₂ < F₂"]', 0, 'Halogen reactivity decreases down Group 17 as atomic radius increases, making fluorine the most reactive and iodine the least.', true, '2026-09-09 17:12:49.417', '2026-09-09 17:12:49.417', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('07f7fc81-ad23-426c-a743-ba6f3442b82e', 'Biology', 'JAMB', null, 2026, null, 'Thyroxine and adrenalin are hormones that control', null, '["Blood grouping","Tongue rolling","Behavioural patterns","Colour variation"]', 2, 'Thyroxine and adrenalin are hormones that control behavioural patterns. Thyroxine (produced by the thyroid gland) regulates metabolic rate, growth, and development, and affects behavior and activity levels. Adrenalin (produced by the adrenal medulla) is involved in the ''fight or flight'' response, causing increased heart rate, alertness, and changes in behavior. Blood grouping is determined by antigens on red blood cells (genetic). Tongue rolling is a genetic trait. Colour variation is determined by pigmentation genes.', true, '2026-09-09 03:18:58.324', '2026-09-09 03:18:58.324', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('07f9adc3-696e-4695-9f59-3c01ea9cde75', 'English Language', 'JAMB', null, 2007, null, 'He boasts so much about his high scores and he <u>__________</u> at the efforts of others', null, '["scorns","sneers","grins","smiles"]', 1, 'Correct spelling: sneers.', true, '2026-10-24 07:21:45.172', '2026-10-24 07:21:45.172', null, null, null, 'He boasts so much about his high scores and he <u>__________</u> at the efforts of others', '["scorns","sneers","grins","smiles"]', 'Correct spelling: sneers.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0803237c-d5b4-4f3d-ab95-014e5194da2e', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Ogedegbe was <u>an intrepid</u> fighter for human freedom and dignity.', null, '["timid","half-hearted","fearless","undaunted"]', 0, 'Intrepid = fearless; opposite = timid.', true, '2026-10-24 07:21:13.819', '2026-10-24 07:21:13.819', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Ogedegbe was <u>an intrepid</u> fighter for human freedom and dignity.', '["timid","half-hearted","fearless","undaunted"]', 'Intrepid = fearless; opposite = timid.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0805803b-4364-406b-a87a-ca312949e4e7', 'Physics', 'JAMB', null, 1997, null, 'What happens when a certain quantity of pure ice is completely changed to water at 0 °C?', null, '["Latent heat is absorbed, the mass remains constant and the volume decreases.","Latent heat is given out, the mass remains constant and the volume decreases.","Latent heat is given out, the mass increases and the volume remains constant.","Latent heat is absorbed, the mass decreases and the volume increases."]', 0, 'Melting needs latent heat, mass is conserved, and ice contracts on melting, so the volume decreases.', true, '2026-10-12 19:15:43.636', '2026-10-12 19:15:43.636', null, null, null, 'What happens when a certain quantity of pure ice is completely changed to water at 0 °C?', '["Latent heat is absorbed, the mass remains constant and the volume decreases.","Latent heat is given out, the mass remains constant and the volume decreases.","Latent heat is given out, the mass increases and the volume remains constant.","Latent heat is absorbed, the mass decreases and the volume increases."]', 'Melting needs latent heat, mass is conserved, and ice contracts on melting, so the volume decreases.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0806c153-0789-4fda-be4e-9c07bf23bfe9', 'Physics', 'JAMB', null, 1987, null, 'An elevator of mass 4800 kg is supported by a cable which can safely withstand a maximum tension of 60 000 N. The maximum upward acceleration the elevator can have is (g = 10 m s⁻²)', null, '["2.5 m s⁻²","5.0 m s⁻²","7.5 m s⁻²","10.0 m s⁻²"]', 0, 'T - mg = ma, so a = (60 000 - 48 000)/4800 = 2.5 m s⁻².', true, '2026-10-12 19:15:24.759', '2026-10-12 19:15:24.759', null, null, null, 'An elevator of mass 4800 kg is supported by a cable which can safely withstand a maximum tension of 60 000 N. The maximum upward acceleration the elevator can have is (g = 10 m s<sup>-2</sup>)', '["2.5 m s<sup>-2</sup>","5.0 m s<sup>-2</sup>","7.5 m s<sup>-2</sup>","10.0 m s<sup>-2</sup>"]', 'T - mg = ma, so a = (60 000 - 48 000)/4800 = 2.5 m s<sup>-2</sup>.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0810c657-414f-49e3-8560-9fe749449206', 'Physics', 'JAMB', null, 2001, null, 'What is the angle of dip at the magnetic equator?', null, '["45°","0°","90°","180°"]', 1, 'At the magnetic equator the earth''s field is horizontal, so the dip is 0°.', true, '2026-10-12 19:15:52.117', '2026-10-12 19:15:52.117', null, null, null, 'What is the angle of dip at the magnetic equator?', '["45°","0°","90°","180°"]', 'At the magnetic equator the earth''s field is horizontal, so the dip is 0°.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('08184f73-a04b-491d-a70b-66981a9ef6a3', 'Biology', 'JAMB', null, 0, null, 'The structure that holds the yolk in position is labelled:', 'https://res.cloudinary.com/kwi1uv0g/image/upload/v1791839002/questions/oalwoej0a4dlu8nsbpwv.jpg', '["i","ii","iii","iv"]', 0, 'Part III represents the chalaza, the twisted strand that anchors the yolk in the center of the egg.', true, '2026-10-12 21:05:16.176', '2026-10-12 21:05:16.176', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('08245fd8-4c91-4f29-9859-35d5cc235a38', 'Physics', 'JAMB', null, 1989, null, 'Two points on a velocity-time graph have co-ordinates (5 s, 10 m s⁻¹) and (20 s, 20 m s⁻¹). Calculate the mean acceleration between the two points.', null, '["0.67 m s⁻²","0.83 m s⁻²","1.50 m s⁻²","2.00 m s⁻²"]', 0, 'a = Δv/Δt = (20 - 10)/(20 - 5) = 10/15 = 0.67 m s⁻².', true, '2026-10-12 19:15:28.765', '2026-10-12 19:15:28.765', null, null, null, 'Two points on a velocity-time graph have co-ordinates (5 s, 10 m s<sup>-1</sup>) and (20 s, 20 m s<sup>-1</sup>). Calculate the mean acceleration between the two points.', '["0.67 m s<sup>-2</sup>","0.83 m s<sup>-2</sup>","1.50 m s<sup>-2</sup>","2.00 m s<sup>-2</sup>"]', 'a = Δv/Δt = (20 - 10)/(20 - 5) = 10/15 = 0.67 m s<sup>-2</sup>.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('082477e4-6aa3-4587-8643-f57931d5ad1e', 'Yoruba', 'JAMB', null, 2007, null, 'Ìwé Àyírí Amòòkùnjalè Tú ní ìbéèrè 32 -34 dá lé. Òrë Orínmóògùnjë ti ó p bá a ra kòkó ni', null, '["Àlàó","Òmòtóýõõ","Ilésanmí","Ajíýefínní."]', 3, 'Ajíýefínní ni òrë Orínmóògùnjë ti ó p bá a ra kòkó.', true, '2026-10-13 13:23:32.122', '2026-10-13 13:23:32.122', null, null, null, 'Ìwé Àyírí Amòòkùnjalè Tú ní ìbéèrè 32 -34 dá lé. Òrë Orínmóògùnjë ti ó p bá a ra kòkó ni', '["Àlàó","Òmòtóýõõ","Ilésanmí","Ajíýefínní."]', 'Ajíýefínní ni òrë Orínmóògùnjë ti ó p bá a ra kòkó.', '{"bold":["Ajíýefínní"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('082e258c-fd30-4525-9d89-bf41894badcd', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). The preacher has <u>made good his promise</u> to visit some of his converts today.', null, '["fulfilled","abided by","seen to","accepted"]', 0, '''Made good'' = fulfilled.', true, '2026-10-24 01:04:16.59', '2026-10-24 01:04:16.59', null, null, null, '(Choose the most appropriate interpretation). The preacher has <u>made good his promise</u> to visit some of his converts today.', '["<u>fulfilled</u>","abided by","seen to","accepted"]', '''<b>Made good</b>'' = <b>fulfilled</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('084c92c9-07f4-4be1-aa6c-00e5cc407efe', 'English Language', 'JAMB', null, 2024, null, 'Identify the option that contains /j/', null, '["jest","value","haste","flew"]', 1, '"Value" contains the /j/ sound.', true, '2026-09-18 09:43:02.677', '2026-09-18 09:43:02.677', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('084ce50d-d58e-496a-aae1-a854635c5cd6', 'Physics', 'JAMB', null, 2026, null, 'Calculate the apparent weight difference of a man weighing 70kg in an elevator moving upwards with an acceleration of 1.5m/s²', null, '["685N","595N","581N","105N","805N"]', 3, 'Apparent weight = m(g+a) = 70(10+1.5) = 70 × 11.5 = 805N. Actual weight = 70 × 10 = 700N. Difference = 805 - 700 = 105N.', true, '2026-09-10 10:56:45.306', '2026-09-10 10:56:45.306', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('08513dce-a674-45ec-938a-dad9089ffa33', 'Physics', 'JAMB', null, 1992, null, 'A body starts from rest and moves with uniform acceleration of 6 m s⁻². What distance does it cover in the third second?', null, '["15 m","18 m","27 m","30 m"]', 0, 'Distance in the 3rd second = ½a(3² - 2²) = ½ x 6 x 5 = 15 m.', true, '2026-10-12 19:15:34.909', '2026-10-12 19:15:34.909', null, null, null, 'A body starts from rest and moves with uniform acceleration of 6 m s<sup>-2</sup>. What distance does it cover in the third second?', '["15 m","18 m","27 m","30 m"]', 'Distance in the 3rd second = ½a(3<sup>2</sup> - 2<sup>2</sup>) = ½ x 6 x 5 = 15 m.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('08552560-17b2-43da-8a4f-c690272e8dda', 'Chemistry', 'JAMB', null, 2026, null, 'Which compound shows both ionic and covalent bonding?', null, '["NaCl","NH₃","NH₄Cl","CO₂"]', 2, 'NH₄Cl contains both ionic bonds (between NH₄⁺ and Cl⁻) and covalent bonds (within NH₄⁺).', true, '2026-09-12 11:32:54.048', '2026-09-12 11:32:54.048', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0857b87a-3c30-4dfc-b70d-abdfc9c78a02', 'Yoruba', 'JAMB', null, 2007, null, 'Nínú Gbágùúdá, oúnjç wo ni ‘baálé’ ohun tí à p fêgê jẹ?', null, '["Fùfú","Gaàrí","Láfún","Sítààsi"]', 1, 'Gaàrí ni ‘baálé’ ohun tí à p fêgê jẹ.', true, '2026-10-13 13:23:32.232', '2026-10-13 13:23:32.232', null, null, null, 'Nínú Gbágùúdá, oúnjç wo ni ‘baálé’ ohun tí à p fêgê jẹ?', '["Fùfú","Gaàrí","Láfún","Sítààsi"]', 'Gaàrí ni ‘baálé’ ohun tí à p fêgê jẹ.', '{"bold":["Gaàrí"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0866db23-7b1e-4159-9224-b4470106dd46', 'Biology', 'JAMB', null, 2026, null, 'When it''s cold, the blood vessels of the skin', null, '["dilate to increase the amount of blood flowing to the skin","constrict to reduce the amount of blood flowing to the skin","dilate to reduce the amount of blood flowing to the skin","constrict to increase the amount of blood flowing to the skin"]', 1, 'When it''s cold, the blood vessels of the skin constrict (vasoconstriction) to reduce the amount of blood flowing to the skin. This reduces heat loss from the body surface, conserving body heat. Vasodilation (dilation) would increase blood flow to the skin and cause heat loss, which is the response in hot conditions. The constriction of peripheral blood vessels is a thermoregulatory response to maintain core body temperature.', true, '2026-09-09 03:19:11.607', '2026-09-09 03:19:11.607', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('086fcf52-480d-489c-9e3b-e8f6f2e4e312', 'English Language', 'JAMB', null, 2024, null, 'Put the ______ on the rack.', null, '["big brown leather bag","big leather brown bag","brown leather big bag","leather brown big bag"]', 0, 'The correct order is: size, colour, material. "Big brown leather bag" is correct.', true, '2026-09-18 09:43:02.579', '2026-09-18 09:43:02.579', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('087553bf-4b04-471b-a008-45c718d451a5', 'Physics', 'JAMB', null, 1983, null, 'Which of the following may be used to determine relative humidity in a physics laboratory?
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('087803c9-c74b-421f-ba92-c6cf3e3e8a17', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'The theme of Hebrews centres on', null, '["law and prophets","creation","judgement","supremacy of Christ"]', 3, 'Hebrews emphasises Christ''s supremacy over angels, Moses, and the old covenant.', true, '2026-09-12 10:40:59.609', '2026-09-12 10:40:59.609', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('088e5a5a-d71a-4d7f-8f76-6a271e75583d', 'Chemistry', 'JAMB', null, 2026, null, 'Which property increases across a period in the periodic table?', null, '["Atomic radius","Metallic character","Ionization energy","Reactivity of metals"]', 2, 'Ionization energy increases across a period.', true, '2026-09-12 11:32:56.046', '2026-09-12 11:32:56.046', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('08aff8ca-f540-4dde-8c5a-71f75573a990', 'Financial Accounting', 'UTME', null, 2001, null, 'Marhumu and Yusuf are in partnership sharing profit and losses in the ratio of 2:1. On 31/3/2000, the partnership decided to admit Idris who is to take 1/4 of future profits without changing the ratio of Marhumu and Yusuf. What is the new profit-sharing ratio of Marhumu and Yusuf?', null, '["50% : 25%","50% : 20%","25% : 50%","25% : 25%"]', 0, 'New ratio: Idris takes 1/4. Remaining 3/4 shared between Marhumu and Yusuf in ratio 2:1. Marhumu = 3/4 x 2/3 = 1/2 = 50%. Yusuf = 3/4 x 1/3 = 1/4 = 25%.', true, '2026-10-12 22:00:07.084', '2026-10-12 22:00:07.084', null, null, null, 'Marhumu and Yusuf are in partnership sharing profit and losses in the ratio of 2:1. On 31/3/2000, the partnership decided to admit Idris who is to take 1/4 of future profits without changing the ratio of Marhumu and Yusuf. What is the new profit-sharing ratio of Marhumu and Yusuf?', '["<b>50% : 25%</b>","50% : 20%","25% : 50%","25% : 25%"]', 'New ratio: Idris takes 1/4. Remaining 3/4 shared between Marhumu and Yusuf in ratio 2:1. Marhumu = 3/4 x 2/3 = 1/2 = <b>50%</b>. Yusuf = 3/4 x 1/3 = 1/4 = <b>25%</b>.', '{"bold":["50% : 25%"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('08b131ee-6507-4069-adb8-3a44edc8c70b', 'Government', 'JAMB', null, 2026, null, 'An interest group that admits members and conducts its affairs according to stated rules is described as', null, '["Organizational","Associational","non-associational","Institutional"]', 1, 'An associational interest group admits members and follows stated rules.', true, '2026-09-12 11:23:55.836', '2026-09-12 11:23:55.836', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('08c5b87f-c033-4cfa-9615-ffca824bfaf1', 'English Language', 'JAMB', null, 2024, null, 'One of these functions is that it ______ the blood sugar.', null, '["releases","withholds","regulates","produces"]', 2, 'The liver regulates blood sugar.', true, '2026-09-18 09:43:02.84', '2026-09-18 09:43:02.84', null, null, 'CLOZE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('08cfae7e-bdcb-4388-be95-bf4d4a206314', 'English Language', 'JAMB', null, 2007, null, 'By twelve midnight, we will be <u>__________</u> en route for Britain.', null, '["airbourned","airborne","air borned","airbourne"]', 1, 'Correct spelling: airborne.', true, '2026-10-24 07:21:35.211', '2026-10-24 07:21:35.211', null, null, null, 'By twelve midnight, we will be <u>__________</u> en route for Britain.', '["airbourned","airborne","air borned","airbourne"]', 'Correct spelling: airborne.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('08d72032-4ec8-4425-a1bf-0fc218c2dd28', 'Physics', 'JAMB', null, 1994, null, 'A motor vehicle is brought to rest from a speed of 15 m s⁻¹ in 20 seconds. Calculate the retardation.', null, '["0.75 m s⁻²","1.33 m s⁻²","5.00 m s⁻²","7.50 m s⁻²"]', 0, 'a = (v - u)/t = (0 - 15)/20 = -0.75 m s⁻², so the retardation is 0.75 m s⁻².', true, '2026-10-12 19:15:38.89', '2026-10-12 19:15:38.89', null, null, null, 'A motor vehicle is brought to rest from a speed of 15 m s<sup>-1</sup> in 20 seconds. Calculate the retardation.', '["0.75 m s<sup>-2</sup>","1.33 m s<sup>-2</sup>","5.00 m s<sup>-2</sup>","7.50 m s<sup>-2</sup>"]', 'a = (v - u)/t = (0 - 15)/20 = -0.75 m s<sup>-2</sup>, so the retardation is 0.75 m s<sup>-2</sup>.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('08dc9656-b0f1-491a-8013-53ae2aa0ae61', 'Chemistry', 'JAMB', null, 2026, null, 'Which of the following is a secondary alkanol?', null, '["Butan-1-ol","Butan-2-ol","Ethanol","Butanal"]', 1, 'Butan-2-ol is a secondary alcohol.', true, '2026-09-12 11:36:25.467', '2026-09-12 11:36:25.467', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('08e9611e-7e3c-4489-98dd-2eda2ee2ff3b', 'Hausa', 'JAMB', null, 2011, null, 'labarin ''Kowa Ya Dogara Ga Allah, Kada Ya Ji Tsoron Mahassada, Balle Keta'' na cikin Magana Jari Ce na III na A. Imam, ya amsa sunansa ganin yadda', null, '["aka halaka Waziri","Sarkin Karaya ya cika umarnin Sarkin Sudan","aka yi shagalin sarautar Abdun Ugu","Abdun Ugu ya Ketare makircin Waziri."]', 0, 'Labarin ya amsa sunansa ganin yadda aka halaka Waziri.', true, '2026-10-13 10:37:22.48', '2026-10-13 10:37:22.48', null, null, null, 'labarin ''Kowa Ya Dogara Ga Allah, Kada Ya Ji Tsoron Mahassada, Balle Keta'' na cikin Magana Jari Ce na III na A. Imam, ya amsa sunansa ganin yadda', '["aka halaka Waziri","Sarkin Karaya ya cika umarnin Sarkin Sudan","aka yi shagalin sarautar Abdun Ugu","Abdun Ugu ya Ketare makircin Waziri."]', 'Labarin ya amsa sunansa ganin yadda aka halaka Waziri.', '{"bold":["aka halaka Waziri"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('08feef02-5fe1-4117-822e-e14fc757293e', 'Physics', 'JAMB', null, 1985, null, 'If the fundamental frequency of a closed pipe organ on a day when the speed of sound is 340 m s⁻¹ is 170 Hz, then the length of the pipe is', null, '["50 cm","70 cm","100 cm","150 cm","200 cm"]', 0, 'For a closed pipe f = v/(4L), so L = 340/(4 x 170) = 0.5 m = 50 cm.', true, '2026-10-12 19:15:21.801', '2026-10-12 19:15:21.801', null, null, null, 'If the fundamental frequency of a closed pipe organ on a day when the speed of sound is 340 m s<sup>-1</sup> is 170 Hz, then the length of the pipe is', '["50 cm","70 cm","100 cm","150 cm","200 cm"]', 'For a closed pipe f = v/(4L), so L = 340/(4 x 170) = 0.5 m = 50 cm.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('090d0613-2c22-4cc5-a225-0f8ce26cc4cb', 'Chemistry', 'JAMB', null, 2026, null, 'Which of the following is an oxidizing agent?', null, '["CO","H₂","Cl₂","CH₄"]', 2, 'Cl₂ is an oxidizing agent.', true, '2026-09-12 11:35:52.234', '2026-09-12 11:35:52.234', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('090d3afe-db47-43eb-abc3-e185cbde6496', 'Physics', 'JAMB', null, 1983, null, 'If the relative density of a metal is 19, what will be the mass of 20 cm³ of the metal when immersed in water?', null, '["380 g","400 g","360 g","39 g","180 g"]', 0, 'Density = 19 g/cm³, so mass = 19 x 20 = 380 g. Immersion in water changes the apparent weight (it would appear to weigh 360 g), not the mass.', true, '2026-10-12 19:15:15.994', '2026-10-12 19:15:15.994', null, null, null, 'If the relative density of a metal is 19, what will be the mass of 20 cm<sup>3</sup> of the metal when immersed in water?', '["380 g","400 g","360 g","39 g","180 g"]', 'Density = 19 g/cm<sup>3</sup>, so mass = 19 x 20 = 380 g. Immersion in water changes the apparent weight (it would appear to weigh 360 g), not the mass.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('091985bb-7705-4363-aae4-3dcadfba1c1a', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). Jimoh has <u>cupboard love</u> for Sidikatu.', null, '["love that never fails","genuine love","love for what he wants from her","love that can fail in time of trouble"]', 2, '''Cupboard love'' = affection for what one can get.', true, '2026-10-24 01:02:05.8', '2026-10-24 01:02:05.8', null, null, null, '(Choose the most appropriate interpretation). Jimoh has <u>cupboard love</u> for Sidikatu.', '["love that never fails","genuine love","<u>love for what he wants from her</u>","love that can fail in time of trouble"]', '''<b>Cupboard love</b>'' = <b>affection for what one can get</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0919c3ab-f135-4a5b-9ea8-158ee4f1ef8b', 'Government', 'JAMB', null, 2026, null, 'Under the 1999 constitution, the Chief Law Officer and the Supreme Court Judge respectively are the', null, '["Chief Judge, Chief Judge","Minister of Justice, Chief Judge","Attorney General, Chief Justice","Chief Registrar of the Supreme Court, Chief Justice"]', 2, 'Under the 1999 constitution, the Chief Law Officer and the Supreme Court Judge respectively are the Attorney General and the Chief Justice. The Attorney General is the chief law officer of the federation, responsible for all legal affairs of the government. The Chief Justice of Nigeria is the head of the judiciary and the Supreme Court. These are two distinct offices: Attorney General (executive/legal) and Chief Justice (judicial).', true, '2026-09-10 10:44:18.826', '2026-09-10 10:44:18.826', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('091b6540-3328-45f4-a93d-e468d0872bc8', 'English Language', 'JAMB', null, 2024, null, 'Identify the option that is nearest in meaning to the underlined word: Lunatics have some lucid moments', null, '["troubled","quiet","noisy","sane"]', 3, '"Lucid" means clear-headed or sane.', true, '2026-09-18 09:43:02.513', '2026-09-18 09:43:02.513', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0924c136-df5a-4fda-b3db-0f95e1f4020f', 'Physics', 'JAMB', null, 2003, null, 'A magnetic field is said to exist at a point if a force is', null, '["Deflection at the point","Strengthened at the point","Exerted on a moving charge at the point","Exerted on a stationary charge at the point"]', 2, 'A magnetic field exerts a force on a moving charge (or a current), but not on a stationary charge.', true, '2026-10-12 19:15:57.413', '2026-10-12 19:15:57.413', null, null, null, 'A magnetic field is said to exist at a point if a force is', '["Deflection at the point","Strengthened at the point","Exerted on a moving charge at the point","Exerted on a stationary charge at the point"]', 'A magnetic field exerts a force on a moving charge (or a current), but not on a stationary charge.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('09280025-3fca-441f-91ec-e2e190a08db6', 'Chemistry', 'JAMB', null, 2026, null, 'Determine the empirical formula of a compound containing: C = 40%, H = 6.7%, O = 53.3%', null, '["CH₂O","C₂H₄O₂","CHO","C₂H₆O"]', 0, 'Moles: C = 40/12 = 3.33, H = 6.7/1 = 6.7, O = 53.3/16 = 3.33. Ratio = 3.33:6.7:3.33 = 1:2:1. Empirical formula = CH₂O.', true, '2026-09-12 11:32:59.844', '2026-09-12 11:32:59.844', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('09384d3e-6871-4e3c-9349-5c652792cb56', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. There are many <u>venal</u> judges in our law courts today.', null, '["qualified","professional","corrupt","honest"]', 2, 'Venal = corrupt.', true, '2026-10-24 01:01:48.282', '2026-10-24 01:01:48.282', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. There are many <u>venal</u> judges in our law courts today.', '["qualified","professional","<u>corrupt</u>","honest"]', '<b>Venal</b> = <b>corrupt</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('093af885-9d4b-4a4c-aba9-454972fe0f19', 'Financial Accounting', 'UTME', null, 2002, null, 'Statement of Assets and liabilities as at 31st December, 2001. Shareholder''s interest 240 Current liabilities 20 Current assets 110 Fixed assets 140. Determine the value of the trade investment', 'https://res.cloudinary.com/kwi1uv0g/image/upload/v1791840775/questions/kwwsveh4qknpjjyolfh7.jpg', '["N8m","N10m","N15m","N20m"]', 1, 'Value of trade investment is Net Assets minus Shareholder''s interest. 250m - 240m = 10m.', true, '2026-10-12 21:59:57.285', '2026-10-12 21:59:57.285', null, null, null, 'Statement of Assets and liabilities as at 31st December, 2001. Shareholder''s interest 240 Current liabilities 20 Current assets 110 Fixed assets 140. Determine the value of the trade investment', '["N8m","<b>N10m</b>","N15m","N20m"]', 'Value of trade investment is Net Assets minus Shareholder''s interest. 250m - 240m = <b>10m</b>.', '{"bold":["10m"],"italic":[],"underline":[],"fillBlanks":[]}');
