insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0964b625-34f6-47c6-b9ce-b8b89b6f31ad', 'Government', 'JAMB', null, 2026, null, 'In which year did the Nigerian government first officially adopt federalism?', null, '["1960","1954","1946","1951"]', 1, 'Nigeria first officially adopted federalism in 1954.', true, '2026-09-12 11:24:44.02', '2026-09-12 11:24:44.02', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('09689b6d-3e33-48c7-b1ea-da942ba0ded2', 'Physics', 'JAMB', null, 2026, null, 'Which of the following is NOT True? I. specific Gravity is measured with Hydrometer II. Heat is measured with thermometer III. Density is measured with an hygrometer IV. Time is measured with a stopwatch V. Voltage is measured with a voltmeter.', null, '["all of above","II only","i, ii, III only","ii & III only","none"]', 1, 'Statement II is not true: Heat is measured with a calorimeter, not a thermometer. A thermometer measures temperature, not heat. Specific gravity is measured with a hydrometer, density with a hydrometer (not hygrometer—a hygrometer measures humidity), time with a stopwatch, and voltage with a voltmeter.
