insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('097afdc6-cfa5-4f90-9cae-9296888719d4', 'Biology', 'JAMB', null, 2003, null, 'Nervous control differs from hormonal control in that the former', null, '["involves only chemical transmission","is a slower process","produces short-term changes","has no specific pathway"]', 2, 'Nervous responses are typically rapid and produce short-term localized changes compared to hormones.', true, '2026-10-12 20:05:10.064', '2026-10-12 20:05:10.064', null, null, null, 'Nervous control differs from hormonal control in that the former', '["involves only chemical transmission","is a slower process","produces short-term changes","has no specific pathway"]', 'Nervous responses are typically rapid and produce short-term localized changes compared to hormones.', '{}');
