insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('09b8683d-a227-4c92-a03f-7c10ad5e55a6', 'English Language', 'JAMB', null, 2007, null, 'That single <u>__________</u> was enough to spoil a whole life time of good living.', null, '["occurence","ocurence","ocurrent","occurrense","occurrence"]', 4, 'Correct spelling: occurrence.', true, '2026-10-24 07:21:32.29', '2026-10-24 07:21:32.29', null, null, null, 'That single <u>__________</u> was enough to spoil a whole life time of good living.', '["occurence","ocurence","ocurrent","occurrense","occurrence"]', 'Correct spelling: occurrence.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('09c980a4-84a1-4de0-92f8-93261fb0b9ec', 'Government', 'JAMB', null, 2026, null, 'A system of government in which power derives from total control of the instruments of force is called', null, '["monarchy","oligarchy","capitalism","fascism"]', 3, 'Fascism derives power from total control of instruments of force.', true, '2026-09-12 11:24:55.851', '2026-09-12 11:24:55.851', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('09cd6542-87a6-4c40-aab5-ebfafc908951', 'Economics', 'JAMB', null, 2026, null, 'If the supply curve of labour market is given as S = 4L + 8. What is L when s = 20?', null, '["2","4","5","3"]', 3, '20 = 4L + 8. 4L = 12. L = 3.', true, '2026-09-12 11:00:36.753', '2026-09-12 11:00:36.753', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('09daf131-e934-4fce-839f-d8fb751bba72', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). At the age of 80, Musa wished he could <u>turn the clock back</u>.', null, '["stop the clock","put down the clock","go back in time","have more time"]', 2, '''Turn the clock back'' = go back in time.', true, '2026-10-24 01:04:19.861', '2026-10-24 01:04:19.861', null, null, null, '(Choose the most appropriate interpretation). At the age of 80, Musa wished he could <u>turn the clock back</u>.', '["stop the clock","put down the clock","<u>go back in time</u>","have more time"]', '''<b>Turn the clock back</b>'' = <b>go back in time</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('09e4a905-85f2-4dec-8d4f-4b30e962e8eb', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The press described the efforts of the government in <u>pejorative</u> terms.', null, '["superlative","palpable","critical","contemptible"]', 3, 'Pejorative = contemptible.', true, '2026-10-24 01:04:05.151', '2026-10-24 01:04:05.151', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The press described the efforts of the government in <u>pejorative</u> terms.', '["superlative","palpable","critical","<u>contemptible</u>"]', '<b>Pejorative</b> = <b>contemptible</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('09f688a8-98b9-4712-915c-203096d8b5ad', 'Chemistry', 'JAMB', null, 2026, null, 'Which of the following forms an acidic oxide?', null, '["N","Mg","S","Ca"]', 2, 'Sulfur forms acidic oxides (SO₂, SO₃).', true, '2026-09-12 11:35:51.57', '2026-09-12 11:35:51.57', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0a0084d8-205a-4b9a-b994-6c47e71d081e', 'Physics', 'JAMB', null, 1983, null, 'A train has an initial velocity of 44 m/s and an acceleration of -4 m/s². Its velocity after 10 seconds is', null, '["2 m/s","4 m/s","8 m/s","12 m/s","16 m/s"]', 1, 'v = u + at = 44 + (-4)(10) = 44 - 40 = 4 m/s.', true, '2026-10-12 19:15:16.712', '2026-10-12 19:15:16.712', null, null, null, 'A train has an initial velocity of 44 m/s and an acceleration of -4 m/s<sup>2</sup>. Its velocity after 10 seconds is', '["2 m/s","4 m/s","8 m/s","12 m/s","16 m/s"]', 'v = u + at = 44 + (-4)(10) = 44 - 40 = 4 m/s.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0a0df564-1fa3-41e0-a83a-66039e610de1', 'Biology', 'JAMB', null, 2005, null, 'The association in which one member benefits and the other is relatively unaffected by the interaction is termed', null, '["symbiosis","parasitism","commensalism","mutualism"]', 2, 'Commensalism benefits one member without affecting the other.', true, '2026-10-12 20:59:38.257', '2026-10-12 20:59:38.257', null, null, null, 'The association in which one member benefits and the other is relatively unaffected by the interaction is termed', '["symbiosis","parasitism","commensalism","mutualism"]', 'Commensalism benefits one member without affecting the other.', '{"bold":["Commensalism"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0a1707e0-47bc-4f20-8e33-1484d1527b6d', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'The elders at Jerusalem advised Paul on his arrival in the city to', null, '["avoid the Jewish Christians","purify himself along with men under vows","join those in the temple for prayer and fasting","preach the good news"]', 1, 'The elders at Jerusalem advised Paul to purify himself along with men under vows. They suggested this to demonstrate to the Jewish Christians that Paul was not teaching Jews to forsake the law of Moses.', true, '2026-09-12 09:46:11.413', '2026-09-12 09:46:11.413', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0a174848-2b86-414e-aa17-540c2640de0a', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). <u>Be careful!</u> We are approaching the crossroads.', null, '["look up","watch out","look out","hold up","look in"]', 1, '''Watch out'' = be careful.', true, '2026-10-24 01:04:14.29', '2026-10-24 01:04:14.29', null, null, null, '(Choose the most appropriate interpretation). <u>Be careful!</u> We are approaching the crossroads.', '["look up","<u>watch out</u>","look out","hold up","look in"]', '''<b>Watch out</b>'' = <b>be careful</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0a1b3ca6-7e39-4610-b9eb-9fd061fb84ae', 'English Language', 'JAMB', null, 2007, null, 'The driver will <u>__________</u> all the students interested in going to Lagos tomorrow at 7 a.m. outside the main building', null, '["lift","lift up","pick","pick up"]', 3, 'Correct form: pick up.', true, '2026-10-24 07:21:41.954', '2026-10-24 07:21:41.954', null, null, null, 'The driver will <u>__________</u> all the students interested in going to Lagos tomorrow at 7 a.m. outside the main building', '["lift","lift up","pick","pick up"]', 'Correct form: pick up.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0a28c7a5-509a-4453-a3b3-944b27ff936b', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Every human being is <u>vulnerable</u> to communicable diseases.', null, '["liable","immuned","lifted","closed"]', 0, 'Vulnerable = liable.', true, '2026-10-24 01:01:55.333', '2026-10-24 01:01:55.333', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Every human being is <u>vulnerable</u> to communicable diseases.', '["<u>liable</u>","immuned","lifted","closed"]', '<b>Vulnerable</b> = <b>liable</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0a2b8f6f-7b50-4cb8-bb6f-c83aefe7d87e', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. It is sheer <u>fantasy</u> to believe that there could never be a miscalculation by any nation that has atomic weapons. Fantasy here means ________________', null, '["dream","hope","nonsense","joke","stupidity"]', 2, 'Fantasy = unrealistic notion; nonsense.', true, '2026-10-24 01:03:52.897', '2026-10-24 01:03:52.897', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. It is sheer <u>fantasy</u> to believe that there could never be a miscalculation by any nation that has atomic weapons. Fantasy here means ________________', '["dream","hope","<u>nonsense</u>","joke","stupidity"]', '<b>Fantasy</b> = unrealistic notion; <b>nonsense</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0a32ce81-c3c5-4702-83fe-adf068bfbc1e', 'Biology', 'JAMB', null, 2026, null, 'In the normal sense roots are: I. Positively phototropic II. Negatively phototropic III. Positively geotropic IV. Negatively geotropic', null, '["I & III","I & IV","II & III","II & IV"]', 2, 'Roots are negatively phototropic (grow away from light) and positively geotropic (grow toward gravity). Negative phototropism allows roots to grow away from light and deeper into the soil. Positive geotropism causes roots to grow downward, anchoring the plant and enabling access to water and nutrients. Shoots are positively phototropic (grow toward light) and negatively geotropic (grow away from gravity). This opposite response of roots and shoots to light and gravity ensures optimal positioning of the plant in its environment.', true, '2026-09-09 03:18:32.351', '2026-09-09 03:18:32.351', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0a340f9d-0c4a-43e0-8987-1522a7ee6490', 'Yoruba', 'JAMB', null, 2002, null, 'Ka àwôn àyòkà ìsàlé yìí, Kí o sì dáhùn àwòn ìbéèrè tí ó télè wòn. Òba Fadérera ní oko kòkó àti oko obì, ó ní oko ìyù àti oko òwú, ilá inú oko rè ni gbogbo ìlú gbójú lé, ìyù àkùrò rè ní kòkò yójú sí òjà. Oko òba gbòòrò púpõ.Sé ìgbà púpõ ni òpòlópõ ènìyàn p lò láti ìyìç òfé fún òba. Òba tún fì ògbòn yè é tó bèé tí ìrè oko rè kò wòn tó ti çlòmíràn. Òba Fadérera bí ómòkùnrin kan tí ó féràn púpô. Ómò òba yìí kì í yè ìyè kankan, àfì kì ó máa ìyìré nínu ògbà baba rê. Àwòn ìrányè pò láti fún un ní gbogbo ohun tí ó bá p fè. Aỳò tuntun ni òmò òba p wò ní ojoojúmò. Òba kè òmò náà bí çyin ojú, ó kè ç pélú ohun ìní àti ìrányè. Ohun kan wá jě děùn òkàn àwòn ará ìlú Éyin-Òla. Ohun náà ni pé, ìkòokò a máa dédé wò ìlù láti gbé ewùrê tàbí àgùntàn wòn lò. Ní ìgbà púpõ ni àwòn ará ìlù tì lò ké bá òba kí ó bá àwòn yanjù òràn tí ó dé bá wòn. Nígbà tí ó yè wàyí o, àwòn ìkòokò pàápàá wá tùn ara mú, wòn béré sí í gbé àwòn òmò ará ìlù Éyin-òla. Àwòn ìlù tùn ké lò sí òdò òba, ìgùbòn òba kò ka òrõ náà sí rárá. Ní òjò kan nígbà tí òmò òba Fadérera àti àwòn çmèwà bàbá rê p ìyìré lórí pápá tí ó wà lèbàà ààfin, ìkòokò plá kan yò sí wòn, ó sì gbé òmò òba lò ráúráú. Nígbà tí òba gbò ohun tí ó ìçlè, ó kígbè ní ohùn rara. Örö náà wá ya gbogbo ìlù lënu nítorí pé òba pàyç lësêkçsê pé kí gbogbo àwòn òdç atamátasê ìlù jáde, kí wön sì pa gbogbo ìkokò tí ó wà agbègbè náà. Sùgbön ìkòokò tí pa òmò òba Fadérera jç. Ëpa kò bóró mò. Asòtàn fì Òba Fadérera hàn bíi', null, '["apànìyàn","onínú rere","alaìbìkítà","alaìláàánú."]', 1, 'Asòtàn fì Òba Fadérera hàn bíi onínú rere.', true, '2026-10-13 13:22:37.622', '2026-10-13 13:22:37.622', null, null, null, 'Ka àwôn àyòkà ìsàlé yìí, Kí o sì dáhùn àwòn ìbéèrè tí ó télè wòn. Òba Fadérera ní oko kòkó àti oko obì, ó ní oko ìyù àti oko òwú, ilá inú oko rè ni gbogbo ìlú gbójú lé, ìyù àkùrò rè ní kòkò yójú sí òjà. Oko òba gbòòrò púpõ.Sé ìgbà púpõ ni òpòlópõ ènìyàn p lò láti ìyìç òfé fún òba. Òba tún fì ògbòn yè é tó bèé tí ìrè oko rè kò wòn tó ti çlòmíràn. Òba Fadérera bí ómòkùnrin kan tí ó féràn púpô. Ómò òba yìí kì í yè ìyè kankan, àfì kì ó máa ìyìré nínu ògbà baba rê. Àwòn ìrányè pò láti fún un ní gbogbo ohun tí ó bá p fè. Aỳò tuntun ni òmò òba p wò ní ojoojúmò. Òba kè òmò náà bí çyin ojú, ó kè ç pélú ohun ìní àti ìrányè. Ohun kan wá jě děùn òkàn àwòn ará ìlú Éyin-Òla. Ohun náà ni pé, ìkòokò a máa dédé wò ìlù láti gbé ewùrê tàbí àgùntàn wòn lò. Ní ìgbà púpõ ni àwòn ará ìlù tì lò ké bá òba kí ó bá àwòn yanjù òràn tí ó dé bá wòn. Nígbà tí ó yè wàyí o, àwòn ìkòokò pàápàá wá tùn ara mú, wòn béré sí í gbé àwòn òmò ará ìlù Éyin-òla. Àwòn ìlù tùn ké lò sí òdò òba, ìgùbòn òba kò ka òrõ náà sí rárá. Ní òjò kan nígbà tí òmò òba Fadérera àti àwòn çmèwà bàbá rê p ìyìré lórí pápá tí ó wà lèbàà ààfin, ìkòokò plá kan yò sí wòn, ó sì gbé òmò òba lò ráúráú. Nígbà tí òba gbò ohun tí ó ìçlè, ó kígbè ní ohùn rara. Örö náà wá ya gbogbo ìlù lënu nítorí pé òba pàyç lësêkçsê pé kí gbogbo àwòn òdç atamátasê ìlù jáde, kí wön sì pa gbogbo ìkokò tí ó wà agbègbè náà. Sùgbön ìkòokò tí pa òmò òba Fadérera jç. Ëpa kò bóró mò. Asòtàn fì Òba Fadérera hàn bíi', '["apànìyàn","onínú rere","alaìbìkítà","alaìláàánú."]', 'Asòtàn fì Òba Fadérera hàn bíi onínú rere.', '{"bold":["onínú rere"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0a3a4bf9-e588-4ed4-b7ba-1b9e8549f0bc', 'Government', 'JAMB', null, 2026, null, 'An order compelling a lower court or public corporation to perform in accordance with legitimacy is called', null, '["the writ of mandamus","the great writ","the writ of ombudsman","none of the above"]', 0, 'The writ of mandamus compels performance of a duty.', true, '2026-09-12 11:24:52.49', '2026-09-12 11:24:52.49', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0a513c91-909b-4e56-b48f-dc18226f0bda', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. <u>As soon as</u> the headmaster appeared, the chanting resumed.', null, '["Immediately","Much later","Soon after","Almost as"]', 1, 'As soon as = immediately; opposite = much later.', true, '2026-10-24 07:21:15.968', '2026-10-24 07:21:15.968', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. <u>As soon as</u> the headmaster appeared, the chanting resumed.', '["Immediately","Much later","Soon after","Almost as"]', 'As soon as = immediately; opposite = much later.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0a64f746-3fab-42cb-b139-e6008fbb5566', 'Biology', 'JAMB', null, 2001, null, 'The epiphytic habitat can best be described as', null, '["aquatic","terrestrial","arboreal","estuarine"]', 2, 'Epiphytes live on trees, making their habitat arboreal.', true, '2026-10-12 20:59:29.004', '2026-10-12 20:59:29.004', null, null, null, 'The epiphytic habitat can best be described as', '["aquatic","terrestrial","arboreal","estuarine"]', 'Epiphytes live on trees, making their habitat arboreal.', '{"bold":["arboreal"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0a653088-9bb7-4654-a008-cd5883a1f474', 'Physics', 'JAMB', null, 1997, null, 'A piece of wire gauze can be made to lie on water because', null, '["The wire gauze is less dense than water","The water molecules repel the wire gauze upwards.","The water surface has the effect of an elastic thin skin","Of the cohesive forces between the water and the wire gauze molecules."]', 2, 'Surface tension makes the water surface behave like a stretched elastic skin that can support light objects.', true, '2026-10-12 19:15:43.2', '2026-10-12 19:15:43.2', null, null, null, 'A piece of wire gauze can be made to lie on water because', '["The wire gauze is less dense than water","The water molecules repel the wire gauze upwards.","The water surface has the effect of an elastic thin skin","Of the cohesive forces between the water and the wire gauze molecules."]', 'Surface tension makes the water surface behave like a stretched elastic skin that can support light objects.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
