insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0a6ddad5-b5d0-4600-ac8e-e00f473dd0bc', 'Literature in English', 'JAMB', null, 2026, null, 'The first-person narrative style is used when the main character in a novel recounts', null, '["The author''s Story","Other character''s story","His own story","His best friend''s story"]', 2, 'The first-person narrative style is used when the main character in a novel recounts his own story. In first-person narration, the narrator uses pronouns like ''I,'' ''me,'' and ''my'' and tells the story from their own perspective. The narrator is usually a character within the story. This creates intimacy and allows the reader to see events through the narrator''s eyes.', true, '2026-09-10 10:47:09.619', '2026-09-10 10:47:09.619', null, null, null, null, null, null, null);
