insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0aa18fed-a295-4930-af91-6f7ecd8fe835', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. This is <u>an abridged</u> version of No Longer at Ease.', null, '["an enlarged","an illustrated","a shortened","an outdated"]', 2, 'Abridged = shortened.', true, '2026-10-24 01:01:54.908', '2026-10-24 01:01:54.908', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. This is <u>an abridged</u> version of No Longer at Ease.', '["an enlarged","an illustrated","<u>a shortened</u>","an outdated"]', '<b>Abridged</b> = <b>a shortened</b>.', '{}');
