insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0ab46ad2-be1d-40c2-af1b-ec237ca2914c', 'Government', 'JAMB', null, 2026, null, 'The colonial governor whose constitution introduced elective principle into Nigerian politics was', null, '["Arthur Richards","Frederick Lugard","Hugh Clifford","John Macpherson"]', 2, 'Hugh Clifford introduced the elective principle in 1922.', true, '2026-09-12 11:24:26.082', '2026-09-12 11:24:26.082', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0ab734b0-f8d8-4031-8a91-df1d49e79d26', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The journalist''s write-up contained a <u>plethora</u> of detail.', null, '["simplicity","shortage","complexity","spectrum"]', 1, 'Plethora = excess; opposite = shortage.', true, '2026-10-24 07:21:22.456', '2026-10-24 07:21:22.456', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The journalist''s write-up contained a <u>plethora</u> of detail.', '["simplicity","shortage","complexity","spectrum"]', 'Plethora = excess; opposite = shortage.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0abfc569-42e6-41ea-a645-a261df8513e9', 'Physics', 'JAMB', null, 1993, null, 'The primary aim in high tension transmission is to', null, '["Minimize electrical energy losses due to heat production","Increase the rate of energy transfer by using high voltage","Increase the current in the wires.","Generate electricity at high current and low voltage."]', 0, 'At high voltage the current is small for a given power, so heat loss (I²R) in the transmission lines is minimized.', true, '2026-10-12 19:15:38.566', '2026-10-12 19:15:38.566', null, null, null, 'The primary aim in high tension transmission is to', '["Minimize electrical energy losses due to heat production","Increase the rate of energy transfer by using high voltage","Increase the current in the wires.","Generate electricity at high current and low voltage."]', 'At high voltage the current is small for a given power, so heat loss (I<sup>2</sup>R) in the transmission lines is minimized.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0ac413f1-3498-43f2-b6c9-1a145010db0b', 'Chemistry', 'JAMB', null, 2026, null, 'The oxidation number of sulfur in H₂SO₄ is:', null, '["+2","+4","+6","-2"]', 2, 'In H₂SO₄, H = +1, O = -2. 2(+1) + S + 4(-2) = 0. S = +6.', true, '2026-09-12 11:35:57.146', '2026-09-12 11:35:57.146', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0ac6d4d9-178f-4fb6-9af0-f80e27cbc1cc', 'Physics', 'JAMB', null, 1992, null, 'Which of the following arrangements of the components of the electromagnetic spectrum is in ascending order of wavelengths?', null, '["Gamma rays, ultraviolet rays, x-rays, infra-red rays.","Gamma rays, x-rays, ultraviolet rays, infra-red rays","Infra-red rays, ultraviolet rays, x-rays, gamma rays.","Gamma rays, ultraviolet rays, infra-red rays, x-rays."]', 1, 'Wavelength increases in the order gamma rays, X-rays, ultraviolet, visible, infra-red, radio waves.', true, '2026-10-12 19:15:36.14', '2026-10-12 19:15:36.14', null, null, null, 'Which of the following arrangements of the components of the electromagnetic spectrum is in ascending order of wavelengths?', '["Gamma rays, ultraviolet rays, x-rays, infra-red rays.","Gamma rays, x-rays, ultraviolet rays, infra-red rays","Infra-red rays, ultraviolet rays, x-rays, gamma rays.","Gamma rays, ultraviolet rays, infra-red rays, x-rays."]', 'Wavelength increases in the order gamma rays, X-rays, ultraviolet, visible, infra-red, radio waves.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0ad9348c-18c2-460e-a461-08ed8f95e70e', 'Physics', 'JAMB', null, 1988, null, 'When a resistance R is connected across a cell, the voltage across the terminals of the cell is reduced to two-thirds of its nominal value. The internal resistance of the cell is', null, '["R/3","R/2","2R/3","R"]', 1, 'V/E = R/(R + r) = 2/3, so 3R = 2R + 2r and r = R/2.', true, '2026-10-12 19:15:28.225', '2026-10-12 19:15:28.225', null, null, null, 'When a resistance R is connected across a cell, the voltage across the terminals of the cell is reduced to two-thirds of its nominal value. The internal resistance of the cell is', '["R/3","R/2","2R/3","R"]', 'V/E = R/(R + r) = 2/3, so 3R = 2R + 2r and r = R/2.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0ade8754-8f9a-4a4d-a67a-381cacb11555', 'English Language', 'JAMB', null, 2007, null, 'When the soldiers saw that resistance was <u>__________</u> they stopped fighting', null, '["inadequate","inefficient","futile","successful"]', 2, 'Correct spelling: futile.', true, '2026-10-24 07:21:44.217', '2026-10-24 07:21:44.217', null, null, null, 'When the soldiers saw that resistance was <u>__________</u> they stopped fighting', '["inadequate","inefficient","futile","successful"]', 'Correct spelling: futile.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0b02ad8e-1f1b-430b-b81d-acae9cadf48a', 'Biology', 'JAMB', null, 2003, null, 'If a nursing mother is not producing enough milk, her hormonal system is probably in deficient in', null, '["Prolactin","testosterone","thyroxin","insulin"]', 0, 'Prolactin is the key hormone responsible for milk synthesis and secretion in mammals.', true, '2026-10-12 20:05:11.558', '2026-10-12 20:05:11.558', null, null, null, 'If a nursing mother is not producing enough milk, her hormonal system is probably in deficient in', '["Prolactin","testosterone","thyroxin","insulin"]', 'Prolactin is the key hormone responsible for milk synthesis and secretion in mammals.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0b03dafa-7cb0-4add-bab5-f735f6fc49e8', 'Physics', 'JAMB', null, 2000, null, 'The velocity v of a particle in a time t is given by the equation v = 10 + 2t². Find the instantaneous acceleration after 5 seconds.', null, '["10 m s⁻²","15 m s⁻²","20 m s⁻²","60 m s⁻²"]', 2, 'a = dv/dt = 4t = 4 x 5 = 20 m s⁻².', true, '2026-10-12 19:15:49.214', '2026-10-12 19:15:49.214', null, null, null, 'The velocity v of a particle in a time t is given by the equation v = 10 + 2t<sup>2</sup>. Find the instantaneous acceleration after 5 seconds.', '["10 m s<sup>-2</sup>","15 m s<sup>-2</sup>","20 m s<sup>-2</sup>","60 m s<sup>-2</sup>"]', 'a = dv/dt = 4t = 4 x 5 = 20 m s<sup>-2</sup>.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0b0bc0a6-4b2e-4199-9960-a485f82b645d', 'Biology', 'JAMB', null, 2013, null, 'Oestrogen is a hormone that is synthesized in the', null, '["Anterior pituitary","Adrenal cortex","Ovaries","Testes"]', 2, 'Oestrogen is synthesized in the ovaries.', true, '2026-10-12 20:59:47.89', '2026-10-12 20:59:47.89', null, null, null, 'Oestrogen is a hormone that is synthesized in the', '["Anterior pituitary","Adrenal cortex","Ovaries","Testes"]', 'Oestrogen is synthesized in the ovaries.', '{"bold":["ovaries"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0b0caf0a-dd58-4488-9671-c19b151a3aaf', 'Literature in English', 'JAMB', null, 2026, null, 'The use of animals with human attributes in The Nun''s Priest''s Tale is an example of', null, '["Allegory","Satire","Anthropomorphism","Paradox"]', 2, 'The use of animals with human attributes is anthropomorphism.', true, '2026-09-12 11:12:03.235', '2026-09-12 11:12:03.235', null, null, null, null, null, null, null);
