insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0b269294-9bb4-40f8-a4c0-befeade921ba', 'English Language', 'JAMB', null, 2024, null, 'Which of these word is stressed on the first syllable (I) Pacify (II) Appease (III) basement (IV) Dictionary', null, '["I&II","I&IV","IV","I","II&III"]', 2, '"Dictionary" has stress on the first syllable.', true, '2026-09-18 09:43:02.407', '2026-09-18 09:43:02.407', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0b2c69e4-471e-406b-9ab0-1e56adb4d839', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'One of the four rivers found in the garden of Eden was...', null, '["Nile","Tigris","Abana","Jordan"]', 1, 'Genesis 2:10-14 names the four rivers flowing out of Eden as Pishon, Gihon, Tigris (Hiddekel), and Euphrates.', true, '2026-09-09 17:18:24.107', '2026-09-09 17:18:24.107', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0b330f80-4e63-4b80-bb57-a35746cd3267', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The law is often <u>tardy</u> in reacting to trends in attitudes.', null, '["slow","exclusive","generous","quick"]', 0, 'Tardy = slow.', true, '2026-10-24 01:04:06.654', '2026-10-24 01:04:06.654', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The law is often <u>tardy</u> in reacting to trends in attitudes.', '["<u>slow</u>","exclusive","generous","quick"]', '<b>Tardy</b> = <b>slow</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0b3e29ae-dca9-41b6-8845-18b6fda74b7b', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. All the accident victims are bleeding <u>profusely</u>.', null, '["slowly","excessively","diffusely","clearly"]', 1, 'Profusely = excessively.', true, '2026-10-24 01:01:49.761', '2026-10-24 01:01:49.761', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. All the accident victims are bleeding <u>profusely</u>.', '["slowly","<u>excessively</u>","diffusely","clearly"]', '<b>Profusely</b> = <b>excessively</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0b4765f9-ccbd-456a-a0ad-07c456f4545e', 'Physics', 'JAMB', null, 1988, null, 'An object is placed 10 cm in front of a concave mirror of focal length 15 cm. What is the position and nature of the image formed?', null, '["30 cm and virtual","6 cm and real","6 cm and virtual","30 cm and real."]', 0, '1/v = 1/f - 1/u = 1/15 - 1/10 = -1/30, so v = -30 cm. The image is virtual, 30 cm behind the mirror (object inside the focal length).', true, '2026-10-12 19:15:27.905', '2026-10-12 19:15:27.905', null, null, null, 'An object is placed 10 cm in front of a concave mirror of focal length 15 cm. What is the position and nature of the image formed?', '["30 cm and virtual","6 cm and real","6 cm and virtual","30 cm and real."]', '1/v = 1/f - 1/u = 1/15 - 1/10 = -1/30, so v = -30 cm. The image is virtual, 30 cm behind the mirror (object inside the focal length).', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0b595b2c-e41c-41b8-bdeb-05ff607b29ec', 'Economics', 'JAMB', null, 2026, null, 'Nations engage in external trade because of difference in?', null, '["Comparative cost","Absolute cost","Total cost","Marginal cost"]', 0, 'Nations trade due to differences in comparative cost.', true, '2026-09-12 11:02:13.56', '2026-09-12 11:02:13.56', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0b69c127-239c-4c02-9fa5-ea92267085ee', 'Economics', 'JAMB', null, 2026, null, 'A market for medium- and long-term loans is called?', null, '["Money market","Capital market","Stock exchange","Commodity market"]', 1, 'Capital market is for medium- and long-term loans.', true, '2026-09-12 11:01:12.446', '2026-09-12 11:01:12.446', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0b6f4aea-c827-413a-ac29-520112b0d757', 'Physics', 'JAMB', null, 1984, null, 'What is the cost of running five 50 W lamps and four 100 W lamps for 10 hours if electrical energy costs 2 kobo per kWh?', null, '["N 0.65","N 0.13","N 3.90","N 39.00","N 234.00"]', 1, 'Total power = 5 x 50 + 4 x 100 = 650 W = 0.65 kW. Energy = 0.65 x 10 = 6.5 kWh. Cost = 6.5 x 2 kobo = 13 kobo = N 0.13.', true, '2026-10-12 19:15:20.332', '2026-10-12 19:15:20.332', null, null, null, 'What is the cost of running five 50 W lamps and four 100 W lamps for 10 hours if electrical energy costs 2 kobo per kWh?', '["N 0.65","N 0.13","N 3.90","N 39.00","N 234.00"]', 'Total power = 5 x 50 + 4 x 100 = 650 W = 0.65 kW. Energy = 0.65 x 10 = 6.5 kWh. Cost = 6.5 x 2 kobo = 13 kobo = N 0.13.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0b7336dd-125a-4272-b06b-71c92e76cb64', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). The Vice Chancellor, who is <u>stickler for rules</u>, refused the request by the students for the semester to be rescheduled.', null, '["a puritan","a pedantist","a disciplinarian","an idealist"]', 2, '''Stickler for rules'' = disciplinarian.', true, '2026-10-24 01:02:06.696', '2026-10-24 01:02:06.696', null, null, null, '(Choose the most appropriate interpretation). The Vice Chancellor, who is <u>stickler for rules</u>, refused the request by the students for the semester to be rescheduled.', '["a puritan","a pedantist","<u>a disciplinarian</u>","an idealist"]', '''<b>Stickler for rules</b>'' = <b>disciplinarian</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0b779715-dfc2-4ba3-ae2e-7e83e724002b', 'Physics', 'JAMB', null, 1994, null, 'Light of frequency 6.0 x 10¹⁴ Hz travelling in air is transmitted through glass of refractive index 1.5. Calculate the frequency of the light in the glass.', null, '["4.0 x 10¹⁴ Hz","6.0 x 10¹⁴ Hz","7.5 x 10¹⁴ Hz","9.0 x 10¹⁴ Hz"]', 1, 'Frequency is fixed by the source and does not change when light enters another medium.', true, '2026-10-12 19:15:39.965', '2026-10-12 19:15:39.965', null, null, null, 'Light of frequency 6.0 x 10<sup>14</sup> Hz travelling in air is transmitted through glass of refractive index 1.5. Calculate the frequency of the light in the glass.', '["4.0 x 10<sup>14</sup> Hz","6.0 x 10<sup>14</sup> Hz","7.5 x 10<sup>14</sup> Hz","9.0 x 10<sup>14</sup> Hz"]', 'Frequency is fixed by the source and does not change when light enters another medium.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0b79bfdc-5013-4f07-874d-d8c270807c1b', 'Physics', 'JAMB', null, 2026, null, 'An open pipe is different from a closed pipe because', null, '["it contains odd harmonics while closed has even harmonics","its overtones are even harmonics while a closed pipe are odd harmonics","its vibrations are longitudinal while that of closed are transverse","it contains odd and even harmonics while closed pipe has odd harmonics"]', 3, 'An open pipe contains both odd and even harmonics, while a closed pipe contains only odd harmonics. This is because an open pipe has antinodes at both ends, while a closed pipe has a node at the closed end and an antinode at the open end.', true, '2026-09-10 10:56:42.874', '2026-09-10 10:56:42.874', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0b81b7e0-a450-42dc-a256-9239332e3e73', 'Literature in English', 'JAMB', null, 2026, null, 'Poetry that does not follow a fixed metrical pattern or rhyme scheme is', null, '["epic","free verse","ode","sonnet"]', 1, 'Poetry that does not follow a fixed metrical pattern or rhyme scheme is called free verse. Free verse is a form of poetry that is free from the constraints of regular meter and rhyme. It relies on other poetic devices such as imagery, rhythm, and line breaks. An epic is a long narrative poem, an ode is a lyric poem of praise, and a sonnet is a 14-line poem with a specific rhyme scheme.', true, '2026-09-10 10:45:34.075', '2026-09-10 10:45:34.075', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0b8dad75-d492-49a8-ab3a-8eb51b36eccf', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The manager described Mfon as a man of <u>vehement character</u>.', null, '["clever and helpful","troublesome and noisy","weak and uninterested","strong and insistent"]', 3, 'Vehement = strong and insistent.', true, '2026-10-24 01:04:06.274', '2026-10-24 01:04:06.274', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The manager described Mfon as a man of <u>vehement character</u>.', '["clever and helpful","troublesome and noisy","weak and uninterested","<u>strong and insistent</u>"]', '<b>Vehement</b> = <b>strong and insistent</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0b9a9fbc-17bf-4903-8523-11790a38d3bf', 'Christian Religious Studies', 'JAMB', null, 2026, null, '''Have nothing to do with that righteous man, for I have suffered much over him today in a dream.'' This statement was made by Pilate''s wife during', null, '["the arrest of Jesus","Jesus'' betrayal","Jesus'' trial","Jesus'' crucifixion"]', 2, 'Pilate''s wife made this statement during Jesus'' trial. She sent a message to Pilate while he was sitting on the judgment seat, saying, ''Have nothing to do with that righteous man, for I have suffered much over him today in a dream.''', true, '2026-09-12 09:46:05.764', '2026-09-12 09:46:05.764', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0bb21bae-d396-4eaa-848b-cc5878f9cf8f', 'Literature in English', 'JAMB', null, 2026, null, 'A story written in form of poetry is called what?', null, '["lyric","narrative poem","elegy","ode"]', 1, 'A story written in the form of poetry is called a narrative poem. Narrative poems tell a story and include characters, plot, and setting. Examples include epics like Homer''s "Odyssey" and ballads. A lyric poem expresses personal emotions, an elegy is a mournful poem for the dead, and an ode is a poem of praise. Narrative poetry combines storytelling with poetic form.', true, '2026-09-10 10:45:34.128', '2026-09-10 10:45:34.128', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0bb8b70b-089f-4d1e-a0a8-4de2bd5caa52', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The thieves <u>vandalized</u> the vault''s lock.', null, '["repaired","arranged","serviced","actuated"]', 0, 'Vandalized = destroyed; opposite = repaired.', true, '2026-10-24 07:21:12.75', '2026-10-24 07:21:12.75', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The thieves <u>vandalized</u> the vault''s lock.', '["repaired","arranged","serviced","actuated"]', 'Vandalized = destroyed; opposite = repaired.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0bbab3d1-4430-4db5-88de-b0e962a372c3', 'Economics', 'JAMB', null, 2026, null, '______ is a quantity which assumes different values that may be measured or counted in some numerical units', null, '["Constant term","variables","Coefficient","Functions"]', 1, 'A variable is a quantity that can assume different values.', true, '2026-09-12 11:00:52.749', '2026-09-12 11:00:52.749', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0bbfbe13-b9fb-4090-9739-e33ab1517883', 'Biology', 'JAMB', null, 2001, null, 'A green snake in green grass is able to escape notice from predators because of its', null, '["warning colouration","disruptive colouration","cryptic colouration","countershading"]', 2, 'Cryptic colouration allows the snake to blend with its environment.', true, '2026-10-12 20:59:29.778', '2026-10-12 20:59:29.778', null, null, null, 'A green snake in green grass is able to escape notice from predators because of its', '["warning colouration","disruptive colouration","cryptic colouration","countershading"]', 'Cryptic colouration allows the snake to blend with its environment.', '{"bold":["Cryptic colouration"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0bc35837-a01d-4068-b7ec-1862fd9daa52', 'Government', 'JAMB', null, 2026, null, 'A system of government where political powers are inherited is called', null, '["Monarchy","Diary","Democracy","Aristocracy"]', 0, 'Monarchy is a system where political powers are inherited.', true, '2026-09-12 11:24:20.153', '2026-09-12 11:24:20.153', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0bc65c4f-06d0-4fff-a84e-f11c95391124', 'Literature in English', 'JAMB', null, 2026, null, 'The expression ''colo'' means', null, '["prim and proper","out of date","in-fashion","outside of brain"]', 1, '''Colo'' means out of date.', true, '2026-09-12 11:05:35.368', '2026-09-12 11:05:35.368', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0bcdb0e4-2fdb-46c6-be7e-c548066178a3', 'Chemistry', 'JAMB', null, 2026, null, 'The radioactive element with the least ionization power is?', null, '["Beta-particles","Alpha-particles","X-rays","Gamma-rays"]', 3, 'Gamma rays have the least ionizing power.', true, '2026-09-12 11:36:20.424', '2026-09-12 11:36:20.424', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0bd321c7-13de-47c6-af01-7b812983c23c', 'English Language', 'JAMB', null, 2024, null, 'Graduates find it difficult to secure ______ nowadays', null, '["an employment","employment","employments","few employments"]', 1, '"Employment" is an uncountable noun.', true, '2026-09-18 09:43:02.566', '2026-09-18 09:43:02.566', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0bdaa718-71ce-479e-bd0b-6255b7f112c4', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). ''<u>To beat down the price</u>'' is to _____________', null, '["flog the price","reduce the price","beat the salesman","attack the seller","control the price"]', 1, '''Beat down the price'' means negotiate lower.', true, '2026-10-24 01:02:00.825', '2026-10-24 01:02:00.825', null, null, null, '(Choose the most appropriate interpretation). ''<u>To beat down the price</u>'' is to _____________', '["flog the price","<u>reduce the price</u>","beat the salesman","attack the seller","control the price"]', '''<b>Beat down the price</b>'' means <b>negotiate lower</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0be1e60c-546a-4522-bc77-e749a781cdee', 'Literature in English', 'JAMB', null, 2026, null, 'The cultural practices depicted in the novel serve mainly to', null, '["entertain the reader with folklore","criticize modern religion","highlight the importance of heritage and communal values","promote superstition"]', 2, 'They highlight the importance of heritage and communal values.', true, '2026-09-12 11:09:48.752', '2026-09-12 11:09:48.752', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0beb004e-02a8-4b78-a265-e97e0d79df85', 'Physics', 'JAMB', null, 1991, null, 'What is the difference in the amount of heat given out by 4 kg of steam and 4 kg of water when both are cooled from 100 °C to 80 °C? [The specific latent heat of steam is 2,260,000 J kg⁻¹, specific heat capacity of water is 4200 J kg⁻¹ K⁻¹]', null, '["4,200 J","2,260,000 J","9,040,000 J","9,380,000 J"]', 2, 'Both lose the same sensible heat cooling from 100 °C to 80 °C. The steam additionally releases latent heat on condensing: 4 x 2,260,000 = 9,040,000 J.', true, '2026-10-12 19:15:33.137', '2026-10-12 19:15:33.137', null, null, null, 'What is the difference in the amount of heat given out by 4 kg of steam and 4 kg of water when both are cooled from 100 °C to 80 °C? [The specific latent heat of steam is 2,260,000 J kg<sup>-1</sup>, specific heat capacity of water is 4200 J kg<sup>-1</sup> K<sup>-1</sup>]', '["4,200 J","2,260,000 J","9,040,000 J","9,380,000 J"]', 'Both lose the same sensible heat cooling from 100 °C to 80 °C. The steam additionally releases latent heat on condensing: 4 x 2,260,000 = 9,040,000 J.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0bf27574-432b-4f7d-bc05-403c62aa7724', 'Physics', 'JAMB', null, 2003, null, 'A wire of 5 ohms resistance is drawn out so that its new length is two times the original length. If the resistivity of the wire remains the same and the cross-sectional area is halved, the new resistance is', null, '["20 Ω","5 Ω","40 Ω","10 Ω"]', 0, 'R = ρL/A. New R = ρ(2L)/(A/2) = 4 x 5 = 20 Ω.', true, '2026-10-12 19:15:56.516', '2026-10-12 19:15:56.516', null, null, null, 'A wire of 5 ohms resistance is drawn out so that its new length is two times the original length. If the resistivity of the wire remains the same and the cross-sectional area is halved, the new resistance is', '["20 Ω","5 Ω","40 Ω","10 Ω"]', 'R = ρL/A. New R = ρ(2L)/(A/2) = 4 x 5 = 20 Ω.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0c1a544e-5ee6-4b78-9fb5-77ca00df26fc', 'General Mathematics', 'JAMB', null, 2026, null, 'Find the value of m if 13ₘ + 24ₘ = 41ₘ', null, '["8","6","5","2"]', 2, '13ₘ = m + 3. 24ₘ = 2m + 4. 41ₘ = 4m + 1. So (m+3) + (2m+4) = 4m+1. 3m + 7 = 4m + 1. m = 6. But 6 is not in the options? Option (B) is 6. So m = 6.', true, '2026-09-10 10:48:19.292', '2026-09-10 10:48:19.292', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0c2a2dae-4dca-461d-b4fa-028e03bc9af7', 'Biology', 'JAMB', null, 2001, null, 'The veins of the leaf are formed by the', null, '["spongy mesophyll","palisade tissue","cambium cells","vascular bundles"]', 3, 'Leaf veins consist of xylem and phloem tissues grouped together as vascular bundles for transport and support.', true, '2026-10-12 20:05:08.853', '2026-10-12 20:05:08.853', null, null, null, 'The veins of the leaf are formed by the', '["spongy mesophyll","palisade tissue","cambium cells","vascular bundles"]', 'Leaf veins consist of xylem and phloem tissues grouped together as vascular bundles for transport and support.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0c37a831-f10a-4ece-a34e-3e4a03a68761', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The doctor examined the patient <u>painstakingly</u>.', null, '["perfunctorily","professionally","painfully","carefully"]', 0, 'Painstakingly = carefully; opposite = perfunctorily.', true, '2026-10-24 07:21:24.326', '2026-10-24 07:21:24.326', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The doctor examined the patient <u>painstakingly</u>.', '["perfunctorily","professionally","painfully","carefully"]', 'Painstakingly = carefully; opposite = perfunctorily.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0c3cafa6-679b-4970-8766-9f4b0a8292b0', 'Chemistry', 'JAMB', null, 2026, null, 'Which of the following aqueous solutions are neutral to litmus', null, '["NH₄Cl","Na₂CO₃","FeCl₃","NaCl"]', 3, 'NaCl is neutral to litmus.', true, '2026-09-12 11:36:01.375', '2026-09-12 11:36:01.375', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0c477036-e49f-417a-a569-2e780528c149', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). The family discussed the crisis and resolved to <u>nail the lie to the counter</u>.', null, '["expose it publicly","bury it...","defer action on it","seek more advice"]', 0, '''Nail a lie to the counter'' = expose publicly.', true, '2026-10-24 01:02:08.869', '2026-10-24 01:02:08.869', null, null, null, '(Choose the most appropriate interpretation). The family discussed the crisis and resolved to <u>nail the lie to the counter</u>.', '["<u>expose it publicly</u>","bury it...","defer action on it","seek more advice"]', '''<b>Nail a lie to the counter</b>'' = <b>expose publicly</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0c4d4be7-736c-4c24-b1de-dabc250f38b8', 'Chemistry', 'JAMB', null, 2026, null, 'Which of the following compounds is expected to have the highest boiling point and why?', null, '["CH₄ — due to strong dispersion forces","NH₃ — due to hydrogen bonding","HCl — due to dipole-dipole attraction","CO₂ — due to large molecular size"]', 1, 'Ammonia forms strong hydrogen bonds between molecules due to the highly electronegative nitrogen atom, giving it the highest boiling point among these.', true, '2026-09-09 17:12:48.054', '2026-09-09 17:12:48.054', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0c9edeac-eb33-4c8c-bc67-4924fe9573ce', 'Literature in English', 'JAMB', null, 2026, null, 'A common thematic link between Digging and Still I Rise is', null, '["The rejection of history","The inevitability of death","The importance of romantic love","The celebration of identity and personal strength"]', 3, 'Both poems celebrate identity and personal strength.', true, '2026-09-12 11:05:16.334', '2026-09-12 11:05:16.334', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0ca7d5c4-c7bb-4c04-a6cb-b474f9cec246', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). Adamu woke up with a start and took to his heels, claiming that something was <u>on his trial</u>.', null, '["in his food","giving him the chase","hiding near the bed","staring at him"]', 1, '''On his trail'' = chasing him.', true, '2026-10-24 01:02:08.659', '2026-10-24 01:02:08.659', null, null, null, '(Choose the most appropriate interpretation). Adamu woke up with a start and took to his heels, claiming that something was <u>on his trial</u>.', '["in his food","<u>giving him the chase</u>","hiding near the bed","staring at him"]', '''<b>On his trail</b>'' = <b>chasing him</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0caaea1e-9fae-46aa-a637-2d7cfa8358ff', 'Literature in English', 'JAMB', null, 2026, null, '''Genres of literature'' aptly discusses', null, '["tragedy, comedy and tragic-comedy","Poem, ballad and picaresque","prose, drama and poetry","romance, Shakespearean drama and epitaph"]', 2, 'Genres of literature are prose, drama, and poetry.', true, '2026-09-12 11:06:26.973', '2026-09-12 11:06:26.973', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0cb5b257-f0a3-4e5c-b0dc-a5533ddd54d0', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Darkness was not created during creation because', null, '["the earth was full of water","God''s spirit was over the waters","darkness was already in existence","God wanted to have day and night"]', 2, 'Darkness was not created during creation because it was already in existence. Genesis 1:2 states, ''The earth was without form and void, and darkness was upon the face of the deep.'' God created light and separated it from darkness.', true, '2026-09-12 09:45:57.441', '2026-09-12 09:45:57.441', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0cbd7f1a-c410-4825-9d14-b1e26bf78f85', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The man preaches <u>egalitarianism</u> without matching it up with action.', null, '["salvation","dedication","kindness","equality"]', 3, 'Egalitarianism = equality.', true, '2026-10-24 01:04:01.674', '2026-10-24 01:04:01.674', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The man preaches <u>egalitarianism</u> without matching it up with action.', '["salvation","dedication","kindness","<u>equality</u>"]', '<b>Egalitarianism</b> = <b>equality</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0cbe0b07-f496-4ff1-b4da-629b8e92a778', 'Physics', 'JAMB', null, 1985, null, 'A metal cube of volume 10³ mm³ is lowered into a measuring cylinder containing water. If the internal cross-sectional area of the cylinder is 1.5 x 10² mm², by how much does the water level rise in the cylinder?', null, '["6.67 x 10⁰ mm","8.50 x 10² mm","1.15 x 10³ mm","2.50 x 10³ mm","1.50 x 10⁵ mm"]', 0, 'Rise in level = volume/area = 10³/(1.5 x 10²) = 6.67 mm.', true, '2026-10-12 19:15:21.148', '2026-10-12 19:15:21.148', null, null, null, 'A metal cube of volume 10<sup>3</sup> mm<sup>3</sup> is lowered into a measuring cylinder containing water. If the internal cross-sectional area of the cylinder is 1.5 x 10<sup>2</sup> mm<sup>2</sup>, by how much does the water level rise in the cylinder?', '["6.67 x 10<sup>0</sup> mm","8.50 x 10<sup>2</sup> mm","1.15 x 10<sup>3</sup> mm","2.50 x 10<sup>3</sup> mm","1.50 x 10<sup>5</sup> mm"]', 'Rise in level = volume/area = 10<sup>3</sup>/(1.5 x 10<sup>2</sup>) = 6.67 mm.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0cbf51f8-667d-4150-aa4e-ce9ac05b32fa', 'English Language', 'JAMB', null, 2007, null, 'My little daughter has <u>__________</u> sight, hence, she now wears glasses', null, '["diminutive","blurred","painful","defective"]', 3, 'Correct spelling: defective.', true, '2026-10-24 07:21:41.132', '2026-10-24 07:21:41.132', null, null, null, 'My little daughter has <u>__________</u> sight, hence, she now wears glasses', '["diminutive","blurred","painful","defective"]', 'Correct spelling: defective.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0cc53834-42df-4f61-83c1-f94412967d1e', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The boys knew that a storm was <u>imminent</u>.', null, '["possible","impending","threatening","encroaching"]', 1, 'Imminent = impending.', true, '2026-10-24 01:01:52.303', '2026-10-24 01:01:52.303', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The boys knew that a storm was <u>imminent</u>.', '["possible","<u>impending</u>","threatening","encroaching"]', '<b>Imminent</b> = <b>impending</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0cc7fa18-8f4f-485d-b677-4e8d03899f51', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Who was the man full of the Spirit and wisdom appointed to serve tables?', null, '["Stephen","Paul","John","Silas"]', 0, 'Stephen was one of the seven men full of the Spirit and wisdom appointed to serve tables (distribute food to widows) in the early church. He later became the first Christian martyr.', true, '2026-09-12 09:45:50.938', '2026-09-12 09:45:50.938', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0cc93f89-c539-426f-b527-a15c649e6fd2', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The officer asked for a more <u>temperate</u> assessment of the matter.', null, '["extreme","moderate","radical","human"]', 0, 'Temperate = moderate; opposite = extreme.', true, '2026-10-24 07:21:20.199', '2026-10-24 07:21:20.199', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The officer asked for a more <u>temperate</u> assessment of the matter.', '["extreme","moderate","radical","human"]', 'Temperate = moderate; opposite = extreme.', '{}');
