insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0cd0554b-1afa-49e8-b6b3-f2198ee09896', 'Physics', 'JAMB', null, 1991, null, 'To convert an alternating current dynamo into a direct current dynamo, the', null, '["Number of turns in the coil is increased","Strength of the field magnet is increased","Slip rings are replaced with a split ring commutator","Coil is wound on a soft iron armature."]', 2, 'A split-ring commutator reverses the connections every half turn, so the output current in the external circuit is in one direction only.', true, '2026-10-12 19:15:34.267', '2026-10-12 19:15:34.267', null, null, null, 'To convert an alternating current dynamo into a direct current dynamo, the', '["Number of turns in the coil is increased","Strength of the field magnet is increased","Slip rings are replaced with a split ring commutator","Coil is wound on a soft iron armature."]', 'A split-ring commutator reverses the connections every half turn, so the output current in the external circuit is in one direction only.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0cd3fd11-93a8-4ef8-8114-9aad9d837a29', 'Biology', 'JAMB', null, 2026, null, 'In amoeba osmoregulation is carried out by the', null, '["pseudopodium","food vacuole","contractile vacuole","nucleus"]', 2, 'In amoeba, osmoregulation is carried out by the contractile vacuole. Contractile vacuoles collect excess water that enters the cell by osmosis and expel it to the outside. Pseudopodia are used for movement and feeding. Food vacuoles are for digestion. The nucleus controls cellular activities. Freshwater amoebas live in hypotonic environments where water constantly enters the cell, making the contractile vacuole essential for survival.', true, '2026-09-09 03:19:10.753', '2026-09-09 03:19:10.753', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0ce8ea85-bc7d-45a9-8e24-ce2ebdb483b6', 'Chemistry', 'JAMB', null, 2026, null, 'Which of the following is an ester?', null, '["CH₃COOH","CH₃COOCH₃","CH₃OH","CH₄"]', 1, 'CH₃COOCH₃ (methyl ethanoate) is an ester.', true, '2026-09-12 11:35:58.256', '2026-09-12 11:35:58.256', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0cf42cd5-c7d6-4e6d-a67e-005b2c8bf2d8', 'Government', 'JAMB', null, 2026, null, 'Which organs of government is responsible for ratifying treaties in Nigeria?', null, '["National Assembly","Executive","Judiciary","Minister of Foreign Affairs"]', 0, 'The National Assembly ratifies treaties in Nigeria.', true, '2026-09-12 11:24:45.248', '2026-09-12 11:24:45.248', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0cf8fabd-50b0-49f9-9041-c1dc443b6b11', 'Economics', 'JAMB', null, 2026, null, 'If an increase in the price of good X leads to an increase in the supply of good Y, X and Y are said to be', null, '["competitive","jointly supplied","composite","jointly demanded"]', 0, 'Goods that compete for the same resources in production are competitively supplied.', true, '2026-09-12 11:01:05.766', '2026-09-12 11:01:05.766', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0cfd5658-a742-438a-a9c9-68194d47a03b', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. You have been asked to change your <u>laissez-faire</u> attitude to work.', null, '["stupid","carefree","careful","serious","responsible"]', 1, 'Laissez-faire = carefree.', true, '2026-10-24 01:03:54.028', '2026-10-24 01:03:54.028', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. You have been asked to change your <u>laissez-faire</u> attitude to work.', '["stupid","<u>carefree</u>","careful","serious","responsible"]', '<b>Laissez-faire</b> = <b>carefree</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0cfd6782-7a37-426b-9388-3416b3628037', 'General Mathematics', 'JAMB', null, 2026, null, 'If f(x) = 2x² - 5x + 3, find f(x + 1)', null, '["2x² - x + 10","2x² - x","4x² + 3x + 2","4x² + 3x + 12","5x² + 55"]', 1, 'f(x+1) = 2(x+1)² - 5(x+1) + 3 = 2x²+4x+2 - 5x-5 + 3 = 2x² - x.', true, '2026-09-12 11:44:00.92', '2026-09-12 11:44:00.92', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0d04eecc-2e27-4daa-beae-d3ef68d46948', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Moses asked Pharaoh to allow the Hebrews to depart from Egypt to', null, '["buy more food in the land of Canaan","fight the Jebusites","smite the Amorites","make a sacrifice to the Lord in the wilderness"]', 3, 'Moses asked Pharaoh to allow the Hebrews to go into the wilderness to make a sacrifice to the Lord. This was the initial request, although God''s ultimate purpose was to deliver them from Egypt entirely.', true, '2026-09-12 09:45:59.823', '2026-09-12 09:45:59.823', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0d12aeb7-461b-4bc3-a763-5bdae0f2cce7', 'Biology', 'JAMB', null, 2002, null, 'An amoeba and an unlaid chicken egg are', null, '["animal tissues","organelles","single cells","organisms"]', 2, 'Both an Amoeba and an unlaid chicken egg exist as individual, single cells capable of independent existence.', true, '2026-10-12 20:05:08.902', '2026-10-12 20:05:08.902', null, null, null, 'An amoeba and an unlaid chicken egg are', '["animal tissues","organelles","single cells","organisms"]', 'Both an Amoeba and an unlaid chicken egg exist as individual, single cells capable of independent existence.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0d15f890-c8e4-42d8-a93d-6d97c07ba3d0', 'Physics', 'JAMB', null, 1998, null, 'A bullet fired at a wooden block of thickness 0.15 m manages to penetrate the block. If the mass of the bullet is 0.025 kg and the average resisting force of the wood is 7.5 x 10³ N, calculate the speed of the bullet just before it hits the wooden block.', null, '["450 m s⁻¹","400 m s⁻¹","300 m s⁻¹","250 m s⁻¹"]', 2, 'Work done against resistance = kinetic energy lost: 7.5 x 10³ x 0.15 = ½ x 0.025 x v², so v² = 90 000 and v = 300 m s⁻¹.', true, '2026-10-12 19:15:44.978', '2026-10-12 19:15:44.978', null, null, null, 'A bullet fired at a wooden block of thickness 0.15 m manages to penetrate the block. If the mass of the bullet is 0.025 kg and the average resisting force of the wood is 7.5 x 10<sup>3</sup> N, calculate the speed of the bullet just before it hits the wooden block.', '["450 m s<sup>-1</sup>","400 m s<sup>-1</sup>","300 m s<sup>-1</sup>","250 m s<sup>-1</sup>"]', 'Work done against resistance = kinetic energy lost: 7.5 x 10<sup>3</sup> x 0.15 = ½ x 0.025 x v<sup>2</sup>, so v<sup>2</sup> = 90 000 and v = 300 m s<sup>-1</sup>.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0d20c1e5-10b5-4b5c-8447-fbf0ea12cace', 'Christian Religious Studies', 'JAMB', null, 2026, null, '''Son of man, stand upon your feet, and I will speak with you''. The statement above was made during the call of...', null, '["Isaiah","Hosea","Samuel","Ezekiel"]', 3, 'Ezekiel 2:1-2 records God addressing Ezekiel with ''Son of man, stand on your feet, and I will speak to you.''', true, '2026-09-09 17:18:27.059', '2026-09-09 17:18:27.059', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0d2e540c-d4d9-4d12-8afd-ef3dd1a15e71', 'Biology', 'JAMB', null, 2003, null, 'Organisms I, II, III, IV have surface/volume ratio of 1:2, 1:3, 1:4 and 1:5 respectively. The organism that is likely to have the most complex transport system is', null, '["IV","III","I","II"]', 0, 'Organism IV with the smallest surface/volume ratio needs the most complex transport system.', true, '2026-10-12 20:59:32.775', '2026-10-12 20:59:32.775', null, null, null, 'Organisms I, II, III, IV have surface/volume ratio of 1:2, 1:3, 1:4 and 1:5 respectively. The organism that is likely to have the most complex transport system is', '["IV","III","I","II"]', 'Organism IV with the smallest surface/volume ratio needs the most complex transport system.', '{"bold":["IV"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0d2f0753-05a8-4407-b475-42a04c191cf0', 'Chemistry', 'JAMB', null, 2026, null, 'The air around a petroleum refinery is most likely to contain', null, '["CO2, SO3 and N2O","CO2, CO and N2O","SO2, CO and NO2","PH3, H2O and CO"]', 2, 'Petroleum processing and combustion emit sulfur dioxide (SO2), carbon monoxide (CO), and nitrogen dioxide (NO2) as gaseous pollutants.', true, '2026-09-09 17:12:46.748', '2026-09-09 17:12:46.748', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0d559b4c-e8e7-4a06-af8d-a44c6a0483bd', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The lamp shades were <u>translucent</u>', null, '["opaque","intersected","luminous","transparent"]', 0, 'Translucent = semi-transparent; opposite = opaque.', true, '2026-10-24 07:21:31.737', '2026-10-24 07:21:31.737', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The lamp shades were <u>translucent</u>', '["opaque","intersected","luminous","transparent"]', 'Translucent = semi-transparent; opposite = opaque.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0d69c844-340a-4c22-b0fc-4aae420af493', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Things may change soon, but our economic situation is <u>grim</u>.', null, '["uncertain","unattractive","redeemable","buoyant"]', 1, 'Grim = unattractive.', true, '2026-10-24 01:04:09.607', '2026-10-24 01:04:09.607', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Things may change soon, but our economic situation is <u>grim</u>.', '["uncertain","<u>unattractive</u>","redeemable","buoyant"]', '<b>Grim</b> = <b>unattractive</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0d7187a6-d56e-4ab3-9103-5b7cbf3e3fd0', 'Economics', 'JAMB', null, 2026, null, 'Given 6, 4, 8, 6, 4 and 2, the absolute mean deviation is', null, '["0.67","30.0","1.67","6.00"]', 2, 'The absolute mean deviation is 1.67. First, find the mean: (6+4+8+6+4+2)/6 = 30/6 = 5. Then find the absolute deviations from the mean: |6-5|=1, |4-5|=1, |8-5|=3, |6-5|=1, |4-5|=1, |2-5|=3. Sum of absolute deviations = 1+1+3+1+1+3 = 10. Mean deviation = 10/6 = 1.67.', true, '2026-09-10 10:41:59.484', '2026-09-10 10:41:59.484', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0d724f1a-6304-43aa-bb65-c5e2e19497b3', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). Olu gave his brother <u>a bumpy ride</u>', null, '["Olu''s brother rode on Olu''s back to success","Olu took his brother on a bumpy road","Olu gave his brother a difficult time","Olu gave his brother a ride in his car"]', 2, '''A bumpy ride'' = difficult time.', true, '2026-10-24 01:02:11.215', '2026-10-24 01:02:11.215', null, null, null, '(Choose the most appropriate interpretation). Olu gave his brother <u>a bumpy ride</u>', '["Olu''s brother rode on Olu''s back to success","Olu took his brother on a bumpy road","<u>Olu gave his brother a difficult time</u>","Olu gave his brother a ride in his car"]', '''A <b>bumpy ride</b>'' = <b>difficult time</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0d733970-ff9d-43e5-8e92-d9a86c0424c1', 'Biology', 'JAMB', null, 2026, null, 'The aperture between the left auricle and left ventricle is guarded by the', null, '["auricular valve","tricuspid valve","semi lunar valve","mitral valve"]', 3, 'The mitral valve (also called the bicuspid valve) is the valve between the left atrium (auricle) and left ventricle. It consists of two flaps and prevents backflow of blood from the ventricle to the atrium. The tricuspid valve is between the right atrium and right ventricle. The semilunar valves are located at the exits of the ventricles (pulmonary and aortic valves). Auricular valve is not a standard term. The mitral valve ensures unidirectional flow of oxygenated blood from the left atrium to the left ventricle during the cardiac cycle.', true, '2026-09-09 03:18:44.827', '2026-09-09 03:18:44.827', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0d8bd9d2-f281-43d5-a521-d31fc72cec10', 'English Language', 'JAMB', null, 2024, null, 'Choose the word that contains the sound represented by the given phonetic symbol: /ʌ/', null, '["cough","lock","clerk","tough"]', 3, '"Tough" contains the /ʌ/ sound.', true, '2026-09-18 09:43:02.877', '2026-09-18 09:43:02.877', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0dad60ba-0fd8-41bc-b93a-2742a81ecb6b', 'English Language', 'JAMB', null, 2024, null, 'The expression "work their way out of their situation" means', null, '["walk from village to another","migrate from village to city","work their way out of the village","change their circumstances"]', 3, 'The phrase means to improve one''s circumstances or escape poverty through work, not literal walking or migration.', true, '2026-09-18 09:23:08.206', '2026-09-18 09:23:08.206', null, null, 'COMPREHENSION', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0db3d522-3c1d-4cea-9712-ee2018fde16f', 'Literature in English', 'JAMB', null, 2026, null, 'The reference to "Darwin''s examination of turtle''s shit" serves to', null, '["introduce a humorous element","allude to scientific exploration and observation","Criticize Darwin''s theories","provide an example of marine biology"]', 1, 'The reference to "Darwin''s examination of turtle''s shit" serves to allude to scientific exploration and observation. It references Charles Darwin''s meticulous scientific methods, including the examination of various specimens to understand evolution and natural history. The allusion highlights the poem''s engagement with scientific inquiry and the quest for knowledge.', true, '2026-09-10 10:47:54.56', '2026-09-10 10:47:54.56', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0db837e9-44d9-43e6-85f9-309f12685f1f', 'English Language', 'JAMB', null, 2024, null, 'He devoted himself ______ homeless children.', null, '["To help","To helping","By helping","With helping"]', 1, '"Devote oneself to" is followed by a gerund: "to helping."', true, '2026-09-18 09:24:04.756', '2026-09-18 09:24:04.756', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0db8de0c-ae8a-4805-a6f3-5e4f5632de45', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. He walks in a <u>gawky</u> way', null, '["suitable","clumsy","lumbering","graceful"]', 3, 'Gawky = clumsy; opposite = graceful.', true, '2026-10-24 07:21:30.774', '2026-10-24 07:21:30.774', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. He walks in a <u>gawky</u> way', '["suitable","clumsy","lumbering","graceful"]', 'Gawky = clumsy; opposite = graceful.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0dbbe6e2-3406-41e5-9235-537b0e4604cb', 'General Mathematics', 'JAMB', null, 2026, null, 'Find the equation of a line perpendicular to line 2y = 5x + 4 which passes through (4,2)', null, '["5y - 2x - 18 = 0","5y + 2x - 18 = 0","5y - 2x + 18 = 0","5y + 2x - 2 = 0"]', 1, '2y = 5x+4 → y = 2.5x+2. Perpendicular slope = -2/5. y-2 = -2/5(x-4). 5y-10 = -2x+8. 5y+2x-18 = 0.', true, '2026-09-12 11:44:25.531', '2026-09-12 11:44:25.531', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0dcb633e-13b5-4e8e-8162-998c47696e63', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The officer was given <u>an invidious</u> task.', null, '["a pleasant","a difficult","a vivid","a cruel"]', 0, 'Invidious = unpleasant; opposite = pleasant.', true, '2026-10-24 07:21:25.984', '2026-10-24 07:21:25.984', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The officer was given <u>an invidious</u> task.', '["a pleasant","a difficult","a vivid","a cruel"]', 'Invidious = unpleasant; opposite = pleasant.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0dcc7209-b9e7-4505-ba3e-7e5dad9f2f24', 'Physics', 'JAMB', null, 1989, null, 'Which of the following devices are used to measure pressure?
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0dd61c87-2dac-491f-981b-16cdbe4e69d2', 'General Mathematics', 'JAMB', null, 2026, null, 'Find the sum of 25₆, 52₆ and 43₆ in base 8', null, '["411","141","114","417"]', 1, '25₆ = 2(6)+5 = 17. 52₆ = 5(6)+2 = 32. 43₆ = 4(6)+3 = 27. Sum = 17+32+27 = 76. Convert 76 to base 8: 76/8 = 9 remainder 4, 9/8 = 1 remainder 1, 1/8 = 0 remainder 1. So 76 = 114₈. The answer is (C) 114.', true, '2026-09-10 10:48:19.341', '2026-09-10 10:48:19.341', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0dd867ab-f1b9-4f15-b6d4-24500677c9f7', 'Physics', 'JAMB', null, 2026, null, 'Which conversion chain is most appropriate for a generator?', null, '["Electric → mechanical → sound","Chemical → mechanical → kinetic","Kinetic → sound","electric → chemical → sound"]', 1, 'A generator converts mechanical energy (kinetic) into electrical energy. The most appropriate chain from the options is chemical → mechanical → kinetic (if we consider fuel as the initial source) or simply kinetic → electrical. The closest option is B.', true, '2026-09-10 10:56:43.901', '2026-09-10 10:56:43.901', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0de21c70-5bd9-4293-a742-e8bc59dab9e1', 'Physics', 'JAMB', null, 1987, null, 'A load of 5 N gives an extension of 0.56 cm in a wire which obeys Hooke''s law. What is the extension caused by a load of 20 N?', null, '["1.12 cm","2.14 cm","2.24 cm","2.52 cm."]', 2, 'Extension is proportional to load: 0.56 x (20/5) = 2.24 cm.', true, '2026-10-12 19:15:25.095', '2026-10-12 19:15:25.095', null, null, null, 'A load of 5 N gives an extension of 0.56 cm in a wire which obeys Hooke''s law. What is the extension caused by a load of 20 N?', '["1.12 cm","2.14 cm","2.24 cm","2.52 cm."]', 'Extension is proportional to load: 0.56 x (20/5) = 2.24 cm.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0df30766-ba6b-40a9-9d0c-dfc9c28021c1', 'Physics', 'JAMB', null, 1989, null, 'A far sighted person cannot see objects that are less than 100 cm away. If this person wants to read a book at 25 cm, what type and focal length of lens does he need?', null, '["Convex, 20 cm","Concave, 20 cm","Convex, 33 cm","Concave, 33 cm."]', 2, 'The lens must form a virtual image at 100 cm of an object at 25 cm: 1/f = 1/25 - 1/100 = 3/100, so f = 33 cm. It is a convex (converging) lens.', true, '2026-10-12 19:15:29.522', '2026-10-12 19:15:29.522', null, null, null, 'A far sighted person cannot see objects that are less than 100 cm away. If this person wants to read a book at 25 cm, what type and focal length of lens does he need?', '["Convex, 20 cm","Concave, 20 cm","Convex, 33 cm","Concave, 33 cm."]', 'The lens must form a virtual image at 100 cm of an object at 25 cm: 1/f = 1/25 - 1/100 = 3/100, so f = 33 cm. It is a convex (converging) lens.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0e00bc01-56a4-440d-b6f1-dc7f52c1b9a3', 'Government', 'JAMB', null, 2026, null, 'A cardinal feature of a rigid constitution is that it', null, '["Can only be amended by the judiciary","Requires a special procedure for its amendment","Requires two-thirds majority for its amendment","Requires the votes of the electorate for its amendment"]', 1, 'A rigid constitution requires a special procedure for amendment.', true, '2026-09-12 11:24:20.371', '2026-09-12 11:24:20.371', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0e097fd2-0c5c-4bf1-8ce7-a8e7dc9ceb0f', 'Biology', 'JAMB', null, 2011, null, 'Exo-erythrocytic phase of the life cycle of malaria parasite occurs in the', null, '["Liver of humans","reticuloendothelial cells of humans","malpighian tubules of mosquito","brain of humans."]', 0, 'The exo-erythrocytic phase occurs in the liver of humans.', true, '2026-10-12 20:59:43.22', '2026-10-12 20:59:43.22', null, null, null, 'Exo-erythrocytic phase of the life cycle of malaria parasite occurs in the', '["Liver of humans","reticuloendothelial cells of humans","malpighian tubules of mosquito","brain of humans."]', 'The exo-erythrocytic phase occurs in the liver of humans.', '{"bold":["liver of humans"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0e123874-966a-4918-926c-feb58be3feed', 'Biology', 'JAMB', null, 2026, null, 'When two heterozygous individuals are crossed, the dominant trait will appear in', null, '["the F1 generation","the F2 generation","both the F1 and F2 generations","neither the F1 nor F2 generation"]', 1, 'When two heterozygous individuals are crossed (Tt × Tt), the dominant trait will appear in the F2 generation. The F1 generation results from crossing true-breeding parents (TT × tt), producing all heterozygous (Tt) offspring. The F2 generation is produced by crossing two heterozygous individuals, resulting in a 3:1 phenotype ratio (dominant : recessive). Dominant and recessive traits both appear in the F2 generation. The F1 generation would show only the dominant trait.', true, '2026-09-09 03:19:17.695', '2026-09-09 03:19:17.695', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0e206079-ffa1-4968-a32d-132923bc6751', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The first round of the tournament was <u>a doddle</u>', null, '["easy","balanced","dodgy","exasperating"]', 0, 'A doddle = easy.', true, '2026-10-24 01:04:12.294', '2026-10-24 01:04:12.294', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The first round of the tournament was <u>a doddle</u>', '["<u>easy</u>","balanced","dodgy","exasperating"]', 'A <b>doddle</b> = <b>easy</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0e29f2d4-6a13-4f73-a6e5-1c162ed56455', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). The man who gave the closing remarks at the party spoke <u>tongue-in-cheek</u>.', null, '["ironically","wisely","profusely","eloquently"]', 0, '''Tongue-in-cheek'' = ironically/not seriously.', true, '2026-10-24 01:04:21.308', '2026-10-24 01:04:21.308', null, null, null, '(Choose the most appropriate interpretation). The man who gave the closing remarks at the party spoke <u>tongue-in-cheek</u>.', '["<u>ironically</u>","wisely","profusely","eloquently"]', '''<b>Tongue-in-cheek</b>'' = <b>ironically/not seriously</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0e2ad6b0-f4e0-45ec-a70a-1866613a22e2', 'Chemistry', 'JAMB', null, 2026, null, 'Which indicator is best for strong acid-strong base titration?', null, '["Methyl orange","Phenolphthalein","Litmus","Universal indicator"]', 1, 'Phenolphthalein is best for strong acid-strong base titration.', true, '2026-09-12 11:33:00.717', '2026-09-12 11:33:00.717', null, null, null, null, null, null, null);
