insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0e39ed65-74c0-46d1-b7ae-1f1ce560c579', 'Biology', 'JAMB', null, 2004, null, 'The two key cations involved in the action potential of nervous transmissions are', null, '["Na+ and Fe2+","Mg2+ and K+","Na+ and K+","Fe2+ and Mg2+"]', 2, 'Sodium and potassium ions drive action potentials.', true, '2026-10-12 20:59:35.324', '2026-10-12 20:59:35.324', null, null, null, 'The two key cations involved in the action potential of nervous transmissions are', '["Na+ and Fe2+","Mg2+ and K+","Na+ and K+","Fe2+ and Mg2+"]', 'Sodium and potassium ions drive action potentials.', '{"bold":["Sodium and potassium ions"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0e4133ab-d02c-4421-9aad-af8b93b19d9d', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Travelling in the night can be <u>an ordeal</u>.', null, '["a great exercise","a great fear","a great endurance","moderation"]', 3, 'An ordeal = a trying experience; closest opposite = moderation.', true, '2026-10-24 07:21:18.361', '2026-10-24 07:21:18.361', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Travelling in the night can be <u>an ordeal</u>.', '["a great exercise","a great fear","a great endurance","moderation"]', 'An ordeal = a trying experience; closest opposite = moderation.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0e4ab476-6880-48bb-a860-f2bae04976c5', 'Biology', 'JAMB', null, 2011, null, 'Lack of space in a population could lead to an increase in', null, '["water scarcity","birth rate","disease rate","drought."]', 2, 'Lack of space increases the disease rate.', true, '2026-10-12 20:59:43.524', '2026-10-12 20:59:43.524', null, null, null, 'Lack of space in a population could lead to an increase in', '["water scarcity","birth rate","disease rate","drought."]', 'Lack of space increases the disease rate.', '{"bold":["disease rate"],"italic":[],"underline":[],"fillBlanks":[]}');
