insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0e4ef750-2051-478e-8604-cb29cf2d36ce', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The man was able to persuade his <u>wilful and obstinate</u> daughter to follow the career he chose for her.', null, '["intelligent but arrogant","unyielding and obdurate","obscure and odious","hardworking and intelligent"]', 1, 'Wilful and obstinate = unyielding and obdurate.', true, '2026-10-24 01:04:02.213', '2026-10-24 01:04:02.213', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The man was able to persuade his <u>wilful and obstinate</u> daughter to follow the career he chose for her.', '["intelligent but arrogant","<u>unyielding and obdurate</u>","obscure and odious","hardworking and intelligent"]', '<b>Wilful and obstinate</b> = <b>unyielding and obdurate</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0e52ba4f-655b-46ed-89f9-e666b796bac9', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). <u>To be above board is to be</u>', null, '["afloat","on top of a plank","above suspicion","raised above a board","the chairman of a board"]', 2, '''Above board'' = above suspicion.', true, '2026-10-24 01:02:02.373', '2026-10-24 01:02:02.373', null, null, null, '(Choose the most appropriate interpretation). <u>To be above board is to be</u>', '["afloat","on top of a plank","<u>above suspicion</u>","raised above a board","the chairman of a board"]', '''<b>Above board</b>'' = <b>above suspicion</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0e52d0de-dd68-40a6-b868-6f675922d78e', 'Biology', 'JAMB', null, 2026, null, 'Which of these is not a characteristic of wind pollinated flowers?', null, '["smaller quantities of sticky pollen produced","feathery styles of stigmas pendulously hang outside the flower","small inconspicuous scentless flower","large anthers which are loosely attached to filament","light pollen grains produced in large quantities from anthers"]', 0, 'Wind pollinated (anemophilous) flowers produce large quantities of small, light, dry pollen grains (not sticky) because wind pollination is inefficient and most pollen is wasted. They do not produce smaller quantities of sticky pollen. Sticky pollen is characteristic of insect pollinated flowers, where pollen adheres to insect bodies. Other wind pollination features include: feathery stigmas hanging outside to catch pollen, small inconspicuous scentless flowers (no need to attract insects), and large anthers loosely attached to filaments to release pollen easily.', true, '2026-09-09 03:18:29.045', '2026-09-09 03:18:29.045', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0e65d8ae-fc4d-4d5b-abc9-a890b2a4d500', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The newly elected leader has <u>pledged</u> to ensure better life for the citizens.', null, '["vowed","agreed","undertaken","undertaking"]', 0, 'Pledged = vowed.', true, '2026-10-24 01:03:58.833', '2026-10-24 01:03:58.833', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The newly elected leader has <u>pledged</u> to ensure better life for the citizens.', '["<u>vowed</u>","agreed","undertaken","undertaking"]', '<b>Pledged</b> = <b>vowed</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0e6d00fe-1009-4a65-9d50-5961d3a30303', 'Physics', 'JAMB', null, 1987, null, 'The distance between the fixed points of a centigrade thermometer is 20 cm. What is the temperature when the mercury level is 4.5 cm above the lower mark?', null, '["22.5 °C","29.0 °C","90.0 °C","100.0 °C"]', 0, 'θ = (4.5/20) x 100 = 22.5 °C.', true, '2026-10-12 19:15:25.206', '2026-10-12 19:15:25.206', null, null, null, 'The distance between the fixed points of a centigrade thermometer is 20 cm. What is the temperature when the mercury level is 4.5 cm above the lower mark?', '["22.5 °C","29.0 °C","90.0 °C","100.0 °C"]', 'θ = (4.5/20) x 100 = 22.5 °C.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0e6f3e95-1438-4313-8bac-bec72c4cfc77', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). Can you <u>give a good explanation for</u> your behaviour?', null, '["account for","call for","clear up","make up","give up"]', 0, '''Account for'' means explain.', true, '2026-10-24 01:02:01.318', '2026-10-24 01:02:01.318', null, null, null, '(Choose the most appropriate interpretation). Can you <u>give a good explanation for</u> your behaviour?', '["<u>account for</u>","call for","clear up","make up","give up"]', '''<b>Account for</b>'' means <b>explain</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0e789170-e4f7-462f-93f1-c201ff388a52', 'Physics', 'JAMB', null, 2004, null, 'As the pressure of a fluid increases, its viscosity', null, '["Decreases","Remains constant","Increases then decreases","Increases"]', 3, 'For a liquid, an increase in pressure pushes the molecules closer together and increases the internal friction, so viscosity increases.', true, '2026-10-12 19:15:58.713', '2026-10-12 19:15:58.713', null, null, null, 'As the pressure of a fluid increases, its viscosity', '["Decreases","Remains constant","Increases then decreases","Increases"]', 'For a liquid, an increase in pressure pushes the molecules closer together and increases the internal friction, so viscosity increases.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0e7ee073-0c3f-4e94-84ce-b18a8f23f373', 'Financial Accounting', 'UTME', null, 2002, null, 'Abba''s capital balance at the end of the year will be', null, '["N5475","N5725","N4400","N5000"]', 3, 'The partners maintained fixed capital method; no adjustment will be made on their capital. So there will be no changes in the capital balance, remaining at N5000.', true, '2026-10-12 21:59:58.991', '2026-10-12 21:59:58.991', null, null, null, 'Abba''s capital balance at the end of the year will be', '["N5475","N5725","N4400","<b>N5000</b>"]', 'The partners maintained fixed capital method; no adjustment will be made on their capital. So there will be no changes in the capital balance, remaining at <b>N5000</b>.', '{"bold":["N5000"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0e85f45b-64da-43b4-8757-298980b391b8', 'English Language', 'JAMB', null, 2007, null, 'We must observe that most of the support by other states <u>----------</u> only marginal returns.', null, '["have yielded","yield","has yielded","have yield"]', 2, '''Support'' uncountable â†’ has yielded.', true, '2026-10-24 01:02:12.9', '2026-10-24 01:02:12.9', null, null, null, 'We must observe that most of the support by other states <u>----------</u> only marginal returns.', '["have yielded","yield","<u>has yielded</u>","have yield"]', '''<b>Support</b>'' uncountable â†’ <b>has yielded</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0e88c394-c65e-4f0a-9ea9-94e06328c3b5', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. It is sheer <u>fantasy</u> to believe that there could never be a miscalculation by any nation that has atomic weapons. Fantasy here means ________________', null, '["dream","hope","nonsense","joke","stupidity"]', 2, 'Fantasy = unrealistic notion; nonsense.', true, '2026-10-24 01:01:39.977', '2026-10-24 01:01:39.977', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. It is sheer <u>fantasy</u> to believe that there could never be a miscalculation by any nation that has atomic weapons. Fantasy here means ________________', '["dream","hope","<u>nonsense</u>","joke","stupidity"]', '<b>Fantasy</b> = unrealistic notion; <b>nonsense</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0e8baa61-a455-4ec7-94ad-079f74e5e277', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Their high level of dishonesty has made that department <u>infamous</u> in the entire secretariat.', null, '["reputable","notorious","unpopular","acceptable"]', 1, 'Infamous = notorious.', true, '2026-10-24 07:21:15.456', '2026-10-24 07:21:15.456', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Their high level of dishonesty has made that department <u>infamous</u> in the entire secretariat.', '["reputable","notorious","unpopular","acceptable"]', 'Infamous = notorious.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0e902f59-ab4a-4430-aa8d-711e940d3ab1', 'Physics', 'JAMB', null, 2004, null, 'The energy stored in an inductor of inductance 5 mH when a current of 6 A flows through it is', null, '["1.8 x 10⁻² J","9.0 x 10⁻³ J","1.4 x 10⁻² J","9.0 x 10⁻² J"]', 3, 'E = ½LI² = ½ x 5 x 10⁻³ x 36 = 9.0 x 10⁻² J.', true, '2026-10-12 19:15:59.355', '2026-10-12 19:15:59.355', null, null, null, 'The energy stored in an inductor of inductance 5 mH when a current of 6 A flows through it is', '["1.8 x 10<sup>-2</sup> J","9.0 x 10<sup>-3</sup> J","1.4 x 10<sup>-2</sup> J","9.0 x 10<sup>-2</sup> J"]', 'E = ½LI<sup>2</sup> = ½ x 5 x 10<sup>-3</sup> x 36 = 9.0 x 10<sup>-2</sup> J.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0eac09f2-210d-41a0-bd47-f3f5262e7c30', 'English Language', 'JAMB', null, 2024, null, '{Choose the option that has the same stress pattern as the given word} Student', null, '["Propose","Superb","Refuse(N)","Rebel(V)"]', 2, '"Student" and "Refuse" (noun) both have stress on the first syllable.', true, '2026-09-18 09:43:02.244', '2026-09-18 09:43:02.244', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0eb11429-a56d-4813-9156-28a2f7e7451e', 'English Language', 'JAMB', null, 2007, null, 'We hold that the nation, both in its public and private sectors <u>------------</u> the best consultancy service and advice in all its endeavours.', null, '["deserve","is deserving","deserves","are deserving","richly deserve"]', 2, 'Singular subject ''the nation'' takes ''deserves''.', true, '2026-10-24 01:02:11.636', '2026-10-24 01:02:11.636', null, null, null, 'We hold that the nation, both in its public and private sectors <u>------------</u> the best consultancy service and advice in all its endeavours.', '["deserve","is deserving","<u>deserves</u>","are deserving","richly deserve"]', 'Singular subject ''<b>the nation</b>'' takes ''<b>deserves</b>''.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0ec1fdd5-59ad-48ca-b03c-1037c46cbe89', 'Literature in English', 'JAMB', null, 2026, null, 'The exclusive right given to authors to protect their works from unlawful production is', null, '["Copyright","An authority","An authors right","A constitutional provision"]', 0, 'It is copyright.', true, '2026-09-12 11:07:30.275', '2026-09-12 11:07:30.275', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0ecabb85-f40f-4d8d-bf70-336d1079f15c', 'Literature in English', 'JAMB', null, 2026, null, 'Oral literature is part of', null, '["drama","folklore","poetry","music"]', 1, 'Oral literature is part of folklore.', true, '2026-09-12 11:11:02.452', '2026-09-12 11:11:02.452', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0ecf7661-c72d-4d6c-a9e7-859d5e7940dc', 'Economics', 'JAMB', null, 2026, null, 'If income rises from N2,000 to N4,000 and quantity demanded increases from 80 units to 120 units, find the income elasticity of demand.', null, '["0.5","1.2","2.5","4.0"]', 0, 'Income elasticity of demand = % change in quantity demanded / % change in income. % change in quantity = (120-80)/80 × 100 = 50%. % change in income = (4000-2000)/2000 × 100 = 100%. YED = 50/100 = 0.5. Since YED is positive but less than 1, the good is a normal good (necessity) with inelastic income demand.', true, '2026-09-10 10:41:59.86', '2026-09-10 10:41:59.86', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0ed7fe5d-121d-4d92-9421-4f89f723806f', 'Economics', 'JAMB', null, 2026, null, 'A 35% increase in Price leads to 55% increase in Quantity Demanded. The Price elasticity is', null, '["Fairly inelastic","Perfectly elastic","Fairly elastic","Perfectly Inelastic"]', 2, 'PED = 55/35 = 1.57, which is greater than 1, so demand is fairly elastic.', true, '2026-09-12 10:59:49.873', '2026-09-12 10:59:49.873', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0ee57138-5a81-4207-a1a3-edb89350a272', 'English Language', 'JAMB', null, 2007, null, 'Many a student <u>______</u> failed this course due to poor preparation.', null, '["have","has","are","were"]', 1, '''Many a'' singular â†’ has.', true, '2026-10-24 01:04:29.947', '2026-10-24 01:04:29.947', null, null, null, 'Many a student <u>______</u> failed this course due to poor preparation.', '["have","<u>has</u>","are","were"]', '''<b>Many a</b>'' singular â†’ <b>has</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0ef42109-f724-436d-a2e9-dc53f4582dfd', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. You can use <u>lethal</u> means if necessary to stop dangerous characters from molesting innocent citizens.', null, '["fatal","cruel","harmless","soft"]', 2, 'Lethal = deadly; opposite = harmless.', true, '2026-10-24 07:21:17.499', '2026-10-24 07:21:17.499', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. You can use <u>lethal</u> means if necessary to stop dangerous characters from molesting innocent citizens.', '["fatal","cruel","harmless","soft"]', 'Lethal = deadly; opposite = harmless.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0ef4fde0-ba94-4676-99db-690bd6643571', 'Hausa', 'JAMB', null, 2011, null, 'Wanne ne biki na sana''a?', null, '["Bikin saukar karatu.","Bikin kamun gwauro.","Bikin kamun kifi.","Bikin kalankuwa."]', 2, 'Bikin kamun kifi biki ne na sana''a.', true, '2026-10-13 10:37:21.666', '2026-10-13 10:37:21.666', null, null, null, 'Wanne ne biki na sana''a?', '["Bikin saukar karatu.","Bikin kamun gwauro.","Bikin kamun kifi.","Bikin kalankuwa."]', 'Bikin kamun kifi biki ne na sana''a.', '{"bold":["Bikin kamun kifi"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0ef8f531-f127-4bca-8ea0-3fc45f6958dd', 'Chemistry', 'JAMB', null, 2026, null, 'Which of the following best explains why sodium chloride dissolves easily in water?', null, '["Covalent bonds form between NaCl and water","Hydrogen bonds form between Na⁺ and Cl⁻ ions","Ion-dipole attraction exists between Na⁺, Cl⁻ and water molecules","Van der Waals forces break the crystal lattice"]', 2, 'Hydration energy released by strong ion-dipole attractions between polar water molecules and Na+/Cl- ions overcomes the ionic lattice energy.', true, '2026-09-09 17:12:47.902', '2026-09-09 17:12:47.902', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0efc8b85-86d2-460b-867f-df0935d37e74', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Election process always becomes <u>volatile</u>.', null, '["calm","sudden","strange","latent"]', 0, 'Volatile = unstable; opposite = calm.', true, '2026-10-24 07:21:27.098', '2026-10-24 07:21:27.098', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Election process always becomes <u>volatile</u>.', '["calm","sudden","strange","latent"]', 'Volatile = unstable; opposite = calm.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0f0fe8bf-7df4-4bd8-b497-e28c7ffeade4', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). The new religious leader <u>hands out an olive branch</u>.', null, '["sues for peace","gives out branches of the olive tree","challenges his opponents to a fight","blesses his congregation"]', 0, '''An olive branch'' = offer of peace.', true, '2026-10-24 01:02:03.623', '2026-10-24 01:02:03.623', null, null, null, '(Choose the most appropriate interpretation). The new religious leader <u>hands out an olive branch</u>.', '["<u>sues for peace</u>","gives out branches of the olive tree","challenges his opponents to a fight","blesses his congregation"]', '''<b>An olive branch</b>'' = <b>offer of peace</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0f0feccb-c48b-4975-93fd-df7cb7eb5107', 'Biology', 'JAMB', null, 2026, null, 'The function of pith in plant is', null, '["absorb mineral salt and nutrient from the soil","store and transport nutrients throughout the plant","trap chlorophyll from the sunlight","removal of waste product from the plant"]', 1, 'The primary function of pith is to store and transport nutrients throughout the plant. Pith is the central parenchyma tissue in stems and roots, composed of loosely arranged cells that store food materials (starch, nutrients) and sometimes water. Some nutrients can move through the pith. Absorption of minerals occurs through roots. Chlorophyll is produced, not trapped, by the plant. Waste removal is not a function of pith. The pith is especially prominent in dicot stems and monocot roots, where it serves as a storage tissue and may also help in conducting substances within the plant.', true, '2026-09-09 03:18:56.369', '2026-09-09 03:18:56.369', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0f12562d-20be-4729-ac93-ee508f6d5b35', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Their strength is their <u>staggering capacity</u> to reproduce.', null, '["unstable multiplying power","unreliable attacking power","qualitative multiplying power","overwhelming multiplying power"]', 3, 'Staggering = overwhelming.', true, '2026-10-24 01:04:00.71', '2026-10-24 01:04:00.71', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Their strength is their <u>staggering capacity</u> to reproduce.', '["unstable multiplying power","unreliable attacking power","qualitative multiplying power","<u>overwhelming multiplying power</u>"]', '<b>Staggering</b> = <b>overwhelming</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0f19d9d9-7afa-43c9-9d49-a45515dfc651', 'Biology', 'JAMB', null, 2026, null, 'Which of the following is the best explanation for a child who is phenotypically short and born of two tall parents?', null, '["the father possesses a gene for shortness","both parents possess genes for shortness","nature makes the child short","the mother possesses a gene for shortness"]', 1, 'For a recessive trait to appear, the child must inherit a recessive allele from both parents, meaning both parents carry the gene for shortness.', true, '2026-09-09 02:56:42.641', '2026-09-09 02:56:42.641', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0f206342-7681-40b3-97ad-d7c20dae047d', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Bala was put off by Lanre''s <u>coquettish</u> behaviour towards him.', null, '["unfriendly advantage","inviting and friendly advances","quarrelsome attitude","interesting attitude"]', 0, 'Coquettish = flirtatious; opposite = unfriendly.', true, '2026-10-24 07:21:17.298', '2026-10-24 07:21:17.298', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Bala was put off by Lanre''s <u>coquettish</u> behaviour towards him.', '["unfriendly advantage","inviting and friendly advances","quarrelsome attitude","interesting attitude"]', 'Coquettish = flirtatious; opposite = unfriendly.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0f281233-a1a6-4731-830d-dd2f2a263937', 'Biology', 'JAMB', null, 2026, null, 'Excess water in plants is excreted as water vapour and droplets respectively through', null, '["respiration and guttation","transpiration and guttation","photosynthesis and guttation","guttation and condensation"]', 1, 'Excess water in plants is excreted as water vapor through transpiration and as droplets through guttation. Transpiration is the loss of water vapor from aerial parts through stomata. Guttation is the exudation of liquid water droplets from leaf tips through hydathodes, typically occurring at night or early morning when humidity is high and transpiration is low. Respiration is not involved in water excretion. Photosynthesis produces glucose, not water excretion.', true, '2026-09-09 03:19:08.358', '2026-09-09 03:19:08.358', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0f289b51-627a-4bb3-978f-14ba05847f90', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Ezekiel''s vision of dry bones symbolises', null, '["divine judgement","restoration of Israel","destruction of enemies","exile"]', 1, 'Ezekiel''s vision of dry bones symbolises the restoration of Israel. The dry bones represented the whole house of Israel who said, ''Our bones are dried up, and our hope is lost.'' God promised to bring them back to life and restore them to their land.', true, '2026-09-12 09:45:52.16', '2026-09-12 09:45:52.16', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0f2dc694-f0ed-4473-8fd2-d3d3ad399b19', 'Physics', 'JAMB', null, 1989, null, 'When a radiation strikes a metal surface, electrons may be ejected from the metal. The maximum kinetic energy which may be acquired by an ejected electron depends on the', null, '["Intensity of the radiation","Source of the radiation","Wavelength of the radiation","Detection device for the electron."]', 2, 'Maximum kinetic energy = hf - φ, so it depends on the frequency (and so the wavelength) of the radiation, not on its intensity.', true, '2026-10-12 19:15:30.171', '2026-10-12 19:15:30.171', null, null, null, 'When a radiation strikes a metal surface, electrons may be ejected from the metal. The maximum kinetic energy which may be acquired by an ejected electron depends on the', '["Intensity of the radiation","Source of the radiation","Wavelength of the radiation","Detection device for the electron."]', 'Maximum kinetic energy = hf - φ, so it depends on the frequency (and so the wavelength) of the radiation, not on its intensity.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0f397bdb-7a3b-44be-9fd3-3a623f5948b3', 'Chemistry', 'JAMB', null, 2026, null, '200 cm3 of air was passed over heated copper in a syringe several times to produce copper (II) oxide. When cooled, the final volume of air recorded was 158 cm3. Estimate the percentage of oxygen in the air.', null, '["31%","27%","21%","19%"]', 2, 'Volume of oxygen reacted = 200 - 158 = 42 cm3. Percentage = (42 / 200) * 100 = 21%.', true, '2026-09-09 17:12:46.496', '2026-09-09 17:12:46.496', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0f41bd6f-d4ed-4179-be1c-fa004043693f', 'Yoruba', 'JAMB', null, 2007, null, 'Nínú Bàdé a máa lò sòjà òròòrùn, ibá-ìyêlê tó je yõ ni', null, '["àiyétán bárakú","àiyétán atêrçrç","ayetán ìbèrè","ayetán ìparí."]', 0, 'Ibá-ìyêlê tó je yõ ni àiyétán bárakú.', true, '2026-10-13 13:23:31.465', '2026-10-13 13:23:31.465', null, null, null, 'Nínú Bàdé a máa lò sòjà òròòrùn, ibá-ìyêlê tó je yõ ni', '["àiyétán bárakú","àiyétán atêrçrç","ayetán ìbèrè","ayetán ìparí."]', 'Ibá-ìyêlê tó je yõ ni àiyétán bárakú.', '{"bold":["àiyétán bárakú"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0f44c4a1-422a-410c-91f0-2410a41d7acf', 'Physics', 'JAMB', null, 1986, null, 'The vibration of an air column produces the sound in the', null, '["Piano","Guitar","Flute","School handbell."]', 2, 'In a flute the sound comes from a vibrating column of air. A piano and guitar use strings, and a handbell vibrates as a solid.', true, '2026-10-12 19:15:24.164', '2026-10-12 19:15:24.164', null, null, null, 'The vibration of an air column produces the sound in the', '["Piano","Guitar","Flute","School handbell."]', 'In a flute the sound comes from a vibrating column of air. A piano and guitar use strings, and a handbell vibrates as a solid.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0f47b011-2e3f-468b-bb18-8f85e511c5d2', 'English Language', 'JAMB', null, 2024, null, 'What was Mr. Meko''s reaction when Bepo pointed out the error in the name of the school?', null, '["He immediately agreed and made the correction","He ignored Bepo''s suggestion entirely","He praised Bepo for his linguistic expertise","He feigned ignorance and joked about the matter"]', 3, 'Mr. Meko feigned ignorance and joked about the matter.', true, '2026-09-18 09:43:02.759', '2026-09-18 09:43:02.759', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0f48e2fd-2cc9-4ad5-aa57-72ef53676b0c', 'Biology', 'JAMB', null, 2011, null, 'An example of a filter-feeding animal is', null, '["shark","butterfly","whale","mosquito."]', 2, 'Whale is an example of a filter-feeding animal.', true, '2026-10-12 20:59:42.965', '2026-10-12 20:59:42.965', null, null, null, 'An example of a filter-feeding animal is', '["shark","butterfly","whale","mosquito."]', 'Whale is an example of a filter-feeding animal.', '{"bold":["Whale"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0f4a063d-3baf-467a-bbf1-a439820df476', 'Physics', 'JAMB', null, 1987, null, 'The length of a side of a metallic cube at 20 °C is 5.0 cm. Given that the linear expansivity of the metal is 4.0 x 10⁻⁵ K⁻¹, find the volume of the cube at 120 °C.', null, '["126.50 cm³","126.25 cm³","126.00 cm³","125.00 cm³"]', 0, 'V₀ = 125 cm³, γ = 3α = 1.2 x 10⁻⁴ K⁻¹. ΔV = 125 x 1.2 x 10⁻⁴ x 100 = 1.5 cm³, so V = 126.5 cm³.', true, '2026-10-12 19:15:25.261', '2026-10-12 19:15:25.261', null, null, null, 'The length of a side of a metallic cube at 20 °C is 5.0 cm. Given that the linear expansivity of the metal is 4.0 x 10<sup>-5</sup> K<sup>-1</sup>, find the volume of the cube at 120 °C.', '["126.50 cm<sup>3</sup>","126.25 cm<sup>3</sup>","126.00 cm<sup>3</sup>","125.00 cm<sup>3</sup>"]', 'V<sub>0</sub> = 125 cm<sup>3</sup>, γ = 3α = 1.2 x 10<sup>-4</sup> K<sup>-1</sup>. ΔV = 125 x 1.2 x 10<sup>-4</sup> x 100 = 1.5 cm<sup>3</sup>, so V = 126.5 cm<sup>3</sup>.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0f5bdc6f-a50e-48a6-8e07-99a3fd51a332', 'Physics', 'JAMB', null, 1997, null, 'Two 50 μF parallel plate capacitors are connected in series. The combined capacitor is then connected across a 100-V battery. The charge on each plate of the capacitor is', null, '["5.00 x 10⁻⁵ C","2.50 x 10⁻³ C","1.25 x 10⁻³ C","1.00 x 10⁻² C"]', 1, 'Series combination = 25 μF. Q = CV = 25 x 10⁻⁶ x 100 = 2.50 x 10⁻³ C.', true, '2026-10-12 19:15:44.281', '2026-10-12 19:15:44.281', null, null, null, 'Two 50 μF parallel plate capacitors are connected in series. The combined capacitor is then connected across a 100-V battery. The charge on each plate of the capacitor is', '["5.00 x 10<sup>-5</sup> C","2.50 x 10<sup>-3</sup> C","1.25 x 10<sup>-3</sup> C","1.00 x 10<sup>-2</sup> C"]', 'Series combination = 25 μF. Q = CV = 25 x 10<sup>-6</sup> x 100 = 2.50 x 10<sup>-3</sup> C.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0f607809-cebc-41f8-bd99-b34ffb2614ed', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Our local paper is noted for its <u>incisive</u> editorials on local politics.', null, '["sarcastic","penetrating","decisive","destructive"]', 1, 'Incisive = penetrating.', true, '2026-10-24 01:04:00.228', '2026-10-24 01:04:00.228', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Our local paper is noted for its <u>incisive</u> editorials on local politics.', '["sarcastic","<u>penetrating</u>","decisive","destructive"]', '<b>Incisive</b> = <b>penetrating</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0f742a84-f2ec-4c94-8fc5-df1515edc516', 'Government', 'JAMB', null, 2026, null, 'The earliest nationalists activities in Nigeria were spearheaded by', null, '["Trade Unions","educated elites","political parties","traditional rulers"]', 1, 'The earliest nationalist activities in Nigeria were spearheaded by the educated elites. The educated elite—teachers, lawyers, journalists, doctors, and civil servants—were the first to articulate nationalist grievances and demand political rights. They formed organizations like the Nigerian National Democratic Party (NNDP) and the Nigerian Youth Movement (NYM). Trade unions, political parties, and traditional rulers played roles later, but the educated elite led the earliest nationalist activities.', true, '2026-09-10 10:44:18.56', '2026-09-10 10:44:18.56', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0f780940-e16d-4f2b-998a-389eece20be6', 'Biology', 'JAMB', null, 2011, null, 'The interaction of a community of organisms with its abiotic environment constitutes', null, '["a niche","a food chain","an ecosystem","a microhabitat."]', 2, 'This constitutes an ecosystem.', true, '2026-10-12 20:59:43.066', '2026-10-12 20:59:43.066', null, null, null, 'The interaction of a community of organisms with its abiotic environment constitutes', '["a niche","a food chain","an ecosystem","a microhabitat."]', 'This constitutes an ecosystem.', '{"bold":["an ecosystem"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0f86bbdd-ec71-48b8-a84c-69e164d066fb', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Adeniji is suffering from the consequences of <u>alienation</u>.', null, '["confinement","isolation","enclosure","imprisonment"]', 1, 'Alienation = isolation.', true, '2026-10-24 01:01:46.425', '2026-10-24 01:01:46.425', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Adeniji is suffering from the consequences of <u>alienation</u>.', '["confinement","<u>isolation</u>","enclosure","imprisonment"]', '<b>Alienation</b> = <b>isolation</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0f873fdb-124f-4e42-a9aa-a4b2bfe1e50c', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The girl is very intelligent, but her jokes are rather <u>outrageous</u>.', null, '["offensive","courageous","pleasant","unwholesome"]', 2, 'Outrageous = offensive; opposite = pleasant.', true, '2026-10-24 07:21:13.007', '2026-10-24 07:21:13.007', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The girl is very intelligent, but her jokes are rather <u>outrageous</u>.', '["offensive","courageous","pleasant","unwholesome"]', 'Outrageous = offensive; opposite = pleasant.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0f8d87f0-651a-42d0-9664-294e2aad003c', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The Executive Secretary has just <u>assumed office</u>.', null, '["resumed work","been sworn in","started work","returned"]', 2, 'Assumed office = started work.', true, '2026-10-24 01:01:51.77', '2026-10-24 01:01:51.77', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The Executive Secretary has just <u>assumed office</u>.', '["resumed work","been sworn in","<u>started work</u>","returned"]', '<b>Assumed office</b> = <b>started work</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0f8da89f-e54f-403d-adab-6389e6bf2468', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. You <u>don''t have to agree</u> with our producers.', null, '["shouldn''t disagree","must not agree","may disagree if you don''t wish","may not disagree if you don''t wish"]', 2, 'Don''t have to = may disagree if you don''t wish.', true, '2026-10-24 01:04:00.549', '2026-10-24 01:04:00.549', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. You <u>don''t have to agree</u> with our producers.', '["shouldn''t disagree","must not agree","<u>may disagree if you don''t wish</u>","may not disagree if you don''t wish"]', '<b>Don''t have to</b> = <b>may disagree if you don''t wish</b>.', '{}');
