insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0f9ffa84-eaff-44b9-9dc9-926268418e94', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). The judge <u>took issue with</u> the counsel who complained of double standards.', null, '["agreed with","argued with","criticized","supported"]', 1, '''Took issue with'' = argued with.', true, '2026-10-24 01:02:07.169', '2026-10-24 01:02:07.169', null, null, null, '(Choose the most appropriate interpretation). The judge <u>took issue with</u> the counsel who complained of double standards.', '["agreed with","<u>argued with</u>","criticized","supported"]', '''<b>Took issue with</b>'' = <b>argued with</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0fbedc12-b9b4-4d98-ab4b-b8e7a1156259', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. He won the election because he was able to <u>carry his people with him</u>.', null, '["alienate his people","go out with his people","have the support of the people","fail to provide the people with transport"]', 0, 'Carry people with him = win support; opposite = alienate.', true, '2026-10-24 07:21:14.887', '2026-10-24 07:21:14.887', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. He won the election because he was able to <u>carry his people with him</u>.', '["alienate his people","go out with his people","have the support of the people","fail to provide the people with transport"]', 'Carry people with him = win support; opposite = alienate.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0fc40c11-e7f9-4f64-8df2-c1b0d0dd4365', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The teacher''s apparent nonchalant attitude was <u>misconstrued</u> by his students.', null, '["condoned","misquoted","misinterpreted","misrepresented"]', 2, 'Misconstrued = misinterpreted.', true, '2026-10-24 01:01:51.506', '2026-10-24 01:01:51.506', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The teacher''s apparent nonchalant attitude was <u>misconstrued</u> by his students.', '["condoned","misquoted","<u>misinterpreted</u>","misrepresented"]', '<b>Misconstrued</b> = <b>misinterpreted</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0fc86444-49ba-4e58-8b0b-0f6246dcce73', 'Yoruba', 'JAMB', null, 2007, null, 'Ìwé Àyàyàn Àlò Onítàn ni ìbéèrè 26-28 dá lé. Nínú ìtán Òmõ Onífèrè àti Àwòn Òbí rê, òmõ mélòó ni bàbá olóko plá bí?', null, '["Mêrin","Mêta","Mêjî","Ökan."]', 1, 'Bàbá olóko plá bí òmõ mêta.', true, '2026-10-13 13:23:31.851', '2026-10-13 13:23:31.851', null, null, null, 'Ìwé Àyàyàn Àlò Onítàn ni ìbéèrè 26-28 dá lé. Nínú ìtán Òmõ Onífèrè àti Àwòn Òbí rê, òmõ mélòó ni bàbá olóko plá bí?', '["Mêrin","Mêta","Mêjî","Ökan."]', 'Bàbá olóko plá bí òmõ mêta.', '{"bold":["mêta"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('0fcc85c0-059a-445a-a1e7-65850818a35b', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). This time, she will be competing <u>with a dark horse</u>.', null, '["a weak and low-spirited person","a person about whose abilities little is known","a person who is a formidable candidate","a person as strong as a horse"]', 1, '''A dark horse'' = person whose abilities little is known.', true, '2026-10-24 01:02:07.917', '2026-10-24 01:02:07.917', null, null, null, '(Choose the most appropriate interpretation). This time, she will be competing <u>with a dark horse</u>.', '["a weak and low-spirited person","<u>a person about whose abilities little is known</u>","a person who is a formidable candidate","a person as strong as a horse"]', '''A <b>dark horse</b>'' = <b>person whose abilities little is known</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('10022721-3f71-460c-a597-7fa775420aa4', 'English Language', 'JAMB', null, 2024, null, 'The third chapter of the novel is titled?', null, '["The Ennectment","Migration Tales","A Case of Visa Denied","Snake in the Roof"]', 2, 'The third chapter of the novel is titled "A Case of Visa Denied."', true, '2026-09-18 09:24:04.658', '2026-09-18 09:24:04.658', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('100425ae-5326-4b98-9d08-5a12d8b15033', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The lazy man cast a <u>lustful</u> glance at his neighbour''s wife', null, '["hateful","quick","covetous","envious"]', 2, 'Lustful = covetous.', true, '2026-10-24 01:04:12.348', '2026-10-24 01:04:12.348', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The lazy man cast a <u>lustful</u> glance at his neighbour''s wife', '["hateful","quick","<u>covetous</u>","envious"]', '<b>Lustful</b> = <b>covetous</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('100a1b0e-13e1-4246-98fd-6adbf68a64d5', 'Chemistry', 'JAMB', null, 2026, null, 'Elements P, Q, R, S, have 6, 11, 15 and 17 electrons respectively, therefore', null, '["P will form an electrovalent bond with R","Q will form a covalent bond with S","R will form an electrovalent bond with S","Q will form an electrovalent bond with S"]', 3, 'Q (Na, 11 electrons) and S (Cl, 17 electrons) form an electrovalent bond.', true, '2026-09-12 11:36:09.808', '2026-09-12 11:36:09.808', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('101972cb-53a3-48c7-869b-fe44ec624f9b', 'General Mathematics', 'JAMB', null, 2026, null, 'If the four interior angles of a quadrilateral are (p+10)°, (p-30)°, (2p-45)°, and (p+15)°, then p is', null, '["125°","82°","135°","105°","60°"]', 1, 'Sum = 360. 5p-50 = 360. 5p = 410. p = 82°.', true, '2026-09-12 11:44:21.783', '2026-09-12 11:44:21.783', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1026e433-6277-46ef-9b22-59a1b5b48c2e', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The Minister has finally been dropped from the present cabinet because of his <u>ignoble</u> act.', null, '["criminal","ignorant","honourable","selfish"]', 2, 'Ignoble = dishonourable; opposite = honourable.', true, '2026-10-24 07:21:19.728', '2026-10-24 07:21:19.728', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The Minister has finally been dropped from the present cabinet because of his <u>ignoble</u> act.', '["criminal","ignorant","honourable","selfish"]', 'Ignoble = dishonourable; opposite = honourable.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('102735da-6d85-4402-a0e1-4742e521ee9d', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. His success may be described as <u>a pyrrhic victory</u>.', null, '["a deserving victory","costly","indecisive","an easy victory"]', 1, 'A pyrrhic victory = costly victory.', true, '2026-10-24 01:04:04.027', '2026-10-24 01:04:04.027', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. His success may be described as <u>a pyrrhic victory</u>.', '["a deserving victory","<u>costly</u>","indecisive","an easy victory"]', 'A <b>pyrrhic victory</b> = <b>costly</b> victory.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('102d685b-e7a9-4e79-aff5-fff505cc8813', 'Physics', 'JAMB', null, 2026, null, 'At what angle does a projectile launched with a constant initial velocity reach its maximum height?', null, '["10 degrees","30 degrees","45 degrees","60 degrees","90 degrees"]', 4, 'A projectile reaches its maximum height when launched at 90° (straight up). However, for maximum range, the angle is 45°. The question asks for maximum height, so the answer is 90°.', true, '2026-09-10 10:56:48.215', '2026-09-10 10:56:48.215', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('102f3da0-6e35-42af-ab91-0e638bf8dea4', 'English Language', 'JAMB', null, 2007, null, 'Many a candidate <u>------------</u> to realise the difference between written and spoken English.', null, '["fails","fail","have failed","is failing"]', 0, '''Many a'' takes singular verb.', true, '2026-10-24 01:04:25.788', '2026-10-24 01:04:25.788', null, null, null, 'Many a candidate <u>------------</u> to realise the difference between written and spoken English.', '["<u>fails</u>","fail","have failed","is failing"]', '''<b>Many a</b>'' takes singular verb.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('103018a4-8f14-43d4-8cc7-083c46d45f7c', 'Biology', 'JAMB', null, 2026, null, 'A feature associated with the Y-chromosome in humans is', null, '["long eyelashes","prominent fingernails","facial hairs","enlarged breast"]', 2, 'A feature associated with the Y-chromosome in humans is facial hairs. The Y chromosome contains genes that determine maleness, including the SRY gene that triggers the development of male secondary sexual characteristics, including facial hair. The Y chromosome is only found in males. Long eyelashes, prominent fingernails, and enlarged breasts are not exclusively Y-chromosome-associated traits.', true, '2026-09-09 03:19:21.428', '2026-09-09 03:19:21.428', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1032a4cf-3502-43ee-a5b3-f860baf1bedc', 'Literature in English', 'JAMB', null, 2026, null, 'The character of Bendu is significant primarily because she', null, '["Represents political authority in post-war Liberia","Embodies the psychological and emotional scars of the civil war","Serves as comic relief throughout the narrative","Symbolises Western intervention in Africa"]', 1, 'Bendu embodies the psychological and emotional scars of the civil war.', true, '2026-09-12 11:09:50.964', '2026-09-12 11:09:50.964', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('103eb63f-6d11-43fd-8c7b-5044d078ca15', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'What name did Abraham give the place where he had attempted to sacrifice his son?', null, '["the LORD is with us","the LORD will provide","the Mount of the Lord","the gate of heaven"]', 1, 'Abraham called the place ''The LORD will provide'' (Yahweh-jireh). He named it this because God provided a ram as a substitute for Isaac.', true, '2026-09-12 09:46:08.183', '2026-09-12 09:46:08.183', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('10465a5e-f263-47fc-a446-48a916d05183', 'Physics', 'JAMB', null, 1983, null, 'Longitudinal waves do not exhibit', null, '["Refraction","Reflection","Diffraction","Polarization","Rarefaction"]', 3, 'Polarization only occurs in transverse waves, because it restricts the direction of vibration perpendicular to the direction of travel. In longitudinal waves the vibration is along the direction of travel.', true, '2026-10-12 19:15:18.313', '2026-10-12 19:15:18.313', null, null, null, 'Longitudinal waves do not exhibit', '["Refraction","Reflection","Diffraction","Polarization","Rarefaction"]', 'Polarization only occurs in transverse waves, because it restricts the direction of vibration perpendicular to the direction of travel. In longitudinal waves the vibration is along the direction of travel.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('104f015c-48d0-4366-bd7d-782d9917798f', 'Physics', 'JAMB', null, 2026, null, 'Which of the following graphs correctly represents the variation of mass of a given material deposited with time for constant current in Faraday''s Law of Electrolysis?', 'https://res.cloudinary.com/kwi1uv0g/image/upload/v1789038724/questions/t8wkugwll5glvpuwrx2r.png', '["Graph A","Graph B","Graph C","Graph D"]', 1, 'According to Faraday''s Law of Electrolysis, the mass of a substance deposited is directly proportional to the quantity of charge passed (m ∝ Q = It). For constant current, mass is directly proportional to time (m ∝ t). This gives a straight line passing through the origin.', true, '2026-09-10 11:19:25.93', '2026-09-10 11:19:25.93', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('10606f8a-6094-4130-9e2d-ae610960247d', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). <u>Try not to lose heart</u>, said the man', null, '["Try not to be bold and weak","Try not to become sad and hopeless","Try not to be happy and feeble","Try not to be timid and hopeful"]', 1, '''Lose heart'' = become sad and hopeless.', true, '2026-10-24 01:04:24.689', '2026-10-24 01:04:24.689', null, null, null, '(Choose the most appropriate interpretation). <u>Try not to lose heart</u>, said the man', '["Try not to be bold and weak","<u>Try not to become sad and hopeless</u>","Try not to be happy and feeble","Try not to be timid and hopeful"]', '''<b>Lose heart</b>'' = <b>become sad and hopeless</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('106163a0-b656-4b25-885d-ac7a8b62e876', 'Chemistry', 'JAMB', null, 2026, null, 'Use of diamond as abrasive is due to its', null, '["hardness","durability","High melting point","octahedral"]', 0, 'Diamond is used as an abrasive due to its hardness.', true, '2026-09-12 11:36:05.995', '2026-09-12 11:36:05.995', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('106a5928-7673-4087-b770-6187a3d8ba9a', 'Chemistry', 'JAMB', null, 2026, null, 'The first definition of an element was made by', null, '["J. Dalton","A. Lavoisier","R. Boyle","J. J. Thompson"]', 2, 'Robert Boyle proposed the first modern operational definition of a chemical element in 1661 as a substance that cannot be broken down simpler.', true, '2026-09-09 17:12:47.551', '2026-09-09 17:12:47.551', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('107636b8-b22e-4f01-af47-8b2661756f72', 'Physics', 'JAMB', null, 1986, null, 'The expansion of solids can be considered a disadvantage in the', null, '["Balance wheel of a watch","Fitting of wheels on rims","Fire alarm","Thermostat."]', 0, 'Expansion with temperature would change the period of a watch''s balance wheel, which is why compensated balance wheels are used. In the other options expansion is useful.', true, '2026-10-12 19:15:23.306', '2026-10-12 19:15:23.306', null, null, null, 'The expansion of solids can be considered a disadvantage in the', '["Balance wheel of a watch","Fitting of wheels on rims","Fire alarm","Thermostat."]', 'Expansion with temperature would change the period of a watch''s balance wheel, which is why compensated balance wheels are used. In the other options expansion is useful.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1079f108-24d7-4556-9f6a-28ce18310459', 'Physics', 'JAMB', null, 2002, null, 'Which of the following eye defects can be corrected using a cylindrical lens?', null, '["Presbyopia","Chromatic aberration","Myopia","Astigmatism"]', 3, 'Astigmatism is caused by unequal curvature of the cornea in different directions, which is corrected with a cylindrical lens.', true, '2026-10-12 19:15:53.268', '2026-10-12 19:15:53.268', null, null, null, 'Which of the following eye defects can be corrected using a cylindrical lens?', '["Presbyopia","Chromatic aberration","Myopia","Astigmatism"]', 'Astigmatism is caused by unequal curvature of the cornea in different directions, which is corrected with a cylindrical lens.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
