insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('109d5615-e8e4-4fb3-b37d-a165e1ff1215', 'Literature in English', 'JAMB', null, 2026, null, 'The rhyme scheme of the first stanza is', null, '["Aabb","Abab","Abcd","Abba"]', 1, 'The rhyme scheme is ABAB.', true, '2026-09-12 11:10:52.876', '2026-09-12 11:10:52.876', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('10e208b3-0265-4c34-89f3-ec06a3e1a039', 'Biology', 'JAMB', null, 2002, null, 'One of the adaptations to life on trees by a monkey is its possession of digits which are', null, '["extensible","big","opposable","long"]', 2, 'Opposable digits allow monkeys to grasp tree branches.', true, '2026-10-12 20:59:30.238', '2026-10-12 20:59:30.238', null, null, null, 'One of the adaptations to life on trees by a monkey is its possession of digits which are', '["extensible","big","opposable","long"]', 'Opposable digits allow monkeys to grasp tree branches.', '{"bold":["Opposable"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('10ea8e5c-bc80-4165-9edb-f3052f296acf', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The clerk refused to <u>answer for</u> the mistakes made by the manager and his assistants.', null, '["reply to","give an answer","accept responsibility for","account for"]', 2, 'Answer for = accept responsibility for.', true, '2026-10-24 01:03:57.306', '2026-10-24 01:03:57.306', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The clerk refused to <u>answer for</u> the mistakes made by the manager and his assistants.', '["reply to","give an answer","<u>accept responsibility for</u>","account for"]', '<b>Answer for</b> = <b>accept responsibility for</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('10f33f4f-877d-4241-8717-64a902710025', 'Physics', 'JAMB', null, 2004, null, 'The pitch of a sound note depends on', null, '["Timbre","Harmonics","Quality","Frequency"]', 3, 'Pitch is determined by the frequency of the sound wave.', true, '2026-10-12 19:15:58.499', '2026-10-12 19:15:58.499', null, null, null, 'The pitch of a sound note depends on', '["Timbre","Harmonics","Quality","Frequency"]', 'Pitch is determined by the frequency of the sound wave.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('10f6214a-b805-4452-be74-6a63657fe245', 'Biology', 'JAMB', null, 2011, null, 'The inheritable characters that are determined by a gene located only on the X-chromosome is', null, '["recessive","sex-linked","homozygous","dominant."]', 1, 'Characters determined by genes on the X-chromosome are sex-linked.', true, '2026-10-12 20:59:43.574', '2026-10-12 20:59:43.574', null, null, null, 'The inheritable characters that are determined by a gene located only on the X-chromosome is', '["recessive","sex-linked","homozygous","dominant."]', 'Characters determined by genes on the X-chromosome are sex-linked.', '{"bold":["sex-linked"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('10f83c66-7418-4659-96bb-7a5705bc74dc', 'Biology', 'JAMB', null, 2026, null, 'The urinary tubules of the kidney function through', null, '["osmosis and diffusion","active transport and osmosis","ultrafiltration and selective reabsorption","active transport and cytoplasmic streaming"]', 2, 'The urinary tubules of the kidney function through ultrafiltration and selective reabsorption. Ultrafiltration occurs in the glomerulus where blood is filtered under pressure, forcing water and small molecules out of the blood. Selective reabsorption occurs along the renal tubules where useful substances (glucose, amino acids, ions, water) are reabsorbed back into the blood. Osmosis, diffusion, and active transport are mechanisms involved but do not define the overall process. Cytoplasmic streaming is not involved in kidney function.', true, '2026-09-09 03:19:08.575', '2026-09-09 03:19:08.575', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('10f89944-75dc-45d2-a782-765484d572c8', 'Biology', 'JAMB', null, 2011, null, 'The adaptive importance of nuptial flight from termite colonies is to', null, '["disperse the reproductives in order to establish new colonies","provide abundant food for birds and other animals during the early rains.","ensure cross-breeding between members of one colony and another.","expel the reproductive so as to provide enough food for other members."]', 0, 'Nuptial flight disperses reproductives to establish new colonies.', true, '2026-10-12 20:59:41.849', '2026-10-12 20:59:41.849', null, null, null, 'The adaptive importance of nuptial flight from termite colonies is to', '["disperse the reproductives in order to establish new colonies","provide abundant food for birds and other animals during the early rains.","ensure cross-breeding between members of one colony and another.","expel the reproductive so as to provide enough food for other members."]', 'Nuptial flight disperses reproductives to establish new colonies.', '{"bold":["disperses reproductives to establish new colonies"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('10fc9d5a-64fb-4018-836f-a48bedbc84d0', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). The principal advised the boy to <u>come to grips with himself</u> if he wanted to do well at the end of his course.', null, '["criticize himself","master his difficulties","Learn to be obedient","Behave himself","Fight with himself"]', 1, '''Come to grips with'' = master.', true, '2026-10-24 01:04:16.213', '2026-10-24 01:04:16.213', null, null, null, '(Choose the most appropriate interpretation). The principal advised the boy to <u>come to grips with himself</u> if he wanted to do well at the end of his course.', '["criticize himself","<u>master his difficulties</u>","Learn to be obedient","Behave himself","Fight with himself"]', '''<b>Come to grips with</b>'' = <b>master</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('11093e7c-ecf8-4852-a821-42dfb3bceb34', 'Physics', 'JAMB', null, 1994, null, 'Two resistors, R₁ = 4 Ω and R₂ = 5 Ω, are connected in parallel across a potential difference. If P₁ and P₂ represent the power dissipated in R₁ and R₂ respectively, the ratio P₁ : P₂ is', null, '["4 : 5","5 : 4","16 : 25","25 : 16"]', 1, 'In parallel the voltage is the same, so P = V²/R. P₁:P₂ = R₂:R₁ = 5:4.', true, '2026-10-12 19:15:40.343', '2026-10-12 19:15:40.343', null, null, null, 'Two resistors, R<sub>1</sub> = 4 Ω and R<sub>2</sub> = 5 Ω, are connected in parallel across a potential difference. If P<sub>1</sub> and P<sub>2</sub> represent the power dissipated in R<sub>1</sub> and R<sub>2</sub> respectively, the ratio P<sub>1</sub> : P<sub>2</sub> is', '["4 : 5","5 : 4","16 : 25","25 : 16"]', 'In parallel the voltage is the same, so P = V<sup>2</sup>/R. P<sub>1</sub>:P<sub>2</sub> = R<sub>2</sub>:R<sub>1</sub> = 5:4.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('110b8da8-33b5-43c0-b716-87862575bf72', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearly opposite in meaning to the word(s) or phrase in italics and underlined. The long straight trunk of the tree is <u>ideal</u> for round wood uses like railway sleepers, rafters and fence posts.', null, '["best","perfect","most unsuitable","satisfactory","poor"]', 2, 'Ideal = most suitable; opposite = most unsuitable.', true, '2026-10-24 07:21:10.501', '2026-10-24 07:21:10.501', null, null, null, 'Choose the option nearly opposite in meaning to the word(s) or phrase in italics and underlined. The long straight trunk of the tree is <u>ideal</u> for round wood uses like railway sleepers, rafters and fence posts.', '["best","perfect","most unsuitable","satisfactory","poor"]', 'Ideal = most suitable; opposite = most unsuitable.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1111f64d-c856-4202-aeb9-5001e5885552', 'English Language', 'JAMB', null, 2007, null, 'Measles <u>------------</u> no longer impossible to manage these days.', null, '["is","are","were","was"]', 0, '''Measles'' singular disease â†’ is.', true, '2026-10-24 01:04:27.425', '2026-10-24 01:04:27.425', null, null, null, 'Measles <u>------------</u> no longer impossible to manage these days.', '["<u>is</u>","are","were","was"]', '''<b>Measles</b>'' singular disease â†’ <b>is</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('11209947-6d11-4750-b3a9-7fc168e35bed', 'English Language', 'JAMB', null, 2024, null, 'Mr Colins does not allow his name to be published in connection with his philanthropy because he ______ publicity.', null, '["wields","lacks","detests","denies"]', 2, '"Detests" means strongly dislikes; it fits the context of avoiding publicity.', true, '2026-09-18 09:23:08.543', '2026-09-18 09:23:08.543', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('112eed7c-9dad-41fe-8bce-3d1e7cca820c', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The explosive growth of world population has not been caused by a <u>sudden</u> increase in human fertility.', null, '["fantastic","gradual","combustible","dangerous"]', 1, 'Sudden = abrupt; opposite = gradual.', true, '2026-10-24 07:21:11.977', '2026-10-24 07:21:11.977', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The explosive growth of world population has not been caused by a <u>sudden</u> increase in human fertility.', '["fantastic","gradual","combustible","dangerous"]', 'Sudden = abrupt; opposite = gradual.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1138119d-ea4d-450c-b4c9-2dcf5b5371b8', 'English Language', 'JAMB', null, 2007, null, 'The number of unemployed graduates in the country <u>_______</u> alarming.', null, '["are","were","is","have been"]', 2, '''The number of'' singular â†’ is.', true, '2026-10-24 01:04:30.099', '2026-10-24 01:04:30.099', null, null, null, 'The number of unemployed graduates in the country <u>_______</u> alarming.', '["are","were","<u>is</u>","have been"]', '''<b>The number of</b>'' singular â†’ <b>is</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('11384952-50e1-4739-9122-e4aa83be5b3e', 'Physics', 'JAMB', null, 1994, null, 'If a solid X floats in liquid P of relative density 2.0 and in liquid Q of relative density 1.5, it can be inferred that the', null, '["Weight of P displaced is greater than that of Q","Weight of P displaced is less than that of Q","Volume of P displaced is greater than that of Q","Volume of P displaced is less than that of Q."]', 3, 'In both cases the weight of liquid displaced equals the weight of X. The denser liquid P has to displace a smaller volume to supply the same upthrust.', true, '2026-10-12 19:15:39.371', '2026-10-12 19:15:39.371', null, null, null, 'If a solid X floats in liquid P of relative density 2.0 and in liquid Q of relative density 1.5, it can be inferred that the', '["Weight of P displaced is greater than that of Q","Weight of P displaced is less than that of Q","Volume of P displaced is greater than that of Q","Volume of P displaced is less than that of Q."]', 'In both cases the weight of liquid displaced equals the weight of X. The denser liquid P has to displace a smaller volume to supply the same upthrust.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('113baa35-01e9-4fb9-bb1a-7b1b30a70431', 'Chemistry', 'JAMB', null, 2026, null, 'The oxidation state of hydrogen in Lithium hydride is?', null, '["-1","+2","0","+1"]', 0, 'In LiH, hydrogen has oxidation state -1.', true, '2026-09-12 11:36:23.594', '2026-09-12 11:36:23.594', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('11458eb4-748d-488c-9c11-a60a7ab92d46', 'English Language', 'JAMB', null, 2024, null, 'John gave a fictitious account of the incident but his son''s account was ______', null, '["probable","compelling","factual","necessary"]', 2, '"Factual" means based on facts, contrasting with "fictitious."', true, '2026-09-18 09:43:02.48', '2026-09-18 09:43:02.48', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('115d5a2a-78a6-4d71-87b6-4fa3ee152c9f', 'Biology', 'JAMB', null, 2026, null, 'Neurons that receive stimuli from the body or internal organs are called', null, '["efferent neurons","afferent neurons","motor neurons","relay neurons"]', 1, 'Afferent (sensory) neurons carry nerve impulses from sensory receptors in the body and internal organs toward the central nervous system (brain and spinal cord). These neurons have specialized receptor endings that detect stimuli such as touch, temperature, pain, and pressure. Efferent (motor) neurons carry impulses away from the CNS to effectors like muscles and glands. Relay neurons (interneurons) connect sensory and motor neurons within the CNS.', true, '2026-09-09 03:18:16.542', '2026-09-09 03:18:16.542', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1163b421-1848-4d4c-b741-68388ae7ca25', 'Economics', 'JAMB', null, 2026, null, 'In a public company, shares are', null, '["sold to one person only","distributed freely","advertised to the members of the public for subscription","disposed of by the chief executive"]', 2, 'In a public company, shares are advertised to the members of the public for subscription. A public limited liability company (PLC) can offer its shares to the general public through the stock exchange. This allows the company to raise large amounts of capital from many investors. Shares are not sold to one person only, distributed freely, or disposed of by the chief executive. The public offer must comply with regulatory requirements.', true, '2026-09-10 10:42:55.988', '2026-09-10 10:42:55.988', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('11673a62-fb6e-494c-95e9-f1d29cbe56e3', 'Literature in English', 'JAMB', null, 2026, null, 'One major effect of migration on Finaba is that it', null, '["completely erases his traditional values","strengthens his understanding of his identity","makes him reject all foreign influences","isolates him permanently from his homeland"]', 1, 'Migration strengthens Finaba''s understanding of his identity.', true, '2026-09-12 11:04:25.044', '2026-09-12 11:04:25.044', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1168b3a5-afa4-44a7-bff6-193c9b240e5c', 'Biology', 'JAMB', null, 2010, null, 'The dominant phase in the life cycle of a fern is the', null, '["gametophyte","prothallus","sporophyte","antheridium"]', 2, 'The dominant phase in a fern''s life cycle is the sporophyte.', true, '2026-10-12 20:59:38.84', '2026-10-12 20:59:38.84', null, null, null, 'The dominant phase in the life cycle of a fern is the', '["gametophyte","prothallus","sporophyte","antheridium"]', 'The dominant phase in a fern''s life cycle is the sporophyte.', '{"bold":["sporophyte"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1173a3e6-92c0-47e9-8c03-1d1bc57e31bc', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The president made a <u>passionate</u> appeal for calm.', null, '["inflamed","disturbing","intense","lively"]', 2, 'Passionate = intense.', true, '2026-10-24 01:03:56.666', '2026-10-24 01:03:56.666', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The president made a <u>passionate</u> appeal for calm.', '["inflamed","disturbing","<u>intense</u>","lively"]', '<b>Passionate</b> = <b>intense</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('11751c08-c0ba-48a6-8081-3614afb2cbe8', 'Hausa', 'JAMB', null, 2010, null, 'Su wa suka fi yin wakoKin talla?', null, '["''Yan yara.","''Yan maza.","''Yan galura.","''Yan mata."]', 3, '''Yan mata suka fi yin wakoKin talla.', true, '2026-10-13 10:37:24.892', '2026-10-13 10:37:24.892', null, null, null, 'Su wa suka fi yin wakoKin talla?', '["''Yan yara.","''Yan maza.","''Yan galura.","''Yan mata."]', '''Yan mata suka fi yin wakoKin talla.', '{"bold":["''Yan mata"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1176b5b0-d90e-426c-9cdd-0a1800107e4d', 'Biology', 'JAMB', null, 2003, null, 'One distinctive feature in the life history of liverworts is that they exhibit', null, '["alternation of generation","vegetative reproduction","asexual reproduction","sexual reproduction"]', 0, 'Liverworts exhibit alternation of generation.', true, '2026-10-12 20:59:32.038', '2026-10-12 20:59:32.038', null, null, null, 'One distinctive feature in the life history of liverworts is that they exhibit', '["alternation of generation","vegetative reproduction","asexual reproduction","sexual reproduction"]', 'Liverworts exhibit alternation of generation.', '{"bold":["alternation of generation"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('117714d5-2039-43c2-b2d1-817e8d57ba64', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Shiphrah and Puah refused to obey Pharaoh because...', null, '["Pharaoh wanted to kill the Israelite babies","Pharaoh wanted to control the Hebrew population","They were kinsmen of the Israelites","They were women who feared God"]', 3, 'Exodus 1:17 states: ''But the midwives feared God, and did not do as the king of Egypt commanded them, but saved the male children alive.''', true, '2026-09-09 17:18:26.619', '2026-09-09 17:18:26.619', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1185d4dd-41c4-4182-aca3-341828905235', 'English Language', 'JAMB', null, 2024, null, 'According to the passage, astronauts', null, '["are always successful","always do what is expected of them","know they may not return from their journey into space","have courage and mental stability"]', 2, 'The passage states that astronauts may have a slight foreboding about the contingency of their non-return, meaning they know they may not return.', true, '2026-09-18 09:43:01.997', '2026-09-18 09:43:01.997', null, null, 'COMPREHENSION', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('118648ef-72f4-474b-a23b-e02cb67df2f0', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). Ado is <u>one of the backwoodsmen</u>', null, '["He is one of those that live in a distant and underdeveloped area","He is one of the active members of the community","He is one of the honest men that live in the community","He is one of those that live in the most developed part of the city"]', 0, '''Backwoodsmen'' = people from distant underdeveloped area.', true, '2026-10-24 01:04:24.579', '2026-10-24 01:04:24.579', null, null, null, '(Choose the most appropriate interpretation). Ado is <u>one of the backwoodsmen</u>', '["<u>He is one of those that live in a distant and underdeveloped area</u>","He is one of the active members of the community","He is one of the honest men that live in the community","He is one of those that live in the most developed part of the city"]', '''<b>Backwoodsmen</b>'' = <b>people from distant underdeveloped area</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1195c8c9-dc63-40ad-9dcd-7fc70bcfa0e3', 'English Language', 'JAMB', null, 2024, null, 'Under-employment among the villagers refers to', null, '["lack of sufficient jobs for everyone","low productivity when working","fewer people for many jobs","more people for fewer jobs"]', 3, 'Under-employment in this context means more people available for fewer jobs, leading to low productivity and occasional work.', true, '2026-09-18 09:23:08.215', '2026-09-18 09:23:08.215', null, null, 'COMPREHENSION', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('11a449b1-bccb-4f5b-89fb-7fd42691cb4f', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Eli fell down and died because of the', null, '["defeat of the Israelites","behavior of his delinquent children","capture of the Ark of Covenant","death of his two children"]', 2, 'Eli fell down and died because of the capture of the Ark of Covenant. When a messenger told him that Israel had been defeated, his sons were dead, and the Ark of God had been captured, Eli fell backward from his seat and died.', true, '2026-09-12 09:46:12.576', '2026-09-12 09:46:12.576', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('11b2fcc3-dcf6-4ed1-a0ca-5451e2b8c951', 'Physics', 'JAMB', null, 1992, null, 'At constant pressure, the density of a fixed mass of gas is', null, '["Constant with temperature","Proportional to its volume","Inversely proportional to its temperature","Independent of its volume"]', 2, 'At constant pressure V is proportional to T. Density = mass/V, so density is inversely proportional to the absolute temperature.', true, '2026-10-12 19:15:35.39', '2026-10-12 19:15:35.39', null, null, null, 'At constant pressure, the density of a fixed mass of gas is', '["Constant with temperature","Proportional to its volume","Inversely proportional to its temperature","Independent of its volume"]', 'At constant pressure V is proportional to T. Density = mass/V, so density is inversely proportional to the absolute temperature.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('11be642f-cef9-4221-9cca-caf35d194e8e', 'Physics', 'JAMB', null, 1999, null, 'The temperature gradient across a copper rod of thickness 0.02 m, maintained at two temperature junctions of 20 °C and 80 °C respectively is', null, '["3.0 x 10² K m⁻¹","3.0 x 10³ K m⁻¹","5.0 x 10³ K m⁻¹","3.0 x 10⁴ K m⁻¹"]', 1, 'Temperature gradient = Δθ/thickness = 60/0.02 = 3.0 x 10³ K m⁻¹.', true, '2026-10-12 19:15:47.93', '2026-10-12 19:15:47.93', null, null, null, 'The temperature gradient across a copper rod of thickness 0.02 m, maintained at two temperature junctions of 20 °C and 80 °C respectively is', '["3.0 x 10<sup>2</sup> K m<sup>-1</sup>","3.0 x 10<sup>3</sup> K m<sup>-1</sup>","5.0 x 10<sup>3</sup> K m<sup>-1</sup>","3.0 x 10<sup>4</sup> K m<sup>-1</sup>"]', 'Temperature gradient = Δθ/thickness = 60/0.02 = 3.0 x 10<sup>3</sup> K m<sup>-1</sup>.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('11c07215-ecb9-4c4d-82e9-1c96d6f7a9db', 'Financial Accounting', 'UTME', null, 2001, null, 'What is the cash balance?', 'https://res.cloudinary.com/kwi1uv0g/image/upload/v1791841980/questions/b96fewzclfpctd0d0cql.jpg', '["N12,095","N12,590","N12,905","N12,950"]', 3, 'The cash balance is N12,950.', true, '2026-10-12 22:00:04.263', '2026-10-12 22:00:04.263', null, null, null, 'What is the cash balance?', '["N12,095","N12,590","N12,905","<b>N12,950</b>"]', 'The cash balance is <b>N12,950</b>.', '{"bold":["N12,950"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('11cdac4e-70ca-43e5-a0af-b71e74cfe09d', 'English Language', 'JAMB', null, 2024, null, 'If I ______ what actually happened, I would have punished him', null, '["had heard","heard","have had","have heard","can hear"]', 0, 'The third conditional uses "had heard" in the if-clause.', true, '2026-09-18 09:43:02.529', '2026-09-18 09:43:02.529', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('11d53ad0-b1b7-406a-a569-f22284d61ee4', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Before the call of James and John, Jesus met them helping their Father to...', null, '["Catch fish in the sea","Mend the fishing nets","Collect Tax","Bury the dead"]', 1, 'According to Matthew 4:21 and Mark 1:19, Jesus saw James and John, sons of Zebedee, in a boat with their father mending their nets when He called them.', true, '2026-09-09 17:18:23.67', '2026-09-09 17:18:23.67', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('11efe144-fc50-4d7f-ba06-76a0a9ae48fe', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The discussion became <u>animated</u>.', null, '["specialized","lively","intellectual","unruly"]', 1, 'Animated = lively.', true, '2026-10-24 01:01:41.552', '2026-10-24 01:01:41.552', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The discussion became <u>animated</u>.', '["specialized","<u>lively</u>","intellectual","unruly"]', '<b>Animated</b> = <b>lively</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('121387f8-895a-4a89-b3c7-8f38ffb5d965', 'General Mathematics', 'JAMB', null, 2026, null, 'Find the 10th term of the AP: 3, 7, 11, 15, ...', null, '["35","38","39","43"]', 2, 'a=3, d=4. T10 = 3 + 9(4) = 39.', true, '2026-09-12 11:44:14.976', '2026-09-12 11:44:14.976', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('122838d0-ce72-4c83-8116-6f67bd43fa38', 'Literature in English', 'JAMB', null, 2026, null, 'The list of all the characters in a play is called the', null, '["Dramatis personae","Cast list","Crew","Character sketch"]', 0, 'The list of all the characters in a play is called the dramatis personae. This Latin term means ''persons of the drama'' and is traditionally listed at the beginning of a play. It introduces the characters and sometimes provides brief descriptions of their roles. The cast list refers to the actors assigned to roles, the crew is the backstage team, and a character sketch is a detailed description of a character.', true, '2026-09-10 10:45:33.861', '2026-09-10 10:45:33.861', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('122ae965-9282-4c80-a7f8-e4fce6050182', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'The name “Moses” means...', null, '["the loved child of Pharaoh","God heard our groaning","I have been a sojourner in a foreign land","because I drew him out of water"]', 3, 'Exodus 2:10 explains that Pharaoh''s daughter named him Moses saying, ''Because I drew him out of the water.''', true, '2026-09-09 17:18:25.308', '2026-09-09 17:18:25.308', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('122bd8b7-4f9a-4dab-9463-44b1d55e8125', 'Biology', 'JAMB', null, 2003, null, 'The processes of water loss and intake indicated by the arrows labelled I and II are respectively', null, '["exhalation and osmosis","urination and diffusion","osmosis and diffusion","evaporation and osmosis"]', 3, 'The arrows represent evaporation and osmosis.', true, '2026-10-12 20:59:32.167', '2026-10-12 20:59:32.167', null, null, null, 'The processes of water loss and intake indicated by the arrows labelled I and II are respectively', '["exhalation and osmosis","urination and diffusion","osmosis and diffusion","evaporation and osmosis"]', 'The arrows represent evaporation and osmosis.', '{"bold":["evaporation and osmosis"],"italic":[],"underline":[],"fillBlanks":[]}');
