insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('123772f6-3775-4e01-bf90-89e15d850654', 'testing', 'JAMB', null, 2024, null, 'Hardly had the match begun ..... the captain of the team got injured.', null, '["than","when","that","while"]', 1, '''Hardly ... when''.', true, '2026-10-31 16:48:53.161', '2026-10-31 16:48:53.161', null, null, null, 'Hardly had the match begun ..... the captain of the team got injured.', '["than","when","that","while"]', '''Hardly ... when''.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('123b332c-77bd-454a-8144-ba1e516460a8', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). After careful investigation, the police found no <u>iota</u> of truth in Ibrahim''s allegations.', null, '["quota","grain","evidence","statement"]', 1, '''No iota of truth'' = no grain of truth.', true, '2026-10-24 01:02:06.433', '2026-10-24 01:02:06.433', null, null, null, '(Choose the most appropriate interpretation). After careful investigation, the police found no <u>iota</u> of truth in Ibrahim''s allegations.', '["quota","<u>grain</u>","evidence","statement"]', '''<b>No iota of truth</b>'' = <b>no grain of truth</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('123f1b2e-2419-428e-85b5-1bd3c19bd634', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The stockbroker said it was <u>an astute</u> move to sell the shares then.', null, '["a bad","a shrewd","an unprofitable","an insincere"]', 1, 'Astute = shrewd.', true, '2026-10-24 01:04:10.095', '2026-10-24 01:04:10.095', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The stockbroker said it was <u>an astute</u> move to sell the shares then.', '["a bad","<u>a shrewd</u>","an unprofitable","an insincere"]', '<b>Astute</b> = <b>a shrewd</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1244c70f-2cfa-471e-8857-78a841d68f9d', 'Literature in English', 'JAMB', null, 2026, null, 'Which device is used in ''I have learned to say Glad to meet you without being glad''', null, '["paradox","hyperbole","metonymy","personification"]', 0, 'The device is paradox.', true, '2026-09-12 11:13:43.753', '2026-09-12 11:13:43.753', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('124b7b78-36a8-4ac3-896a-b508e89b1590', 'Biology', 'JAMB', null, 2026, null, 'Absorption of water from faecal matter occurs in the', null, '["colon","jejunum","duodenum","caecum"]', 0, 'The absorption of water from faecal matter occurs in the colon. The colon (large intestine) is responsible for absorbing water and electrolytes from the remaining indigestible food matter, converting it from liquid to solid feces. The jejunum and duodenum are parts of the small intestine, primarily involved in nutrient absorption. The caecum is the beginning of the large intestine, where the appendix is attached. The colon''s reabsorption of water is essential for maintaining body fluid balance and producing formed feces.', true, '2026-09-09 03:18:49.508', '2026-09-09 03:18:49.508', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('124e16e6-2cd0-49b7-85fb-e2c1d6261512', 'Physics', 'JAMB', null, 1999, null, 'A particle of mass 10⁻² kg is fixed to the tip of a fan blade which rotates with angular velocity of 100 rad s⁻¹. If the radius of the blade is 0.2 m, the centripetal force is', null, '["2 N","20 N","200 N","400 N"]', 1, 'F = mω²r = 10⁻² x 100² x 0.2 = 20 N.', true, '2026-10-12 19:15:47.18', '2026-10-12 19:15:47.18', null, null, null, 'A particle of mass 10<sup>-2</sup> kg is fixed to the tip of a fan blade which rotates with angular velocity of 100 rad s<sup>-1</sup>. If the radius of the blade is 0.2 m, the centripetal force is', '["2 N","20 N","200 N","400 N"]', 'F = mω<sup>2</sup>r = 10<sup>-2</sup> x 100<sup>2</sup> x 0.2 = 20 N.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('12577776-2711-4418-bfbe-435f5b0c296c', 'English Language', 'JAMB', null, 2024, null, '12', null, '["back down","hold out","keep up","go away"]', 0, 'Workers will soon back down (give in) if they are not serious.', true, '2026-09-18 10:17:48.799', '2026-09-18 10:17:48.799', '274e150d-fca1-4c72-9c33-e5e119534874', 12, 'CLOZE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1258603a-728f-496a-afdd-2a01c0a92c5b', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'King Josiah was killed by Pharaoh Neco in a battle at...', null, '["Megiddo","Egypt","Syria","Magdallah"]', 0, '2 Kings 23:29-30 records King Josiah marching out to meet Pharaoh Neco at Megiddo, where Neco killed him.', true, '2026-09-09 17:18:27.004', '2026-09-09 17:18:27.004', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('125aaf11-7cc5-492a-a768-51116527fda5', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). His attempts were <u>nipped in the bud</u>.', null, '["unsuccessful","cut short","frustrated","disqualified"]', 1, '''Nipped in the bud'' = stopped early.', true, '2026-10-24 01:02:02.857', '2026-10-24 01:02:02.857', null, null, null, '(Choose the most appropriate interpretation). His attempts were <u>nipped in the bud</u>.', '["unsuccessful","<u>cut short</u>","frustrated","disqualified"]', '''<b>Nipped in the bud</b>'' = <b>stopped early</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('126048ae-ce61-4f90-853d-af04e57583ca', 'Literature in English', 'JAMB', null, 2026, null, 'The dominant feeling in the passage is that of', null, '["hostility","anger","anxiety","bitterness"]', 2, 'The dominant feeling is anxiety.', true, '2026-09-12 11:11:08.917', '2026-09-12 11:11:08.917', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1261417e-9fa6-4527-a16a-0215a59cba20', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). The senator had the habit of <u>setting the cat among the pigeons</u> whenever matters concerning his constituency came up for debate.', null, '["illuminating issues that are clear","monopolizing the discussion","making frequent mistakes in the nature of points of correction","introducing elements of controversy and confusion"]', 3, '''Set the cat among the pigeons'' = introduce controversy.', true, '2026-10-24 01:04:19.325', '2026-10-24 01:04:19.325', null, null, null, '(Choose the most appropriate interpretation). The senator had the habit of <u>setting the cat among the pigeons</u> whenever matters concerning his constituency came up for debate.', '["illuminating issues that are clear","monopolizing the discussion","making frequent mistakes in the nature of points of correction","<u>introducing elements of controversy and confusion</u>"]', '''<b>Set the cat among the pigeons</b>'' = <b>introduce controversy</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1267eaa2-8d87-47f6-a61f-5b8a8860269e', 'Physics', 'JAMB', null, 2026, null, 'The percentage of the original nuclei of the sample of a radioactive substance left after 5 half-lives is', null, '["8%","5%","3%","1%"]', 2, 'After 5 half-lives, fraction remaining = (1/2)⁵ = 1/32 = 0.03125 = 3.125% ≈ 3%.', true, '2026-09-10 10:56:50.003', '2026-09-10 10:56:50.003', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('12682c6a-456d-4926-ae35-8403a0984494', 'Physics', 'JAMB', null, 1995, null, 'The equation PxVyTz = constant is Charles'' law when', null, '["x = 1, y = -1, z = 1","x = 0, y = 1, z = -1","x = 1, y = 0, z = -1","x = 0, y = 1, z = 1."]', 1, 'Charles'' law says V/T is constant (at constant pressure), i.e. V¹T⁻¹ = constant, with no pressure term. So x = 0, y = 1, z = -1.', true, '2026-10-12 19:15:41.254', '2026-10-12 19:15:41.254', null, null, null, 'The equation P<sup>x</sup>V<sup>y</sup>T<sup>z</sup> = constant is Charles'' law when', '["x = 1, y = -1, z = 1","x = 0, y = 1, z = -1","x = 1, y = 0, z = -1","x = 0, y = 1, z = 1."]', 'Charles'' law says V/T is constant (at constant pressure), i.e. V<sup>1</sup>T<sup>-1</sup> = constant, with no pressure term. So x = 0, y = 1, z = -1.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1268dd9d-4205-4f3d-8326-f6c44dd3d8bd', 'Biology', 'JAMB', null, 2026, null, 'Where is food stored in a maize seed?', null, '["cotyledon","endosperm","pericarp","endocarp"]', 1, 'In a maize seed, food is stored in the endosperm. Maize is a monocot and the endosperm is the major food storage tissue, making up most of the seed''s mass. The cotyledon (scutellum in monocots) is small and absorbs nutrients from the endosperm during germination. The pericarp is the fruit wall of the grain. The endocarp is the inner layer of the fruit wall. The starchy endosperm provides nourishment for the germinating embryo, and this is why maize is classified as an endospermous seed.', true, '2026-09-09 03:18:39.36', '2026-09-09 03:18:39.36', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('126eaf1a-1468-427e-8159-6b35cb2a92cb', 'Economics', 'JAMB', null, 2026, null, 'If income rises from 200 to 250 and the amount spent on good X falls from 30 to 27, then good X is', null, '["income elastic good","a normal good","An inferior good","demand elastic good"]', 2, 'Good X is an inferior good. When income rises from 200 to 250 (a 25% increase), the amount spent on good X falls from 30 to 27 (a 10% decrease). This shows a negative income elasticity of demand—as income increases, demand for the good decreases. Inferior goods are those for which consumers switch to better alternatives as their income rises. Examples include cheap cuts of meat and second-hand clothing.', true, '2026-09-10 10:42:55.614', '2026-09-10 10:42:55.614', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1277e6e1-0e32-4c76-87f3-8fb779cc38e1', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. As a journalist, Bala has always has <u>a nose for stories</u>.', null, '["cynical statement","an instinct","a command","soft comment"]', 1, 'A nose for stories = an instinct.', true, '2026-10-24 01:04:11.009', '2026-10-24 01:04:11.009', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. As a journalist, Bala has always has <u>a nose for stories</u>.', '["cynical statement","<u>an instinct</u>","a command","soft comment"]', 'A <b>nose for stories</b> = <b>an instinct</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('127cb2b3-d473-44cf-b6ec-58be5dbc14d6', 'Physics', 'JAMB', null, 1985, null, 'Which of the following is NOT a force?', null, '["Friction","Tension","Upthrust","Weight","Impulse."]', 4, 'Friction, tension, upthrust and weight are all forces. Impulse is force x time (a change of momentum).', true, '2026-10-12 19:15:20.878', '2026-10-12 19:15:20.878', null, null, null, 'Which of the following is <b>NOT</b> a force?', '["Friction","Tension","Upthrust","Weight","Impulse."]', 'Friction, tension, upthrust and weight are all forces. Impulse is force x time (a change of momentum).', '{"bold":["NOT"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1281b04c-3fa4-4dc7-a68f-a113456d0d34', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). Publishing as a business venture has become <u>a hot potato</u> in Nigeria.', null, '["unpleasant","profitable","unacceptable","expensive"]', 0, '''A hot potato'' = controversial unpleasant issue.', true, '2026-10-24 01:02:09.083', '2026-10-24 01:02:09.083', null, null, null, '(Choose the most appropriate interpretation). Publishing as a business venture has become <u>a hot potato</u> in Nigeria.', '["<u>unpleasant</u>","profitable","unacceptable","expensive"]', '''A <b>hot potato</b>'' = <b>controversial unpleasant issue</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('12820867-ccb4-4c8f-84a0-4517f13b9d3c', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The player <u>writhed</u> in pain after the fall.', null, '["cried out","remained still","walked out","shook violently"]', 1, 'Writhed = twisted; opposite = remained still.', true, '2026-10-24 07:21:24.627', '2026-10-24 07:21:24.627', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The player <u>writhed</u> in pain after the fall.', '["cried out","remained still","walked out","shook violently"]', 'Writhed = twisted; opposite = remained still.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('12867d1e-abb0-47d6-9fde-9e8262dfe69b', 'English Language', 'JAMB', null, 2024, null, 'Ensure you ______ my office before going to school', null, '["come past","pass into","call at","call by"]', 2, '"Call at" means to visit a place briefly.', true, '2026-09-18 09:43:02.59', '2026-09-18 09:43:02.59', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('12879b50-ab66-4796-9020-0f6a941bf1ed', 'General Mathematics', 'JAMB', null, 2026, null, 'If tan x = 4/3, calculate sin²x - cos²x', null, '["24/25","16/25","9/25","7/25"]', 3, 'tan x = 4/3, so sin x = 4/5, cos x = 3/5. sin²x - cos²x = (16/25) - (9/25) = 7/25.', true, '2026-09-10 10:48:20.276', '2026-09-10 10:48:20.276', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('129d29cf-714e-4887-9d51-d6e8e3651adb', 'Physics', 'JAMB', null, 1988, null, 'Which of the following symbolic representations is correct for an atom X with 22 electrons and 43 neutrons?', null, '["⁴³₂₂X","²²₄₃X","⁶⁵₄₂X","⁶⁵₂₂X."]', 3, 'Atomic number Z = 22 (protons = electrons), mass number A = 22 + 43 = 65, so the atom is ⁶⁵₂₂X.', true, '2026-10-12 19:15:28.601', '2026-10-12 19:15:28.601', null, null, null, 'Which of the following symbolic representations is correct for an atom X with 22 electrons and 43 neutrons?', '["<sup>43</sup><sub>22</sub>X","<sup>22</sup><sub>43</sub>X","<sup>65</sup><sub>42</sub>X","<sup>65</sup><sub>22</sub>X."]', 'Atomic number Z = 22 (protons = electrons), mass number A = 22 + 43 = 65, so the atom is <sup>65</sup><sub>22</sub>X.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('12a57df6-6701-4954-bb8c-e230cde54832', 'Chemistry', 'JAMB', null, 2026, null, 'The main product of incomplete combustion of carbon is:', null, '["CO₂","CO","CH₄","C"]', 1, 'Incomplete combustion of carbon produces carbon monoxide (CO).', true, '2026-09-12 11:35:53.478', '2026-09-12 11:35:53.478', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('12ae62fa-6677-4bfb-8585-3a6bf78b377b', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'According to Paul, the second coming of Jesus Christ will be preceded by the coming of', null, '["Elijah, the prophet","John the Baptist","the man of lawlessness","the man of righteousness"]', 2, 'According to Paul in 2 Thessalonians 2:3, the second coming of Jesus Christ will be preceded by the coming of the man of lawlessness, the son of perdition, who opposes and exalts himself against every so-called god.', true, '2026-09-12 09:46:13.932', '2026-09-12 09:46:13.932', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('12af4c82-0548-46ab-9410-b14ae832eb6a', 'Literature in English', 'JAMB', null, 2026, null, 'What is the central subject matter of the poem?', null, '["celebration of the sea''s beauty and power","an exploration of the history of navigation and maritime trade","a lament on human brutality and environmental decay as witnessed by the sea","a historical account of the Titanic disaster"]', 2, 'The central subject is a lament on human brutality and environmental decay.', true, '2026-09-12 11:07:23.023', '2026-09-12 11:07:23.023', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('12b525a9-d400-41e5-8e38-76ceb9ea4347', 'Physics', 'JAMB', null, 2002, null, 'If tension is maintained on a stretched string of length 0.6 m, such that its fundamental frequency of 220 Hz is excited, determine the velocity of the transverse wave in the string.', null, '["264 m s⁻¹","132 m s⁻¹","66 m s⁻¹","528 m s⁻¹"]', 0, 'For the fundamental λ = 2L = 1.2 m. v = fλ = 220 x 1.2 = 264 m s⁻¹.', true, '2026-10-12 19:15:53.432', '2026-10-12 19:15:53.432', null, null, null, 'If tension is maintained on a stretched string of length 0.6 m, such that its fundamental frequency of 220 Hz is excited, determine the velocity of the transverse wave in the string.', '["264 m s<sup>-1</sup>","132 m s<sup>-1</sup>","66 m s<sup>-1</sup>","528 m s<sup>-1</sup>"]', 'For the fundamental λ = 2L = 1.2 m. v = fλ = 220 x 1.2 = 264 m s<sup>-1</sup>.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('12b62b50-e661-43bd-a36c-f12092cd38cc', 'English Language', 'JAMB', null, 2024, null, 'Employees demand higher wages, better overtime pay so as to improve the _4_ of living.', null, '["level","standard","class","wishes"]', 1, '"Standard of living" is the fixed expression.', true, '2026-09-18 09:23:08.09', '2026-09-18 09:23:08.09', null, null, 'CLOZE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('12bf0cc0-ca9f-4bd2-877a-00a5d10e651e', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The professor discussed a number of <u>abstruse</u> topics.', null, '["irrelevant","useful","esoteric","relevant"]', 2, 'Abstruse = esoteric/difficult to understand.', true, '2026-10-24 01:04:02.596', '2026-10-24 01:04:02.596', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The professor discussed a number of <u>abstruse</u> topics.', '["irrelevant","useful","<u>esoteric</u>","relevant"]', '<b>Abstruse</b> = <b>esoteric</b>/difficult to understand.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('12eaf299-6936-4826-9afb-dde59e04ddbd', 'English Language', 'JAMB', null, 2007, null, 'All <u>------------</u> well with Peter.', null, '["are not","have not been","were not","is not"]', 3, 'Idiom ''all is well'' â†’ singular is.', true, '2026-10-24 01:02:11.898', '2026-10-24 01:02:11.898', null, null, null, 'All <u>------------</u> well with Peter.', '["are not","have not been","were not","<u>is not</u>"]', 'Idiom ''all <b>is</b> well'' â†’ singular <b>is</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('12ee2cef-832f-42f4-8bdc-908fca18878c', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Teachers of music believe in its <u>therapeutic</u> effect.', null, '["lyrical","healing","sound","rhythmic"]', 1, 'Therapeutic = healing.', true, '2026-10-24 01:01:51.611', '2026-10-24 01:01:51.611', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Teachers of music believe in its <u>therapeutic</u> effect.', '["lyrical","<u>healing</u>","sound","rhythmic"]', '<b>Therapeutic</b> = <b>healing</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('12ee5635-8982-4a43-9a32-60672fb3f264', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Many people used to live in <u>poverty</u>.', null, '["the slums","instability","want","difficulty"]', 2, 'Poverty = want.', true, '2026-10-24 01:04:06.221', '2026-10-24 01:04:06.221', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Many people used to live in <u>poverty</u>.', '["the slums","instability","<u>want</u>","difficulty"]', '<b>Poverty</b> = <b>want</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('12fd1a39-cd26-4e7d-9f09-a70b734f6726', 'English Language', 'JAMB', null, 2024, null, 'When the striking workers were threatened with dismissal, they decided to make a virtue of necessity. This means that they', null, '["all resigned","continue the strike action","had to call off the strike","accused some of their colleagues of treachery"]', 2, '"Make a virtue of necessity" means to do willingly what you must do anyway.', true, '2026-09-18 09:43:02.488', '2026-09-18 09:43:02.488', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('12fff0ff-3c91-4fd5-bc68-0a7923d7d9e1', 'Physics', 'JAMB', null, 2026, null, 'A body weighing 80N stands in an elevator that is about to move. The force exerted by the floor on the body as the elevator moves upwards with an acceleration of 5ms⁻² is', null, '["160N","120N","80N","40N"]', 1, 'Apparent weight = m(g+a). m = 80/10 = 8kg. Apparent weight = 8(10+5) = 8 × 15 = 120N.', true, '2026-09-10 10:56:45.792', '2026-09-10 10:56:45.792', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('13045949-79fe-45f5-957e-817e80d14691', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'The Holiness of God was mostly emphasized by...', null, '["Amos","Hosea","Jeremiah","Isaiah"]', 3, 'Isaiah frequently refers to God as ''The Holy One of Israel'' (e.g., Isaiah 6:3) and centers his prophetic message around God''s absolute holiness.', true, '2026-09-09 17:18:24.709', '2026-09-09 17:18:24.709', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1308813a-653e-4ca4-92cb-c3f8d1bac9b9', 'English Language', 'JAMB', null, 2007, null, 'The university has been TEMPORARILY closed.', null, '["has the college been temporarily closed?","has the University been temporarily opened?","has the university been Permanently closed?","has the university been Permanently opened?"]', 0, 'Correct question form retains meaning; ''college'' is synonym for university.', true, '2026-10-25 18:25:07.062', '2026-10-25 18:25:07.062', null, null, null, 'The university has been TEMPORARILY closed.', '["has the college been temporarily closed?","has the University been temporarily opened?","has the university been Permanently closed?","has the university been Permanently opened?"]', 'Correct question form retains meaning; ''college'' is synonym for university.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('13098aa2-644d-49c7-8684-8bd96f2ef192', 'Physics', 'JAMB', null, 1998, null, 'The electrochemical equivalent of a metal is 1.3 x 10⁻⁷ kg C⁻¹. The mass of the metal which 2.0 x 10⁴ C of electricity will deposit from a suitable electrolyte is', null, '["6.5 x 10⁻² kg","2.6 x 10⁻² kg","6.5 x 10⁻³ kg","2.6 x 10⁻³ kg"]', 3, 'm = zQ = 1.3 x 10⁻⁷ x 2.0 x 10⁴ = 2.6 x 10⁻³ kg.', true, '2026-10-12 19:15:46.751', '2026-10-12 19:15:46.751', null, null, null, 'The electrochemical equivalent of a metal is 1.3 x 10<sup>-7</sup> kg C<sup>-1</sup>. The mass of the metal which 2.0 x 10<sup>4</sup> C of electricity will deposit from a suitable electrolyte is', '["6.5 x 10<sup>-2</sup> kg","2.6 x 10<sup>-2</sup> kg","6.5 x 10<sup>-3</sup> kg","2.6 x 10<sup>-3</sup> kg"]', 'm = zQ = 1.3 x 10<sup>-7</sup> x 2.0 x 10<sup>4</sup> = 2.6 x 10<sup>-3</sup> kg.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('130bcdd5-9b96-450e-ac25-6d7ae00d82cd', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). Had she known he was a high-way robber she would not have married him. This means', null, '["she married him before she knew he was a robber","she knew he was a robber when she married him","she did not marry him because she was a robber","she refused to marry the man when she knew he was a robber","she was a robber marrying a highway robber"]', 0, 'Third conditional shows she married him without knowing.', true, '2026-10-24 01:02:00.667', '2026-10-24 01:02:00.667', null, null, null, '(Choose the most appropriate interpretation). Had she known he was a high-way robber she would not have married him. This means', '["<u>she married him before she knew he was a robber</u>","she knew he was a robber when she married him","she did not marry him because she was a robber","she refused to marry the man when she knew he was a robber","she was a robber marrying a highway robber"]', 'Third conditional shows she married him <b>without knowing</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('131df95b-2745-4de3-89e2-143fdc510661', 'Chemistry', 'JAMB', null, 2026, null, 'Which bond is strongest?', null, '["Ionic","Covalent","Hydrogen","Metallic"]', 1, 'Covalent bonds are typically the strongest among the options.', true, '2026-09-12 11:33:00.506', '2026-09-12 11:33:00.506', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('132583ee-a3bb-450d-bff3-373f9d76494e', 'Literature in English', 'JAMB', null, 2026, null, 'When characters talk to each other, it is known as', null, '["dialogue","Monologue","epilogue","soliloquy"]', 0, 'Dialogue is when characters talk to each other.', true, '2026-09-12 11:05:54.718', '2026-09-12 11:05:54.718', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('132dc777-1306-4615-8fb5-e1a071c93482', 'Literature in English', 'JAMB', null, 2026, null, 'In The Digging, the line ''Between my finger and my thumb / The squat pen rests; snug as a gun'' suggests that the pen', null, '["Is a weapon of violence","Symbolises the poet''s tool of labour","Represents political struggle","Is inferior to manual labour"]', 1, 'The pen symbolizes the poet''s tool of labour.', true, '2026-09-12 11:05:13.835', '2026-09-12 11:05:13.835', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('13310cd2-0a82-479e-b407-0d9430730ef9', 'English Language', 'JAMB', null, 2007, null, 'Their high <u>__________</u> was an advantage.', null, '["moral","morality","morale","morals"]', 2, 'Correct spelling and meaning: morale.', true, '2026-10-24 07:21:32.641', '2026-10-24 07:21:32.641', null, null, null, 'Their high <u>__________</u> was an advantage.', '["moral","morality","morale","morals"]', 'Correct spelling and meaning: morale.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('13313a82-54dc-4670-a328-9836f7bc2cbe', 'Literature in English', 'JAMB', null, 2026, null, 'The poem can be read as a critique of', null, '["modern education","political corruption","the loss of authentic identity","the decline of family values"]', 2, 'The poem ''Once Upon A Time'' by Gabriel Okara can be read as a critique of the loss of authentic identity. The poem laments how people have learned to wear ''many faces'' and disguise their true feelings. The speaker yearns for the innocence and sincerity of childhood, before societal pressures forced him to become hypocritical. It is not about modern education, political corruption, or family values. The poem deals with cultural loss and personal authenticity.', true, '2026-09-10 10:45:35.098', '2026-09-10 10:45:35.098', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('134955c7-d260-4058-87ec-8cc4c9e66604', 'Literature in English', 'JAMB', null, 2026, null, 'The title ''New Tongue'' in the poem mainly refers to', null, '["learning a foreign language","the loss and replacement of one''s native language","a speech defect","the language of animals"]', 1, 'The title refers to the loss and replacement of one''s native language.', true, '2026-09-12 11:10:21.459', '2026-09-12 11:10:21.459', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('134b71cb-95b6-4935-8424-4973376fd2c2', 'Biology', 'JAMB', null, 2013, null, 'A plant tissue that carries water and mineral salts is the', null, '["Cortex","Phloem","Cambium","Xylem"]', 3, 'Xylem carries water and mineral salts.', true, '2026-10-12 20:59:47.232', '2026-10-12 20:59:47.232', null, null, null, 'A plant tissue that carries water and mineral salts is the', '["Cortex","Phloem","Cambium","Xylem"]', 'Xylem carries water and mineral salts.', '{"bold":["Xylem"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('134c23c6-f98c-4a5c-9942-3f8b4325b1c9', 'Literature in English', 'JAMB', null, 2026, null, 'The poem is about love', null, '["Unforgettable","Unrequited","Sacrificial","Selfish"]', 1, 'The poem is about unrequited love.', true, '2026-09-12 11:11:10.327', '2026-09-12 11:11:10.327', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('13541242-359d-49bd-91c0-7f0bfa561ce0', 'Literature in English', 'JAMB', null, 2026, null, '______ is an understatement expressed by using a negation to affirm the opposite', null, '["bildungsroman","picaresque","litotes","hyperbole"]', 2, 'Litotes is an understatement using negation to affirm the opposite.', true, '2026-09-12 11:12:10.635', '2026-09-12 11:12:10.635', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('135f165c-29b6-4ca5-957c-f019306f94a6', 'Chemistry', 'JAMB', null, 2026, null, 'A reaction occurs spontaneously when', null, '["∆G > 0","∆S < 0 and ∆H > 0","∆H < T∆S","∆G = 0"]', 2, 'Using Gibbs free energy formula ∆G = ∆H - T∆S, a reaction is spontaneous when ∆G < 0, which requires ∆H < T∆S.', true, '2026-09-09 17:12:45.538', '2026-09-09 17:12:45.538', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('136a7134-d81f-4a9a-9787-edd405f5a9db', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). Can you <u>give a good explanation for</u> your behaviour?', null, '["account for","call for","clear up","make up","give up"]', 0, '''Account for'' means explain.', true, '2026-10-24 01:04:14.189', '2026-10-24 01:04:14.189', null, null, null, '(Choose the most appropriate interpretation). Can you <u>give a good explanation for</u> your behaviour?', '["<u>account for</u>","call for","clear up","make up","give up"]', '''<b>Account for</b>'' means <b>explain</b>.', '{}');
