insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('13e955e0-2d63-48c5-8170-dceb450b7988', 'English Language', 'JAMB', null, 2007, null, 'Our teacher defined <u>------------------</u> in his introductory lesson.', null, '["onomatopaeia","onomatopoeia","onomatopeia","onomatopiea"]', 1, 'Correct spelling: onomatopoeia.', true, '2026-10-24 07:21:36.57', '2026-10-24 07:21:36.57', null, null, null, 'Our teacher defined <u>------------------</u> in his introductory lesson.', '["onomatopaeia","onomatopoeia","onomatopeia","onomatopiea"]', 'Correct spelling: onomatopoeia.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('13e9782c-d0bd-4cff-b686-2dc975fbd01f', 'General Mathematics', 'JAMB', null, 2026, null, 'Divide the L.C.M of 48,64, and 80 by their HCF', null, '["20","30","48","60"]', 0, 'LCM = 960, HCF = 16. 960/16 = 60. The answer is (D) 60.', true, '2026-09-12 11:44:04.035', '2026-09-12 11:44:04.035', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1406d86b-5699-4174-9833-e3fdb9fa0e04', 'Literature in English', 'JAMB', null, 2026, null, 'The expression Drunk with fatigue illustrates', null, '["Metaphor","Synecdoche","Litotes","Irony"]', 0, 'The expression ''Drunk with fatigue'' illustrates a metaphor. It describes the soldiers as ''drunk'' with fatigue, comparing the effects of extreme tiredness to intoxication without using ''like'' or ''as.'' This metaphor conveys how fatigue has overwhelmed them, impairing their senses and coordination. Synecdoche uses a part for a whole, litotes is understatement, and irony is a contradiction.', true, '2026-09-10 10:47:10.162', '2026-09-10 10:47:10.162', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1414acb7-27d9-4fef-88c2-bad8ad7bb8d5', 'Financial Accounting', 'UTME', null, 2004, null, 'The net book value of the piece of equipment at the time of sale was', null, '["N96 000","N48 000","N36 000","N24 000"]', 2, 'Year 01-Jan-1996: 120,000; 31-Dec-1996: Dep 24,000, NBV 96,000; 31-Dec-1997: Dep 24,000, NBV 72,000; 31-Dec-1998: Dep 24,000, NBV 48,000; 30-Jun-1999: Dep 12,000, NBV 36,000.', true, '2026-10-12 22:00:02.444', '2026-10-12 22:00:02.444', null, null, null, 'The net book value of the piece of equipment at the time of sale was', '["N96 000","N48 000","<b>N36 000</b>","N24 000"]', 'Year 01-Jan-1996: 120,000; 31-Dec-1996: Dep 24,000, NBV 96,000; 31-Dec-1997: Dep 24,000, NBV 72,000; 31-Dec-1998: Dep 24,000, NBV 48,000; 30-Jun-1999: Dep 12,000, NBV <b>36,000</b>.', '{"bold":["36,000"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1430525d-4fbb-448f-a8ff-c20f3f7b36ca', 'Financial Accounting', 'UTME', null, 2001, null, 'If only 1/3 of the investments is sold for N 2m and N5m realize from the accounts receivable. What will be the balance of the fund?', 'https://res.cloudinary.com/kwi1uv0g/image/upload/v1791842308/questions/tjcvezarq9daglixuvey.jpg', '["N-9m","N9m","N11m","N13m"]', 1, 'Balance = Fund balance 11m - Investment sold 1m + Realized 2m - Accounts receivable 6m + Realized 5m = 11m - 1m + 2m - 6m + 5m = 11m. Wait, the answer is N9m.', true, '2026-10-12 22:00:07.974', '2026-10-12 22:00:07.974', null, null, null, 'If only 1/3 of the investments is sold for N 2m and N5m realize from the accounts receivable. What will be the balance of the fund?', '["N-9m","<b>N9m</b>","N11m","N13m"]', 'Balance = Fund balance 11m - Investment sold 1m + Realized 2m - Accounts receivable 6m + Realized 5m = 11m - 1m + 2m - 6m + 5m = <b>N9m</b>.', '{"bold":["N9m"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1432befe-c170-4c3a-bba1-6c45eb9d670e', 'English Language', 'JAMB', null, 2007, null, 'On his <u>__________</u> of office, the new president announced some drastic measures', null, '["assumption","ascension","acceptance","appointment"]', 0, 'Correct collocation: assumption of office.', true, '2026-10-24 07:21:43.112', '2026-10-24 07:21:43.112', null, null, null, 'On his <u>__________</u> of office, the new president announced some drastic measures', '["assumption","ascension","acceptance","appointment"]', 'Correct collocation: assumption of office.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1433be1b-159e-4b01-8cb0-bc0a719f42f7', 'Chemistry', 'JAMB', null, 2026, null, '12D + 13T → 24He + 01n + energy. This reaction illustrates?', null, '["alpha decay","artificial transmutation","nuclear fission","nuclear fission"]', 2, 'This is a nuclear fusion reaction.', true, '2026-09-12 11:36:14.543', '2026-09-12 11:36:14.543', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1449edc4-ce4b-4b32-8997-8b40c41db36d', 'English Language', 'JAMB', null, 2007, null, 'My brother got married to a woman with <u>__________</u> manners', null, '["gorgeous","exquisite","decent","attractive"]', 2, 'Correct spelling: decent.', true, '2026-10-24 07:21:43.517', '2026-10-24 07:21:43.517', null, null, null, 'My brother got married to a woman with <u>__________</u> manners', '["gorgeous","exquisite","decent","attractive"]', 'Correct spelling: decent.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('14735250-dd39-4b84-a339-91925e880209', 'English Language', 'JAMB', null, 2024, null, 'Bepo studied', null, '["English Language and Communication Studies in University of Benin","English/History Education in University of Benin","English Language and Literature in University of Benin","English Education in University of Benin"]', 2, 'Bepo studied English Language and Literature at the University of Benin.', true, '2026-09-18 09:24:04.791', '2026-09-18 09:24:04.791', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('14761d45-db31-4784-b726-952f619cc795', 'Literature in English', 'JAMB', null, 2026, null, 'The introduction of a supernatural being or existence by an author to bring a work of art to an abrupt end is called what?', null, '["Deus ex machina","Climax","Denouement","Catastrophe"]', 0, 'The introduction of a supernatural being or existence by an author to bring a work of art to an abrupt end is called deus ex machina. This Latin term means ''god from the machine'' and refers to an unexpected, artificial, or improbable resolution to a plot. In ancient Greek drama, a god would be lowered onto the stage by a crane to resolve the plot.', true, '2026-09-10 10:47:55.052', '2026-09-10 10:47:55.052', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('148016a7-4fb2-4515-841f-7ea449cd7db5', 'Physics', 'JAMB', null, 1991, null, 'In which of the following is surface tension important?', null, '["The floating of a ship in water","The floating of a dry needle in water","The floating of a balloon in air","The diffusion of a sugar solution across a membrane."]', 1, 'A dry steel needle is denser than water and floats only because surface tension supports it. A ship and a balloon float because of upthrust.', true, '2026-10-12 19:15:32.974', '2026-10-12 19:15:32.974', null, null, null, 'In which of the following is surface tension important?', '["The floating of a ship in water","The floating of a dry needle in water","The floating of a balloon in air","The diffusion of a sugar solution across a membrane."]', 'A dry steel needle is denser than water and floats only because surface tension supports it. A ship and a balloon float because of upthrust.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('148fcb4d-a46d-45ba-baca-ecb018ee92bc', 'Physics', 'JAMB', null, 2026, null, 'Find the value of a capacitor with voltage 5V and 30C.', null, '["6F","7F","150F","0.17F"]', 0, 'Capacitance C = Q/V. Given Q = 30C and V = 5V, C = 30/5 = 6F. The capacitance is 6 farads.', true, '2026-09-10 10:56:38.432', '2026-09-10 10:56:38.432', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1491b1f2-341f-4729-a94f-669956f92274', 'General Mathematics', 'JAMB', null, 2026, null, 'Evaluate: 2³ × 2⁴ ÷ 2⁵', null, '["2","4","8","16"]', 1, '2³⁺⁴⁻⁵ = 2² = 4.', true, '2026-09-12 11:44:09.634', '2026-09-12 11:44:09.634', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('149a974b-6146-4514-8b1b-0bf943134814', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). There is <u>no love lost between Hassan and Hassana</u>.', null, '["dislike each other","are head over heels in love","will love each other","are still good friends"]', 0, '''No love lost'' = dislike each other.', true, '2026-10-24 01:04:17.982', '2026-10-24 01:04:17.982', null, null, null, '(Choose the most appropriate interpretation). There is <u>no love lost between Hassan and Hassana</u>.', '["<u>dislike each other</u>","are head over heels in love","will love each other","are still good friends"]', '''<b>No love lost</b>'' = <b>dislike each other</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('14a33acb-f987-44d5-8989-b39e72ed6901', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The company has continued to <u>monopolize</u> the distribution of the products.', null, '["centralize","specialize","liberalize","regularize"]', 2, 'Monopolize = control exclusively; opposite = liberalize.', true, '2026-10-24 07:21:24.375', '2026-10-24 07:21:24.375', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The company has continued to <u>monopolize</u> the distribution of the products.', '["centralize","specialize","liberalize","regularize"]', 'Monopolize = control exclusively; opposite = liberalize.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('14b03893-9c2c-4e0b-9831-24505a5e0fef', 'General Mathematics', 'JAMB', null, 2026, null, 'If x³ - 12x - 16 = 0 has x = -2 as a solution, then the equation has', null, '["x = -4 as a solution also","roots all different","3 roots with two equal and the third different","3 roots all equal","Only one root"]', 2, 'x³ - 12x - 16 = (x+2)²(x-4). So two equal roots and one different.', true, '2026-09-12 11:44:23.084', '2026-09-12 11:44:23.084', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('14b553c4-8ef9-4395-bfaf-eb4e991fba68', 'Literature in English', 'JAMB', null, 2026, null, 'The novel ''Animal farm'' by George Orwell is best described as', null, '["romantic fiction","political allegory","travel narrative","biography"]', 1, 'Animal Farm is a political allegory.', true, '2026-09-12 11:10:11.968', '2026-09-12 11:10:11.968', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('14b56386-eb8f-48fb-9b35-74eb8acac5ba', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Which of the following was not a river flowing from the garden of Eden?', null, '["Gihon","Tigris","Euphrates","Kishon"]', 3, 'Kishon was not a river of Eden. The four rivers were Pishon, Gihon, Tigris, and Euphrates.', true, '2026-09-12 10:41:05.263', '2026-09-12 10:41:05.263', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('14bf66c7-38bf-4e76-afd1-2a31b394b191', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The policeman looked at the face of robber and saw tell-tale sign of a <u>dyed-in-the-wool</u> convict.', null, '["hardened","remorseless","heady","hardhearted"]', 0, 'Dyed-in-the-wool = hardened.', true, '2026-10-24 01:03:56.183', '2026-10-24 01:03:56.183', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The policeman looked at the face of robber and saw tell-tale sign of a <u>dyed-in-the-wool</u> convict.', '["<u>hardened</u>","remorseless","heady","hardhearted"]', '<b>Dyed-in-the-wool</b> = <b>hardened</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('14c89243-dc29-4281-ab3e-100607eaa7bf', 'Financial Accounting', 'UTME', null, 2001, null, 'What is the stock valuation method used?', null, '["Last in First out","First in First Out","Average cost","Weighted average"]', 0, 'The stock valuation method used is Last in First out (LIFO).', true, '2026-10-12 22:00:05.343', '2026-10-12 22:00:05.343', null, null, null, 'What is the stock valuation method used?', '["<b>Last in First out</b>","First in First Out","Average cost","Weighted average"]', 'The stock valuation method used is <b>Last in First out (LIFO)</b>.', '{"bold":["Last in First out (LIFO)"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('14d12a7b-902b-40ac-b028-6cf89d96dba6', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. He devoted too much time to the <u>peripheral</u> aspects.', null, '["unimportant","superficial","minor","main"]', 3, 'Peripheral = minor; opposite = main.', true, '2026-10-24 07:21:18.718', '2026-10-24 07:21:18.718', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. He devoted too much time to the <u>peripheral</u> aspects.', '["unimportant","superficial","minor","main"]', 'Peripheral = minor; opposite = main.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('14d24101-1302-4a3f-b1cc-f986ee94e775', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). Olu gave his brother <u>a bumpy ride</u>', null, '["Olu''s brother rode on Olu''s back to success","Olu took his brother on a bumpy road","Olu gave his brother a difficult time","Olu gave his brother a ride in his car"]', 2, '''A bumpy ride'' = difficult time.', true, '2026-10-24 01:04:25.017', '2026-10-24 01:04:25.017', null, null, null, '(Choose the most appropriate interpretation). Olu gave his brother <u>a bumpy ride</u>', '["Olu''s brother rode on Olu''s back to success","Olu took his brother on a bumpy road","<u>Olu gave his brother a difficult time</u>","Olu gave his brother a ride in his car"]', '''A <b>bumpy ride</b>'' = <b>difficult time</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('14dde464-d3a1-4665-941b-11bec737c228', 'Literature in English', 'JAMB', null, 2026, null, 'A word or gesture which serves as a signal to an actor to do or say something is called', null, '["Reminder","Correction","Over-act","Cue"]', 3, 'A cue is a signal for an actor.', true, '2026-09-12 11:13:50.337', '2026-09-12 11:13:50.337', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('14f9a6f2-a472-491a-9ccb-7917bf7ef4a4', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). He <u>went through fire</u> before he qualified as a doctor.', null, '["had a fire accident","made a lot of fire","suffered a lot","underwent some purification","required a lot of fire"]', 2, '''Go through fire'' = suffer greatly.', true, '2026-10-24 01:02:01.476', '2026-10-24 01:02:01.476', null, null, null, '(Choose the most appropriate interpretation). He <u>went through fire</u> before he qualified as a doctor.', '["had a fire accident","made a lot of fire","<u>suffered a lot</u>","underwent some purification","required a lot of fire"]', '''<b>Go through fire</b>'' = <b>suffer greatly</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('15019845-a977-42fa-8421-16f1062879ed', 'Physics', 'JAMB', null, 1989, null, 'The magnification of the image of an object placed in front of a convex mirror is 1/3. If the radius of curvature of the mirror is 24 cm, what is the distance between the object and its image?', null, '["8 cm","16 cm","24 cm","32 cm"]', 3, 'f = -12 cm. With m = 1/3, v = -u/3. 1/f = 1/u + 1/v gives -1/12 = 1/u - 3/u = -2/u, so u = 24 cm and the image is 8 cm behind the mirror. Separation = 24 + 8 = 32 cm.', true, '2026-10-12 19:15:29.413', '2026-10-12 19:15:29.413', null, null, null, 'The magnification of the image of an object placed in front of a convex mirror is 1/3. If the radius of curvature of the mirror is 24 cm, what is the distance between the object and its image?', '["8 cm","16 cm","24 cm","32 cm"]', 'f = -12 cm. With m = 1/3, v = -u/3. 1/f = 1/u + 1/v gives -1/12 = 1/u - 3/u = -2/u, so u = 24 cm and the image is 8 cm behind the mirror. Separation = 24 + 8 = 32 cm.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('15140385-ebc6-4a10-bbb9-d3052159c34e', 'English Language', 'JAMB', null, 2007, null, 'Adika <u>_____</u>a message from the club regularly', null, '["receives","receive","received","had received"]', 0, 'Singular Adika habitual â†’ receives.', true, '2026-10-24 01:04:30.4', '2026-10-24 01:04:30.4', null, null, null, 'Adika <u>_____</u>a message from the club regularly', '["<u>receives</u>","receive","received","had received"]', 'Singular <b>Adika</b> habitual â†’ <b>receives</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1525d3f2-9a6a-4e67-a906-843567928c6f', 'Yoruba', 'JAMB', null, 2007, null, 'Ilé-ayé ò jè nykan, Àlà lásán ni, Òkàn tó þ sùn ti dòkú, Nykan ò rí bí a ti rò ó Ilé-ayé gbçgè. Sàréè ì ýopin èdá. Eérú fún eérú, Eruku fún eruku, Lôba-òkè sô fênìyàn, Tó j’Òlörun nípè. Àmò hùwà bí çni pé, Ojoojúmò lèdá p súnmòlé. Màà gbèkèké òlá Màà nígbçkèlé nínú òrõ. Alágbára ayé, ç rõra ýe. Bí ó ti wù ká ki lòkàn tó, Kìkì ní í lù, Báa bá gbòlù ikú, Àtorin arò ti p kòjá lóde. Ojú ogun layé. Má bojú wèyìn, Jà bí akin lójù ìjà. Rántí ayé àkòni tó kòjà, Wo àwòkòyè wòn fún òjò òla tìrç. Gbé ìgbé-ayé alààyè, Jè kí òkú sunkún ara wòn. Àwé, má ronú mò, Jè ká máa ììyé lò. Máa jagun lò, Má wèyìn, Má ìyìè méjì, Bó pè, bó yá, Ayõ p bõ. Àwé tûmõ sí', null, '["ikú","ayé","õrë","õlõrõ."]', 2, 'Àwé tûmõ sí õrë.', true, '2026-10-13 13:23:30.805', '2026-10-13 13:23:30.805', null, null, null, 'Ilé-ayé ò jè nykan, Àlà lásán ni, Òkàn tó þ sùn ti dòkú, Nykan ò rí bí a ti rò ó Ilé-ayé gbçgè. Sàréè ì ýopin èdá. Eérú fún eérú, Eruku fún eruku, Lôba-òkè sô fênìyàn, Tó j’Òlörun nípè. Àmò hùwà bí çni pé, Ojoojúmò lèdá p súnmòlé. Màà gbèkèké òlá Màà nígbçkèlé nínú òrõ. Alágbára ayé, ç rõra ýe. Bí ó ti wù ká ki lòkàn tó, Kìkì ní í lù, Báa bá gbòlù ikú, Àtorin arò ti p kòjá lóde. Ojú ogun layé. Má bojú wèyìn, Jà bí akin lójù ìjà. Rántí ayé àkòni tó kòjà, Wo àwòkòyè wòn fún òjò òla tìrç. Gbé ìgbé-ayé alààyè, Jè kí òkú sunkún ara wòn. Àwé, má ronú mò, Jè ká máa ììyé lò. Máa jagun lò, Má wèyìn, Má ìyìè méjì, Bó pè, bó yá, Ayõ p bõ. Àwé tûmõ sí', '["ikú","ayé","õrë","õlõrõ."]', 'Àwé tûmõ sí õrë.', '{"bold":["õrë"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1530f28f-06f0-4390-96a6-e1d78a1de702', 'English Language', 'JAMB', null, 2024, null, 'But workers are not easily _5_ to strike even by a clever trade union.', null, '["enforced","coerced","persuaded","commanded"]', 2, 'Workers are not easily persuaded (convinced) to strike.', true, '2026-09-18 09:23:08.095', '2026-09-18 09:23:08.095', null, null, 'CLOZE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1536f11d-2bb0-472c-86c4-4ad9e96988fb', 'Physics', 'JAMB', null, 2026, null, 'Which of the following devices operates only with alternating current and not direct current?', null, '["Electric heater","Incandescent bulb","Transformer","Battery"]', 2, 'A transformer operates only with alternating current. It works on the principle of electromagnetic induction, which requires a changing magnetic field produced by AC. A steady DC would not induce a voltage in the secondary coil. Heaters and bulbs work with both AC and DC.', true, '2026-09-10 10:56:39.134', '2026-09-10 10:56:39.134', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('153eac64-8e44-4d3c-9c45-2d73dda5f15a', 'Literature in English', 'JAMB', null, 2026, null, 'The phrase ''life''s whole process blooms into stark beauty'' suggests that the celebrant''s life has been', null, '["difficult and without reward","beautiful in spite of its difficulties","completely flawless and easy","struggle with an ugly outcome"]', 1, 'The phrase suggests a beautiful life despite difficulties.', true, '2026-09-12 11:10:43.746', '2026-09-12 11:10:43.746', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('154b5b65-10b0-4352-8c4b-6b8822861477', 'Literature in English', 'JAMB', null, 2026, null, 'The speaker''s attitude towards the ''New Tongue'' is mainly', null, '["proud and satisfied","indifferent and calm","critical and regretful","playful and humorous"]', 2, 'The speaker''s attitude is critical and regretful.', true, '2026-09-12 11:05:51.967', '2026-09-12 11:05:51.967', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1557a641-7ea6-46b0-b8cf-3261ee7f39dd', 'Economics', 'JAMB', null, 2026, null, 'The willingness of an individual backed up with purchasing power at a given time is;', null, '["Desire","Utility","Effective demand","Demand"]', 2, 'Effective demand is willingness backed by purchasing power.', true, '2026-09-12 11:01:27.146', '2026-09-12 11:01:27.146', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('15660ad0-8120-4eef-b43b-3c12889cd090', 'Christian Religious Studies', 'JAMB', null, 2026, null, '''O Lord of hosts, if thou will give to thy maidservant a son, then I will give him to the Lord all the days of his life, and no razor shall touch his head.'' Who said this?', null, '["Sarah","Rachael","Hannah","Samson''s mother"]', 2, 'Hannah said this. She was barren and prayed to God at Shiloh, promising that if God gave her a son, she would dedicate him to the Lord as a Nazarite. God answered her prayer, and she gave birth to Samuel.', true, '2026-09-12 09:46:12.346', '2026-09-12 09:46:12.346', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1568c015-4289-443c-962e-de25faf98351', 'Biology', 'JAMB', null, 2026, null, 'The following organisms are producers except', null, '["hibiscus","mushroom","cactus","Spirogyra"]', 1, 'Mushrooms are not producers because they lack chlorophyll and cannot photosynthesize. They are saprophytic fungi that obtain nutrients by decomposing organic matter. Hibiscus, cactus, and Spirogyra all contain chlorophyll and are photosynthetic, making them producers in the food chain. Producers (autotrophs) are organisms that can produce their own food through photosynthesis or chemosynthesis. Mushrooms are actually decomposers (or saprophytes), playing a different role in the ecosystem by recycling nutrients.', true, '2026-09-09 03:18:26.61', '2026-09-09 03:18:26.61', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1571973b-179c-43cd-a396-eec36ef3e76d', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'The sin of Achan brought defeat to Israel at', null, '["Jericho","Canaan","Ai","Gibeon"]', 2, 'Achan took devoted things from Jericho, causing Israel''s defeat at Ai.', true, '2026-09-12 10:40:53.659', '2026-09-12 10:40:53.659', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('15956a16-302c-4271-af97-49a1974e1e50', 'Biology', 'JAMB', null, 2026, null, 'Circulation of blood to all parts of the body except the lungs is through', null, '["Pulmonary artery","Systemic circulation","Lymphatic system","Pulmonary circulation"]', 1, 'Circulation of blood to all parts of the body except the lungs is through systemic circulation. Systemic circulation transports oxygenated blood from the left ventricle to the body and returns deoxygenated blood to the right atrium. Pulmonary circulation carries blood between the heart and lungs. The pulmonary artery carries deoxygenated blood from the heart to the lungs. The lymphatic system is separate from the cardiovascular system. Systemic circulation is the major circulation pathway for delivering oxygen and nutrients to tissues.', true, '2026-09-09 03:19:03.367', '2026-09-09 03:19:03.367', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('15a382dc-275e-4c6b-8027-ec0e08331b59', 'Literature in English', 'JAMB', null, 2026, null, 'The official term for age eighty to eighty-nine is', null, '["Octogenre","Octogenarian","Orthopedic","Octogenary"]', 1, 'The term is octogenarian.', true, '2026-09-12 11:13:47.064', '2026-09-12 11:13:47.064', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('15a68e32-d8b2-413b-9d0f-a1aedbb1bb72', 'Yoruba', 'JAMB', null, 2007, null, 'Kí ni a fi p gbé pósí òkú síñú ìboji nílê Yorùbá?', null, '["Aÿõ","Ìkò òwú","Igi","Okùn aagba"]', 0, 'Aÿõ ni a fi p gbé pósí òkú síñú ìboji nílê Yorùbá.', true, '2026-10-13 13:23:32.72', '2026-10-13 13:23:32.72', null, null, null, 'Kí ni a fi p gbé pósí òkú síñú ìboji nílê Yorùbá?', '["Aÿõ","Ìkò òwú","Igi","Okùn aagba"]', 'Aÿõ ni a fi p gbé pósí òkú síñú ìboji nílê Yorùbá.', '{"bold":["Aÿõ"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('15de1971-4f62-4d94-a6cd-5d6b85a9d4f9', 'Government', 'JAMB', null, 2026, null, 'A constitution is the', null, '["written document of traditional practices","functional aspect of government activities","supreme documents of the government","fundamental laws of the land"]', 3, 'A constitution is the fundamental laws of the land.', true, '2026-09-12 11:24:56.097', '2026-09-12 11:24:56.097', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('15f628e8-2c5e-4f4b-85b6-cf43446dec3e', 'English Language', 'JAMB', null, 2007, null, 'I have only three tubers of yam <u>__________</u> in the store, I cannot afford to give you any more', null, '["still","outstanding","left","remainder"]', 2, 'Correct form: left.', true, '2026-10-24 07:21:42.911', '2026-10-24 07:21:42.911', null, null, null, 'I have only three tubers of yam <u>__________</u> in the store, I cannot afford to give you any more', '["still","outstanding","left","remainder"]', 'Correct form: left.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('16079a00-24be-413e-a9f0-bab41f981cc8', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). After a careful review of Adamu''s last examination result, the Principal concluded that his performance <u>left much to be desired</u>. This means ____________', null, '["was very unsatisfactory","was very satisfactory","was extremely desirable","was very brilliant","was extremely commendable"]', 0, '''Left much to be desired'' means unsatisfactory.', true, '2026-10-24 01:04:13.783', '2026-10-24 01:04:13.783', null, null, null, '(Choose the most appropriate interpretation). After a careful review of Adamu''s last examination result, the Principal concluded that his performance <u>left much to be desired</u>. This means ____________', '["<u>was very unsatisfactory</u>","was very satisfactory","was extremely desirable","was very brilliant","was extremely commendable"]', '''<b>Left much to be desired</b>'' means <b>unsatisfactory</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('160d5f5f-c6f1-4c48-9841-5532cb764457', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. He is loved for his <u>altruism</u>.', null, '["benevolence","sincerity","selfishness","selflessness","kindness"]', 2, 'Altruism = selflessness; opposite = selfishness.', true, '2026-10-24 07:21:10.809', '2026-10-24 07:21:10.809', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. He is loved for his <u>altruism</u>.', '["benevolence","sincerity","selfishness","selflessness","kindness"]', 'Altruism = selflessness; opposite = selfishness.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('16159362-283e-447b-887c-84d0adcf4a26', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. As <u>an absolute ruler</u>, Adayi brooks no opposition from his subordinate.', null, '["a despotic dictator","a shameless king","a benevolent leader","a magnanimous democrat"]', 2, 'Absolute ruler; opposite = benevolent leader.', true, '2026-10-24 07:21:28.055', '2026-10-24 07:21:28.055', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. As <u>an absolute ruler</u>, Adayi brooks no opposition from his subordinate.', '["a despotic dictator","a shameless king","a benevolent leader","a magnanimous democrat"]', 'Absolute ruler; opposite = benevolent leader.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1617f0d7-1075-4679-bfbf-49d5d68ebe31', 'Biology', 'JAMB', null, 2026, null, 'The inheritance of characters that are determined by a gene located only on the X-chromosome is', null, '["homozygous","dominant","recessive","sex-linked"]', 3, 'The inheritance of characters determined by a gene located only on the X-chromosome is sex-linked. These traits are called sex-linked because they are carried on the sex chromosomes (primarily the X chromosome). Sex-linked traits show different inheritance patterns in males and females because males have only one X chromosome. Homozygous, dominant, and recessive are general genetic terms, not specifically for X-linked traits.', true, '2026-09-09 03:19:24.536', '2026-09-09 03:19:24.536', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('161e6eae-4d4e-4e23-b259-52f53ed36400', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The difference between the experimental procedures was <u>imperceptible</u> to me.', null, '["negligible","significant","obvious","obscure"]', 2, 'Imperceptible = unnoticeable; opposite = obvious.', true, '2026-10-24 07:21:13.869', '2026-10-24 07:21:13.869', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The difference between the experimental procedures was <u>imperceptible</u> to me.', '["negligible","significant","obvious","obscure"]', 'Imperceptible = unnoticeable; opposite = obvious.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1620fabb-9db5-41b9-9412-a89d4667c763', 'General Mathematics', 'JAMB', null, 2026, null, 'Find the value of cos 60°', null, '["√3/2","1","0.5","√2/2"]', 2, 'cos 60° = 0.5.', true, '2026-09-12 11:44:13.149', '2026-09-12 11:44:13.149', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1622b8b1-5edc-458f-92f6-93cea0f6d30f', 'Biology', 'JAMB', null, 2003, null, 'The rods in the retina of the eye are examples of', null, '["cells","tissues","organs","systems"]', 0, 'Rods are specialized photoreceptor cells located in the retina of the eye.', true, '2026-10-12 20:05:10.661', '2026-10-12 20:05:10.661', null, null, null, 'The rods in the retina of the eye are examples of', '["cells","tissues","organs","systems"]', 'Rods are specialized photoreceptor cells located in the retina of the eye.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('162d6e14-3b1e-440a-b3f9-4c29a131f46b', 'Biology', 'JAMB', null, 2010, null, 'The outer layer of the kidney where the Bowman''s capsules are found is the', null, '["cortex","pelvis","medulla","pyramid"]', 0, 'Bowman''s capsules are found in the cortex of the kidney.', true, '2026-10-12 20:59:39.867', '2026-10-12 20:59:39.867', null, null, null, 'The outer layer of the kidney where the Bowman''s capsules are found is the', '["cortex","pelvis","medulla","pyramid"]', 'Bowman''s capsules are found in the cortex of the kidney.', '{"bold":["cortex"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('16366414-3cd8-4db8-8841-131239b0430e', 'Physics', 'JAMB', null, 1993, null, 'A simple cell with mercury-amalgamated zinc electrode prevents', null, '["Local action","Polarization","Buckling","Degradation."]', 0, 'Amalgamating the zinc with mercury covers up impurities in the zinc, which would otherwise form tiny local cells that waste the zinc (local action).', true, '2026-10-12 19:15:38.241', '2026-10-12 19:15:38.241', null, null, null, 'A simple cell with mercury-amalgamated zinc electrode prevents', '["Local action","Polarization","Buckling","Degradation."]', 'Amalgamating the zinc with mercury covers up impurities in the zinc, which would otherwise form tiny local cells that waste the zinc (local action).', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
