insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1656ff41-855a-43cc-964f-e3618c67c792', 'Hausa', 'JAMB', null, 2010, null, 'Akan kira dan da aka haifa bayan tagwaye', null, '["Cindo","Audi","Gambo","Damina."]', 2, 'Akan kira dan da aka haifa bayan tagwaye Gambo.', true, '2026-10-13 10:37:24.09', '2026-10-13 10:37:24.09', null, null, null, 'Akan kira dan da aka haifa bayan tagwaye', '["Cindo","Audi","Gambo","Damina."]', 'Akan kira dan da aka haifa bayan tagwaye Gambo.', '{"bold":["Gambo"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1661a4fb-c2b5-4e72-8334-01e96531ac4f', 'Biology', 'JAMB', null, 2013, null, 'Physiological adaptation to very dry condition in animals demonstrates', null, '["Hibernation","Aestivation","Rejuvenation","Xeromorphism"]', 1, 'Aestivation is physiological adaptation to very dry conditions.', true, '2026-10-12 20:59:48.298', '2026-10-12 20:59:48.298', null, null, null, 'Physiological adaptation to very dry condition in animals demonstrates', '["Hibernation","Aestivation","Rejuvenation","Xeromorphism"]', 'Aestivation is physiological adaptation to very dry conditions.', '{"bold":["Aestivation"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('166225bc-5fc7-4524-b1ea-ceccaef2601c', 'Chemistry', 'JAMB', null, 2026, null, 'Arrange the process in town water treatment. I) coagulation ii) filtration iii) sedimentation iv) disinfection', null, '["iii, ii and iv","iv, ii, I and iii","I, iii, ii and iv","I, ii, iii and iv"]', 2, 'The correct order is coagulation, sedimentation, filtration, and disinfection.', true, '2026-09-12 11:36:18.22', '2026-09-12 11:36:18.22', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('16695166-86d5-487b-98ef-18f16a6a9e44', 'Hausa', 'JAMB', null, 2010, null, 'Daga cikin waŝannan bukukuwa a wanne ne ake ŝauri?', null, '["kalankuwa.","buŝar dawa.","Sallar gani.","Sallar idi."]', 0, 'A kalankuwa ake yin ŝauri.', true, '2026-10-13 10:37:24.357', '2026-10-13 10:37:24.357', null, null, null, 'Daga cikin waŝannan bukukuwa a wanne ne ake ŝauri?', '["kalankuwa.","buŝar dawa.","Sallar gani.","Sallar idi."]', 'A kalankuwa ake yin ŝauri.', '{"bold":["kalankuwa"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('166f6255-8d99-43dc-8845-3f2a28db1790', 'General Mathematics', 'JAMB', null, 2026, null, '7 pupils of average age 12 years leave a class of 25 pupils of average age 14 years. If 6 new pupils of average age 11 years join the class, what is the average age of the pupils now in the class?', null, '["13 years","12 years and 10 months","13 years and 5 months","13 years and 10 months"]', 1, 'Total initially = 25×14 = 350. After leaving = 350-84 = 266. After joining = 266+66 = 332. Number = 24. Average = 332/24 = 13.83 years = 13 years 10 months. The answer is (D) 13 years and 10 months.', true, '2026-09-12 11:44:19.541', '2026-09-12 11:44:19.541', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1682b861-2236-4150-9480-70e448854198', 'Physics', 'JAMB', null, 2026, null, 'Calculate the force acting on an electron of charge 1.6×10⁻¹⁹ C placed in an electric field intensity 10¹² Vm⁻¹', null, '["1.6×10⁻⁷ N","1×10⁻⁸ N","1.6×10¹³ N","1×10¹⁷ N"]', 0, 'F = qE. F = (1.6×10⁻¹⁹)(10¹²) = 1.6×10⁻⁷ N.', true, '2026-09-10 10:56:41.843', '2026-09-10 10:56:41.843', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('168e73a1-889d-47a4-a908-cbca6e424ba2', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The labour leader''s <u>recalcitrant</u> stance was applauded.', null, '["stubborn","flexible","uncompromising","well-informed"]', 1, 'Recalcitrant = stubborn; opposite = flexible.', true, '2026-10-24 07:21:24.076', '2026-10-24 07:21:24.076', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The labour leader''s <u>recalcitrant</u> stance was applauded.', '["stubborn","flexible","uncompromising","well-informed"]', 'Recalcitrant = stubborn; opposite = flexible.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('169e8eea-9af1-4a5e-9d57-b8904df2a4eb', 'Literature in English', 'JAMB', null, 2026, null, 'The poem portrays the night as', null, '["protective and comforting","dangerous and mysterious","joyful and musical","peace and calm"]', 1, 'The night is portrayed as dangerous and mysterious.', true, '2026-09-12 11:10:12.776', '2026-09-12 11:10:12.776', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('16ab1fd6-6242-47df-a04f-da4d05949569', 'English Language', 'JAMB', null, 2007, null, 'The man was happy that his son confessed his guilt and so the others were <u>__________</u>', null, '["accused","punished","exonerated","implicated"]', 2, 'Correct spelling: exonerated.', true, '2026-10-24 07:21:39.216', '2026-10-24 07:21:39.216', null, null, null, 'The man was happy that his son confessed his guilt and so the others were <u>__________</u>', '["accused","punished","exonerated","implicated"]', 'Correct spelling: exonerated.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('16ba3cdf-9d3b-4764-ba19-a06f219ddc54', 'Literature in English', 'JAMB', null, 2026, null, '''I have told you a million times'' is an example of', null, '["Irony","Hyperbole","Pun","Euphemism"]', 1, 'It is hyperbole.', true, '2026-09-12 11:11:25.779', '2026-09-12 11:11:25.779', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('16ba539a-a8c4-41e7-9c8c-1d180cc4ec80', 'Biology', 'JAMB', null, 2012, null, 'From his study of Galapagos finches Darwin derived his Theory of evolution from', null, '["comparative anatomy","comparative physiology","fossil remains","comparative embryology."]', 0, 'Darwin derived his theory from comparative anatomy.', true, '2026-10-12 20:59:46.01', '2026-10-12 20:59:46.01', null, null, null, 'From his study of Galapagos finches Darwin derived his Theory of evolution from', '["comparative anatomy","comparative physiology","fossil remains","comparative embryology."]', 'Darwin derived his theory from comparative anatomy.', '{"bold":["comparative anatomy"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('16c61c3d-1232-4a04-8f5b-fa4cfa0e0f60', 'Biology', 'JAMB', null, 2026, null, 'The major site of photosynthesis in the leaf is the', null, '["palisade mesophyll","mesophyll parenchyma","upper epidermis","lower epidermis"]', 0, 'The palisade mesophyll is the primary site of photosynthesis because its cells contain the highest concentration of chloroplasts, which house the chlorophyll pigment necessary for capturing light energy. These elongated cells are densely packed just beneath the upper epidermis, allowing them to maximize light absorption. The spongy mesophyll (mesophyll parenchyma) has fewer chloroplasts and is more involved in gas exchange. The upper and lower epidermis lack chloroplasts entirely and serve primarily as protective layers with the cuticle reducing water loss.', true, '2026-09-09 03:18:14.361', '2026-09-09 03:18:14.361', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('16c8b90b-4db7-44e0-95d0-aecc1948bcaa', 'English Language', 'JAMB', null, 2007, null, 'Two young boys have been caught with parts of the stolen machine but <u>--------------</u> admitted stealing it.', null, '["neither of them has","neither of them have","none of them has","none of them have"]', 0, '''Neither of'' singular â†’ has; two boys â†’ neither.', true, '2026-10-24 01:02:14.565', '2026-10-24 01:02:14.565', null, null, null, 'Two young boys have been caught with parts of the stolen machine but <u>--------------</u> admitted stealing it.', '["<u>neither of them has</u>","neither of them have","none of them has","none of them have"]', '''<b>Neither of</b>'' singular â†’ <b>has</b>; two boys â†’ <b>neither</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('16ce4ec8-087c-471f-ad64-6e2e013a56ed', 'English Language', 'JAMB', null, 2024, null, 'The farmer in the passage', null, '["used to be self-sufficient","had a dream to expand his farm","is more envied than the astronauts","lives a life too simple"]', 0, 'The passage states that the farmer was self-sufficient and could live without a car, television, or newspaper.', true, '2026-09-18 10:16:10.246', '2026-09-18 10:16:10.246', '11a7b560-dd3b-4c82-b5ad-fe71fdd120ed', 2, 'COMPREHENSION', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('16d142dc-82f3-43e0-9c4b-5d3154466138', 'Chemistry', 'JAMB', null, 2026, null, 'How many moles of oxygen molecules are needed for the complete combustion of one mole of 3-methylpent-2-ene? I) 18 ii) 9 iii) 19 iv) 9.5 v) 10', null, '["none except ii","iii only","iv only","I only"]', 1, 'C₆H₁₂ + 9O₂ → 6CO₂ + 6H₂O. So 9 moles of O₂ are needed.', true, '2026-09-12 11:36:15.767', '2026-09-12 11:36:15.767', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('16d68cb6-0725-4ee0-8a67-8a5d6bab4c89', 'Literature in English', 'JAMB', null, 2026, null, 'The phrase "Booted the whole house awake" is an example of', null, '["personification","metaphor","metonymy","synecdoche"]', 0, 'The phrase "Booted the whole house awake" is an example of personification. It attributes the human action of ''booting'' (kicking) to a house, which cannot literally be booted. The phrase suggests that the violent actions of the oppressors disturbed the entire household. Personification gives human qualities to inanimate objects or abstract ideas. The other options (metaphor, metonymy, synecdoche) are different figures of speech.', true, '2026-09-10 10:45:34.883', '2026-09-10 10:45:34.883', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('16d72918-09f3-44b4-a127-ad56e006a4d7', 'Economics', 'JAMB', null, 2026, null, 'The demand curve which is parallel to the horizontal line is', null, '["perfect inelastic","perfect elastic","relatively inelastic","Relatively elastic"]', 1, 'A demand curve parallel to the horizontal line is perfectly elastic. This means that at a given price, consumers will buy any quantity, but if the price rises even slightly, quantity demanded falls to zero. The price elasticity of demand is infinite (∞). This occurs in perfectly competitive markets where firms are price takers. A vertical demand curve represents perfectly inelastic demand.', true, '2026-09-10 10:42:56.148', '2026-09-10 10:42:56.148', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('16d8abed-454f-44bb-b2a5-3d760e7548e7', 'Literature in English', 'JAMB', null, 2026, null, 'A short narrative poem that tells a story is', null, '["sonnet","lyric","Ode","Ballad"]', 3, 'A short narrative poem that tells a story is a ballad. Ballads are narrative poems that tell a story, often of love, adventure, or tragedy, and were traditionally passed down orally. A sonnet is a 14-line poem, a lyric expresses personal emotions, and an ode is a poem of praise.', true, '2026-09-10 10:47:53.531', '2026-09-10 10:47:53.531', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1704c8a3-b2b8-41fb-9068-98ebcbb7b955', 'English Language', 'JAMB', null, 2007, null, 'He <u>compliments</u> me on my way of doing things.', null, '["complements","imitates","disgusts","praises"]', 3, 'Compliments = praises.', true, '2026-10-24 01:04:09.93', '2026-10-24 01:04:09.93', null, null, null, 'He <u>compliments</u> me on my way of doing things.', '["complements","imitates","disgusts","<u>praises</u>"]', '<b>Compliments</b> = <b>praises</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('17121f4e-6210-4cb5-8426-3b0076727fb0', 'Biology', 'JAMB', null, 2003, null, 'In the egg of a bird, the embryo is located in the', null, '["chalaza","yolk","albumen","embryo disc"]', 1, 'The embryo is located in the yolk of a bird''s egg.', true, '2026-10-12 20:59:31.986', '2026-10-12 20:59:31.986', null, null, null, 'In the egg of a bird, the embryo is located in the', '["chalaza","yolk","albumen","embryo disc"]', 'The embryo is located in the yolk of a bird''s egg.', '{"bold":["yolk"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('171c0052-87ac-4672-b4af-fefcad6b3da0', 'Chemistry', 'JAMB', null, 2026, null, 'One mole of an hydrocarbon contains 48g of carbon. Of its vapour density is 28, the hydrocarbon is? (C=12, H=1)', null, '["An alkane","An alkene","An alkyne","Aromatic"]', 1, 'Molar mass = 2 × 28 = 56. Carbon = 48g = 4 moles. Hydrogen = 8g = 8 moles. Formula = C₄H₈ (butene, an alkene).', true, '2026-09-12 11:36:25.926', '2026-09-12 11:36:25.926', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('171e719d-0d22-4615-b8ff-919f9b15e448', 'Physics', 'JAMB', null, 1984, null, 'A simple pendulum, 0.6 m long, has a period of 1.5 s. What is the period of a similar pendulum 0.4 m long in the same location?', null, '["1.5√(2/3) s","1.5√(3/2) s","2.25 s","1.00 s","2.00 s"]', 0, 'T is proportional to √L, so T₂ = 1.5 x √(0.4/0.6) = 1.5√(2/3) s ≈ 1.22 s.', true, '2026-10-12 19:15:19.344', '2026-10-12 19:15:19.344', null, null, null, 'A simple pendulum, 0.6 m long, has a period of 1.5 s. What is the period of a similar pendulum 0.4 m long in the same location?', '["1.5√(2/3) s","1.5√(3/2) s","2.25 s","1.00 s","2.00 s"]', 'T is proportional to √L, so T<sub>2</sub> = 1.5 x √(0.4/0.6) = 1.5√(2/3) s ≈ 1.22 s.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1729bfe4-02bf-4be4-a610-2c98eab07767', 'Physics', 'JAMB', null, 1987, null, 'The coefficient of static friction between a 40 kg crate and a concrete surface is 0.25. Find the magnitude of the minimum force needed to keep the crate stationary on the concrete base inclined at 45° to the horizontal. (g = 10 m s⁻²)', null, '["400 N","300 N","283 N","212 N"]', 3, 'Down-slope component = mg sin 45° = 283 N. Maximum friction = μmg cos 45° = 0.25 x 283 = 71 N. Minimum holding force up the slope = 283 - 71 = 212 N.', true, '2026-10-12 19:15:24.93', '2026-10-12 19:15:24.93', null, null, null, 'The coefficient of static friction between a 40 kg crate and a concrete surface is 0.25. Find the magnitude of the minimum force needed to keep the crate stationary on the concrete base inclined at 45° to the horizontal. (g = 10 m s<sup>-2</sup>)', '["400 N","300 N","283 N","212 N"]', 'Down-slope component = mg sin 45° = 283 N. Maximum friction = μmg cos 45° = 0.25 x 283 = 71 N. Minimum holding force up the slope = 283 - 71 = 212 N.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('172af7a5-f627-4fdb-a64a-64c5ae95149d', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The man paid a large sum to <u>redeem</u> his mortgaged property.', null, '["ransom","pawn","acquire","recover"]', 1, 'Redeem = recover; opposite = pawn.', true, '2026-10-24 07:21:28.565', '2026-10-24 07:21:28.565', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The man paid a large sum to <u>redeem</u> his mortgaged property.', '["ransom","pawn","acquire","recover"]', 'Redeem = recover; opposite = pawn.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('172fbd5c-bdef-4c4b-a327-802ed785b3a1', 'General Mathematics', 'JAMB', null, 2026, null, 'A number is increased by 20% to give 180. What is the original number?', null, '["144","150","156","160"]', 1, '1.2x = 180. x = 150.', true, '2026-09-12 11:44:10.076', '2026-09-12 11:44:10.076', null, null, null, null, null, null, null);
