insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('17536231-212b-4506-aba9-0b7382f5bac9', 'English Language', 'JAMB', null, 2007, null, 'After a three-day meeting, two presidents issued a <u>__________</u> calling for peace.', null, '["bulletin","memorandum","communique","directive"]', 2, 'Correct spelling: communique.', true, '2026-10-24 07:21:37.075', '2026-10-24 07:21:37.075', null, null, null, 'After a three-day meeting, two presidents issued a <u>__________</u> calling for peace.', '["bulletin","memorandum","communique","directive"]', 'Correct spelling: communique.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('175f7531-51ea-4517-b1ba-212786c8d702', 'Financial Accounting', 'UTME', null, 2004, null, 'Which of the following items is found on the credit side of the sales ledger control account?', null, '["discount received","dishonoured cheques","credit sales","bills receivable"]', 3, 'Bills receivable is found on the credit side of the sales ledger control account.', true, '2026-10-12 22:00:02.689', '2026-10-12 22:00:02.689', null, null, null, 'Which of the following items is found on the credit side of the sales ledger control account?', '["discount received","dishonoured cheques","credit sales","<b>bills receivable</b>"]', '<b>Bills receivable</b> is found on the credit side of the sales ledger control account.', '{"bold":["bills receivable"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1760acc1-0bec-4e29-8291-53474c69e570', 'Biology', 'JAMB', null, 2001, null, 'The enzyme invertase will hydrolyze sucrose to give', null, '["mannose and galactose","glucose and fructose","maltose and glucose","glycerol and fatty acid"]', 1, 'Invertase hydrolyzes sucrose into glucose and fructose.', true, '2026-10-12 20:59:28.382', '2026-10-12 20:59:28.382', null, null, null, 'The enzyme invertase will hydrolyze sucrose to give', '["mannose and galactose","glucose and fructose","maltose and glucose","glycerol and fatty acid"]', 'Invertase hydrolyzes sucrose into glucose and fructose.', '{"bold":["glucose and fructose"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('17637469-41b6-4625-b463-0975c980e4b9', 'English Language', 'JAMB', null, 2007, null, 'Many young men of nowadays do not know how to properly <u>__________</u> their clothes', null, '["press","iron","smoothen","stretch"]', 1, 'Correct form: iron.', true, '2026-10-24 07:21:41.803', '2026-10-24 07:21:41.803', null, null, null, 'Many young men of nowadays do not know how to properly <u>__________</u> their clothes', '["press","iron","smoothen","stretch"]', 'Correct form: iron.', '{}');
