insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1779d2bc-fca1-44b1-a802-966e2600708e', 'Literature in English', 'JAMB', null, 2026, null, 'In the expression: ''He is a lion in battle,'' the device used is', null, '["Simile","Metaphor","Euphemism","Litotes"]', 1, 'The device is metaphor.', true, '2026-09-12 11:14:13.887', '2026-09-12 11:14:13.887', null, null, null, null, null, null, null);
