insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('17890164-0c5e-4473-8c03-3301790289cb', 'Physics', 'JAMB', null, 2001, null, 'A ray of light strikes a plane mirror at an angle of incidence of 35°. If the mirror is rotated through 10°, through what angle is the reflected ray rotated?', null, '["70°","45°","25°","20°"]', 3, 'The reflected ray turns through twice the angle through which the mirror is rotated: 2 x 10° = 20°.', true, '2026-10-12 19:15:51.2', '2026-10-12 19:15:51.2', null, null, null, 'A ray of light strikes a plane mirror at an angle of incidence of 35°. If the mirror is rotated through 10°, through what angle is the reflected ray rotated?', '["70°","45°","25°","20°"]', 'The reflected ray turns through twice the angle through which the mirror is rotated: 2 x 10° = 20°.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('17980313-e373-4700-a5fb-5abcbc78497b', 'Financial Accounting', 'UTME', null, 2001, null, 'If a property developing company sells a completed building to an interested third party, this sale can be treated in the books of the company as', 'https://res.cloudinary.com/kwi1uv0g/image/upload/v1791842032/questions/orsvg2utd6rhleuxc5qw.jpg', '["capital receipt","revenue receipt","windfall receipt","miscellaneous receipt"]', 1, 'If a property developing company sells a completed building, this sale is treated as revenue receipt.', true, '2026-10-12 22:00:05.073', '2026-10-12 22:00:05.073', null, null, null, 'If a property developing company sells a completed building to an interested third party, this sale can be treated in the books of the company as', '["capital receipt","<b>revenue receipt</b>","windfall receipt","miscellaneous receipt"]', 'If a property developing company sells a completed building, this sale is treated as <b>revenue receipt</b>.', '{"bold":["revenue receipt"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('17a83cd0-a49f-45b1-9dc1-9bfb372b6191', 'English Language', 'JAMB', null, 2007, null, 'The continuous rain has really <u>__________</u> the soil', null, '["mopped up","satiated","saturated","melted up"]', 2, 'Correct spelling: saturated.', true, '2026-10-24 07:21:39.621', '2026-10-24 07:21:39.621', null, null, null, 'The continuous rain has really <u>__________</u> the soil', '["mopped up","satiated","saturated","melted up"]', 'Correct spelling: saturated.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('17a8a033-10d2-4021-a520-9e7bdfc595eb', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The lecture seemed <u>interminable</u>.', null, '["brief","interesting","boring","unending"]', 0, 'Interminable = endless; opposite = brief.', true, '2026-10-24 07:21:22.81', '2026-10-24 07:21:22.81', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The lecture seemed <u>interminable</u>.', '["brief","interesting","boring","unending"]', 'Interminable = endless; opposite = brief.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('17acf823-feab-41be-b742-d0f5ec6e0669', 'Christian Religious Studies', 'JAMB', null, 2026, null, '''But I will be with you and you will smite the Midianites as one man'' was said by God to', null, '["Moses","Joshua","Gideon","Deborah"]', 2, 'God said this to Gideon when calling him to deliver Israel.', true, '2026-09-12 10:41:14.509', '2026-09-12 10:41:14.509', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('17ae73c6-6da6-41cd-b7ea-f18bc1f3246d', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. You are <u>free</u> to leave the hall.', null, '["at an advantage","opportune","at liberty","right"]', 2, 'Free = at liberty.', true, '2026-10-24 01:01:41.438', '2026-10-24 01:01:41.438', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. You are <u>free</u> to leave the hall.', '["at an advantage","opportune","<u>at liberty</u>","right"]', '<b>Free</b> = <b>at liberty</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('17b10e40-27b8-4f29-abb1-814e6eabe825', 'Biology', 'JAMB', null, 2026, null, 'Which of the following enzymes is active in the duodenum?', null, '["pepsin","renin","trypsin","amylase"]', 2, 'Trypsin is an enzyme that is active in the duodenum. It is secreted by the pancreas as inactive trypsinogen and is activated by enterokinase in the duodenum. Trypsin digests proteins into peptides. Pepsin is active in the stomach and requires an acidic environment. Renin is produced in the stomach of infants for milk digestion. Amylase (salivary amylase) begins starch digestion in the mouth and is inactivated in the acidic stomach, though pancreatic amylase acts in the duodenum. Trypsin''s optimum pH is slightly alkaline, matching the duodenal environment.', true, '2026-09-09 03:18:26.379', '2026-09-09 03:18:26.379', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('17c7ab08-1845-48ce-8b63-0dd6c00c0fae', 'Physics', 'JAMB', null, 1992, null, 'Which of the following factors has no effect on the e.m.f. of a primary cell?', null, '["Temperature","Size of the cell","Nature of the plates","Nature of the electrolyte."]', 1, 'The e.m.f. depends on the materials of the plates and electrolyte (and slightly on temperature), not on the size of the cell.', true, '2026-10-12 19:15:36.358', '2026-10-12 19:15:36.358', null, null, null, 'Which of the following factors has no effect on the e.m.f. of a primary cell?', '["Temperature","Size of the cell","Nature of the plates","Nature of the electrolyte."]', 'The e.m.f. depends on the materials of the plates and electrolyte (and slightly on temperature), not on the size of the cell.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('17c86722-e7ef-4032-8efc-6ecbaf07bb36', 'Financial Accounting', 'UTME', null, 2003, null, 'Given: Rich Social Club N Cash 100 000 Loan 30 000 Subscription in arrears 5 000 Subscription in advance 15 000. What is the accumulated fund?', 'https://res.cloudinary.com/kwi1uv0g/image/upload/v1791841431/questions/fcpc1ymji7bz9ballvw6.jpg', '["N60 000","N80 000","N90 000","N110 000"]', 0, 'Accumulated fund: Cash 100,000 + Subscriptions Arrears 5,000 = 105,000. Less: Loan 30,000 + Sub. Advance 15,000 = 45,000. 105,000 - 45,000 = 60,000.', true, '2026-10-12 22:00:00.717', '2026-10-12 22:00:00.717', null, null, null, 'Given: Rich Social Club N Cash 100 000 Loan 30 000 Subscription in arrears 5 000 Subscription in advance 15 000. What is the accumulated fund?', '["<b>N60 000</b>","N80 000","N90 000","N110 000"]', 'Accumulated fund: Cash 100,000 + Subscriptions Arrears 5,000 = 105,000. Less: Loan 30,000 + Sub. Advance 15,000 = 45,000. 105,000 - 45,000 = <b>60,000</b>.', '{"bold":["60,000"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('17c95fb2-50bf-409a-bd86-ab07469d5814', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The uniform makes the guards look <u>absurd</u>', null, '["smart","sensible","ridiculous","diny"]', 2, 'Absurd = ridiculous.', true, '2026-10-24 01:01:54.273', '2026-10-24 01:01:54.273', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The uniform makes the guards look <u>absurd</u>', '["smart","sensible","<u>ridiculous</u>","diny"]', '<b>Absurd</b> = <b>ridiculous</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('17e24005-3e29-455a-9db9-2781e0f9ee74', 'English Language', 'JAMB', null, 2024, null, 'I did ______ to the club frequently when I was a teenager.', null, '["go","went","goes","gone"]', 0, 'After the auxiliary "did," the base form of the verb "go" is used.', true, '2026-09-18 09:24:04.796', '2026-09-18 09:24:04.796', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('17e4321b-2666-48e9-af53-80f6eac8f0bb', 'Chemistry', 'JAMB', null, 2026, null, 'The reaction between zinc and copper(II) sulfate solution is an example of', null, '["precipitation","neutralization","redox reaction","hydrolysis"]', 2, 'Zinc loses electrons (oxidized) to copper ions which gain electrons (reduced), making it a single displacement redox reaction.', true, '2026-09-09 17:12:48.361', '2026-09-09 17:12:48.361', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('17eda6b9-3eea-4d8e-9aa8-9446e7f2e2b8', 'General Mathematics', 'JAMB', null, 2026, null, 'The mode of 2, 3, 4, 3, 5, 3, 6 is:', null, '["2","3","4","5"]', 1, 'Mode = 3 (appears 3 times).', true, '2026-09-12 11:44:14.284', '2026-09-12 11:44:14.284', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('18025b28-924d-4d1c-b76d-a022b2ddd477', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. For millions of years, the world''s resources have remained <u>boundless</u>.', null, '["unlimited","scarce","indomitable","limited"]', 3, 'Boundless = unlimited; opposite = limited.', true, '2026-10-24 07:21:13.717', '2026-10-24 07:21:13.717', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. For millions of years, the world''s resources have remained <u>boundless</u>.', '["unlimited","scarce","indomitable","limited"]', 'Boundless = unlimited; opposite = limited.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('180efe9a-930f-4deb-8b1d-fc7dcd9d1119', 'Biology', 'JAMB', null, 2026, null, 'The stem differs from the root in having the xylem and phloem strands', null, '["on the same radii","scattered","on alternate radii","towards the pith"]', 2, 'The stem differs from the root in having xylem and phloem strands on alternate radii. In stems (dicots), xylem and phloem are arranged with the xylem toward the center and phloem toward the outside. In roots, xylem and phloem are arranged in alternating radii (radial arrangement). Scattered arrangement is characteristic of monocots. Toward the pith is a general direction but not the key difference. This vascular arrangement pattern is used to distinguish stems from roots in cross-section.', true, '2026-09-09 03:19:06.852', '2026-09-09 03:19:06.852', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('180f21ff-1fde-4b5a-b43f-e7140a01f6df', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The material in the book is presented within <u>an eclectic</u> framework.', null, '["simple","a broad","a restricted","clumsy"]', 1, 'Eclectic = broad (drawing from many sources).', true, '2026-10-24 01:01:48.863', '2026-10-24 01:01:48.863', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The material in the book is presented within <u>an eclectic</u> framework.', '["simple","<u>a broad</u>","a restricted","clumsy"]', '<b>Eclectic</b> = <b>a broad</b> (drawing from many sources).', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('18137bb4-e964-4b12-96a1-97babd1ab040', 'Biology', 'JAMB', null, 2011, null, 'The ability of a living organism to detect and respond to changes in the environment is referred to as', null, '["locomotion","irritability","growth","taxis."]', 1, 'Irritability is the ability to detect and respond to changes.', true, '2026-10-12 20:59:42.153', '2026-10-12 20:59:42.153', null, null, null, 'The ability of a living organism to detect and respond to changes in the environment is referred to as', '["locomotion","irritability","growth","taxis."]', 'Irritability is the ability to detect and respond to changes.', '{"bold":["Irritability"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('181efe1b-9a73-4a39-9923-2ace554a9d2c', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. He accepted a <u>mundane</u> task without hesitation.', null, '["great","lowly","menial","moderate"]', 0, 'Mundane = ordinary; opposite = great.', true, '2026-10-24 07:21:14.276', '2026-10-24 07:21:14.276', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. He accepted a <u>mundane</u> task without hesitation.', '["great","lowly","menial","moderate"]', 'Mundane = ordinary; opposite = great.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('182bfbf4-18b2-4749-9636-6ddc0743e599', 'Physics', 'JAMB', null, 2002, null, 'From the generating station to each substation, power is transmitted at a very high voltage so as to reduce', null, '["Heating in the cables","Magnetic flux leakage","Hysteresis loss","Eddy current loss."]', 0, 'At very high voltage the current is small, so the I²R heating loss in the cables is reduced.', true, '2026-10-12 19:15:54.727', '2026-10-12 19:15:54.727', null, null, null, 'From the generating station to each substation, power is transmitted at a very high voltage so as to reduce', '["Heating in the cables","Magnetic flux leakage","Hysteresis loss","Eddy current loss."]', 'At very high voltage the current is small, so the I<sup>2</sup>R heating loss in the cables is reduced.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1831653f-d084-4720-acf3-cee799d1ea02', 'Physics', 'JAMB', null, 1995, null, 'A real object is placed at a distance u cm in front of a curved mirror of focal length f cm. If the image is upright and magnified, then the mirror is', null, '["Convex and u = 2f","Concave and u = 2f","Convex and u = f/2","Concave and u = f/2"]', 3, 'Only a concave mirror gives an upright, magnified image, and only when the object is inside the focal length (u < f), as with u = f/2.', true, '2026-10-12 19:15:41.897', '2026-10-12 19:15:41.897', null, null, null, 'A real object is placed at a distance u cm in front of a curved mirror of focal length f cm. If the image is upright and magnified, then the mirror is', '["Convex and u = 2f","Concave and u = 2f","Convex and u = f/2","Concave and u = f/2"]', 'Only a concave mirror gives an upright, magnified image, and only when the object is inside the focal length (u < f), as with u = f/2.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('18530c14-4757-4c0f-8651-97571ec710f7', 'Literature in English', 'JAMB', null, 2026, null, 'The expression Drunk with fatigue illustrates', null, '["Metaphor","Synecdoche","Litotes","Irony"]', 0, 'It illustrates metaphor.', true, '2026-09-12 11:07:28.033', '2026-09-12 11:07:28.033', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('186a8c93-98ea-4e52-ae69-ec6dc7ffac28', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). Ada has not been regular at lectures because she has been <u>off colour</u>.', null, '["gloomy","trying to hide her bleached skin","slightly sick","upset"]', 2, '''Off colour'' = slightly sick.', true, '2026-10-24 01:04:19.379', '2026-10-24 01:04:19.379', null, null, null, '(Choose the most appropriate interpretation). Ada has not been regular at lectures because she has been <u>off colour</u>.', '["gloomy","trying to hide her bleached skin","<u>slightly sick</u>","upset"]', '''<b>Off colour</b>'' = <b>slightly sick</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1874eeb1-ecfa-42ec-b333-b44967a99d95', 'Literature in English', 'JAMB', null, 2026, null, 'Who is the author of the poem ''Once Upon A Time''?', null, '["Gabriel Imomotimi","Wole Soyinka","Christopher Okigbo","Gabriel Imomotimi Okara"]', 3, 'The author of the poem ''Once Upon A Time'' is Gabriel Imomotimi Okara. He was a Nigerian poet and novelist born in 1921 in Bayelsa State. The poem reflects on the loss of innocence and sincerity in adulthood. Wole Soyinka and Christopher Okigbo are also famous Nigerian poets but did not write this poem. The full name of the author is Gabriel Imomotimi Okara.', true, '2026-09-10 10:45:35.205', '2026-09-10 10:45:35.205', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('188240f4-e0a3-4736-bd9a-bd2c9c5f6fea', 'Physics', 'JAMB', null, 1999, null, 'A man stands 4 m in front of a plane mirror. If the mirror is moved 1 m towards the man, the distance between him and his image is', null, '["3 m","5 m","6 m","10 m"]', 2, 'The man is now 3 m from the mirror, and the image is 3 m behind it, so the distance between him and his image is 6 m.', true, '2026-10-12 19:15:47.714', '2026-10-12 19:15:47.714', null, null, null, 'A man stands 4 m in front of a plane mirror. If the mirror is moved 1 m towards the man, the distance between him and his image is', '["3 m","5 m","6 m","10 m"]', 'The man is now 3 m from the mirror, and the image is 3 m behind it, so the distance between him and his image is 6 m.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('188ed7d8-4217-4345-bb38-684ac53c06c2', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). The story is rather <u>hard to believe</u>.', null, '["incredulous","incredible","superstitious","untenable"]', 1, 'Incredible = hard to believe.', true, '2026-10-24 01:04:17.5', '2026-10-24 01:04:17.5', null, null, null, '(Choose the most appropriate interpretation). The story is rather <u>hard to believe</u>.', '["incredulous","<u>incredible</u>","superstitious","untenable"]', '<b>Incredible</b> = <b>hard to believe</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1896c13f-7e0d-41c5-8e3a-fb78962e4f78', 'English Language', 'JAMB', null, 2024, null, 'Which of the following statements is correct (I) If I am opportuned, I will travel to London next week (II) The government has banned child trafficking (III) If she had told me earlier, I wouldn''t employ her (IV) The head of state travels tomorrow', null, '["II&IV","IV","II&III","II","I,II&III"]', 0, 'Statements II and IV are grammatically correct. "Opportuned" is not standard English; "wouldn''t employ" should be "wouldn''t have employed."', true, '2026-09-18 09:43:02.325', '2026-09-18 09:43:02.325', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('18ad0a31-2453-4dbc-ae42-f5771b700bac', 'Literature in English', 'JAMB', null, 2026, null, 'The concept of redemption in the novel is achieved mainly through', null, '["revenge","forgiveness and reconciliation","punishment","exile"]', 1, 'Redemption is achieved through forgiveness and reconciliation.', true, '2026-09-12 11:14:09.345', '2026-09-12 11:14:09.345', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('18ad8874-71df-47c0-8a56-4db9522d7bb4', 'Chemistry', 'JAMB', null, 2026, null, 'CH₄ has this geometry:', null, '["trigonal","planar","tetrahedral","octahedral","linear"]', 2, 'CH₄ has a tetrahedral geometry.', true, '2026-09-12 11:36:09.486', '2026-09-12 11:36:09.486', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('18b3f1e3-1168-404e-a888-b25fba606474', 'Christian Religious Studies', 'JAMB', null, 2026, null, '''But now that faith has come, we are no longer under a custodian....'' Custodian here means the', null, '["church","law","priest","covenant"]', 1, 'The law was our custodian until Christ came (Galatians 3:24-25).', true, '2026-09-12 10:41:27.504', '2026-09-12 10:41:27.504', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('18bc525c-cb93-48be-8fcb-2f342c88cc47', 'Literature in English', 'JAMB', null, 2026, null, 'The phrase ''life''s whole process blooms into stark beauty'' suggests that the celebrant''s life has been', null, '["difficult and without reward","beautiful in spite of its difficulties","completely flawless and easy","struggle with an ugly outcome"]', 1, 'The phrase suggests a beautiful life despite difficulties.', true, '2026-09-12 11:13:46.624', '2026-09-12 11:13:46.624', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('18c246cb-3225-4486-9cab-be3c51c2e664', 'Literature in English', 'JAMB', null, 2026, null, 'Which device involves a deliberate understatement?', null, '["Hyperbole","Litotes","Irony","Paradox"]', 1, 'Litotes involves deliberate understatement.', true, '2026-09-12 11:11:26.023', '2026-09-12 11:11:26.023', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('18c96d6b-abce-4d52-8692-1b8482ecacea', 'Physics', 'JAMB', null, 1997, null, 'The length of a mercury thread when it is at 0 °C, 100 °C and at an unknown temperature θ is 25 mm, 225 mm and 174 mm respectively. The value of θ is', null, '["85.0 °C","80.0 °C","75.0 °C","70.0 °C"]', 2, 'θ = (174 - 25)/(225 - 25) x 100 = 149/200 x 100 ≈ 75 °C.', true, '2026-10-12 19:15:43.361', '2026-10-12 19:15:43.361', null, null, null, 'The length of a mercury thread when it is at 0 °C, 100 °C and at an unknown temperature θ is 25 mm, 225 mm and 174 mm respectively. The value of θ is', '["85.0 °C","80.0 °C","75.0 °C","70.0 °C"]', 'θ = (174 - 25)/(225 - 25) x 100 = 149/200 x 100 ≈ 75 °C.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('18d602ab-8503-44b4-980c-229077a02c81', 'Economics', 'JAMB', null, 2026, null, 'Given Demand function: Qd = 5P + 10; Supply function: Qs = 7P - 5. The equilibrium quantity is', null, '["50","55","75.5","47.5","55.5"]', 3, 'At equilibrium, Qd = Qs. So, 5P + 10 = 7P - 5. Solving: 10 + 5 = 7P - 5P, giving 15 = 2P, so P = 7.5. Substituting P = 7.5 into either equation: Qd = 5(7.5) + 10 = 37.5 + 10 = 47.5. Therefore, equilibrium quantity is 47.5.', true, '2026-09-10 10:41:20.078', '2026-09-10 10:41:20.078', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('18e22cf3-9087-41d5-b3ca-39a318a9895f', 'Government', 'JAMB', null, 2026, null, 'A non-permanent feature of a state is', null, '["Society","Population","Territory","Government"]', 3, 'Government is a non-permanent feature of a state; population, territory, and sovereignty are permanent.', true, '2026-09-12 11:23:57.225', '2026-09-12 11:23:57.225', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('18efd1f8-9467-47b7-84b5-cf93048176c1', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. It is sheer <u>foolhardiness</u> for unarmed policemen to pursue armed robbers.', null, '["nonsense","bravery","foolishness","stupidity","foolish risk taking"]', 4, 'Foolhardiness = foolish risk taking.', true, '2026-10-24 01:03:54.19', '2026-10-24 01:03:54.19', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. It is sheer <u>foolhardiness</u> for unarmed policemen to pursue armed robbers.', '["nonsense","bravery","foolishness","stupidity","<u>foolish risk taking</u>"]', '<b>Foolhardiness</b> = <b>foolish risk taking</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1919eb33-58ab-492c-af84-a6e10dfa2e58', 'Literature in English', 'JAMB', null, 2026, null, '______ is an understatement expressed by using a negation to affirm the opposite', null, '["bildungsroman","picaresque","litotes","hyperbole"]', 2, 'Litotes is an understatement using negation to affirm the opposite.', true, '2026-09-12 11:05:38.302', '2026-09-12 11:05:38.302', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('19347d62-a660-44bd-8a8f-fda0d25edebe', 'Literature in English', 'JAMB', null, 2026, null, 'In the play, why does Mark Antony initially neglect his duties in Rome?', null, '["He is ill and unable to travel","He is deeply engrossed in his love for Cleopatra","He fears political enemies in Rome","He is planning a secret military attack"]', 1, 'Antony neglects his duties because he is engrossed in his love for Cleopatra.', true, '2026-09-12 11:09:49.191', '2026-09-12 11:09:49.191', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('193a3e6a-7809-49cf-8f2d-332b7e2f65ea', 'English Language', 'JAMB', null, 2007, null, 'Tsado and his wife are always fighting. The <u>__________</u> to be drawn from this is that they are not happy together.', null, '["reference","inference","difference","deference"]', 1, 'Correct spelling and meaning: inference.', true, '2026-10-24 07:21:33.095', '2026-10-24 07:21:33.095', null, null, null, 'Tsado and his wife are always fighting. The <u>__________</u> to be drawn from this is that they are not happy together.', '["reference","inference","difference","deference"]', 'Correct spelling and meaning: inference.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1948d8fa-76ec-4758-a992-5e9439aa373d', 'English Language', 'JAMB', null, 2007, null, 'How can we believe this witness when no one will <u>__________</u> his story', null, '["collate","correlate","collaborate","corroborate"]', 3, 'Correct spelling: corroborate.', true, '2026-10-24 07:21:43.617', '2026-10-24 07:21:43.617', null, null, null, 'How can we believe this witness when no one will <u>__________</u> his story', '["collate","correlate","collaborate","corroborate"]', 'Correct spelling: corroborate.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('194948c5-dc27-484d-9784-982dae06f55f', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The Governor''s visit is <u>an unprecedented</u> event in the history of the social club.', null, '["an unnecessary","a momentous","a perfect","an insignificant"]', 3, 'Unprecedented = never before; opposite = insignificant.', true, '2026-10-24 07:21:23.011', '2026-10-24 07:21:23.011', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The Governor''s visit is <u>an unprecedented</u> event in the history of the social club.', '["an unnecessary","a momentous","a perfect","an insignificant"]', 'Unprecedented = never before; opposite = insignificant.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('195d4dd1-a21f-4b3f-b1c8-f4aa0f607241', 'Economics', 'JAMB', null, 2026, null, 'Which of the following is NOT among the objectives of OPEC;', null, '["to stabilize the price of oil in the world market","to establish petroleum refineries in all member state","to make sure that oil flows to all the consuming countries","to stabilize the revenue from oil to producing countries"]', 1, 'OPEC does not aim to establish refineries in all member states.', true, '2026-09-12 11:01:26.317', '2026-09-12 11:01:26.317', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1962fc08-9ab8-40fd-a6e3-3831cd2d0010', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). Publishing as a business venture has become <u>a hot potato</u> in Nigeria.', null, '["unpleasant","profitable","unacceptable","expensive"]', 0, '''A hot potato'' = controversial unpleasant issue.', true, '2026-10-24 01:04:22.813', '2026-10-24 01:04:22.813', null, null, null, '(Choose the most appropriate interpretation). Publishing as a business venture has become <u>a hot potato</u> in Nigeria.', '["<u>unpleasant</u>","profitable","unacceptable","expensive"]', '''A <b>hot potato</b>'' = <b>controversial unpleasant issue</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1965c327-9559-411e-b968-8ac997b4fe50', 'Physics', 'JAMB', null, 1998, null, 'An ebonite rod rubbed with fur attracts a glass rod rubbed with silk because', null, '["Ebonite has a negative charge while glass has a positive charge","Ebonite has a positive charge while glass has a negative charge","Both have negative charges","Both have positive charges."]', 0, 'Ebonite rubbed with fur becomes negative and glass rubbed with silk becomes positive. Unlike charges attract.', true, '2026-10-12 19:15:46.376', '2026-10-12 19:15:46.376', null, null, null, 'An ebonite rod rubbed with fur attracts a glass rod rubbed with silk because', '["Ebonite has a negative charge while glass has a positive charge","Ebonite has a positive charge while glass has a negative charge","Both have negative charges","Both have positive charges."]', 'Ebonite rubbed with fur becomes negative and glass rubbed with silk becomes positive. Unlike charges attract.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('197634af-c1e8-48c5-83a4-14110a1744c6', 'Physics', 'JAMB', null, 2001, null, 'The magnetic force on a charged particle moving with velocity v is', null, '["Proportional to both the magnitude of the charge and the velocity","Independent of the magnitude of the charge","Proportional to the velocity v only","Proportional to the magnitude of the charge only."]', 0, 'F = qvB sin θ, so the force is proportional to both the charge and the velocity.', true, '2026-10-12 19:15:52.727', '2026-10-12 19:15:52.727', null, null, null, 'The magnetic force on a charged particle moving with velocity v is', '["Proportional to both the magnitude of the charge and the velocity","Independent of the magnitude of the charge","Proportional to the velocity v only","Proportional to the magnitude of the charge only."]', 'F = qvB sin θ, so the force is proportional to both the charge and the velocity.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('197b8b47-5031-4bc8-9bad-ec5b90d7d215', 'Literature in English', 'JAMB', null, 2026, null, 'The poet''s attitude towards the celebrant can best be described as', null, '["envious","reverential","sympathetic","apathetic"]', 1, 'The poet''s attitude is reverential.', true, '2026-09-12 11:07:21.886', '2026-09-12 11:07:21.886', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('19805c7c-6963-4c58-b463-db7e29a1420f', 'Physics', 'JAMB', null, 1983, null, 'The range of wavelengths of the visible spectrum is 400 nm - 700 nm. The wavelength of gamma rays is', null, '["Longer than 700 nm","Shorter than 700 nm but longer than 400 nm","550 nm","Shorter than 400 nm","Infinite"]', 3, 'Gamma rays lie far beyond the violet end of the electromagnetic spectrum, with wavelengths much shorter than 400 nm.', true, '2026-10-12 19:15:16.657', '2026-10-12 19:15:16.657', null, null, null, 'The range of wavelengths of the visible spectrum is 400 nm - 700 nm. The wavelength of gamma rays is', '["Longer than 700 nm","Shorter than 700 nm but longer than 400 nm","550 nm","Shorter than 400 nm","Infinite"]', 'Gamma rays lie far beyond the violet end of the electromagnetic spectrum, with wavelengths much shorter than 400 nm.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1980782e-6d40-496d-b8ad-5379c45ab2eb', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The chairman''s conduct <u>redounds</u> to the image of the company.', null, '["contributes to","detracts from","assists in","reflects on"]', 1, 'Redounds = contributes; opposite = detracts from.', true, '2026-10-24 07:21:23.414', '2026-10-24 07:21:23.414', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The chairman''s conduct <u>redounds</u> to the image of the company.', '["contributes to","detracts from","assists in","reflects on"]', 'Redounds = contributes; opposite = detracts from.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('19820c03-cbdb-4559-8dc9-2555b133150c', 'General Mathematics', 'JAMB', null, 2026, null, 'The difference between 33/7 and 9/4 is greater than the sum of 1/14 and 3/2 by', null, '["23/28","24/48","50/56","27/28","48/56"]', 0, '33/7 - 9/4 = (132-63)/28 = 69/28. 1/14 + 3/2 = (1+21)/14 = 22/14 = 44/28. Difference = 69/28 - 44/28 = 25/28. Wait, that''s not 23/28. Let me recalculate: 33/7 = 132/28, 9/4 = 63/28, difference = 69/28. 1/14 = 2/28, 3/2 = 42/28, sum = 44/28. Difference = 69/28 - 44/28 = 25/28. Not in options. The closest is 23/28. The question may have a typo.', true, '2026-09-10 10:48:19.439', '2026-09-10 10:48:19.439', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('198ac0ca-5a91-41ed-8371-094d72cc4ab7', 'General Mathematics', 'JAMB', null, 2026, null, 'A triangle has vertices P(-1, 6), Q(-3, -4) and R(1, -4). Find the midpoints of PQ', null, '["(0, -2) and (-1, -4)","(-2, 1) and (-1, 4)","(-1, 0) and (-1, -1)","(-2, 1) and (0, 1)"]', 0, 'Midpoint PQ = ((-1-3)/2, (6-4)/2) = (-2, 1).', true, '2026-09-12 11:44:17.624', '2026-09-12 11:44:17.624', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1992adbf-192c-4ade-8a12-93e8652d8ef6', 'Financial Accounting', 'UTME', null, 2002, null, 'Keeping records under the single entry system has the advantage of', null, '["quality in terms of records","completeness in terms of records","accuracy in terms of operation","simplicity in terms of operation"]', 3, 'The only advantage that can be derived from single entry system of account is its simplicity in term of operation.', true, '2026-10-12 21:59:58.843', '2026-10-12 21:59:58.843', null, null, null, 'Keeping records under the single entry system has the advantage of', '["quality in terms of records","completeness in terms of records","accuracy in terms of operation","<b>simplicity in terms of operation</b>"]', 'The only advantage that can be derived from single entry system of account is its <b>simplicity in term of operation</b>.', '{"bold":["simplicity in term of operation"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('19a0d2d0-5146-440a-8d87-b0d5288a974d', 'Literature in English', 'JAMB', null, 2026, null, 'Tragedy is from the Greek word which translates into meaning', null, '["tragos, goat song","tragedos, sad song","tragoedia, lament","tragoidia, goat song"]', 0, 'Tragedy is from the Greek word ''tragos'' which translates into ''goat song'' meaning. The word tragedy comes from the Greek ''tragoidia'' which combines ''tragos'' (goat) and ''ode'' (song), referring to the goat-song sung at festivals honoring Dionysus. The goat was sacred to Dionysus, and the songs were part of religious rituals that evolved into tragic drama.', true, '2026-09-10 10:47:53.726', '2026-09-10 10:47:53.726', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('19ae6c72-15af-46eb-ac2e-dd4781661da0', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Bose was angry because her friend called her a <u>pilferer</u>.', null, '["liar","hypocrite","criminal","thief"]', 3, 'Pilferer = thief.', true, '2026-10-24 01:04:03.211', '2026-10-24 01:04:03.211', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Bose was angry because her friend called her a <u>pilferer</u>.', '["liar","hypocrite","criminal","<u>thief</u>"]', '<b>Pilferer</b> = <b>thief</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('19b0f043-7f79-43be-9d68-7326e9de4d55', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The greatness of the creator of the universe is always <u>inexpressible</u> to many adherents.', null, '["ineffable","unbearable","wonderful","inevitable"]', 0, 'Inexpressible = ineffable.', true, '2026-10-24 01:01:53.745', '2026-10-24 01:01:53.745', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The greatness of the creator of the universe is always <u>inexpressible</u> to many adherents.', '["<u>ineffable</u>","unbearable","wonderful","inevitable"]', '<b>Inexpressible</b> = <b>ineffable</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('19b1e491-2c31-4b05-98c4-7bd6d87d4884', 'Biology', 'JAMB', null, 2001, null, 'The greatest influence on a stable ecosystem in nature is excreted by', null, '["rainfall","animals","man","pollution"]', 2, 'Human activities have the greatest impact on ecosystem stability.', true, '2026-10-12 20:59:29.159', '2026-10-12 20:59:29.159', null, null, null, 'The greatest influence on a stable ecosystem in nature is excreted by', '["rainfall","animals","man","pollution"]', 'Human activities have the greatest impact on ecosystem stability.', '{"bold":["Human activities"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('19b25f07-735e-4edf-bc1e-055d5572dfd7', 'Economics', 'JAMB', null, 2026, null, 'The Nigerian bank for commerce and industry is?', null, '["a commercial bank","a development bank","an industrial bank","a merchant bank"]', 2, 'The Nigerian Bank for Commerce and Industry is an industrial bank.', true, '2026-09-12 11:00:51.178', '2026-09-12 11:00:51.178', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('19e103cd-9f22-4e4d-867f-afd3733ae403', 'Economics', 'JAMB', null, 2026, null, 'The number of people who are qualified to work and who offer themselves for employment is called?', null, '["Migrant labour","Working population","Mobility of labour","Labour turnover"]', 1, 'The working population refers to those qualified and available for employment.', true, '2026-09-12 10:58:58.289', '2026-09-12 10:58:58.289', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('19f4d76a-bc79-4835-a660-b5417a75deb3', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The nurse was in favour of voluntary <u>euthanasia</u>.', null, '["a painless death","a simple operation","a sleeping pill","a major operation"]', 0, 'Euthanasia = painless death.', true, '2026-10-24 01:04:04.67', '2026-10-24 01:04:04.67', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The nurse was in favour of voluntary <u>euthanasia</u>.', '["<u>a painless death</u>","a simple operation","a sleeping pill","a major operation"]', '<b>Euthanasia</b> = <b>a painless death</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('19f9311e-7375-467b-ba97-794b3eef32d4', 'English Language', 'JAMB', null, 2007, null, 'Vacancies in the company will be notified by <u>__________</u>', null, '["bulletin","publication","publicity","advertisement"]', 3, 'Correct spelling: advertisement.', true, '2026-10-24 07:21:39.318', '2026-10-24 07:21:39.318', null, null, null, 'Vacancies in the company will be notified by <u>__________</u>', '["bulletin","publication","publicity","advertisement"]', 'Correct spelling: advertisement.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('19fa349c-bbf0-4d0c-b7b4-a00b43d208a0', 'English Language', 'JAMB', null, 2007, null, 'Mark is a very handsome fellow who informs me that he has <u>__________</u> for pretty girls', null, '["a heart","a lip","an eye","a check"]', 2, 'Correct form: an eye for.', true, '2026-10-24 07:21:41.853', '2026-10-24 07:21:41.853', null, null, null, 'Mark is a very handsome fellow who informs me that he has <u>__________</u> for pretty girls', '["a heart","a lip","an eye","a check"]', 'Correct form: an eye for.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1a0afa3d-0946-4979-95bb-ff53a2429987', 'Chemistry', 'JAMB', null, 2026, null, 'Which is a strong acid?', null, '["Ethanoic acid","Carbonic acid","Hydrochloric acid","Citric acid"]', 2, 'Hydrochloric acid is a strong acid that fully dissociates in water.', true, '2026-09-12 11:32:58.966', '2026-09-12 11:32:58.966', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1a0d7e0a-1fd6-435f-a8fb-431800997569', 'General Mathematics', 'JAMB', null, 2026, null, 'Find the equation of the perpendicular bisector of the line segment joining the points P(-3, 2) and Q(5, -4)', null, '["4x - 3y = 7","4x + 3y = 1","3x + 4y = -1","3x - 4y = 9"]', 2, 'Midpoint = (1, -1). Slope PQ = -6/8 = -3/4. Perpendicular slope = 4/3. Equation: y+1 = 4/3(x-1). 3y+3 = 4x-4. 4x-3y = 7. The answer is (A) 4x - 3y = 7.', true, '2026-09-12 11:43:50.695', '2026-09-12 11:43:50.695', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1a11d004-2837-45e0-8a27-16835514cc15', 'Yoruba', 'JAMB', null, 2007, null, 'I am indisposed tûmõ sí', null, '["Ara mi kò yá","Mò p gbõn","Ara mi kò balê","Mo ni àrùn."]', 0, 'I am indisposed tûmõ sí Ara mi kò yá.', true, '2026-10-13 13:23:31.631', '2026-10-13 13:23:31.631', null, null, null, 'I am indisposed tûmõ sí', '["Ara mi kò yá","Mò p gbõn","Ara mi kò balê","Mo ni àrùn."]', 'I am indisposed tûmõ sí Ara mi kò yá.', '{"bold":["Ara mi kò yá"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1a14228d-7e12-4299-b317-83707876e2bf', 'Physics', 'JAMB', null, 1983, null, 'The speed of light in vacuum is 3.0 x 10⁸ m s⁻¹. If the refractive index of a transparent liquid is 4/3, then the speed of light in the liquid is', null, '["0.44 x 10⁸ m s⁻¹","2.25 x 10⁸ m s⁻¹","3.0 x 10⁸ m s⁻¹","4.0 x 10⁸ m s⁻¹","4.33 x 10⁸ m s⁻¹"]', 1, 'v = c/n = (3.0 x 10⁸)/(4/3) = 2.25 x 10⁸ m s⁻¹.', true, '2026-10-12 19:15:18.147', '2026-10-12 19:15:18.147', null, null, null, 'The speed of light in vacuum is 3.0 x 10<sup>8</sup> m s<sup>-1</sup>. If the refractive index of a transparent liquid is 4/3, then the speed of light in the liquid is', '["0.44 x 10<sup>8</sup> m s<sup>-1</sup>","2.25 x 10<sup>8</sup> m s<sup>-1</sup>","3.0 x 10<sup>8</sup> m s<sup>-1</sup>","4.0 x 10<sup>8</sup> m s<sup>-1</sup>","4.33 x 10<sup>8</sup> m s<sup>-1</sup>"]', 'v = c/n = (3.0 x 10<sup>8</sup>)/(4/3) = 2.25 x 10<sup>8</sup> m s<sup>-1</sup>.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1a170531-a3d0-4c62-818b-f548a88ff385', 'English Language', 'JAMB', null, 2024, null, 'Choose the option that has the correct stress: participate', null, '["par-ti-CI-pate","PAR-ti-ci-pate","par-ti-ci-PATE","par-TI-ci-pate"]', 0, 'The stress is on the third syllable: par-ti-CI-pate.', true, '2026-09-18 09:23:08.461', '2026-09-18 09:23:08.461', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1a1a868d-1eff-4365-a541-6f6a798d87a8', 'Economics', 'JAMB', null, 2026, null, 'The population density of a town made up of 50 square kilometer land area and 100 million people is', null, '["2 million people per sq km","0.5 million people per sq km","20 million people per sq km","50,000 people per sq km"]', 0, 'Population density = Population / Land area = 100,000,000 / 50 = 2,000,000 people per sq km.', true, '2026-09-12 10:58:59.109', '2026-09-12 10:58:59.109', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1a26e4c2-90fd-4cd6-af44-7ce7d825e71b', 'Biology', 'JAMB', null, 2005, null, 'When bacteria swim from cold to warm regions, this is known as', null, '["negative chemotaxis","positive thermotaxis","positive photoaxis","negative phototaxis"]', 1, 'Movement towards warmth is positive thermotaxis.', true, '2026-10-12 20:59:37.53', '2026-10-12 20:59:37.53', null, null, null, 'When bacteria swim from cold to warm regions, this is known as', '["negative chemotaxis","positive thermotaxis","positive photoaxis","negative phototaxis"]', 'Movement towards warmth is positive thermotaxis.', '{"bold":["positive thermotaxis"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1a313c84-5094-43ac-8fd4-82d04fca8ea6', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The young man who distributed political pamphlets on campus was promptly <u>repudiated</u>.', null, '["disowned","arrested","warned","killed"]', 0, 'Repudiated = disowned.', true, '2026-10-24 01:01:49.18', '2026-10-24 01:01:49.18', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The young man who distributed political pamphlets on campus was promptly <u>repudiated</u>.', '["<u>disowned</u>","arrested","warned","killed"]', '<b>Repudiated</b> = <b>disowned</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1a386b5f-48c7-4836-b48e-43713ea28508', 'English Language', 'JAMB', null, 2024, null, 'Choose the most appropriate interpretation: Had it been possible to leave the country then, I would have done so.', null, '["I have not left the country and nothing will make me leave","I wanted to leave the country and I did","I will definitely leave the country one day when I have the opportunity","I would have liked to leave the country but I wasn''t able to"]', 3, 'The third conditional expresses an unreal past desire: the speaker wanted to leave but couldn''t.', true, '2026-09-18 09:24:04.939', '2026-09-18 09:24:04.939', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1a4c3ba3-5a2d-48ce-bb1c-d595719ffca3', 'General', 'JAMB', null, 2024, null, 'What is the capital of Nigeria?', null, '["Abuja","Lagos","Kano","Ibadan"]', 0, null, true, '2026-10-31 16:40:40.52', '2026-10-31 16:40:40.52', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1a535a61-ee6e-480e-a5f9-bc407d89f425', 'Literature in English', 'JAMB', null, 2026, null, 'In She Walks in Beauty, the contrast between ''dark'' and ''bright'' primarily emphasizes', null, '["Moral conflict","Physical environment","Harmonious balance in beauty","Supernatural imagery"]', 2, 'The contrast emphasizes harmonious balance in beauty.', true, '2026-09-12 11:09:53.112', '2026-09-12 11:09:53.112', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1a542e50-b44d-4735-be1a-a9c61282c853', 'Physics', 'JAMB', null, 2000, null, 'A radio is operated by eight cells each of e.m.f. 2.0 V connected in series. If two of the cells are wrongly connected, the net e.m.f. of the radio is', null, '["16 V","12 V","10 V","8 V"]', 3, 'Six cells add (+12 V) and the two reversed cells subtract (-4 V): net = 12 - 4 = 8 V.', true, '2026-10-12 19:15:50.182', '2026-10-12 19:15:50.182', null, null, null, 'A radio is operated by eight cells each of e.m.f. 2.0 V connected in series. If two of the cells are wrongly connected, the net e.m.f. of the radio is', '["16 V","12 V","10 V","8 V"]', 'Six cells add (+12 V) and the two reversed cells subtract (-4 V): net = 12 - 4 = 8 V.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1a5f43e4-f798-4802-9a96-630b78dce12a', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Nwankwo was on the <u>verge</u> of signing a two-year contract with the club.', null, '["shore","summit","brink","height"]', 2, 'Verge = brink.', true, '2026-10-24 01:01:58.345', '2026-10-24 01:01:58.345', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Nwankwo was on the <u>verge</u> of signing a two-year contract with the club.', '["shore","summit","<u>brink</u>","height"]', '<b>Verge</b> = <b>brink</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1a74104d-c318-4c69-a3e5-70362c4a0f23', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. We were warned not to indulge in <u>recrimination</u>.', null, '["accusation","indiscretion","counter-charge","frivolous allegation"]', 2, 'Recrimination = counter-charge.', true, '2026-10-24 01:01:56.966', '2026-10-24 01:01:56.966', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. We were warned not to indulge in <u>recrimination</u>.', '["accusation","indiscretion","<u>counter-charge</u>","frivolous allegation"]', '<b>Recrimination</b> = <b>counter-charge</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1a7fb2d5-9fa7-4311-89a5-7c01c2c7f998', 'English Language', 'JAMB', null, 2024, null, 'Either the teacher or the students ______ to blame', null, '["Is","Are","Has being","Are being"]', 1, 'With "either...or," the verb agrees with the nearest subject, which is "students" (plural), so "are" is correct.', true, '2026-09-18 09:34:03.989', '2026-09-18 09:34:03.989', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1a8378ae-1fd2-4fd6-a7e9-f84c9bd33397', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The sales were lively; the <u>upset price</u> in each case was fair.', null, '["price that was the highest in the sales","price that upset every other buyer","highest amount for a bidder to offer","lowest selling price of each item"]', 3, 'Upset price = lowest selling price.', true, '2026-10-24 01:01:48.652', '2026-10-24 01:01:48.652', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The sales were lively; the <u>upset price</u> in each case was fair.', '["price that was the highest in the sales","price that upset every other buyer","highest amount for a bidder to offer","<u>lowest selling price of each item</u>"]', '<b>Upset price</b> = <b>lowest selling price</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1a8fe8b0-1f13-49bd-b576-62ea0529c78e', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Abdul is fond of his teacher though he sometimes makes <u>derogatory</u> remarks about him.', null, '["unpleasant","complimentary","expressive","inconsiderate"]', 1, 'Derogatory = belittling; opposite = complimentary.', true, '2026-10-24 07:21:20.502', '2026-10-24 07:21:20.502', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Abdul is fond of his teacher though he sometimes makes <u>derogatory</u> remarks about him.', '["unpleasant","complimentary","expressive","inconsiderate"]', 'Derogatory = belittling; opposite = complimentary.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1a92709d-eb28-4229-b989-ce894629fab1', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Ibro shows enough <u>liberality</u> with his meager income.', null, '["insensitivity","prodigality","frugality","generosity"]', 3, 'Liberality = generosity.', true, '2026-10-24 01:01:52.729', '2026-10-24 01:01:52.729', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Ibro shows enough <u>liberality</u> with his meager income.', '["insensitivity","prodigality","frugality","<u>generosity</u>"]', '<b>Liberality</b> = <b>generosity</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1a92a867-a0bc-4736-826f-ff4d19ce2c4b', 'English Language', 'JAMB', null, 2007, null, 'Oche should leave for New York on Friday <u>__________</u> being equal.', null, '["all the things","all other things","other things","other things all"]', 2, 'Correct idiom: other things being equal.', true, '2026-10-24 07:21:34.152', '2026-10-24 07:21:34.152', null, null, null, 'Oche should leave for New York on Friday <u>__________</u> being equal.', '["all the things","all other things","other things","other things all"]', 'Correct idiom: other things being equal.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1a97458e-9bd3-40ba-8168-84a4b227facb', 'testing', 'JAMB', null, 2024, null, 'One of the boys who ...... punished yesterday has apologised', null, '["was","is","were","has been"]', 1, '''Who'' refers to ''boys'' (plural) → ''were''.', true, '2026-10-31 16:48:52.78', '2026-10-31 16:48:52.78', null, null, null, 'One of the boys who ...... punished yesterday has apologised', '["was","is","were","has been"]', '''Who'' refers to ''boys'' (plural) → ''were''.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1aa0def0-f26f-49cc-ab5d-32d66e21427c', 'Physics', 'JAMB', null, 1987, null, 'When a transformer has more secondary winding than primary winding, it', null, '["Has a smaller secondary current","Has a greater power output","Is a step-down transformer","Increases the total energy output."]', 0, 'It is a step-up transformer. Power in is about equal to power out, so the secondary voltage is larger and the secondary current is smaller.', true, '2026-10-12 19:15:26.299', '2026-10-12 19:15:26.299', null, null, null, 'When a transformer has more secondary winding than primary winding, it', '["Has a smaller secondary current","Has a greater power output","Is a step-down transformer","Increases the total energy output."]', 'It is a step-up transformer. Power in is about equal to power out, so the secondary voltage is larger and the secondary current is smaller.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1aa60e9f-05e9-4b98-ad66-572462c9f876', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). Smiling broadly, she explained why she always <u>took exception to</u> being referred to as an old maid.', null, '["objected to","preferred very much","felt specially honoured by","liked nothing excepts"]', 0, '''Took exception to'' = objected to.', true, '2026-10-24 01:02:07.706', '2026-10-24 01:02:07.706', null, null, null, '(Choose the most appropriate interpretation). Smiling broadly, she explained why she always <u>took exception to</u> being referred to as an old maid.', '["<u>objected to</u>","preferred very much","felt specially honoured by","liked nothing excepts"]', '''<b>Took exception to</b>'' = <b>objected to</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1aa896aa-c5e4-4f19-8484-dc955a50760c', 'Biology', 'JAMB', null, 2012, null, 'Which of the following is true in blood transfusion?', null, '["A person of blood group AB can donate blood only to another person of blood group AB.","Person of blood groups A and B can donate or receive blood from each other.","A person of blood group AB can receive blood only from persons of blood group A or B.","A person of blood group O can donate only to a person of blood group O."]', 0, 'A person of blood group AB can donate blood only to another person of blood group AB.', true, '2026-10-12 20:59:45.602', '2026-10-12 20:59:45.602', null, null, null, 'Which of the following is true in blood transfusion?', '["A person of blood group AB can donate blood only to another person of blood group AB.","Person of blood groups A and B can donate or receive blood from each other.","A person of blood group AB can receive blood only from persons of blood group A or B.","A person of blood group O can donate only to a person of blood group O."]', 'A person of blood group AB can donate blood only to another person of blood group AB.', '{"bold":["AB can donate blood only to another person of blood group AB"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1aa98d1f-7d42-4908-8552-73fe422e036b', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Samson, as a Nazarite was required to avoid alcohol,', null, '["omen and dead lions","unclean things and shaving","shaving and swearing","shaving and women"]', 1, 'As a Nazarite, Samson was required to avoid alcohol, unclean things, and shaving. The Nazarite vow included abstaining from wine and strong drink, not touching unclean things, and not cutting the hair.', true, '2026-09-12 09:46:09.348', '2026-09-12 09:46:09.348', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1aba9c73-126a-4f29-9012-78c2d114349c', 'Government', 'JAMB', null, 2026, null, 'The African leader mostly credited for spearheading the formation of the African Union is', null, '["Abdelziz Bouteflika","Abdoulaye Wade","Muammar Ghaddafi","Thabo Mbeki"]', 2, 'Muammar Ghaddafi spearheaded the formation of the African Union.', true, '2026-09-12 11:24:41.562', '2026-09-12 11:24:41.562', null, null, null, null, null, null, null);
