insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1ac5f979-3e75-4597-b9a7-7a43c47f568a', 'English Language', 'JAMB', null, 2024, null, 'Choose the option that best explains the information conveyed in the sentence: Amedu''s actions provoked severe criticism', null, '["his actions provoked the humour","his actions were itemized because he was young","his actions were severe and accepted","his actions were seriously rejected"]', 3, '"Provoked severe criticism" means his actions were seriously rejected.', true, '2026-09-18 09:43:02.91', '2026-09-18 09:43:02.91', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1acd4852-2c2a-496d-b1c5-7b4ce8bd52db', 'Christian Religious Studies', 'JAMB', null, 2026, null, '''Let it be known to you then that this salvation of God has been sent to the Gentiles, they will listen.'' This implies that', null, '["the Gentiles will be more receptive to Christianity than the Jews","the Jews have lost the opportunity of salvation forever","the Gentiles are very understanding","Paul has completely lost hope in the Jews"]', 0, 'This statement implies that the Gentiles will be more receptive to Christianity than the Jews. Paul declared this after the Jews in Rome rejected the gospel, stating that the Gentiles would listen.', true, '2026-09-12 09:45:55.136', '2026-09-12 09:45:55.136', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1ad1a746-0cfe-4b95-aa74-e8c0d3626f47', 'Literature in English', 'JAMB', null, 2026, null, 'The novel "Animal Farm" by George Orwell is best described as', null, '["romantic fiction","political allegory","travel narrative","biography"]', 1, '"Animal Farm" by George Orwell is best described as a political allegory. The novel uses farm animals to represent the events and figures of the Russian Revolution and the rise of Stalinism. It is an allegory because it has a hidden political meaning beneath the surface story. It is not romantic fiction, a travel narrative, or a biography.', true, '2026-09-10 10:45:33.967', '2026-09-10 10:45:33.967', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1ad649fb-33f4-4d08-b562-9dd0fe66bde1', 'English Language', 'JAMB', null, 2007, null, 'Tosin refused to be <u>__________</u> though he has written the same examination three times', null, '["sad","placated","frustrated","indifferent"]', 2, 'Correct spelling: frustrated.', true, '2026-10-24 07:21:43.062', '2026-10-24 07:21:43.062', null, null, null, 'Tosin refused to be <u>__________</u> though he has written the same examination three times', '["sad","placated","frustrated","indifferent"]', 'Correct spelling: frustrated.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1b0888bc-799c-45a7-8f08-93a25ed1f533', 'Chemistry', 'JAMB', null, 2026, null, 'The heat energy released when one mole of an ionic solid is formed from its gaseous ions is known as', null, '["bond energy","hydration energy","lattice energy","ionization energy"]', 2, 'Lattice energy measures the enthalpy change when constituent gaseous ions combine to form one mole of an ionic crystalline solid.', true, '2026-09-09 17:12:48.003', '2026-09-09 17:12:48.003', null, null, null, null, null, null, null);
