insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1b26ca43-1078-4ed7-bbbf-24cb11c37fc4', 'English Language', 'JAMB', null, 0, null, '12', null, '["back down ","hold out ","keepup","go away "]', 0, 'Workers will soon back down (give in) if they are not serious.', true, '2026-09-18 09:08:13.483', '2026-09-18 09:08:13.483', '1edea09d-7ad3-4c90-8c54-eeb4b369dcff', 11, 'CLOZE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1b2ed943-8221-4ffc-8432-179f09a02dc8', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The use of this equipment should <u>obviate</u> the problem.', null, '["prevent","improve","promote","worsen"]', 0, 'Obviate = prevent.', true, '2026-10-24 01:04:11.277', '2026-10-24 01:04:11.277', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The use of this equipment should <u>obviate</u> the problem.', '["<u>prevent</u>","improve","promote","worsen"]', '<b>Obviate</b> = <b>prevent</b>.', '{}');
