insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1b466d59-06c6-42ec-a136-f76e6f25ab0a', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Adams is a <u>die-hard</u> criminal.', null, '["hard to kill","hard to arrest","remorseless","relentless"]', 2, 'Die-hard = remorseless.', true, '2026-10-24 01:04:01.352', '2026-10-24 01:04:01.352', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Adams is a <u>die-hard</u> criminal.', '["hard to kill","hard to arrest","<u>remorseless</u>","relentless"]', '<b>Die-hard</b> = <b>remorseless</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1b56cd7e-4bdf-4a3c-81c2-e598218dd0ee', 'Physics', 'JAMB', null, 1999, null, 'Calculate the mass of ice that would melt when 2 kg of copper is quickly transferred from boiling water to a block of ice without heat loss. [Specific heat capacity of copper = 400 J kg⁻¹ K⁻¹; Latent heat of fusion of ice = 3.3 x 10⁵ J kg⁻¹]', null, '["8/33 kg","33/80 kg","80/33 kg","33/8 kg"]', 0, 'Heat lost by the copper = 2 x 400 x 100 = 80 000 J. Mass of ice melted = 80 000/(3.3 x 10⁵) = 8/33 kg.', true, '2026-10-12 19:15:47.876', '2026-10-12 19:15:47.876', null, null, null, 'Calculate the mass of ice that would melt when 2 kg of copper is quickly transferred from boiling water to a block of ice without heat loss. [Specific heat capacity of copper = 400 J kg<sup>-1</sup> K<sup>-1</sup>; Latent heat of fusion of ice = 3.3 x 10<sup>5</sup> J kg<sup>-1</sup>]', '["8/33 kg","33/80 kg","80/33 kg","33/8 kg"]', 'Heat lost by the copper = 2 x 400 x 100 = 80 000 J. Mass of ice melted = 80 000/(3.3 x 10<sup>5</sup>) = 8/33 kg.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1b62426b-0f7a-4460-99ed-40a0daac2643', 'English Language', 'JAMB', null, 2024, null, 'You know that you ______ it before tomorrow', null, '["might do","ought to do","like to do","may do"]', 1, '"Ought to do" expresses obligation or expectation.', true, '2026-09-18 09:43:02.26', '2026-09-18 09:43:02.26', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1b7b464c-b3a8-4ca5-8a98-0784b27cf88e', 'Literature in English', 'JAMB', null, 2026, null, 'Which of the following is NOT a theme in the poem?', null, '["post-colonial identity","the importance of preserving ancient myths","the cyclical nature of violence and suffering","environmental pollution"]', 1, 'The importance of preserving ancient myths is not a theme.', true, '2026-09-12 11:10:46.771', '2026-09-12 11:10:46.771', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1b8351bc-cbe1-4f9f-a1c1-0b120b739bed', 'Physics', 'JAMB', null, 1994, null, 'If two parallel conductors carry currents flowing in the same direction, the conductors will', null, '["Attract each other","Repel each other","Both move in the same direction","Have no effect on each other."]', 0, 'Parallel conductors with currents in the same direction attract each other.', true, '2026-10-12 19:15:40.451', '2026-10-12 19:15:40.451', null, null, null, 'If two parallel conductors carry currents flowing in the same direction, the conductors will', '["Attract each other","Repel each other","Both move in the same direction","Have no effect on each other."]', 'Parallel conductors with currents in the same direction attract each other.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1b8ac789-4ab3-4e7f-8219-636330e480e0', 'English Language', 'JAMB', null, 2007, null, 'Which of the following sentences is correct: A. She has ran five times today B. She has run five times today C. She has being running five times daily D. She has ranned five times today', null, '["She has ran five times today","She has run five times today","She has being running five times daily","She has ranned five times today"]', 1, 'Past participle of ''run'' is ''run''.', true, '2026-10-25 18:25:06.902', '2026-10-25 18:25:06.902', null, null, null, 'Which of the following sentences is correct: A. She has ran five times today B. She has run five times today C. She has being running five times daily D. She has ranned five times today', '["She has ran five times today","She has run five times today","She has being running five times daily","She has ranned five times today"]', 'Past participle of ''run'' is ''run''.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1b8b113a-726b-4b30-8645-79aef5293db0', 'General Mathematics', 'JAMB', null, 2026, null, 'Factorize: x² - 5x + 6', null, '["(x-2)(x-3)","(x+2)(x+3)","(x-1)(x-6)","(x+1)(x-6)"]', 0, 'x² - 5x + 6 = (x-2)(x-3).', true, '2026-09-12 11:44:07.603', '2026-09-12 11:44:07.603', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1b8ca023-c8a9-4ecc-bf21-9f9d8f3b94a3', 'Biology', 'JAMB', null, 2026, null, 'A dilute solution of phenylthiocarbamide tastes bitter to some people and is tasteless to others. This is an example of', null, '["Taste bud variation","Discontinuous variation","Morphological variation","Continuous variation"]', 1, 'PTC tasting ability is an example of discontinuous variation. The ability to taste PTC is controlled by a single gene with two alleles: taster (T) and non-taster (t). People are either tasters or non-tasters with no intermediate types. Discontinuous variation produces distinct, non-overlapping categories. Continuous variation shows a gradation of values (like height, weight). Morphological variation refers to physical structure differences. This is not just about taste buds; it''s a specific genetic trait demonstrating discontinuous variation.', true, '2026-09-09 03:18:58.572', '2026-09-09 03:18:58.572', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1b97d036-5164-4173-8963-12df424ac5bf', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The actress <u>screamed</u> when she noticed an object behind her.', null, '["protested","waded in","stormed out","wailed"]', 3, 'Screamed = wailed.', true, '2026-10-24 01:04:10.901', '2026-10-24 01:04:10.901', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The actress <u>screamed</u> when she noticed an object behind her.', '["protested","waded in","stormed out","<u>wailed</u>"]', '<b>Screamed</b> = <b>wailed</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1ba843a9-f500-448a-937d-ef70079d7b4d', 'Physics', 'JAMB', null, 2004, null, 'In a reverse biased junction diode, current flows by', null, '["Electrons alone","Majority carriers","Minority carriers","Positive holes alone"]', 2, 'Reverse bias blocks majority carriers. The small leakage current is carried by minority carriers.', true, '2026-10-12 19:15:59.302', '2026-10-12 19:15:59.302', null, null, null, 'In a reverse biased junction diode, current flows by', '["Electrons alone","Majority carriers","Minority carriers","Positive holes alone"]', 'Reverse bias blocks majority carriers. The small leakage current is carried by minority carriers.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1ba84fd7-4e3b-4230-9091-a5207f8ef0af', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). ''<u>I can''t wait to</u> become a mother,'' the new bride declared.', null, '["She sees motherhood as a burden","She is excited about motherhood","She is not keen on becoming a mother","She will be patient as a mother"]', 1, '''Can''t wait'' = excited about.', true, '2026-10-24 01:04:23.507', '2026-10-24 01:04:23.507', null, null, null, '(Choose the most appropriate interpretation). ''<u>I can''t wait to</u> become a mother,'' the new bride declared.', '["She sees motherhood as a burden","<u>She is excited about motherhood</u>","She is not keen on becoming a mother","She will be patient as a mother"]', '''<b>Can''t wait</b>'' = <b>excited about</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1bba5a9e-9d75-4d38-9e0c-730ed4ee5e3d', 'Physics', 'JAMB', null, 2026, null, 'Which of the following are true for alpha decay? (I) mass number decrease by 4 (II) atomic number decrease by 2 (III) mass number does not change', null, '["I & II","II & III","I & III","I, II & III"]', 0, 'In alpha decay, the mass number decreases by 4 and the atomic number decreases by 2. An alpha particle is a helium nucleus (⁴₂He). So statements I and II are true. Statement III is false.', true, '2026-09-10 10:56:40.49', '2026-09-10 10:56:40.49', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1bc35381-e803-45ea-bbdf-130d570e229c', 'Yoruba', 'JAMB', null, 2007, null, 'Nínú Owó, ohun ti akẹwì dàníyan kí ó pa òun ti ni', null, '["ìjayà","òjì","ayé","ajé."]', 1, 'Ohun ti akẹwì dàníyan kí ó pa òun ti ni òjì.', true, '2026-10-13 13:23:32.34', '2026-10-13 13:23:32.34', null, null, null, 'Nínú Owó, ohun ti akẹwì dàníyan kí ó pa òun ti ni', '["ìjayà","òjì","ayé","ajé."]', 'Ohun ti akẹwì dàníyan kí ó pa òun ti ni òjì.', '{"bold":["òjì"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1bc957af-5be3-4075-8462-40bfe38045c6', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Akoso thought that her father was very <u>callous</u>.', null, '["indifferent","compassionate","wicked","careless"]', 1, 'Callous = unfeeling; opposite = compassionate.', true, '2026-10-24 07:21:18.461', '2026-10-24 07:21:18.461', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Akoso thought that her father was very <u>callous</u>.', '["indifferent","compassionate","wicked","careless"]', 'Callous = unfeeling; opposite = compassionate.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1bcd788a-5f04-48ea-84d6-de7a2c4655c2', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The way the workshop was organized was rather <u>hit-and-miss</u>.', null, '["systematic","slow","hasty","funny"]', 0, 'Hit-and-miss = unplanned; opposite = systematic.', true, '2026-10-24 07:21:27.505', '2026-10-24 07:21:27.505', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The way the workshop was organized was rather <u>hit-and-miss</u>.', '["systematic","slow","hasty","funny"]', 'Hit-and-miss = unplanned; opposite = systematic.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1bd17f2d-87a8-420c-9e56-8bcabba227d1', 'Physics', 'JAMB', null, 1986, null, 'Which of the following is a derived unit?', null, '["Kilogramme","Metre","Kelvin","Newton"]', 3, 'The kilogram, metre and kelvin are base SI units. The newton is derived (kg m s⁻²).', true, '2026-10-12 19:15:22.77', '2026-10-12 19:15:22.77', null, null, null, 'Which of the following is a derived unit?', '["Kilogramme","Metre","Kelvin","Newton"]', 'The kilogram, metre and kelvin are base SI units. The newton is derived (kg m s<sup>-2</sup>).', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1bdb2ae2-467c-4e9a-9fab-6bda898168c7', 'Literature in English', 'JAMB', null, 2026, null, 'In Redemption Road, the narrative structure is best described as', null, '["A linear plot focusing on a single protagonist''s growth","A non-linear narrative employing multiple perspectives to depict post-war trauma","A dramatic monologue centred on a single voice","A purely epistolary narrative composed of letters"]', 1, 'The narrative is non-linear, employing multiple perspectives to depict post-war trauma.', true, '2026-09-12 11:12:00.291', '2026-09-12 11:12:00.291', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1bdc5bf2-f82c-4072-af70-764b474aaaa1', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. He is <u>notorious</u> for his drunkenness.', null, '["known","renowned","popular","well known"]', 1, 'Notorious = infamous; opposite = renowned.', true, '2026-10-24 07:21:23.715', '2026-10-24 07:21:23.715', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. He is <u>notorious</u> for his drunkenness.', '["known","renowned","popular","well known"]', 'Notorious = infamous; opposite = renowned.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1be4a976-00d9-475f-8e04-ddebda894d5f', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). I didn''t think she could be so easily <u>taken in</u> by his pretences.', null, '["flattered","deceived","overcome","blackmailed"]', 1, '''Taken in'' = deceived.', true, '2026-10-24 01:02:05.113', '2026-10-24 01:02:05.113', null, null, null, '(Choose the most appropriate interpretation). I didn''t think she could be so easily <u>taken in</u> by his pretences.', '["flattered","<u>deceived</u>","overcome","blackmailed"]', '''<b>Taken in</b>'' = <b>deceived</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1be64ddb-cf78-4869-9403-cdea98a15d70', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Though his parents'' poverty placed many <u>obstacles</u> in his path as a young man, Olu succeeded at last.', null, '["hurdles","advantages","temptations","diversions"]', 1, 'Obstacles = hindrances; opposite = advantages.', true, '2026-10-24 07:21:13.514', '2026-10-24 07:21:13.514', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Though his parents'' poverty placed many <u>obstacles</u> in his path as a young man, Olu succeeded at last.', '["hurdles","advantages","temptations","diversions"]', 'Obstacles = hindrances; opposite = advantages.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1be70149-904c-45e9-b092-e8a9bdb0dd97', 'Chemistry', 'JAMB', null, 2026, null, 'A compound contains 24g of carbon, 4g of hydrogen and 32g of oxygen. Determine its empirical formula.', null, '["CH₂O","C₂H₄O₂","CHO","C₃H₆O₃"]', 1, 'Moles: C = 24/12 = 2, H = 4/1 = 4, O = 32/16 = 2. Ratio = 2:4:2 = 1:2:1. Empirical formula = CH₂O. Wait, the ratio is 2:4:2 which simplifies to 1:2:1. So the empirical formula is CH₂O. But the option CH₂O is (A). The question asks for the empirical formula. The correct answer is (A) CH₂O.', true, '2026-09-12 11:32:54.925', '2026-09-12 11:32:54.925', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1be83f3b-fc86-4116-8c63-9de26091c6fc', 'Biology', 'JAMB', null, 2003, null, 'The dark reaction of photosynthesis involves the', null, '["reduction of carbon (IV) oxide to organic compounds","release of oxygen and the splitting of water","photolysis of water and the production of starch","splitting of water into hydrogen ions"]', 0, 'During the dark reactions (Calvin cycle), carbon dioxide is reduced to form organic sugar molecules.', true, '2026-10-12 20:05:09.6', '2026-10-12 20:05:09.6', null, null, null, 'The dark reaction of photosynthesis involves the', '["reduction of carbon (IV) oxide to organic compounds","release of oxygen and the splitting of water","photolysis of water and the production of starch","splitting of water into hydrogen ions"]', 'During the dark reactions (Calvin cycle), carbon dioxide is reduced to form organic sugar molecules.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1beaadf9-1730-4894-8777-ef7eead6f420', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'According to Ezekiel, the new covenant involves', null, '["sacrificing oxen","sprinkling clean water upon the people","washing the people with the blood of an animal","erecting an altar"]', 1, 'According to Ezekiel 36:25-27, the new covenant involves sprinkling clean water upon the people, giving them a new heart, and putting a new spirit within them. God said, ''I will sprinkle clean water upon you, and you shall be clean from all your uncleannesses.''', true, '2026-09-12 09:46:08.415', '2026-09-12 09:46:08.415', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1beffbd9-aa9a-42ad-b662-4b0b6758caa3', 'Literature in English', 'JAMB', null, 2026, null, 'When a story is told in a song and passed down by word of mouth, it is called', null, '["A sonnet","An epic","a ballad","A singer''s story"]', 2, 'It is a ballad.', true, '2026-09-12 11:10:55.758', '2026-09-12 11:10:55.758', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1c04ecad-7f2d-49a4-9c54-1c89c0fa1dbe', 'Biology', 'JAMB', null, 2026, null, 'A mammal with red fur and long ears was crossed with another having white fur and short ears. If the offspring had red fur and short ears, the', null, '["characters are linked","characters are not linked","parents are not related","parents are related"]', 0, 'The offspring inherited red fur from one parent and short ears from the other, suggesting these traits are linked on the same chromosome. If genes are linked, they are inherited together because they are located close to each other on the same chromosome, reducing the chance of crossing over. The fact that the specific combinations (red fur with short ears, and likely white fur with long ears) appear together indicates linkage rather than independent assortment.', true, '2026-09-09 03:18:16.318', '2026-09-09 03:18:16.318', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1c13cc04-300d-4b6b-95a4-22e4012e398d', 'English Language', 'JAMB', null, 2024, null, 'The number of hours spent ______ too much. (I) Is (II) are (III) Were (IV) Was', null, '["I&III","I","II","IV"]', 1, '"The number of" takes a singular verb, so "is" is correct.', true, '2026-09-18 09:43:02.308', '2026-09-18 09:43:02.308', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1c183cde-381a-4799-a8ea-bd9f5cbc60c1', 'Biology', 'JAMB', null, 2005, null, 'The blackfly is a vector of', null, '["malaria","trypanosomiasis","onchocerciasis","yellow fever"]', 2, 'Blackflies transmit onchocerciasis.', true, '2026-10-12 20:59:37.021', '2026-10-12 20:59:37.021', null, null, null, 'The blackfly is a vector of', '["malaria","trypanosomiasis","onchocerciasis","yellow fever"]', 'Blackflies transmit onchocerciasis.', '{"bold":["onchocerciasis"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1c26744f-9e92-4fec-9cce-6d6db678501c', 'Hausa', 'JAMB', null, 2011, null, 'An tsara Kukan Kurciya na M. B. Bambale', null, '["fitowa-fitowa da shiga-shiga","kashi-kashi da fitowa-fitowa","rabo-rabo da kashi-kashi","shiga-shiga da rabo-rabo."]', 1, 'An tsara Kukan Kurciya da kashi-kashi da fitowa-fitowa.', true, '2026-10-13 10:37:23.072', '2026-10-13 10:37:23.072', null, null, null, 'An tsara Kukan Kurciya na M. B. Bambale', '["fitowa-fitowa da shiga-shiga","kashi-kashi da fitowa-fitowa","rabo-rabo da kashi-kashi","shiga-shiga da rabo-rabo."]', 'An tsara Kukan Kurciya da kashi-kashi da fitowa-fitowa.', '{"bold":["kashi-kashi da fitowa-fitowa"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1c2ddf71-4270-46c1-8751-cad3900e27cc', 'Hausa', 'JAMB', null, 2011, null, 'Mece ce dangantakar Gizo da Koƙi a tatsuniyoyin Hausa?', null, '["Wa da kanwa.","Ubangida da baranya.","Uba da ''ya.","Miji da mata."]', 3, 'Gizo da Koƙi miji da mata ne a tatsuniyoyin Hausa.', true, '2026-10-13 10:37:22.101', '2026-10-13 10:37:22.101', null, null, null, 'Mece ce dangantakar Gizo da Koƙi a tatsuniyoyin Hausa?', '["Wa da kanwa.","Ubangida da baranya.","Uba da ''ya.","Miji da mata."]', 'Gizo da Koƙi miji da mata ne a tatsuniyoyin Hausa.', '{"bold":["miji da mata"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1c353e01-65db-4e3f-8415-5fa416ac4224', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). He has been advised to <u>keep his head</u>, the confusion notwithstanding.', null, '["avoid being beaten or insulted","keep calm","save his head","prevent being beheaded"]', 1, '''Keep his head'' = stay calm.', true, '2026-10-24 01:04:17.661', '2026-10-24 01:04:17.661', null, null, null, '(Choose the most appropriate interpretation). He has been advised to <u>keep his head</u>, the confusion notwithstanding.', '["avoid being beaten or insulted","<u>keep calm</u>","save his head","prevent being beheaded"]', '''<b>Keep his head</b>'' = <b>stay calm</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1c457125-a90c-4854-9c27-cf1e28035b4d', 'Biology', 'JAMB', null, 2026, null, 'Arrange the following structures from the external to the internal environment: I. Nostrils II. Larynx III. Bronchi IV. Pharynx V. Trachea VI. Bronchioles', null, '["I-II-IV-V-III-VI","I-IV-II-V-III-VI","I-II-V-IV-III-VI","I-V-II-IV-III-VI"]', 1, 'The correct sequence from external to internal in the human respiratory system is: Nostrils (I) → Pharynx (IV) → Larynx (II) → Trachea (V) → Bronchi (III) → Bronchioles (VI). Air enters through the nostrils, passes through the pharynx (throat), through the larynx (voice box), down the trachea (windpipe), which divides into the bronchi, and then into smaller bronchioles within the lungs. This is the pathway of air from the external environment to the internal respiratory surfaces where gas exchange occurs.', true, '2026-09-09 03:18:30.915', '2026-09-09 03:18:30.915', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1c4a677f-934a-4f9b-a0ec-907ce8a54a0a', 'Physics', 'JAMB', null, 1993, null, 'A metal rod 800 mm long is heated from 10 °C to 95 °C. If it expands by 1.36 mm, the linear expansivity of the metal is', null, '["2.0 x 10² K⁻¹","2.0 x 10⁻² K⁻¹","5.0 x 10⁻² K⁻¹","2.0 x 10⁻⁵ K⁻¹"]', 3, 'α = ΔL/(L Δθ) = 1.36/(800 x 85) = 2.0 x 10⁻⁵ K⁻¹.', true, '2026-10-12 19:15:37.489', '2026-10-12 19:15:37.489', null, null, null, 'A metal rod 800 mm long is heated from 10 °C to 95 °C. If it expands by 1.36 mm, the linear expansivity of the metal is', '["2.0 x 10<sup>2</sup> K<sup>-1</sup>","2.0 x 10<sup>-2</sup> K<sup>-1</sup>","5.0 x 10<sup>-2</sup> K<sup>-1</sup>","2.0 x 10<sup>-5</sup> K<sup>-1</sup>"]', 'α = ΔL/(L Δθ) = 1.36/(800 x 85) = 2.0 x 10<sup>-5</sup> K<sup>-1</sup>.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1c537c51-d7cb-4813-9676-0ef85fcd4c51', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). In their desire to impress their friends and relatives, many young workers <u>bite off more than they can chew</u> in terms of financial obligations.', null, '["have more money than sense","eat more than they can digest properly","spend too much money on food","care too much for their relatives","take on more responsibility than they can afford"]', 4, '''Bite off more than you can chew'' = take on too much.', true, '2026-10-24 01:04:15.083', '2026-10-24 01:04:15.083', null, null, null, '(Choose the most appropriate interpretation). In their desire to impress their friends and relatives, many young workers <u>bite off more than they can chew</u> in terms of financial obligations.', '["have more money than sense","eat more than they can digest properly","spend too much money on food","care too much for their relatives","<u>take on more responsibility than they can afford</u>"]', '''<b>Bite off more than you can chew</b>'' = <b>take on too much</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1c5ed7b5-7662-45d5-93f3-3d327b04187c', 'Biology', 'JAMB', null, 2026, null, 'A hormone produced in the adrenal medulla is', null, '["cortisol","norepinephrine","aldosterone","glucagon"]', 1, 'Norepinephrine (noradrenaline) is a hormone produced in the adrenal medulla. The adrenal medulla produces catecholamines: adrenaline (epinephrine) and noradrenaline (norepinephrine). Cortisol and aldosterone are produced by the adrenal cortex. Glucagon is produced by the alpha cells of the pancreas. The adrenal medulla is part of the sympathetic nervous system and produces hormones that prepare the body for ''fight or flight'' responses.', true, '2026-09-09 03:19:24.105', '2026-09-09 03:19:24.105', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1c5f1c55-a7a9-4cf9-b2ca-8908347a526c', 'Government', 'JAMB', null, 2026, null, 'The first law-making body in Nigeria after amalgamation was', null, '["Nigeria Council","National Assembly","Legislative Council","Regional"]', 2, 'The first law-making body in Nigeria after amalgamation was the Legislative Council. After the amalgamation of Northern and Southern Protectorates in 1914 by Lord Lugard, a Legislative Council was established for the Colony and Southern Protectorate. The Governor was the President of the Council. The Legislative Council had both official and unofficial members. It made laws for the Colony and Southern Protectorate, while the Governor legislated for the North by proclamation.', true, '2026-09-10 10:44:19.093', '2026-09-10 10:44:19.093', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1c629756-f4ae-49e1-9cb2-8d45a77e3196', 'Economics', 'JAMB', null, 2026, null, 'The factor of production that has the highest degree of mobility is', null, '["Land","Capital","Entrepreneur","Labour"]', 3, 'Labour is the most mobile factor of production, as workers can move between jobs and locations.', true, '2026-09-12 10:58:50.876', '2026-09-12 10:58:50.876', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1c64042a-97e1-4675-adef-787e0f7a1989', 'Literature in English', 'JAMB', null, 2026, null, 'Which of the following poetic devices is mostly used to praise the subject of the poem?', null, '["imagery","alliteration","hyperbole","apostrophe"]', 2, 'Hyperbole is mostly used to praise the subject.', true, '2026-09-12 11:12:10.419', '2026-09-12 11:12:10.419', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1c65d658-a3ff-4771-b673-b1940723e773', 'Physics', 'JAMB', null, 1985, null, 'Which of the following statements about electrolysis is NOT correct?', null, '["The substances in solution in the electrolyte become ionized.","Ions are electrically charged and are attracted towards electrodes when a potential difference is applied.","Ions may be discharged at the electrodes, forming bubbles or deposits.","The mass deposited depends upon the length of time for which current flows.","The mass of gas set free or metal deposited is proportional to the square of the current."]', 4, 'By Faraday''s first law, the mass deposited is proportional to the current (and time), not to the square of the current.', true, '2026-10-12 19:15:22.502', '2026-10-12 19:15:22.502', null, null, null, 'Which of the following statements about electrolysis is <b>NOT</b> correct?', '["The substances in solution in the electrolyte become ionized.","Ions are electrically charged and are attracted towards electrodes when a potential difference is applied.","Ions may be discharged at the electrodes, forming bubbles or deposits.","The mass deposited depends upon the length of time for which current flows.","The mass of gas set free or metal deposited is proportional to the square of the current."]', 'By Faraday''s first law, the mass deposited is proportional to the current (and time), not to the square of the current.', '{"bold":["NOT"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1c6cd845-6c11-443c-b0dd-fc5bea647a5a', 'Literature in English', 'JAMB', null, 2026, null, '''These naked sons of misery''. This expression is an example of', null, '["Litotes","Paradox","Assonance","metaphor"]', 3, 'The expression is a metaphor.', true, '2026-09-12 11:13:51.222', '2026-09-12 11:13:51.222', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1c6e0c21-7e22-438a-84c1-5a203248736b', 'Physics', 'JAMB', null, 1984, null, 'The distance travelled by a particle starting from rest is plotted against the square of the time elapsed from the commencement of motion. The resulting graph is linear. The slope of this graph is a measure of', null, '["Initial displacement","Initial velocity","Acceleration","Half the acceleration","Half the initial velocity"]', 3, 'From rest, s = ½at². Plotting s against t² gives a straight line whose slope is a/2, i.e. half the acceleration.', true, '2026-10-12 19:15:18.368', '2026-10-12 19:15:18.368', null, null, null, 'The distance travelled by a particle starting from rest is plotted against the square of the time elapsed from the commencement of motion. The resulting graph is linear. The slope of this graph is a measure of', '["Initial displacement","Initial velocity","Acceleration","Half the acceleration","Half the initial velocity"]', 'From rest, s = ½at<sup>2</sup>. Plotting s against t<sup>2</sup> gives a straight line whose slope is a/2, i.e. half the acceleration.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1c71ab3b-01e9-41ec-9d6d-df46fe8ede35', 'Literature in English', 'JAMB', null, 2026, null, 'Which of the following gives additional information in a play?', null, '["producer","clown","chorus","director"]', 2, 'The chorus gives additional information.', true, '2026-09-12 11:11:04.747', '2026-09-12 11:11:04.747', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1c7b35a9-399f-487c-8a59-ac613a64a53d', 'Economics', 'JAMB', null, 2026, null, 'Given that the cash reserve ratio is 10%, what is the maximum amount of money the banking system can create from an initial deposit of #100.00?', null, '["#100.00","#1000.00","#9,000.00","#10,000.00"]', 1, 'The maximum amount of money the banking system can create from an initial deposit of #100.00 with a 10% cash reserve ratio is #1000.00. The money multiplier = 1 / Cash Reserve Ratio = 1 / 0.10 = 10. Total money creation = Initial Deposit × Money Multiplier = 100 × 10 = #1000.00. This is the maximum amount of demand deposits that can be created from the initial deposit.', true, '2026-09-10 10:42:55.934', '2026-09-10 10:42:55.934', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1c9a982b-348a-4d8e-a1ef-c8008a9dc9aa', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). The thought of his admission to the University <u>keyed Olu up</u> to a state of great excitement. This means the thought ______________', null, '["stimulated Olu","ushered Olu","opened Olu","frightened Olu","allowed Olu"]', 0, '''Keyed up'' means stimulated.', true, '2026-10-24 01:02:01.045', '2026-10-24 01:02:01.045', null, null, null, '(Choose the most appropriate interpretation). The thought of his admission to the University <u>keyed Olu up</u> to a state of great excitement. This means the thought ______________', '["<u>stimulated Olu</u>","ushered Olu","opened Olu","frightened Olu","allowed Olu"]', '''<b>Keyed up</b>'' means <b>stimulated</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1cc73881-47e8-4f25-aa7b-5ca631336f6c', 'Financial Accounting', 'UTME', null, 2001, null, 'If a partner pays a premium of N500 for 1/5 share of profit, then the total value of goodwill is', null, '["N 500","N 2,000","N 2,500","N 3,000"]', 2, 'Goodwill = Premium / Share = 500 / (1/5) = 2,500.', true, '2026-10-12 22:00:07.141', '2026-10-12 22:00:07.141', null, null, null, 'If a partner pays a premium of N500 for 1/5 share of profit, then the total value of goodwill is', '["N 500","N 2,000","<b>N 2,500</b>","N 3,000"]', 'Goodwill = Premium / Share = 500 / (1/5) = <b>2,500</b>.', '{"bold":["2,500"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1cdbc88e-9ac3-44ca-a8c0-909cd329ffc1', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Ojo <u>used to play</u> tennis every day.', null, '["is familiar with playing","has to play","was in the habit of playing","was made to play"]', 2, 'Used to = was in the habit of.', true, '2026-10-24 01:01:47.536', '2026-10-24 01:01:47.536', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Ojo <u>used to play</u> tennis every day.', '["is familiar with playing","has to play","<u>was in the habit of playing</u>","was made to play"]', '<b>Used to</b> = <b>was in the habit of</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1cf983a8-b350-458f-b475-6564dc962075', 'English Language', 'JAMB', null, 2007, null, 'He did not attend the final burial <u>__________</u>', null, '["rite","rights","rites","right"]', 2, 'Correct form: rites (burial rites).', true, '2026-10-24 07:21:32.491', '2026-10-24 07:21:32.491', null, null, null, 'He did not attend the final burial <u>__________</u>', '["rite","rights","rites","right"]', 'Correct form: rites (burial rites).', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1d072ffa-b562-4dc1-9142-ecc2ae5597c5', 'Literature in English', 'JAMB', null, 2026, null, 'Literature is best described as a', null, '["Complication of folktales","Record of past norms","Totality of man''s life experience","Story of great men and women"]', 2, 'Literature is the totality of man''s life experience.', true, '2026-09-12 11:13:59.014', '2026-09-12 11:13:59.014', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1d0f224f-0f29-4164-9be8-69fcbcaf7750', 'Literature in English', 'JAMB', null, 2026, null, 'When a story is told in a song and passed down by word of mouth, it is called', null, '["A sonnet","An epic","a ballad","A singer''s story"]', 2, 'It is a ballad.', true, '2026-09-12 11:07:30.516', '2026-09-12 11:07:30.516', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1d17e110-1b99-4f89-b8bf-046a3478f883', 'Financial Accounting', 'UTME', null, 2004, null, 'If the assets and liabilities of a firm were valued at N17 200 and N5 120 respectively, the capital of the firm would be', null, '["N22 320","N17 200","N12 080","N5 120"]', 2, 'Capital = Asset - Liabilities = 17200 - 5120 = 12080.', true, '2026-10-12 22:00:02.738', '2026-10-12 22:00:02.738', null, null, null, 'If the assets and liabilities of a firm were valued at N17 200 and N5 120 respectively, the capital of the firm would be', '["N22 320","N17 200","<b>N12 080</b>","N5 120"]', 'Capital = Asset - Liabilities = 17200 - 5120 = <b>12080</b>.', '{"bold":["12080"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1d23b164-0a88-4813-8e59-ec29820ac29d', 'General Mathematics', 'JAMB', null, 2026, null, 'Find the midpoint of the line PQ is (2,3) and the point P is (-2,1). Find the coordinate of the point Q.', null, '["(0,4)","(6,5)","(8,6)","(5,6)"]', 1, 'Midpoint = ((x₁+x₂)/2, (y₁+y₂)/2) = (2,3). (-2+x₂)/2 = 2, so -2+x₂ = 4, x₂ = 6. (1+y₂)/2 = 3, so 1+y₂ = 6, y₂ = 5. So Q = (6,5).', true, '2026-09-10 10:48:20.08', '2026-09-10 10:48:20.08', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1d24fe7d-3fbd-45a7-aa37-3f23a65728ac', 'Physics', 'JAMB', null, 1992, null, 'A platinum resistance thermometer wire has a resistance of 5 ohms at 0 °C and 5.5 ohms at 100 °C. Calculate the temperature of the wire when the resistance is 5.2 ohms.', null, '["80 °C","60 °C","40 °C","10 °C"]', 2, 'θ = (5.2 - 5.0)/(5.5 - 5.0) x 100 = 0.2/0.5 x 100 = 40 °C.', true, '2026-10-12 19:15:35.23', '2026-10-12 19:15:35.23', null, null, null, 'A platinum resistance thermometer wire has a resistance of 5 ohms at 0 °C and 5.5 ohms at 100 °C. Calculate the temperature of the wire when the resistance is 5.2 ohms.', '["80 °C","60 °C","40 °C","10 °C"]', 'θ = (5.2 - 5.0)/(5.5 - 5.0) x 100 = 0.2/0.5 x 100 = 40 °C.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1d2934eb-d8c9-4363-9771-0a25dd3f1aac', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The director''s remark was extremely <u>apposite</u> to the issue being discussed.', null, '["inconsequential","emphatic","adequate","appropriate"]', 3, 'Apposite = appropriate.', true, '2026-10-24 01:01:54.75', '2026-10-24 01:01:54.75', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The director''s remark was extremely <u>apposite</u> to the issue being discussed.', '["inconsequential","emphatic","adequate","<u>appropriate</u>"]', '<b>Apposite</b> = <b>appropriate</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1d2e8483-5bb4-433e-be3b-91d46760a5c3', 'Physics', 'JAMB', null, 1999, null, 'If the stress on a wire is 10⁷ N m⁻² and the wire is stretched from its original length of 10.00 cm to 10.05 cm, the Young''s modulus of the wire is', null, '["5.0 x 10⁴ N m⁻²","5.0 x 10⁵ N m⁻²","2.0 x 10⁸ N m⁻²","2.0 x 10⁹ N m⁻²"]', 3, 'Strain = 0.05/10.00 = 0.005. E = stress/strain = 10⁷/0.005 = 2.0 x 10⁹ N m⁻².', true, '2026-10-12 19:15:47.394', '2026-10-12 19:15:47.394', null, null, null, 'If the stress on a wire is 10<sup>7</sup> N m<sup>-2</sup> and the wire is stretched from its original length of 10.00 cm to 10.05 cm, the Young''s modulus of the wire is', '["5.0 x 10<sup>4</sup> N m<sup>-2</sup>","5.0 x 10<sup>5</sup> N m<sup>-2</sup>","2.0 x 10<sup>8</sup> N m<sup>-2</sup>","2.0 x 10<sup>9</sup> N m<sup>-2</sup>"]', 'Strain = 0.05/10.00 = 0.005. E = stress/strain = 10<sup>7</sup>/0.005 = 2.0 x 10<sup>9</sup> N m<sup>-2</sup>.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1d2f86a3-c491-49f1-9498-21ccbb7f98f0', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). In answer to the question as to how life is treating him, the stranger said <u>''it never rains but it pours''</u>.', null, '["the blessings of life shower on him like fortunes","he is contented with his improved fortunes","things are getting decidedly worse","his financial status is deteriorating"]', 2, '''It never rains but it pours'' = troubles come all at once.', true, '2026-10-24 01:04:21.685', '2026-10-24 01:04:21.685', null, null, null, '(Choose the most appropriate interpretation). In answer to the question as to how life is treating him, the stranger said <u>''it never rains but it pours''</u>.', '["the blessings of life shower on him like fortunes","he is contented with his improved fortunes","<u>things are getting decidedly worse</u>","his financial status is deteriorating"]', '''<b>It never rains but it pours</b>'' = <b>troubles come all at once</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1d4fac11-6704-40db-8d3c-9e003a1eda38', 'Biology', 'JAMB', null, 2026, null, 'When the ciliary muscle of the eye contracts, the eye lens', null, '["bulges","contracts","rotates","flattens"]', 0, 'When the ciliary muscle contracts, the eye lens bulges (becomes more convex). Contraction of the ciliary muscle releases tension on the suspensory ligaments (zonules), allowing the elastic lens to become rounder and more curved. This increases the refractive power of the lens, enabling near vision (accommodation for close objects). When the ciliary muscle relaxes, the lens becomes flatter for distance vision. This accommodation process is controlled by the parasympathetic nervous system and is essential for focusing on objects at different distances. With age, the lens becomes less elastic, causing presbyopia.', true, '2026-09-09 03:18:55.907', '2026-09-09 03:18:55.907', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1d57af0c-e62b-4e06-a681-a4209071a3f7', 'Physics', 'JAMB', null, 1997, null, 'If 8 x 10⁻² J of work is required to move 100 μC of charge from a point X to a point Y in an electrical circuit, the potential difference between X and Y is', null, '["4.0 x 10² V","4.0 x 10⁴ V","8.0 x 10² V","8.0 x 10⁴ V"]', 2, 'V = W/Q = (8 x 10⁻²)/(100 x 10⁻⁶) = 8.0 x 10² V.', true, '2026-10-12 19:15:44.174', '2026-10-12 19:15:44.174', null, null, null, 'If 8 x 10<sup>-2</sup> J of work is required to move 100 μC of charge from a point X to a point Y in an electrical circuit, the potential difference between X and Y is', '["4.0 x 10<sup>2</sup> V","4.0 x 10<sup>4</sup> V","8.0 x 10<sup>2</sup> V","8.0 x 10<sup>4</sup> V"]', 'V = W/Q = (8 x 10<sup>-2</sup>)/(100 x 10<sup>-6</sup>) = 8.0 x 10<sup>2</sup> V.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1d5a954c-aaad-4fdf-aa7e-21e461bd0a8e', 'Physics', 'JAMB', null, 2001, null, 'A plane sound wave of frequency 85.5 Hz and velocity 342 m s⁻¹ is reflected from a vertical wall. At what distance from the wall does the wave have an antinode?', null, '["2 m","4 m","1 m","3 m"]', 2, 'λ = 342/85.5 = 4 m. The wall is a displacement node, and the first antinode is λ/4 = 1 m from it.', true, '2026-10-12 19:15:51.415', '2026-10-12 19:15:51.415', null, null, null, 'A plane sound wave of frequency 85.5 Hz and velocity 342 m s<sup>-1</sup> is reflected from a vertical wall. At what distance from the wall does the wave have an antinode?', '["2 m","4 m","1 m","3 m"]', 'λ = 342/85.5 = 4 m. The wall is a displacement node, and the first antinode is λ/4 = 1 m from it.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1d5b2197-1b6d-4d8c-bc0d-0bf8a0ebd307', 'General Mathematics', 'JAMB', null, 2026, null, 'Father reduced the quantity of food bought for the family by 10% when he found that the cost of living had increased by 15%. Thus the fractional increase in the family food bill is now', null, '["1/12","6/35","19/300","7/200","5/100"]', 0, 'New cost = 0.9 × 1.15 = 1.035. Increase = 0.035 = 7/200. The answer is (D) 7/200.', true, '2026-09-12 11:44:20.886', '2026-09-12 11:44:20.886', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1d6254ac-8e48-4fe0-8a5b-a94bb59037a6', 'Physics', 'JAMB', null, 1983, null, 'It is usual to transmit electric power at high voltage and low current. Which of the following are possible advantages of the method?
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1d6bb6e6-11a6-41b4-8148-75a4a9791e18', 'Biology', 'JAMB', null, 2026, null, 'Which of the following insects undergoes incomplete metamorphosis?', null, '["housefly","termite","mosquito","moth"]', 1, 'Termites undergo incomplete metamorphosis (hemimetabolism), where the life cycle consists of three stages: egg → nymph → adult. The nymph resembles a miniature adult (without wings) and gradually develops into the adult form through successive molts. Houseflies, mosquitoes, and moths all undergo complete metamorphosis (holometabolism) with four stages: egg → larva → pupa → adult, where the larval form is completely different from the adult. Termites are social insects and the nymphs are similar to adults in appearance.', true, '2026-09-09 03:18:18.107', '2026-09-09 03:18:18.107', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1d80473c-c196-4682-afb9-55f82be235e1', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'The raising of Lazarus from the dead made people to', null, '["persecute Jesus","convert to Christianity","believe that Jesus is the Messiah","become disciples of Jesus"]', 2, 'Many believed in Jesus after Lazarus was raised.', true, '2026-09-12 10:42:13.709', '2026-09-12 10:42:13.709', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1d84bab1-4c1d-4d43-818c-6963e29bcb90', 'Biology', 'JAMB', null, 2026, null, 'The sons of a colour blind woman will be colour blind regardless of the state of the father because', null, '["the egg determines the phenotype of the son","sons inherit the sex chromosomes of their mother","the father''s sex chromosome is weaker in sons","sex linked traits express dominance in females"]', 1, 'Sons of a colour blind woman will be colour blind regardless of the father''s state because sons inherit the sex chromosomes of their mother. The mother provides the X chromosome to her sons (the father provides the Y chromosome). If the mother is colour blind (X^n X^n), all her X chromosomes carry the recessive allele. Therefore, all sons will inherit X^n and be colour blind (X^n Y). The father''s condition does not affect the son''s color vision.', true, '2026-09-09 03:19:30.318', '2026-09-09 03:19:30.318', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1d86d2ca-9a21-4e6f-8bb0-9e53f5a29f07', 'Physics', 'JAMB', null, 1991, null, 'Two tuning forks of frequencies 256 Hz and 260 Hz are sounded close to each other. What is the frequency of the beats produced?', null, '["2 Hz","4 Hz","8 Hz","258 Hz"]', 1, 'Beat frequency = 260 - 256 = 4 Hz.', true, '2026-10-12 19:15:33.785', '2026-10-12 19:15:33.785', null, null, null, 'Two tuning forks of frequencies 256 Hz and 260 Hz are sounded close to each other. What is the frequency of the beats produced?', '["2 Hz","4 Hz","8 Hz","258 Hz"]', 'Beat frequency = 260 - 256 = 4 Hz.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1d870d02-a1a5-4b70-a3f1-d236eac8e5ae', 'Literature in English', 'JAMB', null, 2026, null, 'The poem criticizes the younger generation mainly for', null, '["embracing fashion trends","building modern houses","abandoning tradition and heritage","refusing to travel abroad"]', 2, 'The poem criticizes abandoning tradition and heritage.', true, '2026-09-12 11:07:20.789', '2026-09-12 11:07:20.789', null, null, null, null, null, null, null);
