insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1d9658b6-c43f-4ec9-ace7-445b1cc00343', 'Economics', 'JAMB', null, 2026, null, 'Which of the following is NOT a function of money?', null, '["Medium of exchange","Measure of value","Store of value","Increase in labour productivity"]', 3, 'Increasing labour productivity is not a function of money.', true, '2026-09-12 10:59:54.283', '2026-09-12 10:59:54.283', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1d96e52e-88d5-4e96-a14b-9e311c7f3803', 'Biology', 'JAMB', null, 2011, null, 'An example of an endospermous seed is', null, '["maize grain","cashew nut","cotton seed","bean seed."]', 0, 'Maize grain is an endospermous seed.', true, '2026-10-12 20:59:42.254', '2026-10-12 20:59:42.254', null, null, null, 'An example of an endospermous seed is', '["maize grain","cashew nut","cotton seed","bean seed."]', 'Maize grain is an endospermous seed.', '{"bold":["Maize grain"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1d98ff0b-012b-42b6-a753-874c16c5e97d', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'A call of Abraham is important to Christianity because it led to the', null, '["blessing of mankind","institution of God''s call to service","redemption of the human race","institution of covenants"]', 0, 'The call of Abraham is important to Christianity because it led to the blessing of mankind. God promised Abraham, ''In you all the families of the earth shall be blessed.'' This was fulfilled in Jesus Christ, through whom salvation came to all nations.', true, '2026-09-12 09:45:58.143', '2026-09-12 09:45:58.143', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1dbb81a9-336c-4658-b5e8-71f6095bf04f', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Many would argue that the achievement <u>commensurate with</u> the effort.', null, '["unexpected in the light of","funny compared with","proportional to","the wrong excuse for"]', 2, 'Commensurate with = proportional to.', true, '2026-10-24 01:01:47.43', '2026-10-24 01:01:47.43', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Many would argue that the achievement <u>commensurate with</u> the effort.', '["unexpected in the light of","funny compared with","<u>proportional to</u>","the wrong excuse for"]', '<b>Commensurate with</b> = <b>proportional to</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1dc50836-75be-4973-8226-5b693c4fd855', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Hypertension is a <u>debilitating</u> disease that everyone should prevent.', null, '["a mortal","an enervating","an energizing","a horrible"]', 2, 'Debilitating = weakening; opposite = energizing.', true, '2026-10-24 07:21:22.053', '2026-10-24 07:21:22.053', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Hypertension is a <u>debilitating</u> disease that everyone should prevent.', '["a mortal","an enervating","an energizing","a horrible"]', 'Debilitating = weakening; opposite = energizing.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1dcc9960-adb3-4cb3-a8d1-0a3920935116', 'Physics', 'JAMB', null, 1995, null, 'An electric current of 2 amperes flows in a heating coil of resistance 50 ohms for 3 minutes 20 seconds. Determine the heat produced.', null, '["0.5 kJ","8.0 kJ","20.0 kJ","40.0 kJ"]', 3, 'H = I²Rt = 2² x 50 x 200 = 40 000 J = 40.0 kJ.', true, '2026-10-12 19:15:42.272', '2026-10-12 19:15:42.272', null, null, null, 'An electric current of 2 amperes flows in a heating coil of resistance 50 ohms for 3 minutes 20 seconds. Determine the heat produced.', '["0.5 kJ","8.0 kJ","20.0 kJ","40.0 kJ"]', 'H = I<sup>2</sup>Rt = 2<sup>2</sup> x 50 x 200 = 40 000 J = 40.0 kJ.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1dd6e52c-2cc5-45cc-a20f-85eda0522e3c', 'Literature in English', 'JAMB', null, 2026, null, 'The poem employs repetition mainly to', null, '["create humour","emphasize apathy and complicity","beautify language","confuse the reader"]', 1, 'Repetition emphasizes apathy and complicity.', true, '2026-09-12 11:14:11.333', '2026-09-12 11:14:11.333', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1dd7237e-d13b-4cec-98a2-5fa6d0112e10', 'Chemistry', 'JAMB', null, 2026, null, 'Which of the following is unsaturated?', null, '["Ethane","Propane","Ethene","Methane"]', 2, 'Ethene is unsaturated (contains a double bond).', true, '2026-09-12 11:35:59.155', '2026-09-12 11:35:59.155', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1dd992ce-05df-4768-a91d-0267993ad28e', 'Physics', 'JAMB', null, 1987, null, 'If a beaker is filled with water, it is observed that the surface of the water is not horizontal at the glass-water interface. This behaviour is due to', null, '["Friction","Viscosity","Surface tension","Evaporation."]', 2, 'Adhesion between water and glass pulls the water up the wall (meniscus). This curved surface is a surface tension effect.', true, '2026-10-12 19:15:24.985', '2026-10-12 19:15:24.985', null, null, null, 'If a beaker is filled with water, it is observed that the surface of the water is not horizontal at the glass-water interface. This behaviour is due to', '["Friction","Viscosity","Surface tension","Evaporation."]', 'Adhesion between water and glass pulls the water up the wall (meniscus). This curved surface is a surface tension effect.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1de6031a-7f8e-4964-af43-72162bf1013e', 'Biology', 'JAMB', null, 2010, null, 'When a mixture of a food substance and Benedict''s solution was warmed, the solution changed from blue to brick-red. This indicates the presence of', null, '["reducing sugar","fatty acid","sucrose","amino acid"]', 0, 'Benedict''s solution changing to brick-red indicates reducing sugar.', true, '2026-10-12 20:59:39.487', '2026-10-12 20:59:39.487', null, null, null, 'When a mixture of a food substance and Benedict''s solution was warmed, the solution changed from blue to brick-red. This indicates the presence of', '["reducing sugar","fatty acid","sucrose","amino acid"]', 'Benedict''s solution changing to brick-red indicates reducing sugar.', '{"bold":["reducing sugar"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1dea9511-c8a6-4df8-961d-95eccf43202e', 'Economics', 'JAMB', null, 2026, null, 'The ultimate objective of economics is to', null, '["decide under what circumstances that government should intervene in the economy","Make the best use of scarce resources","make efforts to understand how the economy works","Organize production at the lowest cost"]', 1, 'The ultimate objective of economics is to make the best use of scarce resources to satisfy human wants.', true, '2026-09-12 10:58:50.519', '2026-09-12 10:58:50.519', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1deab7a7-2379-4cce-acd7-8eb83087691c', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). The presence of the security men in the area will provide <u>a moment of respite</u> to the residents.', null, '["soothing relaxation","enduring reprieve","lasting security","temporary relief"]', 3, '''A moment of respite'' = temporary relief.', true, '2026-10-24 01:04:22.652', '2026-10-24 01:04:22.652', null, null, null, '(Choose the most appropriate interpretation). The presence of the security men in the area will provide <u>a moment of respite</u> to the residents.', '["soothing relaxation","enduring reprieve","lasting security","<u>temporary relief</u>"]', '''A <b>moment of respite</b>'' = <b>temporary relief</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1df3c4ea-d8cb-4c44-adcf-bf631787f170', 'Biology', 'JAMB', null, 2026, null, 'A plant which grows in a soil that lacks nitrogen is likely to be', null, '["epiphytic","saprophytic","carnivorous","parasitic"]', 2, 'A plant that grows in soil lacking nitrogen is likely to be carnivorous (insectivorous). Carnivorous plants like sundews, pitcher plants, and Venus flytraps have adapted to nitrogen-poor soils by capturing and digesting insects to obtain nitrogen and other nutrients. Epiphytes grow on other plants but are not parasitic. Saprophytes obtain nutrients from dead organic matter. Parasites obtain nutrients from living hosts. Carnivorous plants use their modified leaves to trap prey, and the digestive enzymes break down the prey to release nutrients that are otherwise scarce.', true, '2026-09-09 03:18:51.07', '2026-09-09 03:18:51.07', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1e026886-30c0-4610-84ca-f0eb4663c190', 'Chemistry', 'JAMB', null, 2026, null, 'Calculate the volume of carbon (iv) oxide measured at stp produced when 1kg potassium hydrogen trioxocarbonate (IV) is totally decomposed by heat [GMV=22.4dm3, K=39, O=16, C=12, H=1]', null, '["28dm3","56dm3","112dm3","196dm3"]', 2, '2KHCO3 -> K2CO3 + H2O + CO2. Molar mass KHCO3 = 100g/mol. 1000g / (2 * 100g) = 5 moles of CO2. Volume = 5 * 22.4 dm3 = 112 dm3.', true, '2026-09-09 17:12:45.134', '2026-09-09 17:12:45.134', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1e12ff33-e276-4385-a045-6a0823225dec', 'English Language', 'JAMB', null, 2024, null, 'All of the following served as a relief to political crisis in Nigeria except', null, '["the death of General Sanni Abacha","the appointment of General Abdusalam Abubakar","the ''stepping aside'' of the military president, Ibrahim Babangida","the election of the new president"]', 2, 'The ''stepping aside'' of Ibrahim Babangida did not restore sanity, according to the passage.', true, '2026-09-18 09:24:04.926', '2026-09-18 09:24:04.926', null, null, 'COMPREHENSION', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1e155f94-1020-4af1-983e-845c4d3ff2aa', 'Government', 'JAMB', null, 2026, null, 'When a superior court declares an action of the executive ultra-vires, it means that', null, '["the executive should leave power","a vote of no confidence had been passed on the government","the judiciary is more powerful than the executive","the action Is illegal and of no effect"]', 3, 'Ultra vires means the action is illegal and of no effect.', true, '2026-09-12 11:24:32.91', '2026-09-12 11:24:32.91', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1e162275-5c30-4055-be90-86960c3a364b', 'Physics', 'JAMB', null, 2000, null, 'If the force and the velocity on a system are each reduced simultaneously by half, the power of the system is', null, '["Doubled","Constant","Reduced to a quarter","Reduced by half."]', 2, 'P = Fv. With F and v each halved, P becomes ½ x ½ = ¼ of the original.', true, '2026-10-12 19:15:49.267', '2026-10-12 19:15:49.267', null, null, null, 'If the force and the velocity on a system are each reduced simultaneously by half, the power of the system is', '["Doubled","Constant","Reduced to a quarter","Reduced by half."]', 'P = Fv. With F and v each halved, P becomes ½ x ½ = ¼ of the original.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1e1b0bc9-b959-4b37-aff1-f601317c58a8', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Men living in an <u>extended</u> family know that they have to be responsible for the welfare of some other person''s children.', null, '["extensive","nuclear","neutral","contracted"]', 1, 'Extended family; opposite = nuclear family.', true, '2026-10-24 07:21:13.159', '2026-10-24 07:21:13.159', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Men living in an <u>extended</u> family know that they have to be responsible for the welfare of some other person''s children.', '["extensive","nuclear","neutral","contracted"]', 'Extended family; opposite = nuclear family.', '{}');
