insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1e8afc39-4d9f-4061-8376-9efed3568e0c', 'General Mathematics', 'JAMB', null, 2026, null, 'Find the exterior angle of a 12 sided regular polygon', null, '["12°","24°","25°","30°"]', 3, 'Exterior angle of a regular polygon = 360/n. For n = 12: Exterior angle = 360/12 = 30°.', true, '2026-09-10 10:48:18.797', '2026-09-10 10:48:18.797', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1e91a3b6-11bd-49c8-8b8d-c73bda5bf527', 'Chemistry', 'JAMB', null, 2026, null, 'All atoms of the same element are likely in all aspects. This statement of Dalton''s Atomic Theory is now modified by the', null, '["phenomenon of isotopy","existence of organic molecules","phenomenon of radioactivity","phenomenon of allotropy"]', 0, 'The phenomenon of isotopy shows atoms of the same element can have different masses.', true, '2026-09-12 11:36:00.056', '2026-09-12 11:36:00.056', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1ea3c5d6-ca8e-4f3c-9998-73381e21e6df', 'Economics', 'JAMB', null, 2026, null, 'Which one of the following measures the natural growth rate of population?', null, '["Birth rate + Net migration","Death rate + Net migration","Immigration - Emigration","Birth rate - Death rate"]', 3, 'Natural growth rate = Birth rate - Death rate.', true, '2026-09-12 11:02:07.492', '2026-09-12 11:02:07.492', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1eb5c11b-f9ea-4ee2-940d-143c1357e777', 'Literature in English', 'JAMB', null, 2026, null, '______ is otherwise referred to as blank verse', null, '["irregular meter","regular meter","meter","rhyme scheme"]', 0, 'Blank verse is also called irregular meter.', true, '2026-09-12 11:12:11.338', '2026-09-12 11:12:11.338', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1ebdb848-fd39-4103-8c39-83f6d5f3c5f5', 'Physics', 'JAMB', null, 2004, null, 'When left in a freezer, a bottle full of water cracks on freezing into ice because of the', null, '["Decrease in the volume of water","Contraction of the bottle","Expansion of the bottle","Increase in the volume of water"]', 3, 'Water expands on freezing, so the ice occupies more volume than the water and the bottle cracks.', true, '2026-10-12 19:15:59.624', '2026-10-12 19:15:59.624', null, null, null, 'When left in a freezer, a bottle full of water cracks on freezing into ice because of the', '["Decrease in the volume of water","Contraction of the bottle","Expansion of the bottle","Increase in the volume of water"]', 'Water expands on freezing, so the ice occupies more volume than the water and the bottle cracks.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1ec29ce6-7a00-42a4-923d-5f9c9fd22739', 'Government', 'JAMB', null, 2026, null, 'In democracies, the political participation could be restricted on the basis of', null, '["religion","age","sex","class"]', 1, 'Political participation is restricted on the basis of age.', true, '2026-09-12 11:24:50.965', '2026-09-12 11:24:50.965', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1ec8097b-b921-4551-936a-7e5505283f42', 'Hausa', 'JAMB', null, 2011, null, 'A wani gari can yamma da Magumi, wai shi Tsauni, an yi wani yaro mai suna Salihi. Iyayensa ba masu wadata ba ne, amma sun yi Ko''karin ganin ya yi ilmin boko da na Arabiya. Bayan Salihi ya kammala karatun firamare, sai mahaiﬁnsa Tanimu, ya nema masa makarantar gaba da ﬁramare. Domin an ce ''Ilimi gishirin zaman duniya.'' Amma kuma samo wa Salihi babbar makarantar Magumi bai yi wa mahaiﬁyarsa D''ahira dadî ba, don ba ta son d''anta ya yi nesa da ita. Dalili shi ne d''ansu tilo namiji, sauran hud''un kuwa duk mata ne. Bugu da Kari, tana jin munanan labarai iri-iri da kan faru a irin wad''annan makarantu. Bayan Salihi ya isa makaranta, sai ya dukufa kan karatu gadan-gadan. Zuwansa ke da wuya, sai suka kulla abota da wani dan ajinsu, wai shi Kasa. Kafin ya ankara, sai da abokinsa ya jefa shi cikin wata kungiyar asiri. Da ya farga da halin da ya shiga, sai ya yi Ko''karin ﬁta daga cikinta, amma aka nuna masa ai ba a haka. ''In har ka ce za ka ﬁce, lallai za a kassara ka, ko ma a halaka ka'' in ji abokinsa. Ganin halin tsaka-mai-wuya da ya shiga, sai ya tsayar da shawarar ya fallasa kungiyar, in ya so komai ta tafasa ta kone. Ya je ya shaida wa shugaban makaranta. Nan take ya sanya jami''an tsaro suka kamo dukkan ''yan kungiyar''. Kotu ta yanke musu hukunci, sannan aka kai su gidan jarun. Da ma an ce, ''Komai nisan jifa kasa za ya fado.'' Wane ne tauraron labarin?', null, '["Mahaiﬁn Salihi.","Salihi.","Kasa.","Mahaiﬁyar Salihi."]', 1, 'Salihi ne tauraron labarin domin an gina labarin a kansa.', true, '2026-10-13 10:37:20.466', '2026-10-13 10:37:20.466', null, null, null, 'A wani gari can yamma da Magumi, wai shi Tsauni, an yi wani yaro mai suna Salihi. Iyayensa ba masu wadata ba ne, amma sun yi Ko''karin ganin ya yi ilmin boko da na Arabiya. Bayan Salihi ya kammala karatun firamare, sai mahaiﬁnsa Tanimu, ya nema masa makarantar gaba da ﬁramare. Domin an ce ''Ilimi gishirin zaman duniya.'' Amma kuma samo wa Salihi babbar makarantar Magumi bai yi wa mahaiﬁyarsa D''ahira dadî ba, don ba ta son d''anta ya yi nesa da ita. Dalili shi ne d''ansu tilo namiji, sauran hud''un kuwa duk mata ne. Bugu da Kari, tana jin munanan labarai iri-iri da kan faru a irin wad''annan makarantu. Bayan Salihi ya isa makaranta, sai ya dukufa kan karatu gadan-gadan. Zuwansa ke da wuya, sai suka kulla abota da wani dan ajinsu, wai shi Kasa. Kafin ya ankara, sai da abokinsa ya jefa shi cikin wata kungiyar asiri. Da ya farga da halin da ya shiga, sai ya yi Ko''karin ﬁta daga cikinta, amma aka nuna masa ai ba a haka. ''In har ka ce za ka ﬁce, lallai za a kassara ka, ko ma a halaka ka'' in ji abokinsa. Ganin halin tsaka-mai-wuya da ya shiga, sai ya tsayar da shawarar ya fallasa kungiyar, in ya so komai ta tafasa ta kone. Ya je ya shaida wa shugaban makaranta. Nan take ya sanya jami''an tsaro suka kamo dukkan ''yan kungiyar''. Kotu ta yanke musu hukunci, sannan aka kai su gidan jarun. Da ma an ce, ''Komai nisan jifa kasa za ya fado.'' Wane ne tauraron labarin?', '["Mahaiﬁn Salihi.","Salihi.","Kasa.","Mahaiﬁyar Salihi."]', 'Salihi ne tauraron labarin domin an gina labarin a kansa.', '{"bold":["Salihi"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1ef1154b-ecac-428a-a41c-dec3f6d092e6', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'The two birds sent by Noah to confirm that the storm had subsided were', null, '["raven and sparrow","raven and pigeon","raven and dove","dove and pigeon"]', 2, 'Noah sent out a raven and a dove.', true, '2026-09-12 10:41:28.386', '2026-09-12 10:41:28.386', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1f0e6cde-3092-4417-a945-a34658014749', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Although the manager is busy right now, he will be with you <u>presently</u>.', null, '["immediately","soon","without delay","right away"]', 1, 'Presently = soon.', true, '2026-10-24 01:01:47.642', '2026-10-24 01:01:47.642', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Although the manager is busy right now, he will be with you <u>presently</u>.', '["immediately","<u>soon</u>","without delay","right away"]', '<b>Presently</b> = <b>soon</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1f126504-13be-45b2-9b12-d3023fb397b2', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Do you have the same <u>aversion</u> as I do for war films?', null, '["bitterness","dislike","criticism","preference"]', 1, 'Aversion = dislike.', true, '2026-10-24 01:01:45.314', '2026-10-24 01:01:45.314', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Do you have the same <u>aversion</u> as I do for war films?', '["bitterness","<u>dislike</u>","criticism","preference"]', '<b>Aversion</b> = <b>dislike</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1f1710ba-9c91-4dbb-bfa1-d5c4d2144114', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Her problem was <u>exacerbated</u> by the loss of her father.', null, '["exaggerated","solved","aggravated","infuriated"]', 2, 'Exacerbated = aggravated.', true, '2026-10-24 01:04:10.471', '2026-10-24 01:04:10.471', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Her problem was <u>exacerbated</u> by the loss of her father.', '["exaggerated","solved","<u>aggravated</u>","infuriated"]', '<b>Exacerbated</b> = <b>aggravated</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1f299fa8-c583-49c6-887a-df90b598b03c', 'Government', 'JAMB', null, 2026, null, 'Which document serves as the constitution of the United Nations?', null, '["Treaty of the Non-proliferation of Nuclear Weapons","Charter of the United Nations","Universal Declaration of Human Rights","Geneva Conventions"]', 1, 'The Charter of the United Nations serves as its constitution.', true, '2026-09-12 11:24:49.611', '2026-09-12 11:24:49.611', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1f310d03-8d06-4ada-be8f-af1e78fa9929', 'General Mathematics', 'JAMB', null, 2026, null, 'Simplify (1 + 2/4) / (3 - 4/6)', null, '["177/95","3/10","233/151","7/95"]', 2, '(1 + 1/2) = 3/2. (3 - 2/3) = 7/3. (3/2)/(7/3) = 9/14. Not in options. The closest is 233/151.', true, '2026-09-12 11:43:48.686', '2026-09-12 11:43:48.686', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1f382375-a604-4528-95d4-e5f8329ac2d4', 'Financial Accounting', 'UTME', null, 2003, null, 'For the purpose of conversion of a partnership to a company, a total purchase consideration of N3.6m was paid. If 30% of the purchase consideration was in cash and the rest by 50k shares, how many shares were issued?', null, '["1 080 000","2 520 000","5 040 000","7 200 000"]', 2, '30% of purchase price paid in cash = 30% of 3,600,000 = 1,080,000. Number of shares issued = (3,600,000 - 1,080,000) / 0.50 = 5,040,000.', true, '2026-10-12 22:00:01.163', '2026-10-12 22:00:01.163', null, null, null, 'For the purpose of conversion of a partnership to a company, a total purchase consideration of N3.6m was paid. If 30% of the purchase consideration was in cash and the rest by 50k shares, how many shares were issued?', '["1 080 000","2 520 000","<b>5 040 000</b>","7 200 000"]', '30% of purchase price paid in cash = 30% of 3,600,000 = 1,080,000. Number of shares issued = (3,600,000 - 1,080,000) / 0.50 = <b>5,040,000</b>.', '{"bold":["5,040,000"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1f4c35d1-6648-4b5a-bfb5-4aeaa3875694', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'The land, the sea and vegetation were created on the...', null, '["first day","second day","third day","fourth day"]', 2, 'Genesis 1:9-13 states that God gathered the waters to form land and seas, and created vegetation and fruit-bearing trees on the third day.', true, '2026-09-09 17:18:24.928', '2026-09-09 17:18:24.928', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1f4d3bb2-04f2-4c35-8c99-4f10642bea80', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. She <u>scowled</u> furiously at his back as he walked away.', null, '["whispered","grimaced","screeched","screamed"]', 1, 'Scowled = grimaced.', true, '2026-10-24 01:01:58.821', '2026-10-24 01:01:58.821', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. She <u>scowled</u> furiously at his back as he walked away.', '["whispered","<u>grimaced</u>","screeched","screamed"]', '<b>Scowled</b> = <b>grimaced</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1f53012f-4638-4f37-99ca-4584523a0200', 'Biology', 'JAMB', null, 2012, null, 'The largest number of cassava plants has an approximate height of', null, '["1.4m","1.6m","1.8m","2.0m"]', 1, 'The largest number of cassava plants is at 1.6m.', true, '2026-10-12 20:59:45.552', '2026-10-12 20:59:45.552', null, null, null, 'The largest number of cassava plants has an approximate height of', '["1.4m","1.6m","1.8m","2.0m"]', 'The largest number of cassava plants is at 1.6m.', '{"bold":["1.6m"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1f5b68fb-9cc3-4055-98d2-4f0c67812e7c', 'Physics', 'JAMB', null, 2002, null, 'The time rate of loss of heat by a body is proportional to the', null, '["Temperature of its surroundings","Difference in temperature between the body and its surrounding","Temperature of the body","Ratio of the temperature of the body to that of its surrounding."]', 1, 'Newton''s law of cooling states that the rate of heat loss is proportional to the temperature difference between the body and its surroundings.', true, '2026-10-12 19:15:54.031', '2026-10-12 19:15:54.031', null, null, null, 'The time rate of loss of heat by a body is proportional to the', '["Temperature of its surroundings","Difference in temperature between the body and its surrounding","Temperature of the body","Ratio of the temperature of the body to that of its surrounding."]', 'Newton''s law of cooling states that the rate of heat loss is proportional to the temperature difference between the body and its surroundings.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1f6543ad-0d4c-4939-9957-74f3b1bd2d8e', 'Physics', 'JAMB', null, 1992, null, 'When an object is placed very close to the pole of a concave mirror, the virtual image obtained is', null, '["Diminished and upright","Diminished and inverted","Enlarged and inverted","Enlarged and upright."]', 3, 'For an object between the pole and the focus of a concave mirror, the image is virtual, upright and enlarged.', true, '2026-10-12 19:15:35.873', '2026-10-12 19:15:35.873', null, null, null, 'When an object is placed very close to the pole of a concave mirror, the virtual image obtained is', '["Diminished and upright","Diminished and inverted","Enlarged and inverted","Enlarged and upright."]', 'For an object between the pole and the focus of a concave mirror, the image is virtual, upright and enlarged.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1f886c7c-7a6e-495d-a273-74a35a03a3d6', 'Literature in English', 'JAMB', null, 2026, null, 'The playwright''s use of direct audience interaction is an example of', null, '["dramatic irony","breaking the fourth wall","catharsis","climax"]', 1, 'It is breaking the fourth wall.', true, '2026-09-12 11:14:10.225', '2026-09-12 11:14:10.225', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1f8cc946-9c82-4bfa-a1a3-6e3f17f599eb', 'Biology', 'JAMB', null, 2026, null, 'The mammalian erythrocytes differ from the leucocytes at maturity because the erythrocytes are', null, '["Discoid and nucleated","Discoid and enucleated","Amoeboid and nucleated","Amoeboid and enucleated"]', 1, 'Mammalian erythrocytes (red blood cells) at maturity are biconcave, discoid (disk-shaped) cells that lack a nucleus (enucleated). They also lack most organelles, including mitochondria, to maximize space for hemoglobin. Leucocytes (white blood cells) are irregular (amoeboid) in shape and contain a nucleus. The enucleated state of erythrocytes is an adaptation that allows for maximum oxygen-carrying capacity. The loss of the nucleus occurs during maturation in the bone marrow before the cells enter circulation.', true, '2026-09-09 03:18:25.265', '2026-09-09 03:18:25.265', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1fa33fb5-af3a-4841-9061-d22e7d3ed424', 'Physics', 'JAMB', null, 1985, null, 'A simple pendulum with a period of 2.0 s has its length doubled. Its new period is', null, '["1.00 s","1.41 s","0.35 s","2.83 s","4.00 s"]', 3, 'T is proportional to √L, so T'' = 2.0 x √2 = 2.83 s.', true, '2026-10-12 19:15:20.552', '2026-10-12 19:15:20.552', null, null, null, 'A simple pendulum with a period of 2.0 s has its length doubled. Its new period is', '["1.00 s","1.41 s","0.35 s","2.83 s","4.00 s"]', 'T is proportional to √L, so T'' = 2.0 x √2 = 2.83 s.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1fa63650-985a-4276-9949-8e27257ed09b', 'Yoruba', 'JAMB', null, 2002, null, 'Ìwé Ààrò Mèta ni ìbèèrè 35-37 dá lé. ‘Ilé ayé kò tó nyìkan Atubótán Ìàgbà níìú ohun tó wà lókè èèpé … Bùgbòn òjò àtisùn Ìçbó’ Nínú Atubótán, àtubótán túmò sí', null, '["dúníyàn","òjò òla","àséyìnbò","ìgbéyìn."]', 3, 'Àtubótán túmò sí ìgbéyìn.', true, '2026-10-13 13:22:39.999', '2026-10-13 13:22:39.999', null, null, null, 'Ìwé Ààrò Mèta ni ìbèèrè 35-37 dá lé. ‘Ilé ayé kò tó nyìkan Atubótán Ìàgbà níìú ohun tó wà lókè èèpé … Bùgbòn òjò àtisùn Ìçbó’ Nínú Atubótán, àtubótán túmò sí', '["dúníyàn","òjò òla","àséyìnbò","ìgbéyìn."]', 'Àtubótán túmò sí ìgbéyìn.', '{"bold":["ìgbéyìn"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1fa65256-7398-4e7b-b0a6-b5d37e98ba61', 'Economics', 'JAMB', null, 2026, null, 'The motive for holding money for unforeseen circumstances is known as?', null, '["Speculative","Precautionary","Transaction","Investment"]', 1, 'Precautionary motive is holding money for unforeseen circumstances.', true, '2026-09-12 11:01:10.851', '2026-09-12 11:01:10.851', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1fb05270-b524-47fd-9da0-8fb5d2700158', 'Chemistry', 'JAMB', null, 2026, null, 'The gas produced when calcium dicarbide touches water is', null, '["ethene","ethane","ethyne","ethanol"]', 2, 'CaC₂ + 2H₂O → Ca(OH)₂ + C₂H₂ (ethyne).', true, '2026-09-12 11:36:03.364', '2026-09-12 11:36:03.364', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1fbbb141-3753-41ff-9711-763fe6e62498', 'Physics', 'JAMB', null, 2026, null, 'Calculate the energy stored in a stretched spring constant 10000Nm⁻¹ when a force of 200N is applied to its end', null, '["2000J","200J","0.2J","2J"]', 3, 'F = kx, so x = F/k = 200/10000 = 0.02m. Energy = ½kx² = ½ × 10000 × 0.0004 = 2J.', true, '2026-09-10 10:56:46.115', '2026-09-10 10:56:46.115', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1fbc6b88-29ab-4a14-9977-d02486db3f7f', 'English Language', 'JAMB', null, 2007, null, 'The panel''s <u>----------</u> was stretched to the limit by what they heard.', null, '["credit","credence","credibility","credulity"]', 2, 'Correct spelling and meaning: credibility.', true, '2026-10-24 07:21:34.657', '2026-10-24 07:21:34.657', null, null, null, 'The panel''s <u>----------</u> was stretched to the limit by what they heard.', '["credit","credence","credibility","credulity"]', 'Correct spelling and meaning: credibility.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1fc6a2db-e7a1-4177-833c-c75b61117ebc', 'Physics', 'JAMB', null, 2026, null, 'What is the graduation of the meter rule?', null, '["1m","1mm","0.1mm","0.1m","100cm"]', 1, 'The graduation of a meter rule is 1mm. A standard meter rule is 1 meter long and has markings every millimeter (mm).', true, '2026-09-10 10:56:44.711', '2026-09-10 10:56:44.711', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1ffbc150-5520-404b-ace2-b73ec9e9e504', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. When kerosene was poured on the fire, the effect was <u>instantaneous</u>.', null, '["momentary","momentous","amazing","terrifying","immediate"]', 4, 'Instantaneous = immediate.', true, '2026-10-24 01:01:40.248', '2026-10-24 01:01:40.248', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. When kerosene was poured on the fire, the effect was <u>instantaneous</u>.', '["momentary","momentous","amazing","terrifying","<u>immediate</u>"]', '<b>Instantaneous</b> = <b>immediate</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('1ffe9d29-5219-492c-9d21-8758aac30fd4', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The student''s <u>remonstrance</u> were rebuffed by the authority.', null, '["protest","suggestions","complaints","regrets"]', 0, 'Remonstrance = protest.', true, '2026-10-24 01:04:08.482', '2026-10-24 01:04:08.482', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The student''s <u>remonstrance</u> were rebuffed by the authority.', '["<u>protest</u>","suggestions","complaints","regrets"]', '<b>Remonstrance</b> = <b>protest</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2003ab2d-0e80-45a6-a1da-1f8b927db565', 'Physics', 'JAMB', null, 2000, null, 'If a charged ion goes through combined electric and magnetic fields, the resultant emergent velocity of the ion is', null, '["E/B","EB","B/E","E - B"]', 0, 'An ion passes undeflected when the electric force equals the magnetic force: qE = qvB, so v = E/B.', true, '2026-10-12 19:15:50.072', '2026-10-12 19:15:50.072', null, null, null, 'If a charged ion goes through combined electric and magnetic fields, the resultant emergent velocity of the ion is', '["E/B","EB","B/E","E - B"]', 'An ion passes undeflected when the electric force equals the magnetic force: qE = qvB, so v = E/B.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2004bbd2-9e1e-47c7-a3d2-47123cbda1b3', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Jummai is <u>cruel</u> to her husband.', null, '["harsh","brutal","passionate","ferocious"]', 2, 'Cruel = unkind; opposite = passionate.', true, '2026-10-24 07:21:29.27', '2026-10-24 07:21:29.27', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Jummai is <u>cruel</u> to her husband.', '["harsh","brutal","passionate","ferocious"]', 'Cruel = unkind; opposite = passionate.', '{}');
