insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('20c4efb6-9b0b-4a87-8064-043291337acc', 'Biology', 'JAMB', null, 2005, null, 'The only vein that carries pure oxygenated blood is the', null, '["renal vein","pulmonary vein","hepatic vein","sciatic vein"]', 1, 'The pulmonary vein carries oxygenated blood.', true, '2026-10-12 20:59:37.226', '2026-10-12 20:59:37.226', null, null, null, 'The only vein that carries pure oxygenated blood is the', '["renal vein","pulmonary vein","hepatic vein","sciatic vein"]', 'The pulmonary vein carries oxygenated blood.', '{"bold":["pulmonary vein"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('20e4515f-f036-4ada-b1db-63c4b33f969e', 'Literature in English', 'JAMB', null, 2026, null, '''I have told you a thousand times to be careful'' is an example of what figure of speech.', null, '["hyperbole","litotes","euphemism","oxymoron"]', 0, 'The statement is an example of hyperbole.', true, '2026-09-12 11:05:36.65', '2026-09-12 11:05:36.65', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('20ee5881-a6c6-48bd-8cbb-50c21a5e16f5', 'Financial Accounting', 'UTME', null, 2003, null, 'The necessary accounts to be opened on the issue of ordinary share capital are', null, '["preference share capital, cash and allotment accounts","bank and ordinary share capital accounts","cash and ordinary share capital accounts","nominal value and ordinary share capital accounts"]', 1, 'The necessary accounts to be opened on the issue of ordinary share capital are bank and ordinary share capital accounts.', true, '2026-10-12 22:00:01.361', '2026-10-12 22:00:01.361', null, null, null, 'The necessary accounts to be opened on the issue of ordinary share capital are', '["preference share capital, cash and allotment accounts","<b>bank and ordinary share capital accounts</b>","cash and ordinary share capital accounts","nominal value and ordinary share capital accounts"]', 'The necessary accounts to be opened on the issue of ordinary share capital are <b>bank and ordinary share capital accounts</b>.', '{"bold":["bank and ordinary share capital accounts"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('20f63a38-459d-4f1e-9699-cfcdad39dea2', 'Government', 'JAMB', null, 2026, null, 'Nationalism in West Africa was aimed at', null, '["working out an alliance with colonial regimes","bringing all the educated elite together","the attainment of political independence from Britain","the attainment of political independence from the colonizers"]', 3, 'Nationalism in West Africa was aimed at the attainment of political independence from the colonizers. Nationalist movements across West Africa sought to end colonial rule and achieve self-government. While some nationalists initially sought reforms within the colonial system, the ultimate goal was independence from colonial powers. This was achieved through various means including political agitation, protests, strikes, and negotiations. The answer is more general (colonizers) than specific (Britain).', true, '2026-09-10 10:44:18.72', '2026-09-10 10:44:18.72', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('20fb7e1c-594d-4a42-afca-016159636ae1', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). ''<u>To ask after a friend</u>'' is to ________________', null, '["ask questions about the friend","inquire about the friend''s welfare","go after the friend","like the friend","take after the friend"]', 1, '''Ask after'' means inquire about welfare.', true, '2026-10-24 01:02:00.878', '2026-10-24 01:02:00.878', null, null, null, '(Choose the most appropriate interpretation). ''<u>To ask after a friend</u>'' is to ________________', '["ask questions about the friend","<u>inquire about the friend''s welfare</u>","go after the friend","like the friend","take after the friend"]', '''<b>Ask after</b>'' means <b>inquire about welfare</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2105245f-b449-4623-a09a-8abe527c9e4a', 'Physics', 'JAMB', null, 1991, null, 'Which of the following is TRUE of light and sound waves?', null, '["They both transmit energy","They both need a medium for propagation","They are both transverse waves","Their velocities in air are equal."]', 0, 'Both transfer energy. Light needs no medium, sound is longitudinal, and their speeds are very different.', true, '2026-10-12 19:15:33.461', '2026-10-12 19:15:33.461', null, null, null, 'Which of the following is <b>TRUE</b> of light and sound waves?', '["They both transmit energy","They both need a medium for propagation","They are both transverse waves","Their velocities in air are equal."]', 'Both transfer energy. Light needs no medium, sound is longitudinal, and their speeds are very different.', '{"bold":["TRUE"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2106ac14-851b-486e-8e2e-28c1b0433fc2', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). <u>For all he cared, the game was as good as lost</u>.', null, '["He did not care if the game was lost","He could not care less if the game was lost","He was almost certain that the game would be lost","He was afraid the game would be lost","The game was very good, and he cared very much about losing it"]', 0, '''For all he cared'' = did not care.', true, '2026-10-24 01:04:14.881', '2026-10-24 01:04:14.881', null, null, null, '(Choose the most appropriate interpretation). <u>For all he cared, the game was as good as lost</u>.', '["<u>He did not care if the game was lost</u>","He could not care less if the game was lost","He was almost certain that the game would be lost","He was afraid the game would be lost","The game was very good, and he cared very much about losing it"]', '''<b>For all he cared</b>'' = <b>did not care</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2109d862-3dad-40c8-9b0d-cca1baaf2e8a', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). Jamila will do well <u>if she was given a fair crack of the whip</u>', null, '["She would do well if she was given a fair whip","She would excel if she used the whip well","She would do well if she was given equal opportunity","She would do well if she was made to cry"]', 2, '''Fair crack of the whip'' = equal opportunity.', true, '2026-10-24 01:04:24.201', '2026-10-24 01:04:24.201', null, null, null, '(Choose the most appropriate interpretation). Jamila will do well <u>if she was given a fair crack of the whip</u>', '["She would do well if she was given a fair whip","She would excel if she used the whip well","<u>She would do well if she was given equal opportunity</u>","She would do well if she was made to cry"]', '''<b>Fair crack of the whip</b>'' = <b>equal opportunity</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2114863c-7c17-4af8-91d5-ec6339f8e003', 'Economics', 'JAMB', null, 2026, null, 'All the following are banking institutions except', null, '["Merchant bank","Commercial bank","Stock exchange","Development bank"]', 2, 'Stock exchange is not a banking institution.', true, '2026-09-12 11:01:11.085', '2026-09-12 11:01:11.085', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('211e4253-0996-4928-a40c-0dc488837334', 'Financial Accounting', 'UTME', null, 2004, null, 'A company paid cash in redemption of N10 000 debenture. The accounting entry to record this will be to debit', null, '["cash and credit debentures","debenture and credit cash","cash and credit capital","capital and debit cash"]', 1, 'Debenture Account will be debited while Cash Account will be credited with 10,000. Debit the Receiver, Credit the Giver.', true, '2026-10-12 22:00:03.772', '2026-10-12 22:00:03.772', null, null, null, 'A company paid cash in redemption of N10 000 debenture. The accounting entry to record this will be to debit', '["cash and credit debentures","<b>debenture and credit cash</b>","cash and credit capital","capital and debit cash"]', '<b>Debenture Account</b> will be debited while Cash Account will be credited with 10,000. Debit the Receiver, Credit the Giver.', '{"bold":["Debenture Account"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('21232ba8-efc3-4128-bed6-dc2e7515184b', 'Government', 'JAMB', null, 2026, null, 'OAU provided a platform for the', null, '["disengagement from colonial rules","promotion of unity among states","advancement of competition with the Europeans","advancement of economic development of the continent"]', 1, 'The OAU provided a platform for the promotion of unity among states.', true, '2026-09-12 11:24:48.162', '2026-09-12 11:24:48.162', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2126b958-5d46-49b1-8ec8-79be46c3a225', 'Physics', 'JAMB', null, 2000, null, 'A transverse wave is applied to a string whose mass per unit length is 3 x 10⁻² kg m⁻¹. If the string is under a tension of 12 N, the speed of propagation of the wave is', null, '["40 m s⁻¹","30 m s⁻¹","20 m s⁻¹","5 m s⁻¹"]', 2, 'v = √(T/μ) = √(12/0.03) = √400 = 20 m s⁻¹.', true, '2026-10-12 19:15:49.749', '2026-10-12 19:15:49.749', null, null, null, 'A transverse wave is applied to a string whose mass per unit length is 3 x 10<sup>-2</sup> kg m<sup>-1</sup>. If the string is under a tension of 12 N, the speed of propagation of the wave is', '["40 m s<sup>-1</sup>","30 m s<sup>-1</sup>","20 m s<sup>-1</sup>","5 m s<sup>-1</sup>"]', 'v = √(T/μ) = √(12/0.03) = √400 = 20 m s<sup>-1</sup>.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2127c8e0-582b-4598-a55c-a2ad4bca4141', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Some of my neighbours have an <u>antipathy</u> to dogs', null, '["enmity towards","acronym for","affection for","alarm for"]', 2, 'Antipathy = dislike; opposite = affection.', true, '2026-10-24 07:21:31.838', '2026-10-24 07:21:31.838', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Some of my neighbours have an <u>antipathy</u> to dogs', '["enmity towards","acronym for","affection for","alarm for"]', 'Antipathy = dislike; opposite = affection.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('212a3b17-bbe4-4974-a288-414e3d17036a', 'Physics', 'JAMB', null, 2026, null, 'The momentum of a car moving at a constant speed in a circular track', null, '["can be both positive and negative","can be zero depending on its position in the track","can be zero depending on its inertia in the track","a centrifugal"]', 0, 'The momentum of a car moving at constant speed in a circular track can be both positive and negative. Momentum is a vector quantity, and its direction changes continuously as the car moves around the track. At different points, the momentum vector points in different directions.', true, '2026-09-10 10:56:44.117', '2026-09-10 10:56:44.117', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('212d5ed7-bc68-4bb6-a126-4c8da70c2b86', 'Biology', 'JAMB', null, 2026, null, 'Which of these worms is beneficial to man?', null, '["Hook worm","Tape worm","Round worm","Earthworm","Guinea worm"]', 3, 'Earthworms are beneficial to humans as they improve soil fertility through their burrowing activities. Their tunnels aerate the soil, improve drainage, and bring nutrients from deeper layers to the surface. Their castings (worm dung) are rich in nutrients and improve soil structure. The other options are parasitic worms that cause diseases in humans: hookworm (ancylostomiasis), tapeworm (taeniasis), roundworm (ascariasis), and guinea worm (dracunculiasis), all of which are harmful parasites.', true, '2026-09-09 03:18:23.87', '2026-09-09 03:18:23.87', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('213b5265-64c4-4b55-8687-a8c2a896b4cd', 'Biology', 'JAMB', null, 2026, null, 'Which of the following is a homeostatic response in humans?', null, '["withdrawing the hand from a hot object","the mouth getting watery when food is sighted","yawning owing to tiredness","shivering in a cold environment"]', 3, 'Shivering in a cold environment is a homeostatic response in humans. Shivering generates heat through muscle contraction, helping to maintain body temperature. Withdrawing the hand from a hot object is a reflex action. Mouth watering when food is sighted is a conditioned response. Yawning is a response to tiredness and increased CO₂. Homeostasis is the maintenance of a stable internal environment, and shivering is a thermoregulatory response to maintain body temperature.', true, '2026-09-09 03:19:11.184', '2026-09-09 03:19:11.184', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('214257f7-8135-4d39-a3c9-27ee568afde9', 'Literature in English', 'JAMB', null, 2026, null, 'Which of the following best explains the effect of alliteration in poetry?', null, '["It creates rhythm and musicality","It compares two unlike things directly","It exaggerates reality","It contradicts meaning"]', 0, 'Alliteration creates rhythm and musicality.', true, '2026-09-12 11:11:24.613', '2026-09-12 11:11:24.613', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2142dc6a-59d0-40d1-99ac-7d35c8de2f08', 'Chemistry', 'JAMB', null, 2026, null, 'One mole of an hydrocarbon contains 48g of carbon. Of its vapour density is 28, the hydrocarbon is? (C=12, H=1)', null, '["An alkane","An alkene","An alkyne","Aromatic"]', 1, 'Molar mass = 56. C₄H₈ is an alkene.', true, '2026-09-12 11:36:28.522', '2026-09-12 11:36:28.522', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('21485a66-b717-4ff6-9a03-02f99e570c4f', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The urban environment tends to form the <u>nucleus</u> of a common dialect.', null, '["setting","repository","cell","core"]', 3, 'Nucleus = core.', true, '2026-10-24 01:03:56.397', '2026-10-24 01:03:56.397', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The urban environment tends to form the <u>nucleus</u> of a common dialect.', '["setting","repository","cell","<u>core</u>"]', '<b>Nucleus</b> = <b>core</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('21506315-1732-4b75-9417-bcd9697e12d5', 'Physics', 'JAMB', null, 1999, null, 'The lowest note emitted by a stretched string has a frequency of 40 Hz. How many overtones are there between 40 Hz and 180 Hz?', null, '["4","3","2","1"]', 1, 'The overtones of a string are 80, 120, 160, 200 Hz... Those between 40 Hz and 180 Hz are 80, 120 and 160 Hz, so there are 3.', true, '2026-10-12 19:15:47.661', '2026-10-12 19:15:47.661', null, null, null, 'The lowest note emitted by a stretched string has a frequency of 40 Hz. How many overtones are there between 40 Hz and 180 Hz?', '["4","3","2","1"]', 'The overtones of a string are 80, 120, 160, 200 Hz... Those between 40 Hz and 180 Hz are 80, 120 and 160 Hz, so there are 3.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2155d57c-e6dc-48ec-9d95-5112c9f9a58b', 'Literature in English', 'JAMB', null, 2026, null, 'The title Redemption Road is most appropriately interpreted as symbolizing', null, '["Economic recovery after colonialism","A literal journey taken by refugees","The moral and psychological quest for healing and forgiveness","Political reform in post-independence Africa"]', 2, 'The title symbolizes the moral and psychological quest for healing and forgiveness.', true, '2026-09-12 11:04:57.698', '2026-09-12 11:04:57.698', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('21623a5d-1a6a-4d8b-a20f-95261a922015', 'English Language', 'JAMB', null, 2007, null, 'When the teacher asked him to join the queue outside, he considered it <u>__________</u> to his dignity', null, '["an attack","an insolence","an affront","a disrespect"]', 2, 'Correct spelling: an affront.', true, '2026-10-24 07:21:43.313', '2026-10-24 07:21:43.313', null, null, null, 'When the teacher asked him to join the queue outside, he considered it <u>__________</u> to his dignity', '["an attack","an insolence","an affront","a disrespect"]', 'Correct spelling: an affront.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('216bd7e5-e8d0-4b7d-bf58-8cb2a29c43dd', 'Physics', 'JAMB', null, 2026, null, 'Short sightedness can be corrected by what type of lens?', null, '["Concave lens","Convex lens","Converging lens","Mirrors"]', 0, 'Short sightedness (myopia) is corrected using a concave (diverging) lens. In myopia, the eye focuses images in front of the retina. A concave lens diverges light rays before they enter the eye, pushing the focus back onto the retina.', true, '2026-09-10 10:56:39.243', '2026-09-10 10:56:39.243', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('21773853-489f-4efa-8f8d-4cec75797a2c', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Adama''s father simply <u>condoned</u> her bad habits instead of punishing her appropriately.', null, '["opposed","blamed","accepted","forbade"]', 3, 'Condoned = tolerated; opposite = forbade.', true, '2026-10-24 07:21:17.809', '2026-10-24 07:21:17.809', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Adama''s father simply <u>condoned</u> her bad habits instead of punishing her appropriately.', '["opposed","blamed","accepted","forbade"]', 'Condoned = tolerated; opposite = forbade.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('218ba422-7483-44d6-9e2e-e5b30b01f590', 'Physics', 'JAMB', null, 1988, null, 'A dynamo primarily converts', null, '["Mechanical energy into electrical energy","Electrical energy into kinetic energy","Potential energy into kinetic energy","Kinetic energy into potential energy."]', 0, 'A dynamo turns mechanical (rotational) energy into electrical energy by electromagnetic induction.', true, '2026-10-12 19:15:28.493', '2026-10-12 19:15:28.493', null, null, null, 'A dynamo primarily converts', '["Mechanical energy into electrical energy","Electrical energy into kinetic energy","Potential energy into kinetic energy","Kinetic energy into potential energy."]', 'A dynamo turns mechanical (rotational) energy into electrical energy by electromagnetic induction.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('21a46940-e88c-4cb0-8ac9-632eb085d48a', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The noise across the road <u>drowned</u> the sound of the keyboard in my room.', null, '["overshadowed","neutralized","balanced","equalized"]', 0, 'Drowned = overshadowed.', true, '2026-10-24 01:04:09.017', '2026-10-24 01:04:09.017', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The noise across the road <u>drowned</u> the sound of the keyboard in my room.', '["<u>overshadowed</u>","neutralized","balanced","equalized"]', '<b>Drowned</b> = <b>overshadowed</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('21a67d6f-2aa1-40d7-b165-19416194576d', 'Physics', 'JAMB', null, 2001, null, 'A student is at a height 4 m above the ground during a thunderstorm. Given that the potential difference between the thundercloud and the ground is 10⁷ V, the electric field created by the storm is', null, '["2.0 x 10⁶ N C⁻¹","2.5 x 10⁶ N C⁻¹","1.0 x 10⁷ N C⁻¹","4.0 x 10⁷ N C⁻¹"]', 1, 'E = V/d = 10⁷/4 = 2.5 x 10⁶ N C⁻¹ (using the 4 m given in the question).', true, '2026-10-12 19:15:51.737', '2026-10-12 19:15:51.737', null, null, null, 'A student is at a height 4 m above the ground during a thunderstorm. Given that the potential difference between the thundercloud and the ground is 10<sup>7</sup> V, the electric field created by the storm is', '["2.0 x 10<sup>6</sup> N C<sup>-1</sup>","2.5 x 10<sup>6</sup> N C<sup>-1</sup>","1.0 x 10<sup>7</sup> N C<sup>-1</sup>","4.0 x 10<sup>7</sup> N C<sup>-1</sup>"]', 'E = V/d = 10<sup>7</sup>/4 = 2.5 x 10<sup>6</sup> N C<sup>-1</sup> (using the 4 m given in the question).', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('21af8b94-100b-4ad9-8864-ed827d6c582f', 'English Language', 'JAMB', null, 2007, null, 'Because of the <u>__________</u> he did to my car, I am going to sue him for <u>__________</u>', null, '["damage/damages","damages/damage","damages/damages","damage/damage"]', 0, 'Correct forms: damage/damages.', true, '2026-10-24 07:21:33.146', '2026-10-24 07:21:33.146', null, null, null, 'Because of the <u>__________</u> he did to my car, I am going to sue him for <u>__________</u>', '["damage/damages","damages/damage","damages/damages","damage/damage"]', 'Correct forms: damage/damages.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('21ca188a-0ce6-4750-bcf2-f735c580b5ef', 'Physics', 'JAMB', null, 1986, null, 'Which of the following properties makes metals ideal for cooking utensils?', null, '["High coefficient of expansion","Good conduction of heat","Low specific heat capacity","Poor radiation of heat."]', 1, 'Metals conduct heat well, so heat passes quickly from the stove to the food.', true, '2026-10-12 19:15:23.522', '2026-10-12 19:15:23.522', null, null, null, 'Which of the following properties makes metals ideal for cooking utensils?', '["High coefficient of expansion","Good conduction of heat","Low specific heat capacity","Poor radiation of heat."]', 'Metals conduct heat well, so heat passes quickly from the stove to the food.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('21d7204c-3339-4e55-bfcb-deefe19c2f94', 'English Language', 'JAMB', null, 2024, null, 'Choose the option nearest in meaning to the word or phrase in italics: She has a caustic remark on the occasion', null, '["sarcastic","friendly","tangible","insignificant"]', 0, '"Caustic" means sarcastic or bitterly critical.', true, '2026-09-18 09:43:02.894', '2026-09-18 09:43:02.894', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('21e84e01-4452-4bce-ac66-716058db7380', 'Physics', 'JAMB', null, 2026, null, 'Which of the following statements is NOT part of Kepler''s Laws of planetary motion?', null, '["Planets move in circular orbits around the Sun","A line connecting a planet to the Sun sweeps equal areas in equal time intervals","The square of a planet''s orbital period is proportional to the cube of its average distance from the Sun","The Sun exerts a gravitational force on the planets"]', 0, 'Kepler''s first law states that planets move in elliptical orbits, not circular orbits. The statement that planets move in circular orbits is not part of Kepler''s laws.', true, '2026-09-10 10:56:48.761', '2026-09-10 10:56:48.761', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('21e8c546-7e5f-4260-b50b-aeeddb21d3e8', 'Biology', 'JAMB', null, 2012, null, 'A yellow maize is planted and all the fruits obtained are of yellow seeds. When they are cross-bred, yellow seeds and white seeds are obtained in a ratio 3:1. The yellow seed is said to be', null, '["non-heritable","sex-linked","a recessive trait","a dominant trait"]', 3, 'The yellow seed is a dominant trait.', true, '2026-10-12 20:59:45.653', '2026-10-12 20:59:45.653', null, null, null, 'A yellow maize is planted and all the fruits obtained are of yellow seeds. When they are cross-bred, yellow seeds and white seeds are obtained in a ratio 3:1. The yellow seed is said to be', '["non-heritable","sex-linked","a recessive trait","a dominant trait"]', 'The yellow seed is a dominant trait.', '{"bold":["a dominant trait"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('21ef437d-8e3b-47e6-a434-3b5572f4ad23', 'Economics', 'JAMB', null, 2026, null, 'At every point on an indifference curve, the', null, '["total utility is increasing","level of utility is constant","level of utility is increasing","consumer is satisfied"]', 1, 'At every point on an indifference curve, the level of utility is constant. An indifference curve shows different combinations of two goods that give the consumer the same level of satisfaction (utility). The consumer is indifferent between any two points on the same curve because they yield equal utility. As you move along the curve, you trade one good for another but total utility remains unchanged. Higher indifference curves represent higher utility levels.', true, '2026-09-10 10:42:55.775', '2026-09-10 10:42:55.775', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('21f1f0ac-7b6e-47b8-b2ac-ef57499534ca', 'Biology', 'JAMB', null, 2026, null, 'Long neck in giraffe is used to illustrate the theory of', null, '["use and disuse","origin of species","origin of life","natural selection"]', 3, 'The long neck in giraffes is used to illustrate the theory of natural selection. Darwin explained that giraffes with longer necks could reach higher leaves, had a survival advantage, and were more likely to reproduce, passing on their long-neck genes. Lamarck would have explained this as due to use and disuse (giraffes stretched their necks to reach leaves). The long neck is often used as an example of adaptation through natural selection.', true, '2026-09-09 03:19:20.775', '2026-09-09 03:19:20.775', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('21f32566-d463-4102-a32f-0d5dba17b7ec', 'Biology', 'JAMB', null, 2026, null, 'A child with blood group genotype different from those of both parents and with a mother of genotype OO, can only have a father of genotype', null, '["A","B","AB","OO"]', 2, 'A child with a blood group genotype different from both parents, with a mother of genotype OO, can only have a father of genotype AB. If the mother is OO, the child must get an O from the mother. For the child to have a different genotype from both parents, the father must be AB. The child could be AO (blood group A) or BO (blood group B), both different from both parents (mother is O, father is AB). The child cannot be AB or OO. This is a classic example showing how ABO blood group inheritance works.', true, '2026-09-09 03:19:18.136', '2026-09-09 03:19:18.136', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('21f963d1-ae2f-4458-981c-507d16cc80ab', 'Physics', 'JAMB', null, 1991, null, 'The electrochemical equivalent of platinum is 5.0 x 10⁻⁷ kg C⁻¹. To plate-out 1.0 kg of platinum, a current of 100 A must be passed through an appropriate vessel for', null, '["5.6 hours","56 hours","1.4 x 10⁴ hours","2.0 x 10⁴ hours."]', 0, 't = m/(zI) = 1.0/(5.0 x 10⁻⁷ x 100) = 2.0 x 10⁴ s = 5.6 hours.', true, '2026-10-12 19:15:34.375', '2026-10-12 19:15:34.375', null, null, null, 'The electrochemical equivalent of platinum is 5.0 x 10<sup>-7</sup> kg C<sup>-1</sup>. To plate-out 1.0 kg of platinum, a current of 100 A must be passed through an appropriate vessel for', '["5.6 hours","56 hours","1.4 x 10<sup>4</sup> hours","2.0 x 10<sup>4</sup> hours."]', 't = m/(zI) = 1.0/(5.0 x 10<sup>-7</sup> x 100) = 2.0 x 10<sup>4</sup> s = 5.6 hours.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('21fafd9e-1f7b-44f1-b70d-86ecaa97d40c', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). The politician <u>played to the gallery</u> to win the election.', null, '["obeyed the people","sang a good song for the people","went to the gallery","went out of his way to appeal to the taste of the people"]', 3, '''Play to the gallery'' = appeal to popular taste.', true, '2026-10-24 01:02:05.958', '2026-10-24 01:02:05.958', null, null, null, '(Choose the most appropriate interpretation). The politician <u>played to the gallery</u> to win the election.', '["obeyed the people","sang a good song for the people","went to the gallery","<u>went out of his way to appeal to the taste of the people</u>"]', '''<b>Play to the gallery</b>'' = <b>appeal to popular taste</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('220347d2-ee34-4adb-b250-571b5b87b8eb', 'English Language', 'JAMB', null, 2007, null, 'He would rather resign .... compromise his principles.', null, '["than","to","instead","rather than"]', 0, '''Would rather ... than''.', true, '2026-10-25 18:25:06.737', '2026-10-25 18:25:06.737', null, null, null, 'He would rather resign .... compromise his principles.', '["than","to","instead","rather than"]', '''Would rather ... than''.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2210cf3e-1115-4887-8469-4c4faae80774', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). The sudden death of the King <u>put paid to</u> the ambition of the Minister.', null, '["encouraged","rewarded","benefited","terminated"]', 3, '''Put paid to'' = terminated.', true, '2026-10-24 01:04:19.7', '2026-10-24 01:04:19.7', null, null, null, '(Choose the most appropriate interpretation). The sudden death of the King <u>put paid to</u> the ambition of the Minister.', '["encouraged","rewarded","benefited","<u>terminated</u>"]', '''<b>Put paid to</b>'' = <b>terminated</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('221d6930-89b7-4cf6-9382-e1258454461e', 'Financial Accounting', 'UTME', null, 2001, null, 'The accuracy of journalizing is checked by', null, '["ensuring that debit totals equals credit totals","posting all journal entries to ledger accounts","adding all figures in the debit column","comparing accounts in the ledger against the journals"]', 0, 'The accuracy of journalizing is checked by ensuring that debit totals equals credit totals.', true, '2026-10-12 22:00:04.363', '2026-10-12 22:00:04.363', null, null, null, 'The accuracy of journalizing is checked by', '["<b>ensuring that debit totals equals credit totals</b>","posting all journal entries to ledger accounts","adding all figures in the debit column","comparing accounts in the ledger against the journals"]', 'The accuracy of journalizing is checked by <b>ensuring that debit totals equals credit totals</b>.', '{"bold":["ensuring that debit totals equals credit totals"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('221db088-f31a-4f60-8f2b-25c813c9941b', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. He has a <u>big</u> heart, but he is inept at following a witty conversation.', null, '["large","huge","warm","fragile"]', 2, 'Big heart = warm/generous.', true, '2026-10-24 01:01:44.847', '2026-10-24 01:01:44.847', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. He has a <u>big</u> heart, but he is inept at following a witty conversation.', '["large","huge","<u>warm</u>","fragile"]', '<b>Big heart</b> = <b>warm</b>/generous.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2225e736-1388-4633-8b02-d98fdce2896e', 'Literature in English', 'JAMB', null, 2026, null, 'In New Tongue, the ''new tongue'' symbolically represents', null, '["Linguistic confusion","Religious transformation","Political rebellion","Cultural alienation and loss of identity"]', 3, 'The ''new tongue'' represents cultural alienation and loss of identity.', true, '2026-09-12 11:12:05.345', '2026-09-12 11:12:05.345', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('22265108-af7b-4a94-9650-185d0f812e46', 'Biology', 'JAMB', null, 2026, null, 'A gene which expresses itself only in the homozygous condition is', null, '["mutant","dominant","recessive","lethal"]', 2, 'A recessive gene expresses itself only in the homozygous condition (having two copies of the recessive allele). Dominant genes express themselves in both homozygous and heterozygous conditions. Mutant genes may be dominant or recessive. Lethal genes cause death when present in certain combinations (often homozygous). Recessive traits are masked by dominant alleles in heterozygotes, so the phenotype only appears when both alleles are recessive. This principle is fundamental to Mendelian genetics.', true, '2026-09-09 03:18:51.517', '2026-09-09 03:18:51.517', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('222eb094-2aa0-4b95-b17b-bbf10fe05d19', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The discussion became <u>animated</u>.', null, '["specialized","lively","intellectual","unruly"]', 1, 'Animated = lively.', true, '2026-10-24 01:03:54.35', '2026-10-24 01:03:54.35', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The discussion became <u>animated</u>.', '["specialized","<u>lively</u>","intellectual","unruly"]', '<b>Animated</b> = <b>lively</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2239cb61-d8f7-48a3-88f8-0ef35259844c', 'English Language', 'JAMB', null, 2024, null, 'The child would feel irresponsible for his mother''s death even if it is connected with his wishes because', null, '["He regards his wishes as a curse","He hates her and wants her dead","His need are not gratified","He cannot distinguish between wish and reality"]', 3, 'The child cannot distinguish between the wish to kill and the actual act, so he blames himself.', true, '2026-09-18 09:43:02.638', '2026-09-18 09:43:02.638', null, null, 'COMPREHENSION', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('225f2241-7031-4100-95b8-3165622af2a1', 'Literature in English', 'JAMB', null, 2026, null, 'The line "the sea will groan under its weight" in Breast of the Sea is an example of which literary device', null, '["Allusion","Hyperbole","Personification","Metonymy"]', 2, 'The line "the sea will groan under its weight" is an example of personification. The sea is given the human ability to ''groan,'' which is a human vocalization of pain or distress. Personification attributes human qualities to inanimate objects or natural phenomena. Allusion is a reference, hyperbole is exaggeration, and metonymy is substitution.', true, '2026-09-10 10:47:54.414', '2026-09-10 10:47:54.414', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2274d0f5-c4b0-44a1-ad78-8dfb97d2ae6c', 'testing', 'JAMB', null, 2024, null, 'The organisation established a scholarship scheme ....... talented students from disadvantaged backgrounds.', null, '["supporting","support","for support","to support"]', 1, 'Infinitive of purpose: ''to support''.', true, '2026-10-31 16:48:52.506', '2026-10-31 16:48:52.506', null, null, null, 'The organisation established a scholarship scheme ....... talented students from disadvantaged backgrounds.', '["supporting","support","for support","to support"]', 'Infinitive of purpose: ''to support''.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('22808ba2-0227-4b1f-a374-a4fb4b058490', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). I told my brother to <u>get the matter off his chest</u> as soon as possible.', null, '["give serious thought to the matter","say what he has been anxious to say","make a brief comment","state his points clearly"]', 1, '''Get off one''s chest'' = say what has been anxious to say.', true, '2026-10-24 01:02:05.325', '2026-10-24 01:02:05.325', null, null, null, '(Choose the most appropriate interpretation). I told my brother to <u>get the matter off his chest</u> as soon as possible.', '["give serious thought to the matter","<u>say what he has been anxious to say</u>","make a brief comment","state his points clearly"]', '''<b>Get off one''s chest</b>'' = <b>say what has been anxious to say</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('228922ed-25bc-40e6-8d26-869fbcabdef9', 'Chemistry', 'JAMB', null, 2026, null, 'The vulcanizer''s solution is prepared by dissolving rubber in?', null, '["Ethanol","Kerosene","Benzene","Petrol"]', 2, 'Rubber is dissolved in benzene to make vulcanizer''s solution.', true, '2026-09-12 11:36:24.798', '2026-09-12 11:36:24.798', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('22918d47-3034-40b5-a2dc-5c95b5eeb3b2', 'Biology', 'JAMB', null, 2003, null, 'Spines and shells on animals are adaptations for', null, '["camouflage","chemical defence","physical defence","mimicry"]', 2, 'Spines and shells are adaptations for physical defence.', true, '2026-10-12 20:59:34.1', '2026-10-12 20:59:34.1', null, null, null, 'Spines and shells on animals are adaptations for', '["camouflage","chemical defence","physical defence","mimicry"]', 'Spines and shells are adaptations for physical defence.', '{"bold":["physical defence"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('22983d92-aa86-4deb-8c1a-dbd1aa330b85', 'English Language', 'JAMB', null, 2024, null, 'I can''t go out of the rain now, the rain is not ______', null, '["letting down","letting up","giving in","giving up"]', 1, '"Letting up" means diminishing or stopping.', true, '2026-09-18 09:43:02.313', '2026-09-18 09:43:02.313', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('229fdcc0-d697-4da7-b7bb-200a37b1c0b4', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'What did Paul compare the church to in 1 Corinthians 12?', null, '["a field","a holy temple","a body","a vine"]', 2, 'Paul compared the church to a body with many members working together.', true, '2026-09-12 10:40:57.365', '2026-09-12 10:40:57.365', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('22a0afad-8faa-4cfa-a2f3-6a92fb00bbca', 'Chemistry', 'JAMB', null, 2026, null, 'The three dimensional shape of ammonia is', null, '["linear","trigonal planar","trigonal pyramidal","tetrahedral"]', 2, 'Ammonia (NH3) features three bonding pairs and one lone pair around the nitrogen atom, producing a trigonal pyramidal geometry.', true, '2026-09-09 17:12:45.99', '2026-09-09 17:12:45.99', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('22a884fe-34e5-45d3-ba42-f9c2cca20785', 'Physics', 'JAMB', null, 1984, null, 'Which of the following is a correct explanation of the inertia of a body?', null, '["Ability to overcome the earth''s gravity","Reluctance to stop moving","Readiness to start moving","Reluctance to start moving and its readiness to stop moving once it has begun to move","Reluctance to start moving and its reluctance to stop moving once it has begun to move."]', 4, 'Inertia is the tendency of a body to resist any change in its state of rest or uniform motion.', true, '2026-10-12 19:15:19.884', '2026-10-12 19:15:19.884', null, null, null, 'Which of the following is a correct explanation of the inertia of a body?', '["Ability to overcome the earth''s gravity","Reluctance to stop moving","Readiness to start moving","Reluctance to start moving and its readiness to stop moving once it has begun to move","Reluctance to start moving and its reluctance to stop moving once it has begun to move."]', 'Inertia is the tendency of a body to resist any change in its state of rest or uniform motion.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('22b264ca-abf7-4d23-8f26-49a6d0c120f0', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The lecturer <u>maintained</u> his usual good humour in spite of the cat-calls and the rude behaviour of his students.', null, '["provoked","obtained","kept","lost","improved"]', 2, 'Maintained = kept.', true, '2026-10-24 01:03:53.49', '2026-10-24 01:03:53.49', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The lecturer <u>maintained</u> his usual good humour in spite of the cat-calls and the rude behaviour of his students.', '["provoked","obtained","<u>kept</u>","lost","improved"]', '<b>Maintained</b> = <b>kept</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('22bb6a16-e516-4f3e-abd2-01a6fd430754', 'Physics', 'JAMB', null, 2004, null, 'A person can focus an object only when it lies within 200 cm from him. Which spectacles should be used to increase his maximum distance of distinct vision to infinity?', null, '["Concave lens","Plane glasses","Binoculars","Convex lens"]', 0, 'He is short-sighted. A concave (diverging) lens makes distant rays appear to come from his far point so he can see clearly.', true, '2026-10-12 19:15:58.231', '2026-10-12 19:15:58.231', null, null, null, 'A person can focus an object only when it lies within 200 cm from him. Which spectacles should be used to increase his maximum distance of distinct vision to infinity?', '["Concave lens","Plane glasses","Binoculars","Convex lens"]', 'He is short-sighted. A concave (diverging) lens makes distant rays appear to come from his far point so he can see clearly.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('22d38ea4-8540-4888-ab99-b196d9e79607', 'Physics', 'JAMB', null, 1993, null, 'Which of the following waves can propagate through a vacuum?', null, '["High velocity sound waves","Ultrasonic waves","Acoustic waves","Infra-red waves"]', 3, 'Infra-red waves are electromagnetic and need no medium. Sound, ultrasonic and acoustic waves are mechanical and need a medium.', true, '2026-10-12 19:15:37.703', '2026-10-12 19:15:37.703', null, null, null, 'Which of the following waves can propagate through a vacuum?', '["High velocity sound waves","Ultrasonic waves","Acoustic waves","Infra-red waves"]', 'Infra-red waves are electromagnetic and need no medium. Sound, ultrasonic and acoustic waves are mechanical and need a medium.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('22d6c480-27e5-4c35-b5df-2d594f30f26c', 'Hausa', 'JAMB', null, 2011, null, 'A wani gari can yamma da Magumi, wai shi Tsauni, an yi wani yaro mai suna Salihi. Iyayensa ba masu wadata ba ne, amma sun yi Ko''karin ganin ya yi ilmin boko da na Arabiya. Bayan Salihi ya kammala karatun firamare, sai mahaiﬁnsa Tanimu, ya nema masa makarantar gaba da ﬁramare. Domin an ce ''Ilimi gishirin zaman duniya.'' Amma kuma samo wa Salihi babbar makarantar Magumi bai yi wa mahaiﬁyarsa D''ahira dadî ba, don ba ta son d''anta ya yi nesa da ita. Dalili shi ne d''ansu tilo namiji, sauran hud''un kuwa duk mata ne. Bugu da Kari, tana jin munanan labarai iri-iri da kan faru a irin wad''annan makarantu. Bayan Salihi ya isa makaranta, sai ya dukufa kan karatu gadan-gadan. Zuwansa ke da wuya, sai suka kulla abota da wani dan ajinsu, wai shi Kasa. Kafin ya ankara, sai da abokinsa ya jefa shi cikin wata kungiyar asiri. Da ya farga da halin da ya shiga, sai ya yi Ko''karin ﬁta daga cikinta, amma aka nuna masa ai ba a haka. ''In har ka ce za ka ﬁce, lallai za a kassara ka, ko ma a halaka ka'' in ji abokinsa. Ganin halin tsaka-mai-wuya da ya shiga, sai ya tsayar da shawarar ya fallasa kungiyar, in ya so komai ta tafasa ta kone. Ya je ya shaida wa shugaban makaranta. Nan take ya sanya jami''an tsaro suka kamo dukkan ''yan kungiyar''. Kotu ta yanke musu hukunci, sannan aka kai su gidan jarun. Da ma an ce, ''Komai nisan jifa kasa za ya fado.'' Mece ce dangantakar Salihi da Dahira?', null, '["Wa da Kanwa.","Uba da ''ya.","Miji da mata.","Da da Uwa."]', 3, 'Dahira ita ce mahaifiyar Salihi, don haka dangantakar su ita ce ta da da uwa.', true, '2026-10-13 10:37:20.128', '2026-10-13 10:37:20.128', null, null, null, 'A wani gari can yamma da Magumi, wai shi Tsauni, an yi wani yaro mai suna Salihi. Iyayensa ba masu wadata ba ne, amma sun yi Ko''karin ganin ya yi ilmin boko da na Arabiya. Bayan Salihi ya kammala karatun firamare, sai mahaiﬁnsa Tanimu, ya nema masa makarantar gaba da ﬁramare. Domin an ce ''Ilimi gishirin zaman duniya.'' Amma kuma samo wa Salihi babbar makarantar Magumi bai yi wa mahaiﬁyarsa D''ahira dadî ba, don ba ta son d''anta ya yi nesa da ita. Dalili shi ne d''ansu tilo namiji, sauran hud''un kuwa duk mata ne. Bugu da Kari, tana jin munanan labarai iri-iri da kan faru a irin wad''annan makarantu. Bayan Salihi ya isa makaranta, sai ya dukufa kan karatu gadan-gadan. Zuwansa ke da wuya, sai suka kulla abota da wani dan ajinsu, wai shi Kasa. Kafin ya ankara, sai da abokinsa ya jefa shi cikin wata kungiyar asiri. Da ya farga da halin da ya shiga, sai ya yi Ko''karin ﬁta daga cikinta, amma aka nuna masa ai ba a haka. ''In har ka ce za ka ﬁce, lallai za a kassara ka, ko ma a halaka ka'' in ji abokinsa. Ganin halin tsaka-mai-wuya da ya shiga, sai ya tsayar da shawarar ya fallasa kungiyar, in ya so komai ta tafasa ta kone. Ya je ya shaida wa shugaban makaranta. Nan take ya sanya jami''an tsaro suka kamo dukkan ''yan kungiyar''. Kotu ta yanke musu hukunci, sannan aka kai su gidan jarun. Da ma an ce, ''Komai nisan jifa kasa za ya fado.'' Mece ce dangantakar Salihi da Dahira?', '["Wa da Kanwa.","Uba da ''ya.","Miji da mata.","Da da Uwa."]', 'Dahira ita ce mahaifiyar Salihi, don haka dangantakar su ita ce ta da da uwa.', '{"bold":["da da uwa"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('22df4b29-e3c9-4dd1-a9ae-948d328bf262', 'Chemistry', 'JAMB', null, 2026, null, 'Which of the following oxides will react with both hydrochloric acid and sodium hydroxide?', null, '["CaO","SO₂","Al₂O₃","CO₂"]', 2, 'Al₂O₃ is amphoteric, meaning it reacts with both acids and bases. With HCl: Al₂O₃ + 6HCl → 2AlCl₃ + 3H₂O. With NaOH: Al₂O₃ + 2NaOH → 2NaAlO₂ + H₂O. CaO is basic, while SO₂ and CO₂ are acidic.', true, '2026-09-12 09:38:09.838', '2026-09-12 09:38:09.838', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('22df560b-abb4-4c93-a5d6-a4d47e31f282', 'Chemistry', 'JAMB', null, 2026, null, 'In the reaction between sodium hydroxide and sulphuric acid solutions, what volume of 0.5 molar sodium hydroxide would exactly neutralise 10cm³ of 1.25 molar sulphuric acid?', null, '["5cm³","10cm³","20cm³","25cm³","50cm³"]', 4, '2NaOH + H₂SO₄ → Na₂SO₄ + 2H₂O. Moles H₂SO₄ = 0.01 × 1.25 = 0.0125 mol. Moles NaOH = 0.025 mol. Volume = 0.025/0.5 = 0.05 dm³ = 50 cm³.', true, '2026-09-12 11:36:15.237', '2026-09-12 11:36:15.237', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('22e6e4b1-bc33-4c20-bd29-af1ff29f7dec', 'Physics', 'JAMB', null, 1986, null, 'A constant force of magnitude F acts on an object of mass 0.04 kg initially at rest at a point O. If the speed of the object when it has moved 50 m from O is 500 m s⁻¹, what is the value of F?', null, '["0.4 N","100.0 N","250.0 N","1 000.0 N"]', 1, 'a = v²/2s = 500²/(2 x 50) = 2500 m s⁻². F = ma = 0.04 x 2500 = 100 N.', true, '2026-10-12 19:15:23.093', '2026-10-12 19:15:23.093', null, null, null, 'A constant force of magnitude F acts on an object of mass 0.04 kg initially at rest at a point O. If the speed of the object when it has moved 50 m from O is 500 m s<sup>-1</sup>, what is the value of F?', '["0.4 N","100.0 N","250.0 N","1 000.0 N"]', 'a = v<sup>2</sup>/2s = 500<sup>2</sup>/(2 x 50) = 2500 m s<sup>-2</sup>. F = ma = 0.04 x 2500 = 100 N.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('22ec1b22-3823-41f8-bc7f-f4b358a22494', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The <u>severity</u> of the harmattan helped me to complete my writing assignment in record time because I had no choice but to lock myself indoors.', null, '["warmth","mildness","moderation","leniency","gentility"]', 1, 'Severity = harshness; opposite = mildness.', true, '2026-10-24 07:21:11.065', '2026-10-24 07:21:11.065', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The <u>severity</u> of the harmattan helped me to complete my writing assignment in record time because I had no choice but to lock myself indoors.', '["warmth","mildness","moderation","leniency","gentility"]', 'Severity = harshness; opposite = mildness.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('22eddbae-867e-4817-b543-547bda4fae8f', 'Literature in English', 'JAMB', null, 2026, null, 'What does Cleopatra mean by ''if it be love indeed, tell me how much''?', null, '["Cleopatra has been unfaithful, and he wants to make her jealous","Cleopatra is teasing Anthony and testing the depth of his love for her","Cleopatra''s wealth backs the triumvirate","Cleopatra is a lover of pleasure"]', 1, 'Cleopatra is teasing Anthony and testing his love.', true, '2026-09-12 11:14:08.224', '2026-09-12 11:14:08.224', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('22ef0555-9074-4e18-9f52-50433ce8e63c', 'Physics', 'JAMB', null, 1995, null, 'A uniform rod PQ of length 1 m and mass 2 kg is pivoted at the end P. If a load of 14 N is placed at the centre of the rod, find the force that should be applied vertically upwards at Q to maintain the rod in equilibrium horizontally. [g = 10 m s⁻²]', null, '["68 N","28 N","17 N","7 N"]', 2, 'Taking moments about P: F x 1 = 20 x 0.5 + 14 x 0.5 = 17, so F = 17 N.', true, '2026-10-12 19:15:40.879', '2026-10-12 19:15:40.879', null, null, null, 'A uniform rod PQ of length 1 m and mass 2 kg is pivoted at the end P. If a load of 14 N is placed at the centre of the rod, find the force that should be applied vertically upwards at Q to maintain the rod in equilibrium horizontally. [g = 10 m s<sup>-2</sup>]', '["68 N","28 N","17 N","7 N"]', 'Taking moments about P: F x 1 = 20 x 0.5 + 14 x 0.5 = 17, so F = 17 N.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('22ef536f-4583-48a4-9f0e-b4123a0973d3', 'Economics', 'JAMB', null, 2026, null, 'An economy in which decision of what to produce is taken partly by private individuals and state is referred to as?', null, '["Mixed","Communist","Socialist","Capitalist"]', 0, 'A mixed economy has both private and state decision-making.', true, '2026-09-12 11:01:34.661', '2026-09-12 11:01:34.661', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('22f576d4-f731-4881-aa2a-ac0ffe5839c9', 'Physics', 'JAMB', null, 1984, null, 'What is the apparent colour of a RED SHIRT when viewed in PURE green light?', null, '["Red","Green","Yellow","Black","Blue"]', 3, 'A red shirt absorbs green light and reflects only red. In pure green light there is no red to reflect, so it appears black.', true, '2026-10-12 19:15:20.003', '2026-10-12 19:15:20.003', null, null, null, 'What is the apparent colour of a RED SHIRT when viewed in PURE green light?', '["Red","Green","Yellow","Black","Blue"]', 'A red shirt absorbs green light and reflects only red. In pure green light there is no red to reflect, so it appears black.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('22fa3ef6-a6ab-4adc-a910-0c6a89b4630c', 'Government', 'JAMB', null, 2026, null, 'The guiding principle of communism is from each according to his/her', null, '["ability and to each according to his/her need","qualification and to each according to his/her need","race and to each according to his/her ability","age and to each according to his/her status"]', 0, 'Communism''s guiding principle is from each according to ability, to each according to need.', true, '2026-09-12 11:23:59.732', '2026-09-12 11:23:59.732', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('231c3ecc-d53d-476c-9425-af4a28cd265a', 'Literature in English', 'JAMB', null, 2026, null, 'Ananse''s scheme to send identical letters to multiple chiefs is an example of', null, '["Dramatic irony and opportunistic manipulation","Catharsis leading to emotional purification","A tragic flaw resulting in his downfall","Symbolism representing colonial resistance"]', 0, 'Ananse''s scheme is an example of dramatic irony and opportunistic manipulation.', true, '2026-09-12 11:12:00.057', '2026-09-12 11:12:00.057', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('232a40a2-fbb3-4e68-9cdb-134a80420e72', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The college was worried about Tunji''s <u>garrulous</u> tendencies.', null, '["reticent","loquacious","quarrelsome","outspoken"]', 0, 'Garrulous = talkative; opposite = reticent.', true, '2026-10-24 07:21:15.092', '2026-10-24 07:21:15.092', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The college was worried about Tunji''s <u>garrulous</u> tendencies.', '["reticent","loquacious","quarrelsome","outspoken"]', 'Garrulous = talkative; opposite = reticent.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('232e44ae-b0a7-4bbe-8a69-678a95a5bc9f', 'Physics', 'JAMB', null, 1993, null, 'The force experienced by an object of mass 60.0 kg in the moon''s gravitational field is 100.2 N. What is the intensity of the gravitational field?', null, '["0.60 N kg⁻¹","1.67 N kg⁻¹","6.12 x 10² N kg⁻¹","9.81 m s⁻²"]', 1, 'Gravitational field intensity = force/mass = 100.2/60.0 = 1.67 N kg⁻¹.', true, '2026-10-12 19:15:37.162', '2026-10-12 19:15:37.162', null, null, null, 'The force experienced by an object of mass 60.0 kg in the moon''s gravitational field is 100.2 N. What is the intensity of the gravitational field?', '["0.60 N kg<sup>-1</sup>","1.67 N kg<sup>-1</sup>","6.12 x 10<sup>2</sup> N kg<sup>-1</sup>","9.81 m s<sup>-2</sup>"]', 'Gravitational field intensity = force/mass = 100.2/60.0 = 1.67 N kg<sup>-1</sup>.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2361be2c-e036-4722-8d1d-460cc1750346', 'Literature in English', 'JAMB', null, 2026, null, 'The speaker''s attitude towards the ''New Tongue'' is mainly', null, '["proud and satisfied","indifferent and calm","critical and regretful","playful and humorous"]', 2, 'The speaker''s attitude is critical and regretful.', true, '2026-09-12 11:10:21.683', '2026-09-12 11:10:21.683', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2364fd70-06f8-4411-8840-66e38a219be4', 'Biology', 'JAMB', null, 2013, null, 'Which of the following types of feathers is used for flight in birds?', null, '["Covert","Down","Quill","Filoplume"]', 2, 'Quill feathers are used for flight in birds.', true, '2026-10-12 20:59:46.466', '2026-10-12 20:59:46.466', null, null, null, 'Which of the following types of feathers is used for flight in birds?', '["Covert","Down","Quill","Filoplume"]', 'Quill feathers are used for flight in birds.', '{"bold":["Quill"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('23794d15-db89-4703-9cc1-228e850fdcaf', 'Biology', 'JAMB', null, 2026, null, 'From the study of Galapagos finches, Darwin derived his theory of evolution from', null, '["comparative anatomy","comparative physiology","fossil remains","comparative embryology"]', 0, 'From the study of Galapagos finches, Darwin derived his theory of evolution from comparative anatomy. Darwin observed variations in beak shapes among finches on different islands of the Galapagos, which were adapted to different food sources. This provided evidence for adaptation and natural selection. Comparative anatomy shows how organisms share common features but have modified them for different environments.', true, '2026-09-09 03:19:23.441', '2026-09-09 03:19:23.441', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('237a9800-355f-4dfc-819b-5c2e1d7faba3', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). The man who gave the closing remarks at the party spoke <u>tongue-in-cheek</u>.', null, '["ironically","wisely","profusely","eloquently"]', 0, '''Tongue-in-cheek'' = ironically/not seriously.', true, '2026-10-24 01:02:07.6', '2026-10-24 01:02:07.6', null, null, null, '(Choose the most appropriate interpretation). The man who gave the closing remarks at the party spoke <u>tongue-in-cheek</u>.', '["<u>ironically</u>","wisely","profusely","eloquently"]', '''<b>Tongue-in-cheek</b>'' = <b>ironically/not seriously</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('23820df9-38f5-4729-9a97-593224e3ffef', 'English Language', 'JAMB', null, 2024, null, 'Our world of accelerating social and technological change means that', null, '["Our world is moving too fast socially and technologically","Our world is going through more rapid, social and technological change","The social and technological change is more exhilarating than before","The social and technological change is accelerating our world"]', 1, 'The phrase means the world is experiencing increasingly rapid social and technological change.', true, '2026-09-18 09:43:02.623', '2026-09-18 09:43:02.623', null, null, 'COMPREHENSION', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('23849457-32cb-4023-ad9e-4e55b61a711c', 'Economics', 'JAMB', null, 2026, null, 'What happens when the central bank increases the bank rate in an economy?', null, '["Increase in consumer''s borrowing","Increase in money supply","Increase in bank''s lending","Borrowing is discouraged"]', 3, 'Higher bank rate discourages borrowing.', true, '2026-09-12 11:02:13.057', '2026-09-12 11:02:13.057', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('23854c51-f63a-443d-9c05-07546e6186a0', 'Literature in English', 'JAMB', null, 2026, null, 'In Redemption Road, the narrative structure is best described as', null, '["A linear plot focusing on a single protagonist''s growth","A non-linear narrative employing multiple perspectives to depict post-war trauma","A dramatic monologue centred on a single voice","A purely epistolary narrative composed of letters"]', 1, 'The narrative is non-linear, employing multiple perspectives to depict post-war trauma.', true, '2026-09-12 11:09:50.598', '2026-09-12 11:09:50.598', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2386fd26-cc38-4646-aec5-e2b6acf2e9b4', 'Economics', 'JAMB', null, 2026, null, 'Which of the following is NOT a source of government revenue?', null, '["Taxes, fees, licenses and fines","Grants, aids and borrowing","Interest, dividends, profits and earnings","Personal income, disposable income and transfer earnings"]', 3, 'Personal income, disposable income, and transfer earnings are not sources of government revenue.', true, '2026-09-12 10:58:49.788', '2026-09-12 10:58:49.788', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('239953c6-f843-4ccf-b1a4-f0860fed7cd6', 'Chemistry', 'JAMB', null, 2026, null, 'What mass of anhydrous sodium trioxocarbonate (IV) is present in 500cm³ of 0.1 mol/dm³ of its solution? (Na=23, C=12, O=16)', null, '["212g","106g","5.3g","10.6g"]', 2, 'Molar mass Na₂CO₃ = 106 g/mol. Moles = 0.1 × 0.5 = 0.05 mol. Mass = 0.05 × 106 = 5.3g.', true, '2026-09-12 11:36:20.196', '2026-09-12 11:36:20.196', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('239beba9-2fe2-490f-b6a9-ca8f9563141f', 'Physics', 'JAMB', null, 2026, null, 'The process where Alternating Current is converted to direct current is called', null, '["oscillation","Rectification","amplification","transformation","Inversion (Stepdown)"]', 1, 'The process where alternating current is converted to direct current is called rectification. This is achieved using devices called rectifiers, typically diodes. Oscillation is producing AC, amplification increases signal strength, and transformation changes voltage.', true, '2026-09-10 10:56:39.027', '2026-09-10 10:56:39.027', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('23a09270-0827-482e-8109-7d634f67fc0a', 'Physics', 'JAMB', null, 1992, null, 'A stone Q is thrown with velocity u at an angle of 75° to the horizontal. Another stone R is thrown with the same velocity u but at an angle of 15° to the horizontal. The ranges covered by the stones will be', null, '["Greater for Q","Greater for R","The same for Q and R","Greater for heavier of the stones"]', 2, 'Range = (u² sin 2θ)/g. sin 150° = sin 30°, so angles of 75° and 15° (complementary) give equal ranges.', true, '2026-10-12 19:15:34.963', '2026-10-12 19:15:34.963', null, null, null, 'A stone Q is thrown with velocity u at an angle of 75° to the horizontal. Another stone R is thrown with the same velocity u but at an angle of 15° to the horizontal. The ranges covered by the stones will be', '["Greater for Q","Greater for R","The same for Q and R","Greater for heavier of the stones"]', 'Range = (u<sup>2</sup> sin 2θ)/g. sin 150° = sin 30°, so angles of 75° and 15° (complementary) give equal ranges.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('23a4a875-cf4e-4a1d-bf90-b7b74845ed15', 'English Language', 'JAMB', null, 2024, null, 'If I went to the cinema I ______ early', null, '["would have returned","am returning","would return","had return","may return"]', 2, 'This is a second conditional sentence; "would return" is the correct form.', true, '2026-09-18 09:24:04.684', '2026-09-18 09:24:04.684', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('23adc9d6-0eb4-4452-9eca-3199dab4c68a', 'Economics', 'JAMB', null, 2026, null, 'Normative economics deals with', null, '["what is and not what should be","facts and not figures","fact and figures","value judgement"]', 3, 'Normative economics deals with value judgements. It is concerned with what ought to be, rather than what is. Normative statements are subjective and based on opinions, beliefs, and values. They cannot be tested or proven true or false. For example, ''The government should increase taxes on the rich'' is a normative statement. Positive economics deals with facts and what is.', true, '2026-09-10 10:42:56.094', '2026-09-10 10:42:56.094', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('23bd2203-3c5c-482e-a1f1-5c977ecbf9bd', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. They have tried to <u>circumvent</u> the restriction on the importation of the commodities.', null, '["bypass","confront","oppose","challenge"]', 0, 'Circumvent = bypass.', true, '2026-10-24 01:01:49.287', '2026-10-24 01:01:49.287', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. They have tried to <u>circumvent</u> the restriction on the importation of the commodities.', '["<u>bypass</u>","confront","oppose","challenge"]', '<b>Circumvent</b> = <b>bypass</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('23cd728d-de4d-47a1-8fdb-ab476e6fe50e', 'Physics', 'JAMB', null, 1983, null, 'Which of the following best describes the energy changes which take place when a steam engine drives a generator which lights a lamp?', null, '["Heat → Light → Sound → Kinetic","Kinetic → Light → Heat → Electricity","Heat → Kinetic → Electricity → Heat and Light","Electricity → Kinetic → Heat → Light","Heat → Sound → Kinetic → Electricity"]', 2, 'The steam engine converts heat to kinetic energy, the generator converts kinetic energy to electrical energy, and the lamp converts electrical energy to heat and light.', true, '2026-10-12 19:15:17.653', '2026-10-12 19:15:17.653', null, null, null, 'Which of the following best describes the energy changes which take place when a steam engine drives a generator which lights a lamp?', '["Heat → Light → Sound → Kinetic","Kinetic → Light → Heat → Electricity","Heat → Kinetic → Electricity → Heat and Light","Electricity → Kinetic → Heat → Light","Heat → Sound → Kinetic → Electricity"]', 'The steam engine converts heat to kinetic energy, the generator converts kinetic energy to electrical energy, and the lamp converts electrical energy to heat and light.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('23cf04d1-4a1e-4947-85f0-2b311c506fc7', 'Economics', 'JAMB', null, 2026, null, 'If an increase in the price of a commodity leads to an increase in total revenue, then it follows that the demand for the commodity is', null, '["normal","elastic","inelastic","abnormal","unitary"]', 2, 'If an increase in price leads to an increase in total revenue, demand is inelastic. When demand is inelastic (PED < 1), quantity demanded falls proportionately less than the price increase, so total revenue rises. If demand were elastic (PED > 1), a price increase would cause a proportionately larger fall in quantity demanded, reducing total revenue.', true, '2026-09-10 10:41:20.67', '2026-09-10 10:41:20.67', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('23ddd1cb-1a14-4596-acfb-68852f0cbea7', 'Chemistry', 'JAMB', null, 2026, null, 'The volume of oxygen required to burn completely, 1.12g of methane is?', null, '["4256cm³","1785cm³","2631cm³","3136cm³"]', 3, 'CH₄ + 2O₂ → CO₂ + 2H₂O. Moles CH₄ = 1.12/16 = 0.07 mol. Moles O₂ = 0.14 mol. Volume = 0.14 × 22400 = 3136 cm³.', true, '2026-09-12 11:36:21.541', '2026-09-12 11:36:21.541', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('23e6593d-2ca3-4083-865a-7705e6437a1d', 'Physics', 'JAMB', null, 1986, null, 'A gas occupies a volume of 300 cm³ at a temperature of 27 °C. What is its volume at 54 °C, when the pressure is constant?', null, '["150 cm³","273 cm³","327 cm³","600 cm³"]', 2, 'Charles'' law with Kelvin temperatures: V₂ = 300 x 327/300 = 327 cm³.', true, '2026-10-12 19:15:23.575', '2026-10-12 19:15:23.575', null, null, null, 'A gas occupies a volume of 300 cm<sup>3</sup> at a temperature of 27 °C. What is its volume at 54 °C, when the pressure is constant?', '["150 cm<sup>3</sup>","273 cm<sup>3</sup>","327 cm<sup>3</sup>","600 cm<sup>3</sup>"]', 'Charles'' law with Kelvin temperatures: V<sub>2</sub> = 300 x 327/300 = 327 cm<sup>3</sup>.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('23faa960-dab1-4b50-84c4-c248b7a71f24', 'Literature in English', 'JAMB', null, 2026, null, 'The sentence style is characterized by', null, '["long sentences","visual images","tactile image","short sentence"]', 3, 'The sentence style is characterized by short sentences.', true, '2026-09-12 11:14:04.532', '2026-09-12 11:14:04.532', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('24026a34-8621-4aec-a6f0-5148248d5a4d', 'Government', 'JAMB', null, 2026, null, 'Public Corporations are referred to as statutory bodies because they are established by', null, '["a legislative instrument","Acts of parliament","an executive instrument","Bye-laws"]', 1, 'Public corporations are established by Acts of parliament.', true, '2026-09-12 11:23:58.386', '2026-09-12 11:23:58.386', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2404db0d-1ccb-498f-89b4-71b7fa55b3d8', 'Biology', 'JAMB', null, 2026, null, 'The Malphigian corpuscle is made up of: I. Loop of Henle II. Collecting duct III. Bowman''s capsule IV. Glomerulus', null, '["I & II","I & III","III & IV","II & III","II & IV"]', 2, 'The Malpighian corpuscle (renal corpuscle) is the initial filtering component of the nephron and consists of two structures: Bowman''s capsule (III) and the glomerulus (IV). The glomerulus is a network of capillaries where blood is filtered. Bowman''s capsule is the cup-shaped structure that surrounds the glomerulus and collects the filtrate. The Loop of Henle (I) and collecting duct (II) are later parts of the nephron that function in concentration of urine after filtration. The Malpighian corpuscle is located in the renal cortex.', true, '2026-09-09 03:18:32.13', '2026-09-09 03:18:32.13', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('24066286-2145-44d2-baa9-c246d0e3ba73', 'General Mathematics', 'JAMB', null, 2026, null, 'If y is a whole number such that 3y + 4 ≡ 7 (mod 8). Find the value of y', null, '["1","2","3","4"]', 0, '3y + 4 ≡ 7 (mod 8). 3y ≡ 3 (mod 8). y ≡ 1 (mod 8). So y = 1.', true, '2026-09-12 11:43:40.602', '2026-09-12 11:43:40.602', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('24076b03-ad4f-4f70-9a54-448da3f6af51', 'Government', 'JAMB', null, 2026, null, 'What did the 1963 and the 1979 Constitutions of Nigeria have in common? I. They both employed Westminster System II. They both maintained republicanism III. They both had a president vested with real executive power IV. They both retained Presidential System', null, '["II only","I only","II&III","IV only"]', 0, 'Both constitutions maintained republicanism.', true, '2026-09-12 11:24:36.084', '2026-09-12 11:24:36.084', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('24090b61-96fa-46ab-9a5d-67222bcc6289', 'Physics', 'JAMB', null, 2000, null, 'A metal of mass 0.5 kg is heated to 100 °C and then transferred to a well-lagged calorimeter of heat capacity 80 J K⁻¹ containing water of heat capacity 420 J K⁻¹ at 15 °C. If the final steady temperature of the mixture is 25 °C, find the specific heat capacity of the metal.', null, '["92 J kg⁻¹ K⁻¹","133 J kg⁻¹ K⁻¹","286 J kg⁻¹ K⁻¹","887 J kg⁻¹ K⁻¹"]', 1, 'Heat gained = (80 + 420) x 10 = 5000 J. Heat lost = 0.5 x c x 75, so c = 5000/37.5 = 133 J kg⁻¹ K⁻¹.', true, '2026-10-12 19:15:49.642', '2026-10-12 19:15:49.642', null, null, null, 'A metal of mass 0.5 kg is heated to 100 °C and then transferred to a well-lagged calorimeter of heat capacity 80 J K<sup>-1</sup> containing water of heat capacity 420 J K<sup>-1</sup> at 15 °C. If the final steady temperature of the mixture is 25 °C, find the specific heat capacity of the metal.', '["92 J kg<sup>-1</sup> K<sup>-1</sup>","133 J kg<sup>-1</sup> K<sup>-1</sup>","286 J kg<sup>-1</sup> K<sup>-1</sup>","887 J kg<sup>-1</sup> K<sup>-1</sup>"]', 'Heat gained = (80 + 420) x 10 = 5000 J. Heat lost = 0.5 x c x 75, so c = 5000/37.5 = 133 J kg<sup>-1</sup> K<sup>-1</sup>.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('241daf2a-ec8e-44e1-a4f9-4f1fb88adc96', 'General Mathematics', 'JAMB', null, 2026, null, 'If 5²ˣ × 5³ʸ = 125 and 10ˣ × 10²ʸ = 1000, what is x - y?', null, '["2","0","-3","-6"]', 1, '5²ˣ⁺³ʸ = 5³. 2x+3y = 3. 10ˣ⁺²ʸ = 10³. x+2y = 3. Solving: x = -3, y = 3. x-y = -6. The answer is (D) -6.', true, '2026-09-12 11:43:49.374', '2026-09-12 11:43:49.374', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2427d908-c534-4315-afd5-b662a83534e6', 'Hausa', 'JAMB', null, 2009, null, 'Bayan wata uku, ata sake mu. Da muka huta kwana biyu, sai muka yi shirin zuwa kasashen Ris tare da shi, ya zama kuma abokina. Muna cikin tafiya a daji, sai wani mahaukacin rakumi, amale, ya biyo mu baki bud`e. muka sheka wurin wata itaciya muka hau. Shi kuwa, rakumin ya tsaya nan gindin itaciyar yana jira wai sai mun sauko, ya tasam mana. Muka rasa yadda za mu yi tun da safe har azahar, gas hi kuwa cikunanmu suna ta kiran ciorma. Can zuwa la''asar, sai nag a wad`ansu Fulani za su yawon sharo. Da dai na hange su kan hanya, sai na ce, ''Kai masu tafiya, uwaku!'' Ka san bafillace kan bakin rai, daga can kuwa sai suka nufo mu da gudu, wais u ji dalilin da ya san a zage su. Da dai rakumin nan ya kyalla ido ya gan su, bai sake komawa ta kanmu ba, sai ya cce dasu aka gama mu. Kowanne ya ranta, suka yi dawa! Mu kuwa muka sauka, muka yi tamu hanya. Ga mu nan sai Birnin Ris . Zurke na can yana kale-kalle, har nab ace masa. Ka ji rabuwata da shi. Na yi gaba, na shiga jirgi. Na nufi Alkama neman abin da ya rabo ni da gida, watau Ruwan Baganja. Da muka sauka a wani tsibiri don mu huta, sai na tafi yawon shan iska. Jirgi ya tshai, aka bar ni nan ni kad`ai! Bayan sun wuce, na tashi da tafiya, ina neman wani jirgi in bi su. Ina bin bakin teku, sai na tarar da wani mutum a zaune. Na dube shi da kyau, ashe dai Malam Zurke ne dan Muhammad. Da nag a haka sai n ace, ''Zurke d`an Muhammad!'' Sai ya amsa y ace, ''Himma dai d`an Shehu!'' Muka tafa. Y ace ''Wallahi, tun da ka zo na gane ka''. Muka ba juna labarin rabuwarmu. Wanne ne lafizin tsokanar da su Zurke suka yi wa Fulani?', null, '["''Zurke d`an Muhammad!''","''Himma dai d`an Shehu!''","''Kai masu tafiya, uwaku!''","''Kai Fulani, uwaku!''"]', 2, 'Lafizin tsokanar da suka yi wa Fulani shi ne ''Kai masu tafiya, uwaku!''', true, '2026-10-13 10:37:25.911', '2026-10-13 10:37:25.911', null, null, null, 'Bayan wata uku, ata sake mu. Da muka huta kwana biyu, sai muka yi shirin zuwa kasashen Ris tare da shi, ya zama kuma abokina. Muna cikin tafiya a daji, sai wani mahaukacin rakumi, amale, ya biyo mu baki bud`e. muka sheka wurin wata itaciya muka hau. Shi kuwa, rakumin ya tsaya nan gindin itaciyar yana jira wai sai mun sauko, ya tasam mana. Muka rasa yadda za mu yi tun da safe har azahar, gas hi kuwa cikunanmu suna ta kiran ciorma. Can zuwa la''asar, sai nag a wad`ansu Fulani za su yawon sharo. Da dai na hange su kan hanya, sai na ce, ''Kai masu tafiya, uwaku!'' Ka san bafillace kan bakin rai, daga can kuwa sai suka nufo mu da gudu, wais u ji dalilin da ya san a zage su. Da dai rakumin nan ya kyalla ido ya gan su, bai sake komawa ta kanmu ba, sai ya cce dasu aka gama mu. Kowanne ya ranta, suka yi dawa! Mu kuwa muka sauka, muka yi tamu hanya. Ga mu nan sai Birnin Ris . Zurke na can yana kale-kalle, har nab ace masa. Ka ji rabuwata da shi. Na yi gaba, na shiga jirgi. Na nufi Alkama neman abin da ya rabo ni da gida, watau Ruwan Baganja. Da muka sauka a wani tsibiri don mu huta, sai na tafi yawon shan iska. Jirgi ya tshai, aka bar ni nan ni kad`ai! Bayan sun wuce, na tashi da tafiya, ina neman wani jirgi in bi su. Ina bin bakin teku, sai na tarar da wani mutum a zaune. Na dube shi da kyau, ashe dai Malam Zurke ne dan Muhammad. Da nag a haka sai n ace, ''Zurke d`an Muhammad!'' Sai ya amsa y ace, ''Himma dai d`an Shehu!'' Muka tafa. Y ace ''Wallahi, tun da ka zo na gane ka''. Muka ba juna labarin rabuwarmu. Wanne ne lafizin tsokanar da su Zurke suka yi wa Fulani?', '["''Zurke d`an Muhammad!''","''Himma dai d`an Shehu!''","''Kai masu tafiya, uwaku!''","''Kai Fulani, uwaku!''"]', 'Lafizin tsokanar da suka yi wa Fulani shi ne ''Kai masu tafiya, uwaku!''', '{"bold":["''Kai masu tafiya, uwaku!''"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2442f1c2-fd85-4b68-9025-96525c50df5c', 'English Language', 'JAMB', null, 2024, null, 'For while on strike they are _7_ work and earn no wages.', null, '["out of","in","with","up to"]', 0, 'While on strike, they are out of work.', true, '2026-09-18 09:23:08.102', '2026-09-18 09:23:08.102', null, null, 'CLOZE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('244d70aa-4803-4fe5-aaf6-475fb13b3a57', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Moses asked Pharaoh to allow the Hebrews to depart from Egypt to', null, '["buy more food in the land of Canaan","fight the Jebusites","smite the Amorites","make a sacrifice to the Lord in the wilderness"]', 3, 'Moses asked Pharaoh to let the Hebrews go to sacrifice to the Lord in the wilderness.', true, '2026-09-12 10:41:12.636', '2026-09-12 10:41:12.636', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2460c711-7cf7-48e9-860f-9511a4be16f4', 'Physics', 'JAMB', null, 2004, null, 'The change in volume when 450 kg of ice is completely melted is [density of ice = 900 kg m⁻³, density of water = 1 000 kg m⁻³]', null, '["0.05 m³","0.45 m³","4.50 m³","0.50 m³"]', 0, 'Volume of ice = 450/900 = 0.50 m³. Volume of water = 450/1000 = 0.45 m³. The volume decreases by 0.05 m³.', true, '2026-10-12 19:15:59.677', '2026-10-12 19:15:59.677', null, null, null, 'The change in volume when 450 kg of ice is completely melted is [density of ice = 900 kg m<sup>-3</sup>, density of water = 1 000 kg m<sup>-3</sup>]', '["0.05 m<sup>3</sup>","0.45 m<sup>3</sup>","4.50 m<sup>3</sup>","0.50 m<sup>3</sup>"]', 'Volume of ice = 450/900 = 0.50 m<sup>3</sup>. Volume of water = 450/1000 = 0.45 m<sup>3</sup>. The volume decreases by 0.05 m<sup>3</sup>.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2461b235-0d93-4290-8ae7-783fa88e582a', 'Financial Accounting', 'UTME', null, 2003, null, 'Assuming that depreciation is charged on the addition of the year', 'https://res.cloudinary.com/kwi1uv0g/image/upload/v1791841260/questions/o0wuirbifovbzpkbcgtt.jpg', '["N111000","N280000","N289000","N340000"]', 2, 'Depreciation charged on the addition of the year is N289000.', true, '2026-10-12 21:59:59.732', '2026-10-12 21:59:59.732', null, null, null, 'Assuming that depreciation is charged on the addition of the year', '["N111000","N280000","<b>N289000</b>","N340000"]', 'Depreciation charged on the addition of the year is <b>N289000</b>.', '{"bold":["N289000"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2467e663-1485-435d-9a85-81a440295adb', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The <u>exhibition</u> was an eye opener to all.', null, '["display","style","examination","dispatch"]', 0, 'Exhibition = display.', true, '2026-10-24 01:04:10.955', '2026-10-24 01:04:10.955', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The <u>exhibition</u> was an eye opener to all.', '["<u>display</u>","style","examination","dispatch"]', '<b>Exhibition</b> = <b>display</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('246e2750-89d2-4949-8a13-24e033d75980', 'Physics', 'JAMB', null, 1986, null, 'A dentist obtains a linear magnification of 4 of a hole in a tooth by placing a concave mirror at a distance of 2.0 cm from the tooth. The radius of curvature of the mirror is', null, '["5.3 cm","3.2 cm","2.7 cm","1.6 cm."]', 0, 'The magnified image is virtual: v = -4u = -8 cm. 1/f = 1/u + 1/v = 1/2 - 1/8 = 3/8, so f = 2.67 cm and R = 2f = 5.3 cm.', true, '2026-10-12 19:15:23.842', '2026-10-12 19:15:23.842', null, null, null, 'A dentist obtains a linear magnification of 4 of a hole in a tooth by placing a concave mirror at a distance of 2.0 cm from the tooth. The radius of curvature of the mirror is', '["5.3 cm","3.2 cm","2.7 cm","1.6 cm."]', 'The magnified image is virtual: v = -4u = -8 cm. 1/f = 1/u + 1/v = 1/2 - 1/8 = 3/8, so f = 2.67 cm and R = 2f = 5.3 cm.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('247360be-6780-4452-be01-e37ea57b8cf6', 'Hausa', 'JAMB', null, 2011, null, 'Jigon labarin ''Kowa Ya Daka Rawar Wani'' na Magana Jari Ce na III na A. na Imam, ya yi daidai da ''kowa ya', null, '["Ji a Jikinsa","Tsaya Matsayinsa","Ji da Kansa","Shiga Taitayinsa.''"]', 1, 'Jigon labarin ya yi daidai da ''kowa ya tsaya matsayinsa''.', true, '2026-10-13 10:37:22.372', '2026-10-13 10:37:22.372', null, null, null, 'Jigon labarin ''Kowa Ya Daka Rawar Wani'' na Magana Jari Ce na III na A. na Imam, ya yi daidai da ''kowa ya', '["Ji a Jikinsa","Tsaya Matsayinsa","Ji da Kansa","Shiga Taitayinsa.''"]', 'Jigon labarin ya yi daidai da ''kowa ya tsaya matsayinsa''.', '{"bold":["kowa ya tsaya matsayinsa"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('24791421-aad0-4ba1-af0a-5393c87cbe1a', 'Physics', 'JAMB', null, 1992, null, 'The maximum permissible current through a galvanometer G of internal resistance 10 Ω is 0.05 A. A resistance R is used to convert G into a voltmeter with a maximum reading of 100 V. Find the value of R and how it is connected to G.', null, '["20,000 ohms in parallel","19,990 ohms in series","1,990 ohms in series","100 ohms in series"]', 2, 'Total resistance needed = 100/0.05 = 2000 Ω. Series resistor R = 2000 - 10 = 1,990 Ω.', true, '2026-10-12 19:15:36.627', '2026-10-12 19:15:36.627', null, null, null, 'The maximum permissible current through a galvanometer G of internal resistance 10 Ω is 0.05 A. A resistance R is used to convert G into a voltmeter with a maximum reading of 100 V. Find the value of R and how it is connected to G.', '["20,000 ohms in parallel","19,990 ohms in series","1,990 ohms in series","100 ohms in series"]', 'Total resistance needed = 100/0.05 = 2000 Ω. Series resistor R = 2000 - 10 = 1,990 Ω.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2479515a-470b-4e2d-97ad-63cb19f3e564', 'Literature in English', 'JAMB', null, 2026, null, '______ is otherwise referred to as blank verse', null, '["irregular meter","regular meter","meter","rhyme scheme"]', 0, 'Blank verse is also called irregular meter.', true, '2026-09-12 11:05:39.444', '2026-09-12 11:05:39.444', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2482cfc0-a0b7-45ab-8ebd-b1af3ea88c95', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). He <u>went through fire</u> before he qualified as a doctor.', null, '["had a fire accident","made a lot of fire","suffered a lot","underwent some purification","required a lot of fire"]', 2, '''Go through fire'' = suffer greatly.', true, '2026-10-24 01:04:14.492', '2026-10-24 01:04:14.492', null, null, null, '(Choose the most appropriate interpretation). He <u>went through fire</u> before he qualified as a doctor.', '["had a fire accident","made a lot of fire","<u>suffered a lot</u>","underwent some purification","required a lot of fire"]', '''<b>Go through fire</b>'' = <b>suffer greatly</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2485a4ab-2874-4718-968d-029910a5daa4', 'Physics', 'JAMB', null, 2003, null, 'A 2 000 W electric heater is used to heat a metal object of mass 5 kg initially at 10 °C. If a temperature rise of 30 °C is obtained after 10 min, the heat capacity of the material is', null, '["1.2 x 10⁴ J °C⁻¹","6.0 x 10⁴ J °C⁻¹","8.0 x 10³ J °C⁻¹","4.0 x 10⁴ J °C⁻¹"]', 3, 'Heat supplied = 2000 x 600 = 1.2 x 10⁶ J. Heat capacity = 1.2 x 10⁶/30 = 4.0 x 10⁴ J °C⁻¹.', true, '2026-10-12 19:15:56.041', '2026-10-12 19:15:56.041', null, null, null, 'A 2 000 W electric heater is used to heat a metal object of mass 5 kg initially at 10 °C. If a temperature rise of 30 °C is obtained after 10 min, the heat capacity of the material is', '["1.2 x 10<sup>4</sup> J °C<sup>-1</sup>","6.0 x 10<sup>4</sup> J °C<sup>-1</sup>","8.0 x 10<sup>3</sup> J °C<sup>-1</sup>","4.0 x 10<sup>4</sup> J °C<sup>-1</sup>"]', 'Heat supplied = 2000 x 600 = 1.2 x 10<sup>6</sup> J. Heat capacity = 1.2 x 10<sup>6</sup>/30 = 4.0 x 10<sup>4</sup> J °C<sup>-1</sup>.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2495966f-ee91-48b2-a46a-dcf32cfbe4ce', 'Literature in English', 'JAMB', null, 2026, null, 'A poem that expresses the poet''s feelings and emotions is called', null, '["lyric","narrative","epic","parody"]', 0, 'A poem that expresses the poet''s feelings and emotions is called a lyric. Lyric poetry is characterized by personal expression and emotional intensity. It is often short and musical. Narrative poetry tells a story, an epic is a long narrative poem, and a parody imitates another work for comic effect.', true, '2026-09-10 10:47:54.069', '2026-09-10 10:47:54.069', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('249b69c7-302e-4f03-b928-e47fdd85d55a', 'Biology', 'JAMB', null, 0, null, 'answer the question above ', 'https://res.cloudinary.com/kwi1uv0g/image/upload/v1791839349/questions/vccbz4alskiwpt04tuh2.jpg', '["a","b","c","d"]', 1, 'Part II points to a root hair, which provides a large surface area responsible for the absorption of water and mineral salts from the soil.', true, '2026-10-12 21:09:43.785', '2026-10-12 21:09:43.785', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('24a129e8-a86a-4174-97e2-f922ef7ad820', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. She said boxing is <u>in fact her pet aversion</u>.', null, '["something she likes very much","something she dislikes very much","a hobby she loves to pursue","one thing she can''t miss"]', 1, 'Pet aversion = something she dislikes very much.', true, '2026-10-24 01:04:01.138', '2026-10-24 01:04:01.138', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. She said boxing is <u>in fact her pet aversion</u>.', '["something she likes very much","<u>something she dislikes very much</u>","a hobby she loves to pursue","one thing she can''t miss"]', '<b>Pet aversion</b> = <b>something she dislikes very much</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('24ae2dde-351f-48c5-9b55-fa45881f8b80', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). As the wedding day approached, the bride began to <u>develop cold feet</u>.', null, '["fall sick","feel cold","be reluctant","become aggressive"]', 2, '''Cold feet'' = reluctance.', true, '2026-10-24 01:04:18.947', '2026-10-24 01:04:18.947', null, null, null, '(Choose the most appropriate interpretation). As the wedding day approached, the bride began to <u>develop cold feet</u>.', '["fall sick","feel cold","<u>be reluctant</u>","become aggressive"]', '''<b>Cold feet</b>'' = <b>reluctance</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('24b7c581-6dec-49be-8d74-5bef0b1f9a8a', 'Chemistry', 'JAMB', null, 2026, null, 'All the photochemical reaction except (I) CH₄ + Cl₂ → CH₃Cl + HCl (II) CO₂ + H₂O → C₆H₁₂O₆ + O₂ (III) H₂ + Cl₂ → HCl (IV) NaOH + HCl → NaCl + H₂O', null, '["I","II, IV","IV","none"]', 2, 'NaOH + HCl → NaCl + H₂O is not a photochemical reaction.', true, '2026-09-12 11:36:08.028', '2026-09-12 11:36:08.028', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('24c092af-6144-43d4-8edc-cf128d09b760', 'Physics', 'JAMB', null, 1999, null, 'In a series R-L-C circuit at resonance, the voltages across the resistor and the inductor are 30 V and 40 V respectively. What is the voltage across the capacitor?', null, '["30 V","40 V","50 V","70 V"]', 1, 'At resonance XL = XC, so the voltages across the inductor and the capacitor are equal: 40 V.', true, '2026-10-12 19:15:48.68', '2026-10-12 19:15:48.68', null, null, null, 'In a series R-L-C circuit at resonance, the voltages across the resistor and the inductor are 30 V and 40 V respectively. What is the voltage across the capacitor?', '["30 V","40 V","50 V","70 V"]', 'At resonance X<sub>L</sub> = X<sub>C</sub>, so the voltages across the inductor and the capacitor are equal: 40 V.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('24c93c73-a582-49a2-b010-6daea3f40752', 'Biology', 'JAMB', null, 2002, null, 'The animals that move by means of Flagella include', null, '["Chlamydomonas and Euglena","Planaria and Amoeba","Amoeba and Hydra","Paramecium and Planaria"]', 0, 'Chlamydomonas and Euglena move using flagella.', true, '2026-10-12 20:59:30.033', '2026-10-12 20:59:30.033', null, null, null, 'The animals that move by means of Flagella include', '["Chlamydomonas and Euglena","Planaria and Amoeba","Amoeba and Hydra","Paramecium and Planaria"]', 'Chlamydomonas and Euglena move using flagella.', '{"bold":["Chlamydomonas and Euglena"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('24cb5409-bb86-47db-9898-e9311908bddd', 'Physics', 'JAMB', null, 1984, null, 'The unit quantity of electricity is called', null, '["The ampere","The volt","The coulomb","The ammeter","Electromotive force."]', 2, 'The coulomb is the unit of electric charge (quantity of electricity); 1 C = 1 A s.', true, '2026-10-12 19:15:18.639', '2026-10-12 19:15:18.639', null, null, null, 'The unit quantity of electricity is called', '["The ampere","The volt","The coulomb","The ammeter","Electromotive force."]', 'The coulomb is the unit of electric charge (quantity of electricity); 1 C = 1 A s.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('24cbf089-0071-43ef-bc4d-6c5c30fe08ec', 'Literature in English', 'JAMB', null, 2026, null, 'Which of the following is NOT a theme in the poem?', null, '["post-colonial identity","the importance of preserving ancient myths","the cyclical nature of violence and suffering","environmental pollution"]', 1, 'The importance of preserving ancient myths is not a theme.', true, '2026-09-12 11:13:48.204', '2026-09-12 11:13:48.204', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('24cfa751-3837-47bf-9e9a-b28b87b1e11d', 'Biology', 'JAMB', null, 2026, null, 'An onion is a bulb because it', null, '["has adventitious roots","bears many buds at the nodes","has a tuberous stem","has a reduced stem and thick fleshy leaves"]', 3, 'A bulb is characterized by a reduced stem surrounded by fleshy, modified leaves (scales).', true, '2026-09-09 02:56:40.896', '2026-09-09 02:56:40.896', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('25157f8d-b6e7-49ba-9df6-409496ba6c99', 'Chemistry', 'JAMB', null, 2026, null, 'A metal common to brass and bronze is?', null, '["Aluminum","Copper","Nickel","Iron"]', 1, 'Copper is common to both brass and bronze.', true, '2026-09-12 11:36:25.022', '2026-09-12 11:36:25.022', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('251e27be-400f-4c65-9234-47416cfe6d72', 'Economics', 'JAMB', null, 2026, null, 'In a two-sector circular flow model, the factor services are provided by the', null, '["Firms and households","Households","Firms","Government","Foreign nations"]', 1, 'In a two-sector circular flow model, factor services are provided by households. Households own the factors of production (land, labour, capital, entrepreneurship) and provide them to firms. In return, households receive factor incomes (wages, rent, interest, profit). Firms produce goods and services and sell them to households.', true, '2026-09-10 10:41:21.367', '2026-09-10 10:41:21.367', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2523a70c-7a54-497c-bdd0-b8fc2171bba3', 'Chemistry', 'JAMB', null, 2026, null, 'What are the possible oxidation numbers for an element if its atomic number is 17?', null, '["-1 and 7","-1 and 6","-3 and 5","-2 and 6"]', 0, 'Chlorine (atomic number 17) has oxidation numbers -1 and +7.', true, '2026-09-12 11:36:22.923', '2026-09-12 11:36:22.923', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2540f20f-50a3-48b8-8142-9cc3f694de5e', 'Physics', 'JAMB', null, 2026, null, 'If the Nigeria flag (green, white, green) is viewed in pure yellow light, which of the following set of colours would be observed on the flag?', null, '["green, yellow, green","red, yellow, red","black, yellow, black","green, white, green"]', 2, 'In pure yellow light, the green parts of the flag will appear black because green objects absorb yellow light and reflect green. The white part will appear yellow because white reflects all colours including yellow. So the flag will appear black, yellow, black.', true, '2026-09-10 10:56:47.303', '2026-09-10 10:56:47.303', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('25541e7a-b68a-4646-8835-3454793ecef4', 'Yoruba', 'JAMB', null, 2007, null, 'Níbo ní ètò ìsèlú láàrin àwòn Yorùba ti bêrê?', null, '["Nínú ilé","Ní agboolé","Ní àdúgbò","Nínú ààfin"]', 0, 'Ètò ìsèlú láàrin àwòn Yorùba bêrê ní Nínú ilé.', true, '2026-10-13 13:23:32.829', '2026-10-13 13:23:32.829', null, null, null, 'Níbo ní ètò ìsèlú láàrin àwòn Yorùba ti bêrê?', '["Nínú ilé","Ní agboolé","Ní àdúgbò","Nínú ààfin"]', 'Ètò ìsèlú láàrin àwòn Yorùba bêrê ní Nínú ilé.', '{"bold":["Nínú ilé"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('25581cde-0761-4ca2-b696-0f0dba06c1e6', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Their strength is their <u>staggering capacity</u> to reproduce.', null, '["unstable multiplying power","unreliable attacking power","qualitative multiplying power","overwhelming multiplying power"]', 3, 'Staggering = overwhelming.', true, '2026-10-24 01:01:48.598', '2026-10-24 01:01:48.598', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Their strength is their <u>staggering capacity</u> to reproduce.', '["unstable multiplying power","unreliable attacking power","qualitative multiplying power","<u>overwhelming multiplying power</u>"]', '<b>Staggering</b> = <b>overwhelming</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('255d6382-083f-40ac-9a6c-e71fa70d9aae', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). The armed robbers who raided passengers on the Expressway <u>came to grief</u> when they had a shoot out with the police today.', null, '["came to a bad end","became grieved","encountered grief","came to a dead"]', 0, '''Came to grief'' = came to a bad end.', true, '2026-10-24 01:02:03.071', '2026-10-24 01:02:03.071', null, null, null, '(Choose the most appropriate interpretation). The armed robbers who raided passengers on the Expressway <u>came to grief</u> when they had a shoot out with the police today.', '["<u>came to a bad end</u>","became grieved","encountered grief","came to a dead"]', '''<b>Came to grief</b>'' = <b>came to a bad end</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('255e381c-2b5d-4f37-af1c-2739c847faec', 'Physics', 'JAMB', null, 1991, null, 'A body of weight W N rests on a smooth plane inclined at an angle θ to the horizontal. What is the resolved part of the weight in newtons along the plane?', null, '["W sin θ","W cos θ","W sec θ","W tan θ"]', 0, 'The component of the weight along the plane is W sin θ; the component perpendicular to the plane is W cos θ.', true, '2026-10-12 19:15:32.436', '2026-10-12 19:15:32.436', null, null, null, 'A body of weight W N rests on a smooth plane inclined at an angle θ to the horizontal. What is the resolved part of the weight in newtons along the plane?', '["W sin θ","W cos θ","W sec θ","W tan θ"]', 'The component of the weight along the plane is W sin θ; the component perpendicular to the plane is W cos θ.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('256d0831-9c0b-496a-8588-7a4d2de5eb20', 'Financial Accounting', 'UTME', null, 2002, null, 'In preparing the final accounts, the bad debt account is closed by a transfer to the', null, '["balance sheet","provision for bad debt account","profit and loss account","trading account"]', 2, 'In closing a bad debt account the amount is transferred to the profit and loss account as a charge against profit.', true, '2026-10-12 21:59:56.593', '2026-10-12 21:59:56.593', null, null, null, 'In preparing the final accounts, the bad debt account is closed by a transfer to the', '["balance sheet","provision for bad debt account","<b>profit and loss account</b>","trading account"]', 'In closing a bad debt account the amount is transferred to the <b>profit and loss account</b> as a charge against profit.', '{"bold":["profit and loss account"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2576ad68-46c8-4f05-9e40-f13f894c4b41', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). Amaka <u>would pass for a beauty queen</u>.', null, '["She would pass the drink to the queen who is sitting next to her","She would be accepted by all as a beauty queen","She walked past the beauty queen","She was acting as a beauty queen"]', 1, '''Pass for'' = be accepted as.', true, '2026-10-24 01:02:09.662', '2026-10-24 01:02:09.662', null, null, null, '(Choose the most appropriate interpretation). Amaka <u>would pass for a beauty queen</u>.', '["She would pass the drink to the queen who is sitting next to her","<u>She would be accepted by all as a beauty queen</u>","She walked past the beauty queen","She was acting as a beauty queen"]', '''<b>Pass for</b>'' = <b>be accepted as</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('258506ad-3d55-41ed-9748-d2a32fafbba3', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Herod’s expectation in receiving Jesus for a trial was to...', null, '["See signs from Jesus","Become a friend of Pilate","Set Jesus free","Punish Jesus"]', 0, 'Luke 23:8 explains that Herod Antipas was exceedingly glad to see Jesus because he had heard about Him and hoped to see some miracle/sign performed by Him.', true, '2026-09-09 17:18:24.218', '2026-09-09 17:18:24.218', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('258509cb-0565-4c32-9d48-edffc70b239f', 'Physics', 'JAMB', null, 1986, null, 'A man clapping his hands at regular intervals observes that the echo of a clap coincides with the next clap. If the reflecting cliff is 160 m away and the speed of sound is 320 m s⁻¹, what is the frequency of the clapping?', null, '["1 Hz","2 Hz","4 Hz","8 Hz."]', 0, 'Echo time = 2 x 160/320 = 1 s. Claps are 1 s apart, so the frequency is 1 Hz.', true, '2026-10-12 19:15:24.11', '2026-10-12 19:15:24.11', null, null, null, 'A man clapping his hands at regular intervals observes that the echo of a clap coincides with the next clap. If the reflecting cliff is 160 m away and the speed of sound is 320 m s<sup>-1</sup>, what is the frequency of the clapping?', '["1 Hz","2 Hz","4 Hz","8 Hz."]', 'Echo time = 2 x 160/320 = 1 s. Claps are 1 s apart, so the frequency is 1 Hz.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('25902fa0-6780-4087-987c-3e6c2a26e582', 'English Language', 'JAMB', null, 2007, null, 'I forgot to bring a pen with me. Would you please <u>__________</u> me yours?', null, '["borrow","loan","provide","lend"]', 3, 'Correct form: lend.', true, '2026-10-24 07:21:40.931', '2026-10-24 07:21:40.931', null, null, null, 'I forgot to bring a pen with me. Would you please <u>__________</u> me yours?', '["borrow","loan","provide","lend"]', 'Correct form: lend.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('25a35388-de43-4f84-8c12-8bfd1abffcb9', 'Government', 'JAMB', null, 2026, null, 'Which of the following is not a member of the ECOWAS?', null, '["Nigeria","Togo","Cameroun","Ghana"]', 2, 'Cameroun is not a member of ECOWAS.', true, '2026-09-12 11:24:26.541', '2026-09-12 11:24:26.541', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('25a4584e-7f80-4b3e-a45f-1330488cdbca', 'English Language', 'JAMB', null, 2024, null, 'A suitable title for the passage is', null, '["Knowing fatigue","Fatigue","Tiredness and fatigue","Body machine"]', 1, '"Fatigue" is the most suitable title as it is the central topic of the passage.', true, '2026-09-18 10:16:10.285', '2026-09-18 10:16:10.285', '02a05385-eb73-4b9c-9707-f8f4d3c6be8c', 1, 'COMPREHENSION', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('25c4d47d-88be-4bd1-b471-94b9dacf7193', 'Government', 'JAMB', null, 2026, null, 'The principle of collective responsibility applies to which of the following bodies?', null, '["Judiciary","Cabinet","Council of Chiefs","National Assembly"]', 1, 'Collective responsibility applies to the Cabinet.', true, '2026-09-12 11:24:49.129', '2026-09-12 11:24:49.129', null, null, null, null, null, null, null);
