insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('25cfe383-58d9-4d2f-857b-6a2cc392f533', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The player kept on <u>gamely</u> to the end of the match.', null, '["courageously","skillfully","amateurishly","stubbornly"]', 0, 'Gamely = courageously.', true, '2026-10-24 01:04:03.325', '2026-10-24 01:04:03.325', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The player kept on <u>gamely</u> to the end of the match.', '["<u>courageously</u>","skillfully","amateurishly","stubbornly"]', '<b>Gamely</b> = <b>courageously</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('25db44ae-29ab-4c32-8585-1010508cc9bd', 'Literature in English', 'JAMB', null, 2026, null, 'The livid and snarled waters roared and lapped / At the poor battered and weeping Yatch. The dominant literary device in the lines is', null, '["simile","alliteration","assonance","personification"]', 3, 'The dominant device is personification.', true, '2026-09-12 11:11:03.828', '2026-09-12 11:11:03.828', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('25deca98-45d0-4bfe-87ce-36739072f379', 'English Language', 'JAMB', null, 2007, null, 'Four persons accused of currency <u>__________</u> are being held by the security agents.', null, '["trafficking","traviking","trafficing","trafficking"]', 0, 'Correct spelling: trafficking (options A and D duplicated in source).', true, '2026-10-24 07:21:32.391', '2026-10-24 07:21:32.391', null, null, null, 'Four persons accused of currency <u>__________</u> are being held by the security agents.', '["trafficking","traviking","trafficing","trafficking"]', 'Correct spelling: trafficking (options A and D duplicated in source).', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('25e81a40-54f2-44de-b8c7-f016fe62fc49', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The cleaner resigned from his job which he said had become a <u>trivial</u> round.', null, '["unrewarding","too routine","rather degrading","unattractive"]', 1, 'A trivial round = too routine.', true, '2026-10-24 01:04:00.817', '2026-10-24 01:04:00.817', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The cleaner resigned from his job which he said had become a <u>trivial</u> round.', '["unrewarding","<u>too routine</u>","rather degrading","unattractive"]', 'A <b>trivial round</b> = <b>too routine</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('25f62b65-f962-4777-9da9-dacc484e1951', 'Economics', 'JAMB', null, 2026, null, 'A price floor is usually fixed;', null, '["Above the equilibrium and cause shortage","Below the equilibrium and cause surplus","Below the equilibrium and cause shortage","Above the equilibrium and cause surplus"]', 3, 'A price floor is set above equilibrium and causes a surplus.', true, '2026-09-12 11:02:11.323', '2026-09-12 11:02:11.323', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('25f8599e-2461-4257-a927-85c89282857b', 'testing', 'JAMB', null, 2024, null, 'The lecturer recommended that the student ..... course again.', null, '["takes","took","take","has taken"]', 1, 'Subjunctive after ''recommended that''.', true, '2026-10-31 16:48:52.834', '2026-10-31 16:48:52.834', null, null, null, 'The lecturer recommended that the student ..... course again.', '["takes","took","take","has taken"]', 'Subjunctive after ''recommended that''.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('25f91094-d646-402c-a71d-efe9c3abf653', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The <u>schism</u> in the organization is on the increase', null, '["disagreement","understanding","opportunity","rot"]', 0, 'Schism = disagreement.', true, '2026-10-24 01:04:11.92', '2026-10-24 01:04:11.92', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The <u>schism</u> in the organization is on the increase', '["<u>disagreement</u>","understanding","opportunity","rot"]', '<b>Schism</b> = <b>disagreement</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('25fa6911-8f03-4e32-b3c3-caa3a1cef426', 'Physics', 'JAMB', null, 2026, null, 'The bursting of water pipe during the cold weather, when the water in the pipe forms ice would be attributed to', null, '["contraction of water on freezing","expansion of water on freezing","expansion of ice on melting","contraction of pipe when cooled"]', 1, 'The bursting of water pipes during cold weather is attributed to the expansion of water on freezing. Water is anomalous—it expands when it freezes, unlike most substances. This expansion exerts pressure on the pipe walls, causing them to burst.', true, '2026-09-10 10:56:42.711', '2026-09-10 10:56:42.711', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('260b69c1-bfb4-4653-86c6-45a8a2a17688', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). Ijeoma <u>counted her chickens before they were hatched</u>. This means that Ijeoma ________________', null, '["regarded each egg as a chicken","hatched the eggs prematurely","assumed that her expectations had already been realized","protected her eggs from breaking","insured the eggs"]', 2, 'Assumed success prematurely.', true, '2026-10-24 01:04:12.794', '2026-10-24 01:04:12.794', null, null, null, '(Choose the most appropriate interpretation). Ijeoma <u>counted her chickens before they were hatched</u>. This means that Ijeoma ________________', '["regarded each egg as a chicken","hatched the eggs prematurely","<u>assumed that her expectations had already been realized</u>","protected her eggs from breaking","insured the eggs"]', 'Assumed <b>success prematurely</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('261b97b6-897f-4f18-9021-ceffaab0b41b', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'In the first creation account, the firmament was created on the', null, '["first day","second day","third day","fourth day"]', 1, 'According to Genesis 1, the firmament (heaven) was created on the second day.', true, '2026-09-12 10:40:50.662', '2026-09-12 10:40:50.662', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('261d3795-d2de-4dbc-b789-301f9b95b1b8', 'General Mathematics', 'JAMB', null, 2026, null, 'An arithmetic progression has first term 11 and fourth term 32. The sum of the first nine terms is', null, '["351","531","135","315","153"]', 3, 'a=11, a+3d=32. 3d=21. d=7. S9 = 9/2(2(11)+8(7)) = 9/2(22+56) = 9/2(78) = 351.', true, '2026-09-12 11:44:21.114', '2026-09-12 11:44:21.114', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('26202a56-af6d-4c1c-8938-04e617b60f66', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). The governor advised his people to <u>get off the beaten tracks</u> in their approach to community matters.', null, '["use the old roads","make the tracks better","find new ways","avoid beating about the bush"]', 2, '''Get off the beaten tracks'' = find new ways.', true, '2026-10-24 01:04:19.11', '2026-10-24 01:04:19.11', null, null, null, '(Choose the most appropriate interpretation). The governor advised his people to <u>get off the beaten tracks</u> in their approach to community matters.', '["use the old roads","make the tracks better","<u>find new ways</u>","avoid beating about the bush"]', '''<b>Get off the beaten tracks</b>'' = <b>find new ways</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2620cc47-eb39-4d68-803d-055f53d95474', 'General Mathematics', 'JAMB', null, 2026, null, 'Find the gradient of the line passing through the points P(1,1) and Q(2,5)', null, '["5","4","3","2"]', 1, '(5-1)/(2-1) = 4.', true, '2026-09-12 11:44:16.504', '2026-09-12 11:44:16.504', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('26289d95-968c-44cd-99d7-7ee40d7b14bf', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. She is <u>immune</u> to the flattery of young men.', null, '["resistant","susceptible","insensible","unresponsive"]', 1, 'Immune = resistant; opposite = susceptible.', true, '2026-10-24 07:21:18.972', '2026-10-24 07:21:18.972', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. She is <u>immune</u> to the flattery of young men.', '["resistant","susceptible","insensible","unresponsive"]', 'Immune = resistant; opposite = susceptible.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('26330e19-9a7c-40d9-b190-c8186eebfc4e', 'Government', 'JAMB', null, 2026, null, 'Nigeria joined OPEC in', null, '["1960","1975","1971","1963"]', 2, 'Nigeria joined OPEC in 1971.', true, '2026-09-12 11:24:05.392', '2026-09-12 11:24:05.392', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2646206f-d189-4307-b7bc-d1d2114c869d', 'General Mathematics', 'JAMB', null, 2026, null, 'In a class of 150 students, the sector in a pie chart representing the students offering physics has an angle of 12°. How many students are offering physics?', null, '["18","15","10","5"]', 3, '(12/360) × 150 = 5.', true, '2026-09-12 11:44:06.653', '2026-09-12 11:44:06.653', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('26463a60-c4f5-4b99-b066-7006f541f82e', 'Biology', 'JAMB', null, 2026, null, 'Which of the following is an adaptation for conserving water in plants?', null, '["broad leaves with hairs","leaves with sunken stomata and thin cuticle","leaves with sunken stomata and thick cuticle","reduced leaves with numerous stomata"]', 2, 'Leaves with sunken stomata and a thick cuticle are adaptations for conserving water in plants. Sunken stomata (stomata in pits or depressions) create a microclimate of higher humidity immediately above the stomata, reducing water loss. A thick cuticle provides a physical barrier to water loss. Broad leaves increase surface area and water loss (not conserving water). A thin cuticle is not water-conserving. Reduced leaves with numerous stomata would increase water loss. This combination of adaptations is common in xerophytes (desert plants).', true, '2026-09-09 03:18:47.671', '2026-09-09 03:18:47.671', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('264f0591-fb1a-4526-92bf-d3a69d7b00c7', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'In his teaching on partiality, James declares that mercy triumphs over', null, '["judgment","righteousness","grace","faith"]', 0, 'James says mercy triumphs over judgment.', true, '2026-09-12 10:41:41.143', '2026-09-12 10:41:41.143', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2657a4ed-48d2-4ac8-b07d-10fcb66ee378', 'Literature in English', 'JAMB', null, 2026, null, 'The poem is primarily a tribute to a person who has attained a significant milestone', null, '["marriage","birthday","graduation","promotion"]', 1, 'The poem is a tribute to a birthday milestone.', true, '2026-09-12 11:10:43.518', '2026-09-12 11:10:43.518', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2678bd91-5e17-4aee-b350-be73c56105fd', 'Literature in English', 'JAMB', null, 2026, null, 'Identify the device in: ''The crown will decide your fate.''', null, '["Synecdoche","Metonymy","Hyperbole","Irony"]', 1, 'Metonymy is used.', true, '2026-09-12 11:11:25.322', '2026-09-12 11:11:25.322', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('26896953-f7c1-4c71-a234-d38bce8445f3', 'Financial Accounting', 'UTME', null, 2003, null, 'Ezekiel Malgwi is a retailer. He recorded sales representing 95% cash and 5% credit. He took the total cash sales of N19 000 from the business tray and banked it. The credit sales for the period would be', null, '["N5 000","N1 900","N1 000","N950"]', 2, 'Cash sales 95% of Total sales. Cash sales 19000 (given). Total sales = 100/95 x 19000 = 20000. Credit sales = 20000 - 19000 = 1000.', true, '2026-10-12 21:59:59.435', '2026-10-12 21:59:59.435', null, null, null, 'Ezekiel Malgwi is a retailer. He recorded sales representing 95% cash and 5% credit. He took the total cash sales of N19 000 from the business tray and banked it. The credit sales for the period would be', '["N5 000","N1 900","<b>N1 000</b>","N950"]', 'Cash sales 95% of Total sales. Cash sales 19000 (given). Total sales = 100/95 x 19000 = 20000. Credit sales = 20000 - 19000 = <b>1000</b>.', '{"bold":["1000"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('268c685b-627a-4e13-8560-c6796548bca6', 'Yoruba', 'JAMB', null, 2007, null, 'Ilé-ayé ò jè nykan, Àlà lásán ni, Òkàn tó þ sùn ti dòkú, Nykan ò rí bí a ti rò ó Ilé-ayé gbçgè. Sàréè ì ýopin èdá. Eérú fún eérú, Eruku fún eruku, Lôba-òkè sô fênìyàn, Tó j’Òlörun nípè. Àmò hùwà bí çni pé, Ojoojúmò lèdá p súnmòlé. Màà gbèkèké òlá Màà nígbçkèlé nínú òrõ. Alágbára ayé, ç rõra ýe. Bí ó ti wù ká ki lòkàn tó, Kìkì ní í lù, Báa bá gbòlù ikú, Àtorin arò ti p kòjá lóde. Ojú ogun layé. Má bojú wèyìn, Jà bí akin lójù ìjà. Rántí ayé àkòni tó kòjà, Wo àwòkòyè wòn fún òjò òla tìrç. Gbé ìgbé-ayé alààyè, Jè kí òkú sunkún ara wòn. Àwé, má ronú mò, Jè ká máa ììyé lò. Máa jagun lò, Má wèyìn, Má ìyìè méjì, Bó pè, bó yá, Ayõ p bõ. Nibo ni òpin èdá?', null, '["Inú eérú","Inú eruku","Ödö Ölörun","Ilé ayé."]', 2, 'Òpin èdá wà ní Ödö Ölörun.', true, '2026-10-13 13:23:31.083', '2026-10-13 13:23:31.083', null, null, null, 'Ilé-ayé ò jè nykan, Àlà lásán ni, Òkàn tó þ sùn ti dòkú, Nykan ò rí bí a ti rò ó Ilé-ayé gbçgè. Sàréè ì ýopin èdá. Eérú fún eérú, Eruku fún eruku, Lôba-òkè sô fênìyàn, Tó j’Òlörun nípè. Àmò hùwà bí çni pé, Ojoojúmò lèdá p súnmòlé. Màà gbèkèké òlá Màà nígbçkèlé nínú òrõ. Alágbára ayé, ç rõra ýe. Bí ó ti wù ká ki lòkàn tó, Kìkì ní í lù, Báa bá gbòlù ikú, Àtorin arò ti p kòjá lóde. Ojú ogun layé. Má bojú wèyìn, Jà bí akin lójù ìjà. Rántí ayé àkòni tó kòjà, Wo àwòkòyè wòn fún òjò òla tìrç. Gbé ìgbé-ayé alààyè, Jè kí òkú sunkún ara wòn. Àwé, má ronú mò, Jè ká máa ììyé lò. Máa jagun lò, Má wèyìn, Má ìyìè méjì, Bó pè, bó yá, Ayõ p bõ. Nibo ni òpin èdá?', '["Inú eérú","Inú eruku","Ödö Ölörun","Ilé ayé."]', 'Òpin èdá wà ní Ödö Ölörun.', '{"bold":["Ödö Ölörun"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('268e9c63-89fa-416c-94d8-f6943f229d37', 'Literature in English', 'JAMB', null, 2026, null, 'The dominant figure of speech in the first stanza is', null, '["Hyperbole","Simile","Euphemism","Pun"]', 1, 'The dominant figure of speech is simile.', true, '2026-09-12 11:07:27.812', '2026-09-12 11:07:27.812', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('26a495ae-bf0b-4f5d-9586-e965c562b080', 'Government', 'JAMB', null, 2026, null, 'The transfer of certain powers and functions by means of constitutional and legislation process to the lowest levels of government is known as', null, '["delegation","devolution","deconcentration","decentralization"]', 1, 'Devolution is the transfer of powers to the lowest levels of government.', true, '2026-09-12 11:24:57.515', '2026-09-12 11:24:57.515', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('26b6fd93-f7b6-437d-8a46-59606a5f7f94', 'Physics', 'JAMB', null, 2026, null, 'The correct dimensions of pressure and density are', null, '["ML⁻¹T⁻², ML⁻³","ML⁻³, ML⁻¹T²","ML⁻², ML⁻¹T²","ML⁻¹T², ML²"]', 0, 'Pressure = Force/Area = MLT⁻²/L² = ML⁻¹T⁻². Density = Mass/Volume = M/L³ = ML⁻³.', true, '2026-09-10 10:56:47.196', '2026-09-10 10:56:47.196', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('26bd5590-e2ec-462d-a530-2c57bce4a9d0', 'English Language', 'JAMB', null, 2024, null, 'What is the major weakness of training students for specific technologies?', null, '["It trains students for only one type of career","It helps students to acquire money later when they are employed","It makes them anxious for a job in the market","It cannot help students to cope with the rapid changes in the world"]', 3, 'The passage states that specific training becomes obsolete quickly and cannot help students cope with rapid changes.', true, '2026-09-18 09:43:02.609', '2026-09-18 09:43:02.609', null, null, 'COMPREHENSION', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('26bdf3e3-bedd-4106-840f-3b8290760061', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Civil engineering is <u>predominantly</u> a male profession.', null, '["absolutely","essentially","generally","seldom"]', 3, 'Predominantly = mainly; opposite = seldom.', true, '2026-10-24 07:21:20.906', '2026-10-24 07:21:20.906', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Civil engineering is <u>predominantly</u> a male profession.', '["absolutely","essentially","generally","seldom"]', 'Predominantly = mainly; opposite = seldom.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('26c7e9ca-d381-47b0-a4e0-04ed35b4d102', 'English Language', 'JAMB', null, 2024, null, 'Compressing the air around them into what is called ______, or the blast wave.', null, '["Shock jocks","Shock therapy","Shock waves","Shock troops"]', 2, '"Shock waves" is the correct scientific term.', true, '2026-09-18 09:43:02.443', '2026-09-18 09:43:02.443', null, null, 'CLOZE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('26d03018-82ed-47fb-85de-0ff895d04e49', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. He went to the polls in defiance of sound advice and recorded <u>an abysmal</u> performance.', null, '["surprisingly good","disappointingly bad","mediocre","landslide"]', 1, 'Abysmal = disappointingly bad.', true, '2026-10-24 01:01:55.809', '2026-10-24 01:01:55.809', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. He went to the polls in defiance of sound advice and recorded <u>an abysmal</u> performance.', '["surprisingly good","<u>disappointingly bad</u>","mediocre","landslide"]', '<b>Abysmal</b> = <b>disappointingly bad</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('26d64123-6c67-4276-acda-e5018fce5838', 'Physics', 'JAMB', null, 1997, null, 'A body of mass 2 kg moving vertically upwards has its velocity increased uniformly from 10 m s⁻¹ to 40 m s⁻¹ in 4 s. Neglecting air resistance, calculate the upward vertical force acting on the body. [g = 10 m s⁻²]', null, '["15 N","20 N","35 N","45 N"]', 2, 'a = (40 - 10)/4 = 7.5 m s⁻². F - mg = ma, so F = 2(10 + 7.5) = 35 N.', true, '2026-10-12 19:15:42.868', '2026-10-12 19:15:42.868', null, null, null, 'A body of mass 2 kg moving vertically upwards has its velocity increased uniformly from 10 m s<sup>-1</sup> to 40 m s<sup>-1</sup> in 4 s. Neglecting air resistance, calculate the upward vertical force acting on the body. [g = 10 m s<sup>-2</sup>]', '["15 N","20 N","35 N","45 N"]', 'a = (40 - 10)/4 = 7.5 m s<sup>-2</sup>. F - mg = ma, so F = 2(10 + 7.5) = 35 N.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('26d97181-87c7-4650-abab-4dd1af9cba85', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. No wonder Sikemi later became a detective; she has been very <u>observant</u>.', null, '["inquisitive","inductive","curious","perceptive"]', 3, 'Observant = perceptive.', true, '2026-10-24 01:01:53.587', '2026-10-24 01:01:53.587', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. No wonder Sikemi later became a detective; she has been very <u>observant</u>.', '["inquisitive","inductive","curious","<u>perceptive</u>"]', '<b>Observant</b> = <b>perceptive</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('26e9f57a-50d2-4f8a-bae7-6534e415da0e', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'In Romans, believers are taught to obey those in authority because rulers are representative of...', null, '["the prophets","the kingdom","God","the people"]', 2, 'Romans 13:1-2 teaches that all authority comes from God and governing ministers are servants/representatives of God.', true, '2026-09-09 17:18:27.549', '2026-09-09 17:18:27.549', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('270757a3-32e6-4175-a1fb-9c4f88d07fe7', 'Government', 'JAMB', null, 2026, null, 'Which of the following is NOT a founding member of OPEC? I. Venezuela II. Saudi Arabia III. United States IV. United Kingdom V. Iraq', null, '["None","III&V","II&IV","III&IV"]', 3, 'The United States and United Kingdom are not founding members of OPEC.', true, '2026-09-12 11:24:37.508', '2026-09-12 11:24:37.508', null, null, null, null, null, null, null);
