insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('278ac28b-c6ef-4e0f-a816-d2aa79d4ab48', 'Physics', 'JAMB', null, 2026, null, 'The slope of the straight line displacement-time graph indicates', null, '["distance traveled","uniform velocity","uniform acceleration","uniform speed"]', 1, 'The slope of a displacement-time graph indicates velocity. A straight line indicates uniform (constant) velocity.', true, '2026-09-10 10:56:47.939', '2026-09-10 10:56:47.939', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('278e7d60-e331-4f09-8123-f6a5e33dd001', 'General Mathematics', 'JAMB', null, 2026, null, 'If log₈₁y = 3/4, find y', null, '["27","9","63","162"]', 0, 'log₈₁y = 3/4 means 81^(3/4) = y. 81 = 3⁴, so 81^(3/4) = (3⁴)^(3/4) = 3³ = 27. So y = 27.', true, '2026-09-10 10:48:19.54', '2026-09-10 10:48:19.54', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('27936d7d-6711-4c7c-842e-73e3e7d49c72', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. He <u>detests</u> honesty', null, '["likes","hates","encourages","commands"]', 1, 'Detests = hates.', true, '2026-10-24 01:04:12.027', '2026-10-24 01:04:12.027', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. He <u>detests</u> honesty', '["likes","<u>hates</u>","encourages","commands"]', '<b>Detests</b> = <b>hates</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('27970bdc-c16b-4c2a-8ee0-4487b676b860', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. His story gave us <u>an inkling</u> of what he passed through during the strike.', null, '["a possible idea","a summary","a taste","the right view"]', 0, 'Inkling = possible idea.', true, '2026-10-24 01:01:55.491', '2026-10-24 01:01:55.491', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. His story gave us <u>an inkling</u> of what he passed through during the strike.', '["<u>a possible idea</u>","a summary","a taste","the right view"]', '<b>Inkling</b> = <b>a possible idea</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('279a2899-2096-4830-8cb1-518f2060af1f', 'Physics', 'JAMB', null, 2026, null, 'Mercury is a suitable barometer fluid because it', null, '["expands uniformly","is opaque","is several times denser","is a good conductor of heat"]', 2, 'Mercury is a suitable barometer fluid because it is several times denser than water. Its high density means a relatively short column (about 760mm) is needed to balance atmospheric pressure. Water would require a column over 10 meters tall.', true, '2026-09-10 10:56:41.573', '2026-09-10 10:56:41.573', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('279b7f77-4890-4f1a-b1f9-49e5434962a3', 'Hausa', 'JAMB', null, 2011, null, 'Labarun cikin Magana Jari ce na III na A. Imam, an shirya su ne bisa salon', null, '["ji ka Karu","karba – karba","koyi da kanka","zaƙi da kanka."]', 0, 'An shirya labarun ne bisa salon ji ka karu.', true, '2026-10-13 10:37:22.427', '2026-10-13 10:37:22.427', null, null, null, 'Labarun cikin Magana Jari ce na III na A. Imam, an shirya su ne bisa salon', '["ji ka Karu","karba – karba","koyi da kanka","zaƙi da kanka."]', 'An shirya labarun ne bisa salon ji ka karu.', '{"bold":["ji ka karu"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('27a3cc95-1328-4516-b8d5-09a2b2ac5d49', 'Physics', 'JAMB', null, 1990, null, 'Which of the following is a fundamental unit?', null, '["Newton","Watt","Joule","Second"]', 3, 'The second is a base SI unit. The newton, watt and joule are derived units.', true, '2026-10-12 19:15:30.333', '2026-10-12 19:15:30.333', null, null, null, 'Which of the following is a fundamental unit?', '["Newton","Watt","Joule","Second"]', 'The second is a base SI unit. The newton, watt and joule are derived units.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('27aa7f32-079e-4563-93fb-8b1e281d4f7f', 'Government', 'JAMB', null, 2026, null, 'NEPAD was adopted during the OAU summit held in', null, '["Cairo","Tunis","Abuja","Lusaka"]', 3, 'NEPAD was adopted during the OAU summit in Lusaka.', true, '2026-09-12 11:24:42.79', '2026-09-12 11:24:42.79', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('27c114e2-330b-4586-855a-1b9c7e57b8d2', 'Chemistry', 'JAMB', null, 2026, null, 'Which of the following is used to test the purity of a substance? (I) Melting point (II) Density (III) Solubility (IV) Boiling point (V) Chromatography', null, '["I, II, III, IV, V","I, II, IV, V","I, II, IV, V","I, II, III, IV"]', 1, 'Melting point, density, boiling point, and chromatography are used to test purity.', true, '2026-09-12 11:36:06.451', '2026-09-12 11:36:06.451', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('27cc7ef8-2168-4a54-91a2-df94a037f1aa', 'Physics', 'JAMB', null, 2003, null, 'The force on a charge moving with velocity v in a magnetic field B is half of the maximum force when the angle between v and B is', null, '["0°","90°","45°","30°"]', 3, 'F = Fmax sin θ. For F = ½Fmax, sin θ = 0.5, so θ = 30°.', true, '2026-10-12 19:15:58.069', '2026-10-12 19:15:58.069', null, null, null, 'The force on a charge moving with velocity v in a magnetic field B is half of the maximum force when the angle between v and B is', '["0°","90°","45°","30°"]', 'F = F<sub>max</sub> sin θ. For F = ½F<sub>max</sub>, sin θ = 0.5, so θ = 30°.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('27dc4df5-20dd-4d17-bcfc-7c387372b3c3', 'Physics', 'JAMB', null, 1995, null, 'A quantity of ice at -10 °C is heated until the temperature of the heating vessel is 90 °C. Which of the following constants is NOT required?', null, '["Specific heat capacity of ice","Specific heat capacity of water","Specific latent heat of fusion","Specific latent heat of vaporization."]', 3, 'The water never reaches 100 °C, so it does not boil and the latent heat of vaporization is not needed.', true, '2026-10-12 19:15:41.416', '2026-10-12 19:15:41.416', null, null, null, 'A quantity of ice at -10 °C is heated until the temperature of the heating vessel is 90 °C. Which of the following constants is <b>NOT</b> required?', '["Specific heat capacity of ice","Specific heat capacity of water","Specific latent heat of fusion","Specific latent heat of vaporization."]', 'The water never reaches 100 °C, so it does not boil and the latent heat of vaporization is not needed.', '{"bold":["NOT"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('27de072a-98f8-4e87-9c69-418d6cfab892', 'Literature in English', 'JAMB', null, 2026, null, 'The primary cause of Chanticleer''s near fatal encounter with the fox in The Nun''s Priest Tale is his susceptibility to', null, '["destiny","gluttony","flattery","love"]', 2, 'The primary cause of Chanticleer''s near-fatal encounter with the fox in ''The Nun''s Priest Tale'' is his susceptibility to flattery. The fox flatters Chanticleer by praising his singing voice, and Chanticleer, pleased by the praise, closes his eyes to sing, allowing the fox to seize him. The tale illustrates the danger of pride and flattery. Destiny, gluttony, and love are not the primary cause.', true, '2026-09-10 10:47:54.659', '2026-09-10 10:47:54.659', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('27f2c675-9c9b-4d34-ab70-33012f745356', 'Biology', 'JAMB', null, 2026, null, 'Which of the following theories was NOT considered by Darwin in his evolutionary theory?', null, '["variation","survival of the fittest","use and disuse","competition"]', 2, 'The ''use and disuse'' theory was NOT part of Darwin''s evolutionary theory; it was proposed by Lamarck. Darwin''s theory included variation (inherited differences), survival of the fittest (natural selection), and competition (struggle for existence). Darwin''s theory was based on: 1) variation exists in populations, 2) some variations are inherited, 3) there is a struggle for existence, and 4) favorable variations are preserved (natural selection). Lamarck''s use and disuse concept is not supported by modern genetics as heritable changes require genetic mutations.', true, '2026-09-09 03:18:54.764', '2026-09-09 03:18:54.764', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('27ffb24b-6300-4e93-a799-b52aa73cd73c', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. What he received from the visitor was <u>invaluable</u>.', null, '["priceless","worthless","valueless","costly"]', 0, 'Invaluable = priceless.', true, '2026-10-24 01:01:45.578', '2026-10-24 01:01:45.578', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. What he received from the visitor was <u>invaluable</u>.', '["<u>priceless</u>","worthless","valueless","costly"]', '<b>Invaluable</b> = <b>priceless</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('28084dae-742f-4dd1-8267-5668d5d87d79', 'English Language', 'JAMB', null, 2024, null, '32', null, '["breakdown","crushing","production","release"]', 0, 'The liver is involved in the breakdown of red blood cells.', true, '2026-09-18 10:17:48.933', '2026-09-18 10:17:48.933', '5c9f355e-7680-453e-a8bf-38eba91547e7', 8, 'CLOZE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('281e80d3-4723-44c2-95bc-dba9608cb31f', 'Physics', 'JAMB', null, 1999, null, 'At what frequency would a 10 H inductor have a reactance of 2000 ohms?', null, '["π/200 Hz","π/100 Hz","100/π Hz","100π Hz"]', 2, 'XL = 2πfL, so f = 2000/(2π x 10) = 100/π Hz.', true, '2026-10-12 19:15:48.358', '2026-10-12 19:15:48.358', null, null, null, 'At what frequency would a 10 H inductor have a reactance of 2000 ohms?', '["π/200 Hz","π/100 Hz","100/π Hz","100π Hz"]', 'X<sub>L</sub> = 2πfL, so f = 2000/(2π x 10) = 100/π Hz.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('282f5317-9eab-44a0-b500-f1a0a71079bd', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). Thousands of students <u>are candidates for</u> the examination but only very few pass.', null, '["come into","call for","go into","enter for","turn up for"]', 3, '''Enter for'' = register as candidate.', true, '2026-10-24 01:02:01.423', '2026-10-24 01:02:01.423', null, null, null, '(Choose the most appropriate interpretation). Thousands of students <u>are candidates for</u> the examination but only very few pass.', '["come into","call for","go into","<u>enter for</u>","turn up for"]', '''<b>Enter for</b>'' = <b>register as candidate</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('283252ef-9b31-49c6-9b49-4d5c62d02731', 'English Language', 'JAMB', null, 2024, null, 'When you ______ an opponent''s point in a debate, you must do so politely.', null, '["refute","rebuke","reject","refuse"]', 0, '"Refute" means to prove a statement or argument to be wrong.', true, '2026-09-18 09:23:08.539', '2026-09-18 09:23:08.539', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('28381560-3d21-4767-bb86-4266192693d5', 'Physics', 'JAMB', null, 1995, null, 'A 12-V battery has an internal resistance of 0.5 Ω. If a cable of 1.0 Ω resistance is connected across the two terminals of the battery, the current drawn from the battery is', null, '["16.0 A","8.0 A","0.8 A","0.4 A"]', 1, 'I = E/(R + r) = 12/(1.0 + 0.5) = 8.0 A.', true, '2026-10-12 19:15:42.165', '2026-10-12 19:15:42.165', null, null, null, 'A 12-V battery has an internal resistance of 0.5 Ω. If a cable of 1.0 Ω resistance is connected across the two terminals of the battery, the current drawn from the battery is', '["16.0 A","8.0 A","0.8 A","0.4 A"]', 'I = E/(R + r) = 12/(1.0 + 0.5) = 8.0 A.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2843505d-da23-49f6-9330-e9af5368f68e', 'Financial Accounting', 'UTME', null, 2002, null, 'I. Fixtures account II. Machinery account III. Wages account IV. Rent account. Which of the above are nominal accounts?', null, '["III and IV","I and II","I and III","II and III"]', 0, 'Nominal accounts are accounts of intangible assets, expenses and revenue accounts. Wages and rent accounts are expenses accounts.', true, '2026-10-12 21:59:56.99', '2026-10-12 21:59:56.99', null, null, null, 'I. Fixtures account II. Machinery account III. Wages account IV. Rent account. Which of the above are nominal accounts?', '["<b>III and IV</b>","I and II","I and III","II and III"]', 'Nominal accounts are accounts of intangible assets, expenses and revenue accounts. <b>Wages and rent accounts</b> are expenses accounts.', '{"bold":["III and IV"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2845fbc2-3cd8-419e-bb67-1234f19e0293', 'General Mathematics', 'JAMB', null, 2026, null, 'How many sides has a regular polygon whose interior angle is 135° each?', null, '["12","10","9","8"]', 3, 'Interior angle = 135°. Exterior angle = 180 - 135 = 45°. Number of sides = 360/45 = 8.', true, '2026-09-10 10:48:18.847', '2026-09-10 10:48:18.847', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('28490627-d5af-43db-b106-be19931e9ab6', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Practising medicine is not as lucrative as many people <u>think</u>.', null, '["know","assume","consider","understand"]', 1, 'Think = assume.', true, '2026-10-24 01:01:51.399', '2026-10-24 01:01:51.399', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Practising medicine is not as lucrative as many people <u>think</u>.', '["know","<u>assume</u>","consider","understand"]', '<b>Think</b> = <b>assume</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('285ee4a1-5c0a-4ea7-b0a1-de35054fb0cb', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. My spell in the university was <u>an unmitigated</u> disaster.', null, '["an unavoidable","a painful","a regrettable","an unquantified","an unfortunate"]', 4, 'Unmitigated disaster = unfortunate.', true, '2026-10-24 01:03:54.136', '2026-10-24 01:03:54.136', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. My spell in the university was <u>an unmitigated</u> disaster.', '["an unavoidable","a painful","a regrettable","an unquantified","<u>an unfortunate</u>"]', '<b>Unmitigated disaster</b> = <b>unfortunate</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2864c807-6d02-46de-b343-6560436106bc', 'Literature in English', 'JAMB', null, 2026, null, 'The dominant tone of the poem is', null, '["nostalgic and reflective","angry and violent","humorous and playful","satirical and mocking"]', 0, 'The dominant tone is nostalgic and reflective.', true, '2026-09-12 11:05:46.515', '2026-09-12 11:05:46.515', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('28727b92-6b47-436b-b498-d81242518fe9', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). At that point, the <u>speaker went off at a tangent</u>.', null, '["started to run away like a mad person","took a lashing out at the audience","began to discuss unrelated matters","chose to recall previous decision"]', 2, '''Went off at a tangent'' = digressed to unrelated matters.', true, '2026-10-24 01:02:07.275', '2026-10-24 01:02:07.275', null, null, null, '(Choose the most appropriate interpretation). At that point, the <u>speaker went off at a tangent</u>.', '["started to run away like a mad person","took a lashing out at the audience","<u>began to discuss unrelated matters</u>","chose to recall previous decision"]', '''<b>Went off at a tangent</b>'' = <b>digressed to unrelated matters</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('28769513-b826-49b4-befc-e8c22fa498a7', 'Biology', 'JAMB', null, 2003, null, 'The dark reaction of photosynthesis involves the', null, '["reduction of carbon (IV) oxide to organic compounds","release of oxygen and the splitting of water","photolysis of water and the production of starch","splitting of water into hydrogen ions"]', 0, 'The dark reaction involves reduction of carbon dioxide to organic compounds.', true, '2026-10-12 20:59:32.623', '2026-10-12 20:59:32.623', null, null, null, 'The dark reaction of photosynthesis involves the', '["reduction of carbon (IV) oxide to organic compounds","release of oxygen and the splitting of water","photolysis of water and the production of starch","splitting of water into hydrogen ions"]', 'The dark reaction involves reduction of carbon dioxide to organic compounds.', '{"bold":["reduction of carbon dioxide to organic compounds"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('287b8020-c48e-4bdb-b834-66ce694c593e', 'Physics', 'JAMB', null, 2026, null, 'A ray of light which strikes a glass slab from air at normal incidence passes through the slab', null, '["undeviated and displaced at a faster speed","undeviated and undisplaced at a lower speed","deviated and undisplaced at a lower speed","deviated and displaced at a lower speed"]', 1, 'A ray of light striking a glass slab at normal incidence passes through undeviated and undisplaced at a lower speed. At normal incidence, there is no refraction (no deviation). The speed of light is lower in glass than in air.', true, '2026-09-10 10:56:46.654', '2026-09-10 10:56:46.654', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('287f4c9a-66e2-4090-af30-d27ec846535a', 'English Language', 'JAMB', null, 2007, null, 'It was difficult to <u>__________</u> a man walking on the moon two centuries ago.', null, '["contrive","perceive","conceive","imagine"]', 2, 'Correct spelling: conceive.', true, '2026-10-24 07:21:33.301', '2026-10-24 07:21:33.301', null, null, null, 'It was difficult to <u>__________</u> a man walking on the moon two centuries ago.', '["contrive","perceive","conceive","imagine"]', 'Correct spelling: conceive.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('288a4f37-c55c-4336-abb2-69dc25093f55', 'Chemistry', 'JAMB', null, 2026, null, 'Which of the following is arranged in order of increasing electronegativity', null, '["Cl, Al, Mg, P, Na","Na, Mg, Al, P, Cl","Cl, P, Al, Mg, Na","Na, Cl, P, Mg, Al"]', 1, 'Na < Mg < Al < P < Cl is the order of increasing electronegativity.', true, '2026-09-12 11:36:03.812', '2026-09-12 11:36:03.812', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('288c5915-dfb7-4147-a97f-20c7e0c308ce', 'Physics', 'JAMB', null, 1986, null, 'Which of the following is stored by a dry Leclanché cell?', null, '["Electrical power","Kinetic energy","Electric current","Chemical energy."]', 3, 'A cell stores chemical energy, which it converts to electrical energy when a circuit is completed.', true, '2026-10-12 19:15:24.27', '2026-10-12 19:15:24.27', null, null, null, 'Which of the following is stored by a dry Leclanché cell?', '["Electrical power","Kinetic energy","Electric current","Chemical energy."]', 'A cell stores chemical energy, which it converts to electrical energy when a circuit is completed.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('28a95f52-2d80-4824-99b9-ea33e0895601', 'Physics', 'JAMB', null, 1992, null, 'If a plastic sphere floats in water (density = 1000 kg m⁻³) with 0.5 of its volume submerged and floats in oil with 0.4 of its volume submerged, the density of the oil is', null, '["800 kg m⁻³","1 200 kg m⁻³","1 250 kg m⁻³","2 000 kg m⁻³"]', 2, 'The sphere''s density = 0.5 x 1000 = 500 kg m⁻³. In oil 0.4 x ρoil = 500, so ρoil = 1 250 kg m⁻³.', true, '2026-10-12 19:15:35.177', '2026-10-12 19:15:35.177', null, null, null, 'If a plastic sphere floats in water (density = 1000 kg m<sup>-3</sup>) with 0.5 of its volume submerged and floats in oil with 0.4 of its volume submerged, the density of the oil is', '["800 kg m<sup>-3</sup>","1 200 kg m<sup>-3</sup>","1 250 kg m<sup>-3</sup>","2 000 kg m<sup>-3</sup>"]', 'The sphere''s density = 0.5 x 1000 = 500 kg m<sup>-3</sup>. In oil 0.4 x ρ<sub>oil</sub> = 500, so ρ<sub>oil</sub> = 1 250 kg m<sup>-3</sup>.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('28a996fd-f2c8-472f-880c-44c371d79099', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The manager described Mfon as a man of <u>vehement character</u>.', null, '["clever and helpful","troublesome and noisy","weak and uninterested","strong and insistent"]', 3, 'Vehement = strong and insistent.', true, '2026-10-24 01:01:53.957', '2026-10-24 01:01:53.957', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The manager described Mfon as a man of <u>vehement character</u>.', '["clever and helpful","troublesome and noisy","weak and uninterested","<u>strong and insistent</u>"]', '<b>Vehement</b> = <b>strong and insistent</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('28ae5449-f431-4904-82a4-8369598d4753', 'Literature in English', 'JAMB', null, 2026, null, 'Through the ills of society are criticized with the objective of having them corrected are', null, '["comic relief","satire","farce","dramatic irony"]', 1, 'Satire criticizes societal ills for correction.', true, '2026-09-12 11:11:05.354', '2026-09-12 11:11:05.354', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('28b6d969-4dda-4c8e-bbb5-bfa1eb046af4', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Mary complained that she slept on the <u>coarse</u> floor.', null, '["smooth","rough","bad","harsh"]', 0, 'Coarse = rough; opposite = smooth.', true, '2026-10-24 07:21:11.369', '2026-10-24 07:21:11.369', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Mary complained that she slept on the <u>coarse</u> floor.', '["smooth","rough","bad","harsh"]', 'Coarse = rough; opposite = smooth.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('28cadc7b-6359-40bc-bdde-720d6556edc4', 'Chemistry', 'JAMB', null, 2026, null, 'Which of the following reactions is correct?', null, '["C6H5COOH + CaO → C6H5Ca + HCO3","C6H5COOH + CaO → C6H6 + CaCO3","C6H5COOH + PCl5 → C6H5Cl + H2PO4","C6H5COOH + C2H5OH → C6H6 + C3H8COOH"]', 1, 'Decarboxylation of benzoic acid using soda lime (CaO/NaOH) yields benzene (C6H6) and calcium carbonate (CaCO3).', true, '2026-09-09 17:12:46.947', '2026-09-09 17:12:46.947', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('28d4e59d-d085-444e-96d8-eb55af929e84', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The President can afford to dispense with some of his <u>henchmen</u>.', null, '["advisers","detractors","body guards","sycophants"]', 1, 'Henchmen = loyal supporters; opposite = detractors.', true, '2026-10-24 07:21:25.332', '2026-10-24 07:21:25.332', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The President can afford to dispense with some of his <u>henchmen</u>.', '["advisers","detractors","body guards","sycophants"]', 'Henchmen = loyal supporters; opposite = detractors.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('28d76041-c84d-4ab1-a9ba-a60c1fccff49', 'Biology', 'JAMB', null, 2026, null, 'The term "Thallophyta" refers to', null, '["Ferns and mosses","Algae and fungi","Mosses and liverworts","Fungi and ferns"]', 1, 'Thallophyta is a traditional division that includes plants with a thallus body structure that is not differentiated into true roots, stems, and leaves. This group includes algae and fungi. Algae are photosynthetic thallophytes, while fungi are non-photosynthetic thallophytes. Ferns and mosses (Bryophyta) are not thallophytes because they have differentiated structures, even though mosses lack vascular tissue. Liverworts and mosses belong to Bryophyta. Fungi and ferns do not belong together in a single group.', true, '2026-09-09 03:18:23.44', '2026-09-09 03:18:23.44', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('28dabbae-113c-4fa3-83c8-881647c5fdbe', 'Yoruba', 'JAMB', null, 2002, null, '‘Owó tí mo ya tán’ Irú awé-gbólóhùn wo ní tí mo ya?', null, '["Aÿàlàyé","Aÿàpèjùwe","Aÿòyìkà","Aláfìbò."]', 1, 'Irú awé-gbólóhùn tí mo ya ni Aÿàpèjùwe.', true, '2026-10-13 13:22:38.578', '2026-10-13 13:22:38.578', null, null, null, '‘Owó tí mo ya tán’ Irú awé-gbólóhùn wo ní tí mo ya?', '["Aÿàlàyé","Aÿàpèjùwe","Aÿòyìkà","Aláfìbò."]', 'Irú awé-gbólóhùn tí mo ya ni Aÿàpèjùwe.', '{"bold":["Aÿàpèjùwe"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('28df3a52-f7da-45c9-b8f6-cef41d7eb1da', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Everybody complained of a <u>lean</u> harvest last year.', null, '["surplus","abundant","poor","thin"]', 2, 'Lean harvest = poor harvest.', true, '2026-10-24 01:03:58.673', '2026-10-24 01:03:58.673', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Everybody complained of a <u>lean</u> harvest last year.', '["surplus","abundant","<u>poor</u>","thin"]', '<b>Lean harvest</b> = <b>poor</b> harvest.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('28dff126-aa57-4d24-a849-8f2b42ae43b3', 'English Language', 'JAMB', null, 2007, null, 'He travelled <u>__________</u> last week', null, '["somewhat","some where","some what","somewhere"]', 3, 'Correct spelling: somewhere.', true, '2026-10-24 07:21:37.325', '2026-10-24 07:21:37.325', null, null, null, 'He travelled <u>__________</u> last week', '["somewhat","some where","some what","somewhere"]', 'Correct spelling: somewhere.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('28e95196-c168-40a2-b9de-d6cc14c5536c', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). He has been advised to <u>keep his head</u>, the confusion notwithstanding.', null, '["avoid being beaten or insulted","keep calm","save his head","prevent being beheaded"]', 1, '''Keep his head'' = stay calm.', true, '2026-10-24 01:02:04', '2026-10-24 01:02:04', null, null, null, '(Choose the most appropriate interpretation). He has been advised to <u>keep his head</u>, the confusion notwithstanding.', '["avoid being beaten or insulted","<u>keep calm</u>","save his head","prevent being beheaded"]', '''<b>Keep his head</b>'' = <b>stay calm</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('28eb5059-fdda-447b-8c60-d3e84cdb0249', 'English Language', 'JAMB', null, 2024, null, 'Which of the following statements can be inferred from the passage?', null, '["The approach to employ in conflict management depends on the state of affairs","all conflict management approach can applied in all situations","There is a general disagreement among scholars on conflict management","only one conflict management approach can be applied in all situations"]', 0, 'The passage states that different approaches may have utility in particular circumstances.', true, '2026-09-18 09:43:02.745', '2026-09-18 09:43:02.745', null, null, 'COMPREHENSION', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('28f38952-0570-45b4-b1ce-1b669e85e911', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Jesus did not grant the request of the sons of Zebedee because...', null, '["they were not qualified for the privilege they asked for","He did not want to encourage rivalry among the disciples","it was not His to grant the request","they could not drink with Jesus cup"]', 2, 'Mark 10:40 records Jesus replying: ''to sit on My right hand or on My left is not Mine to give, but it is for those for whom it is prepared.''', true, '2026-09-09 17:18:27.44', '2026-09-09 17:18:27.44', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('28f422ae-e9da-437e-9851-595e07ad5f7b', 'English Language', 'JAMB', null, 2007, null, 'The words <u>------------</u> divided between the end of one line.', null, '["have been","have being","has been","has being"]', 0, 'Plural ''words'' â†’ have been.', true, '2026-10-24 01:02:15.873', '2026-10-24 01:02:15.873', null, null, null, 'The words <u>------------</u> divided between the end of one line.', '["<u>have been</u>","have being","has been","has being"]', 'Plural ''<b>words</b>'' â†’ <b>have been</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('28fcfad9-497f-4761-925c-f4cb2a83dfff', 'Economics', 'JAMB', null, 2026, null, 'Given a consumption function in an economy as C = 200 + 0.75Yd, the marginal propensity to save is', null, '["0.75","200","0.25","200.75","1.75"]', 2, 'The marginal propensity to save (MPS) is 0.25. In the consumption function C = 200 + 0.75Yd, the marginal propensity to consume (MPC) is 0.75 (the coefficient of Yd). Since MPC + MPS = 1, MPS = 1 - 0.75 = 0.25. This means that for every additional unit of disposable income, households save 25% and spend 75%. The 200 is autonomous consumption.', true, '2026-09-10 10:41:21.42', '2026-09-10 10:41:21.42', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('29018adc-4cda-4e23-bc62-efc0347bbec7', 'Literature in English', 'JAMB', null, 2026, null, 'The poem portrays the night as', null, '["protective and comforting","dangerous and mysterious","joyful and musical","peace and calm"]', 1, 'The night is portrayed as dangerous and mysterious.', true, '2026-09-12 11:05:43.653', '2026-09-12 11:05:43.653', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('290ce4a2-b360-45b6-9798-8e78fb612cbc', 'Literature in English', 'JAMB', null, 2026, null, '''When the criminal was arrested, he rattled like a rattle snake'' is an example of', null, '["Pun","Simile","Hyperbole","Apostrophe"]', 1, 'The statement is a simile.', true, '2026-09-12 11:07:25.385', '2026-09-12 11:07:25.385', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('290e90b3-d634-4e76-a1db-4ca100ce6d84', 'Yoruba', 'JAMB', null, 2007, null, 'Ka àwôn àyókà ìsàlẹ yìí, Kí o sì dáhùn àwòn ìbéèrè tí ó tẹlé wòn. Babárində nífèè Föláyadé púpõ. Föláyadé náà sì rèé, òrékelèwà òmõge, çlèyinjú-çgè, çlèrin-ín èyc! Òun náà sì dá ìfè yìí padà pèlú ayõ àti ìdùnnú. Bùgbòn bàbá Föláyadé ni igì wòròkò tí p da iná rú nídìí òrõ yìí: ó kórìíra Babárində nítorí pé ó kà á sí òtòyì ènìyàn. Bèè òmólójú rè sì ni Föláyadé í ÿe. Baba gbàgbò pé bí òmò òun bá fè Babárində, inú ìyà ni tòkòtaya wòn yóò wà. Kì í kúkú í ÿe pé Babárində jë tálákà bëë náà: ó p ÿiyë gëgë bí òÿìÿë kékere nílë-iÿë plá kan, bëë nì kò sì tòrò jç, ÿùgbòn ó kàn jë pé kò lówò tó Ayõkúnlé Atáyëwá, oníÿòwò kan tí baba Föláyadé fë kí òmò rë fë. Ìyá Föláyadé náà sì rèé, ìbi tí òkò rë bá të sí nì òun náà p të sí. Bé ojúbõrõ kò ni a sì fì p gbòmò lòwò ëkùrò: àwòn òbí Föláyadé fì toògùn-toògùn fa òmò wòn fún Ayõkúnlé Atáyëwá ÿaya. Babárində banùjë nídìí òrõ yìí, ëdùn-òkàn sì ni Föláyadé gbé wòlé òkò. Òjò þ gori ójò, òdún þ gori òdún, bèè ni ìgbà sì þ rékòjà lo. Fòláyadé bí akò, ó bi abo nílé òkò, ÿúgbòn nykan ò lò déédé fún òkò rè mò lënu òwò rè. Àwòn oníbodè ti gbèsè lé òjà rè tó jè çgbëlègbè náírà. Ó yáwó nílé-ìfowópamò, ÿúgbòn kò rí i san padà. Àwòn báykì bá gba ilé, òkò àti àwòn dúkiá rè mìíràn. Àtijç-àtimu wá di ìjòro fún òun àti ìyàwó rè àti àwon òmò wòn pèlú. Níha kejì, Babárində náà ti gbéyàwó, ó sì tí bímò. Lénu ìyê rê wàyìí, ó ti di ògá, orí sì ti sún un sólá. Àwòn òbí Föláyadé wá p wò sùn- ùn, wòn rí i bí ìgbé-ayé Ayõkúnlé Atáyéwá ÿe p lò, wòn sì tún wo ti Föláyadé òmò wòn, bákan náà ni wòn sì p gbókèèrè wo ti Babárində bó ÿe p dùn sí i fún un. Wòn wá fika àbámò bónu: ìwájú ò ÿeé lò, èyìn ò sì ÿeé padà sí fún wòn. Babárində, eni tí wòn rò pé kò lè pàgò ló wá dçni tí p kòlé aláruru. Ó wá hàn kedere sí wòn pé çni tí yóò dòlòlà lòla, orí ló mõ òn. Föláyadé gbé èdùn-òkàn wòlékò nítorí pé', null, '["nþkan kò lò déédéfún òkò rê","kò lè fè çni tó wù ù lòkan","ó rí i pé ìyà þ bç níwájù","kò wòlé òkò nígbà tó wù ù"]', 2, 'Föláyadé gbé èdùn-òkàn wòlékò nítorí pé ó rí i pé ìyà þ bç níwájù.', true, '2026-10-13 13:23:30.641', '2026-10-13 13:23:30.641', null, null, null, 'Ka àwôn àyókà ìsàlẹ yìí, Kí o sì dáhùn àwòn ìbéèrè tí ó tẹlé wòn. Babárində nífèè Föláyadé púpõ. Föláyadé náà sì rèé, òrékelèwà òmõge, çlèyinjú-çgè, çlèrin-ín èyc! Òun náà sì dá ìfè yìí padà pèlú ayõ àti ìdùnnú. Bùgbòn bàbá Föláyadé ni igì wòròkò tí p da iná rú nídìí òrõ yìí: ó kórìíra Babárində nítorí pé ó kà á sí òtòyì ènìyàn. Bèè òmólójú rè sì ni Föláyadé í ÿe. Baba gbàgbò pé bí òmò òun bá fè Babárində, inú ìyà ni tòkòtaya wòn yóò wà. Kì í kúkú í ÿe pé Babárində jë tálákà bëë náà: ó p ÿiyë gëgë bí òÿìÿë kékere nílë-iÿë plá kan, bëë nì kò sì tòrò jç, ÿùgbòn ó kàn jë pé kò lówò tó Ayõkúnlé Atáyëwá, oníÿòwò kan tí baba Föláyadé fë kí òmò rë fë. Ìyá Föláyadé náà sì rèé, ìbi tí òkò rë bá të sí nì òun náà p të sí. Bé ojúbõrõ kò ni a sì fì p gbòmò lòwò ëkùrò: àwòn òbí Föláyadé fì toògùn-toògùn fa òmò wòn fún Ayõkúnlé Atáyëwá ÿaya. Babárində banùjë nídìí òrõ yìí, ëdùn-òkàn sì ni Föláyadé gbé wòlé òkò. Òjò þ gori ójò, òdún þ gori òdún, bèè ni ìgbà sì þ rékòjà lo. Fòláyadé bí akò, ó bi abo nílé òkò, ÿúgbòn nykan ò lò déédé fún òkò rè mò lënu òwò rè. Àwòn oníbodè ti gbèsè lé òjà rè tó jè çgbëlègbè náírà. Ó yáwó nílé-ìfowópamò, ÿúgbòn kò rí i san padà. Àwòn báykì bá gba ilé, òkò àti àwòn dúkiá rè mìíràn. Àtijç-àtimu wá di ìjòro fún òun àti ìyàwó rè àti àwon òmò wòn pèlú. Níha kejì, Babárində náà ti gbéyàwó, ó sì tí bímò. Lénu ìyê rê wàyìí, ó ti di ògá, orí sì ti sún un sólá. Àwòn òbí Föláyadé wá p wò sùn- ùn, wòn rí i bí ìgbé-ayé Ayõkúnlé Atáyéwá ÿe p lò, wòn sì tún wo ti Föláyadé òmò wòn, bákan náà ni wòn sì p gbókèèrè wo ti Babárində bó ÿe p dùn sí i fún un. Wòn wá fika àbámò bónu: ìwájú ò ÿeé lò, èyìn ò sì ÿeé padà sí fún wòn. Babárində, eni tí wòn rò pé kò lè pàgò ló wá dçni tí p kòlé aláruru. Ó wá hàn kedere sí wòn pé çni tí yóò dòlòlà lòla, orí ló mõ òn. Föláyadé gbé èdùn-òkàn wòlékò nítorí pé', '["nþkan kò lò déédéfún òkò rê","kò lè fè çni tó wù ù lòkan","ó rí i pé ìyà þ bç níwájù","kò wòlé òkò nígbà tó wù ù"]', 'Föláyadé gbé èdùn-òkàn wòlékò nítorí pé ó rí i pé ìyà þ bç níwájù.', '{"bold":["ó rí i pé ìyà þ bç níwájù"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('29163fa4-2afc-4d80-b1e5-438b0c08cc2d', 'Literature in English', 'JAMB', null, 2026, null, 'Another character present is', null, '["Varrius","Enobarbus","Lepidus","Caesar"]', 0, 'Varrius is another character present.', true, '2026-09-12 11:14:07.342', '2026-09-12 11:14:07.342', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2918217f-7560-44f7-9a2b-4e97ee70ecdf', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'According to Jesus, what defiles a person?', null, '["words that come out of the mouth","sinful thoughts","faithlessness","touching a leper"]', 0, 'Jesus said that what comes out of the mouth defiles a person, not what goes into it. He explained that evil thoughts, murder, adultery, and other sins come from the heart and defile a person.', true, '2026-09-12 09:45:50.502', '2026-09-12 09:45:50.502', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('292ee932-96ae-4f99-8d1e-4c20f7729d2d', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). The minister considered the ministry''s budget to be <u>a drop in the ocean</u> in view of the number of projects in the pipeline.', null, '["The amount available may be inadequate for projected expenditure","The minister may be dropped for failing to complete a number of projects","The money approved cannot complete the pipeline project across the ocean","The pipeline project across the ocean will be abandoned unless budgetary allocation improve"]', 0, '''A drop in the ocean'' = inadequate amount.', true, '2026-10-24 01:04:24.744', '2026-10-24 01:04:24.744', null, null, null, '(Choose the most appropriate interpretation). The minister considered the ministry''s budget to be <u>a drop in the ocean</u> in view of the number of projects in the pipeline.', '["<u>The amount available may be inadequate for projected expenditure</u>","The minister may be dropped for failing to complete a number of projects","The money approved cannot complete the pipeline project across the ocean","The pipeline project across the ocean will be abandoned unless budgetary allocation improve"]', '''A <b>drop in the ocean</b>'' = <b>inadequate amount</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('292f864f-d451-4b1b-b3b2-eda8fbe98e00', 'Physics', 'JAMB', null, 2003, null, 'Which of the following pairs of light rays shows the widest separation in the spectrum of white light?', null, '["Green and yellow","Indigo and violet","Orange and red","Blue and red"]', 3, 'Of the pairs given, blue and red are furthest apart in the spectrum.', true, '2026-10-12 19:15:56.789', '2026-10-12 19:15:56.789', null, null, null, 'Which of the following pairs of light rays shows the widest separation in the spectrum of white light?', '["Green and yellow","Indigo and violet","Orange and red","Blue and red"]', 'Of the pairs given, blue and red are furthest apart in the spectrum.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('293037ee-08f4-43c9-bc06-65a07e628376', 'Literature in English', 'JAMB', null, 2026, null, 'In The Breasts of the Sea, the sea is most appropriately interpreted as a', null, '["Literal geographic feature only","Symbol of nurturing, mystery, and vast emotional depth","Representation of political boundaries","Device for comic imagery"]', 1, 'The sea symbolizes nurturing, mystery, and vast emotional depth.', true, '2026-09-12 11:09:59.397', '2026-09-12 11:09:59.397', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('293c256a-2d60-4644-bb1b-f7bcbc939ea3', 'English Language', 'JAMB', null, 2024, null, 'It controls the amount of glucose in the blood using the hormone called ______.', null, '["insulin","amino","bile","acid"]', 0, 'Insulin controls blood glucose levels.', true, '2026-09-18 09:43:02.843', '2026-09-18 09:43:02.843', null, null, 'CLOZE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('29471fc2-7444-4fb2-9b0a-561d8eb46488', 'Physics', 'JAMB', null, 1997, null, 'An arrow of mass 0.1 kg moving with a horizontal velocity of 15 m s⁻¹ is shot into a wooden block of mass 0.4 kg lying at rest on a smooth horizontal surface. Their common velocity after impact is', null, '["15.0 m s⁻¹","7.5 m s⁻¹","3.8 m s⁻¹","3.0 m s⁻¹"]', 3, 'Momentum is conserved: 0.1 x 15 = (0.1 + 0.4)v, so v = 1.5/0.5 = 3.0 m s⁻¹.', true, '2026-10-12 19:15:42.706', '2026-10-12 19:15:42.706', null, null, null, 'An arrow of mass 0.1 kg moving with a horizontal velocity of 15 m s<sup>-1</sup> is shot into a wooden block of mass 0.4 kg lying at rest on a smooth horizontal surface. Their common velocity after impact is', '["15.0 m s<sup>-1</sup>","7.5 m s<sup>-1</sup>","3.8 m s<sup>-1</sup>","3.0 m s<sup>-1</sup>"]', 'Momentum is conserved: 0.1 x 15 = (0.1 + 0.4)v, so v = 1.5/0.5 = 3.0 m s<sup>-1</sup>.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('29485e35-14cb-46cf-a8c6-3920830ce6fe', 'Physics', 'JAMB', null, 2003, null, 'In the calibration of an ammeter using Faraday''s laws of electrolysis, the ammeter reading is kept constant at 1.20 A. If 0.990 g of copper is deposited in 40 minutes, the correction to be applied to the ammeter is [e.c.e. of copper = 3.3 x 10⁻⁴ g C⁻¹]', null, '["0.05 A","0.06 A","0.03 A","0.04 A"]', 0, 'True current I = m/(zt) = 0.990/(3.3 x 10⁻⁴ x 2400) = 1.25 A. The ammeter reads 1.20 A, so the correction is 0.05 A.', true, '2026-10-12 19:15:57.962', '2026-10-12 19:15:57.962', null, null, null, 'In the calibration of an ammeter using Faraday''s laws of electrolysis, the ammeter reading is kept constant at 1.20 A. If 0.990 g of copper is deposited in 40 minutes, the correction to be applied to the ammeter is [e.c.e. of copper = 3.3 x 10<sup>-4</sup> g C<sup>-1</sup>]', '["0.05 A","0.06 A","0.03 A","0.04 A"]', 'True current I = m/(zt) = 0.990/(3.3 x 10<sup>-4</sup> x 2400) = 1.25 A. The ammeter reads 1.20 A, so the correction is 0.05 A.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('294b85ad-a4be-4610-99ef-a9c18ef60b6a', 'English Language', 'JAMB', null, 2007, null, 'The mechanic did not tell me the brakes <u>------------</u> bad.', null, '["were","are","is","was"]', 0, 'Plural ''brakes'' past â†’ were.', true, '2026-10-24 01:02:15.82', '2026-10-24 01:02:15.82', null, null, null, 'The mechanic did not tell me the brakes <u>------------</u> bad.', '["<u>were</u>","are","is","was"]', 'Plural ''<b>brakes</b>'' past â†’ <b>were</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2966e17e-32e9-47fe-a39c-44329daf4134', 'English Language', 'JAMB', null, 2007, null, 'Soyinka''s masterful <u>__________</u> of the atmosphere of his childhood helped to make his book, Ake, an outright success', null, '["evocation","invocation","convocation","revocation"]', 0, 'Correct spelling: evocation.', true, '2026-10-24 07:21:44.919', '2026-10-24 07:21:44.919', null, null, null, 'Soyinka''s masterful <u>__________</u> of the atmosphere of his childhood helped to make his book, Ake, an outright success', '["evocation","invocation","convocation","revocation"]', 'Correct spelling: evocation.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('296b0120-cdab-4c37-b205-cb1f0e44a42d', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). Old customs <u>die hard</u>. This implies that old customs ____________', null, '["cause a lot of hardship and death","must be stopped","never die out","cause hardship for younger people","tend to last for a long time"]', 4, '''Die hard'' means slow to disappear.', true, '2026-10-24 01:04:13.011', '2026-10-24 01:04:13.011', null, null, null, '(Choose the most appropriate interpretation). Old customs <u>die hard</u>. This implies that old customs ____________', '["cause a lot of hardship and death","must be stopped","never die out","cause hardship for younger people","<u>tend to last for a long time</u>"]', '''<b>Die hard</b>'' means <b>slow to disappear</b>.', '{}');
