insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2977df0e-76d7-457b-8b57-8811a583436b', 'English Language', 'JAMB', null, 2007, null, 'Neither Agbo nor his parents <u>------------</u> the meetings now.', null, '["has attended","attend","attended","attends"]', 1, 'Nearest subject parents plural â†’ attend.', true, '2026-10-24 01:04:28.379', '2026-10-24 01:04:28.379', null, null, null, 'Neither Agbo nor his parents <u>------------</u> the meetings now.', '["has attended","<u>attend</u>","attended","attends"]', 'Nearest subject <b>parents</b> plural â†’ <b>attend</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2977eb17-553e-4150-a5ab-92c97dd9b155', 'English Language', 'JAMB', null, 2007, null, 'A child that shows mature characteristics at an early age may be described as <u>__________</u>', null, '["preconceived","premature","ingenuous","precocious"]', 3, 'Correct spelling: precocious.', true, '2026-10-24 07:21:37.983', '2026-10-24 07:21:37.983', null, null, null, 'A child that shows mature characteristics at an early age may be described as <u>__________</u>', '["preconceived","premature","ingenuous","precocious"]', 'Correct spelling: precocious.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2986ed8c-9042-4e07-bc6a-6e8e5bdd0787', 'Government', 'JAMB', null, 2026, null, 'The second coup d''etat in Nigeria took place on', null, '["29th July, 1966","29th July, 1975","29th February, 1976","1 October, 1966"]', 0, 'The second coup d''etat took place on 29th July, 1966.', true, '2026-09-12 11:24:27.226', '2026-09-12 11:24:27.226', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('298b5946-8b0c-41e0-89f6-5e72beb65b65', 'English Language', 'JAMB', null, 2024, null, 'Choose the word that has the same sound as the one represented by the underlined letters: j_our_ney', null, '["cousin","blood","pawpaw","curse"]', 3, 'The "our" in "journey" sounds like /ɜː/, same as the "ur" in "curse."', true, '2026-09-18 09:23:08.403', '2026-09-18 09:23:08.403', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('298d609c-dadb-4644-acbc-a91194ee7dd5', 'Government', 'JAMB', null, 2026, null, 'A major event in Nigerian history that led to the suspension of Nigeria''s constitution and the declaration of a state of emergency by the colonial authorities in 1953 was the ....', null, '["Aba women''s riot","Zikist movement","Kano riots","Action group crisis"]', 2, 'The Kano riots led to the suspension of the constitution in 1953.', true, '2026-09-12 11:24:30.978', '2026-09-12 11:24:30.978', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('299d86a0-f768-41f4-b438-4b881d036c73', 'Government', 'JAMB', null, 2026, null, 'The emergence of nationalism was essentially the result of the ills of', null, '["slavery","independence","imperialism","colonialism"]', 3, 'Nationalism emerged as a result of the ills of colonialism.', true, '2026-09-12 11:24:09.419', '2026-09-12 11:24:09.419', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('299fba45-898a-4635-8aae-35030dbcbab0', 'Financial Accounting', 'UTME', null, 2002, null, 'The normal accounting entry to record the dishonor of a cheque by a business man is', null, '["debit cash book and credit suspense account","debit cash book and credit drawer","credit cash book and debit suspense account","credit cash book and debit drawer"]', 3, 'The entry is to credit cash book and debit drawer.', true, '2026-10-12 21:59:57.187', '2026-10-12 21:59:57.187', null, null, null, 'The normal accounting entry to record the dishonor of a cheque by a business man is', '["debit cash book and credit suspense account","debit cash book and credit drawer","credit cash book and debit suspense account","<b>credit cash book and debit drawer</b>"]', 'The entry is to <b>credit cash book and debit drawer</b>.', '{"bold":["credit cash book and debit drawer"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('29abc852-a736-4f31-a59e-5d0aed685eb3', 'Chemistry', 'JAMB', null, 2026, null, 'The periodic classification of the elements is an arrangement of the elements in order of their', null, '["atomic weights","isotopic weights","molecular weights","atomic numbers"]', 3, 'Elements are arranged in order of increasing atomic numbers.', true, '2026-09-12 11:36:10.923', '2026-09-12 11:36:10.923', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('29c6984e-e2a1-4a77-a86d-6b4aa0aa1215', 'Biology', 'JAMB', null, 2003, null, 'The most effective method of dealing with non-biodegradable pollutants is by', null, '["dumping","recycling","incineration","burying"]', 1, 'Recycling is the most effective method for non-biodegradable pollutants.', true, '2026-10-12 20:59:33.333', '2026-10-12 20:59:33.333', null, null, null, 'The most effective method of dealing with non-biodegradable pollutants is by', '["dumping","recycling","incineration","burying"]', 'Recycling is the most effective method for non-biodegradable pollutants.', '{"bold":["Recycling"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('29c76562-4587-4cdf-84c0-b9262d9937a4', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Gideon was called Jerubbaal because', null, '["he broke down the altar of Baal","he defeated the Midianites","he sacrificed to Baal","his father''s name was Baal","the people did not like him"]', 0, 'Gideon was called Jerubbaal because he broke down the altar of Baal. After Gideon destroyed the altar of Baal and cut down the Asherah beside it, the people of the town called him Jerubbaal, saying, ''Let Baal contend against him, because he has broken down his altar.''', true, '2026-09-12 09:46:09.12', '2026-09-12 09:46:09.12', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('29ef13f6-b2eb-4e39-bc7e-34cc2ad63415', 'Biology', 'JAMB', null, 2012, null, 'Counter-shading is an adaptive feature that enables animals to', null, '["fight enemies","remain undetected","warn enemies","attract mates."]', 1, 'Counter-shading enables animals to remain undetected.', true, '2026-10-12 20:59:44.489', '2026-10-12 20:59:44.489', null, null, null, 'Counter-shading is an adaptive feature that enables animals to', '["fight enemies","remain undetected","warn enemies","attract mates."]', 'Counter-shading enables animals to remain undetected.', '{"bold":["remain undetected"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('29f08fe7-375e-4d77-b813-28708469912d', 'Chemistry', 'JAMB', null, 2026, null, 'All the following are raw materials in Solvay process except', null, '["sodium chloride","calcium carbonate(IV)","Ammonia","sodium trioxocarbonate (IV)"]', 3, 'Sodium trioxocarbonate (IV) [Na2CO3] is the final product synthesized by the Solvay process, not a raw starting material.', true, '2026-09-09 17:12:46.091', '2026-09-09 17:12:46.091', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('29f6d50d-11eb-4dbf-a1cc-d50f59e8d6a2', 'Economics', 'JAMB', null, 2026, null, 'When the government revenue is planned in such a way that it should exceed proposed government expenditure. This kind of budget is called', null, '["Balanced budget","Budget deficit","Budget surplus","None of the above"]', 2, 'When revenue exceeds expenditure, it is a budget surplus.', true, '2026-09-12 11:00:55.285', '2026-09-12 11:00:55.285', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('29f77b83-f41f-431a-9bf9-624170476abb', 'Physics', 'JAMB', null, 1994, null, 'A capacitor of 8 μF is charged to a potential difference of 100 V. The energy stored by the capacitor is', null, '["1.0 x 10⁴ J","8.0 x 10 J","1.25 x 10 J","4.0 x 10⁻² J"]', 3, 'E = ½CV² = ½ x 8 x 10⁻⁶ x 100² = 4.0 x 10⁻² J.', true, '2026-10-12 19:15:40.29', '2026-10-12 19:15:40.29', null, null, null, 'A capacitor of 8 μF is charged to a potential difference of 100 V. The energy stored by the capacitor is', '["1.0 x 10<sup>4</sup> J","8.0 x 10 J","1.25 x 10 J","4.0 x 10<sup>-2</sup> J"]', 'E = ½CV<sup>2</sup> = ½ x 8 x 10<sup>-6</sup> x 100<sup>2</sup> = 4.0 x 10<sup>-2</sup> J.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('29fb0455-4221-47b8-8f75-e8553e7c1b41', 'Physics', 'JAMB', null, 2026, null, 'A radioactive isotope has a half-life of 10 minutes. If the initial count rate is 800 counts per second, what will the count rate be after 30 minutes?', null, '["400 counts per second","200 counts per second","100 counts per second","50 counts per second"]', 2, 'After 30 minutes (3 half-lives), the count rate = 800 × (1/2)³ = 800/8 = 100 counts per second.', true, '2026-09-10 10:56:49.411', '2026-09-10 10:56:49.411', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2a032d87-21db-494f-9e1c-36839493643d', 'Physics', 'JAMB', null, 1991, null, 'An insulated rod when rubbed with a material acquires', null, '["A negative charge if it is made of glass and rubbed with silk","No charge if it is made of glass and rubbed with fur","No charge if it is made of copper and rubbed with silk","A positive charge if it is made of copper and rubbed with fur."]', 2, 'A copper rod held in the hand is a conductor, so any charge produced leaks away to earth and it stays uncharged. Glass rubbed with silk becomes positive.', true, '2026-10-12 19:15:33.998', '2026-10-12 19:15:33.998', null, null, null, 'An insulated rod when rubbed with a material acquires', '["A negative charge if it is made of glass and rubbed with silk","No charge if it is made of glass and rubbed with fur","No charge if it is made of copper and rubbed with silk","A positive charge if it is made of copper and rubbed with fur."]', 'A copper rod held in the hand is a conductor, so any charge produced leaks away to earth and it stays uncharged. Glass rubbed with silk becomes positive.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2a04f31d-6a16-4458-8783-a0488bd1159d', 'Hausa', 'JAMB', null, 2011, null, 'A wani gari can yamma da Magumi, wai shi Tsauni, an yi wani yaro mai suna Salihi. Iyayensa ba masu wadata ba ne, amma sun yi Ko''karin ganin ya yi ilmin boko da na Arabiya. Bayan Salihi ya kammala karatun firamare, sai mahaiﬁnsa Tanimu, ya nema masa makarantar gaba da ﬁramare. Domin an ce ''Ilimi gishirin zaman duniya.'' Amma kuma samo wa Salihi babbar makarantar Magumi bai yi wa mahaiﬁyarsa D''ahira dadî ba, don ba ta son d''anta ya yi nesa da ita. Dalili shi ne d''ansu tilo namiji, sauran hud''un kuwa duk mata ne. Bugu da Kari, tana jin munanan labarai iri-iri da kan faru a irin wad''annan makarantu. Bayan Salihi ya isa makaranta, sai ya dukufa kan karatu gadan-gadan. Zuwansa ke da wuya, sai suka kulla abota da wani dan ajinsu, wai shi Kasa. Kafin ya ankara, sai da abokinsa ya jefa shi cikin wata kungiyar asiri. Da ya farga da halin da ya shiga, sai ya yi Ko''karin ﬁta daga cikinta, amma aka nuna masa ai ba a haka. ''In har ka ce za ka ﬁce, lallai za a kassara ka, ko ma a halaka ka'' in ji abokinsa. Ganin halin tsaka-mai-wuya da ya shiga, sai ya tsayar da shawarar ya fallasa kungiyar, in ya so komai ta tafasa ta kone. Ya je ya shaida wa shugaban makaranta. Nan take ya sanya jami''an tsaro suka kamo dukkan ''yan kungiyar''. Kotu ta yanke musu hukunci, sannan aka kai su gidan jarun. Da ma an ce, ''Komai nisan jifa kasa za ya fado.'' Wane take ya fi dacewa da wannan labari?', null, '["''Ilimi gishirin zaman duniya.''","''Ramin Karya Kurarre ne.''","''Alheri danko ne ...''","''Ba a fafar gora ...''"]', 0, 'Taken da ya fi dacewa da labarin shi ne ''Ilimi gishirin zaman duniya'' domin ya jaddada muhimmancin ilimi.', true, '2026-10-13 10:37:20.303', '2026-10-13 10:37:20.303', null, null, null, 'A wani gari can yamma da Magumi, wai shi Tsauni, an yi wani yaro mai suna Salihi. Iyayensa ba masu wadata ba ne, amma sun yi Ko''karin ganin ya yi ilmin boko da na Arabiya. Bayan Salihi ya kammala karatun firamare, sai mahaiﬁnsa Tanimu, ya nema masa makarantar gaba da ﬁramare. Domin an ce ''Ilimi gishirin zaman duniya.'' Amma kuma samo wa Salihi babbar makarantar Magumi bai yi wa mahaiﬁyarsa D''ahira dadî ba, don ba ta son d''anta ya yi nesa da ita. Dalili shi ne d''ansu tilo namiji, sauran hud''un kuwa duk mata ne. Bugu da Kari, tana jin munanan labarai iri-iri da kan faru a irin wad''annan makarantu. Bayan Salihi ya isa makaranta, sai ya dukufa kan karatu gadan-gadan. Zuwansa ke da wuya, sai suka kulla abota da wani dan ajinsu, wai shi Kasa. Kafin ya ankara, sai da abokinsa ya jefa shi cikin wata kungiyar asiri. Da ya farga da halin da ya shiga, sai ya yi Ko''karin ﬁta daga cikinta, amma aka nuna masa ai ba a haka. ''In har ka ce za ka ﬁce, lallai za a kassara ka, ko ma a halaka ka'' in ji abokinsa. Ganin halin tsaka-mai-wuya da ya shiga, sai ya tsayar da shawarar ya fallasa kungiyar, in ya so komai ta tafasa ta kone. Ya je ya shaida wa shugaban makaranta. Nan take ya sanya jami''an tsaro suka kamo dukkan ''yan kungiyar''. Kotu ta yanke musu hukunci, sannan aka kai su gidan jarun. Da ma an ce, ''Komai nisan jifa kasa za ya fado.'' Wane take ya fi dacewa da wannan labari?', '["''Ilimi gishirin zaman duniya.''","''Ramin Karya Kurarre ne.''","''Alheri danko ne ...''","''Ba a fafar gora ...''"]', 'Taken da ya fi dacewa da labarin shi ne ''Ilimi gishirin zaman duniya'' domin ya jaddada muhimmancin ilimi.', '{"bold":["''Ilimi gishirin zaman duniya''"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2a0621c4-5dd2-4c92-a3ca-f602bb1d33cd', 'Biology', 'JAMB', null, 2026, null, 'When a mixture of a food substance and Benedict''s solution was warmed, it changed from blue to brick-red. This indicates the presence of', null, '["Reducing sugar","Fatty acid","Sucrose","Amino acid"]', 0, 'A color change from blue to brick-red with Benedict''s solution indicates the presence of reducing sugar. Reducing sugars (glucose, fructose, maltose) have free aldehyde or ketone groups that can reduce copper ions in Benedict''s solution, forming a brick-red precipitate of copper (I) oxide. Sucrose is a non-reducing sugar and will not give a positive Benedict''s test unless hydrolyzed. Fatty acids and amino acids do not give this reaction. The intensity of the color can indicate the concentration of reducing sugar.', true, '2026-09-09 03:19:04.019', '2026-09-09 03:19:04.019', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2a0a0355-9cc5-4c6f-8257-c60a2100fb0b', 'Literature in English', 'JAMB', null, 2026, null, '''He passed away'' instead of ''he died'' is an example of', null, '["Malapropism","Euphemism","Antonomasia","Paradox"]', 1, 'It is an example of euphemism.', true, '2026-09-12 11:05:56.328', '2026-09-12 11:05:56.328', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2a0ea6d6-af34-4d95-92d8-138fecea6a76', 'Literature in English', 'JAMB', null, 2026, null, '''These naked sons of misery''. This expression is an example of', null, '["Litotes","Paradox","Assonance","metaphor"]', 3, 'The expression is a metaphor.', true, '2026-09-12 11:07:26.474', '2026-09-12 11:07:26.474', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2a0ee0e2-1d50-45f7-a0e7-3bc5e10c1af0', 'Economics', 'JAMB', null, 2026, null, '______ refers to the extraction of raw materials from the land or sea', null, '["Secondary production","Intermediate production","Main production","Primary production","Source production"]', 3, 'Primary production involves the extraction of raw materials from land or sea.', true, '2026-09-12 11:00:53.622', '2026-09-12 11:00:53.622', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2a0f4c68-7bc5-470c-b5e0-c38f4f8845e0', 'Literature in English', 'JAMB', null, 2026, null, '''But at my back I always heard Time''s winged chariot hurrying near'' illustrates', null, '["Metaphor","Apostrophe","Oxymoron","Metonymy"]', 0, 'It illustrates metaphor.', true, '2026-09-12 11:13:54.704', '2026-09-12 11:13:54.704', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2a1d8751-e4a0-46c9-9911-ccb42c14dd4a', 'Economics', 'JAMB', null, 2026, null, 'Long run cost is U-shaped because of the operation of', null, '["economies of scale on the left hand side and diseconomies of scale on the right hand side","diseconomies of scale on the left and right hand sides","economies of scale on the left and right hand sides","constant return to scale","diseconomies of scale of the left hand side and economies of scale of the right hand side"]', 0, 'The long-run average cost curve is U-shaped because of economies of scale on the left side and diseconomies of scale on the right side. As a firm expands output in the long run, it initially experiences economies of scale (lower average costs) due to specialization, bulk buying, and improved efficiency. After reaching minimum efficient scale, further expansion leads to diseconomies of scale (higher average costs) due to management problems and coordination difficulties.', true, '2026-09-10 10:41:58.614', '2026-09-10 10:41:58.614', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2a31cf61-779a-4cc7-9615-b99170899e25', 'English Language', 'JAMB', null, 2024, null, '______ bring a letter of authority before he can collect the money?', null, '["Needs he","Need he","He needs","Does he needed"]', 1, '"Need he" is the correct inverted form for a question with the modal "need."', true, '2026-09-18 09:24:04.776', '2026-09-18 09:24:04.776', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2a3da470-4d6f-4134-9fe0-ea03fd61ece5', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. He is bound to exposes himself by his <u>nefarious</u> activities.', null, '["kind","disreputable","despicable","nocturnal"]', 1, 'Nefarious = disreputable/wicked.', true, '2026-10-24 01:04:00.442', '2026-10-24 01:04:00.442', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. He is bound to exposes himself by his <u>nefarious</u> activities.', '["kind","<u>disreputable</u>","despicable","nocturnal"]', '<b>Nefarious</b> = <b>disreputable</b>/wicked.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2a4cb6a8-9263-4e10-b3d5-8d998089a96d', 'Biology', 'JAMB', null, 2026, null, 'Which of the following isn''t an example of plasma protein found in the blood plasma?', null, '["valine","albumin","fibrinogen","globulin","prothrombin"]', 0, 'Valine is an amino acid, not a plasma protein. It is one of the essential amino acids that the body cannot synthesize and must obtain from diet. Albumin is the most abundant plasma protein, maintaining osmotic pressure. Fibrinogen and prothrombin are clotting factors in plasma. Globulins are plasma proteins involved in immunity (antibodies) and transport. Plasma contains many proteins, but amino acids like valine are individual molecules that make up proteins, not proteins themselves.', true, '2026-09-09 03:18:30.45', '2026-09-09 03:18:30.45', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2a523a36-615a-4743-b1d1-470bae12beaf', 'English Language', 'JAMB', null, 2024, null, 'According to the novel, who built the first-storey building in Nigeria?', null, '["Bishop Samuel Ajayi Crowther","Lord Federick Lugard","Henry Townsend","Lord Bernard Shaw"]', 0, 'According to the novel, Bishop Samuel Ajayi Crowther built the first-storey building in Nigeria.', true, '2026-09-18 09:43:02.293', '2026-09-18 09:43:02.293', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2a628cf0-71d3-4865-a7ca-d338206b05dd', 'English Language', 'JAMB', null, 2024, null, 'The air surrounding the bomb is raised very rapidly to an enormously high ______.', null, '["Way","Temperature","Class","Profile"]', 1, '"High temperature" is the correct collocation.', true, '2026-09-18 09:43:02.438', '2026-09-18 09:43:02.438', null, null, 'CLOZE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2a790016-80c0-427e-8a44-4c579dc891c6', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The diminutive figure bounces over the track with <u>unfathomable</u> lightness.', null, '["invigorating","irresistible","predictable","impressive"]', 2, 'Unfathomable = incomprehensible; opposite = predictable.', true, '2026-10-24 07:21:21.699', '2026-10-24 07:21:21.699', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The diminutive figure bounces over the track with <u>unfathomable</u> lightness.', '["invigorating","irresistible","predictable","impressive"]', 'Unfathomable = incomprehensible; opposite = predictable.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2a813719-2e3b-4a69-ad8c-4ce0f6897768', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). In his own story, the thief claimed that he had been <u>led astray</u> by a friend.', null, '["closely followed by a friend","searching for him","tagging him a talebearer","misguided by a friend"]', 3, '''Led astray'' = misguided.', true, '2026-10-24 01:04:20.452', '2026-10-24 01:04:20.452', null, null, null, '(Choose the most appropriate interpretation). In his own story, the thief claimed that he had been <u>led astray</u> by a friend.', '["closely followed by a friend","searching for him","tagging him a talebearer","<u>misguided by a friend</u>"]', '''<b>Led astray</b>'' = <b>misguided</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2a87b781-c263-4bee-8858-8eb9ceef07e8', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The striking workers have vowed to work until the decision is rescinded.', null, '["implemented","rescinded","dismissed","reversed"]', 3, 'Rescinded = reversed.', true, '2026-10-24 01:01:57.236', '2026-10-24 01:01:57.236', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The striking workers have vowed to work until the decision is rescinded.', '["implemented","rescinded","dismissed","<u>reversed</u>"]', '<b>Rescinded</b> = <b>reversed</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2a88d91d-b0ab-4ad4-a919-ca65e7a2b0d8', 'English Language', 'JAMB', null, 2007, null, 'Adika <u>_____</u>a message from the club regularly', null, '["receives","receive","received","had received"]', 0, 'Singular Adika habitual â†’ receives.', true, '2026-10-24 01:02:16.956', '2026-10-24 01:02:16.956', null, null, null, 'Adika <u>_____</u>a message from the club regularly', '["<u>receives</u>","receive","received","had received"]', 'Singular <b>Adika</b> habitual â†’ <b>receives</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2a92c578-d528-48cc-8d76-4105aad4fa84', 'Hausa', 'JAMB', null, 2011, null, 'Wanne ne bare dangane da jinsi?', null, '["Cinnaka.","Hankaka.","Buraka.","Gauraka."]', 2, 'Buraka bare ne dangane da jinsi (mace).', true, '2026-10-13 10:37:21.179', '2026-10-13 10:37:21.179', null, null, null, 'Wanne ne bare dangane da jinsi?', '["Cinnaka.","Hankaka.","Buraka.","Gauraka."]', 'Buraka bare ne dangane da jinsi (mace).', '{"bold":["Buraka"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2a9a18db-2431-4c44-88f6-3518dcd771c7', 'Physics', 'JAMB', null, 2003, null, 'If an object is placed between two parallel plane mirrors with their reflecting surfaces facing each other, how many images of the object will be formed?', null, '["Four","Two","Eight","Infinite"]', 3, 'The images are reflected repeatedly from one mirror to the other, so an infinite number of images form (in practice they fade).', true, '2026-10-12 19:15:55.91', '2026-10-12 19:15:55.91', null, null, null, 'If an object is placed between two parallel plane mirrors with their reflecting surfaces facing each other, how many images of the object will be formed?', '["Four","Two","Eight","Infinite"]', 'The images are reflected repeatedly from one mirror to the other, so an infinite number of images form (in practice they fade).', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2a9e22a2-de3b-435b-9f93-ff9401f5717a', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). <u>A basic objective in this respect is the attainment of self-sufficiency in food in about a decade.</u>', null, '["Food will soon be sufficient for everybody","Mass production of food","We should aim at producing food for sale and consumption in ten years","We should be able to feed ourselves in five years","Our aim is to provide enough food for our needs in ten years"]', 4, 'Self-sufficiency in food in a decade = enough food in ten years.', true, '2026-10-24 01:04:14.982', '2026-10-24 01:04:14.982', null, null, null, '(Choose the most appropriate interpretation). <u>A basic objective in this respect is the attainment of self-sufficiency in food in about a decade.</u>', '["Food will soon be sufficient for everybody","Mass production of food","We should aim at producing food for sale and consumption in ten years","We should be able to feed ourselves in five years","<u>Our aim is to provide enough food for our needs in ten years</u>"]', '<b>Self-sufficiency in food in a decade</b> = <b>enough food in ten years</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2aa00ddc-55b3-429f-bf4f-b196b77d151e', 'Physics', 'JAMB', null, 2026, null, 'A car accelerates uniformly from rest at 4 ms⁻². How far will it travel in the fifth complete second?', null, '["15m","18m","27m","30m"]', 1, 'Distance in nth second = u + a(2n-1)/2. For n=5: s = 0 + 4(2×5-1)/2 = 4(9)/2 = 18m.', true, '2026-09-10 10:58:05.108', '2026-09-10 10:58:05.108', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2aa0333a-5ecc-4510-8737-92789a560dec', 'English Language', 'JAMB', null, 0, null, '8', null, '["demand ","earn ","take","market"]', 1, 'They earn no wages while on strike', true, '2026-09-18 09:08:12.936', '2026-09-18 09:08:12.936', '1edea09d-7ad3-4c90-8c54-eeb4b369dcff', 7, 'CLOZE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2aa8980e-47ba-46f1-b00b-5702f4e7d70e', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). After a careful review of Adamu''s last examination result, the Principal concluded that his performance <u>left much to be desired</u>. This means ____________', null, '["was very unsatisfactory","was very satisfactory","was extremely desirable","was very brilliant","was extremely commendable"]', 0, '''Left much to be desired'' means unsatisfactory.', true, '2026-10-24 01:02:01.098', '2026-10-24 01:02:01.098', null, null, null, '(Choose the most appropriate interpretation). After a careful review of Adamu''s last examination result, the Principal concluded that his performance <u>left much to be desired</u>. This means ____________', '["<u>was very unsatisfactory</u>","was very satisfactory","was extremely desirable","was very brilliant","was extremely commendable"]', '''<b>Left much to be desired</b>'' means <b>unsatisfactory</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2aa956ac-3670-44ff-9fbf-321fd8f3cf97', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Tortoises need cool climates and must have places where they can <u>hibernate</u>.', null, '["sleep deeply","relax","reproduce","hide at night"]', 0, 'Hibernate = sleep deeply.', true, '2026-10-24 01:01:51.293', '2026-10-24 01:01:51.293', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Tortoises need cool climates and must have places where they can <u>hibernate</u>.', '["<u>sleep deeply</u>","relax","reproduce","hide at night"]', '<b>Hibernate</b> = <b>sleep deeply</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2aaa02a7-5aed-4ca9-a284-62f05469b99f', 'English Language', 'JAMB', null, 0, null, '2', null, '["inflation","cost","deflation","devaluation "]', 0, 'Inflation directly affects living standards by raising prices.', true, '2026-09-18 09:08:12.209', '2026-09-18 09:08:12.209', '1edea09d-7ad3-4c90-8c54-eeb4b369dcff', 1, 'CLOZE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2aabc67b-c87e-4200-90ad-3a8d08743362', 'Economics', 'JAMB', null, 2026, null, '______ refers to the part of income not spent.', null, '["Consumption","Savings","injection","injector"]', 1, 'Savings is the part of income not spent on consumption.', true, '2026-09-12 11:00:20.405', '2026-09-12 11:00:20.405', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2ab31d3b-6bca-48a7-896a-e026dc6d8dfb', 'Literature in English', 'JAMB', null, 2026, null, 'A character who defends a bad cause or who argues in a contrary position just to stimulate an argument is referred to as', null, '["Legend","Cynic","Villain","Critic"]', 1, 'A cynic argues in a contrary position to stimulate argument.', true, '2026-09-12 11:10:48.268', '2026-09-12 11:10:48.268', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2ab8d8df-9d3a-4e0e-ab35-de695b43cc8f', 'Hausa', 'JAMB', null, 2010, null, 'A lafazin kalma, wane wasali ke gandanta |g|?', null, '["/a/.","/u/.","/o/.","/e/."]', 3, 'Wasali /e/ ke gandanta |g|.', true, '2026-10-13 10:37:23.825', '2026-10-13 10:37:23.825', null, null, null, 'A lafazin kalma, wane wasali ke gandanta |g|?', '["/a/.","/u/.","/o/.","/e/."]', 'Wasali /e/ ke gandanta |g|.', '{"bold":["/e/"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2abe183e-926a-4af7-a083-7eb7bc12e081', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. We admire the minister''s <u>passionate and dynamic</u> characteristics.', null, '["cruel and passive","kind and forceful","passive and harmless","harmless and cruel"]', 2, 'Passionate and dynamic; opposite = passive and harmless.', true, '2026-10-24 07:21:17.398', '2026-10-24 07:21:17.398', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. We admire the minister''s <u>passionate and dynamic</u> characteristics.', '["cruel and passive","kind and forceful","passive and harmless","harmless and cruel"]', 'Passionate and dynamic; opposite = passive and harmless.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2ad3661e-8df0-4c59-8f5e-5bbc74e1c9b1', 'Physics', 'JAMB', null, 2003, null, 'The table shows the saturation vapour pressure (S.V.P.) against temperature in a certain town: T (°C): 0, 5, 10, 15, 20, 40, 60; S.V.P. (mmHg): 4.58, 6.51, 8.94, 12.67, 17.50, 55.10, 149.00. If the vapour pressure in this town at 20 °C is 10 mmHg, what is the relative humidity?', null, '["57.0%","17.5%","10.0%","170.0%"]', 0, 'Relative humidity = (vapour pressure/S.V.P.) x 100 = (10/17.50) x 100 ≈ 57%.', true, '2026-10-12 19:15:56.224', '2026-10-12 19:15:56.224', null, null, null, 'The table shows the saturation vapour pressure (S.V.P.) against temperature in a certain town: T (°C): 0, 5, 10, 15, 20, 40, 60; S.V.P. (mmHg): 4.58, 6.51, 8.94, 12.67, 17.50, 55.10, 149.00. If the vapour pressure in this town at 20 °C is 10 mmHg, what is the relative humidity?', '["57.0%","17.5%","10.0%","170.0%"]', 'Relative humidity = (vapour pressure/S.V.P.) x 100 = (10/17.50) x 100 ≈ 57%.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2ad4ebbd-fc5d-43b2-a685-92c1f5fb31a5', 'Physics', 'JAMB', null, 1984, null, 'A small steel needle is carefully floated on water in a beaker. When a few drops of kerosene are introduced into the water the needle sinks. Which of the following statements correctly explain(s) the observation?
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2ad63802-a087-4be4-b3ff-b76d19761b2e', 'Literature in English', 'JAMB', null, 2026, null, 'In Still I Rise, the imagery ''like dust, I''ll rise'' primarily conveys', null, '["Fragility and weakness","Social stagnation","Environmental awareness","Inevitability of resilience and persistence"]', 3, 'The imagery conveys the inevitability of resilience and persistence.', true, '2026-09-12 11:09:54.688', '2026-09-12 11:09:54.688', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2adfe4b8-366d-40f9-8531-0d35f1e09a6b', 'Physics', 'JAMB', null, 2026, null, 'An object is weighed at different locations on the Earth. What will be the right observation?', null, '["Both the mass and weight vary","The weight is constant while the mass varies","The mass is constant while the weight varies","Both the mass and weight are constant"]', 2, 'The mass of an object is constant everywhere, but its weight varies with the local value of g. Since g varies slightly with latitude and altitude, weight varies at different locations on Earth.', true, '2026-09-10 10:56:48.705', '2026-09-10 10:56:48.705', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2ae5db77-bb3b-4da0-8973-6c85cf14eb3e', 'Biology', 'JAMB', null, 2026, null, 'The theory of natural selection was developed by', null, '["Lamarck and Darwin","Darwin and Wallace","Wallace and Mendel","Mendel and Lamarck"]', 1, 'The theory of natural selection was developed by Charles Darwin and Alfred Russel Wallace. They independently conceived the same theory of evolution by natural selection. Lamarck proposed inheritance of acquired characteristics. Mendel discovered the principles of heredity. Wallace and Darwin presented their joint paper in 1858, and Darwin published ''On the Origin of Species'' in 1859.', true, '2026-09-09 03:19:18.823', '2026-09-09 03:19:18.823', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2af9a0ec-7a4c-458e-b724-78db99f8577e', 'Biology', 'JAMB', null, 2026, null, 'The tissue not found in the stem of monocots is', null, '["cambium","pericycle","pith","phloem"]', 0, 'Cambium is the lateral meristem responsible for secondary growth, which is typically absent in monocot stems. Monocots generally do not undergo secondary thickening as seen in dicots, so they lack a vascular cambium. The pericycle (II) is present (though may be inconspicuous), pith (III) is present in many monocot stems (often with scattered vascular bundles), and phloem (IV) is always present in vascular tissues. The absence of cambium means monocot stems typically cannot increase in girth through secondary growth, though some monocots develop secondary growth through other mechanisms.', true, '2026-09-09 03:18:40.013', '2026-09-09 03:18:40.013', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2afae959-db06-4815-bb3b-eb3b3274bb3f', 'Chemistry', 'JAMB', null, 2026, null, 'In the electrolysis of acidified water (I) electrolyte becomes more acidic (II) electrolyte becomes dilute (III) hydrogen gas is gotten at the anode (IV) oxygen is gotten at the anode', null, '["I, IV","II, III","II, III","II, IV"]', 0, 'The electrolyte becomes more acidic, and oxygen is at the anode.', true, '2026-09-12 11:36:07.59', '2026-09-12 11:36:07.59', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2afc304c-a326-47f6-89ac-aaf9558f680f', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Rich citizens are often <u>niggardly</u> in their ways.', null, '["beggarly","sordid","miserly","pompous"]', 2, 'Niggardly = miserly.', true, '2026-10-24 01:01:41.608', '2026-10-24 01:01:41.608', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Rich citizens are often <u>niggardly</u> in their ways.', '["beggarly","sordid","<u>miserly</u>","pompous"]', '<b>Niggardly</b> = <b>miserly</b>.', '{}');
