insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2bb04c52-fb50-4559-9301-e48b03b40849', 'Biology', 'JAMB', null, 2026, null, 'In a population of living things, the parameters of size, height, weight and colour are examples of', null, '["discontinuous variations","continuous variations","physiological variations","non-heritable variations"]', 1, 'In a population, the parameters of size, height, weight, and colour are examples of continuous variations. These traits show a range of values with no distinct categories (a gradient from one extreme to the other). Continuous variation is often controlled by multiple genes (polygenic inheritance) and influenced by environmental factors. Discontinuous variations show distinct, non-overlapping categories (like blood groups).', true, '2026-09-09 03:19:28.307', '2026-09-09 03:19:28.307', null, null, null, null, null, null, null);
