insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2bc7dcc9-b033-438e-96ae-64709794a751', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The Federal Government approved a new salary structure as <u>an incentive</u> for the Nigerian workers.', null, '["a reward","an encouragement","a package","an advance"]', 1, 'Incentive = an encouragement.', true, '2026-10-24 01:01:49.656', '2026-10-24 01:01:49.656', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The Federal Government approved a new salary structure as <u>an incentive</u> for the Nigerian workers.', '["a reward","<u>an encouragement</u>","a package","an advance"]', '<b>Incentive</b> = <b>an encouragement</b>.', '{}');
