insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2be19581-a4d3-4a4b-b6f1-1e3cb749ecde', 'Chemistry', 'JAMB', null, 2026, null, 'Bond dissociation energy of 500 KJ mol⁻¹ may be assigned to', null, '["ionic bonding","covalent bonding","hydrogen bonding","metallic bonding","van-der-waals bonding"]', 1, '500 kJ/mol is typical of covalent bonding.', true, '2026-09-12 11:36:09.266', '2026-09-12 11:36:09.266', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2be403c5-b861-4749-8179-5d3e7d633a7a', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). It was surprising how we <u>took to the stranger</u> at once.', null, '["talked to long with","introduced ourselves to","formed a liking for","started fighting"]', 2, '''Took to'' = formed a liking for.', true, '2026-10-24 01:04:22.224', '2026-10-24 01:04:22.224', null, null, null, '(Choose the most appropriate interpretation). It was surprising how we <u>took to the stranger</u> at once.', '["talked to long with","introduced ourselves to","<u>formed a liking for</u>","started fighting"]', '''<b>Took to</b>'' = <b>formed a liking for</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2bf43195-cf62-4750-8e52-a86d11399f75', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Moses led the children of Israel through the', null, '["Sahara desert","Lion''s den","Dead sea","Valley of the Shadow of Death","Red Sea"]', 4, 'Moses led the children of Israel through the Red Sea. God parted the waters of the Red Sea, allowing the Israelites to cross on dry ground, and then closed the waters over the pursuing Egyptian army.', true, '2026-09-12 09:45:59.381', '2026-09-12 09:45:59.381', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2bf7a5e5-9b8b-4554-8a5a-112b301307db', 'Physics', 'JAMB', null, 1990, null, 'A particle of mass M which is at rest splits up into two. If the mass and velocity of one of the particles are m and v respectively, calculate the velocity of the second particle.', null, '["mv/M","Mv/(M - m)","Mv/(M + m)","mv/(M - m)"]', 3, 'Momentum is conserved: 0 = mv + (M - m)V, so the second particle has speed V = mv/(M - m), in the opposite direction.', true, '2026-10-12 19:15:30.44', '2026-10-12 19:15:30.44', null, null, null, 'A particle of mass M which is at rest splits up into two. If the mass and velocity of one of the particles are m and v respectively, calculate the velocity of the second particle.', '["mv/M","Mv/(M - m)","Mv/(M + m)","mv/(M - m)"]', 'Momentum is conserved: 0 = mv + (M - m)V, so the second particle has speed V = mv/(M - m), in the opposite direction.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2bf84b6c-ba03-49f7-80b3-356be5fe5f40', 'Physics', 'JAMB', null, 2026, null, 'The direction of the electric field at a point is the direction of', null, '["force on a positive test charge","Force on a negative test charge","Motion of electrons","Flow of current"]', 0, 'The direction of the electric field at a point is the direction of the force on a positive test charge placed at that point. Electric field lines point away from positive charges and toward negative charges.', true, '2026-09-10 10:56:38.812', '2026-09-10 10:56:38.812', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2c02f6ea-e737-4c91-a376-9153cfdac453', 'English Language', 'JAMB', null, 2007, null, 'We heard the <u>__________</u> of brakes which was followed by a crashing noise.', null, '["screaming","screeching","scrapping","streaking"]', 1, 'Correct spelling: screeching.', true, '2026-10-24 07:21:32.995', '2026-10-24 07:21:32.995', null, null, null, 'We heard the <u>__________</u> of brakes which was followed by a crashing noise.', '["screaming","screeching","scrapping","streaking"]', 'Correct spelling: screeching.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2c04932c-9c7d-4536-9cf6-031f8c18a2bf', 'Yoruba', 'JAMB', null, 2002, null, 'Fí àmì-ohùn tó tòna sórí Olubóbótíríbó láti fùn un ní ìtumò tó péye.', null, '["Olúbóbótíríbò","Olúbóbótíríbò","Olúbóbótíríbò","Olúbóbótíríbò"]', 2, 'Olúbóbótíríbò ni àmì-ohùn tó tòna.', true, '2026-10-13 13:22:38.25', '2026-10-13 13:22:38.25', null, null, null, 'Fí àmì-ohùn tó tòna sórí Olubóbótíríbó láti fùn un ní ìtumò tó péye.', '["Olúbóbótíríbò","Olúbóbótíríbò","Olúbóbótíríbò","Olúbóbótíríbò"]', 'Olúbóbótíríbò ni àmì-ohùn tó tòna.', '{"bold":["Olúbóbótíríbò"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2c06eec0-b212-40be-9bb6-72f0989e93bd', 'Physics', 'JAMB', null, 1988, null, 'The amount of heat needed to raise the temperature of 10 kg of copper by 1 K is its', null, '["Specific heat capacity","Heat capacity","Latent heat","Internal heat."]', 1, 'Heat capacity is the heat needed to raise the temperature of a given body by 1 K. Specific heat capacity refers to 1 kg.', true, '2026-10-12 19:15:27.371', '2026-10-12 19:15:27.371', null, null, null, 'The amount of heat needed to raise the temperature of 10 kg of copper by 1 K is its', '["Specific heat capacity","Heat capacity","Latent heat","Internal heat."]', 'Heat capacity is the heat needed to raise the temperature of a given body by 1 K. Specific heat capacity refers to 1 kg.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2c0e17b1-23ab-43f5-a2e7-a62d9319a57c', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'In Timothy, Paul urges Christians to pray for Kings and those in authority for the achievement of', null, '["a successful Christian life","godly and acceptable life","peace and exaltation in life","quiet and peaceable life"]', 3, 'Paul urges Christians to pray for kings and all in high positions, that they may lead a quiet and peaceable life, godly and respectful in every way.', true, '2026-09-12 09:46:01.94', '2026-09-12 09:46:01.94', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2c113040-42a3-4e00-b172-55e39e2c1aa5', 'Government', 'JAMB', null, 2026, null, 'The zoning system in Nigerian politics refers to', null, '["the rotation of power among different regions","the process of selecting party leaders","the allocation of campaign funds","the system of proportional representation"]', 0, 'Zoning refers to the rotation of power among different regions.', true, '2026-09-12 11:24:30.019', '2026-09-12 11:24:30.019', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2c14429b-6ff1-45ff-bc64-8f2456bf1aa9', 'Yoruba', 'JAMB', null, 2007, null, 'Çgbê-n-bígbo, àbí àjùmõ-gbélé-põ? Ta ló lè pèdè yìí síní?', null, '["Òrë","Ajunilò","Ojúgbà çni","Òmõ-çgbê çni."]', 1, 'Ajunilò ló lè pèdè yìí síní.', true, '2026-10-13 13:23:32.559', '2026-10-13 13:23:32.559', null, null, null, 'Çgbê-n-bígbo, àbí àjùmõ-gbélé-põ? Ta ló lè pèdè yìí síní?', '["Òrë","Ajunilò","Ojúgbà çni","Òmõ-çgbê çni."]', 'Ajunilò ló lè pèdè yìí síní.', '{"bold":["Ajunilò"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2c177b61-26ae-4f0e-8b33-727193b13ccc', 'Physics', 'JAMB', null, 2002, null, 'A copper cube weighs 0.25 N in air, 0.17 N when completely immersed in paraffin oil and 0.15 N when completely immersed in water. The ratio of upthrust in oil to upthrust in water is', null, '["13 : 10","7 : 10","3 : 5","4 : 5"]', 3, 'Upthrust in oil = 0.25 - 0.17 = 0.08 N. Upthrust in water = 0.25 - 0.15 = 0.10 N. Ratio = 8 : 10 = 4 : 5.', true, '2026-10-12 19:15:52.782', '2026-10-12 19:15:52.782', null, null, null, 'A copper cube weighs 0.25 N in air, 0.17 N when completely immersed in paraffin oil and 0.15 N when completely immersed in water. The ratio of upthrust in oil to upthrust in water is', '["13 : 10","7 : 10","3 : 5","4 : 5"]', 'Upthrust in oil = 0.25 - 0.17 = 0.08 N. Upthrust in water = 0.25 - 0.15 = 0.10 N. Ratio = 8 : 10 = 4 : 5.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2c3c03dd-5f96-4906-96f6-aa27ecf4d2d8', 'Physics', 'JAMB', null, 2026, null, 'A body of mass 10kg on a smooth inclined plane is connected to a smooth pulley to a mass of 15kg as shown below, the acceleration of the system is', 'https://res.cloudinary.com/kwi1uv0g/image/upload/v1789038724/questions/sfgjd7plsludqnubsxli.png', '["1/4 g","8/25 g","1/2 g","2/5 g","3/4 g"]', 3, 'Using Newton''s second law for the system: a = (m₂ - m₁ sin θ)g / (m₁ + m₂). Assuming θ = 30°: a = (15 - 10×0.5)g / (10+15) = (15-5)g/25 = 10g/25 = 2/5 g.', true, '2026-09-10 11:19:26.047', '2026-09-10 11:19:26.047', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2c3f0499-2641-4d21-8509-42b06c242623', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The lecturer <u>maintained</u> his usual good humour in spite of the cat-calls and the rude behaviour of his students.', null, '["provoked","obtained","kept","lost","improved"]', 2, 'Maintained = kept.', true, '2026-10-24 01:01:40.638', '2026-10-24 01:01:40.638', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The lecturer <u>maintained</u> his usual good humour in spite of the cat-calls and the rude behaviour of his students.', '["provoked","obtained","<u>kept</u>","lost","improved"]', '<b>Maintained</b> = <b>kept</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2c3fd8bf-849b-4f27-be35-efd0ab2672fa', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). Employees have been <u>urged to desist from witch-hunting and character assassination</u>.', null, '["commanded to stop hunting witches","ordered to stop assassinating witches","entreated not to accuse individuals unjustly and maliciously","informed to resist witch hunters and character assassins","urged to desist from barbaric acts"]', 2, '''Character assassination'' = malicious accusation.', true, '2026-10-24 01:02:02.638', '2026-10-24 01:02:02.638', null, null, null, '(Choose the most appropriate interpretation). Employees have been <u>urged to desist from witch-hunting and character assassination</u>.', '["commanded to stop hunting witches","ordered to stop assassinating witches","<u>entreated not to accuse individuals unjustly and maliciously</u>","informed to resist witch hunters and character assassins","urged to desist from barbaric acts"]', '''<b>Character assassination</b>'' = <b>malicious accusation</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2c409807-9ec9-4248-9575-7368c67d1f11', 'Government', 'JAMB', null, 2026, null, 'A group of people with different natures, opinions, and goals with complicated networks of social relation is', null, '["a union","an association","a society","a state"]', 2, 'A society is a group with different natures and complicated social relations.', true, '2026-09-12 11:24:31.681', '2026-09-12 11:24:31.681', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2c41b4cb-619f-4af0-9ac4-dc7bd5d6fd5f', 'Financial Accounting', 'UTME', null, 2002, null, 'The Assets and Liabilities of Udo Co. Ltd. as at 31st December, 2000. Creditors 50000 Debtors 46000 Loan 10000 Stock 20000 Motor vehicle 120000 Building 70000 Accrued wages 30000 Bank 25000. The liabilities of Udo Co. Ltd is', 'https://res.cloudinary.com/kwi1uv0g/image/upload/v1791840710/questions/qjse54gjfnvhxgj5clxp.jpg', '["N 180,000","N 181,000","N 177,000","N 110,000"]', 0, 'Liabilities of Udo Co. Ltd: Creditors 50,000 + Loan 100,000 + Accrued Wages 30,000 = 180,000.', true, '2026-10-12 21:59:57.138', '2026-10-12 21:59:57.138', null, null, null, 'The Assets and Liabilities of Udo Co. Ltd. as at 31st December, 2000. Creditors 50000 Debtors 46000 Loan 10000 Stock 20000 Motor vehicle 120000 Building 70000 Accrued wages 30000 Bank 25000. The liabilities of Udo Co. Ltd is', '["<b>N 180,000</b>","N 181,000","N 177,000","N 110,000"]', 'Liabilities of Udo Co. Ltd: Creditors 50,000 + Loan 100,000 + Accrued Wages 30,000 = <b>180,000</b>.', '{"bold":["180,000"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2c52ac2e-5bc6-46b0-9039-89d087df8231', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'According to Paul, spiritual gifts, if properly employed, help in', null, '["attracting converts","hastening miracles","identifying evil doers","edifying the church"]', 3, 'According to Paul in 1 Corinthians 12 and 14, spiritual gifts are given for the common good and the edification of the church. They are meant to build up the body of Christ.', true, '2026-09-12 09:46:04.135', '2026-09-12 09:46:04.135', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2c570aa4-494f-44c0-a8a4-64fff4a8d2aa', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Lami and her husband are simply <u>munificent</u>.', null, '["niggardly","angry","happy","weighty"]', 0, 'Munificent = generous; opposite = niggardly.', true, '2026-10-24 07:21:28.916', '2026-10-24 07:21:28.916', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Lami and her husband are simply <u>munificent</u>.', '["niggardly","angry","happy","weighty"]', 'Munificent = generous; opposite = niggardly.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2c5da2a7-ffb3-4505-a6cf-0cbef7a89976', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Mr. Ojo has a <u>fickle</u> character.', null, '["a genuine","a stable","an impelled","an unpredictable"]', 3, 'Fickle = unpredictable.', true, '2026-10-24 01:04:11.062', '2026-10-24 01:04:11.062', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Mr. Ojo has a <u>fickle</u> character.', '["a genuine","a stable","an impelled","<u>an unpredictable</u>"]', '<b>Fickle</b> = <b>an unpredictable</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2c5fd9ec-b1cb-43f2-8129-d93801e3d21e', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). This time, she will be competing <u>with a dark horse</u>.', null, '["a weak and low-spirited person","a person about whose abilities little is known","a person who is a formidable candidate","a person as strong as a horse"]', 1, '''A dark horse'' = person whose abilities little is known.', true, '2026-10-24 01:04:21.631', '2026-10-24 01:04:21.631', null, null, null, '(Choose the most appropriate interpretation). This time, she will be competing <u>with a dark horse</u>.', '["a weak and low-spirited person","<u>a person about whose abilities little is known</u>","a person who is a formidable candidate","a person as strong as a horse"]', '''A <b>dark horse</b>'' = <b>person whose abilities little is known</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2c6e8fc8-88f5-42f0-9194-a695b6a07908', 'Literature in English', 'JAMB', null, 2026, null, 'The poet compares old age to', null, '["a shadowy evening","a cloudless dawn","a raging storm","a cold winter"]', 0, 'In ''Hearty Garlands,'' the poet compares old age to a shadowy evening. This metaphor suggests that old age is a time of fading light, reflection, and approaching night (death). It is a common poetic comparison that conveys the gentle decline of life. A cloudless dawn suggests youth and hope, a raging storm suggests conflict, and a cold winter suggests hardship.', true, '2026-09-10 10:47:54.315', '2026-09-10 10:47:54.315', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2c70345c-15c0-4ff2-89be-4a9bd66a520b', 'Economics', 'JAMB', null, 2026, null, 'Economics, according to Lionel C. Robbins is defined as', null, '["The study of human behaviour as a relationship between scarce resources","A social science which studies human behaviour as a relationship between ends and scarce means which has alternative uses","It''s an enquiry into nature and causes of wealth of Nations","it''s a science of human behaviour"]', 1, 'Robbins defined economics as the science which studies human behaviour as a relationship between ends and scarce means with alternative uses.', true, '2026-09-12 11:00:10.842', '2026-09-12 11:00:10.842', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2c752ab7-c391-40e1-9d3a-56af6f01dd1c', 'Economics', 'JAMB', null, 2026, null, 'When the price elasticity of supply coefficient is greater than 1, the supply of the product is said to be', null, '["Perfectly elastic","Perfectly inelastic","Elastic","Inelastic","Unit elastic"]', 2, 'When the price elasticity of supply coefficient is greater than 1, supply is elastic. Elastic supply means that quantity supplied is responsive to price changes—a small change in price leads to a proportionately larger change in quantity supplied. Perfectly elastic supply (Es = ∞) is a horizontal line. Perfectly inelastic supply (Es = 0) is a vertical line.', true, '2026-09-10 10:41:20.723', '2026-09-10 10:41:20.723', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2c864cc6-590a-42c0-b10d-ac4df5c61a7a', 'English Language', 'JAMB', null, 2007, null, 'Mumps <u>______</u> a common childhood disease.', null, '["are","is","were","have been"]', 1, '''Mumps'' singular â†’ is.', true, '2026-10-24 01:02:16.166', '2026-10-24 01:02:16.166', null, null, null, 'Mumps <u>______</u> a common childhood disease.', '["are","<u>is</u>","were","have been"]', '''<b>Mumps</b>'' singular â†’ <b>is</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2c86d30a-c550-4346-9a54-3821aa524d5d', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'According to the Gospel of Mark, after Jesus was baptized, He', null, '["was transfigured","preached to those around river Jordan","performed His first miracle","headed to the wilderness","called His first disciple"]', 3, 'The Spirit drove Jesus into the wilderness after His baptism.', true, '2026-09-12 10:42:09.567', '2026-09-12 10:42:09.567', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2c98463c-1204-423d-bf82-60ce6d6eafbb', 'Literature in English', 'JAMB', null, 2026, null, 'In Still I Rise, the repetition of ''I rise'' is an example of', null, '["Alliteration","Anaphora","Euphemism","Irony"]', 1, 'The repetition of ''I rise'' is anaphora.', true, '2026-09-12 11:12:03.966', '2026-09-12 11:12:03.966', null, null, null, null, null, null, null);
