insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2cc78a58-e8a0-45b9-8157-3bee2dd60773', 'Biology', 'JAMB', null, 2012, null, 'Which of the following is a polysaccharide?', null, '["Glucose","Sucrose","Maltose","Cellulose."]', 3, 'Cellulose is a polysaccharide.', true, '2026-10-12 20:59:44.792', '2026-10-12 20:59:44.792', null, null, null, 'Which of the following is a polysaccharide?', '["Glucose","Sucrose","Maltose","Cellulose."]', 'Cellulose is a polysaccharide.', '{"bold":["Cellulose"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2cdc11d4-2b23-40d8-8d87-5431037ef644', 'Physics', 'JAMB', null, 2000, null, 'In a pure semiconductor, the number of electrons in the conduction band is', null, '["Equal to the number of holes in the valence band","Greater than the number of holes in the valence band","Less than the number of holes in the valence band","Twice the number of holes in the valence band."]', 0, 'Each electron that jumps to the conduction band leaves one hole behind in the valence band, so the numbers are equal.', true, '2026-10-12 19:15:50.396', '2026-10-12 19:15:50.396', null, null, null, 'In a pure semiconductor, the number of electrons in the conduction band is', '["Equal to the number of holes in the valence band","Greater than the number of holes in the valence band","Less than the number of holes in the valence band","Twice the number of holes in the valence band."]', 'Each electron that jumps to the conduction band leaves one hole behind in the valence band, so the numbers are equal.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2ce0aca8-45d6-4373-8b89-1a9511c72f37', 'Literature in English', 'JAMB', null, 2026, null, 'The predominant use of the third person pronoun in a novel creates a', null, '["Sense of detachment on the part of the writer","Sense of detachment on the part of the reader","Psychological affinity with the characters","Balance of opinion among the characters"]', 0, 'Third person creates detachment on the writer''s part.', true, '2026-09-12 11:13:53.826', '2026-09-12 11:13:53.826', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2ce2b1ab-96c1-4f4e-94f7-e4dc5a605f17', 'Literature in English', 'JAMB', null, 2026, null, 'In Not My Business, the repeated phrase ''What business of mine is it...'' serves as', null, '["Irony exposing societal indifference","Alliteration for sound effect","Euphemism for fear","Metaphor for oppression"]', 0, 'The phrase is irony exposing societal indifference.', true, '2026-09-12 11:05:27.202', '2026-09-12 11:05:27.202', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2ce690b0-4fd1-45c8-9d1f-d2643cb827c9', 'Biology', 'JAMB', null, 2010, null, 'The primary structure responsible for pumping blood for circulation through the mammalian circulatory systems is the', null, '["veins","right auricle","arteries","left ventricle"]', 3, 'The left ventricle pumps blood for circulation.', true, '2026-10-12 20:59:39.549', '2026-10-12 20:59:39.549', null, null, null, 'The primary structure responsible for pumping blood for circulation through the mammalian circulatory systems is the', '["veins","right auricle","arteries","left ventricle"]', 'The left ventricle pumps blood for circulation.', '{"bold":["left ventricle"],"italic":[],"underline":[],"fillBlanks":[]}');
