insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2d110014-e2b1-44f7-b02c-524d8ca11fc9', 'General Mathematics', 'JAMB', null, 2026, null, 'If a circular paper disc is trimmed in such a way that its circumference is reduced in the ratio 2:5, in what ratio is the surface area reduced?', null, '["8:125","2:5","8:25","4:25"]', 3, 'Circumference ratio = 2:5, so radius ratio = 2:5. Area ratio = (2:5)² = 4:25.', true, '2026-09-12 11:43:46.214', '2026-09-12 11:43:46.214', null, null, null, null, null, null, null);
