insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2d7c25c5-ed05-44eb-a463-e5860af3adba', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The Principal was filled with <u>scorn</u> when we gave our reason for coming late.', null, '["sympathy","contempt","pity","anger"]', 0, 'Scorn = contempt; opposite = sympathy.', true, '2026-10-24 07:21:25.734', '2026-10-24 07:21:25.734', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The Principal was filled with <u>scorn</u> when we gave our reason for coming late.', '["sympathy","contempt","pity","anger"]', 'Scorn = contempt; opposite = sympathy.', '{}');
