insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2d8f5236-ae3e-41a8-84af-ae90af980cdf', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). Olu and Ade <u>are about to come to blows</u>', null, '["They are about to agree with each other","They are about to accept other people''s opinion","They are about to hit each other","They are about to disagree with other people''s opinion"]', 2, '''Come to blows'' = start fighting/hit each other.', true, '2026-10-24 01:04:24.041', '2026-10-24 01:04:24.041', null, null, null, '(Choose the most appropriate interpretation). Olu and Ade <u>are about to come to blows</u>', '["They are about to agree with each other","They are about to accept other people''s opinion","<u>They are about to hit each other</u>","They are about to disagree with other people''s opinion"]', '''<b>Come to blows</b>'' = <b>start fighting/hit each other</b>.', '{}');
