insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2da83a64-9ffc-4d60-bcb6-b1eaf98bf373', 'General Mathematics', 'JAMB', null, 2026, null, 'If |2 3; 5 3x| = |4 1; 3 2x|. Find the value of x', null, '["-6","6","-12","12"]', 1, '6x - 15 = 8x - 3. -12 = 2x. x = -6. The answer is (A) -6.', true, '2026-09-12 11:44:16.285', '2026-09-12 11:44:16.285', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2dac944d-2716-46bd-9be1-417c2244125f', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). The story has to be taken <u>with a grain of salt</u>. This means that _______________', null, '["you need some salt to listen to the story","there is no salt in the story","the story is questionable","the story is true","you have too much salt in the story"]', 2, '''With a grain of salt'' means with scepticism.', true, '2026-10-24 01:02:00.193', '2026-10-24 01:02:00.193', null, null, null, '(Choose the most appropriate interpretation). The story has to be taken <u>with a grain of salt</u>. This means that _______________', '["you need some salt to listen to the story","there is no salt in the story","<u>the story is questionable</u>","the story is true","you have too much salt in the story"]', '''<b>With a grain of salt</b>'' means with scepticism.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2daf553b-d629-4dbe-a29c-b71971c64919', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Abraham''s faith and works were better illustrated when he', null, '["took Lot with him to Canaan","offered his son, Isaac on the altar","parted ways with Lot","spoke with angels"]', 1, 'Abraham''s faith and works were better illustrated when he offered his son Isaac on the altar. James uses this as an example of how faith was active along with works, and faith was completed by works.', true, '2026-09-12 09:46:10.28', '2026-09-12 09:46:10.28', null, null, null, null, null, null, null);
