insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2e8d9636-04c7-4ee8-8c6a-18d0be2a7317', 'Financial Accounting', 'UTME', null, 2004, null, 'Calculate the prime cost', 'https://res.cloudinary.com/kwi1uv0g/image/upload/v1791841865/questions/duqei6gxqpqc1un4ggty.jpg', '["N50 000","N68 000","N70 000","N75 000"]', 1, 'Prime cost is total of all the element of costs; Material, labour and Expenses. Raw Material Used 18000 + Direct Labour 50000 = Prime Cost 68000.', true, '2026-10-12 22:00:02.985', '2026-10-12 22:00:02.985', null, null, null, 'Calculate the prime cost', '["N50 000","<b>N68 000</b>","N70 000","N75 000"]', 'Prime cost is total of all the element of costs; Material, labour and Expenses. Raw Material Used 18000 + Direct Labour 50000 = Prime Cost <b>68000</b>.', '{"bold":["68000"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2e8edf55-7bfa-4052-b25a-e7bc3a7ff3e5', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Why did the Pharisees criticize Jesus during the triumphal entry?', null, '["They were jealous of Jesus'' popularity","They thought Jesus was a Roman sympathizer","They believed Jesus was claiming to be the Messiah","They were upset about the disruption caused by the crowd"]', 0, 'The Pharisees were jealous of Jesus'' popularity.', true, '2026-09-12 10:41:48.716', '2026-09-12 10:41:48.716', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2e980ba3-527a-40df-b95a-eb98cdf61410', 'Physics', 'JAMB', null, 2002, null, 'A transistor is used in the amplification of signals because it', null, '["Allows doping","Controls the flow of current","Contains electron and hole carriers","Consumes a lot of power"]', 1, 'In a transistor a small base current controls a larger collector current, which makes amplification possible.', true, '2026-10-12 19:15:54.567', '2026-10-12 19:15:54.567', null, null, null, 'A transistor is used in the amplification of signals because it', '["Allows doping","Controls the flow of current","Contains electron and hole carriers","Consumes a lot of power"]', 'In a transistor a small base current controls a larger collector current, which makes amplification possible.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2ea4b198-0af8-4bd5-98f8-68a72d3e8be1', 'General Mathematics', 'JAMB', null, 2026, null, 'If x⁴ - kx³ + 10x² + lx - 3 is divisible by (x-1) and when divided by (x+2) the remainder is 27. Find k and l', null, '["k=-7, l=-15","k=-15, l=-7","k=-21/5, l=-61/5","k=-5/3, l=19/3","k=5/3, l=-19/3"]', 0, 'P(1) = 1-k+10+l-3 = 0. -k+l = -8. P(-2) = 16+8k+40-2l-3 = 27. 8k-2l = -26. 4k-l = -13. Solving: 3k = -21. k = -7. l = -15.', true, '2026-09-12 11:44:22.865', '2026-09-12 11:44:22.865', null, null, null, null, null, null, null);
