insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2eb299d7-5246-4bce-b026-0aad2a66f37c', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Before Amos became a prophet, he was a...', null, '["Judge","Seer","Tent Maker","Farmer"]', 3, 'Amos 1:1 and Amos 7:14 state that Amos was a herdsman/shepherd and a dresser of sycamore fig trees in Tekoa before God called him to prophesy to Israel.', true, '2026-09-09 17:18:23.56', '2026-09-09 17:18:23.56', null, null, null, null, null, null, null);
