insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2f03bc1f-aad6-40aa-8a34-cafebe099870', 'Physics', 'JAMB', null, 1989, null, 'From the kinetic theory of gases, temperature is a', null, '["Form of energy and is proportional to the total kinetic energy of the molecules.","Form of energy and is proportional to the average kinetic energy of the molecules.","Physical property and is proportional to the total kinetic energy of the molecules.","Physical property and is proportional to the average energy of the molecules."]', 3, 'Temperature is a physical property (not a form of energy) that is proportional to the average kinetic energy of the molecules.', true, '2026-10-12 19:15:29.195', '2026-10-12 19:15:29.195', null, null, null, 'From the kinetic theory of gases, temperature is a', '["Form of energy and is proportional to the total kinetic energy of the molecules.","Form of energy and is proportional to the average kinetic energy of the molecules.","Physical property and is proportional to the total kinetic energy of the molecules.","Physical property and is proportional to the average energy of the molecules."]', 'Temperature is a physical property (not a form of energy) that is proportional to the average kinetic energy of the molecules.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2f0eb8ea-f1e4-44b6-a47f-fcf6d5d7ea28', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Moses was nursed by', null, '["Pharaoh''s daughter","his mother","Shiphrah","Puah"]', 1, 'Moses was nursed by his own mother. When Pharaoh''s daughter found the baby Moses, Moses'' sister Miriam suggested a Hebrew woman to nurse him. Pharaoh''s daughter agreed, and Miriam brought Moses'' mother, who nursed him for her.', true, '2026-09-12 09:46:09.561', '2026-09-12 09:46:09.561', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2f11dfd3-467e-434c-b832-bfacddee94ff', 'Biology', 'JAMB', null, 2026, null, 'The surest way to combine the best qualities of both parents in the offspring is by', null, '["cross breeding","pure breeding","selective breeding","cutting down and clearing of trees"]', 2, 'Selective breeding (artificial selection) is the intentional mating of individuals with desired traits to produce offspring with a combination of those traits. Over generations, this process allows breeders to amplify desirable characteristics while reducing undesirable ones. Cross breeding is mating different breeds or species, which can combine qualities but is less predictable. Pure breeding maintains specific traits but limits variation. Selective breeding gives breeders the most control over trait combination and is widely used in agriculture for improved crop yield, livestock quality, and disease resistance.', true, '2026-09-09 03:18:19.212', '2026-09-09 03:18:19.212', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2f154142-cda5-499e-8d0f-cee0d24fcde2', 'English Language', 'JAMB', null, 2024, null, '2', null, '["inflation","costs","deflation","devaluation"]', 0, 'Inflation directly affects living standards by raising prices.', true, '2026-09-18 10:17:48.765', '2026-09-18 10:17:48.765', '274e150d-fca1-4c72-9c33-e5e119534874', 2, 'CLOZE', null, null, null, null);
