insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2fe553c2-b947-4bf3-87a6-640d70acd2a0', 'Economics', 'JAMB', null, 2026, null, 'The following are problems associated with National Income computation except', null, '["Changes in price level","Depreciation","Double counting","Adequate statistical data","Illegal incomes"]', 3, 'Adequate statistical data is NOT a problem associated with National Income computation; it is a solution or requirement for accurate computation. Problems include changes in price level (inflation), depreciation (capital consumption), double counting, and illegal incomes (not captured). The lack of adequate statistical data is a problem, but the presence of adequate data is not a problem.', true, '2026-09-10 10:41:21.314', '2026-09-10 10:41:21.314', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2fecc5cb-bf8e-4a53-8eaf-0e94f542cec8', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Do you know one of the most <u>astounding</u> events of my life?', null, '["special","amazing","serious","outstanding"]', 1, 'Astounding = amazing.', true, '2026-10-24 01:01:46.372', '2026-10-24 01:01:46.372', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Do you know one of the most <u>astounding</u> events of my life?', '["special","<u>amazing</u>","serious","outstanding"]', '<b>Astounding</b> = <b>amazing</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2feced19-9bb9-4da5-b8ca-fb21e8a7ef10', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Despite his laxity in other matters, Ojo''s father <u>drew the line at</u> truancy.', null, '["favoured","rejected","emphasized","ignored"]', 0, 'Drew the line at = refused to allow; opposite = favoured.', true, '2026-10-24 07:21:21.901', '2026-10-24 07:21:21.901', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Despite his laxity in other matters, Ojo''s father <u>drew the line at</u> truancy.', '["favoured","rejected","emphasized","ignored"]', 'Drew the line at = refused to allow; opposite = favoured.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('2fff2c39-d9a0-4be5-bf3a-b796ed81d2d1', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Jankoli was dressed in an old <u>assortment</u> of clothes.', null, '["homogeneity","sameness","mÃ©lange","avalanche"]', 2, 'Assortment = mÃ©lange.', true, '2026-10-24 01:01:54.643', '2026-10-24 01:01:54.643', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Jankoli was dressed in an old <u>assortment</u> of clothes.', '["homogeneity","sameness","<u>mÃ©lange</u>","avalanche"]', '<b>Assortment</b> = <b>mÃ©lange</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3003436b-8b1b-4dc1-aa15-31a959e40e85', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The teacher announced that the class would be making a <u>fleeting</u> visit to the zoo.', null, '["routine","brief","long","guided"]', 2, 'Fleeting = brief; opposite = long.', true, '2026-10-24 07:21:20.704', '2026-10-24 07:21:20.704', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The teacher announced that the class would be making a <u>fleeting</u> visit to the zoo.', '["routine","brief","long","guided"]', 'Fleeting = brief; opposite = long.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3007d0d6-b5e4-4a9e-903d-8c68606cb0ca', 'Physics', 'JAMB', null, 2026, null, 'When a red rose flower is observed in blue light, what colour does the observer see?', null, '["red","blue","magenta","yellow"]', 0, 'A red rose appears red in blue light. Wait, that''s incorrect. A red rose reflects red light and absorbs other colours. In blue light, there is no red to reflect, so the rose appears black. But the options don''t include black. The closest answer based on the options is red, but the correct answer should be black. The document may have an error.', true, '2026-09-10 10:56:42.168', '2026-09-10 10:56:42.168', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3019d4e3-2953-4847-9072-6454fb243030', 'Chemistry', 'JAMB', null, 2026, null, 'A reaction take place spontaneously if', null, '["G=0","S<0 and H>0","H<ATs","G>0"]', 2, 'A reaction is spontaneous if ΔG < 0, which can occur when ΔH < TΔS.', true, '2026-09-12 11:36:02.483', '2026-09-12 11:36:02.483', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('301d51f4-3be9-4ccc-8d17-decdc3b385b4', 'English Language', 'JAMB', null, 2007, null, 'The students went on whispering in <u>__________</u> of the teacher', null, '["dishonour","disagreement","defiance","disobedience"]', 2, 'Correct spelling: defiance.', true, '2026-10-24 07:21:41.346', '2026-10-24 07:21:41.346', null, null, null, 'The students went on whispering in <u>__________</u> of the teacher', '["dishonour","disagreement","defiance","disobedience"]', 'Correct spelling: defiance.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('30297dfc-b064-4149-97f9-db5b4caa6833', 'Biology', 'JAMB', null, 2003, null, 'In mammalian males, the excretory and reproductive systems share the', null, '["ureter","vas deferens","urethra","testes"]', 2, 'The urethra is shared by excretory and reproductive systems.', true, '2026-10-12 20:59:32.927', '2026-10-12 20:59:32.927', null, null, null, 'In mammalian males, the excretory and reproductive systems share the', '["ureter","vas deferens","urethra","testes"]', 'The urethra is shared by excretory and reproductive systems.', '{"bold":["urethra"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('30362a4a-8238-4a02-a707-e0822ddee5c8', 'Government', 'JAMB', null, 2026, null, 'While political parties aim at forming a government, pressure groups aim at', null, '["imposing military rule","causing social unrest","influencing governmental decisions","controlling a nation''s economy"]', 2, 'Pressure groups aim at influencing governmental decisions.', true, '2026-09-12 11:24:22.982', '2026-09-12 11:24:22.982', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3041db5e-8e41-4cb8-bdbe-f82ff259a4cf', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. As these boys never act in public, the police are now worried about their <u>covert</u> activities.', null, '["evil","open","cryptic","ignoble"]', 1, 'Covert = secret; opposite = open.', true, '2026-10-24 07:21:22.306', '2026-10-24 07:21:22.306', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. As these boys never act in public, the police are now worried about their <u>covert</u> activities.', '["evil","open","cryptic","ignoble"]', 'Covert = secret; opposite = open.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('30457d1a-b818-4df0-9c05-f55ed37ed3ec', 'Physics', 'JAMB', null, 2026, null, 'Which of the following diagrams correctly represents the relationship between the time (T) of swing of a simple pendulum and its length (L)?', 'https://res.cloudinary.com/kwi1uv0g/image/upload/v1789039774/questions/dyibtnebewk6pw3jz7td.jpg', '["Graph A","Graph B","Graph C","Graph D"]', 1, 'For a simple pendulum, T = 2π√(L/g), so T² = (4π²/g)L. The graph of T² vs L gives a straight line through the origin. Graph B is correct.', true, '2026-09-10 11:30:19.531', '2026-09-10 11:30:19.531', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('305a208a-1fee-4494-a998-6b9264c0b8a3', 'Biology', 'JAMB', null, 2005, null, 'The population density of Tridax in an abandoned square farmland of side 200m was found to be 5 plants per m2. The population size of the plant on the farm is', null, '["40","1000","40000","200000"]', 3, 'Population size = 5 x (200 x 200) = 200000.', true, '2026-10-12 20:59:37.837', '2026-10-12 20:59:37.837', null, null, null, 'The population density of Tridax in an abandoned square farmland of side 200m was found to be 5 plants per m2. The population size of the plant on the farm is', '["40","1000","40000","200000"]', 'Population size = 5 x (200 x 200) = 200000.', '{"bold":["200000"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('305de162-0995-41f0-969d-80f3e9f73465', 'General Mathematics', 'JAMB', null, 2026, null, 'How many significant figures are there in the number 37,460,000?', null, '["5","4","8","6"]', 1, '37,460,000 has 4 significant figures (3,7,4,6).', true, '2026-09-12 11:43:55.282', '2026-09-12 11:43:55.282', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('305fac57-8add-4a61-8370-33cbc9d4b448', 'Government', 'JAMB', null, 2026, null, 'One of the greatest advocates of socialism was', null, '["Baron de Montesquieu","Karl Marx","A.V. Dicey","Adam Smith"]', 1, 'Karl Marx was a great advocate of socialism.', true, '2026-09-12 11:24:55.392', '2026-09-12 11:24:55.392', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('30664da9-dec3-4dc7-98ec-c3dfb2e17199', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. It was a good try but it didn''t <u>work out</u>.', null, '["come to","come off","come out","come for"]', 1, 'Work out = come off.', true, '2026-10-24 01:04:11.652', '2026-10-24 01:04:11.652', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. It was a good try but it didn''t <u>work out</u>.', '["come to","<u>come off</u>","come out","come for"]', '<b>Work out</b> = <b>come off</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('308287ed-2f77-4c40-8512-b6a58d5886d9', 'Government', 'JAMB', null, 2026, null, 'The .... is responsible for advising the president of Nigeria on the sovereignty and territorial Integrity of the country.', null, '["National Defence Council","Council of State","National Security Council","Federal Executive Council"]', 1, 'The Council of State advises the president on sovereignty and territorial integrity.', true, '2026-09-12 11:23:57.911', '2026-09-12 11:23:57.911', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3086e24f-1a3c-486e-be82-db4a621223bf', 'Chemistry', 'JAMB', null, 2026, null, 'Sulphur (IV) oxide bleaches by', null, '["reduction","oxidation","hydration","adsorption"]', 0, 'SO₂ bleaches by reduction.', true, '2026-09-12 11:36:05.115', '2026-09-12 11:36:05.115', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('30886df4-4aa5-49de-a431-5645a25a76b7', 'General Mathematics', 'JAMB', null, 2026, null, 'Find the sum to infinity of the following sequence: 1, 9/10, (9/10)², (9/10)³', null, '["1/10","9/10","10/9","10"]', 3, 'S∞ = a/(1-r) = 1/(1-9/10) = 1/(1/10) = 10.', true, '2026-09-12 11:43:48.465', '2026-09-12 11:43:48.465', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('30893b94-c1e3-480b-87bb-e0291320af3c', 'Biology', 'JAMB', null, 2026, null, 'Which of the following organs regulates the levels of water, salts, hydrogen ions, and urea in mammals?', null, '["kidney","colon","bladder","liver"]', 0, 'The kidney is the primary organ that regulates water, salts, hydrogen ions (pH), and urea in mammals through the processes of filtration, reabsorption, and secretion. It maintains homeostasis by adjusting the composition and volume of blood plasma. The colon absorbs water from undigested material. The bladder stores urine but does not regulate its composition. The liver produces urea from ammonia but does not regulate its concentration in blood. The kidneys are essential for maintaining fluid and electrolyte balance (osmoregulation) and removing metabolic waste.', true, '2026-09-09 03:18:41.314', '2026-09-09 03:18:41.314', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('308fa5cc-5a57-4ada-950e-dfaa686fb9db', 'Literature in English', 'JAMB', null, 2026, null, 'The phrase poetic walking at the end of the poem refers to', null, '["the celebrant''s slow movement","a unique, graceful way of living","a poet''s literal walk","a march in protest"]', 1, 'The phrase ''poetic walking'' at the end of ''Hearty Garlands'' refers to a unique, graceful way of living. It suggests that the celebrant has lived life with grace, beauty, and purpose, like a poet composing verse. It is not about literal movement, a poet''s walk, or a protest march. The phrase celebrates a life well-lived with artistry and dignity.', true, '2026-09-10 10:47:54.364', '2026-09-10 10:47:54.364', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3094c824-0ef1-4352-8add-e39f559e1ea0', 'General Mathematics', 'JAMB', null, 2026, null, 'If S varies directly as t and the square of u, and s=18 when t=2 and u=3, find s when t=3 and u=4.', null, '["64","54","36","48"]', 0, 'S = ktu². 18 = k(2)(9) = 18k. k = 1. S = 3(16) = 48. The answer is (D) 48.', true, '2026-09-12 11:43:53.233', '2026-09-12 11:43:53.233', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3095e287-2027-4ec2-a90c-6e3ffde2aca0', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'According to Paul, spiritual gifts, if properly employed, help in', null, '["attracting converts","hastening miracles","identifying evil doers","edifying the church"]', 3, 'Spiritual gifts are for building up the church (1 Corinthians 14:12).', true, '2026-09-12 10:41:23.949', '2026-09-12 10:41:23.949', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('30a8994f-22de-4a04-927c-fb56ae061260', 'Literature in English', 'JAMB', null, 2026, null, 'The phrase ''impregnable chains'' metaphorically refers to', null, '["unbreakable family bonds","the strong influence of the new culture","physical restraints","the strength of traditional values"]', 1, 'The phrase ''impregnable chains'' metaphorically refers to the strong influence of the new culture. In ''Once Upon A Time,'' the speaker describes how society has bound him with ''impregnable chains'' of hypocrisy and falsehood. The new culture of pretence has a powerful, almost unbreakable hold on him. It is not about family bonds, physical restraints, or traditional values. The chains represent the inescapable influence of societal expectations.', true, '2026-09-10 10:45:35.313', '2026-09-10 10:45:35.313', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('30ab1461-bd7c-41fc-8373-0d9348fa962d', 'Biology', 'JAMB', null, 2011, null, 'Which of the following theories was NOT considered by Darwin in his evolutionary theory?', null, '["Variation","Survival of the fittest","Use and disuse","Competition."]', 2, 'Use and disuse was Lamarck''s theory, not Darwin''s.', true, '2026-10-12 20:59:43.676', '2026-10-12 20:59:43.676', null, null, null, 'Which of the following theories was NOT considered by Darwin in his evolutionary theory?', '["Variation","Survival of the fittest","Use and disuse","Competition."]', 'Use and disuse was Lamarck''s theory, not Darwin''s.', '{"bold":["Use and disuse"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('30ae3d90-5631-482e-95b6-bd82279b50d1', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'In Romans, Paul condemned sin taking over mortal bodies in the new life as instruments of', null, '["greediness","wickedness","sadness","foolishness"]', 1, 'Paul says do not yield your members to sin as instruments of wickedness (Romans 6:13).', true, '2026-09-12 10:41:21.711', '2026-09-12 10:41:21.711', null, null, null, null, null, null, null);
