insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('30c8e47f-a5ac-43cc-b59d-387145360cb5', 'Physics', 'JAMB', null, 1986, null, 'A heavy object is suspended from a string and lowered into water so that it is completely submerged. The object appears lighter because', null, '["The density of water is less than that of the object.","The pressure is low just below the water surface.","It experiences an upthrust.","The tension in the string neutralizes part of the weight."]', 2, 'The water exerts an upward force (upthrust) on the submerged object, reducing the apparent weight.', true, '2026-10-12 19:15:22.717', '2026-10-12 19:15:22.717', null, null, null, 'A heavy object is suspended from a string and lowered into water so that it is completely submerged. The object appears lighter because', '["The density of water is less than that of the object.","The pressure is low just below the water surface.","It experiences an upthrust.","The tension in the string neutralizes part of the weight."]', 'The water exerts an upward force (upthrust) on the submerged object, reducing the apparent weight.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
