insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('30cb064c-e0c0-4ffd-8984-b5dd2c03d2cf', 'Physics', 'JAMB', null, 1985, null, 'Water shows anomalous behaviour', null, '["Below 0 °C","Between 0 °C and 4 °C","At exactly 4 °C","Between 4 °C and 100 °C","Above 100 °C"]', 1, 'Between 0 °C and 4 °C water contracts on heating, so its density rises to a maximum at 4 °C. This is the anomalous expansion of water.', true, '2026-10-12 19:15:21.474', '2026-10-12 19:15:21.474', null, null, null, 'Water shows anomalous behaviour', '["Below 0 °C","Between 0 °C and 4 °C","At exactly 4 °C","Between 4 °C and 100 °C","Above 100 °C"]', 'Between 0 °C and 4 °C water contracts on heating, so its density rises to a maximum at 4 °C. This is the anomalous expansion of water.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
