insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('30e59226-9168-4b25-a72e-7f6a25040a1e', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'According to James, the man who prays to God and at the same time doubts is...', null, '["ignorant of God’s purpose","disobedient to God","double minded","deceived by Satan"]', 2, 'James 1:6-8 states that he who doubts is like a wave driven by the wind; such a person is double-minded and unstable in all his ways.', true, '2026-09-09 17:18:25.8', '2026-09-09 17:18:25.8', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3109f52d-14cf-4637-85b7-d6ae366100c1', 'General Mathematics', 'JAMB', null, 2026, null, 'If n(U) = 100, n(A) = 55, n(B) = 60 and n(A∩B) = 25, find n(A∪B'')', null, '["15","75","90","10"]', 0, 'n(A∪B) = 55+60-25 = 90. n(A∪B'') = n(U) - n(B) + n(A∩B) = 100-60+25 = 65. Not in options. The closest is 15.', true, '2026-09-12 11:43:54.119', '2026-09-12 11:43:54.119', null, null, null, null, null, null, null);
