insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3117002a-4eeb-41ff-895b-69167947e603', 'Physics', 'JAMB', null, 1992, null, 'A bridge made of steel is 600 m long. What is the daily variation in its length if the night-time and day-time temperatures are 10 °C and 35 °C respectively? The linear expansivity of steel is 0.000012 °C⁻¹.', null, '["0.18 cm","1.80 cm","18.00 cm","1800 cm"]', 2, 'ΔL = L α Δθ = 600 x 0.000012 x 25 = 0.18 m = 18.00 cm.', true, '2026-10-12 19:15:35.284', '2026-10-12 19:15:35.284', null, null, null, 'A bridge made of steel is 600 m long. What is the daily variation in its length if the night-time and day-time temperatures are 10 °C and 35 °C respectively? The linear expansivity of steel is 0.000012 °C<sup>-1</sup>.', '["0.18 cm","1.80 cm","18.00 cm","1800 cm"]', 'ΔL = L α Δθ = 600 x 0.000012 x 25 = 0.18 m = 18.00 cm.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
