insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('31c9a271-5275-4127-a557-205f5d67b1eb', 'Economics', 'JAMB', null, 2026, null, 'By utility we mean', null, '["Benefit","Consumable","Satisfaction of wants","Advantage"]', 2, 'Utility is the satisfaction derived from consuming a good or service.', true, '2026-09-12 10:58:51.125', '2026-09-12 10:58:51.125', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('31d73a8c-d974-4c8b-a9ab-460a1bb2031e', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'When Eve was about to be created, God did all the following except', null, '["causing a deep sleep to fall on Adam","taking a rib from Adam''s side","covering where he removed the rib with a robe","slept with Eve"]', 3, 'God did not sleep with Eve. The creation of Eve involved God causing a deep sleep to fall on Adam, taking a rib from his side, and closing up the flesh. God does not have physical relations with humans.', true, '2026-09-12 09:45:57.193', '2026-09-12 09:45:57.193', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('31db7a8e-70a6-49a9-aba3-0d24772b7f0d', 'Biology', 'JAMB', null, 2005, null, 'Angiosperms and gymnosperms belong to the class', null, '["schizophyta","spermatophyte","pteridophyta","bryophyta"]', 1, 'Angiosperms and gymnosperms are spermatophytes.', true, '2026-10-12 20:59:36.395', '2026-10-12 20:59:36.395', null, null, null, 'Angiosperms and gymnosperms belong to the class', '["schizophyta","spermatophyte","pteridophyta","bryophyta"]', 'Angiosperms and gymnosperms are spermatophytes.', '{"bold":["spermatophytes"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('31db7ff3-3d8e-442d-86bb-fdd451cb7968', 'English Language', 'JAMB', null, 2024, null, 'Choose the option that best completes the gaps: the policeman became suspicious as the hoodlums ______ in their office', null, '["freretted","ferreted","ferreted about","ferreted about"]', 2, '"Ferreted about" means searched around suspiciously.', true, '2026-09-18 09:24:04.8', '2026-10-17 10:55:46.061', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('31de6735-1bc4-474e-907d-6d42bd601dd7', 'Literature in English', 'JAMB', null, 2026, null, '………is primal to a play or novel.', null, '["Conflict","Mime","Flashback","Epilogue"]', 0, 'Conflict is primal to a play or novel. Conflict is the central struggle between opposing forces that drives the plot forward. Without conflict, there would be no story. It can be internal (man vs. self) or external (man vs. man, man vs. nature, man vs. society). Conflict creates tension, suspense, and interest in literary works.', true, '2026-09-10 10:45:33.432', '2026-09-10 10:45:33.432', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('31eebaf5-51d0-4980-9347-2d95225cd81e', 'Financial Accounting', 'UTME', null, 2002, null, 'What is the amount to be written off as other expenses?', 'https://res.cloudinary.com/kwi1uv0g/image/upload/v1791840989/questions/oioxmewg1xbk9becrace.jpg', '["N4500","N6000","N4000","N5000"]', 3, 'Subscription received 20,000. Other exp. 25% of Sub. = 25/100 x 20,000 = 5,000.', true, '2026-10-12 21:59:58.055', '2026-10-12 21:59:58.055', null, null, null, 'What is the amount to be written off as other expenses?', '["N4500","N6000","N4000","<b>N5000</b>"]', 'Subscription received 20,000. Other exp. 25% of Sub. = 25/100 x 20,000 = <b>5,000</b>.', '{"bold":["5,000"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('31f09696-8480-4c96-8239-ab9be58fc191', 'Literature in English', 'JAMB', null, 2026, null, '''The bitter taste of failure lingered on his tongue'' illustrates', null, '["Visual imagery","Gustatory imagery","Auditory imagery","Kinesthetic imagery"]', 1, 'It illustrates gustatory imagery.', true, '2026-09-12 11:14:18.372', '2026-09-12 11:14:18.372', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('31f2ed07-393c-4ded-8dc7-a413a8aa49fa', 'Economics', 'JAMB', null, 2026, null, 'The cost incurred in the production of additional unit of commodity is known as', null, '["Average cost","Total cost","Variable cost","Marginal cost"]', 3, 'Marginal cost is the cost of producing one additional unit of a commodity.', true, '2026-09-12 10:59:11.284', '2026-09-12 10:59:11.284', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('31fa6e51-be8f-408f-b2ff-1e1cca44d2f6', 'Economics', 'JAMB', null, 2026, null, 'In order to increase revenue, government should tax commodities for which demand is?', null, '["Price elastic","Price inelastic","Perfectly elastic","Unitary elastic"]', 1, 'Government should tax goods with inelastic demand to increase revenue.', true, '2026-09-12 11:02:13.302', '2026-09-12 11:02:13.302', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('31fec4f5-762e-4f38-be00-dd97e93eed6c', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). The governor advised his people to <u>get off the beaten tracks</u> in their approach to community matters.', null, '["use the old roads","make the tracks better","find new ways","avoid beating about the bush"]', 2, '''Get off the beaten tracks'' = find new ways.', true, '2026-10-24 01:02:05.43', '2026-10-24 01:02:05.43', null, null, null, '(Choose the most appropriate interpretation). The governor advised his people to <u>get off the beaten tracks</u> in their approach to community matters.', '["use the old roads","make the tracks better","<u>find new ways</u>","avoid beating about the bush"]', '''<b>Get off the beaten tracks</b>'' = <b>find new ways</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('32014429-14b3-4638-91c8-eff7fb54e649', 'Literature in English', 'JAMB', null, 2026, null, '''Genres of literature'' aptly discusses', null, '["tragedy, comedy and tragic-comedy","Poem, ballad and picaresque","prose, drama and poetry","romance, Shakespearean drama and epitaph"]', 2, 'Genres of literature are prose, drama, and poetry.', true, '2026-09-12 11:10:36.114', '2026-09-12 11:10:36.114', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('320260ed-3fec-4b11-bd18-a75631dc654a', 'Economics', 'JAMB', null, 2026, null, 'Positive check as envisaged by Thomas Malthus include all the following EXCEPT?', null, '["Famine","War","Birth control","Pestilence"]', 2, 'Birth control is a preventive check, not a positive check.', true, '2026-09-12 11:02:12.407', '2026-09-12 11:02:12.407', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('320a6e41-b8fe-468e-bd63-1b7263f5b40c', 'Biology', 'JAMB', null, 2026, null, 'Mycorrhiza promote plant growth by', null, '["Absorbing inorganic ions from the soil","Protecting it from infection","Helping it to utilize atmospheric nitrogen","Serving as a growth regulator"]', 0, 'Mycorrhizae promote plant growth by absorbing inorganic ions (particularly phosphorus, but also nitrogen, zinc, and copper) from the soil. Mycorrhizae are symbiotic associations between fungi and plant roots. The fungal hyphae greatly increase the surface area for absorption, making nutrients more available to the plant. Mycorrhizae do not fix atmospheric nitrogen (that is done by nitrogen-fixing bacteria). While they may provide some protection against pathogens and act as growth regulators, their primary benefit is enhancing nutrient uptake.', true, '2026-09-09 03:19:01.206', '2026-09-09 03:19:01.206', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('321107d1-0a22-41cd-93c7-46f26dd7256e', 'Physics', 'JAMB', null, 1989, null, 'Dispersion of light by a glass prism is due to the', null, '["Different hidden colours of the glass","Different speeds of the various colours in glass","Defects in the glass","High density of glass."]', 1, 'Each colour travels at a different speed in glass, so each has a different refractive index and is deviated by a different amount.', true, '2026-10-12 19:15:29.632', '2026-10-12 19:15:29.632', null, null, null, 'Dispersion of light by a glass prism is due to the', '["Different hidden colours of the glass","Different speeds of the various colours in glass","Defects in the glass","High density of glass."]', 'Each colour travels at a different speed in glass, so each has a different refractive index and is deviated by a different amount.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('32169d48-dfa4-4113-aa04-692a9c27d767', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. ''This is a <u>miniaturized</u> version of your house'' remarked the Architect.', null, '["compressed","abridged","decreased","smaller"]', 3, 'Miniaturized = smaller.', true, '2026-10-24 01:03:55.061', '2026-10-24 01:03:55.061', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. ''This is a <u>miniaturized</u> version of your house'' remarked the Architect.', '["compressed","abridged","decreased","<u>smaller</u>"]', '<b>Miniaturized</b> = <b>smaller</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('321ac974-af1e-4576-b587-6a1c2fdce4c7', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'How many people were saved in Noah''s ark?', null, '["12","8","40","6"]', 1, 'Eight people were saved in Noah''s ark: Noah, his wife, his three sons (Shem, Ham, and Japheth), and their three wives.', true, '2026-09-12 09:45:48.823', '2026-09-12 09:45:48.823', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3222aeb6-5af2-4f00-963d-07496c48f20c', 'Physics', 'JAMB', null, 1985, null, 'Two masses 40 g and 60 g respectively, are attached firmly to the ends of a light metre rule. The centre of gravity of the system is', null, '["At the mid-point of the metre rule","40 cm from the lighter mass","40 cm from the heavier mass","60 cm from the heavier mass","Indeterminate because the metre-rule is light."]', 2, 'Taking moments about the centre of gravity: 60 x d = 40 x (100 - d), so d = 40 cm from the heavier mass.', true, '2026-10-12 19:15:20.931', '2026-10-12 19:15:20.931', null, null, null, 'Two masses 40 g and 60 g respectively, are attached firmly to the ends of a light metre rule. The centre of gravity of the system is', '["At the mid-point of the metre rule","40 cm from the lighter mass","40 cm from the heavier mass","60 cm from the heavier mass","Indeterminate because the metre-rule is light."]', 'Taking moments about the centre of gravity: 60 x d = 40 x (100 - d), so d = 40 cm from the heavier mass.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('322489e9-d4f7-4bc9-8a5f-a4f4508eda49', 'English Language', 'JAMB', null, 2007, null, 'It is mandatory that each applicant <u>_______</u> two passport photographs along with the form.', null, '["submits","submitted","submit","is submitting"]', 2, '''Mandatory that'' â†’ subjunctive submit.', true, '2026-10-24 01:04:26.455', '2026-10-24 01:04:26.455', null, null, null, 'It is mandatory that each applicant <u>_______</u> two passport photographs along with the form.', '["submits","submitted","<u>submit</u>","is submitting"]', '''<b>Mandatory that</b>'' â†’ subjunctive <b>submit</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('322e15b6-8153-4a20-8c52-c7f95c778d78', 'Hausa', 'JAMB', null, 2011, null, 'Wanne ne gaskiya dangane da makadan fada?', null, '["Ba su yi wa kowa wa ka sai sarki.","Ba su kar bar kyauta sai daga sarki.","Sarkinsu na sa su yi wa wani wa ka.","Dukkansu maka dan taushi ne."]', 2, 'Gaskiya dangane da makadan fada shi ne sarkinsu na sa su yi wa wani wa ka.', true, '2026-10-13 10:37:22.209', '2026-10-13 10:37:22.209', null, null, null, 'Wanne ne gaskiya dangane da makadan fada?', '["Ba su yi wa kowa wa ka sai sarki.","Ba su kar bar kyauta sai daga sarki.","Sarkinsu na sa su yi wa wani wa ka.","Dukkansu maka dan taushi ne."]', 'Gaskiya dangane da makadan fada shi ne sarkinsu na sa su yi wa wani wa ka.', '{"bold":["sarkinsu na sa su yi wa wani wa ka"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3243d2ec-628c-4b1c-ab38-92e0fad3aede', 'Biology', 'JAMB', null, 2026, null, 'If the cross of a red-flowered plant with a white-flowered plant produces a pink-flowered plant, it''s an example of', null, '["mutation","linkage","co-dominance","incomplete dominance"]', 3, 'If a red-flowered plant crossed with a white-flowered plant produces pink-flowered plants, it''s an example of incomplete dominance. In incomplete dominance, neither allele is completely dominant, and the heterozygote shows an intermediate phenotype (pink). Mutation is a change in DNA. Linkage is the inheritance of genes on the same chromosome. Co-dominance is when both alleles are expressed equally (like AB blood group). Incomplete dominance produces a blending of traits.', true, '2026-09-09 03:19:24.317', '2026-09-09 03:19:24.317', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3257231d-30bd-403e-8a4d-abf0af857984', 'English Language', 'JAMB', null, 2024, null, 'Choose the word that has the same sound as the one represented by the underlined letters: s_w_ore', null, '["scroll","suite","sword","straight"]', 2, 'The "w" in "swore" is silent, same as in "sword."', true, '2026-09-18 09:23:08.366', '2026-09-18 09:23:08.366', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('325a3f8b-ed76-4eec-b203-4ee5090116f4', 'Biology', 'JAMB', null, 2012, null, 'Which of the following is involved in secondary thickening in plants?', null, '["Collenchyma and xylem cells","Vascular cambium and collenchyma cells","Vascular cambium and cork cambium","Cork cambium and sclerenchyma."]', 2, 'Vascular cambium and cork cambium are involved in secondary thickening.', true, '2026-10-12 20:59:44.842', '2026-10-12 20:59:44.842', null, null, null, 'Which of the following is involved in secondary thickening in plants?', '["Collenchyma and xylem cells","Vascular cambium and collenchyma cells","Vascular cambium and cork cambium","Cork cambium and sclerenchyma."]', 'Vascular cambium and cork cambium are involved in secondary thickening.', '{"bold":["Vascular cambium and cork cambium"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('326131e5-70d2-48e2-b4a1-b863a994601c', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The teacher said that Ali''s essay was full of many <u>redundant</u> details.', null, '["strange","necessary","useful","unexplained"]', 1, 'Redundant = unnecessary; opposite = necessary.', true, '2026-10-24 07:21:26.135', '2026-10-24 07:21:26.135', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The teacher said that Ali''s essay was full of many <u>redundant</u> details.', '["strange","necessary","useful","unexplained"]', 'Redundant = unnecessary; opposite = necessary.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3271ea6d-a531-40d4-9bc4-5aa6c736df0f', 'Biology', 'JAMB', null, 2026, null, 'An organism that has been extensively used to test the chromosome theory of heredity is', null, '["Drosophila melanogaster","Homo sapiens","Zea Mays","Musca domestica"]', 0, 'Drosophila melanogaster (fruit fly) has been extensively used to test the chromosome theory of heredity. It has been used in genetic studies for over a century because it has short generation time, produces many offspring, and has only 4 pairs of chromosomes. It was used by Thomas Hunt Morgan to demonstrate that genes are on chromosomes. Homo sapiens, Zea Mays (corn), and Musca domestica (housefly) are also studied, but Drosophila is the classic model organism.', true, '2026-09-09 03:19:26.974', '2026-09-09 03:19:26.974', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3279641f-b1b0-4508-a315-8785533aafb6', 'Physics', 'JAMB', null, 1998, null, 'A radioactive substance has a half-life of 80 days. If the initial number of atoms in the sample is 6.0 x 10¹⁰, how many atoms would remain at the end of 320 days?', null, '["3.75 x 10⁹","7.50 x 10⁹","3.00 x 10¹⁰","5.63 x 10¹⁰"]', 0, '320 days = 4 half-lives. N = 6.0 x 10¹⁰/2⁴ = 3.75 x 10⁹.', true, '2026-10-12 19:15:46.805', '2026-10-12 19:15:46.805', null, null, null, 'A radioactive substance has a half-life of 80 days. If the initial number of atoms in the sample is 6.0 x 10<sup>10</sup>, how many atoms would remain at the end of 320 days?', '["3.75 x 10<sup>9</sup>","7.50 x 10<sup>9</sup>","3.00 x 10<sup>10</sup>","5.63 x 10<sup>10</sup>"]', '320 days = 4 half-lives. N = 6.0 x 10<sup>10</sup>/2<sup>4</sup> = 3.75 x 10<sup>9</sup>.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('32851fe3-996d-4fa7-b2a0-e1f4d16c9460', 'Biology', 'JAMB', null, 2026, null, 'The characters by which an organism is recognized are termed its', null, '["phenotype","genotype","morphology","anatomy","physiology"]', 0, 'The phenotype is the observable characteristics or traits of an organism, including morphology (form and structure), physiology (function), and behavior, resulting from the interaction of genotype with the environment. It is what allows organisms to be recognized and distinguished. Genotype is the genetic makeup. Morphology refers specifically to form and structure. Anatomy is the internal structure of organisms. Physiology is the study of functions. Phenotype encompasses all observable features that are used to identify and classify organisms.', true, '2026-09-09 03:18:38.693', '2026-09-09 03:18:38.693', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('32866dfb-64f3-4974-8474-de639148e187', 'Economics', 'JAMB', null, 2026, null, 'The price of a good rises from N5 to N8 and the quantity falls from 200 to 190 units. It can be deduced that the demand curve is', null, '["Fairly elastic","perfectly elastic","fairly inelastic","unit elastic"]', 2, 'The demand curve is fairly inelastic. Price elasticity of demand = % change in quantity / % change in price. % change in price = (8-5)/5 × 100 = 60%. % change in quantity = (200-190)/200 × 100 = 5%. PED = 5/60 = 0.083. Since PED < 1, demand is inelastic. The quantity demanded is not very responsive to price changes. A large price increase caused only a small decrease in quantity demanded.', true, '2026-09-10 10:41:59.376', '2026-09-10 10:41:59.376', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3289818a-957c-4639-8118-3de9a5df43c8', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Do you know one of the most <u>astounding</u> events of my life?', null, '["special","amazing","serious","outstanding"]', 1, 'Astounding = amazing.', true, '2026-10-24 01:03:58.456', '2026-10-24 01:03:58.456', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Do you know one of the most <u>astounding</u> events of my life?', '["special","<u>amazing</u>","serious","outstanding"]', '<b>Astounding</b> = <b>amazing</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('328a94fd-5f7b-4c7b-8e28-ca7cdb952efd', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The Principal told the teacher to stop <u>browbeating</u> the children.', null, '["pampering","bullying","deceiving","caning"]', 1, 'Browbeating = bullying.', true, '2026-10-24 01:04:02.048', '2026-10-24 01:04:02.048', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The Principal told the teacher to stop <u>browbeating</u> the children.', '["pampering","<u>bullying</u>","deceiving","caning"]', '<b>Browbeating</b> = <b>bullying</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('328fd2de-9224-4d36-a767-46e532fc9f76', 'Physics', 'JAMB', null, 1989, null, 'The plane mirrors in a kaleidoscope are usually placed', null, '["At an angle of 60°","Parallel to one another","Perpendicular to one another","At an angle of 45°"]', 0, 'A kaleidoscope uses two mirrors at 60° to give a symmetrical pattern of 5 images (six-fold symmetry).', true, '2026-10-12 19:15:29.468', '2026-10-12 19:15:29.468', null, null, null, 'The plane mirrors in a kaleidoscope are usually placed', '["At an angle of 60°","Parallel to one another","Perpendicular to one another","At an angle of 45°"]', 'A kaleidoscope uses two mirrors at 60° to give a symmetrical pattern of 5 images (six-fold symmetry).', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3296b726-ffc0-4f2c-ab7e-5aeff6f67915', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'According to John, Jesus said the work of God is...', null, '["Preaching the gospel","Healing the sick","Feeding the hungry who are in need","Believing in Him whom He had sent"]', 3, 'John 6:29 states: ''This is the work of God, that you believe in Him whom He sent.''', true, '2026-09-09 17:18:28.366', '2026-09-09 17:18:28.366', null, null, null, null, null, null, null);
