insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('36bbc711-ac9b-46cd-9cf3-9407db15ddce', 'Biology', 'JAMB', null, 2002, null, 'The organ located within the duodenal loop in the mammal is the', null, '["spleen","pancreas","liver","gall bladder"]', 1, 'The pancreas is located within the duodenal loop.', true, '2026-10-12 20:59:31.473', '2026-10-12 20:59:31.473', null, null, null, 'The organ located within the duodenal loop in the mammal is the', '["spleen","pancreas","liver","gall bladder"]', 'The pancreas is located within the duodenal loop.', '{"bold":["pancreas"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('36c4eb05-3c01-4129-9b9a-4c779c4b1916', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'How many people were saved in Noah''s ark?', null, '["12","8","40","6"]', 1, 'Eight people were saved: Noah, his wife, three sons, and their wives.', true, '2026-09-12 10:40:56.239', '2026-09-12 10:40:56.239', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('36daec9a-fe1d-4412-b1ad-0903cba1a2e5', 'Chemistry', 'JAMB', null, 2026, null, 'In rusting, iron reacts with:', null, '["Oxygen only","Water only","Oxygen and water","CO₂ only"]', 2, 'Rusting requires both oxygen and water.', true, '2026-09-12 11:35:59.375', '2026-09-12 11:35:59.375', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('36deae37-a87e-4712-945e-83f7d857b50a', 'Literature in English', 'JAMB', null, 2026, null, 'The expression Drunk with fatigue illustrates', null, '["Metaphor","Synecdoche","Litotes","Irony"]', 0, 'It illustrates metaphor.', true, '2026-09-12 11:13:52.944', '2026-09-12 11:13:52.944', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('36dfb91f-50df-464b-9d27-5429600a99da', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). After my husband''s death, I find it hard to <u>keep open house</u>.', null, '["entertain every visitor","keep all doors open","relax security","give a party"]', 0, '''Keep open house'' = entertain every visitor.', true, '2026-10-24 01:04:20.505', '2026-10-24 01:04:20.505', null, null, null, '(Choose the most appropriate interpretation). After my husband''s death, I find it hard to <u>keep open house</u>.', '["<u>entertain every visitor</u>","keep all doors open","relax security","give a party"]', '''<b>Keep open house</b>'' = <b>entertain every visitor</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('36e845da-8643-40e6-bb5d-88baa2f7678d', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). The retired army officer did <u>a yeoman''s service to the nation</u>', null, '["His activity brought disrepute to the nation","His service to the nation was not exemplary","He was showered with the responsibility of the yeoman","He was very loyal to the nation"]', 3, '''Yeoman''s service'' = valuable, loyal service.', true, '2026-10-24 01:04:23.933', '2026-10-24 01:04:23.933', null, null, null, '(Choose the most appropriate interpretation). The retired army officer did <u>a yeoman''s service to the nation</u>', '["His activity brought disrepute to the nation","His service to the nation was not exemplary","He was showered with the responsibility of the yeoman","<u>He was very loyal to the nation</u>"]', '''<b>Yeoman''s service</b>'' = <b>valuable, loyal service</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('36e8ae17-857f-4952-9a9b-f9b9b7f0dd00', 'English Language', 'JAMB', null, 2007, null, 'I shall work hard so that I can <u>__________</u> a distinction in English', null, '["secure","make","receive","grab"]', 0, 'Correct form: secure a distinction.', true, '2026-10-24 07:21:45.071', '2026-10-24 07:21:45.071', null, null, null, 'I shall work hard so that I can <u>__________</u> a distinction in English', '["secure","make","receive","grab"]', 'Correct form: secure a distinction.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('36fd6f2c-44d8-48b0-99bb-a4e8ab851bb3', 'Biology', 'JAMB', null, 2026, null, 'The process by which solid undigested food substances is being removed from the body', null, '["Excretion","Digestion","Egestion","Secretion","Assimilation"]', 2, 'Egestion is the removal of undigested solid waste (feces) from the body through the anus. This material never entered the body''s cells and is not a product of metabolism. Excretion is the removal of metabolic waste products (urea, uric acid, carbon dioxide) that have been produced by cellular activities. Digestion is the breakdown of food. Secretion is the release of substances by glands. Assimilation is the incorporation of absorbed nutrients into body tissues. Egestion is often confused with excretion but they are distinct processes.', true, '2026-09-09 03:18:31.348', '2026-09-09 03:18:31.348', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('36fe5a1d-b0c9-4954-b669-0b08785e7c57', 'English Language', 'JAMB', null, 2024, null, 'Identify the option that contains /ð/', null, '["feather","stealthy","wither","breathe"]', 0, '"Feather" contains the /ð/ sound.', true, '2026-09-18 09:43:02.674', '2026-09-18 09:43:02.674', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('36fe7c9e-15c6-47b4-b82a-86e8bc1ef84e', 'Literature in English', 'JAMB', null, 2026, null, 'Purgation of emotion, pity or fear is', null, '["Catharsis","Catastrophe","Epilogue","Exposition"]', 0, 'Catharsis is the purgation of emotions.', true, '2026-09-12 11:13:41.704', '2026-09-12 11:13:41.704', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('370e13a6-7fb6-45df-a103-9bdea396beaa', 'English Language', 'JAMB', null, 2007, null, 'My <u>__________</u> is for you to refuse the <u>__________</u> of the wicked.', null, '["advise/advise","advice/advice","advice/advise","advise/advice"]', 2, 'Correct forms: advice/advise.', true, '2026-10-24 07:21:34.556', '2026-10-24 07:21:34.556', null, null, null, 'My <u>__________</u> is for you to refuse the <u>__________</u> of the wicked.', '["advise/advise","advice/advice","advice/advise","advise/advice"]', 'Correct forms: advice/advise.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('371323cc-268d-470c-8099-8941e678cc72', 'Physics', 'JAMB', null, 2026, null, 'Which is the vector amongst the following?', null, '["Electro-Motive-Force","pressure","polarization","escape velocity","Voltage"]', 3, 'Escape velocity is a vector quantity. It has both magnitude and direction. EMF, pressure, polarization, and voltage are scalar quantities (though EMF and voltage can have direction in circuit analysis, they are generally treated as scalars in physics).', true, '2026-09-10 10:56:42.982', '2026-09-10 10:56:42.982', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('37198ec5-76f9-414a-9d3c-4f1b007f83cc', 'Physics', 'JAMB', null, 1999, null, 'What is the speed of a particle of mass 10⁻²⁷ kg whose wavelength is 10⁻⁸ m? (h = 6.63 x 10⁻³⁴ J s)', null, '["6.63 m s⁻¹","66.30 m s⁻¹","663.00 m s⁻¹","6630.00 m s⁻¹"]', 1, 'de Broglie: λ = h/(mv), so v = h/(mλ) = 6.63 x 10⁻³⁴/(10⁻²⁷ x 10⁻⁸) = 66.3 m s⁻¹.', true, '2026-10-12 19:15:48.625', '2026-10-12 19:15:48.625', null, null, null, 'What is the speed of a particle of mass 10<sup>-27</sup> kg whose wavelength is 10<sup>-8</sup> m? (h = 6.63 x 10<sup>-34</sup> J s)', '["6.63 m s<sup>-1</sup>","66.30 m s<sup>-1</sup>","663.00 m s<sup>-1</sup>","6630.00 m s<sup>-1</sup>"]', 'de Broglie: λ = h/(mv), so v = h/(mλ) = 6.63 x 10<sup>-34</sup>/(10<sup>-27</sup> x 10<sup>-8</sup>) = 66.3 m s<sup>-1</sup>.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('37227e34-123c-435f-8002-4978407de164', 'English Language', 'JAMB', null, 2007, null, 'The college bus was travelling at a high <u>__________</u> when the accident occurred', null, '["velocity","acceleration","rapidity","speed"]', 3, 'Correct form: high speed.', true, '2026-10-24 07:21:42.611', '2026-10-24 07:21:42.611', null, null, null, 'The college bus was travelling at a high <u>__________</u> when the accident occurred', '["velocity","acceleration","rapidity","speed"]', 'Correct form: high speed.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3724ab02-6305-488b-a0ae-f000495e2581', 'Literature in English', 'JAMB', null, 2026, null, 'The presentation of Ananse being whipped by rain symbolizes', null, '["struggles and hardship of life","the raining season","a hasty man without an umbrella","a drenched struggling father"]', 0, 'It symbolizes the struggles and hardship of life.', true, '2026-09-12 11:10:00.413', '2026-09-12 11:10:00.413', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('37297ee6-dbdb-415e-aa9c-da474aafdb87', 'English Language', 'JAMB', null, 2007, null, 'She has a set of gold <u>__________</u>', null, '["earing","earings","earrings","ear-ring"]', 2, 'Correct spelling: earrings.', true, '2026-10-24 07:21:34.052', '2026-10-24 07:21:34.052', null, null, null, 'She has a set of gold <u>__________</u>', '["earing","earings","earrings","ear-ring"]', 'Correct spelling: earrings.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('372a624c-ecb8-41e3-a76e-7cb6bcee182c', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation).<u>Watch it!</u> You could be followed said the robber.', null, '["Look around","Be sober","Be vigilant","Look out"]', 2, '''Watch it'' = be vigilant.', true, '2026-10-24 01:02:02.963', '2026-10-24 01:02:02.963', null, null, null, '(Choose the most appropriate interpretation).<u>Watch it!</u> You could be followed said the robber.', '["Look around","Be sober","<u>Be vigilant</u>","Look out"]', '''<b>Watch it</b>'' = <b>be vigilant</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('372e8bb8-a8d4-4bc5-b694-a62bfe8f525e', 'Christian Religious Studies', 'JAMB', null, 2026, null, '''But now that faith has come, we are no longer under a custodian....'' Custodian here means the', null, '["church","law","priest","covenant"]', 1, 'Custodian here means the law. In Galatians 3:24-25, Paul says, ''So the law was our custodian until Christ came, that we might be justified by faith. But now that faith has come, we are no longer under a custodian.''', true, '2026-09-12 09:46:05.512', '2026-09-12 09:46:05.512', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('373432df-63c5-41b5-950e-d6e9aba3c3b1', 'Government', 'JAMB', null, 2026, null, 'In contemporary times, the primary agent of public opinion is', null, '["mass media","educational institution","family","political party"]', 0, 'In contemporary times, the primary agent of public opinion is the mass media. The mass media (television, radio, newspapers, internet, social media) plays a dominant role in shaping public opinion by determining what issues people think about, providing information, and framing debates. While family, educational institutions, and political parties influence opinion, the mass media has the widest reach and most immediate impact in modern society.', true, '2026-09-10 10:44:17.814', '2026-09-10 10:44:17.814', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('376ad1b3-5fb0-45da-ba3f-4bb05eae9f98', 'Physics', 'JAMB', null, 1993, null, 'The thermometric property of the thermocouple is that its', null, '["e.m.f. changes with temperature","Resistance changes with temperature","Volume changes with temperature","Pressure changes with resistance."]', 0, 'A thermocouple produces an e.m.f. that depends on the temperature difference between its two junctions.', true, '2026-10-12 19:15:37.432', '2026-10-12 19:15:37.432', null, null, null, 'The thermometric property of the thermocouple is that its', '["e.m.f. changes with temperature","Resistance changes with temperature","Volume changes with temperature","Pressure changes with resistance."]', 'A thermocouple produces an e.m.f. that depends on the temperature difference between its two junctions.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('376b8dd3-689c-4cdb-8931-000198cd5ea8', 'Chemistry', 'JAMB', null, 2026, null, 'The abnormally high boiling point of water is primarily due to', null, '["ionic bonding","covalent bonding","dative bonding","coordinate covalent bonding","hydrogen bonding"]', 4, 'The high boiling point of water is due to hydrogen bonding.', true, '2026-09-12 11:36:10.413', '2026-09-12 11:36:10.413', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3783d802-e925-4a9b-81ce-29c15c3a314e', 'Physics', 'JAMB', null, 1986, null, 'A wave of frequency 10 Hz forms a stationary wave pattern in a medium where the velocity is 20 cm s⁻¹. The distance between adjacent nodes is', null, '["1.0 cm","1.5 cm","2.0 cm","5.0 cm"]', 0, 'λ = v/f = 20/10 = 2 cm. Adjacent nodes are λ/2 apart = 1.0 cm.', true, '2026-10-12 19:15:24.003', '2026-10-12 19:15:24.003', null, null, null, 'A wave of frequency 10 Hz forms a stationary wave pattern in a medium where the velocity is 20 cm s<sup>-1</sup>. The distance between adjacent nodes is', '["1.0 cm","1.5 cm","2.0 cm","5.0 cm"]', 'λ = v/f = 20/10 = 2 cm. Adjacent nodes are λ/2 apart = 1.0 cm.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('37890617-70db-48dc-b24f-3614cff82dfb', 'Biology', 'JAMB', null, 2012, null, 'Plants that show secondary growth are usually found among the', null, '["thallophytes","pteridophytes","monocotyledons","dicotyledons."]', 3, 'Secondary growth is found among dicotyledons.', true, '2026-10-12 20:59:44.185', '2026-10-12 20:59:44.185', null, null, null, 'Plants that show secondary growth are usually found among the', '["thallophytes","pteridophytes","monocotyledons","dicotyledons."]', 'Secondary growth is found among dicotyledons.', '{"bold":["dicotyledons"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('37957b39-4f31-4a6c-befc-7df1fb5a48c9', 'Economics', 'JAMB', null, 2026, null, 'The production within domestic territory of a country is called?', null, '["Gross Domestic Product","Gross National Product","Per Capita Income","Disposable Income"]', 0, 'Gross Domestic Product (GDP) measures production within a country''s domestic territory.', true, '2026-09-12 10:58:43.461', '2026-09-12 10:58:43.461', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('37b39701-8c43-4c04-8727-f8b295170a23', 'General Mathematics', 'JAMB', null, 2026, null, 'If y = x sin x find d²y/dx²', null, '["2cos x - x sin x","sin x + x cos x","sin x - x cos x","x sin x - 2cos x"]', 0, 'y = x sin x. dy/dx = sin x + x cos x. d²y/dx² = cos x + cos x - x sin x = 2cos x - x sin x.', true, '2026-09-12 11:44:01.373', '2026-09-12 11:44:01.373', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('37b56f4e-cb90-43eb-8853-ce291049b5b8', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'What name did Abraham give the place where he had attempted to sacrifice his son?', null, '["the LORD is with us","the LORD will provide","the Mount of the Lord","the gate of heaven"]', 1, 'Abraham called it ''The LORD will provide'' (Yahweh-jireh).', true, '2026-09-12 10:41:31.815', '2026-09-12 10:41:31.815', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('37bbf3d6-5b70-43b8-b955-710fd8ecd8ac', 'Chemistry', 'JAMB', null, 2026, null, 'Which of the following best explains why diamond is extremely hard while graphite is soft, even though both are allotropes of carbon?', null, '["Diamond contains double bonds","Graphite contains ionic bonds","Diamond has a giant covalent structure while graphite has layered sheets","Graphite molecules are larger"]', 2, 'Diamond forms a rigid 3D tetrahedral giant covalent network, whereas graphite consists of hexagonal layers held by weak van der Waals forces that slide easily.', true, '2026-09-09 17:12:48.154', '2026-09-09 17:12:48.154', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('37c5f517-c291-4234-a791-527c42fa51d8', 'Biology', 'JAMB', null, 2026, null, 'Root hairs have their origin from', null, '["Endodermis","Pericycle","Cortex","Epidermis","Xylem"]', 3, 'Root hairs are extensions of epidermal cells in the root''s maturation zone. These are unicellular outgrowths that increase the surface area of the root for water and mineral absorption. The epidermis is the outer layer of the root that is in direct contact with the soil. The endodermis is a waterproof barrier around the vascular cylinder. The pericycle is the layer that produces lateral roots. The cortex is the region between the epidermis and endodermis, made of parenchyma cells. Xylem is the water-conducting vascular tissue.', true, '2026-09-09 03:18:23.663', '2026-09-09 03:18:23.663', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('37c90bd2-4cba-4a59-a52c-9a81489ad9d0', 'Physics', 'JAMB', null, 2003, null, 'A 90 cm uniform lever has a load of 30 N suspended at 15 cm from one of its ends. If the fulcrum is at the centre of gravity, the force that must be applied at its other end to keep it in horizontal equilibrium is', null, '["20 N","30 N","60 N","15 N"]', 0, 'The fulcrum is at 45 cm. The load is 30 cm from it, and the applied force acts 45 cm from it on the other side. 30 x 30 = F x 45, so F = 20 N.', true, '2026-10-12 19:15:55.155', '2026-10-12 19:15:55.155', null, null, null, 'A 90 cm uniform lever has a load of 30 N suspended at 15 cm from one of its ends. If the fulcrum is at the centre of gravity, the force that must be applied at its other end to keep it in horizontal equilibrium is', '["20 N","30 N","60 N","15 N"]', 'The fulcrum is at 45 cm. The load is 30 cm from it, and the applied force acts 45 cm from it on the other side. 30 x 30 = F x 45, so F = 20 N.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('37cc9a2f-0e61-48af-9e02-714e4ec4c3eb', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). ''<u>An open secret</u>'' means ___________', null, '["a fact that is very secret","an open matter","a secret known to everybody","a confidential matter","a secret told in the open air"]', 2, '''Open secret'' means widely known but officially hidden.', true, '2026-10-24 01:04:13.39', '2026-10-24 01:04:13.39', null, null, null, '(Choose the most appropriate interpretation). ''<u>An open secret</u>'' means ___________', '["a fact that is very secret","an open matter","<u>a secret known to everybody</u>","a confidential matter","a secret told in the open air"]', '''<b>Open secret</b>'' means <b>widely known</b> but officially hidden.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('37d5afdb-daef-4ab3-b85b-2d7e38a594f0', 'General Mathematics', 'JAMB', null, 2026, null, 'In how many ways can 6 subjects be selected from 10 subjects for an examination?', null, '["218","216","215","210"]', 3, '10C6 = 210.', true, '2026-09-12 11:44:06.215', '2026-09-12 11:44:06.215', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('37d84063-046d-49f9-985d-a88e96e6fd49', 'Financial Accounting', 'UTME', null, 2004, null, 'The balance of current accounts of Jide and Haruna are respectively', null, '["N6 000 and N5 000","N3 000 and N3 400","N4 000 and N4 000","N3 000 and N6 000"]', 3, 'Current Account: Jide: Drawings 3000, Salary 2000, Share of Profit 4000 = 6000. Haruna: Drawings 3400, Balance c/d 3000, Share of Profit 4000 = 6000. Balances are N3,000 and N6,000 respectively.', true, '2026-10-12 22:00:03.674', '2026-10-12 22:00:03.674', null, null, null, 'The balance of current accounts of Jide and Haruna are respectively', '["N6 000 and N5 000","N3 000 and N3 400","N4 000 and N4 000","<b>N3 000 and N6 000</b>"]', 'Current Account: Jide: Drawings 3000, Salary 2000, Share of Profit 4000 = 6000. Haruna: Drawings 3400, Balance c/d 3000, Share of Profit 4000 = 6000. Balances are <b>N3,000 and N6,000</b> respectively.', '{"bold":["N3,000 and N6,000"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('37e2efae-c54d-4476-be1e-974b524eec44', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Her reputation is without a <u>blemish</u>.', null, '["problem","fault","blessing","struggle"]', 1, 'Blemish = fault.', true, '2026-10-24 01:01:54.802', '2026-10-24 01:01:54.802', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Her reputation is without a <u>blemish</u>.', '["problem","<u>fault</u>","blessing","struggle"]', '<b>Blemish</b> = <b>fault</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('37e9651f-6960-4b18-9333-e1eacd6d7c9f', 'Chemistry', 'JAMB', null, 2026, null, 'How many moles are present in 44 g of CO₂? (C = 12, O = 16)', null, '["0.5","1.0","2.0","4.0"]', 1, 'Molar mass of CO₂ = 12 + 32 = 44 g/mol. Moles = 44/44 = 1.0 mol.', true, '2026-09-12 11:32:57.445', '2026-09-12 11:32:57.445', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('37e9f307-79e5-49c3-b4ca-49309b3ee799', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. It is advisable to <u>administer</u> the test in the morning when students are fresh.', null, '["perform","set","undertake","give"]', 3, 'Administer = give.', true, '2026-10-24 01:03:54.9', '2026-10-24 01:03:54.9', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. It is advisable to <u>administer</u> the test in the morning when students are fresh.', '["perform","set","undertake","<u>give</u>"]', '<b>Administer</b> = <b>give</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('37ef2885-30a5-469b-ac63-08711b72a4a3', 'Biology', 'JAMB', null, 2026, null, 'Suture joint is found in the', null, '["hip","ankle","skull","elbow"]', 2, 'Suture joints are found in the skull, connecting the flat bones of the cranium. These are immovable (synarthrotic) joints where bones are held together by fibrous connective tissue. The sutures allow the skull to accommodate growth in infancy and then fuse completely in adults. The hip and elbow are synovial joints with significant movement. The ankle is a synovial hinge joint. Suture joints serve important functions: protecting the brain, allowing for skull expansion during development, and providing structural rigidity to the skull.', true, '2026-09-09 03:18:41.097', '2026-09-09 03:18:41.097', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('37f2c044-64df-4b00-95ab-c2f176c66aa9', 'English Language', 'JAMB', null, 2007, null, 'You would be well <u>__________</u> to listen to what the teachers say', null, '["informed","advised","reminded","warned"]', 1, 'Correct form: well advised.', true, '2026-10-24 07:21:45.425', '2026-10-24 07:21:45.425', null, null, null, 'You would be well <u>__________</u> to listen to what the teachers say', '["informed","advised","reminded","warned"]', 'Correct form: well advised.', '{}');
