insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3b92abc3-df06-4712-a0dd-c93abf555b63', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Measures were taken to <u>authenticate</u> the number of the booklets received.', null, '["reaffirm","discredit","discountenance","count"]', 2, 'Authenticate = confirm; opposite = discountenance.', true, '2026-10-24 07:21:17.707', '2026-10-24 07:21:17.707', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Measures were taken to <u>authenticate</u> the number of the booklets received.', '["reaffirm","discredit","discountenance","count"]', 'Authenticate = confirm; opposite = discountenance.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3ba575cc-56e2-4dc8-8ed7-a4c075ba2af9', 'Literature in English', 'JAMB', null, 2026, null, 'Which historical reality makes the poem''s message most urgent?', null, '["technological innovation","the fading of indigenous languages","rise of urbanization","climate migration"]', 1, 'The fading of indigenous languages makes the message urgent.', true, '2026-09-12 11:13:44.042', '2026-09-12 11:13:44.042', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3bb11b3b-45c5-450e-9377-cdb3764ab793', 'Biology', 'JAMB', null, 2026, null, 'The kidney of all vertebrates act as osmoregulators. This means that they', null, '["keep the composition of the plasma constant","regulate osmotic pressure","control the volume of blood entering the kidney","decrease the osmotic pressure of blood","increase the osmotic pressure of the blood"]', 1, 'Osmoregulation is the regulation of osmotic pressure (the concentration of dissolved substances) of body fluids. The kidney regulates osmotic pressure by adjusting the amount of water and solutes excreted or reabsorbed, maintaining the correct balance of water and salts in the body. While the kidney does help keep plasma composition constant (I), this is a broader function that includes osmoregulation. The kidney adjusts water and solute balance to maintain optimal osmotic pressure. It does not simply decrease or increase osmotic pressure, but keeps it within a narrow, functional range.', true, '2026-09-09 03:18:44.175', '2026-09-09 03:18:44.175', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3bb3ee8e-d308-48dd-b4e6-154d362fb20a', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). Victor will not attend the dinner party tonight: he is <u>afraid of his own shadow</u>.', null, '["not in the mood","attending another party","scared of imaginary things","unhappy with his assigned role","unable to forget his fears"]', 2, '''Afraid of own shadow'' = scared of imaginary things.', true, '2026-10-24 01:02:01.846', '2026-10-24 01:02:01.846', null, null, null, '(Choose the most appropriate interpretation). Victor will not attend the dinner party tonight: he is <u>afraid of his own shadow</u>.', '["not in the mood","attending another party","<u>scared of imaginary things</u>","unhappy with his assigned role","unable to forget his fears"]', '''<b>Afraid of own shadow</b>'' = <b>scared of imaginary things</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3bcdf85e-294d-44e8-8d13-5007f25c77e8', 'General Mathematics', 'JAMB', null, 2026, null, 'Find the total surface area of a closed cylinder of diameter 10cm and height 21cm (use π = 22/7)', null, '["817.14cm²","824cm²","834.24cm²","724.34cm²"]', 0, 'r = 5. TSA = 2πr(r+h) = 2(22/7)(5)(26) = 817.14 cm².', true, '2026-09-12 11:44:02.716', '2026-09-12 11:44:02.716', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3bce639a-933b-4212-ac1f-e16eb9015656', 'Hausa', 'JAMB', null, 2011, null, '''Ja ya fado, ja ya đauka'' Wane rukunin adabin baka wannan magana ta fito?', null, '["Zuben baka.","Maganganun azanci.","Salon magana.","Waƙƙin baka."]', 1, 'Wannan magana ta fito ne daga maganganun azanci.', true, '2026-10-13 10:37:21.937', '2026-10-13 10:37:21.937', null, null, null, '''Ja ya fado, ja ya đauka'' Wane rukunin adabin baka wannan magana ta fito?', '["Zuben baka.","Maganganun azanci.","Salon magana.","Waƙƙin baka."]', 'Wannan magana ta fito ne daga maganganun azanci.', '{"bold":["maganganun azanci"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3bd71433-827d-4da9-870c-dc644e5ac310', 'Physics', 'JAMB', null, 1994, null, 'A certain radioisotope of ²³⁵₉₂U emits four alpha particles and three beta particles. The mass number and the atomic number of the resulting element respectively are', null, '["219 and 87","84 and 223","223 and 87","219 and 81"]', 0, 'Mass number = 235 - 4 x 4 = 219. Atomic number = 92 - 4 x 2 + 3 = 87.', true, '2026-10-12 19:15:40.504', '2026-10-12 19:15:40.504', null, null, null, 'A certain radioisotope of <sup>235</sup><sub>92</sub>U emits four alpha particles and three beta particles. The mass number and the atomic number of the resulting element respectively are', '["219 and 87","84 and 223","223 and 87","219 and 81"]', 'Mass number = 235 - 4 x 4 = 219. Atomic number = 92 - 4 x 2 + 3 = 87.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3be0c817-cc47-4fac-9f76-80dc76f40f97', 'Financial Accounting', 'UTME', null, 2004, null, 'The tier of government that uses financial memorandum is the', null, '["federal government","state government","local government","municipal government"]', 2, 'The tier of government that uses financial memorandum is the local government.', true, '2026-10-12 22:00:04.017', '2026-10-12 22:00:04.017', null, null, null, 'The tier of government that uses financial memorandum is the', '["federal government","state government","<b>local government</b>","municipal government"]', 'The tier of government that uses financial memorandum is the <b>local government</b>.', '{"bold":["local government"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3bef02af-4154-462f-bded-c0b089f9492e', 'Biology', 'JAMB', null, 2026, null, 'Which of the following are not among axial skeleton? I. Skull II. Vertebral column III. Limbs IV. Sternum V. Girdle', null, '["III & V","I & II","I, II & IV","I, II & III"]', 0, 'The axial skeleton consists of the skull (I), vertebral column (II), and sternum (IV). The appendicular skeleton consists of the limbs (III) and girdles (V - pectoral and pelvic girdles). Therefore, limbs and girdles are not part of the axial skeleton. The axial skeleton forms the central axis of the body, protecting the brain, spinal cord, and thoracic organs. The appendicular skeleton is attached to the axial skeleton and facilitates movement and locomotion.', true, '2026-09-09 03:18:33.178', '2026-09-09 03:18:33.178', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3befcc58-b0b1-43e2-9b5f-e94eb7737555', 'Physics', 'JAMB', null, 2026, null, 'A resistor connected to a 12V battery draws current of 2A. Calculate the energy dissipated from the load after 5mins.', null, '["7200","3600","6000","120","none"]', 0, 'Energy = Power × Time = V × I × t. E = 12 × 2 × (5 × 60) = 12 × 2 × 300 = 7200J.', true, '2026-09-10 10:56:38.704', '2026-09-10 10:56:38.704', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3bf016b4-38be-4d07-84af-c0ef492c8198', 'Financial Accounting', 'UTME', null, 2003, null, 'What is the receipt and payment account balance?', 'https://res.cloudinary.com/kwi1uv0g/image/upload/v1791841467/questions/jeay1uuu2ryqhptwjzyn.jpg', '["N260 000","N233 000","N155 000","N100 000"]', 2, 'Receipt and Payment account: Sales 260,000 - Club House 100,000 - Electricity 5,000 = Balance c/d 155,000.', true, '2026-10-12 22:00:00.816', '2026-10-12 22:00:00.816', null, null, null, 'What is the receipt and payment account balance?', '["N260 000","N233 000","<b>N155 000</b>","N100 000"]', 'Receipt and Payment account: Sales 260,000 - Club House 100,000 - Electricity 5,000 = Balance c/d <b>155,000</b>.', '{"bold":["155,000"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3bf96200-4268-4b3c-b240-95f2e30c126f', 'Literature in English', 'JAMB', null, 2026, null, 'The poem suggests that language is important because it', null, '["determines economic success","preserves culture and identity","helps people travel","improves political leadership"]', 1, 'Language preserves culture and identity.', true, '2026-09-12 11:05:54.47', '2026-09-12 11:05:54.47', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3bfc74ac-9404-4f7b-9e5d-ca711085ae20', 'English Language', 'JAMB', null, 2024, null, 'The final audit revealed that the construction company was on the rocks. This means that the construction company was', null, '["making higher profit","beginning to gain stronger recognition","in serious financial trouble","situated firmly on a rocky site"]', 2, '"On the rocks" means in serious financial difficulty.', true, '2026-09-18 09:43:02.497', '2026-09-18 09:43:02.497', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3bfffa43-2043-44a0-9db1-4657bfbac34d', 'Physics', 'JAMB', null, 1987, null, 'Which of the following units is equivalent to kg m s⁻¹?', null, '["N s⁻¹","N m s","N s","J s⁻¹"]', 2, 'kg m s⁻¹ is the unit of momentum. Since 1 N = 1 kg m s⁻², 1 N s = 1 kg m s⁻¹.', true, '2026-10-12 19:15:24.596', '2026-10-12 19:15:24.596', null, null, null, 'Which of the following units is equivalent to kg m s<sup>-1</sup>?', '["N s<sup>-1</sup>","N m s","N s","J s<sup>-1</sup>"]', 'kg m s<sup>-1</sup> is the unit of momentum. Since 1 N = 1 kg m s<sup>-2</sup>, 1 N s = 1 kg m s<sup>-1</sup>.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3c0115ae-6ea9-4e63-af03-24d4be610f11', 'English Language', 'JAMB', null, 2007, null, 'He is one of the few teachers who <u>_________</u> consistently encouraged independent learning.', null, '["has","is","have","was"]', 2, '''Who'' â†’ teachers (plural) â†’ have.', true, '2026-10-24 01:04:26.097', '2026-10-24 01:04:26.097', null, null, null, 'He is one of the few teachers who <u>_________</u> consistently encouraged independent learning.', '["has","is","<u>have</u>","was"]', '''<b>Who</b>'' â†’ <b>teachers</b> (plural) â†’ <b>have</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3c0e7c2e-3664-4034-8e04-409ed64cc9d3', 'Government', 'JAMB', null, 2026, null, 'The Nigeria first post-independence constitution is the', null, '["1979","1999","1963","1960"]', 0, 'The first post-independence constitution of Nigeria is the 1963 Republican Constitution. Nigeria became independent in 1960 with the Queen as head of state, but the 1960 constitution was a colonial-era document. In 1963, Nigeria became a republic with the 1963 Constitution, which replaced the Queen with a Nigerian President as head of state. However, the 1979 Constitution was the first constitution drafted entirely by Nigerians after independence. The answer based on common usage is 1963 as the first post-independence constitution.', true, '2026-09-10 10:44:19.466', '2026-09-10 10:44:19.466', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3c43aacb-428b-4808-84b4-cbd04f1e485c', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The school''s badge is the <u>insignia</u> of office for all the prefects in the school.', null, '["seal","recognition","power","symbol"]', 3, 'Insignia = symbol.', true, '2026-10-24 01:04:05.365', '2026-10-24 01:04:05.365', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The school''s badge is the <u>insignia</u> of office for all the prefects in the school.', '["seal","recognition","power","<u>symbol</u>"]', '<b>Insignia</b> = <b>symbol</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3c46d188-078d-4e5a-8376-cad2cdd1d5da', 'Biology', 'JAMB', null, 2002, null, 'In a population of living things, the parameters of size, height, weight and colour are examples of', null, '["discontinuous variations","continuous variations","physiological variations","non-heritable variations"]', 1, 'Size, height, weight and colour are continuous variations.', true, '2026-10-12 20:59:31.731', '2026-10-12 20:59:31.731', null, null, null, 'In a population of living things, the parameters of size, height, weight and colour are examples of', '["discontinuous variations","continuous variations","physiological variations","non-heritable variations"]', 'Size, height, weight and colour are continuous variations.', '{"bold":["continuous variations"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3c4826e3-7404-49a8-b2f1-7005528e2ad5', 'Financial Accounting', 'UTME', null, 2003, null, 'What is the total expenses?', 'https://res.cloudinary.com/kwi1uv0g/image/upload/v1791841510/questions/ioimi0l0cl2xm4mpvwvc.jpg', '["N1 875","N1 764","N1 626","N1 426"]', 2, 'Rates & Insurance 188 + Wages 913 + Rent 325 + Sundry Expenses 200 = 1626.', true, '2026-10-12 22:00:01.311', '2026-10-12 22:00:01.311', null, null, null, 'What is the total expenses?', '["N1 875","N1 764","<b>N1 626</b>","N1 426"]', 'Rates & Insurance 188 + Wages 913 + Rent 325 + Sundry Expenses 200 = <b>1626</b>.', '{"bold":["1626"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3c4d81f5-210c-439e-b7cb-953a32d067cd', 'Financial Accounting', 'UTME', null, 2004, null, 'Goods withdrawn from business for private use are credited to', null, '["drawings","purchases","sales","capital"]', 1, 'Goods withdrawn from business for private use are credited to purchase account as reduction from the total value of purchase.', true, '2026-10-12 22:00:02.345', '2026-10-12 22:00:02.345', null, null, null, 'Goods withdrawn from business for private use are credited to', '["drawings","<b>purchases</b>","sales","capital"]', 'Goods withdrawn from business for private use are credited to <b>purchase account</b> as reduction from the total value of purchase.', '{"bold":["purchase account"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3c50b251-c96b-46ce-b4b7-0f0ae5ba195e', 'Economics', 'JAMB', null, 2026, null, 'Which tends to be a progressive tax in Nigeria?', null, '["income tax","property tax","sales tax","import tax"]', 0, 'Income tax tends to be a progressive tax in Nigeria. A progressive tax takes a larger percentage of income from high-income earners than from low-income earners. Nigeria''s personal income tax uses a graduated rate structure where higher incomes are taxed at higher rates. Property tax, sales tax, and import tax are generally regressive because they take a larger percentage of income from low-income earners.', true, '2026-09-10 10:42:55.133', '2026-09-10 10:42:55.133', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3c56e871-f392-4704-a7d0-46a945b7f76d', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The <u>potential</u> resources of the university should be fully exploited.', null, '["important","latent","abundant","effective"]', 1, 'Potential = latent.', true, '2026-10-24 01:01:45.632', '2026-10-24 01:01:45.632', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The <u>potential</u> resources of the university should be fully exploited.', '["important","<u>latent</u>","abundant","effective"]', '<b>Potential</b> = <b>latent</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3c577a7b-46fd-4473-a7f0-22842ce5ea4f', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). The story has to be taken <u>with a grain of salt</u>. This means that _______________', null, '["you need some salt to listen to the story","there is no salt in the story","the story is questionable","the story is true","you have too much salt in the story"]', 2, '''With a grain of salt'' means with scepticism.', true, '2026-10-24 01:04:12.633', '2026-10-24 01:04:12.633', null, null, null, '(Choose the most appropriate interpretation). The story has to be taken <u>with a grain of salt</u>. This means that _______________', '["you need some salt to listen to the story","there is no salt in the story","<u>the story is questionable</u>","the story is true","you have too much salt in the story"]', '''<b>With a grain of salt</b>'' means with scepticism.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3c7536d9-0bab-4452-86cb-5fe739998a22', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The village girl wore <u>sumptuous</u> clothes.', null, '["loose-fitting","cheap","faded-looking","expensive"]', 3, 'Sumptuous = expensive/luxurious.', true, '2026-10-24 01:01:50.765', '2026-10-24 01:01:50.765', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The village girl wore <u>sumptuous</u> clothes.', '["loose-fitting","cheap","faded-looking","<u>expensive</u>"]', '<b>Sumptuous</b> = <b>expensive</b>/luxurious.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3c832a50-9262-4e75-b37c-0b7fd3b2cd5f', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). As the wedding day approached, the bride began to <u>develop cold feet</u>.', null, '["fall sick","feel cold","be reluctant","become aggressive"]', 2, '''Cold feet'' = reluctance.', true, '2026-10-24 01:02:05.272', '2026-10-24 01:02:05.272', null, null, null, '(Choose the most appropriate interpretation). As the wedding day approached, the bride began to <u>develop cold feet</u>.', '["fall sick","feel cold","<u>be reluctant</u>","become aggressive"]', '''<b>Cold feet</b>'' = <b>reluctance</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3c83823c-073f-4b01-bb68-dbb008e74b99', 'Physics', 'JAMB', null, 2026, null, 'An object moves with uniform speed round a circle. Its acceleration has', null, '["constant magnitude and constant direction","constant magnitude and varying direction","varying magnitude and constant direction","varying magnitude and varying direction"]', 1, 'For an object moving with uniform speed in a circle, the centripetal acceleration has constant magnitude but varying direction. The acceleration always points toward the center of the circle, so its direction changes continuously.', true, '2026-09-10 10:56:45.63', '2026-09-10 10:56:45.63', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3c856a28-0d0d-40d5-b1fa-3fd3aee4a851', 'Economics', 'JAMB', null, 2026, null, 'What happens to a supply curve when variables that are normally held constant are allowed to change?', null, '["The Curve flattens out","there''s a movement along the supply curve","the curve shifts","the curve becomes steeper"]', 2, 'When variables that are normally held constant (such as input prices, technology, taxes, subsidies) are allowed to change, the entire supply curve shifts to a new position. This is called a change in supply. A movement along the supply curve occurs only when the price of the good itself changes. A shift in supply means that at every price, a different quantity is supplied.', true, '2026-09-10 10:42:54.972', '2026-09-10 10:42:54.972', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3c8abdb1-d0b9-4909-91ca-f2a25ffd3a1a', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Amina said she married <u>a doting</u> husband.', null, '["a loving","a fun-loving","an uncaring","a nagging"]', 0, 'Doting = loving.', true, '2026-10-24 01:04:01.62', '2026-10-24 01:04:01.62', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Amina said she married <u>a doting</u> husband.', '["<u>a loving</u>","a fun-loving","an uncaring","a nagging"]', '<b>Doting</b> = <b>a loving</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3c8be4cc-e494-482a-ad06-64e0d376eb16', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The teacher''s face broke into an <u>incredulous</u> smile when he heard Adamu''s reason for coming late.', null, '["irritating","artificial","unbelieving","irresponsible"]', 2, 'Incredulous = unbelieving.', true, '2026-10-24 01:03:59.262', '2026-10-24 01:03:59.262', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The teacher''s face broke into an <u>incredulous</u> smile when he heard Adamu''s reason for coming late.', '["irritating","artificial","<u>unbelieving</u>","irresponsible"]', '<b>Incredulous</b> = <b>unbelieving</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3c9fed1e-5abe-4719-b32f-60633adcb273', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). Telling Ali to break his habit of coming to work late is like <u>knocking your head against a brick wall</u>.', null, '["trying the impossible","asking him to beat you up","making a fool of yourself","asking him to be your enemy","making him break down at work"]', 0, '''Knocking head against brick wall'' = attempt the impossible.', true, '2026-10-24 01:04:15.386', '2026-10-24 01:04:15.386', null, null, null, '(Choose the most appropriate interpretation). Telling Ali to break his habit of coming to work late is like <u>knocking your head against a brick wall</u>.', '["<u>trying the impossible</u>","asking him to beat you up","making a fool of yourself","asking him to be your enemy","making him break down at work"]', '''<b>Knocking head against brick wall</b>'' = <b>attempt the impossible</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3ca79f4b-b6ce-4189-8de2-fab7fd57b449', 'English Language', 'JAMB', null, 2007, null, 'The police <u>______</u> invited to maintain order during the rally.', null, '["was","has been","were","is"]', 2, '''Police'' plural â†’ were.', true, '2026-10-24 01:02:16.429', '2026-10-24 01:02:16.429', null, null, null, 'The police <u>______</u> invited to maintain order during the rally.', '["was","has been","<u>were</u>","is"]', '''<b>Police</b>'' plural â†’ <b>were</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3cc464c7-8b1f-4fca-8be6-27a3b9c82072', 'Biology', 'JAMB', null, 2003, null, 'The stunted growth of a leguminous plant suffering from nitrogen deficiency may be corrected by inoculating the soil with', null, '["denitrifying bacteria","saprophytic bacteria","rhizobium","nitrosomonas"]', 2, 'Rhizobium fixes nitrogen for leguminous plants.', true, '2026-10-12 20:59:32.522', '2026-10-12 20:59:32.522', null, null, null, 'The stunted growth of a leguminous plant suffering from nitrogen deficiency may be corrected by inoculating the soil with', '["denitrifying bacteria","saprophytic bacteria","rhizobium","nitrosomonas"]', 'Rhizobium fixes nitrogen for leguminous plants.', '{"bold":["Rhizobium"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3cc841e3-d102-4a9b-be9e-032093c4f69e', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'According to Peter, Christians living among non-Christians should', null, '["maintain good conduct","live like them","be suspicious of them","avoid them"]', 0, 'Peter says maintain good conduct among non-Christians (1 Peter 2:12).', true, '2026-09-12 10:41:25.664', '2026-09-12 10:41:25.664', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3cd6f588-6ccc-49dc-a100-cf90b1765287', 'Literature in English', 'JAMB', null, 2026, null, '''Haman is an out-at-the elbow looking man'' is referred to as', null, '["Metonymy","Idiomatic expression","Personification","Irony"]', 1, 'It is an idiomatic expression.', true, '2026-09-12 11:07:27.153', '2026-09-12 11:07:27.153', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3cd8c974-bdb0-4a25-bbc3-94ac4eb489e2', 'Physics', 'JAMB', null, 1987, null, 'A constant force of 40 N acting on a body initially at rest gives an acceleration of 0.1 m s⁻² for 4 s. Calculate the work done by the force.', null, '["8 J","10 J","32 J","160 J"]', 2, 'Distance = ½at² = ½ x 0.1 x 16 = 0.8 m. Work = F x s = 40 x 0.8 = 32 J.', true, '2026-10-12 19:15:24.816', '2026-10-12 19:15:24.816', null, null, null, 'A constant force of 40 N acting on a body initially at rest gives an acceleration of 0.1 m s<sup>-2</sup> for 4 s. Calculate the work done by the force.', '["8 J","10 J","32 J","160 J"]', 'Distance = ½at<sup>2</sup> = ½ x 0.1 x 16 = 0.8 m. Work = F x s = 40 x 0.8 = 32 J.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3cd8cce7-b1e8-4b88-8215-9dcaa44e0468', 'Government', 'JAMB', null, 2026, null, 'Which African country experienced a violent resistance movement against British colonial rule known as the Mau Mau rebellion?', null, '["Sudan","Kenya","Ghana","Nigeria"]', 1, 'The Mau Mau rebellion occurred in Kenya.', true, '2026-09-12 11:24:30.277', '2026-09-12 11:24:30.277', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3ce1169a-17eb-49d5-85f0-0835f2f53364', 'Literature in English', 'JAMB', null, 2026, null, 'Which literary device is most prominent in ''borrowed books, borrowed looks''?', null, '["assonance","alliteration","onomatopoeia","Oxymoron"]', 1, 'The literary device most prominent in ''borrowed books, borrowed looks'' is alliteration. Alliteration is the repetition of initial consonant sounds in nearby words. In this phrase, the ''b'' sound is repeated in ''borrowed,'' ''books,'' and ''borrowed.'' It is not assonance (repetition of vowel sounds), onomatopoeia (words that imitate sounds), or oxymoron (contradictory terms).', true, '2026-09-10 10:45:35.366', '2026-09-10 10:45:35.366', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3ce31ee8-bef6-41c0-920b-a7d0555b44d7', 'Physics', 'JAMB', null, 1986, null, 'When two objects P and Q are supplied with the same quantity of heat, the temperature change in P is observed to be twice that of Q. The mass of P is half that of Q. The ratio of the specific heat capacity of P to Q is', null, '["1 : 4","4 : 1","1 : 1","2 : 1"]', 2, 'Q = mcΔθ is the same for both: (m/2)cP(2Δθ) = m cQ Δθ, so cP = cQ and the ratio is 1 : 1.', true, '2026-10-12 19:15:23.628', '2026-10-12 19:15:23.628', null, null, null, 'When two objects P and Q are supplied with the same quantity of heat, the temperature change in P is observed to be twice that of Q. The mass of P is half that of Q. The ratio of the specific heat capacity of P to Q is', '["1 : 4","4 : 1","1 : 1","2 : 1"]', 'Q = mcΔθ is the same for both: (m/2)c<sub>P</sub>(2Δθ) = m c<sub>Q</sub> Δθ, so c<sub>P</sub> = c<sub>Q</sub> and the ratio is 1 : 1.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3cea3a74-9b8f-436f-b13f-42b36f88e28e', 'Physics', 'JAMB', null, 1984, null, 'Normal atmospheric pressure at sea-level is 10⁵ N m⁻² and the acceleration due to gravity is approximately 10 m s⁻². If the atmosphere has a uniform density of 1 kg m⁻³, its height is', null, '["100 m","1000 m","10 000 m","100 000 m","1 000 000 m"]', 2, 'P = ρgh, so h = P/(ρg) = 10⁵/(1 x 10) = 10 000 m.', true, '2026-10-12 19:15:19.829', '2026-10-12 19:15:19.829', null, null, null, 'Normal atmospheric pressure at sea-level is 10<sup>5</sup> N m<sup>-2</sup> and the acceleration due to gravity is approximately 10 m s<sup>-2</sup>. If the atmosphere has a uniform density of 1 kg m<sup>-3</sup>, its height is', '["100 m","1000 m","10 000 m","100 000 m","1 000 000 m"]', 'P = ρgh, so h = P/(ρg) = 10<sup>5</sup>/(1 x 10) = 10 000 m.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3cf0a249-fc89-40d6-948c-b9906466a8d1', 'Physics', 'JAMB', null, 2026, null, 'One of the features of fission process is that', null, '["its product are not radioactive","it leads to chain reactions","neutrons are not released","the sum of the masses of the reactants equals the sum of the masses of the product"]', 1, 'One feature of the fission process is that it leads to chain reactions. When a heavy nucleus splits, it releases neutrons that can cause further fission in other nuclei. The products are radioactive, neutrons are released, and mass is converted to energy (mass defect).', true, '2026-09-10 10:56:40.815', '2026-09-10 10:56:40.815', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3cf1bb2a-a2a4-4c6e-bfe8-229353516a50', 'Literature in English', 'JAMB', null, 2026, null, 'The predominant use of the third person pronoun in a novel creates a', null, '["Sense of detachment on the part of the writer","Sense of detachment on the part of the reader","Psychological affinity with the characters","Balance of opinion among the characters"]', 0, 'Third person creates detachment on the writer''s part.', true, '2026-09-12 11:07:28.977', '2026-09-12 11:07:28.977', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3cf2ddd2-2740-4703-b6fb-2022803e5188', 'Literature in English', 'JAMB', null, 2026, null, 'A narrative that extols the deeds of a heroic figure is a', null, '["Ballad","Folktale","Panegyric","Pastoral"]', 2, 'A panegyric extols heroic deeds.', true, '2026-09-12 11:13:59.968', '2026-09-12 11:13:59.968', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3cf5f945-6b49-4ba4-9038-3c5385b2468e', 'Biology', 'JAMB', null, 2013, null, 'Movement of minerals and chemical compounds within a plant occurs during', null, '["Transpiration","Diffusion","Osmosis","Translocation"]', 3, 'Movement of minerals and chemical compounds within a plant is translocation.', true, '2026-10-12 20:59:46.825', '2026-10-12 20:59:46.825', null, null, null, 'Movement of minerals and chemical compounds within a plant occurs during', '["Transpiration","Diffusion","Osmosis","Translocation"]', 'Movement of minerals and chemical compounds within a plant is translocation.', '{"bold":["translocation"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3cf6289a-802a-4fa8-893d-ed7fb67f5344', 'Economics', 'JAMB', null, 2026, null, '______ is the Total product divided by input', null, '["Total productivity","Average product","Marginal product","Fixed product"]', 1, 'Average product = Total product / Units of input.', true, '2026-09-12 11:00:54.166', '2026-09-12 11:00:54.166', null, null, null, null, null, null, null);
