insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3d1f23d6-b117-4694-a620-0db5c49012ca', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. He is bound to exposes himself by his <u>nefarious</u> activities.', null, '["kind","disreputable","despicable","nocturnal"]', 1, 'Nefarious = disreputable/wicked.', true, '2026-10-24 01:01:48.335', '2026-10-24 01:01:48.335', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. He is bound to exposes himself by his <u>nefarious</u> activities.', '["kind","<u>disreputable</u>","despicable","nocturnal"]', '<b>Nefarious</b> = <b>disreputable</b>/wicked.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3d342305-e8f0-4c6f-96b5-29faa3215a1e', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The enemy interestingly proved a real <u>bulwark</u> on that memorable day.', null, '["protecting force","source of trouble","troubleshooter","tribulation"]', 0, 'Bulwark = protecting force.', true, '2026-10-24 01:01:47.806', '2026-10-24 01:01:47.806', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The enemy interestingly proved a real <u>bulwark</u> on that memorable day.', '["<u>protecting force</u>","source of trouble","troubleshooter","tribulation"]', '<b>Bulwark</b> = <b>protecting force</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3d3d6a29-5bb0-4957-9e4c-82826f37a770', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). The party gathering was thrown into <u>a state of euphoria</u> after the election result was announced.', null, '["pleasure","sadness","excitement","confusion"]', 2, '''Euphoria'' = intense excitement.', true, '2026-10-24 01:02:08.817', '2026-10-24 01:02:08.817', null, null, null, '(Choose the most appropriate interpretation). The party gathering was thrown into <u>a state of euphoria</u> after the election result was announced.', '["pleasure","sadness","<u>excitement</u>","confusion"]', '''<b>Euphoria</b>'' = <b>intense excitement</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3d405c97-3947-4859-b5e9-20a5ab19ad8e', 'Economics', 'JAMB', null, 2026, null, 'To control inflation, the monetary authorities of a country can', null, '["reduce taxes","advise the government to increase its expenditure","Engage in expansive monetary policies","Engage in restrictive monetary policies"]', 3, 'Restrictive monetary policies reduce money supply to control inflation.', true, '2026-09-12 11:00:51.405', '2026-09-12 11:00:51.405', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3d42f3e3-bf05-4d2c-ad99-115927e704bc', 'Physics', 'JAMB', null, 2026, null, 'In sunlight a blue flower looks blue because we see the flower by the light it', null, '["receives from our eye","disperse","absorbs","refracts","reflects"]', 4, 'A blue flower looks blue because we see the flower by the light it reflects. The flower absorbs all colours except blue, which it reflects to our eyes.', true, '2026-09-10 10:56:46.6', '2026-09-10 10:56:46.6', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3d6cc720-e253-4247-b397-3182b0982453', 'Chemistry', 'JAMB', null, 2026, null, 'Calculate the mass of NaCl formed when 2.3 g of sodium reacts completely with chlorine. (Na = 23, Cl = 35.5)', null, '["2.9 g","5.85 g","3.5 g","4.0 g"]', 1, '2Na + Cl₂ → 2NaCl. Moles of Na = 2.3/23 = 0.1 mol. Moles of NaCl = 0.1 mol. Mass = 0.1 × 58.5 = 5.85 g.', true, '2026-09-12 11:32:58.747', '2026-09-12 11:32:58.747', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3d8dbbd1-cf47-44be-99ee-cdbb03d360e4', 'English Language', 'JAMB', null, 2024, null, 'Which is stress on the first syllable (I) transitive (II) aeroplane (III) gymnasium (IV) Festivity', null, '["IV","II&II","III","II"]', 3, '"Aeroplane" has stress on the first syllable.', true, '2026-09-18 09:43:02.362', '2026-09-18 09:43:02.362', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3d906fe5-6fb0-42cd-bf59-310bb81b1916', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Jesus gave the sign of Jonah to the Pharisees to indicate His...', null, '["three-fold office as Prophet, Priest and King","transfiguration and glorification","messianic role","death and resurrection"]', 3, 'Matthew 12:39-40 explains that just as Jonah was three days and three nights in the belly of the fish, so the Son of Man will be three days and three nights in the heart of the earth.', true, '2026-09-09 17:18:27.331', '2026-09-09 17:18:27.331', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3d946fe0-153d-4733-b249-a8a60b93fc04', 'Physics', 'JAMB', null, 1985, null, 'An object is placed 15 cm in front of a concave mirror of radius 40 cm. The image formed is', null, '["Virtual and 60 cm behind the mirror","Real and 60 cm in front of the mirror","Virtual and at infinity","Real and at infinity","Virtual and 40 cm from the mirror."]', 0, 'f = R/2 = 20 cm. 1/v = 1/f - 1/u = 1/20 - 1/15 = -1/60, so v = -60 cm: a virtual image 60 cm behind the mirror (the object is inside the focal length).', true, '2026-10-12 19:15:21.854', '2026-10-12 19:15:21.854', null, null, null, 'An object is placed 15 cm in front of a concave mirror of radius 40 cm. The image formed is', '["Virtual and 60 cm behind the mirror","Real and 60 cm in front of the mirror","Virtual and at infinity","Real and at infinity","Virtual and 40 cm from the mirror."]', 'f = R/2 = 20 cm. 1/v = 1/f - 1/u = 1/20 - 1/15 = -1/60, so v = -60 cm: a virtual image 60 cm behind the mirror (the object is inside the focal length).', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3db448fa-5d07-4719-864d-6cb84ce79114', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The law is often <u>tardy</u> in reacting to trends in attitudes.', null, '["slow","exclusive","generous","quick"]', 0, 'Tardy = slow.', true, '2026-10-24 01:01:54.326', '2026-10-24 01:01:54.326', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The law is often <u>tardy</u> in reacting to trends in attitudes.', '["<u>slow</u>","exclusive","generous","quick"]', '<b>Tardy</b> = <b>slow</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3db467d8-b5eb-46c1-8c96-26b17f664801', 'Physics', 'JAMB', null, 1994, null, 'Heat is supplied to a test tube containing 100 g of ice at its melting point. The ice melts completely in 1 min. What is the power rating of the source of heat? (Latent heat of fusion of ice = 336 J g⁻¹)', null, '["336 W","450 W","560 W","600 W"]', 2, 'Heat = 100 x 336 = 33 600 J in 60 s. Power = 33 600/60 = 560 W.', true, '2026-10-12 19:15:39.532', '2026-10-12 19:15:39.532', null, null, null, 'Heat is supplied to a test tube containing 100 g of ice at its melting point. The ice melts completely in 1 min. What is the power rating of the source of heat? (Latent heat of fusion of ice = 336 J g<sup>-1</sup>)', '["336 W","450 W","560 W","600 W"]', 'Heat = 100 x 336 = 33 600 J in 60 s. Power = 33 600/60 = 560 W.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3db78815-1595-4287-9f14-1263aa98bb62', 'Chemistry', 'JAMB', null, 2026, null, 'Which trend occurs down Group 17 elements?', null, '["Increasing oxidizing power","Increasing atomic radius","Decreasing molecular mass","Increasing electronegativity"]', 1, 'Atomic radius increases down Group 17 (halogens). As you go down the group, additional electron shells are added, increasing the distance of the outermost electrons from the nucleus. Oxidizing power and electronegativity decrease down the group, while molecular mass increases.', true, '2026-09-12 09:38:16.805', '2026-09-12 09:38:16.805', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3db97153-e9c5-4451-b5b5-72073d5f533e', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The popularity of the slogan is beginning to <u>wane</u>.', null, '["wear","slide","thin out","decline"]', 3, 'Wane = decline.', true, '2026-10-24 01:03:56.129', '2026-10-24 01:03:56.129', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The popularity of the slogan is beginning to <u>wane</u>.', '["wear","slide","thin out","<u>decline</u>"]', '<b>Wane</b> = <b>decline</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3dbc8a71-6daf-4838-8bc1-30c01ca067a1', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. This year''s harvest is <u>surplus</u>.', null, '["enough for our need","limitless","more than enough","plenty"]', 2, 'Surplus = more than enough.', true, '2026-10-24 01:01:41.775', '2026-10-24 01:01:41.775', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. This year''s harvest is <u>surplus</u>.', '["enough for our need","limitless","<u>more than enough</u>","plenty"]', '<b>Surplus</b> = <b>more than enough</b>.', '{}');
