insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3dd85e47-183b-428d-bc20-23a841d66a17', 'Economics', 'JAMB', null, 2026, null, 'Cooperative societies are formed mainly to', null, '["assist producers to maximize their profits","encourage thrift and credit among members","promote and maintain the welfare of members","break the monopolies of private companies"]', 2, 'Cooperative societies are formed to promote and maintain the welfare of members.', true, '2026-09-12 11:01:51.413', '2026-09-12 11:01:51.413', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3de57476-ef31-409f-b441-b7ad1c29008d', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Funmi is just being <u>facetious</u> about her marrying a soldier.', null, '["unfaithful","serious","crazy","unserious"]', 3, 'Facetious = unserious.', true, '2026-10-24 01:01:50.713', '2026-10-24 01:01:50.713', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Funmi is just being <u>facetious</u> about her marrying a soldier.', '["unfaithful","serious","crazy","<u>unserious</u>"]', '<b>Facetious</b> = <b>unserious</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3de79dc9-3a89-4016-bd7d-c70d3aaca591', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The man''s story sounded <u>plausible</u> to his audience.', null, '["fantastic","credulous","credible","entertaining"]', 2, 'Plausible = credible.', true, '2026-10-24 01:04:04.991', '2026-10-24 01:04:04.991', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The man''s story sounded <u>plausible</u> to his audience.', '["fantastic","credulous","<u>credible</u>","entertaining"]', '<b>Plausible</b> = <b>credible</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3dee2f5d-80a3-4591-b505-0bd1f7b8b54f', 'Biology', 'JAMB', null, 2026, null, 'Tape worm absorbs food through its', null, '["scolex","body surface","sucker","proglottids"]', 1, 'The tapeworm absorbs food through its body surface (tegument). Tapeworms lack a digestive system and absorb nutrients directly through their outer covering from the host''s intestinal contents. The scolex is the head region with suckers for attachment. The sucker is used for attachment to the host intestine. Proglottids are the segments containing reproductive organs. The tapeworm''s body surface is adapted for maximum absorption of nutrients due to its high surface area, which is essential for its parasitic lifestyle.', true, '2026-09-09 03:18:49.758', '2026-09-09 03:18:49.758', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3dfc53ea-97b2-4058-945a-3eba78562aaf', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The principal was advised to be <u>flexible</u> on critical issues.', null, '["livid","evasive","cautious","rigid"]', 3, 'Flexible = adaptable; opposite = rigid.', true, '2026-10-24 07:21:26.896', '2026-10-24 07:21:26.896', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The principal was advised to be <u>flexible</u> on critical issues.', '["livid","evasive","cautious","rigid"]', 'Flexible = adaptable; opposite = rigid.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3dfc5de7-3a59-4954-8eba-dd1c9f7c14ec', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearly opposite in meaning to the word(s) or phrase in italics and underlined. The chief was <u>generous</u> in his award of university scholarships.', null, '["noble","considerate","liberal","mean","honest"]', 3, 'Generous = liberal; opposite = mean.', true, '2026-10-24 07:21:10.707', '2026-10-24 07:21:10.707', null, null, null, 'Choose the option nearly opposite in meaning to the word(s) or phrase in italics and underlined. The chief was <u>generous</u> in his award of university scholarships.', '["noble","considerate","liberal","mean","honest"]', 'Generous = liberal; opposite = mean.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3e090933-4044-4104-8a84-634fd5c2eff0', 'Physics', 'JAMB', null, 1986, null, 'A ball is thrown vertically into the air with an initial velocity u. What is the greatest height reached?', null, '["u/2g","3u²/2g","u²/g","u²/2g."]', 3, 'At the top v = 0, so 0 = u² - 2gh and h = u²/2g.', true, '2026-10-12 19:15:22.93', '2026-10-12 19:15:22.93', null, null, null, 'A ball is thrown vertically into the air with an initial velocity u. What is the greatest height reached?', '["u/2g","3u<sup>2</sup>/2g","u<sup>2</sup>/g","u<sup>2</sup>/2g."]', 'At the top v = 0, so 0 = u<sup>2</sup> - 2gh and h = u<sup>2</sup>/2g.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3e0ad2f1-dabc-4b16-a825-97316ec2c1fc', 'Physics', 'JAMB', null, 1993, null, 'When the volume of a given mass of gas is halved and its temperature doubled, the pressure', null, '["Remains constant","Increases by a factor of 4","Increases by a factor of 3","Decreases by a factor of 4"]', 1, 'P V/T is constant. P'' = P x (V/(V/2)) x (2T/T) = P x 2 x 2 = 4P.', true, '2026-10-12 19:15:37.543', '2026-10-12 19:15:37.543', null, null, null, 'When the volume of a given mass of gas is halved and its temperature doubled, the pressure', '["Remains constant","Increases by a factor of 4","Increases by a factor of 3","Decreases by a factor of 4"]', 'P V/T is constant. P'' = P x (V/(V/2)) x (2T/T) = P x 2 x 2 = 4P.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3e16be1d-1e79-48f3-85b2-b8a744163624', 'Government', 'JAMB', null, 2026, null, 'A naturalized citizen can lose his citizenship if found guilty of', null, '["treason","evading of taxes","electoral violence","loitering"]', 0, 'A naturalized citizen can lose citizenship if found guilty of treason.', true, '2026-09-12 11:24:13.511', '2026-09-12 11:24:13.511', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3e208002-f27f-46d2-bce2-c51f7f7b938b', 'Literature in English', 'JAMB', null, 2026, null, 'The poem can be classified as a work of', null, '["Romanticism","Imagism","Magical Realism","Post-colonial literature"]', 3, 'The poem can be classified as a work of Post-colonial literature. The poem deals with themes of national trauma, violence, and the aftermath of colonial rule in Sierra Leone. Post-colonial literature addresses the cultural, political, and psychological impact of colonialism and its legacy. Romanticism focuses on emotion and nature, Imagism on precise images, and Magical Realism blends fantasy with reality.', true, '2026-09-10 10:47:54.512', '2026-09-10 10:47:54.512', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3e2f870b-e227-4538-a379-397d6bcfbee2', 'Government', 'JAMB', null, 2026, null, 'Political parties aim at all the following except', null, '["Contesting elections","Forming a government","Organizing general elections","Educating the electorate politically"]', 2, 'Organizing general elections is the duty of the electoral commission, not political parties.', true, '2026-09-12 11:24:22.414', '2026-09-12 11:24:22.414', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3e331294-9ca7-4759-bf26-3cf5a657443e', 'Biology', 'JAMB', null, 2026, null, 'The turbidity of a pond can be measured using the', null, '["Anemometer","Secchi disc","Theodolite","Hydrometer"]', 1, 'A Secchi disc is a circular white disc attached to a graduated line, lowered into water to measure turbidity (cloudiness). The depth at which it disappears from sight indicates water clarity, with shallower readings indicating higher turbidity. An anemometer measures wind speed. A theodolite measures angles in surveying. A hydrometer measures the specific gravity (density) of liquids. Turbidity is an important ecological parameter affecting light penetration, photosynthesis, and the distribution of aquatic organisms.', true, '2026-09-09 03:18:21.209', '2026-09-09 03:18:21.209', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3e3ab737-9487-40ef-a6cd-576b4ab8fa5a', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. His story gave us <u>an inkling</u> of what he passed through during the strike.', null, '["a possible idea","a summary","a taste","the right view"]', 0, 'Inkling = possible idea.', true, '2026-10-24 01:04:07.83', '2026-10-24 01:04:07.83', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. His story gave us <u>an inkling</u> of what he passed through during the strike.', '["<u>a possible idea</u>","a summary","a taste","the right view"]', '<b>Inkling</b> = <b>a possible idea</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3e50422a-051c-4461-9029-3284d16062bd', 'Physics', 'JAMB', null, 2003, null, 'When an alternating current given by I = 10 sin(120πt) passes through a 12 ohm resistor, the power dissipated in the resistor is', null, '["120 W","20 W","600 W","1200 W"]', 2, 'Irms = 10/√2, so Irms² = 50. P = Irms²R = 50 x 12 = 600 W.', true, '2026-10-12 19:15:57.793', '2026-10-12 19:15:57.793', null, null, null, 'When an alternating current given by I = 10 sin(120πt) passes through a 12 ohm resistor, the power dissipated in the resistor is', '["120 W","20 W","600 W","1200 W"]', 'I<sub>rms</sub> = 10/√2, so I<sub>rms</sub><sup>2</sup> = 50. P = I<sub>rms</sub><sup>2</sup>R = 50 x 12 = 600 W.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3e57ffbf-9a0a-4f45-9b41-1de7045fca5d', 'Biology', 'JAMB', null, 2026, null, 'The appendicular skeleton comprises of', null, '["pectoral and pelvic girdles","forelimbs, skull and pectoral girdle","lungs and ribs","skull and the vertebral column"]', 0, 'The appendicular skeleton comprises the pectoral girdle and pelvic girdle, along with the limbs attached to them. It includes all the bones associated with the appendages (limbs) of the body. The pectoral girdle includes the scapula and clavicle, attaching the forelimbs. The pelvic girdle includes the hip bones, attaching the hindlimbs. The limbs themselves are part of the appendicular skeleton. The skull and vertebral column are part of the axial skeleton. Lungs and ribs are not part of the skeleton proper. The appendicular skeleton allows for movement and locomotion.', true, '2026-09-09 03:18:56.812', '2026-09-09 03:18:56.812', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3e58cec5-ff35-4fd0-baca-194cb27e1ad6', 'General Mathematics', 'JAMB', null, 2026, null, 'Add the same number to the numerator and denominator of 3/18. If the resulting fraction is 1/2, then the number added is', null, '["13","14","15","12"]', 3, '(3+n)/(18+n) = 1/2. 6+2n = 18+n. n = 12.', true, '2026-09-12 11:43:45.986', '2026-09-12 11:43:45.986', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3e660c35-78df-4631-ac80-e24738c82101', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'According to John, the accusation of the Jews levelled against Jesus before Pilate was that he was', null, '["an evildoer","an imposter","a perverter","a blasphemer"]', 0, 'The Jews accused Jesus of being an evildoer. Pilate said to them, ''Take him yourselves and judge him by your own law.'' The Jews said to him, ''It is not lawful for us to put any man to death.'' They accused Jesus of being an evildoer.', true, '2026-09-12 09:46:11.871', '2026-09-12 09:46:11.871', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3e7805f8-5694-4f83-be3a-9ec8886418cf', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). He works long hours collecting trash to <u>eke out a livelihood</u>.', null, '["try a living","struggle for a living","make a living","carve out a living"]', 2, '''Eke out a livelihood'' = make a living.', true, '2026-10-24 01:02:04.107', '2026-10-24 01:02:04.107', null, null, null, '(Choose the most appropriate interpretation). He works long hours collecting trash to <u>eke out a livelihood</u>.', '["try a living","struggle for a living","<u>make a living</u>","carve out a living"]', '''<b>Eke out a livelihood</b>'' = <b>make a living</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3e8c8a79-8dc6-4ead-ab28-f297aaf7936d', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). Look at the <u>tell-tale signs</u> of battering on her.', null, '["confirming looks","suspicious marks","revealing marks","signifying marks"]', 2, '''Tell-tale signs'' = revealing marks.', true, '2026-10-24 01:02:03.018', '2026-10-24 01:02:03.018', null, null, null, '(Choose the most appropriate interpretation). Look at the <u>tell-tale signs</u> of battering on her.', '["confirming looks","suspicious marks","<u>revealing marks</u>","signifying marks"]', '''<b>Tell-tale signs</b>'' = <b>revealing marks</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3e8f516f-21de-4150-a974-900e4c0af7c7', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. He was very much respected, though he had no <u>temporal</u> power.', null, '["spiritual","permanent","mundane","ephemeral"]', 0, 'Temporal = worldly; opposite = spiritual.', true, '2026-10-24 07:21:27.454', '2026-10-24 07:21:27.454', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. He was very much respected, though he had no <u>temporal</u> power.', '["spiritual","permanent","mundane","ephemeral"]', 'Temporal = worldly; opposite = spiritual.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3e917021-201a-4560-8b54-c3ad1940ec62', 'Economics', 'JAMB', null, 2026, null, 'The bank established to finance projects aimed at promoting economic and social development within the African continent is;', null, '["African development bank","African bank for commerce and industry","Economic bank for African","Recovery fund bank for Africa"]', 0, 'African Development Bank finances development projects in Africa.', true, '2026-09-12 11:01:26.93', '2026-09-12 11:01:26.93', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3e92c83d-b94d-4817-b853-8219da35b2db', 'Yoruba', 'JAMB', null, 2002, null, '‘Një o gbò kí o panumò’, jë gbólóhùn', null, '["àlàyé","àyç","ibá iyèlé","kání."]', 1, '‘Një o gbò kí o panumò’, jë gbólóhùn àyç.', true, '2026-10-13 13:22:38.633', '2026-10-13 13:22:38.633', null, null, null, '‘Një o gbò kí o panumò’, jë gbólóhùn', '["àlàyé","àyç","ibá iyèlé","kání."]', '‘Një o gbò kí o panumò’, jë gbólóhùn àyç.', '{"bold":["àyç"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3e9b0a6f-0807-4ae4-b4c3-09591404cf75', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. She is known for her <u>bizarre</u> dressing', null, '["natural","weird","obsolete","odious"]', 0, 'Bizarre = strange; opposite = natural.', true, '2026-10-24 07:21:31.224', '2026-10-24 07:21:31.224', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. She is known for her <u>bizarre</u> dressing', '["natural","weird","obsolete","odious"]', 'Bizarre = strange; opposite = natural.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3ea73b17-81a0-4812-b74b-8708e1206ab0', 'Literature in English', 'JAMB', null, 2026, null, 'The first-person narrative style is used when the main character in a novel recounts', null, '["The author''s Story","Other character''s story","His own story","His best friend''s story"]', 2, 'First-person narrative recounts the character''s own story.', true, '2026-09-12 11:13:49.88', '2026-09-12 11:13:49.88', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3ea7ca5f-d3eb-4b36-9bc9-5f8d79a2603f', 'English Language', 'JAMB', null, 2007, null, 'There is no point getting upset by problems; I take them <u>__________</u>', null, '["in my stride","on the spur of the moment","by leaps and bounds","in a jiffy"]', 0, 'Correct form: in my stride.', true, '2026-10-24 07:21:41.903', '2026-10-24 07:21:41.903', null, null, null, 'There is no point getting upset by problems; I take them <u>__________</u>', '["in my stride","on the spur of the moment","by leaps and bounds","in a jiffy"]', 'Correct form: in my stride.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3eaf9a3d-b298-4302-a48b-6121e2f3fbf4', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'One of the reasons why Saul was rejected as king was that', null, '["the Lord preferred David","he disobeyed God by not destroying all that belonged to the Amalekites","he spared Jonathan","he said there should be no king in Israel","he oppressed the people"]', 1, 'Saul disobeyed God by not destroying the Amalekites completely.', true, '2026-09-12 10:41:41.896', '2026-09-12 10:41:41.896', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3ebfe3cc-2256-400d-bc6a-3259b471dd10', 'Biology', 'JAMB', null, 2026, null, 'Gamete are formed by a kind of cell division called', null, '["Equatorial cell division","Fragmentation","Chromosome","Reductional cell division"]', 3, 'Gametes (sex cells) are formed by reductional cell division, which is meiosis. Meiosis is called reductional division because the chromosome number is halved (from diploid 2n to haploid n). This ensures that when gametes fuse during fertilization, the diploid number is restored. Equatorial division is not a standard term. Fragmentation is an asexual reproductive method. Chromosome is a structure, not a division type. Meiosis involves two divisions (meiosis I and II) and produces four genetically diverse haploid cells from a single diploid cell.', true, '2026-09-09 03:18:34.577', '2026-09-09 03:18:34.577', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3ed45dea-bc21-4a21-ab14-a7ebabb1fffd', 'Government', 'JAMB', null, 2026, null, 'Which constitution first introduced the office the Prime Minister in Nigeria?', null, '["Clifford Constitution(1922)","Lyttleton Constitution(1954)","Macpherson Constitution(1951)","Independence Constitution(1960)"]', 1, 'The Lyttleton Constitution of 1954 first introduced the office of Prime Minister.', true, '2026-09-12 11:24:46.693', '2026-09-12 11:24:46.693', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3eddbe2b-ecdb-4339-9f9d-1f24471d3544', 'Biology', 'JAMB', null, 2026, null, 'Vegetative propagation is a form of', null, '["sexual reproduction","asexual reproduction","conjugation","fertilization","vegetative pollination"]', 1, 'Vegetative propagation is a form of asexual reproduction in which new plants develop from vegetative parts (stems, roots, leaves) of a parent plant without the formation of seeds or gametes. It produces offspring that are genetically identical to the parent (clones). Conjugation is a form of sexual reproduction in bacteria and some algae where genetic material is exchanged. Fertilization is the fusion of gametes. Vegetative pollination is not a term in biology. Vegetative propagation occurs naturally (runners, rhizomes) or through human intervention (cuttings, grafting).', true, '2026-09-09 03:18:28.83', '2026-09-09 03:18:28.83', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3edee9be-cc6e-48b9-b157-70f3c5d66ff8', 'Government', 'JAMB', null, 2026, null, 'Apart from globalization, what other factor to a large extent affects the sovereignty of a state?', null, '["Right of a franchise","System of government","International laws","Inalienability"]', 2, 'International laws affect the sovereignty of a state.', true, '2026-09-12 11:24:29.101', '2026-09-12 11:24:29.101', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3eea9d89-0be5-4e4d-b792-1ede61b6c88c', 'Economics', 'JAMB', null, 2026, null, 'What is the highest body in ECOWAS organ?', null, '["General assembly","Council of ministers","Authority of head of state and government","Executive council"]', 2, 'The Authority of Heads of State and Government is the highest body in ECOWAS.', true, '2026-09-12 11:02:01.942', '2026-09-12 11:02:01.942', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3eee0695-3624-4c8c-a229-f13dc989f6ae', 'Biology', 'JAMB', null, 2011, null, 'In an experiment to determine the percentage of humus and water in a soil sample, the following results were obtained. Weight of the evaporating basin alone = 80.5g, Weight of basin and soil = 101.5g, Weight after drying the soil in the oven = 99.0g, Weight of basin and roasted soil = 95.5g. The percentage of humus in the soil sample is', null, '["16.7%","17.6%","26.7%","16.2%."]', 0, 'The percentage of humus in the soil sample is 16.7%.', true, '2026-10-12 20:59:42.914', '2026-10-12 20:59:42.914', null, null, null, 'In an experiment to determine the percentage of humus and water in a soil sample, the following results were obtained. Weight of the evaporating basin alone = 80.5g, Weight of basin and soil = 101.5g, Weight after drying the soil in the oven = 99.0g, Weight of basin and roasted soil = 95.5g. The percentage of humus in the soil sample is', '["16.7%","17.6%","26.7%","16.2%."]', 'The percentage of humus in the soil sample is 16.7%.', '{"bold":["16.7%"],"italic":[],"underline":[],"fillBlanks":[]}');
