insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3ef74c2e-5def-4715-a5cd-7c46cd3afcec', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Jesus said to her, ''I am the resurrection and the life; he who believes in me, though he dies, yet shall he live, and whoever lives and believes in me shall never die...'' On what occasion was this statement made?', null, '["on the day of Jesus'' resurrection","on the day Jesus restored Lazarus back to life","when Jairus'' daughter was raised from the dead","when Jesus demonstrated the fact of his resurrection to Thomas"]', 1, 'Jesus said this to Martha before raising Lazarus.', true, '2026-09-12 10:41:37.418', '2026-09-12 10:41:37.418', null, null, null, null, null, null, null);
