insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3f0fbd77-7e01-4363-b203-f580346aa581', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The teacher''s face broke into an <u>incredulous</u> smile when he heard Adamu''s reason for coming late.', null, '["irritating","artificial","unbelieving","irresponsible"]', 2, 'Incredulous = unbelieving.', true, '2026-10-24 01:01:47.167', '2026-10-24 01:01:47.167', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The teacher''s face broke into an <u>incredulous</u> smile when he heard Adamu''s reason for coming late.', '["irritating","artificial","<u>unbelieving</u>","irresponsible"]', '<b>Incredulous</b> = <b>unbelieving</b>.', '{}');
