insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3f1d4df4-884f-4b22-889f-f4d8e28f4dc8', 'Literature in English', 'JAMB', null, 2026, null, 'The main difference between Drama and prose is that drama is meant to be', null, '["written for silent reading","performed before an audience","narrated by an author","told through description"]', 1, 'Drama is meant to be performed before an audience.', true, '2026-09-12 11:12:12.473', '2026-09-12 11:12:12.473', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3f1e6b74-c324-405b-b172-83f4da1c63e5', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation).<u>Watch it!</u> You could be followed said the robber.', null, '["Look around","Be sober","Be vigilant","Look out"]', 2, '''Watch it'' = be vigilant.', true, '2026-10-24 01:04:16.644', '2026-10-24 01:04:16.644', null, null, null, '(Choose the most appropriate interpretation).<u>Watch it!</u> You could be followed said the robber.', '["Look around","Be sober","<u>Be vigilant</u>","Look out"]', '''<b>Watch it</b>'' = <b>be vigilant</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3f231559-4bca-4424-9a54-1346cdde2f5e', 'English Language', 'JAMB', null, 2007, null, 'Neither the chairman nor the board members <u>______</u> aware of the development.', null, '["was","is","are","has been"]', 2, 'Nearest subject ''members'' plural â†’ are.', true, '2026-10-24 01:04:29.543', '2026-10-24 01:04:29.543', null, null, null, 'Neither the chairman nor the board members <u>______</u> aware of the development.', '["was","is","<u>are</u>","has been"]', 'Nearest subject ''<b>members</b>'' plural â†’ <b>are</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3f24226e-18f2-4a8e-b44e-bd7e7c3c8509', 'Physics', 'JAMB', null, 2026, null, 'Calculate the ratio of the period of the minute hand and second hand', null, '["1:12","1:60","12:1","60:1"]', 3, 'Period of minute hand = 3600s. Period of second hand = 60s. Ratio = 3600:60 = 60:1.', true, '2026-09-10 10:56:45.522', '2026-09-10 10:56:45.522', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3f28fadf-b1dc-41d1-be22-b341196c0fde', 'Biology', 'JAMB', null, 2026, null, 'The anterior chamber of the eye is filled with', null, '["aqueous humour","synovial fluid","vitreous humour","lymphatic fluid"]', 0, 'The anterior chamber of the eye is filled with aqueous humour, a clear watery fluid that maintains the shape of the front part of the eye and provides nutrients to the cornea and lens. Synovial fluid is found in joints. Vitreous humour fills the posterior chamber (behind the lens). Lymphatic fluid is part of the lymphatic system. Aqueous humour is continuously produced by the ciliary body and drains through the trabecular meshwork. Imbalance in its production and drainage can lead to glaucoma.', true, '2026-09-09 03:18:50.419', '2026-09-09 03:18:50.419', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3f2ae40a-1398-4a91-8ed8-b056aec30081', 'Financial Accounting', 'UTME', null, 2001, null, 'The main objective of accounting report is to provide information about', null, '["a company''s shareholding","an entity''s management","the efficacy of assets","a company''s economic resources"]', 3, 'The main objective of accounting report is to provide information about a company''s economic resources.', true, '2026-10-12 22:00:04.164', '2026-10-12 22:00:04.164', null, null, null, 'The main objective of accounting report is to provide information about', '["a company''s shareholding","an entity''s management","the efficacy of assets","<b>a company''s economic resources</b>"]', 'The main objective of accounting report is to provide information about <b>a company''s economic resources</b>.', '{"bold":["a company''s economic resources"],"italic":[],"underline":[],"fillBlanks":[]}');
