insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3f48e45c-b8e1-48a5-bfe9-e1b544d78956', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'What effect did the decision of the Council of Jerusalem have on the Early Church?', null, '["Members became more united","The Jews became leaders of the community","The church experienced freedom from persecution","Gentiles were free to be members"]', 3, 'The decision of the Council of Jerusalem meant that Gentiles were free to be members of the church without being required to be circumcised or follow the law of Moses. This settled the controversy and allowed the church to grow among the Gentiles.', true, '2026-09-12 09:46:16', '2026-09-12 09:46:16', null, null, null, null, null, null, null);
