insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3f4db541-3139-48de-8eba-b5d046d96412', 'Biology', 'JAMB', null, 2013, null, 'An example of a parasitic protozoan is', null, '["Euglena","Chlamydomonas","Paramecium","Plasmodium"]', 3, 'Plasmodium is a parasitic protozoan.', true, '2026-10-12 20:59:47.08', '2026-10-12 20:59:47.08', null, null, null, 'An example of a parasitic protozoan is', '["Euglena","Chlamydomonas","Paramecium","Plasmodium"]', 'Plasmodium is a parasitic protozoan.', '{"bold":["Plasmodium"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3f6256cf-c871-47f6-9e37-993720de001a', 'English Language', 'JAMB', null, 2024, null, 'Choose the option that has the same vowel sound as the one represented by the letter(s) underlined: pleasure', null, '["pliable","pleat","plenary","jeopardy"]', 3, 'The "ea" in "pleasure" sounds like /e/, same as the "eo" in "jeopardy."', true, '2026-09-18 09:24:04.951', '2026-09-18 09:24:04.951', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3f6b8769-f6ec-43ae-a4cb-b6dbd3513d62', 'Biology', 'JAMB', null, 2004, null, 'The function of the long-winged reproductives in a termite colony is to', null, '["disperse the population","feed the young","participate in swarming","protect the young"]', 2, 'Long-winged reproductives participate in swarming.', true, '2026-10-12 20:59:34.609', '2026-10-12 20:59:34.609', null, null, null, 'The function of the long-winged reproductives in a termite colony is to', '["disperse the population","feed the young","participate in swarming","protect the young"]', 'Long-winged reproductives participate in swarming.', '{"bold":["participate in swarming"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3f7d87d6-41d5-450b-9cd8-4dae6bd79212', 'Physics', 'JAMB', null, 1995, null, 'The wavelength of the signal from a radio transmitter is 1500 m and the frequency is 200 kHz. What is the wavelength for a transmitter operating at 1000 kHz?', null, '["7 500 m","300 m","75 m","15 m"]', 1, 'v = fλ is constant for radio waves, so λ₂ = 1500 x 200/1000 = 300 m.', true, '2026-10-12 19:15:41.629', '2026-10-12 19:15:41.629', null, null, null, 'The wavelength of the signal from a radio transmitter is 1500 m and the frequency is 200 kHz. What is the wavelength for a transmitter operating at 1000 kHz?', '["7 500 m","300 m","75 m","15 m"]', 'v = fλ is constant for radio waves, so λ<sub>2</sub> = 1500 x 200/1000 = 300 m.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3f89d7c3-8c4b-43d9-a501-21fb0a104fd2', 'Chemistry', 'JAMB', null, 2026, null, 'The shapes of CO2, H2O and CH4 respectively are', null, '["bent, linear and tetrahedral","bent, tetrahedral and linear","tetrahedral, linear and bent","linear, bent and tetrahedral"]', 3, 'Carbon dioxide is linear, water is bent/V-shaped due to lone pairs, and methane forms a symmetrical regular tetrahedron.', true, '2026-09-09 17:12:47.098', '2026-09-09 17:12:47.098', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3f9c2da4-3895-429c-874d-7f99b5099ede', 'English Language', 'JAMB', null, 2024, null, 'Which of the following best interprets the expression: the usher took a French leave while the programme was on.', null, '["the usher left without permission","the usher left quickly and came back as fast","the usher left hurriedly","the usher visited France shortly"]', 0, '"French leave" means leaving without permission.', true, '2026-09-18 09:23:08.296', '2026-09-18 09:23:08.296', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3fa29d62-6730-46df-814a-590e7c987f1d', 'Literature in English', 'JAMB', null, 2026, null, 'The war had ended, but its shadows lingered in the minds of the people. Each step forward seemed weighed down by memories that refused to fade. The dominant literary device in the passage above is', null, '["Hyperbole","Metaphor","Irony","Euphemism"]', 1, 'The dominant device is metaphor (shadows lingering in minds).', true, '2026-09-12 11:12:01.191', '2026-09-12 11:12:01.191', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3fae661c-9a82-4295-9b0e-86d42a1509d2', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). These job cuts are just <u>the thin end of the wedge</u>', null, '["Job cuts are very rampant","Job cuts are inconclusive","Job cuts are the beginning of unpleasant situations","Job cuts are the beginning of healthy rivalries"]', 2, '''Thin end of the wedge'' = beginning of something unpleasant.', true, '2026-10-24 01:02:10.363', '2026-10-24 01:02:10.363', null, null, null, '(Choose the most appropriate interpretation). These job cuts are just <u>the thin end of the wedge</u>', '["Job cuts are very rampant","Job cuts are inconclusive","<u>Job cuts are the beginning of unpleasant situations</u>","Job cuts are the beginning of healthy rivalries"]', '''<b>Thin end of the wedge</b>'' = <b>beginning of something unpleasant</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3fc097fe-8754-49bf-a6f5-0b5d63b3e5a4', 'English Language', 'JAMB', null, 2007, null, 'Yesterday in the hall, Ola said that <u>__________</u> his watch', null, '["he had forget","he had mislaid","he has misplaced","he have lost"]', 1, 'Correct form: he had mislaid.', true, '2026-10-24 07:21:39.772', '2026-10-24 07:21:39.772', null, null, null, 'Yesterday in the hall, Ola said that <u>__________</u> his watch', '["he had forget","he had mislaid","he has misplaced","he have lost"]', 'Correct form: he had mislaid.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3fc2e218-d3d6-4ac6-af05-38c43e63f8cf', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. governor''s wife, in <u>characteristically</u> simple attire, walked into the hall unnoticed.', null, '["eccentrically","typically","consistently","intrinsically"]', 1, 'Characteristically = typically.', true, '2026-10-24 01:01:47.695', '2026-10-24 01:01:47.695', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. governor''s wife, in <u>characteristically</u> simple attire, walked into the hall unnoticed.', '["eccentrically","<u>typically</u>","consistently","intrinsically"]', '<b>Characteristically</b> = <b>typically</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3fd01741-05b6-49e0-b1e1-27da0bd5ffd0', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation).Ike is <u>head over heels</u> in love with Ngozi. This means that', null, '["Ike is friendly with Ngozi","Ike is trying to fall in love with Ngozi","Ngozi fell on Ike''s heel and both of them fell in love","Ike is madly in love with Ngozi"]', 3, '''Head over heels'' means deeply in love.', true, '2026-10-24 01:04:12.904', '2026-10-24 01:04:12.904', null, null, null, '(Choose the most appropriate interpretation).Ike is <u>head over heels</u> in love with Ngozi. This means that', '["Ike is friendly with Ngozi","Ike is trying to fall in love with Ngozi","Ngozi fell on Ike''s heel and both of them fell in love","<u>Ike is madly in love with Ngozi</u>"]', '''<b>Head over heels</b>'' means <b>deeply in love</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3fe3180b-45a1-4ad5-b50d-9e0e462567d8', 'Biology', 'JAMB', null, 2002, null, 'The most common means of transmitting the Acquired Immune Deficiency Syndrome (AIDS) is', null, '["from mother to child","through blood transfusion","through sexual intercourse","through the sharing of needles"]', 2, 'Sexual intercourse is the most common means of AIDS transmission.', true, '2026-10-12 20:59:30.341', '2026-10-12 20:59:30.341', null, null, null, 'The most common means of transmitting the Acquired Immune Deficiency Syndrome (AIDS) is', '["from mother to child","through blood transfusion","through sexual intercourse","through the sharing of needles"]', 'Sexual intercourse is the most common means of AIDS transmission.', '{"bold":["Sexual intercourse"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3fe9496e-dec0-447a-b9ef-9936b41213e7', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. She <u>encapsulated</u> her view of the nature of life in a poem.', null, '["summed up","explained","expatiated on","reflected"]', 2, 'Encapsulated = summarized; opposite = expatiated on.', true, '2026-10-24 07:21:28.309', '2026-10-24 07:21:28.309', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. She <u>encapsulated</u> her view of the nature of life in a poem.', '["summed up","explained","expatiated on","reflected"]', 'Encapsulated = summarized; opposite = expatiated on.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3ff71858-49a6-4a31-916d-f75f1f2d7af6', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'God guided Abraham’s steward in choosing a wife for Isaac by...', null, '["teaching him how to select a good woman","leading a lady to fulfill his prayer request","taking him to Abraham’s fatherland","giving him an exemplary woman"]', 1, 'Genesis 24:12-20 shows Abraham''s servant asking God for a specific sign (offering water to him and his camels), which Rebekah fulfilled immediately.', true, '2026-09-09 17:18:26.346', '2026-09-09 17:18:26.346', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('3ffb68e9-8f19-422c-a01b-d9e8147e76ce', 'Biology', 'JAMB', null, 2003, null, 'The rods in the retina of the eye are examples of', null, '["cells","tissues","organs","systems"]', 0, 'Rods are specialized photoreceptor cells located in the retina of the eye.', true, '2026-10-12 20:05:10.163', '2026-10-12 20:05:10.163', null, null, null, 'The rods in the retina of the eye are examples of', '["cells","tissues","organs","systems"]', 'Rods are specialized photoreceptor cells located in the retina of the eye.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('400021b1-8920-489a-9ef4-fe9481c13d51', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'What was Samson’s major achievement as Israel’s leader?', null, '["He suppressed the Philistines","He captured the city of Jericho","He saved the Israelites from the Amorites","He secured permanent independence for Israel"]', 0, 'Samson served as a judge for 20 years and began the deliverance of Israel by suppressing and destroying key Philistine military leaders and property (Judges 13:5, 16:30).', true, '2026-09-09 17:18:26.019', '2026-09-09 17:18:26.019', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4001178a-b832-4400-9dbf-8e3e630ef2aa', 'Literature in English', 'JAMB', null, 2026, null, '"Haman is an out-at-the elbow looking man" is referred to as', null, '["Metonymy","Idiomatic expression","Personification","Irony"]', 1, '"Haman is an out-at-the elbow looking man" is referred to as an idiomatic expression. ''Out-at-the elbow'' is an idiom meaning shabby or poorly dressed, suggesting poverty or neglect. Idioms are expressions whose meanings cannot be understood from the individual words. Metonymy substitutes one thing for another, personification gives human qualities to objects, and irony is a contradiction between appearance and reality.', true, '2026-09-10 10:47:09.965', '2026-09-10 10:47:09.965', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('400d76e6-9821-4434-9618-93b1e0a0eb6d', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Tom''s <u>aberrant</u> behaviour attracted attention.', null, '["rascally","selfish","heady","abnormal"]', 3, 'Aberrant = abnormal.', true, '2026-10-24 01:01:45.685', '2026-10-24 01:01:45.685', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Tom''s <u>aberrant</u> behaviour attracted attention.', '["rascally","selfish","heady","<u>abnormal</u>"]', '<b>Aberrant</b> = <b>abnormal</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4011e925-e24d-49a7-a24b-6458332f5179', 'General Mathematics', 'JAMB', null, 2026, null, 'A task can be completed by 12 workers in 20 days. If 4 workers leave after 5 days, how many more days will it take for the remaining workers to complete the task?', null, '["24 days","21 days","22.5 days","20.5 days"]', 2, 'Total work = 12×20 = 240 man-days. Work done in 5 days = 12×5 = 60. Remaining = 180. Workers left = 8. Days = 180/8 = 22.5 days.', true, '2026-09-12 11:43:49.596', '2026-09-12 11:43:49.596', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4015b001-a69d-4d0b-a4e3-3e068961cc3a', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The greenhouse effect is beginning to <u>abate</u> in Europe.', null, '["intensify","extenuate","surface","ameliorate"]', 0, 'Abate = lessen; opposite = intensify.', true, '2026-10-24 07:21:18.211', '2026-10-24 07:21:18.211', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The greenhouse effect is beginning to <u>abate</u> in Europe.', '["intensify","extenuate","surface","ameliorate"]', 'Abate = lessen; opposite = intensify.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('401887cf-809d-4e14-a83e-dbab12f5d165', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Olu <u>might</u> visit London next summer.', null, '["could","will","should","can"]', 0, 'Might = could.', true, '2026-10-24 01:01:47.061', '2026-10-24 01:01:47.061', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Olu <u>might</u> visit London next summer.', '["<u>could</u>","will","should","can"]', '<b>Might</b> = <b>could</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4026c9a6-0b02-4390-b23d-88806ab09f20', 'Biology', 'JAMB', null, 2012, null, 'An animal body that can be cut along its axis in any plane to give two identical parts is said to be', null, '["radially symmetrical","bilaterally symmetrical","asymmetrical","symmetrical"]', 0, 'Radially symmetrical animals can be cut in any plane to give identical parts.', true, '2026-10-12 20:59:44.337', '2026-10-12 20:59:44.337', null, null, null, 'An animal body that can be cut along its axis in any plane to give two identical parts is said to be', '["radially symmetrical","bilaterally symmetrical","asymmetrical","symmetrical"]', 'Radially symmetrical animals can be cut in any plane to give identical parts.', '{"bold":["Radially symmetrical"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4034e4f1-5a1b-47ec-b4eb-89c168acef44', 'English Language', 'JAMB', null, 2007, null, 'There are many ways to kill a rat, so we should be <u>__________</u> in our approach to the task ahead of us.', null, '["eclectic","ecclectic","ecletic","eclectic"]', 0, 'Correct spelling: eclectic (options A and D duplicated in source).', true, '2026-10-24 07:21:36.821', '2026-10-24 07:21:36.821', null, null, null, 'There are many ways to kill a rat, so we should be <u>__________</u> in our approach to the task ahead of us.', '["eclectic","ecclectic","ecletic","eclectic"]', 'Correct spelling: eclectic (options A and D duplicated in source).', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('40398de7-146e-47b1-8507-34fbf2df0b65', 'Physics', 'JAMB', null, 1999, null, 'A car of mass 800 kg attains a speed of 25 m s⁻¹ in 20 seconds. The power developed in the engine is', null, '["1.25 x 10⁴ W","2.50 x 10⁴ W","1.25 x 10⁶ W","2.50 x 10⁶ W"]', 0, 'Kinetic energy gained = ½ x 800 x 25² = 250 000 J. Power = 250 000/20 = 1.25 x 10⁴ W.', true, '2026-10-12 19:15:46.965', '2026-10-12 19:15:46.965', null, null, null, 'A car of mass 800 kg attains a speed of 25 m s<sup>-1</sup> in 20 seconds. The power developed in the engine is', '["1.25 x 10<sup>4</sup> W","2.50 x 10<sup>4</sup> W","1.25 x 10<sup>6</sup> W","2.50 x 10<sup>6</sup> W"]', 'Kinetic energy gained = ½ x 800 x 25<sup>2</sup> = 250 000 J. Power = 250 000/20 = 1.25 x 10<sup>4</sup> W.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4039947b-10c6-483a-8ae7-9536a1575f4f', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Usama likes toys made with <u>bright and animated</u> colours.', null, '["dull","sparkling","black","deep"]', 1, 'Animated = sparkling.', true, '2026-10-24 01:01:59.402', '2026-10-24 01:01:59.402', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Usama likes toys made with <u>bright and animated</u> colours.', '["dull","<u>sparkling</u>","black","deep"]', '<b>Animated</b> = <b>sparkling</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('40405a59-bc07-4423-ad6b-e889d1777de3', 'Biology', 'JAMB', null, 2002, null, 'If XN is the dominant allele for normal vision and Xn the recessive allele for colour-blindness, a boy with the genotype YXn will', null, '["Have normal vision","Be colour-blind","Be totally blind","Be a carrier of colour-blindness"]', 1, 'A boy with genotype YXn is colour-blind.', true, '2026-10-12 20:59:31.781', '2026-10-12 20:59:31.781', null, null, null, 'If XN is the dominant allele for normal vision and Xn the recessive allele for colour-blindness, a boy with the genotype YXn will', '["Have normal vision","Be colour-blind","Be totally blind","Be a carrier of colour-blindness"]', 'A boy with genotype YXn is colour-blind.', '{"bold":["colour-blind"],"italic":[],"underline":[],"fillBlanks":[]}');
