insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('406f3dad-410f-4bb2-b85a-bf48135f22f9', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Nigeria has been playing a <u>vital</u> role in the political and economic development of Africa.', null, '["respectable","creditable","laudable","crucial"]', 3, 'Vital = crucial.', true, '2026-10-24 01:01:53.851', '2026-10-24 01:01:53.851', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Nigeria has been playing a <u>vital</u> role in the political and economic development of Africa.', '["respectable","creditable","laudable","<u>crucial</u>"]', '<b>Vital</b> = <b>crucial</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4073f501-8813-4961-82d4-27be406f968f', 'Biology', 'JAMB', null, 2026, null, 'What is the function of contractile vacuole in Paramecium?', null, '["Produces Enzymes","Gets rid of excreta","Stores and digest food","Gets rid of excess water"]', 3, 'The contractile vacuole in Paramecium functions to get rid of excess water (osmoregulation). Paramecium lives in freshwater environments where the surrounding water is hypotonic (lower solute concentration) compared to its cytoplasm. Water continuously enters the cell by osmosis. The contractile vacuole collects this excess water and expels it from the cell through a pore. This prevents the cell from swelling and bursting. Food digestion occurs in food vacuoles. Enzyme production and excretion are not the main functions of the contractile vacuole.', true, '2026-09-09 03:18:56.581', '2026-09-09 03:18:56.581', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4077c7ae-5fd8-43a7-8e12-b94f249c7233', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. <u>Accountability</u> is certainly a desirable quality in a politician.', null, '["responsibility","respectability","diligence","courage"]', 0, 'Accountability = responsibility.', true, '2026-10-24 01:01:54.115', '2026-10-24 01:01:54.115', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. <u>Accountability</u> is certainly a desirable quality in a politician.', '["<u>responsibility</u>","respectability","diligence","courage"]', '<b>Accountability</b> = <b>responsibility</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('407c15db-1e75-4f8f-92bb-2f9e664c7585', 'Financial Accounting', 'UTME', null, 2001, null, 'The correct entry to reflect the receipt of cash sent by a branch to head office is', null, '["debit cash and credit branch current account","debit branch current account and debit cash","credit branch debtors and debit cash","credit branch current account and debit branch debtors"]', 0, 'The correct entry is debit cash and credit branch current account.', true, '2026-10-12 22:00:07.76', '2026-10-12 22:00:07.76', null, null, null, 'The correct entry to reflect the receipt of cash sent by a branch to head office is', '["<b>debit cash and credit branch current account</b>","debit branch current account and debit cash","credit branch debtors and debit cash","credit branch current account and debit branch debtors"]', 'The correct entry is <b>debit cash and credit branch current account</b>.', '{"bold":["debit cash and credit branch current account"],"italic":[],"underline":[],"fillBlanks":[]}');
