insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('409d824d-4d12-444f-99f6-6e86ce2a2530', 'Physics', 'JAMB', null, 1997, null, 'Which of the following with respect to a body performing simple harmonic motion are in phase?', null, '["Displacement and velocity of the body.","Displacement and force on the body","Velocity and acceleration of the body.","Force acting on the body and the acceleration."]', 3, 'By Newton''s second law F = ma, so the force and the acceleration are always in the same direction and in phase.', true, '2026-10-12 19:15:42.814', '2026-10-12 19:15:42.814', null, null, null, 'Which of the following with respect to a body performing simple harmonic motion are in phase?', '["Displacement and velocity of the body.","Displacement and force on the body","Velocity and acceleration of the body.","Force acting on the body and the acceleration."]', 'By Newton''s second law F = ma, so the force and the acceleration are always in the same direction and in phase.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
