insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('40fee2b6-81af-4dfe-a900-64464d291fb5', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'In 1 Thessalonians, Paul advises believers awaiting the coming of the Lord to put on the...', null, '["Armour of hope","Helmet of righteousness","Breastplate of faith and love","Breastplate of salvation"]', 2, '1 Thessalonians 5:8 states: ''putting on the breastplate of faith and love, and as a helmet the hope of salvation.''', true, '2026-09-09 17:18:28.42', '2026-09-09 17:18:28.42', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('40ff58d0-5129-4efc-b45f-05cb7529d098', 'Physics', 'JAMB', null, 2026, null, 'Which of the following act as energy for the sun?', null, '["nuclear fusion","nuclear fission","chain reaction","transmutation"]', 0, 'Nuclear fusion acts as the energy source for the sun. In the sun, hydrogen nuclei fuse to form helium, releasing enormous amounts of energy. This is different from nuclear fission, which splits heavy nuclei.', true, '2026-09-10 10:56:40.977', '2026-09-10 10:56:40.977', null, null, null, null, null, null, null);
