insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('41135b24-183d-4a87-bead-006a611ee5c3', 'Physics', 'JAMB', null, 1990, null, 'A boy looks at the image of an object in a plane mirror. He observes two images, a main bright one and the other faint. The observed images result from', null, '["Reflection only","Refraction only","Diffraction and interference","Reflection and refraction."]', 3, 'A faint image forms by reflection at the front glass surface and the bright one by refraction through the glass and reflection at the silvered back.', true, '2026-10-12 19:15:31.304', '2026-10-12 19:15:31.304', null, null, null, 'A boy looks at the image of an object in a plane mirror. He observes two images, a main bright one and the other faint. The observed images result from', '["Reflection only","Refraction only","Diffraction and interference","Reflection and refraction."]', 'A faint image forms by reflection at the front glass surface and the bright one by refraction through the glass and reflection at the silvered back.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('41223e4d-2295-4c7a-8024-50611348b407', 'Biology', 'JAMB', null, 2026, null, 'The major site of photosynthesis in the leaf is the', null, '["palisade mesophyll","mesophyll parenchyma","upper epidermis","lower epidermis"]', 0, 'The palisade mesophyll contains the highest concentration of chloroplasts and is the primary site of photosynthesis.', true, '2026-09-09 02:56:39.303', '2026-09-09 02:56:39.303', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('41289eb6-372f-4bca-83a7-4c3e6cfb307d', 'Physics', 'JAMB', null, 2026, null, 'Find the energy conversion found in a speaker', null, '["sound to electrical","electrical to sound","chemical to mechanical","sound to mechanical"]', 1, 'A speaker converts electrical energy to sound energy. Electrical signals are converted into mechanical vibrations of the speaker cone, which produce sound waves in the air.', true, '2026-09-10 10:56:43.847', '2026-09-10 10:56:43.847', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4131b635-9762-4eef-8dd5-1fc596a62714', 'Financial Accounting', 'UTME', null, 2002, null, 'What is department Q''s share of discount allowed?', 'https://res.cloudinary.com/kwi1uv0g/image/upload/v1791840964/questions/r9eemujiy0yjkestpca2.jpg', '["N2000","N1500","N800","N1200"]', 2, 'Total Sales 10,000, Total Discount Allowed 2,000. Q''s Portion = 4/10 x 2,000 = 800.', true, '2026-10-12 21:59:58.006', '2026-10-12 21:59:58.006', null, null, null, 'What is department Q''s share of discount allowed?', '["N2000","N1500","<b>N800</b>","N1200"]', 'Total Sales 10,000, Total Discount Allowed 2,000. Q''s Portion = 4/10 x 2,000 = <b>800</b>.', '{"bold":["800"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4136e6df-48fb-4a33-aaf2-15916cd9b3eb', 'Physics', 'JAMB', null, 1997, null, 'An object of mass 100 g projected vertically upwards from the ground level has a velocity of 20 m s⁻¹ at a height of 10 m. Calculate its initial kinetic energy at the ground level. [g = 10 m s⁻²; neglect air resistance]', null, '["10 J","20 J","30 J","50 J"]', 2, 'At 10 m: KE = ½ x 0.1 x 20² = 20 J and PE = 0.1 x 10 x 10 = 10 J. By energy conservation the initial KE = 20 + 10 = 30 J.', true, '2026-10-12 19:15:42.981', '2026-10-12 19:15:42.981', null, null, null, 'An object of mass 100 g projected vertically upwards from the ground level has a velocity of 20 m s<sup>-1</sup> at a height of 10 m. Calculate its initial kinetic energy at the ground level. [g = 10 m s<sup>-2</sup>; neglect air resistance]', '["10 J","20 J","30 J","50 J"]', 'At 10 m: KE = ½ x 0.1 x 20<sup>2</sup> = 20 J and PE = 0.1 x 10 x 10 = 10 J. By energy conservation the initial KE = 20 + 10 = 30 J.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('414641c8-5052-4ac1-befd-2a06a5bb3187', 'Chemistry', 'JAMB', null, 2026, null, 'The enzyme used in the hydrolysis of starch into dextrin and maltose is?', null, '["Zymase","Sucrase","Amylase","Lactase"]', 2, 'Amylase hydrolyzes starch into dextrin and maltose.', true, '2026-09-12 11:36:26.138', '2026-09-12 11:36:26.138', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('414d0d0c-089f-45ce-addc-1e16057a8e98', 'Physics', 'JAMB', null, 1994, null, 'A pipe of length 45 cm is closed at one end. Calculate the fundamental frequency of the sound wave generated in the pipe if the velocity of sound in air is 360 m s⁻¹. (Neglect end corrections).', null, '["55.0 Hz","148.5 Hz","200.0 Hz","550.0 Hz"]', 2, 'f = v/(4L) = 360/(4 x 0.45) = 200 Hz.', true, '2026-10-12 19:15:39.804', '2026-10-12 19:15:39.804', null, null, null, 'A pipe of length 45 cm is closed at one end. Calculate the fundamental frequency of the sound wave generated in the pipe if the velocity of sound in air is 360 m s<sup>-1</sup>. (Neglect end corrections).', '["55.0 Hz","148.5 Hz","200.0 Hz","550.0 Hz"]', 'f = v/(4L) = 360/(4 x 0.45) = 200 Hz.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('414f5220-508a-4ed6-b75a-2c12b87e15ec', 'Economics', 'JAMB', null, 2026, null, 'A type of Demand in which a good satisfies multiple purposes is called', null, '["Complementary","Composite","Substitutes","Derived"]', 1, 'Composite demand is when a good is demanded for multiple purposes.', true, '2026-09-12 11:01:07.766', '2026-09-12 11:01:07.766', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('41503c40-e21e-4e8c-8f03-9b2d9bb996dd', 'Economics', 'JAMB', null, 2026, null, '______ refers to the type of agriculture which is concerned with production of food, animals and cash crops in large quantities mainly for sale', null, '["Mechanised farming","shift rotation","plantation farming","mixed farming"]', 2, 'Plantation farming involves large-scale production of food, animals, and cash crops mainly for sale.', true, '2026-09-12 11:00:32.72', '2026-09-12 11:00:32.72', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('416fb65e-af7a-4626-9c6f-f956ea090b95', 'English Language', 'JAMB', null, 2024, null, '(Choose the Antonym) After the surgical operation, the doctor gave the indication that Mr. Idogo will pull through', null, '["Be maimed","Survive","Die","Be revived"]', 2, '"Pull through" means to survive or recover; the antonym is "die."', true, '2026-09-18 09:34:03.823', '2026-09-18 09:34:03.823', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4172de4e-8585-4a0a-b623-161dd79e27a4', 'Christian Religious Studies', 'JAMB', null, 2026, null, '“I will turn aside and see this great sight…” In the statement above, the great sight referred to was...', null, '["the burning bush that was not burnt","thick smoke on Mount Sinai","mountain that was shaking","thunder and lightning on Mount Sinai"]', 0, 'Exodus 3:3 records Moses observing the bush that burned with fire yet was not consumed.', true, '2026-09-09 17:18:26.073', '2026-09-09 17:18:26.073', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('41736304-2597-4e0d-bb15-348f2be32f2a', 'Physics', 'JAMB', null, 2003, null, 'In a fission process, the decrease in mass is 0.01%. How much energy could be obtained from the fission of 1.0 g of the material? [c = 3.0 x 10⁸ m s⁻¹]', null, '["9.0 x 10¹⁰ J","6.3 x 10¹¹ J","9.0 x 10¹¹ J","9.0 x 10⁹ J"]', 3, 'Mass lost = 0.01% of 1.0 g = 10⁻⁴ x 10⁻³ kg = 10⁻⁷ kg. E = mc² = 10⁻⁷ x 9 x 10¹⁶ = 9.0 x 10⁹ J.', true, '2026-10-12 19:15:57.683', '2026-10-12 19:15:57.683', null, null, null, 'In a fission process, the decrease in mass is 0.01%. How much energy could be obtained from the fission of 1.0 g of the material? [c = 3.0 x 10<sup>8</sup> m s<sup>-1</sup>]', '["9.0 x 10<sup>10</sup> J","6.3 x 10<sup>11</sup> J","9.0 x 10<sup>11</sup> J","9.0 x 10<sup>9</sup> J"]', 'Mass lost = 0.01% of 1.0 g = 10<sup>-4</sup> x 10<sup>-3</sup> kg = 10<sup>-7</sup> kg. E = mc<sup>2</sup> = 10<sup>-7</sup> x 9 x 10<sup>16</sup> = 9.0 x 10<sup>9</sup> J.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4173fc5a-2e9c-441d-afed-42e24a0fd548', 'Biology', 'JAMB', null, 2026, null, 'If a woman who is a carrier of sickle cell trait married a man who is sickler and they had four children. How many of them would be normal?', null, '["3","2","1","none"]', 3, 'None of the children would be normal (AA). A woman who is a carrier (AS) married to a man who is a sickler (SS) would have offspring with genotypes AS (50%) and SS (50%). None would have the genotype AA. The children would either be carriers (AS) or have sickle cell disease (SS). None would be normal (AA) because the man contributes the S allele to all children, and the woman contributes A or S, but the child cannot get A from both parents.', true, '2026-09-09 03:19:17.029', '2026-09-09 03:19:17.029', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('41766119-4b06-45ea-baea-6f4b4a657907', 'Literature in English', 'JAMB', null, 2026, null, 'A deliberate imitation of a literary style with the intention to ridicule is', null, '["paradox","prosody","parody","pun"]', 2, 'Parody is deliberate imitation to ridicule.', true, '2026-09-12 11:10:36.87', '2026-09-12 11:10:36.87', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4183d81c-3d45-4b65-b0d1-53b4dbde7f4e', 'Financial Accounting', 'UTME', null, 2004, null, 'The quick ratio is', 'https://res.cloudinary.com/kwi1uv0g/image/upload/v1791841944/questions/d1dzrpsledl89lhjxans.jpg', '["1:2","1.3:1","1.7.1","3:1"]', 1, 'Quick Ratio = Current Assets minus Stock to Current Liabilities = (30,000 - 10,000)/15,000 = 20,000/15,000 = 4/3 = 1.3:1.', true, '2026-10-12 22:00:03.87', '2026-10-12 22:00:03.87', null, null, null, 'The quick ratio is', '["1:2","<b>1.3:1</b>","1.7.1","3:1"]', 'Quick Ratio = Current Assets minus Stock to Current Liabilities = (30,000 - 10,000)/15,000 = 20,000/15,000 = 4/3 = <b>1.3:1</b>.', '{"bold":["1.3:1"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4192691d-2645-4c27-9476-6b9d39921435', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Which epistle contains the famous analogy of the Church as the ''body of Christ'' and the members as individual parts?', null, '["1 Corinthians","Romans","Galatians","Colossians"]', 0, '1 Corinthians 12 contains the body of Christ analogy.', true, '2026-09-12 10:41:45.368', '2026-09-12 10:41:45.368', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4197a929-0aa4-4118-b096-e5fa7e70348d', 'Biology', 'JAMB', null, 2003, null, 'In the experiment, the layer of oil serves to prevent water loss by', null, '["transpiration","evaporation","osmosis","guttation"]', 1, 'The oil layer prevents water loss by evaporation.', true, '2026-10-12 20:59:32.725', '2026-10-12 20:59:32.725', null, null, null, 'In the experiment, the layer of oil serves to prevent water loss by', '["transpiration","evaporation","osmosis","guttation"]', 'The oil layer prevents water loss by evaporation.', '{"bold":["evaporation"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('41a237ed-1453-46a3-aadd-c863366bfe51', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Our government is making <u>determined</u> efforts to eradicate illiteracy.', null, '["compulsory","ineffective","innocent","unreliable"]', 1, 'Determined = resolute; opposite = ineffective.', true, '2026-10-24 07:21:12.197', '2026-10-24 07:21:12.197', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Our government is making <u>determined</u> efforts to eradicate illiteracy.', '["compulsory","ineffective","innocent","unreliable"]', 'Determined = resolute; opposite = ineffective.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('41a61082-2378-4781-9ae1-b0f6a5cacebf', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. If you are really keen on immediate results, you just have to adopt this <u>pragmatic</u> approach.', null, '["practical","unrealistic","opportunistic","sensible"]', 1, 'Pragmatic = practical; opposite = unrealistic.', true, '2026-10-24 07:21:17.599', '2026-10-24 07:21:17.599', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. If you are really keen on immediate results, you just have to adopt this <u>pragmatic</u> approach.', '["practical","unrealistic","opportunistic","sensible"]', 'Pragmatic = practical; opposite = unrealistic.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('41ae6090-0fb0-42a4-99f7-e0014e0df092', 'Physics', 'JAMB', null, 1987, null, 'When two parallel wires carry currents in opposite directions, the force on either wire is', null, '["Away from the other wire","Zero, because the currents cancel each other","Twice as much as when the currents are in the same direction","Towards the other wire."]', 0, 'Parallel wires carrying currents in the same direction attract, and wires with opposite currents repel.', true, '2026-10-12 19:15:26.461', '2026-10-12 19:15:26.461', null, null, null, 'When two parallel wires carry currents in opposite directions, the force on either wire is', '["Away from the other wire","Zero, because the currents cancel each other","Twice as much as when the currents are in the same direction","Towards the other wire."]', 'Parallel wires carrying currents in the same direction attract, and wires with opposite currents repel.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('41b3e844-657a-4648-a508-f42ef2f3a1ad', 'Hausa', 'JAMB', null, 2010, null, 'Babban amsa-amon waŝar ''Mu Sha Falala'' ta Sarkin Zazzau Aliyu ''Dansidi a WaKoŝin Hausa, shi ne', null, '["-ba","-ca","-ma","-la"]', 3, 'Babban amsa-amon waŝar shi ne -la.', true, '2026-10-13 10:37:25.427', '2026-10-13 10:37:25.427', null, null, null, 'Babban amsa-amon waŝar ''Mu Sha Falala'' ta Sarkin Zazzau Aliyu ''Dansidi a WaKoŝin Hausa, shi ne', '["-ba","-ca","-ma","-la"]', 'Babban amsa-amon waŝar shi ne -la.', '{"bold":["-la"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('41b5b3c4-8cc6-4e1e-bc47-f7cb80d7e4f8', 'Literature in English', 'JAMB', null, 2026, null, 'The tone of Still I Rise is best described as', null, '["Melancholic and reflective","Defiant and triumphant","Satirical and humorous","Passive and indifferent"]', 1, 'The tone is defiant and triumphant.', true, '2026-09-12 11:09:54.477', '2026-09-12 11:09:54.477', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('41bf89d9-7ed9-44d6-85ff-e16b1fbf73ad', 'Literature in English', 'JAMB', null, 2026, null, 'The writing convention in which the events in a narrative are scrambled as they come to the writer''s mind without any attempt to arrange them in orderly sequence is called', null, '["Shifting style","Narrator''s mind style","Psycho-consciousness style","Stream of consciousness"]', 3, 'It is stream of consciousness.', true, '2026-09-12 11:13:54.272', '2026-09-12 11:13:54.272', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('41c12998-acc0-4581-b59a-c27c6100b49a', 'Physics', 'JAMB', null, 1987, null, 'Which of the following instruments has a pure tone?', null, '["Guitar","Vibrating string","Tuning fork","Siren."]', 2, 'A tuning fork vibrates almost entirely at one frequency, so it produces a pure tone with no significant overtones.', true, '2026-10-12 19:15:25.761', '2026-10-12 19:15:25.761', null, null, null, 'Which of the following instruments has a pure tone?', '["Guitar","Vibrating string","Tuning fork","Siren."]', 'A tuning fork vibrates almost entirely at one frequency, so it produces a pure tone with no significant overtones.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('41d73281-708c-4150-9a09-a7959c0f8bca', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'According to Peter, when the chief Shepherd would be manifested, the elders would obtain the', null, '["house of glory","crown with stars","unfading crown of glory","sceptre of authority"]', 2, 'Elders will receive the unfading crown of glory (1 Peter 5:4).', true, '2026-09-12 10:41:56.343', '2026-09-12 10:41:56.343', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('41dfaa17-2f29-49e9-878d-2be4dfcd94be', 'Financial Accounting', 'UTME', null, 2002, null, 'Given: N Sales 195,200 Stock 1st January 34,000 Purchases 126,000 Sales returns 1,200 Purchases 2,000. If the gross profit is N66,000, what is the value of stock at 31st December?', 'https://res.cloudinary.com/kwi1uv0g/image/upload/v1791841163/questions/opfja7p68vwdqt6ije5o.jpg', '["N30,000","N40,000","N50,000","N20,000"]', 0, 'Cost of goods available for sales: Opening stock 34000 + Purchases less returns 124000 = 158,000. Less cost of goods sold: Sales less returns 194000 - 66000 = 128000. Closing Stock = 30,000.', true, '2026-10-12 21:59:58.893', '2026-10-12 21:59:58.893', null, null, null, 'Given: N Sales 195,200 Stock 1st January 34,000 Purchases 126,000 Sales returns 1,200 Purchases 2,000. If the gross profit is N66,000, what is the value of stock at 31st December?', '["<b>N30,000</b>","N40,000","N50,000","N20,000"]', 'Cost of goods available for sales: Opening stock 34000 + Purchases less returns 124000 = 158,000. Less cost of goods sold: Sales less returns 194000 - 66000 = 128000. Closing Stock = <b>30,000</b>.', '{"bold":["30,000"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('41e1a15e-665a-43b6-8be4-b828bd5f59e9', 'Government', 'JAMB', null, 2026, null, 'Nigeria''s membership of the UN complements her foreign policy in the area of', null, '["bilateral diplomacy","regional diplomacy","sub-regional diplomacy","multilateral diplomacy"]', 3, 'Nigeria''s UN membership complements her multilateral diplomacy.', true, '2026-09-12 11:24:48.426', '2026-09-12 11:24:48.426', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('41f0d260-a3d1-466b-9cc3-fc328120ccc6', 'Literature in English', 'JAMB', null, 2026, null, '''Anansewa- a! where is that typewriter I bought for you at a price that nearly drove me to sell myself?'' This statement depicts', null, '["the abundant state of Ananse''s wealth","the struggle behind living up to standard","the hand-to-mouth feeding status of Ananse''s family","the nonchalant nature of Anansewa"]', 1, 'It depicts the struggle behind living up to standard.', true, '2026-09-12 11:05:29.098', '2026-09-12 11:05:29.098', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('41f49345-6ab3-4ac4-86c4-413a8b8f60b3', 'English Language', 'JAMB', null, 2007, null, 'We hold that the nation, both in its public and private sectors <u>------------</u> the best consultancy service and advice in all its endeavours.', null, '["deserve","is deserving","deserves","are deserving","richly deserve"]', 2, 'Singular subject ''the nation'' takes ''deserves''.', true, '2026-10-24 01:04:25.483', '2026-10-24 01:04:25.483', null, null, null, 'We hold that the nation, both in its public and private sectors <u>------------</u> the best consultancy service and advice in all its endeavours.', '["deserve","is deserving","<u>deserves</u>","are deserving","richly deserve"]', 'Singular subject ''<b>the nation</b>'' takes ''<b>deserves</b>''.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('41f49f01-0c23-490f-a768-3e3244ab29de', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Much to her <u>chagrin</u>, the bridegroom did not turn up for the wedding.', null, '["wonder","surprise","disappointment","depression"]', 2, 'Chagrin = disappointment.', true, '2026-10-24 01:01:47.752', '2026-10-24 01:01:47.752', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Much to her <u>chagrin</u>, the bridegroom did not turn up for the wedding.', '["wonder","surprise","<u>disappointment</u>","depression"]', '<b>Chagrin</b> = <b>disappointment</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('42073748-db21-478b-ab2d-a7399e4cbeb0', 'General Mathematics', 'JAMB', null, 2026, null, 'Make u the subject of the formula 1/f = 1/u + 1/v', null, '["(v+f)/fv","(v-f)/fv","fv/(v+f)","fv/(v-f)"]', 3, '1/u = 1/f - 1/v = (v-f)/fv. u = fv/(v-f).', true, '2026-09-12 11:44:05.334', '2026-09-12 11:44:05.334', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('420d1e1a-9c55-4bc2-b96b-19a55a326f60', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Updating the Board''s brochure is an <u>arduous</u> task.', null, '["a regular","an annual","a difficult","an easy"]', 3, 'Arduous = difficult; opposite = easy.', true, '2026-10-24 07:21:22.759', '2026-10-24 07:21:22.759', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Updating the Board''s brochure is an <u>arduous</u> task.', '["a regular","an annual","a difficult","an easy"]', 'Arduous = difficult; opposite = easy.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('420f2c94-b646-45df-81c5-ce964c8ef330', 'English Language', 'JAMB', null, 2007, null, 'A wide range options <u>------------</u> made available to students in their final year last year.', null, '["were","are","was","is"]', 2, 'Singular ''range'' past â†’ was.', true, '2026-10-24 01:02:15.659', '2026-10-24 01:02:15.659', null, null, null, 'A wide range options <u>------------</u> made available to students in their final year last year.', '["were","are","<u>was</u>","is"]', 'Singular ''<b>range</b>'' past â†’ <b>was</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('42105f3a-c79f-4357-bf6f-130355f45819', 'Physics', 'JAMB', null, 2000, null, 'A boy observes a piece of stone at the bottom of a river 6.0 m deep. If he looks from the surface of the river, what is the apparent distance of the stone from him?', null, '["4.5 m","5.0 m","5.5 m","8.0 m"]', 0, 'Apparent depth = real depth/n = 6.0/1.33 ≈ 4.5 m.', true, '2026-10-12 19:15:49.588', '2026-10-12 19:15:49.588', null, null, null, 'A boy observes a piece of stone at the bottom of a river 6.0 m deep. If he looks from the surface of the river, what is the apparent distance of the stone from him?', '["4.5 m","5.0 m","5.5 m","8.0 m"]', 'Apparent depth = real depth/n = 6.0/1.33 ≈ 4.5 m.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('42179b83-2a6a-4f1f-ac55-64061508d198', 'Physics', 'JAMB', null, 2026, null, 'A cannon is fired from town X. After how long is the sound heard at a town Y 4.95km away? (velocity of sound in air = 330ms⁻¹)', null, '["30s","10s","12s","15s"]', 3, 'Time = distance/speed = 4950/330 = 15s.', true, '2026-09-10 10:56:42.276', '2026-09-10 10:56:42.276', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('421b86e4-4c6d-476f-a490-f84752634f81', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Teachers of music believe in its <u>therapeutic</u> effect.', null, '["lyrical","healing","sound","rhythmic"]', 1, 'Therapeutic = healing.', true, '2026-10-24 01:04:03.92', '2026-10-24 01:04:03.92', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Teachers of music believe in its <u>therapeutic</u> effect.', '["lyrical","<u>healing</u>","sound","rhythmic"]', '<b>Therapeutic</b> = <b>healing</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('42205a88-ce98-468c-ba37-b93f86de3cc8', 'Literature in English', 'JAMB', null, 2026, null, 'The word ''Drama'' originated from where and the untranslated word of ''Drama'' is', null, '["Greek, ''dran'' meaning to do or act","Latin, ''drama'' meaning play","French, ''drame'' meaning story","English, ''drama'' meaning performance"]', 0, 'The word ''Drama'' originated from Greek, and the untranslated word is ''dran'' meaning ''to do'' or ''to act.'' Drama comes from the Greek word ''dran'' which means to act or to do. This reflects the essential nature of drama as something performed or acted out. The Greek origin emphasizes action and performance.', true, '2026-09-10 10:47:53.677', '2026-09-10 10:47:53.677', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('424c546d-bd19-44c2-bf6b-0572cc6db07d', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation).The young man thought he was <u>at the top of the tree</u>.', null, '["at the highest point of his career","confused","at a point of prominence","arrogant"]', 0, '''At the top of the tree'' = highest point of career.', true, '2026-10-24 01:04:20.719', '2026-10-24 01:04:20.719', null, null, null, '(Choose the most appropriate interpretation).The young man thought he was <u>at the top of the tree</u>.', '["<u>at the highest point of his career</u>","confused","at a point of prominence","arrogant"]', '''<b>At the top of the tree</b>'' = <b>highest point of career</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('425263c9-0c6d-495c-bcb1-3ea4ce4a4842', 'Biology', 'JAMB', null, 2026, null, 'The hormone in mammalian females that induces ovulation is', null, '["testosterone","oestrogen","progesterone","luteinizing hormone"]', 3, 'Luteinizing hormone (LH) is the hormone that induces ovulation in mammalian females. A surge in LH triggers the release of a mature egg from the Graafian follicle. Oestrogen is involved in follicle development and the preparation of the uterine lining. Progesterone maintains the uterine lining and pregnancy. Testosterone is the primary male sex hormone. The LH surge is essential for ovulation, and its timing is critical for reproductive function. This hormone is produced by the anterior pituitary gland and regulated by GnRH from the hypothalamus.', true, '2026-09-09 03:18:46.587', '2026-09-09 03:18:46.587', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4253b69e-97e2-4d8b-af8d-2c3ab2eeb529', 'Biology', 'JAMB', null, 2026, null, 'Which of the following is not a characteristic of monocot plants?', null, '["occurrence of secondary thickening","parallel venation","scattered vascular bundles","floral parts arranged in threes","perianth is usually insignificant"]', 0, 'Secondary thickening does not typically occur in monocot plants. Monocots generally lack a vascular cambium and do not undergo secondary growth (increasing stem width). Parallel venation, scattered vascular bundles, floral parts arranged in threes, and insignificant perianth are all characteristics of monocots. The absence of secondary thickening is a key difference between monocots and dicots, as dicots typically have cambium for secondary growth. Some monocots (like palms) may have secondary thickening through a different mechanism but this is the exception, not the rule.', true, '2026-09-09 03:19:07.281', '2026-09-09 03:19:07.281', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('425a0204-968b-44ce-b866-c901c9af0580', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). The police are looking for the woman who <u>farmed her children out to</u> her neighbours', null, '["The woman and her children are in the habit of working in neighbours'' farms and the police are not well disposed to this","The police may arrest the woman for allowing her neighbours to take care of her children","The woman may be arrested for allowing her children to be a nuisance to her neighbours","The police wanted the woman for allowing her children to destroy her neighboursâ€™ crops"]', 1, '''Farmed out'' = sent away to be cared for.', true, '2026-10-24 01:02:11.003', '2026-10-24 01:02:11.003', null, null, null, '(Choose the most appropriate interpretation). The police are looking for the woman who <u>farmed her children out to</u> her neighbours', '["The woman and her children are in the habit of working in neighbours'' farms and the police are not well disposed to this","<u>The police may arrest the woman for allowing her neighbours to take care of her children</u>","The woman may be arrested for allowing her children to be a nuisance to her neighbours","The police wanted the woman for allowing her children to destroy her neighboursâ€™ crops"]', '''<b>Farmed out</b>'' = <b>sent away to be cared for</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('425afdbb-1170-48f7-9d84-5af63566bf86', 'English Language', 'JAMB', null, 2024, null, 'The primary setting of "The Lekki Headmaster" is?', null, '["Abuja","Lagos","Kano","Port Harcourt"]', 1, 'The novel is primarily set in Lagos.', true, '2026-09-18 09:34:04.038', '2026-09-18 09:34:04.038', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('425dca0e-8d7e-4c6d-a5e5-fd5a56047c78', 'Literature in English', 'JAMB', null, 2026, null, 'The speaker''s tone throughout the poem can best be described as', null, '["submissive","bitter","defiant","indifferent"]', 2, 'The speaker''s tone is defiant.', true, '2026-09-12 11:07:21.661', '2026-09-12 11:07:21.661', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('425ea075-0a40-4ef8-9c08-862986102a66', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation).Ator <u>led a dog''s life</u> for the twenty years he stayed in the United Kingdom.', null, '["lived a dirty life","was promiscuous","was domesticated","led an unhappy and troubled life"]', 3, '''A dog''s life'' = unhappy and troubled life.', true, '2026-10-24 01:02:06.591', '2026-10-24 01:02:06.591', null, null, null, '(Choose the most appropriate interpretation).Ator <u>led a dog''s life</u> for the twenty years he stayed in the United Kingdom.', '["lived a dirty life","was promiscuous","was domesticated","<u>led an unhappy and troubled life</u>"]', '''A <b>dog''s life</b>'' = <b>unhappy and troubled life</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('42679d38-1ce4-44a4-aed1-5ea04717b2a3', 'Financial Accounting', 'UTME', null, 2003, null, 'Provision for discount allowed can be recorded as a debit to', null, '["the profit and loss account and a credit to provision for discount allowed","provision for discount allowed and a credit to the profit and loss account","discount allowed and a credit to the profit and loss account","expenses and a credit to customers'' account"]', 2, 'Provision for discount allowed is an attempt to charge against profit losses which are certain to be incurred but the amount cannot be accurately calculated. The entries will debit profit and loss account and credit provision for discount allowed account.', true, '2026-10-12 21:59:59.977', '2026-10-12 21:59:59.977', null, null, null, 'Provision for discount allowed can be recorded as a debit to', '["the profit and loss account and a credit to provision for discount allowed","provision for discount allowed and a credit to the profit and loss account","<b>discount allowed and a credit to the profit and loss account</b>","expenses and a credit to customers'' account"]', 'Provision for discount allowed is an attempt to charge against profit losses which are certain to be incurred but the amount cannot be accurately calculated. The entries will debit profit and loss account and credit <b>discount allowed</b>.', '{"bold":["discount allowed"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('426bddc2-2e39-4f18-b448-50012902d113', 'General Mathematics', 'JAMB', null, 2026, null, 'Find the sum of the first 21 terms in the progression -10, -8, -6, ...', null, '["180","190","200","210"]', 3, 'This is an arithmetic progression with first term a=-10, common difference d=2. Sum of n terms = n/2[2a+(n-1)d]. For n=21: Sum = 21/2[2(-10)+20(2)] = 21/2[-20+40] = 21/2[20] = 210.', true, '2026-09-10 10:48:19.884', '2026-09-10 10:48:19.884', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('426e48e3-139f-4799-87d6-4f0c724029d4', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Thompson was a prosecution witness at the court <u>hearing</u>.', null, '["false","reliable","government","trial"]', 3, 'Hearing = trial.', true, '2026-10-24 01:03:54.511', '2026-10-24 01:03:54.511', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Thompson was a prosecution witness at the court <u>hearing</u>.', '["false","reliable","government","<u>trial</u>"]', '<b>Hearing</b> = <b>trial</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('427087ba-c64b-4c67-8772-be0062b5a11f', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The athlete is proud to be in the <u>vanguard</u> of sports development.', null, '["unforgettable position","leading position","destructive position","emerging position"]', 1, 'Vanguard = leading position.', true, '2026-10-24 01:01:58.292', '2026-10-24 01:01:58.292', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The athlete is proud to be in the <u>vanguard</u> of sports development.', '["unforgettable position","<u>leading position</u>","destructive position","emerging position"]', '<b>Vanguard</b> = <b>leading position</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('42720f73-94d1-4d88-b92c-8981c6e7a906', 'General Mathematics', 'JAMB', null, 2026, null, 'The sum of the progression 1 + x + x² + x³ + ... =', null, '["1/(1-x)","1/(1+x)","1/(x-1)","1/x","None of these"]', 0, 'S∞ = 1/(1-x) for |x| < 1.', true, '2026-09-12 11:44:20.407', '2026-09-12 11:44:20.407', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('427b8d4e-d171-40ed-9b51-f641a11143a8', 'Biology', 'JAMB', null, 2026, null, 'When blood only passes through the heart once every time it makes one complete circuit through the body. This type of circulation is called', null, '["Open circulation","closed circulation","single circulation","double circulation"]', 2, 'Single circulation is found in fish where blood passes through the heart only once during each complete circuit of the body. The heart pumps deoxygenated blood to the gills for oxygenation, then the oxygenated blood travels to the rest of the body before returning to the heart. Double circulation (found in mammals and birds) involves two circuits: pulmonary (heart → lungs → heart) and systemic (heart → body → heart). Open circulation (found in arthropods and mollusks) has blood pumped into open spaces (hemocoel). Closed circulation has blood contained within vessels.', true, '2026-09-09 03:18:29.711', '2026-09-09 03:18:29.711', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4280242d-34fa-4f79-be33-c47b8aa35541', 'Literature in English', 'JAMB', null, 2026, null, 'Characters whose roles are predictable due to presentation over time are called', null, '["Archaeological characters","Archetypical characters","Over-time characters","Didactic characters"]', 1, 'Archetypical characters have predictable roles.', true, '2026-09-12 11:05:39.903', '2026-09-12 11:05:39.903', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4280f1df-f3b6-4a73-b9b6-0355acaedb0f', 'English Language', 'JAMB', null, 2007, null, 'A number of applicants <u>______</u> invited for the interview.', null, '["was","has been","have been","is"]', 2, '''A number of'' plural â†’ have been.', true, '2026-10-24 01:02:16.111', '2026-10-24 01:02:16.111', null, null, null, 'A number of applicants <u>______</u> invited for the interview.', '["was","has been","<u>have been</u>","is"]', '''<b>A number of</b>'' plural â†’ <b>have been</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('42991af0-a460-4681-82ec-7a7e39ff4436', 'Government', 'JAMB', null, 2026, null, 'Constitution originated from a belief that there is need for', null, '["limited government","freedom of worship","full employment","judicial independence"]', 0, 'Constitution originated from the belief in limited government.', true, '2026-09-12 11:24:56.84', '2026-09-12 11:24:56.84', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('42a8ad38-12c9-4c1f-923f-7dc6f067f754', 'English Language', 'JAMB', null, 2024, null, 'No sooner had the examination ended ______ the students started vacating the halls of residence', null, '["When","That","Than","Before"]', 2, '"No sooner... than" is the correct correlative conjunction.', true, '2026-09-18 09:24:04.724', '2026-09-18 09:24:04.724', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('42a982c9-acbd-48e3-9047-71a92328b67c', 'Biology', 'JAMB', null, 2002, null, 'The presence of endoskeleton is characteristic of', null, '["invertebrata","vertebrata","insecta","coelenterata"]', 1, 'Vertebrates possess an endoskeleton.', true, '2026-10-12 20:59:31.217', '2026-10-12 20:59:31.217', null, null, null, 'The presence of endoskeleton is characteristic of', '["invertebrata","vertebrata","insecta","coelenterata"]', 'Vertebrates possess an endoskeleton.', '{"bold":["Vertebrates"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('42abf194-3daf-4950-b27a-39cab6e8040f', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Your reaction <u>underscores</u> the point I was making.', null, '["reveals","proves wrong","emphasizes","justifies"]', 2, 'Underscores = emphasizes.', true, '2026-10-24 01:01:45.525', '2026-10-24 01:01:45.525', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Your reaction <u>underscores</u> the point I was making.', '["reveals","proves wrong","<u>emphasizes</u>","justifies"]', '<b>Underscores</b> = <b>emphasizes</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('42b5343f-c1d6-44e4-b435-ed4aaf9f1d68', 'Chemistry', 'JAMB', null, 2026, null, 'Addition of sodium chloride to water to form a solution would lead to', null, '["decrease in freezing point and increase the boiling point","increase in freezing point and increase the boiling point","decrease in freezing point and decrease boiling point","increase in freezing point and decrease the boiling point"]', 0, 'Dissolving a non-volatile solute like sodium chloride in water lowers its freezing point (freezing point depression) and raises its boiling point (boiling point elevation).', true, '2026-09-09 17:12:44.524', '2026-09-09 17:12:44.524', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('42b7a137-792d-4f3a-9bf4-c397037bce9c', 'Physics', 'JAMB', null, 1983, null, 'Which of the following statements about liquid pressure is NOT correct? The pressure', null, '["At a point in a liquid is proportional to the depth.","At any point in a liquid is the same at the same level.","Is exerted equally in all directions at any point.","Of a liquid at any point on the wall of its container acts in a direction perpendicular to the wall.","At a particular depth depends on the shape of the vessel."]', 4, 'Liquid pressure is P = ρgh. It depends on depth, density and g, not on the shape of the vessel, so statement E is incorrect.', true, '2026-10-12 19:15:16.439', '2026-10-12 19:15:16.439', null, null, null, 'Which of the following statements about liquid pressure is <b>NOT</b> correct? The pressure', '["At a point in a liquid is proportional to the depth.","At any point in a liquid is the same at the same level.","Is exerted equally in all directions at any point.","Of a liquid at any point on the wall of its container acts in a direction perpendicular to the wall.","At a particular depth depends on the shape of the vessel."]', 'Liquid pressure is P = ρgh. It depends on depth, density and g, not on the shape of the vessel, so statement E is incorrect.', '{"bold":["NOT"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('42bafaa0-06c9-4bdc-9bf1-fb0da0d5ae55', 'General Mathematics', 'JAMB', null, 2026, null, 'A regular polygon of n sides is such that each interior angle is 120° greater than the exterior angle. Find the value of n', null, '["90°","12°","45°","30°","60°"]', 1, 'Interior = 120 + exterior. Interior + exterior = 180. 120 + 2E = 180. E = 30. n = 360/30 = 12.', true, '2026-09-12 11:43:45.337', '2026-09-12 11:43:45.337', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('42c057b7-4725-4460-9eea-209d5a2cbc11', 'General Mathematics', 'JAMB', null, 2026, null, 'If the height of two circular cylinders are in the ratio 2:3 and their base radii are in the ratio 9:8. What is the ratio of their volume', null, '["27:32","32:27","23:72","14:26"]', 1, 'V ∝ r²h. Ratio = (9²×2):(8²×3) = 162:192 = 27:32. The answer is (A) 27:32.', true, '2026-09-12 11:44:21.985', '2026-09-12 11:44:21.985', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('42c28526-2f90-4dfe-8167-39b4c9bb3f09', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Paul told the Athenians that they were very religious because...', null, '["some of their poets said that men are the offspring of God","they dedicated an altar to an unknown god","their epicurean and stoic philosophers always discussed religious issues","the city was full of idols and symbols of religious altars"]', 1, 'In Acts 17:22-23 at the Areopagus, Paul mentions seeing an altar with the inscription ''TO THE UNKNOWN GOD'' as evidence of their religious devotion.', true, '2026-09-09 17:18:25.471', '2026-09-09 17:18:25.471', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('42ce9195-5821-427b-8a6f-4f2690154257', 'Literature in English', 'JAMB', null, 2026, null, 'In The Marriage of Anansewa, the dramatic technique of Anansegoro is best described as', null, '["A tragic form characterised by the downfall of a noble hero","A traditional storytelling mode blending narration, music, and audience participation","A realist technique focusing strictly on dialogue and stage action","A symbolic method relying solely on abstract characters"]', 1, 'Anansegoro is a traditional storytelling mode blending narration, music, and audience participation.', true, '2026-09-12 11:09:49.915', '2026-09-12 11:09:49.915', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4302a764-9a0e-4691-aaee-f191ed46e16c', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The lawyer gave <u>evasive</u> answers to all the questions.', null, '["unintelligent","ineffective","unreliable","equivocal"]', 3, 'Evasive = equivocal.', true, '2026-10-24 01:01:48.546', '2026-10-24 01:01:48.546', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The lawyer gave <u>evasive</u> answers to all the questions.', '["unintelligent","ineffective","unreliable","<u>equivocal</u>"]', '<b>Evasive</b> = <b>equivocal</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('430a4c19-5c2c-4257-a6c9-6dfa1e0b31c4', 'Physics', 'JAMB', null, 1984, null, 'Dew point is the temperature at which water vapour in the atmosphere', null, '["Turns into steam","Solidifies into ice pellets","First condenses into liquid form","Is just sufficient to cause cooling","Has a relative humidity of fifty percent."]', 2, 'Dew point is the temperature at which the air becomes saturated and water vapour begins to condense to liquid.', true, '2026-10-12 19:15:19.128', '2026-10-12 19:15:19.128', null, null, null, 'Dew point is the temperature at which water vapour in the atmosphere', '["Turns into steam","Solidifies into ice pellets","First condenses into liquid form","Is just sufficient to cause cooling","Has a relative humidity of fifty percent."]', 'Dew point is the temperature at which the air becomes saturated and water vapour begins to condense to liquid.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('430ff771-9f9f-4215-918e-d07d3e70121e', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The injured man is determined to <u>get back at</u> his assailant.', null, '["visit","forgive","identify","attack"]', 1, 'Get back at = retaliate; opposite = forgive.', true, '2026-10-24 07:21:25.029', '2026-10-24 07:21:25.029', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The injured man is determined to <u>get back at</u> his assailant.', '["visit","forgive","identify","attack"]', 'Get back at = retaliate; opposite = forgive.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('43101b76-538c-46e8-9ff2-3e19f198e906', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Ada gave her husband a look that made words <u>superfluous</u>.', null, '["spurious","unnecessary","scanty","redundant"]', 3, 'Superfluous = unnecessary; closest opposite = redundant (necessary implied).', true, '2026-10-24 07:21:26.74', '2026-10-24 07:21:26.74', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Ada gave her husband a look that made words <u>superfluous</u>.', '["spurious","unnecessary","scanty","redundant"]', 'Superfluous = unnecessary; closest opposite = redundant (necessary implied).', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('43137a43-8e55-444d-8244-84632bea70bc', 'Literature in English', 'JAMB', null, 2026, null, 'The dominant tone of the poem is', null, '["nostalgic and reflective","angry and violent","humorous and playful","satirical and mocking"]', 0, 'The dominant tone is nostalgic and reflective.', true, '2026-09-12 11:12:14.795', '2026-09-12 11:12:14.795', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('43252151-dab4-42cc-ac41-d2d851ea5a8b', 'Economics', 'JAMB', null, 2026, null, 'Theory of absolute advantage was postulated by', null, '["Alfred Marshall","Adam Smith","David Richard","Samuelson"]', 1, 'Adam Smith postulated the theory of absolute advantage.', true, '2026-09-12 11:00:34.881', '2026-09-12 11:00:34.881', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4328946e-2bab-49bf-be72-76c829baf2d1', 'Biology', 'JAMB', null, 2012, null, 'Which Question Paper Type of Biology as indicated above is given to you?', null, '["Type Green","Type Purple","Type Red","Type Yellow"]', 3, 'The question paper type is Type Yellow.', true, '2026-10-12 20:59:44.033', '2026-10-12 20:59:44.033', null, null, null, 'Which Question Paper Type of Biology as indicated above is given to you?', '["Type Green","Type Purple","Type Red","Type Yellow"]', 'The question paper type is Type Yellow.', '{"bold":["Type Yellow"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('433a1adf-232d-433a-a875-1b06fa614a52', 'General Mathematics', 'JAMB', null, 2026, null, 'The cost of a car is partly constant and partly varies with the time it takes to do work. It cost 3500 for 5.5 hours and 2900 for 4 hours. Find the cost of a 7.5 hours work', null, '["12900/3","1300","880/7","27000"]', 1, 'C = a + bt. 3500 = a + 5.5b. 2900 = a + 4b. 600 = 1.5b. b = 400. a = 2900 - 1600 = 1300. C = 1300 + 400(7.5) = 1300 + 3000 = 4300. Not in options.', true, '2026-09-12 11:43:43.109', '2026-09-12 11:43:43.109', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4357cc96-a123-43f3-be4d-eacd3b38adda', 'Physics', 'JAMB', null, 1986, null, 'The angle between the magnetic meridian and the geographic meridian at a locality on the earth is the', null, '["Longitude of the locality.","Angle of inclination at the locality","Latitude of the locality","Angle of declination of the locality."]', 3, 'This angle is the magnetic declination (variation). Inclination (dip) is the angle between the earth''s field and the horizontal.', true, '2026-10-12 19:15:24.379', '2026-10-12 19:15:24.379', null, null, null, 'The angle between the magnetic meridian and the geographic meridian at a locality on the earth is the', '["Longitude of the locality.","Angle of inclination at the locality","Latitude of the locality","Angle of declination of the locality."]', 'This angle is the magnetic declination (variation). Inclination (dip) is the angle between the earth''s field and the horizontal.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('43686849-6af6-4682-8734-a62cd24a1063', 'English Language', 'JAMB', null, 2024, null, '11', null, '["exorbitant","irrational","expensive","extortion"]', 0, 'Management refuses if they think the demand is exorbitant (unreasonably high).', true, '2026-09-18 10:17:48.796', '2026-09-18 10:17:48.796', '274e150d-fca1-4c72-9c33-e5e119534874', 11, 'CLOZE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('436a1a3a-2f89-4095-841d-40321106a69d', 'Biology', 'JAMB', null, 2026, null, 'Which of the following waste products in plant is excreted through the stomata and lenticels?', null, '["carbon dioxide","alkaloids","tannins","anthocyanins"]', 0, 'Carbon dioxide is excreted by plants through stomata and lenticels. CO₂ is produced in cellular respiration and diffuses out through these openings. Alkaloids, tannins, and anthocyanins are secondary metabolites that are often stored in vacuoles, deposited in cell walls, or excreted into the soil, not primarily through stomata and lenticels. Plants excrete various waste products through different mechanisms, but gaseous waste like CO₂ and water vapor are released through stomata and lenticels.', true, '2026-09-09 03:19:08.142', '2026-09-09 03:19:08.142', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('43789a8f-4e14-4bee-b6c6-b4cab56065a6', 'Physics', 'JAMB', null, 1998, null, 'In a resonance tube experiment, if the fundamental frequency of the vibrating air column is 280 Hz, the frequency of the third overtone is', null, '["70 Hz","840 Hz","1 120 Hz","1 960 Hz"]', 3, 'A closed tube has only odd harmonics: f, 3f, 5f, 7f. The third overtone is 7f = 7 x 280 = 1 960 Hz.', true, '2026-10-12 19:15:45.945', '2026-10-12 19:15:45.945', null, null, null, 'In a resonance tube experiment, if the fundamental frequency of the vibrating air column is 280 Hz, the frequency of the third overtone is', '["70 Hz","840 Hz","1 120 Hz","1 960 Hz"]', 'A closed tube has only odd harmonics: f, 3f, 5f, 7f. The third overtone is 7f = 7 x 280 = 1 960 Hz.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4396f1a2-cc76-4e99-bb5b-2662a3cb3228', 'English Language', 'JAMB', null, 2007, null, 'It is mandatory that each applicant <u>_______</u> two passport photographs along with the form.', null, '["submits","submitted","submit","is submitting"]', 2, '''Mandatory that'' â†’ subjunctive submit.', true, '2026-10-24 01:02:12.688', '2026-10-24 01:02:12.688', null, null, null, 'It is mandatory that each applicant <u>_______</u> two passport photographs along with the form.', '["submits","submitted","<u>submit</u>","is submitting"]', '''<b>Mandatory that</b>'' â†’ subjunctive <b>submit</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('439919d6-3a62-434e-9a5c-86177b4375a6', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). My boss asked me <u>to take my eyes off the ball</u>', null, '["should stop paying attention to what is most important","I should be focused when I am about to stay off football","I should stay off football after sustaining an injury","I should be focused when playing football"]', 0, '''Take eyes off the ball'' = stop paying attention to what matters.', true, '2026-10-24 01:04:25.071', '2026-10-24 01:04:25.071', null, null, null, '(Choose the most appropriate interpretation). My boss asked me <u>to take my eyes off the ball</u>', '["<u>should stop paying attention to what is most important</u>","I should be focused when I am about to stay off football","I should stay off football after sustaining an injury","I should be focused when playing football"]', '''<b>Take eyes off the ball</b>'' = <b>stop paying attention to what matters</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('439df3f6-a963-4be8-8b80-3d237d1effa1', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The result of the election would have been different if some people had not been <u>disfranchised</u>.', null, '["disfavoured","banned from contesting","allowed to rig","prevented from voting"]', 3, 'Disfranchised = prevented from voting.', true, '2026-10-24 01:01:47.008', '2026-10-24 01:01:47.008', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The result of the election would have been different if some people had not been <u>disfranchised</u>.', '["disfavoured","banned from contesting","allowed to rig","<u>prevented from voting</u>"]', '<b>Disfranchised</b> = <b>prevented from voting</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('43b02b62-0c81-4441-a8aa-fc8c53f21dff', 'Physics', 'JAMB', null, 1993, null, '200 g of water at 90 °C is mixed with 100 g of water at 30 °C. What is the final temperature?', null, '["50 °C","60 °C","70 °C","80 °C"]', 2, 'Heat lost = heat gained: 200(90 - θ) = 100(θ - 30), so 18000 - 200θ = 100θ - 3000 and θ = 70 °C.', true, '2026-10-12 19:15:37.596', '2026-10-12 19:15:37.596', null, null, null, '200 g of water at 90 °C is mixed with 100 g of water at 30 °C. What is the final temperature?', '["50 °C","60 °C","70 °C","80 °C"]', 'Heat lost = heat gained: 200(90 - θ) = 100(θ - 30), so 18000 - 200θ = 100θ - 3000 and θ = 70 °C.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('43b3bde0-2173-431d-ad18-fb56d9def3e0', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The patient <u>disregarded</u> the advice of the doctor.', null, '["ignored","disobeyed","questioned","respected"]', 0, 'Disregarded = ignored.', true, '2026-10-24 01:01:46.689', '2026-10-24 01:01:46.689', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The patient <u>disregarded</u> the advice of the doctor.', '["<u>ignored</u>","disobeyed","questioned","respected"]', '<b>Disregarded</b> = <b>ignored</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('43c4ac1b-44b5-4acb-ad06-1f0f816fa43d', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The lecturers were advised to carry out a <u>cursory survey</u> of Nigerian languages.', null, '["detailed study","careful teaching","careful description","partial consideration"]', 0, 'Cursory = hasty; opposite = detailed study.', true, '2026-10-24 07:21:20.3', '2026-10-24 07:21:20.3', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The lecturers were advised to carry out a <u>cursory survey</u> of Nigerian languages.', '["detailed study","careful teaching","careful description","partial consideration"]', 'Cursory = hasty; opposite = detailed study.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('43c91a24-59f1-4ff2-8b6e-a7d523b47abd', 'Literature in English', 'JAMB', null, 2026, null, 'The poem "Not My Business" by Niyi Osundare is primarily a critique of', null, '["economic hardship in Nigeria","the future of failed democratic institutions","political apathy and selfish indifference","inter-ethnic conflicts"]', 2, '"Not My Business" by Niyi Osundare is primarily a critique of political apathy and selfish indifference. The poem criticizes those who remain silent in the face of oppression and injustice because they are not directly affected. The speaker''s attitude of ''not my business'' eventually leads to his own suffering. The poem warns that indifference to the suffering of others is dangerous because oppression will eventually reach everyone.', true, '2026-09-10 10:45:34.776', '2026-09-10 10:45:34.776', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('43de922c-39ad-40d1-8e5e-e8703a3c0b96', 'English Language', 'JAMB', null, 2007, null, 'Neither Agbo nor his parents <u>------------</u> the meetings now.', null, '["has attended","attend","attends","attended"]', 1, 'Nearest subject ''parents'' (plural) â†’ attend.', true, '2026-10-24 01:02:11.793', '2026-10-24 01:02:11.793', null, null, null, 'Neither Agbo nor his parents <u>------------</u> the meetings now.', '["has attended","<u>attend</u>","attends","attended"]', 'Nearest subject ''<b>parents</b>'' (plural) â†’ <b>attend</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('43e2743b-a6ca-46ef-af37-9f16ee3e4758', 'Literature in English', 'JAMB', null, 2026, null, 'The title ''New Tongue'' in the poem mainly refers to', null, '["learning a foreign language","the loss and replacement of one''s native language","a speech defect","the language of animals"]', 1, 'The title refers to the loss and replacement of one''s native language.', true, '2026-09-12 11:12:20.769', '2026-09-12 11:12:20.769', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('43e59cce-ee5a-4d0a-ae81-5f2306352887', 'Physics', 'JAMB', null, 1992, null, 'A boy sits in a train moving with uniform speed on a straight track. If from his outstretched palm he gently tosses a coin vertically upwards, the coin will fall', null, '["In front of his palm","Behind his palm","Beside his palm","Into his palm"]', 3, 'The coin keeps the train''s horizontal velocity while it rises and falls, so it stays level with his hand and lands back in his palm.', true, '2026-10-12 19:15:34.856', '2026-10-12 19:15:34.856', null, null, null, 'A boy sits in a train moving with uniform speed on a straight track. If from his outstretched palm he gently tosses a coin vertically upwards, the coin will fall', '["In front of his palm","Behind his palm","Beside his palm","Into his palm"]', 'The coin keeps the train''s horizontal velocity while it rises and falls, so it stays level with his hand and lands back in his palm.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('43ea5023-e2e6-42ac-92ae-6af5435d5085', 'Financial Accounting', 'UTME', null, 2004, null, 'The items that are contained in the bought ledger control account are', null, '["discount allowed, bad debts and purchases","dishonored cheques, returns inwards and sales","returns outwards, bad debts and purchases","discount received, returns outwards and purchases"]', 3, 'Items contained in the bought ledger control account: Discount received from creditor for goods bought, Goods returned to supplier (Return outwards), Purchases.', true, '2026-10-12 22:00:02.591', '2026-10-12 22:00:02.591', null, null, null, 'The items that are contained in the bought ledger control account are', '["discount allowed, bad debts and purchases","dishonored cheques, returns inwards and sales","returns outwards, bad debts and purchases","<b>discount received, returns outwards and purchases</b>"]', 'Items contained in the bought ledger control account: <b>Discount received, Returns outwards and Purchases</b>.', '{"bold":["Discount received, Returns outwards and Purchases"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('44049b05-8d51-4a88-898b-1690b0807ef7', 'Biology', 'JAMB', null, 2026, null, 'Mango can be propagated by', null, '["stem cutting","Marcotting","Stem grafting","Budding"]', 1, 'Mango is commonly propagated by marcotting (air layering). This technique involves inducing roots on a branch while it is still attached to the parent plant, then cutting it off and planting it as a new plant. Marcotting is preferred because mango seeds often produce plants that are not true to type (genetically different from the parent). Stem cuttings root poorly in mango. Grafting and budding are also used but marcotting is more reliable. Marcotting preserves the exact genetic characteristics of the parent plant.', true, '2026-09-09 03:18:33.757', '2026-09-09 03:18:33.757', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('44065c8b-6ae1-4e5c-aa63-62fba933f9f5', 'Biology', 'JAMB', null, 2026, null, 'Mastic movement is', null, '["Response to light stimulus","Non-directional","Response to internal stimulus"]', 1, 'Mastic (nastic) movements are non-directional responses to stimuli. Unlike tropisms (which are directional, growing toward or away from a stimulus), nastic movements occur in a direction determined by the plant''s structure rather than the stimulus direction. Examples include the closing of Mimosa pudica leaves when touched (thigmonasty), the opening and closing of flowers in response to temperature (thermonasty) or light (photonasty). The movement is independent of the stimulus direction and is often reversible.', true, '2026-09-09 03:18:21.892', '2026-09-09 03:18:21.892', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('441604a1-cc2a-4aa1-9e54-34995750b968', 'Government', 'JAMB', null, 2026, null, 'The final court of appeal in Nigeria during the colonial era was the', null, '["Privy Council","High Court","Supreme Court","Appeal Court"]', 0, 'The final court of appeal in Nigeria during the colonial era was the Privy Council. The Judicial Committee of the Privy Council in London was the highest court of appeal for Nigeria and other British colonies. Appeals from Nigerian courts could go to the Privy Council. This arrangement ended in 1963 when Nigeria became a republic and established its own Supreme Court as the final court of appeal.', true, '2026-09-10 10:44:19.146', '2026-09-10 10:44:19.146', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('44171c4a-a8aa-41f3-8ce5-102292bfc874', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The class as a whole will have a <u>lecture</u> on scarce commodities tomorrow.', null, '["argument","deliberation","dispute","conference","talk"]', 4, 'Lecture = talk.', true, '2026-10-24 01:03:53.543', '2026-10-24 01:03:53.543', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The class as a whole will have a <u>lecture</u> on scarce commodities tomorrow.', '["argument","deliberation","dispute","conference","<u>talk</u>"]', '<b>Lecture</b> = <b>talk</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('44182bae-2172-4732-8753-315f4ec6253b', 'Biology', 'JAMB', null, 2026, null, 'Which of the following is used to test for the presence of lime in a soil sample?', null, '["NaOH","H2SO4","HCl","HNO3"]', 2, 'Hydrochloric acid (HCl) is used to test for lime (calcium carbonate, CaCO₃) in soil. When diluted HCl is added to a soil sample containing lime, effervescence (fizzing) occurs due to the release of carbon dioxide gas: CaCO₃ + 2HCl → CaCl₂ + H₂O + CO₂. The bubbles of CO₂ gas indicate the presence of calcium carbonate. While other acids could theoretically react with carbonates, HCl is the standard acid used in this simple field test because it reacts readily and safely with carbonates to produce visible effervescence.', true, '2026-09-09 03:18:20.096', '2026-09-09 03:18:20.096', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4418ae85-d0b0-4ff7-a05e-b8a1ae81349b', 'Physics', 'JAMB', null, 2026, null, 'Which statement best describes a plane-polarized wave?', null, '["A wave where the oscillations are in many planes perpendicular to the direction of propagation","A wave where the oscillations are parallel to the direction of propagation","A wave where the oscillations are confined to a single plane perpendicular to the direction of propagation","A wave that travels in a straight line"]', 2, 'A plane-polarized wave is a wave where the oscillations are confined to a single plane perpendicular to the direction of propagation. This is a characteristic of transverse waves. Polarization restricts the vibrations to one plane.', true, '2026-09-10 10:56:44.009', '2026-09-10 10:56:44.009', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('44225fa4-9b0b-4097-9254-3388dba70563', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'According to Ephesians, children who obey their parents in the Lord will', null, '["be happy","go to heaven","have long life","be great"]', 2, 'According to Ephesians 6:2-3, the commandment to honor your father and mother is the first commandment with a promise, ''that it may be well with you and that you may live long on the earth.''', true, '2026-09-12 09:46:02.408', '2026-09-12 09:46:02.408', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4424f499-7792-40c9-b5ad-e1b50713390e', 'Literature in English', 'JAMB', null, 2026, null, 'The sea in the poem is best described as', null, '["a symbol of maternal care","an enemy of the people","a source of political power","a symbol of war"]', 0, 'The sea symbolizes maternal care.', true, '2026-09-12 11:10:13.422', '2026-09-12 11:10:13.422', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4425782b-eafa-44da-b89d-77cd6e559160', 'Chemistry', 'JAMB', null, 2026, null, 'The mass of an element liberated during electrolysis depend on? i) current passed through the electrolyte ii) time duration iii) magnitude of electric charge', null, '["I and ii only","I, ii, iii only","I, ii, iv","all of the above"]', 1, 'Mass liberated depends on current, time, and charge.', true, '2026-09-12 11:36:17.127', '2026-09-12 11:36:17.127', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('442c068c-f057-4e4b-82d8-1d5a38c339d0', 'Financial Accounting', 'UTME', null, 2001, null, 'Determine the total fixed asset from the opening balance sheet.', 'https://res.cloudinary.com/kwi1uv0g/image/upload/v1791842095/questions/vsynh3cnevvezqo47lby.jpg', '["N2,200","N2,020","N1,720","N1,270"]', 0, 'Total fixed asset = Plant & Mach 1,500 + Fixtures 700 = 2,200.', true, '2026-10-12 22:00:05.694', '2026-10-12 22:00:05.694', null, null, null, 'Determine the total fixed asset from the opening balance sheet.', '["<b>N2,200</b>","N2,020","N1,720","N1,270"]', 'Total fixed asset = Plant & Mach 1,500 + Fixtures 700 = <b>2,200</b>.', '{"bold":["2,200"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('443e418e-6567-4635-aa16-92cd80f73220', 'Biology', 'JAMB', null, 2026, null, 'One advantage of variation in a species population is that individuals', null, '["with favored traits become dominant","easily reach their reproduction age","are easily recognised","are better adapted to changes"]', 3, 'One advantage of variation in a species population is that individuals are better adapted to changes. Variation provides the raw material for natural selection, allowing populations to adapt to changing environmental conditions. When the environment changes, some individuals with beneficial traits will survive and reproduce, passing on their traits. This is the basis of evolution by natural selection.', true, '2026-09-09 03:19:25.651', '2026-09-09 03:19:25.651', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('443fabbd-f483-4aa6-8a19-e69b5c788c09', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Mrs. Kofi is very <u>provocative</u> in her style of dressing.', null, '["modest","happy","angry","beautiful"]', 0, 'Provocative = alluring; opposite = modest.', true, '2026-10-24 07:21:18.411', '2026-10-24 07:21:18.411', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Mrs. Kofi is very <u>provocative</u> in her style of dressing.', '["modest","happy","angry","beautiful"]', 'Provocative = alluring; opposite = modest.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4458d8a5-0784-46ff-a214-85ea204f3bdf', 'Biology', 'JAMB', null, 2002, null, 'The animals that move by means of Flagella include', null, '["Chlamydomonas and Euglena","Planaria and Amoeba","Amoeba and Hydra","Paramecium and Planaria"]', 0, 'Chlamydomonas and Euglena utilize whip-like flagella for locomotion.', true, '2026-10-12 20:05:09.001', '2026-10-12 20:05:09.001', null, null, null, 'The animals that move by means of Flagella include', '["Chlamydomonas and Euglena","Planaria and Amoeba","Amoeba and Hydra","Paramecium and Planaria"]', 'Chlamydomonas and Euglena utilize whip-like flagella for locomotion.', '{}');
