insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('44d04004-a3e1-481a-9e21-ccf3c9c47537', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Her anxiety was <u>apparent</u> to everyone present at the ceremony.', null, '["real","visible","transparent","unknown"]', 1, 'Apparent = visible/obvious.', true, '2026-10-24 01:03:56.559', '2026-10-24 01:03:56.559', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Her anxiety was <u>apparent</u> to everyone present at the ceremony.', '["real","<u>visible</u>","transparent","unknown"]', '<b>Apparent</b> = <b>visible</b>/obvious.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('44d26531-c54d-4705-9ef5-39766c754f94', 'General Mathematics', 'JAMB', null, 2026, null, 'Factorize completely: y³ - 4xy + xy³ - 4y', null, '["y(x+1)(y-2)(y+2)","y(x+1)(y-2)(y-2)","y(x-1)(y-2)(y+2)","y(x+1)(y+2)(y+2)"]', 0, 'Group: y³ - 4y + xy³ - 4xy = y(y²-4) + xy(y²-4) = y(y²-4)(1+x) = y(x+1)(y-2)(y+2).', true, '2026-09-12 11:43:48.923', '2026-09-12 11:43:48.923', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('44d2a529-950b-40b2-b7a2-c5a20d8153e9', 'Chemistry', 'JAMB', null, 2026, null, 'What volume of oxygen at STP is required to completely burn 4.8g of carbon? C + O₂ → CO₂ (1 mole gas occupies 22.4 dm³ at STP)', null, '["2.24 dm³","4.48 dm³","8.96 dm³","11.2 dm³"]', 2, 'Moles of C = 4.8/12 = 0.4 mol. From equation, 1 mol C requires 1 mol O₂. Volume of O₂ = 0.4 × 22.4 = 8.96 dm³.', true, '2026-09-12 11:32:55.823', '2026-09-12 11:32:55.823', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('44d2e956-c034-4deb-b57f-ed97c301ee3e', 'Physics', 'JAMB', null, 1995, null, 'Which of the following is the exclusive property of a transverse wave?', null, '["Diffraction","Refraction","Compression","Polarization"]', 3, 'Polarization occurs only in transverse waves. Diffraction and refraction occur in all waves, and compression occurs in longitudinal waves.', true, '2026-10-12 19:15:41.576', '2026-10-12 19:15:41.576', null, null, null, 'Which of the following is the exclusive property of a transverse wave?', '["Diffraction","Refraction","Compression","Polarization"]', 'Polarization occurs only in transverse waves. Diffraction and refraction occur in all waves, and compression occurs in longitudinal waves.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('44dd986d-d126-4a65-aac2-f7a2130b3b28', 'Biology', 'JAMB', null, 2004, null, 'Plants survive hot dry conditions by', null, '["storing water in large parenchyma cells","producing numerous leaves","having numerous stomata","having evergreen leaves"]', 0, 'Storing water in large parenchyma cells helps plants survive hot dry conditions.', true, '2026-10-12 20:59:36.04', '2026-10-12 20:59:36.04', null, null, null, 'Plants survive hot dry conditions by', '["storing water in large parenchyma cells","producing numerous leaves","having numerous stomata","having evergreen leaves"]', 'Storing water in large parenchyma cells helps plants survive hot dry conditions.', '{"bold":["Storing water in large parenchyma cells"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('44de9841-4f92-419f-ab2c-2c5f60b887ea', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The man has strong <u>distaste</u> for alcohol', null, '["love","aversion","desire","excitement"]', 1, 'Distaste = aversion.', true, '2026-10-24 01:04:11.865', '2026-10-24 01:04:11.865', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The man has strong <u>distaste</u> for alcohol', '["love","<u>aversion</u>","desire","excitement"]', '<b>Distaste</b> = <b>aversion</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('44e376aa-2826-431e-84d7-e6dad173695f', 'English Language', 'JAMB', null, 2024, null, 'Choose the option that has the same sound as the one represented by the letter(s) underlined: tailor', null, '["walk","lamb","calm","talk"]', 1, 'The "l" in "tailor" is silent, same as the "l" in "lamb."', true, '2026-09-18 09:43:02.657', '2026-09-18 09:43:02.657', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('44e6e80e-9e01-42a8-8881-084017d40e81', 'Physics', 'JAMB', null, 1988, null, 'A body whose mass is 2 kg and has a volume of 500 cm³ just floats when completely immersed in a liquid. Calculate the density of the liquid.', null, '["4.0 x 10² kg m⁻³","4.0 x 10³ kg m⁻³","1.0 x 10³ kg m⁻³","1.0 x 10⁶ kg m⁻³"]', 1, 'A body that just floats when fully immersed has the same density as the liquid: 2/(500 x 10⁻⁶) = 4.0 x 10³ kg m⁻³.', true, '2026-10-12 19:15:27.265', '2026-10-12 19:15:27.265', null, null, null, 'A body whose mass is 2 kg and has a volume of 500 cm<sup>3</sup> just floats when completely immersed in a liquid. Calculate the density of the liquid.', '["4.0 x 10<sup>2</sup> kg m<sup>-3</sup>","4.0 x 10<sup>3</sup> kg m<sup>-3</sup>","1.0 x 10<sup>3</sup> kg m<sup>-3</sup>","1.0 x 10<sup>6</sup> kg m<sup>-3</sup>"]', 'A body that just floats when fully immersed has the same density as the liquid: 2/(500 x 10<sup>-6</sup>) = 4.0 x 10<sup>3</sup> kg m<sup>-3</sup>.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('44ea1a0c-febc-454f-bcf5-625e5e5c01e3', 'Chemistry', 'JAMB', null, 2026, null, 'Which metal reacts most vigorously with water?', null, '["Mg","Ca","Na","Cu"]', 2, 'Sodium reacts most vigorously with water among the options.', true, '2026-09-12 11:35:56.931', '2026-09-12 11:35:56.931', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('44f56b70-0639-4c4d-8b4a-4d24ce3831c3', 'Physics', 'JAMB', null, 2003, null, 'A force of 100 N is used to kick a football of mass 0.8 kg. Find the velocity with which the ball moves if it takes 0.8 s to be kicked.', null, '["100 m s⁻¹","32 m s⁻¹","50 m s⁻¹","64 m s⁻¹"]', 0, 'Impulse = change in momentum: Ft = mv, so v = (100 x 0.8)/0.8 = 100 m s⁻¹.', true, '2026-10-12 19:15:55.323', '2026-10-12 19:15:55.323', null, null, null, 'A force of 100 N is used to kick a football of mass 0.8 kg. Find the velocity with which the ball moves if it takes 0.8 s to be kicked.', '["100 m s<sup>-1</sup>","32 m s<sup>-1</sup>","50 m s<sup>-1</sup>","64 m s<sup>-1</sup>"]', 'Impulse = change in momentum: Ft = mv, so v = (100 x 0.8)/0.8 = 100 m s<sup>-1</sup>.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('44f5a63f-b7e5-4deb-abd7-66a394e139b5', 'English Language', 'JAMB', null, 2024, null, 'Why did Bepo find Mrs. Ignatius call at 11:55PM particularly frustrating?', null, '["because he had already warned her about calling late at night","because he was about to pray and didn''t want to be disturbed","because he didn''t like the personal nature of their relationship","because he was busy and could not attend to the call"]', 1, 'Bepo was about to pray and didn''t want to be disturbed.', true, '2026-09-18 09:43:02.779', '2026-09-18 09:43:02.779', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('44ff0f1c-4e36-46e9-af4a-a2ba93a1f16c', 'Economics', 'JAMB', null, 2026, null, 'The following will occur when maximum price is fixed below the free market price EXCEPT', null, '["Hoarding","Presence of black market","Excess supply","Excess demand"]', 2, 'Maximum price below equilibrium causes excess demand, not excess supply.', true, '2026-09-12 11:01:28.435', '2026-09-12 11:01:28.435', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('44ff230e-9140-4d8e-aa2a-02ba2368d462', 'Physics', 'JAMB', null, 2026, null, 'Water waves and light waves differ generally in their', null, '["ability to be diffracted","ability to be reflected","direction of vibration","medium of propagation"]', 3, 'Water waves and light waves differ generally in their medium of propagation. Water waves are mechanical waves that require a material medium (water). Light waves are electromagnetic waves that can travel through a vacuum. Both can be diffracted and reflected.', true, '2026-09-10 10:56:43.955', '2026-09-10 10:56:43.955', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4506671b-1ca2-46b5-a61e-86bef5d48272', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Agbenu was <u>ecstatic</u> about her result.', null, '["dispassionate","sad","pessimistic","mad"]', 1, 'Ecstatic = overjoyed; opposite = sad.', true, '2026-10-24 07:21:24.015', '2026-10-24 07:21:24.015', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Agbenu was <u>ecstatic</u> about her result.', '["dispassionate","sad","pessimistic","mad"]', 'Ecstatic = overjoyed; opposite = sad.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('450918e9-6c27-4b00-b4e5-af9e6b472771', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. He <u>reneged on</u> the agreement between him and his employees.', null, '["kept","failed to keep","failed to approve","failed to sign"]', 1, 'Reneged on = failed to keep.', true, '2026-10-24 01:03:58.941', '2026-10-24 01:03:58.941', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. He <u>reneged on</u> the agreement between him and his employees.', '["kept","<u>failed to keep</u>","failed to approve","failed to sign"]', '<b>Reneged on</b> = <b>failed to keep</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('45092329-cf97-4934-9fa2-ada60e7f6f49', 'Literature in English', 'JAMB', null, 2026, null, '''Stream of Consciousness'' is the name for', null, '["a narrative mode that produces a character''s random thoughts and associations","an Italian rhyme scheme brought into vogue in the sixteenth century","a stage device in which the actor addresses the audience directly","a cultural phenomenon of the eighteenth century"]', 0, '''Stream of Consciousness'' is a narrative mode that produces a character''s random thoughts and associations. This technique attempts to capture the flow of a character''s inner thoughts, feelings, and memories as they occur, often without logical order or punctuation. It was used by writers like James Joyce, Virginia Woolf, and William Faulkner. It is not a rhyme scheme, stage device, or cultural phenomenon.', true, '2026-09-10 10:45:34.506', '2026-09-10 10:45:34.506', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4509c62c-b571-47ca-a276-1ef36ca1ded9', 'Literature in English', 'JAMB', null, 2026, null, 'What is the approximate age of the celebrant in the poem?', null, '["fifty-five","five and eighty","eighty-five","ninety-five"]', 2, 'The celebrant is approximately eighty-five.', true, '2026-09-12 11:07:22.568', '2026-09-12 11:07:22.568', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('450ae610-34bf-4cc3-94f9-4a98fbaf5db6', 'Government', 'JAMB', null, 2026, null, 'All the following are types of elections except', null, '["Recall","General election","Shadow elections","Bye-elections"]', 2, 'Shadow elections are not a type of election.', true, '2026-09-12 11:24:07.501', '2026-09-12 11:24:07.501', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('45157c2a-0ba3-4b87-b7e2-83acb3dbdf83', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. I wish the commander were less <u>adamant about</u> his proposed reprisal attack on the enemy.', null, '["unyielding about/retaliatory","tolerant of/surprise","sentimental about/rehearsed","supportive of/retributive"]', 0, 'Adamant = unyielding; reprisal = retaliatory.', true, '2026-10-24 01:01:51.981', '2026-10-24 01:01:51.981', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. I wish the commander were less <u>adamant about</u> his proposed reprisal attack on the enemy.', '["<u>unyielding about/retaliatory</u>","tolerant of/surprise","sentimental about/rehearsed","supportive of/retributive"]', '<b>Adamant</b> = <b>unyielding</b>; <b>reprisal</b> = <b>retaliatory</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('45195ee0-57ef-4469-86b6-2b05eeb78c09', 'Biology', 'JAMB', null, 2003, null, 'A density-dependent factor that regulates the population size of organisms is', null, '["disease","sudden flood","drought","fire outbreak"]', 0, 'Disease is a density-dependent factor.', true, '2026-10-12 20:59:33.23', '2026-10-12 20:59:33.23', null, null, null, 'A density-dependent factor that regulates the population size of organisms is', '["disease","sudden flood","drought","fire outbreak"]', 'Disease is a density-dependent factor.', '{"bold":["Disease"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('45227fd6-773d-4519-b10a-966d54b3a985', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). One significant characteristics of the jet age is that it encourages people to <u>cut corners</u>.', null, '["not to face all problems","to want to become rich quickly","to want to avoid necessary hardships","not to do the proper thing at the right time"]', 2, '''Cut corners'' = take shortcuts.', true, '2026-10-24 01:02:08.077', '2026-10-24 01:02:08.077', null, null, null, '(Choose the most appropriate interpretation). One significant characteristics of the jet age is that it encourages people to <u>cut corners</u>.', '["not to face all problems","to want to become rich quickly","<u>to want to avoid necessary hardships</u>","not to do the proper thing at the right time"]', '''<b>Cut corners</b>'' = <b>take shortcuts</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('45257f8f-395a-4267-b597-b492d4d5b412', 'Chemistry', 'JAMB', null, 2026, null, 'During electrolysis of acidified water, the gas produced at the cathode is:', null, '["Oxygen","Hydrogen","Chlorine","Nitrogen"]', 1, 'Hydrogen gas is produced at the cathode during electrolysis of acidified water.', true, '2026-09-12 11:32:56.965', '2026-09-12 11:32:56.965', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('45397daa-1a34-42fb-bee4-1ca85e6afcbf', 'Literature in English', 'JAMB', null, 2026, null, 'Which device is used in: ''So fair and foul a day I have not seen''?', null, '["Irony","Oxymoron","Pun","Metonymy"]', 1, 'Oxymoron is used.', true, '2026-09-12 11:11:25.066', '2026-09-12 11:11:25.066', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('45417d27-624b-42e8-bda3-013bce7a7c3c', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. My father is a very <u>prosperous</u> businessman.', null, '["ungrateful","unscrupulous","unskillful","unsuccessful"]', 3, 'Prosperous = successful; opposite = unsuccessful.', true, '2026-10-24 07:21:14.021', '2026-10-24 07:21:14.021', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. My father is a very <u>prosperous</u> businessman.', '["ungrateful","unscrupulous","unskillful","unsuccessful"]', 'Prosperous = successful; opposite = unsuccessful.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('45510e6f-558f-444a-974d-c8e6f40bf187', 'Chemistry', 'JAMB', null, 2026, null, 'When palm wine is left exposed to air for a few days, it goes sour. The bacteria in the air oxidises.________ in palm wine to _________', null, '["ethanol, ethanoic acid","ethanoic acid, ethanol","ester, ethanoic acid","ether, ethanol"]', 0, 'Acetobacter bacteria in air aerobically oxidize the ethanol present in palm wine into ethanoic acid (vinegar), causing a sour taste.', true, '2026-09-09 17:12:47.349', '2026-09-09 17:12:47.349', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('45511a54-9dc7-4f4c-951e-96d206da58d5', 'Biology', 'JAMB', null, 2026, null, 'The function of the loop of Henle is to', null, '["increase the flow of urine","concentrate amino acids in the kidney tissue","concentrate sodium chloride in the medulla of the kidneys","increase the volume of urine"]', 2, 'The function of the loop of Henle is to concentrate sodium chloride (NaCl) in the medulla of the kidneys. This creates an osmotic gradient that allows the collecting duct to concentrate urine by drawing water out through osmosis. This is essential for producing concentrated urine and conserving water. The loop of Henle does not increase urine flow or volume. It does not concentrate amino acids. The creation of the medullary osmotic gradient is one of the kidney''s most important functions for water conservation.', true, '2026-09-09 03:19:08.798', '2026-09-09 03:19:08.798', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('45512cf7-1d53-4c08-a472-c89119d7b1ed', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. He might be compelled to make a <u>momentous</u> decision.', null, '["a voluntary","a spontaneous","an important","an involuntary"]', 2, 'Momentous = important.', true, '2026-10-24 01:01:47.858', '2026-10-24 01:01:47.858', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. He might be compelled to make a <u>momentous</u> decision.', '["a voluntary","a spontaneous","<u>an important</u>","an involuntary"]', '<b>Momentous</b> = <b>an important</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4551de64-a1c9-4720-8ded-edb6970e3706', 'Physics', 'JAMB', null, 2001, null, 'A cell of internal resistance r supplies current to a 6.0 Ω resistor and its efficiency is 75%. Find the value of r.', null, '["4.5 Ω","1.0 Ω","8.0 Ω","2.0 Ω"]', 3, 'Efficiency = R/(R + r) = 0.75, so 6/(6 + r) = 0.75 and r = 2.0 Ω.', true, '2026-10-12 19:15:51.629', '2026-10-12 19:15:51.629', null, null, null, 'A cell of internal resistance r supplies current to a 6.0 Ω resistor and its efficiency is 75%. Find the value of r.', '["4.5 Ω","1.0 Ω","8.0 Ω","2.0 Ω"]', 'Efficiency = R/(R + r) = 0.75, so 6/(6 + r) = 0.75 and r = 2.0 Ω.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4552a889-54c7-460b-a63e-7c7ea7119984', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The last <u>criticism</u> at the rally was made in ignorance.', null, '["unimpeachable","objection","impeccable","uniformed"]', 3, 'Garbled source; closest = uniformed (uninformed).', true, '2026-10-24 01:04:09.284', '2026-10-24 01:04:09.284', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The last <u>criticism</u> at the rally was made in ignorance.', '["unimpeachable","objection","impeccable","<u>uniformed</u>"]', '<b>Garbled source</b>; closest = <b>uniformed</b> (uninformed).', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4553e193-8ded-49f6-89c2-392da8ab2884', 'Physics', 'JAMB', null, 1987, null, 'A pool of water appears to be 1.0 m deep when viewed vertically from above. If the refractive index of water is 1.33, what is the actual depth of the pool?', null, '["0.75 m","1.013 m","1.330 m","13.300 m"]', 2, 'Real depth = apparent depth x n = 1.0 x 1.33 = 1.33 m.', true, '2026-10-12 19:15:26.031', '2026-10-12 19:15:26.031', null, null, null, 'A pool of water appears to be 1.0 m deep when viewed vertically from above. If the refractive index of water is 1.33, what is the actual depth of the pool?', '["0.75 m","1.013 m","1.330 m","13.300 m"]', 'Real depth = apparent depth x n = 1.0 x 1.33 = 1.33 m.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4553e22d-c11c-45b7-b01d-5f9acbf97f41', 'Biology', 'JAMB', null, 2026, null, 'The process that takes place in the dark stage of photosynthesis is', null, '["oxidation of water","photolysis of water","oxidation of carbon (IV) oxide","reduction of carbon (IV) oxide"]', 3, 'In the dark stage (Calvin cycle) of photosynthesis, carbon dioxide (CO₂) is reduced to form glucose. This is the carbon fixation phase where CO₂ is incorporated into organic molecules using ATP and NADPH produced in the light stage. Oxidation of water and photolysis of water occur in the light stage (light-dependent reactions). Carbon dioxide is reduced (gains hydrogen atoms) to form carbohydrates, not oxidized. The dark stage does not directly require light but depends on the products of the light stage (ATP and NADPH).', true, '2026-09-09 03:18:40.881', '2026-09-09 03:18:40.881', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('455e78cc-6fc0-4353-bca0-fcb4c52c72ee', 'Economics', 'JAMB', null, 2026, null, 'Trade between two cities in the same country is an example of', null, '["international trade","internal trade","Investment trade","Domestic trade","b and D"]', 4, 'Trade between two cities in the same country is internal trade (also called domestic trade).', true, '2026-09-12 11:00:33.845', '2026-09-12 11:00:33.845', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('457d8646-8c2d-45c1-9ec2-0ecf7e96e47d', 'Economics', 'JAMB', null, 2026, null, 'One of the factors affecting the supply of manufactured goods is', null, '["weather","technology","consumer tastes","availability of input"]', 1, 'Technology is a major factor affecting the supply of manufactured goods. Improved technology reduces production costs, increases efficiency, and allows firms to produce more output at each price level, shifting the supply curve to the right. Weather primarily affects agricultural supply. Consumer tastes affect demand, not supply. Availability of input affects supply but is not the only factor; technology is a key determinant.', true, '2026-09-10 10:42:00.02', '2026-09-10 10:42:00.02', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4590a737-3b5b-43b1-89cd-15d8dd920351', 'Hausa', 'JAMB', null, 2010, null, '''Ba neman aure ke da wuya ba, shiga-ka-fito''. Ka ga shiga-ka-fito din nan, lallai shiga-ka-fito din ne! Domin aljihu kan jigata kafin a kai ga biki. Tuddan da al''ada ta tanada, wadanda dole sai an haye su, suna da yawa. Yanzu dauki misalin kayan na-gani-ina-so, wato ''yan kayan nan da ake shiryawa a kai gidan su yarinya a karon farko. Ma''anar yin haka, wai iyaye su san cewa manemin auren ''yarsu da gaske yake. To, ina dole ga yin haka? Da can da yake zuwa yana zance da ''yarsu yana yi mata hasafi, ba a san da gaske yake ba? Gangaro kan kayan toshi. Nan ma tsabagen kudi ake kashewa a sayi suturu da kayan shafe-shafe a kai wa yarinya. Kada fa ka ce zuwa zance da manemi yake yana yi wa yarinya kyauta mako-mako, shi ke nan, ya wadatar. Ina, ko kadan! Kada ka mance da kudin gaisuwar iyaye da dukiyar aure kafin a yi baiko da sa ranar biki. Kudi ne madididiki ake tanada a kai wa iyayen yarinya da niyyar dai wannan abu da aka ambata. Duk bayan wannan, ana sa ranar aure, manemin yarinya ya dosa karakaina ke nan daga wannan gida zuwa wancan, ko ma wannan gari zuwa wancan da sunan gayar da iyaye da kakaninnta, wai don su san shi. I, za su san shi mana, tun da ba yana zuwa ne zikau ba! Da zarar biki ya kawo jiki kuma, uwa-uba za a shirya kayan lefe na fitar hankali a kai wa yarinya. Nan ma dukiya ake narkawa. Haķika duk wadannan abubuwa al''ada ce kawai ta kaķaba wa al''umma. Ai ta fuskar dukiya, muhimmin abu ga aure, sadaki. Amma abin takaici, yanzu an yi masa mahalli a can ķarshen sahu! Shiga-ka-fito wajen neman aure ta fi alaka da', null, '["karakaina","gaishe-gaishe","kashe kudi","kamun kafa."]', 2, 'Shiga-ka-fito wajen neman aure ta fi alaka da kashe kudi.', true, '2026-10-13 10:37:23.556', '2026-10-13 10:37:23.556', null, null, null, '''Ba neman aure ke da wuya ba, shiga-ka-fito''. Ka ga shiga-ka-fito din nan, lallai shiga-ka-fito din ne! Domin aljihu kan jigata kafin a kai ga biki. Tuddan da al''ada ta tanada, wadanda dole sai an haye su, suna da yawa. Yanzu dauki misalin kayan na-gani-ina-so, wato ''yan kayan nan da ake shiryawa a kai gidan su yarinya a karon farko. Ma''anar yin haka, wai iyaye su san cewa manemin auren ''yarsu da gaske yake. To, ina dole ga yin haka? Da can da yake zuwa yana zance da ''yarsu yana yi mata hasafi, ba a san da gaske yake ba? Gangaro kan kayan toshi. Nan ma tsabagen kudi ake kashewa a sayi suturu da kayan shafe-shafe a kai wa yarinya. Kada fa ka ce zuwa zance da manemi yake yana yi wa yarinya kyauta mako-mako, shi ke nan, ya wadatar. Ina, ko kadan! Kada ka mance da kudin gaisuwar iyaye da dukiyar aure kafin a yi baiko da sa ranar biki. Kudi ne madididiki ake tanada a kai wa iyayen yarinya da niyyar dai wannan abu da aka ambata. Duk bayan wannan, ana sa ranar aure, manemin yarinya ya dosa karakaina ke nan daga wannan gida zuwa wancan, ko ma wannan gari zuwa wancan da sunan gayar da iyaye da kakaninnta, wai don su san shi. I, za su san shi mana, tun da ba yana zuwa ne zikau ba! Da zarar biki ya kawo jiki kuma, uwa-uba za a shirya kayan lefe na fitar hankali a kai wa yarinya. Nan ma dukiya ake narkawa. Haķika duk wadannan abubuwa al''ada ce kawai ta kaķaba wa al''umma. Ai ta fuskar dukiya, muhimmin abu ga aure, sadaki. Amma abin takaici, yanzu an yi masa mahalli a can ķarshen sahu! Shiga-ka-fito wajen neman aure ta fi alaka da', '["karakaina","gaishe-gaishe","kashe kudi","kamun kafa."]', 'Shiga-ka-fito wajen neman aure ta fi alaka da kashe kudi.', '{"bold":["kashe kudi"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('459703c3-349c-4572-a627-0d9f70569076', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. In spite of many days of fasting, Musa is still <u>fastidious</u> about his food.', null, '["particular","undecided","indifferent","unmindful"]', 2, 'Fastidious = particular; opposite = indifferent.', true, '2026-10-24 07:21:16.943', '2026-10-24 07:21:16.943', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. In spite of many days of fasting, Musa is still <u>fastidious</u> about his food.', '["particular","undecided","indifferent","unmindful"]', 'Fastidious = particular; opposite = indifferent.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('45988831-cb34-4357-b68e-35e3e0f71ccf', 'English Language', 'JAMB', null, 2024, null, 'According to the novel, the Gurara Waterfall was actually discovered in what year?', null, '["1845","1745","1925","1945"]', 1, 'According to the novel, the Gurara Waterfall was discovered in 1745.', true, '2026-09-18 09:24:04.671', '2026-09-18 09:24:04.671', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('45ade0aa-441e-4dbf-a261-5d6cec834822', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Musa is a gifted but <u>erratic</u> player', null, '["strong","regular","unpredictable","unstable"]', 1, 'Erratic = unpredictable; opposite = regular.', true, '2026-10-24 07:21:31.686', '2026-10-24 07:21:31.686', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Musa is a gifted but <u>erratic</u> player', '["strong","regular","unpredictable","unstable"]', 'Erratic = unpredictable; opposite = regular.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('45b1874e-b18a-4de3-9678-7a3885b5f0c8', 'Biology', 'JAMB', null, 2003, null, 'Organisms I, II, III, IV have surface/volUTME ration of 1:2, 1:3, 1:4 and 1:5 respectively. The organism that is likely to have the most complex transport system is', null, '["IV","III","I","II"]', 0, 'A smaller surface-area-to-volUTME ratio means diffusion is insufficient, necessitating a more complex transport system.', true, '2026-10-12 20:05:09.661', '2026-10-12 20:05:09.661', null, null, null, 'Organisms I, II, III, IV have surface/volUTME ration of 1:2, 1:3, 1:4 and 1:5 respectively. The organism that is likely to have the most complex transport system is', '["IV","III","I","II"]', 'A smaller surface-area-to-volUTME ratio means diffusion is insufficient, necessitating a more complex transport system.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('45b7e4f7-cc85-46f0-b8a0-8f598235f7cd', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Toyin is married to an <u>impatient</u>, self-centered man.', null, '["a fretful","a tolerant","an edgy","a tolerable"]', 1, 'Impatient; opposite = tolerant.', true, '2026-10-24 07:21:24.226', '2026-10-24 07:21:24.226', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Toyin is married to an <u>impatient</u>, self-centered man.', '["a fretful","a tolerant","an edgy","a tolerable"]', 'Impatient; opposite = tolerant.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('45ba8b1e-5dca-42b0-bf9e-3c6fd40030d8', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). ''<u>To put something aside</u>'' is to ____________', null, '["put it by one''s side","put it in a side pocket for future use","keep something for some special purpose","keep in safety","protect it"]', 2, '''Put aside'' means reserve for special purpose.', true, '2026-10-24 01:02:00.983', '2026-10-24 01:02:00.983', null, null, null, '(Choose the most appropriate interpretation). ''<u>To put something aside</u>'' is to ____________', '["put it by one''s side","put it in a side pocket for future use","<u>keep something for some special purpose</u>","keep in safety","protect it"]', '''<b>Put aside</b>'' means <b>reserve for special purpose</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('45c8acbd-761e-48b7-aeaf-de8f75d9317e', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). It was their custom to <u>keep an open house</u> on Sundays.', null, '["welcome all visitors","keep the shutters open","leave the house open","expose the whole house"]', 0, '''Keep an open house'' = welcome all visitors.', true, '2026-10-24 01:02:05.482', '2026-10-24 01:02:05.482', null, null, null, '(Choose the most appropriate interpretation). It was their custom to <u>keep an open house</u> on Sundays.', '["<u>welcome all visitors</u>","keep the shutters open","leave the house open","expose the whole house"]', '''<b>Keep an open house</b>'' = <b>welcome all visitors</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('45d1ce2e-a91e-4bd0-8919-e9996684d5b8', 'Physics', 'JAMB', null, 2026, null, 'Starting from rest, a car of mass 2000kg accelerates steadily to 15ms⁻¹ in 10s. Calculate the average power developed during the period.', null, '["15000J","15500J","22500J","10000J"]', 2, 'Acceleration a = 15/10 = 1.5 m/s². Force F = ma = 2000 × 1.5 = 3000N. Distance s = ½at² = ½ × 1.5 × 100 = 75m. Work done = Fs = 3000 × 75 = 225000J. Average power = Work/time = 225000/10 = 22500W.', true, '2026-09-10 10:56:42.765', '2026-09-10 10:56:42.765', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('45d229f8-c355-4983-9420-e89fb549c8c3', 'Chemistry', 'JAMB', null, 2026, null, 'On which of the following is the solubility of gaseous substance dependent (I) nature of the solvent (II) nature of the solute (III) temperature (IV) pressure', null, '["I, II, III, IV","I, II","II","I, III, IV"]', 0, 'Gas solubility in liquids depends on solute/solvent chemical identity, ambient temperature, and external partial pressure (Henry''s Law).', true, '2026-09-09 17:12:45.89', '2026-09-09 17:12:45.89', null, null, null, null, null, null, null);
