insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('45eb21fc-1c32-46e5-9c52-c9dbfbee0070', 'Government', 'JAMB', null, 2026, null, 'The French Policy of Assimilation was based on the idea that African culture was', null, '["Expensive","Unwritten","Elaborate","Inferior"]', 3, 'The French policy of assimilation assumed African culture was inferior.', true, '2026-09-12 11:24:25.608', '2026-09-12 11:24:25.608', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('45eed549-ba7c-4b08-8c61-7bc738936f04', 'Chemistry', 'JAMB', null, 2026, null, 'The thermal decomposition of ammonium nitrate yields ______ and the decomposition of trioxonitrate (V) acid when heated is ______', null, '["NO₂, O₂ and NO₂, water","N₂O, water and NO₂, O₂","water, NO₂ and NO₂, O₂","NO, N and NO₂, N₂O"]', 1, 'NH₄NO₃ → N₂O + 2H₂O. 4HNO₃ → 4NO₂ + O₂ + 2H₂O.', true, '2026-09-12 11:36:00.714', '2026-09-12 11:36:00.714', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('45f133f8-930a-487f-a6f7-c658a9e0382a', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The policy has been <u>espoused</u> by the ruling party.', null, '["condemned","supported","rejected","outlined"]', 1, 'Espoused = supported.', true, '2026-10-24 01:01:55.543', '2026-10-24 01:01:55.543', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The policy has been <u>espoused</u> by the ruling party.', '["condemned","<u>supported</u>","rejected","outlined"]', '<b>Espoused</b> = <b>supported</b>.', '{}');
