insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4623ec5e-6437-4866-8fa9-07b577b8fa17', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Sola is <u>apathetic</u> about his work.', null, '["indifferent","enthusiastic","half-hearted","bored"]', 1, 'Apathetic = indifferent; opposite = enthusiastic.', true, '2026-10-24 07:21:27.556', '2026-10-24 07:21:27.556', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Sola is <u>apathetic</u> about his work.', '["indifferent","enthusiastic","half-hearted","bored"]', 'Apathetic = indifferent; opposite = enthusiastic.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('46290374-6deb-41b2-a5c1-9e5868992abc', 'Physics', 'JAMB', null, 1986, null, 'The sign of the charge on a charged glass rod may be determined with', null, '["A charged electroscope","An uncharged electroscope","A galvanometer","An electrometer."]', 0, 'Bringing the rod near a charged electroscope, the leaf divergence increases if the charges are alike and decreases if unlike, so the sign can be found. An uncharged electroscope only detects the presence of charge.', true, '2026-10-12 19:15:24.433', '2026-10-12 19:15:24.433', null, null, null, 'The sign of the charge on a charged glass rod may be determined with', '["A charged electroscope","An uncharged electroscope","A galvanometer","An electrometer."]', 'Bringing the rod near a charged electroscope, the leaf divergence increases if the charges are alike and decreases if unlike, so the sign can be found. An uncharged electroscope only detects the presence of charge.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('462feda2-fcc9-4ac0-b5c4-7a2469af55a5', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). <u>I would rather not attend</u> the party.', null, '["detest attending","do not have the enthusiasm to attend","must not attend","have a choice to attend or not to"]', 1, '''Would rather not'' = lack of enthusiasm.', true, '2026-10-24 01:02:04.423', '2026-10-24 01:02:04.423', null, null, null, '(Choose the most appropriate interpretation). <u>I would rather not attend</u> the party.', '["detest attending","<u>do not have the enthusiasm to attend</u>","must not attend","have a choice to attend or not to"]', '''<b>Would rather not</b>'' = <b>lack of enthusiasm</b>.', '{}');
