insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('463554c1-56d7-4530-a9da-d0c317d8a197', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The witness decided to <u>conceal</u> the evidence.', null, '["divulge","hide","destroy","pugnacious"]', 0, 'Conceal = hide; opposite = divulge.', true, '2026-10-24 07:21:23.915', '2026-10-24 07:21:23.915', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The witness decided to <u>conceal</u> the evidence.', '["divulge","hide","destroy","pugnacious"]', 'Conceal = hide; opposite = divulge.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('463fda21-5520-4d6b-ab62-8d4193e9f56b', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). The man insisted on having <u>no strings attached</u> to the agreement.', null, '["financial obligations","documents","conditions","moral obligations"]', 2, '''No strings attached'' = without conditions.', true, '2026-10-24 01:04:19.754', '2026-10-24 01:04:19.754', null, null, null, '(Choose the most appropriate interpretation). The man insisted on having <u>no strings attached</u> to the agreement.', '["financial obligations","documents","<u>conditions</u>","moral obligations"]', '''<b>No strings attached</b>'' = <b>without conditions</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('464172d5-3a58-4e22-9de7-56c5b2cef538', 'Literature in English', 'JAMB', null, 2026, null, 'The central theme of The Digging is', null, '["Industrialisation","War and conflict","Respect for ancestral labour and identity","Religious devotion"]', 2, 'The central theme is respect for ancestral labour and identity.', true, '2026-09-12 11:09:54.001', '2026-09-12 11:09:54.001', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4641bf3f-a26f-4abd-be61-a60812deccf2', 'Biology', 'JAMB', null, 2026, null, 'One advantage of outbreeding is', null, '["pests tolerance","disease tolerance","fast growth","tall height"]', 1, 'One advantage of outbreeding is disease tolerance. Outbreeding increases genetic diversity, which can lead to hybrid vigor (heterosis). Offspring of unrelated parents may have a better immune system and greater resistance to diseases. This is because they are more likely to have a diverse set of alleles, making them less susceptible to pathogens and diseases.', true, '2026-09-09 03:19:19.735', '2026-09-09 03:19:19.735', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4644c002-c159-416b-9f01-b343ec0f4916', 'Physics', 'JAMB', null, 2026, null, 'The charge a material obtains is due to the', null, '["Proton loss/gain","Proton and Electron Number","Electron Loss/Gain","Hydrogen Bonds"]', 2, 'The charge a material obtains is due to electron loss or gain. When an object loses electrons, it becomes positively charged. When it gains electrons, it becomes negatively charged. Protons are not transferred in charging processes.', true, '2026-09-10 10:56:45.199', '2026-09-10 10:56:45.199', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('464be13b-b767-4bb8-97da-c6df1f377bfc', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). If experience is anything to go by, this action will prove <u>a political minefield</u>.', null, '["a sources of political benefits","a way out of political trouble","a causes for political joy","an invitation to political problems"]', 3, '''A political minefield'' = invitation to political problems.', true, '2026-10-24 01:02:08.392', '2026-10-24 01:02:08.392', null, null, null, '(Choose the most appropriate interpretation). If experience is anything to go by, this action will prove <u>a political minefield</u>.', '["a sources of political benefits","a way out of political trouble","a causes for political joy","<u>an invitation to political problems</u>"]', '''A <b>political minefield</b>'' = <b>invitation to political problems</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('46562b5b-373c-4294-aa68-65c95d43bf2f', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The leader has the <u>unstinting</u> support of his party.', null, '["unsparing","laudable","uninspiring","cautious"]', 0, 'Unstinting = unsparing.', true, '2026-10-24 01:04:04.348', '2026-10-24 01:04:04.348', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The leader has the <u>unstinting</u> support of his party.', '["<u>unsparing</u>","laudable","uninspiring","cautious"]', '<b>Unstinting</b> = <b>unsparing</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('46704f6a-3975-45d0-ab50-df2937c2ffc1', 'Yoruba', 'JAMB', null, 2007, null, 'Ìwé Àyàyàn Àlò Onítàn ni ìbéèrè 26-28 dá lé. Nínú ìtàn Ìdí tí Çyc Àkókó ýe p fçnu sò igi, ta ni àwòn ökùnrin p dù láti fè?', null, '["Bçwclç","Ìyá çlèmu","Àkalà","Ìyá arúgbó."]', 0, 'Bçwclç ni àwòn ökùnrin p dù láti fè.', true, '2026-10-13 13:23:31.74', '2026-10-13 13:23:31.74', null, null, null, 'Ìwé Àyàyàn Àlò Onítàn ni ìbéèrè 26-28 dá lé. Nínú ìtàn Ìdí tí Çyc Àkókó ýe p fçnu sò igi, ta ni àwòn ökùnrin p dù láti fè?', '["Bçwclç","Ìyá çlèmu","Àkalà","Ìyá arúgbó."]', 'Bçwclç ni àwòn ökùnrin p dù láti fè.', '{"bold":["Bçwclç"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('467e866e-1ce7-4188-9797-6220e25001e9', 'Government', 'JAMB', null, 2026, null, 'The non-aligned movement was established by group of third world countries at the', null, '["Berlin conference 1884","Bandung conference 1955","Accra Conference 1958","Addis Ababa Conference 1963"]', 1, 'The non-aligned movement was established at the Bandung Conference in 1955.', true, '2026-09-12 11:24:14.604', '2026-09-12 11:24:14.604', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('469feb7a-f680-4dba-9f08-4a1360e7e146', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). The distance is not more than twenty kilometres <u>as the crow flies</u>.', null, '["by the longest route","by the shortest route","by air","by the fastest means"]', 1, '''As the crow flies'' = shortest route.', true, '2026-10-24 01:02:06.275', '2026-10-24 01:02:06.275', null, null, null, '(Choose the most appropriate interpretation). The distance is not more than twenty kilometres <u>as the crow flies</u>.', '["by the longest route","<u>by the shortest route</u>","by air","by the fastest means"]', '''<b>As the crow flies</b>'' = <b>shortest route</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('46aa3434-fa50-4d09-af1c-ec9d2f7b6fb1', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). The story is rather <u>hard to believe</u>.', null, '["incredulous","incredible","superstitious","untenable"]', 1, 'Incredible = hard to believe.', true, '2026-10-24 01:02:03.839', '2026-10-24 01:02:03.839', null, null, null, '(Choose the most appropriate interpretation). The story is rather <u>hard to believe</u>.', '["incredulous","<u>incredible</u>","superstitious","untenable"]', '<b>Incredible</b> = <b>hard to believe</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('46bcda4d-12ff-4ce6-a523-84449cd7c2c0', 'Physics', 'JAMB', null, 2026, null, 'What is the apparent colour of a green shirt in a pure red light?', null, '["green","yellow","black","red"]', 2, 'A green shirt appears black in pure red light. A green object reflects green light and absorbs all other colours. Red light contains no green light, so the shirt absorbs the red light and reflects nothing, appearing black.', true, '2026-09-10 10:56:41.789', '2026-09-10 10:56:41.789', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('46c4b364-5246-4f42-b982-fcc6efb9a7dc', 'Hausa', 'JAMB', null, 2010, null, 'Mene ne jigon ''Waĉar Hana Zalunci'' ta Salihu Kwantagora a WaKoĉin Hausa?', null, '["Saĉa wa tafarkin adalci.","Saĉa wa tafarkin lalaci.","Jahilci.","Fariya."]', 0, 'Jigon wakar shi ne saĉa wa tafarkin adalci.', true, '2026-10-13 10:37:25.536', '2026-10-13 10:37:25.536', null, null, null, 'Mene ne jigon ''Waĉar Hana Zalunci'' ta Salihu Kwantagora a WaKoĉin Hausa?', '["Saĉa wa tafarkin adalci.","Saĉa wa tafarkin lalaci.","Jahilci.","Fariya."]', 'Jigon wakar shi ne saĉa wa tafarkin adalci.', '{"bold":["saĉa wa tafarkin adalci"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('46d823e3-ed83-4c7c-9111-0c1562c0d917', 'Financial Accounting', 'UTME', null, 2003, null, 'A company has two departments X and Y. Y transferred goods to X at a profit margin of 25%. N10 000 worth of goods was not sold at the end of the accounting period. How much is the unrealized profit?', null, '["N2 000","N2 500","N12 000","N12 500"]', 1, 'Goods worth 10,000 will be sold for 12,500 i.e., Cost + 25% profit. Unrealized profit will be 12,500 - 10,000 = 2,500.', true, '2026-10-12 22:00:00.668', '2026-10-12 22:00:00.668', null, null, null, 'A company has two departments X and Y. Y transferred goods to X at a profit margin of 25%. N10 000 worth of goods was not sold at the end of the accounting period. How much is the unrealized profit?', '["N2 000","<b>N2 500</b>","N12 000","N12 500"]', 'Goods worth 10,000 will be sold for 12,500 i.e., Cost + 25% profit. Unrealized profit will be 12,500 - 10,000 = <b>2,500</b>.', '{"bold":["2,500"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('46db956a-bccb-4643-883f-59b501c5b1ae', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Jesus mostly referred to Himself as the Son of', null, '["Man","Jacob","God","David","Abraham"]', 0, 'Jesus most often called Himself the Son of Man.', true, '2026-09-12 10:42:10.682', '2026-09-12 10:42:10.682', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('46dd9c45-2554-4a65-a0ce-b80461c7f701', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'One of the seven Hellenists who preached the gospel in Samaria and from Azotus to the Syrian capital, Caesarea, was', null, '["Stephen","Prochorus","Nicanor","Philip"]', 3, 'Philip was one of the seven Hellenists chosen to serve tables. He preached the gospel in Samaria, converted the Ethiopian Eunuch, and preached from Azotus to Caesarea.', true, '2026-09-12 09:45:53.527', '2026-09-12 09:45:53.527', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('46e7948a-dd5e-4c02-898a-d698ab20366a', 'Government', 'JAMB', null, 2026, null, 'The administrative head of a ministry under the civil service is', null, '["managing director","permanent secretary","general secretary","minister"]', 1, 'The administrative head of a ministry under the civil service is the Permanent Secretary. The Permanent Secretary is the highest-ranking civil servant in a ministry. They are responsible for the day-to-day administration of the ministry and advise the minister on policy matters. The minister is a political appointee and the head of the ministry, but the Permanent Secretary is the administrative head. The managing director heads a parastatal, and the general secretary is a union position.', true, '2026-09-10 10:45:06.356', '2026-09-10 10:45:06.356', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('46ebbfc4-2cc1-4eb7-9a4a-d9879063637e', 'Physics', 'JAMB', null, 2026, null, 'A few grains of table salt were put in a cup of cold water, kept at constant temperature and left undisturbed. Eventually all the water tested salty. This action is due to', null, '["convention","osmosis","capillarity","diffusion"]', 3, 'The salt spreads throughout the water by diffusion. Diffusion is the movement of particles from a region of higher concentration to a region of lower concentration. The salt molecules dissolve and spread evenly through the water by random molecular motion.', true, '2026-09-10 10:56:39.998', '2026-09-10 10:56:39.998', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('46f80931-3e42-425e-9e9b-6c17d3833d3c', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Jesus declared that men love darkness rather than light because', null, '["their hearts were hardened","they had no truth","they had been blinded","their deeds were evil"]', 3, 'Men loved darkness because their deeds were evil (John 3:19).', true, '2026-09-12 10:41:38.9', '2026-09-12 10:41:38.9', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('46f81749-e35d-4f4d-ae9a-49df5bd1fc41', 'Financial Accounting', 'UTME', null, 2003, null, 'Using the periodic simple average method, the cost per unit is', null, '["N4.25","N3.25","N2.25","N1.25"]', 2, 'Simple Average Method: Date Price Feb.1 1, Feb.5 2, Feb.10 3, Feb.20 4. Total N10. Cost per unit = N10/4 = N2.50.', true, '2026-10-12 22:00:00.076', '2026-10-12 22:00:00.076', null, null, null, 'Using the periodic simple average method, the cost per unit is', '["N4.25","N3.25","<b>N2.25</b>","N1.25"]', 'Simple Average Method: Date Price Feb.1 1, Feb.5 2, Feb.10 3, Feb.20 4. Total N10. Cost per unit = N10/4 = <b>N2.50</b>.', '{"bold":["N2.50"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4700bdb4-d79b-412f-be54-54b3f6de1e78', 'Biology', 'JAMB', null, 2026, null, 'A plant which has a horizontal underground stem is', null, '["Rhizome","Corm","Creeper","Tuber","Bulb"]', 0, 'A rhizome is a horizontal underground stem that grows parallel to the soil surface. It has nodes and internodes, and produces adventitious roots from the nodes. Examples include ginger, turmeric, and some grasses. A corm is a swollen vertical underground stem (e.g., cocoyam). A tuber is a swollen stem tip (e.g., potato). A bulb is a reduced stem with fleshy leaves (e.g., onion). A creeper is a plant that grows along the ground but is not necessarily underground. Rhizomes allow for vegetative propagation and survival through unfavorable conditions.', true, '2026-09-09 03:18:22.541', '2026-09-09 03:18:22.541', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('471481c7-bb20-40e2-a141-d341c7743157', 'General Mathematics', 'JAMB', null, 2026, null, 'A binary operation is defined by a*b = a²b + 1. Evaluate (2*3)*4', null, '["677","13","44","209"]', 3, '2*3 = 4(3)+1 = 13. 13*4 = 169(4)+1 = 677. The answer is (A) 677.', true, '2026-09-12 11:44:19.985', '2026-09-12 11:44:19.985', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('47307d51-607e-4d54-9965-fadc11e38132', 'Literature in English', 'JAMB', null, 2026, null, 'A tragic hero, according to the Aristotelian precept must be', null, '["a noble character with hubris","a lowly character who suddenly stumbles on some fortune","a king with deep affection for his subjects","a central character after whom the play is named"]', 0, 'A tragic hero is a noble character with hubris.', true, '2026-09-12 11:10:53.88', '2026-09-12 11:10:53.88', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4734013f-e10b-43be-8e9d-3d194af69c3d', 'Physics', 'JAMB', null, 2002, null, 'The particle that is responsible for nuclear fission in a nuclear reactor is', null, '["Electron","Neutron","Photon","Proton"]', 1, 'A slow neutron is absorbed by a uranium nucleus, which splits and releases more neutrons for the chain reaction.', true, '2026-10-12 19:15:54.352', '2026-10-12 19:15:54.352', null, null, null, 'The particle that is responsible for nuclear fission in a nuclear reactor is', '["Electron","Neutron","Photon","Proton"]', 'A slow neutron is absorbed by a uranium nucleus, which splits and releases more neutrons for the chain reaction.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
