insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('47349bb7-94c5-4357-9a9f-a124718cdc04', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Many would argue that the achievement <u>commensurate with</u> the effort.', null, '["unexpected in the light of","funny compared with","proportional to","the wrong excuse for"]', 2, 'Commensurate with = proportional to.', true, '2026-10-24 01:03:59.532', '2026-10-24 01:03:59.532', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Many would argue that the achievement <u>commensurate with</u> the effort.', '["unexpected in the light of","funny compared with","<u>proportional to</u>","the wrong excuse for"]', '<b>Commensurate with</b> = <b>proportional to</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('47394292-189d-4378-8391-af10f8f2e684', 'Chemistry', 'JAMB', null, 2026, null, 'Which of the following statements is NOT correct?', null, '["The average kinetic energy of a gas is directly proportional to its temperature","At constant temperature, the volume of a gas increases as the pressure increases","The pressure of a gas is inversely proportional to the density","The temperature of a gas is directly proportional to its volume"]', 1, 'At constant temperature, volume decreases as pressure increases (Boyle''s Law).', true, '2026-09-12 11:36:14.327', '2026-09-12 11:36:14.327', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('473cb238-ba4b-4119-947b-2c2e53016ebe', 'English Language', 'JAMB', null, 2007, null, 'Three-quarters of the people in the village <u>------------</u> killed but only half of their huts <u>------------</u> affected.', null, '["were/were","was/was","were/was","was/were"]', 0, 'Both people and huts plural â†’ were/were.', true, '2026-10-24 01:04:28.78', '2026-10-24 01:04:28.78', null, null, null, 'Three-quarters of the people in the village <u>------------</u> killed but only half of their huts <u>------------</u> affected.', '["<u>were/were</u>","was/was","were/was","was/were"]', 'Both <b>people</b> and <b>huts</b> plural â†’ <b>were/were</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('47418fcc-d9c6-4781-ae43-3e6f7c3af0ea', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Nigeria has been playing a <u>vital</u> role in the political and economic development of Africa.', null, '["respectable","creditable","laudable","crucial"]', 3, 'Vital = crucial.', true, '2026-10-24 01:04:06.168', '2026-10-24 01:04:06.168', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Nigeria has been playing a <u>vital</u> role in the political and economic development of Africa.', '["respectable","creditable","laudable","<u>crucial</u>"]', '<b>Vital</b> = <b>crucial</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4749de3d-9a26-4a80-83b4-d8e16f6d0d90', 'Physics', 'JAMB', null, 1995, null, 'What is the acceleration due to gravity g on the moon, if g is 10 m s⁻² on the earth?', null, '["0.10 m s⁻²","0.74 m s⁻²","1.67 m s⁻²","10.00 m s⁻²"]', 2, 'Gravity on the moon is about one-sixth of that on the earth: 10/6 ≈ 1.67 m s⁻².', true, '2026-10-12 19:15:40.772', '2026-10-12 19:15:40.772', null, null, null, 'What is the acceleration due to gravity g on the moon, if g is 10 m s<sup>-2</sup> on the earth?', '["0.10 m s<sup>-2</sup>","0.74 m s<sup>-2</sup>","1.67 m s<sup>-2</sup>","10.00 m s<sup>-2</sup>"]', 'Gravity on the moon is about one-sixth of that on the earth: 10/6 ≈ 1.67 m s<sup>-2</sup>.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('474efb29-5597-4793-86c4-c37b75cf8014', 'Literature in English', 'JAMB', null, 2026, null, 'Which of these characters is not mentioned in the poem?', null, '["Chinwe","Danladi","Akanni","Ibrahim"]', 3, 'Ibrahim is not mentioned in the poem.', true, '2026-09-12 11:10:40.309', '2026-09-12 11:10:40.309', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('47537ac6-6c1f-47b2-9f4c-58cc8d1577c0', 'Literature in English', 'JAMB', null, 2026, null, 'In the poem, the sea mainly serves as', null, '["a place of entertainment","a witness to human history and suffering","a symbol of wealth","a source of political power"]', 1, 'The sea serves as a witness to human history and suffering.', true, '2026-09-12 11:10:18.645', '2026-09-12 11:10:18.645', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('475b58a2-4549-43d9-ac15-13c4a586162e', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The officer said that he knew nothing to the <u>detriment</u> of the applicant.', null, '["damage","disfavour","advantage","background"]', 2, 'Detriment = harm; opposite = advantage.', true, '2026-10-24 07:21:21.007', '2026-10-24 07:21:21.007', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The officer said that he knew nothing to the <u>detriment</u> of the applicant.', '["damage","disfavour","advantage","background"]', 'Detriment = harm; opposite = advantage.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('475d71b3-3fdd-4d4b-bffe-95b7e59992ee', 'Literature in English', 'JAMB', null, 2026, null, '''Haman is an out-at-the elbow looking man'' is referred to as', null, '["Metonymy","Idiomatic expression","Personification","Irony"]', 1, 'It is an idiomatic expression.', true, '2026-09-12 11:13:52.052', '2026-09-12 11:13:52.052', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('477c48c9-f163-40f6-ae07-e5a6bea2a3a4', 'Literature in English', 'JAMB', null, 2026, null, 'In Still I Rise, the repetition of ''I rise'' is an example of', null, '["Alliteration","Anaphora","Euphemism","Irony"]', 1, 'The repetition of ''I rise'' is anaphora.', true, '2026-09-12 11:05:14.48', '2026-09-12 11:05:14.48', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4791c2c0-c6d7-4ecc-8451-85123427b7c3', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. As <u>a prudent</u> businessman, Adayi does not leave anything to chance.', null, '["a frugal","a shrewd","a careless","an unsuccessful"]', 2, 'Prudent = careful; opposite = careless.', true, '2026-10-24 07:21:29.772', '2026-10-24 07:21:29.772', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. As <u>a prudent</u> businessman, Adayi does not leave anything to chance.', '["a frugal","a shrewd","a careless","an unsuccessful"]', 'Prudent = careful; opposite = careless.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('479235ca-0aa8-4d72-9a27-1e5155a3ea7b', 'Financial Accounting', 'UTME', null, 2003, null, 'Compute the amount withdrawn', 'https://res.cloudinary.com/kwi1uv0g/image/upload/v1791841222/questions/iybak9d1qgbdmcon1o9q.jpg', '["N2 000","N1 500","N1 250","N1 000"]', 3, 'Drawings 50% of capital. Capital 2000 (given). Therefore, drawings = 50/100 x 2000 = 1000.', true, '2026-10-12 21:59:59.386', '2026-10-12 21:59:59.386', null, null, null, 'Compute the amount withdrawn', '["N2 000","N1 500","N1 250","<b>N1 000</b>"]', 'Drawings 50% of capital. Capital 2000 (given). Therefore, drawings = 50/100 x 2000 = <b>1000</b>.', '{"bold":["1000"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('47a1afdc-c413-462a-872d-156c24eb5ab6', 'Physics', 'JAMB', null, 1987, null, 'Calculate the amount of heat required to convert 2 kg of ice at -2 °C to water at 0 °C. (Specific heat capacity of ice = 2090 J kg⁻¹ °C⁻¹, specific latent heat of fusion = 333 kJ kg⁻¹).', null, '["666 J","8 360 J","666 000 J","674 360 J."]', 3, 'Warm the ice to 0 °C: 2 x 2090 x 2 = 8 360 J. Melt it: 2 x 333 000 = 666 000 J. Total = 674 360 J.', true, '2026-10-12 19:15:25.425', '2026-10-12 19:15:25.425', null, null, null, 'Calculate the amount of heat required to convert 2 kg of ice at -2 °C to water at 0 °C. (Specific heat capacity of ice = 2090 J kg<sup>-1</sup> °C<sup>-1</sup>, specific latent heat of fusion = 333 kJ kg<sup>-1</sup>).', '["666 J","8 360 J","666 000 J","674 360 J."]', 'Warm the ice to 0 °C: 2 x 2090 x 2 = 8 360 J. Melt it: 2 x 333 000 = 666 000 J. Total = 674 360 J.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('47a85df1-c971-44fe-a0dd-76933cb3cf75', 'Physics', 'JAMB', null, 1997, null, 'A patient with a sight defect has a distance of distinct vision of 150 cm. For him to be able to read a material placed at a distance of 25 cm, what is the focal length of the glasses he should wear?', null, '["15.0 cm","17.6 cm","21.4 cm","30.0 cm"]', 3, 'The lens must form a virtual image at 150 cm of an object at 25 cm: 1/f = 1/25 - 1/150 = 5/150, so f = 30 cm.', true, '2026-10-12 19:15:44.012', '2026-10-12 19:15:44.012', null, null, null, 'A patient with a sight defect has a distance of distinct vision of 150 cm. For him to be able to read a material placed at a distance of 25 cm, what is the focal length of the glasses he should wear?', '["15.0 cm","17.6 cm","21.4 cm","30.0 cm"]', 'The lens must form a virtual image at 150 cm of an object at 25 cm: 1/f = 1/25 - 1/150 = 5/150, so f = 30 cm.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('47ac2e59-adea-4bb6-a5cc-70b17c32ea05', 'Economics', 'JAMB', null, 2026, null, 'The demand for labor is an example of', null, '["composite demand","joint demand","derived demand","competitive demand"]', 2, 'The demand for labor is an example of derived demand. Derived demand means that the demand for a factor of production (like labor) is derived from the demand for the goods and services that the labor helps to produce. If there is no demand for the final product, there will be no demand for the labor to produce it. Composite demand is when a good is demanded for multiple uses. Joint demand is when goods are demanded together.', true, '2026-09-10 10:42:00.663', '2026-09-10 10:42:00.663', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('47c019f1-6b0b-40c5-abb1-860602287fe4', 'Physics', 'JAMB', null, 2026, null, 'The particle that is responsible for nuclear fission in a nuclear reactor is', null, '["neutron","proton","electron","photon"]', 0, 'The neutron is responsible for nuclear fission in a nuclear reactor. When a neutron strikes a heavy nucleus like uranium-235, it causes the nucleus to split, releasing energy and more neutrons.', true, '2026-09-10 10:56:46.87', '2026-09-10 10:56:46.87', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('47c52cb6-c07f-440f-b058-7a9da7e0b875', 'Physics', 'JAMB', null, 2026, null, 'What is the escape velocity of a satellite launched from the earth''s surface? (Take g as 10ms⁻² and the radius of the earth as 6.4×10⁶m)', null, '["7.80×10³ ms⁻¹","11.2×10³ ms⁻¹","3.56×10⁷ ms⁻¹","6.00×10⁷ ms⁻¹","1.20×10⁸ ms⁻¹"]', 1, 'Escape velocity v = √(2gR) = √(2 × 10 × 6.4×10⁶) = √(1.28×10⁸) = 1.13×10⁴ m/s ≈ 11.2×10³ m/s.', true, '2026-09-10 10:56:44.28', '2026-09-10 10:56:44.28', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('47cf8f60-22f9-4374-a31c-58aa52dece15', 'Biology', 'JAMB', null, 2005, null, 'The main reservoir of water in the cycle is the', null, '["cloud","groundwater","plant","ocean"]', 3, 'The ocean is the main reservoir of water.', true, '2026-10-12 20:59:37.683', '2026-10-12 20:59:37.683', null, null, null, 'The main reservoir of water in the cycle is the', '["cloud","groundwater","plant","ocean"]', 'The ocean is the main reservoir of water.', '{"bold":["ocean"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('47d075af-0e7a-472e-b165-61f9126bcb21', 'English Language', 'JAMB', null, 2024, null, 'After we have taken our share, we shall give ______ to them.', null, '["Their","Theirs","Their''s","Theirs''"]', 1, '"Theirs" is the correct possessive pronoun.', true, '2026-09-18 09:34:03.969', '2026-09-18 09:34:03.969', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('47df0a34-9fe0-4c80-8dfb-ab9e3c6e4caa', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Kaltume <u>crouched over</u> the letter on her desk.', null, '["stood on","walked over","bent over","wrote on"]', 2, 'Crouched = bent over.', true, '2026-10-24 01:01:54.431', '2026-10-24 01:01:54.431', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Kaltume <u>crouched over</u> the letter on her desk.', '["stood on","walked over","<u>bent over</u>","wrote on"]', '<b>Crouched</b> = <b>bent over</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('47e9eb0c-5251-40cd-96ac-e15c52b5c211', 'Literature in English', 'JAMB', null, 2026, null, 'In She Walks in Beauty, the line ''She walks in beauty, like the night'' is an example of', null, '["Metaphor","Simile","Personification","Oxymoron"]', 1, 'The line is a simile using ''like''.', true, '2026-09-12 11:12:02.571', '2026-09-12 11:12:02.571', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4807cc73-f794-4f19-bf69-df0c6fa31314', 'Physics', 'JAMB', null, 1988, null, 'A 20-toothed gear wheel drives a 60-toothed one. If the angular speed of the smaller wheel is 120 rev s⁻¹, the angular speed of the larger wheel is', null, '["3 rev s⁻¹","40 rev s⁻¹","360 rev s⁻¹","2 400 rev s⁻¹"]', 1, 'Angular speeds are inversely proportional to the number of teeth: 120 x 20/60 = 40 rev s⁻¹.', true, '2026-10-12 19:15:27.105', '2026-10-12 19:15:27.105', null, null, null, 'A 20-toothed gear wheel drives a 60-toothed one. If the angular speed of the smaller wheel is 120 rev s<sup>-1</sup>, the angular speed of the larger wheel is', '["3 rev s<sup>-1</sup>","40 rev s<sup>-1</sup>","360 rev s<sup>-1</sup>","2 400 rev s<sup>-1</sup>"]', 'Angular speeds are inversely proportional to the number of teeth: 120 x 20/60 = 40 rev s<sup>-1</sup>.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('48080868-89d8-418b-a87c-b22847080b67', 'General Mathematics', 'JAMB', null, 2026, null, 'The sum of the first 5 terms of a GP with first term 2 and common ratio 3 is:', null, '["242","244","246","248"]', 0, 'S5 = 2(3⁵-1)/(3-1) = 2(242)/2 = 242.', true, '2026-09-12 11:44:15.192', '2026-09-12 11:44:15.192', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4809fd93-1c6a-4bf9-b50f-17bffa19924f', 'General Mathematics', 'JAMB', null, 2026, null, 'An arc of a circle of radius 2cm subtends an angle of 60° at the centre. Find the area of the sector', null, '["2π/3 cm²","2π/3 cm³","π cm²","π/3 cm²","π/6 cm²"]', 0, 'Area = (60/360)π(4) = (1/6)(4π) = 2π/3 cm².', true, '2026-09-12 11:44:23.304', '2026-09-12 11:44:23.304', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('480ec4fc-efc4-4ed1-82ab-6912a98300ad', 'Literature in English', 'JAMB', null, 2026, null, '''The bitter taste of failure lingered on his tongue'' illustrates', null, '["Visual imagery","Gustatory imagery","Auditory imagery","Kinesthetic imagery"]', 1, 'It illustrates gustatory imagery.', true, '2026-09-12 11:11:29.845', '2026-09-12 11:11:29.845', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('481096ea-9ddb-4a90-997e-c59c792e8efa', 'Christian Religious Studies', 'JAMB', null, 2026, null, '''Do not weep for me, but weep for yourselves and for your children...'' These words were addressed by Jesus to the', null, '["sons of Jerusalem","men of Bethlehem","women of Bethlehem","daughters of Jerusalem"]', 3, 'These words were addressed by Jesus to the daughters of Jerusalem. As Jesus was being led to crucifixion, a great multitude of people followed Him, including women who bewailed and lamented Him. Jesus turned to them and said, ''Daughters of Jerusalem, do not weep for me, but weep for yourselves and for your children.''', true, '2026-09-12 09:46:10.951', '2026-09-12 09:46:10.951', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4813ff30-337c-4ebe-b0c5-a63d8a19e973', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The <u>hardline</u> posture of the labour leader has not helped matters', null, '["imposing","difficult","compromising","uncompromising"]', 2, 'Hardline = uncompromising; opposite = compromising.', true, '2026-10-24 07:21:23.162', '2026-10-24 07:21:23.162', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The <u>hardline</u> posture of the labour leader has not helped matters', '["imposing","difficult","compromising","uncompromising"]', 'Hardline = uncompromising; opposite = compromising.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('481c5352-7172-41d1-80a5-af39f3196871', 'English Language', 'JAMB', null, 2007, null, 'His chances in the game <u>------------</u> seriously jeopardized.', null, '["have been","has been","have being","has being"]', 0, 'Plural ''chances'' â†’ have been.', true, '2026-10-24 01:04:28.329', '2026-10-24 01:04:28.329', null, null, null, 'His chances in the game <u>------------</u> seriously jeopardized.', '["<u>have been</u>","has been","have being","has being"]', 'Plural ''<b>chances</b>'' â†’ <b>have been</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('481f24fb-41b5-48bd-9123-f10a1fc0712a', 'Physics', 'JAMB', null, 1984, null, 'What volume of alcohol with a density of 8.4 x 10² kg m⁻³ will have the same mass as 4.2 m³ of petrol whose density is 7.2 x 10² kg m⁻³?', null, '["1.4 m³","3.6 m³","4.9 m³","5.0 m³","5.8 m³"]', 1, 'Equal masses: 8.4 x 10² x V = 7.2 x 10² x 4.2, so V = (7.2 x 4.2)/8.4 = 3.6 m³.', true, '2026-10-12 19:15:18.475', '2026-10-12 19:15:18.475', null, null, null, 'What volume of alcohol with a density of 8.4 x 10<sup>2</sup> kg m<sup>-3</sup> will have the same mass as 4.2 m<sup>3</sup> of petrol whose density is 7.2 x 10<sup>2</sup> kg m<sup>-3</sup>?', '["1.4 m<sup>3</sup>","3.6 m<sup>3</sup>","4.9 m<sup>3</sup>","5.0 m<sup>3</sup>","5.8 m<sup>3</sup>"]', 'Equal masses: 8.4 x 10<sup>2</sup> x V = 7.2 x 10<sup>2</sup> x 4.2, so V = (7.2 x 4.2)/8.4 = 3.6 m<sup>3</sup>.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('48239229-83c7-4a09-a39f-6c6e506002ff', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Mali stole the day''s <u>takings</u> from the bakery.', null, '["receipts","collections","contributions","offerings"]', 0, 'Takings = receipts.', true, '2026-10-24 01:03:56.719', '2026-10-24 01:03:56.719', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Mali stole the day''s <u>takings</u> from the bakery.', '["<u>receipts</u>","collections","contributions","offerings"]', '<b>Takings</b> = <b>receipts</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4823ccd1-0a23-4a71-b996-a56be948af4d', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Some workers <u>went on rampage</u> at a trade-fair.', null, '["turned violent","robber","were angry","demonstrated"]', 0, 'Went on rampage = turned violent.', true, '2026-10-24 01:03:55.221', '2026-10-24 01:03:55.221', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Some workers <u>went on rampage</u> at a trade-fair.', '["<u>turned violent</u>","robber","were angry","demonstrated"]', '<b>Went on rampage</b> = <b>turned violent</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4824c5a9-650e-48bf-864c-8239a7f63a07', 'Literature in English', 'JAMB', null, 2026, null, 'Which of the following poetic devices is mostly used to praise the subject of the poem?', null, '["imagery","alliteration","hyperbole","apostrophe"]', 2, 'Hyperbole is mostly used to praise the subject.', true, '2026-09-12 11:10:07.156', '2026-09-12 11:10:07.156', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('482ca958-cf4c-4d10-be58-98cbb74f5043', 'Economics', 'JAMB', null, 2026, null, 'The transfer of public shareholding in corporations to private enterprise is', null, '["Commercialization","Incorporation","Deregulation","Privatization"]', 3, 'Privatization is the transfer of public shareholding to private enterprise.', true, '2026-09-12 10:58:55.078', '2026-09-12 10:58:55.078', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('48305bfb-2b02-44d6-a6df-a48b4a6d9a67', 'English Language', 'JAMB', null, 2007, null, 'One of the boys who ...... punished yesterday has apologised', null, '["was","is","were","has been"]', 2, '''Who'' refers to ''boys'' (plural) → ''were''.', true, '2026-10-25 18:25:06.574', '2026-10-25 18:25:06.574', null, null, null, 'One of the boys who ...... punished yesterday has apologised', '["was","is","were","has been"]', '''Who'' refers to ''boys'' (plural) → ''were''.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('48332efa-3aeb-4dd2-bb99-83b21bb2d4b7', 'Economics', 'JAMB', null, 2026, null, 'The trade-off between two commodities along the Production Possibility Curve (PPC) shows', null, '["Unattainable production","Scarcity principle","Transferable output","Opportunity cost principle"]', 3, 'The PPC illustrates the opportunity cost principle.', true, '2026-09-12 11:01:33.959', '2026-09-12 11:01:33.959', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('483de472-cee1-4bb9-9052-0e6763324da6', 'Physics', 'JAMB', null, 1984, null, 'A given mass of an ideal gas occupies a volume V at a temperature T and under a pressure P. If the pressure is increased to 2P and the temperature reduced to T/2, then the percentage change in the volume of the gas is', null, '["0 %","25 %","75 %","300 %","400 %"]', 2, 'V'' = V x (P/2P) x (T/2)/T = V/4. The volume falls to a quarter, a 75% change (decrease).', true, '2026-10-12 19:15:19.612', '2026-10-12 19:15:19.612', null, null, null, 'A given mass of an ideal gas occupies a volume V at a temperature T and under a pressure P. If the pressure is increased to 2P and the temperature reduced to T/2, then the percentage change in the volume of the gas is', '["0 %","25 %","75 %","300 %","400 %"]', 'V'' = V x (P/2P) x (T/2)/T = V/4. The volume falls to a quarter, a 75% change (decrease).', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4843ed00-0108-4aab-8932-bb87ac4d26d5', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. He was asked to give <u>copious</u> examples to appear convincing.', null, '["concrete","rigid","cogent","many"]', 3, 'Copious = many/plentiful.', true, '2026-10-24 01:01:46.478', '2026-10-24 01:01:46.478', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. He was asked to give <u>copious</u> examples to appear convincing.', '["concrete","rigid","cogent","<u>many</u>"]', '<b>Copious</b> = <b>many</b>/plentiful.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('48448e78-884e-4d85-8c80-2cbd5ee9947c', 'English Language', 'JAMB', null, 2024, null, 'Why was Bepo''s visit to the NIN office problematic?', null, '["the office was closed for maintenance","he faced network glitches during validation","he lost his National Identity Number","he was asked to provide additional documents"]', 1, 'Bepo faced network glitches during validation.', true, '2026-09-18 09:43:02.77', '2026-09-18 09:43:02.77', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4849bfa9-a958-4751-b4c7-d5d7ca329528', 'Yoruba', 'JAMB', null, 2002, null, 'Ìwé Abìkù S’olòògùn D’èké ni ìbèèrè 38-40 dá lé. Ta ni ó sö pé, ‘kì í yè qni méje ni çó pa, a ti di méjō’?', null, '["Ráliátù","Sùnmònù","Aríkuyçrí","Àjàdí."]', 0, 'Ráliátù ló sö gbólóhùn yìí.', true, '2026-10-13 13:22:40.109', '2026-10-13 13:22:40.109', null, null, null, 'Ìwé Abìkù S’olòògùn D’èké ni ìbèèrè 38-40 dá lé. Ta ni ó sö pé, ‘kì í yè qni méje ni çó pa, a ti di méjō’?', '["Ráliátù","Sùnmònù","Aríkuyçrí","Àjàdí."]', 'Ráliátù ló sö gbólóhùn yìí.', '{"bold":["Ráliátù"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('485b8fdf-b454-488a-955e-41980118b958', 'General Mathematics', 'JAMB', null, 2026, null, 'If log 2 = x, log 3 = y and log 7 = z, find in terms of x, y and z, the value of log(28/3)', null, '["2x + y - z","2x + z - y","x + y - 2z","x + z - y"]', 1, 'log(28/3) = log 28 - log 3 = log(4×7) - log 3 = 2log2 + log7 - log3 = 2x + z - y.', true, '2026-09-12 11:43:44.216', '2026-09-12 11:43:44.216', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4864721d-3eee-40d2-a923-32c6e731d3f1', 'Physics', 'JAMB', null, 1987, null, 'The direction of the magnetic field at a point in the vicinity of a bar magnet is', null, '["Always towards the north pole of the magnet","Always away from the south pole of the magnet","Along the line joining the point to the neutral point","In the direction the north pole of a compass needle would point."]', 3, 'By definition the field direction at a point is the direction a free north pole (a compass needle''s north end) would point.', true, '2026-10-12 19:15:26.407', '2026-10-12 19:15:26.407', null, null, null, 'The direction of the magnetic field at a point in the vicinity of a bar magnet is', '["Always towards the north pole of the magnet","Always away from the south pole of the magnet","Along the line joining the point to the neutral point","In the direction the north pole of a compass needle would point."]', 'By definition the field direction at a point is the direction a free north pole (a compass needle''s north end) would point.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('48682cce-9781-464f-8c24-1f99031a3ca6', 'English Language', 'JAMB', null, 2007, null, 'A wide range of options <u>------------</u> made available to the political parties during the recently concluded elections.', null, '["was","were","are","is"]', 0, 'Singular ''range'' past â†’ was.', true, '2026-10-24 01:02:14.95', '2026-10-24 01:02:14.95', null, null, null, 'A wide range of options <u>------------</u> made available to the political parties during the recently concluded elections.', '["<u>was</u>","were","are","is"]', 'Singular ''<b>range</b>'' past â†’ <b>was</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('486ac762-bdf1-4094-9f05-cb823be6b020', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Aduma was so vociferous during the meeting of the congregation that he succeeded in incurring the <u>wrath</u> of the chairman.', null, '["anger","admiration","displeasure","sympathy"]', 1, 'Wrath = anger; opposite = admiration.', true, '2026-10-24 07:21:18.616', '2026-10-24 07:21:18.616', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Aduma was so vociferous during the meeting of the congregation that he succeeded in incurring the <u>wrath</u> of the chairman.', '["anger","admiration","displeasure","sympathy"]', 'Wrath = anger; opposite = admiration.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4876b4e8-83b6-4a04-9195-19b55b81c8ab', 'Physics', 'JAMB', null, 1997, null, 'A 5 kg block is released from rest on a smooth plane inclined at an angle of 30° to the horizontal. What is its acceleration down the plane? [g = 10 m s⁻²]', null, '["5.0 m s⁻²","5.8 m s⁻²","8.7 m s⁻²","25.0 m s⁻²"]', 0, 'a = g sin 30° = 10 x 0.5 = 5.0 m s⁻².', true, '2026-10-12 19:15:42.651', '2026-10-12 19:15:42.651', null, null, null, 'A 5 kg block is released from rest on a smooth plane inclined at an angle of 30° to the horizontal. What is its acceleration down the plane? [g = 10 m s<sup>-2</sup>]', '["5.0 m s<sup>-2</sup>","5.8 m s<sup>-2</sup>","8.7 m s<sup>-2</sup>","25.0 m s<sup>-2</sup>"]', 'a = g sin 30° = 10 x 0.5 = 5.0 m s<sup>-2</sup>.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('487f7313-3efd-42a0-ae54-e8a62a218679', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The study he carried out of the problems was quite <u>comprehensive</u>.', null, '["detailed","inscrutable","sketchy","complete"]', 2, 'Comprehensive = detailed; opposite = sketchy.', true, '2026-10-24 07:21:29.12', '2026-10-24 07:21:29.12', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The study he carried out of the problems was quite <u>comprehensive</u>.', '["detailed","inscrutable","sketchy","complete"]', 'Comprehensive = detailed; opposite = sketchy.', '{}');
