insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('48a80009-6cdb-4a08-ba07-e21d7945d538', 'English Language', 'JAMB', null, 2007, null, 'It is high time the government .... action.', null, '["takes","took","has taken","will take"]', 1, '''It is high time'' + past subjunctive ''took''.', true, '2026-10-25 18:25:06.465', '2026-10-25 18:25:06.465', null, null, null, 'It is high time the government .... action.', '["takes","took","has taken","will take"]', '''It is high time'' + past subjunctive ''took''.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('48a94bcf-2255-4fbe-b0dc-8d39b9ab7e37', 'Biology', 'JAMB', null, 2012, null, 'The carrying capacity of a habitat is reached when the population growth begins to', null, '["increase slowly","increase exponentially","slow down","remain steady"]', 3, 'Carrying capacity is reached when population growth remains steady.', true, '2026-10-12 20:59:45.349', '2026-10-12 20:59:45.349', null, null, null, 'The carrying capacity of a habitat is reached when the population growth begins to', '["increase slowly","increase exponentially","slow down","remain steady"]', 'Carrying capacity is reached when population growth remains steady.', '{"bold":["remains steady"],"italic":[],"underline":[],"fillBlanks":[]}');
