insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('48bfd654-5622-48d6-9852-065c6da8bdf9', 'Economics', 'JAMB', null, 2026, null, 'The formula (N + 1) / 2 is used to determine the;', null, '["Mode","Variance","Mean","Median"]', 3, 'The formula (N+1)/2 is used to find the median position.', true, '2026-09-12 11:01:27.961', '2026-09-12 11:01:27.961', null, null, null, null, null, null, null);
