insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('48e8db13-f416-4464-adce-6887bb7ea424', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). After careful investigation, the police found no <u>iota</u> of truth in Ibrahim''s allegations.', null, '["quota","grain","evidence","statement"]', 1, '''No iota of truth'' = no grain of truth.', true, '2026-10-24 01:04:20.131', '2026-10-24 01:04:20.131', null, null, null, '(Choose the most appropriate interpretation). After careful investigation, the police found no <u>iota</u> of truth in Ibrahim''s allegations.', '["quota","<u>grain</u>","evidence","statement"]', '''<b>No iota of truth</b>'' = <b>no grain of truth</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('48fae14e-fd76-40b3-94fb-20086e2df2bd', 'English Language', 'JAMB', null, 2024, null, 'Choose the appropriate STRESS pattern from the options. The SYLLABLES are written in capital letters: meditative', null, '["meDltative","mediTActive","MEditative","meditaTIVE"]', 2, 'The stress in "meditative" is on the first syllable: MEditative.', true, '2026-09-18 09:24:04.803', '2026-09-18 09:24:04.803', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('48fd44e5-a7cc-4b1b-801c-b862e7bd5438', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Moses'' reluctance at his call was primarily due to his', null, '["lack of faith","old age","speech impediment","ignorance of God"]', 2, 'Moses was reluctant because he had a speech impediment (Exodus 4:10).', true, '2026-09-12 10:40:52.963', '2026-09-12 10:40:52.963', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('49098a1a-2134-4ddb-b9ba-7ce66a7146a0', 'Biology', 'JAMB', null, 2005, null, 'An example of a radially symmetrical organism is', null, '["planaria","hydra","tapeworm","roundworm"]', 1, 'Hydra exhibits radial symmetry across its central axis.', true, '2026-10-12 20:05:11.858', '2026-10-12 20:05:11.858', null, null, null, 'An example of a radially symmetrical organism is', '["planaria","hydra","tapeworm","roundworm"]', 'Hydra exhibits radial symmetry across its central axis.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('492569d4-9cc1-4755-90c4-9f796abf7b50', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The village girl wore <u>sumptuous</u> clothes.', null, '["loose-fitting","cheap","faded-looking","expensive"]', 3, 'Sumptuous = expensive/luxurious.', true, '2026-10-24 01:04:02.934', '2026-10-24 01:04:02.934', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The village girl wore <u>sumptuous</u> clothes.', '["loose-fitting","cheap","faded-looking","<u>expensive</u>"]', '<b>Sumptuous</b> = <b>expensive</b>/luxurious.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4925dae6-3cfe-420e-ae97-d479a2a5ea52', 'Literature in English', 'JAMB', null, 2026, null, 'A critic in the literary world is one who', null, '["appreciates and judges literary work","condemns a work of art","writes novels and play","Prose and poetry"]', 0, 'A critic appreciates and judges literary work.', true, '2026-09-12 11:11:03.595', '2026-09-12 11:11:03.595', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('492dc59a-82a2-442c-88de-e9984464d710', 'Government', 'JAMB', null, 2026, null, 'The basic human right of citizens in a state are', null, '["freedom of movement, free education and free health","free social services, speech and religion","right to life, liberty and property","Right to higher education, property and freedom of thought"]', 2, 'Basic human rights include right to life, liberty, and property.', true, '2026-09-12 11:24:32.373', '2026-09-12 11:24:32.373', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('492f0103-b07b-437a-8426-edf98dbea59a', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The principal described Oche as the most <u>tactful</u> person he had ever worked with.', null, '["passionate","discreet","hard-working","innovate"]', 1, 'Tactful = discreet.', true, '2026-10-24 01:04:10.148', '2026-10-24 01:04:10.148', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The principal described Oche as the most <u>tactful</u> person he had ever worked with.', '["passionate","<u>discreet</u>","hard-working","innovate"]', '<b>Tactful</b> = <b>discreet</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('492f469c-68db-4167-a0a0-508f58ce24ff', 'Physics', 'JAMB', null, 2004, null, 'The difference between x-rays and gamma rays is that', null, '["X-rays arise from energy changes in the electronic structure of atoms while gamma rays come from the nucleus.","X-rays are electromagnetic radiations while gamma rays are negatively charged radiations.","X-rays have higher frequencies than gamma rays","X-rays are more penetrating than gamma rays."]', 0, 'X-rays come from electron transitions (or fast electrons stopping), while gamma rays come from changes within the nucleus.', true, '2026-10-12 19:16:00.108', '2026-10-12 19:16:00.108', null, null, null, 'The difference between x-rays and gamma rays is that', '["X-rays arise from energy changes in the electronic structure of atoms while gamma rays come from the nucleus.","X-rays are electromagnetic radiations while gamma rays are negatively charged radiations.","X-rays have higher frequencies than gamma rays","X-rays are more penetrating than gamma rays."]', 'X-rays come from electron transitions (or fast electrons stopping), while gamma rays come from changes within the nucleus.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('493857a7-83d4-4383-9f8e-09bbbf274c5f', 'Physics', 'JAMB', null, 1989, null, 'A block of mass m is held in equilibrium against a vertical wall by a horizontal force. If the coefficient of friction between the block and the wall is μ, the minimum value of the horizontal force is', null, '["μmg","(1 - μ)mg","(1 + μ)mg","mg/μ"]', 3, 'Friction balances weight: μF = mg, so F = mg/μ.', true, '2026-10-12 19:15:28.818', '2026-10-12 19:15:28.818', null, null, null, 'A block of mass m is held in equilibrium against a vertical wall by a horizontal force. If the coefficient of friction between the block and the wall is μ, the minimum value of the horizontal force is', '["μmg","(1 - μ)mg","(1 + μ)mg","mg/μ"]', 'Friction balances weight: μF = mg, so F = mg/μ.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4940c86b-9c2d-46c3-bea2-8c08ee5484a5', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Adigun''s jokes are always <u>puerile</u>.', null, '["entertaining","empty","childish","amusing"]', 2, 'Puerile = childish.', true, '2026-10-24 01:01:51.928', '2026-10-24 01:01:51.928', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Adigun''s jokes are always <u>puerile</u>.', '["entertaining","empty","<u>childish</u>","amusing"]', '<b>Puerile</b> = <b>childish</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('49567057-e338-4f2e-a085-ddc29c76ccdf', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. I have never been accustomed to seeing my brother in such a <u>pensive</u> mood.', null, '["merry","infuriated","thoughtful","hostile"]', 2, 'Pensive = thoughtful.', true, '2026-10-24 01:03:56.879', '2026-10-24 01:03:56.879', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. I have never been accustomed to seeing my brother in such a <u>pensive</u> mood.', '["merry","infuriated","<u>thoughtful</u>","hostile"]', '<b>Pensive</b> = <b>thoughtful</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4959265a-38a1-4f2a-9826-d1e9fd7b743c', 'Hausa', 'JAMB', null, 2009, null, 'Bayan wata uku, ata sake mu. Da muka huta kwana biyu, sai muka yi shirin zuwa kasashen Ris tare da shi, ya zama kuma abokina. Muna cikin tafiya a daji, sai wani mahaukacin rakumi, amale, ya biyo mu baki bud`e. muka sheka wurin wata itaciya muka hau. Shi kuwa, rakumin ya tsaya nan gindin itaciyar yana jira wai sai mun sauko, ya tasam mana. Muka rasa yadda za mu yi tun da safe har azahar, gas hi kuwa cikunanmu suna ta kiran ciorma. Can zuwa la''asar, sai nag a wad`ansu Fulani za su yawon sharo. Da dai na hange su kan hanya, sai na ce, ''Kai masu tafiya, uwaku!'' Ka san bafillace kan bakin rai, daga can kuwa sai suka nufo mu da gudu, wais u ji dalilin da ya san a zage su. Da dai rakumin nan ya kyalla ido ya gan su, bai sake komawa ta kanmu ba, sai ya cce dasu aka gama mu. Kowanne ya ranta, suka yi dawa! Mu kuwa muka sauka, muka yi tamu hanya. Ga mu nan sai Birnin Ris . Zurke na can yana kale-kalle, har nab ace masa. Ka ji rabuwata da shi. Na yi gaba, na shiga jirgi. Na nufi Alkama neman abin da ya rabo ni da gida, watau Ruwan Baganja. Da muka sauka a wani tsibiri don mu huta, sai na tafi yawon shan iska. Jirgi ya tshai, aka bar ni nan ni kad`ai! Bayan sun wuce, na tashi da tafiya, ina neman wani jirgi in bi su. Ina bin bakin teku, sai na tarar da wani mutum a zaune. Na dube shi da kyau, ashe dai Malam Zurke ne dan Muhammad. Da nag a haka sai n ace, ''Zurke d`an Muhammad!'' Sai ya amsa y ace, ''Himma dai d`an Shehu!'' Muka tafa. Y ace ''Wallahi, tun da ka zo na gane ka''. Muka ba juna labarin rabuwarmu. A ina marubucin y ace sun rabu da Malam Zurke?', null, '["Aikama.","Birnin Ris.","Cikin teku.","Wani tsibiri."]', 1, 'A Birnin Ris marubucin ya rabu da Malam Zurke.', true, '2026-10-13 10:37:25.965', '2026-10-13 10:37:25.965', null, null, null, 'Bayan wata uku, ata sake mu. Da muka huta kwana biyu, sai muka yi shirin zuwa kasashen Ris tare da shi, ya zama kuma abokina. Muna cikin tafiya a daji, sai wani mahaukacin rakumi, amale, ya biyo mu baki bud`e. muka sheka wurin wata itaciya muka hau. Shi kuwa, rakumin ya tsaya nan gindin itaciyar yana jira wai sai mun sauko, ya tasam mana. Muka rasa yadda za mu yi tun da safe har azahar, gas hi kuwa cikunanmu suna ta kiran ciorma. Can zuwa la''asar, sai nag a wad`ansu Fulani za su yawon sharo. Da dai na hange su kan hanya, sai na ce, ''Kai masu tafiya, uwaku!'' Ka san bafillace kan bakin rai, daga can kuwa sai suka nufo mu da gudu, wais u ji dalilin da ya san a zage su. Da dai rakumin nan ya kyalla ido ya gan su, bai sake komawa ta kanmu ba, sai ya cce dasu aka gama mu. Kowanne ya ranta, suka yi dawa! Mu kuwa muka sauka, muka yi tamu hanya. Ga mu nan sai Birnin Ris . Zurke na can yana kale-kalle, har nab ace masa. Ka ji rabuwata da shi. Na yi gaba, na shiga jirgi. Na nufi Alkama neman abin da ya rabo ni da gida, watau Ruwan Baganja. Da muka sauka a wani tsibiri don mu huta, sai na tafi yawon shan iska. Jirgi ya tshai, aka bar ni nan ni kad`ai! Bayan sun wuce, na tashi da tafiya, ina neman wani jirgi in bi su. Ina bin bakin teku, sai na tarar da wani mutum a zaune. Na dube shi da kyau, ashe dai Malam Zurke ne dan Muhammad. Da nag a haka sai n ace, ''Zurke d`an Muhammad!'' Sai ya amsa y ace, ''Himma dai d`an Shehu!'' Muka tafa. Y ace ''Wallahi, tun da ka zo na gane ka''. Muka ba juna labarin rabuwarmu. A ina marubucin y ace sun rabu da Malam Zurke?', '["Aikama.","Birnin Ris.","Cikin teku.","Wani tsibiri."]', 'A Birnin Ris marubucin ya rabu da Malam Zurke.', '{"bold":["Birnin Ris"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('495945e1-78d8-4787-8e1e-9745f72ce01d', 'Biology', 'JAMB', null, 2026, null, 'Which of the following insects undergoes incomplete metamorphosis?', null, '["housefly","termite","mosquito","moth"]', 1, 'Termites undergo incomplete metamorphosis (egg -> nymph -> adult), while houseflies, mosquitoes, and moths have complete metamorphosis.', true, '2026-09-09 02:56:42.857', '2026-09-09 02:56:42.857', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('495c1579-6ba5-4541-bbb2-acadb35f20e3', 'English Language', 'JAMB', null, 2007, null, 'Knowledge of figures of speech as well as of idioms and lexical items <u>-----</u> in this section.', null, '["is tested","have been tested","are tested","were tested"]', 0, '''As well as'' does not change singular ''Knowledge''.', true, '2026-10-24 01:04:26.3', '2026-10-24 01:04:26.3', null, null, null, 'Knowledge of figures of speech as well as of idioms and lexical items <u>-----</u> in this section.', '["<u>is tested</u>","have been tested","are tested","were tested"]', '''<b>As well as</b>'' does not change singular ''<b>Knowledge</b>''.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('495f55ca-9d8a-4f55-ad9a-a9180d0cdd7a', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Which is among the fruit of the Spirit in Galatians 5:22-23?', null, '["tongues and prophecy","miracles","joy and love","righteousness"]', 2, 'The fruit of the Spirit listed in Galatians 5:22-23 includes love, joy, peace, patience, kindness, goodness, faithfulness, gentleness, and self-control. Joy and love are part of this list. Tongues, prophecy, and miracles are gifts of the Spirit, not fruit of the Spirit.', true, '2026-09-12 09:45:49.036', '2026-09-12 09:45:49.036', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('496da5e4-b986-432e-9c03-84682fc4a229', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. My niece has <u>an unquenchable</u> thirst for adventure stories', null, '["a spurious","an illegitimate","a reduced","an inextinguishable"]', 2, 'Unquenchable = cannot be satisfied; opposite = reduced.', true, '2026-10-24 07:21:31.787', '2026-10-24 07:21:31.787', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. My niece has <u>an unquenchable</u> thirst for adventure stories', '["a spurious","an illegitimate","a reduced","an inextinguishable"]', 'Unquenchable = cannot be satisfied; opposite = reduced.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('497271ea-047c-4c46-97eb-e4366fd6fa5c', 'Biology', 'JAMB', null, 2026, null, 'Blood grouping in human beings is derived from the combination of', null, '["two different alleles","four different alleles","three different alleles","two different alleles"]', 2, 'Blood grouping in human beings is derived from the combination of three different alleles of the ABO gene: Iᴬ, Iᴮ, and i. These three alleles produce four blood groups: A (IᴬIᴬ or Iᴬi), B (IᴮIᴮ or Iᴮi), AB (IᴬIᴮ), and O (ii). The presence of three alleles (multiple alleles) at a single gene locus determines blood type. This is an example of multiple allelism, where more than two alleles exist in the population.', true, '2026-09-09 03:19:11.829', '2026-09-09 03:19:11.829', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('49735962-906b-4d66-af07-5068989e7a17', 'Literature in English', 'JAMB', null, 2026, null, 'What is the approximate age of the celebrant in the poem?', null, '["fifty-five","five and eighty","eighty-five","ninety-five"]', 2, 'The celebrant is approximately eighty-five.', true, '2026-09-12 11:10:43.976', '2026-09-12 11:10:43.976', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4976f648-d365-4d8a-b486-06a1271b686c', 'Christian Religious Studies', 'JAMB', null, 2026, null, '“Let there be light: and there was light” This statement reveals God’s...', null, '["Graciousness","Sovereignty","Omnipotence","Omnipresence"]', 2, 'God creating light purely through spoken word in Genesis 1:3 demonstrates His supreme power over all creation (Omnipotence).', true, '2026-09-09 17:18:24.654', '2026-09-09 17:18:24.654', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('49788b06-1277-4e41-bf48-fdddf43cef98', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Mark’s Gospel starts with...', null, '["The story of the birth of Jesus","The story of Simon Peter","The story of John the Baptist","The story of the temptation of Jesus"]', 2, 'Mark 1:1-4 begins immediately with John the Baptist preaching a baptism of repentance in the wilderness.', true, '2026-09-09 17:18:28.202', '2026-09-09 17:18:28.202', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('497b04d0-57be-4123-9545-dbaa2b4c7d93', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Tortoises need cool climates and must have places where they can <u>hibernate</u>.', null, '["sleep deeply","relax","reproduce","hide at night"]', 0, 'Hibernate = sleep deeply.', true, '2026-10-24 01:04:03.599', '2026-10-24 01:04:03.599', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Tortoises need cool climates and must have places where they can <u>hibernate</u>.', '["<u>sleep deeply</u>","relax","reproduce","hide at night"]', '<b>Hibernate</b> = <b>sleep deeply</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('497db639-3bab-4449-8e89-9c6a38b7bd6c', 'English Language', 'JAMB', null, 2024, null, '"Rough" in the first sentence of the passage means', null, '["mountains and molehills","the dangers attributed to space travel","challenges that will breed opportunities","difficulties"]', 3, '"May your road be rough" means may you face difficulties and challenges.', true, '2026-09-18 10:16:10.269', '2026-09-18 10:16:10.269', '11a7b560-dd3b-4c82-b5ad-fe71fdd120ed', 5, 'COMPREHENSION', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('49a6ac72-7859-4543-922f-b609affbd3f3', 'Government', 'JAMB', null, 2026, null, 'The primary function of a legislature (or the National Assembly) is the', null, '["appointment of the president","making of laws","vetoing of bills","monitoring of the judiciary","re-assignment of civil servants"]', 1, 'The primary function of a legislature (or the National Assembly) is the making of laws. The legislature is the law-making arm of government. It debates and passes bills into law, represents the people, approves the budget, and oversees the executive. While it also vetoes bills (executive), monitors the judiciary, and performs other functions, law-making is its primary and defining function.', true, '2026-09-10 10:45:06.784', '2026-09-10 10:45:06.784', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('49aaf372-e97f-4662-8d68-420fd3041aab', 'English Language', 'JAMB', null, 2007, null, 'The chief priest will <u>__________</u> the men into the cult today.', null, '["indoctrinate","usher","convert","initiate"]', 3, 'Correct spelling: initiate.', true, '2026-10-24 07:21:42.711', '2026-10-24 07:21:42.711', null, null, null, 'The chief priest will <u>__________</u> the men into the cult today.', '["indoctrinate","usher","convert","initiate"]', 'Correct spelling: initiate.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('49adf3d3-3551-4d62-bf78-306da2c75412', 'Christian Religious Studies', 'JAMB', null, 2026, null, '“…For if this plan or undertaking is of man, it will fail; but if it is of God, you will not be able to overthrow them…” Gamaliel’s statement referred to...', null, '["Peter and John","Peter and the apostles","Paul and Timothy","Paul and Silas"]', 1, 'Acts 5:34-39 records Gamaliel giving this advice to the Sanhedrin council regarding Peter and the rest of the arrested apostles.', true, '2026-09-09 17:18:25.636', '2026-09-09 17:18:25.636', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('49bde8ad-a0a6-4aea-9a4d-4964b8e3689f', 'Literature in English', 'JAMB', null, 2026, null, 'What is Dress Rehearsal?', null, '["A final rehearsal in full costume before the actual performance","A rehearsal without costumes","A rehearsal for the crew only","A rehearsal of the script only"]', 0, 'A dress rehearsal is a final rehearsal in full costume before the actual performance. It is the last opportunity for the cast and crew to run through the entire production with all elements—costumes, props, lighting, sound, and set changes—as they will be in the actual performance. It is not without costumes or for crew only.', true, '2026-09-10 10:47:55.395', '2026-09-10 10:47:55.395', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('49c9577b-5ca9-4e74-8ac9-5618b77b2d36', 'Economics', 'JAMB', null, 2026, null, '______ refers to minimum prices by the law, below which a particular good or service cannot be sold.', null, '["Minimum price legislation","Maximum price legislation","Price ceiling","none of the above"]', 0, 'Minimum price legislation sets a floor price below which a good cannot be sold.', true, '2026-09-12 11:00:53.196', '2026-09-12 11:00:53.196', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('49c9ba07-999a-478b-acea-a5d1850714f7', 'English Language', 'JAMB', null, 2024, null, 'Invariably, he ends his letters ______ amicably', null, '["You","your''s","yours''","Yours","your own"]', 3, '"Yours" is the correct possessive pronoun used to end a letter.', true, '2026-09-18 09:24:04.681', '2026-09-18 09:24:04.681', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('49f7e028-7ac6-4c39-9abe-883e5ac426d7', 'Christian Religious Studies', 'JAMB', null, 2026, null, '“…as I was with Moses, so I will be with you, I will not fail you or forsake you…” In this passage, God addresses...', null, '["the spies","Joshua","Aaron","Gideon"]', 1, 'Joshua 1:5 records God''s promise to Joshua upon commissioning him to lead Israel into Canaan after Moses'' death.', true, '2026-09-09 17:18:26.129', '2026-09-09 17:18:26.129', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('49f7f0c3-ca42-496b-ba85-61eba1481e9a', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Orinya balances the pail on her head with <u>accustomed</u> ease.', null, '["convincing","surprising","unwary","unusual"]', 3, 'Accustomed = habitual; opposite = unusual.', true, '2026-10-24 07:21:20.603', '2026-10-24 07:21:20.603', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Orinya balances the pail on her head with <u>accustomed</u> ease.', '["convincing","surprising","unwary","unusual"]', 'Accustomed = habitual; opposite = unusual.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('49f87a60-bcea-4221-b2ab-555ed7c7d91b', 'Literature in English', 'JAMB', null, 2026, null, 'What prompts Cleopatra to test the loyalty of Mark Antony?', null, '["A prophecy from the oracle","Antony''s marriage to Octavia","A letter from Rome","A rumour of war"]', 1, 'Cleopatra tests Antony''s loyalty after his marriage to Octavia.', true, '2026-09-12 11:09:49.472', '2026-09-12 11:09:49.472', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('49f8b804-42e8-4d6e-a535-733f0c4aac97', 'Physics', 'JAMB', null, 1988, null, 'A cell of internal resistance 2 ohms supplies current to a 6-ohm resistor. The efficiency of the cell is', null, '["12.0 %","25.0 %","33.3 %","75.0 %"]', 3, 'Efficiency = R/(R + r) = 6/(6 + 2) = 0.75 = 75 %.', true, '2026-10-12 19:15:28.172', '2026-10-12 19:15:28.172', null, null, null, 'A cell of internal resistance 2 ohms supplies current to a 6-ohm resistor. The efficiency of the cell is', '["12.0 %","25.0 %","33.3 %","75.0 %"]', 'Efficiency = R/(R + r) = 6/(6 + 2) = 0.75 = 75 %.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('49fe41f7-bf97-4afa-9ad7-9a44f1e133f8', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). Jummai''s father remarked that <u>pigs would fly</u> before she passed', null, '["It would be possible to pass only if she worked harder","It would never be possible for her to pass","He would have to bribe her teachers to enable her to pass","She would have to cheat in order to pass"]', 1, '''Pigs would fly'' = never happen.', true, '2026-10-24 01:04:24.854', '2026-10-24 01:04:24.854', null, null, null, '(Choose the most appropriate interpretation). Jummai''s father remarked that <u>pigs would fly</u> before she passed', '["It would be possible to pass only if she worked harder","<u>It would never be possible for her to pass</u>","He would have to bribe her teachers to enable her to pass","She would have to cheat in order to pass"]', '''<b>Pigs would fly</b>'' = <b>never happen</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('49ff4171-711e-42f5-8f83-f6ba7e1b5393', 'Physics', 'JAMB', null, 1994, null, 'An object is projected with a velocity of 80 m s⁻¹ at an angle of 30° to the horizontal. The maximum height reached is', null, '["20 m","80 m","160 m","320 m"]', 1, 'H = (u sin θ)²/2g = (80 sin 30°)²/(2 x 10) = 40²/20 = 80 m.', true, '2026-10-12 19:15:38.835', '2026-10-12 19:15:38.835', null, null, null, 'An object is projected with a velocity of 80 m s<sup>-1</sup> at an angle of 30° to the horizontal. The maximum height reached is', '["20 m","80 m","160 m","320 m"]', 'H = (u sin θ)<sup>2</sup>/2g = (80 sin 30°)<sup>2</sup>/(2 x 10) = 40<sup>2</sup>/20 = 80 m.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('49ffdb63-e249-4714-8ae2-74ef7397f356', 'Chemistry', 'JAMB', null, 2026, null, '__________ can be used to test for reducing sugars:', null, '["Iodine solution","bromine water","Fehling’s solution","de-ionized water"]', 2, 'Fehling''s solution contains Cu2+ ions that reduce to a brick-red precipitate of copper(I) oxide (Cu2O) in the presence of reducing sugars.', true, '2026-09-09 17:12:46.897', '2026-09-09 17:12:46.897', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4a046777-8394-4316-85e8-04fd9109b9ed', 'English Language', 'JAMB', null, 2007, null, 'I was seriously disappointed when the <u>__________</u> between the two teams ended in a goalless draw.', null, '["march","marsh","match","mash","martch"]', 2, 'Correct spelling: match.', true, '2026-10-24 07:21:32.139', '2026-10-24 07:21:32.139', null, null, null, 'I was seriously disappointed when the <u>__________</u> between the two teams ended in a goalless draw.', '["march","marsh","match","mash","martch"]', 'Correct spelling: match.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4a05f0ea-e3e3-4d9c-8741-17d000d40c5d', 'Biology', 'JAMB', null, 2026, null, 'What is the phenotype ratio in question 11?', null, '["1:2:1 (homozygous dominant : heterozygous : homozygous recessive)","3:1 (dominant : recessive)","1:1 (dominant : recessive)","9:3:3:1 (dihybrid ratio)"]', 1, 'The phenotype ratio in the F2 generation is 3:1 (three showing the dominant trait to one showing the recessive trait). This applies to a monohybrid cross with complete dominance. For example, in a cross of Tt × Tt, the offspring phenotypes are 3 tall : 1 dwarf. This 3:1 ratio is the classic Mendelian phenotype ratio for the F2 generation of a monohybrid cross. The 1:2:1 ratio is the genotype ratio, not the phenotype ratio. The 1:1 ratio would appear in a test cross (Tt × tt).', true, '2026-09-09 03:20:41.203', '2026-09-09 03:20:41.203', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4a06cff6-0db9-4f94-81f2-47272dec3cd1', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. I shall be with you <u>presently</u>.', null, '["now","in a moment","at present","for the time being"]', 1, 'Presently = in a moment.', true, '2026-10-24 01:03:56.451', '2026-10-24 01:03:56.451', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. I shall be with you <u>presently</u>.', '["now","<u>in a moment</u>","at present","for the time being"]', '<b>Presently</b> = <b>in a moment</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4a08d48c-04ef-4ad5-9b34-9e44b215b148', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Adigun''s jokes are always <u>puerile</u>.', null, '["entertaining","empty","childish","amusing"]', 2, 'Puerile = childish.', true, '2026-10-24 01:04:04.241', '2026-10-24 01:04:04.241', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Adigun''s jokes are always <u>puerile</u>.', '["entertaining","empty","<u>childish</u>","amusing"]', '<b>Puerile</b> = <b>childish</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4a19f5c2-4b6a-4bac-bb1a-2cbf412ed073', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The Chief approached the issue with convincing <u>disinterestedness</u>.', null, '["lack of interest","lack of personal interest","inability to be interested","unwillingness"]', 1, 'Disinterestedness = impartiality.', true, '2026-10-24 01:01:43.19', '2026-10-24 01:01:43.19', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The Chief approached the issue with convincing <u>disinterestedness</u>.', '["lack of interest","<u>lack of personal interest</u>","inability to be interested","unwillingness"]', '<b>Disinterestedness</b> = <b>impartiality</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4a226cf3-7360-4cce-9906-0f58b68480b2', 'Financial Accounting', 'UTME', null, 2003, null, 'Which of the following is used to update the cash book in bank reconciliation?', null, '["Interest received and unrepresented cheques","Commission and debit note","Unpresented cheques and direct credit","Interest received and direct credit"]', 3, 'Interest received and direct credit are found in the bank''s statement when received. It is then that the cash book would be updated.', true, '2026-10-12 21:59:59.19', '2026-10-12 21:59:59.19', null, null, null, 'Which of the following is used to update the cash book in bank reconciliation?', '["Interest received and unrepresented cheques","Commission and debit note","Unpresented cheques and direct credit","<b>Interest received and direct credit</b>"]', '<b>Interest received and direct credit</b> are found in the bank''s statement when received. It is then that the cash book would be updated.', '{"bold":["Interest received and direct credit"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4a2657c7-2726-4cf6-94cf-b2342e8a8707', 'Physics', 'JAMB', null, 1990, null, '40 cm³ of liquid P is mixed with 60 cm³ of another liquid Q. If the densities of P and Q are 1.00 g cm⁻³ and 1.6 g cm⁻³ respectively, what is the density of the mixture?', null, '["0.05 g cm⁻³","1.25 g cm⁻³","1.30 g cm⁻³","1.36 g cm⁻³"]', 3, 'Total mass = 40 x 1.00 + 60 x 1.6 = 136 g in 100 cm³, so the density is 1.36 g cm⁻³.', true, '2026-10-12 19:15:30.767', '2026-10-12 19:15:30.767', null, null, null, '40 cm<sup>3</sup> of liquid P is mixed with 60 cm<sup>3</sup> of another liquid Q. If the densities of P and Q are 1.00 g cm<sup>-3</sup> and 1.6 g cm<sup>-3</sup> respectively, what is the density of the mixture?', '["0.05 g cm<sup>-3</sup>","1.25 g cm<sup>-3</sup>","1.30 g cm<sup>-3</sup>","1.36 g cm<sup>-3</sup>"]', 'Total mass = 40 x 1.00 + 60 x 1.6 = 136 g in 100 cm<sup>3</sup>, so the density is 1.36 g cm<sup>-3</sup>.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4a31f5a2-ff62-414b-afb0-882f291abb33', 'Physics', 'JAMB', null, 2026, null, 'When impurities are added to a semiconductor, the conductivity of the semiconductor will', null, '["increase","decrease","remain constant","increase then decrease"]', 0, 'When impurities (dopants) are added to a semiconductor, the conductivity increases. This process is called doping. Adding pentavalent (n-type) or trivalent (p-type) impurities increases the number of free charge carriers (electrons or holes), thereby increasing conductivity.', true, '2026-09-10 10:56:40.054', '2026-09-10 10:56:40.054', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4a4f79cd-89e6-49cf-beba-8c51c80d1e44', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). The boss <u>made a clean sweep</u> of all the old hands in the office.', null, '["completely got rid","cleanly swept the office","made a quick change","made an adjustment"]', 0, '''A clean sweep'' = complete removal.', true, '2026-10-24 01:02:05.535', '2026-10-24 01:02:05.535', null, null, null, '(Choose the most appropriate interpretation). The boss <u>made a clean sweep</u> of all the old hands in the office.', '["<u>completely got rid</u>","cleanly swept the office","made a quick change","made an adjustment"]', '''A <b>clean sweep</b>'' = <b>complete removal</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4a51b8b3-a69e-4610-9cf7-adfd89f8d45f', 'Physics', 'JAMB', null, 2026, null, 'Two 50μF parallel plate capacitors are connected in series. The combined capacitor is then connected across 100V battery. The charge on each plate of the capacitor is', null, '["0.00005C","0.0025C","0.00125C","0.01C"]', 1, 'For capacitors in series: 1/C = 1/50 + 1/50 = 2/50 = 1/25. C = 25μF. Q = CV = 25×10⁻⁶ × 100 = 2.5×10⁻³ = 0.0025C.', true, '2026-09-10 10:56:47.142', '2026-09-10 10:56:47.142', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4a56db28-88aa-4cbe-a7ee-0c150abef388', 'Literature in English', 'JAMB', null, 2026, null, 'The phrase ''laugh with my teeth'' is a powerful symbol of', null, '["glee and merriment","insincerity and pretense","anger and aggression","childish joy"]', 1, 'The phrase ''laugh with my teeth'' is a powerful symbol of insincerity and pretense. It suggests laughing outwardly without genuine feeling—a hollow, forced laugh. The phrase indicates that the laughter is superficial, not from the heart. It is not about glee, anger, or childish joy. The symbol highlights the theme of hypocrisy and false appearances in the poem.', true, '2026-09-10 10:45:35.045', '2026-09-10 10:45:35.045', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4a5b34f4-bffa-417c-9bef-c511c9874757', 'Literature in English', 'JAMB', null, 2026, null, 'Where are the characters?', null, '["Alexandria, a room in Cleopatra''s palace","in Rome","on the street","none of the above"]', 0, 'The characters are in Alexandria, a room in Cleopatra''s palace.', true, '2026-09-12 11:11:28.25', '2026-09-12 11:11:28.25', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4a60e720-7c2e-46fc-898f-139a411ffb38', 'Government', 'JAMB', null, 2026, null, 'The ECOWAS Treaty was reviewed in 1991 to', null, '["make it responsive to new challenge","accommodate the interest of France","mobilize ECOMOG","accommodate extra sub-regional interest"]', 0, 'The ECOWAS Treaty was reviewed in 1991 to make it responsive to new challenges.', true, '2026-09-12 11:24:42.261', '2026-09-12 11:24:42.261', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4a7406d6-6202-42f0-b730-5dd817ff6070', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). When he found himself in a difficult situation, he tried to <u>double-talk his way through</u>.', null, '["talk to two people to help him","mix up facts to sound nervous","mix up facts to confuse people","talk twice to gain sympathy"]', 2, '''Double-talk'' = deliberately confusing speech.', true, '2026-10-24 01:04:22.331', '2026-10-24 01:04:22.331', null, null, null, '(Choose the most appropriate interpretation). When he found himself in a difficult situation, he tried to <u>double-talk his way through</u>.', '["talk to two people to help him","mix up facts to sound nervous","<u>mix up facts to confuse people</u>","talk twice to gain sympathy"]', '''<b>Double-talk</b>'' = <b>deliberately confusing speech</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4a977c5b-2bf4-4e2a-a749-1fe4a1f78d8e', 'Biology', 'JAMB', null, 2001, null, 'Water fleas, wood lice and barnacles belong to the group', null, '["insecta","chilopoda","crustacea","arachnida"]', 2, 'Water fleas, wood lice, and barnacles are all crustaceans.', true, '2026-10-12 20:59:27.706', '2026-10-12 20:59:27.706', null, null, null, 'Water fleas, wood lice and barnacles belong to the group', '["insecta","chilopoda","crustacea","arachnida"]', 'Water fleas, wood lice, and barnacles are all crustaceans.', '{"bold":["crustaceans"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4a988df9-44a7-47b0-bdcb-a8576a9f4a22', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The hefty warder came in and all the prisoners <u>snuffed</u> out their cigarettes.', null, '["extinguished","put out","squeezed","put down"]', 0, 'Snuffed out = extinguished.', true, '2026-10-24 01:01:43.678', '2026-10-24 01:01:43.678', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The hefty warder came in and all the prisoners <u>snuffed</u> out their cigarettes.', '["<u>extinguished</u>","put out","squeezed","put down"]', '<b>Snuffed out</b> = <b>extinguished</b>.', '{}');
