insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4ab21309-c534-4092-a82a-af66d5164d3f', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'God called Jonah and sent him to the people of Nineveh to', null, '["Pray to Him for their forgiveness","Pray for their repentance","Preach His word to them","cry against their wickedness"]', 3, 'God sent Jonah to cry against Nineveh''s wickedness.', true, '2026-09-12 10:41:56.883', '2026-09-12 10:41:56.883', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4abac927-9721-4eed-8a6a-adc4426eb53c', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. We have to identify the <u>protagonists</u> of the new movement.', null, '["enemies","leading figures","opponents","believers"]', 1, 'Protagonists = leading figures.', true, '2026-10-24 01:03:55.274', '2026-10-24 01:03:55.274', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. We have to identify the <u>protagonists</u> of the new movement.', '["enemies","<u>leading figures</u>","opponents","believers"]', '<b>Protagonists</b> = <b>leading figures</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4abd7c1b-52ed-40f3-a646-f1d1329875b6', 'Literature in English', 'JAMB', null, 2026, null, 'The phrase ''Beat him soft like clay'' is an example of', null, '["simile","Metaphor","Personification","Hyperbole"]', 0, 'It is a simile.', true, '2026-09-12 11:13:55.876', '2026-09-12 11:13:55.876', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4ac47939-e862-4bea-b5dd-95be9bae4a42', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The tax rebate was a <u>concession</u> given to servants.', null, '["an incentive","an allowance","work","intelligence"]', 1, 'Concession = an allowance.', true, '2026-10-24 01:01:56.492', '2026-10-24 01:01:56.492', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The tax rebate was a <u>concession</u> given to servants.', '["an incentive","<u>an allowance</u>","work","intelligence"]', '<b>Concession</b> = <b>an allowance</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4ae06ad4-1be4-4903-8d4f-aaf0a15e6dfa', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'In his teaching on partiality, James declares that mercy triumphs over', null, '["judgement","righteousness","grace","faith"]', 0, 'James says mercy triumphs over judgement.', true, '2026-09-12 10:41:21.943', '2026-09-12 10:41:21.943', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4af4a446-5d5f-4de0-b158-51a78f80b00b', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation).) Olu promised to <u>look out for</u> her next time he is in town.', null, '["watch for","visit","greet","take care of"]', 3, '''Look out for'' = take care of.', true, '2026-10-24 01:02:02.75', '2026-10-24 01:02:02.75', null, null, null, '(Choose the most appropriate interpretation).) Olu promised to <u>look out for</u> her next time he is in town.', '["watch for","visit","greet","<u>take care of</u>"]', '''<b>Look out for</b>'' = <b>take care of</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4b025ebd-ef23-45b6-b12e-682d6190f699', 'English Language', 'JAMB', null, 2007, null, 'The team has benefited from the coach''s <u>__________</u> of experience', null, '["reservoir","wealth","minefield","world"]', 1, 'Correct collocation: wealth of experience.', true, '2026-10-24 07:21:39.872', '2026-10-24 07:21:39.872', null, null, null, 'The team has benefited from the coach''s <u>__________</u> of experience', '["reservoir","wealth","minefield","world"]', 'Correct collocation: wealth of experience.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4b1799e5-8b26-474f-b901-d443278eafab', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Ali wondered why the principal was <u>ambivalent</u> about the students'' future.', null, '["inconsiderate","decisive","anxious","ambitious"]', 1, 'Ambivalent = undecided; opposite = decisive.', true, '2026-10-24 07:21:22.607', '2026-10-24 07:21:22.607', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Ali wondered why the principal was <u>ambivalent</u> about the students'' future.', '["inconsiderate","decisive","anxious","ambitious"]', 'Ambivalent = undecided; opposite = decisive.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4b1fe4fa-43a4-483e-86e5-438b532332e7', 'Literature in English', 'JAMB', null, 2026, null, 'The clash of interest that originates from opposing forces in literature is', null, '["Climax","Denouement","Conflict","Aside"]', 2, 'It is conflict.', true, '2026-09-12 11:11:07.165', '2026-09-12 11:11:07.165', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4b2b48f7-8631-45aa-b46c-bda2cf32b469', 'Financial Accounting', 'UTME', null, 2003, null, 'A company has departments M and N. The expenses incurred wholly in M is N5 000. General expenses incurred amount to N25 000. Expenses are apportioned in the ratio 2:3 for departments M and N respectively. What is N''s share of the expenses?', null, '["N10.000","N15 000","N18 000","N20 000"]', 1, 'General Expenses: 25,000 to be shared in ratio 2:3 between M and N = 10:15. Therefore, N''s share of the expenses is 15,000.', true, '2026-10-12 22:00:00.767', '2026-10-12 22:00:00.767', null, null, null, 'A company has departments M and N. The expenses incurred wholly in M is N5 000. General expenses incurred amount to N25 000. Expenses are apportioned in the ratio 2:3 for departments M and N respectively. What is N''s share of the expenses?', '["N10.000","<b>N15 000</b>","N18 000","N20 000"]', 'General Expenses: 25,000 to be shared in ratio 2:3 between M and N = 10:15. Therefore, N''s share of the expenses is <b>15,000</b>.', '{"bold":["15,000"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4b2efba5-0559-4ae2-88ec-88bd66abaa28', 'General Mathematics', 'JAMB', null, 2026, null, 'If sin x equals cosine x, what is x in radians', null, '["π/2","π/3","π/4","π/6","π/12"]', 2, 'sin x = cos x → tan x = 1 → x = π/4.', true, '2026-09-12 11:44:21.333', '2026-09-12 11:44:21.333', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4b3e93ba-4563-4b34-ae3d-267773e61dc4', 'English Language', 'JAMB', null, 2007, null, 'Every programming language and software package <u>--------------</u> limitations.', null, '["have its","have their","has its","has their"]', 2, '''Everyâ€¦'' singular â†’ has its.', true, '2026-10-24 01:02:13.162', '2026-10-24 01:02:13.162', null, null, null, 'Every programming language and software package <u>--------------</u> limitations.', '["have its","have their","<u>has its</u>","has their"]', '''<b>Everyâ€¦</b>'' singular â†’ <b>has its</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4b4186ef-cc5e-4710-82b2-5e3a8b52a316', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The <u>ingenious</u> scheme of the robber broke down because of the efficiency of the police officer. Ingenious here means __________________', null, '["suspicious","ambitious","deceitful","clever","stupid"]', 3, 'Ingenious = cleverly devised.', true, '2026-10-24 01:01:40.193', '2026-10-24 01:01:40.193', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The <u>ingenious</u> scheme of the robber broke down because of the efficiency of the police officer. Ingenious here means __________________', '["suspicious","ambitious","deceitful","<u>clever</u>","stupid"]', '<b>Ingenious</b> = <b>cleverly devised</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4b425eb1-5c56-427b-b5cc-b7e4da378125', 'Physics', 'JAMB', null, 1994, null, 'The fundamental frequency of vibration of a sonometer wire may be halved by', null, '["Doubling the length of the wire","Doubling the mass of the wire","Reducing the tension by half","Reducing the absolute temperature by half."]', 0, 'f = (1/2L)√(T/μ), so f is inversely proportional to length. Doubling the length halves the frequency.', true, '2026-10-12 19:15:39.75', '2026-10-12 19:15:39.75', null, null, null, 'The fundamental frequency of vibration of a sonometer wire may be halved by', '["Doubling the length of the wire","Doubling the mass of the wire","Reducing the tension by half","Reducing the absolute temperature by half."]', 'f = (1/2L)√(T/μ), so f is inversely proportional to length. Doubling the length halves the frequency.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4b52a2b4-fb4e-4cf6-a79f-9797b9fd0635', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). The team''s poor performance at the tournament <u>plumbs the depths of horror</u>.', null, '["The team''s performance took them to the next round.","The team''s performance was enjoyed by all.","The team''s performance was full of disappointment.","The team''s performance was rewarded."]', 2, '''Plumbs the depths of horror'' = full of disappointment.', true, '2026-10-24 01:04:23.08', '2026-10-24 01:04:23.08', null, null, null, '(Choose the most appropriate interpretation). The team''s poor performance at the tournament <u>plumbs the depths of horror</u>.', '["The team''s performance took them to the next round.","The team''s performance was enjoyed by all.","<u>The team''s performance was full of disappointment.</u>","The team''s performance was rewarded."]', '''<b>Plumbs the depths of horror</b>'' = <b>full of disappointment</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4b535a18-15e3-4796-b974-5e3bbad24eb3', 'Economics', 'JAMB', null, 2026, null, 'Given a consumption function C = 10 + 0.6Y, determine the value of C if Y is 200', null, '["130","210","120","240"]', 0, 'C = 10 + 0.6(200) = 10 + 120 = 130.', true, '2026-09-12 10:58:47.954', '2026-09-12 10:58:47.954', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4b5a9bc0-c638-44ad-9809-53ffae4f28b5', 'Government', 'JAMB', null, 2026, null, 'The option A4 model was used in the conduct of the', null, '["1999 elections","2007 elections","1983 elections","1993 elections"]', 3, 'The option A4 model was used in the conduct of the 1993 elections. The Option A4 model was introduced by the National Electoral Commission (NEC) for the 1993 presidential election. Under this system, voters queued behind the picture or symbol of their preferred candidate. It was a form of open ballot voting. The election was won by Moshood Abiola but was annulled by the military government. This model was used only in the 1993 elections.', true, '2026-09-10 10:44:19.04', '2026-09-10 10:44:19.04', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4b603e6f-87a7-4428-85bd-afb24a2341cb', 'Biology', 'JAMB', null, 2026, null, 'Which of the following characters is not sex linked?', null, '["river blindness","baldness","haemophilia","colour blindness"]', 0, 'River blindness (onchocerciasis) is not sex-linked; it is an infectious disease caused by a parasitic worm, not a genetic trait. Baldness can be sex-influenced but is not strictly sex-linked, meaning it can be influenced by sex hormones but is not on the sex chromosomes. Haemophilia and colour blindness are classic X-linked recessive disorders. River blindness is caused by infection with Onchocerca volvulus transmitted by blackflies and is not inherited.', true, '2026-09-09 03:19:17.907', '2026-09-09 03:19:17.907', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4b65208c-dbf2-45b3-8720-fd5c1097487b', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. I think I''ll like to <u>reiterate</u> the points earlier made.', null, '["withdraw","change","challenge","repeat"]', 3, 'Reiterate = repeat.', true, '2026-10-24 01:03:55.914', '2026-10-24 01:03:55.914', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. I think I''ll like to <u>reiterate</u> the points earlier made.', '["withdraw","change","challenge","<u>repeat</u>"]', '<b>Reiterate</b> = <b>repeat</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4b6db990-87b6-485f-8b45-0cf23ee31cc4', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'God''s anger was kindled against Eli and his children because Eli did not', null, '["train his children against sin","warn his children against sin","apply appropriate sanctions on his children when due","know the gravity of their actions"]', 2, 'Eli did not restrain his sons, honoring them above God.', true, '2026-09-12 10:41:40.418', '2026-09-12 10:41:40.418', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4b80b35b-2238-4dd1-850f-046b101f6190', 'Financial Accounting', 'UTME', null, 2001, null, 'Bala Ltd acquired the business of Bello Ltd and caused the separate existence of the latter company to terminate. This situation is best described as', null, '["absorption","merger","conversion","dissolution"]', 0, 'This situation is best described as absorption.', true, '2026-10-12 22:00:07.253', '2026-10-12 22:00:07.253', null, null, null, 'Bala Ltd acquired the business of Bello Ltd and caused the separate existence of the latter company to terminate. This situation is best described as', '["<b>absorption</b>","merger","conversion","dissolution"]', 'This situation is best described as <b>absorption</b>.', '{"bold":["absorption"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4b86bd04-d0c1-438e-83a8-692a572471da', 'Literature in English', 'JAMB', null, 2026, null, 'Those you have loved and respected mock you to your face illustrates', null, '["Hyperbole","Irony","Oxymoron","Paradox"]', 1, 'It illustrates irony.', true, '2026-09-12 11:11:05.877', '2026-09-12 11:11:05.877', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4b8f13f4-21ea-4842-b2d2-858207cf6fd7', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). The manager often quarrels with his staff because he goes around with <u>a chip on his shoulder</u>.', null, '["deformed shoulder","readiness to be angered","look of contempt","an air of superiority","search for gossip"]', 1, '''A chip on one''s shoulder'' = readiness to take offence.', true, '2026-10-24 01:04:15.487', '2026-10-24 01:04:15.487', null, null, null, '(Choose the most appropriate interpretation). The manager often quarrels with his staff because he goes around with <u>a chip on his shoulder</u>.', '["deformed shoulder","<u>readiness to be angered</u>","look of contempt","an air of superiority","search for gossip"]', '''A <b>chip on one''s shoulder</b>'' = <b>readiness to take offence</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4b991e33-96dc-4b07-ba3b-f7f1edf0ca38', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Paul declares that Christians have the same functions, but they have gifts that differ according to', null, '["their devotion of prayer","their suffering and endurance","grace given to them","enablement of the spirit"]', 2, 'Gifts differ according to the grace given to us (Romans 12:6).', true, '2026-09-12 10:41:22.159', '2026-09-12 10:41:22.159', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4ba0aa3b-4854-415a-abcd-576b54a1d6bc', 'Physics', 'JAMB', null, 1990, null, 'A bar of initial length l₀ is heated through a temperature change Δt to a new length l. The linear expansivity, α, of the bar is', null, '["(l - l₀)/(l Δt)","(l - l₀)/(l₀ Δt)","l₀(1 + Δt)","(l - l₀)/(l₀(1 + Δt))"]', 1, 'Linear expansivity = increase in length/(original length x temperature rise) = (l - l₀)/(l₀ Δt).', true, '2026-10-12 19:15:30.874', '2026-10-12 19:15:30.874', null, null, null, 'A bar of initial length l<sub>0</sub> is heated through a temperature change Δt to a new length l. The linear expansivity, α, of the bar is', '["(l - l<sub>0</sub>)/(l Δt)","(l - l<sub>0</sub>)/(l<sub>0</sub> Δt)","l<sub>0</sub>(1 + Δt)","(l - l<sub>0</sub>)/(l<sub>0</sub>(1 + Δt))"]', 'Linear expansivity = increase in length/(original length x temperature rise) = (l - l<sub>0</sub>)/(l<sub>0</sub> Δt).', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4ba639ff-c189-4943-8243-be58bf92aa98', 'Biology', 'JAMB', null, 2003, null, 'In mammalian males, the excretory and reproductive systems share the', null, '["ureter","vas deferens","urethra","testes"]', 2, 'The urethra serves as a common passageway for both urine excretion and semen ejaculation in males.', true, '2026-10-12 20:05:09.813', '2026-10-12 20:05:09.813', null, null, null, 'In mammalian males, the excretory and reproductive systems share the', '["ureter","vas deferens","urethra","testes"]', 'The urethra serves as a common passageway for both urine excretion and semen ejaculation in males.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4ba8fc1a-e31f-442a-a26a-8bb68decde4b', 'Economics', 'JAMB', null, 2026, null, 'Which of the following is an indicator of economic growth?', null, '["High tax rate","Technology development","High gross domestic product","High interest rate"]', 2, 'High GDP is an indicator of economic growth.', true, '2026-09-12 11:00:59.714', '2026-09-12 11:00:59.714', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4bab6643-b128-4071-929a-01d49f06666c', 'Biology', 'JAMB', null, 2026, null, 'The correct pairing of DNA is', null, '["adenine-thymine and guanine-cytosine","adenine-guanine and thymine-cytosine","adenine-cytosine and guanine-thymine","adenine-adenine and cytosine-cytosine"]', 0, 'The correct pairing of DNA bases is adenine-thymine (A-T) and guanine-cytosine (G-C). These are complementary base pairs held together by hydrogen bonds. Adenine pairs with thymine via two hydrogen bonds, and guanine pairs with cytosine via three hydrogen bonds. This base pairing is the basis of DNA''s double helix structure and is essential for DNA replication and transcription.', true, '2026-09-09 03:19:19.989', '2026-09-09 03:19:19.989', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4bbd8f7a-9677-40ae-b307-3f547fc305af', 'Literature in English', 'JAMB', null, 2026, null, 'Repetition, rhyme and rhythm are permanent features of', null, '["Drama","Poetry","Short story","Prose"]', 1, 'These are features of poetry.', true, '2026-09-12 11:07:27.373', '2026-09-12 11:07:27.373', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4bcc90d6-1a52-4eff-b356-635cc36ee91c', 'Chemistry', 'JAMB', null, 2026, null, 'Hydrogen bonding is found between molecules of the following except? I) NH₃ ii) HF iii) H₂O iv) CH₄', null, '["iv only","I, ii and iii","I and iv","iii only"]', 0, 'CH₄ does not exhibit hydrogen bonding.', true, '2026-09-12 11:36:18.886', '2026-09-12 11:36:18.886', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4bd21b66-8425-4388-a4e4-56c730d02727', 'Biology', 'JAMB', null, 2026, null, 'Mendel''s second law of inheritance states that', null, '["alleles combine randomly","alleles segregate independently","alleles separate predictably","chromosomes segregate independently"]', 1, 'Mendel''s second law of inheritance (Law of Independent Assortment) states that alleles of different genes segregate independently of each other during gamete formation. This means the inheritance of one trait does not affect the inheritance of another trait. The Law of Segregation (first law) states that alleles separate during gamete formation. Mendel''s laws laid the foundation for genetics and explain patterns of inheritance.', true, '2026-09-09 03:19:13.168', '2026-09-09 03:19:13.168', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4bdf08ca-7ba1-4cba-9549-534ff93002d0', 'Hausa', 'JAMB', null, 2010, null, 'Unguwanni, kalma ce mai gaoobi', null, '["bakwai","shida","biyar","hudu."]', 3, 'Unguwanni kalma ce mai gaoobi hudu.', true, '2026-10-13 10:37:23.93', '2026-10-13 10:37:23.93', null, null, null, 'Unguwanni, kalma ce mai gaoobi', '["bakwai","shida","biyar","hudu."]', 'Unguwanni kalma ce mai gaoobi hudu.', '{"bold":["hudu"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4bfcf865-1c62-4e41-8c57-caeb775fcb2b', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The police demanded <u>a factual</u> account of the accident.', null, '["an undisguised","an admissible","a supportive","an uncorroborated"]', 3, 'Factual = verified; opposite = uncorroborated.', true, '2026-10-24 07:21:28.616', '2026-10-24 07:21:28.616', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The police demanded <u>a factual</u> account of the accident.', '["an undisguised","an admissible","a supportive","an uncorroborated"]', 'Factual = verified; opposite = uncorroborated.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4c02ba53-91ae-4665-af06-a161a46e0e2b', 'Physics', 'JAMB', null, 1998, null, 'A parallel plate capacitor has a common plate area of 5 x 10⁻⁸ m² and plate separation of 2 x 10⁻³ m. Assuming free space, what is the capacitance? (ε₀ = 9 x 10⁻¹² F m⁻¹)', null, '["2.25 x 10⁻¹⁷ F","4.50 x 10⁻¹⁷ F","2.25 x 10⁻¹⁶ F","4.50 x 10⁻¹⁶ F"]', 2, 'C = ε₀A/d = (9 x 10⁻¹² x 5 x 10⁻⁸)/(2 x 10⁻³) = 2.25 x 10⁻¹⁶ F.', true, '2026-10-12 19:15:46.537', '2026-10-12 19:15:46.537', null, null, null, 'A parallel plate capacitor has a common plate area of 5 x 10<sup>-8</sup> m<sup>2</sup> and plate separation of 2 x 10<sup>-3</sup> m. Assuming free space, what is the capacitance? (ε<sub>0</sub> = 9 x 10<sup>-12</sup> F m<sup>-1</sup>)', '["2.25 x 10<sup>-17</sup> F","4.50 x 10<sup>-17</sup> F","2.25 x 10<sup>-16</sup> F","4.50 x 10<sup>-16</sup> F"]', 'C = ε<sub>0</sub>A/d = (9 x 10<sup>-12</sup> x 5 x 10<sup>-8</sup>)/(2 x 10<sup>-3</sup>) = 2.25 x 10<sup>-16</sup> F.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4c109784-d8f7-40be-bf18-a0182a248325', 'Economics', 'JAMB', null, 2026, null, 'Among the disadvantages of the one-man business is the fact that', null, '["the proprietor may not sue for bad debts","its capital may not be increased without government permission","the proprietor is not able to obtain credit","the proprietor is personally liable for the firm''s debts"]', 3, 'A sole proprietor has unlimited liability, meaning personal assets can be used to settle business debts.', true, '2026-09-12 10:57:26.079', '2026-09-12 10:57:26.079', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4c130181-8e8b-4b02-a1a8-8df81099c03b', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The Chief approached the issue with convincing <u>disinterestedness</u>.', null, '["lack of interest","lack of personal interest","inability to be interested","unwillingness"]', 1, 'Disinterestedness = impartiality.', true, '2026-10-24 01:03:55.594', '2026-10-24 01:03:55.594', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The Chief approached the issue with convincing <u>disinterestedness</u>.', '["lack of interest","<u>lack of personal interest</u>","inability to be interested","unwillingness"]', '<b>Disinterestedness</b> = <b>impartiality</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4c31eb71-8492-43eb-8818-6e2cf9bfc213', 'Government', 'JAMB', null, 2026, null, 'ECOWAS monitoring group (ECOMOG) was established to', null, '["Recruit able bodied men to defend West Africa","Restore peace to War-torn West African Countries","Change bad government in West Africa","Arrest and prosecute war leaders"]', 1, 'ECOMOG was established to restore peace to war-torn West African countries.', true, '2026-09-12 11:24:38.864', '2026-09-12 11:24:38.864', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4c36e20b-e32e-4443-95b3-eb72b317f7b7', 'Economics', 'JAMB', null, 2026, null, 'A major factor affecting the value of money is the?', null, '["price level","banking habits","Transaction motive","divisible nature of money"]', 0, 'The price level is a major factor affecting the value of money.', true, '2026-09-12 11:00:50.543', '2026-09-12 11:00:50.543', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4c565d67-66a0-48b9-9498-7ee8ec1a25ad', 'Economics', 'JAMB', null, 2026, null, 'Suppose wages by the firm increases, what would reasonably be expected to happen to equilibrium price and quantity for the firm''s output?', null, '["price increases; quantity decreases","Price decreases; quantity decreases","price decreases; quantity increases","price increases; quantity increases"]', 0, 'If wages increase, production costs rise, causing the supply curve to shift to the left. This results in a higher equilibrium price and a lower equilibrium quantity. The increase in wages makes production more expensive, so firms supply less at each price. The leftward shift of supply leads to a movement along the demand curve to a higher price and lower quantity.', true, '2026-09-10 10:42:00.29', '2026-09-10 10:42:00.29', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4c59493a-63b1-43ac-9760-4f0916b919ea', 'Literature in English', 'JAMB', null, 2026, null, 'When characters talk to each other, it is known as', null, '["dialogue","Monologue","epilogue","soliloquy"]', 0, 'Dialogue is when characters talk to each other.', true, '2026-09-12 11:10:24.635', '2026-09-12 11:10:24.635', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4c628b52-1fcc-4e41-a3c4-9e04bc544b0e', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The evidence the leader gave was <u>incontrovertible</u>.', null, '["logical","indubitable","practicable","contestable"]', 3, 'Incontrovertible = indisputable; opposite = contestable.', true, '2026-10-24 07:21:23.263', '2026-10-24 07:21:23.263', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The evidence the leader gave was <u>incontrovertible</u>.', '["logical","indubitable","practicable","contestable"]', 'Incontrovertible = indisputable; opposite = contestable.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4c671cd2-e0d6-4ba9-bcb8-6b40a5ae7da9', 'Financial Accounting', 'UTME', null, 2003, null, 'Income and expenditure account is more informative than receipts and payments account because it discloses', null, '["cash","cheques","debtors","stocks"]', 2, 'Income and expenditure account discloses especially members that owe subscriptions (debtors).', true, '2026-10-12 22:00:00.619', '2026-10-12 22:00:00.619', null, null, null, 'Income and expenditure account is more informative than receipts and payments account because it discloses', '["cash","cheques","<b>debtors</b>","stocks"]', 'Income and expenditure account discloses especially members that owe subscriptions (<b>debtors</b>).', '{"bold":["debtors"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4c6b6fb7-48d8-408e-8155-9256bea73e1d', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). Okonkwo manages his household <u>with a heavy hand</u>.', null, '["using the cane on every occasion","without tolerating weaknesses","like a powerful dictator","like a heavyweight champion"]', 1, '''With a heavy hand'' = without tolerating weaknesses.', true, '2026-10-24 01:02:09.188', '2026-10-24 01:02:09.188', null, null, null, '(Choose the most appropriate interpretation). Okonkwo manages his household <u>with a heavy hand</u>.', '["using the cane on every occasion","<u>without tolerating weaknesses</u>","like a powerful dictator","like a heavyweight champion"]', '''<b>With a heavy hand</b>'' = <b>without tolerating weaknesses</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4c797c1b-6ad0-427b-8c08-560df70ab1e9', 'Chemistry', 'JAMB', null, 2026, null, 'Which of the following gases will show the greatest deviation from ideal gas behavior?', null, '["H₂","O₂","NH₃","He"]', 2, 'Ammonia (NH3) is a polar molecule with strong intermolecular hydrogen bonding, causing severe deviations from ideal gas behavior.', true, '2026-09-09 17:12:49.569', '2026-09-09 17:12:49.569', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4c7a6b26-6e8b-451d-b5f6-0b816190096f', 'Physics', 'JAMB', null, 2003, null, 'By what factor will the size of an object placed 10 cm from a convex lens be increased if the image is seen on a screen placed 25 cm from the lens?', null, '["2.5","1.5","0.4","15.0"]', 0, 'Magnification = v/u = 25/10 = 2.5.', true, '2026-10-12 19:15:56.106', '2026-10-12 19:15:56.106', null, null, null, 'By what factor will the size of an object placed 10 cm from a convex lens be increased if the image is seen on a screen placed 25 cm from the lens?', '["2.5","1.5","0.4","15.0"]', 'Magnification = v/u = 25/10 = 2.5.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4c7d8db3-8bec-49c1-8657-5612c0f547e5', 'Physics', 'JAMB', null, 2000, null, 'A cell of internal resistance 1 ohm supplies current to an external resistor of 3 ohms. The efficiency of the cell is', null, '["75%","50%","33%","25%"]', 0, 'Efficiency = R/(R + r) = 3/(3 + 1) = 0.75 = 75%.', true, '2026-10-12 19:15:50.45', '2026-10-12 19:15:50.45', null, null, null, 'A cell of internal resistance 1 ohm supplies current to an external resistor of 3 ohms. The efficiency of the cell is', '["75%","50%","33%","25%"]', 'Efficiency = R/(R + r) = 3/(3 + 1) = 0.75 = 75%.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4c880c3a-00df-478a-b4e7-7d4b8c2549ee', 'Biology', 'JAMB', null, 2026, null, 'Which of the following is true in blood transfusion?', null, '["a person of blood group AB can donate blood only to another person of blood group AB","persons of blood groups A and B can donate or receive from each other","a person of blood group AB can receive blood from persons of blood groups A or B","a person of blood group O can donate only to a person of blood group O"]', 2, 'A person of blood group AB can receive blood from persons of blood groups A or B. This is because AB individuals have no anti-A or anti-B antibodies, so they do not attack foreign red blood cells. They are universal recipients. Blood group O individuals are universal donors. A and B individuals can only receive from their own type or O. This is because AB individuals have both A and B antigens on their red blood cells but neither anti-A nor anti-B antibodies in their plasma.', true, '2026-09-09 03:19:23.661', '2026-09-09 03:19:23.661', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4c9b134b-8eff-497f-89c7-da9b37bf543f', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'In Timothy, Paul urges Christians to pray for Kings and those in authority for the achievement of', null, '["a successful Christian life","godly and acceptable life","peace and exaltation in life","quiet and peaceable life"]', 3, 'Paul urges prayer for rulers so believers may live quiet and peaceable lives.', true, '2026-09-12 10:41:18.529', '2026-09-12 10:41:18.529', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4ca9793d-f760-4dda-9dfc-05e37700df3d', 'Government', 'JAMB', null, 2026, null, 'The responsibility of the judiciary is to', null, '["make laws","formulate decisions","arrest offenders","adjudicate cases"]', 3, 'The judiciary''s responsibility is to adjudicate cases.', true, '2026-09-12 11:24:21.153', '2026-09-12 11:24:21.153', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4caa42d6-9753-4e93-8cbf-24931d32117e', 'Biology', 'JAMB', null, 2003, null, 'The process of pollination involves the transfer of pollens from', null, '["I to II","II to III","III to IV","IV to I"]', 1, 'Pollination involves transferring pollen grains from the anther to the stigma.', true, '2026-10-12 20:05:11.459', '2026-10-12 20:05:11.459', null, null, null, 'The process of pollination involves the transfer of pollens from', '["I to II","II to III","III to IV","IV to I"]', 'Pollination involves transferring pollen grains from the anther to the stigma.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4cc25db8-2cb7-49f2-8fc0-feab50ea5bd5', 'Economics', 'JAMB', null, 2026, null, 'The development of an economic hypothesis through intuition, insight, or logic is associated with', null, '["Deduction","Policy economics","Normative economics","Induction"]', 0, 'Deduction is developing a hypothesis through intuition, insight, or logic.', true, '2026-09-12 11:00:36.399', '2026-09-12 11:00:36.399', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4cc6b9ca-1da4-4d0d-b80b-0c7b171d7fda', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'A call of Abraham is important to Christianity because it led to the', null, '["blessing of mankind","institution of God''s call to service","redemption of the human race","institution of covenants"]', 0, 'God promised Abraham, ''In you all the families of the earth shall be blessed.''', true, '2026-09-12 10:41:09.259', '2026-09-12 10:41:09.259', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4cd333a7-ab16-42ae-aad3-eeb382def853', 'Physics', 'JAMB', null, 2026, null, 'An ebonite rod is placed near a positively charged electroscope. What observation would be spotted with the gold leaf?', null, '["Divergence Increases","Leaf would converge","Leaf would Stay absolutely still","Teleportation"]', 1, 'When an ebonite rod (negatively charged) is placed near a positively charged electroscope, the leaf would converge (decrease divergence). The negative charge on the rod attracts positive charges to the cap, reducing the charge on the leaves.', true, '2026-09-10 10:56:44.928', '2026-09-10 10:56:44.928', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4cf85282-39b7-41ef-9378-f35f2b33f74c', 'Economics', 'JAMB', null, 2026, null, 'Average fixed cost is a rectangular hyperbola', null, '["since unit cost increases as output increases","unit cost increases as output decreases","unit cost decreases as output increases","unit cost remains the same as output increases","none of the above"]', 2, 'Average fixed cost (AFC) is a rectangular hyperbola because unit cost decreases as output increases. AFC = Total Fixed Cost / Output. Since total fixed cost is constant, as output increases, AFC continuously decreases. This is why the AFC curve slopes downward throughout and never touches the axes. It is a rectangular hyperbola because the area under the curve (AFC × Output) remains constant (equal to TFC).', true, '2026-09-10 10:41:58.667', '2026-09-10 10:41:58.667', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4d040924-d910-43c8-9245-d3e13602b2a1', 'English Language', 'JAMB', null, 2007, null, 'It was an <u>__________</u> moment for us to be <u>__________</u> to welcome the new Vice-Chancellor.', null, '["opportune/previleged","opportuned/privileged","opportune/privileged","opportuned/opportune"]', 2, 'Correct forms: opportune/privileged.', true, '2026-10-24 07:21:34.758', '2026-10-24 07:21:34.758', null, null, null, 'It was an <u>__________</u> moment for us to be <u>__________</u> to welcome the new Vice-Chancellor.', '["opportune/previleged","opportuned/privileged","opportune/privileged","opportuned/opportune"]', 'Correct forms: opportune/privileged.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4d1a6d32-7446-479c-a79a-1b96cc0d58be', 'Physics', 'JAMB', null, 2026, null, 'The energy stored in an inductor of inductance 5mH when a current of 6A flows through it is', null, '["1.8×10⁻² J","9×10⁻² J","1.4×10⁻² J","9×10⁻³ J"]', 1, 'E = ½LI² = ½ × 5×10⁻³ × 6² = ½ × 5×10⁻³ × 36 = 90×10⁻³ = 9×10⁻² J.', true, '2026-09-10 10:56:42.114', '2026-09-10 10:56:42.114', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4d1c1310-5030-407a-87d3-7f338cc3eead', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. In the opinion of most observers, it was a <u>disinterested</u> decision.', null, '["neutral","impartial","biased","candid"]', 2, 'Disinterested = impartial; opposite = biased.', true, '2026-10-24 07:21:16.381', '2026-10-24 07:21:16.381', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. In the opinion of most observers, it was a <u>disinterested</u> decision.', '["neutral","impartial","biased","candid"]', 'Disinterested = impartial; opposite = biased.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4d2587a0-7bc6-4d0b-a351-c4d489769e26', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. One <u>hindrance</u> to an orderly economic development of the country is large-scale fraud and corruption.', null, '["difficulty","element","reason","obstacle","ritual"]', 3, 'Hindrance = obstacle.', true, '2026-10-24 01:03:53.758', '2026-10-24 01:03:53.758', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. One <u>hindrance</u> to an orderly economic development of the country is large-scale fraud and corruption.', '["difficulty","element","reason","<u>obstacle</u>","ritual"]', '<b>Hindrance</b> = <b>obstacle</b>.', '{}');
