insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4da75e56-cf2f-47c0-8477-46d93feb0cf5', 'Government', 'JAMB', null, 2026, null, 'Government as a process of governing means the', null, '["activities of the pressure groups and political parties","act of vetoing of bills","orders of the judiciary and legislature","activities by which Government policies are made and implemented","Activities of parliamentary opposition"]', 3, 'Government as a process of governing means the activities by which government policies are made and implemented. This definition emphasizes government as a dynamic process rather than just a set of institutions. It includes all the activities involved in making decisions, implementing policies, and managing public affairs. The other options describe specific activities or institutions, not the broad process of governing.', true, '2026-09-10 10:45:06.624', '2026-09-10 10:45:06.624', null, null, null, null, null, null, null);
