insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4de5565e-44bd-46a7-b1ea-2c18c59b6492', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). Solo has resigned his job with the Textile Mills. He has no worry to worry about getting another job. His plans are still quite <u>in the air</u>. This means that his plans are _________________', null, '["airmailed","air tight","uncertain","certain","airborne"]', 2, '''In the air'' means unsettled/uncertain.', true, '2026-10-24 01:04:12.85', '2026-10-24 01:04:12.85', null, null, null, '(Choose the most appropriate interpretation). Solo has resigned his job with the Textile Mills. He has no worry to worry about getting another job. His plans are still quite <u>in the air</u>. This means that his plans are _________________', '["airmailed","air tight","<u>uncertain</u>","certain","airborne"]', '''<b>In the air</b>'' means unsettled/<b>uncertain</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4dedc7fc-efbd-47c5-a754-02786d845d30', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. I cannot understand how he suddenly became <u>audacious</u> contrary to his nature.', null, '["proud","bold","rude","hostile"]', 1, 'Audacious = bold.', true, '2026-10-24 01:03:55.434', '2026-10-24 01:03:55.434', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. I cannot understand how he suddenly became <u>audacious</u> contrary to his nature.', '["proud","<u>bold</u>","rude","hostile"]', '<b>Audacious</b> = <b>bold</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4dfaa459-c905-4fdb-bfbe-7952250de5d3', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Christians ought to be humble because', null, '["the law commanded it absolutely","Jesus Christ demonstrated it","it is a spiritual gift","only the humble will inherit eternal life"]', 1, 'Jesus humbled Himself and became obedient to death (Philippians 2).', true, '2026-09-12 10:41:22.501', '2026-09-12 10:41:22.501', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4e074f9e-a84f-4554-8cde-8241e884c3c9', 'Literature in English', 'JAMB', null, 2026, null, 'The use of animals with human attributes in The Nun''s Priest''s Tale is an example of', null, '["Allegory","Satire","Anthropomorphism","Paradox"]', 2, 'The use of animals with human attributes is anthropomorphism.', true, '2026-09-12 11:05:13.61', '2026-09-12 11:05:13.61', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4e1cf863-dffe-464e-83a1-5506413c167c', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. I cannot understand how he suddenly became <u>audacious</u> contrary to his nature.', null, '["proud","bold","rude","hostile"]', 1, 'Audacious = bold.', true, '2026-10-24 01:01:43.031', '2026-10-24 01:01:43.031', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. I cannot understand how he suddenly became <u>audacious</u> contrary to his nature.', '["proud","<u>bold</u>","rude","hostile"]', '<b>Audacious</b> = <b>bold</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4e1e28a2-5082-4d8b-a7f0-de3c70699de1', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'According to Paul, all Christians who have been baptized into Christ were baptized', null, '["into his death","By fire","Under the law","By his disciples"]', 0, 'Baptized into Christ means baptized into His death (Romans 6:3).', true, '2026-09-12 10:42:00.13', '2026-09-12 10:42:00.13', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4e293b9f-3417-495a-9167-9a8688b5796f', 'General Mathematics', 'JAMB', null, 2026, null, 'If three numbers p, q, r are in the ratio 6:4:5, find the value of (3p-q)/(4q+r)', null, '["3/2","2/3","2","3","18"]', 1, 'Let p=6k, q=4k, r=5k. (3p-q) = 18k-4k = 14k. (4q+r) = 16k+5k = 21k. So (3p-q)/(4q+r) = 14k/21k = 2/3.', true, '2026-09-10 10:48:19.785', '2026-09-10 10:48:19.785', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4e33f818-84a5-4577-b45a-0f145919ee85', 'Literature in English', 'JAMB', null, 2026, null, 'The dominant literary device in New Tongue is', null, '["Symbolism","Irony","Euphemism","Hyperbole"]', 0, 'The dominant device is symbolism.', true, '2026-09-12 11:05:26.173', '2026-09-12 11:05:26.173', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4e468e6d-2dde-4116-b073-3cb174dfdba8', 'Physics', 'JAMB', null, 1999, null, 'When the brakes in a car are applied, the frictional force on the tyres is', null, '["A disadvantage because it is in the direction of motion of the car","A disadvantage because it is in the opposite direction of motion of the car.","An advantage because it is in the direction of motion of the car.","An advantage because it is in the opposite direction of motion of the car."]', 3, 'Friction opposes the motion of the car, and this is exactly what is needed to slow it down, so it is an advantage.', true, '2026-10-12 19:15:47.608', '2026-10-12 19:15:47.608', null, null, null, 'When the brakes in a car are applied, the frictional force on the tyres is', '["A disadvantage because it is in the direction of motion of the car","A disadvantage because it is in the opposite direction of motion of the car.","An advantage because it is in the direction of motion of the car.","An advantage because it is in the opposite direction of motion of the car."]', 'Friction opposes the motion of the car, and this is exactly what is needed to slow it down, so it is an advantage.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4e500950-d4d1-49e8-9314-b8f6a070878d', 'Physics', 'JAMB', null, 1995, null, 'Temperature is a measure of the', null, '["Quantity of heat transferred into the molecules of an object","Mean kinetic energy of any molecules of the object","Kinetic energy of any individual molecules of the substance.","Amount of work done by the molecules of the object."]', 1, 'Temperature measures the average (mean) kinetic energy of the molecules of a substance.', true, '2026-10-12 19:15:41.147', '2026-10-12 19:15:41.147', null, null, null, 'Temperature is a measure of the', '["Quantity of heat transferred into the molecules of an object","Mean kinetic energy of any molecules of the object","Kinetic energy of any individual molecules of the substance.","Amount of work done by the molecules of the object."]', 'Temperature measures the average (mean) kinetic energy of the molecules of a substance.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4e5e12c1-42d0-49dc-a36d-8601fd48255d', 'Literature in English', 'JAMB', null, 2026, null, '"When the criminal was arrested, he rattled like a rattle snake" is an example of', null, '["Pun","Simile","Hyperbole","Apostrophe"]', 1, 'The expression "he rattled like a rattle snake" is an example of simile. A simile is a figure of speech that compares two different things using ''like'' or ''as.'' Here, the criminal''s rattling (shaking or making noise) is compared to a rattlesnake using ''like.'' A pun is a play on words, hyperbole is exaggeration, and apostrophe is addressing an absent person or abstract idea.', true, '2026-09-10 10:47:09.57', '2026-09-10 10:47:09.57', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4e73f7ec-c7ad-4c52-8655-8d8cc6149fc5', 'English Language', 'JAMB', null, 2024, null, 'Bepo''s voice was naturally loud, making it unnecessary for him to use a', null, '["Whistle","Loudspeaker","Microphone","Megaphone"]', 2, 'Bepo''s voice was naturally loud, making it unnecessary for him to use a microphone.', true, '2026-09-18 09:43:02.708', '2026-09-18 09:43:02.708', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4e7c9544-318d-4ec9-9f56-7975170e027b', 'English Language', 'JAMB', null, 2024, null, '54', null, '["Firearms","Fireballs","Fireworks","Firesmokes"]', 1, '"Fireballs" is the correct term for expanding hot gases.', true, '2026-09-18 10:17:48.897', '2026-09-18 10:17:48.897', 'decfd2ca-8924-4681-ba7c-9a039e9bda97', 7, 'CLOZE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4e81b8a7-6a43-487d-8ee1-c0ddc877db3c', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'In the prophetic tradition, the concept of the ''Day of the Lord'' (e.g. in Amos and Zephaniah) is best understood as', null, '["a time of political independence","divine intervention in judgement and restoration","celebration of covenant renewal","period of economic prosperity"]', 1, 'The ''Day of the Lord'' is divine intervention in judgement and restoration.', true, '2026-09-12 10:41:01.636', '2026-09-12 10:41:01.636', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4e8ce2ba-fa7e-4f6e-805a-88181c063ef5', 'Economics', 'JAMB', null, 2026, null, 'The financial institution in charge of accepting deposits and giving loans to the public is', null, '["Central Bank","Insurance Company","Commercial Bank","Development Bank"]', 2, 'Commercial banks accept deposits and give loans to the public.', true, '2026-09-12 10:59:50.849', '2026-09-12 10:59:50.849', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4e9b3f64-e285-4fb5-ab22-0f3beb9a817b', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The <u>plebs</u> can be found in every society of the world.', null, '["masses","elite","middle class","politicians"]', 1, 'Plebs = commoners; opposite = elite.', true, '2026-10-24 07:21:30.172', '2026-10-24 07:21:30.172', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The <u>plebs</u> can be found in every society of the world.', '["masses","elite","middle class","politicians"]', 'Plebs = commoners; opposite = elite.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4ea136b7-34e6-45eb-8735-b0baf2356a4f', 'Government', 'JAMB', null, 2026, null, 'The Igbo of eastern Nigeria in the pre-colonial era had', null, '["No central government","A government of chiefs","A government by age grade","A government controlled by warrant chiefs"]', 0, 'The Igbo had no central government in the pre-colonial era.', true, '2026-09-12 11:24:24.894', '2026-09-12 11:24:24.894', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4ea3dcd8-ab15-4f28-a62c-7c1446c0f3e1', 'Literature in English', 'JAMB', null, 2026, null, 'What literary device is used in this extract?', null, '["Hyperbole","Irony","Metaphor","Onomatopoeia"]', 0, 'Hyperbole is used in this extract.', true, '2026-09-12 11:11:18.751', '2026-09-12 11:11:18.751', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4eaccd77-0706-489e-ac0d-d42833f248f2', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The astute businessman neatly <u>fended off</u> questions about his private life.', null, '["asked","welcomed","sidestepped","explained"]', 2, 'Fended off = sidestepped.', true, '2026-10-24 01:04:09.07', '2026-10-24 01:04:09.07', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The astute businessman neatly <u>fended off</u> questions about his private life.', '["asked","welcomed","<u>sidestepped</u>","explained"]', '<b>Fended off</b> = <b>sidestepped</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4ec9addf-b46b-42f7-9574-d075db627fd8', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Though David''s condition is <u>serious</u>, his life is not in immediate danger.', null, '["nasty","hypertensive","dangerous","grave"]', 3, 'Serious = grave.', true, '2026-10-24 01:04:02.431', '2026-10-24 01:04:02.431', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Though David''s condition is <u>serious</u>, his life is not in immediate danger.', '["nasty","hypertensive","dangerous","<u>grave</u>"]', '<b>Serious</b> = <b>grave</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4ecb48f5-8d43-416e-88d2-fcbae58afd9f', 'Economics', 'JAMB', null, 2026, null, 'Which tends to be a progressive tax in Nigeria?', null, '["income tax","property tax","sales tax","import tax"]', 0, 'Income tax tends to be a progressive tax in Nigeria. A progressive tax takes a larger percentage of income from high-income earners than from low-income earners. Nigeria''s personal income tax uses a graduated rate structure where higher incomes are taxed at higher rates. Property tax, sales tax, and import tax are generally regressive because they take a larger percentage of income from low-income earners.', true, '2026-09-10 10:42:00.343', '2026-09-10 10:42:00.343', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4eccf17f-a9a0-4a88-ba48-caa739674790', 'Physics', 'JAMB', null, 1985, null, 'A charge of one coulomb liberates 0.0033 g of copper in an electrolytic process. How long will it take a current of 2 A to liberate 1.98 g of copper in such a process?', null, '["5 minutes","30 minutes","50 minutes","60 minutes","120 minutes"]', 0, 'Charge needed = 1.98/0.0033 = 600 C. t = Q/I = 600/2 = 300 s = 5 minutes.', true, '2026-10-12 19:15:22.122', '2026-10-12 19:15:22.122', null, null, null, 'A charge of one coulomb liberates 0.0033 g of copper in an electrolytic process. How long will it take a current of 2 A to liberate 1.98 g of copper in such a process?', '["5 minutes","30 minutes","50 minutes","60 minutes","120 minutes"]', 'Charge needed = 1.98/0.0033 = 600 C. t = Q/I = 600/2 = 300 s = 5 minutes.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4ecf027c-b0d1-4727-9066-782cdf96e6af', 'English Language', 'JAMB', null, 2007, null, '<u>Beads</u> of sweat ran down Ngozi''s armpit.', null, '["pounds","springs","rivulets","pools"]', 2, 'Beads = rivulets.', true, '2026-10-24 01:01:56.808', '2026-10-24 01:01:56.808', null, null, null, '<u>Beads</u> of sweat ran down Ngozi''s armpit.', '["pounds","springs","<u>rivulets</u>","pools"]', '<b>Beads</b> = <b>rivulets</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4ee1d8bc-4dbc-4ba7-8ef5-61763fbc6e43', 'Physics', 'JAMB', null, 2003, null, 'A pipe closed at one end produces its fundamental note. If the velocity of sound in air is v and l is the length of the pipe, the frequency of the note is', null, '["v/2l","2v/l","v/5l","v/4l"]', 3, 'A closed pipe has a node at the closed end and an antinode at the open end, so λ = 4l and f = v/4l.', true, '2026-10-12 19:15:56.354', '2026-10-12 19:15:56.354', null, null, null, 'A pipe closed at one end produces its fundamental note. If the velocity of sound in air is v and l is the length of the pipe, the frequency of the note is', '["v/2l","2v/l","v/5l","v/4l"]', 'A closed pipe has a node at the closed end and an antinode at the open end, so λ = 4l and f = v/4l.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4ee43cec-fb8c-4703-b4ea-b88932a62063', 'Physics', 'JAMB', null, 1985, null, 'A uniform cylindrical block of wood floats in water with one-third of its height above the water level. In a liquid of relative density 0.8, what fraction of its height will be above the liquid level?', null, '["1/6","1/5","1/3","4/5","5/6"]', 0, 'The wood''s relative density is 2/3. In the liquid, fraction submerged = (2/3)/0.8 = 5/6, so the fraction above the surface is 1/6.', true, '2026-10-12 19:15:21.203', '2026-10-12 19:15:21.203', null, null, null, 'A uniform cylindrical block of wood floats in water with one-third of its height above the water level. In a liquid of relative density 0.8, what fraction of its height will be above the liquid level?', '["1/6","1/5","1/3","4/5","5/6"]', 'The wood''s relative density is 2/3. In the liquid, fraction submerged = (2/3)/0.8 = 5/6, so the fraction above the surface is 1/6.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4ef098e8-d8e1-4805-8e29-9472bcce4272', 'Economics', 'JAMB', null, 2026, null, 'From an economics point of view, an activity does not have cost when', null, '["someone else pays for it","the returns are greater than costs","the choice involves giving up nothing","government pays for it"]', 2, 'From an economics point of view, an activity does not have cost when the choice involves giving up nothing. Opportunity cost is the value of the next best alternative forgone. If no alternative is sacrificed, there is no opportunity cost. If someone else pays or the government pays, there is still a cost to society (opportunity cost).', true, '2026-09-10 10:41:20.349', '2026-09-10 10:41:20.349', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4efb439e-5b88-4fd1-8f56-a6b714b32ddc', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'The Christological hymn in Philippians 2:5-11 emphasises', null, '["Christ''s earthly miracles","kenosis and exaltation","apostolic authority","eschatological judgement"]', 1, 'The Christological hymn in Philippians 2:5-11 emphasises kenosis (Christ''s self-emptying by becoming human and obedient to death) and exaltation (God highly exalted Him and gave Him the name above every name).', true, '2026-09-12 09:45:53.74', '2026-09-12 09:45:53.74', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4f0419a6-b9aa-4c55-8cec-ce5293b2fb4e', 'Financial Accounting', 'UTME', null, 2003, null, 'Which of these is a capital expenditure warrant?', null, '["provisional general warrant","development fund general warrant","reserved expenditure general warrant","supplementary warrant"]', 1, 'Development fund general warrant is a capital expenditure warrant.', true, '2026-10-12 22:00:01.114', '2026-10-12 22:00:01.114', null, null, null, 'Which of these is a capital expenditure warrant?', '["provisional general warrant","<b>development fund general warrant</b>","reserved expenditure general warrant","supplementary warrant"]', '<b>Development fund general warrant</b> is a capital expenditure warrant.', '{"bold":["development fund general warrant"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4f06b871-781c-40ee-aa41-00a708baa9e2', 'Economics', 'JAMB', null, 2026, null, 'Identify one of the following which can NOT be used to close deflationary gap.', null, '["Increased interest rate","Increased money supply","Reduction in tax","Increased government expenditure"]', 0, 'Increased interest rate would worsen a deflationary gap.', true, '2026-09-12 11:02:06.251', '2026-09-12 11:02:06.251', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4f2b05ea-b1fa-4c69-ac1f-fc33f8d07552', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Jeremiah described Israel as faithless and Judah as', null, '["Idolatrous","False","Stubborn","Rebellious"]', 3, 'Jeremiah described Judah as rebellious (Jeremiah 3:11).', true, '2026-09-12 10:41:58.432', '2026-09-12 10:41:58.432', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4f2dec89-0294-4041-8f74-9a486eb89985', 'Literature in English', 'JAMB', null, 2026, null, 'A deliberate imitation of a literary style with the intention to ridicule is', null, '["paradox","prosody","parody","pun"]', 2, 'Parody is deliberate imitation to ridicule.', true, '2026-09-12 11:05:41.127', '2026-09-12 11:05:41.127', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4f2e96cd-5b08-465e-a540-ae542b695924', 'Physics', 'JAMB', null, 2001, null, 'The cost of running five 60 W lamps and four 100 W lamps for 20 hours if electrical energy costs N10.00 per kWh is', null, '["N 280.00","N 160.00","N 120.00","N 140.00"]', 3, 'Total power = 5 x 60 + 4 x 100 = 700 W = 0.7 kW. Energy = 0.7 x 20 = 14 kWh. Cost = 14 x 10 = N 140.00.', true, '2026-10-12 19:15:51.845', '2026-10-12 19:15:51.845', null, null, null, 'The cost of running five 60 W lamps and four 100 W lamps for 20 hours if electrical energy costs N10.00 per kWh is', '["N 280.00","N 160.00","N 120.00","N 140.00"]', 'Total power = 5 x 60 + 4 x 100 = 700 W = 0.7 kW. Energy = 0.7 x 20 = 14 kWh. Cost = 14 x 10 = N 140.00.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4f394276-ae17-4963-b911-c05ae92bd8e3', 'Financial Accounting', 'UTME', null, 2002, null, 'Costs that vary in proportion to the level of production in a manufacturing environment are known as', null, '["control costs","overheads","direct costs","indirect cost"]', 2, 'Direct costs also known as prime cost vary directly with level of production. The three costs that made up of direct costs are direct materials, labour and expenses.', true, '2026-10-12 21:59:58.301', '2026-10-12 21:59:58.301', null, null, null, 'Costs that vary in proportion to the level of production in a manufacturing environment are known as', '["control costs","overheads","<b>direct costs</b>","indirect cost"]', '<b>Direct costs</b> also known as prime cost vary directly with level of production. The three costs that made up of direct costs are direct materials, labour and expenses.', '{"bold":["direct costs"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4f685bd8-6bc3-488d-a3b8-b1f07809500a', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). The judge always takes <u>a hardline</u> on such issues.', null, '["complex stand","simple stand","uncompromising stand","difficult stand"]', 2, '''Hardline'' = uncompromising stand.', true, '2026-10-24 01:04:18.468', '2026-10-24 01:04:18.468', null, null, null, '(Choose the most appropriate interpretation). The judge always takes <u>a hardline</u> on such issues.', '["complex stand","simple stand","<u>uncompromising stand</u>","difficult stand"]', '''<b>Hardline</b>'' = <b>uncompromising stand</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4f6a9515-2880-495d-b1db-8f30f15c5f86', 'Chemistry', 'JAMB', null, 2026, null, 'Increasing the pressure of gas', null, '["lowers the average kinetic energy of the molecules","decrease the density of the gas","decrease the temperature of the gas","increase the density of the gas","increase the volume of the gas"]', 3, 'Increasing pressure increases the density of the gas.', true, '2026-09-12 11:36:04.236', '2026-09-12 11:36:04.236', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4f74a540-e610-4544-a7fb-4b6162643f00', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). Ngozi and Ekwere were <u>fast friends</u> when they were in the secondary school.', null, '["friends who run very quickly together","friends who go without food for a long time together","friends who spend too much time and energy on pleasure and excitement together","friends who are not easily separated from each other"]', 3, '''Fast friends'' = closely attached friends.', true, '2026-10-24 01:04:19.807', '2026-10-24 01:04:19.807', null, null, null, '(Choose the most appropriate interpretation). Ngozi and Ekwere were <u>fast friends</u> when they were in the secondary school.', '["friends who run very quickly together","friends who go without food for a long time together","friends who spend too much time and energy on pleasure and excitement together","<u>friends who are not easily separated from each other</u>"]', '''<b>Fast friends</b>'' = <b>closely attached friends</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4f78949b-fbd2-4526-ab41-c3d2cb1fa492', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). In those days an ordinary school drop-out would come around <u>putting on airs</u>.', null, '["giving himself patches of air","trying to oppress people","wearing flashy clothes","desires in light materials"]', 2, '''Putting on airs'' = showy behaviour.', true, '2026-10-24 01:02:07.759', '2026-10-24 01:02:07.759', null, null, null, '(Choose the most appropriate interpretation). In those days an ordinary school drop-out would come around <u>putting on airs</u>.', '["giving himself patches of air","trying to oppress people","<u>wearing flashy clothes</u>","desires in light materials"]', '''<b>Putting on airs</b>'' = <b>showy behaviour</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4f7c91a0-57b3-449d-bdf1-245af9562d63', 'English Language', 'JAMB', null, 2007, null, 'After too much exercise, some people suffer from cramp which is caused by the <u>............</u> of the muscles', null, '["contraction","restriction","conscription","relaxation"]', 0, 'Correct spelling: contraction.', true, '2026-10-24 07:21:37.225', '2026-10-24 07:21:37.225', null, null, null, 'After too much exercise, some people suffer from cramp which is caused by the <u>............</u> of the muscles', '["contraction","restriction","conscription","relaxation"]', 'Correct spelling: contraction.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4f818ef0-c4f2-48de-822a-8a90405c6672', 'Government', 'JAMB', null, 2026, null, 'A major drawback to the NEPAD initiative is its', null, '["inability to empower the youth","reliance on Western donors for funds","articulation by few African leaders","affiliation to the African Union"]', 1, 'A major drawback of NEPAD is reliance on Western donors for funds.', true, '2026-09-12 11:24:40.681', '2026-09-12 11:24:40.681', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4f917a29-a494-4b5c-8b36-662c030e2125', 'Literature in English', 'JAMB', null, 2026, null, 'The dominant figure of speech in the first stanza is', null, '["Hyperbole","Simile","Euphemism","Pun"]', 1, 'The dominant figure of speech is simile.', true, '2026-09-12 11:13:52.725', '2026-09-12 11:13:52.725', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4f9193ce-2316-4611-8eae-0baa2895cc49', 'English Language', 'JAMB', null, 2024, null, '______ football, I also play basketball.', null, '["besides","except for","beside","except"]', 0, '"Besides" means in addition to.', true, '2026-09-18 09:43:02.593', '2026-09-18 09:43:02.593', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4f9a1d6d-c45d-4489-88c1-36d0c1605041', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The cleaner resigned from his job which he said had become a <u>trivial</u> round.', null, '["unrewarding","too routine","rather degrading","unattractive"]', 1, 'A trivial round = too routine.', true, '2026-10-24 01:01:48.705', '2026-10-24 01:01:48.705', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The cleaner resigned from his job which he said had become a <u>trivial</u> round.', '["unrewarding","<u>too routine</u>","rather degrading","unattractive"]', 'A <b>trivial round</b> = <b>too routine</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4f9e6431-344d-46b3-bec3-586e2fbbf139', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). ''<u>To put something aside</u>'' is to ____________', null, '["put it by one''s side","put it in a side pocket for future use","keep something for some special purpose","keep in safety","protect it"]', 2, '''Put aside'' means reserve for special purpose.', true, '2026-10-24 01:04:13.443', '2026-10-24 01:04:13.443', null, null, null, '(Choose the most appropriate interpretation). ''<u>To put something aside</u>'' is to ____________', '["put it by one''s side","put it in a side pocket for future use","<u>keep something for some special purpose</u>","keep in safety","protect it"]', '''<b>Put aside</b>'' means <b>reserve for special purpose</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4fa7d802-47be-4207-beca-8f71a9464235', 'Hausa', 'JAMB', null, 2011, null, 'Marubucin ''WaKar Zambon Kazama'' ta zaBaßßun WaKokin Da Da Na Yanzu na D. Abdulkadir ya nuna cewa mata Kazamai suna nuna Kazantarsu ta', null, '["jiki da abinci","gida da abinci","jiki gida da abinci","jiki gida da waje."]', 2, 'Mata Kazamai suna nuna Kazantarsu ta jiki, gida da abinci.', true, '2026-10-13 10:37:22.75', '2026-10-13 10:37:22.75', null, null, null, 'Marubucin ''WaKar Zambon Kazama'' ta zaBaßßun WaKokin Da Da Na Yanzu na D. Abdulkadir ya nuna cewa mata Kazamai suna nuna Kazantarsu ta', '["jiki da abinci","gida da abinci","jiki gida da abinci","jiki gida da waje."]', 'Mata Kazamai suna nuna Kazantarsu ta jiki, gida da abinci.', '{"bold":["jiki, gida da abinci"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4fa99889-167c-4856-b4f6-61c7507c139a', 'Physics', 'JAMB', null, 1987, null, 'In which of the following are the substances arranged in descending order of their thermal conductivities?', null, '["Copper, steel, glass","Steel, copper, glass","Steel, glass, copper","Copper, glass, steel."]', 0, 'Copper is an excellent conductor, steel is a moderate one, and glass is a poor conductor.', true, '2026-10-12 19:15:25.478', '2026-10-12 19:15:25.478', null, null, null, 'In which of the following are the substances arranged in descending order of their thermal conductivities?', '["Copper, steel, glass","Steel, copper, glass","Steel, glass, copper","Copper, glass, steel."]', 'Copper is an excellent conductor, steel is a moderate one, and glass is a poor conductor.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4faf14fd-bff8-43fb-a82a-f3f8d399f44d', 'Biology', 'JAMB', null, 2026, null, 'Which of the following has cones?', null, '["angiosperms","gymnosperms","pteridophytes","bryophytes"]', 1, 'Gymnosperms (conifers, cycads, ginkgo) have cones. Cones are the reproductive structures of gymnosperms. Angiosperms have flowers and fruits. Pteridophytes (ferns) have sori on fronds. Bryophytes have sporophyte capsules. Gymnosperm cones include male (pollen) cones and female (seed) cones. The cone is a strobilus containing reproductive structures. Cone-bearing plants are some of the earliest seed plants and include pines, spruces, firs, and cedars.', true, '2026-09-09 03:19:06.636', '2026-09-09 03:19:06.636', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4fbef30f-2a0a-4a0d-8edf-31b9a253d265', 'Literature in English', 'JAMB', null, 2026, null, 'The poet''s tone shifts from', null, '["joy to anger","nostalgia to disillusionment","anger to love","satire to humour"]', 1, 'The tone shifts from nostalgia to disillusionment.', true, '2026-09-12 11:11:22.3', '2026-09-12 11:11:22.3', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('4fd1c1e4-1aa6-4dc0-bc88-52e371a43d92', 'Literature in English', 'JAMB', null, 2026, null, 'Who is the addressee?', null, '["Antony","Cleopatra","Demetrius","Charmian"]', 2, 'The addressee is Demetrius.', true, '2026-09-12 11:14:16.604', '2026-09-12 11:14:16.604', null, null, null, null, null, null, null);
