insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('508f6f8e-273c-420f-83b8-79440907e9a6', 'Physics', 'JAMB', null, 1991, null, 'A trough 12.0 cm deep is filled with water of refractive index 4/3. By how much would a coin at the bottom of the trough appear to be displaced when viewed vertically from above the water surface?', null, '["3.0 cm","6.0 cm","9.0 cm","16.0 cm"]', 0, 'Apparent depth = 12/(4/3) = 9.0 cm. The coin appears raised by 12 - 9 = 3.0 cm.', true, '2026-10-12 19:15:33.623', '2026-10-12 19:15:33.623', null, null, null, 'A trough 12.0 cm deep is filled with water of refractive index 4/3. By how much would a coin at the bottom of the trough appear to be displaced when viewed vertically from above the water surface?', '["3.0 cm","6.0 cm","9.0 cm","16.0 cm"]', 'Apparent depth = 12/(4/3) = 9.0 cm. The coin appears raised by 12 - 9 = 3.0 cm.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('509b9415-efa2-4040-8a5a-eef357bd00e8', 'Physics', 'JAMB', null, 1987, null, 'A body rolls down a slope from a height of 100 m. Its velocity at the foot of the slope is 20 m s⁻¹. What percentage of its initial potential energy is converted into kinetic energy? (g = 10 m s⁻²)', null, '["40 %","35 %","20 %","15 %"]', 2, 'Per kg: PE = gh = 1000 J, KE = ½v² = 200 J. Percentage = 200/1000 x 100 = 20 %.', true, '2026-10-12 19:15:24.87', '2026-10-12 19:15:24.87', null, null, null, 'A body rolls down a slope from a height of 100 m. Its velocity at the foot of the slope is 20 m s<sup>-1</sup>. What percentage of its initial potential energy is converted into kinetic energy? (g = 10 m s<sup>-2</sup>)', '["40 %","35 %","20 %","15 %"]', 'Per kg: PE = gh = 1000 J, KE = ½v<sup>2</sup> = 200 J. Percentage = 200/1000 x 100 = 20 %.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('50a15ebe-3f02-4bd9-914d-e0bd78ef9ff8', 'Financial Accounting', 'UTME', null, 2004, null, 'A component of an overhead manufacturing cost is', null, '["cost of work-in-progress","cost of finished goods","labour","rent"]', 3, 'All expenses incurred in the factory which cannot be traced directly to production are called Factory overhead. These include Factory rent, power, repairs, etc.', true, '2026-10-12 22:00:02.887', '2026-10-12 22:00:02.887', null, null, null, 'A component of an overhead manufacturing cost is', '["cost of work-in-progress","cost of finished goods","labour","<b>rent</b>"]', 'All expenses incurred in the factory which cannot be traced directly to production are called Factory overhead. These include Factory <b>rent</b>, power, repairs, etc.', '{"bold":["rent"],"italic":[],"underline":[],"fillBlanks":[]}');
