insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('53d23558-bd22-49f6-a3c3-6701e06470d1', 'Physics', 'JAMB', null, 2001, null, 'The terrestrial telescope has one extra lens more than the astronomical telescope. The extra lens is for', null, '["Improving the sharpness","Creating an inverted image","Magnification of the image","Erection of the image"]', 3, 'The astronomical telescope gives an inverted image. The extra lens in a terrestrial telescope turns it the right way up (erects it).', true, '2026-10-12 19:15:51.254', '2026-10-12 19:15:51.254', null, null, null, 'The terrestrial telescope has one extra lens more than the astronomical telescope. The extra lens is for', '["Improving the sharpness","Creating an inverted image","Magnification of the image","Erection of the image"]', 'The astronomical telescope gives an inverted image. The extra lens in a terrestrial telescope turns it the right way up (erects it).', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('53efd10b-e1ae-47f0-95b0-e49da4a0a556', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The press described the efforts of the government in <u>pejorative</u> terms.', null, '["superlative","palpable","critical","contemptible"]', 3, 'Pejorative = contemptible.', true, '2026-10-24 01:01:52.84', '2026-10-24 01:01:52.84', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The press described the efforts of the government in <u>pejorative</u> terms.', '["superlative","palpable","critical","<u>contemptible</u>"]', '<b>Pejorative</b> = <b>contemptible</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('53fa597b-3f8a-434b-af61-8b2ff56a1737', 'Literature in English', 'JAMB', null, 2026, null, 'A deliberate imitation of a literary style with the intention to ridicule is', null, '["paradox","prosody","parody","pun"]', 2, 'Parody is deliberate imitation to ridicule.', true, '2026-09-12 11:10:11.75', '2026-09-12 11:10:11.75', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('53ff1e78-e5dc-472f-b012-b14a8e8fd9d8', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Such measures end up <u>exacerbating</u> the pain.', null, '["aggravating","increasing","eliminating","alleviating"]', 3, 'Exacerbating = worsening; opposite = alleviating.', true, '2026-10-24 07:21:15.867', '2026-10-24 07:21:15.867', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Such measures end up <u>exacerbating</u> the pain.', '["aggravating","increasing","eliminating","alleviating"]', 'Exacerbating = worsening; opposite = alleviating.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('540f0d31-eaf4-4ebb-b1c7-55ab748028ec', 'Government', 'JAMB', null, 2026, null, 'All the following are merits of the indirect rule except', null, '["it preserved pre-colonial traditional institutions","It made people familiar with the government","It trained future leaders","It gives traditional rulers opportunity to participate in the act of government"]', 2, 'Training future leaders was not a merit of indirect rule. The indirect rule system was designed to use traditional rulers to administer the colonies, but it did not deliberately train future leaders for self-government. In fact, indirect rule was criticized for preserving traditional institutions that were not democratic and for slowing political development. The other options are merits: it preserved traditional institutions, made people familiar with government, and gave traditional rulers opportunities to participate in governance.', true, '2026-09-10 10:45:06.25', '2026-09-10 10:45:06.25', null, null, null, null, null, null, null);
