insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('541b40f6-59d7-4c9b-aba8-4d0e874f3c0f', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. There has been a <u>downturn</u> in the affairs of the company.', null, '["a turn-around","a massive increase","a decline","little progress"]', 2, 'Downturn = a decline.', true, '2026-10-24 01:01:53.323', '2026-10-24 01:01:53.323', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. There has been a <u>downturn</u> in the affairs of the company.', '["a turn-around","a massive increase","<u>a decline</u>","little progress"]', '<b>Downturn</b> = <b>a decline</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('542573ec-ae90-41e1-ad5d-82d96cc2bd14', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The proprietor accused Uche of silently <u>acquiescing</u> to the students'' demand.', null, '["adjusting","resisting","compromising on","submitting to"]', 1, 'Acquiescing = agreeing; opposite = resisting.', true, '2026-10-24 07:21:25.483', '2026-10-24 07:21:25.483', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The proprietor accused Uche of silently <u>acquiescing</u> to the students'' demand.', '["adjusting","resisting","compromising on","submitting to"]', 'Acquiescing = agreeing; opposite = resisting.', '{}');
