insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5490bf4a-9141-4844-8c36-3bfe01357a40', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'The Deuteronomic interpretation of Israel''s history emphasises that national prosperity is contingent upon', null, '["covenant obedience","military strength","prophetic leadership","temple sacrifices"]', 0, 'The Deuteronomic interpretation of Israel''s history emphasises that national prosperity is contingent upon covenant obedience. If Israel obeyed God''s commandments, they would be blessed; if they disobeyed, they would be cursed and exiled.', true, '2026-09-12 09:45:54.459', '2026-09-12 09:45:54.459', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('54b30299-4a13-40c0-b51d-4117ec0abc26', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Laraba saw a <u>forlorn</u> little figure sitting outside the class.', null, '["wise and intelligent","lonely and unhappy","smart and healthy","short and ugly"]', 1, 'Forlorn = lonely and unhappy.', true, '2026-10-24 01:01:57.975', '2026-10-24 01:01:57.975', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Laraba saw a <u>forlorn</u> little figure sitting outside the class.', '["wise and intelligent","<u>lonely and unhappy</u>","smart and healthy","short and ugly"]', '<b>Forlorn</b> = <b>lonely and unhappy</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('54baa332-3b86-4a28-a980-25078e28d251', 'Physics', 'JAMB', null, 1988, null, 'The speed of sound in air at sea-level is 340 m s⁻¹ while that of light is 300,000 km s⁻¹. How far (to the nearest metre) from the centre of a thunderstorm is an observer who hears a thunder 2 s after a lightning flash?', null, '["170 m","340 m","600 m","680 m."]', 3, 'Light arrives almost instantly, so the delay is the travel time of sound: d = 340 x 2 = 680 m.', true, '2026-10-12 19:15:27.745', '2026-10-12 19:15:27.745', null, null, null, 'The speed of sound in air at sea-level is 340 m s<sup>-1</sup> while that of light is 300,000 km s<sup>-1</sup>. How far (to the nearest metre) from the centre of a thunderstorm is an observer who hears a thunder 2 s after a lightning flash?', '["170 m","340 m","600 m","680 m."]', 'Light arrives almost instantly, so the delay is the travel time of sound: d = 340 x 2 = 680 m.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
