insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5624f9b4-9e9f-4df9-8d61-ad28e45db297', 'Chemistry', 'JAMB', null, 2026, null, 'The process used to concentrate cassiterite ore before extraction of tin is', null, '["froth flotation","magnetic separation","gravity separation","chemical reduction"]', 2, 'Cassiterite (SnO2) is a dense heavy tin ore efficiently concentrated using gravity separation methods like washing.', true, '2026-09-09 17:12:49.67', '2026-09-09 17:12:49.67', null, null, null, null, null, null, null);
