insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('563859c5-548f-458d-a1d1-6e7f83953252', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Oche entered the principal''s office in a rather <u>abrasive</u> manner.', null, '["gentle","lackadaisical","rude","indifferent"]', 0, 'Abrasive = harsh; opposite = gentle.', true, '2026-10-24 07:21:27.149', '2026-10-24 07:21:27.149', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Oche entered the principal''s office in a rather <u>abrasive</u> manner.', '["gentle","lackadaisical","rude","indifferent"]', 'Abrasive = harsh; opposite = gentle.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('564888d4-8213-4779-9afa-97e7fa6b972d', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The relationship between the couple has been <u>frosty</u>.', null, '["fraudulent","cordial","amenable","frugal"]', 1, 'Frosty = cold; opposite = cordial.', true, '2026-10-24 07:21:30.023', '2026-10-24 07:21:30.023', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The relationship between the couple has been <u>frosty</u>.', '["fraudulent","cordial","amenable","frugal"]', 'Frosty = cold; opposite = cordial.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('565a8afb-4263-40c2-ae1a-9097209d4b8a', 'Biology', 'JAMB', null, 2011, null, 'The enzyme involved in the hydrolysis is', null, '["rennin","erepsin","sucrase","maltase."]', 2, 'Sucrase is the enzyme involved in hydrolysis of cane sugar.', true, '2026-10-12 20:59:42.407', '2026-10-12 20:59:42.407', null, null, null, 'The enzyme involved in the hydrolysis is', '["rennin","erepsin","sucrase","maltase."]', 'Sucrase is the enzyme involved in hydrolysis of cane sugar.', '{"bold":["Sucrase"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5661292b-70f1-4356-a979-07312bd45516', 'English Language', 'JAMB', null, 2007, null, 'The government which <u>------------</u> recruiting <u>------------</u> workers suddenly stopped doing so.', null, '["are/its","was/its","is/their","were/their"]', 1, 'Past narration + singular government â†’ was/its.', true, '2026-10-24 01:02:14.841', '2026-10-24 01:02:14.841', null, null, null, 'The government which <u>------------</u> recruiting <u>------------</u> workers suddenly stopped doing so.', '["are/its","<u>was/its</u>","is/their","were/their"]', 'Past narration + singular <b>government</b> â†’ <b>was/its</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('56703358-4112-4ed8-8f1d-512953e60ce2', 'English Language', 'JAMB', null, 2007, null, 'Knowledge of figures of speech as well as of idioms and lexical items <u>-----</u> in this section.', null, '["is tested","have been tested","are tested","were tested"]', 0, '''As well as'' does not change singular ''Knowledge''.', true, '2026-10-24 01:02:12.53', '2026-10-24 01:02:12.53', null, null, null, 'Knowledge of figures of speech as well as of idioms and lexical items <u>-----</u> in this section.', '["<u>is tested</u>","have been tested","are tested","were tested"]', '''<b>As well as</b>'' does not change singular ''<b>Knowledge</b>''.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('567f1b39-4689-47e1-9f3f-41c47f77a69d', 'Chemistry', 'JAMB', null, 2026, null, 'A hydrocarbon contains 80% carbon and has a vapour density of 15. Determine its molecular formula.', null, '["CH₄","C₂H₆","C₂H₄","C₃H₆"]', 1, 'Empirical formula: C = 80/12 = 6.67, H = 20/1 = 20. Ratio = 1:3. Empirical formula = CH₃. Molar mass = 2 × 15 = 30. Molecular formula = C₂H₆.', true, '2026-09-12 11:35:48.155', '2026-09-12 11:35:48.155', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('568ecd04-2b88-4e09-9a43-194e653bff11', 'Government', 'JAMB', null, 2026, null, 'The central point of capitalism, as expounded by Karl Marx, is that', null, '["capitalist profit is the surplus value obtained from workers labour","workers are inherently incapable of being owners of their labour","capitalists shall always increase worker earning capacity through wages","capitalists shall always readily consent to workers welfare demands"]', 0, 'Marx argued capitalist profit is surplus value from workers'' labour.', true, '2026-09-12 11:24:33.558', '2026-09-12 11:24:33.558', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('569a3c16-1742-4924-9d86-d99425c3e6b5', 'Literature in English', 'JAMB', null, 2026, null, 'The poet''s use of the second-person address ''you'' in the latter part of the poem refers to', null, '["his father","his son","society","his childhood self"]', 1, 'The second-person address refers to his son.', true, '2026-09-12 11:10:40.776', '2026-09-12 11:10:40.776', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('56b197ff-4c5c-4c84-b5b1-f0048333451a', 'Physics', 'JAMB', null, 1997, null, 'A planet has mass m₁ and is at a distance r₁ from the sun. A second planet has mass m₂ = 10m₁ and is at a distance r₂ = 2r₁ from the sun. Determine the ratio of the gravitational force experienced by the planets.', null, '["1 : 5","2 : 5","3 : 5","4 : 5"]', 1, 'F is proportional to m/r². F₁:F₂ = (m₁/r₁²) : (10m₁/4r₁²) = 1 : 2.5 = 2 : 5.', true, '2026-10-12 19:15:42.924', '2026-10-12 19:15:42.924', null, null, null, 'A planet has mass m<sub>1</sub> and is at a distance r<sub>1</sub> from the sun. A second planet has mass m<sub>2</sub> = 10m<sub>1</sub> and is at a distance r<sub>2</sub> = 2r<sub>1</sub> from the sun. Determine the ratio of the gravitational force experienced by the planets.', '["1 : 5","2 : 5","3 : 5","4 : 5"]', 'F is proportional to m/r<sup>2</sup>. F<sub>1</sub>:F<sub>2</sub> = (m<sub>1</sub>/r<sub>1</sub><sup>2</sup>) : (10m<sub>1</sub>/4r<sub>1</sub><sup>2</sup>) = 1 : 2.5 = 2 : 5.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
