insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('56c82224-c006-4c2f-b54d-505c4fe359c4', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The dispute between the two countries has resulted in the <u>severing</u> of diplomatic relations', null, '["breaking","securing","swapping","strengthening"]', 0, 'Severing = breaking.', true, '2026-10-24 01:04:12.58', '2026-10-24 01:04:12.58', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The dispute between the two countries has resulted in the <u>severing</u> of diplomatic relations', '["<u>breaking</u>","securing","swapping","strengthening"]', '<b>Severing</b> = <b>breaking</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('56cd05b9-276c-4717-a752-9c2d939c3665', 'Government', 'JAMB', null, 2026, null, 'The local governments were to be elected for _ number of years under the 1976 local government reform', null, '["4","5","3","2"]', 2, 'Under the 1976 local government reform, local governments were to be elected for a period of 3 years. The 1976 Local Government Reform introduced a uniform system of local government administration throughout Nigeria. It provided for elected local government councils with a three-year term. This reform was a major step in decentralizing governance and promoting grassroots development.', true, '2026-09-10 10:45:06.09', '2026-09-10 10:45:06.09', null, null, null, null, null, null, null);
