insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('56e19cc1-b73a-4dcd-b15e-877e0ec51a60', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Events in South Africa indicate a kind of political <u>renascence</u>.', null, '["rejuvenation","decline","turbulence","upheaval"]', 1, 'Renascence = rebirth; opposite = decline.', true, '2026-10-24 07:21:19.023', '2026-10-24 07:21:19.023', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Events in South Africa indicate a kind of political <u>renascence</u>.', '["rejuvenation","decline","turbulence","upheaval"]', 'Renascence = rebirth; opposite = decline.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('56ef63a1-6b95-4784-a791-8ed5acc11171', 'Biology', 'JAMB', null, 2002, null, 'The capture and digestion of insects by a pitcher plant is a special form of nutrition termed', null, '["autotrophic","heterotrophic","chemosynthetic","Saprophytic"]', 1, 'Pitcher plants are heterotrophic by capturing and digesting insects.', true, '2026-10-12 20:59:31.269', '2026-10-12 20:59:31.269', null, null, null, 'The capture and digestion of insects by a pitcher plant is a special form of nutrition termed', '["autotrophic","heterotrophic","chemosynthetic","Saprophytic"]', 'Pitcher plants are heterotrophic by capturing and digesting insects.', '{"bold":["heterotrophic"],"italic":[],"underline":[],"fillBlanks":[]}');
