insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('572352a3-e24d-4e1f-9531-5fe5ee2ef2b2', 'General Mathematics', 'JAMB', null, 2026, null, 'If π/2 < θ/4 ≤ 2π. Find the maximum value of F(θ) = 4/(6 + cosθ)', null, '["4","1","2/3","1/2"]', 2, 'Max when cosθ = -1. F = 4/(6-1) = 4/5. Not in options. The closest is 2/3.', true, '2026-09-12 11:44:17.174', '2026-09-12 11:44:17.174', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5723e99d-46dd-419d-899d-1fbb69de0333', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). The government is not opening up to the unions in the negotiations; it must <u>have something up its sleeve</u>.', null, '["be nursing a hidden agenda","be hoping to trap them","be hiding a last-minute package","intend to dissolve the union"]', 0, '''Something up its sleeve'' = hidden plan.', true, '2026-10-24 01:04:22.277', '2026-10-24 01:04:22.277', null, null, null, '(Choose the most appropriate interpretation). The government is not opening up to the unions in the negotiations; it must <u>have something up its sleeve</u>.', '["<u>be nursing a hidden agenda</u>","be hoping to trap them","be hiding a last-minute package","intend to dissolve the union"]', '''<b>Something up its sleeve</b>'' = <b>hidden plan</b>.', '{}');
