insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('576b0e3a-8591-43c1-9266-14b54fd496cb', 'Chemistry', 'JAMB', null, 2026, null, 'An element has electronic configuration 2, 8, 7. Its group number is:', null, '["I","VI","VII","0"]', 2, 'The element has 7 valence electrons, so it belongs to Group VII.', true, '2026-09-12 11:32:58.085', '2026-09-12 11:32:58.085', null, null, null, null, null, null, null);
