insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('577c06a4-17d1-4e20-907d-0fcf5bc69fc8', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Everyone, including the Principal, believed that he was a very <u>assiduous</u> student.', null, '["assertive","industrious","aggressive","casual"]', 3, 'Assiduous = diligent; opposite = casual.', true, '2026-10-24 07:21:19.477', '2026-10-24 07:21:19.477', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Everyone, including the Principal, believed that he was a very <u>assiduous</u> student.', '["assertive","industrious","aggressive","casual"]', 'Assiduous = diligent; opposite = casual.', '{}');
