insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('578ab09e-3a7a-43ae-97e9-d7517f18d421', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Which set of these disciples were with Jesus on the mountain of transfiguration?', null, '["Philip, John and Peter","Peter, James, and John","Peter, Andrew, and James","John, Philip and James","Andrew, Philip and James"]', 1, 'Peter, James, and John witnessed the transfiguration.', true, '2026-09-12 10:42:11.813', '2026-09-12 10:42:11.813', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('57a04a3c-1a33-47af-8380-2091bc971a7c', 'Biology', 'JAMB', null, 2001, null, 'The stem of a typical aquatic plant usually has many', null, '["water cavities","water-conducting cells","air cavities","intercellular spaces"]', 2, 'Aquatic plant stems have air cavities for buoyancy.', true, '2026-10-12 20:59:29.726', '2026-10-12 20:59:29.726', null, null, null, 'The stem of a typical aquatic plant usually has many', '["water cavities","water-conducting cells","air cavities","intercellular spaces"]', 'Aquatic plant stems have air cavities for buoyancy.', '{"bold":["air cavities"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('57a11b81-b953-4dcd-af1c-50c1ede833a7', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Who baptized the Ethiopian Eunuch?', null, '["John","Paul","Peter","Philip"]', 3, 'Philip baptized the Ethiopian Eunuch. An angel directed Philip to the road from Jerusalem to Gaza, where he met the Ethiopian official reading Isaiah. Philip explained the scripture, and the Eunuch believed and was baptized.', true, '2026-09-12 09:45:49.474', '2026-09-12 09:45:49.474', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('57af482c-5839-42ac-a81d-b2f9622b8574', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. <u>Gregarious</u> animals can be found in the zoo.', null, '["Various","Wild","Lonely","Tame"]', 2, 'Gregarious = sociable; opposite = lonely.', true, '2026-10-24 07:21:24.276', '2026-10-24 07:21:24.276', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. <u>Gregarious</u> animals can be found in the zoo.', '["Various","Wild","Lonely","Tame"]', 'Gregarious = sociable; opposite = lonely.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('57c28a58-76f5-49ce-a396-353e1c6c3080', 'Government', 'JAMB', null, 2026, null, 'The chief executive of the Royal Niger Company was', null, '["Lord Lugard","John Freeman","Tubman Goldie","Samuel Cookery"]', 2, 'Tubman Goldie was the chief executive of the Royal Niger Company.', true, '2026-09-12 11:24:15.262', '2026-09-12 11:24:15.262', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('57cbbaf9-bb55-44cf-b3c4-81cccf006889', 'Chemistry', 'JAMB', null, 2026, null, 'A sample of gas occupies 500 cm³ at 27°C. If the temperature is increased to 327°C at constant pressure, what will be the new volume?', null, '["750 cm³","1000 cm³","833 cm³","1200 cm³"]', 1, 'Using Charles''s Law: V₁/T₁ = V₂/T₂. T₁ = 27 + 273 = 300K, T₂ = 327 + 273 = 600K. V₂ = V₁ × T₂/T₁ = 500 × 600/300 = 1000 cm³.', true, '2026-09-12 09:38:08.229', '2026-09-12 09:38:08.229', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('57d5acf9-e185-4856-a8ca-772de447f535', 'English Language', 'JAMB', null, 2024, null, 'Ibrahim''s flamboyant lifestyle contrasts sharply with Aminu''s ______ attitude', null, '["austere","ostentatious","serious","lavish"]', 0, '"Austere" means simple and plain, contrasting with "flamboyant."', true, '2026-09-18 09:43:02.465', '2026-09-18 09:43:02.465', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('57ec725f-ec4e-4e9b-bb27-b3f897670c9c', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Her <u>ingenuous</u> smile drew our attention.', null, '["naive","clever","arrogant","witty"]', 1, 'Ingenuous = naive; opposite = clever.', true, '2026-10-24 07:21:26.235', '2026-10-24 07:21:26.235', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Her <u>ingenuous</u> smile drew our attention.', '["naive","clever","arrogant","witty"]', 'Ingenuous = naive; opposite = clever.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('57fe9645-a69a-4d24-857c-daf2df52227b', 'Chemistry', 'JAMB', null, 2026, null, 'When excess sodium hydroxide is added to zinc hydroxide precipitate, it dissolves because zinc hydroxide is', null, '["acidic","amphoteric","neutral","basic"]', 1, 'Zinc hydroxide is amphoteric and reacts with excess hydroxide ions to form a soluble zincate complex ion, [Zn(OH)4]2-.', true, '2026-09-09 17:12:49.267', '2026-09-09 17:12:49.267', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('580f7e05-b3be-4299-bbf7-aff17fc860b9', 'English Language', 'JAMB', null, 2024, null, '30', null, '["storage","detoxification","purification","cleansing"]', 1, 'Detoxification is a key function of the liver.', true, '2026-09-18 10:17:48.927', '2026-09-18 10:17:48.927', '5c9f355e-7680-453e-a8bf-38eba91547e7', 6, 'CLOZE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5810faf1-364e-4d81-b208-9baffef269e0', 'General Mathematics', 'JAMB', null, 2026, null, 'From a point P, the bearing of two points Q and R are N67°W and N23°E respectively. If the bearing of R from Q is N68°E and PQ = 150m, calculate PR', null, '["120m","140m","150m","160m","150m²"]', 1, 'Angle QPR = 67+23 = 90°. Angle PQR = 180-67-68 = 45°. Using sine rule: PR/sin45 = 150/sin45. PR = 150. The answer is (C) 150m.', true, '2026-09-12 11:44:24.624', '2026-09-12 11:44:24.624', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5816fde3-63b0-4bc9-b674-b097168e4fbe', 'English Language', 'JAMB', null, 2024, null, '53', null, '["Way","Temperature","Class","Profile"]', 1, '"High temperature" is the correct collocation.', true, '2026-09-18 10:17:48.895', '2026-09-18 10:17:48.895', 'decfd2ca-8924-4681-ba7c-9a039e9bda97', 6, 'CLOZE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('58179682-a972-4ed9-a4c0-9bd75c8efa0d', 'Government', 'JAMB', null, 2026, null, 'In the United States, what do they call by-election?', null, '["special election","by polls","general election","recall"]', 0, 'In the US, a by-election is called a special election.', true, '2026-09-12 11:24:57.953', '2026-09-12 11:24:57.953', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('58199637-52f8-4662-852a-329282f620dc', 'English Language', 'JAMB', null, 2024, null, 'How does Mrs. Gloss'' leadership style reflect her reaction to the discovery of the cars?', null, '["she is authoritative and wants to maintain control","she is lenient and understanding","she is passive and indecisive","she is carefree and unconcerned"]', 0, 'Mrs. Gloss is authoritative and wants to maintain control.', true, '2026-09-18 09:43:02.782', '2026-09-18 09:43:02.782', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('581d54f7-1b77-4b11-b262-4a61f9a2b673', 'General Mathematics', 'JAMB', null, 2026, null, 'If log₂3 = x, express log₂96 - 2log₂64 in terms of x', null, '["x - 3","3 - x","2x - 3","3 - 2x"]', 0, 'log₂96 = log₂(32×3) = log₂32 + log₂3 = 5 + x. 2log₂64 = 2×6 = 12. So log₂96 - 2log₂64 = 5 + x - 12 = x - 7. Not in options. Let me recalculate: log₂64 = 6, 2log₂64 = 12. log₂96 = log₂(32×3) = 5 + x. So 5 + x - 12 = x - 7. Not in options. The closest is x - 3. The question may have a typo.', true, '2026-09-10 10:48:19.589', '2026-09-10 10:48:19.589', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('581f3ae5-c817-422d-91dd-184b9735f7a6', 'English Language', 'JAMB', null, 2007, null, 'Three-quarters of the people in the village <u>------------</u> killed but only half of their huts <u>------------</u> affected.', null, '["were/were","was/was","were/was","was/were"]', 0, 'Both people and huts plural â†’ were/were.', true, '2026-10-24 01:02:15.227', '2026-10-24 01:02:15.227', null, null, null, 'Three-quarters of the people in the village <u>------------</u> killed but only half of their huts <u>------------</u> affected.', '["<u>were/were</u>","was/was","were/was","was/were"]', 'Both <b>people</b> and <b>huts</b> plural â†’ <b>were/were</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('582a5152-59a9-4d43-aae7-80ad522aec58', 'Economics', 'JAMB', null, 2026, null, 'Completely competitive market exists when each member is a?', null, '["Price seeker","Price taker","Price maker","Price breaker"]', 1, 'In a perfectly competitive market, each firm is a price taker.', true, '2026-09-12 10:58:46.425', '2026-09-12 10:58:46.425', null, null, null, null, null, null, null);
