insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('582dc90a-6bd2-4fa6-a582-d7ecc913f55a', 'English Language', 'JAMB', null, 2007, null, 'Although the Officer wanted a <u>__________</u> report on the matter, he got <u>__________</u> account', null, '["truthful/uninteresting","factual/an unpleasant","genuine/a ridiculous","painstaking/a half-hearted"]', 3, 'Correct forms: painstaking/a half-hearted.', true, '2026-10-24 07:21:45.274', '2026-10-24 07:21:45.274', null, null, null, 'Although the Officer wanted a <u>__________</u> report on the matter, he got <u>__________</u> account', '["truthful/uninteresting","factual/an unpleasant","genuine/a ridiculous","painstaking/a half-hearted"]', 'Correct forms: painstaking/a half-hearted.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('583892d6-d7c9-4192-a7a8-b70611ef249b', 'English Language', 'JAMB', null, 2007, null, 'I hereby declare and <u>__________</u> that, to the best of my knowledge, this statement is true in all respects', null, '["inform","confirm","affirm","conform"]', 2, 'Correct spelling: affirm.', true, '2026-10-24 07:21:44.017', '2026-10-24 07:21:44.017', null, null, null, 'I hereby declare and <u>__________</u> that, to the best of my knowledge, this statement is true in all respects', '["inform","confirm","affirm","conform"]', 'Correct spelling: affirm.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('58435647-caf1-4c6a-880c-79f2b5afe278', 'Christian Religious Studies', 'JAMB', null, 2026, null, '“I heard the sound of thee in the garden, and I was afraid, because I was naked, and I hid myself''''. The question that immediately followed this statement was...', null, '["''''what is this that you have done?''''","''''who told you that you were naked?''''","''''where are you?''''","''''Have you eaten of the tree of which I commanded you not to eat?''''"]', 1, 'Genesis 3:10-11 records God immediately asking: ''Who told you that you were naked? Have you eaten from the tree of which I commanded you not to eat?''', true, '2026-09-09 17:18:26.51', '2026-09-09 17:18:26.51', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('58443750-f49a-411f-8a02-978e8a7913c5', 'Biology', 'JAMB', null, 2005, null, 'In the root vascular system, the stele is directly surrounded by the', null, '["pericycle","cortex","endodermis","parenchyma"]', 2, 'The stele is directly surrounded by the endodermis.', true, '2026-10-12 20:59:37.175', '2026-10-12 20:59:37.175', null, null, null, 'In the root vascular system, the stele is directly surrounded by the', '["pericycle","cortex","endodermis","parenchyma"]', 'The stele is directly surrounded by the endodermis.', '{"bold":["endodermis"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('584b3261-1171-493b-b7cb-723401ea078d', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'When the people of Israel did what was evil in the sight of the Lord, he gave them into the hand of the Philistines for', null, '["twenty years","thirty years","forty years","fifty years"]', 2, 'God gave Israel into Philistine hands for forty years.', true, '2026-09-12 10:41:36.662', '2026-09-12 10:41:36.662', null, null, null, null, null, null, null);
