insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('585f0c46-a43d-440d-9be4-859757f92643', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The economic situation is responsible for the recent <u>discord</u> in many families.', null, '["division","resourcefulness","harmony","suffering"]', 2, 'Discord = disagreement; opposite = harmony.', true, '2026-10-24 07:21:15.04', '2026-10-24 07:21:15.04', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The economic situation is responsible for the recent <u>discord</u> in many families.', '["division","resourcefulness","harmony","suffering"]', 'Discord = disagreement; opposite = harmony.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5863e2f4-6083-4890-910a-1835185595d4', 'General Mathematics', 'JAMB', null, 2026, null, 'What is the area between two concentric circles of diameters 26cm and 20cm?', null, '["100π","69π","68π","9π","269π"]', 1, 'Radius of larger circle = 13cm, smaller = 10cm. Area between = π(13² - 10²) = π(169-100) = 69π.', true, '2026-09-10 10:48:20.178', '2026-09-10 10:48:20.178', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('586e982c-fc61-4a8e-9529-dfcb2fca4d68', 'English Language', 'JAMB', null, 2007, null, 'A survey of opinions on how pupils feel about their teachers <u>-------------</u> carried out.', null, '["has been","have been","are being","is been"]', 0, 'Singular ''survey'' â†’ has been.', true, '2026-10-24 01:02:13.373', '2026-10-24 01:02:13.373', null, null, null, 'A survey of opinions on how pupils feel about their teachers <u>-------------</u> carried out.', '["<u>has been</u>","have been","are being","is been"]', 'Singular ''<b>survey</b>'' â†’ <b>has been</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('587865ac-fbce-4fd6-b01c-a6a1b97e9ab7', 'English Language', 'JAMB', null, 2024, null, 'According to the writer, a study of the humanities', null, '["Is accepted by present day students essential","Prepares students for specific careers","Provides missing link in the technological education of our students","Is the best solution to the problem of unemployment"]', 2, 'The passage states that the humanities provide a missing link in technological education by teaching students how to think.', true, '2026-09-18 09:43:02.612', '2026-09-18 09:43:02.612', null, null, 'COMPREHENSION', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('58875142-7f0f-44a8-b990-e3ed8fd00907', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). Osyaku <u>started playing</u> football because he thought it would develop him physically.', null, '["took up football","picked up football","returned to football","took up with football","put in for football"]', 0, '''Took up'' = started.', true, '2026-10-24 01:04:14.678', '2026-10-24 01:04:14.678', null, null, null, '(Choose the most appropriate interpretation). Osyaku <u>started playing</u> football because he thought it would develop him physically.', '["<u>took up football</u>","picked up football","returned to football","took up with football","put in for football"]', '''<b>Took up</b>'' = <b>started</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('58a815d3-32a5-40f3-9a21-7824592b9a71', 'Government', 'JAMB', null, 2026, null, 'Lagos was first amalgamated with the Western Region as a result of the', null, '["Clifford Constitution (1922)","Richard Constitution (1946)","Macpherson Constitution (1951)","Lyttleton Constitution (1954)","Independence Constitution (1960)"]', 1, 'Lagos was first amalgamated with the Western Region as a result of the Richard Constitution (1946). The Richards Constitution divided Nigeria into three regions: Northern, Western, and Eastern. Lagos, which was previously a separate colony, was merged with the Western Region for administrative purposes. This arrangement continued until 1954 when Lagos was made a federal territory again under the Lyttleton Constitution.', true, '2026-09-10 10:44:19.413', '2026-09-10 10:44:19.413', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('58acdf58-7a66-473c-a43a-1158fc6b29da', 'Biology', 'JAMB', null, 2004, null, 'Sex-linked genes are located on', null, '["Y-chromosome","X-and Y-chromosomes","homologous chromosomes","X-chromosome"]', 3, 'Sex-linked genes are located on the X-chromosome.', true, '2026-10-12 20:59:35.939', '2026-10-12 20:59:35.939', null, null, null, 'Sex-linked genes are located on', '["Y-chromosome","X-and Y-chromosomes","homologous chromosomes","X-chromosome"]', 'Sex-linked genes are located on the X-chromosome.', '{"bold":["X-chromosome"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('58b14b9a-c40e-4f1e-b070-18f6ef9b70b4', 'General Mathematics', 'JAMB', null, 2026, null, 'The remainder when 6p³ - p² - 47p + 30 is divided by p - 3 is', null, '["21","42","63","18"]', 1, 'f(3) = 6(27) - 9 - 141 + 30 = 162-9-141+30 = 42.', true, '2026-09-12 11:44:04.892', '2026-09-12 11:44:04.892', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('58b16b92-bd33-48c5-bf75-2646638e9498', 'Economics', 'JAMB', null, 2026, null, 'The burden of tax on a good whose demand is infinitely inelastic is', null, '["zero","will be borne by the seller alone","will be borne by the buyers alone","impossible to tell"]', 2, 'The burden of tax on a good whose demand is infinitely inelastic will be borne by the buyers alone. When demand is perfectly inelastic (vertical demand curve), consumers will buy the same quantity regardless of price. If a tax is imposed, producers can pass the entire tax burden to consumers in the form of higher prices without losing sales. Buyers bear the full burden of the tax.', true, '2026-09-10 10:42:55.4', '2026-09-10 10:42:55.4', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('58c68be6-87ed-4f22-a3bf-073dbe07fa84', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'The name ''Moses'' means', null, '["the loved child of Pharaoh","God heard our groaning","I have been a sojourner in a foreign land","my beloved child of old age","because I drew him out of water"]', 4, 'The name Moses means ''because I drew him out of water.'' Pharaoh''s daughter named him Moses, saying, ''Because I drew him out of the water.''', true, '2026-09-12 09:46:00.13', '2026-09-12 09:46:00.13', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('58cf377e-89c8-4a31-ab54-e6d27d8b9ca8', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). Employees have been <u>urged to desist from witch-hunting and character assassination</u>.', null, '["commanded to stop hunting witches","ordered to stop assassinating witches","entreated not to accuse individuals unjustly and maliciously","informed to resist witch hunters and character assassins","urged to desist from barbaric acts"]', 2, '''Character assassination'' = malicious accusation.', true, '2026-10-24 01:04:16.321', '2026-10-24 01:04:16.321', null, null, null, '(Choose the most appropriate interpretation). Employees have been <u>urged to desist from witch-hunting and character assassination</u>.', '["commanded to stop hunting witches","ordered to stop assassinating witches","<u>entreated not to accuse individuals unjustly and maliciously</u>","informed to resist witch hunters and character assassins","urged to desist from barbaric acts"]', '''<b>Character assassination</b>'' = <b>malicious accusation</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('58d5bec9-563f-40b4-bf42-4a531b2fc390', 'Biology', 'JAMB', null, 2026, null, 'During ovulation, an egg is released from the', null, '["Corpus luteum","Ovarian funnel","Graafian follicle","Fallopian tube"]', 2, 'Ovulation is the release of a mature ovum (egg) from the Graafian follicle, a fluid-filled sac in the ovary. The follicle matures under the influence of FSH (follicle-stimulating hormone) and LH (luteinizing hormone). After ovulation, the ruptured follicle transforms into the corpus luteum, which produces progesterone to maintain the uterine lining for potential implantation. The ovarian funnel (infundibulum) catches the released egg and directs it into the fallopian tube, where fertilization typically occurs. The egg is not released from these structures.', true, '2026-09-09 03:18:22.328', '2026-09-09 03:18:22.328', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('58d9cde8-2ffb-44c3-b157-1dc4623c448a', 'Economics', 'JAMB', null, 2026, null, 'Goods sold in perfectly competitive markets are generally', null, '["Durable","Heterogeneous","Homogenous","Intermediate"]', 2, 'Goods in perfectly competitive markets are homogeneous (identical).', true, '2026-09-12 10:58:46.089', '2026-09-12 10:58:46.089', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('58dc6ff2-ac7d-42c5-8370-e77ba12ff61d', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The manager made <u>disparaging</u> remarks about the retiring officer.', null, '["parochial","cynical","derogatory","rude"]', 2, 'Disparaging = derogatory.', true, '2026-10-24 01:01:51.453', '2026-10-24 01:01:51.453', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The manager made <u>disparaging</u> remarks about the retiring officer.', '["parochial","cynical","<u>derogatory</u>","rude"]', '<b>Disparaging</b> = <b>derogatory</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('58e6ddf8-e40e-413b-ad63-8acebce6b7aa', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Bola has <u>sonorous</u> voice.', null, '["high-pitched","beautiful","strong","throaty"]', 2, 'Sonorous = strong and deep.', true, '2026-10-24 01:01:42.765', '2026-10-24 01:01:42.765', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Bola has <u>sonorous</u> voice.', '["high-pitched","beautiful","<u>strong</u>","throaty"]', '<b>Sonorous</b> = <b>strong</b> and deep.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('58f26605-36f7-476b-8978-4bb983b58a8b', 'English Language', 'JAMB', null, 2007, null, 'The quality of your questions which <u>------------</u> always attracted attention <u>------------</u> never been in doubt.', null, '["have/has","have/have","has/has","has/have"]', 0, '''Which'' â†’ questions (have); ''quality'' singular (has).', true, '2026-10-24 01:02:15.173', '2026-10-24 01:02:15.173', null, null, null, 'The quality of your questions which <u>------------</u> always attracted attention <u>------------</u> never been in doubt.', '["<u>have/has</u>","have/have","has/has","has/have"]', '''<b>Which</b>'' â†’ <b>questions</b> (<b>have</b>); ''<b>quality</b>'' singular (<b>has</b>).', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('58f64d4e-b350-4f33-a38f-71ebede5b13b', 'Physics', 'JAMB', null, 2026, null, 'The bond that forms a semiconductor is', null, '["covalent","electrovalent","ionic","metallic"]', 0, 'The bond that forms a semiconductor is covalent. Semiconductor materials like silicon and germanium form covalent bonds where atoms share electrons.', true, '2026-09-10 10:56:49.608', '2026-09-10 10:56:49.608', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('58f7c8af-be71-4ea2-a2c8-aa50211f6c01', 'Literature in English', 'JAMB', null, 2026, null, 'The central message of Not My Business is', null, '["The importance of economic growth","The inevitability of fate","The beauty of communal living","The danger of apathy in the face of injustice"]', 3, 'The central message is the danger of apathy in the face of injustice.', true, '2026-09-12 11:05:27.722', '2026-09-12 11:05:27.722', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('58f7e51d-34fb-4e64-a300-67813dfd85fe', 'English Language', 'JAMB', null, 2007, null, 'We must not take with us the feelings of inadequacy <u>------------</u> experienced during our preparations for the debate.', null, '["that were","those were","that was","that is"]', 0, '''Feelings'' plural â†’ that were.', true, '2026-10-24 01:02:12.163', '2026-10-24 01:02:12.163', null, null, null, 'We must not take with us the feelings of inadequacy <u>------------</u> experienced during our preparations for the debate.', '["<u>that were</u>","those were","that was","that is"]', '''<b>Feelings</b>'' plural â†’ <b>that were</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('58fab8ac-1314-4b83-8439-fbe98841858e', 'Biology', 'JAMB', null, 2011, null, 'The gas evolved in the process is', null, '["carbon (IV) oxide","nitrogen","oxygen","carbon (II) oxide."]', 0, 'Carbon (IV) oxide is evolved in the process.', true, '2026-10-12 20:59:41.9', '2026-10-12 20:59:41.9', null, null, null, 'The gas evolved in the process is', '["carbon (IV) oxide","nitrogen","oxygen","carbon (II) oxide."]', 'Carbon (IV) oxide is evolved in the process.', '{"bold":["Carbon (IV) oxide"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('58ff1894-ebba-4f36-ac76-7308fd79923a', 'Hausa', 'JAMB', null, 2010, null, 'A karkara da ma wasu manyan garuruwa kalilan, mutane kan hadu su rika cin abinci tare. Akan zabi gidan mutum daya daga cikinsu ya zama shi ne matattara. Mutumin da aka zabi gidansa, kusan shi ne shugaba, kuma ya fi kowa yawan shekaru. A wasu lokuta kuma, ana duba gidan da ya fi yalwa, ko ya fi zama kan hanya, babu wahala sosi zuwa gidan, musamman da damina. A wurin haduwa a ci abinci tare, kowane magidanci zai kawo abincin da aka dafa a gidansa, wanda ya fi shiga. Nan fa matan da suka kware suke shan yabo da godiya. Wadanda ba su iya ba kuwa, aiki ya gan su da kuma takaici. Saboda wasu mazan kan yi wa matansu gori. Ba nan ma abin ya tsaya ba, rashin iya abincin nan na iya haddasa mutuwar aure, idan ba a kai hankali nesa ba. Al''amari ya yi muni ke nan. Cikin abubuwan da ake kawowa, akwai tuwo da shinkafa da fate da dan wake da dambu da alkubus da doya da taliya da kuma makaroni. Ana kawo wasu daga cikin wadannan nau''o''in abinci tare da miya, wasu kuma a siffar dafa-duka. Duka dai wannan, ya danganta da irin cefanen da maigida ya yi. Akwai alfanu babba game da wannan zama. Da farko, akwai kyautata dangantaka da zaman tare. Ana kuma taimakon juna ta hanyar tattaua matsalolin da suka addabe su. Wanda ma ba ya da karfin yin abinci wani lokaci, ba zai tagayyara ba, zai sami abin da zai ci a wajen. Mutumin da ake haduwa, a ci abinci gidansa, yana matsayin', null, '["wakili","shugaba","malami","hakimi."]', 1, 'Mutumin da ake haduwa a gidansa yana matsayin shugaba.', true, '2026-10-13 10:37:23.18', '2026-10-13 10:37:23.18', null, null, null, 'A karkara da ma wasu manyan garuruwa kalilan, mutane kan hadu su rika cin abinci tare. Akan zabi gidan mutum daya daga cikinsu ya zama shi ne matattara. Mutumin da aka zabi gidansa, kusan shi ne shugaba, kuma ya fi kowa yawan shekaru. A wasu lokuta kuma, ana duba gidan da ya fi yalwa, ko ya fi zama kan hanya, babu wahala sosi zuwa gidan, musamman da damina. A wurin haduwa a ci abinci tare, kowane magidanci zai kawo abincin da aka dafa a gidansa, wanda ya fi shiga. Nan fa matan da suka kware suke shan yabo da godiya. Wadanda ba su iya ba kuwa, aiki ya gan su da kuma takaici. Saboda wasu mazan kan yi wa matansu gori. Ba nan ma abin ya tsaya ba, rashin iya abincin nan na iya haddasa mutuwar aure, idan ba a kai hankali nesa ba. Al''amari ya yi muni ke nan. Cikin abubuwan da ake kawowa, akwai tuwo da shinkafa da fate da dan wake da dambu da alkubus da doya da taliya da kuma makaroni. Ana kawo wasu daga cikin wadannan nau''o''in abinci tare da miya, wasu kuma a siffar dafa-duka. Duka dai wannan, ya danganta da irin cefanen da maigida ya yi. Akwai alfanu babba game da wannan zama. Da farko, akwai kyautata dangantaka da zaman tare. Ana kuma taimakon juna ta hanyar tattaua matsalolin da suka addabe su. Wanda ma ba ya da karfin yin abinci wani lokaci, ba zai tagayyara ba, zai sami abin da zai ci a wajen. Mutumin da ake haduwa, a ci abinci gidansa, yana matsayin', '["wakili","shugaba","malami","hakimi."]', 'Mutumin da ake haduwa a gidansa yana matsayin shugaba.', '{"bold":["shugaba"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('590262d2-ad73-4fda-8caa-e8b47eee44ef', 'Biology', 'JAMB', null, 2004, null, 'The scarcity of food causes a sudden decrease in population size by', null, '["decreasing the reproductive rate","bringing about immigration","raising the mortality rate","minimizing the rate of competition"]', 2, 'Food scarcity raises the mortality rate.', true, '2026-10-12 20:59:35.63', '2026-10-12 20:59:35.63', null, null, null, 'The scarcity of food causes a sudden decrease in population size by', '["decreasing the reproductive rate","bringing about immigration","raising the mortality rate","minimizing the rate of competition"]', 'Food scarcity raises the mortality rate.', '{"bold":["raises the mortality rate"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5908d5b3-b743-4b17-8816-6abae6b48338', 'Economics', 'JAMB', null, 2026, null, 'The residual of production which accrues to the ownership of land after all other expenses have been met is called', null, '["wages","profit","rent","interest","discount"]', 2, 'Economic rent is the residual payment to land after all other production costs have been deducted. It is the surplus that remains after paying for labour (wages), capital (interest), and entrepreneurship (profit). This is the classical economic definition of rent as a surplus. Rent arises because land is fixed in supply and has different levels of fertility.', true, '2026-09-10 10:41:19.646', '2026-09-10 10:41:19.646', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('590bedf7-6c8d-4bce-bd79-713577d9fbfc', 'Literature in English', 'JAMB', null, 2026, null, 'The poet''s relationship with the sea suggests', null, '["fear and hostility","emotional attachment","indifference","rivalry"]', 1, 'The relationship suggests emotional attachment.', true, '2026-09-12 11:10:14.525', '2026-09-12 11:10:14.525', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('590d68a1-3815-4814-9927-29bd96ee6c71', 'English Language', 'JAMB', null, 2024, null, 'According to the passage, the different approaches to conflict management are', null, '["uniform","pernicious","fundamental","misleading"]', 2, 'The approaches are fundamental to conflict management.', true, '2026-09-18 09:43:02.748', '2026-09-18 09:43:02.748', null, null, 'COMPREHENSION', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('59148eb7-1eb2-4c39-bed5-324d59cfd8c8', 'General Mathematics', 'JAMB', null, 2026, null, 'A cylinder of height h and radius r is open at one end. Its surface area is', null, '["2πrh","πr²h","2πrh + 2πr²","2πrh + πr²"]', 3, 'Open cylinder: curved surface + one base = 2πrh + πr².', true, '2026-09-12 11:43:45.767', '2026-09-12 11:43:45.767', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('59264a73-ce95-4667-a05f-1754c9846157', 'Economics', 'JAMB', null, 2026, null, 'If price is increased to N = 3, how much is the excess supply?', null, '["30","22","12","8"]', 1, 'At p = 3: Qd = 20 - 4(3) = 20 - 12 = 8. Qs = 6(3) + 12 = 18 + 12 = 30. Excess supply = Qs - Qd = 30 - 8 = 22. Therefore, the excess supply is 22.', true, '2026-09-10 10:41:59.966', '2026-09-10 10:41:59.966', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('592bfe91-6275-40fa-be1b-16ac81f12ec6', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). Some men will continue to cause offenses until they are <u>given a taste of their own medicine</u>.', null, '["placated","recompensed for","revenged on","cured"]', 2, '''Given a taste of their own medicine'' = revenged on.', true, '2026-10-24 01:04:23.027', '2026-10-24 01:04:23.027', null, null, null, '(Choose the most appropriate interpretation). Some men will continue to cause offenses until they are <u>given a taste of their own medicine</u>.', '["placated","recompensed for","<u>revenged on</u>","cured"]', '''<b>Given a taste of their own medicine</b>'' = <b>revenged on</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('594248ad-1d83-4584-a8ff-fa064ff6eda3', 'Physics', 'JAMB', null, 2002, null, 'If the distance between two suspended masses of 10 kg each is tripled, the gravitational force of attraction between them is reduced by', null, '["One ninth","One quarter","One third","One half"]', 0, 'F is proportional to 1/r². Tripling r makes the force 1/9 of its original value.', true, '2026-10-12 19:15:52.998', '2026-10-12 19:15:52.998', null, null, null, 'If the distance between two suspended masses of 10 kg each is tripled, the gravitational force of attraction between them is reduced by', '["One ninth","One quarter","One third","One half"]', 'F is proportional to 1/r<sup>2</sup>. Tripling r makes the force 1/9 of its original value.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5946d6b7-e409-401d-884b-5e13b40adb73', 'English Language', 'JAMB', null, 2007, null, 'The lecturer insisted that every student <u>_______</u> present for the practical examination.', null, '["is","was","be","were","are"]', 2, '''Insisted that'' triggers subjunctive be.', true, '2026-10-24 01:02:12.11', '2026-10-24 01:02:12.11', null, null, null, 'The lecturer insisted that every student <u>_______</u> present for the practical examination.', '["is","was","<u>be</u>","were","are"]', '''<b>Insisted that</b>'' triggers subjunctive <b>be</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('595a39aa-93b8-48bc-b7e4-4ac1d3e41248', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The Lions lost the match because their goalkeeper was <u>in a haze</u> most of the time.', null, '["indisposed","confused","alert","sleeping"]', 2, 'In a haze = confused; opposite = alert.', true, '2026-10-24 07:21:11.875', '2026-10-24 07:21:11.875', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The Lions lost the match because their goalkeeper was <u>in a haze</u> most of the time.', '["indisposed","confused","alert","sleeping"]', 'In a haze = confused; opposite = alert.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('595c6cc5-42f2-45e5-93ec-b06ba9ff4d23', 'Physics', 'JAMB', null, 2000, null, 'Light of energy 5 eV falls on a metal of work function 3 eV and electrons are liberated. The stopping potential is', null, '["15.0 V","8.0 V","2.0 V","1.7 V"]', 2, 'Maximum kinetic energy = 5 - 3 = 2 eV, so the stopping potential is 2.0 V.', true, '2026-10-12 19:15:50.503', '2026-10-12 19:15:50.503', null, null, null, 'Light of energy 5 eV falls on a metal of work function 3 eV and electrons are liberated. The stopping potential is', '["15.0 V","8.0 V","2.0 V","1.7 V"]', 'Maximum kinetic energy = 5 - 3 = 2 eV, so the stopping potential is 2.0 V.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('596832b9-8de2-4f3e-95cd-6a99d3a97cb9', 'English Language', 'JAMB', null, 2024, null, 'A suitable title for the passage is', null, '["Knowing fatigue","Fatigue","Tiredness and fatigue","Body machine"]', 1, '"Fatigue" is the most suitable title as it is the central topic of the passage.', true, '2026-09-18 09:43:02.453', '2026-09-18 09:43:02.453', null, null, 'COMPREHENSION', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('597cb62f-eb19-4a4b-bd56-45edec5d3fc3', 'Financial Accounting', 'UTME', null, 2003, null, 'What is the capital employed?', 'https://res.cloudinary.com/kwi1uv0g/image/upload/v1791841296/questions/aodh61kvbrym61zsfptl.jpg', '["N44 600","N43 052","N43 044","N38 600"]', 2, 'Capital employed is Fixed asset plus Working capital or Net Assets i.e., Total Assets minus Current liabilities.', true, '2026-10-12 21:59:59.879', '2026-10-12 21:59:59.879', null, null, null, 'What is the capital employed?', '["N44 600","N43 052","<b>N43 044</b>","N38 600"]', 'Capital employed is Fixed asset plus Working capital or Net Assets i.e., Total Assets minus Current liabilities = <b>N43 044</b>.', '{"bold":["N43 044"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('598fb44e-2191-4639-aed9-7ef3301fbc56', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Where did Jesus spend the night after the Triumphant Entry into Jerusalem?', null, '["Bethphage","Bethany","Gethsemane","Jerusalem","Jericho"]', 1, 'Jesus went to Bethany with the twelve disciples.', true, '2026-09-12 10:42:19.255', '2026-09-12 10:42:19.255', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('59962291-f5dc-41f1-8fcd-e605ce413116', 'Physics', 'JAMB', null, 1993, null, 'An element X of atomic number 88 and mass number 226 decays to form an element Z by emitting two beta particles and an alpha particle. Z is represented by', null, '["²²²₈₂Z","²²²₈₈Z","²²⁶₈₆Z","²²⁶₈₀Z"]', 1, 'Alpha emission: A = 226 - 4 = 222, Z = 88 - 2 = 86. Two beta emissions raise Z by 2: Z = 88. So the product is ²²²₈₈Z.', true, '2026-10-12 19:15:38.728', '2026-10-12 19:15:38.728', null, null, null, 'An element X of atomic number 88 and mass number 226 decays to form an element Z by emitting two beta particles and an alpha particle. Z is represented by', '["<sup>222</sup><sub>82</sub>Z","<sup>222</sup><sub>88</sub>Z","<sup>226</sup><sub>86</sub>Z","<sup>226</sup><sub>80</sub>Z"]', 'Alpha emission: A = 226 - 4 = 222, Z = 88 - 2 = 86. Two beta emissions raise Z by 2: Z = 88. So the product is <sup>222</sup><sub>88</sub>Z.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('599bccc5-f0d6-44d0-b4d5-df0a24fb3b17', 'Economics', 'JAMB', null, 2026, null, 'Calculate the equilibrium level of national income (Y) where Y = C + I + G, C = 100 + 0.75Y, I = 50, G = 200', null, '["2000","1500","1400","2500"]', 2, 'Y = 100 + 0.75Y + 50 + 200. Y - 0.75Y = 350. 0.25Y = 350. Y = 1400.', true, '2026-09-12 11:02:07.243', '2026-09-12 11:02:07.243', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('59a27c23-a4aa-491b-bdb5-0e95341e135e', 'Literature in English', 'JAMB', null, 2026, null, 'The writing convention in which the events in a narrative are scrambled as they come to the writer''s mind without any attempt to arrange them in orderly sequence is called', null, '["Shifting style","Narrator''s mind style","Psycho-consciousness style","Stream of consciousness"]', 3, 'The writing convention in which events are scrambled as they come to the writer''s mind without orderly sequence is called stream of consciousness. This technique attempts to capture the flow of a character''s thoughts and feelings as they occur, often without logical transitions or chronological order. It was used by writers like James Joyce and Virginia Woolf. It is not shifting style, narrator''s mind style, or psycho-consciousness style.', true, '2026-09-10 10:47:10.456', '2026-09-10 10:47:10.456', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('59ab960f-1afd-4bf9-bcc7-e85d18ebc1c6', 'Biology', 'JAMB', null, 2012, null, 'In the mammalian male reproductive system, the part that serves as a passage for both urine and semen is the', null, '["urethra","ureter","bladder","seminal vesicle."]', 0, 'The urethra serves as a passage for both urine and semen.', true, '2026-10-12 20:59:44.59', '2026-10-12 20:59:44.59', null, null, null, 'In the mammalian male reproductive system, the part that serves as a passage for both urine and semen is the', '["urethra","ureter","bladder","seminal vesicle."]', 'The urethra serves as a passage for both urine and semen.', '{"bold":["urethra"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('59baf1c6-be2a-452c-b46e-18bfc9110419', 'Chemistry', 'JAMB', null, 2026, null, 'Which process separates crude oil into fractions?', null, '["Distillation","Filtration","Fractional distillation","Crystallization"]', 2, 'Fractional distillation separates crude oil into fractions.', true, '2026-09-12 11:35:55.411', '2026-09-12 11:35:55.411', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('59c1c596-d05e-42f5-a182-e5b635fc5cb6', 'Physics', 'JAMB', null, 2026, null, 'In an elastic collision, momentum is conserved as well as', null, '["velocity","kinetic energy","potential energy","speed"]', 1, 'In an elastic collision, both momentum and kinetic energy are conserved. In an inelastic collision, momentum is conserved but kinetic energy is not.', true, '2026-09-10 10:56:44.766', '2026-09-10 10:56:44.766', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5a02f1ed-9241-4bda-9d18-c6e97f188ae9', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'During the Temple''s repair, King Josiah commanded that the money for the work be given to the workmen without asking for an account of it because', null, '["They were honest men","they were to be tested first","there was no room for that","the king enquired from God"]', 0, 'They dealt faithfully and could be trusted.', true, '2026-09-12 10:41:42.853', '2026-09-12 10:41:42.853', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5a0f77f9-1ea1-40b4-b5e0-8f4e2fa60830', 'English Language', 'JAMB', null, 2024, null, '6', null, '["trade union","member","operator","organization"]', 0, 'A trade union is the body that organizes and persuades workers.', true, '2026-09-18 10:17:48.779', '2026-09-18 10:17:48.779', '274e150d-fca1-4c72-9c33-e5e119534874', 6, 'CLOZE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5a12fe75-6d4b-48fe-b3a1-0be5d5bb1fac', 'Chemistry', 'JAMB', null, 2026, null, 'In the electrolysis of brine (I) hydrogen gas is given off at the cathode (II) chlorine is gotten at the anode (III) oxygen gas is given off at the anode (IV) electrolyte becomes neutral', null, '["I, II","II, IV","III, IV","I, IV"]', 0, 'In brine electrolysis, hydrogen is at the cathode and chlorine at the anode.', true, '2026-09-12 11:36:07.365', '2026-09-12 11:36:07.365', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5a268f4b-ce0c-411f-8fc6-4d593b5052f9', 'English Language', 'JAMB', null, 2007, null, 'He <u>compliments</u> me on my way of doing things.', null, '["complements","imitates","disgusts","praises"]', 3, 'Compliments = praises.', true, '2026-10-24 01:01:57.55', '2026-10-24 01:01:57.55', null, null, null, 'He <u>compliments</u> me on my way of doing things.', '["complements","imitates","disgusts","<u>praises</u>"]', '<b>Compliments</b> = <b>praises</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5a38365e-19c1-42ca-afa5-c498077ff732', 'Hausa', 'JAMB', null, 2011, null, 'Da ya hango su, ya ce ''Da wa Allah ya hafa mu?'' Wannan na nufin da ya hango su, Sai ya', null, '["gudu","bi su a guje","boye","ja ya tsaya"]', 1, 'Wannan na nufin da ya hango su, sai ya bi su a guje.', true, '2026-10-13 10:37:21.343', '2026-10-13 10:37:21.343', null, null, null, 'Da ya hango su, ya ce ''Da wa Allah ya hafa mu?'' Wannan na nufin da ya hango su, Sai ya', '["gudu","bi su a guje","boye","ja ya tsaya"]', 'Wannan na nufin da ya hango su, sai ya bi su a guje.', '{"bold":["bi su a guje"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5a38fe12-13e4-4c44-8458-e78a228a0441', 'Biology', 'JAMB', null, 2013, null, 'Plants that have special devices for trapping and digesting insects are', null, '["Parasitic","Saprophytic","Carnivorous","Symbiotic"]', 2, 'Carnivorous plants trap and digest insects.', true, '2026-10-12 20:59:46.928', '2026-10-12 20:59:46.928', null, null, null, 'Plants that have special devices for trapping and digesting insects are', '["Parasitic","Saprophytic","Carnivorous","Symbiotic"]', 'Carnivorous plants trap and digest insects.', '{"bold":["Carnivorous"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5a3d3b06-335c-4318-9495-c0f613d6e239', 'English Language', 'JAMB', null, 2024, null, 'The hot gases expand violently as great ______, compressing the air around them into what is called ______.', null, '["Firearms","Fireballs","Fireworks","Firesmokes"]', 1, '"Fireballs" is the correct term for expanding hot gases.', true, '2026-09-18 09:43:02.44', '2026-09-18 09:43:02.44', null, null, 'CLOZE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5a3d9a96-7b89-48b5-8b6f-6a9825bbff7d', 'Physics', 'JAMB', null, 2026, null, 'The tension in a sonometer wire is tripled. The ratio of the new frequency to the initial frequency is', null, '["1/3","3","1/√3","√3"]', 3, 'Frequency f ∝ √T. If tension is tripled, new frequency = √3 × old frequency. So the ratio is √3:1.', true, '2026-09-10 10:56:42.493', '2026-09-10 10:56:42.493', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5a404d4e-0a55-4675-93cc-e38645a01cae', 'Physics', 'JAMB', null, 2026, null, 'Gases conduct electricity under', null, '["high pressure and high voltage","low pressure and low voltage","normal pressure and low voltage","low pressure and high voltage"]', 3, 'Gases conduct electricity under low pressure and high voltage. At low pressure, gas molecules are far apart, allowing ions to travel without collision. High voltage provides the energy needed to ionize the gas molecules.', true, '2026-09-10 10:56:41.518', '2026-09-10 10:56:41.518', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5a4a8010-9344-42a5-85ab-56b233e4c3f1', 'English Language', 'JAMB', null, 2007, null, 'The House and The Senate will <u>__________</u> at noon next Wednesday to hear a special address by the president.', null, '["convene","adjourn","rise","collude"]', 0, 'Correct spelling: convene.', true, '2026-10-24 07:21:37.375', '2026-10-24 07:21:37.375', null, null, null, 'The House and The Senate will <u>__________</u> at noon next Wednesday to hear a special address by the president.', '["convene","adjourn","rise","collude"]', 'Correct spelling: convene.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5a61d4d0-2109-4044-8af0-5251338b5a3c', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'At Shechem, God appeared to Abram and told him that...', null, '["the land would be given to his descendants","He should continue on his journey southwards","He should leave his country","He should settle there with his descendants"]', 0, 'Genesis 12:7 states: ''Then the Lord appeared to Abram and said, To your offspring I will give this land.'' So he built an altar there.', true, '2026-09-09 17:18:28.475', '2026-09-09 17:18:28.475', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5a7f5697-29e8-476d-8aa0-25da7aebc25a', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The scholar''s <u>epitaph</u> was demolished.', null, '["monument","embodiment","farmland","book"]', 0, 'Epitaph = monument.', true, '2026-10-24 01:04:10.58', '2026-10-24 01:04:10.58', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The scholar''s <u>epitaph</u> was demolished.', '["<u>monument</u>","embodiment","farmland","book"]', '<b>Epitaph</b> = <b>monument</b>.', '{}');
