insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5a9bf04d-1fea-45ac-abb2-ff03e2c3c520', 'Biology', 'JAMB', null, 2026, null, 'Which enzymes are contained in the pancreatic juice?', null, '["amylase, lipase, trypsin","maltase, erepsin and trypsin","ptyalin, lipase and erepsin","renin, sucrase and lipase"]', 0, 'Pancreatic juice contains amylase (for starch), lipase (for fats), and trypsinogen/trypsin (for proteins).', true, '2026-09-09 02:56:40.686', '2026-09-09 02:56:40.686', null, null, null, null, null, null, null);
