insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5ab5deda-8168-4d20-953f-0073f43e51c8', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. I cannot understand why Ali should serve in that <u>moribund</u> administration.', null, '["crumbling","purposeless","prodigal","oppressive"]', 0, 'Moribund = crumbling/near death.', true, '2026-10-24 01:01:50.87', '2026-10-24 01:01:50.87', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. I cannot understand why Ali should serve in that <u>moribund</u> administration.', '["<u>crumbling</u>","purposeless","prodigal","oppressive"]', '<b>Moribund</b> = <b>crumbling</b>/near death.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5acaa8a6-8357-4c24-ad7b-18ba9c4421d1', 'English Language', 'JAMB', null, 2007, null, 'Four persons accused of currency <u>__________</u> are being held by the security agents', null, '["traficking","traviking","trafficking","traffiking"]', 2, 'Correct spelling: trafficking.', true, '2026-10-24 07:21:32.089', '2026-10-24 07:21:32.089', null, null, null, 'Four persons accused of currency <u>__________</u> are being held by the security agents', '["traficking","traviking","trafficking","traffiking"]', 'Correct spelling: trafficking.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5ae944fa-4ce5-4ae9-9a84-4b12f0802be8', 'Chemistry', 'JAMB', null, 2026, null, 'Which metal is extracted by electrolysis?', null, '["Iron","Copper","Aluminium","Zinc"]', 2, 'Aluminium is extracted by electrolysis of molten bauxite.', true, '2026-09-12 11:33:01.158', '2026-09-12 11:33:01.158', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5aff76b0-1de4-4c3d-bc55-3c9985c28262', 'General Mathematics', 'JAMB', null, 2026, null, 'A plane flies due East from A(lat. 53°N, long. 25°E) to a point B(lat. 53°N, long. 85°E) at an average speed of 400km/h. The plane then flies South from B to C 2000km away. Calculate, correct to the nearest kilometer, the distance AB', null, '["3043km","4035 km","2853 km","1800km","15.15km"]', 2, 'Longitude difference = 60°. Distance = 60 × 111 × cos53° = 60 × 111 × 0.6018 = 4008 km. The closest is 4035 km.', true, '2026-09-12 11:43:45.547', '2026-09-12 11:43:45.547', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5b16234d-18c0-4206-bee0-767a41055932', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'How did King Nebuchadnezzar describe the fourth person he saw with Shadrach, Meshach and Abednego in the fiery furnace?', null, '["Like a son of the gods","As a servant of God","As an angel","As a prophet"]', 0, 'Daniel 3:25 states: ''Look! I see four men loose, walking in the midst of the fire... and the form of the fourth is like the Son of God / a son of the gods.''', true, '2026-09-09 17:18:27.113', '2026-09-09 17:18:27.113', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5b1744ff-fb36-4e79-b615-449dc9f56aae', 'Physics', 'JAMB', null, 1998, null, 'The linear expansivity of brass is 2 x 10⁻⁵ °C⁻¹. If the volume of a piece of brass is 15.00 cm³ at 0 °C, what is the volume at 100 °C?', null, '["16.03 cm³","16.00 cm³","15.09 cm³","15.03 cm³"]', 2, 'γ = 3α = 6 x 10⁻⁵. ΔV = 15.00 x 6 x 10⁻⁵ x 100 = 0.09 cm³, so V = 15.09 cm³.', true, '2026-10-12 19:15:45.409', '2026-10-12 19:15:45.409', null, null, null, 'The linear expansivity of brass is 2 x 10<sup>-5</sup> °C<sup>-1</sup>. If the volume of a piece of brass is 15.00 cm<sup>3</sup> at 0 °C, what is the volume at 100 °C?', '["16.03 cm<sup>3</sup>","16.00 cm<sup>3</sup>","15.09 cm<sup>3</sup>","15.03 cm<sup>3</sup>"]', 'γ = 3α = 6 x 10<sup>-5</sup>. ΔV = 15.00 x 6 x 10<sup>-5</sup> x 100 = 0.09 cm<sup>3</sup>, so V = 15.09 cm<sup>3</sup>.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5b1b099e-1dbe-43dd-9b02-79a18a19b0c8', 'Yoruba', 'JAMB', null, 2007, null, 'Ilé-ayé ò jè nykan, Àlà lásán ni, Òkàn tó þ sùn ti dòkú, Nykan ò rí bí a ti rò ó Ilé-ayé gbçgè. Sàréè ì ýopin èdá. Eérú fún eérú, Eruku fún eruku, Lôba-òkè sô fênìyàn, Tó j’Òlörun nípè. Àmò hùwà bí çni pé, Ojoojúmò lèdá p súnmòlé. Màà gbèkèké òlá Màà nígbçkèlé nínú òrõ. Alágbára ayé, ç rõra ýe. Bí ó ti wù ká ki lòkàn tó, Kìkì ní í lù, Báa bá gbòlù ikú, Àtorin arò ti p kòjá lóde. Ojú ogun layé. Má bojú wèyìn, Jà bí akin lójù ìjà. Rántí ayé àkòni tó kòjà, Wo àwòkòyè wòn fún òjò òla tìrç. Gbé ìgbé-ayé alààyè, Jè kí òkú sunkún ara wòn. Àwé, má ronú mò, Jè ká máa ììyé lò. Máa jagun lò, Má wèyìn, Má ìyìè méjì, Bó pè, bó yá, Ayõ p bõ. Kí ni akéwì sò pé yóò yè èdá tó gbò nípa ikú?', null, '["Yóò kún fún ayõ","Yóò bojú wèyìn","Yóò máa ronú","Yóò máa jáyà."]', 1, 'Kí ni akéwì sò pé yóò yè èdá tó gbò nípa ikú ni Yóò bojú wèyìn.', true, '2026-10-13 13:23:30.863', '2026-10-13 13:23:30.863', null, null, null, 'Ilé-ayé ò jè nykan, Àlà lásán ni, Òkàn tó þ sùn ti dòkú, Nykan ò rí bí a ti rò ó Ilé-ayé gbçgè. Sàréè ì ýopin èdá. Eérú fún eérú, Eruku fún eruku, Lôba-òkè sô fênìyàn, Tó j’Òlörun nípè. Àmò hùwà bí çni pé, Ojoojúmò lèdá p súnmòlé. Màà gbèkèké òlá Màà nígbçkèlé nínú òrõ. Alágbára ayé, ç rõra ýe. Bí ó ti wù ká ki lòkàn tó, Kìkì ní í lù, Báa bá gbòlù ikú, Àtorin arò ti p kòjá lóde. Ojú ogun layé. Má bojú wèyìn, Jà bí akin lójù ìjà. Rántí ayé àkòni tó kòjà, Wo àwòkòyè wòn fún òjò òla tìrç. Gbé ìgbé-ayé alààyè, Jè kí òkú sunkún ara wòn. Àwé, má ronú mò, Jè ká máa ììyé lò. Máa jagun lò, Má wèyìn, Má ìyìè méjì, Bó pè, bó yá, Ayõ p bõ. Kí ni akéwì sò pé yóò yè èdá tó gbò nípa ikú?', '["Yóò kún fún ayõ","Yóò bojú wèyìn","Yóò máa ronú","Yóò máa jáyà."]', 'Kí ni akéwì sò pé yóò yè èdá tó gbò nípa ikú ni Yóò bojú wèyìn.', '{"bold":["Yóò bojú wèyìn"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5b2209fa-317b-4603-be0a-576ebe70e5ba', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. police are not happy with the number of <u>depraving</u> people around the politician.', null, '["indolent","violent","immoral","loquacious"]', 2, 'Depraving = immoral.', true, '2026-10-24 01:01:57.071', '2026-10-24 01:01:57.071', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. police are not happy with the number of <u>depraving</u> people around the politician.', '["indolent","violent","<u>immoral</u>","loquacious"]', '<b>Depraving</b> = <b>immoral</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5b244b83-47c8-4eed-a04c-333095c9d0ec', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. His has been a life of <u>make-belief</u>.', null, '["faith","fantasy","grandeur","religion"]', 1, 'Make-belief = fantasy.', true, '2026-10-24 01:01:43.085', '2026-10-24 01:01:43.085', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. His has been a life of <u>make-belief</u>.', '["faith","<u>fantasy</u>","grandeur","religion"]', '<b>Make-belief</b> = <b>fantasy</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5b25edf2-ab90-4d40-a279-febaa43a28f3', 'General Mathematics', 'JAMB', null, 2026, null, 'In a right-angled triangle, if the opposite side is 3 and hypotenuse is 5, find tan θ', null, '["3/5","4/5","3/4","5/3"]', 2, 'Adjacent = 4. tan θ = 3/4.', true, '2026-09-12 11:44:13.367', '2026-09-12 11:44:13.367', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5b26a674-ea53-4cc8-88fe-5d3046675dcb', 'Government', 'JAMB', null, 2026, null, 'Public corporations and parastatals are typically established by', null, '["private individuals","legislative acts and statutes","trade unions","International organizations"]', 1, 'Public corporations are established by legislative acts and statutes.', true, '2026-09-12 11:24:30.495', '2026-09-12 11:24:30.495', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5b26e4ed-e3ab-47aa-928d-9dc4f21e3425', 'Biology', 'JAMB', null, 2005, null, 'Which of the following is likely to have a higher concentration of mitochondria?', null, '["sperm cell","white blood cell","egg cell","red blood cell"]', 0, 'Sperm cells require high energy for active locomotion, hence a high concentration of mitochondria.', true, '2026-10-12 20:05:11.707', '2026-10-12 20:05:11.707', null, null, null, 'Which of the following is likely to have a higher concentration of mitochondria?', '["sperm cell","white blood cell","egg cell","red blood cell"]', 'Sperm cells require high energy for active locomotion, hence a high concentration of mitochondria.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5b2a6e0b-e8d1-4b86-8948-aa87affdf962', 'Hausa', 'JAMB', null, 2010, null, 'A karkara da ma wasu manyan garuruwa kalilan, mutane kan hadu su rika cin abinci tare. Akan zabi gidan mutum daya daga cikinsu ya zama shi ne matattara. Mutumin da aka zabi gidansa, kusan shi ne shugaba, kuma ya fi kowa yawan shekaru. A wasu lokuta kuma, ana duba gidan da ya fi yalwa, ko ya fi zama kan hanya, babu wahala sosi zuwa gidan, musamman da damina. A wurin haduwa a ci abinci tare, kowane magidanci zai kawo abincin da aka dafa a gidansa, wanda ya fi shiga. Nan fa matan da suka kware suke shan yabo da godiya. Wadanda ba su iya ba kuwa, aiki ya gan su da kuma takaici. Saboda wasu mazan kan yi wa matansu gori. Ba nan ma abin ya tsaya ba, rashin iya abincin nan na iya haddasa mutuwar aure, idan ba a kai hankali nesa ba. Al''amari ya yi muni ke nan. Cikin abubuwan da ake kawowa, akwai tuwo da shinkafa da fate da dan wake da dambu da alkubus da doya da taliya da kuma makaroni. Ana kawo wasu daga cikin wadannan nau''o''in abinci tare da miya, wasu kuma a siffar dafa-duka. Duka dai wannan, ya danganta da irin cefanen da maigida ya yi. Akwai alfanu babba game da wannan zama. Da farko, akwai kyautata dangantaka da zaman tare. Ana kuma taimakon juna ta hanyar tattaua matsalolin da suka addabe su. Wanda ma ba ya da karfin yin abinci wani lokaci, ba zai tagayyara ba, zai sami abin da zai ci a wajen. Babbar fa''idar cin abinci tare, ita ce', null, '["sada zumunci tsakanin mutane","yalwar abinci daban-daban","sa mata su kara himma","wani zai yi santi da abincin wani."]', 0, 'Babbar fa''idar cin abinci tare ita ce sada zumunci tsakanin mutane.', true, '2026-10-13 10:37:23.395', '2026-10-13 10:37:23.395', null, null, null, 'A karkara da ma wasu manyan garuruwa kalilan, mutane kan hadu su rika cin abinci tare. Akan zabi gidan mutum daya daga cikinsu ya zama shi ne matattara. Mutumin da aka zabi gidansa, kusan shi ne shugaba, kuma ya fi kowa yawan shekaru. A wasu lokuta kuma, ana duba gidan da ya fi yalwa, ko ya fi zama kan hanya, babu wahala sosi zuwa gidan, musamman da damina. A wurin haduwa a ci abinci tare, kowane magidanci zai kawo abincin da aka dafa a gidansa, wanda ya fi shiga. Nan fa matan da suka kware suke shan yabo da godiya. Wadanda ba su iya ba kuwa, aiki ya gan su da kuma takaici. Saboda wasu mazan kan yi wa matansu gori. Ba nan ma abin ya tsaya ba, rashin iya abincin nan na iya haddasa mutuwar aure, idan ba a kai hankali nesa ba. Al''amari ya yi muni ke nan. Cikin abubuwan da ake kawowa, akwai tuwo da shinkafa da fate da dan wake da dambu da alkubus da doya da taliya da kuma makaroni. Ana kawo wasu daga cikin wadannan nau''o''in abinci tare da miya, wasu kuma a siffar dafa-duka. Duka dai wannan, ya danganta da irin cefanen da maigida ya yi. Akwai alfanu babba game da wannan zama. Da farko, akwai kyautata dangantaka da zaman tare. Ana kuma taimakon juna ta hanyar tattaua matsalolin da suka addabe su. Wanda ma ba ya da karfin yin abinci wani lokaci, ba zai tagayyara ba, zai sami abin da zai ci a wajen. Babbar fa''idar cin abinci tare, ita ce', '["sada zumunci tsakanin mutane","yalwar abinci daban-daban","sa mata su kara himma","wani zai yi santi da abincin wani."]', 'Babbar fa''idar cin abinci tare ita ce sada zumunci tsakanin mutane.', '{"bold":["sada zumunci tsakanin mutane"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5b37ca40-691e-4580-994b-0a07650fff06', 'Christian Religious Studies', 'JAMB', null, 2026, null, '''I am the LORD, and there is no other, beside me there is no God.'' God''s statement through Isaiah depicts', null, '["Israel''s acceptance of His Supremacy","assurance to Isaiah of His existence","His sovereignty","His divine nature"]', 2, 'God''s statement through Isaiah depicts His sovereignty. God declares that He alone is God and there is no other. This emphasizes His supreme power and authority over all creation.', true, '2026-09-12 09:46:16.681', '2026-09-12 09:46:16.681', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5b3c3496-5a08-41af-8cb5-e443aa705aa3', 'Physics', 'JAMB', null, 2026, null, 'The distance between two successive crest of a wave is 15cm and the velocity 300ms⁻¹. Calculate the frequency.', null, '["2×10³ Hz","4.5×10³ Hz","2×10³ Hz","4.5×10³ Hz"]', 0, 'Frequency = velocity/wavelength = 300/0.15 = 2000 Hz = 2×10³ Hz.', true, '2026-09-10 10:56:42.384', '2026-09-10 10:56:42.384', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5b3f0c89-26f3-4076-b44a-f41db3824f55', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Beneath Ado''s curt exterior, he is really very <u>kind-hearted</u>.', null, '["harsh","rough","gentle","nice"]', 0, 'Kind-hearted; opposite = harsh.', true, '2026-10-24 07:21:26.336', '2026-10-24 07:21:26.336', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Beneath Ado''s curt exterior, he is really very <u>kind-hearted</u>.', '["harsh","rough","gentle","nice"]', 'Kind-hearted; opposite = harsh.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5b49ca73-3e61-40f6-afa3-e75bc9f1f31a', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Herod treated Jesus with contempt and mockery by...', null, '["Forcing him for signs and wonders","Subjecting him to severe beatings","Dressing him in gorgeous apparels","Accusing him falsely and bitterly"]', 2, 'Luke 23:11 notes that Herod and his soldiers treated Jesus with contempt, mocked Him, arrayed Him in gorgeous/splendid apparel, and sent Him back to Pilate.', true, '2026-09-09 17:18:23.889', '2026-09-09 17:18:23.889', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5b4e7fd9-7509-44b9-b664-f3f89b062152', 'Biology', 'JAMB', null, 2026, null, 'Heat produced in tissue respiration in plants is', null, '["a chemical form of energy","the only form of energy","the main form of energy","a useful form of energy","a waste form of energy"]', 4, 'Heat produced in tissue respiration in plants is a waste form of energy. During respiration, energy is released from glucose breakdown. Some of this energy is captured in ATP (useful chemical energy), but the remainder is released as heat. In plants, this heat is generally dissipated as it does not serve a useful function (unlike in warm-blooded animals). Heat is a waste product of metabolism, not the primary useful form of energy.', true, '2026-09-09 03:19:10.107', '2026-09-09 03:19:10.107', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5b4f0a78-4e55-4fc1-95f0-4729c3b3b68c', 'Biology', 'JAMB', null, 2003, null, 'The inactive state exhibited by an animal during hot dry season is termed', null, '["aestivation","dormancy","resting","hibernation"]', 0, 'The inactive state during hot dry season is aestivation.', true, '2026-10-12 20:59:34.253', '2026-10-12 20:59:34.253', null, null, null, 'The inactive state exhibited by an animal during hot dry season is termed', '["aestivation","dormancy","resting","hibernation"]', 'The inactive state during hot dry season is aestivation.', '{"bold":["aestivation"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5b532bbd-eff7-4003-a9da-5d732b2a4795', 'Literature in English', 'JAMB', null, 2026, null, 'Ananse''s extraordinary address of appellation of the chiefs is the theme of', null, '["manipulation","flattery","respect","I too doy do"]', 1, 'The theme is flattery.', true, '2026-09-12 11:05:30.768', '2026-09-12 11:05:30.768', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5b559532-d1b3-44b0-b8a9-7eec94132873', 'Biology', 'JAMB', null, 2003, null, 'An example of cryptic colouration is the', null, '["mottled colours on moths that rest on lichen","bright colour of an insect pollinated flower","green colour of a plant","bright marks on a poisonous tropical frog on variegated leaves"]', 0, 'Mottled colours on moths resting on lichen is cryptic colouration.', true, '2026-10-12 20:59:34.152', '2026-10-12 20:59:34.152', null, null, null, 'An example of cryptic colouration is the', '["mottled colours on moths that rest on lichen","bright colour of an insect pollinated flower","green colour of a plant","bright marks on a poisonous tropical frog on variegated leaves"]', 'Mottled colours on moths resting on lichen is cryptic colouration.', '{"bold":["Mottled colours on moths resting on lichen"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5b5ca5b0-e576-4ad3-a595-7611766eb047', 'Government', 'JAMB', null, 2026, null, 'The electoral officer charged with the responsibility of announcing election result is the', null, '["Returning officer","Presiding officer","Residential electoral commissioner","Supervisory presiding officer"]', 0, 'The Returning Officer announces election results.', true, '2026-09-12 11:24:23.2', '2026-09-12 11:24:23.2', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5b634ca2-9d1b-4d47-b666-3cbe4cfa114b', 'testing', 'JAMB', null, 2024, null, 'I would rather...... the money to Janet because......', null, '["you give/it''s hers","you gave / it''s hers","gave/ it''s hers","you gave / it''s her''s"]', 1, '''Would rather'' + past subjunctive ''you gave''; possessive ''hers'' has no apostrophe.', true, '2026-10-31 16:48:52.126', '2026-10-31 16:48:52.126', null, null, null, 'I would rather...... the money to Janet because......', '["you give/it''s hers","you gave / it''s hers","gave/ it''s hers","you gave / it''s her''s"]', '''Would rather'' + past subjunctive ''you gave''; possessive ''hers'' has no apostrophe.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5b67032f-4fea-40d9-b90b-61b7d665714c', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). Mr. Okon has been described as <u>an eagle-eyed</u> editor.', null, '["a short-sighted","a clear-sighted","a long-sighted","a quick-sighted"]', 3, '''Eagle-eyed'' = keen-sighted/quick-sighted.', true, '2026-10-24 01:04:22.492', '2026-10-24 01:04:22.492', null, null, null, '(Choose the most appropriate interpretation). Mr. Okon has been described as <u>an eagle-eyed</u> editor.', '["a short-sighted","a clear-sighted","a long-sighted","<u>a quick-sighted</u>"]', '''<b>Eagle-eyed</b>'' = <b>keen-sighted/quick-sighted</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5b6a7fd3-f086-4808-b286-5c4215f596f0', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Sola''s car is badly damaged; he has to look for an <u>expert</u> mechanic to fix it.', null, '["uneducated","amateurish","awkward","unscientific"]', 1, 'Expert = skilled; opposite = amateurish.', true, '2026-10-24 07:21:12.547', '2026-10-24 07:21:12.547', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Sola''s car is badly damaged; he has to look for an <u>expert</u> mechanic to fix it.', '["uneducated","amateurish","awkward","unscientific"]', 'Expert = skilled; opposite = amateurish.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5b7187a7-5c38-4574-ab71-6f0dac82cf68', 'Biology', 'JAMB', null, 2026, null, 'The older fossil-bearing rocks, in contrast to the more recent ones, are more likely to contain', null, '["animals rather than plant remains","invertebrates rather than birds","flowering plants rather than mosses","reptiles rather than fishes"]', 1, 'Older fossil-bearing rocks, in contrast to more recent ones, are more likely to contain invertebrates rather than birds. The fossil record shows that simpler organisms (invertebrates) appeared earlier in geological history, while more complex organisms (birds, mammals) appeared later. This supports the theory of evolution. The progression is: invertebrates → fishes → amphibians → reptiles → birds/mammals → flowering plants.', true, '2026-09-09 03:19:29.173', '2026-09-09 03:19:29.173', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5b75e742-4dd5-4e35-a3d1-add5ae09528d', 'Literature in English', 'JAMB', null, 2026, null, 'A drama with a sad or serious ending is called a', null, '["Comedy","Farce","Satire","Tragedy"]', 3, 'A drama with a sad or serious ending is called a tragedy. Tragedy is a form of drama that deals with serious themes and typically ends with the downfall or death of the protagonist. It often involves a tragic hero with a tragic flaw that leads to their downfall. Comedy, farce, and satire are forms of drama that are humorous or critical in nature.', true, '2026-09-10 10:45:33.645', '2026-09-10 10:45:33.645', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5b85e2d5-7c66-47ad-b720-ab2b1241672f', 'Yoruba', 'JAMB', null, 2002, null, 'Ìwé Ìwúre Níbi Àyèyç ni Ìbéèrè 29-31 dá lé. Nínú Ìwúre Níbi Ìkòjéyega, tá ló kòjé yega?', null, '["Arinnàká","Iyábo","Àdùkè","ó bá dákù."]', 2, 'Àdùkè ló kòjé yega.', true, '2026-10-13 13:22:39.562', '2026-10-13 13:22:39.562', null, null, null, 'Ìwé Ìwúre Níbi Àyèyç ni Ìbéèrè 29-31 dá lé. Nínú Ìwúre Níbi Ìkòjéyega, tá ló kòjé yega?', '["Arinnàká","Iyábo","Àdùkè","ó bá dákù."]', 'Àdùkè ló kòjé yega.', '{"bold":["Àdùkè"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5b895513-ec0e-4f7d-817a-3071e71f8572', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The girl''s father was <u>astounded</u> to see her appear from the shrine.', null, '["overwhelmed","embarrassed","astonished","collected"]', 2, 'Astounded = astonished.', true, '2026-10-24 01:01:54.696', '2026-10-24 01:01:54.696', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The girl''s father was <u>astounded</u> to see her appear from the shrine.', '["overwhelmed","embarrassed","<u>astonished</u>","collected"]', '<b>Astounded</b> = <b>astonished</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5b914431-79d9-45ac-8e7f-10c7be3ba655', 'English Language', 'JAMB', null, 0, null, '11', null, '["exhorbitant ","irrational","extortion","expensive"]', 0, 'Management refuses if they think the demand is exorbitant (unreasonably high).', true, '2026-09-18 09:08:13.398', '2026-09-18 09:08:13.398', '1edea09d-7ad3-4c90-8c54-eeb4b369dcff', 10, 'CLOZE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5b9bad5c-9135-442f-8243-107bb828b571', 'General Mathematics', 'JAMB', null, 2026, null, 'If sin Y = -√3/2 find cos Y', null, '["0.866","-0.5","-0.866","0.5","0.707"]', 1, 'sin Y = -√3/2. cos Y = -0.5 (in third quadrant).', true, '2026-09-12 11:44:00.037', '2026-09-12 11:44:00.037', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5ba4ab6b-0a14-46b4-9183-7b46ab892964', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). The convict said he was tired of <u>leading a dog''s life</u>. To lead a dog''s life means to live ___________', null, '["carelessly","in disgrace","in solitude","in misery","in poverty"]', 3, '''A dog''s life'' means a miserable life.', true, '2026-10-24 01:04:13.067', '2026-10-24 01:04:13.067', null, null, null, '(Choose the most appropriate interpretation). The convict said he was tired of <u>leading a dog''s life</u>. To lead a dog''s life means to live ___________', '["carelessly","in disgrace","in solitude","<u>in misery</u>","in poverty"]', '''A <b>dog''s life</b>'' means a <b>miserable life</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5ba507e3-4680-4028-8138-d17338d99145', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). The robber was <u>hedged in</u> by the people', null, '["The robber was surrounded by the people","The robber was killed by the people","The robber was exposed by the people","The robber was caught by the people"]', 0, '''Hedged in'' = surrounded.', true, '2026-10-24 01:02:11.319', '2026-10-24 01:02:11.319', null, null, null, '(Choose the most appropriate interpretation). The robber was <u>hedged in</u> by the people', '["<u>The robber was surrounded by the people</u>","The robber was killed by the people","The robber was exposed by the people","The robber was caught by the people"]', '''<b>Hedged in</b>'' = <b>surrounded</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5bb36cfb-4865-45ee-b968-03521983e8f5', 'English Language', 'JAMB', null, 2007, null, 'Emeka is now a <u>__________</u> student but it took him years to <u>__________</u>', null, '["matured/mature","mature/mature","mature/matured","matured/matured"]', 2, 'Correct forms: mature/matured.', true, '2026-10-24 07:21:34.958', '2026-10-24 07:21:34.958', null, null, null, 'Emeka is now a <u>__________</u> student but it took him years to <u>__________</u>', '["matured/mature","mature/mature","mature/matured","matured/matured"]', 'Correct forms: mature/matured.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5bb873a6-a6be-4029-b22d-2bd4512819a8', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). The president said that the country was <u>not out of the _______________ yet</u>', null, '["forest","fog","water","wood"]', 3, '''Not out of the woods'' = still in difficulty.', true, '2026-10-24 01:04:25.278', '2026-10-24 01:04:25.278', null, null, null, '(Choose the most appropriate interpretation). The president said that the country was <u>not out of the _______________ yet</u>', '["forest","fog","water","<u>wood</u>"]', '''<b>Not out of the woods</b>'' = <b>still in difficulty</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5bbf3d58-69cf-4dac-9e9d-ffbbcdc8cc7d', 'English Language', 'JAMB', null, 2007, null, 'We cannot all wear expensive shoes in situation of <u>__________</u>', null, '["divergent demand and supply","uneven wear and tear","differing purchasing power","unpredictable national income"]', 2, 'Correct form: differing purchasing power.', true, '2026-10-24 07:21:44.819', '2026-10-24 07:21:44.819', null, null, null, 'We cannot all wear expensive shoes in situation of <u>__________</u>', '["divergent demand and supply","uneven wear and tear","differing purchasing power","unpredictable national income"]', 'Correct form: differing purchasing power.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5bc24dc9-4ec9-46d2-8443-19e2c550af90', 'English Language', 'JAMB', null, 2007, null, 'The driver was short of petrol, so he <u>__________</u> down the hills with the engine switched off.', null, '["glided","coasted","wheeled","taxied"]', 1, 'Correct spelling: coasted.', true, '2026-10-24 07:21:39.368', '2026-10-24 07:21:39.368', null, null, null, 'The driver was short of petrol, so he <u>__________</u> down the hills with the engine switched off.', '["glided","coasted","wheeled","taxied"]', 'Correct spelling: coasted.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5bc61b3d-cce3-425d-bea2-5d33aacf2579', 'Biology', 'JAMB', null, 2011, null, 'Which of the following is a feature of the population pyramid of a developing country?', null, '["Long lifespan","low birth rate","low death rate","short lifespan."]', 3, 'Short lifespan is a feature of developing countries'' population pyramids.', true, '2026-10-12 20:59:43.015', '2026-10-12 20:59:43.015', null, null, null, 'Which of the following is a feature of the population pyramid of a developing country?', '["Long lifespan","low birth rate","low death rate","short lifespan."]', 'Short lifespan is a feature of developing countries'' population pyramids.', '{"bold":["Short lifespan"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5bc643c5-2d16-4123-995a-a659f84dd53e', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The girl took a <u>cursory</u> glance at the letter and hid it.', null, '["sententious","concise","brief","lasting"]', 3, 'Cursory = brief/hasty; opposite = lasting.', true, '2026-10-24 07:21:29.972', '2026-10-24 07:21:29.972', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The girl took a <u>cursory</u> glance at the letter and hid it.', '["sententious","concise","brief","lasting"]', 'Cursory = brief/hasty; opposite = lasting.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5bd07423-1c7d-4b1d-aa7d-85bf4f0227d7', 'Chemistry', 'JAMB', null, 2026, null, 'Which non-metal conducts electricity?', null, '["Sulphur","Phosphorus","Graphite","Oxygen"]', 2, 'Graphite is a non-metal that conducts electricity due to delocalized electrons.', true, '2026-09-12 11:32:59.407', '2026-09-12 11:32:59.407', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5bd4b467-455b-429b-b3e3-2c55d0c5ad56', 'Physics', 'JAMB', null, 2001, null, 'Which of the following consists entirely of vector quantities?', null, '["Velocity, magnetic flux density and reaction.","Tension, magnetic flux and mass","Displacement, impulse and power","Work, pressure and moment."]', 0, 'Velocity, magnetic flux density and reaction force have direction. Mass, power, work and pressure are scalars.', true, '2026-10-12 19:15:51.094', '2026-10-12 19:15:51.094', null, null, null, 'Which of the following consists entirely of vector quantities?', '["Velocity, magnetic flux density and reaction.","Tension, magnetic flux and mass","Displacement, impulse and power","Work, pressure and moment."]', 'Velocity, magnetic flux density and reaction force have direction. Mass, power, work and pressure are scalars.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5be1638b-ae6a-4577-a8f4-248d5bac54c3', 'Government', 'JAMB', null, 2026, null, 'The main focus of Nigeria''s foreign policy since independence centres on', null, '["Afrocentrism","subregionalism","south-south cooperation","globalism"]', 0, 'Nigeria''s foreign policy focuses on Afrocentrism.', true, '2026-09-12 11:24:41.335', '2026-09-12 11:24:41.335', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5be3840a-050d-4c8f-abbd-75f07d466f86', 'Economics', 'JAMB', null, 2026, null, 'Quantity supplied depends on the price of the good. Identify the independent and dependent variable in this', null, '["QS is independent, P is dependent","QS is dependent, P is dependent","QS is dependent, P is independent","QS is independent, P is independent"]', 2, 'Quantity supplied (QS) is the dependent variable, and price (P) is the independent variable.', true, '2026-09-12 11:00:13.74', '2026-09-12 11:00:13.74', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5be6734f-a327-4a17-9d8f-5134466e65ed', 'English Language', 'JAMB', null, 2024, null, 'To Nigerians, corruption in high places is not strange to ______', null, '["we","us","ours","ourselves"]', 1, '"Us" is the correct object pronoun after "to."', true, '2026-09-18 09:24:04.793', '2026-10-17 10:49:36.942', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5be83ce6-c5a3-4fba-ad6b-0c819a34873f', 'Biology', 'JAMB', null, 2026, null, 'Which of the following substances are reabsorbed in the Proximal convoluted tubule of the nephron? I. Glucose II. Urea III. Amino acids IV. Sodium ion', null, '["I, II, III & IV","I & III","I","I, III & IV"]', 3, 'The proximal convoluted tubule reabsorbs glucose, amino acids, and sodium ions (I, III, and IV). Urea is not significantly reabsorbed here; it remains in the filtrate and is concentrated as it moves through the nephron. The PCT is responsible for the reabsorption of about 65% of filtered water and most of the filtered glucose, amino acids, and ions through active transport and cotransport mechanisms. This selective reabsorption is essential for maintaining blood composition and conserving valuable nutrients and electrolytes.', true, '2026-09-09 03:18:31.561', '2026-09-09 03:18:31.561', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5be8808e-9291-42c4-b283-71e5b2a8d6ce', 'Biology', 'JAMB', null, 2003, null, 'A limiting factor in a plant population near a chemical factory is likely to be', null, '["light","humidity","wind","pH"]', 3, 'pH is likely to be a limiting factor near a chemical factory.', true, '2026-10-12 20:59:33.487', '2026-10-12 20:59:33.487', null, null, null, 'A limiting factor in a plant population near a chemical factory is likely to be', '["light","humidity","wind","pH"]', 'pH is likely to be a limiting factor near a chemical factory.', '{"bold":["pH"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5bebc4f9-caa0-452c-9c73-56244f12ba4a', 'Physics', 'JAMB', null, 1990, null, 'A substance has a half life of 3 min. After 6 min, the count rate was observed to be 400. What was its count rate at zero time?', null, '["200","1 200","1 600","2 400"]', 2, '6 min is two half-lives, so the rate fell to 1/4 of the original. The initial rate = 400 x 4 = 1 600.', true, '2026-10-12 19:15:32.271', '2026-10-12 19:15:32.271', null, null, null, 'A substance has a half life of 3 min. After 6 min, the count rate was observed to be 400. What was its count rate at zero time?', '["200","1 200","1 600","2 400"]', '6 min is two half-lives, so the rate fell to 1/4 of the original. The initial rate = 400 x 4 = 1 600.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5bf69951-20c7-457b-abde-c0a8725953dc', 'General Mathematics', 'JAMB', null, 2026, null, 'X, y and z are related such that x varies directly as the cube of y and inversely as the square of z. If x = 108 when y = 3 and z = 4, find z when x = 4000 and y = 10', null, '["±4","4","16","8","None of these"]', 1, 'x = ky³/z². 108 = k(27)/16. k = 64. 4000 = 64(1000)/z². z² = 64000/4000 = 16. z = 4.', true, '2026-09-12 11:43:44.868', '2026-09-12 11:43:44.868', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5bf6cb66-181b-43d8-8897-82ef24062e3e', 'testing', 'JAMB', null, 2024, null, 'The director insisted that every applicant ........the form personally.', null, '["submits","submitted","submit","has submitted"]', 1, 'Subjunctive after ''insisted that''.', true, '2026-10-31 16:48:52.724', '2026-10-31 16:48:52.724', null, null, null, 'The director insisted that every applicant ........the form personally.', '["submits","submitted","submit","has submitted"]', 'Subjunctive after ''insisted that''.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5bfce309-6a6b-4712-aa83-ec5327ae0ef8', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'The Decalogue was given to the Israelites at', null, '["Horeb","Sinai","Gilgal","Shiloh"]', 1, 'The Decalogue (Ten Commandments) was given to Moses on Mount Sinai. God gave Moses the two tablets of stone containing the Ten Commandments on Mount Sinai.', true, '2026-09-12 09:45:46.352', '2026-09-12 09:45:46.352', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5bfe73a4-f5bf-4e8f-b73c-c850c61d3c5a', 'Physics', 'JAMB', null, 2026, null, 'In photo-emission, the number of photoelectrons ejected per second depends on the', null, '["work function of the metal","Threshold frequency of the metals","Intensity of the beam","Frequency of the beam"]', 2, 'In photo-emission, the number of photoelectrons ejected per second depends on the intensity of the beam. Higher intensity means more photons, so more electrons are ejected. The kinetic energy of the electrons depends on frequency and work function.', true, '2026-09-10 10:56:41.031', '2026-09-10 10:56:41.031', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5c0a971c-cc20-4db4-9765-739cf6bb2a3f', 'English Language', 'JAMB', null, 2007, null, 'Three quarters of the hostel <u>------------</u> been painted and three quarters of the students <u>------------</u> moved in.', null, '["has/has","has/have","have/have","have/has"]', 1, 'Hostel singular (has); students plural (have).', true, '2026-10-24 01:02:14.896', '2026-10-24 01:02:14.896', null, null, null, 'Three quarters of the hostel <u>------------</u> been painted and three quarters of the students <u>------------</u> moved in.', '["has/has","<u>has/have</u>","have/have","have/has"]', '<b>Hostel</b> singular (<b>has</b>); <b>students</b> plural (<b>have</b>).', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5c168c31-503c-43f6-8737-3b161083b6ca', 'Physics', 'JAMB', null, 2026, null, 'In an a.c circuit, the ratio of r.m.s value to peak value of current is', null, '["1/√2","√2","2","1/2"]', 0, 'The ratio of r.m.s value to peak value of current is 1/√2. I_rms = I_peak/√2, so the ratio is 1/√2.', true, '2026-09-10 10:56:42.059', '2026-09-10 10:56:42.059', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5c181659-c4bc-4c66-9582-2b418009780b', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Wilfred was a <u>mindless</u> criminal.', null, '["strong","mindful","feeling","memorable"]', 1, 'Mindless = unthinking; opposite = mindful.', true, '2026-10-24 07:21:12.649', '2026-10-24 07:21:12.649', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Wilfred was a <u>mindless</u> criminal.', '["strong","mindful","feeling","memorable"]', 'Mindless = unthinking; opposite = mindful.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5c1e17b3-0019-460f-b949-6fb67efe6471', 'Christian Religious Studies', 'JAMB', null, 2026, null, '''Let it be known to you then that this salvation of God has been sent to the Gentiles, they will listen.'' This implies that', null, '["The Gentiles will be more receptive to Christianity than the Jews","the Jews have lost the opportunity of salvation forever","the Gentiles are very understanding","Paul has completely lost hope in the Jews"]', 0, 'This implies the Gentiles will be more receptive.', true, '2026-09-12 10:41:51.646', '2026-09-12 10:41:51.646', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5c363646-f53a-4646-8b73-57550ed550dd', 'Economics', 'JAMB', null, 2026, null, 'The following are features of monopoly except', null, '["Free entry and exit","Single seller","Goods have no close substitutes","Presence of Market power"]', 0, 'Free entry and exit is a feature of perfect competition, not monopoly. Monopoly has barriers to entry.', true, '2026-09-12 10:59:13.706', '2026-09-12 10:59:13.706', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5c3fcc18-b9c4-4fb5-9b8f-6095aaace3fd', 'Economics', 'JAMB', null, 2026, null, 'The supply curve of a locally-produced good may shift to the right if', null, '["Increase in tax on inputs","Price of commodity rises","Government increases subsidies","Rural-urban migration is encouraged"]', 2, 'Government subsidies reduce production costs and shift supply right.', true, '2026-09-12 11:01:49.748', '2026-09-12 11:01:49.748', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5c43b1d5-b25b-4f4e-9e91-14b29cd67f13', 'Biology', 'JAMB', null, 2026, null, 'In budding, a bud from the ______ fuses with a branch on a ______ and grows into a new plant', null, '["stem, root","leaves, stem","roots, shoots","scion, stock"]', 3, 'In budding, a bud (scion) from the desired plant is fused with a branch on another plant (stock or rootstock). The scion is the bud or shoot that will produce the desired fruit or flowers. The stock provides the root system and sometimes disease resistance or environmental adaptation. The two parts must be compatible species for successful union. The cambium layers of both scion and stock must be aligned for successful grafting. This technique is widely used in fruit tree propagation.', true, '2026-09-09 03:18:34', '2026-09-09 03:18:34', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5c49db71-8720-42a5-bb38-d28284267db2', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The enemy interestingly proved a real <u>bulwark</u> on that memorable day.', null, '["protecting force","source of trouble","troubleshooter","tribulation"]', 0, 'Bulwark = protecting force.', true, '2026-10-24 01:03:59.907', '2026-10-24 01:03:59.907', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The enemy interestingly proved a real <u>bulwark</u> on that memorable day.', '["<u>protecting force</u>","source of trouble","troubleshooter","tribulation"]', '<b>Bulwark</b> = <b>protecting force</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5c513e9c-7413-41b1-a736-b40d0cb34150', 'Economics', 'JAMB', null, 2026, null, 'In the study of economics, land, labour, capital and entrepreneur are referred to as factors of production. These factors produce commodities only if they are', null, '["profitable to the production process","purchased for the purpose of production","combined in the production process","produced adequately for the production process","brought into factory"]', 2, 'Factors of production produce commodities only if they are combined in the production process. Land, labour, capital, and entrepreneurship must be organized together to produce goods and services. Each factor alone cannot produce anything. The entrepreneur combines the other factors in the right proportions to produce goods efficiently.', true, '2026-09-10 10:41:19.754', '2026-09-10 10:41:19.754', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5c568f82-3ab9-40fa-8435-2eacba8f6391', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. You''re <u>impossible</u>; she said to me.', null, '["unreasonable","unforgiving","daft","strong"]', 0, 'Impossible = unreasonable.', true, '2026-10-24 01:01:56.387', '2026-10-24 01:01:56.387', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. You''re <u>impossible</u>; she said to me.', '["<u>unreasonable</u>","unforgiving","daft","strong"]', '<b>Impossible</b> = <b>unreasonable</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5c5d7ec0-a96b-431f-861d-dca02dd4e23b', 'Biology', 'JAMB', null, 2026, null, 'Gases enter and leave the cells of an organism by', null, '["Active transport","Osmosis","Diffusion","Effusion"]', 2, 'Gases enter and leave cells primarily by diffusion, which is the passive movement of molecules from an area of higher concentration to an area of lower concentration. Oxygen diffuses from the blood (higher concentration) into cells (lower concentration), while carbon dioxide diffuses from cells (higher concentration) into the blood (lower concentration). Active transport requires energy and is used for molecules like ions and sugars. Osmosis is specific to water movement. Effusion is the escape of gas through a small opening, not relevant to cellular gas exchange.', true, '2026-09-09 03:18:31.13', '2026-09-09 03:18:31.13', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5c6e2a20-1d05-4bb8-bb52-5a260438ef9a', 'General Mathematics', 'JAMB', null, 2026, null, 'Make M the subject of the equation T = KWM³/XCY²', null, '["CTXY²/KW","∛(KWM³/XCY²)","∛(XCY²/KWM)","CY²/XKWM"]', 2, 'T = KWM³/XCY². Multiply by XCY²: TXCY² = KWM³. Divide by KW: M³ = TXCY²/KW. Take cube root: M = ∛(XCY²/KW). Wait, the equation is T = KWM³/XCY², so TXCY² = KWM³, M³ = TXCY²/KW. But the option says ∛(XCY²/KWM) which is different. The closest is option (C).', true, '2026-09-10 10:48:19.193', '2026-09-10 10:48:19.193', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5c6ed20d-09a2-492c-9322-7f4dd78dd462', 'Physics', 'JAMB', null, 1992, null, 'How much heat is absorbed when a block of copper of mass 0.05 kg and specific heat capacity 390 J kg⁻¹ K⁻¹ is heated from 20 °C to 70 °C?', null, '["3.98 x 10⁻¹ J","9.75 x 10² J","3.98 x 10³ J","9.75 x 10³ J"]', 1, 'Q = mcΔθ = 0.05 x 390 x 50 = 975 J = 9.75 x 10² J.', true, '2026-10-12 19:15:35.444', '2026-10-12 19:15:35.444', null, null, null, 'How much heat is absorbed when a block of copper of mass 0.05 kg and specific heat capacity 390 J kg<sup>-1</sup> K<sup>-1</sup> is heated from 20 °C to 70 °C?', '["3.98 x 10<sup>-1</sup> J","9.75 x 10<sup>2</sup> J","3.98 x 10<sup>3</sup> J","9.75 x 10<sup>3</sup> J"]', 'Q = mcΔθ = 0.05 x 390 x 50 = 975 J = 9.75 x 10<sup>2</sup> J.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5c6f2250-27ca-4825-9d83-66d38b72fe23', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Before the cock crowed, Peter denied Jesus three times. Who was the first person to recognize him?', null, '["a bystander","a maid","one of the rulers","the high Priest"]', 1, 'A maid first recognized Peter.', true, '2026-09-12 10:41:38.363', '2026-09-12 10:41:38.363', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5c8b873e-dd6d-47af-832b-b652b073ffc3', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). Zinana''s examination result was <u>not unfavourable</u>.', null, '["She failed her examination","Her examination did not meet her expectation","She was successful in the examination","Her result could not earn her admission"]', 2, '''Not unfavourable'' = successful.', true, '2026-10-24 01:02:09.557', '2026-10-24 01:02:09.557', null, null, null, '(Choose the most appropriate interpretation). Zinana''s examination result was <u>not unfavourable</u>.', '["She failed her examination","Her examination did not meet her expectation","<u>She was successful in the examination</u>","Her result could not earn her admission"]', '''<b>Not unfavourable</b>'' = <b>successful</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5c90d131-72ee-4a57-b04d-7bcde919cc2d', 'English Language', 'JAMB', null, 2007, null, '''Be that as <u>__________</u> we are determined to get to the root of the matter!'' shouted the officer', null, '["you like","it may","it would","it might"]', 1, 'Correct idiom: be that as it may.', true, '2026-10-24 07:21:42.408', '2026-10-24 07:21:42.408', null, null, null, '''Be that as <u>__________</u> we are determined to get to the root of the matter!'' shouted the officer', '["you like","it may","it would","it might"]', 'Correct idiom: be that as it may.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5ca1e09a-be93-441b-804c-e3c204d70aef', 'Government', 'JAMB', null, 2026, null, 'A major weakness of confederation is', null, '["lack of local independence","lack of common currency","over-concentration of authority","tendency towards secession"]', 3, 'A major weakness of confederation is the tendency towards secession.', true, '2026-09-12 11:24:53.132', '2026-09-12 11:24:53.132', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5ca36749-b73d-4f23-aeb3-a7df663e0928', 'English Language', 'JAMB', null, 2007, null, 'The buildings damaged by the rainstorm <u>------------</u> schools, hospitals and private houses.', null, '["included","include","were included","was including"]', 1, 'Plural ''buildings'' â†’ include.', true, '2026-10-24 01:02:12.583', '2026-10-24 01:02:12.583', null, null, null, 'The buildings damaged by the rainstorm <u>------------</u> schools, hospitals and private houses.', '["included","<u>include</u>","were included","was including"]', 'Plural ''<b>buildings</b>'' â†’ <b>include</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5cb063bd-ecbf-4553-868b-1a35fd1c703c', 'English Language', 'JAMB', null, 2024, null, '''Traumatized'' as used in the passage means', null, '["Angered","Made happy and satisfied","Made sad and dejected","Made to feel guilty"]', 3, '"Traumatized" in this context means made to feel guilty and responsible.', true, '2026-09-18 09:43:02.642', '2026-09-18 09:43:02.642', null, null, 'COMPREHENSION', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5cb662a8-1786-47e0-a09c-25149c4c559f', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Idris gives me a <u>sour</u> look every time I pass by him.', null, '["satisfactory","friendly","sinister","bad"]', 1, 'Sour = unfriendly; opposite = friendly.', true, '2026-10-24 07:21:25.633', '2026-10-24 07:21:25.633', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Idris gives me a <u>sour</u> look every time I pass by him.', '["satisfactory","friendly","sinister","bad"]', 'Sour = unfriendly; opposite = friendly.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5cbce005-86c5-412b-a24b-103bade70b0c', 'Chemistry', 'JAMB', null, 2026, null, 'Calculate the volume of carbon (IV) oxide measured at STP produced when 1kg of potassium hydrogen trioxocarbonate (IV) is totally decomposed by heat (Mv=22.4dm³, K=39, O=16, C=12, H=1)', null, '["28dm³","56dm³","112dm³","196dm³"]', 2, '2KHCO₃ → K₂CO₃ + H₂O + CO₂. Moles KHCO₃ = 1000/100 = 10 mol. Moles CO₂ = 5 mol. Volume = 5 × 22.4 = 112 dm³.', true, '2026-09-12 11:36:01.595', '2026-09-12 11:36:01.595', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5cc4750c-611a-4bc8-ac49-3f700aa92075', 'Biology', 'JAMB', null, 2002, null, 'A flower that has both stamens and pistil is said to be', null, '["Staminate","pistillate","perfect","imperfect"]', 2, 'A flower containing both male (stamen) and female (pistil) reproductive organs is termed a perfect flower.', true, '2026-10-12 20:05:09.101', '2026-10-12 20:05:09.101', null, null, null, 'A flower that has both stamens and pistil is said to be', '["Staminate","pistillate","perfect","imperfect"]', 'A flower containing both male (stamen) and female (pistil) reproductive organs is termed a perfect flower.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5ccfd562-5743-4173-9075-6b8eb2ed743b', 'English Language', 'JAMB', null, 2024, null, 'The story of the Idoma man illustrates that', null, '["People experience life differently despite similar conditions","Everyone who migrates has the same outcome","Only the hardworking succeed abroad","Financial success is guaranteed for migrants"]', 0, 'The story illustrates that people experience life differently despite similar conditions.', true, '2026-09-18 09:43:02.692', '2026-09-18 09:43:02.692', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5cd6a705-010c-4ab9-8839-fbf1e09b15c0', 'Literature in English', 'JAMB', null, 2026, null, '''Parting is such sweet sorrow'' combines contradictory terms. This is', null, '["Paradox","Oxymoron","Irony","Satire"]', 1, 'It is an oxymoron.', true, '2026-09-12 11:11:28.924', '2026-09-12 11:11:28.924', null, null, null, null, null, null, null);
