insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5d088d9d-c6db-4139-9bd2-dda823e07718', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Isa and Iju ate <u>sumptuous</u> meals at their brother''s wedding day.', null, '["foreign","insipid","cheap","expensive"]', 3, 'Sumptuous = expensive.', true, '2026-10-24 01:04:06.708', '2026-10-24 01:04:06.708', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Isa and Iju ate <u>sumptuous</u> meals at their brother''s wedding day.', '["foreign","insipid","cheap","<u>expensive</u>"]', '<b>Sumptuous</b> = <b>expensive</b>.', '{}');
