insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5d10879e-1f52-4097-943f-56c2339f341b', 'Chemistry', 'JAMB', null, 2026, null, 'Which of the following non-metals has the highest electronegativity?', null, '["Oxygen","Chlorine","Nitrogen","Fluorine"]', 3, 'Fluorine is the most electronegative element on the Pauling scale (value of 4.0).', true, '2026-09-09 17:12:48.966', '2026-09-09 17:12:48.966', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5d19c3e1-2b7c-4762-826b-4ae3fcea0d43', 'Physics', 'JAMB', null, 1991, null, 'A wheel and axle have radii 80 cm and 10 cm respectively. If the efficiency of the machine is 0.85, an applied force of 1200 N to the wheel will raise a load of', null, '["8.0 N","6.8 N","8160.0 N","9600.0 N"]', 2, 'VR = 80/10 = 8. MA = efficiency x VR = 0.85 x 8 = 6.8. Load = MA x effort = 6.8 x 1200 = 8160 N.', true, '2026-10-12 19:15:32.758', '2026-10-12 19:15:32.758', null, null, null, 'A wheel and axle have radii 80 cm and 10 cm respectively. If the efficiency of the machine is 0.85, an applied force of 1200 N to the wheel will raise a load of', '["8.0 N","6.8 N","8160.0 N","9600.0 N"]', 'VR = 80/10 = 8. MA = efficiency x VR = 0.85 x 8 = 6.8. Load = MA x effort = 6.8 x 1200 = 8160 N.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5d1d6760-1c4a-40bd-b1a3-58a8163b6777', 'English Language', 'JAMB', null, 2007, null, '<u>__________</u> a good leader must have two characteristics.', null, '["First and formost","First and furmost","First and farmost","First and foremost"]', 3, 'Correct form: First and foremost.', true, '2026-10-24 07:21:36.419', '2026-10-24 07:21:36.419', null, null, null, '<u>__________</u> a good leader must have two characteristics.', '["First and formost","First and furmost","First and farmost","First and foremost"]', 'Correct form: First and foremost.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5d2e44dc-3ad1-4793-9694-2a371ba2d009', 'Biology', 'JAMB', null, 2010, null, 'The average number of individuals of a species per unit area of the habitat is the', null, '["population density","population frequency","population size","population distribution"]', 0, 'Population density is the average number per unit area.', true, '2026-10-12 20:59:40.886', '2026-10-12 20:59:40.886', null, null, null, 'The average number of individuals of a species per unit area of the habitat is the', '["population density","population frequency","population size","population distribution"]', 'Population density is the average number per unit area.', '{"bold":["Population density"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5d3e4199-d5cc-4805-b1d4-127a832a092c', 'Economics', 'JAMB', null, 2026, null, 'The following can be used to improve a country''s balance of payment EXCEPT', null, '["decreasing taxation on personal income","anti-dumping policies","granting subsidies to export producers","increasing import duties"]', 0, 'Decreasing personal income tax does not directly improve balance of payments.', true, '2026-09-12 11:01:29.476', '2026-09-12 11:01:29.476', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5d3f8188-5e67-4055-89b0-5320b0a4dba9', 'Financial Accounting', 'UTME', null, 2001, null, 'Hauwa Ltd bought 10bags of rice for N500 each. The company was given 5% and 12% trade and cash discounts respectively. What will be recorded as a discount received in the company''s book?', null, '["N 250","N 570","N 600","N 850"]', 1, 'Cost = 10 x 500 = 5000. Trade discount 5% = 250. Net = 4750. Cash discount 12% = 570. Discount received = 570.', true, '2026-10-12 22:00:04.413', '2026-10-12 22:00:04.413', null, null, null, 'Hauwa Ltd bought 10bags of rice for N500 each. The company was given 5% and 12% trade and cash discounts respectively. What will be recorded as a discount received in the company''s book?', '["N 250","<b>N 570</b>","N 600","N 850"]', 'Cost = 10 x 500 = 5000. Trade discount 5% = 250. Net = 4750. Cash discount 12% = <b>570</b>.', '{"bold":["570"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5d44d2ba-55d0-4ef3-b3c3-f936c8b8c3b2', 'Literature in English', 'JAMB', null, 2026, null, '''But at my back I always heard Time''s winged chariot hurrying near'' illustrates', null, '["Metaphor","Apostrophe","Oxymoron","Metonymy"]', 0, 'It illustrates metaphor.', true, '2026-09-12 11:10:54.564', '2026-09-12 11:10:54.564', null, null, null, null, null, null, null);
