insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5d539b8a-6b21-4914-93d1-e228b4775f44', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. It is sheer <u>foolhardiness</u> for unarmed policemen to pursue armed robbers.', null, '["nonsense","bravery","foolishness","stupidity","foolish risk taking"]', 4, 'Foolhardiness = foolish risk taking.', true, '2026-10-24 01:01:41.381', '2026-10-24 01:01:41.381', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. It is sheer <u>foolhardiness</u> for unarmed policemen to pursue armed robbers.', '["nonsense","bravery","foolishness","stupidity","<u>foolish risk taking</u>"]', '<b>Foolhardiness</b> = <b>foolish risk taking</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5d567b22-2644-463a-9a4a-627b16b1bee0', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'The Epistle of Romans is significant in discussing the contrast between law and grace. Who is the author of the Epistle to the Romans?', null, '["James","John","Paul","Peter"]', 2, 'Paul wrote the Epistle to the Romans.', true, '2026-09-12 10:41:46.589', '2026-09-12 10:41:46.589', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5d5c2404-4402-4252-a565-b1e06fdf2317', 'Literature in English', 'JAMB', null, 2026, null, 'The dominant feeling in the passage is that of', null, '["hostility","anger","anxiety","bitterness"]', 2, 'The dominant feeling is anxiety.', true, '2026-09-12 11:14:03.645', '2026-09-12 11:14:03.645', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5d605dcd-a746-4133-be20-373902998519', 'Physics', 'JAMB', null, 1990, null, 'Which of the following is most suitable for protecting the circuit of a 2000 W electric iron connected to a 250 V mains?', null, '["13 A","8 A","5 A","3 A"]', 0, 'Normal current = P/V = 2000/250 = 8 A. A fuse must have a rating just above this, so the 13 A fuse is suitable; 8 A is too close and 5 A and 3 A would blow.', true, '2026-10-12 19:15:31.948', '2026-10-12 19:15:31.948', null, null, null, 'Which of the following is most suitable for protecting the circuit of a 2000 W electric iron connected to a 250 V mains?', '["13 A","8 A","5 A","3 A"]', 'Normal current = P/V = 2000/250 = 8 A. A fuse must have a rating just above this, so the 13 A fuse is suitable; 8 A is too close and 5 A and 3 A would blow.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5d6480b1-f9ff-4a7c-9a28-0abf4db947ec', 'English Language', 'JAMB', null, 2024, null, 'What type of education does the writer advocate for our student?', null, '["Vocational as well as technological education","Business, engineering, medicine and computer programming","Technological education plus the humanities","Technology education only"]', 2, 'The writer advocates for technological education combined with the humanities.', true, '2026-09-18 09:43:02.615', '2026-09-18 09:43:02.615', null, null, 'COMPREHENSION', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5d657712-3cae-48da-b508-bf6207defe46', 'Economics', 'JAMB', null, 2026, null, 'Increase in quantity supplied is caused by ______ while increase in supply is caused by ______?', null, '["Increase in Price, increase in other factors","Decrease in price, decrease in other factors","Increase in price, decrease in other factors","decrease in price, increase in other factors"]', 0, 'Increase in quantity supplied is caused by an increase in price. Increase in supply is caused by other factors.', true, '2026-09-12 11:00:15.251', '2026-09-12 11:00:15.251', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5d6a0c71-e5dd-4e55-ad90-ecfd9904033a', 'English Language', 'JAMB', null, 2024, null, 'She was ______ and it was not clear to me what she meant.', null, '["unknown","unintelligible","indefinite","illegible"]', 1, '"Unintelligible" means impossible to understand.', true, '2026-09-18 09:23:08.555', '2026-09-18 09:23:08.555', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5d6ab7da-5f88-4b67-9410-50b966678efe', 'Biology', 'JAMB', null, 2026, null, 'Mineral salts can be absorbed into the roots by', null, '["Osmosis only","Osmosis and diffusion","Diffusion and active transport","Diffusion only"]', 2, 'Mineral salts are absorbed into root cells through two mechanisms: diffusion (passive movement from high to low concentration) and active transport (movement against a concentration gradient using energy, primarily from ATP). Osmosis is responsible only for water absorption, not mineral salts. When mineral concentration in the soil is lower than in root cells, active transport is required. Diffusion occurs when mineral concentration is higher in the soil than in root cells. This combined mechanism allows plants to absorb essential minerals even from dilute soil solutions.', true, '2026-09-09 03:18:22.972', '2026-09-09 03:18:22.972', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5d78ca18-677a-4e99-bb5a-03b3cb1cc1bd', 'Biology', 'JAMB', null, 2026, null, 'The function of the fluid-filled pericardium is to', null, '["reduce the friction by pumping movements of the heart","reduce the intensity of the pumping action of the heart","prevent disease organisms from attacking the heart","supply the heart with oxygen and nutrients"]', 0, 'The pericardium is a double-layered sac surrounding the heart, containing pericardial fluid between its layers. This fluid acts as a lubricant to reduce friction between the heart and surrounding structures as the heart contracts and relaxes during its pumping movements. Without this lubrication, the constant motion of the heart would cause irritation and inflammation. The pericardium also provides protection against infection and anchors the heart in place. The heart receives oxygen and nutrients through the coronary arteries, not the pericardium.', true, '2026-09-09 03:18:20.322', '2026-09-09 03:18:20.322', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5d8a10a3-bc09-4b82-840d-ff09f8717071', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. He is <u>a stringer for</u> a newspaper.', null, '["a financier of","a reporter for","an editor of","a freelancer for"]', 3, 'A stringer = a freelancer for.', true, '2026-10-24 01:04:04.188', '2026-10-24 01:04:04.188', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. He is <u>a stringer for</u> a newspaper.', '["a financier of","a reporter for","an editor of","<u>a freelancer for</u>"]', 'A <b>stringer</b> = <b>a freelancer for</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5d932401-221b-4094-9724-75b35f524131', 'English Language', 'JAMB', null, 2024, null, 'It''s certain we shall travel by train, ______', null, '["Shan''t we?","Shall we?","Is it?","Isn''t it?"]', 0, 'The question tag for "we shall" is "shan''t we?"', true, '2026-09-18 09:34:03.992', '2026-09-18 09:34:03.992', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5da133e0-0ef2-4192-87e5-7f24b83ee451', 'Chemistry', 'JAMB', null, 2026, null, 'Zn + CuSO₄ → ZnSO₄ + Cu. In the reaction above, the oxidation number of the reducing agent changes from?', null, '["0 to +2","+1 to +2","+1 to +3","0 to +4"]', 0, 'Zn (reducing agent) is oxidized from 0 to +2.', true, '2026-09-12 11:36:19.542', '2026-09-12 11:36:19.542', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5dbe14db-9d1c-41fe-9a5c-18e5cd9f75b7', 'Physics', 'JAMB', null, 1984, null, 'If a water pump at Kainji Dam is capable of lifting 1000 kg of water through a vertical height of 10 m in 10 s, the power of the pump is (g = 10 m s⁻²)', null, '["1.0 kW","10.0 kW","12.5 kW","15.0 kW","20.0 kW"]', 1, 'Power = mgh/t = (1000 x 10 x 10)/10 = 10 000 W = 10.0 kW.', true, '2026-10-12 19:15:19.94', '2026-10-12 19:15:19.94', null, null, null, 'If a water pump at Kainji Dam is capable of lifting 1000 kg of water through a vertical height of 10 m in 10 s, the power of the pump is (g = 10 m s<sup>-2</sup>)', '["1.0 kW","10.0 kW","12.5 kW","15.0 kW","20.0 kW"]', 'Power = mgh/t = (1000 x 10 x 10)/10 = 10 000 W = 10.0 kW.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5dc9495d-d284-4ef9-a1f1-bbf8ec7a8b78', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The Senate postponed the meeting <u>indefinitely</u>.', null, '["for a short time","for six months","definitely","without fixing a date","for several months"]', 3, 'Indefinitely = without fixed date.', true, '2026-10-24 01:03:53.975', '2026-10-24 01:03:53.975', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The Senate postponed the meeting <u>indefinitely</u>.', '["for a short time","for six months","definitely","<u>without fixing a date</u>","for several months"]', '<b>Indefinitely</b> = <b>without fixed date</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5dce3bbc-75ca-44d0-8765-65e420edf677', 'Government', 'JAMB', null, 2026, null, 'The political party that was formed from a sociocultural group known as Jamiyya Mutanem Arewa was', null, '["NYM","NCNC","NPC","UPGA"]', 2, 'The political party that was formed from a sociocultural group known as Jamiyya Mutanem Arewa was the NPC (Northern People''s Congress). The Jamiyya Mutanem Arewa was a cultural organization of Northern Nigerian elites. In 1949, it transformed into a political party, the Northern People''s Congress (NPC), which dominated Northern Nigerian politics and later formed the federal government at independence.', true, '2026-09-10 10:45:06.409', '2026-09-10 10:45:06.409', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5ddc9a46-2eff-4f02-a130-d83e60ccf837', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). It would need <u>a high flyer</u> to make a first-class degree in the university.', null, '["a smart performer","an outright genius","an outstanding scholar","an unmitigated swot"]', 2, '''A high flyer'' = outstanding scholar.', true, '2026-10-24 01:02:08.235', '2026-10-24 01:02:08.235', null, null, null, '(Choose the most appropriate interpretation). It would need <u>a high flyer</u> to make a first-class degree in the university.', '["a smart performer","an outright genius","<u>an outstanding scholar</u>","an unmitigated swot"]', '''A <b>high flyer</b>'' = <b>outstanding scholar</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5de134bf-3017-43c5-9b58-16caa6c6e57c', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). The man rebuked his son severely, but his words seem to have <u>cut no ice</u>.', null, '["been convincing","had no effect","not cooled the boy''s temper","added insult to injury"]', 1, '''Cut no ice'' = had no effect.', true, '2026-10-24 01:02:06.38', '2026-10-24 01:02:06.38', null, null, null, '(Choose the most appropriate interpretation). The man rebuked his son severely, but his words seem to have <u>cut no ice</u>.', '["been convincing","<u>had no effect</u>","not cooled the boy''s temper","added insult to injury"]', '''<b>Cut no ice</b>'' = <b>had no effect</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5de44434-96e6-458d-95cc-81d87560caa7', 'Physics', 'JAMB', null, 2004, null, 'For semiconductors to have a negative temperature coefficient of resistance implies that', null, '["They have electrons and holes at high temperatures","Their resistance is constantly changing with temperature","Their resistance increases with temperature","Their resistance decreases with temperature"]', 3, 'A negative temperature coefficient means resistance falls as temperature rises, because more charge carriers are freed.', true, '2026-10-12 19:15:59.195', '2026-10-12 19:15:59.195', null, null, null, 'For semiconductors to have a negative temperature coefficient of resistance implies that', '["They have electrons and holes at high temperatures","Their resistance is constantly changing with temperature","Their resistance increases with temperature","Their resistance decreases with temperature"]', 'A negative temperature coefficient means resistance falls as temperature rises, because more charge carriers are freed.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5dec43b9-2a49-4f7c-8d5d-9582f7d34056', 'Physics', 'JAMB', null, 1993, null, 'Which of the following quantities has the same unit as the watt?', null, '["Force x time","Force x distance","Force x acceleration","Force x velocity"]', 3, 'Power = work/time = force x distance/time = force x velocity, which is measured in watts.', true, '2026-10-12 19:15:36.895', '2026-10-12 19:15:36.895', null, null, null, 'Which of the following quantities has the same unit as the watt?', '["Force x time","Force x distance","Force x acceleration","Force x velocity"]', 'Power = work/time = force x distance/time = force x velocity, which is measured in watts.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5df1c115-3e61-4334-b738-d6b40e675eeb', 'Biology', 'JAMB', null, 2026, null, 'If a tall man TT marries a dwarf woman tt and they have four children, the offspring will be', null, '["all short","three short, one tall","two short, two tall","one short and three tall","all tall"]', 4, 'The offspring from a tall man (TT) and a dwarf woman (tt) will all be tall. All children will be heterozygous (Tt) and tall because tallness (T) is dominant over dwarfness (t). The cross is TT × tt, producing all Tt offspring. Even though they carry the allele for dwarfness, it is not expressed. This is an example of complete dominance where the dominant trait is expressed in all heterozygous individuals.', true, '2026-09-09 03:19:15.207', '2026-09-09 03:19:15.207', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5df4fd40-005d-484d-a4d6-2ec07c3ab14c', 'Economics', 'JAMB', null, 2026, null, 'Which of these is not an importance of Agriculture in an economy', null, '["Provision of food","Provision of raw materials for industries","Source of foreign exchange","Unemployment opportunities"]', 3, 'Agriculture provides employment opportunities, not unemployment.', true, '2026-09-12 11:00:33.358', '2026-09-12 11:00:33.358', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5e0211e8-abf3-42e6-9888-6cc1381d7bb0', 'Literature in English', 'JAMB', null, 2026, null, 'The major part of the Petrarchan sonnet is the', null, '["octave","sestet","quatrain","tercet"]', 0, 'The octave is the major part of the Petrarchan sonnet.', true, '2026-09-12 11:14:01.704', '2026-09-12 11:14:01.704', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5e0cd4ff-0358-43cb-89a0-e092bd6b3dc6', 'Biology', 'JAMB', null, 2026, null, 'One advantage of variation in a species population is that individuals', null, '["with favored traits become dominant","easily reach their reproductive age","are easily recognized by mates","are better adapted to changes"]', 3, 'One advantage of variation in a species population is that individuals are better adapted to changes. Variation provides the raw material for natural selection, allowing populations to adapt to changing environmental conditions. When the environment changes, some individuals with beneficial traits will survive and reproduce, passing on their traits. This is the basis of evolution by natural selection. Variation ensures that not all individuals are affected the same way by environmental changes.', true, '2026-09-09 03:19:12.956', '2026-09-09 03:19:12.956', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5e16b6c0-4a17-4063-a869-b608c7559cac', 'Biology', 'JAMB', null, 2026, null, 'The activity of an organism which affects the survival of another organism in the same habitat constitutes', null, '["An edaphic factor","An abiotic factor","A biotic factor","A physiographic factor"]', 2, 'A biotic factor is an activity of an organism that affects the survival of another organism in the same habitat. Biotic factors include interactions like predation, competition, parasitism, mutualism, and disease. Edaphic factors relate to soil conditions. Abiotic factors are non-living physical or chemical factors (temperature, water, light). Physiographic factors are related to the physical geography (altitude, slope). Biotic factors are the living components of an ecosystem that influence other organisms.', true, '2026-09-09 03:18:59.705', '2026-09-09 03:18:59.705', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5e257a84-dea2-410d-9b64-320bd9efb0ba', 'Government', 'JAMB', null, 2026, null, 'The central legislature of Nigeria became bicameral in', null, '["1960","1951","1959","1963"]', 0, 'The central legislature became bicameral in 1960.', true, '2026-09-12 11:24:34.262', '2026-09-12 11:24:34.262', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5e28b619-a89b-495d-bd85-b30944b17321', 'Biology', 'JAMB', null, 2026, null, 'The blood component that has the greatest affinity for oxygen is the', null, '["Lymphocytes","Leucocytes","Erythrocytes","Thrombocytes"]', 2, 'Erythrocytes (red blood cells) have the greatest affinity for oxygen due to the presence of hemoglobin, the oxygen-carrying protein. Hemoglobin binds to oxygen in the lungs and releases it in tissues. Lymphocytes and leucocytes are white blood cells involved in immunity. Thrombocytes are platelets involved in blood clotting. Erythrocytes are specifically adapted for oxygen transport, with hemoglobin making up about 90% of their protein content. Their shape (biconcave) maximizes surface area for gas exchange.', true, '2026-09-09 03:19:00.773', '2026-09-09 03:19:00.773', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5e43c98f-9660-447f-ace7-f18dd766de63', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). Surely, Ahmed is <u>a ball of fire</u>', null, '["a quarrelsome person","a hot-headed activist","a fiery speaker or writer","a very energetic person"]', 3, '''A ball of fire'' = very energetic person.', true, '2026-10-24 01:02:07.864', '2026-10-24 01:02:07.864', null, null, null, '(Choose the most appropriate interpretation). Surely, Ahmed is <u>a ball of fire</u>', '["a quarrelsome person","a hot-headed activist","a fiery speaker or writer","<u>a very energetic person</u>"]', '''A <b>ball of fire</b>'' = <b>very energetic person</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5e54bf5b-5a7b-449d-b662-4e49cd8e7129', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. In his quest for <u>solidarity</u>, the party leader undertook a nation-wide tour.', null, '["unity","resistance","mobilization","re-organization"]', 1, 'Solidarity = unity; opposite = resistance.', true, '2026-10-24 07:21:16.791', '2026-10-24 07:21:16.791', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. In his quest for <u>solidarity</u>, the party leader undertook a nation-wide tour.', '["unity","resistance","mobilization","re-organization"]', 'Solidarity = unity; opposite = resistance.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5e5fa74d-4768-41aa-b564-b8b6693ed04a', 'Physics', 'JAMB', null, 1983, null, 'A 24 V potential difference is applied across a parallel combination of four 6-ohm resistors. The current in each resistor is', null, '["1 A","4 A","16 A","18 A","36 A"]', 1, 'In a parallel combination each resistor has the full 24 V across it, so I = V/R = 24/6 = 4 A.', true, '2026-10-12 19:15:16.985', '2026-10-12 19:15:16.985', null, null, null, 'A 24 V potential difference is applied across a parallel combination of four 6-ohm resistors. The current in each resistor is', '["1 A","4 A","16 A","18 A","36 A"]', 'In a parallel combination each resistor has the full 24 V across it, so I = V/R = 24/6 = 4 A.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5e70d8be-d317-45b1-ab52-d28f4e73b1e4', 'Biology', 'JAMB', null, 2010, null, 'In the male reproductive system of a mammal, sperm is stored in the', null, '["vas deferens","urethra","epididymis","seminiferous tubules"]', 2, 'Sperm is stored in the epididymis.', true, '2026-10-12 20:59:40.265', '2026-10-12 20:59:40.265', null, null, null, 'In the male reproductive system of a mammal, sperm is stored in the', '["vas deferens","urethra","epididymis","seminiferous tubules"]', 'Sperm is stored in the epididymis.', '{"bold":["epididymis"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5e720377-53c2-4ffb-a62d-91b80c39db8a', 'Literature in English', 'JAMB', null, 2026, null, 'The primary cause of Chaoticleer''s near fatal encounter with the fox in The Nun''s Priest Tale is his susceptibility to', null, '["destiny","gluttony","flattery","love"]', 2, 'His susceptibility to flattery is the cause.', true, '2026-09-12 11:10:59.783', '2026-09-12 11:10:59.783', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5e745bb2-ff26-4459-96b5-479dae8ad407', 'Physics', 'JAMB', null, 1991, null, 'The function of the system of granulated carbon mixed with manganese (IV) oxide in a Leclanché cell is to', null, '["Increase the e.m.f. of the cell to 2.0 V","Prevent local action in the cell","Prevent polarization in the cell","Make the cell black and hence a good radiator"]', 2, 'Manganese dioxide oxidises the hydrogen gas that would otherwise collect on the carbon rod, which prevents polarization.', true, '2026-10-12 19:15:34.052', '2026-10-12 19:15:34.052', null, null, null, 'The function of the system of granulated carbon mixed with manganese (IV) oxide in a Leclanché cell is to', '["Increase the e.m.f. of the cell to 2.0 V","Prevent local action in the cell","Prevent polarization in the cell","Make the cell black and hence a good radiator"]', 'Manganese dioxide oxidises the hydrogen gas that would otherwise collect on the carbon rod, which prevents polarization.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5e8146d7-c194-4f4a-a3b2-21355eac9dc5', 'Chemistry', 'JAMB', null, 2026, null, 'The halogen which is chiefly produced commercially from sea water is', null, '["fluorine","chlorine","iodine","bromine"]', 3, 'Bromine is commercially extracted from seawater and natural brine solutions using chlorine displacement gas oxidation.', true, '2026-09-09 17:12:45.739', '2026-09-09 17:12:45.739', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5e90b0b1-aa67-4bc3-9580-db8e65681638', 'General Mathematics', 'JAMB', null, 2026, null, 'Find the angle between the lines: y = 3x - 4 and 2x - y + 1 = 0', null, '["5.4°","2.7°","8.1°","12.3°"]', 0, 'm₁ = 3, m₂ = 2. tanθ = |(3-2)/(1+6)| = 1/7. θ = tan⁻¹(1/7) = 8.1°. The answer is (C) 8.1°.', true, '2026-09-12 11:43:56.154', '2026-09-12 11:43:56.154', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5ea19c8e-9f0e-4cdf-bfa9-ec66fca885c2', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). You need to <u>brush up on</u> your Spanish.', null, '["You need to study the history of Spain","You need to improve your skills","You need a brush from Spain","You need to learn to play with a Spaniard"]', 1, '''Brush up on'' = improve/refresh skills.', true, '2026-10-24 01:02:09.609', '2026-10-24 01:02:09.609', null, null, null, '(Choose the most appropriate interpretation). You need to <u>brush up on</u> your Spanish.', '["You need to study the history of Spain","<u>You need to improve your skills</u>","You need a brush from Spain","You need to learn to play with a Spaniard"]', '''<b>Brush up on</b>'' = <b>improve/refresh skills</b>.', '{}');
