insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5ea96392-4b74-4116-84f1-bcfdcd2044bf', 'English Language', 'JAMB', null, 2007, null, 'One of the rioters who <u>------------</u> arrested yesterday <u>------------</u> released.', null, '["was/has been","were/have been","was/have been","were/has been"]', 3, '''Who'' â†’ rioters (were); ''one'' â†’ has been.', true, '2026-10-24 01:02:12.427', '2026-10-24 01:02:12.427', null, null, null, 'One of the rioters who <u>------------</u> arrested yesterday <u>------------</u> released.', '["was/has been","were/have been","was/have been","<u>were/has been</u>"]', '''<b>Who</b>'' â†’ <b>rioters</b> (<b>were</b>); ''<b>one</b>'' â†’ <b>has been</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5eb6ccb4-0188-4058-bc25-89423338b1f7', 'General Mathematics', 'JAMB', null, 2026, null, 'A triangle has a base of 8 cm and height of 5 cm. Find its area.', null, '["15 cm²","18 cm²","20 cm²","40 cm²"]', 2, 'Area = ½ × 8 × 5 = 20 cm².', true, '2026-09-12 11:44:12.045', '2026-09-12 11:44:12.045', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5ebfaf3e-b3fb-44d1-a8c8-53f07eeb63cd', 'English Language', 'JAMB', null, 2007, null, 'Everyone makes mistakes occasionally; nobody is <u>__________</u>', null, '["incorrigible","imperfect","infallible","indestructible"]', 2, 'Correct spelling: infallible.', true, '2026-10-24 07:21:39.469', '2026-10-24 07:21:39.469', null, null, null, 'Everyone makes mistakes occasionally; nobody is <u>__________</u>', '["incorrigible","imperfect","infallible","indestructible"]', 'Correct spelling: infallible.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5ec0dbb4-04de-4951-9a87-f25f03671e63', 'Chemistry', 'JAMB', null, 2026, null, 'Which homologous series has the general formula CₙH₂ₙ₊₂?', null, '["Alkane","Alkenes","Alkynes","Alcohols"]', 0, 'Alkanes have the general formula CₙH₂ₙ₊₂.', true, '2026-09-12 11:32:57.859', '2026-09-12 11:32:57.859', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5ece07b8-3231-49af-866f-ea88ac604bf5', 'Literature in English', 'JAMB', null, 2026, null, 'The title Redemption Road is most appropriately interpreted as symbolizing', null, '["Economic recovery after colonialism","A literal journey taken by refugees","The moral and psychological quest for healing and forgiveness","Political reform in post-independence Africa"]', 2, 'The title symbolizes the moral and psychological quest for healing and forgiveness.', true, '2026-09-12 11:12:01.647', '2026-09-12 11:12:01.647', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5ed497eb-e2b4-40db-be54-e9eaace478c0', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Everyone admired the manager''s <u>adroit</u> handling of the crises in the company.', null, '["clever","clumsy","skilful","tactless"]', 1, 'Adroit = skilful; opposite = clumsy.', true, '2026-10-24 07:21:23.364', '2026-10-24 07:21:23.364', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Everyone admired the manager''s <u>adroit</u> handling of the crises in the company.', '["clever","clumsy","skilful","tactless"]', 'Adroit = skilful; opposite = clumsy.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5ed9aefa-6b65-4741-beb7-e10c25970ef9', 'Physics', 'JAMB', null, 1993, null, 'Determine the inductive reactance when a 30.0 mH inductor with a negligible resistance is connected to a 1.30 x 10³ Hz oscillator.', null, '["39.0 Ω","122.5 Ω","245.0 Ω","39000.0 Ω"]', 2, 'XL = 2πfL = 2π x 1300 x 0.030 ≈ 245 Ω.', true, '2026-10-12 19:15:38.62', '2026-10-12 19:15:38.62', null, null, null, 'Determine the inductive reactance when a 30.0 mH inductor with a negligible resistance is connected to a 1.30 x 10<sup>3</sup> Hz oscillator.', '["39.0 Ω","122.5 Ω","245.0 Ω","39000.0 Ω"]', 'X<sub>L</sub> = 2πfL = 2π x 1300 x 0.030 ≈ 245 Ω.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5eea85f2-fb09-46c7-bc3f-36c90a2c054b', 'Biology', 'JAMB', null, 2026, null, 'The digestive enzymes found in the ileum is', null, '["trypsin","pepsin","erepsin","renin"]', 2, 'Erepsin is a digestive enzyme found in the ileum (small intestine). It is a mixture of peptidases that completes protein digestion by breaking down peptides into amino acids. Trypsin is a pancreatic enzyme that acts in the duodenum. Pepsin is a gastric enzyme active in the stomach. Renin is produced in the stomach of infants to digest milk proteins. The ileum is the final part of the small intestine where digestion is completed and absorption occurs, and erepsin is one of the enzymes present in the intestinal juice (succus entericus).', true, '2026-09-09 03:18:51.95', '2026-09-09 03:18:51.95', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5eeb3916-0693-4a15-993e-7c45b6e8b8bb', 'Financial Accounting', 'UTME', null, 2003, null, 'Given: N Cost of raw material issued to production 37 000 Opening stock of raw material 2 000 Purchases of raw material 38 000 Wages 5 000. What is the closing stock of raw material?', null, '["N4 000","N3 000","N2 000","N1 000"]', 1, 'Opening Stock of R.M. 2000 + Purchases 38000 = 40000. Less Mat. Issued to Production 37,000. Closing Stock = 3000.', true, '2026-10-12 22:00:00.47', '2026-10-12 22:00:00.47', null, null, null, 'Given: N Cost of raw material issued to production 37 000 Opening stock of raw material 2 000 Purchases of raw material 38 000 Wages 5 000. What is the closing stock of raw material?', '["N4 000","<b>N3 000</b>","N2 000","N1 000"]', 'Opening Stock of R.M. 2000 + Purchases 38000 = 40000. Less Mat. Issued to Production 37,000. Closing Stock = <b>3000</b>.', '{"bold":["3000"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5eee3c39-620f-4d06-a4e5-4603c80041fb', 'Physics', 'JAMB', null, 1991, null, 'When a plane mirror at which a ray is incident is rotated through an angle θ, the reflected ray will be rotated through', null, '["½θ","θ","2θ","3θ"]', 2, 'Rotating a mirror by θ while the incident ray stays fixed turns the reflected ray through 2θ.', true, '2026-10-12 19:15:33.569', '2026-10-12 19:15:33.569', null, null, null, 'When a plane mirror at which a ray is incident is rotated through an angle θ, the reflected ray will be rotated through', '["½θ","θ","2θ","3θ"]', 'Rotating a mirror by θ while the incident ray stays fixed turns the reflected ray through 2θ.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5ef00ed7-463e-4f48-a1fb-35fad65a2d5b', 'Physics', 'JAMB', null, 1985, null, 'The areas of the effort and load pistons of a hydraulic press are 0.5 m² and 5 m² respectively. If a force F₁ of 100 N is applied on the effort piston, the force F₂ on the load is', null, '["10 N","100 N","500 N","1 000 N","5 000 N"]', 3, 'Pressure is transmitted equally: F₂ = F₁ x (A₂/A₁) = 100 x (5/0.5) = 1 000 N.', true, '2026-10-12 19:15:21.095', '2026-10-12 19:15:21.095', null, null, null, 'The areas of the effort and load pistons of a hydraulic press are 0.5 m<sup>2</sup> and 5 m<sup>2</sup> respectively. If a force F<sub>1</sub> of 100 N is applied on the effort piston, the force F<sub>2</sub> on the load is', '["10 N","100 N","500 N","1 000 N","5 000 N"]', 'Pressure is transmitted equally: F<sub>2</sub> = F<sub>1</sub> x (A<sub>2</sub>/A<sub>1</sub>) = 100 x (5/0.5) = 1 000 N.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5f144612-b0e3-452d-a35a-cdf161c3b937', 'Economics', 'JAMB', null, 2026, null, 'One of the following is not a source of government revenue', null, '["Tax","Subsidy","Licenses","Royalties"]', 1, 'Subsidy is government expenditure, not revenue.', true, '2026-09-12 11:01:14.23', '2026-09-12 11:01:14.23', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5f20ff75-eafd-4eca-aa60-de554b8fd191', 'Physics', 'JAMB', null, 2026, null, 'A photon of wavelength 6×10⁻⁷ m behaves like a particle of certain mass. The value of the mass is', null, '["3.6×10⁻³⁶ kg","3.6×10⁻³⁵ kg","3.5×10⁻³⁵ kg","3.5×10⁻³⁶ kg"]', 0, 'Using de Broglie''s equation: λ = h/p, so p = h/λ. p = (6.63×10⁻³⁴)/(6×10⁻⁷) = 1.105×10⁻²⁷ kg·m/s. Mass equivalent m = p/c = (1.105×10⁻²⁷)/(3×10⁸) = 3.68×10⁻³⁶ kg ≈ 3.6×10⁻³⁶ kg.', true, '2026-09-10 10:56:41.247', '2026-09-10 10:56:41.247', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5f27b5d2-e154-47f2-9969-b16f0ec20eb9', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'The prophecy “The soul that sins shall die”, was given by the Prophet...', null, '["Isaiah","Amos","Hosea","Ezekiel"]', 3, 'Ezekiel 18:4 explicitly declares individual moral responsibility: ''The soul who sins shall die.''', true, '2026-09-09 17:18:28.148', '2026-09-09 17:18:28.148', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5f4abd57-5211-491b-8867-4680d9d39c43', 'General Mathematics', 'JAMB', null, 2026, null, 'From two points x and y, 8cm apart, and in line with a pole. The angle of elevation of the top of the pole are 30° and 60° respectively. Find the height of the pole', null, '["4m","2√2","3√4","3m","4√3m"]', 0, 'Let height = h. Distance from x = h/tan30 = h√3. Distance from y = h/tan60 = h/√3. h√3 - h/√3 = 8. (3h-h)/√3 = 8. 2h = 8√3. h = 4√3. The answer is (E) 4√3m.', true, '2026-09-12 11:44:22.221', '2026-09-12 11:44:22.221', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5f4e49c7-c4bd-4f28-8133-d7d2f5acbe02', 'Physics', 'JAMB', null, 2004, null, 'Tea pots are often silver-coated to prevent heat loss by', null, '["Convection and conduction","Radiation only","Conduction only","Convection only."]', 1, 'A shiny silver surface is a poor emitter of radiation, so it reduces heat loss by radiation.', true, '2026-10-12 19:15:59.784', '2026-10-12 19:15:59.784', null, null, null, 'Tea pots are often silver-coated to prevent heat loss by', '["Convection and conduction","Radiation only","Conduction only","Convection only."]', 'A shiny silver surface is a poor emitter of radiation, so it reduces heat loss by radiation.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5f5035bc-23bb-4141-9f5e-ddd73d66aa03', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Sule admires people who have <u>unbending</u> character', null, '["mobile","steady","wavering","unstable"]', 1, 'Unbending = steady.', true, '2026-10-24 01:04:11.973', '2026-10-24 01:04:11.973', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Sule admires people who have <u>unbending</u> character', '["mobile","<u>steady</u>","wavering","unstable"]', '<b>Unbending</b> = <b>steady</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5f51fb59-cecf-4a59-b99f-276e4d68d8bd', 'Economics', 'JAMB', null, 2026, null, 'Which of the following is not a function of the money market?', null, '["Lender of loans","Provision of finance","Creation of long-term loans","Acceptance of deposits"]', 2, 'The money market deals with short-term loans. Long-term loans are the function of the capital market.', true, '2026-09-12 10:58:42.227', '2026-09-12 10:58:42.227', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5f526cb6-9152-4542-897e-112a7e5b5cf7', 'English Language', 'JAMB', null, 2024, null, 'It is ______ in colour.', null, '["reddish-brown","brownish-green","yellowish-brown","brownish-pink"]', 0, 'The liver is reddish-brown in colour.', true, '2026-09-18 09:43:02.836', '2026-09-18 09:43:02.836', null, null, 'CLOZE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5f55560e-3b55-4f97-82a5-6e1c49c9368b', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Aisha seems to feel <u>ambivalent</u> about her future.', null, '["anxious","ambitious","inconsiderate","decisive"]', 3, 'Ambivalent = uncertain; opposite = decisive.', true, '2026-10-24 07:21:26.587', '2026-10-24 07:21:26.587', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Aisha seems to feel <u>ambivalent</u> about her future.', '["anxious","ambitious","inconsiderate","decisive"]', 'Ambivalent = uncertain; opposite = decisive.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5f585e81-ba07-48e7-99e6-5e3971851fe3', 'Biology', 'JAMB', null, 2026, null, 'Mangrove swamp can be found', null, '["on a mud flat near the sea","where a river meets the sea","where two rivers meet","on a seashore with flat terrains"]', 1, 'Mangrove swamps are typically found in estuaries where a river meets the sea, providing brackish water conditions.', true, '2026-09-09 02:56:40.47', '2026-09-09 02:56:40.47', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5f5c8e8c-cfaf-46af-89cc-fb5667ffc61b', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. A few years ago, nobody would have believed that the economy would <u>turn around</u>.', null, '["deteriorate","improve","stagnate","change"]', 1, 'Turn around = improve.', true, '2026-10-24 01:04:04.563', '2026-10-24 01:04:04.563', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. A few years ago, nobody would have believed that the economy would <u>turn around</u>.', '["deteriorate","<u>improve</u>","stagnate","change"]', '<b>Turn around</b> = <b>improve</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5f5f1cfd-cc06-4fff-a889-82bb92504208', 'Literature in English', 'JAMB', null, 2026, null, 'Ananse''s extraordinary address of appellation of the chiefs is the theme of', null, '["manipulation","flattery","respect","I too doy do"]', 1, 'The theme is flattery.', true, '2026-09-12 11:10:04.057', '2026-09-12 11:10:04.057', null, null, null, null, null, null, null);
