insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5f6a6672-e028-452c-8248-b14942f93407', 'Economics', 'JAMB', null, 2026, null, 'Which of the following forms of economic integration is a member nation free to impose duty against non-members?', null, '["Common market","Free trade area","Custom union","Economic community"]', 1, 'In a free trade area, members can impose different duties on non-members.', true, '2026-09-12 11:02:13.816', '2026-09-12 11:02:13.816', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5f79e8ab-1af1-4836-992c-35060a709082', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). The legislator has decided to <u>play second fiddle</u> after he had been walked out of the Assembly for violating basic procedure of the House. This means that the legislator has decided to ______________', null, '["oppose every motion in the House","support every motion in the House","condemn every motion","support the lead given by others","become active in the house"]', 3, '''Play second fiddle'' means take a subordinate role.', true, '2026-10-24 01:04:12.958', '2026-10-24 01:04:12.958', null, null, null, '(Choose the most appropriate interpretation). The legislator has decided to <u>play second fiddle</u> after he had been walked out of the Assembly for violating basic procedure of the House. This means that the legislator has decided to ______________', '["oppose every motion in the House","support every motion in the House","condemn every motion","<u>support the lead given by others</u>","become active in the house"]', '''<b>Play second fiddle</b>'' means take a <b>subordinate role</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5f9145cf-f8f7-40b6-a745-db4d9909c163', 'English Language', 'JAMB', null, 2007, null, 'I have no respect for individuals who are too <u>__________</u>', null, '["compliance","compliant","compliable","complicated"]', 1, 'Correct spelling: compliant.', true, '2026-10-24 07:21:34.102', '2026-10-24 07:21:34.102', null, null, null, 'I have no respect for individuals who are too <u>__________</u>', '["compliance","compliant","compliable","complicated"]', 'Correct spelling: compliant.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5f916cdb-fd0c-4f63-8f00-09b6cd18932b', 'Financial Accounting', 'UTME', null, 2004, null, 'The cost of raw materials consumed is', 'https://res.cloudinary.com/kwi1uv0g/image/upload/v1791841895/questions/vqlnhihcunvaucx6fsy2.jpg', '["N17 250","N15 750","N15 000","N14 250"]', 3, 'Opening stock of R. material 2250 + Purchases 15000 = 17250. Less Closing stock 3000 = Cost of R. materials consumed 14250.', true, '2026-10-12 22:00:03.034', '2026-10-12 22:00:03.034', null, null, null, 'The cost of raw materials consumed is', '["N17 250","N15 750","N15 000","<b>N14 250</b>"]', 'Opening stock of R. material 2250 + Purchases 15000 = 17250. Less Closing stock 3000 = Cost of R. materials consumed <b>14250</b>.', '{"bold":["14250"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5f9283f1-9283-4cff-86b3-02c2f42b3fa8', 'English Language', 'JAMB', null, 2024, null, '(Emphatic Stress) The teacher wants MY pen', null, '["Does the teacher want his pen?","What does the teacher want?","Does the teacher want your ruler?","Who wants my pen?"]', 0, 'The emphasis on "MY" contrasts with "his pen."', true, '2026-09-18 09:24:04.779', '2026-09-18 09:24:04.779', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5f9857bc-9e4b-48b6-9c64-26b509aa7e11', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. She gave a <u>caustic</u> remark on the occasion.', null, '["tangible","friendly","polite","sarcastic"]', 3, 'Caustic = sarcastic.', true, '2026-10-24 01:04:11.599', '2026-10-24 01:04:11.599', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. She gave a <u>caustic</u> remark on the occasion.', '["tangible","friendly","polite","<u>sarcastic</u>"]', '<b>Caustic</b> = <b>sarcastic</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5f9906ba-93be-4f5c-8070-50a3c23b52b3', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. In spite of constant financial support from his father, Udenyi treats his studies with considerable <u>levity</u>.', null, '["lassitude","wastefulness","enthusiasm","seriousness"]', 0, 'Levity = lack of seriousness; closest = lassitude.', true, '2026-10-24 01:01:53.002', '2026-10-24 01:01:53.002', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. In spite of constant financial support from his father, Udenyi treats his studies with considerable <u>levity</u>.', '["<u>lassitude</u>","wastefulness","enthusiasm","seriousness"]', '<b>Levity</b> = lack of seriousness; closest = <b>lassitude</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5f9f4ebe-fda8-4a7c-8313-b12e6a52ec25', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The gateman does his work <u>perfunctorily</u>.', null, '["without commitment","with speed","grudgingly","enthusiastically"]', 0, 'Perfunctorily = without commitment.', true, '2026-10-24 01:04:01.192', '2026-10-24 01:04:01.192', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The gateman does his work <u>perfunctorily</u>.', '["<u>without commitment</u>","with speed","grudgingly","enthusiastically"]', '<b>Perfunctorily</b> = <b>without commitment</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5fa6d858-491d-4c5e-9f77-8386da6e0199', 'Physics', 'JAMB', null, 2004, null, 'In which of the following material media would sound travel faster?', null, '["Water","Oil","Metal","Gas"]', 2, 'Sound travels fastest in solids such as metals because the particles are closely packed and rigid.', true, '2026-10-12 19:15:58.284', '2026-10-12 19:15:58.284', null, null, null, 'In which of the following material media would sound travel faster?', '["Water","Oil","Metal","Gas"]', 'Sound travels fastest in solids such as metals because the particles are closely packed and rigid.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5fab77cb-509d-4870-b814-b109777d6cb3', 'Hausa', 'JAMB', null, 2011, null, 'A Gandƙki na Walin Katsina A. Bello an nuna Gandƙki ya yi faƙa har da', null, '["aljannu","mata","dabbobi","sarauniya."]', 0, 'An nuna Gandƙki ya yi faƙa har da aljannu.', true, '2026-10-13 10:37:22.534', '2026-10-13 10:37:22.534', null, null, null, 'A Gandƙki na Walin Katsina A. Bello an nuna Gandƙki ya yi faƙa har da', '["aljannu","mata","dabbobi","sarauniya."]', 'An nuna Gandƙki ya yi faƙa har da aljannu.', '{"bold":["aljannu"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5fb43f81-95b9-4327-99b9-4bae4c2059cd', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Everybody <u>respects</u> the team leader.', null, '["looks up for","looks up on","looks up to","looks up at"]', 2, 'Respects = looks up to.', true, '2026-10-24 01:03:54.618', '2026-10-24 01:03:54.618', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Everybody <u>respects</u> the team leader.', '["looks up for","looks up on","<u>looks up to</u>","looks up at"]', '<b>Respects</b> = <b>looks up to</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5fb58685-b244-4b16-9d91-f6473e6bdb5f', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). The man insisted on having <u>no strings attached</u> to the agreement.', null, '["financial obligations","documents","conditions","moral obligations"]', 2, '''No strings attached'' = without conditions.', true, '2026-10-24 01:02:06.063', '2026-10-24 01:02:06.063', null, null, null, '(Choose the most appropriate interpretation). The man insisted on having <u>no strings attached</u> to the agreement.', '["financial obligations","documents","<u>conditions</u>","moral obligations"]', '''<b>No strings attached</b>'' = <b>without conditions</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5fb9e5e9-0b19-4ad2-86ab-9be126f7eb1d', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. One of the students bought a <u>plagiarized</u> copy of the book', null, '["a used","an original","revised","an annotated"]', 1, 'Plagiarized = copied; opposite = original.', true, '2026-10-24 07:21:31.586', '2026-10-24 07:21:31.586', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. One of the students bought a <u>plagiarized</u> copy of the book', '["a used","an original","revised","an annotated"]', 'Plagiarized = copied; opposite = original.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5fbf86ca-bd87-47c4-a684-b68ac46c221f', 'Literature in English', 'JAMB', null, 2026, null, 'In Not My Business, the repeated phrase ''What business of mine is it...'' serves as', null, '["Irony exposing societal indifference","Alliteration for sound effect","Euphemism for fear","Metaphor for oppression"]', 0, 'The phrase is irony exposing societal indifference.', true, '2026-09-12 11:09:58.353', '2026-09-12 11:09:58.353', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5fbfbdfa-dbcd-46f7-b27f-9ec5116b2a55', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). The officer refused to be <u>taken in</u> by the private.', null, '["won over","drawn in","overtaken","deceived","involved"]', 3, '''Taken in'' = deceived.', true, '2026-10-24 01:04:16.16', '2026-10-24 01:04:16.16', null, null, null, '(Choose the most appropriate interpretation). The officer refused to be <u>taken in</u> by the private.', '["won over","drawn in","overtaken","<u>deceived</u>","involved"]', '''<b>Taken in</b>'' = <b>deceived</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5fc47e16-ffbc-42d6-8322-776225c4bbbf', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. He gave an unsatisfactory excuse but the boss <u>swallowed it hook, line and sinker</u>.', null, '["completely","with a pinch of salt","entirely","without mincing words"]', 1, 'Swallowed hook, line and sinker = believed fully; opposite = with a pinch of salt.', true, '2026-10-24 07:21:23.062', '2026-10-24 07:21:23.062', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. He gave an unsatisfactory excuse but the boss <u>swallowed it hook, line and sinker</u>.', '["completely","with a pinch of salt","entirely","without mincing words"]', 'Swallowed hook, line and sinker = believed fully; opposite = with a pinch of salt.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5fcab569-7950-4acc-bcbd-d9e8e26db22b', 'testing', 'JAMB', null, 2024, null, 'It is high time the government .... action.', null, '["takes","took","has taken","will take"]', 1, '''It is high time'' + past subjunctive ''took''.', true, '2026-10-31 16:48:52.669', '2026-10-31 16:48:52.669', null, null, null, 'It is high time the government .... action.', '["takes","took","has taken","will take"]', '''It is high time'' + past subjunctive ''took''.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5fe5c7f7-1435-421b-be4c-2438d3ca5458', 'Christian Religious Studies', 'JAMB', null, 2026, null, '''Here am I send me.'' Which prophet said this in response to his call?', null, '["Hosea","Ezekiel","Jeremiah","Isaiah","Amos"]', 3, 'Isaiah responded to God''s call with ''Here am I! Send me.''', true, '2026-09-12 10:42:07.069', '2026-09-12 10:42:07.069', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5fea15e8-9a2c-403f-815d-6acd96446ea1', 'Physics', 'JAMB', null, 2026, null, 'A projectile is fired from the ground level with a velocity of 300ms⁻¹ at an angle 30° to the vertical. Calculate the time taken to reach the maximum height (g=10)', null, '["26s","15s","20s","23s"]', 1, 'Angle to the vertical = 30°, so angle to the horizontal = 60°. Time to max height = u sin θ / g = 300 sin 60° / 10 = 300 × 0.866 / 10 = 26s. Wait, if angle is to the vertical, then vertical component = u cos 30° = 300 × 0.866 = 260. Time = 260/10 = 26s. The answer is (A) 26s.', true, '2026-09-10 10:56:45.846', '2026-09-10 10:56:45.846', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5ff0e8ad-f94b-4e89-b65a-fdae257e80d8', 'Physics', 'JAMB', null, 1997, null, 'A load of 20 N on a wire of cross-sectional area 8 x 10⁻⁷ m² produces an extension of 10⁻⁴ m. Calculate Young''s modulus for the material of the wire if its length is 3 m.', null, '["7.0 x 10¹¹ N m⁻²","7.5 x 10¹¹ N m⁻²","8.5 x 10¹¹ N m⁻²","9.0 x 10¹¹ N m⁻²"]', 1, 'E = (F/A)/(e/L) = (20/8 x 10⁻⁷)/(10⁻⁴/3) = (2.5 x 10⁷)/(3.33 x 10⁻⁵) = 7.5 x 10¹¹ N m⁻².', true, '2026-10-12 19:15:43.09', '2026-10-12 19:15:43.09', null, null, null, 'A load of 20 N on a wire of cross-sectional area 8 x 10<sup>-7</sup> m<sup>2</sup> produces an extension of 10<sup>-4</sup> m. Calculate Young''s modulus for the material of the wire if its length is 3 m.', '["7.0 x 10<sup>11</sup> N m<sup>-2</sup>","7.5 x 10<sup>11</sup> N m<sup>-2</sup>","8.5 x 10<sup>11</sup> N m<sup>-2</sup>","9.0 x 10<sup>11</sup> N m<sup>-2</sup>"]', 'E = (F/A)/(e/L) = (20/8 x 10<sup>-7</sup>)/(10<sup>-4</sup>/3) = (2.5 x 10<sup>7</sup>)/(3.33 x 10<sup>-5</sup>) = 7.5 x 10<sup>11</sup> N m<sup>-2</sup>.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5ff2119d-9f8e-4083-9f8d-ab5bf6524527', 'Christian Religious Studies', 'JAMB', null, 2026, null, '''My spirit shall not abide in man forever, for he is flesh...'' When God made the statement above, He concluded that man''s days shall be', null, '["one hundred years","one hundred and fifty years","eighty years","one hundred and twenty years"]', 3, 'God said man''s days shall be 120 years (Genesis 6:3).', true, '2026-09-12 10:41:28.597', '2026-09-12 10:41:28.597', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('5ff4c09e-9571-4ad0-822d-46762419c4a7', 'Biology', 'JAMB', null, 2005, null, 'The recycling method of solid waste disposal is unsuitable for', null, '["organic matter","glass","plastics","metal scraps"]', 0, 'Recycling is unsuitable for organic matter.', true, '2026-10-12 20:59:38.041', '2026-10-12 20:59:38.041', null, null, null, 'The recycling method of solid waste disposal is unsuitable for', '["organic matter","glass","plastics","metal scraps"]', 'Recycling is unsuitable for organic matter.', '{"bold":["organic matter"],"italic":[],"underline":[],"fillBlanks":[]}');
