insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('600844a3-495e-45bd-a77d-05c59b9f42b6', 'Biology', 'JAMB', null, 2002, null, 'The structures found only in plant cell are', null, '["cell membranes and cytoplasm","chromatin and nucleolus","cell wall and chloroplast","cell membrane and lysosome"]', 2, 'Cell wall and chloroplast are found only in plant cells.', true, '2026-10-12 20:59:30.085', '2026-10-12 20:59:30.085', null, null, null, 'The structures found only in plant cell are', '["cell membranes and cytoplasm","chromatin and nucleolus","cell wall and chloroplast","cell membrane and lysosome"]', 'Cell wall and chloroplast are found only in plant cells.', '{"bold":["Cell wall and chloroplast"],"italic":[],"underline":[],"fillBlanks":[]}');
