insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('603f19b9-4df2-4574-8790-d58ae48f8dc7', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. As the triumphant rebels were returning to their base, they met with <u>a serious reverse</u>.', null, '["an enemy","an army","a victory","a defeat"]', 3, 'A reverse = a defeat.', true, '2026-10-24 01:04:03.434', '2026-10-24 01:04:03.434', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. As the triumphant rebels were returning to their base, they met with <u>a serious reverse</u>.', '["an enemy","an army","a victory","<u>a defeat</u>"]', 'A <b>reverse</b> = <b>a defeat</b>.', '{}');
