insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('612ad169-7d83-4fad-a81e-6a221b10a052', 'Biology', 'JAMB', null, 2013, null, 'The main structure in vertebrates that supports and protects the body is the', null, '["Muscle","Joint","Skeleton","Ligament"]', 2, 'The skeleton supports and protects the body.', true, '2026-10-12 20:59:47.485', '2026-10-12 20:59:47.485', null, null, null, 'The main structure in vertebrates that supports and protects the body is the', '["Muscle","Joint","Skeleton","Ligament"]', 'The skeleton supports and protects the body.', '{"bold":["skeleton"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6144e693-4ac3-4fb2-ba80-b547fe7da8ec', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. He likes to call attention to <u>unimportant</u> matters.', null, '["dubious","incidental","trivial","simple"]', 2, 'Unimportant = trivial.', true, '2026-10-24 01:01:41.945', '2026-10-24 01:01:41.945', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. He likes to call attention to <u>unimportant</u> matters.', '["dubious","incidental","<u>trivial</u>","simple"]', '<b>Unimportant</b> = <b>trivial</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6159309b-a7a3-41ae-b550-729cf49444c7', 'Physics', 'JAMB', null, 2000, null, 'The velocity ratio of a machine is 5 and its efficiency is 75%. What effort would be needed to lift a load of 150 N with the machine?', null, '["50 N","40 N","30 N","20 N"]', 1, 'MA = efficiency x VR = 0.75 x 5 = 3.75. Effort = load/MA = 150/3.75 = 40 N.', true, '2026-10-12 19:15:49.321', '2026-10-12 19:15:49.321', null, null, null, 'The velocity ratio of a machine is 5 and its efficiency is 75%. What effort would be needed to lift a load of 150 N with the machine?', '["50 N","40 N","30 N","20 N"]', 'MA = efficiency x VR = 0.75 x 5 = 3.75. Effort = load/MA = 150/3.75 = 40 N.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('616b5116-d145-4a83-a7b8-00264311d96b', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). The convict said he was tired of <u>leading a dog''s life</u>. To lead a dog''s life means to live ___________', null, '["carelessly","in disgrace","in solitude","in misery","in poverty"]', 3, '''A dog''s life'' means a miserable life.', true, '2026-10-24 01:02:00.614', '2026-10-24 01:02:00.614', null, null, null, '(Choose the most appropriate interpretation). The convict said he was tired of <u>leading a dog''s life</u>. To lead a dog''s life means to live ___________', '["carelessly","in disgrace","in solitude","<u>in misery</u>","in poverty"]', '''A <b>dog''s life</b>'' means a <b>miserable life</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('61710137-684b-42fb-bbf8-5a10127cae5a', 'Biology', 'JAMB', null, 2002, null, 'A person that is obese must avoid meals containing', null, '["carrots and oranges","margarine and butter","beef and beans","rice and yam"]', 1, 'Margarine and butter are high in fat and should be avoided by obese persons.', true, '2026-10-12 20:59:31.576', '2026-10-12 20:59:31.576', null, null, null, 'A person that is obese must avoid meals containing', '["carrots and oranges","margarine and butter","beef and beans","rice and yam"]', 'Margarine and butter are high in fat and should be avoided by obese persons.', '{"bold":["Margarine and butter"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6180eb29-6fda-4635-8793-c7d2379e6e84', 'Physics', 'JAMB', null, 1983, null, 'Which of the following is NOT correct?
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6187ce37-e6f0-48b6-b453-6c66c020087f', 'Physics', 'JAMB', null, 1999, null, 'The core of an efficient transformer should consist of laminated pieces of metal in order to', null, '["Increase the heat produced by increasing the eddy current","Increase the heat produced by reducing the eddy current","Reduce the heat produced by increasing the eddy current","Reduce the heat produced by reducing the eddy current."]', 3, 'Lamination breaks up the paths of the eddy currents, which reduces them and so reduces the heat they produce.', true, '2026-10-12 19:15:48.199', '2026-10-12 19:15:48.199', null, null, null, 'The core of an efficient transformer should consist of laminated pieces of metal in order to', '["Increase the heat produced by increasing the eddy current","Increase the heat produced by reducing the eddy current","Reduce the heat produced by increasing the eddy current","Reduce the heat produced by reducing the eddy current."]', 'Lamination breaks up the paths of the eddy currents, which reduces them and so reduces the heat they produce.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('618908bf-387b-46c5-b8ed-b57c0adc2396', 'Biology', 'JAMB', null, 2026, null, 'The process by which animals with exoskeleton shed their old skin periodically to a new one is known as', null, '["Repairing","Ecdysis","Growth","Ossification"]', 1, 'Ecdysis (molting) is the process by which arthropods and other animals with exoskeletons shed their old cuticle and form a new, larger one. This allows for growth since the exoskeleton is rigid and does not expand. During ecdysis, the animal produces new exoskeleton material under the old one, then breaks and sheds the old covering. Ossification is the process of bone formation in vertebrates. Growth refers to the general increase in size, while ecdysis is the specific mechanism for growth in exoskeleton-bearing animals.', true, '2026-09-09 03:18:32.953', '2026-09-09 03:18:32.953', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6192f475-6331-4aad-bbcb-e507a28a30bf', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). The judge <u>came down heavily</u> on the accused person in his judgment.', null, '["crashed heavily","fell down heading","descended upon heavily","imposed a stiff penalty","crash landed on"]', 3, '''Came down heavily on'' = imposed severe penalty.', true, '2026-10-24 01:02:02.586', '2026-10-24 01:02:02.586', null, null, null, '(Choose the most appropriate interpretation). The judge <u>came down heavily</u> on the accused person in his judgment.', '["crashed heavily","fell down heading","descended upon heavily","<u>imposed a stiff penalty</u>","crash landed on"]', '''<b>Came down heavily on</b>'' = <b>imposed severe penalty</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6194f95d-e87d-4ac7-94ad-c6d747d73bfb', 'Biology', 'JAMB', null, 2026, null, 'The excretory structure in the earthworm is the', null, '["malphigian tubule","flame cell","nephridium","kidney"]', 2, 'The excretory structure in the earthworm is the nephridium. Nephridia are segmentally arranged tubular organs in annelids that function in excretion and osmoregulation. Malpighian tubules are excretory organs in insects. Flame cells (protonephridia) are found in flatworms. Kidneys are excretory organs in vertebrates. Earthworms have nephridia in each body segment, which filter waste from the coelomic fluid and blood, excreting dilute urine.', true, '2026-09-09 03:19:09.01', '2026-09-09 03:19:09.01', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('61a53948-6df1-4d80-af81-8bdfa9bae55d', 'Literature in English', 'JAMB', null, 2026, null, 'In the poem, cupid is', null, '["An illusion","A metonymy","The persona''s mistress","The person''s rival"]', 1, 'Cupid is a metonymy.', true, '2026-09-12 11:14:05.979', '2026-09-12 11:14:05.979', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('61b2f519-81b9-41a7-b1a4-98b4fe2e2fad', 'Economics', 'JAMB', null, 2026, null, 'Which of the following equations is the correct one about Net National Product (NNP)?', null, '["NNP = GNP - Depreciation","NNP = GNP + Net income from abroad","NNP = GDP - net income from abroad","NNP = GDP - Depreciation"]', 0, 'The correct equation is NNP = GNP - Depreciation. Net National Product (NNP) is Gross National Product (GNP) minus depreciation (capital consumption allowance). Depreciation is the value of capital goods worn out or used up during the year. NNP measures the net output of a country''s economy after accounting for the replacement of worn-out capital. It represents the true net income of the nation.', true, '2026-09-10 10:42:55.507', '2026-09-10 10:42:55.507', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('61b7861a-ddf1-4435-84a5-47d183053edc', 'Economics', 'JAMB', null, 2026, null, 'The number of shareholders in a private limited liability company ranges from', null, '["two to twenty","two to fifty","two to seven","two to three"]', 1, 'The number of shareholders in a private limited liability company ranges from two to fifty. In Nigeria, a private limited liability company (Ltd) must have at least 2 and at most 50 shareholders. It cannot offer its shares to the public. A public limited liability company (PLC) must have at least 2 shareholders but no maximum limit. The range of 2 to 50 is a regulatory requirement to maintain the private nature of the company.', true, '2026-09-10 10:42:00.77', '2026-09-10 10:42:00.77', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('61bcb909-7278-4d15-8e7a-25d9ea20af06', 'Economics', 'JAMB', null, 2026, null, 'In a closed economy, the marginal propensity to consume is 0.6 and the average propensity to consume is 0.8. The value of the multiplier is', null, '["2.5","2.6","2.7","2.4"]', 0, 'The value of the multiplier is 2.5. The multiplier (k) = 1 / (1 - MPC) = 1 / MPS. Given MPC = 0.6, MPS = 1 - 0.6 = 0.4. So, k = 1 / 0.4 = 2.5. The average propensity to consume (APC = 0.8) is not needed to calculate the multiplier. The multiplier shows how much national income changes in response to a change in autonomous spending.', true, '2026-09-10 10:41:58.832', '2026-09-10 10:41:58.832', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('61bf3aa3-28fb-42dd-aab7-6d6500566b5c', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'To the question of the Philippian jailer, ''Men what must I do to be saved?'' Paul replied', null, '["confess your sins and give alms","believe in the Lord Jesus","release us to wash our wounds","trust in God and pray always"]', 1, 'Paul replied to the Philippian jailer, ''Believe in the Lord Jesus, and you will be saved, you and your household.'' This emphasized salvation by faith in Christ.', true, '2026-09-12 09:45:54.912', '2026-09-12 09:45:54.912', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('61c9a8b4-84ad-4ac7-b578-ec37eb0ff014', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The delegates to the Constitutional Conference have <u>mooted</u> that funding of universities be transferred to states where they are located.', null, '["said","agreed","proposed","legislated"]', 2, 'Mooted = proposed.', true, '2026-10-24 01:04:00.067', '2026-10-24 01:04:00.067', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The delegates to the Constitutional Conference have <u>mooted</u> that funding of universities be transferred to states where they are located.', '["said","agreed","<u>proposed</u>","legislated"]', '<b>Mooted</b> = <b>proposed</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('61cdc5d9-37ba-4e38-8723-7dcc93d3c44a', 'Biology', 'JAMB', null, 2013, null, 'The structural adaptation of desert plants for water conservation is', null, '["Spiny leaves","Prominent stomata in leaves","Broad leaves with numerous stomata","Spongy mesophyll"]', 0, 'Spiny leaves are a structural adaptation for water conservation.', true, '2026-10-12 20:59:46.672', '2026-10-12 20:59:46.672', null, null, null, 'The structural adaptation of desert plants for water conservation is', '["Spiny leaves","Prominent stomata in leaves","Broad leaves with numerous stomata","Spongy mesophyll"]', 'Spiny leaves are a structural adaptation for water conservation.', '{"bold":["Spiny leaves"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('61ceec31-c026-4832-9092-ac100718dfe7', 'Biology', 'JAMB', null, 2026, null, 'Women do not suffer from colour blindness', null, '["because the trait is sex linked","only men are colour blind","the genes are recessive and sex linked","the genes occur on both the X and Y chromosomes"]', 0, 'Women do not suffer from colour blindness because the trait is sex linked (X-linked recessive). Women have two X chromosomes, so they must inherit two copies of the recessive allele (one from each parent) to be affected. A woman with one affected X chromosome and one normal X chromosome is a carrier. Men have only one X chromosome, so if they inherit the affected chromosome, they will have the condition. This explains why colour blindness is more common in men than women.', true, '2026-09-09 03:19:18.363', '2026-09-09 03:19:18.363', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('61d4144d-2327-429d-bdd9-0a19b0821c05', 'Biology', 'JAMB', null, 2003, null, 'The presence of sunken stomata and the folding of leaves are adaptations to', null, '["prevent entry of pathogens","reduce water loss","remove excess water","prevent guttation"]', 1, 'Sunken stomata and folded leaves reduce water loss.', true, '2026-10-12 20:59:34.05', '2026-10-12 20:59:34.05', null, null, null, 'The presence of sunken stomata and the folding of leaves are adaptations to', '["prevent entry of pathogens","reduce water loss","remove excess water","prevent guttation"]', 'Sunken stomata and folded leaves reduce water loss.', '{"bold":["reduce water loss"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('61d44ff7-78e3-4f8c-849f-933ffaed5c94', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The doctor was very <u>gentle</u> with his patients in the examining room.', null, '["harsh","rude","tough","unkind"]', 0, 'Gentle = mild; opposite = harsh.', true, '2026-10-24 07:21:14.174', '2026-10-24 07:21:14.174', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The doctor was very <u>gentle</u> with his patients in the examining room.', '["harsh","rude","tough","unkind"]', 'Gentle = mild; opposite = harsh.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('61d8724a-89f0-4bb1-b843-ede80f4b956c', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). Jide is <u>being forced to</u> go to Lagos tomorrow. This means that Jide ____________', null, '["will go to Lagos","must go to Lagos","wishes to go to Lagos","is going to Lagos","goes to Lagos"]', 1, '''Being forced to'' expresses obligation â†’ must.', true, '2026-10-24 01:02:00.72', '2026-10-24 01:02:00.72', null, null, null, '(Choose the most appropriate interpretation). Jide is <u>being forced to</u> go to Lagos tomorrow. This means that Jide ____________', '["will go to Lagos","<u>must go to Lagos</u>","wishes to go to Lagos","is going to Lagos","goes to Lagos"]', '''<b>Being forced to</b>'' expresses obligation â†’ <b>must</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('61e7d88a-c1f8-4046-94ef-1bc9467b90a7', 'English Language', 'JAMB', null, 2007, null, 'I wanted to know his political beliefs, so I asked him what <u>------------</u>', null, '["this was","these are","this is","these were"]', 3, 'Plural beliefs + past â†’ these were.', true, '2026-10-24 01:02:15.764', '2026-10-24 01:02:15.764', null, null, null, 'I wanted to know his political beliefs, so I asked him what <u>------------</u>', '["this was","these are","this is","<u>these were</u>"]', 'Plural <b>beliefs</b> + past â†’ <b>these were</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('61e81690-67b5-477a-b1e7-76f38a423853', 'Physics', 'JAMB', null, 2002, null, 'The carbon-granule microphone works on the principle of change in', null, '["Capacitance","Voltage","Inductance","Resistance"]', 3, 'Sound waves compress the carbon granules by different amounts, changing the electrical resistance and hence the current.', true, '2026-10-12 19:15:54.833', '2026-10-12 19:15:54.833', null, null, null, 'The carbon-granule microphone works on the principle of change in', '["Capacitance","Voltage","Inductance","Resistance"]', 'Sound waves compress the carbon granules by different amounts, changing the electrical resistance and hence the current.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('620c15fc-318d-4499-8fa9-45ee74988c37', 'Hausa', 'JAMB', null, 2010, null, '''Ba neman aure ke da wuya ba, shiga-ka-fito''. Ka ga shiga-ka-fito din nan, lallai shiga-ka-fito din ne! Domin aljihu kan jigata kafin a kai ga biki. Tuddan da al''ada ta tanada, wadanda dole sai an haye su, suna da yawa. Yanzu dauki misalin kayan na-gani-ina-so, wato ''yan kayan nan da ake shiryawa a kai gidan su yarinya a karon farko. Ma''anar yin haka, wai iyaye su san cewa manemin auren ''yarsu da gaske yake. To, ina dole ga yin haka? Da can da yake zuwa yana zance da ''yarsu yana yi mata hasafi, ba a san da gaske yake ba? Gangaro kan kayan toshi. Nan ma tsabagen kudi ake kashewa a sayi suturu da kayan shafe-shafe a kai wa yarinya. Kada fa ka ce zuwa zance da manemi yake yana yi wa yarinya kyauta mako-mako, shi ke nan, ya wadatar. Ina, ko kadan! Kada ka mance da kudin gaisuwar iyaye da dukiyar aure kafin a yi baiko da sa ranar biki. Kudi ne madididiki ake tanada a kai wa iyayen yarinya da niyyar dai wannan abu da aka ambata. Duk bayan wannan, ana sa ranar aure, manemin yarinya ya dosa karakaina ke nan daga wannan gida zuwa wancan, ko ma wannan gari zuwa wancan da sunan gayar da iyaye da kakaninnta, wai don su san shi. I, za su san shi mana, tun da ba yana zuwa ne zikau ba! Da zarar biki ya kawo jiki kuma, uwa-uba za a shirya kayan lefe na fitar hankali a kai wa yarinya. Nan ma dukiya ake narkawa. Haķika duk wadannan abubuwa al''ada ce kawai ta kaķaba wa al''umma. Ai ta fuskar dukiya, muhimmin abu ga aure, sadaki. Amma abin takaici, yanzu an yi masa mahalli a can ķarshen sahu! Manufar na-gani-ina-so, ita ce bayyana', null, '["niyya","samun duniya","asali","wurin zama."]', 0, 'Manufar na-gani-ina-so ita ce bayyana niyya.', true, '2026-10-13 10:37:23.502', '2026-10-13 10:37:23.502', null, null, null, '''Ba neman aure ke da wuya ba, shiga-ka-fito''. Ka ga shiga-ka-fito din nan, lallai shiga-ka-fito din ne! Domin aljihu kan jigata kafin a kai ga biki. Tuddan da al''ada ta tanada, wadanda dole sai an haye su, suna da yawa. Yanzu dauki misalin kayan na-gani-ina-so, wato ''yan kayan nan da ake shiryawa a kai gidan su yarinya a karon farko. Ma''anar yin haka, wai iyaye su san cewa manemin auren ''yarsu da gaske yake. To, ina dole ga yin haka? Da can da yake zuwa yana zance da ''yarsu yana yi mata hasafi, ba a san da gaske yake ba? Gangaro kan kayan toshi. Nan ma tsabagen kudi ake kashewa a sayi suturu da kayan shafe-shafe a kai wa yarinya. Kada fa ka ce zuwa zance da manemi yake yana yi wa yarinya kyauta mako-mako, shi ke nan, ya wadatar. Ina, ko kadan! Kada ka mance da kudin gaisuwar iyaye da dukiyar aure kafin a yi baiko da sa ranar biki. Kudi ne madididiki ake tanada a kai wa iyayen yarinya da niyyar dai wannan abu da aka ambata. Duk bayan wannan, ana sa ranar aure, manemin yarinya ya dosa karakaina ke nan daga wannan gida zuwa wancan, ko ma wannan gari zuwa wancan da sunan gayar da iyaye da kakaninnta, wai don su san shi. I, za su san shi mana, tun da ba yana zuwa ne zikau ba! Da zarar biki ya kawo jiki kuma, uwa-uba za a shirya kayan lefe na fitar hankali a kai wa yarinya. Nan ma dukiya ake narkawa. Haķika duk wadannan abubuwa al''ada ce kawai ta kaķaba wa al''umma. Ai ta fuskar dukiya, muhimmin abu ga aure, sadaki. Amma abin takaici, yanzu an yi masa mahalli a can ķarshen sahu! Manufar na-gani-ina-so, ita ce bayyana', '["niyya","samun duniya","asali","wurin zama."]', 'Manufar na-gani-ina-so ita ce bayyana niyya.', '{"bold":["niyya"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('620d7718-d4b1-4d8f-a16e-bec1a6bd3259', 'Physics', 'JAMB', null, 1984, null, 'A particle moves in a circular orbit of radius 0.02 m. If the speed of the particle is 0.88 m s⁻¹, calculate its frequency in cycles per second.', null, '["2.0","7.0","8.8","14.0","17.6"]', 1, 'v = 2πrf, so f = v/(2πr) = 0.88/(2 x 22/7 x 0.02) = 7.0 Hz.', true, '2026-10-12 19:15:19.505', '2026-10-12 19:15:19.505', null, null, null, 'A particle moves in a circular orbit of radius 0.02 m. If the speed of the particle is 0.88 m s<sup>-1</sup>, calculate its frequency in cycles per second.', '["2.0","7.0","8.8","14.0","17.6"]', 'v = 2πrf, so f = v/(2πr) = 0.88/(2 x 22/7 x 0.02) = 7.0 Hz.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('621a5420-69f9-4033-a506-cecb8b9e1deb', 'Yoruba', 'JAMB', null, 2002, null, 'Òrìyà tí àwòn Yorùbá gbàgbò pé ó jé àpẹẹrẹ àwòn baba-þlá tó tí kú ni', null, '["l̩gunnu","Òrìyà-þlá","Eégún","Ayélála."]', 2, 'Eégún ni àwòn Yorùbá gbàgbò pé ó jé àpẹẹrẹ àwòn baba-þlá tó tí kú.', true, '2026-10-13 13:22:40.549', '2026-10-13 13:22:40.549', null, null, null, 'Òrìyà tí àwòn Yorùbá gbàgbò pé ó jé àpẹẹrẹ àwòn baba-þlá tó tí kú ni', '["l̩gunnu","Òrìyà-þlá","Eégún","Ayélála."]', 'Eégún ni àwòn Yorùbá gbàgbò pé ó jé àpẹẹrẹ àwòn baba-þlá tó tí kú.', '{"bold":["Eégún"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6226f891-04a6-49a9-b887-cf31ebe79c90', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'According to Galatians, one of the benefits of being a joint heir with Christ is having his Spirit in', null, '["worship","the heart","the body","prayers"]', 1, 'According to Galatians 4:6, because believers are sons, God has sent the Spirit of His Son into their hearts, crying, ''Abba! Father!'' So the Spirit is in the heart.', true, '2026-09-12 09:46:02.16', '2026-09-12 09:46:02.16', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('62279d7f-63af-4ff5-a3b8-8a59dc4c553c', 'General Mathematics', 'JAMB', null, 2026, null, 'If y = 3cos4x, dy/dx equals', null, '["6sin8x","-24sin4x","12sin4x","-12sin4x"]', 3, 'dy/dx = -12sin4x.', true, '2026-09-12 11:44:01.587', '2026-09-12 11:44:01.587', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6239d694-132e-435a-b3b9-ad2a8c78f551', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). Solo has resigned his job with the Textile Mills. He has no worry to worry about getting another job. His plans are still quite <u>in the air</u>. This means that his plans are _________________', null, '["airmailed","air tight","uncertain","certain","airborne"]', 2, '''In the air'' means unsettled/uncertain.', true, '2026-10-24 01:02:00.404', '2026-10-24 01:02:00.404', null, null, null, '(Choose the most appropriate interpretation). Solo has resigned his job with the Textile Mills. He has no worry to worry about getting another job. His plans are still quite <u>in the air</u>. This means that his plans are _________________', '["airmailed","air tight","<u>uncertain</u>","certain","airborne"]', '''<b>In the air</b>'' means unsettled/<b>uncertain</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('62413442-9280-4c2c-9ede-9ba27b73b02c', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Which of the following was not a river flowing from the garden of Eden?', null, '["Gihon","Tigris","Euphrates","Kishon"]', 3, 'Kishon was not a river flowing from the garden of Eden. The four rivers mentioned in Genesis 2 are Pishon, Gihon, Tigris (Hiddekel), and Euphrates. The Kishon is a river in Israel, not in Eden.', true, '2026-09-12 09:45:56.986', '2026-09-12 09:45:56.986', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6246e2ef-d857-4e58-96ab-529209d75239', 'Chemistry', 'JAMB', null, 2026, null, 'Which of the following best explains why ionic compounds generally have high melting points?', null, '["Presence of strong intermolecular forces","Strong electrostatic attraction between oppositely charged ions","Large molecular masses","Covalent bond formation"]', 1, 'Ionic crystals require high thermal energy to overcome strong multidirectional electrostatic attractions within the giant ionic lattice.', true, '2026-09-09 17:12:48.763', '2026-09-09 17:12:48.763', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6261ed5c-f9a8-4b98-a18c-280bc4d37f6e', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'According to Ephesians, children who obey their parents in the Lord will', null, '["be happy","go to heaven","have long life","be great"]', 2, 'Ephesians 6:2-3 promises long life to those who honor their parents.', true, '2026-09-12 10:41:21.122', '2026-09-12 10:41:21.122', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6268942a-4fe5-44d3-afbd-81577b9a73d9', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The lazy man cast a <u>lustful</u> glance at his neighbour''s wife', null, '["hateful","quick","covetous","envious"]', 2, 'Lustful = covetous.', true, '2026-10-24 01:01:59.93', '2026-10-24 01:01:59.93', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The lazy man cast a <u>lustful</u> glance at his neighbour''s wife', '["hateful","quick","<u>covetous</u>","envious"]', '<b>Lustful</b> = <b>covetous</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('626caa78-80e1-4a1e-a8d1-ef764b2660fc', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'The call of Matthew, the tax collector to be one of Jesus’ apostles implied that...', null, '["Tax collectors were sinless","Christ came to call sinners","Matthew was willing to repent","All tax collectors had repented"]', 1, 'In Matthew 9:12-13, when criticized for eating with tax collectors and sinners, Jesus responded that He came not to call the righteous, but sinners to repentance.', true, '2026-09-09 17:18:24.327', '2026-09-09 17:18:24.327', null, null, null, null, null, null, null);
