insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('62b18a62-52b0-4850-9256-875ba6ee4ac6', 'Economics', 'JAMB', null, 2026, null, 'External economies arise essentially from?', null, '["Localization of industry","Firm''s individual policy","Government economic policy","Transferability of shares"]', 0, 'External economies arise from the localization of industry, where firms benefit from being in the same area.', true, '2026-09-12 10:58:16.813', '2026-09-12 10:58:16.813', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('62b67bdb-2954-4237-b1db-eefdd99bcc10', 'Chemistry', 'JAMB', null, 2026, null, 'Which of the following represents an aromatic compound?', null, '["Cyclohexane","Propanol","Benzene","Cyclohexanol"]', 2, 'Benzene is an aromatic compound.', true, '2026-09-12 11:36:19.975', '2026-09-12 11:36:19.975', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('62d223a4-1c76-4a11-9966-37ca0d4f77c8', 'Physics', 'JAMB', null, 1990, null, 'A lamp is rated 240 V, 60 W. The resistance of the filament is', null, '["960 Ω","16 Ω","15 Ω","4 Ω"]', 0, 'R = V²/P = 240²/60 = 960 Ω.', true, '2026-10-12 19:15:32.055', '2026-10-12 19:15:32.055', null, null, null, 'A lamp is rated 240 V, 60 W. The resistance of the filament is', '["960 Ω","16 Ω","15 Ω","4 Ω"]', 'R = V<sup>2</sup>/P = 240<sup>2</sup>/60 = 960 Ω.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('62d5f5d3-cf97-4712-9d01-d83e78e09e11', 'English Language', 'JAMB', null, 2007, null, 'The number of unemployed graduates in the country <u>_______</u> alarming.', null, '["are","were","is","have been"]', 2, '''The number of'' singular â†’ is.', true, '2026-10-24 01:02:16.639', '2026-10-24 01:02:16.639', null, null, null, 'The number of unemployed graduates in the country <u>_______</u> alarming.', '["are","were","<u>is</u>","have been"]', '''<b>The number of</b>'' singular â†’ <b>is</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('62d696b2-d01f-4527-97b0-3532d2a6efa5', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. They often quarreled before leaving the house but <u>made it up</u> by the time they returned home.', null, '["added it up","reconciled","fell out","compounded the problem"]', 2, 'Made it up = reconciled; opposite = fell out.', true, '2026-10-24 07:21:14.938', '2026-10-24 07:21:14.938', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. They often quarreled before leaving the house but <u>made it up</u> by the time they returned home.', '["added it up","reconciled","fell out","compounded the problem"]', 'Made it up = reconciled; opposite = fell out.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('62e06938-ba25-46b2-b282-40700686108f', 'Physics', 'JAMB', null, 1984, null, 'Cathode rays are', null, '["High-energy electromagnetic waves","Protons","Streams of electrons","Neutrons","Radio waves"]', 2, 'Cathode rays are streams of fast-moving electrons emitted from the cathode of a discharge tube.', true, '2026-10-12 19:15:20.111', '2026-10-12 19:15:20.111', null, null, null, 'Cathode rays are', '["High-energy electromagnetic waves","Protons","Streams of electrons","Neutrons","Radio waves"]', 'Cathode rays are streams of fast-moving electrons emitted from the cathode of a discharge tube.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('62e40244-1cd3-4a02-a571-1e37f411224e', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. He picked up the phone expecting to hear the chairman''s <u>gruff</u> voice.', null, '["gracious","musical","husky","polite"]', 2, 'Gruff = husky.', true, '2026-10-24 01:01:58.715', '2026-10-24 01:01:58.715', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. He picked up the phone expecting to hear the chairman''s <u>gruff</u> voice.', '["gracious","musical","<u>husky</u>","polite"]', '<b>Gruff</b> = <b>husky</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('62f74353-9870-4bdf-a77c-87fc9f96750e', 'Physics', 'JAMB', null, 2026, null, 'The neutron, Nucleus and Electron were respectively discovered by?', null, '["Chadwick, Einstein, Newton","Rutherford, Chadwick, Thompson","Bohr, Rutherford, Thompson","Chadwick, Rutherford, Thompson"]', 3, 'The neutron was discovered by James Chadwick, the nucleus by Ernest Rutherford, and the electron by J.J. Thomson.', true, '2026-09-10 10:56:49.904', '2026-09-10 10:56:49.904', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('630113cf-e87d-4ea6-9cc6-c52d5737e435', 'Biology', 'JAMB', null, 2002, null, 'When a marine fish was taken from the ocean and put in a tank of fresh water, it died after a short period because', null, '["the tank was too small compared to the large ocean","the body cells of the fish swelled and burst as a result of the hypotonic fresh water","the body cells of the fish shrank as their sap was hypertonic to the fresh water","there was no food in the tank, so the fish starved"]', 1, 'Marine fish cells swell and burst in hypotonic fresh water.', true, '2026-10-12 20:59:31.319', '2026-10-12 20:59:31.319', null, null, null, 'When a marine fish was taken from the ocean and put in a tank of fresh water, it died after a short period because', '["the tank was too small compared to the large ocean","the body cells of the fish swelled and burst as a result of the hypotonic fresh water","the body cells of the fish shrank as their sap was hypertonic to the fresh water","there was no food in the tank, so the fish starved"]', 'Marine fish cells swell and burst in hypotonic fresh water.', '{"bold":["swell and burst"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('630c2802-90f2-43be-ab68-92e04a35c854', 'Chemistry', 'JAMB', null, 2026, null, 'Calculate the mass of silver deposited when a current of 2.6A is passed through a solution of a silver salt for 70mins (Ag=108, 1 Faraday=96500C)', null, '["10g","11g","12g","14g"]', 3, 'Q = It = 2.6 × 70 × 60 = 10920C. Moles of Ag = 10920/96500 = 0.113 mol. Mass = 0.113 × 108 = 12.2g ≈ 12g. The answer is (III) 12g.', true, '2026-09-12 11:36:08.817', '2026-09-12 11:36:08.817', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6313eaad-c832-4722-8d87-6dd25278f7ff', 'General Mathematics', 'JAMB', null, 2026, null, 'The gradient of the line joining (x,4) and (1,2) is 1/2, find the value of x', null, '["-3","-5","5","3"]', 1, '(4-2)/(x-1) = 1/2. 2/(x-1) = 1/2. x-1 = 4. x = 5. The answer is (C) 5.', true, '2026-09-12 11:44:02.268', '2026-09-12 11:44:02.268', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6327fd7e-8440-4d3c-a67e-bcce5c89e768', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Gideon was able to defeat the Midianites, with a reduced number of soldiers because he', null, '["was a good fighter","was a prudent warrior","had better weapons","had faith in God"]', 3, 'Gideon had faith in God, who reduced his army to 300 so Israel would know God gave the victory.', true, '2026-09-12 10:41:14.253', '2026-09-12 10:41:14.253', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('63295f7a-ced4-420a-8c74-d1d20b4047ae', 'Economics', 'JAMB', null, 2026, null, 'One main quality of a good is that it', null, '["is always tangible","satisfies wants","is made in factory","is nonperishable"]', 1, 'One main quality of a good is that it satisfies wants. A good is anything that satisfies human wants and provides utility. Goods can be tangible (physical objects) or intangible (services). They are not necessarily made in factories or nonperishable. The defining characteristic of a good is its ability to satisfy human wants, which gives it value and makes it desirable.', true, '2026-09-10 10:41:59.538', '2026-09-10 10:41:59.538', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('63303a07-d372-49e0-9b21-30623710a0ca', 'Chemistry', 'JAMB', null, 2026, null, 'Which quantum number divide orbital into sub orbital', null, '["spin","magnetic","Azimuthal","Principal"]', 2, 'The Azimuthal (or orbital angular momentum) quantum number (l) specifies the shape and subshell/sub-orbital energy level structure of an atom.', true, '2026-09-09 17:12:45.436', '2026-09-09 17:12:45.436', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('63344e4a-39d7-4ab4-bb0f-f30dc9a7f8b0', 'Chemistry', 'JAMB', null, 2026, null, 'A mixture of iron and sulphur can best be separated by dissolving the mixture in', null, '["Steam","Dilute hydrochloric acid","Dilute sodium hydroxide","Benzene"]', 1, 'Iron dissolves in dilute HCl while sulphur does not.', true, '2026-09-12 11:36:21.076', '2026-09-12 11:36:21.076', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('635506fb-6449-4c1b-82c1-b3c629a11888', 'Literature in English', 'JAMB', null, 2026, null, 'The night in the poem is portrayed as', null, '["source of sorrow","a powerful and mystical presence","a time of complete silence","a moment of danger"]', 1, 'The night in the poem ''Night'' is portrayed as a powerful and mystical presence. It is personified as a force with a heavy hand, evoking a sense of mystery and awe. The night is not just a time of darkness but a presence with agency and influence. It is not portrayed primarily as a source of sorrow, complete silence, or danger. The poem emphasizes the night''s mystical and powerful nature.', true, '2026-09-10 10:45:35.58', '2026-09-10 10:45:35.58', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('63618f6d-89bf-4dc3-8ce1-36874fbc7f17', 'Literature in English', 'JAMB', null, 2026, null, 'In The Digging, the line ''Between my finger and my thumb / The squat pen rests; snug as a gun'' suggests that the pen', null, '["Is a weapon of violence","Symbolises the poet''s tool of labour","Represents political struggle","Is inferior to manual labour"]', 1, 'The pen symbolizes the poet''s tool of labour.', true, '2026-09-12 11:09:53.791', '2026-09-12 11:09:53.791', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('638f2a5c-e951-4c4e-9c3d-43a04909e1e2', 'Literature in English', 'JAMB', null, 2026, null, 'Oral literature is part of', null, '["drama","folklore","poetry","music"]', 1, 'Oral literature is part of folklore.', true, '2026-09-12 11:13:59.225', '2026-09-12 11:13:59.225', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('639f03a9-7788-4b4a-a873-97b26e297e1c', 'Chemistry', 'JAMB', null, 2026, null, 'The bond breaking energies in an endothermic reaction is usually', null, '["equal to the bond forming energies","more than bond forming energies","less than the bonding forming energies","double the bond forming energies"]', 1, 'In endothermic reactions, bond breaking energy is more than bond forming energy.', true, '2026-09-12 11:36:03.143', '2026-09-12 11:36:03.143', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('63a6dda7-e010-466f-bea7-985c583307d5', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The party supporters <u>vilified</u> the Chairman for the role he played in the crisis that rocked the party.', null, '["elected","challenged","condemned","impeached"]', 2, 'Vilified = condemned.', true, '2026-10-24 01:04:04.401', '2026-10-24 01:04:04.401', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The party supporters <u>vilified</u> the Chairman for the role he played in the crisis that rocked the party.', '["elected","challenged","<u>condemned</u>","impeached"]', '<b>Vilified</b> = <b>condemned</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('63b94668-d80e-40b5-951a-e6d58e2f0acd', 'Economics', 'JAMB', null, 2026, null, 'Which of the following is regarded as fixed cost?', null, '["cost of raw materials","labour wages","rent on land","cost of light"]', 2, 'Rent on land is regarded as a fixed cost. Fixed costs are expenses that do not change with the level of output in the short run. Rent on land must be paid regardless of whether the firm produces anything. Cost of raw materials, labour wages, and cost of light (utilities) are variable costs because they change with the level of production. Fixed costs include rent, insurance, depreciation, and salaries of permanent staff.', true, '2026-09-10 10:42:55.828', '2026-09-10 10:42:55.828', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('63c5277b-9904-4f62-ac09-84697bac1d38', 'Biology', 'JAMB', null, 2010, null, 'Which of the following is lacking in the diet of a person with kwashiorkor?', null, '["Vitamins.","Proteins.","Carbohydrates.","Minerals."]', 1, 'Proteins are lacking in the diet of a person with kwashiorkor.', true, '2026-10-12 20:59:39.321', '2026-10-12 20:59:39.321', null, null, null, 'Which of the following is lacking in the diet of a person with kwashiorkor?', '["Vitamins.","Proteins.","Carbohydrates.","Minerals."]', 'Proteins are lacking in the diet of a person with kwashiorkor.', '{"bold":["Proteins"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('63d5288a-265c-4b28-9b2f-bc3c31165e36', 'English Language', 'JAMB', null, 2007, null, 'Sa''adatu as well as the maids <u>--------------</u>', null, '["like plantain chips","are liking plantain chips","is liking plantain chips","likes plantain chips"]', 3, '''As well as'' â†’ subject Sa''adatu (singular) â†’ likes.', true, '2026-10-24 01:04:27.375', '2026-10-24 01:04:27.375', null, null, null, 'Sa''adatu as well as the maids <u>--------------</u>', '["like plantain chips","are liking plantain chips","is liking plantain chips","<u>likes plantain chips</u>"]', '''<b>As well as</b>'' â†’ subject <b>Sa''adatu</b> (singular) â†’ <b>likes</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('63e06807-e8a2-41e7-85e1-b0c469548205', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The <u>potency</u> of the drug has been acknowledged.', null, '["action","inefficacy","power","loss"]', 1, 'Potency = strength; opposite = inefficacy.', true, '2026-10-24 07:21:25.18', '2026-10-24 07:21:25.18', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The <u>potency</u> of the drug has been acknowledged.', '["action","inefficacy","power","loss"]', 'Potency = strength; opposite = inefficacy.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('63e92b96-781f-4780-9cec-393d43315060', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Alade is noted for his <u>erratic</u> behaviour', null, '["fitful","bizarre","consistent","euphoric"]', 2, 'Erratic = unpredictable; opposite = consistent.', true, '2026-10-24 07:21:31.425', '2026-10-24 07:21:31.425', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Alade is noted for his <u>erratic</u> behaviour', '["fitful","bizarre","consistent","euphoric"]', 'Erratic = unpredictable; opposite = consistent.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('63f1fef7-12ee-4183-8a0b-42e2586a0aca', 'Physics', 'JAMB', null, 2026, null, 'What happens to the electrical resistance of a pure (intrinsic) semiconductor as its temperature is increased?', null, '["The resistance increases","The resistance stays the same","The resistance decreases","The resistance fluctuates randomly"]', 2, 'The resistance of a pure semiconductor decreases as temperature increases. Heating generates more electron-hole pairs, increasing the number of charge carriers and thus conductivity, which means resistance decreases.', true, '2026-09-10 10:56:49.558', '2026-09-10 10:56:49.558', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6409e684-6997-4cc8-948c-b7467eb6ee94', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Paul''s argument in Romans 5 contrasts Adam and Christ to illustrate', null, '["continuity of the Law","universality of sin and grace","superiority of Gentiles","limitation of justification"]', 1, 'Paul''s argument in Romans 5 contrasts Adam and Christ to illustrate the universality of sin and grace. Just as sin and death came to all through Adam''s disobedience, so grace and righteousness come to all through Christ''s obedience.', true, '2026-09-12 09:45:53.974', '2026-09-12 09:45:53.974', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('640d42ee-7fae-4cfa-b070-2b8f87893bd2', 'Physics', 'JAMB', null, 1997, null, 'The electromagnetic waves that are sensitive to temperature changes are', null, '["X-rays","Gamma-rays","Ultra-violet rays","Infra-red rays."]', 3, 'Infra-red radiation is heat radiation, and it is detected by its heating effect.', true, '2026-10-12 19:15:44.066', '2026-10-12 19:15:44.066', null, null, null, 'The electromagnetic waves that are sensitive to temperature changes are', '["X-rays","Gamma-rays","Ultra-violet rays","Infra-red rays."]', 'Infra-red radiation is heat radiation, and it is detected by its heating effect.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6427f431-8a35-478f-81d4-be47ed915d3e', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. His father served as a <u>mercenary</u> in the army.', null, '["preacher","regular","recruit","officer"]', 1, 'Mercenary = hired; opposite = regular (soldier).', true, '2026-10-24 07:21:29.22', '2026-10-24 07:21:29.22', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. His father served as a <u>mercenary</u> in the army.', '["preacher","regular","recruit","officer"]', 'Mercenary = hired; opposite = regular (soldier).', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('642fa935-a15f-44f6-a18e-111698d564a1', 'Literature in English', 'JAMB', null, 2026, null, 'A reference to another work of literature, history, or culture is known as', null, '["Alyson","Allusion","Illusion","Personification"]', 1, 'Allusion is a reference to another work.', true, '2026-09-12 11:05:55.379', '2026-09-12 11:05:55.379', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('64328b26-16ec-4508-83f1-28d2f8582371', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). You need to <u>brush up on</u> your Spanish.', null, '["You need to study the history of Spain","You need to improve your skills","You need a brush from Spain","You need to learn to play with a Spaniard"]', 1, '''Brush up on'' = improve/refresh skills.', true, '2026-10-24 01:04:23.399', '2026-10-24 01:04:23.399', null, null, null, '(Choose the most appropriate interpretation). You need to <u>brush up on</u> your Spanish.', '["You need to study the history of Spain","<u>You need to improve your skills</u>","You need a brush from Spain","You need to learn to play with a Spaniard"]', '''<b>Brush up on</b>'' = <b>improve/refresh skills</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('643add70-669f-44e9-9c54-a3352c26a2d6', 'Economics', 'JAMB', null, 2026, null, '______ refers to the fall in the value of a country''s currency against other currencies as a result of the interplay of the forces of demand and supply', null, '["Depreciation","Depression","inter-precision","Appreciation"]', 0, 'Depreciation is the fall in the value of a currency due to demand and supply forces.', true, '2026-09-12 11:00:59.488', '2026-09-12 11:00:59.488', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6442578b-da5c-43e3-9d27-8212dbb6a618', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The members of the family had a <u>hasty</u> breakfast before starting out on their journey.', null, '["hurried","leisurely","tasty","nasty"]', 1, 'Hasty = hurried; opposite = leisurely.', true, '2026-10-24 07:21:27.613', '2026-10-24 07:21:27.613', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The members of the family had a <u>hasty</u> breakfast before starting out on their journey.', '["hurried","leisurely","tasty","nasty"]', 'Hasty = hurried; opposite = leisurely.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('644ee955-e581-4738-a936-c09298f09419', 'General Mathematics', 'JAMB', null, 2026, null, 'Evaluate ∫sin2x dx', null, '["-1/2 cos2x + K","-2cos2x + K","1/2 cos2x + K","cos2x + K"]', 0, '∫sin2x dx = -1/2 cos2x + K.', true, '2026-09-12 11:43:46.451', '2026-09-12 11:43:46.451', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('64596a56-1d66-4d79-9c36-907c7afd8d46', 'Christian Religious Studies', 'JAMB', null, 2026, null, '''Do not weep for me, but weep for yourselves and for your children...'' These words were addressed by Jesus to the', null, '["sons of Jerusalem","men of Bethlehem","women of Bethlehem","daughters of Jerusalem"]', 3, 'Jesus addressed these words to the daughters of Jerusalem.', true, '2026-09-12 10:41:37.683', '2026-09-12 10:41:37.683', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6463a55c-5ee3-4143-a094-026690eac773', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The man''s wife has her <u>misgiving</u> about him.', null, '["fears for","distrust of","hatred for","love for"]', 1, 'Misgiving = distrust of.', true, '2026-10-24 01:04:08.589', '2026-10-24 01:04:08.589', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The man''s wife has her <u>misgiving</u> about him.', '["fears for","<u>distrust of</u>","hatred for","love for"]', '<b>Misgiving</b> = <b>distrust of</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('647b3cc4-802c-4403-a7de-1c7a7991ec5f', 'Physics', 'JAMB', null, 2004, null, 'A radioisotope has a decay constant of 10⁻⁷ s⁻¹. The average life of the radioisotope is', null, '["6.93 x 10⁸ s","1.00 x 10⁻⁷ s","1.00 x 10⁷ s","6.93 x 10⁷ s"]', 2, 'Average life = 1/λ = 1/10⁻⁷ = 1.00 x 10⁷ s.', true, '2026-10-12 19:15:58.981', '2026-10-12 19:15:58.981', null, null, null, 'A radioisotope has a decay constant of 10<sup>-7</sup> s<sup>-1</sup>. The average life of the radioisotope is', '["6.93 x 10<sup>8</sup> s","1.00 x 10<sup>-7</sup> s","1.00 x 10<sup>7</sup> s","6.93 x 10<sup>7</sup> s"]', 'Average life = 1/λ = 1/10<sup>-7</sup> = 1.00 x 10<sup>7</sup> s.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('647cb8b7-b0e5-4142-b351-c71b5120716f', 'Government', 'JAMB', null, 2026, null, 'The supreme power of a State to make and enforce law within its jurisdiction is called', null, '["Authority","power","coercion","sovereignty"]', 3, 'The supreme power of a state to make and enforce law within its jurisdiction is called sovereignty. Sovereignty is the supreme, absolute, and unlimited power of the state to make and enforce laws within its territory without external interference. It has two aspects: internal sovereignty (supreme power within the state) and external sovereignty (independence from external control). Authority is the right to exercise power, power is the ability to influence, and coercion is the use of force.', true, '2026-09-10 10:45:07.265', '2026-09-10 10:45:07.265', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('647e7686-1200-4fb4-9ac6-a8d7d78be41f', 'Physics', 'JAMB', null, 2026, null, 'Which is not a difference between mass and weight?', null, '["Mass is constant and weight is variable","Mass is a vector and Weight is a scalar","Mass is dependent on location/position while weight is not","Mass is measured with a beam balance while weight is measured with spring balance","mass is measured in kg weight in N"]', 1, 'The statement that mass is a vector and weight is a scalar is not a difference between mass and weight—it is incorrect. Mass is a scalar and weight is a vector. This is a false statement, making it the correct answer.', true, '2026-09-10 10:56:49.264', '2026-09-10 10:56:49.264', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6480eee0-9f96-43d8-a10b-63a32d0d88e7', 'English Language', 'JAMB', null, 2007, null, 'People dislike Mariam because she is <u>__________</u>', null, '["trickful","trickish","tricky","a tricker"]', 2, 'Correct spelling: tricky.', true, '2026-10-24 07:21:35.818', '2026-10-24 07:21:35.818', null, null, null, 'People dislike Mariam because she is <u>__________</u>', '["trickful","trickish","tricky","a tricker"]', 'Correct spelling: tricky.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6485e6ec-ed0c-4668-bcc8-4bdd77654111', 'Literature in English', 'JAMB', null, 2026, null, 'The character of Bendu is significant primarily because she', null, '["Represents political authority in post-war Liberia","Embodies the psychological and emotional scars of the civil war","Serves as comic relief throughout the narrative","Symbolises Western intervention in Africa"]', 1, 'Bendu embodies the psychological and emotional scars of the civil war.', true, '2026-09-12 11:12:00.74', '2026-09-12 11:12:00.74', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('649af231-74f2-4044-8b24-c9bb9e73a4ed', 'Physics', 'JAMB', null, 2026, null, 'Calculate the force acting on an electron of charge 1.6×10⁻¹⁹C placed in an electric field of intensity 10⁸Vm⁻¹', null, '["1.6×10⁻¹⁰N","1.6×10⁻¹¹N","1.6×10⁻¹⁴N","1×10⁻¹⁶N"]', 1, 'F = qE = 1.6×10⁻¹⁹ × 10⁸ = 1.6×10⁻¹¹N.', true, '2026-09-10 10:56:47.467', '2026-09-10 10:56:47.467', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('64a2059d-08d0-4e2f-980a-d050e5fe5858', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Okibe was rusticated from his <u>derogatory</u> remark about the principal.', null, '["complimentary","unwarranted","unsavoury","lacklustre"]', 2, 'Derogatory = unsavoury.', true, '2026-10-24 01:01:54.961', '2026-10-24 01:01:54.961', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Okibe was rusticated from his <u>derogatory</u> remark about the principal.', '["complimentary","unwarranted","<u>unsavoury</u>","lacklustre"]', '<b>Derogatory</b> = <b>unsavoury</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('64a2f181-4272-45ac-931e-23d8c2c64a1d', 'Government', 'JAMB', null, 2026, null, 'Which of the following is not a tool used in e-government', null, '["Internet","Telephone","Paper and pen","Short messaging service"]', 2, 'Paper and pen is not a tool of e-government.', true, '2026-09-12 11:24:38.633', '2026-09-12 11:24:38.633', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('64b38146-3853-48de-9cc4-5c73fef638e2', 'Yoruba', 'JAMB', null, 2007, null, 'Iwà òmòlùàbí ni kí a', null, '["fèjè sínú tutó funfun jáde","tí ojú çlesè mèsàn-án kà á","ránni níyè çrú fi tòmò jè ç","máa yè fààjì lóòrekóòrè."]', 0, 'Iwà òmòlùàbí ni kí a fèjè sínú tutó funfun jáde.', true, '2026-10-13 13:23:32.995', '2026-10-13 13:23:32.995', null, null, null, 'Iwà òmòlùàbí ni kí a', '["fèjè sínú tutó funfun jáde","tí ojú çlesè mèsàn-án kà á","ránni níyè çrú fi tòmò jè ç","máa yè fààjì lóòrekóòrè."]', 'Iwà òmòlùàbí ni kí a fèjè sínú tutó funfun jáde.', '{"bold":["fèjè sínú tutó funfun jáde"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('64b547dd-ccdd-4f99-81d9-0b4b704f31a8', 'Physics', 'JAMB', null, 1997, null, 'Light of velocity 3.0 x 10⁸ m s⁻¹ is incident on a material of refractive index n. If the velocity of light is reduced to 2.4 x 10⁸ m s⁻¹ in the material, what is n?', null, '["2.33","2.25","1.33","1.25"]', 3, 'n = c/v = (3.0 x 10⁸)/(2.4 x 10⁸) = 1.25.', true, '2026-10-12 19:15:43.959', '2026-10-12 19:15:43.959', null, null, null, 'Light of velocity 3.0 x 10<sup>8</sup> m s<sup>-1</sup> is incident on a material of refractive index n. If the velocity of light is reduced to 2.4 x 10<sup>8</sup> m s<sup>-1</sup> in the material, what is n?', '["2.33","2.25","1.33","1.25"]', 'n = c/v = (3.0 x 10<sup>8</sup>)/(2.4 x 10<sup>8</sup>) = 1.25.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('64b96737-df25-4b15-bdc5-762378bc7953', 'Physics', 'JAMB', null, 1998, null, 'The physical properties of sound waves can best be described by', null, '["Reflection and diffraction","Polarization and reflection","Polarization and diffraction","Polarization and refraction"]', 0, 'Sound is a longitudinal wave, so it cannot be polarized. It does show reflection (echoes) and diffraction.', true, '2026-10-12 19:15:45.731', '2026-10-12 19:15:45.731', null, null, null, 'The physical properties of sound waves can best be described by', '["Reflection and diffraction","Polarization and reflection","Polarization and diffraction","Polarization and refraction"]', 'Sound is a longitudinal wave, so it cannot be polarized. It does show reflection (echoes) and diffraction.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('64cb1255-4e0f-4171-a35f-5e23bc8236a2', 'Literature in English', 'JAMB', null, 2026, null, 'Iya Agba helped Desola and Odekunle to', null, '["place a curse on Ajanaku","Re-order their lives","cast a spell on Ajanaku","expose Serubawon''s atrocities"]', 1, 'Iya Agba helped them re-order their lives.', true, '2026-09-12 11:13:55.632', '2026-09-12 11:13:55.632', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('64d77671-23b1-49a5-8577-1f91c6a5a6fd', 'Biology', 'JAMB', null, 2026, null, 'One of the following is also known as mitral valve', null, '["tricuspid valve","aortic valve","semilunar valve","bicuspid valve"]', 3, 'The mitral valve is also known as the bicuspid valve. It is the atrioventricular valve between the left atrium and left ventricle, consisting of two flaps (hence ''bi-cuspid''). The tricuspid valve is between the right atrium and right ventricle. The aortic valve and semilunar valves are associated with the exits of the ventricles (aortic and pulmonary). The mitral valve is named for its resemblance to a bishop''s mitre (hat). It is one of the four valves of the heart, essential for maintaining unidirectional blood flow.', true, '2026-09-09 03:18:51.734', '2026-09-09 03:18:51.734', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('64d8cb87-7336-4da9-b6be-8c6a547d1a9e', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. In spite of her grim situation, the young widow smiled dutifully at the visitor''s <u>pleasantries</u>.', null, '["unkind comments","sad stories","condolence messages","jocular remarks"]', 3, 'Pleasantries = jocular remarks.', true, '2026-10-24 01:04:02.266', '2026-10-24 01:04:02.266', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. In spite of her grim situation, the young widow smiled dutifully at the visitor''s <u>pleasantries</u>.', '["unkind comments","sad stories","condolence messages","<u>jocular remarks</u>"]', '<b>Pleasantries</b> = <b>jocular remarks</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('64e611b8-0ab9-401f-97e1-3e0a7aa85616', 'Physics', 'JAMB', null, 1987, null, 'Which of the following statements is TRUE of the photoelectric effect?', null, '["It cannot occur in liquids","The energy of the emitted electron is independent of the work function of the surface","The energy of the emitted electron depends on the wavelength of the incident light","The greater the intensity of the incident light, the greater the energy of the emitted electron."]', 2, 'Maximum kinetic energy = hf - φ. It depends on the frequency (and so the wavelength) of the light and the work function, not on the intensity.', true, '2026-10-12 19:15:26.621', '2026-10-12 19:15:26.621', null, null, null, 'Which of the following statements is TRUE of the photoelectric effect?', '["It cannot occur in liquids","The energy of the emitted electron is independent of the work function of the surface","The energy of the emitted electron depends on the wavelength of the incident light","The greater the intensity of the incident light, the greater the energy of the emitted electron."]', 'Maximum kinetic energy = hf - φ. It depends on the frequency (and so the wavelength) of the light and the work function, not on the intensity.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('64e7b051-5099-47a2-9085-8935907d912b', 'Biology', 'JAMB', null, 2001, null, 'Most monocots are easily recognized by their', null, '["long and sword-like leaves","long and palm-like leaves","short leaves with petioles","short leaves with many veinlets"]', 0, 'Monocots typically have long, sword-like leaves with parallel venation.', true, '2026-10-12 20:59:28.119', '2026-10-12 20:59:28.119', null, null, null, 'Most monocots are easily recognized by their', '["long and sword-like leaves","long and palm-like leaves","short leaves with petioles","short leaves with many veinlets"]', 'Monocots typically have long, sword-like leaves with parallel venation.', '{"bold":["long, sword-like leaves"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('64eea47a-3c32-4602-914b-aada4f3ad123', 'Government', 'JAMB', null, 2026, null, 'Which of these is a way to enhance or improve local government revenue base', null, '["Absence of priority","Decreasing the monthly allocation","Absence of special grants","Engaging in more profitable ventures"]', 3, 'Engaging in more profitable ventures improves local government revenue.', true, '2026-09-12 11:24:24.681', '2026-09-12 11:24:24.681', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('64f1b1cd-e732-4308-a554-9c82a0669353', 'Physics', 'JAMB', null, 1997, null, 'A liquid of mass 1.0 x 10³ kg fills a rectangular tank of length 2.5 m and width 2.0 m. If the tank is 4 m high, what is the pressure at the middle of the tank? [g = 10 m s⁻²]', null, '["1.0 x 10⁴ N m⁻²","2.0 x 10³ N m⁻²","1.5 x 10³ N m⁻²","1.0 x 10³ N m⁻²"]', 3, 'Volume = 2.5 x 2.0 x 4 = 20 m³, so density = 1000/20 = 50 kg m⁻³. At the middle (depth 2 m) P = ρgh = 50 x 10 x 2 = 1.0 x 10³ N m⁻².', true, '2026-10-12 19:15:43.254', '2026-10-12 19:15:43.254', null, null, null, 'A liquid of mass 1.0 x 10<sup>3</sup> kg fills a rectangular tank of length 2.5 m and width 2.0 m. If the tank is 4 m high, what is the pressure at the middle of the tank? [g = 10 m s<sup>-2</sup>]', '["1.0 x 10<sup>4</sup> N m<sup>-2</sup>","2.0 x 10<sup>3</sup> N m<sup>-2</sup>","1.5 x 10<sup>3</sup> N m<sup>-2</sup>","1.0 x 10<sup>3</sup> N m<sup>-2</sup>"]', 'Volume = 2.5 x 2.0 x 4 = 20 m<sup>3</sup>, so density = 1000/20 = 50 kg m<sup>-3</sup>. At the middle (depth 2 m) P = ρgh = 50 x 10 x 2 = 1.0 x 10<sup>3</sup> N m<sup>-2</sup>.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('64fac8c7-f1c9-43eb-ad92-35368355bebb', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). I didn''t think she could be so easily <u>taken in</u> by his pretences.', null, '["flattered","deceived","overcome","blackmailed"]', 1, '''Taken in'' = deceived.', true, '2026-10-24 01:04:18.787', '2026-10-24 01:04:18.787', null, null, null, '(Choose the most appropriate interpretation). I didn''t think she could be so easily <u>taken in</u> by his pretences.', '["flattered","<u>deceived</u>","overcome","blackmailed"]', '''<b>Taken in</b>'' = <b>deceived</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('64fb7b82-cd6e-4a12-9546-0c6f59868eca', 'English Language', 'JAMB', null, 2007, null, 'The laughter <u>__________</u> his face for a moment', null, '["improved","controlled","animated","remade"]', 2, 'Correct spelling: animated.', true, '2026-10-24 07:21:37.78', '2026-10-24 07:21:37.78', null, null, null, 'The laughter <u>__________</u> his face for a moment', '["improved","controlled","animated","remade"]', 'Correct spelling: animated.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('650cc07c-b8fd-45c5-a3f9-a1d45556da92', 'Literature in English', 'JAMB', null, 2026, null, 'The repeated refrain from ''What business of mine is it/So long they don''t take the yam/ From my savouring mouth?'' serves to', null, '["create a musical rhythm for the poem","emphasizes the speaker''s political engagement","highlights the speaker''s hypocritical reasoning","provides comic relief after each tragic event"]', 2, 'It highlights the speaker''s hypocritical reasoning.', true, '2026-09-12 11:11:01.757', '2026-09-12 11:11:01.757', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6518a3a5-c1e8-4aae-a30d-11145add94ff', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Our teacher <u>seldom</u> comes late to school.', null, '["very often","always","frequently","hardly ever"]', 3, 'Seldom = hardly ever.', true, '2026-10-24 01:03:55.541', '2026-10-24 01:03:55.541', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Our teacher <u>seldom</u> comes late to school.', '["very often","always","frequently","<u>hardly ever</u>"]', '<b>Seldom</b> = <b>hardly ever</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('65387238-b62d-4955-9c57-43ed5f839217', 'Biology', 'JAMB', null, 2026, null, 'Which of the following is not required for photosynthesis in plants?', null, '["sunlight","oxygen","water","chlorophyll"]', 1, 'Oxygen is not required for photosynthesis; in fact, it is a product of photosynthesis. The required raw materials for photosynthesis are sunlight (energy source), water (H₂O), and carbon dioxide (CO₂). Chlorophyll is necessary as the pigment that captures light energy. Photosynthesis produces glucose and oxygen. Oxygen is released as a byproduct. Some photosynthetic bacteria can use compounds other than water as electron donors, but for plants, the process requires water and CO₂, with light providing the energy.', true, '2026-09-09 03:18:50.189', '2026-09-09 03:18:50.189', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('653934e2-c79c-4e05-b42b-02e242bc050a', 'Physics', 'JAMB', null, 1999, null, 'Two bodies have masses in the ratio 3 : 1. They experience forces which impart to them accelerations in the ratio 2 : 9 respectively. Find the ratio of the forces the masses experience.', null, '["1 : 4","2 : 1","2 : 3","2 : 5."]', 2, 'F = ma, so F₁:F₂ = (3 x 2) : (1 x 9) = 6 : 9 = 2 : 3.', true, '2026-10-12 19:15:47.127', '2026-10-12 19:15:47.127', null, null, null, 'Two bodies have masses in the ratio 3 : 1. They experience forces which impart to them accelerations in the ratio 2 : 9 respectively. Find the ratio of the forces the masses experience.', '["1 : 4","2 : 1","2 : 3","2 : 5."]', 'F = ma, so F<sub>1</sub>:F<sub>2</sub> = (3 x 2) : (1 x 9) = 6 : 9 = 2 : 3.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6539bc3d-8bd4-49d2-af7a-6d427ad68039', 'English Language', 'JAMB', null, 2007, null, 'Neither Agbo nor his parents <u>------------</u> the meetings now.', null, '["has attended","attend","attended","attends"]', 1, 'Nearest subject parents plural â†’ attend.', true, '2026-10-24 01:02:14.785', '2026-10-24 01:02:14.785', null, null, null, 'Neither Agbo nor his parents <u>------------</u> the meetings now.', '["has attended","<u>attend</u>","attended","attends"]', 'Nearest subject <b>parents</b> plural â†’ <b>attend</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('65439b74-05b1-49e4-b00c-9118d35429cf', 'Biology', 'JAMB', null, 2004, null, 'One adaptation of reptiles to water loss is the presence of', null, '["keratinous scales","claws on limbs","long tails","long sticky tongues"]', 0, 'Keratinous scales reduce water loss in reptiles.', true, '2026-10-12 20:59:35.527', '2026-10-12 20:59:35.527', null, null, null, 'One adaptation of reptiles to water loss is the presence of', '["keratinous scales","claws on limbs","long tails","long sticky tongues"]', 'Keratinous scales reduce water loss in reptiles.', '{"bold":["Keratinous scales"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('654bf0aa-6fcc-4852-a72e-01931c0a6689', 'Literature in English', 'JAMB', null, 2026, null, 'Identify the device in: ''The crown will decide your fate.''', null, '["Synecdoche","Metonymy","Hyperbole","Irony"]', 1, 'Metonymy is used.', true, '2026-09-12 11:14:14.326', '2026-09-12 11:14:14.326', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6556df76-686a-4ee7-b405-67c06eb8fa21', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The new employee is so humble and friendly that he will soon <u>make himself popular</u>.', null, '["welcomed and accepted","hated","estranged","rejected","a personal friend"]', 0, 'Make himself popular = welcomed and accepted.', true, '2026-10-24 01:03:53.328', '2026-10-24 01:03:53.328', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The new employee is so humble and friendly that he will soon <u>make himself popular</u>.', '["<u>welcomed and accepted</u>","hated","estranged","rejected","a personal friend"]', '<b>Make himself popular</b> = <b>welcomed and accepted</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('655bd36e-60e8-4c1a-bce6-0f6f141e0f3d', 'English Language', 'JAMB', null, 2007, null, 'I had not given the question a thought before; my answer came <u>__________</u>', null, '["momentarily","in an instant","on the spur of the moment","just like that"]', 2, 'Correct form: on the spur of the moment.', true, '2026-10-24 07:21:42.004', '2026-10-24 07:21:42.004', null, null, null, 'I had not given the question a thought before; my answer came <u>__________</u>', '["momentarily","in an instant","on the spur of the moment","just like that"]', 'Correct form: on the spur of the moment.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('655d33e1-3203-4d54-99f7-3cbbda235518', 'Literature in English', 'JAMB', null, 2026, null, 'The clash of interest that originates from opposing forces in literature is', null, '["Climax","Denouement","Conflict","Aside"]', 2, 'It is conflict.', true, '2026-09-12 11:14:02.939', '2026-09-12 11:14:02.939', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6567ac60-ea06-459b-aae7-ad497268b4c1', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The tennis player <u>surreptitiously swapped</u> rackets after the first set.', null, '["openly retained","overtly exchanged","quietly surrendered","violently swung"]', 0, 'Surreptitiously = secretly; opposite = openly.', true, '2026-10-24 07:21:19.274', '2026-10-24 07:21:19.274', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The tennis player <u>surreptitiously swapped</u> rackets after the first set.', '["openly retained","overtly exchanged","quietly surrendered","violently swung"]', 'Surreptitiously = secretly; opposite = openly.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('656a85fe-57e5-407f-88d2-3800fd488e7c', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Your effort to bring peace between us is futile because you are <u>biased</u>.', null, '["convinced","clever","prejudiced","worried"]', 2, 'Biased = prejudiced.', true, '2026-10-24 01:01:55.914', '2026-10-24 01:01:55.914', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Your effort to bring peace between us is futile because you are <u>biased</u>.', '["convinced","clever","<u>prejudiced</u>","worried"]', '<b>Biased</b> = <b>prejudiced</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('657ee4c4-3b9c-4bae-be9c-4b07d5a13e55', 'Biology', 'JAMB', null, 2026, null, 'When a person with blood group O has lost much blood due to an accident, he can be given blood belonging to', null, '["group O only","group A only","group AB only","group A and O","group AB and O"]', 0, 'When a person with blood group O has lost much blood, he can be given blood belonging to group O only. A person with blood group O has anti-A and anti-B antibodies in their plasma. If they receive blood from any other group (A, B, or AB), the antibodies will attack the donor''s red blood cells, causing agglutination (clumping). Therefore, individuals with blood group O can only receive blood from other O donors. They are universal donors but universal recipients only for O blood.', true, '2026-09-09 03:19:31.695', '2026-09-09 03:19:31.695', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('658391b2-b4af-40b4-b8c0-1d5bbbe5831a', 'Chemistry', 'JAMB', null, 2026, null, 'The energy which accompanies the addition of an electron to an isolated gaseous atom is', null, '["electron affinity","atomization","Ionisation","electronegativity"]', 0, 'Electron affinity is defined as the energy change that occurs when an electron is added to a neutral gaseous atom to form a negative ion.', true, '2026-09-09 17:12:44.882', '2026-09-09 17:12:44.882', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('65a6a6c1-8244-41fc-87ec-c8b9de68176a', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Jankoli was dressed in an old <u>assortment</u> of clothes.', null, '["homogeneity","sameness","mÃ©lange","avalanche"]', 2, 'Assortment = mÃ©lange.', true, '2026-10-24 01:04:06.975', '2026-10-24 01:04:06.975', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Jankoli was dressed in an old <u>assortment</u> of clothes.', '["homogeneity","sameness","<u>mÃ©lange</u>","avalanche"]', '<b>Assortment</b> = <b>mÃ©lange</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('65b10035-adaa-4ec8-9b91-8e0ababf26ca', 'Biology', 'JAMB', null, 2010, null, 'The protozoan Plasmodium falciparum is transmitted by', null, '["female Anopheles mosquitoes","female Aedes mosquitoes","female Culex mosquitoes","female blackfly"]', 0, 'Plasmodium falciparum is transmitted by female Anopheles mosquitoes.', true, '2026-10-12 20:59:41.088', '2026-10-12 20:59:41.088', null, null, null, 'The protozoan Plasmodium falciparum is transmitted by', '["female Anopheles mosquitoes","female Aedes mosquitoes","female Culex mosquitoes","female blackfly"]', 'Plasmodium falciparum is transmitted by female Anopheles mosquitoes.', '{"bold":["female Anopheles mosquitoes"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('65b29c3d-2796-41a0-8a4d-a722738ae062', 'Biology', 'JAMB', null, 2026, null, 'Homologous pairs of chromosomes separate during', null, '["cleavage","cytolysis","mitosis","meiosis"]', 3, 'Homologous pairs of chromosomes separate during meiosis. This occurs during meiosis I (specifically during anaphase I). In meiosis I, homologous chromosomes separate from each other, reducing the chromosome number from diploid to haploid. Mitosis involves the separation of sister chromatids, not homologous chromosomes. Cleavage is cell division without growth. Cytolysis is cell bursting.', true, '2026-09-09 03:19:27.196', '2026-09-09 03:19:27.196', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('65c1897a-d111-4370-b4ca-60dd533aed16', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The manager made <u>disparaging</u> remarks about the retiring officer.', null, '["parochial","cynical","derogatory","rude"]', 2, 'Disparaging = derogatory.', true, '2026-10-24 01:04:03.759', '2026-10-24 01:04:03.759', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The manager made <u>disparaging</u> remarks about the retiring officer.', '["parochial","cynical","<u>derogatory</u>","rude"]', '<b>Disparaging</b> = <b>derogatory</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('65d2c53f-d943-4cba-a5e9-05355e6140b7', 'Physics', 'JAMB', null, 2026, null, 'The proton and neutron has a relative mass of 1U where U represents the unified atomic mass unit. What is the value of U?', null, '["9.31×10⁻³¹kg","1.6×10⁻¹⁹kg","9×10kg","1.66×10⁻²⁷kg"]', 3, '1 unified atomic mass unit (U) = 1.66×10⁻²⁷ kg.', true, '2026-09-10 10:56:49.953', '2026-09-10 10:56:49.953', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('65d76725-a805-4479-ab2d-76f756a5b8e4', 'Biology', 'JAMB', null, 2026, null, 'A water medium is necessary for fertilization in', null, '["fungi","conifers","ferns","angiosperms"]', 2, 'A water medium is necessary for fertilization in ferns (pteridophytes). Ferns have motile sperm that require water to swim to the egg. Fungi do not require water for fertilization, reproducing through spores. Conifers and angiosperms have pollen grains that do not require water, using wind or animal pollinators to transfer sperm to the egg. This is why ferns are often found in moist environments where water is available for reproduction. The need for water for fertilization limits ferns to damp habitats.', true, '2026-09-09 03:19:05.98', '2026-09-09 03:19:05.98', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('65dbe6b7-f405-43b3-af3e-2a71cdd2373f', 'Financial Accounting', 'UTME', null, 2003, null, 'Calculate the price per unit of closing stock using the periodic weighted method.', null, '["N3.20","N3.00","N2.20","N2.00"]', 2, 'Using the periodic weighted average method, the price per unit of closing stock is N2.20.', true, '2026-10-12 22:00:00.027', '2026-10-12 22:00:00.027', null, null, null, 'Calculate the price per unit of closing stock using the periodic weighted method.', '["N3.20","N3.00","<b>N2.20</b>","N2.00"]', 'Using the periodic weighted average method, the price per unit of closing stock is <b>N2.20</b>.', '{"bold":["N2.20"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('65de5adf-352d-48e7-8a4e-ef62ec7d5b01', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). Old customs <u>die hard</u>. This implies that old customs ____________', null, '["cause a lot of hardship and death","must be stopped","never die out","cause hardship for younger people","tend to last for a long time"]', 4, '''Die hard'' means slow to disappear.', true, '2026-10-24 01:02:00.562', '2026-10-24 01:02:00.562', null, null, null, '(Choose the most appropriate interpretation). Old customs <u>die hard</u>. This implies that old customs ____________', '["cause a lot of hardship and death","must be stopped","never die out","cause hardship for younger people","<u>tend to last for a long time</u>"]', '''<b>Die hard</b>'' means <b>slow to disappear</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('65dec03a-b77d-45ea-8e2f-04d1b6f5d62c', 'Economics', 'JAMB', null, 2026, null, 'The Production Possibility Boundary (PPB) can be shifted inward by all the following except', null, '["Technology progress","Natural disasters","Decline in demand","Increase in cost of production"]', 0, 'Technology progress shifts the PPB outward, not inward.', true, '2026-09-12 10:59:45.77', '2026-09-12 10:59:45.77', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('65ee9e7f-d245-47b9-9ff7-bce7d569cfb7', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Iliya''s account of the incident is <u>appalling</u>.', null, '["tasking","fascinating","horrifying","ridiculous"]', 1, 'Appalling = horrifying; opposite = fascinating.', true, '2026-10-24 07:21:28.258', '2026-10-24 07:21:28.258', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Iliya''s account of the incident is <u>appalling</u>.', '["tasking","fascinating","horrifying","ridiculous"]', 'Appalling = horrifying; opposite = fascinating.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('660eb609-a778-4121-8809-ab86ea974b7a', 'Physics', 'JAMB', null, 2026, null, 'The colours seen in soap bubbles are due to', null, '["diffraction","refraction","dispersion","interference"]', 3, 'The colours seen in soap bubbles are due to interference. Light reflects off both the outer and inner surfaces of the soap film, and these reflected waves interfere constructively or destructively for different wavelengths, producing colours.', true, '2026-09-10 10:56:46.979', '2026-09-10 10:56:46.979', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('662aad86-2c75-458f-bd51-7dc41ac3e949', 'Physics', 'JAMB', null, 2026, null, 'Coplanar forces, of magnitudes F.N, 3FN, GN and 50N, act at a point P, as shown in the diagram. If F = 0, G = 75N and angle α = 60°, find the resultant force', 'https://res.cloudinary.com/kwi1uv0g/image/upload/v1789039564/questions/tl32b3tadoom20k879fo.jpg', '["3N","50N","110N","67N"]', 2, 'With F = 0 and G = 75N: Resolving horizontal = 75 + 50cos60° = 75 + 25 = 100N. Vertical = 50sin60° = 43.3N. Resultant = √(100² + 43.3²) = √11875 = 109N ≈ 110N.', true, '2026-09-10 11:27:02.224', '2026-09-10 11:27:02.224', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('663bd32c-2182-40d9-a25a-82501a6e0705', 'General Mathematics', 'JAMB', null, 2026, null, 'The sum to infinity of a G.P is 80. If the first term of the series is 20, find the second term.', null, '["15","45/4","5","5/4","3/4"]', 0, '20/(1-r) = 80. 1-r = 1/4. r = 3/4. Second term = 20(3/4) = 15.', true, '2026-09-12 11:44:03.365', '2026-09-12 11:44:03.365', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('66409222-0182-4ef2-a8c7-341a40c2c4ea', 'English Language', 'JAMB', null, 2024, null, 'Choose the word that has the same sound as the one represented by the underlined letters: p_e_pper', null, '["head","ago","bear","err"]', 0, 'The "e" in "pepper" sounds like /e/, same as the "ea" in "head."', true, '2026-09-18 09:23:08.371', '2026-09-18 09:23:08.371', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('665503db-852c-4b01-bbaf-1aadad2b4abc', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). The task was <u>Herculean</u>.', null, '["irregular","related to Hercules","stimulating","demanding"]', 3, 'Herculean = demanding great effort.', true, '2026-10-24 01:04:17.447', '2026-10-24 01:04:17.447', null, null, null, '(Choose the most appropriate interpretation). The task was <u>Herculean</u>.', '["irregular","related to Hercules","stimulating","<u>demanding</u>"]', '<b>Herculean</b> = <b>demanding great effort</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('66559d52-1b27-4c93-ac04-74f33cfa46c3', 'Biology', 'JAMB', null, 2012, null, 'Plant growth can be artificially stimulated by the addition of', null, '["gibberellin","kinin","abscisic acid","ethylene."]', 0, 'Gibberellin stimulates plant growth.', true, '2026-10-12 20:59:44.944', '2026-10-12 20:59:44.944', null, null, null, 'Plant growth can be artificially stimulated by the addition of', '["gibberellin","kinin","abscisic acid","ethylene."]', 'Gibberellin stimulates plant growth.', '{"bold":["Gibberellin"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6666afae-f112-46e2-a928-cceb23150eaf', 'English Language', 'JAMB', null, 2007, null, 'What bothered me about the lecture was the speaker <u>__________</u> too many irrelevant words.', null, '["slighted","sighted","sited","cited"]', 3, 'Correct spelling and meaning: cited.', true, '2026-10-24 07:21:32.892', '2026-10-24 07:21:32.892', null, null, null, 'What bothered me about the lecture was the speaker <u>__________</u> too many irrelevant words.', '["slighted","sighted","sited","cited"]', 'Correct spelling and meaning: cited.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('667d6103-95da-45d6-bc9c-84d444a1c341', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). Everybody <u>respects</u> the team leader.', null, '["looks up for","looks up on","looks up to","looks up at"]', 2, '''Looks up to'' = respects.', true, '2026-10-24 01:04:17.178', '2026-10-24 01:04:17.178', null, null, null, '(Choose the most appropriate interpretation). Everybody <u>respects</u> the team leader.', '["looks up for","looks up on","<u>looks up to</u>","looks up at"]', '''<b>Looks up to</b>'' = <b>respects</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('668c684c-526a-46ef-82fc-311963779559', 'General Mathematics', 'JAMB', null, 2026, null, 'In a survey of 100 students, 60 like Math, 50 like physics, and 40 like chemistry. If 30 students like math and physics, 20 like physics and chemistry, 25 like math and chemistry, and 15 like all three, how many students like NONE of the three subjects?', null, '["10","15","90","25"]', 2, 'n(M∪P∪C) = 60+50+40-30-20-25+15 = 90. None = 100-90 = 10.', true, '2026-09-12 11:43:49.813', '2026-10-24 17:14:39.209', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('669b0766-6332-4987-820c-f0d3e90bf2db', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. We must not <u>foreclose</u> reconciliation as the purpose of his trip.', null, '["exclude","underestimate","consider","forgo"]', 0, 'Foreclose = exclude.', true, '2026-10-24 01:01:55.597', '2026-10-24 01:01:55.597', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. We must not <u>foreclose</u> reconciliation as the purpose of his trip.', '["<u>exclude</u>","underestimate","consider","forgo"]', '<b>Foreclose</b> = <b>exclude</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('66a5e0d9-ddb1-4fe2-91dc-9ab9337bdb4d', 'Physics', 'JAMB', null, 1985, null, 'A narrow beam of white light can be split up into different colours by a glass prism. The correct explanation is that', null, '["White light is an electromagnetic wave","The prism has all the colours of the white light","White light has undergone total internal reflection in the prism","Different colours of white light travel with different speeds in glass.","White light consists of yellow, green and red colours."]', 3, 'Each colour has its own speed in glass, hence its own refractive index, so each is bent by a different amount (dispersion).', true, '2026-10-12 19:15:22.069', '2026-10-12 19:15:22.069', null, null, null, 'A narrow beam of white light can be split up into different colours by a glass prism. The correct explanation is that', '["White light is an electromagnetic wave","The prism has all the colours of the white light","White light has undergone total internal reflection in the prism","Different colours of white light travel with different speeds in glass.","White light consists of yellow, green and red colours."]', 'Each colour has its own speed in glass, hence its own refractive index, so each is bent by a different amount (dispersion).', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('66a772b6-e9a1-4029-b6fb-83fd8b1abede', 'Physics', 'JAMB', null, 1988, null, 'A piano wire 0.5 m long has a total mass of 0.01 kg and is stretched with a tension of 800 N. Calculate the frequency of the wire when it sounds its fundamental note.', null, '["200 Hz","100 Hz","4 Hz","2 Hz."]', 0, 'Mass per unit length μ = 0.01/0.5 = 0.02 kg m⁻¹. v = √(T/μ) = √(800/0.02) = 200 m s⁻¹. f = v/2L = 200/1 = 200 Hz.', true, '2026-10-12 19:15:27.585', '2026-10-12 19:15:27.585', null, null, null, 'A piano wire 0.5 m long has a total mass of 0.01 kg and is stretched with a tension of 800 N. Calculate the frequency of the wire when it sounds its fundamental note.', '["200 Hz","100 Hz","4 Hz","2 Hz."]', 'Mass per unit length μ = 0.01/0.5 = 0.02 kg m<sup>-1</sup>. v = √(T/μ) = √(800/0.02) = 200 m s<sup>-1</sup>. f = v/2L = 200/1 = 200 Hz.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('66aaf8cf-764d-417b-9420-6e02d139ce55', 'Chemistry', 'JAMB', null, 2026, null, 'For the reaction: 2SO₂(g) + O₂(g) ⇌ 2SO₃(g) ΔH < 0. Which condition favors the forward reaction?', null, '["Low pressure, high temperature","High pressure, low temperature","Low pressure, low temperature","High pressure, high temperature"]', 1, 'High pressure and low temperature favor the forward exothermic reaction with fewer gas moles.', true, '2026-09-12 11:32:59.625', '2026-09-12 11:32:59.625', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('66b16474-cd4b-4ef5-9791-c262d4ebb6a4', 'General Mathematics', 'JAMB', null, 2026, null, 'Five years ago, a father was 3 times as old as his son. Now, their combined ages amount to 110 years. Thus, the present age of the father is', null, '["75 years","60 years","98 years","80 years","105 years"]', 3, 'F-5 = 3(S-5). F+S = 110. F = 3S-10. 3S-10+S = 110. 4S = 120. S = 30. F = 80.', true, '2026-09-12 11:44:20.625', '2026-09-12 11:44:20.625', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('66cd4f49-d648-469b-a830-1dda0686cb11', 'Government', 'JAMB', null, 2026, null, 'An ideology is essentially', null, '["guide to political action","a manual for revolution","a curse on political actors","a non-political concept","negative in connotation"]', 0, 'An ideology is essentially a guide to political action.', true, '2026-09-12 11:24:51.382', '2026-09-12 11:24:51.382', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('66cdf9b4-e82a-4dce-ab1e-5c4522601bc2', 'Physics', 'JAMB', null, 2026, null, 'Which of the following electromagnetic waves has the highest frequency?', null, '["ultra violet rays","radio waves","X-rays","infrared rays"]', 2, 'X-rays have the highest frequency among the options. The electromagnetic spectrum in order of increasing frequency: radio waves, microwaves, infrared, visible light, ultraviolet, X-rays, gamma rays.', true, '2026-09-10 10:56:42.222', '2026-09-10 10:56:42.222', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('66d8dd68-cf2c-4062-b633-6d97082ef297', 'Chemistry', 'JAMB', null, 2026, null, 'In the electrolysis of CuCl₂ solution using carbon electrode (I) Copper is gotten at cathode (II) chlorine is gotten at anode (III) electrolyte becomes dilute (IV) electrolyte becomes concentrated', null, '["I, IV","II, III","II, III","II, IV"]', 0, 'Copper is deposited at the cathode, and the electrolyte becomes concentrated.', true, '2026-09-12 11:36:07.094', '2026-09-12 11:36:07.094', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('66e5cb6c-e3e0-49a3-a65b-38b92bba52eb', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. His gift to the poor was always <u>infinitesimal</u>.', null, '["large","supportive","small","shameful"]', 0, 'Infinitesimal = tiny; opposite = large.', true, '2026-10-24 07:21:27.25', '2026-10-24 07:21:27.25', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. His gift to the poor was always <u>infinitesimal</u>.', '["large","supportive","small","shameful"]', 'Infinitesimal = tiny; opposite = large.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('66e785e5-91c0-4f2a-aea2-4fae17eb8c65', 'English Language', 'JAMB', null, 2024, null, 'Remember to return it to Ruth; ______ hers.', null, '["is","it''s","it","its","its''"]', 1, '"It''s" means "it is."', true, '2026-09-18 09:43:02.533', '2026-09-18 09:43:02.533', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('66e9481c-bdfb-4fde-aa0c-ab4b00fc3d43', 'Financial Accounting', 'UTME', null, 2002, null, 'In a departmental accounting system, which of the following expenses will most likely be apportioned on the basis of turnover?', null, '["carriage outwards","carriage inwards","discounts received","return outward"]', 0, 'Carriage outwards is the amount spent in transporting goods to customers. It is therefore an expense to be apportioned on the basis of turnover.', true, '2026-10-12 21:59:57.483', '2026-10-12 21:59:57.483', null, null, null, 'In a departmental accounting system, which of the following expenses will most likely be apportioned on the basis of turnover?', '["<b>carriage outwards</b>","carriage inwards","discounts received","return outward"]', '<b>Carriage outwards</b> is the amount spent in transporting goods to customers. It is therefore an expense to be apportioned on the basis of turnover.', '{"bold":["carriage outwards"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('67023445-2b71-4c8b-a483-14d9bec556f4', 'Physics', 'JAMB', null, 2026, null, 'A satellite is in a parking orbit if its period is', null, '["less than the period of the earth","more than the period of the earth","equal to the period of the earth","the square of the period of the earth"]', 2, 'A satellite is in a parking orbit if its period is equal to the period of the earth (24 hours). This is a geostationary orbit, where the satellite appears stationary relative to a point on the earth''s surface.', true, '2026-09-10 10:56:44.334', '2026-09-10 10:56:44.334', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('67104f40-b15f-4d8c-adfe-b9fec130c5f9', 'English Language', 'JAMB', null, 2007, null, 'The man rose to an important position as a result of <u>__________</u> hard work.', null, '["sheer","cheer","share","shear"]', 0, 'Correct spelling: sheer.', true, '2026-10-24 07:21:33.501', '2026-10-24 07:21:33.501', null, null, null, 'The man rose to an important position as a result of <u>__________</u> hard work.', '["sheer","cheer","share","shear"]', 'Correct spelling: sheer.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('67309264-ab01-4493-ac93-329c50710089', 'Literature in English', 'JAMB', null, 2026, null, '''Mine'' in the extract refers to', null, '["Pompey","Cleopatra","Menas","Caesar"]', 0, '''Mine'' refers to Pompey.', true, '2026-09-12 11:11:17.059', '2026-09-12 11:11:17.059', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6733c60a-198c-4ee6-921c-347cce5a8279', 'Literature in English', 'JAMB', null, 2026, null, 'The written text of a play before it is performed on stage is known as the', null, '["Script","Dialogue","Drama","Excerpt"]', 0, 'The written text of a play before it is performed on stage is known as the script. The script contains the dialogue, stage directions, character descriptions, and other instructions for the performance. It is the blueprint for the play. Dialogue is the conversation between characters, drama is the genre, and an excerpt is a short extract from a longer work.', true, '2026-09-10 10:45:33.698', '2026-09-10 10:45:33.698', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('673bf190-effd-4ff0-8538-d7a62864e097', 'English Language', 'JAMB', null, 2007, null, 'The adventurers ran into many <u>__________</u>', null, '["dear","dears","deers","deer"]', 3, 'Correct plural: deer (unchanged).', true, '2026-10-24 07:21:35.058', '2026-10-24 07:21:35.058', null, null, null, 'The adventurers ran into many <u>__________</u>', '["dear","dears","deers","deer"]', 'Correct plural: deer (unchanged).', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('67592e84-2b0b-4ab9-8133-3b43ef75b0c7', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Their new house was roofed with <u>corrugated</u> sheets.', null, '["folded","iron","aluminium","corrupted"]', 0, 'Corrugated = folded.', true, '2026-10-24 01:04:10.041', '2026-10-24 01:04:10.041', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Their new house was roofed with <u>corrugated</u> sheets.', '["<u>folded</u>","iron","aluminium","corrupted"]', '<b>Corrugated</b> = <b>folded</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6769495b-160a-4889-9787-9a78a35a744f', 'Chemistry', 'JAMB', null, 2026, null, 'Which of the following salts soluble in water', null, '["CaSO4","Na2CO3","PbCl2","AgCl"]', 1, 'All common sodium (Na+) salts, including sodium carbonate (Na2CO3), are completely soluble in water.', true, '2026-09-09 17:12:45.235', '2026-09-09 17:12:45.235', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('676a0c8f-c4b8-4853-8eeb-a35802c89860', 'English Language', 'JAMB', null, 2024, null, '32', null, '["neutralize","harmonize","settle","decide"]', 1, 'The market mechanism harmonizes the whims and caprice of both producer and consumer.', true, '2026-09-18 10:17:48.741', '2026-09-18 10:17:48.741', '01c7070a-0591-4cea-af06-fe54980dbb5f', 3, 'CLOZE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('677654bc-20ec-4a57-bdb9-ad94cbf3fe21', 'English Language', 'JAMB', null, 2007, null, 'The organisation established a scholarship scheme ....... talented students from disadvantaged backgrounds.', null, '["supporting","support","for support","to support"]', 3, 'Infinitive of purpose: ''to support''.', true, '2026-10-25 18:25:06.305', '2026-10-25 18:25:06.305', null, null, null, 'The organisation established a scholarship scheme ....... talented students from disadvantaged backgrounds.', '["supporting","support","for support","to support"]', 'Infinitive of purpose: ''to support''.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('678a1ab3-39c7-4ebf-a06f-4ee03cf372e3', 'Physics', 'JAMB', null, 1993, null, 'The external and internal diameters of a tube are measured as (32 ± 2) mm and (21 ± 1) mm respectively. Determine the percentage error in the thickness of the tube.', null, '["27%","14%","9%","3%"]', 0, 'Thickness = (32 - 21)/2 = 5.5 mm. The error in (D - d) is 2 + 1 = 3 mm out of 11 mm, so the percentage error = 3/11 x 100 ≈ 27%.', true, '2026-10-12 19:15:36.948', '2026-10-12 19:15:36.948', null, null, null, 'The external and internal diameters of a tube are measured as (32 ± 2) mm and (21 ± 1) mm respectively. Determine the percentage error in the thickness of the tube.', '["27%","14%","9%","3%"]', 'Thickness = (32 - 21)/2 = 5.5 mm. The error in (D - d) is 2 + 1 = 3 mm out of 11 mm, so the percentage error = 3/11 x 100 ≈ 27%.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('67960542-792e-4348-a992-028e9ffe75ec', 'Literature in English', 'JAMB', null, 2026, null, 'What is the central theme of the poem?', null, '["environmental degradation","historical atrocities","maritime exploration","technological advancement"]', 1, 'The central theme is historical atrocities.', true, '2026-09-12 11:10:59.547', '2026-09-12 11:10:59.547', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('67a21e67-605d-4b50-a402-7881418f8539', 'Biology', 'JAMB', null, 0, null, 'answer the question above ', 'https://res.cloudinary.com/kwi1uv0g/image/upload/v1791839667/questions/alblffouh5xsyxbpch7c.jpg', '["a","b","c","d"]', 1, 'This apparatus uses a bell jar (representing the thoracic cavity), a rubber sheet (representing the diaphragm), and balloons (representing the lungs) to demonstrate how volume and pressure changes brought about by the diaphragm drive the process of breathing (inspiration and expiration).', true, '2026-10-12 21:14:59.607', '2026-10-12 21:14:59.607', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('67b6157b-9de0-493d-ae31-cb8943e0964d', 'Physics', 'JAMB', null, 2026, null, 'A body starts from rest and moves with uniform acceleration of 6ms⁻². What distance does it cover in the third second?', null, '["15m","18m","27m","30m"]', 0, 'Distance in nth second = u + a(2n-1)/2 = 0 + 6(5)/2 = 15m.', true, '2026-09-10 10:56:45.9', '2026-09-10 10:56:45.9', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('67b9ff72-260e-473f-b897-0748daf6c6b9', 'Biology', 'JAMB', null, 2026, null, 'The hormone which regulates the amount of glucose in the blood is called', null, '["adrenaline","auxins","insulin","thyroxin"]', 2, 'Insulin is the hormone that regulates the amount of glucose in the blood. It is produced by the beta cells of the pancreas. Insulin lowers blood glucose levels by promoting glucose uptake by cells and glycogenesis (conversion of glucose to glycogen) in the liver. Adrenaline raises blood glucose levels in response to stress. Auxins are plant hormones. Thyroxine regulates metabolism. Insulin deficiency or resistance causes diabetes mellitus.', true, '2026-09-09 03:19:10.969', '2026-09-09 03:19:10.969', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('67c16575-47cd-45e6-88f8-ebb6cac3f4fb', 'English Language', 'JAMB', null, 2024, null, 'It is a large organ which has two ______.', null, '["parts","sections","kidneys","lobes"]', 3, 'The liver has two lobes.', true, '2026-09-18 09:43:02.832', '2026-09-18 09:43:02.832', null, null, 'CLOZE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('67c33aa3-06bd-422c-b1d2-3ca736a6cbed', 'Literature in English', 'JAMB', null, 2026, null, 'In the play, ''The marriage of Anansenwa'', Anansewa opposes her father''s matchmaking attempt, arguing that she won''t be sold like a', null, '["maid","parcel","goat","commodity"]', 3, 'She argues she won''t be sold like a commodity.', true, '2026-09-12 11:13:58.792', '2026-09-12 11:13:58.792', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('67d05862-3765-4f37-9b58-627ddffaea18', 'Biology', 'JAMB', null, 2003, null, 'If a nursing mother is not producing enough milk, her hormonal system is probably in deficient in', null, '["Prolactin","testosterone","thyroxin","insulin"]', 0, 'Prolactin is the primary pituitary hormone responsible for stimulating milk production in mothers.', true, '2026-10-12 20:05:10.114', '2026-10-12 20:05:10.114', null, null, null, 'If a nursing mother is not producing enough milk, her hormonal system is probably in deficient in', '["Prolactin","testosterone","thyroxin","insulin"]', 'Prolactin is the primary pituitary hormone responsible for stimulating milk production in mothers.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('67d59821-225b-4fc5-9391-f865f67ce248', 'Biology', 'JAMB', null, 2026, null, 'Yeast respires anaerobically to convert simple sugar to carbon (IV) oxide and', null, '["Alcohol","Acid","Oxygen","Water"]', 0, 'Yeast respires anaerobically to convert simple sugar to carbon dioxide and alcohol (ethanol). This is alcoholic fermentation, which is used in brewing, wine making, and bread making. In anaerobic respiration, yeast converts pyruvate to acetaldehyde and then to ethanol, regenerating NAD⁺ for glycolysis. Acid production is associated with lactic acid fermentation in animals. Oxygen and water are products of aerobic respiration. The ability of yeast to produce alcohol is economically important for food and beverage production.', true, '2026-09-09 03:19:03.583', '2026-09-09 03:19:03.583', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('67e0a384-6029-423b-a960-1b66a6d88267', 'Physics', 'JAMB', null, 2002, null, 'The electromagnetic wave that can produce a heating effect on the environment is', null, '["Gamma rays","X-rays","Ultraviolet rays","Infrared rays."]', 3, 'Infra-red radiation is absorbed by objects and warms them, so it is known as heat radiation.', true, '2026-10-12 19:15:54.244', '2026-10-12 19:15:54.244', null, null, null, 'The electromagnetic wave that can produce a heating effect on the environment is', '["Gamma rays","X-rays","Ultraviolet rays","Infrared rays."]', 'Infra-red radiation is absorbed by objects and warms them, so it is known as heat radiation.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('681f4725-514e-4d2c-82b3-f97d3ea51e2e', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The house-wife was <u>hard up</u> before the end of each month.', null, '["upset","penniless","borrowing","in no need"]', 3, 'Hard up = short of money; opposite = in no need.', true, '2026-10-24 07:21:11.774', '2026-10-24 07:21:11.774', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The house-wife was <u>hard up</u> before the end of each month.', '["upset","penniless","borrowing","in no need"]', 'Hard up = short of money; opposite = in no need.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('68222535-21ea-498d-bbc7-f36d93bdc2af', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. A number of people impersonating tax officials were <u>arraigned</u> before the Chief Magistrate this morning.', null, '["arranged","paraded","moved","brought"]', 3, 'Arraigned = brought before a court.', true, '2026-10-24 01:03:57.787', '2026-10-24 01:03:57.787', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. A number of people impersonating tax officials were <u>arraigned</u> before the Chief Magistrate this morning.', '["arranged","paraded","moved","<u>brought</u>"]', '<b>Arraigned</b> = <b>brought</b> before a court.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6826879c-ff9f-465c-a909-b0fdb3dfe64d', 'Literature in English', 'JAMB', null, 2026, null, 'The tone of the poem can best be described as', null, '["celebratory","nostalgic and reflective","humorous","indifferent"]', 1, 'The tone is nostalgic and reflective.', true, '2026-09-12 11:12:27.819', '2026-09-12 11:12:27.819', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('682b1474-f884-4b07-9913-e6bfba238790', 'Financial Accounting', 'UTME', null, 2001, null, 'Lubricating oil and spare parts of machinery are examples of', null, '["direct materials","indirect materials","indirect expenses","direct expenses"]', 1, 'Lubricating oil and spare parts of machinery are examples of indirect materials.', true, '2026-10-12 22:00:06.127', '2026-10-12 22:00:06.127', null, null, null, 'Lubricating oil and spare parts of machinery are examples of', '["direct materials","<b>indirect materials</b>","indirect expenses","direct expenses"]', 'Lubricating oil and spare parts of machinery are examples of <b>indirect materials</b>.', '{"bold":["indirect materials"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('683756dc-768f-41e8-a22e-99bbef09cada', 'Biology', 'JAMB', null, 2005, null, 'A test tube containing yeast in glucose solution was suspended in a covered conical flask containing alkaline pyrogallol. The bubbles of carbon (IV) oxide produced indicate that the yeast cells are', null, '["respiring in the absence of oxygen","liberating oxygen on their own","living and consuming oxygen","being killed by the alcohol produced"]', 0, 'Yeast cells are respiring in the absence of oxygen.', true, '2026-10-12 20:59:37.379', '2026-10-12 20:59:37.379', null, null, null, 'A test tube containing yeast in glucose solution was suspended in a covered conical flask containing alkaline pyrogallol. The bubbles of carbon (IV) oxide produced indicate that the yeast cells are', '["respiring in the absence of oxygen","liberating oxygen on their own","living and consuming oxygen","being killed by the alcohol produced"]', 'Yeast cells are respiring in the absence of oxygen.', '{"bold":["respiring in the absence of oxygen"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('68397af2-35f3-4bda-8f70-a7e0d697d493', 'Literature in English', 'JAMB', null, 2026, null, 'The juxtaposition of two contrasting ideas in a line of poetry is', null, '["euphemism","synecdoche","catharsis","oxymoron"]', 3, 'Oxymoron juxtaposes contrasting ideas.', true, '2026-09-12 11:06:33.038', '2026-09-12 11:06:33.038', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('683abd79-a4f6-4647-a0d7-572003abc51a', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Let us not indulge in <u>recrimination</u>.', null, '["unfounded allegation","counter-accusation","accusation","indictment"]', 1, 'Recrimination = counter-accusation.', true, '2026-10-24 01:04:03.866', '2026-10-24 01:04:03.866', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Let us not indulge in <u>recrimination</u>.', '["unfounded allegation","<u>counter-accusation</u>","accusation","indictment"]', '<b>Recrimination</b> = <b>counter-accusation</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('683c3926-b860-46d8-867c-e2dbd1680eb2', 'General Mathematics', 'JAMB', null, 2026, null, 'Find the solution of the equation x + 2√x - 8 = 0', null, '["(4,16)","(2,4)","(4,1)","(1,16)","(16,16)"]', 0, 'Let √x = y. y² + 2y - 8 = 0. (y+4)(y-2) = 0. y = 2. x = 4. The answer is (C) (4,1)? Wait, x = 4. The options are confusing. The answer is x = 4.', true, '2026-09-12 11:44:05.105', '2026-09-12 11:44:05.105', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6843d161-b10c-4b13-83b5-7f813dcfe1ed', 'Physics', 'JAMB', null, 1983, null, 'The difference of potential between the terminals of a cell is 2.2 volts. When a 4 ohm resistor is connected across the terminals of this cell, the potential difference is 2 volts. What is the internal resistance of the cell?', null, '["0.10 ohms","0.25 ohms","0.40 ohms","2.50 ohms","4.00 ohms"]', 2, 'Current I = 2/4 = 0.5 A. Lost volts = 2.2 - 2 = 0.2 V, so internal resistance r = 0.2/0.5 = 0.40 ohms.', true, '2026-10-12 19:15:17.599', '2026-10-12 19:15:17.599', null, null, null, 'The difference of potential between the terminals of a cell is 2.2 volts. When a 4 ohm resistor is connected across the terminals of this cell, the potential difference is 2 volts. What is the internal resistance of the cell?', '["0.10 ohms","0.25 ohms","0.40 ohms","2.50 ohms","4.00 ohms"]', 'Current I = 2/4 = 0.5 A. Lost volts = 2.2 - 2 = 0.2 V, so internal resistance r = 0.2/0.5 = 0.40 ohms.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('684998a1-cae7-4c4d-b7be-6e5eaadefe90', 'English Language', 'JAMB', null, 2007, null, 'The exercise presented us with a lot of problems but later it was all <u>__________</u> sailing', null, '["plain","smooth","rough","tough"]', 0, 'Correct idiom: plain sailing.', true, '2026-10-24 07:21:44.718', '2026-10-24 07:21:44.718', null, null, null, 'The exercise presented us with a lot of problems but later it was all <u>__________</u> sailing', '["plain","smooth","rough","tough"]', 'Correct idiom: plain sailing.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('684cc951-ce47-40ff-8d1b-a7bad238eb0e', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). Ramatu expressed her feelings <u>in no uncertain terms</u>.', null, '["She expressed it clearly and strongly","She expressed it secretly and courageously","She expressed it quickly and cautiously","She expressed it feebly and sickly"]', 0, '''In no uncertain terms'' = clearly and strongly.', true, '2026-10-24 01:02:09.82', '2026-10-24 01:02:09.82', null, null, null, '(Choose the most appropriate interpretation). Ramatu expressed her feelings <u>in no uncertain terms</u>.', '["<u>She expressed it clearly and strongly</u>","She expressed it secretly and courageously","She expressed it quickly and cautiously","She expressed it feebly and sickly"]', '''<b>In no uncertain terms</b>'' = <b>clearly and strongly</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('684d8e4e-ed5d-44b2-936e-bbe8d3cf06b5', 'Biology', 'JAMB', null, 2012, null, 'The water cycle is maintained mainly by', null, '["evaporation of water in the environment","evaporation and condensation of water in the environment","condensation of water in the environment","Transpiration and respiration in plants."]', 1, 'The water cycle is maintained by evaporation and condensation.', true, '2026-10-12 20:59:45.096', '2026-10-12 20:59:45.096', null, null, null, 'The water cycle is maintained mainly by', '["evaporation of water in the environment","evaporation and condensation of water in the environment","condensation of water in the environment","Transpiration and respiration in plants."]', 'The water cycle is maintained by evaporation and condensation.', '{"bold":["evaporation and condensation"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6855809d-48f9-4085-9494-8031f8253221', 'Literature in English', 'JAMB', null, 2026, null, '"Singing songs of sorrow is symbolic of sincere sympathy" illustrates', null, '["Assonance","Refrain","Alliteration","Anecdote"]', 2, '"Singing songs of sorrow is symbolic of sincere sympathy" illustrates alliteration. Alliteration is the repetition of initial consonant sounds in nearby words. Here, the ''s'' sound is repeated in ''Singing,'' ''songs,'' ''sorrow,'' ''symbolic,'' ''sincere,'' and ''sympathy.'' Assonance is vowel repetition, refrain is a repeated line, and anecdote is a short story.', true, '2026-09-10 10:47:10.309', '2026-09-10 10:47:10.309', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('685ee96b-71f3-45a5-bce4-f3e9e90ae962', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). <u>Be careful!</u> We are approaching the crossroads.', null, '["look up","watch out","look out","hold up","look in"]', 1, '''Watch out'' = be careful.', true, '2026-10-24 01:02:01.371', '2026-10-24 01:02:01.371', null, null, null, '(Choose the most appropriate interpretation). <u>Be careful!</u> We are approaching the crossroads.', '["look up","<u>watch out</u>","look out","hold up","look in"]', '''<b>Watch out</b>'' = <b>be careful</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('685fefd4-6696-4467-bf71-58f88459aa3c', 'Chemistry', 'JAMB', null, 2026, null, 'A mixture contains 3.2 g of oxygen gas and 4.0 g of methane. Which statement best explains why methane diffuses faster than oxygen at the same temperature and pressure?', null, '["Methane has a lower density","Methane has a smaller molecular mass","Methane molecules move randomly","Methane has weaker intermolecular forces"]', 1, 'According to Graham''s Law of Diffusion, gases with smaller relative molecular masses diffuse at faster rates than heavier gases.', true, '2026-09-09 17:12:47.702', '2026-09-09 17:12:47.702', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6865df7b-0a71-4708-8191-c4586dee2322', 'Physics', 'JAMB', null, 1991, null, 'An object moves with uniform speed round a circle. Its acceleration has', null, '["Constant magnitude and constant direction.","Constant magnitude and varying direction.","Varying magnitude and constant direction","Varying magnitude and varying direction."]', 1, 'The centripetal acceleration v²/r has constant magnitude but always points to the centre, so its direction keeps changing.', true, '2026-10-12 19:15:32.597', '2026-10-12 19:15:32.597', null, null, null, 'An object moves with uniform speed round a circle. Its acceleration has', '["Constant magnitude and constant direction.","Constant magnitude and varying direction.","Varying magnitude and constant direction","Varying magnitude and varying direction."]', 'The centripetal acceleration v<sup>2</sup>/r has constant magnitude but always points to the centre, so its direction keeps changing.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('68662659-21fd-4733-afb0-4fe46c22d782', 'Biology', 'JAMB', null, 2011, null, 'Which of the following can cause shrinkage of living cells?', null, '["Hypotonic solution","Isotonic solution","Deionized water","Hypertonic solution."]', 3, 'Hypertonic solution causes shrinkage of living cells.', true, '2026-10-12 20:59:42.002', '2026-10-12 20:59:42.002', null, null, null, 'Which of the following can cause shrinkage of living cells?', '["Hypotonic solution","Isotonic solution","Deionized water","Hypertonic solution."]', 'Hypertonic solution causes shrinkage of living cells.', '{"bold":["Hypertonic solution"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('68700342-5122-41eb-9aa5-41d4e7d6b83c', 'Physics', 'JAMB', null, 2002, null, 'A wheel and axle is used to raise a load of 500 N by the application of an effort of 250 N. If the radii of the wheel and the axle are 0.4 cm and 0.1 cm respectively, the efficiency of the machine is', null, '["50%","60%","20%","40%"]', 0, 'MA = 500/250 = 2. VR = 0.4/0.1 = 4. Efficiency = MA/VR x 100 = 2/4 x 100 = 50%.', true, '2026-10-12 19:15:53.053', '2026-10-12 19:15:53.053', null, null, null, 'A wheel and axle is used to raise a load of 500 N by the application of an effort of 250 N. If the radii of the wheel and the axle are 0.4 cm and 0.1 cm respectively, the efficiency of the machine is', '["50%","60%","20%","40%"]', 'MA = 500/250 = 2. VR = 0.4/0.1 = 4. Efficiency = MA/VR x 100 = 2/4 x 100 = 50%.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('68762db9-ca00-4979-8c26-e5e017b7eac5', 'Physics', 'JAMB', null, 1985, null, 'Which of the following statements is NOT correct?', null, '["A galvanometer can be converted to an ammeter with a different range by connecting a high resistance in series.","An electric current always produces a magnetic field","Maxwell''s screw rule states that if a corkscrew moves in the direction of the current, the hand turns in the direction of the lines of force.","Electromagnets are used in electric bells and telephone receivers.","The lines of force round a straight current carrying conductor are circular."]', 0, 'A galvanometer is converted into an ammeter by connecting a low-resistance shunt in parallel, not a high resistance in series.', true, '2026-10-12 19:15:22.39', '2026-10-12 19:15:22.39', null, null, null, 'Which of the following statements is <b>NOT</b> correct?', '["A galvanometer can be converted to an ammeter with a different range by connecting a high resistance in series.","An electric current always produces a magnetic field","Maxwell''s screw rule states that if a corkscrew moves in the direction of the current, the hand turns in the direction of the lines of force.","Electromagnets are used in electric bells and telephone receivers.","The lines of force round a straight current carrying conductor are circular."]', 'A galvanometer is converted into an ammeter by connecting a low-resistance shunt in parallel, not a high resistance in series.', '{"bold":["NOT"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('687f9aa9-1b6e-44ec-bfd2-7103fc749fda', 'English Language', 'JAMB', null, 2007, null, 'The effort made by the principal to get the students to be serious in their studies <u>--------</u>', null, '["are appreciated","will appreciate","is to appreciate","is appreciated"]', 3, 'Singular ''effort'' â†’ is appreciated.', true, '2026-10-24 01:02:12.952', '2026-10-24 01:02:12.952', null, null, null, 'The effort made by the principal to get the students to be serious in their studies <u>--------</u>', '["are appreciated","will appreciate","is to appreciate","<u>is appreciated</u>"]', 'Singular ''<b>effort</b>'' â†’ <b>is appreciated</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('688d9e63-31e1-48e8-a768-c3248820b306', 'English Language', 'JAMB', null, 2024, null, '______ bomb had earlier been defused', null, '["a life","an alive","a live","alive"]', 2, '"A live bomb" means a bomb that is still capable of exploding.', true, '2026-09-18 09:43:02.812', '2026-09-18 09:43:02.812', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('688f11c7-e44a-4c62-bbb3-7c55cc6ea3d1', 'Government', 'JAMB', null, 2026, null, 'One way by which the legislature checks the executive is by', null, '["Delaying the promotion of some Ministers","Ordering the dismissal of corrupt Minister","Withholding the salaries of some Ministers","Demanding the review of an executive action"]', 3, 'The legislature checks the executive by demanding review of executive actions.', true, '2026-09-12 11:24:20.708', '2026-09-12 11:24:20.708', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('68943fa8-1eed-4d78-8d40-0602cabba7d5', 'Literature in English', 'JAMB', null, 2026, null, 'A word or gesture which serves as a signal to an actor to do or say something is called', null, '["Reminder","Correction","Over-act","Cue"]', 3, 'A cue is a signal for an actor.', true, '2026-09-12 11:10:49.753', '2026-09-12 11:10:49.753', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6897485b-4784-4dd4-b321-2bed47074cb2', 'English Language', 'JAMB', null, 2007, null, 'He is one of those who <u>---</u> in my school.', null, '["teaches","is teaching","are teaching","teach"]', 3, '''Who'' â†’ those (plural) â†’ teach.', true, '2026-10-24 01:04:27.829', '2026-10-24 01:04:27.829', null, null, null, 'He is one of those who <u>---</u> in my school.', '["teaches","is teaching","are teaching","<u>teach</u>"]', '''<b>Who</b>'' â†’ <b>those</b> (plural) â†’ <b>teach</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('689786db-233b-428e-ba75-14a2ed058cbd', 'Physics', 'JAMB', null, 1995, null, 'A piece of wood floats inside water at room temperature with a fraction of it above the liquid surface. As the temperature of the water is raised, the part of the wood above the liquid surface will', null, '["Decrease because the density of water decreases with temperature.","Increase because the density of water decreases with temperature.","Decrease because the density of water increases with temperature","Increase because the density of water increases with temperature."]', 0, 'Heating lowers the density of water, so the wood has to displace more water to float. It sinks lower, and less of it is above the surface.', true, '2026-10-12 19:15:41.2', '2026-10-12 19:15:41.2', null, null, null, 'A piece of wood floats inside water at room temperature with a fraction of it above the liquid surface. As the temperature of the water is raised, the part of the wood above the liquid surface will', '["Decrease because the density of water decreases with temperature.","Increase because the density of water decreases with temperature.","Decrease because the density of water increases with temperature","Increase because the density of water increases with temperature."]', 'Heating lowers the density of water, so the wood has to displace more water to float. It sinks lower, and less of it is above the surface.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('689cffe3-158b-446c-8336-1a9c73812cf7', 'Physics', 'JAMB', null, 1983, null, 'Ripples on water are similar to light waves in that they both', null, '["Have the same wavelength","Are longitudinal","Cannot be reflected","Travel at the same speed","Can be refracted and diffracted."]', 4, 'Ripples and light are both transverse waves, so both can be reflected, refracted and diffracted. Their wavelengths and speeds are very different.', true, '2026-10-12 19:15:17.095', '2026-10-12 19:15:17.095', null, null, null, 'Ripples on water are similar to light waves in that they both', '["Have the same wavelength","Are longitudinal","Cannot be reflected","Travel at the same speed","Can be refracted and diffracted."]', 'Ripples and light are both transverse waves, so both can be reflected, refracted and diffracted. Their wavelengths and speeds are very different.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('689f59be-ed0f-4778-83db-be0084f4fed2', 'English Language', 'JAMB', null, 2007, null, 'Every programming language and software package <u>--------------</u> limitations.', null, '["have its","have their","has its","has their"]', 2, '''Everyâ€¦'' singular â†’ has its.', true, '2026-10-24 01:04:26.908', '2026-10-24 01:04:26.908', null, null, null, 'Every programming language and software package <u>--------------</u> limitations.', '["have its","have their","<u>has its</u>","has their"]', '''<b>Everyâ€¦</b>'' singular â†’ <b>has its</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('689fc73f-2683-47b6-904c-e2466cb20dc5', 'Physics', 'JAMB', null, 1999, null, 'A lead bullet of mass 0.05 kg is fired with a velocity of 200 m s⁻¹ into a lead block of mass 0.95 kg. Given that the lead block can move freely, the final kinetic energy after impact is', null, '["50 J","100 J","150 J","200 J"]', 0, 'Momentum is conserved: 0.05 x 200 = 1.0 x v, so v = 10 m s⁻¹. Final KE = ½ x 1.0 x 10² = 50 J.', true, '2026-10-12 19:15:47.02', '2026-10-12 19:15:47.02', null, null, null, 'A lead bullet of mass 0.05 kg is fired with a velocity of 200 m s<sup>-1</sup> into a lead block of mass 0.95 kg. Given that the lead block can move freely, the final kinetic energy after impact is', '["50 J","100 J","150 J","200 J"]', 'Momentum is conserved: 0.05 x 200 = 1.0 x v, so v = 10 m s<sup>-1</sup>. Final KE = ½ x 1.0 x 10<sup>2</sup> = 50 J.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('68a204b5-bc9f-4e37-b81b-8901aef988f2', 'Physics', 'JAMB', null, 2000, null, 'An engineer intends to deviate a light ray from its path by 120° through reflection from a plane mirror. Calculate the angle of incidence.', null, '["20°","30°","40°","60°"]', 1, 'Deviation on reflection = 180° - 2i. So 120° = 180° - 2i and i = 30°.', true, '2026-10-12 19:15:49.428', '2026-10-12 19:15:49.428', null, null, null, 'An engineer intends to deviate a light ray from its path by 120° through reflection from a plane mirror. Calculate the angle of incidence.', '["20°","30°","40°","60°"]', 'Deviation on reflection = 180° - 2i. So 120° = 180° - 2i and i = 30°.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('68a680a9-aa13-4637-8c65-486edc2c62aa', 'Physics', 'JAMB', null, 1987, null, 'Isotopes are nuclei which have', null, '["The same number of neutrons and electrons","Equal number of electrons and protons","The same atomic number but different number of neutrons","The same number of total particles."]', 2, 'Isotopes of an element have the same number of protons (atomic number) but different numbers of neutrons.', true, '2026-10-12 19:15:26.674', '2026-10-12 19:15:26.674', null, null, null, 'Isotopes are nuclei which have', '["The same number of neutrons and electrons","Equal number of electrons and protons","The same atomic number but different number of neutrons","The same number of total particles."]', 'Isotopes of an element have the same number of protons (atomic number) but different numbers of neutrons.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('68b8d7ee-8dca-4a6d-9687-d4074237093e', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. From what she said, one may <u>infer</u> that she does not like the course.', null, '["suppose","realize","deduce","agree"]', 2, 'Infer = deduce.', true, '2026-10-24 01:01:52.517', '2026-10-24 01:01:52.517', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. From what she said, one may <u>infer</u> that she does not like the course.', '["suppose","realize","<u>deduce</u>","agree"]', '<b>Infer</b> = <b>deduce</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('68c1d1e0-3e2e-4eae-bd71-0af9ca1db36c', 'General Mathematics', 'JAMB', null, 2026, null, 'Evaluate 1+2+3+4+5+6+…..100', null, '["5550","5050","5500","5000"]', 1, 'The sum of the first n natural numbers is given by n(n+1)/2. For n = 100: Sum = 100 × 101 / 2 = 10100 / 2 = 5050.', true, '2026-09-10 10:48:18.306', '2026-09-10 10:48:18.306', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('68d061df-a3dc-4156-a5ce-716d7ba73ead', 'English Language', 'JAMB', null, 2007, null, 'A sterile range of mountains, broken at intervals by deep ravines <u>-----------</u> the whole of this small state.', null, '["enclose","encloses","cover","covers"]', 1, 'Singular ''range'' â†’ encloses.', true, '2026-10-24 01:02:14.403', '2026-10-24 01:02:14.403', null, null, null, 'A sterile range of mountains, broken at intervals by deep ravines <u>-----------</u> the whole of this small state.', '["enclose","<u>encloses</u>","cover","covers"]', 'Singular ''<b>range</b>'' â†’ <b>encloses</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('68d59426-50ea-410f-8945-8b3ff7d7d2f6', 'General Mathematics', 'JAMB', null, 2026, null, 'A boy walks 6km from a point P to a point Q on a bearing of 065°. He then walks to a point R, a distance of 13km, on a bearing of 146°. Calculate correct to the nearest kilometer, the distance PR', null, '["16km","15.15 km","17km","12.4km","15km"]', 2, 'Using cosine rule: PR² = 6² + 13² - 2(6)(13)cos(146-65) = 36 + 169 - 156cos81° = 205 - 156(0.1564) = 205 - 24.4 = 180.6. PR = 13.4 km. The closest is 12.4km.', true, '2026-09-12 11:43:45.101', '2026-09-12 11:43:45.101', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('68e66b45-0e59-4b0c-86dd-1ff12f2003e3', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The ruler expects full <u>allegiance</u> from his subjects at all times.', null, '["obedience","homage","disloyalty","disapproval"]', 2, 'Allegiance = loyalty; opposite = disloyalty.', true, '2026-10-24 07:21:16.893', '2026-10-24 07:21:16.893', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The ruler expects full <u>allegiance</u> from his subjects at all times.', '["obedience","homage","disloyalty","disapproval"]', 'Allegiance = loyalty; opposite = disloyalty.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('68ebd3c4-4f96-4389-a2b1-0e945efd1514', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'What was the consequence for those who disobeyed Moses by going to gather manna on the Sabbath day?', null, '["the manna melted in the pot","they could not find any","they were bitten by snakes","the manna grew worms"]', 1, 'Those who disobeyed Moses by going to gather manna on the Sabbath day could not find any. God had commanded that no manna would fall on the Sabbath, and those who went out to gather found none.', true, '2026-09-12 09:46:10.501', '2026-09-12 09:46:10.501', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('68f67e84-96a8-4809-8cfb-e7dec7345531', 'English Language', 'JAMB', null, 2007, null, 'The researcher, ..... findings challenged the accepted theory, received an international award', null, '["who","whom","which","whose"]', 3, 'Possessive relative pronoun ''whose''.', true, '2026-10-25 18:25:06.252', '2026-10-25 18:25:06.252', null, null, null, 'The researcher, ..... findings challenged the accepted theory, received an international award', '["who","whom","which","whose"]', 'Possessive relative pronoun ''whose''.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6906ab1f-4ce6-4708-88c9-05875691048e', 'General Mathematics', 'JAMB', null, 2026, null, 'A rectangular picture 6cm by 8cm is enclosed by a frame 1/2cm wide. Calculate the area of the frame.', null, '["15sq.cm","20sq.cm","13sq.cm","16sq.cm","17sq.cm"]', 0, 'Outer dimensions = (6+1) by (8+1) = 7cm by 9cm. Area of frame = (7×9) - (6×8) = 63 - 48 = 15 sq.cm.', true, '2026-09-10 10:48:18.897', '2026-09-10 10:48:18.897', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6910ccd5-9f1b-4674-8206-c0e8ca76557c', 'General Mathematics', 'JAMB', null, 2026, null, 'Given log 2 = 0.69, log 3 = 1.10 and log 7 = 1.90 all to a fixed base, find log 10.5 to the same base, without using tables', null, '["1.03","2.31","3.69","10.5","1.69"]', 1, 'log 10.5 = log(21/2) = log 21 - log 2 = log 3 + log 7 - log 2 = 1.10 + 1.90 - 0.69 = 2.31.', true, '2026-09-12 11:44:23.524', '2026-09-12 11:44:23.524', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('691a9726-9ad9-42ed-a2aa-e4a5114684f1', 'Physics', 'JAMB', null, 2026, null, 'If the decay constant of a radioactive substance is 0.231s⁻¹, the half life is', null, '["3s","0.12s","0.33s","1.50s"]', 0, 'Half-life T½ = ln2/λ = 0.693/0.231 = 3s.', true, '2026-09-10 10:56:40.435', '2026-09-10 10:56:40.435', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('692333e4-98bb-48b5-a2d8-c04526db2ff8', 'General Mathematics', 'JAMB', null, 2026, null, 'Find the remainder when the polynomial f(x) = 3x³ + x² - 8x + 4 is divided by x + 2', null, '["0","-2","2","1"]', 0, 'f(-2) = 3(-8) + 4 + 16 + 4 = -24+4+16+4 = 0.', true, '2026-09-12 11:44:02.045', '2026-09-12 11:44:02.045', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6924b8e2-140d-4316-8c45-c23eba24ce6c', 'Yoruba', 'JAMB', null, 2007, null, 'Ìwé Iyán Ogún Òdún ni ìbéèrè 38-40 dá lé. Ta ni ó dábàà Ifábùnmi fún oyè Balógun?', null, '["Àró","Òdòfin","Òba","Ògúnlérè"]', 3, 'Ògúnlérè ni ó dábàà Ifábùnmi fún oyè Balógun.', true, '2026-10-13 13:23:32.504', '2026-10-13 13:23:32.504', null, null, null, 'Ìwé Iyán Ogún Òdún ni ìbéèrè 38-40 dá lé. Ta ni ó dábàà Ifábùnmi fún oyè Balógun?', '["Àró","Òdòfin","Òba","Ògúnlérè"]', 'Ògúnlérè ni ó dábàà Ifábùnmi fún oyè Balógun.', '{"bold":["Ògúnlérè"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('69265d6b-536b-4323-85a5-be8a82949261', 'Biology', 'JAMB', null, 2026, null, 'In flowers, the terminal part of a stamen containing the pollen sacs is known as the', null, '["filament","pistil","anther","style"]', 2, 'The anther is the part of the stamen that produces and contains pollen grains.', true, '2026-09-09 02:56:43.729', '2026-09-09 02:56:43.729', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('692b4a8f-add2-43dc-afc7-efffab5619dd', 'Financial Accounting', 'UTME', null, 2001, null, 'A club received rent N10, 000 and donation N30, 000. It paid N6, 000 for entertainment and is still owing N16, 000. The balance of the receipts and payments account is', null, '["N24,000","N22,000","N14,000","N8,000"]', 0, 'Balance = Rent 10,000 + Donation 30,000 - Entertainment 6,000 - Owing 16,000 = 18,000. Wait, the answer is N24,000.', true, '2026-10-12 22:00:06.516', '2026-10-12 22:00:06.516', null, null, null, 'A club received rent N10, 000 and donation N30, 000. It paid N6, 000 for entertainment and is still owing N16, 000. The balance of the receipts and payments account is', '["<b>N24,000</b>","N22,000","N14,000","N8,000"]', 'Balance = Rent 10,000 + Donation 30,000 - Entertainment 6,000 - Owing 16,000 = <b>N24,000</b>.', '{"bold":["N24,000"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('69345b51-dd24-4c3b-8425-4f6018ad4119', 'Literature in English', 'JAMB', null, 2026, null, 'The term ''catharsis'' refers to', null, '["emotional purification","comic relief","tragic flaw","irony"]', 0, 'Catharsis is emotional purification.', true, '2026-09-12 11:11:23.443', '2026-09-12 11:11:23.443', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('69426c4a-bb5f-48a8-a1db-cc05264dd411', 'Biology', 'JAMB', null, 2026, null, 'Both recessive and dominant characters are found', null, '["on different chromosomes in the cell","at the same locus of a homologous chromosome","mother''s sex cell","mother''s X chromosome"]', 1, 'Both recessive and dominant characters are found at the same locus (position) of a homologous chromosome pair. Homologous chromosomes have genes for the same traits at the same loci. These genes can be in different forms (alleles), which may be dominant or recessive. This is the basis of Mendelian inheritance. The expression of a trait depends on which alleles are present at these loci.', true, '2026-09-09 03:19:28.951', '2026-09-09 03:19:28.951', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('695ad3f5-a95b-4d69-861a-feb0d294d55d', 'Financial Accounting', 'UTME', null, 2004, null, 'A sole trader provides the following balance for the financial year ended 30th June, 2003. The capital employed is', 'https://res.cloudinary.com/kwi1uv0g/image/upload/v1791841704/questions/oyxfejtczhqxb4kaop2f.jpg', '["N13 000","N9 900","N9 000","N8 400"]', 2, 'The capital employed is N9,000.', true, '2026-10-12 22:00:02.247', '2026-10-12 22:00:02.247', null, null, null, 'A sole trader provides the following balance for the financial year ended 30th June, 2003. The capital employed is', '["N13 000","N9 900","<b>N9 000</b>","N8 400"]', 'The capital employed is <b>N9,000</b>.', '{"bold":["N9,000"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('695e22a2-946c-4939-9c04-bbbf92170678', 'Biology', 'JAMB', null, 2011, null, 'The path followed by air as it passes through the lungs in mammals is', null, '["trachea - bronchi - bronchioles - alveoli","bronchi - trachea - alveoli - bronchioles","trachea - bronchioles - bronchi - alveoli.","bronchioles - alveoli - bronchi - trachea."]', 0, 'The correct path is trachea - bronchi - bronchioles - alveoli.', true, '2026-10-12 20:59:42.509', '2026-10-12 20:59:42.509', null, null, null, 'The path followed by air as it passes through the lungs in mammals is', '["trachea - bronchi - bronchioles - alveoli","bronchi - trachea - alveoli - bronchioles","trachea - bronchioles - bronchi - alveoli.","bronchioles - alveoli - bronchi - trachea."]', 'The correct path is trachea - bronchi - bronchioles - alveoli.', '{"bold":["trachea - bronchi - bronchioles - alveoli"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('696b8901-4181-4661-8754-94bfd2b56fa3', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Moses was nursed by', null, '["Pharaoh''s daughter","his mother","Shiphrah","Puah"]', 1, 'Moses was nursed by his own mother.', true, '2026-09-12 10:41:36.086', '2026-09-12 10:41:36.086', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6971e7e3-cab5-4da0-8d7c-8f642549b44b', 'Literature in English', 'JAMB', null, 2026, null, 'The poem can be classified as a work of', null, '["Romanticism","Imagism","Magical Realism","Postcolonial literature"]', 3, 'The poem is postcolonial literature.', true, '2026-09-12 11:13:57.253', '2026-09-12 11:13:57.253', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('69748627-d267-4b40-a2e6-997ec5b0948f', 'Literature in English', 'JAMB', null, 2026, null, 'Dramatic irony occurs when', null, '["audience knows more than characters","characters know everything","narrator is unreliable","conflict is resolved"]', 0, 'Dramatic irony occurs when the audience knows more than characters.', true, '2026-09-12 11:11:23.673', '2026-09-12 11:11:23.673', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('697653f7-4425-4bfc-9ca0-6eab6643c0be', 'Chemistry', 'JAMB', null, 2026, null, '10cm³ of Hydrogen was sparkled with 10cm³ of oxygen at STP. Calculate the volume of the unreacted gas.', null, '["15cm³","20cm³","5cm³","10cm³"]', 2, '2H₂ + O₂ → 2H₂O. 10 cm³ H₂ reacts with 5 cm³ O₂. Unreacted O₂ = 10 - 5 = 5 cm³.', true, '2026-09-12 11:36:27.515', '2026-09-12 11:36:27.515', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('69894341-7d5e-4fdd-831c-0e1bd9850e55', 'English Language', 'JAMB', null, 2007, null, 'Half of the mangoes in the basket <u>______</u> rotten.', null, '["is","was","are","has been"]', 2, 'Plural ''mangoes'' â†’ are.', true, '2026-10-24 01:02:16.323', '2026-10-24 01:02:16.323', null, null, null, 'Half of the mangoes in the basket <u>______</u> rotten.', '["is","was","<u>are</u>","has been"]', 'Plural ''<b>mangoes</b>'' â†’ <b>are</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6989dc9b-e3f5-403d-97e0-7ec69d8932e7', 'Physics', 'JAMB', null, 1983, null, 'Which of the following statements about friction is NOT correct?', null, '["The force of kinetic friction is less than the force of static friction.","The force of kinetic friction between two surfaces is independent of the areas in contact provided the normal reaction is unchanged.","The force of rolling friction between two surfaces is less than the force of sliding friction.","The angle of friction is the angle between the normal reaction and the force of friction.","Friction may be reduced by lubrication."]', 3, 'The friction force acts along the surface, at 90° to the normal reaction. The angle of friction is actually the angle between the normal reaction and the resultant of the normal reaction and the limiting friction, so statement D is the incorrect one.', true, '2026-10-12 19:15:15.717', '2026-10-12 19:15:15.717', null, null, null, 'Which of the following statements about friction is <b>NOT</b> correct?', '["The force of kinetic friction is less than the force of static friction.","The force of kinetic friction between two surfaces is independent of the areas in contact provided the normal reaction is unchanged.","The force of rolling friction between two surfaces is less than the force of sliding friction.","The angle of friction is the angle between the normal reaction and the force of friction.","Friction may be reduced by lubrication."]', 'The friction force acts along the surface, at 90° to the normal reaction. The angle of friction is actually the angle between the normal reaction and the resultant of the normal reaction and the limiting friction, so statement D is the incorrect one.', '{"bold":["NOT"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('698ea4ae-34bd-4bc3-8ddb-ccad6f1d85fc', 'Literature in English', 'JAMB', null, 2026, null, 'The rhyme scheme of the first stanza is', null, '["Aabb","Abab","Abcd","Abba"]', 1, 'The rhyme scheme of the first stanza is ABAB. The first line rhymes with the third line (''sacks'' and ''backs''), and the second line rhymes with the fourth line (''sludge'' and ''trudge''). This alternating rhyme scheme is common in English poetry. AABB is couplet rhyme, ABCD is no rhyme, and ABBA is enclosed rhyme.', true, '2026-09-10 10:47:10.211', '2026-09-10 10:47:10.211', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('699b0b2f-1d7e-4bd2-981c-75d3b07e8bc0', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Lantana <u>dwelt</u> in a ruined cottage on the hillside.', null, '["sat","worked","slept","lived"]', 3, 'Dwelt = lived.', true, '2026-10-24 01:01:57.445', '2026-10-24 01:01:57.445', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Lantana <u>dwelt</u> in a ruined cottage on the hillside.', '["sat","worked","slept","<u>lived</u>"]', '<b>Dwelt</b> = <b>lived</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('69a51c31-c418-4b84-837f-992225d193cc', 'English Language', 'JAMB', null, 2024, null, '9', null, '["general","proper","genuine","good"]', 2, 'A genuine grievance is a real and justified complaint.', true, '2026-09-18 10:17:48.789', '2026-09-18 10:17:48.789', '274e150d-fca1-4c72-9c33-e5e119534874', 9, 'CLOZE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('69a9d8cd-b89c-4992-a98b-3dc4d179cb46', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'The name of Sarah’s Egyptian maid was...', null, '["Haggai","Haggar","Hagar","Aggar"]', 2, 'Genesis 16:1 identifies Sarai''s Egyptian maidservant as Hagar.', true, '2026-09-09 17:18:25.09', '2026-09-09 17:18:25.09', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('69abc1e1-f8b8-45a7-a240-00e62859b31d', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The demonstrators have refused to <u>call off</u> their action.', null, '["consolidate","start","resume","end"]', 1, 'Call off = end; opposite = start.', true, '2026-10-24 07:21:12.801', '2026-10-24 07:21:12.801', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The demonstrators have refused to <u>call off</u> their action.', '["consolidate","start","resume","end"]', 'Call off = end; opposite = start.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('69b82bde-2d04-4e25-a187-4c8071eec7f1', 'Economics', 'JAMB', null, 2026, null, 'Which of these is not one of the reasons for population census?', null, '["To know the population size","For revenue estimates","To forecast future economic needs","To waste resources of the country"]', 3, 'Census is not conducted to waste resources.', true, '2026-09-12 11:00:57.364', '2026-09-12 11:00:57.364', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('69c5420a-21d9-47fb-b9de-eefb427e6c26', 'Literature in English', 'JAMB', null, 2026, null, 'The dominant literary device in New Tongue is', null, '["Symbolism","Irony","Euphemism","Hyperbole"]', 0, 'The dominant device is symbolism.', true, '2026-09-12 11:12:05.691', '2026-09-12 11:12:05.691', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('69c58d13-4990-4294-b4d9-a252e66d7d4d', 'Financial Accounting', 'UTME', null, 2001, null, 'The main difference between the ordinary and preference shareholders is that', null, '["the former receive dividends while the latter do not","the latter are not members of the company while the former are","in the case of winding up, the former are paid first before the latter","the former have voting rights while the latter do not"]', 3, 'The main difference is that the former (ordinary shareholders) have voting rights while the latter (preference shareholders) do not.', true, '2026-10-12 22:00:07.435', '2026-10-12 22:00:07.435', null, null, null, 'The main difference between the ordinary and preference shareholders is that', '["the former receive dividends while the latter do not","the latter are not members of the company while the former are","in the case of winding up, the former are paid first before the latter","<b>the former have voting rights while the latter do not</b>"]', 'The main difference is that the <b>former (ordinary shareholders) have voting rights while the latter (preference shareholders) do not</b>.', '{"bold":["former (ordinary shareholders) have voting rights while the latter (preference shareholders) do not"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('69cc0296-baae-4f8c-8891-2752f4ca2853', 'English Language', 'JAMB', null, 2024, null, 'Please, I want my own Biology notebook, and', null, '["nobody else''s","nobody''s else","nobody''s else''s","nobody else''"]', 0, '"Nobody else''s" is the correct possessive form.', true, '2026-09-18 09:23:08.267', '2026-09-18 09:23:08.267', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('69ce0171-2ec9-4dcb-b7d8-e64cbbfad978', 'Literature in English', 'JAMB', null, 2026, null, 'Sludge in the extract means', null, '["Water","Fire","Snow","Mud"]', 3, 'Sludge in the extract means mud. In the context of the poem, soldiers are described as ''cursing through sludge,'' which refers to thick, muddy ground typical of trench warfare. The word ''sludge'' specifically means thick, soft mud or sediment. It is not water, fire, or snow. The muddy conditions added to the soldiers'' misery and difficulty in movement.', true, '2026-09-10 10:47:10.259', '2026-09-10 10:47:10.259', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('69dbb6b6-b425-4786-b5ff-d63900d96ccf', 'Biology', 'JAMB', null, 2003, null, 'If water that has been coloured red is poured at the base of a wilting plant, it will appear as a red stain in the cell of the', null, '["xylem","epidermis","phloem","parenchyma"]', 0, 'Water and dissolved minerals travel upward through the xylem tissues, staining them.', true, '2026-10-12 20:05:09.55', '2026-10-12 20:05:09.55', null, null, null, 'If water that has been coloured red is poured at the base of a wilting plant, it will appear as a red stain in the cell of the', '["xylem","epidermis","phloem","parenchyma"]', 'Water and dissolved minerals travel upward through the xylem tissues, staining them.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('69ede2d7-e216-44e7-8c51-638ac50b49e6', 'General Mathematics', 'JAMB', null, 2026, null, 'A sum of money becomes #3,600 in 2 years and #4,800 in 5 years at simple interest. Find the principal.', null, '["#3,200","#2,400","#2,800","#3,000"]', 3, 'Interest for 3 years = 4800-3600 = 1200. Interest per year = 400. Principal + 2(400) = 3600. Principal = 2800. The answer is (C) #2,800.', true, '2026-09-12 11:43:52.983', '2026-09-12 11:43:52.983', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6a02a8cd-db29-48c9-94e1-96d44e93d4b8', 'Biology', 'JAMB', null, 2002, null, 'The mode of nutrition exhibited by a tapeworm is', null, '["symbiotic","saprophytic","parasitic","holozoic"]', 2, 'Tapeworms are parasitic.', true, '2026-10-12 20:59:31.421', '2026-10-12 20:59:31.421', null, null, null, 'The mode of nutrition exhibited by a tapeworm is', '["symbiotic","saprophytic","parasitic","holozoic"]', 'Tapeworms are parasitic.', '{"bold":["parasitic"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6a042f05-f8b2-427a-b9f8-4e52d8fa5626', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Oisa <u>hoodwinked</u> the men into buying and selling.', null, '["prevent","improve","promote","worsen"]', 0, 'Garbled source; closest = prevent (deceived).', true, '2026-10-24 01:04:11.331', '2026-10-24 01:04:11.331', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Oisa <u>hoodwinked</u> the men into buying and selling.', '["<u>prevent</u>","improve","promote","worsen"]', '<b>Garbled source</b>; closest = <b>prevent</b> (deceived).', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6a16320e-177c-42f5-a94b-8e69a639422f', 'Literature in English', 'JAMB', null, 2026, null, 'When a story is told in a song and passed down by word of mouth, it is called', null, '["A sonnet","An epic","a ballad","A singer''s story"]', 2, 'When a story is told in a song and passed down by word of mouth, it is called a ballad. Ballads are narrative poems or songs that tell a story, often of love, adventure, or tragedy. They were traditionally passed down orally from generation to generation. A sonnet is a 14-line poem, an epic is a long narrative poem, and a singer''s story is not a standard literary term.', true, '2026-09-10 10:47:10.655', '2026-09-10 10:47:10.655', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6a36be03-2193-44d8-b2a7-8db88a4190d0', 'English Language', 'JAMB', null, 2007, null, 'Simbi <u>------------</u> novels since she came home.', null, '["is reading","had been reading","has read","has been reading"]', 3, '''Since'' + ongoing â†’ present perfect continuous.', true, '2026-10-24 01:04:26.857', '2026-10-24 01:04:26.857', null, null, null, 'Simbi <u>------------</u> novels since she came home.', '["is reading","had been reading","has read","<u>has been reading</u>"]', '''<b>Since</b>'' + ongoing â†’ present perfect continuous.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6a3f80cd-0dab-49e3-92bb-e532174c2b57', 'Biology', 'JAMB', null, 2026, null, 'The spinal cord serve as the centre of', null, '["subconscious thought","reflex action","habits","tropisms","synapse"]', 1, 'The spinal cord serves as the center for reflex actions. Reflex actions are rapid, automatic, involuntary responses to stimuli that do not require conscious brain involvement. The spinal cord contains reflex arcs where sensory neurons connect directly to motor neurons via interneurons, allowing quick responses. Subconscious thought and habits involve the brain (cerebrum and cerebellum). Tropisms are plant growth responses, not animal spinal cord functions. A synapse is the junction between neurons, not a center of the spinal cord.', true, '2026-09-09 03:18:28.61', '2026-09-09 03:18:28.61', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6a4a7d1b-475d-4e07-8c29-aa00e06c530a', 'English Language', 'JAMB', null, 2007, null, 'Neither Agbo nor his parents <u>------------</u> the meetings now.', null, '["has attended","attend","attends","attended"]', 1, 'Nearest subject ''parents'' (plural) â†’ attend.', true, '2026-10-24 01:04:25.635', '2026-10-24 01:04:25.635', null, null, null, 'Neither Agbo nor his parents <u>------------</u> the meetings now.', '["has attended","<u>attend</u>","attends","attended"]', 'Nearest subject ''<b>parents</b>'' (plural) â†’ <b>attend</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6a609400-f2ad-41aa-9485-430acb80a82e', 'Literature in English', 'JAMB', null, 2026, null, 'The setting of the stage entails', null, '["a bare room with cushioned table and chair","a bare room with a small table and chair","a room with typewriter, table and two chairs","a spacious room with necessary home appliances"]', 2, 'The setting is a room with a typewriter, table, and two chairs.', true, '2026-09-12 11:05:31.761', '2026-09-12 11:05:31.761', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6a6324db-3c63-4bfc-bb18-bf68e994352d', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Mr. Dzokoto plays the piano with great <u>dexterity</u>.', null, '["wisdom","power","force","skill"]', 3, 'Dexterity = skill.', true, '2026-10-24 01:04:01.567', '2026-10-24 01:04:01.567', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Mr. Dzokoto plays the piano with great <u>dexterity</u>.', '["wisdom","power","force","<u>skill</u>"]', '<b>Dexterity</b> = <b>skill</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6a6846f8-66c3-434e-bb18-ca9f0b5cf670', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. If your life is in <u>turmoil</u> always take courage.', null, '["devastation","crisis","trial","tragedy"]', 1, 'Turmoil = crisis/confusion.', true, '2026-10-24 01:03:58.403', '2026-10-24 01:03:58.403', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. If your life is in <u>turmoil</u> always take courage.', '["devastation","<u>crisis</u>","trial","tragedy"]', '<b>Turmoil</b> = <b>crisis</b>/confusion.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6a73f849-b209-443b-bf33-aa594bab10d8', 'Chemistry', 'JAMB', null, 2026, null, 'Mg(s) + 2HCl(aq) → MgCl2(aq) + H2(g) From the equation above, the mass of magnesium required to react with 250cm3 of 0.5M HCl is [Mg = 24]', null, '["0.3g","1.5g","2.4g","3.0g"]', 1, 'Moles HCl = 0.250 * 0.5 = 0.125 mol. Moles Mg needed = 0.125 / 2 = 0.0625 mol. Mass Mg = 0.0625 * 24 = 1.5 g.', true, '2026-09-09 17:12:47.501', '2026-09-09 17:12:47.501', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6a7dc4ae-f5c9-4676-9936-44759f28aa21', 'English Language', 'JAMB', null, 2007, null, 'Watching carefully, I could see the fish <u>__________</u> along the bottom', null, '["doting","crawling","diving","darting"]', 3, 'Correct spelling: darting.', true, '2026-10-24 07:21:45.02', '2026-10-24 07:21:45.02', null, null, null, 'Watching carefully, I could see the fish <u>__________</u> along the bottom', '["doting","crawling","diving","darting"]', 'Correct spelling: darting.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6a917e1d-9ef8-4497-a791-d0eb34ed44fd', 'Literature in English', 'JAMB', null, 2026, null, 'The phrase poetic walking at the end of the poem refers to', null, '["the celebrant''s slow movement","a unique, graceful way of living","a poet''s literal walk","a march in protest"]', 1, 'It refers to a unique, graceful way of living.', true, '2026-09-12 11:10:58.154', '2026-09-12 11:10:58.154', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6a99f790-9aa1-4d66-bcd4-4413354ef8ea', 'Physics', 'JAMB', null, 1983, null, 'A ship travelling towards a cliff receives the echo of its whistle after 3.5 seconds. A short while later, it receives the echo after 2.5 seconds. If the speed of sound in air under the prevailing conditions is 250 m s⁻¹, how much closer is the ship to the cliff?', null, '["10 m","125 m","175 m","350 m","1,000 m"]', 1, 'Distance to cliff = (speed x time)/2. First: (250 x 3.5)/2 = 437.5 m. Second: (250 x 2.5)/2 = 312.5 m. The ship is 437.5 - 312.5 = 125 m closer.', true, '2026-10-12 19:15:16.494', '2026-10-12 19:15:16.494', null, null, null, 'A ship travelling towards a cliff receives the echo of its whistle after 3.5 seconds. A short while later, it receives the echo after 2.5 seconds. If the speed of sound in air under the prevailing conditions is 250 m s<sup>-1</sup>, how much closer is the ship to the cliff?', '["10 m","125 m","175 m","350 m","1,000 m"]', 'Distance to cliff = (speed x time)/2. First: (250 x 3.5)/2 = 437.5 m. Second: (250 x 2.5)/2 = 312.5 m. The ship is 437.5 - 312.5 = 125 m closer.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6aa0c889-4422-466f-b934-51a1b1c94ac7', 'English Language', 'JAMB', null, 2007, null, 'The freed robber expressed his gratitude in a <u>__________</u> prayer of thanksgiving', null, '["spurious","spasmodic","spontaneous","sporadic"]', 2, 'Correct spelling: spontaneous.', true, '2026-10-24 07:21:45.122', '2026-10-24 07:21:45.122', null, null, null, 'The freed robber expressed his gratitude in a <u>__________</u> prayer of thanksgiving', '["spurious","spasmodic","spontaneous","sporadic"]', 'Correct spelling: spontaneous.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6aa8fb2a-2281-496a-ae46-f55005792778', 'Literature in English', 'JAMB', null, 2026, null, 'In the line: ''Golden rays danced upon the trembling sea,'' which imagery is most dominant?', null, '["Auditory","Visual","Tactile","Olfactory"]', 1, 'Visual imagery is most dominant.', true, '2026-09-12 11:14:17.699', '2026-09-12 11:14:17.699', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6aae9d08-dcf0-47ed-a58a-b3dac889881f', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The culprit <u>unwittingly</u> subjected himself to great humiliation.', null, '["cunningly","curiously","foolishly","subtly"]', 0, 'Unwittingly = unintentionally; opposite = cunningly.', true, '2026-10-24 07:21:16.69', '2026-10-24 07:21:16.69', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The culprit <u>unwittingly</u> subjected himself to great humiliation.', '["cunningly","curiously","foolishly","subtly"]', 'Unwittingly = unintentionally; opposite = cunningly.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6ab3d691-07a0-4060-9861-69238e4f9f62', 'Biology', 'JAMB', null, 2003, null, 'In the egg of a bird, the embryo is located in the', null, '["chalaza","yolk","albUTMEn","embryo disc"]', 3, 'The embryo develops directly from the germinal disc (embryo disc) located on the yolk surface.', true, '2026-10-12 20:05:09.151', '2026-10-12 20:05:09.151', null, null, null, 'In the egg of a bird, the embryo is located in the', '["chalaza","yolk","albUTMEn","embryo disc"]', 'The embryo develops directly from the germinal disc (embryo disc) located on the yolk surface.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6ab687a9-b57f-47ac-a18a-5ce1e6852988', 'Physics', 'JAMB', null, 2026, null, 'Two metals P and Q of lengths L1 and L2 are heated through the same temperature differences. If the ratio of the linear expansivities of P to Q is 2:3 and the ratio of their lengths is 3:4. What is the ratio of increase in lengths of P and Q?', null, '["5:7","2:1","1:2","7:5"]', 2, 'Increase in length ΔL = αLΔT. Ratio ΔL_P/ΔL_Q = (α_P L_P)/(α_Q L_Q) = (2/3) × (3/4) = 6/12 = 1/2. So the ratio is 1:2.', true, '2026-09-10 10:56:43.577', '2026-09-10 10:56:43.577', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6abc40bd-e43c-44c1-8bb2-2dbeacc21e5c', 'Biology', 'JAMB', null, 2010, null, 'Which of the following groups of cells is devoid of true nuclei?', null, '["Viruses.","Algae","Monera","Fungi."]', 2, 'Monera are prokaryotes devoid of true nuclei.', true, '2026-10-12 20:59:39.17', '2026-10-12 20:59:39.17', null, null, null, 'Which of the following groups of cells is devoid of true nuclei?', '["Viruses.","Algae","Monera","Fungi."]', 'Monera are prokaryotes devoid of true nuclei.', '{"bold":["Monera"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6ac296a4-7baa-436e-a94d-61b015ffeeff', 'Hausa', 'JAMB', null, 2010, null, 'Wace kalma ke da wasula dogaye?', null, '["Akwati.","Ayaba.","Tumatir.","Kakaki."]', 3, 'Kakaki tana da wasula dogaye.', true, '2026-10-13 10:37:23.771', '2026-10-13 10:37:23.771', null, null, null, 'Wace kalma ke da wasula dogaye?', '["Akwati.","Ayaba.","Tumatir.","Kakaki."]', 'Kakaki tana da wasula dogaye.', '{"bold":["Kakaki"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6ac5dc02-a31b-40b5-aa1a-18ed4f29c22f', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'According to Thessalonians, the day of the Lord will not come unless the', null, '["living die first","scoffers come first","dead rise first","rebellion comes first"]', 3, 'According to 2 Thessalonians 2:3, the day of the Lord will not come unless the rebellion comes first, and the man of lawlessness is revealed. Paul wrote this to correct the false belief that the day of the Lord had already come.', true, '2026-09-12 09:46:13.489', '2026-09-12 09:46:13.489', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6ac73af7-b282-4072-912e-0def7c2779f9', 'Government', 'JAMB', null, 2026, null, 'The study of government is important because it', null, '["Directs people''s attention to development of non-state institution","Enables citizens to understand the processes for managing state affairs","Encourages individual to take decisions that satisfy aspirations","Encourages the elite to remain in power"]', 1, 'The study of government enables citizens to understand state affairs.', true, '2026-09-12 11:24:17.92', '2026-09-12 11:24:17.92', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6ada2229-2896-4fa9-b72b-1def34abc6ae', 'Financial Accounting', 'UTME', null, 2001, null, 'How much is owed to suppliers?', 'https://res.cloudinary.com/kwi1uv0g/image/upload/v1791842130/questions/gpedxvu4x3inu0rm2qq5.jpg', '["N50,000","N40,000","N30,000","N20,000"]', 3, 'Amount owed to suppliers = Amount owed at beginning 10,000 + Bar credit purchases 40,000 - Payment to suppliers 30,000 = 20,000.', true, '2026-10-12 22:00:05.952', '2026-10-12 22:00:05.952', null, null, null, 'How much is owed to suppliers?', '["N50,000","N40,000","N30,000","<b>N20,000</b>"]', 'Amount owed to suppliers = Amount owed at beginning 10,000 + Bar credit purchases 40,000 - Payment to suppliers 30,000 = <b>20,000</b>.', '{"bold":["20,000"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6ae6875b-a821-4b42-902f-30e04281ed00', 'General Mathematics', 'JAMB', null, 2026, null, 'Differentiate (x² - 1/x)² with respect to x', null, '["4x³ - 2 - 1/x³","4x³ - 2 + 2/x³","4x³ - 3x + 2/x","4x³ - 4x - 2/x"]', 1, 'y = (x² - x⁻¹)². dy/dx = 2(x²-x⁻¹)(2x+x⁻²) = 2(2x³ + 1 - 2x - x⁻³) = 4x³ - 4x + 2 - 2x⁻³. Not in options.', true, '2026-09-12 11:44:18.563', '2026-09-12 11:44:18.563', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6ae724a6-424f-4811-9585-10be528b253b', 'English Language', 'JAMB', null, 2007, null, 'Four weeks <u>------------</u> enough for the police to conclude their investigation.', null, '["were","is","are","has been"]', 1, 'Period as unit â†’ singular is.', true, '2026-10-24 01:04:28.83', '2026-10-24 01:04:28.83', null, null, null, 'Four weeks <u>------------</u> enough for the police to conclude their investigation.', '["were","<u>is</u>","are","has been"]', 'Period as <b>unit</b> â†’ singular <b>is</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6ae9b1a4-69b0-490c-807b-cf2ab37efe32', 'Biology', 'JAMB', null, 2011, null, 'Which of the following instruments is used to measure relative humidity?', null, '["Hydrometer","Thermometer","Hygrometer","Anemometer"]', 2, 'A hygrometer measures relative humidity.', true, '2026-10-12 20:59:43.17', '2026-10-12 20:59:43.17', null, null, null, 'Which of the following instruments is used to measure relative humidity?', '["Hydrometer","Thermometer","Hygrometer","Anemometer"]', 'A hygrometer measures relative humidity.', '{"bold":["hygrometer"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6aee1f29-e930-4f3f-8bbe-084cfc3edaa7', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). What you will find in the book is <u>a bird''s-eye view</u> of the subject.', null, '["a detailed account","a balanced discussion","a biased treatment","a general survey"]', 3, '''A bird''s-eye view'' = general survey.', true, '2026-10-24 01:02:08.287', '2026-10-24 01:02:08.287', null, null, null, '(Choose the most appropriate interpretation). What you will find in the book is <u>a bird''s-eye view</u> of the subject.', '["a detailed account","a balanced discussion","a biased treatment","<u>a general survey</u>"]', '''A <b>bird''s-eye view</b>'' = <b>general survey</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6affd99f-ad7a-4f04-b9af-bd7302dd022a', 'Chemistry', 'JAMB', null, 2026, null, 'Ammonia gas is normally dried with', null, '["fused CaCl2","concentrated H2SO4","CaO","MgSO4"]', 2, 'Calcium oxide (quicklime, CaO) is a basic drying agent that does not chemically react with alkaline ammonia gas.', true, '2026-09-09 17:12:45.487', '2026-09-09 17:12:45.487', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6afff562-1cde-4a5e-9052-183f400e0d84', 'English Language', 'JAMB', null, 2007, null, 'Note that only senior members of staff have the <u>__________</u> of using the toilet upstairs', null, '["permission","occasion","privilege","habit"]', 2, 'Correct spelling: privilege.', true, '2026-10-24 07:21:42.661', '2026-10-24 07:21:42.661', null, null, null, 'Note that only senior members of staff have the <u>__________</u> of using the toilet upstairs', '["permission","occasion","privilege","habit"]', 'Correct spelling: privilege.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6b0654b0-fd0f-48ab-b5ba-50dd08e4df38', 'Biology', 'JAMB', null, 2013, null, 'The eye defect caused by the development of cloudy areas in the lenses is', null, '["Cataract","Astigmatism","Presbyopia","Glaucoma"]', 0, 'Cataract is caused by cloudy areas in the lenses.', true, '2026-10-12 20:59:47.941', '2026-10-12 20:59:47.941', null, null, null, 'The eye defect caused by the development of cloudy areas in the lenses is', '["Cataract","Astigmatism","Presbyopia","Glaucoma"]', 'Cataract is caused by cloudy areas in the lenses.', '{"bold":["Cataract"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6b066144-3a33-4955-95eb-ff809dbd85ef', 'Chemistry', 'JAMB', null, 2026, null, 'Which compound represents the simplest alkene?', null, '["C₂H₄","C₂H₆","C₂H₂","CH₄"]', 0, 'C₂H₄ (ethene) is the simplest alkene. It contains a carbon-carbon double bond and has the general formula CₙH₂ₙ. C₂H₆ is ethane (alkane), C₂H₂ is ethyne (alkyne), and CH₄ is methane (alkane).', true, '2026-09-12 09:38:16.559', '2026-09-12 09:38:16.559', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6b1a21e1-8108-42f1-b453-f6081c54b0e3', 'Biology', 'JAMB', null, 2026, null, 'The main distinguishing features between the soldier termite and other members of the caste are the', null, '["Presence of wings, small head and large thorax","Presence of wings, large thorax and small head","Absence of wings, strong mandibles and large head","Absence of wings, big head and no mandibles"]', 2, 'Soldier termites are distinguished from other caste members by the absence of wings, strong mandibles, and a large head. Soldiers are specialized for colony defense. Their large heads and powerful mandibles are used to attack predators. The absence of wings distinguishes them from reproductive individuals (which have wings). Workers have smaller heads and weaker mandibles. Reproductive termites have wings and smaller heads and are larger overall. The soldier termite''s large head is a defense adaptation that makes them effective at protecting the colony.', true, '2026-09-09 03:18:57.46', '2026-09-09 03:18:57.46', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6b2559a7-c35e-4975-af55-c7f4d626c7f0', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. That team has become <u>indomitable</u> quite recently.', null, '["incorrigible","disobedient","unconquerable","unruly"]', 2, 'Indomitable = unconquerable.', true, '2026-10-24 01:03:57.466', '2026-10-24 01:03:57.466', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. That team has become <u>indomitable</u> quite recently.', '["incorrigible","disobedient","<u>unconquerable</u>","unruly"]', '<b>Indomitable</b> = <b>unconquerable</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6b27d048-ea9c-4066-9f94-6a333114b75a', 'Hausa', 'JAMB', null, 2010, null, 'Wanne ne bare daga cikin magungunan da magori ke bayarwa?', null, '["Sassaŝe.","Turare.","Laya.","Shafi."]', 2, 'Laya bare ne daga cikin magungunan da magori ke bayarwa.', true, '2026-10-13 10:37:24.57', '2026-10-13 10:37:24.57', null, null, null, 'Wanne ne bare daga cikin magungunan da magori ke bayarwa?', '["Sassaŝe.","Turare.","Laya.","Shafi."]', 'Laya bare ne daga cikin magungunan da magori ke bayarwa.', '{"bold":["Laya"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6b29b367-6925-43f3-a536-27c1dc3ab91c', 'English Language', 'JAMB', null, 2007, null, 'The suspect defrauded his <u>----------------</u> victims of large sums of money', null, '["unsuspected","unsuspecting","unexpected","unexpected"]', 1, 'Correct spelling: unsuspecting.', true, '2026-10-24 07:21:41.499', '2026-10-24 07:21:41.499', null, null, null, 'The suspect defrauded his <u>----------------</u> victims of large sums of money', '["unsuspected","unsuspecting","unexpected","unexpected"]', 'Correct spelling: unsuspecting.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6b36facb-36b2-4ef3-ab25-505b8385f617', 'Biology', 'JAMB', null, 2026, null, 'An example of a fruit that develops from a single carpel is', null, '["okro","tomato","bean","orange"]', 2, 'The bean is a fruit (pod) that develops from a single carpel (monocarpous). It is a legume that splits along two sides at maturity. Okro (okra) has multiple carpels, forming a capsule. Tomato is a berry with multiple carpels. Orange is a hesperidium with multiple carpels. Fruits from a single carpel are considered simple fruits and include leguminous pods (beans, peas). The number of carpels in the flower is determined by the structure of the ovary and the pattern of the fruit development.', true, '2026-09-09 03:18:47.025', '2026-09-09 03:18:47.025', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6b3abb49-5a8d-4da0-b461-096791705e41', 'Biology', 'JAMB', null, 2026, null, 'The flow of air and water in or out of the mesophyll layer of a leaf is controlled by the', null, '["air space","lenticels","stomata","guard cell"]', 2, 'Stomata control the flow of air and water into and out of the mesophyll layer of the leaf. These are microscopic pores in the epidermis that allow gas exchange (CO₂ in, O₂ out) and transpiration (water vapor out). While guard cells (IV) control the opening and closing of stomata, it is the stomata themselves that directly control gas and water flow. Air spaces are within the mesophyll, not controlling the flow. Lenticels are pores in woody stems, not leaves, for gas exchange. The stomatal pore is the passageway for gases.', true, '2026-09-09 03:18:41.757', '2026-09-09 03:18:41.757', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6b425b55-29cc-42f8-9638-e4a21ba4838b', 'Biology', 'JAMB', null, 2011, null, 'Drancunculosis can be contacted through', null, '["eating contaminated food","drinking contaminated water","bathing in contaminated water","bites of blackfly."]', 1, 'Drancunculosis is contacted through drinking contaminated water.', true, '2026-10-12 20:59:43.322', '2026-10-12 20:59:43.322', null, null, null, 'Drancunculosis can be contacted through', '["eating contaminated food","drinking contaminated water","bathing in contaminated water","bites of blackfly."]', 'Drancunculosis is contacted through drinking contaminated water.', '{"bold":["drinking contaminated water"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6b50a845-a68a-48fa-a14b-883ee7293fe1', 'Biology', 'JAMB', null, 2004, null, 'A farmer practice that results in the loss of soil fertility is', null, '["mixed farming","bush fallowing","shifting cultivation","continuous cropping"]', 3, 'Continuous cropping leads to loss of soil fertility.', true, '2026-10-12 20:59:35.732', '2026-10-12 20:59:35.732', null, null, null, 'A farmer practice that results in the loss of soil fertility is', '["mixed farming","bush fallowing","shifting cultivation","continuous cropping"]', 'Continuous cropping leads to loss of soil fertility.', '{"bold":["Continuous cropping"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6b54cc90-f5b4-41cd-9bd6-13b65deddfe7', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'At the age of seventeen, Joseph', null, '["was sold into slavery","was imprisoned","re-united with his brothers","became a Governor"]', 0, 'Joseph was sold into slavery at seventeen.', true, '2026-09-12 10:42:01.055', '2026-09-12 10:42:01.055', null, null, null, null, null, null, null);
