insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6b5926f3-fe64-48d0-9e30-bf6c3e3e3063', 'Physics', 'JAMB', null, 1999, null, 'Steel is more suitable for a permanent magnet than iron because the former', null, '["Is easily demagnetized by shaking vigorously","Is an alloy of many metals","Is easily magnetized by alternating current through one cycle","Retains magnetism more than iron."]', 3, 'Steel has high retentivity, so it keeps its magnetism once magnetized. Soft iron loses it easily.', true, '2026-10-12 19:15:48.092', '2026-10-12 19:15:48.092', null, null, null, 'Steel is more suitable for a permanent magnet than iron because the former', '["Is easily demagnetized by shaking vigorously","Is an alloy of many metals","Is easily magnetized by alternating current through one cycle","Retains magnetism more than iron."]', 'Steel has high retentivity, so it keeps its magnetism once magnetized. Soft iron loses it easily.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
