insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6b75bdca-9da3-412d-8d15-936a744165b1', 'Literature in English', 'JAMB', null, 2026, null, 'In The Digging, the line ''Between my finger and my thumb / The squat pen rests; snug as a gun'' suggests that the pen', null, '["Is a weapon of violence","Symbolises the poet''s tool of labour","Represents political struggle","Is inferior to manual labour"]', 1, 'The pen symbolizes the poet''s tool of labour.', true, '2026-09-12 11:12:03.466', '2026-09-12 11:12:03.466', null, null, null, null, null, null, null);
