insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6b82d3ca-74eb-4b4f-8d2d-f5b6cdced513', 'Physics', 'JAMB', null, 1986, null, 'The specific latent heat of fusion of lead is the amount of heat required to', null, '["Melt lead at its melting point","Heat a unit mass of lead through 1 °C.","Change the state of a unit mass of lead at its melting point.","Change the state of a unit mass of lead at its boiling point."]', 2, 'Specific latent heat of fusion is the heat needed to change a unit mass of solid to liquid at its melting point without a temperature change.', true, '2026-10-12 19:15:23.36', '2026-10-12 19:15:23.36', null, null, null, 'The specific latent heat of fusion of lead is the amount of heat required to', '["Melt lead at its melting point","Heat a unit mass of lead through 1 °C.","Change the state of a unit mass of lead at its melting point.","Change the state of a unit mass of lead at its boiling point."]', 'Specific latent heat of fusion is the heat needed to change a unit mass of solid to liquid at its melting point without a temperature change.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
