insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6bfb859e-8e32-46d6-bf23-eab3d92e467b', 'Biology', 'JAMB', null, 2011, null, 'Which of the following is true of leucocytes?', null, '["They are respiratory pigments","They are most numerous and ramify all cells.","They are large and nucleated.","They are involved in blood clotting."]', 2, 'Leucocytes are large and nucleated.', true, '2026-10-12 20:59:42.052', '2026-10-12 20:59:42.052', null, null, null, 'Which of the following is true of leucocytes?', '["They are respiratory pigments","They are most numerous and ramify all cells.","They are large and nucleated.","They are involved in blood clotting."]', 'Leucocytes are large and nucleated.', '{"bold":["large and nucleated"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6c06af47-b774-4f52-9f10-9068570540c3', 'Literature in English', 'JAMB', null, 2026, null, 'What are they discussing?', null, '["the throne","war","Love affairs","grievances"]', 2, 'They are discussing love affairs.', true, '2026-09-12 11:11:28.469', '2026-09-12 11:11:28.469', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6c06ded6-551b-4e7e-b6ed-0800311d947c', 'Biology', 'JAMB', null, 2026, null, 'Which of these instruments is used to demonstrate the response of shoots and roots to gravity?', null, '["klinostat","manometer","potometer","photometer"]', 0, 'A klinostat (clinostat) is an instrument used to demonstrate the response of plant shoots and roots to gravity (geotropism). It rotates plants slowly, neutralizing the effect of gravity so that growth responses can be studied. A manometer measures pressure. A potometer measures transpiration rate. A photometer measures light intensity. The klinostat allows researchers to observe plant growth in the absence of a constant gravitational signal, helping to study the mechanisms of gravitropism and the role of auxins in directional plant growth.', true, '2026-09-09 03:18:50.846', '2026-09-09 03:18:50.846', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6c13a2df-ded0-48bc-a0bd-96712afcac49', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'To the question of the Philippian jailer, ''Men what must I do to be saved?'' Paul replied', null, '["confess your sins and give alms","believe in the Lord Jesus","release us to wash our wounds","trust in God and pray always"]', 1, 'Paul said, ''Believe in the Lord Jesus, and you will be saved.''', true, '2026-09-12 10:41:02.468', '2026-09-12 10:41:02.468', null, null, null, null, null, null, null);
