insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6c4d3c61-54ae-44c8-a3a6-1266b43cf39c', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The principal gave his speech <u>offhand</u> at the sports meeting.', null, '["beautifully","unconcerned","unprepared","calmly"]', 2, 'Offhand = unprepared.', true, '2026-10-24 01:04:06.922', '2026-10-24 01:04:06.922', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The principal gave his speech <u>offhand</u> at the sports meeting.', '["beautifully","unconcerned","<u>unprepared</u>","calmly"]', '<b>Offhand</b> = <b>unprepared</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6c5fc281-e7ea-4671-a98b-d869f53665b8', 'Literature in English', 'JAMB', null, 2026, null, 'Expressions or ideas that have been used so often that they lost their expressive power are called', null, '["Cliches","Obsolete","Tautology","Archaic"]', 0, 'They are called cliches.', true, '2026-09-12 11:14:01.081', '2026-09-12 11:14:01.081', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6c652516-6693-43ed-91f2-cf36af30ee0d', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. You are <u>free</u> to leave the hall.', null, '["at an advantage","opportune","at liberty","right"]', 2, 'Free = at liberty.', true, '2026-10-24 01:03:54.243', '2026-10-24 01:03:54.243', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. You are <u>free</u> to leave the hall.', '["at an advantage","opportune","<u>at liberty</u>","right"]', '<b>Free</b> = <b>at liberty</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6c705fc6-825a-4849-a24a-d7208f0258e7', 'Literature in English', 'JAMB', null, 2026, null, 'A performance whereby a story is expressed through singing and music is called', null, '["Drama","Opera","Pantomime","Ballet"]', 1, 'An opera expresses story through singing and music.', true, '2026-09-12 11:07:25.825', '2026-09-12 11:07:25.825', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6c766bf9-641e-43cf-a39e-5651263e5e1c', 'Biology', 'JAMB', null, 2010, null, 'Which of the following stimuli is likely to elicit a nastic response in an organism?', null, '["Touch.","Light intensity","Chemical substances.","Gravity"]', 0, 'Touch elicits a nastic response.', true, '2026-10-12 20:59:40.055', '2026-10-12 20:59:40.055', null, null, null, 'Which of the following stimuli is likely to elicit a nastic response in an organism?', '["Touch.","Light intensity","Chemical substances.","Gravity"]', 'Touch elicits a nastic response.', '{"bold":["Touch"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6c7b2afd-4d19-429c-929f-7f08a3a57008', 'Literature in English', 'JAMB', null, 2026, null, 'A tragic hero, according to the Aristotelian precept must be', null, '["a noble character with hubris","a lowly character who suddenly stumbles on some fortune","a king with deep affection for his subjects","a central character after whom the play is named"]', 0, 'A tragic hero, according to the Aristotelian precept, must be a noble character with hubris. Aristotle defined the tragic hero as a person of high status and noble character who possesses a tragic flaw (hamartia), often hubris (excessive pride), which leads to their downfall. The hero''s misfortune is not entirely deserved but results from their flaw. A lowly character would not fit the Aristotelian model.', true, '2026-09-10 10:47:10.407', '2026-09-10 10:47:10.407', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6c812f3d-940f-43c0-8767-a9d5a30a9fba', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'To whom was this addressed? ''Rule over us, you and your son and your grandson also; for you have delivered us out of the hand of Midian''', null, '["Deborah","Samson","Gideon","Jephthah"]', 2, 'The Israelites asked Gideon to rule over them after he delivered them from Midian.', true, '2026-09-12 10:41:14.024', '2026-09-12 10:41:14.024', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6c81ede0-651b-47b9-97ef-d47827b34896', 'Physics', 'JAMB', null, 1999, null, 'A ball of mass 0.1 kg is thrown vertically upwards with a speed of 10 m s⁻¹ from the top of a tower 10 m high. Neglecting air resistance, its total energy just before hitting the ground is [g = 10 m s⁻²]', null, '["5 J","10 J","15 J","20 J"]', 2, 'Total energy is conserved. At launch: KE = ½ x 0.1 x 100 = 5 J and PE = 0.1 x 10 x 10 = 10 J (taking the ground as zero). The total is 15 J.', true, '2026-10-12 19:15:47.074', '2026-10-12 19:15:47.074', null, null, null, 'A ball of mass 0.1 kg is thrown vertically upwards with a speed of 10 m s<sup>-1</sup> from the top of a tower 10 m high. Neglecting air resistance, its total energy just before hitting the ground is [g = 10 m s<sup>-2</sup>]', '["5 J","10 J","15 J","20 J"]', 'Total energy is conserved. At launch: KE = ½ x 0.1 x 100 = 5 J and PE = 0.1 x 10 x 10 = 10 J (taking the ground as zero). The total is 15 J.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6c87aeae-5eb8-4d31-bd74-cceabf2d8fd5', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. My father lived a <u>Spartan</u> life before his death.', null, '["extravagant","peaceful","quite","luxurious"]', 3, 'Spartan = austere; opposite = luxurious.', true, '2026-10-24 07:21:28.157', '2026-10-24 07:21:28.157', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. My father lived a <u>Spartan</u> life before his death.', '["extravagant","peaceful","quite","luxurious"]', 'Spartan = austere; opposite = luxurious.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6c9cc194-aead-41ce-ae2e-a3abdf09d93d', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The essay topic is <u>nebulous</u>.', null, '["vague","incorrect","distinct","clear"]', 0, 'Nebulous = vague.', true, '2026-10-24 01:04:02.156', '2026-10-24 01:04:02.156', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The essay topic is <u>nebulous</u>.', '["<u>vague</u>","incorrect","distinct","clear"]', '<b>Nebulous</b> = <b>vague</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6c9cfda1-3050-4ba7-8ef8-ddd8becb67b3', 'Physics', 'JAMB', null, 2026, null, 'Which of the following statements correctly describes the penetrating power of ionizing radiations?', null, '["Alpha particles are more penetrating than beta particles","Gamma rays are the most penetrating because they have no mass or charge","Beta particles can be stopped by a single sheet of paper","Alpha particles can easily pass through several centimeters of aluminum"]', 1, 'Gamma rays are the most penetrating because they have no mass or charge. They can pass through several centimeters of lead. Alpha particles are stopped by paper, beta particles by a few millimeters of aluminum.', true, '2026-09-10 10:56:49.362', '2026-09-10 10:56:49.362', null, null, null, null, null, null, null);
