insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6cb712b0-5d0a-4c4b-968f-5922fe92f8f1', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Since his father''s death, Osita has not been able to <u>cope with</u> the tasks of a family head.', null, '["perform adequately","tolerate","accept","assess properly","manage"]', 4, 'Cope with = manage.', true, '2026-10-24 01:03:54.082', '2026-10-24 01:03:54.082', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Since his father''s death, Osita has not been able to <u>cope with</u> the tasks of a family head.', '["perform adequately","tolerate","accept","assess properly","<u>manage</u>"]', '<b>Cope with</b> = <b>manage</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6cc2c059-a39b-486d-be35-b49d572847ba', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. After careful investigation, the police found no <u>iota</u> of truth in Ibrahim''s allegations.', null, '["quota","grain","evidence","statement"]', 1, 'Iota = grain (tiny amount).', true, '2026-10-24 01:03:57.093', '2026-10-24 01:03:57.093', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. After careful investigation, the police found no <u>iota</u> of truth in Ibrahim''s allegations.', '["quota","<u>grain</u>","evidence","statement"]', '<b>Iota</b> = <b>grain</b> (tiny amount).', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6cde4d56-980b-4c64-85c9-37e4535a2c6f', 'Physics', 'JAMB', null, 2004, null, 'In a hydraulic press, a force of 40 N is applied on the effort piston of area 0.4 m². If the force exerted on the load piston is 400 N, the area of the large piston is', null, '["8 m²","4 m²","2 m²","1 m²"]', 1, 'Pressure is the same: 40/0.4 = 400/A, so A = 4 m².', true, '2026-10-12 19:15:58.82', '2026-10-12 19:15:58.82', null, null, null, 'In a hydraulic press, a force of 40 N is applied on the effort piston of area 0.4 m<sup>2</sup>. If the force exerted on the load piston is 400 N, the area of the large piston is', '["8 m<sup>2</sup>","4 m<sup>2</sup>","2 m<sup>2</sup>","1 m<sup>2</sup>"]', 'Pressure is the same: 40/0.4 = 400/A, so A = 4 m<sup>2</sup>.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6ce27fca-3c56-487b-b5c0-112299f28efc', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Paul told the Athenians that they were very religious because', null, '["some of their poets said that men are the offsprings","they dedicated an altar to the unknown God","their Epicurean and Stoic philosophers always discussed religious issues","the city was full of idols and symbols of religious devotion"]', 1, 'Paul noted their altar to the unknown God.', true, '2026-09-12 10:41:49.708', '2026-09-12 10:41:49.708', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6ce6bc84-368f-4e79-95fd-750a78b6adfe', 'English Language', 'JAMB', null, 2007, null, 'My experience in Lagos last week was <u>__________</u> about', null, '["something to excite","nothing to explain at home","nothing to write home","something to celebrate"]', 2, 'Correct idiom: nothing to write home about.', true, '2026-10-24 07:21:43.213', '2026-10-24 07:21:43.213', null, null, null, 'My experience in Lagos last week was <u>__________</u> about', '["something to excite","nothing to explain at home","nothing to write home","something to celebrate"]', 'Correct idiom: nothing to write home about.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6cfd4aaf-913a-4455-95af-8b09472f8552', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. He <u>deprecated</u> the attempts made to unseat him.', null, '["resisted","condemned","despised","challenged"]', 1, 'Deprecated = condemned.', true, '2026-10-24 01:01:56.756', '2026-10-24 01:01:56.756', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. He <u>deprecated</u> the attempts made to unseat him.', '["resisted","<u>condemned</u>","despised","challenged"]', '<b>Deprecated</b> = <b>condemned</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6cff393e-e727-42e9-9801-d65e734be76a', 'Biology', 'JAMB', null, 2011, null, 'The function of the red head in male Agama lizards is to', null, '["conceal and camouflage the animal from predators.","scare other males from the territory.","attract female lizards for mating purposes.","warn predators of the distastefulness."]', 2, 'The red head attracts female lizards for mating.', true, '2026-10-12 20:59:41.596', '2026-10-12 20:59:41.596', null, null, null, 'The function of the red head in male Agama lizards is to', '["conceal and camouflage the animal from predators.","scare other males from the territory.","attract female lizards for mating purposes.","warn predators of the distastefulness."]', 'The red head attracts female lizards for mating.', '{"bold":["attracts female lizards for mating"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6d053a8b-f872-40d1-9543-a9dae63d082c', 'Economics', 'JAMB', null, 2026, null, 'The principle that specified that the amount, when and how to pay tax should be made known to tax payer is known as?', null, '["Economy","Certainty","Simplicity","Convenience"]', 1, 'The principle of certainty requires that tax amounts and payment details be clear to taxpayers.', true, '2026-09-12 11:02:04.622', '2026-09-12 11:02:04.622', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6d0f8be5-11e0-435b-872c-803887ca4d21', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. That team has become <u>indomitable</u> quite recently.', null, '["incorrigible","disobedient","unconquerable","unruly"]', 2, 'Indomitable = unconquerable.', true, '2026-10-24 01:01:45.419', '2026-10-24 01:01:45.419', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. That team has become <u>indomitable</u> quite recently.', '["incorrigible","disobedient","<u>unconquerable</u>","unruly"]', '<b>Indomitable</b> = <b>unconquerable</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6d0f98f4-d4f5-4858-9770-6c67d6985352', 'English Language', 'JAMB', null, 2024, null, 'But workers are not easily persuaded to strike even by a clever _6_.', null, '["trade union","member","operator","organization"]', 0, 'A trade union is the body that organizes and persuades workers.', true, '2026-09-18 09:23:08.098', '2026-09-18 09:23:08.098', null, null, 'CLOZE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6d100b11-ac8d-41a0-844b-67573a00cdd8', 'Literature in English', 'JAMB', null, 2026, null, 'The rhyme scheme of the first stanza is', null, '["Aabb","Abab","Abcd","Abba"]', 1, 'The rhyme scheme is ABAB.', true, '2026-09-12 11:07:28.263', '2026-09-12 11:07:28.263', null, null, null, null, null, null, null);
