insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6d3440b8-e471-49e6-bfd2-a7b8e7ee5bfc', 'Literature in English', 'JAMB', null, 2026, null, 'Who are the speakers in this extract?', null, '["Octavius Caesar and Enobarbus","Anthony and Thyreus","Cleopatra and Anthony","Enobarbus and Anthony"]', 2, 'The speakers are Cleopatra and Anthony.', true, '2026-09-12 11:11:17.852', '2026-09-12 11:11:17.852', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6d35637a-3438-4b27-b993-faf108f2dbe6', 'Physics', 'JAMB', null, 2026, null, 'In the above fig, PQ and R are vectors, which of the following options gives a correct relationship between the vectors?', 'https://res.cloudinary.com/kwi1uv0g/image/upload/v1789039564/questions/i9ic2clg7yayajdt5a6w.jpg', '["P = Q + R","P = Q - R","P = R - Q","P + Q + R = 0"]', 0, 'In vector addition, if vectors Q and R are arranged head-to-tail, their resultant is vector P. This gives P = Q + R. The diagram shows a vector triangle where P is the resultant of Q and R.', true, '2026-09-10 11:27:02.174', '2026-09-10 11:27:02.174', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6d375304-1445-47ce-a036-05bfbd34a642', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). Many candidates apply to read Law because it <u>is a lucrative profession</u>.', null, '["brings plenty of profit","brings high prestige","brings quick money","brings plenty of knowledge"]', 0, 'Lucrative = profitable.', true, '2026-10-24 01:02:03.286', '2026-10-24 01:02:03.286', null, null, null, '(Choose the most appropriate interpretation). Many candidates apply to read Law because it <u>is a lucrative profession</u>.', '["<u>brings plenty of profit</u>","brings high prestige","brings quick money","brings plenty of knowledge"]', '<b>Lucrative</b> = <b>profitable</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6d474e00-5745-4985-884b-a03cc5963377', 'Economics', 'JAMB', null, 2026, null, 'A firm owned and managed by a family is an example of', null, '["Cooperative society","Sole proprietorship","Joint stock","Partnership"]', 1, 'A firm owned and managed by a family is typically a sole proprietorship.', true, '2026-09-12 10:58:41.586', '2026-09-12 10:58:41.586', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6d4908ac-8ee6-4d4a-a888-006a7297be7b', 'Hausa', 'JAMB', null, 2011, null, 'Me furen tumfafiya kan kara wa mutum?', null, '["KwarinKashi.","Farin jini.","Kwarjini.","Jarumtaka."]', 0, 'Furen tumfafiya kan kara wa mutum kwarin kashi.', true, '2026-10-13 10:37:21.881', '2026-10-13 10:37:21.881', null, null, null, 'Me furen tumfafiya kan kara wa mutum?', '["KwarinKashi.","Farin jini.","Kwarjini.","Jarumtaka."]', 'Furen tumfafiya kan kara wa mutum kwarin kashi.', '{"bold":["kwarin kashi"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6d63d517-d15d-4604-977d-3223a9f1b2bb', 'Government', 'JAMB', null, 2026, null, 'The UNO security council comprises ______ permanent members and ______ non-permanent members', null, '["10, 5","5, 10","5, 12","5, 15"]', 1, 'The UN Security Council comprises 5 permanent and 10 non-permanent members.', true, '2026-09-12 11:24:03.816', '2026-09-12 11:24:03.816', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6d69c6a9-1abb-4d85-b7a7-52a5fe5c0860', 'Chemistry', 'JAMB', null, 2026, null, 'The brown fumes given off when trioxonitrate (V) acid is heated consists of', null, '["NO2 and O2","H2O and NO2","NO2, O2 and H2O","NO, NO2, H2O"]', 0, 'Thermal decomposition of concentrated HNO3 releases nitrogen dioxide (NO2, brown fumes) and oxygen gas (O2).', true, '2026-09-09 17:12:45.589', '2026-09-09 17:12:45.589', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6d757548-3b1c-4c78-856a-d1a2f4a029d2', 'Financial Accounting', 'UTME', null, 2002, null, 'The gross profit on manufactured goods is the difference between the cost of goods manufactured and the', null, '["market value of goods produced","prime cost of production","indirect cost of production","goods produced"]', 0, 'Gross profit on manufacturing is also known as mark-up and always expressed as a percentage of cost of goods sold/manufactured. Market value is price at which the company would buy the goods if not produced by itself.', true, '2026-10-12 21:59:58.154', '2026-10-12 21:59:58.154', null, null, null, 'The gross profit on manufactured goods is the difference between the cost of goods manufactured and the', '["<b>market value of goods produced</b>","prime cost of production","indirect cost of production","goods produced"]', 'Gross profit on manufacturing is also known as mark-up and always expressed as a percentage of cost of goods sold/manufactured. <b>Market value</b> is price at which the company would buy the goods if not produced by itself.', '{"bold":["market value"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6d88c0a8-346e-495a-9daf-06194d4d6bbb', 'Literature in English', 'JAMB', null, 2026, null, 'In the play, why does Mark Antony initially neglect his duties in Rome?', null, '["He is ill and unable to travel","He is deeply engrossed in his love for Cleopatra","He fears political enemies in Rome","He is planning a secret military attack"]', 1, 'Antony neglects his duties because he is engrossed in his love for Cleopatra.', true, '2026-09-12 11:11:58.797', '2026-09-12 11:11:58.797', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6d8b08c2-d0fd-4439-9bd1-36bf54b308e2', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Is it necessary for us to go? She asked in her <u>shrill</u> voice.', null, '["indistinct","angry","quiet","aggressive"]', 2, 'Shrill = high-pitched; opposite = quiet.', true, '2026-10-24 07:21:28.666', '2026-10-24 07:21:28.666', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Is it necessary for us to go? She asked in her <u>shrill</u> voice.', '["indistinct","angry","quiet","aggressive"]', 'Shrill = high-pitched; opposite = quiet.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6d956b2a-9647-430a-b276-24c53f3f268b', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). The fact that Ruth has inherited her late husband''s house is <u>cold comfort to her</u>.', null, '["appropriate comfort","inadequate comfort","no comfort at all","wet comfort"]', 1, '''Cold comfort'' = inadequate consolation.', true, '2026-10-24 01:02:04.585', '2026-10-24 01:02:04.585', null, null, null, '(Choose the most appropriate interpretation). The fact that Ruth has inherited her late husband''s house is <u>cold comfort to her</u>.', '["appropriate comfort","<u>inadequate comfort</u>","no comfort at all","wet comfort"]', '''<b>Cold comfort</b>'' = <b>inadequate consolation</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6d987f8c-0396-4ff8-b2df-4cc1980dc148', 'Biology', 'JAMB', null, 2026, null, 'Which of the organelles has a double membrane?', null, '["nucleus","chloroplast","mitochondria","all except b","all"]', 4, 'The nucleus (nuclear envelope), chloroplasts, and mitochondria are all double-membrane-bound organelles. This double membrane structure is characteristic of organelles that are believed to have originated from endosymbiotic events. The nucleus has an outer and inner nuclear membrane with pores. Chloroplasts have an outer and inner membrane with the thylakoid system inside. Mitochondria have an outer smooth membrane and an inner folded membrane forming cristae. No other listed option is fully correct, making ''all'' the answer.', true, '2026-09-09 03:18:16.101', '2026-09-09 03:18:16.101', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6d9f94ae-4435-4927-a49b-0ce53fa66821', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. There is much <u>apathy</u> towards reading among students nowadays.', null, '["indecision","enthusiasm","indifference","disinclination"]', 1, 'Apathy = indifference; opposite = enthusiasm.', true, '2026-10-24 07:21:22.961', '2026-10-24 07:21:22.961', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. There is much <u>apathy</u> towards reading among students nowadays.', '["indecision","enthusiasm","indifference","disinclination"]', 'Apathy = indifference; opposite = enthusiasm.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6da16a13-1840-40e6-84da-6553f95019a6', 'Literature in English', 'JAMB', null, 2026, null, 'Who are the speakers in this extract?', null, '["Octavius Caesar and Enobarbus","Anthony and Thyreus","Cleopatra and Anthony","Enobarbus and Anthony"]', 2, 'The speakers are Cleopatra and Anthony.', true, '2026-09-12 11:14:07.569', '2026-09-12 11:14:07.569', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6da46a77-4d71-4dde-a976-0be0dceffede', 'English Language', 'JAMB', null, 2024, null, 'What sort of life, according to the passage, will drive people back like aimless sheep back to cave dwelling?', null, '["life without risks","life without science and technology","life without ambition","life without hope"]', 0, 'The passage suggests that if we were all to revert to the farmer''s simple, risk-free life, we would be driven back to cave dwelling.', true, '2026-09-18 09:43:02.213', '2026-09-18 09:43:02.213', null, null, 'COMPREHENSION', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6daad516-bbb5-438c-810d-6fe08f24e2f8', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The principal gave his speech <u>offhand</u> at the sports meeting.', null, '["beautifully","unconcerned","unprepared","calmly"]', 2, 'Offhand = unprepared.', true, '2026-10-24 01:01:54.591', '2026-10-24 01:01:54.591', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The principal gave his speech <u>offhand</u> at the sports meeting.', '["beautifully","unconcerned","<u>unprepared</u>","calmly"]', '<b>Offhand</b> = <b>unprepared</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6dab9684-5bbd-49dd-b5d2-9db76418dc59', 'Literature in English', 'JAMB', null, 2026, null, 'The aim of caricature is to', null, '["expose","describe","ridicule","emphasis"]', 2, 'The aim of caricature is to ridicule.', true, '2026-09-12 11:14:01.283', '2026-09-12 11:14:01.283', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6dafc5c3-e10c-416a-87f8-f3330bc82db1', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Spiritual gifts, according to Paul should be used for the', null, '["upliftment of individuals in church","edification of the church","eradication of enmity among Christians","upliftment of the community"]', 1, 'Spiritual gifts, according to Paul, should be used for the edification of the church. In 1 Corinthians 14:12, he says, ''Since you are eager for manifestations of the Spirit, strive to excel in building up the church.''', true, '2026-09-12 09:46:05.253', '2026-09-12 09:46:05.253', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6dd1b08e-4065-4d86-b4d9-4ccec5ec0d37', 'General Mathematics', 'JAMB', null, 2026, null, 'The sum of the interior angle of a polygon is 20 right angles. How many sides does the polygon have?', null, '["12","10","20","40"]', 1, '20 × 90 = 1800. (n-2)180 = 1800. n-2 = 10. n = 12. The answer is (A) 12.', true, '2026-09-12 11:44:17.388', '2026-09-12 11:44:17.388', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6de6a8e6-8d8b-416e-b8d8-8a366f831c79', 'Economics', 'JAMB', null, 2026, null, 'Long run cost is U-shaped because of the operation of', null, '["economies of scale on the left hand side and diseconomies of scale on the right hand side","diseconomies of scale on the left and right hand sides","economies of scale on the left and right hand sides","constant return to scale","diseconomies of scale of the left hand side and economies of scale of the right hand side"]', 0, 'The long-run average cost curve is U-shaped because of economies of scale on the left side and diseconomies of scale on the right side. As a firm expands output in the long run, it initially experiences economies of scale (lower average costs) due to specialization, bulk buying, and improved efficiency. After reaching minimum efficient scale, further expansion leads to diseconomies of scale (higher average costs) due to management problems and coordination difficulties.', true, '2026-09-10 10:41:19.536', '2026-09-10 10:41:19.536', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6de9583e-af2b-4e44-9462-13e8d2db13f6', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. In his <u>naivety</u>, he believed all the stories his friend told him.', null, '["artlessness","friendliness","incredulity","stupidity"]', 2, 'Naivety = gullibility; opposite = incredulity.', true, '2026-10-24 07:21:22.709', '2026-10-24 07:21:22.709', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. In his <u>naivety</u>, he believed all the stories his friend told him.', '["artlessness","friendliness","incredulity","stupidity"]', 'Naivety = gullibility; opposite = incredulity.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6dec2c07-85ff-452a-a079-28304f984c43', 'Physics', 'JAMB', null, 2026, null, 'If the length of the second hand is 15 cm, what is the approximate linear velocity of the tip of the second hand?', null, '["1.57cm/s","57cm/s","0.016cm/s","6000cm/s"]', 0, 'Linear velocity v = 2πr/T. r = 15cm, T = 60s. v = 2π(15)/60 = 30π/60 = π/2 ≈ 1.57 cm/s.', true, '2026-09-10 10:56:45.468', '2026-09-10 10:56:45.468', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6df6984d-7840-4e9e-a2d0-52c424e4f9e3', 'Financial Accounting', 'UTME', null, 2002, null, 'The closing stock on March 11th by LIFO valuation is', 'https://res.cloudinary.com/kwi1uv0g/image/upload/v1791841114/questions/jppok8cniimdsihdbc6k.jpg', '["N4200","N2700","N4500","N3900"]', 3, 'Balance of 2nd Jan. receipt 100 @ 25 = 2500. Balance of Mar. receipts 50 @ 28 = 1400. Value of closing at 11th Mar. = 3900.', true, '2026-10-12 21:59:58.646', '2026-10-12 21:59:58.646', null, null, null, 'The closing stock on March 11th by LIFO valuation is', '["N4200","N2700","N4500","<b>N3900</b>"]', 'Balance of 2nd Jan. receipt 100 @ 25 = 2500. Balance of Mar. receipts 50 @ 28 = 1400. Value of closing at 11th Mar. = <b>3900</b>.', '{"bold":["3900"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6dfbabc1-f2bd-4f92-a5ba-4aee91090b72', 'English Language', 'JAMB', null, 2024, null, 'The passage reveals that Angel Honorio Roffo has a sound knowledge of', null, '["Chemistry","Medicine","Pharmacy","Physiology"]', 1, 'Roffo''s research on cancer and tobacco suggests a sound knowledge of medicine.', true, '2026-09-18 09:34:04.034', '2026-09-18 09:34:04.034', null, null, 'COMPREHENSION', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6e02065b-2bd3-45d7-a5fc-68181309063c', 'Economics', 'JAMB', null, 2026, null, 'A rightward shift in the supply curve is caused by', null, '["Advancement in technology","Increase in Price of the good","Increase in Government tax on good","Increase in cost of production"]', 0, 'Advancement in technology reduces production costs and shifts supply to the right.', true, '2026-09-12 10:59:50.34', '2026-09-12 10:59:50.34', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6e095bb6-8a10-4122-9599-bb8ec154484e', 'English Language', 'JAMB', null, 2007, null, 'At the <u>__________</u> of the century, many ways of doing things were introduced.', null, '["turn","event","birth","sight"]', 0, 'Correct form: turn of the century.', true, '2026-10-24 07:21:37.425', '2026-10-24 07:21:37.425', null, null, null, 'At the <u>__________</u> of the century, many ways of doing things were introduced.', '["turn","event","birth","sight"]', 'Correct form: turn of the century.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6e296d1b-5c28-49b2-b37a-a36526f9587b', 'Yoruba', 'JAMB', null, 2002, null, 'lÿë àwòn òbí nínû ètò ìgbéyàwó ni', null, '["ìjòhçn","ìwádìí","aýò ríra","eyín pípa."]', 1, 'lÿë àwòn òbí nínû ètò ìgbéyàwó ni ìwádìí.', true, '2026-10-13 13:22:40.616', '2026-10-13 13:22:40.616', null, null, null, 'lÿë àwòn òbí nínû ètò ìgbéyàwó ni', '["ìjòhçn","ìwádìí","aýò ríra","eyín pípa."]', 'lÿë àwòn òbí nínû ètò ìgbéyàwó ni ìwádìí.', '{"bold":["ìwádìí"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6e2a3230-5a98-4086-989a-81885c104595', 'English Language', 'JAMB', null, 2007, null, 'He started his career as an <u>__________</u> teacher.', null, '["auxillary","auxilliary","auxiliary","auxillary"]', 2, 'Correct spelling: auxiliary.', true, '2026-10-24 07:21:36.369', '2026-10-24 07:21:36.369', null, null, null, 'He started his career as an <u>__________</u> teacher.', '["auxillary","auxilliary","auxiliary","auxillary"]', 'Correct spelling: auxiliary.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6e2d1098-593f-4c9e-b636-481cee1b702b', 'Physics', 'JAMB', null, 2026, null, 'Which of the following materials is a good insulator?', null, '["Silver","Water","Graphene","Copper","rubber"]', 4, 'Rubber is a good insulator. Insulators are materials that do not allow electric current to flow easily because they have no free electrons. Rubber, plastic, glass, and dry wood are good insulators. Silver, copper, and graphene are excellent conductors. Water can conduct if it contains dissolved ions.', true, '2026-09-10 10:56:38.378', '2026-09-10 10:56:38.378', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6e2ec22a-f177-40c1-b489-fcc3be17a76b', 'English Language', 'JAMB', null, 2024, null, 'Sally assisted me in buying my ______ yesterday', null, '["very first party dress","first very party dress","party very first dress","party dress first very"]', 0, 'The correct order of adjectives is: opinion, size, age, shape, colour, origin, material, purpose. "Very first party dress" is correct.', true, '2026-09-18 09:43:02.257', '2026-09-18 09:43:02.257', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6e2f08af-8888-4ca7-a298-3074a465f746', 'Physics', 'JAMB', null, 1987, null, 'The vacuum in the Thermos flask helps to reduce heat transfer by', null, '["Convection and radiation","Convection and conduction","Conduction and radiation","Radiation only."]', 1, 'A vacuum has no particles, so neither conduction nor convection can occur across it. Radiation is reduced by the silvered walls.', true, '2026-10-12 19:15:25.532', '2026-10-12 19:15:25.532', null, null, null, 'The vacuum in the Thermos flask helps to reduce heat transfer by', '["Convection and radiation","Convection and conduction","Conduction and radiation","Radiation only."]', 'A vacuum has no particles, so neither conduction nor convection can occur across it. Radiation is reduced by the silvered walls.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6e3e71b6-a665-4f8d-ba2b-eec363edfac4', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The economic situation in the country is obviously <u>gloomy</u>.', null, '["encouraging","moody","unknown","regrettable"]', 0, 'Gloomy = depressing; opposite = encouraging.', true, '2026-10-24 07:21:14.477', '2026-10-24 07:21:14.477', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The economic situation in the country is obviously <u>gloomy</u>.', '["encouraging","moody","unknown","regrettable"]', 'Gloomy = depressing; opposite = encouraging.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6e41089b-b17c-4c4e-b4ca-d2735dae59eb', 'Biology', 'JAMB', null, 2026, null, 'If water that has been coloured red is poured at the base of a wilting plant, it will appear as a red stain in the cells of the', null, '["xylem","epidermis","phloem","parenchyma"]', 0, 'The red stain will appear in the xylem cells. The xylem is responsible for transporting water and dissolved minerals from the roots upward through the plant. When colored water is added at the base, it is taken up by root hairs, passes through the root cortex, and moves up the stem through the xylem vessels and tracheids. This is why xylem is often called the water-conducting tissue. The phloem transports sugars. The epidermis is the outer protective layer. Parenchyma cells are storage tissue.', true, '2026-09-09 03:18:44.609', '2026-09-09 03:18:44.609', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6e4828d5-8c7b-4d25-a7d6-6db6dc5aca78', 'Literature in English', 'JAMB', null, 2026, null, 'In the poem, the ''waiting jeep'' symbolizes', null, '["oppression","wealth","freedom","adventure"]', 0, 'The waiting jeep symbolizes oppression.', true, '2026-09-12 11:13:42.604', '2026-09-12 11:13:42.604', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6e4acf7e-5821-47cd-b80d-de80a9c98c90', 'Biology', 'JAMB', null, 2026, null, 'The part of a domestic fowl responsible for preventing heat loss is the', null, '["Filoplume","Contour feather","Down feather","Quill"]', 2, 'Down feathers are soft, fluffy feathers located beneath the contour feathers. Their structure lacks interlocking barbules, creating air pockets that trap heat close to the body, providing excellent insulation against heat loss. Filoplumes are hair-like feathers with sensory functions. Contour feathers provide shape, waterproofing, and flight capability. The quill is the hollow shaft of a feather. Down feathers are the primary insulation in birds, similar to the function of underfur in mammals, and are especially important in cold environments.', true, '2026-09-09 03:18:24.545', '2026-09-09 03:18:24.545', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6e4cf283-0bdd-41ea-8ef0-025cd9715536', 'Biology', 'JAMB', null, 2026, null, 'Evidence of a common ancestry for fishes, amphibians, reptiles, birds and mammals is the', null, '["possession of wings by birds and wings","cold bloodedness of fishes, amphibians and reptiles","presence of gill clefts in vertebrate embryos","possession of scales by fishes and reptiles"]', 2, 'Evidence of a common ancestry for fishes, amphibians, reptiles, birds, and mammals is the presence of gill clefts in vertebrate embryos. This is an example of embryological evidence for evolution. All vertebrate embryos show gill slits and similar early developmental patterns, suggesting a common ancestor. Wings and scales are not found in all these groups. Cold bloodedness is not shared by birds and mammals.', true, '2026-09-09 03:19:21.891', '2026-09-09 03:19:21.891', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6e65f27d-d6df-402f-a5ce-dc477f2450c3', 'Financial Accounting', 'UTME', null, 2004, null, 'When assets are realized during partnership dissolution, the entries for the proceeds are to debit', null, '["cash account and credit realization account","asset account and credit realization account","realization account and credit cash account","asset account and credit cash account"]', 0, 'Cash Account will be debited and Realization Account will be credited with proceeds of assets to follow the principle of Debit the Receiver and Credit the Giver.', true, '2026-10-12 22:00:03.722', '2026-10-12 22:00:03.722', null, null, null, 'When assets are realized during partnership dissolution, the entries for the proceeds are to debit', '["<b>cash account and credit realization account</b>","asset account and credit realization account","realization account and credit cash account","asset account and credit cash account"]', '<b>Cash Account</b> will be debited and Realization Account will be credited with proceeds of assets to follow the principle of Debit the Receiver and Credit the Giver.', '{"bold":["Cash Account"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6e7da39f-7342-4c9c-a752-ee2bf9135f75', 'Government', 'JAMB', null, 2026, null, 'All the following are merits of the indirect rule except', null, '["it preserved pre-colonial traditional institutions","It made people familiar with the government","It trained future leaders","It gives traditional rulers opportunity to participate in the act of government"]', 2, 'Training future leaders was not a merit of indirect rule.', true, '2026-09-12 11:24:08.402', '2026-09-12 11:24:08.402', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6ea94750-512d-48fe-a0aa-73c2016977f4', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'The covenant between God and Abraham in Genesis 15 was ratified through', null, '["circumcision","animal sacrifice","a burnt offering","a grain offering"]', 1, 'In Genesis 15, God made a covenant with Abraham through a ritual involving animal sacrifice. Abraham brought a heifer, a goat, a ram, a turtledove, and a young pigeon, divided them, and God passed between the pieces as a flaming torch and smoking firepot.', true, '2026-09-12 09:45:44.649', '2026-09-12 09:45:44.649', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6eaa3a7a-be22-4911-a0dd-e09db25458a4', 'Chemistry', 'JAMB', null, 2026, null, 'The oxidizing agent in the reaction, 3Br2 + 6OH- = BrO3- + 5Br- + 3H2O is', null, '["Br2","OH-","BrO3-","e-"]', 0, 'Bromine (Br2) undergoes disproportionation, serving as both an oxidizing agent (reduced to Br-) and a reducing agent (oxidized to BrO3-).', true, '2026-09-09 17:12:47.048', '2026-09-09 17:12:47.048', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6eb2b40f-7493-4c11-80b9-4cfed5681815', 'Chemistry', 'JAMB', null, 2026, null, 'The order in which a mixture of sand, ammonium chloride and sodium chloride can be separated', null, '["dissolution > filtration > sublimation > evaporation","dissolution > dryness > filtration > evaporation","sublimation > dissolution > filtration > evaporation","filtration > sublimation > evaporation > dryness"]', 2, 'Ammonium chloride sublimes upon heating and is collected first. Dissolving the residue in water leaves sand, which is filtered out, and the filtrate is evaporated to obtain sodium chloride.', true, '2026-09-09 17:12:45.084', '2026-09-09 17:12:45.084', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6eb2bab8-79ec-4088-ba71-a626e4984a02', 'Biology', 'JAMB', null, 2026, null, 'Which plant hormone is responsible for inhibiting growth and promoting dormancy in seeds?', null, '["Auxin","Cytokinins","Abscisic acid","Ethylene"]', 2, 'Abscisic acid (ABA) is the plant hormone that promotes seed dormancy and inhibits growth. It maintains dormancy during seed development and prevents premature germination. ABA also triggers stomatal closure during water stress. Auxin promotes cell elongation and root initiation. Cytokinins promote cell division and delay senescence. Ethylene promotes fruit ripening and abscission. The balance between ABA and gibberellins (which promote germination) determines whether seeds remain dormant or germinate. ABA levels decrease during imbibition to allow germination.', true, '2026-09-09 03:18:35.905', '2026-09-09 03:18:35.905', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6ec1dba7-93d6-4605-9134-d1815c698e12', 'Physics', 'JAMB', null, 1985, null, 'Which of the following phenomena CANNOT be explained by the molecular theory of matter?', null, '["Expansion","Conduction","Convection","Radiation","Evaporation."]', 3, 'Radiation needs no material medium and travels as electromagnetic waves, so it cannot be explained by molecular motion.', true, '2026-10-12 19:15:21.637', '2026-10-12 19:15:21.637', null, null, null, 'Which of the following phenomena <b>CANNOT</b> be explained by the molecular theory of matter?', '["Expansion","Conduction","Convection","Radiation","Evaporation."]', 'Radiation needs no material medium and travels as electromagnetic waves, so it cannot be explained by molecular motion.', '{"bold":["CANNOT"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6ec3d75e-4790-498f-ba3f-6332a7cac03c', 'English Language', 'JAMB', null, 2007, null, 'The Dark Continent was an <u>__________</u> for Africa', null, '["abuse","enigma","eclectic","epithet"]', 3, 'Correct spelling: epithet.', true, '2026-10-24 07:21:45.877', '2026-10-24 07:21:45.877', null, null, null, 'The Dark Continent was an <u>__________</u> for Africa', '["abuse","enigma","eclectic","epithet"]', 'Correct spelling: epithet.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6edb7b39-5f3c-454f-9d35-1f2dbaf29ea0', 'Biology', 'JAMB', null, 2003, null, 'If water that has been coloured red is poured at the base of a wilting plant, it will appear as a red stain in the cell of the', null, '["xylem","epidermis","phloem","parenchyma"]', 0, 'Water moves through the xylem.', true, '2026-10-12 20:59:32.572', '2026-10-12 20:59:32.572', null, null, null, 'If water that has been coloured red is poured at the base of a wilting plant, it will appear as a red stain in the cell of the', '["xylem","epidermis","phloem","parenchyma"]', 'Water moves through the xylem.', '{"bold":["xylem"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6ee6ba51-6250-4d85-aff7-49a6c6cdc2c2', 'Yoruba', 'JAMB', null, 2002, null, 'Ìwé Àjà ló Ìçrù ni ìbèèrè 32 -34 dá lé. Níbo ni àwòn ólòpaà ti rí oko igbó?', null, '["Ìbàdàn","Àkánrán","Abèòkúta","Ìkèrèkú"]', 3, 'Ìkèrèkú ni àwòn ólòpaà ti rí oko igbó.', true, '2026-10-13 13:22:39.725', '2026-10-13 13:22:39.725', null, null, null, 'Ìwé Àjà ló Ìçrù ni ìbèèrè 32 -34 dá lé. Níbo ni àwòn ólòpaà ti rí oko igbó?', '["Ìbàdàn","Àkánrán","Abèòkúta","Ìkèrèkú"]', 'Ìkèrèkú ni àwòn ólòpaà ti rí oko igbó.', '{"bold":["Ìkèrèkú"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6eebfa42-e309-4dac-b8de-a8ca12dbb012', 'Physics', 'JAMB', null, 1988, null, 'The product PV, where P is pressure and V is volume, has the same unit as', null, '["Force","Power","Energy","Acceleration"]', 2, 'Pressure x volume = (N m⁻²)(m³) = N m = joule, which is the unit of energy.', true, '2026-10-12 19:15:27.318', '2026-10-12 19:15:27.318', null, null, null, 'The product PV, where P is pressure and V is volume, has the same unit as', '["Force","Power","Energy","Acceleration"]', 'Pressure x volume = (N m<sup>-2</sup>)(m<sup>3</sup>) = N m = joule, which is the unit of energy.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6ef431eb-975a-470b-8ad7-f035a711f71f', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Solomon''s request for wisdom pleased God because it showed', null, '["humility and discernment","ambition for power","desire for wealth","fear of enemies"]', 0, 'Solomon''s request for wisdom pleased God because it showed humility and discernment. He did not ask for wealth, long life, or the lives of his enemies, but for an understanding mind to govern God''s people. God granted him wisdom and also added what he did not ask for.', true, '2026-09-12 09:45:47.327', '2026-09-12 09:45:47.327', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6f268509-5a41-4e65-9e7a-028bf765c914', 'Chemistry', 'JAMB', null, 2026, null, 'In which of these will equilibrium shift to right when pressure is increased? I) C(s) + O₂(g) ⇌ CO₂(g) ii) CaCO₃(s) ⇌ CaO(s) + CO₂(g) iii) 2Mg(s) + O₂(g) ⇌ 2MgO(s) iv) 2H₂(g) + O₂(g) ⇌ 2H₂O(g)', null, '["I, iv only","ii only","iii only","iv only"]', 2, 'Increasing pressure shifts equilibrium to the side with fewer gas moles. For (iii), 1 gas mole on left, 0 on right.', true, '2026-09-12 11:36:16.465', '2026-09-12 11:36:16.465', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6f3652fe-2b74-4daf-b4be-68ec22839239', 'Government', 'JAMB', null, 2026, null, 'Indirect rule as a British Colonial policy was first introduced in', null, '["Nigeria","India","Uganda","Ghana"]', 1, 'Indirect rule was first introduced in India before being used in Africa.', true, '2026-09-12 11:24:11.227', '2026-09-12 11:24:11.227', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6f3afa93-cfe1-4b14-9800-c4829a59a060', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Gideon was called Jerubbaal because', null, '["he broke down the altar of Baal","he defeated the Midianites","he sacrificed to Baal","his father''s name was Baal","the people did not like him"]', 0, 'Gideon broke down the altar of Baal, so he was called Jerubbaal.', true, '2026-09-12 10:41:35.3', '2026-09-12 10:41:35.3', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('6f431f70-c92e-429d-9f7e-9925b7e82b0a', 'testing', 'JAMB', null, 2024, null, 'The university has been TEMPORARILY closed.', null, '["has the college been temporarily closed?","has the University been temporarily opened?","has the university been Permanently closed?","has the university been Permanently opened?"]', 1, 'Correct question form retains meaning; ''college'' is synonym for university.', true, '2026-10-31 16:48:53.269', '2026-10-31 16:48:53.269', null, null, null, 'The university has been TEMPORARILY closed.', '["has the college been temporarily closed?","has the University been temporarily opened?","has the university been Permanently closed?","has the university been Permanently opened?"]', 'Correct question form retains meaning; ''college'' is synonym for university.', '{}');
