insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('705c029c-b5d9-4b4d-a0b7-0f97d041651f', 'Physics', 'JAMB', null, 1990, null, 'When light is incident on an object which is magenta in colour, which of the following colours will be absorbed?', null, '["Red and blue","Green only","Red and green","Red only."]', 1, 'Magenta is red + blue. A magenta object reflects red and blue and absorbs green.', true, '2026-10-12 19:15:31.464', '2026-10-12 19:15:31.464', null, null, null, 'When light is incident on an object which is magenta in colour, which of the following colours will be absorbed?', '["Red and blue","Green only","Red and green","Red only."]', 'Magenta is red + blue. A magenta object reflects red and blue and absorbs green.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7064dcbc-ed91-435c-9616-95586b6f1175', 'Economics', 'JAMB', null, 2026, null, 'The main function of NNPC is to...', null, '["develop the oil producing areas","fix the price of petroleum products","ensure regular supply of oil","oversee the development of the oil sector"]', 3, 'NNPC oversees the development of the oil sector in Nigeria.', true, '2026-09-12 11:00:42.21', '2026-09-12 11:00:42.21', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('706895a1-01b1-481a-bd67-41b8aaa8969e', 'Physics', 'JAMB', null, 2003, null, 'A piece of stone attached to one end of a string is whirled round in a horizontal circle and the string suddenly breaks. The stone will fly off in a direction', null, '["Tangential to the circular path","Perpendicular to the circular path","Towards the centre of the circle","Parallel to the circular path."]', 0, 'With no centripetal force, the stone moves in a straight line along the direction of its velocity at that instant, which is tangential to the circle.', true, '2026-10-12 19:15:55.048', '2026-10-12 19:15:55.048', null, null, null, 'A piece of stone attached to one end of a string is whirled round in a horizontal circle and the string suddenly breaks. The stone will fly off in a direction', '["Tangential to the circular path","Perpendicular to the circular path","Towards the centre of the circle","Parallel to the circular path."]', 'With no centripetal force, the stone moves in a straight line along the direction of its velocity at that instant, which is tangential to the circle.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('706fb423-2591-486a-931b-bb0c8da16f95', 'Literature in English', 'JAMB', null, 2026, null, 'The narrative technique employed in Path of Lucas: The Journey He Endured is best described as', null, '["A first-person autobiographical account limited to a single perspective","A third-person narrative that explores the protagonist''s internal and external conflicts","A purely epistolary structure based on letters","A dramatic script with dialogue only"]', 1, 'The narrative technique is third-person, exploring internal and external conflicts.', true, '2026-09-12 11:09:52.243', '2026-09-12 11:09:52.243', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7077acf2-7049-4d46-81f9-a2b1b53519c1', 'Yoruba', 'JAMB', null, 2002, null, 'Órò wo ní kò ní apààlà sílébù nínú Olú á ra bàtà?', null, '["Olú","á","ra","bàtà."]', 1, 'Á ni kò ní apààlà sílébù nínú gbólóhùn náà.', true, '2026-10-13 13:22:38.305', '2026-10-13 13:22:38.305', null, null, null, 'Órò wo ní kò ní apààlà sílébù nínú Olú á ra bàtà?', '["Olú","á","ra","bàtà."]', 'Á ni kò ní apààlà sílébù nínú gbólóhùn náà.', '{"bold":["Á"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7087d44a-f791-4e38-a28d-6130fe9ffdac', 'English Language', 'JAMB', null, 2007, null, 'This professor of <u>__________</u> medicine has <u>__________</u> the mystery of bird flu.', null, '["vetinary/unraveled","vertrinary/unraveled","veteinary/unraveled","veterinary/unraveled"]', 3, 'Correct forms: veterinary/unraveled.', true, '2026-10-24 07:21:36.47', '2026-10-24 07:21:36.47', null, null, null, 'This professor of <u>__________</u> medicine has <u>__________</u> the mystery of bird flu.', '["vetinary/unraveled","vertrinary/unraveled","veteinary/unraveled","veterinary/unraveled"]', 'Correct forms: veterinary/unraveled.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7094f3d3-c5ab-4d9a-a7ab-f50a0a305ffb', 'Biology', 'JAMB', null, 2001, null, 'The gas produced during tissues respiration can be identified by using', null, '["sodium hydroxide","calcium carbonate","copper sulphate","calcium hydroxide"]', 3, 'Calcium hydroxide (limewater) turns milky in the presence of carbon dioxide.', true, '2026-10-12 20:59:28.539', '2026-10-12 20:59:28.539', null, null, null, 'The gas produced during tissues respiration can be identified by using', '["sodium hydroxide","calcium carbonate","copper sulphate","calcium hydroxide"]', 'Calcium hydroxide (limewater) turns milky in the presence of carbon dioxide.', '{"bold":["Calcium hydroxide"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('709c3338-e9c1-4fc1-a60d-b73f0f79e95c', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. All the efforts made to settle the quarrel were <u>futile</u>.', null, '["successful","wicked","reasonable","remarkable","fruitless"]', 4, 'Futile = fruitless/useless.', true, '2026-10-24 01:03:53.274', '2026-10-24 01:03:53.274', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. All the efforts made to settle the quarrel were <u>futile</u>.', '["successful","wicked","reasonable","remarkable","<u>fruitless</u>"]', '<b>Futile</b> = <b>fruitless/useless</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('709e96de-67fb-46bd-b767-7ad920a0c406', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). She realised that she was <u>up against</u> stiff competition when a new large departmental store was opened next to her small provisions shop.', null, '["next to","standing next to","opposed to","faced with"]', 3, '''Up against'' = faced with.', true, '2026-10-24 01:02:03.406', '2026-10-24 01:02:03.406', null, null, null, '(Choose the most appropriate interpretation). She realised that she was <u>up against</u> stiff competition when a new large departmental store was opened next to her small provisions shop.', '["next to","standing next to","opposed to","<u>faced with</u>"]', '''<b>Up against</b>'' = <b>faced with</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('70b37625-4203-4d58-8920-c89e575486c7', 'General Mathematics', 'JAMB', null, 2026, null, 'From the top of a tower of height 60m, the angles of depression of the top and the bottom of a building are observed to be 30° and 60° respectively. Find the height of the building.', null, '["80m","40m","30m","20m"]', 2, 'Let height of building = h. Distance = 60/tan60° = 60/√3 = 20√3. Also (60-h)/20√3 = tan30° = 1/√3. 60-h = 20. h = 40m. The answer is (B) 40m.', true, '2026-09-12 11:43:55.035', '2026-09-12 11:43:55.035', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('70b7406a-8604-4035-9414-7be60b143cf1', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The Military Governor <u>upheld</u> the decision of his cabinet.', null, '["held up","undercut","maintained","abolished","reversed"]', 4, 'Upheld = maintained; opposite = reversed.', true, '2026-10-24 07:21:10.86', '2026-10-24 07:21:10.86', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The Military Governor <u>upheld</u> the decision of his cabinet.', '["held up","undercut","maintained","abolished","reversed"]', 'Upheld = maintained; opposite = reversed.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('70bacab9-cca1-4a34-88ce-70bd3652e252', 'Literature in English', 'JAMB', null, 2026, null, 'The phrase ''horrors of red corals'' is an example of', null, '["an oxymoron","simile","visual imagery","euphemism"]', 2, '''Horrors of red corals'' is visual imagery.', true, '2026-09-12 11:07:23.836', '2026-09-12 11:07:23.836', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('70bbd92c-25fa-4c75-8c44-1f6650f4dca5', 'Biology', 'JAMB', null, 2010, null, 'If both parents are heterozygous for a trait, the probability that an offspring will be recessive for that trait is', null, '["3/4","1/2","1/4","1"]', 2, 'Two heterozygous parents produce 1/4 recessive offspring.', true, '2026-10-12 20:59:41.342', '2026-10-12 20:59:41.342', null, null, null, 'If both parents are heterozygous for a trait, the probability that an offspring will be recessive for that trait is', '["3/4","1/2","1/4","1"]', 'Two heterozygous parents produce 1/4 recessive offspring.', '{"bold":["1/4"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('70c465da-bc95-4fe9-aaa3-e3250ceb287f', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Jesus declared that men loved darkness rather than light because', null, '["their hearts were hardened","their deeds were evil","they had no truth","they had been blinded"]', 1, 'Men loved darkness because their deeds were evil.', true, '2026-09-12 10:41:57.13', '2026-09-12 10:41:57.13', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('70c6698f-1c50-48fd-a988-0c1a76e6ff71', 'Literature in English', 'JAMB', null, 2026, null, 'Ananse is best described as a', null, '["tragic hero","comic trickster","villain","chorus"]', 1, 'Ananse is a comic trickster.', true, '2026-09-12 11:11:20.992', '2026-09-12 11:11:20.992', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('70cfbf98-657a-427e-bd0f-48939648dff4', 'Chemistry', 'JAMB', null, 2026, null, 'Element X forms an oxide with the formula X₂O₅ which dissolves in water to form an acidic solution. Which statement about element X is most likely correct?', null, '["X is a highly reactive metal","X is most likely a non-metal in group 15","X forms basic oxides in all reactions","X readily forms positive ions in solution"]', 1, 'The oxide X₂O₅ is acidic (dissolves in water to form an acidic solution). Non-metals in Group 15 (e.g., nitrogen, phosphorus) form acidic oxides with the general formula X₂O₅. For example, P₂O₅ dissolves in water to form phosphoric acid. Metals form basic oxides, so X is most likely a non-metal in Group 15.', true, '2026-09-12 09:38:03.014', '2026-09-12 09:38:03.014', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('70d6a1ad-b9c7-406c-9845-c6380e09526c', 'Physics', 'JAMB', null, 1983, null, 'If the force on a charge of 0.2 coulomb in an electric field is 4 N, then the electric field intensity of the field is', null, '["0.8","0.8 N/C","20.0 N/C","4.2 N/C","20.0 C/N"]', 2, 'Electric field intensity E = F/q = 4/0.2 = 20.0 N/C.', true, '2026-10-12 19:15:18.202', '2026-10-12 19:15:18.202', null, null, null, 'If the force on a charge of 0.2 coulomb in an electric field is 4 N, then the electric field intensity of the field is', '["0.8","0.8 N/C","20.0 N/C","4.2 N/C","20.0 C/N"]', 'Electric field intensity E = F/q = 4/0.2 = 20.0 N/C.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('70d8a90d-6dad-4db3-ac5a-156c0429873b', 'Literature in English', 'JAMB', null, 2026, null, 'Iya Agba helped Desola and Odekunle to', null, '["place a curse on Ajanaku","Re-order their lives","cast a spell on Ajanaku","expose Serubawon''s atrocities"]', 1, 'Iya Agba helped them re-order their lives.', true, '2026-09-12 11:07:30.748', '2026-09-12 11:07:30.748', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('70db2f4c-0b4b-4da4-a5bc-5a63f029f4df', 'Literature in English', 'JAMB', null, 2026, null, '______ is Bathos', null, '["climax","anti-climax","exposition","resolution"]', 1, 'Bathos is anti-climax.', true, '2026-09-12 11:12:12.021', '2026-09-12 11:12:12.021', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('70ee30f0-ccfd-42c6-a88b-bac1973a6421', 'English Language', 'JAMB', null, 2024, null, '(opposite in meaning) His father surmounted the myriad of obstacles on his way.', null, '["Most","Few","All","Many"]', 1, '"Myriad" means many; the opposite is "few."', true, '2026-09-18 09:24:04.768', '2026-09-18 09:24:04.768', null, null, 'STANDALONE', null, null, null, null);
