insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('711b2d75-8fa5-42ab-ae00-9f95b01af4a7', 'English Language', 'JAMB', null, 2007, null, 'Only observers from the Ministry of Works <u>-----</u> allowed into the conference room.', null, '["is","are","have","been"]', 1, 'Plural ''observers'' â†’ are.', true, '2026-10-24 01:02:13.005', '2026-10-24 01:02:13.005', null, null, null, 'Only observers from the Ministry of Works <u>-----</u> allowed into the conference room.', '["is","<u>are</u>","have","been"]', 'Plural ''<b>observers</b>'' â†’ <b>are</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('715d4f15-f701-44b1-b3d4-6a0686269de3', 'Biology', 'JAMB', null, 2003, null, 'The two key cations involved in the action potential of nervous transmissions are', null, '["Na+ and Fe2+","Mg2+ and K+","Na and K","Fe2+ and Mg2+"]', 2, 'Sodium and potassium ions are essential for generating the electrical action potential in neurons.', true, '2026-10-12 20:05:11.607', '2026-10-12 20:05:11.607', null, null, null, 'The two key cations involved in the action potential of nervous transmissions are', '["Na+ and Fe2+","Mg2+ and K+","Na and K","Fe2+ and Mg2+"]', 'Sodium and potassium ions are essential for generating the electrical action potential in neurons.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('715fcec0-1153-4b66-9090-e27d037e0eb8', 'English Language', 'JAMB', null, 2007, null, 'A nursery rhyme is used to teach pupils how to spell the word <u>__________</u>', null, '["hippopotemus","hippopottomuse","hipopotamus","hippopotamus"]', 3, 'Correct spelling: hippopotamus.', true, '2026-10-24 07:21:36.169', '2026-10-24 07:21:36.169', null, null, null, 'A nursery rhyme is used to teach pupils how to spell the word <u>__________</u>', '["hippopotemus","hippopottomuse","hipopotamus","hippopotamus"]', 'Correct spelling: hippopotamus.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7168f44e-755c-4c23-bb29-6ce68699c41c', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). In his own story, the thief claimed that he had been <u>led astray</u> by a friend.', null, '["closely followed by a friend","searching for him","tagging him a talebearer","misguided by a friend"]', 3, '''Led astray'' = misguided.', true, '2026-10-24 01:02:06.748', '2026-10-24 01:02:06.748', null, null, null, '(Choose the most appropriate interpretation). In his own story, the thief claimed that he had been <u>led astray</u> by a friend.', '["closely followed by a friend","searching for him","tagging him a talebearer","<u>misguided by a friend</u>"]', '''<b>Led astray</b>'' = <b>misguided</b>.', '{}');
