insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('71a2d94e-19f3-42e0-b874-ae003ee2d1d0', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). Thousands of students <u>are candidates for</u> the examination but only very few pass.', null, '["come into","call for","go into","enter for","turn up for"]', 3, '''Enter for'' = register as candidate.', true, '2026-10-24 01:04:14.391', '2026-10-24 01:04:14.391', null, null, null, '(Choose the most appropriate interpretation). Thousands of students <u>are candidates for</u> the examination but only very few pass.', '["come into","call for","go into","<u>enter for</u>","turn up for"]', '''<b>Enter for</b>'' = <b>register as candidate</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('71bf44d7-f69b-4038-874f-4b68c5b113b8', 'English Language', 'JAMB', null, 2007, null, 'The politicians are responsible for the <u>__________</u> of events that have taken place in this country', null, '["course","curse","coarse","cause","corse"]', 0, 'Correct spelling: course.', true, '2026-10-24 07:21:40.73', '2026-10-24 07:21:40.73', null, null, null, 'The politicians are responsible for the <u>__________</u> of events that have taken place in this country', '["course","curse","coarse","cause","corse"]', 'Correct spelling: course.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('71c30f91-15ed-44fe-a6f6-82117c3347e8', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). Uche''s mother advised him to talk very little because <u>still waters run deep</u>.', null, '["his enemies may be listening","there is no pride in talking too much","there is wisdom in silence","talking too much could lead him into trouble"]', 2, '''Still waters run deep'' = wisdom in silence.', true, '2026-10-24 01:04:21.148', '2026-10-24 01:04:21.148', null, null, null, '(Choose the most appropriate interpretation). Uche''s mother advised him to talk very little because <u>still waters run deep</u>.', '["his enemies may be listening","there is no pride in talking too much","<u>there is wisdom in silence</u>","talking too much could lead him into trouble"]', '''<b>Still waters run deep</b>'' = <b>wisdom in silence</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('71c78f4d-71e3-4298-83c6-6a3136ec3678', 'Yoruba', 'JAMB', null, 2002, null, '‘Iwò n/ Nínú gbólóhùn yìí, n/ jè òrõ', null, '["atòkùn","orúkò","ìyè","àpèjùwe."]', 2, 'Nínú gbólóhùn yìí, n/ jè òrõ ìyè.', true, '2026-10-13 13:22:38.524', '2026-10-13 13:22:38.524', null, null, null, '‘Iwò n/ Nínú gbólóhùn yìí, n/ jè òrõ', '["atòkùn","orúkò","ìyè","àpèjùwe."]', 'Nínú gbólóhùn yìí, n/ jè òrõ ìyè.', '{"bold":["ìyè"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('71e35b59-8c07-48c8-9354-2a1ceb23bb0b', 'Financial Accounting', 'UTME', null, 2002, null, 'What is the gross profit carried to the profit and loss account?', 'https://res.cloudinary.com/kwi1uv0g/image/upload/v1791840909/questions/sugiapjvvd2x3zho78f0.jpg', '["N 1820","N 1640","N 1530","N 1500"]', 0, 'Cash Sales 9160 - Opening stock 400 + Goods sent less Returns 7660 - Closing Stock 720 = 1820.', true, '2026-10-12 21:59:57.71', '2026-10-12 21:59:57.71', null, null, null, 'What is the gross profit carried to the profit and loss account?', '["<b>N 1820</b>","N 1640","N 1530","N 1500"]', 'Cash Sales 9160 - Opening stock 400 + Goods sent less Returns 7660 - Closing Stock 720 = <b>1820</b>.', '{"bold":["1820"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7200a121-1e30-4758-bba1-46ace23855a7', 'English Language', 'JAMB', null, 2007, null, 'The <u>__________</u> event marked the beginning of a new life for the entire cabinet.', null, '["historic","history of the","historicity of the","historical"]', 0, 'Correct spelling: historic.', true, '2026-10-24 07:21:36.219', '2026-10-24 07:21:36.219', null, null, null, 'The <u>__________</u> event marked the beginning of a new life for the entire cabinet.', '["historic","history of the","historicity of the","historical"]', 'Correct spelling: historic.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('72026d19-a0e4-4390-a110-69f9411cc323', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The lamb is a <u>feeble</u> little animal.', null, '["quite","loving","weak","fat"]', 2, 'Feeble = weak.', true, '2026-10-24 01:01:58.45', '2026-10-24 01:01:58.45', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The lamb is a <u>feeble</u> little animal.', '["quite","loving","<u>weak</u>","fat"]', '<b>Feeble</b> = <b>weak</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('720ca9aa-9812-49ba-8c30-6b5fb21357f5', 'General Mathematics', 'JAMB', null, 2026, null, 'Integrate (1-x)/x³ with respect to x', null, '["1/x - 1/(2x²) + K","1/x - 1/(2x²) - K","1/x + 1/(2x²) + K","1/x - 1/x² + K"]', 0, '∫(x⁻³ - x⁻²)dx = -1/(2x²) + 1/x + K = 1/x - 1/(2x²) + K.', true, '2026-09-12 11:44:18.807', '2026-09-12 11:44:18.807', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7210fb0b-a33b-4cec-848f-e8ed422c9bcf', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). Jummai''s father remarked that <u>pigs would fly</u> before she passed', null, '["It would be possible to pass only if she worked harder","It would never be possible for her to pass","He would have to bribe her teachers to enable her to pass","She would have to cheat in order to pass"]', 1, '''Pigs would fly'' = never happen.', true, '2026-10-24 01:02:11.056', '2026-10-24 01:02:11.056', null, null, null, '(Choose the most appropriate interpretation). Jummai''s father remarked that <u>pigs would fly</u> before she passed', '["It would be possible to pass only if she worked harder","<u>It would never be possible for her to pass</u>","He would have to bribe her teachers to enable her to pass","She would have to cheat in order to pass"]', '''<b>Pigs would fly</b>'' = <b>never happen</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7217febd-7ea3-4b7d-92a3-7b82c78725cd', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'According to Paul in Philippians, Jesus demonstrated humility when He', null, '["Likened Himself to God","had pity on the possessed man","took the form of man","forgave those who crucified Him"]', 2, 'According to Philippians 2, Jesus demonstrated humility when He took the form of a servant and was born in the likeness of men. Though He was in the form of God, He emptied Himself and became obedient unto death.', true, '2026-09-12 09:46:15.77', '2026-09-12 09:46:15.77', null, null, null, null, null, null, null);
