insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7524a257-8f68-4d2c-af7a-3c4f78dc5b22', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Following the death of Stephen, the only group of believers not scattered by the persecution against the Jerusalem Church were...', null, '["deacons","apostles","prophets","disciples"]', 1, 'Acts 8:1 states that a great persecution arose against the church in Jerusalem and all except the apostles were scattered throughout Judea and Samaria.', true, '2026-09-09 17:18:25.581', '2026-09-09 17:18:25.581', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7526d7d0-22e2-4b8f-b41a-4acc904510ca', 'Financial Accounting', 'UTME', null, 2004, null, 'What is the goods manufactured?', 'https://res.cloudinary.com/kwi1uv0g/image/upload/v1791841865/questions/duqei6gxqpqc1un4ggty.jpg', '["N117 000","N104 000","N97 000","N93 000"]', 3, 'To ascertain goods manufactured: Raw Material used 18000 + Direct Labour 50000 = Prime Cost 68000. Factory Overhead: Indirect Labour 4000 + Factory supplies 7000 + Other Factory 19000 = 30000. 68000 + 30000 + Opening WIP 4000 - Closing WIP 9000 = 93000.', true, '2026-10-12 22:00:02.936', '2026-10-12 22:00:02.936', null, null, null, 'What is the goods manufactured?', '["N117 000","N104 000","N97 000","<b>N93 000</b>"]', 'To ascertain goods manufactured: Raw Material used 18000 + Direct Labour 50000 = Prime Cost 68000. Factory Overhead: Indirect Labour 4000 + Factory supplies 7000 + Other Factory 19000 = 30000. 68000 + 30000 + Opening WIP 4000 - Closing WIP 9000 = <b>93000</b>.', '{"bold":["93000"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('753939c2-c85c-48d8-a279-87bf6c067d1a', 'Financial Accounting', 'UTME', null, 2001, null, 'The excess of income over expenditure is usually transferred to the', null, '["accumulated fund","profit and loss account","current assets in the balance sheet","current liabilities in the balance sheet"]', 0, 'The excess of income over expenditure is usually transferred to the accumulated fund.', true, '2026-10-12 22:00:06.928', '2026-10-12 22:00:06.928', null, null, null, 'The excess of income over expenditure is usually transferred to the', '["<b>accumulated fund</b>","profit and loss account","current assets in the balance sheet","current liabilities in the balance sheet"]', 'The excess of income over expenditure is usually transferred to the <b>accumulated fund</b>.', '{"bold":["accumulated fund"],"italic":[],"underline":[],"fillBlanks":[]}');
