insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('75499f01-3bd7-4826-b9c9-70c60b8c4367', 'Biology', 'JAMB', null, 2005, null, 'Which of the following is the best explanation for a child who is phenotypically short and born of two tall parents?', null, '["the father possesses a gene for shortness","the mother possesses a gene for shortness","nature makes the child short","both parents possess genes for shortness"]', 3, 'Both parents possess recessive genes for shortness.', true, '2026-10-12 20:59:38.143', '2026-10-12 20:59:38.143', null, null, null, 'Which of the following is the best explanation for a child who is phenotypically short and born of two tall parents?', '["the father possesses a gene for shortness","the mother possesses a gene for shortness","nature makes the child short","both parents possess genes for shortness"]', 'Both parents possess recessive genes for shortness.', '{"bold":["Both parents possess recessive genes for shortness"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('754e5805-804d-4bf2-aa88-900cf81d3f58', 'Physics', 'JAMB', null, 2003, null, 'A ray incident on a glass prism undergoes minimum deviation when the', null, '["Refraction angle equals 90°","Incident angle is equal to the angle of refraction","Incident angle is equal to the angle of emergence","Incident angle equals 90°"]', 2, 'At minimum deviation the ray passes symmetrically through the prism, so the angle of incidence equals the angle of emergence.', true, '2026-10-12 19:15:56.579', '2026-10-12 19:15:56.579', null, null, null, 'A ray incident on a glass prism undergoes minimum deviation when the', '["Refraction angle equals 90°","Incident angle is equal to the angle of refraction","Incident angle is equal to the angle of emergence","Incident angle equals 90°"]', 'At minimum deviation the ray passes symmetrically through the prism, so the angle of incidence equals the angle of emergence.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
