insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('759b9526-6f4f-4541-90e8-9250c03b4e1b', 'Chemistry', 'JAMB', null, 2026, null, 'A mixture of iodine and sulphur crystals can be separated by treatment with', null, '["water to filter off sulphur","methanol to filter off iodine","ethanoic acid to filter off sulphur","carbon (IV) sulphide to filter off iodine"]', 3, 'Iodine dissolves in carbon disulphide while sulphur does not.', true, '2026-09-12 11:36:05.562', '2026-09-12 11:36:05.562', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('75a7bd1c-50c0-42ca-a704-d82149c1b0d1', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). We <u>made a pile</u> in the business deal.', null, '["cut corners","broke even","earned a lot of money","lost a lot of money"]', 2, '''Made a pile'' = earned a lot of money.', true, '2026-10-24 01:04:22.974', '2026-10-24 01:04:22.974', null, null, null, '(Choose the most appropriate interpretation). We <u>made a pile</u> in the business deal.', '["cut corners","broke even","<u>earned a lot of money</u>","lost a lot of money"]', '''<b>Made a pile</b>'' = <b>earned a lot of money</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('75bc0d3d-4d0a-4452-88d4-b147b0492684', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. I had to make my way through the <u>throng</u> of people in the church.', null, '["group","crowd","gathering","theme"]', 1, 'Throng = crowd.', true, '2026-10-24 01:01:56.125', '2026-10-24 01:01:56.125', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. I had to make my way through the <u>throng</u> of people in the church.', '["group","<u>crowd</u>","gathering","theme"]', '<b>Throng</b> = <b>crowd</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('75bc867c-546f-45db-b767-043750cd8fc0', 'Biology', 'JAMB', null, 2005, null, 'The urinary tubules of the kidney function through', null, '["osmosis and diffusion","active transport and osmosis","ultrafiltration and selective reabsorption","active transport and cytoplasmic streaming"]', 2, 'Urinary tubules function through ultrafiltration and selective reabsorption.', true, '2026-10-12 20:59:37.43', '2026-10-12 20:59:37.43', null, null, null, 'The urinary tubules of the kidney function through', '["osmosis and diffusion","active transport and osmosis","ultrafiltration and selective reabsorption","active transport and cytoplasmic streaming"]', 'Urinary tubules function through ultrafiltration and selective reabsorption.', '{"bold":["ultrafiltration and selective reabsorption"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('75c74bc8-451b-452f-8d26-54a54f687750', 'Biology', 'JAMB', null, 2026, null, 'The nitrogenous base not found in DNA is', null, '["cytosine","adenine","thymine","uracil"]', 3, 'Uracil is not found in DNA; it is found in RNA. In DNA, the four nitrogenous bases are adenine (A), thymine (T), cytosine (C), and guanine (G). In RNA, thymine is replaced by uracil (U). Uracil pairs with adenine in RNA during transcription. DNA uses thymine instead of uracil because thymine provides greater stability in the DNA double helix and allows for more efficient repair mechanisms. The presence of uracil in RNA is important for the ribosome''s role in protein synthesis.', true, '2026-09-09 03:18:40.444', '2026-09-09 03:18:40.444', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('75c94879-f9fa-494e-a781-7316dca303f5', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The minister''s anger was <u>aggravated</u> by the news of the disaster.', null, '["abated","magnified","intensified","impeded"]', 2, 'Aggravated = intensified.', true, '2026-10-24 01:04:00.603', '2026-10-24 01:04:00.603', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The minister''s anger was <u>aggravated</u> by the news of the disaster.', '["abated","magnified","<u>intensified</u>","impeded"]', '<b>Aggravated</b> = <b>intensified</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('75e073e9-866b-4631-b2f7-6eef96d38458', 'Chemistry', 'JAMB', null, 2026, null, 'In electrolysis, the cathode is defined as the electrode where', null, '["oxidation occurs","electrons are released","reduction occurs","positive ions are formed"]', 2, 'The cathode is the electrode where reduction occurs. Positive ions (cations) gain electrons at the cathode. The anode is where oxidation occurs (loss of electrons). A helpful mnemonic: ''Red Cat'' (Reduction at Cathode) and ''An Ox'' (Oxidation at Anode).', true, '2026-09-12 09:38:12.696', '2026-09-12 09:38:12.696', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('75ef7074-7d89-4eac-a224-fa8f70c9391d', 'Christian Religious Studies', 'JAMB', null, 2026, null, '''The very stone which the builders rejected has become the head of the corner.'' This statement by Peter was directed to those who', null, '["built the Temple of Jerusalem","did not believe in Jesus'' preciousness","are hard hearted against Jesus Christ","don''t offer spiritual sacrifice"]', 1, 'Peter quoted Psalm 118:22 about those who rejected Jesus.', true, '2026-09-12 10:41:44.064', '2026-09-12 10:41:44.064', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('75efc86d-be66-425e-bf66-c51419ed68fd', 'Literature in English', 'JAMB', null, 2026, null, 'The use of professional tools (clowns) in drama is primarily to', null, '["heighten emotion","create comic relief","develop plot","cause commotion"]', 1, 'Clowns create comic relief.', true, '2026-09-12 11:14:03.174', '2026-09-12 11:14:03.174', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('75fd80be-a819-45c1-92b2-2b659bfc8b13', 'Government', 'JAMB', null, 2026, null, 'The king that revolted against British invasion of Lagos in 1851 was', null, '["King Dosunmu","King Jaja","King Kosoko","King Akintoye"]', 2, 'The king that revolted against British invasion of Lagos in 1851 was King Kosoko. King Kosoko resisted British attempts to establish control over Lagos and continued the slave trade despite British abolition efforts. In 1851, the British bombarded Lagos and forced Kosoko to flee, replacing him with Akintoye who was more cooperative with British interests. This event marked the beginning of British colonial influence in Lagos.', true, '2026-09-10 10:44:18.347', '2026-09-10 10:44:18.347', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7602d7ba-0e2d-42b7-b811-e50974b88842', 'Chemistry', 'JAMB', null, 2026, null, 'Which of the following explains why sulfur dioxide dissolves readily in water but carbon dioxide dissolves only slightly?', null, '["Sulfur dioxide forms stronger covalent bonds","Sulfur dioxide reacts chemically with water to form an acid","Carbon dioxide molecules are larger","Carbon dioxide contains ionic bonds"]', 1, 'Sulfur dioxide reacts with water to form sulfurous acid (SO₂ + H₂O → H₂SO₃), which is highly soluble. Carbon dioxide also reacts with water to form carbonic acid (CO₂ + H₂O → H₂CO₃), but the reaction is much less extensive, so CO₂ is only slightly soluble. The chemical reaction with water is the key difference.', true, '2026-09-12 09:38:08.901', '2026-09-12 09:38:08.901', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('760c05ba-185f-41a2-8744-f362877c5f59', 'Biology', 'JAMB', null, 2026, null, 'Which of the following is a stem tuber? I. Sweet potato II. Yam III. Cassava IV. Ginger', null, '["III","III & IV","I, III & IV","II"]', 3, 'Yam is a stem tuber, which is a modified swollen stem that stores nutrients. Sweet potato is a root tuber (modified root for storage). Cassava is also a root tuber, not a stem tuber. Ginger is a rhizome (horizontal underground stem). Among these options, only yam is a stem tuber. Stem tubers (like yam and potato) have nodes (eyes) and internodes, while root tubers (like sweet potato and cassava) are swollen roots without nodes. Ginger is a rhizome with distinct nodes and internodes.', true, '2026-09-09 03:18:34.359', '2026-09-09 03:18:34.359', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7614bdcc-6381-4e14-b87e-167950b95c8c', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. My father''s advice to me was quite <u>invaluable</u>.', null, '["useless","useful","helpful","unsolicited"]', 0, 'Invaluable = priceless; opposite = useless.', true, '2026-10-24 07:21:19.678', '2026-10-24 07:21:19.678', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. My father''s advice to me was quite <u>invaluable</u>.', '["useless","useful","helpful","unsolicited"]', 'Invaluable = priceless; opposite = useless.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('76150a28-fcaf-4b86-958f-386b6c968cf6', 'Biology', 'JAMB', null, 2026, null, 'Adaptation radiation is illustrated in', null, '["modified insect mouth parts","dentition in mammals","wings in birds and bats","appendages in insects"]', 0, 'Adaptive radiation is illustrated in modified insect mouth parts. Insects have evolved a wide variety of mouth parts for different feeding strategies (chewing, sucking, piercing, sponging) from a common ancestral form. This is an example of divergent evolution from a common ancestor. Dentition in mammals, wings in birds and bats (convergent evolution), and appendages in insects also show evolution but are not classic examples of adaptive radiation.', true, '2026-09-09 03:19:23.224', '2026-09-09 03:19:23.224', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('761ef3cb-310d-496e-9b8c-0af6c6dfd02a', 'Financial Accounting', 'UTME', null, 2001, null, 'The law that currently regulates the registration of companies in Nigeria is the', null, '["Constitution of the Federal Republic of Nigeria,1999","Nigerian Enterprises Promotion Decree,1972","Companies and Allied Matters Decree,1990","Companies Decree,1968."]', 2, 'The law that currently regulates the registration of companies in Nigeria is the Companies and Allied Matters Decree, 1990.', true, '2026-10-12 22:00:07.594', '2026-10-12 22:00:07.594', null, null, null, 'The law that currently regulates the registration of companies in Nigeria is the', '["Constitution of the Federal Republic of Nigeria,1999","Nigerian Enterprises Promotion Decree,1972","<b>Companies and Allied Matters Decree,1990</b>","Companies Decree,1968."]', 'The law that currently regulates the registration of companies in Nigeria is the <b>Companies and Allied Matters Decree, 1990</b>.', '{"bold":["Companies and Allied Matters Decree, 1990"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7632b23b-09a7-4399-a2f2-1747bb4b5ce0', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. From what she said, one may <u>infer</u> that she does not like the course.', null, '["suppose","realize","deduce","agree"]', 2, 'Infer = deduce.', true, '2026-10-24 01:04:04.831', '2026-10-24 01:04:04.831', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. From what she said, one may <u>infer</u> that she does not like the course.', '["suppose","realize","<u>deduce</u>","agree"]', '<b>Infer</b> = <b>deduce</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7639669e-7b8f-4447-a677-58c31a99065e', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The trader was amused by the <u>cut-throat</u> rush for the goods.', null, '["strange","lackluster","mad","worrisome"]', 1, 'Cut-throat = intense; opposite = lackluster.', true, '2026-10-24 07:21:26.085', '2026-10-24 07:21:26.085', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The trader was amused by the <u>cut-throat</u> rush for the goods.', '["strange","lackluster","mad","worrisome"]', 'Cut-throat = intense; opposite = lackluster.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('763ff505-bc44-4bc8-8a80-3229fefcc38e', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). Mr. Rufus <u>bore the brunt</u> in the last promotion examination', null, '["Mr. Rufus failed the examination woefully","Mr. Rufus excelled in the examination","Mr. Rufus was excited about the examination","Mr. Rufus toyed with the examination"]', 0, '''Bore the brunt'' = suffered the worst part.', true, '2026-10-24 01:02:10.581', '2026-10-24 01:02:10.581', null, null, null, '(Choose the most appropriate interpretation). Mr. Rufus <u>bore the brunt</u> in the last promotion examination', '["<u>Mr. Rufus failed the examination woefully</u>","Mr. Rufus excelled in the examination","Mr. Rufus was excited about the examination","Mr. Rufus toyed with the examination"]', '''<b>Bore the brunt</b>'' = <b>suffered the worst part</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('76477414-6e5a-47a7-b4a9-58e252ad71f5', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The <u>schism</u> in the organization is on the increase', null, '["disagreement","understanding","opportunity","rot"]', 0, 'Schism = disagreement.', true, '2026-10-24 01:01:59.508', '2026-10-24 01:01:59.508', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The <u>schism</u> in the organization is on the increase', '["<u>disagreement</u>","understanding","opportunity","rot"]', '<b>Schism</b> = <b>disagreement</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('764c3db0-4d8a-41d5-a579-e1d3befb28a6', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The man advised his wife to <u>steer a middle course</u> in the argument between her and her employers.', null, '["be unrelenting","be unrepentant","be reclaimed","be compromising"]', 0, 'Steer a middle course = compromise; opposite = be unrelenting.', true, '2026-10-24 07:21:28.966', '2026-10-24 07:21:28.966', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The man advised his wife to <u>steer a middle course</u> in the argument between her and her employers.', '["be unrelenting","be unrepentant","be reclaimed","be compromising"]', 'Steer a middle course = compromise; opposite = be unrelenting.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('764e8826-5756-447c-8004-a8db15f2bc7b', 'Biology', 'JAMB', null, 2003, null, 'Epigeal germination of a seed is characterized by', null, '["more rapid elongation of the hypocotyl than the epicotyl","more rapid elongation of the epicotyl than the hypocotyl","equal growth rate of both the hypocotyl and epicotyl","lack of growth of the hypocotyl"]', 0, 'In epigeal germination, the hypocotyl elongates faster, pushing the cotyledons above the soil surface.', true, '2026-10-12 20:05:10.014', '2026-10-12 20:05:10.014', null, null, null, 'Epigeal germination of a seed is characterized by', '["more rapid elongation of the hypocotyl than the epicotyl","more rapid elongation of the epicotyl than the hypocotyl","equal growth rate of both the hypocotyl and epicotyl","lack of growth of the hypocotyl"]', 'In epigeal germination, the hypocotyl elongates faster, pushing the cotyledons above the soil surface.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7651732b-b8fb-4065-956a-fd6769aa69ca', 'Physics', 'JAMB', null, 1988, null, 'Which of the following properties is/are common to all waves?
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('76527028-7873-42c8-8eef-6f317dd0c816', 'Biology', 'JAMB', null, 2026, null, 'The oily substance that lubricates mammalian hair to keep it flexible and water repellent is secreted by the', null, '["Sweat glands","Sebaceous glands","Fatty cells","Granular layer"]', 1, 'The oily substance that lubricates mammalian hair is secreted by the sebaceous glands. Sebaceous glands produce sebum, which is an oily mixture of lipids, waxes, and dead cells. Sebum lubricates hair and skin, prevents water loss, and has antimicrobial properties. Sweat glands produce sweat for temperature regulation. Fatty cells store fat. The granular layer is a layer of the epidermis. Sebaceous glands are attached to hair follicles and their secretion is important for maintaining healthy skin and hair.', true, '2026-09-09 03:19:02.939', '2026-09-09 03:19:02.939', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7659243c-d64a-4038-a7c5-db45fadd3fcc', 'English Language', 'JAMB', null, 2007, null, 'No sooner had she arrived ........ it began to rain.', null, '["when","than","that","while"]', 1, '''No sooner ... than''.', true, '2026-10-25 18:25:06.683', '2026-10-25 18:25:06.683', null, null, null, 'No sooner had she arrived ........ it began to rain.', '["when","than","that","while"]', '''No sooner ... than''.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('765e32de-1df2-490b-9366-9a3237e38f0d', 'Biology', 'JAMB', null, 2026, null, 'In the absence of Oxygen, the pyruvic acid produced during glycolysis is converted to CO2 and', null, '["glycerol","water","citric acid","ethanol"]', 3, 'In the absence of oxygen, pyruvic acid undergoes anaerobic fermentation. In yeast and some plants, it is converted to ethanol and CO₂. In animal muscle cells, it is converted to lactic acid (lactate). Glycerol and water are not products of anaerobic respiration. Citric acid is part of the aerobic Krebs cycle. Ethanol fermentation is important in the food industry (bread making, alcoholic beverages). Anaerobic respiration allows glycolysis to continue by regenerating NAD⁺ from NADH, though it produces much less ATP than aerobic respiration (2 ATP vs 36 ATP).', true, '2026-09-09 03:18:42.663', '2026-09-09 03:18:42.663', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('766055f2-e606-4c01-a23b-568c30d271d2', 'Literature in English', 'JAMB', null, 2026, null, 'The character of Lucas is best described as a', null, '["Static character unaffected by events","Tragic hero whose flaw leads to his downfall","Dynamic character who evolves through adversity","Comic figure designed to entertain"]', 2, 'Lucas is a dynamic character who evolves through adversity.', true, '2026-09-12 11:12:02.352', '2026-09-12 11:12:02.352', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('766698ec-560b-438f-9fb7-877bb26eca58', 'English Language', 'JAMB', null, 2007, null, 'One of my sisters who <u>______</u> in Lagos is getting married next month.', null, '["live","lives","is living","leave"]', 0, '''Who'' â†’ sisters plural â†’ live.', true, '2026-10-24 01:02:16.376', '2026-10-24 01:02:16.376', null, null, null, 'One of my sisters who <u>______</u> in Lagos is getting married next month.', '["<u>live</u>","lives","is living","leave"]', '''<b>Who</b>'' â†’ <b>sisters</b> plural â†’ <b>live</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('766a05d2-673d-4fa8-9808-377c0d54ae4d', 'Biology', 'JAMB', null, 2026, null, 'Which of the following are common to all habitats: I. Light II. Current III. Dissolved gas IV. Wind', null, '["All but II only","I, IV","I, III, IV","I"]', 0, 'Light, dissolved gases (particularly oxygen and carbon dioxide), and wind are common to all habitats to some degree. Currents (water flow) are only present in aquatic habitats, not in terrestrial or aerial habitats. While aquatic habitats have currents, terrestrial habitats do not. Light is essential for photosynthesis in all ecosystems. Dissolved gases are present in both aquatic (dissolved in water) and terrestrial (in air) environments. Wind is present in all habitats though its effect varies. Therefore, ''All but II only'' is correct.', true, '2026-09-09 03:18:29.488', '2026-09-09 03:18:29.488', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('766cc4bf-24a4-4133-a6c4-d33de3982561', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The Doctor insisted on giving all of us <u>prophylactic</u> drugs.', null, '["curative","preventive","routine","special"]', 1, 'Prophylactic = preventive.', true, '2026-10-24 01:04:00.014', '2026-10-24 01:04:00.014', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The Doctor insisted on giving all of us <u>prophylactic</u> drugs.', '["curative","<u>preventive</u>","routine","special"]', '<b>Prophylactic</b> = <b>preventive</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('76727739-803b-40a6-a1ec-d419a1ff9d69', 'Chemistry', 'JAMB', null, 2026, null, 'The vapour density of a gas is', null, '["the mass of a volume of the gas compared to an equal volume of hydrogen","the mass of a volume of the gas compared to an equal volume of helium","the mass of a volume of the gas compared to an equal volume of oxygen","the mass of a volume of the gas compared to an equal volume of water vapour"]', 0, 'Vapour density measures gas density relative to hydrogen gas under identical conditions of temperature and pressure.', true, '2026-09-09 17:12:46.394', '2026-09-09 17:12:46.394', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('767508d8-0eb3-4620-afb5-88f9a318be0f', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. We were at a loss to understand why Olu should <u>retract</u> his statement before the judge.', null, '["assert","repeat","withdraw","reiterate"]', 2, 'Retract = withdraw.', true, '2026-10-24 01:04:08.107', '2026-10-24 01:04:08.107', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. We were at a loss to understand why Olu should <u>retract</u> his statement before the judge.', '["assert","repeat","<u>withdraw</u>","reiterate"]', '<b>Retract</b> = <b>withdraw</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('76802aa3-d2a6-4e12-9fab-a1c9aa29d212', 'English Language', 'JAMB', null, 2024, null, 'Identify the option that is nearest in meaning to the underlined word: She spurned the advances of her boss', null, '["accommodated","accepted","rejected","discouraged"]', 2, '"Spurned" means rejected with disdain.', true, '2026-09-18 09:43:02.51', '2026-09-18 09:43:02.51', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('768b251a-6245-4411-b53f-123d1a870d49', 'Literature in English', 'JAMB', null, 2026, null, 'The main difference between Drama and prose is that drama is meant to be', null, '["written for silent reading","performed before an audience","narrated by an author","told through description"]', 1, 'The main difference between drama and prose is that drama is meant to be performed before an audience. Drama is written to be acted on stage, with dialogue and action. Prose (novels, short stories) is written to be read. While both can be read, drama is specifically designed for performance, which is why it includes stage directions and dialogue rather than narration and description.', true, '2026-09-10 10:45:33.753', '2026-09-10 10:45:33.753', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7696a641-af66-4de1-a812-a512a494f743', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The rampage was organized and directed by the <u>militant ones</u> among the students.', null, '["soldiers","rebellious ones","belligerent ones","commandos"]', 2, 'Militant = belligerent.', true, '2026-10-24 01:01:44.209', '2026-10-24 01:01:44.209', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The rampage was organized and directed by the <u>militant ones</u> among the students.', '["soldiers","rebellious ones","<u>belligerent ones</u>","commandos"]', '<b>Militant</b> = <b>belligerent</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7698bd91-2146-4f69-a347-69313c02384f', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). The boss told the man <u>to let sleeping dogs lie</u>.', null, '["not to look for trouble","not to disturb other people","let the dogs sleep well","let the trouble begin"]', 0, '''Let sleeping dogs lie'' = avoid trouble.', true, '2026-10-24 01:04:18.197', '2026-10-24 01:04:18.197', null, null, null, '(Choose the most appropriate interpretation). The boss told the man <u>to let sleeping dogs lie</u>.', '["<u>not to look for trouble</u>","not to disturb other people","let the dogs sleep well","let the trouble begin"]', '''<b>Let sleeping dogs lie</b>'' = <b>avoid trouble</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('769bfd1c-52c5-42a7-9eea-fc4c971cfae9', 'Government', 'JAMB', null, 2026, null, 'The judiciary checks the other arms of government through', null, '["Judicial recall","Judicial precedence","Judicial review","Judicial oversight"]', 2, 'The judiciary checks other arms through judicial review.', true, '2026-09-12 11:24:30.739', '2026-09-12 11:24:30.739', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('76a5382d-4614-4a69-b1d9-6db04890caca', 'English Language', 'JAMB', null, 2007, null, 'The teacher, together with her students, <u>______</u> preparing for the inter-house sport.', null, '["are","is","were","have been"]', 1, '''Together with'' â†’ subject teacher (singular) â†’ is.', true, '2026-10-24 01:04:29.744', '2026-10-24 01:04:29.744', null, null, null, 'The teacher, together with her students, <u>______</u> preparing for the inter-house sport.', '["are","<u>is</u>","were","have been"]', '''<b>Together with</b>'' â†’ subject <b>teacher</b> (singular) â†’ <b>is</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('76c48a48-e007-40da-acff-3f9f110a0074', 'General Mathematics', 'JAMB', null, 2026, null, 'A dog is tied to a corner of a square shed with a rope of length 5 meters. The shed stands flush against both a vertical and a horizontal wall. What is the locus of the region the dog can move in?', null, '["A full circle of radius 5m","A quarter-circle of radius 5m","A semicircle of radius 5m","A square of side 5m"]', 1, 'The dog can move in a quarter-circle of radius 5m.', true, '2026-09-12 11:43:50.484', '2026-09-12 11:43:50.484', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('76ccbbf2-810d-4422-80fa-ba4b8fe991d4', 'English Language', 'JAMB', null, 2024, null, 'It''s a miracle that the child didn''t die after the illness, ______?', null, '["did she","isn''t it","didn''t she","wasn''t it"]', 1, 'The question tag for "It''s" is "isn''t it?"', true, '2026-09-18 09:43:02.571', '2026-09-18 09:43:02.571', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('76f0e69a-649f-456c-b863-130ce1954006', 'Biology', 'JAMB', null, 2013, null, 'Which of the following is caused by Treponema pallidum?', null, '["Tuberculosis","Syphilis","Gonorrhea","Leprosy"]', 1, 'Syphilis is caused by Treponema pallidum.', true, '2026-10-12 20:59:48.146', '2026-10-12 20:59:48.146', null, null, null, 'Which of the following is caused by Treponema pallidum?', '["Tuberculosis","Syphilis","Gonorrhea","Leprosy"]', 'Syphilis is caused by Treponema pallidum.', '{"bold":["Syphilis"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('76ff5887-f967-4d4e-b921-846863177bab', 'Chemistry', 'JAMB', null, 2026, null, 'Which process is used to purify copper after extraction?', null, '["Roasting","Electrolytic refining","Smelting","Cracking"]', 1, 'Electrolytic refining is used to purify copper after extraction.', true, '2026-09-12 11:35:47.936', '2026-09-12 11:35:47.936', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7702267c-02a2-453f-bc02-d6f1bcf0769f', 'Biology', 'JAMB', null, 2026, null, 'An example of plant adaptation to a xerophytic environment is represented by the development of', null, '["broad canopy and extensive surface root system","fleshy tissue and reduced leaves","thick barks and broad leaves","rough leaves and shallow root system"]', 1, 'Xerophytes often have fleshy stems (succulence) and reduced leaves (spines) to minimize water loss.', true, '2026-09-09 02:56:43.071', '2026-09-09 02:56:43.071', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7710cb42-61c4-4aac-aef4-56f730e3e816', 'Physics', 'JAMB', null, 2026, null, 'A material 1m in length increases by 15cm due to a 10Kelvin temperature change. If it has a surface area of 1mm², calculate its superficial expansivity.', null, '["0.01K⁻¹","0.02K⁻¹","0.03K⁻¹","0.001nK⁻¹","0.0135nK⁻¹"]', 2, 'Superficial expansivity β = ΔA/(A₀ΔT). But we are given linear expansion. First, linear expansivity α = ΔL/(L₀ΔT) = 0.15/(1×10) = 0.015 K⁻¹. Superficial expansivity β = 2α = 0.03 K⁻¹.', true, '2026-09-10 10:56:43.739', '2026-09-10 10:56:43.739', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7711c646-577c-44f5-af38-ce8c60a8c128', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Chidi is naturally <u>taciturn</u>.', null, '["friendly","cheerful","dumb","lively","garrulous"]', 4, 'Taciturn = reserved; opposite = garrulous.', true, '2026-10-24 07:21:10.758', '2026-10-24 07:21:10.758', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Chidi is naturally <u>taciturn</u>.', '["friendly","cheerful","dumb","lively","garrulous"]', 'Taciturn = reserved; opposite = garrulous.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('771a8d18-e2ba-4c56-aa0a-b675330e3747', 'Hausa', 'JAMB', null, 2010, null, 'A karkara da ma wasu manyan garuruwa kalilan, mutane kan hadu su rika cin abinci tare. Akan zabi gidan mutum daya daga cikinsu ya zama shi ne matattara. Mutumin da aka zabi gidansa, kusan shi ne shugaba, kuma ya fi kowa yawan shekaru. A wasu lokuta kuma, ana duba gidan da ya fi yalwa, ko ya fi zama kan hanya, babu wahala sosi zuwa gidan, musamman da damina. A wurin haduwa a ci abinci tare, kowane magidanci zai kawo abincin da aka dafa a gidansa, wanda ya fi shiga. Nan fa matan da suka kware suke shan yabo da godiya. Wadanda ba su iya ba kuwa, aiki ya gan su da kuma takaici. Saboda wasu mazan kan yi wa matansu gori. Ba nan ma abin ya tsaya ba, rashin iya abincin nan na iya haddasa mutuwar aure, idan ba a kai hankali nesa ba. Al''amari ya yi muni ke nan. Cikin abubuwan da ake kawowa, akwai tuwo da shinkafa da fate da dan wake da dambu da alkubus da doya da taliya da kuma makaroni. Ana kawo wasu daga cikin wadannan nau''o''in abinci tare da miya, wasu kuma a siffar dafa-duka. Duka dai wannan, ya danganta da irin cefanen da maigida ya yi. Akwai alfanu babba game da wannan zama. Da farko, akwai kyautata dangantaka da zaman tare. Ana kuma taimakon juna ta hanyar tattaua matsalolin da suka addabe su. Wanda ma ba ya da karfin yin abinci wani lokaci, ba zai tagayyara ba, zai sami abin da zai ci a wajen. A labarin, kalmar kware na daidai da', null, '["hadu","saba","dace","gwanance."]', 3, 'Kalmar kware na daidai da gwanance.', true, '2026-10-13 10:37:23.287', '2026-10-13 10:37:23.287', null, null, null, 'A karkara da ma wasu manyan garuruwa kalilan, mutane kan hadu su rika cin abinci tare. Akan zabi gidan mutum daya daga cikinsu ya zama shi ne matattara. Mutumin da aka zabi gidansa, kusan shi ne shugaba, kuma ya fi kowa yawan shekaru. A wasu lokuta kuma, ana duba gidan da ya fi yalwa, ko ya fi zama kan hanya, babu wahala sosi zuwa gidan, musamman da damina. A wurin haduwa a ci abinci tare, kowane magidanci zai kawo abincin da aka dafa a gidansa, wanda ya fi shiga. Nan fa matan da suka kware suke shan yabo da godiya. Wadanda ba su iya ba kuwa, aiki ya gan su da kuma takaici. Saboda wasu mazan kan yi wa matansu gori. Ba nan ma abin ya tsaya ba, rashin iya abincin nan na iya haddasa mutuwar aure, idan ba a kai hankali nesa ba. Al''amari ya yi muni ke nan. Cikin abubuwan da ake kawowa, akwai tuwo da shinkafa da fate da dan wake da dambu da alkubus da doya da taliya da kuma makaroni. Ana kawo wasu daga cikin wadannan nau''o''in abinci tare da miya, wasu kuma a siffar dafa-duka. Duka dai wannan, ya danganta da irin cefanen da maigida ya yi. Akwai alfanu babba game da wannan zama. Da farko, akwai kyautata dangantaka da zaman tare. Ana kuma taimakon juna ta hanyar tattaua matsalolin da suka addabe su. Wanda ma ba ya da karfin yin abinci wani lokaci, ba zai tagayyara ba, zai sami abin da zai ci a wajen. A labarin, kalmar kware na daidai da', '["hadu","saba","dace","gwanance."]', 'Kalmar kware na daidai da gwanance.', '{"bold":["gwanance"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('772218c3-3a9f-46ad-b39f-ad11c5eccd96', 'English Language', 'JAMB', null, 2007, null, 'The helpless <u>--------------</u> our sympathy.', null, '["require","requires","does require","do requires"]', 0, '''The helpless'' = helpless people (plural) â†’ require.', true, '2026-10-24 01:02:13.532', '2026-10-24 01:02:13.532', null, null, null, 'The helpless <u>--------------</u> our sympathy.', '["<u>require</u>","requires","does require","do requires"]', '''<b>The helpless</b>'' = helpless people (plural) â†’ <b>require</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('77237192-b778-4161-8acd-9f9ef1f1034f', 'Literature in English', 'JAMB', null, 2026, null, 'The lines that provide the evidence for question 26 are', null, '["2 & 3","7 & 8","9 & 10","11 & 12"]', 2, 'Lines 9 & 10 provide the evidence.', true, '2026-09-12 11:11:10.557', '2026-09-12 11:11:10.557', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7727388b-bcb1-4483-86ff-d142fdac3d4a', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Funmi is just being <u>facetious</u> about her marrying a soldier.', null, '["unfaithful","serious","crazy","unserious"]', 3, 'Facetious = unserious.', true, '2026-10-24 01:04:02.88', '2026-10-24 01:04:02.88', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Funmi is just being <u>facetious</u> about her marrying a soldier.', '["unfaithful","serious","crazy","<u>unserious</u>"]', '<b>Facetious</b> = <b>unserious</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('77292a58-90a0-44d1-bc1f-bf8aaab8c312', 'Physics', 'JAMB', null, 1995, null, 'If the maximum voltage across a 100-ohm resistor is 20 V, then the maximum power it can dissipate is', null, '["5.00 W","4.00 W","2.00 W","0.25 W"]', 1, 'P = V²/R = 20²/100 = 4.00 W.', true, '2026-10-12 19:15:42.326', '2026-10-12 19:15:42.326', null, null, null, 'If the maximum voltage across a 100-ohm resistor is 20 V, then the maximum power it can dissipate is', '["5.00 W","4.00 W","2.00 W","0.25 W"]', 'P = V<sup>2</sup>/R = 20<sup>2</sup>/100 = 4.00 W.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('772bd277-07ce-4030-a690-f60acb8fa64f', 'Literature in English', 'JAMB', null, 2026, null, '''The aroma of roasted corn filled the evening air'' appeals to', null, '["Gustatory imagery","Olfactory imagery","Tactile imagery","Visual imagery"]', 1, 'It appeals to olfactory imagery.', true, '2026-09-12 11:11:29.364', '2026-09-12 11:11:29.364', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('772eabf4-e347-4aac-9436-4caf00298220', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Otokpa is a member of the <u>ad hoc</u> committee on stock acquisition.', null, '["improvised","temporary","formal","fact-finding"]', 2, 'Ad hoc = temporary/improvised; opposite = formal.', true, '2026-10-24 07:21:27.199', '2026-10-24 07:21:27.199', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Otokpa is a member of the <u>ad hoc</u> committee on stock acquisition.', '["improvised","temporary","formal","fact-finding"]', 'Ad hoc = temporary/improvised; opposite = formal.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('773781eb-765a-40a6-b4ae-034f56b62e8f', 'English Language', 'JAMB', null, 2007, null, 'My advice to Tolu was; <u>look before you leap</u>.', null, '["Tolu was advised to consider the possible consequences before taking action","Tolu was advised to consider her opinion before reaching any decision","Tolu was advised to weigh her decision by looking and leaping","Tolu was advised to leap only after looking"]', 0, '''Look before you leap'' = consider consequences before acting.', true, '2026-10-24 01:02:09.925', '2026-10-24 01:02:09.925', null, null, null, 'My advice to Tolu was; <u>look before you leap</u>.', '["<u>Tolu was advised to consider the possible consequences before taking action</u>","Tolu was advised to consider her opinion before reaching any decision","Tolu was advised to weigh her decision by looking and leaping","Tolu was advised to leap only after looking"]', '''<b>Look before you leap</b>'' = <b>consider consequences before acting</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('773af43c-59a7-42e0-81d6-75e9cbd641f8', 'Literature in English', 'JAMB', null, 2026, null, 'The psychological depth of characters is revealed through', null, '["flashbacks and internal conflict","proverbs and aphorisms","dialogue alone","stage directions"]', 0, 'Psychological depth is revealed through flashbacks and internal conflict.', true, '2026-09-12 11:14:09.58', '2026-09-12 11:14:09.58', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('77449205-1054-4ec3-b35a-3ae2f1257ddb', 'Economics', 'JAMB', null, 2026, null, 'Indirect taxes are levied on ______ while direct taxes are levied on ______', null, '["goods and services, production","Production, goods and services","Goods and services, Income","income, goods and services"]', 2, 'Indirect taxes are on goods and services; direct taxes are on income.', true, '2026-09-12 11:00:55.515', '2026-09-12 11:00:55.515', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('774d6ef1-6bee-4869-b319-274c0bd08f52', 'Biology', 'JAMB', null, 2012, null, 'The diseases caused by water-borne pathogens include', null, '["gonorrhea and poliomyelitis","typhoid and syphilis","tuberculosis and cholera","typhoid and cholera."]', 3, 'Typhoid and cholera are water-borne diseases.', true, '2026-10-12 20:59:45.501', '2026-10-12 20:59:45.501', null, null, null, 'The diseases caused by water-borne pathogens include', '["gonorrhea and poliomyelitis","typhoid and syphilis","tuberculosis and cholera","typhoid and cholera."]', 'Typhoid and cholera are water-borne diseases.', '{"bold":["Typhoid and cholera"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('774f5138-9f40-4215-b472-2d8f9a644af1', 'Government', 'JAMB', null, 2026, null, 'The key word for explaining the term ''authority'' is', null, '["right","ability","control","power"]', 0, 'The key word for authority is ''right'' (the right to exercise power).', true, '2026-09-12 11:24:15.7', '2026-09-12 11:24:15.7', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('775ba379-f2df-49b8-bda8-4123ca0d6d20', 'Economics', 'JAMB', null, 2026, null, 'If the demand for a good is perfectly inelastic, a price increase will', null, '["Change quantity demanded infinitely","Have no effect on quantity demanded","Will cause a less change in quantity demanded","Will cause a greater change in quantity demanded"]', 1, 'Perfectly inelastic demand means quantity demanded does not change with price.', true, '2026-09-12 10:59:28.204', '2026-09-12 10:59:28.204', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('775e845f-01fc-442a-89ce-de86af0ca41c', 'Biology', 'JAMB', null, 2026, null, 'What is the main neurotransmitter involved in transmitting signals between nerve cells in the nervous system?', null, '["serotonin","dopamine","acetylcholine","endorphins"]', 2, 'Acetylcholine is the main neurotransmitter involved in transmitting signals between nerve cells (neurons) and at neuromuscular junctions. It is released from presynaptic neurons and binds to receptors on postsynaptic neurons, transmitting the nerve impulse. Serotonin and dopamine are neurotransmitters involved in mood, emotion, and reward systems. Endorphins are neurotransmitters that inhibit pain signals and promote feelings of pleasure. Acetylcholine is the primary excitatory neurotransmitter at synapses in the peripheral nervous system and important in the central nervous system.', true, '2026-09-09 03:18:36.12', '2026-09-09 03:18:36.12', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('776a7a3f-567f-4490-ac7d-625e72ea6747', 'Chemistry', 'JAMB', null, 2026, null, 'How many bonding pairs are present in carbon (IV) oxide molecules', null, '["3","2","1","4"]', 3, 'Carbon (IV) oxide (CO2) features two double covalent bonds between carbon and oxygen atoms (O=C=O), giving a total of 4 shared electron pairs (bonding pairs).', true, '2026-09-09 17:12:44.933', '2026-09-09 17:12:44.933', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7770aa88-9dfd-476d-b82c-09dc0c4e98c7', 'General Mathematics', 'JAMB', null, 2026, null, 'Y varies directly as w². When y=8, w=2. Find y when w=3', null, '["18","12","9","6"]', 0, 'y = kw². 8 = k(4). k = 2. y = 2(9) = 18.', true, '2026-09-12 11:44:05.546', '2026-09-12 11:44:05.546', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('777818fa-71cc-42ef-8bc1-17b824220a4a', 'Chemistry', 'JAMB', null, 2026, null, 'The pollutants that are likely to be present in an industrial environment are', null, '["H2S, SO2 and oxides of nitrogen","NH3, HCl and CO","CO2, NH3, and H2S","dust, NO and Cl2"]', 0, 'Industrial fuel combustion and manufacturing processes release hydrogen sulfide (H2S), sulfur dioxide (SO2), and nitrogen oxides into the air.', true, '2026-09-09 17:12:47.198', '2026-09-09 17:12:47.198', null, null, null, null, null, null, null);
