insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('779a2109-d37b-42fc-8e58-6b03be3e3146', 'Biology', 'JAMB', null, 2010, null, 'The barrier between maternal and foetal blood is the', null, '["placenta","liver","umbilical chord","uterine wall"]', 0, 'The placenta is the barrier between maternal and foetal blood.', true, '2026-10-12 20:59:40.582', '2026-10-12 20:59:40.582', null, null, null, 'The barrier between maternal and foetal blood is the', '["placenta","liver","umbilical chord","uterine wall"]', 'The placenta is the barrier between maternal and foetal blood.', '{"bold":["placenta"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('779f4885-d78a-4ef4-8d2c-b5bc084eb8b2', 'Physics', 'JAMB', null, 2026, null, 'A small object of mass 50g is released from a point A. Determine the velocity of the object when it reaches a point B, a vertical distance of 30m below A. [g = 10 ms⁻²]', null, '["1.5 ms⁻¹","6.0 m s⁻¹","17.3 m s⁻¹","24.5 m s⁻¹"]', 3, 'Using v² = u² + 2gh, u=0, h=30m. v² = 2 × 10 × 30 = 600. v = √600 = 24.5 m/s.', true, '2026-09-10 10:56:48.282', '2026-09-10 10:56:48.282', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('77bdcc9d-5307-423c-85df-c741334f7b47', 'Financial Accounting', 'UTME', null, 2002, null, 'I. Orientation II. Entity III. Legal status IV. Finance. Which of the characteristics above distinguishes a profit-making from a not-for-profit-making organization?', null, '["I, II, III and IV","I, II and III","II and III","I and II"]', 0, 'All the above characteristics distinguish the two organizations.', true, '2026-10-12 21:59:57.659', '2026-10-12 21:59:57.659', null, null, null, 'I. Orientation II. Entity III. Legal status IV. Finance. Which of the characteristics above distinguishes a profit-making from a not-for-profit-making organization?', '["<b>I, II, III and IV</b>","I, II and III","II and III","I and II"]', '<b>All the above characteristics</b> distinguish the two organizations.', '{"bold":["All the above characteristics"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('77c9dc7a-e148-4174-ba33-835286a67353', 'Physics', 'JAMB', null, 2026, null, 'A satellite is in a parking orbit if its period is', 'https://res.cloudinary.com/kwi1uv0g/image/upload/v1789039774/questions/hlhkodkwiu3bzcjccioa.jpg', '["less than the period of the earth","more than the period of the earth","equal to the period of the earth","the square of the period of the earth"]', 2, 'A satellite is in a parking orbit if its period is equal to the period of the earth (24 hours). This is a geostationary orbit, where the satellite appears stationary relative to a point on the earth''s surface.', true, '2026-09-10 11:30:20.115', '2026-09-10 11:30:20.115', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('77d04f0b-9925-4839-977c-bdae8ee6532c', 'Physics', 'JAMB', null, 2026, null, 'When a positively charged rod is brought nearer the cap of a positively charged electroscope, the leaves divergence will', null, '["be induced","converge","Diverge","remain constant"]', 2, 'When a positively charged rod is brought near the cap of a positively charged electroscope, the leaves will diverge more. This is because like charges repel. The positive charge on the rod repels positive charges in the electroscope down to the leaves, increasing their divergence.', true, '2026-09-10 10:56:38.541', '2026-09-10 10:56:38.541', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('77e35622-127d-41b3-a3d6-629fe8a9d877', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Since his father''s death, Osita has not been able to <u>cope with</u> the tasks of a family head.', null, '["perform adequately","tolerate","accept","assess properly","manage"]', 4, 'Cope with = manage.', true, '2026-10-24 01:01:41.27', '2026-10-24 01:01:41.27', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Since his father''s death, Osita has not been able to <u>cope with</u> the tasks of a family head.', '["perform adequately","tolerate","accept","assess properly","<u>manage</u>"]', '<b>Cope with</b> = <b>manage</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('77e805ee-df7c-48ff-9541-0070276124d6', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'David''s reaction to the death of the child born to him by Bathsheba is an indication that', null, '["man is helpless in the face of death","he is faithful to God","God fulfils his promises","any child from an adulterous relationship is punished by God"]', 0, 'David accepted God''s will, showing man''s helplessness before death.', true, '2026-09-12 10:42:01.328', '2026-09-12 10:42:01.328', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('77ea03e1-6ffd-4eb3-b00f-dc9c3fc4a736', 'Literature in English', 'JAMB', null, 2026, null, 'The phrase ''garlands'' symbolises', null, '["weapons of war","symbols of praise and honour","tools for farming","signs of punishment"]', 1, 'Garlands symbolize praise and honour.', true, '2026-09-12 11:05:37.669', '2026-09-12 11:05:37.669', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('77ef6f14-c6f0-4734-9fd2-75835a089c90', 'English Language', 'JAMB', null, 2007, null, 'When the strike is over, there will probably be an increase in wages and a <u>__________</u> increase in prices.', null, '["sporadic","concordant","concurrent","chronic"]', 2, 'Correct spelling: concurrent.', true, '2026-10-24 07:21:37.627', '2026-10-24 07:21:37.627', null, null, null, 'When the strike is over, there will probably be an increase in wages and a <u>__________</u> increase in prices.', '["sporadic","concordant","concurrent","chronic"]', 'Correct spelling: concurrent.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('77f04c42-2b2b-4285-82a0-0d23b548e4e3', 'Literature in English', 'JAMB', null, 2026, null, 'Mention one theme reflected in this extract', null, '["Disloyalty","Grief","Duty","Passion"]', 3, 'Passion is a theme reflected in this extract.', true, '2026-09-12 11:14:08.461', '2026-09-12 11:14:08.461', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('77faf438-a0f9-4f40-b22b-991f103bfa97', 'General Mathematics', 'JAMB', null, 2026, null, 'There are deer and peacocks in a zoo. By counting heads they are 80. The numbers of their legs is 200. How many peacocks are there?', null, '["20","30","50","60"]', 3, 'd+p = 80. 4d+2p = 200. 2d+2p = 160. 2d = 40. d = 20. p = 60.', true, '2026-09-12 11:44:21.546', '2026-09-12 11:44:21.546', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('77fb26cd-0c15-44ee-b899-f6e683a0b1f3', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Jesus declared that men love darkness rather than light because', null, '["their hearts were hardened","they had no truth","they had been blinded","their deeds were evil"]', 3, 'Jesus declared that men love darkness rather than light because their deeds were evil. In John 3:19-20, Jesus said, ''And this is the judgment, that the light has come into the world, and men loved darkness rather than light, because their deeds were evil.''', true, '2026-09-12 09:46:12.095', '2026-09-12 09:46:12.095', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('781afa7b-5f60-420d-ae50-6672a1f75c4d', 'Hausa', 'JAMB', null, 2009, null, 'Bayan wata uku, ata sake mu. Da muka huta kwana biyu, sai muka yi shirin zuwa kasashen Ris tare da shi, ya zama kuma abokina. Muna cikin tafiya a daji, sai wani mahaukacin rakumi, amale, ya biyo mu baki bud`e. muka sheka wurin wata itaciya muka hau. Shi kuwa, rakumin ya tsaya nan gindin itaciyar yana jira wai sai mun sauko, ya tasam mana. Muka rasa yadda za mu yi tun da safe har azahar, gas hi kuwa cikunanmu suna ta kiran ciorma. Can zuwa la''asar, sai nag a wad`ansu Fulani za su yawon sharo. Da dai na hange su kan hanya, sai na ce, ''Kai masu tafiya, uwaku!'' Ka san bafillace kan bakin rai, daga can kuwa sai suka nufo mu da gudu, wais u ji dalilin da ya san a zage su. Da dai rakumin nan ya kyalla ido ya gan su, bai sake komawa ta kanmu ba, sai ya cce dasu aka gama mu. Kowanne ya ranta, suka yi dawa! Mu kuwa muka sauka, muka yi tamu hanya. Ga mu nan sai Birnin Ris . Zurke na can yana kale-kalle, har nab ace masa. Ka ji rabuwata da shi. Na yi gaba, na shiga jirgi. Na nufi Alkama neman abin da ya rabo ni da gida, watau Ruwan Baganja. Da muka sauka a wani tsibiri don mu huta, sai na tafi yawon shan iska. Jirgi ya tshai, aka bar ni nan ni kad`ai! Bayan sun wuce, na tashi da tafiya, ina neman wani jirgi in bi su. Ina bin bakin teku, sai na tarar da wani mutum a zaune. Na dube shi da kyau, ashe dai Malam Zurke ne dan Muhammad. Da nag a haka sai n ace, ''Zurke d`an Muhammad!'' Sai ya amsa y ace, ''Himma dai d`an Shehu!'' Muka tafa. Y ace ''Wallahi, tun da ka zo na gane ka''. Muka ba juna labarin rabuwarmu. A labarin, wa aka ce yana dab akin rai?', null, '["Bafillace","Dan Shehu","Marubucin","Malam Zurke"]', 0, 'Bafillace aka ce yana dabakin rai.', true, '2026-10-13 10:37:26.074', '2026-10-13 10:37:26.074', null, null, null, 'Bayan wata uku, ata sake mu. Da muka huta kwana biyu, sai muka yi shirin zuwa kasashen Ris tare da shi, ya zama kuma abokina. Muna cikin tafiya a daji, sai wani mahaukacin rakumi, amale, ya biyo mu baki bud`e. muka sheka wurin wata itaciya muka hau. Shi kuwa, rakumin ya tsaya nan gindin itaciyar yana jira wai sai mun sauko, ya tasam mana. Muka rasa yadda za mu yi tun da safe har azahar, gas hi kuwa cikunanmu suna ta kiran ciorma. Can zuwa la''asar, sai nag a wad`ansu Fulani za su yawon sharo. Da dai na hange su kan hanya, sai na ce, ''Kai masu tafiya, uwaku!'' Ka san bafillace kan bakin rai, daga can kuwa sai suka nufo mu da gudu, wais u ji dalilin da ya san a zage su. Da dai rakumin nan ya kyalla ido ya gan su, bai sake komawa ta kanmu ba, sai ya cce dasu aka gama mu. Kowanne ya ranta, suka yi dawa! Mu kuwa muka sauka, muka yi tamu hanya. Ga mu nan sai Birnin Ris . Zurke na can yana kale-kalle, har nab ace masa. Ka ji rabuwata da shi. Na yi gaba, na shiga jirgi. Na nufi Alkama neman abin da ya rabo ni da gida, watau Ruwan Baganja. Da muka sauka a wani tsibiri don mu huta, sai na tafi yawon shan iska. Jirgi ya tshai, aka bar ni nan ni kad`ai! Bayan sun wuce, na tashi da tafiya, ina neman wani jirgi in bi su. Ina bin bakin teku, sai na tarar da wani mutum a zaune. Na dube shi da kyau, ashe dai Malam Zurke ne dan Muhammad. Da nag a haka sai n ace, ''Zurke d`an Muhammad!'' Sai ya amsa y ace, ''Himma dai d`an Shehu!'' Muka tafa. Y ace ''Wallahi, tun da ka zo na gane ka''. Muka ba juna labarin rabuwarmu. A labarin, wa aka ce yana dab akin rai?', '["Bafillace","Dan Shehu","Marubucin","Malam Zurke"]', 'Bafillace aka ce yana dabakin rai.', '{"bold":["Bafillace"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7825df1c-e5c2-4272-a3a5-da9d1e94c7a6', 'English Language', 'JAMB', null, 2024, null, '31', null, '["exploitation","manipulation","manoeuvring","freedom"]', 3, 'The essential characteristic of capitalism is economic freedom.', true, '2026-09-18 10:17:48.736', '2026-09-18 10:17:48.736', '01c7070a-0591-4cea-af06-fe54980dbb5f', 2, 'CLOZE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('782aaf8f-6c5f-4295-a011-ed7fdd011070', 'Physics', 'JAMB', null, 1983, null, 'If the normal atmospheric pressure in a laboratory supports a column of mercury 0.76 m high and the relative density of mercury is 13.8, then the height of water column which atmospheric pressure will support in the same laboratory at the same time is', null, '["0 m","10 m","13 m","14 m","18 m"]', 1, 'Pressure = hρg is the same for both columns, so hwater = hHg x (relative density of Hg) = 0.76 x 13.8 ≈ 10.5 m, which is closest to 10 m.', true, '2026-10-12 19:15:17.489', '2026-10-12 19:15:17.489', null, null, null, 'If the normal atmospheric pressure in a laboratory supports a column of mercury 0.76 m high and the relative density of mercury is 13.8, then the height of water column which atmospheric pressure will support in the same laboratory at the same time is', '["0 m","10 m","13 m","14 m","18 m"]', 'Pressure = hρg is the same for both columns, so h<sub>water</sub> = h<sub>Hg</sub> x (relative density of Hg) = 0.76 x 13.8 ≈ 10.5 m, which is closest to 10 m.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7832828c-4224-4745-8200-2b7610256fbf', 'Physics', 'JAMB', null, 1990, null, 'Electrical power is transmitted at a high voltage rather than low voltage because the amount of energy loss is reduced due to', null, '["Heat dissipation","Production of eddy currents","Excessive current discharged","Excessive voltage discharged."]', 0, 'High voltage means a low current for the same power, and heat loss in the cables (I²R) is reduced.', true, '2026-10-12 19:15:32.002', '2026-10-12 19:15:32.002', null, null, null, 'Electrical power is transmitted at a high voltage rather than low voltage because the amount of energy loss is reduced due to', '["Heat dissipation","Production of eddy currents","Excessive current discharged","Excessive voltage discharged."]', 'High voltage means a low current for the same power, and heat loss in the cables (I<sup>2</sup>R) is reduced.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7837701b-3868-4296-a442-6ed0f323ee26', 'testing', 'JAMB', null, 2024, null, 'The teacher, along with her students ....invited to the ceremony', null, '["Were","Was","Have been","Are"]', 1, '''Along with'' does not change singular subject ''teacher'' → ''was''.', true, '2026-10-31 16:48:52.999', '2026-10-31 16:48:52.999', null, null, null, 'The teacher, along with her students ....invited to the ceremony', '["Were","Was","Have been","Are"]', '''Along with'' does not change singular subject ''teacher'' → ''was''.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('783beba2-879b-4a02-8c84-d7e24061eced', 'Physics', 'JAMB', null, 1998, null, 'A transformer which can produce 8 V from a 240 V a.c. supply has an efficiency of 80%. If the current in the secondary coil is 15 A, calculate the current in the primary coil.', null, '["0.625 A","1.600 A","2.500 A","6.250 A"]', 0, 'Output power = 8 x 15 = 120 W. Input power = 120/0.80 = 150 W. Ip = 150/240 = 0.625 A.', true, '2026-10-12 19:15:46.698', '2026-10-12 19:15:46.698', null, null, null, 'A transformer which can produce 8 V from a 240 V a.c. supply has an efficiency of 80%. If the current in the secondary coil is 15 A, calculate the current in the primary coil.', '["0.625 A","1.600 A","2.500 A","6.250 A"]', 'Output power = 8 x 15 = 120 W. Input power = 120/0.80 = 150 W. I<sub>p</sub> = 150/240 = 0.625 A.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7847c072-ba5e-43c9-afca-84507585211e', 'Physics', 'JAMB', null, 1998, null, 'A 500 W heater is used to heat 0.6 kg of water from 25 °C to 100 °C in t₁ seconds. If another 1000 W heater is used to heat 0.2 kg of water from 10 °C to 100 °C in t₂ seconds, find t₁/t₂.', null, '["50","5","5/4","1/5"]', 1, 't₁ = (0.6 x c x 75)/500 = 0.09c. t₂ = (0.2 x c x 90)/1000 = 0.018c. t₁/t₂ = 0.09/0.018 = 5.', true, '2026-10-12 19:15:45.516', '2026-10-12 19:15:45.516', null, null, null, 'A 500 W heater is used to heat 0.6 kg of water from 25 °C to 100 °C in t<sub>1</sub> seconds. If another 1000 W heater is used to heat 0.2 kg of water from 10 °C to 100 °C in t<sub>2</sub> seconds, find t<sub>1</sub>/t<sub>2</sub>.', '["50","5","5/4","1/5"]', 't<sub>1</sub> = (0.6 x c x 75)/500 = 0.09c. t<sub>2</sub> = (0.2 x c x 90)/1000 = 0.018c. t<sub>1</sub>/t<sub>2</sub> = 0.09/0.018 = 5.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('784b0b0e-adde-419d-9f8f-043c76fc53fd', 'Biology', 'JAMB', null, 2012, null, 'Plants of temperate origin can be grown in tropical areas in the vegetation zones of the', null, '["rain forest","Guinea savanna","Sudan savanna","montane forest"]', 3, 'Plants of temperate origin can be grown in montane forests.', true, '2026-10-12 20:59:45.046', '2026-10-12 20:59:45.046', null, null, null, 'Plants of temperate origin can be grown in tropical areas in the vegetation zones of the', '["rain forest","Guinea savanna","Sudan savanna","montane forest"]', 'Plants of temperate origin can be grown in montane forests.', '{"bold":["montane forests"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('784bcf60-6dfa-44f1-8b8c-2922f18370c5', 'Physics', 'JAMB', null, 2026, null, 'What is the total resistance in the above diagram?', 'https://res.cloudinary.com/kwi1uv0g/image/upload/v1789038682/questions/neyh7hdxprtlijx6slsa.jpg', '["5 ohms","25 Ohms","15 ohms","35 ohms","45 ohms"]', 1, 'The circuit has two 10Ω resistors in series (R₁ at both ends) and a parallel combination of two 10Ω resistors (R₂ and R₃) in the middle. The parallel combination: 1/Rp = 1/10 + 1/10 = 2/10, so Rp = 5Ω. Total resistance = 10 + 5 + 10 = 25Ω.', true, '2026-09-10 11:19:25.493', '2026-09-10 11:19:25.493', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('785838f2-c675-45cd-b9b5-12bc656110e2', 'English Language', 'JAMB', null, 2007, null, 'A range of options <u>-----</u> available to the political parties during the recently concluded elections.', null, '["were made","is made","are made","was made"]', 3, 'Singular ''range'' past â†’ was made.', true, '2026-10-24 01:02:13.807', '2026-10-24 01:02:13.807', null, null, null, 'A range of options <u>-----</u> available to the political parties during the recently concluded elections.', '["were made","is made","are made","<u>was made</u>"]', 'Singular ''<b>range</b>'' past â†’ <b>was made</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('785af2c4-893e-414e-b397-22f778e70d3b', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Tade has <u>an aquiline</u> nose.', null, '["a large and curve nose","a wide and straight nose","a big and pointed nose","a small and attractive nose"]', 0, 'Aquiline = large and curved nose.', true, '2026-10-24 01:04:08.696', '2026-10-24 01:04:08.696', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Tade has <u>an aquiline</u> nose.', '["<u>a large and curve nose</u>","a wide and straight nose","a big and pointed nose","a small and attractive nose"]', '<b>Aquiline</b> = <b>a large and curve nose</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('785cb213-8a66-417a-a3fe-274bd1fd49f9', 'Chemistry', 'JAMB', null, 2026, null, 'Reduction of alkanones with LiAlH₃ produces?', null, '["Primary alkanols","Secondary alkanols","Tertiary alkanols","Carboxylic acids"]', 1, 'Reduction of ketones (alkanones) produces secondary alcohols.', true, '2026-09-12 11:36:23.814', '2026-09-12 11:36:23.814', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7861aedc-c533-4e58-8688-d15446f3ae37', 'Physics', 'JAMB', null, 2026, null, 'Which is not a kinetic theory of gases?', null, '["They move in constant random motion","the collision between them is perfectly inelastic","There''s no force of attraction or repulsion between the molecules","Temperature is the average kinetic energy of the molecules in the system"]', 1, 'The statement that collisions between gas molecules are perfectly inelastic is not a kinetic theory of gases. In the kinetic theory, collisions between gas molecules are assumed to be perfectly elastic (no kinetic energy is lost).', true, '2026-09-10 10:56:43.253', '2026-09-10 10:56:43.253', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('786a71fd-767f-44f1-965a-ad17e08f399b', 'Biology', 'JAMB', null, 2003, null, 'Hermaphroditic reproduction can be found among the', null, '["arthropods and nematodes","pisces and amphibians","annelids and molluscs","coelenterates and platyhelminthes"]', 2, 'Hermaphroditic reproduction is found among annelids and molluscs.', true, '2026-10-12 20:59:32.334', '2026-10-12 20:59:32.334', null, null, null, 'Hermaphroditic reproduction can be found among the', '["arthropods and nematodes","pisces and amphibians","annelids and molluscs","coelenterates and platyhelminthes"]', 'Hermaphroditic reproduction is found among annelids and molluscs.', '{"bold":["annelids and molluscs"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('78721b46-e948-445e-a85e-b80bca2a7625', 'Economics', 'JAMB', null, 2026, null, 'Basic concepts of Economics include the following except', null, '["Scarcity","Choice","Needs","Opportunity cost"]', 2, 'Basic concepts of economics include scarcity, choice, and opportunity cost. Needs is not a basic concept in the same sense.', true, '2026-09-12 11:00:09.442', '2026-09-12 11:00:09.442', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('787750ec-09d1-4e8d-8139-ac8437dc726a', 'Physics', 'JAMB', null, 2000, null, 'An electric generator with a power output of 3.0 kW at a voltage of 1.5 kV distributes power along cables of total resistance 20.0 ohms. The power loss in the cable is', null, '["0.1 W","10.0 W","40.0 W","80.0 W"]', 3, 'I = P/V = 3000/1500 = 2 A. Power loss = I²R = 4 x 20 = 80 W.', true, '2026-10-12 19:15:50.665', '2026-10-12 19:15:50.665', null, null, null, 'An electric generator with a power output of 3.0 kW at a voltage of 1.5 kV distributes power along cables of total resistance 20.0 ohms. The power loss in the cable is', '["0.1 W","10.0 W","40.0 W","80.0 W"]', 'I = P/V = 3000/1500 = 2 A. Power loss = I<sup>2</sup>R = 4 x 20 = 80 W.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('787bac1e-8e38-4629-b4c0-d60757a7222e', 'Biology', 'JAMB', null, 2003, null, 'The larval stage of a mosquito is called', null, '["wriggler","grub","maggot","caterpillar"]', 0, 'Mosquito larvae are aquatic and commonly referred to as wrigglers due to their movement.', true, '2026-10-12 20:05:10.413', '2026-10-12 20:05:10.413', null, null, null, 'The larval stage of a mosquito is called', '["wriggler","grub","maggot","caterpillar"]', 'Mosquito larvae are aquatic and commonly referred to as wrigglers due to their movement.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('787dd587-5655-43c2-a5b9-0523eb70d537', 'Literature in English', 'JAMB', null, 2026, null, 'A character who defends a bad cause or who argues in a contrary position just to stimulate an argument is referred to as', null, '["Legend","Cynic","Villain","Critic"]', 1, 'A cynic argues in a contrary position to stimulate argument.', true, '2026-09-12 11:07:25.157', '2026-09-12 11:07:25.157', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('789031d0-b174-41ff-83c8-01ad5fc31ef6', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'According to the Gospel of John, when Jesus appeared to the disciples on the evening of the first day of the week He', null, '["taught them about the kingdom","pronounced peace upon them","washed their feet","narrated to them how he suffered"]', 1, 'Jesus said, ''Peace be with you.''', true, '2026-09-12 10:41:57.336', '2026-09-12 10:41:57.336', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('78915b6f-fab4-4919-baa7-aef51317de04', 'English Language', 'JAMB', null, 2007, null, 'Three quarters of the hostel <u>------------</u> been painted and three quarters of the students <u>------------</u> moved in.', null, '["has/has","has/have","have/have","have/has"]', 1, 'Hostel singular (has); students plural (have).', true, '2026-10-24 01:04:28.48', '2026-10-24 01:04:28.48', null, null, null, 'Three quarters of the hostel <u>------------</u> been painted and three quarters of the students <u>------------</u> moved in.', '["has/has","<u>has/have</u>","have/have","have/has"]', '<b>Hostel</b> singular (<b>has</b>); <b>students</b> plural (<b>have</b>).', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('78a02e65-986a-4d21-88d9-40418815c754', 'General Mathematics', 'JAMB', null, 2026, null, 'Simplify: 3⁻⁴ + 3⁻⁵', null, '["5/6","17/12","7/12","5/12"]', 3, '3⁻⁴ + 3⁻⁵ = 1/81 + 1/243 = 3/243 + 1/243 = 4/243. Not in options.', true, '2026-09-12 11:44:10.284', '2026-09-12 11:44:10.284', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('78a2c6ab-3cbf-4293-8df2-088fbeaf45ca', 'Physics', 'JAMB', null, 1991, null, 'Which of the following phenomena is called photoelectric effect?', null, '["High energy electrons impinge on a metallic anode which then emits photons","A high energy photon emits photons as it is slowed down","A metal absorbs quanta of light and then emits electrons","Two electrons are created from a quantum of light."]', 2, 'In the photoelectric effect a metal absorbs photons (quanta of light) and emits electrons if the photon energy exceeds the work function.', true, '2026-10-12 19:15:34.695', '2026-10-12 19:15:34.695', null, null, null, 'Which of the following phenomena is called photoelectric effect?', '["High energy electrons impinge on a metallic anode which then emits photons","A high energy photon emits photons as it is slowed down","A metal absorbs quanta of light and then emits electrons","Two electrons are created from a quantum of light."]', 'In the photoelectric effect a metal absorbs photons (quanta of light) and emits electrons if the photon energy exceeds the work function.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('78abb992-bd7d-4d7c-b847-064fdfb09a4b', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. She showed an <u>affected</u> interest in the game.', null, '["a real","a pretended","a concerned","a slight"]', 1, 'Affected = pretended/artificial.', true, '2026-10-24 01:03:55.807', '2026-10-24 01:03:55.807', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. She showed an <u>affected</u> interest in the game.', '["a real","<u>a pretended</u>","a concerned","a slight"]', '<b>Affected</b> = <b>a pretended</b>/artificial.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('78cd2b12-7066-4c7e-b436-9b84c398d687', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The accident victim received <u>a superficial</u> wound from the crash.', null, '["a painless","a serious","an external","an internal"]', 2, 'Superficial = external.', true, '2026-10-24 01:01:53.797', '2026-10-24 01:01:53.797', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The accident victim received <u>a superficial</u> wound from the crash.', '["a painless","a serious","<u>an external</u>","an internal"]', '<b>Superficial</b> = <b>an external</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('78cd7fe6-96d1-4444-9f6a-22f005831109', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The members of the congregation were <u>inspired</u> by the sermon.', null, '["bewitched","enthralled","disenchanted","disorientated"]', 2, 'Inspired = uplifted; opposite = disenchanted.', true, '2026-10-24 07:21:23.965', '2026-10-24 07:21:23.965', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The members of the congregation were <u>inspired</u> by the sermon.', '["bewitched","enthralled","disenchanted","disorientated"]', 'Inspired = uplifted; opposite = disenchanted.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('78d70310-8bb3-4e64-b26f-7c9652b275fc', 'Physics', 'JAMB', null, 1992, null, 'Which of the following apparatus will require the smallest fuse rating for its protection?', null, '["60 W, 240 V","60 W, 40 V","40 W, 12 V","40 W, 5 V"]', 0, 'Current I = P/V: 0.25 A, 1.5 A, 3.3 A and 8 A respectively. The 60 W, 240 V apparatus draws the smallest current.', true, '2026-10-12 19:15:36.52', '2026-10-12 19:15:36.52', null, null, null, 'Which of the following apparatus will require the smallest fuse rating for its protection?', '["60 W, 240 V","60 W, 40 V","40 W, 12 V","40 W, 5 V"]', 'Current I = P/V: 0.25 A, 1.5 A, 3.3 A and 8 A respectively. The 60 W, 240 V apparatus draws the smallest current.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('78e0da33-4067-4587-958b-3ae514b543fc', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The uniform makes the guards look <u>absurd</u>', null, '["smart","sensible","ridiculous","diny"]', 2, 'Absurd = ridiculous.', true, '2026-10-24 01:04:06.6', '2026-10-24 01:04:06.6', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The uniform makes the guards look <u>absurd</u>', '["smart","sensible","<u>ridiculous</u>","diny"]', '<b>Absurd</b> = <b>ridiculous</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('78e10785-0667-4002-b661-9f144c6cc579', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. He has a <u>big</u> heart, but he is inept at following a witty conversation.', null, '["large","huge","warm","fragile"]', 2, 'Big heart = warm/generous.', true, '2026-10-24 01:03:57.253', '2026-10-24 01:03:57.253', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. He has a <u>big</u> heart, but he is inept at following a witty conversation.', '["large","huge","<u>warm</u>","fragile"]', '<b>Big heart</b> = <b>warm</b>/generous.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('78ee3bba-1731-4a72-b98b-a3694293f2f3', 'Literature in English', 'JAMB', null, 2026, null, 'The speaker is a', null, '["Warlord","Servant","Politician","Military leader"]', 3, 'The speaker is a military leader.', true, '2026-09-12 11:11:17.369', '2026-09-12 11:11:17.369', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('78f87675-3f81-48b9-bae5-7fb4e1f3a47d', 'Physics', 'JAMB', null, 2026, null, 'Which of the following is a type of wave that is both mechanical and longitudinal?', null, '["Water waves","Seismic waves","Sound waves","Light waves"]', 2, 'Sound waves are both mechanical and longitudinal. They require a material medium for propagation (mechanical) and the particles vibrate parallel to the direction of wave propagation (longitudinal). Light waves are electromagnetic and transverse. Water waves are mechanical but transverse (surface waves).', true, '2026-09-10 10:56:43.09', '2026-09-10 10:56:43.09', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('78f8b61b-7dba-4a7f-ba2f-cf35d83480f3', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The boys knew that a storm was <u>imminent</u>.', null, '["possible","impending","threatening","encroaching"]', 1, 'Imminent = impending.', true, '2026-10-24 01:04:04.617', '2026-10-24 01:04:04.617', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The boys knew that a storm was <u>imminent</u>.', '["possible","<u>impending</u>","threatening","encroaching"]', '<b>Imminent</b> = <b>impending</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('78fbc732-7c52-41a4-b036-a877f842b1e1', 'Biology', 'JAMB', null, 2013, null, 'A pollutant that is biodegradable is', null, '["Cellophane","Sewage","Crude oil","Heavy metals"]', 1, 'Sewage is a biodegradable pollutant.', true, '2026-10-12 20:59:47.993', '2026-10-12 20:59:47.993', null, null, null, 'A pollutant that is biodegradable is', '["Cellophane","Sewage","Crude oil","Heavy metals"]', 'Sewage is a biodegradable pollutant.', '{"bold":["Sewage"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('790392b0-05f0-466b-846c-fe17af94e6e8', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. We intend to make the reception <u>a diurnal</u> event.', null, '["a nightly","a weekly","a short","an annual"]', 0, 'Diurnal = daytime; opposite = nightly.', true, '2026-10-24 07:21:22.154', '2026-10-24 07:21:22.154', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. We intend to make the reception <u>a diurnal</u> event.', '["a nightly","a weekly","a short","an annual"]', 'Diurnal = daytime; opposite = nightly.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7908395d-23ce-46fb-800a-640a0b540321', 'General Mathematics', 'JAMB', null, 2026, null, 'If 5^(x+1) - 3^x = 16, find x', null, '["3","2.5","1.5","2","2.87"]', 3, 'Testing x = 2: 5^(2+1) - 3^2 = 5^3 - 9 = 125 - 9 = 116 ≠ 16. Let me re-read: the question may be 5^x - 3^x = 16. If x = 2: 25 - 9 = 16. Yes! So 5^2 - 3^2 = 25 - 9 = 16. Therefore x = 2.', true, '2026-09-10 10:48:18.452', '2026-09-10 10:48:18.452', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('790b6494-ce0c-41dc-8c95-edf7dc890c5b', 'Literature in English', 'JAMB', null, 2026, null, '______ is the arrangement of stressed and unstressed syllables in a line of poem', null, '["rhythm","rhetorical arrangement","meter","ballad"]', 2, 'Meter is the arrangement of stressed and unstressed syllables.', true, '2026-09-12 11:05:38.625', '2026-09-12 11:05:38.625', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7915f17a-d195-41d5-bc6d-ee9d0c05b801', 'General Mathematics', 'JAMB', null, 2026, null, 'Evaluate √-4 × √-9', null, '["6","0","-6","-12"]', 2, '√-4 = 2i and √-9 = 3i, where i = √-1. So √-4 × √-9 = 2i × 3i = 6i² = 6(-1) = -6.', true, '2026-09-10 10:48:18.403', '2026-09-10 10:48:18.403', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7918986a-deef-476c-b854-b2ab9366b604', 'Biology', 'JAMB', null, 2026, null, 'The tendency of organisms as they evolve is the', null, '["decrease in size","increase in number","development of specialized structures","feed indiscriminately"]', 2, 'The tendency of organisms as they evolve is the development of specialized structures. Evolution leads to adaptations that make organisms more suited to their environment, often through the development of structures specialized for particular functions. This is called adaptive radiation. While organisms can increase in number over time, the key evolutionary trend is the development of specialized structures.', true, '2026-09-09 03:19:20.436', '2026-09-09 03:19:20.436', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('791b4b5a-e750-4dce-a50f-aabf7527e499', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). Jide is <u>being forced to</u> go to Lagos tomorrow. This means that Jide ____________', null, '["will go to Lagos","must go to Lagos","wishes to go to Lagos","is going to Lagos","goes to Lagos"]', 1, '''Being forced to'' expresses obligation â†’ must.', true, '2026-10-24 01:04:13.174', '2026-10-24 01:04:13.174', null, null, null, '(Choose the most appropriate interpretation). Jide is <u>being forced to</u> go to Lagos tomorrow. This means that Jide ____________', '["will go to Lagos","<u>must go to Lagos</u>","wishes to go to Lagos","is going to Lagos","goes to Lagos"]', '''<b>Being forced to</b>'' expresses obligation â†’ <b>must</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('792a32ec-79a7-480b-af39-bed96752999b', 'Government', 'JAMB', null, 2026, null, 'The executive checks the excesses of the legislature through', null, '["assent to bills","insurance of orders","the use of veto power","the ratification of treaties"]', 2, 'The executive checks the legislature through veto power.', true, '2026-09-12 11:24:10.764', '2026-09-12 11:24:10.764', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('792a8583-6d81-498e-911d-a59c8deb8bf1', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). The fact that Ruth has inherited her late husband''s house is <u>cold comfort to her</u>.', null, '["appropriate comfort","inadequate comfort","no comfort at all","wet comfort"]', 1, '''Cold comfort'' = inadequate consolation.', true, '2026-10-24 01:04:18.253', '2026-10-24 01:04:18.253', null, null, null, '(Choose the most appropriate interpretation). The fact that Ruth has inherited her late husband''s house is <u>cold comfort to her</u>.', '["appropriate comfort","<u>inadequate comfort</u>","no comfort at all","wet comfort"]', '''<b>Cold comfort</b>'' = <b>inadequate consolation</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('793cbe7f-d806-4933-91dc-7e86746fef57', 'Government', 'JAMB', null, 2026, null, 'Laws enacted by the legislature are known as', null, '["legislation","legislature","budget","executive"]', 0, 'Laws enacted by the legislature are legislation.', true, '2026-09-12 11:24:57.736', '2026-09-12 11:24:57.736', null, null, null, null, null, null, null);
