insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('79ac24ce-6f48-44e0-bc77-463d16f38950', 'Government', 'JAMB', null, 2026, null, 'In the all-Nigerian constitutional conference of 1950', null, '["all official members of the legislative council participated","it was resolved that the Nigerians federation be organized on ethnic basis","it was concluded that a quasi-federal structure should be developed for colonial Nigeria","all unofficial members of the legislative council participated"]', 3, 'In the all-Nigerian constitutional conference of 1950, all unofficial members of the legislative council participated. The Ibadan Conference of 1950 was convened to review the Richards Constitution and discuss the future constitutional arrangements for Nigeria. It was unique because all unofficial (elected and nominated Nigerian) members were invited to participate, unlike previous conferences. The conference recommended a federal system with greater autonomy for the regions.', true, '2026-09-10 10:44:18.773', '2026-09-10 10:44:18.773', null, null, null, null, null, null, null);
