insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('79b320fc-9e95-4738-bbcc-88ac89a3665d', 'Physics', 'JAMB', null, 2000, null, 'When a ship sails from salt water into fresh water, the fraction of its volume above the water surface will', null, '["Remain the same","Increase","Decrease","Increase then decrease."]', 2, 'Fresh water is less dense, so the ship must displace more water to float. It sinks lower and less of it is above the surface.', true, '2026-10-12 19:15:49', '2026-10-12 19:15:49', null, null, null, 'When a ship sails from salt water into fresh water, the fraction of its volume above the water surface will', '["Remain the same","Increase","Decrease","Increase then decrease."]', 'Fresh water is less dense, so the ship must displace more water to float. It sinks lower and less of it is above the surface.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
