insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7a28d046-819e-4699-a545-2d36d4f01e32', 'Physics', 'JAMB', null, 1985, null, 'Which of the following is NOT a fundamental S.I. unit?', null, '["Metre","Ampere","Kelvin","Second","Radian"]', 4, 'The base SI units include the metre, kilogram, second, ampere, kelvin, mole and candela. The radian is a supplementary (derived) unit.', true, '2026-10-12 19:15:20.496', '2026-10-12 19:15:20.496', null, null, null, 'Which of the following is <b>NOT</b> a fundamental S.I. unit?', '["Metre","Ampere","Kelvin","Second","Radian"]', 'The base SI units include the metre, kilogram, second, ampere, kelvin, mole and candela. The radian is a supplementary (derived) unit.', '{"bold":["NOT"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7a2de669-e95a-44fd-9941-006f0a1ec050', 'Yoruba', 'JAMB', null, 2007, null, 'Ilé-ayé ò jè nykan, Àlà lásán ni, Òkàn tó þ sùn ti dòkú, Nykan ò rí bí a ti rò ó Ilé-ayé gbçgè. Sàréè ì ýopin èdá. Eérú fún eérú, Eruku fún eruku, Lôba-òkè sô fênìyàn, Tó j’Òlörun nípè. Àmò hùwà bí çni pé, Ojoojúmò lèdá p súnmòlé. Màà gbèkèké òlá Màà nígbçkèlé nínú òrõ. Alágbára ayé, ç rõra ýe. Bí ó ti wù ká ki lòkàn tó, Kìkì ní í lù, Báa bá gbòlù ikú, Àtorin arò ti p kòjá lóde. Ojú ogun layé. Má bojú wèyìn, Jà bí akin lójù ìjà. Rántí ayé àkòni tó kòjà, Wo àwòkòyè wòn fún òjò òla tìrç. Gbé ìgbé-ayé alààyè, Jè kí òkú sunkún ara wòn. Àwé, má ronú mò, Jè ká máa ììyé lò. Máa jagun lò, Má wèyìn, Má ìyìè méjì, Bó pè, bó yá, Ayõ p bõ. … i ní ilà 17 tòka sí', null, '["òkàn","ikú","ayé","ilú."]', 0, '… i ní ilà 17 tòka sí òkàn.', true, '2026-10-13 13:23:31.028', '2026-10-13 13:23:31.028', null, null, null, 'Ilé-ayé ò jè nykan, Àlà lásán ni, Òkàn tó þ sùn ti dòkú, Nykan ò rí bí a ti rò ó Ilé-ayé gbçgè. Sàréè ì ýopin èdá. Eérú fún eérú, Eruku fún eruku, Lôba-òkè sô fênìyàn, Tó j’Òlörun nípè. Àmò hùwà bí çni pé, Ojoojúmò lèdá p súnmòlé. Màà gbèkèké òlá Màà nígbçkèlé nínú òrõ. Alágbára ayé, ç rõra ýe. Bí ó ti wù ká ki lòkàn tó, Kìkì ní í lù, Báa bá gbòlù ikú, Àtorin arò ti p kòjá lóde. Ojú ogun layé. Má bojú wèyìn, Jà bí akin lójù ìjà. Rántí ayé àkòni tó kòjà, Wo àwòkòyè wòn fún òjò òla tìrç. Gbé ìgbé-ayé alààyè, Jè kí òkú sunkún ara wòn. Àwé, má ronú mò, Jè ká máa ììyé lò. Máa jagun lò, Má wèyìn, Má ìyìè méjì, Bó pè, bó yá, Ayõ p bõ. … i ní ilà 17 tòka sí', '["òkàn","ikú","ayé","ilú."]', '… i ní ilà 17 tòka sí òkàn.', '{"bold":["òkàn"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7a2f58d9-4176-4f00-ba4d-0e48051dbe0f', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Some travellers <u>unwittingly</u> render themselves open prey to questionable character.', null, '["genuinely","wholesomely","knowingly","inadvertently"]', 2, 'Unwittingly = unintentionally; opposite = knowingly.', true, '2026-10-24 07:21:17.91', '2026-10-24 07:21:17.91', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Some travellers <u>unwittingly</u> render themselves open prey to questionable character.', '["genuinely","wholesomely","knowingly","inadvertently"]', 'Unwittingly = unintentionally; opposite = knowingly.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7a2fd09b-58ca-4591-822f-d921ac53b1b5', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. There are many areas of <u>convergence</u> between male and female behaviour.', null, '["concomitance","concordance","incompatibility","incomparability"]', 2, 'Convergence = agreement; opposite = incompatibility.', true, '2026-10-24 07:21:18.161', '2026-10-24 07:21:18.161', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. There are many areas of <u>convergence</u> between male and female behaviour.', '["concomitance","concordance","incompatibility","incomparability"]', 'Convergence = agreement; opposite = incompatibility.', '{}');
