insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7a8f1250-e76d-4c9e-9dcf-b29af73e6fb0', 'Physics', 'JAMB', null, 1990, null, 'What must be the distance between an object and a converging lens of focal length 20 cm to produce an erect image two times the object height?', null, '["20 cm","15 cm","10 cm","5 cm"]', 2, 'An erect image is virtual: m = f/(f - u) with u positive gives 2 = 20/(20 - u), so u = 10 cm.', true, '2026-10-12 19:15:31.357', '2026-10-12 19:15:31.357', null, null, null, 'What must be the distance between an object and a converging lens of focal length 20 cm to produce an erect image two times the object height?', '["20 cm","15 cm","10 cm","5 cm"]', 'An erect image is virtual: m = f/(f - u) with u positive gives 2 = 20/(20 - u), so u = 10 cm.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7a9d37f9-e1cd-4ba1-9824-39fba5895331', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). If Garba had listened to advice, <u>he would not have had to be rushed to the hospital</u>.', null, '["deliberately desired to be rushed","was in position to have prevented the need to be rushed","was rushed against his wish","was given a cheque, but preferred to go"]', 1, 'Third conditional = could have prevented.', true, '2026-10-24 01:04:18.143', '2026-10-24 01:04:18.143', null, null, null, '(Choose the most appropriate interpretation). If Garba had listened to advice, <u>he would not have had to be rushed to the hospital</u>.', '["deliberately desired to be rushed","<u>was in position to have prevented the need to be rushed</u>","was rushed against his wish","was given a cheque, but preferred to go"]', 'Third conditional = <b>could have prevented</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7a9def5c-a452-40df-8969-f814fee70269', 'Biology', 'JAMB', null, 2026, null, 'In vegetative propagation which of the following requires part of another plant to develop?', null, '["scion","bulb","rhizomes","sucker"]', 0, 'A scion is the part of a plant (shoot or bud) that is grafted onto another plant (rootstock) during grafting. It requires the rootstock (another plant) to develop as a separate plant. Bulbs, rhizomes, and suckers are all forms of natural vegetative propagation where a part of the parent plant develops into a new independent plant without requiring another plant. Grafting with a scion is a form of artificial vegetative propagation where two different plants are joined together to combine desirable traits.', true, '2026-09-09 03:18:28.396', '2026-09-09 03:18:28.396', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7aa5dd87-ef75-4ecd-9927-9bf7f2097355', 'Chemistry', 'JAMB', null, 2026, null, 'Which non-metal is essential in the Contact process for producing sulfuric acid because it forms sulfur dioxide first?', null, '["Sulfur","Nitrogen","Carbon","Oxygen"]', 0, 'Sulfur is essential in the Contact process. It is burned in air to form sulfur dioxide (S + O₂ → SO₂), which is then converted to sulfur trioxide (2SO₂ + O₂ ⇌ 2SO₃) and finally to sulfuric acid. Nitrogen, carbon, and oxygen are not the primary raw material.', true, '2026-09-12 09:38:17.554', '2026-09-12 09:38:17.554', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7aa87d9d-26a7-43cd-b86a-9b5384bc6a76', 'Literature in English', 'JAMB', null, 2026, null, '''Their silence spoke millions'' illustrates', null, '["oxymoron","litotes","antithesis","assonance"]', 0, 'It illustrates oxymoron.', true, '2026-09-12 11:14:03.872', '2026-09-12 11:14:03.872', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7aac628c-a875-46cc-979b-324a774f02b5', 'English Language', 'JAMB', null, 2007, null, 'Why do you worry about such <u>__________</u> matters?', null, '["insignificant","significant","non-significant","unsignificant"]', 0, 'Correct spelling: insignificant.', true, '2026-10-24 07:21:33.25', '2026-10-24 07:21:33.25', null, null, null, 'Why do you worry about such <u>__________</u> matters?', '["insignificant","significant","non-significant","unsignificant"]', 'Correct spelling: insignificant.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7ab0cdf7-38df-4d31-99b1-eb3a5235285e', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The journalist said he was working <u>freelance</u>.', null, '["satisfactorily","without a pay","dependently","tirelessly"]', 2, 'Freelance = independent; opposite = dependently.', true, '2026-10-24 07:21:24.979', '2026-10-24 07:21:24.979', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The journalist said he was working <u>freelance</u>.', '["satisfactorily","without a pay","dependently","tirelessly"]', 'Freelance = independent; opposite = dependently.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7ab3fb47-9a1e-49ea-b0ab-7d601dbd7edd', 'Literature in English', 'JAMB', null, 2026, null, 'The character of Bendu is significant primarily because she', null, '["Represents political authority in post-war Liberia","Embodies the psychological and emotional scars of the civil war","Serves as comic relief throughout the narrative","Symbolises Western intervention in Africa"]', 1, 'Bendu embodies the psychological and emotional scars of the civil war.', true, '2026-09-12 11:04:53.452', '2026-09-12 11:04:53.452', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7abb4f79-e9c2-41cb-8888-9d3b4cbd45a1', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The case was thrown out because the court lacked <u>jurisdiction</u>.', null, '["jurors to help the judge","authority","prosecutors","appellate powers"]', 1, 'Jurisdiction = authority.', true, '2026-10-24 01:03:57.147', '2026-10-24 01:03:57.147', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The case was thrown out because the court lacked <u>jurisdiction</u>.', '["jurors to help the judge","<u>authority</u>","prosecutors","appellate powers"]', '<b>Jurisdiction</b> = <b>authority</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7ac07dc3-d8e0-46a0-be42-c3858e5bbd8c', 'Physics', 'JAMB', null, 1988, null, 'A spectrum of sunlight is said to be impure when', null, '["It is made of only three colours","It has no red colour in it","The different colours in it overlap","It does not contain white light."]', 2, 'In an impure spectrum the colours overlap, so each colour is not clearly separated from its neighbours.', true, '2026-10-12 19:15:28.119', '2026-10-12 19:15:28.119', null, null, null, 'A spectrum of sunlight is said to be impure when', '["It is made of only three colours","It has no red colour in it","The different colours in it overlap","It does not contain white light."]', 'In an impure spectrum the colours overlap, so each colour is not clearly separated from its neighbours.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7ac4eb0b-a9d6-4a60-90d5-fe3e94d3988f', 'Physics', 'JAMB', null, 1997, null, 'An electric water pump rated 1.5 kW lifts 200 kg of water through a vertical height of 6 metres in 10 seconds. What is the efficiency of the pump? [g = 10 m s⁻²; neglect air resistance]', null, '["90.0%","85.0%","80.0%","65.0%"]', 2, 'Output power = (200 x 10 x 6)/10 = 1200 W. Efficiency = 1200/1500 x 100 = 80.0%.', true, '2026-10-12 19:15:43.035', '2026-10-12 19:15:43.035', null, null, null, 'An electric water pump rated 1.5 kW lifts 200 kg of water through a vertical height of 6 metres in 10 seconds. What is the efficiency of the pump? [g = 10 m s<sup>-2</sup>; neglect air resistance]', '["90.0%","85.0%","80.0%","65.0%"]', 'Output power = (200 x 10 x 6)/10 = 1200 W. Efficiency = 1200/1500 x 100 = 80.0%.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7acf47d1-e29d-42b9-82ed-3277f7ec6de2', 'Financial Accounting', 'UTME', null, 2003, null, 'The goodwill on purchase is', 'https://res.cloudinary.com/kwi1uv0g/image/upload/v1791841571/questions/wiqixshonomae8jmtu4l.jpg', '["N90 000","N30 000","N19 000","N18 000"]', 1, 'Goodwill calculation: Purchase consideration 120,000 - Net Cash 90,000 = Goodwill 30,000.', true, '2026-10-12 22:00:01.459', '2026-10-12 22:00:01.459', null, null, null, 'The goodwill on purchase is', '["N90 000","<b>N30 000</b>","N19 000","N18 000"]', 'Goodwill calculation: Purchase consideration 120,000 - Net Cash 90,000 = Goodwill <b>30,000</b>.', '{"bold":["30,000"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7ad11476-fd71-4230-af30-a7040c51e8db', 'Literature in English', 'JAMB', null, 2026, null, 'The line ''the sea will groan under its weight'' in Breast of the Sea is an example of which literary device', null, '["Allusion","Hyperbole","Personification","Metonymy"]', 2, 'It is personification.', true, '2026-09-12 11:13:56.814', '2026-09-12 11:13:56.814', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7ad87ecd-d39e-4620-8884-bfed301623e5', 'Physics', 'JAMB', null, 2002, null, 'An electric iron is rated 1 000 W, 230 V. What is the resistance of its element?', null, '["57.6 Ω","55.9 Ω","51.9 Ω","52.9 Ω"]', 3, 'R = V²/P = 230²/1000 = 52.9 Ω.', true, '2026-10-12 19:15:54.084', '2026-10-12 19:15:54.084', null, null, null, 'An electric iron is rated 1 000 W, 230 V. What is the resistance of its element?', '["57.6 Ω","55.9 Ω","51.9 Ω","52.9 Ω"]', 'R = V<sup>2</sup>/P = 230<sup>2</sup>/1000 = 52.9 Ω.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7aec116c-4afe-4791-a21b-4bc5989c420e', 'Literature in English', 'JAMB', null, 2026, null, 'A stanza of three lines linked by rhyme is generally called', null, '["a Couplet","a Ballad","a Tercet","a Quatrain"]', 2, 'A three-line stanza is a tercet.', true, '2026-09-12 11:13:54.485', '2026-09-12 11:13:54.485', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7aeec321-5d6e-4eb3-ab22-a40a243113d9', 'English Language', 'JAMB', null, 2007, null, 'The policemen pointed out a <u>__________</u> between Mr. Ogene''s two accounts of the incident.', null, '["discrepancy","discord","distinction","disagreement"]', 0, 'Correct spelling: discrepancy.', true, '2026-10-24 07:21:44.117', '2026-10-24 07:21:44.117', null, null, null, 'The policemen pointed out a <u>__________</u> between Mr. Ogene''s two accounts of the incident.', '["discrepancy","discord","distinction","disagreement"]', 'Correct spelling: discrepancy.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7aeec66a-060e-4c9e-af66-df04c2970aeb', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'To whom was this addressed? ''Rule over us, you and your son and your grandson also; for you have delivered us out of the hand of Midian''', null, '["Deborah","Samson","Gideon","Jephthah"]', 2, 'This statement was addressed to Gideon. After Gideon delivered Israel from the Midianites, the Israelites asked him to rule over them, along with his son and grandson. Gideon refused, saying, ''I will not rule over you, and my son will not rule over you; the LORD will rule over you.''', true, '2026-09-12 09:46:00.357', '2026-09-12 09:46:00.357', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7afeaa8b-2c99-4cb3-8833-bde2b14a1dc3', 'Physics', 'JAMB', null, 1992, null, 'The equation of a wave is y = 0.005 sin[π(0.5x - 200t)], where x and y are in metres and t is in seconds. What is the velocity of the wave?', null, '["4 000 m s⁻¹","400 m s⁻¹","250 m s⁻¹","40 m s⁻¹"]', 1, 'Comparing with y = A sin(kx - ωt), v = ω/k = 200/0.5 = 400 m s⁻¹.', true, '2026-10-12 19:15:35.606', '2026-10-12 19:15:35.606', null, null, null, 'The equation of a wave is y = 0.005 sin[π(0.5x - 200t)], where x and y are in metres and t is in seconds. What is the velocity of the wave?', '["4 000 m s<sup>-1</sup>","400 m s<sup>-1</sup>","250 m s<sup>-1</sup>","40 m s<sup>-1</sup>"]', 'Comparing with y = A sin(kx - ωt), v = ω/k = 200/0.5 = 400 m s<sup>-1</sup>.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7afeea03-98da-42b9-9bc3-72a36e32a53d', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). The new educational system <u>took off</u> this school year.', null, '["went off","continued","began","resumed"]', 2, '''Took off'' = began.', true, '2026-10-24 01:02:03.18', '2026-10-24 01:02:03.18', null, null, null, '(Choose the most appropriate interpretation). The new educational system <u>took off</u> this school year.', '["went off","continued","<u>began</u>","resumed"]', '''<b>Took off</b>'' = <b>began</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7b0914f4-3155-4f32-af1d-0b3cadcf9216', 'Economics', 'JAMB', null, 2026, null, '''There will be a general rise in the price level of goods and services whenever the supply of money is greater than the supply of goods and services in an economy''. This statement is a', null, '["Normative statement","positive statement","inferential statement","The combination of normative and positive statement"]', 1, 'This is a positive statement because it describes what is (cause and effect).', true, '2026-09-12 11:00:52.518', '2026-09-12 11:00:52.518', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7b126fab-ad79-48b0-a169-64586364c963', 'Physics', 'JAMB', null, 2026, null, 'Which is a unit of gravitational Field intensity?', null, '["N/kg","m/s²","Jm⁻¹kg⁻¹","All","None"]', 3, 'Gravitational field intensity has units of N/kg, m/s², and Jm⁻¹kg⁻¹. All three are equivalent units for gravitational field intensity. N/kg = m/s² = J/(m·kg).', true, '2026-09-10 10:56:45.037', '2026-09-10 10:56:45.037', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7b15d214-dcd4-48d5-8ac8-fdcd7d33e899', 'Physics', 'JAMB', null, 1984, null, 'For a concave mirror to form a real diminished image, the object must be placed', null, '["Behind the mirror","Between the mirror and in focus","Between the focus and the center of curvature","At the center of curvature","At a distance greater than the radius of curvature."]', 4, 'When the object is beyond the centre of curvature, the image is real, inverted, diminished and lies between F and C.', true, '2026-10-12 19:15:18.585', '2026-10-12 19:15:18.585', null, null, null, 'For a concave mirror to form a real diminished image, the object must be placed', '["Behind the mirror","Between the mirror and in focus","Between the focus and the center of curvature","At the center of curvature","At a distance greater than the radius of curvature."]', 'When the object is beyond the centre of curvature, the image is real, inverted, diminished and lies between F and C.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7b1afdec-40cd-4371-b3df-078687288268', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'During the reign of Josiah, the book of law was found in the temple by', null, '["Zedekiah","Shaphan","Isaiah","Hilkiah"]', 3, 'Hilkiah the high priest found the book of the law.', true, '2026-09-12 10:42:04.772', '2026-09-12 10:42:04.772', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7b54160e-db41-48fa-b52b-8ad2032a858a', 'Physics', 'JAMB', null, 2026, null, 'Which of the following statements is false about isotopes of the same element?', null, '["they have same numbers of electrons in their outermost shell","they have different atomic mass","they have same proton number but different numbers of electrons","can be separated by physical means"]', 2, 'The statement that isotopes have the same proton number but different numbers of electrons is false. Isotopes of the same element have the same number of protons and electrons (in neutral atoms) but different numbers of neutrons. They have the same proton number and different mass numbers.', true, '2026-09-10 10:56:40.76', '2026-09-10 10:56:40.76', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7b580ad9-7aa8-4e9b-b5d1-6e413f0703ea', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The presidential aspirant warned of the political <u>catastrophe</u> that would follow if the election were rigged.', null, '["problem","turmoil","success","conflagration"]', 2, 'Catastrophe = disaster; opposite = success.', true, '2026-10-24 07:21:19.123', '2026-10-24 07:21:19.123', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The presidential aspirant warned of the political <u>catastrophe</u> that would follow if the election were rigged.', '["problem","turmoil","success","conflagration"]', 'Catastrophe = disaster; opposite = success.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7b59deba-c126-48fd-a9f0-33588ec93448', 'Literature in English', 'JAMB', null, 2026, null, 'The word "octave" refers to the first eight lines of', null, '["Lyric","Sonnet","Ode","Dirge"]', 1, 'The word "octave" refers to the first eight lines of a sonnet. A sonnet is a 14-line poem, and its structure is often divided into an octave (first 8 lines) and a sestet (last 6 lines). The octave typically presents a problem or question, while the sestet provides a resolution or answer. A lyric is a type of poem, an ode is a poem of praise, and a dirge is a mournful song.', true, '2026-09-10 10:47:09.767', '2026-09-10 10:47:09.767', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7b75dc86-3ced-4f96-9796-a64c59065f77', 'Biology', 'JAMB', null, 2026, null, 'The miniature shoot in a newly germinating plant is ______ and has a sheath known as ______', null, '["I & IV","I & V","III & V","III & IV","IV & III"]', 0, 'The miniature shoot in a newly germinating plant is the plumule (I), and it has a sheath known as the coleoptile (IV) in monocot plants. The plumule is the embryonic shoot that develops into the stem and first true leaves. The coleoptile is a protective sheath that covers the plumule as it pushes through the soil during germination. The radicle (III) is the embryonic root, and the coleorhiza (V) is the root sheath in monocot seedlings. The cotyledon (II) is the seed leaf and not the shoot structure.', true, '2026-09-09 03:18:37.035', '2026-09-09 03:18:37.035', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7b7bdae6-cc3d-4a33-aab1-a85d850a88a1', 'Christian Religious Studies', 'JAMB', null, 2026, null, '''But I will be with you and you will smite the Midianites as one man'' was said by God to', null, '["Moses","Joshua","Gideon","Deborah"]', 2, 'God said this to Gideon when He called him to deliver Israel from the Midianites. God assured Gideon of His presence and promised victory.', true, '2026-09-12 09:46:00.796', '2026-09-12 09:46:00.796', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7b824135-1948-44e8-86d2-65e8aacf52ea', 'Government', 'JAMB', null, 2026, null, 'Another name for parliamentary system of government is', null, '["Westminster","Executive","Westminister","Constitutional"]', 0, 'Another name for parliamentary system of government is Westminster. The Westminster system originated in the United Kingdom and is characterized by a fusion of powers between the executive and legislature, a ceremonial head of state, and a head of government (prime minister) who is accountable to parliament. The correct spelling is ''Westminster'' (not ''Westminister'').', true, '2026-09-10 10:45:06.463', '2026-09-10 10:45:06.463', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7b85189e-fcce-4bdd-ae75-f4fc7b1d50a0', 'Biology', 'JAMB', null, 2026, null, 'Which of the above structures is correctly matched with the organisms? I. Stomata → Spirogyra II. Alveoli → Earthworm III. Malpighian tubule → Mammal IV. Contractile vacuole → Protozoa', null, '["III","II","I","IV"]', 3, 'The contractile vacuole is correctly matched with Protozoa (IV). Contractile vacuoles are osmoregulatory organelles in freshwater protists. Stomata are found in higher plants, not Spirogyra (an alga). Alveoli are respiratory structures in mammals, not earthworms (earthworms use skin/cutaneous respiration). Malpighian tubules are excretory structures in insects, not mammals (mammals use kidneys). Therefore, only option IV is correctly matched.', true, '2026-09-09 03:19:01.422', '2026-09-09 03:19:01.422', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7b87e9b2-1f85-4874-9a13-1b43492b2c8d', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Some actions of the Nigerian youth have <u>alienated</u> them from those who were <u>sympathetic</u> to their cause.', null, '["endeared/kindly","confronted/ill disposed","separated/opposed","estranged/well disposed"]', 3, 'Alienated/sympathetic = estranged/well disposed.', true, '2026-10-24 01:04:02.102', '2026-10-24 01:04:02.102', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Some actions of the Nigerian youth have <u>alienated</u> them from those who were <u>sympathetic</u> to their cause.', '["endeared/kindly","confronted/ill disposed","separated/opposed","<u>estranged/well disposed</u>"]', '<b>Alienated/sympathetic</b> = <b>estranged/well disposed</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7b892917-9a48-4b6a-8eb0-524e2c62523b', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The group of performers thrilled the audience with its peculiar <u>choreography</u>.', null, '["form of dancing","art of theatrics","type of costuming","mode of singing"]', 0, 'Choreography = form of dancing.', true, '2026-10-24 01:01:48.071', '2026-10-24 01:01:48.071', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The group of performers thrilled the audience with its peculiar <u>choreography</u>.', '["<u>form of dancing</u>","art of theatrics","type of costuming","mode of singing"]', '<b>Choreography</b> = <b>form of dancing</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7b897b04-8190-4021-a8cf-1e38c1264a2d', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Jeroboam''s major sin was', null, '["idolatry with golden calves","heavy taxation","rejecting prophets","alliance with Egypt"]', 0, 'Jeroboam''s major sin was idolatry with golden calves. He set up two golden calves, one at Bethel and one at Dan, and told the people, ''Behold your gods, O Israel, who brought you up out of the land of Egypt.'' This led Israel into idolatry.', true, '2026-09-12 09:45:47.849', '2026-09-12 09:45:47.849', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7b9b4257-4528-4721-bbe5-2d361027312f', 'Literature in English', 'JAMB', null, 2026, null, 'In The Nun''s Priest''s Tale, the character of Chanticleer is best described as', null, '["A tragic hero","An allegorical figure representing pride and vanity","A static rural character","A symbol of political authority"]', 1, 'Chanticleer is an allegorical figure representing pride and vanity.', true, '2026-09-12 11:12:03.024', '2026-09-12 11:12:03.024', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7b9fe2a8-5de4-4c00-aa8c-cd985a54bf88', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). Yahaya hardly knows on which side his <u>bread is buttered</u> in the matter.', null, '["where his interest lies","what he must do","whom to contact for help","where he should go"]', 0, '''Know which side one''s bread is buttered'' = know where interest lies.', true, '2026-10-24 01:02:05.853', '2026-10-24 01:02:05.853', null, null, null, '(Choose the most appropriate interpretation). Yahaya hardly knows on which side his <u>bread is buttered</u> in the matter.', '["<u>where his interest lies</u>","what he must do","whom to contact for help","where he should go"]', '''<b>Know which side one''s bread is buttered</b>'' = <b>know where interest lies</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7ba342c9-a84f-442f-bfd2-5d7187cffcea', 'English Language', 'JAMB', null, 2024, null, 'Identify the option that is nearest in meaning to the underlined word: The rapper''s popularity is beginning to wane', null, '["disappear","change","disperse","decline"]', 3, '"Wane" means to decrease or decline.', true, '2026-09-18 09:43:02.524', '2026-09-18 09:43:02.524', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7ba528e1-2aec-4674-9ed9-76da328dcd8f', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). Once I have <u>finished all my homework I am permitted</u> to watch television.', null, '["I can watch television at anytime","I can only watch television after doing my homework.","Television comes first, then homework second.","I can only finish my homework after permission to watch television.","After watching television, I finished my homework"]', 1, 'Homework before television.', true, '2026-10-24 01:02:01.582', '2026-10-24 01:02:01.582', null, null, null, '(Choose the most appropriate interpretation). Once I have <u>finished all my homework I am permitted</u> to watch television.', '["I can watch television at anytime","<u>I can only watch television after doing my homework.</u>","Television comes first, then homework second.","I can only finish my homework after permission to watch television.","After watching television, I finished my homework"]', '<b>Homework</b> before television.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7bb011d7-0855-48c9-b7fe-30492c4dc1d9', 'English Language', 'JAMB', null, 2007, null, 'The plane overshot the <u>__________</u> in a minor accident', null, '["railway","hangar","tarmac","run-way","road"]', 3, 'Correct spelling: run-way.', true, '2026-10-24 07:21:40.781', '2026-10-24 07:21:40.781', null, null, null, 'The plane overshot the <u>__________</u> in a minor accident', '["railway","hangar","tarmac","run-way","road"]', 'Correct spelling: run-way.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7bc8a9a4-94f5-48d5-991c-d782001420f3', 'Government', 'JAMB', null, 2026, null, 'Which of the following received the Nigerian government support and backing during the Angolan struggle?', null, '["Movement for Population Liberation of Angola (MPLA)","National Front for the Liberation of Angola (FLNA)","Union for the Total Independence of Angola (UNITA)","Freedom Movement for United Angola (FMUA)"]', 0, 'Nigeria supported the MPLA during the Angolan struggle.', true, '2026-09-12 11:24:14.821', '2026-09-12 11:24:14.821', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7bce7ee2-69e0-44f2-8f2a-762a2c8568ce', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. I am yet to write the <u>penultimate</u> paragraph of my essay.', null, '["last but one","third to the last","second","concluding","introductory"]', 0, 'Penultimate = last but one.', true, '2026-10-24 01:01:40.879', '2026-10-24 01:01:40.879', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. I am yet to write the <u>penultimate</u> paragraph of my essay.', '["<u>last but one</u>","third to the last","second","concluding","introductory"]', '<b>Penultimate</b> = <b>last but one</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7bdc5d0d-27b8-43e1-9fab-3b1ffe1a36ff', 'Physics', 'JAMB', null, 2026, null, 'If a wheel 1.2m in diameter rotates at one revolution per second, calculate the velocity of the wheel.', null, '["3.6 ms⁻¹","3.77 ms⁻¹","4.0 ms⁻¹","7.5 ms⁻¹"]', 1, 'Circumference = πD = π × 1.2 = 3.77m. Velocity = circumference × frequency = 3.77 × 1 = 3.77 ms⁻¹.', true, '2026-09-10 10:56:47.879', '2026-09-10 10:56:47.879', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7be45530-510d-4dca-8c34-e93ff7df9f50', 'Biology', 'JAMB', null, 2003, null, 'In the internal structure of plants, a wide pith in the center is common to', null, '["dicot stems and monocot stems","dicot stems and monocot roots","dicot roots and monocot roots","dicot roots and monocot stems"]', 1, 'Dicot stems and monocot roots typically feature a prominent central pith.', true, '2026-10-12 20:05:11.059', '2026-10-12 20:05:11.059', null, null, null, 'In the internal structure of plants, a wide pith in the center is common to', '["dicot stems and monocot stems","dicot stems and monocot roots","dicot roots and monocot roots","dicot roots and monocot stems"]', 'Dicot stems and monocot roots typically feature a prominent central pith.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7be52c32-adf7-4152-abad-ceea66f58f6a', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Your effort to bring peace between us is futile because you are <u>biased</u>.', null, '["convinced","clever","prejudiced","worried"]', 2, 'Biased = prejudiced.', true, '2026-10-24 01:04:08.322', '2026-10-24 01:04:08.322', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Your effort to bring peace between us is futile because you are <u>biased</u>.', '["convinced","clever","<u>prejudiced</u>","worried"]', '<b>Biased</b> = <b>prejudiced</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7be5c46f-c6da-41db-b108-07049006f224', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). The Vice Chancellor, who is <u>stickler for rules</u>, refused the request by the students for the semester to be rescheduled.', null, '["a puritan","a pedantist","a disciplinarian","an idealist"]', 2, '''Stickler for rules'' = disciplinarian.', true, '2026-10-24 01:04:20.398', '2026-10-24 01:04:20.398', null, null, null, '(Choose the most appropriate interpretation). The Vice Chancellor, who is <u>stickler for rules</u>, refused the request by the students for the semester to be rescheduled.', '["a puritan","a pedantist","<u>a disciplinarian</u>","an idealist"]', '''<b>Stickler for rules</b>'' = <b>disciplinarian</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7bed7146-516d-4ed7-b906-7be8ef768476', 'Biology', 'JAMB', null, 2026, null, 'The barrier between maternal and fetal blood is the', null, '["Placenta","Liver","Umbilical cord","Uterine wall"]', 0, 'The placenta is the barrier between maternal and fetal blood. It is a specialized organ that allows exchange of nutrients, gases, and waste between mother and fetus while preventing their blood from directly mixing. The umbilical cord connects the fetus to the placenta. The liver is an organ of the fetus. The uterine wall is the muscular wall of the uterus. The placental barrier allows selective passage of substances: oxygen, nutrients, and antibodies pass to the fetus, while CO₂ and urea pass to the mother.', true, '2026-09-09 03:19:00.989', '2026-09-09 03:19:00.989', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7bf306e6-c715-4a7b-8dee-75b60f33e9d3', 'English Language', 'JAMB', null, 2024, null, '36', null, '["conflict","equidistance","equilibrium","opprobrium"]', 2, 'The mechanism brings about equilibrium (balance) between producers and consumers.', true, '2026-09-18 10:17:48.755', '2026-09-18 10:17:48.755', '01c7070a-0591-4cea-af06-fe54980dbb5f', 7, 'CLOZE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7bfbd0aa-62fa-43f1-833a-3027a23abe62', 'Biology', 'JAMB', null, 2026, null, 'During thunderstorms the energy of lightning discharge causes', null, '["oxygen and nitrogen to combine","more carbon dioxide to be formed","nitrites to be converted to nitrates","nitrates to be converted to nitrogen"]', 0, 'During thunderstorms, lightning energy causes oxygen and nitrogen to combine, forming nitric oxide (NO), which eventually leads to nitrate production. The high temperature of lightning breaks the strong bonds of nitrogen gas (N₂), allowing it to react with oxygen to form nitrogen oxides. These dissolve in rainwater to form nitrates that are added to the soil. This is an important natural process of nitrogen fixation, contributing a significant amount of fixed nitrogen to ecosystems. Lightning is one of the few natural processes that can fix atmospheric nitrogen.', true, '2026-09-09 03:18:54.996', '2026-09-09 03:18:54.996', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7c0d184e-51dc-49ee-9b7d-922e26b76a0e', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'One significance of St Paul’s teaching on Resurrection is that...', null, '["Christians must not underestimate the power of baptism by immersion","As Christ rose and ascended into glory, so as also must uphold the observance of law","The foundation of their hope of salvation is in Christ’s resurrection","The second coming of Christ is near"]', 2, 'In 1 Corinthians 15:14-19, Paul emphasizes that if Christ is not risen, Christian faith is futile and believers remain in their sins; resurrection is the cornerstone of salvation.', true, '2026-09-09 17:18:27.985', '2026-09-09 17:18:27.985', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7c1ab208-1c4a-4e57-9596-59d81f485cd6', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). The pressman said that his interview with the President was <u>off the record</u>.', null, '["not written on government record books","not intended for publication","not tape","written elsewhere other than in government records"]', 1, '''Off the record'' = not for publication.', true, '2026-10-24 01:04:17.018', '2026-10-24 01:04:17.018', null, null, null, '(Choose the most appropriate interpretation). The pressman said that his interview with the President was <u>off the record</u>.', '["not written on government record books","<u>not intended for publication</u>","not tape","written elsewhere other than in government records"]', '''<b>Off the record</b>'' = <b>not for publication</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7c1c54b8-0c8c-4ff1-94d3-e9fe707a7acb', 'Chemistry', 'JAMB', null, 2026, null, 'The solution that will conduct the highest amount of electricity is', null, '["2.0 moldm3 of hydrochloric acid","0.5 moldm3 ethanoic acid","2.0 moldm3 of ethanoic acid","0.50 moldm3 of hydrochloric acid"]', 0, 'Hydrochloric acid is a strong electrolyte that fully dissociates in solution. Higher concentration (2.0 mol/dm3) provides the maximum density of mobile ions for electrical conduction.', true, '2026-09-09 17:12:45.034', '2026-09-09 17:12:45.034', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7c2edbe8-5372-4b50-9024-32d5b1fe0e29', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Your extreme patience sometimes <u>infuriates</u> me.', null, '["impresses","annoys","frustrates","amuses"]', 1, 'Infuriates = annoys greatly.', true, '2026-10-24 01:03:55.381', '2026-10-24 01:03:55.381', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Your extreme patience sometimes <u>infuriates</u> me.', '["impresses","<u>annoys</u>","frustrates","amuses"]', '<b>Infuriates</b> = <b>annoys</b> greatly.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7c310213-551e-48e9-8702-7df433318e60', 'English Language', 'JAMB', null, 2007, null, 'I hope I have not <u>__________</u> too much on your time', null, '["invaded","encroached","intruded","trespassed"]', 1, 'Correct spelling: encroached.', true, '2026-10-24 07:21:44.668', '2026-10-24 07:21:44.668', null, null, null, 'I hope I have not <u>__________</u> too much on your time', '["invaded","encroached","intruded","trespassed"]', 'Correct spelling: encroached.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7c34352b-9d25-4787-98c5-2a2d415d939d', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Joseph interpreted Pharaoh''s dream as predicting', null, '["famine and war","seven years of abundance and famine","invasion of Egypt","death of Pharaoh"]', 1, 'Joseph interpreted Pharaoh''s dream as seven years of abundance followed by seven years of famine.', true, '2026-09-12 10:40:52.185', '2026-09-12 10:40:52.185', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7c35a9d0-64b3-4c77-a6e5-5f20b477a53c', 'Hausa', 'JAMB', null, 2010, null, '''Ba neman aure ke da wuya ba, shiga-ka-fito''. Ka ga shiga-ka-fito din nan, lallai shiga-ka-fito din ne! Domin aljihu kan jigata kafin a kai ga biki. Tuddan da al''ada ta tanada, wadanda dole sai an haye su, suna da yawa. Yanzu dauki misalin kayan na-gani-ina-so, wato ''yan kayan nan da ake shiryawa a kai gidan su yarinya a karon farko. Ma''anar yin haka, wai iyaye su san cewa manemin auren ''yarsu da gaske yake. To, ina dole ga yin haka? Da can da yake zuwa yana zance da ''yarsu yana yi mata hasafi, ba a san da gaske yake ba? Gangaro kan kayan toshi. Nan ma tsabagen kudi ake kashewa a sayi suturu da kayan shafe-shafe a kai wa yarinya. Kada fa ka ce zuwa zance da manemi yake yana yi wa yarinya kyauta mako-mako, shi ke nan, ya wadatar. Ina, ko kadan! Kada ka mance da kudin gaisuwar iyaye da dukiyar aure kafin a yi baiko da sa ranar biki. Kudi ne madididiki ake tanada a kai wa iyayen yarinya da niyyar dai wannan abu da aka ambata. Duk bayan wannan, ana sa ranar aure, manemin yarinya ya dosa karakaina ke nan daga wannan gida zuwa wancan, ko ma wannan gari zuwa wancan da sunan gayar da iyaye da kakaninnta, wai don su san shi. I, za su san shi mana, tun da ba yana zuwa ne zikau ba! Da zarar biki ya kawo jiki kuma, uwa-uba za a shirya kayan lefe na fitar hankali a kai wa yarinya. Nan ma dukiya ake narkawa. Haķika duk wadannan abubuwa al''ada ce kawai ta kaķaba wa al''umma. Ai ta fuskar dukiya, muhimmin abu ga aure, sadaki. Amma abin takaici, yanzu an yi masa mahalli a can ķarshen sahu! Zikau a labarin na nufin', null, '["da mummunar kama","babu kudi","babu mutunci","a galabaice."]', 1, 'Zikau a labarin na nufin babu kudi.', true, '2026-10-13 10:37:23.61', '2026-10-13 10:37:23.61', null, null, null, '''Ba neman aure ke da wuya ba, shiga-ka-fito''. Ka ga shiga-ka-fito din nan, lallai shiga-ka-fito din ne! Domin aljihu kan jigata kafin a kai ga biki. Tuddan da al''ada ta tanada, wadanda dole sai an haye su, suna da yawa. Yanzu dauki misalin kayan na-gani-ina-so, wato ''yan kayan nan da ake shiryawa a kai gidan su yarinya a karon farko. Ma''anar yin haka, wai iyaye su san cewa manemin auren ''yarsu da gaske yake. To, ina dole ga yin haka? Da can da yake zuwa yana zance da ''yarsu yana yi mata hasafi, ba a san da gaske yake ba? Gangaro kan kayan toshi. Nan ma tsabagen kudi ake kashewa a sayi suturu da kayan shafe-shafe a kai wa yarinya. Kada fa ka ce zuwa zance da manemi yake yana yi wa yarinya kyauta mako-mako, shi ke nan, ya wadatar. Ina, ko kadan! Kada ka mance da kudin gaisuwar iyaye da dukiyar aure kafin a yi baiko da sa ranar biki. Kudi ne madididiki ake tanada a kai wa iyayen yarinya da niyyar dai wannan abu da aka ambata. Duk bayan wannan, ana sa ranar aure, manemin yarinya ya dosa karakaina ke nan daga wannan gida zuwa wancan, ko ma wannan gari zuwa wancan da sunan gayar da iyaye da kakaninnta, wai don su san shi. I, za su san shi mana, tun da ba yana zuwa ne zikau ba! Da zarar biki ya kawo jiki kuma, uwa-uba za a shirya kayan lefe na fitar hankali a kai wa yarinya. Nan ma dukiya ake narkawa. Haķika duk wadannan abubuwa al''ada ce kawai ta kaķaba wa al''umma. Ai ta fuskar dukiya, muhimmin abu ga aure, sadaki. Amma abin takaici, yanzu an yi masa mahalli a can ķarshen sahu! Zikau a labarin na nufin', '["da mummunar kama","babu kudi","babu mutunci","a galabaice."]', 'Zikau a labarin na nufin babu kudi.', '{"bold":["babu kudi"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7c4d2413-3ccf-40b8-b618-7b20400d3dbb', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Do not be <u>discouraged</u> by failure in life.', null, '["dissuaded","sincere","reasonable","actuated"]', 0, 'Discouraged = disheartened; opposite = dissuaded (garbled).', true, '2026-10-24 07:21:28.816', '2026-10-24 07:21:28.816', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Do not be <u>discouraged</u> by failure in life.', '["dissuaded","sincere","reasonable","actuated"]', 'Discouraged = disheartened; opposite = dissuaded (garbled).', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7c4ec387-4550-4733-8237-ce2e4d6391db', 'Physics', 'JAMB', null, 1989, null, 'An ammeter of resistance 0.1 Ω has a full-scale deflection of 50 mA. Determine the resultant full-scale deflection of the meter when a shunt of 0.0111 Ω is connected across its terminals.', null, '["400 mA","450 mA","500 mA","550 mA."]', 2, 'Voltage across the meter = 0.05 x 0.1 = 0.005 V. Shunt current = 0.005/0.0111 = 0.45 A. Total = 0.45 + 0.05 = 0.50 A = 500 mA.', true, '2026-10-12 19:15:30.064', '2026-10-12 19:15:30.064', null, null, null, 'An ammeter of resistance 0.1 Ω has a full-scale deflection of 50 mA. Determine the resultant full-scale deflection of the meter when a shunt of 0.0111 Ω is connected across its terminals.', '["400 mA","450 mA","500 mA","550 mA."]', 'Voltage across the meter = 0.05 x 0.1 = 0.005 V. Shunt current = 0.005/0.0111 = 0.45 A. Total = 0.45 + 0.05 = 0.50 A = 500 mA.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7c5fde98-a753-4e70-944b-e10284b4ca1f', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'What role did Jethro play in Moses'' ministry?', null, '["Levite elder","Priest of Midian and father-in-law","High priest of Israel","Pharaoh''s adviser"]', 1, 'Jethro was the priest of Midian and Moses'' father-in-law. He advised Moses to delegate authority by appointing capable men to judge the people, so Moses would not be overwhelmed by judging all disputes himself.', true, '2026-09-12 09:45:48.591', '2026-09-12 09:45:48.591', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7c70442b-0552-466e-85d2-e6147f076689', 'Financial Accounting', 'UTME', null, 2002, null, 'In an incomplete record, the preparation of bank reconciliation ensures that', null, '["all cash takings are banked","the cash book is correct","there are no overdraft","there are no hidden loan"]', 1, 'Incomplete record is a system of accounting where most records are not recorded. This will affect the cash book and will be corrected when bank reconciliation is prepared.', true, '2026-10-12 21:59:56.941', '2026-10-12 21:59:56.941', null, null, null, 'In an incomplete record, the preparation of bank reconciliation ensures that', '["all cash takings are banked","<b>the cash book is correct</b>","there are no overdraft","there are no hidden loan"]', 'Incomplete record is a system of accounting where most records are not recorded. This will affect the cash book and will be corrected when bank reconciliation is prepared, ensuring <b>the cash book is correct</b>.', '{"bold":["the cash book is correct"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7c7b69c1-3abd-4b83-b83f-543fc09c9482', 'Biology', 'JAMB', null, 2026, null, 'When the sepals and petals are similar they are collectively known as', null, '["Petaloid","Tepals","Sepaloid","Spathes","Perianth"]', 1, 'When sepals and petals are similar in appearance and cannot be easily distinguished, they are collectively called tepals. This condition occurs in flowers like lilies and tulips where the perianth segments are uniform and petal-like. The perianth (V) is the collective term for all the flower''s non-reproductive parts (calyx + corolla), but when the parts are distinct, they are called sepals and petals. Petaloid means resembling petals, sepaloid means resembling sepals, and spathes are large bracts. Tepals are the specialized term for undifferentiated sepals and petals.', true, '2026-09-09 03:18:37.245', '2026-09-09 03:18:37.245', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7c8da273-c4fd-43ca-9907-dfc4a0f4fff2', 'Economics', 'JAMB', null, 2026, null, 'One of these is not the reason for international trade between countries', null, '["Differences in resources endowment","Differences in climate and vegetation","Differences in language","Differences in skill and technical knowledge"]', 2, 'Differences in language are not a reason for international trade.', true, '2026-09-12 11:00:34.278', '2026-09-12 11:00:34.278', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7c914c84-50f5-45a2-9dd1-6eef8a9b9af9', 'Literature in English', 'JAMB', null, 2026, null, '______ entails the working class struggles and lifestyle', null, '["sink in the kitchen drama","comedy of manner","Kitchen-sink drama","Satirical drama"]', 2, 'Kitchen-sink drama entails working class struggles and lifestyle.', true, '2026-09-12 11:10:05.991', '2026-09-12 11:10:05.991', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7c985f1c-dc76-49b3-abae-8e37e6f57ffa', 'Physics', 'JAMB', null, 2026, null, 'An image formed on a screen is always', null, '["inverted","magnified","upright","virtual"]', 0, 'An image formed on a screen is always inverted (upside down) and real. Real images can be projected onto a screen because light rays actually converge at the image point. Virtual images cannot be formed on a screen.', true, '2026-09-10 10:56:39.513', '2026-09-10 10:56:39.513', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7c9f7eaa-9c50-46ea-946b-c98547174331', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The Lions of Cameroun is really an <u>indomitable</u> team.', null, '["a powerful","a prominent","a weak","a cowardly"]', 2, 'Indomitable = unconquerable; opposite = weak.', true, '2026-10-24 07:21:18.515', '2026-10-24 07:21:18.515', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The Lions of Cameroun is really an <u>indomitable</u> team.', '["a powerful","a prominent","a weak","a cowardly"]', 'Indomitable = unconquerable; opposite = weak.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7cae048b-094a-44f1-893e-56af9510a29a', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The <u>ingenious</u> scheme of the robber broke down because of the efficiency of the police officer. Ingenious here means __________________', null, '["suspicious","ambitious","deceitful","clever","stupid"]', 3, 'Ingenious = cleverly devised.', true, '2026-10-24 01:03:53.057', '2026-10-24 01:03:53.057', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The <u>ingenious</u> scheme of the robber broke down because of the efficiency of the police officer. Ingenious here means __________________', '["suspicious","ambitious","deceitful","<u>clever</u>","stupid"]', '<b>Ingenious</b> = <b>cleverly devised</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7caf4986-4ba7-4cbe-a351-113893a6ebdd', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Unless we see the evils clearly, <u>contending against</u> them is like fighting the air.', null, '["avoiding","struggling with","combating","repelling"]', 0, 'Contending against = fighting; opposite = avoiding.', true, '2026-10-24 07:21:11.926', '2026-10-24 07:21:11.926', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Unless we see the evils clearly, <u>contending against</u> them is like fighting the air.', '["avoiding","struggling with","combating","repelling"]', 'Contending against = fighting; opposite = avoiding.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7cb252ae-cc61-4c44-8f41-d701b1b4b408', 'Government', 'JAMB', null, 2026, null, 'The party system operated by a country is determined by the', null, '["Leaders of political parties","Head of government in power","Electoral law","Elites of the country"]', 2, 'The electoral law determines the party system.', true, '2026-09-12 11:24:22.755', '2026-09-12 11:24:22.755', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7ccc63c3-6721-4e88-8022-a9530f75def2', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The town was all <u>agog</u> at his unexpected return.', null, '["unexcited","excited","on fire","surprised"]', 0, 'Agog = excited; opposite = unexcited.', true, '2026-10-24 07:21:22.356', '2026-10-24 07:21:22.356', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The town was all <u>agog</u> at his unexpected return.', '["unexcited","excited","on fire","surprised"]', 'Agog = excited; opposite = unexcited.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7cdc43f1-8677-487a-b73e-2c9691cc70b8', 'Biology', 'JAMB', null, 2004, null, 'A state in Nigeria that is most susceptible to desert encroachment is', null, '["Kwara","Taraba","Kaduna","Kastina"]', 3, 'Katsina is most susceptible to desert encroachment.', true, '2026-10-12 20:59:35.578', '2026-10-12 20:59:35.578', null, null, null, 'A state in Nigeria that is most susceptible to desert encroachment is', '["Kwara","Taraba","Kaduna","Kastina"]', 'Katsina is most susceptible to desert encroachment.', '{"bold":["Katsina"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7cde5062-f3e4-4092-aa0f-fb923c6ffa96', 'Literature in English', 'JAMB', null, 2026, null, 'The conflict between modernity and tradition in the novel is best illustrated through', null, '["Finaba''s academic struggle","generational and cultural tensions","economic competition in the village","religious conversion alone"]', 1, 'The conflict is illustrated through generational and cultural tensions.', true, '2026-09-12 11:11:58.13', '2026-09-12 11:11:58.13', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7ce66cfb-ec5e-4709-959a-3b5536cf827e', 'Biology', 'JAMB', null, 2026, null, 'Which of the following statements is true of inhalation of air by man?', null, '["The ribs are not raised","Diaphragm is raised","Intercostal muscles relax","Pressure of the thoracic cavity increases","Size of the thoracic cavity increases"]', 4, 'During inhalation (inspiration), the size of the thoracic cavity increases. This occurs through the contraction of the intercostal muscles (which raises the ribs and sternum) and the contraction of the diaphragm (which moves downward and flattens). As the thoracic cavity volume increases, the pressure inside decreases below atmospheric pressure, causing air to rush into the lungs. The diaphragm is lowered, not raised, during inhalation. The intercostal muscles contract rather than relax. The pressure decreases, not increases.', true, '2026-09-09 03:18:24.787', '2026-09-09 03:18:24.787', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7cefa3df-a4ee-428b-a1a2-976c33f85585', 'Physics', 'JAMB', null, 1991, null, 'A moving coil galvanometer of 300 Ω resistance gives full scale deflection for 1.0 mA. The resistance, R, of the shunt that is required to convert the galvanometer into a 3.0 A ammeter is', null, '["899.70 Ω","10.00 Ω","0.10 Ω","0.01 Ω"]', 2, 'The shunt carries 3.0 - 0.001 = 2.999 A at the same voltage as the galvanometer: R = (0.001 x 300)/2.999 ≈ 0.10 Ω.', true, '2026-10-12 19:15:34.106', '2026-10-12 19:15:34.106', null, null, null, 'A moving coil galvanometer of 300 Ω resistance gives full scale deflection for 1.0 mA. The resistance, R, of the shunt that is required to convert the galvanometer into a 3.0 A ammeter is', '["899.70 Ω","10.00 Ω","0.10 Ω","0.01 Ω"]', 'The shunt carries 3.0 - 0.001 = 2.999 A at the same voltage as the galvanometer: R = (0.001 x 300)/2.999 ≈ 0.10 Ω.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7cf5bdd8-5dfc-4308-a7f7-598bf076c73d', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'The friend of Amnon that advised him to rape his sister Tamar was', null, '["Jonah","Shimeah","Jonadab","Joseah"]', 2, 'Jonadab advised Amnon to rape Tamar.', true, '2026-09-12 10:41:41.661', '2026-09-12 10:41:41.661', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7cf63b3f-67c8-4ceb-8058-92f8763b5bdd', 'Christian Religious Studies', 'JAMB', null, 2026, null, '''Are you the only visitor to Jerusalem who does not know the things that have happened there in these days?'' The things being referred to in this statement are the', null, '["triumphal entry and cleansing of the Temple","arrest, trials and judgement of Jesus","crucifixion, death and resurrection of Jesus","birth and presentation of Jesus"]', 2, 'Jesus asked this on the road to Emmaus about His crucifixion and resurrection.', true, '2026-09-12 10:41:53.782', '2026-09-12 10:41:53.782', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7cfba418-8206-4854-948d-6e8c195763c8', 'Government', 'JAMB', null, 2026, null, 'General Murtala created ______ states', null, '["12","11","7","6"]', 0, 'General Murtala Muhammed created 12 states in 1976.', true, '2026-09-12 11:24:02.874', '2026-09-12 11:24:02.874', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7cfcc17d-872d-4649-b133-4e6b8f0c47fe', 'English Language', 'JAMB', null, 2007, null, 'The operations of the bank <u>------------</u> not <u>------------</u> cottage and small-scale industries.', null, '["does/covered","does/cover","did/covered","do/cover"]', 3, 'Plural ''operations'' â†’ do/cover.', true, '2026-10-24 01:04:28.58', '2026-10-24 01:04:28.58', null, null, null, 'The operations of the bank <u>------------</u> not <u>------------</u> cottage and small-scale industries.', '["does/covered","does/cover","did/covered","<u>do/cover</u>"]', 'Plural ''<b>operations</b>'' â†’ <b>do/cover</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7d0bba67-ab07-4d64-9ac2-7932c425d0e2', 'Literature in English', 'JAMB', null, 2026, null, 'The phrase ''horrors of red corals'' is an example of', null, '["an oxymoron","simile","visual imagery","euphemism"]', 2, '''Horrors of red corals'' is visual imagery.', true, '2026-09-12 11:13:47.985', '2026-09-12 11:13:47.985', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7d1bf4cd-92bd-4ef2-b8cc-9c6d36f89fbe', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). ''<u>I can''t wait to</u> become a mother,'' the new bride declared.', null, '["She sees motherhood as a burden","She is excited about motherhood","She is not keen on becoming a mother","She will be patient as a mother"]', 1, '''Can''t wait'' = excited about.', true, '2026-10-24 01:02:09.715', '2026-10-24 01:02:09.715', null, null, null, '(Choose the most appropriate interpretation). ''<u>I can''t wait to</u> become a mother,'' the new bride declared.', '["She sees motherhood as a burden","<u>She is excited about motherhood</u>","She is not keen on becoming a mother","She will be patient as a mother"]', '''<b>Can''t wait</b>'' = <b>excited about</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7d265d2c-d38e-4d8d-aaa8-4d506aaffdb3', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'The response of Eli after Samuel had told him the Lord''s message as regards his sons'' acts of blasphemy was that', null, '["He was the LORD, and should do what pleased Him","he would call them and rebuke them","sacrifice would be offered on their behalf","God should have mercy on them"]', 0, 'Eli said, ''He is the LORD; let him do what seems good to him.''', true, '2026-09-12 10:41:53.571', '2026-09-12 10:41:53.571', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7d377785-6abe-463d-a5cc-cbe8a8a5efc0', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The Governor told the chief that he was only on a <u>routine tour</u>.', null, '["normal and regular visit","unplanned encounter","surprise and impromptu check","working visit and homage"]', 0, 'Routine tour = normal and regular visit.', true, '2026-10-24 01:04:01.941', '2026-10-24 01:04:01.941', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The Governor told the chief that he was only on a <u>routine tour</u>.', '["<u>normal and regular visit</u>","unplanned encounter","surprise and impromptu check","working visit and homage"]', '<b>Routine tour</b> = <b>normal and regular visit</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7d3b6a1c-7620-4002-ac79-ab59b81707fb', 'English Language', 'JAMB', null, 2007, null, 'One of the ladies who <u>------------</u> in the premises <u>------------</u> been asked to withdraw.', null, '["sells/have","sell/have","sells/has","sell/has"]', 3, '''Who'' â†’ ladies (sell); ''one'' â†’ has.', true, '2026-10-24 01:04:25.84', '2026-10-24 01:04:25.84', null, null, null, 'One of the ladies who <u>------------</u> in the premises <u>------------</u> been asked to withdraw.', '["sells/have","sell/have","sells/has","<u>sell/has</u>"]', '''<b>Who</b>'' â†’ <b>ladies</b> (<b>sell</b>); ''<b>one</b>'' â†’ <b>has</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7d497404-f595-4318-ab56-351d8780bb59', 'Literature in English', 'JAMB', null, 2026, null, 'Who is the above speaker?', null, '["Philo","Demetrius","Cleopatra","Anthony"]', 0, 'The speaker is Philo.', true, '2026-09-12 11:11:27.809', '2026-09-12 11:11:27.809', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7d59e7eb-14db-494f-b884-340622f972d7', 'Literature in English', 'JAMB', null, 2026, null, '"These naked sons of misery". This expression is an example of', null, '["Litotes","Paradox","Assonance","Metaphor"]', 3, 'The expression "These naked sons of misery" is an example of metaphor. It describes people as ''sons of misery'' without using ''like'' or ''as,'' directly equating them with misery. A metaphor is a figure of speech that makes an implicit comparison. Litotes is understatement, paradox is a contradictory statement, and assonance is the repetition of vowel sounds.', true, '2026-09-10 10:47:09.816', '2026-09-10 10:47:09.816', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7d5b9bcc-04ab-4ff6-9549-0d2fa0f21b87', 'Physics', 'JAMB', null, 1998, null, 'A solid of weight 0.600 N is totally immersed in oil and water respectively. If the upthrust in oil is 0.210 N and the relative density of oil is 0.875, find the upthrust in water.', null, '["0.6000 N","0.360 N","0.240 N","0.180 N"]', 2, 'Upthrust is proportional to the density of the liquid: upthrust in water = 0.210/0.875 = 0.240 N.', true, '2026-10-12 19:15:45.302', '2026-10-12 19:15:45.302', null, null, null, 'A solid of weight 0.600 N is totally immersed in oil and water respectively. If the upthrust in oil is 0.210 N and the relative density of oil is 0.875, find the upthrust in water.', '["0.6000 N","0.360 N","0.240 N","0.180 N"]', 'Upthrust is proportional to the density of the liquid: upthrust in water = 0.210/0.875 = 0.240 N.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7d601d37-76c6-472a-ba52-97a266a3806d', 'Financial Accounting', 'UTME', null, 2003, null, 'The profit realized from the trade is', 'https://res.cloudinary.com/kwi1uv0g/image/upload/v1791841510/questions/ioimi0l0cl2xm4mpvwvc.jpg', '["N4 069","N1 817","N1 440","N1 328"]', 1, 'Remittance to head office 16625 - Opening stock 1875 - Goods sent less returns 13282 = 15157 - Closing stock 1975 = 13182 + Expenses 1626 = 14808. Profit = 1817.', true, '2026-10-12 22:00:01.262', '2026-10-12 22:00:01.262', null, null, null, 'The profit realized from the trade is', '["N4 069","<b>N1 817</b>","N1 440","N1 328"]', 'Remittance to head office 16625 - Opening stock 1875 - Goods sent less returns 13282 = 15157 - Closing stock 1975 = 13182 + Expenses 1626 = 14808. Profit = <b>1817</b>.', '{"bold":["1817"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7d8592f5-4760-43a3-bc37-05eb4a2d4f9a', 'Biology', 'JAMB', null, 2026, null, 'Which of the following is the best explanation for a child who is phenotypically short and born of two tall parents?', null, '["The father possesses a gene for shortness","The mother possesses a gene for shortness","Nature makes the child short","Both parents possess genes for shortness"]', 3, 'For a child to be short when both parents are tall, both parents must possess genes for shortness (be heterozygous carriers). Tallness is dominant (T) and shortness is recessive (t). Both parents must be Tt, and the child must inherit t from both parents, resulting in tt (short). This is the only genetic explanation for two tall parents having a short child. The child''s phenotype is determined by the genotype, not by nature.', true, '2026-09-09 03:19:26.086', '2026-09-09 03:19:26.086', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7d9261ac-5c0c-40a0-ae28-200fa4fe4bbd', 'Physics', 'JAMB', null, 1998, null, 'A man whose mass is 80 kg climbs a staircase in 20 s and expends a power of 120 W. Find the height of the staircase. [g = 10 m s⁻²]', null, '["1.8 m","2.0 m","2.5 m","3.0 m"]', 3, 'Work = Pt = 120 x 20 = 2400 J = mgh, so h = 2400/(80 x 10) = 3.0 m.', true, '2026-10-12 19:15:45.031', '2026-10-12 19:15:45.031', null, null, null, 'A man whose mass is 80 kg climbs a staircase in 20 s and expends a power of 120 W. Find the height of the staircase. [g = 10 m s<sup>-2</sup>]', '["1.8 m","2.0 m","2.5 m","3.0 m"]', 'Work = Pt = 120 x 20 = 2400 J = mgh, so h = 2400/(80 x 10) = 3.0 m.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7d98f985-643c-42d2-9c97-4afa734932e5', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'In order that Benjamin might be brought to Egypt, Joseph detained...', null, '["Reuben","Levi","Zebulun","Simeon"]', 3, 'Genesis 42:24 records that Joseph bound Simeon before their eyes and held him in custody while the rest returned to bring Benjamin.', true, '2026-09-09 17:18:27.876', '2026-09-09 17:18:27.876', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7d9cc8f0-5fe6-4f09-9aac-45f022a707ff', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. It was a good try but it didn''t <u>work out</u>.', null, '["come to","come off","come out","come for"]', 1, 'Work out = come off.', true, '2026-10-24 01:01:59.243', '2026-10-24 01:01:59.243', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. It was a good try but it didn''t <u>work out</u>.', '["come to","<u>come off</u>","come out","come for"]', '<b>Work out</b> = <b>come off</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7d9e95fd-fcbe-4d09-b94c-254f6b9171ea', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The students were <u>undeterred</u> by the noisy lecture environment.', null, '["encouraged","discouraged","frustrated","challenged"]', 1, 'Undeterred = not discouraged; opposite = discouraged.', true, '2026-10-24 07:21:28.716', '2026-10-24 07:21:28.716', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The students were <u>undeterred</u> by the noisy lecture environment.', '["encouraged","discouraged","frustrated","challenged"]', 'Undeterred = not discouraged; opposite = discouraged.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7da33bf4-95df-4196-8810-687fcaba2f46', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. My son has just been <u>rusticated</u> from the university.', null, '["sent home to get his fees","sent home for misconduct","sent home to rest for sometime","sent home to become rustic"]', 1, 'Rusticated = sent home for misconduct.', true, '2026-10-24 01:01:43.569', '2026-10-24 01:01:43.569', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. My son has just been <u>rusticated</u> from the university.', '["sent home to get his fees","<u>sent home for misconduct</u>","sent home to rest for sometime","sent home to become rustic"]', '<b>Rusticated</b> = <b>sent home for misconduct</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7dabbc72-5698-4568-8c47-7008749362a7', 'English Language', 'JAMB', null, 2007, null, 'In spite of Shade''s good looks, her hair is always <u>__________</u>', null, '["uncared for","unkept","unkempt","unwashed"]', 2, 'Correct spelling: unkempt.', true, '2026-10-24 07:21:36.119', '2026-10-24 07:21:36.119', null, null, null, 'In spite of Shade''s good looks, her hair is always <u>__________</u>', '["uncared for","unkept","unkempt","unwashed"]', 'Correct spelling: unkempt.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7db1f118-ef67-450d-87a5-2c1c72345f96', 'English Language', 'JAMB', null, 2024, null, 'As you make your bed, so you will ______ on it.', null, '["lie","lay","lying","laid"]', 0, '"Lie" means to recline.', true, '2026-09-18 09:43:02.788', '2026-09-18 09:43:02.788', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7db6999e-7549-4405-acdf-d6cc3090f06c', 'Biology', 'JAMB', null, 2005, null, 'I. Rattus rattus II. Agama agama III. Bufo regularis IV. Tilapia zilli. The order of evolutionary advancement of the above vertebrates is', null, '["I, II, III, IV","I, IV, III, II","II, III, IV, I","IV, III, II, I"]', 3, 'The correct evolutionary order is IV, III, II, I.', true, '2026-10-12 20:59:36.92', '2026-10-12 20:59:36.92', null, null, null, 'I. Rattus rattus II. Agama agama III. Bufo regularis IV. Tilapia zilli. The order of evolutionary advancement of the above vertebrates is', '["I, II, III, IV","I, IV, III, II","II, III, IV, I","IV, III, II, I"]', 'The correct evolutionary order is IV, III, II, I.', '{"bold":["IV, III, II, I"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7dbecdac-04cf-43f8-99d0-ea44a78ba522', 'Government', 'JAMB', null, 2026, null, 'That type of sovereignty that thrives on legitimacy is', null, '["external sovereignty","vested on any form of government","legal sovereignty","within the people''s mandate"]', 3, 'Sovereignty that thrives on legitimacy is within the people''s mandate.', true, '2026-09-12 11:24:49.847', '2026-09-12 11:24:49.847', null, null, null, null, null, null, null);
