insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7dcab474-d97c-483b-8ee0-b5e30e095f13', 'General Mathematics', 'JAMB', null, 2026, null, 'Find correct to 2.d.p: 100 + 1/100 + 3/1000 + 27/10000', null, '["100.02","1000.02","100.02","100.01","100.51"]', 0, '100 + 0.01 + 0.003 + 0.0027 = 100.0157. To 2 decimal places: 100.02.', true, '2026-09-10 10:48:19.39', '2026-09-10 10:48:19.39', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7dd35d96-c48e-4bda-9fcb-b7367a5efd82', 'English Language', 'JAMB', null, 2024, null, 'The thief died shortly after ______ shot at by the police', null, '["Been","Having","Having Being","Being"]', 3, '"After being shot" is the correct passive gerund construction.', true, '2026-09-18 09:24:04.773', '2026-09-18 09:24:04.773', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7dd44b2d-4201-4715-ad16-7e0f34225dd4', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). Kunana is <u>like a bear with a sore head</u>', null, '["He is a bully","He is grumpy","He is ugly","He is quiet"]', 1, '''A bear with a sore head'' = grumpy.', true, '2026-10-24 01:04:24.961', '2026-10-24 01:04:24.961', null, null, null, '(Choose the most appropriate interpretation). Kunana is <u>like a bear with a sore head</u>', '["He is a bully","<u>He is grumpy</u>","He is ugly","He is quiet"]', '''A <b>bear with a sore head</b>'' = <b>grumpy</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7dda6c6d-558d-4e32-a25e-1999560c2493', 'Biology', 'JAMB', null, 2003, null, 'One example of fossil is', null, '["limestone","coral","coal","firewood"]', 2, 'Coal is an example of fossil.', true, '2026-10-12 20:59:33.282', '2026-10-12 20:59:33.282', null, null, null, 'One example of fossil is', '["limestone","coral","coal","firewood"]', 'Coal is an example of fossil.', '{"bold":["Coal"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7ddc55ed-e180-47dd-9026-d38503f7b0c5', 'Literature in English', 'JAMB', null, 2026, null, 'The imagery of ''doors'' closing ''on me'' symbolizes', null, '["the father''s physical isolation","his social exclusion","his emotional disconnection from others","His loss of opportunity"]', 1, 'The imagery symbolizes his social exclusion.', true, '2026-09-12 11:13:43.065', '2026-09-12 11:13:43.065', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7dde46ff-98bc-48b8-a79a-0fa83709f747', 'Physics', 'JAMB', null, 1984, null, 'The lower and upper fixed points marked on a mercury-in-glass thermometer are 210 mm apart. The end of the mercury column in the tube is 49 mm above the lower fixed point in a room. What is the temperature of the room in degrees Celsius?', null, '["55.3 °C","23.3 °C","49.0 °C","16.1 °C","76.7 °C"]', 1, 'θ = (49/210) x 100 = 23.3 °C.', true, '2026-10-12 19:15:19.181', '2026-10-12 19:15:19.181', null, null, null, 'The lower and upper fixed points marked on a mercury-in-glass thermometer are 210 mm apart. The end of the mercury column in the tube is 49 mm above the lower fixed point in a room. What is the temperature of the room in degrees Celsius?', '["55.3 °C","23.3 °C","49.0 °C","16.1 °C","76.7 °C"]', 'θ = (49/210) x 100 = 23.3 °C.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7de97994-9cd3-4431-8dcf-cfa6b7a3d839', 'Chemistry', 'JAMB', null, 2026, null, 'Which of the following substances has the strongest intermolecular attraction?', null, '["CO₂","NH₃","CH₄","H₂"]', 1, 'Ammonia forms hydrogen bonds, which are significantly stronger than the London dispersion forces present in CO2, CH4, and H2.', true, '2026-09-09 17:12:49.317', '2026-09-09 17:12:49.317', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7dec2641-4e0d-45d8-b9f0-f463e2759b4c', 'Economics', 'JAMB', null, 2026, null, 'If workers at the school canteen cannot sell during the holidays, this is example of;', null, '["Cyclical unemployment","Structural unemployment","Seasonal unemployment","Frictional unemployment"]', 2, 'This is seasonal unemployment due to holiday periods.', true, '2026-09-12 11:02:12.178', '2026-09-12 11:02:12.178', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7df2da2d-87d0-4b48-b357-a348e4d2f029', 'Biology', 'JAMB', null, 2026, null, 'Which of the following is an example of a biotic factor that can influence the distribution of organisms in an ecosystem? I. Temperature II. Predation III. Sunlight IV. Humidity', null, '["IV","II","III & IV","II & IV"]', 1, 'Predation (II) is a biotic factor because it involves interactions between living organisms (predator-prey relationships). Temperature (I), sunlight (III), and humidity (IV) are abiotic (non-living) factors. Biotic factors include all living components of an ecosystem that affect organisms: predators, parasites, pathogens, competitors, and food availability. These interactions are crucial in determining species distribution, population sizes, and community structure. Predation, in particular, can significantly influence where prey species can survive and reproduce.', true, '2026-09-09 03:18:36.559', '2026-09-09 03:18:36.559', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7df89517-b5f4-466c-b9e9-5d354602544d', 'Economics', 'JAMB', null, 2026, null, 'Using the income method of computing the National Income of a country, which of the following are excluded?', null, '["Value added","Net wages","Transfer payments","Interest and dividends earned","Final values of goods"]', 2, 'Using the income method, transfer payments are excluded from National Income computation. Transfer payments are payments made without any corresponding production of goods or services, such as pensions, unemployment benefits, and gifts. Including them would result in double counting because the money is eventually spent on goods and services that are already counted.', true, '2026-09-10 10:41:21.206', '2026-09-10 10:41:21.206', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7dfa662d-bd50-4d62-be6f-c482cf1e1df0', 'Literature in English', 'JAMB', null, 2026, null, 'The dominant theme of the poem ''Hearty Garlands'' is', null, '["birthday celebration","generational conflict","loneliness in old age","political struggle"]', 0, 'The dominant theme is birthday celebration.', true, '2026-09-12 11:10:56.915', '2026-09-12 11:10:56.915', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7dfff3b9-a5f9-48ed-8ebd-07587dcf82a3', 'Economics', 'JAMB', null, 2026, null, '______ refers to the production of crops and rearing of animals for man''s use', null, '["Aquaculture","Agriculture","Fishing","Animal husbandry"]', 1, 'Agriculture is the production of crops and rearing of animals for man''s use.', true, '2026-09-12 11:00:24.309', '2026-09-12 11:00:24.309', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7e074ccb-d30b-416e-9b3c-b49bfc3cda22', 'Literature in English', 'JAMB', null, 2026, null, 'The presentation of Ananse being whipped by rain symbolizes', null, '["struggles and hardship of life","the raining season","a hasty man without an umbrella","a drenched struggling father"]', 0, 'It symbolizes the struggles and hardship of life.', true, '2026-09-12 11:05:28.869', '2026-09-12 11:05:28.869', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7e0a660e-d3c1-47bd-aacb-e0037a10d242', 'English Language', 'JAMB', null, 2024, null, 'A suitable title for this passage is', null, '["The transition programme","The history of Nigeria","The military politics in Nigeria","The political crisis in Nigeria"]', 3, 'The passage discusses various political crises in Nigeria, so "The political crisis in Nigeria" is the most suitable title.', true, '2026-09-18 09:24:04.914', '2026-09-18 09:24:04.914', null, null, 'COMPREHENSION', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7e10b7fe-18d3-48b1-ba81-e773f9ac2867', 'Economics', 'JAMB', null, 2026, null, 'The sum of production within a domestic territory and by members of the territory living in diaspora is called?', null, '["Net Product","Gross Domestic Product","Disposable Income","Gross National Product"]', 3, 'Gross National Product (GNP) = GDP + Net income from abroad.', true, '2026-09-12 10:58:44.29', '2026-09-12 10:58:44.29', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7e16def8-a7ef-4121-b4ec-79cd53acd83e', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The <u>mottled</u> skin of a person with HIV indicates an advanced stage of its development.', null, '["pimply","scaly","brown","spotted"]', 3, 'Mottled = spotted.', true, '2026-10-24 01:01:53.162', '2026-10-24 01:01:53.162', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The <u>mottled</u> skin of a person with HIV indicates an advanced stage of its development.', '["pimply","scaly","brown","<u>spotted</u>"]', '<b>Mottled</b> = <b>spotted</b>.', '{}');
