insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7e2f3835-3189-4fc5-8244-b87a6be0eed3', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). After my husband''s death, I find it hard to <u>keep open house</u>.', null, '["entertain every visitor","keep all doors open","relax security","give a party"]', 0, '''Keep open house'' = entertain every visitor.', true, '2026-10-24 01:02:06.801', '2026-10-24 01:02:06.801', null, null, null, '(Choose the most appropriate interpretation). After my husband''s death, I find it hard to <u>keep open house</u>.', '["<u>entertain every visitor</u>","keep all doors open","relax security","give a party"]', '''<b>Keep open house</b>'' = <b>entertain every visitor</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7e5669da-a32d-4ea7-ba4a-c140c1469ca6', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The soldiers tried in their <u>dogged</u> defence of the city.', null, '["indifferent","strong","miserable","classical"]', 0, 'Dogged = determined; opposite = indifferent.', true, '2026-10-24 07:21:30.373', '2026-10-24 07:21:30.373', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The soldiers tried in their <u>dogged</u> defence of the city.', '["indifferent","strong","miserable","classical"]', 'Dogged = determined; opposite = indifferent.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7e56b587-5101-4fc6-8fc8-cce5c1a77285', 'General Mathematics', 'JAMB', null, 2026, null, 'What is the value of P if the gradient of the line joining (-1,p) and (p,4) is 2/3?', null, '["-2","-1","1","2"]', 3, 'Gradient = (4-p)/(p-(-1)) = (4-p)/(p+1) = 2/3. 3(4-p) = 2(p+1). 12-3p = 2p+2. 10 = 5p. p = 2.', true, '2026-09-10 10:48:20.129', '2026-09-10 10:48:20.129', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7e5b1e61-4dca-4b1c-83a6-8e3ea3d70a85', 'Physics', 'JAMB', null, 2026, null, 'A narrow beam of white light can be split up into different colours by a glass prism. The correct explanation is that', null, '["white light is an electromagnetic wave","the prism has all the colours of the white light","white light has undergone total internal reflection in the prism","different colours of white light travel with different speeds in glass","white light consist of yellow, green and red colours"]', 3, 'White light is split into different colours by a prism because different colours travel with different speeds in glass. This phenomenon is called dispersion. Violet light travels slowest and is refracted most, while red light travels fastest and is refracted least.', true, '2026-09-10 10:56:39.459', '2026-09-10 10:56:39.459', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7e5ce53c-61a6-4742-822b-901bc2a0e335', 'Biology', 'JAMB', null, 2010, null, 'The part of the human gut that has an acidic content is the', null, '["stomach","duodenum","ileum","colon"]', 0, 'The stomach has acidic content.', true, '2026-10-12 20:59:40.38', '2026-10-12 20:59:40.38', null, null, null, 'The part of the human gut that has an acidic content is the', '["stomach","duodenum","ileum","colon"]', 'The stomach has acidic content.', '{"bold":["stomach"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7e5e36a7-04d6-4396-a801-29e1aef764d1', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). When you go to a foreign country to study, you will discover that life there is <u>not a bed of roses</u>.', null, '["as pleasant as one thought","a bed with roses","an unmitigated disappointment","as expected"]', 0, '''Not a bed of roses'' = not as pleasant as one thought.', true, '2026-10-24 01:02:04.265', '2026-10-24 01:02:04.265', null, null, null, '(Choose the most appropriate interpretation). When you go to a foreign country to study, you will discover that life there is <u>not a bed of roses</u>.', '["<u>as pleasant as one thought</u>","a bed with roses","an unmitigated disappointment","as expected"]', '''<b>Not a bed of roses</b>'' = <b>not as pleasant as one thought</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7e5f5fd4-23a9-474e-9194-dfff5250844e', 'Physics', 'JAMB', null, 1991, null, 'The absolute temperature of a perfect gas is proportional to the average', null, '["Potential energy of the molecules","Separation between the molecules","Kinetic energy of the molecules","Velocity of the molecules."]', 2, 'From kinetic theory the absolute temperature is directly proportional to the average kinetic energy of the molecules.', true, '2026-10-12 19:15:33.299', '2026-10-12 19:15:33.299', null, null, null, 'The absolute temperature of a perfect gas is proportional to the average', '["Potential energy of the molecules","Separation between the molecules","Kinetic energy of the molecules","Velocity of the molecules."]', 'From kinetic theory the absolute temperature is directly proportional to the average kinetic energy of the molecules.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7e5f6dc2-8196-4656-bd67-4dbe1d1fe249', 'Biology', 'JAMB', null, 2013, null, 'The process of transforming the chemical energy of cellular fuels into the high energy bonds of ATP in plants is', null, '["Photolysis","Respiration","Autotrophism","Photosynthesis"]', 1, 'Respiration transforms chemical energy into ATP.', true, '2026-10-12 20:59:46.978', '2026-10-12 20:59:46.978', null, null, null, 'The process of transforming the chemical energy of cellular fuels into the high energy bonds of ATP in plants is', '["Photolysis","Respiration","Autotrophism","Photosynthesis"]', 'Respiration transforms chemical energy into ATP.', '{"bold":["Respiration"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7e6325de-06f9-41ff-9156-ad8604a21a22', 'English Language', 'JAMB', null, 2007, null, 'Don''t <u>__________</u> said the leader I want a decision now', null, '["prevaricate","predicate","precipitate","be pejorative"]', 0, 'Correct spelling: prevaricate.', true, '2026-10-24 07:21:44.518', '2026-10-24 07:21:44.518', null, null, null, 'Don''t <u>__________</u> said the leader I want a decision now', '["prevaricate","predicate","precipitate","be pejorative"]', 'Correct spelling: prevaricate.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7e6f39e8-c36a-4f31-9a19-74d285794ae7', 'Economics', 'JAMB', null, 2026, null, 'The population theory that is concerned with the cases of over population and shortage of food production is', null, '["population density","Malthusian population theory","national population theory","demographical transition theory"]', 1, 'Malthusian theory deals with overpopulation and food shortage.', true, '2026-09-12 11:01:00.17', '2026-09-12 11:01:00.17', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7e6f8f17-b9d8-4ae0-bfd1-d1bf51fc0ac6', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. We were <u>shocked</u> by the news that he had lost the money.', null, '["astonished","unconcerned","disconcerted","surprised"]', 1, 'Shocked = surprised; opposite = unconcerned.', true, '2026-10-24 07:21:26.843', '2026-10-24 07:21:26.843', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. We were <u>shocked</u> by the news that he had lost the money.', '["astonished","unconcerned","disconcerted","surprised"]', 'Shocked = surprised; opposite = unconcerned.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7e8fa8ee-b606-4b6a-907e-2ace71df8ecf', 'General Mathematics', 'JAMB', null, 2026, null, 'If x*y = x+y², find the value of (2*3)*5', null, '["25","11","55","36"]', 3, 'First, 2*3 = 2+3² = 2+9 = 11. Then 11*5 = 11+5² = 11+25 = 36.', true, '2026-09-10 10:48:20.031', '2026-09-10 10:48:20.031', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7ea84857-52e7-4820-bcda-2ca8de04f84f', 'Biology', 'JAMB', null, 2026, null, 'During seed germination, the first visible structure to emerge from the soil and reaches the surface is', null, '["Cotyledon","Hypocotyl","Plumule","Radicle","Endosperm"]', 1, 'The hypocotyl is the first visible structure to emerge from the soil. In epigeal germination, the hypocotyl elongates and pushes the cotyledons above ground. The radicle emerges first from the seed but emerges from the seed into the soil, not above the surface. The plumule emerges later. Cotyledons may or may not emerge depending on germination type. Endosperm is the stored food source and is not a structure that emerges. The hypocotyl is the stem region below the cotyledons and above the radicle.', true, '2026-09-09 03:18:35.459', '2026-09-09 03:18:35.459', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7eb0f92e-7bd4-4bae-8618-b162a0893f46', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'What was Zechariah''s punishment for doubting Gabriel''s message?', null, '["leprosy","deafness","blindness","muteness"]', 3, 'Zechariah was struck mute until John the Baptist was born.', true, '2026-09-12 10:40:56.7', '2026-09-12 10:40:56.7', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7ec2eec4-c30f-42f5-bde7-c66b7d271ad0', 'General Mathematics', 'JAMB', null, 2026, null, 'A person has 2 parents, 4 grandparents, 8 great grandparents, and so on. Find the number of his ancestors during the ten generations preceding his own.', null, '["1024","2046","1023","2048"]', 1, 'Sum = 2+4+8+...+2¹⁰ = 2(2¹⁰-1) = 2(1023) = 2046.', true, '2026-09-12 11:43:53.454', '2026-09-12 11:43:53.454', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7ec56fc1-65d6-4bbb-9eaf-4888c9dbfe1f', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. She was asked to <u>swallow her pride</u> and get busy.', null, '["be more realistic","at up her pride","be more insistent","be less proud"]', 2, 'Swallow one''s pride = be humble; opposite = be more insistent.', true, '2026-10-24 07:21:16.484', '2026-10-24 07:21:16.484', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. She was asked to <u>swallow her pride</u> and get busy.', '["be more realistic","at up her pride","be more insistent","be less proud"]', 'Swallow one''s pride = be humble; opposite = be more insistent.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7ed4918f-ca87-49ce-946b-5f8cdd312aa0', 'Literature in English', 'JAMB', null, 2026, null, 'The poet personifies the sea as a', null, '["benevolent goddess","long-suffering maternal figure","malevolent entity","silent, unfeeling observer"]', 1, 'The sea is personified as a long-suffering maternal figure.', true, '2026-09-12 11:07:23.47', '2026-09-12 11:07:23.47', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7ee2cc5d-2abe-434a-afb4-0e5375752779', 'Physics', 'JAMB', null, 1989, null, 'A bar magnet is most effectively demagnetized by', null, '["Placing it in a N-S position and hitting it with a hammer.","Subjecting it to an electric current from a battery","Bringing its north pole in contact with the north pole of a very strong magnet","Heating the magnet."]', 3, 'Heating a magnet strongly agitates its molecules and destroys the alignment of the magnetic domains. Hammering in the N-S position tends to strengthen magnetism instead.', true, '2026-10-12 19:15:29.796', '2026-10-12 19:15:29.796', null, null, null, 'A bar magnet is most effectively demagnetized by', '["Placing it in a N-S position and hitting it with a hammer.","Subjecting it to an electric current from a battery","Bringing its north pole in contact with the north pole of a very strong magnet","Heating the magnet."]', 'Heating a magnet strongly agitates its molecules and destroys the alignment of the magnetic domains. Hammering in the N-S position tends to strengthen magnetism instead.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7efcd0f7-e3c9-4f5f-a027-2e72b5e5a253', 'Physics', 'JAMB', null, 2026, null, 'Identify what part of a charged pencil would carry the most charge', null, '["The top","the mid side","The middle","The base"]', 0, 'The part of a charged pencil that would carry the most charge is the top (the end with the most pointed tip or the end that is rubbed). Charge concentrates at pointed ends due to higher charge density at sharp points.', true, '2026-09-10 10:56:44.983', '2026-09-10 10:56:44.983', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7f06e22a-3c1c-43ea-882e-ef6e5f72f402', 'Chemistry', 'JAMB', null, 2026, null, 'Which of the following substances will show the greatest degree of hydrogen bonding?', null, '["H₂S","CH₃OH","HCl","NH₄Cl"]', 1, 'Methanol (CH3OH) contains a highly polar hydroxyl (-OH) group capable of forming extensive intermolecular hydrogen bonds.', true, '2026-09-09 17:12:48.411', '2026-09-09 17:12:48.411', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7f0d65ee-fec6-4634-9a71-6a4c076f430f', 'General Mathematics', 'JAMB', null, 2026, null, 'The number of people living in a town is 47,000 to the nearest 1,000. Which one of these is a possible number of people living in the town?', null, '["47,500","46,000","48,000","46,500"]', 0, '47,000 to nearest 1000 means range [46,500, 47,500). So 47,500 is possible.', true, '2026-09-12 11:43:56.816', '2026-09-12 11:43:56.816', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7f175a80-a1ff-40ce-8485-f391177ab1de', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Herod Agrippa killed James in order to...', null, '["Offer breathing space to Judaism","Punish Christians from outside Jerusalem","Win confidence of the Jews","Seek revenge for the Herods"]', 2, 'Acts 12:1-3 states that Herod Agrippa I executed James the brother of John with a sword, and when he saw that it pleased the Jews, he proceeded to arrest Peter as well.', true, '2026-09-09 17:18:24.163', '2026-09-09 17:18:24.163', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7f30bc3f-febd-46df-b7b0-bf359f17116e', 'Physics', 'JAMB', null, 1993, null, 'Which of the following may be used to explain a mirage?
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7f4759b2-6015-4764-936e-e9eb72d87aa5', 'Biology', 'JAMB', null, 2026, null, 'A colour-blind man marries a carrier woman. What is the probability of their offspring being colour blind?', null, '["25%","50%","75%","100%"]', 1, 'The probability of their offspring being colour blind is 50%. The cross is X^n Y (colour-blind father) × X^N X^n (carrier mother). The possible offspring are: X^N X^n (carrier daughters, 25%), X^n X^n (colour-blind daughters, 25%), X^N Y (normal sons, 25%), X^n Y (colour-blind sons, 25%). Overall, 50% of all children (all sons and half the daughters) are affected or carriers. The sons have 50% chance of being affected, daughters 50% chance of being carriers.', true, '2026-09-09 03:19:23.006', '2026-09-09 03:19:23.006', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7f5bf647-f179-43c7-81d8-bf501c6c7ea3', 'Biology', 'JAMB', null, 2026, null, 'Which of the following is lacking in the diet of a person with kwashiorkor?', null, '["Proteins","Carbohydrates","Minerals","Vitamins"]', 0, 'Kwashiorkor is caused by a lack of protein in the diet, even when carbohydrate intake is adequate. It is characterized by edema (swelling from fluid retention), a distended belly, thin limbs, hair changes, and skin lesions. It typically occurs in children who have been weaned and fed a carbohydrate-rich but protein-deficient diet. Unlike marasmus (caused by overall calorie malnutrition), kwashiorkor patients may have adequate carbohydrate intake but insufficient protein for growth and tissue maintenance.', true, '2026-09-09 03:19:04.456', '2026-09-09 03:19:04.456', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7f5eaae3-d32a-4cfe-9c01-e23b5d80ecff', 'English Language', 'JAMB', null, 2007, null, 'Yesterday, the exhausted travellers .... On the sofa for nearly three hours.', null, '["Lay","Laid","Lied","Lain"]', 0, '''Lay'' is past tense of intransitive ''lie'' (to recline).', true, '2026-10-25 18:25:07.008', '2026-10-25 18:25:07.008', null, null, null, 'Yesterday, the exhausted travellers .... On the sofa for nearly three hours.', '["Lay","Laid","Lied","Lain"]', '''Lay'' is past tense of intransitive ''lie'' (to recline).', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7f61d6c0-7ffa-47f0-9fa4-84acb7389dd3', 'Physics', 'JAMB', null, 1997, null, 'The power dissipated in an a.c. circuit with an r.m.s. current of 5 A, r.m.s. voltage of 10 V and a phase angle of 60° is', null, '["25 W","50 W","120 W","125 W"]', 0, 'P = Vrms Irms cos φ = 10 x 5 x cos 60° = 25 W.', true, '2026-10-12 19:15:44.387', '2026-10-12 19:15:44.387', null, null, null, 'The power dissipated in an a.c. circuit with an r.m.s. current of 5 A, r.m.s. voltage of 10 V and a phase angle of 60° is', '["25 W","50 W","120 W","125 W"]', 'P = V<sub>rms</sub> I<sub>rms</sub> cos φ = 10 x 5 x cos 60° = 25 W.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7f68852e-45d5-4e2e-9d1c-88dd94c1c4ed', 'Literature in English', 'JAMB', null, 2026, null, 'The dominant image is one of', null, '["Begging","Flying","Running","Waiting"]', 2, 'The dominant image is of running.', true, '2026-09-12 11:11:16.037', '2026-09-12 11:11:16.037', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7f689477-d8fe-46a1-b2a8-ec1aea851e3a', 'Chemistry', 'JAMB', null, 2026, null, 'Which change will increase the pH of an aqueous solution of ammonium chloride?', null, '["Addition of sodium hydroxide solution","Addition of hydrochloric acid","Addition of more ammonium chloride","Dilution with distilled water"]', 0, 'Ammonium chloride is an acidic salt solution. Adding a strong base like NaOH neutralizes excess H+ ions, raising the solution pH.', true, '2026-09-09 17:12:47.953', '2026-09-09 17:12:47.953', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7f68f4a2-8be3-4306-8e88-5e3511c51670', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The Senate postponed the meeting <u>indefinitely</u>.', null, '["for a short time","for six months","definitely","without fixing a date","for several months"]', 3, 'Indefinitely = without fixed date.', true, '2026-10-24 01:01:41.155', '2026-10-24 01:01:41.155', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The Senate postponed the meeting <u>indefinitely</u>.', '["for a short time","for six months","definitely","<u>without fixing a date</u>","for several months"]', '<b>Indefinitely</b> = <b>without fixed date</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7f6c29f2-4bc0-40eb-9cb1-966b0820f8dd', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Some workers <u>went on rampage</u> at a trade-fair.', null, '["turned violent","robber","were angry","demonstrated"]', 0, 'Went on rampage = turned violent.', true, '2026-10-24 01:01:42.818', '2026-10-24 01:01:42.818', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Some workers <u>went on rampage</u> at a trade-fair.', '["<u>turned violent</u>","robber","were angry","demonstrated"]', '<b>Went on rampage</b> = <b>turned violent</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7f6d6344-cd34-4f8a-805b-5cf43ec5c5ee', 'Literature in English', 'JAMB', null, 2026, null, 'The dominant theme of the poem Hearty Garlands is', null, '["political oppression","appreciation and admiration","war and destruction","betrayal among friends"]', 1, 'The dominant theme is appreciation and admiration.', true, '2026-09-12 11:12:09.83', '2026-09-12 11:12:09.83', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7f72354e-6acf-4144-b077-013b5e862f6f', 'Biology', 'JAMB', null, 2004, null, 'The anaerobic fermentation of a glucose molecule yields', null, '["38 ATP molecules","2 ATP molecules and alcohol","pyruvic acid and alcohol","Water and carbon(IV)oxide"]', 1, 'Anaerobic fermentation yields 2 ATP molecules and alcohol.', true, '2026-10-12 20:59:34.964', '2026-10-12 20:59:34.964', null, null, null, 'The anaerobic fermentation of a glucose molecule yields', '["38 ATP molecules","2 ATP molecules and alcohol","pyruvic acid and alcohol","Water and carbon(IV)oxide"]', 'Anaerobic fermentation yields 2 ATP molecules and alcohol.', '{"bold":["2 ATP molecules and alcohol"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7f7fe7f5-dd27-4e8c-95be-7c2fe6baf249', 'Government', 'JAMB', null, 2026, null, 'The head of the judiciary arm of Government is known as', null, '["Chief Justice","Attorney General","A judge","An advocate"]', 0, 'The head of the judiciary arm of government is known as the Chief Justice. In Nigeria, the Chief Justice of Nigeria (CJN) is the head of the judiciary and presides over the Supreme Court. The Attorney General is the chief law officer of the executive, not the judiciary. A judge is a member of the judiciary, and an advocate is a lawyer. The Chief Justice is the highest judicial officer in the land.', true, '2026-09-10 10:45:07.158', '2026-09-10 10:45:07.158', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7f8f5168-5f03-4b54-bbf8-3ba4a726fc58', 'Literature in English', 'JAMB', null, 2026, null, 'The poem criticizes the younger generation mainly for', null, '["embracing fashion trends","building modern houses","abandoning tradition and heritage","refusing to travel abroad"]', 2, 'The poem criticizes abandoning tradition and heritage.', true, '2026-09-12 11:13:44.742', '2026-09-12 11:13:44.742', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7f92ec6d-7c91-4efd-bb1e-e4659abd4f33', 'Chemistry', 'JAMB', null, 2026, null, 'Which factor will shift the position of equilibrium to the right in the reaction: N₂(g) + 3H₂(g) ⇌ 2NH₃(g) + heat', null, '["Increase in temperature","Decrease in pressure","Addition of catalyst","Increase in pressure"]', 3, 'Increasing total pressure shifts equilibrium toward the side with fewer gas moles (4 moles on left vs 2 moles on right), producing more NH3.', true, '2026-09-09 17:12:48.563', '2026-09-09 17:12:48.563', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7f9aec9c-4f94-4965-887a-3981f157f0a0', 'Physics', 'JAMB', null, 1991, null, 'An equipment whose power is 1500 W and resistance is 375 ohms would draw a current of', null, '["0.10 A","2.00 A","4.00 A","77.5 A."]', 1, 'P = I²R, so I = √(1500/375) = √4 = 2.00 A.', true, '2026-10-12 19:15:34.214', '2026-10-12 19:15:34.214', null, null, null, 'An equipment whose power is 1500 W and resistance is 375 ohms would draw a current of', '["0.10 A","2.00 A","4.00 A","77.5 A."]', 'P = I<sup>2</sup>R, so I = √(1500/375) = √4 = 2.00 A.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7faf0b2e-7171-4498-b222-cd66d1faf366', 'Literature in English', 'JAMB', null, 2026, null, 'Ananse is best described as a', null, '["tragic hero","comic trickster","villain","chorus"]', 1, 'Ananse is a comic trickster.', true, '2026-09-12 11:14:10.004', '2026-09-12 11:14:10.004', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7fb1b60e-7b48-44cd-a4fa-03df91b7024a', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Why was Saul pleased when he was told that his daughter Michal was in love with David?', null, '["Michal was already getting old to marry","Jonathan, David''s friend was Michal''s brother","He would get a handsome marriage present from David","He thought that Michal might be a snare for David","He would get David to destroy the Philistines"]', 3, 'Saul was pleased when he was told that Michal was in love with David because he thought that Michal might be a snare for David. Saul hoped that David would be killed by the Philistines while trying to fulfill the marriage condition.', true, '2026-09-12 09:46:15.085', '2026-09-12 09:46:15.085', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7fb321bb-9ee6-42f6-af17-3671df23acb7', 'Financial Accounting', 'UTME', null, 2002, null, 'Given that 1/3 of the N6000 stock held by a branch is purchased from outsiders. If goods are invoiced to branch at 25% on cost, the provision for unrealized profit is', null, '["N1000.00","N333.33","N666.66","N800.00"]', 3, 'Total Stock held 6000, 1/3 bought outside 2000, Market value of goods sent for H.O 4000. 25% on cost = 20% on market value. 20/100 x 4,000 = 800.', true, '2026-10-12 21:59:58.203', '2026-10-12 21:59:58.203', null, null, null, 'Given that 1/3 of the N6000 stock held by a branch is purchased from outsiders. If goods are invoiced to branch at 25% on cost, the provision for unrealized profit is', '["N1000.00","N333.33","N666.66","<b>N800.00</b>"]', 'Total Stock held 6000, 1/3 bought outside 2000, Market value of goods sent for H.O 4000. 25% on cost = 20% on market value. 20/100 x 4,000 = <b>800</b>.', '{"bold":["800"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7fb65a62-aa1a-436a-9c6d-f7ff2e460d24', 'Literature in English', 'JAMB', null, 2026, null, '''I have told you a thousand times to be careful'' is an example of what figure of speech.', null, '["hyperbole","litotes","euphemism","oxymoron"]', 0, 'The statement is an example of hyperbole.', true, '2026-09-12 11:12:09.262', '2026-09-12 11:12:09.262', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7fbbf8c9-d9ed-4499-a83e-53c1c7386e57', 'Literature in English', 'JAMB', null, 2026, null, 'The phrase ''blood and brine'' in the third stanza is an example of', null, '["alliteration","onomatopoeia","assonance","consonance"]', 0, '''Blood and brine'' is alliteration.', true, '2026-09-12 11:07:21.437', '2026-09-12 11:07:21.437', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7fbc3448-247b-4c3c-8af7-4a1277d82e72', 'Physics', 'JAMB', null, 2003, null, 'A bead travelling on a straight wire is brought to rest at 0.2 m by friction. If the mass of the bead is 0.01 kg and the coefficient of friction between the bead and the wire is 0.1, determine the work done by the friction. [g = 10 m s⁻²]', null, '["2 x 10⁻³ J","2 x 10² J","2 x 10⁻⁴ J","2 x 10¹ J"]', 0, 'Friction force = μmg = 0.1 x 0.01 x 10 = 0.01 N. Work = F x d = 0.01 x 0.2 = 2 x 10⁻³ J.', true, '2026-10-12 19:15:54.994', '2026-10-12 19:15:54.994', null, null, null, 'A bead travelling on a straight wire is brought to rest at 0.2 m by friction. If the mass of the bead is 0.01 kg and the coefficient of friction between the bead and the wire is 0.1, determine the work done by the friction. [g = 10 m s<sup>-2</sup>]', '["2 x 10<sup>-3</sup> J","2 x 10<sup>2</sup> J","2 x 10<sup>-4</sup> J","2 x 10<sup>1</sup> J"]', 'Friction force = μmg = 0.1 x 0.01 x 10 = 0.01 N. Work = F x d = 0.01 x 0.2 = 2 x 10<sup>-3</sup> J.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7fc5abd0-f50e-478c-af28-5aa1695b1908', 'Literature in English', 'JAMB', null, 2026, null, 'What does Antony mean by ''bridegroom in my death''?', null, '["He plans to marry before dying","He welcomes death as lovingly as meeting a bride","He dreams of a royal wedding","He wants to be buried beside Cleopatra"]', 1, 'He welcomes death as lovingly as meeting a bride.', true, '2026-09-12 11:14:15.272', '2026-09-12 11:14:15.272', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7fc88277-0698-43e3-9347-29a0c745607d', 'Physics', 'JAMB', null, 2001, null, 'Ice cubes are added to a glass of warm water. The glass and water are cooled by', null, '["Conduction only","Convection only","Conduction and convection","Convection and radiation"]', 2, 'Heat passes from the water to the ice by conduction, and the cooled water sinks and circulates in convection currents.', true, '2026-10-12 19:15:51.147', '2026-10-12 19:15:51.147', null, null, null, 'Ice cubes are added to a glass of warm water. The glass and water are cooled by', '["Conduction only","Convection only","Conduction and convection","Convection and radiation"]', 'Heat passes from the water to the ice by conduction, and the cooled water sinks and circulates in convection currents.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7fc94d6b-f26a-4617-9c59-4223922387d0', 'Physics', 'JAMB', null, 1997, null, 'In a metre bridge experiment, two resistors 2 Ω and 3 Ω occupy the left and right gaps respectively. Find the balance point from the left side of the bridge.', null, '["20 cm","40 cm","60 cm","80 cm"]', 1, 'l/(100 - l) = 2/3, so 3l = 200 - 2l and l = 40 cm.', true, '2026-10-12 19:15:44.227', '2026-10-12 19:15:44.227', null, null, null, 'In a metre bridge experiment, two resistors 2 Ω and 3 Ω occupy the left and right gaps respectively. Find the balance point from the left side of the bridge.', '["20 cm","40 cm","60 cm","80 cm"]', 'l/(100 - l) = 2/3, so 3l = 200 - 2l and l = 40 cm.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7fca3ab9-b072-4881-9648-ae91ffc9f90e', 'Biology', 'JAMB', null, 2026, null, 'Which enzymes are contained in the pancreatic juice?', null, '["amylase, lipase, trypsin","maltase, erepsin and trypsin","ptyalin, lipase and erepsin","renin, sucrase and lipase"]', 0, 'Pancreatic juice contains three major digestive enzymes: pancreatic amylase (digests starch into maltose), pancreatic lipase (digests fats into fatty acids and glycerol), and trypsinogen (activated to trypsin in the duodenum, digesting proteins into peptides). Maltase and erepsin are intestinal enzymes, not pancreatic. Ptyalin is salivary amylase. Renin is produced in the stomach of infants, and sucrase is an intestinal enzyme.', true, '2026-09-09 03:18:15.671', '2026-09-09 03:18:15.671', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7fd86163-ba6e-4a79-8d84-7548aa73fcf0', 'English Language', 'JAMB', null, 2024, null, '(Choose the Antonym) Gregarious animals can be found in the zoo.', null, '["Wild","lonely","various","Tame"]', 1, '"Gregarious" means sociable or fond of company; the antonym is "lonely."', true, '2026-09-18 09:34:03.956', '2026-09-18 09:34:03.956', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7fe4114d-7804-42df-9401-8ee79689a61f', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). Ngozi and Ekwere were <u>fast friends</u> when they were in the secondary school.', null, '["friends who run very quickly together","friends who go without food for a long time together","friends who spend too much time and energy on pleasure and excitement together","friends who are not easily separated from each other"]', 3, '''Fast friends'' = closely attached friends.', true, '2026-10-24 01:02:06.116', '2026-10-24 01:02:06.116', null, null, null, '(Choose the most appropriate interpretation). Ngozi and Ekwere were <u>fast friends</u> when they were in the secondary school.', '["friends who run very quickly together","friends who go without food for a long time together","friends who spend too much time and energy on pleasure and excitement together","<u>friends who are not easily separated from each other</u>"]', '''<b>Fast friends</b>'' = <b>closely attached friends</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7fecd7a4-38ae-4456-a8cb-78067c538b2e', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. He broke his mallet <u>ostensibly</u> trying to maintain order although he was actually enjoying the commotion.', null, '["apparently","carelessly","angrily","accidentally"]', 0, 'Ostensibly = apparently.', true, '2026-10-24 01:01:42.551', '2026-10-24 01:01:42.551', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. He broke his mallet <u>ostensibly</u> trying to maintain order although he was actually enjoying the commotion.', '["<u>apparently</u>","carelessly","angrily","accidentally"]', '<b>Ostensibly</b> = <b>apparently</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7fee14f9-db22-42ce-8d12-d944bc167d4f', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Jim was one of the <u>spectators</u> at the concert.', null, '["ushers","judges","guests","performers"]', 3, 'Spectators = watchers; opposite = performers.', true, '2026-10-24 07:21:11.419', '2026-10-24 07:21:11.419', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Jim was one of the <u>spectators</u> at the concert.', '["ushers","judges","guests","performers"]', 'Spectators = watchers; opposite = performers.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('7ff8695e-a9af-40ab-a028-8f4e576edf3e', 'Literature in English', 'JAMB', null, 2026, null, 'The conflict presented in the poem is mainly between', null, '["tradition and modern technology","native culture and foreign influence","rich and poor citizens","government and opposition"]', 1, 'The conflict is between native culture and foreign influence.', true, '2026-09-12 11:05:54.247', '2026-09-12 11:05:54.247', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('80012bf6-531d-4963-a6c4-80c50b6df533', 'Physics', 'JAMB', null, 1998, null, 'The most suitable type of mirror used for the construction of a searchlight is the', null, '["Concave mirror","Convex mirror","Spherical mirror","Parabolic mirror."]', 3, 'A parabolic reflector produces a truly parallel beam from a source at its focus, which is why it is used for searchlights.', true, '2026-10-12 19:15:46.105', '2026-10-12 19:15:46.105', null, null, null, 'The most suitable type of mirror used for the construction of a searchlight is the', '["Concave mirror","Convex mirror","Spherical mirror","Parabolic mirror."]', 'A parabolic reflector produces a truly parallel beam from a source at its focus, which is why it is used for searchlights.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('800203af-b880-4db6-ad1c-2b403e4f7c1d', 'Biology', 'JAMB', null, 2005, null, 'The main function of the caudal fin in Tilapia is to', null, '["propel it forward in water","steer it while changing direction","balance it in water","enable it to float in water"]', 0, 'The caudal fin propels the fish forward.', true, '2026-10-12 20:59:37.125', '2026-10-12 20:59:37.125', null, null, null, 'The main function of the caudal fin in Tilapia is to', '["propel it forward in water","steer it while changing direction","balance it in water","enable it to float in water"]', 'The caudal fin propels the fish forward.', '{"bold":["propels the fish forward"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8006350b-42a0-4887-b725-fd7beb45b714', 'Hausa', 'JAMB', null, 2011, null, 'Wace hanya ce ake bi domin shiga harkar bori?', null, '["Girka.","Garaya.","Addu''a.","Shaushawa."]', 0, 'Girka ita ce hanya da ake bi domin shiga harkar bori.', true, '2026-10-13 10:37:21.72', '2026-10-13 10:37:21.72', null, null, null, 'Wace hanya ce ake bi domin shiga harkar bori?', '["Girka.","Garaya.","Addu''a.","Shaushawa."]', 'Girka ita ce hanya da ake bi domin shiga harkar bori.', '{"bold":["Girka"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('800e696a-8be7-4e75-b1f5-1abd06cc1091', 'English Language', 'JAMB', null, 2024, null, 'What was the major problem Bepo faced during his NIN validation?', null, '["corruption among officials","Long queues","poor network","demand for bribes"]', 2, 'Bepo''s major problem during NIN validation was poor network.', true, '2026-09-18 09:23:08.255', '2026-09-18 09:23:08.255', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('80243163-08ec-4b3a-b6d4-df1487c352e2', 'Literature in English', 'JAMB', null, 2026, null, 'A short poem inscribed on a tombstone is called an', null, '["Epigram","Epitaph","Epistle","Elegy"]', 1, 'A short poem inscribed on a tombstone is called an epitaph. Epitaphs are brief commemorative inscriptions, often in verse, honoring the deceased. An epigram is a brief, witty, and satirical poem. An epistle is a letter in verse form. An elegy is a mournful poem lamenting the dead. The epitaph is specifically associated with tombstones.', true, '2026-09-10 10:45:34.182', '2026-09-10 10:45:34.182', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('803ae6af-2df3-4485-a8ec-0c5b0adc7e6e', 'Christian Religious Studies', 'JAMB', null, 2026, null, '''He saved others, he cannot save himself.'' Who mocked Jesus with these words?', null, '["Those who passed by the cross","The soldiers who crucified Jesus","The women who watched the crucifixion","The Chief priests, scribes and elders","The two robbers who were hanged together with Jesus"]', 3, 'The chief priests, scribes, and elders mocked Jesus.', true, '2026-09-12 10:42:17.801', '2026-09-12 10:42:17.801', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('804378f3-6647-4ef3-a17b-945b32f2fe43', 'Biology', 'JAMB', null, 2026, null, 'The probability of producing a heterozygous progeny between two heterozygous individuals of pea plant is', null, '["1/2","1/3","1/4","3/4"]', 0, 'The probability of producing a heterozygous progeny between two heterozygous individuals (Tt × Tt) is 1/2 (50%). The Punnett square shows: TT (1/4), Tt (1/2), tt (1/4). This is the classic Mendelian ratio of 1:2:1. The probability of heterozygous offspring is 2 out of 4 or 1/2. The probability of homozygous dominant is 1/4 and homozygous recessive is 1/4.', true, '2026-09-09 03:19:24.989', '2026-09-09 03:19:24.989', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('80594200-96d3-43c5-b499-c8cf25bd6a32', 'Government', 'JAMB', null, 2026, null, 'The Armed forces ruling council was introduced by', null, '["Maj. Gen. Ibrahim Babangida","Gen. Sanni Abacha","Lt. Col. Yakubu Gowon","Brig. Murtala Muhammed"]', 0, 'The AFRC was introduced by Maj. Gen. Ibrahim Babangida.', true, '2026-09-12 11:24:01.696', '2026-09-12 11:24:01.696', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('805bdc53-01be-4bb7-b929-cc1fb34fa84a', 'Biology', 'JAMB', null, 2002, null, 'The carnassial teeth of a carnivorous animal consist of the', null, '["last upper premolar and the first lower molar","last upper molar and the last lower molar","first upper premolar and the first lower molar","first upper molar and the first lower molar"]', 0, 'Carnassial teeth are the last upper premolar and first lower molar.', true, '2026-10-12 20:59:30.858', '2026-10-12 20:59:30.858', null, null, null, 'The carnassial teeth of a carnivorous animal consist of the', '["last upper premolar and the first lower molar","last upper molar and the last lower molar","first upper premolar and the first lower molar","first upper molar and the first lower molar"]', 'Carnassial teeth are the last upper premolar and first lower molar.', '{"bold":["last upper premolar and first lower molar"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('806602a9-e17e-44e3-8e39-5e6901b53385', 'Government', 'JAMB', null, 2026, null, 'Which of the following is a feature of Nigerian Federalism?', null, '["Single-party system","Centralized fiscal system","Autonomy of local government","Strong central government"]', 1, 'A centralized fiscal system is a feature of Nigerian federalism.', true, '2026-09-12 11:24:31.241', '2026-09-12 11:24:31.241', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('80774985-2461-4091-8cbf-4ad2ae1d1ca4', 'Chemistry', 'JAMB', null, 2026, null, 'In which of the following is gallium showing an oxidation number of +3', null, '["NaGaO","NaGa(OH)4","NaGa(OH)3","NaGaO3"]', 1, 'In NaGa(OH)4: (+1) + Ga + 4(-1) = 0 => Ga - 3 = 0 => Ga = +3.', true, '2026-09-09 17:12:46.293', '2026-09-09 17:12:46.293', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('807de1cd-a539-49bc-b297-c1886403ea73', 'English Language', 'JAMB', null, 2007, null, 'Unoka <u>__________</u> the whole house to find his missing wristwatch.', null, '["scourged","scoured","scored","scouted"]', 1, 'Correct spelling: scoured.', true, '2026-10-24 07:21:36.771', '2026-10-24 07:21:36.771', null, null, null, 'Unoka <u>__________</u> the whole house to find his missing wristwatch.', '["scourged","scoured","scored","scouted"]', 'Correct spelling: scoured.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('808ba180-3318-454c-9e2f-f53c34484418', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The judge blamed the <u>plaintiff</u> for misleading the court.', null, '["defendant","complainant","accused","prosecution"]', 0, 'Plaintiff = complainant; opposite = defendant.', true, '2026-10-24 07:21:12.7', '2026-10-24 07:21:12.7', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The judge blamed the <u>plaintiff</u> for misleading the court.', '["defendant","complainant","accused","prosecution"]', 'Plaintiff = complainant; opposite = defendant.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('808ed4c8-2536-46d0-93a3-e8e23c1a021c', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Violent crime is only one of the <u>maladies</u> afflictions modern society.', null, '["damages","illnesses","wounds","crises"]', 1, 'Maladies = illnesses.', true, '2026-10-24 01:01:56.23', '2026-10-24 01:01:56.23', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Violent crime is only one of the <u>maladies</u> afflictions modern society.', '["damages","<u>illnesses</u>","wounds","crises"]', '<b>Maladies</b> = <b>illnesses</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('809df24c-b26e-464a-ade8-feab16bcf2b4', 'English Language', 'JAMB', null, 2007, null, 'Go straight down the hill and take the third <u>__________</u> on the left. You can''t miss it', null, '["bend","branch","junction","turning"]', 3, 'Correct spelling: turning.', true, '2026-10-24 07:21:43.967', '2026-10-24 07:21:43.967', null, null, null, 'Go straight down the hill and take the third <u>__________</u> on the left. You can''t miss it', '["bend","branch","junction","turning"]', 'Correct spelling: turning.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('80a50482-d4ad-4dac-a75b-3f340dd21d8e', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Many Nigerians are <u>wary of</u> night journeys.', null, '["unscarred of","worried about","troubled about","satisfied with"]', 3, 'Wary of = cautious of; opposite = satisfied with.', true, '2026-10-24 07:21:25.382', '2026-10-24 07:21:25.382', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Many Nigerians are <u>wary of</u> night journeys.', '["unscarred of","worried about","troubled about","satisfied with"]', 'Wary of = cautious of; opposite = satisfied with.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('80abc560-a48c-43d0-81ac-59731c173401', 'Hausa', 'JAMB', null, 2011, null, 'A wani gari can yamma da Magumi, wai shi Tsauni, an yi wani yaro mai suna Salihi. Iyayensa ba masu wadata ba ne, amma sun yi Ko''karin ganin ya yi ilmin boko da na Arabiya. Bayan Salihi ya kammala karatun firamare, sai mahaiﬁnsa Tanimu, ya nema masa makarantar gaba da ﬁramare. Domin an ce ''Ilimi gishirin zaman duniya.'' Amma kuma samo wa Salihi babbar makarantar Magumi bai yi wa mahaiﬁyarsa D''ahira dadî ba, don ba ta son d''anta ya yi nesa da ita. Dalili shi ne d''ansu tilo namiji, sauran hud''un kuwa duk mata ne. Bugu da Kari, tana jin munanan labarai iri-iri da kan faru a irin wad''annan makarantu. Bayan Salihi ya isa makaranta, sai ya dukufa kan karatu gadan-gadan. Zuwansa ke da wuya, sai suka kulla abota da wani dan ajinsu, wai shi Kasa. Kafin ya ankara, sai da abokinsa ya jefa shi cikin wata kungiyar asiri. Da ya farga da halin da ya shiga, sai ya yi Ko''karin ﬁta daga cikinta, amma aka nuna masa ai ba a haka. ''In har ka ce za ka ﬁce, lallai za a kassara ka, ko ma a halaka ka'' in ji abokinsa. Ganin halin tsaka-mai-wuya da ya shiga, sai ya tsayar da shawarar ya fallasa kungiyar, in ya so komai ta tafasa ta kone. Ya je ya shaida wa shugaban makaranta. Nan take ya sanya jami''an tsaro suka kamo dukkan ''yan kungiyar''. Kotu ta yanke musu hukunci, sannan aka kai su gidan jarun. Da ma an ce, ''Komai nisan jifa kasa za ya fado.'' Ina aka kai su Kasa bayan an yanke musu hukunci?', null, '["Tsauni.","Yamma da Magumi.","Ga shugaban makaranta.","Kurkuku."]', 3, 'Kotu ta yanke musu hukunci, sannan aka kai su gidan jarun (kurkuku).', true, '2026-10-13 10:37:20.412', '2026-10-13 10:37:20.412', null, null, null, 'A wani gari can yamma da Magumi, wai shi Tsauni, an yi wani yaro mai suna Salihi. Iyayensa ba masu wadata ba ne, amma sun yi Ko''karin ganin ya yi ilmin boko da na Arabiya. Bayan Salihi ya kammala karatun firamare, sai mahaiﬁnsa Tanimu, ya nema masa makarantar gaba da ﬁramare. Domin an ce ''Ilimi gishirin zaman duniya.'' Amma kuma samo wa Salihi babbar makarantar Magumi bai yi wa mahaiﬁyarsa D''ahira dadî ba, don ba ta son d''anta ya yi nesa da ita. Dalili shi ne d''ansu tilo namiji, sauran hud''un kuwa duk mata ne. Bugu da Kari, tana jin munanan labarai iri-iri da kan faru a irin wad''annan makarantu. Bayan Salihi ya isa makaranta, sai ya dukufa kan karatu gadan-gadan. Zuwansa ke da wuya, sai suka kulla abota da wani dan ajinsu, wai shi Kasa. Kafin ya ankara, sai da abokinsa ya jefa shi cikin wata kungiyar asiri. Da ya farga da halin da ya shiga, sai ya yi Ko''karin ﬁta daga cikinta, amma aka nuna masa ai ba a haka. ''In har ka ce za ka ﬁce, lallai za a kassara ka, ko ma a halaka ka'' in ji abokinsa. Ganin halin tsaka-mai-wuya da ya shiga, sai ya tsayar da shawarar ya fallasa kungiyar, in ya so komai ta tafasa ta kone. Ya je ya shaida wa shugaban makaranta. Nan take ya sanya jami''an tsaro suka kamo dukkan ''yan kungiyar''. Kotu ta yanke musu hukunci, sannan aka kai su gidan jarun. Da ma an ce, ''Komai nisan jifa kasa za ya fado.'' Ina aka kai su Kasa bayan an yanke musu hukunci?', '["Tsauni.","Yamma da Magumi.","Ga shugaban makaranta.","Kurkuku."]', 'Kotu ta yanke musu hukunci, sannan aka kai su gidan jarun (kurkuku).', '{"bold":["gidan jarun"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('80b55201-1645-4e36-bccd-adb383a8c33b', 'Financial Accounting', 'UTME', null, 2003, null, 'What is the actual profit or loss arising from the vehicle as at 31st December 2003?', 'https://res.cloudinary.com/kwi1uv0g/image/upload/v1791841260/questions/o0wuirbifovbzpkbcgtt.jpg', '["N250000 loss","N50000 loss","N450000 profit","N575000 profit"]', 3, 'Written down value of the vehicle disposed 125,000. Sales proceeds 700,000. Less written down value 120,000 = 575,000 profit.', true, '2026-10-12 21:59:59.781', '2026-10-12 21:59:59.781', null, null, null, 'What is the actual profit or loss arising from the vehicle as at 31st December 2003?', '["N250000 loss","N50000 loss","N450000 profit","<b>N575000 profit</b>"]', 'Written down value of the vehicle disposed 125,000. Sales proceeds 700,000. Less written down value 120,000 = <b>575,000 profit</b>.', '{"bold":["575,000 profit"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('80d1923d-571b-4d8a-a101-d6a03b7d44a3', 'Economics', 'JAMB', null, 2026, null, 'An economy system that uses what is regarded as the ''Market mechanism'' is called', null, '["Communism","Socialism","Capitalism","Mixed"]', 2, 'Capitalism uses the market mechanism (price system) to allocate resources.', true, '2026-09-12 10:57:27.059', '2026-09-12 10:57:27.059', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('80d1f3ff-bd68-41df-9aa6-13d499d684cc', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Many untrustworthy students give <u>evasive</u> answers to questions which they fully understand.', null, '["direct","outspoken","simple","truthful","clever"]', 0, 'Evasive = indirect; opposite = direct.', true, '2026-10-24 07:21:10.91', '2026-10-24 07:21:10.91', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Many untrustworthy students give <u>evasive</u> answers to questions which they fully understand.', '["direct","outspoken","simple","truthful","clever"]', 'Evasive = indirect; opposite = direct.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('80f56f9c-6676-42c3-bebe-e37460e872e2', 'Government', 'JAMB', null, 2026, null, 'What was the primary purpose of the Sir Henry Willinks Commission of inquiry', null, '["to approve the independence of Nigeria","To allay the fears of minorities in Nigeria","to amalgamate Northern and Southern Nigeria","to make Lagos a British colony"]', 1, 'The Willinks Commission was set up to allay the fears of minorities.', true, '2026-09-12 11:24:15.912', '2026-09-12 11:24:15.912', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('80f616a8-f99d-46bb-b75c-1e2edec6b63f', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The company is to <u>shed</u> three thousand staff this year.', null, '["demote","lay off","throw up","placate"]', 1, 'Shed staff = lay off.', true, '2026-10-24 01:04:04.455', '2026-10-24 01:04:04.455', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The company is to <u>shed</u> three thousand staff this year.', '["demote","<u>lay off</u>","throw up","placate"]', '<b>Shed</b> staff = <b>lay off</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('80f9b1bb-6018-4903-a0d0-5f7d056fa3e5', 'Physics', 'JAMB', null, 2002, null, 'The effect of a particle in a fluid attaining its terminal velocity is that the', null, '["Buoyancy force is more than the weight of the fluid displaced","Buoyancy force is equal to the viscous retarding force","Acceleration is maximum","Weight is equal to the retarding force."]', 3, 'At terminal velocity the acceleration is zero, so the weight equals the total retarding force (upthrust plus viscous drag).', true, '2026-10-12 19:15:52.944', '2026-10-12 19:15:52.944', null, null, null, 'The effect of a particle in a fluid attaining its terminal velocity is that the', '["Buoyancy force is more than the weight of the fluid displaced","Buoyancy force is equal to the viscous retarding force","Acceleration is maximum","Weight is equal to the retarding force."]', 'At terminal velocity the acceleration is zero, so the weight equals the total retarding force (upthrust plus viscous drag).', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('80ff8d74-113a-48cd-b37d-d23196358882', 'Biology', 'JAMB', null, 2026, null, 'The major site of photosynthesis in the leaf is the', null, '["upper epidermis","lower epidermis","mesophyll parenchyma","palisade parenchyma"]', 3, 'The palisade parenchyma is the major site of photosynthesis in the leaf. These elongated cells are densely packed with chloroplasts and are located just beneath the upper epidermis. This position maximizes light capture for photosynthesis. The upper and lower epidermis lack chloroplasts and primarily serve protective functions. The mesophyll parenchyma (spongy mesophyll) has fewer chloroplasts and is more involved in gas exchange. The palisade cells contain the highest concentration of chloroplasts, making them the main photosynthetic tissue.', true, '2026-09-09 03:18:42.214', '2026-09-09 03:18:42.214', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('810711b1-d52a-4790-87f6-22705c50c44b', 'English Language', 'JAMB', null, 2007, null, 'Wherever the leader went people struggled to catch a <u>__________</u> of him', null, '["look","view","glimpse","portrait","picture"]', 2, 'Correct spelling: glimpse.', true, '2026-10-24 07:21:40.68', '2026-10-24 07:21:40.68', null, null, null, 'Wherever the leader went people struggled to catch a <u>__________</u> of him', '["look","view","glimpse","portrait","picture"]', 'Correct spelling: glimpse.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('810c0f16-88be-4350-98af-df746607f0c4', 'Government', 'JAMB', null, 2026, null, 'Power differs from influence in that it is', null, '["persuasive while influence is directive","coercive while influence is harmful","coercive while influence is persuasive","arrogant while influence is corruptive"]', 2, 'Power is coercive (ability to enforce compliance), while influence is persuasive (ability to affect others without force).', true, '2026-09-12 11:23:53.566', '2026-09-12 11:23:53.566', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('81136f24-05c5-434f-bac7-7ffd0dba73ca', 'Chemistry', 'JAMB', null, 2026, null, 'At equilibrium in a closed system', null, '["the reaction has stopped","reactants and products are equal in amount","forward and reverse reactions occur at equal rates","the catalyst has been used up"]', 2, 'At equilibrium, the forward and reverse reactions occur at equal rates, so the concentrations of reactants and products remain constant. The reaction has not stopped; it is dynamic. Reactants and products are not necessarily equal in amount, and the catalyst is not used up.', true, '2026-09-12 09:38:17.328', '2026-09-12 09:38:17.328', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('813b310d-ae89-4ba8-965d-e5ca68db0676', 'General Mathematics', 'JAMB', null, 2026, null, 'In a school, there are 1000 boys and a number of girls. 48% of the total number of students were successful in an examination, made up of 50% of the boys and 40% of the girls. Find the number of girls in the school', null, '["1600","400","800","500","250"]', 2, 'Let g = number of girls. Total = 1000 + g. Successful = 0.48(1000+g). Also = 0.50(1000) + 0.40g = 500 + 0.4g. So 0.48(1000+g) = 500 + 0.4g. 480 + 0.48g = 500 + 0.4g. 0.08g = 20. g = 250. Wait, that gives 250. Let me recalculate: 480 + 0.48g = 500 + 0.4g. 0.08g = 20. g = 250. The answer is 250 (E). But option (C) is 800. Let me check: 48% of total = 500 + 0.4g. If g = 800, total = 1800. 48% of 1800 = 864. 50% of 1000 + 40% of 800 = 500 + 320 = 820. Not equal. If g = 250, total = 1250. 48% of 1250 = 600. 500 + 100 = 600. Yes! g = 250. The answer is (E) 250.', true, '2026-09-12 11:43:38.338', '2026-09-12 11:43:38.338', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8149a980-5a81-4662-8bbf-e4e01815e292', 'Biology', 'JAMB', null, 2001, null, 'Urea formation occurs in the', null, '["liver","kidney","heart","lung"]', 0, 'Urea is formed in the liver through the ornithine cycle.', true, '2026-10-12 20:59:28.642', '2026-10-12 20:59:28.642', null, null, null, 'Urea formation occurs in the', '["liver","kidney","heart","lung"]', 'Urea is formed in the liver through the ornithine cycle.', '{"bold":["liver"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8151de89-202d-466e-8b32-615a211a5713', 'Biology', 'JAMB', null, 2003, null, 'The most common characteristic of the fungal hyphae is the possession of', null, '["cell-like compartments with one nucleus each","cell walls that are both rigid and chitinous","a multicellular mycelium in the substrate","cell-like partitions formed by cross-walls"]', 1, 'Fungal cell walls are characteristically rigid and composed of chitin.', true, '2026-10-12 20:05:10.811', '2026-10-12 20:05:10.811', null, null, null, 'The most common characteristic of the fungal hyphae is the possession of', '["cell-like compartments with one nucleus each","cell walls that are both rigid and chitinous","a multicellular mycelium in the substrate","cell-like partitions formed by cross-walls"]', 'Fungal cell walls are characteristically rigid and composed of chitin.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8154ad12-a692-45f8-b1a0-3b8a44f67edc', 'Physics', 'JAMB', null, 1998, null, 'A man wears convex lens glasses of focal length 30 cm in order to correct his eye defect. Instead of the optimum 25 cm, his least distance of distinct vision is', null, '["14 cm","28 cm","75 cm","150 cm"]', 3, 'The glasses form a virtual image at the man''s near point d for an object at 25 cm: 1/30 = 1/25 - 1/d, so 1/d = 1/150 and d = 150 cm.', true, '2026-10-12 19:15:46.216', '2026-10-12 19:15:46.216', null, null, null, 'A man wears convex lens glasses of focal length 30 cm in order to correct his eye defect. Instead of the optimum 25 cm, his least distance of distinct vision is', '["14 cm","28 cm","75 cm","150 cm"]', 'The glasses form a virtual image at the man''s near point d for an object at 25 cm: 1/30 = 1/25 - 1/d, so 1/d = 1/150 and d = 150 cm.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('81586c31-35cc-4adf-b48e-33a7bec3302c', 'General Mathematics', 'JAMB', null, 2026, null, 'A vertical radio mast is supported by three equal wires. One end of each wire is fixed to the mast and the other end forms an equilateral triangular horizontal ground. If the length of each wire is twice the height of the mast, find the angle between any two adjacent wires', null, '["181.7°","30°","45.3°","97.2°","None of these"]', 3, 'The angle between adjacent wires is 97.2°.', true, '2026-09-12 11:43:42.187', '2026-09-12 11:43:42.187', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('815efe9c-8fd1-4ac3-b62f-21f93d293c6f', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The <u>exhibition</u> was an eye opener to all.', null, '["display","style","examination","dispatch"]', 0, 'Exhibition = display.', true, '2026-10-24 01:01:58.556', '2026-10-24 01:01:58.556', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The <u>exhibition</u> was an eye opener to all.', '["<u>display</u>","style","examination","dispatch"]', '<b>Exhibition</b> = <b>display</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('816cb441-ad25-4649-a6fa-c70560b02e64', 'Biology', 'JAMB', null, 2002, null, 'An amoeba and an unlaid chicken egg are', null, '["animal tissues","organelles","single cells","organisms"]', 2, 'Both amoeba and an unlaid chicken egg are single cells.', true, '2026-10-12 20:59:29.931', '2026-10-12 20:59:29.931', null, null, null, 'An amoeba and an unlaid chicken egg are', '["animal tissues","organelles","single cells","organisms"]', 'Both amoeba and an unlaid chicken egg are single cells.', '{"bold":["single cells"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('816ee0fd-6e1c-4f71-ba71-6973b234a153', 'General Mathematics', 'JAMB', null, 2026, null, 'Make R the subject of the formula in T = (KR² + M)/3', null, '["√((3T-K)/M)","√((3T+K)/M)","√((3T-M)/K)","√((3T+M)/K)"]', 2, '3T = KR² + M. KR² = 3T-M. R = √((3T-M)/K).', true, '2026-09-12 11:44:16.946', '2026-09-12 11:44:16.946', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8179e7e4-96e0-42be-a4ba-5df9f4844aeb', 'Economics', 'JAMB', null, 2026, null, 'Currency is the same between two or more countries in international trade. True or false', null, '["True","False","Maybe","Uncertain"]', 1, 'False. Different countries have different currencies in international trade.', true, '2026-09-12 11:00:34.064', '2026-09-12 11:00:34.064', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('817cf020-bfe2-4778-a52a-6785e4a2ab6a', 'Chemistry', 'JAMB', null, 2026, null, 'A side effect of soft water is that', null, '["it gives offensive taste","excess calcium is precipitated","it encourages the growth of bacteria","it attacks lead contained in pipes"]', 3, 'Soft water lacks protective dissolved calcium salts, allowing it to dissolve lead from plumbing pipes (plumbosolvency).', true, '2026-09-09 17:12:47.148', '2026-09-09 17:12:47.148', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('818da12a-ad71-4ba3-8e91-1a907ab13ca1', 'Economics', 'JAMB', null, 2026, null, 'The following are features of an Oligopoly except', null, '["Interdependence of firms","Restriction of entry","Possible collusion to form cartel","Large number of sellers"]', 3, 'Oligopoly has a few large sellers, not a large number of sellers.', true, '2026-09-12 10:59:49.542', '2026-09-12 10:59:49.542', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('81931640-188c-410b-90d0-4bc6664e6b6d', 'Literature in English', 'JAMB', null, 2026, null, 'In Once Upon a Time, the line ''They used to laugh with their hearts / And laugh with their eyes'' suggests', null, '["Artificiality in human interaction","Emotional weakness","Mockery among friends","Genuine sincerity in past relationships"]', 3, 'The line suggests genuine sincerity in past relationships.', true, '2026-09-12 11:09:55.128', '2026-09-12 11:09:55.128', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8195be6c-5afa-42aa-a22f-81498f2f4914', 'Physics', 'JAMB', null, 2000, null, 'A certain radioactive source emits radiations that were found to be deflected by both magnetic and electric fields. The radiations are', null, '["X-rays","Beta rays","Gamma rays","Ultra-violet rays"]', 1, 'Only charged radiation is deflected by electric and magnetic fields. Of the options, beta rays (electrons) are charged; the others are electromagnetic waves.', true, '2026-10-12 19:15:50.343', '2026-10-12 19:15:50.343', null, null, null, 'A certain radioactive source emits radiations that were found to be deflected by both magnetic and electric fields. The radiations are', '["X-rays","Beta rays","Gamma rays","Ultra-violet rays"]', 'Only charged radiation is deflected by electric and magnetic fields. Of the options, beta rays (electrons) are charged; the others are electromagnetic waves.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('819eb894-ac12-4965-9761-def71b8f777a', 'General Mathematics', 'JAMB', null, 2026, null, 'Find the equation of the perpendicular line at point (4,3) to the line: y + 2x = 5', null, '["2y - x = 4","y + 2x = 3","y + 2x = 5","2y - x = 2"]', 3, 'The line y + 2x = 5 has slope -2. The perpendicular line has slope 1/2. Using point (4,3): y - 3 = (1/2)(x - 4). Multiplying by 2: 2y - 6 = x - 4, so 2y - x = 2.', true, '2026-09-10 10:48:18.552', '2026-09-10 10:48:18.552', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('81a1f5f6-9e4c-4873-b905-2e246b13fcec', 'Christian Religious Studies', 'JAMB', null, 2026, null, '''The very stone which the builders rejected has become the head of the corner.'' This statement by Peter was directed to those who', null, '["built the Temple of Jerusalem","did not believe in Jesus'' preciousness","are hard hearted against Jesus Christ","don''t offer spiritual sacrifice"]', 1, 'Peter directed this statement to those who did not believe in Jesus'' preciousness. He quoted Psalm 118:22 to show that Jesus, though rejected by men, has become the cornerstone of God''s building. For those who do not believe, He is a stone of stumbling.', true, '2026-09-12 09:46:16.236', '2026-09-12 09:46:16.236', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('81a4d365-16b8-443e-9c97-9068fac40d26', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'The elders of Israel went to Samuel to request for a King at...', null, '["Jerusalem","Gilgal","Ramah","Ziph"]', 2, '1 Samuel 8:4 states that all the elders of Israel gathered together and came to Samuel at Ramah to demand a king to judge them.', true, '2026-09-09 17:18:23.78', '2026-09-09 17:18:23.78', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('81af6642-8d5d-455c-92ca-fd9db6878384', 'Physics', 'JAMB', null, 1986, null, 'Which of the following assumptions is made in a simple pendulum experiment? The', null, '["Suspending string is inextensible","Bob has a finite size","Bob has a definite mass","Initial angle of oscillation must be large."]', 0, 'A simple pendulum assumes a light, inextensible string, a point-like bob, and small-angle oscillations.', true, '2026-10-12 19:15:22.984', '2026-10-12 19:15:22.984', null, null, null, 'Which of the following assumptions is made in a simple pendulum experiment? The', '["Suspending string is inextensible","Bob has a finite size","Bob has a definite mass","Initial angle of oscillation must be large."]', 'A simple pendulum assumes a light, inextensible string, a point-like bob, and small-angle oscillations.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('81af7f44-2eb4-45e1-b8e8-712bed56d037', 'Biology', 'JAMB', null, 2026, null, 'At which trophic level would the highest accumulation of a non-biodegradable substance occur?', null, '["secondary consumers","tertiary consumers","primary consumers","primary consumers"]', 1, 'Biomagnification is the increase in concentration of non-biodegradable substances (such as DDT, heavy metals, and PCBs) as they move up the food chain. Tertiary consumers (top predators) accumulate the highest concentrations because they eat secondary consumers that have already accumulated substances from primary consumers. This occurs because these substances are stored in fatty tissues and are not excreted. Each level in the food chain results in a higher concentration, sometimes reaching levels that are toxic to top predators.', true, '2026-09-09 03:18:19.436', '2026-09-09 03:18:19.436', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('81b3dbe7-711e-4bad-b579-d58722543c73', 'Literature in English', 'JAMB', null, 2026, null, 'Literature is best described as a', null, '["Complication of folktales","Record of past norms","Totality of man''s life experience","Story of great men and women"]', 2, 'Literature is the totality of man''s life experience.', true, '2026-09-12 11:11:02.226', '2026-09-12 11:11:02.226', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('81b6c0c7-42d1-4e2b-be8a-ec5ef27b31f7', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'God commanded that Aaron should speak for Moses to the Israelites, but Moses should be to Aaron as...', null, '["God","master","brother","priest"]', 0, 'Exodus 4:16 states: ''He shall be your spokesman to the people... and you shall be to him as God.''', true, '2026-09-09 17:18:26.674', '2026-09-09 17:18:26.674', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('81c18e30-231c-443f-88d5-f689b45baf40', 'Physics', 'JAMB', null, 1995, null, 'When a ball rolls on a smooth level ground, the motion of its centre is', null, '["Translational","Oscillatory","Random","Rotational"]', 0, 'The centre of the ball moves along a straight line, which is translational motion (the ball as a whole also rotates about its centre).', true, '2026-10-12 19:15:40.718', '2026-10-12 19:15:40.718', null, null, null, 'When a ball rolls on a smooth level ground, the motion of its centre is', '["Translational","Oscillatory","Random","Rotational"]', 'The centre of the ball moves along a straight line, which is translational motion (the ball as a whole also rotates about its centre).', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('81df28cb-6b1f-48b8-b8f5-b8987f5d796b', 'Biology', 'JAMB', null, 2003, null, 'The most important hormone that induces the ripening of fruit is', null, '["ethylene","indole acetic acid","gibberellin","cytokinin"]', 0, 'Ethylene induces fruit ripening.', true, '2026-10-12 20:59:33.18', '2026-10-12 20:59:33.18', null, null, null, 'The most important hormone that induces the ripening of fruit is', '["ethylene","indole acetic acid","gibberellin","cytokinin"]', 'Ethylene induces fruit ripening.', '{"bold":["Ethylene"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('81e0f42c-1796-4e1f-8cb8-b21a5056fcf0', 'Physics', 'JAMB', null, 1989, null, 'When a yellow card is observed through a blue glass, the card would appear', null, '["Black","Green","Red","White"]', 0, 'A yellow card reflects red and green only. A blue glass transmits only blue light, so no light reaches the eye and the card looks black.', true, '2026-10-12 19:15:29.577', '2026-10-12 19:15:29.577', null, null, null, 'When a yellow card is observed through a blue glass, the card would appear', '["Black","Green","Red","White"]', 'A yellow card reflects red and green only. A blue glass transmits only blue light, so no light reaches the eye and the card looks black.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('81e7f672-dfe9-4127-9b0a-8ec8f1c08a90', 'Literature in English', 'JAMB', null, 2026, null, 'The sea in the poem is best described as', null, '["a symbol of maternal care","an enemy of the people","a source of political power","a symbol of war"]', 0, 'The sea symbolizes maternal care.', true, '2026-09-12 11:05:46.243', '2026-09-12 11:05:46.243', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('81fcbd72-0c5e-41cf-84a7-55e5eba72793', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The administrator''s <u>apathy</u> was soon noticed by all his subordinates.', null, '["indifference","kindness","concern","inefficiency"]', 0, 'Apathy = indifference.', true, '2026-10-24 01:01:44.528', '2026-10-24 01:01:44.528', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The administrator''s <u>apathy</u> was soon noticed by all his subordinates.', '["<u>indifference</u>","kindness","concern","inefficiency"]', '<b>Apathy</b> = <b>indifference</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8213d057-f600-47a6-9c29-0f8882dee848', 'Physics', 'JAMB', null, 2002, null, 'The colours seen in soap bubbles are due to', null, '["Refraction","Diffraction","Interference","Dispersion"]', 2, 'Light reflected from the front and back of the thin soap film interferes, giving the colours.', true, '2026-10-12 19:15:53.762', '2026-10-12 19:15:53.762', null, null, null, 'The colours seen in soap bubbles are due to', '["Refraction","Diffraction","Interference","Dispersion"]', 'Light reflected from the front and back of the thin soap film interferes, giving the colours.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8224eab2-114d-4e5f-b74c-de0e1aaac3d2', 'Biology', 'JAMB', null, 2026, null, 'The flow of air and water in or out of the mesophyll layer of a leaf is controlled by the', null, '["stomata","lenticels","air spaces","guard cells"]', 0, 'The flow of air and water in or out of the mesophyll layer of a leaf is controlled by the stomata. Stomata are pores in the leaf epidermis that regulate gas exchange (CO₂ in, O₂ out) and water loss. Lenticels are pores in woody stems, not leaves. Air spaces are within the mesophyll but do not control flow. Guard cells control the opening and closing of the stomatal pore, but it is the stomata themselves that control flow. This regulation is crucial for balancing photosynthesis and water conservation.', true, '2026-09-09 03:19:07.498', '2026-09-09 03:19:07.498', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8233a6d6-8472-4078-aa30-ced01f3c4ca0', 'Physics', 'JAMB', null, 2026, null, 'What is another name for static Electricity?', null, '["Charge per unit mass","Electromagnetism","Electric Circuit","electrostatics"]', 3, 'Another name for static electricity is electrostatics. Electrostatics is the study of electric charges at rest and the forces between them.', true, '2026-09-10 10:56:45.144', '2026-09-10 10:56:45.144', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('82434267-1390-47d2-816d-88444ff37694', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Ayodeji is <u>an ardent</u> supporter of education for the girl child.', null, '["an optimistic","a cogent","a passionate","an ignorant"]', 2, 'Ardent = passionate.', true, '2026-10-24 01:01:58.134', '2026-10-24 01:01:58.134', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Ayodeji is <u>an ardent</u> supporter of education for the girl child.', '["an optimistic","a cogent","<u>a passionate</u>","an ignorant"]', '<b>Ardent</b> = <b>a passionate</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8253b129-6bf7-48ad-b386-377159f9e011', 'Literature in English', 'JAMB', null, 2026, null, 'The dramatic technique of ''story within a story'' is known as', null, '["aside","flashback","play-within-a-play","soliloquy"]', 2, 'It is known as play-within-a-play.', true, '2026-09-12 11:11:20.715', '2026-09-12 11:11:20.715', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('825bbbc5-ef48-4b31-a4b8-8c4b12888914', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The chief''s brother was a complete <u>nonentity</u>.', null, '["upstart","vagabond","riff-raff","person of inexperience"]', 3, 'Nonentity = person of no importance/inexperience.', true, '2026-10-24 01:03:59.047', '2026-10-24 01:03:59.047', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The chief''s brother was a complete <u>nonentity</u>.', '["upstart","vagabond","riff-raff","<u>person of inexperience</u>"]', '<b>Nonentity</b> = <b>person of no importance</b>/inexperience.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('825d6a91-2316-4f8f-8a82-f8ca00df485a', 'English Language', 'JAMB', null, 2007, null, 'Most of his personal <u>------------</u> stolen.', null, '["affects was","affects were","effect was","effects were"]', 3, '''Effects'' (belongings) plural â†’ were.', true, '2026-10-24 01:04:27.677', '2026-10-24 01:04:27.677', null, null, null, 'Most of his personal <u>------------</u> stolen.', '["affects was","affects were","effect was","<u>effects were</u>"]', '''<b>Effects</b>'' (belongings) plural â†’ <b>were</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8268eaf5-cb4b-4b89-8341-8865f9f8d6a9', 'Biology', 'JAMB', null, 2003, null, 'The stunted growth of a leguminous plant suffering from nitrogen deficiency may be corrected by inoculating the soil with', null, '["denifying bacteria","saprophytic bacteria","rhizobium","nitrosomonas"]', 2, 'Rhizobium bacteria fix atmospheric nitrogen into forms usable by leguminous plants.', true, '2026-10-12 20:05:09.5', '2026-10-12 20:05:09.5', null, null, null, 'The stunted growth of a leguminous plant suffering from nitrogen deficiency may be corrected by inoculating the soil with', '["denifying bacteria","saprophytic bacteria","rhizobium","nitrosomonas"]', 'Rhizobium bacteria fix atmospheric nitrogen into forms usable by leguminous plants.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8269ca8d-1007-4183-855f-fc9d9d252029', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'The promise of God with Abraham was that', null, '["he will live long","he would make nations out of him","he would make him return to his father''s house","he would give him flocks"]', 1, 'The promise of God to Abraham was that He would make nations out of him. God said, ''I will make of you a great nation, and I will bless you, and make your name great.''', true, '2026-09-12 09:46:07.776', '2026-09-12 09:46:07.776', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8279a2bd-c418-4136-81dd-c6e03bc52c34', 'Physics', 'JAMB', null, 2026, null, 'The fundamental frequency of vibration of a sonometer wire may be halved by', null, '["doubling the length of the wire","doubling the mass of the wire","reducing the tension by half","reducing the absolute temperature by half"]', 0, 'The fundamental frequency of a sonometer wire is inversely proportional to its length (f ∝ 1/L). To halve the frequency, the length must be doubled. Doubling the mass changes the linear density, reducing frequency by 1/√2. Reducing tension by half reduces frequency by 1/√2.', true, '2026-09-10 10:56:47.358', '2026-09-10 10:56:47.358', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('827a71f4-ba48-4657-a761-e6d642fb4753', 'Biology', 'JAMB', null, 2005, null, 'The transition from amphibians to mammals involves the limbs becoming arranged to support the weight more effectively requiring modifications in the', null, '["collar bones and coccyx","pectoral and pelvic girdles","scapulae and clavicles","vertebrae and sternum"]', 1, 'Pectoral and pelvic girdles were modified for weight support.', true, '2026-10-12 20:59:37.074', '2026-10-12 20:59:37.074', null, null, null, 'The transition from amphibians to mammals involves the limbs becoming arranged to support the weight more effectively requiring modifications in the', '["collar bones and coccyx","pectoral and pelvic girdles","scapulae and clavicles","vertebrae and sternum"]', 'Pectoral and pelvic girdles were modified for weight support.', '{"bold":["Pectoral and pelvic girdles"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('82876370-dcee-4237-b463-67383158d1b6', 'Physics', 'JAMB', null, 1993, null, 'The kinetic energy of a photoelectron liberated from a metallic surface depends on the', null, '["Intensity of the incident radiation","Time duration of the incident radiation","Temperature of the incident radiation","Frequency of the incident radiation"]', 3, 'Maximum kinetic energy = hf - φ, so it depends on the frequency of the incident radiation, not on its intensity.', true, '2026-10-12 19:15:38.782', '2026-10-12 19:15:38.782', null, null, null, 'The kinetic energy of a photoelectron liberated from a metallic surface depends on the', '["Intensity of the incident radiation","Time duration of the incident radiation","Temperature of the incident radiation","Frequency of the incident radiation"]', 'Maximum kinetic energy = hf - φ, so it depends on the frequency of the incident radiation, not on its intensity.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('82a656c4-ef7d-49dd-8a18-2a473cae2d5d', 'Biology', 'JAMB', null, 2001, null, 'The jointed structure in insects that bears organs which are sensitive to touch, smell and vibration is the', null, '["antenna","abdomen","maxilla","labium"]', 0, 'Insect antennae are sensory appendages covered with receptors sensitive to touch, smell, and vibrations.', true, '2026-10-12 20:05:08.803', '2026-10-12 20:05:08.803', null, null, null, 'The jointed structure in insects that bears organs which are sensitive to touch, smell and vibration is the', '["antenna","abdomen","maxilla","labium"]', 'Insect antennae are sensory appendages covered with receptors sensitive to touch, smell, and vibrations.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('82b2fd1a-5124-4219-a3ba-b78ccb8def81', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The Principal told the teacher to stop <u>browbeating</u> the children.', null, '["pampering","bullying","deceiving","caning"]', 1, 'Browbeating = bullying.', true, '2026-10-24 01:01:49.92', '2026-10-24 01:01:49.92', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The Principal told the teacher to stop <u>browbeating</u> the children.', '["pampering","<u>bullying</u>","deceiving","caning"]', '<b>Browbeating</b> = <b>bullying</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('82b93f5f-b4da-4ca5-aee8-7a1c6b9fe730', 'Literature in English', 'JAMB', null, 2026, null, 'In ''Night'', the poet primarily uses night as a symbol of', null, '["freedom","death and mystery","celebration","romantic love"]', 1, 'Night symbolizes death and mystery.', true, '2026-09-12 11:07:21', '2026-09-12 11:07:21', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('82bca56b-d413-4926-9e78-3179fa0edbd0', 'Biology', 'JAMB', null, 2002, null, 'A feature of the caste systems of bees and termites is that', null, '["the workers are sterile","the kings are bigger than the queens","only the worker perform duties","nuptial flight is performed by all members"]', 2, 'Only the workers perform duties in bee and termite colonies.', true, '2026-10-12 20:59:30.909', '2026-10-12 20:59:30.909', null, null, null, 'A feature of the caste systems of bees and termites is that', '["the workers are sterile","the kings are bigger than the queens","only the worker perform duties","nuptial flight is performed by all members"]', 'Only the workers perform duties in bee and termite colonies.', '{"bold":["Only the workers perform duties"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('82be2086-6ef5-498c-abfb-388bc9cc297a', 'Physics', 'JAMB', null, 1998, null, 'A vapour is said to be saturated when', null, '["More molecules return to the liquid than the amount that left it.","A dynamic equilibrium exists between the molecules of the liquid and the vapour molecules at a given temperature.","The vapour pressure is equal to the atmospheric pressure","All molecules are moving with the same speed in all directions at a given temperature."]', 1, 'A vapour is saturated when the rate at which molecules leave the liquid equals the rate at which they return (dynamic equilibrium).', true, '2026-10-12 19:15:45.623', '2026-10-12 19:15:45.623', null, null, null, 'A vapour is said to be saturated when', '["More molecules return to the liquid than the amount that left it.","A dynamic equilibrium exists between the molecules of the liquid and the vapour molecules at a given temperature.","The vapour pressure is equal to the atmospheric pressure","All molecules are moving with the same speed in all directions at a given temperature."]', 'A vapour is saturated when the rate at which molecules leave the liquid equals the rate at which they return (dynamic equilibrium).', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('82beeeed-c897-4e19-b2f4-2a54ceb17901', 'Biology', 'JAMB', null, 2026, null, 'The character producing factors in living organisms are found in the', null, '["chromomere","alleles","chromatids","chromosomes","genes"]', 4, 'Genes are the fundamental units of heredity that produce characters in living organisms. They are segments of DNA that code for proteins, which ultimately determine an organism''s traits. Chromosomes are structures that contain genes. Alleles are different forms of the same gene. Chromatids are duplicated chromosome strands. Chromomeres are bead-like structures on chromosomes. Genes are the functional units that carry instructions for all inherited characteristics and are passed from parents to offspring.', true, '2026-09-09 03:18:39.137', '2026-09-09 03:18:39.137', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('82d4ad60-6f45-4954-800a-1def08aa0459', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'The Amalekites were to be totally destroyed because they', null, '["were neighbours to Israelites","were men of Belial","were idol worshippers","opposed Israelites when they came out of Egypt"]', 3, 'The Amalekites opposed Israel during the Exodus.', true, '2026-09-12 10:42:04.422', '2026-09-12 10:42:04.422', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('82d5564c-dc8f-4bbd-8ec8-29ce8d8ca2cc', 'Yoruba', 'JAMB', null, 2007, null, 'Orí àpólà-ìye ni', null, '["òrõ-ìye","òrõ-orúkõ","òrõ-àpònlé","òrõ-àpèjúwe."]', 0, 'Orí àpólà-ìye ni òrõ-ìye.', true, '2026-10-13 13:23:31.357', '2026-10-13 13:23:31.357', null, null, null, 'Orí àpólà-ìye ni', '["òrõ-ìye","òrõ-orúkõ","òrõ-àpònlé","òrõ-àpèjúwe."]', 'Orí àpólà-ìye ni òrõ-ìye.', '{"bold":["òrõ-ìye"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('82faa3d1-ed15-4667-b8cb-8d56805a0786', 'Biology', 'JAMB', null, 2005, null, 'Which of the following is a homeostatic response in humans?', null, '["Withdrawing a hand from a hot object","The mouth getting watery when food is sighted","Yawning owing to tiredness","Shivering in a cold environment"]', 3, 'Shivering in a cold environment is a homeostatic response.', true, '2026-10-12 20:59:37.632', '2026-10-12 20:59:37.632', null, null, null, 'Which of the following is a homeostatic response in humans?', '["Withdrawing a hand from a hot object","The mouth getting watery when food is sighted","Yawning owing to tiredness","Shivering in a cold environment"]', 'Shivering in a cold environment is a homeostatic response.', '{"bold":["Shivering in a cold environment"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('830794bc-8295-46ce-ae26-2b025fe809d0', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. After the surgical operation, the doctor gave the indication that Mr. Idogo will <u>pull through</u>.', null, '["be maimed","survive","die","be revived"]', 2, 'Pull through = survive; opposite = die.', true, '2026-10-24 07:21:19.174', '2026-10-24 07:21:19.174', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. After the surgical operation, the doctor gave the indication that Mr. Idogo will <u>pull through</u>.', '["be maimed","survive","die","be revived"]', 'Pull through = survive; opposite = die.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8314a5fc-6ec3-4a15-9252-cfb1ec034059', 'Physics', 'JAMB', null, 2026, null, 'Which of the following is true? I. Triboelectric charging is one of the oldest form of charging II. Ebonite rod rubbed with silk forms positive charges III. charging by friction can also be called Triboelectric Charging IV. Triboelectric charging is charging via contact V. Electroscopes can be charged only by friction', null, '["I, III and IV only","I, II and III only","II, III and V only","I, II, III, IV and V"]', 0, 'Statements I, III, and IV are true. Statement II is false because ebonite rod rubbed with fur (not silk) becomes negatively charged. Statement V is false because electroscopes can be charged by induction, not only by friction.', true, '2026-09-10 10:58:05.255', '2026-09-10 10:58:05.255', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('831c22a1-3df8-4c75-9fb6-14ade5322488', 'Biology', 'JAMB', null, 2026, null, 'The nitrogenous substance that is excreted by birds in order to conserve water is', null, '["ammonia","urea","uric acid","nitric acid"]', 2, 'Birds excrete uric acid to conserve water. Uric acid is a nitrogenous waste product with low solubility, allowing it to be excreted as a semi-solid paste (white part of bird droppings) with minimal water loss. Ammonia is highly toxic and water-soluble, requiring large amounts of water for excretion. Urea is moderately toxic and water-soluble, requiring moderate water. Uric acid is the most water-efficient nitrogenous waste, making it ideal for birds, insects, and desert reptiles. Nitric acid is not a nitrogenous waste product in animals.', true, '2026-09-09 03:18:52.811', '2026-09-09 03:18:52.811', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('831f1384-b6e2-4200-bc98-c7ecfa1a4e2e', 'English Language', 'JAMB', null, 2007, null, 'No matter to whom I <u>__________</u> nobody in the crowd had a clue to what was going on', null, '["discussed","asked","turned","contacted"]', 2, 'Correct form: turned.', true, '2026-10-24 07:21:42.51', '2026-10-24 07:21:42.51', null, null, null, 'No matter to whom I <u>__________</u> nobody in the crowd had a clue to what was going on', '["discussed","asked","turned","contacted"]', 'Correct form: turned.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('83456143-074d-44b2-a0bd-a7130d310909', 'Economics', 'JAMB', null, 2026, null, 'Which of the following is NOT a function of marketing boards in Nigeria?', null, '["Marketing of farm produce","Fixing of prices for farm produce","Grading of farm produce","Importation of farm produce"]', 3, 'Marketing boards do not import farm produce.', true, '2026-09-12 11:01:31.54', '2026-09-12 11:01:31.54', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('83523770-cec5-4ee7-af8d-fee2d764d981', 'Economics', 'JAMB', null, 2026, null, 'Budget deficit of the government is financed by', null, '["Borrowing","Stealing","Printing more money","Lending"]', 0, 'Budget deficit is typically financed by borrowing.', true, '2026-09-12 11:00:55.057', '2026-09-12 11:00:55.057', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8352dea1-bd81-4ff0-9ec2-b6c9e5465e53', 'General Mathematics', 'JAMB', null, 2026, null, 'A cuboid has a diagonal of length 9cm and a square base of side 4cm. What is its height?', null, '["9cm","65cm","4√2cm","7cm","6.5cm"]', 3, 'Diagonal of cuboid = √(l²+w²+h²) = √(4²+4²+h²) = √(32+h²) = 9. 32+h² = 81. h² = 49. h = 7cm.', true, '2026-09-10 10:48:20.227', '2026-09-10 10:48:20.227', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('83576bd9-371b-443d-8d3b-982ba4018e7e', 'Chemistry', 'JAMB', null, 2026, null, 'Which of the following elements would most likely form an acidic oxide?', null, '["Sodium","Calcium","Sulfur","Magnesium"]', 2, 'Sulfur is a non-metal and forms acidic oxides such as SO₂ and SO₃. When dissolved in water, these form sulfurous acid (H₂SO₃) and sulfuric acid (H₂SO₄). Sodium, calcium, and magnesium are metals and form basic oxides.', true, '2026-09-12 09:38:12.327', '2026-09-12 09:38:12.327', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8367852a-aa81-45d0-9ec2-168d8c88965f', 'Economics', 'JAMB', null, 2026, null, 'Which of the following is NOT a measure of central tendency?', null, '["mean","median","Mode","standard deviation"]', 3, 'Standard deviation is NOT a measure of central tendency. It is a measure of dispersion (variability) that shows how spread out data is around the mean. Measures of central tendency include mean, median, and mode, which describe the center or typical value of a data set. Standard deviation measures the average distance of each data point from the mean.', true, '2026-09-10 10:41:20.616', '2026-09-10 10:41:20.616', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8367ff71-8305-4897-b532-3f12f5e895d2', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Even though there is no obvious riot on the campus, the atmosphere is <u>restive</u>.', null, '["quiet","chaotic","restless","tense"]', 2, 'Restive = restless.', true, '2026-10-24 01:01:49.392', '2026-10-24 01:01:49.392', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Even though there is no obvious riot on the campus, the atmosphere is <u>restive</u>.', '["quiet","chaotic","<u>restless</u>","tense"]', '<b>Restive</b> = <b>restless</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8379b43a-b642-4888-b733-cb5357f97bf7', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Bola always looks <u>sober</u>.', null, '["excited","worried","serious","hapless"]', 0, 'Sober = calm/serious; opposite = excited.', true, '2026-10-24 07:21:26.947', '2026-10-24 07:21:26.947', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Bola always looks <u>sober</u>.', '["excited","worried","serious","hapless"]', 'Sober = calm/serious; opposite = excited.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('837e30f6-efaa-4eee-9688-0242fe0640f3', 'Chemistry', 'JAMB', null, 2026, null, 'Which of the following salts will hydrolyze in water to produce an acidic solution?', null, '["NaCl","NH₄Cl","Na₂CO₃","KNO₃"]', 1, 'Ammonium chloride (NH4Cl) is a salt formed from a weak base and strong acid, undergoing cation hydrolysis to produce an acidic solution.', true, '2026-09-09 17:12:48.664', '2026-09-09 17:12:48.664', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('83a2e94e-2e92-4daf-9528-aaadcf8bd089', 'Chemistry', 'JAMB', null, 2026, null, 'Combustion is accompanied by i) heat ii) light iii) power iv) energy', null, '["I only","ii only","iii and iv","I and ii"]', 3, 'Combustion is accompanied by heat and light.', true, '2026-09-12 11:36:18.435', '2026-09-12 11:36:18.435', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('83a310fd-c7fc-4c83-a8e2-4239bfe8ed65', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). If Garba had listened to advice, <u>he would not have had to be rushed to the hospital</u>.', null, '["deliberately desired to be rushed","was in position to have prevented the need to be rushed","was rushed against his wish","was given a cheque, but preferred to go"]', 1, 'Third conditional = could have prevented.', true, '2026-10-24 01:02:04.476', '2026-10-24 01:02:04.476', null, null, null, '(Choose the most appropriate interpretation). If Garba had listened to advice, <u>he would not have had to be rushed to the hospital</u>.', '["deliberately desired to be rushed","<u>was in position to have prevented the need to be rushed</u>","was rushed against his wish","was given a cheque, but preferred to go"]', 'Third conditional = <b>could have prevented</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('83a41768-fa17-44a7-80a7-fc1e880b927d', 'Literature in English', 'JAMB', null, 2026, null, 'The imagery in Night contributes mainly to the creation of', null, '["Suspense and tension","Comic relief","Romantic atmosphere","Didactic instruction"]', 0, 'The imagery creates suspense and tension.', true, '2026-09-12 11:12:06.128', '2026-09-12 11:12:06.128', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('83a8cd10-348c-468b-9e3a-a3396773d5b7', 'English Language', 'JAMB', null, 2007, null, 'The jury <u>_______</u> unable to agree on a verdict after three days of deliberation.', null, '["is","are","was","have"]', 1, 'Jury as individuals disagree â†’ are.', true, '2026-10-24 01:02:16.587', '2026-10-24 01:02:16.587', null, null, null, 'The jury <u>_______</u> unable to agree on a verdict after three days of deliberation.', '["is","<u>are</u>","was","have"]', '<b>Jury</b> as individuals <b>disagree</b> â†’ <b>are</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('83ab70c6-79fc-4e2f-b54f-4e065c6a5ec3', 'English Language', 'JAMB', null, 2024, null, '5', null, '["enforced","coerced","persuaded","commanded"]', 2, 'Workers are not easily persuaded (convinced) to strike.', true, '2026-09-18 10:17:48.776', '2026-09-18 10:17:48.776', '274e150d-fca1-4c72-9c33-e5e119534874', 5, 'CLOZE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('83bff066-e957-4035-9315-d0f44e209cc4', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in opposite to the word(s) or phrase in italics and underlined. It is <u>inconceivable</u> that the sun shone in the night.', null, '["credible","unthinkable","impossible","contestable"]', 0, 'Inconceivable = unbelievable; opposite = credible.', true, '2026-10-24 07:21:29.671', '2026-10-24 07:21:29.671', null, null, null, 'Choose the option nearest in opposite to the word(s) or phrase in italics and underlined. It is <u>inconceivable</u> that the sun shone in the night.', '["credible","unthinkable","impossible","contestable"]', 'Inconceivable = unbelievable; opposite = credible.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('83c7283f-1298-4057-ba75-e337c82041b2', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Who among the following volunteered to dress the remains of Jesus Christ for burial?', null, '["The Ethiopian Eunuch","Simon of Cyrene","Joseph of Arimathea","Felix the Governor","Caesar the Emperor"]', 2, 'Joseph of Arimathea took Jesus'' body for burial.', true, '2026-09-12 10:42:14.037', '2026-09-12 10:42:14.037', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('83c92224-a1fa-4624-8be0-0ed1931859e3', 'Physics', 'JAMB', null, 1998, null, 'Which of the following can be used to reduce local action in a Leclanché cell?', null, '["A carbon rod as the positive pole.","Pure zinc as the negative pole.","Potassium permanganate solution in contact with the positive pole.","Common salt solution."]', 1, 'Local action is caused by impurities in the zinc forming tiny cells. Using pure (or amalgamated) zinc reduces it.', true, '2026-10-12 19:15:46.43', '2026-10-12 19:15:46.43', null, null, null, 'Which of the following can be used to reduce local action in a Leclanché cell?', '["A carbon rod as the positive pole.","Pure zinc as the negative pole.","Potassium permanganate solution in contact with the positive pole.","Common salt solution."]', 'Local action is caused by impurities in the zinc forming tiny cells. Using pure (or amalgamated) zinc reduces it.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('83c92ac3-03c6-4e3f-8149-9252e78ef7e3', 'Government', 'JAMB', null, 2026, null, 'Which Nigerian leader nationalized British Petroleum in retaliation for UK support of Biafra?', null, '["Aguiyi Ironsi","Olusegun Obasanjo","Yakubu Gowon","Murtala Muhammed"]', 3, 'Murtala Muhammed nationalized British Petroleum in retaliation for UK support of Biafra.', true, '2026-09-12 11:24:44.317', '2026-09-12 11:24:44.317', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('83e36db3-08f6-40ec-b4e1-87d95d04eb63', 'Government', 'JAMB', null, 2026, null, 'A vote of no confidence means', null, '["the same as impeachment in a presidential system","the ability of the head of state to dissolve the parliament when collective responsibility fails to hold","the act of showing disapproval to the new prime minister having breached the collective responsibility doctrine","the disapproval with dismissal in effect, the ministers and its heads"]', 3, 'A vote of no confidence means disapproval leading to dismissal of ministers.', true, '2026-09-12 11:24:53.813', '2026-09-12 11:24:53.813', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8402fd8f-3326-4f1d-90f6-7ccd8bb6bb58', 'English Language', 'JAMB', null, 2007, null, 'The police report was <u>__________</u> to that of the eye witness.', null, '["contrary","inconsistent","different","congruent"]', 0, 'Correct collocation: contrary to.', true, '2026-10-24 07:21:42.811', '2026-10-24 07:21:42.811', null, null, null, 'The police report was <u>__________</u> to that of the eye witness.', '["contrary","inconsistent","different","congruent"]', 'Correct collocation: contrary to.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('840fc126-ac6f-4ac2-b5c2-278ed7611c6d', 'Literature in English', 'JAMB', null, 2026, null, 'The character of Lucas is best described as a', null, '["Static character unaffected by events","Tragic hero whose flaw leads to his downfall","Dynamic character who evolves through adversity","Comic figure designed to entertain"]', 2, 'Lucas is a dynamic character who evolves through adversity.', true, '2026-09-12 11:04:58.405', '2026-09-12 11:04:58.405', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('84203a2a-27a5-46aa-996c-78738c7f257b', 'Physics', 'JAMB', null, 2004, null, 'An a.c. circuit of e.m.f. 12 V has a resistor of resistance 8 Ω connected in series to an inductor of inductive reactance 16 Ω and a capacitor of capacitive reactance 10 Ω. The current flowing in the circuit is', null, '["1.4 A","14.0 A","1.2 A","12.0 A"]', 2, 'Net reactance = 16 - 10 = 6 Ω. Z = √(8² + 6²) = 10 Ω. I = 12/10 = 1.2 A.', true, '2026-10-12 19:15:59.462', '2026-10-12 19:15:59.462', null, null, null, 'An a.c. circuit of e.m.f. 12 V has a resistor of resistance 8 Ω connected in series to an inductor of inductive reactance 16 Ω and a capacitor of capacitive reactance 10 Ω. The current flowing in the circuit is', '["1.4 A","14.0 A","1.2 A","12.0 A"]', 'Net reactance = 16 - 10 = 6 Ω. Z = √(8<sup>2</sup> + 6<sup>2</sup>) = 10 Ω. I = 12/10 = 1.2 A.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8425c31f-395c-4e81-aa2b-8d6a87c73e03', 'Physics', 'JAMB', null, 1984, null, 'Which of the following statements is (are) NOT correct?
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('842cc678-fa45-41f5-88a0-b1454d07bdc1', 'Biology', 'JAMB', null, 2001, null, 'The jointed structure in insects that bears organs which are sensitive to touch, smell and vibration is the', null, '["antenna","abdomen","maxilla","labium"]', 0, 'The antenna is the jointed sensory structure in insects.', true, '2026-10-12 20:59:28.224', '2026-10-12 20:59:28.224', null, null, null, 'The jointed structure in insects that bears organs which are sensitive to touch, smell and vibration is the', '["antenna","abdomen","maxilla","labium"]', 'The antenna is the jointed sensory structure in insects.', '{"bold":["antenna"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8445dbd7-b734-4c59-a070-81d20303e683', 'Literature in English', 'JAMB', null, 2026, null, '………………………….is a story written on life journey', null, '["Picaresque novel","Bildungsroman","Epistolary novel","Historical novel"]', 1, 'A Bildungsroman is a story written on a life journey, specifically focusing on the moral and psychological growth of the protagonist from youth to adulthood. The term comes from German, meaning ''formation novel.'' A picaresque novel features a rogue, an epistolary novel is told through letters, and a historical novel is set in a past era.', true, '2026-09-10 10:47:54.806', '2026-09-10 10:47:54.806', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8446c6d3-7c3f-4774-8abf-9f9aea782663', 'Biology', 'JAMB', null, 2026, null, 'The correct increasing order of size for the cell components responsible for heredity is', null, '["chromosome, DNA, nucleus, gene","DNA, gene, chromosome, nucleus","chromosome, nucleus, DNA, gene","DNA, gene, nucleus, chromosome"]', 1, 'The correct increasing order of size is: DNA → gene → chromosome → nucleus. DNA is the smallest component, containing genes. Genes are segments of DNA. Chromosomes are made of DNA and proteins. The nucleus contains the chromosomes. This hierarchy is fundamental to understanding genetics. A gene is a specific sequence of DNA that codes for a protein. Chromosomes are the structures that carry genes.', true, '2026-09-09 03:19:29.875', '2026-09-09 03:19:29.875', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('844babe6-b392-4d5a-9a19-2dc3141b2476', 'English Language', 'JAMB', null, 2024, null, 'Unlike the academic who returned empty-handed, Riike was able to', null, '["Buy two houses in Ibadan in less than three years","Build a school in her hometown","Return to Nigeria with huge savings","Fund multiple businesses back home"]', 0, 'Riike was able to buy two houses in Ibadan in less than three years.', true, '2026-09-18 09:43:02.695', '2026-09-18 09:43:02.695', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('845b0f4e-5540-46fa-a7c1-083eb6a011e6', 'Physics', 'JAMB', null, 1993, null, 'A field that results from the contact of a positively charged ball with the inner wall of an uncharged hollow conducting sphere is', null, '["Inside the sphere","On the surface of the ball","Inside and outside the sphere","Outside the sphere."]', 3, 'All the charge moves to the outer surface of the conducting sphere. There is no field inside the hollow conductor, so the field exists only outside.', true, '2026-10-12 19:15:38.08', '2026-10-12 19:15:38.08', null, null, null, 'A field that results from the contact of a positively charged ball with the inner wall of an uncharged hollow conducting sphere is', '["Inside the sphere","On the surface of the ball","Inside and outside the sphere","Outside the sphere."]', 'All the charge moves to the outer surface of the conducting sphere. There is no field inside the hollow conductor, so the field exists only outside.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('845f5c38-ea5d-4435-9283-f9373a85a04a', 'Physics', 'JAMB', null, 1984, null, 'Which of the following may be found in light nuclei?
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8465a269-1e28-482b-b3f0-e3d5964d059b', 'Literature in English', 'JAMB', null, 2026, null, 'The poet compares old age to', null, '["a shadowy evening","a cloudless dawn","a raging storm","a cold winter"]', 0, 'Old age is compared to a shadowy evening.', true, '2026-09-12 11:10:57.518', '2026-09-12 11:10:57.518', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('846ced09-c1b4-4463-83c5-32b5f8482e25', 'Chemistry', 'JAMB', null, 2026, null, 'Which organic compound belongs to the alkene series?', null, '["C₂H₆","C₃H₆","C₂H₂","C₃H₈"]', 1, 'C₃H₆ (propene) belongs to the alkene series with the general formula CₙH₂ₙ. It contains a carbon-carbon double bond. C₂H₆ and C₃H₈ are alkanes (CₙH₂ₙ₊₂), and C₂H₂ is an alkyne (CₙH₂ₙ₋₂).', true, '2026-09-12 09:38:15.437', '2026-09-12 09:38:15.437', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8481d864-d2b3-40e1-9d75-9342c6a436e9', 'Biology', 'JAMB', null, 2010, null, 'Chemosynthetic organisms are capable of manufacturing their food from simple inorganic substances through the process of', null, '["oxidation","denitrification","reduction","phosphorylation"]', 0, 'Chemosynthetic organisms manufacture food through oxidation.', true, '2026-10-12 20:59:40.327', '2026-10-12 20:59:40.327', null, null, null, 'Chemosynthetic organisms are capable of manufacturing their food from simple inorganic substances through the process of', '["oxidation","denitrification","reduction","phosphorylation"]', 'Chemosynthetic organisms manufacture food through oxidation.', '{"bold":["oxidation"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8487ddae-c13b-4bee-973c-77ecf72d1370', 'Physics', 'JAMB', null, 1998, null, 'A platinum resistance thermometer records 3.0 Ω at 0 °C and 8.0 Ω at 100 °C. If it records 6.0 Ω in a certain environment, the temperature of the medium is', null, '["80 °C","60 °C","50 °C","30 °C"]', 1, 'θ = (6.0 - 3.0)/(8.0 - 3.0) x 100 = 3/5 x 100 = 60 °C.', true, '2026-10-12 19:15:45.355', '2026-10-12 19:15:45.355', null, null, null, 'A platinum resistance thermometer records 3.0 Ω at 0 °C and 8.0 Ω at 100 °C. If it records 6.0 Ω in a certain environment, the temperature of the medium is', '["80 °C","60 °C","50 °C","30 °C"]', 'θ = (6.0 - 3.0)/(8.0 - 3.0) x 100 = 3/5 x 100 = 60 °C.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('84894d37-dddf-4061-9c45-8b5d82cbe150', 'English Language', 'JAMB', null, 2024, null, 'Choose the option opposite in meaning to the word or phrase in italics: She said the experience was harrowing', null, '["educating","frightening","strange","pleasant"]', 3, '"Harrowing" means distressing; the opposite is "pleasant."', true, '2026-09-18 09:43:02.883', '2026-09-18 09:43:02.883', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8489d85c-8cda-4949-9ba0-ecaf7f638b06', 'Physics', 'JAMB', null, 1999, null, 'Four cells each of e.m.f. 1.5 V and internal resistance of 4 Ω are connected in parallel. What is the effective e.m.f. and internal resistance of the combination?', null, '["6.0 V, 16 Ω","6.0 V, 1 Ω","1.5 V, 4 Ω","1.5 V, 1 Ω"]', 3, 'Identical cells in parallel give the same e.m.f. (1.5 V) and the internal resistance divides by the number of cells: 4/4 = 1 Ω.', true, '2026-10-12 19:15:47.984', '2026-10-12 19:15:47.984', null, null, null, 'Four cells each of e.m.f. 1.5 V and internal resistance of 4 Ω are connected in parallel. What is the effective e.m.f. and internal resistance of the combination?', '["6.0 V, 16 Ω","6.0 V, 1 Ω","1.5 V, 4 Ω","1.5 V, 1 Ω"]', 'Identical cells in parallel give the same e.m.f. (1.5 V) and the internal resistance divides by the number of cells: 4/4 = 1 Ω.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('84908838-8ac9-4cf0-b002-7a0c407aa0dd', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. In the latter part of his life, the famous soldier showed signs of <u>youthfulness</u>.', null, '["bravery","vitality","energy","senility"]', 3, 'Youthfulness; opposite = senility.', true, '2026-10-24 07:21:22.507', '2026-10-24 07:21:22.507', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. In the latter part of his life, the famous soldier showed signs of <u>youthfulness</u>.', '["bravery","vitality","energy","senility"]', 'Youthfulness; opposite = senility.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('84935641-1cb3-4b75-ab37-67d4db67e809', 'testing', 'JAMB', null, 2024, null, 'Neither of the two explanations.... convincing', null, '["Are","Were","Is","Have been"]', 1, '''Neither'' is singular and takes ''is''.', true, '2026-10-31 16:48:52.342', '2026-10-31 16:48:52.342', null, null, null, 'Neither of the two explanations.... convincing', '["Are","Were","Is","Have been"]', '''Neither'' is singular and takes ''is''.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('84947cfa-b92d-4474-ba10-5e960a26aaee', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). He works long hours collecting trash to <u>eke out a livelihood</u>.', null, '["try a living","struggle for a living","make a living","carve out a living"]', 2, '''Eke out a livelihood'' = make a living.', true, '2026-10-24 01:04:17.768', '2026-10-24 01:04:17.768', null, null, null, '(Choose the most appropriate interpretation). He works long hours collecting trash to <u>eke out a livelihood</u>.', '["try a living","struggle for a living","<u>make a living</u>","carve out a living"]', '''<b>Eke out a livelihood</b>'' = <b>make a living</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('849490dc-0f48-42a0-a64e-f90976935deb', 'Physics', 'JAMB', null, 1993, null, 'A current of 100 mA passes through a conductor for 2 minutes. The quantity of electricity transported is', null, '["200 C","50 C","12 C","0.02 C"]', 2, 'Q = It = 0.1 x 120 = 12 C.', true, '2026-10-12 19:15:38.348', '2026-10-12 19:15:38.348', null, null, null, 'A current of 100 mA passes through a conductor for 2 minutes. The quantity of electricity transported is', '["200 C","50 C","12 C","0.02 C"]', 'Q = It = 0.1 x 120 = 12 C.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('84a31d98-3c32-45ff-9a52-aeb69aeb4d48', 'Physics', 'JAMB', null, 2002, null, 'Vibrations in a stretched spring cannot be polarized because they are', null, '["Longitudinal waves","Mechanical waves","Stationary waves","Transverse waves."]', 0, 'Only transverse waves can be polarized. Waves in a spring (compressions and rarefactions) are longitudinal, so they cannot.', true, '2026-10-12 19:15:53.869', '2026-10-12 19:15:53.869', null, null, null, 'Vibrations in a stretched spring cannot be polarized because they are', '["Longitudinal waves","Mechanical waves","Stationary waves","Transverse waves."]', 'Only transverse waves can be polarized. Waves in a spring (compressions and rarefactions) are longitudinal, so they cannot.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('84a3ae23-90d8-45a0-96a1-c0f05369f56e', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. All through his years in public office, he found his father''s advice <u>invaluable</u>.', null, '["priceless","hopeless","worthless","helpful"]', 2, 'Invaluable = priceless; opposite = worthless.', true, '2026-10-24 07:21:15.667', '2026-10-24 07:21:15.667', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. All through his years in public office, he found his father''s advice <u>invaluable</u>.', '["priceless","hopeless","worthless","helpful"]', 'Invaluable = priceless; opposite = worthless.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('84a658ff-ce80-462c-8402-76296d1620c0', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Despite increasingly <u>punitive</u> laws against hemp smoking, it is still rising at an alarming rate.', null, '["devastating","exemplary","barbaric","severe","satisfactory"]', 3, 'Punitive = severe.', true, '2026-10-24 01:03:53.921', '2026-10-24 01:03:53.921', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Despite increasingly <u>punitive</u> laws against hemp smoking, it is still rising at an alarming rate.', '["devastating","exemplary","barbaric","<u>severe</u>","satisfactory"]', '<b>Punitive</b> = <b>severe</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('84a83aef-a062-41ce-9f70-d3dbd63efdf6', 'English Language', 'JAMB', null, 2007, null, 'You, who <u>------------</u> convicted, should appeal.', null, '["was","are","has been","is"]', 1, '''Who'' â†’ you â†’ are.', true, '2026-10-24 01:02:15.554', '2026-10-24 01:02:15.554', null, null, null, 'You, who <u>------------</u> convicted, should appeal.', '["was","<u>are</u>","has been","is"]', '''<b>Who</b>'' â†’ <b>you</b> â†’ <b>are</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('84a900ad-d562-40ba-a931-54a2433be6c7', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. There is much <u>indifference</u> in his behaviour.', null, '["concern","nonchalance","willingness","inconsistency"]', 0, 'Indifference = unconcern; opposite = concern.', true, '2026-10-24 07:21:19.997', '2026-10-24 07:21:19.997', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. There is much <u>indifference</u> in his behaviour.', '["concern","nonchalance","willingness","inconsistency"]', 'Indifference = unconcern; opposite = concern.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('84abd721-79f8-450c-b4d7-68cb85a6438f', 'Economics', 'JAMB', null, 2026, null, 'ECOWAS full form is', null, '["Economic Cooperation of West African States","Economic Community of West African States","European Community of Western African States","Economic Committee of Western African States"]', 1, 'ECOWAS stands for Economic Community of West African States.', true, '2026-09-12 10:59:52.988', '2026-09-12 10:59:52.988', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('84ad5791-4b70-4724-8cf4-8475281145ef', 'English Language', 'JAMB', null, 2007, null, 'The hunter brought home <u>__________</u> antelope.', null, '["alive","a life","a live","a living"]', 2, 'Correct form: a live antelope.', true, '2026-10-24 07:21:32.842', '2026-10-24 07:21:32.842', null, null, null, 'The hunter brought home <u>__________</u> antelope.', '["alive","a life","a live","a living"]', 'Correct form: a live antelope.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('84bf74b2-fde0-43a0-8f8f-4c7b62340b97', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'According to John, the accusation the Jews leveled against Jesus before Pilate was that He was...', null, '["a blasphemer","an evil doer","an impostor","perverted"]', 1, 'John 18:30 records the Jews answering Pilate: ''If He were not an evildoer / malefactor, we would not have delivered Him up to you.''', true, '2026-09-09 17:18:27.495', '2026-09-09 17:18:27.495', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('84c950ea-078c-4796-a585-264505da8873', 'Biology', 'JAMB', null, 2002, null, 'In which of the following groups of fruits is the pericarp inseparable from the seed coat?', null, '["Nut","Follicle","Cypsela","Caryopsis"]', 3, 'In caryopsis the pericarp is inseparable from the seed coat.', true, '2026-10-12 20:59:31.525', '2026-10-12 20:59:31.525', null, null, null, 'In which of the following groups of fruits is the pericarp inseparable from the seed coat?', '["Nut","Follicle","Cypsela","Caryopsis"]', 'In caryopsis the pericarp is inseparable from the seed coat.', '{"bold":["caryopsis"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('84cc5d8a-3797-4044-ad11-b9b41dffe14c', 'Biology', 'JAMB', null, 2026, null, 'Which of the following is true of the children of a haemophilic man who marries a woman that is not haemophilic and does not carry the trait?', null, '["All their sons will be haemophilic","All their daughters will be haemophilic","All their daughters will be carriers","All their sons will be carriers"]', 2, 'All their daughters will be carriers. Haemophilia is an X-linked recessive disorder. The father has genotype X^h Y (affected). The mother is normal and not a carrier, so she has genotype X^H X^H. Daughters will inherit X^h from the father and X^H from the mother, making them carriers (X^H X^h). Sons will inherit Y from the father and X^H from the mother, making them normal. None of the children will have the condition, but all daughters will be carriers.', true, '2026-09-09 03:19:31.01', '2026-09-09 03:19:31.01', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('84d22be4-0616-4fd6-a834-e3549cb1011c', 'Biology', 'JAMB', null, 2004, null, 'The breakdown of fats and oils into simpler absorbable compounds is catalyzed by the group of enzymes called', null, '["lipases","hydrolases","amylases","peptidases"]', 0, 'Lipases break down fats and oils.', true, '2026-10-12 20:59:34.862', '2026-10-12 20:59:34.862', null, null, null, 'The breakdown of fats and oils into simpler absorbable compounds is catalyzed by the group of enzymes called', '["lipases","hydrolases","amylases","peptidases"]', 'Lipases break down fats and oils.', '{"bold":["Lipases"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('84d99ff2-d4dd-4426-a9b4-194d648d19c8', 'English Language', 'JAMB', null, 2007, null, 'We must not take with us the feelings of inadequacy <u>--------</u> experienced during our preparation for the debate', null, '["that were","those were","that was","that is"]', 0, '''Feelings'' plural â†’ that were.', true, '2026-10-24 01:04:29.442', '2026-10-24 01:04:29.442', null, null, null, 'We must not take with us the feelings of inadequacy <u>--------</u> experienced during our preparation for the debate', '["<u>that were</u>","those were","that was","that is"]', '''<b>Feelings</b>'' plural â†’ <b>that were</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('84def6d9-ff8d-4f9f-843d-1e15a54c1bc3', 'Government', 'JAMB', null, 2026, null, 'The delineation of constituencies is a major duty of the', null, '["electoral commission","boundary commission","legislature","electorate"]', 1, 'The boundary commission delineates constituencies.', true, '2026-09-12 11:24:12.822', '2026-09-12 11:24:12.822', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('84e58076-a4f8-4f7f-add3-d8f31cf382cc', 'Physics', 'JAMB', null, 2026, null, 'The ability of the human eye to focus object on the retina is referred to as the power of', null, '["interference","diffraction","accommodation","superposition"]', 2, 'The ability of the human eye to focus objects on the retina is called accommodation. This is achieved by the ciliary muscles changing the shape (curvature) of the eye lens. When viewing near objects, the lens becomes thicker; for distant objects, it becomes thinner.', true, '2026-09-10 10:56:39.297', '2026-09-10 10:56:39.297', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('84e8d4d2-4fed-44a8-ab9e-89c18edf7b34', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'God blessed and hallowed the seventh day because', null, '["it was the day he rested from creation","it was the day he created man","he wanted it to be a day of worship","he saw that all he had created was good"]', 0, 'God blessed and hallowed the seventh day because on it He rested from all His work of creation. The seventh day became the Sabbath, a day of rest.', true, '2026-09-12 09:45:56.547', '2026-09-12 09:45:56.547', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('84eeb838-c8a6-4a7f-8eac-db6c43179930', 'Yoruba', 'JAMB', null, 2007, null, 'Ka àwôn àyókà ìsàlẹ yìí, Kí o sì dáhùn àwòn ìbéèrè tí ó tẹlé wòn. Babárində nífèè Föláyadé púpõ. Föláyadé náà sì rèé, òrékelèwà òmõge, çlèyinjú-çgè, çlèrin-ín èyc! Òun náà sì dá ìfè yìí padà pèlú ayõ àti ìdùnnú. Bùgbòn bàbá Föláyadé ni igì wòròkò tí p da iná rú nídìí òrõ yìí: ó kórìíra Babárində nítorí pé ó kà á sí òtòyì ènìyàn. Bèè òmólójú rè sì ni Föláyadé í ÿe. Baba gbàgbò pé bí òmò òun bá fè Babárində, inú ìyà ni tòkòtaya wòn yóò wà. Kì í kúkú í ÿe pé Babárində jë tálákà bëë náà: ó p ÿiyë gëgë bí òÿìÿë kékere nílë-iÿë plá kan, bëë nì kò sì tòrò jç, ÿùgbòn ó kàn jë pé kò lówò tó Ayõkúnlé Atáyëwá, oníÿòwò kan tí baba Föláyadé fë kí òmò rë fë. Ìyá Föláyadé náà sì rèé, ìbi tí òkò rë bá të sí nì òun náà p të sí. Bé ojúbõrõ kò ni a sì fì p gbòmò lòwò ëkùrò: àwòn òbí Föláyadé fì toògùn-toògùn fa òmò wòn fún Ayõkúnlé Atáyëwá ÿaya. Babárində banùjë nídìí òrõ yìí, ëdùn-òkàn sì ni Föláyadé gbé wòlé òkò. Òjò þ gori ójò, òdún þ gori òdún, bèè ni ìgbà sì þ rékòjà lo. Fòláyadé bí akò, ó bi abo nílé òkò, ÿúgbòn nykan ò lò déédé fún òkò rè mò lënu òwò rè. Àwòn oníbodè ti gbèsè lé òjà rè tó jè çgbëlègbè náírà. Ó yáwó nílé-ìfowópamò, ÿúgbòn kò rí i san padà. Àwòn báykì bá gba ilé, òkò àti àwòn dúkiá rè mìíràn. Àtijç-àtimu wá di ìjòro fún òun àti ìyàwó rè àti àwon òmò wòn pèlú. Níha kejì, Babárində náà ti gbéyàwó, ó sì tí bímò. Lénu ìyê rê wàyìí, ó ti di ògá, orí sì ti sún un sólá. Àwòn òbí Föláyadé wá p wò sùn- ùn, wòn rí i bí ìgbé-ayé Ayõkúnlé Atáyéwá ÿe p lò, wòn sì tún wo ti Föláyadé òmò wòn, bákan náà ni wòn sì p gbókèèrè wo ti Babárində bó ÿe p dùn sí i fún un. Wòn wá fika àbámò bónu: ìwájú ò ÿeé lò, èyìn ò sì ÿeé padà sí fún wòn. Babárində, eni tí wòn rò pé kò lè pàgò ló wá dçni tí p kòlé aláruru. Ó wá hàn kedere sí wòn pé çni tí yóò dòlòlà lòla, orí ló mõ òn. Àwòn òbí Föláyadé kábàámõ ìwà wòn nítorí pé', null, '["ibi ti wòn fojú sí, ònà ò gbabè lò","nykan ò dánmörán fún wòn mò","Babárìndé ti gbéyàwó, ó sì ti bímò","oògùn ti wòn yè kò ÿiyè mò."]', 0, 'Àwòn òbí Föláyadé kábàámõ ìwà wòn nítorí pé ibi ti wòn fojú sí, ònà ò gbabè lò.', true, '2026-10-13 13:23:30.751', '2026-10-13 13:23:30.751', null, null, null, 'Ka àwôn àyókà ìsàlẹ yìí, Kí o sì dáhùn àwòn ìbéèrè tí ó tẹlé wòn. Babárində nífèè Föláyadé púpõ. Föláyadé náà sì rèé, òrékelèwà òmõge, çlèyinjú-çgè, çlèrin-ín èyc! Òun náà sì dá ìfè yìí padà pèlú ayõ àti ìdùnnú. Bùgbòn bàbá Föláyadé ni igì wòròkò tí p da iná rú nídìí òrõ yìí: ó kórìíra Babárində nítorí pé ó kà á sí òtòyì ènìyàn. Bèè òmólójú rè sì ni Föláyadé í ÿe. Baba gbàgbò pé bí òmò òun bá fè Babárində, inú ìyà ni tòkòtaya wòn yóò wà. Kì í kúkú í ÿe pé Babárində jë tálákà bëë náà: ó p ÿiyë gëgë bí òÿìÿë kékere nílë-iÿë plá kan, bëë nì kò sì tòrò jç, ÿùgbòn ó kàn jë pé kò lówò tó Ayõkúnlé Atáyëwá, oníÿòwò kan tí baba Föláyadé fë kí òmò rë fë. Ìyá Föláyadé náà sì rèé, ìbi tí òkò rë bá të sí nì òun náà p të sí. Bé ojúbõrõ kò ni a sì fì p gbòmò lòwò ëkùrò: àwòn òbí Föláyadé fì toògùn-toògùn fa òmò wòn fún Ayõkúnlé Atáyëwá ÿaya. Babárində banùjë nídìí òrõ yìí, ëdùn-òkàn sì ni Föláyadé gbé wòlé òkò. Òjò þ gori ójò, òdún þ gori òdún, bèè ni ìgbà sì þ rékòjà lo. Fòláyadé bí akò, ó bi abo nílé òkò, ÿúgbòn nykan ò lò déédé fún òkò rè mò lënu òwò rè. Àwòn oníbodè ti gbèsè lé òjà rè tó jè çgbëlègbè náírà. Ó yáwó nílé-ìfowópamò, ÿúgbòn kò rí i san padà. Àwòn báykì bá gba ilé, òkò àti àwòn dúkiá rè mìíràn. Àtijç-àtimu wá di ìjòro fún òun àti ìyàwó rè àti àwon òmò wòn pèlú. Níha kejì, Babárində náà ti gbéyàwó, ó sì tí bímò. Lénu ìyê rê wàyìí, ó ti di ògá, orí sì ti sún un sólá. Àwòn òbí Föláyadé wá p wò sùn- ùn, wòn rí i bí ìgbé-ayé Ayõkúnlé Atáyéwá ÿe p lò, wòn sì tún wo ti Föláyadé òmò wòn, bákan náà ni wòn sì p gbókèèrè wo ti Babárində bó ÿe p dùn sí i fún un. Wòn wá fika àbámò bónu: ìwájú ò ÿeé lò, èyìn ò sì ÿeé padà sí fún wòn. Babárində, eni tí wòn rò pé kò lè pàgò ló wá dçni tí p kòlé aláruru. Ó wá hàn kedere sí wòn pé çni tí yóò dòlòlà lòla, orí ló mõ òn. Àwòn òbí Föláyadé kábàámõ ìwà wòn nítorí pé', '["ibi ti wòn fojú sí, ònà ò gbabè lò","nykan ò dánmörán fún wòn mò","Babárìndé ti gbéyàwó, ó sì ti bímò","oògùn ti wòn yè kò ÿiyè mò."]', 'Àwòn òbí Föláyadé kábàámõ ìwà wòn nítorí pé ibi ti wòn fojú sí, ònà ò gbabè lò.', '{"bold":["ibi ti wòn fojú sí, ònà ò gbabè lò"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('84f51561-24b8-455a-97f4-a5127579da8a', 'Economics', 'JAMB', null, 2026, null, 'Which of the following is a money market?', null, '["Commercial banks","Development bank","Stock exchange","Merchant banks"]', 0, 'Commercial banks are part of the money market.', true, '2026-09-12 11:01:19.407', '2026-09-12 11:01:19.407', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8509f7c7-040b-4ef0-89ee-6f9189717d30', 'Literature in English', 'JAMB', null, 2026, null, 'When a story is told in a song and passed down by word of mouth, it is called', null, '["A sonnet","An epic","a ballad","A singer''s story"]', 2, 'It is a ballad.', true, '2026-09-12 11:13:55.156', '2026-09-12 11:13:55.156', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('850ad58f-8250-4ddb-9149-66038e33748d', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. He was not able to <u>withstand</u> the attack from his immediate family.', null, '["survive","overcome","match","resist"]', 3, 'Withstand = resist.', true, '2026-10-24 01:04:08.268', '2026-10-24 01:04:08.268', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. He was not able to <u>withstand</u> the attack from his immediate family.', '["survive","overcome","match","<u>resist</u>"]', '<b>Withstand</b> = <b>resist</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('85168131-0937-44aa-a2d7-616c451980cf', 'Chemistry', 'JAMB', null, 2026, null, 'Which of the following is not true about benzoic acid', null, '["it''s aromatic in nature","it can be manufactured from methyl benzene","it has molecular formula C₆H₆COOH","it sublime readily"]', 3, 'Benzoic acid does not sublime readily.', true, '2026-09-12 11:36:09.033', '2026-09-12 11:36:09.033', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('851c40cc-913f-425d-8d86-180ce61f76b7', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Adewale''s arrival always triggers a media <u>frenzy</u>', null, '["violence","agitation","calmness","excitement"]', 2, 'Frenzy = excitement; opposite = calmness.', true, '2026-10-24 07:21:30.972', '2026-10-24 07:21:30.972', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Adewale''s arrival always triggers a media <u>frenzy</u>', '["violence","agitation","calmness","excitement"]', 'Frenzy = excitement; opposite = calmness.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('85223c1f-e10c-4f6d-a964-1ff922d4ab81', 'Literature in English', 'JAMB', null, 2026, null, 'In Night, night is primarily presented as a', null, '["Symbol of celebration and rest","Harmless natural occurrence","Mysterious and possibly threatening force","Political metaphor for leadership"]', 2, 'Night is presented as a mysterious and possibly threatening force.', true, '2026-09-12 11:09:56.68', '2026-09-12 11:09:56.68', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8533f016-3fdc-400a-9900-0d8e5fcd42b3', 'Biology', 'JAMB', null, 2026, null, 'A flower with inferior ovary is said to be', null, '["perigynous","epigynous","hypogynous","progynous"]', 1, 'A flower with an inferior ovary (ovary below the attachment point of other floral parts) is described as epigynous. In epigynous flowers, the ovary is completely enclosed by the receptacle, and the sepals, petals, and stamens appear to arise from above the ovary. Perigynous flowers have a superior ovary with floral parts around the ovary on a cup-shaped receptacle. Hypogynous flowers have a superior ovary with floral parts below the ovary. Progynous is not a standard floral position term. Examples of epigynous flowers include apple, cucumber, and sunflower.', true, '2026-09-09 03:18:40.229', '2026-09-09 03:18:40.229', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8539c510-3de7-4df9-af02-a36bf2a83ce9', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. His textile business deals are <u>in gross</u>.', null, '["wholesale","imported","retailed","exported"]', 2, 'In gross = wholesale; opposite = retailed.', true, '2026-10-24 07:21:16.588', '2026-10-24 07:21:16.588', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. His textile business deals are <u>in gross</u>.', '["wholesale","imported","retailed","exported"]', 'In gross = wholesale; opposite = retailed.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('853f5afe-8b2f-4453-91e7-a99c946a6b50', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. <u>When the chips are down</u>, we will know those who have the courage to stand.', null, '["When we get to a crisis point","In the final analysis","When the blocks are lowered","When we get to the end of the road"]', 0, 'When the chips are down = at a crisis point.', true, '2026-10-24 01:04:01.084', '2026-10-24 01:04:01.084', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. <u>When the chips are down</u>, we will know those who have the courage to stand.', '["<u>When we get to a crisis point</u>","In the final analysis","When the blocks are lowered","When we get to the end of the road"]', '<b>When the chips are down</b> = <b>at a crisis point</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('854403ee-d1bb-4bc9-a730-3ec3122eea8f', 'Yoruba', 'JAMB', null, 2002, null, 'Ìwé Abìkù S’olòògùn D’èké ni ìbèèrè 38-40 dá lé. Kí ni Ökánlàwòn pè ní obì àwòn kápsèlò?', null, '["Ökö","Ilé","Oögün","Owó."]', 3, 'Owó ni Ökánlàwòn pè ní obì àwòn kápsèlò.', true, '2026-10-13 13:22:40.164', '2026-10-13 13:22:40.164', null, null, null, 'Ìwé Abìkù S’olòògùn D’èké ni ìbèèrè 38-40 dá lé. Kí ni Ökánlàwòn pè ní obì àwòn kápsèlò?', '["Ökö","Ilé","Oögün","Owó."]', 'Owó ni Ökánlàwòn pè ní obì àwòn kápsèlò.', '{"bold":["Owó"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8546fb86-03a3-42b1-9058-a60b90cb5d47', 'Chemistry', 'JAMB', null, 2026, null, 'A solution is prepared by dissolving 5.3 g of Na₂CO₃ in 250 cm³ of solution. Calculate its concentration.', null, '["0.10 mol/dm³","0.20 mol/dm³","0.25 mol/dm³","0.50 mol/dm³"]', 1, 'Molar mass of Na₂CO₃ = 106 g/mol. Moles = 5.3/106 = 0.05 mol. Volume = 0.25 dm³. Concentration = 0.05/0.25 = 0.20 mol/dm³.', true, '2026-09-12 11:35:49.495', '2026-09-12 11:35:49.495', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('85499a1e-4f8a-4f1f-9e02-0a5ad9dd5c26', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. A number of people impersonating tax officials were <u>arraigned</u> before the Chief Magistrate this morning.', null, '["arranged","paraded","moved","brought"]', 3, 'Arraigned = brought before a court.', true, '2026-10-24 01:01:45.738', '2026-10-24 01:01:45.738', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. A number of people impersonating tax officials were <u>arraigned</u> before the Chief Magistrate this morning.', '["arranged","paraded","moved","<u>brought</u>"]', '<b>Arraigned</b> = <b>brought</b> before a court.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('854bde32-e4e6-43cc-96d4-12f6f8494371', 'Physics', 'JAMB', null, 1990, null, 'Shadows and eclipse result from the', null, '["Refraction of light","Rectilinear propagation of light","Diffraction of light","Reflection of light"]', 1, 'Light travels in straight lines, so opaque objects block it and form shadows (and eclipses).', true, '2026-10-12 19:15:31.197', '2026-10-12 19:15:31.197', null, null, null, 'Shadows and eclipse result from the', '["Refraction of light","Rectilinear propagation of light","Diffraction of light","Reflection of light"]', 'Light travels in straight lines, so opaque objects block it and form shadows (and eclipses).', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('854c2736-70dd-41ea-a4ab-b5b545023c0d', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). In answer to the question as to how life is treating him, the stranger said <u>''it never rains but it pours''</u>.', null, '["the blessings of life shower on him like fortunes","he is contented with his improved fortunes","things are getting decidedly worse","his financial status is deteriorating"]', 2, '''It never rains but it pours'' = troubles come all at once.', true, '2026-10-24 01:02:07.97', '2026-10-24 01:02:07.97', null, null, null, '(Choose the most appropriate interpretation). In answer to the question as to how life is treating him, the stranger said <u>''it never rains but it pours''</u>.', '["the blessings of life shower on him like fortunes","he is contented with his improved fortunes","<u>things are getting decidedly worse</u>","his financial status is deteriorating"]', '''<b>It never rains but it pours</b>'' = <b>troubles come all at once</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('854cdda6-d841-453b-bb62-5e548a80a017', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Before Jesus raised Jairus’ daughter, the people mocked Him because He...', null, '["told them that the girl was not dead but sleeping","rebuked them for weeping and mourning over the dead","did not pray before performing the miracle","did not arrive at the place before the girl died"]', 0, 'Matthew 9:24 / Mark 5:39-40 record that when Jesus told the mourners ''the child is not dead, but sleeping,'' they ridiculed and laughed at Him.', true, '2026-09-09 17:18:27.386', '2026-09-09 17:18:27.386', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8551e0ce-a941-42d8-b1dd-291a74e2c6ff', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. We cannot but talk about his <u>invaluable</u> contributions to the affairs of the society.', null, '["worthless","costly","unrecognized","incalculable"]', 0, 'Invaluable = priceless; opposite = worthless.', true, '2026-10-24 07:21:13.058', '2026-10-24 07:21:13.058', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. We cannot but talk about his <u>invaluable</u> contributions to the affairs of the society.', '["worthless","costly","unrecognized","incalculable"]', 'Invaluable = priceless; opposite = worthless.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8576e4b1-6779-42ed-84dc-a9f8901f7f7e', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). <u>To be above board is to be</u>', null, '["afloat","on top of a plank","above suspicion","raised above a board","the chairman of a board"]', 2, '''Above board'' = above suspicion.', true, '2026-10-24 01:04:16.053', '2026-10-24 01:04:16.053', null, null, null, '(Choose the most appropriate interpretation). <u>To be above board is to be</u>', '["afloat","on top of a plank","<u>above suspicion</u>","raised above a board","the chairman of a board"]', '''<b>Above board</b>'' = <b>above suspicion</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('857ff595-58ef-43e9-b3ca-5044e75ad53a', 'Economics', 'JAMB', null, 2026, null, 'When the demand for a good is inelastic, total revenue will fall if', null, '["price is increased","price remains constant","price is reduced","the good is a luxury"]', 2, 'When demand is inelastic (PED < 1), total revenue will fall if price is reduced. Inelastic demand means quantity demanded is not very responsive to price changes. If price is reduced, the percentage increase in quantity demanded is smaller than the percentage decrease in price, so total revenue (Price × Quantity) falls. Conversely, if price is increased with inelastic demand, total revenue rises. This is the relationship between price elasticity and total revenue.', true, '2026-09-10 10:42:55.668', '2026-09-10 10:42:55.668', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8584fd5d-8098-4f6b-8f64-51a1cc827c7c', 'Biology', 'JAMB', null, 2005, null, 'A yellow maize is crossed with a white maize and the first filial generation produce yellow maize only. The white trait is said to exhibit', null, '["dominance","recessiveness","codominance","incomplete dominance"]', 1, 'The white trait is recessive.', true, '2026-10-12 20:59:38.193', '2026-10-12 20:59:38.193', null, null, null, 'A yellow maize is crossed with a white maize and the first filial generation produce yellow maize only. The white trait is said to exhibit', '["dominance","recessiveness","codominance","incomplete dominance"]', 'The white trait is recessive.', '{"bold":["recessive"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('859a29a8-d2d0-44d3-88f5-36f5c6240db7', 'Physics', 'JAMB', null, 1990, null, 'An inclined plane which makes an angle of 30° with the horizontal has a velocity ratio of', null, '["2","1","0.866","0.50."]', 0, 'Velocity ratio = 1/sin θ = 1/sin 30° = 2.', true, '2026-10-12 19:15:30.658', '2026-10-12 19:15:30.658', null, null, null, 'An inclined plane which makes an angle of 30° with the horizontal has a velocity ratio of', '["2","1","0.866","0.50."]', 'Velocity ratio = 1/sin θ = 1/sin 30° = 2.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('85b1b715-03dd-41db-8ac0-e01c5c8a840c', 'Chemistry', 'JAMB', null, 2026, null, 'P₁V₁ = P₂V₂ supports i) Charles''s law ii) Boyle''s law iii) Graham''s law iv) Avogadro''s law', null, '["I only","ii only","iii and iv","none of the above"]', 1, 'P₁V₁ = P₂V₂ is Boyle''s Law.', true, '2026-09-12 11:36:19.094', '2026-09-12 11:36:19.094', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('85b2747e-8f48-4cce-82a4-67023c39b8c4', 'Physics', 'JAMB', null, 1987, null, 'An object 3.0 cm high is placed 60.0 cm from a converging lens whose focal length is 20.0 cm. Calculate the size of the image formed.', null, '["0.5 cm","1.5 cm","2.0 cm","6.0 cm"]', 1, '1/v = 1/20 - 1/60 = 2/60, so v = 30 cm. Magnification = 30/60 = 0.5, so image size = 0.5 x 3.0 = 1.5 cm.', true, '2026-10-12 19:15:25.978', '2026-10-12 19:15:25.978', null, null, null, 'An object 3.0 cm high is placed 60.0 cm from a converging lens whose focal length is 20.0 cm. Calculate the size of the image formed.', '["0.5 cm","1.5 cm","2.0 cm","6.0 cm"]', '1/v = 1/20 - 1/60 = 2/60, so v = 30 cm. Magnification = 30/60 = 0.5, so image size = 0.5 x 3.0 = 1.5 cm.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('85d07e13-27a7-4999-87a1-ec5be0c8af89', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. They are considered to be legal <u>luminaries</u>.', null, '["experts","practitioners","directors","powers"]', 0, 'Luminaries = experts.', true, '2026-10-24 01:04:03.652', '2026-10-24 01:04:03.652', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. They are considered to be legal <u>luminaries</u>.', '["<u>experts</u>","practitioners","directors","powers"]', '<b>Luminaries</b> = <b>experts</b>.', '{}');
