insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('85dac685-f2db-420b-b96d-7ce64e067410', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. It is claimed that there is <u>an extinct</u> volcano near Pankshin.', null, '["an extinguished","an inactive","a dead","a disused"]', 2, 'Extinct = dead (no longer active).', true, '2026-10-24 01:03:55.114', '2026-10-24 01:03:55.114', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. It is claimed that there is <u>an extinct</u> volcano near Pankshin.', '["an extinguished","an inactive","<u>a dead</u>","a disused"]', '<b>Extinct</b> = <b>a dead</b> (no longer active).', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('85dc4b22-54c5-487d-aa8a-1fa5ae2ebe10', 'Biology', 'JAMB', null, 2026, null, 'A mammal with red fur and long ears was crossed with another having white fur and short ears. If the offspring had red fur and short ears, then the', null, '["characters are linked","characters are not linked","parents are related","parents are not related"]', 0, 'The characters are linked because the offspring inherited red fur from one parent and short ears from the other. This suggests the genes for these traits are on the same chromosome and are inherited together. If characters were not linked, independent assortment would produce a more even distribution of combinations. The specific combination of traits (red fur with short ears) suggests linkage. Linkage reduces the frequency of recombinant offspring.', true, '2026-09-09 03:19:18.585', '2026-09-09 03:19:18.585', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('85dd5671-3170-4016-859a-bc5d8a4eb557', 'Physics', 'JAMB', null, 1998, null, 'In a closed organ pipe producing a musical note, an antinode will always be produced at', null, '["The closed end","The open end","The middle","All the parts of the pipe."]', 1, 'A closed pipe has a node at the closed end and an antinode at the open end.', true, '2026-10-12 19:15:45.837', '2026-10-12 19:15:45.837', null, null, null, 'In a closed organ pipe producing a musical note, an antinode will always be produced at', '["The closed end","The open end","The middle","All the parts of the pipe."]', 'A closed pipe has a node at the closed end and an antinode at the open end.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
