insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('861879c0-c130-449b-a2b7-36191fac286a', 'General Mathematics', 'JAMB', null, 2026, null, 'Make G the subject of the equation F = GMM/R²', null, '["FR/MR","FR²/MM","MM/FR²","MMR/FR"]', 1, 'F = GMM/R². Multiply both sides by R²: FR² = GMM. Divide by MM: G = FR²/MM.', true, '2026-09-10 10:48:18.996', '2026-09-10 10:48:18.996', null, null, null, null, null, null, null);
