insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8626b226-ce5d-4b23-9845-298660ead502', 'Physics', 'JAMB', null, 1995, null, 'The purpose of a dielectric material in a parallel plate capacitor is to', null, '["Increase its capacitance","Decrease its capacitance","Insulate the plates from each other","Increase the magnetic field between the plates."]', 0, 'A dielectric between the plates raises the capacitance by a factor equal to its relative permittivity (it also keeps the plates apart).', true, '2026-10-12 19:15:42.218', '2026-10-12 19:15:42.218', null, null, null, 'The purpose of a dielectric material in a parallel plate capacitor is to', '["Increase its capacitance","Decrease its capacitance","Insulate the plates from each other","Increase the magnetic field between the plates."]', 'A dielectric between the plates raises the capacitance by a factor equal to its relative permittivity (it also keeps the plates apart).', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
