insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('86675303-770f-4f30-9876-fc5a75c9cb56', 'General Mathematics', 'JAMB', null, 2026, null, 'What is the value of K if the mid-point of the line joining (1-K,4) and (2,K+1) is (-K,K)?', null, '["-1","-2","-3","-4"]', 2, '(1-K+2)/2 = -K. 3-K = -2K. K = -3.', true, '2026-09-12 11:44:16.739', '2026-09-12 11:44:16.739', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8668cb00-5e2a-4612-b9f1-3616ef728129', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation).The young man thought he was <u>at the top of the tree</u>.', null, '["at the highest point of his career","confused","at a point of prominence","arrogant"]', 0, '''At the top of the tree'' = highest point of career.', true, '2026-10-24 01:02:07.011', '2026-10-24 01:02:07.011', null, null, null, '(Choose the most appropriate interpretation).The young man thought he was <u>at the top of the tree</u>.', '["<u>at the highest point of his career</u>","confused","at a point of prominence","arrogant"]', '''<b>At the top of the tree</b>'' = <b>highest point of career</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('86779be9-77e6-4ad8-bf0b-ae056cfd1375', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The shortage of petrol was a <u>perennial</u> problem.', null, '["a seasonal","a recurring","an incurring","an annual"]', 1, 'Perennial = recurring.', true, '2026-10-24 01:01:57.018', '2026-10-24 01:01:57.018', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The shortage of petrol was a <u>perennial</u> problem.', '["a seasonal","<u>a recurring</u>","an incurring","an annual"]', '<b>Perennial</b> = <b>a recurring</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8680f044-c651-4450-856c-274de0898a7d', 'Government', 'JAMB', null, 2026, null, 'In which year did Nigeria become a member of the Organisation of the Petroleum Exporting Countries (OPEC)', null, '["1973","1967","1971","1980"]', 2, 'Nigeria became a member of OPEC in 1971.', true, '2026-09-12 11:24:46.19', '2026-09-12 11:24:46.19', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8686bfea-6929-42e3-9a62-4c81a39c18a2', 'Biology', 'JAMB', null, 2010, null, 'Mycorrhizae promote plant growth by', null, '["absorbing inorganic ions from the soil","protecting it from infection","helping it to utilize atmospheric nitrogen","serving as a growth regulator."]', 0, 'Mycorrhizae absorb inorganic ions from the soil.', true, '2026-10-12 20:59:40.531', '2026-10-12 20:59:40.531', null, null, null, 'Mycorrhizae promote plant growth by', '["absorbing inorganic ions from the soil","protecting it from infection","helping it to utilize atmospheric nitrogen","serving as a growth regulator."]', 'Mycorrhizae absorb inorganic ions from the soil.', '{"bold":["absorb inorganic ions from the soil"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('868795c0-92de-4d36-a306-1209126456b4', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). Surely, Ahmed is <u>a ball of fire</u>', null, '["a quarrelsome person","a hot-headed activist","a fiery speaker or writer","a very energetic person"]', 3, '''A ball of fire'' = very energetic person.', true, '2026-10-24 01:04:21.578', '2026-10-24 01:04:21.578', null, null, null, '(Choose the most appropriate interpretation). Surely, Ahmed is <u>a ball of fire</u>', '["a quarrelsome person","a hot-headed activist","a fiery speaker or writer","<u>a very energetic person</u>"]', '''A <b>ball of fire</b>'' = <b>very energetic person</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('86888ac5-f308-4df4-bc90-00a11492b362', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). The Principal advised the students to bear with him in their present situation since <u>every cloud has a silver lining</u>.', null, '["every school has its problem","every bad situation has something good","good things always bring problems","difficulties often bring good things"]', 1, '''Every cloud has a silver lining'' = every bad situation has something good.', true, '2026-10-24 01:02:07.389', '2026-10-24 01:02:07.389', null, null, null, '(Choose the most appropriate interpretation). The Principal advised the students to bear with him in their present situation since <u>every cloud has a silver lining</u>.', '["every school has its problem","<u>every bad situation has something good</u>","good things always bring problems","difficulties often bring good things"]', '''<b>Every cloud has a silver lining</b>'' = <b>every bad situation has something good</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8690391d-b0a3-40a7-a951-22c3a67beaad', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. In a sentence, there must always be <u>concord</u> between a subject and its verb.', null, '["breach","departure","disagreement","dispute"]', 2, 'Concord = agreement; opposite = disagreement.', true, '2026-10-24 07:21:15.918', '2026-10-24 07:21:15.918', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. In a sentence, there must always be <u>concord</u> between a subject and its verb.', '["breach","departure","disagreement","dispute"]', 'Concord = agreement; opposite = disagreement.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('869859da-7a25-47a3-865b-eb3c454e32a6', 'General Mathematics', 'JAMB', null, 2026, null, 'Two events A and B are mutually exclusive. If P(A) = 0.4 and P(B) = 0.3, what is the probability of A or B occurring?', null, '["1.0","0.5","0.7","0.12"]', 2, 'P(A∪B) = P(A) + P(B) = 0.4 + 0.3 = 0.7.', true, '2026-09-12 11:43:52.104', '2026-09-12 11:43:52.104', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('869b25ad-8b10-428a-89de-e67b17c66aec', 'Yoruba', 'JAMB', null, 2007, null, 'Ìwé Àkójópò Ewi Alohùn Yorùbá ni ìbéèrè 29-31 dá lé. Nínú Ìjálá, kí ni òkòrin sò pé ó máa p gbéyin àlè?', null, '["Òmò","Ìjà","Òyé","Àbámò."]', 1, 'Nínú Ìjálá, òkòrin sò pé ó máa p gbéyin àlè ni Ìjà.', true, '2026-10-13 13:23:32.013', '2026-10-13 13:23:32.013', null, null, null, 'Ìwé Àkójópò Ewi Alohùn Yorùbá ni ìbéèrè 29-31 dá lé. Nínú Ìjálá, kí ni òkòrin sò pé ó máa p gbéyin àlè?', '["Òmò","Ìjà","Òyé","Àbámò."]', 'Nínú Ìjálá, òkòrin sò pé ó máa p gbéyin àlè ni Ìjà.', '{"bold":["Ìjà"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('86b261dc-157a-4345-aea8-ebce906621e0', 'Physics', 'JAMB', null, 1986, null, 'Two objects, one having three times the mass of the other, are dropped at the same time from the top of a building. When they are above the ground, the two objects will have the same', null, '["Momentum","Kinetic energy","Potential energy","Acceleration."]', 3, 'In free fall all bodies have the same acceleration, g, regardless of mass. Momentum and energies depend on mass.', true, '2026-10-12 19:15:22.823', '2026-10-12 19:15:22.823', null, null, null, 'Two objects, one having three times the mass of the other, are dropped at the same time from the top of a building. When they are above the ground, the two objects will have the same', '["Momentum","Kinetic energy","Potential energy","Acceleration."]', 'In free fall all bodies have the same acceleration, g, regardless of mass. Momentum and energies depend on mass.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('86b3cca9-9962-41cb-8764-a87ee3e38182', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The accused was <u>eventually</u> convicted.', null, '["initially","consequently","subsequently","finally"]', 0, 'Eventually = finally; opposite = initially.', true, '2026-10-24 07:21:30.122', '2026-10-24 07:21:30.122', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The accused was <u>eventually</u> convicted.', '["initially","consequently","subsequently","finally"]', 'Eventually = finally; opposite = initially.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('86b947f8-d860-4f69-b8bb-1c00dcbda6fa', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'The promise of God with Abraham was that', null, '["he will live long","he would make nations out of him","he would make him return to his father''s house","he would give him flocks"]', 1, 'The promise of God to Abraham was that He would make nations out of him. God said, ''I will make of you a great nation, and I will bless you, and make your name great.''', true, '2026-09-12 09:45:58.372', '2026-09-12 09:45:58.372', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('86c2958f-5955-4ba5-a4a9-f0b5a11bc53f', 'Physics', 'JAMB', null, 1989, null, 'The magnitude of the resultant of two mutually perpendicular forces, F₁ and F₂, is 13 N. If the magnitude of F₁ is 5 N, what is the magnitude of F₂?', null, '["2.6 N","8.0 N","12.0 N","18.0 N"]', 2, 'R² = F₁² + F₂², so F₂ = √(13² - 5²) = √144 = 12.0 N.', true, '2026-10-12 19:15:28.711', '2026-10-12 19:15:28.711', null, null, null, 'The magnitude of the resultant of two mutually perpendicular forces, F<sub>1</sub> and F<sub>2</sub>, is 13 N. If the magnitude of F<sub>1</sub> is 5 N, what is the magnitude of F<sub>2</sub>?', '["2.6 N","8.0 N","12.0 N","18.0 N"]', 'R<sup>2</sup> = F<sub>1</sub><sup>2</sup> + F<sub>2</sub><sup>2</sup>, so F<sub>2</sub> = √(13<sup>2</sup> - 5<sup>2</sup>) = √144 = 12.0 N.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('86c3a173-9623-4d81-b585-a9b3c403a8d4', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Her <u>phlegmatic</u> temperament endears her to her friends.', null, '["cold","stoic","lively","irritable"]', 2, 'Phlegmatic = calm; opposite = lively.', true, '2026-10-24 07:21:23.464', '2026-10-24 07:21:23.464', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Her <u>phlegmatic</u> temperament endears her to her friends.', '["cold","stoic","lively","irritable"]', 'Phlegmatic = calm; opposite = lively.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('86c911ca-bb24-458e-a7da-d90e73c6dbe4', 'Physics', 'JAMB', null, 1993, null, 'Which of the following correctly describes the energy changes in the generation of light by a hydroelectric power station?', null, '["Electrical → Mechanical → Potential → Light","Potential → Mechanical → Electrical → Light","Mechanical → Sound → Electrical → Light","Kinetic → Mechanical → Electrical → Light"]', 1, 'Water at a height has potential energy, which drives the turbine (mechanical energy), the generator converts this to electrical energy, and the lamp gives light.', true, '2026-10-12 19:15:37.216', '2026-10-12 19:15:37.216', null, null, null, 'Which of the following correctly describes the energy changes in the generation of light by a hydroelectric power station?', '["Electrical → Mechanical → Potential → Light","Potential → Mechanical → Electrical → Light","Mechanical → Sound → Electrical → Light","Kinetic → Mechanical → Electrical → Light"]', 'Water at a height has potential energy, which drives the turbine (mechanical energy), the generator converts this to electrical energy, and the lamp gives light.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('86d13fde-f028-4190-b744-4498eee1587d', 'Chemistry', 'JAMB', null, 2026, null, 'Which compound is an alcohol?', null, '["CH₃COOH","C₂H₅OH","CH₄","C₂H₄"]', 1, 'C₂H₅OH (ethanol) is an alcohol.', true, '2026-09-12 11:33:01.604', '2026-09-12 11:33:01.604', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('86d8d4b0-f08f-45c5-a3b1-0d28049e7988', 'English Language', 'JAMB', null, 2024, null, 'We had to ______ the group headed by Taiwo.', null, '["sell out","sell off","sell up","selled"]', 1, '"Sell off" means to dispose of goods cheaply.', true, '2026-09-18 09:43:02.237', '2026-09-18 09:43:02.237', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('86e2c6cf-1de4-47f4-9237-8d22b51c1e48', 'Government', 'JAMB', null, 2026, null, 'Vassalage as a political system was practiced by the', null, '["Ibbio and Igala","Tiv","Hausa-Fulani","Igbo and Efik"]', 2, 'Vassalage was practiced by the Hausa-Fulani.', true, '2026-09-12 11:24:58.393', '2026-09-12 11:24:58.393', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('86e83857-1ebd-4758-ba58-b90f45d2d72e', 'General Mathematics', 'JAMB', null, 2026, null, 'Which property holds for the binary operation * defined by a*b = |a - b| on R?', null, '["has an identity","all of the above","associative","commutative"]', 3, '|a-b| = |b-a|, so it is commutative.', true, '2026-09-12 11:43:52.536', '2026-09-12 11:43:52.536', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('86f0bd8b-21fa-444c-a1b7-d124829b9904', 'Physics', 'JAMB', null, 1990, null, 'What precaution should a manufacturer take to ensure that energy loss in a transformer is minimized?', null, '["The winding of the transformer should be made of high resistance wires.","The core should be made of thin sheets of metal.","No magnetic material should be used to make the core.","The flux linking the primary with the secondary coils should be minimum."]', 1, 'A laminated core of thin insulated sheets reduces eddy current losses.', true, '2026-10-12 19:15:32.217', '2026-10-12 19:15:32.217', null, null, null, 'What precaution should a manufacturer take to ensure that energy loss in a transformer is minimized?', '["The winding of the transformer should be made of high resistance wires.","The core should be made of thin sheets of metal.","No magnetic material should be used to make the core.","The flux linking the primary with the secondary coils should be minimum."]', 'A laminated core of thin insulated sheets reduces eddy current losses.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('86f12796-62ce-40f0-a27d-e4e355ebea5a', 'Economics', 'JAMB', null, 2026, null, 'The necessary condition for a firm to be at equilibrium at a given output level is where', null, '["The marginal cost is rising","MC = MR","AC = AR","TC < TR","TVC = TR"]', 1, 'The necessary condition for a firm to be at equilibrium is where marginal cost (MC) equals marginal revenue (MR). At this point, the firm is maximizing profit or minimizing losses. If MC < MR, the firm can increase profit by producing more. If MC > MR, the firm should produce less. MC = MR is the profit-maximization condition.', true, '2026-09-10 10:41:21.098', '2026-09-10 10:41:21.098', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('86f49572-a9a8-4f99-8b56-248982fcb2d0', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. I shall be with you <u>presently</u>.', null, '["now","in a moment","at present","for the time being"]', 1, 'Presently = in a moment.', true, '2026-10-24 01:01:44.05', '2026-10-24 01:01:44.05', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. I shall be with you <u>presently</u>.', '["now","<u>in a moment</u>","at present","for the time being"]', '<b>Presently</b> = <b>in a moment</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('86f82054-6bcb-456b-a5dd-19996ad53cea', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The party supporters <u>vilified</u> the Chairman for the role he played in the crisis that rocked the party.', null, '["elected","challenged","condemned","impeached"]', 2, 'Vilified = condemned.', true, '2026-10-24 01:01:52.089', '2026-10-24 01:01:52.089', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The party supporters <u>vilified</u> the Chairman for the role he played in the crisis that rocked the party.', '["elected","challenged","<u>condemned</u>","impeached"]', '<b>Vilified</b> = <b>condemned</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('86febce9-bcb4-4eee-80ea-ea41bf2ef389', 'English Language', 'JAMB', null, 2007, null, 'Three quarters of the Physics class <u>---------</u> dramatically.', null, '["improve","improves","are improving","is improving"]', 1, 'Collective ''class'' â†’ singular improves.', true, '2026-10-24 01:02:13.214', '2026-10-24 01:02:13.214', null, null, null, 'Three quarters of the Physics class <u>---------</u> dramatically.', '["improve","<u>improves</u>","are improving","is improving"]', 'Collective ''<b>class</b>'' â†’ singular <b>improves</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('870e6f51-ea21-406b-8965-4e4105a584fd', 'Literature in English', 'JAMB', null, 2026, null, 'Who is the addressee?', null, '["Antony","Cleopatra","Demetrius","Charmian"]', 2, 'The addressee is Demetrius.', true, '2026-09-12 11:11:28.034', '2026-09-12 11:11:28.034', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('871ca093-0dda-4747-a10f-3b4a656f6aa3', 'Chemistry', 'JAMB', null, 2026, null, 'The number of protons in an atom is called its:', null, '["Mass number","Atomic number","Nucleon number","Atomic mass"]', 1, 'The number of protons in an atom is called the atomic number.', true, '2026-09-12 11:32:54.706', '2026-09-12 11:32:54.706', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('872f9afd-6e53-485b-8f19-a3b6f5173152', 'Physics', 'JAMB', null, 2001, null, 'The pressure of a mass of gas changes from 300 N m⁻² to 120 N m⁻² while the temperature drops from 127 °C to -73 °C. The ratio of the final volume to the initial volume is', null, '["2 : 5","5 : 4","5 : 2","4 : 5"]', 1, 'V₂/V₁ = (P₁/P₂)(T₂/T₁) = (300/120)(200/400) = 2.5 x 0.5 = 1.25 = 5 : 4.', true, '2026-10-12 19:15:51.361', '2026-10-12 19:15:51.361', null, null, null, 'The pressure of a mass of gas changes from 300 N m<sup>-2</sup> to 120 N m<sup>-2</sup> while the temperature drops from 127 °C to -73 °C. The ratio of the final volume to the initial volume is', '["2 : 5","5 : 4","5 : 2","4 : 5"]', 'V<sub>2</sub>/V<sub>1</sub> = (P<sub>1</sub>/P<sub>2</sub>)(T<sub>2</sub>/T<sub>1</sub>) = (300/120)(200/400) = 2.5 x 0.5 = 1.25 = 5 : 4.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8731373b-6b9c-4fe4-bba7-62506b99ff7b', 'English Language', 'JAMB', null, 2007, null, 'There are <u>__________</u> on spelling and pronunciation at the end of the book.', null, '["apendixes","appendix","appendices","appendixes"]', 2, 'Correct plural spelling: appendices.', true, '2026-10-24 07:21:34.353', '2026-10-24 07:21:34.353', null, null, null, 'There are <u>__________</u> on spelling and pronunciation at the end of the book.', '["apendixes","appendix","appendices","appendixes"]', 'Correct plural spelling: appendices.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8737249f-332e-4f40-9bd6-d3a8e0549957', 'English Language', 'JAMB', null, 2024, null, 'The investor could not help ______ at the idea. I) laughing II) laughed III) to laugh IV) laughs V) laugh', null, '["iv only","iii only","ii only","i only"]', 3, '"Could not help" is followed by a gerund: "laughing."', true, '2026-09-18 09:34:04.017', '2026-09-18 09:34:04.017', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('873c485e-74db-4541-a86f-36923a35873d', 'English Language', 'JAMB', null, 2007, null, 'In moments of serious economic hardship, many people are <u>__________</u> to turn to God', null, '["concerned","inclined","disposed","propensed"]', 1, 'Correct spelling: inclined.', true, '2026-10-24 07:21:44.769', '2026-10-24 07:21:44.769', null, null, null, 'In moments of serious economic hardship, many people are <u>__________</u> to turn to God', '["concerned","inclined","disposed","propensed"]', 'Correct spelling: inclined.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8747d4a3-cf57-4d1f-8978-bf5b1fe45fb0', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). Amedu''s actions <u>provoked severe criticism</u>', null, '["His actions were seriously rejected","His actions were severe and accepted","His actions were itemized because he was young","His actions provoked the humour"]', 0, '''Provoked severe criticism'' = seriously rejected.', true, '2026-10-24 01:04:24.416', '2026-10-24 01:04:24.416', null, null, null, '(Choose the most appropriate interpretation). Amedu''s actions <u>provoked severe criticism</u>', '["<u>His actions were seriously rejected</u>","His actions were severe and accepted","His actions were itemized because he was young","His actions provoked the humour"]', '''<b>Provoked severe criticism</b>'' = <b>seriously rejected</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('87509f18-89e3-40f9-b94e-a306d2abab99', 'Biology', 'JAMB', null, 2026, null, 'The function of the fluid-filled pericardium is to', null, '["reduce the friction by pumping movements of the heart","reduce the intensity of the pumping action of the heart","prevent disease organisms from attacking the heart","supply the heart with oxygen and nutrients"]', 0, 'The pericardial fluid lubricates the heart, reducing friction as the heart beats.', true, '2026-09-09 02:56:45.107', '2026-09-09 02:56:45.107', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('87511eee-151d-4a23-b1e9-02c1e6957a9c', 'Physics', 'JAMB', null, 1998, null, 'The physical quantity that has the same dimensions as impulse is', null, '["Energy","Momentum","Surface tension","Pressure."]', 1, 'Impulse = force x time = MLT⁻² x T = MLT⁻¹, which is the dimension of momentum.', true, '2026-10-12 19:15:44.655', '2026-10-12 19:15:44.655', null, null, null, 'The physical quantity that has the same dimensions as impulse is', '["Energy","Momentum","Surface tension","Pressure."]', 'Impulse = force x time = MLT<sup>-2</sup> x T = MLT<sup>-1</sup>, which is the dimension of momentum.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('87539f49-ad22-4b2c-b55d-661da6fbd674', 'Literature in English', 'JAMB', null, 2026, null, 'The poem can be classified as a work of', null, '["Romanticism","Imagism","Magical Realism","Postcolonial literature"]', 3, 'The poem is postcolonial literature.', true, '2026-09-12 11:10:59.077', '2026-09-12 11:10:59.077', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('87663fc7-ceaf-4b58-80fa-bd5c890cbef2', 'Literature in English', 'JAMB', null, 2026, null, 'Iya Agba helped Desola and Odekunle to', null, '["place a curse on Ajanaku","Re-order their lives","cast a spell on Ajanaku","expose Serubawon''s atrocities"]', 1, 'Iya Agba helped Desola and Odekunle to re-order their lives. In the play ''Once upon an Elephant,'' Iya Agba is a wise elder who provides guidance and support to the younger characters, helping them navigate their challenges and make better decisions. She does not place curses or cast spells, and exposing atrocities is not her primary role.', true, '2026-09-10 10:47:54.167', '2026-09-10 10:47:54.167', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8767b4bc-0ded-4f99-af2f-352080c10f92', 'Physics', 'JAMB', null, 1987, null, 'A radioactive sample initially contains N atoms. After three half-lives the number of atoms that have disintegrated is', null, '["N/8","3N/8","5N/8","7N/8"]', 3, 'After three half-lives N/8 remain, so the number disintegrated is N - N/8 = 7N/8.', true, '2026-10-12 19:15:26.728', '2026-10-12 19:15:26.728', null, null, null, 'A radioactive sample initially contains N atoms. After three half-lives the number of atoms that have disintegrated is', '["N/8","3N/8","5N/8","7N/8"]', 'After three half-lives N/8 remain, so the number disintegrated is N - N/8 = 7N/8.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('876a2318-025f-4c97-83bd-c759d921da42', 'English Language', 'JAMB', null, 2024, null, 'Identify the option that contains /dy/', null, '["gear","suggest","seizure","rich"]', 1, '"Suggest" contains the /dʒ/ sound.', true, '2026-09-18 09:43:02.671', '2026-09-18 09:43:02.671', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8780a119-8cb5-42bf-8152-2cdb1679548f', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Coastal plains are often very <u>densely</u> populated.', null, '["weakly","badly","rarely","sparsely"]', 3, 'Densely = thickly; opposite = sparsely.', true, '2026-10-24 07:21:12.598', '2026-10-24 07:21:12.598', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Coastal plains are often very <u>densely</u> populated.', '["weakly","badly","rarely","sparsely"]', 'Densely = thickly; opposite = sparsely.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('878fd2ee-a561-4fac-9c73-d6e8551dd9bc', 'Economics', 'JAMB', null, 2026, null, 'When the supply of a commodity is fixed, its price elasticity of supply is said to be: (i) perfectly elastic (ii) perfectly inelastic (iii) undefined (iv) elastic (v) inelastic', null, '["ii only","I only","ii and v only","v only"]', 0, 'When the supply of a commodity is fixed, its price elasticity of supply is perfectly inelastic (ii). This means that quantity supplied does not change regardless of price changes. The supply curve is vertical. The coefficient of elasticity is zero. This occurs for goods with fixed supply in the short run, such as agricultural products after harvest or unique artworks.', true, '2026-09-10 10:41:20.134', '2026-09-10 10:41:20.134', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('879240ba-2507-46c4-a048-4f0ecb829df7', 'Physics', 'JAMB', null, 2026, null, 'A gas is ideal under what conditions?', null, '["high temperature Low Pressure","low temperature high pressure","Low pressure only","High temperature high pressure"]', 0, 'A gas behaves ideally under conditions of high temperature and low pressure. At high temperature, molecules have enough kinetic energy to overcome intermolecular forces. At low pressure, molecules are far apart, so intermolecular forces are negligible.', true, '2026-09-10 10:56:43.307', '2026-09-10 10:56:43.307', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('879d3080-fc9a-4b91-b236-a896e06f7a64', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation).The government should stop <u>white elephant projects</u>.', null, '["projects in which white men kill elephants","projects in which white elephants are used","projects for painting some elephants white","high cost projects with low utility values","low cost projects with high utility values"]', 3, '''White elephant'' = costly project of little use.', true, '2026-10-24 01:02:02.695', '2026-10-24 01:02:02.695', null, null, null, '(Choose the most appropriate interpretation).The government should stop <u>white elephant projects</u>.', '["projects in which white men kill elephants","projects in which white elephants are used","projects for painting some elephants white","<u>high cost projects with low utility values</u>","low cost projects with high utility values"]', '''<b>White elephant</b>'' = <b>costly project of little use</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('87a3ed0d-2960-45b9-b34e-49f545200c21', 'Chemistry', 'JAMB', null, 2026, null, 'What is the pH of 0.001M solution of sodium hydroxide?', null, '["14","13","12","11"]', 3, 'pOH = -log(0.001) = 3. pH = 14 - 3 = 11.', true, '2026-09-12 11:36:28.074', '2026-09-12 11:36:28.074', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('87aa498a-3be0-4f2b-8812-91cca51c40b1', 'Biology', 'JAMB', null, 2003, null, 'Insects are considered the most successful among the invertebrates because they', null, '["possess exoskeletons","survive in various environmental conditions","have wings for flight","possess the ability to change their forms"]', 1, 'Insects exhibit remarkable adaptability, allowing them to survive in diverse and extreme environments.', true, '2026-10-12 20:05:10.363', '2026-10-12 20:05:10.363', null, null, null, 'Insects are considered the most successful among the invertebrates because they', '["possess exoskeletons","survive in various environmental conditions","have wings for flight","possess the ability to change their forms"]', 'Insects exhibit remarkable adaptability, allowing them to survive in diverse and extreme environments.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('87bc9d65-75ea-49aa-9f0e-3103ba80aa2a', 'English Language', 'JAMB', null, 2007, null, 'The <u>----------</u> engineer was unhappy with the shoddy work done by the contractors.', null, '["cite","sight","site","side"]', 2, 'Correct spelling: site.', true, '2026-10-24 07:21:34.708', '2026-10-24 07:21:34.708', null, null, null, 'The <u>----------</u> engineer was unhappy with the shoddy work done by the contractors.', '["cite","sight","site","side"]', 'Correct spelling: site.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('87be1f81-d2bb-4609-bf3c-f565ad18bec7', 'Biology', 'JAMB', null, 2010, null, 'The loss of soil through erosion can be reduced by', null, '["watering","crop rotation","manuring","irrigation"]', 1, 'Crop rotation reduces soil erosion.', true, '2026-10-12 20:59:40.987', '2026-10-12 20:59:40.987', null, null, null, 'The loss of soil through erosion can be reduced by', '["watering","crop rotation","manuring","irrigation"]', 'Crop rotation reduces soil erosion.', '{"bold":["Crop rotation"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('87cabb93-7212-47ff-86c9-8963a925ab10', 'Physics', 'JAMB', null, 2003, null, 'A satellite is in a parking orbit if its period is', null, '["More than the period of the earth","Equal to the period of the earth","The square of the period of the earth","Less than the period of the earth"]', 1, 'A parking (geostationary) orbit has the same period as the earth''s rotation, so the satellite stays above the same point on the earth.', true, '2026-10-12 19:15:54.887', '2026-10-12 19:15:54.887', null, null, null, 'A satellite is in a parking orbit if its period is', '["More than the period of the earth","Equal to the period of the earth","The square of the period of the earth","Less than the period of the earth"]', 'A parking (geostationary) orbit has the same period as the earth''s rotation, so the satellite stays above the same point on the earth.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('87ce2326-bcc5-4d63-ab41-489f28316638', 'Economics', 'JAMB', null, 2026, null, 'The following are the objectives of agricultural policies in Nigeria EXCEPT', null, '["provision of agricultural raw materials to industrial sectors","provision of food","increasing prices of agricultural Inputs","creation of rural employment"]', 2, 'Increasing prices of agricultural inputs is not an objective of agricultural policy.', true, '2026-09-12 11:01:29.256', '2026-09-12 11:01:29.256', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('87e73275-faf0-4730-b857-974517cc281a', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The chief will <u>launch</u> the fund-raising appeal.', null, '["make a speech at","eat his afternoon meal during","travel by boat to","start off"]', 3, 'Launch = start off.', true, '2026-10-24 01:03:57.2', '2026-10-24 01:03:57.2', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The chief will <u>launch</u> the fund-raising appeal.', '["make a speech at","eat his afternoon meal during","travel by boat to","<u>start off</u>"]', '<b>Launch</b> = <b>start off</b>.', '{}');
