insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('885eee20-23e2-433e-9bcb-030082cbca4b', 'Chemistry', 'JAMB', null, 2026, null, 'Soaps and detergents have the same basic characteristics except that the carboxyl group of the fatty acid in detergent is replaced by:', null, '["alcohol","sulphate or a sulphonate group","ester","acids"]', 1, 'Synthetic detergents replace the carboxylate (-COO-) group found in traditional soap with a sulfonate (-SO3-) or sulfate (-OSO3-) polar head.', true, '2026-09-09 17:12:47.298', '2026-09-09 17:12:47.298', null, null, null, null, null, null, null);
