insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8870797a-99cd-4746-912a-a83e8c087cc8', 'Biology', 'JAMB', null, 2026, null, 'The mutations theory of organic evolution was propounded by', null, '["Gregor Mendel","Hugo Vries","Jean Lamarck","Charles Darwin"]', 1, 'The mutations theory of organic evolution was propounded by Hugo de Vries. He proposed that mutations (sudden heritable changes) are the source of variation, which drives evolution. Mendel discovered the principles of heredity. Lamarck proposed the inheritance of acquired characteristics. Darwin proposed natural selection. De Vries'' mutation theory emphasized the importance of sudden genetic changes in evolution.', true, '2026-09-09 03:19:21.209', '2026-09-09 03:19:21.209', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('88718796-15a2-49bb-8037-cec502191c63', 'Financial Accounting', 'UTME', null, 2004, null, 'A company incurred N21 00 in running its four departments namely J, K, L and M with a corresponding number of employees as 1500, 2000, 3000 and 3500 respectively. What is the share of department K?', null, '["N9 000","N6 000","N4 500","N1 500"]', 1, 'Running Cost 21000. Total Number of employees: J 1500, K 2000, L 3000, M 3500 = 10,000. Share of K is 2000/10,000 x 21000 = 4200.', true, '2026-10-12 22:00:03.378', '2026-10-12 22:00:03.378', null, null, null, 'A company incurred N21 00 in running its four departments namely J, K, L and M with a corresponding number of employees as 1500, 2000, 3000 and 3500 respectively. What is the share of department K?', '["N9 000","<b>N6 000</b>","N4 500","N1 500"]', 'Running Cost 21000. Total Number of employees: J 1500, K 2000, L 3000, M 3500 = 10,000. Share of K is 2000/10,000 x 21000 = <b>4200</b>.', '{"bold":["4200"],"italic":[],"underline":[],"fillBlanks":[]}');
