insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('88b302f1-1c84-480c-9d7f-e570addf37c1', 'Literature in English', 'JAMB', null, 2026, null, 'In Still I Rise, the imagery ''like dust, I''ll rise'' primarily conveys', null, '["Fragility and weakness","Social stagnation","Environmental awareness","Inevitability of resilience and persistence"]', 3, 'The imagery conveys the inevitability of resilience and persistence.', true, '2026-09-12 11:05:15.365', '2026-09-12 11:05:15.365', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('88bb2812-46ca-4d00-a16b-d56230e4376f', 'Physics', 'JAMB', null, 2026, null, 'Which of the following is a vector quantity?', null, '["Magnetic flux","electromotive-force","escape velocity","magnetic induction","entropy"]', 2, 'Escape velocity is a vector quantity. It has both magnitude and direction. Magnetic flux, EMF, magnetic induction, and entropy are scalar quantities.', true, '2026-09-10 10:56:44.603', '2026-09-10 10:56:44.603', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('88bd5252-b810-4080-887e-187b0da6ce1a', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. It is surprising that this politician has now turned <u>renegade</u>.', null, '["militant","corrupt","loyal","quiet"]', 2, 'Renegade = traitor; opposite = loyal.', true, '2026-10-24 07:21:22.205', '2026-10-24 07:21:22.205', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. It is surprising that this politician has now turned <u>renegade</u>.', '["militant","corrupt","loyal","quiet"]', 'Renegade = traitor; opposite = loyal.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('88cb4f9d-d86f-4b54-b1db-d1df4923f4c7', 'Economics', 'JAMB', null, 2026, null, 'The cost that doesn''t change no matter the level of output is known as', null, '["Variable cost","Total cost","Average cost","Fixed cost"]', 3, 'Fixed cost does not change with the level of output.', true, '2026-09-12 11:01:10.05', '2026-09-12 11:01:10.05', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('88d2c031-f5c2-4721-b429-46e552d26cdd', 'Physics', 'JAMB', null, 1983, null, 'Which of the following arrangements in the sequence shown can be used to obtain a pure spectrum of white light?', null, '["Source, slit, converging lens, prism, converging lens, screen.","Source, slit, diverging lens, screen.","Source, converging lens, prism, diverging lens, screen.","Source, slit, prism, diverging lens, screen."]', 0, 'A slit gives a narrow beam, the first converging lens makes it parallel, the prism disperses it, and the second converging lens focuses each colour on the screen to give a pure spectrum.', true, '2026-10-12 19:15:16.875', '2026-10-12 19:15:16.875', null, null, null, 'Which of the following arrangements in the sequence shown can be used to obtain a pure spectrum of white light?', '["Source, slit, converging lens, prism, converging lens, screen.","Source, slit, diverging lens, screen.","Source, converging lens, prism, diverging lens, screen.","Source, slit, prism, diverging lens, screen."]', 'A slit gives a narrow beam, the first converging lens makes it parallel, the prism disperses it, and the second converging lens focuses each colour on the screen to give a pure spectrum.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('88e14811-3616-4690-ab24-68e6a190254e', 'Biology', 'JAMB', null, 2002, null, 'In corms, food is usually stored in the', null, '["leaves","stems","roots","buds"]', 1, 'Corms are modified underground plant stems specialized for food storage.', true, '2026-10-12 20:05:08.952', '2026-10-12 20:05:08.952', null, null, null, 'In corms, food is usually stored in the', '["leaves","stems","roots","buds"]', 'Corms are modified underground plant stems specialized for food storage.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('88f860b6-b7b1-4ba3-9e46-58d8701b597c', 'Literature in English', 'JAMB', null, 2026, null, 'One of the important means available to writer of a literary work is', null, '["Diction","Fiction","Stage","Stanza"]', 0, 'Diction is an important means for a writer.', true, '2026-09-12 11:11:03.357', '2026-09-12 11:11:03.357', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8921b72b-c6e5-427d-b587-4d7676535070', 'Physics', 'JAMB', null, 2026, null, 'A mass attached to the lower end of a spring bounces up and down. At which points in the path of the mass do the gravitational potential energy of the mass (GPE), the elastic potential energy in the spring (EPE) and the kinetic energy of the mass (KE) have their highest values?', 'https://res.cloudinary.com/kwi1uv0g/image/upload/v1789039774/questions/opxdjfgwb2unffbnwnn8.jpg', '["GPE: bottom, EPE: middle, KE: top","GPE: bottom, EPE: top, KE: middle","GPE: top, EPE: bottom, KE: middle","GPE: top, EPE: bottom, KE: top"]', 2, 'GPE is maximum at the top (highest position). EPE is maximum at the bottom (maximum stretch of spring). KE is maximum at the middle (equilibrium position where velocity is highest).', true, '2026-09-10 11:30:20.18', '2026-09-10 11:30:20.18', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('89226ebb-db95-41a4-83d2-57ce49478f68', 'Physics', 'JAMB', null, 1999, null, 'Gamma rays are produced when', null, '["High velocity electrons are abruptly stopped in metals","Energy changes occur within the nucleus of atoms","Energy changes occur within the electronic structure of atoms","Electrons are deflected in very strong magnetic fields."]', 1, 'Gamma rays are emitted when a nucleus drops from an excited state to a lower energy state.', true, '2026-10-12 19:15:48.733', '2026-10-12 19:15:48.733', null, null, null, 'Gamma rays are produced when', '["High velocity electrons are abruptly stopped in metals","Energy changes occur within the nucleus of atoms","Energy changes occur within the electronic structure of atoms","Electrons are deflected in very strong magnetic fields."]', 'Gamma rays are emitted when a nucleus drops from an excited state to a lower energy state.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('89262493-d8e3-49fe-b92c-af045f6e6a2e', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. A political <u>impasse</u> does not offer the best opportunity for merrymaking.', null, '["party","gridlock","rally","manifesto"]', 1, 'Impasse = gridlock.', true, '2026-10-24 01:04:06.489', '2026-10-24 01:04:06.489', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. A political <u>impasse</u> does not offer the best opportunity for merrymaking.', '["party","<u>gridlock</u>","rally","manifesto"]', '<b>Impasse</b> = <b>gridlock</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8938eda6-f93c-40ac-af81-6f4f1f675609', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. My father''s presentation was rather <u>casual</u>.', null, '["divisive","vital","informal","formal"]', 3, 'Casual = informal; opposite = formal.', true, '2026-10-24 07:21:24.878', '2026-10-24 07:21:24.878', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. My father''s presentation was rather <u>casual</u>.', '["divisive","vital","informal","formal"]', 'Casual = informal; opposite = formal.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('893bcb2e-89be-47bf-ba46-10e402a05481', 'Chemistry', 'JAMB', null, 2026, null, 'The shape of ammonia molecule is:', null, '["Linear","Trigonal planar","Trigonal pyramidal","Tetrahedral"]', 2, 'Ammonia has a trigonal pyramidal shape due to the lone pair on nitrogen.', true, '2026-09-12 11:35:49.28', '2026-09-12 11:35:49.28', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('894bf7b1-8654-4852-aad6-4ee8560f2023', 'English Language', 'JAMB', null, 2007, null, 'I had not given the question a thought before; my answer came <u>____________________</u>', null, '["momentarily","in an instant","on the spur of the moment","just like that"]', 2, '''On the spur of the moment'' = without prior thought.', true, '2026-10-24 01:04:25.381', '2026-10-24 01:04:25.381', null, null, null, 'I had not given the question a thought before; my answer came <u>____________________</u>', '["momentarily","in an instant","<u>on the spur of the moment</u>","just like that"]', '''<b>On the spur of the moment</b>'' = <b>without prior thought</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('895bed3f-c4ee-4d2f-bd28-c9d55971f857', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). Sade has been employed. But she is unhappy because it is <u>a run of the mill</u> job.', null, '["a boring","an exciting","a tiring","an ordinary"]', 3, '''Run of the mill'' = ordinary.', true, '2026-10-24 01:02:05.166', '2026-10-24 01:02:05.166', null, null, null, '(Choose the most appropriate interpretation). Sade has been employed. But she is unhappy because it is <u>a run of the mill</u> job.', '["a boring","an exciting","a tiring","<u>an ordinary</u>"]', '''<b>Run of the mill</b>'' = <b>ordinary</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('896b1002-fc4b-4d78-8f3e-167f6e469046', 'English Language', 'JAMB', null, 2007, null, 'Ali has been cured of his amnesia; he no longer suffers from <u>__________</u>', null, '["rounds of anxiety","loss of memory","pains in his arms","bouts of malaria"]', 1, 'Correct form: loss of memory.', true, '2026-10-24 07:21:38.545', '2026-10-24 07:21:38.545', null, null, null, 'Ali has been cured of his amnesia; he no longer suffers from <u>__________</u>', '["rounds of anxiety","loss of memory","pains in his arms","bouts of malaria"]', 'Correct form: loss of memory.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('896f0139-d7da-4337-8c8f-a93f8e739df4', 'Biology', 'JAMB', null, 2026, null, 'Viruses are regarded as non-living because they', null, '["can neither reproduce asexually or sexually","can''t survive in their respective environment","do not possess characteristic that can be transmitted from one generation to the next","can neither respire nor reproduce"]', 3, 'Viruses are considered non-living because they cannot respire or reproduce independently. They lack cellular structures and metabolic machinery. Viruses can only reproduce inside a host cell using the host''s metabolism. They don''t have their own energy production systems. Viruses do possess genetic material (DNA or RNA) that can be transmitted to the next generation, but they cannot replicate without a host. They can survive in the environment but are inactive. The inability to carry out basic life processes like respiration and independent reproduction makes viruses non-living.', true, '2026-09-09 03:18:49.036', '2026-09-09 03:18:49.036', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('896fb8bc-58ac-4e2f-b473-b8d56e2eb712', 'Literature in English', 'JAMB', null, 2026, null, 'The poet personifies the sea as a', null, '["benevolent goddess","long-suffering maternal figure","malevolent entity","silent, unfeeling observer"]', 1, 'The sea is personified as a long-suffering maternal figure.', true, '2026-09-12 11:10:44.867', '2026-09-12 11:10:44.867', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8970641a-2e91-4c18-8a05-736fe37aa90a', 'English Language', 'JAMB', null, 2007, null, 'No sooner..... the classroom than the lesson began.', null, '["had she entered","She entered","She had entered","Did she entered"]', 0, '''No sooner'' takes past perfect inversion: ''had she entered''.', true, '2026-10-25 18:25:06.198', '2026-10-25 18:25:06.198', null, null, null, 'No sooner..... the classroom than the lesson began.', '["had she entered","She entered","She had entered","Did she entered"]', '''No sooner'' takes past perfect inversion: ''had she entered''.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('89778b4a-51c0-4502-8b52-7e376211d919', 'Biology', 'JAMB', null, 2026, null, 'The gland directly affecting metabolic rate, growth and development is known as', null, '["adrenal gland","thyroid gland","mammary gland","parathyroid gland"]', 1, 'The thyroid gland directly affects metabolic rate, growth, and development. The thyroid produces thyroxine (T4) and triiodothyronine (T3), which regulate basal metabolic rate, heat production, and growth. The adrenal gland produces stress hormones. The mammary gland produces milk. The parathyroid gland regulates calcium levels. Thyroid hormones are essential for normal growth, brain development, and metabolic function. Hypothyroidism or hyperthyroidism can affect growth and development.', true, '2026-09-09 03:19:11.395', '2026-09-09 03:19:11.395', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('89be1381-9278-4c50-b06c-347945fb306d', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. It is claimed that there is <u>an extinct</u> volcano near Pankshin.', null, '["an extinguished","an inactive","a dead","a disused"]', 2, 'Extinct = dead (no longer active).', true, '2026-10-24 01:01:42.712', '2026-10-24 01:01:42.712', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. It is claimed that there is <u>an extinct</u> volcano near Pankshin.', '["an extinguished","an inactive","<u>a dead</u>","a disused"]', '<b>Extinct</b> = <b>a dead</b> (no longer active).', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('89c30cf5-5106-427d-a1da-a88aaf7074e4', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The pastor decided to <u>exorcise</u> the evil spirit as the afflicted member of his congregation cried for help.', null, '["expel","dive","invite","charm"]', 3, 'Exorcise = expel; opposite = charm.', true, '2026-10-24 07:21:18.06', '2026-10-24 07:21:18.06', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The pastor decided to <u>exorcise</u> the evil spirit as the afflicted member of his congregation cried for help.', '["expel","dive","invite","charm"]', 'Exorcise = expel; opposite = charm.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('89ccad89-acf0-42c1-b002-a0a2e3661b43', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). Adayi <u>cannot halt the march of time</u>', null, '["She is willing to march on","She cannot change the way things happen","She halts the march on time","She cannot alter the peace march"]', 1, '''Halt the march of time'' = change the way things happen.', true, '2026-10-24 01:04:24.47', '2026-10-24 01:04:24.47', null, null, null, '(Choose the most appropriate interpretation). Adayi <u>cannot halt the march of time</u>', '["She is willing to march on","<u>She cannot change the way things happen</u>","She halts the march on time","She cannot alter the peace march"]', '''<b>Halt the march of time</b>'' = <b>change the way things happen</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('89cf5a0e-0f6f-4ea2-8b5a-6c52e8321b01', 'Physics', 'JAMB', null, 2026, null, 'When a semiconductor is heated its resistance', null, '["increase","decrease","remains the same","increase and decrease"]', 1, 'When a semiconductor is heated, its resistance decreases. Unlike metals, semiconductors have a negative temperature coefficient of resistance. Heating generates more electron-hole pairs, increasing conductivity.', true, '2026-09-10 10:56:46.223', '2026-09-10 10:56:46.223', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('89d3cae2-8814-464a-8139-1b858fe5b2a8', 'Biology', 'JAMB', null, 2026, null, 'The crossing of individuals of the same species with different genetic characters is', null, '["non-disjunction","inbreeding","cross breeding","polygenic inheritance"]', 2, 'The crossing of individuals of the same species with different genetic characters is cross breeding. This is the intentional mating of individuals with different traits to combine desirable characteristics. Non-disjunction is the failure of chromosomes to separate during meiosis. Inbreeding is mating between closely related individuals. Polygenic inheritance is the control of a trait by multiple genes. Cross breeding is used to create hybrid vigor and combine desired traits.', true, '2026-09-09 03:19:22.787', '2026-09-09 03:19:22.787', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('89dbd102-7f38-44cd-82d2-1af0ec51c116', 'Government', 'JAMB', null, 2026, null, 'Southern Nigeria was divided into Eastern and Western provinces for administrative purposes in', null, '["1935","1937","1939","1941"]', 2, 'Southern Nigeria was divided into Eastern and Western provinces in 1939.', true, '2026-09-12 11:23:58.906', '2026-09-12 11:23:58.906', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('89dec03c-0575-4c5c-bda8-8bbff6d4f55e', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Just give me the <u>basic facts</u>, needless details.', null, '["relevant","extraneous","essential","critical"]', 2, 'Basic facts = essential.', true, '2026-10-24 01:01:59.35', '2026-10-24 01:01:59.35', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Just give me the <u>basic facts</u>, needless details.', '["relevant","extraneous","<u>essential</u>","critical"]', '<b>Basic facts</b> = <b>essential</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('89e6c007-665e-4628-be8e-96ca8a6ffa46', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Isa and Iju ate <u>sumptuous</u> meals at their brother''s wedding day.', null, '["foreign","insipid","cheap","expensive"]', 3, 'Sumptuous = expensive.', true, '2026-10-24 01:01:54.378', '2026-10-24 01:01:54.378', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Isa and Iju ate <u>sumptuous</u> meals at their brother''s wedding day.', '["foreign","insipid","cheap","<u>expensive</u>"]', '<b>Sumptuous</b> = <b>expensive</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('89fcf7f8-027d-44b2-9204-4fea05030b96', 'Biology', 'JAMB', null, 2026, null, 'Which of the following is the most advanced plant?', null, '["Marchantia","Dryopteris","Chlamydomonas","Spirogyra"]', 1, 'Dryopteris (a fern) is the most advanced among these options. Marchantia is a liverwort (bryophyte), Chlamydomonas is a unicellular green alga, and Spirogyra is a filamentous green alga. Ferns (pteridophytes) evolved after algae and bryophytes and are more advanced due to their vascular tissue (xylem and phloem), which allows for more efficient transport of water and nutrients. Ferns also have true roots, stems, and leaves, as well as a dominant sporophyte generation, making them more complex than the simpler non-vascular plants and algae.', true, '2026-09-09 03:18:20.539', '2026-09-09 03:18:20.539', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8a0932dc-7746-416d-9361-cd0cf8427b49', 'English Language', 'JAMB', null, 2007, null, 'Many people would always find reasons to <u>__________</u> the law.', null, '["debase","circumvent","circumspect","arrogate"]', 1, 'Correct spelling: circumvent.', true, '2026-10-24 07:21:39.267', '2026-10-24 07:21:39.267', null, null, null, 'Many people would always find reasons to <u>__________</u> the law.', '["debase","circumvent","circumspect","arrogate"]', 'Correct spelling: circumvent.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8a14ab4f-8f53-4847-bbaa-73e07c2ea9ca', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Everybody complained of a <u>lean</u> harvest last year.', null, '["surplus","abundant","poor","thin"]', 2, 'Lean harvest = poor harvest.', true, '2026-10-24 01:01:46.584', '2026-10-24 01:01:46.584', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Everybody complained of a <u>lean</u> harvest last year.', '["surplus","abundant","<u>poor</u>","thin"]', '<b>Lean harvest</b> = <b>poor</b> harvest.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8a1a796e-e482-4a06-a0cd-1dadb632c8f2', 'Biology', 'JAMB', null, 2001, null, 'The most important adaptation of xerophytes is the ability of the protoplasm to', null, '["absorb water and swell","resist being damaged by loss","shrink from the cell wall","store sugar and minerals in the vacuoles"]', 1, 'Xerophyte protoplasm resists damage from water loss.', true, '2026-10-12 20:59:29.675', '2026-10-12 20:59:29.675', null, null, null, 'The most important adaptation of xerophytes is the ability of the protoplasm to', '["absorb water and swell","resist being damaged by loss","shrink from the cell wall","store sugar and minerals in the vacuoles"]', 'Xerophyte protoplasm resists damage from water loss.', '{"bold":["resists damage from water loss"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8a27296c-7248-48bc-8f94-6dfd8a93c3c5', 'Financial Accounting', 'UTME', null, 2004, null, 'What is the cash balance in the receipts and payments account?', 'https://res.cloudinary.com/kwi1uv0g/image/upload/v1791841912/questions/mqtwjs9qg12fxglmhbmu.jpg', '["N2 520","N2 600","N3 000","N4 120"]', 3, 'Receipt and Payment Account: Subscription 5240 + Canopy 400 + Wages 1100 + Postages 300 + Furniture 120 = Balance c/d 4120.', true, '2026-10-12 22:00:03.133', '2026-10-12 22:00:03.133', null, null, null, 'What is the cash balance in the receipts and payments account?', '["N2 520","N2 600","N3 000","<b>N4 120</b>"]', 'Receipt and Payment Account: Subscription 5240 + Canopy 400 + Wages 1100 + Postages 300 + Furniture 120 = Balance c/d <b>4120</b>.', '{"bold":["4120"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8a3ba013-63d1-47e6-8521-442ec1562683', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The College Officer insisted that I show him my <u>credentials</u> before I could be registered.', null, '["papers","qualifications","testimonials","identities"]', 1, 'Credentials = qualifications.', true, '2026-10-24 01:04:01.46', '2026-10-24 01:04:01.46', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The College Officer insisted that I show him my <u>credentials</u> before I could be registered.', '["papers","<u>qualifications</u>","testimonials","identities"]', '<b>Credentials</b> = <b>qualifications</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8a44fa36-a1de-4e11-9971-e4308b4bc69c', 'Biology', 'JAMB', null, 2026, null, 'Gaseous exchange in domestic fowl occurs in the', null, '["tracheoles","trachea","air sacs","bronchi"]', 2, 'Birds have a unique respiratory system where gaseous exchange occurs in the air sacs, not the lungs themselves. The air sacs act as bellows that maintain a continuous unidirectional flow of air through the lungs during both inhalation and exhalation. This highly efficient system ensures that fresh air constantly passes over the respiratory surfaces, allowing birds to meet their high metabolic demands during flight. Tracheoles are in insects, and the trachea and bronchi are air passages, not sites of exchange.', true, '2026-09-09 03:18:17.234', '2026-09-09 03:18:17.234', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8a4f5b67-23e3-450a-80fe-754ab3932b85', 'Literature in English', 'JAMB', null, 2026, null, 'One major effect of migration on Finaba is that it', null, '["completely erases his traditional values","strengthens his understanding of his identity","makes him reject all foreign influences","isolates him permanently from his homeland"]', 1, 'Migration strengthens Finaba''s understanding of his identity.', true, '2026-09-12 11:11:58.359', '2026-09-12 11:11:58.359', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8a4f76ea-e02d-4a20-af26-48a5a4c48342', 'English Language', 'JAMB', null, 0, null, '6', null, '["trade union ","member","operator","organisation "]', 0, 'A trade union is the body that organizes and persuades workers.', true, '2026-09-18 09:08:12.699', '2026-09-18 09:08:12.699', '1edea09d-7ad3-4c90-8c54-eeb4b369dcff', 5, 'CLOZE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8a51483c-11de-4ae4-98f5-88fb08e89e32', 'Literature in English', 'JAMB', null, 2026, null, 'The predominant use of the third person pronoun in a novel creates a', null, '["Sense of detachment on the part of the writer","Sense of detachment on the part of the reader","Psychological affinity with the characters","Balance of opinion among the characters"]', 0, 'Third person creates detachment on the writer''s part.', true, '2026-09-12 11:10:53.625', '2026-09-12 11:10:53.625', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8a548d75-9175-4a90-8138-a7a8bfb5c8dd', 'English Language', 'JAMB', null, 2024, null, 'No sooner had he left the classroom ______ the teacher came in.', null, '["when","than","that","then"]', 1, '"No sooner... than" is the correct correlative conjunction.', true, '2026-09-18 09:23:08.299', '2026-09-18 09:23:08.299', null, null, 'STANDALONE', null, null, null, null);
