insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8a70c98d-d96e-4fa1-a6f4-aedcfe215119', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'The Lord appeared to Abraham and promised his descendants the land of the Canaanites at', null, '["Mount Sinai","the Oaks of Mamre","the Oak of Moreh","in the mountain east of Bethel"]', 2, 'The Lord appeared to Abraham at the Oak of Moreh (also called the oak of Shechem) and promised to give the land to his descendants. Abraham built an altar there to the Lord who had appeared to him.', true, '2026-09-12 09:45:57.905', '2026-09-12 09:45:57.905', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8a74c04b-c531-47d1-8a58-d878a3d2cac2', 'English Language', 'JAMB', null, 2024, null, 'The phrase the annulment and the phrase ______ in the passage are synonymous', null, '["the advent","a respite","a positive reversal","the cancellation"]', 3, '"The annulment" and "the cancellation" are synonymous.', true, '2026-09-18 10:13:05.093', '2026-10-24 17:39:12.324', '2708c14b-deb6-44cd-a86f-ce8964db149f', 4, 'COMPREHENSION', null, null, null, null);
