insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8aca95cd-60c1-47dc-bf17-ca1128cd13cc', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The secretary <u>runs down</u> anybody that does not sing his praises.', null, '["hates","please","honours","discredits"]', 2, 'Runs down = discredits; opposite = honours.', true, '2026-10-24 07:21:19.425', '2026-10-24 07:21:19.425', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The secretary <u>runs down</u> anybody that does not sing his praises.', '["hates","please","honours","discredits"]', 'Runs down = discredits; opposite = honours.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8ad0f7a0-b73e-40f1-bbb4-7c8629c076d5', 'Government', 'JAMB', null, 2026, null, 'The pre-colonial political system regarded as fragmented was', null, '["Yoruba","Hausa/Fulani","Tiv","Igbo"]', 3, 'The Igbo pre-colonial political system was fragmented (acephalous).', true, '2026-09-12 11:24:07.959', '2026-09-12 11:24:07.959', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8ad642e8-61b4-49e3-a5b1-afbcf375e59c', 'Physics', 'JAMB', null, 1997, null, 'An empty 60 litre petrol tank has a mass of 10 kg. Its mass when full of fuel of relative density 0.72 is', null, '["7.2 kg","33.2 kg","43.2 kg","53.2 kg"]', 3, 'Mass of fuel = 60 x 0.72 = 43.2 kg. Total mass = 10 + 43.2 = 53.2 kg.', true, '2026-10-12 19:15:43.308', '2026-10-12 19:15:43.308', null, null, null, 'An empty 60 litre petrol tank has a mass of 10 kg. Its mass when full of fuel of relative density 0.72 is', '["7.2 kg","33.2 kg","43.2 kg","53.2 kg"]', 'Mass of fuel = 60 x 0.72 = 43.2 kg. Total mass = 10 + 43.2 = 53.2 kg.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8ad783f8-6c25-4ca7-9fe8-52ad9ef45c47', 'General Mathematics', 'JAMB', null, 2026, null, 'If cos a = 3/5 and 0° < a < 90°. Evaluate 3cos a - 2sin a', null, '["1/2","1/5","3/5","2/5","1/3"]', 3, 'sin a = 4/5. 3(3/5) - 2(4/5) = 9/5 - 8/5 = 1/5. The answer is (B) 1/5.', true, '2026-09-12 11:43:41.277', '2026-09-12 11:43:41.277', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8adb9a89-f550-4da7-b831-35ea6df45301', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). ''<u>An open secret</u>'' means ___________', null, '["a fact that is very secret","an open matter","a secret known to everybody","a confidential matter","a secret told in the open air"]', 2, '''Open secret'' means widely known but officially hidden.', true, '2026-10-24 01:02:00.93', '2026-10-24 01:02:00.93', null, null, null, '(Choose the most appropriate interpretation). ''<u>An open secret</u>'' means ___________', '["a fact that is very secret","an open matter","<u>a secret known to everybody</u>","a confidential matter","a secret told in the open air"]', '''<b>Open secret</b>'' means <b>widely known</b> but officially hidden.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8aded2dd-8108-4bba-8779-d2ef56a3c16b', 'Physics', 'JAMB', null, 1998, null, 'The displacement d produced in a glass block of thickness t and refractive index n when an object is viewed through it is', null, '["t - n","t(1 + 1/n)","t(1 - 1/n)","t(1/n - 1)"]', 2, 'Apparent depth = t/n, so the apparent displacement (rise) of the object is t - t/n = t(1 - 1/n).', true, '2026-10-12 19:15:46.159', '2026-10-12 19:15:46.159', null, null, null, 'The displacement d produced in a glass block of thickness t and refractive index n when an object is viewed through it is', '["t - n","t(1 + 1/n)","t(1 - 1/n)","t(1/n - 1)"]', 'Apparent depth = t/n, so the apparent displacement (rise) of the object is t - t/n = t(1 - 1/n).', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8aeb52df-ff2e-4c40-9512-56971a52aefb', 'Financial Accounting', 'UTME', null, 2001, null, 'The N6, 000 subscription received is', 'https://res.cloudinary.com/kwi1uv0g/image/upload/v1791842158/questions/rxbv6w980s4kcz39mced.jpg', '["current asset","current liability","fixed asset","capital"]', 1, 'The N6,000 subscription received in advance is a current liability.', true, '2026-10-12 22:00:06.192', '2026-10-12 22:00:06.192', null, null, null, 'The N6, 000 subscription received is', '["current asset","<b>current liability</b>","fixed asset","capital"]', 'The N6,000 subscription received in advance is a <b>current liability</b>.', '{"bold":["current liability"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8af5d139-161c-4dcc-bfc2-d59e68e05bfd', 'English Language', 'JAMB', null, 0, null, 'Where are the rich getting richer and poor poorer?', null, '["in nearly all developing countries","in the majority of countries in the world","in developing countries with modern sectors"," in countries with non-modern"]', 1, null, true, '2026-09-18 08:52:55.359', '2026-09-18 08:52:55.359', '11db5bf8-0beb-4013-a66f-caacfb3d7413', 4, 'COMPREHENSION', null, null, null, null);
