insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8b203516-f958-41b1-b320-b5ce3fd42336', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). The boss told the man <u>to let sleeping dogs lie</u>.', null, '["not to look for trouble","not to disturb other people","let the dogs sleep well","let the trouble begin"]', 0, '''Let sleeping dogs lie'' = avoid trouble.', true, '2026-10-24 01:02:04.531', '2026-10-24 01:02:04.531', null, null, null, '(Choose the most appropriate interpretation). The boss told the man <u>to let sleeping dogs lie</u>.', '["<u>not to look for trouble</u>","not to disturb other people","let the dogs sleep well","let the trouble begin"]', '''<b>Let sleeping dogs lie</b>'' = <b>avoid trouble</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8b26b237-375a-4f48-8b1f-53a44236100f', 'Biology', 'JAMB', null, 2003, null, 'The gall bladder of a mammal has a duct connected to the', null, '["liver","duodenum","small intestine","pancreas"]', 1, 'The bile duct from the gall bladder empties bile directly into the duodenum.', true, '2026-10-12 20:05:10.612', '2026-10-12 20:05:10.612', null, null, null, 'The gall bladder of a mammal has a duct connected to the', '["liver","duodenum","small intestine","pancreas"]', 'The bile duct from the gall bladder empties bile directly into the duodenum.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8b304b35-8f3f-4911-8c60-ba6a1dd7da07', 'Biology', 'JAMB', null, 2012, null, 'The fungi are a distinct group of eukaryotes mainly because they have', null, '["spores","no chlorophyll","many fruiting bodies","sexual and asexual reproduction."]', 1, 'Fungi lack chlorophyll and are distinct eukaryotes.', true, '2026-10-12 20:59:44.235', '2026-10-12 20:59:44.235', null, null, null, 'The fungi are a distinct group of eukaryotes mainly because they have', '["spores","no chlorophyll","many fruiting bodies","sexual and asexual reproduction."]', 'Fungi lack chlorophyll and are distinct eukaryotes.', '{"bold":["lack chlorophyll"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8b34d01a-4ef2-4a33-9da4-751ad1a4527f', 'Government', 'JAMB', null, 2026, null, 'The ICJ comprises _ judges elected for the period of _ years', null, '["10, 6","15, 7","15, 9","25, 10"]', 2, 'The International Court of Justice (ICJ) comprises 15 judges elected for a period of 9 years. The judges are elected by the United Nations General Assembly and Security Council. They serve for a term of nine years and may be re-elected. The ICJ is the principal judicial organ of the United Nations and sits at The Hague in the Netherlands.', true, '2026-09-10 10:45:05.662', '2026-09-10 10:45:05.662', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8b390379-0e23-469a-8cf4-5e8093e4b2c5', 'English Language', 'JAMB', null, 2007, null, 'My shoes are worn out; I must see my <u>__________</u>', null, '["grocer","tanner","cobbler","hosier"]', 2, 'Correct spelling: cobbler.', true, '2026-10-24 07:21:44.317', '2026-10-24 07:21:44.317', null, null, null, 'My shoes are worn out; I must see my <u>__________</u>', '["grocer","tanner","cobbler","hosier"]', 'Correct spelling: cobbler.', '{}');
