insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8b3dc0ba-dd60-4523-9704-a9cb9b383205', 'English Language', 'JAMB', null, 2007, null, 'When we visited him, he offered us a variety of <u>__________</u> drinks such as whisky and brandy', null, '["hot","local","hard","soft"]', 2, 'Correct collocation: hard drinks.', true, '2026-10-24 07:21:43.916', '2026-10-24 07:21:43.916', null, null, null, 'When we visited him, he offered us a variety of <u>__________</u> drinks such as whisky and brandy', '["hot","local","hard","soft"]', 'Correct collocation: hard drinks.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8b46c1c7-6ca8-4218-bd49-0598f2027cf2', 'Chemistry', 'JAMB', null, 2026, null, 'What volume of oxygen measured at S.T.P would be liberated on electrolysis by 9650 coulombs of electricity {MVG=22.4dm3, F=96500Cmol-1}', null, '["22.4dm3","11.2dm3","1.12dm3","0.560dm3"]', 3, 'Anode reaction: 4OH- -> 2H2O + O2 + 4e-. 4 Faradays (4 * 96500 C) release 22.4 dm3 O2. Thus, 9650 C releases (9650 / 386000) * 22.4 = 0.56 dm3.', true, '2026-09-09 17:12:45.184', '2026-09-09 17:12:45.184', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8b51dcd6-0c2a-4edf-a876-9b5eaea1ebd9', 'Chemistry', 'JAMB', null, 2026, null, 'Alkanoic acids have low volatility compared with alkanols because they?', null, '["Are more polar than alkanols","Have two oxygen atoms while alkanols have one","Form Hydrogen bonds while alkanols do not","Form two Hydrogen bonds while alkanols form one"]', 3, 'Alkanoic acids form two hydrogen bonds while alkanols form one.', true, '2026-09-12 11:36:25.699', '2026-09-12 11:36:25.699', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8b522d48-2f7e-4c01-9152-335634104b36', 'Chemistry', 'JAMB', null, 2026, null, 'The Presence of an impurity in a substance will cause the melting point to?', null, '["Be stable","Be zero","Decrease","Increase"]', 2, 'Impurities decrease the melting point.', true, '2026-09-12 11:36:27.848', '2026-09-12 11:36:27.848', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8b61c2d3-4d2d-4f94-9ef9-788905d68095', 'Physics', 'JAMB', null, 2026, null, 'A solid cube of side 50cm and mass 75kg floats in a liquid with 1/3 of its height above the liquid surface. The relative density of the liquid is', null, '["0.33","0.50","0.67","0.90"]', 1, 'Volume of cube = 0.5³ = 0.125 m³. Volume submerged = 2/3 × 0.125 = 0.0833 m³. Density of cube = 75/0.125 = 600 kg/m³. Relative density = density of cube / density of liquid = 600/1000 = 0.6. Wait, using flotation: weight = upthrust. 75×10 = ρ_liquid × 0.0833 × 10. ρ_liquid = 750/0.833 = 900 kg/m³. Relative density = 0.9. The correct answer is 0.90, which is option (D).', true, '2026-09-10 10:56:42.602', '2026-09-10 10:56:42.602', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8b6998c1-f51b-4366-8451-4d2523001c75', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Ibro shows enough <u>liberality</u> with his meager income.', null, '["insensitivity","prodigality","frugality","generosity"]', 3, 'Liberality = generosity.', true, '2026-10-24 01:04:05.044', '2026-10-24 01:04:05.044', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Ibro shows enough <u>liberality</u> with his meager income.', '["insensitivity","prodigality","frugality","<u>generosity</u>"]', '<b>Liberality</b> = <b>generosity</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8b6a9aa1-97a6-43c6-b6b8-366e3de0c1a6', 'English Language', 'JAMB', null, 2007, null, 'The politicians were <u>__________</u> by the press', null, '["marooned","ridiculed","eclipsed","ostracized"]', 1, 'Correct spelling: ridiculed.', true, '2026-10-24 07:21:45.726', '2026-10-24 07:21:45.726', null, null, null, 'The politicians were <u>__________</u> by the press', '["marooned","ridiculed","eclipsed","ostracized"]', 'Correct spelling: ridiculed.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8b6c3ff3-93ed-42c5-88c1-6db29cbca193', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). Our new Vice-Chancellor <u>got off on the wrong foot</u> when he arrived.', null, '["injured his foot","started off badly","made a costly mistake","stepped on the wrong person"]', 1, '''Got off on the wrong foot'' = started off badly.', true, '2026-10-24 01:04:20.559', '2026-10-24 01:04:20.559', null, null, null, '(Choose the most appropriate interpretation). Our new Vice-Chancellor <u>got off on the wrong foot</u> when he arrived.', '["injured his foot","<u>started off badly</u>","made a costly mistake","stepped on the wrong person"]', '''<b>Got off on the wrong foot</b>'' = <b>started off badly</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8b70c7da-b7ff-423c-85c1-0ef73d656c2f', 'testing', 'JAMB', null, 2024, null, 'She is proficient ....... three foreign languages.', null, '["in","at","With","about"]', 1, '''Proficient in'' is the correct collocation.', true, '2026-10-31 16:48:53.378', '2026-10-31 16:48:53.378', null, null, null, 'She is proficient ....... three foreign languages.', '["in","at","With","about"]', '''Proficient in'' is the correct collocation.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8b7e7232-4978-4618-84fb-bd05707ca5d8', 'Government', 'JAMB', null, 2026, null, 'The first Secretary General of UNO was', null, '["Dr. Boutros Ghali","Riliwan Lukman","Trygve Lie","Diallo Telli"]', 2, 'The first Secretary General of the United Nations Organization (UNO) was Trygve Lie. He was a Norwegian politician and served as the first UN Secretary-General from 1946 to 1952. Dr. Boutros Ghali was the sixth Secretary-General (1992-1996). Riliwan Lukman was a Nigerian diplomat, and Diallo Telli was the first Secretary-General of the OAU.', true, '2026-09-10 10:45:05.875', '2026-09-10 10:45:05.875', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8b9ad41f-9492-49de-a4dd-cb8109721084', 'Physics', 'JAMB', null, 2026, null, 'Two forces each of 10N acts on a body one towards the north and the other towards the east. The magnitude and the direction of the resultant force are', null, '["10√2N, 45°E","10√2N, 45°W","20N, 45°W","20N, 45°E"]', 0, 'Resultant = √(10²+10²) = 10√2N. Direction = tan⁻¹(10/10) = 45° east of north.', true, '2026-09-10 10:56:46.007', '2026-09-10 10:56:46.007', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8ba620a1-96b8-4323-be0b-5089ad64e45b', 'English Language', 'JAMB', null, 2024, null, 'The sudden death of his friend made Etim have his heart in his boot. This means that Etim', null, '["became greatly discouraged","was very excited","took the matter very seriously","was frivolous about the matter"]', 0, '"Have one''s heart in one''s boot" means to be discouraged or depressed.', true, '2026-09-18 09:43:02.491', '2026-09-18 09:43:02.491', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8bb1525e-cc94-4dfd-8809-6045850b3f6a', 'General Mathematics', 'JAMB', null, 2026, null, 'The gradient of the straight line joining the points P(5,7) and Q(-2,-3) is', null, '["1/2","2/5","-4/7","-2/3"]', 0, '(7-(-3))/(5-(-2)) = 10/7. Not in options. The closest is 1/2.', true, '2026-09-12 11:44:02.496', '2026-09-12 11:44:02.496', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8bbdb384-2bc8-46c5-8fd6-10ad6f3c4b28', 'Literature in English', 'JAMB', null, 2026, null, 'The reference to ''Darwin''s examination of turtle''s shit'' serves to', null, '["introduce a humorous element","allude to scientific exploration and observation","Criticize Darwin''s theories","provide an example of marine biology"]', 1, 'It alludes to scientific exploration and observation.', true, '2026-09-12 11:10:59.337', '2026-09-12 11:10:59.337', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8bcf6786-4bdb-4e85-9526-d3f144eb15e9', 'English Language', 'JAMB', null, 2007, null, 'The teacher, along with her students ....invited to the ceremony', null, '["Were","Was","Have been","Are"]', 1, '''Along with'' does not change singular subject ''teacher'' → ''was''.', true, '2026-10-25 18:25:06.79', '2026-10-25 18:25:06.79', null, null, null, 'The teacher, along with her students ....invited to the ceremony', '["Were","Was","Have been","Are"]', '''Along with'' does not change singular subject ''teacher'' → ''was''.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8bcf7ed0-4a13-4622-8291-11d193afedcf', 'Hausa', 'JAMB', null, 2011, null, 'A al''adance, wacec hanya ce aka fi amfani da ita wajen magance ciwo?', null, '["Tauna.","Turare.","JiKo.","Surace."]', 2, 'Jiko ita ce hanya da aka fi amfani da ita wajen magance ciwo.', true, '2026-10-13 10:37:21.827', '2026-10-13 10:37:21.827', null, null, null, 'A al''adance, wacec hanya ce aka fi amfani da ita wajen magance ciwo?', '["Tauna.","Turare.","JiKo.","Surace."]', 'Jiko ita ce hanya da aka fi amfani da ita wajen magance ciwo.', '{"bold":["Jiko"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8bd43921-bca9-4018-af3f-d11d24fe0508', 'Physics', 'JAMB', null, 2026, null, 'Which of the following materials is used to control the rate of neutron production in a nuclear reactor?', null, '["Boron rods","Graphite rods","concrete shield","uranium rods"]', 0, 'Boron rods (control rods) are used to control the rate of neutron production in a nuclear reactor. Boron absorbs neutrons, slowing down or stopping the chain reaction. Graphite rods are moderators that slow neutrons. Concrete shields provide radiation protection.', true, '2026-09-10 10:56:40.923', '2026-09-10 10:56:40.923', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8bd54936-833a-4b31-8b47-579c8ce6fdd3', 'English Language', 'JAMB', null, 2007, null, 'It is important that you clear the refuse in front of your house every <u>__________</u>', null, '["fourtnight","fortnight","fourthnight","forthnight"]', 1, 'Correct spelling: fortnight.', true, '2026-10-24 07:21:36.671', '2026-10-24 07:21:36.671', null, null, null, 'It is important that you clear the refuse in front of your house every <u>__________</u>', '["fourtnight","fortnight","fourthnight","forthnight"]', 'Correct spelling: fortnight.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8bde61be-5855-416d-a7eb-54229a46bc08', 'English Language', 'JAMB', null, 2024, null, 'We videoed him ______ the faulty phone', null, '["repaired","repairing","repairs","repair"]', 1, '"Repairing" is the present participle used after the object.', true, '2026-09-18 09:43:02.596', '2026-09-18 09:43:02.596', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8be0fc58-53ae-40c5-870c-6150228d6453', 'English Language', 'JAMB', null, 2007, null, 'Femi has been <u>__________</u> behind in classroom', null, '["lacking","lagging","larking","lurking"]', 1, 'Correct spelling: lagging.', true, '2026-10-24 07:21:40.127', '2026-10-24 07:21:40.127', null, null, null, 'Femi has been <u>__________</u> behind in classroom', '["lacking","lagging","larking","lurking"]', 'Correct spelling: lagging.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8be12146-d389-4f8f-bcfb-3e607a3f2f6a', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. General Murtala Muhammed excelled in deeds of <u>prowess</u>.', null, '["warfare","politics","courage","eloquence"]', 2, 'Prowess = courage/bravery.', true, '2026-10-24 01:01:47.114', '2026-10-24 01:01:47.114', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. General Murtala Muhammed excelled in deeds of <u>prowess</u>.', '["warfare","politics","<u>courage</u>","eloquence"]', '<b>Prowess</b> = <b>courage</b>/bravery.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8be33d22-e0d7-47df-b83a-01686852b5e1', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The builder''s taste reflected <u>superfluous</u> grandeur.', null, '["excellent","superlative","expensive","too much"]', 3, 'Superfluous = too much.', true, '2026-10-24 01:03:56.505', '2026-10-24 01:03:56.505', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The builder''s taste reflected <u>superfluous</u> grandeur.', '["excellent","superlative","expensive","<u>too much</u>"]', '<b>Superfluous</b> = <b>too much</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8bf29e61-b491-440c-84ee-58ef7eb9eedb', 'Physics', 'JAMB', null, 1999, null, 'A gas at a volume V₀ in a container at pressure P₀ is compressed to one fifth of its volume. What will be its pressure if it maintains its original temperature T?', null, '["P₀/5","4P₀/5","P₀","5P₀"]', 3, 'Boyle''s law: P V is constant, so reducing V to one-fifth increases P to 5P₀.', true, '2026-10-12 19:15:47.287', '2026-10-12 19:15:47.287', null, null, null, 'A gas at a volume V<sub>0</sub> in a container at pressure P<sub>0</sub> is compressed to one fifth of its volume. What will be its pressure if it maintains its original temperature T?', '["P<sub>0</sub>/5","4P<sub>0</sub>/5","P<sub>0</sub>","5P<sub>0</sub>"]', 'Boyle''s law: P V is constant, so reducing V to one-fifth increases P to 5P<sub>0</sub>.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8bf34f65-08a5-403b-a802-3ad78860ff02', 'Literature in English', 'JAMB', null, 2026, null, 'The Greek tragedy must comply with how many unities?', null, '["Three","Two","Four","Five"]', 0, 'Greek tragedy must comply with three unities: unity of action (one main plot), unity of place (one setting), and unity of time (events occur within 24 hours). These unities were derived from Aristotle''s Poetics and were strictly observed in classical Greek drama. The three unities ensure focus and coherence in the dramatic structure.', true, '2026-09-10 10:47:55.003', '2026-09-10 10:47:55.003', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8c0c2b4d-ca0c-4b50-9122-30d1ff3967a7', 'Physics', 'JAMB', null, 1989, null, 'Light of wavelength 5000 x 10⁻⁸ cm travels in free space with a velocity of 3 x 10⁸ m s⁻¹. What is its wavelength in glass of refractive index 1.5?', null, '["3 333 x 10⁻⁸ cm","5 000 x 10⁻⁸ cm","6 666 x 10⁻⁸ cm","7 500 x 10⁻⁸ cm"]', 0, 'Wavelength in glass = λ/n = 5000 x 10⁻⁸/1.5 = 3 333 x 10⁻⁸ cm (frequency stays the same).', true, '2026-10-12 19:15:29.359', '2026-10-12 19:15:29.359', null, null, null, 'Light of wavelength 5000 x 10<sup>-8</sup> cm travels in free space with a velocity of 3 x 10<sup>8</sup> m s<sup>-1</sup>. What is its wavelength in glass of refractive index 1.5?', '["3 333 x 10<sup>-8</sup> cm","5 000 x 10<sup>-8</sup> cm","6 666 x 10<sup>-8</sup> cm","7 500 x 10<sup>-8</sup> cm"]', 'Wavelength in glass = λ/n = 5000 x 10<sup>-8</sup>/1.5 = 3 333 x 10<sup>-8</sup> cm (frequency stays the same).', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8c1b1632-31ae-417c-a8c8-1bb31f82280b', 'Physics', 'JAMB', null, 1985, null, 'A thin aluminium plate has a surface area of 1.500 m² at 20 °C. What will be its surface area when it is cooled to -20 °C? (Take the linear expansivity of aluminium to be 2 x 10⁻⁵ K⁻¹)', null, '["1.503 m²","1.500 m²","1.498 m²","1.497 m²","1.490 m²"]', 2, 'Area expansivity = 2 x 2 x 10⁻⁵ = 4 x 10⁻⁵ K⁻¹. ΔA = 1.500 x 4 x 10⁻⁵ x (-40) = -0.0024 m², so new area ≈ 1.498 m².', true, '2026-10-12 19:15:21.258', '2026-10-12 19:15:21.258', null, null, null, 'A thin aluminium plate has a surface area of 1.500 m<sup>2</sup> at 20 °C. What will be its surface area when it is cooled to -20 °C? (Take the linear expansivity of aluminium to be 2 x 10<sup>-5</sup> K<sup>-1</sup>)', '["1.503 m<sup>2</sup>","1.500 m<sup>2</sup>","1.498 m<sup>2</sup>","1.497 m<sup>2</sup>","1.490 m<sup>2</sup>"]', 'Area expansivity = 2 x 2 x 10<sup>-5</sup> = 4 x 10<sup>-5</sup> K<sup>-1</sup>. ΔA = 1.500 x 4 x 10<sup>-5</sup> x (-40) = -0.0024 m<sup>2</sup>, so new area ≈ 1.498 m<sup>2</sup>.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8c1f75ee-c4e1-487a-acaf-256493399c54', 'Government', 'JAMB', null, 2026, null, 'The political party serves as', null, '["a platform upon which the rights and liberties of the people can be attained","the group aggregating the interest of all in the state","a platform for rebelling against military rule","a platform for interest representation"]', 0, 'A political party serves as a platform upon which the rights and liberties of the people can be attained. Political parties are organized groups that seek to acquire and exercise political power by contesting elections. They aggregate interests, recruit leaders, and implement policies that protect citizens'' rights and liberties. While they do aggregate interests and represent interests, the fundamental purpose is to provide a platform for achieving rights and liberties through governance.', true, '2026-09-10 10:44:17.388', '2026-09-10 10:44:17.388', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8c2a2617-9f20-46d7-86ba-24ab8912bd23', 'Government', 'JAMB', null, 2026, null, 'All the following are not revenue allocation commission except', null, '["Udoji commission","Adedeji commission","Okigbo commission","Abolade commission"]', 2, 'The Okigbo Commission was a revenue allocation commission. It was set up in 1979 under the chairmanship of Dr. Pius Okigbo to review the revenue allocation formula in Nigeria. The Udoji Commission was a public service review commission, the Adedeji Commission dealt with tax reform, and the Abolade Commission was not a revenue allocation commission. The Okigbo Commission specifically addressed revenue allocation.', true, '2026-09-10 10:45:05.555', '2026-09-10 10:45:05.555', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8c342de4-f683-432d-a8f8-99021974cae9', 'Physics', 'JAMB', null, 1998, null, 'A ball of mass 0.15 kg is kicked against a rigid vertical wall with a horizontal velocity of 50 m s⁻¹. Calculate the impulse of the ball on the wall.', null, '["3.0 N s","4.5 N s","7.5 N s","12.0 N s"]', 2, 'Impulse = change in momentum of the ball = mv = 0.15 x 50 = 7.5 N s.', true, '2026-10-12 19:15:44.815', '2026-10-12 19:15:44.815', null, null, null, 'A ball of mass 0.15 kg is kicked against a rigid vertical wall with a horizontal velocity of 50 m s<sup>-1</sup>. Calculate the impulse of the ball on the wall.', '["3.0 N s","4.5 N s","7.5 N s","12.0 N s"]', 'Impulse = change in momentum of the ball = mv = 0.15 x 50 = 7.5 N s.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8c3e9807-d44e-4c2c-b31d-d1ed803023bb', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. I have always believed that my mother is a very <u>impassioned</u> woman.', null, '["emotive","impartial","impassive","emotional"]', 3, 'Impassioned = emotional.', true, '2026-10-24 01:04:02.321', '2026-10-24 01:04:02.321', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. I have always believed that my mother is a very <u>impassioned</u> woman.', '["emotive","impartial","impassive","<u>emotional</u>"]', '<b>Impassioned</b> = <b>emotional</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8c46fb6c-4240-4733-aee1-4e42c3fcffae', 'Financial Accounting', 'UTME', null, 2002, null, 'Nasara Manufacturing Plc has three direct labour employees that work 40 hours each a week for 50 weeks a year. Factory overhead costs of N60,000 is distributed on the basis of direct labour hours. Compute the overhead rate.', null, '["N12 per hour","N16 per hour","N10 per hour","N15 per hour"]', 2, 'No of employees 3, No of hours per week per person 40, No of weeks 50. Total hours = 3 x 40 x 50 = 6000 hours. Overhead rate = 60000/6000 = N10 per hour.', true, '2026-10-12 21:59:57.809', '2026-10-12 21:59:57.809', null, null, null, 'Nasara Manufacturing Plc has three direct labour employees that work 40 hours each a week for 50 weeks a year. Factory overhead costs of N60,000 is distributed on the basis of direct labour hours. Compute the overhead rate.', '["N12 per hour","N16 per hour","<b>N10 per hour</b>","N15 per hour"]', 'No of employees 3, No of hours per week per person 40, No of weeks 50. Total hours = 3 x 40 x 50 = 6000 hours. Overhead rate = 60000/6000 = <b>N10 per hour</b>.', '{"bold":["N10 per hour"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8c4c7c5d-0ebf-4738-9c33-254c1cd20270', 'Biology', 'JAMB', null, 2026, null, 'For pollination and fruit formation, the essential part(s) of the flower should be the', null, '["corolla","ovary","pistil (gynoecium)","ovules"]', 2, 'The pistil (gynoecium) is the essential part of the flower for pollination and fruit formation. The pistil contains the ovary, which develops into the fruit after fertilization. The ovary contains ovules, which develop into seeds. The corolla (petals) is often involved in attracting pollinators but is not essential for pollination and fruit formation. The ovary alone is part of the pistil, not the complete structure. Ovules are contained within the ovary. The pistil as a whole (including stigma and style) is necessary for pollination to occur.', true, '2026-09-09 03:18:55.21', '2026-09-09 03:18:55.21', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8c67e640-2ef4-4928-bc88-98bd24f9438f', 'Economics', 'JAMB', null, 2026, null, 'When a union is composed of workers with the same skill, it is called', null, '["a technical union","a craft union","an industrial union","a workers'' union"]', 1, 'When a union is composed of workers with the same skill, it is called a craft union. Craft unions organize workers based on a specific trade or skill, such as carpenters, plumbers, or electricians. Industrial unions organize all workers in a particular industry regardless of skill. Technical unions are not a standard classification. Workers'' union is a general term.', true, '2026-09-10 10:42:00.717', '2026-09-10 10:42:00.717', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8c7b4c2f-d46d-4dc9-ad3a-cb28439ba0a5', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The dictator wanted <u>tractable</u> men in his cabinet.', null, '["tough","intelligent","unruly","reliable"]', 2, 'Tractable = docile; opposite = unruly.', true, '2026-10-24 07:21:25.08', '2026-10-24 07:21:25.08', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The dictator wanted <u>tractable</u> men in his cabinet.', '["tough","intelligent","unruly","reliable"]', 'Tractable = docile; opposite = unruly.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8c8292ac-2d80-49c7-94f5-dcdd42315005', 'Physics', 'JAMB', null, 2026, null, 'Thermionic emission is the process whereby', null, '["beta rays are produced","x rays are produced","electrons leave a hot element","holes are produced"]', 2, 'Thermionic emission is the process whereby electrons leave a hot element. When a metal is heated to a high temperature, some electrons gain enough energy to overcome the work function and escape from the surface.', true, '2026-09-10 10:56:41.409', '2026-09-10 10:56:41.409', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8c86128c-7298-4afa-8dc8-4ac7ceca2e69', 'Yoruba', 'JAMB', null, 2007, null, 'Àfòmò ìbèrè ni a fi ýèdá', null, '["èlò","èdè","edé","ejò"]', 1, 'Àfòmò ìbèrè ni a fi ýèdá èdè.', true, '2026-10-13 13:23:31.192', '2026-10-13 13:23:31.192', null, null, null, 'Àfòmò ìbèrè ni a fi ýèdá', '["èlò","èdè","edé","ejò"]', 'Àfòmò ìbèrè ni a fi ýèdá èdè.', '{"bold":["èdè"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8c8fca23-a5d4-4dbd-9a70-70413eff684f', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Which is among the fruit of the Spirit in Galatians 5:22-23?', null, '["tongues and prophecy","miracles","joy and love","righteousness"]', 2, 'The fruit of the Spirit includes love, joy, peace, patience, kindness, goodness, faithfulness, gentleness, and self-control.', true, '2026-09-12 10:40:56.465', '2026-09-12 10:40:56.465', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8c976dd6-c3f9-4345-9dba-605316dbc69e', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Instead of proceeding to Nineveh, Jonah in disobedience, decided to go to the city of', null, '["Tarshish","Sodom","Joppa","Judah"]', 0, 'Jonah fled to Tarshish instead of going to Nineveh.', true, '2026-09-12 10:42:06.403', '2026-09-12 10:42:06.403', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8ca66b3a-5252-4938-b36a-8343ccb3dfd7', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Saul lost his kingship mainly because he', null, '["disobeyed divine instruction","was rejected by the people","lost battles","was too young"]', 0, 'Saul lost his kingship because he disobeyed divine instruction. He failed to completely destroy the Amalekites as God commanded, sparing King Agag and the best of the livestock. Samuel told him, ''To obey is better than sacrifice.''', true, '2026-09-12 09:45:47.069', '2026-09-12 09:45:47.069', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8cb72438-ece1-4c03-a198-ab97c8b8b122', 'Literature in English', 'JAMB', null, 2026, null, 'An anti-social action taken by the tragic hero which results in a catastrophe is called', null, '["anagnorisis","premonition","hamartia","empathy"]', 2, 'Hamartia is the tragic hero''s error leading to catastrophe.', true, '2026-09-12 11:06:30.683', '2026-09-12 11:06:30.683', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8ccda43f-c970-416b-8d9d-fbf790af502c', 'Physics', 'JAMB', null, 2000, null, 'A 2 H inductor has negligible resistance and is connected to a 50/π Hz a.c. supply. The reactance of the inductor is', null, '["200 Ω","50 Ω","100 Ω","25 Ω"]', 0, 'XL = 2πfL = 2π x (50/π) x 2 = 200 Ω.', true, '2026-10-12 19:15:50.235', '2026-10-12 19:15:50.235', null, null, null, 'A 2 H inductor has negligible resistance and is connected to a 50/π Hz a.c. supply. The reactance of the inductor is', '["200 Ω","50 Ω","100 Ω","25 Ω"]', 'X<sub>L</sub> = 2πfL = 2π x (50/π) x 2 = 200 Ω.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8cdbeb0b-e39b-49af-b6b0-f1f62dcfbb06', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Lola was <u>agitated</u> when the sad news of her mother''s accident was broken to her.', null, '["excited","calm","uncontrollable","unreasonable"]', 1, 'Agitated = disturbed; opposite = calm.', true, '2026-10-24 07:21:13.463', '2026-10-24 07:21:13.463', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Lola was <u>agitated</u> when the sad news of her mother''s accident was broken to her.', '["excited","calm","uncontrollable","unreasonable"]', 'Agitated = disturbed; opposite = calm.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8ce26044-9fa0-4018-bba4-19d5d872368b', 'Biology', 'JAMB', null, 0, null, 'answer the question above ', 'https://res.cloudinary.com/kwi1uv0g/image/upload/v1791839906/questions/ujfuikko9kwzk0hjukdl.jpg', '["a","b","c","d"]', 0, 'In this classic experiment, the hollowed-out yam tuber acts as a container, but its living cells function as a semi-permeable membrane. It allows water molecules to move through via osmosis (causing water from the beaker to rise into the yam cavity), while preventing the larger salt molecules from freely passing through.', true, '2026-10-12 21:18:58.052', '2026-10-12 21:18:58.052', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8ce591e0-27c1-44e0-b80c-7953e7bddec9', 'English Language', 'JAMB', null, 2007, null, 'After the initial confusion, the Manager''s suggestion brought <u>__________</u> to the depressed investors', null, '["a glitter of hope","a glimmer of hope","a sparkle of hope","a raise of hope","a shower of hope"]', 1, 'Correct form: a glimmer of hope.', true, '2026-10-24 07:21:40.279', '2026-10-24 07:21:40.279', null, null, null, 'After the initial confusion, the Manager''s suggestion brought <u>__________</u> to the depressed investors', '["a glitter of hope","a glimmer of hope","a sparkle of hope","a raise of hope","a shower of hope"]', 'Correct form: a glimmer of hope.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8cffce70-3acc-4020-b2c1-c1598f74c6ed', 'Literature in English', 'JAMB', null, 2026, null, 'What prompts Cleopatra to test the loyalty of Mark Antony?', null, '["A prophecy from the oracle","Antony''s marriage to Octavia","A letter from Rome","A rumour of war"]', 1, 'Cleopatra tests Antony''s loyalty after his marriage to Octavia.', true, '2026-09-12 11:11:59.027', '2026-09-12 11:11:59.027', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8d01ce92-b94a-4706-ac73-7fa01393c293', 'Chemistry', 'JAMB', null, 2026, null, 'Light is a factor responsible for the following reaction (I) Decomposition of H₂O₂ (II) Reaction between methane and chlorine (III) Conversion of silver halides to grey metallic silver (IV) Action of metal on an acid', null, '["II, III","I, II, III, IV","II","I, II, III"]', 3, 'Light is a factor for decomposition of H₂O₂, methane-chlorine reaction, and silver halide conversion.', true, '2026-09-12 11:36:08.241', '2026-09-12 11:36:08.241', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8d01dfde-188d-4bab-8cfe-9cbecdf1f5a6', 'Chemistry', 'JAMB', null, 2026, null, 'A substance which dissolves readily in organic solvent would', null, '["conduct electricity in molten state","be a covalent compound","have a strong electrostatic forces of attraction","have a high melting point"]', 1, 'Covalent compounds are non-polar or weakly polar, making them readily soluble in non-polar organic solvents following the principle ''like dissolves like''.', true, '2026-09-09 17:12:44.78', '2026-09-09 17:12:44.78', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8d09628f-4346-4175-8ad3-e709b108e946', 'Literature in English', 'JAMB', null, 2026, null, 'The first-person narrative style is used when the main character in a novel recounts', null, '["The author''s Story","Other character''s story","His own story","His best friend''s story"]', 2, 'First-person narrative recounts the character''s own story.', true, '2026-09-12 11:07:25.597', '2026-09-12 11:07:25.597', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8d1d53bc-0665-4e2c-817b-0af9ba7f23e4', 'Physics', 'JAMB', null, 1985, null, 'Which of the following will convert a milliammeter to a voltmeter?', null, '["Low series resistance","Low parallel resistance","High series resistance","High parallel resistance","Parallel resistance equal to milliammeter resistance."]', 2, 'A voltmeter needs a high total resistance so it draws little current. A high resistance (multiplier) is connected in series with the meter.', true, '2026-10-12 19:15:22.176', '2026-10-12 19:15:22.176', null, null, null, 'Which of the following will convert a milliammeter to a voltmeter?', '["Low series resistance","Low parallel resistance","High series resistance","High parallel resistance","Parallel resistance equal to milliammeter resistance."]', 'A voltmeter needs a high total resistance so it draws little current. A high resistance (multiplier) is connected in series with the meter.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8d273002-a757-4d21-b7ec-6e02e05c0406', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The warring tribes have been told to <u>parley</u> with each other.', null, '["hold talks","observe a truce","suspend hostilities","sign a treat"]', 0, 'Parley = hold talks.', true, '2026-10-24 01:01:51.822', '2026-10-24 01:01:51.822', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The warring tribes have been told to <u>parley</u> with each other.', '["<u>hold talks</u>","observe a truce","suspend hostilities","sign a treat"]', '<b>Parley</b> = <b>hold talks</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8d2bb343-da26-4178-b228-e0ee0343b3d8', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). Though a brilliant student, Binta <u>lost her tongue</u> when she was asked to give the vote of thanks at the end of the Governor''s visit to her school.', null, '["became dumb","became deaf and dumb","said nothing because she was shy","forgot her native language"]', 2, '''Lost her tongue'' = unable to speak from shyness.', true, '2026-10-24 01:02:03.676', '2026-10-24 01:02:03.676', null, null, null, '(Choose the most appropriate interpretation). Though a brilliant student, Binta <u>lost her tongue</u> when she was asked to give the vote of thanks at the end of the Governor''s visit to her school.', '["became dumb","became deaf and dumb","<u>said nothing because she was shy</u>","forgot her native language"]', '''<b>Lost her tongue</b>'' = <b>unable to speak from shyness</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8d391899-8118-4e27-a303-5b2ad5cf7efd', 'English Language', 'JAMB', null, 2024, null, '"Rough" in the first sentence of the passage means', null, '["mountains and molehills","the dangers attributed to space travel","challenges that will breed opportunities","difficulties"]', 3, '"May your road be rough" means may you face difficulties and challenges.', true, '2026-09-18 09:43:02.221', '2026-09-18 09:43:02.221', null, null, 'COMPREHENSION', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8d4fb023-8130-4202-88b7-d19c56b3ae4f', 'Physics', 'JAMB', null, 2004, null, 'A 50 W electric heater is used to heat a metal block of mass 5 kg. If in 10 minutes, a temperature rise of 12 °C is achieved, the specific heat capacity of the metal is', null, '["500 J kg⁻¹ K⁻¹","130 J kg⁻¹ K⁻¹","390 J kg⁻¹ K⁻¹","400 J kg⁻¹ K⁻¹"]', 0, 'Heat = 50 x 600 = 30 000 J. c = Q/(mΔθ) = 30 000/(5 x 12) = 500 J kg⁻¹ K⁻¹.', true, '2026-10-12 19:15:59.838', '2026-10-12 19:15:59.838', null, null, null, 'A 50 W electric heater is used to heat a metal block of mass 5 kg. If in 10 minutes, a temperature rise of 12 °C is achieved, the specific heat capacity of the metal is', '["500 J kg<sup>-1</sup> K<sup>-1</sup>","130 J kg<sup>-1</sup> K<sup>-1</sup>","390 J kg<sup>-1</sup> K<sup>-1</sup>","400 J kg<sup>-1</sup> K<sup>-1</sup>"]', 'Heat = 50 x 600 = 30 000 J. c = Q/(mΔθ) = 30 000/(5 x 12) = 500 J kg<sup>-1</sup> K<sup>-1</sup>.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8d599be3-eebf-4981-8bd2-ad634c988a6a', 'Physics', 'JAMB', null, 2002, null, 'If the total force acting on a particle is zero, the linear momentum will', null, '["Be constant","Increase","Increase then decrease","Decrease"]', 0, 'By Newton''s second law, force = rate of change of momentum. If the net force is zero, momentum does not change.', true, '2026-10-12 19:15:52.89', '2026-10-12 19:15:52.89', null, null, null, 'If the total force acting on a particle is zero, the linear momentum will', '["Be constant","Increase","Increase then decrease","Decrease"]', 'By Newton''s second law, force = rate of change of momentum. If the net force is zero, momentum does not change.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8d5ac8e4-26ec-4956-9d30-fc3c77ad20ca', 'Physics', 'JAMB', null, 1986, null, 'What is the effect of the increase in the size of the hole of a pin-hole camera on the image? It', null, '["Gives a blurred image.","Corrects for chromatic aberration","Magnifies the image","Brings the image into the sharper focus."]', 0, 'A larger hole lets rays from each object point spread over a larger patch on the screen, so the image is brighter but blurred.', true, '2026-10-12 19:15:23.896', '2026-10-12 19:15:23.896', null, null, null, 'What is the effect of the increase in the size of the hole of a pin-hole camera on the image? It', '["Gives a blurred image.","Corrects for chromatic aberration","Magnifies the image","Brings the image into the sharper focus."]', 'A larger hole lets rays from each object point spread over a larger patch on the screen, so the image is brighter but blurred.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8d6b380e-acc2-4553-bc40-1ea92200acec', 'Physics', 'JAMB', null, 2002, null, 'A current of 0.5 A flowing for 3 h deposits 2 g of metal during electrolysis. The quantity of the same metal that would be deposited by a current of 1.5 A flowing in 1 h is', null, '["18 g","10 g","6 g","2 g"]', 3, 'Mass is proportional to charge. 0.5 A for 3 h and 1.5 A for 1 h are both 1.5 A h, so the same 2 g is deposited.', true, '2026-10-12 19:15:54.46', '2026-10-12 19:15:54.46', null, null, null, 'A current of 0.5 A flowing for 3 h deposits 2 g of metal during electrolysis. The quantity of the same metal that would be deposited by a current of 1.5 A flowing in 1 h is', '["18 g","10 g","6 g","2 g"]', 'Mass is proportional to charge. 0.5 A for 3 h and 1.5 A for 1 h are both 1.5 A h, so the same 2 g is deposited.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8d6b9979-d17b-4124-98ef-31c7a314d5e3', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). The judge <u>took issue with</u> the counsel who complained of double standards.', null, '["agreed with","argued with","criticized","supported"]', 1, '''Took issue with'' = argued with.', true, '2026-10-24 01:04:20.88', '2026-10-24 01:04:20.88', null, null, null, '(Choose the most appropriate interpretation). The judge <u>took issue with</u> the counsel who complained of double standards.', '["agreed with","<u>argued with</u>","criticized","supported"]', '''<b>Took issue with</b>'' = <b>argued with</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8d6e403c-ef6b-4ff4-8e64-048939139b99', 'Physics', 'JAMB', null, 2000, null, 'A simple pendulum has a period of 17.0 s. When the length is shortened by 1.5 m, its period is 8.5 s. Calculate the original length of the pendulum.', null, '["1.5 m","2.0 m","3.0 m","4.0 m"]', 1, 'T is proportional to √L. T halves, so L falls to 1/4: L - 1.5 = L/4, giving 0.75L = 1.5 and L = 2.0 m.', true, '2026-10-12 19:15:49.053', '2026-10-12 19:15:49.053', null, null, null, 'A simple pendulum has a period of 17.0 s. When the length is shortened by 1.5 m, its period is 8.5 s. Calculate the original length of the pendulum.', '["1.5 m","2.0 m","3.0 m","4.0 m"]', 'T is proportional to √L. T halves, so L falls to 1/4: L - 1.5 = L/4, giving 0.75L = 1.5 and L = 2.0 m.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8d6f96f1-c24e-4b7c-911d-2994b90a96ec', 'Literature in English', 'JAMB', null, 2026, null, 'The tone of Still I Rise is best described as', null, '["Melancholic and reflective","Defiant and triumphant","Satirical and humorous","Passive and indifferent"]', 1, 'The tone is defiant and triumphant.', true, '2026-09-12 11:05:14.719', '2026-09-12 11:05:14.719', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8db27b16-f145-4dcf-8611-a1484b791bc2', 'Physics', 'JAMB', null, 1989, null, 'A piece of wood of mass 40 g and uniform cross-sectional area of 2 cm² floats upright in water. The length of the wood immersed is', null, '["80 cm","40 cm","20 cm","2 cm"]', 2, 'The wood displaces its own mass of water, 40 g = 40 cm³. Length immersed = 40/2 = 20 cm.', true, '2026-10-12 19:15:28.979', '2026-10-12 19:15:28.979', null, null, null, 'A piece of wood of mass 40 g and uniform cross-sectional area of 2 cm<sup>2</sup> floats upright in water. The length of the wood immersed is', '["80 cm","40 cm","20 cm","2 cm"]', 'The wood displaces its own mass of water, 40 g = 40 cm<sup>3</sup>. Length immersed = 40/2 = 20 cm.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8db78b96-12a7-4dbc-af93-cfaf88b34699', 'Literature in English', 'JAMB', null, 2026, null, 'The psychological depth of characters is revealed through', null, '["flashbacks and internal conflict","proverbs and aphorisms","dialogue alone","stage directions"]', 0, 'Psychological depth is revealed through flashbacks and internal conflict.', true, '2026-09-12 11:11:20.503', '2026-09-12 11:11:20.503', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8db8ccb0-ba67-45e3-adce-294f3a20abc2', 'Chemistry', 'JAMB', null, 2026, null, 'The pH of a solution increases from 2 to 4. This implies that:', null, '["Acidity increases","[H⁺] decreases by 10 times","[H⁺] decreases by 100 times","Solution becomes basic"]', 2, 'pH increases by 2 units, so [H⁺] decreases by 10² = 100 times.', true, '2026-09-12 11:35:48.816', '2026-09-12 11:35:48.816', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8dbc3d42-ef1e-4caa-9a30-551b3119136b', 'English Language', 'JAMB', null, 2024, null, 'What was the topic of the debate at Bepo''s send-off?', null, '["Migration: A curse or a blessing?","Who shapes the future: Teachers or parents?","The arts have contributed more to national development than the science","Public schools vs. Private schools: Which is better?"]', 0, 'The debate topic at Bepo''s send-off was "Migration: A curse or a blessing?"', true, '2026-09-18 09:43:02.298', '2026-09-18 09:43:02.298', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8dc43ff4-2e9f-485d-a559-8edda37531cc', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'When Joseph''s brothers came to him in Egypt, he said to them, ''You are...''', null, '["spies","robbers","traitors","mongers"]', 0, 'Joseph accused his brothers of being spies. He said, ''You are spies; you have come to see the weakness of the land.'' He used this accusation to test them and to ensure they would bring Benjamin to Egypt.', true, '2026-09-12 09:45:59.161', '2026-09-12 09:45:59.161', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8dca30f5-fbb0-4980-8386-0bf7fb49108b', 'English Language', 'JAMB', null, 2007, null, 'The judge demanded that the accused <u>_______</u> the full story to the court.', null, '["tells","told","telling","tell"]', 3, '''Demanded that'' â†’ subjunctive tell.', true, '2026-10-24 01:04:30.25', '2026-10-24 01:04:30.25', null, null, null, 'The judge demanded that the accused <u>_______</u> the full story to the court.', '["tells","told","telling","<u>tell</u>"]', '''<b>Demanded that</b>'' â†’ subjunctive <b>tell</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8dcfd05f-2175-4e53-93bc-8a20b54247df', 'Physics', 'JAMB', null, 1984, null, 'The spectrum of white light consists of coloured lights arranged in the following order', null, '["Blue, red, green, yellow, indigo, violet, orange.","Red, orange, yellow, green, blue, indigo, violet.","Red, orange, yellow, indigo, green, blue, violet.","Indigo, green, blue, violet, yellow, red, orange.","Yellow, blue, green, violet, orange, indigo, red."]', 1, 'The order of the spectrum is red, orange, yellow, green, blue, indigo, violet (ROYGBIV).', true, '2026-10-12 19:15:20.057', '2026-10-12 19:15:20.057', null, null, null, 'The spectrum of white light consists of coloured lights arranged in the following order', '["Blue, red, green, yellow, indigo, violet, orange.","Red, orange, yellow, green, blue, indigo, violet.","Red, orange, yellow, indigo, green, blue, violet.","Indigo, green, blue, violet, yellow, red, orange.","Yellow, blue, green, violet, orange, indigo, red."]', 'The order of the spectrum is red, orange, yellow, green, blue, indigo, violet (ROYGBIV).', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8dd27913-124d-4550-8f70-03fded0cbdc9', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. He was too <u>petrified</u> to give the closing remarks at the conference.', null, '["frightened","agitated","delighted","happy"]', 0, 'Petrified = frightened.', true, '2026-10-24 01:04:07.563', '2026-10-24 01:04:07.563', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. He was too <u>petrified</u> to give the closing remarks at the conference.', '["<u>frightened</u>","agitated","delighted","happy"]', '<b>Petrified</b> = <b>frightened</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8df690d7-b4f6-4ed9-b04e-74c188d93ba6', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Jeroboam''s major sin was', null, '["idolatry with golden calves","heavy taxation","rejecting prophets","alliance with Egypt"]', 0, 'Jeroboam set up golden calves at Bethel and Dan, leading Israel into idolatry.', true, '2026-09-12 10:40:55.071', '2026-09-12 10:40:55.071', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8df9221a-e31c-436a-9be4-f375b0930e2e', 'English Language', 'JAMB', null, 2007, null, 'That center-forward was <u>__________</u> consequently, the goal was not disallowed', null, '["in an off-side position","very well positioned","a brilliant player","the captain of the team"]', 0, 'Correct form: in an off-side position.', true, '2026-10-24 07:21:44.869', '2026-10-24 07:21:44.869', null, null, null, 'That center-forward was <u>__________</u> consequently, the goal was not disallowed', '["in an off-side position","very well positioned","a brilliant player","the captain of the team"]', 'Correct form: in an off-side position.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8dfe3001-188e-438d-941d-60bbd0dfc399', 'Biology', 'JAMB', null, 2001, null, 'The center for learning and memory in the human brain is the', null, '["olfactory lobe","cerebrum","medulla oblongata","cerebellum"]', 1, 'The cerebrum is responsible for learning and memory.', true, '2026-10-12 20:59:28.694', '2026-10-12 20:59:28.694', null, null, null, 'The center for learning and memory in the human brain is the', '["olfactory lobe","cerebrum","medulla oblongata","cerebellum"]', 'The cerebrum is responsible for learning and memory.', '{"bold":["cerebrum"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8e00f274-713f-4aa8-b3bc-c7ab63caa81e', 'English Language', 'JAMB', null, 0, null, '5', null, '["enforced"," coerced","persuaded","commanded "]', 0, 'Workers are not easily persuaded (convinced) to strike.', true, '2026-09-18 09:08:12.655', '2026-10-24 17:02:16.817', '1edea09d-7ad3-4c90-8c54-eeb4b369dcff', 4, 'CLOZE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8e058e35-0625-41b7-b4ef-98b18b606a43', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Mohammed does his work with so much <u>ardour</u>.', null, '["enthusiasm","discouragement","knowledge","indifference"]', 0, 'Ardour = enthusiasm.', true, '2026-10-24 01:01:58.239', '2026-10-24 01:01:58.239', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Mohammed does his work with so much <u>ardour</u>.', '["<u>enthusiasm</u>","discouragement","knowledge","indifference"]', '<b>Ardour</b> = <b>enthusiasm</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8e096a95-e365-4ea5-83c6-92ae566b4523', 'Biology', 'JAMB', null, 2013, null, 'The process in which complex substances are broken down into simpler ones is referred to as', null, '["metabolism","tropism","anabolism","catabolism"]', 3, 'The breakdown of complex substances into simpler ones is catabolism.', true, '2026-10-12 20:59:46.111', '2026-10-12 20:59:46.111', null, null, null, 'The process in which complex substances are broken down into simpler ones is referred to as', '["metabolism","tropism","anabolism","catabolism"]', 'The breakdown of complex substances into simpler ones is catabolism.', '{"bold":["catabolism"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8e1eb979-7649-4141-b5ab-71eb695be64e', 'English Language', 'JAMB', null, 2024, null, 'Choose the word that is opposite in meaning to the word or phrase in italics: his father served as mercenary in the army', null, '["preacher","regular","recruit","officer"]', 1, 'A "mercenary" is a hired soldier; the opposite is a "regular" soldier.', true, '2026-09-18 09:24:04.807', '2026-09-18 09:24:04.807', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8e261cc9-96c5-4392-8f36-2c6d15206ff1', 'Literature in English', 'JAMB', null, 2026, null, 'Ananse''s mattress is a', null, '["a straw-stuffed mat","a straw-stuffed, lumpy mattress","a soft, bouncy duniplo","a fragment of patched-up foam"]', 1, 'Ananse''s mattress is a straw-stuffed, lumpy mattress.', true, '2026-09-12 11:05:34.011', '2026-09-12 11:05:34.011', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8e27b81f-08be-4d9f-8ee9-74f04c877210', 'English Language', 'JAMB', null, 2024, null, 'Had Aisha realized what marriage entails, she ______', null, '["would not have rushes into it","would not run into it","would not have rushed into it","could have not rush into it","would have rushes into it"]', 2, 'The third conditional uses "would not have rushed."', true, '2026-09-18 09:43:02.82', '2026-09-18 09:43:02.82', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8e45f9a0-1289-463d-855a-d444a9e98c16', 'Financial Accounting', 'UTME', null, 2004, null, 'Given: Jan.2003 Dec.2003 N N Provision for bad debt 1000 Debtors 20000 Bad debt to be written off 2000. The provision for bad debt stands at 10% of debts. How much is to be charged to profit and loss account as provision for bad debt?', 'https://res.cloudinary.com/kwi1uv0g/image/upload/v1791841721/questions/s8nt2a2wu7ibpghqljqf.jpg', '["N800","N1 000","N1 800","N2 000"]', 2, 'Debtors 20,000 - Bad debt 2,000 = 18,000. Provision for bad debt (10%) = 10% of 18,000 = 1,800.', true, '2026-10-12 22:00:02.296', '2026-10-12 22:00:02.296', null, null, null, 'Given: Jan.2003 Dec.2003 N N Provision for bad debt 1000 Debtors 20000 Bad debt to be written off 2000. The provision for bad debt stands at 10% of debts. How much is to be charged to profit and loss account as provision for bad debt?', '["N800","N1 000","<b>N1 800</b>","N2 000"]', 'Debtors 20,000 - Bad debt 2,000 = 18,000. Provision for bad debt (10%) = 10% of 18,000 = <b>1,800</b>.', '{"bold":["1,800"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8e46c0f3-f565-4116-a98c-ba0b38bb34c0', 'Biology', 'JAMB', null, 2011, null, 'Which of the following groups of environmental factors are density-dependent?', null, '["Food, salinity, accumulation of metabolites and light","Temperature, salinity, predation and disease","Food, predation, disease and accumulation of metabolites.","Temperature, food, disease and light."]', 2, 'Food, predation, disease and accumulation of metabolites are density-dependent.', true, '2026-10-12 20:59:43.372', '2026-10-12 20:59:43.372', null, null, null, 'Which of the following groups of environmental factors are density-dependent?', '["Food, salinity, accumulation of metabolites and light","Temperature, salinity, predation and disease","Food, predation, disease and accumulation of metabolites.","Temperature, food, disease and light."]', 'Food, predation, disease and accumulation of metabolites are density-dependent.', '{"bold":["Food, predation, disease and accumulation of metabolites"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8e5c3dfe-f9f0-4f75-9429-ec9e65aab7e5', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The way he handled the whole issue was rather <u>despicable</u>.', null, '["disturbing","likeable","contemptible","frustrating"]', 2, 'Despicable = contemptible.', true, '2026-10-24 01:01:44.582', '2026-10-24 01:01:44.582', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The way he handled the whole issue was rather <u>despicable</u>.', '["disturbing","likeable","<u>contemptible</u>","frustrating"]', '<b>Despicable</b> = <b>contemptible</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8e668b81-6c34-4b2e-bc6c-a75c731f9fe5', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Had I known about their plan much earlier, I would have <u>nipped it in the bud</u>.', null, '["promoted it","squashed it","initiated it","stopped it"]', 0, 'Nipped in the bud = stopped; opposite = promoted.', true, '2026-10-24 07:21:22.86', '2026-10-24 07:21:22.86', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Had I known about their plan much earlier, I would have <u>nipped it in the bud</u>.', '["promoted it","squashed it","initiated it","stopped it"]', 'Nipped in the bud = stopped; opposite = promoted.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8e6d5473-2db8-4dee-97cc-c193ae330d7a', 'Literature in English', 'JAMB', null, 2026, null, 'The war had ended, but its shadows lingered in the minds of the people. Each step forward seemed weighed down by memories that refused to fade. The dominant literary device in the passage above is', null, '["Hyperbole","Metaphor","Irony","Euphemism"]', 1, 'The dominant device is metaphor (shadows lingering in minds).', true, '2026-09-12 11:09:51.559', '2026-09-12 11:09:51.559', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8e717e9c-0a66-497b-98d2-373e6f1f166d', 'Government', 'JAMB', null, 2026, null, 'The Nigerian civil war started on ______ and was led by ______', null, '["Jan 1, 1966, Maj. Gen. Ojukwu","May 30, 1976, Lt. Col. Ojukwu","July 1, 1967, Lt. Col. Ojukwu","June 1, 1967, Lt. Col. Ojukwu"]', 2, 'The Nigerian civil war started on July 1, 1967, led by Lt. Col. Ojukwu.', true, '2026-09-12 11:24:07.29', '2026-09-12 11:24:07.29', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8e73c87a-2161-4904-8a51-398b530663f1', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. You can <u>learn</u> a great deal just from watching other players.', null, '["invent","accumulate","allow","discover"]', 3, 'Learn = discover.', true, '2026-10-24 01:02:00.035', '2026-10-24 01:02:00.035', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. You can <u>learn</u> a great deal just from watching other players.', '["invent","accumulate","allow","<u>discover</u>"]', '<b>Learn</b> = <b>discover</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8e7ad1b3-6080-4996-a6af-136589203745', 'Financial Accounting', 'UTME', null, 2002, null, 'An entry in a subsidiary book which does not form part of the double entry system is a', 'https://res.cloudinary.com/kwi1uv0g/image/upload/v1791840630/questions/hkl61shtizsmo72tv4lm.jpg', '["contra entry","journal entry","single entry","memorandum entry"]', 3, 'Memorandum entries are entries recorded in the cash book to modify recording process of discount allowed and discount received accounts.', true, '2026-10-12 21:59:56.891', '2026-10-12 21:59:56.891', null, null, null, 'An entry in a subsidiary book which does not form part of the double entry system is a', '["contra entry","journal entry","single entry","<b>memorandum entry</b>"]', '<b>Memorandum entries</b> are entries recorded in the cash book to modify recording process of discount allowed and discount received accounts.', '{"bold":["Memorandum entries"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8e8b6526-cd87-4240-9c2d-e9726e4f8bf0', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). The preacher has <u>made good his promise</u> to visit some of his converts today.', null, '["fulfilled","abided by","seen to","accepted"]', 0, '''Made good'' = fulfilled.', true, '2026-10-24 01:02:02.91', '2026-10-24 01:02:02.91', null, null, null, '(Choose the most appropriate interpretation). The preacher has <u>made good his promise</u> to visit some of his converts today.', '["<u>fulfilled</u>","abided by","seen to","accepted"]', '''<b>Made good</b>'' = <b>fulfilled</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8e974e40-eda9-44d7-b2ff-196b56d5c9d9', 'Physics', 'JAMB', null, 1988, null, 'The principle of operation of an induction coil is based on', null, '["Ohm''s law","Ampere''s law","Faraday''s law","Coulomb''s law."]', 2, 'An induction coil produces a high induced e.m.f. in the secondary when the primary current changes, which is Faraday''s law of electromagnetic induction.', true, '2026-10-12 19:15:28.44', '2026-10-12 19:15:28.44', null, null, null, 'The principle of operation of an induction coil is based on', '["Ohm''s law","Ampere''s law","Faraday''s law","Coulomb''s law."]', 'An induction coil produces a high induced e.m.f. in the secondary when the primary current changes, which is Faraday''s law of electromagnetic induction.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8e9896a8-37f9-4c84-8e74-b5873b0a8165', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The poor man is compelled to <u>languish in</u> his poverty-stricken situation.', null, '["luxuriate in","deteriorate in","suffer in","laugh at"]', 0, 'Languish in = suffer in; opposite = luxuriate in.', true, '2026-10-24 07:21:17.147', '2026-10-24 07:21:17.147', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The poor man is compelled to <u>languish in</u> his poverty-stricken situation.', '["luxuriate in","deteriorate in","suffer in","laugh at"]', 'Languish in = suffer in; opposite = luxuriate in.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8e9e86a7-c24a-4f23-a1c8-f4a6eb4d4cf6', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Most warring countries end up in a state of <u>satiation</u>.', null, '["hunger","thirst","danger","famine"]', 0, 'Satiation = fullness; opposite = hunger.', true, '2026-10-24 07:21:20.098', '2026-10-24 07:21:20.098', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Most warring countries end up in a state of <u>satiation</u>.', '["hunger","thirst","danger","famine"]', 'Satiation = fullness; opposite = hunger.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8ea60cd9-a6ff-4af7-a98c-ec03dd3a66e3', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. ''Marcus <u>bears</u> watching;'' remarked Emperor Nero.', null, '["deserves","needs","favours","enjoys"]', 0, 'Bears watching = deserves watching.', true, '2026-10-24 01:01:43.837', '2026-10-24 01:01:43.837', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. ''Marcus <u>bears</u> watching;'' remarked Emperor Nero.', '["<u>deserves</u>","needs","favours","enjoys"]', '<b>Bears watching</b> = <b>deserves watching</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8eb08ce3-7643-41ec-965d-bff7e79ff018', 'Literature in English', 'JAMB', null, 2026, null, 'What is the central subject matter of the poem?', null, '["celebration of the sea''s beauty and power","an exploration of the history of navigation and maritime trade","a lament on human brutality and environmental decay as witnessed by the sea","a historical account of the Titanic disaster"]', 2, 'The central subject is a lament on human brutality and environmental decay.', true, '2026-09-12 11:13:47.306', '2026-09-12 11:13:47.306', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8ebbc0d7-cda3-447c-8a40-90f6217d40d8', 'Economics', 'JAMB', null, 2026, null, 'A supply curve parallel to the X-axis indicates', null, '["Infinitely inelastic supply","Fairly elastic supply","Fairly inelastic supply","Perfectly elastic supply"]', 3, 'A horizontal supply curve indicates perfectly elastic supply.', true, '2026-09-12 11:02:10.455', '2026-09-12 11:02:10.455', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8ebd1eb3-1983-4a59-b94a-b0f888343561', 'Chemistry', 'JAMB', null, 2026, null, 'Which statement best explains why non-metals generally form covalent compounds with each other?', null, '["They have low ionization energies","They have similar electronegativities","They have metallic lattices","They lose electrons easily"]', 1, 'Non-metals have similar electronegativities (both tend to gain electrons). When two non-metals react, neither can easily donate electrons to the other, so they share electrons to form covalent bonds. Metals have low ionization energies and lose electrons easily to form ionic bonds.', true, '2026-09-12 09:38:09.368', '2026-09-12 09:38:09.368', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8ede948c-5f3e-4ec0-8293-b6dd6e241fc4', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The striking workers have vowed to work until the decision is rescinded.', null, '["implemented","rescinded","dismissed","reversed"]', 3, 'Rescinded = reversed.', true, '2026-10-24 01:04:09.661', '2026-10-24 01:04:09.661', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The striking workers have vowed to work until the decision is rescinded.', '["implemented","rescinded","dismissed","<u>reversed</u>"]', '<b>Rescinded</b> = <b>reversed</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8ee424ee-1383-44b8-86b4-db5075cb46c9', 'Physics', 'JAMB', null, 1987, null, 'A ray of light is incident at an angle of 30° on the top surface of a parallel-sided glass block of refractive index 1.5. The ray finally emerges from the lower surface. What is the angular deviation of the emergent ray?', null, '["60°","39°","28°","0°"]', 3, 'In a parallel-sided block the emergent ray is parallel to the incident ray, so the net angular deviation is zero (it is only displaced sideways).', true, '2026-10-12 19:15:26.084', '2026-10-12 19:15:26.084', null, null, null, 'A ray of light is incident at an angle of 30° on the top surface of a parallel-sided glass block of refractive index 1.5. The ray finally emerges from the lower surface. What is the angular deviation of the emergent ray?', '["60°","39°","28°","0°"]', 'In a parallel-sided block the emergent ray is parallel to the incident ray, so the net angular deviation is zero (it is only displaced sideways).', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8ee57d7c-f995-417b-895f-fe553cd4e0fa', 'English Language', 'JAMB', null, 2024, null, 'The press will no longer be free when the new government starts to ______ the newspaper.', null, '["censure","edit","publish","censor"]', 3, '"Censor" means to examine and suppress parts of media, restricting press freedom.', true, '2026-09-18 09:23:08.547', '2026-09-18 09:23:08.547', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8ee60507-4b83-43ec-b2a2-067bdc92b076', 'Literature in English', 'JAMB', null, 2026, null, 'In Not My Business, the repeated phrase ''What business of mine is it...'' serves as', null, '["Irony exposing societal indifference","Alliteration for sound effect","Euphemism for fear","Metaphor for oppression"]', 0, 'The phrase is irony exposing societal indifference.', true, '2026-09-12 11:12:06.351', '2026-09-12 11:12:06.351', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8eed18e1-753c-43e5-b412-869e26ee0a1c', 'Literature in English', 'JAMB', null, 2026, null, 'Sludge in the extract means', null, '["Water","Fire","Snow","Mud"]', 3, 'Sludge means mud.', true, '2026-09-12 11:13:53.385', '2026-09-12 11:13:53.385', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8eeff421-fcfd-47cd-ba5f-6aa1614c58f1', 'General Mathematics', 'JAMB', null, 2026, null, 'If log 5 = 0.6990, log 7 = 0.8451 and log 8 = 0.9031, evaluate log[(35×49)/(40÷56)]', null, '["3.3804","4.3804","2.3804","3.2805"]', 0, 'log[(35×49)/(40/56)] = log(35×49×56/40) = log(35) + log(49) + log(56) - log(40) = log(5×7) + 2log7 + log(7×8) - log(5×8) = log5+log7+2log7+log7+log8-log5-log8 = 4log7 = 4(0.8451) = 3.3804.', true, '2026-09-12 11:44:00.689', '2026-09-12 11:44:00.689', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8f09a689-ce50-4fc8-9e9f-869cfdf23ba7', 'Physics', 'JAMB', null, 2001, null, 'In a Daniell cell, the depolarizer, positive and negative electrodes are respectively', null, '["Copper sulphate, copper and zinc","Manganese dioxide, carbon and zinc","Sulphuric acid, lead oxide and lead","Potassium hydroxide, nickel and iron"]', 0, 'A Daniell cell has a copper positive electrode in copper sulphate (the depolarizer) and a zinc negative electrode.', true, '2026-10-12 19:15:51.899', '2026-10-12 19:15:51.899', null, null, null, 'In a Daniell cell, the depolarizer, positive and negative electrodes are respectively', '["Copper sulphate, copper and zinc","Manganese dioxide, carbon and zinc","Sulphuric acid, lead oxide and lead","Potassium hydroxide, nickel and iron"]', 'A Daniell cell has a copper positive electrode in copper sulphate (the depolarizer) and a zinc negative electrode.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8f0e6762-6821-4a27-8470-188325b40758', 'Physics', 'JAMB', null, 1995, null, 'The length of a displaced pendulum bob which passes its lowest point twice every second is [g = 10 m s⁻²]', null, '["0.25 m","0.45 m","0.58 m","1.00 m"]', 0, 'The bob passes the lowest point twice per period, so T = 1 s. L = gT²/4π² = 10/39.5 ≈ 0.25 m.', true, '2026-10-12 19:15:40.665', '2026-10-12 19:15:40.665', null, null, null, 'The length of a displaced pendulum bob which passes its lowest point twice every second is [g = 10 m s<sup>-2</sup>]', '["0.25 m","0.45 m","0.58 m","1.00 m"]', 'The bob passes the lowest point twice per period, so T = 1 s. L = gT<sup>2</sup>/4π<sup>2</sup> = 10/39.5 ≈ 0.25 m.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8f26d2b6-3ac6-4bb4-a1ba-297a8bf7541a', 'Biology', 'JAMB', null, 2013, null, 'The plants that grow in deserts or very dry areas are referred to as', null, '["epiphytes","xerophytes","mesophytes","hydrophytes"]', 1, 'Plants that grow in deserts are xerophytes.', true, '2026-10-12 20:59:46.517', '2026-10-12 20:59:46.517', null, null, null, 'The plants that grow in deserts or very dry areas are referred to as', '["epiphytes","xerophytes","mesophytes","hydrophytes"]', 'Plants that grow in deserts are xerophytes.', '{"bold":["xerophytes"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8f2be2cd-2092-4c33-a829-e73b9de555c0', 'Biology', 'JAMB', null, 2026, null, 'Which of the following is true of the children of a haemophilic man who marries a woman that is not haemophilic and does not carry the trait?', null, '["all their daughters will be haemophilic","all their daughters will be carriers","all their sons will be haemophilic","all their sons will be carriers"]', 1, 'Haemophilia is X-linked. The father gives his X chromosome to all daughters; since the mother is normal, all daughters will be carriers.', true, '2026-09-09 02:56:42.424', '2026-09-09 02:56:42.424', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8f3008b3-d176-4eb7-8d9d-d88cab389cab', 'Literature in English', 'JAMB', null, 2026, null, 'In The Marriage of Anansewa, the dramatic technique of Anansegoro is best described as', null, '["A tragic form characterised by the downfall of a noble hero","A traditional storytelling mode blending narration, music, and audience participation","A realist technique focusing strictly on dialogue and stage action","A symbolic method relying solely on abstract characters"]', 1, 'Anansegoro is a traditional storytelling mode blending narration, music, and audience participation.', true, '2026-09-12 11:04:34.608', '2026-09-12 11:04:34.608', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8f375ae0-82e9-451d-b7d7-fe933cb5cd23', 'English Language', 'JAMB', null, 2024, null, 'They think the management will soon agree to a satisfactory _10_.', null, '["promotion","progress","end","settlement"]', 3, 'Management agrees to a satisfactory settlement (resolution).', true, '2026-09-18 09:23:08.181', '2026-09-18 09:23:08.181', null, null, 'CLOZE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8f3bca64-b03e-4d39-855f-310c3ec58784', 'Physics', 'JAMB', null, 1995, null, 'Which of the following is the dimension of pressure?', null, '["ML⁻¹T⁻²","MLT⁻²","ML²T⁻³","ML⁻³"]', 0, 'Pressure = force/area = MLT⁻²/L² = ML⁻¹T⁻².', true, '2026-10-12 19:15:40.611', '2026-10-12 19:15:40.611', null, null, null, 'Which of the following is the dimension of pressure?', '["ML<sup>-1</sup>T<sup>-2</sup>","MLT<sup>-2</sup>","ML<sup>2</sup>T<sup>-3</sup>","ML<sup>-3</sup>"]', 'Pressure = force/area = MLT<sup>-2</sup>/L<sup>2</sup> = ML<sup>-1</sup>T<sup>-2</sup>.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8f3c5785-9bb3-4ce0-a02a-cdb59b5d4dd2', 'Physics', 'JAMB', null, 1988, null, 'How long will it take a 60 kg man to climb a height of 22 m if he expends energy at the rate of 0.25 kW? [g = 10 m s⁻²]', null, '["5.3 s","34.5 s","41.6 s","52.8 s"]', 3, 'Work = mgh = 60 x 10 x 22 = 13 200 J. Time = work/power = 13 200/250 = 52.8 s.', true, '2026-10-12 19:15:27.158', '2026-10-12 19:15:27.158', null, null, null, 'How long will it take a 60 kg man to climb a height of 22 m if he expends energy at the rate of 0.25 kW? [g = 10 m s<sup>-2</sup>]', '["5.3 s","34.5 s","41.6 s","52.8 s"]', 'Work = mgh = 60 x 10 x 22 = 13 200 J. Time = work/power = 13 200/250 = 52.8 s.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8f428d21-ad55-4e3a-b717-c3b489556a3d', 'English Language', 'JAMB', null, 2007, null, 'The lecturer insisted that every student <u>_______</u> present for the practical examination.', null, '["is","was","be","were","are"]', 2, '''Insisted that'' triggers subjunctive be.', true, '2026-10-24 01:04:25.942', '2026-10-24 01:04:25.942', null, null, null, 'The lecturer insisted that every student <u>_______</u> present for the practical examination.', '["is","was","<u>be</u>","were","are"]', '''<b>Insisted that</b>'' triggers subjunctive <b>be</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8f47a985-3d4f-479b-891a-0521035874f4', 'Literature in English', 'JAMB', null, 2026, null, 'The poet''s relationship with the sea suggests', null, '["fear and hostility","emotional attachment","indifference","rivalry"]', 1, 'The relationship suggests emotional attachment.', true, '2026-09-12 11:12:15.758', '2026-09-12 11:12:15.758', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8f691108-0fb9-4d79-bf89-923afbe0b2aa', 'English Language', 'JAMB', null, 2007, null, 'Two young boys have been caught with parts of the stolen machine but <u>--------------</u> admitted stealing it.', null, '["neither of them has","neither of them have","none of them has","none of them have"]', 0, '''Neither of'' singular â†’ has; two boys â†’ neither.', true, '2026-10-24 01:04:28.229', '2026-10-24 01:04:28.229', null, null, null, 'Two young boys have been caught with parts of the stolen machine but <u>--------------</u> admitted stealing it.', '["<u>neither of them has</u>","neither of them have","none of them has","none of them have"]', '''<b>Neither of</b>'' singular â†’ <b>has</b>; two boys â†’ <b>neither</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8f82c26b-3d92-4d8d-ae69-0cfe241d19a2', 'Physics', 'JAMB', null, 1993, null, 'An aeroplane lands on a runway at a speed of 180 km h⁻¹ and is brought to a stop uniformly in 30 seconds. What distance does it cover on the runway before coming to rest?', null, '["360 m","540 m","750 m","957 m"]', 2, '180 km h⁻¹ = 50 m s⁻¹. Distance = average speed x time = (50/2) x 30 = 750 m.', true, '2026-10-12 19:15:37.055', '2026-10-12 19:15:37.055', null, null, null, 'An aeroplane lands on a runway at a speed of 180 km h<sup>-1</sup> and is brought to a stop uniformly in 30 seconds. What distance does it cover on the runway before coming to rest?', '["360 m","540 m","750 m","957 m"]', '180 km h<sup>-1</sup> = 50 m s<sup>-1</sup>. Distance = average speed x time = (50/2) x 30 = 750 m.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8f82d87a-78cd-46ed-a05e-5329c4e5f77b', 'Physics', 'JAMB', null, 1995, null, 'Two parallel plates at a distance of 8.0 x 10⁻³ m apart are maintained at a p.d. of 600 volts with the negative plate earthed. What is the electric field strength?', null, '["4.8 V m⁻¹","75.0 V m⁻¹","4800.0 V m⁻¹","75 000.0 V m⁻¹"]', 3, 'E = V/d = 600/(8.0 x 10⁻³) = 75 000 V m⁻¹.', true, '2026-10-12 19:15:42.004', '2026-10-12 19:15:42.004', null, null, null, 'Two parallel plates at a distance of 8.0 x 10<sup>-3</sup> m apart are maintained at a p.d. of 600 volts with the negative plate earthed. What is the electric field strength?', '["4.8 V m<sup>-1</sup>","75.0 V m<sup>-1</sup>","4800.0 V m<sup>-1</sup>","75 000.0 V m<sup>-1</sup>"]', 'E = V/d = 600/(8.0 x 10<sup>-3</sup>) = 75 000 V m<sup>-1</sup>.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8f8a9742-c7a3-4d98-afef-762cbf9c3bd3', 'Physics', 'JAMB', null, 1986, null, 'Which of the following is in a neutral equilibrium?', null, '["A heavy weight suspended on a string.","A cone resting on its slant edge.","A heavy based table lamp.","The beam of a balance in use."]', 1, 'A cone lying on its slant side stays at rest in any new position when rolled, with its centre of gravity at the same height. That is neutral equilibrium.', true, '2026-10-12 19:15:22.877', '2026-10-12 19:15:22.877', null, null, null, 'Which of the following is in a neutral equilibrium?', '["A heavy weight suspended on a string.","A cone resting on its slant edge.","A heavy based table lamp.","The beam of a balance in use."]', 'A cone lying on its slant side stays at rest in any new position when rolled, with its centre of gravity at the same height. That is neutral equilibrium.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8f8db1c7-983d-41f0-a26f-1f17848548bf', 'English Language', 'JAMB', null, 2007, null, 'The girl cannot speak with a clear voice; she is always <u>__________</u>', null, '["blabbing","gesticulating","vociferating","stuttering"]', 3, 'Correct spelling: stuttering.', true, '2026-10-24 07:21:39.923', '2026-10-24 07:21:39.923', null, null, null, 'The girl cannot speak with a clear voice; she is always <u>__________</u>', '["blabbing","gesticulating","vociferating","stuttering"]', 'Correct spelling: stuttering.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8f91f12b-2d85-4940-9fb9-26a488fea6f9', 'Physics', 'JAMB', null, 1995, null, 'Total eclipse of the sun occurs when the', null, '["Earth is between the moon and the sun","Sun is between the moon and the earth","Moon is between the sun and the earth","Ozone layer is threatened"]', 2, 'A solar eclipse happens when the moon passes between the sun and the earth, casting its shadow on the earth.', true, '2026-10-12 19:15:41.79', '2026-10-12 19:15:41.79', null, null, null, 'Total eclipse of the sun occurs when the', '["Earth is between the moon and the sun","Sun is between the moon and the earth","Moon is between the sun and the earth","Ozone layer is threatened"]', 'A solar eclipse happens when the moon passes between the sun and the earth, casting its shadow on the earth.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8fa12f8e-7680-490e-b133-257efea0836b', 'English Language', 'JAMB', null, 2007, null, 'Chinyere has not really described the Cabinet as irresponsible; she only <u>__________</u> it in her speech', null, '["alluded to","implied","applied","suggested"]', 0, 'Correct spelling: alluded to.', true, '2026-10-24 07:21:41.032', '2026-10-24 07:21:41.032', null, null, null, 'Chinyere has not really described the Cabinet as irresponsible; she only <u>__________</u> it in her speech', '["alluded to","implied","applied","suggested"]', 'Correct spelling: alluded to.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8fa34b38-75c3-4f16-91e1-1ba3cd2317d9', 'English Language', 'JAMB', null, 2007, null, 'People dislike Jobe because he is a <u>__________</u> young man.', null, '["trickery","tricking","trickful","tricky"]', 3, 'Correct spelling: tricky.', true, '2026-10-24 07:21:34.303', '2026-10-24 07:21:34.303', null, null, null, 'People dislike Jobe because he is a <u>__________</u> young man.', '["trickery","tricking","trickful","tricky"]', 'Correct spelling: tricky.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8fa6fa2d-e331-4b32-a2a0-94dc65aaa3c4', 'Biology', 'JAMB', null, 2026, null, 'Which of these organisms partly digest its food extracellularly?', null, '["Housefly","Cockroach","Termite","Mosquito"]', 0, 'The housefly partly digests its food extracellularly. Houseflies have sponging mouthparts and regurgitate digestive enzymes onto food to start digestion outside the body before sucking up the liquefied food. This is called external or pre-oral digestion. Cockroaches, termites, and mosquitoes digest food internally (intracellularly or inside the gut). The housefly''s method of external digestion is an adaptation for feeding on a variety of semisolid materials. Termites rely on symbiotic microorganisms in their gut for digestion of cellulose.', true, '2026-09-09 03:18:54.322', '2026-09-09 03:18:54.322', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8fc05424-5ffe-4d74-98ab-64cf64348d06', 'Biology', 'JAMB', null, 2011, null, 'During blood transfusion, agglutination may occur as a result of the reaction between', null, '["contrasting antigens and antibodies","two different antigens","two different antibodies","similar antigens and antibodies."]', 3, 'Agglutination occurs due to reaction between similar antigens and antibodies.', true, '2026-10-12 20:59:43.828', '2026-10-12 20:59:43.828', null, null, null, 'During blood transfusion, agglutination may occur as a result of the reaction between', '["contrasting antigens and antibodies","two different antigens","two different antibodies","similar antigens and antibodies."]', 'Agglutination occurs due to reaction between similar antigens and antibodies.', '{"bold":["similar antigens and antibodies"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8fc382e4-ddb6-4734-9df3-6160aa2421c2', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The town was in such <u>a turmoil</u> that the dance was called off.', null, '["state of darkness","state of confusion","rainy state","mourning state"]', 1, 'Turmoil = state of confusion.', true, '2026-10-24 01:01:52.893', '2026-10-24 01:01:52.893', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The town was in such <u>a turmoil</u> that the dance was called off.', '["state of darkness","<u>state of confusion</u>","rainy state","mourning state"]', '<b>Turmoil</b> = <b>state of confusion</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8fc63bfa-0e41-42f3-a908-63dc2cefd491', 'Government', 'JAMB', null, 2026, null, 'The application of the rule of law may be constrained by', null, '["securing the tenure of office of judges","insulating judges from partisan politics","employing men of proven integrity as judges","invoking emergency powers"]', 3, 'Invoking emergency powers can constrain the rule of law.', true, '2026-09-12 11:24:12.603', '2026-09-12 11:24:12.603', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8fc78a54-e279-4974-ad32-3d2be7da1e96', 'English Language', 'JAMB', null, 2024, null, 'Choose the appropriate stress pattern: postulate', null, '["ex-POS-tu-late","ex-pos-TU-late","ex-pos-tu-LATE","EX-pos-tu-late"]', 0, 'The stress in "postulate" is on the second syllable: ex-POS-tu-late.', true, '2026-09-18 09:24:04.956', '2026-09-18 09:24:04.956', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8fccb2e0-6e90-4099-8892-7da7d8fa935e', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. He might be compelled to make a <u>momentous</u> decision.', null, '["a voluntary","a spontaneous","an important","an involuntary"]', 2, 'Momentous = important.', true, '2026-10-24 01:03:59.96', '2026-10-24 01:03:59.96', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. He might be compelled to make a <u>momentous</u> decision.', '["a voluntary","a spontaneous","<u>an important</u>","an involuntary"]', '<b>Momentous</b> = <b>an important</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8fe5209d-16f5-4d31-8566-a18144782b6a', 'English Language', 'JAMB', null, 2007, null, 'It was very easy for the two political parties to form a <u>__________</u> government', null, '["colonial","collusion","coalition","co-operative"]', 2, 'Correct spelling: coalition.', true, '2026-10-24 07:21:39.671', '2026-10-24 07:21:39.671', null, null, null, 'It was very easy for the two political parties to form a <u>__________</u> government', '["colonial","collusion","coalition","co-operative"]', 'Correct spelling: coalition.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8fee3957-dac2-4256-98b9-550bab6b96f1', 'Chemistry', 'JAMB', null, 2026, null, 'Two gases X and Y diffuse at rates 4 cm/s and 1 cm/s respectively. What is the ratio of their molar masses (X : Y)?', null, '["1 : 4","4 : 1","1 : 16","16 : 1"]', 2, 'Graham''s Law: Rate ∝ 1/√M. (Rate X / Rate Y)² = M_Y / M_X. (4/1)² = M_Y / M_X. 16 = M_Y / M_X. So M_X : M_Y = 1 : 16.', true, '2026-09-12 11:32:56.738', '2026-09-12 11:32:56.738', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('8fee5d0d-7db6-4a90-a27d-72b97e57f933', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The effect of rising prices has <u>snowballed</u> considerably.', null, '["risen","decreased","frozen","grown"]', 1, 'Snowballed = increased; opposite = decreased.', true, '2026-10-24 07:21:14.99', '2026-10-24 07:21:14.99', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The effect of rising prices has <u>snowballed</u> considerably.', '["risen","decreased","frozen","grown"]', 'Snowballed = increased; opposite = decreased.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('900df97a-3563-4dab-a319-6fd59dc61747', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. His plans <u>boomeranged</u> on him.', null, '["catapulted","backfired","fell","bounced"]', 1, 'Boomeranged = backfired.', true, '2026-10-24 01:01:53.376', '2026-10-24 01:01:53.376', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. His plans <u>boomeranged</u> on him.', '["catapulted","<u>backfired</u>","fell","bounced"]', '<b>Boomeranged</b> = <b>backfired</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('90100f5d-eb31-4a78-bccb-b09bdc53ff95', 'Biology', 'JAMB', null, 2026, null, 'The sheet of muscle that separates the thoracic and abdominal cavities is the', null, '["Diaphragm","Intercostal muscle","Pleural membrane","Pericardium"]', 0, 'The diaphragm is the sheet of muscle that separates the thoracic and abdominal cavities. It is the primary muscle of respiration. The intercostal muscles are between the ribs and assist with breathing. The pleural membrane covers the lungs. The pericardium covers the heart. The diaphragm is a dome-shaped structure that plays a crucial role in breathing: when it contracts, it flattens, increasing the thoracic cavity volume and causing inhalation. It also contributes to abdominal pressure.', true, '2026-09-09 03:19:03.152', '2026-09-09 03:19:03.152', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('90155129-31d2-4679-a90c-88503f93d00c', 'Economics', 'JAMB', null, 2026, null, 'If the quantity demanded of a commodity increases from 20 units to 30 units when there is an increase in price from $4.00 to $5.00, the elasticity of demand is?', null, '["0.5","2","2.5","0.55"]', 2, 'PED = (10/20)/(1/4) = 0.5/0.25 = 2. Wait, (30-20)/20 = 0.5, (5-4)/4 = 0.25. PED = 0.5/0.25 = 2. The answer is 2, not 2.5. So option B is correct.', true, '2026-09-12 11:01:42.522', '2026-09-12 11:01:42.522', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('90163cf9-195f-4d47-bfee-859a34e6da29', 'General Mathematics', 'JAMB', null, 2026, null, 'In a geometric series the first term is 7 and the last term is 448 and the sum is 889. Find the common ratio', null, '["r = 13","r = 12","r = 2","r = 3"]', 2, 'Sum = a(rⁿ-1)/(r-1) = 889. Last term = arⁿ⁻¹ = 448. 7rⁿ⁻¹ = 448. rⁿ⁻¹ = 64. rⁿ = 64r. 7(64r-1)/(r-1) = 889. 448r - 7 = 889r - 889. 441r = 882. r = 2.', true, '2026-09-12 11:43:42.862', '2026-09-12 11:43:42.862', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('901ac358-840e-4343-8898-43d82c42f50b', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). Hers was <u>a chequered career</u>.', null, '["an interesting and successful career","a career full of sorrow and tears","a bright and memorable career","a career full of ups and downs"]', 3, '''A chequered career'' = full of ups and downs.', true, '2026-10-24 01:04:22.064', '2026-10-24 01:04:22.064', null, null, null, '(Choose the most appropriate interpretation). Hers was <u>a chequered career</u>.', '["an interesting and successful career","a career full of sorrow and tears","a bright and memorable career","<u>a career full of ups and downs</u>"]', '''A <b>chequered career</b>'' = <b>full of ups and downs</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('90388655-04de-47f0-940c-156937d372b3', 'Chemistry', 'JAMB', null, 2026, null, 'Which property is common to all metals?', null, '["Ductility","Electrical conductivity","High melting point","Hardness"]', 1, 'All metals conduct electricity. Ductility, high melting point, and hardness vary among metals.', true, '2026-09-12 11:32:58.522', '2026-09-12 11:32:58.522', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('903a1950-5841-4600-b15e-cc6f01a99859', 'General Mathematics', 'JAMB', null, 2026, null, 'Simplify: 2x² + 3x - 2x² + 5x', null, '["4x² + 8x","8x","4x","8x²"]', 1, '2x² - 2x² = 0. 3x + 5x = 8x.', true, '2026-09-12 11:44:07.153', '2026-09-12 11:44:07.153', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9042a5c0-5d76-4795-9b96-abbc58210fbd', 'Economics', 'JAMB', null, 2026, null, 'The effects on the demand for product A caused by a change in the price of product B is called', null, '["Demand","Cross elasticity of demand","Elasticity of supply","Price elasticity of demand"]', 1, 'Cross elasticity of demand measures how demand for one good responds to price changes in another good.', true, '2026-09-12 10:58:53.413', '2026-09-12 10:58:53.413', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('905197a1-7928-4974-ba56-b15155cab498', 'Literature in English', 'JAMB', null, 2026, null, 'Which imagery is present in: ''Her voice was a soft lullaby in the dark night''?', null, '["Auditory imagery","Visual imagery","Tactile imagery","Organic imagery"]', 0, 'Auditory imagery is present.', true, '2026-09-12 11:11:29.589', '2026-09-12 11:11:29.589', null, null, null, null, null, null, null);
