insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9076aa2b-a26b-4b2b-a0ab-f68c4f7e6758', 'Literature in English', 'JAMB', null, 2026, null, 'A stanza of three lines linked by rhyme is generally called', null, '["a Couplet","a Ballad","a Tercet","a Quatrain"]', 2, 'A three-line stanza is a tercet.', true, '2026-09-12 11:07:29.798', '2026-09-12 11:07:29.798', null, null, null, null, null, null, null);
