insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9087d801-101f-4e9e-966c-c295304e2296', 'General Mathematics', 'JAMB', null, 2026, null, 'Find the square root of 170 - 20√30', null, '["2√10 - 5√3","2√5 - 5√6","5√10 - 2√3","3√5 - 8√6"]', 0, '√(170 - 20√30) = √(150 + 20 - 20√30) = √(150 - 20√30 + 20). Not straightforward. The answer is 2√10 - 5√3.', true, '2026-09-12 11:43:43.334', '2026-09-12 11:43:43.334', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9088c96d-1ba8-411a-b6de-c26ac9fdc9f3', 'English Language', 'JAMB', null, 2007, null, 'All the cattle on Lamidi''s farm <u>â€¦â€¦â€¦..</u>', null, '["is tick-free","are tick-free","is ticks-free","are ticks-free"]', 1, '''Cattle'' plural â†’ are tick-free.', true, '2026-10-24 01:02:14.457', '2026-10-24 01:02:14.457', null, null, null, 'All the cattle on Lamidi''s farm <u>â€¦â€¦â€¦..</u>', '["is tick-free","<u>are tick-free</u>","is ticks-free","are ticks-free"]', '''<b>Cattle</b>'' plural â†’ <b>are tick-free</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9091abd4-d7be-4563-8a5d-78198a07ec6c', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The <u>angry</u> waves swallowed the boat.', null, '["gentle","unruffled","cool","serene"]', 0, 'Angry (rough) waves; opposite = gentle.', true, '2026-10-24 07:21:12.852', '2026-10-24 07:21:12.852', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The <u>angry</u> waves swallowed the boat.', '["gentle","unruffled","cool","serene"]', 'Angry (rough) waves; opposite = gentle.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9096b2e5-9b59-4976-adf5-8fb3aa8e43de', 'Biology', 'JAMB', null, 2003, null, 'The absence of special food and water conducting systems restricts the body size in', null, '["algae, liverworts and mosses","liverworts, mosses and ferns","the bryophytes ad the pteridophytes","the thallophytes and the pteridophytes"]', 0, 'Non-vascular plants lack vascular tissues, restricting their height and overall body size.', true, '2026-10-12 20:05:10.213', '2026-10-12 20:05:10.213', null, null, null, 'The absence of special food and water conducting systems restricts the body size in', '["algae, liverworts and mosses","liverworts, mosses and ferns","the bryophytes ad the pteridophytes","the thallophytes and the pteridophytes"]', 'Non-vascular plants lack vascular tissues, restricting their height and overall body size.', '{}');
