insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('90aa2e1d-f56c-4e72-91eb-209e68a979d4', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The builder''s taste reflected <u>superfluous</u> grandeur.', null, '["excellent","superlative","expensive","too much"]', 3, 'Superfluous = too much.', true, '2026-10-24 01:01:44.102', '2026-10-24 01:01:44.102', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The builder''s taste reflected <u>superfluous</u> grandeur.', '["excellent","superlative","expensive","<u>too much</u>"]', '<b>Superfluous</b> = <b>too much</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('90b5aa5f-2332-4e93-9e96-1ec467aae1b0', 'Literature in English', 'JAMB', null, 2026, null, 'The speaker is', null, '["Menas","Pompey","Caesar","Anthony"]', 1, 'The speaker is Pompey.', true, '2026-09-12 11:14:06.308', '2026-09-12 11:14:06.308', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('90b5e11a-dab0-4239-8ea5-e77e7fed47d6', 'Government', 'JAMB', null, 2026, null, 'A system of government in which a single person or a group who governs has unlimited power is a', null, '["oligarchy","republican","aristocracy","autocracy"]', 3, 'Autocracy is a system where a single person or group has unlimited power.', true, '2026-09-12 11:24:32.135', '2026-09-12 11:24:32.135', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('90b6a648-c958-4d9c-a076-b54b2c56972c', 'Physics', 'JAMB', null, 2026, null, 'One major reason why electrical appliances in homes are normally earthed is that the', null, '["none","appliances are maintained at a higher p.d. than the earth","Person touching the appliance is safe from electric shock","appliances are maintained at the same p.d. with that of the earth"]', 2, 'Electrical appliances are earthed so that a person touching the appliance is safe from electric shock. Earthing provides a low-resistance path to the ground. If a fault occurs and the metal casing becomes live, the current flows to earth rather than through a person touching the appliance, preventing electric shock.', true, '2026-09-10 10:56:38.271', '2026-09-10 10:56:38.271', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('90bef590-628a-44ca-b226-7ec2deb11400', 'Literature in English', 'JAMB', null, 2026, null, 'A poem that is shaped in the image of the object it talks about is', null, '["concrete","Lyrical","Metaphysical","Romantic"]', 0, 'A concrete poem is shaped like its subject.', true, '2026-09-12 11:11:02.916', '2026-09-12 11:11:02.916', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('90c84405-b0f4-4a1b-a0f3-bad3416c998d', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). He is <u>a clinging child</u>.', null, '["He is a handsome young man.","He is possessive","He likes to cling with his sister","He is a bully"]', 1, '''Clinging'' = possessive.', true, '2026-10-24 01:04:23.293', '2026-10-24 01:04:23.293', null, null, null, '(Choose the most appropriate interpretation). He is <u>a clinging child</u>.', '["He is a handsome young man.","<u>He is possessive</u>","He likes to cling with his sister","He is a bully"]', '''<b>Clinging</b>'' = <b>possessive</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('90c9a780-721b-4984-b71d-580030975853', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. She said boxing is <u>in fact her pet aversion</u>.', null, '["something she likes very much","something she dislikes very much","a hobby she loves to pursue","one thing she can''t miss"]', 1, 'Pet aversion = something she dislikes very much.', true, '2026-10-24 01:01:49.022', '2026-10-24 01:01:49.022', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. She said boxing is <u>in fact her pet aversion</u>.', '["something she likes very much","<u>something she dislikes very much</u>","a hobby she loves to pursue","one thing she can''t miss"]', '<b>Pet aversion</b> = <b>something she dislikes very much</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('90d11b17-2737-49f9-a0d8-e05d76968348', 'Biology', 'JAMB', null, 2013, null, 'The long and sharp clawed feet of birds is an adaptation for', null, '["Tearing flesh","Grasping prey","Crushing seeds","Scooping mud"]', 1, 'Long and sharp clawed feet are adapted for grasping prey.', true, '2026-10-12 20:59:46.723', '2026-10-12 20:59:46.723', null, null, null, 'The long and sharp clawed feet of birds is an adaptation for', '["Tearing flesh","Grasping prey","Crushing seeds","Scooping mud"]', 'Long and sharp clawed feet are adapted for grasping prey.', '{"bold":["grasping prey"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('90db0b74-531c-4244-8499-51941e18492c', 'Physics', 'JAMB', null, 2026, null, 'A plastic object floats in water with 0.6 of its volume submerged and in oil with 0.75 of its volume submerged. The density of the oil is', null, '["750kgm⁻³","800kgm⁻³","1000kgm⁻³","1250kgm⁻³"]', 1, 'For water: ρ_object = 0.6 × 1000 = 600 kg/m³. For oil: ρ_object = 0.75 × ρ_oil. 600 = 0.75 × ρ_oil. ρ_oil = 600/0.75 = 800 kg/m³.', true, '2026-09-10 10:56:42.656', '2026-09-10 10:56:42.656', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('90df9de9-62c8-45f7-95f9-ab9132e431ed', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'According to Jesus, what defiles a person?', null, '["words that come out of the mouth","sinful thoughts","faithlessness","touching a leper"]', 0, 'Jesus said what comes out of the mouth defiles a person.', true, '2026-09-12 10:40:57.82', '2026-09-12 10:40:57.82', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('90f072c9-ba6a-4b4b-b988-0e7488b50893', 'General Mathematics', 'JAMB', null, 2026, null, 'A tower and a building stand on the same horizontal level. From the point P at the bottom of the building the angle of elevation of the top T of the tower is 65°. From the top Q of the building, the angle of elevation of the point T is 25°. If the building is 20m high, calculate the distance PT', null, '["18.5m","25.6m","28.3m","33.2m","67.5m"]', 2, 'Using trigonometry: PT = 20/sin(65° - 25°) = 20/sin40° = 20/0.6428 = 31.1m. The closest is 28.3m.', true, '2026-09-12 11:43:41.494', '2026-09-12 11:43:41.494', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('90fd74c0-fa75-4734-a7b1-9b5502837aac', 'General Mathematics', 'JAMB', null, 2026, null, 'Find the sum of the range and mode of the set of numbers 10,9,10,9,8,7,7,10,8,10,8,4,6,9,10,9,10,9,7,10,6,5', null, '["16","14","12","15"]', 1, 'Range = 10-4 = 6. Mode = 10. Sum = 16. The answer is (A) 16.', true, '2026-09-12 11:43:58.135', '2026-09-12 11:43:58.135', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('90fe5589-5952-49c0-892a-23036f87dc0c', 'Physics', 'JAMB', null, 1984, null, 'Which of the following can be described as high tension transmission?', null, '["High resistance and low voltage","Low current and high voltage","High current and low voltage","High voltage and zero current","High current and low resistance."]', 1, 'High tension transmission uses high voltage and low current to reduce I²R power loss in the cables.', true, '2026-10-12 19:15:18.856', '2026-10-12 19:15:18.856', null, null, null, 'Which of the following can be described as high tension transmission?', '["High resistance and low voltage","Low current and high voltage","High current and low voltage","High voltage and zero current","High current and low resistance."]', 'High tension transmission uses high voltage and low current to reduce I<sup>2</sup>R power loss in the cables.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('91006e31-2200-4c29-ad07-269c9031728f', 'Literature in English', 'JAMB', null, 2026, null, 'Which of the following poetic devices is mostly used to praise the subject of the poem?', null, '["imagery","alliteration","hyperbole","apostrophe"]', 2, 'Hyperbole is mostly used to praise the subject.', true, '2026-09-12 11:05:38.078', '2026-09-12 11:05:38.078', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9122911a-283b-4c3c-9c9c-c9497605f030', 'English Language', 'JAMB', null, 2007, null, 'She has the <u>__________</u> of being intelligent, when in fact she is not.', null, '["elision","illusion","delusion","allusion"]', 2, 'Correct spelling and meaning: delusion.', true, '2026-10-24 07:21:34.606', '2026-10-24 07:21:34.606', null, null, null, 'She has the <u>__________</u> of being intelligent, when in fact she is not.', '["elision","illusion","delusion","allusion"]', 'Correct spelling and meaning: delusion.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('91284fd4-b351-4027-ab54-17a813e2131c', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). The presence of the security men in the area will provide <u>a moment of respite</u> to the residents.', null, '["soothing relaxation","enduring reprieve","lasting security","temporary relief"]', 3, '''A moment of respite'' = temporary relief.', true, '2026-10-24 01:02:08.924', '2026-10-24 01:02:08.924', null, null, null, '(Choose the most appropriate interpretation). The presence of the security men in the area will provide <u>a moment of respite</u> to the residents.', '["soothing relaxation","enduring reprieve","lasting security","<u>temporary relief</u>"]', '''A <b>moment of respite</b>'' = <b>temporary relief</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('912aafc7-cd07-465f-ad20-c0460b046d6d', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'What did God use to confirm His promise to Abraham in Genesis 15?', null, '["thunder and lightning","a rainbow","a flaming torch and a smoking firepot","a burning bush"]', 2, 'God passed between the divided animal pieces as a flaming torch and smoking firepot.', true, '2026-09-12 10:40:58.716', '2026-09-12 10:40:58.716', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('912ce832-5c4f-4818-8e9e-7ab9e23341fd', 'Financial Accounting', 'UTME', null, 2004, null, 'Earnings per share is measured of', null, '["solvency","leverage","liquidity","profitability"]', 3, 'Earning per share measures the net returns on investment. Earning per share = Profit after tax / Equity.', true, '2026-10-12 22:00:03.919', '2026-10-12 22:00:03.919', null, null, null, 'Earnings per share is measured of', '["solvency","leverage","liquidity","<b>profitability</b>"]', 'Earning per share measures the net returns on investment. Earning per share = Profit after tax / Equity, measuring <b>profitability</b>.', '{"bold":["profitability"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9139cfcb-f3b8-465f-84f9-959c2232c72c', 'Physics', 'JAMB', null, 2003, null, 'A ray of light is incident on an equilateral triangular glass prism of refractive index 3/2. Calculate the angle through which the ray is minimally deviated in the prism.', null, '["37.2°","48.6°","30.0°","42.0°"]', 0, 'n = sin((A + D)/2)/sin(A/2). 1.5 = sin((60° + D)/2)/sin 30°, so sin((60° + D)/2) = 0.75. (60° + D)/2 = 48.6°, so D = 37.2°.', true, '2026-10-12 19:15:57.09', '2026-10-12 19:15:57.09', null, null, null, 'A ray of light is incident on an equilateral triangular glass prism of refractive index 3/2. Calculate the angle through which the ray is minimally deviated in the prism.', '["37.2°","48.6°","30.0°","42.0°"]', 'n = sin((A + D)/2)/sin(A/2). 1.5 = sin((60° + D)/2)/sin 30°, so sin((60° + D)/2) = 0.75. (60° + D)/2 = 48.6°, so D = 37.2°.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('914a43d8-def3-4eb2-90fc-178141b00876', 'Christian Religious Studies', 'JAMB', null, 2026, null, '''O Lord of hosts, if thou will give to thy maidservant a son, then I will give him to the Lord all the days of his life, and no razor shall touch his head.'' Who said this?', null, '["Sarah","Rachael","Hannah","Samson''s mother"]', 2, 'Hannah prayed this prayer for a son, Samuel.', true, '2026-09-12 10:41:39.364', '2026-09-12 10:41:39.364', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('915b11e2-ba0d-40e0-a437-ead449ac5703', 'English Language', 'JAMB', null, 2007, null, 'Three quarters of the Physics class <u>---------</u> dramatically.', null, '["improve","improves","are improving","is improving"]', 1, 'Collective ''class'' â†’ singular improves.', true, '2026-10-24 01:04:26.959', '2026-10-24 01:04:26.959', null, null, null, 'Three quarters of the Physics class <u>---------</u> dramatically.', '["improve","<u>improves</u>","are improving","is improving"]', 'Collective ''<b>class</b>'' â†’ singular <b>improves</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('916f4ecd-2a35-413c-ab77-bbd281195623', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The festivals create in the people a feeling of pride in their cultural <u>heritage</u>.', null, '["legacy","possession","history","heirloom"]', 0, 'Heritage = legacy.', true, '2026-10-24 01:01:52.947', '2026-10-24 01:01:52.947', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The festivals create in the people a feeling of pride in their cultural <u>heritage</u>.', '["<u>legacy</u>","possession","history","heirloom"]', '<b>Heritage</b> = <b>legacy</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('917a3272-c879-40d0-b2b1-3cdf9a0e4f0a', 'Physics', 'JAMB', null, 1993, null, 'A current-carrying conductor experiences a force when placed in a magnetic field because the', null, '["Conductor is magnetized","Magnetic field of the current interacts with external magnetic field.","Force is due to the motor principle","Electric field of the current interacts with the external magnetic field."]', 1, 'The current produces its own magnetic field, which interacts with the external field and results in a force on the conductor.', true, '2026-10-12 19:15:38.187', '2026-10-12 19:15:38.187', null, null, null, 'A current-carrying conductor experiences a force when placed in a magnetic field because the', '["Conductor is magnetized","Magnetic field of the current interacts with external magnetic field.","Force is due to the motor principle","Electric field of the current interacts with the external magnetic field."]', 'The current produces its own magnetic field, which interacts with the external field and results in a force on the conductor.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('917a92c2-7028-4a2f-b6ae-f651f1ec9b45', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Joshua''s first victory was over the people of', null, '["Ai","Gibeon","Gilgal","Jericho"]', 3, 'Joshua''s first victory was over the people of Jericho. After crossing the Jordan, the Israelites conquered Jericho first, with God miraculously causing the walls to fall.', true, '2026-09-12 09:46:08.643', '2026-09-12 09:46:08.643', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('91824f9a-279c-4e49-9ba8-2d48ad6d48bd', 'Biology', 'JAMB', null, 2005, null, 'Which of the following is likely to have a higher concentration of mitochondria?', null, '["sperm cell","white blood cell","egg cell","red blood cell"]', 0, 'Sperm cells require high energy for locomotion.', true, '2026-10-12 20:59:36.291', '2026-10-12 20:59:36.291', null, null, null, 'Which of the following is likely to have a higher concentration of mitochondria?', '["sperm cell","white blood cell","egg cell","red blood cell"]', 'Sperm cells require high energy for locomotion.', '{"bold":["Sperm cells"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('91856c25-8f87-4a17-a0eb-776bbf503fc0', 'Chemistry', 'JAMB', null, 2026, null, 'Which of the following changes will increase the value of Kc for a reversible reaction?', null, '["Increasing temperature for an endothermic reaction","Decreasing pressure","Adding a catalyst","Increasing concentration of reactants"]', 0, 'The equilibrium constant (Kc) is only altered by temperature changes. For an endothermic reaction, increasing temperature shifts equilibrium right, increasing Kc.', true, '2026-09-09 17:12:48.26', '2026-09-09 17:12:48.26', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('91948a08-7351-4bb5-bdcd-59917c31a428', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Amos condemned the women of Samaria and called them of Bashan', null, '["Beasts","Cows","goats","Dogs","Sheep"]', 1, 'Amos called them ''cows of Bashan'' (Amos 4:1).', true, '2026-09-12 10:42:08.327', '2026-09-12 10:42:08.327', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('91a4d65a-ee1e-4be3-84d6-f8b498fe1058', 'English Language', 'JAMB', null, 2007, null, 'The visitor was very uncomfortable because of his <u>__________</u> nose', null, '["runny","running","watery","flowing"]', 0, 'Correct spelling: runny.', true, '2026-10-24 07:21:45.224', '2026-10-24 07:21:45.224', null, null, null, 'The visitor was very uncomfortable because of his <u>__________</u> nose', '["runny","running","watery","flowing"]', 'Correct spelling: runny.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('91a4d9f8-ab42-4ce0-8fc0-cbc6e4ebd95e', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Agoshito is a <u>callow</u> youth; said the teacher.', null, '["an ignorant","an experienced","an idle","an organized"]', 1, 'Callow = inexperienced; opposite = experienced.', true, '2026-10-24 07:21:29.421', '2026-10-24 07:21:29.421', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Agoshito is a <u>callow</u> youth; said the teacher.', '["an ignorant","an experienced","an idle","an organized"]', 'Callow = inexperienced; opposite = experienced.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('91b7f837-9e45-4bdb-ab6b-c67450067c26', 'Physics', 'JAMB', null, 1987, null, 'If an object is placed in front of two mirrors inclined at 90°, how many images will be formed?', null, '["Five","Four","Three","Two."]', 2, 'Number of images = 360°/θ - 1 = 360/90 - 1 = 3.', true, '2026-10-12 19:15:25.924', '2026-10-12 19:15:25.924', null, null, null, 'If an object is placed in front of two mirrors inclined at 90°, how many images will be formed?', '["Five","Four","Three","Two."]', 'Number of images = 360°/θ - 1 = 360/90 - 1 = 3.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('91cbed9e-858f-44a9-b906-0708a2c3f4a2', 'Chemistry', 'JAMB', null, 2026, null, 'During electrolysis of molten lead(II) iodide, iodine is liberated at the anode because', null, '["iodide ions lose electrons","iodine atoms gain electrons","lead ions lose electrons","iodine molecules gain protons"]', 0, 'At the anode, oxidation occurs. Iodide ions (I⁻) lose electrons to form iodine molecules: 2I⁻ → I₂ + 2e⁻. Lead ions (Pb²⁺) gain electrons at the cathode to form lead metal.', true, '2026-09-12 09:38:10.084', '2026-09-12 09:38:10.084', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('91d91456-c7e1-4df2-9584-447096aa472c', 'English Language', 'JAMB', null, 2024, null, 'The author of The Lekki Headmaster is?', null, '["Kabir Alabi Garba","Kabir Alabi Garuba","Kabir Alani Garba","Kabir Alabi Gabar"]', 0, 'The author is Kabir Alabi Garba.', true, '2026-09-18 09:43:02.731', '2026-09-18 09:43:02.731', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('91f293ae-9f2d-4221-b770-19c4189188fe', 'Chemistry', 'JAMB', null, 2026, null, 'The main impurity in iron ore during extraction of iron is', null, '["SO₂","CO₂","CaSiO₃","SO"]', 2, 'CaSiO₃ (slag) is the main impurity removed during iron extraction.', true, '2026-09-12 11:36:02.7', '2026-09-12 11:36:02.7', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('91f8e204-8423-4411-a912-046997b823bf', 'Economics', 'JAMB', null, 2026, null, 'Economic efficiency means: (i) obtaining maximum output from available resources (ii) equitable distribution of nation''s resources (iii) carrying out production without any waste (iv) producing the maximum output from available resources at the lowest possible cost (v) efficient utilisation of the nation''s resources', null, '["I and v only","ii only","iv and v only","iv only"]', 2, 'Economic efficiency is best defined as producing the maximum output from available resources at the lowest possible cost (iv) and efficient utilisation of the nation''s resources (v). Economic efficiency occurs when resources are allocated to produce the greatest possible satisfaction of wants. It involves both technical efficiency (producing at lowest cost) and allocative efficiency (producing what consumers want).', true, '2026-09-10 10:41:19.862', '2026-09-10 10:41:19.862', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('92048837-73c7-4d80-bf36-5a2add6143fc', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Adebayo''s plans for the future are <u>in the air</u>.', null, '["suspended","uncertain","empty","floating"]', 1, 'In the air = uncertain.', true, '2026-10-24 01:04:00.121', '2026-10-24 01:04:00.121', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Adebayo''s plans for the future are <u>in the air</u>.', '["suspended","<u>uncertain</u>","empty","floating"]', '<b>In the air</b> = <b>uncertain</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9208a934-8e5f-4b0e-8f24-76f63170d7b8', 'Literature in English', 'JAMB', null, 2026, null, 'In the play, why does Mark Antony initially neglect his duties in Rome?', null, '["He is ill and unable to travel","He is deeply engrossed in his love for Cleopatra","He fears political enemies in Rome","He is planning a secret military attack"]', 1, 'Antony neglects his duties because he is engrossed in his love for Cleopatra.', true, '2026-09-12 11:04:30.849', '2026-09-12 11:04:30.849', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('921467a2-b5ce-47c6-97de-2652f3fe366d', 'Literature in English', 'JAMB', null, 2026, null, 'The role of the Storyteller in the play primarily serves to', null, '["Represent colonial authority and control","Provide comic relief without influencing the plot","Bridge the gap between the audience and the dramatic action through commentary and direction","Act as a silent observer of events"]', 2, 'The Storyteller bridges the gap between the audience and the dramatic action.', true, '2026-09-12 11:04:35.244', '2026-09-12 11:04:35.244', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9223c71c-7f68-45d1-a1e2-811db989be2c', 'Literature in English', 'JAMB', null, 2026, null, 'Dionysus is', null, '["The Greek god of wine and fertility","The Greek god of war","The Greek god of wisdom","The Greek god of the sea"]', 0, 'Dionysus is the Greek god of wine and fertility. He was also associated with ritual madness, ecstasy, and theatre. The festivals of Dionysus, where goats were sacrificed and songs were sung, were the origins of Greek tragedy and comedy. Dionysus is one of the most important figures in the history of drama.', true, '2026-09-10 10:47:53.776', '2026-09-10 10:47:53.776', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('922cbf8d-377b-483a-b4b5-9afe217f25c2', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. His father is a <u>shrewd</u> businessman.', null, '["gullible","orderly","reliable","resourceful"]', 0, 'Shrewd = astute; opposite = gullible.', true, '2026-10-24 07:21:17.96', '2026-10-24 07:21:17.96', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. His father is a <u>shrewd</u> businessman.', '["gullible","orderly","reliable","resourceful"]', 'Shrewd = astute; opposite = gullible.', '{}');
