insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('92376867-2b74-4394-ab35-b3e7a455fd60', 'Government', 'JAMB', null, 2026, null, 'In which system of government does the state require the control of everything and allow no opposition', null, '["Feudalism","Totalitarian","Communism","Socialism"]', 1, 'Totalitarian system controls everything and allows no opposition.', true, '2026-09-12 11:24:19.503', '2026-09-12 11:24:19.503', null, null, null, null, null, null, null);
