insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('925ea417-f7a1-4601-9ffa-e704de0fdde1', 'Biology', 'JAMB', null, 2002, null, 'Tissue respiration is important for the', null, '["absorption of oxygen into the alveoli","release of carbon(IV)oxide into the lungs","release of energy for the body use","exhalation of carbon(IV)oxide from the lungs"]', 2, 'Tissue respiration releases energy for body use.', true, '2026-10-12 20:59:31.627', '2026-10-12 20:59:31.627', null, null, null, 'Tissue respiration is important for the', '["absorption of oxygen into the alveoli","release of carbon(IV)oxide into the lungs","release of energy for the body use","exhalation of carbon(IV)oxide from the lungs"]', 'Tissue respiration releases energy for body use.', '{"bold":["releases energy for body use"],"italic":[],"underline":[],"fillBlanks":[]}');
