insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('92f97777-ff0a-43b2-a219-720d9e63b06a', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Some drugs have <u>deleterious</u> effect on a child''s development.', null, '["debilitating","helpful","harmful","healing"]', 2, 'Deleterious = harmful.', true, '2026-10-24 01:04:10.256', '2026-10-24 01:04:10.256', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Some drugs have <u>deleterious</u> effect on a child''s development.', '["debilitating","helpful","<u>harmful</u>","healing"]', '<b>Deleterious</b> = <b>harmful</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('930106cc-36d2-49cb-96a7-47c18e512a56', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Only those who are <u>gullible</u> fall victim to his trickery.', null, '["saucy","devastated","courteous","astute"]', 3, 'Gullible = credulous; opposite = astute.', true, '2026-10-24 07:21:23.765', '2026-10-24 07:21:23.765', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Only those who are <u>gullible</u> fall victim to his trickery.', '["saucy","devastated","courteous","astute"]', 'Gullible = credulous; opposite = astute.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('930787c7-54de-47cc-8bbe-215104cd7bc8', 'Physics', 'JAMB', null, 1997, null, 'In a purely inductive circuit, the current', null, '["Lags behind the voltage in phase by 90°","Leads the voltage in phase by 90°","Is in the same phase with the voltage","Leads the voltage by 180°."]', 0, 'In a pure inductor the current lags the applied voltage by 90°.', true, '2026-10-12 19:15:44.494', '2026-10-12 19:15:44.494', null, null, null, 'In a purely inductive circuit, the current', '["Lags behind the voltage in phase by 90°","Leads the voltage in phase by 90°","Is in the same phase with the voltage","Leads the voltage by 180°."]', 'In a pure inductor the current lags the applied voltage by 90°.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('93088514-8f4f-442e-af70-baf07a582dc6', 'Biology', 'JAMB', null, 2026, null, 'Millipede and earthworm are', null, '["Decomposers","heterotrophs","detritivores","consumers"]', 2, 'Millipedes and earthworms are detritivores, meaning they feed on dead organic matter (detritus). They ingest decomposing plant and animal material and play a crucial role in nutrient cycling by breaking down organic matter and returning nutrients to the soil. Decomposers (like fungi and bacteria) break down organic matter extracellularly and absorb nutrients directly. Heterotrophs are organisms that cannot produce their own food (includes all animals, fungi, and some bacteria). Consumers are a broader category that includes herbivores, carnivores, omnivores, and detritivores. Detritivore is the most specific correct classification.', true, '2026-09-09 03:18:38.42', '2026-09-09 03:18:38.42', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('930e8f20-3532-41bf-8a4d-c045ef1a5a57', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). The new Vice-Chancellor''s immediate concern was to <u>tide over the major difficulties of the moment</u>.', null, '["temporarily accommodate","permanently handle","decisively solve","pretend to solve"]', 0, '''Tide over'' = cope temporarily.', true, '2026-10-24 01:02:07.811', '2026-10-24 01:02:07.811', null, null, null, '(Choose the most appropriate interpretation). The new Vice-Chancellor''s immediate concern was to <u>tide over the major difficulties of the moment</u>.', '["<u>temporarily accommodate</u>","permanently handle","decisively solve","pretend to solve"]', '''<b>Tide over</b>'' = <b>cope temporarily</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9318ab90-d59a-4358-bcff-64b58c33de5e', 'Physics', 'JAMB', null, 2026, null, 'What is not a unit of momentum?', null, '["kgm/s","Ns","Pa","b&c","c only"]', 2, 'The unit of momentum is kgm/s or Ns. Pa (pascal) is the unit of pressure, not momentum. So the answer is Pa (c only).', true, '2026-09-10 10:56:48.453', '2026-09-10 10:56:48.453', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9319eccb-0cf8-4597-8137-6b55a15cecca', 'General Mathematics', 'JAMB', null, 2026, null, 'Find the circumference of a circle with diameter 14 cm. (π = 22/7)', null, '["22 cm","34 cm","44 cm","54 cm"]', 2, 'C = πd = (22/7)(14) = 44 cm.', true, '2026-09-12 11:44:12.486', '2026-09-12 11:44:12.486', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('931ea339-da50-4782-a5e1-acdf0fd8cc36', 'English Language', 'JAMB', null, 2007, null, 'Three-quarters of the church <u>__________</u> painted by members the previous day', null, '["were","was","is","are"]', 1, 'Singular ''church'' past â†’ was.', true, '2026-10-24 01:02:14.512', '2026-10-24 01:02:14.512', null, null, null, 'Three-quarters of the church <u>__________</u> painted by members the previous day', '["were","<u>was</u>","is","are"]', 'Singular ''<b>church</b>'' past â†’ <b>was</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('93203e3d-c3d5-4bdc-9bbf-01c7cc820b9f', 'Biology', 'JAMB', null, 2003, null, 'The most common characteristic of the fungal hyphae is the possession of', null, '["cell-like compartments with one nucleus each","cell walls that are both rigid and chitinous","a multicellular mycelium in the substrate","cell-like partitions formed by cross-walls"]', 1, 'Fungal cell walls are characteristically rigid and composed of chitin.', true, '2026-10-12 20:05:10.313', '2026-10-12 20:05:10.313', null, null, null, 'The most common characteristic of the fungal hyphae is the possession of', '["cell-like compartments with one nucleus each","cell walls that are both rigid and chitinous","a multicellular mycelium in the substrate","cell-like partitions formed by cross-walls"]', 'Fungal cell walls are characteristically rigid and composed of chitin.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9327184e-117a-4d3c-af8c-38a0893462d4', 'Biology', 'JAMB', null, 2026, null, 'The first four children of a couple were all girls. The probability that the fifth will also be a girl is', null, '["1/5","1/4","1/3","1/2"]', 3, 'The probability that the fifth child will also be a girl is 1/2 (50%). Each pregnancy is an independent event. The sex of each child is determined by the sperm that fertilizes the egg. The chance of having a girl is always 50% (the father''s sperm carries either X or Y chromosome). Previous births do not affect the probability of future births. This is a common probability misconception.', true, '2026-09-09 03:19:27.853', '2026-09-09 03:19:27.853', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9339e137-4cbc-4857-9d51-4a9f752f8411', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. As the triumphant rebels were returning to their base, they met with <u>a serious reverse</u>.', null, '["an enemy","an army","a victory","a defeat"]', 3, 'A reverse = a defeat.', true, '2026-10-24 01:01:51.135', '2026-10-24 01:01:51.135', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. As the triumphant rebels were returning to their base, they met with <u>a serious reverse</u>.', '["an enemy","an army","a victory","<u>a defeat</u>"]', 'A <b>reverse</b> = <b>a defeat</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('933aee10-1f1f-44b3-b148-e47155ba6557', 'Biology', 'JAMB', null, 0, null, 'answer the question above ', 'https://res.cloudinary.com/kwi1uv0g/image/upload/v1791839268/questions/twuvyyx28abuvxim7q2x.jpg', '["a","b","c","d"]', 0, 'In the food web, vegetation acts as the producer.   Primary consumers (herbivores) like the grasshopper and rabbit feed on the vegetation.   Secondary consumers (like the lizard) feed on the primary consumers.   The hawk feeds on secondary consumers (such as the lizard), placing it at the tertiary consumer level.   ', true, '2026-10-12 21:08:30.127', '2026-10-12 21:08:30.127', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('934a5b07-e4ee-407c-8423-9e9ab6ba197e', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The dispute between the two countries has resulted in the <u>severing</u> of diplomatic relations', null, '["breaking","securing","swapping","strengthening"]', 0, 'Severing = breaking.', true, '2026-10-24 01:02:00.14', '2026-10-24 01:02:00.14', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The dispute between the two countries has resulted in the <u>severing</u> of diplomatic relations', '["<u>breaking</u>","securing","swapping","strengthening"]', '<b>Severing</b> = <b>breaking</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('93517510-bb71-4b9e-adb3-0d1324450080', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. He is <u>credulous</u>.', null, '["credible","creditable","gullible","fallible"]', 2, 'Credulous = gullible.', true, '2026-10-24 01:03:58.994', '2026-10-24 01:03:58.994', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. He is <u>credulous</u>.', '["credible","creditable","<u>gullible</u>","fallible"]', '<b>Credulous</b> = <b>gullible</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9362b44b-65a7-4dfa-8309-c29f1e5f17ca', 'Physics', 'JAMB', null, 1984, null, 'A plane inclined at an angle of 30° to the horizontal has an efficiency of 60%. The force parallel to the plane required to push a load of 120 N uniformly up the plane is', null, '["60 N","100 N","120 N","200 N","240 N"]', 1, 'VR = 1/sin 30° = 2. Efficiency = MA/VR, so MA = 0.6 x 2 = 1.2. Effort = load/MA = 120/1.2 = 100 N.', true, '2026-10-12 19:15:19.289', '2026-10-12 19:15:19.289', null, null, null, 'A plane inclined at an angle of 30° to the horizontal has an efficiency of 60%. The force parallel to the plane required to push a load of 120 N uniformly up the plane is', '["60 N","100 N","120 N","200 N","240 N"]', 'VR = 1/sin 30° = 2. Efficiency = MA/VR, so MA = 0.6 x 2 = 1.2. Effort = load/MA = 120/1.2 = 100 N.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9363213b-5150-4f2f-a32b-5a139ff0cebc', 'Biology', 'JAMB', null, 2026, null, 'A flowering plant having both male and female flowers on the same plant is said to be', null, '["dioecious","irregular","regular","monoecious"]', 3, 'A monoecious plant has both male (staminate) and female (pistillate) flowers on the same individual plant. Examples include maize (corn), cucurbits (cucumbers, squash), and oak trees. Dioecious plants have male and female flowers on separate plants (e.g., holly, papaya). Regular and irregular refer to the symmetry of flowers, not the distribution of sexes. Monoecy is an adaptation that promotes cross-pollination while allowing for some self-pollination if necessary, reducing the need for separate male and female plants.', true, '2026-09-09 03:18:19.653', '2026-09-09 03:18:19.653', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('936f6c9e-8646-45fc-9e72-7f625394b3e0', 'Yoruba', 'JAMB', null, 2007, null, 'Ìwé Àkójópò Ewi Alohùn Yorùbá ni ìbéèrè 29-31 dá lé. Nínú Èfè, kí ni àyírí ìyàwó ògá Súlè tí òkòrin tú?', null, '["Ó rí òba fín","Ó p fè òba","Ó jalè lòjà Jọǹà","Ó jowú gbàgbé ayò."]', 2, 'Àyírí ìyàwó ògá Súlè tí òkòrin tú ni pé ó jalè lòjà Jọǹà.', true, '2026-10-13 13:23:31.905', '2026-10-13 13:23:31.905', null, null, null, 'Ìwé Àkójópò Ewi Alohùn Yorùbá ni ìbéèrè 29-31 dá lé. Nínú Èfè, kí ni àyírí ìyàwó ògá Súlè tí òkòrin tú?', '["Ó rí òba fín","Ó p fè òba","Ó jalè lòjà Jọǹà","Ó jowú gbàgbé ayò."]', 'Àyírí ìyàwó ògá Súlè tí òkòrin tú ni pé ó jalè lòjà Jọǹà.', '{"bold":["ó jalè lòjà Jọǹà"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9385bc4b-3893-4605-b097-d641973b1268', 'Physics', 'JAMB', null, 1989, null, 'Eight alpha decays and six beta decays are necessary before an atom of ²³⁸₉₂U achieves stability. The final product in the chain has an atomic number of', null, '["70","78","82","90."]', 2, 'Each alpha decay lowers Z by 2 and each beta decay raises it by 1: Z = 92 - 8 x 2 + 6 = 82 (lead).', true, '2026-10-12 19:15:30.279', '2026-10-12 19:15:30.279', null, null, null, 'Eight alpha decays and six beta decays are necessary before an atom of <sup>238</sup><sub>92</sub>U achieves stability. The final product in the chain has an atomic number of', '["70","78","82","90."]', 'Each alpha decay lowers Z by 2 and each beta decay raises it by 1: Z = 92 - 8 x 2 + 6 = 82 (lead).', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('93883333-876b-40c3-bbb4-03cd1a4a69be', 'English Language', 'JAMB', null, 2024, null, 'From the passage, it can be deduced that', null, '["conflicts are noted for facilitating opportunities","all nations adopt the peaceful approach","prevailing circumstances push a warring nation to sue for peace","all nations prefer the military option"]', 2, 'The passage suggests that circumstances determine which conflict management approach is used.', true, '2026-09-18 09:43:02.742', '2026-09-18 09:43:02.742', null, null, 'COMPREHENSION', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('938db210-a225-4156-935a-cfad18a776b6', 'Chemistry', 'JAMB', null, 2026, null, 'The maximum number of electrons in the L shell of an atom is', null, '["8","18","32","2"]', 0, 'The L shell can hold a maximum of 8 electrons.', true, '2026-09-12 11:36:21.295', '2026-09-12 11:36:21.295', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('938e0b8d-07c0-43dd-8b4f-29be26a78cfc', 'Economics', 'JAMB', null, 2026, null, 'All the following are factors that affect demand except;', null, '["Consumer''s expectations","Tastes and preferences","Government policies","Cost of production"]', 3, 'Cost of production affects supply, not demand.', true, '2026-09-12 11:01:25.156', '2026-09-12 11:01:25.156', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('939a809a-f83f-4696-8a23-292f2a8ba60b', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). The distance is not more than twenty kilometres <u>as the crow flies</u>.', null, '["by the longest route","by the shortest route","by air","by the fastest means"]', 1, '''As the crow flies'' = shortest route.', true, '2026-10-24 01:04:19.968', '2026-10-24 01:04:19.968', null, null, null, '(Choose the most appropriate interpretation). The distance is not more than twenty kilometres <u>as the crow flies</u>.', '["by the longest route","<u>by the shortest route</u>","by air","by the fastest means"]', '''<b>As the crow flies</b>'' = <b>shortest route</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('939aca06-3723-42cf-afdf-7248ef01c273', 'English Language', 'JAMB', null, 2007, null, 'The judge demanded that the accused <u>_______</u> the full story to the court.', null, '["tells","told","telling","tell"]', 3, '''Demanded that'' â†’ subjunctive tell.', true, '2026-10-24 01:02:16.798', '2026-10-24 01:02:16.798', null, null, null, 'The judge demanded that the accused <u>_______</u> the full story to the court.', '["tells","told","telling","<u>tell</u>"]', '''<b>Demanded that</b>'' â†’ subjunctive <b>tell</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('93dac2cb-ad4b-4ee5-8944-72f2e90ad24b', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). It is futile trying <u>to make bricks without straw</u>.', null, '["fertile","important","fragile","vain","bad"]', 3, 'Futile = vain.', true, '2026-10-24 01:04:15.839', '2026-10-24 01:04:15.839', null, null, null, '(Choose the most appropriate interpretation). It is futile trying <u>to make bricks without straw</u>.', '["fertile","important","fragile","<u>vain</u>","bad"]', '<b>Futile</b> = <b>vain</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('93e1170d-7121-4e62-9a6e-c8287fd62453', 'Literature in English', 'JAMB', null, 2026, null, 'A playwright who solves the dilemma of his characters by rescuing them from impossible circumstances using extra human device has employed the use of', null, '["Due to the machine","deus ex machina","denouement","de ja vu"]', 1, 'It is deus ex machina.', true, '2026-09-12 11:13:38.048', '2026-09-12 11:13:38.048', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('93f70434-d5ef-430e-bbd9-491bf8c3a453', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The deafening noise of the two jet planes which flew across our compound yesterday made people fear that an assault on the country might be <u>imminent</u>.', null, '["impending","ahead","remote","eminent","threatening"]', 2, 'Imminent = impending; opposite = remote.', true, '2026-10-24 07:21:10.962', '2026-10-24 07:21:10.962', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The deafening noise of the two jet planes which flew across our compound yesterday made people fear that an assault on the country might be <u>imminent</u>.', '["impending","ahead","remote","eminent","threatening"]', 'Imminent = impending; opposite = remote.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('93f91952-f2a5-43bc-99fd-3981240aa240', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Who was sent by God to restore Saul''s sight after his encounter with Jesus on the road to Damascus?', null, '["Simon","Stephen","Aeneas","Ananias"]', 3, 'Ananias was sent by God to restore Saul''s sight. The Lord appeared to Ananias in a vision and told him to go to Saul, lay hands on him, and restore his sight.', true, '2026-09-12 09:46:11.196', '2026-09-12 09:46:11.196', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('93fbd6f2-cbd6-4cfc-84f9-94655f4c1920', 'Literature in English', 'JAMB', null, 2026, null, 'A character who does not change throughout a story is a', null, '["dynamic character","flat character","round character","foil character"]', 1, 'A character who does not change throughout a story is a flat character. Flat characters are one-dimensional, often defined by a single trait or characteristic, and remain the same from beginning to end. Dynamic (round) characters undergo significant change or development. A foil character is one who contrasts with another character to highlight their traits.', true, '2026-09-10 10:45:34.021', '2026-09-10 10:45:34.021', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('940cd798-9e9c-439d-ab68-68ec1239be85', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. One <u>hindrance</u> to an orderly economic development of the country is large-scale fraud and corruption.', null, '["difficulty","element","reason","obstacle","ritual"]', 3, 'Hindrance = obstacle.', true, '2026-10-24 01:01:40.934', '2026-10-24 01:01:40.934', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. One <u>hindrance</u> to an orderly economic development of the country is large-scale fraud and corruption.', '["difficulty","element","reason","<u>obstacle</u>","ritual"]', '<b>Hindrance</b> = <b>obstacle</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('940e8bb4-49a5-4515-be6c-f20b3d07b27c', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). We enjoy the story but it sounds <u>larger than life</u>.', null, '["too long and uninteresting","a realistic story about human nature","a little piece of life","somewhat unusual"]', 3, '''Larger than life'' = somewhat unusual/exaggerated.', true, '2026-10-24 01:04:20.345', '2026-10-24 01:04:20.345', null, null, null, '(Choose the most appropriate interpretation). We enjoy the story but it sounds <u>larger than life</u>.', '["too long and uninteresting","a realistic story about human nature","a little piece of life","<u>somewhat unusual</u>"]', '''<b>Larger than life</b>'' = <b>somewhat unusual/exaggerated</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('941b7f3d-dc10-457c-9b39-e446bd6ab4b6', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Okonkwo''s <u>lethal</u> right foot did the magic in the football match.', null, '["weak","wicked","fat","harmless"]', 3, 'Lethal = deadly; opposite = harmless.', true, '2026-10-24 07:21:29.872', '2026-10-24 07:21:29.872', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Okonkwo''s <u>lethal</u> right foot did the magic in the football match.', '["weak","wicked","fat","harmless"]', 'Lethal = deadly; opposite = harmless.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9423ec71-3eb4-4f34-8489-d67769a67605', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The administrator''s <u>apathy</u> was soon noticed by all his subordinates.', null, '["indifference","kindness","concern","inefficiency"]', 0, 'Apathy = indifference.', true, '2026-10-24 01:03:56.933', '2026-10-24 01:03:56.933', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The administrator''s <u>apathy</u> was soon noticed by all his subordinates.', '["<u>indifference</u>","kindness","concern","inefficiency"]', '<b>Apathy</b> = <b>indifference</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9437dd32-f507-4cc2-a72e-b8ddf54bd7c9', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). Usman needs to <u>get his act together</u> if he wants to pass the examination', null, '["He needs to put all points down in the examination","He needs to organize himself","He needs to be fast when writing the examination","He needs to put on his stage costume"]', 1, '''Get his act together'' = organize himself.', true, '2026-10-24 01:04:23.56', '2026-10-24 01:04:23.56', null, null, null, '(Choose the most appropriate interpretation). Usman needs to <u>get his act together</u> if he wants to pass the examination', '["He needs to put all points down in the examination","<u>He needs to organize himself</u>","He needs to be fast when writing the examination","He needs to put on his stage costume"]', '''<b>Get his act together</b>'' = <b>organize himself</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9440e2c7-0dce-4060-bed6-b5ced4cbb318', 'English Language', 'JAMB', null, 2007, null, 'Adamu is one of the<u>______</u> who always <u>_____</u>hard.', null, '["men/works","men/work","man/works","man/work"]', 1, '''Who'' â†’ men (plural) â†’ work.', true, '2026-10-24 01:04:30.3', '2026-10-24 01:04:30.3', null, null, null, 'Adamu is one of the<u>______</u> who always <u>_____</u>hard.', '["men/works","<u>men/work</u>","man/works","man/work"]', '''<b>Who</b>'' â†’ <b>men</b> (plural) â†’ <b>work</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('944dd4ee-bb27-41b2-8330-9634843c639b', 'Biology', 'JAMB', null, 2026, null, 'The stage of mitosis associated with the formation of spindle fibre is the', null, '["prophase","metaphase","anaphase","telophase"]', 0, 'Prophase is the stage of mitosis where the spindle fibers begin to form. During prophase, the nuclear envelope breaks down, chromatin condenses into visible chromosomes, and the mitotic spindle apparatus forms from the centrosomes. Metaphase is when chromosomes align on the metaphase plate. Anaphase is when sister chromatids separate and move to opposite poles. Telophase is when the nuclear envelope reforms. Spindle fiber formation begins in prophase and is complete by metaphase. The spindle apparatus is crucial for chromosome separation during mitosis.', true, '2026-09-09 03:18:45.935', '2026-09-09 03:18:45.935', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('944e7136-05b7-47e3-828a-dca6ee9dd553', 'Christian Religious Studies', 'JAMB', null, 2026, null, '“Behold, you are old and your sons do not walk in your ways” The Israelites made this statement to Samuel because his sons...', null, '["Took bribes and perverted justice","Treated the offering of the Lord with contempt","Had immoral dealings with women","Disregarded the advice of Israel’s elders"]', 0, '1 Samuel 8:3-5 records that Samuel''s sons Joel and Abijah turned aside after dishonest gain, took bribes, and perverted justice.', true, '2026-09-09 17:18:28.53', '2026-09-09 17:18:28.53', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9453d87a-1971-4139-ab13-3097387479c9', 'Financial Accounting', 'UTME', null, 2003, null, 'Calculate the value of fixed assets', 'https://res.cloudinary.com/kwi1uv0g/image/upload/v1791841296/questions/aodh61kvbrym61zsfptl.jpg', '["N15 992","N18 470","N27 000","N27 052"]', 3, 'Fixed Assets: Land and Building 18470 + Furnitures and fittings 5120 + Motor Vehicle 3462 = 27052.', true, '2026-10-12 21:59:59.928', '2026-10-12 21:59:59.928', null, null, null, 'Calculate the value of fixed assets', '["N15 992","N18 470","N27 000","<b>N27 052</b>"]', 'Fixed Assets: Land and Building 18470 + Furnitures and fittings 5120 + Motor Vehicle 3462 = <b>27052</b>.', '{"bold":["27052"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('945756fc-fa2a-481d-9311-fea68265952a', 'English Language', 'JAMB', null, 2024, null, 'The tone of the writer in this passage is', null, '["Critical","Argumentative","Analytical","Ideological"]', 0, 'The writer is critical of the tobacco companies'' deception.', true, '2026-09-18 10:14:27.403', '2026-09-18 10:14:27.403', '517da099-8f3e-4ce4-a114-f53efc5c5835', 3, 'COMPREHENSION', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9460d86c-be7b-4f19-8273-4fd2f6f2ad60', 'Physics', 'JAMB', null, 2003, null, 'The phenomenon whereby the water droplets in the atmosphere combine with dust particles in the air to reduce visibility is', null, '["Fog","Hail","Mist","Cloud"]', 0, 'Fog is formed by water droplets condensing on dust and smoke particles near the ground, which cuts visibility.', true, '2026-10-12 19:15:55.394', '2026-10-12 19:15:55.394', null, null, null, 'The phenomenon whereby the water droplets in the atmosphere combine with dust particles in the air to reduce visibility is', '["Fog","Hail","Mist","Cloud"]', 'Fog is formed by water droplets condensing on dust and smoke particles near the ground, which cuts visibility.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('94617c3a-1417-42d9-b0d2-724d67e694d9', 'Biology', 'JAMB', null, 2026, null, 'A food substance which produces black colouration with osmic acid contains', null, '["fat","protein","carbohydrates","sugar"]', 0, 'A food substance that produces black coloration with osmic acid contains fat (lipid). Osmic acid (osmium tetroxide) reacts with unsaturated fats, producing a black precipitate. This reaction is used as a histochemical stain for lipids. Proteins, carbohydrates, and sugars do not produce this specific reaction with osmic acid. This is a specific test for the presence of fats in biological samples. Osmic acid is also a fixative that can preserve lipid structures for electron microscopy.', true, '2026-09-09 03:18:49.977', '2026-09-09 03:18:49.977', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('947406e3-ddbd-4c76-b2ce-aceeb93c85aa', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'The first apostolic martyr was...', null, '["Judas Iscariot","James, the brother of John","Simon Peter","James, the son of Alphaeus"]', 1, 'Acts 12:1-2 records that James, the brother of John, was executed by Herod Agrippa I, making him the first apostle to be martyred.', true, '2026-09-09 17:18:24.382', '2026-09-09 17:18:24.382', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9486387a-ab25-48e3-b720-3e42ef06577a', 'Physics', 'JAMB', null, 2026, null, 'A transformer is rated 240V. If the primary coil is 4000 turns and the secondary voltage 12V, determine the number of turns in the secondary coil.', null, '["250","100","150","200"]', 3, 'Ns/Np = Vs/Vp. Ns = Np × Vs/Vp = 4000 × 12/240 = 4000/20 = 200 turns.', true, '2026-09-10 10:56:46.438', '2026-09-10 10:56:46.438', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9493def0-efd4-4361-92c3-a04a1feecbc8', 'Literature in English', 'JAMB', null, 2026, null, 'Cleopatra is best described as a', null, '["static character","tragic heroine with complexity","flat character","symbolic figure only"]', 1, 'Cleopatra is a tragic heroine with complexity.', true, '2026-09-12 11:11:22.037', '2026-09-12 11:11:22.037', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9499cbcc-3d3b-443d-826b-98362169f890', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). The lecture is Uye''s <u>road to Damascus</u>', null, '["The lecture is an opportunity to travel to Damascus","The lecture is an experience that changes the way she thinks","The lecture is exclusively about Damascus","The lecture is an experience that cannot be changed"]', 1, '''Road to Damascus'' = life-changing experience.', true, '2026-10-24 01:02:10.739', '2026-10-24 01:02:10.739', null, null, null, '(Choose the most appropriate interpretation). The lecture is Uye''s <u>road to Damascus</u>', '["The lecture is an opportunity to travel to Damascus","<u>The lecture is an experience that changes the way she thinks</u>","The lecture is exclusively about Damascus","The lecture is an experience that cannot be changed"]', '''<b>Road to Damascus</b>'' = <b>life-changing experience</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('94a36ab9-ee28-4f79-b734-be4a66172604', 'English Language', 'JAMB', null, 2024, null, 'I''m proud of you. The underlined expression functions as', null, '["prepositional complement","adjectival complement","subject complement","verbal complement"]', 0, '"Of you" is a prepositional phrase functioning as a complement to the adjective "proud."', true, '2026-09-18 09:43:02.342', '2026-09-18 09:43:02.342', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('94b29fb2-0c7e-4f97-b3bf-8deceef88b14', 'Literature in English', 'JAMB', null, 2026, null, '………………………………is a speech or writing that attacks or makes fun of a person in an insulting way.', null, '["Satire","Lampoon","Parody","Irony"]', 1, 'A lampoon is a speech or writing that attacks or makes fun of a person in an insulting way. Unlike satire, which targets societal vices or institutions, a lampoon is typically directed at a specific individual. Satire is broader, parody imitates a style, and irony is a contradiction between appearance and reality.', true, '2026-09-10 10:47:55.296', '2026-09-10 10:47:55.296', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('94b33b97-819f-4332-b0bc-8ac452322298', 'English Language', 'JAMB', null, 2024, null, 'Yet another function of the liver is the formation and breakdown of the red blood ______.', null, '["sugar","corpuscles","cells","bank"]', 2, 'Red blood cells are broken down by the liver.', true, '2026-09-18 09:43:02.859', '2026-09-18 09:43:02.859', null, null, 'CLOZE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('94b977b4-edab-43e2-adf5-fe30cf3bc19b', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). Before announcing his retirement, Ochima resolved to <u>settle on account</u> with the bank.', null, '["pay back all he owes","close his account with","retire his loans from","get back at"]', 0, '''Settle on account'' = pay back all owed.', true, '2026-10-24 01:04:22.76', '2026-10-24 01:04:22.76', null, null, null, '(Choose the most appropriate interpretation). Before announcing his retirement, Ochima resolved to <u>settle on account</u> with the bank.', '["<u>pay back all he owes</u>","close his account with","retire his loans from","get back at"]', '''<b>Settle on account</b>'' = <b>pay back all owed</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('94ba48f7-da74-49d9-b006-51044fe994d2', 'English Language', 'JAMB', null, 2024, null, 'Adio tried to ______ all the memories of his dead father', null, '["Obliterate","Obstruct","Eulogize","Recalled"]', 0, '"Obliterate" means to destroy completely or wipe out.', true, '2026-09-18 09:34:03.977', '2026-09-18 09:34:03.977', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('94bb937d-2512-4d37-8098-2a3788f62e0d', 'English Language', 'JAMB', null, 2007, null, 'The new manager was responsible for the <u>__________</u> of the organization.', null, '["uplift","upliftment","lifting","uplifting"]', 0, 'Correct form: uplift.', true, '2026-10-24 07:21:38.798', '2026-10-24 07:21:38.798', null, null, null, 'The new manager was responsible for the <u>__________</u> of the organization.', '["uplift","upliftment","lifting","uplifting"]', 'Correct form: uplift.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('94bf44e6-1513-445b-a237-158a0f9c4a36', 'English Language', 'JAMB', null, 2024, null, 'Choose the appropriate stress: circumstantial', null, '["CIR-cum-stan-tial","cir-CUM-stan-tial","cir-cum-STAN-tial","cir-cum-stan-TIAL"]', 2, 'The stress in "circumstantial" is on the third syllable: cir-cum-STAN-tial.', true, '2026-09-18 09:43:02.667', '2026-09-18 09:43:02.667', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('94d57f88-bc2d-4c4e-a063-8edab478703b', 'Yoruba', 'JAMB', null, 2002, null, 'Ka àwôn àyòkà ìsàlé yìí, Kí o sì dáhùn àwòn ìbéèrè tí ó télè wòn. Òba Fadérera ní oko kòkó àti oko obì, ó ní oko ìyù àti oko òwú, ilá inú oko rè ni gbogbo ìlú gbójú lé, ìyù àkùrò rè ní kòkò yójú sí òjà. Oko òba gbòòrò púpõ.Sé ìgbà púpõ ni òpòlópõ ènìyàn p lò láti ìyìç òfé fún òba. Òba tún fì ògbòn yè é tó bèé tí ìrè oko rè kò wòn tó ti çlòmíràn. Òba Fadérera bí ómòkùnrin kan tí ó féràn púpô. Ómò òba yìí kì í yè ìyè kankan, àfì kì ó máa ìyìré nínu ògbà baba rê. Àwòn ìrányè pò láti fún un ní gbogbo ohun tí ó bá p fè. Aỳò tuntun ni òmò òba p wò ní ojoojúmò. Òba kè òmò náà bí çyin ojú, ó kè ç pélú ohun ìní àti ìrányè. Ohun kan wá jě děùn òkàn àwòn ará ìlú Éyin-Òla. Ohun náà ni pé, ìkòokò a máa dédé wò ìlù láti gbé ewùrê tàbí àgùntàn wòn lò. Ní ìgbà púpõ ni àwòn ará ìlù tì lò ké bá òba kí ó bá àwòn yanjù òràn tí ó dé bá wòn. Nígbà tí ó yè wàyí o, àwòn ìkòokò pàápàá wá tùn ara mú, wòn béré sí í gbé àwòn òmò ará ìlù Éyin-òla. Àwòn ìlù tùn ké lò sí òdò òba, ìgùbòn òba kò ka òrõ náà sí rárá. Ní òjò kan nígbà tí òmò òba Fadérera àti àwòn çmèwà bàbá rê p ìyìré lórí pápá tí ó wà lèbàà ààfin, ìkòokò plá kan yò sí wòn, ó sì gbé òmò òba lò ráúráú. Nígbà tí òba gbò ohun tí ó ìçlè, ó kígbè ní ohùn rara. Örö náà wá ya gbogbo ìlù lënu nítorí pé òba pàyç lësêkçsê pé kí gbogbo àwòn òdç atamátasê ìlù jáde, kí wön sì pa gbogbo ìkokò tí ó wà agbègbè náà. Sùgbön ìkòokò tí pa òmò òba Fadérera jç. Ëpa kò bóró mò. Ohun ti ó mú ìrè oko òba tà ju ti ará ìlù lò ni pé', null, '["òba gbòn jù wòn lò","ìrè oko òba kò wòn","iyu oko òba tóbi ju ti ará ìlù","òba ní agbára."]', 1, 'Ìrè oko òba kò wòn ni ó mú kí ó tà ju ti ará ìlù lò.', true, '2026-10-13 13:22:37.679', '2026-10-13 13:22:37.679', null, null, null, 'Ka àwôn àyòkà ìsàlé yìí, Kí o sì dáhùn àwòn ìbéèrè tí ó télè wòn. Òba Fadérera ní oko kòkó àti oko obì, ó ní oko ìyù àti oko òwú, ilá inú oko rè ni gbogbo ìlú gbójú lé, ìyù àkùrò rè ní kòkò yójú sí òjà. Oko òba gbòòrò púpõ.Sé ìgbà púpõ ni òpòlópõ ènìyàn p lò láti ìyìç òfé fún òba. Òba tún fì ògbòn yè é tó bèé tí ìrè oko rè kò wòn tó ti çlòmíràn. Òba Fadérera bí ómòkùnrin kan tí ó féràn púpô. Ómò òba yìí kì í yè ìyè kankan, àfì kì ó máa ìyìré nínu ògbà baba rê. Àwòn ìrányè pò láti fún un ní gbogbo ohun tí ó bá p fè. Aỳò tuntun ni òmò òba p wò ní ojoojúmò. Òba kè òmò náà bí çyin ojú, ó kè ç pélú ohun ìní àti ìrányè. Ohun kan wá jě děùn òkàn àwòn ará ìlú Éyin-Òla. Ohun náà ni pé, ìkòokò a máa dédé wò ìlù láti gbé ewùrê tàbí àgùntàn wòn lò. Ní ìgbà púpõ ni àwòn ará ìlù tì lò ké bá òba kí ó bá àwòn yanjù òràn tí ó dé bá wòn. Nígbà tí ó yè wàyí o, àwòn ìkòokò pàápàá wá tùn ara mú, wòn béré sí í gbé àwòn òmò ará ìlù Éyin-òla. Àwòn ìlù tùn ké lò sí òdò òba, ìgùbòn òba kò ka òrõ náà sí rárá. Ní òjò kan nígbà tí òmò òba Fadérera àti àwòn çmèwà bàbá rê p ìyìré lórí pápá tí ó wà lèbàà ààfin, ìkòokò plá kan yò sí wòn, ó sì gbé òmò òba lò ráúráú. Nígbà tí òba gbò ohun tí ó ìçlè, ó kígbè ní ohùn rara. Örö náà wá ya gbogbo ìlù lënu nítorí pé òba pàyç lësêkçsê pé kí gbogbo àwòn òdç atamátasê ìlù jáde, kí wön sì pa gbogbo ìkokò tí ó wà agbègbè náà. Sùgbön ìkòokò tí pa òmò òba Fadérera jç. Ëpa kò bóró mò. Ohun ti ó mú ìrè oko òba tà ju ti ará ìlù lò ni pé', '["òba gbòn jù wòn lò","ìrè oko òba kò wòn","iyu oko òba tóbi ju ti ará ìlù","òba ní agbára."]', 'Ìrè oko òba kò wòn ni ó mú kí ó tà ju ti ará ìlù lò.', '{"bold":["Ìrè oko òba kò wòn"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('94d85557-c188-46f2-b0a0-c8d7c8e294a9', 'Literature in English', 'JAMB', null, 2026, null, 'The tone of Once Upon a Time shifts from', null, '["Nostalgic to cynical","Joyful to indifferent","Angry to humorous","Passive to celebratory"]', 0, 'The tone shifts from nostalgic to cynical.', true, '2026-09-12 11:09:55.455', '2026-09-12 11:09:55.455', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('94db7d9c-e77b-43a3-8feb-d1fd3fc692dd', 'English Language', 'JAMB', null, 2024, null, '(nearest in meaning) Now that the company is insolvent, it will shut down.', null, '["Overworked","Unstable","Bankrupt","Affluent"]', 2, '"Insolvent" means unable to pay debts; it is nearest in meaning to "bankrupt."', true, '2026-09-18 09:24:04.676', '2026-09-18 09:24:04.676', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('94e7072a-e7ae-4814-bcb9-777728e1532d', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The high cost of living, these days, calls for a lot of <u>frugality</u>.', null, '["economy","recklessness","prudence","extravagance"]', 3, 'Frugality = thrift; opposite = extravagance.', true, '2026-10-24 07:21:23.213', '2026-10-24 07:21:23.213', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The high cost of living, these days, calls for a lot of <u>frugality</u>.', '["economy","recklessness","prudence","extravagance"]', 'Frugality = thrift; opposite = extravagance.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('94f4eb52-f010-4a9d-a5c3-89c2d71e572b', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The athlete has unexpectedly become <u>indomitable</u>.', null, '["unruly","unconquerable","weak","disoriented"]', 2, 'Indomitable = unconquerable; opposite = weak.', true, '2026-10-24 07:21:23.665', '2026-10-24 07:21:23.665', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The athlete has unexpectedly become <u>indomitable</u>.', '["unruly","unconquerable","weak","disoriented"]', 'Indomitable = unconquerable; opposite = weak.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('951b0d22-0578-45bc-bc42-0b2dd8d97b50', 'Hausa', 'JAMB', null, 2010, null, '''Yanzu tun abin nan Geda, me kike jira ba ki mayar da yarinyar nan đakinta ba?'' Wa ya fadi wannan magana a wasan ''Bari Ba Shegiya Ba Ce'' na Zaman Duniya Iyawa Ne na Y. Ladan?', null, '["Bawa.","Baban Tagudu.","Kofur.","Alhaji Mai Rokoki."]', 1, 'Baban Tagudu ne ya fadi wannan magana.', true, '2026-10-13 10:37:25.804', '2026-10-13 10:37:25.804', null, null, null, '''Yanzu tun abin nan Geda, me kike jira ba ki mayar da yarinyar nan đakinta ba?'' Wa ya fadi wannan magana a wasan ''Bari Ba Shegiya Ba Ce'' na Zaman Duniya Iyawa Ne na Y. Ladan?', '["Bawa.","Baban Tagudu.","Kofur.","Alhaji Mai Rokoki."]', 'Baban Tagudu ne ya fadi wannan magana.', '{"bold":["Baban Tagudu"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('951bbfc8-b4f4-4607-b877-421b50043f97', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). The principal warned us against <u>burning the candle at both ends</u>.', null, '["being careless with candles","wearing ourselves out","being too generous","disloyalty"]', 1, '''Burning candle at both ends'' = exhausting oneself.', true, '2026-10-24 01:04:20.184', '2026-10-24 01:04:20.184', null, null, null, '(Choose the most appropriate interpretation). The principal warned us against <u>burning the candle at both ends</u>.', '["being careless with candles","<u>wearing ourselves out</u>","being too generous","disloyalty"]', '''<b>Burning candle at both ends</b>'' = <b>exhausting oneself</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('951e10d0-a6e6-4fdb-a17b-716f78b4e444', 'Biology', 'JAMB', null, 2012, null, 'The autonomic nervous system consists of neurons that control the', null, '["voluntary muscles","heart beat","tongue","hands"]', 1, 'The autonomic nervous system controls the heart beat.', true, '2026-10-12 20:59:44.994', '2026-10-12 20:59:44.994', null, null, null, 'The autonomic nervous system consists of neurons that control the', '["voluntary muscles","heart beat","tongue","hands"]', 'The autonomic nervous system controls the heart beat.', '{"bold":["heart beat"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('952d75ed-299f-4ee1-9ea9-873f5170f6c0', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). Bankole was a man <u>given to</u> much wine.', null, '["pushed to","taken over by","addicted to","forced to","afflicted by"]', 2, '''Given to'' = addicted to.', true, '2026-10-24 01:04:16.107', '2026-10-24 01:04:16.107', null, null, null, '(Choose the most appropriate interpretation). Bankole was a man <u>given to</u> much wine.', '["pushed to","taken over by","<u>addicted to</u>","forced to","afflicted by"]', '''<b>Given to</b>'' = <b>addicted to</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('95302e65-fc8c-4f51-860f-6e69cc5750bc', 'Hausa', 'JAMB', null, 2010, null, '''Shi ke sa kasa ta koma baya, Cikin duniya da lalaci'' Wane abu mawakin nan yake nufi a wannan baiti daga WakoKin Mu''azu Haĉeja?', null, '["Shashanci.","Jahilci.","Hassada.","Giba."]', 1, 'Mawakin yana nufin jahilci.', true, '2026-10-13 10:37:25.373', '2026-10-13 10:37:25.373', null, null, null, '''Shi ke sa kasa ta koma baya, Cikin duniya da lalaci'' Wane abu mawakin nan yake nufi a wannan baiti daga WakoKin Mu''azu Haĉeja?', '["Shashanci.","Jahilci.","Hassada.","Giba."]', 'Mawakin yana nufin jahilci.', '{"bold":["jahilci"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('953359d9-b154-4593-8448-d495eb45cb4d', 'Literature in English', 'JAMB', null, 2026, null, 'The concept of redemption in the novel is achieved mainly through', null, '["revenge","forgiveness and reconciliation","punishment","exile"]', 1, 'Redemption is achieved through forgiveness and reconciliation.', true, '2026-09-12 11:11:20.276', '2026-09-12 11:11:20.276', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('953d6fee-46f9-41bd-87d6-256dd73de878', 'Literature in English', 'JAMB', null, 2026, null, 'A play that tells a single story, has one setting and takes place within a specified period is said to', null, '["be heavily moralistic","be clearly cohesive","possess the unities","have tragic elements"]', 2, 'A play that tells a single story, has one setting, and takes place within a specified period is said to possess the unities. The three unities of classical drama are: unity of action (one main plot), unity of place (one setting), and unity of time (events occur within 24 hours). These unities were derived from Aristotle''s Poetics and were strictly observed in classical Greek and French drama.', true, '2026-09-10 10:45:34.289', '2026-09-10 10:45:34.289', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('95406bbc-c83d-4be8-b0dc-8a7392757c6c', 'Biology', 'JAMB', null, 2026, null, 'The companion cells are parts of the', null, '["pericycle","phloem","pith","xylem"]', 1, 'Companion cells are living cells associated with sieve tubes in the phloem tissue. They are connected to sieve tubes through plasmodesmata and function to load and unload sugars into and from the sieve tubes, providing metabolic support to the enucleate sieve tube elements. The pericycle is a layer in roots. The pith is the central ground tissue in stems. The xylem contains dead cells (tracheids and vessels) and lacks companion cells. The phloem is the food-conducting tissue of vascular plants, and companion cells are essential for its active transport functions.', true, '2026-09-09 03:18:44.392', '2026-09-09 03:18:44.392', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9541392c-d22d-4774-b559-8c637ed147ee', 'Physics', 'JAMB', null, 2026, null, 'The melting point of a substance is equivalent to its', null, '["vapour pressure","solidification temperature","liquidation temperature","solidification pressure"]', 1, 'The melting point of a substance is equivalent to its solidification temperature. At the melting point, the solid and liquid phases coexist in equilibrium. The temperature remains constant during the phase change.', true, '2026-09-10 10:56:42.33', '2026-09-10 10:56:42.33', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9553d900-96f4-4354-8f75-af479ec27360', 'English Language', 'JAMB', null, 2024, null, 'She wished she ______ well', null, '["had passed","has passed","will","shall pass"]', 0, '"Had passed" is the past perfect used after "wished" for past regrets.', true, '2026-09-18 09:43:02.804', '2026-09-18 09:43:02.804', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9564b994-7dc8-4114-82d5-90f773686814', 'Physics', 'JAMB', null, 2026, null, 'If a reverse biased voltage is applied across a p-n junction, the depletion layer width is', null, '["increased","decreased","constant","halved"]', 0, 'When a reverse biased voltage is applied across a p-n junction, the depletion layer width increases. Reverse bias widens the depletion region because it pulls majority carriers away from the junction, increasing the potential barrier. Forward bias decreases the depletion width.', true, '2026-09-10 10:56:40.218', '2026-09-10 10:56:40.218', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('956806f1-6204-44ff-96b8-ddc60027ddfa', 'Physics', 'JAMB', null, 2000, null, 'A catapult used to hold a stone of mass 500 g is extended by 20 cm with an applied force F. If the stone leaves with a velocity of 40 m s⁻¹, the value of F is', null, '["4.0 x 10⁴ N","4.0 x 10³ N","2.0 x 10³ N","4.0 x 10² N"]', 1, 'Work done on the stone = its kinetic energy: ½F x 0.20 = ½ x 0.5 x 40² = 400 J, so F = 4.0 x 10³ N.', true, '2026-10-12 19:15:48.841', '2026-10-12 19:15:48.841', null, null, null, 'A catapult used to hold a stone of mass 500 g is extended by 20 cm with an applied force F. If the stone leaves with a velocity of 40 m s<sup>-1</sup>, the value of F is', '["4.0 x 10<sup>4</sup> N","4.0 x 10<sup>3</sup> N","2.0 x 10<sup>3</sup> N","4.0 x 10<sup>2</sup> N"]', 'Work done on the stone = its kinetic energy: ½F x 0.20 = ½ x 0.5 x 40<sup>2</sup> = 400 J, so F = 4.0 x 10<sup>3</sup> N.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9575079f-b8e6-4112-a88a-63c773bd34fa', 'Economics', 'JAMB', null, 2026, null, 'Scarcity in economics means: (i) a period of scarce things (ii) when things are costly to acquire (iii) monopolisation of available resources by a few (iv) nationalisation of natural resources such as petroleum in Venezuela (v) none of the above', null, '["I only","ii only","I, ii and iii only","V only"]', 3, 'Scarcity in economics means none of the above (v). Scarcity refers to the fundamental economic problem of having unlimited human wants in a world of limited resources. It is not about a period of scarce things, costly acquisition, or monopolization. Scarcity is the basic economic problem that necessitates choice and the allocation of resources.', true, '2026-09-10 10:41:20.295', '2026-09-10 10:41:20.295', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('958c1eef-b8ff-4355-9596-f7e3855ab450', 'Physics', 'JAMB', null, 1993, null, 'A rocket burns fuel at the rate of 10 kg s⁻¹ and ejects it with a velocity of 5 x 10³ m s⁻¹. The thrust exerted by the gas on the rocket is', null, '["2.5 x 10⁷ N","5.0 x 10⁴ N","5.0 x 10² N","2.0 x 10⁻³ N"]', 1, 'Thrust = (mass ejected per second) x exhaust velocity = 10 x 5 x 10³ = 5.0 x 10⁴ N.', true, '2026-10-12 19:15:37.109', '2026-10-12 19:15:37.109', null, null, null, 'A rocket burns fuel at the rate of 10 kg s<sup>-1</sup> and ejects it with a velocity of 5 x 10<sup>3</sup> m s<sup>-1</sup>. The thrust exerted by the gas on the rocket is', '["2.5 x 10<sup>7</sup> N","5.0 x 10<sup>4</sup> N","5.0 x 10<sup>2</sup> N","2.0 x 10<sup>-3</sup> N"]', 'Thrust = (mass ejected per second) x exhaust velocity = 10 x 5 x 10<sup>3</sup> = 5.0 x 10<sup>4</sup> N.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('958e94dc-e3d6-474e-b06f-3ccf4154e8fb', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'In his teaching on partiality, James declares that mercy triumphs over', null, '["judgment","righteousness","grace","faith"]', 0, 'James declares that mercy triumphs over judgment. He writes, ''For judgment is without mercy to one who has shown no mercy; yet mercy triumphs over judgment.''', true, '2026-09-12 09:46:13.719', '2026-09-12 09:46:13.719', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('959e3116-8318-4cc1-a01c-60f81eb7ed70', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The workers hope to appear before the <u>arbitration</u> panel to resolve the lingering dispute.', null, '["trial","legislative","investigative","reconciliatory"]', 3, 'Arbitration = reconciliatory.', true, '2026-10-24 01:04:08.161', '2026-10-24 01:04:08.161', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The workers hope to appear before the <u>arbitration</u> panel to resolve the lingering dispute.', '["trial","legislative","investigative","<u>reconciliatory</u>"]', '<b>Arbitration</b> = <b>reconciliatory</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('95a1e43c-94aa-4fe3-9628-34063165975c', 'Economics', 'JAMB', null, 2026, null, 'Economics is best defined as: (i) the study of allocation of resources to satisfy human wants (ii) the study of human behaviour in the process of buying and selling (iii) study of how nations grow and improve their welfare (iv) the study of how to allocate scarce resources to satisfy human wants', null, '["I and iv only","I only","iv only","I, ii, iii and iv"]', 0, 'Economics is best defined as the study of allocation of resources to satisfy human wants (i) and the study of how to allocate scarce resources to satisfy human wants (iv). Both definitions capture the essence of economics: the study of how society manages its scarce resources. Option (ii) is too narrow (only buying and selling), and option (iii) is more about development economics.', true, '2026-09-10 10:41:20.403', '2026-09-10 10:41:20.403', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('95aa0500-50b1-478f-b529-2067a17906ff', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). If people don''t want to play the game according to the rule, <u>that is their business</u>.', null, '["their business will suffer","it is not their fault","they should blame others for it","other people will take over their business","they will have themselves to blame"]', 4, '''That is their business'' = they bear consequences.', true, '2026-10-24 01:02:02.32', '2026-10-24 01:02:02.32', null, null, null, '(Choose the most appropriate interpretation). If people don''t want to play the game according to the rule, <u>that is their business</u>.', '["their business will suffer","it is not their fault","they should blame others for it","other people will take over their business","<u>they will have themselves to blame</u>"]', '''<b>That is their business</b>'' = <b>they bear consequences</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('95af19f6-7f46-4fb9-a36b-40d70028e3f0', 'Biology', 'JAMB', null, 2026, null, 'The loss of soil through erosion can be reduced by', null, '["Watering","Crop rotation","Manuring","Irrigation"]', 1, 'Crop rotation can help reduce soil erosion by maintaining soil cover and structure. Different crops have different root systems that hold soil at different depths. Crop rotation also improves soil fertility and reduces the need for soil-disturbing activities. Watering, manuring, and irrigation do not directly prevent erosion and may even exacerbate it if not done properly. Other erosion control methods include contour plowing, terracing, mulching, and planting windbreaks.', true, '2026-09-09 03:18:59.003', '2026-09-09 03:18:59.003', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('95b333fd-0525-47c5-a019-33109a5c74e7', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. It is of <u>fundamental</u> importance that one sleeps properly.', null, '["undisputed","basic","special","least"]', 1, 'Fundamental = basic.', true, '2026-10-24 01:01:43.298', '2026-10-24 01:01:43.298', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. It is of <u>fundamental</u> importance that one sleeps properly.', '["undisputed","<u>basic</u>","special","least"]', '<b>Fundamental</b> = <b>basic</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('95b37ae7-f65b-48ec-89ab-a97ab677f0c9', 'Government', 'JAMB', null, 2026, null, 'Capitalism is an economic system in which', null, '["The economy of the State is centrally planned and controlled","Private Persons are permitted to undertake enterprises","Accumulation of private property is forbidden","That means of production are owned and controlled by the State"]', 1, 'Capitalism permits private persons to undertake enterprises.', true, '2026-09-12 11:24:19.714', '2026-09-12 11:24:19.714', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('95b44ad9-0e19-4042-ad28-839fa98f3405', 'Yoruba', 'JAMB', null, 2002, null, 'Orí loníye, édá láyànmò. Àkúnléyàn òun ni àdáyébá. A délé ayé tán ojú p kán gbogbo wa; Orí níí ýatökùn fúnni. Ìgbà ti ara èniyàn kò yá, Òògùn ló lójò kan ìpònjú, Orí ló lójò gbogbo. Orí çni làwùre çni; Orí ló yç kénìyàn ó sìn. Báa bá wálé ayé táa lówó lòwò, Àyànmò ni. Bí a sì wà lókèèrè, táyé p yò wa wò níkòrò, ßebí orí ló sohun gbogbo. Ohun ti Táyé p ýe tó fi lówó lòwò, Òun ni Kèhindé ýe tó dolòsì. Ç má fõrõ àyànmò wéra. Nítori ohun ti a yàn, õtõõtõ ni, Báyé bá yçni, ýebí orí inú çni ni. Báa bá dènìyàn plá, ohun táa dì mò kádàrà ni. Ohun ti a rù lórí, látòde õrun wá ni. Kò sééyàn ti í paýò àgùntàn-án dà. Táyé bá ýelá tílá fi kó, Ténìyàn ýekàn tíkàn bá wêwù èjè Táyé náà bá tún taýò ìjímèrè bepo Ká rántí pé ohun táa mú wáyé látòde õrun ni Kò sëni pa Lágbájà, Kò sëni pa Lákàyègbè: Ó ti wà nínú àkòòlé rè ni. Orí jà ò joògùn Orí là bá máa bò lójò gbogbo Orí ni ààbò çni, Kò sórìjà ti p gbeni lèyin orí çni. Bénìyàn bá ní wàhálà, orí ni yóò ké sí. Máà bënìkan sò, Nítorí ènìyàn kò fëni fòrõ, à forí çni. līdī ti akēwī fī nī kā bórí sō kā māā bēnikan sō nī pé', null, '["ēnīyān kō fēnī fōrō","a kō mçnī tō fēnī dēnú","çnīkan kō bāni yan orī çnī","orī nī ēdā sīn wāyé."]', 0, 'Ìdí tí akēwī fī nī kā bórí sō kā māā bēnikan sō nī pé ēnīyān kō fēnī fōrō.', true, '2026-10-13 13:22:38.032', '2026-10-13 13:22:38.032', null, null, null, 'Orí loníye, édá láyànmò. Àkúnléyàn òun ni àdáyébá. A délé ayé tán ojú p kán gbogbo wa; Orí níí ýatökùn fúnni. Ìgbà ti ara èniyàn kò yá, Òògùn ló lójò kan ìpònjú, Orí ló lójò gbogbo. Orí çni làwùre çni; Orí ló yç kénìyàn ó sìn. Báa bá wálé ayé táa lówó lòwò, Àyànmò ni. Bí a sì wà lókèèrè, táyé p yò wa wò níkòrò, ßebí orí ló sohun gbogbo. Ohun ti Táyé p ýe tó fi lówó lòwò, Òun ni Kèhindé ýe tó dolòsì. Ç má fõrõ àyànmò wéra. Nítori ohun ti a yàn, õtõõtõ ni, Báyé bá yçni, ýebí orí inú çni ni. Báa bá dènìyàn plá, ohun táa dì mò kádàrà ni. Ohun ti a rù lórí, látòde õrun wá ni. Kò sééyàn ti í paýò àgùntàn-án dà. Táyé bá ýelá tílá fi kó, Ténìyàn ýekàn tíkàn bá wêwù èjè Táyé náà bá tún taýò ìjímèrè bepo Ká rántí pé ohun táa mú wáyé látòde õrun ni Kò sëni pa Lágbájà, Kò sëni pa Lákàyègbè: Ó ti wà nínú àkòòlé rè ni. Orí jà ò joògùn Orí là bá máa bò lójò gbogbo Orí ni ààbò çni, Kò sórìjà ti p gbeni lèyin orí çni. Bénìyàn bá ní wàhálà, orí ni yóò ké sí. Máà bënìkan sò, Nítorí ènìyàn kò fëni fòrõ, à forí çni. līdī ti akēwī fī nī kā bórí sō kā māā bēnikan sō nī pé', '["ēnīyān kō fēnī fōrō","a kō mçnī tō fēnī dēnú","çnīkan kō bāni yan orī çnī","orī nī ēdā sīn wāyé."]', 'Ìdí tí akēwī fī nī kā bórí sō kā māā bēnikan sō nī pé ēnīyān kō fēnī fōrō.', '{"bold":["ēnīyān kō fēnī fōrō"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('95b729ed-36da-4a1f-8fc3-5f567c0498e8', 'Physics', 'JAMB', null, 1994, null, 'In a projection lantern of focal length f, the object distance u is such that', null, '["u > 2f > f","u < f < 2f","u = f < 2f","f < u < 2f"]', 3, 'A projector needs a real, magnified image on a distant screen. This happens when the slide is placed between f and 2f from the lens.', true, '2026-10-12 19:15:40.13', '2026-10-12 19:15:40.13', null, null, null, 'In a projection lantern of focal length f, the object distance u is such that', '["u > 2f > f","u < f < 2f","u = f < 2f","f < u < 2f"]', 'A projector needs a real, magnified image on a distant screen. This happens when the slide is placed between f and 2f from the lens.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('95c5daa2-9cfe-49ad-9800-0b8f619a43c5', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). The take home pay of many workers is such that they can hardly <u>make both ends meet</u>. This means ________________', null, '["live an honest life","finish their schedule of work","keep two jobs at a time","live within their income","live on both ends"]', 3, '''Make both ends meet'' means live within income.', true, '2026-10-24 01:02:01.203', '2026-10-24 01:02:01.203', null, null, null, '(Choose the most appropriate interpretation). The take home pay of many workers is such that they can hardly <u>make both ends meet</u>. This means ________________', '["live an honest life","finish their schedule of work","keep two jobs at a time","<u>live within their income</u>","live on both ends"]', '''<b>Make both ends meet</b>'' means <b>live within income</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('95dd764b-7e2d-48a9-8592-2275e4f1141d', 'Financial Accounting', 'UTME', null, 2002, null, 'NAFARA & SONS Balance sheet as at 31st December, 1987. Capital Creditors Prepaid expenses Motor vehicles Furniture Accrued expenses Stock Cash balance Debtors. Compute the value of current assets.', 'https://res.cloudinary.com/kwi1uv0g/image/upload/v1791840662/questions/cmu1hhcvmnoklzdukhfn.jpg', '["N 20400","N 20465","N 35695","N 19820"]', 0, 'Current assets are assets that exist for only short-term. Stock 8100 + Debtors 1809 + Prepaid Expenses 580 + Cash Balance 991 = 20400.', true, '2026-10-12 21:59:57.039', '2026-10-12 21:59:57.039', null, null, null, 'NAFARA & SONS Balance sheet as at 31st December, 1987. Capital Creditors Prepaid expenses Motor vehicles Furniture Accrued expenses Stock Cash balance Debtors. Compute the value of current assets.', '["<b>N 20400</b>","N 20465","N 35695","N 19820"]', 'Current assets are assets that exist for only short-term. Stock 8100 + Debtors 1809 + Prepaid Expenses 580 + Cash Balance 991 = <b>20400</b>.', '{"bold":["N 20400"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('96090ad6-c55e-46ab-81d3-9c89d939c1c4', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. He is very <u>modest</u> in his demands.', null, '["honest","bogus","extravagant","humble"]', 3, 'Modest = humble.', true, '2026-10-24 01:03:58.726', '2026-10-24 01:03:58.726', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. He is very <u>modest</u> in his demands.', '["honest","bogus","extravagant","<u>humble</u>"]', '<b>Modest</b> = <b>humble</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('960f85ac-6fd8-4d46-9f61-22d1c8b1a9bb', 'Literature in English', 'JAMB', null, 2026, null, '''He passed away'' instead of ''he died'' is an example of', null, '["Malapropism","Euphemism","Antonomasia","Paradox"]', 1, 'It is an example of euphemism.', true, '2026-09-12 11:10:25.767', '2026-09-12 11:10:25.767', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('96171c24-0331-4fc7-a75c-994840a400ee', 'English Language', 'JAMB', null, 2024, null, 'What sort of life, according to the passage, will drive people back like aimless sheep back to cave dwelling?', null, '["life without risks","life without science and technology","life without ambition","life without hope"]', 0, 'The passage suggests that if we were all to revert to the farmer''s simple, risk-free life, we would be driven back to cave dwelling.', true, '2026-09-18 10:16:10.264', '2026-09-18 10:16:10.264', '11a7b560-dd3b-4c82-b5ad-fe71fdd120ed', 4, 'COMPREHENSION', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('961bcf36-ef23-43fe-b414-355db2fd49d6', 'Literature in English', 'JAMB', null, 2026, null, 'The narrative technique employed in Path of Lucas: The Journey He Endured is best described as', null, '["A first-person autobiographical account limited to a single perspective","A third-person narrative that explores the protagonist''s internal and external conflicts","A purely epistolary structure based on letters","A dramatic script with dialogue only"]', 1, 'The narrative technique is third-person, exploring internal and external conflicts.', true, '2026-09-12 11:04:57.949', '2026-09-12 11:04:57.949', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('963ca551-6444-4e5c-8ad9-a003654d7dcd', 'Literature in English', 'JAMB', null, 2026, null, '______ are examples of meter classification based on two syllables.', null, '["anapest, septet, iamb, trochaic","iamb, pyrrhic, trochaic, spondee","sonnet, dizain, anapest, pyrrhic","rondeau, monostitched, spondee, dactyle"]', 1, 'Iamb, pyrrhic, trochaic, and spondee are meters based on two syllables.', true, '2026-09-12 11:10:07.816', '2026-09-12 11:10:07.816', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('963d54ef-774b-4c2c-925e-5760e2651104', 'Chemistry', 'JAMB', null, 2026, null, 'Which acid is dibasic?', null, '["HCl","HNO₃","H₂SO₄","H₃PO₄"]', 2, 'H₂SO₄ is dibasic because it can donate two protons.', true, '2026-09-12 11:33:02.045', '2026-09-12 11:33:02.045', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('964facec-00a6-42a8-a1ee-a8d6b1e62438', 'Economics', 'JAMB', null, 2026, null, 'The comparison of the standard of living between Nigeria and Ghana is best known through the use of:', null, '["Per capita income","Gross National Income","Net National Income","Disposable income"]', 0, 'Per capita income is used to compare standards of living.', true, '2026-09-12 11:01:27.624', '2026-09-12 11:01:27.624', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9667e587-a345-46fb-8b4d-22647b1d8c8d', 'English Language', 'JAMB', null, 2024, null, 'Which of the following best describe the character of Mr. Alabi in the novel?', null, '["an opposition to Bepo''s reforms","A supporter of Bepo''s reforms","an indifferent party to Bepo''s reforms","unaware of Bepo''s reforms"]', 0, 'Mr. Alabi opposed Bepo''s reforms.', true, '2026-09-18 09:34:04.043', '2026-09-18 09:34:04.043', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('96741d86-0f6a-42a1-9b24-87c2c2788034', 'Literature in English', 'JAMB', null, 2026, null, 'The expression ''After our bloody century'' in the poem refers to', null, '["a century of celebration","a period marked by wars and violence","an era of technological progress","a time of peace and prosperity"]', 1, 'It refers to a period marked by wars and violence.', true, '2026-09-12 11:05:47.462', '2026-09-12 11:05:47.462', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9675466e-ab7d-4b97-ac39-843402e36e42', 'Government', 'JAMB', null, 2026, null, 'The term "Supremacy of Parliament" connotes that Parliament', null, '["Is above the Law","is not subject to judicial control","has power to enact any Law","is above all other organs of Government"]', 2, 'The term "Supremacy of Parliament" connotes that Parliament has power to enact any law. Parliamentary supremacy means that Parliament is the supreme legal authority and can make or unmake any law. No other body can override or invalidate Parliament''s legislation. However, Parliament is not above the law; it is subject to the law it makes. This principle is a feature of the Westminster parliamentary system.', true, '2026-09-10 10:45:06.837', '2026-09-10 10:45:06.837', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('967ec182-f321-46d7-b796-d1df61b40b1f', 'Physics', 'JAMB', null, 1991, null, 'A brass rod is 2 m long at a certain temperature. What is the length for a temperature rise of 100 K if the expansivity of brass is 18 x 10⁻⁶ K⁻¹?', null, '["2.0036 m","2.0018 m","2.1800 m","2.0360 m"]', 0, 'ΔL = L α Δθ = 2 x 18 x 10⁻⁶ x 100 = 0.0036 m, so new length = 2.0036 m.', true, '2026-10-12 19:15:33.083', '2026-10-12 19:15:33.083', null, null, null, 'A brass rod is 2 m long at a certain temperature. What is the length for a temperature rise of 100 K if the expansivity of brass is 18 x 10<sup>-6</sup> K<sup>-1</sup>?', '["2.0036 m","2.0018 m","2.1800 m","2.0360 m"]', 'ΔL = L α Δθ = 2 x 18 x 10<sup>-6</sup> x 100 = 0.0036 m, so new length = 2.0036 m.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('968710d6-7bdc-471f-a291-cdc07346819a', 'Literature in English', 'JAMB', null, 2026, null, 'A common thematic link between Digging and Still I Rise is', null, '["The rejection of history","The inevitability of death","The importance of romantic love","The celebration of identity and personal strength"]', 3, 'Both poems celebrate identity and personal strength.', true, '2026-09-12 11:12:04.657', '2026-09-12 11:12:04.657', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('968a231d-1cc5-43a1-88f6-12cd0adb654c', 'Hausa', 'JAMB', null, 2010, null, 'Wacce ke da hanyar jam''i daban?', null, '["Kwando.","Hula.","Rumbu.","Kwabri."]', 3, 'Kwabri tana da hanyar jam''i daban.', true, '2026-10-13 10:37:23.878', '2026-10-13 10:37:23.878', null, null, null, 'Wacce ke da hanyar jam''i daban?', '["Kwando.","Hula.","Rumbu.","Kwabri."]', 'Kwabri tana da hanyar jam''i daban.', '{"bold":["Kwabri"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('96a0f84c-07f5-4e17-8e41-43bb84497d59', 'English Language', 'JAMB', null, 2024, null, 'Choose the option opposite in meaning to the underlined word: Science may be a complicated area of learning, but its teaching needs to be demystified.', null, '["simplified","twisted","made difficult","distorted"]', 2, '"Demystified" means made clear or easy to understand; the opposite is "made difficult."', true, '2026-09-18 09:23:08.522', '2026-09-18 09:23:08.522', null, null, 'STANDALONE', null, null, null, null);
