insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('96f85a21-10bf-4407-809c-8342f813dde2', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. In the course of the debate, the speakers were advised to <u>summarize</u> their points.', null, '["argue","develop","round off","round up"]', 1, 'Summarize = condense; opposite = develop.', true, '2026-10-24 07:21:16.019', '2026-10-24 07:21:16.019', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. In the course of the debate, the speakers were advised to <u>summarize</u> their points.', '["argue","develop","round off","round up"]', 'Summarize = condense; opposite = develop.', '{}');
