insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9712e8db-1687-4e45-8f62-ee6c3c47f000', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'What did Paul compare the church to in 1 Corinthians 12?', null, '["a field","a holy temple","a body","a vine"]', 2, 'Paul compared the church to a body in 1 Corinthians 12. Just as a body has many members with different functions, the church has many members with different spiritual gifts, but all are needed and work together under Christ as the head.', true, '2026-09-12 09:45:50.051', '2026-09-12 09:45:50.051', null, null, null, null, null, null, null);
