insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('972acc8d-12c0-4181-adb6-309b2ceca1f8', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). Mr. Rufus <u>bore the brunt</u> in the last promotion examination', null, '["Mr. Rufus failed the examination woefully","Mr. Rufus excelled in the examination","Mr. Rufus was excited about the examination","Mr. Rufus toyed with the examination"]', 0, '''Bore the brunt'' = suffered the worst part.', true, '2026-10-24 01:04:24.362', '2026-10-24 01:04:24.362', null, null, null, '(Choose the most appropriate interpretation). Mr. Rufus <u>bore the brunt</u> in the last promotion examination', '["<u>Mr. Rufus failed the examination woefully</u>","Mr. Rufus excelled in the examination","Mr. Rufus was excited about the examination","Mr. Rufus toyed with the examination"]', '''<b>Bore the brunt</b>'' = <b>suffered the worst part</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('972b6f18-1a83-426d-b6d9-b9bebc6e2af3', 'Literature in English', 'JAMB', null, 2026, null, 'What are they discussing?', null, '["the throne","war","Love affairs","grievances"]', 2, 'They are discussing love affairs.', true, '2026-09-12 11:14:17.041', '2026-09-12 11:14:17.041', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9734a736-fe60-4f4e-ac72-94704f13ca07', 'English Language', 'JAMB', null, 2007, null, 'There are many <u>__________</u> to her personality', null, '["moods","styles","facets","faces"]', 2, 'Correct spelling: facets.', true, '2026-10-24 07:21:45.777', '2026-10-24 07:21:45.777', null, null, null, 'There are many <u>__________</u> to her personality', '["moods","styles","facets","faces"]', 'Correct spelling: facets.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('973ca65e-07d1-476c-b86f-8f3c21bfbfab', 'Financial Accounting', 'UTME', null, 2002, null, 'In a complete record system, a trading account cannot be prepared until the', null, '["day book has been balanced","amount of personal drawings has been established","cash book has been balanced","amount of sales and purchases has been established"]', 3, 'Major elements of Trading Account are Sales and Purchase figures. In fact, without any of the two there cannot be Trading account.', true, '2026-10-12 21:59:58.596', '2026-10-12 21:59:58.596', null, null, null, 'In a complete record system, a trading account cannot be prepared until the', '["day book has been balanced","amount of personal drawings has been established","cash book has been balanced","<b>amount of sales and purchases has been established</b>"]', 'Major elements of Trading Account are Sales and Purchase figures. In fact, without any of the two there cannot be Trading account, so the <b>amount of sales and purchases must be established</b>.', '{"bold":["amount of sales and purchases must be established"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9741968f-4790-4436-8e0a-9ca93a14ce6d', 'Biology', 'JAMB', null, 2026, null, 'The adaptive feature of plants in the Savanna is', null, '["fissured bark","few grasses","tall grasses","long lifespan"]', 0, 'Fissured (thick, rough) bark is an adaptive feature of plants in the savanna, particularly trees. Thick bark protects against fire, which is common in the savanna biome. Tall grasses are characteristic of savannas but are not specifically an adaptive feature of plants. Few grasses is incorrect. Long lifespan is not specific to savanna plants. Savanna plants have adaptations to survive drought, fire, and grazing, including fire-resistant bark, deep root systems, and the ability to shed leaves during dry periods.', true, '2026-09-09 03:18:50.632', '2026-09-09 03:18:50.632', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('974af490-e0d3-4d12-9362-9668352b3a87', 'Chemistry', 'JAMB', null, 2026, null, 'Calculate the volume of carbon dioxide produced when 5.0 g of calcium carbonate is completely decomposed by heating. [Ca = 40, C = 12, O = 16; 1 mole of gas occupies 24 dm³ at r.t.p]', null, '["0.60 dm³","1.20 dm³","2.40 dm³","3.60 dm³"]', 1, 'CaCO3 -> CaO + CO2. Molar mass CaCO3 = 100 g/mol. Moles CaCO3 = 5.0 / 100 = 0.05 mol. Volume CO2 = 0.05 * 24 dm3 = 1.20 dm3.', true, '2026-09-09 17:12:48.462', '2026-09-09 17:12:48.462', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('974b86ee-fca8-4fb8-90ab-65d40c9e78c2', 'English Language', 'JAMB', null, 2024, null, 'When the beggar was tired he ______ down by the roadside.', null, '["Lied","Laid","Layed","Lay","lain"]', 3, '"Lay" is the past tense of "lie" (to recline).', true, '2026-09-18 09:24:04.678', '2026-09-18 09:24:04.678', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('975a2ba8-be1f-406c-a064-63d51ef407f8', 'English Language', 'JAMB', null, 2007, null, 'He was not a very <u>__________</u> student when I first met him but the years <u>__________</u> his character ultimately.', null, '["mature/mature","matured/mature","mature/matured","matured/matured"]', 2, 'Correct forms: mature/matured.', true, '2026-10-24 07:21:33.2', '2026-10-24 07:21:33.2', null, null, null, 'He was not a very <u>__________</u> student when I first met him but the years <u>__________</u> his character ultimately.', '["mature/mature","matured/mature","mature/matured","matured/matured"]', 'Correct forms: mature/matured.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('97622e81-30ee-4435-9eb7-ddfbc39da769', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The man''s story sounded <u>plausible</u> to his audience.', null, '["fantastic","credulous","credible","entertaining"]', 2, 'Plausible = credible.', true, '2026-10-24 01:01:52.676', '2026-10-24 01:01:52.676', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The man''s story sounded <u>plausible</u> to his audience.', '["fantastic","credulous","<u>credible</u>","entertaining"]', '<b>Plausible</b> = <b>credible</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9764f979-e036-465f-a42b-eb3805544344', 'English Language', 'JAMB', null, 2024, null, 'Bala was able to lift his luggage', null, '["in spite of it''s weight","despite of its weight","in spite of its weight","in despite its weight"]', 2, '"In spite of" is the correct phrase, and "its" is the possessive form (not "it''s" which means "it is").', true, '2026-09-18 09:23:08.263', '2026-09-18 09:23:08.263', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9767c8fd-03ae-4aa5-abdf-97a578249869', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'The elders at Jerusalem advised Paul on his arrival to the city to', null, '["Avoid Jewish Christians","purify himself along with men under vows","join those in the temple for prayer and fasting","preach the good news"]', 1, 'They advised Paul to purify himself with men under vows.', true, '2026-09-12 10:41:49.932', '2026-09-12 10:41:49.932', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('977887d2-2651-46f6-8137-8abc7cad3dc0', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The leader called for <u>concerted</u> efforts in order to get over the problems.', null, '["combined","definite","disparate","isolated"]', 2, 'Concerted = combined; opposite = disparate.', true, '2026-10-24 07:21:16.994', '2026-10-24 07:21:16.994', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The leader called for <u>concerted</u> efforts in order to get over the problems.', '["combined","definite","disparate","isolated"]', 'Concerted = combined; opposite = disparate.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9791242c-e157-4267-bf0e-83822b72d287', 'Physics', 'JAMB', null, 1990, null, 'A car moving with a speed of 90 km h⁻¹ was brought uniformly to rest by the application of the brakes in 10 s. How far did the car travel after the brakes were applied?', null, '["125 m","150 m","250 m","15 km"]', 0, '90 km h⁻¹ = 25 m s⁻¹. Distance = average speed x time = (25/2) x 10 = 125 m.', true, '2026-10-12 19:15:30.386', '2026-10-12 19:15:30.386', null, null, null, 'A car moving with a speed of 90 km h<sup>-1</sup> was brought uniformly to rest by the application of the brakes in 10 s. How far did the car travel after the brakes were applied?', '["125 m","150 m","250 m","15 km"]', '90 km h<sup>-1</sup> = 25 m s<sup>-1</sup>. Distance = average speed x time = (25/2) x 10 = 125 m.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('979508fa-3b2a-4249-9f49-b8719246529d', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'The church that was commended for giving even when in extreme poverty was in', null, '["Corinth","Galatia","Thessalonica","Macedonia"]', 3, 'The churches in Macedonia gave generously despite extreme poverty.', true, '2026-09-12 10:41:44.339', '2026-09-12 10:41:44.339', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('979edb52-d040-4dcd-8890-78fe7144e0c6', 'Literature in English', 'JAMB', null, 2026, null, 'The phrase ''life''s whole process blooms into stark beauty'' suggests that the celebrant''s life has been', null, '["difficult and without reward","beautiful in spite of its difficulties","completely flawless and easy","struggle with an ugly outcome"]', 1, 'The phrase suggests a beautiful life despite difficulties.', true, '2026-09-12 11:07:22.333', '2026-09-12 11:07:22.333', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('97a26881-6a01-466d-9d07-ea5708ebe93b', 'English Language', 'JAMB', null, 2024, null, 'The prisoner finally ______ that he drank to ______ on the night he committed the murder', null, '["exceeded/extreme","acceded/access","conceded/excess","eluded/escape"]', 2, '"Conceded" means admitted, and "excess" means too much.', true, '2026-09-18 09:43:02.228', '2026-09-18 09:43:02.228', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('97a70f70-107e-4509-b3b7-6a0dbcdb50a3', 'Physics', 'JAMB', null, 1990, null, 'Which of the following conditions will make water boil at a temperature of 100 °C when the atmospheric pressure is 750 mm Hg?', null, '["Increase the external pressure","Reduce the external pressure","Heat more rapidly at the same pressure.","Reduce the external pressure by a quarter."]', 0, 'Water boils at 100 °C only at standard pressure (760 mm Hg). At 750 mm Hg the pressure must be increased.', true, '2026-10-12 19:15:30.981', '2026-10-12 19:15:30.981', null, null, null, 'Which of the following conditions will make water boil at a temperature of 100 °C when the atmospheric pressure is 750 mm Hg?', '["Increase the external pressure","Reduce the external pressure","Heat more rapidly at the same pressure.","Reduce the external pressure by a quarter."]', 'Water boils at 100 °C only at standard pressure (760 mm Hg). At 750 mm Hg the pressure must be increased.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('97ae598c-704e-4582-ace5-10622fdafa59', 'Physics', 'JAMB', null, 1989, null, 'Three resistors, with resistances 250 Ω, 500 Ω and 1 kΩ are connected in series. A 6 V battery is connected to either end of the combination. Calculate the potential difference between the ends of the 250 Ω resistor.', null, '["0.20 V","0.86 V","1.71 V","3.43 V."]', 1, 'Total resistance = 1750 Ω. V = 6 x 250/1750 = 0.86 V.', true, '2026-10-12 19:15:29.903', '2026-10-12 19:15:29.903', null, null, null, 'Three resistors, with resistances 250 Ω, 500 Ω and 1 kΩ are connected in series. A 6 V battery is connected to either end of the combination. Calculate the potential difference between the ends of the 250 Ω resistor.', '["0.20 V","0.86 V","1.71 V","3.43 V."]', 'Total resistance = 1750 Ω. V = 6 x 250/1750 = 0.86 V.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('97b5f728-cf27-41ea-8505-13b9496fc0fc', 'Biology', 'JAMB', null, 2026, null, 'Which of the following minerals is not typically required by plants for their growth and development?', null, '["nitrogen","aluminium","potassium","phosphorus"]', 1, 'Aluminium is not an essential element for plant growth. While some plants can accumulate aluminium (as in some acid-tolerant species), it is not considered a nutrient. In fact, aluminium can be toxic to many plants at high concentrations in acidic soils. Nitrogen (N), potassium (K), and phosphorus (P) are macronutrients essential for plant growth: nitrogen for proteins and chlorophyll, potassium for enzyme activation and water regulation, and phosphorus for ATP and nucleic acids.', true, '2026-09-09 03:18:18.557', '2026-09-09 03:18:18.557', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('97c0f490-152b-4f27-9452-7a761278d146', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Violent crime is only one of the <u>maladies</u> afflictions modern society.', null, '["damages","illnesses","wounds","crises"]', 1, 'Maladies = illnesses.', true, '2026-10-24 01:04:08.643', '2026-10-24 01:04:08.643', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Violent crime is only one of the <u>maladies</u> afflictions modern society.', '["damages","<u>illnesses</u>","wounds","crises"]', '<b>Maladies</b> = <b>illnesses</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('97d25e99-5ba0-49d9-9841-4a483d896d37', 'Economics', 'JAMB', null, 2026, null, 'In economics, production is complete when', null, '["Goods are produced in the factories","Goods are sold to the wholesaler","Goods and services are produced by the government","Prices are fixed for goods and services","Goods and services finally reach the consumer"]', 4, 'In economics, production is complete when goods and services finally reach the consumer. Production is not complete when goods are manufactured in factories; they must be transported, distributed, and sold to the final consumer. Production includes all activities from extraction to the final consumption of goods and services. This is why transportation, storage, and distribution are all part of production.', true, '2026-09-10 10:41:19.808', '2026-09-10 10:41:19.808', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('97f0ff21-7c79-4167-8ecd-c790b31e0fe4', 'Chemistry', 'JAMB', null, 2026, null, 'The ions X⁻ and Y⁺ are isoelectronic each containing a total of 10 electrons. How many protons are in the nuclei of the neutral atoms of X and Y respectively', null, '["10 and 10","9 and 9","11 and 9","9 and 11"]', 3, 'X⁻ has 10 electrons, so X has 9 protons. Y⁺ has 10 electrons, so Y has 11 protons.', true, '2026-09-12 11:36:00.942', '2026-09-12 11:36:00.942', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('97f43f90-f8c2-45d0-931f-c630510ebfd5', 'Hausa', 'JAMB', null, 2010, null, 'Danmaraya Jos ya na amfani ne da', null, '["kuntigi","gurmi","garaya","molo"]', 0, 'Danmaraya Jos na amfani da kuntigi.', true, '2026-10-13 10:37:24.305', '2026-10-13 10:37:24.305', null, null, null, 'Danmaraya Jos ya na amfani ne da', '["kuntigi","gurmi","garaya","molo"]', 'Danmaraya Jos na amfani da kuntigi.', '{"bold":["kuntigi"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('97f5536c-0178-4e48-bf82-9b4a5b2eab4a', 'Financial Accounting', 'UTME', null, 2002, null, 'Upon the dissolution of the partnership, the partnership Act provides that the amount realized should be', null, '["used to pay all taxes due to government","used to start a new partnership business by members who are willing","shared equally by the existing partners","used in paying the debts and liabilities of the firm to person who are not partners"]', 3, 'The proceeds from assets of partnership will be used to settle outsiders first i.e., the creditors of the partnership.', true, '2026-10-12 21:59:59.09', '2026-10-12 21:59:59.09', null, null, null, 'Upon the dissolution of the partnership, the partnership Act provides that the amount realized should be', '["used to pay all taxes due to government","used to start a new partnership business by members who are willing","shared equally by the existing partners","<b>used in paying the debts and liabilities of the firm to person who are not partners</b>"]', 'The proceeds from assets of partnership will be <b>used to settle outsiders first</b> i.e., the creditors of the partnership.', '{"bold":["used to settle outsiders first"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('97fcd875-5c5f-44ec-9b2f-e217e01f5612', 'General Mathematics', 'JAMB', null, 2026, null, 'Find the tangent of the acute angle between lines 2x + y = 3 and 3x - 2y = 5', null, '["-7/4","7/8","7/4","7/2"]', 2, 'Slopes: m₁ = -2, m₂ = 3/2. tan θ = |(m₁-m₂)/(1+m₁m₂)| = |(-2-1.5)/(1-3)| = |-3.5/-2| = 7/4.', true, '2026-09-12 11:43:43.781', '2026-09-12 11:43:43.781', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('97fdfba9-597e-4594-9e51-c624d7103bb1', 'Literature in English', 'JAMB', null, 2026, null, 'The poem is primarily a tribute to a person who has attained a significant milestone', null, '["marriage","birthday","graduation","promotion"]', 1, 'The poem is a tribute to a birthday milestone.', true, '2026-09-12 11:13:46.398', '2026-09-12 11:13:46.398', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('97ffec6a-44cd-4811-8dba-6fc7962a6cba', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The driver, on seeing the traffic warden, was <u>hesitant</u> to start the engine.', null, '["slow","unable","anxious","reluctant"]', 3, 'Hesitant = reluctant.', true, '2026-10-24 01:03:54.676', '2026-10-24 01:03:54.676', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The driver, on seeing the traffic warden, was <u>hesitant</u> to start the engine.', '["slow","unable","anxious","<u>reluctant</u>"]', '<b>Hesitant</b> = <b>reluctant</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('98062584-e3ae-4415-9530-126091cc48aa', 'Literature in English', 'JAMB', null, 2026, null, 'What does this reveal about Antony''s attitude?', null, '["He accepts death honorably and fearlessly","He is terrified of dying","He blames Cleopatra","He plans revenge"]', 0, 'He accepts death honorably and fearlessly.', true, '2026-09-12 11:14:15.494', '2026-09-12 11:14:15.494', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('980d37a9-0d10-403d-863b-008237b16ea9', 'English Language', 'JAMB', null, 2024, null, 'Because of the hard times, many workers live in ______ poverty', null, '["repulsive","ridiculous","abject","unpardonable"]', 2, '"Abject poverty" is the correct collocation meaning extreme poverty.', true, '2026-09-18 09:24:04.942', '2026-09-18 09:24:04.942', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('981ceb75-9205-4e1e-bb44-546cbe0868da', 'Hausa', 'JAMB', null, 2011, null, 'Wannan alamar (-), ita aka fi sani da', null, '["wakafi","ruwa biyu","karan dori","debewa"]', 2, 'Alamar (-) ita aka fi sani da karan dori.', true, '2026-10-13 10:37:20.792', '2026-10-13 10:37:20.792', null, null, null, 'Wannan alamar (-), ita aka fi sani da', '["wakafi","ruwa biyu","karan dori","debewa"]', 'Alamar (-) ita aka fi sani da karan dori.', '{"bold":["karan dori"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('98206a86-13f4-4561-860a-7b47f8311af5', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Ezekiel''s vision of dry bones symbolises', null, '["divine judgement","restoration of Israel","destruction of enemies","exile"]', 1, 'The dry bones symbolised Israel''s restoration.', true, '2026-09-12 10:40:59.394', '2026-09-12 10:40:59.394', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9837fac5-a1a1-41c5-b4be-d334d1c15ace', 'Physics', 'JAMB', null, 1989, null, 'A column of air 10.0 cm long is trapped in a tube at 27 °C. What is the length of the air column at 100 °C?', null, '["12.4 cm","13.7 cm","18.5 cm","37.0 cm"]', 0, 'Charles'' law: L₂ = 10.0 x 373/300 = 12.4 cm.', true, '2026-10-12 19:15:29.032', '2026-10-12 19:15:29.032', null, null, null, 'A column of air 10.0 cm long is trapped in a tube at 27 °C. What is the length of the air column at 100 °C?', '["12.4 cm","13.7 cm","18.5 cm","37.0 cm"]', 'Charles'' law: L<sub>2</sub> = 10.0 x 373/300 = 12.4 cm.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('98405829-4f33-4bd5-abf1-b63882f74fcc', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Obi''s dog is old but still <u>lively</u>.', null, '["barking","frisky","howling","attractive"]', 1, 'Lively = frisky.', true, '2026-10-24 01:04:05.846', '2026-10-24 01:04:05.846', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Obi''s dog is old but still <u>lively</u>.', '["barking","<u>frisky</u>","howling","attractive"]', '<b>Lively</b> = <b>frisky</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('984d093b-c000-48d0-961b-fa5048da4cde', 'Physics', 'JAMB', null, 2026, null, 'The resultant of two forces acting on an object is maximum when the angle between them is', null, '["180","90","45","0"]', 3, 'The resultant of two forces is maximum when the angle between them is 0° (they act in the same direction). The resultant is the sum of the magnitudes.', true, '2026-09-10 10:56:50.052', '2026-09-10 10:56:50.052', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('985399db-23e9-4f14-8967-fe6905e0da0b', 'Government', 'JAMB', null, 2026, null, 'A sovereign state is one', null, '["Whose constitution can only be changed by a military government","Where its citizens can speak without fear or favour","Whose citizens are free to evade responsibility","Whose government decisions are made independent of foreign interference"]', 3, 'A sovereign state makes decisions independent of foreign interference.', true, '2026-09-12 11:24:18.865', '2026-09-12 11:24:18.865', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('98581667-10cc-48b4-b9d0-c0593eaf6366', 'Literature in English', 'JAMB', null, 2026, null, 'The title So the Path Does Not Die primarily suggests', null, '["the inevitability of death","the preservation of tradition and legacy","the struggle for political power","the importance of education"]', 1, 'The title suggests the preservation of tradition and legacy.', true, '2026-09-12 11:11:57.473', '2026-09-12 11:11:57.473', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9869e9c5-5c40-4016-a369-0e63381d5d26', 'Biology', 'JAMB', null, 2026, null, 'The excretory organ in insects is the', null, '["flame cell","nephridium","Malpighian tubule","kidney"]', 2, 'Malpighian tubules are the excretory organs in insects. These are blind-ended tubules that project from the gut into the hemocoel, absorbing waste products (uric acid, ions) from the hemolymph and transporting them to the alimentary canal for elimination. Flame cells are found in flatworms. Nephridia are found in annelids and mollusks. Kidneys are the excretory organs of vertebrates. Malpighian tubules are an efficient system for excreting nitrogenous waste while conserving water, which is why insects produce uric acid rather than urea or ammonia.', true, '2026-09-09 03:18:42.875', '2026-09-09 03:18:42.875', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('987bba50-7ecb-43e6-96b1-601abfcb7ef2', 'Financial Accounting', 'UTME', null, 2002, null, 'The Assets and Liabilities of Udo Co. Ltd. as at 31st December, 2000. Creditors 50000 Debtors 46000 Loan 10000 Stock 20000 Motor vehicle 120000 Building 70000 Accrued wages 30000 Bank 25000. The value of money invested by the owners is', 'https://res.cloudinary.com/kwi1uv0g/image/upload/v1791840710/questions/qjse54gjfnvhxgj5clxp.jpg', '["N 110,000","N 105,000","N 101,000","N 100,000"]', 2, 'Owner Investment = Total Assets less Liabilities. Building 70,000 + Motor Vehicle 120,000 + Debtors 46,000 + Stock 20,000 + Bank 25,000 = 281000 - Liabilities 180,000 = 101,000.', true, '2026-10-12 21:59:57.089', '2026-10-12 21:59:57.089', null, null, null, 'The Assets and Liabilities of Udo Co. Ltd. as at 31st December, 2000. Creditors 50000 Debtors 46000 Loan 10000 Stock 20000 Motor vehicle 120000 Building 70000 Accrued wages 30000 Bank 25000. The value of money invested by the owners is', '["N 110,000","N 105,000","<b>N 101,000</b>","N 100,000"]', 'Owner Investment = Total Assets less Liabilities. Building 70,000 + Motor Vehicle 120,000 + Debtors 46,000 + Stock 20,000 + Bank 25,000 = 281000 - Liabilities 180,000 = <b>101,000</b>.', '{"bold":["101,000"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('987ef642-012a-485d-8488-cffca3c7ae27', 'Yoruba', 'JAMB', null, 2007, null, 'Ìwé Iyán Ogún Òdún ni ìbéèrè 38-40 dá lé. Ta ni ìyàwó Arówóná?', null, '["Àtòkẹ","Àjòkẹ","Mòdélé","Àbèkẹ"]', 1, 'Àjòkẹ ni ìyàwó Arówóná.', true, '2026-10-13 13:23:32.449', '2026-10-13 13:23:32.449', null, null, null, 'Ìwé Iyán Ogún Òdún ni ìbéèrè 38-40 dá lé. Ta ni ìyàwó Arówóná?', '["Àtòkẹ","Àjòkẹ","Mòdélé","Àbèkẹ"]', 'Àjòkẹ ni ìyàwó Arówóná.', '{"bold":["Àjòkẹ"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('98874776-d74b-4038-a653-52bcec709b55', 'Financial Accounting', 'UTME', null, 2003, null, 'Given: Total debtors b/d 31/12/99 25 000, Cheques received from debtors 255 000, Total debtors c/d 31/12/00 15 000. Determine the sales figure.', 'https://res.cloudinary.com/kwi1uv0g/image/upload/v1791841510/questions/ioimi0l0cl2xm4mpvwvc.jpg', '["N295 000","N265 000","N245 000","N215 000"]', 2, 'Sales Ledger Control Account: Bal b/d 25,000 + Sales 245,000 = 270,000. Cash 255,000 + Bal c/d 15,000 = 270,000. Sales = 245,000.', true, '2026-10-12 22:00:01.065', '2026-10-12 22:00:01.065', null, null, null, 'Given: Total debtors b/d 31/12/99 25 000, Cheques received from debtors 255 000, Total debtors c/d 31/12/00 15 000. Determine the sales figure.', '["N295 000","N265 000","<b>N245 000</b>","N215 000"]', 'Sales Ledger Control Account: Bal b/d 25,000 + Sales 245,000 = 270,000. Cash 255,000 + Bal c/d 15,000 = 270,000. Sales = <b>245,000</b>.', '{"bold":["245,000"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9889799c-827d-410f-96a3-7a51eb8c249f', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Who was sent by God to restore Saul''s sight after his encounter with Jesus on the road to Damascus?', null, '["Simon","Stephen","Aeneas","Ananias"]', 3, 'Ananias was sent to restore Saul''s sight.', true, '2026-09-12 10:41:37.908', '2026-09-12 10:41:37.908', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('988b6bfb-9864-408b-a2b8-a504cbaee446', 'Financial Accounting', 'UTME', null, 2004, null, 'Yahaya''s bank account shows a credit balance of N1 500. He paid N1 700 000 into the bank. What is his expected balance?', null, '["credit balance of N200 000","debit balance of N200 000","credit balance of N3 200 000","debit balance of N3 200 000"]', 2, 'Bank Account Extract: Bal c/d 1500000 + 1700000 = 3200000. When bank shows a debit balance in the book of customer it is a credit balance in the bank showing that the bank is a debtor to the customer.', true, '2026-10-12 22:00:01.951', '2026-10-12 22:00:01.951', null, null, null, 'Yahaya''s bank account shows a credit balance of N1 500. He paid N1 700 000 into the bank. What is his expected balance?', '["credit balance of N200 000","debit balance of N200 000","<b>credit balance of N3 200 000</b>","debit balance of N3 200 000"]', 'Bank Account Extract: Bal c/d 1500000 + 1700000 = 3200000. When bank shows a debit balance in the book of customer it is a <b>credit balance of N3,200,000</b>.', '{"bold":["credit balance of N3,200,000"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('988d20d7-27ed-45ae-baec-9c54bbb5b55a', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Those were the days of the <u>fallacy</u> that some languages are primitive while others are not.', null, '["argument","excuse","misconception","truth"]', 3, 'Fallacy = misconception; opposite = truth.', true, '2026-10-24 07:21:18.921', '2026-10-24 07:21:18.921', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Those were the days of the <u>fallacy</u> that some languages are primitive while others are not.', '["argument","excuse","misconception","truth"]', 'Fallacy = misconception; opposite = truth.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('988f7c73-b384-46dd-bfb9-3b2d8d65a56a', 'Physics', 'JAMB', null, 2026, null, 'A body of mass 10kg on a smooth inclined plane is connected to a smooth pulley to a mass of 15kg as shown below. The acceleration of the system is', null, '["1/4 g","8/25 g","1/2 g","2/5 g","3/4 g"]', 3, 'Using Newton''s second law: a = (m2 - m1 sin θ)g / (m1 + m2). Assuming θ = 30°: a = (15 - 10×0.5)g / (10+15) = (15-5)g/25 = 10g/25 = 2/5 g.', true, '2026-09-10 10:56:49.756', '2026-09-10 10:56:49.756', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9893ac8c-d440-4246-ae78-7911f4bae45e', 'Literature in English', 'JAMB', null, 2026, null, 'The term "dramatist" refers to', null, '["The person who directs the play","the person who writes the play","the main character of the play","the audience of the play"]', 1, 'The term "dramatist" refers to the person who writes the play. A dramatist (also called a playwright) is the author of a drama. They create the characters, dialogue, plot, and stage directions. The director interprets the play for performance, the main character is a role in the play, and the audience watches the performance. The dramatist is the writer.', true, '2026-09-10 10:45:33.807', '2026-09-10 10:45:33.807', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9896eb01-4fac-4107-a99d-a2f5b4359a94', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'In order that Benjamin might be brought to Egypt, Joseph detained', null, '["Reuben","Levi","Judah","Simeon","Zebulun"]', 3, 'Joseph detained Simeon in Egypt as a guarantee that his brothers would return with Benjamin. He bound Simeon before their eyes and told them to bring Benjamin back to prove they were not spies.', true, '2026-09-12 09:46:01.012', '2026-09-12 09:46:01.012', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('98a624b4-dc90-484f-9b69-6a7ef5109d6e', 'English Language', 'JAMB', null, 2024, null, 'The tone of the writer in this passage is', null, '["Critical","Argumentative","Analytical","Ideological"]', 0, 'The writer is critical of the tobacco companies'' deception.', true, '2026-09-18 09:34:04.027', '2026-09-18 09:34:04.027', null, null, 'COMPREHENSION', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('98ab67b3-9ec4-4cab-9b55-68c326d5fabf', 'Physics', 'JAMB', null, 1986, null, 'Which of the following is NOT a part of the d.c. electric motor?', null, '["Field-magnet","Armature","Commutator","Transformer."]', 3, 'A d.c. motor has a field magnet, armature coil and commutator. A transformer is a separate a.c. device.', true, '2026-10-12 19:15:24.217', '2026-10-12 19:15:24.217', null, null, null, 'Which of the following is <b>NOT</b> a part of the d.c. electric motor?', '["Field-magnet","Armature","Commutator","Transformer."]', 'A d.c. motor has a field magnet, armature coil and commutator. A transformer is a separate a.c. device.', '{"bold":["NOT"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('98acdd3c-bd62-4b71-ad48-fa1b738e9098', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The carpenter built a <u>commodious</u> wardrobe.', null, '["gigantic","small","spacious","wide"]', 2, 'Commodious = spacious.', true, '2026-10-24 01:04:04.937', '2026-10-24 01:04:04.937', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The carpenter built a <u>commodious</u> wardrobe.', '["gigantic","small","<u>spacious</u>","wide"]', '<b>Commodious</b> = <b>spacious</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('98ae6ba1-29c8-43ff-8eab-ab7212dc7f48', 'Government', 'JAMB', null, 2026, null, 'The process whereby the electorate votes for representatives who in turn vote on their behalf is called', null, '["An indirect election","An unfair election","A rigged election","A disputed election"]', 0, 'This is an indirect election.', true, '2026-09-12 11:24:23.436', '2026-09-12 11:24:23.436', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('98b8769a-6968-48ad-a9d8-8f768892ce88', 'Literature in English', 'JAMB', null, 2026, null, 'In the line: ''Golden rays danced upon the trembling sea,'' which imagery is most dominant?', null, '["Auditory","Visual","Tactile","Olfactory"]', 1, 'Visual imagery is most dominant.', true, '2026-09-12 11:11:29.127', '2026-09-12 11:11:29.127', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('98b97424-481c-47ae-8485-13cc545d84bc', 'Chemistry', 'JAMB', null, 2026, null, 'An decrease in atomic size and an increase in nuclear charge across a period leads to', null, '["an increase in chemical reactivity","a decrease in electropositivity","an increase in the tendency to lose electron","a decrease in the covalency in bond formation"]', 1, 'Across a period, higher effective nuclear charge holds valence electrons more tightly, reducing the tendency to lose electrons (electropositivity).', true, '2026-09-09 17:12:44.983', '2026-09-09 17:12:44.983', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('98ba79cd-69f4-4136-b1ac-5ca8bc89eebe', 'Biology', 'JAMB', null, 2010, null, 'Which of the following organisms is mainly found in the marine habitat?', null, '["Achatina","Tilapia","Dog fish","Tortoise."]', 2, 'Dog fish is mainly found in the marine habitat.', true, '2026-10-12 20:59:40.683', '2026-10-12 20:59:40.683', null, null, null, 'Which of the following organisms is mainly found in the marine habitat?', '["Achatina","Tilapia","Dog fish","Tortoise."]', 'Dog fish is mainly found in the marine habitat.', '{"bold":["Dog fish"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('98be5293-9408-4777-abae-91b77e7b501b', 'Biology', 'JAMB', null, 2002, null, 'The structure that is common in the embryos of mammals, amphibians, birds, fishes and reptiles and which is an evidence of their common ancestry is the', null, '["eye","chorion","allantois","gill-slits"]', 3, 'Gill-slits in embryos provide evidence of common ancestry.', true, '2026-10-12 20:59:30.959', '2026-10-12 20:59:30.959', null, null, null, 'The structure that is common in the embryos of mammals, amphibians, birds, fishes and reptiles and which is an evidence of their common ancestry is the', '["eye","chorion","allantois","gill-slits"]', 'Gill-slits in embryos provide evidence of common ancestry.', '{"bold":["Gill-slits"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('98d25c24-d529-43d4-9d64-77353ac83aac', 'Economics', 'JAMB', null, 2026, null, 'Economics is the study of human behaviour as it relates to the', null, '["efficient allocation of resources","production of goods","operation of companies","generation of income"]', 0, 'Economics is the study of human behaviour as it relates to the efficient allocation of scarce resources to satisfy unlimited wants. This definition captures the core of economics: how individuals and societies make choices about resource allocation. Production of goods, operation of companies, and generation of income are all aspects of economic activity but are not the central focus of the definition.', true, '2026-09-10 10:41:59.592', '2026-09-10 10:41:59.592', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('98d2d6f1-146b-4732-a518-38fda0c593d2', 'English Language', 'JAMB', null, 2007, null, 'The old man''s speech has become completely <u>__________</u>', null, '["uncomprehensible","uncomprehensive","incomprehensive","incomprehensible"]', 3, 'Correct spelling: incomprehensible.', true, '2026-10-24 07:21:35.261', '2026-10-24 07:21:35.261', null, null, null, 'The old man''s speech has become completely <u>__________</u>', '["uncomprehensible","uncomprehensive","incomprehensive","incomprehensible"]', 'Correct spelling: incomprehensible.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('98d5c9e8-91f0-4a20-9f77-140b50cba1d6', 'Government', 'JAMB', null, 2026, null, 'Which of the following is a basic feature of the rule of law?', null, '["equality before the law","secret trial of offenders","executive control of the judiciary","unlimited powers of the police"]', 0, 'Equality before the law is a basic feature of the rule of law.', true, '2026-09-12 11:24:21.936', '2026-09-12 11:24:21.936', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('98e1f395-bead-465b-a112-f26cb1e9123e', 'Literature in English', 'JAMB', null, 2026, null, 'The poem suggests that language is important because it', null, '["determines economic success","preserves culture and identity","helps people travel","improves political leadership"]', 1, 'Language preserves culture and identity.', true, '2026-09-12 11:12:33.335', '2026-09-12 11:12:33.335', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('98e3019c-bf75-4a2b-bb81-b40495871108', 'Physics', 'JAMB', null, 2026, null, 'Electrons were discovered by', null, '["Dalton","James Chadwick","J.J Thompson","Niels bohr","Rutherford"]', 2, 'Electrons were discovered by J.J. Thomson in 1897 through his experiments with cathode rays. James Chadwick discovered the neutron, Rutherford discovered the nucleus, and Dalton proposed atomic theory.', true, '2026-09-10 10:56:41.464', '2026-09-10 10:56:41.464', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('98e3569e-8474-43d5-80d9-a796bf660576', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Uche could not travel last December because of the <u>severity</u> of the harmattan.', null, '["cold","mildness","warmth","moderation"]', 1, 'Severity = harshness; opposite = mildness.', true, '2026-10-24 07:21:18.311', '2026-10-24 07:21:18.311', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Uche could not travel last December because of the <u>severity</u> of the harmattan.', '["cold","mildness","warmth","moderation"]', 'Severity = harshness; opposite = mildness.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('98ed90a1-3f94-4c92-ada5-be90835f780e', 'Literature in English', 'JAMB', null, 2026, null, 'The sea in the poem is best described as', null, '["a symbol of maternal care","an enemy of the people","a source of political power","a symbol of war"]', 0, 'The sea symbolizes maternal care.', true, '2026-09-12 11:12:14.584', '2026-09-12 11:12:14.584', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('98ef1eb4-9798-498e-ad73-51a27cf8ac98', 'Literature in English', 'JAMB', null, 2026, null, 'A tragic hero, according to the Aristotelian precept must be', null, '["a noble character with hubris","a lowly character who suddenly stumbles on some fortune","a king with deep affection for his subjects","a central character after whom the play is named"]', 0, 'A tragic hero is a noble character with hubris.', true, '2026-09-12 11:13:54.043', '2026-09-12 11:13:54.043', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('98ef74fc-d0bc-4bba-854c-d7c242509ffe', 'Literature in English', 'JAMB', null, 2026, null, 'The speaker''s tone throughout the poem can best be described as', null, '["submissive","bitter","defiant","indifferent"]', 2, 'The speaker''s tone is defiant.', true, '2026-09-12 11:10:43.053', '2026-09-12 11:10:43.053', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('98f55a21-39ca-43b7-a04c-abd5131a4ed3', 'Economics', 'JAMB', null, 2026, null, 'The mean is the best measure of central tendency because it', null, '["is not affected by extreme values in a data","is a midpoint value in an array of data","is a balancing point in an observation","can be calculated from incomplete data"]', 2, 'The mean is the best measure of central tendency because it is a balancing point in an observation. The mean is the sum of all values divided by the number of values. It represents the point where the data would balance if placed on a seesaw. Unlike the median (midpoint) or mode (most frequent), the mean uses all data values in its calculation, making it the most representative measure in many cases.', true, '2026-09-10 10:41:59.752', '2026-09-10 10:41:59.752', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('98f80b6d-d2ca-4557-a89b-2d593eb00a36', 'English Language', 'JAMB', null, 2007, null, 'Good schools don''t just teach their students, they <u>__________</u> them', null, '["inform","instruct","educate","coach"]', 2, 'Correct spelling: educate.', true, '2026-10-24 07:21:43.768', '2026-10-24 07:21:43.768', null, null, null, 'Good schools don''t just teach their students, they <u>__________</u> them', '["inform","instruct","educate","coach"]', 'Correct spelling: educate.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('990a71d1-5a60-403e-b05f-6bf99986fcee', 'Literature in English', 'JAMB', null, 2026, null, 'What figure of speech is used in ''lover''s bed''?', null, '["Personification","Metaphor","Alliteration","Simile"]', 1, 'Metaphor is used in ''lover''s bed''.', true, '2026-09-12 11:14:15.945', '2026-09-12 11:14:15.945', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('990eaf5c-db8f-4db5-b0b1-070e1b2065dc', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Nehemiah succeeded in building the walls of Jerusalem because...', null, '["He defeated Sanballat and Tobiah","Artaxerxes sent troops to protect him","God’s hand was with the Jews","God sent plagues upon their enemies"]', 2, 'Throughout Nehemiah (e.g., Nehemiah 2:8, 2:18, 6:16), the success of rebuilding the wall despite opposition is attributed directly to the good hand of God being upon them.', true, '2026-09-09 17:18:23.998', '2026-09-09 17:18:23.998', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('991f4c92-1753-4390-b131-4519393bc196', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Many Nigerian have <u>inured</u> themselves to hardship.', null, '["subjected","submitted","accustomed","endeared"]', 2, 'Inured = accustomed.', true, '2026-10-24 01:04:00.334', '2026-10-24 01:04:00.334', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Many Nigerian have <u>inured</u> themselves to hardship.', '["subjected","submitted","<u>accustomed</u>","endeared"]', '<b>Inured</b> = <b>accustomed</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9923983c-64f7-42c8-97bc-e6025a210b2b', 'Physics', 'JAMB', null, 1988, null, 'Two strings of the same length and under the same tension give notes of frequencies in the ratio 4 : 1. The masses of the strings are in the corresponding ratio of', null, '["2 : 1","1 : 2","1 : 4","1 : 16"]', 3, 'f is proportional to 1/√μ, so the mass ratio is the inverse square: (1/4)² = 1 : 16.', true, '2026-10-12 19:15:27.852', '2026-10-12 19:15:27.852', null, null, null, 'Two strings of the same length and under the same tension give notes of frequencies in the ratio 4 : 1. The masses of the strings are in the corresponding ratio of', '["2 : 1","1 : 2","1 : 4","1 : 16"]', 'f is proportional to 1/√μ, so the mass ratio is the inverse square: (1/4)<sup>2</sup> = 1 : 16.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('992df46b-a4ad-45cd-908f-b4fbb9e95c2e', 'Economics', 'JAMB', null, 2026, null, 'If the marginal utility of commodity is equal to its price, then;', null, '["Consumer is in equilibrium","Total utility is equal to price","More commodity can be consumed","Average utility is falling"]', 0, 'Consumer equilibrium occurs when marginal utility equals price.', true, '2026-09-12 11:02:11.108', '2026-09-12 11:02:11.108', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9934bade-32c6-4a4f-b67e-9222021f7293', 'Government', 'JAMB', null, 2026, null, 'A Security Council resolution requires the concurrence of', null, '["1 of the 5 permanent members","all of the 5 permanent members","9 of the 15 council members","3 of the 5 permanent members"]', 2, 'A Security Council resolution requires 9 of the 15 council members, including all permanent members.', true, '2026-09-12 11:23:56.276', '2026-09-12 11:23:56.276', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9943b4f0-e79d-4c52-a46c-63c3c20a5d46', 'Biology', 'JAMB', null, 2013, null, 'A tropical disease caused by Trypanosoma is', null, '["Yellow fever","Malaria","Sleeping sickness","River blindness"]', 2, 'Sleeping sickness is caused by Trypanosoma.', true, '2026-10-12 20:59:48.044', '2026-10-12 20:59:48.044', null, null, null, 'A tropical disease caused by Trypanosoma is', '["Yellow fever","Malaria","Sleeping sickness","River blindness"]', 'Sleeping sickness is caused by Trypanosoma.', '{"bold":["Sleeping sickness"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('99508c12-fc86-4d34-ada2-e90270b2fb05', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). After many years of struggle as a trader he <u>struck gold</u>', null, '["became quite rich","won a big contract","became a gold miner","became a goldsmith"]', 0, '''Struck gold'' = became rich.', true, '2026-10-24 01:02:08.024', '2026-10-24 01:02:08.024', null, null, null, '(Choose the most appropriate interpretation). After many years of struggle as a trader he <u>struck gold</u>', '["<u>became quite rich</u>","won a big contract","became a gold miner","became a goldsmith"]', '''<b>Struck gold</b>'' = <b>became rich</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('99606ce2-94af-4df5-9901-7b4299f95380', 'Physics', 'JAMB', null, 2026, null, 'In a series resonant circuit, the current flowing in the circuit is', null, '["minimum","Maximum","zero","unaffected"]', 1, 'In a series resonant circuit, the current is maximum. At resonance, impedance is minimum (Z = R), so according to Ohm''s law (I = V/Z), current is maximum. This is a key property of series resonance.', true, '2026-09-10 10:56:38.973', '2026-09-10 10:56:38.973', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('99695c61-2888-4ff2-805e-79c413c653e4', 'Biology', 'JAMB', null, 2013, null, 'One adaptation of Cactus opuntia to conserve water is the reduction of', null, '["Leaves to spine","Flower size","Internodes","Stem to leaves"]', 0, 'Cactus opuntia reduces leaves to spines to conserve water.', true, '2026-10-12 20:59:48.349', '2026-10-12 20:59:48.349', null, null, null, 'One adaptation of Cactus opuntia to conserve water is the reduction of', '["Leaves to spine","Flower size","Internodes","Stem to leaves"]', 'Cactus opuntia reduces leaves to spines to conserve water.', '{"bold":["reduces leaves to spines"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('99703941-b00e-4862-a0ca-d5a99b131813', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The chief''s brother was a complete <u>nonentity</u>.', null, '["upstart","vagabond","riff-raff","person of inexperience"]', 3, 'Nonentity = person of no importance/inexperience.', true, '2026-10-24 01:01:46.954', '2026-10-24 01:01:46.954', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The chief''s brother was a complete <u>nonentity</u>.', '["upstart","vagabond","riff-raff","<u>person of inexperience</u>"]', '<b>Nonentity</b> = <b>person of no importance</b>/inexperience.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('997b6131-643a-43a0-b864-d407b3877747', 'English Language', 'JAMB', null, 2007, null, 'All God''s prophets were given the great <u>__________</u> to preach salvation to people.', null, '["comission","commition","commision","commission"]', 3, 'Correct spelling: commission.', true, '2026-10-24 07:21:35.868', '2026-10-24 07:21:35.868', null, null, null, 'All God''s prophets were given the great <u>__________</u> to preach salvation to people.', '["comission","commition","commision","commission"]', 'Correct spelling: commission.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('997d53c1-90a8-4ed7-8cbc-85a40da1e58c', 'English Language', 'JAMB', null, 2024, null, 'Choose the option nearest in meaning to the word or phrase in italics: just give me the basic facts, with needless details', null, '["essential","relevant","critical","extraneous"]', 3, '"Needless" means unnecessary; nearest in meaning to "extraneous."', true, '2026-09-18 09:43:02.904', '2026-09-18 09:43:02.904', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9980e80f-873f-4872-acc3-18655cd6a15e', 'Financial Accounting', 'UTME', null, 2002, null, 'In a control account, discount received is found on the', null, '["debit side of the purchases ledger control account","debit side of the sales ledger control account","credit side of the purchases ledger control account","credit side of the sales ledger control account"]', 0, 'Discount received is a reduction on the amount owed the supplier. Therefore, it should be found on the debit side of purchases ledger control account where cash payment appeared.', true, '2026-10-12 21:59:58.547', '2026-10-12 21:59:58.547', null, null, null, 'In a control account, discount received is found on the', '["<b>debit side of the purchases ledger control account</b>","debit side of the sales ledger control account","credit side of the purchases ledger control account","credit side of the sales ledger control account"]', 'Discount received is a reduction on the amount owed the supplier. Therefore, it should be found on the <b>debit side of purchases ledger control account</b> where cash payment appeared.', '{"bold":["debit side of purchases ledger control account"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9989ae0e-545a-4882-a028-91ec3514333f', 'Economics', 'JAMB', null, 2026, null, 'A farmer that grows maize for sale to a popcorn company engages in what type of production?', null, '["Direct","Indirect","Tertiary","Secondary"]', 3, 'The farmer is engaged in primary production. Processing maize into popcorn is secondary production.', true, '2026-09-12 10:59:54.499', '2026-09-12 10:59:54.499', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('998bf305-7f5a-4c31-9b39-ba7bf69d7bb5', 'Government', 'JAMB', null, 2026, null, 'Parliamentary filibuster strategy means', null, '["A delay method by prolonging debates in Parliament","A special way of initiating money bills","an impeachment procedure","an approach adopted by the upper house to by-pass the president''s Veto"]', 0, 'Parliamentary filibuster strategy means a delay method by prolonging debates in Parliament. Filibustering involves making long speeches, proposing numerous amendments, or using other procedural tactics to delay or prevent a vote on a bill. It is a tactic used by the minority to block legislation they oppose. It is commonly used in the United States Senate but is also known in other parliamentary systems.', true, '2026-09-10 10:45:07.052', '2026-09-10 10:45:07.052', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('999acb5d-b1d6-456a-a319-09ec026d3ca0', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. There are many <u>venal</u> judges in our law courts today.', null, '["qualified","professional","corrupt","honest"]', 2, 'Venal = corrupt.', true, '2026-10-24 01:04:00.388', '2026-10-24 01:04:00.388', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. There are many <u>venal</u> judges in our law courts today.', '["qualified","professional","<u>corrupt</u>","honest"]', '<b>Venal</b> = <b>corrupt</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('99a9b55d-8f61-4f02-8206-eb04aa99d55c', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Tade became <u>timorous</u> when she was asked to give the valedictory speech.', null, '["excited","aggressive","nervous","happy"]', 2, 'Timorous = nervous/fearful.', true, '2026-10-24 01:01:50.503', '2026-10-24 01:01:50.503', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Tade became <u>timorous</u> when she was asked to give the valedictory speech.', '["excited","aggressive","<u>nervous</u>","happy"]', '<b>Timorous</b> = <b>nervous</b>/fearful.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('99acb9ea-a749-4d96-9e69-f059a1713186', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). The idle steward could not <u>see ___________ on the wall</u> and he lost his job.', null, '["what will be written","what is written","the handwriting","the writing"]', 3, '''See the writing on the wall'' = foresee coming disaster.', true, '2026-10-24 01:02:09.872', '2026-10-24 01:02:09.872', null, null, null, '(Choose the most appropriate interpretation). The idle steward could not <u>see ___________ on the wall</u> and he lost his job.', '["what will be written","what is written","the handwriting","<u>the writing</u>"]', '''<b>See the writing on the wall</b>'' = <b>foresee coming disaster</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('99af65c9-ea9c-4ace-8264-d48dc9eba56c', 'Physics', 'JAMB', null, 2004, null, 'Electrical appliances in homes are normally earthed so that', null, '["Both the a.c. and d.c. sources can be used","A person touching the appliances is safe from electric shock","The appliances are maintained at a higher p.d. than the earth","The appliances are maintained at a lower p.d. than the earth"]', 1, 'Earthing keeps the metal casing at earth potential, so a fault current flows to earth (and blows the fuse) instead of through a person.', true, '2026-10-12 19:16:00.267', '2026-10-12 19:16:00.267', null, null, null, 'Electrical appliances in homes are normally earthed so that', '["Both the a.c. and d.c. sources can be used","A person touching the appliances is safe from electric shock","The appliances are maintained at a higher p.d. than the earth","The appliances are maintained at a lower p.d. than the earth"]', 'Earthing keeps the metal casing at earth potential, so a fault current flows to earth (and blows the fuse) instead of through a person.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('99b4e358-eb8c-4a61-b95b-c7d80a234ed7', 'English Language', 'JAMB', null, 2007, null, 'Two-thirds of the building <u>_______</u> destroyed by the fire.', null, '["was","were","have been","are"]', 0, 'Singular ''building'' â†’ was.', true, '2026-10-24 01:04:30.15', '2026-10-24 01:04:30.15', null, null, null, 'Two-thirds of the building <u>_______</u> destroyed by the fire.', '["<u>was</u>","were","have been","are"]', 'Singular ''<b>building</b>'' â†’ <b>was</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('99bb21ff-f7c1-422b-b963-2001d5433e42', 'English Language', 'JAMB', null, 2007, null, 'Ado tried to <u>__________</u> all memory of his dead father.', null, '["recall","obstruct","obliterate","eulogize"]', 2, 'Correct spelling: obliterate.', true, '2026-10-24 07:21:38.186', '2026-10-24 07:21:38.186', null, null, null, 'Ado tried to <u>__________</u> all memory of his dead father.', '["recall","obstruct","obliterate","eulogize"]', 'Correct spelling: obliterate.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('99c48167-983f-47c1-9973-2dd8ef90e622', 'Physics', 'JAMB', null, 1997, null, 'What is the total electrical energy consumed by using an electric cooker rated 1000 W for 5 hrs?', null, '["5.3 x 10³ J","6.5 x 10³ J","1.8 x 10⁷ J","2.3 x 10⁷ J"]', 2, 'E = Pt = 1000 x 5 x 3600 = 1.8 x 10⁷ J.', true, '2026-10-12 19:15:44.334', '2026-10-12 19:15:44.334', null, null, null, 'What is the total electrical energy consumed by using an electric cooker rated 1000 W for 5 hrs?', '["5.3 x 10<sup>3</sup> J","6.5 x 10<sup>3</sup> J","1.8 x 10<sup>7</sup> J","2.3 x 10<sup>7</sup> J"]', 'E = Pt = 1000 x 5 x 3600 = 1.8 x 10<sup>7</sup> J.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('99cacb94-1b0e-4f0a-85bb-79e72bce593b', 'Financial Accounting', 'UTME', null, 2001, null, 'Calculate the shareholders'' fund', 'https://res.cloudinary.com/kwi1uv0g/image/upload/v1791842277/questions/fnjheuiueu2ik1k1anxv.jpg', '["N60,000","N75,000","N85,000","N185,000"]', 2, 'Shareholders'' fund = Ordinary shares 50,000 + Preference shares 10,000 + Reserves 25,000 = 85,000.', true, '2026-10-12 22:00:07.541', '2026-10-12 22:00:07.541', null, null, null, 'Calculate the shareholders'' fund', '["N60,000","N75,000","<b>N85,000</b>","N185,000"]', 'Shareholders'' fund = Ordinary shares 50,000 + Preference shares 10,000 + Reserves 25,000 = <b>85,000</b>.', '{"bold":["85,000"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('99d58d67-763a-4033-b3e3-0b69e0500ac6', 'Biology', 'JAMB', null, 2010, null, 'The flippers of a whale and the fins of a fish are examples of', null, '["divergent evolution","coevolution","continuous variation","convergent evolution"]', 3, 'The flippers of a whale and fins of a fish are examples of convergent evolution.', true, '2026-10-12 20:59:41.495', '2026-10-12 20:59:41.495', null, null, null, 'The flippers of a whale and the fins of a fish are examples of', '["divergent evolution","coevolution","continuous variation","convergent evolution"]', 'The flippers of a whale and fins of a fish are examples of convergent evolution.', '{"bold":["convergent evolution"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('99f281b6-6c0a-4b65-8b54-a19c1ae20314', 'Physics', 'JAMB', null, 2026, null, 'A substance has a half life of 3 mins. After 6 mins, the count rate was observed to be 400. What was its count rate at zero time?', null, '["200","1200","1600","2400"]', 2, 'After 6 minutes (2 half-lives), the count rate is 400. After 1 half-life (3 min), it would be 800. At zero time, it would be 1600.', true, '2026-09-10 10:56:40.381', '2026-09-10 10:56:40.381', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('99f3fcb1-315d-4ce8-b7c9-6b00f41a9185', 'English Language', 'JAMB', null, 2007, null, 'Aggrieved persons are free to seek <u>__________</u> in the court of law', null, '["reparation","redress","consolation","acquittal"]', 1, 'Correct spelling: redress.', true, '2026-10-24 07:21:45.525', '2026-10-24 07:21:45.525', null, null, null, 'Aggrieved persons are free to seek <u>__________</u> in the court of law', '["reparation","redress","consolation","acquittal"]', 'Correct spelling: redress.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('99f72b4a-0e79-4da3-90af-34259ac4a559', 'Physics', 'JAMB', null, 1983, null, 'A man of mass 50 kg ascends a flight of stairs 5 m high in 5 seconds. If acceleration due to gravity is 10 m s⁻², the power expended is', null, '["100 W","300 W","250 W","400 W","500 W"]', 4, 'Power = work done/time = mgh/t = (50 x 10 x 5)/5 = 500 W.', true, '2026-10-12 19:15:16.82', '2026-10-12 19:15:16.82', null, null, null, 'A man of mass 50 kg ascends a flight of stairs 5 m high in 5 seconds. If acceleration due to gravity is 10 m s<sup>-2</sup>, the power expended is', '["100 W","300 W","250 W","400 W","500 W"]', 'Power = work done/time = mgh/t = (50 x 10 x 5)/5 = 500 W.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9a0c93c8-2097-4c86-9429-d11f68d66336', 'Physics', 'JAMB', null, 1991, null, 'A body of mass 100 g moving with a velocity of 10.0 m s⁻¹ collides with a wall. If after the collision, it moves with a velocity of 2.0 m s⁻¹ in the opposite direction, calculate the change in momentum.', null, '["0.8 N s","1.2 N s","12.0 N s","80.0 N s"]', 1, 'Taking the initial direction as positive: Δp = m(v - u) = 0.1 x (-2 - 10) = -1.2 N s. The magnitude is 1.2 N s.', true, '2026-10-12 19:15:32.651', '2026-10-12 19:15:32.651', null, null, null, 'A body of mass 100 g moving with a velocity of 10.0 m s<sup>-1</sup> collides with a wall. If after the collision, it moves with a velocity of 2.0 m s<sup>-1</sup> in the opposite direction, calculate the change in momentum.', '["0.8 N s","1.2 N s","12.0 N s","80.0 N s"]', 'Taking the initial direction as positive: Δp = m(v - u) = 0.1 x (-2 - 10) = -1.2 N s. The magnitude is 1.2 N s.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9a179ed6-e644-4ae4-923e-d2ca5c7b6cd8', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Peter encourages Christians to endure suffering because', null, '["it brings wealth","it leads to glory","it avoids punishment","it ensures power"]', 1, 'Peter says suffering leads to glory.', true, '2026-09-12 10:41:00.184', '2026-09-12 10:41:00.184', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9a187165-76f7-47b7-b187-c6090339ac9e', 'Government', 'JAMB', null, 2026, null, 'One of the benefits which the West African states derive from the United Nation is', null, '["equal opportunities of appointments to its highest office","permanence membership of the Security Council","greater access to the organs of the United Nations","total eradication of poverty from the African Continent"]', 2, 'West African states benefit from greater access to UN organs.', true, '2026-09-12 11:24:17.471', '2026-09-12 11:24:17.471', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9a1f6afe-ffc2-4ee2-8c5b-6d7ec59b6274', 'Economics', 'JAMB', null, 2026, null, 'The output per unit of the variable factor employed is called', null, '["Marginal product","Average product","Total product","Average cost","Productivity of labour"]', 1, 'The output per unit of the variable factor employed is called average product (AP). It is calculated as total product divided by the number of units of the variable factor. Marginal product is the additional output from employing one more unit of the variable factor. Total product is the total output produced.', true, '2026-09-10 10:41:20.991', '2026-09-10 10:41:20.991', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9a254ce7-f0b7-4dd1-af3a-3663448c2b15', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). The new inspector decided that the culprits should <u>be brought to book</u>.', null, '["should have their names recorded in a book","should be brought before him to show whether they could read or not","should be booked","should be jailed","should be made to answer for their conduct"]', 4, '''Brought to book'' = made to answer for conduct.', true, '2026-10-24 01:04:15.184', '2026-10-24 01:04:15.184', null, null, null, '(Choose the most appropriate interpretation). The new inspector decided that the culprits should <u>be brought to book</u>.', '["should have their names recorded in a book","should be brought before him to show whether they could read or not","should be booked","should be jailed","<u>should be made to answer for their conduct</u>"]', '''<b>Brought to book</b>'' = <b>made to answer for conduct</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9a2a6ff5-4974-4527-a339-21b479104b61', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Language teachers believe that grammar exercises <u>stretch</u> the mind.', null, '["expand","ruin","enrich","restrict"]', 3, 'Stretch = expand; opposite = restrict.', true, '2026-10-24 07:21:14.577', '2026-10-24 07:21:14.577', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Language teachers believe that grammar exercises <u>stretch</u> the mind.', '["expand","ruin","enrich","restrict"]', 'Stretch = expand; opposite = restrict.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9a2ace28-e6d5-420a-a935-470a8f705239', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Sailors are unusually <u>dauntless</u> in their exploits.', null, '["excited","ruthless","frightened","selfless"]', 2, 'Dauntless = fearless; opposite = frightened.', true, '2026-10-24 07:21:24.777', '2026-10-24 07:21:24.777', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Sailors are unusually <u>dauntless</u> in their exploits.', '["excited","ruthless","frightened","selfless"]', 'Dauntless = fearless; opposite = frightened.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9a438fc7-057b-4e02-9054-e1af42abecce', 'Biology', 'JAMB', null, 2003, null, 'An insect whose economic importance is both harmful and beneficial is the', null, '["tsetsefly","blackfly","mosquito","butterfly"]', 3, 'Butterflies are both harmful (larvae eat crops) and beneficial (pollination).', true, '2026-10-12 20:59:32.389', '2026-10-12 20:59:32.389', null, null, null, 'An insect whose economic importance is both harmful and beneficial is the', '["tsetsefly","blackfly","mosquito","butterfly"]', 'Butterflies are both harmful (larvae eat crops) and beneficial (pollination).', '{"bold":["Butterflies"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9a494b08-97f4-4bee-8bdd-5b6196991159', 'Chemistry', 'JAMB', null, 2026, null, 'In the reaction: A + 2B ⇌ C + D If Kc is large, it means that at equilibrium', null, '["reactants predominate","products predominate","reaction is very slow","reaction never reaches equilibrium"]', 1, 'A large equilibrium constant (Kc >> 1) indicates that product concentration is significantly greater than reactant concentration at equilibrium.', true, '2026-09-09 17:12:49.367', '2026-09-09 17:12:49.367', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9a4b7ea0-40fd-4939-b5bc-a59768bb2a5d', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Florence flogged the girl <u>reluctantly</u>.', null, '["eagerly","calmly","furiously","laboriously"]', 0, 'Reluctantly = unwillingly; opposite = eagerly.', true, '2026-10-24 07:21:12.497', '2026-10-24 07:21:12.497', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Florence flogged the girl <u>reluctantly</u>.', '["eagerly","calmly","furiously","laboriously"]', 'Reluctantly = unwillingly; opposite = eagerly.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9a521a23-fcd9-498d-aea7-31cbde21926e', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. All the efforts made to settle the quarrel were <u>futile</u>.', null, '["successful","wicked","reasonable","remarkable","fruitless"]', 4, 'Futile = fruitless/useless.', true, '2026-10-24 01:01:40.415', '2026-10-24 01:01:40.415', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. All the efforts made to settle the quarrel were <u>futile</u>.', '["successful","wicked","reasonable","remarkable","<u>fruitless</u>"]', '<b>Futile</b> = <b>fruitless/useless</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9a6c7de6-fedb-4b77-a571-41e7502f1ce2', 'Biology', 'JAMB', null, 2026, null, 'There will be agglutination when the', null, '["Group A serum mixes with Group A erythrocytes","Group A serum mixes with Group B erythrocytes","Group AB serum mixes with Group O erythrocytes","Group B serum mixes with Group B erythrocytes"]', 1, 'Agglutination will occur when Group A serum mixes with Group B erythrocytes. Group A serum contains anti-B antibodies, which will bind to B antigens on Group B erythrocytes, causing clumping (agglutination). When serum and erythrocytes have compatible antigens/antibodies, no agglutination occurs. Group A serum with Group A erythrocytes is compatible. Group AB serum has no anti-A or anti-B antibodies, so it would not agglutinate with Group O erythrocytes.', true, '2026-09-09 03:19:17.466', '2026-09-09 03:19:17.466', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9a6e57b6-874b-42e2-a566-8188de69041d', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Tunde''s reaction <u>underscores</u> the point I was making.', null, '["contradicts","justifies","summarizes","emphasizes"]', 0, 'Underscores = emphasizes; opposite = contradicts.', true, '2026-10-24 07:21:23.313', '2026-10-24 07:21:23.313', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Tunde''s reaction <u>underscores</u> the point I was making.', '["contradicts","justifies","summarizes","emphasizes"]', 'Underscores = emphasizes; opposite = contradicts.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9a8277e8-8ee5-441d-835a-7db1034bc0e7', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The musician''s popularity is beginning to <u>decline</u>.', null, '["change","wane","slide","disappear"]', 1, 'Decline = wane.', true, '2026-10-24 01:01:41.663', '2026-10-24 01:01:41.663', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The musician''s popularity is beginning to <u>decline</u>.', '["change","<u>wane</u>","slide","disappear"]', '<b>Decline</b> = <b>wane</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9a962993-d588-4c43-b7be-71319de718bd', 'Biology', 'JAMB', null, 2001, null, 'Which of the following groups is the most advanced?', null, '["Thallophytes","Pteridophytes","Gymnosperms","Bryophytes"]', 2, 'Gymnosperms are seed-producing vascular plants, making them more evolutionarily advanced.', true, '2026-10-12 20:05:08.555', '2026-10-12 20:05:08.555', null, null, null, 'Which of the following groups is the most advanced?', '["Thallophytes","Pteridophytes","Gymnosperms","Bryophytes"]', 'Gymnosperms are seed-producing vascular plants, making them more evolutionarily advanced.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9a974a69-6749-4b79-8624-3eaf5168010c', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Our local paper is noted for its <u>incisive</u> editorials on local politics.', null, '["sarcastic","penetrating","decisive","destructive"]', 1, 'Incisive = penetrating.', true, '2026-10-24 01:01:48.124', '2026-10-24 01:01:48.124', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Our local paper is noted for its <u>incisive</u> editorials on local politics.', '["sarcastic","<u>penetrating</u>","decisive","destructive"]', '<b>Incisive</b> = <b>penetrating</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9aa0e738-48cc-4fba-9b2d-e5c4159557c0', 'Economics', 'JAMB', null, 2026, null, 'The type of population census which involves the counting of people who have been permanent residents of a specific area is called?', null, '["De facto","De jure","Factos","Jury"]', 1, 'De jure census counts people who are permanent residents of a specific area.', true, '2026-09-12 11:00:56.928', '2026-09-12 11:00:56.928', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9acc4d0d-b452-44f0-8cc5-1b9138a4aaaa', 'Chemistry', 'JAMB', null, 2026, null, 'Which non-metal is most responsible for the formation of ozone in the upper atmosphere?', null, '["Nitrogen","Oxygen","Carbon","Chlorine"]', 1, 'Oxygen is responsible for ozone formation. In the upper atmosphere, UV radiation splits O₂ molecules into oxygen atoms, which then combine with O₂ to form ozone (O₃): O₂ + O → O₃. Chlorine is involved in ozone depletion, not formation.', true, '2026-09-12 09:38:11.103', '2026-09-12 09:38:11.103', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9ad9aafd-151e-49ae-8f72-ff7b86f6c946', 'Physics', 'JAMB', null, 2026, null, 'The general formula that best describes the conservation of momentum is', null, '["[(m1+m2)u = (m1+m2)v]","[m1u1 - m2u2 = m1v1 + m2v2]","[m1u1 + m2u2 = (m1+m2)v]","[m1u1 = m2v2]"]', 0, 'The general formula for conservation of momentum when two bodies coalesce (stick together) is (m1+m2)u = (m1+m2)v. This applies to perfectly inelastic collisions where the bodies move together after collision.', true, '2026-09-10 10:56:45.252', '2026-09-10 10:56:45.252', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9adbca35-07fb-4d91-a50b-b841e86082ba', 'English Language', 'JAMB', null, 2024, null, 'The fifth chapter of the novel is titled', null, '["Dusk...","Migration Tales","Snake on the roof","A case of Visa Denied"]', 2, 'The fifth chapter is titled "Snake on the Roof."', true, '2026-09-18 09:23:08.245', '2026-09-18 09:23:08.245', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9ae6d9a0-d637-4b77-8e94-5b9fb129b2b7', 'Government', 'JAMB', null, 2026, null, 'The organ of the United Nations Organisation responsible for the former colonies of defeated World War II power is the', null, '["General Assembly","Security Council","Economic and Social Council","Trusteeship Council"]', 3, 'The Trusteeship Council was responsible for former colonies.', true, '2026-09-12 11:24:47.151', '2026-09-12 11:24:47.151', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9ae798f8-a91c-4f9d-aeae-c714d0aa48c6', 'Yoruba', 'JAMB', null, 2007, null, 'Àgbè ni mo ri jè gbólóhùn', null, '["alágbèékà","oníbõ","alátçnumó","Abòdé."]', 2, 'Àgbè ni mo ri jè gbólóhùn alátçnumó.', true, '2026-10-13 13:23:31.411', '2026-10-13 13:23:31.411', null, null, null, 'Àgbè ni mo ri jè gbólóhùn', '["alágbèékà","oníbõ","alátçnumó","Abòdé."]', 'Àgbè ni mo ri jè gbólóhùn alátçnumó.', '{"bold":["alátçnumó"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9aeb0c53-554f-47ac-8073-479b11f234fb', 'General Mathematics', 'JAMB', null, 2026, null, 'A cylinder has radius 3 cm and height 10 cm. Find its volume. (π = 22/7)', null, '["270 cm³","282.86 cm³","300 cm³","314 cm³"]', 1, 'V = πr²h = (22/7)(9)(10) = 282.86 cm³.', true, '2026-09-12 11:44:12.713', '2026-09-12 11:44:12.713', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9b0e9537-62e1-4d97-aae4-48fe44d7d7d3', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Reuben said ''shed no blood'' because', null, '["He was afraid at the sight of blood","Blood is life","Jews do not eat blood","Blood is used in sacrifice","Blood is evil"]', 1, 'Reuben said ''shed no blood'' because blood is life. He intended to rescue Joseph from their hands and restore him to his father. Reuben said, ''Shed no blood; cast him into this pit here in the wilderness, but lay no hand upon him.''', true, '2026-09-12 09:45:58.923', '2026-09-12 09:45:58.923', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9b1cd3d5-90bc-485a-9f15-88f05c06491b', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. I visited Amina <u>umpteen times</u>, but she never came to me.', null, '["seldom","often","occasionally","twice"]', 1, 'Umpteen = often.', true, '2026-10-24 01:01:57.124', '2026-10-24 01:01:57.124', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. I visited Amina <u>umpteen times</u>, but she never came to me.', '["seldom","<u>often</u>","occasionally","twice"]', '<b>Umpteen</b> = <b>often</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9b27913b-4bfb-40a5-9b5e-61beef37b8e6', 'English Language', 'JAMB', null, 2007, null, 'He is one of those who <u>---</u> in my school.', null, '["teaches","is teaching","are teaching","teach"]', 3, '''Who'' â†’ those (plural) â†’ teach.', true, '2026-10-24 01:02:14.137', '2026-10-24 01:02:14.137', null, null, null, 'He is one of those who <u>---</u> in my school.', '["teaches","is teaching","are teaching","<u>teach</u>"]', '''<b>Who</b>'' â†’ <b>those</b> (plural) â†’ <b>teach</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9b375887-2200-417e-84d8-eed807d3f8a0', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). Ado is <u>one of the backwoodsmen</u>', null, '["He is one of those that live in a distant and underdeveloped area","He is one of the active members of the community","He is one of the honest men that live in the community","He is one of those that live in the most developed part of the city"]', 0, '''Backwoodsmen'' = people from distant underdeveloped area.', true, '2026-10-24 01:02:10.792', '2026-10-24 01:02:10.792', null, null, null, '(Choose the most appropriate interpretation). Ado is <u>one of the backwoodsmen</u>', '["<u>He is one of those that live in a distant and underdeveloped area</u>","He is one of the active members of the community","He is one of the honest men that live in the community","He is one of those that live in the most developed part of the city"]', '''<b>Backwoodsmen</b>'' = <b>people from distant underdeveloped area</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9b574ff2-c379-444e-b2ae-5dd5cac2dc3d', 'Biology', 'JAMB', null, 2002, null, 'The first four children of a couple were all girls. The probability that the fifth will also be a girl is', null, '["1/5","1/4","1/3","1/2"]', 3, 'The probability of a girl is always 1/2.', true, '2026-10-12 20:59:31.832', '2026-10-12 20:59:31.832', null, null, null, 'The first four children of a couple were all girls. The probability that the fifth will also be a girl is', '["1/5","1/4","1/3","1/2"]', 'The probability of a girl is always 1/2.', '{"bold":["1/2"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9b59b0bf-b4c2-41a4-bc59-f50e6035fcf3', 'Economics', 'JAMB', null, 2026, null, 'The most popular sizes of dresses and shoes are determined by the', null, '["range","mean","mode","median"]', 2, 'The most popular sizes of dresses and shoes are determined by the mode. The mode is the most frequently occurring value in a data set. For dress and shoe sizes, the mode represents the size that is purchased most often, indicating the most popular size. The mean would give an average size that may not correspond to actual popular sizes. The median would give the middle size. The range shows the spread of sizes.', true, '2026-09-10 10:41:59.806', '2026-09-10 10:41:59.806', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9b63f812-2ef5-4f55-a0f8-b447c51533de', 'Economics', 'JAMB', null, 2026, null, 'A monopolist will practice price discrimination in two markets if', null, '["there''s a patent of the commodity","there''s free flow of information in the two markets","the markets have different elasticities of demand","the cost of separating the market is low"]', 2, 'A monopolist will practice price discrimination in two markets if the markets have different elasticities of demand. Price discrimination involves charging different prices to different consumers for the same product. For this to be profitable, the monopolist must be able to segment the market into groups with different price elasticities of demand. The group with inelastic demand is charged a higher price, while the group with elastic demand is charged a lower price.', true, '2026-09-10 10:42:55.721', '2026-09-10 10:42:55.721', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9b7c830d-3d6f-41e3-8047-86b287628167', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Peter called on Christians not to retaliate because...', null, '["Vengeance belongs to God","God fights for the innocent","God made light Jesus persecution","Jesus patiently bore his persecutions"]', 3, 'In 1 Peter 2:21-23, Peter urges believers to endure suffering patiently without retaliating because Christ set the example by suffering for us without reviling or threatening in return.', true, '2026-09-09 17:18:24.436', '2026-09-09 17:18:24.436', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9b7e4d51-6638-4f22-a854-0a1aeac2ef11', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. This card <u>entitles</u> you to attend the film show.', null, '["disqualifies","discourages","disenchants","proclaims","satisfies"]', 0, 'Entitles = qualifies; opposite = disqualifies.', true, '2026-10-24 07:21:11.166', '2026-10-24 07:21:11.166', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. This card <u>entitles</u> you to attend the film show.', '["disqualifies","discourages","disenchants","proclaims","satisfies"]', 'Entitles = qualifies; opposite = disqualifies.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9b81e32f-b070-40f8-8a3a-1989beba231c', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Justice is difficult to enforce because people are unwilling to accept any loss of <u>sovereignty</u>.', null, '["autonomy","leadership","position","kingdom"]', 0, 'Sovereignty = autonomy.', true, '2026-10-24 01:04:07.349', '2026-10-24 01:04:07.349', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Justice is difficult to enforce because people are unwilling to accept any loss of <u>sovereignty</u>.', '["<u>autonomy</u>","leadership","position","kingdom"]', '<b>Sovereignty</b> = <b>autonomy</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9b8971a1-7b9e-44eb-9007-96d5ee624b32', 'Economics', 'JAMB', null, 2026, null, 'Which of the following combination is a veritable set of development indicators?', null, '["high fertility, literacy and school enrollment rates","growth of imports and government expenditures","low infant mortality, literacy rates and high per Capita income","high population and national income"]', 2, 'Low infant mortality, high literacy, and high per capita income are veritable development indicators.', true, '2026-09-12 11:00:45.414', '2026-09-12 11:00:45.414', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9b9a653a-c214-43fd-8fd3-31b2a1010607', 'Literature in English', 'JAMB', null, 2026, null, 'The phrase ''our bloody century'' primarily refers to the', null, '["18th century and the slave trade","19th century and the age of exploration","20th century, marked by wars and violence","the present century due to ongoing conflicts"]', 2, 'It refers to the 20th century, marked by wars and violence.', true, '2026-09-12 11:13:47.525', '2026-09-12 11:13:47.525', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9ba87329-eb4d-4def-afa6-f7982d671d72', 'Economics', 'JAMB', null, 2026, null, 'The use of tax and expenditure policy to regulate the economy is known as', null, '["Monetary policy","Deregulation","Fiscal policy","Physical measures"]', 2, 'Fiscal policy uses tax and expenditure to regulate the economy.', true, '2026-09-12 11:01:37.395', '2026-09-12 11:01:37.395', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9bad76ed-5035-4fa4-9381-3ae46fafd156', 'Chemistry', 'JAMB', null, 2026, null, 'Consider the reaction: 2Mg(s) + O₂(g) → 2MgO(s). If 4.8 g of magnesium reacts with excess oxygen, calculate the mass of magnesium oxide formed. [Mg = 24, O = 16]', null, '["6.4 g","8.0 g","10.4 g","12.0 g"]', 1, 'Moles Mg = 4.8 / 24 = 0.2 mol. Stoichiometric ratio 2:2 gives 0.2 mol MgO. Mass MgO = 0.2 * (24 + 16) = 0.2 * 40 = 8.0 g.', true, '2026-09-09 17:12:47.852', '2026-09-09 17:12:47.852', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9bb2f5f8-2ad8-46cd-95d4-50552f987b09', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The boy was told that he would need <u>several</u> more pints of blood if he was to survive.', null, '["many","much","some","plenty"]', 0, 'Several = many.', true, '2026-10-24 01:01:49.867', '2026-10-24 01:01:49.867', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The boy was told that he would need <u>several</u> more pints of blood if he was to survive.', '["<u>many</u>","much","some","plenty"]', '<b>Several</b> = <b>many</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9bcaf5cd-e048-41b8-85f4-c85253b7ea91', 'Yoruba', 'JAMB', null, 2002, null, 'Dá iná di Dáná nípasè', null, '["ìyòpò","àrànmò","àýkóò fàwèlì","ìpajç fàwèlì."]', 3, 'Dá iná di Dáná nípasè ìpajç fàwèlì.', true, '2026-10-13 13:22:38.359', '2026-10-13 13:22:38.359', null, null, null, 'Dá iná di Dáná nípasè', '["ìyòpò","àrànmò","àýkóò fàwèlì","ìpajç fàwèlì."]', 'Dá iná di Dáná nípasè ìpajç fàwèlì.', '{"bold":["ìpajç fàwèlì"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9bd9c5af-e638-4de4-bf92-28966bb7d9bd', 'Physics', 'JAMB', null, 2026, null, 'Which of the following can be used to measure human body temperature?', null, '["constant volume gas thermometer","liquid in glass thermometer","clinical thermometer","thermocouple thermometer"]', 2, 'A clinical thermometer is used to measure human body temperature. It is designed with a narrow range (35-42°C) and a constriction to prevent mercury from returning after use. It is specifically designed for medical use.', true, '2026-09-10 10:56:47.521', '2026-09-10 10:56:47.521', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9be06c50-2962-477e-bb66-5ecd7f76bcb4', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Statesmen are <u>revered</u> for their objectivity.', null, '["referred","respected","remembered","rejected"]', 1, 'Revered = respected.', true, '2026-10-24 01:03:58.887', '2026-10-24 01:03:58.887', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Statesmen are <u>revered</u> for their objectivity.', '["referred","<u>respected</u>","remembered","rejected"]', '<b>Revered</b> = <b>respected</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9be1af61-1193-42cd-aed3-35f7fa00fcc3', 'Economics', 'JAMB', null, 2026, null, 'If the labour force in a given community is 2,000,000, in the wage employment 200,000 and the unemployed are 80,000, what is the unemployment rate in the community?', null, '["4.0%","0.4%","10.0%","40.0%"]', 0, 'Unemployment rate = (Unemployed / Labour Force) × 100 = (80,000 / 2,000,000) × 100 = 4.0%. The labour force is the total number of people available for work, which includes both employed and unemployed individuals.', true, '2026-09-10 10:41:58.777', '2026-09-10 10:41:58.777', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9be320e8-0c2f-43f8-ba30-7e61c107ab80', 'Physics', 'JAMB', null, 1998, null, 'The velocity of a sound wave at 27 °C is 360 m s⁻¹. Its velocity at 127 °C is', null, '["120√3 m s⁻¹","240 m s⁻¹","240√3 m s⁻¹","720√3 m s⁻¹"]', 2, 'v is proportional to √T. v₂ = 360 x √(400/300) = 360 x 2/√3 = 240√3 m s⁻¹.', true, '2026-10-12 19:15:45.784', '2026-10-12 19:15:45.784', null, null, null, 'The velocity of a sound wave at 27 °C is 360 m s<sup>-1</sup>. Its velocity at 127 °C is', '["120√3 m s<sup>-1</sup>","240 m s<sup>-1</sup>","240√3 m s<sup>-1</sup>","720√3 m s<sup>-1</sup>"]', 'v is proportional to √T. v<sub>2</sub> = 360 x √(400/300) = 360 x 2/√3 = 240√3 m s<sup>-1</sup>.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9be53cf7-292a-4a00-93e6-caf209b494f2', 'Government', 'JAMB', null, 2026, null, 'Public opinion is important because it', null, '["Tells government what action it must take","let government know what the people want","Allows the police to determine trouble makers","Protects minorities"]', 1, 'Public opinion lets government know what the people want.', true, '2026-09-12 11:24:24.006', '2026-09-12 11:24:24.006', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9beb24e5-e08a-4ac7-9b31-a8f54e502027', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. One wonders if the situation will <u>improve</u>.', null, '["brighten","diminish","disintegrate","worsen"]', 3, 'Improve = get better; opposite = worsen.', true, '2026-10-24 07:21:14.527', '2026-10-24 07:21:14.527', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. One wonders if the situation will <u>improve</u>.', '["brighten","diminish","disintegrate","worsen"]', 'Improve = get better; opposite = worsen.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9becaa46-66be-4546-aac9-d2f0b6dfe215', 'Chemistry', 'JAMB', null, 2026, null, 'Which of the following reactions is most likely to occur when ethanol is heated with concentrated sulfuric acid at about 170°C?', null, '["Substitution reaction forming ethyl hydrogen sulfate","Dehydration to form ethene","Oxidation to form ethanoic acid","Neutralization to form sodium ethanoate"]', 1, 'At 170°C, concentrated H2SO4 acts as a powerful dehydrating agent, removing water from ethanol to yield ethene gas.', true, '2026-09-09 17:12:48.613', '2026-09-09 17:12:48.613', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9becf0f3-3ff0-4524-b4f2-28944afbbed7', 'Biology', 'JAMB', null, 2026, null, 'Hassan and Hussain. This is probably because', null, '["Hassan inherits gene for tallness and fatness from the father","they have dissimilar genotypes","Hussain is endowed with genes for shortness and thinness","they are raised in different environments"]', 1, 'This question is incomplete, but the most logical answer is that they have dissimilar genotypes. Differences between siblings (like Hassan and Hussain) are due to genetic variation. Each child inherits a unique combination of genes from their parents. Dissimilar genotypes result in differences in traits like height, weight, hair color, etc. Genes are inherited from both parents, not just the father.', true, '2026-09-09 03:19:25.868', '2026-09-09 03:19:25.868', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9bed85cc-116d-4fb7-94e2-c32c80422c6f', 'English Language', 'JAMB', null, 2007, null, '<u>__________</u> any problems, I shall travel to London tomorrow on a business trip.', null, '["In spite of","Given","In case of","Barring"]', 3, 'Correct spelling: Barring.', true, '2026-10-24 07:21:38.747', '2026-10-24 07:21:38.747', null, null, null, '<u>__________</u> any problems, I shall travel to London tomorrow on a business trip.', '["In spite of","Given","In case of","Barring"]', 'Correct spelling: Barring.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9beebaab-ee33-409f-a46c-9902571ec370', 'English Language', 'JAMB', null, 2007, null, 'Sixty percent of the unskilled workers <u>-----</u> yearly by the company.', null, '["are retain","is retained","were retained","are retained"]', 3, 'Plural ''workers'' habitual â†’ are retained.', true, '2026-10-24 01:02:13.859', '2026-10-24 01:02:13.859', null, null, null, 'Sixty percent of the unskilled workers <u>-----</u> yearly by the company.', '["are retain","is retained","were retained","<u>are retained</u>"]', 'Plural ''<b>workers</b>'' habitual â†’ <b>are retained</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9bfd96b4-9806-4eaa-805b-faca82cb9e52', 'Biology', 'JAMB', null, 2026, null, 'Paternity disputes can most accurately be resolved through the use of', null, '["fingerprint","blood group typing","DNA testing","tongue rolling"]', 2, 'Paternity disputes can most accurately be resolved through DNA testing. DNA testing analyzes specific genetic markers that are inherited from parents. It provides near 100% accuracy in identifying biological relationships. Blood group typing is less accurate because it can only exclude possible fathers, not prove paternity. Fingerprints and tongue rolling are not used in paternity testing.', true, '2026-09-09 03:19:26.524', '2026-09-09 03:19:26.524', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9c051edb-7130-4e08-9de4-e0fc360abd33', 'Biology', 'JAMB', null, 2026, null, 'Parental care is exhibited by', null, '["Snails","Earthworms","Birds","Toads"]', 2, 'Parental care is exhibited by birds. Birds build nests, incubate eggs, and feed and protect their young. Parental care in birds includes both parents often sharing responsibilities. Snails and earthworms show little or no parental care beyond egg deposition. Toads generally lay eggs and leave them. Birds have evolved complex parental behaviors essential for their survival. Parental care is more developed in birds than in amphibians and invertebrates.', true, '2026-09-09 03:19:05.119', '2026-09-09 03:19:05.119', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9c0d13db-6220-43f3-84a3-d475aa0f9589', 'Economics', 'JAMB', null, 2026, null, 'An industry operating in a perfect competitive market situation will maximize profit when', null, '["MR=MC","AR>MR","MC<MR","AR<MC"]', 0, 'Profit is maximized where Marginal Revenue equals Marginal Cost.', true, '2026-09-12 11:01:30.747', '2026-09-12 11:01:30.747', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9c11dabf-e986-465c-b630-d182eb10ae79', 'Yoruba', 'JAMB', null, 2007, null, 'Àsìkò wo ni a máa p ýe eré ìdàrayá?', null, '["Lèyìn iýê òòjó","Lààárõ kùtùkùtù","Lòsàn-an gangan","Lásìkò iýê òòjò."]', 0, 'Àsìkò tí a máa p ýe eré ìdàrayá ni lèyìn iýê òòjó.', true, '2026-10-13 13:23:32.667', '2026-10-13 13:23:32.667', null, null, null, 'Àsìkò wo ni a máa p ýe eré ìdàrayá?', '["Lèyìn iýê òòjó","Lààárõ kùtùkùtù","Lòsàn-an gangan","Lásìkò iýê òòjò."]', 'Àsìkò tí a máa p ýe eré ìdàrayá ni lèyìn iýê òòjó.', '{"bold":["lèyìn iýê òòjó"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9c126108-295f-4d74-9de7-cb35630294f6', 'Financial Accounting', 'UTME', null, 2001, null, 'The officer responsible for ascertaining whether all public expenditure and appropriation are in line with approve guidelines is the', null, '["Accountant General","Auditor General","Finance Minister","Permanent secretary"]', 1, 'The officer responsible is the Auditor General.', true, '2026-10-12 22:00:07.868', '2026-10-12 22:00:07.868', null, null, null, 'The officer responsible for ascertaining whether all public expenditure and appropriation are in line with approve guidelines is the', '["Accountant General","<b>Auditor General</b>","Finance Minister","Permanent secretary"]', 'The officer responsible is the <b>Auditor General</b>.', '{"bold":["Auditor General"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9c12c5e3-6b30-47a6-8da1-16e335873d4e', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). The president said that he <u>found himself between a rock and a hard place</u> when the press said that he had resigned', null, '["He dreamt that he was abandoned","He thought that hard places were unsafe","He had a hard decision to make","Hard places are dangerous for the president"]', 2, '''Between a rock and a hard place'' = facing a difficult choice.', true, '2026-10-24 01:04:24.908', '2026-10-24 01:04:24.908', null, null, null, '(Choose the most appropriate interpretation). The president said that he <u>found himself between a rock and a hard place</u> when the press said that he had resigned', '["He dreamt that he was abandoned","He thought that hard places were unsafe","<u>He had a hard decision to make</u>","Hard places are dangerous for the president"]', '''<b>Between a rock and a hard place</b>'' = <b>facing a difficult choice</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9c34050a-e5d8-43bb-ac12-6795c6dba206', 'Financial Accounting', 'UTME', null, 2004, null, 'The head office of Emeka stores maintains the financial account of all its branches. The branch store account in the head office serves as the branch', null, '["debtors'' account","trading account","expenses account","cash account"]', 1, 'The branch store account in the head office serves as the branch trading account.', true, '2026-10-12 22:00:03.477', '2026-10-12 22:00:03.477', null, null, null, 'The head office of Emeka stores maintains the financial account of all its branches. The branch store account in the head office serves as the branch', '["debtors'' account","<b>trading account</b>","expenses account","cash account"]', 'The branch store account in the head office serves as the branch <b>trading account</b>.', '{"bold":["trading account"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9c3529b9-1555-4702-8e48-3dd0b57cfdd2', 'English Language', 'JAMB', null, 2007, null, 'The officer described the comment as <u>__________</u> because it was very amusing.', null, '["ludicrous","dangerous","sad","libellous"]', 0, 'Correct spelling: ludicrous.', true, '2026-10-24 07:21:38.646', '2026-10-24 07:21:38.646', null, null, null, 'The officer described the comment as <u>__________</u> because it was very amusing.', '["ludicrous","dangerous","sad","libellous"]', 'Correct spelling: ludicrous.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9c386f49-3a8b-4f66-a093-a08975dd11d1', 'Literature in English', 'JAMB', null, 2026, null, '______ are examples of meter classification based on two syllables.', null, '["anapest, septet, iamb, trochaic","iamb, pyrrhic, trochaic, spondee","sonnet, dizain, anapest, pyrrhic","rondeau, monostitched, spondee, dactyle"]', 1, 'Iamb, pyrrhic, trochaic, and spondee are meters based on two syllables.', true, '2026-09-12 11:05:39.101', '2026-09-12 11:05:39.101', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9c44f30b-3db4-4d55-9d94-7e6056927cc3', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). The speaker <u>took his audience down memory lane</u> before he went to the topic of his lecture.', null, '["took his audience a journey through a street called Memory Lane","recalled events from the past","told a tale about a place called Memory Lane","gave an outline of his lecture"]', 1, '''Down memory lane'' = recall past events.', true, '2026-10-24 01:02:03.57', '2026-10-24 01:02:03.57', null, null, null, '(Choose the most appropriate interpretation). The speaker <u>took his audience down memory lane</u> before he went to the topic of his lecture.', '["took his audience a journey through a street called Memory Lane","<u>recalled events from the past</u>","told a tale about a place called Memory Lane","gave an outline of his lecture"]', '''<b>Down memory lane</b>'' = <b>recall past events</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9c494138-35a1-4718-8413-2f48cb493785', 'Economics', 'JAMB', null, 2026, null, 'Direct payment incurred for producing a commodity is called: (i) implicit cost (ii) real cost (iii) opportunity cost (iv) due cost (v) explicit cost', null, '["ii and iii only","I only","iv and v only","V only"]', 3, 'Direct payment incurred for producing a commodity is called explicit cost (v). Explicit costs are actual monetary payments made by a firm for inputs such as wages, rent, raw materials, and utilities. These are recorded in the firm''s accounting books. Implicit costs are opportunity costs of using owned resources. Real cost refers to the physical resources used.', true, '2026-09-10 10:41:19.915', '2026-09-10 10:41:19.915', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9c65a59e-243b-4308-bb8f-9180bc3cc718', 'Biology', 'JAMB', null, 2001, null, 'Viviparity occurs in', null, '["aves","amphibians","mammals","reptiles"]', 2, 'Viviparity, the development of an embryo inside the parent''s body, is a characteristic of mammals.', true, '2026-10-12 20:05:08.654', '2026-10-12 20:05:08.654', null, null, null, 'Viviparity occurs in', '["aves","amphibians","mammals","reptiles"]', 'Viviparity, the development of an embryo inside the parent''s body, is a characteristic of mammals.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('9c7180e2-135f-4a0e-9bca-7ba61c297848', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'St Paul’s epistle to the Philippians on ''Christian Giving'' indicated his reception of gifts from them through...', null, '["The Church in Corinth","St Peter","The Church in Achaia","Epaphroditus"]', 3, 'Philippians 4:18 states: ''I have received all and abound. I am full, having received from Epaphroditus the things sent from you.''', true, '2026-09-09 17:18:28.094', '2026-09-09 17:18:28.094', null, null, null, null, null, null, null);
