insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a2db9658-7cf1-4b31-a2af-b0d91cd242c8', 'Biology', 'JAMB', null, 2002, null, 'Examples of organisms in which extracellular digestion occurs are', null, '["Fungus, Loranthus and housefly","Rhizopus, sponges and earthworm","Round worm, tapeworm and hydra","Rhizopus, housefly and hydra"]', 3, 'Rhizopus, housefly and hydra exhibit extracellular digestion.', true, '2026-10-12 20:59:31.113', '2026-10-12 20:59:31.113', null, null, null, 'Examples of organisms in which extracellular digestion occurs are', '["Fungus, Loranthus and housefly","Rhizopus, sponges and earthworm","Round worm, tapeworm and hydra","Rhizopus, housefly and hydra"]', 'Rhizopus, housefly and hydra exhibit extracellular digestion.', '{"bold":["Rhizopus, housefly and hydra"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a2e09eae-acac-483b-a795-1500fd550c7f', 'Yoruba', 'JAMB', null, 2002, null, 'Ìwé Ojú Òjúpá, apá kìíní ni ìbéèrè 26-28 dá lé. Nínú ìtàn Ìtànjan Oòrùn … lèyìn bí òjò mélòò ní Êsankígbé tó tù àyìrí òba fún baba rè?', null, '["Mèjì","Mèta","Mèrin","Mèfà."]', 1, 'Lèyìn òjò mèta ní Êsankígbé tó tù àyìrí òba fún baba rè.', true, '2026-10-13 13:22:39.398', '2026-10-13 13:22:39.398', null, null, null, 'Ìwé Ojú Òjúpá, apá kìíní ni ìbéèrè 26-28 dá lé. Nínú ìtàn Ìtànjan Oòrùn … lèyìn bí òjò mélòò ní Êsankígbé tó tù àyìrí òba fún baba rè?', '["Mèjì","Mèta","Mèrin","Mèfà."]', 'Lèyìn òjò mèta ní Êsankígbé tó tù àyìrí òba fún baba rè.', '{"bold":["mèta"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a2e58de2-973d-4cd6-8dd6-c429d6a251ef', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Akin is <u>an inveterate</u> gambler.', null, '["a selfish and self-centred","an extremely unlucky but popular","an incurable but fearful","a long time and incorrigible"]', 3, 'Inveterate = long time and incorrigible.', true, '2026-10-24 01:04:07.51', '2026-10-24 01:04:07.51', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Akin is <u>an inveterate</u> gambler.', '["a selfish and self-centred","an extremely unlucky but popular","an incurable but fearful","<u>a long time and incorrigible</u>"]', '<b>Inveterate</b> = <b>long time and incorrigible</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a2eb76e1-1a23-4da4-8cd8-64eb07b1e48d', 'English Language', 'JAMB', null, 2024, null, 'The force of the explosion lifts the ______ around the bomb.', null, '["Atmosphere","Space","Height","Form"]', 0, '"Atmosphere" is the correct term for the air around the bomb.', true, '2026-09-18 09:43:02.445', '2026-09-18 09:43:02.445', null, null, 'CLOZE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a2ee434c-0bd1-44fc-b14a-54dd8afaba5f', 'Biology', 'JAMB', null, 2011, null, 'Seed plants are divided into', null, '["tracheophytes and ferns","angiosperms and gymnosperms","monocotyledons and dicotyledons.","thallophytes and bryophytes."]', 1, 'Seed plants are divided into angiosperms and gymnosperms.', true, '2026-10-12 20:59:41.747', '2026-10-12 20:59:41.747', null, null, null, 'Seed plants are divided into', '["tracheophytes and ferns","angiosperms and gymnosperms","monocotyledons and dicotyledons.","thallophytes and bryophytes."]', 'Seed plants are divided into angiosperms and gymnosperms.', '{"bold":["angiosperms and gymnosperms"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a2f5e548-e479-48ec-b433-da2defba23b2', 'Chemistry', 'JAMB', null, 2026, null, 'Which of the following best explains why aluminium does not react readily with water despite its high position in the electrochemical series?', null, '["Aluminium is less reactive than iron","Aluminium is protected by an oxide layer","Water is a weak oxidizing agent","Hydrogen gas prevents further reaction"]', 1, 'Aluminium quickly forms a thin, tough, unreactive surface film of aluminium oxide (Al2O3) that prevents contact with water.', true, '2026-09-09 17:12:48.31', '2026-09-09 17:12:48.31', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a30f676b-b8fe-4116-ad68-f4fa73b07fde', 'English Language', 'JAMB', null, 2007, null, 'We must not take with us the feelings of inadequacy <u>--------</u> experienced during our preparation for the debate', null, '["that were","those were","that was","that is"]', 0, '''Feelings'' plural â†’ that were.', true, '2026-10-24 01:02:15.926', '2026-10-24 01:02:15.926', null, null, null, 'We must not take with us the feelings of inadequacy <u>--------</u> experienced during our preparation for the debate', '["<u>that were</u>","those were","that was","that is"]', '''<b>Feelings</b>'' plural â†’ <b>that were</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a31bf0e7-dfe6-4fee-9b2d-07ef3b32be6f', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Bose was angry because her friend called her a <u>pilferer</u>.', null, '["liar","hypocrite","criminal","thief"]', 3, 'Pilferer = thief.', true, '2026-10-24 01:01:50.923', '2026-10-24 01:01:50.923', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Bose was angry because her friend called her a <u>pilferer</u>.', '["liar","hypocrite","criminal","<u>thief</u>"]', '<b>Pilferer</b> = <b>thief</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a31ffbef-c5da-4c9d-a8e2-baba5bb93c41', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'What name did Abraham give the place where he had attempted to sacrifice his son?', null, '["the LORD is with us","the LORD will provide","the Mount of the Lord","the gate of heaven"]', 1, 'Abraham called it ''The LORD will provide'' (Yahweh-jireh).', true, '2026-09-12 10:41:08.8', '2026-09-12 10:41:08.8', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a32a547c-ef4e-4edd-9e1e-6d51123a644f', 'General Mathematics', 'JAMB', null, 2026, null, 'Express 0.004562 in three decimal places.', null, '["0.00456","0.005","0.0046","0.0050"]', 1, '0.004562 to 3 d.p. = 0.005.', true, '2026-09-12 11:43:54.782', '2026-09-12 11:43:54.782', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a32e8908-1311-4546-a82e-6fd843ec4539', 'Christian Religious Studies', 'JAMB', null, 2026, null, '“I was in the city of joppa praying; and in a trance, I saw a vision...” What was the outcome of this vision?', null, '["Peter ate forbidden fruit for the first time","Gentiles were circumcised for the first time","Peter was praised by believers in Jerusalem","Gentiles received the word of God"]', 3, 'In Acts 11:1–18, Peter defends his visit to Cornelius in Caesarea by describing his vision in Joppa. The vision demonstrated that God treats no human as unclean, leading directly to Gentiles hearing and receiving the word of God and receiving the Holy Spirit.', true, '2026-09-09 17:18:23.397', '2026-09-09 17:18:23.397', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a349af1b-b5c7-4ffa-94a3-e24e804d7c01', 'General Mathematics', 'JAMB', null, 2026, null, 'X varies as the product of U and V and inversely as their sum. If X = 3 when U = 3 and V = 1, what is the value of X if U = 3 and V = 3?', null, '["9","3","4","6"]', 1, 'X = kUV/(U+V). 3 = k(3)(1)/(3+1) = 3k/4, so k = 4. When U = 3, V = 3: X = 4(3)(3)/(3+3) = 36/6 = 6. Wait, that gives 6. Let me recalculate: 3 = k(3)(1)/4 = 3k/4, k = 4. X = 4(3)(3)/6 = 36/6 = 6. The answer is (D) 6.', true, '2026-09-10 10:48:19.094', '2026-09-10 10:48:19.094', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a34e2090-2eed-42db-bf4a-7e882dd75b72', 'Physics', 'JAMB', null, 1997, null, 'A boy on looking into a mirror observed that his face appeared to have grown bigger. The boy must have been looking at a', null, '["Convex mirror with his face at the focus","Concave mirror with his face between the focus and the mirror.","Concave mirror with his face at the focus","Convex mirror with his face between the focus and the mirror."]', 1, 'Only a concave mirror gives an enlarged image, and an upright enlarged image occurs when the object is between the focus and the mirror.', true, '2026-10-12 19:15:43.906', '2026-10-12 19:15:43.906', null, null, null, 'A boy on looking into a mirror observed that his face appeared to have grown bigger. The boy must have been looking at a', '["Convex mirror with his face at the focus","Concave mirror with his face between the focus and the mirror.","Concave mirror with his face at the focus","Convex mirror with his face between the focus and the mirror."]', 'Only a concave mirror gives an enlarged image, and an upright enlarged image occurs when the object is between the focus and the mirror.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a356b4c0-0509-4240-acfd-e5053c1aad98', 'Biology', 'JAMB', null, 2003, null, 'A noticeable adaptation of the animal to its aquatic habitat is the possession of', null, '["a wide mouth","large eyes","webbed digits","four limbs"]', 2, 'Webbed digits are an adaptation to aquatic habitat.', true, '2026-10-12 20:59:32.105', '2026-10-12 20:59:32.105', null, null, null, 'A noticeable adaptation of the animal to its aquatic habitat is the possession of', '["a wide mouth","large eyes","webbed digits","four limbs"]', 'Webbed digits are an adaptation to aquatic habitat.', '{"bold":["Webbed digits"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a358a18a-ba82-44ca-954b-9ef916f8815a', 'Economics', 'JAMB', null, 2026, null, 'If commodities X and Y are substitute, their cross elasticity of demand will be?', null, '["Positive","Zero","Negative","One"]', 0, 'Substitutes have positive cross elasticity of demand.', true, '2026-09-12 11:02:05.656', '2026-09-12 11:02:05.656', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a35e48e6-2a8c-4a0c-8ca4-2114673cc4c5', 'Biology', 'JAMB', null, 2012, null, 'In plants, which of the following is required in minute quantities for growth?', null, '["Copper","Potassium","Phosphorus","Sodium."]', 0, 'Copper is required in minute quantities for plant growth.', true, '2026-10-12 20:59:44.64', '2026-10-12 20:59:44.64', null, null, null, 'In plants, which of the following is required in minute quantities for growth?', '["Copper","Potassium","Phosphorus","Sodium."]', 'Copper is required in minute quantities for plant growth.', '{"bold":["Copper"],"italic":[],"underline":[],"fillBlanks":[]}');
