insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a51e281d-8c7a-4f49-877f-e741cf673326', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). At that point, the <u>speaker went off at a tangent</u>.', null, '["started to run away like a mad person","took a lashing out at the audience","began to discuss unrelated matters","chose to recall previous decision"]', 2, '''Went off at a tangent'' = digressed to unrelated matters.', true, '2026-10-24 01:04:20.987', '2026-10-24 01:04:20.987', null, null, null, '(Choose the most appropriate interpretation). At that point, the <u>speaker went off at a tangent</u>.', '["started to run away like a mad person","took a lashing out at the audience","<u>began to discuss unrelated matters</u>","chose to recall previous decision"]', '''<b>Went off at a tangent</b>'' = <b>digressed to unrelated matters</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a52162e5-92dd-437c-9035-124a32086b79', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). Kelechi <u>hardly ever</u> falls sick.', null, '["most often","very seldom","sometimes","frequently","occasionally"]', 1, '''Hardly ever'' = very seldom.', true, '2026-10-24 01:04:15.689', '2026-10-24 01:04:15.689', null, null, null, '(Choose the most appropriate interpretation). Kelechi <u>hardly ever</u> falls sick.', '["most often","<u>very seldom</u>","sometimes","frequently","occasionally"]', '''<b>Hardly ever</b>'' = <b>very seldom</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a526255c-0db9-4f9b-98f0-811e28b8beea', 'Literature in English', 'JAMB', null, 2026, null, 'Repetition, rhyme and rhythm are permanent features of', null, '["Drama","Poetry","Short story","Prose"]', 1, 'These are features of poetry.', true, '2026-09-12 11:10:51.524', '2026-09-12 11:10:51.524', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a5284d21-d7bb-4fdd-8d56-bbdfd14beaad', 'Literature in English', 'JAMB', null, 2026, null, 'What theme is best illustrated by the tale?', null, '["romantic love","the power of prophecy","the danger of pride and flattery","heroism in battle"]', 2, 'The danger of pride and flattery is the theme.', true, '2026-09-12 11:13:58.345', '2026-09-12 11:13:58.345', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a53186a6-a8e8-4e5a-b537-aba6689c99d3', 'Economics', 'JAMB', null, 2026, null, 'The sellers are willing to offer all available quantity for sale at a prevailing price. If there''s any fall in price, it can cause an infinite change in supply. This describes', null, '["Fairly inelastic supply","elastic supply","Perfectly inelastic supply","Perfectly elastic supply"]', 3, 'Perfectly elastic supply means sellers will supply any quantity at a given price, but none at a lower price.', true, '2026-09-12 11:00:12.8', '2026-09-12 11:00:12.8', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a53ed1d7-b7e4-45cf-8e7b-ead0af551c3e', 'Literature in English', 'JAMB', null, 2026, null, 'The thematic preoccupation of migration in the novel is best examined through', null, '["symbolism of landscape","characterization and diaspora experience","dialogue and humour","episodic narration"]', 1, 'Migration is examined through characterization and diaspora experience.', true, '2026-09-12 11:11:19.816', '2026-09-12 11:11:19.816', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a5418876-b31b-495d-afae-f4ff4cd8524b', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. He <u>reneged on</u> the agreement between him and his employees.', null, '["kept","failed to keep","failed to approve","failed to sign"]', 1, 'Reneged on = failed to keep.', true, '2026-10-24 01:01:46.848', '2026-10-24 01:01:46.848', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. He <u>reneged on</u> the agreement between him and his employees.', '["kept","<u>failed to keep</u>","failed to approve","failed to sign"]', '<b>Reneged on</b> = <b>failed to keep</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a542933c-728e-45eb-91cd-39f0b4317b66', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'The Apostles created an office besides prayer and preaching to address', null, '["injustice","incest","adultery","false prophecy"]', 0, 'The Apostles created the office of deacon to address injustice. There was a complaint that the Hellenist widows were being neglected in the daily distribution, so seven men were appointed to serve tables.', true, '2026-09-12 09:45:56.059', '2026-09-12 09:45:56.059', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a54ee3a6-9169-4efe-9705-9be0858bc09a', 'General Mathematics', 'JAMB', null, 2026, null, 'If the second term of a G.P is 2 and its sum to infinity is 8, find its fifth term.', null, '["1/9","1/4","1/8","1/81"]', 2, 'ar = 2. a/(1-r) = 8. a = 8(1-r). 8r(1-r) = 2. 4r(1-r) = 1. 4r²-4r+1 = 0. r = 1/2. a = 4. T5 = 4(1/2)⁴ = 4/16 = 1/4. The answer is (B) 1/4.', true, '2026-09-12 11:43:55.935', '2026-09-12 11:43:55.935', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a565efe7-dbd5-4133-9a5a-14013d1bd8b9', 'Economics', 'JAMB', null, 2026, null, 'A partnership sourcing for funds to expand its business would approach', null, '["Capital market","Money market","Insurance","Stock exchange"]', 1, 'A partnership would approach the money market for short-term funds.', true, '2026-09-12 10:58:48.215', '2026-09-12 10:58:48.215', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a56e54dc-3d12-49b4-b373-ccf7b2273e11', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'In Acts, what event caused the dispersion of Christians and led to the spread of the Gospel among Gentiles?', null, '["The resurrection of Jesus","The stoning of Stephen","The conversion of Saul","The crucifixion of Jesus"]', 1, 'The stoning of Stephen led to persecution and dispersion of Christians.', true, '2026-09-12 10:41:45.83', '2026-09-12 10:41:45.83', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a573775c-ceac-4073-8d5c-bf736cc0a935', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). When the man lost his two sons in a motor accident, he <u>cracked up</u>.', null, '["became broken-hearted","became insane/irresponsible","became slightly deranged","became temperamental"]', 0, '''Cracked up'' = broke down emotionally.', true, '2026-10-24 01:02:05.747', '2026-10-24 01:02:05.747', null, null, null, '(Choose the most appropriate interpretation). When the man lost his two sons in a motor accident, he <u>cracked up</u>.', '["<u>became broken-hearted</u>","became insane/irresponsible","became slightly deranged","became temperamental"]', '''<b>Cracked up</b>'' = <b>broke down emotionally</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a576e0b1-1949-4bf5-9458-39f54e642623', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). Many workers are not happy because they <u>live a hand-to-mouth life</u>', null, '["They work hard with their hands","They are voracious and avaricious","They are barely surviving","They have rejected the use of spoons"]', 2, '''A hand-to-mouth life'' = barely surviving.', true, '2026-10-24 01:04:25.228', '2026-10-24 01:04:25.228', null, null, null, '(Choose the most appropriate interpretation). Many workers are not happy because they <u>live a hand-to-mouth life</u>', '["They work hard with their hands","They are voracious and avaricious","<u>They are barely surviving</u>","They have rejected the use of spoons"]', '''A <b>hand-to-mouth life</b>'' = <b>barely surviving</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a5772a95-da7c-4930-93d1-572f94dace9a', 'English Language', 'JAMB', null, 2007, null, 'We shall offer a good job to a <u>__________</u> to register guests in the Central Hotel', null, '["waiter","watchman","cashier","receptionist","cleaner"]', 3, 'Correct spelling: receptionist.', true, '2026-10-24 07:21:40.479', '2026-10-24 07:21:40.479', null, null, null, 'We shall offer a good job to a <u>__________</u> to register guests in the Central Hotel', '["waiter","watchman","cashier","receptionist","cleaner"]', 'Correct spelling: receptionist.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a57cd71e-3dc2-4c45-8c26-92642db57997', 'English Language', 'JAMB', null, 2007, null, 'Four weeks <u>------------</u> enough for the police to conclude their investigation.', null, '["were","is","are","has been"]', 1, 'Period as unit â†’ singular is.', true, '2026-10-24 01:02:15.283', '2026-10-24 01:02:15.283', null, null, null, 'Four weeks <u>------------</u> enough for the police to conclude their investigation.', '["were","<u>is</u>","are","has been"]', 'Period as <b>unit</b> â†’ singular <b>is</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a57ce930-c1e4-4b17-a2e0-ed720135abe6', 'Literature in English', 'JAMB', null, 2026, null, '______ entails the working class struggles and lifestyle', null, '["sink in the kitchen drama","comedy of manner","Kitchen-sink drama","Satirical drama"]', 2, 'Kitchen-sink drama entails working class struggles and lifestyle.', true, '2026-09-12 11:12:09.026', '2026-09-12 11:12:09.026', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a57e43a1-71e1-4edd-82da-8d109b1f3c2e', 'Biology', 'JAMB', null, 2026, null, 'The exchange of genes between homologous chromosomes is called', null, '["test cross","back cross","crossing-over","mutation"]', 2, 'The exchange of genes between homologous chromosomes is called crossing-over. This occurs during prophase I of meiosis when homologous chromosomes pair up and exchange genetic material. Crossing-over produces new combinations of alleles, contributing to genetic diversity. A test cross is crossing an organism with a recessive homozygote. A back cross is crossing an organism with one of its parents. Mutation is a change in the DNA sequence.', true, '2026-09-09 03:19:13.845', '2026-09-09 03:19:13.845', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a591869a-c62d-4d31-bff9-712dbf1d1903', 'Economics', 'JAMB', null, 2026, null, 'All but one of the following is a direct tax;', null, '["Value-added tax","Poll tax","Capital Gain tax","Personal Income tax"]', 0, 'Value-added tax (VAT) is an indirect tax.', true, '2026-09-12 11:01:24.086', '2026-09-12 11:01:24.086', null, null, null, null, null, null, null);
