insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a5bdc24a-a16e-439b-8b80-585176153725', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. There was <u>a glut of</u> oil on the market.', null, '["a variety of","an accumulation of","an abundance of","an increase in"]', 2, 'Glut = abundance.', true, '2026-10-24 01:01:52.195', '2026-10-24 01:01:52.195', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. There was <u>a glut of</u> oil on the market.', '["a variety of","an accumulation of","<u>an abundance of</u>","an increase in"]', '<b>Glut</b> = <b>abundance</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a5c36183-defa-4945-a31d-e7a31377fc7c', 'Physics', 'JAMB', null, 1998, null, 'The tendon in a man''s leg is 0.01 m long. If a force of 5 N stretches the tendon by 2.0 x 10⁻⁵ m, calculate the strain on the muscle.', null, '["5 x 10⁶","5 x 10²","2 x 10⁻³","2 x 10⁻⁷"]', 2, 'Strain = extension/original length = (2.0 x 10⁻⁵)/0.01 = 2 x 10⁻³.', true, '2026-10-12 19:15:45.194', '2026-10-12 19:15:45.194', null, null, null, 'The tendon in a man''s leg is 0.01 m long. If a force of 5 N stretches the tendon by 2.0 x 10<sup>-5</sup> m, calculate the strain on the muscle.', '["5 x 10<sup>6</sup>","5 x 10<sup>2</sup>","2 x 10<sup>-3</sup>","2 x 10<sup>-7</sup>"]', 'Strain = extension/original length = (2.0 x 10<sup>-5</sup>)/0.01 = 2 x 10<sup>-3</sup>.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
