insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a5c8355f-1faa-40fa-90ca-5741e980348c', 'Literature in English', 'JAMB', null, 2026, null, '______ is Bathos', null, '["climax","anti-climax","exposition","resolution"]', 1, 'Bathos is anti-climax.', true, '2026-09-12 11:10:09.77', '2026-09-12 11:10:09.77', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a5c92ca8-e720-42b9-9e4d-c0b9e0e96b5e', 'Biology', 'JAMB', null, 2026, null, 'Haemophilia results from the mutation of the genes', null, '["in the sex chromosome","which control skin colour","which control the mechanism for blood clotting","which control the formation of haemoglobin"]', 2, 'Haemophilia results from the mutation of genes which control the mechanism for blood clotting. The genes for clotting factors VIII (haemophilia A) and IX (haemophilia B) are located on the X chromosome. Mutations in these genes lead to deficiencies in the clotting factors, causing prolonged bleeding. Haemophilia does not affect skin colour or hemoglobin formation. Sickle cell anaemia affects hemoglobin formation, and thalassemia is another hemoglobin disorder.', true, '2026-09-09 03:19:31.475', '2026-09-09 03:19:31.475', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a5d178f3-00e0-4049-a572-cdb2ab1835ee', 'Physics', 'JAMB', null, 1991, null, 'The mass of a stone is 15.0 g when completely immersed in water and 10.0 g when completely immersed in a liquid of relative density 2.0. The mass of the stone in air is', null, '["5.0 g","12.0 g","20.0 g","25.0 g"]', 2, 'Let the mass be m and volume V (cm³). m - V = 15 and m - 2V = 10, so V = 5 cm³ and m = 20 g.', true, '2026-10-12 19:15:32.92', '2026-10-12 19:15:32.92', null, null, null, 'The mass of a stone is 15.0 g when completely immersed in water and 10.0 g when completely immersed in a liquid of relative density 2.0. The mass of the stone in air is', '["5.0 g","12.0 g","20.0 g","25.0 g"]', 'Let the mass be m and volume V (cm<sup>3</sup>). m - V = 15 and m - 2V = 10, so V = 5 cm<sup>3</sup> and m = 20 g.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a5dbf8ef-6695-4998-bf19-15d33989b5a9', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. <u>Funnily</u> enough, the priest prayed for the robber who shot him.', null, '["Timidly","Fearlessly","Unexpectedly","Disappointingly"]', 2, 'Funnily enough = unexpectedly.', true, '2026-10-24 01:04:05.419', '2026-10-24 01:04:05.419', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. <u>Funnily</u> enough, the priest prayed for the robber who shot him.', '["Timidly","Fearlessly","<u>Unexpectedly</u>","Disappointingly"]', '<b>Funnily enough</b> = <b>Unexpectedly</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a5ea1725-1197-44bf-a7e5-2be2d0b54077', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Mariam looks rather <u>furtive</u> to Shehu.', null, '["intoxicated","sad","unfriendly","sly"]', 3, 'Furtive = sly.', true, '2026-10-24 01:04:07.723', '2026-10-24 01:04:07.723', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Mariam looks rather <u>furtive</u> to Shehu.', '["intoxicated","sad","unfriendly","<u>sly</u>"]', '<b>Furtive</b> = <b>sly</b>.', '{}');
