insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a5fe1b4a-9739-4f73-9974-fc3b27b57ae6', 'Physics', 'JAMB', null, 2002, null, 'A concave mirror of radius of curvature 40 cm forms a real image twice as large as the object. The object distance is', null, '["60 cm","40 cm","30 cm","10 cm"]', 2, 'f = 20 cm. For a real image with m = 2, v = 2u. 1/20 = 1/u + 1/(2u) = 3/(2u), so u = 30 cm.', true, '2026-10-12 19:15:53.377', '2026-10-12 19:15:53.377', null, null, null, 'A concave mirror of radius of curvature 40 cm forms a real image twice as large as the object. The object distance is', '["60 cm","40 cm","30 cm","10 cm"]', 'f = 20 cm. For a real image with m = 2, v = 2u. 1/20 = 1/u + 1/(2u) = 3/(2u), so u = 30 cm.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a611ed2e-b218-42c0-b67b-5f365a4c3664', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Man was the last of all that God created but man was crowned by God at creation to be king over all other creatures is not unconnected with', null, '["man''s ability to manage all other creatures","man''s religious in divination","the reflection of God''s image in the nature of man","man''s ability to recreate all that God created originally"]', 2, 'Man was crowned king over all creatures because of the reflection of God''s image in the nature of man. God said, ''Let us make man in our image, after our likeness; and let them have dominion over all the earth.''', true, '2026-09-12 09:45:56.296', '2026-09-12 09:45:56.296', null, null, null, null, null, null, null);
