insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a6a27f35-bae2-43cf-9eaa-a4d1abbf02da', 'Physics', 'JAMB', null, 1983, null, 'The total length of a spring when a mass of 200 g is hung from its end is 14 cm, while its total length is 16 cm when a mass of 300 g is hung from the same end. Calculate the unstretched length of the spring assuming Hooke''s law is obeyed.', null, '["9.33 cm","10.00 cm","10.66 cm","12.00 cm","15.00 cm"]', 1, 'Extension is proportional to load. An extra 100 g adds 2 cm, so 200 g gives an extension of 4 cm. Unstretched length = 14 - 4 = 10.00 cm.', true, '2026-10-12 19:15:17.263', '2026-10-12 19:15:17.263', null, null, null, 'The total length of a spring when a mass of 200 g is hung from its end is 14 cm, while its total length is 16 cm when a mass of 300 g is hung from the same end. Calculate the unstretched length of the spring assuming Hooke''s law is obeyed.', '["9.33 cm","10.00 cm","10.66 cm","12.00 cm","15.00 cm"]', 'Extension is proportional to load. An extra 100 g adds 2 cm, so 200 g gives an extension of 4 cm. Unstretched length = 14 - 4 = 10.00 cm.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a6a62fc3-f450-4aee-8861-98af3c482f07', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Jesus said he had come down from heaven to', null, '["give bread","give water","do the will of God","baptize people"]', 2, 'Jesus came to do the will of God who sent Him.', true, '2026-09-12 10:42:17.276', '2026-09-12 10:42:17.276', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a6b13cec-91e2-4888-9c13-e71607e87035', 'Biology', 'JAMB', null, 2011, null, 'In which of the following groups of vertebrates is parental care mostly exhibited?', null, '["Reptilia","Amphibia","Aves","Mammalia"]', 3, 'Mammalia exhibit the most parental care.', true, '2026-10-12 20:59:41.798', '2026-10-12 20:59:41.798', null, null, null, 'In which of the following groups of vertebrates is parental care mostly exhibited?', '["Reptilia","Amphibia","Aves","Mammalia"]', 'Mammalia exhibit the most parental care.', '{"bold":["Mammalia"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a6bc8059-8184-43c0-8073-238b051f56fd', 'Literature in English', 'JAMB', null, 2026, null, 'The poem employs repetition mainly to', null, '["create humour","emphasize apathy and complicity","beautify language","confuse the reader"]', 1, 'Repetition emphasizes apathy and complicity.', true, '2026-09-12 11:11:22.537', '2026-09-12 11:11:22.537', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a6c45fa9-cb25-430b-aaaf-62237b4eef1b', 'English Language', 'JAMB', null, 2007, null, 'A Tale of Two Cities <u>------------</u> the <u>------------</u> we are studying for the examination.', null, '["are/novels","was/novel","were/novels","is/novel"]', 3, 'Book title singular â†’ is/novel.', true, '2026-10-24 01:02:12.057', '2026-10-24 01:02:12.057', null, null, null, 'A Tale of Two Cities <u>------------</u> the <u>------------</u> we are studying for the examination.', '["are/novels","was/novel","were/novels","<u>is/novel</u>"]', 'Book <b>title</b> singular â†’ <b>is/novel</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a6c68af0-ca9d-479e-8a4f-25f9c5d09795', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'What name did Abraham give the place where he had attempted to sacrifice his son?', null, '["the LORD is with us","the LORD will provide","the Mount of the Lord","the gate of heaven"]', 1, 'Abraham called the place ''The LORD will provide'' (Yahweh-jireh). He named it this because God provided a ram as a substitute for Isaac.', true, '2026-09-12 09:45:57.66', '2026-09-12 09:45:57.66', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a6debd49-dc11-4b12-87cd-62ce3a93cd4a', 'Biology', 'JAMB', null, 2026, null, 'Identical twins inherit their genes from', null, '["different eggs and sperms","the same egg and sperm","two eggs and a sperm","one egg and two sperms"]', 1, 'Identical twins inherit their genes from the same egg and sperm. Identical (monozygotic) twins form when a single fertilized egg (zygote) splits into two embryos. Therefore, they have identical genetic material. They are always the same sex and have nearly identical physical characteristics. Fraternal (dizygotic) twins come from different eggs and sperms. The same egg and sperm produce genetically identical offspring.', true, '2026-09-09 03:19:26.3', '2026-09-09 03:19:26.3', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a70d8fca-1c2f-4086-bbb5-b7d52a46fa9d', 'Physics', 'JAMB', null, 1997, null, 'A galvanometer of internal resistance 50 Ω has a full scale deflection for a current of 5 mA. What is the resistance required to convert it to a voltmeter with full scale deflection of 10 V?', null, '["1 750 Ω","1 950 Ω","2 000 Ω","2 500 Ω"]', 1, 'Total resistance = 10/0.005 = 2000 Ω. Series resistance = 2000 - 50 = 1 950 Ω.', true, '2026-10-12 19:15:44.12', '2026-10-12 19:15:44.12', null, null, null, 'A galvanometer of internal resistance 50 Ω has a full scale deflection for a current of 5 mA. What is the resistance required to convert it to a voltmeter with full scale deflection of 10 V?', '["1 750 Ω","1 950 Ω","2 000 Ω","2 500 Ω"]', 'Total resistance = 10/0.005 = 2000 Ω. Series resistance = 2000 - 50 = 1 950 Ω.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a719f2f3-a272-48f1-a6ac-7f40e732ee51', 'Biology', 'JAMB', null, 2026, null, 'At what stage in the life history of a mammal is the sex of an individual set?', null, '["Adolescence","Puberty","Birth","Conception"]', 3, 'The sex of an individual is set at conception, when the sperm (carrying either X or Y chromosome) fuses with the egg (always carrying X chromosome). If a sperm carrying the Y chromosome fertilizes the egg, the resulting embryo will be male (XY). If a sperm carrying the X chromosome fertilizes the egg, the resulting embryo will be female (XX). This genetic sex is determined at the moment of fertilization. Adolescence and puberty are when sex characteristics develop, and birth is when the individual is delivered.', true, '2026-09-09 03:18:57.677', '2026-09-09 03:18:57.677', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a71b551d-f351-4ba5-8a8a-ec8ac017c032', 'Literature in English', 'JAMB', null, 2026, null, 'The major divisions in a play are', null, '["Acts","Chapters","Scenes","Stanzas"]', 0, 'Acts are the major divisions in a play.', true, '2026-09-12 11:11:05.66', '2026-09-12 11:11:05.66', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a7233ddd-6464-4619-b731-8a0a2f4a4a7b', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. He gave a <u>painstaking</u> account of his encounter with the ghost of his father.', null, '["sordid","fearful","half-hearted","tender-hearted"]', 2, 'Painstaking = careful; opposite = half-hearted.', true, '2026-10-24 07:21:17.247', '2026-10-24 07:21:17.247', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. He gave a <u>painstaking</u> account of his encounter with the ghost of his father.', '["sordid","fearful","half-hearted","tender-hearted"]', 'Painstaking = careful; opposite = half-hearted.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a7269ad7-cc1f-481d-893b-cc17b0a948dd', 'Biology', 'JAMB', null, 2013, null, 'During the manufacture of food by plants, which of the following organisms use energy from the sun?', null, '["Nitrospmonas sp.","Nitrobacter sp.","Anabaena","Sulfur bacteria"]', 2, 'Anabaena uses energy from the sun for photosynthesis.', true, '2026-10-12 20:59:46.773', '2026-10-12 20:59:46.773', null, null, null, 'During the manufacture of food by plants, which of the following organisms use energy from the sun?', '["Nitrospmonas sp.","Nitrobacter sp.","Anabaena","Sulfur bacteria"]', 'Anabaena uses energy from the sun for photosynthesis.', '{"bold":["Anabaena"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a727d570-f009-4fc7-8eb7-09f68896c811', 'Government', 'JAMB', null, 2026, null, 'The name of the electoral body under the 1979 constitution was', null, '["NEC","INEC","FEDECO","NECON"]', 2, 'FEDECO was the electoral body under the 1979 constitution.', true, '2026-09-12 11:24:00.372', '2026-09-12 11:24:00.372', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a738bf7c-14cf-4843-a95d-e28b06d74426', 'English Language', 'JAMB', null, 2007, null, 'The Governor rejected the bill and withheld his <u>__________</u>', null, '["accent","assent","access","ascent"]', 1, 'Correct spelling and meaning: assent.', true, '2026-10-24 07:21:35.467', '2026-10-24 07:21:35.467', null, null, null, 'The Governor rejected the bill and withheld his <u>__________</u>', '["accent","assent","access","ascent"]', 'Correct spelling and meaning: assent.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a751fdc2-b277-4a74-ad6b-469d26ee26b4', 'Government', 'JAMB', null, 2026, null, 'LEGITIMACY means the', null, '["Seizure of power by force","Separation of powers of governments","Sovereignty of parliament","Acceptance of the right to rule"]', 3, 'Legitimacy means acceptance of the right to rule.', true, '2026-09-12 11:24:18.591', '2026-09-12 11:24:18.591', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a7522c74-4c74-4ce2-9c6c-2484d7a3c5b8', 'Biology', 'JAMB', null, 2003, null, 'Homologous pairs of chromosomes separate during', null, '["cytolysis","cleavage","mitosis","meiosis"]', 3, 'Homologous chromosomes segregate during the first anaphase stage of meiosis.', true, '2026-10-12 20:05:09.914', '2026-10-12 20:05:09.914', null, null, null, 'Homologous pairs of chromosomes separate during', '["cytolysis","cleavage","mitosis","meiosis"]', 'Homologous chromosomes segregate during the first anaphase stage of meiosis.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a75eb688-018c-4705-8b3c-2bcebefea1ab', 'Physics', 'JAMB', null, 2026, null, 'A load of 300N is to be lifted by a machine with a velocity ratio of 2 and an efficiency of 60%. What effort will be applied to lift the load?', null, '["100N","150N","250N","400N"]', 2, 'Efficiency = (MA/VR) × 100. 60 = (MA/2) × 100. MA = 1.2. Effort = Load/MA = 300/1.2 = 250N.', true, '2026-09-10 10:56:49.657', '2026-09-10 10:56:49.657', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a77039e2-b4de-4049-8b9a-4b1b288ac445', 'Biology', 'JAMB', null, 2026, null, 'Which of the following is not an evidence of evolution?', null, '["fossil","anatomy","embryology","genetics","behavior"]', 4, 'Behavior is not typically considered a direct evidence of evolution. While behavior can evolve and be influenced by natural selection, it is not used as primary evidence for evolution in the way that fossils, comparative anatomy, embryology, and genetics are. Fossils show a chronological sequence of life forms. Comparative anatomy reveals homologous structures. Embryology shows similarities in early development. Genetics shows shared DNA sequences. These four provide concrete physical and molecular evidence for evolutionary relationships.', true, '2026-09-09 03:18:38.922', '2026-09-09 03:18:38.922', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a77779e9-8c68-41a3-9b66-2314e498d4eb', 'Hausa', 'JAMB', null, 2010, null, 'Ana fitar da mataccen jini daga jiki ta hanyar', null, '["rauni","ŝaho","sakiya","tsaga."]', 1, 'Ana fitar da mataccen jini daga jiki ta hanyar ŝaho.', true, '2026-10-13 10:37:24.517', '2026-10-13 10:37:24.517', null, null, null, 'Ana fitar da mataccen jini daga jiki ta hanyar', '["rauni","ŝaho","sakiya","tsaga."]', 'Ana fitar da mataccen jini daga jiki ta hanyar ŝaho.', '{"bold":["ŝaho"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a77e3a7c-a6aa-4583-b251-c117de4aba6a', 'English Language', 'JAMB', null, 2007, null, 'Tokyo is one of the most developed <u>__________</u> of the world.', null, '["electronics centre","electronic centre","electronics centres","electronic centres"]', 3, 'Correct form: electronic centres.', true, '2026-10-24 07:21:34.506', '2026-10-24 07:21:34.506', null, null, null, 'Tokyo is one of the most developed <u>__________</u> of the world.', '["electronics centre","electronic centre","electronics centres","electronic centres"]', 'Correct form: electronic centres.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a7960894-71b6-4b7a-a192-703da5002fa3', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Every human being is <u>vulnerable</u> to communicable diseases.', null, '["liable","immuned","lifted","closed"]', 0, 'Vulnerable = liable.', true, '2026-10-24 01:04:07.67', '2026-10-24 01:04:07.67', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Every human being is <u>vulnerable</u> to communicable diseases.', '["<u>liable</u>","immuned","lifted","closed"]', '<b>Vulnerable</b> = <b>liable</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a7965917-2079-4cad-af37-315584860333', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). She realised that she was <u>up against</u> stiff competition when a new large departmental store was opened next to her small provisions shop.', null, '["next to","standing next to","opposed to","faced with"]', 3, '''Up against'' = faced with.', true, '2026-10-24 01:04:17.072', '2026-10-24 01:04:17.072', null, null, null, '(Choose the most appropriate interpretation). She realised that she was <u>up against</u> stiff competition when a new large departmental store was opened next to her small provisions shop.', '["next to","standing next to","opposed to","<u>faced with</u>"]', '''<b>Up against</b>'' = <b>faced with</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a79b2fb3-33e6-446c-b608-c7e90a2da560', 'Physics', 'JAMB', null, 1988, null, 'When white light is dispersed by a spectrometer, the component having the shortest wavelength is', null, '["Orange","Green","Violet","Red."]', 2, 'Violet light has the shortest wavelength of the visible colours; red has the longest.', true, '2026-10-12 19:15:28.011', '2026-10-12 19:15:28.011', null, null, null, 'When white light is dispersed by a spectrometer, the component having the shortest wavelength is', '["Orange","Green","Violet","Red."]', 'Violet light has the shortest wavelength of the visible colours; red has the longest.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a79bccc1-a7fe-410f-a8a1-36dacf505859', 'Biology', 'JAMB', null, 2026, null, 'The black fly is a vector of', null, '["Malaria","Trypanosomiasis","Onchocerciasis","Yellow fever"]', 2, 'The black fly (Simulium species) is the vector for Onchocerciasis (river blindness), caused by the parasitic worm Onchocerca volvulus. The flies breed near fast-flowing rivers and transmit the larvae to humans through bites. Malaria is transmitted by female Anopheles mosquitoes. Trypanosomiasis (sleeping sickness) is transmitted by tsetse flies. Yellow fever is transmitted by Aedes mosquitoes. Onchocerciasis is a major cause of blindness in tropical Africa and the Americas.', true, '2026-09-09 03:18:21.446', '2026-09-09 03:18:21.446', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a7a57ed6-70a6-4412-aea9-8cc353eaf7a2', 'Chemistry', 'JAMB', null, 2026, null, 'The number of hydrogen ion in 9.8g of tetraoxosulphate (VI) acid solution is', null, '["6.02 × 10^23","6.02 × 10^22","1.20 × 10^23","1.20 × 10^22"]', 2, 'Molar mass H2SO4 = 98 g/mol. Moles = 9.8 / 98 = 0.1 mol. Each mole releases 2 moles of H+ ions. Total H+ = 0.2 * 6.02 × 10^23 = 1.204 × 10^23 ions.', true, '2026-09-09 17:12:46.243', '2026-09-09 17:12:46.243', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a7a90330-208c-4a35-b1e1-f94161c41730', 'Biology', 'JAMB', null, 2003, null, 'An example of a caryopsis is', null, '["guava","maize grain","coconut","tomato"]', 1, 'Maize grain is a caryopsis.', true, '2026-10-12 20:59:33.079', '2026-10-12 20:59:33.079', null, null, null, 'An example of a caryopsis is', '["guava","maize grain","coconut","tomato"]', 'Maize grain is a caryopsis.', '{"bold":["Maize grain"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a7bfd607-e70a-4c70-9f21-0db039c29932', 'English Language', 'JAMB', null, 2024, null, 'Hope''s wife stopped supporting him financially because', null, '["She lost her job unexpectedly","She had planned to leave him from the start","Her job demands made it impracticable to continue","Her parents advised her to stop sending money"]', 2, 'Hope''s wife stopped supporting him because her job demands made it impracticable to continue.', true, '2026-09-18 09:43:02.689', '2026-09-18 09:43:02.689', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a7c18a3f-c14e-4bb4-b42d-77c16f28e142', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. For a long time, the robber defied police warnings as if he was <u>invulnerable</u>.', null, '["perfectly justifiable","difficult to catch","impossible to harm","indifferent to danger"]', 2, 'Invulnerable = impossible to harm.', true, '2026-10-24 01:01:48.81', '2026-10-24 01:01:48.81', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. For a long time, the robber defied police warnings as if he was <u>invulnerable</u>.', '["perfectly justifiable","difficult to catch","<u>impossible to harm</u>","indifferent to danger"]', '<b>Invulnerable</b> = <b>impossible to harm</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a7caa47e-eefe-4a9d-99b6-e8b20ec3e7b6', 'Government', 'JAMB', null, 2026, null, 'The Armed Forces Ruling Council (AFRC) is attributable to the regime', null, '["Ibrahim Babangida''s","Murtala/Obasanjo''s","Yakubu Gowon''s","Abdulsalam Abubakar''s"]', 0, 'The AFRC was established during Ibrahim Babangida''s regime.', true, '2026-09-12 11:23:59.509', '2026-09-12 11:23:59.509', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a7cbe8e1-4c9d-452b-9223-89900c99eda0', 'Biology', 'JAMB', null, 2026, null, 'What is the probability of a color blind mother and a normal father giving birth to a normal male child?', null, '["25%","50%","75%","0%"]', 3, 'The probability is 0% (none). Color blindness is an X-linked recessive trait. A color blind mother has the genotype X^n X^n (both X chromosomes have the recessive allele). A normal father has the genotype X^N Y. Sons inherit their Y chromosome from their father and one X chromosome from their mother. Since all of the mother''s X chromosomes carry the color blindness allele (X^n), all sons will inherit X^n from their mother and will be color blind (X^n Y). Therefore, there is zero probability of having a normal male child.', true, '2026-09-09 03:18:37.721', '2026-09-09 03:18:37.721', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a7cdb0f3-1dfd-4f3d-8839-c1938a1916f0', 'Physics', 'JAMB', null, 1994, null, 'An object is placed directly below a glass block of thickness 3.0 cm. Calculate the displacement of the object if the refractive index of the glass is 1.5.', null, '["1.0 cm","1.5 cm","2.0 cm","2.5 cm"]', 0, 'The apparent shift = t(1 - 1/n) = 3.0 x (1 - 1/1.5) = 1.0 cm.', true, '2026-10-12 19:15:40.076', '2026-10-12 19:15:40.076', null, null, null, 'An object is placed directly below a glass block of thickness 3.0 cm. Calculate the displacement of the object if the refractive index of the glass is 1.5.', '["1.0 cm","1.5 cm","2.0 cm","2.5 cm"]', 'The apparent shift = t(1 - 1/n) = 3.0 x (1 - 1/1.5) = 1.0 cm.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a7d23fda-9d85-4c7a-8a70-7a8b6f299584', 'Literature in English', 'JAMB', null, 2026, null, 'The tone of the poem can best be described as', null, '["celebratory","nostalgic and reflective","humorous","indifferent"]', 1, 'The tone is nostalgic and reflective.', true, '2026-09-12 11:05:52.511', '2026-09-12 11:05:52.511', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a7d32797-000d-449e-a798-dc50c22b8325', 'Economics', 'JAMB', null, 2026, null, 'The following is a factor that affects supply.', null, '["Income of consumer","Technology","Taste and Preferences","Demand"]', 1, 'Technology is a factor affecting supply. Income, taste, and demand affect demand, not supply.', true, '2026-09-12 10:59:49.245', '2026-09-12 10:59:49.245', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a7e118f0-3f77-484b-b393-ab2bc11846e6', 'English Language', 'JAMB', null, 2007, null, 'Simbi <u>------------</u> novels since she came home.', null, '["is reading","had been reading","has read","has been reading"]', 3, '''Since'' + ongoing â†’ present perfect continuous.', true, '2026-10-24 01:02:13.11', '2026-10-24 01:02:13.11', null, null, null, 'Simbi <u>------------</u> novels since she came home.', '["is reading","had been reading","has read","<u>has been reading</u>"]', '''<b>Since</b>'' + ongoing â†’ present perfect continuous.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a7e5bf25-b0da-41a3-98ca-1886f49f1cc3', 'English Language', 'JAMB', null, 2024, null, '48', null, '["Programmes","Occurrences","Resources","Laws"]', 1, '"Occurrences" fits the context of natural events.', true, '2026-09-18 10:17:48.876', '2026-09-18 10:17:48.876', 'decfd2ca-8924-4681-ba7c-9a039e9bda97', 1, 'CLOZE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a7e961e2-4e50-444d-af8e-5b242001c9d2', 'General Mathematics', 'JAMB', null, 2026, null, 'If 2x + y = 10 and x - y = 2, find x', null, '["3","4","5","6"]', 1, 'Adding: 3x = 12. x = 4.', true, '2026-09-12 11:44:07.825', '2026-09-12 11:44:07.825', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a7e9b9b0-efc4-4338-9497-bf3ccec9e9e1', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The paper carries many <u>humorous</u> cartoons on Saturdays.', null, '["amorous","grievous","hilarious","grave"]', 3, 'Humorous = funny; opposite = grave.', true, '2026-10-24 07:21:15.614', '2026-10-24 07:21:15.614', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The paper carries many <u>humorous</u> cartoons on Saturdays.', '["amorous","grievous","hilarious","grave"]', 'Humorous = funny; opposite = grave.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a7eae35e-849d-4cd4-abc2-f8361ee7041f', 'Physics', 'JAMB', null, 1985, null, 'In a gas experiment, the pressure of the gas is plotted against the reciprocal of the volume of the gas at a constant temperature. The unit of the slope of the resulting curve is', null, '["Force","Force/m","Work","Force/m³","Energy/m²"]', 2, 'The slope is P/(1/V) = PV. Pressure x volume has units (N m⁻²)(m³) = N m = joule, i.e. work (energy).', true, '2026-10-12 19:15:21.419', '2026-10-12 19:15:21.419', null, null, null, 'In a gas experiment, the pressure of the gas is plotted against the reciprocal of the volume of the gas at a constant temperature. The unit of the slope of the resulting curve is', '["Force","Force/m","Work","Force/m<sup>3</sup>","Energy/m<sup>2</sup>"]', 'The slope is P/(1/V) = PV. Pressure x volume has units (N m<sup>-2</sup>)(m<sup>3</sup>) = N m = joule, i.e. work (energy).', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a7f4954c-ae65-4c83-b363-95fccb149651', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). The cooperate existence of any nation is in jeopardy if her leaders <u>pay lip service to her unity</u>', null, '["injured his foot while entering his office","started off badly","made a costly mistake","stepped on the wrong toes"]', 3, 'Note: garbled source. Closest option chosen.', true, '2026-10-24 01:02:06.906', '2026-10-24 01:02:06.906', null, null, null, '(Choose the most appropriate interpretation). The cooperate existence of any nation is in jeopardy if her leaders <u>pay lip service to her unity</u>', '["injured his foot while entering his office","started off badly","made a costly mistake","<u>stepped on the wrong toes</u>"]', 'Note: <b>garbled source</b>. Closest option chosen.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a7fb722f-b951-4cc6-8d14-6111bb6eeff6', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). His summary of the meeting was <u>brief and to the point</u>.', null, '["precise","accurate","exact","crucial"]', 0, '''Brief and to the point'' = precise.', true, '2026-10-24 01:04:18.574', '2026-10-24 01:04:18.574', null, null, null, '(Choose the most appropriate interpretation). His summary of the meeting was <u>brief and to the point</u>.', '["<u>precise</u>","accurate","exact","crucial"]', '''<b>Brief and to the point</b>'' = <b>precise</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a8004010-f234-46aa-a6b8-e69ea4c33144', 'Biology', 'JAMB', null, 2026, null, 'Exhaled air differs from inhaled air in that it', null, '["contains less amounts of CO2","is usually lower in temperature","often has more oxygen","usually has more water vapour"]', 3, 'Exhaled air differs from inhaled air in that it usually has more water vapor. Exhaled air is saturated with moisture from the respiratory tract. Exhaled air also has more CO₂ and less oxygen than inhaled air. It is usually higher in temperature, as it is warmed by the body. During respiration, oxygen is taken up and CO₂ is released, making the exhaled air have less oxygen and more CO₂. The humidification of inhaled air is an important function of the respiratory system.', true, '2026-09-09 03:19:09.224', '2026-09-09 03:19:09.224', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a805f898-0d1b-4e24-be70-ff5a25dde813', 'Biology', 'JAMB', null, 2012, null, 'The feature that links birds to reptiles in evolution is the possession of', null, '["feathers","beak","skeleton","scales."]', 3, 'Scales link birds to reptiles in evolution.', true, '2026-10-12 20:59:44.438', '2026-10-12 20:59:44.438', null, null, null, 'The feature that links birds to reptiles in evolution is the possession of', '["feathers","beak","skeleton","scales."]', 'Scales link birds to reptiles in evolution.', '{"bold":["Scales"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a809e41a-52cc-451e-b076-734c14cf8591', 'Chemistry', 'JAMB', null, 2026, null, 'This type of bonding involves overlapping of orbitals during which electrons are shared', null, '["hydrogen bonding","covalent bonding","ionic bonding","metallic bonding","van-der-waals bonding"]', 1, 'Covalent bonding involves overlapping of orbitals and sharing of electrons.', true, '2026-09-12 11:36:11.562', '2026-09-12 11:36:11.562', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a81facfd-4b33-4e83-8b2d-32c853199559', 'Biology', 'JAMB', null, 2004, null, 'The larval stage of a mosquito is called', null, '["wriggler","grub","maggot","caterpillar"]', 0, 'Mosquito larvae are called wrigglers.', true, '2026-10-12 20:59:34.559', '2026-10-12 20:59:34.559', null, null, null, 'The larval stage of a mosquito is called', '["wriggler","grub","maggot","caterpillar"]', 'Mosquito larvae are called wrigglers.', '{"bold":["wrigglers"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a8251d15-ab72-4729-b7ba-cbfb1cf7ead2', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. My brother''s primary school foundation was <u>solid</u> and this influenced his secondary education.', null, '["sound","sordid","shaky","weak"]', 2, 'Solid = firm; opposite = shaky.', true, '2026-10-24 07:21:12.097', '2026-10-24 07:21:12.097', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. My brother''s primary school foundation was <u>solid</u> and this influenced his secondary education.', '["sound","sordid","shaky","weak"]', 'Solid = firm; opposite = shaky.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a828fe60-abb3-4310-b36c-f9e9693556b0', 'Biology', 'JAMB', null, 2026, null, 'A person with type O blood can donate to a patient with type A because the donor''s blood', null, '["lacks antigen","lacks anti-A antibodies","lacks anti-B antibodies","has both anti-A and anti-B antibodies"]', 0, 'A person with type O blood can donate to a patient with type A because the donor''s blood lacks antigens. Type O blood has no A or B antigens on the red blood cells, so it does not react with the anti-A antibodies in the recipient''s blood. While type O blood has both anti-A and anti-B antibodies in the plasma, the transfusion of packed red blood cells (which does not include plasma) is safe. This is why type O individuals are universal donors.', true, '2026-09-09 03:19:30.54', '2026-09-09 03:19:30.54', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a82cdaff-b1da-490a-a831-23e366070fc3', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Okibe was rusticated from his <u>derogatory</u> remark about the principal.', null, '["complimentary","unwarranted","unsavoury","lacklustre"]', 2, 'Derogatory = unsavoury.', true, '2026-10-24 01:04:07.296', '2026-10-24 01:04:07.296', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Okibe was rusticated from his <u>derogatory</u> remark about the principal.', '["complimentary","unwarranted","<u>unsavoury</u>","lacklustre"]', '<b>Derogatory</b> = <b>unsavoury</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a8470236-c0f5-4520-bec0-d0320a2cf991', 'English Language', 'JAMB', null, 2007, null, 'Either the manager or his assistants <u>_______</u> responsible for the error.', null, '["is","was","are","has been"]', 2, 'Nearest subject ''assistants'' plural â†’ are.', true, '2026-10-24 01:04:30.2', '2026-10-24 01:04:30.2', null, null, null, 'Either the manager or his assistants <u>_______</u> responsible for the error.', '["is","was","<u>are</u>","has been"]', 'Nearest subject ''<b>assistants</b>'' plural â†’ <b>are</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a848961e-997c-45c3-af78-a589463b5a17', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Because our representative is immature and biased, he takes a <u>jaundiced</u> view of our problems.', null, '["hazy","unclear","prejudiced","bleak"]', 2, 'Jaundiced = prejudiced.', true, '2026-10-24 01:03:58.189', '2026-10-24 01:03:58.189', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Because our representative is immature and biased, he takes a <u>jaundiced</u> view of our problems.', '["hazy","unclear","<u>prejudiced</u>","bleak"]', '<b>Jaundiced</b> = <b>prejudiced</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a86bcd10-52b3-41d1-a150-114140fee3f4', 'Hausa', 'JAMB', null, 2010, null, '''Ba neman aure ke da wuya ba, shiga-ka-fito''. Ka ga shiga-ka-fito din nan, lallai shiga-ka-fito din ne! Domin aljihu kan jigata kafin a kai ga biki. Tuddan da al''ada ta tanada, wadanda dole sai an haye su, suna da yawa. Yanzu dauki misalin kayan na-gani-ina-so, wato ''yan kayan nan da ake shiryawa a kai gidan su yarinya a karon farko. Ma''anar yin haka, wai iyaye su san cewa manemin auren ''yarsu da gaske yake. To, ina dole ga yin haka? Da can da yake zuwa yana zance da ''yarsu yana yi mata hasafi, ba a san da gaske yake ba? Gangaro kan kayan toshi. Nan ma tsabagen kudi ake kashewa a sayi suturu da kayan shafe-shafe a kai wa yarinya. Kada fa ka ce zuwa zance da manemi yake yana yi wa yarinya kyauta mako-mako, shi ke nan, ya wadatar. Ina, ko kadan! Kada ka mance da kudin gaisuwar iyaye da dukiyar aure kafin a yi baiko da sa ranar biki. Kudi ne madididiki ake tanada a kai wa iyayen yarinya da niyyar dai wannan abu da aka ambata. Duk bayan wannan, ana sa ranar aure, manemin yarinya ya dosa karakaina ke nan daga wannan gida zuwa wancan, ko ma wannan gari zuwa wancan da sunan gayar da iyaye da kakaninnta, wai don su san shi. I, za su san shi mana, tun da ba yana zuwa ne zikau ba! Da zarar biki ya kawo jiki kuma, uwa-uba za a shirya kayan lefe na fitar hankali a kai wa yarinya. Nan ma dukiya ake narkawa. Haķika duk wadannan abubuwa al''ada ce kawai ta kaķaba wa al''umma. Ai ta fuskar dukiya, muhimmin abu ga aure, sadaki. Amma abin takaici, yanzu an yi masa mahalli a can ķarshen sahu! Yaushe manemin yarinya ke zuwa gayar da iyaye da kakaninnta?', null, '["Bayan sa rana.","Kafin baiko.","Da soma ganin ta.","Da an yi biki."]', 0, 'Manemin yarinya ke zuwa gayar da iyaye da kakaninnta bayan sa rana.', true, '2026-10-13 10:37:23.448', '2026-10-13 10:37:23.448', null, null, null, '''Ba neman aure ke da wuya ba, shiga-ka-fito''. Ka ga shiga-ka-fito din nan, lallai shiga-ka-fito din ne! Domin aljihu kan jigata kafin a kai ga biki. Tuddan da al''ada ta tanada, wadanda dole sai an haye su, suna da yawa. Yanzu dauki misalin kayan na-gani-ina-so, wato ''yan kayan nan da ake shiryawa a kai gidan su yarinya a karon farko. Ma''anar yin haka, wai iyaye su san cewa manemin auren ''yarsu da gaske yake. To, ina dole ga yin haka? Da can da yake zuwa yana zance da ''yarsu yana yi mata hasafi, ba a san da gaske yake ba? Gangaro kan kayan toshi. Nan ma tsabagen kudi ake kashewa a sayi suturu da kayan shafe-shafe a kai wa yarinya. Kada fa ka ce zuwa zance da manemi yake yana yi wa yarinya kyauta mako-mako, shi ke nan, ya wadatar. Ina, ko kadan! Kada ka mance da kudin gaisuwar iyaye da dukiyar aure kafin a yi baiko da sa ranar biki. Kudi ne madididiki ake tanada a kai wa iyayen yarinya da niyyar dai wannan abu da aka ambata. Duk bayan wannan, ana sa ranar aure, manemin yarinya ya dosa karakaina ke nan daga wannan gida zuwa wancan, ko ma wannan gari zuwa wancan da sunan gayar da iyaye da kakaninnta, wai don su san shi. I, za su san shi mana, tun da ba yana zuwa ne zikau ba! Da zarar biki ya kawo jiki kuma, uwa-uba za a shirya kayan lefe na fitar hankali a kai wa yarinya. Nan ma dukiya ake narkawa. Haķika duk wadannan abubuwa al''ada ce kawai ta kaķaba wa al''umma. Ai ta fuskar dukiya, muhimmin abu ga aure, sadaki. Amma abin takaici, yanzu an yi masa mahalli a can ķarshen sahu! Yaushe manemin yarinya ke zuwa gayar da iyaye da kakaninnta?', '["Bayan sa rana.","Kafin baiko.","Da soma ganin ta.","Da an yi biki."]', 'Manemin yarinya ke zuwa gayar da iyaye da kakaninnta bayan sa rana.', '{"bold":["bayan sa rana"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a86cd9dc-478e-416b-95f8-c070a4cc92d6', 'Literature in English', 'JAMB', null, 2026, null, 'What is the central subject matter of the poem?', null, '["celebration of the sea''s beauty and power","an exploration of the history of navigation and maritime trade","a lament on human brutality and environmental decay as witnessed by the sea","a historical account of the Titanic disaster"]', 2, 'The central subject is a lament on human brutality and environmental decay.', true, '2026-09-12 11:10:44.407', '2026-09-12 11:10:44.407', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a87c6136-bbeb-450a-813d-66c5a16c8b90', 'English Language', 'JAMB', null, 2007, null, 'Western education is one of the <u>__________</u> of colonial rule.', null, '["evidence","remnants","inheritance","legacies"]', 3, 'Correct spelling: legacies.', true, '2026-10-24 07:21:39.116', '2026-10-24 07:21:39.116', null, null, null, 'Western education is one of the <u>__________</u> of colonial rule.', '["evidence","remnants","inheritance","legacies"]', 'Correct spelling: legacies.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a8a85001-c5ed-4bf9-ba6e-236620599d65', 'General Mathematics', 'JAMB', null, 2026, null, 'When the polynomial ax² - x + bx - 5 is divided by x-1 the remainder is -3 and when divided by x+2 the remainder is -27', null, '["a = 1, b = 2","a = 2, b = 1","a = 1/2, b = -1/2","a = -1/2, b = -2"]', 0, 'P(1) = a - 1 + b - 5 = -3. a + b = 3. P(-2) = 4a + 2 + 2b - 5 = -27. 4a + 2b = -24. 2a + b = -12. Solving: a = -15, b = 18. Not in options.', true, '2026-09-12 11:43:42.628', '2026-09-12 11:43:42.628', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a8ac35ec-94f0-43f7-a8e7-4c9ff2e38eb2', 'Biology', 'JAMB', null, 2003, null, 'The umbrella-shaped fruiting body of a fully developed mushroom is the', null, '["pileus","mycelium","basidium","stipe"]', 0, 'The umbrella-shaped fruiting body is the pileus.', true, '2026-10-12 20:59:32.225', '2026-10-12 20:59:32.225', null, null, null, 'The umbrella-shaped fruiting body of a fully developed mushroom is the', '["pileus","mycelium","basidium","stipe"]', 'The umbrella-shaped fruiting body is the pileus.', '{"bold":["pileus"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a8bf169a-2593-4471-aac6-91098634306c', 'Financial Accounting', 'UTME', null, 2001, null, 'To account for expenses paid by head office on behalf of the branch, the branch should', null, '["debit head office account and credit cash","debit profit and loss account and credit head office account","credit cash and debit profit and loss account","credit profit and loss account and debit head office account"]', 1, 'The branch should debit profit and loss account and credit head office account.', true, '2026-10-12 22:00:07.813', '2026-10-12 22:00:07.813', null, null, null, 'To account for expenses paid by head office on behalf of the branch, the branch should', '["debit head office account and credit cash","<b>debit profit and loss account and credit head office account</b>","credit cash and debit profit and loss account","credit profit and loss account and debit head office account"]', 'The branch should <b>debit profit and loss account and credit head office account</b>.', '{"bold":["debit profit and loss account and credit head office account"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a8cd03e0-fc3d-4ed5-b93d-90f9c17f3267', 'Yoruba', 'JAMB', null, 2002, null, 'Ìwé Ojú Òjúpá, apá kìíní ni ìbéèrè 26-28 dá lé. Nínú ìtàn Oríkò, kí ni Òrúnmìlà fì obì aláwè-mèta tí ó gbà lòwò Jégéjégé ÿe?', null, '["Ó fi bò ifá","Ó fi lérí ifá","Ó fi ÿe alejo","Ó fi rán alejo."]', 1, 'Ó fi lérí ifá ni Òrúnmìlà fi obì aláwè-mèta ÿe.', true, '2026-10-13 13:22:39.453', '2026-10-13 13:22:39.453', null, null, null, 'Ìwé Ojú Òjúpá, apá kìíní ni ìbéèrè 26-28 dá lé. Nínú ìtàn Oríkò, kí ni Òrúnmìlà fì obì aláwè-mèta tí ó gbà lòwò Jégéjégé ÿe?', '["Ó fi bò ifá","Ó fi lérí ifá","Ó fi ÿe alejo","Ó fi rán alejo."]', 'Ó fi lérí ifá ni Òrúnmìlà fi obì aláwè-mèta ÿe.', '{"bold":["Ó fi lérí ifá"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a8ce443a-367a-4a8e-a8da-6364c1d9acf2', 'Chemistry', 'JAMB', null, 2026, null, 'The number of orbitals in a p-subshell is:', null, '["1","2","3","5"]', 2, 'A p-subshell has 3 orbitals (px, py, pz).', true, '2026-09-12 11:35:58.934', '2026-09-12 11:35:58.934', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a8d18e24-6f38-4651-b0ae-1d9ceedafaf1', 'Biology', 'JAMB', null, 2001, null, 'Which of the following organisms does not exist as a single free living cell?', null, '["volvox","amoeba","chlamydomonas","paramecium"]', 0, 'Volvox exists as a colony of cells, not as a single free-living cell.', true, '2026-10-12 20:59:27.858', '2026-10-12 20:59:27.858', null, null, null, 'Which of the following organisms does not exist as a single free living cell?', '["volvox","amoeba","chlamydomonas","paramecium"]', 'Volvox exists as a colony of cells, not as a single free-living cell.', '{"bold":["Volvox"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a8d8cf2b-04c6-4a58-958d-3e4f5ea14695', 'English Language', 'JAMB', null, 2024, null, 'Choose the option opposite in meaning to the word or phrase in italics: Adewale''s arrival always triggers a media frenzy', null, '["excitement","agitation","calm","violence"]', 2, '"Frenzy" means wild excitement; the opposite is "calm."', true, '2026-09-18 09:43:02.88', '2026-09-18 09:43:02.88', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a8dce15f-8f14-4dc5-bb0f-4850dcada247', 'Literature in English', 'JAMB', null, 2026, null, 'Which historical reality makes the poem''s message most urgent?', null, '["technological innovation","the fading of indigenous languages","rise of urbanization","climate migration"]', 1, 'The fading of indigenous languages makes the message urgent.', true, '2026-09-12 11:10:41.447', '2026-09-12 11:10:41.447', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a8ded3ef-167e-486c-8a56-c72a49fc26a2', 'Literature in English', 'JAMB', null, 2026, null, 'A tragic hero, according to the Aristotelian precept must be', null, '["a noble character with hubris","a lowly character who suddenly stumbles on some fortune","a king with deep affection for his subjects","a central character after whom the play is named"]', 0, 'A tragic hero is a noble character with hubris.', true, '2026-09-12 11:07:29.209', '2026-09-12 11:07:29.209', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a8e52f51-6f95-442b-8754-65392e893ce9', 'Financial Accounting', 'UTME', null, 2004, null, 'Given: N Liabilities 23 700 Current 20 300 Fixed 64 500. What is the capital introduced by the proprietor?', 'https://res.cloudinary.com/kwi1uv0g/image/upload/v1791841604/questions/o1ziwxaskjpq37epz9dv.jpg', '["N40 800","N61 100","N88 200","N108 500"]', 1, 'Capital Introduced: Current Asset 20300 + Fixed Assets 64500 = 84800. Less Liabilities 23700 = 61100.', true, '2026-10-12 22:00:01.754', '2026-10-12 22:00:01.754', null, null, null, 'Given: N Liabilities 23 700 Current 20 300 Fixed 64 500. What is the capital introduced by the proprietor?', '["N40 800","<b>N61 100</b>","N88 200","N108 500"]', 'Capital Introduced: Current Asset 20300 + Fixed Assets 64500 = 84800. Less Liabilities 23700 = <b>61100</b>.', '{"bold":["61100"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a9136888-c15b-4089-b34d-4d0f0c1db1bd', 'English Language', 'JAMB', null, 2007, null, '<u>Beads</u> of sweat ran down Ngozi''s armpit.', null, '["pounds","springs","rivulets","pools"]', 2, 'Beads = rivulets.', true, '2026-10-24 01:04:09.231', '2026-10-24 01:04:09.231', null, null, null, '<u>Beads</u> of sweat ran down Ngozi''s armpit.', '["pounds","springs","<u>rivulets</u>","pools"]', '<b>Beads</b> = <b>rivulets</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a921d0ab-6b72-4acd-9f4d-733e177f5adf', 'Literature in English', 'JAMB', null, 2026, null, 'A story not based on fact and reality is', null, '["Myth","Legend","Pasquinde","Love story"]', 0, 'A myth is a story not based on fact and reality.', true, '2026-09-12 11:10:48.045', '2026-09-12 11:10:48.045', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a921f316-847d-4ec0-8160-16ef5c22b741', 'Economics', 'JAMB', null, 2026, null, 'If a firm can sell 30,000 units of product A at #10 per unit and 5,000 at #8, then', null, '["the price elasticity of demand is 0.44","A is a complementary goods","the price elasticity of demand is 2.25","A is an inferior good"]', 0, 'Price elasticity of demand = % change in quantity / % change in price. % change in quantity = (5000 - 30000)/30000 × 100 = -83.33%. % change in price = (8 - 10)/10 × 100 = -20%. PED = -83.33 / -20 = 4.17. However, the options are 0.44 and 2.25. Using the arc elasticity formula: PED = [(5000-30000)/((30000+5000)/2)] / [(8-10)/((10+8)/2)] = (-25000/17500) / (-2/9) = -1.4286 / -0.2222 = 6.43. The closest option in the document is 0.44, which may be a typo. Based on the document, the answer is (A) 0.44.', true, '2026-09-10 10:42:56.202', '2026-09-10 10:42:56.202', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a946ad01-d84c-4996-94a1-a48f16323932', 'Biology', 'JAMB', null, 2011, null, 'I. Parasitism - Sundew II. Autotrophism - Amoeba III. Saprophytism - Alga IV. Heterotrophism - Agama. Which of the above modes of nutrition is correctly matched with the organism that exhibits it?', null, '["II","III","IV","I"]', 2, 'Heterotrophism is correctly matched with Agama.', true, '2026-10-12 20:59:42.305', '2026-10-12 20:59:42.305', null, null, null, 'I. Parasitism - Sundew II. Autotrophism - Amoeba III. Saprophytism - Alga IV. Heterotrophism - Agama. Which of the above modes of nutrition is correctly matched with the organism that exhibits it?', '["II","III","IV","I"]', 'Heterotrophism is correctly matched with Agama.', '{"bold":["Heterotrophism"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a9479573-5251-4b01-935f-1bcf354c2687', 'Physics', 'JAMB', null, 2026, null, 'A constant force of 40N acting on a body initially at rest gives an acceleration of 0.1ms⁻² for 4s. Calculate the work done by the force.', null, '["8J","10J","32J","160J"]', 2, 'Distance s = ½at² = ½ × 0.1 × 16 = 0.8m. Work = Fs = 40 × 0.8 = 32J.', true, '2026-09-10 10:56:46.062', '2026-09-10 10:56:46.062', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a94ae1c9-9920-48cd-bb27-3fcac6de1705', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. I had to make my way through the <u>throng</u> of people in the church.', null, '["group","crowd","gathering","theme"]', 1, 'Throng = crowd.', true, '2026-10-24 01:04:08.535', '2026-10-24 01:04:08.535', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. I had to make my way through the <u>throng</u> of people in the church.', '["group","<u>crowd</u>","gathering","theme"]', '<b>Throng</b> = <b>crowd</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a94f0767-ccdf-43b5-a68c-64817bd25e71', 'Government', 'JAMB', null, 2026, null, 'Which Nigerian leader played a significant role in mediating peace talks during the Liberian civil war?', null, '["Olusegun Obasanjo","Muhammadu Buhari","Goodluck Jonathan","Ibrahim Babangida"]', 3, 'Ibrahim Babangida played a significant role in mediating peace during the Liberian civil war.', true, '2026-09-12 11:24:28.641', '2026-09-12 11:24:28.641', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a956edd7-ab78-40b4-8394-c985f81f69e3', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. I wonder what will be left of his essay when the <u>extraneous</u> material is deleted.', null, '["main","relevant","erroneous","superfluous"]', 3, 'Extraneous = superfluous.', true, '2026-10-24 01:01:51.24', '2026-10-24 01:01:51.24', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. I wonder what will be left of his essay when the <u>extraneous</u> material is deleted.', '["main","relevant","erroneous","<u>superfluous</u>"]', '<b>Extraneous</b> = <b>superfluous</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a9583d40-88ac-4562-94f9-442b59727fee', 'Financial Accounting', 'UTME', null, 2004, null, 'Mr. Bassey purchased a motor vehicle for use in his business and debited the purchases account with the same value. This is an error of', null, '["omission","principle","commission","original entry"]', 1, 'Items that should appear under the purchase account are items bought for re-sale and not fixed assets like motor vehicle. The error is an error of principle.', true, '2026-10-12 22:00:01.902', '2026-10-12 22:00:01.902', null, null, null, 'Mr. Bassey purchased a motor vehicle for use in his business and debited the purchases account with the same value. This is an error of', '["omission","<b>principle</b>","commission","original entry"]', 'Items that should appear under the purchase account are items bought for re-sale and not fixed assets like motor vehicle. The error is an <b>error of principle</b>.', '{"bold":["error of principle"],"italic":[],"underline":[],"fillBlanks":[]}');
