insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a967f9c3-ec0f-4d5c-99e9-b880865283e7', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Everyone''s condition was <u>appalling</u>.', null, '["simple","cloudy","pleasant","complex"]', 2, 'Appalling = horrifying; opposite = pleasant.', true, '2026-10-24 07:21:30.222', '2026-10-24 07:21:30.222', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Everyone''s condition was <u>appalling</u>.', '["simple","cloudy","pleasant","complex"]', 'Appalling = horrifying; opposite = pleasant.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a97b900b-1791-46a0-aa63-df4e4ad6bc29', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The refugees were received at the <u>transit</u> camp.', null, '["permanent","passage","temporary","nearby"]', 0, 'Transit = temporary; opposite = permanent.', true, '2026-10-24 07:21:29.02', '2026-10-24 07:21:29.02', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The refugees were received at the <u>transit</u> camp.', '["permanent","passage","temporary","nearby"]', 'Transit = temporary; opposite = permanent.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a97cc109-159f-414a-b0d1-1e2d18b008a9', 'Physics', 'JAMB', null, 2004, null, 'X-rays can be used in the study of crystal structures because they', null, '["Have an extremely short wavelength","Have a very long reaching wavelength","Are very fast","Are invisible."]', 0, 'X-ray wavelengths are comparable to the spacing between atoms in a crystal, so crystals diffract them.', true, '2026-10-12 19:15:59.409', '2026-10-12 19:15:59.409', null, null, null, 'X-rays can be used in the study of crystal structures because they', '["Have an extremely short wavelength","Have a very long reaching wavelength","Are very fast","Are invisible."]', 'X-ray wavelengths are comparable to the spacing between atoms in a crystal, so crystals diffract them.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a97d4a21-0326-40c3-b5b9-7ff6d1360366', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'What did Gehazi deceitfully receive from Naaman?', null, '["two talents of silver and two festal garments","two talents silver and two shekels of gold","two festal garments and two talents of gold","two thousand shekels and two festal garments"]', 0, '2 Kings 5:22-23 records Gehazi pursuing Naaman and asking for a talent of silver and two changes of garments, but Naaman urged him to take two talents of silver and two changes of garments.', true, '2026-09-09 17:18:26.95', '2026-09-09 17:18:26.95', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a9899593-b910-497e-b0f6-27028eaa74bd', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). Yahaya hardly knows on which side his <u>bread is buttered</u> in the matter.', null, '["where his interest lies","what he must do","whom to contact for help","where he should go"]', 0, '''Know which side one''s bread is buttered'' = know where interest lies.', true, '2026-10-24 01:04:19.539', '2026-10-24 01:04:19.539', null, null, null, '(Choose the most appropriate interpretation). Yahaya hardly knows on which side his <u>bread is buttered</u> in the matter.', '["<u>where his interest lies</u>","what he must do","whom to contact for help","where he should go"]', '''<b>Know which side one''s bread is buttered</b>'' = <b>know where interest lies</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a98f5162-3129-48be-8ca1-4e5dd96e7573', 'Christian Religious Studies', 'JAMB', null, 2026, null, '''In a short time, you think to make me a Christian?'' Who said this statement?', null, '["Claudius Lysias","Felix the governor","King Agrippa","Festus the governor"]', 2, 'King Agrippa said this to Paul after his defense.', true, '2026-09-12 10:41:28.165', '2026-09-12 10:41:28.165', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a9985933-a5f5-4d83-9ded-deaa27f4fe8d', 'Biology', 'JAMB', null, 2026, null, 'The outer layer of the kidney where the Bowman''s capsules are found is the', null, '["Cortex","Pelvis","Medulla","Pyramid"]', 0, 'The outer layer of the kidney where the Bowman''s capsules are found is the cortex. The renal cortex is the outer region containing the renal corpuscles (Bowman''s capsules and glomeruli) and the convoluted tubules. The medulla is the inner region with the loops of Henle and collecting ducts. The renal pelvis is the funnel-shaped structure collecting urine. Pyramids are the conical structures in the medulla. The cortex is the site of blood filtration, containing approximately 1 million nephrons.', true, '2026-09-09 03:19:02.721', '2026-09-09 03:19:02.721', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a99b0960-c878-4a7d-a523-f83f73408244', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). In their desire to impress their friends and relatives, many young workers <u>bite off more than they can chew</u> in terms of financial obligations.', null, '["have more money than sense","eat more than they can digest properly","spend too much money on food","care too much for their relatives","take on more responsibility than they can afford"]', 4, '''Bite off more than you can chew'' = take on too much.', true, '2026-10-24 01:02:01.741', '2026-10-24 01:02:01.741', null, null, null, '(Choose the most appropriate interpretation). In their desire to impress their friends and relatives, many young workers <u>bite off more than they can chew</u> in terms of financial obligations.', '["have more money than sense","eat more than they can digest properly","spend too much money on food","care too much for their relatives","<u>take on more responsibility than they can afford</u>"]', '''<b>Bite off more than you can chew</b>'' = <b>take on too much</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a9b01e15-10c6-4294-b2a6-b0b29907a69a', 'Literature in English', 'JAMB', null, 2026, null, 'The narrative technique predominantly used in the novel is', null, '["Omniscient narration","Epistolary narration","Stream of consciousness","Dramatic monologue"]', 0, 'Omniscient narration is predominantly used.', true, '2026-09-12 11:11:19.585', '2026-09-12 11:11:19.585', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a9d1cdc5-a348-49b8-baf9-8c6f93d200eb', 'Biology', 'JAMB', null, 2004, null, 'All living cells require water because it', null, '["is a medium for all metabolic reactions","is a medium that neutralizes acids in cells","is the main source of energy for the cells","prevents the development of diseases in cell"]', 0, 'Water is the medium for all metabolic reactions.', true, '2026-10-12 20:59:34.812', '2026-10-12 20:59:34.812', null, null, null, 'All living cells require water because it', '["is a medium for all metabolic reactions","is a medium that neutralizes acids in cells","is the main source of energy for the cells","prevents the development of diseases in cell"]', 'Water is the medium for all metabolic reactions.', '{"bold":["is the medium for all metabolic reactions"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a9d3fd67-3a35-421c-bd1e-aa5e79f59224', 'Literature in English', 'JAMB', null, 2026, null, 'A poem of 14 lines, often with a set rhyme scheme, is a/an', null, '["ode","elegy","sonnet","ballad"]', 2, 'A 14-line poem is a sonnet.', true, '2026-09-12 11:13:48.886', '2026-09-12 11:13:48.886', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a9dbf5fe-36e9-454b-bdbf-a582fc5cfc00', 'Physics', 'JAMB', null, 1989, null, 'Two insulated charged spheres of different sizes and carrying opposite charges are connected together by a metallic conductor. Current will flow from one sphere to the other until both spheres', null, '["Carry the same magnitude and sign of charge.","Are at the same potential.","Are at the same temperature.","Are of the same size."]', 1, 'Charge flows from the higher potential to the lower until the potentials are equal.', true, '2026-10-12 19:15:29.741', '2026-10-12 19:15:29.741', null, null, null, 'Two insulated charged spheres of different sizes and carrying opposite charges are connected together by a metallic conductor. Current will flow from one sphere to the other until both spheres', '["Carry the same magnitude and sign of charge.","Are at the same potential.","Are at the same temperature.","Are of the same size."]', 'Charge flows from the higher potential to the lower until the potentials are equal.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a9f85511-d06d-4129-936c-b5fbb2330348', 'Yoruba', 'JAMB', null, 2002, null, 'Orí loníye, édá láyànmò. Àkúnléyàn òun ni àdáyébá. A délé ayé tán ojú p kán gbogbo wa; Orí níí ýatökùn fúnni. Ìgbà ti ara èniyàn kò yá, Òògùn ló lójò kan ìpònjú, Orí ló lójò gbogbo. Orí çni làwùre çni; Orí ló yç kénìyàn ó sìn. Báa bá wálé ayé táa lówó lòwò, Àyànmò ni. Bí a sì wà lókèèrè, táyé p yò wa wò níkòrò, ßebí orí ló sohun gbogbo. Ohun ti Táyé p ýe tó fi lówó lòwò, Òun ni Kèhindé ýe tó dolòsì. Ç má fõrõ àyànmò wéra. Nítori ohun ti a yàn, õtõõtõ ni, Báyé bá yçni, ýebí orí inú çni ni. Báa bá dènìyàn plá, ohun táa dì mò kádàrà ni. Ohun ti a rù lórí, látòde õrun wá ni. Kò sééyàn ti í paýò àgùntàn-án dà. Táyé bá ýelá tílá fi kó, Ténìyàn ýekàn tíkàn bá wêwù èjè Táyé náà bá tún taýò ìjímèrè bepo Ká rántí pé ohun táa mú wáyé látòde õrun ni Kò sëni pa Lágbájà, Kò sëni pa Lákàyègbè: Ó ti wà nínú àkòòlé rè ni. Orí jà ò joògùn Orí là bá máa bò lójò gbogbo Orí ni ààbò çni, Kò sórìjà ti p gbeni lèyin orí çni. Bénìyàn bá ní wàhálà, orí ni yóò ké sí. Máà bënìkan sò, Nítorí ènìyàn kò fëni fòrõ, à forí çni. Nīnū īlā 14-15, ohun ti akēwī sō nīpa Tāyé āti Kēhīndé nī pé', null, '["ēmō īyā kan nīwōn","orī ōkan sunwōn ju ēkējī lō","ākōōlē onīkālūkū, ōtōōtō nī","Tāyé kō lē ran Kēhīndé lōwō"]', 2, 'Ohun ti akēwī sō nīpa Tāyé āti Kēhīndé nī pé ākōōlē onīkālūkū, ōtōōtō nī.', true, '2026-10-13 13:22:38.088', '2026-10-13 13:22:38.088', null, null, null, 'Orí loníye, édá láyànmò. Àkúnléyàn òun ni àdáyébá. A délé ayé tán ojú p kán gbogbo wa; Orí níí ýatökùn fúnni. Ìgbà ti ara èniyàn kò yá, Òògùn ló lójò kan ìpònjú, Orí ló lójò gbogbo. Orí çni làwùre çni; Orí ló yç kénìyàn ó sìn. Báa bá wálé ayé táa lówó lòwò, Àyànmò ni. Bí a sì wà lókèèrè, táyé p yò wa wò níkòrò, ßebí orí ló sohun gbogbo. Ohun ti Táyé p ýe tó fi lówó lòwò, Òun ni Kèhindé ýe tó dolòsì. Ç má fõrõ àyànmò wéra. Nítori ohun ti a yàn, õtõõtõ ni, Báyé bá yçni, ýebí orí inú çni ni. Báa bá dènìyàn plá, ohun táa dì mò kádàrà ni. Ohun ti a rù lórí, látòde õrun wá ni. Kò sééyàn ti í paýò àgùntàn-án dà. Táyé bá ýelá tílá fi kó, Ténìyàn ýekàn tíkàn bá wêwù èjè Táyé náà bá tún taýò ìjímèrè bepo Ká rántí pé ohun táa mú wáyé látòde õrun ni Kò sëni pa Lágbájà, Kò sëni pa Lákàyègbè: Ó ti wà nínú àkòòlé rè ni. Orí jà ò joògùn Orí là bá máa bò lójò gbogbo Orí ni ààbò çni, Kò sórìjà ti p gbeni lèyin orí çni. Bénìyàn bá ní wàhálà, orí ni yóò ké sí. Máà bënìkan sò, Nítorí ènìyàn kò fëni fòrõ, à forí çni. Nīnū īlā 14-15, ohun ti akēwī sō nīpa Tāyé āti Kēhīndé nī pé', '["ēmō īyā kan nīwōn","orī ōkan sunwōn ju ēkējī lō","ākōōlē onīkālūkū, ōtōōtō nī","Tāyé kō lē ran Kēhīndé lōwō"]', 'Ohun ti akēwī sō nīpa Tāyé āti Kēhīndé nī pé ākōōlē onīkālūkū, ōtōōtō nī.', '{"bold":["ākōōlē onīkālūkū, ōtōōtō nī"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a9fd171e-83d8-4180-8166-50fbb40f1c8e', 'Financial Accounting', 'UTME', null, 2003, null, 'Given: I. the consolidated revenue fund balance b/d N650 000 II. Issues from contingency amounted to N240 000 III. Amount transferred to contingency fund is N210 000. What is the consolidated revenue fund balance?', null, '["N1 100 000","N680 000","N440 0000","N410 000"]', 1, 'Consolidated Revenue b/d 650,000 + Transfer from contingency 240,000 = 890,000. Less Transfer to Contingency 210,000 = 680,000.', true, '2026-10-12 22:00:01.212', '2026-10-12 22:00:01.212', null, null, null, 'Given: I. the consolidated revenue fund balance b/d N650 000 II. Issues from contingency amounted to N240 000 III. Amount transferred to contingency fund is N210 000. What is the consolidated revenue fund balance?', '["N1 100 000","<b>N680 000</b>","N440 0000","N410 000"]', 'Consolidated Revenue b/d 650,000 + Transfer from contingency 240,000 = 890,000. Less Transfer to Contingency 210,000 = <b>680,000</b>.', '{"bold":["680,000"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a9fdbfb4-8b30-4f24-919b-488fc600e885', 'Economics', 'JAMB', null, 2026, null, 'Which of the following is used to describe a payment representing a surplus in excess of transfer earnings?', null, '["interest rates","opportunity costs","economic rent","indirect costs","wages"]', 2, 'Economic rent is the payment made to a factor of production that exceeds its transfer earnings (the minimum amount needed to keep the factor in its current use). It represents a surplus above what is necessary to keep the factor employed in its present occupation. For example, if a worker would accept N50,000 to do a job but is paid N80,000, the economic rent is N30,000.', true, '2026-09-10 10:41:19.427', '2026-09-10 10:41:19.427', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('a9fe7040-ce8f-46a2-8dfc-a8e8591e485e', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. There was an infectious <u>gaiety</u> in the children''s character.', null, '["exhilaration","depression","moodiness","desperation"]', 0, 'Gaiety = exhilaration.', true, '2026-10-24 01:04:11.384', '2026-10-24 01:04:11.384', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. There was an infectious <u>gaiety</u> in the children''s character.', '["<u>exhilaration</u>","depression","moodiness","desperation"]', '<b>Gaiety</b> = <b>exhilaration</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('aa00354c-bcef-40fc-bf6a-08e68f5d1c46', 'Government', 'JAMB', null, 2026, null, 'The military head of state that used the title of president was', null, '["Gen. Muhammed Buhari","Gen. Olusegun Obasanjo","Maj. Gen. Ibrahim Babangida","Brig. Muritala"]', 2, 'Major General Ibrahim Babangida used the title of President. He was the first military head of state in Nigeria to adopt the title of President, which he used throughout his regime (1985-1993). Other military leaders used titles such as Head of State. Babangida''s use of the title President was part of his attempt to give his administration a civilian appearance.', true, '2026-09-10 10:45:05.609', '2026-09-10 10:45:05.609', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('aa02e5d8-beff-478c-a526-c27fdde6bb3d', 'Biology', 'JAMB', null, 2013, null, 'The behavioural adaptation in social insects could best be described as', null, '["Parasitism","Commensalism","Symbiosis","Saprophytism"]', 2, 'The behavioural adaptation in social insects is symbiosis.', true, '2026-10-12 20:59:48.5', '2026-10-12 20:59:48.5', null, null, null, 'The behavioural adaptation in social insects could best be described as', '["Parasitism","Commensalism","Symbiosis","Saprophytism"]', 'The behavioural adaptation in social insects is symbiosis.', '{"bold":["symbiosis"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('aa07c88a-099a-40a8-bd47-bb90442cd016', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. He shared his room with a person whose behaviour was quite <u>nauseating</u>.', null, '["disrespectful","disgraceful","discouraging","disgusting"]', 3, 'Nauseating = disgusting.', true, '2026-10-24 01:04:04.884', '2026-10-24 01:04:04.884', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. He shared his room with a person whose behaviour was quite <u>nauseating</u>.', '["disrespectful","disgraceful","discouraging","<u>disgusting</u>"]', '<b>Nauseating</b> = <b>disgusting</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('aa0b5ebe-c674-4cde-aa02-624359eeaf44', 'Economics', 'JAMB', null, 2026, null, 'The multiplier is always the reciprocal of', null, '["MPC","MPS","APC","APS"]', 1, 'The multiplier is always the reciprocal of MPS (Marginal Propensity to Save). Multiplier = 1 / MPS = 1 / (1 - MPC). The multiplier measures the change in national income resulting from a change in autonomous spending. A higher MPS means a lower multiplier because more income is saved (leaked) rather than spent. The APC and APS are average propensities, not used in the multiplier formula.', true, '2026-09-10 10:42:00.235', '2026-09-10 10:42:00.235', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('aa0cba0f-3e3b-4062-9bb1-9213ae5419f4', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Before the cock crowed, Peter denied Jesus three times. Who was the first person to recognize him?', null, '["a bystander","a maid","one of the rulers","the high Priest"]', 1, 'A maid was the first person to recognize Peter. As Peter sat in the courtyard of the high priest, a maid came to him and said, ''You also were with Jesus the Galilean.''', true, '2026-09-12 09:46:11.645', '2026-09-12 09:46:11.645', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('aa208a2c-75b3-4e7a-9c57-823b9509921c', 'Biology', 'JAMB', null, 2003, null, 'Insects are considered the most successful among the invertebrates because they', null, '["possess exoskeletons","survive in various environmental conditions","have wings for flight","possess the ability to change their forms"]', 1, 'Insects exhibit remarkable adaptability, allowing them to survive in diverse and extreme environments.', true, '2026-10-12 20:05:10.861', '2026-10-12 20:05:10.861', null, null, null, 'Insects are considered the most successful among the invertebrates because they', '["possess exoskeletons","survive in various environmental conditions","have wings for flight","possess the ability to change their forms"]', 'Insects exhibit remarkable adaptability, allowing them to survive in diverse and extreme environments.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('aa3788ec-19b0-4f93-81c1-1a28eec7b1c4', 'English Language', 'JAMB', null, 2024, null, 'Ten miles ______ a great distance. (I) is (II) was (III) were (IV) are', null, '["I","I&II","were","are"]', 1, '"Ten miles" is treated as a singular unit, so "is" and "was" are both correct.', true, '2026-09-18 09:43:02.33', '2026-09-18 09:43:02.33', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('aa4323f5-7906-4da9-b682-c519a913744c', 'Biology', 'JAMB', null, 2003, null, 'The breakdown of fats and oils into simpler absorbable compounds is catalyzed by the group of enzymes called', null, '["lipases","hydrolases","amylases","peptidases"]', 0, 'Lipases are specific enzymes that catalyze the breakdown of lipids, fats, and oils.', true, '2026-10-12 20:05:11.209', '2026-10-12 20:05:11.209', null, null, null, 'The breakdown of fats and oils into simpler absorbable compounds is catalyzed by the group of enzymes called', '["lipases","hydrolases","amylases","peptidases"]', 'Lipases are specific enzymes that catalyze the breakdown of lipids, fats, and oils.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('aa446761-b747-4d0d-a667-96f0f3220b95', 'Physics', 'JAMB', null, 2026, null, 'The horizontal component of Earth''s magnetic field is given by', null, '["B sin θ","B cos θ","B tan θ","B sec θ"]', 1, 'The horizontal component of Earth''s magnetic field is given by B cos θ, where B is the total magnetic field and θ is the angle of dip (inclination). The vertical component is B sin θ.', true, '2026-09-10 10:56:39.944', '2026-09-10 10:56:39.944', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('aa56e65f-aaef-4ffd-9152-1f01cb5f655d', 'English Language', 'JAMB', null, 2024, null, '13', null, '["dividend","progress","gain","profit"]', 3, 'During a strike, the company makes no profit.', true, '2026-09-18 10:17:48.868', '2026-09-18 10:17:48.868', '274e150d-fca1-4c72-9c33-e5e119534874', 13, 'CLOZE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('aa58426b-0433-41d0-9c19-e41ebb3024f5', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. What he received from the visitor was <u>invaluable</u>.', null, '["priceless","worthless","valueless","costly"]', 0, 'Invaluable = priceless.', true, '2026-10-24 01:03:57.626', '2026-10-24 01:03:57.626', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. What he received from the visitor was <u>invaluable</u>.', '["<u>priceless</u>","worthless","valueless","costly"]', '<b>Invaluable</b> = <b>priceless</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('aa5eee47-4ac9-4705-993d-af77817e2d57', 'English Language', 'JAMB', null, 2007, null, 'The Federal Government has <u>__________</u> child trafficking.', null, '["projected","prescribed","proscribed","postulated"]', 2, 'Correct spelling and meaning: proscribed.', true, '2026-10-24 07:21:36.319', '2026-10-24 07:21:36.319', null, null, null, 'The Federal Government has <u>__________</u> child trafficking.', '["projected","prescribed","proscribed","postulated"]', 'Correct spelling and meaning: proscribed.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('aa7c50f7-e537-491d-9d94-ec4988409153', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). What you will find in the book is <u>a bird''s-eye view</u> of the subject.', null, '["a detailed account","a balanced discussion","a biased treatment","a general survey"]', 3, '''A bird''s-eye view'' = general survey.', true, '2026-10-24 01:04:22.01', '2026-10-24 01:04:22.01', null, null, null, '(Choose the most appropriate interpretation). What you will find in the book is <u>a bird''s-eye view</u> of the subject.', '["a detailed account","a balanced discussion","a biased treatment","<u>a general survey</u>"]', '''A <b>bird''s-eye view</b>'' = <b>general survey</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('aa7dbe5c-8d7f-45a3-8e8c-a53035e2b785', 'Physics', 'JAMB', null, 1987, null, 'What type of reaction is represented by the following scheme? ₁²X + ₁²Y → ₂³Z + ₀¹n + energy', null, '["Fusion reaction","Fission reaction","Chain reaction","Radioactive decay."]', 0, 'Two light nuclei combine into a heavier nucleus with release of energy. That is nuclear fusion.', true, '2026-10-12 19:15:26.568', '2026-10-12 19:15:26.568', null, null, null, 'What type of reaction is represented by the following scheme? ₁²X + ₁²Y → ₂³Z + ₀¹n + energy', '["Fusion reaction","Fission reaction","Chain reaction","Radioactive decay."]', 'Two light nuclei combine into a heavier nucleus with release of energy. That is nuclear fusion.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
