insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('aaa0c603-ec8d-46b7-bb66-0fbf16851f39', 'Biology', 'JAMB', null, 2010, null, 'The main distinguishing features between the soldier termite and other members of the caste are the', null, '["presence of wings possession of a small head and large thorax","presence of wings possession of a large thorax and a small head","absence of wings possession of strong mandibles and a large head","absence of wings possession of big head and the absence of mandibles"]', 2, 'Soldier termites lack wings and have strong mandibles and a large head.', true, '2026-10-12 20:59:41.445', '2026-10-12 20:59:41.445', null, null, null, 'The main distinguishing features between the soldier termite and other members of the caste are the', '["presence of wings possession of a small head and large thorax","presence of wings possession of a large thorax and a small head","absence of wings possession of strong mandibles and a large head","absence of wings possession of big head and the absence of mandibles"]', 'Soldier termites lack wings and have strong mandibles and a large head.', '{"bold":["lack wings and have strong mandibles and a large head"],"italic":[],"underline":[],"fillBlanks":[]}');
