insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('aac22c92-cec6-4a2d-b992-546377a1071d', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'The three sons of Saul who lost their lives on Mount Gilboa were', null, '["Malchishua, Jonathan & Caleb","Jonathan, Ishboleth and Malchishua","Jonathan, Abinadab and Malchishua","Ishbosheth, Malchishua and Abinadab"]', 2, 'Jonathan, Abinadab, and Malchishua died with Saul at Gilboa.', true, '2026-09-12 10:42:02.669', '2026-09-12 10:42:02.669', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('aac82701-4249-4be6-b4ab-18ccf291c602', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Nigeria, like most other African countries is <u>predominantly</u> agricultural.', null, '["mainly","certainly","entirely","undoubtedly","superficially"]', 0, 'Predominantly = mainly.', true, '2026-10-24 01:03:53.866', '2026-10-24 01:03:53.866', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Nigeria, like most other African countries is <u>predominantly</u> agricultural.', '["<u>mainly</u>","certainly","entirely","undoubtedly","superficially"]', '<b>Predominantly</b> = <b>mainly</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('aaca66d1-6be8-4420-a95b-c9f70821958b', 'Physics', 'JAMB', null, 2026, null, 'Which equation/expression is wrong?', null, '["Force is directly proportional to acceleration","Force is inversely proportional to time interval during motion","Mass of Body is directly proportional to The Force applied on it","Change in momentum varies directly with force","all of above"]', 1, 'The statement that force is inversely proportional to time interval during motion is wrong. Force is not inversely proportional to time. Force is directly proportional to acceleration (F=ma) and to the rate of change of momentum (F=Δp/t).', true, '2026-09-10 10:56:44.225', '2026-09-10 10:56:44.225', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('aacc785c-ccd7-4617-a986-87cfcf05742f', 'General Mathematics', 'JAMB', null, 2026, null, 'The locus of points which are equidistant from two fixed points is', null, '["a line","a circle","the perpendicular bisector","the angle bisector"]', 2, 'The locus is the perpendicular bisector of the line joining the two points.', true, '2026-09-12 11:43:54.553', '2026-09-12 11:43:54.553', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('aad703a9-37eb-4c09-a834-84eaee3e76ae', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. We should discourage further investment in <u>existing</u> factories.', null, '["productive","prosperous","prospective","precious"]', 2, 'Existing = current; opposite = prospective.', true, '2026-10-24 07:21:16.121', '2026-10-24 07:21:16.121', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. We should discourage further investment in <u>existing</u> factories.', '["productive","prosperous","prospective","precious"]', 'Existing = current; opposite = prospective.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('aaddaf13-0c07-48bd-af1d-c22b70f1bbfb', 'Physics', 'JAMB', null, 1994, null, 'To produce a parallel beam of light from a concave mirror, the distance at which the lamp should be placed from the mirror is equal to', null, '["The focal length","Two times the focal length","The distance of the image","Two times the radius of curvature."]', 0, 'A source at the principal focus sends out rays that become parallel after reflection from the mirror.', true, '2026-10-12 19:15:39.912', '2026-10-12 19:15:39.912', null, null, null, 'To produce a parallel beam of light from a concave mirror, the distance at which the lamp should be placed from the mirror is equal to', '["The focal length","Two times the focal length","The distance of the image","Two times the radius of curvature."]', 'A source at the principal focus sends out rays that become parallel after reflection from the mirror.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('aae676b3-9dba-4527-943e-7ff1e5ebe6e7', 'English Language', 'JAMB', null, 2024, null, 'The main challenge Bepo encountered in the story is?', null, '["resistance to educational reforms","financial difficulties","personal health issues","family problems"]', 0, 'Bepo''s main challenge was resistance to his educational reforms.', true, '2026-09-18 09:34:04.041', '2026-09-18 09:34:04.041', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('aae8c091-09ba-4936-b5c0-266640bdd4da', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). The criminal didn''t <u>bat an eyelid</u> when the judge pronounced the sentence.', null, '["displayed no understanding whatsoever","was bold and insensitive","moved none of his eyelids","showed no emotion or surprise"]', 3, '''Didn''t bat an eyelid'' = showed no emotion/surprise.', true, '2026-10-24 01:02:07.653', '2026-10-24 01:02:07.653', null, null, null, '(Choose the most appropriate interpretation). The criminal didn''t <u>bat an eyelid</u> when the judge pronounced the sentence.', '["displayed no understanding whatsoever","was bold and insensitive","moved none of his eyelids","<u>showed no emotion or surprise</u>"]', '''<b>Didn''t bat an eyelid</b>'' = <b>showed no emotion/surprise</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('aaf9488d-de5b-4a16-addf-0d313e676f7b', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The hefty warder came in and all the prisoners <u>snuffed</u> out their cigarettes.', null, '["extinguished","put out","squeezed","put down"]', 0, 'Snuffed out = extinguished.', true, '2026-10-24 01:03:56.075', '2026-10-24 01:03:56.075', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The hefty warder came in and all the prisoners <u>snuffed</u> out their cigarettes.', '["<u>extinguished</u>","put out","squeezed","put down"]', '<b>Snuffed out</b> = <b>extinguished</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ab03319c-c05f-4e4b-bef1-bac49f76efd7', 'Chemistry', 'JAMB', null, 2026, null, 'Which of the following processes is endothermic?', null, '["Neutralization of acid and base","Dissolution of ammonium chloride in water","Combustion of methane","Formation of sodium chloride"]', 1, 'Dissolving ammonium chloride in water absorbs heat energy from surroundings, dropping temperature during dissolution.', true, '2026-09-09 17:12:48.814', '2026-09-09 17:12:48.814', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ab1a3ec0-9783-434f-a3b3-7f31e37998f5', 'General Mathematics', 'JAMB', null, 2026, null, 'The nth term of the sequence 3, 9, 27, 81,.... is', null, '["3 × 3ⁿ⁺¹","3 × 3ⁿ⁻¹","3 × 3ⁿ⁻²","3 × 3²ⁿ⁺¹"]', 1, 'Tn = 3 × 3ⁿ⁻¹ = 3ⁿ.', true, '2026-09-12 11:44:17.884', '2026-09-12 11:44:17.884', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ab1b1423-d6a7-4ee4-b571-b0a411a66369', 'Physics', 'JAMB', null, 1989, null, 'The function of a 5-A fuse included in a circuit supplying a household refrigerator with power is to keep the', null, '["Temperature of the refrigerator low and constant.","Current supplied to the refrigerator below 5 A","Voltage supply constant","Current supplied to the refrigerator constant and above 5 A."]', 1, 'The fuse wire melts and breaks the circuit if the current exceeds 5 A, so it protects the appliance.', true, '2026-10-12 19:15:30.01', '2026-10-12 19:15:30.01', null, null, null, 'The function of a 5-A fuse included in a circuit supplying a household refrigerator with power is to keep the', '["Temperature of the refrigerator low and constant.","Current supplied to the refrigerator below 5 A","Voltage supply constant","Current supplied to the refrigerator constant and above 5 A."]', 'The fuse wire melts and breaks the circuit if the current exceeds 5 A, so it protects the appliance.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ab1e2edd-715d-4be0-891e-3438fff1f502', 'Financial Accounting', 'UTME', null, 2003, null, 'Advertising expense incurred on a product in a business organization should be charged to', null, '["production department","sales department","administration department","purchases department"]', 1, 'Advertising expense is charged to the sales department.', true, '2026-10-12 22:00:00.372', '2026-10-12 22:00:00.372', null, null, null, 'Advertising expense incurred on a product in a business organization should be charged to', '["production department","<b>sales department</b>","administration department","purchases department"]', 'Advertising expense is charged to the <b>sales department</b>.', '{"bold":["sales department"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ab274e23-9721-41cb-992b-c90dceaf751f', 'Government', 'JAMB', null, 2026, null, 'Deconcentration of power means the', null, '["sharing of powers among tiers of government","creation of semi-autonomous units to govern other parts of a state","process of setting strategies or policies for the subsidiary territories in the state by putting recognized personnel in place","act of delegating powers and authority to component units that exist in a state"]', 2, 'Deconcentration is setting strategies for subsidiary territories by putting personnel in place.', true, '2026-09-12 11:24:57.057', '2026-09-12 11:24:57.057', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ab50c2f6-3e11-446d-8300-c98df4403094', 'Christian Religious Studies', 'JAMB', null, 2026, null, '''Have nothing to do with that righteous man, for I have suffered much over him today in a dream.'' This statement was made by Pilate''s wife during', null, '["the arrest of Jesus","Jesus'' betrayal","Jesus'' trial","Jesus'' crucifixion"]', 2, 'Pilate''s wife sent this message during Jesus'' trial.', true, '2026-09-12 10:41:27.729', '2026-09-12 10:41:27.729', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ab84f69b-9f1a-4504-9506-d6cf8bd5f773', 'General Mathematics', 'JAMB', null, 2026, null, 'Express 1/8 as a percentage', null, '["60%","62.5%","65%","67.5%"]', 1, '1/8 = 0.125 = 12.5%. Wait, the options are 60, 62.5, 65, 67.5. 1/8 = 12.5%, not in options. The question may be 5/8 = 62.5%. The answer is (B) 62.5%.', true, '2026-09-12 11:44:10.954', '2026-09-12 11:44:10.954', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ab87cf56-c5f5-4b12-b2e6-90665d1c1a9c', 'Biology', 'JAMB', null, 2026, null, 'A food chain always begins with a', null, '["Consumer","Decomposer","Producer","Primary consumer"]', 2, 'A food chain always begins with a producer (autotroph). Producers, such as green plants and algae, convert solar energy into chemical energy through photosynthesis. Consumers (including primary consumers) feed on producers or other organisms. Decomposers break down dead organic matter. Without producers, there would be no energy source for other organisms in the food chain. This represents the first trophic level in all food chains.', true, '2026-09-09 03:19:01.861', '2026-09-09 03:19:01.861', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ab8cf0b5-d1d7-43ed-85ed-cc0eff2eb986', 'English Language', 'JAMB', null, 2007, null, 'One of the <u>---</u> selective marking of errors.', null, '["school of thought suggests","schools of thought suggest","school of thoughts suggested","schools of thought suggests"]', 3, '''One of the schools of thought'' â†’ suggests.', true, '2026-10-24 01:04:27.224', '2026-10-24 01:04:27.224', null, null, null, 'One of the <u>---</u> selective marking of errors.', '["school of thought suggests","schools of thought suggest","school of thoughts suggested","<u>schools of thought suggests</u>"]', '''One of the <b>schools of thought</b>'' â†’ <b>suggests</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ab8cfee8-44c2-4c5a-b627-293dd752bf23', 'Biology', 'JAMB', null, 2026, null, 'The head of the femur fit into the', null, '["pleural cavity","glenoid cavity","acetabulum","odontoid process","pectoral girdle"]', 2, 'The head of the femur (thigh bone) fits into the acetabulum, a cup-shaped socket in the pelvic girdle. This ball-and-socket joint forms the hip joint, allowing a wide range of movement. The glenoid cavity is the socket in the scapula for the head of the humerus (shoulder joint). The pleural cavity is the space around the lungs. The odontoid process is part of the axis vertebra. The pectoral girdle connects the forelimbs to the axial skeleton. The acetabulum is deep and strong, supporting body weight during standing and movement.', true, '2026-09-09 03:18:33.527', '2026-09-09 03:18:33.527', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ab91b874-dd68-4154-907c-2b92fe8a6c00', 'Chemistry', 'JAMB', null, 2026, null, 'Butene can be distinguished from benzene by reaction with:', null, '["Hydrochloric acid","Bromine water","Potassium sulphate","Sodium hydroxide"]', 1, 'Alkenes like butene rapidly decolorize red-brown bromine water via addition, whereas aromatic benzene does not react without a catalyst.', true, '2026-09-09 17:12:47.248', '2026-09-09 17:12:47.248', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('abab225e-12b1-4f3b-8ce4-0eb84939e7da', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'During the voyage to Rome, some people thought that Paul was a god because', null, '["he caused rain to fall","an angel appeared to him","he was not harmed by a viper","he broke his chains easily"]', 2, 'Some people thought Paul was a god because he was not harmed by a viper. When he was gathering sticks for a fire, a viper bit his hand, but he shook it off into the fire and suffered no harm.', true, '2026-09-12 09:45:55.403', '2026-09-12 09:45:55.403', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('abb392f5-7cdb-405a-8b43-c78d62f8dfbf', 'Economics', 'JAMB', null, 2026, null, 'Which of the following business organization is allowed to raise capital by sales of shares to the public?', null, '["Partnership","Private limited liability company","Public limited liability company","Cooperative society"]', 2, 'Only public limited liability companies can sell shares to the public.', true, '2026-09-12 10:59:07.363', '2026-09-12 10:59:07.363', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('abb9ae9c-c01c-44da-89cc-58fec8972f19', 'Biology', 'JAMB', null, 2012, null, 'An example of a fruit that develops from a single carpel is', null, '["okro","tomato","bean","orange."]', 2, 'Bean develops from a single carpel.', true, '2026-10-12 20:59:44.893', '2026-10-12 20:59:44.893', null, null, null, 'An example of a fruit that develops from a single carpel is', '["okro","tomato","bean","orange."]', 'Bean develops from a single carpel.', '{"bold":["Bean"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('abbb721f-c5e0-438b-917d-f934ddc3a804', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The woman acted <u>courageously</u> when she was attacked by thieves.', null, '["shyly","fearlessly","timidly","carelessly"]', 1, 'Courageously = fearlessly.', true, '2026-10-24 01:01:46.214', '2026-10-24 01:01:46.214', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The woman acted <u>courageously</u> when she was attacked by thieves.', '["shyly","<u>fearlessly</u>","timidly","carelessly"]', '<b>Courageously</b> = <b>fearlessly</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('abd336eb-ce3d-4064-895b-f8b06d2a8471', 'Physics', 'JAMB', null, 2003, null, 'What does not drop through an open umbrella of silk material unless the inside of the umbrella is touched?', null, '["Osmotic pressure","Capillarity","Surface tension","Viscosity"]', 2, 'Surface tension makes the water surface act like a skin across the tiny holes in the silk, so rain does not pass through until it is disturbed by touching.', true, '2026-10-12 19:15:54.941', '2026-10-12 19:15:54.941', null, null, null, 'What does not drop through an open umbrella of silk material unless the inside of the umbrella is touched?', '["Osmotic pressure","Capillarity","Surface tension","Viscosity"]', 'Surface tension makes the water surface act like a skin across the tiny holes in the silk, so rain does not pass through until it is disturbed by touching.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('abe95b30-c418-4eec-ae15-a3557f3bc222', 'Chemistry', 'JAMB', null, 2026, null, 'A metallic oxide which reacts with both HCl and NaOH to give salt and water only can be classified as', null, '["an acidic oxide","a basic oxide","a neutral oxide","an amphoteric oxide"]', 3, 'An amphoteric oxide reacts with both acids and bases.', true, '2026-09-12 11:36:02.922', '2026-09-12 11:36:02.922', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('abebeab0-14aa-4bb9-a468-cbf9bc9e3763', 'Chemistry', 'JAMB', null, 2026, null, 'A gas occupies 240 cm³ at 300 K. What will be its volume at 450 K at constant pressure?', null, '["300 cm³","360 cm³","400 cm³","480 cm³"]', 1, 'Using Charles''s Law: V₁/T₁ = V₂/T₂. V₂ = 240 × (450/300) = 360 cm³.', true, '2026-09-12 11:35:47.274', '2026-09-12 11:35:47.274', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('abf09449-d45d-463b-b9c7-521d54e973de', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Amnon''s incest with Tamar marks the beginning of', null, '["the intrigues for succession to the throne","David''s popularity","the fame of Solomon''s wisdom","David''s love for Uriah''s wife"]', 0, 'This event began the succession intrigues in David''s family.', true, '2026-09-12 10:41:40.196', '2026-09-12 10:41:40.196', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('abf895be-334a-4ee2-9c06-47d4a06869b1', 'Physics', 'JAMB', null, 1986, null, 'Which of the following is true of magnetism?', null, '["Iron filings cling mainly round the ends of a bar magnet.","The freely suspended bar magnet comes to rest in the geographic north-south direction.","Like poles attract.","Lodestone is a non-magnetic oxide."]', 0, 'The magnetic strength is concentrated at the poles, so filings cluster there. A suspended magnet settles along the magnetic (not exactly geographic) meridian, like poles repel, and lodestone is a magnetic oxide of iron.', true, '2026-10-12 19:15:24.324', '2026-10-12 19:15:24.324', null, null, null, 'Which of the following is true of magnetism?', '["Iron filings cling mainly round the ends of a bar magnet.","The freely suspended bar magnet comes to rest in the geographic north-south direction.","Like poles attract.","Lodestone is a non-magnetic oxide."]', 'The magnetic strength is concentrated at the poles, so filings cluster there. A suspended magnet settles along the magnetic (not exactly geographic) meridian, like poles repel, and lodestone is a magnetic oxide of iron.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ac1a400f-529f-43b3-a081-8936d21321f8', 'Physics', 'JAMB', null, 1988, null, 'Which of the following factors affects the speed of sound in air?
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ac1ce94a-689e-434f-9f9b-44e61b25434b', 'Biology', 'JAMB', null, 0, null, 'answer the question above ', 'https://res.cloudinary.com/kwi1uv0g/image/upload/v1791839598/questions/qmgdftyuwsvxbg3i1sco.jpg', '["a","b","c","d"]', 2, 'Part I represents the cell wall, which is characteristic of plant cells but absent in animal cells.   Part II points to the cytoplasm (containing pyrenoids/organelles), which is common to both plant and animal cells.   Part III points to the nucleus, which is present in both plant and animal cells.   Part IV points to the pyrenoid/chloroplast structure typical of algae/plants. ', true, '2026-10-12 21:13:53.205', '2026-10-12 21:13:53.205', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ac206c8b-a0fa-43d1-a586-c3acc54238dd', 'Government', 'JAMB', null, 2026, null, 'The class that oversees the implementation of government decisions and policies is the', null, '["executive","clerical","technical","administrative"]', 3, 'The class that oversees the implementation of government decisions and policies is the administrative class. In the civil service, the administrative cadre is responsible for policy formulation, advising ministers, coordinating activities, and ensuring the implementation of government decisions. The executive, clerical, and technical classes support the administrative class in carrying out specific functions. The administrative class occupies the highest positions in the civil service hierarchy.', true, '2026-09-10 10:44:17.92', '2026-09-10 10:44:17.92', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ac298cab-6065-4656-812b-d68bcacc654e', 'Biology', 'JAMB', null, 2026, null, 'If a plant, homozygous for round and yellow (RR,YY), is crossed with a wrinkled green type (rr,yy), all of the resulting seed will be', null, '["blue and wrinkled","round and yellow","wrinkled and yellow","round and greenish yellow"]', 1, 'All resulting seeds will be round and yellow. Round (R) is dominant over wrinkled (r). Yellow (Y) is dominant over green (y). The cross RR,YY × rr,yy produces offspring that are Rr,Yy (heterozygous for both traits). Since both traits are completely dominant, all F1 seeds will show the dominant phenotypes: round and yellow. This is a dihybrid cross where the F1 generation shows both dominant traits.', true, '2026-09-09 03:19:17.255', '2026-09-09 03:19:17.255', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ac50a6cf-2fc8-4d81-af64-6e76149c2334', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. I wonder what will be left of his essay when the <u>extraneous</u> material is deleted.', null, '["main","relevant","erroneous","superfluous"]', 3, 'Extraneous = superfluous.', true, '2026-10-24 01:04:03.545', '2026-10-24 01:04:03.545', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. I wonder what will be left of his essay when the <u>extraneous</u> material is deleted.', '["main","relevant","erroneous","<u>superfluous</u>"]', '<b>Extraneous</b> = <b>superfluous</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ac516e81-7f08-48d6-9a18-34c704d03633', 'Government', 'JAMB', null, 2026, null, 'The doctrine of Separation of powers is associated with', null, '["Locke","Marx","Montesquieu","Hobbes"]', 2, 'Montesquieu is associated with the doctrine of separation of powers.', true, '2026-09-12 11:24:21.607', '2026-09-12 11:24:21.607', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ac5b38e3-dd33-413c-b65b-477cbab0e8d9', 'Biology', 'JAMB', null, 2003, null, 'If a DNA strand has a base sequence TCA, its complementary strand must be', null, '["ATG","TAG","GAT","AGT"]', 3, 'The complementary strand for TCA is AGT.', true, '2026-10-12 20:59:33.639', '2026-10-12 20:59:33.639', null, null, null, 'If a DNA strand has a base sequence TCA, its complementary strand must be', '["ATG","TAG","GAT","AGT"]', 'The complementary strand for TCA is AGT.', '{"bold":["AGT"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ac6efc2f-6a58-4f64-9d2f-0f86a0322a58', 'Physics', 'JAMB', null, 1993, null, 'If the focal length of a camera lens is 20 cm, the distance from the film at which the lens must be set to produce a sharp image of an object 100 cm away is', null, '["17 cm","20 cm","25 cm","100 cm"]', 2, '1/v = 1/f - 1/u = 1/20 - 1/100 = 4/100, so v = 25 cm.', true, '2026-10-12 19:15:37.81', '2026-10-12 19:15:37.81', null, null, null, 'If the focal length of a camera lens is 20 cm, the distance from the film at which the lens must be set to produce a sharp image of an object 100 cm away is', '["17 cm","20 cm","25 cm","100 cm"]', '1/v = 1/f - 1/u = 1/20 - 1/100 = 4/100, so v = 25 cm.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ac741100-dbd2-4ce0-a337-24e5c0866e88', 'English Language', 'JAMB', null, 2007, null, 'The students were suspended because they were <u>__________</u>', null, '["indisciplined","undisciplined","undiscipled","disciplinary"]', 1, 'Correct spelling: undisciplined.', true, '2026-10-24 07:21:32.942', '2026-10-24 07:21:32.942', null, null, null, 'The students were suspended because they were <u>__________</u>', '["indisciplined","undisciplined","undiscipled","disciplinary"]', 'Correct spelling: undisciplined.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ac7d7447-bb76-404a-96fd-618a13b990fb', 'Chemistry', 'JAMB', null, 2026, null, 'A student prepares a buffer solution using ethanoic acid and sodium ethanoate. The function of sodium ethanoate in the solution is to', null, '["neutralize the acid completely","supply OH⁻ ions","maintain a nearly constant pH by reacting with added H⁺","increase the strength of the acid"]', 2, 'Sodium ethanoate provides conjugate base ethanoate ions (CH3COO-) that absorb added H+ ions, stabilizing solution pH.', true, '2026-09-09 17:12:48.204', '2026-09-09 17:12:48.204', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ac93e311-008a-435d-86b2-fe8d2783c3e6', 'General Mathematics', 'JAMB', null, 2026, null, 'A die is thrown once. What is the probability of getting a number greater than 4?', null, '["1/6","1/3","1/2","2/3"]', 1, 'P(>4) = 2/6 = 1/3.', true, '2026-09-12 11:44:14.748', '2026-09-12 11:44:14.748', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ac9493f0-e8b6-4e78-88de-9074cf4a4942', 'Physics', 'JAMB', null, 2026, null, 'Transistors are used for the', null, '["conversion of AC to DC","amplification of signals","rectifications of signals","conversion of DC to AC"]', 1, 'Transistors are used for the amplification of signals. They can amplify weak electrical signals in circuits. Rectification (AC to DC) is done by diodes. Conversion of DC to AC is done by inverters.', true, '2026-09-10 10:56:40.327', '2026-09-10 10:56:40.327', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ac94c945-2b3a-4e53-9d6c-c736a2aa7b32', 'Biology', 'JAMB', null, 2013, null, 'The blood circulatory system of vertebrates consists of', null, '["Heart aorta arteries and veins","Heart vena cava arteries and veins","Heart arteries capillaries and veins","Heart aorta capillaries and veins"]', 2, 'The blood circulatory system consists of heart, arteries, capillaries and veins.', true, '2026-10-12 20:59:47.181', '2026-10-12 20:59:47.181', null, null, null, 'The blood circulatory system of vertebrates consists of', '["Heart aorta arteries and veins","Heart vena cava arteries and veins","Heart arteries capillaries and veins","Heart aorta capillaries and veins"]', 'The blood circulatory system consists of heart, arteries, capillaries and veins.', '{"bold":["heart, arteries, capillaries and veins"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ac965f03-a812-4fbb-a3c8-c0969446810b', 'Literature in English', 'JAMB', null, 2026, null, 'In Redemption Road, the narrative structure is best described as', null, '["A linear plot focusing on a single protagonist''s growth","A non-linear narrative employing multiple perspectives to depict post-war trauma","A dramatic monologue centred on a single voice","A purely epistolary narrative composed of letters"]', 1, 'The narrative is non-linear, employing multiple perspectives to depict post-war trauma.', true, '2026-09-12 11:04:49.411', '2026-09-12 11:04:49.411', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('acb041c6-2835-478f-9f1c-f5464745299c', 'Physics', 'JAMB', null, 1995, null, 'If a resistance is halved in value and the potential difference across it is tripled, then the ratio of the new current to the old is', null, '["1 : 6","1 : 3","2 : 1","6 : 1"]', 3, 'I = V/R. New current = 3V/(R/2) = 6V/R, which is 6 times the old current, so the ratio is 6 : 1.', true, '2026-10-12 19:15:42.111', '2026-10-12 19:15:42.111', null, null, null, 'If a resistance is halved in value and the potential difference across it is tripled, then the ratio of the new current to the old is', '["1 : 6","1 : 3","2 : 1","6 : 1"]', 'I = V/R. New current = 3V/(R/2) = 6V/R, which is 6 times the old current, so the ratio is 6 : 1.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('acb0d8c2-8d1c-4717-afa3-6daf73b51237', 'Biology', 'JAMB', null, 2026, null, 'A pair of genes that control a trait is referred to as', null, '["An allele","Recessive","Dominant","A hybrid"]', 0, 'An allele is one of the alternative forms of a gene that controls a trait. A pair of alleles (one inherited from each parent) determines the expression of a trait. Dominant and recessive describe how alleles are expressed. A hybrid refers to the offspring of genetically different parents. Alleles occupy the same locus on homologous chromosomes and can be the same (homozygous) or different (heterozygous).', true, '2026-09-09 03:18:58.108', '2026-09-09 03:18:58.108', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('acc5a54d-3d78-496e-9daa-aeaf56341a1d', 'Physics', 'JAMB', null, 2026, null, 'A missile of mass 10kg is projected at an angle 30° from the ground with an initial velocity 10ms⁻¹. What is the time of flight? (g=10ms⁻²)', null, '["6.00s","1.00s","1.96s","3.50s"]', 1, 'Time of flight T = 2u sin θ / g = 2 × 10 × sin 30° / 10 = 2 × 10 × 0.5 / 10 = 1.00s.', true, '2026-09-10 10:56:42.928', '2026-09-10 10:56:42.928', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('acc868bc-1b69-406a-bdd5-f25e3e7ef120', 'Biology', 'JAMB', null, 2012, null, 'The most likely first colonizers of a bare rock are', null, '["mosses","ferns","lichen","fungi."]', 2, 'Lichens are the first colonizers of bare rock.', true, '2026-10-12 20:59:45.299', '2026-10-12 20:59:45.299', null, null, null, 'The most likely first colonizers of a bare rock are', '["mosses","ferns","lichen","fungi."]', 'Lichens are the first colonizers of bare rock.', '{"bold":["Lichens"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('accc4aa4-077e-419d-a620-f313cd964d78', 'Chemistry', 'JAMB', null, 2026, null, 'During electrolysis of molten sodium chloride, sodium ions move toward the cathode because', null, '["they are negatively charged","they gain electrons in solution","they are attracted to electrons at the cathode","they combine with chlorine atoms"]', 2, 'Sodium ions (Na⁺) are positively charged and are attracted to the cathode, which is negatively charged (has excess electrons). At the cathode, Na⁺ gains an electron to form sodium metal: Na⁺ + e⁻ → Na.', true, '2026-09-12 09:38:15.203', '2026-09-12 09:38:15.203', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('acd6b548-25a4-453e-a2da-0d028de61a3f', 'English Language', 'JAMB', null, 2007, null, 'More than one student <u>_______</u>complained about the new rule.', null, '["have","are","has","were"]', 2, '''More than one'' singular â†’ has.', true, '2026-10-24 01:02:16.903', '2026-10-24 01:02:16.903', null, null, null, 'More than one student <u>_______</u>complained about the new rule.', '["have","are","<u>has</u>","were"]', '''<b>More than one</b>'' singular â†’ <b>has</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('acd6f6a6-7001-43a9-82b6-423eb923229c', 'Chemistry', 'JAMB', null, 2026, null, 'An organic functional group which can likely decolourize ammonical silver nitrate', null, '["alkyne","alkane","alkanol","alkene"]', 0, 'Terminal alkynes react with ammoniacal silver nitrate (Tollens'' reagent) to yield a characteristic white/grey precipitate of silver acetylide.', true, '2026-09-09 17:12:44.575', '2026-09-09 17:12:44.575', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ace66598-8c34-42da-97ca-3594f0533380', 'English Language', 'JAMB', null, 2007, null, 'The council chairman <u>__________</u> the tension between the villagers and the tax collectors.', null, '["dispersed","defused","diffused","disputed"]', 1, 'Correct spelling and meaning: defused.', true, '2026-10-24 07:21:33.451', '2026-10-24 07:21:33.451', null, null, null, 'The council chairman <u>__________</u> the tension between the villagers and the tax collectors.', '["dispersed","defused","diffused","disputed"]', 'Correct spelling and meaning: defused.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('acf9b696-08ce-4835-8430-d5fa197c3f5b', 'Economics', 'JAMB', null, 2026, null, 'Counter trading is an international arrangement whereby...', null, '["goods and services are exchanged in manner similar to barter system","goods are shipped to countries on which UN has placed a trade embargo","goods and services are sold over the counter","goods are sold via online"]', 0, 'Counter trading involves exchanging goods and services in a manner similar to barter.', true, '2026-09-12 11:00:43.77', '2026-09-12 11:00:43.77', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ad09c89e-55ff-41ae-95d8-014518c86d34', 'Biology', 'JAMB', null, 2001, null, 'An association between the root nodule of a leguminous plant and Rhizobium sp. is known as', null, '["parasitism","symbiosis","commensalism","mycorrhiza"]', 1, 'Rhizobium and leguminous plants share a mutually beneficial relationship known as symbiosis.', true, '2026-10-12 20:05:08.504', '2026-10-12 20:05:08.504', null, null, null, 'An association between the root nodule of a leguminous plant and Rhizobium sp. is known as', '["parasitism","symbiosis","commensalism","mycorrhiza"]', 'Rhizobium and leguminous plants share a mutually beneficial relationship known as symbiosis.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ad0b4eb3-b7ee-4a2b-bb86-0d6836393a9c', 'Economics', 'JAMB', null, 2026, null, 'The following are problems of development planning in Nigeria EXCEPT', null, '["inadequate capital","under-population","inadequate statistical data","poor implementation of economic planning"]', 1, 'Under-population is not a problem of development planning in Nigeria.', true, '2026-09-12 11:01:30.036', '2026-09-12 11:01:30.036', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ad1b1b76-a62d-4584-a43d-8afd42808161', 'Physics', 'JAMB', null, 1997, null, 'A mass of a liquid at 30 °C is mixed with a mass of the same liquid at 70 °C and the temperature of the mixture is 45 °C. Find the ratio of the mass of the cold liquid to the mass of the other liquid.', null, '["3 : 5","5 : 3","3 : 7","7 : 3"]', 1, 'mc(45 - 30) = mh(70 - 45), so mc/mh = 25/15 = 5/3.', true, '2026-10-12 19:15:43.525', '2026-10-12 19:15:43.525', null, null, null, 'A mass of a liquid at 30 °C is mixed with a mass of the same liquid at 70 °C and the temperature of the mixture is 45 °C. Find the ratio of the mass of the cold liquid to the mass of the other liquid.', '["3 : 5","5 : 3","3 : 7","7 : 3"]', 'm<sub>c</sub>(45 - 30) = m<sub>h</sub>(70 - 45), so m<sub>c</sub>/m<sub>h</sub> = 25/15 = 5/3.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ad1d2057-8330-45f5-a600-921713620911', 'Physics', 'JAMB', null, 1984, null, 'Which of the following components is NOT contained in a dry cell?', null, '["Carbon rod","Paste of manganese dioxide","Paste of ammonium chloride","Zinc case","Copper rod."]', 4, 'A dry (Leclanché) cell has a carbon rod, manganese dioxide, ammonium chloride paste and a zinc case, but no copper rod.', true, '2026-10-12 19:15:18.802', '2026-10-12 19:15:18.802', null, null, null, 'Which of the following components is <b>NOT</b> contained in a dry cell?', '["Carbon rod","Paste of manganese dioxide","Paste of ammonium chloride","Zinc case","Copper rod."]', 'A dry (Leclanché) cell has a carbon rod, manganese dioxide, ammonium chloride paste and a zinc case, but no copper rod.', '{"bold":["NOT"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ad341838-9272-4537-9b75-e7c9cac56842', 'Biology', 'JAMB', null, 2026, null, 'Hydrostatic skeleton is the type of supporting system found in', null, '["Mammals","Reptiles","Oligochaete","Arthropods"]', 2, 'A hydrostatic skeleton is a fluid-filled cavity (coelom) that provides support through fluid pressure. It is found in soft-bodied invertebrates, including oligochaetes (earthworms) and other annelids. The fluid in the coelom acts as a skeleton, providing structural support and enabling movement through muscle contraction against the fluid. Mammals and reptiles have endoskeletons (internal bony skeletons). Arthropods have exoskeletons (external chitinous skeletons). The hydrostatic skeleton is the simplest form of skeletal system.', true, '2026-09-09 03:18:25.501', '2026-09-09 03:18:25.501', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ad34fb56-29b8-471e-a38f-7a621bbe9364', 'Physics', 'JAMB', null, 1984, null, 'When vibration occurs in an air column, the distance between a node and an adjacent antinode is equal to', null, '["One-quarter of the wavelength","One-half of the wavelength","The wavelength","Twice the wavelength","Four-times the wavelength."]', 0, 'Adjacent nodes are λ/2 apart, and an antinode lies midway between them, so node-to-antinode distance is λ/4.', true, '2026-10-12 19:15:18.966', '2026-10-12 19:15:18.966', null, null, null, 'When vibration occurs in an air column, the distance between a node and an adjacent antinode is equal to', '["One-quarter of the wavelength","One-half of the wavelength","The wavelength","Twice the wavelength","Four-times the wavelength."]', 'Adjacent nodes are λ/2 apart, and an antinode lies midway between them, so node-to-antinode distance is λ/4.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ad3a1bb4-7169-450c-af8d-d1ba4c16be6e', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Surveying the sky in the quiet of the night gives me an <u>ethereal</u> feeling.', null, '["human","earthly","mundane","commonplace"]', 1, 'Ethereal = heavenly; opposite = earthly.', true, '2026-10-24 07:21:15.244', '2026-10-24 07:21:15.244', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Surveying the sky in the quiet of the night gives me an <u>ethereal</u> feeling.', '["human","earthly","mundane","commonplace"]', 'Ethereal = heavenly; opposite = earthly.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ad49974b-f40b-4732-a398-8bc21d5f27df', 'English Language', 'JAMB', null, 2007, null, 'There is no point getting upset by problems; I <u>take them _________________</u>', null, '["in my stride","on the spur of the moment","by leaps and bounds","in a jiffy"]', 0, '''Take in one''s stride'' = cope calmly.', true, '2026-10-24 01:04:25.433', '2026-10-24 01:04:25.433', null, null, null, 'There is no point getting upset by problems; I <u>take them _________________</u>', '["<u>in my stride</u>","on the spur of the moment","by leaps and bounds","in a jiffy"]', '''<b>Take in one''s stride</b>'' = <b>cope calmly</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ad56934f-6f8b-483f-9c59-065dd4f0ae51', 'Chemistry', 'JAMB', null, 2026, null, 'A solution contains 0.25 moles in 125 cm³. Find its concentration.', null, '["1.0 mol/dm³","2.0 mol/dm³","0.5 mol/dm³","0.25 mol/dm³"]', 1, 'Concentration = 0.25 / 0.125 = 2.0 mol/dm³.', true, '2026-09-12 11:35:58.504', '2026-09-12 11:35:58.504', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ad57d465-4e44-4ecc-9613-5c33ca0475f1', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). Mark is a very handsome fellow who informs me that he has <u>_____________</u> for pretty girls', null, '["a heart","a lip","an eye","a check"]', 2, '''Have an eye for'' = be attracted to.', true, '2026-10-24 01:02:11.479', '2026-10-24 01:02:11.479', null, null, null, '(Choose the most appropriate interpretation). Mark is a very handsome fellow who informs me that he has <u>_____________</u> for pretty girls', '["a heart","a lip","<u>an eye</u>","a check"]', '''<b>Have an eye for</b>'' = <b>be attracted to</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ad592edf-1f2e-42dc-b25b-62ba2caa3eb1', 'Literature in English', 'JAMB', null, 2026, null, 'The conflict presented in the poem is mainly between', null, '["tradition and modern technology","native culture and foreign influence","rich and poor citizens","government and opposition"]', 1, 'The conflict is between native culture and foreign influence.', true, '2026-09-12 11:12:30.774', '2026-09-12 11:12:30.774', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ad64261e-0406-402b-b697-f80c350bb7af', 'General Mathematics', 'JAMB', null, 2026, null, 'Simplify: (3a²b)(2ab³)', null, '["5a³b⁴","6a²b³","6a³b⁴","5a²b⁴"]', 2, '3a²b × 2ab³ = 6a³b⁴.', true, '2026-09-12 11:44:08.748', '2026-09-12 11:44:08.748', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ad676f1d-45e3-4809-ae55-72851fbe941a', 'Physics', 'JAMB', null, 1987, null, 'The mechanical advantage (MA) of an inclined plane depends on', null, '["Its length","Its height","The product of its length and height","The ratio of its length and its height."]', 3, 'For an inclined plane the velocity ratio is length/height, and the ideal MA is the same ratio.', true, '2026-10-12 19:15:25.04', '2026-10-12 19:15:25.04', null, null, null, 'The mechanical advantage (MA) of an inclined plane depends on', '["Its length","Its height","The product of its length and height","The ratio of its length and its height."]', 'For an inclined plane the velocity ratio is length/height, and the ideal MA is the same ratio.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ad686bab-0984-4318-8dc3-0c86b7e28437', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Everyone was talking about the <u>camaraderie</u> in the club.', null, '["companionship","quarrelsome","commissioning","disunity"]', 0, 'Camaraderie = companionship.', true, '2026-10-24 01:04:08.75', '2026-10-24 01:04:08.75', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Everyone was talking about the <u>camaraderie</u> in the club.', '["<u>companionship</u>","quarrelsome","commissioning","disunity"]', '<b>Camaraderie</b> = <b>companionship</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ad6dfea1-a49d-4dc0-95c4-3b24d83abe49', 'Physics', 'JAMB', null, 2001, null, 'A string is fastened tightly between two walls 24 cm apart. The wavelength of the second overtone is', null, '["24 cm","16 cm","12 cm","8 cm"]', 1, 'The second overtone is the third harmonic, with 3 half-wavelengths in the string: 3λ/2 = 24, so λ = 16 cm.', true, '2026-10-12 19:15:51.468', '2026-10-12 19:15:51.468', null, null, null, 'A string is fastened tightly between two walls 24 cm apart. The wavelength of the second overtone is', '["24 cm","16 cm","12 cm","8 cm"]', 'The second overtone is the third harmonic, with 3 half-wavelengths in the string: 3λ/2 = 24, so λ = 16 cm.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ad7acb1f-9802-4cbd-8abd-30eeb87b8255', 'Biology', 'JAMB', null, 2013, null, 'The organism is found in soils rich in', null, '["clay","sand","mud","humus"]', 3, 'Earthworms are found in soils rich in humus.', true, '2026-10-12 20:59:46.314', '2026-10-12 20:59:46.314', null, null, null, 'The organism is found in soils rich in', '["clay","sand","mud","humus"]', 'Earthworms are found in soils rich in humus.', '{"bold":["humus"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ad7bc5f5-fe6e-4347-98f9-e236dff7de3c', 'English Language', 'JAMB', null, 0, null, '1', null, '["recession","strikes","bankruptcy","unrest"]', 3, 'Industrial unrest" is the standard collocation for strikes and labor disputes.', true, '2026-09-18 09:08:12.065', '2026-09-18 09:08:12.065', '1edea09d-7ad3-4c90-8c54-eeb4b369dcff', 0, 'CLOZE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ad85fd3f-cd57-404b-8f26-e79eb51e0279', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. There was <u>a glut of</u> oil on the market.', null, '["a variety of","an accumulation of","an abundance of","an increase in"]', 2, 'Glut = abundance.', true, '2026-10-24 01:04:04.509', '2026-10-24 01:04:04.509', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. There was <u>a glut of</u> oil on the market.', '["a variety of","an accumulation of","<u>an abundance of</u>","an increase in"]', '<b>Glut</b> = <b>abundance</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ad86801a-96f6-4e65-9811-e3ca843c1002', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The principal described Oche as the most <u>tactful</u> person he had ever worked with.', null, '["passionate","discreet","hard-working","innovate"]', 1, 'Tactful = discreet.', true, '2026-10-24 01:01:57.761', '2026-10-24 01:01:57.761', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The principal described Oche as the most <u>tactful</u> person he had ever worked with.', '["passionate","<u>discreet</u>","hard-working","innovate"]', '<b>Tactful</b> = <b>discreet</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ad873530-5c22-4e36-a610-c55ef50ceb65', 'Physics', 'JAMB', null, 1988, null, 'A lorry travels 10 km northwards, 4 km eastwards, 6 km southwards and 4 km westwards to arrive at a point T. What is the total displacement?', null, '["6 km south","4 km north","6 km north","4 km east"]', 1, 'Net north-south = 10 - 6 = 4 km north. Net east-west = 4 - 4 = 0. Displacement = 4 km north.', true, '2026-10-12 19:15:26.836', '2026-10-12 19:15:26.836', null, null, null, 'A lorry travels 10 km northwards, 4 km eastwards, 6 km southwards and 4 km westwards to arrive at a point T. What is the total displacement?', '["6 km south","4 km north","6 km north","4 km east"]', 'Net north-south = 10 - 6 = 4 km north. Net east-west = 4 - 4 = 0. Displacement = 4 km north.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ad87f861-fc10-4ea6-a36e-3ace5253038d', 'Economics', 'JAMB', null, 2026, null, 'A system of taxation in which all taxpayers pay the same proportion of their income as tax is known as:', null, '["Regressive","Proportional","Progressive","None of the options"]', 1, 'Proportional tax takes the same proportion of income from all taxpayers.', true, '2026-09-12 11:01:24.677', '2026-09-12 11:01:24.677', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ad8f9e17-94fc-4ebb-b98e-994ae3b05953', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Christians ought to be humble because', null, '["the law commanded it absolutely","Jesus Christ demonstrated it","it is a spiritual gift","only the humble will inherit eternal life"]', 1, 'Christians ought to be humble because Jesus Christ demonstrated it. In Philippians 2, Paul says, ''Have this mind among yourselves, which is yours in Christ Jesus, who, though he was in the form of God, did not count equality with God a thing to be grasped, but emptied himself, taking the form of a servant.''', true, '2026-09-12 09:46:03.328', '2026-09-12 09:46:03.328', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ad9a4c16-7ea5-4482-b31c-30de96453518', 'Literature in English', 'JAMB', null, 2026, null, 'The phrase ''horrors of red corals'' is an example of', null, '["an oxymoron","simile","visual imagery","euphemism"]', 2, '''Horrors of red corals'' is visual imagery.', true, '2026-09-12 11:10:45.235', '2026-09-12 11:10:45.235', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ada0879b-5a30-4a6f-9e17-53c83cd63ce5', 'Economics', 'JAMB', null, 2026, null, 'Which of the following is not a possible source of finance of a sole proprietorship?', null, '["Personal savings","Borrowing from banks","Ploughing back profit","Inherited capital","Selling shares to the public"]', 4, 'Selling shares to the public is not a possible source of finance for a sole proprietorship. A sole proprietorship is owned and controlled by one person and cannot sell shares to the public. Only public limited liability companies can sell shares to the public. Sources of finance for a sole proprietor include personal savings, bank loans, ploughing back profits, and inherited capital.', true, '2026-09-10 10:41:21.044', '2026-09-10 10:41:21.044', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ada2cce4-e9ed-48de-9ffe-bac7e3b31b07', 'Physics', 'JAMB', null, 1983, null, 'An electric current of 3 A flowing through an electric heating element of resistance 20 Ω embedded in 1,000 g of an oil raises the temperature of the oil by 10 °C in 10 seconds. The specific heat capacity of the oil is', null, '["1.8 J/g","0.6 J/g","0.18 J/g °C","1.8 J/g °C","0.06 J/g °C"]', 2, 'Heat supplied = I²Rt = 3² x 20 x 10 = 1800 J. Specific heat capacity c = Q/(mΔθ) = 1800/(1000 x 10) = 0.18 J/g °C.', true, '2026-10-12 19:15:17.544', '2026-10-12 19:15:17.544', null, null, null, 'An electric current of 3 A flowing through an electric heating element of resistance 20 Ω embedded in 1,000 g of an oil raises the temperature of the oil by 10 °C in 10 seconds. The specific heat capacity of the oil is', '["1.8 J/g","0.6 J/g","0.18 J/g °C","1.8 J/g °C","0.06 J/g °C"]', 'Heat supplied = I<sup>2</sup>Rt = 3<sup>2</sup> x 20 x 10 = 1800 J. Specific heat capacity c = Q/(mΔθ) = 1800/(1000 x 10) = 0.18 J/g °C.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('adbb2d30-6c13-4037-89aa-927395657dde', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'According to the Letter of Paul to the Romans, sin reigned in death. While grace reigned through righteousness to', null, '["salvation","eternal life","eternal peace","eternal joy"]', 1, 'Grace reigns through righteousness to eternal life (Romans 5:21).', true, '2026-09-12 10:41:23.388', '2026-09-12 10:41:23.388', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('adc53fac-656a-4007-84c1-cc3a0ab4268f', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Ojo <u>used to play</u> tennis every day.', null, '["is familiar with playing","has to play","was in the habit of playing","was made to play"]', 2, 'Used to = was in the habit of.', true, '2026-10-24 01:03:59.638', '2026-10-24 01:03:59.638', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Ojo <u>used to play</u> tennis every day.', '["is familiar with playing","has to play","<u>was in the habit of playing</u>","was made to play"]', '<b>Used to</b> = <b>was in the habit of</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('add61057-cffa-4c89-9746-5fce86bda0cb', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The suggestion he made were very <u>unobstructed</u>.', null, '["sincerity","reasonable","forceful","helpful"]', 3, 'Unobstructed = clear; closest opposite = helpful.', true, '2026-10-24 07:21:28.866', '2026-10-24 07:21:28.866', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The suggestion he made were very <u>unobstructed</u>.', '["sincerity","reasonable","forceful","helpful"]', 'Unobstructed = clear; closest opposite = helpful.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ade33c1c-d96e-4951-8a0c-05ba14cfacf8', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. All we need is a <u>concerted</u> effort to combat the epidemic.', null, '["persistent","dramatic","joint","concentrated"]', 2, 'Concerted = joint.', true, '2026-10-24 01:03:56.022', '2026-10-24 01:03:56.022', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. All we need is a <u>concerted</u> effort to combat the epidemic.', '["persistent","dramatic","<u>joint</u>","concentrated"]', '<b>Concerted</b> = <b>joint</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('adf6248a-c85c-4ed3-9169-ff1223535887', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Garuba''s performance in the play was <u>horrid</u>.', null, '["terrible","encouraging","commendable","rigid"]', 0, 'Horrid = terrible.', true, '2026-10-24 01:01:59.297', '2026-10-24 01:01:59.297', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Garuba''s performance in the play was <u>horrid</u>.', '["<u>terrible</u>","encouraging","commendable","rigid"]', '<b>Horrid</b> = <b>terrible</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('adfd3300-f9fd-4053-9a62-20fd975163c7', 'English Language', 'JAMB', null, 2024, null, 'The police claim that a number of stolen cars ______ recovered', null, '["Have been","Has been","Is being","Has being"]', 0, '"A number of" takes a plural verb, so "have been" is correct.', true, '2026-09-18 09:34:03.984', '2026-09-18 09:34:03.984', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('adfdebac-551e-432f-86aa-733c8ce608ac', 'Economics', 'JAMB', null, 2026, null, 'Scarcity in economics means?', null, '["human wants are limitless","the economy has very few resources","the economy can scarcely produce anything","resources are limited in relation to wants"]', 3, 'Scarcity means resources are limited in relation to unlimited wants.', true, '2026-09-12 11:00:49.113', '2026-09-12 11:00:49.113', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ae0305f8-bd83-42ab-bf8c-7d255710c295', 'Chemistry', 'JAMB', null, 2026, null, 'Calculate the mass of magnesium that would be deposited by 8 Faraday''s of electricity (Mg=24, 1F=96500)', null, '["96g","48g","72g","120g"]', 0, 'Mg²⁺ + 2e⁻ → Mg. 2F deposits 24g. 8F deposits (8/2) × 24 = 96g.', true, '2026-09-12 11:36:00.495', '2026-09-12 11:36:00.495', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ae037e6d-9634-46fb-809b-1fdce2b47807', 'Economics', 'JAMB', null, 2026, null, 'A good is described as inferior when its income elasticity of demand coefficient is', null, '["Negative","Positive","Zero","Infinity","One"]', 0, 'A good is described as inferior when its income elasticity of demand coefficient is negative. This means that as consumer income increases, the quantity demanded of the good decreases. Inferior goods are those for which consumers switch to better alternatives as their income rises. Examples include cheap cuts of meat, second-hand clothing, and generic brands.', true, '2026-09-10 10:41:20.83', '2026-09-10 10:41:20.83', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ae17a543-405d-48e5-b8d8-34b35f9c5854', 'Literature in English', 'JAMB', null, 2026, null, 'The main purpose of drama is to', null, '["Only entertain the audience","Confuse the viewers","Educate and entertain through action and dialogue","describe the setting vividly"]', 2, 'The main purpose of drama is to educate and entertain through action and dialogue. Drama serves both purposes: it entertains audiences with compelling stories, characters, and conflicts, while also conveying moral lessons, social commentary, and human truths. The combination of education and entertainment is often called ''edutainment.'' Drama is not meant to confuse viewers or only entertain.', true, '2026-09-10 10:45:33.914', '2026-09-10 10:45:33.914', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ae190475-0b82-4874-b1d5-70893e66ffba', 'Physics', 'JAMB', null, 1988, null, 'Which of the following instruments consumes the highest current?', null, '["Electric iron (250 V, 1 kW)","Television set (220 V, 110 W)","Torch light (6 V, 30 W)","Immersion heater (110 V, 500 W)"]', 2, 'I = P/V: iron = 4 A, television = 0.5 A, torch light = 5 A, immersion heater = 4.5 A. The torch light draws the most.', true, '2026-10-12 19:15:28.333', '2026-10-12 19:15:28.333', null, null, null, 'Which of the following instruments consumes the highest current?', '["Electric iron (250 V, 1 kW)","Television set (220 V, 110 W)","Torch light (6 V, 30 W)","Immersion heater (110 V, 500 W)"]', 'I = P/V: iron = 4 A, television = 0.5 A, torch light = 5 A, immersion heater = 4.5 A. The torch light draws the most.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ae208278-1392-422e-a51c-404cbe1c6ecb', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). Mr. Okon has been described as <u>an eagle-eyed</u> editor.', null, '["a short-sighted","a clear-sighted","a long-sighted","a quick-sighted"]', 3, '''Eagle-eyed'' = keen-sighted/quick-sighted.', true, '2026-10-24 01:02:08.764', '2026-10-24 01:02:08.764', null, null, null, '(Choose the most appropriate interpretation). Mr. Okon has been described as <u>an eagle-eyed</u> editor.', '["a short-sighted","a clear-sighted","a long-sighted","<u>a quick-sighted</u>"]', '''<b>Eagle-eyed</b>'' = <b>keen-sighted/quick-sighted</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ae231ddc-7ef7-4a56-94ae-5d2e2c1a202f', 'Literature in English', 'JAMB', null, 2026, null, 'Which of these characters is not mentioned in the poem?', null, '["Chinwe","Danladi","Akanni","Ibrahim"]', 3, 'Ibrahim is not mentioned in the poem.', true, '2026-09-12 11:13:42.832', '2026-09-12 11:13:42.832', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ae2cae3d-d276-4e8d-a373-abd50c812f97', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Eli''s attitude towards his children showed parental', null, '["weakness","responsibility","Love","intolerance"]', 0, 'Eli''s failure to restrain his sons showed parental weakness.', true, '2026-09-12 10:42:03.746', '2026-09-12 10:42:03.746', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ae2f844e-ebe2-4ebe-ba53-3395be86c27c', 'Biology', 'JAMB', null, 2003, null, 'The correct sequence of biomes from northern to southern Nigeria is', null, '["Guinea savanna - Sudan savanna - tropical rain forest - Sahel savanna - estuarine","Estuarine - tropical rain forest - Guinea savanna - Sahel savanna","Sahel savanna - tropical rain forest - estuarine - Guinea savanna","Sahel savanna - Sudan savanna - Guinea savanna - tropical rain forest - estuarine"]', 3, 'The correct sequence from north to south is Sahel savanna, Sudan savanna, Guinea savanna, tropical rain forest, estuarine.', true, '2026-10-12 20:59:33.385', '2026-10-12 20:59:33.385', null, null, null, 'The correct sequence of biomes from northern to southern Nigeria is', '["Guinea savanna - Sudan savanna - tropical rain forest - Sahel savanna - estuarine","Estuarine - tropical rain forest - Guinea savanna - Sahel savanna","Sahel savanna - tropical rain forest - estuarine - Guinea savanna","Sahel savanna - Sudan savanna - Guinea savanna - tropical rain forest - estuarine"]', 'The correct sequence from north to south is Sahel savanna, Sudan savanna, Guinea savanna, tropical rain forest, estuarine.', '{"bold":["Sahel savanna, Sudan savanna, Guinea savanna, tropical rain forest, estuarine"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ae311be0-8508-4a2f-9e09-103da0c58e60', 'Biology', 'JAMB', null, 2026, null, 'Which of the following stimuli is likely to elicit a nastic response in an organism?', null, '["Wound lesion","Light intensity","Chemical substances","Gravity"]', 1, 'Light intensity is likely to elicit a nastic response in an organism (photonasty). Nastic responses are non-directional responses to stimuli. In plants, light intensity can cause flowers to open or close (photonasty). Wound lesion may elicit a response but not typically a nastic one. Chemical substances elicit chemotropisms. Gravity elicits gravitropism. Nastic responses are determined by the plant''s structure rather than the direction of the stimulus. Photonasty in flowers is a common example, with flowers opening and closing in response to light intensity.', true, '2026-09-09 03:19:02.506', '2026-09-09 03:19:02.506', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ae340914-cebb-41b8-82f7-5d4aa33bb6fe', 'Government', 'JAMB', null, 2026, null, 'A bill that applies to the whole population and is intended to promote the general welfare is called', null, '["A private bill","A decree","a public bill","an edict"]', 2, 'A bill that applies to the whole population and is intended to promote the general welfare is called a public bill. Public bills are proposed laws that affect the general public and deal with matters of national or public interest. They are introduced by ministers or members of parliament and debated in the legislature. Private bills affect specific individuals or groups, decrees are made by military governments, and edicts are regional laws.', true, '2026-09-10 10:45:06.998', '2026-09-10 10:45:06.998', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ae3b15ee-e154-46a9-ae1c-b0449060ed83', 'English Language', 'JAMB', null, 2024, null, '{Choose the synonym to the highlighted expression} The attempt by the robbers to break into the bank was futile', null, '["successful","expensive","hostile","fruitless"]', 3, '"Futile" means useless or fruitless.', true, '2026-09-18 09:43:02.27', '2026-09-18 09:43:02.27', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ae3b2739-dc20-4de1-bc2a-198936641966', 'English Language', 'JAMB', null, 2024, null, 'What reason was suggested for the principal''s emotional breakdown', null, '["a personal issue, possibly related to his wife","a medical condition","a work-related crisis at the school","financial troubles"]', 0, 'A personal issue, possibly related to his wife, was suggested as the reason.', true, '2026-09-18 09:43:02.756', '2026-09-18 09:43:02.756', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ae422552-a16b-4199-bcc5-bb1718a268ae', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Just give me the <u>basic facts</u>, needless details.', null, '["relevant","extraneous","essential","critical"]', 2, 'Basic facts = essential.', true, '2026-10-24 01:04:11.758', '2026-10-24 01:04:11.758', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Just give me the <u>basic facts</u>, needless details.', '["relevant","extraneous","<u>essential</u>","critical"]', '<b>Basic facts</b> = <b>essential</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ae552ed7-c489-4d08-abf4-9742b4fcac38', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. In spite of constant financial support from his father, Udenyi treats his studies with considerable <u>levity</u>.', null, '["lassitude","wastefulness","enthusiasm","seriousness"]', 0, 'Levity = lack of seriousness; closest = lassitude.', true, '2026-10-24 01:04:05.312', '2026-10-24 01:04:05.312', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. In spite of constant financial support from his father, Udenyi treats his studies with considerable <u>levity</u>.', '["<u>lassitude</u>","wastefulness","enthusiasm","seriousness"]', '<b>Levity</b> = lack of seriousness; closest = <b>lassitude</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ae5d2f99-1c89-48be-9d00-54ca4c529c3a', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Man was the last of all that God created, but man was crowned by God at creation to be king over all other creatures due to...', null, '["man’s ability to manage all other creatures","man’s religious in divination","the reflection of God’s image in the nature of man","man’s ability to recreate all that God created originally"]', 2, 'Genesis 1:26-28 shows that human dominion over creation stems directly from being created in the image and likeness of God.', true, '2026-09-09 17:18:24.982', '2026-09-09 17:18:24.982', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ae63ec30-8527-4876-b313-64543b782af1', 'Physics', 'JAMB', null, 1992, null, 'Which of the following statements is CORRECT about a long-sighted boy who does not put on glasses?', null, '["He cannot see distant objects clearly","Rays of light from a close object are focused in front of his retina","His eyeball is too long","Parallel rays of light are focused behind his retina."]', 3, 'A long-sighted eye is too short or too weak, so the rays from near objects (and parallel rays) focus behind the retina.', true, '2026-10-12 19:15:35.979', '2026-10-12 19:15:35.979', null, null, null, 'Which of the following statements is <b>CORRECT</b> about a long-sighted boy who does not put on glasses?', '["He cannot see distant objects clearly","Rays of light from a close object are focused in front of his retina","His eyeball is too long","Parallel rays of light are focused behind his retina."]', 'A long-sighted eye is too short or too weak, so the rays from near objects (and parallel rays) focus behind the retina.', '{"bold":["CORRECT"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ae675bde-93e4-4125-a0aa-33d551192879', 'General Mathematics', 'JAMB', null, 2026, null, 'The mean of the numbers 3,6,4,x and 7 = 5, find the standard deviation', null, '["3","√2","√3","2"]', 2, 'Sum = 3+6+4+x+7 = 20+x = 25. x = 5. Deviations: -2,1,-1,0,2. Variance = (4+1+1+0+4)/5 = 10/5 = 2. SD = √2. The answer is (B) √2.', true, '2026-09-12 11:44:06.434', '2026-09-12 11:44:06.434', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ae6edf0e-0850-4350-b834-45842fd8a850', 'Literature in English', 'JAMB', null, 2026, null, 'A character that develops psychologically is', null, '["flat character","round character","stock character","chorus"]', 1, 'A round character develops psychologically.', true, '2026-09-12 11:11:23.209', '2026-09-12 11:11:23.209', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ae7078d6-367f-476a-b3f2-064a40cbf084', 'Literature in English', 'JAMB', null, 2026, null, 'The poetic persona''s attitude in the first three stanzas can best be described as', null, '["sympathetic and concerned","fearful and anxious","nonchalant and self-serving","confrontational and rebellion"]', 2, 'The poetic persona''s attitude in the first three stanzas of "Not My Business" can best be described as nonchalant and self-serving. The speaker shows no concern for the victims of oppression, repeatedly asking ''what business of mine is it?'' as long as his own comfort is not disturbed. He is indifferent to the suffering of others. This attitude changes in the final stanza when he himself becomes a victim.', true, '2026-09-10 10:45:34.83', '2026-09-10 10:45:34.83', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ae71b147-ac97-4abb-9115-2e20fd3f0709', 'Biology', 'JAMB', null, 2026, null, 'The enzymes of the glycolytic pathway are located in the', null, '["mitochondria","gastric juice","plasma","cytoplasm"]', 3, 'The enzymes of the glycolytic pathway are located in the cytoplasm. Glycolysis occurs in the cytoplasm of cells, where glucose is broken down to pyruvate, producing ATP and NADH. Mitochondria contain enzymes for the Krebs cycle and electron transport chain. Gastric juice contains digestive enzymes. Blood plasma contains various proteins but not glycolytic enzymes. Glycolysis is an ancient metabolic pathway that occurs in the cytoplasm, not requiring membrane-bound organelles.', true, '2026-09-09 03:19:09.661', '2026-09-09 03:19:09.661', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ae71ec2f-e41d-40c6-bd07-f1fbb442fb20', 'Economics', 'JAMB', null, 2026, null, 'Average fixed cost is a rectangular hyperbola', null, '["since unit cost increases as output increases","unit cost increases as output decreases","unit cost decreases as output increases","unit cost remains the same as output increases","none of the above"]', 2, 'Average fixed cost (AFC) is a rectangular hyperbola because unit cost decreases as output increases. AFC = Total Fixed Cost / Output. Since total fixed cost is constant, as output increases, AFC continuously decreases. This is why the AFC curve slopes downward throughout and never touches the axes. It is a rectangular hyperbola because the area under the curve (AFC × Output) remains constant (equal to TFC).', true, '2026-09-10 10:41:19.591', '2026-09-10 10:41:19.591', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ae736bfd-0f60-444c-b59b-e3f706172c02', 'Biology', 'JAMB', null, 2026, null, 'Which of the following substances are eliminated from the body through the process of excretion? I. CO2 II. Urea III. Water IV. Glucose', null, '["I & II","I, II, III & IV","II & IV","I, II & IV"]', 1, 'Carbon dioxide (CO2), urea, and water are all excretory products that are eliminated from the body. CO2 is excreted through the lungs during exhalation. Urea is excreted through the kidneys in urine. Water is excreted through the kidneys, skin (sweat), and lungs (water vapor). Glucose is not an excretory product under normal conditions; it is a valuable nutrient that is reabsorbed in the kidneys. The presence of glucose in urine (glycosuria) indicates a pathological condition such as diabetes mellitus. Therefore, I, II, and III are correct.', true, '2026-09-09 03:18:31.883', '2026-09-09 03:18:31.883', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ae8ca3b8-137d-4170-8698-a7bd80006b82', 'Biology', 'JAMB', null, 2004, null, 'A plant-like feature in Euglena is the', null, '["pellicle","pigment spot","large vacuole","gullet"]', 0, 'Euglena possesses a pellicle characteristic of plant-like autotrophs.', true, '2026-10-12 20:59:34.406', '2026-10-12 20:59:34.406', null, null, null, 'A plant-like feature in Euglena is the', '["pellicle","pigment spot","large vacuole","gullet"]', 'Euglena possesses a pellicle characteristic of plant-like autotrophs.', '{"bold":["pellicle"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ae9662a4-8fdf-481d-a67d-cbacb2eeb4ea', 'Biology', 'JAMB', null, 2003, null, 'Homologous pairs of chromosomes separate during', null, '["cytolysis","cleavage","mitosis","meiosis"]', 3, 'Homologous chromosomes separate during meiosis.', true, '2026-10-12 20:59:33.029', '2026-10-12 20:59:33.029', null, null, null, 'Homologous pairs of chromosomes separate during', '["cytolysis","cleavage","mitosis","meiosis"]', 'Homologous chromosomes separate during meiosis.', '{"bold":["meiosis"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ae97de53-9432-4da7-bbb7-e5f92e260d69', 'Literature in English', 'JAMB', null, 2026, null, 'The narrative technique predominantly used in the novel is', null, '["Omniscient narration","Epistolary narration","Stream of consciousness","Dramatic monologue"]', 0, 'Omniscient narration is predominantly used.', true, '2026-09-12 11:14:08.663', '2026-09-12 11:14:08.663', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ae9da053-fa7a-4a15-8117-7f71f8f375c3', 'Government', 'JAMB', null, 2026, null, 'In a representative government, citizens exercise their political power', null, '["directly","indirectly","in reverence for the political system","under undue political pressure"]', 1, 'In a representative government, citizens exercise power indirectly through representatives.', true, '2026-09-12 11:24:16.802', '2026-09-12 11:24:16.802', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ae9f6ba0-0653-40f9-af1d-df8ce2459c3e', 'English Language', 'JAMB', null, 2007, null, 'The lecturer was concerned not so much about the students'' poor results ...... about their unwillingness to improve.', null, '["than","but","as","and"]', 2, '''Not so much ... as'' is the correct correlative.', true, '2026-10-25 18:25:06.359', '2026-10-25 18:25:06.359', null, null, null, 'The lecturer was concerned not so much about the students'' poor results ...... about their unwillingness to improve.', '["than","but","as","and"]', '''Not so much ... as'' is the correct correlative.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('aea960fe-baf9-4769-ba71-304e953418e6', 'English Language', 'JAMB', null, 2024, null, 'How much did Bepo give his landlord''s children as he left for the airport?', null, '["#2,000","#5,000","#10,000","#7,500"]', 0, 'Bepo gave his landlord''s children #2,000 as he left for the airport.', true, '2026-09-18 09:24:04.786', '2026-09-18 09:24:04.786', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('aec49003-80cf-4ed6-abb5-c3f9e818a932', 'Literature in English', 'JAMB', null, 2026, null, '______ is an understatement expressed by using a negation to affirm the opposite', null, '["bildungsroman","picaresque","litotes","hyperbole"]', 2, 'Litotes is an understatement using negation to affirm the opposite.', true, '2026-09-12 11:10:07.378', '2026-09-12 11:10:07.378', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('aec6b612-c403-4ba8-971e-4ffe270a1738', 'Biology', 'JAMB', null, 2010, null, 'Parental care is exhibited by', null, '["toads","snails","earthworms","birds"]', 3, 'Birds exhibit parental care.', true, '2026-10-12 20:59:38.898', '2026-10-12 20:59:38.898', null, null, null, 'Parental care is exhibited by', '["toads","snails","earthworms","birds"]', 'Birds exhibit parental care.', '{"bold":["Birds"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('aec73d06-2f57-47ad-9dc2-f0e8ccffa208', 'Biology', 'JAMB', null, 2026, null, 'Which of the above conditions are necessary for germination of seed? I. Water II. O2 III. CO2 IV. Warmth V. Viable seed', null, '["I, II, III, IV & V","I, II, III & IV","I, II, IV & V","I, III, IV & V"]', 2, 'For successful germination, seeds require water (I), oxygen (II), warmth (IV), and a viable seed (V). CO2 (III) is not required for germination; in fact, oxygen is necessary for aerobic respiration during germination to provide energy. Water activates enzymes and softens the seed coat. Warmth provides optimal temperature for enzyme activity. A viable seed contains a living embryo. Without these four conditions, germination will not occur. Some seeds also require light or specific temperature treatments (stratification), but the basic requirements are water, oxygen, warmth, and viability.', true, '2026-09-09 03:18:35.246', '2026-09-09 03:18:35.246', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('aeccbe54-576a-48e1-9d67-295076ff9905', 'Economics', 'JAMB', null, 2026, null, 'A drawer of a cheque is', null, '["person who is to be paid","bank on which the cheque is drawn","person who writes out the cheque","bank officials who certify the payment"]', 2, 'A drawer of a cheque is the person who writes out the cheque. The drawer is the account holder who issues the cheque and instructs the bank to pay a specified amount to a named person or bearer. The person to be paid is the payee. The bank on which the cheque is drawn is the drawee bank. Bank officials who certify payment are not the drawer.', true, '2026-09-10 10:42:55.346', '2026-09-10 10:42:55.346', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('aecd23d4-75be-45d2-ad62-18eccc569633', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). The preacher is <u>under a cloud</u> among the congregation.', null, '["out of favour","under observation","under weather","confused"]', 0, '''Under a cloud'' = out of favour.', true, '2026-10-24 01:04:19.592', '2026-10-24 01:04:19.592', null, null, null, '(Choose the most appropriate interpretation). The preacher is <u>under a cloud</u> among the congregation.', '["<u>out of favour</u>","under observation","under weather","confused"]', '''<b>Under a cloud</b>'' = <b>out of favour</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('aecedccd-807d-4cd1-8a50-7ecedbc89a89', 'Biology', 'JAMB', null, 2002, null, 'The mammalian erythrocytes differ from the leucocytes at maturity because the erythrocytes are', null, '["discoid and nucleated","discoid and enucleated","amoeboid and nucleated","amoeboid and enucleated"]', 1, 'Mature mammalian erythrocytes are discoid and enucleated.', true, '2026-10-12 20:59:31.165', '2026-10-12 20:59:31.165', null, null, null, 'The mammalian erythrocytes differ from the leucocytes at maturity because the erythrocytes are', '["discoid and nucleated","discoid and enucleated","amoeboid and nucleated","amoeboid and enucleated"]', 'Mature mammalian erythrocytes are discoid and enucleated.', '{"bold":["discoid and enucleated"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('aecf310c-d9ae-4c84-850e-cc670be6a265', 'Biology', 'JAMB', null, 2011, null, 'The crossing of individuals of the same species with different genetic characters is', null, '["cross breeding","polygenic inheritance","non-disjunction","inbreeding."]', 3, 'Crossing individuals of the same species with different genetic characters is inbreeding.', true, '2026-10-12 20:59:43.727', '2026-10-12 20:59:43.727', null, null, null, 'The crossing of individuals of the same species with different genetic characters is', '["cross breeding","polygenic inheritance","non-disjunction","inbreeding."]', 'Crossing individuals of the same species with different genetic characters is inbreeding.', '{"bold":["inbreeding"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('aee46a60-b05b-483c-b822-12392b90273b', 'Financial Accounting', 'UTME', null, 2003, null, 'The amount of each invoiced goods sent to the branch is debited to', null, '["branch expense account credited and to branch debtors'' account","branch stock account and credited to the goods sent to branch account","branch debtors'' account and credited to branch expense account","goods sent to branch account and credited to branch expense account"]', 1, 'The amount of each invoiced goods sent to the branch is debited to branch stock account and credited to the goods sent to branch account.', true, '2026-10-12 22:00:01.41', '2026-10-12 22:00:01.41', null, null, null, 'The amount of each invoiced goods sent to the branch is debited to', '["branch expense account credited and to branch debtors'' account","<b>branch stock account and credited to the goods sent to branch account</b>","branch debtors'' account and credited to branch expense account","goods sent to branch account and credited to branch expense account"]', 'The amount of each invoiced goods sent to the branch is debited to <b>branch stock account and credited to the goods sent to branch account</b>.', '{"bold":["branch stock account and credited to the goods sent to branch account"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('aef967b5-c928-4259-b717-471fd5e5f958', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'According to the Letter of Paul to the Romans, sin reigned in death. While grace reigned through righteousness to', null, '["salvation","eternal life","eternal peace","eternal joy"]', 1, 'In Romans 5:21, Paul says, ''As sin reigned in death, grace also might reign through righteousness to eternal life through Jesus Christ our Lord.''', true, '2026-09-12 09:46:03.791', '2026-09-12 09:46:03.791', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('aeff99b8-ccad-4693-b44a-17554bf6902e', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The Executive Secretary has just <u>assumed office</u>.', null, '["resumed work","been sworn in","started work","returned"]', 2, 'Assumed office = started work.', true, '2026-10-24 01:04:04.08', '2026-10-24 01:04:04.08', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The Executive Secretary has just <u>assumed office</u>.', '["resumed work","been sworn in","<u>started work</u>","returned"]', '<b>Assumed office</b> = <b>started work</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('af12e7a1-889e-4023-bdb2-6763014607a7', 'English Language', 'JAMB', null, 2007, null, 'He keeps his <u>__________</u> clean always', null, '["surroundings","surrounding","premise","environments"]', 0, 'Correct form: surroundings.', true, '2026-10-24 07:21:34.002', '2026-10-24 07:21:34.002', null, null, null, 'He keeps his <u>__________</u> clean always', '["surroundings","surrounding","premise","environments"]', 'Correct form: surroundings.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('af20582d-ae51-43e1-900e-b0b308d3ff4e', 'Physics', 'JAMB', null, 2004, null, 'If the angle between two vectors P and Q is 0°, the vectors are said to', null, '["Be perpendicular","Be parallel","Intersect at angle 60°","Intersect at angle 45°"]', 1, 'An angle of 0° between two vectors means they point in the same direction, so they are parallel.', true, '2026-10-12 19:15:58.553', '2026-10-12 19:15:58.553', null, null, null, 'If the angle between two vectors P and Q is 0°, the vectors are said to', '["Be perpendicular","Be parallel","Intersect at angle 60°","Intersect at angle 45°"]', 'An angle of 0° between two vectors means they point in the same direction, so they are parallel.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('af264abd-9f32-4af7-aa2e-5365371987ad', 'Physics', 'JAMB', null, 1986, null, 'A pencil is placed vertically between a concave mirror and its focal point. The image of the pencil in the mirror will be', null, '["Real, inverted and diminished","Virtual, inverted and enlarged","Real, erect and enlarged.","Virtual, erect and enlarged."]', 3, 'For an object inside the focal length of a concave mirror, the image is virtual, erect and enlarged (as in a shaving mirror).', true, '2026-10-12 19:15:23.949', '2026-10-12 19:15:23.949', null, null, null, 'A pencil is placed vertically between a concave mirror and its focal point. The image of the pencil in the mirror will be', '["Real, inverted and diminished","Virtual, inverted and enlarged","Real, erect and enlarged.","Virtual, erect and enlarged."]', 'For an object inside the focal length of a concave mirror, the image is virtual, erect and enlarged (as in a shaving mirror).', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('af30fd50-6ab2-4317-a5cd-cdca327e23b7', 'Literature in English', 'JAMB', null, 2026, null, 'The sequence of events that make up a story is called the', null, '["theme","plot","conflict","setting"]', 1, 'Plot is the sequence of events.', true, '2026-09-12 11:10:47.022', '2026-09-12 11:10:47.022', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('af3103b8-d3df-4cc1-845c-e918322e288c', 'Literature in English', 'JAMB', null, 2026, null, '''Singing songs of sorrow is symbolic of sincere sympathy'' illustrates', null, '["Assonance","Refrain","Alliteration","Anecdote"]', 2, 'It illustrates alliteration.', true, '2026-09-12 11:10:53.344', '2026-09-12 11:10:53.344', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('af321376-7dcd-497f-b638-00818a97c6b2', 'Literature in English', 'JAMB', null, 2026, null, 'A mistake committed by the hero which leads to his downfall is known as', null, '["Climax","tragic flaw","comic relief","terse"]', 1, 'A mistake committed by the hero which leads to his downfall is known as a tragic flaw (hamartia). In classical tragedy, the tragic hero is a person of high status who possesses a character flaw (such as pride, jealousy, or ambition) that leads to their downfall. The climax is the turning point of the plot, comic relief is a humorous scene in a tragedy, and terse means brief.', true, '2026-09-10 10:45:34.399', '2026-09-10 10:45:34.399', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('af40fe13-ce7b-45e8-83f4-1c46264f36c2', 'Physics', 'JAMB', null, 1987, null, 'The lowest note emitted by a stretched string has a frequency of 40 Hz. How many overtones are there between 40 Hz and 150 Hz?', null, '["1","2","3","4."]', 1, 'Overtones of a string are at 80, 120, 160 Hz... Only 80 Hz and 120 Hz lie between 40 and 150 Hz, giving 2.', true, '2026-10-12 19:15:25.815', '2026-10-12 19:15:25.815', null, null, null, 'The lowest note emitted by a stretched string has a frequency of 40 Hz. How many overtones are there between 40 Hz and 150 Hz?', '["1","2","3","4."]', 'Overtones of a string are at 80, 120, 160 Hz... Only 80 Hz and 120 Hz lie between 40 and 150 Hz, giving 2.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('af49162c-007b-427b-8486-29b2ca353f59', 'Physics', 'JAMB', null, 2026, null, 'A wheelbarrow inclined at 30° to the horizontal is pushed with a force of 150N. What is the horizontal component of the applied force?', null, '["130N","75N","60N","50N"]', 0, 'Horizontal component = F cos θ = 150 cos 30° = 150 × 0.866 = 130N.', true, '2026-09-10 10:56:44.064', '2026-09-10 10:56:44.064', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('af4a05e4-dc17-4c20-a2a4-0229c4894c09', 'English Language', 'JAMB', null, 2007, null, 'Sixty percent of the unskilled workers <u>-----</u> yearly by the company.', null, '["are retain","is retained","were retained","are retained"]', 3, 'Plural ''workers'' habitual â†’ are retained.', true, '2026-10-24 01:04:27.575', '2026-10-24 01:04:27.575', null, null, null, 'Sixty percent of the unskilled workers <u>-----</u> yearly by the company.', '["are retain","is retained","were retained","<u>are retained</u>"]', 'Plural ''<b>workers</b>'' habitual â†’ <b>are retained</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('af4edbae-a5b4-46ef-b2d8-1b2f0007f8fa', 'English Language', 'JAMB', null, 2024, null, 'Children are not allowed in the park ______ dark', null, '["at","over","after","in"]', 2, '"After dark" is the correct expression.', true, '2026-09-18 09:43:02.231', '2026-09-18 09:43:02.231', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('af583b8c-84ce-4897-81d7-087d7dd2d65a', 'English Language', 'JAMB', null, 2007, null, 'The quality of your questions which <u>------------</u> always attracted attention <u>------------</u> never been in doubt.', null, '["have/has","have/have","has/has","has/have"]', 0, '''Which'' â†’ questions (have); ''quality'' singular (has).', true, '2026-10-24 01:04:28.73', '2026-10-24 01:04:28.73', null, null, null, 'The quality of your questions which <u>------------</u> always attracted attention <u>------------</u> never been in doubt.', '["<u>have/has</u>","have/have","has/has","has/have"]', '''<b>Which</b>'' â†’ <b>questions</b> (<b>have</b>); ''<b>quality</b>'' singular (<b>has</b>).', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('af5d0a48-c53a-47e9-b0d4-b165dbb64c53', 'Economics', 'JAMB', null, 2026, null, 'Given Demand function: Qd = 5P + 10; Supply function: Qs = 7P - 5. If the price is at N5, the excess demand is', null, '["35","30","10","5","65"]', 3, 'At P = 5: Qd = 5(5) + 10 = 25 + 10 = 35. Qs = 7(5) - 5 = 35 - 5 = 30. Excess demand = Qd - Qs = 35 - 30 = 5. Therefore, the excess demand is 5.', true, '2026-09-10 10:41:20.242', '2026-09-10 10:41:20.242', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('af64b0ba-aabe-47cf-8934-dc8acb72095e', 'English Language', 'JAMB', null, 2024, null, 'The expression ''rocked the boat'' means', null, '["capsized the boat","improved the situation","disturbed the peace","shook the foundation"]', 2, '"Rocked the boat" means disturbed the peace or caused trouble.', true, '2026-09-18 09:24:04.917', '2026-09-18 09:24:04.917', null, null, 'COMPREHENSION', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('af7e4546-84ab-4f84-a432-2f1e5edef449', 'Physics', 'JAMB', null, 2003, null, 'The maximum kinetic energy of the photoelectrons emitted from a metal surface is 0.34 eV. If the work function of the metal surface is 1.83 eV, find the stopping potential.', null, '["1.09 V","2.17 V","0.34 V","1.49 V"]', 2, 'The stopping potential equals the maximum kinetic energy in electron-volts divided by e: 0.34 eV corresponds to 0.34 V.', true, '2026-10-12 19:15:58.015', '2026-10-12 19:15:58.015', null, null, null, 'The maximum kinetic energy of the photoelectrons emitted from a metal surface is 0.34 eV. If the work function of the metal surface is 1.83 eV, find the stopping potential.', '["1.09 V","2.17 V","0.34 V","1.49 V"]', 'The stopping potential equals the maximum kinetic energy in electron-volts divided by e: 0.34 eV corresponds to 0.34 V.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('af816017-c313-498c-a925-448339f1fa73', 'Biology', 'JAMB', null, 2010, null, 'The chromosome number of a cell before and after the process of meiosis is conventionally represented as', null, '["2n - 2n","n - n","n - 2n","2n - n"]', 3, 'Meiosis reduces chromosome number from 2n to n.', true, '2026-10-12 20:59:41.292', '2026-10-12 20:59:41.292', null, null, null, 'The chromosome number of a cell before and after the process of meiosis is conventionally represented as', '["2n - 2n","n - n","n - 2n","2n - n"]', 'Meiosis reduces chromosome number from 2n to n.', '{"bold":["2n to n"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('af85f7af-c80c-4337-b73c-487396074f48', 'Physics', 'JAMB', null, 2001, null, 'A gas with an initial volume of 2 x 10⁻⁶ m³ is allowed to expand to six times its initial volume at a constant pressure of 2 x 10⁵ N m⁻². The work done is', null, '["2.0 J","4.0 J","12.0 J","1.2 J"]', 0, 'ΔV = 5 x 2 x 10⁻⁶ = 10⁻⁵ m³. Work = PΔV = 2 x 10⁵ x 10⁻⁵ = 2.0 J.', true, '2026-10-12 19:15:51.522', '2026-10-12 19:15:51.522', null, null, null, 'A gas with an initial volume of 2 x 10<sup>-6</sup> m<sup>3</sup> is allowed to expand to six times its initial volume at a constant pressure of 2 x 10<sup>5</sup> N m<sup>-2</sup>. The work done is', '["2.0 J","4.0 J","12.0 J","1.2 J"]', 'ΔV = 5 x 2 x 10<sup>-6</sup> = 10<sup>-5</sup> m<sup>3</sup>. Work = PΔV = 2 x 10<sup>5</sup> x 10<sup>-5</sup> = 2.0 J.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('af89f511-b91b-4c24-bc76-e33638d5a0cb', 'Literature in English', 'JAMB', null, 2026, null, 'Expressions or ideas that have been used so often that they lost their expressive power are called', null, '["Cliches","Obsolete","Tautology","Archaic"]', 0, 'They are called cliches.', true, '2026-09-12 11:11:04.268', '2026-09-12 11:11:04.268', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('af950f99-6e63-46a7-9439-0b5def3a30f8', 'Physics', 'JAMB', null, 1998, null, 'A ball is moving at 18 m s⁻¹ in a direction inclined at 60° to the horizontal. The horizontal component of its velocity is', null, '["9√3 m s⁻¹","6√3 m s⁻¹","6√3 m s⁻¹","9 m s⁻¹"]', 3, 'Horizontal component = 18 cos 60° = 18 x 0.5 = 9 m s⁻¹.', true, '2026-10-12 19:15:44.708', '2026-10-12 19:15:44.708', null, null, null, 'A ball is moving at 18 m s<sup>-1</sup> in a direction inclined at 60° to the horizontal. The horizontal component of its velocity is', '["9√3 m s<sup>-1</sup>","6√3 m s<sup>-1</sup>","6√3 m s<sup>-1</sup>","9 m s<sup>-1</sup>"]', 'Horizontal component = 18 cos 60° = 18 x 0.5 = 9 m s<sup>-1</sup>.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('af9b3c97-2e1a-454a-bd21-e5cb35548e92', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The stadium was <u>seething</u> with people when we entered.', null, '["empty","noisy","filled","crowded"]', 0, 'Seething = crowded; opposite = empty.', true, '2026-10-24 07:21:28.766', '2026-10-24 07:21:28.766', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The stadium was <u>seething</u> with people when we entered.', '["empty","noisy","filled","crowded"]', 'Seething = crowded; opposite = empty.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('afb44107-d233-4f00-a097-5a84081db1c1', 'Biology', 'JAMB', null, 2026, null, 'Chemosynthetic organisms are capable of manufacturing their food from simple inorganic substances through the process of', null, '["Oxidation","Denitrification","Reduction","Phosphorylation"]', 0, 'Chemosynthetic organisms manufacture food through oxidation of simple inorganic substances. They obtain energy by oxidizing inorganic compounds such as hydrogen sulfide, ammonia, or iron. This energy is used to fix carbon dioxide into organic compounds. Denitrification is the conversion of nitrates to nitrogen gas. Reduction is the opposite of oxidation. Phosphorylation is the addition of phosphate groups. Chemosynthesis is important in deep-sea hydrothermal vents and other environments where light is unavailable.', true, '2026-09-09 03:19:02.291', '2026-09-09 03:19:02.291', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('afb8335e-ac89-48c9-b7e6-ef9e8dafeac7', 'Hausa', 'JAMB', null, 2010, null, 'Wanda shakuwar abota ta hada ku, shi ne', null, '["aboki","shakiiki","amini","masoyi."]', 2, 'Wanda shakuwar abota ta hada ku shi ne amini.', true, '2026-10-13 10:37:24.197', '2026-10-13 10:37:24.197', null, null, null, 'Wanda shakuwar abota ta hada ku, shi ne', '["aboki","shakiiki","amini","masoyi."]', 'Wanda shakuwar abota ta hada ku shi ne amini.', '{"bold":["amini"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('afb92d79-e73d-4183-b1a1-65d7fcbe8aae', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). My friend <u>is well off</u> nowadays', null, '["My friend is financially sound","My friend is well known to people","My friend is now well","My friend has lost focus"]', 0, '''Well off'' = financially sound.', true, '2026-10-24 01:02:10.1', '2026-10-24 01:02:10.1', null, null, null, '(Choose the most appropriate interpretation). My friend <u>is well off</u> nowadays', '["<u>My friend is financially sound</u>","My friend is well known to people","My friend is now well","My friend has lost focus"]', '''<b>Well off</b>'' = <b>financially sound</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('afbe6180-2208-4818-a4cc-f5a0d8660451', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Kalu is hard to convince because he is an <u>opinionated</u> person.', null, '["imperative","discursive","subjective","objective"]', 3, 'Opinionated = biased; opposite = objective.', true, '2026-10-24 07:21:25.834', '2026-10-24 07:21:25.834', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Kalu is hard to convince because he is an <u>opinionated</u> person.', '["imperative","discursive","subjective","objective"]', 'Opinionated = biased; opposite = objective.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('afc0656e-a856-4bd8-b164-fc6d157523f0', 'Literature in English', 'JAMB', null, 2026, null, '''The family bell summoned us'' is an example of', null, '["apostrophe","personification","allusion","euphemism"]', 1, 'It is personification.', true, '2026-09-12 11:11:09.541', '2026-09-12 11:11:09.541', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('afc28d3c-3d1e-4ee0-9a41-39389d033260', 'Economics', 'JAMB', null, 2026, null, 'The short run can be defined as the period of time during which', null, '["All inputs are fixed","At least one of the firm''s input is fixed","At least two inputs are fixed","All inputs are variable"]', 1, 'In the short run, at least one input is fixed.', true, '2026-09-12 11:00:40.197', '2026-09-12 11:00:40.197', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('afc9e10d-64d4-49b7-b67f-1a714278836c', 'Government', 'JAMB', null, 2026, null, 'The ICJ comprises ______ judges elected for the period of ______ years', null, '["10, 6","15, 7","15, 9","25, 10"]', 2, 'The ICJ comprises 15 judges elected for 9 years.', true, '2026-09-12 11:24:03.141', '2026-09-12 11:24:03.141', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('afdbfa1f-4920-4711-81fd-c55da30e7750', 'Physics', 'JAMB', null, 1983, null, 'The force with which an object is attracted to the earth is called its', null, '["Acceleration","Mass","Gravity","Impulse","Weight"]', 4, 'The gravitational force acting on a body is its weight (W = mg). Mass is the quantity of matter in the body, and impulse is force × time.', true, '2026-10-12 19:15:15.879', '2026-10-12 19:15:15.879', null, null, null, 'The force with which an object is attracted to the earth is called its', '["Acceleration","Mass","Gravity","Impulse","Weight"]', 'The gravitational force acting on a body is its weight (W = mg). Mass is the quantity of matter in the body, and impulse is force × time.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('afe002b8-1ce9-44d7-9ed8-cc6a078c4069', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Abraham''s faith and works were better illustrated when he', null, '["took Lot with him to Canaan","offered his son, Isaac on the altar","parted ways with Lot","spoke with angels"]', 1, 'Abraham''s faith was shown when he offered Isaac on the altar.', true, '2026-09-12 10:41:36.981', '2026-09-12 10:41:36.981', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('afed0f9f-352a-4d10-8323-4bbd954da11c', 'Chemistry', 'JAMB', null, 2026, null, 'An example of aliphatic unsaturated hydrocarbon is?', null, '["Butanol","Propene","Pentane","Benzene"]', 1, 'Propene is an aliphatic unsaturated hydrocarbon.', true, '2026-09-12 11:36:22.488', '2026-09-12 11:36:22.488', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('aff4fc5f-8402-459f-9696-c4ef7076bf26', 'Physics', 'JAMB', null, 1995, null, 'The energy contained in a wire when it is extended by 0.02 m by a force of 500 N is', null, '["5 J","10 J","10³ J","10⁴ J"]', 0, 'Energy = ½Fx = ½ x 500 x 0.02 = 5 J.', true, '2026-10-12 19:15:40.987', '2026-10-12 19:15:40.987', null, null, null, 'The energy contained in a wire when it is extended by 0.02 m by a force of 500 N is', '["5 J","10 J","10<sup>3</sup> J","10<sup>4</sup> J"]', 'Energy = ½Fx = ½ x 500 x 0.02 = 5 J.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('affeb53b-d9ea-4ac8-a60a-1992afe7db6d', 'Biology', 'JAMB', null, 2026, null, 'The most likely first colonizers of bare rock are', null, '["mosses","ferns","lichen","fungi"]', 2, 'Lichens are the most likely first colonizers of bare rock. They are pioneer species in primary succession on rock surfaces. Lichens are symbiotic associations between fungi and algae that can survive on bare rock with minimal nutrients. They produce acids that break down rock, beginning soil formation. Mosses can colonize after lichens have created some organic matter. Ferns require more developed soil. Fungi can grow on rock but typically do not colonize bare rock as effectively as lichens. Lichens are incredibly hardy and can survive extreme conditions.', true, '2026-09-09 03:18:48.107', '2026-09-09 03:18:48.107', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b00332c3-1db3-4412-9f4b-0f3389edcf8d', 'English Language', 'JAMB', null, 2007, null, 'A range of options <u>-----</u> available to the political parties during the recently concluded elections.', null, '["were made","is made","are made","was made"]', 3, 'Singular ''range'' past â†’ was made.', true, '2026-10-24 01:04:27.525', '2026-10-24 01:04:27.525', null, null, null, 'A range of options <u>-----</u> available to the political parties during the recently concluded elections.', '["were made","is made","are made","<u>was made</u>"]', 'Singular ''<b>range</b>'' past â†’ <b>was made</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b00510f9-5992-45e4-8d11-de4adfcb9441', 'Physics', 'JAMB', null, 2004, null, 'Calculate the angle of minimum deviation for a ray which is refracted through an equiangular prism of refractive index 1.4.', null, '["29°","60°","99°","90°"]', 0, 'sin((A + D)/2) = n sin(A/2) = 1.4 x 0.5 = 0.7, so (60° + D)/2 = 44.4° and D ≈ 29°.', true, '2026-10-12 19:15:58.338', '2026-10-12 19:15:58.338', null, null, null, 'Calculate the angle of minimum deviation for a ray which is refracted through an equiangular prism of refractive index 1.4.', '["29°","60°","99°","90°"]', 'sin((A + D)/2) = n sin(A/2) = 1.4 x 0.5 = 0.7, so (60° + D)/2 = 44.4° and D ≈ 29°.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b01690c0-bb2a-433a-a2ba-47403a889d74', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). ''<u>To be in the red</u>'' is to be ______________', null, '["in debt","rich","a socialist","red","dressed in red"]', 0, '''In the red'' means owing money.', true, '2026-10-24 01:02:00.772', '2026-10-24 01:02:00.772', null, null, null, '(Choose the most appropriate interpretation). ''<u>To be in the red</u>'' is to be ______________', '["<u>in debt</u>","rich","a socialist","red","dressed in red"]', '''<b>In the red</b>'' means <b>owing money</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b016a403-cf26-48aa-98d6-fc95a1d5d728', 'Biology', 'JAMB', null, 2026, null, 'Which of the following is NOT a function of the nucleus of a cell?', null, '["It translates genetic information for protein manufacture","It stores and carries hereditary information","It is a reservoir of energy for the cell","It controls the life processes of the cell"]', 2, 'Being a reservoir of energy for the cell is NOT a function of the nucleus. Energy storage and production occur in the mitochondria and cytoplasm. The nucleus functions to: translate genetic information for protein manufacture through transcription and mRNA processing, store and carry hereditary information in DNA, and control the life processes of the cell by regulating gene expression and cell division. The nucleus directs cellular activities but does not store or produce energy directly.', true, '2026-09-09 03:19:05.334', '2026-09-09 03:19:05.334', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b03d490f-c27c-4b38-b5cc-8e1ad08a9412', 'English Language', 'JAMB', null, 2007, null, 'The University has a large collection of sporting <u>__________</u>', null, '["equipment","equipments","costumes","aids"]', 0, 'Correct form: equipment (uncountable).', true, '2026-10-24 07:21:33.952', '2026-10-24 07:21:33.952', null, null, null, 'The University has a large collection of sporting <u>__________</u>', '["equipment","equipments","costumes","aids"]', 'Correct form: equipment (uncountable).', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b05636b8-d1b5-429b-a224-6cbf643b1889', 'English Language', 'JAMB', null, 2024, null, 'From the tone in the passage, it can be inferred that', null, '["The writer sits on the fence as to whether or not smoking of cigarettes causes cancer","Researchers have tried to no avail to establish the fact that smoking of cigarettes causes cancer","The tobacco companies have been unable to ascertain whether or not smoking of cigarettes reasonably causes cancer","Scientific evidence supported cigarette smoking as a causative factor in the etiology of cancer."]', 3, 'The passage reveals that scientific evidence supports cigarette smoking as a causative factor in cancer.', true, '2026-09-18 10:14:27.389', '2026-09-18 10:14:27.389', '517da099-8f3e-4ce4-a114-f53efc5c5835', 1, 'COMPREHENSION', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b05c6f46-b98d-4c64-80cd-c761f3843bb4', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The group of performers thrilled the audience with its peculiar <u>choreography</u>.', null, '["form of dancing","art of theatrics","type of costuming","mode of singing"]', 0, 'Choreography = form of dancing.', true, '2026-10-24 01:04:00.174', '2026-10-24 01:04:00.174', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The group of performers thrilled the audience with its peculiar <u>choreography</u>.', '["<u>form of dancing</u>","art of theatrics","type of costuming","mode of singing"]', '<b>Choreography</b> = <b>form of dancing</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b05cceba-c926-44c2-97c3-652af0608628', 'Literature in English', 'JAMB', null, 2026, null, 'The phrase ''blood and brine'' in the third stanza is an example of', null, '["alliteration","onomatopoeia","assonance","consonance"]', 0, '''Blood and brine'' is alliteration.', true, '2026-09-12 11:13:45.582', '2026-09-12 11:13:45.582', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b0601c71-8c5a-41d6-bd4e-c7f991702f68', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The lawyer pointed out a <u>discrepancy</u> in the two stories.', null, '["similarity","gap","falsehood","difference"]', 0, 'Discrepancy = difference; opposite = similarity.', true, '2026-10-24 07:21:15.4', '2026-10-24 07:21:15.4', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The lawyer pointed out a <u>discrepancy</u> in the two stories.', '["similarity","gap","falsehood","difference"]', 'Discrepancy = difference; opposite = similarity.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b0626ad0-2e9f-4baa-baea-70ce3abc2ae1', 'Biology', 'JAMB', null, 2003, null, 'A peculiar characteristic of mammals is that they', null, '["have teeth","are warm-blooded","have lungs","have sebaceous glands"]', 3, 'Sebaceous glands are unique cutaneous glands found exclusively in mammals.', true, '2026-10-12 20:05:10.512', '2026-10-12 20:05:10.512', null, null, null, 'A peculiar characteristic of mammals is that they', '["have teeth","are warm-blooded","have lungs","have sebaceous glands"]', 'Sebaceous glands are unique cutaneous glands found exclusively in mammals.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b0664988-576d-47e9-9724-427fb5aa867a', 'English Language', 'JAMB', null, 2007, null, 'A wide range of options <u>------------</u> made available to the political parties during the recently concluded elections.', null, '["was","were","are","is"]', 0, 'Singular ''range'' past â†’ was.', true, '2026-10-24 01:04:28.529', '2026-10-24 01:04:28.529', null, null, null, 'A wide range of options <u>------------</u> made available to the political parties during the recently concluded elections.', '["<u>was</u>","were","are","is"]', 'Singular ''<b>range</b>'' past â†’ <b>was</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b08d84b0-74c1-48f7-937f-78c489f27fc7', 'General Mathematics', 'JAMB', null, 2026, null, 'A group consists of 4 girls and 7 boys. In how many ways can a team of 5 members be selected if the team has at least one boy and one girl?', null, '["336","621","441","503"]', 2, 'Total = 11C5 = 462. All boys = 7C5 = 21. All girls = 4C5 = 0. Valid = 462 - 21 = 441.', true, '2026-09-12 11:43:54.336', '2026-09-12 11:43:54.336', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b09537ae-b377-4491-9d8c-0e8f990bba8e', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). The legislator has decided to <u>play second fiddle</u> after he had been walked out of the Assembly for violating basic procedure of the House. This means that the legislator has decided to ______________', null, '["oppose every motion in the House","support every motion in the House","condemn every motion","support the lead given by others","become active in the house"]', 3, '''Play second fiddle'' means take a subordinate role.', true, '2026-10-24 01:02:00.509', '2026-10-24 01:02:00.509', null, null, null, '(Choose the most appropriate interpretation). The legislator has decided to <u>play second fiddle</u> after he had been walked out of the Assembly for violating basic procedure of the House. This means that the legislator has decided to ______________', '["oppose every motion in the House","support every motion in the House","condemn every motion","<u>support the lead given by others</u>","become active in the house"]', '''<b>Play second fiddle</b>'' means take a <b>subordinate role</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b0b0077a-4bba-45cc-967a-c476ba530076', 'Literature in English', 'JAMB', null, 2026, null, 'The Greek word of Comedy is', null, '["Komoidia","Tragoidia","Dran","Ode"]', 0, 'The Greek word for comedy is ''Komoidia.'' It comes from ''komos'' (revelry) and ''ode'' (song), meaning ''song of revelry.'' Greek comedy originated from the drunken revels and fertility rituals associated with Dionysus. Tragoidia is the Greek word for tragedy, dran means to act, and ode means song.', true, '2026-09-10 10:47:54.953', '2026-09-10 10:47:54.953', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b0b884f2-1cf4-4d5c-91c7-48dffe570fa6', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). The senior prefect had to <u>carry the can</u> because he refused to identify the culprit.', null, '["dispose the can of refuse","accept responsibility","he made one of the scape-goats","bear the brunt"]', 1, '''Carry the can'' = accept responsibility.', true, '2026-10-24 01:04:19.271', '2026-10-24 01:04:19.271', null, null, null, '(Choose the most appropriate interpretation). The senior prefect had to <u>carry the can</u> because he refused to identify the culprit.', '["dispose the can of refuse","<u>accept responsibility</u>","he made one of the scape-goats","bear the brunt"]', '''<b>Carry the can</b>'' = <b>accept responsibility</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b0bdd73d-8bd3-4d88-8648-5e671dd50a45', 'General Mathematics', 'JAMB', null, 2026, null, 'In a basket of fruits, there are 6 grapes, 11 bananas and 13 oranges. If one fruit is chosen at random, what is the probability that the fruit is either a grape or a banana?', null, '["17/30","11/30","5/30","7/3"]', 0, 'Total = 30. P(grape or banana) = (6+11)/30 = 17/30.', true, '2026-09-12 11:44:19.772', '2026-09-12 11:44:19.772', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b0c64a83-9b84-41cf-84a8-cc11ef199d02', 'Biology', 'JAMB', null, 2001, null, 'When specimen X is mixed with few drops of iodine solution, the appearance of a blue-black colour confirms X is', null, '["sucrose","glucose","starch","galactose"]', 2, 'Iodine solution gives a blue-black colour with starch.', true, '2026-10-12 20:59:28.33', '2026-10-12 20:59:28.33', null, null, null, 'When specimen X is mixed with few drops of iodine solution, the appearance of a blue-black colour confirms X is', '["sucrose","glucose","starch","galactose"]', 'Iodine solution gives a blue-black colour with starch.', '{"bold":["starch"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b0c89852-fdf6-4ef6-8d8a-2c13fa470067', 'Physics', 'JAMB', null, 1993, null, 'A 40-W instrument has a resistance of 90 ohms. On what voltage should it be operated normally?', null, '["60 V","150 V","225 V","3 600 V"]', 0, 'P = V²/R, so V = √(PR) = √(40 x 90) = √3600 = 60 V.', true, '2026-10-12 19:15:38.459', '2026-10-12 19:15:38.459', null, null, null, 'A 40-W instrument has a resistance of 90 ohms. On what voltage should it be operated normally?', '["60 V","150 V","225 V","3 600 V"]', 'P = V<sup>2</sup>/R, so V = √(PR) = √(40 x 90) = √3600 = 60 V.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b0d4be11-a496-4a9f-a283-b107f360f82b', 'Literature in English', 'JAMB', null, 2026, null, 'The main difference between Drama and prose is that drama is meant to be', null, '["written for silent reading","performed before an audience","narrated by an author","told through description"]', 1, 'Drama is meant to be performed before an audience.', true, '2026-09-12 11:10:11.497', '2026-09-12 11:10:11.497', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b0d9d8a7-207e-4016-951d-cca92f3fcc7a', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The meeting was <u>cancelled</u> because of the convocation.', null, '["brought up","called off","broken off","dropped out","phased out"]', 1, 'Cancelled = called off.', true, '2026-10-24 01:03:53.221', '2026-10-24 01:03:53.221', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The meeting was <u>cancelled</u> because of the convocation.', '["brought up","<u>called off</u>","broken off","dropped out","phased out"]', '<b>Cancelled</b> = <b>called off</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b0de11f7-2546-45db-9457-7a2a1d034e91', 'English Language', 'JAMB', null, 2024, null, 'All of the following served as a relief to political crisis in Nigeria except', null, '["the death of General Sanni Abacha","the appointment of General Abdusalam Abubakar","the ''stepping aside'' of the military president, Ibrahim Babangida","the election of the new president"]', 2, 'The ''stepping aside'' of Ibrahim Babangida did not restore sanity, according to the passage.', true, '2026-09-18 10:13:05.09', '2026-10-24 17:39:10.843', '2708c14b-deb6-44cd-a86f-ce8964db149f', 3, 'COMPREHENSION', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b0e00f71-ec06-4f58-a438-f7e119f89fa0', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The hasty action will bring nothing but <u>discredit</u> to them.', null, '["honour","shame","reward","disgrace"]', 0, 'Discredit = disgrace; opposite = honour.', true, '2026-10-24 07:21:13.312', '2026-10-24 07:21:13.312', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The hasty action will bring nothing but <u>discredit</u> to them.', '["honour","shame","reward","disgrace"]', 'Discredit = disgrace; opposite = honour.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b0efbea7-3263-4c5f-8b2a-2b2e56c2b6e8', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Bola''s parent went through an <u>acrimonious</u> divorce.', null, '["a bitter","an acrid","a sour","a peaceful"]', 3, 'Acrimonious = bitter; opposite = peaceful.', true, '2026-10-24 07:21:28.208', '2026-10-24 07:21:28.208', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Bola''s parent went through an <u>acrimonious</u> divorce.', '["a bitter","an acrid","a sour","a peaceful"]', 'Acrimonious = bitter; opposite = peaceful.', '{}');
