insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b1c1d473-938e-446f-a83d-54cad351b65f', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The mistake brought the show to an <u>ignominious</u> end.', null, '["a good","a palatable","a disgraceful","a satisfactory"]', 2, 'Ignominious = disgraceful.', true, '2026-10-24 01:04:09.876', '2026-10-24 01:04:09.876', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The mistake brought the show to an <u>ignominious</u> end.', '["a good","a palatable","<u>a disgraceful</u>","a satisfactory"]', '<b>Ignominious</b> = <b>a disgraceful</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b1c37734-a460-40e7-b054-d1a098163ce1', 'Chemistry', 'JAMB', null, 2026, null, '''Quicklime'' has the formula', null, '["Ca(OH)₂","CaO","CaCO₃","CaSO₄.2H₂O","CaCl₂"]', 1, 'Quicklime is CaO.', true, '2026-09-12 11:36:13.641', '2026-09-12 11:36:13.641', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b1cf22b8-d97a-4590-800d-4651c1b335ea', 'Biology', 'JAMB', null, 2026, null, 'Which of the following characters is not sex linked?', null, '["albinism","baldness","haemophilia","colour blindness"]', 0, 'Albinism is not sex-linked; it is an autosomal recessive condition. It is controlled by genes on autosomes (non-sex chromosomes) that code for melanin production. Baldness, haemophilia, and colour blindness are sex-linked traits, typically located on the X chromosome. Sex-linked traits show different inheritance patterns in males and females. Albinism can affect both sexes equally and shows typical autosomal recessive inheritance patterns, with affected individuals inheriting two copies of the mutated gene.', true, '2026-09-09 03:18:51.292', '2026-09-09 03:18:51.292', null, null, null, null, null, null, null);
