insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b26a187b-61e1-41eb-99d3-464d90fb6db7', 'Physics', 'JAMB', null, 1992, null, 'The threshold frequency for photoelectric effect depends on the', null, '["Intensity of incident light","Frequency of incident light","Material of the photocathode","Potential difference between the cathode and the anode"]', 2, 'The threshold frequency is f₀ = φ/h, so it depends on the work function of the photocathode material.', true, '2026-10-12 19:15:36.734', '2026-10-12 19:15:36.734', null, null, null, 'The threshold frequency for photoelectric effect depends on the', '["Intensity of incident light","Frequency of incident light","Material of the photocathode","Potential difference between the cathode and the anode"]', 'The threshold frequency is f<sub>0</sub> = φ/h, so it depends on the work function of the photocathode material.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b26ef532-8964-487a-9e63-73c7aad552db', 'Biology', 'JAMB', null, 2001, null, 'Amphibians are normally found', null, '["in water","on moist land","in water and moist land","on dry land and in water"]', 2, 'Amphibians require both aquatic environments and moist terrestrial land to complete their life cycle.', true, '2026-10-12 20:05:08.754', '2026-10-12 20:05:08.754', null, null, null, 'Amphibians are normally found', '["in water","on moist land","in water and moist land","on dry land and in water"]', 'Amphibians require both aquatic environments and moist terrestrial land to complete their life cycle.', '{}');
