insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b28adcc0-d380-432e-a65e-9fe9340af265', 'Biology', 'JAMB', null, 2026, null, 'In Mendelian inheritance, discontinuous characters are controlled by the', null, '["centromere","alleles","chromosome","chromatids"]', 1, 'In Mendelian inheritance, discontinuous characters are controlled by alleles. Discontinuous variation (like flower color, seed shape) is controlled by one or a few genes with distinct alleles. Alleles produce distinct phenotypes with no intermediate forms. The centromere is the constriction point of chromosomes. Chromosomes contain genes, but it is the alleles that determine the expression of traits.', true, '2026-09-09 03:19:22.548', '2026-09-09 03:19:22.548', null, null, null, null, null, null, null);
