insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b29e8437-eb29-4fde-8f0c-3f5a841e524a', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. ''Marcus <u>bears</u> watching;'' remarked Emperor Nero.', null, '["deserves","needs","favours","enjoys"]', 0, 'Bears watching = deserves watching.', true, '2026-10-24 01:03:56.236', '2026-10-24 01:03:56.236', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. ''Marcus <u>bears</u> watching;'' remarked Emperor Nero.', '["<u>deserves</u>","needs","favours","enjoys"]', '<b>Bears watching</b> = <b>deserves watching</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b2a23da9-786d-49ff-9493-e5aee7893343', 'Physics', 'JAMB', null, 1984, null, 'All the heat generated in a 5 Ω resistor by 2 A flowing for 30 seconds is used to evaporate 5 g of liquid at its boiling point. Which of the following is the correct value of the specific latent heat of the liquid?', null, '["120 J","60 J g⁻¹","120 J g⁻¹","1 500 J","1 500 J g⁻¹"]', 2, 'Heat = I²Rt = 4 x 5 x 30 = 600 J. Specific latent heat = 600/5 = 120 J g⁻¹.', true, '2026-10-12 19:15:18.911', '2026-10-12 19:15:18.911', null, null, null, 'All the heat generated in a 5 Ω resistor by 2 A flowing for 30 seconds is used to evaporate 5 g of liquid at its boiling point. Which of the following is the correct value of the specific latent heat of the liquid?', '["120 J","60 J g<sup>-1</sup>","120 J g<sup>-1</sup>","1 500 J","1 500 J g<sup>-1</sup>"]', 'Heat = I<sup>2</sup>Rt = 4 x 5 x 30 = 600 J. Specific latent heat = 600/5 = 120 J g<sup>-1</sup>.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b2bfc5d2-fb87-40e1-945d-f47d9adda004', 'Physics', 'JAMB', null, 1995, null, 'A well-lagged bar of length 100 cm has its ends maintained at 100 °C and 40 °C respectively. What is the temperature at a point 60 cm from the hotter end?', null, '["58 °C","62 °C","64 °C","76 °C"]', 2, 'The temperature gradient is 60 °C per 100 cm = 0.6 °C cm⁻¹. At 60 cm: 100 - 0.6 x 60 = 64 °C.', true, '2026-10-12 19:15:41.522', '2026-10-12 19:15:41.522', null, null, null, 'A well-lagged bar of length 100 cm has its ends maintained at 100 °C and 40 °C respectively. What is the temperature at a point 60 cm from the hotter end?', '["58 °C","62 °C","64 °C","76 °C"]', 'The temperature gradient is 60 °C per 100 cm = 0.6 °C cm<sup>-1</sup>. At 60 cm: 100 - 0.6 x 60 = 64 °C.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b2c4c760-82c3-43d2-af15-229bd28adae5', 'Literature in English', 'JAMB', null, 2026, null, 'The conflict presented in the poem is mainly between', null, '["tradition and modern technology","native culture and foreign influence","rich and poor citizens","government and opposition"]', 1, 'The conflict is between native culture and foreign influence.', true, '2026-09-12 11:10:23.776', '2026-09-12 11:10:23.776', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b2c63b54-2b11-44f6-a65b-ebd804cc3b5b', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The circular <u>supersedes</u> all previous correspondence on the matter.', null, '["supports","displaces","eliminates","circumvent"]', 1, 'Supersedes = displaces.', true, '2026-10-24 01:04:10.417', '2026-10-24 01:04:10.417', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The circular <u>supersedes</u> all previous correspondence on the matter.', '["supports","<u>displaces</u>","eliminates","circumvent"]', '<b>Supersedes</b> = <b>displaces</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b2c8365a-4fbe-4aa4-9e9b-7833b5845c64', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. ''It is very difficult to know who is <u>entitled to</u> essential commodities these days'', observed the mobbed NNSC official.', null, '["qualified for","disqualified from","eligible","worthy of"]', 0, 'Entitled to = qualified for.', true, '2026-10-24 01:03:55.007', '2026-10-24 01:03:55.007', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. ''It is very difficult to know who is <u>entitled to</u> essential commodities these days'', observed the mobbed NNSC official.', '["<u>qualified for</u>","disqualified from","eligible","worthy of"]', '<b>Entitled to</b> = <b>qualified for</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b2c83ade-2c4c-41eb-a69d-6413bd6d629a', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Little Ugochi has a bicycle which is in <u>marvelous</u> condition.', null, '["need of a tune up","excellent","questionable","unstable","working"]', 1, 'Marvelous = excellent.', true, '2026-10-24 01:03:53.436', '2026-10-24 01:03:53.436', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Little Ugochi has a bicycle which is in <u>marvelous</u> condition.', '["need of a tune up","<u>excellent</u>","questionable","unstable","working"]', '<b>Marvelous</b> = <b>excellent</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b2d7271f-4d94-4460-bb73-84726be4ac44', 'Physics', 'JAMB', null, 2000, null, 'Total internal reflection occurs when light moves from', null, '["Air to water","Water to glass","A dense medium to a less dense medium","A less dense medium to a dense medium"]', 2, 'Total internal reflection requires light to travel from an optically denser to a less dense medium at an angle greater than the critical angle.', true, '2026-10-12 19:15:49.481', '2026-10-12 19:15:49.481', null, null, null, 'Total internal reflection occurs when light moves from', '["Air to water","Water to glass","A dense medium to a less dense medium","A less dense medium to a dense medium"]', 'Total internal reflection requires light to travel from an optically denser to a less dense medium at an angle greater than the critical angle.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b2e19f4a-dcd5-42b9-9873-614578a74bd1', 'Biology', 'JAMB', null, 2003, null, 'The umbrella-shaped fruiting body of a fully developed mushroom is the', null, '["pileus","mycelium","basidium","stipe"]', 0, 'The cap of a mushroom is scientifically called the pileus.', true, '2026-10-12 20:05:09.251', '2026-10-12 20:05:09.251', null, null, null, 'The umbrella-shaped fruiting body of a fully developed mushroom is the', '["pileus","mycelium","basidium","stipe"]', 'The cap of a mushroom is scientifically called the pileus.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b2e6236e-4d8a-430b-9d21-09902a676f00', 'Economics', 'JAMB', null, 2026, null, 'The multiplier is always the reciprocal of', null, '["MPC","MPS","APC","APS"]', 1, 'The multiplier is always the reciprocal of MPS (Marginal Propensity to Save). Multiplier = 1 / MPS = 1 / (1 - MPC). The multiplier measures the change in national income resulting from a change in autonomous spending. A higher MPS means a lower multiplier because more income is saved (leaked) rather than spent. The APC and APS are average propensities, not used in the multiplier formula.', true, '2026-09-10 10:42:55.026', '2026-09-10 10:42:55.026', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b2f8bf05-3b4e-4f55-a6d0-bb64d8e7e025', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). The accounts clerk was jailed because he <u>cooked the books</u>.', null, '["set fire to the account books","sold the books in his office to get money for food","falsified the accounts to his advantage","destroyed the account books by cooking them"]', 2, '''Cooked the books'' = falsified accounts.', true, '2026-10-24 01:04:17.393', '2026-10-24 01:04:17.393', null, null, null, '(Choose the most appropriate interpretation). The accounts clerk was jailed because he <u>cooked the books</u>.', '["set fire to the account books","sold the books in his office to get money for food","<u>falsified the accounts to his advantage</u>","destroyed the account books by cooking them"]', '''<b>Cooked the books</b>'' = <b>falsified accounts</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b2fdb041-664b-449c-9a16-c39ab355fa2d', 'Physics', 'JAMB', null, 2001, null, 'When a piece of rectangular glass block is inserted between two parallel plate capacitor plates, at constant plate area and distance of separation, the capacitance of the capacitor will', null, '["Increase","Decrease","Decrease, then increase","Remain constant"]', 0, 'Glass is a dielectric with relative permittivity greater than 1, so the capacitance increases.', true, '2026-10-12 19:15:52.009', '2026-10-12 19:15:52.009', null, null, null, 'When a piece of rectangular glass block is inserted between two parallel plate capacitor plates, at constant plate area and distance of separation, the capacitance of the capacitor will', '["Increase","Decrease","Decrease, then increase","Remain constant"]', 'Glass is a dielectric with relative permittivity greater than 1, so the capacitance increases.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b309946f-7f86-4f03-bb6d-1aa070509e7f', 'Chemistry', 'JAMB', null, 2026, null, 'Which of the following mixtures is the synthetic gas (I) CO & 3H₂ (II) CO & N₂ (III) CO & H₂ (IV) CO₂ & 3H₂O', null, '["I","II","None except III","IV"]', 2, 'Synthetic gas (syngas) is a mixture of CO and H₂.', true, '2026-09-12 11:36:08.463', '2026-09-12 11:36:08.463', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b31a8eef-8862-403e-a533-366969436eec', 'Literature in English', 'JAMB', null, 2026, null, 'The character of Chaoticleer is a satire of', null, '["the humble farmer","the chivalrous knight","the wise old man","the pious monk"]', 2, 'Chaoticleer satirizes the wise old man.', true, '2026-09-12 11:11:00.073', '2026-09-12 11:11:00.073', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b31caa14-27de-482a-aadb-04c4e6775b93', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The policeman was asked to <u>investigate</u> the matter.', null, '["ask about","forget about","examine","inquire about"]', 1, 'Investigate = examine; opposite = forget about.', true, '2026-10-24 07:21:13.413', '2026-10-24 07:21:13.413', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The policeman was asked to <u>investigate</u> the matter.', '["ask about","forget about","examine","inquire about"]', 'Investigate = examine; opposite = forget about.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b324c463-1af9-46a3-a0e5-92e62cd51f9d', 'Government', 'JAMB', null, 2026, null, 'The National Congress of British West Africa (NCBWA) was founded in', null, '["Sierra Leone","Liberia","Ghana","Nigeria"]', 2, 'The NCBWA was founded in Ghana (Gold Coast) in 1920.', true, '2026-09-12 11:23:58.141', '2026-09-12 11:23:58.141', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b32c6419-74fc-4b38-b213-a8837442edf5', 'Government', 'JAMB', null, 2026, null, 'All but one of the following includes the characteristics of a civil service', null, '["Impartiality","Political neutrality","Permanence","Functionality"]', 3, 'Functionality is not a characteristic of the civil service. The characteristics of the civil service include impartiality (treating all citizens equally), political neutrality (serving any government in power), and permanence (continuing in office regardless of changes in government). Functionality is a general term applicable to many organizations, not a specific characteristic of the civil service.', true, '2026-09-10 10:45:05.288', '2026-09-10 10:45:05.288', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b32fa2b3-e14a-4cba-87b8-8797c2b5a5b3', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The president has sent his <u>regrets</u>. He is unable to attend the meeting.', null, '["explanation","anxieties","unhappiness","apologies"]', 3, 'Regrets = apologies.', true, '2026-10-24 01:03:58.242', '2026-10-24 01:03:58.242', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The president has sent his <u>regrets</u>. He is unable to attend the meeting.', '["explanation","anxieties","unhappiness","<u>apologies</u>"]', '<b>Regrets</b> = <b>apologies</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b33182bf-e1c1-492a-8499-8b45d17466b5', 'Physics', 'JAMB', null, 2026, null, 'A man climbs slowly at a steady speed to the top of a ladder. What is the main energy transfer taking place for the man as he climbs?', null, '["chemical potential to gravitational potential","chemical potential to kinetic","kinetic to gravitational potential","thermal (heat) to kinetic"]', 0, 'The main energy transfer as a man climbs a ladder is from chemical potential energy (from food) to gravitational potential energy. At steady speed, there is no change in kinetic energy. The chemical energy in muscles is converted to gravitational potential energy.', true, '2026-09-10 10:56:44.495', '2026-09-10 10:56:44.495', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b360b15e-1f31-4914-91cc-85d82286ddd9', 'Literature in English', 'JAMB', null, 2026, null, 'One of the following terms applies to the discussion of both tragedy and comedy;', null, '["climax","tragic hero","Epilogue","happy ending"]', 0, 'Climax applies to both tragedy and comedy.', true, '2026-09-12 11:06:26.309', '2026-09-12 11:06:26.309', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b3623708-29ee-41b5-9efe-89407869c720', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. It has been a <u>fraught</u> day.', null, '["difficult","pleasant","wonderful","solemn"]', 0, 'Fraught = difficult.', true, '2026-10-24 01:04:11.169', '2026-10-24 01:04:11.169', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. It has been a <u>fraught</u> day.', '["<u>difficult</u>","pleasant","wonderful","solemn"]', '<b>Fraught</b> = <b>difficult</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b386a0b3-b6a7-4926-9380-a93e8d5a6fb3', 'English Language', 'JAMB', null, 2007, null, 'One of the women who <u>------------</u> in the premises, <u>------------</u> been ordered to quit.', null, '["sell/has","sell/have","sells/has","sells/have"]', 0, '''Who'' â†’ women (sell); ''one'' â†’ has.', true, '2026-10-24 01:02:15.712', '2026-10-24 01:02:15.712', null, null, null, 'One of the women who <u>------------</u> in the premises, <u>------------</u> been ordered to quit.', '["<u>sell/has</u>","sell/have","sells/has","sells/have"]', '''<b>Who</b>'' â†’ <b>women</b> (<b>sell</b>); ''<b>one</b>'' â†’ <b>has</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b39bd5a1-4b0b-454f-9e15-caf021759439', 'Economics', 'JAMB', null, 2026, null, 'A perfectly competitive firm produces the most profitable output where its', null, '["marginal revenue equals average cost","price equals average cost","price equals marginal cost","marginal cost equals marginal revenue","average revenue equals average cost"]', 3, 'In perfect competition, profit is maximized where marginal cost (MC) equals marginal revenue (MR). Since price equals marginal revenue under perfect competition, this is also where price equals marginal cost. At this point, the firm cannot increase profit by producing more or less. If MR > MC, the firm should produce more; if MR < MC, the firm should produce less.', true, '2026-09-10 10:41:19.292', '2026-09-10 10:41:19.292', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b39cf9f6-9e57-4547-b47c-fd5ecabb9b2a', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Joseph was sold to the Ishmaelites for ___ shekels of silver', null, '["forty","thirty-five","thirty","twenty-five","twenty"]', 4, 'Joseph was sold for twenty shekels of silver.', true, '2026-09-12 10:41:10.795', '2026-09-12 10:41:10.795', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b3a9365a-c4a0-49a0-9818-21ed84535f2e', 'English Language', 'JAMB', null, 2024, null, '(Choose the appropriate stress pattern)', null, '["sugeSTible","SUggestible","suGGEstible","sugestibleLE"]', 1, 'The stress in "suggestible" is on the second syllable: sug-GEST-i-ble.', true, '2026-09-18 09:34:04.001', '2026-09-18 09:34:04.001', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b3b0c394-5e26-42e3-9895-b70bf8076598', 'Economics', 'JAMB', null, 2026, null, 'If the population of a school is 600 and 60% are in JSS, how many students are in SSS?', null, '["200","204","220","240"]', 3, 'SSS = 40% of 600 = 240.', true, '2026-09-12 11:01:28.773', '2026-09-12 11:01:28.773', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b3b2abf6-c6af-4652-84a2-04ce936e9066', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. My nephew came in <u>stealthily</u> through the back gate.', null, '["briskly","boldly","wearily","quietly"]', 3, 'Stealthily = quietly and secretly.', true, '2026-10-24 01:03:55.327', '2026-10-24 01:03:55.327', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. My nephew came in <u>stealthily</u> through the back gate.', '["briskly","boldly","wearily","<u>quietly</u>"]', '<b>Stealthily</b> = <b>quietly</b> and secretly.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b3b99950-7bae-481d-869d-3c3c9c747476', 'Literature in English', 'JAMB', null, 2026, null, 'The expression ''the knights arrived at night'' is known as', null, '["Pun","Satire","Metaphor","Simile"]', 0, 'The expression is a pun.', true, '2026-09-12 11:10:50.52', '2026-09-12 11:10:50.52', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b3bb21e5-f8e2-456b-82e4-9d06625950b2', 'Economics', 'JAMB', null, 2026, null, 'The use of taxation and government expenditure to regulate economic activity is called', null, '["Monetary policy","Physical policy","money policy","Fiscal policy"]', 3, 'Fiscal policy uses taxation and government expenditure to regulate the economy.', true, '2026-09-12 11:00:54.854', '2026-09-12 11:00:54.854', null, null, null, null, null, null, null);
