insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b4644dd9-251e-45c5-b530-9c3499b373f2', 'Physics', 'JAMB', null, 1992, null, 'A block of ice floats on water inside a container. If the block of ice gets completely melted, the level of water in the container will', null, '["Increase","Remain the same","Decrease","First decrease and then increase."]', 1, 'The floating ice displaces water equal to its weight. When it melts, the water formed has exactly the same volume, so the level stays the same.', true, '2026-10-12 19:15:35.497', '2026-10-12 19:15:35.497', null, null, null, 'A block of ice floats on water inside a container. If the block of ice gets completely melted, the level of water in the container will', '["Increase","Remain the same","Decrease","First decrease and then increase."]', 'The floating ice displaces water equal to its weight. When it melts, the water formed has exactly the same volume, so the level stays the same.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b4681e2b-052b-4285-94e8-a4f1ee6d5104', 'Financial Accounting', 'UTME', null, 2002, null, 'A company operating a chain of retail provision stores invoices to the branches at cost plus a mark-up of 25%. What is the mark-up percentage on selling price?', null, '["15%","20%","25%","30%"]', 1, 'Let the cost price be 100%, mark-up 25% (given). Invoice = (100 + 25)% = 125%. Mark-up% to selling price = 25/125 x 100 = 20%.', true, '2026-10-12 21:59:58.35', '2026-10-12 21:59:58.35', null, null, null, 'A company operating a chain of retail provision stores invoices to the branches at cost plus a mark-up of 25%. What is the mark-up percentage on selling price?', '["15%","<b>20%</b>","25%","30%"]', 'Let the cost price be 100%, mark-up 25% (given). Invoice = (100 + 25)% = 125%. Mark-up% to selling price = 25/125 x 100 = <b>20%</b>.', '{"bold":["20%"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b46c9091-4afd-4af8-911c-3ae2ca1d11ed', 'Physics', 'JAMB', null, 1994, null, 'The note produced by a stretched string has a fundamental frequency of 400 Hz. If the length of the string is doubled while the tension in the string is increased by a factor of 4, the frequency is', null, '["200 Hz","400 Hz","800 Hz","1600 Hz"]', 1, 'f is proportional to √T/L. Doubling L halves f, and multiplying T by 4 doubles it, so the frequency stays at 400 Hz.', true, '2026-10-12 19:15:39.858', '2026-10-12 19:15:39.858', null, null, null, 'The note produced by a stretched string has a fundamental frequency of 400 Hz. If the length of the string is doubled while the tension in the string is increased by a factor of 4, the frequency is', '["200 Hz","400 Hz","800 Hz","1600 Hz"]', 'f is proportional to √T/L. Doubling L halves f, and multiplying T by 4 doubles it, so the frequency stays at 400 Hz.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
