insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b4f06bd3-bfc1-4c76-9b3c-91ae98136cc0', 'Literature in English', 'JAMB', null, 2026, null, 'The aim of caricature is to', null, '["expose","describe","ridicule","emphasis"]', 2, 'The aim of caricature is to ridicule.', true, '2026-09-12 11:11:04.516', '2026-09-12 11:11:04.516', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b506cbf1-bdc5-4f06-92cc-d2562b1410df', 'Literature in English', 'JAMB', null, 2026, null, 'The major part of the Petrarchan sonnet is the', null, '["octave","sestet","quatrain","tercet"]', 0, 'The octave is the major part of the Petrarchan sonnet.', true, '2026-09-12 11:11:05.023', '2026-09-12 11:11:05.023', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b50c4a8e-f00d-4857-986c-c5ac48051585', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Lami normally <u>scurries</u> around town', null, '["scampers","dashes","dawdles","scuttles"]', 2, 'Scurries = hurries; opposite = dawdles.', true, '2026-10-24 07:21:31.274', '2026-10-24 07:21:31.274', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Lami normally <u>scurries</u> around town', '["scampers","dashes","dawdles","scuttles"]', 'Scurries = hurries; opposite = dawdles.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b50caf10-ad0e-4d6f-8bff-5414da826921', 'Physics', 'JAMB', null, 1991, null, 'A 20 kg mass is to be pulled up a slope inclined at 30° to the horizontal. If the efficiency of the plane is 75%, the force required to pull the load up the plane is', null, '["13.3 N","73.5 N","133.3 N","533.2 N"]', 2, 'Ideal force = mg sin 30° = 20 x 10 x 0.5 = 100 N. Actual force = 100/0.75 = 133.3 N.', true, '2026-10-12 19:15:32.812', '2026-10-12 19:15:32.812', null, null, null, 'A 20 kg mass is to be pulled up a slope inclined at 30° to the horizontal. If the efficiency of the plane is 75%, the force required to pull the load up the plane is', '["13.3 N","73.5 N","133.3 N","533.2 N"]', 'Ideal force = mg sin 30° = 20 x 10 x 0.5 = 100 N. Actual force = 100/0.75 = 133.3 N.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b519c9a6-5fba-464c-9397-7901e0bd4b69', 'Biology', 'JAMB', null, 2026, null, 'All living organism', null, '["photosynthesize","respire","move","feed","transpire"]', 1, 'All living organisms respire. Respiration is the fundamental process by which organisms release energy from organic compounds. It occurs in all living cells, whether aerobic (using oxygen) or anaerobic (without oxygen). Not all organisms photosynthesize (only plants, algae, and some bacteria). Not all organisms move (plants do not move from place to place, though they may show growth movements). Not all organisms feed in the same way (autotrophs make their own food). Not all organisms transpire (transpiration is specific to plants). Respiration is universal to life.', true, '2026-09-09 03:18:48.76', '2026-09-09 03:18:48.76', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b52e0766-d95f-4349-a749-f85c1f847af0', 'English Language', 'JAMB', null, 2007, null, 'The attitude of my students to <u>__________</u> baffles me.', null, '["pronunciation","pronounciation","pronounceation","pronouncciation"]', 0, 'Correct spelling: pronunciation.', true, '2026-10-24 07:21:33.702', '2026-10-24 07:21:33.702', null, null, null, 'The attitude of my students to <u>__________</u> baffles me.', '["pronunciation","pronounciation","pronounceation","pronouncciation"]', 'Correct spelling: pronunciation.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b52f2ffa-3122-46c8-b06c-340f6f39c607', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Governing a country is not always as <u>straightforward</u> as people sometimes imagine.', null, '["troublesome","untoward","irksome","complicated"]', 3, 'Straightforward = simple; opposite = complicated.', true, '2026-10-24 07:21:26.436', '2026-10-24 07:21:26.436', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Governing a country is not always as <u>straightforward</u> as people sometimes imagine.', '["troublesome","untoward","irksome","complicated"]', 'Straightforward = simple; opposite = complicated.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b541fee2-2b74-47b2-ad22-13d6e6b99ea8', 'Physics', 'JAMB', null, 2002, null, 'Two forces each of 10 N act on a body, one towards north and the other towards the east. The magnitude and the direction of the resultant force are', null, '["20 N, 45° W","10√2 N, 45° W","10√2 N, 45° E","20 N, 45° E"]', 2, 'The forces are at right angles, so R = √(10² + 10²) = 10√2 N, directed north-east, 45° east of north.', true, '2026-10-12 19:15:53.161', '2026-10-12 19:15:53.161', null, null, null, 'Two forces each of 10 N act on a body, one towards north and the other towards the east. The magnitude and the direction of the resultant force are', '["20 N, 45° W","10√2 N, 45° W","10√2 N, 45° E","20 N, 45° E"]', 'The forces are at right angles, so R = √(10<sup>2</sup> + 10<sup>2</sup>) = 10√2 N, directed north-east, 45° east of north.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b54cda5c-ffd4-48fe-a62d-192071f1a983', 'Financial Accounting', 'UTME', null, 2001, null, 'Partners'' salaries and drawings are usually posted to the', null, '["trading account","current account","profit and loss account","balance sheet"]', 1, 'Partners'' salaries and drawings are usually posted to the current account.', true, '2026-10-12 22:00:07.029', '2026-10-12 22:00:07.029', null, null, null, 'Partners'' salaries and drawings are usually posted to the', '["trading account","<b>current account</b>","profit and loss account","balance sheet"]', 'Partners'' salaries and drawings are usually posted to the <b>current account</b>.', '{"bold":["current account"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b54cf87d-6f1f-4b88-834d-99b33ff5ea27', 'Chemistry', 'JAMB', null, 2026, null, 'Which of the following is a physical change?', null, '["Rusting of iron","Burning of wood","Melting of ice","Digestion of food"]', 2, 'Melting of ice is a physical change because it involves a change of state only; no new substance is formed.', true, '2026-09-12 11:32:53.826', '2026-09-12 11:32:53.826', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b54f9b51-aa86-45e0-8ddb-ac56b02a445c', 'Biology', 'JAMB', null, 2012, null, 'Organisms living in an estuarine habitat are adapted to', null, '["withstand wide fluctuations in temperature","survive only in water with low salinity","withstand wide fluctuations in salinity","feed only on phytoplankton and dead organic matter."]', 2, 'Estuarine organisms withstand wide fluctuations in salinity.', true, '2026-10-12 20:59:45.147', '2026-10-12 20:59:45.147', null, null, null, 'Organisms living in an estuarine habitat are adapted to', '["withstand wide fluctuations in temperature","survive only in water with low salinity","withstand wide fluctuations in salinity","feed only on phytoplankton and dead organic matter."]', 'Estuarine organisms withstand wide fluctuations in salinity.', '{"bold":["withstand wide fluctuations in salinity"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b5507277-b569-40e1-9174-97a6a0e6e5f7', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'The Macedonians who travelled with Paul to Ephesus were', null, '["Demetrius and Alexander","Alexander and Gaius","Demetrius and Aristarchus","Gaius and Aristarchus"]', 3, 'Gaius and Aristarchus were Paul''s Macedonian companions.', true, '2026-09-12 10:41:56.08', '2026-09-12 10:41:56.08', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b5512a40-20b4-412c-b088-ae81861613c5', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). I would like to believe that this brilliant performance of yours is not just <u>a flash in the pan</u>.', null, '["repeated occurrence","normal happening","flashy happening","chance occurrence"]', 3, '''Flash in the pan'' = one-off chance occurrence.', true, '2026-10-24 01:02:05.219', '2026-10-24 01:02:05.219', null, null, null, '(Choose the most appropriate interpretation). I would like to believe that this brilliant performance of yours is not just <u>a flash in the pan</u>.', '["repeated occurrence","normal happening","flashy happening","<u>chance occurrence</u>"]', '''<b>Flash in the pan</b>'' = <b>one-off chance occurrence</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b556ead8-bca6-460e-9362-706aca6c804d', 'Physics', 'JAMB', null, 1984, null, 'If a solid changes directly into a gas when heat is applied the process is called', null, '["Vaporization","Evaporation","Sublimation","Ionization","Conversion."]', 2, 'Direct change from solid to gas without passing through the liquid state is sublimation.', true, '2026-10-12 19:15:19.236', '2026-10-12 19:15:19.236', null, null, null, 'If a solid changes directly into a gas when heat is applied the process is called', '["Vaporization","Evaporation","Sublimation","Ionization","Conversion."]', 'Direct change from solid to gas without passing through the liquid state is sublimation.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b558610c-5444-4b13-ad40-9eabf0eee5a3', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Laraba saw a <u>forlorn</u> little figure sitting outside the class.', null, '["wise and intelligent","lonely and unhappy","smart and healthy","short and ugly"]', 1, 'Forlorn = lonely and unhappy.', true, '2026-10-24 01:04:10.363', '2026-10-24 01:04:10.363', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Laraba saw a <u>forlorn</u> little figure sitting outside the class.', '["wise and intelligent","<u>lonely and unhappy</u>","smart and healthy","short and ugly"]', '<b>Forlorn</b> = <b>lonely and unhappy</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b558f7a9-fd23-4227-bba7-e8d524590f5c', 'Physics', 'JAMB', null, 2002, null, 'A body weighing 80 N stands in an elevator that is about to move. The force exerted by the floor on the body as the elevator moves upwards with an acceleration of 5 m s⁻² is [g = 10 m s⁻²]', null, '["120 N","40 N","160 N","80 N"]', 0, 'm = 8 kg. R - mg = ma, so R = 8(10 + 5) = 120 N.', true, '2026-10-12 19:15:53.107', '2026-10-12 19:15:53.107', null, null, null, 'A body weighing 80 N stands in an elevator that is about to move. The force exerted by the floor on the body as the elevator moves upwards with an acceleration of 5 m s<sup>-2</sup> is [g = 10 m s<sup>-2</sup>]', '["120 N","40 N","160 N","80 N"]', 'm = 8 kg. R - mg = ma, so R = 8(10 + 5) = 120 N.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b55c4d42-f3d8-47bd-bda4-c9df2c43df38', 'Physics', 'JAMB', null, 2000, null, 'If the frequency of emitted x-rays is 1.6 x 10¹⁶ Hz, the accelerating potential is (h = 6.63 x 10⁻³⁴ J s, e = 1.6 x 10⁻¹⁹ C)', null, '["6.6 V","66.3 V","663.0 V","6630.0 V"]', 1, 'eV = hf, so V = hf/e = (6.63 x 10⁻³⁴ x 1.6 x 10¹⁶)/(1.6 x 10⁻¹⁹) = 66.3 V.', true, '2026-10-12 19:15:50.61', '2026-10-12 19:15:50.61', null, null, null, 'If the frequency of emitted x-rays is 1.6 x 10<sup>16</sup> Hz, the accelerating potential is (h = 6.63 x 10<sup>-34</sup> J s, e = 1.6 x 10<sup>-19</sup> C)', '["6.6 V","66.3 V","663.0 V","6630.0 V"]', 'eV = hf, so V = hf/e = (6.63 x 10<sup>-34</sup> x 1.6 x 10<sup>16</sup>)/(1.6 x 10<sup>-19</sup>) = 66.3 V.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b5659ad8-f94d-4168-8da7-2202576014a9', 'Christian Religious Studies', 'JAMB', null, 2026, null, '''The Lord opened her heart to give heed to what was said by Paul.'' The person who gave heed to the words of Paul was', null, '["Sapphira","Priscilla","Dorcas","Lydia"]', 3, 'Lydia was the seller of purple goods whose heart the Lord opened.', true, '2026-09-12 10:41:57.591', '2026-09-12 10:41:57.591', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b565b63e-1f8f-4322-bd93-55df6df59106', 'Chemistry', 'JAMB', null, 2026, null, 'Calculate the percentage yield if 12g of CO₂ is obtained instead of 16g theoretically expected.', null, '["60%","70%","75%","80%"]', 2, 'Percentage yield = (actual yield / theoretical yield) × 100 = (12/16) × 100 = 75%.', true, '2026-09-12 11:32:54.488', '2026-09-12 11:32:54.488', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b566701d-5f8e-4d41-b689-8c85c8be633f', 'English Language', 'JAMB', null, 2024, null, 'Choose the word or group of words that is nearest in meaning to the underlined words: The ingenious scheme of the robber broke down because of the efficiency of the police officer.', null, '["suspicious","clever","ambitious","dangerous"]', 1, '"Ingenious" means clever, original, and inventive.', true, '2026-09-18 09:23:08.411', '2026-09-18 09:23:08.411', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b56791e6-7d76-4b76-83c8-f733e8ccb7c5', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Mrs Akunilo looks <u>anaemic</u> today.', null, '["strange","sick","weak","strong"]', 3, 'Anaemic = weak; opposite = strong.', true, '2026-10-24 07:21:29.621', '2026-10-24 07:21:29.621', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Mrs Akunilo looks <u>anaemic</u> today.', '["strange","sick","weak","strong"]', 'Anaemic = weak; opposite = strong.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b56cdd9b-2196-4e90-9daf-964780fe0e6d', 'Physics', 'JAMB', null, 1984, null, 'Radio waves have a velocity of 3 x 10⁸ m s⁻¹. A radio station sends out a broadcast on a frequency of 800 kHz. The wavelength of the broadcast is', null, '["375.0 m","267.0 m","240.0 m","37.5 m","26.7 m"]', 0, 'λ = v/f = (3 x 10⁸)/(8 x 10⁵) = 375 m.', true, '2026-10-12 19:15:20.278', '2026-10-12 19:15:20.278', null, null, null, 'Radio waves have a velocity of 3 x 10<sup>8</sup> m s<sup>-1</sup>. A radio station sends out a broadcast on a frequency of 800 kHz. The wavelength of the broadcast is', '["375.0 m","267.0 m","240.0 m","37.5 m","26.7 m"]', 'λ = v/f = (3 x 10<sup>8</sup>)/(8 x 10<sup>5</sup>) = 375 m.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b5724627-b3c6-4f34-a300-1a74c16a7f4a', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The <u>cynics</u> feared that the nation''s nascent democracy would fail.', null, '["pessimists","delinquents","critics","illusionists"]', 0, 'Cynics = pessimists.', true, '2026-10-24 01:01:52.41', '2026-10-24 01:01:52.41', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The <u>cynics</u> feared that the nation''s nascent democracy would fail.', '["<u>pessimists</u>","delinquents","critics","illusionists"]', '<b>Cynics</b> = <b>pessimists</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b57660fe-7335-4606-9978-47128e33b5b2', 'Physics', 'JAMB', null, 2001, null, 'The ratio of the electrostatic force FE to the gravitational force FG between two protons each of charge e and mass m, at a distance d is', null, '["e/(4πε₀Gm)","e²/(Gm²)","Gm²/(4πε₀e²)","e²/(4πε₀Gm²)"]', 3, 'FE = e²/(4πε₀d²) and FG = Gm²/d². The ratio FE/FG = e²/(4πε₀Gm²).', true, '2026-10-12 19:15:52.063', '2026-10-12 19:15:52.063', null, null, null, 'The ratio of the electrostatic force F<sub>E</sub> to the gravitational force F<sub>G</sub> between two protons each of charge e and mass m, at a distance d is', '["e/(4πε<sub>0</sub>Gm)","e<sup>2</sup>/(Gm<sup>2</sup>)","Gm<sup>2</sup>/(4πε<sub>0</sub>e<sup>2</sup>)","e<sup>2</sup>/(4πε<sub>0</sub>Gm<sup>2</sup>)"]', 'F<sub>E</sub> = e<sup>2</sup>/(4πε<sub>0</sub>d<sup>2</sup>) and F<sub>G</sub> = Gm<sup>2</sup>/d<sup>2</sup>. The ratio F<sub>E</sub>/F<sub>G</sub> = e<sup>2</sup>/(4πε<sub>0</sub>Gm<sup>2</sup>).', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b5768238-5f85-435f-a160-4a88f38d3691', 'Physics', 'JAMB', null, 1990, null, 'A wave disturbance travelling in air enters a medium in which its velocity is less than that in air. Which of the following statements is true about the wave in the medium?', null, '["Both the frequency of the wave and the wavelength are decreased.","The frequency of the wave is decreased while the wavelength is increased.","The frequency of the wave is unaltered while the wavelength is decreased.","The frequency of the wave is decreased while the wavelength is unaltered."]', 2, 'Frequency is fixed by the source and does not change. Since v = fλ and v decreases, the wavelength decreases.', true, '2026-10-12 19:15:31.143', '2026-10-12 19:15:31.143', null, null, null, 'A wave disturbance travelling in air enters a medium in which its velocity is less than that in air. Which of the following statements is true about the wave in the medium?', '["Both the frequency of the wave and the wavelength are decreased.","The frequency of the wave is decreased while the wavelength is increased.","The frequency of the wave is unaltered while the wavelength is decreased.","The frequency of the wave is decreased while the wavelength is unaltered."]', 'Frequency is fixed by the source and does not change. Since v = fλ and v decreases, the wavelength decreases.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b57dda5c-03aa-4777-b97b-5414834b8d7f', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. My eldest brother is now faced with the <u>vicissitudes</u> of married life.', null, '["amazement","sweetness","amiability","stability"]', 3, 'Vicissitudes = changes/instability; opposite = stability.', true, '2026-10-24 07:21:19.628', '2026-10-24 07:21:19.628', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. My eldest brother is now faced with the <u>vicissitudes</u> of married life.', '["amazement","sweetness","amiability","stability"]', 'Vicissitudes = changes/instability; opposite = stability.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b5808c12-d453-4459-9e11-0bc63153a1a2', 'Biology', 'JAMB', null, 2001, null, 'Which of the following groups is the most advanced?', null, '["Thallophytes","Pteridophytes","Gymnosperms","Bryophytes"]', 2, 'Gymnosperms are the most advanced among the listed plant groups.', true, '2026-10-12 20:59:27.963', '2026-10-12 20:59:27.963', null, null, null, 'Which of the following groups is the most advanced?', '["Thallophytes","Pteridophytes","Gymnosperms","Bryophytes"]', 'Gymnosperms are the most advanced among the listed plant groups.', '{"bold":["Gymnosperms"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b5854b38-7c2f-4712-876d-666124a09ba9', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The news of his performance in the sessional examination has made Okechukwu <u>crestfallen</u>.', null, '["highly irritable","dejected","elated","pompous"]', 1, 'Crestfallen = dejected.', true, '2026-10-24 01:03:56.289', '2026-10-24 01:03:56.289', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The news of his performance in the sessional examination has made Okechukwu <u>crestfallen</u>.', '["highly irritable","<u>dejected</u>","elated","pompous"]', '<b>Crestfallen</b> = <b>dejected</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b58826d3-3167-42c7-b198-93018dacc614', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'According to Thessalonians, the day of the Lord will not come unless the', null, '["living die first","scoffers come first","dead rise first","rebellion comes first"]', 3, 'The day of the Lord will not come unless the rebellion comes first (2 Thessalonians 2:3).', true, '2026-09-12 10:41:40.92', '2026-09-12 10:41:40.92', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b591093c-d8c9-4ebb-a365-b9eeb9b3b69e', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Man was the last of all that God created but man was crowned by God at creation to be king over all other creatures is not unconnected with', null, '["man''s ability to manage all other creatures","man''s religious in divination","the reflection of God''s image in the nature of man","man''s ability to recreate all that God created originally"]', 2, 'Man was crowned king because of the reflection of God''s image in him.', true, '2026-09-12 10:41:04.142', '2026-09-12 10:41:04.142', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b595886c-b1d2-4466-95bd-781c4d27811a', 'Biology', 'JAMB', null, 2003, null, 'The best method of propagating sugarcane is by', null, '["seed sowing","layering","grafting","stem cuttings"]', 3, 'Sugarcane is commercially and efficiently propagated using stem cuttings.', true, '2026-10-12 20:05:09.76', '2026-10-12 20:05:09.76', null, null, null, 'The best method of propagating sugarcane is by', '["seed sowing","layering","grafting","stem cuttings"]', 'Sugarcane is commercially and efficiently propagated using stem cuttings.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b59a92c4-cfbd-4785-8831-966485b6f05c', 'Chemistry', 'JAMB', null, 2026, null, 'Which factor is most responsible for hydrogen bonding?', null, '["High molar mass","Large atomic radius","High electronegativity and lone pair electrons","High boiling point"]', 2, 'Hydrogen bonding is due to high electronegativity and lone pair electrons on small atoms like N, O, F.', true, '2026-09-12 11:32:57.224', '2026-09-12 11:32:57.224', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b59f849a-ea53-4774-9bda-55505e3e273a', 'Literature in English', 'JAMB', null, 2026, null, 'The term litterateur refers to', null, '["a literary critic","a scholar of science","a person who writes literature","a person who studies languages"]', 2, 'A litterateur is a person who writes literature.', true, '2026-09-12 11:13:48.662', '2026-09-12 11:13:48.662', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b5a26167-f08a-4e14-b5b3-506f5813d4b3', 'English Language', 'JAMB', null, 2024, null, '(opposite in meaning) He is very much respected, though he had no temporal power', null, '["Spiritual","Mundane","Permanent","Ephemeral"]', 0, '"Temporal" means worldly or secular; the opposite is "spiritual."', true, '2026-09-18 09:24:04.77', '2026-09-18 09:24:04.77', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b5bf2637-7c5c-47ed-9a70-89d36fd726ee', 'Physics', 'JAMB', null, 1987, null, 'A boat at anchor is rocked by waves whose crests are 100 m apart and whose velocity is 25 m s⁻¹. At what interval does the wave crest reach the boat?', null, '["2,500.00 s","75.00 s","4.00 s","0.25 s"]', 2, 'Period T = λ/v = 100/25 = 4.00 s.', true, '2026-10-12 19:15:25.707', '2026-10-12 19:15:25.707', null, null, null, 'A boat at anchor is rocked by waves whose crests are 100 m apart and whose velocity is 25 m s<sup>-1</sup>. At what interval does the wave crest reach the boat?', '["2,500.00 s","75.00 s","4.00 s","0.25 s"]', 'Period T = λ/v = 100/25 = 4.00 s.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b5c4fdb6-e4ef-4206-8afe-7789b242ed0c', 'Literature in English', 'JAMB', null, 2026, null, 'The poem is a', null, '["Haiku","Kenning","Limerick","Lyric"]', 3, 'The poem is a lyric.', true, '2026-09-12 11:14:05.276', '2026-09-12 11:14:05.276', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b5ebc3f4-aff6-4545-a79b-362e526e96f2', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. He lost his voice <u>momentarily</u>.', null, '["in a moment","in a split second","for a brief period of time","without delay","instantly"]', 2, 'Momentarily = for a brief period.', true, '2026-10-24 01:01:40.823', '2026-10-24 01:01:40.823', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. He lost his voice <u>momentarily</u>.', '["in a moment","in a split second","<u>for a brief period of time</u>","without delay","instantly"]', '<b>Momentarily</b> = <b>for a brief period</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b5eff80f-fb9c-4c4d-8151-7109592b749c', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). Akin made such <u>a dog''s breakfast</u> of his homework.', null, '["an excellent job","a brilliant attempt","a mess","a poor performance"]', 2, '''A dog''s breakfast'' = a mess.', true, '2026-10-24 01:04:21.201', '2026-10-24 01:04:21.201', null, null, null, '(Choose the most appropriate interpretation). Akin made such <u>a dog''s breakfast</u> of his homework.', '["an excellent job","a brilliant attempt","<u>a mess</u>","a poor performance"]', '''A <b>dog''s breakfast</b>'' = <b>a mess</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b5f36171-720d-43ba-8ea9-9fdb1c90c93d', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Nwankwo was on the <u>verge</u> of signing a two-year contract with the club.', null, '["shore","summit","brink","height"]', 2, 'Verge = brink.', true, '2026-10-24 01:04:10.741', '2026-10-24 01:04:10.741', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Nwankwo was on the <u>verge</u> of signing a two-year contract with the club.', '["shore","summit","<u>brink</u>","height"]', '<b>Verge</b> = <b>brink</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b5fba6a3-4759-4c7a-8a98-b38a2873880e', 'Physics', 'JAMB', null, 2003, null, 'An electron of charge 1.6 x 10⁻¹⁹ C is accelerated between two metal plates. If the kinetic energy of the electron is 4.8 x 10⁻¹⁷ J, the potential difference between the plates is', null, '["300 V","30 V","400 V","40 V"]', 0, 'KE = eV, so V = (4.8 x 10⁻¹⁷)/(1.6 x 10⁻¹⁹) = 300 V.', true, '2026-10-12 19:15:57.268', '2026-10-12 19:15:57.268', null, null, null, 'An electron of charge 1.6 x 10<sup>-19</sup> C is accelerated between two metal plates. If the kinetic energy of the electron is 4.8 x 10<sup>-17</sup> J, the potential difference between the plates is', '["300 V","30 V","400 V","40 V"]', 'KE = eV, so V = (4.8 x 10<sup>-17</sup>)/(1.6 x 10<sup>-19</sup>) = 300 V.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b61a9c53-4053-4261-9eb6-191f47bfc36c', 'Physics', 'JAMB', null, 1985, null, 'Which of the following statements is NOT correct?', null, '["Boiling occurs when the saturated vapour pressure of the liquid involved equals the external pressure.","Both the boiling point and the saturated vapour pressure of a given liquid depend on the external pressure.","The saturated vapour pressure rises with increase in temperature.","The saturated vapour pressure is independent of the volume available for the vapour.","It is possible to boil water at a lower temperature than 100 °C at high altitude."]', 1, 'Saturated vapour pressure depends only on temperature, not on the external pressure. The boiling point does depend on external pressure, so B is incorrect.', true, '2026-10-12 19:15:21.581', '2026-10-12 19:15:21.581', null, null, null, 'Which of the following statements is <b>NOT</b> correct?', '["Boiling occurs when the saturated vapour pressure of the liquid involved equals the external pressure.","Both the boiling point and the saturated vapour pressure of a given liquid depend on the external pressure.","The saturated vapour pressure rises with increase in temperature.","The saturated vapour pressure is independent of the volume available for the vapour.","It is possible to boil water at a lower temperature than 100 °C at high altitude."]', 'Saturated vapour pressure depends only on temperature, not on the external pressure. The boiling point does depend on external pressure, so B is incorrect.', '{"bold":["NOT"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b6436ab4-a304-43ad-b0c5-cd56cee61bfe', 'testing', 'JAMB', null, 2024, null, 'The company hired three consultants, all of ..... had extensive experience.', null, '["who","whom","whose","which"]', 1, 'After preposition ''of'', use objective ''whom''.', true, '2026-10-31 16:48:52.615', '2026-10-31 16:48:52.615', null, null, null, 'The company hired three consultants, all of ..... had extensive experience.', '["who","whom","whose","which"]', 'After preposition ''of'', use objective ''whom''.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b64532a5-face-4325-96c3-f270bfca4221', 'English Language', 'JAMB', null, 2007, null, 'Measles <u>------------</u> no longer impossible to manage these days.', null, '["is","are","were","was"]', 0, '''Measles'' singular disease â†’ is.', true, '2026-10-24 01:02:13.698', '2026-10-24 01:02:13.698', null, null, null, 'Measles <u>------------</u> no longer impossible to manage these days.', '["<u>is</u>","are","were","was"]', '''<b>Measles</b>'' singular disease â†’ <b>is</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b6453530-6496-4eb5-a394-747ed8643562', 'English Language', 'JAMB', null, 2007, null, 'Ebun Ojo <u>__________</u> international fame as an actress.', null, '["aquired","acqired","acquired","adquired"]', 2, 'Correct spelling: acquired.', true, '2026-10-24 07:21:33.551', '2026-10-24 07:21:33.551', null, null, null, 'Ebun Ojo <u>__________</u> international fame as an actress.', '["aquired","acqired","acquired","adquired"]', 'Correct spelling: acquired.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b6474c57-2cbf-4901-a331-f023899a45f2', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. They accused him of <u>fomenting</u> political unrest', null, '["inciting","discouraging","preventing","guiding"]', 0, 'Fomenting = inciting.', true, '2026-10-24 01:04:12.401', '2026-10-24 01:04:12.401', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. They accused him of <u>fomenting</u> political unrest', '["<u>inciting</u>","discouraging","preventing","guiding"]', '<b>Fomenting</b> = <b>inciting</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b64982e7-d22e-4153-a459-1aa67c1bc6d4', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Members of the panel were working <u>at cross purposes</u>.', null, '["in harmony","in disunity","for selfish purpose","for selfless purposes"]', 1, 'At cross purposes = in disunity.', true, '2026-10-24 01:01:49.128', '2026-10-24 01:01:49.128', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Members of the panel were working <u>at cross purposes</u>.', '["in harmony","<u>in disunity</u>","for selfish purpose","for selfless purposes"]', '<b>At cross purposes</b> = <b>in disunity</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b64b2de8-4e20-44fe-8fcf-0f9e350e76b4', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The old woman is suffering from <u>dementia</u>.', null, '["lucidity","senility","insanity","sagacity"]', 1, 'Dementia = senility.', true, '2026-10-24 01:04:10.202', '2026-10-24 01:04:10.202', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The old woman is suffering from <u>dementia</u>.', '["lucidity","<u>senility</u>","insanity","sagacity"]', '<b>Dementia</b> = <b>senility</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b64e7e13-3c5f-478e-ad4b-427dd3f39244', 'Economics', 'JAMB', null, 2026, null, 'Which of the following will NOT bring about an increase in Labour force?', null, '["Immigration","Good health facilities","Emigration","Reduced death rate"]', 2, 'Emigration reduces the labour force.', true, '2026-09-12 11:01:31.807', '2026-09-12 11:01:31.807', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b65dfd4e-6ed3-46e7-9e10-04b951f458be', 'General Mathematics', 'JAMB', null, 2026, null, 'A regular polygon has an interior angle that is four times its exterior angle. How many sides does this polygon have?', null, '["16","8","20","10"]', 3, 'Interior = 4E. Interior + E = 180. 5E = 180. E = 36. n = 360/36 = 10.', true, '2026-09-12 11:43:52.759', '2026-09-12 11:43:52.759', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b661ca91-d694-4972-96f0-c4975afe8f14', 'Literature in English', 'JAMB', null, 2026, null, 'In the poem, cupid is', null, '["An illusion","A metonymy","The persona''s mistress","The person''s rival"]', 1, 'Cupid is a metonymy.', true, '2026-09-12 11:11:16.381', '2026-09-12 11:11:16.381', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b66e85ee-4866-4bc7-94be-aed65455c439', 'Financial Accounting', 'UTME', null, 2001, null, 'Given: A Capital 200,000 Total assets 210,000 Liabilities 10,000 210,000 210,000. If the business is purchased at a price including goodwill of N20, 000, what must have been the purchase price?', null, '["190,000","210,000","220,000","230,000"]', 2, 'Purchase price = Capital 200,000 + Goodwill 20,000 = 220,000.', true, '2026-10-12 22:00:07.374', '2026-10-12 22:00:07.374', null, null, null, 'Given: A Capital 200,000 Total assets 210,000 Liabilities 10,000 210,000 210,000. If the business is purchased at a price including goodwill of N20, 000, what must have been the purchase price?', '["190,000","210,000","<b>220,000</b>","230,000"]', 'Purchase price = Capital 200,000 + Goodwill 20,000 = <b>220,000</b>.', '{"bold":["220,000"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b676ee57-385e-43ca-b61f-e2c18fbc48ef', 'Literature in English', 'JAMB', null, 2026, null, 'Where are the characters?', null, '["Alexandria, a room in Cleopatra''s palace","in Rome","on the street","none of the above"]', 0, 'The characters are in Alexandria, a room in Cleopatra''s palace.', true, '2026-09-12 11:14:16.823', '2026-09-12 11:14:16.823', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b6938511-d21a-4c5f-88ec-8756f0349cdc', 'Economics', 'JAMB', null, 2026, null, 'Which of the following is not a function of the money market?', null, '["Provision of finance","enhance loan savings","creation of long term","Provision of finance"]', 2, 'The money market deals with short-term loans, not long-term.', true, '2026-09-12 11:00:59.922', '2026-09-12 11:00:59.922', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b6954e34-8018-4e51-b127-3b538027e6e3', 'Physics', 'JAMB', null, 1989, null, 'An electric heater is used to melt a block of ice, mass 1.5 kg. If the heater is powered by a 12 V battery and a current of 20 A flows through the coil, calculate the time taken to melt the block of ice at 0 °C. (Specific latent heat of fusion of ice = 336 x 10³ J kg⁻¹).', null, '["76.0 min","35.0 min","21.0 min","2.9 min."]', 1, 'Heat needed = mL = 1.5 x 336 000 = 504 000 J. Power = 12 x 20 = 240 W. t = 504 000/240 = 2100 s = 35 min.', true, '2026-10-12 19:15:29.139', '2026-10-12 19:15:29.139', null, null, null, 'An electric heater is used to melt a block of ice, mass 1.5 kg. If the heater is powered by a 12 V battery and a current of 20 A flows through the coil, calculate the time taken to melt the block of ice at 0 °C. (Specific latent heat of fusion of ice = 336 x 10<sup>3</sup> J kg<sup>-1</sup>).', '["76.0 min","35.0 min","21.0 min","2.9 min."]', 'Heat needed = mL = 1.5 x 336 000 = 504 000 J. Power = 12 x 20 = 240 W. t = 504 000/240 = 2100 s = 35 min.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b69e3a46-2c63-4d90-baa6-1f7b339c3292', 'Physics', 'JAMB', null, 1983, null, 'The electrochemical equivalent of a metal is 0.126 x 10⁻⁶ kg/C. The mass of the metal that a current of 5 A deposits from a suitable bath in 1 hour is', null, '["0.0378 x 10⁻³ kg","0.227 x 10⁻³ kg","0.378 x 10⁻³ kg","0.595 x 10⁻³ kg","2.268 x 10⁻³ kg"]', 4, 'm = zIt = (0.126 x 10⁻⁶) x 5 x 3600 = 2.268 x 10⁻³ kg.', true, '2026-10-12 19:15:17.04', '2026-10-12 19:15:17.04', null, null, null, 'The electrochemical equivalent of a metal is 0.126 x 10<sup>-6</sup> kg/C. The mass of the metal that a current of 5 A deposits from a suitable bath in 1 hour is', '["0.0378 x 10<sup>-3</sup> kg","0.227 x 10<sup>-3</sup> kg","0.378 x 10<sup>-3</sup> kg","0.595 x 10<sup>-3</sup> kg","2.268 x 10<sup>-3</sup> kg"]', 'm = zIt = (0.126 x 10<sup>-6</sup>) x 5 x 3600 = 2.268 x 10<sup>-3</sup> kg.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b6a64317-2955-4a64-a900-e47960a349f7', 'Government', 'JAMB', null, 2026, null, 'The term ultra vires means', null, '["the exercise of supervisory functions by the judiciary","a situation where a public authority dutifully performs its functions","a situation where a public authority acts beyond the scope of its duties","the act of exercising administrative competence over a matter"]', 2, 'Ultra vires means acting beyond the scope of one''s duties.', true, '2026-09-12 11:24:52.699', '2026-09-12 11:24:52.699', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b6ac4208-993c-44ca-87bb-c185b365d1c1', 'Literature in English', 'JAMB', null, 2026, null, 'The central thematic concern of Redemption Road is the', null, '["Conflict between tradition and modernity in urban settings","Exploration of justice, trauma, and the possibility of healing after conflict","Rise of capitalist structures in postcolonial Africa","Romantic relationships as tools for social mobility"]', 1, 'The central theme is the exploration of justice, trauma, and the possibility of healing.', true, '2026-09-12 11:04:53.917', '2026-09-12 11:04:53.917', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b6b34175-0329-474b-b67d-4153037fdd9c', 'General Mathematics', 'JAMB', null, 2026, null, 'The time taken to do a piece of work is inversely proportional to the number of men employed. If it takes 45 men to do a piece of work in 5 days, how long will it take 25 men?', null, '["15days","12days","5days","9days","3days"]', 3, 'T = k/n. 5 = k/45. k = 225. T = 225/25 = 9 days.', true, '2026-09-12 11:43:58.72', '2026-09-12 11:43:58.72', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b6b957c5-d549-470c-a304-56987365d5d8', 'Financial Accounting', 'UTME', null, 2002, null, 'Given: N(m) Balance at 31st December 14,744 Treasury Bills issued Jan-Dec 7,124 Revenue for the year 6,387 Expenditure 8,767. What is the opening balance on the consolidated revenue fund account?', null, '["N10,000m","N12,000m","N90,00m","N11,000m"]', 0, 'The opening balance on the consolidated revenue fund account is N10,000m.', true, '2026-10-12 21:59:58.942', '2026-10-12 21:59:58.942', null, null, null, 'Given: N(m) Balance at 31st December 14,744 Treasury Bills issued Jan-Dec 7,124 Revenue for the year 6,387 Expenditure 8,767. What is the opening balance on the consolidated revenue fund account?', '["<b>N10,000m</b>","N12,000m","N90,00m","N11,000m"]', 'The opening balance on the consolidated revenue fund account is <b>N10,000m</b>.', '{"bold":["N10,000m"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b6ba7aa4-44b6-49cb-8e68-5fa1320370df', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). My friend will hate his uncle forever because he <u>left him in the lurch</u> in his hour of need.', null, '["abandoned him","punished him","disinherited him","despised him"]', 0, '''Left in the lurch'' = abandoned.', true, '2026-10-24 01:04:18.68', '2026-10-24 01:04:18.68', null, null, null, '(Choose the most appropriate interpretation). My friend will hate his uncle forever because he <u>left him in the lurch</u> in his hour of need.', '["<u>abandoned him</u>","punished him","disinherited him","despised him"]', '''<b>Left in the lurch</b>'' = <b>abandoned</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b6cb9afb-7a05-433a-a48c-2a8b8eee9f57', 'English Language', 'JAMB', null, 2007, null, 'My mother was <u>__________</u> annoyed with me for coming late.', null, '["very","neither","hotly","just"]', 0, 'Correct form: very annoyed.', true, '2026-10-24 07:21:37.677', '2026-10-24 07:21:37.677', null, null, null, 'My mother was <u>__________</u> annoyed with me for coming late.', '["very","neither","hotly","just"]', 'Correct form: very annoyed.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b6d37a42-5840-496f-8e23-3df4bef4a63a', 'Physics', 'JAMB', null, 1991, null, 'A boy timed 30 oscillations of a certain pendulum thrice and obtained 1 min 10 s, 1 min 12 s and 1 min 7 s respectively. The mean period of oscillation of the pendulum is', null, '["0.14 s","0.43 s","2.32 s","6.97 s"]', 2, 'Times are 70 s, 72 s and 67 s. Mean time = 209/3 = 69.7 s for 30 oscillations. Period = 69.7/30 = 2.32 s.', true, '2026-10-12 19:15:33.407', '2026-10-12 19:15:33.407', null, null, null, 'A boy timed 30 oscillations of a certain pendulum thrice and obtained 1 min 10 s, 1 min 12 s and 1 min 7 s respectively. The mean period of oscillation of the pendulum is', '["0.14 s","0.43 s","2.32 s","6.97 s"]', 'Times are 70 s, 72 s and 67 s. Mean time = 209/3 = 69.7 s for 30 oscillations. Period = 69.7/30 = 2.32 s.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b6d5ab11-19d8-438e-99cf-c43f96b49b7b', 'Biology', 'JAMB', null, 2004, null, 'Which of the following is an example of intraspecific competition?', null, '["a Lizard and an ant-eater chasing an insect","a worker termite and a soldier in a limited space","a hawk and an eagle targeting the same chicken","yam and potato shoots growing out through the same window"]', 1, 'Intraspecific competition occurs between members of the same species.', true, '2026-10-12 20:59:35.989', '2026-10-12 20:59:35.989', null, null, null, 'Which of the following is an example of intraspecific competition?', '["a Lizard and an ant-eater chasing an insect","a worker termite and a soldier in a limited space","a hawk and an eagle targeting the same chicken","yam and potato shoots growing out through the same window"]', 'Intraspecific competition occurs between members of the same species.', '{"bold":["Intraspecific competition"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b6d67d9e-da9d-4acf-aa9a-37339c136537', 'English Language', 'JAMB', null, 2007, null, 'A very popular ruler is at the <u>__________</u>', null, '["helms of affair","helm of affair","realm of affair","helm of affairs"]', 3, 'Correct form: helm of affairs.', true, '2026-10-24 07:21:34.858', '2026-10-24 07:21:34.858', null, null, null, 'A very popular ruler is at the <u>__________</u>', '["helms of affair","helm of affair","realm of affair","helm of affairs"]', 'Correct form: helm of affairs.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b6d994c0-7361-4484-9b91-53b6f7b55b80', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. We travelled to an <u>obscure</u> little town', null, '["rugged","distinguished","secluded","inglorious"]', 1, 'Obscure = little known; opposite = distinguished.', true, '2026-10-24 07:21:31.173', '2026-10-24 07:21:31.173', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. We travelled to an <u>obscure</u> little town', '["rugged","distinguished","secluded","inglorious"]', 'Obscure = little known; opposite = distinguished.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b6e35e8b-ae5c-4345-bb1e-effb023cfdd3', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The material in the book is presented within <u>an eclectic</u> framework.', null, '["simple","a broad","a restricted","clumsy"]', 1, 'Eclectic = broad (drawing from many sources).', true, '2026-10-24 01:04:00.978', '2026-10-24 01:04:00.978', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The material in the book is presented within <u>an eclectic</u> framework.', '["simple","<u>a broad</u>","a restricted","clumsy"]', '<b>Eclectic</b> = <b>a broad</b> (drawing from many sources).', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b706b7e3-3765-4f1a-89d2-3e4877cf83ed', 'Biology', 'JAMB', null, 2026, null, 'The arrangement of ovules attached to the sides of a syncarpous ovary with a single chamber is referred to as', null, '["free-central placentation","axile placentation","parietal placentation","marginal placentation"]', 2, 'Parietal placentation is the arrangement where ovules are attached to the walls (sides) of a syncarpous (fused carpels) ovary with a single chamber. In parietal placentation, the ovules are born on the ovary wall or on inward-growing extensions of the wall. Free-central placentation has ovules on a central column but no septa. Axile placentation has ovules on a central axis with septa. Marginal placentation is typical of legumes with a single carpel. Parietal placentation is found in plants like violet and passionflower.', true, '2026-09-09 03:18:53.894', '2026-09-09 03:18:53.894', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b706bb77-14d8-4d90-a118-e92557b236db', 'English Language', 'JAMB', null, 2007, null, 'Jimoh is noted for his <u>__________</u> attitude to his seniors at school.', null, '["receptive","respective","respectful","respectable"]', 2, 'Correct spelling: respectful.', true, '2026-10-24 07:21:42.761', '2026-10-24 07:21:42.761', null, null, null, 'Jimoh is noted for his <u>__________</u> attitude to his seniors at school.', '["receptive","respective","respectful","respectable"]', 'Correct spelling: respectful.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b712f6f7-8206-468c-a536-ac54da41a261', 'Hausa', 'JAMB', null, 2011, null, '''Balarabe na Balaraba Sannu Balaraba Sai wata rana.'' Me Haruna Uji, ke nuna wa a wannan tsakure?', null, '["Ambaton Balaraba.","Dangantakarsa da Balaraba.","Ban kwana da duniya.","Yabon Balaraba."]', 1, 'Haruna Uji na nuna dangantakarsa da Balaraba a wannan tsakure.', true, '2026-10-13 10:37:22.318', '2026-10-13 10:37:22.318', null, null, null, '''Balarabe na Balaraba Sannu Balaraba Sai wata rana.'' Me Haruna Uji, ke nuna wa a wannan tsakure?', '["Ambaton Balaraba.","Dangantakarsa da Balaraba.","Ban kwana da duniya.","Yabon Balaraba."]', 'Haruna Uji na nuna dangantakarsa da Balaraba a wannan tsakure.', '{"bold":["dangantakarsa da Balaraba"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b71c556a-f930-4c72-8b54-e9f2efe7f488', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. police are not happy with the number of <u>depraving</u> people around the politician.', null, '["indolent","violent","immoral","loquacious"]', 2, 'Depraving = immoral.', true, '2026-10-24 01:04:09.5', '2026-10-24 01:04:09.5', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. police are not happy with the number of <u>depraving</u> people around the politician.', '["indolent","violent","<u>immoral</u>","loquacious"]', '<b>Depraving</b> = <b>immoral</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b72f6998-16cf-48da-874b-049b894bd989', 'Physics', 'JAMB', null, 2004, null, 'To protect a material from the influence of an external magnetic field, the material should be kept in a', null, '["Square steel ring","Loop of copper wire","Triangular zinc ring","Soft iron ring."]', 3, 'Soft iron has a high permeability, so the field lines pass through the iron ring and bypass the space inside it (magnetic screening).', true, '2026-10-12 19:16:00.161', '2026-10-12 19:16:00.161', null, null, null, 'To protect a material from the influence of an external magnetic field, the material should be kept in a', '["Square steel ring","Loop of copper wire","Triangular zinc ring","Soft iron ring."]', 'Soft iron has a high permeability, so the field lines pass through the iron ring and bypass the space inside it (magnetic screening).', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b74de16e-c739-43c9-ae8e-b58d35ee3b48', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The president has sent his <u>regrets</u>. He is unable to attend the meeting.', null, '["explanation","anxieties","unhappiness","apologies"]', 3, 'Regrets = apologies.', true, '2026-10-24 01:01:46.161', '2026-10-24 01:01:46.161', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The president has sent his <u>regrets</u>. He is unable to attend the meeting.', '["explanation","anxieties","unhappiness","<u>apologies</u>"]', '<b>Regrets</b> = <b>apologies</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b76dfbc6-d12d-4b8f-96c1-4dc9f19057dd', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). We <u>made a pile</u> in the business deal.', null, '["cut corners","broke even","earned a lot of money","lost a lot of money"]', 2, '''Made a pile'' = earned a lot of money.', true, '2026-10-24 01:02:09.241', '2026-10-24 01:02:09.241', null, null, null, '(Choose the most appropriate interpretation). We <u>made a pile</u> in the business deal.', '["cut corners","broke even","<u>earned a lot of money</u>","lost a lot of money"]', '''<b>Made a pile</b>'' = <b>earned a lot of money</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b7753363-25e6-49bc-9e49-98bbf379d9a6', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. It is entirely up to you to <u>make a profession of your faith</u>.', null, '["confess your belief","turn your faith into a business","deny your faith","loudly proclaim your religion"]', 2, 'Profession of faith = declaration; opposite = denial.', true, '2026-10-24 07:21:14.835', '2026-10-24 07:21:14.835', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. It is entirely up to you to <u>make a profession of your faith</u>.', '["confess your belief","turn your faith into a business","deny your faith","loudly proclaim your religion"]', 'Profession of faith = declaration; opposite = denial.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b7792dd7-f80d-4511-9a3a-5e7173c171eb', 'Physics', 'JAMB', null, 2001, null, 'A transistor functions mainly as a', null, '["Switch and an amplifier","Rectifier and an amplifier","Charge storer and an amplifier","Charge storer and switch."]', 0, 'A transistor can amplify signals and act as an electronic switch.', true, '2026-10-12 19:15:52.549', '2026-10-12 19:15:52.549', null, null, null, 'A transistor functions mainly as a', '["Switch and an amplifier","Rectifier and an amplifier","Charge storer and an amplifier","Charge storer and switch."]', 'A transistor can amplify signals and act as an electronic switch.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b77b3d49-f7f0-4535-aec5-ee5a8c42244d', 'Physics', 'JAMB', null, 2026, null, 'Which of the following liquid is a poor conductor of electricity?', null, '["Drinking water","Tap water","Sea water","distilled water"]', 3, 'Distilled water is a poor conductor of electricity because it contains no dissolved ions or impurities. Tap water, drinking water, and sea water contain dissolved salts and minerals that provide ions for conduction. Pure water is actually a very poor conductor; it is the dissolved ions that make water conductive.', true, '2026-09-10 10:56:38.324', '2026-09-10 10:56:38.324', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b7801884-deff-4019-85c5-5cd92181a27d', 'Physics', 'JAMB', null, 1986, null, 'Which of the following is most strongly deflected by a magnetic field?', null, '["Gamma rays","Alpha particles","Beta particles","X-rays."]', 2, 'Gamma rays and X-rays are uncharged. Beta particles are charged and very light, so they are deflected much more than the heavy alpha particles.', true, '2026-10-12 19:15:24.542', '2026-10-12 19:15:24.542', null, null, null, 'Which of the following is most strongly deflected by a magnetic field?', '["Gamma rays","Alpha particles","Beta particles","X-rays."]', 'Gamma rays and X-rays are uncharged. Beta particles are charged and very light, so they are deflected much more than the heavy alpha particles.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b7814676-2d40-4ad8-9790-b4e0b5fe1dfd', 'Physics', 'JAMB', null, 1998, null, 'A uniform metre rule weighing 0.5 N is to be pivoted on a knife-edge at the 30 cm mark. Where will a force of 2 N be placed from the pivot to balance the metre rule?', null, '["95 cm","25 cm","20 cm","5 cm"]', 3, 'The rule''s weight acts at the 50 cm mark, 20 cm from the pivot: moment = 0.5 x 20 = 10 N cm. The 2 N force must be at d = 10/2 = 5 cm from the pivot on the opposite side.', true, '2026-10-12 19:15:44.925', '2026-10-12 19:15:44.925', null, null, null, 'A uniform metre rule weighing 0.5 N is to be pivoted on a knife-edge at the 30 cm mark. Where will a force of 2 N be placed from the pivot to balance the metre rule?', '["95 cm","25 cm","20 cm","5 cm"]', 'The rule''s weight acts at the 50 cm mark, 20 cm from the pivot: moment = 0.5 x 20 = 10 N cm. The 2 N force must be at d = 10/2 = 5 cm from the pivot on the opposite side.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b7884213-4afe-466d-b854-1465d7fa0360', 'Biology', 'JAMB', null, 2002, null, 'When oil is poured into the breeding site of mosquitoes, it', null, '["deprives the larvae of water","kills the adults","suffocates the pupae","slows down egg development"]', 2, 'Oil suffocates mosquito pupae by blocking air access.', true, '2026-10-12 20:59:30.187', '2026-10-12 20:59:30.187', null, null, null, 'When oil is poured into the breeding site of mosquitoes, it', '["deprives the larvae of water","kills the adults","suffocates the pupae","slows down egg development"]', 'Oil suffocates mosquito pupae by blocking air access.', '{"bold":["suffocates the pupae"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b7928c29-c68d-4074-9f58-bc0739591231', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'The children of Israel asked Samuel for a king because', null, '["it was in their constitution","their former king was killed in the battle with the Philistines","they desired to be like the heathen nations around them","they were tired of a military regime","Samuel wanted to contest the election"]', 2, 'The children of Israel asked Samuel for a king because they desired to be like the heathen nations around them. They said, ''Appoint for us a king to govern us like all the nations.''', true, '2026-09-12 09:46:04.793', '2026-09-12 09:46:04.793', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b79698ed-4e4a-49a5-a798-62e5ea62d8ec', 'Physics', 'JAMB', null, 1995, null, 'The primary winding of a transformer has 400 turns and its secondary has 100 turns. If a source of e.m.f. 12 V is applied to the primary, the secondary e.m.f. will be', null, '["3 V","6 V","24 V","48 V"]', 0, 'Vs = Vp x Ns/Np = 12 x 100/400 = 3 V.', true, '2026-10-12 19:15:42.433', '2026-10-12 19:15:42.433', null, null, null, 'The primary winding of a transformer has 400 turns and its secondary has 100 turns. If a source of e.m.f. 12 V is applied to the primary, the secondary e.m.f. will be', '["3 V","6 V","24 V","48 V"]', 'V<sub>s</sub> = V<sub>p</sub> x N<sub>s</sub>/N<sub>p</sub> = 12 x 100/400 = 3 V.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b7a803df-527d-4ff0-8a9b-39aea8cf9e4d', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The men were <u>tardy</u> in offering help.', null, '["generous","quick","brave","slow"]', 3, 'Tardy = slow.', true, '2026-10-24 01:04:02.713', '2026-10-24 01:04:02.713', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The men were <u>tardy</u> in offering help.', '["generous","quick","brave","<u>slow</u>"]', '<b>Tardy</b> = <b>slow</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b7a892a5-c41c-4bf2-a160-5155c5665c4c', 'Economics', 'JAMB', null, 2026, null, 'The impact of a change in the price of commodity A on the quantity demanded of commodity B is best explained using the concept of: (i) price-elasticity of demand (ii) cross-price elasticity of demand (iii) income elasticity of demand (iv) elasticity of substitution', null, '["I only","ii only","ii and iv only","None of the above"]', 1, 'The impact of a change in the price of commodity A on the quantity demanded of commodity B is best explained using cross-price elasticity of demand (ii). Cross-price elasticity measures the responsiveness of quantity demanded of one good to a change in the price of another good. It helps determine whether goods are substitutes (positive cross elasticity) or complements (negative cross elasticity).', true, '2026-09-10 10:41:20.188', '2026-09-10 10:41:20.188', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b7a8b4d3-291b-44ef-bebe-18b0708d6806', 'General Mathematics', 'JAMB', null, 2026, null, 'Simplify √(160r² + √(71r⁴) + √(100r⁵))', null, '["9r²","12√3r","13r","√13r"]', 2, 'The expression simplifies to 13r.', true, '2026-09-12 11:43:46.666', '2026-09-12 11:43:46.666', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b7a9df57-afc9-415c-b09d-8c957110d084', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Stephen was blamed for leaving his door <u>ajar</u> during the heavy rainfall.', null, '["unlocked","unbolted","open","keyless","locked"]', 2, 'Ajar = slightly open.', true, '2026-10-24 01:01:40.99', '2026-10-24 01:01:40.99', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Stephen was blamed for leaving his door <u>ajar</u> during the heavy rainfall.', '["unlocked","unbolted","<u>open</u>","keyless","locked"]', '<b>Ajar</b> = slightly <b>open</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b7b93756-b11f-4128-bd3d-c7cb1bcb821e', 'Literature in English', 'JAMB', null, 2026, null, 'What figure of speech is used in ''lover''s bed''?', null, '["Personification","Metaphor","Alliteration","Simile"]', 1, 'Metaphor is used in ''lover''s bed''.', true, '2026-09-12 11:11:27.375', '2026-09-12 11:11:27.375', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b7c10a4a-17e4-46df-8c6d-fd8d5b841137', 'Literature in English', 'JAMB', null, 2026, null, 'The poem is primarily a tribute to a person who has attained a significant milestone', null, '["marriage","birthday","graduation","promotion"]', 1, 'The poem is a tribute to a birthday milestone.', true, '2026-09-12 11:07:22.113', '2026-09-12 11:07:22.113', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b7c1e9d2-a257-40c1-8fbe-67b66ba5175b', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. When Uche wouldn''t <u>come to</u> quickly enough, the principal rushed him to the hospital.', null, '["revive","pass out","arrive","come up"]', 1, 'Come to = regain consciousness; opposite = pass out.', true, '2026-10-24 07:21:15.511', '2026-10-24 07:21:15.511', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. When Uche wouldn''t <u>come to</u> quickly enough, the principal rushed him to the hospital.', '["revive","pass out","arrive","come up"]', 'Come to = regain consciousness; opposite = pass out.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b7c2e412-e214-45ac-b451-b73c41a8b502', 'Physics', 'JAMB', null, 1989, null, 'The electrochemical equivalent of silver is 0.0012 g C⁻¹. If 36.0 g of silver is to be deposited by electrolysis on a surface by passing a steady current for 5.0 minutes, the current must be', null, '["6 000 A","100 A","10 A","1 A"]', 1, 'm = zIt, so I = m/(zt) = 36.0/(0.0012 x 300) = 100 A.', true, '2026-10-12 19:15:30.118', '2026-10-12 19:15:30.118', null, null, null, 'The electrochemical equivalent of silver is 0.0012 g C<sup>-1</sup>. If 36.0 g of silver is to be deposited by electrolysis on a surface by passing a steady current for 5.0 minutes, the current must be', '["6 000 A","100 A","10 A","1 A"]', 'm = zIt, so I = m/(zt) = 36.0/(0.0012 x 300) = 100 A.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b7c8ff90-b400-45d0-ad36-d91ba051ca85', 'Hausa', 'JAMB', null, 2011, null, '''Ya dan''uwa da ke fatawa a kan zancen, Tawakkali da du''ai wadda ba bidi''a. Da fassarar kaddara bisa yadda anka fadi. Cikin kitabu da sunna wanda ba bidi''a. Ai ka yi fatawarka gun wannan da bai da sani, Kuma bai da hikima ta rarrabe mas''alar bidi''a.'' A wadannan baitoci na ''Wakar Bidi''a'' ta Wakokin Sa''adu Zungur ana yin qargadi ne kan', null, '["dacewar mai karatu ya yi fatawa","karancin malamai a yanzu","fayyace karya cikin gaskiya","neman bayani wurin masana."]', 3, 'Ana yin qargadi ne kan neman bayani wurin masana.', true, '2026-10-13 10:37:22.641', '2026-10-13 10:37:22.641', null, null, null, '''Ya dan''uwa da ke fatawa a kan zancen, Tawakkali da du''ai wadda ba bidi''a. Da fassarar kaddara bisa yadda anka fadi. Cikin kitabu da sunna wanda ba bidi''a. Ai ka yi fatawarka gun wannan da bai da sani, Kuma bai da hikima ta rarrabe mas''alar bidi''a.'' A wadannan baitoci na ''Wakar Bidi''a'' ta Wakokin Sa''adu Zungur ana yin qargadi ne kan', '["dacewar mai karatu ya yi fatawa","karancin malamai a yanzu","fayyace karya cikin gaskiya","neman bayani wurin masana."]', 'Ana yin qargadi ne kan neman bayani wurin masana.', '{"bold":["neman bayani wurin masana"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b7dcf7ba-6b7a-4e8c-ad16-5bffe60abc85', 'Physics', 'JAMB', null, 2026, null, 'The instrument used to measuring/securing a large number of charges by Induction is called', null, '["Electrophorus","proof Plane","capacitor","electroscope"]', 0, 'An electrophorus is an instrument used to produce and store a large number of charges through the process of electrostatic induction. It consists of a dielectric plate and a metal plate with an insulating handle. The electrophorus can be used repeatedly to transfer charge by induction without losing its original charge.', true, '2026-09-10 10:56:38.103', '2026-09-10 10:56:38.103', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b7e4f38c-3b47-40b5-9881-09561205f593', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). The idle steward could not <u>see ___________ on the wall</u> and he lost his job.', null, '["what will be written","what is written","the handwriting","the writing"]', 3, '''See the writing on the wall'' = foresee coming disaster.', true, '2026-10-24 01:04:23.667', '2026-10-24 01:04:23.667', null, null, null, '(Choose the most appropriate interpretation). The idle steward could not <u>see ___________ on the wall</u> and he lost his job.', '["what will be written","what is written","the handwriting","<u>the writing</u>"]', '''<b>See the writing on the wall</b>'' = <b>foresee coming disaster</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b7e8ec18-6ad0-4837-970f-4e5a2e61cf22', 'Biology', 'JAMB', null, 2002, null, 'Animals aestivate when the environment in which they live becomes', null, '["hot and dry","cold and wet","warm and humid","windy and snowy"]', 0, 'Aestivation occurs in hot and dry conditions.', true, '2026-10-12 20:59:31.01', '2026-10-12 20:59:31.01', null, null, null, 'Animals aestivate when the environment in which they live becomes', '["hot and dry","cold and wet","warm and humid","windy and snowy"]', 'Aestivation occurs in hot and dry conditions.', '{"bold":["hot and dry"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b7ec29f3-3c37-4120-b495-15b1711e06f1', 'Economics', 'JAMB', null, 2026, null, 'Total revenue is always equal to', null, '["Total cost multiplied by Average Revenue","Average Revenue multiplied by the quantity sold","Marginal revenue multiplied by the quantity sold","Total cost divided by quantity sold"]', 1, 'Total Revenue = Average Revenue × Quantity sold.', true, '2026-09-12 11:01:06.779', '2026-09-12 11:01:06.779', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b7fbdd98-4181-45f5-843f-2109ddb97f17', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Jesus said: ''I am the true vine and you are the branches.'' ''Branches'' here means the', null, '["Christians","Churches","Disciples","world"]', 2, 'Jesus was speaking to His disciples, calling them branches.', true, '2026-09-12 10:42:16.76', '2026-09-12 10:42:16.76', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b7fd36d5-c5d3-4795-ac5d-5c43b6b0f8a4', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. We found <u>a shady</u> place for the display.', null, '["an enclosed","a stuffy","an open","an unsafe"]', 2, 'Shady; opposite = open.', true, '2026-10-24 07:21:24.576', '2026-10-24 07:21:24.576', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. We found <u>a shady</u> place for the display.', '["an enclosed","a stuffy","an open","an unsafe"]', 'Shady; opposite = open.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b8030101-30ab-4c0d-a4a1-0b2907cc3f6d', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). The advertisement served as <u>a smoke-screen</u> for the activities of the company.', null, '["a camouflage","a protection","an enhancement","an exchange"]', 0, '''Smoke-screen'' = camouflage/disguise.', true, '2026-10-24 01:02:04.691', '2026-10-24 01:02:04.691', null, null, null, '(Choose the most appropriate interpretation). The advertisement served as <u>a smoke-screen</u> for the activities of the company.', '["<u>a camouflage</u>","a protection","an enhancement","an exchange"]', '''<b>Smoke-screen</b>'' = <b>camouflage/disguise</b>.', '{}');
