insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b80a4903-915d-45fb-a94d-9b0629a47fbf', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. I have never been accustomed to seeing my brother in such a <u>pensive</u> mood.', null, '["merry","infuriated","thoughtful","hostile"]', 2, 'Pensive = thoughtful.', true, '2026-10-24 01:01:44.475', '2026-10-24 01:01:44.475', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. I have never been accustomed to seeing my brother in such a <u>pensive</u> mood.', '["merry","infuriated","<u>thoughtful</u>","hostile"]', '<b>Pensive</b> = <b>thoughtful</b>.', '{}');
