insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b826b04d-fa0d-40b6-9ba3-2f704a04bf97', 'English Language', 'JAMB', null, 2007, null, 'His many years of success in legal practice <u>__________</u> didn''t come without challenges.', null, '["indeed","but","in spite of it all","however"]', 3, 'Correct form: however.', true, '2026-10-24 07:21:39.419', '2026-10-24 07:21:39.419', null, null, null, 'His many years of success in legal practice <u>__________</u> didn''t come without challenges.', '["indeed","but","in spite of it all","however"]', 'Correct form: however.', '{}');
