insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b8451ca8-0d18-4d67-86b4-73278487838e', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The man rebuked his son severely, but his words seem to have <u>cut no ice</u>.', null, '["been unconvincing","had no effect","not cooled the boy''s temper","added insult to injury"]', 1, 'Cut no ice = had no effect.', true, '2026-10-24 01:03:56.343', '2026-10-24 01:03:56.343', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The man rebuked his son severely, but his words seem to have <u>cut no ice</u>.', '["been unconvincing","<u>had no effect</u>","not cooled the boy''s temper","added insult to injury"]', '<b>Cut no ice</b> = <b>had no effect</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b847f3f0-25a5-4009-b3d0-f03201179642', 'Economics', 'JAMB', null, 2026, null, 'The responsiveness of the quantity demanded of one commodity to a change in the price of another commodity defines', null, '["Own price elasticity of demand","Cross-price elasticity of demand","Income elasticity of demand","Income inelasticity of demand","Perfect elasticity of demand"]', 1, 'Cross-price elasticity of demand measures the responsiveness of quantity demanded of one commodity to a change in the price of another commodity. It is calculated as the percentage change in quantity demanded of good X divided by the percentage change in price of good Y. Positive cross elasticity indicates substitutes; negative indicates complements.', true, '2026-09-10 10:41:20.884', '2026-09-10 10:41:20.884', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b8487514-54e6-4ddd-8703-db971ec6931d', 'Government', 'JAMB', null, 2026, null, 'Which of the following is the lowest in the hierarchy of feudal system?', null, '["Knights","Serfs","Nobles","Lords"]', 1, 'Serfs were the lowest in the feudal hierarchy.', true, '2026-09-12 11:24:54.944', '2026-09-12 11:24:54.944', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b84dbecc-6bc9-4127-9d18-9a87325625f6', 'Chemistry', 'JAMB', null, 2026, null, 'In the Contact process, the catalyst used is:', null, '["Fe","V₂O₅","Pt","Ni"]', 1, 'Vanadium(V) oxide (V₂O₅) is the catalyst used in the Contact process.', true, '2026-09-12 11:35:48.387', '2026-09-12 11:35:48.387', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b87ca6b9-4ef3-4117-be72-b7245297fc84', 'Biology', 'JAMB', null, 2003, null, 'The eggs of birds contain relatively larger quantities of yolk than those of amphibians and reptiles because', null, '["birds are generally bigger in size","embryonic development is longer in birds","those of birds are fertilized internally","birds lay shelled eggs"]', 1, 'Extended internal and external incubation periods require more nutrient reserves in bird eggs.', true, '2026-10-12 20:05:09.965', '2026-10-12 20:05:09.965', null, null, null, 'The eggs of birds contain relatively larger quantities of yolk than those of amphibians and reptiles because', '["birds are generally bigger in size","embryonic development is longer in birds","those of birds are fertilized internally","birds lay shelled eggs"]', 'Extended internal and external incubation periods require more nutrient reserves in bird eggs.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b881bcf8-22db-4f8f-ba27-a1ca2e4c3e89', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). The new Vice-Chancellor''s immediate concern was to <u>tide over the major difficulties of the moment</u>.', null, '["temporarily accommodate","permanently handle","decisively solve","pretend to solve"]', 0, '''Tide over'' = cope temporarily.', true, '2026-10-24 01:04:21.524', '2026-10-24 01:04:21.524', null, null, null, '(Choose the most appropriate interpretation). The new Vice-Chancellor''s immediate concern was to <u>tide over the major difficulties of the moment</u>.', '["<u>temporarily accommodate</u>","permanently handle","decisively solve","pretend to solve"]', '''<b>Tide over</b>'' = <b>cope temporarily</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b88419bc-ff07-47eb-9d5b-7e23b676f5a5', 'Yoruba', 'JAMB', null, 2002, null, 'Ka àwôn àyòkà ìsàlé yìí, Kí o sì dáhùn àwòn ìbéèrè tí ó télè wòn. Òba Fadérera ní oko kòkó àti oko obì, ó ní oko ìyù àti oko òwú, ilá inú oko rè ni gbogbo ìlú gbójú lé, ìyù àkùrò rè ní kòkò yójú sí òjà. Oko òba gbòòrò púpõ.Sé ìgbà púpõ ni òpòlópõ ènìyàn p lò láti ìyìç òfé fún òba. Òba tún fì ògbòn yè é tó bèé tí ìrè oko rè kò wòn tó ti çlòmíràn. Òba Fadérera bí ómòkùnrin kan tí ó féràn púpô. Ómò òba yìí kì í yè ìyè kankan, àfì kì ó máa ìyìré nínu ògbà baba rê. Àwòn ìrányè pò láti fún un ní gbogbo ohun tí ó bá p fè. Aỳò tuntun ni òmò òba p wò ní ojoojúmò. Òba kè òmò náà bí çyin ojú, ó kè ç pélú ohun ìní àti ìrányè. Ohun kan wá jě děùn òkàn àwòn ará ìlú Éyin-Òla. Ohun náà ni pé, ìkòokò a máa dédé wò ìlù láti gbé ewùrê tàbí àgùntàn wòn lò. Ní ìgbà púpõ ni àwòn ará ìlù tì lò ké bá òba kí ó bá àwòn yanjù òràn tí ó dé bá wòn. Nígbà tí ó yè wàyí o, àwòn ìkòokò pàápàá wá tùn ara mú, wòn béré sí í gbé àwòn òmò ará ìlù Éyin-òla. Àwòn ìlù tùn ké lò sí òdò òba, ìgùbòn òba kò ka òrõ náà sí rárá. Ní òjò kan nígbà tí òmò òba Fadérera àti àwòn çmèwà bàbá rê p ìyìré lórí pápá tí ó wà lèbàà ààfin, ìkòokò plá kan yò sí wòn, ó sì gbé òmò òba lò ráúráú. Nígbà tí òba gbò ohun tí ó ìçlè, ó kígbè ní ohùn rara. Örö náà wá ya gbogbo ìlù lënu nítorí pé òba pàyç lësêkçsê pé kí gbogbo àwòn òdç atamátasê ìlù jáde, kí wön sì pa gbogbo ìkokò tí ó wà agbègbè náà. Sùgbön ìkòokò tí pa òmò òba Fadérera jç. Ëpa kò bóró mò. Ìtumõ ráúráú nínú àyòkà yìí ní', null, '["tipátipá","kíakía","pátápátá","tólátóla"]', 2, 'Ìtumõ ráúráú nínú àyòkà yìí ni pátápátá.', true, '2026-10-13 13:22:37.734', '2026-10-13 13:22:37.734', null, null, null, 'Ka àwôn àyòkà ìsàlé yìí, Kí o sì dáhùn àwòn ìbéèrè tí ó télè wòn. Òba Fadérera ní oko kòkó àti oko obì, ó ní oko ìyù àti oko òwú, ilá inú oko rè ni gbogbo ìlú gbójú lé, ìyù àkùrò rè ní kòkò yójú sí òjà. Oko òba gbòòrò púpõ.Sé ìgbà púpõ ni òpòlópõ ènìyàn p lò láti ìyìç òfé fún òba. Òba tún fì ògbòn yè é tó bèé tí ìrè oko rè kò wòn tó ti çlòmíràn. Òba Fadérera bí ómòkùnrin kan tí ó féràn púpô. Ómò òba yìí kì í yè ìyè kankan, àfì kì ó máa ìyìré nínu ògbà baba rê. Àwòn ìrányè pò láti fún un ní gbogbo ohun tí ó bá p fè. Aỳò tuntun ni òmò òba p wò ní ojoojúmò. Òba kè òmò náà bí çyin ojú, ó kè ç pélú ohun ìní àti ìrányè. Ohun kan wá jě děùn òkàn àwòn ará ìlú Éyin-Òla. Ohun náà ni pé, ìkòokò a máa dédé wò ìlù láti gbé ewùrê tàbí àgùntàn wòn lò. Ní ìgbà púpõ ni àwòn ará ìlù tì lò ké bá òba kí ó bá àwòn yanjù òràn tí ó dé bá wòn. Nígbà tí ó yè wàyí o, àwòn ìkòokò pàápàá wá tùn ara mú, wòn béré sí í gbé àwòn òmò ará ìlù Éyin-òla. Àwòn ìlù tùn ké lò sí òdò òba, ìgùbòn òba kò ka òrõ náà sí rárá. Ní òjò kan nígbà tí òmò òba Fadérera àti àwòn çmèwà bàbá rê p ìyìré lórí pápá tí ó wà lèbàà ààfin, ìkòokò plá kan yò sí wòn, ó sì gbé òmò òba lò ráúráú. Nígbà tí òba gbò ohun tí ó ìçlè, ó kígbè ní ohùn rara. Örö náà wá ya gbogbo ìlù lënu nítorí pé òba pàyç lësêkçsê pé kí gbogbo àwòn òdç atamátasê ìlù jáde, kí wön sì pa gbogbo ìkokò tí ó wà agbègbè náà. Sùgbön ìkòokò tí pa òmò òba Fadérera jç. Ëpa kò bóró mò. Ìtumõ ráúráú nínú àyòkà yìí ní', '["tipátipá","kíakía","pátápátá","tólátóla"]', 'Ìtumõ ráúráú nínú àyòkà yìí ni pátápátá.', '{"bold":["pátápátá"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b8850763-bc3c-4faa-b563-d423996ea0fd', 'Financial Accounting', 'UTME', null, 2001, null, 'Determine the net current assets.', 'https://res.cloudinary.com/kwi1uv0g/image/upload/v1791842277/questions/fnjheuiueu2ik1k1anxv.jpg', '["N43,000","N28,000","N13,000","N3,000"]', 3, 'Net current assets = Current assets - Current liabilities = (Debtors 13,000 + Cash 5,000) - Creditors 15,000 = 18,000 - 15,000 = 3,000.', true, '2026-10-12 22:00:07.488', '2026-10-12 22:00:07.488', null, null, null, 'Determine the net current assets.', '["N43,000","N28,000","N13,000","<b>N3,000</b>"]', 'Net current assets = Current assets - Current liabilities = (Debtors 13,000 + Cash 5,000) - Creditors 15,000 = 18,000 - 15,000 = <b>3,000</b>.', '{"bold":["3,000"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b8881c9b-57cb-435e-bb69-5354e3bab8a4', 'Biology', 'JAMB', null, 2026, null, 'If XN is the dominant allele for normal vision and Xn the recessive allele for colour blindness, a boy with the genotype Yxn will', null, '["have a normal vision","be colour blind","be totally blind","be a carrier of colour blindness"]', 1, 'A boy with the genotype Yxn will be colour blind. The X chromosome carries the recessive allele for colour blindness (Xn). Since males have only one X chromosome (inherited from their mother), they express whatever allele is on that chromosome. There is no second X chromosome to mask the recessive allele. This is why colour blindness is more common in men than in women. The boy would be affected by colour blindness.', true, '2026-09-09 03:19:28.521', '2026-09-09 03:19:28.521', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b8a0f79b-2334-4f85-8722-8a67ffba5302', 'Physics', 'JAMB', null, 2001, null, 'A bread toaster uses a current of 4 A when plugged in a 240 volts line. It takes one minute to toast slices of bread. What is the energy consumed by the toaster?', null, '["5.76 x 10⁴ J","1.60 x 10⁴ J","3.60 x 10³ J","1.60 x 10² J"]', 0, 'E = VIt = 240 x 4 x 60 = 5.76 x 10⁴ J.', true, '2026-10-12 19:15:51.956', '2026-10-12 19:15:51.956', null, null, null, 'A bread toaster uses a current of 4 A when plugged in a 240 volts line. It takes one minute to toast slices of bread. What is the energy consumed by the toaster?', '["5.76 x 10<sup>4</sup> J","1.60 x 10<sup>4</sup> J","3.60 x 10<sup>3</sup> J","1.60 x 10<sup>2</sup> J"]', 'E = VIt = 240 x 4 x 60 = 5.76 x 10<sup>4</sup> J.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b8a25c0f-61d4-4d69-b03c-da15fa04ac8f', 'Physics', 'JAMB', null, 2026, null, 'Calculate the value of electric field intensity due to a charge of 4μC if the force due to the charge is 8N.', null, '["3.0 × 10⁶ NC⁻¹","2.0 × 10⁶ NC⁻¹","4.0 × 10⁶ NC⁻¹","8.0 × 10⁶ NC⁻¹"]', 1, 'Electric field intensity E = F/q. Given F = 8N and q = 4μC = 4 × 10⁻⁶C, E = 8/(4 × 10⁻⁶) = 2 × 10⁶ NC⁻¹.', true, '2026-09-10 10:56:38.486', '2026-09-10 10:56:38.486', null, null, null, null, null, null, null);
