insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b91f2088-d2ad-4e47-976f-956ebee020c4', 'Chemistry', 'JAMB', null, 2026, null, 'What volume of 11.0M hydrochloric acid must be diluted to obtain 1dm³ of 0.05M acid?', null, '["5cm³","100cm³","550cm³","11000cm³"]', 0, 'C₁V₁ = C₂V₂. 11 × V₁ = 0.05 × 1. V₁ = 0.0045 dm³ = 4.5 cm³ ≈ 5 cm³.', true, '2026-09-12 11:36:20.856', '2026-09-12 11:36:20.856', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b9288733-19d3-4789-802f-4f4f60c88dd4', 'English Language', 'JAMB', null, 2024, null, 'What major event led to the acceptance of Mr. Bepo''s reform?', null, '["a public forum organized by the school","the resignation of Mr. Alabi","recognition from a government official","a successful academic competition"]', 3, 'A successful academic competition led to the acceptance of Bepo''s reforms.', true, '2026-09-18 09:34:04.051', '2026-09-18 09:34:04.051', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b9395a5b-0c8e-40ea-b7db-5594fcc095d2', 'Christian Religious Studies', 'JAMB', null, 2026, null, '''Put off your shoes from your feet; for the place where you stand is holy.'' Where was this statement made?', null, '["Mount Horeb","Mount Sinai","Jericho","Gilgal"]', 0, 'God said this to Moses at the burning bush on Mount Horeb.', true, '2026-09-12 10:41:36.322', '2026-09-12 10:41:36.322', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b93b4a52-adb8-4035-bd7c-f4057dc40631', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. He picked up the phone expecting to hear the chairman''s <u>gruff</u> voice.', null, '["gracious","musical","husky","polite"]', 2, 'Gruff = husky.', true, '2026-10-24 01:04:11.116', '2026-10-24 01:04:11.116', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. He picked up the phone expecting to hear the chairman''s <u>gruff</u> voice.', '["gracious","musical","<u>husky</u>","polite"]', '<b>Gruff</b> = <b>husky</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b94449a4-a88f-4166-9177-31a7c06f6192', 'Physics', 'JAMB', null, 2002, null, 'The percentage of the original nuclei of a sample of a radioactive substance left after 5 half-lives is', null, '["1 %","3 %","5 %","8 %"]', 1, 'After 5 half-lives the fraction left is (1/2)⁵ = 1/32 ≈ 3.1%, i.e. about 3 %.', true, '2026-10-12 19:15:54.407', '2026-10-12 19:15:54.407', null, null, null, 'The percentage of the original nuclei of a sample of a radioactive substance left after 5 half-lives is', '["1 %","3 %","5 %","8 %"]', 'After 5 half-lives the fraction left is (1/2)<sup>5</sup> = 1/32 ≈ 3.1%, i.e. about 3 %.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
