insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b9630c49-0928-487b-9399-8796db5efecc', 'English Language', 'JAMB', null, 2007, null, 'The price of everything seems to have <u>----------</u> up in the last few months.', null, '["climbed","shot","risen","flared"]', 1, 'Correct form: shot up.', true, '2026-10-24 07:21:41.75', '2026-10-24 07:21:41.75', null, null, null, 'The price of everything seems to have <u>----------</u> up in the last few months.', '["climbed","shot","risen","flared"]', 'Correct form: shot up.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b97e4fbb-27f0-414a-a9bf-43fa43945f87', 'Hausa', 'JAMB', null, 2010, null, '''Malam Jatau, ka san yarinyar nan da ke zaune a kusurwar đaki, ga ta can ta leko da kanta ta taga?'' Wanda ya yi wannan magana a Jatau Na Kyallu na S. Makarfi, shi ne', null, '["Danwanka","AlKali","Muhuti","Jamanu."]', 1, 'AlKali ne ya yi wannan magana.', true, '2026-10-13 10:37:25.589', '2026-10-13 10:37:25.589', null, null, null, '''Malam Jatau, ka san yarinyar nan da ke zaune a kusurwar đaki, ga ta can ta leko da kanta ta taga?'' Wanda ya yi wannan magana a Jatau Na Kyallu na S. Makarfi, shi ne', '["Danwanka","AlKali","Muhuti","Jamanu."]', 'AlKali ne ya yi wannan magana.', '{"bold":["AlKali"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b9823cf0-fc9b-49af-9d1f-0b14588a5bf6', 'English Language', 'JAMB', null, 2024, null, 'According to the novel, what is the approximate annual migration rate of Nigerian doctors?', null, '["300 out of 3,000","2,000 out of 3,000","1,000 out of 3,000","500 out of 3,000"]', 2, 'According to the novel, approximately 1,000 out of 3,000 Nigerian doctors migrate annually.', true, '2026-09-18 09:23:08.237', '2026-09-18 09:23:08.237', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b986a7e2-f8b7-41d5-9500-06dafa5e73f0', 'Chemistry', 'JAMB', null, 2026, null, 'The oxidation state of P in H2P2O7 2- is', null, '["-3","+3","+1","+5"]', 3, 'In H2P2O7 2-: 2(+1) + 2(P) + 7(-2) = -2 => 2 + 2P - 14 = -2 => 2P = 10 => P = +5.', true, '2026-09-09 17:12:46.797', '2026-09-09 17:12:46.797', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b98c0baf-7e82-4b7f-8b6f-be685930084d', 'English Language', 'JAMB', null, 2024, null, 'The word in capital letters has an emphatic stress. Choose the option that best fits the expression in the sentence: The electricity in OUR premises comes from a generator.', null, '["is the electricity in your compound supplied by a generator?","is the electricity in your neighbour''s premises supplied by a generator?","does the electricity in your premises come from NEPA?","does everybody in your street receive electricity from generators?"]', 1, 'The emphasis on "OUR" contrasts with "your neighbour''s premises."', true, '2026-09-18 09:23:08.53', '2026-09-18 09:23:08.53', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b98f7674-999c-47ec-8227-6e9de98512da', 'Literature in English', 'JAMB', null, 2026, null, 'The internal conflict experienced by Bendu is best understood as a struggle between', null, '["Tradition and modernity","Memory and repression","Wealth and poverty","Loyalty and betrayal"]', 1, 'Bendu''s internal conflict is between memory and repression.', true, '2026-09-12 11:04:56.643', '2026-09-12 11:04:56.643', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b98f84d2-a02c-4edb-a888-6cb6e434f07c', 'Financial Accounting', 'UTME', null, 2004, null, 'What was the balance of cash with the petty cashier at the end of period 1?', 'https://res.cloudinary.com/kwi1uv0g/image/upload/v1791841660/questions/uyeb5hwi1y2svbycwykx.jpg', '["N50","N200","N300","N450"]', 0, 'Petty Cash Book preparation: Period 1: Cash advanced 500 - Stamp 200 - Newspaper 250 = Balance 50.', true, '2026-10-12 22:00:02.05', '2026-10-12 22:00:02.05', null, null, null, 'What was the balance of cash with the petty cashier at the end of period 1?', '["<b>N50</b>","N200","N300","N450"]', 'Petty Cash Book preparation: Period 1: Cash advanced 500 - Stamp 200 - Newspaper 250 = Balance <b>50</b>.', '{"bold":["50"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b99a83c6-7900-4530-8a51-169b58de960a', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The climate of Nigeria is <u>an enervating</u> one.', null, '["a weakening","an energy sapping","an invigorating","a sluggish"]', 2, 'Enervating = weakening; opposite = invigorating.', true, '2026-10-24 07:21:18.769', '2026-10-24 07:21:18.769', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The climate of Nigeria is <u>an enervating</u> one.', '["a weakening","an energy sapping","an invigorating","a sluggish"]', 'Enervating = weakening; opposite = invigorating.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b9b416e7-4c29-4985-84ff-3a0911b53bda', 'English Language', 'JAMB', null, 2007, null, 'Because of his <u>__________</u> nature, Ayo was tricked out of his wristwatch', null, '["pliable","kind","uncompromising","uncalculating"]', 3, 'Correct spelling: uncalculating.', true, '2026-10-24 07:21:39.721', '2026-10-24 07:21:39.721', null, null, null, 'Because of his <u>__________</u> nature, Ayo was tricked out of his wristwatch', '["pliable","kind","uncompromising","uncalculating"]', 'Correct spelling: uncalculating.', '{}');
