insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b9b46d41-1c5d-4232-beb5-ddc4836260c7', 'Biology', 'JAMB', null, 2026, null, 'Which of these excretory structures is not found in amphibians?', null, '["lungs","flame cells","gills","skin"]', 1, 'Flame cells are excretory structures found in flatworms (Platyhelminthes), not in amphibians.', true, '2026-09-09 02:56:43.504', '2026-09-09 02:56:43.504', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b9c9f8b9-83b3-4937-951c-ab812ee2964b', 'English Language', 'JAMB', null, 2007, null, 'The plaintiff <u>__________</u> the court to restrain the defendants from further action', null, '["asked","begged","demanded of","prayed"]', 3, 'Correct form: prayed (legal usage).', true, '2026-10-24 07:21:43.162', '2026-10-24 07:21:43.162', null, null, null, 'The plaintiff <u>__________</u> the court to restrain the defendants from further action', '["asked","begged","demanded of","prayed"]', 'Correct form: prayed (legal usage).', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b9d5a24d-13a6-4ce5-b9ec-84e2d71e81e5', 'Biology', 'JAMB', null, 2026, null, 'In a breeding programme a cross was made between two true-breeding cowpea types: one with round seeds and the other with wrinkled seeds. If roundness is dominant while wrinkledness is recessive, in the first filial generation all the seeds produced will be', null, '["25 percent wrinkled, 75 percent round","100 percent wrinkled","50 percent wrinkled, 50 percent round","75 percent wrinkled, 25 percent round","100 percent round"]', 4, 'In the first filial (F1) generation, all seeds will be 100% round. If roundness (R) is dominant and wrinkledness (r) is recessive, and the parents are true-breeding (RR × rr), all offspring will be Rr (round). The F1 generation shows the dominant trait uniformly. This is Mendel''s principle of dominance: in the presence of a dominant allele, the recessive trait is not expressed. The wrinkled trait will reappear in the F2 generation if F1 plants are self-crossed.', true, '2026-09-09 03:19:14.523', '2026-09-09 03:19:14.523', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b9da92aa-06d1-4497-954d-c9fa7685c7c7', 'Literature in English', 'JAMB', null, 2026, null, 'What theme is expressed here?', null, '["Power and greed","Honour in death","Political rivalry","Friendship and loyalty"]', 1, 'The theme expressed is honour in death.', true, '2026-09-12 11:11:27.599', '2026-09-12 11:11:27.599', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b9dd1ed6-56b1-4aa9-a6bf-33b81bd83dd5', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The chairman admires <u>incessant</u> meetings', null, '["unusual","planned","constant","irregular"]', 2, 'Incessant = constant.', true, '2026-10-24 01:04:12.08', '2026-10-24 01:04:12.08', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The chairman admires <u>incessant</u> meetings', '["unusual","planned","<u>constant</u>","irregular"]', '<b>Incessant</b> = <b>constant</b>.', '{}');
