insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('b9f30915-50b2-4c51-b1c2-356020ef7d05', 'Physics', 'JAMB', null, 1999, null, 'A 3000 W electric cooker is to be used on a 200 V mains circuit. Which of the fuses below can be used safely with the cooker?', null, '["2 A","5 A","10 A","20 A"]', 3, 'Current = P/V = 3000/200 = 15 A. The fuse rating must be above this, so a 20 A fuse is suitable.', true, '2026-10-12 19:15:48.411', '2026-10-12 19:15:48.411', null, null, null, 'A 3000 W electric cooker is to be used on a 200 V mains circuit. Which of the fuses below can be used safely with the cooker?', '["2 A","5 A","10 A","20 A"]', 'Current = P/V = 3000/200 = 15 A. The fuse rating must be above this, so a 20 A fuse is suitable.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
