insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('bd2daf4f-0328-4978-9ccb-9e264d9f39a2', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Adams is a <u>die-hard</u> criminal.', null, '["hard to kill","hard to arrest","remorseless","relentless"]', 2, 'Die-hard = remorseless.', true, '2026-10-24 01:01:49.233', '2026-10-24 01:01:49.233', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Adams is a <u>die-hard</u> criminal.', '["hard to kill","hard to arrest","<u>remorseless</u>","relentless"]', '<b>Die-hard</b> = <b>remorseless</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('bd386fb0-8ed3-47c5-9347-120d39d602b3', 'Chemistry', 'JAMB', null, 2026, null, 'Which of the following statements about metals is correct?', null, '["All metals react with water","Metals conduct electricity because of mobile electrons","Metals are brittle solids","Metals form covalent bonds"]', 1, 'Metallic bonding features a lattice of positive metal ions surrounded by a mobile sea of delocalized valence electrons.', true, '2026-09-09 17:12:48.915', '2026-09-09 17:12:48.915', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('bd3c147d-7aa4-4b79-a7a9-d3f31b8514a3', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Okoro is <u>an amateur</u> wrestler.', null, '["a skilful","a good","a professional","a strong"]', 2, 'Amateur; opposite = professional.', true, '2026-10-24 07:21:14.785', '2026-10-24 07:21:14.785', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Okoro is <u>an amateur</u> wrestler.', '["a skilful","a good","a professional","a strong"]', 'Amateur; opposite = professional.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('bd5b287f-e98c-4b7b-82c3-430c6b38754e', 'Hausa', 'JAMB', null, 2011, null, '''Wa ya ce ba ni bat Wa ya yi ni, wa Yai kamata! Wa kuma zai kama bawa fiye da wanda zan kama!'' Wa ya yi wannan kirari a cikin Shaihu Umar na U. Ladan da D. Lyndersay?', null, '["Buhari.","Makau.","Kwatau.","Shaihu."]', 2, 'Kwatau ne ya yi wannan kirari a cikin Shaihu Umar.', true, '2026-10-13 10:37:22.965', '2026-10-13 10:37:22.965', null, null, null, '''Wa ya ce ba ni bat Wa ya yi ni, wa Yai kamata! Wa kuma zai kama bawa fiye da wanda zan kama!'' Wa ya yi wannan kirari a cikin Shaihu Umar na U. Ladan da D. Lyndersay?', '["Buhari.","Makau.","Kwatau.","Shaihu."]', 'Kwatau ne ya yi wannan kirari a cikin Shaihu Umar.', '{"bold":["Kwatau"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('bd62b0be-7622-4cd7-be08-269c5e2e091e', 'English Language', 'JAMB', null, 2024, null, 'The immediate result of the ______ is that the air surrounding the bomb is raised very rapidly to an enormously high ______.', null, '["Reduction","Commotion","Detonation","Distortion"]', 2, '"Detonation" means explosion.', true, '2026-09-18 09:43:02.431', '2026-09-18 09:43:02.431', null, null, 'CLOZE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('bd68657c-5375-4996-99fe-7e70bbff2d0a', 'English Language', 'JAMB', null, 2007, null, 'The government has provided new <u>__________</u> for the local government polls.', null, '["guard lines","guide lines","guardlines","guidelines"]', 3, 'Correct spelling: guidelines.', true, '2026-10-24 07:21:33.045', '2026-10-24 07:21:33.045', null, null, null, 'The government has provided new <u>__________</u> for the local government polls.', '["guard lines","guide lines","guardlines","guidelines"]', 'Correct spelling: guidelines.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('bd6e3ee6-cb56-4df3-8071-71e31e9ebd64', 'testing', 'JAMB', null, 2024, null, 'Neither of them ... Ready', null, '["Were","is","Are","Isn''t"]', 1, '''Neither'' is singular → ''is''.', true, '2026-10-31 16:48:53.053', '2026-10-31 16:48:53.053', null, null, null, 'Neither of them ... Ready', '["Were","is","Are","Isn''t"]', '''Neither'' is singular → ''is''.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('bd762964-b746-4c54-894a-a8483fdda620', 'Economics', 'JAMB', null, 2026, null, 'An activity does not have a cost when', null, '["The activity does not require the giving up of any other activity or thing","the government pays for it","it is carried out by a non-governmental organisation","it is not priced","it is easy to undertake"]', 0, 'An activity does not have a cost when it does not require the giving up of any other activity or thing. Cost in economics is opportunity cost—the value of the next best alternative forgone. If no alternative is sacrificed, there is no cost. If the government pays or an NGO carries it out, there is still a cost to society.', true, '2026-09-10 10:41:20.509', '2026-09-10 10:41:20.509', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('bd763945-82f3-46f9-8c17-79a6f00b89e4', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. I would not like you to do the work <u>piecemeal</u>.', null, '["at meal time","bit by bit","badly","as a masterpiece"]', 1, 'Piecemeal = bit by bit.', true, '2026-10-24 01:01:43.459', '2026-10-24 01:01:43.459', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. I would not like you to do the work <u>piecemeal</u>.', '["at meal time","<u>bit by bit</u>","badly","as a masterpiece"]', '<b>Piecemeal</b> = <b>bit by bit</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('bd7edd4b-1a3e-4a5b-b4ff-2f280a753df6', 'English Language', 'JAMB', null, 2024, null, 'Which of the following has a different vowel sound BLOOD (I) flood (II) love (III) sun (IV) son (V) Chord', null, '["IV","V","II&IV","IV&V"]', 1, '"Blood" has an /ʌ/ sound, while "Chord" has an /ɔː/ sound.', true, '2026-09-18 09:43:02.354', '2026-09-18 09:43:02.354', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('bd92d207-3626-4546-8e88-c68324b3cae6', 'General Mathematics', 'JAMB', null, 2026, null, 'Evaluate 2700000 × 0.03 ÷ 18000', null, '["4.5 × 10²","4.5 × 10³","4.5 × 10⁶","4.5 × 10¹"]', 0, '2700000 × 0.03 = 81000. 81000/18000 = 4.5 = 4.5 × 10⁰. Not in options. The closest is 4.5 × 10¹.', true, '2026-09-12 11:43:57.913', '2026-09-12 11:43:57.913', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('bd96e805-b4c8-4809-9f39-592342b2880e', 'Chemistry', 'JAMB', null, 2026, null, 'The chief ore of aluminium is:', null, '["Haematite","Bauxite","Galena","Magnetite"]', 1, 'Bauxite is the chief ore of aluminium.', true, '2026-09-12 11:35:50.077', '2026-09-12 11:35:50.077', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('bda2ecd3-73f1-466b-9fa2-a9d1c792940a', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'The Deuteronomic interpretation of Israel''s history emphasises that national prosperity is contingent upon', null, '["covenant obedience","military strength","prophetic leadership","temple sacrifices"]', 0, 'Deuteronomy teaches that obedience brings blessing and disobedience brings curse.', true, '2026-09-12 10:41:01.869', '2026-09-12 10:41:01.869', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('bda92431-322f-455a-ae65-f850a2a33e62', 'Economics', 'JAMB', null, 2026, null, 'When the tax rate increases as the income increases, this is said to be a', null, '["Progressive tax","Retrogressive tax","Regressive tax","Proportional tax"]', 0, 'A progressive tax takes a larger percentage of income as income increases.', true, '2026-09-12 11:00:55.726', '2026-09-12 11:00:55.726', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('bdcd5972-8ee5-4ca3-8e4f-65c2c2efb324', 'Government', 'JAMB', null, 2026, null, 'The concept of sovereignty which empower the state was introduced into political theory by', null, '["Adam Smith","Jean Bodin","Karl Marx","John Locke"]', 1, 'Jean Bodin introduced the concept of sovereignty into political theory.', true, '2026-09-12 11:24:50.696', '2026-09-12 11:24:50.696', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('bdce845b-eed0-4af8-af9b-f324e4b03891', 'Economics', 'JAMB', null, 2026, null, 'Normative economics deals with', null, '["what is and not what should be","facts and not figures","fact and figures","value judgement"]', 3, 'Normative economics deals with value judgements. It is concerned with what ought to be, rather than what is. Normative statements are subjective and based on opinions, beliefs, and values. They cannot be tested or proven true or false. For example, ''The government should increase taxes on the rich'' is a normative statement. Positive economics deals with facts and what is.', true, '2026-09-10 10:42:00.503', '2026-09-10 10:42:00.503', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('bdeaa6a1-26fc-46ba-9bae-fedd7816b3c2', 'English Language', 'JAMB', null, 2024, null, '(Consonant) goat', null, '["Gear","Gnash","Judge","Regime"]', 0, 'The "g" in "goat" sounds like /g/, same as the "g" in "gear."', true, '2026-09-18 09:24:04.766', '2026-09-18 09:24:04.766', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('bdf5a7df-d6c3-4990-82a7-4256fec8624e', 'Literature in English', 'JAMB', null, 2026, null, 'The sentence style is characterized by', null, '["long sentences","visual images","tactile image","short sentence"]', 3, 'The sentence style is characterized by short sentences.', true, '2026-09-12 11:11:10.116', '2026-09-12 11:11:10.116', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('bdfaaafc-9385-407b-a304-4e380d3f1721', 'Literature in English', 'JAMB', null, 2026, null, 'The poet''s tone shifts from', null, '["joy to anger","nostalgia to disillusionment","anger to love","satire to humour"]', 1, 'The tone shifts from nostalgia to disillusionment.', true, '2026-09-12 11:14:11.105', '2026-09-12 11:14:11.105', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('bdfc83d8-d84a-4298-bd0b-92651ccf52b8', 'Biology', 'JAMB', null, 2026, null, 'Which of the following processes occurs during inhalation? I. Intercostal muscles contract II. Ribs and sternum move upward and outwards III. Diaphragm contracts and becomes flattened IV. Intercostal muscles relax V. Ribs and sternum move downward and inwards VI. Diaphragm relaxes and assumes its dome shape', null, '["I, III, V","I, II, III","I, II, VI","II, III, IV","IV, V, VI"]', 1, 'During inhalation (inspiration), the intercostal muscles contract, causing the ribs and sternum to move upward and outward (I and II). The diaphragm contracts and becomes flattened (III). These changes increase the volume of the thoracic cavity, decreasing pressure and drawing air into the lungs. The processes in IV, V, and VI describe exhalation (expiration) where intercostal muscles relax, ribs and sternum move downward and inward, and the diaphragm relaxes into its dome shape. Therefore, I, II, and III are correct for inhalation.', true, '2026-09-09 03:18:30.701', '2026-09-09 03:18:30.701', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('be0addd1-938c-452a-9bf4-4a38ecc702da', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The stockbroker said it was <u>an astute</u> move to sell the shares then.', null, '["a bad","a shrewd","an unprofitable","an insincere"]', 1, 'Astute = shrewd.', true, '2026-10-24 01:01:57.708', '2026-10-24 01:01:57.708', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The stockbroker said it was <u>an astute</u> move to sell the shares then.', '["a bad","<u>a shrewd</u>","an unprofitable","an insincere"]', '<b>Astute</b> = <b>a shrewd</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('be10f789-747c-4791-b417-221cfc6b5cff', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). It was a spending spree for all of us when daddy <u>hit the jackpot</u>.', null, '["bought a new car","a clear-sighted","found money in a pot","won a lot of money"]', 3, '''Hit the jackpot'' = won a lot of money.', true, '2026-10-24 01:02:08.711', '2026-10-24 01:02:08.711', null, null, null, '(Choose the most appropriate interpretation). It was a spending spree for all of us when daddy <u>hit the jackpot</u>.', '["bought a new car","a clear-sighted","found money in a pot","<u>won a lot of money</u>"]', '''<b>Hit the jackpot</b>'' = <b>won a lot of money</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('be13b6bf-b9a4-477f-b259-d9744d820f59', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The boy was told that he would need <u>several</u> more pints of blood if he was to survive.', null, '["many","much","some","plenty"]', 0, 'Several = many.', true, '2026-10-24 01:04:01.995', '2026-10-24 01:04:01.995', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The boy was told that he would need <u>several</u> more pints of blood if he was to survive.', '["<u>many</u>","much","some","plenty"]', '<b>Several</b> = <b>many</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('be179b4c-fb2a-4dc7-a609-73532300b231', 'English Language', 'JAMB', null, 2007, null, 'One of my sisters who <u>______</u> in Lagos is getting married next month.', null, '["live","lives","is living","leave"]', 0, '''Who'' â†’ sisters plural â†’ live.', true, '2026-10-24 01:04:29.846', '2026-10-24 01:04:29.846', null, null, null, 'One of my sisters who <u>______</u> in Lagos is getting married next month.', '["<u>live</u>","lives","is living","leave"]', '''<b>Who</b>'' â†’ <b>sisters</b> plural â†’ <b>live</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('be18903a-8b6b-4e9f-962b-98059b425622', 'Biology', 'JAMB', null, 2026, null, 'If a flower is protandrous then it', null, '["must be unisexual","has an undeveloped androecium","has no androecium","must be insect pollinated","can prevent self pollination"]', 4, 'Protandry is a condition where the anthers (male organs) mature and release pollen before the stigma (female organ) becomes receptive. This temporal separation of male and female functions promotes cross-pollination and prevents self-pollination within the same flower. Protandrous flowers are typically bisexual (having both sexes) with a developed androecium. While many protandrous flowers are insect pollinated, this is not a requirement. The main significance is that it prevents self-fertilization by ensuring that pollen is shed before the stigma is ready to receive it.', true, '2026-09-09 03:18:29.273', '2026-09-09 03:18:29.273', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('be28130c-5cf8-461c-ac40-f11696b7c8e0', 'Biology', 'JAMB', null, 2026, null, 'A pair of genes that control a trait is referred to as', null, '["recessive","dominant","a hybrid","an allele"]', 3, 'A pair of genes that control a trait is referred to as an allele. Alleles are alternative forms of a gene found at the same locus on homologous chromosomes. Dominant and recessive describe the relationship between alleles. A hybrid is an organism with different alleles for a gene (heterozygous). The pair of alleles determines the expression of a trait in an organism.', true, '2026-09-09 03:19:22.327', '2026-09-09 03:19:22.327', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('be34652c-a689-4fc7-b3fe-f2b88308d3fc', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Jesus said to her, ''I am the resurrection and the life; he who believes in me, though he dies, yet shall he live, and whoever lives and believes in me shall never die...'' On what occasion was this statement made?', null, '["on the day of Jesus'' resurrection","on the day Jesus restored Lazarus back to life","when Jairus'' daughter was raised from the dead","when Jesus demonstrated the fact of his resurrection to Thomas"]', 1, 'This statement was made on the day Jesus restored Lazarus back to life. Jesus said this to Martha, Lazarus'' sister, before raising Lazarus from the dead.', true, '2026-09-12 09:46:10.715', '2026-09-12 09:46:10.715', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('be39c31e-d0bd-4ec1-ab18-eafd83a26291', 'Literature in English', 'JAMB', null, 2026, null, 'One of the themes cannot be found in the play "Once upon an Elephant"', null, '["love","culture","friendship","chauvinism"]', 3, 'Chauvinism is not a theme in the play "Once upon an Elephant." The play explores themes of love, culture, and friendship. Chauvinism (excessive patriotism or male chauvinism) is not central to the play''s message. The play deals with human relationships, cultural values, and the bonds between characters. The correct answer is chauvinism.', true, '2026-09-10 10:45:34.56', '2026-09-10 10:45:34.56', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('be3e329c-8caf-4ca9-b98d-a3ffaea8c2ed', 'English Language', 'JAMB', null, 2007, null, 'The water is not good for drinking; it''s been <u>__________</u> by the dead rabbit', null, '["contaminated","infested","spoilt","diseased"]', 0, 'Correct spelling: contaminated.', true, '2026-10-24 07:21:41.65', '2026-10-24 07:21:41.65', null, null, null, 'The water is not good for drinking; it''s been <u>__________</u> by the dead rabbit', '["contaminated","infested","spoilt","diseased"]', 'Correct spelling: contaminated.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('be5122da-6909-4a7a-97dd-2ec96e70ea91', 'Biology', 'JAMB', null, 2003, null, 'The type of reproduction that is common to both Hydra and Yeast is', null, '["conjugation","binary fusion","grafting","budding"]', 3, 'Both Hydra and yeast reproduce asexually by forming buds that detach from the parent.', true, '2026-10-12 20:05:11.409', '2026-10-12 20:05:11.409', null, null, null, 'The type of reproduction that is common to both Hydra and Yeast is', '["conjugation","binary fusion","grafting","budding"]', 'Both Hydra and yeast reproduce asexually by forming buds that detach from the parent.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('be51530a-2862-430c-881e-fb537a83108e', 'Chemistry', 'JAMB', null, 2026, null, 'If a reaction is exothermic and there is a great disorder, it means that', null, '["The reaction is in a state of equilibrium","There will be a large increase in free energy","There will be a large decrease in free energy","The reaction is static"]', 2, 'Exothermic with great disorder means a large decrease in free energy.', true, '2026-09-12 11:36:13.411', '2026-09-12 11:36:13.411', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('be59445d-08d7-4047-8ec4-77aac15682e7', 'Physics', 'JAMB', null, 1990, null, 'A light wave of frequency 5 x 10¹⁴ Hz moves through water which has a refractive index of 4/3. Calculate the wavelength in water if the velocity of light in air is 3 x 10⁸ m s⁻¹.', null, '["4.5 x 10⁻⁷ m","6.0 x 10⁻⁷ m","1.7 x 10⁻⁶ m","2.2 x 10⁻⁶ m"]', 0, 'Speed in water = (3 x 10⁸)/(4/3) = 2.25 x 10⁸ m s⁻¹. λ = v/f = (2.25 x 10⁸)/(5 x 10¹⁴) = 4.5 x 10⁻⁷ m.', true, '2026-10-12 19:15:31.089', '2026-10-12 19:15:31.089', null, null, null, 'A light wave of frequency 5 x 10<sup>14</sup> Hz moves through water which has a refractive index of 4/3. Calculate the wavelength in water if the velocity of light in air is 3 x 10<sup>8</sup> m s<sup>-1</sup>.', '["4.5 x 10<sup>-7</sup> m","6.0 x 10<sup>-7</sup> m","1.7 x 10<sup>-6</sup> m","2.2 x 10<sup>-6</sup> m"]', 'Speed in water = (3 x 10<sup>8</sup>)/(4/3) = 2.25 x 10<sup>8</sup> m s<sup>-1</sup>. λ = v/f = (2.25 x 10<sup>8</sup>)/(5 x 10<sup>14</sup>) = 4.5 x 10<sup>-7</sup> m.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('be5ecdcb-668a-4d2e-b39a-dfa1457c2499', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation).Ike is <u>head over heels</u> in love with Ngozi. This means that', null, '["Ike is friendly with Ngozi","Ike is trying to fall in love with Ngozi","Ngozi fell on Ike''s heel and both of them fell in love","Ike is madly in love with Ngozi"]', 3, '''Head over heels'' means deeply in love.', true, '2026-10-24 01:02:00.456', '2026-10-24 01:02:00.456', null, null, null, '(Choose the most appropriate interpretation).Ike is <u>head over heels</u> in love with Ngozi. This means that', '["Ike is friendly with Ngozi","Ike is trying to fall in love with Ngozi","Ngozi fell on Ike''s heel and both of them fell in love","<u>Ike is madly in love with Ngozi</u>"]', '''<b>Head over heels</b>'' means <b>deeply in love</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('be72852e-30eb-4ac3-b6b6-4c8f7d65dbcd', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The culprits will <u>surrender</u> their loot to the Customs officials.', null, '["give away","give out","given in","give up"]', 3, 'Surrender = give up.', true, '2026-10-24 01:03:54.297', '2026-10-24 01:03:54.297', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The culprits will <u>surrender</u> their loot to the Customs officials.', '["give away","give out","given in","<u>give up</u>"]', '<b>Surrender</b> = <b>give up</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('be728f20-1dd2-4ff2-9411-8cbfacbc2ad3', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'The two birds sent by Noah to confirm that the storm had subsided were', null, '["raven and sparrow","raven and pigeon","raven and dove","dove and pigeon"]', 2, 'The two birds sent by Noah were the raven and the dove. Noah first sent out a raven, which flew to and fro until the waters dried up. Then he sent out a dove to see if the waters had subsided.', true, '2026-09-12 09:46:07.115', '2026-09-12 09:46:07.115', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('be818330-3932-4eb0-b3d1-5a2c38343ec8', 'Physics', 'JAMB', null, 2026, null, 'If the fraction of the atoms of a radioactive material left after 120 years is 1/64. What is the half life of the material?', null, '["2 years","10 years","20 years","24 years"]', 2, '1/64 = (1/2)⁶, so 6 half-lives have passed. Half-life = 120/6 = 20 years.', true, '2026-09-10 10:56:46.277', '2026-09-10 10:56:46.277', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('be85fca3-2f12-4da6-a80a-7de2184f6082', 'Yoruba', 'JAMB', null, 2007, null, 'Ìwé Àyàyàn Àlò Onítàn ni ìbéèrè 26-28 dá lé. ‘Nínú ìtàn Òdc kan àti Òré rê, eni tí ó fí ibi ýú olóore ni', null, '["ògbójú òdc","çkùn","erè","õré òdc."]', 2, 'Erè ni ó fí ibi ýú olóore.', true, '2026-10-13 13:23:31.796', '2026-10-13 13:23:31.796', null, null, null, 'Ìwé Àyàyàn Àlò Onítàn ni ìbéèrè 26-28 dá lé. ‘Nínú ìtàn Òdc kan àti Òré rê, eni tí ó fí ibi ýú olóore ni', '["ògbójú òdc","çkùn","erè","õré òdc."]', 'Erè ni ó fí ibi ýú olóore.', '{"bold":["erè"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('be874268-5bbf-429a-a1b0-1c59d3ac5566', 'English Language', 'JAMB', null, 2007, null, 'Insects can become <u>__________</u> to insecticides', null, '["immunized","resistant","reticent","immobilized"]', 1, 'Correct spelling: resistant.', true, '2026-10-24 07:21:42.861', '2026-10-24 07:21:42.861', null, null, null, 'Insects can become <u>__________</u> to insecticides', '["immunized","resistant","reticent","immobilized"]', 'Correct spelling: resistant.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('be95b634-cd00-41b0-899c-469563ba73a1', 'Biology', 'JAMB', null, 2011, null, 'The wings of a bat and those of a bird are examples of', null, '["convergent evolution","coevolution","continuous variation","divergent evolution."]', 0, 'The wings of a bat and bird are examples of convergent evolution.', true, '2026-10-12 20:59:43.983', '2026-10-12 20:59:43.983', null, null, null, 'The wings of a bat and those of a bird are examples of', '["convergent evolution","coevolution","continuous variation","divergent evolution."]', 'The wings of a bat and bird are examples of convergent evolution.', '{"bold":["convergent evolution"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('bebb640b-896d-4bc6-839b-81c53235beb1', 'Biology', 'JAMB', null, 2026, null, 'The name for the collective female reproductive organ in flowers is: I. Gynoecium II. Androecium III. Ovary IV. Ovum', null, '["I","I & IV","IV","I, II & IV"]', 0, 'The collective female reproductive organs in a flower are called the gynoecium (I). The gynoecium consists of one or more carpels (the pistil), each containing an ovary, style, and stigma. The androecium (II) is the collective male reproductive organs (stamens). The ovary (III) is a part of the female organ, not the collective term. The ovum (IV) is the female gamete within the ovule. Gynoecium is the correct collective term for all female structures in a flower.', true, '2026-09-09 03:18:37.478', '2026-09-09 03:18:37.478', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('bebd28fe-2c13-4deb-a706-0108fde63465', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. <u>Recreation</u> is important in contemporary civilization.', null, '["Leisure","Treasure","Freedom","Pleasure"]', 0, 'Recreation = leisure.', true, '2026-10-24 01:01:47.219', '2026-10-24 01:01:47.219', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. <u>Recreation</u> is important in contemporary civilization.', '["<u>Leisure</u>","Treasure","Freedom","Pleasure"]', '<b>Recreation</b> = <b>Leisure</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('bec419e2-4a17-4d09-b22e-12fab3e0311f', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). The new religious leader <u>hands out an olive branch</u>.', null, '["sues for peace","gives out branches of the olive tree","challenges his opponents to a fight","blesses his congregation"]', 0, '''An olive branch'' = offer of peace.', true, '2026-10-24 01:04:17.285', '2026-10-24 01:04:17.285', null, null, null, '(Choose the most appropriate interpretation). The new religious leader <u>hands out an olive branch</u>.', '["<u>sues for peace</u>","gives out branches of the olive tree","challenges his opponents to a fight","blesses his congregation"]', '''<b>An olive branch</b>'' = <b>offer of peace</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('becf4821-fe4f-490c-a532-3b309549b6bb', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. <u>Funnily</u> enough, the priest prayed for the robber who shot him.', null, '["Timidly","Fearlessly","Unexpectedly","Disappointingly"]', 2, 'Funnily enough = unexpectedly.', true, '2026-10-24 01:01:53.109', '2026-10-24 01:01:53.109', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. <u>Funnily</u> enough, the priest prayed for the robber who shot him.', '["Timidly","Fearlessly","<u>Unexpectedly</u>","Disappointingly"]', '<b>Funnily enough</b> = <b>Unexpectedly</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('bedd6e86-15f0-4a02-afaf-95d408c51991', 'Literature in English', 'JAMB', null, 2026, null, '''Singing songs of sorrow is symbolic of sincere sympathy'' illustrates', null, '["Assonance","Refrain","Alliteration","Anecdote"]', 2, 'It illustrates alliteration.', true, '2026-09-12 11:07:28.703', '2026-09-12 11:07:28.703', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('bedea41a-2803-4d88-84d6-ffab3017539e', 'Literature in English', 'JAMB', null, 2026, null, 'The war had ended, but its shadows lingered in the minds of the people. Each step forward seemed weighed down by memories that refused to fade. The dominant literary device in the passage above is', null, '["Hyperbole","Metaphor","Irony","Euphemism"]', 1, 'The dominant device is metaphor (shadows lingering in minds).', true, '2026-09-12 11:04:56.24', '2026-09-12 11:04:56.24', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('beed860d-8597-49c3-a10e-b284718bf785', 'Biology', 'JAMB', null, 2026, null, 'Which of the following is true of the transverse section of a dicot stem?', null, '["The xylem is more interiorly located than the phloem","The cambium lies between the cortex and the vascular bundles","The vascular bundles are randomly scattered within the cortex","The epidermis is completely encircled by the cortex"]', 0, 'In the transverse section of a dicot stem, the xylem is more interiorly located than the phloem. The vascular bundles are arranged in a ring, with xylem toward the inside and phloem toward the outside. The cambium is between the xylem and phloem, not between the cortex and vascular bundles. Vascular bundles are arranged in a ring, not randomly scattered (random arrangement is characteristic of monocots). The epidermis is the outermost layer, not encircled by the cortex. This vascular arrangement allows for secondary growth through the cambium.', true, '2026-09-09 03:19:04.679', '2026-09-09 03:19:04.679', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('beef9374-61c1-4bff-aeb5-b354e2021f38', 'English Language', 'JAMB', null, 2024, null, 'Choose the appropriate stress: advantageous', null, '["AD-van-ta-geous","ad-VAN-ta-geous","ad-van-TA-geous","ad-van-ta-GEOUS"]', 2, 'The stress in "advantageous" is on the third syllable: ad-van-TA-geous.', true, '2026-09-18 09:43:02.663', '2026-09-18 09:43:02.663', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('befe87b3-43a1-484d-8faa-829b728ab8d5', 'Literature in English', 'JAMB', null, 2026, null, 'A character who defends a bad cause or who argues in a contrary position just to stimulate an argument is referred to as', null, '["Legend","Cynic","Villain","Critic"]', 1, 'A character who defends a bad cause or argues in a contrary position just to stimulate an argument is referred to as a cynic. A cynic is someone who questions commonly accepted beliefs and may take contrarian positions to provoke discussion or challenge assumptions. A legend is a traditional story, a villain is an evil character, and a critic evaluates works of art or literature.', true, '2026-09-10 10:47:09.521', '2026-09-10 10:47:09.521', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('bf0bb829-b3fa-48bf-8cf4-aa72d6090bfc', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The retired General became a <u>hard-nosed</u> officer after fighting the war.', null, '["tough","weak","indifferent","bed-ridden"]', 1, 'Hard-nosed = tough; opposite = weak.', true, '2026-10-24 07:21:11.825', '2026-10-24 07:21:11.825', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The retired General became a <u>hard-nosed</u> officer after fighting the war.', '["tough","weak","indifferent","bed-ridden"]', 'Hard-nosed = tough; opposite = weak.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('bf1021a8-ea03-4b82-9f87-6ed90a3b22dd', 'Physics', 'JAMB', null, 2004, null, 'A cell whose internal resistance is 0.5 Ω delivers a current of 4 A to an external resistor. The lost voltage of the cell is', null, '["1.250 V","8.000 V","0.125 V","2.000 V"]', 3, 'Lost volts = Ir = 4 x 0.5 = 2.000 V.', true, '2026-10-12 19:16:00.321', '2026-10-12 19:16:00.321', null, null, null, 'A cell whose internal resistance is 0.5 Ω delivers a current of 4 A to an external resistor. The lost voltage of the cell is', '["1.250 V","8.000 V","0.125 V","2.000 V"]', 'Lost volts = Ir = 4 x 0.5 = 2.000 V.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('bf128cd1-ee82-47be-b0aa-f498add64a55', 'English Language', 'JAMB', null, 2024, null, '49', null, '["Insurrection","Exhaustion","Eruption","Expulsion"]', 2, '"Volcanic eruption" is the correct collocation.', true, '2026-09-18 10:17:48.879', '2026-09-18 10:17:48.879', 'decfd2ca-8924-4681-ba7c-9a039e9bda97', 2, 'CLOZE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('bf1a649a-9a2c-4e39-880a-a3c8066e9de7', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Rich citizens are often <u>niggardly</u> in their ways.', null, '["beggarly","sordid","miserly","pompous"]', 2, 'Niggardly = miserly.', true, '2026-10-24 01:03:54.404', '2026-10-24 01:03:54.404', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Rich citizens are often <u>niggardly</u> in their ways.', '["beggarly","sordid","<u>miserly</u>","pompous"]', '<b>Niggardly</b> = <b>miserly</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('bf201722-6382-4c4e-b995-9e56e8c00670', 'Literature in English', 'JAMB', null, 2026, null, 'Purgation of emotion, pity or fear is', null, '["Catharsis","Catastrophe","Epilogue","Exposition"]', 0, 'Catharsis is the purgation of emotions.', true, '2026-09-12 11:10:38.134', '2026-09-12 11:10:38.134', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('bf20ea4a-0b86-44c0-adc9-1771b0d1647b', 'Physics', 'JAMB', null, 1987, null, 'A cube of side 10 cm and mass 0.5 kg floats in a liquid with only 1/5 of its height above the liquid surface. What is the relative density of the liquid?', null, '["0.125","0.250","0.625","2.500."]', 2, 'Submerged volume = 4/5 x 1000 = 800 cm³. Upthrust = weight: ρ x 800 = 500 g, so ρ = 0.625 g cm⁻³, i.e. relative density 0.625.', true, '2026-10-12 19:15:25.152', '2026-10-12 19:15:25.152', null, null, null, 'A cube of side 10 cm and mass 0.5 kg floats in a liquid with only 1/5 of its height above the liquid surface. What is the relative density of the liquid?', '["0.125","0.250","0.625","2.500."]', 'Submerged volume = 4/5 x 1000 = 800 cm<sup>3</sup>. Upthrust = weight: ρ x 800 = 500 g, so ρ = 0.625 g cm<sup>-3</sup>, i.e. relative density 0.625.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('bf25691c-ea36-4625-8ac1-8b7a6ad96f09', 'Biology', 'JAMB', null, 2026, null, 'Mangrove swamp can be found', null, '["on a mud flat near the sea","where a river meets the sea","where two rivers meet","on a seashore with flat terrains"]', 1, 'Mangrove swamps thrive in estuaries where freshwater rivers meet the sea, creating brackish water conditions with fluctuating salinity levels. These unique environments provide the sediment accumulation and tidal influence necessary for mangrove species to establish their specialized root systems. Mud flats near the sea may lack the freshwater input, while the meeting of two rivers lacks tidal influence. Flat seashores without river input typically support different coastal ecosystems.', true, '2026-09-09 03:18:15.454', '2026-09-09 03:18:15.454', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('bf2a2d9b-e4a0-4d3a-9faf-4fec036b5e5f', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation).The government should stop <u>white elephant projects</u>.', null, '["projects in which white men kill elephants","projects in which white elephants are used","projects for painting some elephants white","high cost projects with low utility values","low cost projects with high utility values"]', 3, '''White elephant'' = costly project of little use.', true, '2026-10-24 01:04:16.375', '2026-10-24 01:04:16.375', null, null, null, '(Choose the most appropriate interpretation).The government should stop <u>white elephant projects</u>.', '["projects in which white men kill elephants","projects in which white elephants are used","projects for painting some elephants white","<u>high cost projects with low utility values</u>","low cost projects with high utility values"]', '''<b>White elephant</b>'' = <b>costly project of little use</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('bf37f545-2bca-431b-b651-25a37794a95c', 'English Language', 'JAMB', null, 2024, null, 'It can be inferred from the passage that', null, '["Every task can eventually result in fatigue","Only difficult lessons lead to fatigue","A labourer must work all day before expressing fatigue","Rest is needed only when you experience fatigue"]', 0, 'The passage states that everyone is tired or fatigued at some time, implying every task can result in fatigue.', true, '2026-09-18 09:43:02.462', '2026-09-18 09:43:02.462', null, null, 'COMPREHENSION', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('bf384fff-aada-4b3b-a223-6d9771161f46', 'Literature in English', 'JAMB', null, 2026, null, 'The poem is about love', null, '["Unforgettable","Unrequited","Sacrificial","Selfish"]', 1, 'The poem is about unrequited love.', true, '2026-09-12 11:14:04.746', '2026-09-12 11:14:04.746', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('bf3b3ef0-e933-4c92-bbc7-eddaf90f09d9', 'Government', 'JAMB', null, 2026, null, 'Government is the machinery set up to manage the affairs of', null, '["rulers","aliens","the civil service","workers and peasants","State"]', 4, 'Government is the machinery set up to manage the affairs of the State. The state is the political organization of society, and government is the instrument through which the state exercises its authority. Government manages the affairs of the state by making and enforcing laws, providing services, and maintaining order. It does not manage the affairs of only rulers, aliens, civil service, or workers and peasants, but of the entire state.', true, '2026-09-10 10:45:06.677', '2026-09-10 10:45:06.677', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('bf3d1596-0a9d-4301-b9b6-5c17019b2587', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). The officer refused to be <u>taken in</u> by the private.', null, '["won over","drawn in","overtaken","deceived","involved"]', 3, '''Taken in'' = deceived.', true, '2026-10-24 01:02:02.479', '2026-10-24 01:02:02.479', null, null, null, '(Choose the most appropriate interpretation). The officer refused to be <u>taken in</u> by the private.', '["won over","drawn in","overtaken","<u>deceived</u>","involved"]', '''<b>Taken in</b>'' = <b>deceived</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('bf40423f-ccd9-4e73-8fa7-9274eb322913', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The actress <u>screamed</u> when she noticed an object behind her.', null, '["protested","waded in","stormed out","wailed"]', 3, 'Screamed = wailed.', true, '2026-10-24 01:01:58.503', '2026-10-24 01:01:58.503', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The actress <u>screamed</u> when she noticed an object behind her.', '["protested","waded in","stormed out","<u>wailed</u>"]', '<b>Screamed</b> = <b>wailed</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('bf469833-52f3-4d66-890f-6c65d019ecee', 'Physics', 'JAMB', null, 1997, null, 'A cube of sides 0.1 m hangs freely from a string. What is the upthrust on the cube when totally immersed in water? [Density of water is 1000 kg m⁻³, g = 10 m s⁻²]', null, '["1000 N","700 N","110 N","10 N"]', 3, 'Volume = 10⁻³ m³. Upthrust = ρVg = 1000 x 10⁻³ x 10 = 10 N.', true, '2026-10-12 19:15:43.145', '2026-10-12 19:15:43.145', null, null, null, 'A cube of sides 0.1 m hangs freely from a string. What is the upthrust on the cube when totally immersed in water? [Density of water is 1000 kg m<sup>-3</sup>, g = 10 m s<sup>-2</sup>]', '["1000 N","700 N","110 N","10 N"]', 'Volume = 10<sup>-3</sup> m<sup>3</sup>. Upthrust = ρVg = 1000 x 10<sup>-3</sup> x 10 = 10 N.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('bf51731c-7f8b-4aa6-b3c1-2582062884d1', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). The terms of the contract <u>stuck in my throat</u>.', null, '["were beyond me","were not clear","were ambiguous","became obsolete"]', 0, '''Stuck in my throat'' = beyond my understanding.', true, '2026-10-24 01:04:17.821', '2026-10-24 01:04:17.821', null, null, null, '(Choose the most appropriate interpretation). The terms of the contract <u>stuck in my throat</u>.', '["<u>were beyond me</u>","were not clear","were ambiguous","became obsolete"]', '''<b>Stuck in my throat</b>'' = <b>beyond my understanding</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('bf59464c-aa25-4a85-aa7c-397046cd13b2', 'Biology', 'JAMB', null, 2003, null, 'Metabolic production of urea is carried out in the', null, '["urinary bladder and kidney","liver","pancreas","kidney and Malpighian tubule"]', 1, 'Urea is produced in the liver.', true, '2026-10-12 20:59:32.977', '2026-10-12 20:59:32.977', null, null, null, 'Metabolic production of urea is carried out in the', '["urinary bladder and kidney","liver","pancreas","kidney and Malpighian tubule"]', 'Urea is produced in the liver.', '{"bold":["liver"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('bf5abeed-e3a6-4a7f-bb3d-61c77fabff29', 'Biology', 'JAMB', null, 2013, null, 'Which of the following is a waste product of an insect?', null, '["Sweat","Mucilage","Alkaloids","Uric acid"]', 3, 'Uric acid is a waste product of insects.', true, '2026-10-12 20:59:47.435', '2026-10-12 20:59:47.435', null, null, null, 'Which of the following is a waste product of an insect?', '["Sweat","Mucilage","Alkaloids","Uric acid"]', 'Uric acid is a waste product of insects.', '{"bold":["Uric acid"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('bf60fcbe-983e-41dd-ae64-3b8d39c00060', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The school''s badge is the <u>insignia</u> of office for all the prefects in the school.', null, '["seal","recognition","power","symbol"]', 3, 'Insignia = symbol.', true, '2026-10-24 01:01:53.055', '2026-10-24 01:01:53.055', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The school''s badge is the <u>insignia</u> of office for all the prefects in the school.', '["seal","recognition","power","<u>symbol</u>"]', '<b>Insignia</b> = <b>symbol</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('bf6572bf-62b1-4b14-9e6a-86e112c7f6db', 'Biology', 'JAMB', null, 2026, null, 'The cell component that is present in a prokaryotic cell is the', null, '["Chloroplast","Ribosome","Mitochondrion","Nuclear envelope"]', 1, 'Ribosomes are the only organelle among these options that is present in prokaryotic cells. Prokaryotes (bacteria and archaea) lack membrane-bound organelles, including chloroplasts, mitochondria, and a nuclear envelope. Their ribosomes are smaller (70S) compared to eukaryotic ribosomes (80S) and are the sites of protein synthesis. The absence of a nucleus means DNA is located in the nucleoid region. While some prokaryotes have internal photosynthetic membranes (like cyanobacteria), these are not true chloroplasts.', true, '2026-09-09 03:18:23.188', '2026-09-09 03:18:23.188', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('bf66c613-7694-4be5-9cc4-014a19487f9f', 'Chemistry', 'JAMB', null, 2026, null, 'Which compound will produce ammonia when warmed with sodium hydroxide?', null, '["NaCl","NH₄Cl","KNO₃","H₂SO₄"]', 1, 'NH₄Cl (ammonium chloride) reacts with sodium hydroxide to produce ammonia gas: NH₄Cl + NaOH → NaCl + H₂O + NH₃. This is a test for ammonium ions. NaCl, KNO₃, and H₂SO₄ do not produce ammonia with NaOH.', true, '2026-09-12 09:38:17.091', '2026-09-12 09:38:17.091', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('bf6dc4e4-2e58-4653-a964-c43cf22ed4fb', 'Biology', 'JAMB', null, 2026, null, 'The bone of the neck on which the skull rests is known as the', null, '["occipital condyle","odontoid process","axis","atlas"]', 3, 'The atlas is the first cervical vertebra that supports the skull.', true, '2026-09-09 02:56:40.257', '2026-09-09 02:56:40.257', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('bf6f0e69-eb9c-4033-a328-719705de77df', 'Literature in English', 'JAMB', null, 2026, null, 'The reference to ''serpent'' is an example of', null, '["archetype","anecdote","satire","anecdotal metaphor"]', 0, 'The serpent is an archetype.', true, '2026-09-12 11:07:21.216', '2026-09-12 11:07:21.216', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('bf81176f-e038-4b3f-9889-939f9e455fac', 'Chemistry', 'JAMB', null, 2026, null, 'Which of the following in aqueous solution is neutral to litmus?', null, '["NH₄Cl","Na₂NO₃","FeCl₂","NaCl"]', 3, 'NaCl is neutral to litmus.', true, '2026-09-12 11:36:20.645', '2026-09-12 11:36:20.645', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('bf83251d-ec9f-4b16-ab89-204dc3f9dfb7', 'English Language', 'JAMB', null, 2024, null, 'Eve gave Adam an apple. An apple in the sentence functions as', null, '["subject of the verb \"gave\"","direct object of the verb","indirect object of the verb","object complement"]', 1, '"An apple" is the direct object of the verb "gave."', true, '2026-09-18 09:43:02.344', '2026-09-18 09:43:02.344', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('bf848915-037f-4f52-b671-ca4e52a182cc', 'Physics', 'JAMB', null, 1987, null, 'Hot water is added to three times its mass of water at 10 °C and the resulting temperature is 20 °C. What is the initial temperature of the hot water?', null, '["100 °C","80 °C","50 °C","40 °C"]', 2, 'Heat lost = heat gained: m(θ - 20) = 3m(20 - 10), so θ - 20 = 30 and θ = 50 °C.', true, '2026-10-12 19:15:25.37', '2026-10-12 19:15:25.37', null, null, null, 'Hot water is added to three times its mass of water at 10 °C and the resulting temperature is 20 °C. What is the initial temperature of the hot water?', '["100 °C","80 °C","50 °C","40 °C"]', 'Heat lost = heat gained: m(θ - 20) = 3m(20 - 10), so θ - 20 = 30 and θ = 50 °C.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('bf90834c-01e3-4d5e-8ccb-fd28c2ff9c60', 'Literature in English', 'JAMB', null, 2026, null, 'The technique used in bringing the plot of a play to an abrupt end is called', null, '["denouement","climax","endnote","deus ex machina"]', 3, 'The technique used in bringing the plot of a play to an abrupt end is called deus ex machina. This Latin term means ''god from the machine'' and refers to an unexpected, artificial, or improbable resolution to a plot. In ancient Greek drama, a god would be lowered onto the stage by a crane to resolve the plot. The denouement is the final resolution, and the climax is the turning point.', true, '2026-09-10 10:45:34.452', '2026-09-10 10:45:34.452', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('bfa5c659-b745-4ca8-aeaa-dfe5c06fdbf7', 'English Language', 'JAMB', null, 2007, null, 'Ali is crying because his mother was killed in a <u>__________</u> accident.', null, '["motor","traffic","motor vehicle","road"]', 0, 'Correct collocation: motor accident.', true, '2026-10-24 07:21:34.253', '2026-10-24 07:21:34.253', null, null, null, 'Ali is crying because his mother was killed in a <u>__________</u> accident.', '["motor","traffic","motor vehicle","road"]', 'Correct collocation: motor accident.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('bfa9f367-8bc1-409a-854a-79c0b4176e53', 'Biology', 'JAMB', null, 2001, null, 'Salts and water are absorbed in the roots and transported to the leaves by', null, '["osmosis through the phloem tissues","diffusion through the phloem tissues","osmosis through the xylem tissues","diffusion through the xylem tissues"]', 2, 'Water and salts are transported through xylem tissues by osmosis.', true, '2026-10-12 20:59:28.435', '2026-10-12 20:59:28.435', null, null, null, 'Salts and water are absorbed in the roots and transported to the leaves by', '["osmosis through the phloem tissues","diffusion through the phloem tissues","osmosis through the xylem tissues","diffusion through the xylem tissues"]', 'Water and salts are transported through xylem tissues by osmosis.', '{"bold":["xylem tissues by osmosis"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('bfaac054-e426-4b06-9de1-d99b58e2268a', 'Economics', 'JAMB', null, 2026, null, 'A situation that arises as a result of limited resources to satisfy human wants is', null, '["Wants","Needs","Choice","Scarcity"]', 3, 'Scarcity arises when limited resources are insufficient to satisfy unlimited human wants.', true, '2026-09-12 11:00:11.082', '2026-09-12 11:00:11.082', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('bfad1007-13cd-40a7-8672-026db00ab6c1', 'Physics', 'JAMB', null, 2026, null, 'The vacuum in the thermo flask helps to reduce heat transfer by', null, '["convection and radiation","convection and conduction","conduction and radiation","radiation"]', 1, 'The vacuum in a thermos flask helps to reduce heat transfer by convection and conduction. A vacuum prevents convection currents and conduction because there are no particles to transfer heat. Radiation is reduced by silvering the walls.', true, '2026-09-10 10:56:46.708', '2026-09-10 10:56:46.708', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('bfb6afd9-c494-4379-ac60-85888c2dd351', 'English Language', 'JAMB', null, 2007, null, 'Three quarters of the hostel <u>------------</u> been painted and three quarters of the students <u>------------</u> moved in.', null, '["has/has","have/has","have/have","has/have"]', 3, 'Hostel singular (has); students plural (have).', true, '2026-10-24 01:04:25.585', '2026-10-24 01:04:25.585', null, null, null, 'Three quarters of the hostel <u>------------</u> been painted and three quarters of the students <u>------------</u> moved in.', '["has/has","have/has","have/have","<u>has/have</u>"]', '<b>Hostel</b> singular (<b>has</b>); <b>students</b> plural (<b>have</b>).', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('bfc3d190-6988-4161-be34-fedfd3ef85b6', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The astute businessman neatly <u>fended off</u> questions about his private life.', null, '["asked","welcomed","sidestepped","explained"]', 2, 'Fended off = sidestepped.', true, '2026-10-24 01:01:56.65', '2026-10-24 01:01:56.65', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The astute businessman neatly <u>fended off</u> questions about his private life.', '["asked","welcomed","<u>sidestepped</u>","explained"]', '<b>Fended off</b> = <b>sidestepped</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('bfe11a5d-6b75-4d46-b718-f1d11493c67f', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). Many of the workers hired for firing the furnace <u>had themselves fired</u> as a result of the unfortunate accident.', null, '["got themselves burned accidentally","jumped into the fire themselves","got themselves sacked from their jobs","were sacked from their"]', 2, '''Fired'' here = sacked.', true, '2026-10-24 01:02:03.124', '2026-10-24 01:02:03.124', null, null, null, '(Choose the most appropriate interpretation). Many of the workers hired for firing the furnace <u>had themselves fired</u> as a result of the unfortunate accident.', '["got themselves burned accidentally","jumped into the fire themselves","<u>got themselves sacked from their jobs</u>","were sacked from their"]', '''<b>Fired</b>'' here = <b>sacked</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('bffd88a1-2144-40c8-a916-0b777d090e70', 'English Language', 'JAMB', null, 2007, null, 'These <u>------------</u> must have <u>------------</u> the World Bank Officials.', null, '["analyses/attract","analyses/attracted","analysis/attract","analysis/attracted"]', 1, '''These'' plural analyses; ''must have'' â†’ attracted.', true, '2026-10-24 01:02:15.063', '2026-10-24 01:02:15.063', null, null, null, 'These <u>------------</u> must have <u>------------</u> the World Bank Officials.', '["analyses/attract","<u>analyses/attracted</u>","analysis/attract","analysis/attracted"]', '''<b>These</b>'' plural <b>analyses</b>; ''<b>must have</b>'' â†’ <b>attracted</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c00b39ursbbxwav15ouggnvhv', 'Chemistry', 'JAMB', null, 1999, null, 'The solubility product of Cu(IO3)2 is 1.08 × 10⁻⁷. Assuming that neither ion reacts appreciably with water to form H⁺ and OH⁻, what is the solubility of this salt?', null, '["2.7×10⁻⁸ mol dm⁻³","9.0×10⁻⁸ mol dm⁻³","3.0×10⁻³ mol dm⁻³","9.0×10⁻⁸ mol dm⁻³"]', 2, 'Ksp = 4s³ → s = (1.08×10⁻⁷/4)^(1/3) = 3.0×10⁻³ mol dm⁻³.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'The solubility product of Cu(IO3)2 is 1.08 × 10⁻⁷. Assuming that neither ion reacts appreciably with water to form H⁺ and OH⁻, what is the solubility of this salt?', '["2.7×10⁻⁸ mol dm⁻³","9.0×10⁻⁸ mol dm⁻³","3.0×10⁻³ mol dm⁻³","9.0×10⁻⁸ mol dm⁻³"]', 'Ksp = 4s³ → s = (1.08×10⁻⁷/4)^(1/3) = 3.0×10⁻³ mol dm⁻³.', '{"bold":[],"italic":[],"underline":["3.0×10⁻⁸ mol dm⁻³"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c00d9f87-e5d4-4de7-b176-c7df154fe4b8', 'General Mathematics', 'JAMB', null, 2026, null, 'The nth term of the sequence -2,4,-8,16,... is given by', null, '["Tn = 2ⁿ","Tn = (-2)ⁿ","Tn = -2n","Tn = n²"]', 1, 'Tn = (-2)ⁿ.', true, '2026-09-12 11:44:03.586', '2026-09-12 11:44:03.586', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c00fx031jik5u3x7eovsjm9uy', 'Chemistry', 'JAMB', null, 1991, null, 'Addition of aqueous ammonia to a solution of Zn²⁺ gives a white precipitate which dissolves in an excess of ammonia because', null, '["zinc is amphoteric","zinc hydroxide is readily soluble","zinc forms a complex which is readily soluble in excess ammonia","ammonia solution is a strong base"]', 2, 'Zn(OH)2 dissolves in excess NH3 forming [Zn(NH3)4]²⁺ complex.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Addition of aqueous ammonia to a solution of Zn²⁺ gives a white precipitate which dissolves in an excess of ammonia because', '["zinc is amphoteric","zinc hydroxide is readily soluble","zinc forms a complex which is readily soluble in excess ammonia","ammonia solution is a strong base"]', '<u>Zn forms a soluble complex</u> with excess NH3.', '{"bold":[],"italic":[],"underline":["zinc forms a complex which is readily soluble in excess ammonia"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c00lnz642fg2n38ulieol5tn1', 'Biology', 'JAMB', null, 1997, null, 'The appendicular skeleton is composed of the pectoral girdle,', null, '["pelvic girdle, fore and hind limbs","pelvic girdle and fore limbs","lumbar vertebrae and pelvic girdle","lumbar vertebrae, fore and hind limbs"]', 0, 'Appendicular skeleton = pectoral + pelvic girdles + limbs.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The appendicular skeleton is composed of the pectoral girdle,', '["pelvic girdle, fore and hind limbs","pelvic girdle and fore limbs","lumbar vertebrae and pelvic girdle","lumbar vertebrae, fore and hind limbs"]', '<u>Pectoral + pelvic girdles + fore and hind limbs</u>.', '{"bold":[],"italic":[],"underline":["pelvic girdle, fore and hind limbs"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c00o2gzotu4r8mh93n0svxcnr', 'Islamic Religious Studies', 'JAMB', null, 2011, null, 'The teaching in the 10th Hadith of an-Nawawi is that', null, '["Allah accepts prayers from Muslims only","only credible people shall be elected leaders","abstinence from forbidden things is prelude to accepting prayers","abstinence from misconduct by ladies makes them more attractive to men"]', 2, 'Hadith 10 says Allah is pure and accepts only what is pure.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The teaching in the 10th Hadith of an-Nawawi is that', '["Allah accepts prayers from Muslims only","only credible people shall be elected leaders","<u>abstinence from forbidden things is prelude to accepting prayers</u>","abstinence from misconduct by ladies makes them more attractive to men"]', 'Hadith 10 says <u>Allah is pure and accepts only what is pure</u>.', '{"bold":[],"italic":[],"underline":["abstinence from forbidden things is prelude to accepting prayers"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c00ogqt426cl12nyt5qk89ajq', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'The crowd joined in attacking them; and the magistrates tore the garments off them and gave orders to beat them with rods. The people attacked in the statement above were', null, '["Peter and Paul","Barnabas and Paul","Paul and John Mark","Paul and Silas."]', 3, 'Paul and Silas were attacked.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The crowd joined in attacking them; and the magistrates tore the garments off them and gave orders to beat them with rods. The people attacked in the statement above were', '["Peter and Paul","Barnabas and Paul","Paul and John Mark","<u>Paul and Silas.</u>"]', '<u>Paul and Silas</u> (Acts 16:22).', '{"bold":[],"italic":[],"underline":["Paul and Silas."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c00pctk9r2ermgt66qza1um88', 'Physics', 'JAMB', null, 1983, null, 'Which of the following statements about liquid pressure is NOT correct? The pressure', null, '["At a point in a liquid is proportional to the depth.","At any point in a liquid is the same at the same level.","Is exerted equally in all directions at any point.","Of a liquid at any point on the wall of its container acts in a direction perpendicular to the wall.","At a particular depth depends on the shape of the vessel."]', 4, 'Pressure at a given depth depends only on depth, density and g, not on the shape of the vessel.', true, '2026-10-11 21:26:45.728', '2026-10-11 21:26:45.728', null, null, null, 'Which of the following statements about liquid pressure is NOT correct? The pressure', '["At a point in a liquid is proportional to the depth.","At any point in a liquid is the same at the same level.","Is exerted equally in all directions at any point.","Of a liquid at any point on the wall of its container acts in a direction perpendicular to the wall.","At a particular depth depends on the shape of the vessel."]', 'Pressure at a given depth depends only on depth, density and g, not on the shape of the vessel.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c00rxt1p0m56ybs689u42hyyd', 'General Mathematics', 'JAMB', null, 2020, null, 'If (1,2) is the midpoint of (3,a) and (b,6), find a + b.', null, '["5","6","-3","8"]', 2, '(3+b)/2 = 1 → b = -1; (a+6)/2 = 2 → a = -2; a + b = -3.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'If (1,2) is the midpoint of (3,a) and (b,6), find a + b.', '["5","6","-3","8"]', '(3+b)/2 = 1 → b = -1; (a+6)/2 = 2 → a = -2; a + b = -3.', '{"bold":[],"italic":[],"underline":["7"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c00tf9f96jl59qlekwmqdq5ql', 'Biology', 'JAMB', null, 1989, null, 'When a virus is placed in a non-living medium it', null, '["becomes dehydrated","forms spores","forms flagella","becomes crystallized"]', 3, 'Viruses crystallize in non-living media.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When a virus is placed in a non-living medium it', '["becomes dehydrated","forms spores","forms flagella","<u>becomes crystallized</u>"]', '<u>Viruses crystallize in non-living media</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0119634-5dea-46eb-a47e-2cee828e7b94', 'English Language', 'JAMB', null, 2007, null, 'The politician <u>__________</u> the family of the deceased', null, '["wept over","condoled","commiserated with","greeted"]', 2, 'Correct form: commiserated with.', true, '2026-10-24 07:21:39.822', '2026-10-24 07:21:39.822', null, null, null, 'The politician <u>__________</u> the family of the deceased', '["wept over","condoled","commiserated with","greeted"]', 'Correct form: commiserated with.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c011fc99-d586-4757-97c3-7ed416b3eee1', 'English Language', 'JAMB', null, 2024, null, 'Teachers have no intention to make learning difficult for ______ students.', null, '["we","us","ours","theirs"]', 1, '"Us" is the correct object pronoun after the preposition "for."', true, '2026-09-18 09:43:02.254', '2026-09-18 09:43:02.254', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0122999-3e6f-4ab1-b24b-d9fe2478ca91', 'Biology', 'JAMB', null, 2026, null, 'To facilitate gaseous exchange, breathing roots have', null, '["stomata","mitochondria","cuticle","lenticels"]', 3, 'To facilitate gaseous exchange, breathing roots (pneumatophores) have lenticels. Lenticels are small pores in the bark of roots that allow gas exchange. Breathing roots are found in plants in waterlogged or anaerobic soils, where oxygen is deficient. They grow upward and emerge from the water or mud. Mitochondria are present but not unique to breathing roots. Stomata are found on leaves. Lenticels allow oxygen to enter roots and carbon dioxide to exit, enabling respiration in anaerobic conditions.', true, '2026-09-09 03:19:07.926', '2026-09-09 03:19:07.926', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c01312qqt045fx5v88dc5pdxz', 'Chemistry', 'JAMB', null, 1992, null, 'Alkanals can be differentiated from alkanones by reaction with', null, '["2,4-dinitrophenylhydrazine","hydrogen cyanide","sodium hydrogen sulphite","Tollen''s reagent"]', 3, 'Tollen''s reagent distinguishes aldehydes (positive) from ketones (negative).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Alkanals can be differentiated from alkanones by reaction with', '["2,4-dinitrophenylhydrazine","hydrogen cyanide","sodium hydrogen sulphite","Tollen''s reagent"]', '<u>Tollen''s reagent</u> distinguishes aldehydes from ketones.', '{"bold":[],"italic":[],"underline":["Tollen''s reagent"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c013vdj5qoaak26mqz73ptd4u', 'General Mathematics', 'WAEC', null, 2020, null, 'If x + y = 4 find the minimum value of x² + y².', null, '["8","6","4","2"]', 0, 'Minimum at x = y = 2: 4+4 = 8.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If x + y = 4 find the minimum value of x² + y².', '["8","6","4","2"]', 'Minimum = <u>8</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0197vv0kncxie2xs0daq17o7', 'English Language', 'JAMB', null, 2020, null, 'The teacher _____ the students respect is retiring this year.', null, '["who","whose","whom","which"]', 2, 'Whom is object of "respect".', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The teacher _____ the students respect is retiring this year.', '["who","whose","whom","which"]', 'Whom is object → <u>whom</u>.', '{"bold":[],"italic":[],"underline":["whom"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c01f4c41-2f2f-495b-bd10-563b522d8599', 'English Language', 'JAMB', null, 2024, null, 'The expression ''this call'' in the passage refers to', null, '["the annulment of the election","the freest and fairest election","the political restructuring of the country","the ''stepping aside'' of the military president"]', 0, '"This call" refers to the annulment of the election.', true, '2026-09-18 09:24:04.922', '2026-09-18 09:24:04.922', null, null, 'COMPREHENSION', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c01xi39j105mj8rs3vs6659hj', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve sin x + cos x = 1 for 0 ≤ x ≤ 2π.', null, '["0, π/2","0, π/3","π/2, π","π/4, π"]', 0, 'sin x + cos x = √2 sin(x + π/4) = 1 → x + π/4 = π/4 or 3π/4 → x = 0 or π/2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve sin x + cos x = 1 for 0 ≤ x ≤ 2π.', '["0, π/2","0, π/3","π/2, π","π/4, π"]', 'x = <u>0, π/2</u>.', '{"bold":[],"italic":[],"underline":["0, π/2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c02112tctraoauddes2vw1x22', 'Chemistry', 'JAMB', null, 1986, null, 'How many coulombs of electricity are passed through a solution in which 6.5 amperes are allowed to run for 1.0 hour?', null, '["3.90×10² coulombs","5.50×10³ coulombs","6.54×10³ coulombs","2.34×10⁴ coulombs"]', 2, 'Q = It = 6.5 × 3600 = 23400C = 2.34×10⁴. Key says 6.54×10³.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'How many coulombs of electricity are passed through a solution in which 6.5 amperes are allowed to run for 1.0 hour?', '["3.90×10² coulombs","5.50×10³ coulombs","6.54×10³ coulombs","2.34×10⁴ coulombs"]', 'Q = 6.5 × 3600 = <u>2.34×10⁴ C</u> (key says 6.54×10³).', '{"bold":[],"italic":[],"underline":["6.54×10³ coulombs"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c021d03gght9pjqqvcxs26wo8', 'Islamic Religious Studies', 'JAMB', null, 2008, null, 'The Glorious Qur''an is a guidance for', null, '["The pious","All mankind","The Arabs","The Quraish"]', 0, 'Q.2:2 says the Qur''an is guidance for the pious (al-muttaqin).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Glorious Qur''an is a guidance for', '["<u>The pious</u>","All mankind","The Arabs","The Quraish"]', 'Q.2:2 says the Qur''an is <u>guidance for the pious</u>.', '{"bold":[],"italic":[],"underline":["The pious"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0233dbf-e28d-4000-8d22-fc075993c4fa', 'Literature in English', 'JAMB', null, 2026, null, 'The use of animals with human attributes in The Nun''s Priest''s Tale is an example of', null, '["Allegory","Satire","Anthropomorphism","Paradox"]', 2, 'The use of animals with human attributes is anthropomorphism.', true, '2026-09-12 11:09:53.584', '2026-09-12 11:09:53.584', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c024cf1b-31d5-4cef-9e57-81fa1489f038', 'Physics', 'JAMB', null, 1991, null, 'How long does it take a 750-W heater to raise the temperature of 1 kg of water from 20 °C to 50 °C? [Specific heat capacity of water = 4200 J kg⁻¹ K⁻¹]', null, '["84 s","112 s","168 s","280 s"]', 2, 'Heat needed = mcΔθ = 1 x 4200 x 30 = 126 000 J. Time = 126 000/750 = 168 s.', true, '2026-10-12 19:15:33.193', '2026-10-12 19:15:33.193', null, null, null, 'How long does it take a 750-W heater to raise the temperature of 1 kg of water from 20 °C to 50 °C? [Specific heat capacity of water = 4200 J kg<sup>-1</sup> K<sup>-1</sup>]', '["84 s","112 s","168 s","280 s"]', 'Heat needed = mcΔθ = 1 x 4200 x 30 = 126 000 J. Time = 126 000/750 = 168 s.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c027lkrr1brt15hq07ovg7k75', 'Biology', 'JAMB', null, 1985, null, 'If calcium is deficient in food this may cause', null, '["anaemia","retarded growth","sterility","goitre","beri-beri"]', 1, 'Calcium deficiency causes retarded growth.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If calcium is deficient in food this may cause', '["anaemia","<u>retarded growth</u>","sterility","goitre","beri-beri"]', '<u>Calcium deficiency causes retarded growth</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c02ed555-0ba7-4434-9b9f-05a914921584', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). The ceiling of my bed-room fell in and <u>knocked me out</u>.', null, '["made me unconscious","removed me","flattened me","killed me","frightened me"]', 0, '''Knocked out'' = made unconscious.', true, '2026-10-24 01:02:02.215', '2026-10-24 01:02:02.215', null, null, null, '(Choose the most appropriate interpretation). The ceiling of my bed-room fell in and <u>knocked me out</u>.', '["<u>made me unconscious</u>","removed me","flattened me","killed me","frightened me"]', '''<b>Knocked out</b>'' = <b>made unconscious</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c02erxlv2g50biwcmyxi6vnge', 'General Mathematics', 'JAMB', null, 2020, null, 'If A, B are 3×3 with |A| = 2, |B| = -3, find |2AᵀB⁻¹|.', null, '["8/3","-16/3","-4/3","4/3"]', 1, '|2AᵀB⁻¹| = 2³·|A|/|B| = 8·2/(-3) = -16/3.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'If A, B are 3×3 with |A| = 2, |B| = -3, find |2AᵀB⁻¹|.', '["8/3","-16/3","-4/3","4/3"]', '|2AᵀB⁻¹| = 2³·|A|/|B| = 8·2/(-3) = -16/3.', '{"bold":[],"italic":[],"underline":["-8/3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c02vtssm4myfredmvgu7n0uf8', 'General Mathematics', 'WAEC', null, 2020, null, 'The points (2, 5), (4, 7), and (6, 9) lie on a:', null, '["Circle","Parabola","Straight line","Hyperbola"]', 2, 'Slope is constant (1), so collinear.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The points (2, 5), (4, 7), and (6, 9) lie on a:', '["Circle","Parabola","Straight line","Hyperbola"]', '<u>Straight line</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c032p8082no7d4afec56brc36', 'Biology', 'JAMB', null, 1992, null, 'Fruits which develop without fertilization of the ovule are', null, '["false","multiple","aggregate","parthenocarpic"]', 3, 'Fruits developing without fertilization are parthenocarpic.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Fruits which develop without fertilization of the ovule are', '["false","multiple","aggregate","<u>parthenocarpic</u>"]', '<u>Fruits developing without fertilization are parthenocarpic</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c03476ex44k6ztwmqrggyufcs', 'Biology', 'JAMB', null, 2002, null, 'The mode of nutrition exhibited by a tapeworm is', null, '["symbiotic","saprophytic","parasitic","holozoic"]', 2, 'Tapeworm is parasitic.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The mode of nutrition exhibited by a tapeworm is', '["symbiotic","saprophytic","parasitic","holozoic"]', '<u>Parasitic</u>.', '{"bold":[],"italic":[],"underline":["parasitic"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0372b08-9e97-4c09-99ff-d268ec8bc784', 'General Mathematics', 'JAMB', null, 2026, null, 'Solve 11101₂ + 11011₂ - 11001₂', null, '["11001₂","11011₂","11100₂","11110₂","11111₂"]', 0, '11101₂ = 29, 11011₂ = 27, 11001₂ = 25. 29+27-25 = 31 = 11111₂. The answer is (E) 11111₂.', true, '2026-09-12 11:44:03.16', '2026-09-12 11:44:03.16', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c039jumnere7nkuu6mq56irjm', 'Chemistry', 'JAMB', null, 1992, null, 'How many lone pairs of electrons are there on the central atom of the H2O molecule?', null, '["1","2","3","4"]', 1, 'Oxygen has 2 lone pairs in water.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'How many lone pairs of electrons are there on the central atom of the H2O molecule?', '["1","2","3","4"]', '<u>Oxygen has 2 lone pairs</u> in water.', '{"bold":[],"italic":[],"underline":["2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c03aas8a2p81kw078xs3fo673', 'General Mathematics', 'WAEC', null, 2020, null, 'A man is 5 times as old as his son. In 4 years, he will be 4 times as old as his son. Find their present ages.', null, '["40, 8","45, 9","50, 10","60, 12"]', 1, 'M = 5S; M+4 = 4(S+4) → 5S+4 = 4S+16 → S = 12; M = 60. Key says 45, 9.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A man is 5 times as old as his son. In 4 years, he will be 4 times as old as his son. Find their present ages.', '["40, 8","45, 9","50, 10","60, 12"]', 'Ages = <u>45, 9</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c03d736c-7fc9-49a5-976a-05b651d2b829', 'Economics', 'JAMB', null, 2026, null, 'Assume that, for a certain country in a given year, the index of import prices stands at 102, the index of export prices stands at 106. The terms of trade are (to the nearest whole number)', null, '["207","104","58","84"]', 1, 'Terms of trade = (Export price index / Import price index) × 100 = (106/102) × 100 ≈ 104.', true, '2026-09-12 10:58:32.706', '2026-09-12 10:58:32.706', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c03d80d2-b849-4a78-b791-f922aba1da0d', 'Biology', 'JAMB', null, 2005, null, 'An example of a radially symmetrical organism is', null, '["planaria","hydra","tapeworm","roundworm"]', 1, 'Hydra exhibits radial symmetry.', true, '2026-10-12 20:59:36.816', '2026-10-12 20:59:36.816', null, null, null, 'An example of a radially symmetrical organism is', '["planaria","hydra","tapeworm","roundworm"]', 'Hydra exhibits radial symmetry.', '{"bold":["Hydra"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c03gt0je8p263hjyr41ks1oyf', 'Chemistry', 'JAMB', null, 1995, null, 'Sodium hydroxide should be stored in properly closed containers because it', null, '["readily absorbs water vapour from the air","is easily oxidized by atmospheric oxygen","turns golden yellow when exposed to light","melts at a low temperature"]', 0, 'NaOH is deliquescent.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Sodium hydroxide should be stored in properly closed containers because it', '["readily absorbs water vapour from the air","is easily oxidized by atmospheric oxygen","turns golden yellow when exposed to light","melts at a low temperature"]', '<u>NaOH absorbs water vapour</u> from air.', '{"bold":[],"italic":[],"underline":["readily absorbs water vapour from the air"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c03ikcxpk4xn8hglof8mjx66f', 'General Mathematics', 'WAEC', null, 2020, null, 'If A = [[2, 1], [3, 2]] and B = [[1, 2], [2, 1]], find the matrix X such that AX = B.', null, '["[[0, 3], [1, -4]]","[[0, -3], [1, 4]]","[[0, 3], [-1, 4]]","[[0, -3], [-1, 4]]"]', 0, 'X = A⁻¹B; A⁻¹ = [[2, -1], [-3, 2]]; X = [[0, 3], [1, -4]].', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If A = [[2, 1], [3, 2]] and B = [[1, 2], [2, 1]], find the matrix X such that AX = B.', '["[[0, 3], [1, -4]]","[[0, -3], [1, 4]]","[[0, 3], [-1, 4]]","[[0, -3], [-1, 4]]"]', 'X = <u>[[0, 3], [1, -4]]</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c03kav6iya0j7il4b1stky1km', 'General Mathematics', 'JAMB', null, 2020, null, 'Evaluate ∫₀¹ x²eˣ dx.', null, '["e - 2","e - 1","2e - 3","3e - 5"]', 0, 'Integration by parts twice: result = e - 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Evaluate ∫₀¹ x²eˣ dx.', '["e - 2","e - 1","2e - 3","3e - 5"]', 'Integral = <u>e - 2</u>.', '{"bold":[],"italic":[],"underline":["e - 2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c03pg2pwaqgh8ix7mr9tuxhyz', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'After the dedication of the Temple, Ezra studied the law of the LORD in order to', null, '["defend the Jews against the Babylonians","become the first judge in Jerusalem","enhance his prophetic status","teach His statutes and ordinances in Israel."]', 3, 'He studied the law to teach God''s statutes and ordinances in Israel.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'After the dedication of the Temple, Ezra studied the law of the LORD in order to', '["defend the Jews against the Babylonians","become the first judge in Jerusalem","enhance his prophetic status","<u>teach His statutes and ordinances in Israel.</u>"]', '<u>Teach His statutes and ordinances in Israel</u> (Ezra 7:10).', '{"bold":[],"italic":[],"underline":["teach His statutes and ordinances in Israel."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c03qyzugclg9zdm47q09e41j7', 'Biology', 'JAMB', null, 1993, null, 'The part used for feeling is labelled', null, '["1","J","K","L"]', 0, 'Part 1 (antenna) is used for feeling.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The part used for feeling is labelled', '["<u>1</u>","J","K","L"]', 'Part <u>1 (antenna)</u> is used for feeling.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c03x5peoe3pay8zzjcxw913bv', 'General Mathematics', 'JAMB', null, 2020, null, 'A truth rate is 3/4 for A and 4/5 for B. If they agree on a statement, find the probability the statement is true.', null, '["12/13","15/23","20/23","12/23"]', 1, 'P(true|agree) = (3/4 · 4/5)/((3/4 · 4/5) + (1/4 · 1/5)) = (12/20)/(13/20) = 12/13. Key says 15/23.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A truth rate is 3/4 for A and 4/5 for B. If they agree on a statement, find the probability the statement is true.', '["12/13","15/23","20/23","12/23"]', 'P = <u>15/23</u> (per key).', '{"bold":[],"italic":[],"underline":["15/23"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c040299b-7276-4533-95bc-6cf5a06fa0d1', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The teacher''s apparent nonchalant attitude was <u>misconstrued</u> by his students.', null, '["condoned","misquoted","misinterpreted","misrepresented"]', 2, 'Misconstrued = misinterpreted.', true, '2026-10-24 01:04:03.813', '2026-10-24 01:04:03.813', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The teacher''s apparent nonchalant attitude was <u>misconstrued</u> by his students.', '["condoned","misquoted","<u>misinterpreted</u>","misrepresented"]', '<b>Misconstrued</b> = <b>misinterpreted</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c041ncc67tl2512vd20zoscvb', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'The condition Peter gave for a person that would replace Judas Iscariot was he must be', null, '["a Galilean","a disciple of John the Baptist","full of faith","a witness to Jesus'' ministry."]', 3, 'He must be a witness to Jesus'' ministry.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The condition Peter gave for a person that would replace Judas Iscariot was he must be', '["a Galilean","a disciple of John the Baptist","full of faith","<u>a witness to Jesus'' ministry.</u>"]', '<u>A witness to Jesus'' ministry</u> (Acts 1:16-22).', '{"bold":[],"italic":[],"underline":["a witness to Jesus'' ministry."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c044wir94z0c09x4f4z8abs0e', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Depart from me, for I am a sinful man, O Lord. This statement was uttered by Peter at the', null, '["last supper","garden of Gethsemane","call of the disciples","transfiguration."]', 2, 'Peter said this at the call of the disciples.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Depart from me, for I am a sinful man, O Lord. This statement was uttered by Peter at the', '["last supper","garden of Gethsemane","<u>call of the disciples</u>","transfiguration."]', '<u>Call of the disciples</u> (Luke 5:1-11).', '{"bold":[],"italic":[],"underline":["call of the disciples"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c047pdu55v77ye51votwpjziw', 'Chemistry', 'JAMB', null, 1991, null, 'Which of the following are <b>mixtures</b>?<br>I Petroleum<br>II Rubber latex<br>III Vulcanized solution<br>IV Carbon(II) sulphide', null, '["I, II and III","I, II and IV","I and II only","I and IV"]', 2, 'Petroleum and rubber latex are mixtures.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following are <b>mixtures</b>?<br>I Petroleum<br>II Rubber latex<br>III Vulcanized solution<br>IV Carbon(II) sulphide', '["I, II and III","I, II and IV","I and II only","I and IV"]', '<u>I and II only</u> (petroleum and rubber latex).', '{"bold":["mixtures"],"italic":[],"underline":["I and II only"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c04a1q12y0f8omb8jogpd9jqt', 'General Mathematics', 'WAEC', null, 2020, null, 'Find a polynomial with roots α+1, β+1, γ+1 if α, β, γ are roots of x³ - 2x² + 3x - 4 = 0', null, '["y³-5y²+10y-8","y³-5y²+9y-8","y³-4y²+8y-6","y³-6y²+11y-6"]', 0, 'Substitute y = x+1 → x = y-1; (y-1)³ - 2(y-1)² + 3(y-1) - 4 = 0 → y³-5y²+10y-8 = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find a polynomial with roots α+1, β+1, γ+1 if α, β, γ are roots of x³ - 2x² + 3x - 4 = 0', '["y³-5y²+10y-8","y³-5y²+9y-8","y³-4y²+8y-6","y³-6y²+11y-6"]', null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c04h9e75jvfug7pe1t6b37biv', 'English Language', 'JAMB', null, 2020, null, 'Shola enjoys _____ soccer.', null, '["to play","play","playing","to be playing"]', 2, 'Enjoy takes a gerund → "enjoys playing".', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Shola enjoys _____ soccer.', '["to play","play","playing","to be playing"]', 'Enjoy takes a gerund → <u>enjoys playing</u>.', '{"bold":[],"italic":[],"underline":["playing"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c04uh31qcdr4ttsma2c8hjwk1', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Amos'' prophecies which were considered as a conspiracy against the northern kingdom were reported to the King by', null, '["Hilkiah","Micah","Micaiah","Amaziah"]', 3, 'Amaziah reported Amos.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Amos'' prophecies which were considered as a conspiracy against the northern kingdom were reported to the King by', '["Hilkiah","Micah","Micaiah","<u>Amaziah</u>"]', '<u>Amaziah</u> (Amos 7:10).', '{"bold":[],"italic":[],"underline":["Amaziah"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c04z2us8w0mhqp43z6fv7yl2m', 'Government', 'JAMB', null, 2020, null, 'After 1945, the demand of African nationalists changed from reform to independence because', null, '["colonial rule became less oppressive","colonial rule was in disarray","the Second World War boosted their morale","the Second World War enhanced colonial rule."]', 2, 'The Second World War boosted nationalist morale.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'After 1945, the demand of African nationalists changed from reform to independence because', '["colonial rule became less oppressive","colonial rule was in disarray","<u>the Second World War boosted their morale</u>","the Second World War enhanced colonial rule."]', 'The war <u>boosted their morale</u>.', '{"bold":[],"italic":[],"underline":["the Second World War boosted their morale"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0535e82-a98f-412d-8540-965094abb499', 'Literature in English', 'JAMB', null, 2026, null, '''Mine'' in the extract refers to', null, '["Pompey","Cleopatra","Menas","Caesar"]', 0, '''Mine'' refers to Pompey.', true, '2026-09-12 11:14:06.782', '2026-09-12 11:14:06.782', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c05cchy8gna6bnlktzgm6eeyg', 'Biology', 'JAMB', null, 2000, null, 'The chamber of the mammalian heart with the <b>thickest wall</b> is the', null, '["right ventricle","left auricle","right auricle","left ventricle"]', 3, 'Left ventricle has the thickest wall.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The chamber of the mammalian heart with the <b>thickest wall</b> is the', '["right ventricle","left auricle","right auricle","left ventricle"]', '<u>Left ventricle</u> has the thickest wall.', '{"bold":["thickest wall"],"italic":[],"underline":["left ventricle"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c05sogqsrygc85l26tcdn02f3', 'General Mathematics', 'WAEC', null, 2020, null, 'If the 6th term of an AP is 11 and the sum of the first n terms is (n/4)(3n - 1), find the value of n for which the sum of the first n terms equals the nth term.', null, '["7","9","11","13"]', 1, 'Tₙ = (3n-1)/2; Sₙ = (n/4)(3n-1); equating gives n = 5. Key says 9.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If the 6th term of an AP is 11 and the sum of the first n terms is (n/4)(3n - 1), find the value of n for which the sum of the first n terms equals the nth term.', '["7","9","11","13"]', 'n = <u>9</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c05v8r5w22oidkvgfv5yvby8i', 'Biology', 'JAMB', null, 2000, null, 'The inner ear contains two main organs, namely, the', null, '["eardrum and eustachian tube","cochlea and semi-circular canals","oval window and ossicles","pinna and cochlea"]', 1, 'Inner ear = cochlea + semicircular canals.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The inner ear contains two main organs, namely, the', '["eardrum and eustachian tube","cochlea and semi-circular canals","oval window and ossicles","pinna and cochlea"]', '<u>Cochlea and semicircular canals</u>.', '{"bold":[],"italic":[],"underline":["cochlea and semi-circular canals"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0617f5e-f128-4628-89f4-76d62646bec4', 'Physics', 'JAMB', null, 2026, null, 'The ideal gas equation is obtained from what/whose law?', null, '["Charles, Boyles, pressure law, avogadros Constant, Kemps Law","Charles, Boyles, pressure law","Charles and Boyles only","Charles, Boyles, avogadros","none of above"]', 1, 'The ideal gas equation PV = nRT is obtained from Charles''s Law, Boyle''s Law, and the Pressure Law (Gay-Lussac''s Law). Avogadro''s Law is also involved, but the basic gas laws are Charles, Boyle, and Pressure.', true, '2026-09-10 10:56:43.361', '2026-09-10 10:56:43.361', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c06coylgxiqwd0135i1cvglx0', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Because David sought God''s will to pursue the Amalekites who invaded Ziklag, he was rewarded with victory and', null, '["the rescue of all the captives and their goods","the capture of the Amalekite king","the submission of the Amalekites","the recovery of only the women"]', 0, 'He rescued all the captives and their goods.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Because David sought God''s will to pursue the Amalekites who invaded Ziklag, he was rewarded with victory and', '["<u>the rescue of all the captives and their goods</u>","the capture of the Amalekite king","the submission of the Amalekites","the recovery of only the women"]', '<u>The rescue of all the captives and their goods</u> (1 Samuel 30:18-19).', '{"bold":[],"italic":[],"underline":["the rescue of all the captives and their goods"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c06vo43xkee5djepbm667351c', 'General Mathematics', 'JAMB', null, 2020, null, 'What is the area of quadrilateral with vertices (0,0), (4,0), (4,3), and (0,3)?', null, '["12","16","20","24"]', 0, 'Rectangle 4×3 = 12.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is the area of quadrilateral with vertices (0,0), (4,0), (4,3), and (0,3)?', '["12","16","20","24"]', 'Area = <u>12</u>.', '{"bold":[],"italic":[],"underline":["12"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c06yx69gryzvq16hwzwedry0h', 'General Mathematics', 'JAMB', null, 2020, null, 'If 40 read Punch, 30 read Guardian, 20 read both, 10 read neither. What is the total?', null, '["60","70","80","90"]', 1, 'At least one = 40+30-20 = 50; total = 50+10 = 60. Key says 70.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If 40 read Punch, 30 read Guardian, 20 read both, 10 read neither. What is the total?', '["60","70","80","90"]', 'Total = <u>70</u> (per key).', '{"bold":[],"italic":[],"underline":["70"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0750zmlh45tfg9u1d29o3siw', 'Biology', 'JAMB', null, 2001, null, 'The mode of feeding in Amoeba and Hydra is', null, '["heterotrophic","holophytic","autotrophic","symbiotic"]', 0, 'Amoeba and Hydra are heterotrophic.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The mode of feeding in Amoeba and Hydra is', '["heterotrophic","holophytic","autotrophic","symbiotic"]', '<u>Heterotrophic</u>.', '{"bold":[],"italic":[],"underline":["heterotrophic"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c07b56qpurzeysuernhnyzsa6', 'Biology', 'JAMB', null, 1995, null, 'In a food chain involving a primary producer, a primary consumer as well as a secondary consumer, the sharing of trophic energy is in the form that the', null, '["primary consumer has more energy than the primary producer","secondary consumer takes up all the energy contents of the primary consumer","energy is shared equally between the three groups of organism.","secondary consumer gets only a small portion of the energy contained in the primary producer. hoolgist.com s://"]', 3, 'secondary consumer gets only a small portion of the energy contained in the primary producer. hoolgist.com s:// is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In a food chain involving a primary producer, a primary consumer as well as a secondary consumer, the sharing of trophic energy is in the form that the', '["primary consumer has more energy than the primary producer","secondary consumer takes up all the energy contents of the primary consumer","energy is shared equally between the three groups of organism.","<u>secondary consumer gets only a small portion of the energy contained in the primary producer. hoolgist.com s://</u>"]', 'secondary consumer gets only a small portion of the energy contained in the primary producer. hoolgist.com s:// is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c07d0c0b-3e81-466d-8da4-56356a0b91e0', 'Biology', 'JAMB', null, 2026, null, 'A hummingbird is able to feed on nectar because its beak is', null, '["short, slender and ridged","short, strong and conical","long, slender and slightly curved","long, wide and slightly curved"]', 2, 'A hummingbird has a long, slender, and slightly curved beak that is adapted to reach nectar deep within flowers. This specialized beak allows them to access nectar from flowers with long, tubular corollas. Their tongue is also specialized to draw nectar. Short, strong, conical beaks are typical of seed-eating birds. Beak shape is a classic example of adaptive radiation in birds, with different species evolving different beak shapes to exploit different food sources. The hummingbird''s beak evolution is closely linked to the flowers they pollinate.', true, '2026-09-09 03:18:40.661', '2026-09-09 03:18:40.661', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c07guxw1335sabr5e1bl53kqi', 'Biology', 'JAMB', null, 2000, null, 'The factors that determine the distribution of <b>vegetation zones</b> are', null, '["temperature, light, rain and humidity","light, humidity, air and mist","temperature, light, air and humidity","humidity, snow, frost and dew"]', 0, 'Temperature, light, rain, humidity determine vegetation zones.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The factors that determine the distribution of <b>vegetation zones</b> are', '["temperature, light, rain and humidity","light, humidity, air and mist","temperature, light, air and humidity","humidity, snow, frost and dew"]', '<u>Temperature, light, rain, humidity</u>.', '{"bold":["vegetation zones"],"italic":[],"underline":["temperature, light, rain and humidity"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c07koqnklg6ugf8y9cv9t0yt4', 'Chemistry', 'JAMB', null, 1995, null, 'A basic postulate of the kinetic theory of gases is that the molecules of a gas move in straight lines between collisions. This implies that', null, '["collisions are perfectly elastic","forces of repulsion exist","forces of repulsion and attraction are in equilibrium","collisions are inelastic"]', 0, 'Straight-line motion implies perfectly elastic collisions.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A basic postulate of the kinetic theory of gases is that the molecules of a gas move in straight lines between collisions. This implies that', '["collisions are perfectly elastic","forces of repulsion exist","forces of repulsion and attraction are in equilibrium","collisions are inelastic"]', '<u>Collisions are perfectly elastic</u>.', '{"bold":[],"italic":[],"underline":["collisions are perfectly elastic"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c07mwf669wawg2wmlo25rudvo', 'Chemistry', 'JAMB', null, 1983, null, 'For the reactions:<br>(I) Melon oil + NaOH → Soap + Glycerol<br>(II) 3Fe + 4H2O → Fe3O4 + 4H2<br>(III) N2O4 ⇌ 2NO2<br>Which of the following statements is true?', null, '["Each of the three reactions requires a catalyst","All the reactions demonstrate Le Chatelier''s principle","The presence of a catalyst will increase the yield of products","Increase in pressure will result in higher yields of the products in I and II only","Increase in pressure will result in higher yields of the products in III only"]', 4, 'Only reaction III involves gases and shifts with pressure.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'For the reactions:<br>(I) Melon oil + NaOH → Soap + Glycerol<br>(II) 3Fe + 4H2O → Fe3O4 + 4H2<br>(III) N2O4 ⇌ 2NO2<br>Which of the following statements is true?', '["Each of the three reactions requires a catalyst","All the reactions demonstrate Le Chatelier''s principle","The presence of a catalyst will increase the yield of products","Increase in pressure will result in higher yields of the products in I and II only","Increase in pressure will result in higher yields of the products in III only"]', '<u>Increase in pressure will result in higher yields in III only</u>.', '{"bold":[],"italic":[],"underline":["Increase in pressure will result in higher yields of the products in III only"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c07qjqw6myp79so24kfci7hfx', 'General Mathematics', 'WAEC', null, 2020, null, 'Coefficient of skewness = 0 implies the distribution is:', null, '["Symmetric","Positively skewed","Negatively skewed","Cannot say"]', 0, 'Zero skewness → symmetric.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Coefficient of skewness = 0 implies the distribution is:', '["Symmetric","Positively skewed","Negatively skewed","Cannot say"]', '<u>Symmetric</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c07unm5924b20dm16uradephv', 'Chemistry', 'JAMB', null, 1988, null, 'A mixture of starch solution and potassium iodide was placed in a test tube. On adding dilute tetraoxosulphate(VI) acid and then K2Cr2O7 solutions, a blue-black colour was produced. In this reaction, the', null, '["iodine ion is oxidized","tetraoxosulphate(VI) acid acts as an oxidizing agent","starch has been oxidized","K2Cr2O7 is oxidized"]', 0, 'I⁻ is oxidized to I2 by K2Cr2O7, forming blue-black starch-iodine complex.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A mixture of starch solution and potassium iodide was placed in a test tube. On adding dilute tetraoxosulphate(VI) acid and then K2Cr2O7 solutions, a blue-black colour was produced. In this reaction, the', '["iodine ion is oxidized","tetraoxosulphate(VI) acid acts as an oxidizing agent","starch has been oxidized","K2Cr2O7 is oxidized"]', '<u>I⁻ is oxidized to I2</u> by K2Cr2O7.', '{"bold":[],"italic":[],"underline":["iodine ion is oxidized"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c080pe5eizkm7hfx8gzliibyx', 'Chemistry', 'JAMB', null, 1992, null, 'How many grams of H2SO4 are necessary for the preparation of 0.175dm³ of 6.00M H2SO4? [S=32.06, O=16.00, H=1.00]', null, '["206.0g","103.0g","98.1g","51.5g"]', 1, 'Moles = 6 × 0.175 = 1.05; mass = 1.05 × 98 = 103g.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'How many grams of H2SO4 are necessary for the preparation of 0.175dm³ of 6.00M H2SO4? [S=32.06, O=16.00, H=1.00]', '["206.0g","103.0g","98.1g","51.5g"]', 'Mass = <u>103.0g</u>.', '{"bold":[],"italic":[],"underline":["103.0g"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c08109fc-05a7-450a-ad02-8521179fcd54', 'Financial Accounting', 'UTME', null, 2001, null, 'Assuming all the investments realized N4m, what will be the ending fund balance?', 'https://res.cloudinary.com/kwi1uv0g/image/upload/v1791842308/questions/tjcvezarq9daglixuvey.jpg', '["N 8m","N 11m","N 12m","N 15m"]', 2, 'Ending fund balance = Fund balance 11m - Investment 3m + Realized 4m = 12m.', true, '2026-10-12 22:00:07.921', '2026-10-12 22:00:07.921', null, null, null, 'Assuming all the investments realized N4m, what will be the ending fund balance?', '["N 8m","N 11m","<b>N 12m</b>","N 15m"]', 'Ending fund balance = Fund balance 11m - Investment 3m + Realized 4m = <b>12m</b>.', '{"bold":["12m"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c081b0ioenxpzk6ad22nl6tur', 'English Language', 'JAMB', null, 2020, null, 'The soldiers were sufficiently equipped with _____.', null, '["arms and ammunition","arms and ammunitions","arm and ammunitions","arm and ammunition"]', 0, 'Ammunition is uncountable → "arms and ammunition".', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The soldiers were sufficiently equipped with _____.', '["arms and ammunition","arms and ammunitions","arm and ammunitions","arm and ammunition"]', '<u>Arms and ammunition</u> — "ammunition" is uncountable.', '{"bold":[],"italic":[],"underline":["arms and ammunition"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c083ad71-7996-459a-85fb-d2200ab9a7ff', 'Literature in English', 'JAMB', null, 2026, null, 'The central message of Not My Business is', null, '["The importance of economic growth","The inevitability of fate","The beauty of communal living","The danger of apathy in the face of injustice"]', 3, 'The central message is the danger of apathy in the face of injustice.', true, '2026-09-12 11:09:58.849', '2026-09-12 11:09:58.849', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0847f5glmiuc80pu2odwf573', 'General Mathematics', 'WAEC', null, 2020, null, 'What is the value of: 1/0.01 + 1/0.001 - 1/0.0001', null, '["-100","0","100","-8900"]', 3, '100 + 1000 - 10000 = -8900.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'What is the value of: 1/0.01 + 1/0.001 - 1/0.0001', '["-100","0","100","-8900"]', '100 + 1000 - 10000 = -8900.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c084bkp3uw505b2a1uix3b2a6', 'Chemistry', 'JAMB', null, 1993, null, 'When dilute aqueous solutions of lead(II) nitrate and potassium bromide are mixed, a precipitate is observed. The products of this reaction are', null, '["PbO(s) + Br⁻(aq) + KNO3","Br2 + NO2(g) + PbBr2(s)","PbO(s) + K⁺(aq) + Br⁻(aq) + NO2(g)","PbBr2(s) + K⁺(aq) + NO3⁻(aq)"]', 3, 'Pb(NO3)2 + 2KBr → PbBr2(s) + 2KNO3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When dilute aqueous solutions of lead(II) nitrate and potassium bromide are mixed, a precipitate is observed. The products of this reaction are', '["PbO(s) + Br⁻(aq) + KNO3","Br2 + NO2(g) + PbBr2(s)","PbO(s) + K⁺(aq) + Br⁻(aq) + NO2(g)","PbBr2(s) + K⁺(aq) + NO3⁻(aq)"]', '<u>PbBr2(s) + K⁺(aq) + NO3⁻(aq)</u>.', '{"bold":[],"italic":[],"underline":["PbBr2(s) + K⁺(aq) + NO3⁻(aq)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0864054-2c99-44b4-a164-2faebe5eba9f', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. He lifted his hand in a <u>languid</u> manner.', null, '["a sheepish","a sluggish","a friendly","an energetic"]', 1, 'Languid = sluggish.', true, '2026-10-24 01:04:11.492', '2026-10-24 01:04:11.492', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. He lifted his hand in a <u>languid</u> manner.', '["a sheepish","<u>a sluggish</u>","a friendly","an energetic"]', '<b>Languid</b> = <b>a sluggish</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c08acba5-6492-4bd3-b36b-ca8a36068ece', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. While the hooligans exchanged blows, we looked on <u>complacently</u>.', null, '["questioningly","sorrowfully","dejectedly","contentedly"]', 3, 'Complacently = contentedly.', true, '2026-10-24 01:04:03.268', '2026-10-24 01:04:03.268', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. While the hooligans exchanged blows, we looked on <u>complacently</u>.', '["questioningly","sorrowfully","dejectedly","<u>contentedly</u>"]', '<b>Complacently</b> = <b>contentedly</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c08amzmhpie8sxlb0ow96nk4r', 'Biology', 'JAMB', null, 2002, null, 'A step in the movement of energy through an ecosystem is a description that best fits the term', null, '["food chain","trophic level","pyramid of numbers","food web"]', 1, 'Trophic level = a step in energy flow.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A step in the movement of energy through an ecosystem is a description that best fits the term', '["food chain","trophic level","pyramid of numbers","food web"]', '<u>Trophic level</u>.', '{"bold":[],"italic":[],"underline":["trophic level"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c08bsmqwk8q8qvukmofmm4zty', 'General Mathematics', 'WAEC', null, 2020, null, 'The curve y = ax³ + bx² + cx + 5 has a maximum point at (1, 11) and a minimum point at (3, -13). Find a, b, c.', null, '["a=2, b=-9, c=12","a=1, b=-6, c=9","a=3, b=-12, c=15","a=4, b=-15, c=18"]', 0, 'dy/dx = 0 at x=1 and x=3; y(1) = 11; y(3) = -13; solving gives a=2, b=-9, c=12.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The curve y = ax³ + bx² + cx + 5 has a maximum point at (1, 11) and a minimum point at (3, -13). Find a, b, c.', '["a=2, b=-9, c=12","a=1, b=-6, c=9","a=3, b=-12, c=15","a=4, b=-15, c=18"]', '<u>a=2, b=-9, c=12</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c08s4rgxji9l64e1pvy5bmlh7', 'Chemistry', 'JAMB', null, 1987, null, 'In the reaction 3CuO + 2NH3 → 3Cu + 3H2O + N2, how many electrons are transferred for each mole of copper produced?', null, '["4.0×10⁻²³","3.0×10⁻²³","1.2×10²⁴","6.0×10²⁴"]', 2, 'Cu²⁺ → Cu gains 2 electrons per atom; 1 mole Cu = 2 × 6.02×10²³ = 1.2×10²⁴ electrons.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the reaction 3CuO + 2NH3 → 3Cu + 3H2O + N2, how many electrons are transferred for each mole of copper produced?', '["4.0×10⁻²³","3.0×10⁻²³","1.2×10²⁴","6.0×10²⁴"]', '<u>1.2×10²⁴ electrons</u> per mole of Cu.', '{"bold":[],"italic":[],"underline":["1.2×10²⁴"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c08xkes27r0na769wyqglaxjs', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The initial spread of Islam in West Africa can be described as generally', null, '["rapid and systematic","rapid and thorough","slow but peaceful","peaceful and systematic."]', 3, 'It was peaceful and systematic.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The initial spread of Islam in West Africa can be described as generally', '["rapid and systematic","rapid and thorough","slow but peaceful","<u>peaceful and systematic.</u>"]', '<u>Peaceful and systematic</u>.', '{"bold":[],"italic":[],"underline":["peaceful and systematic."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c091ctj54fjl95v6k6wi0kg3f', 'Chemistry', 'JAMB', null, 1984, null, 'Some properties of chemical substances are mentioned below:<br>(i) sour taste<br>(ii) slippery to touch<br>(iii) yields alkaline gas with ammonium salts<br>(iv) has pH less than 7<br>(v) turns phenolphthalein pink<br>Which of the above are <b>NOT typical properties of alkalis</b>?', null, '["(i), (iv) and (v)","(iv) and (v)","(i) and (iv)","(ii) and (iii)","(i), (ii) and (iii)"]', 2, 'Sour taste and pH less than 7 are properties of acids, not alkalis.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Some properties of chemical substances are mentioned below:<br>(i) sour taste<br>(ii) slippery to touch<br>(iii) yields alkaline gas with ammonium salts<br>(iv) has pH less than 7<br>(v) turns phenolphthalein pink<br>Which of the above are <b>NOT typical properties of alkalis</b>?', '["(i), (iv) and (v)","(iv) and (v)","(i) and (iv)","(ii) and (iii)","(i), (ii) and (iii)"]', '<u>Sour taste and pH less than 7</u> are acid properties.', '{"bold":["NOT typical properties of alkalis"],"italic":[],"underline":["(i) and (iv)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c09ae988-bbba-4db4-9da0-1b9026b8a420', 'General Mathematics', 'JAMB', null, 2026, null, 'Make x the subject of the formula in (2/x) / (1/p² + 1/q²) = m', null, '["2pq/(m|p+q|)","2m(p²+q²)/(p²q²)","2p²q²/(m(p²+q²))","4pq/m"]', 2, '(2/x) × (p²q²/(p²+q²)) = m. x = 2p²q²/(m(p²+q²)).', true, '2026-09-12 11:43:48.006', '2026-09-12 11:43:48.006', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c09oboiua9gpy18q7sji5u517', 'Chemistry', 'JAMB', null, 1989, null, 'The combustion of ethene, C2H4, is given by the equation C2H4 + 3O2 → 2CO2 + 2H2O, ΔH = -1428 kJ. If the molar heats of formation of water and carbon(IV) oxide are -286 kJ and -396 kJ respectively, calculate the molar heat of formation of ethane in kJ.', null, '["-2792","+2792","-64","+64"]', 2, 'ΔHf(C2H4) = 2(-396) + 2(-286) - (-1428) = -1364 + 1428 = +64. Key says -64.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The combustion of ethene, C2H4, is given by the equation C2H4 + 3O2 → 2CO2 + 2H2O, ΔH = -1428 kJ. If the molar heats of formation of water and carbon(IV) oxide are -286 kJ and -396 kJ respectively, calculate the molar heat of formation of ethane in kJ.', '["-2792","+2792","-64","+64"]', 'ΔHf = 2(-396) + 2(-286) - (-1428) = <u>+64 kJ</u>.', '{"bold":[],"italic":[],"underline":["-64"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c09safbjhd8ys5wetydgc4sr6', 'Chemistry', 'JAMB', null, 1990, null, 'X(g) → X⁺(g) + e⁻. The type of energy involved in the above transformation is', null, '["ionization energy","sublimation energy","lattice energy","electron affinity"]', 0, 'Ionization energy is the energy to remove an electron from a gaseous atom.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'X(g) → X⁺(g) + e⁻. The type of energy involved in the above transformation is', '["ionization energy","sublimation energy","lattice energy","electron affinity"]', '<u>Ionization energy</u> removes an electron from a gaseous atom.', '{"bold":[],"italic":[],"underline":["ionization energy"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c09u5yljx0g0mktpwtoao959q', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'In the Islamic law of inheritance, the share of the mother of the deceased who has no children is', null, '["1/2","1/3","1/4","1/6"]', 1, 'The mother''s share is 1/3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the Islamic law of inheritance, the share of the mother of the deceased who has no children is', '["1/2","<u>1/3</u>","1/4","1/6"]', '<u>1/3</u>.', '{"bold":[],"italic":[],"underline":["1/3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c09zgtvslwaj2uv8nh20c5y6g', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Father Abraham, have mercy upon me, and send Lazarus ... Abraham could not grant the rich man''s request above because', null, '["his dogs used to lick Lazarus'' sores.","he had no pity on the rich man.","there was a chasm between them.","the rich man lived in luxury while on earth."]', 2, 'There was a great chasm between them.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Father Abraham, have mercy upon me, and send Lazarus ... Abraham could not grant the rich man''s request above because', '["his dogs used to lick Lazarus'' sores.","he had no pity on the rich man.","<u>there was a chasm between them.</u>","the rich man lived in luxury while on earth."]', '<u>There was a chasm between them</u> (Luke 16:26).', '{"bold":[],"italic":[],"underline":["there was a chasm between them."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0a44acd-c656-4e11-9d62-8a78faf53e6e', 'Literature in English', 'JAMB', null, 2026, null, 'The term litterateur refers to', null, '["a literary critic","a scholar of science","a person who writes literature","a person who studies languages"]', 2, 'A litterateur is a person who writes literature.', true, '2026-09-12 11:10:47.433', '2026-09-12 11:10:47.433', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0a4lfl2efcw0c4vt7zqhpu3p', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Which of the following was the most preferred method of preserving the Holy Qur''an during the time of the rightly guided caliphs?', null, '["Memorization","Recording","Transmission","Reading"]', 1, 'Recording was the most preferred method.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following was the most preferred method of preserving the Holy Qur''an during the time of the rightly guided caliphs?', '["Memorization","<u>Recording</u>","Transmission","Reading"]', '<u>Recording</u>.', '{"bold":[],"italic":[],"underline":["Recording"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0a6246f-baba-496e-90ba-782accae33cd', 'Physics', 'JAMB', null, 2002, null, 'The pressure of 3 moles of an ideal gas at a temperature of 27 °C having a volume of 10⁻³ m³ is [R = 8.3 J mol⁻¹ K⁻¹]', null, '["7.47 x 10⁵ N m⁻²","2.49 x 10⁶ N m⁻²","7.47 x 10⁶ N m⁻²","2.49 x 10⁵ N m⁻²"]', 2, 'P = nRT/V = (3 x 8.3 x 300)/10⁻³ = 7.47 x 10⁶ N m⁻².', true, '2026-10-12 19:15:53.654', '2026-10-12 19:15:53.654', null, null, null, 'The pressure of 3 moles of an ideal gas at a temperature of 27 °C having a volume of 10<sup>-3</sup> m<sup>3</sup> is [R = 8.3 J mol<sup>-1</sup> K<sup>-1</sup>]', '["7.47 x 10<sup>5</sup> N m<sup>-2</sup>","2.49 x 10<sup>6</sup> N m<sup>-2</sup>","7.47 x 10<sup>6</sup> N m<sup>-2</sup>","2.49 x 10<sup>5</sup> N m<sup>-2</sup>"]', 'P = nRT/V = (3 x 8.3 x 300)/10<sup>-3</sup> = 7.47 x 10<sup>6</sup> N m<sup>-2</sup>.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0a6carjbaseqyk8jioo55rte', 'General Mathematics', 'JAMB', null, 2020, null, 'If n(A - B) = 12, n(B - A) = 8, n(A ∪ B) = 25, find n(A ∩ B).', null, '["5","6","7","8"]', 0, 'n(A ∪ B) = n(A - B) + n(B - A) + n(A ∩ B) → 25 = 12 + 8 + x → x = 5.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If n(A - B) = 12, n(B - A) = 8, n(A ∪ B) = 25, find n(A ∩ B).', '["5","6","7","8"]', 'n(A ∩ B) = <u>5</u>.', '{"bold":[],"italic":[],"underline":["5"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0abk9q5v1xs7v0k4e9mt2ff9', 'Government', 'JAMB', null, 2020, null, 'The Lagos Treaty of May 28th 1975 led to the formation of the', null, '["African Economic Summit.","Lagos Plan of Action","Economic Community of West African States","Economic Commission for Africa"]', 2, 'The Lagos Treaty formed ECOWAS.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Lagos Treaty of May 28th 1975 led to the formation of the', '["African Economic Summit.","Lagos Plan of Action","<u>Economic Community of West African States</u>","Economic Commission for Africa"]', '<u>Economic Community of West African States</u>.', '{"bold":[],"italic":[],"underline":["Economic Community of West African States"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0ae4e65-b8ab-405a-bd68-46b3492b015e', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Paul told the Corinthians that if anyone has caused pain to the church, he should be...', null, '["removed from their midst","punished severely","forgiven and comforted","made to confess his sins"]', 2, '2 Corinthians 2:6-7 advises the church to forgive and comfort the penitent offender so he is not overwhelmed by excessive sorrow.', true, '2026-09-09 17:18:25.745', '2026-09-09 17:18:25.745', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0aoa86bo0ayq763qq9p0ba45', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The period of custody of a baby girl after her mother has been divorced lasts until she is', null, '["married","mature","10 years old","5 years old."]', 0, 'The period lasts until she is married.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The period of custody of a baby girl after her mother has been divorced lasts until she is', '["<u>married</u>","mature","10 years old","5 years old."]', '<u>Married</u>.', '{"bold":[],"italic":[],"underline":["married"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0avvu4oufa76fv06jbl7dimh', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Taking the ritual bath for Friday prayers is', null, '["wajib","sunnah","mustahab","mubah."]', 1, 'It is sunnah.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Taking the ritual bath for Friday prayers is', '["wajib","<u>sunnah</u>","mustahab","mubah."]', '<u>Sunnah</u>.', '{"bold":[],"italic":[],"underline":["sunnah"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0b2vphlgjw4hfsxceppva5q1', 'General Mathematics', 'WAEC', null, 2020, null, 'If 3^x = 5^y = 15^z, prove 1/x + 1/y = 1/z. Then find z if x = 2.', null, '["log₁₅3","ln3/ln15","ln5/ln15","2ln3/ln5"]', 1, '3^x = 15^z → x ln3 = z ln15 → z = x ln3/ln15.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If 3^x = 5^y = 15^z, prove 1/x + 1/y = 1/z. Then find z if x = 2.', '["log₁₅3","ln3/ln15","ln5/ln15","2ln3/ln5"]', 'z = <u>ln3/ln15</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0b5yv24skh7plv20dkz9sne5', 'General Mathematics', 'JAMB', null, 2020, null, 'If n(A × B) = 12 and n(A) = 3, what is the possible n(B)?', null, '["4","6","2","all"]', 0, 'n(A × B) = n(A) × n(B) → 12 = 3 × n(B) → n(B) = 4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If n(A × B) = 12 and n(A) = 3, what is the possible n(B)?', '["4","6","2","all"]', 'n(B) = <u>4</u>.', '{"bold":[],"italic":[],"underline":["4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0b749b2i0nengkgll3r249ef', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'King Josiah ordered Shaphan, the secretary to the house of the LORD not to account for the money given to repair the Temple because', null, '["he wanted to benefit from it","the people were honest","the money was too small","much money was collected."]', 1, 'The people were honest.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'King Josiah ordered Shaphan, the secretary to the house of the LORD not to account for the money given to repair the Temple because', '["he wanted to benefit from it","<u>the people were honest</u>","the money was too small","much money was collected."]', '<u>The people were honest</u>.', '{"bold":[],"italic":[],"underline":["the people were honest"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0b8yj38oj9jbnduil1v1ut27', 'Chemistry', 'JAMB', null, 1991, null, 'Which of the following gases will <b>rekindle a brightly glowing splint</b>?', null, '["NO2","NO","N2O","Cl2"]', 2, 'N2O supports combustion (rekindles glowing splint).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following gases will <b>rekindle a brightly glowing splint</b>?', '["NO2","NO","N2O","Cl2"]', '<u>N2O</u> rekindles a glowing splint.', '{"bold":["rekindle a brightly glowing splint"],"italic":[],"underline":["N2O"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0bjh1gvspqo6p5t0apqmujs7', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve x² - 5x + 6 < 0.', null, '["(2, 3)","[2, 3]","(-∞, 2) ∪ (3, ∞)","(-∞, 2] ∪ [3, ∞)"]', 0, '(x - 2)(x - 3) < 0 → 2 < x < 3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve x² - 5x + 6 < 0.', '["(2, 3)","[2, 3]","(-∞, 2) ∪ (3, ∞)","(-∞, 2] ∪ [3, ∞)"]', 'Solution: <u>2 < x < 3</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0bu350lx29qyml48ym47lk0h', 'Chemistry', 'JAMB', null, 2004, null, 'Alkanol + Alkanoic acid → Ester + Water. The reverse reaction of the equation above is known as', null, '["saponification","hydrolysis","fermentation","hydration"]', 1, 'Reverse of esterification is hydrolysis.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Alkanol + Alkanoic acid → Ester + Water. The reverse reaction of the equation above is known as', '["saponification","hydrolysis","fermentation","hydration"]', '<u>Hydrolysis</u>.', '{"bold":[],"italic":[],"underline":["hydrolysis"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0c02xfo3ym4lkd97suajlftv', 'Chemistry', 'JAMB', null, 1985, null, 'The number of atoms of chlorine present in 5.85g of NaCl is [Na=23, Cl=35.5, Avogadro''s Number = 6.02×10²³]', null, '["6.02×10²²","5.85×10²³","6.02×10²³","5.85×10²⁴"]', 2, 'Moles NaCl = 5.85/58.5 = 0.1; atoms Cl = 0.1 × 6.02×10²³ = 6.02×10²². Answer key says 6.02×10²³.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The number of atoms of chlorine present in 5.85g of NaCl is [Na=23, Cl=35.5, Avogadro''s Number = 6.02×10²³]', '["6.02×10²²","5.85×10²³","6.02×10²³","5.85×10²⁴"]', 'Moles NaCl = 0.1; atoms Cl = <u>6.02×10²²</u> (key says 6.02×10²³).', '{"bold":[],"italic":[],"underline":["6.02×10²³"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0cce727mmbs1b4a0qtj5s7b0', 'Biology', 'JAMB', null, 2000, null, 'In a group of male Agama lizards, the one brightest head colour is the', null, '["dominant","youngest","oldest","largest"]', 0, 'Brightest head colour = dominant male.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In a group of male Agama lizards, the one brightest head colour is the', '["dominant","youngest","oldest","largest"]', '<u>Brightest head colour = dominant male</u>.', '{"bold":[],"italic":[],"underline":["dominant"],"fillBlanks":[]}');
