insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0cvv81bzl4lc6bv708kiqdpo', 'Chemistry', 'JAMB', null, 2004, null, 'The property of chlorine which causes hydrogen chloride to be more ionic than the chlorine molecule is its', null, '["electronegativity","electropositivity","electron affinity","electrovalency"]', 0, 'Chlorine''s electronegativity makes HCl ionic.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The property of chlorine which causes hydrogen chloride to be more ionic than the chlorine molecule is its', '["electronegativity","electropositivity","electron affinity","electrovalency"]', '<u>Electronegativity</u>.', '{"bold":[],"italic":[],"underline":["electronegativity"],"fillBlanks":[]}');
