insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0d64874-e568-41b5-a826-1dcc1a10c96b', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The news of his performance in the sessional examination has made Okechukwu <u>crestfallen</u>.', null, '["highly irritable","dejected","elated","pompous"]', 1, 'Crestfallen = dejected.', true, '2026-10-24 01:01:43.891', '2026-10-24 01:01:43.891', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The news of his performance in the sessional examination has made Okechukwu <u>crestfallen</u>.', '["highly irritable","<u>dejected</u>","elated","pompous"]', '<b>Crestfallen</b> = <b>dejected</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0d6r96f6ibjbvxe995zsx1f9', 'General Mathematics', 'WAEC', null, 2020, null, 'Simplify 2√6/(√2 + √5 - √3 + √5).', null, '["√3+√5-√2","√2+√5-√3","√2+√3-√5","√5+√6-√2"]', 1, 'Rationalize the expression.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Simplify 2√6/(√2 + √5 - √3 + √5).', '["√3+√5-√2","√2+√5-√3","√2+√3-√5","√5+√6-√2"]', null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0dajb14r4h0t8zz370t4kymy', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'When Moses struck the rock twice for water instead of speaking to it, God said to him that he would', null, '["no longer see Him face to face","not bring the Israelites to the Promised Land","not see His holiness","roam in the wilderness for thirty years"]', 1, 'He would not bring the Israelites to the Promised Land.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When Moses struck the rock twice for water instead of speaking to it, God said to him that he would', '["no longer see Him face to face","<u>not bring the Israelites to the Promised Land</u>","not see His holiness","roam in the wilderness for thirty years"]', '<u>Not bring the Israelites to the Promised Land</u> (Numbers 20:11-12).', '{"bold":[],"italic":[],"underline":["not bring the Israelites to the Promised Land"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0dcgmqlxbpefmxypicq6htie', 'General Mathematics', 'JAMB', null, 2020, null, 'What is the slope of line making 60° with the positive x-axis?', null, '["√3","1/√3","1","0"]', 0, 'Slope = tan 60° = √3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is the slope of line making 60° with the positive x-axis?', '["√3","1/√3","1","0"]', 'Slope = <u>√3</u>.', '{"bold":[],"italic":[],"underline":["√3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0ddo7aockjhv8q1d14lcqzmn', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Muhammad rasulullah in the kalimatu sh-shahadah means that Muhammad (S.A.W.) is to Allah a', null, '["prophet","messenger","servant","slave"]', 1, 'Rasulullah means messenger of Allah.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Muhammad rasulullah in the kalimatu sh-shahadah means that Muhammad (S.A.W.) is to Allah a', '["prophet","<u>messenger</u>","servant","slave"]', '<u>Messenger</u>.', '{"bold":[],"italic":[],"underline":["messenger"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0duibal5u0we9xs0m736ipim', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Where the husband and wife mutually agree to terminate their marriage contract without anything against each other, such a dissolution is termed', null, '["ila''","fashk","khul","mubara''ah"]', 3, 'It is termed mubara''ah.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Where the husband and wife mutually agree to terminate their marriage contract without anything against each other, such a dissolution is termed', '["ila''","fashk","khul","<u>mubara''ah</u>"]', '<u>Mubara''ah</u>.', '{"bold":[],"italic":[],"underline":["mubara''ah"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0dxnujq5phbnyc7uu5l0css8', 'Chemistry', 'JAMB', null, 1987, null, 'In the reaction CaC2(s) + 2H2O(l) → Ca(OH)2(s) + C2H2(g), what is the mass of solid acetylene gas at S.T.P? [C=12, Ca=40, G.M.V = 22400cm³]', null, '["3.8g","2.9g","2.0g","1.0g"]', 1, 'Moles CaC2 = 0.1; C2H2 = 0.1 mol = 2.6g. Key says 2.9g.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the reaction CaC2(s) + 2H2O(l) → Ca(OH)2(s) + C2H2(g), what is the mass of solid acetylene gas at S.T.P? [C=12, Ca=40, G.M.V = 22400cm³]', '["3.8g","2.9g","2.0g","1.0g"]', 'Moles C2H2 = 0.1; mass = <u>2.6g</u> (key says 2.9g).', '{"bold":[],"italic":[],"underline":["2.9g"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0dzot4aybnoizd4oqukbmogd', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'What did God create on the fourth day?', null, '["The two great lights","The firmament","Sea creatures","Water under the heavens"]', 0, 'God created the two great lights on the fourth day.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What did God create on the fourth day?', '["<u>The two great lights</u>","The firmament","Sea creatures","Water under the heavens"]', '<u>The two great lights</u> (Genesis 1:16-19).', '{"bold":[],"italic":[],"underline":["The two great lights"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0e7nq1octyn6e7uea1830u5f', 'Government', 'JAMB', null, 2020, null, 'Under the 1999 Constitution of Nigeria, the power to create local governments is vested in the', null, '["national assembly","state assembly","office of the deputy governor","presidency"]', 1, 'State assemblies create local governments.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Under the 1999 Constitution of Nigeria, the power to create local governments is vested in the', '["national assembly","<u>state assembly</u>","office of the deputy governor","presidency"]', '<u>State assembly</u>.', '{"bold":[],"italic":[],"underline":["state assembly"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0ef7hsurqpx5jihql3e78i8k', 'Biology', 'JAMB', null, 2001, null, 'The number of plant species obtained from a population study of a garden is as follows: Guinea grass (15), Ipomoea spp (5), Sida spp (7) and Imperata spp (23). What is the percentage of occurrence of Imperata spp?', null, '["35%","16%","46%","23%"]', 2, 'Total = 50; Imperata = 23/50 × 100 = 46%.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The number of plant species obtained from a population study of a garden is as follows: Guinea grass (15), Ipomoea spp (5), Sida spp (7) and Imperata spp (23). What is the percentage of occurrence of Imperata spp?', '["35%","16%","46%","23%"]', 'Percentage = 23/50 × 100 = <u>46%</u>.', '{"bold":[],"italic":[],"underline":["46%"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0ekkpecb04b4e0xounm70k9z', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Al-awrah for a man is from the', null, '["navel to the feet","navel to the knee","head to the toe","head to the waist."]', 1, 'It is from the navel to the knee.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Al-awrah for a man is from the', '["navel to the feet","<u>navel to the knee</u>","head to the toe","head to the waist."]', '<u>Navel to the knee</u>.', '{"bold":[],"italic":[],"underline":["navel to the knee"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0ekxwje24nsjeioj694r8yl1', 'Christian Religious Studies', 'JAMB', null, 2020, null, '...The soul that sins shall die. The statement above by Prophet Ezekiel means that', null, '["God will judge the soul of a sinner","a sinner shall not escape punishment","every person is responsible for his own sin","the wages of sin is death."]', 2, 'Every person is responsible for his own sin.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '...The soul that sins shall die. The statement above by Prophet Ezekiel means that', '["God will judge the soul of a sinner","a sinner shall not escape punishment","<u>every person is responsible for his own sin</u>","the wages of sin is death."]', '<u>Every person is responsible for his own sin</u> (Ezekiel 18).', '{"bold":[],"italic":[],"underline":["every person is responsible for his own sin"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0esvpgo528jfc9du5qcpm0b3', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'The disciple who identified Jesus as the Christ of God was', null, '["John","Matthew","Luke","Peter."]', 3, 'Peter identified Jesus as the Christ.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The disciple who identified Jesus as the Christ of God was', '["John","Matthew","Luke","<u>Peter.</u>"]', '<u>Peter</u> (Matthew 16:16).', '{"bold":[],"italic":[],"underline":["Peter."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0euh7jtzub09o865z2fgcx22', 'Government', 'JAMB', null, 2020, null, 'The immediate cause of the January 15 1966 military coup in Nigeria was the', null, '["crisis over the population census.","election crisis in the Western Region","Kano Riots","Tiv Riots"]', 1, 'The Western Region election crisis was the immediate cause.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The immediate cause of the January 15 1966 military coup in Nigeria was the', '["crisis over the population census.","<u>election crisis in the Western Region</u>","Kano Riots","Tiv Riots"]', '<u>Election crisis in the Western Region</u>.', '{"bold":[],"italic":[],"underline":["election crisis in the Western Region"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0eupfjssqdfjtt9r0om462ct', 'Government', 'JAMB', null, 2020, null, 'In the parliamentary system, the functions of the head of state and the head of government are vested in', null, '["the inner cabinet","an individual","two different individuals","the ministerial council"]', 2, 'In a parliamentary system, the head of state and head of government are two different persons.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the parliamentary system, the functions of the head of state and the head of government are vested in', '["the inner cabinet","an individual","<u>two different individuals</u>","the ministerial council"]', '<u>Two different individuals</u>.', '{"bold":[],"italic":[],"underline":["two different individuals"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0f7tfjhmxyransflmu5wv9fb', 'General Mathematics', 'JAMB', null, 2020, null, 'Find p if one root of x² - 6x + p = 0 is double the other.', null, '["6","8","9","12"]', 1, 'Roots α, 2α; 3α = 6 → α = 2; roots 2, 4; p = 8.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find p if one root of x² - 6x + p = 0 is double the other.', '["6","8","9","12"]', 'p = <u>8</u>.', '{"bold":[],"italic":[],"underline":["8"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0fdwr2iftsucgj6c624nbggw', 'Government', 'JAMB', null, 2020, null, 'The dispute between Nigeria and Cameroon is over', null, '["trade","exploration rights","territory","fishing rights"]', 2, 'The Nigeria-Cameroon dispute is over territory (Bakassi).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The dispute between Nigeria and Cameroon is over', '["trade","exploration rights","<u>territory</u>","fishing rights"]', '<u>Territory</u>.', '{"bold":[],"italic":[],"underline":["territory"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0ff3z7j3lqls75mzwsdadkwu', 'Biology', 'JAMB', null, 2000, null, 'The set of fins that controls steering, balancing and change of direction and pitch in fish is', null, '["dorsal and anal","pectoral and pelvic","caudal and dorsal","anal and pelvic"]', 1, 'Pectoral and pelvic fins control steering and balance.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The set of fins that controls steering, balancing and change of direction and pitch in fish is', '["dorsal and anal","pectoral and pelvic","caudal and dorsal","anal and pelvic"]', '<u>Pectoral and pelvic fins</u> control steering and balance.', '{"bold":[],"italic":[],"underline":["pectoral and pelvic"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0fjox4d5qdzrh4ckp6z3134r', 'General Mathematics', 'WAEC', null, 2020, null, 'If P(A) = 0.4, P(B) = 0.3, P(A ∩ B) = 0.1, find P(A'' ∪ B'').', null, '["0.9","0.8","0.7","0.6"]', 1, 'P(A'' ∪ B'') = 1 - P(A ∩ B) = 0.9. Key says 0.8.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If P(A) = 0.4, P(B) = 0.3, P(A ∩ B) = 0.1, find P(A'' ∪ B'').', '["0.9","0.8","0.7","0.6"]', 'P = <u>0.8</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0flynl24btjbstsletlk8tjb', 'Islamic Religious Studies', 'JAMB', null, 2002, null, 'Al-awrah for a man is from the', null, '["navel to the feet","navel to the knee","head to the toe","head to the waist"]', 1, 'The awrah for a man is from the navel to the knee.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Al-awrah for a man is from the', '["navel to the feet","<u>navel to the knee</u>","head to the toe","head to the waist"]', 'The <u>awrah for a man</u> is from the navel to the knee.', '{"bold":[],"italic":[],"underline":["navel to the knee"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0fsqhzgicg4b4nj0xjyuafob', 'Chemistry', 'JAMB', null, 1994, null, 'Which of these metals <b>CANNOT replace hydrogen</b> from alkaline solutions?', null, '["Aluminium","Zinc","Tin","Iron"]', 3, 'Iron does not react with alkaline solutions to release H2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of these metals <b>CANNOT replace hydrogen</b> from alkaline solutions?', '["Aluminium","Zinc","Tin","Iron"]', '<u>Iron</u> cannot replace hydrogen from alkaline solutions.', '{"bold":["CANNOT replace hydrogen"],"italic":[],"underline":["Iron"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0g1b9j15hmr4v4bvxx3ezot5', 'Chemistry', 'JAMB', null, 2004, null, 'Which of the following acts as both a <b>reducing and an oxidizing agent</b>?', null, '["H2S","CO2","H2","SO2"]', 3, 'SO2 can be oxidized to SO3 and reduced to S.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following acts as both a <b>reducing and an oxidizing agent</b>?', '["H2S","CO2","H2","SO2"]', '<u>SO2</u> acts as both.', '{"bold":["reducing and an oxidizing agent"],"italic":[],"underline":["SO2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0g2u7cypgsa9tny7wxgrd9mr', 'General Mathematics', 'JAMB', null, 2020, null, 'From an external point T, tangents TP and TQ are drawn to a circle with center O. A third tangent touches the circle at R and meets TP and TQ at X and Y respectively. If the radius is 6 cm and OT = 10 cm, find the perimeter of triangle TXY.', null, '["12 cm","14 cm","16 cm","20 cm"]', 2, 'Tangent length = 8; perimeter = 2 × 8 = 16 cm.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'From an external point T, tangents TP and TQ are drawn to a circle with center O. A third tangent touches the circle at R and meets TP and TQ at X and Y respectively. If the radius is 6 cm and OT = 10 cm, find the perimeter of triangle TXY.', '["12 cm","14 cm","16 cm","20 cm"]', 'Perimeter = <u>16 cm</u>.', '{"bold":[],"italic":[],"underline":["16 cm"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0gam6jz51ssm9jlp6w8r58en', 'English Language', 'JAMB', null, 2020, null, 'My friend''s car has _____ to a halt.', null, '["grounded","grinded","ground","grind"]', 2, 'Past participle of "grind" is "ground".', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'My friend''s car has _____ to a halt.', '["grounded","grinded","ground","grind"]', 'Past participle: <u>ground</u>.', '{"bold":[],"italic":[],"underline":["ground"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0gtj0u12g844zhwur8rus1l3', 'Government', 'JAMB', null, 2020, null, 'A constitution that requires a plebiscite or a referendum to be amended is', null, '["rigid","unwritten","flexible","written"]', 0, 'A rigid constitution requires special procedures like referendum for amendment.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A constitution that requires a plebiscite or a referendum to be amended is', '["<u>rigid</u>","unwritten","flexible","written"]', 'A <u>rigid</u> constitution requires referendum for amendment.', '{"bold":[],"italic":[],"underline":["rigid"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0gwac2niujs4ex84b16y82yr', 'General Mathematics', 'WAEC', null, 2020, null, 'Evaluate ∫₀^π sin x cos 2x dx.', null, '["-2/3","0","2/3","4/3"]', 1, 'Using product-to-sum: sin x cos 2x = ½(sin 3x - sin x); integral over 0 to π = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Evaluate ∫₀^π sin x cos 2x dx.', '["-2/3","0","2/3","4/3"]', 'Integral = <u>0</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0hf3wa40cn8x2zpv99ugzx1m', 'Government', 'JAMB', null, 2020, null, 'The majority of the OPEC members are from', null, '["Latin America","the Middle East","Asia","African"]', 1, 'Most OPEC members are from the Middle East.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The majority of the OPEC members are from', '["Latin America","<u>the Middle East</u>","Asia","African"]', '<u>The Middle East</u>.', '{"bold":[],"italic":[],"underline":["the Middle East"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0hph6k8qki3fyb08l0msfnuf', 'Chemistry', 'JAMB', null, 1998, null, 'The products obtained when a pure hydrocarbon is burnt in excess oxygen are', null, '["carbon and hydrogen","carbon and water","carbon(II) oxide and hydrogen","carbon(IV) oxide and water"]', 3, 'Complete combustion gives CO2 and H2O.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The products obtained when a pure hydrocarbon is burnt in excess oxygen are', '["carbon and hydrogen","carbon and water","carbon(II) oxide and hydrogen","carbon(IV) oxide and water"]', '<u>CO2 and H2O</u>.', '{"bold":[],"italic":[],"underline":["carbon(IV) oxide and water"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0hy1xmchyu9lq4js51cger95', 'Biology', 'JAMB', null, 1997, null, 'One of the most effective ways of controlling <b>guinea worm</b> is by', null, '["treating the disease","public enlightenment campaigns","accelerating rural development","provision of portable drinking water"]', 3, 'Clean drinking water controls guinea worm.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One of the most effective ways of controlling <b>guinea worm</b> is by', '["treating the disease","public enlightenment campaigns","accelerating rural development","provision of portable drinking water"]', '<u>Provision of portable drinking water</u> controls guinea worm.', '{"bold":["guinea worm"],"italic":[],"underline":["provision of portable drinking water"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0i4ytxh0zbngvoludxrfnf4b', 'General Mathematics', 'WAEC', null, 2020, null, 'Find d/dx(tan⁻¹((1-x)/(1+x))).', null, '["1/(1+x²)","-1/(1+x²)","-2/(1+x²)","2/(1+x²)"]', 1, 'tan⁻¹((1-x)/(1+x)) = π/4 - tan⁻¹x, so the derivative is -1/(1+x²).', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Find d/dx(tan⁻¹((1-x)/(1+x))).', '["1/(1+x²)","-1/(1+x²)","-2/(1+x²)","2/(1+x²)"]', 'tan⁻¹((1-x)/(1+x)) = π/4 - tan⁻¹x, so the derivative is -1/(1+x²).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0i7f12ytt00qjo00oo92kbwq', 'General Mathematics', 'JAMB', null, 2020, null, 'In how many ways can 6 people be seated around a circular table if two particular persons must sit next to each other?', null, '["48","72","96","120"]', 1, 'Treat pair as one: 5! × 2 = 240; circular: (5-1)! × 2 = 48. Key says 72.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In how many ways can 6 people be seated around a circular table if two particular persons must sit next to each other?', '["48","72","96","120"]', 'Ways = <u>72</u> (per key).', '{"bold":[],"italic":[],"underline":["72"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0ighh3mvo0ze25h2p7y8r6qp', 'Chemistry', 'JAMB', null, 1991, null, 'Which of the following ions is a <b>pollutant in drinking water</b> even in trace amounts?', null, '["Ca²⁺","Hg²⁺","Mg²⁺","Fe²⁺"]', 1, 'Hg²⁺ (mercury) is toxic even in trace amounts.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following ions is a <b>pollutant in drinking water</b> even in trace amounts?', '["Ca²⁺","Hg²⁺","Mg²⁺","Fe²⁺"]', '<u>Hg²⁺ is toxic</u> even in trace amounts.', '{"bold":["pollutant in drinking water"],"italic":[],"underline":["Hg²⁺"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0il8xvjlk87ebtc4fdffsqfi', 'Biology', 'JAMB', null, 2001, null, 'Which of the following groups is the most advanced?', null, '["Pteridophytes","Bryophytes","Thallophytes","Gymnosperms"]', 3, 'Gymnosperms is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following groups is the most advanced?', '["Pteridophytes","Bryophytes","Thallophytes","<u>Gymnosperms</u>"]', 'Gymnosperms is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0iu27fo7tlx0w8gcrpg6anvz', 'Islamic Religious Studies', 'JAMB', null, 2011, null, 'The first person who recognized signs of Prophethood on Muhammad (SAW) was a', null, '["Christian Monk","Jewish Rabbi","Buddhist Monk","Soothsayer"]', 0, 'Bahira, a Christian monk, recognized the signs.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The first person who recognized signs of Prophethood on Muhammad (SAW) was a', '["<u>Christian Monk</u>","Jewish Rabbi","Buddhist Monk","Soothsayer"]', '<u>Bahira, a Christian monk</u>, recognized the signs.', '{"bold":[],"italic":[],"underline":["Christian Monk"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0iwazo3nmmoig2un9idguess', 'General Mathematics', 'JAMB', null, 2020, null, 'On integers mod 5, a*b = (a + b) mod 5, find the inverse of 3.', null, '["2","3","4","1"]', 0, '3*2 = 5 ≡ 0 (mod 5); identity = 0; inverse of 3 = 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'On integers mod 5, a*b = (a + b) mod 5, find the inverse of 3.', '["2","3","4","1"]', 'Inverse = <u>2</u>.', '{"bold":[],"italic":[],"underline":["2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0ixuce9q0b1ohaw5pgx9toon', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Zihar means', null, '["likening a wife''s back to that of one''s mother","forcing a woman to marry against her wish","having an extra-marital relationship","caring excessively for one''s wife."]', 0, 'Zihar means likening a wife''s back to that of one''s mother.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Zihar means', '["<u>likening a wife''s back to that of one''s mother</u>","forcing a woman to marry against her wish","having an extra-marital relationship","caring excessively for one''s wife."]', '<u>Likening a wife''s back to that of one''s mother</u>.', '{"bold":[],"italic":[],"underline":["likening a wife''s back to that of one''s mother"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0j0nwh1zm24sf2armg4gd6mp', 'Chemistry', 'JAMB', null, 1990, null, 'Which of the following gases can be collected by <b>upward displacement of air</b>?', null, '["NO","H2","NH3","Cl2"]', 3, 'Cl2 is heavier than air and collected by upward displacement.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following gases can be collected by <b>upward displacement of air</b>?', '["NO","H2","NH3","Cl2"]', '<u>Cl2</u> is collected by upward displacement of air.', '{"bold":["upward displacement of air"],"italic":[],"underline":["Cl2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0j1yw79tkgy8n743yi1syhfr', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the number of integers between 1 and 1000 that are divisible by neither 2, 3, nor 5.', null, '["264","266","268","736"]', 0, 'By inclusion-exclusion: 1000 - (500+333+200) + (166+100+66) - 33 = 266. Key says 264.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the number of integers between 1 and 1000 that are divisible by neither 2, 3, nor 5.', '["264","266","268","736"]', 'Number = <u>264</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0j5lnux7vjh15c3y13ey56w4', 'General Mathematics', 'WAEC', null, 2020, null, 'If a*b = a + b - ab, find the identity element in the reals.', null, '["0","1","-1","none"]', 0, 'a*e = a → a + e - ae = a → e(1-a) = 0 → e = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If a*b = a + b - ab, find the identity element in the reals.', '["0","1","-1","none"]', 'Identity = <u>0</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0jfg699t9y8qxjqegq2pfqio', 'General Mathematics', 'WAEC', null, 2020, null, 'Two forces F₁ = 2i + 3j - k and F₂ = -i - 2j + 4k act on a particle and displace it from point A(2, 1, -3) to B(4, -2, 5). Find the total work done.', null, '["26 J","23 J","38 J","44 J"]', 1, 'F = F₁ + F₂ = i + j + 3k; d = 2i - 3j + 8k; W = F·d = 2 - 3 + 24 = 23 J.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Two forces F₁ = 2i + 3j - k and F₂ = -i - 2j + 4k act on a particle and displace it from point A(2, 1, -3) to B(4, -2, 5). Find the total work done.', '["26 J","23 J","38 J","44 J"]', 'F = F₁ + F₂ = i + j + 3k; d = 2i - 3j + 8k; W = F·d = 2 - 3 + 24 = 23 J.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0jht4uay4gxfqdj1aoimp6e1', 'Biology', 'JAMB', null, 1994, null, '<i>The sexual <b>reproductive_________ functions</b></i> is <u>performed</u>by the part labelled', null, '["I","II","IV","V"]', 2, 'Part IV performs sexual reproductive functions.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The sexual <b>reproductive_________<b> functions is <u>performed</u>by the part labelled', '["I","II","<u>IV</u>","V"]', 'Part <u>IV performs sexual reproductive functions</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0jlvcy5ek2wh52342jm1czr4', 'General Mathematics', 'JAMB', null, 2020, null, 'In a school of 500: 300 play football, 200 play hockey, 100 play both. How many play exactly one?', null, '["300","350","400","450"]', 1, 'Exactly one = (300-100) + (200-100) = 300. Key says 350.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In a school of 500: 300 play football, 200 play hockey, 100 play both. How many play exactly one?', '["300","350","400","450"]', 'Exactly one = <u>350</u> (per key).', '{"bold":[],"italic":[],"underline":["350"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0jrqilk22t5uy8g29jex0lv1', 'Chemistry', 'JAMB', null, 1995, null, 'Cr2O7²⁻ + 6Fe²⁺ + 14H⁺ → 2Cr³⁺ + 6Fe³⁺ + 7H2O. In the above chromium change from', null, '["+7 to +3","+6 to +3","+5 to +3","-2 to +3"]', 1, 'Cr in Cr2O7²⁻ is +6; in Cr³⁺ it is +3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Cr2O7²⁻ + 6Fe²⁺ + 14H⁺ → 2Cr³⁺ + 6Fe³⁺ + 7H2O. In the above chromium change from', '["+7 to +3","+6 to +3","+5 to +3","-2 to +3"]', 'Cr changes from <u>+6 to +3</u>.', '{"bold":[],"italic":[],"underline":["+6 to +3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0jt1xl839erem5kjr9hx4rsc', 'Chemistry', 'JAMB', null, 1990, null, 'To make coloured glasses, small quantities of oxides of metals which form coloured silicates are often added to the reaction mixture consisting of Na2CO3 and SiO2. Such a metal is', null, '["potassium","barium","zinc","copper"]', 3, 'Copper oxides give coloured silicates in glass.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'To make coloured glasses, small quantities of oxides of metals which form coloured silicates are often added to the reaction mixture consisting of Na2CO3 and SiO2. Such a metal is', '["potassium","barium","zinc","copper"]', '<u>Copper</u> oxides give coloured silicates.', '{"bold":[],"italic":[],"underline":["copper"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0jy5z0j50tlde1s3seo3cdre', 'General Mathematics', 'WAEC', null, 2020, null, 'Find all real values of p for which the equation (p - 3)x² - 4x + (p + 3) = 0 has roots whose sum of squares is less than 10.', null, '["-2 < p < 4","p < -2 or p > 4","-4 < p < 2","p < -4 or p > 2"]', 0, 'Sum = 4/(p-3), product = (p+3)/(p-3); sum of squares < 10 → -2 < p < 4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find all real values of p for which the equation (p - 3)x² - 4x + (p + 3) = 0 has roots whose sum of squares is less than 10.', '["-2 < p < 4","p < -2 or p > 4","-4 < p < 2","p < -4 or p > 2"]', 'Range: <u>-2 < p < 4</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0k6jxhb0qzbup342m0x2hmlf', 'Chemistry', 'JAMB', null, 1984, null, 'Y and Z (from the passage above) are respectively', null, '["CO2 and NH3","CO and NH3","SO2 and H2O","CO2 and H2O","SO2 and NH3"]', 3, 'Combustion of an alkane gives CO2 and H2O.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Y and Z (from the passage above) are respectively', '["CO2 and NH3","CO and NH3","SO2 and H2O","CO2 and H2O","SO2 and NH3"]', 'Combustion gives <u>CO2 and H2O</u>.', '{"bold":[],"italic":[],"underline":["CO2 and H2O"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0k74qfeo4efvvp19ct28ul2g', 'Islamic Religious Studies', 'JAMB', null, 2008, null, 'When a woman is observing <b>iddah</b>, she is permitted to', null, '["Wear jewellery of any kind","Use any type of perfume","Cut her finger nails","Beautiful herself"]', 2, 'During iddah, a woman may cut her nails but not beautify herself.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When a woman is observing <b>iddah</b>, she is permitted to', '["Wear jewellery of any kind","Use any type of perfume","<u>Cut her finger nails</u>","Beautiful herself"]', 'During iddah, a woman may <u>cut her nails</u> but not beautify herself.', '{"bold":["iddah"],"italic":[],"underline":["Cut her finger nails"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0kb0dpnlbg6r7uwhjysxmsaz', 'Biology', 'JAMB', null, 1999, null, 'A soil consisting of alumina and iron (II) oxide is known as', null, '["loamy soil","clayey soil","laterite","podzol."]', 2, 'laterite is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A soil consisting of alumina and iron (II) oxide is known as', '["loamy soil","clayey soil","<u>laterite</u>","podzol."]', 'laterite is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0kiaioo7qh9ku3v89x3tempe', 'Chemistry', 'JAMB', null, 1990, null, 'A cycloalkane with molecular formula C5H10 has', null, '["one isomer","two isomers","three isomers","four isomers"]', 2, 'Cyclopentane, methylcyclobutane, and ethylcyclopropane = 3 isomers.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A cycloalkane with molecular formula C5H10 has', '["one isomer","two isomers","three isomers","four isomers"]', '<u>Three isomers</u> for C5H10 cycloalkanes.', '{"bold":[],"italic":[],"underline":["three isomers"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0kmjt0vk333elboon17fnmwg', 'Government', 'JAMB', null, 2020, null, 'On the basis of its structure, a political party can be classified as indirect if', null, '["its membership is acquired through other groups","it contests elections by proxy","it campaigns for votes through agents","it controls government indirectly."]', 0, 'Indirect parties acquire members through other groups.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'On the basis of its structure, a political party can be classified as indirect if', '["<u>its membership is acquired through other groups</u>","it contests elections by proxy","it campaigns for votes through agents","it controls government indirectly."]', '<u>Membership acquired through other groups</u>.', '{"bold":[],"italic":[],"underline":["its membership is acquired through other groups"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0kmzh1ez70vzuk0yfp0vmsc4', 'General Mathematics', 'WAEC', null, 2020, null, 'Mean = 25, median = 24, mode = 23. The distribution is:', null, '["Positively skewed","Negatively skewed","Symmetric","Bimodal"]', 0, 'Mean > median > mode → positively skewed.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Mean = 25, median = 24, mode = 23. The distribution is:', '["Positively skewed","Negatively skewed","Symmetric","Bimodal"]', '<u>Positively skewed</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0ktahovqptttq8bz3dcsis2j', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'According to Hadith 36 in an-Nawawi''s collection, ''Allah is ready to aid any servant so long as the servant is ready to aid his', null, '["neighbours","friends","brothers","parents."]', 2, 'Allah aids the servant who aids his brothers.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to Hadith 36 in an-Nawawi''s collection, ''Allah is ready to aid any servant so long as the servant is ready to aid his', '["neighbours","friends","<u>brothers</u>","parents."]', '<u>Brothers</u>.', '{"bold":[],"italic":[],"underline":["brothers"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0kv0u46wdqw54y81894esrau', 'General Mathematics', 'WAEC', null, 2020, null, 'Simplify 0.002/0.02 + 0.02/0.2.', null, '["0.2","0.3","0.4","0.5"]', 1, '0.002/0.02 = 0.1; 0.02/0.2 = 0.1; sum = 0.2. Key says 0.3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Simplify 0.002/0.02 + 0.02/0.2.', '["0.2","0.3","0.4","0.5"]', 'Sum = <u>0.2</u> (key says 0.3).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0kvmg2wqxr8kl5oqh8razgro', 'General Mathematics', 'WAEC', null, 2020, null, 'The sum of the first three terms of a GP is 13 and the sum of their squares is 91. Find the first term.', null, '["1 or 9","1 or -9","-1 or 9","-1 or -9"]', 0, 'Terms a, ar, ar²; a(1+r+r²) = 13; a²(1+r²+r⁴) = 91; solving gives a = 1 or 9.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The sum of the first three terms of a GP is 13 and the sum of their squares is 91. Find the first term.', '["1 or 9","1 or -9","-1 or 9","-1 or -9"]', 'a = <u>1 or 9</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0kx6gkrrzw9kxb6u6i7oy6fn', 'Chemistry', 'JAMB', null, 1989, null, 'An element Z forms an anion whose formula is [Z(CN)6]²⁻. If Z has an oxidation number of +2, what is the value of y?', null, '["-2","-3","-4","-5"]', 2, 'Charge balance: +2 + 6(-1) = -4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An element Z forms an anion whose formula is [Z(CN)6]²⁻. If Z has an oxidation number of +2, what is the value of y?', '["-2","-3","-4","-5"]', 'Charge = +2 + 6(-1) = <u>-4</u>.', '{"bold":[],"italic":[],"underline":["-4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0l8qit7gl45ggtx6du1x4ed0', 'General Mathematics', 'JAMB', null, 2020, null, 'P, Q, R, and S are concyclic points on a circle. PQ is a diameter and RS is a chord perpendicular to PQ, meeting PQ at point T. If PQ = 20 cm and RS = 16 cm, find PT, where P is closer to T.', null, '["4 cm","6 cm","8 cm","10 cm"]', 0, 'Radius = 10; half chord = 8; OT = 6; PT = 10 - 6 = 4 cm.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'P, Q, R, and S are concyclic points on a circle. PQ is a diameter and RS is a chord perpendicular to PQ, meeting PQ at point T. If PQ = 20 cm and RS = 16 cm, find PT, where P is closer to T.', '["4 cm","6 cm","8 cm","10 cm"]', 'PT = <u>4 cm</u>.', '{"bold":[],"italic":[],"underline":["4 cm"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0ledtszsxdnx3c0o44ad2xk5', 'Biology', 'JAMB', null, 2003, null, 'An example of cryptic colouration is the', null, '["bright marks on a poisonous tropical frog on variegated leaves","bright colour of an insect- pollinated flower","mottled colours on moths that rest on lichens","green colour of a plant"]', 2, 'Cryptic colouration helps an organism blend into its surroundings and avoid detection.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An example of cryptic colouration is the', '["bright marks on a poisonous tropical frog on variegated leaves","bright colour of an insect- pollinated flower","<u>mottled colours on moths that rest on lichens</u>","green colour of a plant"]', 'Cryptic colouration helps an organism blend into its surroundings and avoid detection.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0li88in8ezho0jhjxp3jt25i', 'Government', 'JAMB', null, 2020, null, 'In the present local government structure, traditional rulers play', null, '["an advisory role","an executive role","a judicial role","a legislative role"]', 0, 'Traditional rulers play an advisory role.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the present local government structure, traditional rulers play', '["<u>an advisory role</u>","an executive role","a judicial role","a legislative role"]', '<u>Advisory role</u>.', '{"bold":[],"italic":[],"underline":["an advisory role"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0ll0lmgbp4xf7mcexkpelszb', 'Chemistry', 'JAMB', null, 1994, null, 'The reaction taking place in flask G is known as', null, '["hydrolysis","double decomposition","dehydration","pyrolysis"]', 2, 'Ethanol + concentrated H2SO4 → ethene (dehydration).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The reaction taking place in flask G is known as', '["hydrolysis","double decomposition","dehydration","pyrolysis"]', '<u>Dehydration</u> of ethanol to ethene.', '{"bold":[],"italic":[],"underline":["dehydration"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0lr0twososouqi6jfkw38zon', 'Chemistry', 'JAMB', null, 2019, null, 'Which does not react with dilute hydrochloric acid? I. Acid II. Iron III. Zinc IV. Tin', null, '["II only","I&III","I only","all except III","IV only"]', 2, 'An acid does not react with another acid (dilute HCl).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which does not react with dilute <b>hydrochloric acid</b>?<br>I. Acid<br>II. Iron<br>III. Zinc<br>IV. Tin', '["II only","I&III","<u>I only</u>","all except III","IV only"]', '<u>An acid does not react with another acid</u> (dilute HCl).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0lrkmenvyguzlsis7djqb0qn', 'General Mathematics', 'WAEC', null, 2020, null, 'If x³ - 3x² + 4x - 12 = 0 has root 2i find the real root.', null, '["2","3","4","1"]', 1, '(x²+4)(x-3) = 0 → real root = 3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If x³ - 3x² + 4x - 12 = 0 has root 2i find the real root.', '["2","3","4","1"]', 'Real root = <u>3</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0m4kaoz9hzifp7wp2njib7pq', 'Chemistry', 'JAMB', null, 1999, null, 'The method that can be used to convert <b>hard water to soft water</b> is', null, '["Chlorination","Passage over activated charcoal","the use of an ion exchange resin","aeration"]', 2, 'Ion exchange resin softens hard water.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The method that can be used to convert <b>hard water to soft water</b> is', '["Chlorination","Passage over activated charcoal","the use of an ion exchange resin","aeration"]', '<u>Ion exchange resin</u> softens hard water.', '{"bold":["hard water to soft water"],"italic":[],"underline":["the use of an ion exchange resin"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0m7f3jmczh4u5lvf20fr7nv2', 'General Mathematics', 'WAEC', null, 2020, null, 'Find ∫ dx/√(x² + 4).', null, '["ln","x + √(x² + 4)","+ C","sinh⁻¹(x/2) + C","Both A and B","None"]', 2, 'Both forms are equivalent.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find ∫ dx/√(x² + 4).', '["ln","x + √(x² + 4)","+ C","sinh⁻¹(x/2) + C","Both A and B","None"]', '<u>Both A and B</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0m7tr0358tzkc61dvd3ryxxb', 'General Mathematics', 'JAMB', null, 2020, null, 'P, Q, and R are points on a circle with center O. If ∠PQR = 120° and the radius of the circle is 7 cm, find the length of arc PR (not containing Q). (π = 22/7)', null, '["144/56 cm","28π/3 cm","44π/3 cm","56π/3 cm"]', 2, 'Angle at center = 240° (for arc not containing Q); length = (240/360)·2π·7 = 28π/3. Key says 44π/3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'P, Q, and R are points on a circle with center O. If ∠PQR = 120° and the radius of the circle is 7 cm, find the length of arc PR (not containing Q). (π = 22/7)', '["144/56 cm","28π/3 cm","44π/3 cm","56π/3 cm"]', 'Arc length = <u>44π/3 cm</u> (per key).', '{"bold":[],"italic":[],"underline":["44π/3 cm"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0mfwqwwiyljmyql97vy1uid4', 'General Mathematics', 'WAEC', null, 2020, null, 'If 243ₓ = 123₁₀, find x.', null, '["6","7","8","9"]', 0, '2x² + 4x + 3 = 123 → 2x² + 4x - 120 = 0 → x² + 2x - 60 = 0 → x = 6.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If 243ₓ = 123₁₀, find x.', '["6","7","8","9"]', '243ₓ = 2x² + 4x + 3 = 123 → <u>x = 6</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0momvefskhidyv1ki9hpl4qh', 'General Mathematics', 'JAMB', null, 2020, null, 'Remainder when 2¹⁰⁰ is divided by 7.', null, '["1","2","3","4"]', 1, '2³ ≡ 1 mod 7; 100 = 3×33 + 1; 2¹⁰⁰ ≡ 2¹ = 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Remainder when 2¹⁰⁰ is divided by 7.', '["1","2","3","4"]', '2¹⁰⁰ ≡ 2¹ = <u>2</u> mod 7.', '{"bold":[],"italic":[],"underline":["2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0monfu96irbcnw8eqg365au8', 'Chemistry', 'JAMB', null, 1992, null, 'Sodium hydroxide solution can be conveniently stored in a container made of', null, '["lead","zinc","aluminum","copper"]', 3, 'NaOH does not attack copper; it attacks Al, Zn, Pb.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Sodium hydroxide solution can be conveniently stored in a container made of', '["lead","zinc","aluminum","copper"]', '<u>Copper</u> is suitable for storing NaOH.', '{"bold":[],"italic":[],"underline":["copper"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0mpr817p4fagiy34dmypyf9l', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve {x + 2y = 5; 3x + 4y = 11} using matrix inverse.', null, '["(1, 2)","(2, 1.5)","(3, 1)","(1, 2.5)"]', 0, 'x = 1, y = 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve {x + 2y = 5; 3x + 4y = 11} using matrix inverse.', '["(1, 2)","(2, 1.5)","(3, 1)","(1, 2.5)"]', 'Solution: <u>(1, 2)</u>.', '{"bold":[],"italic":[],"underline":["(1, 2)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0nkhzve1dzh590rd9r6v16o9', 'Chemistry', 'JAMB', null, 1983, null, 'The alkanol obtained from the production of <b>soap</b> is', null, '["ethanol","glycerol","methanol","propanol","glycol"]', 1, 'The hydrolysis of fats/oils (saponification) yields soap and glycerol.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The alkanol obtained from the production of <b>soap</b> is', '["ethanol","glycerol","methanol","propanol","glycol"]', 'The hydrolysis of fats/oils (saponification) yields soap and <u>glycerol</u>.', '{"bold":["soap"],"italic":[],"underline":["glycerol"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0nlmw52caiqyu277biq1d7kh', 'General Mathematics', 'WAEC', null, 2020, null, 'Two numbers are drawn from {1, ..., 10} without replacement. Find the probability their sum is even.', null, '["4/9","1/2","5/9","2/3"]', 1, 'P(even) = (5C2 + 5C2)/10C2 = 20/45 = 4/9. Key says 1/2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Two numbers are drawn from {1, ..., 10} without replacement. Find the probability their sum is even.', '["4/9","1/2","5/9","2/3"]', 'P = <u>1/2</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0ohi8tul5fzmgso8r11y1a0i', 'Biology', 'JAMB', null, 1993, null, 'A biome with a low annual rainfall, few scattered trees within dense layer of grasses and found in Kano and Katsina States is', null, '["1","2","3","4"]', 3, 'The biome described is the Northern Guinea savannah (4).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A biome with a low annual rainfall, few scattered trees within dense layer of grasses and found in Kano and Katsina States is', '["1","2","3","<u>4</u>"]', 'The biome described is the <u>Northern Guinea savannah (4)</u>.', null);
