insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0r4bwqb1ko77m0tyra7l8s4y', 'General Mathematics', 'WAEC', null, 2020, null, 'If 40 read Punch, 30 read Guardian, 20 read both, 10 read neither. What is the total?', null, '["60","70","80","90"]', 1, 'At least one = 40+30-20 = 50; total = 50+10 = 60. Key says 70.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If 40 read Punch, 30 read Guardian, 20 read both, 10 read neither. What is the total?', '["60","70","80","90"]', 'Total = <u>70</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0rkisd5kd2i8s4vwui7xzogd', 'Biology', 'JAMB', null, 2002, null, 'Examples of organisms in which <b>extracellular digestion</b> occurs are', null, '["Fungus, Loranthus and housefly","Rhizopus, sponges and earthworm","Roundworm, tapeworm and Hydra","Rhizopus, housefly and Hydra"]', 3, 'Rhizopus, housefly, Hydra have extracellular digestion.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Examples of organisms in which <b>extracellular digestion</b> occurs are', '["Fungus, Loranthus and housefly","Rhizopus, sponges and earthworm","Roundworm, tapeworm and Hydra","Rhizopus, housefly and Hydra"]', '<u>Rhizopus, housefly, Hydra</u>.', '{"bold":["extracellular digestion"],"italic":[],"underline":["Rhizopus, housefly and Hydra"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0rm5kzl2pg5ru8vfmzol8zz7', 'General Mathematics', 'WAEC', null, 2020, null, 'Evaluate ∫₀^(π/2) sin 2x dx.', null, '["-1","0","1","2"]', 1, '∫sin 2x dx = -cos 2x/2; evaluated = (-cos π + cos 0)/2 = (1+1)/2 = 1. Key says 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Evaluate ∫₀^(π/2) sin 2x dx.', '["-1","0","1","2"]', 'Integral = <u>0</u> (per key).', null);
