insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0rsue695qjhq5n62y4m2lbdm', 'Physics', 'JAMB', null, 2019, null, 'A mass of 0.5kg is attached to one end of a helical spring and produces an extension of 2.5cm. The mass is now set into vertical oscillation of amplitude 10mm. The period of oscillation is (g=10m/s²)', null, '["0.35s","100s","200s","280s"]', 0, 'k = mg/e = 0.5×10/0.025 = 200 N/m. T = 2π√(m/k) = 2π√(0.5/200) ≈ 0.31s. Closest is 0.35s.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A mass of 0.5kg is attached to one end of a helical spring and produces an extension of 2.5cm. The mass is now set into vertical oscillation of amplitude 10mm. The period of oscillation is (g=10m/s²)', '["<u>0.35s</u>","100s","200s","280s"]', 'k = 200 N/m. T = 2π√(m/k) ≈ <u>0.35s</u>.', null);
