insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0ryf9gk5avp71mecj91pjvg1', 'Biology', 'JAMB', null, 1993, null, 'Which is the most important adaptation of a bony fish to life in water?', null, '["The possession of a streamlined shape","The presence of overlapping scales","The covering of the body by thin film of shine","The possession of a caudal fin"]', 0, 'A streamlined shape is the most important adaptation for life in water.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which is the most important adaptation of a bony fish to life in water?', '["<u>The possession of a streamlined shape</u>","The presence of overlapping scales","The covering of the body by thin film of shine","The possession of a caudal fin"]', '<u>A streamlined shape</u> is the most important adaptation for life in water.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0s6nws9pl5tu2g6lbm0fxpde', 'Government', 'JAMB', null, 2020, null, 'Nigeria''s influence in OPEC is determined by the', null, '["volume of her oil reserve","sizes of her refineries","accessibility of her oil field","low sulphur content of her crude"]', 0, 'Nigeria''s OPEC influence is based on oil reserve volume.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Nigeria''s influence in OPEC is determined by the', '["<u>volume of her oil reserve</u>","sizes of her refineries","accessibility of her oil field","low sulphur content of her crude"]', '<u>Volume of her oil reserve</u>.', '{"bold":[],"italic":[],"underline":["volume of her oil reserve"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0s8u5zbqarpqkjh4sg23g032', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The message in Q. 2:219 is that wine and gambling are', null, '["good for man","bad for man","profitable for man","harmless to man"]', 1, 'Wine and gambling are bad for man.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The message in Q. 2:219 is that wine and gambling are', '["good for man","<u>bad for man</u>","profitable for man","harmless to man"]', '<u>Bad for man</u> (Q. 2:219).', '{"bold":[],"italic":[],"underline":["bad for man"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0sig7ggje2nrtub657pqjz3e', 'Chemistry', 'JAMB', null, 1984, null, '3.0g of a mixture of potassium carbonate and potassium chloride were dissolved in a 250cm³ standard flask. 25cm³ of this solution required 40.00cm³ of 0.1M HCl for neutralization. What is the percentage by weight of K2CO3 in the mixture? [K=39, O=16, C=12]', null, '["60","72","82","89","92"]', 2, 'Moles HCl = 0.004; moles K2CO3 in 25cm³ = 0.002; in 250cm³ = 0.02; mass = 2.76g; % = 92%. Answer key says 82.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '3.0g of a mixture of potassium carbonate and potassium chloride were dissolved in a 250cm³ standard flask. 25cm³ of this solution required 40.00cm³ of 0.1M HCl for neutralization. What is the percentage by weight of K2CO3 in the mixture? [K=39, O=16, C=12]', '["60","72","82","89","92"]', 'Moles K2CO3 = 0.02; mass = 2.76g; % = <u>92%</u> (key says 82).', '{"bold":[],"italic":[],"underline":["82"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0sikfadutjd7c5r7j0ufbtih', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the determinant of [[1, 2, 3], [4, 5, 6], [7, 8, 10]].', null, '["-3","-6","0","3"]', 0, 'det = 1(50-48) - 2(40-42) + 3(32-35) = 2 + 4 - 9 = -3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the determinant of [[1, 2, 3], [4, 5, 6], [7, 8, 10]].', '["-3","-6","0","3"]', 'det = <u>-3</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0sqsluqjjubdxdm2jch05m7k', 'Islamic Religious Studies', 'JAMB', null, 2003, null, 'Muhammed Bello justified Jihad against the Islamic state of Borno because of the people''s tendency towards', null, '["syncretism","extremism","asceticism","formalism"]', 0, 'Syncretism (mixing Islamic and traditional beliefs) was the reason for the jihad.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Muhammed Bello justified Jihad against the Islamic state of Borno because of the people''s tendency towards', '["<u>syncretism</u>","extremism","asceticism","formalism"]', '<u>Syncretism</u> was the reason for the jihad.', '{"bold":[],"italic":[],"underline":["syncretism"],"fillBlanks":[]}');
