insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0svu279nmmecrovcuzpm82t1', 'Biology', 'JAMB', null, 1984, null, 'Heat produced in tissue respiration in plants is', null, '["a chemical from of energy","the only form of energy","the main form of energy","a useful form of energy","a waste from of energy"]', 4, 'Heat from tissue respiration is a waste form of energy.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Heat produced in tissue respiration in plants is', '["a chemical from of energy","the only form of energy","the main form of energy","a useful form of energy","<u>a waste from of energy</u>"]', 'Heat from tissue respiration is a <u>waste form of energy</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0sxaflgg23svjy7wdxlvt5c1', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Hosea declares that the upright walk in the ways of the LORD, but transgressors', null, '["stumble in them","flee from them","scorn them","reject them."]', 0, 'Transgressors stumble in them.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Hosea declares that the upright walk in the ways of the LORD, but transgressors', '["<u>stumble in them</u>","flee from them","scorn them","reject them."]', '<u>Stumble in them</u> (Hosea 14:9).', '{"bold":[],"italic":[],"underline":["stumble in them"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0t09wedjba6b7b94hszidvyn', 'General Mathematics', 'WAEC', null, 2020, null, 'In an AP, Tₘ = n and Tₙ = m. Find Tₘ₊ₙ.', null, '["0","m + n","m - n","m"]', 0, 'a + (m-1)d = n; a + (n-1)d = m; subtracting: (m-n)d = n-m → d = -1; a = m + n - 1; Tₘ₊ₙ = a + (m+n-1)d = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In an AP, Tₘ = n and Tₙ = m. Find Tₘ₊ₙ.', '["0","m + n","m - n","m"]', 'Tₘ₊ₙ = <u>0</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0t5d7fxjbmtft2j9bn3sl8pg', 'Biology', 'JAMB', null, 1997, null, 'Which organism in the food-web illustrated above is an <b>omnivore</b>?', null, '["Weevils","Rat","Hawk","Praying mantis"]', 1, 'The rat is an omnivore.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which organism in the food-web illustrated above is an <b>omnivore</b>?', '["Weevils","Rat","Hawk","Praying mantis"]', '<u>The rat is an omnivore</u>.', '{"bold":["omnivore"],"italic":[],"underline":["Rat"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0tuvw5mqqqtxoxm7tguswwmr', 'Chemistry', 'JAMB', null, 1992, null, 'Which of the following oxides of nitrogen is <b>unstable in air</b>?', null, '["NO","N2O","NO2","N2O4"]', 0, 'NO reacts readily with O2 in air to form NO2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following oxides of nitrogen is <b>unstable in air</b>?', '["NO","N2O","NO2","N2O4"]', '<u>NO is unstable in air</u> (forms NO2).', '{"bold":["unstable in air"],"italic":[],"underline":["NO"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0u2npyubl6aneoibzu5kcqoq', 'General Mathematics', 'WAEC', null, 2020, null, 'Find d/dx(ln|sec x + tan x|).', null, '["sec x","tan x","csc x","cot x"]', 0, 'Derivative = sec x.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find d/dx(ln|sec x + tan x|).', '["sec x","tan x","csc x","cot x"]', 'Derivative = <u>sec x</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0u2rbbbmj6yb6noxy6nxp1y4', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The verse (Q. 99:4) translates as ''On that Day will', null, '["all people declare their deeds","she declare her tidings","the dead be raised up","men proclaim religion."]', 1, 'The verse translates as ''she declare her tidings''.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The verse (Q. 99:4) translates as ''On that Day will', '["all people declare their deeds","<u>she declare her tidings</u>","the dead be raised up","men proclaim religion."]', '<u>She declare her tidings</u> (Q. 99:4).', '{"bold":[],"italic":[],"underline":["she declare her tidings"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0u7exx5xavleppn05n4r8u4h', 'Chemistry', 'JAMB', null, 1995, null, 'A metallic oxide which reacts with both HCl and NaOH to give salt and water only can be classified as', null, '["an acidic oxide","an atmospheric oxide","a neutral oxide","an amphoteric oxide"]', 3, 'Amphoteric oxides react with both acids and bases.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A metallic oxide which reacts with both HCl and NaOH to give salt and water only can be classified as', '["an acidic oxide","an atmospheric oxide","a neutral oxide","an amphoteric oxide"]', '<u>Amphoteric oxide</u>.', '{"bold":[],"italic":[],"underline":["an amphoteric oxide"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0u8rx2e8zi40sv8egiwkgukt', 'Biology', 'JAMB', null, 1993, null, 'Which of the following combinations differentiates a bony fish from a cartilaginous fish? I Presence of gills. II Absence of gill slits III Possession of bony skeleton IV Possession of laterally compressed body V Possession of dorso ventrally compressed body', null, '["I,II and II","I, III and IV","II, III and IV","II, III and V"]', 1, 'Bony fish have gills, bony skeleton, and laterally compressed body.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following combinations differentiates a bony fish from a cartilaginous fish?<br>I Presence of gills.<br>II Absence of gill slits<br>III Possession of bony skeleton<br>IV Possession of laterally compressed body<br>V Possession of dorso ventrally compressed body', '["I,II and II","<u>I, III and IV</u>","II, III and IV","II, III and V"]', '<u>Bony fish have gills, bony skeleton, and laterally compressed body</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0ucy1ugdxn4uq646zv06g52p', 'Christian Religious Studies', 'JAMB', null, 2020, null, '... In the territory of Jezreel the dogs shall eat the flesh of Jezebel... so that no one can say, This is Jezebel. In the statement above, Jehu was referring to the prophecy of', null, '["Elijah","Elisha","Nathan","Micah"]', 0, 'Jehu referred to Elijah''s prophecy.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '... In the territory of Jezreel the dogs shall eat the flesh of Jezebel... so that no one can say, This is Jezebel. In the statement above, Jehu was referring to the prophecy of', '["<u>Elijah</u>","Elisha","Nathan","Micah"]', '<u>Elijah</u> (1 Kings 21:23).', '{"bold":[],"italic":[],"underline":["Elijah"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0uesw2zn7ang8sx8qjndtflh', 'Chemistry', 'JAMB', null, 1991, null, 'Which of the following, in clear solution, forms a white precipitate when <b>carbon(IV) oxide</b> is bubbled into it for a short time?', null, '["KOH","NaOH","Ca(OH)2","Al(OH)3"]', 2, 'CO2 + Ca(OH)2 → CaCO3 (white precipitate) + H2O.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following, in clear solution, forms a white precipitate when <b>carbon(IV) oxide</b> is bubbled into it for a short time?', '["KOH","NaOH","Ca(OH)2","Al(OH)3"]', '<u>Ca(OH)2</u> gives white CaCO3 precipitate with CO2.', '{"bold":["carbon(IV) oxide"],"italic":[],"underline":["Ca(OH)2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0uhp3w21dm1kpo90vd8742vf', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The battle of Khandaq was known as such because the', null, '["encounter took place near Khandaq","Muslims dug a trench as a war strategy","hypocrites protected Khandaq from enemies","Quraysh fell into a trench."]', 1, 'The Muslims dug a trench as a war strategy.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The battle of Khandaq was known as such because the', '["encounter took place near Khandaq","<u>Muslims dug a trench as a war strategy</u>","hypocrites protected Khandaq from enemies","Quraysh fell into a trench."]', '<u>Muslims dug a trench as a war strategy</u>.', '{"bold":[],"italic":[],"underline":["Muslims dug a trench as a war strategy"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0ui683d6c7ye1h9cr0sjpcqe', 'General Mathematics', 'WAEC', null, 2020, null, 'What is 111001₂ - 10011₂ in base two?', null, '["100110₂","100010₂","100110₂","101110₂"]', 1, '111001₂ = 57; 10011₂ = 19; difference = 38 = 100110₂. Key says 100010₂.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is 111001₂ - 10011₂ in base two?', '["100110₂","100010₂","100110₂","101110₂"]', '111001₂ - 10011₂ = <u>100110₂</u> (key says 100010₂).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0umdrapwvtv7ouv3ogerl54k', 'Chemistry', 'JAMB', null, 1992, null, 'Safety matches contain sulphur and', null, '["Potassium trioxochlorate(V)","Potassium trioxonitrate(V)","Charcoal","Phosphorus sulphide"]', 3, 'Safety match heads contain phosphorus sulphide and sulphur.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Safety matches contain sulphur and', '["Potassium trioxochlorate(V)","Potassium trioxonitrate(V)","Charcoal","Phosphorus sulphide"]', '<u>Phosphorus sulphide</u> is in safety matches.', '{"bold":[],"italic":[],"underline":["Phosphorus sulphide"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0uny8wmx5hs1vuqjc2mvynsz', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the range of m so that x² + (m-3)x + m = 0 has real roots.', null, '["m≤1 or m≥9","m≤-1 or m≥9","m≤1 or m≥8","m≤-2 or m≥7"]', 1, '(m-3)² - 4m ≥ 0 → m²-10m+9 ≥ 0 → m ≤ 1 or m ≥ 9. Key says m≤-1 or m≥9.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the range of m so that x² + (m-3)x + m = 0 has real roots.', '["m≤1 or m≥9","m≤-1 or m≥9","m≤1 or m≥8","m≤-2 or m≥7"]', '<u>m ≤ 1 or m ≥ 9</u> (key says m≤-1 or m≥9).', '{"bold":[],"italic":[],"underline":["m≤-1 or m≥9"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0upmsko4ufcmdf3hnlz77g10', 'General Mathematics', 'WAEC', null, 2020, null, 'If a*b = ab/(a + b), find 2*(3*6).', null, '["1","2","3","4"]', 0, '3*6 = 18/9 = 2; 2*2 = 4/4 = 1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If a*b = ab/(a + b), find 2*(3*6).', '["1","2","3","4"]', '2*(3*6) = <u>1</u>.', null);
