insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0wluq29x56xmewjao3uwire9', 'General Mathematics', 'JAMB', null, 2020, null, 'If x, y, z are in HP, then x/(y+z-x) = ?', null, '["y/(z+x-y)","z/(x+y-z)","both","none"]', 2, 'In HP, x/(y+z-x) = y/(z+x-y) = z/(x+y-z).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If x, y, z are in HP, then x/(y+z-x) = ?', '["y/(z+x-y)","z/(x+y-z)","both","none"]', 'Both equal.', '{"bold":[],"italic":[],"underline":["both"],"fillBlanks":[]}');
