insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0wo0uumb8wdxtqt0ww4vruju', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the missing digit: 345₆ + 43_₆ = 443₆.', null, '["1","2","3","4"]', 0, '345₆ + 43x₆ = 443₆ → 137 + (4×6 + 3×6 + x) = 167 → 137 + 27 + x = 167 → x = 3. Key says 1.', false, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Find the missing digit: 345₆ + 43_₆ = 443₆.', '["1","2","3","4"]', 'Missing digit = <u>3</u> (key says 1).', '{"bold":[],"italic":[],"underline":["1"],"fillBlanks":[]}');
