insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0x9f6tmoigv99etid1kba747', 'Chemistry', 'JAMB', null, 1984, null, 'X + Y ⇌ Z is an equilibrium reaction. The addition of a <b>catalyst</b>', null, '["increases the amount of W produced in a given time","increases the rate of change in concentrations of X, Y and Z","increases the rate of disappearance of X and Y","increases the rate of the forward reaction","decreases the amounts of X and Y left after the attainment of equilibrium"]', 1, 'A catalyst increases the rate of both forward and reverse reactions equally.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'X + Y ⇌ Z is an equilibrium reaction. The addition of a <b>catalyst</b>', '["increases the amount of W produced in a given time","increases the rate of change in concentrations of X, Y and Z","increases the rate of disappearance of X and Y","increases the rate of the forward reaction","decreases the amounts of X and Y left after the attainment of equilibrium"]', 'A catalyst <u>increases the rate of both forward and reverse reactions</u>.', '{"bold":["catalyst"],"italic":[],"underline":["increases the rate of change in concentrations of X, Y and Z"],"fillBlanks":[]}');
