insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0y3upjygvwpxsalnyfqmyfwr', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve: x⁴ - 5x² + 4 = 0', null, '["±1, ±2","±1, ±3","±2, ±3","±1, ±4"]', 0, 'y² - 5y + 4 = 0 → y = 1 or 4 → x = ±1, ±2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve: x⁴ - 5x² + 4 = 0', '["±1, ±2","±1, ±3","±2, ±3","±1, ±4"]', '<u>x = ±1, ±2</u>.', '{"bold":[],"italic":[],"underline":["±1, ±2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0y5oa4ckkgwrfvieyo9x8vv6', 'Chemistry', 'JAMB', null, 1996, null, 'The data in the table above shows the rate of reaction of nitrogen(II) oxide with chlorine at 25°C. It can be concluded that doubling the initial concentration of NO increases the rate of reaction by a factor of', null, '["two","three","four","five"]', 2, 'Rate ∝ [NO]², so doubling [NO] quadruples rate.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The data in the table above shows the rate of reaction of nitrogen(II) oxide with chlorine at 25°C. It can be concluded that doubling the initial concentration of NO increases the rate of reaction by a factor of', '["two","three","four","five"]', 'Doubling [NO] → rate × <u>4</u>.', '{"bold":[],"italic":[],"underline":["four"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0ycrx8tj4jvs38p3x6tdlikj', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the remainder when 4x⁴ - 3x³ + 2x² - x + 5 is divided by (2x - 1).', null, '["39/8","75/8","75/4","75/2"]', 0, 'R = f(1/2) = 1/4 - 3/8 + 1/2 - 1/2 + 5 = 39/8.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Find the remainder when 4x⁴ - 3x³ + 2x² - x + 5 is divided by (2x - 1).', '["39/8","75/8","75/4","75/2"]', 'R = f(1/2) = 1/4 - 3/8 + 1/2 - 1/2 + 5 = 39/8.', '{"bold":[],"italic":[],"underline":["75/16"],"fillBlanks":[]}');
