insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0yjde9msbb8pww0er47dmplj', 'Chemistry', 'JAMB', null, 1999, null, 'Which of the following statements is true of the <b>electrochemical series</b>?', null, '["Electropositivity of metals increase down the series","Electropositivity of non-metals decrease down the series","Electronegativity of non-metals increase down the series","Electropositivity of metals decreases down the series"]', 0, 'Electropositivity increases down the series.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following statements is true of the <b>electrochemical series</b>?', '["Electropositivity of metals increase down the series","Electropositivity of non-metals decrease down the series","Electronegativity of non-metals increase down the series","Electropositivity of metals decreases down the series"]', '<u>Electropositivity increases down the series</u>.', '{"bold":["electrochemical series"],"italic":[],"underline":["Electropositivity of metals increase down the series"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0ylfhcxtvknw469pi4euq917', 'Chemistry', 'JAMB', null, 1995, null, 'Fe2O3(s) + 2Al → Al2O3 + 2Fe(s). Given ΔHf(Fe2O3) = -1670 kJ mol⁻¹ and ΔHf(Al2O3) = -822 kJ mol⁻¹, the enthalpy change in kJ for the reaction is', null, '["+2492","+848","-848","-2492"]', 1, 'ΔH = -822 - (-1670) = +848 kJ.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Fe2O3(s) + 2Al → Al2O3 + 2Fe(s). Given ΔHf(Fe2O3) = -1670 kJ mol⁻¹ and ΔHf(Al2O3) = -822 kJ mol⁻¹, the enthalpy change in kJ for the reaction is', '["+2492","+848","-848","-2492"]', 'ΔH = <u>+848 kJ</u>.', '{"bold":[],"italic":[],"underline":["+848"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0yu1lgs309zkj1utpjg62hth', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The first Qur''anic verse revealed, instructed the Prophet (S.A.W) to', null, '["engage in preaching and warning","seek knowledge through reading","keep vigil the night long","read the minds of people."]', 1, 'The first verse instructed him to read (seek knowledge).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The first Qur''anic verse revealed, instructed the Prophet (S.A.W) to', '["engage in preaching and warning","<u>seek knowledge through reading</u>","keep vigil the night long","read the minds of people."]', '<u>Seek knowledge through reading</u> (Q. 96:1).', '{"bold":[],"italic":[],"underline":["seek knowledge through reading"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0ywl8vrh38defr1nx5pi7uag', 'General Mathematics', 'WAEC', null, 2020, null, 'The variance of the numbers 4, 5, 6, 8, and x is 6.8. Find x.', null, '["2","7","10","12"]', 1, 'Mean = (23+x)/5; variance = 6.8; solving → x = 7.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The variance of the numbers 4, 5, 6, 8, and x is 6.8. Find x.', '["2","7","10","12"]', 'x = <u>7</u>.', null);
