insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c0z0ivxjcdo1i4qzyn528ed3l', 'Islamic Religious Studies', 'JAMB', null, 2010, null, 'The significant message contained in surah <b>at-Takathur</b> is that', null, '["passion for wealth and position may divert man''s attention from worship of Allah","moral obligation and spiritual sacrifice should be uppermost in the minds of a true believer","man should avoid committing sin at all times","man should pray five times daily"]', 0, 'At-Takathur warns against obsession with wealth.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The significant message contained in surah <b>at-Takathur</b> is that', '["<u>passion for wealth and position may divert man''s attention from worship of Allah</u>","moral obligation and spiritual sacrifice should be uppermost in the minds of a true believer","man should avoid committing sin at all times","man should pray five times daily"]', '<u>At-Takathur</u> warns against obsession with wealth.', '{"bold":["at-Takathur"],"italic":[],"underline":["passion for wealth and position may divert man''s attention from worship of Allah"],"fillBlanks":[]}');
