insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c142tcltcqeucad2io2l32dzi', 'General Mathematics', 'JAMB', null, 2020, null, 'What is the value of x for which: x ≡ 2 (mod 3), x ≡ 3 (mod 5).', null, '["8","13","18","23"]', 0, 'x = 8: 8 mod 3 = 2; 8 mod 5 = 3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is the value of x for which: x ≡ 2 (mod 3), x ≡ 3 (mod 5).', '["8","13","18","23"]', 'x = <u>8</u>.', '{"bold":[],"italic":[],"underline":["8"],"fillBlanks":[]}');
