insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c1a8ghb6hs22u73mo2zos15jf', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'The destruction of Jerusalem by Nebuchadnezzar was a consequence of', null, '["Hezekiah''s death","Josiah''s reforms","Israel''s stubbornness","Zedekiah''s rebellion against Babylon."]', 3, 'It was a consequence of Zedekiah''s rebellion against Babylon.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The destruction of Jerusalem by Nebuchadnezzar was a consequence of', '["Hezekiah''s death","Josiah''s reforms","Israel''s stubbornness","<u>Zedekiah''s rebellion against Babylon.</u>"]', '<u>Zedekiah''s rebellion against Babylon</u>.', '{"bold":[],"italic":[],"underline":["Zedekiah''s rebellion against Babylon."],"fillBlanks":[]}');
