insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c1ad6c5e-3145-443f-a081-57d4103cbb4e', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). There is <u>no love lost between Hassan and Hassana</u>.', null, '["dislike each other","are head over heels in love","will love each other","are still good friends"]', 0, '''No love lost'' = dislike each other.', true, '2026-10-24 01:02:04.318', '2026-10-24 01:02:04.318', null, null, null, '(Choose the most appropriate interpretation). There is <u>no love lost between Hassan and Hassana</u>.', '["<u>dislike each other</u>","are head over heels in love","will love each other","are still good friends"]', '''<b>No love lost</b>'' = <b>dislike each other</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c1adc77c3o60fbo89y856z1ex', 'Islamic Religious Studies', 'JAMB', null, 2003, null, 'The author of the <b>Muwatta</b> was the Imam of', null, '["Madinah","Makkah","Kufah","Basrah"]', 0, 'Imam Malik, author of the Muwatta, was the Imam of Madinah.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The author of the <b>Muwatta</b> was the Imam of', '["<u>Madinah</u>","Makkah","Kufah","Basrah"]', '<u>Imam Malik</u>, author of the Muwatta, was the Imam of Madinah.', '{"bold":["Muwatta"],"italic":[],"underline":["Madinah"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c1akwgiw5c7f28ctur0b1dv1j', 'Chemistry', 'JAMB', null, 1992, null, 'On which of the following is the solubility of a gaseous substance dependent?<br>I. Nature of solvent<br>II. Nature of solute<br>III. Temperature<br>IV. Pressure', null, '["I, II, III and IV","I and II only","II only","I, III and IV only"]', 0, 'All four factors affect gas solubility.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'On which of the following is the solubility of a gaseous substance dependent?<br>I. Nature of solvent<br>II. Nature of solute<br>III. Temperature<br>IV. Pressure', '["I, II, III and IV","I and II only","II only","I, III and IV only"]', '<u>All four factors</u> affect gas solubility.', '{"bold":[],"italic":[],"underline":["I, II, III and IV"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c1ao76wt2y8lkkpzj61rjxxld', 'Christian Religious Studies', 'JAMB', null, 2020, null, '...The soul that sins shall die. The statement above by Prophet Ezekiel means that', null, '["God will judge the soul of a sinner","a sinner shall not escape punishment","every person is responsible for his own sin","the wages of sin is death."]', 2, 'Every person is responsible for his own sin.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '...The soul that sins shall die. The statement above by Prophet Ezekiel means that', '["God will judge the soul of a sinner","a sinner shall not escape punishment","<u>every person is responsible for his own sin</u>","the wages of sin is death."]', '<u>Every person is responsible for his own sin</u> (Ezekiel 18).', '{"bold":[],"italic":[],"underline":["every person is responsible for his own sin"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c1auqg2z7gdtp7g4rp1jtx5n2', 'General Mathematics', 'WAEC', null, 2020, null, 'If α and β are the roots of x² - 5x + 2 = 0, find the equation whose roots are α²/β and β²/α.', null, '["2x² - 21x + 4 = 0","2x² + 21x + 4 = 0","4x² - 21x + 2 = 0","4x² + 21x + 2 = 0"]', 0, 'α+β = 5, αβ = 2; new sum = (α³+β³)/αβ = (125-30)/2 = 95/2; new product = αβ = 2; equation: 2x² - 21x + 4 = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If α and β are the roots of x² - 5x + 2 = 0, find the equation whose roots are α²/β and β²/α.', '["2x² - 21x + 4 = 0","2x² + 21x + 4 = 0","4x² - 21x + 2 = 0","4x² + 21x + 2 = 0"]', 'Equation: <u>2x² - 21x + 4 = 0</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c1b22n3xeejh6hk1lt9qrnhdc', 'General Mathematics', 'JAMB', null, 2020, null, 'If α, β are roots of x² + px + q = 0 form the equation with roots α², β².', null, '["x²-(p²-2q)x+q²=0","x²-(p²+2q)x+q²=0","x²+(p²-2q)x+q²=0","x²+(p²+2q)x+q²=0"]', 0, 'Sum = α²+β² = p²-2q; product = q².', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If α, β are roots of x² + px + q = 0 form the equation with roots α², β².', '["x²-(p²-2q)x+q²=0","x²-(p²+2q)x+q²=0","x²+(p²-2q)x+q²=0","x²+(p²+2q)x+q²=0"]', null, '{"bold":[],"italic":[],"underline":["x²-(p²-2q)x+q²=0"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c1b4caarfkbcfgkgdec6ucee8', 'Biology', 'JAMB', null, 1995, null, 'Which of the following insects lays its eggs in horny, purse-like cases?', null, '["Mosquito.","Butterfly.","Termite.","Cockroach."]', 3, 'Cockroach. is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following insects lays its eggs in horny, purse-like cases?', '["Mosquito.","Butterfly.","Termite.","<u>Cockroach.</u>"]', 'Cockroach. is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c1b5tp221bxm7f7jsmakfne7y', 'General Mathematics', 'WAEC', null, 2020, null, 'cos 36° - cos 72° =', null, '["1/2","1/3","1/4","1/6"]', 0, 'cos 36° - cos 72° = 1/2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'cos 36° - cos 72° =', '["1/2","1/3","1/4","1/6"]', 'Value = <u>1/2</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c1b7adbru8dsm89gfj31wlc6p', 'Biology', 'JAMB', null, 1997, null, 'The three classes in a <b>termitarium</b> are', null, '["soldiers, queen and workers","workers, soldiers and reproductive","soldiers, workers and kings","kings, queen and soldiers"]', 1, 'Termite castes: workers, soldiers, reproductive.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The three classes in a <b>termitarium</b> are', '["soldiers, queen and workers","workers, soldiers and reproductive","soldiers, workers and kings","kings, queen and soldiers"]', '<u>Workers, soldiers, reproductive</u>.', '{"bold":["termitarium"],"italic":[],"underline":["workers, soldiers and reproductive"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c1babd98-8e12-4bf4-ac17-9af659df5183', 'Literature in English', 'JAMB', null, 2026, null, 'A performance whereby a story is expressed through singing and music is called', null, '["Drama","Opera","Pantomime","Ballet"]', 1, 'A performance whereby a story is expressed through singing and music is called an opera. Opera is a dramatic work in which the action is conveyed through music and singing rather than spoken dialogue. Drama uses spoken dialogue, pantomime uses gestures without words, and ballet uses dance to tell a story. Opera combines music, singing, and drama.', true, '2026-09-10 10:47:09.668', '2026-09-10 10:47:09.668', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c1bjj1zwp1jnngow7ezein87p', 'Biology', 'JAMB', null, 1995, null, 'The least evidence in support of the theory of evolution is provided by the study of', null, '["anatomy","ecology","geology","embryology.8"]', 1, 'ecology is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The least evidence in support of the theory of evolution is provided by the study of', '["anatomy","<u>ecology</u>","geology","embryology.8"]', 'ecology is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c1bm470meqgd2rhvy083r6xmc', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the identity for a*b = a + b + 3.', null, '["-3","0","3","none"]', 0, 'a*e = a → a+e+3 = a → e = -3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the identity for a*b = a + b + 3.', '["-3","0","3","none"]', 'Identity = <u>-3</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c1bsu3uokm2nuootjokpwq31l', 'Chemistry', 'JAMB', null, 1992, null, 'An emulsion paint consists of', null, '["gas or liquid particles dispersed in liquid","liquid particles dispersed in liquid","solid particles dispersed in liquid","solid particles dispersed in solid"]', 1, 'Emulsion paint is liquid-in-liquid dispersion.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An emulsion paint consists of', '["gas or liquid particles dispersed in liquid","liquid particles dispersed in liquid","solid particles dispersed in liquid","solid particles dispersed in solid"]', '<u>Liquid particles dispersed in liquid</u> (emulsion).', '{"bold":[],"italic":[],"underline":["liquid particles dispersed in liquid"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c1bxd1fsnjmnkn3a8dfzi4oew', 'Chemistry', 'JAMB', null, 1990, null, 'The volume occupied by 1.58g of a gas at s.t.p is 500cm³. What is the relative molecular mass of the gas?', null, '["28","32","344","71"]', 2, 'Moles = 0.5/22.4 = 0.0223; Mr = 1.58/0.0223 = 71. Closest is 71.', true, '2026-10-11 07:17:11.699', '2026-10-24 07:26:54.629', null, null, null, 'The volume occupied by 1.58g of a gas at s.t.p is 500cm³. What is the relative molecular mass of the gas?', '["28","32","344","71"]', 'Moles = 0.0223; Mr = <u>71</u> (key says 344).', '{"bold":[],"italic":[],"underline":["344"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c1bxugigkaiyi8xx41o52v63w', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The money given to a woman at the time of contracting her marriage is known as', null, '["al-Mahar","al-Zakah","al-Jizyyah","al-Ujrah"]', 0, 'It is al-Mahar.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The money given to a woman at the time of contracting her marriage is known as', '["<u>al-Mahar</u>","al-Zakah","al-Jizyyah","al-Ujrah"]', '<u>Al-Mahar</u>.', '{"bold":[],"italic":[],"underline":["al-Mahar"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c1by6o7rkpm8fzeusqe2pz5xz', 'Chemistry', 'JAMB', null, 1992, null, 'The characteristic reaction of <b>carbonyl compounds</b> is', null, '["Substitution","Elimination","Addition","Saponification"]', 2, 'Carbonyl compounds undergo nucleophilic addition.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The characteristic reaction of <b>carbonyl compounds</b> is', '["Substitution","Elimination","Addition","Saponification"]', '<u>Addition</u> is characteristic of carbonyl compounds.', '{"bold":["carbonyl compounds"],"italic":[],"underline":["Addition"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c1c131x0ybgbjzf39v18trhhx', 'General Mathematics', 'JAMB', null, 2020, null, 'In how many ways can the letters of the word "INSTITUTE" be arranged so that the vowels always come together?', null, '["3024","1440","12096","18144"]', 1, 'Vowels I,I,U,E form one block (4!/2! = 12 orders); the block and N,S,T,T,T give 6!/3! = 120; 120 × 12 = 1440.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'In how many ways can the letters of the word "INSTITUTE" be arranged so that the vowels always come together?', '["3024","1440","12096","18144"]', 'Vowels I,I,U,E form one block (4!/2! = 12 orders); the block and N,S,T,T,T give 6!/3! = 120; 120 × 12 = 1440.', '{"bold":[],"italic":[],"underline":["6048"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c1c3364iltfp5ratdrdqubhsc', 'Chemistry', 'JAMB', null, 1983, null, 'Sodium chloride may be obtained from brine by', null, '["titration","decantation","distillation","evaporation","sublimation"]', 3, 'Evaporation of brine leaves sodium chloride crystals.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Sodium chloride may be obtained from brine by', '["titration","decantation","distillation","evaporation","sublimation"]', '<u>Evaporation</u> of brine leaves sodium chloride crystals.', '{"bold":[],"italic":[],"underline":["evaporation"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c1c7d1e4-8d80-490e-921f-0eae57aec658', 'Biology', 'JAMB', null, 2004, null, 'Identical twins inherit their genes from', null, '["different eggs and sperms","the same egg and sperm","two eggs and a sperm","one egg and two sperms"]', 1, 'Identical twins inherit from the same egg and sperm.', true, '2026-10-12 20:59:35.888', '2026-10-12 20:59:35.888', null, null, null, 'Identical twins inherit their genes from', '["different eggs and sperms","the same egg and sperm","two eggs and a sperm","one egg and two sperms"]', 'Identical twins inherit from the same egg and sperm.', '{"bold":["the same egg and sperm"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c1cccwzm1t7ez0680rh10s4i0', 'General Mathematics', 'JAMB', null, 2020, null, 'What is 3¹⁰⁰ (mod 7)?', null, '["1","2","3","4"]', 0, '3⁶ ≡ 1 mod 7; 100 = 6×16 + 4; 3⁴ = 81 ≡ 4 mod 7. Key says 1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is 3¹⁰⁰ (mod 7)?', '["1","2","3","4"]', '3¹⁰⁰ ≡ 3⁴ = 81 ≡ <u>4</u> mod 7 (key says 1).', '{"bold":[],"italic":[],"underline":["1"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c1ce1v1x09ycixeull9539puw', 'General Mathematics', 'JAMB', null, 2020, null, 'What is the exact value of tan 15°?', null, '["2 - √3","√3 - 2","2 + √3","√3 + 1"]', 0, 'tan 15° = 2 - √3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is the exact value of tan 15°?', '["2 - √3","√3 - 2","2 + √3","√3 + 1"]', 'tan 15° = <u>2 - √3</u>.', '{"bold":[],"italic":[],"underline":["2 - √3"],"fillBlanks":[]}');
