insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c1cj8o78b9hhyakljbcohxmvj', 'Government', 'JAMB', null, 2020, null, 'The major function of the civil service is', null, '["providing relevant information on government","keeping records of the activities of government","promoting the interest of civil servants","advising government and implementing its policies"]', 3, 'The civil service advises government and implements policies.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The major function of the civil service is', '["providing relevant information on government","keeping records of the activities of government","promoting the interest of civil servants","<u>advising government and implementing its policies</u>"]', '<u>Advising government and implementing its policies</u>.', '{"bold":[],"italic":[],"underline":["advising government and implementing its policies"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c1cjt9eu2qj27nz4vc8l15d1o', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'The promise to those who are persecuted for righteousness sake is that they will', null, '["see God","be called the sons of God","inherit the earth","inherit the kingdom of heaven."]', 3, 'They will inherit the kingdom of heaven.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The promise to those who are persecuted for righteousness sake is that they will', '["see God","be called the sons of God","inherit the earth","<u>inherit the kingdom of heaven.</u>"]', '<u>Inherit the kingdom of heaven</u> (Matthew 5:10).', '{"bold":[],"italic":[],"underline":["inherit the kingdom of heaven."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c1cklryw14azf930p2ewzjedj', 'General Mathematics', 'JAMB', null, 2020, null, 'What is the angle between the lines 2x + y + 5 = 0 and x - 2y + 1 = 0?', null, '["0°","45°","60°","90°"]', 3, 'Slopes -2 and 1/2; product = -1 → perpendicular.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is the angle between the lines 2x + y + 5 = 0 and x - 2y + 1 = 0?', '["0°","45°","60°","90°"]', 'Angle = <u>90°</u>.', '{"bold":[],"italic":[],"underline":["90°"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c1cm660dom80mucfa4gz1cug7', 'Biology', 'JAMB', null, 1984, null, 'Which of the following invertebrates does NOT possess antennae?', null, '["Centipede","Crustacean","Millipede","Insect","Snider"]', 4, 'Spiders (sniders) do not possess antennae.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following invertebrates does <b>NOT</b> possess <b>antennae</b>?', '["Centipede","Crustacean","Millipede","Insect","<u>Snider</u>"]', 'Spiders (sniders) <u>do not possess antennae</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c1crcc47oq68nqk3oormcggnk', 'General Mathematics', 'JAMB', null, 2020, null, 'What is the circumradius of triangle with vertices (0,0), (4,0), and (0,3)?', null, '["2.5","3.5","4.5","5"]', 0, 'Right triangle; hypotenuse = 5; circumradius = 2.5.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is the circumradius of triangle with vertices (0,0), (4,0), and (0,3)?', '["2.5","3.5","4.5","5"]', 'Circumradius = <u>2.5</u>.', '{"bold":[],"italic":[],"underline":["2.5"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c1cu1yfibr71uxtf0avmkxwu0', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'To maintain the quality of Taqwa one has to be', null, '["wealthy","disciplined","poor","a leader"]', 1, 'One has to be disciplined.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'To maintain the quality of Taqwa one has to be', '["wealthy","<u>disciplined</u>","poor","a leader"]', '<u>Disciplined</u>.', '{"bold":[],"italic":[],"underline":["disciplined"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c1cwbvre7wn939xl2mmyob428', 'Chemistry', 'JAMB', null, 1999, null, 'When excess ethanol is heated to 145°C in the presence of concentrated H2SO4, the product is', null, '["ethylene","diethyl sulphate","diethyl ether","acetone"]', 2, 'Excess ethanol at 145°C gives diethyl ether.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When excess ethanol is heated to 145°C in the presence of concentrated H2SO4, the product is', '["ethylene","diethyl sulphate","diethyl ether","acetone"]', '<u>Diethyl ether</u> is produced.', '{"bold":[],"italic":[],"underline":["diethyl ether"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c1d124a5-8402-471a-98a9-1fe9eed532fc', 'Biology', 'JAMB', null, 2026, null, 'Sclerenchyma cells are lignified to', null, '["strengthen and support the plant","transport synthesized food","conduct water and salt","protect the plant from injury"]', 0, 'Sclerenchyma cells are lignified (have lignin deposited in their cell walls) to provide mechanical strength and support to the plant. Lignin is a complex polymer that makes the cell walls rigid, strong, and waterproof. Transporting synthesized food is the function of phloem. Conducting water and salts is the function of xylem. Protection from injury is a function of epidermal tissues and cork. Sclerenchyma cells are dead at maturity and provide structural support that allows plants to grow tall and resist various mechanical forces.', true, '2026-09-09 03:18:45.471', '2026-09-09 03:18:45.471', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c1d8j8avdmc3rxn3vej1ze14c', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the sum to infinity of the series: 1/(1+4) + 1/(4+7) + 1/(7+10) + ...', null, '["1/2","1/3","1/4","1/5"]', 1, 'Telescoping series → 1/3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the sum to infinity of the series: 1/(1+4) + 1/(4+7) + 1/(7+10) + ...', '["1/2","1/3","1/4","1/5"]', 'Sum = <u>1/3</u>.', '{"bold":[],"italic":[],"underline":["1/3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c1db70c1-c5e1-4216-a6b6-969e0e52a824', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. ''I do not trust him'' he said, in a rare moment of <u>candor</u>.', null, '["reproach","dishonesty","frankness","fairness"]', 1, 'Candor = honesty; opposite = dishonesty.', true, '2026-10-24 07:21:29.57', '2026-10-24 07:21:29.57', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. ''I do not trust him'' he said, in a rare moment of <u>candor</u>.', '["reproach","dishonesty","frankness","fairness"]', 'Candor = honesty; opposite = dishonesty.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c1dbwf5wgm42l86m3t98riwhm', 'Biology', 'JAMB', null, 2002, null, 'If Xᴺ is the dominant allele for normal vision and Xⁿ the recessive allele for colour-blindness, a boy with the genotype YXⁿ will', null, '["have normal vision","be colour-blind","be totally blind","be a carrier of colour-blindness"]', 1, 'YXⁿ is colour-blind (only one X with recessive allele).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If Xᴺ is the dominant allele for normal vision and Xⁿ the recessive allele for colour-blindness, a boy with the genotype YXⁿ will', '["have normal vision","be colour-blind","be totally blind","be a carrier of colour-blindness"]', '<u>Colour-blind</u>.', '{"bold":[],"italic":[],"underline":["be colour-blind"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c1dl5om12jsl4cydsmtmwyfsd', 'Chemistry', 'JAMB', null, 1988, null, 'Which of the following is used in the manufacture of <b>glass</b>?', null, '["Sodium chlorine","Sodium trioxocarbonate(IV)","Sodium tetraoxosulphate(VI)","Sodium trioxonitrate(V)"]', 1, 'Na2CO3 is used in glass manufacture.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is used in the manufacture of <b>glass</b>?', '["Sodium chlorine","Sodium trioxocarbonate(IV)","Sodium tetraoxosulphate(VI)","Sodium trioxonitrate(V)"]', '<u>Na2CO3</u> is used in glass manufacture.', '{"bold":["glass"],"italic":[],"underline":["Sodium trioxocarbonate(IV)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c1drxbxuhzteb5hbnhysgyekj', 'General Mathematics', 'JAMB', null, 2020, null, 'In a family with 2 children, given at least one is a boy, find the probability both are boys.', null, '["1/3","1/2","1/4","2/3"]', 0, 'Sample space: BB, BG, GB → P(BB) = 1/3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In a family with 2 children, given at least one is a boy, find the probability both are boys.', '["1/3","1/2","1/4","2/3"]', 'P = <u>1/3</u>.', '{"bold":[],"italic":[],"underline":["1/3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c1dry102xsu4m0vkzvhjx2a8a', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the directrix of the parabola y² = -12x.', null, '["x = 3","x = -3","y = 3","y = -3"]', 0, '4a = -12 → a = -3; directrix x = 3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the directrix of the parabola y² = -12x.', '["x = 3","x = -3","y = 3","y = -3"]', 'Directrix: <u>x = 3</u>.', '{"bold":[],"italic":[],"underline":["x = 3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c1dw9thswa8uupzql1pgaeqom', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The ill-treatment of a wife in Islam is called', null, '["hadd","''idrar","shigaq","fitnah."]', 1, 'It is called ''idrar.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The ill-treatment of a wife in Islam is called', '["hadd","<u>''idrar</u>","shigaq","fitnah."]', '<u>''Idrar</u>.', '{"bold":[],"italic":[],"underline":["''idrar"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c1e44zkf4h8rvxnk6ahl7tk1z', 'Biology', 'JAMB', null, 1997, null, 'In mammals, the exchange of nutrients and metabolic products occurs in the', null, '["lymph","lungs","heart","liver."]', 3, 'liver. is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In mammals, the exchange of nutrients and metabolic products occurs in the', '["lymph","lungs","heart","<u>liver.</u>"]', 'liver. is the best answer because it matches the biological principle tested by the question.', null);
