insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c1e6fab2-559a-4eb1-b9d8-ae67510b7355', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The young girl was <u>taken aback</u> by her father''s gift of a car', null, '["shocked","unmoved","surprised","nonplussed"]', 1, 'Taken aback = surprised; opposite = unmoved.', true, '2026-10-24 07:21:31.636', '2026-10-24 07:21:31.636', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The young girl was <u>taken aback</u> by her father''s gift of a car', '["shocked","unmoved","surprised","nonplussed"]', 'Taken aback = surprised; opposite = unmoved.', '{}');
