insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c1etsmfz8dgnyly0ns5784k0j', 'General Mathematics', 'JAMB', null, 2020, null, 'The parabola y² = 8x has its focus at:', null, '["(2, 0)","(0, 2)","(4, 0)","(0, 4)"]', 0, '4a = 8 → a = 2; focus = (2, 0).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The parabola y² = 8x has its focus at:', '["(2, 0)","(0, 2)","(4, 0)","(0, 4)"]', 'Focus = <u>(2, 0)</u>.', '{"bold":[],"italic":[],"underline":["(2, 0)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c1f1ug0w44qbb4z9kx8emiboh', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'When you read loudly while praying Zuhr in one of the rak''at, you are expected to', null, '["repeat your prayer","make a qabli sujud","make a ba''di sujud","recite the qunut."]', 2, 'You should make a ba''di sujud.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When you read loudly while praying Zuhr in one of the rak''at, you are expected to', '["repeat your prayer","make a qabli sujud","<u>make a ba''di sujud</u>","recite the qunut."]', '<u>Make a ba''di sujud</u>.', '{"bold":[],"italic":[],"underline":["make a ba''di sujud"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c1f3inr4mxke0b0zga89l8ot4', 'Chemistry', 'JAMB', null, 1993, null, 'Bronze is an alloy which will react to', null, '["Silver and copper","Silver and gold","Copper and nickel","Copper and tin"]', 3, 'Bronze is an alloy of copper and tin (copper and zinc make brass).', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Bronze is an alloy which will react to', '["Silver and copper","Silver and gold","Copper and nickel","Copper and tin"]', 'Bronze is an alloy of copper and tin (copper and zinc make brass).', '{"bold":[],"italic":[],"underline":["Copper and zinc"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c1f95954-d58d-42e1-8955-18718ddaba79', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. <u>When the chips are down</u>, we will know those who have the courage to stand.', null, '["When we get to a crisis point","In the final analysis","When the blocks are lowered","When we get to the end of the road"]', 0, 'When the chips are down = at a crisis point.', true, '2026-10-24 01:01:48.969', '2026-10-24 01:01:48.969', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. <u>When the chips are down</u>, we will know those who have the courage to stand.', '["<u>When we get to a crisis point</u>","In the final analysis","When the blocks are lowered","When we get to the end of the road"]', '<b>When the chips are down</b> = <b>at a crisis point</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c1ff52yeqkqc3804muq2q4asn', 'Chemistry', 'JAMB', null, 1983, null, 'A gas that can behave as <b>reducing agent</b> towards chlorine and as an <b>oxidizing agent</b> toward hydrogen sulphide is', null, '["O2","NO","SO2","NH3","CO2"]', 2, 'SO2 can be oxidized by Cl2 and can oxidize H2S.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A gas that can behave as <b>reducing agent</b> towards chlorine and as an <b>oxidizing agent</b> toward hydrogen sulphide is', '["O2","NO","SO2","NH3","CO2"]', '<u>SO2</u> can be oxidized by Cl2 and can oxidize H2S.', '{"bold":["reducing agent","oxidizing agent"],"italic":[],"underline":["SO2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c1fgocliq8lfen20zap19r3fi', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Which question paper type of Christian Religious Studies is given to you?', null, '["Green","Purple","Red","Yellow"]', 3, 'The question paper type is Yellow.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which question paper type of Christian Religious Studies is given to you?', '["Green","Purple","Red","<u>Yellow</u>"]', '<u>Yellow</u>.', '{"bold":[],"italic":[],"underline":["Yellow"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c1fnz45djb5yc7j42uk457acn', 'English Language', 'JAMB', null, 2020, null, 'The young lady decided to _____.', null, '["do away with the many advices given by her relatives","reject all the advices given by her relatives","reject all the advice given by her relations","take to all the advices given by her relations"]', 2, 'Advice is uncountable → "advice", not "advices".', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The young lady decided to _____.', '["do away with the many advices given by her relatives","reject all the advices given by her relatives","reject all the advice given by her relations","take to all the advices given by her relations"]', '<u>Reject all the advice</u> — "advice" is uncountable.', '{"bold":[],"italic":[],"underline":["reject all the advice given by her relations"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c1g001n5ktqz4987ghlrj2l6r', 'Christian Religious Studies', 'JAMB', null, 2020, null, '... and I will say to my soul, Soul, you have ample goods laid up for many years; take your ease, eat, drink, be merry ... God''s response to the statement above was that', null, '["his soul was required of him","his soul should be satisfied with his increase","he should lay up more treasures for himself","the servant should enter into the rest of the lord."]', 0, 'God said his soul was required of him.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '... and I will say to my soul, Soul, you have ample goods laid up for many years; take your ease, eat, drink, be merry ... God''s response to the statement above was that', '["<u>his soul was required of him</u>","his soul should be satisfied with his increase","he should lay up more treasures for himself","the servant should enter into the rest of the lord."]', '<u>His soul was required of him</u> (Luke 12:20).', '{"bold":[],"italic":[],"underline":["his soul was required of him"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c1g5kzyz52kkmf7rf475u4xq0', 'Biology', 'JAMB', null, 1994, null, 'In a tropical rain forest, non-epiphytic ferns and fern allies occur as', null, '["middle storey species","upper storey species","shade-loving species","emergent species"]', 2, 'Non-epiphytic ferns are shade-loving species.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In a tropical rain forest, non-epiphytic ferns and fern allies occur as', '["middle storey species","upper storey species","<u>shade-loving species</u>","emergent species"]', '<u>Non-epiphytic ferns are shade-loving species</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c1ge0hpi0ujb8ymm7s9fphqcy', 'Biology', 'JAMB', null, 1985, null, 'Each of the following is an arthropod EXCEPT the', null, '["crab","spider","snail","millipede","cockroach"]', 2, 'A snail is a mollusc, not an arthropod.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Each of the following is an <b>arthropod</b> EXCEPT the', '["crab","spider","<u>snail</u>","millipede","cockroach"]', '<u>A snail is a mollusc</u>, not an arthropod.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c1gfeikla7a5icriiul1s4t61', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Peter teaches that, for being humble, a Christian obtains', null, '["hope","grace","faith","eternity"]', 1, 'God gives grace to the humble.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Peter teaches that, for being humble, a Christian obtains', '["hope","<u>grace</u>","faith","eternity"]', '<u>Grace</u> (1 Peter 5:5).', '{"bold":[],"italic":[],"underline":["grace"],"fillBlanks":[]}');
