insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c1gog43qn8uzfjp4mligfjjsj', 'Biology', 'JAMB', null, 2000, null, 'The factors that determine the distribution of <b>vegetation zones</b> are', null, '["temperature, light, rain and humidity","light, humidity, air and mist","temperature, light, air and humidity","humidity, snow, frost and dew"]', 0, 'Temperature, light, rain, humidity determine vegetation zones.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The factors that determine the distribution of <b>vegetation zones</b> are', '["temperature, light, rain and humidity","light, humidity, air and mist","temperature, light, air and humidity","humidity, snow, frost and dew"]', '<u>Temperature, light, rain, humidity</u>.', '{"bold":["vegetation zones"],"italic":[],"underline":["temperature, light, rain and humidity"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c1h80lkx9vwpdcdo3wii2zh4v', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'According to Ezekiel, the new covenant would involve', null, '["sacrificing oxen","sprinkling clean water upon the people","washing the people with the blood of an animal","erecting an altar."]', 1, 'The new covenant involved sprinkling clean water.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to Ezekiel, the new covenant would involve', '["sacrificing oxen","<u>sprinkling clean water upon the people</u>","washing the people with the blood of an animal","erecting an altar."]', '<u>Sprinkling clean water upon the people</u> (Ezekiel 36:25).', '{"bold":[],"italic":[],"underline":["sprinkling clean water upon the people"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c1hj9zz8q82eu01rncjw6y8o7', 'English Language', 'JAMB', null, 2020, null, 'The teacher did not like _____ the class early.', null, '["us leaving","we leaving","our leaving","us to leave"]', 2, 'Possessive before gerund: "our leaving".', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The teacher did not like _____ the class early.', '["us leaving","we leaving","our leaving","us to leave"]', 'Possessive + gerund: <u>our leaving</u>.', '{"bold":[],"italic":[],"underline":["our leaving"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c1hogel77wdgpftatmkkvftls', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'The greatest domestic problem king David experienced which almost cost him his kingdom was', null, '["the revolt of Absalom against him","his adultery with Bathsheba","the killing of Uriah","the proclamation of Adonijah as king."]', 0, 'Absalom''s revolt was the greatest domestic problem David faced.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The greatest domestic problem king David experienced which almost cost him his kingdom was', '["<u>the revolt of Absalom against him</u>","his adultery with Bathsheba","the killing of Uriah","the proclamation of Adonijah as king."]', '<u>The revolt of Absalom against him</u>.', '{"bold":[],"italic":[],"underline":["the revolt of Absalom against him"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c1htamgl50ncnq20wg5mij073', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'David''s behaviour after Prophet Nathan accused him of murder and adultery showed his', null, '["justification","repentance","greed","righteousness."]', 1, 'David''s behaviour showed repentance.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'David''s behaviour after Prophet Nathan accused him of murder and adultery showed his', '["justification","<u>repentance</u>","greed","righteousness."]', '<u>Repentance</u> (Psalm 51).', '{"bold":[],"italic":[],"underline":["repentance"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c1i3sihrna2bmz09fd8b12pqs', 'English Language', 'JAMB', null, 2020, null, 'When I came in, I _____.', null, '["laid on the floor","lie on the floor","lain on the floor","lay on the floor"]', 3, 'Lay = past tense of "lie" (recline).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When I came in, I _____.', '["laid on the floor","lie on the floor","lain on the floor","lay on the floor"]', '<u>Lay</u> = past of "lie".', '{"bold":[],"italic":[],"underline":["lay on the floor"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c1ice4jr8g7t5pb9aw1lhi5rg', 'Government', 'JAMB', null, 2020, null, 'The emirate system of administration can be likened to a', null, '["unitary system of government","federal system of government","constitutional monarchy","confederal system of government"]', 1, 'The emirate system resembled a federal system.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The emirate system of administration can be likened to a', '["unitary system of government","<u>federal system of government</u>","constitutional monarchy","confederal system of government"]', '<u>Federal system of government</u>.', '{"bold":[],"italic":[],"underline":["federal system of government"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c1ikdtfrplfzr4r4p46xefcxm', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Qur''an 22:31 likens one who assigns partners to Allah to that who had fallen from heaven and was snatched up by', null, '["the angels","spirits","the devil","birds"]', 2, 'He was snatched up by the devil.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Qur''an 22:31 likens one who assigns partners to Allah to that who had fallen from heaven and was snatched up by', '["the angels","spirits","<u>the devil</u>","birds"]', '<u>The devil</u> (Q. 22:31).', '{"bold":[],"italic":[],"underline":["the devil"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c1ivqdtp3oihjo0pastgw198d', 'Biology', 'JAMB', null, 1983, null, 'What is the genetic ratio of the F generation if members of F generation are allowed to self-pollinate?', null, '["1tall: 3short","3 tall: 1 short","1 tall: 1 short","4 shorts: 0 tall","4 tall: 0 short"]', 1, 'The F2 generation ratio is 3 tall : 1 short.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is the genetic ratio of the <b>F generation</b> if members of F generation are allowed to self-pollinate?', '["1tall: 3short","<u>3 tall: 1 short</u>","1 tall: 1 short","4 shorts: 0 tall","4 tall: 0 short"]', 'The F2 generation ratio is <u>3 tall : 1 short</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c1iz0yfszccz1n7a16hz1rplj', 'Physics', 'JAMB', null, 1983, null, 'Which of the following is NOT a vector quantity?', null, '["Force","Altitude","Weight","Displacement","Acceleration"]', 1, 'Altitude has magnitude only (a scalar). Force, weight, displacement and acceleration all have direction.', true, '2026-10-11 21:26:45.728', '2026-10-11 21:26:45.728', null, null, null, 'Which of the following is NOT a vector quantity?', '["Force","Altitude","Weight","Displacement","Acceleration"]', 'Altitude has magnitude only (a scalar). Force, weight, displacement and acceleration all have direction.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c1izg1jnixw10cn33tsi3gaqa', 'Biology', 'JAMB', null, 1993, null, 'A circulatory system that does not allow mixing of oxygenated and de-oxygenated blood in mammalian heart is referred to as', null, '["open","haemocoolic","single","closed"]', 3, 'A closed circulatory system prevents mixing of blood.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A circulatory system that does not allow mixing of oxygenated and de-oxygenated blood in mammalian heart is referred to as', '["open","haemocoolic","single","<u>closed</u>"]', 'A <u>closed circulatory system</u> prevents mixing of blood.', null);
