insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c1r0y9y8pfyg7s26gh0mh0y0y', 'Chemistry', 'JAMB', null, 1996, null, 'The appropriate test paper to use in the above experiment(test of SO2) is moist ______________________', null, '["litmus paper","potassium heptaoxodichromate(IV) paper","lead(II) trioxonitrate(V) paper","Universal indicator paper"]', 1, 'Dichromate paper detects SO2 (turns green).', true, '2026-10-11 07:17:11.699', '2026-10-24 07:31:06.597', null, null, null, 'The appropriate test paper to use in the above experiment is moist', '["litmus paper","potassium heptaoxodichromate(IV) paper","lead(II) trioxonitrate(V) paper","Universal indicator paper"]', '<u>Dichromate paper</u> detects SO2.', '{"bold":[],"italic":[],"underline":["potassium heptaoxodichromate(IV) paper"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c1r2arjvzexlj31f5wbh3fdaz', 'General Mathematics', 'JAMB', null, 2020, null, 'Find remainder when 7⁷ is divided by 5.', null, '["2","3","4","1"]', 1, '7 ≡ 2 mod 5; 2⁷ = 128 ≡ 3 mod 5.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find remainder when 7⁷ is divided by 5.', '["2","3","4","1"]', '7⁷ ≡ 2⁷ = 128 ≡ <u>3</u> mod 5.', '{"bold":[],"italic":[],"underline":["3"],"fillBlanks":[]}');
