insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c1tt37quqg9cx23zx5y6frtr3', 'Biology', 'JAMB', null, 2001, null, 'A freshwater pond may contain', null, '["tadpole, water boatman, leeches and crab","water beetle, shrimps, water snail and water bug","water lily, fish, water scorpion and dragontly larva","pond skater, water lily, shark and mosquito larva"]', 2, 'water lily, fish, water scorpion and dragontly larva is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A freshwater pond may contain', '["tadpole, water boatman, leeches and crab","water beetle, shrimps, water snail and water bug","<u>water lily, fish, water scorpion and dragontly larva</u>","pond skater, water lily, shark and mosquito larva"]', 'water lily, fish, water scorpion and dragontly larva is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c1u1vnmg3il1028ovn39n3wua', 'Biology', 'JAMB', null, 2000, null, 'The production of violet colouration, when dilute Na0H solution is added to a solution of food substance, followed by drops of 1 % CUSO4 solution while making indicates the presence of', null, '["protein","carbohydrates","fats","reducing sugar"]', 0, 'protein is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The production of violet colouration, when dilute Na0H solution is added to a solution of food substance, followed by drops of 1 % CUSO4 solution while making indicates the presence of', '["<u>protein</u>","carbohydrates","fats","reducing sugar"]', 'protein is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c1u29oz2gdpga8gzvfrtd7ge8', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve for y: 43_y = 21_(y+2).', null, '["5","6","7","8"]', 0, '4y + 3 = 2(y+2) + 1 = 2y + 5 → 2y = 2 → y = 1. But y > 4. No solution. Key says 5.', false, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Solve for y: 43_y = 21_(y+2).', '["5","6","7","8"]', '4y + 3 = 2y + 5 → <u>y = 1</u> (invalid, key says 5).', '{"bold":[],"italic":[],"underline":["5"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c1ufgtqredt185eicfbeo2yd1', 'General Mathematics', 'WAEC', null, 2020, null, 'Simplify (3√2 - 2√3)/(3√2 + 2√3) + (3√2 + 2√3)/(3√2 - 2√3).', null, '["8","10","12","14"]', 1, 'Let a = 3√2, b = 2√3; (a-b)/(a+b) + (a+b)/(a-b) = 2(a²+b²)/(a²-b²) = 2(18+12)/(18-12) = 60/6 = 10.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Simplify (3√2 - 2√3)/(3√2 + 2√3) + (3√2 + 2√3)/(3√2 - 2√3).', '["8","10","12","14"]', 'Sum = <u>10</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c1uksz1jxvsgx6gdj0x7ngk9z', 'General Mathematics', 'JAMB', null, 2020, null, 'Find 47 × 36 (mod 8).', null, '["4","5","6","7"]', 0, '47 mod 8 = 7; 36 mod 8 = 4; 7×4 = 28 ≡ 4 mod 8.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find 47 × 36 (mod 8).', '["4","5","6","7"]', '47×36 ≡ 7×4 = 28 ≡ <u>4</u> mod 8.', '{"bold":[],"italic":[],"underline":["4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c1ur8g0t14r6dwmbts3h7wqhi', 'General Mathematics', 'WAEC', null, 2020, null, 'Which is true?', null, '["36 ≡ 1 (mod 7)","36 ≡ 2 (mod 7)","36 ≡ 3 (mod 7)","36 ≡ 4 (mod 7)"]', 0, '36 mod 7 = 1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which is true?', '["36 ≡ 1 (mod 7)","36 ≡ 2 (mod 7)","36 ≡ 3 (mod 7)","36 ≡ 4 (mod 7)"]', '36 ≡ <u>1</u> mod 7.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c1v3ahjc4h6ddmxy1zlc5ze6n', 'Biology', 'JAMB', null, 1989, null, 'If a healthy potted plant is continuously kept in dim light', null, '["the rate of respiration may equal that of photosynthesis","more carbon dioxide and water are taken in","respiration may be halted","the volume of oxygen released increases"]', 0, 'In dim light, respiration may equal photosynthesis.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If a healthy potted plant is continuously kept in dim light', '["<u>the rate of respiration may equal that of photosynthesis</u>","more carbon dioxide and water are taken in","respiration may be halted","the volume of oxygen released increases"]', 'In dim light, <u>respiration may equal photosynthesis</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c1v5c5mii5o8gp86or15ktnrw', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'The Jerusalem wall was rebuilt under the leadership of Nehemiah because', null, '["there were enough materials for the work","the people had the mind to work","all the settlers supported the work","King Cyrus had granted funds for the work."]', 1, 'The people had a mind to work.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Jerusalem wall was rebuilt under the leadership of Nehemiah because', '["there were enough materials for the work","<u>the people had the mind to work</u>","all the settlers supported the work","King Cyrus had granted funds for the work."]', '<u>The people had the mind to work</u> (Nehemiah 4:6).', '{"bold":[],"italic":[],"underline":["the people had the mind to work"],"fillBlanks":[]}');
