insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c1wkjo1lhpf7wdth6jjncegcm', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'In Galatians, Paul said he persecuted the Church of God at first because he', null, '["felt the Church was too fanatical about its faith","was extremely zealous for the tradition of his fathers","thought the Church was a heretical wing of Judaism","believed the Church was turning people away from God"]', 1, 'He was extremely zealous for the tradition of his fathers.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In Galatians, Paul said he persecuted the Church of God at first because he', '["felt the Church was too fanatical about its faith","<u>was extremely zealous for the tradition of his fathers</u>","thought the Church was a heretical wing of Judaism","believed the Church was turning people away from God"]', '<u>Was extremely zealous for the tradition of his fathers</u> (Galatians 1:13-14).', '{"bold":[],"italic":[],"underline":["was extremely zealous for the tradition of his fathers"],"fillBlanks":[]}');
