insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c1wqpxu3sy19ifr5a6m6208gi', 'General Mathematics', 'JAMB', null, 2020, null, 'If y = sin⁻¹√(1-t) and t = cos x, find dy/dx.', null, '["1","-1","1/2","-1/2"]', 0, 'y = sin⁻¹√(1-cos x) = sin⁻¹(√2 sin(x/2)); dy/dx = 1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If y = sin⁻¹√(1-t) and t = cos x, find dy/dx.', '["1","-1","1/2","-1/2"]', 'dy/dx = <u>1</u>.', '{"bold":[],"italic":[],"underline":["1"],"fillBlanks":[]}');
