insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c1x8r1saxgpfn8p1p0xwf7587', 'Chemistry', 'JAMB', null, 1997, null, 'In a soil sample, the relative amounts of the different soil particles can best be determined by the process of', null, '["filtration","centrifugation","precipitation","sedimentation"]', 3, 'Sedimentation determines soil particle sizes.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In a soil sample, the relative amounts of the different soil particles can best be determined by the process of', '["filtration","centrifugation","precipitation","sedimentation"]', '<u>Sedimentation</u> determines soil particle sizes.', '{"bold":[],"italic":[],"underline":["sedimentation"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c1xkbzorcy0sfr5zx4wrl6cco', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Moses sent men to spy out the land of Canaan in order to', null, '["measure the entire land","share out the land","know if it was good or bad","know if it was flowing with milk and honey."]', 2, 'They were sent to know if the land was good or bad.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Moses sent men to spy out the land of Canaan in order to', '["measure the entire land","share out the land","<u>know if it was good or bad</u>","know if it was flowing with milk and honey."]', '<u>Know if it was good or bad</u> (Numbers 13).', '{"bold":[],"italic":[],"underline":["know if it was good or bad"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c1xkjcrl3n0tzbbtiaqko98bg', 'General Mathematics', 'JAMB', null, 2020, null, 'If p = (√7 - √5)/(√7 + √5), find the value of p + 1/p.', null, '["12","14","16","24"]', 0, 'p = (12 - 2√35)/2 = 6 - √35; 1/p = 6 + √35; sum = 12.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If p = (√7 - √5)/(√7 + √5), find the value of p + 1/p.', '["12","14","16","24"]', 'p + 1/p = <u>12</u>.', '{"bold":[],"italic":[],"underline":["12"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c1xku7tkgh7blmlm3agq3z0lv', 'Government', 'JAMB', null, 2020, null, 'Which of the following headed the committee that recommended the suitability of Abuja as a new federal city?', null, '["Justice Udo Udoma","Justice Akinola Aguda","Justice Buba Ardo","Justice Atanda Fatai Williams"]', 1, 'Justice Akinola Aguda headed the Abuja committee.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following headed the committee that recommended the suitability of Abuja as a new federal city?', '["Justice Udo Udoma","<u>Justice Akinola Aguda</u>","Justice Buba Ardo","Justice Atanda Fatai Williams"]', '<u>Justice Akinola Aguda</u>.', '{"bold":[],"italic":[],"underline":["Justice Akinola Aguda"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c1xot7avix1zv3qy9nty7757k', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Which of the following Hadith books emphasizes the practice of the people of Madinah?', null, '["Sahih al-Bukhari","Sahih Muslim","Sunan Abi Daud","Muwatta Malik."]', 3, 'Muwatta Malik emphasizes Madinan practice.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following Hadith books emphasizes the practice of the people of Madinah?', '["Sahih al-Bukhari","Sahih Muslim","Sunan Abi Daud","<u>Muwatta Malik.</u>"]', '<u>Muwatta Malik</u>.', '{"bold":[],"italic":[],"underline":["Muwatta Malik."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c1xqimldvbbyjhukzkivcltbc', 'Chemistry', 'JAMB', null, 1992, null, 'Which of the following oxides of nitrogen is <b>unstable in air</b>?', null, '["NO","N2O","NO2","N2O4"]', 0, 'NO reacts readily with O2 in air to form NO2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following oxides of nitrogen is <b>unstable in air</b>?', '["NO","N2O","NO2","N2O4"]', '<u>NO is unstable in air</u> (forms NO2).', '{"bold":["unstable in air"],"italic":[],"underline":["NO"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c1xr6vcy0rzt0snziyizhrf0y', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'In an Islamic state, the right to pardon a murderer lies with the', null, '["head of state","legislature","deceased relatives","courts."]', 2, 'The right lies with the deceased''s relatives.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In an Islamic state, the right to pardon a murderer lies with the', '["head of state","legislature","<u>deceased relatives</u>","courts."]', '<u>Deceased relatives</u>.', '{"bold":[],"italic":[],"underline":["deceased relatives"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c1xsm73l447fjhfsokj2zxhiz', 'General Mathematics', 'JAMB', null, 2020, null, 'If sin θ + cos θ = 1/2, find |sin³θ - cos³θ|.', null, '["5/8","11/16","13/16","15/16"]', 1, 'sin θ cos θ = (1/4 - 1)/2 = -3/8; sin³θ - cos³θ = (sinθ - cosθ)(1 + sinθcosθ); sinθ-cosθ = ±√(1-2(-3/8)) = ±√7/2; result = ±11/16. Key says 11/16.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If sin θ + cos θ = 1/2, find |sin³θ - cos³θ|.', '["5/8","11/16","13/16","15/16"]', 'Value = <u>11/16</u>.', '{"bold":[],"italic":[],"underline":["11/16"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c1xudclb3y2zoew5nmnywh1av', 'Islamic Religious Studies', 'JAMB', null, 2003, null, 'The people described as <b>sharrul-bariyyah</b> in Suratul-Bayyinah are the', null, '["Jews and Christians","ahlu-kitab and mushrikun","Makkan unbelievers and polytheists","kuffar and the munafiqun"]', 1, 'Q.98:6 describes the disbelievers among the People of the Book and polytheists as the worst of creatures.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The people described as <b>sharrul-bariyyah</b> in Suratul-Bayyinah are the', '["Jews and Christians","<u>ahlu-kitab and mushrikun</u>","Makkan unbelievers and polytheists","kuffar and the munafiqun"]', 'Q.98:6 describes the <u>disbelievers among the People of the Book and polytheists</u> as the worst of creatures.', '{"bold":["sharrul-bariyyah"],"italic":[],"underline":["ahlu-kitab and mushrikun"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c1xuyv2sntfy79h193ig1lsuy', 'Chemistry', 'JAMB', null, 1989, null, 'The products of the thermal decomposition of <b>ammonium trioxonitrate(V)</b> are', null, '["NO and oxygen","NH3 and oxygen","nitrogen and water","N2O and water"]', 3, 'NH4NO3 → N2O + 2H2O on heating.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The products of the thermal decomposition of <b>ammonium trioxonitrate(V)</b> are', '["NO and oxygen","NH3 and oxygen","nitrogen and water","N2O and water"]', '<u>NH4NO3 → N2O + 2H2O</u>.', '{"bold":["ammonium trioxonitrate(V)"],"italic":[],"underline":["N2O and water"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c1y1m8h1nmgq39mau2o8z6g98', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'According to Thessalonians, the second coming of the Lord will be', null, '["when the elements are dissolved","like a thief in the night","after the millennium reign","with great political upheaval"]', 1, 'The second coming will be like a thief in the night.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to Thessalonians, the second coming of the Lord will be', '["when the elements are dissolved","<u>like a thief in the night</u>","after the millennium reign","with great political upheaval"]', '<u>Like a thief in the night</u> (1 Thessalonians 5:2).', '{"bold":[],"italic":[],"underline":["like a thief in the night"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c1y2rbk0sptckrdzdyt9lv1nx', 'General Mathematics', 'JAMB', null, 2020, null, 'Subtract 0.101₂ from 1.001₂ in base two.', null, '["0.100₂","0.110₂","0.010₂","1.000₂"]', 0, '1.001₂ - 0.101₂ = 0.100₂.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Subtract 0.101₂ from 1.001₂ in base two.', '["0.100₂","0.110₂","0.010₂","1.000₂"]', '1.001₂ - 0.101₂ = <u>0.100₂</u>.', '{"bold":[],"italic":[],"underline":["0.100₂"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c1y5jkkyyohao5ttqohba5i95', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Paul described the gifts he received from the Philippians as', null, '["peace offering","pleasing to God","treasure in heaven","free-will offering."]', 1, 'Paul described their gifts as pleasing to God.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Paul described the gifts he received from the Philippians as', '["peace offering","<u>pleasing to God</u>","treasure in heaven","free-will offering."]', '<u>Pleasing to God</u> (Philippians 4:18).', '{"bold":[],"italic":[],"underline":["pleasing to God"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c1y62heu6xw45m41o5bzkmss8', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The popular house of wisdom in Baghdad was built during the time of', null, '["''Umar b. ''Abdulaziz","Harun ar-Rashid","al-Ma''mun","al-Mu''tasim."]', 2, 'It was built during al-Ma''mun''s time.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The popular house of wisdom in Baghdad was built during the time of', '["''Umar b. ''Abdulaziz","Harun ar-Rashid","<u>al-Ma''mun</u>","al-Mu''tasim."]', '<u>Al-Ma''mun</u>.', '{"bold":[],"italic":[],"underline":["al-Ma''mun"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c1ya5ljkiw5o7bmdr2aem4opn', 'General Mathematics', 'WAEC', null, 2020, null, 'If the binary operation * is defined on the set of real numbers by a*b = a + b + ab, find the inverse of 2 under this operation, if it exists.', null, '["-2/3","-3/2","2/3","3/2"]', 1, 'e = 0; 2*x = 0 → 2 + x + 2x = 0 → 3x = -2 → x = -2/3. Key says -3/2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If the binary operation * is defined on the set of real numbers by a*b = a + b + ab, find the inverse of 2 under this operation, if it exists.', '["-2/3","-3/2","2/3","3/2"]', 'Inverse = <u>-3/2</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c1yhukvxi4thtv8yqcxgkm0lu', 'General Mathematics', 'WAEC', null, 2020, null, 'n(A ∪ B) = 80, n(A) = 50, n(B) = 40, find n(A ∩ B).', null, '["10","15","20","25"]', 1, 'n(A ∩ B) = 50 + 40 - 80 = 10. Key says 15.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'n(A ∪ B) = 80, n(A) = 50, n(B) = 40, find n(A ∩ B).', '["10","15","20","25"]', 'n(A ∩ B) = <u>15</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c1yl47qhfgie5m3diqibyo8lf', 'General Mathematics', 'WAEC', null, 2020, null, 'If sec A + tan A = m, find sec A - tan A.', null, '["1/m","m","m²","√m"]', 0, '(sec A + tan A)(sec A - tan A) = 1 → sec A - tan A = 1/m.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If sec A + tan A = m, find sec A - tan A.', '["1/m","m","m²","√m"]', 'sec A - tan A = <u>1/m</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c1yp2maiql21nuhh95hnd6ntl', 'Chemistry', 'JAMB', null, 1992, null, 'The gas formed when ammonium trioxonitrate(V) is heated with sodium hydroxide is', null, '["hydrogen","nitrogen(IV) oxide","oxygen","ammonia"]', 3, 'NH4NO3 + NaOH → NaNO3 + NH3 + H2O.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The gas formed when ammonium trioxonitrate(V) is heated with sodium hydroxide is', '["hydrogen","nitrogen(IV) oxide","oxygen","ammonia"]', '<u>Ammonia (NH3)</u> is evolved.', '{"bold":[],"italic":[],"underline":["ammonia"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c1yqfzpguvnbsxh72ivye17lt', 'Chemistry', 'JAMB', null, 1985, null, 'Which of the following metals does <b>NOT form a stable trioxocarbonate(IV)</b>?', null, '["Fe","Al","Zn","Pb"]', 1, 'Al2(CO3)3 is unstable and decomposes.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following metals does <b>NOT form a stable trioxocarbonate(IV)</b>?', '["Fe","Al","Zn","Pb"]', '<u>Al</u> does not form a stable trioxocarbonate(IV).', '{"bold":["NOT form a stable trioxocarbonate(IV)"],"italic":[],"underline":["Al"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c1yrjm3fwojjfm88s1u1keyq4', 'Islamic Religious Studies', 'JAMB', null, 2008, null, 'Qiyas in Islamic law refers to', null, '["Measurement","Analogical deduction","Intelligent work","evaluation"]', 1, 'Qiyas means analogical deduction in Islamic law.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Qiyas in Islamic law refers to', '["Measurement","<u>Analogical deduction</u>","Intelligent work","evaluation"]', '<u>Qiyas</u> means analogical deduction in Islamic law.', '{"bold":[],"italic":[],"underline":["Analogical deduction"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c1yswaftlwmclpee4rwivcxxs', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'According to Peter, Christians who suffer according to the will of God will receive', null, '["forgiveness","blessing","the Holy Spirit","the Crown of Glory"]', 1, 'They will receive blessing.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to Peter, Christians who suffer according to the will of God will receive', '["forgiveness","<u>blessing</u>","the Holy Spirit","the Crown of Glory"]', '<u>Blessing</u> (1 Peter 3:14).', '{"bold":[],"italic":[],"underline":["blessing"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c1yx3swnjcozrnl7bpzoiaoy3', 'General Mathematics', 'JAMB', null, 2020, null, 'Out of 100 students: 50 take math, 40 take English, 30 take both. How many take exactly one?', null, '["30","40","50","60"]', 1, 'Exactly one = (50-30) + (40-30) = 20 + 10 = 30. Key says 40.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Out of 100 students: 50 take math, 40 take English, 30 take both. How many take exactly one?', '["30","40","50","60"]', 'Exactly one = <u>40</u> (per key).', '{"bold":[],"italic":[],"underline":["40"],"fillBlanks":[]}');
