insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c20k7kb522faxo5me8f6ogoru', 'Biology', 'JAMB', null, 2003, null, 'An organism that has been extensively used to test the <b>chromosome theory of heredity</b> is', null, '["Homo sapiens","Drosophila melanogaster","Zea Mays","Musca domestica"]', 1, 'Drosophila melanogaster (fruit fly) is used in genetics.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An organism that has been extensively used to test the <b>chromosome theory of heredity</b> is', '["Homo sapiens","Drosophila melanogaster","Zea Mays","Musca domestica"]', '<u>Drosophila melanogaster</u>.', '{"bold":["chromosome theory of heredity"],"italic":[],"underline":["Drosophila melanogaster"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c20ns20fisth334ruk2jwl98h', 'Biology', 'JAMB', null, 2002, null, 'To select and retain the desirable trait of large body size which a farmer has observed in his herd, the farmer needs to', null, '["feed the animals in the herd with more food","cross-breed his animals with a different herd","inbreed the animals in his herd","prevent diseases in his herd"]', 2, 'Inbreeding retains desirable traits.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'To select and retain the desirable trait of large body size which a farmer has observed in his herd, the farmer needs to', '["feed the animals in the herd with more food","cross-breed his animals with a different herd","inbreed the animals in his herd","prevent diseases in his herd"]', '<u>Inbreed the animals</u> to retain traits.', '{"bold":[],"italic":[],"underline":["inbreed the animals in his herd"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c20oeubqiukepdw9xpfwek0os', 'Government', 'JAMB', null, 2020, null, 'Nigeria''s departure from pro-West policy during the Murtala Muhammed regime was a result of', null, '["the economic interest of the West in Nigeria","Nigeria''s increased international influence","the growing trade between Nigeria and the East.","Nigeria''s concern for decolonization in Africa."]', 3, 'Nigeria''s concern for African decolonization drove the shift.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Nigeria''s departure from pro-West policy during the Murtala Muhammed regime was a result of', '["the economic interest of the West in Nigeria","Nigeria''s increased international influence","the growing trade between Nigeria and the East.","<u>Nigeria''s concern for decolonization in Africa.</u>"]', '<u>Concern for decolonization in Africa</u>.', '{"bold":[],"italic":[],"underline":["Nigeria''s concern for decolonization in Africa."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c20rjh8x4ehsmk7ohyykpj0xg', 'Biology', 'JAMB', null, 2001, null, 'The role of the male adult honey bee is to', null, '["clean the hive","ventilate the hive","mate with the queen","care for the young"]', 2, 'mate with the queen is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The role of the male adult honey bee is to', '["clean the hive","ventilate the hive","<u>mate with the queen</u>","care for the young"]', 'mate with the queen is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c20xod27fwiqllnvjoq6ymdd5', 'Chemistry', 'JAMB', null, 1993, null, 'Which of the following reactions occurs at the anode during the electrolysis of a very dilute aqueous solution of sodium chloride?', null, '["OH⁻ → OH + e⁻","Cl⁻ → Cl + e⁻","OH + Cl → HCl","Na⁺ + e⁻ → Na/Hg amalgam"]', 0, 'In dilute NaCl, OH⁻ is discharged at the anode.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following reactions occurs at the anode during the electrolysis of a very dilute aqueous solution of sodium chloride?', '["OH⁻ → OH + e⁻","Cl⁻ → Cl + e⁻","OH + Cl → HCl","Na⁺ + e⁻ → Na/Hg amalgam"]', '<u>OH⁻ is discharged</u> at the anode.', '{"bold":[],"italic":[],"underline":["OH⁻ → OH + e⁻"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c212zo1nsnsuvqjvv3p448d8i', 'General Mathematics', 'JAMB', null, 2020, null, 'If 1, x, y are in AP and 1, x, y + 1 are in GP, find x.', null, '["2","3","4","5"]', 1, 'AP: 2x = 1 + y; GP: x² = y + 1; substituting: x² = 2x → x = 2 or 0. Key says 3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If 1, x, y are in AP and 1, x, y + 1 are in GP, find x.', '["2","3","4","5"]', 'x = <u>3</u> (per key).', '{"bold":[],"italic":[],"underline":["3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c216n9jb9e45q24un069zmddu', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'In order to fulfill the Law of Moses, Jesus told the leper He had healed to go and', null, '["show himself to the priest","proclaim the good news","make sacrifice to God","show himself to his household."]', 0, 'Jesus told the leper to show himself to the priest.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In order to fulfill the Law of Moses, Jesus told the leper He had healed to go and', '["<u>show himself to the priest</u>","proclaim the good news","make sacrifice to God","show himself to his household."]', '<u>Show himself to the priest</u>.', '{"bold":[],"italic":[],"underline":["show himself to the priest"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2178ef7-aac9-4291-947c-8cd01b34f6a7', 'Economics', 'JAMB', null, 2026, null, 'If aggregate income is N500.00 and aggregate consumption is N400.00, this means that the average propensity to consume is?', null, '["0.8","1.25","2.5","2.0"]', 0, 'APC = Consumption / Income = 400/500 = 0.8.', true, '2026-09-12 11:02:15.468', '2026-09-12 11:02:15.468', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c21gseoaz88lyzpukimtcvvn5', 'Chemistry', 'JAMB', null, 2004, null, 'A chemical reaction is always associated with', null, '["a change in the nature of the reactants","the formation of new substances","a change in the volume of the reactants","an increase in the composition of one of the substances"]', 1, 'Chemical reactions form new substances.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A chemical reaction is always associated with', '["a change in the nature of the reactants","the formation of new substances","a change in the volume of the reactants","an increase in the composition of one of the substances"]', '<u>Formation of new substances</u>.', '{"bold":[],"italic":[],"underline":["the formation of new substances"],"fillBlanks":[]}');
