insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c22m0c14ed1ivecsa6911bhxa', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the mean deviation about the median for 2, 4, 6, 8, 10.', null, '["2.4","2.8","3.2","3.6"]', 0, 'Median = 6; deviations = 4,2,0,2,4 → MD = 12/5 = 2.4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the mean deviation about the median for 2, 4, 6, 8, 10.', '["2.4","2.8","3.2","3.6"]', 'MD = <u>2.4</u>.', null);
