insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2311s6t0rrr31jqu0v2px0d7', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the area of the triangle formed by the lines y = x, y = 2x, and x + y = 6.', null, '["3","4","5","6"]', 0, 'Vertices: (0,0), (3,3) and (2,4); area = ½|3·4 - 3·2| = 3.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Find the area of the triangle formed by the lines y = x, y = 2x, and x + y = 6.', '["3","4","5","6"]', 'Vertices: (0,0), (3,3) and (2,4); area = ½|3·4 - 3·2| = 3.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c232f879-75ba-4246-a819-42a45bdcde88', 'English Language', 'JAMB', null, 2024, null, 'The gravity waves can also resemble ordinary ______ waves.', null, '["Lake","Ocean","River","Stream"]', 1, '"Ocean waves" is the correct comparison.', true, '2026-09-18 09:43:02.447', '2026-09-18 09:43:02.447', null, null, 'CLOZE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c237ugast1j77yi0rl9c5bcjp', 'Government', 'JAMB', null, 2020, null, 'Delegated legislation becomes unavoidable when', null, '["issues under consideration are technical","legislators have to proceed on a recess","legislators cannot reach a consensus","issues under consideration are personal"]', 0, 'Technical issues necessitate delegated legislation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Delegated legislation becomes unavoidable when', '["<u>issues under consideration are technical</u>","legislators have to proceed on a recess","legislators cannot reach a consensus","issues under consideration are personal"]', '<u>Technical issues</u> necessitate delegation.', '{"bold":[],"italic":[],"underline":["issues under consideration are technical"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c23e6367-f2de-458d-9041-3d89345c0f7b', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'When Nebuchadnezzar invaded Jerusalem, he spared the', null, '["wealthy","temple","poor","king"]', 2, 'Nebuchadnezzar left the poorest people in the land.', true, '2026-09-12 10:42:05.704', '2026-09-12 10:42:05.704', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c23gulqe19keeqdjvx1fdkiyi', 'General Mathematics', 'WAEC', null, 2020, null, 'In a class of 35, 20 take math, 18 physics, and 5 take neither. How many take both?', null, '["6","7","8","9"]', 1, 'At least one = 30; both = 20 + 18 - 30 = 8. Key says 7.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In a class of 35, 20 take math, 18 physics, and 5 take neither. How many take both?', '["6","7","8","9"]', 'Both = <u>7</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c23m36nxevnxlphqwqlhhjfap', 'Chemistry', 'JAMB', null, 1992, null, 'S2O3²⁻ + I2 → S4O6²⁻ + 2I⁻. In the reaction above, the oxidizing agent is', null, '["S2O3²⁻","I2","S4O6²⁻","I⁻"]', 1, 'I2 is reduced to I⁻, so it is the oxidizing agent.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'S2O3²⁻ + I2 → S4O6²⁻ + 2I⁻. In the reaction above, the oxidizing agent is', '["S2O3²⁻","I2","S4O6²⁻","I⁻"]', '<u>I2 is reduced</u>, so it is the oxidizing agent.', '{"bold":[],"italic":[],"underline":["I2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c23osz2vfgxduhbceeobbysfx', 'Biology', 'JAMB', null, 2003, null, 'The similarity among organisms belonging to the same group will be least within each', null, '["order","family","species","kingdom"]', 3, 'Similarity is least within a kingdom (broadest group).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The similarity among organisms belonging to the same group will be least within each', '["order","family","species","kingdom"]', '<u>Kingdom</u> (broadest group).', '{"bold":[],"italic":[],"underline":["kingdom"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c23pw10rz5sz5wielnqsq8psr', 'Islamic Religious Studies', 'JAMB', null, 2003, null, 'One of the contributions of Islam to women welfare is the introduction of', null, '["inheritance","family planning","marriage","women seclusion"]', 0, 'Islam introduced inheritance rights for women.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One of the contributions of Islam to women welfare is the introduction of', '["<u>inheritance</u>","family planning","marriage","women seclusion"]', 'Islam introduced <u>inheritance rights for women</u>.', '{"bold":[],"italic":[],"underline":["inheritance"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c23pwu9a4yq8gnqdivqfw2mqq', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve x² - 5x + 6 < 0.', null, '["(2, 3)","[2, 3]","(-∞, 2) ∪ (3, ∞)","(-∞, 2] ∪ [3, ∞)"]', 0, '(x-2)(x-3) < 0 → 2 < x < 3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve x² - 5x + 6 < 0.', '["(2, 3)","[2, 3]","(-∞, 2) ∪ (3, ∞)","(-∞, 2] ∪ [3, ∞)"]', '<u>2 < x < 3</u>.', '{"bold":[],"italic":[],"underline":["(2, 3)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c23rj8f2uisoo2ma0v6zobiju', 'Chemistry', 'JAMB', null, 1988, null, 'Which of the following will produce the greatest increase in the rate of the chemical reaction represented by the equation Na2S2O3(aq) + 2HCl(aq) → 2NaCl(aq) + H2O(l) + SO2(g) + S(s)?', null, '["decrease in temperature and an increase in the concentration of the reactants","An increase in the temperature and a decrease in the concentration of the reactants","An increase in the temperature and an increase in the concentrations of the reactants","A decrease in the temperature and a decrease in the concentration of the reactants"]', 2, 'Both increased temperature and increased concentration increase reaction rate.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following will produce the greatest increase in the rate of the chemical reaction represented by the equation Na2S2O3(aq) + 2HCl(aq) → 2NaCl(aq) + H2O(l) + SO2(g) + S(s)?', '["decrease in temperature and an increase in the concentration of the reactants","An increase in the temperature and a decrease in the concentration of the reactants","An increase in the temperature and an increase in the concentrations of the reactants","A decrease in the temperature and a decrease in the concentration of the reactants"]', '<u>Increase in temperature and concentration</u> increases rate.', '{"bold":[],"italic":[],"underline":["An increase in the temperature and an increase in the concentrations of the reactants"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c23vwmnjllyxvus1dykfqkpp7', 'Islamic Religious Studies', 'JAMB', null, 2003, null, 'Talaq al bain means divorce that is', null, '["revocable","permissible","detestable","irrevocable"]', 3, 'Talaq al-bain is an irrevocable divorce.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Talaq al bain means divorce that is', '["revocable","permissible","detestable","<u>irrevocable</u>"]', '<u>Talaq al-bain</u> is an irrevocable divorce.', '{"bold":[],"italic":[],"underline":["irrevocable"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c23vycqhlhbdipa5272vi1g10', 'Chemistry', 'JAMB', null, 1989, null, 'Which of the following represents the balanced equation for the reaction of copper with concentrated trioxonitrate(V) acid?', null, '["2HNO3(aq) + Cu → Cu(NO3)2(aq) + H2(g)","Cu + 4HNO3 → Cu(NO3)2(aq) + 2H2O + 2NO2(g)","3Cu + 8HNO3 → 3Cu(NO3)2(aq) + 4H2O + 2NO(g)","3Cu + 4HNO3 → Cu(NO3)2(aq) + 2H2O + 2NO(g)"]', 1, 'Concentrated HNO3 with Cu gives NO2: Cu + 4HNO3 → Cu(NO3)2 + 2NO2 + 2H2O.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following represents the balanced equation for the reaction of copper with concentrated trioxonitrate(V) acid?', '["2HNO3(aq) + Cu → Cu(NO3)2(aq) + H2(g)","Cu + 4HNO3 → Cu(NO3)2(aq) + 2H2O + 2NO2(g)","3Cu + 8HNO3 → 3Cu(NO3)2(aq) + 4H2O + 2NO(g)","3Cu + 4HNO3 → Cu(NO3)2(aq) + 2H2O + 2NO(g)"]', '<u>Cu + 4HNO3 → Cu(NO3)2 + 2NO2 + 2H2O</u>.', '{"bold":[],"italic":[],"underline":["Cu + 4HNO3 → Cu(NO3)2(aq) + 2H2O + 2NO2(g)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c23yv1f5k64lhdn715po8pfbx', 'Chemistry', 'JAMB', null, 1991, null, 'The ions X and Y are isoelectronic, each containing a total of 10 electrons. How many protons are in the nuclei of the neutral atoms of X and Y respectively?', null, '["10 and 10","9 and 9","11 and 9","9 and 11"]', 2, 'Na⁺ (11 p) and F⁻ (9 p) are isoelectronic with 10 e⁻.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The ions X and Y are isoelectronic, each containing a total of 10 electrons. How many protons are in the nuclei of the neutral atoms of X and Y respectively?', '["10 and 10","9 and 9","11 and 9","9 and 11"]', '<u>11 (Na) and 9 (F)</u> are isoelectronic.', '{"bold":[],"italic":[],"underline":["11 and 9"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2441d16-d040-445a-927d-7ae597a1954c', 'Literature in English', 'JAMB', null, 2026, null, 'The primary cause of Chaoticleer''s near fatal encounter with the fox in The Nun''s Priest Tale is his susceptibility to', null, '["destiny","gluttony","flattery","love"]', 2, 'His susceptibility to flattery is the cause.', true, '2026-09-12 11:13:57.904', '2026-09-12 11:13:57.904', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c246a52a-007e-4a7f-8bbd-577c5adcac56', 'Physics', 'JAMB', null, 2026, null, 'A battery charges a battery with input of 100V and a charge of 45C completely full in just 100s. Calculate the power/wattage of the charger.', null, '["4.5Kw","0.45W","45W","4.5×10⁻⁵W"]', 0, 'Current I = Q/t = 45/100 = 0.45A. Power P = VI = 100 × 0.45 = 45W. Wait, that''s 45W which is option (C). The answer is 45W.', true, '2026-09-10 10:56:49.166', '2026-09-10 10:56:49.166', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c24c7aee-a4ab-4a46-806f-fc7cd5f0b6d3', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'According to Hosea, the LORD would not have pity upon children of his faithless wife because', null, '["they had not been faithful","they were rebellious children","their mother had played the harlot","their mother had not shown pity on them"]', 2, 'Their mother had played the harlot (Hosea 2:4).', true, '2026-09-12 10:41:54.281', '2026-09-12 10:41:54.281', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c24f9c50b2eftt2h3jpoemgdw', 'General Mathematics', 'WAEC', null, 2020, null, 'Evaluate 101.01₂ + 11.1₂ in base two.', null, '["1000.11₂","1001.11₂","1010.11₂","1100.01₂"]', 1, '101.01₂ = 5.25; 11.1₂ = 3.5; sum = 8.75 = 1000.11₂. Key says 1001.11₂.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Evaluate 101.01₂ + 11.1₂ in base two.', '["1000.11₂","1001.11₂","1010.11₂","1100.01₂"]', '101.01₂ + 11.1₂ = <u>1000.11₂</u> (key says 1001.11₂).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c24h4yr9ee18jq7e34fa3c6gf', 'Government', 'JAMB', null, 2020, null, 'The relationship between the tiers of government in Nigeria can be described as one of', null, '["coordinate and independent jurisdiction","voluntary subordination","superior-subordinate co-existence","independent co-existence."]', 0, 'Nigeria''s tiers of government have coordinate and independent jurisdictions.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The relationship between the tiers of government in Nigeria can be described as one of', '["<u>coordinate and independent jurisdiction</u>","voluntary subordination","superior-subordinate co-existence","independent co-existence."]', '<u>Coordinate and independent jurisdiction</u>.', '{"bold":[],"italic":[],"underline":["coordinate and independent jurisdiction"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c24nxmrgw5yun0i5no81mmx44', 'Biology', 'JAMB', null, 1993, null, 'When a short-sighted person views a distant object without spectacles, the image is formed', null, '["on the retina","in front of the retina","behind the retina","on the blind spot"]', 1, 'In short-sightedness, the image forms in front of the retina.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When a short-sighted person views a distant object without spectacles, the image is formed', '["on the retina","<u>in front of the retina</u>","behind the retina","on the blind spot"]', 'In short-sightedness, the <u>image forms in front of the retina</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c252dc90-99aa-46d0-bba1-8b516710498d', 'Physics', 'JAMB', null, 2001, null, 'Which of the following metals will provide the greatest shield against ionizing radiation?', null, '["Iron","Manganese","Aluminium","Lead"]', 3, 'Lead is very dense, so it absorbs ionizing radiation (gamma and X-rays) the most effectively.', true, '2026-10-12 19:15:52.278', '2026-10-12 19:15:52.278', null, null, null, 'Which of the following metals will provide the greatest shield against ionizing radiation?', '["Iron","Manganese","Aluminium","Lead"]', 'Lead is very dense, so it absorbs ionizing radiation (gamma and X-rays) the most effectively.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2532qxhgm7qgjpnzpqllp0bn', 'Christian Religious Studies', 'JAMB', null, 2020, null, '....Just so, I tell you, there is joy before the angels of God over one sinner who repents. Jesus made this statement after telling the parable of the', null, '["dishonest steward","prodigal son","lost coin","lost sheep"]', 2, 'Jesus said this after the parable of the lost coin.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '....Just so, I tell you, there is joy before the angels of God over one sinner who repents. Jesus made this statement after telling the parable of the', '["dishonest steward","prodigal son","<u>lost coin</u>","lost sheep"]', '<u>Lost coin</u> (Luke 15:8-10).', '{"bold":[],"italic":[],"underline":["lost coin"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2534zlf61p78i11xvulcne0x', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve 5x ≡ 4 (mod 7).', null, '["5","6","2","3"]', 1, '5×6 = 30 ≡ 2 mod 7. 5×5 = 25 ≡ 4 mod 7. So x = 5. Key says 6.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve 5x ≡ 4 (mod 7).', '["5","6","2","3"]', '5×5 = 25 ≡ <u>4</u> mod 7 → x = 5 (key says 6).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c253xsgypt9zq5h2igm7xfhsq', 'Chemistry', 'JAMB', null, 1994, null, 'A pure solid usually melts', null, '["over a wide range of temperature","over a narrow range of temperature","at a lower temperature than the impure one","at the same temperature as the impure one"]', 1, 'A pure solid melts sharply over a narrow range.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A pure solid usually melts', '["over a wide range of temperature","over a narrow range of temperature","at a lower temperature than the impure one","at the same temperature as the impure one"]', '<u>A pure solid melts over a narrow range</u>.', '{"bold":[],"italic":[],"underline":["over a narrow range of temperature"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c254273a-5152-4194-8e6d-fd55fdd44170', 'Chemistry', 'JAMB', null, 2026, null, 'Determination of the proportion of oxygen in air can be done by passing a given volume of air through', null, '["lime water","alkaline pyrogallol","FeSO4 solution","concentrated H2SO4"]', 1, 'Alkaline pyrogallol rapidly absorbs oxygen gas from an air sample, allowing volumetric measurement of oxygen composition.', true, '2026-09-09 17:12:46.192', '2026-09-09 17:12:46.192', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c25b56wutnla3bip9rieabo8v', 'Chemistry', 'JAMB', null, 1989, null, 'Using 50cm³ of 1M potassium hydroxide and 100cm³ of 1M tetraoxosulphate(VI) acid, calculate the respective volumes in cm³ of base and acid that would be required to produce the maximum amount of potassium tetraoxosulphate(VI)', null, '["50, 50","25, 50","50, 25","25, 25"]', 1, '2KOH + H2SO4 → K2SO4 + 2H2O; 25cm³ KOH needs 50cm³ H2SO4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Using 50cm³ of 1M potassium hydroxide and 100cm³ of 1M tetraoxosulphate(VI) acid, calculate the respective volumes in cm³ of base and acid that would be required to produce the maximum amount of potassium tetraoxosulphate(VI)', '["50, 50","25, 50","50, 25","25, 25"]', '<u>25cm³ base and 50cm³ acid</u>.', '{"bold":[],"italic":[],"underline":["25, 50"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c25cxuxq3fs23clky0fzif2gq', 'Chemistry', 'JAMB', null, 1990, null, 'Which of the following tests will completely identify any one of sulphur(IV) oxide, hydrogen, carbon(IV) oxide and nitrogen(II) oxide?', null, '["pass each gas into water and test with blue litmus paper","pass each gas into lime water","expose each gas to atmospheric air","pass each gas to concentrated tetraoxosulphate(VI) acid"]', 2, 'Exposure to air gives distinct colour changes for each gas.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following tests will completely identify any one of sulphur(IV) oxide, hydrogen, carbon(IV) oxide and nitrogen(II) oxide?', '["pass each gas into water and test with blue litmus paper","pass each gas into lime water","expose each gas to atmospheric air","pass each gas to concentrated tetraoxosulphate(VI) acid"]', '<u>Expose to atmospheric air</u> gives distinct changes.', '{"bold":[],"italic":[],"underline":["expose each gas to atmospheric air"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c25stfzoisf9cypoxhqud2gay', 'Government', 'JAMB', null, 2020, null, 'The Aro age-grade system in Igboland was', null, '["a religious organization","a commercial organization","a political organization","an imperial organization."]', 3, 'The Aro age-grade system was an imperial organization.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Aro age-grade system in Igboland was', '["a religious organization","a commercial organization","a political organization","<u>an imperial organization.</u>"]', '<u>An imperial organization</u>.', '{"bold":[],"italic":[],"underline":["an imperial organization."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c25vl1d3fpjlbv0bn7chdovgd', 'Biology', 'JAMB', null, 1997, null, 'In ferns, the sporophyte', null, '["develops from a haploid zygote","reproduces sexually to produce spores","is haploid and dependent on the gametophyte","is diploid and independent of the gametophyte"]', 3, 'Fern sporophyte is diploid and independent.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In ferns, the sporophyte', '["develops from a haploid zygote","reproduces sexually to produce spores","is haploid and dependent on the gametophyte","is diploid and independent of the gametophyte"]', '<u>Fern sporophyte is diploid and independent</u>.', '{"bold":[],"italic":[],"underline":["is diploid and independent of the gametophyte"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c25xqml2sc58z8noygcy1yt8t', 'Biology', 'JAMB', null, 1983, null, 'In a positive phototropic response of a coleoptile, the region of greatest curvature is brought about by the', null, '["movement of auxins away from the region of curvature","even distribution of auxins in all parts of the coleoptile","inhibition of growth by auxins in the region of smaller curvature","concentration of auxins in the region of curvature","absence of auxins in the coleptile"]', 3, 'Auxins concentrate on the shaded side causing greater curvature.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In a positive phototropic response of a coleoptile, the region of greatest curvature is brought about by the', '["movement of auxins away from the region of curvature","even distribution of auxins in all parts of the coleoptile","inhibition of growth by auxins in the region of smaller curvature","<u>concentration of auxins in the region of curvature</u>","absence of auxins in the coleptile"]', 'Auxins <u>concentrate on the shaded side</u> causing greater curvature.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2617esx2ic7j192qrrcyp77r', 'General Mathematics', 'JAMB', null, 2020, null, 'If n(A - B) = 12, n(B - A) = 8, n(A ∪ B) = 25, find n(A ∩ B).', null, '["5","6","7","8"]', 0, 'n(A ∪ B) = n(A - B) + n(B - A) + n(A ∩ B) → 25 = 12 + 8 + x → x = 5.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If n(A - B) = 12, n(B - A) = 8, n(A ∪ B) = 25, find n(A ∩ B).', '["5","6","7","8"]', 'n(A ∩ B) = <u>5</u>.', '{"bold":[],"italic":[],"underline":["5"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c26514c1-a93a-4e70-93d1-4a1394af2051', 'Hausa', 'JAMB', null, 2011, null, '''kulun-kulu-fita.''', null, '["Baba.","Gaita.","Kanwa","Gishiri."]', 1, '''Kulun-kulu-fita'' amsa ce ta kacici-kacici, kuma Gaita ce.', true, '2026-10-13 10:37:22.047', '2026-10-13 10:37:22.047', null, null, null, '''kulun-kulu-fita.''', '["Baba.","Gaita.","Kanwa","Gishiri."]', '''Kulun-kulu-fita'' amsa ce ta kacici-kacici, kuma Gaita ce.', '{"bold":["Gaita"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c269c425-9bfd-48d6-889f-7d33181c1978', 'Biology', 'JAMB', null, 2026, null, 'When a Spirogyra cell is immersed in a salt solution more concentrated than its cell sap, it', null, '["remains unchanged","takes up and burst","absorbs a little water","loses water and shrivel","becomes turgid"]', 3, 'When a Spirogyra cell is placed in a salt solution more concentrated than its cell sap, the cell loses water and shrivels (plasmolysis). This happens because of osmosis: water moves out of the cell (higher water concentration) into the more concentrated external solution (lower water concentration). The cell membrane pulls away from the cell wall as water leaves, causing the cell to shrink. Taking up water and bursting would occur in a hypotonic solution. Remaining unchanged occurs in an isotonic solution. Becoming turgid occurs when water enters the cell in a hypotonic solution.', true, '2026-09-09 03:18:49.284', '2026-09-09 03:18:49.284', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c26af60c-5190-4d5e-9416-5b4bbca054f4', 'English Language', 'JAMB', null, 2007, null, 'Adika <u>------------</u> a message from the club regularly.', null, '["receives","had received","receive","has received"]', 0, 'Singular Adika habitual â†’ receives.', true, '2026-10-24 01:04:28.88', '2026-10-24 01:04:28.88', null, null, null, 'Adika <u>------------</u> a message from the club regularly.', '["<u>receives</u>","had received","receive","has received"]', 'Singular <b>Adika</b> habitual â†’ <b>receives</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c26b9205-c916-4e20-9053-1564ed66543a', 'English Language', 'JAMB', null, 2007, null, 'The driver of that lorry <u>__________</u> lost his life during the collision', null, '["barely","hardly","nearly","closely","narrowly"]', 4, 'Correct spelling: narrowly.', true, '2026-10-24 07:21:40.63', '2026-10-24 07:21:40.63', null, null, null, 'The driver of that lorry <u>__________</u> lost his life during the collision', '["barely","hardly","nearly","closely","narrowly"]', 'Correct spelling: narrowly.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c26bd71flksmgmu88aw7dyanp', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve 2x + 3 ≡ 5 (mod 9).', null, '["1","4","7","8"]', 0, '2x ≡ 2 mod 9 → x ≡ 1 mod 9.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve 2x + 3 ≡ 5 (mod 9).', '["1","4","7","8"]', '2x ≡ 2 → <u>x = 1</u>.', null);
