insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c26enjjvlgxlbvi7294cl9avy', 'General Mathematics', 'WAEC', null, 2020, null, 'If cos 20° = k, find the value of sin 10° in terms of k.', null, '["√((1 - k)/2)","√((1 + k)/2)","√(k/2)","√(1 - k²)"]', 0, 'cos 20° = 1 - 2sin²10° → sin 10° = √((1-k)/2).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If cos 20° = k, find the value of sin 10° in terms of k.', '["√((1 - k)/2)","√((1 + k)/2)","√(k/2)","√(1 - k²)"]', 'sin 10° = <u>√((1 - k)/2)</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c26kkejtf1grv020idq9fwwok', 'Biology', 'JAMB', null, 1992, null, 'A child with blood group genotype different from those of both parents and with a mother of genotype OO, can only have a father of genotype', null, '["A","B","AB","OO"]', 2, 'The father must be AB if the child''s genotype differs from both parents.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A child with blood group genotype different from those of both parents and with a mother of genotype OO, can only have a father of genotype', '["A","B","<u>AB</u>","OO"]', 'The father must be <u>AB</u> if the child''s genotype differs from both parents.', null);
