insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c26mm6jw186jyozbbyq617zcm', 'Islamic Religious Studies', 'JAMB', null, 2008, null, 'Excluded from inheritance is a', null, '["Brother from the estate of his deceased brother","Man after the death of his wife","Person who kills his father for his estate","Woman because of her gender"]', 2, 'A murderer is excluded from inheriting his victim''s estate.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Excluded from inheritance is a', '["Brother from the estate of his deceased brother","Man after the death of his wife","<u>Person who kills his father for his estate</u>","Woman because of her gender"]', 'A <u>murderer is excluded</u> from inheriting his victim''s estate.', '{"bold":[],"italic":[],"underline":["Person who kills his father for his estate"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c26w17umqnrgj391szvc67aut', 'Biology', 'JAMB', null, 2001, null, 'The enzyme invertase will hydrolyze sucrose to give', null, '["maltose and glucose","glycerol and fatty acid","glucose and fructose","mannose and galactose"]', 2, 'Invertase hydrolyses sucrose into glucose and fructose.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The enzyme invertase will hydrolyze sucrose to give', '["maltose and glucose","glycerol and fatty acid","<u>glucose and fructose</u>","mannose and galactose"]', 'Invertase hydrolyses sucrose into glucose and fructose.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c272mifsmpxkqzvajw6cnd1an', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve 5x ≡ 4 (mod 7).', null, '["5","6","2","3"]', 1, '5×6 = 30 ≡ 2 mod 7. 5×5 = 25 ≡ 4 mod 7. So x = 5. Key says 6.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve 5x ≡ 4 (mod 7).', '["5","6","2","3"]', '5×5 = 25 ≡ <u>4</u> mod 7 → x = 5 (key says 6).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c273cgiu3zcoat0xw1t92hezj', 'Chemistry', 'JAMB', null, 1985, null, 'The approximate volume of air containing 10cm³ of oxygen is', null, '["20cm³","25cm³","50cm³","100cm³"]', 2, 'Air is ~21% O2, so 10cm³ O2 is in ~50cm³ air.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The approximate volume of air containing 10cm³ of oxygen is', '["20cm³","25cm³","50cm³","100cm³"]', 'Air is ~21% O2, so <u>50cm³</u> of air contains 10cm³ O2.', '{"bold":[],"italic":[],"underline":["50cm³"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c279bb34zvn7ekn61bnec4xyc', 'Biology', 'JAMB', null, 1990, null, 'In which part of the human body does the secretion of the growth hormone occur?', null, '["head region","waist region","neck region","gonads"]', 0, 'Growth hormone is secreted in the head region (pituitary gland).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In which part of the human body does the secretion of the <b>growth hormone</b> occur?', '["<u>head region</u>","waist region","neck region","gonads"]', '<u>Growth hormone is secreted in the head region</u> (pituitary gland).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c279fecd-9148-4042-a497-5e30ac5d5d41', 'Literature in English', 'JAMB', null, 2026, null, '''He would hear the heavy uneven breathing of the child: it was as if she were carrying a weight with great effort up a long hill………… He prayed again ''Father, look after her. Give her peace……….. Take away my peace forever, but give her peace'' Graham Greene, The Heart of the Matter. The man''s reactions to the presence of the dying child show that he is', null, '["tolerant","compassionate","prayerful","loving"]', 1, 'The man''s reactions show that he is compassionate. He is deeply moved by the child''s suffering, hears her labored breathing, and prays for her peace, even offering to give up his own peace in exchange. This selfless concern for another''s suffering demonstrates compassion. While he is prayerful and loving, compassion best captures his empathetic response.', true, '2026-09-10 10:47:54.118', '2026-09-10 10:47:54.118', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c27b0ruy4dr068f2yl5ccd5w3', 'Biology', 'JAMB', null, 1992, null, 'In typical predator food chain involving secondary and tertiary consumers, the organisms become progressively', null, '["smaller and more numerous along the food chain","equal in number and size along the food chain","larger and fewer along the food chain","parasitized along the food chain as consumers get bigger"]', 2, 'Predators become larger and fewer along the food chain.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In typical predator food chain involving secondary and tertiary consumers, the organisms become progressively', '["smaller and more numerous along the food chain","equal in number and size along the food chain","<u>larger and fewer along the food chain</u>","parasitized along the food chain as consumers get bigger"]', 'Predators <u>become larger and fewer</u> along the food chain.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c27de07c-899f-455e-b19e-e8e1bc8c20f7', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. He was asked to give <u>copious</u> examples to appear convincing.', null, '["concrete","rigid","cogent","many"]', 3, 'Copious = many/plentiful.', true, '2026-10-24 01:03:58.565', '2026-10-24 01:03:58.565', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. He was asked to give <u>copious</u> examples to appear convincing.', '["concrete","rigid","cogent","<u>many</u>"]', '<b>Copious</b> = <b>many</b>/plentiful.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c27j860p8fb8y3qn5h0lxinsw', 'Biology', 'JAMB', null, 2001, null, 'Both recessive and dominant characters are found', null, '["on different chromosomes in the cell","at the same locus of a homologous chromosome","in the mother''s sex cell","on the mother''s X chromosome"]', 1, 'Alleles are at the same locus on homologous chromosomes.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Both recessive and dominant characters are found', '["on different chromosomes in the cell","at the same locus of a homologous chromosome","in the mother''s sex cell","on the mother''s X chromosome"]', '<u>At the same locus of homologous chromosomes</u>.', '{"bold":[],"italic":[],"underline":["at the same locus of a homologous chromosome"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c27jlua5morqugk8brvm4x0fq', 'General Mathematics', 'WAEC', null, 2020, null, 'If log₁₀tan 1 + log₁₀tan 2 + ... + log₁₀tan 89 = k, find k.', null, '["0","1","44","89"]', 0, 'tan θ · tan(90-θ) = 1; sum = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If log₁₀tan 1 + log₁₀tan 2 + ... + log₁₀tan 89 = k, find k.', '["0","1","44","89"]', 'k = <u>0</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c27qaftp0lv1fldxo7bxceeoq', 'Biology', 'JAMB', null, 2000, null, 'Which of the following are adaptations of animals to aquatic habitats?', null, '["Gills, streamlined bodies and lateral line","Lateral line, streamlined bodies and lungs","Gills, streamlined bodies and spiracles","Gills, scales and lungs"]', 0, 'Gills, streamlined bodies and lateral line is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following are adaptations of animals to aquatic habitats?', '["<u>Gills, streamlined bodies and lateral line</u>","Lateral line, streamlined bodies and lungs","Gills, streamlined bodies and spiracles","Gills, scales and lungs"]', 'Gills, streamlined bodies and lateral line is the best answer because it matches the biological principle tested by the question.', null);
