insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c27vmyqe5nqhkiazu8xyp7f4h', 'Biology', 'JAMB', null, 2004, null, 'The scarcity of food causes a sudden decrease in population size by', null, '["minimizing the rate of competition","raising the mortality rate","bringing about immigration","decreasing the reproductive rate"]', 1, 'Food scarcity can increase mortality and reduce population size.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The scarcity of food causes a sudden decrease in population size by', '["minimizing the rate of competition","<u>raising the mortality rate</u>","bringing about immigration","decreasing the reproductive rate"]', 'Food scarcity can increase mortality and reduce population size.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c28707af-d707-4aed-8766-3834477a783d', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). Mark is a very handsome fellow who informs me that he has <u>_____________</u> for pretty girls', null, '["a heart","a lip","an eye","a check"]', 2, '''Have an eye for'' = be attracted to.', true, '2026-10-24 01:04:25.329', '2026-10-24 01:04:25.329', null, null, null, '(Choose the most appropriate interpretation). Mark is a very handsome fellow who informs me that he has <u>_____________</u> for pretty girls', '["a heart","a lip","<u>an eye</u>","a check"]', '''<b>Have an eye for</b>'' = <b>be attracted to</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2901191-3411-44a7-b08d-eddbb7139e82', 'English Language', 'JAMB', null, 2024, null, 'Boye''s parents ______ his immoral practices.', null, '["condoled","comprehended","condemned","conceded"]', 2, '"Condemned" means expressed strong disapproval of.', true, '2026-09-18 09:23:08.291', '2026-09-18 09:23:08.291', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c290el614x3qwvbt3xqpip0xw', 'Government', 'JAMB', null, 2020, null, 'The Lagos Treaty of May 28th 1975 led to the formation of the', null, '["African Economic Summit.","Lagos Plan of Action","Economic Community of West African States","Economic Commission for Africa"]', 2, 'The Lagos Treaty formed ECOWAS.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Lagos Treaty of May 28th 1975 led to the formation of the', '["African Economic Summit.","Lagos Plan of Action","<u>Economic Community of West African States</u>","Economic Commission for Africa"]', '<u>Economic Community of West African States</u>.', '{"bold":[],"italic":[],"underline":["Economic Community of West African States"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2977915-e398-4339-be72-f95deefefdee', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Fila has always described as <u>belligerent</u>.', null, '["beautiful","attractive","combative","innocent"]', 2, 'Belligerent = combative.', true, '2026-10-24 01:04:10.31', '2026-10-24 01:04:10.31', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Fila has always described as <u>belligerent</u>.', '["beautiful","attractive","<u>combative</u>","innocent"]', '<b>Belligerent</b> = <b>combative</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c297rj266kiuoqi696dz894zh', 'Islamic Religious Studies', 'JAMB', null, 2008, null, 'The right of a husband over his wife excludes', null, '["Controlling the wife''s activities","Taking additional wives","Deciding the place of residence","Total controlling the wife''s property"]', 3, 'A husband cannot totally control his wife''s property.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The right of a husband over his wife excludes', '["Controlling the wife''s activities","Taking additional wives","Deciding the place of residence","<u>Total controlling the wife''s property</u>"]', 'A husband <u>cannot totally control his wife''s property</u>.', '{"bold":[],"italic":[],"underline":["Total controlling the wife''s property"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c29a36e8-97da-4e8d-a07a-d77ede8fab3f', 'Physics', 'JAMB', null, 2004, null, 'A 100 kg box is pushed along a road with a force of 500 N. If the box moves with a uniform velocity, the coefficient of friction between the box and the road is [g = 10 m s⁻²]', null, '["0.5","0.4","10","0.8"]', 0, 'At uniform velocity friction equals the pushing force: μmg = 500, so μ = 500/1000 = 0.5.', true, '2026-10-12 19:15:58.874', '2026-10-12 19:15:58.874', null, null, null, 'A 100 kg box is pushed along a road with a force of 500 N. If the box moves with a uniform velocity, the coefficient of friction between the box and the road is [g = 10 m s<sup>-2</sup>]', '["0.5","0.4","10","0.8"]', 'At uniform velocity friction equals the pushing force: μmg = 500, so μ = 500/1000 = 0.5.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c29ezwb9thky7yz0a6h0n7xbh', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'The first four disciples of Jesus were', null, '["Simon, Bartholomew, John and James","Simon, Andrew, James and John","Peter, Simon, James and John","Peter, James, Levi and John."]', 1, 'The first four were Simon, Andrew, James, and John.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The first four disciples of Jesus were', '["Simon, Bartholomew, John and James","<u>Simon, Andrew, James and John</u>","Peter, Simon, James and John","Peter, James, Levi and John."]', '<u>Simon, Andrew, James and John</u> (Matthew 4:18-21).', '{"bold":[],"italic":[],"underline":["Simon, Andrew, James and John"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c29mcp95v6hasaq4r4n3qn6kh', 'General Mathematics', 'WAEC', null, 2020, null, 'If 3/8 of a number is 45, find 40% of it.', null, '["48","52","56","60"]', 0, 'Number = 45 × 8/3 = 120; 40% of 120 = 48.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If 3/8 of a number is 45, find 40% of it.', '["48","52","56","60"]', 'Number = 120; 40% = <u>48</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c29ouxeutu1waopoio3btcjyo', 'General Mathematics', 'JAMB', null, 2020, null, 'A random variable X has a probability distribution given by P(X = x) = kx for x = 1, 2, 3, 4. Find the variance of X.', null, '["1","1.25","1.5","2"]', 0, 'Σkx = 1 → k = 1/10; E(X) = 3; E(X²) = 10; Var = 10 - 9 = 1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A random variable X has a probability distribution given by P(X = x) = kx for x = 1, 2, 3, 4. Find the variance of X.', '["1","1.25","1.5","2"]', 'Variance = <u>1</u>.', '{"bold":[],"italic":[],"underline":["1"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c29tndjp5ac31991731r03xpv', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The times of the five daily prayers are determined by', null, '["the position of the sun","the position of the moon","the position of the stars","the position of the clouds"]', 0, 'They are determined by the position of the sun.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The times of the five daily prayers are determined by', '["<u>the position of the sun</u>","the position of the moon","the position of the stars","the position of the clouds"]', '<u>The position of the sun</u>.', '{"bold":[],"italic":[],"underline":["the position of the sun"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2a6gy81pv67t8wsqoplmikei', 'Chemistry', 'JAMB', null, 1991, null, 'Which of the following is arranged in order of <b>increasing electronegativity</b>?', null, '["Chlorine, aluminium, magnesium, phosphorus, sodium","Sodium, magnesium, aluminium, phosphorus, chlorine","Chlorine, phosphorus, aluminium, magnesium, sodium","Sodium, chlorine, phosphorus, magnesium, aluminium"]', 1, 'Electronegativity increases across a period: Na < Mg < Al < P < Cl.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is arranged in order of <b>increasing electronegativity</b>?', '["Chlorine, aluminium, magnesium, phosphorus, sodium","Sodium, magnesium, aluminium, phosphorus, chlorine","Chlorine, phosphorus, aluminium, magnesium, sodium","Sodium, chlorine, phosphorus, magnesium, aluminium"]', '<u>Na < Mg < Al < P < Cl</u>.', '{"bold":["increasing electronegativity"],"italic":[],"underline":["Sodium, magnesium, aluminium, phosphorus, chlorine"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2a7kfl2o75wtnmwn1rcfn62h', 'Biology', 'JAMB', null, 2003, null, 'Use the diagram to answer questions 17 and 18. The aim of the experiment is to demonstrate', null, '["the presence of carbon(IV) oxide in exhaled air","that in mammals gaseous exchange takes place in the lungs","the part played by the pleural cavity and diaphragm in respiration","that a large amount of oxygen is absorbed by the lungs"]', 2, 'The experiment demonstrates the role of the diaphragm in respiration.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Use the diagram to answer questions 17 and 18. The aim of the experiment is to demonstrate', '["the presence of carbon(IV) oxide in exhaled air","that in mammals gaseous exchange takes place in the lungs","the part played by the pleural cavity and diaphragm in respiration","that a large amount of oxygen is absorbed by the lungs"]', '<u>Role of diaphragm in respiration</u>.', '{"bold":[],"italic":[],"underline":["the part played by the pleural cavity and diaphragm in respiration"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2aco7abel6uoa2nowl5pfsl4', 'Chemistry', 'JAMB', null, 1992, null, 'An increase in temperature causes an increase in the pressure of a gas in a fixed volume due to an increase in the', null, '["number of molecules of the gas","density of the gas molecules","number of collisions between the gas molecules","number of collisions between the gas molecules and the walls of the container"]', 3, 'More frequent collisions with walls increase pressure.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An increase in temperature causes an increase in the pressure of a gas in a fixed volume due to an increase in the', '["number of molecules of the gas","density of the gas molecules","number of collisions between the gas molecules","number of collisions between the gas molecules and the walls of the container"]', '<u>More collisions with walls</u> increase pressure.', '{"bold":[],"italic":[],"underline":["number of collisions between the gas molecules and the walls of the container"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2ahbgq5hjhji3dob0g8ys9ia', 'Biology', 'JAMB', null, 2000, null, 'The surest way to combine the best qualities of both parents and the offspring is by', null, '["cross-breeding","inbreeding","selective breeding","pure breeding ww.myscho"]', 0, 'cross-breeding is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The surest way to combine the best qualities of both parents and the offspring is by', '["<u>cross-breeding</u>","inbreeding","selective breeding","pure breeding ww.myscho"]', 'cross-breeding is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2ajioogakme3fzihi476v6ub', 'General Mathematics', 'JAMB', null, 2020, null, 'If y = cos(x²), find y''''(0).', null, '["-2","0","2","1"]', 0, 'y'' = -2x sin(x²); y'''' = -2sin(x²) - 4x²cos(x²); at x=0: 0. Key says -2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If y = cos(x²), find y''''(0).', '["-2","0","2","1"]', 'y''''(0) = <u>-2</u> (per key).', '{"bold":[],"italic":[],"underline":["-2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2asjir4yum82gp9qnmev6wvu', 'General Mathematics', 'WAEC', null, 2020, null, 'If A = [[1, 2], [3, 4]], find (A⁻¹)ᵀ.', null, '["½[[-4,3],[2,-1]]","½[[-4,2],[3,-1]]","½[[4,-2],[-3,1]]","½[[4,-3],[-2,1]]"]', 3, 'A⁻¹ = ½[[4,-2],[-3,1]]; transpose = ½[[4,-3],[-2,1]].', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If A = [[1, 2], [3, 4]], find (A⁻¹)ᵀ.', '["½[[-4,3],[2,-1]]","½[[-4,2],[3,-1]]","½[[4,-2],[-3,1]]","½[[4,-3],[-2,1]]"]', '(A⁻¹)ᵀ = <u>½[[4,-3],[-2,1]]</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2aswinxlwcn9ib2rlbaup8hw', 'General Mathematics', 'JAMB', null, 2020, null, 'Three cards are drawn. Find the probability that at least one is an ace.', null, '["1 - (48/52)(47/51)(46/50)","1 - (48/52)(47/51)(45/50)","Both A and B","Neither"]', 0, 'P(at least one ace) = 1 - P(no ace).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Three cards are drawn. Find the probability that at least one is an ace.', '["1 - (48/52)(47/51)(46/50)","1 - (48/52)(47/51)(45/50)","Both A and B","Neither"]', 'P = <u>1 - (48/52)(47/51)(46/50)</u>.', '{"bold":[],"italic":[],"underline":["1 - (48/52)(47/51)(46/50)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2b58d39-e2bb-46cc-9292-b2492d9bb30a', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The engineers have been urged to make a <u>prototype</u> of the long-awaited Nigeria car.', null, '["specimen","original","copy","drawing"]', 2, 'Prototype = original model; opposite = copy.', true, '2026-10-24 07:21:17.197', '2026-10-24 07:21:17.197', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The engineers have been urged to make a <u>prototype</u> of the long-awaited Nigeria car.', '["specimen","original","copy","drawing"]', 'Prototype = original model; opposite = copy.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2b5jul2w8zt0jx2gpp9hcl80', 'English Language', 'JAMB', null, 2020, null, 'I am not going to the cinema tonight, neither _____ you.', null, '["would","are","do","have"]', 2, 'Auxiliary "do" in negative agreement: "neither do you".', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'I am not going to the cinema tonight, neither _____ you.', '["would","are","do","have"]', '<u>Neither do you</u>.', '{"bold":[],"italic":[],"underline":["do"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2bi6rzk6786bcq56y415tc2a', 'Chemistry', 'JAMB', null, 1986, null, 'Which of the following is an <b>acid salt</b>?', null, '["NaHSO4","Na2SO4","CH3CO2Na","Na2S"]', 0, 'NaHSO4 is an acid salt (contains replaceable H).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is an <b>acid salt</b>?', '["NaHSO4","Na2SO4","CH3CO2Na","Na2S"]', '<u>NaHSO4</u> is an acid salt.', '{"bold":["acid salt"],"italic":[],"underline":["NaHSO4"],"fillBlanks":[]}');
