insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2bttb31di83oxfepu74zibj1', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'According to the first Epistle of John, to have the Son is to have', null, '["the Holy Spirit","life","salvation","the father."]', 1, 'To have the Son is to have life.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to the first Epistle of John, to have the Son is to have', '["the Holy Spirit","<u>life</u>","salvation","the father."]', '<u>Life</u> (1 John 5:11-12).', '{"bold":[],"italic":[],"underline":["life"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2bv7p27ng1446ia2cbv2uz3z', 'Islamic Religious Studies', 'JAMB', null, 2002, null, 'According to the Prophet (S.A.W), he who betrays trust is regarded as having', null, '["faith but no religion","religion but no faith","no hope in the Hereafter","neither faith nor religion"]', 3, 'The Prophet said one who betrays trust has neither faith nor religion.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to the Prophet (S.A.W), he who betrays trust is regarded as having', '["faith but no religion","religion but no faith","no hope in the Hereafter","<u>neither faith nor religion</u>"]', 'The Prophet said one who betrays trust has <u>neither faith nor religion</u>.', '{"bold":[],"italic":[],"underline":["neither faith nor religion"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2bxaajt3zieecrvbgemwwtoo', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the identity for a*b = a + b + 1.', null, '["-1","0","1","none"]', 0, 'a*e = a → a+e+1 = a → e = -1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the identity for a*b = a + b + 1.', '["-1","0","1","none"]', 'Identity = <u>-1</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2c022a6-a243-4553-8c62-02c6951aac65', 'English Language', 'JAMB', null, 2007, null, 'The thief we caught yesterday was <u>__________</u> as an official of the company', null, '["disguised","concealed","masked","veiled"]', 0, 'Correct spelling: disguised.', true, '2026-10-24 07:21:43.567', '2026-10-24 07:21:43.567', null, null, null, 'The thief we caught yesterday was <u>__________</u> as an official of the company', '["disguised","concealed","masked","veiled"]', 'Correct spelling: disguised.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2c6zqy584f4t7c6cl8qlkn5i', 'Chemistry', 'JAMB', null, 1993, null, 'For iodine crystals to sublime on heating, the molecules must acquire energy that is', null, '["less than the forces of attraction in the solid","equal to the forces of attraction in the solid","necessary to melt the solid","greater than the forces of attraction in both solid and the liquid phases"]', 3, 'Sublimation requires overcoming forces in both solid and liquid phases.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'For iodine crystals to sublime on heating, the molecules must acquire energy that is', '["less than the forces of attraction in the solid","equal to the forces of attraction in the solid","necessary to melt the solid","greater than the forces of attraction in both solid and the liquid phases"]', '<u>Greater than forces in both solid and liquid phases</u>.', '{"bold":[],"italic":[],"underline":["greater than the forces of attraction in both solid and the liquid phases"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2c78usrckzkekywxgg9mip96', 'Biology', 'JAMB', null, 2000, null, 'An ecological succession often leads to', null, '["an increase in species diversity","a decrease in species diversity","an unstable community","the dispersal of species"]', 0, 'Succession increases species diversity.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An ecological succession often leads to', '["an increase in species diversity","a decrease in species diversity","an unstable community","the dispersal of species"]', '<u>Increases species diversity</u>.', '{"bold":[],"italic":[],"underline":["an increase in species diversity"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2c82rxtsu5hknh1idfa52gcg', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'God called Jonah and sent him to the people of Nineveh to', null, '["pray to Him for their forgiveness","pray for their repentance","preach His word to them","destroy them in His anger"]', 2, 'He was to preach God''s word to them.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'God called Jonah and sent him to the people of Nineveh to', '["pray to Him for their forgiveness","pray for their repentance","<u>preach His word to them</u>","destroy them in His anger"]', '<u>Preach His word to them</u> (Jonah 1:2).', '{"bold":[],"italic":[],"underline":["preach His word to them"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2cac135-52a4-47a1-ae1a-9b43282cbb2c', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The undesirable elements who <u>perpetuate</u> these vices are never detected.', null, '["aggravate","overlook","discontinue","encourage"]', 2, 'Perpetuate = continue; opposite = discontinue.', true, '2026-10-24 07:21:17.859', '2026-10-24 07:21:17.859', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The undesirable elements who <u>perpetuate</u> these vices are never detected.', '["aggravate","overlook","discontinue","encourage"]', 'Perpetuate = continue; opposite = discontinue.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2cgf6g1hbdxraq4jxsaax531', 'General Mathematics', 'JAMB', null, 2020, null, 'If (h, 3) lies on the line joining (1,2) and (3,4), find h.', null, '["2","3","4","5"]', 0, 'Slope = 1; (3-2)/(h-1) = 1 → h = 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If (h, 3) lies on the line joining (1,2) and (3,4), find h.', '["2","3","4","5"]', 'h = <u>2</u>.', '{"bold":[],"italic":[],"underline":["2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2coh8kcstic8boh117vvrwjc', 'Chemistry', 'JAMB', null, 1983, null, 'Which of the following pairs of gases will <b>NOT react further</b> with oxygen at a temperature between 30°C and 400°C?', null, '["SO2 and NH3","CO2 and H2","NO2 and SO3","SO3 and NO","CO and HF"]', 3, 'SO3 and NO are already fully oxidized and will not react further with oxygen.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following pairs of gases will <b>NOT react further</b> with oxygen at a temperature between 30°C and 400°C?', '["SO2 and NH3","CO2 and H2","NO2 and SO3","SO3 and NO","CO and HF"]', '<u>SO3 and NO</u> are already fully oxidized.', '{"bold":["NOT react further"],"italic":[],"underline":["SO3 and NO"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2cy392ud0xkkfnuugas5fnlz', 'Biology', 'JAMB', null, 1997, null, 'In which of the following groups of vertebrates would the largest amount of yolk be found in the egg?', null, '["Mammals","Fishes","Amphibians","Reptiles"]', 3, 'Reptiles (and birds) have the largest yolk.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In which of the following groups of vertebrates would the largest amount of yolk be found in the egg?', '["Mammals","Fishes","Amphibians","Reptiles"]', '<u>Reptiles</u> have the largest yolk.', '{"bold":[],"italic":[],"underline":["Reptiles"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2d156cpunqihyc86yu0tkqkw', 'Biology', 'JAMB', null, 1983, null, 'Which of the following diseases is NOT caused by a virus?', null, '["Rinderpest","Maize rust","Newcastle disease","Swine fever","Cassava mosaic disease"]', 1, 'Maize rust is caused by a fungus, not a virus.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following diseases is <b>NOT</b> caused by a <b>virus</b>?', '["Rinderpest","<u>Maize rust</u>","Newcastle disease","Swine fever","Cassava mosaic disease"]', '<u>Maize rust</u> is caused by a fungus, not a virus.', null);
