insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2d42yijq9rjdi0wze052p3dz', 'Chemistry', 'JAMB', null, 1992, null, 'The functional group present in an organic compound that reacts with a saturated solution of NaHCO3 is', null, '["hydroxyl group","carbonalkoxyl group","carbonyl group","carboxy group"]', 3, null, true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The functional group present in an organic compound that reacts with a saturated solution of NaHCO3 is', '["hydroxyl group","carbonalkoxyl group","carbonyl group","carboxy group"]', '<u>-COOH (carboxy)</u> reacts with NaHCO3.', '{"bold":[],"italic":[],"underline":["carboxy group"],"fillBlanks":[]}');
