insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2dzei4hgyxb46kgezm5ch6hk', 'Chemistry', 'JAMB', null, 1988, null, 'Which of the following acts both as <b>reducing and as oxidizing agent</b>?', null, '["H2","SO2","H2S","C"]', 1, 'SO2 can be oxidized to SO3 and reduced to S.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following acts both as <b>reducing and as oxidizing agent</b>?', '["H2","SO2","H2S","C"]', '<u>SO2</u> can act as both oxidizing and reducing agent.', '{"bold":["reducing and as oxidizing agent"],"italic":[],"underline":["SO2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2efy6v2a1f3tdv6wno51foku', 'Chemistry', 'JAMB', null, 1988, null, 'Crude copper can be purified by the electrolysis of CuSO4(aq) if', null, '["platinum electrodes are used","the crude copper is made the anode of the cell","the crude copper is made the cathode of the cell","crude copper electrodes are used"]', 1, 'Crude copper is the anode; pure copper deposits on the cathode.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Crude copper can be purified by the electrolysis of CuSO4(aq) if', '["platinum electrodes are used","the crude copper is made the anode of the cell","the crude copper is made the cathode of the cell","crude copper electrodes are used"]', '<u>Crude copper is the anode</u>; pure Cu deposits on cathode.', '{"bold":[],"italic":[],"underline":["the crude copper is made the anode of the cell"],"fillBlanks":[]}');
