insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2f57e7f-bbb4-44b5-b98e-95e6d11ad36d', 'Biology', 'JAMB', null, 2003, null, 'Which of the following requires the use of carbon dating to prove that evolution has occurred?', null, '["Comparative anatomy","Biochemical similarities","Molecular records","Fossil records"]', 3, 'Fossil records require carbon dating.', true, '2026-10-12 20:59:34.203', '2026-10-12 20:59:34.203', null, null, null, 'Which of the following requires the use of carbon dating to prove that evolution has occurred?', '["Comparative anatomy","Biochemical similarities","Molecular records","Fossil records"]', 'Fossil records require carbon dating.', '{"bold":["Fossil records"],"italic":[],"underline":[],"fillBlanks":[]}');
