insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2hlyhvp2c2mm7d5ye9pkpw88', 'General Mathematics', 'WAEC', null, 2020, null, 'Differentiate y = log₁₀x.', null, '["1/(x ln 10)","ln 10/x","1/x","10/x"]', 0, 'dy/dx = 1/(x ln 10).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Differentiate y = log₁₀x.', '["1/(x ln 10)","ln 10/x","1/x","10/x"]', 'dy/dx = <u>1/(x ln 10)</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2hsydg7vdk5d12xk28595h8f', 'General Mathematics', 'WAEC', null, 2020, null, 'Differentiate y = e^sin x · ln(cos x).', null, '["e^sin x[cos x ln(cos x) - tan x]","e^sin x[cos x ln(cos x) + tan x]","e^sin x[sin x ln(cos x) - tan x]","e^sin x[sin x ln(cos x) + tan x]"]', 0, 'Product rule: dy/dx = e^sin x[cos x ln(cos x) - tan x].', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Differentiate y = e^sin x · ln(cos x).', '["e^sin x[cos x ln(cos x) - tan x]","e^sin x[cos x ln(cos x) + tan x]","e^sin x[sin x ln(cos x) - tan x]","e^sin x[sin x ln(cos x) + tan x]"]', 'dy/dx = <u>e^sin x[cos x ln(cos x) - tan x]</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2huv52xvofte2dfmhjndd4nn', 'General Mathematics', 'JAMB', null, 2020, null, 'Combined variance of two groups of equal size and equal variance σ².', null, '["σ²","2σ²","σ²/2","0"]', 0, 'Combined variance = σ² (equal means).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Combined variance of two groups of equal size and equal variance σ².', '["σ²","2σ²","σ²/2","0"]', 'Combined variance = <u>σ²</u>.', '{"bold":[],"italic":[],"underline":["σ²"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2i4052zmlnuh5plshvtboa5b', 'General Mathematics', 'JAMB', null, 2020, null, 'On {0,1}, a*b = ab. What is the identity?', null, '["0","1","none","both"]', 1, 'a*1 = a; identity = 1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'On {0,1}, a*b = ab. What is the identity?', '["0","1","none","both"]', 'Identity = <u>1</u>.', '{"bold":[],"italic":[],"underline":["1"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2i9w947faz2x6vvc56x23961', 'Biology', 'JAMB', null, 2003, null, 'An insect with a <b>mandibulate mouth part</b> will obtain its food by', null, '["chewing","chewing and sucking","sucking","biting and chewing"]', 3, 'Mandibulate mouthparts bite and chew.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An insect with a <b>mandibulate mouth part</b> will obtain its food by', '["chewing","chewing and sucking","sucking","biting and chewing"]', '<u>Biting and chewing</u>.', '{"bold":["mandibulate mouth part"],"italic":[],"underline":["biting and chewing"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2i9wido7l7d6tkn0q79a79wg', 'General Mathematics', 'JAMB', null, 2020, null, 'If a, b, c are three non-coplanar vectors such that a + b + c = αb and b + c = βc, find α and β.', null, '["α = 2, β = 2","α = 1, β = 1","α = -1, β = -1","α = 0, β = 0"]', 1, 'Non-coplanar → coefficients of each vector must match; α = 1, β = 1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If a, b, c are three non-coplanar vectors such that a + b + c = αb and b + c = βc, find α and β.', '["α = 2, β = 2","α = 1, β = 1","α = -1, β = -1","α = 0, β = 0"]', 'α = <u>1</u>, β = <u>1</u>.', '{"bold":[],"italic":[],"underline":["α = 1, β = 1"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2iavx0p82jqb9yja5e62wmxo', 'Biology', 'JAMB', null, 2004, null, 'A state in Nigeria that is most susceptible to desert encroachment is', null, '["Kaduna","Kastina","Kwara","Taraba"]', 1, 'Kastina is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A state in Nigeria that is most susceptible to desert encroachment is', '["Kaduna","<u>Kastina</u>","Kwara","Taraba"]', 'Kastina is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2ie14sde3fud0d7lmf6qx7zz', 'Chemistry', 'JAMB', null, 1995, null, 'The volume occupied by 1.58g of a gas at s.t.p is 500cm³. What is the relative molecular mass of the gas?', null, '["28","32","344","71"]', 2, 'Moles = 0.5/22.4 = 0.0223; Mr = 1.58/0.0223 = 71. Key says 344.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The volume occupied by 1.58g of a gas at s.t.p is 500cm³. What is the relative molecular mass of the gas?', '["28","32","344","71"]', 'Moles = 0.0223; Mr = <u>71</u> (key says 344).', '{"bold":[],"italic":[],"underline":["344"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2io9aqx8ezjree3lfyimfzft', 'Government', 'JAMB', null, 2020, null, 'An indication that Africa is still the centre-piece of Nigeria''s foreign policy was the creation of the', null, '["Ministry of Integration and Cooperation in Africa","Nigeria Institute of Policy and Strategic Studies","Ministry of Foreign Affairs.","Nigerian Institute of International Affairs"]', 0, 'The Ministry of Integration and Cooperation in Africa reflects Africa-focused policy.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An indication that Africa is still the centre-piece of Nigeria''s foreign policy was the creation of the', '["<u>Ministry of Integration and Cooperation in Africa</u>","Nigeria Institute of Policy and Strategic Studies","Ministry of Foreign Affairs.","Nigerian Institute of International Affairs"]', '<u>Ministry of Integration and Cooperation in Africa</u>.', '{"bold":[],"italic":[],"underline":["Ministry of Integration and Cooperation in Africa"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2ippgsh6tudr8wox1ludu532', 'Chemistry', 'JAMB', null, 1991, null, '2H2S(g) + SO2(g) → 3S(s) + 2H2O(l). The above reaction is', null, '["a redox reaction in which H2S is the oxidant and SO2 is the reductant","a redox reaction in which SO2 is the oxidant and H2S is the reductant","Not a redox reaction because there is no oxidant in the reaction equation","Not a redox reaction because there is no reductant in the reaction equation"]', 1, 'SO2 is reduced (oxidant); H2S is oxidized (reductant).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '2H2S(g) + SO2(g) → 3S(s) + 2H2O(l). The above reaction is', '["a redox reaction in which H2S is the oxidant and SO2 is the reductant","a redox reaction in which SO2 is the oxidant and H2S is the reductant","Not a redox reaction because there is no oxidant in the reaction equation","Not a redox reaction because there is no reductant in the reaction equation"]', '<u>SO2 is the oxidant and H2S is the reductant</u>.', '{"bold":[],"italic":[],"underline":["a redox reaction in which SO2 is the oxidant and H2S is the reductant"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2iq1new9rd9v4i70rks0h13w', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'In the days of Uzziah, Isaiah saw a vision concerning', null, '["Samaria and Judah","Judah and Jerusalem","Samaria and Jerusalem","Judah and Israel."]', 1, 'Isaiah''s vision concerned Judah and Jerusalem.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the days of Uzziah, Isaiah saw a vision concerning', '["Samaria and Judah","<u>Judah and Jerusalem</u>","Samaria and Jerusalem","Judah and Israel."]', '<u>Judah and Jerusalem</u> (Isaiah 2:1).', '{"bold":[],"italic":[],"underline":["Judah and Jerusalem"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2j865n86c0aae46yug4lgonj', 'Chemistry', 'JAMB', null, 1993, null, 'The dissolution of common salt in water is a physical change because', null, '["the salt can be obtained by crystallization","the salt can be recovered by the evaporation of water","Heat is not generated during mixing","The solution will not boil at 100°C"]', 1, 'Salt can be recovered by evaporation (physical change).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The dissolution of common salt in water is a physical change because', '["the salt can be obtained by crystallization","the salt can be recovered by the evaporation of water","Heat is not generated during mixing","The solution will not boil at 100°C"]', '<u>Salt can be recovered by evaporation</u>.', '{"bold":[],"italic":[],"underline":["the salt can be recovered by the evaporation of water"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2japgrd22lmxob7l5f3p98hb', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'They have taken the Lord out of the tomb, and we do not know where they have laid him. What happened immediately after Mary Magdalene made the statement above?', null, '["The guards were afraid and ran away from the tomb","Peter and the other disciples went towards the tomb","Two angels appeared to Mary by the tomb","Mary stood, weeping outside the tomb."]', 1, 'Peter and the other disciple went toward the tomb.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'They have taken the Lord out of the tomb, and we do not know where they have laid him. What happened immediately after Mary Magdalene made the statement above?', '["The guards were afraid and ran away from the tomb","<u>Peter and the other disciples went towards the tomb</u>","Two angels appeared to Mary by the tomb","Mary stood, weeping outside the tomb."]', '<u>Peter and the other disciples went towards the tomb</u> (John 20:2-3).', '{"bold":[],"italic":[],"underline":["Peter and the other disciples went towards the tomb"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2jbnkwvccnmcufwoz4riksy3', 'Government', 'JAMB', null, 2020, null, 'During the Second Republic, the Great Nigeria People''s Party won the governorship election in', null, '["Sokoto and Bauchi States.","Borno and Gongola States","Borno and Kaduna States","Gongola and Sokoto States"]', 1, 'GNPP won in Borno and Gongola States.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'During the Second Republic, the Great Nigeria People''s Party won the governorship election in', '["Sokoto and Bauchi States.","<u>Borno and Gongola States</u>","Borno and Kaduna States","Gongola and Sokoto States"]', '<u>Borno and Gongola States</u>.', '{"bold":[],"italic":[],"underline":["Borno and Gongola States"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2jczsk4ntcmxajno2h6lseyr', 'Chemistry', 'JAMB', null, 1983, null, 'The mass of an atom is determined by', null, '["its ionization potential","its electrochemical potential","the number of protons","the number of neutrons and protons","the number of neutrons and electrons"]', 3, 'Atomic mass is the sum of protons and neutrons in the nucleus.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The mass of an atom is determined by', '["its ionization potential","its electrochemical potential","the number of protons","the number of neutrons and protons","the number of neutrons and electrons"]', 'Atomic mass is the sum of <u>protons and neutrons</u>.', '{"bold":[],"italic":[],"underline":["the number of neutrons and protons"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2jdrg98le5budsepgrxqvkcq', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'What command did Paul give the brethren at Thessalonica concerning those who live in idleness?', null, '["That they should keep away from them","That they should treat them as offenders","That they should be punished","That they should share with them in common."]', 0, 'They should keep away from them.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What command did Paul give the brethren at Thessalonica concerning those who live in idleness?', '["<u>That they should keep away from them</u>","That they should treat them as offenders","That they should be punished","That they should share with them in common."]', '<u>That they should keep away from them</u> (2 Thessalonians 3:6).', '{"bold":[],"italic":[],"underline":["That they should keep away from them"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2jfdijbton42vlahnolc8e6p', 'Biology', 'JAMB', null, 2003, null, 'A limiting factor in a plant population near a chemical factory is likely to be', null, '["humidity","pH","wind","light"]', 1, 'Chemical factory affects soil pH.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A limiting factor in a plant population near a chemical factory is likely to be', '["humidity","pH","wind","light"]', '<u>pH</u> is limiting near a chemical factory.', '{"bold":[],"italic":[],"underline":["pH"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2jr1zzfyt76upqsycd4wo42s', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'The river that flowed out of Eden, to water the garden divided and became four rivers namely', null, '["Pishon, Tigris, Gihon and Nile","Nile, Pishon, Euphrates and Tigris","Gihon, Pishon, Tigris and Euphrates","Pishon, Euphrates, Gihon and Jordan."]', 2, 'The four rivers are Gihon, Pishon, Tigris, and Euphrates.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The river that flowed out of Eden, to water the garden divided and became four rivers namely', '["Pishon, Tigris, Gihon and Nile","Nile, Pishon, Euphrates and Tigris","<u>Gihon, Pishon, Tigris and Euphrates</u>","Pishon, Euphrates, Gihon and Jordan."]', '<u>Gihon, Pishon, Tigris, and Euphrates</u> (Genesis 2:10-14).', '{"bold":[],"italic":[],"underline":["Gihon, Pishon, Tigris and Euphrates"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2jxdvfvhfeggedgf2d38mspa', 'General Mathematics', 'JAMB', null, 2020, null, 'If A = {x : x² - 5x + 6 = 0}, B = {x : |x| = 2}, find A ∪ B.', null, '["{2, 3}","{-2, 2, 3}","{2}","{-2, 2}"]', 1, 'A = {2, 3}; B = {-2, 2}; A ∪ B = {-2, 2, 3}.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If A = {x : x² - 5x + 6 = 0}, B = {x : |x| = 2}, find A ∪ B.', '["{2, 3}","{-2, 2, 3}","{2}","{-2, 2}"]', 'A ∪ B = <u>{-2, 2, 3}</u>.', '{"bold":[],"italic":[],"underline":["{-2, 2, 3}"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2jzjw851kbctk46tejv3edr9', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Peter in his epistle enjoined servants to be submissive to their masters with all', null, '["gentleness","seriousness","respect","humility."]', 2, 'Servants should be submissive with all respect.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Peter in his epistle enjoined servants to be submissive to their masters with all', '["gentleness","seriousness","<u>respect</u>","humility."]', '<u>Respect</u> (1 Peter 2:18).', '{"bold":[],"italic":[],"underline":["respect"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2k2ohh0kp4xly5h4q0vu6ytx', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve for x and y: 4ˣ · 2ʸ = 16 · 2³ˣ and 9ˣ⁺ʸ = 27ʸ⁻¹.', null, '["x = 1, y = 5","x = 2, y = -5","x = 2, y = 5","x = -2, y = -5"]', 0, '2x + y = 4 + 3x → y = x + 4; 2x + 2y = 3y - 3 → y = 2x + 3; so x = 1, y = 5.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Solve for x and y: 4ˣ · 2ʸ = 16 · 2³ˣ and 9ˣ⁺ʸ = 27ʸ⁻¹.', '["x = 1, y = 5","x = 2, y = -5","x = 2, y = 5","x = -2, y = -5"]', '2x + y = 4 + 3x → y = x + 4; 2x + 2y = 3y - 3 → y = 2x + 3; so x = 1, y = 5.', '{"bold":[],"italic":[],"underline":["x = -2, y = 5"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2kf2e4m2yqcuy0h4m6ffhi5u', 'General Mathematics', 'WAEC', null, 2020, null, 'A die is rolled twice. Find the probability the sum is 7, given the first die is a 3.', null, '["1/6","1/5","1/4","1/3"]', 0, 'Given first = 3, second must be 4; P = 1/6.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A die is rolled twice. Find the probability the sum is 7, given the first die is a 3.', '["1/6","1/5","1/4","1/3"]', 'P = <u>1/6</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2kk7hj6h6iyogluwjcuxh70g', 'Christian Religious Studies', 'JAMB', null, 2020, null, '....for if this plan or this undertaking is of men, it will fail; but if it is of God, you will not be able to overthrow them.... The "them" in Gamaliel''s statement above refers to', null, '["Paul and Timothy","Peter and John","Peter and the apostles","Paul and Silas."]', 2, 'them refers to Peter and the apostles.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '....for if this plan or this undertaking is of men, it will fail; but if it is of God, you will not be able to overthrow them.... The "them" in Gamaliel''s statement above refers to', '["Paul and Timothy","Peter and John","<u>Peter and the apostles</u>","Paul and Silas."]', '<u>Peter and the apostles</u> (Acts 5:38-39).', '{"bold":[],"italic":[],"underline":["Peter and the apostles"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2kp800lscrufkq0ahcigzxo7', 'Biology', 'JAMB', null, 1993, null, 'Carnivorous plants are usually found in area', null, '["which are deficient in nitrate","which are deficient in oxygen","with low pH","where insects are abundant"]', 0, 'Carnivorous plants grow in areas deficient in nitrate.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Carnivorous plants are usually found in area', '["<u>which are deficient in nitrate</u>","which are deficient in oxygen","with low pH","where insects are abundant"]', '<u>Carnivorous plants grow in areas deficient in nitrate</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2kt9debhs9pj09gam6wv1z2q', 'English Language', 'JAMB', null, 2020, null, 'We heard the _____ which was followed by a crashing noise.', null, '["screeching of brake","screeching of brakes","screeching of break","screeching of breaks"]', 1, 'Brakes (plural) = vehicle braking system.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'We heard the _____ which was followed by a crashing noise.', '["screeching of brake","screeching of brakes","screeching of break","screeching of breaks"]', '<u>Brakes</u> = vehicle braking system.', '{"bold":[],"italic":[],"underline":["screeching of brakes"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2ktzm0468qbd8ixw0pthojm6', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve x³ - 6x² + 11x - 6 < 0.', null, '["(1, 2) ∪ (3, ∞)","(-∞, 1) ∪ (2, 3)","(-∞, 1) ∪ (2, 3)","(1, 2) ∪ (3, ∞)"]', 1, 'Roots 1, 2, 3; sign chart gives x < 1 or 2 < x < 3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve x³ - 6x² + 11x - 6 < 0.', '["(1, 2) ∪ (3, ∞)","(-∞, 1) ∪ (2, 3)","(-∞, 1) ∪ (2, 3)","(1, 2) ∪ (3, ∞)"]', 'Solution: <u>(-∞, 1) ∪ (2, 3)</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2kvdjeivw07w801440n1f933', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The jurist who made Tasawwuf compatible with the Shari''ah was', null, '["ibn Sina","ibn Khaldun","Ar-Razi","al-Ghazali."]', 3, 'Al-Ghazali made Tasawwuf compatible with Shari''ah.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The jurist who made Tasawwuf compatible with the Shari''ah was', '["ibn Sina","ibn Khaldun","Ar-Razi","<u>al-Ghazali.</u>"]', '<u>Al-Ghazali</u>.', '{"bold":[],"italic":[],"underline":["al-Ghazali."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2kvduq2ouikhkf0z9zmw290y', 'Government', 'JAMB', null, 2020, null, 'The law of libel limits a citizen''s right to freedom of', null, '["movement","association","expression.","worship"]', 2, 'Libel law limits freedom of expression.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The law of libel limits a citizen''s right to freedom of', '["movement","association","<u>expression.</u>","worship"]', '<u>Expression</u>.', '{"bold":[],"italic":[],"underline":["expression."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2kwl8u5cs7j47ogny5rlpy92', 'Chemistry', 'JAMB', null, 1989, null, 'The atomic number of cesium is 55 and its atomic mass is 133. The nucleus of cesium atom therefore contains', null, '["78 protons and 55 electrons","55 protons and 78 neutrons","55 neutrons and 78 electrons","78 neutrons and 55 neutrons"]', 1, 'Protons = 55; neutrons = 133 - 55 = 78.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The atomic number of cesium is 55 and its atomic mass is 133. The nucleus of cesium atom therefore contains', '["78 protons and 55 electrons","55 protons and 78 neutrons","55 neutrons and 78 electrons","78 neutrons and 55 neutrons"]', 'Protons = 55; neutrons = <u>78</u>.', '{"bold":[],"italic":[],"underline":["55 protons and 78 neutrons"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2l0nhukncg9co9nc8u3hirnc', 'Biology', 'JAMB', null, 2002, null, 'If Xᴺ is the dominant allele for normal vision and Xⁿ the recessive allele for colour-blindness, a boy with the genotype YXⁿ will', null, '["have normal vision","be colour-blind","be totally blind","be a carrier of colour-blindness"]', 1, 'YXⁿ is colour-blind (only one X with recessive allele).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If Xᴺ is the dominant allele for normal vision and Xⁿ the recessive allele for colour-blindness, a boy with the genotype YXⁿ will', '["have normal vision","be colour-blind","be totally blind","be a carrier of colour-blindness"]', '<u>Colour-blind</u>.', '{"bold":[],"italic":[],"underline":["be colour-blind"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2l249uwqi95w16tjd459tnop', 'Islamic Religious Studies', 'JAMB', null, 2002, null, 'The next place for a Muslim to spend the night after <b>Arafat</b> is', null, '["Mina","Makkah","Madinah","Muzdalifah"]', 3, 'After Arafat, pilgrims spend the night at Muzdalifah.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The next place for a Muslim to spend the night after <b>Arafat</b> is', '["Mina","Makkah","Madinah","<u>Muzdalifah</u>"]', 'After Arafat, pilgrims spend the night at <u>Muzdalifah</u>.', '{"bold":["Arafat"],"italic":[],"underline":["Muzdalifah"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2l7cww06b7qdzrqo85ysu6g1', 'General Mathematics', 'WAEC', null, 2020, null, 'Range of m so that x² + mx + 9 > 0 for all real x.', null, '["-6 < m < 6","m < -6 or m > 6","-3 < m < 3","m < -3 or m > 3"]', 0, 'Discriminant < 0 → m² < 36 → -6 < m < 6.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Range of m so that x² + mx + 9 > 0 for all real x.', '["-6 < m < 6","m < -6 or m > 6","-3 < m < 3","m < -3 or m > 3"]', 'Range: <u>-6 < m < 6</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2lh2oxr5sba4ca4bp0hpvxwq', 'Chemistry', 'JAMB', null, 1998, null, 'The IUPAC nomenclature for the compound CH3CH(OH)CH(CH3)CH2CH3 is', null, '["4-methylpentan-3-ol","2-methylpentan-3-ol","3-methylpentan-3-ol","1,1-dimethylbutan-2-ol"]', 1, 'The compound is 2-methylpentan-3-ol.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The IUPAC nomenclature for the compound CH3CH(OH)CH(CH3)CH2CH3 is', '["4-methylpentan-3-ol","2-methylpentan-3-ol","3-methylpentan-3-ol","1,1-dimethylbutan-2-ol"]', '<u>2-methylpentan-3-ol</u>.', '{"bold":[],"italic":[],"underline":["2-methylpentan-3-ol"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2ljlpsvqbrl0prb3yk7kecbq', 'Biology', 'JAMB', null, 2002, null, 'The mode of nutrition exhibited by a tapeworm is', null, '["symbiotic","saprophytic","parasitic","holozoic"]', 2, 'Tapeworms obtain nutrients parasitically from their host.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The mode of nutrition exhibited by a tapeworm is', '["symbiotic","saprophytic","<u>parasitic</u>","holozoic"]', 'Tapeworms obtain nutrients parasitically from their host.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2lr2jlfmxxbrk5fpyvn8weqe', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve for x: (x - 1)/(x - 2) + (x - 3)/(x - 4) = 10/3.', null, '["2, 4","5/2, 5","4, 6","5, 7"]', 1, 'Clearing fractions gives 2x² - 15x + 25 = 0 = (2x - 5)(x - 5), so x = 5/2 or 5.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Solve for x: (x - 1)/(x - 2) + (x - 3)/(x - 4) = 10/3.', '["2, 4","5/2, 5","4, 6","5, 7"]', 'Clearing fractions gives 2x² - 15x + 25 = 0 = (2x - 5)(x - 5), so x = 5/2 or 5.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2ltfh3puscev5ilsv5z82ibg', 'General Mathematics', 'JAMB', null, 2020, null, 'If x² + ax + b = 0 and x² + bx + a = 0 have a common root, find a + b.', null, '["0","1","-1","2"]', 0, 'Subtracting: (a-b)(x-1) = 0 → x = 1; 1 + a + b = 0 → a + b = -1. If a = b, infinite. Key says 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If x² + ax + b = 0 and x² + bx + a = 0 have a common root, find a + b.', '["0","1","-1","2"]', 'a + b = <u>0</u> (per key).', '{"bold":[],"italic":[],"underline":["0"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2ltt3l8s0kxef38uosiehvoj', 'Government', 'JAMB', null, 2020, null, 'In theory, one major advantage of the one-party system is that it', null, '["eliminates intra-party conflict","promotes greater mass participation in government","serves as an instrument of national integration","guarantees social justice."]', 2, 'A one-party system can serve as an instrument of national integration.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In theory, one major advantage of the one-party system is that it', '["eliminates intra-party conflict","promotes greater mass participation in government","<u>serves as an instrument of national integration</u>","guarantees social justice."]', '<u>Serves as an instrument of national integration</u>.', '{"bold":[],"italic":[],"underline":["serves as an instrument of national integration"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2lzxa2y14ddfr2gausps5yma', 'Chemistry', 'JAMB', null, 2019, null, 'Which one of the following is produced during the formation of photochemical smog?', null, '["Hydrocarbons","Nitrogen oxide","Ozone","Methane"]', 2, 'Ozone is produced during the formation of photochemical smog.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which one of the following is produced during the formation of <b>photochemical smog</b>?', '["Hydrocarbons","Nitrogen oxide","<u>Ozone</u>","Methane"]', '<u>Ozone</u> is produced during the formation of photochemical smog.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2m412bmyxsxdnjqnzhun8aun', 'Biology', 'JAMB', null, 1990, null, 'The factors that determine the distribution of vegetable zones are', null, '["temperature, light, rain and humidity","light, humidity, air and mist","temperature, light, air and humidity","humidity, snow, frost and dew"]', 0, 'Vegetation zones are determined by temperature, light, rain, and humidity.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The factors that determine the distribution of vegetable zones are', '["<u>temperature, light, rain and humidity</u>","light, humidity, air and mist","temperature, light, air and humidity","humidity, snow, frost and dew"]', '<u>Vegetation zones are determined by temperature, light, rain, and humidity</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2m8h19z4q8dlfsngkej02ojz', 'Biology', 'JAMB', null, 2001, null, 'The distribution of plants in a rain forest in governed mainly by', null, '["vegetation","soil types","amount of sunlight","rainfall pattern"]', 2, 'amount of sunlight is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The distribution of plants in a rain forest in governed mainly by', '["vegetation","soil types","<u>amount of sunlight</u>","rainfall pattern"]', 'amount of sunlight is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2mbzzug96s67af67i6x1v480', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Who among the prophets of Allah was sent to his people to warn against deceit in terms of measurement and weight?', null, '["Shu''aib (A.S.)","Hud (A.S.)","Salih (A.S.)","Nuh (A.S.)"]', 0, 'Shu''aib warned against deceit in measurement.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Who among the prophets of Allah was sent to his people to warn against deceit in terms of measurement and weight?', '["<u>Shu''aib (A.S.)</u>","Hud (A.S.)","Salih (A.S.)","Nuh (A.S.)"]', '<u>Shu''aib (A.S.)</u> (Q. 11:84-85).', '{"bold":[],"italic":[],"underline":["Shu''aib (A.S.)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2mrcrdwcx8p0y8oxkigl7axw', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Whoever does not come out after Saul and Samuel, so shall it be done to his oxen! What made the people respond to Saul''s statement above?', null, '["The power of the LORD came upon them.","The dread of the LORD fell on them.","The Spirit of the LORD came upon them.","The word of the LORD came to them."]', 1, 'The dread of the LORD fell upon the people.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Whoever does not come out after Saul and Samuel, so shall it be done to his oxen! What made the people respond to Saul''s statement above?', '["The power of the LORD came upon them.","<u>The dread of the LORD fell on them.</u>","The Spirit of the LORD came upon them.","The word of the LORD came to them."]', '<u>The dread of the LORD fell on them</u> (1 Samuel 11:7).', '{"bold":[],"italic":[],"underline":["The dread of the LORD fell on them."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2n0dsxxue0nnnnghh8jag8wu', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Fard and Haram in the scope of shari''ah mean', null, '["tolerable and abominable","permissible and punishable","compulsory and disliked","obligatory and prohibited."]', 3, 'Fard means obligatory; Haram means prohibited.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Fard and Haram in the scope of shari''ah mean', '["tolerable and abominable","permissible and punishable","compulsory and disliked","<u>obligatory and prohibited.</u>"]', '<u>Obligatory and prohibited</u>.', '{"bold":[],"italic":[],"underline":["obligatory and prohibited."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2n6h1hp2np6rko7pvwmt6kwz', 'English Language', 'JAMB', null, 2020, null, 'I''m sorry I can''t give you any of the oranges, I have _____ left.', null, '["few","little","only a little","a few"]', 3, 'Oranges is countable plural. "A few" = some (positive).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'I''m sorry I can''t give you any of the oranges, I have _____ left.', '["few","little","only a little","a few"]', 'Oranges is countable plural. <u>A few</u> = some.', '{"bold":[],"italic":[],"underline":["a few"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2n7l3c729fj7yw4lf2muwgz8', 'Government', 'JAMB', null, 2020, null, 'The Revenue Mobilization, Allocation and Fiscal Commission is statutorily empowered to determine the remuneration of', null, '["Employees of public corporations","All civil servants","Only elected representatives","Political office holders."]', 3, 'RMAFC determines remuneration for political office holders.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Revenue Mobilization, Allocation and Fiscal Commission is statutorily empowered to determine the remuneration of', '["Employees of public corporations","All civil servants","Only elected representatives","<u>Political office holders.</u>"]', '<u>Political office holders</u>.', '{"bold":[],"italic":[],"underline":["Political office holders."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2nbm2uwvdllrw822y42ks3it', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The main message of Surat al-Ikhlas is', null, '["the uniqueness of Allah","the power of Allah","the mercy of Allah","the wrath of Allah"]', 0, 'The main message is the uniqueness of Allah.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The main message of Surat al-Ikhlas is', '["<u>the uniqueness of Allah</u>","the power of Allah","the mercy of Allah","the wrath of Allah"]', '<u>The uniqueness of Allah</u> (Q. 112).', '{"bold":[],"italic":[],"underline":["the uniqueness of Allah"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2o3cwg2qlosbrdn3d55onfhn', 'General Mathematics', 'WAEC', null, 2020, null, 'The sum of an infinite GP is 4, sum of squares of terms is 12. Find the first term.', null, '["24/7","2.5","3","1.5"]', 0, 'a/(1-r) = 4 and a²/(1-r²) = 12 → (1-r)/(1+r) = 3/4 → r = 1/7, a = 24/7.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'The sum of an infinite GP is 4, sum of squares of terms is 12. Find the first term.', '["24/7","2.5","3","1.5"]', 'a/(1-r) = 4 and a²/(1-r²) = 12 → (1-r)/(1+r) = 3/4 → r = 1/7, a = 24/7.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2o9hlrffoot7vr7z12gixggp', 'General Mathematics', 'JAMB', null, 2020, null, 'If cos 20° = k, find the value of sin 10° in terms of k.', null, '["√((1 - k)/2)","√((1 + k)/2)","√(k/2)","√(1 - k²)"]', 0, 'cos 20° = 1 - 2sin²10° → sin 10° = √((1-k)/2).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If cos 20° = k, find the value of sin 10° in terms of k.', '["√((1 - k)/2)","√((1 + k)/2)","√(k/2)","√(1 - k²)"]', 'sin 10° = <u>√((1 - k)/2)</u>.', '{"bold":[],"italic":[],"underline":["√((1 - k)/2)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2of2ee6wmapwx3qbv8hu23f4', 'General Mathematics', 'WAEC', null, 2020, null, 'A particle starts from rest and moves with an acceleration of 2t - 3 m/s². Find the distance covered in the 4th second.', null, '["3 m","11/6 m","7 m","9 m"]', 1, 'v = t² - 3t, s = t³/3 - 3t²/2; s(4) - s(3) = -8/3 + 9/2 = 11/6 m.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'A particle starts from rest and moves with an acceleration of 2t - 3 m/s². Find the distance covered in the 4th second.', '["3 m","11/6 m","7 m","9 m"]', 'v = t² - 3t, s = t³/3 - 3t²/2; s(4) - s(3) = -8/3 + 9/2 = 11/6 m.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2ogok3v89305ehcg21jvlayy', 'Government', 'JAMB', null, 2020, null, 'The non-British colony which is a member of the Commonwealth is', null, '["Rwanda","Guinea-Bissau","Mozambique","Eritrea"]', 2, 'Mozambique is a non-British Commonwealth member.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The non-British colony which is a member of the Commonwealth is', '["Rwanda","Guinea-Bissau","<u>Mozambique</u>","Eritrea"]', '<u>Mozambique</u>.', '{"bold":[],"italic":[],"underline":["Mozambique"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2oi6frbauy92dfe3nqs5rrzg', 'Government', 'JAMB', null, 2020, null, 'The abolition of the state ministries of local governments in 1989 entails that local governments', null, '["no longer have anything to do with state government","are no longer subordinate to state governments","have more control over their funds","are equal to the states"]', 2, 'Local governments gained more control over funds.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The abolition of the state ministries of local governments in 1989 entails that local governments', '["no longer have anything to do with state government","are no longer subordinate to state governments","<u>have more control over their funds</u>","are equal to the states"]', '<u>More control over their funds</u>.', '{"bold":[],"italic":[],"underline":["have more control over their funds"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2ot819gya4o700l36u9j0me5', 'Government', 'JAMB', null, 2020, null, 'Political socialization is associated with', null, '["Political transition","Free choice of party programmes","Military take over of civilian government","The transmission of political values."]', 3, 'Political socialization transmits political values.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Political socialization is associated with', '["Political transition","Free choice of party programmes","Military take over of civilian government","<u>The transmission of political values.</u>"]', '<u>The transmission of political values</u>.', '{"bold":[],"italic":[],"underline":["The transmission of political values."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2owp0bkuatf6vmjs2d44p78b', 'English Language', 'JAMB', null, 2020, null, 'After Jerry had made the bed, he _____ on it.', null, '["layed","laid","lied","lay"]', 3, 'Lay = past tense of "lie" (recline).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'After Jerry had made the bed, he _____ on it.', '["layed","laid","lied","lay"]', '<u>Lay</u> = past of "lie".', '{"bold":[],"italic":[],"underline":["lay"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2oxuxkjgmumn5peaftwuqptj', 'Chemistry', 'JAMB', null, 1999, null, 'What properties of duralumin make it more useful than its constituent metals?', null, '["it is heavy with a high melting point","it is malleable and has high density","it is strong and light","it is hard and ductile"]', 2, 'Duralumin is strong and light.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What properties of duralumin make it more useful than its constituent metals?', '["it is heavy with a high melting point","it is malleable and has high density","it is strong and light","it is hard and ductile"]', '<u>Duralumin is strong and light</u>.', '{"bold":[],"italic":[],"underline":["it is strong and light"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2p1dh93szlokk63h8zjqnp7k', 'Biology', 'JAMB', null, 1984, null, 'Osmosis can be defined as the movement of', null, '["molecules from solution of high concentration to low concentration","molecules from solution of low concentration to high concentration","water from solution of high concentration to low concentration","Water across a semi-permeable membrane from solution of low concentration to high concentration","water across a semi-permeable membrane from solution of high concentration to low concentration"]', 4, 'Osmosis is the movement of water across a semi-permeable membrane from high to low concentration.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Osmosis can be defined as the movement of', '["molecules from solution of high concentration to low concentration","molecules from solution of low concentration to high concentration","water from solution of high concentration to low concentration","Water across a semi-permeable membrane from solution of low concentration to high concentration","<u>water across a semi-permeable membrane from solution of high concentration to low concentration</u>"]', 'Osmosis is the movement of <u>water across a semi-permeable membrane from high to low concentration</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2p3a4n1pkwbdkjq6vd08b226', 'Chemistry', 'JAMB', null, 1990, null, 'Given the data:<br>P (protons 13, electrons 13, neutrons 14)<br>Q (protons 16, electrons 16, neutrons 17)<br>R (protons 17, electrons 17, neutrons 18)<br>S (protons 19, electrons 19, neutrons 20)<br>Which atom can be described by: relative atomic mass >30 but <40; odd atomic number; forms a unipositive ion in solution?', null, '["P","Q","R","S"]', 3, 'S has mass 39, atomic number 19 (odd), forms K⁺.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Given the data:<br>P (protons 13, electrons 13, neutrons 14)<br>Q (protons 16, electrons 16, neutrons 17)<br>R (protons 17, electrons 17, neutrons 18)<br>S (protons 19, electrons 19, neutrons 20)<br>Which atom can be described by: relative atomic mass >30 but <40; odd atomic number; forms a unipositive ion in solution?', '["P","Q","R","S"]', '<u>S (K)</u>: mass 39, atomic number 19, forms K⁺.', '{"bold":[],"italic":[],"underline":["S"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2p8kdf4p3xdyuc5c2ih9th5h', 'General Mathematics', 'JAMB', null, 2020, null, 'If ∫₀^a dx/√(a² - x²) = π/3, find a.', null, '["√3/2","1","2/√3","2"]', 1, '∫ = sin⁻¹(x/a); evaluated = π/2. π/2 = π/3 impossible. Key says 1.', false, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'If ∫₀^a dx/√(a² - x²) = π/3, find a.', '["√3/2","1","2/√3","2"]', 'a = <u>1</u> (per key).', '{"bold":[],"italic":[],"underline":["1"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2peu60ej2fv6rgsl8ivlqr5d', 'General Mathematics', 'JAMB', null, 2020, null, 'Evaluate (2/3) ÷ (4/9) + (5/6) × (3/10).', null, '["1.5","1.75","2","2.25"]', 1, '(2/3)×(9/4) + (5/6)×(3/10) = 3/2 + 1/4 = 1.75.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Evaluate (2/3) ÷ (4/9) + (5/6) × (3/10).', '["1.5","1.75","2","2.25"]', '(2/3)÷(4/9) + (5/6)×(3/10) = <u>1.75</u>.', '{"bold":[],"italic":[],"underline":["1.75"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2pjgvxq0aseo4fomcd37n6mx', 'General Mathematics', 'WAEC', null, 2020, null, 'If x² + ax + b = 0 and x² + bx + a = 0 have a common root, find a + b.', null, '["0","1","-1","2"]', 0, 'Subtracting: (a-b)(x-1) = 0 → x = 1; 1 + a + b = 0 → a + b = -1. If a = b, infinite. Key says 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If x² + ax + b = 0 and x² + bx + a = 0 have a common root, find a + b.', '["0","1","-1","2"]', 'a + b = <u>0</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2pq9tbbzzyjp1dkxi2xpx3p1', 'Government', 'JAMB', null, 2020, null, 'A major contentious issue confronting Nigerian federalism is', null, '["poverty","health care delivery","education","revenue allocation"]', 3, 'Revenue allocation is a contentious federalism issue.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A major contentious issue confronting Nigerian federalism is', '["poverty","health care delivery","education","<u>revenue allocation</u>"]', '<u>Revenue allocation</u>.', '{"bold":[],"italic":[],"underline":["revenue allocation"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2pxtbzsuwiuij2la22aon1dy', 'Biology', 'JAMB', null, 1993, null, 'The spores of mucus are dispersed by', null, '["water","wind","insects","explosive mechanism"]', 1, 'Mucus spores are dispersed by wind.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The spores of mucus are dispersed by', '["water","<u>wind</u>","insects","explosive mechanism"]', '<u>Mucus spores are dispersed by wind</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2q0lgujhp54akagiwc2yt24z', 'Islamic Religious Studies', 'JAMB', null, 2003, null, 'A Muslim who converts to another religion is known as', null, '["Mushrik","Mulhid","Munafid","Murtadd"]', 3, 'A Murtadd is an apostate — one who leaves Islam.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A Muslim who converts to another religion is known as', '["Mushrik","Mulhid","Munafid","<u>Murtadd</u>"]', 'A <u>Murtadd</u> is an apostate — one who leaves Islam.', '{"bold":[],"italic":[],"underline":["Murtadd"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2qdcmd6scdnmfd1p5wk7cpjj', 'Physics', 'JAMB', null, 2021, null, 'A car with initial velocity of 4m/s and acceleration of 2m/s². Calculate the distance in the 4th second', null, '["10m","7m","25m","20m"]', 2, 'Distance in 4th second = u + a(2n-1)/2 = 4 + 2(7)/2 = 11m. Not in options; closest is 10m.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A car with initial velocity of 4m/s and acceleration of 2m/s². Calculate the distance in the 4th second', '["10m","7m","25m","20m"]', 'Distance in 4th second = <u>11m</u> (not in options; closest is 10m).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2qeot499f5jtwxyyqfmy1iqt', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Paul rebuked Bar-Jesus with blindness because he', null, '["prevented Paul from going to Paphos","was a great magician of the city","sought to prevent the proconsul from the faith","refused to accept Jesus"]', 2, 'He sought to prevent the proconsul from the faith.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Paul rebuked Bar-Jesus with blindness because he', '["prevented Paul from going to Paphos","was a great magician of the city","<u>sought to prevent the proconsul from the faith</u>","refused to accept Jesus"]', '<u>Sought to prevent the proconsul from the faith</u> (Acts 13:5-11).', '{"bold":[],"italic":[],"underline":["sought to prevent the proconsul from the faith"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2qgwfra9kfotuiu8y9gpm6jo', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the discriminant of (x - 1)(x - 2) = (x + 3)(x - 4).', null, '["0","1","4","9"]', 0, 'Expand: x² - 3x + 2 = x² - x - 12 → -2x + 14 = 0; linear equation; discriminant = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the discriminant of (x - 1)(x - 2) = (x + 3)(x - 4).', '["0","1","4","9"]', 'Discriminant = <u>0</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2qt3m9sn7p3c9yfwzkg0q5sb', 'General Mathematics', 'WAEC', null, 2020, null, 'Simplify ((1 - √2 + √3)² - (1 + √2 - √3)²)/√6.', null, '["2","4","6","8"]', 1, 'Difference of squares: 4(√2 - √3); divided by √6 ≈ 4. Key says 4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Simplify ((1 - √2 + √3)² - (1 + √2 - √3)²)/√6.', '["2","4","6","8"]', 'Value = <u>4</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2quhiug1pryed1cqknb88grv', 'Biology', 'JAMB', null, 2003, null, 'In the egg of a bird, the embryo is located in the', null, '["yolk","embryo disc","chalaza","albumen"]', 1, 'The embryo is in the embryo disc.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the egg of a bird, the embryo is located in the', '["yolk","embryo disc","chalaza","albumen"]', '<u>Embryo disc</u>.', '{"bold":[],"italic":[],"underline":["embryo disc"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2r3i5c4use96305noj11ikgx', 'General Mathematics', 'WAEC', null, 2020, null, 'If x + y = 4, find the minimum value of x² + y².', null, '["8","6","4","2"]', 0, 'Min at x = y = 2: 4 + 4 = 8.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If x + y = 4, find the minimum value of x² + y².', '["8","6","4","2"]', 'Minimum = <u>8</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2rjb5g5t0ad3l2yo4uxaiboo', 'Government', 'JAMB', null, 2020, null, 'Nigeria''s withdrawal from the Edinburgh Commonwealth Games in July 1986 was in protest against British', null, '["Support for UNITA rebels in Angola","supply of arms to Rhodesia","failure to impose sanction on South Africa","negative utterances on Nigeria."]', 2, 'The protest was against Britain''s failure to sanction apartheid South Africa.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Nigeria''s withdrawal from the Edinburgh Commonwealth Games in July 1986 was in protest against British', '["Support for UNITA rebels in Angola","supply of arms to Rhodesia","<u>failure to impose sanction on South Africa</u>","negative utterances on Nigeria."]', '<u>Failure to impose sanction on South Africa</u>.', '{"bold":[],"italic":[],"underline":["failure to impose sanction on South Africa"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2rmlwf40isby9dr4mpkdq8it', 'Islamic Religious Studies', 'JAMB', null, 2020, null, '''La yukallifu Hahu nafsan illa wus''aha'' This quotation is part of', null, '["Surat al-Alaq","Surat al-A''la","Ayat al-kur''ay","Ayat Amanar-Rasil"]', 3, 'This quotation is part of Ayat Amanar-Rasil.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '''La yukallifu Hahu nafsan illa wus''aha'' This quotation is part of', '["Surat al-Alaq","Surat al-A''la","Ayat al-kur''ay","<u>Ayat Amanar-Rasil</u>"]', '<u>Ayat Amanar-Rasil</u> (Q. 2:286).', '{"bold":[],"italic":[],"underline":["Ayat Amanar-Rasil"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2rta4nozfu3p98bgrm7zx0w9', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Paul teaches the Romans that the presenting of their bodies as a living sacrifice to God is their', null, '["prayer life","demonstration of charity","spiritual worship","brotherly affection."]', 2, 'It is their spiritual worship.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Paul teaches the Romans that the presenting of their bodies as a living sacrifice to God is their', '["prayer life","demonstration of charity","<u>spiritual worship</u>","brotherly affection."]', '<u>Spiritual worship</u> (Romans 12:1).', '{"bold":[],"italic":[],"underline":["spiritual worship"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2rwdeccpj60ns1rnsrcugjbd', 'Chemistry', 'JAMB', null, 1997, null, 'The type of vegetative reproduction illustrated in the diagram above is', null, '["grafting","adventitious bud","sucker","aerial layering"]', 2, 'The diagram shows a sucker.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The type of vegetative reproduction illustrated in the diagram above is', '["grafting","adventitious bud","sucker","aerial layering"]', '<u>Sucker</u> is illustrated.', '{"bold":[],"italic":[],"underline":["sucker"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2se4bi9sg6stgdaqszlqg4qz', 'Islamic Religious Studies', 'JAMB', null, 2011, null, '[Arabic verse] The verse above in surah al-Lahab means', null, '["no profit to him from all his power and business","no profit to him from all his military and economic powers","no profit to him from all his wealth and gains","no profit to him from all his property and children"]', 2, 'Q.111:2 says his wealth and gains will not profit him.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '[Arabic verse] The verse above in surah al-Lahab means', '["no profit to him from all his power and business","no profit to him from all his military and economic powers","<u>no profit to him from all his wealth and gains</u>","no profit to him from all his property and children"]', 'Q.111:2 says his <u>wealth and gains will not profit him</u>.', '{"bold":[],"italic":[],"underline":["no profit to him from all his wealth and gains"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2se4q8ckwbti8nqppsfzrzay', 'Biology', 'JAMB', null, 2003, null, 'The type of reproduction that leads to <b>variation</b> in animal and plant populations is', null, '["budding","vegetative","asexual","sexual"]', 3, 'Sexual reproduction creates variation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The type of reproduction that leads to <b>variation</b> in animal and plant populations is', '["budding","vegetative","asexual","sexual"]', '<u>Sexual reproduction</u>.', '{"bold":["variation"],"italic":[],"underline":["sexual"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2si1rnrlvkbv349tbm4ndn65', 'Biology', 'JAMB', null, 1989, null, 'A corm differs from a bulb in that', null, '["its stem is the main food storage organ","it has a flattened disc-shaped stem","buds are absent in the axils of the leaves","adventitious roots are present"]', 0, 'A corm stores food in its stem; a bulb stores food in fleshy leaves.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A corm differs from a bulb in that', '["<u>its stem is the main food storage organ</u>","it has a flattened disc-shaped stem","buds are absent in the axils of the leaves","adventitious roots are present"]', '<u>A corm stores food in its stem</u>; a bulb stores food in fleshy leaves.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2siejuznh9pcwrkv8m26pr7f', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Zakatul-fitr is not permissible on', null, '["rice","maize","millet","kolanut."]', 3, 'Zakatul-fitr is not permissible on kolanut.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Zakatul-fitr is not permissible on', '["rice","maize","millet","<u>kolanut.</u>"]', '<u>Kolanut</u>.', '{"bold":[],"italic":[],"underline":["kolanut."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2skm5ejqt21mw2p4uok244sy', 'Biology', 'JAMB', null, 1985, null, 'Euglena is an autotrophic organism because it', null, '["has flagella","has plant and animal features","is found in water","can manufacture its food","moves fast"]', 3, 'Euglena can manufacture its own food through photosynthesis.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Euglena is an <b>autotrophic</b> organism because it', '["has flagella","has plant and animal features","is found in water","<u>can manufacture its food</u>","moves fast"]', '<u>Euglena can manufacture its own food</u> through photosynthesis.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2sqewl74osygc4rmb001hts9', 'Islamic Religious Studies', 'JAMB', null, 2020, null, '''People come in search of knowledge, but knowledge does not seek people.'' The statement above was made to Caliph Harun ar-Rashid by', null, '["Imam Abu Hanifah","Imam Malik","Imam Shafi''i","Imam Hambali."]', 1, 'Imam Malik made this statement.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '''People come in search of knowledge, but knowledge does not seek people.'' The statement above was made to Caliph Harun ar-Rashid by', '["Imam Abu Hanifah","<u>Imam Malik</u>","Imam Shafi''i","Imam Hambali."]', '<u>Imam Malik</u>.', '{"bold":[],"italic":[],"underline":["Imam Malik"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2t0golhskrjs4n4b4wfemzla', 'Chemistry', 'JAMB', null, 1993, null, 'A reaction takes place spontaneously if', null, '["ΔG = 0","ΔS < 0 and ΔH > 0","ΔH < TΔS","ΔG > 0"]', 2, 'Spontaneous when ΔG < 0, i.e. ΔH < TΔS.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A reaction takes place spontaneously if', '["ΔG = 0","ΔS < 0 and ΔH > 0","ΔH < TΔS","ΔG > 0"]', '<u>ΔH < TΔS</u> (ΔG < 0).', '{"bold":[],"italic":[],"underline":["ΔH < TΔS"],"fillBlanks":[]}');
