insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2thzmfiswtxylcoe3spw86ws', 'Biology', 'JAMB', null, 2003, null, 'The most important hormone that induces the ripening of fruit is', null, '["Cytokinin","Indole acetic acid","Ethylene","Gibberellin"]', 2, 'Ethylene is the plant hormone most strongly associated with fruit ripening.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The most important hormone that induces the ripening of fruit is', '["Cytokinin","Indole acetic acid","<u>Ethylene</u>","Gibberellin"]', 'Ethylene is the plant hormone most strongly associated with fruit ripening.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2tj3fl8edzf6tf0swurpk59f', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'According to John, the accusation the Jews levelled against Jesus before Pilate was that He was', null, '["an evildoer","an impostor","a perverter","a blasphemer."]', 0, 'The Jews accused Jesus of being an evildoer.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to John, the accusation the Jews levelled against Jesus before Pilate was that He was', '["<u>an evildoer</u>","an impostor","a perverter","a blasphemer."]', '<u>An evildoer</u> (John 18:29-30).', '{"bold":[],"italic":[],"underline":["an evildoer"],"fillBlanks":[]}');
