insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2tku0e0pcmqaj42gmrf4ja8o', 'General Mathematics', 'JAMB', null, 2020, null, 'Find 1.3 + 0.6.', null, '["2","1.9","2.1","2.3"]', 0, '1.3 + 0.6 = 1.9. Wait, 0.6 repeating? 1.3 + 0.6 = 1.9. Key says 2 (if 0.6̅ = 2/3).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find 1.3 + 0.6.', '["2","1.9","2.1","2.3"]', '1.3 + 0.6 = <u>1.9</u> (key says 2).', '{"bold":[],"italic":[],"underline":["2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2tq4kxsu3w6zb886mk0tsded', 'Biology', 'JAMB', null, 1986, null, 'If a person is bitten by a snake on the leg, it is advisable for the person', null, '["keep moving so that the venom will ooze out with bleeding","wash the wound with water containing antiseptic","bandage the wound so that germs do not get in through it","keep still and apply a tourniquet above the wound"]', 3, 'Keep still and apply a tourniquet above the wound to slow venom spread.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If a person is bitten by a snake on the leg, it is advisable for the person', '["keep moving so that the venom will ooze out with bleeding","wash the wound with water containing antiseptic","bandage the wound so that germs do not get in through it","<u>keep still and apply a tourniquet above the wound</u>"]', '<u>Keep still and apply a tourniquet above the wound</u> to slow venom spread.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2txhggct325l41hg9vx66r3c', 'Biology', 'JAMB', null, 1998, null, 'In which of the following groups of animals is the Malpighian tubule found?', null, '["Lizards, snakes and frogs","Crickets, houseflies and grasshoppers","Millipedes, centipedes and scorpions","Earthworms, roundworms and flatworms."]', 1, 'Malpighian tubules are the principal excretory structures of insects.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In which of the following groups of animals is the Malpighian tubule found?', '["Lizards, snakes and frogs","<u>Crickets, houseflies and grasshoppers</u>","Millipedes, centipedes and scorpions","Earthworms, roundworms and flatworms."]', 'Malpighian tubules are the principal excretory structures of insects.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2tykxrt6vguqs6plihnoainx', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'On the Day of Judgement, man will be questioned about the joy he indulged in. This is contained in Surah', null, '["al-Takathur","al-Asr","al-Qari''ah","al-Ma''un"]', 1, 'It is contained in Surat al-Asr.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'On the Day of Judgement, man will be questioned about the joy he indulged in. This is contained in Surah', '["al-Takathur","<u>al-Asr</u>","al-Qari''ah","al-Ma''un"]', '<u>Al-Asr</u>.', '{"bold":[],"italic":[],"underline":["al-Asr"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2u1xg73dylw36t443n7eamrr', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve 5x ≡ 4 (mod 7).', null, '["5","6","2","3"]', 1, '5×6 = 30 ≡ 2 mod 7. 5×5 = 25 ≡ 4 mod 7. So x = 5. Key says 6.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve 5x ≡ 4 (mod 7).', '["5","6","2","3"]', '5×5 = 25 ≡ <u>4</u> mod 7 → x = 5 (key says 6).', '{"bold":[],"italic":[],"underline":["6"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2u52cw13hnzr8st1sg1nj0d3', 'Biology', 'JAMB', null, 2000, null, 'The set of fins that controls steering, balancing and change of direction and pitch in fish is', null, '["dorsal and anal","pectoral and pelvic","caudal and dorsal","anal and pelvic"]', 1, 'pectoral and pelvic is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The set of fins that controls steering, balancing and change of direction and pitch in fish is', '["dorsal and anal","<u>pectoral and pelvic</u>","caudal and dorsal","anal and pelvic"]', 'pectoral and pelvic is the best answer because it matches the biological principle tested by the question.', null);
