insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2v0feqqkxzian1tph1a6j9uy', 'Biology', 'JAMB', null, 2000, null, 'The part of the brain that controls <b>body posture</b> in mammals is the', null, '["thalamus","cerebrum","spinal cord","cerebellum"]', 3, 'The cerebellum controls body posture.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The part of the brain that controls <b>body posture</b> in mammals is the', '["thalamus","cerebrum","spinal cord","cerebellum"]', '<u>Cerebellum controls body posture</u>.', '{"bold":["body posture"],"italic":[],"underline":["cerebellum"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2vign3jwlcecnx05ey9eep26', 'General Mathematics', 'WAEC', null, 2020, null, 'Find ∫ dx/(x ln x).', null, '["ln","ln x","+ C","1/ln x + C","ln x + C","1/x + C"]', 0, 'Let u = ln x; ∫du/u = ln|ln x| + C.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find ∫ dx/(x ln x).', '["ln","ln x","+ C","1/ln x + C","ln x + C","1/x + C"]', 'Integral = <u>ln|ln x| + C</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2vzu5k5lzpa1c3j0ijkktun9', 'Chemistry', 'JAMB', null, 1990, null, 'Coal fire should not be used in poorly ventilated rooms because', null, '["of the accumulation of CO2 which causes deep sleep","it is usually too hot","of the accumulation of CO which causes suffocation","it removes most of the gases in the room"]', 2, 'CO from incomplete combustion causes suffocation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Coal fire should not be used in poorly ventilated rooms because', '["of the accumulation of CO2 which causes deep sleep","it is usually too hot","of the accumulation of CO which causes suffocation","it removes most of the gases in the room"]', '<u>CO accumulation causes suffocation</u>.', '{"bold":[],"italic":[],"underline":["of the accumulation of CO which causes suffocation"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2w9b6tmuj1d1yyy4ctdvsrx2', 'Chemistry', 'JAMB', null, 1983, null, 'Which among the elements 1. Carbon 2. Oxygen 3. Copper 4. Bromine 5. Zinc will <b>NOT react</b> with either water or steam?', null, '["1 and 2","2 and 3","3 and 4","1, 2, and 3","2, 3 and 5"]', 2, 'Copper and bromine do not react with water or steam.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which among the elements 1. Carbon 2. Oxygen 3. Copper 4. Bromine 5. Zinc will <b>NOT react</b> with either water or steam?', '["1 and 2","2 and 3","3 and 4","1, 2, and 3","2, 3 and 5"]', '<u>Copper and bromine</u> do not react with water or steam.', '{"bold":["NOT react"],"italic":[],"underline":["3 and 4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2wak29cgxrtj45p484xg7k2a', 'Biology', 'JAMB', null, 2002, null, 'Plants tend to prevent overcrowding by means of efficient', null, '["water uptake","seed germination","pollination","seed dispersal"]', 3, 'seed dispersal is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Plants tend to prevent overcrowding by means of efficient', '["water uptake","seed germination","pollination","<u>seed dispersal</u>"]', 'seed dispersal is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2wlbx2t4mhg19f9mn0un99bz', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Go from your country and your kindred and your father''s house to the land that I will show you ... Where was Abram when this command was given?', null, '["Haran","Ur","Shechem","Bethel."]', 0, 'Abram was at Haran when this command was given.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Go from your country and your kindred and your father''s house to the land that I will show you ... Where was Abram when this command was given?', '["<u>Haran</u>","Ur","Shechem","Bethel."]', '<u>Haran</u> (Genesis 12:4).', '{"bold":[],"italic":[],"underline":["Haran"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2wllzfpr7wxt854zpewiino0', 'Chemistry', 'JAMB', null, 1992, null, 'S2O3²⁻ + I2 → S4O6²⁻ + 2I⁻. In the reaction above, the oxidizing agent is', null, '["S2O3²⁻","I2","S4O6²⁻","I⁻"]', 1, 'I2 is reduced to I⁻, so it is the oxidizing agent.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'S2O3²⁻ + I2 → S4O6²⁻ + 2I⁻. In the reaction above, the oxidizing agent is', '["S2O3²⁻","I2","S4O6²⁻","I⁻"]', '<u>I2 is reduced</u>, so it is the oxidizing agent.', '{"bold":[],"italic":[],"underline":["I2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2wtvxdnxixfn442myetaox73', 'General Mathematics', 'WAEC', null, 2020, null, 'A bag contains 5 red, 4 blue, and 3 green balls. Three balls are drawn at random without replacement. What is the probability that they are all of different colors?', null, '["1/11","3/11","5/11","10/11"]', 1, 'P = (5·4·3)/12C3 = 60/220 = 3/11.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A bag contains 5 red, 4 blue, and 3 green balls. Three balls are drawn at random without replacement. What is the probability that they are all of different colors?', '["1/11","3/11","5/11","10/11"]', 'P = <u>3/11</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2wupan2p7txj4bbbnkn6gcli', 'Biology', 'JAMB', null, 1993, null, 'In the mammal, the autonomic nervous system consists of', null, '["sympathetic and parasympathetic systems","brain and spinal nerves","brain and cranial nerves","spinal cord and spinal nerves"]', 0, 'The autonomic nervous system consists of sympathetic and parasympathetic systems.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the mammal, the <b>autonomic nervous system</b> consists of', '["<u>sympathetic and parasympathetic systems</u>","brain and spinal nerves","brain and cranial nerves","spinal cord and spinal nerves"]', 'The <u>autonomic nervous system consists of sympathetic and parasympathetic systems</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2x2h2tgd0ox0thmwtf5x44rw', 'General Mathematics', 'WAEC', null, 2020, null, 'If log a, log b, log c are in AP, then a, b, c are in:', null, '["AP","GP","HP","None"]', 1, 'log a + log c = 2 log b → ac = b² → GP.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If log a, log b, log c are in AP, then a, b, c are in:', '["AP","GP","HP","None"]', 'a, b, c are in <u>GP</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2x3ohmdedep2ysehyvk14zz3', 'Chemistry', 'JAMB', null, 1996, null, 'Ethene when passed into concentrated H2SO4 is rapidly absorbed. The product is diluted with water and then warmed to produce', null, '["ethanol","diethyl ether","ethanal","diethyl sulphate"]', 0, 'Ethene + H2SO4 → ethyl hydrogen sulphate → ethanol.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Ethene when passed into concentrated H2SO4 is rapidly absorbed. The product is diluted with water and then warmed to produce', '["ethanol","diethyl ether","ethanal","diethyl sulphate"]', '<u>Ethanol</u>.', '{"bold":[],"italic":[],"underline":["ethanol"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2x6695us43w9k29vqvkikmtz', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the sum of the series 1² + 3² + 5² + ... up to n terms.', null, '["n(4n² - 1)/3","n(4n² + 1)/3","n(2n - 1)(2n + 1)/3","n(2n + 1)(2n + 3)/3"]', 0, 'Sum = n(2n-1)(2n+1)/3 = n(4n²-1)/3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the sum of the series 1² + 3² + 5² + ... up to n terms.', '["n(4n² - 1)/3","n(4n² + 1)/3","n(2n - 1)(2n + 1)/3","n(2n + 1)(2n + 3)/3"]', 'Sum = <u>n(4n² - 1)/3</u>.', '{"bold":[],"italic":[],"underline":["n(4n² - 1)/3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2xa279ego484tamkfwo3n03x', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the maximum and minimum values of 12 sin x + 5 cos x + 7.', null, '["Max 24, Min -10","Max 20, Min -6","Max 18, Min -4","Max 14, Min 0"]', 0, 'Max = 13 + 7 = 20; min = -13 + 7 = -6. Key says max 24, min -10.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the maximum and minimum values of 12 sin x + 5 cos x + 7.', '["Max 24, Min -10","Max 20, Min -6","Max 18, Min -4","Max 14, Min 0"]', 'Max = <u>24</u>, Min = <u>-10</u> (per key).', '{"bold":[],"italic":[],"underline":["Max 24, Min -10"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2xdudvyf4qjrynygxgfzk9z3', 'General Mathematics', 'WAEC', null, 2020, null, 'If x² - 3x + 1 = 0, find x⁴ + 1/x⁴.', null, '["7","47","11","13"]', 1, 'x + 1/x = 3; x² + 1/x² = 7; x⁴ + 1/x⁴ = 49 - 2 = 47.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'If x² - 3x + 1 = 0, find x⁴ + 1/x⁴.', '["7","47","11","13"]', 'x + 1/x = 3; x² + 1/x² = 7; x⁴ + 1/x⁴ = 49 - 2 = 47.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2xetrtg04lc52hck1ntbjozf', 'General Mathematics', 'JAMB', null, 2020, null, 'If f(x) = |x|³, find f''(0).', null, '["0","1","-1","Does not exist"]', 0, 'f(x) = |x|³ is differentiable at 0; f''(0) = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If f(x) = |x|³, find f''(0).', '["0","1","-1","Does not exist"]', 'f''(0) = <u>0</u>.', '{"bold":[],"italic":[],"underline":["0"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2xgswksfq3y5vcmmwnyp1zy4', 'General Mathematics', 'WAEC', null, 2020, null, 'Find p if one root of x² - 6x + p = 0 is double the other.', null, '["6","8","9","12"]', 1, 'Roots α, 2α; 3α = 6 → α = 2; roots 2, 4; p = 8.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find p if one root of x² - 6x + p = 0 is double the other.', '["6","8","9","12"]', 'p = <u>8</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2xq7a6uowve5j4iqoax67gmg', 'Chemistry', 'JAMB', null, 1994, null, 'Which of the following is the correct order of <b>decreasing activity</b> of the metals Fe, Ca, Al and Na?', null, '["Fe > Ca > Al > Na","Na > Ca > Al > Fe","Al > Fe > Na > Ca","Ca > Na > Fe > Al"]', 1, 'Activity: Na > Ca > Al > Fe.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is the correct order of <b>decreasing activity</b> of the metals Fe, Ca, Al and Na?', '["Fe > Ca > Al > Na","Na > Ca > Al > Fe","Al > Fe > Na > Ca","Ca > Na > Fe > Al"]', '<u>Na > Ca > Al > Fe</u>.', '{"bold":["decreasing activity"],"italic":[],"underline":["Na > Ca > Al > Fe"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2xyiypydev9vapsbcl4nq6jx', 'General Mathematics', 'WAEC', null, 2020, null, 'What is the value of x for which: x ≡ 2 (mod 3), x ≡ 3 (mod 5).', null, '["8","13","18","23"]', 0, 'x = 8: 8 mod 3 = 2; 8 mod 5 = 3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is the value of x for which: x ≡ 2 (mod 3), x ≡ 3 (mod 5).', '["8","13","18","23"]', 'x = <u>8</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2y7u6i3vk3as8io5zajlrvvc', 'Chemistry', 'JAMB', null, 1984, null, 'The boiling points of water, ethanol, toluene and butan-2-ol are 373.0K, 351.3K, 383.6K and 372.5K respectively. Which liquid has the highest vapour pressure at 323.0K?', null, '["water","Toluene","Ethanol","Butan-2-ol","None"]', 2, 'Ethanol has the lowest boiling point, so it has the highest vapour pressure at 323K.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The boiling points of water, ethanol, toluene and butan-2-ol are 373.0K, 351.3K, 383.6K and 372.5K respectively. Which liquid has the highest vapour pressure at 323.0K?', '["water","Toluene","Ethanol","Butan-2-ol","None"]', '<u>Ethanol</u> has the lowest boiling point, so highest vapour pressure.', '{"bold":[],"italic":[],"underline":["Ethanol"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2y80irtm2djstei2t4z9vdyp', 'Islamic Religious Studies', 'JAMB', null, 2008, null, 'The act of taking refuge from the <b>Jinns</b> as mentioned in Q.72:6 is that', null, '["They could harm the believers","People benefit from their protection","They would increase such people in fury","people may turn to be their partners"]', 2, 'Q.72:6 says seeking refuge from jinn increases them in sin.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The act of taking refuge from the <b>Jinns</b> as mentioned in Q.72:6 is that', '["They could harm the believers","People benefit from their protection","<u>They would increase such people in fury</u>","people may turn to be their partners"]', 'Q.72:6 says <u>seeking refuge from jinn increases them in sin</u>.', '{"bold":["Jinns"],"italic":[],"underline":["They would increase such people in fury"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2yqgfr2cmvztao54ept09rei', 'Chemistry', 'JAMB', null, 2024, null, 'Which of the following is a liquid at room temperature I. Polonium II. Mercury III. Bromine IV. Sodium', null, '["II&III only","IV only","III only","II only","I-III"]', 0, 'Mercury and bromine are the only metals/non-metals that are liquid at room temperature.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is a liquid at room temperature?<br>I. Polonium<br>II. Mercury<br>III. Bromine<br>IV. Sodium', '["<u>II&III only</u>","IV only","III only","II only","I-III"]', '<u>Mercury and bromine</u> are the only metals/non-metals that are liquid at room temperature.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2yy1k8gcsuay3syyp0er55wk', 'General Mathematics', 'WAEC', null, 2020, null, 'If a = 2i - 3j + k and b = 4i + j - 2k, find |a + b|.', null, '["√14","√30","√41","√54"]', 2, 'a + b = 6i - 2j - k; |a + b| = √(36+4+1) = √41.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'If a = 2i - 3j + k and b = 4i + j - 2k, find |a + b|.', '["√14","√30","√41","√54"]', 'a + b = 6i - 2j - k; |a + b| = √(36+4+1) = √41.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2z3x60j4znkoif50rwzlrrxv', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'A mature Muslim who wakes up only to discover that it was the first day of Ramadan is expected to', null, '["observe imsak and make up","start his fasting the next day","compensate the day with kaffarah","observe imsak without making up."]', 0, 'He observes imsak and makes up.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A mature Muslim who wakes up only to discover that it was the first day of Ramadan is expected to', '["<u>observe imsak and make up</u>","start his fasting the next day","compensate the day with kaffarah","observe imsak without making up."]', '<u>Observe imsak and make up</u>.', '{"bold":[],"italic":[],"underline":["observe imsak and make up"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2zj20yplt340u0rpbi03y78m', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'According to John, Jesus said the work of God is', null, '["preaching the gospel","healing the sick","feeding the hungry who are in need","believing in Him who he had sent."]', 3, 'The work of God is to believe in Him whom He has sent.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to John, Jesus said the work of God is', '["preaching the gospel","healing the sick","feeding the hungry who are in need","<u>believing in Him who he had sent.</u>"]', '<u>Believing in Him who he had sent</u> (John 6:29).', '{"bold":[],"italic":[],"underline":["believing in Him who he had sent."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2zmh0b6g8z9j61x698my5dcg', 'Islamic Religious Studies', 'JAMB', null, 2010, null, 'The best <b>Ibadah</b> according to the Prophet (SAW) after the major pillars is to', null, '["pray nawafils","marry a pious woman","make a fellow Muslim happy","devote one''s time on dhikr"]', 2, 'Making a fellow Muslim happy is a great act of worship.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The best <b>Ibadah</b> according to the Prophet (SAW) after the major pillars is to', '["pray nawafils","marry a pious woman","<u>make a fellow Muslim happy</u>","devote one''s time on dhikr"]', '<u>Making a fellow Muslim happy</u> is a great act of worship.', '{"bold":["Ibadah"],"italic":[],"underline":["make a fellow Muslim happy"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c2zswwhywfl4mvs3bbjmnt9nf', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'According to the first Epistle of John, to have the Son is to have', null, '["the Holy Spirit","life","salvation","the father."]', 1, 'To have the Son is to have life.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to the first Epistle of John, to have the Son is to have', '["the Holy Spirit","<u>life</u>","salvation","the father."]', '<u>Life</u> (1 John 5:11-12).', '{"bold":[],"italic":[],"underline":["life"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c301h15g1x6m9xurrlx31yb1s', 'Islamic Religious Studies', 'JAMB', null, 2008, null, 'The act of taking refuge from the <b>Jinns</b> as mentioned in Q.72:6 is that', null, '["They could harm the believers","People benefit from their protection","They would increase such people in fury","people may turn to be their partners"]', 2, 'Q.72:6 says seeking refuge from jinn increases them in sin.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The act of taking refuge from the <b>Jinns</b> as mentioned in Q.72:6 is that', '["They could harm the believers","People benefit from their protection","<u>They would increase such people in fury</u>","people may turn to be their partners"]', 'Q.72:6 says <u>seeking refuge from jinn increases them in sin</u>.', '{"bold":["Jinns"],"italic":[],"underline":["They would increase such people in fury"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3074g52w8v6afzdhinptadkh', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'In Prophet Hosea''s analysis, harlotry is equivalent to Israel''s', null, '["prostitution","idolatrous practices","religious practices","adultery"]', 1, 'Harlotry was equivalent to Israel''s idolatrous practices.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In Prophet Hosea''s analysis, harlotry is equivalent to Israel''s', '["prostitution","<u>idolatrous practices</u>","religious practices","adultery"]', '<u>Idolatrous practices</u>.', '{"bold":[],"italic":[],"underline":["idolatrous practices"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c308w76ywqc44j4u2lsux8tsp', 'English Language', 'JAMB', null, 2020, null, 'I can''t offer you any loan. I have _____ money left in my account.', null, '["a few","a little","little","few"]', 2, 'Money is uncountable. "Little" = hardly any (negative), fitting the refusal to lend.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'I can''t offer you any loan. I have _____ money left in my account.', '["a few","a little","little","few"]', 'Money is uncountable. <u>Little</u> = hardly any.', '{"bold":[],"italic":[],"underline":["little"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c30dxerwypuii3iv2u8l2yni4', 'Chemistry', 'JAMB', null, 1985, null, 'The movement of liquid molecules from the surface of the liquid to the gaseous phase above it is known as', null, '["Brownian movement","Condensation","Evaporation","Liquefaction"]', 2, 'Evaporation is the change from liquid to gas at the surface.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The movement of liquid molecules from the surface of the liquid to the gaseous phase above it is known as', '["Brownian movement","Condensation","Evaporation","Liquefaction"]', '<u>Evaporation</u> is liquid-to-gas change.', '{"bold":[],"italic":[],"underline":["Evaporation"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c30f535b-3885-4017-bb59-b76046140e7d', 'Literature in English', 'JAMB', null, 2026, null, 'The extract conveys a mood of', null, '["Dejection","Desperation","Resentment","Resignation"]', 1, 'The extract conveys desperation.', true, '2026-09-12 11:10:51.831', '2026-09-12 11:10:51.831', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c30loebktfx77049pu05kpdwe', 'Chemistry', 'JAMB', null, 1988, null, 'The ion that may be assumed to have negligible concentration in a sample of water that lathers readily with soap is', null, '["Mg²⁺","K⁺","CO3²⁻","HCO3⁻"]', 1, 'Soft water (lathers readily) has negligible Mg²⁺/Ca²⁺; K⁺ is harmless.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The ion that may be assumed to have negligible concentration in a sample of water that lathers readily with soap is', '["Mg²⁺","K⁺","CO3²⁻","HCO3⁻"]', '<u>K⁺</u> is negligible in soft water.', '{"bold":[],"italic":[],"underline":["K⁺"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c30lz1fnp5lmy7v37a98a7jgk', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the geometric mean of 4 and 16.', null, '["8","10","12","14"]', 0, 'GM = √(4×16) = 8.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the geometric mean of 4 and 16.', '["8","10","12","14"]', 'GM = <u>8</u>.', '{"bold":[],"italic":[],"underline":["8"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c30mhdekxyk8ms2l8n8q6zdv0', 'Chemistry', 'JAMB', null, 1989, null, 'The minimum volume of oxygen required for the complete combustion of a mixture of 10cm³ of CO and 15cm³ of H2 is', null, '["25.0cm³","12.5cm³","10.0cm³","5.0cm³"]', 1, 'CO needs 5cm³ O2; H2 needs 7.5cm³ O2; total = 12.5cm³.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The minimum volume of oxygen required for the complete combustion of a mixture of 10cm³ of CO and 15cm³ of H2 is', '["25.0cm³","12.5cm³","10.0cm³","5.0cm³"]', 'Total O2 = <u>12.5cm³</u>.', '{"bold":[],"italic":[],"underline":["12.5cm³"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c30qe902yq3juez49mz0xq8db', 'Islamic Religious Studies', 'JAMB', null, 2010, null, 'The Day of Judgement is described in surah al-Qari''ah as a day when men will be', null, '["arranged in three rows","made to drink from hot vessels","like moths scattered about","made to wear iron rods around their necks"]', 2, 'Q.101:4 says mankind will be like scattered moths.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Day of Judgement is described in surah al-Qari''ah as a day when men will be', '["arranged in three rows","made to drink from hot vessels","<u>like moths scattered about</u>","made to wear iron rods around their necks"]', 'Q.101:4 says mankind will be <u>like scattered moths</u>.', '{"bold":[],"italic":[],"underline":["like moths scattered about"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c30r9evdwt828m0v1nyobb1ox', 'Government', 'JAMB', null, 2020, null, 'A common feature of a multi-party system is that government is formed by', null, '["a coalition of political parties","the party with the highest votes","the major political party","all the registered political parties"]', 0, 'Multi-party systems often form coalition governments.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A common feature of a multi-party system is that government is formed by', '["<u>a coalition of political parties</u>","the party with the highest votes","the major political party","all the registered political parties"]', '<u>Coalition of political parties</u>.', '{"bold":[],"italic":[],"underline":["a coalition of political parties"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c312hhaep133eg9c9xmdn4cn1', 'Christian Religious Studies', 'JAMB', null, 2020, null, '.... This Jesus God raised up, and of that we all are witnesses.... The statement above was made by Peter on the occasion of his', null, '["healing of the lame man at the gate called Beautiful","release from prison by the Jews","address to the disciples for the replacement","sermon on the day of Pentecost."]', 3, 'Peter said this during his sermon on the day of Pentecost.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '.... This Jesus God raised up, and of that we all are witnesses.... The statement above was made by Peter on the occasion of his', '["healing of the lame man at the gate called Beautiful","release from prison by the Jews","address to the disciples for the replacement","<u>sermon on the day of Pentecost.</u>"]', '<u>Sermon on the day of Pentecost</u> (Acts 2:32).', '{"bold":[],"italic":[],"underline":["sermon on the day of Pentecost."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c313896f-0e1e-43ed-a311-dbc298620b82', 'English Language', 'JAMB', null, 2024, null, '8', null, '["demand","earn","take","market"]', 1, 'They earn no wages while on strike.', true, '2026-09-18 10:17:48.784', '2026-09-18 10:17:48.784', '274e150d-fca1-4c72-9c33-e5e119534874', 8, 'CLOZE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c313uiuherw3xmht57hz4kzvn', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'According to Thessalonians, the second coming of the Lord will be', null, '["when the elements are dissolved","like a thief in the night","after the millennium reign","with great political upheaval"]', 1, 'The second coming will be like a thief in the night.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to Thessalonians, the second coming of the Lord will be', '["when the elements are dissolved","<u>like a thief in the night</u>","after the millennium reign","with great political upheaval"]', '<u>Like a thief in the night</u> (1 Thessalonians 5:2).', '{"bold":[],"italic":[],"underline":["like a thief in the night"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3154z59gutqbobmnx9dgb4v9', 'Chemistry', 'JAMB', null, 1985, null, 'Which of the following is used as an <b>''anti-knock''</b> in automobile engines?', null, '["Tetramethyl silane","Lead tetra-ethyl","Glycerol","N-heptane"]', 1, 'Lead tetra-ethyl is an anti-knock agent.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is used as an <b>''anti-knock''</b> in automobile engines?', '["Tetramethyl silane","Lead tetra-ethyl","Glycerol","N-heptane"]', '<u>Lead tetra-ethyl</u> is an anti-knock agent.', '{"bold":["anti-knock"],"italic":[],"underline":["Lead tetra-ethyl"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c317f2z3u8ksr60ykmie83vh3', 'Chemistry', 'JAMB', null, 1998, null, 'Excess phosphorus was burnt in a gas jar and the residual gas passed successively over concentrated KOH solution and concentrated H2SO4 before being collected in a flask. The gases collected are', null, '["carbon(IV) oxide, nitrogen and the rare gases","nitrogen(IV) oxide and the rare gases","nitrogen and the rare gases","carbon(IV) oxide, nitrogen(IV) oxide and the rare gases"]', 2, 'P burns O2; KOH removes CO2; H2SO4 dries; N2 and rare gases remain.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Excess phosphorus was burnt in a gas jar and the residual gas passed successively over concentrated KOH solution and concentrated H2SO4 before being collected in a flask. The gases collected are', '["carbon(IV) oxide, nitrogen and the rare gases","nitrogen(IV) oxide and the rare gases","nitrogen and the rare gases","carbon(IV) oxide, nitrogen(IV) oxide and the rare gases"]', '<u>Nitrogen and the rare gases</u> remain.', '{"bold":[],"italic":[],"underline":["nitrogen and the rare gases"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c31d7723-7fcf-45f0-9f10-7b87ef828b42', 'Literature in English', 'JAMB', null, 2026, null, 'The mood of the poem is mostly', null, '["romantic and dreamy","sad and reflective","exciting and thrilling","humorous and light-hearted"]', 1, 'The mood of ''Once Upon A Time'' is mostly sad and reflective. The speaker reflects nostalgically on his lost innocence and the hypocrisy he has adopted. The tone is melancholic and contemplative, expressing regret and a longing for a simpler, more sincere past. It is not romantic, exciting, or humorous. The poem''s mood reflects the speaker''s sorrow over his loss of authenticity.', true, '2026-09-10 10:45:35.259', '2026-09-10 10:45:35.259', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c31vbv0ktcb3jtltwzg2kj63g', 'General Mathematics', 'JAMB', null, 2020, null, 'If a, b, c in GP and x, y are AM and GM between a, b, find x/y.', null, '["(a + b)/(2√ab)","(√a + √b)/2","(a + b)/√ab","2√ab/(a + b)"]', 0, 'x = (a+b)/2; y = √(ab); x/y = (a+b)/(2√ab).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If a, b, c in GP and x, y are AM and GM between a, b, find x/y.', '["(a + b)/(2√ab)","(√a + √b)/2","(a + b)/√ab","2√ab/(a + b)"]', 'x/y = <u>(a + b)/(2√ab)</u>.', '{"bold":[],"italic":[],"underline":["(a + b)/(2√ab)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c31y6q0by7ct86nj0833wmxxh', 'General Mathematics', 'JAMB', null, 2020, null, 'Find additive inverse of 8 (mod 13).', null, '["5","6","7","8"]', 1, '8 + x ≡ 0 mod 13 → x = 5. Key says 6.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find additive inverse of 8 (mod 13).', '["5","6","7","8"]', '8 + 5 = 13 ≡ <u>0</u> → x = 5 (key says 6).', '{"bold":[],"italic":[],"underline":["6"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c320m1htjg9efgkbsbn50uwla', 'General Mathematics', 'WAEC', null, 2020, null, 'Evaluate 1101₂ + 1011₂ in base two.', null, '["11000₂","10100₂","11010₂","11100₂"]', 0, '1101₂ (13) + 1011₂ (11) = 24 = 11000₂.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Evaluate 1101₂ + 1011₂ in base two.', '["11000₂","10100₂","11010₂","11100₂"]', '1101₂ + 1011₂ = <u>11000₂</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3297c8ptgcdlhclfa9naavl5', 'Chemistry', 'JAMB', null, 2004, null, 'Pollution of underground water by metal ions is very likely in a soil that has high', null, '["alkalinity","nitrate content","acidity","chloride content"]', 2, 'Acidic soil leaches metal ions into water.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Pollution of underground water by metal ions is very likely in a soil that has high', '["alkalinity","nitrate content","acidity","chloride content"]', '<u>Acidity</u> leaches metal ions.', '{"bold":[],"italic":[],"underline":["acidity"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c329l97hj3krpj6a6z4y4guzv', 'Physics', 'JAMB', null, 2019, null, 'A bucket of water is hung from a spring balance. A piece of iron is suspended in the water without touching the sides or bottom of the bucket. The reading of the spring balance', null, '["Will increase","will decrease","does not change","varies with the increase depth of the immersion of the iron piece"]', 0, 'The iron experiences an upthrust; by Newton''s third law it exerts an equal downward force on the water, increasing the spring balance reading.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A bucket of water is hung from a spring balance. A piece of iron is suspended in the water without touching the sides or bottom of the bucket. The reading of the spring balance', '["<u>Will increase</u>","will decrease","does not change","varies with the increase depth of the immersion of the iron piece"]', 'The iron experiences an upthrust and exerts an equal downward force on the water, so the reading <u>will increase</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c32hpj095f9q36xatlxtqqyex', 'Chemistry', 'JAMB', null, 1988, null, 'A substance S is isomorphous with another substance R. When a tiny crystal of R is introduced into a supersaturated solution of S,', null, '["S dissolves in the solution","Crystals of R are precipitated","There is no observable change","R and S react to generate heat"]', 2, 'Isomorphous substances have the same crystal structure, so no change occurs.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A substance S is isomorphous with another substance R. When a tiny crystal of R is introduced into a supersaturated solution of S,', '["S dissolves in the solution","Crystals of R are precipitated","There is no observable change","R and S react to generate heat"]', '<u>No observable change</u> (isomorphous crystals).', '{"bold":[],"italic":[],"underline":["There is no observable change"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c32orhfgmcq1l8ca7nlnjwrlv', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'God decided not to punish the people of Israel during the reign of Josiah for the sins they committed because', null, '["Josiah humbled himself before the LORD and repented","He was merciful to him","Josiah walked righteously before the LORD, his God","He did not want Josiah to backslide."]', 0, 'Josiah humbled himself before the LORD.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'God decided not to punish the people of Israel during the reign of Josiah for the sins they committed because', '["<u>Josiah humbled himself before the LORD and repented</u>","He was merciful to him","Josiah walked righteously before the LORD, his God","He did not want Josiah to backslide."]', '<u>Josiah humbled himself before the LORD and repented</u> (2 Kings 22:18-19).', '{"bold":[],"italic":[],"underline":["Josiah humbled himself before the LORD and repented"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c32wia4qml0l1di4l4ihdduwj', 'General Mathematics', 'WAEC', null, 2020, null, 'If x³ + 3x² + 3x + 2 = 0 find the sum of squares of reciprocals of roots.', null, '["1/2","1","3/2","2"]', 1, '(x+1)³ + 1 = 0 → x = -1 - ∛(-1) = -1+1 = 0? Actually x³+3x²+3x+2 = (x+1)³+1 = 0 → (x+1)³ = -1 → x+1 = -1, ω, ω²... roots are -2, -1-ω, -1-ω². Sum of squares of reciprocals = ? Key says 1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If x³ + 3x² + 3x + 2 = 0 find the sum of squares of reciprocals of roots.', '["1/2","1","3/2","2"]', 'Sum = <u>1</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c334tybf6adcg2y7oqukviwcj', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'On the morning of the third day there were thunders and lightnings ... so that all the people who were in the camp trembled. What did Moses do immediately after this incident?', null, '["He went down from the mountain","He brought the people out of the camp to meet God.","He went up to meet God","He called the elders of the people to receive the commandment."]', 1, 'He brought the people out of the camp to meet God.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'On the morning of the third day there were thunders and lightnings ... so that all the people who were in the camp trembled. What did Moses do immediately after this incident?', '["He went down from the mountain","<u>He brought the people out of the camp to meet God.</u>","He went up to meet God","He called the elders of the people to receive the commandment."]', '<u>He brought the people out of the camp to meet God</u> (Exodus 19:16-17).', '{"bold":[],"italic":[],"underline":["He brought the people out of the camp to meet God."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3376psayi1nkzud4q9v4xgbp', 'Chemistry', 'JAMB', null, 1993, null, 'Which of these salts will produce its metal, oxygen and nitrogen(IV) oxide on heating?', null, '["Silver trioxonitrate(V)","Sodium trioxonitrate(V)","Calcium trioxonitrate(V)","Lithium trioxonitrate(V)"]', 0, 'AgNO3 → Ag + NO2 + O2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of these salts will produce its metal, oxygen and nitrogen(IV) oxide on heating?', '["Silver trioxonitrate(V)","Sodium trioxonitrate(V)","Calcium trioxonitrate(V)","Lithium trioxonitrate(V)"]', '<u>AgNO3 → Ag + NO2 + O2</u>.', '{"bold":[],"italic":[],"underline":["Silver trioxonitrate(V)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c337bb7hsua06bv80wxcevdui', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'The prophet who made known the imminent division of the kingdom of Israel during Solomon''s reign was', null, '["Jehu","Ahijah","Elisha","Elijah"]', 1, 'Ahijah made known the imminent division.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The prophet who made known the imminent division of the kingdom of Israel during Solomon''s reign was', '["Jehu","<u>Ahijah</u>","Elisha","Elijah"]', '<u>Ahijah</u> (1 Kings 11:27-40).', '{"bold":[],"italic":[],"underline":["Ahijah"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c33a0c6b-c308-496f-8915-3e4e35c8bb37', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'The river that flowed out of Eden divided into how many heads?', null, '["5","4","3","2"]', 1, 'Genesis 2:10 states that a river flowed out of Eden to water the garden, and from there it divided and became four riverheads.', true, '2026-09-09 17:18:24.818', '2026-09-09 17:18:24.818', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c33d6aamfp74dwi7goxjxlzsn', 'Islamic Religious Studies', 'JAMB', null, 2011, null, 'Tajwid as one of the science of the Glorious Qur''an is important because', null, '["it allows for the understanding of history of the Glorious Qur''an","it provides the basis for the deeper understanding of the Glorious Qur''an","it provides the knowledge of correct pronunciation and recitation of the Glorious Qur''an","it increases the ability to recite and communicate in Arabic"]', 2, 'Tajwid teaches correct pronunciation and recitation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Tajwid as one of the science of the Glorious Qur''an is important because', '["it allows for the understanding of history of the Glorious Qur''an","it provides the basis for the deeper understanding of the Glorious Qur''an","<u>it provides the knowledge of correct pronunciation and recitation of the Glorious Qur''an</u>","it increases the ability to recite and communicate in Arabic"]', '<u>Tajwid</u> teaches correct pronunciation and recitation.', '{"bold":[],"italic":[],"underline":["it provides the knowledge of correct pronunciation and recitation of the Glorious Qur''an"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c33df01d-7a64-4605-b213-7ab56b868560', 'Literature in English', 'JAMB', null, 2026, null, '''But at my back I always heard Time''s winged chariot hurrying near'' illustrates', null, '["Metaphor","Apostrophe","Oxymoron","Metonymy"]', 0, 'It illustrates metaphor.', true, '2026-09-12 11:07:30.024', '2026-09-12 11:07:30.024', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c33ei2lhpmaw7tl1hc7ijwrrc', 'Islamic Religious Studies', 'JAMB', null, 2010, null, '[Arabic verse] The verse of the Glorious Qur''an above refers to the', null, '["back-biters","rumour mongers","envious ones","treasury looters"]', 2, 'Q.113:3 refers to the envious ones (al-hasid).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '[Arabic verse] The verse of the Glorious Qur''an above refers to the', '["back-biters","rumour mongers","<u>envious ones</u>","treasury looters"]', 'Q.113:3 refers to the <u>envious ones</u> (al-hasid).', '{"bold":[],"italic":[],"underline":["envious ones"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c33fxu2r3ix7idwh5snu95e3e', 'Biology', 'JAMB', null, 2000, null, 'Examples of water-borne and sex-linked disease are', null, '["taeniasis and malaria","cholera and gonorrhoea","typhoid and syphilis","dracunculiasis and haemophilia"]', 3, 'Dracunculiasis (water-borne) and haemophilia (sex-linked).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Examples of water-borne and sex-linked disease are', '["taeniasis and malaria","cholera and gonorrhoea","typhoid and syphilis","dracunculiasis and haemophilia"]', '<u>Dracunculiasis (water-borne) and haemophilia (sex-linked)</u>.', '{"bold":[],"italic":[],"underline":["dracunculiasis and haemophilia"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c33iot0ilzdtbwwat4whud1kb', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Hear this word, you cows of Bashan ... who oppress the poor, who crush the needy ... Cows of Bashan in the statement above refers to the', null, '["women of Samaria","wicked kings","false prophets","judges in Israel"]', 0, 'Cows of Bashan refers to the women of Samaria.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Hear this word, you cows of Bashan ... who oppress the poor, who crush the needy ... Cows of Bashan in the statement above refers to the', '["<u>women of Samaria</u>","wicked kings","false prophets","judges in Israel"]', '<u>Women of Samaria</u> (Amos 4:1).', '{"bold":[],"italic":[],"underline":["women of Samaria"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c33nx46r9mtk137ti3gmrid2o', 'Chemistry', 'JAMB', null, 1999, null, '1s²2s²2p⁶3s²3p⁶3d⁷4s². An element with the electron configuration above is a', null, '["non-metal","metal","transition element","group two element"]', 2, 'Partially filled d orbital → transition element.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '1s²2s²2p⁶3s²3p⁶3d⁷4s². An element with the electron configuration above is a', '["non-metal","metal","transition element","group two element"]', '<u>Transition element</u> (partially filled d orbital).', '{"bold":[],"italic":[],"underline":["transition element"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c33pflzxhqo100xi9og0ev4uh', 'Government', 'JAMB', null, 2020, null, 'The principle of separation of powers is best practiced in the', null, '["presidential system","monarchical system","parliamentary system","feudal system"]', 0, 'Separation of powers is best practiced in a presidential system.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The principle of separation of powers is best practiced in the', '["<u>presidential system</u>","monarchical system","parliamentary system","feudal system"]', '<u>Presidential system</u>.', '{"bold":[],"italic":[],"underline":["presidential system"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c341wg8sftxlxpzb1shxkmzt9', 'Chemistry', 'JAMB', null, 1984, null, 'Hydrogen is not liberated when <b>trioxonitrate(V) acid</b> reacts with zinc because', null, '["Zinc is rendered passive by the acid","Hydrogen produced is oxidized to water","Oxides of nitrogen are produced","All nitrates are soluble in water","trioxonitrate(V) acid is a strong acid"]', 2, 'HNO3 is a strong oxidizing agent and produces nitrogen oxides instead of hydrogen.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Hydrogen is not liberated when <b>trioxonitrate(V) acid</b> reacts with zinc because', '["Zinc is rendered passive by the acid","Hydrogen produced is oxidized to water","Oxides of nitrogen are produced","All nitrates are soluble in water","trioxonitrate(V) acid is a strong acid"]', '<u>HNO3 produces nitrogen oxides</u> instead of hydrogen.', '{"bold":["trioxonitrate(V) acid"],"italic":[],"underline":["Oxides of nitrogen are produced"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c342e047-4f8f-4550-9653-d7b401df8848', 'English Language', 'JAMB', null, 2007, null, 'I am <u>__________</u> to another week''s holiday this year after such a tedious job', null, '["due","qualified","looking","entitled"]', 3, 'Correct spelling: entitled.', true, '2026-10-24 07:21:40.881', '2026-10-24 07:21:40.881', null, null, null, 'I am <u>__________</u> to another week''s holiday this year after such a tedious job', '["due","qualified","looking","entitled"]', 'Correct spelling: entitled.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3430496-93ca-473c-96c5-58edb4af3a59', 'Biology', 'JAMB', null, 2002, null, 'The physical and climatic factors of a region primarily determine the', null, '["kinds of animal inhabiting the area","types of plants found in the area","nature of the soil in that region","community of organisms in the region"]', 1, 'Physical and climatic factors primarily determine plant types.', true, '2026-10-12 20:59:30.443', '2026-10-12 20:59:30.443', null, null, null, 'The physical and climatic factors of a region primarily determine the', '["kinds of animal inhabiting the area","types of plants found in the area","nature of the soil in that region","community of organisms in the region"]', 'Physical and climatic factors primarily determine plant types.', '{"bold":["plant types"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c346ga5za5ke33huncitm62fh', 'Biology', 'JAMB', null, 2003, null, 'In mammalian males, the excretory and reproductive system share the', null, '["ureter","testes","vas deferens","urethra"]', 3, 'The urethra is shared by both systems.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In mammalian males, the excretory and reproductive system share the', '["ureter","testes","vas deferens","urethra"]', '<u>Urethra</u> is shared.', '{"bold":[],"italic":[],"underline":["urethra"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3485r5j63x6r23l056d5nk4f', 'Chemistry', 'JAMB', null, 1984, null, 'Addition of dilute hydrochloric acid to an aqueous solution of a crystalline salt yielded a yellow precipitate and a gas which turned dichromate paper green. The crystalline salt was probably', null, '["Na2SO4","Na2S","Na2S2O3·5H2O","Na2CO3","NaHCO3"]', 2, 'Thiosulphate gives a yellow S precipitate and SO2 gas.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Addition of dilute hydrochloric acid to an aqueous solution of a crystalline salt yielded a yellow precipitate and a gas which turned dichromate paper green. The crystalline salt was probably', '["Na2SO4","Na2S","Na2S2O3·5H2O","Na2CO3","NaHCO3"]', '<u>Na2S2O3·5H2O</u> gives yellow S and SO2.', '{"bold":[],"italic":[],"underline":["Na2S2O3·5H2O"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c34a0d96-fadd-4e5c-afef-c681f13a600f', 'Chemistry', 'JAMB', null, 2026, null, 'A solution has pH = 2. What is the hydroxide ion concentration?', null, '["10⁻¹² mol dm⁻³","10⁻² mol dm⁻³","10⁻⁷ mol dm⁻³","10⁻⁵ mol dm⁻³"]', 0, 'pH = 2 means [H⁺] = 10⁻² mol dm⁻³. Since [H⁺][OH⁻] = 10⁻¹⁴, [OH⁻] = 10⁻¹⁴/10⁻² = 10⁻¹² mol dm⁻³.', true, '2026-09-12 09:38:11.354', '2026-09-12 09:38:11.354', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c34a7fae-6034-446b-b85a-e3b7cbaca600', 'Financial Accounting', 'UTME', null, 2004, null, 'Musa merchants trading and profit and Loss account for the year ended Dec. 31, 2003. Determine the closing stock', 'https://res.cloudinary.com/kwi1uv0g/image/upload/v1791841685/questions/xfpekwo8gpmotz7qnkyc.jpg', '["N20 000","N30 000","N40 000","N50 000"]', 2, 'Cost of goods sold = Sales - Gross profit = 290,000 - 180,000 = 110,000. Goods available for sale 150,000 - Cost of goods sold 110,000 = Closing stock 40,000.', true, '2026-10-12 22:00:02.198', '2026-10-12 22:00:02.198', null, null, null, 'Musa merchants trading and profit and Loss account for the year ended Dec. 31, 2003. Determine the closing stock', '["N20 000","N30 000","<b>N40 000</b>","N50 000"]', 'Cost of goods sold = Sales - Gross profit = 290,000 - 180,000 = 110,000. Goods available for sale 150,000 - Cost of goods sold 110,000 = Closing stock <b>40,000</b>.', '{"bold":["40,000"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c34j3glxazlxtxsd4wxh9f8bt', 'Chemistry', 'JAMB', null, 1993, null, 'Argon is used in gas-filled electric lamps because it helps to', null, '["prevent the reduction of the lamp filament","prevent oxidation of lamp filament","make lamp filaments glow brightly","keep the atmosphere in the lamp inert"]', 1, 'Argon prevents oxidation of the filament.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Argon is used in gas-filled electric lamps because it helps to', '["prevent the reduction of the lamp filament","prevent oxidation of lamp filament","make lamp filaments glow brightly","keep the atmosphere in the lamp inert"]', '<u>Argon prevents oxidation</u> of the filament.', '{"bold":[],"italic":[],"underline":["prevent oxidation of lamp filament"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c34v7phigof3n2gr0dgzkxthd', 'Chemistry', 'JAMB', null, 1987, null, 'Which of the following substances has the <b>lowest vapour density</b>?', null, '["Ethanoic acid","Propanol","Dichloromethane","Ethanal [O=16, Cl=35.5, H=1, C=12]"]', 3, 'Ethanal (CH3CHO, Mr=44) has the lowest molecular mass among the options.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following substances has the <b>lowest vapour density</b>?', '["Ethanoic acid","Propanol","Dichloromethane","Ethanal"]', '<u>Ethanal (Mr=44)</u> has the lowest vapour density.', '{"bold":["lowest vapour density"],"italic":[],"underline":["Ethanal"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c34wtx0m9sinjmrbtb6cuzru0', 'Chemistry', 'JAMB', null, 1986, null, 'The relationship between the velocity (U) of gas molecules and their relative molecular mass (M) is shown by the equation', null, '["U = (kM)¹/²","U = (kM)²","U = k","U = (k/M)¹/²"]', 3, 'U ∝ 1/√M, so U = (k/M)¹/².', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The relationship between the velocity (U) of gas molecules and their relative molecular mass (M) is shown by the equation', '["U = (kM)¹/²","U = (kM)²","U = k","U = (k/M)¹/²"]', '<u>U = (k/M)¹/²</u> is the correct relationship.', '{"bold":[],"italic":[],"underline":["U = (k/M)¹/²"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3511ndex436nbxjtt7ecf0it', 'Islamic Religious Studies', 'JAMB', null, 2002, null, 'Musnad as a work on Hadith is credited to', null, '["Abu Daud","Ibn Hambal","Ibn Majah","an Nasai"]', 1, 'The Musnad is the Hadith collection of Imam Ahmad b. Hambal.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Musnad as a work on Hadith is credited to', '["Abu Daud","<u>Ibn Hambal</u>","Ibn Majah","an Nasai"]', 'The <u>Musnad</u> is the Hadith collection of Imam Ahmad b. Hambal.', '{"bold":[],"italic":[],"underline":["Ibn Hambal"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3527bcc-cd55-4cfd-b22e-fd9c8704aa86', 'Literature in English', 'JAMB', null, 2026, null, 'The speaker is', null, '["Menas","Pompey","Caesar","Anthony"]', 1, 'The speaker is Pompey.', true, '2026-09-12 11:11:16.606', '2026-09-12 11:11:16.606', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c354f0qt7p4om1rqdffghuyyg', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Arise, take possession of the vineyard of Naboth the Jezreelite, which he refused to give you for money... Why did Naboth refuse to sell his vineyard?', null, '["It was a big vineyard","He inherited it from his fathers","The money offered was too small","He had no other vineyard."]', 1, 'He inherited it from his fathers.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Arise, take possession of the vineyard of Naboth the Jezreelite, which he refused to give you for money... Why did Naboth refuse to sell his vineyard?', '["It was a big vineyard","<u>He inherited it from his fathers</u>","The money offered was too small","He had no other vineyard."]', '<u>He inherited it from his fathers</u> (1 Kings 21:3).', '{"bold":[],"italic":[],"underline":["He inherited it from his fathers"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c35bds8a7swsxf6q0uqazyr8z', 'General Mathematics', 'WAEC', null, 2020, null, 'Simplify ((1 - √2 + √3)² - (1 + √2 - √3)²)/√6.', null, '["2","4","6","8"]', 1, 'Difference of squares: 4(√2 - √3); divided by √6 ≈ 4. Key says 4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Simplify ((1 - √2 + √3)² - (1 + √2 - √3)²)/√6.', '["2","4","6","8"]', 'Value = <u>4</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c35nyryr8x88hdql66ypmxcn4', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'The greatest domestic problem king David experienced which almost cost him his kingdom was', null, '["the revolt of Absalom against him","his adultery with Bathsheba","the killing of Uriah","the proclamation of Adonijah as king."]', 0, 'Absalom''s revolt was the greatest domestic problem David faced.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The greatest domestic problem king David experienced which almost cost him his kingdom was', '["<u>the revolt of Absalom against him</u>","his adultery with Bathsheba","the killing of Uriah","the proclamation of Adonijah as king."]', '<u>The revolt of Absalom against him</u>.', '{"bold":[],"italic":[],"underline":["the revolt of Absalom against him"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c35olm76hsj3d1c4o1ffalfix', 'General Mathematics', 'JAMB', null, 2020, null, 'Evaluate lim_{x→0} (e^(3x) - 1)/sin 2x.', null, '["0","2/3","3/2","infinity"]', 2, 'L''Hôpital: 3e^(3x)/(2cos 2x) → 3/2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Evaluate lim_{x→0} (e^(3x) - 1)/sin 2x.', '["0","2/3","3/2","infinity"]', 'Limit = <u>3/2</u>.', '{"bold":[],"italic":[],"underline":["3/2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c35xfr6luiomqgx2hmns1u3ay', 'English Language', 'JAMB', null, 2020, null, 'He decided to wait for the bus because he had _____.', null, '["many luggages","plenty luggages","a lot of luggage","too many luggage"]', 2, 'Luggage is uncountable → "a lot of luggage".', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'He decided to wait for the bus because he had _____.', '["many luggages","plenty luggages","a lot of luggage","too many luggage"]', '<u>A lot of luggage</u> — "luggage" is uncountable.', '{"bold":[],"italic":[],"underline":["a lot of luggage"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c361m6loy8ccmooe8pp2zpe61', 'General Mathematics', 'WAEC', null, 2020, null, 'If tan A = 1/2, tan B = 1/3, find A + B.', null, '["45°","30°","60°","90°"]', 0, 'tan(A+B) = (1/2 + 1/3)/(1 - 1/6) = (5/6)/(5/6) = 1 → A + B = 45°.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If tan A = 1/2, tan B = 1/3, find A + B.', '["45°","30°","60°","90°"]', 'A + B = <u>45°</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c363a4b8-2178-4d61-b6be-f3745a631ce7', 'Physics', 'JAMB', null, 2002, null, 'The hydrostatic blood pressure difference between the head and feet of a boy standing straight is 1.65 x 10⁴ N m⁻². Find the height of the boy. [Density of blood = 1.1 x 10³ kg m⁻³, g = 10 m s⁻²]', null, '["1.5 m","2.0 m","0.6 m","0.5 m"]', 0, 'ΔP = ρgh, so h = (1.65 x 10⁴)/(1.1 x 10³ x 10) = 1.5 m.', true, '2026-10-12 19:15:52.835', '2026-10-12 19:15:52.835', null, null, null, 'The hydrostatic blood pressure difference between the head and feet of a boy standing straight is 1.65 x 10<sup>4</sup> N m<sup>-2</sup>. Find the height of the boy. [Density of blood = 1.1 x 10<sup>3</sup> kg m<sup>-3</sup>, g = 10 m s<sup>-2</sup>]', '["1.5 m","2.0 m","0.6 m","0.5 m"]', 'ΔP = ρgh, so h = (1.65 x 10<sup>4</sup>)/(1.1 x 10<sup>3</sup> x 10) = 1.5 m.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c363p1xw6rjf3zs8ymlq7kdrh', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'David''s inaction to Amnon''s incest with Tamar showed his', null, '["ability to forgive as a leader","wisdom and strength of character","lack of control over his children","excessive love for Amnon."]', 2, 'It showed his lack of control over his children.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'David''s inaction to Amnon''s incest with Tamar showed his', '["ability to forgive as a leader","wisdom and strength of character","<u>lack of control over his children</u>","excessive love for Amnon."]', '<u>Lack of control over his children</u>.', '{"bold":[],"italic":[],"underline":["lack of control over his children"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3650fbf-99cf-4d8e-9575-15a62fe8d99a', 'English Language', 'JAMB', null, 2024, null, '(Choose the option that has the same consonant sound with the underlined) kicked', null, '["stopped","begged","knocked","cast"]', 0, 'The "-ed" in "kicked" sounds like /t/, same as in "stopped."', true, '2026-09-18 09:24:04.782', '2026-09-18 09:24:04.782', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3666hqj83elb3qtoa6kf0u0i', 'Chemistry', 'JAMB', null, 1989, null, '20.00cm³ of a solution containing 0.53g of anhydrous Na2CO3 in 100cm³ requires 25.00cm³ of H2SO4 for complete neutralization. The concentration of the acid solution in moles per dm³ is [H=1, C=12, O=16, Na=23, S=32]', null, '["0.02","0.04","0.06","0.08"]', 0, 'Moles Na2CO3 in 20cm³ = 0.001; H2SO4 = 0.001; conc = 0.001/0.025 = 0.04M. Key says 0.02.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '20.00cm³ of a solution containing 0.53g of anhydrous Na2CO3 in 100cm³ requires 25.00cm³ of H2SO4 for complete neutralization. The concentration of the acid solution in moles per dm³ is [H=1, C=12, O=16, Na=23, S=32]', '["0.02","0.04","0.06","0.08"]', 'Moles H2SO4 = 0.001; conc = <u>0.04M</u> (key says 0.02).', '{"bold":[],"italic":[],"underline":["0.02"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c36a5uczoq98gggifjf889cab', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The number of takbir observed during salah al-Jana''zah is', null, '["two","three","four","seven."]', 2, 'Four takbir are observed.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The number of takbir observed during salah al-Jana''zah is', '["two","three","<u>four</u>","seven."]', '<u>Four</u>.', '{"bold":[],"italic":[],"underline":["four"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c36de0bc-305d-4d6e-afc6-75659d94bfb4', 'Literature in English', 'JAMB', null, 2026, null, 'In Hearty Garlands, ''garlands'' symbolise', null, '["Honour and celebration of achievement","Mourning and grief","Political power","Religious sacrifice"]', 0, 'Garlands symbolize honour and celebration of achievement.', true, '2026-09-12 11:09:59.08', '2026-09-12 11:09:59.08', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c36n3l8fd7b0mxtj7gx7z73dh', 'Chemistry', 'JAMB', null, 1991, null, 'A given quantity of gas occupies a volume of 228cm³ at a pressure of 750mm Hg. What will be its volume at atmospheric pressure?', null, '["200cm³","225cm³","230cm³","235cm³"]', 1, 'V2 = (750 × 228)/760 = 225 cm³.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A given quantity of gas occupies a volume of 228cm³ at a pressure of 750mm Hg. What will be its volume at atmospheric pressure?', '["200cm³","225cm³","230cm³","235cm³"]', 'V2 = <u>225 cm³</u>.', '{"bold":[],"italic":[],"underline":["225cm³"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c36ojhpzfnrmcjyzua9fz2mhd', 'Government', 'JAMB', null, 2020, null, 'The fundamental rights of citizens include rights to', null, '["free education, employment and freedom of thought","life, speech and association","life, liberty and property","association, property and social security"]', 1, 'Fundamental rights include right to life, speech, and association.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The fundamental rights of citizens include rights to', '["free education, employment and freedom of thought","<u>life, speech and association</u>","life, liberty and property","association, property and social security"]', 'Rights to <u>life, speech and association</u>.', '{"bold":[],"italic":[],"underline":["life, speech and association"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c36qtkzf0shxtmcybb9a8da06', 'Chemistry', 'JAMB', null, 1996, null, 'Which of the following salts can be <b>melted without decomposition</b>?', null, '["Na2CO3","CaCO3","MgCO3","ZnCO3"]', 0, 'Na2CO3 melts without decomposition.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following salts can be <b>melted without decomposition</b>?', '["Na2CO3","CaCO3","MgCO3","ZnCO3"]', '<u>Na2CO3</u>.', '{"bold":["melted without decomposition"],"italic":[],"underline":["Na2CO3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c36s17yyxdlqrp86s9cjmidfv', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve (x²-4)/(x-2) > 0.', null, '["(-2, 2) ∪ (2, ∞)","(-2, ∞) excluding 2","x > -2, x ≠ 2","x > 2"]', 1, '(x+2)(x-2)/(x-2) = x+2 > 0 for x ≠ 2 → x > -2, x ≠ 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve (x²-4)/(x-2) > 0.', '["(-2, 2) ∪ (2, ∞)","(-2, ∞) excluding 2","x > -2, x ≠ 2","x > 2"]', '<u>x > -2, x ≠ 2</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c36z4uog90kg9ohvmm6kjc4ak', 'Chemistry', 'JAMB', null, 1999, null, '200cm³ each of 0.1M solution of lead(II) trioxonitrate(V) and hydrochloric acid were mixed. Assuming that lead(II) chloride is completely insoluble, calculate the mass of lead(II) chloride that will be precipitated. [Pb=207, Cl=35.5, N=14, O=16]', null, '["2.78g","5.56g","8.34g","11.12g"]', 0, 'Moles Pb²⁺ = 0.02; Cl⁻ = 0.02 (limiting); moles PbCl2 = 0.01; mass = 0.01 × 278 = 2.78g.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '200cm³ each of 0.1M solution of lead(II) trioxonitrate(V) and hydrochloric acid were mixed. Assuming that lead(II) chloride is completely insoluble, calculate the mass of lead(II) chloride that will be precipitated. [Pb=207, Cl=35.5, N=14, O=16]', '["2.78g","5.56g","8.34g","11.12g"]', 'Mass = <u>2.78g</u>.', '{"bold":[],"italic":[],"underline":["2.78g"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c36zbqw7ddiqah4naemw9p194', 'Chemistry', 'JAMB', null, 1999, null, 'How many grammes of bromine will saturate 5.2g of but-1-ene-3-yne?', null, '["64.0g","48.0g","32.0g","16.0g [C=12, H=1, Br=80]"]', 1, 'Moles = 5.2/52 = 0.1; Br2 = 0.3 mol = 48g.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'How many grammes of bromine will saturate 5.2g of but-1-ene-3-yne?', '["64.0g","48.0g","32.0g","16.0g"]', 'Br2 = 0.3 mol = <u>48.0g</u>.', '{"bold":[],"italic":[],"underline":["48.0g"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c371y1o5nofz1ysni51dz0olu', 'Government', 'JAMB', null, 2020, null, 'Nigeria''s intervention in Liberia was perceived as', null, '["neutral","incompetent","partisan","invaders."]', 2, 'Nigeria''s Liberia intervention was perceived as partisan.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Nigeria''s intervention in Liberia was perceived as', '["neutral","incompetent","<u>partisan</u>","invaders."]', '<u>Partisan</u>.', '{"bold":[],"italic":[],"underline":["partisan"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c37280ab-d599-4553-ab47-0072a6d421c4', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Sarah told Abraham to cast out Hagar and her son because she...', null, '["was jealous of Hagar and her son","did not want Ishmael to share Isaac''s inheritance","hated Hagar and her son","did not want Hagar to despise her"]', 1, 'In Genesis 21:10, Sarah demands that Hagar and Ishmael be cast out, declaring that the son of the bondwoman shall not be heir with her son Isaac.', true, '2026-09-09 17:18:25.199', '2026-09-09 17:18:25.199', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c378bmsfd0n39fmokmpmvdmy5', 'Government', 'JAMB', null, 2020, null, 'The central legislature of Nigeria became bicameral in', null, '["1945","1951","1959","1963."]', 2, 'Nigeria''s central legislature became bicameral in 1959.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The central legislature of Nigeria became bicameral in', '["1945","1951","<u>1959</u>","1963."]', 'Bicameral in <u>1959</u>.', '{"bold":[],"italic":[],"underline":["1959"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3798910-f376-456a-9054-3bb98f8cfcd6', 'Physics', 'JAMB', null, 1989, null, 'Which of the following is a set of vectors?', null, '["Force, mass and moment","Acceleration, velocity and moment","Mass, weight and density","Mass, volume and density"]', 1, 'Acceleration, velocity and the moment of a force all have both magnitude and direction. Mass, volume and density are scalars.', true, '2026-10-12 19:15:28.655', '2026-10-12 19:15:28.655', null, null, null, 'Which of the following is a set of vectors?', '["Force, mass and moment","Acceleration, velocity and moment","Mass, weight and density","Mass, volume and density"]', 'Acceleration, velocity and the moment of a force all have both magnitude and direction. Mass, volume and density are scalars.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c379wysz4nlxu2r2gr3ff6731', 'General Mathematics', 'WAEC', null, 2020, null, 'For what range of values of x is (x² - 5x + 6)/(x² - 4x + 3) > 0?', null, '["x < 1 or x > 3","1 < x < 2 or x > 3","x < 1 or 2 < x < 3","1 < x < 3"]', 0, 'Factor: (x-2)(x-3)/((x-1)(x-3)); sign chart gives x < 1 or 2 < x < 3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'For what range of values of x is (x² - 5x + 6)/(x² - 4x + 3) > 0?', '["x < 1 or x > 3","1 < x < 2 or x > 3","x < 1 or 2 < x < 3","1 < x < 3"]', 'Solution: <u>x < 1 or 2 < x < 3</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c37b6y1xkrssrojovws9z2150', 'Biology', 'JAMB', null, 1999, null, 'The division of a body into two equal halves along a l ongitudinal plane is called', null, '["bilateral symmetry","transverse section","radial symmetry","longitudinal section"]', 0, 'bilateral symmetry is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The division of a body into two equal halves along a l ongitudinal plane is called', '["<u>bilateral symmetry</u>","transverse section","radial symmetry","longitudinal section"]', 'bilateral symmetry is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c37hfzb20ik3td6vmz27a1gwl', 'Chemistry', 'JAMB', null, 2004, null, 'A characteristic of the alkane family is', null, '["substitution reaction","neutralization reaction","addition reaction","elimination reaction"]', 0, 'Alkanes undergo substitution.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A characteristic of the alkane family is', '["substitution reaction","neutralization reaction","addition reaction","elimination reaction"]', '<u>Substitution reaction</u>.', '{"bold":[],"italic":[],"underline":["substitution reaction"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c37ockwsmmri7uyumlz04av3j', 'Chemistry', 'JAMB', null, 1983, null, '3Cl2 + 2NH3 → N2 + 6HCl. In the above reaction, ammonia acts as', null, '["a reducing agent","an oxidizing agent","an acid","a catalyst","a drying agent"]', 0, 'NH3 is oxidized (loses electrons) so it acts as a reducing agent.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '3Cl2 + 2NH3 → N2 + 6HCl. In the above reaction, ammonia acts as', '["a reducing agent","an oxidizing agent","an acid","a catalyst","a drying agent"]', '<u>NH3 acts as a reducing agent</u>.', '{"bold":[],"italic":[],"underline":["a reducing agent"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c37odhyllc9iqeexoxzn2z96e', 'Biology', 'JAMB', null, 2001, null, 'Water fleas, wood lice and barnacles belong to the group', null, '["arachnida","crustacea","insecta","chilopoda"]', 1, 'Water fleas, wood lice, barnacles are crustaceans.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Water fleas, wood lice and barnacles belong to the group', '["arachnida","crustacea","insecta","chilopoda"]', '<u>Crustacea</u>.', '{"bold":[],"italic":[],"underline":["crustacea"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c37tqqt9i20oy0cwex3oa5h57', 'General Mathematics', 'WAEC', null, 2020, null, 'If log₈5 = x and log₅4 = y, express log₂25 in terms of x and y.', null, '["4/(3xy)","4xy/3","2xy/3","(4/3)(x + y)"]', 1, 'log₂25 = 2log₂5 = 2·(1/(log₅2)) = 2·(1/(1/(2·3x·y)))... Key says 4xy/3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If log₈5 = x and log₅4 = y, express log₂25 in terms of x and y.', '["4/(3xy)","4xy/3","2xy/3","(4/3)(x + y)"]', 'log₂25 = <u>4xy/3</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c37wr1uuqz9x8zmw0bxeybqhi', 'Physics', 'JAMB', null, 2021, null, 'Atomic bomb is an example of', null, '["fusion","controlled fusion reaction","uncontrolled fusion reaction","all of the above"]', 2, 'An atomic bomb is an uncontrolled nuclear fission reaction, but among the options, "uncontrolled fusion reaction" is the closest.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Atomic bomb is an example of', '["fusion","controlled fusion reaction","<u>uncontrolled fusion reaction</u>","all of the above"]', 'An atomic bomb is an <u>uncontrolled nuclear reaction</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c37x0lotd0fc5e3yfnzh0nfzf', 'Biology', 'JAMB', null, 1994, null, 'In spite of the removal of carbon dioxide from the atmosphere, its amount remains more or less constant because', null, '["it is produced by green plants during photosynthesis","it is produced during respiration by animals","it is absorbed in ocean water","green plants release it during the day"]', 1, 'CO2 is replenished by respiration of animals.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In spite of the removal of carbon dioxide from the atmosphere, its amount remains more or less constant because', '["it is produced by green plants during photosynthesis","<u>it is produced during respiration by animals</u>","it is absorbed in ocean water","green plants release it during the day"]', '<u>CO2 is replenished by respiration of animals</u>.', null);
