insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c38faht9stvzn2x315i5oash9', 'General Mathematics', 'WAEC', null, 2020, null, 'Express 0.125 as a percentage of 0.05.', null, '["200%","250%","300%","400%"]', 1, '0.125/0.05 = 2.5 = 250%.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Express 0.125 as a percentage of 0.05.', '["200%","250%","300%","400%"]', '0.125/0.05 = <u>250%</u>.', null);
