insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c38i0846ps05at0k52gnvh9ht', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Moses ran away from Egypt after killing an Egyptian because he felt that he might be', null, '["imprisoned by the Egyptian security officers","killed by Pharaoh of Egypt","endangering other Israelites by his actions","killed by the Egyptian mob."]', 1, 'He feared being killed by Pharaoh.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Moses ran away from Egypt after killing an Egyptian because he felt that he might be', '["imprisoned by the Egyptian security officers","<u>killed by Pharaoh of Egypt</u>","endangering other Israelites by his actions","killed by the Egyptian mob."]', '<u>Killed by Pharaoh of Egypt</u> (Exodus 2:14-15).', '{"bold":[],"italic":[],"underline":["killed by Pharaoh of Egypt"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c38lgpuwumskmbwbba645b3rw', 'Chemistry', 'JAMB', null, 1999, null, 'The set of pollutants that is most likely to be produced when petrol is accidentally spilled on plastic materials and ignited is', null, '["CO, CO2 and SO2","CO, HCl and SO2","CO, CO2 and HCl","SO2, CO2 and HCl"]', 2, 'Burning petrol + PVC plastic → CO, CO2, HCl.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The set of pollutants that is most likely to be produced when petrol is accidentally spilled on plastic materials and ignited is', '["CO, CO2 and SO2","CO, HCl and SO2","CO, CO2 and HCl","SO2, CO2 and HCl"]', '<u>CO, CO2, and HCl</u> are produced.', '{"bold":[],"italic":[],"underline":["CO, CO2 and HCl"],"fillBlanks":[]}');
