insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c38w32y6raffa2qii3pnt79xv', 'General Mathematics', 'JAMB', null, 2020, null, 'If x = 1 + 1/3 + 1/3² + ... and y = 1 + 1/4 + 1/4² + ..., find log_xy(x/y).', null, '["1/2","2log₂3 - 3","1/3","-1/3"]', 1, 'x = 3/2, y = 4/3, xy = 2, x/y = 9/8; log₂(9/8) = 2log₂3 - 3 ≈ 0.17.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'If x = 1 + 1/3 + 1/3² + ... and y = 1 + 1/4 + 1/4² + ..., find log_xy(x/y).', '["1/2","2log₂3 - 3","1/3","-1/3"]', 'x = 3/2, y = 4/3, xy = 2, x/y = 9/8; log₂(9/8) = 2log₂3 - 3 ≈ 0.17.', '{"bold":[],"italic":[],"underline":["-1/2"],"fillBlanks":[]}');
