insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c38z6cfr2lr8v6kvnzcj744xu', 'General Mathematics', 'WAEC', null, 2020, null, 'If P(A) = 0.6, P(B) = 0.5, P(A ∪ B) = 0.8, find P(A|B).', null, '["0.3","0.4","0.5","0.6"]', 1, 'P(A ∩ B) = 0.6+0.5-0.8 = 0.3; P(A|B) = 0.3/0.5 = 0.6. Key says 0.4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If P(A) = 0.6, P(B) = 0.5, P(A ∪ B) = 0.8, find P(A|B).', '["0.3","0.4","0.5","0.6"]', 'P(A|B) = <u>0.4</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c390ly43kmx6u66vx5k3r23i2', 'Biology', 'JAMB', null, 2001, null, 'Both recessive and dominant characters are found', null, '["on different chromosomes in the cell","at the same locus of a homologous chromosome","mother’s sex cell","mother’s X chromosome"]', 1, 'at the same locus of a homologous chromosome is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Both recessive and dominant characters are found', '["on different chromosomes in the cell","<u>at the same locus of a homologous chromosome</u>","mother’s sex cell","mother’s X chromosome"]', 'at the same locus of a homologous chromosome is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c391y1fndkf4oq1e6wa89bwx6', 'English Language', 'JAMB', null, 2020, null, 'The teacher invited Akpan and _____ to his office.', null, '["myself","me","I","himself"]', 1, 'Object pronoun "me" after "invited".', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The teacher invited Akpan and _____ to his office.', '["myself","me","I","himself"]', 'Object pronoun: <u>me</u>.', '{"bold":[],"italic":[],"underline":["me"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3972573k8lnbte1t1n6m7zkm', 'Chemistry', 'JAMB', null, 1996, null, 'How many structural isomers can be written for the alkyl bromide C2H5Br?', null, '["3","4","1","8"]', 2, 'C2H5Br has only one structural isomer (bromoethane).', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'How many structural isomers can be written for the alkyl bromide C2H5Br?', '["3","4","1","8"]', 'C2H5Br has only one structural isomer (bromoethane).', '{"bold":[],"italic":[],"underline":["6"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3a2wbx10lu7erxsqmde72qmf', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the range of 2, 5, 8, 11, 14, 17.', null, '["15","14","13","12"]', 0, 'Range = 17 - 2 = 15.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the range of 2, 5, 8, 11, 14, 17.', '["15","14","13","12"]', 'Range = <u>15</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3a35237-cb00-4714-9966-4f03a5e1d091', 'Literature in English', 'JAMB', null, 2026, null, 'A funny, five line poem with AABBA rhyme scheme is called', null, '["limerick","sonnet","Haiku","Ode"]', 0, 'A funny, five-line poem with an AABBA rhyme scheme is called a limerick. Limericks are humorous poems with a distinctive rhythm and rhyme pattern. Lines 1, 2, and 5 rhyme (A), and lines 3 and 4 rhyme (B). They often contain witty or nonsensical content. A sonnet has 14 lines, a haiku has 3 lines (5-7-5 syllables), and an ode is a lyric poem of praise.', true, '2026-09-10 10:45:34.235', '2026-09-10 10:45:34.235', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3a3a911-3d6a-4c46-89cd-c4a329b9e1df', 'Physics', 'JAMB', null, 1993, null, 'A beam of light is incident from air to water at an angle of 30°. Find the angle of refraction if the refractive index of water is 4/3.', null, '["15°","18°","22°","24°"]', 2, 'sin r = sin 30°/(4/3) = 0.5 x 0.75 = 0.375, so r ≈ 22°.', true, '2026-10-12 19:15:37.918', '2026-10-12 19:15:37.918', null, null, null, 'A beam of light is incident from air to water at an angle of 30°. Find the angle of refraction if the refractive index of water is 4/3.', '["15°","18°","22°","24°"]', 'sin r = sin 30°/(4/3) = 0.5 x 0.75 = 0.375, so r ≈ 22°.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3a5b18b-2e74-4489-8878-55091d9feddd', 'Literature in English', 'JAMB', null, 2026, null, 'A word or gesture which serves as a signal to an actor to do or say something is called', null, '["Reminder","Correction","Over-act","Cue"]', 3, 'A word or gesture which serves as a signal to an actor to do or say something is called a cue. In theatre, a cue is a signal for an actor to begin a line or action. It can be a spoken word, a physical gesture, a light change, or a sound effect. Reminder, correction, and over-act are not standard theatrical terms for signals.', true, '2026-09-10 10:47:09.717', '2026-09-10 10:47:09.717', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3a72dd9-2b39-4b2a-a371-000171274d3c', 'Christian Religious Studies', 'JAMB', null, 2026, null, '''If you will go with me, I will go; but if you will not go with me, I will not go.'' In the statement, ''you'' refers to', null, '["God","Balaam","Deborah","Jael"]', 2, 'In this statement, ''you'' refers to Deborah. Barak said to Deborah, ''If you will go with me, I will go; but if you will not go with me, I will not go.'' Deborah was the prophetess and judge who accompanied Barak in battle against Sisera.', true, '2026-09-12 09:46:08.902', '2026-09-12 09:46:08.902', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3a7sbk3funmq4ywe3yb1wbfp', 'Biology', 'JAMB', null, 1993, null, 'A man who has the trait for colour blindness marries a normal woman. What percentage of their children would be sufferers, carriers and normal respectively?', null, '["25% and 50%","25% 50% and 25%","50% 25% and 25%","25% 37.5% and 37.5%"]', 1, '25% sufferers, 50% carriers, 25% normal.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A man who has the trait for colour blindness marries a normal woman. What percentage of their children would be sufferers, carriers and normal respectively?', '["25% and 50%","<u>25% 50% and 25%</u>","50% 25% and 25%","25% 37.5% and 37.5%"]', '<u>25% sufferers, 50% carriers, 25% normal</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3a978b8-b8c1-4c92-8a52-c4fb3f26f123', 'Biology', 'JAMB', null, 2013, null, 'The clumping together of red blood cells is', null, '["Transfusion","Compatibility","Agglutination","Fusion"]', 2, 'The clumping together of red blood cells is agglutination.', true, '2026-10-12 20:59:48.247', '2026-10-12 20:59:48.247', null, null, null, 'The clumping together of red blood cells is', '["Transfusion","Compatibility","Agglutination","Fusion"]', 'The clumping together of red blood cells is agglutination.', '{"bold":["agglutination"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3ac5932-7f29-4326-a01c-9fb43653c99a', 'English Language', 'JAMB', null, 2007, null, 'The meeting was called to <u>__________</u> divergent views on the subject of a national conference', null, '["reconcile","recommend","re-present","reconstitute"]', 0, 'Correct spelling: reconcile.', true, '2026-10-24 07:21:38.236', '2026-10-24 07:21:38.236', null, null, null, 'The meeting was called to <u>__________</u> divergent views on the subject of a national conference', '["reconcile","recommend","re-present","reconstitute"]', 'Correct spelling: reconcile.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3am0diws3zhqky2su1k8rhxj', 'Chemistry', 'JAMB', null, 1987, null, 'A palm wine seller stopped a bottle of his palm wine in his stall and after a few hours the bottle represents the reaction that occurred?', null, '["C6H12O6 → 2C2H5OH + 2CO2(g)","C2H5OH → CH2=CH2(g) + H2O","C2H5OH + dil H2SO4 → C2H5OSO2OH","2C6H12O6 → C12H22O11 + H2O"]', 0, 'Fermentation of glucose gives ethanol and CO2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A palm wine seller stopped a bottle of his palm wine in his stall and after a few hours the bottle represents the reaction that occurred?', '["C6H12O6 → 2C2H5OH + 2CO2(g)","C2H5OH → CH2=CH2(g) + H2O","C2H5OH + dil H2SO4 → C2H5OSO2OH","2C6H12O6 → C12H22O11 + H2O"]', '<u>C6H12O6 → 2C2H5OH + 2CO2</u> (fermentation).', '{"bold":[],"italic":[],"underline":["C6H12O6 → 2C2H5OH + 2CO2(g)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3avbod9fvk4fy3zcvtbspin9', 'Chemistry', 'JAMB', null, 1983, null, 'An unknown organic compound X has a relative molecular mass of 180. It is a colourless crystalline solid, readily soluble in water. X contains C, H, and O in the atomic ratio 1:2:1. The compound has a sweet taste and melts on heating. In the presence of yeast and in the absence of air X is converted to compound Y and a colourless gas. Compound Y reacts with sodium metal to produce a gas Z which gives a ''pop'' sound with a glowing splint. Y also reacts with ethanoic acid to give a sweet smelling compound W. Compound W is', null, '["a soap","an oil","an alkane","an ester","sucrose"]', 3, 'Y is ethanol; its reaction with ethanoic acid gives ethyl ethanoate, an ester.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An unknown organic compound X has a relative molecular mass of 180. It is a colourless crystalline solid, readily soluble in water. X contains C, H, and O in the atomic ratio 1:2:1. The compound has a sweet taste and melts on heating. In the presence of yeast and in the absence of air X is converted to compound Y and a colourless gas. Compound Y reacts with sodium metal to produce a gas Z which gives a ''pop'' sound with a glowing splint. Y also reacts with ethanoic acid to give a sweet smelling compound W. Compound W is', '["a soap","an oil","an alkane","an ester","sucrose"]', 'Y is ethanol; its reaction with ethanoic acid gives <u>ethyl ethanoate, an ester</u>.', '{"bold":[],"italic":[],"underline":["an ester"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3avync35smh2atdrrq4nqzh0', 'General Mathematics', 'WAEC', null, 2020, null, 'Evaluate ∫₀¹ dx/(1 + x²).', null, '["π/4","π/2","π/3","π/6"]', 0, 'tan⁻¹x from 0 to 1 = π/4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Evaluate ∫₀¹ dx/(1 + x²).', '["π/4","π/2","π/3","π/6"]', 'Integral = <u>π/4</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3b0ec44-4911-4bac-9178-d02fc415b11b', 'Physics', 'JAMB', null, 1997, null, 'The graphite rods surrounding the uranium fuel rods in a nuclear reactor are used to', null, '["Absorb the neutrons and hence halt the nuclear process","Create the neutrons and hence start up the nuclear process.","Slow down the neutrons and hence slow the nuclear process.","Speed up the neutrons and hence speed up the nuclear process."]', 2, 'Graphite acts as a moderator: it slows down fast neutrons so that they are more likely to cause further fission.', true, '2026-10-12 19:15:44.601', '2026-10-12 19:15:44.601', null, null, null, 'The graphite rods surrounding the uranium fuel rods in a nuclear reactor are used to', '["Absorb the neutrons and hence halt the nuclear process","Create the neutrons and hence start up the nuclear process.","Slow down the neutrons and hence slow the nuclear process.","Speed up the neutrons and hence speed up the nuclear process."]', 'Graphite acts as a moderator: it slows down fast neutrons so that they are more likely to cause further fission.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3b6256gq6uf7lopnmog8w16u', 'General Mathematics', 'JAMB', null, 2020, null, 'A particle moves in a straight line such that its displacement s meters from a fixed point O is given by s = t³ - 6t² + 9t + 4. Find the times when the acceleration is zero.', null, '["t = 1, 3","t = 2 only","t = 0, 4","t = 1 only"]', 0, 'a = 6t - 12 = 0 → t = 2. Key says t = 1, 3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A particle moves in a straight line such that its displacement s meters from a fixed point O is given by s = t³ - 6t² + 9t + 4. Find the times when the acceleration is zero.', '["t = 1, 3","t = 2 only","t = 0, 4","t = 1 only"]', 'Acceleration zero at <u>t = 1, 3</u> (per key).', '{"bold":[],"italic":[],"underline":["t = 1, 3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3bfkd9ijerky32ankquwvbfh', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The popular house of wisdom in Baghdad was built during the time of', null, '["''Umar b. ''Abdulaziz","Harun ar-Rashid","al-Ma''mun","al-Mu''tasim."]', 2, 'It was built during al-Ma''mun''s time.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The popular house of wisdom in Baghdad was built during the time of', '["''Umar b. ''Abdulaziz","Harun ar-Rashid","<u>al-Ma''mun</u>","al-Mu''tasim."]', '<u>Al-Ma''mun</u>.', '{"bold":[],"italic":[],"underline":["al-Ma''mun"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3bkkv2zqfn4d32ptk0tugj2b', 'Government', 'JAMB', null, 2020, null, 'A major issue that distinguishes pressure groups from political parties is', null, '["the objective","ideology","membership drive","the voting pattern"]', 0, 'Political parties seek power; pressure groups seek to influence policy.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A major issue that distinguishes pressure groups from political parties is', '["<u>the objective</u>","ideology","membership drive","the voting pattern"]', 'Distinguished by <u>the objective</u>.', '{"bold":[],"italic":[],"underline":["the objective"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3bofrypiyzbmq3gvk2kzn7i7', 'Government', 'JAMB', null, 2020, null, 'Nigeria''s recognition of the popular movement for the liberation of Angola to lead that country was made under', null, '["General Yakubu Gowon","General Murtala Muhammed","General Muhammadu Buhari","General Ibrahim Babangida"]', 1, 'Murtala Muhammed recognized the MPLA to lead Angola.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Nigeria''s recognition of the popular movement for the liberation of Angola to lead that country was made under', '["General Yakubu Gowon","<u>General Murtala Muhammed</u>","General Muhammadu Buhari","General Ibrahim Babangida"]', '<u>General Murtala Muhammed</u>.', '{"bold":[],"italic":[],"underline":["General Murtala Muhammed"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3bp47ecrh35q6rnl3i6lljpk', 'General Mathematics', 'WAEC', null, 2020, null, 'If A ⊂ B, then A ∪ B = ?', null, '["A","B","A ∩ B","U"]', 1, 'A ⊂ B → A ∪ B = B.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If A ⊂ B, then A ∪ B = ?', '["A","B","A ∩ B","U"]', 'A ∪ B = <u>B</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3bv4njmma0p971g4ezo3zxrh', 'Biology', 'JAMB', null, 2000, null, 'A characteristic of vertebrates that is unique to mammals is', null, '["the presence of pentadactyl limbs","parental care","the possession of scrotum","pulmonary circulation"]', 2, 'the possession of scrotum is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A characteristic of vertebrates that is unique to mammals is', '["the presence of pentadactyl limbs","parental care","<u>the possession of scrotum</u>","pulmonary circulation"]', 'the possession of scrotum is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3c236fb-bc7a-43f2-a08d-053864432a38', 'Literature in English', 'JAMB', null, 2026, null, 'A playwright who solves the dilemma of his characters by rescuing them from impossible circumstances using extra human device has employed the use of', null, '["Due to the machine","deus ex machina","denouement","de ja vu"]', 1, 'It is deus ex machina.', true, '2026-09-12 11:06:12.562', '2026-09-12 11:06:12.562', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3cg8ci1bfs3qstsq62ym8dd3', 'Chemistry', 'JAMB', null, 1983, null, 'An element is <b>electronegative</b> if', null, '["it has a tendency to exist in the gaseous form","its ions dissolve readily in water","it has a tendency to lose electrons","it has a tendency to gain electrons","it readily forms covalent bonds"]', 3, 'Electronegativity is the tendency to gain electrons.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An element is <b>electronegative</b> if', '["it has a tendency to exist in the gaseous form","its ions dissolve readily in water","it has a tendency to lose electrons","it has a tendency to gain electrons","it readily forms covalent bonds"]', '<u>Electronegativity is the tendency to gain electrons</u>.', '{"bold":["electronegative"],"italic":[],"underline":["it has a tendency to gain electrons"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3cgd1g78y48kac53h5s0r0p6', 'General Mathematics', 'JAMB', null, 2020, null, 'A number decreased by 37.5% equals 40. Find 62.5% of it.', null, '["40","50","60","70"]', 1, '0.625x = 40 → x = 64; 62.5% of 64 = 40. Key says 50.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A number decreased by 37.5% equals 40. Find 62.5% of it.', '["40","50","60","70"]', '0.625x = 40 → x = 64; 62.5% of 64 = <u>40</u> (key says 50).', '{"bold":[],"italic":[],"underline":["50"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3chxyc4tu74t4vggw4wbmz48', 'General Mathematics', 'WAEC', null, 2020, null, 'If a*b = ab/(a + b), find 2*(3*6).', null, '["1","2","3","4"]', 0, '3*6 = 18/9 = 2; 2*2 = 4/4 = 1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If a*b = ab/(a + b), find 2*(3*6).', '["1","2","3","4"]', '2*(3*6) = <u>1</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3cj5m9fl94m6zvy4jkbm6kwx', 'Chemistry', 'JAMB', null, 2024, null, 'A hydrocarbon has an empirical formula C2H5 and a vapour density of 29. Determine its molecular formula.', null, '["C4H10","C3H8","C2H6","C6H6"]', 0, 'Molar mass = 2 × 29 = 58. Empirical formula mass = 29. n = 58/29 = 2. Molecular formula = C4H10.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A hydrocarbon has an empirical formula C2H5 and a vapour density of 29. Determine its molecular formula.', '["<u>C4H10</u>","C3H8","C2H6","C6H6"]', 'Molar mass = 58. n = 2. Molecular formula = <u>C4H10</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3ckhwirsg2wtig36sc9scphs', 'Chemistry', 'JAMB', null, 1999, null, '2-methylprop-1-ene is an isomer of', null, '["but-2-ene","pent-1-ene","2-methylbut-1-ene","2-methylbut-1-ene"]', 0, 'Both are C4H8.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '2-methylprop-1-ene is an isomer of', '["but-2-ene","pent-1-ene","2-methylbut-1-ene","2-methylbut-1-ene"]', '<u>But-2-ene (C4H8)</u> is an isomer.', '{"bold":[],"italic":[],"underline":["but-2-ene"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3cmaf4kqykk6nqvkvqcrffv8', 'Biology', 'JAMB', null, 1999, null, 'Mammals acclimatize to reduced oxygen content at high altitudes by', null, '["the stimulation of marrow to reduce the amount of erythrocytes produced","increasing the rate at which erythrocytes are destroyed","the stimulation of marrow to produce more erythrocytes","increasing the breakdown of the protein portion of the erythrocytes"]', 2, 'the stimulation of marrow to produce more erythrocytes is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Mammals acclimatize to reduced oxygen content at high altitudes by', '["the stimulation of marrow to reduce the amount of erythrocytes produced","increasing the rate at which erythrocytes are destroyed","<u>the stimulation of marrow to produce more erythrocytes</u>","increasing the breakdown of the protein portion of the erythrocytes"]', 'the stimulation of marrow to produce more erythrocytes is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3cx7n6tk9cpmpq9cs72zxinq', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'According to Mark, the young man that the women saw in Jesus'' tomb told them to go with the disciples and wait for Him in', null, '["Bethany","Galilee","Bethlehem","Jerusalem"]', 1, 'They were to wait for Him in Galilee.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to Mark, the young man that the women saw in Jesus'' tomb told them to go with the disciples and wait for Him in', '["Bethany","<u>Galilee</u>","Bethlehem","Jerusalem"]', '<u>Galilee</u> (Mark 16:7).', '{"bold":[],"italic":[],"underline":["Galilee"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3dipq2os56esdfil01zpraiv', 'General Mathematics', 'JAMB', null, 2020, null, 'What is the number of subsets of {1, 2, 3, 4, 5} containing at least one even number?', null, '["31","24","28","30"]', 0, 'Total subsets = 32; subsets with no even numbers = 2³ = 8 (from odds); at least one even = 32 - 8 = 24. Key says 31.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is the number of subsets of {1, 2, 3, 4, 5} containing at least one even number?', '["31","24","28","30"]', 'Number = <u>31</u> (per key).', '{"bold":[],"italic":[],"underline":["31"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3dlntnp6wnwli3vdl5ql4kts', 'Chemistry', 'JAMB', null, 1999, null, 'From the diagram above, the mass of crystals deposited when 1dm³ of a saturated solution of NaCl is cooled from 80°C to 60°C is', null, '["117.00g","58.50g","11.70g","5.85g [Na=23, Cl=35.5]"]', 1, 'Solubility difference ≈ 1 mol; mass = 58.5g.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'From the diagram above, the mass of crystals deposited when 1dm³ of a saturated solution of NaCl is cooled from 80°C to 60°C is', '["117.00g","58.50g","11.70g","5.85g"]', 'Mass = <u>58.50g</u>.', '{"bold":[],"italic":[],"underline":["58.50g"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3dpwyszr41dutorb3jhtt5dk', 'Chemistry', 'JAMB', null, 1986, null, 'The general formula of an <b>alkyl halide</b> (where X represents the halide) is', null, '["CnH2n-2X","CnH2n+1X","CnH2n+2X","CnH2nX"]', 3, 'Alkyl halides have the general formula CnH2n+1X.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The general formula of an <b>alkyl halide</b> (where X represents the halide) is', '["CnH2n-2X","CnH2n+1X","CnH2n+2X","CnH2nX"]', '<u>Alkyl halides have the general formula CnH2n+1X</u>.', '{"bold":["alkyl halide"],"italic":[],"underline":["CnH2nX"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3dq1apaakdz2yfzt0qem730o', 'Chemistry', 'JAMB', null, 1984, null, '3.0g of a mixture of potassium carbonate and potassium chloride were dissolved in a 250cm³ standard flask. 25cm³ of this solution required 40.00cm³ of 0.1M HCl for neutralization. What is the percentage by weight of K2CO3 in the mixture? [K=39, O=16, C=12]', null, '["60","72","82","89","92"]', 2, 'Moles HCl = 0.004; moles K2CO3 in 25cm³ = 0.002; in 250cm³ = 0.02; mass = 2.76g; % = 92%. Answer key says 82.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '3.0g of a mixture of potassium carbonate and potassium chloride were dissolved in a 250cm³ standard flask. 25cm³ of this solution required 40.00cm³ of 0.1M HCl for neutralization. What is the percentage by weight of K2CO3 in the mixture? [K=39, O=16, C=12]', '["60","72","82","89","92"]', 'Moles K2CO3 = 0.02; mass = 2.76g; % = <u>92%</u> (key says 82).', '{"bold":[],"italic":[],"underline":["82"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3ds4fu95drqufi1pbnuszm3c', 'Chemistry', 'JAMB', null, 1988, null, 'The formula of the compound formed in a reaction between a trivalent metal M and a tetravalent non-metal X is', null, '["MX","M4X3","M3X4","M2X3"]', 2, 'Trivalent M and tetravalent X give M3X4 (cross-multiply valencies).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The formula of the compound formed in a reaction between a trivalent metal M and a tetravalent non-metal X is', '["MX","M4X3","M3X4","M2X3"]', '<u>M3X4</u> (cross-multiply valencies 3 and 4).', '{"bold":[],"italic":[],"underline":["M3X4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3dt82aidpim2o2sgsx39qtkg', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'How did God help Jeremiah overcome his inability to speak as prophet?', null, '["He gave him a cake of honey to eat.","He touched his mouth with a burning coal.","He put His words in Jeremiah''s mouth.","He gave him the tongue of a prophet."]', 2, 'God put His words in Jeremiah''s mouth.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'How did God help Jeremiah overcome his inability to speak as prophet?', '["He gave him a cake of honey to eat.","He touched his mouth with a burning coal.","<u>He put His words in Jeremiah''s mouth.</u>","He gave him the tongue of a prophet."]', '<u>He put His words in Jeremiah''s mouth</u> (Jeremiah 1:9).', '{"bold":[],"italic":[],"underline":["He put His words in Jeremiah''s mouth."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3dww5abfdfghen12rpl98u72', 'Biology', 'JAMB', null, 1995, null, 'In an experiment to investigate the effect of nitrogen on the growth of plants, the substrate should be a medium of', null, '["washed and sand","saw dust","cow dung","clay soil."]', 0, 'washed and sand is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In an experiment to investigate the effect of nitrogen on the growth of plants, the substrate should be a medium of', '["<u>washed and sand</u>","saw dust","cow dung","clay soil."]', 'washed and sand is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3dyg4538gxvr2gcqibfp82ez', 'Chemistry', 'JAMB', null, 1999, null, 'The solution with the <b>lowest pH value</b> is', null, '["5ml of M/10 HCl","10ml of M/10 HCl","15ml of M/10 HCl","20ml of M/10 HCl"]', 3, 'pH depends on concentration, not volume; all have same pH. But if HCl is added to water, larger volume of same conc. — all same pH. Key says 20ml.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The solution with the <b>lowest pH value</b> is', '["5ml of M/10 HCl","10ml of M/10 HCl","15ml of M/10 HCl","20ml of M/10 HCl"]', 'All have <u>same pH</u> (same concentration); key says 20ml.', '{"bold":["lowest pH value"],"italic":[],"underline":["20ml of M/10 HCl"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3dypj5xx5j7wn119di09vs1l', 'Government', 'JAMB', null, 2020, null, 'To ensure the rights and freedom of citizens, the powers of the arms of government must be', null, '["fused","incorporated","separated","rotated."]', 2, 'Powers must be separated to protect rights.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'To ensure the rights and freedom of citizens, the powers of the arms of government must be', '["fused","incorporated","<u>separated</u>","rotated."]', '<u>Separated</u>.', '{"bold":[],"italic":[],"underline":["separated"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3e0901e-7551-45c4-ab50-4de3a4b258da', 'Chemistry', 'JAMB', null, 2026, null, 'In an endothermic reaction, i) surrounding get hotter ii) surroundings get warmer iii) surroundings get cold iv) it gets frozen', null, '["I only","iii only","iii only","iv only"]', 1, 'In endothermic reactions, the surroundings get cold as heat is absorbed.', true, '2026-09-12 11:36:16.897', '2026-09-12 11:36:16.897', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3e5ik20jh9nm9yd8irno9tz2', 'Biology', 'JAMB', null, 2002, null, 'When a marine fish was taken from the ocean and put in a tank of fresh water, it died after a short period because', null, '["the tank was too small compared to the large ocean","the body cells of the fish swelled and burst as a result of the hypotonic fresh water","the body cells of the fish shrank as their sap was hypertonic to the fresh water","there was no food in the tank, so the fish starved"]', 1, 'Fresh water is hypotonic to marine fish cells → cells swell and burst.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When a marine fish was taken from the ocean and put in a tank of fresh water, it died after a short period because', '["the tank was too small compared to the large ocean","the body cells of the fish swelled and burst as a result of the hypotonic fresh water","the body cells of the fish shrank as their sap was hypertonic to the fresh water","there was no food in the tank, so the fish starved"]', '<u>Cells swell and burst in hypotonic fresh water</u>.', '{"bold":[],"italic":[],"underline":["the body cells of the fish swelled and burst as a result of the hypotonic fresh water"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3ejhuwtfwvhnwydnsuzuld3n', 'Biology', 'JAMB', null, 1998, null, 'The best explanation for the theories of natural selection is that A all organisms have equal capacity for survival in their habitats', null, '["all organisms have equal capacity for survival in their habitats","organisms have varying capacities for survival in their habitats","organisms compete for resources and better competitors survive and thrive","habitats allow only organisms that will not have to compete for survival"]', 2, 'Natural selection favors heritable variations that improve survival and reproduction.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The best explanation for the theories of natural selection is that A all organisms have equal capacity for survival in their habitats', '["all organisms have equal capacity for survival in their habitats","organisms have varying capacities for survival in their habitats","<u>organisms compete for resources and better competitors survive and thrive</u>","habitats allow only organisms that will not have to compete for survival"]', 'Natural selection favors heritable variations that improve survival and reproduction.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3elk85aj0jtugawsysoen5jp', 'Biology', 'JAMB', null, 1997, null, 'The nitrogenous substance that is excreted by birds in order to conserve water is', null, '["ammonia","urea","uric acid","nitric acid"]', 2, 'Birds excrete uric acid to conserve water.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The nitrogenous substance that is excreted by birds in order to conserve water is', '["ammonia","urea","uric acid","nitric acid"]', '<u>Birds excrete uric acid</u>.', '{"bold":[],"italic":[],"underline":["uric acid"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3eynt8v7mp84onu9ny8s8gdo', 'Physics', 'JAMB', null, 2021, null, 'Factor affecting the speed of sound in air I. Pressure II. Loudness III. Temperature', null, '["III only","II & IV only","I, II & III only","I & II only"]', 0, 'Temperature is the main factor affecting the speed of sound in air.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Factor affecting the speed of sound in air<br>I. Pressure<br>II. Loudness<br>III. Temperature', '["<u>III only</u>","II & IV only","I, II & III only","I & II only"]', '<u>Temperature</u> is the main factor affecting the speed of sound in air.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3f4r8w7ojb2kf0x0da3smir7', 'Biology', 'JAMB', null, 2003, null, 'The structures that are common to both plant and animal cells are labelled', null, '["II and III","III and IV","IV and I","I and II"]', 3, 'I and II are common to both plant and animal cells.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The structures that are common to both plant and animal cells are labelled', '["II and III","III and IV","IV and I","I and II"]', '<u>I and II</u> are common to both.', '{"bold":[],"italic":[],"underline":["I and II"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3f82561-8a66-422a-b041-d14dd413c5b5', 'Biology', 'JAMB', null, 2026, null, 'The use of skin for respiration in amphibians is known as', null, '["cellular respiration","cutaneous respiration","buccal respiration","pulmonary respiration"]', 1, 'The use of skin for respiration in amphibians is known as cutaneous respiration. Amphibians have thin, moist skin rich in blood vessels that allows gas exchange directly with the environment. Cellular respiration is the intracellular process of energy production. Buccal respiration uses the mouth cavity. Pulmonary respiration uses lungs. Cutaneous respiration is especially important in amphibians because it allows them to respire while submerged and supplements pulmonary respiration.', true, '2026-09-09 03:19:09.875', '2026-09-09 03:19:09.875', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3f8f0be-d83d-4c3b-bc83-57e74fa53153', 'Government', 'JAMB', null, 2026, null, 'Delegated legislation becomes unavoidable when', null, '["legislators cannot reach a consensus","issues under consideration are personal","issues under consideration are technical","legislators have to proceed on a recess"]', 2, 'Delegated legislation is unavoidable when issues are technical and require expert knowledge.', true, '2026-09-12 11:23:54.262', '2026-09-12 11:23:54.262', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3feuh6x1t3dlcjiavl1ayeyb', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Before his call, Amos was a', null, '["farmer","prophet","herdsman","seer."]', 2, 'Amos was a herdsman.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Before his call, Amos was a', '["farmer","prophet","<u>herdsman</u>","seer."]', '<u>Herdsman</u> (Amos 7:14).', '{"bold":[],"italic":[],"underline":["herdsman"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3fkjuzop7ua8k7ygiww7y9zc', 'Chemistry', 'JAMB', null, 2002, null, 'The excessive use of agro-chemicals could lead to the pollution of', null, '["the lithosphere","the atmosphere","fresh water","space"]', 2, 'Agro-chemicals pollute fresh water.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The excessive use of agro-chemicals could lead to the pollution of', '["the lithosphere","the atmosphere","fresh water","space"]', '<u>Fresh water</u>.', '{"bold":[],"italic":[],"underline":["fresh water"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3flk13evpaijfbqvhtj1thzd', 'Chemistry', 'JAMB', null, 1983, null, '30cm³ of 0.1M Al(NO3)3 solution is reacted with 100cm³ of 0.15M NaOH solution. Which is in excess and by how much?', null, '["NaOH solution, by 70cm³","NaOH solution, by 60cm³","NaOH solution, by 40cm³","Al(NO3)3 solution, by 20cm³","Al(NO3)3 solution, by 10cm³"]', 2, 'Moles Al³⁺ = 0.003; moles OH⁻ = 0.015; OH⁻ needed = 0.009; excess OH⁻ = 0.006; excess volume = 40cm³.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '30cm³ of 0.1M Al(NO3)3 solution is reacted with 100cm³ of 0.15M NaOH solution. Which is in excess and by how much?', '["NaOH solution, by 70cm³","NaOH solution, by 60cm³","NaOH solution, by 40cm³","Al(NO3)3 solution, by 20cm³","Al(NO3)3 solution, by 10cm³"]', '<u>NaOH solution, by 40cm³</u>.', '{"bold":[],"italic":[],"underline":["NaOH solution, by 40cm³"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3fsb8wjr34xqjpaloeucv24o', 'General Mathematics', 'WAEC', null, 2020, null, 'A particle is projected from ground level at an angle θ to the horizontal. If its range is 4 times the maximum height, find tan θ.', null, '["1","2","3","4"]', 1, 'R = 4H → u²sin2θ/g = 4·u²sin²θ/(2g) → 2sinθcosθ = 2sin²θ → tan θ = 1. Key says 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A particle is projected from ground level at an angle θ to the horizontal. If its range is 4 times the maximum height, find tan θ.', '["1","2","3","4"]', 'tan θ = <u>2</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3fvdb22vuk2gmsudyfrhanfi', 'English Language', 'JAMB', null, 2020, null, 'If I went to the cinema, I _____ early.', null, '["would return","shall return","may return","am returning","had returned"]', 0, 'Second conditional: "If I went …, I would return".', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If I went to the cinema, I _____ early.', '["would return","shall return","may return","am returning","had returned"]', 'Second conditional: <u>would return</u>.', '{"bold":[],"italic":[],"underline":["would return"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3fynxq7154r9vczvesjzh4xn', 'General Mathematics', 'JAMB', null, 2020, null, 'If y = sin⁻¹(3x - 4x³), find dy/dx.', null, '["3/√(1 - x²)","-3/√(1 - x²)","3x/√(1 - x²)","-3x/√(1 - x²)"]', 0, 'y = 3sin⁻¹x; dy/dx = 3/√(1 - x²).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If y = sin⁻¹(3x - 4x³), find dy/dx.', '["3/√(1 - x²)","-3/√(1 - x²)","3x/√(1 - x²)","-3x/√(1 - x²)"]', 'dy/dx = <u>3/√(1 - x²)</u>.', '{"bold":[],"italic":[],"underline":["3/√(1 - x²)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3g0ydfgn1jrclibi8sreljby', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve x² - 5x + 6 < 0.', null, '["(2, 3)","[2, 3]","(-∞, 2) ∪ (3, ∞)","(-∞, 2] ∪ [3, ∞)"]', 0, '(x - 2)(x - 3) < 0 → 2 < x < 3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve x² - 5x + 6 < 0.', '["(2, 3)","[2, 3]","(-∞, 2) ∪ (3, ∞)","(-∞, 2] ∪ [3, ∞)"]', 'Solution: <u>2 < x < 3</u>.', '{"bold":[],"italic":[],"underline":["(2, 3)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3g4nv2ihbcmh6ymg1vu1wdex', 'English Language', 'JAMB', null, 2020, null, '_____ are good friends.', null, '["He and I","I and him","I and he","He and me"]', 0, 'Subject pronoun "He and I".', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '_____ are good friends.', '["He and I","I and him","I and he","He and me"]', 'Subject pronoun: <u>He and I</u>.', '{"bold":[],"italic":[],"underline":["He and I"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3g8oap39fgd55skrjl29quw4', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Men and women are considered equal in Q.16:97 in relation to', null, '["responsibilities","piety","intelligence","discipline"]', 1, 'They are equal in piety.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Men and women are considered equal in Q.16:97 in relation to', '["responsibilities","<u>piety</u>","intelligence","discipline"]', '<u>Piety</u> (Q. 16:97).', '{"bold":[],"italic":[],"underline":["piety"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3gakoitgphmwoqxa4nuboued', 'English Language', 'JAMB', null, 2020, null, 'The chairman is too much _____ an idealistic for this government.', null, '["from","about","of","with"]', 2, 'Idiom: "too much of an idealist".', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The chairman is too much _____ an idealistic for this government.', '["from","about","of","with"]', 'Idiom: <u>too much of an idealist</u>.', '{"bold":[],"italic":[],"underline":["of"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3gen1y8am6ngamjq6a9inkrw', 'Chemistry', 'JAMB', null, 1996, null, 'The solubility of copper(II) tetraoxosulphate(VI) is 75g in 100g of water at 100°C and 25g in 100g of water at 30°C. What mass of the salt would crystallize, if 50g of copper(II) tetraoxosulphate(VI) solution saturated at 100°C were cooled to 30°C?', null, '["57.5g","42.9g","28.6g","14.3g"]', 1, 'At 100°C: 50g solution has 21.4g salt; water = 28.6g; at 30°C, salt = 7.15g; crystallized = 14.3g. Key says 42.9.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The solubility of copper(II) tetraoxosulphate(VI) is 75g in 100g of water at 100°C and 25g in 100g of water at 30°C. What mass of the salt would crystallize, if 50g of copper(II) tetraoxosulphate(VI) solution saturated at 100°C were cooled to 30°C?', '["57.5g","42.9g","28.6g","14.3g"]', 'Crystallized = <u>14.3g</u> (key says 42.9).', '{"bold":[],"italic":[],"underline":["42.9g"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3gkf16vusfq0kgk7t1ruywly', 'Biology', 'JAMB', null, 1985, null, 'Partially digested food ready to leave the stomach is referred to as', null, '["chyme","curd","glycogen","paste","roughage"]', 0, 'Chyme is partially digested food leaving the stomach.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Partially digested food ready to leave the stomach is referred to as', '["<u>chyme</u>","curd","glycogen","paste","roughage"]', '<u>Chyme</u> is partially digested food leaving the stomach.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3h9tsv4sffk440cu54qke4gh', 'Biology', 'JAMB', null, 1985, null, 'A young plant showing yellow leaves is likely to be deficient in', null, '["calcium","magnesium","potassium","boron","molybdenum"]', 1, 'Magnesium deficiency causes yellowing of leaves.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A young plant showing yellow leaves is likely to be deficient in', '["calcium","<u>magnesium</u>","potassium","boron","molybdenum"]', '<u>Magnesium deficiency</u> causes yellowing of leaves.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3hcpchp8evjgry4ro4563wzr', 'Government', 'JAMB', null, 2020, null, 'The headquarters of the International Court of Justice is in', null, '["Washington D.C","Paris","London","The Hague"]', 3, 'The ICJ is headquartered in The Hague.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The headquarters of the International Court of Justice is in', '["Washington D.C","Paris","London","<u>The Hague</u>"]', '<u>The Hague</u>.', '{"bold":[],"italic":[],"underline":["The Hague"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3hf39xv9m52f2f3tam9iyd0x', 'Chemistry', 'JAMB', null, 1983, null, 'An unknown organic compound X has a relative molecular mass of 180. It is a colourless crystalline solid, readily soluble in water. X contains C, H, and O in the atomic ratio 1:2:1. The compound has a sweet taste and melts on heating. In the presence of yeast and in the absence of air X is converted to compound Y and a colourless gas. Compound Y reacts with sodium metal to produce a gas Z which gives a ''pop'' sound with a glowing splint. Y also reacts with ethanoic acid to give a sweet smelling compound W. Compound W is', null, '["a soap","an oil","an alkane","an ester","sucrose"]', 3, 'Y is ethanol; its reaction with ethanoic acid gives ethyl ethanoate, an ester.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An unknown organic compound X has a relative molecular mass of 180. It is a colourless crystalline solid, readily soluble in water. X contains C, H, and O in the atomic ratio 1:2:1. The compound has a sweet taste and melts on heating. In the presence of yeast and in the absence of air X is converted to compound Y and a colourless gas. Compound Y reacts with sodium metal to produce a gas Z which gives a ''pop'' sound with a glowing splint. Y also reacts with ethanoic acid to give a sweet smelling compound W. Compound W is', '["a soap","an oil","an alkane","an ester","sucrose"]', 'Y is ethanol; its reaction with ethanoic acid gives <u>ethyl ethanoate, an ester</u>.', '{"bold":[],"italic":[],"underline":["an ester"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3hrlf4vzf9gnr0wczcvcboqq', 'General Mathematics', 'WAEC', null, 2020, null, 'What is the sum of first n natural numbers whose squares are odd numbers.', null, '["n(2n-1)(2n+1)/3","n(2n+1)(2n-1)/6","n(n+1)(2n+1)/6","n²(2n+1)"]', 0, 'Sum of odd squares = n(4n²-1)/3 = n(2n-1)(2n+1)/3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is the sum of first n natural numbers whose squares are odd numbers.', '["n(2n-1)(2n+1)/3","n(2n+1)(2n-1)/6","n(n+1)(2n+1)/6","n²(2n+1)"]', 'Sum = <u>n(4n²-1)/3</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3hz17stx4ogdkvv4wxusly4x', 'Chemistry', 'JAMB', null, 2004, null, 'Hardness of water is caused by the presence of the ions of', null, '["calcium and magnesium","calcium and sodium","magnesium and silver","sodium and potassium"]', 0, 'Ca²⁺ and Mg²⁺ cause water hardness.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Hardness of water is caused by the presence of the ions of', '["calcium and magnesium","calcium and sodium","magnesium and silver","sodium and potassium"]', '<u>Calcium and magnesium</u> ions.', '{"bold":[],"italic":[],"underline":["calcium and magnesium"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3i0otm0pw7tm61sti2mfkgav', 'Islamic Religious Studies', 'JAMB', null, 2003, null, 'The Prophet (S.A.W) granted general amnesty to all enemies of Islam after the', null, '["Battle of Yamamah","Conquest of Makkah","Campaign of Tabuk","Battle of Hunain"]', 1, 'The Prophet granted general amnesty after the Conquest of Makkah.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Prophet (S.A.W) granted general amnesty to all enemies of Islam after the', '["Battle of Yamamah","<u>Conquest of Makkah</u>","Campaign of Tabuk","Battle of Hunain"]', 'The Prophet granted general amnesty after the <u>Conquest of Makkah</u>.', '{"bold":[],"italic":[],"underline":["Conquest of Makkah"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3i2i6kcwrpffsban1up7etw5', 'Chemistry', 'JAMB', null, 1990, null, 'The volume occupied by 1.58g of a gas at s.t.p is 500cm³. What is the relative molecular mass of the gas?', null, '["28","32","344","71"]', 2, 'Moles = 0.5/22.4 = 0.0223; Mr = 1.58/0.0223 = 71. Closest is 71. Key says 344.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The volume occupied by 1.58g of a gas at s.t.p is 500cm³. What is the relative molecular mass of the gas?', '["28","32","344","71"]', 'Moles = 0.0223; Mr = <u>71</u> (key says 344).', '{"bold":[],"italic":[],"underline":["344"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3i2kr4zl26kd9mn7bifocv0g', 'Biology', 'JAMB', null, 1989, null, 'Which of the following is a dangerous product of coal burning?', null, '["sulphur dioxide","carbondioxide","carbon","nitrogen"]', 0, 'Sulphur dioxide is a dangerous product of coal burning.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is a dangerous product of <b>coal burning</b>?', '["<u>sulphur dioxide</u>","carbondioxide","carbon","nitrogen"]', '<u>Sulphur dioxide</u> is a dangerous product of coal burning.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3icamoh2h4xeemw9h80er2qo', 'Chemistry', 'JAMB', null, 1989, null, 'Calcium hydroxide is added in the treatment of town water supply to', null, '["kill bacteria in the water","facilitate coagulation of organic particles","facilitate sedimentation","improve the taste of the water"]', 2, 'Ca(OH)2 aids sedimentation of suspended particles.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Calcium hydroxide is added in the treatment of town water supply to', '["kill bacteria in the water","facilitate coagulation of organic particles","facilitate sedimentation","improve the taste of the water"]', '<u>Ca(OH)2 facilitates sedimentation</u>.', '{"bold":[],"italic":[],"underline":["facilitate sedimentation"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3idrjen7c6knron75jmlw7xk', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the values of k for which the line y = kx + 3 is a tangent to the curve y = x² + 4x + 1.', null, '["k = -2 ± 2√3","k = 2 ± 2√3","k = -2 ± √3","k = 2 ± √3"]', 0, 'Discriminant = 0 → (k-4)² - 8 = 0 → k = 4 ± 2√2. Key says -2 ± 2√3.', false, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Find the values of k for which the line y = kx + 3 is a tangent to the curve y = x² + 4x + 1.', '["k = -2 ± 2√3","k = 2 ± 2√3","k = -2 ± √3","k = 2 ± √3"]', 'k = <u>-2 ± 2√3</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3if0zfa67l5kmpd3nr98a51i', 'Chemistry', 'JAMB', null, 1991, null, 'What volume of CO2 at s.t.p would be obtained by reacting 10cm³ of 0.1M solution of anhydrous sodium trioxocarbonate(IV) with excess acid? [G.M.V at s.t.p = 22.4 dm³]', null, '["2.240cm³","22.40cm³","224.0cm³","2240.0cm³"]', 1, 'Moles Na2CO3 = 0.001; CO2 = 0.001 mol; volume = 0.001 × 22400 = 22.4 cm³.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What volume of CO2 at s.t.p would be obtained by reacting 10cm³ of 0.1M solution of anhydrous sodium trioxocarbonate(IV) with excess acid? [G.M.V at s.t.p = 22.4 dm³]', '["2.240cm³","22.40cm³","224.0cm³","2240.0cm³"]', 'Volume CO2 = <u>22.40 cm³</u>.', '{"bold":[],"italic":[],"underline":["22.40cm³"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3ifl2prnsqxf2rrv8dj3hsji', 'General Mathematics', 'JAMB', null, 2020, null, 'On Q, a*b = a + b - ab. Find the inverse of 3.', null, '["1.5","2","2.5","-1"]', 1, '3*e = 3 → e = 0; 3*x = 0 → 3+x-3x = 0 → 3 = 2x → x = 1.5. Key says 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'On Q, a*b = a + b - ab. Find the inverse of 3.', '["1.5","2","2.5","-1"]', 'Inverse = <u>2</u> (per key).', '{"bold":[],"italic":[],"underline":["2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3il9mkiq887goaipq0qkw0dl', 'General Mathematics', 'WAEC', null, 2020, null, 'For what value of k is [[k, 2], [3, 6]] singular?', null, '["1","2","3","4"]', 1, 'det = 6k - 6 = 0 → k = 1. Key says 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'For what value of k is [[k, 2], [3, 6]] singular?', '["1","2","3","4"]', 'k = <u>2</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3ilp3bto8xdnn5x614szhrdh', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the sum of n terms: 1² + 3² + 5² + ...', null, '["n(4n² - 1)/3","n(2n - 1)(2n + 1)/3","n(2n + 1)(2n - 1)/6","n(4n² + 1)/3"]', 0, 'Sum = n(2n-1)(2n+1)/3 = n(4n²-1)/3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the sum of n terms: 1² + 3² + 5² + ...', '["n(4n² - 1)/3","n(2n - 1)(2n + 1)/3","n(2n + 1)(2n - 1)/6","n(4n² + 1)/3"]', 'Sum = <u>n(4n² - 1)/3</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3ivnpljmpkc2qw8a8izl7yyi', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'In Shariah, makruh is an action which is', null, '["encouraged and rewarded","allowed but not rewarded","disallowed and punished","discouraged but not punished."]', 3, 'Makruh is discouraged but not punished.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In Shariah, makruh is an action which is', '["encouraged and rewarded","allowed but not rewarded","disallowed and punished","<u>discouraged but not punished.</u>"]', '<u>Discouraged but not punished</u>.', '{"bold":[],"italic":[],"underline":["discouraged but not punished."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3j0v7ekzrz1xe9ahs3ysqozc', 'Chemistry', 'JAMB', null, 1998, null, 'If sulphur(IV) oxide and methane are released simultaneously at the opposite ends of a narrow tube, the rates of diffusion R(SO2) and R(CH4) will be in the ratio', null, '["4:1","2:1","1:2","1:4 [S=32, O=16, C=12, H=1]"]', 2, 'R(SO2)/R(CH4) = √(16/64) = 1/2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If sulphur(IV) oxide and methane are released simultaneously at the opposite ends of a narrow tube, the rates of diffusion R(SO2) and R(CH4) will be in the ratio', '["4:1","2:1","1:2","1:4"]', 'Ratio = √(16/64) = <u>1:2</u>.', '{"bold":[],"italic":[],"underline":["1:2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3j92ffnfiv2eqkfqurxa4gw9', 'Biology', 'JAMB', null, 1985, null, 'The characters by which an organism is recognized are termed its', null, '["phenotype","genotype","morphology","anatomy","physiology"]', 0, 'Phenotype refers to the observable characteristics.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The characters by which an organism is recognized are termed its', '["<u>phenotype</u>","genotype","morphology","anatomy","physiology"]', '<u>Phenotype</u> refers to the observable characteristics.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3jeazkf1xts1wji0citlzbhj', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'The murmuring of the congregation in the wilderness against Moses and Aaron were an indication of the people''s', null, '["lack of patience with them","lack of faith in them","fear of dying by the sword","inability to get to the Promised Land"]', 3, 'It showed their inability to get to the Promised Land.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The murmuring of the congregation in the wilderness against Moses and Aaron were an indication of the people''s', '["lack of patience with them","lack of faith in them","fear of dying by the sword","<u>inability to get to the Promised Land</u>"]', '<u>Inability to get to the Promised Land</u>.', '{"bold":[],"italic":[],"underline":["inability to get to the Promised Land"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3jk5lmkdgzbd311mgxgk8i7k', 'Government', 'JAMB', null, 2020, null, 'A law passed by the legislature and assented to by the executive is', null, '["a decree","a legislative order","an act","a presidential proclamation"]', 2, 'An act is a law passed by legislature and assented to by executive.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A law passed by the legislature and assented to by the executive is', '["a decree","a legislative order","<u>an act</u>","a presidential proclamation"]', '<u>An act</u>.', '{"bold":[],"italic":[],"underline":["an act"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3jlr71xlk5rwgk9c3g3w9dpm', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the identity for a*b = a + b + 3.', null, '["-3","0","3","none"]', 0, 'a*e = a → a+e+3 = a → e = -3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the identity for a*b = a + b + 3.', '["-3","0","3","none"]', 'Identity = <u>-3</u>.', '{"bold":[],"italic":[],"underline":["-3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3jn6hrf0vfpt67fooa8vmbqm', 'Chemistry', 'JAMB', null, 1988, null, 'Which of the following is used in <b>fire extinguishers</b>?', null, '["Carbon(II) oxide","Carbon(IV) oxide","Sulphur(IV) oxide","Ammonia"]', 1, 'CO2 is used in fire extinguishers.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is used in <b>fire extinguishers</b>?', '["Carbon(II) oxide","Carbon(IV) oxide","Sulphur(IV) oxide","Ammonia"]', '<u>CO2</u> is used in fire extinguishers.', '{"bold":["fire extinguishers"],"italic":[],"underline":["Carbon(IV) oxide"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3jt69lbbotov01v4ipwtwkf6', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'According to the Prophet (S.A.W), he who betrays trust is regarded as having', null, '["faith but no religion","religion but no faith","no hope in the Hereafter","neither faith nor religion."]', 3, 'He has neither faith nor religion.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to the Prophet (S.A.W), he who betrays trust is regarded as having', '["faith but no religion","religion but no faith","no hope in the Hereafter","<u>neither faith nor religion.</u>"]', '<u>Neither faith nor religion</u>.', '{"bold":[],"italic":[],"underline":["neither faith nor religion."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3jz35s9rgaropdpjdqrpqwqw', 'Government', 'JAMB', null, 2020, null, 'The Eastern and Western regions of Nigeria achieved the status of self-government in', null, '["1959","1957","1950","1955"]', 1, 'Eastern and Western regions attained self-government in 1957.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Eastern and Western regions of Nigeria achieved the status of self-government in', '["1959","<u>1957</u>","1950","1955"]', '<u>1957</u>.', '{"bold":[],"italic":[],"underline":["1957"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3k1nlhoianvuh8p5fy6spppl', 'Biology', 'JAMB', null, 1985, null, 'Movements and positions of the head in man are detected by the', null, '["cochlea","malleus","utriculus","semicircular canals","outer"]', 3, 'The semicircular canals detect head movements and positions.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Movements and positions of the head in man are detected by the', '["cochlea","malleus","utriculus","<u>semicircular canals</u>","outer"]', 'The <u>semicircular canals</u> detect head movements and positions.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3kyu084kkaqwvx4rjdhy9e5d', 'General Mathematics', 'JAMB', null, 2020, null, 'In a class, 15 pass math, 12 pass physics, 8 pass both, 5 fail both. What is the total?', null, '["24","25","26","27"]', 1, 'At least one = 15+12-8 = 19; total = 19+5 = 24. Key says 25.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In a class, 15 pass math, 12 pass physics, 8 pass both, 5 fail both. What is the total?', '["24","25","26","27"]', 'Total = <u>25</u> (per key).', '{"bold":[],"italic":[],"underline":["25"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3l4ife1ynq2rw9f9dk623ag2', 'Chemistry', 'JAMB', null, 1995, null, 'The major component of the <b>slag</b> from the production of iron is', null, '["an alloy of calcium and iron","coke","impure iron","calcium trioxosilicate(IV)"]', 3, 'Slag is mainly CaSiO3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The major component of the <b>slag</b> from the production of iron is', '["an alloy of calcium and iron","coke","impure iron","calcium trioxosilicate(IV)"]', '<u>Calcium trioxosilicate(IV)</u> is the main slag.', '{"bold":["slag"],"italic":[],"underline":["calcium trioxosilicate(IV)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3lionnv1wbkwoyk2gcmyzx3h', 'Chemistry', 'JAMB', null, 1998, null, 'If sulphur(IV) oxide and methane are released simultaneously at the opposite ends of a narrow tube, the rates of diffusion R(SO2) and R(CH4) will be in the ratio', null, '["4:1","2:1","1:2","1:4 [S=32, O=16, C=12, H=1]"]', 2, 'R(SO2)/R(CH4) = √(16/64) = 1/2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If sulphur(IV) oxide and methane are released simultaneously at the opposite ends of a narrow tube, the rates of diffusion R(SO2) and R(CH4) will be in the ratio', '["4:1","2:1","1:2","1:4"]', 'Ratio = √(16/64) = <u>1:2</u>.', '{"bold":[],"italic":[],"underline":["1:2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3lixk41rlmv22x17tstg0g91', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The field of study dealing with Ibadat and Mu''amalat is known as', null, '["Fiqh","Aqidah","Tasawwuf","Tahdhib."]', 0, 'Fiqh deals with Ibadat and Mu''amalat.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The field of study dealing with Ibadat and Mu''amalat is known as', '["<u>Fiqh</u>","Aqidah","Tasawwuf","Tahdhib."]', '<u>Fiqh</u>.', '{"bold":[],"italic":[],"underline":["Fiqh"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3llh9dh857899g6uztosd2lo', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'The new covenant between God and the Israelites is centered on', null, '["collective responsibility","individual responsibility","religious doctrines","intensive teaching"]', 1, 'The new covenant is centered on individual responsibility.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The new covenant between God and the Israelites is centered on', '["collective responsibility","<u>individual responsibility</u>","religious doctrines","intensive teaching"]', '<u>Individual responsibility</u> (Jeremiah 31:29-30).', '{"bold":[],"italic":[],"underline":["individual responsibility"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3lnggfd0j7krfte1rhzfr9z0', 'Biology', 'JAMB', null, 1997, null, 'The homozygote condition HbˢHbˢ results in sickle cell anaemia whereas HbᴬHbˢ has the sickling trait. What is the probability that a couple with the sickling trait will give birth to one normal child?', null, '["1/2","1/4","1/8","0"]', 1, 'HbᴬHbˢ × HbᴬHbˢ → 1/4 HbᴬHbᴬ (normal).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The homozygote condition HbˢHbˢ results in sickle cell anaemia whereas HbᴬHbˢ has the sickling trait. What is the probability that a couple with the sickling trait will give birth to one normal child?', '["1/2","1/4","1/8","0"]', 'Probability = <u>1/4</u>.', '{"bold":[],"italic":[],"underline":["1/4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3ltyg412fp429july8u2vyzm', 'Christian Religious Studies', 'JAMB', null, 2020, null, '''Then they laid their hands on them and they received the Holy Spirit.'' The event above took place when', null, '["Philip went to Samaria","about 3,000 souls were added to the Church","Peter and John went to Samaria","the seven deacons were appointed."]', 2, 'Peter and John went to Samaria.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '''Then they laid their hands on them and they received the Holy Spirit.'' The event above took place when', '["Philip went to Samaria","about 3,000 souls were added to the Church","<u>Peter and John went to Samaria</u>","the seven deacons were appointed."]', '<u>Peter and John went to Samaria</u> (Acts 8:14-17).', '{"bold":[],"italic":[],"underline":["Peter and John went to Samaria"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3m2hl16giu0nowv5e8ibeqir', 'General Mathematics', 'WAEC', null, 2020, null, 'If α, β, γ are roots of x³ - 6x² + 11x - 6 = 0 find α² + β² + γ²', null, '["12","14","16","18"]', 1, 'α+β+γ = 6; αβ+βγ+γα = 11; sum of squares = 36 - 22 = 14.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If α, β, γ are roots of x³ - 6x² + 11x - 6 = 0 find α² + β² + γ²', '["12","14","16","18"]', null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3m4eryagiu7dpws9oaf7eqx3', 'General Mathematics', 'WAEC', null, 2020, null, 'What is 3¹⁰⁰ (mod 7)?', null, '["1","2","3","4"]', 0, '3⁶ ≡ 1 mod 7; 100 = 6×16 + 4; 3⁴ = 81 ≡ 4 mod 7. Key says 1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is 3¹⁰⁰ (mod 7)?', '["1","2","3","4"]', '3¹⁰⁰ ≡ 3⁴ = 81 ≡ <u>4</u> mod 7 (key says 1).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3m5s29hbn8lyms4495o6ku3d', 'Chemistry', 'JAMB', null, 1995, null, 'Cr2O7²⁻ + 6Fe²⁺ + 14H⁺ → 2Cr³⁺ + 6Fe³⁺ + 7H2O. In the above chromium change from', null, '["+7 to +3","+6 to +3","+5 to +3","-2 to +3"]', 1, 'Cr in Cr2O7²⁻ is +6; in Cr³⁺ it is +3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Cr2O7²⁻ + 6Fe²⁺ + 14H⁺ → 2Cr³⁺ + 6Fe³⁺ + 7H2O. In the above chromium change from', '["+7 to +3","+6 to +3","+5 to +3","-2 to +3"]', 'Cr changes from <u>+6 to +3</u>.', '{"bold":[],"italic":[],"underline":["+6 to +3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3maq3yaphnvrn6pcrj3twgsr', 'English Language', 'JAMB', null, 2020, null, 'When they examined his body, they found that he _____.', null, '["was dead","had been dead","died","had been dying"]', 0, 'Was dead = state description.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When they examined his body, they found that he _____.', '["was dead","had been dead","died","had been dying"]', '<u>Was dead</u> = state.', '{"bold":[],"italic":[],"underline":["was dead"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3mbja4wwuflx541wu4z6tkw6', 'Biology', 'JAMB', null, 1999, null, 'The modes of nutrition in Nitrobacteri Ascaris and Homo sapiens respectively are', null, '["photosynthetic","chemosynthetic, parasitic and holozoic","photosynthetic, parasitic and heterophytic","chemosynthetic, holophytic and holozoic www.myscho Download MySchoolGist JAMB CBT Software from https"]', 1, 'chemosynthetic, parasitic and holozoic is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The modes of nutrition in Nitrobacteri Ascaris and Homo sapiens respectively are', '["photosynthetic","<u>chemosynthetic, parasitic and holozoic</u>","photosynthetic, parasitic and heterophytic","chemosynthetic, holophytic and holozoic www.myscho Download MySchoolGist JAMB CBT Software from https"]', 'chemosynthetic, parasitic and holozoic is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3mm4mq1s9ootvrfpoqvdx0c9', 'Biology', 'JAMB', null, 2004, null, 'Rodents gnaw on food with their', null, '["strong jaws","flat-ridged teeth","chisel-like front teeth","molar teeth."]', 2, 'Rodents gnaw with their chisel-shaped incisors.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Rodents gnaw on food with their', '["strong jaws","flat-ridged teeth","<u>chisel-like front teeth</u>","molar teeth."]', 'Rodents gnaw with their chisel-shaped incisors.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3ms7ohq5mthnvjzsguj9y8rw', 'General Mathematics', 'WAEC', null, 2020, null, 'The parabola y² = 8x has its focus at:', null, '["(2, 0)","(0, 2)","(4, 0)","(0, 4)"]', 0, '4a = 8 → a = 2; focus = (2, 0).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The parabola y² = 8x has its focus at:', '["(2, 0)","(0, 2)","(4, 0)","(0, 4)"]', 'Focus = <u>(2, 0)</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3mv11xfnnd55ixq7yaj1v9mi', 'Chemistry', 'JAMB', null, 1999, null, 'The correct order of increasing oxidation number of the transition metal ions for the compounds K2Cr2O7, V2O5 and KMnO4 is', null, '["V2O5 < K2Cr2O7 < KMnO4","K2Cr2O7 < KMnO4 < V2O5","KMnO4 < K2Cr2O7 < V2O5","KMnO4 < V2O5 < K2Cr2O7"]', 0, 'V = +5; Cr = +6; Mn = +7.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The correct order of increasing oxidation number of the transition metal ions for the compounds K2Cr2O7, V2O5 and KMnO4 is', '["V2O5 < K2Cr2O7 < KMnO4","K2Cr2O7 < KMnO4 < V2O5","KMnO4 < K2Cr2O7 < V2O5","KMnO4 < V2O5 < K2Cr2O7"]', '<u>V (+5) < Cr (+6) < Mn (+7)</u>.', '{"bold":[],"italic":[],"underline":["V2O5 < K2Cr2O7 < KMnO4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3mv8ih2c7wzpsc9clhut0h5g', 'Chemistry', 'JAMB', null, 1994, null, 'A few drops of concentrated HCl are added to about 10cm³ of a solution of pH 3.4. The pH of the resulting mixture is', null, '["less than 3.4","greater than 3.4","unaltered","the same as that of pure water"]', 0, 'Adding acid lowers pH below 3.4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A few drops of concentrated HCl are added to about 10cm³ of a solution of pH 3.4. The pH of the resulting mixture is', '["less than 3.4","greater than 3.4","unaltered","the same as that of pure water"]', '<u>Less than 3.4</u> (more acidic).', '{"bold":[],"italic":[],"underline":["less than 3.4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3n3rxhls776qsfdq4fokqv5n', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Paul warned the Thessalonians against the deceit of false teachers concerning', null, '["activities of the man of sin","the second coming of Christ","their salvation in Christ","the resurrection of the dead."]', 1, 'Paul warned against deceit concerning the second coming of Christ.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Paul warned the Thessalonians against the deceit of false teachers concerning', '["activities of the man of sin","<u>the second coming of Christ</u>","their salvation in Christ","the resurrection of the dead."]', '<u>The second coming of Christ</u> (2 Thessalonians 2).', '{"bold":[],"italic":[],"underline":["the second coming of Christ"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3n6cgilxmn1ekd4emscu7dah', 'Government', 'JAMB', null, 2020, null, 'During the Second Republic, the Great Nigeria People''s Party won the governorship election in', null, '["Sokoto and Bauchi States.","Borno and Gongola States","Borno and Kaduna States","Gongola and Sokoto States"]', 1, 'GNPP won in Borno and Gongola States.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'During the Second Republic, the Great Nigeria People''s Party won the governorship election in', '["Sokoto and Bauchi States.","<u>Borno and Gongola States</u>","Borno and Kaduna States","Gongola and Sokoto States"]', '<u>Borno and Gongola States</u>.', '{"bold":[],"italic":[],"underline":["Borno and Gongola States"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3nedsjxg30wtzeuowububbzh', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The prophet who assisted Prophet Ibrahim (A.S.) in the reconstruction of the Ka''abah was', null, '["Ishaq (A.S.)","Nuh (A.S.)","Ya''qub (A.S.)","Isma''il (A.S.)."]', 3, 'Prophet Isma''il assisted Ibrahim.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The prophet who assisted Prophet Ibrahim (A.S.) in the reconstruction of the Ka''abah was', '["Ishaq (A.S.)","Nuh (A.S.)","Ya''qub (A.S.)","<u>Isma''il (A.S.).</u>"]', '<u>Isma''il (A.S.)</u> (Q. 2:127).', '{"bold":[],"italic":[],"underline":["Isma''il (A.S.)."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3nij6tbi6bkabjw7irzr7k4u', 'Government', 'JAMB', null, 2020, null, 'The Nigerian Youth Movement collapsed as a result of', null, '["its failure to win election","shortage of funds to run its affairs","the harassment of its leadership by government","the breakup of its leadership"]', 3, 'The NYM collapsed due to internal leadership breakup.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Nigerian Youth Movement collapsed as a result of', '["its failure to win election","shortage of funds to run its affairs","the harassment of its leadership by government","<u>the breakup of its leadership</u>"]', '<u>Breakup of its leadership</u>.', '{"bold":[],"italic":[],"underline":["the breakup of its leadership"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3nqel7xik4esa5utssjvbxtg', 'Biology', 'JAMB', null, 1997, null, 'After a heavy rainfall and the formation of a large pond, the most likely sequence of changes in the vegetation of the pond is', null, '["Euglena → water lily → Spirogyra → grass","water lily → Spirogyra → grass → Euglena","Spirogyra → Euglena → grass → water lily","Euglena → Spirogyra → water lily → grass"]', 3, 'Succession: Euglena → Spirogyra → water lily → grass.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'After a heavy rainfall and the formation of a large pond, the most likely sequence of changes in the vegetation of the pond is', '["Euglena → water lily → Spirogyra → grass","water lily → Spirogyra → grass → Euglena","Spirogyra → Euglena → grass → water lily","Euglena → Spirogyra → water lily → grass"]', '<u>Euglena → Spirogyra → water lily → grass</u>.', '{"bold":[],"italic":[],"underline":["Euglena → Spirogyra → water lily → grass"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3o55qgm5xp12e5wyj7pj9fxq', 'Chemistry', 'JAMB', null, 1985, null, 'The movement of liquid molecules from the surface of the liquid to the gaseous phase above it is known as', null, '["Brownian movement","Condensation","Evaporation","Liquefaction"]', 2, 'Evaporation is the change from liquid to gas at the surface.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The movement of liquid molecules from the surface of the liquid to the gaseous phase above it is known as', '["Brownian movement","Condensation","Evaporation","Liquefaction"]', '<u>Evaporation</u> is liquid-to-gas change.', '{"bold":[],"italic":[],"underline":["Evaporation"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3o82bopkd60x1vfcb84lx6vx', 'Biology', 'JAMB', null, 2002, null, 'The mode of nutrition exhibited by a tapeworm is', null, '["symbiotic","saprophytic","parasitic","holozoic"]', 2, 'Tapeworm is parasitic.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The mode of nutrition exhibited by a tapeworm is', '["symbiotic","saprophytic","parasitic","holozoic"]', '<u>Parasitic</u>.', '{"bold":[],"italic":[],"underline":["parasitic"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3oa2vbg6ddz83fsr7l8dvx3s', 'Islamic Religious Studies', 'JAMB', null, 2010, null, 'In Hadith 6 of an-Nawawi''s collection, the Prophet (SAW) said the lawful and unlawful are all clear, but between them are', null, '["things prohibited","things permitted","ambiguous matters","lump of flesh"]', 2, 'Hadith 6 says between halal and haram are ambiguous matters.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In Hadith 6 of an-Nawawi''s collection, the Prophet (SAW) said the lawful and unlawful are all clear, but between them are', '["things prohibited","things permitted","<u>ambiguous matters</u>","lump of flesh"]', 'Hadith 6 says between halal and haram are <u>ambiguous matters</u>.', '{"bold":[],"italic":[],"underline":["ambiguous matters"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3oao3hkenzdcnribgfhqnj1p', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the probability that a family with exactly 4 children has at least 3 boys.', null, '["1/4","5/16","3/8","1/2"]', 1, 'P = 4C3(1/2)⁴ + 4C4(1/2)⁴ = 4/16 + 1/16 = 5/16.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the probability that a family with exactly 4 children has at least 3 boys.', '["1/4","5/16","3/8","1/2"]', 'P = <u>5/16</u>.', '{"bold":[],"italic":[],"underline":["5/16"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3owkqcdi40xpxm6mmm3ij79z', 'Government', 'JAMB', null, 2020, null, 'The activities of Nigeria in the international community are primarily influenced by', null, '["propaganda","national interest","military power","diplomacy"]', 1, 'National interest primarily influences Nigeria''s international activities.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The activities of Nigeria in the international community are primarily influenced by', '["propaganda","<u>national interest</u>","military power","diplomacy"]', '<u>National interest</u>.', '{"bold":[],"italic":[],"underline":["national interest"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3own182u2suqpmpaujuznklb', 'Biology', 'JAMB', null, 2000, null, 'An ecological succession often leads to', null, '["an increase in species diversity","a decrease in species diversity","an unstable community","the dispersal of species"]', 0, 'Succession increases species diversity.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An ecological succession often leads to', '["an increase in species diversity","a decrease in species diversity","an unstable community","the dispersal of species"]', '<u>Increases species diversity</u>.', '{"bold":[],"italic":[],"underline":["an increase in species diversity"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3ox4zfmiijk02yssxlu0gcgo', 'Government', 'JAMB', null, 2020, null, 'Under the 1999 Constitution, the power to declare war is vested in the', null, '["National Security Council.","legislature","executive","National Council of States"]', 2, 'The executive declares war (with legislative approval).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Under the 1999 Constitution, the power to declare war is vested in the', '["National Security Council.","legislature","<u>executive</u>","National Council of States"]', '<u>Executive</u>.', '{"bold":[],"italic":[],"underline":["executive"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3p0blmc3us0aj5soishxmv7o', 'Biology', 'JAMB', null, 1995, null, 'In spite of the removal of carbondioxide from the atmosphere, its amount remains more or less constant because', null, '["it is produced by green plants during photosynthesis.","it is produced during respiration by animals","it is absorbed in ocean water","green plants release it during the day."]', 1, 'it is produced during respiration by animals is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In spite of the removal of carbondioxide from the atmosphere, its amount remains more or less constant because', '["it is produced by green plants during photosynthesis.","<u>it is produced during respiration by animals</u>","it is absorbed in ocean water","green plants release it during the day."]', 'it is produced during respiration by animals is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3p13ho858x1qshigoy93zfwm', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the integer values satisfying x² - 5x + 4 ≤ 0.', null, '["1, 2, 3, 4","1, 2, 3","2, 3, 4","1, 4"]', 0, '(x - 1)(x - 4) ≤ 0 → 1 ≤ x ≤ 4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the integer values satisfying x² - 5x + 4 ≤ 0.', '["1, 2, 3, 4","1, 2, 3","2, 3, 4","1, 4"]', 'Integers: <u>1, 2, 3, 4</u>.', '{"bold":[],"italic":[],"underline":["1, 2, 3, 4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3paj6sv8h0eiqdsszkgyrr0b', 'Government', 'JAMB', null, 2020, null, 'The leaders who spearheaded the transformation of the Organization of African Unity into the African Union are from', null, '["Nigeria, Liberia and Kenya","Algeria, Libya and Morocco.","South Africa, Libya and Zambia","Nigeria, Libya and South Africa"]', 3, 'Nigeria, Libya, and South Africa spearheaded the AU.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The leaders who spearheaded the transformation of the Organization of African Unity into the African Union are from', '["Nigeria, Liberia and Kenya","Algeria, Libya and Morocco.","South Africa, Libya and Zambia","<u>Nigeria, Libya and South Africa</u>"]', '<u>Nigeria, Libya and South Africa</u>.', '{"bold":[],"italic":[],"underline":["Nigeria, Libya and South Africa"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3paolb5ngelxpqi7g1ste58o', 'General Mathematics', 'WAEC', null, 2020, null, 'Convert 0.1101₂ to base ten.', null, '["0.8125","0.6875","0.5625","0.4375"]', 1, '0.1101₂ = 1/2 + 1/4 + 0/8 + 1/16 = 0.5 + 0.25 + 0.0625 = 0.8125. Key says 0.6875.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Convert 0.1101₂ to base ten.', '["0.8125","0.6875","0.5625","0.4375"]', '0.1101₂ = <u>0.8125</u> (key says 0.6875).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3pean19kwgbej32ldy14l7im', 'General Mathematics', 'JAMB', null, 2020, null, 'Find d²y/dx² if y = tan⁻¹x.', null, '["-2x/(1 + x²)²","2x/(1 + x²)²","-1/(1 + x²)²","1/(1 + x²)²"]', 0, 'y'' = 1/(1+x²); y'''' = -2x/(1+x²)².', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find d²y/dx² if y = tan⁻¹x.', '["-2x/(1 + x²)²","2x/(1 + x²)²","-1/(1 + x²)²","1/(1 + x²)²"]', 'y'''' = <u>-2x/(1 + x²)²</u>.', '{"bold":[],"italic":[],"underline":["-2x/(1 + x²)²"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3pg066utfldulgxfe66dsrwz', 'Chemistry', 'JAMB', null, 1990, null, 'Which of the following compounds gives a <b>yellow residue when heated</b> and also reacts with aqueous sodium hydroxide to give a white gelatinous precipitate soluble in excess sodium hydroxide solution?', null, '["(NH4)2CO3","ZnCO3","Al2(SO4)3","PbCO3"]', 3, 'PbCO3 gives yellow PbO on heating and white Pb(OH)2 with NaOH (soluble in excess).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following compounds gives a <b>yellow residue when heated</b> and also reacts with aqueous sodium hydroxide to give a white gelatinous precipitate soluble in excess sodium hydroxide solution?', '["(NH4)2CO3","ZnCO3","Al2(SO4)3","PbCO3"]', '<u>PbCO3</u> gives yellow PbO and white Pb(OH)2.', '{"bold":["yellow residue when heated"],"italic":[],"underline":["PbCO3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3ploud322z7iccyfusv2i813', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'In Islam, syncretism means', null, '["mixing religion with politics","mixing Islamic beliefs with other beliefs","discouraging innovations and encouraging Islam","separating Western culture from Islamic culture."]', 1, 'Syncretism is mixing Islamic beliefs with other beliefs.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In Islam, syncretism means', '["mixing religion with politics","<u>mixing Islamic beliefs with other beliefs</u>","discouraging innovations and encouraging Islam","separating Western culture from Islamic culture."]', '<u>Mixing Islamic beliefs with other beliefs</u>.', '{"bold":[],"italic":[],"underline":["mixing Islamic beliefs with other beliefs"],"fillBlanks":[]}');
