insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3puasvm523w9tepg5r9ycdy8', 'Chemistry', 'JAMB', null, 1995, null, 'What is the concentration of H⁺ ions in moles per dm³ of a solution of pH 4.398?', null, '["4.0×10⁻⁵","0.4×10⁻⁵","4.0×10⁻³","0.4×10⁻³"]', 0, '[H⁺] = 10⁻⁴·³⁹⁸ = 4.0×10⁻⁵.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is the concentration of H⁺ ions in moles per dm³ of a solution of pH 4.398?', '["4.0×10⁻⁵","0.4×10⁻⁵","4.0×10⁻³","0.4×10⁻³"]', '[H⁺] = <u>4.0×10⁻⁵ mol/dm³</u>.', '{"bold":[],"italic":[],"underline":["4.0×10⁻⁵"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3pumnku2c5vymxayyshduvpm', 'Islamic Religious Studies', 'JAMB', null, 2003, null, 'Allah swears by the <b>Fig</b> and the <b>Olive</b> in Surah', null, '["al-Zilzal","at-Tin","al-Qadr","al-Alaq"]', 1, 'Q.95:1 says "By the fig and the olive."', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Allah swears by the <b>Fig</b> and the <b>Olive</b> in Surah', '["al-Zilzal","<u>at-Tin</u>","al-Qadr","al-Alaq"]', 'Q.95:1 says "By the <u>fig and the olive</u>."', '{"bold":["Fig","Olive"],"italic":[],"underline":["at-Tin"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3pvqpwz3cvh2pct5t1vwkb1p', 'Biology', 'JAMB', null, 2000, null, 'A characteristic of vertebrates that is unique to mammals is', null, '["the presence of pentadactyl limbs","parental care","the possession of scrotum","pulmonary circulation"]', 2, 'Scrotum is unique to mammals.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A characteristic of vertebrates that is unique to mammals is', '["the presence of pentadactyl limbs","parental care","the possession of scrotum","pulmonary circulation"]', '<u>Scrotum is unique to mammals</u>.', '{"bold":[],"italic":[],"underline":["the possession of scrotum"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3pzbjr7hmjt5bkgxoy8shgx2', 'Biology', 'JAMB', null, 2001, null, 'The mode of feeding in Amoeba and Hydra is', null, '["heterotrophic","holophytic","autotrophic","symbiotic"]', 0, 'heterotrophic is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The mode of feeding in Amoeba and Hydra is', '["<u>heterotrophic</u>","holophytic","autotrophic","symbiotic"]', 'heterotrophic is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3pzjm9wf7k93gkgmxpigwstc', 'Biology', 'JAMB', null, 1983, null, 'Starting from the skull end, the vertebrae are arranged in the following order:', null, '["axis, atlas, cervical, thoracic and lumbar","atlas, cervical, axis, thoracic and lumbar","atlas, axis, thoracic, cervical and lumbar","atlas, axis, cervical, thoracic and lumbar","atlas, thoracic, cervical axis and lumbar"]', 3, 'The correct order is atlas → axis → cervical → thoracic → lumbar.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Starting from the skull end, the vertebrae are arranged in the following order:', '["axis, atlas, cervical, thoracic and lumbar","atlas, cervical, axis, thoracic and lumbar","atlas, axis, thoracic, cervical and lumbar","<u>atlas, axis, cervical, thoracic and lumbar</u>","atlas, thoracic, cervical axis and lumbar"]', 'The correct order is <u>atlas → axis → cervical → thoracic → lumbar</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3pznh0gi4b8ygfsaneib22xo', 'Chemistry', 'JAMB', null, 1994, null, 'One mole of a hydrocarbon contains 48g of carbon. If its vapour density is 28, the hydrocarbon is', null, '["an alkane","an alkene","an alkyne","aromatic"]', 1, 'Mr = 56; C = 4 (48g), H = 8 → C4H8 (alkene).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One mole of a hydrocarbon contains 48g of carbon. If its vapour density is 28, the hydrocarbon is', '["an alkane","an alkene","an alkyne","aromatic"]', '<u>C4H8 (alkene)</u>.', '{"bold":[],"italic":[],"underline":["an alkene"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3q2n8mqswgh78i1f9uk8bgd1', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Paul teaches that those who have been baptized into Christ have been baptized into His', null, '["kingdom","service","death","suffering"]', 2, 'They were baptized into His death.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Paul teaches that those who have been baptized into Christ have been baptized into His', '["kingdom","service","<u>death</u>","suffering"]', '<u>Death</u> (Romans 6:3).', '{"bold":[],"italic":[],"underline":["death"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3q8m4pem3x2p2kapg2p9yr81', 'English Language', 'JAMB', null, 2020, null, 'Raffle draws like gambling often end in a _____ for me.', null, '["lost","lose","loose","loss"]', 3, 'Loss = noun after "a".', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Raffle draws like gambling often end in a _____ for me.', '["lost","lose","loose","loss"]', '<u>Loss</u> = noun.', '{"bold":[],"italic":[],"underline":["loss"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3q8p88byfbp8coiw41cug4k6', 'Islamic Religious Studies', 'JAMB', null, 2011, null, 'The only Surah in the Glorious Qur''an which must be recited in every obligatory prayer is', null, '["al-Baqarah","al-Alaq","al-Fatihah","al-Ikhlas"]', 2, 'Al-Fatihah must be recited in every rak''ah of prayer.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The only Surah in the Glorious Qur''an which must be recited in every obligatory prayer is', '["al-Baqarah","al-Alaq","<u>al-Fatihah</u>","al-Ikhlas"]', '<u>Al-Fatihah</u> must be recited in every rak''ah of prayer.', '{"bold":[],"italic":[],"underline":["al-Fatihah"],"fillBlanks":[]}');
