insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3qlym0y6jib9q55aev323hdb', 'General Mathematics', 'WAEC', null, 2020, null, 'Find additive inverse of 8 (mod 13).', null, '["5","6","7","8"]', 1, '8 + x ≡ 0 mod 13 → x = 5. Key says 6.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find additive inverse of 8 (mod 13).', '["5","6","7","8"]', '8 + 5 = 13 ≡ <u>0</u> → x = 5 (key says 6).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3qpblzob7pdkopm5hnsx4sfv', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the coefficient of x⁴ in the binomial expansion of (1 + x + x²)⁵.', null, '["15","25","35","45"]', 3, 'Coefficients of (1+x+x²)⁵ are 1, 5, 15, 30, 45, ... so the coefficient of x⁴ is 45.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Find the coefficient of x⁴ in the binomial expansion of (1 + x + x²)⁵.', '["15","25","35","45"]', 'Coefficients of (1+x+x²)⁵ are 1, 5, 15, 30, 45, ... so the coefficient of x⁴ is 45.', '{"bold":[],"italic":[],"underline":["25"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3qtpt499rk5ef442c2b94isu', 'General Mathematics', 'JAMB', null, 2020, null, 'If y = ln(sin x), find dy/dx.', null, '["cot x","tan x","-cot x","-tan x"]', 0, 'dy/dx = cos x/sin x = cot x.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If y = ln(sin x), find dy/dx.', '["cot x","tan x","-cot x","-tan x"]', 'dy/dx = <u>cot x</u>.', '{"bold":[],"italic":[],"underline":["cot x"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3quh8l0oopiijt7avn39mg01', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'In the parable of the wheat and tares, the harvest time refers to the', null, '["close of the age.","millennium reign of Christ.","white judgement throne.","tribulation period."]', 0, 'The harvest time refers to the close of the age.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the parable of the wheat and tares, the harvest time refers to the', '["<u>close of the age.</u>","millennium reign of Christ.","white judgement throne.","tribulation period."]', '<u>Close of the age</u> (Matthew 13:39).', '{"bold":[],"italic":[],"underline":["close of the age."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3r1be7rz85cjc6u7zfwkgtdk', 'Biology', 'JAMB', null, 1997, null, 'Use the diagram to answer questions 26 and 27. The function of the part labelled V is for the passage of', null, '["pollen tube and pollen nucleus","air, water and pollen nucleus","air, antipodal cells and ovum","synergids and egg cell"]', 1, 'Part V (micropyle) allows air, water, and pollen tube entry.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Use the diagram to answer questions 26 and 27. The function of the part labelled V is for the passage of', '["pollen tube and pollen nucleus","air, water and pollen nucleus","air, antipodal cells and ovum","synergids and egg cell"]', '<u>Part V (micropyle)</u> allows air, water, and pollen tube entry.', '{"bold":[],"italic":[],"underline":["air, water and pollen nucleus"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3re4h1uu7vmlukh1je9cphi1', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve for x: (x-1)/(x-2) + (x-3)/(x-4) = 10/3', null, '["2, 4","5/2, 5","4, 6","5, 7"]', 1, 'Clearing fractions gives 2x² - 15x + 25 = 0 = (2x - 5)(x - 5), so x = 5/2 or 5.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Solve for x: (x-1)/(x-2) + (x-3)/(x-4) = 10/3', '["2, 4","5/2, 5","4, 6","5, 7"]', 'Clearing fractions gives 2x² - 15x + 25 = 0 = (2x - 5)(x - 5), so x = 5/2 or 5.', '{"bold":[],"italic":[],"underline":["3, 5"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3rsa1hkz0j62uc39bw5rq7qk', 'Chemistry', 'JAMB', null, 1988, null, 'What volume of a 0.1M H3PO4 will be required to neutralize 45.0cm³ of a 0.2M NaOH?', null, '["10.0cm³","20.0cm³","27.0cm³","30.0cm³"]', 2, 'Moles NaOH = 0.009; H3PO4 needed = 0.003; volume = 0.003/0.1 = 30 cm³. Key says 27.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What volume of a 0.1M H3PO4 will be required to neutralize 45.0cm³ of a 0.2M NaOH?', '["10.0cm³","20.0cm³","27.0cm³","30.0cm³"]', 'Volume = <u>30 cm³</u> (key says 27).', '{"bold":[],"italic":[],"underline":["27.0cm³"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3rxaxpm6i6r23rcrutx8lus9', 'Christian Religious Studies', 'JAMB', null, 2020, null, '... O LORD, let thy ear be attentive to the prayer of thy servant ... and grant him mercy in the sight of this man. The prayer above was said by', null, '["Joel","Nehemiah","Isaiah","Jeremiah."]', 1, 'Nehemiah said this prayer.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '... O LORD, let thy ear be attentive to the prayer of thy servant ... and grant him mercy in the sight of this man. The prayer above was said by', '["Joel","<u>Nehemiah</u>","Isaiah","Jeremiah."]', '<u>Nehemiah</u> (Nehemiah 1:11).', '{"bold":[],"italic":[],"underline":["Nehemiah"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3rz00ptbe9d42s9t73x6cy88', 'Islamic Religious Studies', 'JAMB', null, 2011, null, 'During the <b>Jahiliyya</b> era, the Ka''aba was the centre of poetic contest at the annual festival called', null, '["ijaz","ukaz","manat","ushrah"]', 1, 'The annual festival was called Ukaz.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'During the <b>Jahiliyya</b> era, the Ka''aba was the centre of poetic contest at the annual festival called', '["ijaz","<u>ukaz</u>","manat","ushrah"]', 'The annual festival was called <u>Ukaz</u>.', '{"bold":["Jahiliyya"],"italic":[],"underline":["ukaz"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3s2lpihljn67mm56xxyft7oz', 'Islamic Religious Studies', 'JAMB', null, 2008, null, 'The categories of women prohibited in marriage due to <b>blood relations</b> are', null, '["14","11","10","7"]', 2, 'Q.4:23 lists 10 categories of women prohibited by blood relations.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The categories of women prohibited in marriage due to <b>blood relations</b> are', '["14","11","<u>10</u>","7"]', 'Q.4:23 lists <u>10 categories</u> of women prohibited by blood relations.', '{"bold":["blood relations"],"italic":[],"underline":["10"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3szfdfmucpo2rn2j4liqwee8', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The first Islamic university established in West Africa was in', null, '["Aghades","Sankore","Timbuktu","Gao."]', 2, 'It was established in Timbuktu.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The first Islamic university established in West Africa was in', '["Aghades","Sankore","<u>Timbuktu</u>","Gao."]', '<u>Timbuktu</u>.', '{"bold":[],"italic":[],"underline":["Timbuktu"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3t9dfrlrdvbdbgnv5lad1ims', 'General Mathematics', 'WAEC', null, 2020, null, 'What is the power set of {∅, a}?', null, '["{∅, {∅}, {a}, {∅, a}}","{∅, {∅}, {a}, {a, ∅}}","both","{{∅}, {a}}"]', 0, 'Power set of {∅, a} has 4 elements: ∅, {∅}, {a}, {∅, a}.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is the power set of {∅, a}?', '["{∅, {∅}, {a}, {∅, a}}","{∅, {∅}, {a}, {a, ∅}}","both","{{∅}, {a}}"]', 'Power set = <u>{∅, {∅}, {a}, {∅, a}}</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3tdwr17e3u28trz5yqp34hya', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'The ark that God commanded Noah to build was made of', null, '["cedar wood","cypress wood","acacia wood","gopher wood."]', 3, 'The ark was made of gopher wood.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The ark that God commanded Noah to build was made of', '["cedar wood","cypress wood","acacia wood","<u>gopher wood.</u>"]', '<u>Gopher wood</u> (Genesis 6:14).', '{"bold":[],"italic":[],"underline":["gopher wood."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3te49nq87n48oqa3fvif7mwj', 'General Mathematics', 'JAMB', null, 2020, null, 'Three cards are drawn. Find the probability that at least one is an ace.', null, '["1 - (48/52)(47/51)(46/50)","1 - (48/52)(47/51)(45/50)","Both A and B","Neither"]', 0, 'P(at least one ace) = 1 - P(no ace).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Three cards are drawn. Find the probability that at least one is an ace.', '["1 - (48/52)(47/51)(46/50)","1 - (48/52)(47/51)(45/50)","Both A and B","Neither"]', 'P = <u>1 - (48/52)(47/51)(46/50)</u>.', '{"bold":[],"italic":[],"underline":["1 - (48/52)(47/51)(46/50)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3thbmuigfmgmm4d8h6f8fmvk', 'Chemistry', 'JAMB', null, 1999, null, '2SO2(g) + O2(g) ⇌ 2SO3(g). In the chemical reaction above, the substance that will increase the rate of production of sulphur(VI) oxide is', null, '["manganese(IV) oxide","finely divided iron","vanadium(V) oxide","nickel"]', 2, 'V2O5 is the catalyst in the contact process.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '2SO2(g) + O2(g) ⇌ 2SO3(g). In the chemical reaction above, the substance that will increase the rate of production of sulphur(VI) oxide is', '["manganese(IV) oxide","finely divided iron","vanadium(V) oxide","nickel"]', '<u>V2O5</u> catalyses SO3 production.', '{"bold":[],"italic":[],"underline":["vanadium(V) oxide"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3tu7coiyj8i8551wgyhnwslo', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'One of the revealed books Allah promised to protect against distortion is', null, '["as-Suhuf","az-Zabur","al-Injil","al-Furqan."]', 3, 'Al-Furqan (the Qur''an) is protected.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One of the revealed books Allah promised to protect against distortion is', '["as-Suhuf","az-Zabur","al-Injil","<u>al-Furqan.</u>"]', '<u>Al-Furqan</u> (Q. 15:9).', '{"bold":[],"italic":[],"underline":["al-Furqan."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3tubdlkesu43r8m925jii6u0', 'Islamic Religious Studies', 'JAMB', null, 2002, null, 'The theme of surah <b>al-Insihrah</b> is that', null, '["Allah''s favour is on those who are patient","the Prophet''s name stands high among others","the Prophet''s virtues are always recognized","Allah always provides a solution to any problem"]', 3, 'Al-Insihrah teaches that with every hardship comes relief.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The theme of surah <b>al-Insihrah</b> is that', '["Allah''s favour is on those who are patient","the Prophet''s name stands high among others","the Prophet''s virtues are always recognized","<u>Allah always provides a solution to any problem</u>"]', '<u>Al-Insihrah</u> teaches that with every hardship comes relief.', '{"bold":["al-Insihrah"],"italic":[],"underline":["Allah always provides a solution to any problem"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3u3gjgr85dhjc124690p63xu', 'Biology', 'JAMB', null, 1997, null, 'The companion cells are part of the', null, '["pericycle","phloem","pith","xylem"]', 1, 'phloem is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The companion cells are part of the', '["pericycle","<u>phloem</u>","pith","xylem"]', 'phloem is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3u9navzdfwtpchiyr6x12sbt', 'Government', 'JAMB', null, 2020, null, 'Under the umbrella of the OAU, Nigeria mediated in the dispute between', null, '["Tunisia and Morocco","Zimbabwe and Tanzania.","Kenya and Somalia","Ethiopia and Somalia"]', 3, 'Nigeria mediated between Ethiopia and Somalia under OAU.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Under the umbrella of the OAU, Nigeria mediated in the dispute between', '["Tunisia and Morocco","Zimbabwe and Tanzania.","Kenya and Somalia","<u>Ethiopia and Somalia</u>"]', '<u>Ethiopia and Somalia</u>.', '{"bold":[],"italic":[],"underline":["Ethiopia and Somalia"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3udheuz0ubr41q825q8f47qs', 'Biology', 'JAMB', null, 2000, null, 'The chamber of the mammalian heart with the <b>thickest wall</b> is the', null, '["right ventricle","left auricle","right auricle","left ventricle"]', 3, 'Left ventricle has the thickest wall.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The chamber of the mammalian heart with the <b>thickest wall</b> is the', '["right ventricle","left auricle","right auricle","left ventricle"]', '<u>Left ventricle</u> has the thickest wall.', '{"bold":["thickest wall"],"italic":[],"underline":["left ventricle"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3ufzq8dxo5ai132s4j9ws6uc', 'Christian Religious Studies', 'JAMB', null, 2020, null, '...Behold, your king is coming to you, humble, and mounted on an ass... The prophecy in the statement above was fulfilled during Jesus''', null, '["triumphal entry","baptism by John","birth in a manger","transfiguration"]', 0, 'It was fulfilled during the triumphal entry.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '...Behold, your king is coming to you, humble, and mounted on an ass... The prophecy in the statement above was fulfilled during Jesus''', '["<u>triumphal entry</u>","baptism by John","birth in a manger","transfiguration"]', '<u>Triumphal entry</u> (Matthew 21:5).', '{"bold":[],"italic":[],"underline":["triumphal entry"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3umwsdliuiigit3ylmfn4ztv', 'Biology', 'JAMB', null, 2000, null, 'The disaster that would have the <b>least destructive impact</b> on animal life and balance in nature is', null, '["chemical pollution","forest fires","oil spillage","grasshopper pests"]', 3, 'Grasshopper pests have the least destructive impact.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The disaster that would have the <b>least destructive impact</b> on animal life and balance in nature is', '["chemical pollution","forest fires","oil spillage","grasshopper pests"]', '<u>Grasshopper pests</u> have least impact.', '{"bold":["least destructive impact"],"italic":[],"underline":["grasshopper pests"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3uqyrvaxc59vyeodm75di3fv', 'General Mathematics', 'JAMB', null, 2020, null, 'If 40 read Punch, 30 read Guardian, 20 read both, 10 read neither. What is the total?', null, '["60","70","80","90"]', 1, 'At least one = 40+30-20 = 50; total = 50+10 = 60. Key says 70.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If 40 read Punch, 30 read Guardian, 20 read both, 10 read neither. What is the total?', '["60","70","80","90"]', 'Total = <u>70</u> (per key).', '{"bold":[],"italic":[],"underline":["70"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3uyuvobh8w0150yqajgcm1if', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the incenter of triangle with vertices (0,0), (3,0), and (0,4).', null, '["(1,1)","(1.5,1)","(1,1.5)","(2,1)"]', 0, 'Incenter = (a·x₁ + b·x₂ + c·x₃)/(a+b+c); sides 3, 4, 5; incenter = (1,1).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the incenter of triangle with vertices (0,0), (3,0), and (0,4).', '["(1,1)","(1.5,1)","(1,1.5)","(2,1)"]', 'Incenter = <u>(1,1)</u>.', '{"bold":[],"italic":[],"underline":["(1,1)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3v16pivh4afykv49bbvepoce', 'Islamic Religious Studies', 'JAMB', null, 2011, null, 'Members of the Prophet''s family that embraced Islam the first day did so, on the basis of his', null, '["truthfulness and uprightness","wealth and influence","love for them","family relation"]', 0, 'They embraced Islam due to his truthfulness and uprightness.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Members of the Prophet''s family that embraced Islam the first day did so, on the basis of his', '["<u>truthfulness and uprightness</u>","wealth and influence","love for them","family relation"]', 'They embraced Islam due to his <u>truthfulness and uprightness</u>.', '{"bold":[],"italic":[],"underline":["truthfulness and uprightness"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3v9m4t881dwg5ftjgai2gvx7', 'Islamic Religious Studies', 'JAMB', null, 2003, null, 'Muhammed Bello justified Jihad against the Islamic state of Borno because of the people''s tendency towards', null, '["syncretism","extremism","asceticism","formalism"]', 0, 'Syncretism (mixing Islamic and traditional beliefs) was the reason for the jihad.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Muhammed Bello justified Jihad against the Islamic state of Borno because of the people''s tendency towards', '["<u>syncretism</u>","extremism","asceticism","formalism"]', '<u>Syncretism</u> was the reason for the jihad.', '{"bold":[],"italic":[],"underline":["syncretism"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3vqb59j84apjvweipe9vlzxf', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Which of the following Prophets, according to the Qur''an, lived for not less than nine hundred and fifty years?', null, '["Adam","Nuh","Ibrahim","Musa"]', 1, 'Prophet Nuh lived for 950 years.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following Prophets, according to the Qur''an, lived for not less than nine hundred and fifty years?', '["Adam","<u>Nuh</u>","Ibrahim","Musa"]', '<u>Nuh</u> (Q. 29:14).', '{"bold":[],"italic":[],"underline":["Nuh"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3vspl6i4sl3auslpabp8dmzs', 'Chemistry', 'JAMB', null, 1998, null, 'C3H8(g) + 5O2(g) → 4H2O(g) + 3CO2(g). From the equation above, the volume of oxygen at s.t.p. required to burn 50cm³ of propane is', null, '["250cm³","150cm³","100cm³","50cm³"]', 0, '1 vol C3H8 needs 5 vol O2; 50 × 5 = 250 cm³.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'C3H8(g) + 5O2(g) → 4H2O(g) + 3CO2(g). From the equation above, the volume of oxygen at s.t.p. required to burn 50cm³ of propane is', '["250cm³","150cm³","100cm³","50cm³"]', 'Volume O2 = 50 × 5 = <u>250 cm³</u>.', '{"bold":[],"italic":[],"underline":["250cm³"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3w4znao7fwgkwrgg7b2xx66b', 'General Mathematics', 'WAEC', null, 2020, null, 'A committee of 5 members is to be formed from 6 men and 4 women. In how many ways can this be done if the committee must include at least 2 women?', null, '["186","246","252","300"]', 1, 'Total - (0 women + 1 woman) = 10C5 - (6C5 + 6C4·4C1) = 252 - (6 + 60) = 186. Key says 246.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A committee of 5 members is to be formed from 6 men and 4 women. In how many ways can this be done if the committee must include at least 2 women?', '["186","246","252","300"]', 'Ways = <u>246</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3w52su23ugyfs2eypiuzgqvs', 'General Mathematics', 'JAMB', null, 2020, null, 'If sec A + tan A = m, find sec A - tan A.', null, '["1/m","m","m²","√m"]', 0, '(sec A + tan A)(sec A - tan A) = 1 → sec A - tan A = 1/m.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If sec A + tan A = m, find sec A - tan A.', '["1/m","m","m²","√m"]', 'sec A - tan A = <u>1/m</u>.', '{"bold":[],"italic":[],"underline":["1/m"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3wh3x856l0xn4icoxheie0w1', 'General Mathematics', 'WAEC', null, 2020, null, 'If log₁₀2 = a, log₁₀3 = b, express log₆120 in terms of a, b.', null, '["(1+2a+b)/(a+b)","(1+2a-b)/(a+b)","(1+2a+b)/(b-a)","(1+2a-b)/(b-a)"]', 0, '120 = 2³×3×5; log₆120 = (3a + b + log₁₀5)/(a+b) = (3a + b + 1-a)/(a+b) = (1+2a+b)/(a+b).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If log₁₀2 = a, log₁₀3 = b, express log₆120 in terms of a, b.', '["(1+2a+b)/(a+b)","(1+2a-b)/(a+b)","(1+2a+b)/(b-a)","(1+2a-b)/(b-a)"]', null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3whj5h79n2hpp86flqgvp32y', 'Biology', 'JAMB', null, 1995, null, 'In a tropical rain forest, non-epiphytic ferns and fern allies occur as', null, '["middle storey species","upper storey species","shade-loving species","emergent species."]', 2, 'Epiphytes live on other plants, usually in an arboreal habitat, without being parasitic.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In a tropical rain forest, non-epiphytic ferns and fern allies occur as', '["middle storey species","upper storey species","<u>shade-loving species</u>","emergent species."]', 'Epiphytes live on other plants, usually in an arboreal habitat, without being parasitic.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3wkmo9rfopzlm0epkf6lxay6', 'Islamic Religious Studies', 'JAMB', null, 2008, null, '[Arabic verse] The verse above teaches that Muslims should', null, '["Travel round the world and see wonders","Explore the earth and be learned","Go into the earth and see Allah''s creatures","Disperse into the land and earn a living"]', 3, 'Q.62:10 says disperse through the land and seek Allah''s bounty.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '[Arabic verse] The verse above teaches that Muslims should', '["Travel round the world and see wonders","Explore the earth and be learned","Go into the earth and see Allah''s creatures","<u>Disperse into the land and earn a living</u>"]', 'Q.62:10 says <u>disperse through the land and seek Allah''s bounty</u>.', '{"bold":[],"italic":[],"underline":["Disperse into the land and earn a living"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c3wkt03i24u52ov751ialbiev', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'What percentage of the estate of a late childless wife can the Muslim husband inherit?', null, '["1/2","1/3","1/4","1/6"]', 0, 'The husband inherits 1/2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What percentage of the estate of a late childless wife can the Muslim husband inherit?', '["<u>1/2</u>","1/3","1/4","1/6"]', '<u>1/2</u>.', '{"bold":[],"italic":[],"underline":["1/2"],"fillBlanks":[]}');
