insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4147r2375cr1u35qoo25vj3w', 'General Mathematics', 'JAMB', null, 2020, null, 'If a*b = a + b - ab, find the identity element in the reals.', null, '["0","1","-1","none"]', 0, 'a*e = a → a + e - ae = a → e(1-a) = 0 → e = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If a*b = a + b - ab, find the identity element in the reals.', '["0","1","-1","none"]', 'Identity = <u>0</u>.', '{"bold":[],"italic":[],"underline":["0"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4182698-2457-4938-ad57-6506413b699c', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The urban environment tends to form the <u>nucleus</u> of a common dialect.', null, '["setting","repository","cell","core"]', 3, 'Nucleus = core.', true, '2026-10-24 01:01:43.997', '2026-10-24 01:01:43.997', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The urban environment tends to form the <u>nucleus</u> of a common dialect.', '["setting","repository","cell","<u>core</u>"]', '<b>Nucleus</b> = <b>core</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c41dls2okg2r4uzwrss2nrjmc', 'Physics', 'JAMB', null, 2021, null, 'Which of the following pairs is not part of electromagnetic spectrum? I. Radiowave II. Betawave III. Gamma wave IV. Alpha wave', null, '["I & II","II & IV","III & IV","I & III","I-IV"]', 1, 'Beta and alpha waves are not electromagnetic waves; they are particle radiation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following pairs is <b>not part of electromagnetic spectrum</b>?<br>I. Radiowave<br>II. Betawave<br>III. Gamma wave<br>IV. Alpha wave', '["I & II","<u>II & IV</u>","III & IV","I & III","I-IV"]', '<u>Beta and alpha waves</u> are not electromagnetic waves; they are particle radiation.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c41hauxp318ae28g3eczyoosy', 'Government', 'JAMB', null, 2020, null, 'The first franchise in the history of the democratic process is', null, '["property franchise.","universal franchise","male franchise","female franchise"]', 0, 'Property franchise was the first form of franchise.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The first franchise in the history of the democratic process is', '["<u>property franchise.</u>","universal franchise","male franchise","female franchise"]', '<u>Property franchise</u>.', '{"bold":[],"italic":[],"underline":["property franchise."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c41kss7qap2nowm90i4ooakdk', 'Christian Religious Studies', 'JAMB', null, 2020, null, '..But let justice roll down like waters and righteousness like an overflowing stream. Amos'' statement above suggests that the society was terribly', null, '["vindictive","abusive","oppressive","destructive"]', 3, 'The society was terribly destructive.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '..But let justice roll down like waters and righteousness like an overflowing stream. Amos'' statement above suggests that the society was terribly', '["vindictive","abusive","oppressive","<u>destructive</u>"]', '<u>Destructive</u>.', '{"bold":[],"italic":[],"underline":["destructive"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c41t7145ngka0hkss06m6cg91', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'According to Isaiah, God sent him to', null, '["proclaim liberty to the captives","proclaim victory over Israel''s enemies","preach the gospel to the poor","proclaim the day of vengeance of the LORD"]', 3, 'God sent Isaiah to proclaim the day of vengeance of the LORD.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to Isaiah, God sent him to', '["proclaim liberty to the captives","proclaim victory over Israel''s enemies","preach the gospel to the poor","<u>proclaim the day of vengeance of the LORD</u>"]', '<u>Proclaim the day of vengeance of the LORD</u> (Isaiah 61:1-2).', '{"bold":[],"italic":[],"underline":["proclaim the day of vengeance of the LORD"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c42ac97jtupxlj4jct1kxs97f', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Tatfif in business transaction occurs when one of the partners', null, '["over-prices the goods","under-prices the commodity","tampers with the measure","refuses to pay for the goods."]', 2, 'Tatfif occurs when one tampers with the measure.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Tatfif in business transaction occurs when one of the partners', '["over-prices the goods","under-prices the commodity","<u>tampers with the measure</u>","refuses to pay for the goods."]', '<u>Tampers with the measure</u> (Q. 83:1-3).', '{"bold":[],"italic":[],"underline":["tampers with the measure"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c42haxkmdq974ffj1edhtojtn', 'Chemistry', 'JAMB', null, 1998, null, '2X(g) + Y(g) → Z(g). In the equation above, the rate of formation of Z is found to be independent of the concentration of Y and to quadruple when the concentration of X is doubled. The rate equation for the reaction is', null, '["R = k[X][Y]","R = k[X]²[Y]","R = k[X]²[Y]⁰","R = k[X]²[Y]⁰"]', 2, 'Rate ∝ [X]², independent of [Y] → R = k[X]².', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '2X(g) + Y(g) → Z(g). In the equation above, the rate of formation of Z is found to be independent of the concentration of Y and to quadruple when the concentration of X is doubled. The rate equation for the reaction is', '["R = k[X][Y]","R = k[X]²[Y]","R = k[X]²[Y]⁰","R = k[X]²[Y]⁰"]', 'Rate = <u>k[X]²</u> (independent of Y).', '{"bold":[],"italic":[],"underline":["R = k[X]²[Y]⁰"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c42yjjy6wk8fknlvacm4we0fd', 'General Mathematics', 'JAMB', null, 2020, null, 'If α, β, γ are the roots of x³ - 3x² + 2x - 1 = 0, find α²β + α²γ + β²α + β²γ + γ²α + γ²β.', null, '["2","3","6","8"]', 1, 'Σα²β = (α+β+γ)(αβ+βγ+γα) - 3αβγ = 3·2 - 3·1 = 3.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'If α, β, γ are the roots of x³ - 3x² + 2x - 1 = 0, find α²β + α²γ + β²α + β²γ + γ²α + γ²β.', '["2","3","6","8"]', 'Σα²β = (α+β+γ)(αβ+βγ+γα) - 3αβγ = 3·2 - 3·1 = 3.', '{"bold":[],"italic":[],"underline":["4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c430o407cxmgldbo7bvly1reh', 'Chemistry', 'JAMB', null, 2004, null, 'An isomer of C5H12 is', null, '["2-ethylbutane","butane","2-methylbutane","2-methylpropane"]', 2, '2-methylbutane is an isomer of C5H12.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An isomer of C5H12 is', '["2-ethylbutane","butane","2-methylbutane","2-methylpropane"]', '<u>2-methylbutane</u>.', '{"bold":[],"italic":[],"underline":["2-methylbutane"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4348loc3f2hf927e3pez2hib', 'Government', 'JAMB', null, 2020, null, 'One of the general tenets of fascist doctrine is that the leader is', null, '["supreme relative to the constitution","subordinate to the laws of the state","weak relative to the constitution","subordinate to the norms of the society"]', 0, 'Fascist leaders are supreme relative to the constitution.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One of the general tenets of fascist doctrine is that the leader is', '["<u>supreme relative to the constitution</u>","subordinate to the laws of the state","weak relative to the constitution","subordinate to the norms of the society"]', '<u>Supreme relative to the constitution</u>.', '{"bold":[],"italic":[],"underline":["supreme relative to the constitution"],"fillBlanks":[]}');
