insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4381imhd1gwq2xlhwc89ru04', 'Government', 'JAMB', null, 2020, null, 'Independence of the judiciary is pertinent because it accords the judiciary the power to', null, '["dismiss any judge who has breached the judicial code of conduct.","determine a fixed salary for judges","determine a fixed term of office for the judges","enable the judges to try and decide cases without bias"]', 3, 'Judicial independence enables judges to decide without bias.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Independence of the judiciary is pertinent because it accords the judiciary the power to', '["dismiss any judge who has breached the judicial code of conduct.","determine a fixed salary for judges","determine a fixed term of office for the judges","<u>enable the judges to try and decide cases without bias</u>"]', '<u>Enable judges to try and decide cases without bias</u>.', '{"bold":[],"italic":[],"underline":["enable the judges to try and decide cases without bias"],"fillBlanks":[]}');
