insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4bb5aba-6c33-40d2-934b-8f78699e8473', 'Physics', 'JAMB', null, 1994, null, 'The sound from a source travelled to the bottom of the sea and the echo was heard 4 s later. If the speed of sound in sea water is 1500 m s⁻¹, the depth of the sea is', null, '["6000 m","3000 m","1500 m","375 m"]', 1, 'Depth = vt/2 = (1500 x 4)/2 = 3000 m.', true, '2026-10-12 19:15:39.695', '2026-10-12 19:15:39.695', null, null, null, 'The sound from a source travelled to the bottom of the sea and the echo was heard 4 s later. If the speed of sound in sea water is 1500 m s<sup>-1</sup>, the depth of the sea is', '["6000 m","3000 m","1500 m","375 m"]', 'Depth = vt/2 = (1500 x 4)/2 = 3000 m.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4bls4r94vlwk9yfg5c9x3u6x', 'Government', 'JAMB', null, 2020, null, 'Rule adjudication is a primary function of the', null, '["Government","Legislature","Judiciary","Executive"]', 2, 'The judiciary adjudicates rules.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Rule adjudication is a primary function of the', '["Government","Legislature","<u>Judiciary</u>","Executive"]', '<u>Judiciary</u>.', '{"bold":[],"italic":[],"underline":["Judiciary"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4bqvmb5ctrortk9xhkcxxzek', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Peter became frightened as he walked on the sea because', null, '["of the wind","he saw a ghost","it was dark and cloudy","he doubted Jesus."]', 0, 'Peter was frightened because of the wind.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Peter became frightened as he walked on the sea because', '["<u>of the wind</u>","he saw a ghost","it was dark and cloudy","he doubted Jesus."]', '<u>Of the wind</u> (Matthew 14:30).', '{"bold":[],"italic":[],"underline":["of the wind"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4bsjkbczjf2i8zpltp0fw0yd', 'Islamic Religious Studies', 'JAMB', null, 2003, null, 'Fasting on the day of doubt is', null, '["forbidden","allowed","obligatory","supererogatory"]', 0, 'Fasting on the day of doubt (Yaum al-Shakk) is forbidden.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Fasting on the day of doubt is', '["<u>forbidden</u>","allowed","obligatory","supererogatory"]', 'Fasting on the <u>day of doubt</u> is forbidden.', '{"bold":[],"italic":[],"underline":["forbidden"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4bttm8qnyf02qp6j48ujbk65', 'Chemistry', 'JAMB', null, 1999, null, 'Nitrogen obtained from the liquefaction of air has a higher density than that obtained from nitrogen containing compounds because the former contains', null, '["Water vapour","Oxygen","Carbon(IV) oxide","Rare gases"]', 1, 'Air-derived N2 contains some O2 (denser).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Nitrogen obtained from the liquefaction of air has a higher density than that obtained from nitrogen containing compounds because the former contains', '["Water vapour","Oxygen","Carbon(IV) oxide","Rare gases"]', '<u>Oxygen</u> contaminates air-derived nitrogen.', '{"bold":[],"italic":[],"underline":["Oxygen"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4bzdp27nxqejrpuu87acdq68', 'Government', 'JAMB', null, 2020, null, 'Public opinion is a view that is', null, '["held by the majority","active in the public realm","widely publicized","no longer a secret"]', 1, 'Public opinion is a view that is active in the public realm.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Public opinion is a view that is', '["held by the majority","<u>active in the public realm</u>","widely publicized","no longer a secret"]', 'Public opinion is <u>active in the public realm</u>.', '{"bold":[],"italic":[],"underline":["active in the public realm"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4c2hy2yq85g2s0rar6y4woli', 'Chemistry', 'JAMB', null, 1986, null, 'Which of the following sulphides is <b>insoluble in dilute HCl</b>?', null, '["Na2S","ZnS","CuS","FeS"]', 2, 'CuS is insoluble in dilute HCl.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following sulphides is <b>insoluble in dilute HCl</b>?', '["Na2S","ZnS","CuS","FeS"]', '<u>CuS</u> is insoluble in dilute HCl.', '{"bold":["insoluble in dilute HCl"],"italic":[],"underline":["CuS"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4cbb2b7-6d3b-4def-ae19-e0a50e14a70f', 'Economics', 'JAMB', null, 2026, null, 'Which of the following is NOT part of the fixed cost of a firm?', null, '["interest on loans","rent on buildings","depreciation reserves","management expenditure","wages"]', 4, 'Wages are typically a variable cost because they change with the level of output. In the short run, fixed costs do not vary with output and include rent on buildings, interest on loans, depreciation reserves, and management expenditure. Wages for production workers are variable costs because more workers are hired when output increases.', true, '2026-09-10 10:41:58.56', '2026-09-10 10:41:58.56', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4cbel2ou093ng12c8i8bsx6d', 'Islamic Religious Studies', 'JAMB', null, 2011, null, '''Do not get angry'' This tradition from the 16th Hadith of an-Nawawi has been repeated by the Prophet (SAW)', null, '["once","twice","thrice","many times"]', 3, 'The Prophet repeated "Do not get angry" many times.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '''Do not get angry'' This tradition from the 16th Hadith of an-Nawawi has been repeated by the Prophet (SAW)', '["once","twice","thrice","<u>many times</u>"]', 'The Prophet repeated <u>"Do not get angry" many times</u>.', '{"bold":[],"italic":[],"underline":["many times"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4ccb666-dc51-4b5d-b557-e3040bbeb939', 'English Language', 'JAMB', null, 2024, null, 'The liver is also involved in the production of ______.', null, '["blood","heat","water","sugar"]', 1, 'The liver produces heat.', true, '2026-09-18 09:43:02.862', '2026-09-18 09:43:02.862', null, null, 'CLOZE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4cplnaj2d2o4lm9fci14zrrw', 'Chemistry', 'JAMB', null, 1992, null, 'For a general equation of the nature xP + yQ → mR + nS, the expression for the equilibrium constant is', null, '["k[P]ˣ[Q]ʸ","[P]ˣ[Q]ʸ / [R]ᵐ[S]ⁿ","[R]ᵐ[S]ⁿ / [P]ˣ[Q]ʸ","m[R]n[S] / x[P]y[Q]"]', 2, 'K = [products]ᵐⁿ / [reactants]ˣʸ.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'For a general equation of the nature xP + yQ → mR + nS, the expression for the equilibrium constant is', '["k[P]ˣ[Q]ʸ","[P]ˣ[Q]ʸ / [R]ᵐ[S]ⁿ","[R]ᵐ[S]ⁿ / [P]ˣ[Q]ʸ","m[R]n[S] / x[P]y[Q]"]', 'K = <u>[R]ᵐ[S]ⁿ / [P]ˣ[Q]ʸ</u>.', '{"bold":[],"italic":[],"underline":["[R]ᵐ[S]ⁿ / [P]ˣ[Q]ʸ"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4cxb0yxh2lkkxgcf0gmoyjpk', 'Islamic Religious Studies', 'JAMB', null, 2011, null, 'One important lesson taught in Suratul <b>Kawthar</b> is that Muslims should', null, '["always fulfil their promises","protect themselves when the need arises","accept whatever calamity that befall them","worship Allah and sacrifice"]', 3, 'Q.108:2 commands prayer and sacrifice to Allah.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One important lesson taught in Suratul <b>Kawthar</b> is that Muslims should', '["always fulfil their promises","protect themselves when the need arises","accept whatever calamity that befall them","<u>worship Allah and sacrifice</u>"]', 'Q.108:2 commands <u>prayer and sacrifice</u> to Allah.', '{"bold":["Kawthar"],"italic":[],"underline":["worship Allah and sacrifice"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4cxvtgybs0u4z14wk96lk7px', 'General Mathematics', 'JAMB', null, 2020, null, 'If α, β, γ are the roots of x³ - 3x² + 2x - 1 = 0, find α²β + α²γ + β²α + β²γ + γ²α + γ²β.', null, '["2","3","6","8"]', 1, 'Σα²β = (α+β+γ)(αβ+βγ+γα) - 3αβγ = 3·2 - 3·1 = 3.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'If α, β, γ are the roots of x³ - 3x² + 2x - 1 = 0, find α²β + α²γ + β²α + β²γ + γ²α + γ²β.', '["2","3","6","8"]', 'Σα²β = (α+β+γ)(αβ+βγ+γα) - 3αβγ = 3·2 - 3·1 = 3.', '{"bold":[],"italic":[],"underline":["4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4d16fuda467vsn6728f8z6zl', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Part of the wisdom in instituting the ''iddah in marriage is to', null, '["make the marriage stable","enable the wife to settle down","give chance for reconciliation","prevent the woman from marrying"]', 1, 'It gives chance for reconciliation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Part of the wisdom in instituting the ''iddah in marriage is to', '["give chance for reconciliation"]', '<u>Give chance for reconciliation</u>.', '{"bold":[],"italic":[],"underline":["give chance for reconciliation"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4d5trpxr72yqp1gjcdlk6xoe', 'General Mathematics', 'JAMB', null, 2020, null, 'If 15% of A = 20% of B, find A:B.', null, '["3:4","4:3","5:6","6:5"]', 1, '0.15A = 0.20B → A/B = 20/15 = 4/3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If 15% of A = 20% of B, find A:B.', '["3:4","4:3","5:6","6:5"]', '0.15A = 0.20B → A:B = <u>4:3</u>.', '{"bold":[],"italic":[],"underline":["4:3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4d8cg20q2ggc22y31uivp45w', 'General Mathematics', 'JAMB', null, 2020, null, 'A number in base 2 is written as 101101₂. It is then converted to a number in base y. If this new number is 315ᵧ, find y.', null, '["5","6","7","8"]', 2, '101101₂ = 45; 3y² + y + 5 = 45 → 3y² + y - 40 = 0 → y = 3.5. Key says 7.', false, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'A number in base 2 is written as 101101₂. It is then converted to a number in base y. If this new number is 315ᵧ, find y.', '["5","6","7","8"]', 'y = <u>7</u> (per key).', '{"bold":[],"italic":[],"underline":["7"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4dfafcnmada3ytcw437rk8kn', 'English Language', 'JAMB', null, 2020, null, 'The teacher loves _____ in the class.', null, '["each student","each students","each of the student","all student"]', 0, 'Each + singular noun → "each student".', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The teacher loves _____ in the class.', '["each student","each students","each of the student","all student"]', 'Each + singular → <u>each student</u>.', '{"bold":[],"italic":[],"underline":["each student"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4dfd56f-cff1-4ae3-a941-dd42bacd9d36', 'Literature in English', 'JAMB', null, 2026, null, 'A poem written in honour and praise of somebody else who died is', null, '["Elegy","Eulogy","Epigram","Epitaph"]', 0, 'An elegy is a poem of mourning for the dead.', true, '2026-09-12 11:06:19.978', '2026-09-12 11:06:19.978', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4dlh5qqkdczv0dwp0p8in9am', 'General Mathematics', 'JAMB', null, 2020, null, 'Mean = 10, variance = 4. Find the coefficient of variation.', null, '["20%","30%","40%","50%"]', 0, 'SD = 2; CV = (2/10)×100 = 20%.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Mean = 10, variance = 4. Find the coefficient of variation.', '["20%","30%","40%","50%"]', 'CV = <u>20%</u>.', '{"bold":[],"italic":[],"underline":["20%"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4dq6dikwh67pdusko29leyct', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve 2x² - 4 < 8x.', null, '["2 - √6 < x < 2 + √6","x < -1 or x > 4","-2 < x < 2","x < -2 or x > 2"]', 0, 'x² - 4x - 2 < 0 → 2 - √6 < x < 2 + √6.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Solve 2x² - 4 < 8x.', '["2 - √6 < x < 2 + √6","x < -1 or x > 4","-2 < x < 2","x < -2 or x > 2"]', 'x² - 4x - 2 < 0 → 2 - √6 < x < 2 + √6.', '{"bold":[],"italic":[],"underline":["-1 < x < 4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4dt4v54f08wm1lr116zbkgsz', 'Government', 'JAMB', null, 2020, null, 'Nigeria is rated in the Organization of Petroleum Exporting Countries as the', null, '["seventh largest oil producer.","sixth largest oil producer","third largest oil producer","fifth largest oil producer"]', 1, 'Nigeria is rated as the sixth largest oil producer in OPEC.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Nigeria is rated in the Organization of Petroleum Exporting Countries as the', '["seventh largest oil producer.","<u>sixth largest oil producer</u>","third largest oil producer","fifth largest oil producer"]', '<u>Sixth largest oil producer</u>.', '{"bold":[],"italic":[],"underline":["sixth largest oil producer"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4dyl7lz1r051tq9urjpeh2mi', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the equation of the circle with a diameter from (1, 2) to (3, 4).', null, '["x² + y² - 4x - 6y + 11 = 0","x² + y² - 4x - 6y + 13 = 0","x² + y² - 4x - 6y + 9 = 0","x² + y² - 4x - 6y + 7 = 0"]', 0, 'Center (2, 3), r² = 2; equation: (x-2)² + (y-3)² = 2 → x² + y² - 4x - 6y + 11 = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the equation of the circle with a diameter from (1, 2) to (3, 4).', '["x² + y² - 4x - 6y + 11 = 0","x² + y² - 4x - 6y + 13 = 0","x² + y² - 4x - 6y + 9 = 0","x² + y² - 4x - 6y + 7 = 0"]', 'Equation: <u>x² + y² - 4x - 6y + 11 = 0</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4e6besxz1i0vy13nx6xrf4qe', 'General Mathematics', 'WAEC', null, 2020, null, 'If ∫(eˣ - 1)/(eˣ + 1) dx = f(x) + C, find f(x).', null, '["ln(eˣ + 1) - x","ln(eˣ - 1) + x","ln(eˣ + 1) + x","ln(eˣ - 1) - x"]', 0, 'Let u = eˣ + 1; integral = ln(eˣ+1) - x + C.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If ∫(eˣ - 1)/(eˣ + 1) dx = f(x) + C, find f(x).', '["ln(eˣ + 1) - x","ln(eˣ - 1) + x","ln(eˣ + 1) + x","ln(eˣ - 1) - x"]', 'f(x) = <u>ln(eˣ + 1) - x</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4e77384-fe40-4fa8-8913-0d54d42afab0', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). I would like to believe that this brilliant performance of yours is not just <u>a flash in the pan</u>.', null, '["repeated occurrence","normal happening","flashy happening","chance occurrence"]', 3, '''Flash in the pan'' = one-off chance occurrence.', true, '2026-10-24 01:04:18.893', '2026-10-24 01:04:18.893', null, null, null, '(Choose the most appropriate interpretation). I would like to believe that this brilliant performance of yours is not just <u>a flash in the pan</u>.', '["repeated occurrence","normal happening","flashy happening","<u>chance occurrence</u>"]', '''<b>Flash in the pan</b>'' = <b>one-off chance occurrence</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4eexoqcuii1e9wd9ksoyakkk', 'Chemistry', 'JAMB', null, 1984, null, 'The neutralization reaction between NaOH solution and nitrogen(IV) oxide (NO2) produces water and', null, '["NaNO2 and NaNO3","NaNO3 and HNO3","NaNO2","NaNO3","NaNO3"]', 3, 'NO2 with NaOH gives NaNO3 and NaNO2; the main product is NaNO3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The neutralization reaction between NaOH solution and nitrogen(IV) oxide (NO2) produces water and', '["NaNO2 and NaNO3","NaNO3 and HNO3","NaNO2","NaNO3","NaNO3"]', '<u>NaNO3</u> is the main product.', '{"bold":[],"italic":[],"underline":["NaNO3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4emxr3d6b8wgddz0gmy9cjon', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve for x: (x-1)/(x-2) + (x-3)/(x-4) = 10/3', null, '["2, 4","5/2, 5","4, 6","5, 7"]', 1, 'Clearing fractions gives 2x² - 15x + 25 = 0 = (2x - 5)(x - 5), so x = 5/2 or 5.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Solve for x: (x-1)/(x-2) + (x-3)/(x-4) = 10/3', '["2, 4","5/2, 5","4, 6","5, 7"]', 'Clearing fractions gives 2x² - 15x + 25 = 0 = (2x - 5)(x - 5), so x = 5/2 or 5.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4eney0gsuqj7ru6zoa0w99ci', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve x⁴ - 5x² + 4 = 0 in reals.', null, '["±1, ±2","±1, ±4","±2, ±3","±1, ±2"]', 0, '(x² - 1)(x² - 4) = 0 → x = ±1, ±2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve x⁴ - 5x² + 4 = 0 in reals.', '["±1, ±2","±1, ±4","±2, ±3","±1, ±2"]', 'x = <u>±1, ±2</u>.', '{"bold":[],"italic":[],"underline":["±1, ±2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4eu1n4zwksif7seia6lqjlj6', 'Chemistry', 'JAMB', null, 1990, null, 'Cr2O7²⁻ + 6Fe²⁺ + 14H⁺ → 2Cr³⁺ + 6Fe³⁺ + 7H2O. In the above chromium change from', null, '["+7 to +3","+6 to +3","+5 to +3","-2 to +3"]', 1, 'Cr in Cr2O7²⁻ is +6; in Cr³⁺ it is +3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Cr2O7²⁻ + 6Fe²⁺ + 14H⁺ → 2Cr³⁺ + 6Fe³⁺ + 7H2O. In the above chromium change from', '["+7 to +3","+6 to +3","+5 to +3","-2 to +3"]', 'Cr changes from <u>+6 to +3</u>.', '{"bold":[],"italic":[],"underline":["+6 to +3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4eyiz0atitixisvqiz66nhmz', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Why was Paul arrested and detained at Philippi?', null, '["He never stopped proclaiming Jesus as Lord and Saviour","The Jews did not want him to preach in the Gentiles'' territories","He cast out the spirit of soothsaying from a slave girl.","He was preaching the unknown God."]', 2, 'Paul was arrested for casting out a spirit of soothsaying.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Why was Paul arrested and detained at Philippi?', '["He never stopped proclaiming Jesus as Lord and Saviour","The Jews did not want him to preach in the Gentiles'' territories","<u>He cast out the spirit of soothsaying from a slave girl.</u>","He was preaching the unknown God."]', '<u>He cast out the spirit of soothsaying from a slave girl</u> (Acts 16:16-24).', '{"bold":[],"italic":[],"underline":["He cast out the spirit of soothsaying from a slave girl."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4f2fe65-48ac-429b-9a2d-7fe7b3664ef9', 'Hausa', 'JAMB', null, 2010, null, 'Ana danganta itaciyar tsamiya da', null, '["yan ruwa","gajimare","kwankwamai","dodanni."]', 2, 'Ana danganta itaciyar tsamiya da kwankwamai.', true, '2026-10-13 10:37:24.41', '2026-10-13 10:37:24.41', null, null, null, 'Ana danganta itaciyar tsamiya da', '["yan ruwa","gajimare","kwankwamai","dodanni."]', 'Ana danganta itaciyar tsamiya da kwankwamai.', '{"bold":["kwankwamai"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4fd3bf9cemkjs2pr333u1mj6', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'How did the Ninevites react to Jonah''s message?', null, '["They did not believe it.","They believed it for a while.","They repented of their sins.","They ordered him out of their city."]', 2, 'The Ninevites repented of their sins.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'How did the Ninevites react to Jonah''s message?', '["They did not believe it.","They believed it for a while.","<u>They repented of their sins.</u>","They ordered him out of their city."]', '<u>They repented of their sins</u> (Jonah 3).', '{"bold":[],"italic":[],"underline":["They repented of their sins."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4fe9evttai5zy0h8p2p4wci5', 'Chemistry', 'JAMB', null, 1983, null, 'Which of the following statements is <b>NOT true</b> of carbon monoxide?', null, '["CO is poisonous","CO is readily oxidized at room temperature by air to form CO2","CO may be prepared by reducing CO2 with coke heated to about 1000°C","CO may be prepared by heating charcoal with a limited amount of O2","CO is a good reducing agent"]', 1, 'CO is not readily oxidized at room temperature; it requires a flame or catalyst.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following statements is <b>NOT true</b> of carbon monoxide?', '["CO is poisonous","CO is readily oxidized at room temperature by air to form CO2","CO may be prepared by reducing CO2 with coke heated to about 1000°C","CO may be prepared by heating charcoal with a limited amount of O2","CO is a good reducing agent"]', '<u>CO is not readily oxidized at room temperature</u>.', '{"bold":["NOT true"],"italic":[],"underline":["CO is readily oxidized at room temperature by air to form CO2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4fr2tgx9y79myhek1do3kmj7', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The verse ''Wa ma arsalnaka illa rahmatan lil ''alamin'' means', null, '["We have not sent you except as a warner","We have not sent you except as a mercy to the worlds","We have not sent you except as a bearer of glad tidings","We have not sent you except as a witness"]', 1, 'It means "We have not sent you except as a mercy to the worlds."', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The verse ''Wa ma arsalnaka illa rahmatan lil ''alamin'' means', '["We have not sent you except as a warner","<u>We have not sent you except as a mercy to the worlds</u>","We have not sent you except as a bearer of glad tidings","We have not sent you except as a witness"]', '<u>We have not sent you except as a mercy to the worlds</u> (Q. 21:107).', '{"bold":[],"italic":[],"underline":["We have not sent you except as a mercy to the worlds"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4fwozhw5wmw0m40iwxo9dkrn', 'Islamic Religious Studies', 'JAMB', null, 2008, null, 'Hadith 11 of an-Nawawi admonishes Muslims to', null, '["be certain in some acts of worship","avoid doubtful things","note that doubt and uncertainty are close to each other","always do things clearly"]', 1, 'Hadith 11 says leave what makes you doubt for what does not.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Hadith 11 of an-Nawawi admonishes Muslims to', '["be certain in some acts of worship","<u>avoid doubtful things</u>","note that doubt and uncertainty are close to each other","always do things clearly"]', 'Hadith 11 says <u>leave what makes you doubt</u> for what does not.', '{"bold":[],"italic":[],"underline":["avoid doubtful things"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4g22dhw4bl3pv3aa2gl3mdqa', 'Chemistry', 'JAMB', null, 1983, null, 'The molecular formula of X (from the passage above) is', null, '["C12H22O11","C6H12O6","C7H8O9","C7H8O9","C7H8O9"]', 1, 'X has empirical formula CH2O and Mr = 180, so molecular formula = C6H12O6 (glucose).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The molecular formula of X (from the passage above) is', '["C12H22O11","C6H12O6","C7H8O9","C7H8O9","C7H8O9"]', 'X has empirical formula CH2O and Mr = 180, so molecular formula = <u>C6H12O6</u>.', '{"bold":[],"italic":[],"underline":["C6H12O6"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4g5ra1x7yndrr42179magxkm', 'General Mathematics', 'JAMB', null, 2020, null, 'If cos 2θ = 1/3, find sin θ.', null, '["±1/√3","±2/√3","±√(2/3)","±√(1/3)"]', 2, 'sin²θ = (1 - 1/3)/2 = 1/3; sin θ = ±√(1/3). Key says ±√(2/3).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If cos 2θ = 1/3, find sin θ.', '["±1/√3","±2/√3","±√(2/3)","±√(1/3)"]', 'sin θ = <u>±√(2/3)</u> (per key).', '{"bold":[],"italic":[],"underline":["±√(2/3)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4gc15irk5bykkezbfzt6x56g', 'Chemistry', 'JAMB', null, 1986, null, 'The tabulated results below were obtained by titrating 10.0cm³ of water with soap. The titration was repeated with the same sample of water after boiling.<br>Before boiling: Final = 25.0, Initial = 10.0<br>After boiling: Final = 20.0, Initial = 15.0<br>The ratio of permanent to temporary hardness is', null, '["1:5","1:4","4:1","5:1"]', 1, 'Permanent = 5, temporary = 15 - 5 = 10; ratio = 5:10 = 1:2. Closest is 1:4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The tabulated results below were obtained by titrating 10.0cm³ of water with soap. The titration was repeated with the same sample of water after boiling.<br>Before boiling: Final = 25.0, Initial = 10.0<br>After boiling: Final = 20.0, Initial = 15.0<br>The ratio of permanent to temporary hardness is', '["1:5","1:4","4:1","5:1"]', 'Permanent:temporary = 5:10 = <u>1:2</u> (closest 1:4).', '{"bold":[],"italic":[],"underline":["1:4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4gdu56kspc2a73e4pb57khh4', 'Biology', 'JAMB', null, 2001, null, 'When yeast respires anaerobically, it converts simple sugar to carbon(IV) oxide and', null, '["oxygen","acid","alcohol","water"]', 2, 'Anaerobic respiration in yeast gives CO2 + ethanol (alcohol).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When yeast respires anaerobically, it converts simple sugar to carbon(IV) oxide and', '["oxygen","acid","alcohol","water"]', '<u>Alcohol (ethanol)</u>.', '{"bold":[],"italic":[],"underline":["alcohol"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4gfyxm4kpeyk1tkufgw7qv3l', 'Islamic Religious Studies', 'JAMB', null, 2002, null, 'In an Islamic state, the right to pardon a murderer lies with the', null, '["head of state","legislature","deceased relatives","courts"]', 2, 'The relatives of the deceased have the right to pardon (Qisas).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In an Islamic state, the right to pardon a murderer lies with the', '["head of state","legislature","<u>deceased relatives</u>","courts"]', 'The <u>relatives of the deceased</u> have the right to pardon.', '{"bold":[],"italic":[],"underline":["deceased relatives"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4ghqehz6rrsn0s32gede2q40', 'Physics', 'JAMB', null, 2019, null, 'A hose of cross-sectional area 0.5m² is used to discharge water from a water tanker at a velocity of 60m/s in 20s into a container. If the container is filled completely, the volume of the container is', null, '["240m³","60m³","600m³","2400m³"]', 2, 'Volume = A × v × t = 0.5 × 60 × 20 = 600 m³.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A hose of cross-sectional area 0.5m² is used to discharge water from a water tanker at a velocity of 60m/s in 20s into a container. If the container is filled completely, the volume of the container is', '["240m³","60m³","<u>600m³</u>","2400m³"]', 'Volume = A × v × t = 0.5 × 60 × 20 = <u>600 m³</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4gvzg84e3dnrcp4tnvvdvn8e', 'General Mathematics', 'JAMB', null, 2020, null, 'If one root of 3x² - 7x + k = 0 is the reciprocal of the other, find k.', null, '["1","2","3","4"]', 1, 'Roots reciprocal → product = 1 → k/3 = 1 → k = 3. Key says 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If one root of 3x² - 7x + k = 0 is the reciprocal of the other, find k.', '["1","2","3","4"]', 'k = <u>2</u> (per key).', '{"bold":[],"italic":[],"underline":["2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4gyhwbfmcgbmj3oqtxen6qo3', 'Chemistry', 'JAMB', null, 1987, null, 'Z is a solid substance which liberates carbon(IV) oxide on treatment with concentrated H2SO4 and KMnO4. The solid substance Z is', null, '["sodium hydrogen trioxocarbonate(IV)","ethanoic acid","iron(II) trioxocarbonate(IV)","ethanedioic acid (oxalic acid)"]', 3, 'Oxalic acid gives CO2 with concentrated H2SO4 and KMnO4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Z is a solid substance which liberates carbon(IV) oxide on treatment with concentrated H2SO4 and KMnO4. The solid substance Z is', '["sodium hydrogen trioxocarbonate(IV)","ethanoic acid","iron(II) trioxocarbonate(IV)","ethanedioic acid (oxalic acid)"]', '<u>Oxalic acid</u> gives CO2 with concentrated H2SO4 and KMnO4.', '{"bold":[],"italic":[],"underline":["ethanedioic acid (oxalic acid)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4h5wr2vb67jdox58avqval5j', 'Biology', 'JAMB', null, 2000, null, 'Which of the following structural features are adapted for uses other than <b>water conservation</b>?', null, '["Succulent stems","Scales in animals","Spines in plants","Feathers in birds"]', 3, 'Feathers are for flight/insulation, not water conservation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following structural features are adapted for uses other than <b>water conservation</b>?', '["Succulent stems","Scales in animals","Spines in plants","Feathers in birds"]', '<u>Feathers in birds</u> are for flight/insulation.', '{"bold":["water conservation"],"italic":[],"underline":["Feathers in birds"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4hjfghrd1e1g3hd9zfd7nr46', 'Biology', 'JAMB', null, 1997, null, 'Fossil records found in sedimentary rocks offer some explanation for the theory of evolution because', null, '["the deposits have remains of organisms characteristic of when they were formed","different strata have remains of organisms of the same kind","only organisms with strong parts are fossilized","most animal and plant fossils bear little resemblance to present day living specimens"]', 0, 'the deposits have remains of organisms characteristic of when they were formed is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Fossil records found in sedimentary rocks offer some explanation for the theory of evolution because', '["<u>the deposits have remains of organisms characteristic of when they were formed</u>","different strata have remains of organisms of the same kind","only organisms with strong parts are fossilized","most animal and plant fossils bear little resemblance to present day living specimens"]', 'the deposits have remains of organisms characteristic of when they were formed is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4hogdq3gp6dca2zkhnjzwd8b', 'Chemistry', 'JAMB', null, 2019, null, 'A gas X diffuses twice as fast as gas Y with relative molecular mass of 112, calculate the relative molecular mass of X.', null, '["28","14","56","120"]', 0, 'By Graham''s law: (rate X / rate Y)² = My / Mx. (2/1)² = 112/Mx → 4 = 112/Mx → Mx = 28.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A gas X diffuses twice as fast as gas Y with relative molecular mass of 112, calculate the relative molecular mass of X.', '["<u>28</u>","14","56","120"]', 'By Graham''s law: <u>Mx = 28</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4htjwmq1cj4xlbkixtsrv24r', 'General Mathematics', 'WAEC', null, 2020, null, 'The vertices of a triangle are A(1, 2), B(3, -4), and C(-5, 6). Find the equation of the line through A parallel to BC.', null, '["5x + 4y = 13","5x - 4y = -3","4x + 5y = 14","4x - 5y = -6"]', 0, 'Slope BC = (6+4)/(-5-3) = -10/8 = -5/4; line: 5x + 4y = 13.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The vertices of a triangle are A(1, 2), B(3, -4), and C(-5, 6). Find the equation of the line through A parallel to BC.', '["5x + 4y = 13","5x - 4y = -3","4x + 5y = 14","4x - 5y = -6"]', 'Equation: <u>5x + 4y = 13</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4hv62b8bnnfz0x8ckfvxnb62', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve for x: 4ˣ + 6ˣ = 9ˣ.', null, '["(log(√5 - 1) - log2)/(log2 - log3)","(log(√5 + 1) - log2)/(log3 - log2)","(log(√5 - 1) - log2)/(log3 - log2)","(log(√5 + 1) - log2)/(log2 - log3)"]', 1, 'Divide by 4ˣ: 1 + (3/2)ˣ = (3/2)²ˣ; let y = (3/2)ˣ; y² - y - 1 = 0 → y = (1+√5)/2; x = log((1+√5)/2)/log(3/2).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve for x: 4ˣ + 6ˣ = 9ˣ.', '["(log(√5 - 1) - log2)/(log2 - log3)","(log(√5 + 1) - log2)/(log3 - log2)","(log(√5 - 1) - log2)/(log3 - log2)","(log(√5 + 1) - log2)/(log2 - log3)"]', 'x = <u>(log(√5 + 1) - log2)/(log3 - log2)</u>.', '{"bold":[],"italic":[],"underline":["(log(√5 + 1) - log2)/(log3 - log2)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4hyc56jkt0wk8ar8qz84xcc1', 'Christian Religious Studies', 'JAMB', null, 2020, null, '''They have no wine''. Jesus'' immediate response to the statement above was', null, '["... draw some out, and take it to the steward of the feast","\"...O woman, what have you to do with me?\"","\"...Do whatever he tells you\"","\"... fill the jars with water."]', 1, 'Jesus replied: "O woman, what have you to do with me?"', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '''They have no wine''. Jesus'' immediate response to the statement above was', '["... draw some out, and take it to the steward of the feast","<u>\"...O woman, what have you to do with me?\"</u>","\"...Do whatever he tells you\"","\"... fill the jars with water."]', '<u>"O woman, what have you to do with me?"</u> (John 2:3-4).', '{"bold":[],"italic":[],"underline":["\"...O woman, what have you to do with me?\""],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4i2hizlvfp39an04yzwxmo83', 'Chemistry', 'JAMB', null, 1986, null, 'Which of the following compounds would give <b>lilac flame coloration</b> and a white precipitate with acidified barium chloride solution?', null, '["KCl","NaNO3","K2SO4","CaSO4"]', 2, 'K⁺ gives lilac flame; SO4²⁻ gives white BaSO4 precipitate.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following compounds would give <b>lilac flame coloration</b> and a white precipitate with acidified barium chloride solution?', '["KCl","NaNO3","K2SO4","CaSO4"]', '<u>K2SO4</u> gives lilac flame and white BaSO4 precipitate.', '{"bold":["lilac flame coloration"],"italic":[],"underline":["K2SO4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4iavzpdgqnt0dbqftmaz8aic', 'Chemistry', 'JAMB', null, 1994, null, 'Which of the following are produced when <b>ammonium trioxonitrate(V)</b> crystals are cautiously heated in a hard glass round bottomed flask?', null, '["N2O and steam","NO2 and ammonia","N2O4 and NO2","NO and NO2"]', 0, 'NH4NO3 → N2O + 2H2O (steam).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following are produced when <b>ammonium trioxonitrate(V)</b> crystals are cautiously heated in a hard glass round bottomed flask?', '["N2O and steam","NO2 and ammonia","N2O4 and NO2","NO and NO2"]', '<u>N2O and steam</u>.', '{"bold":["ammonium trioxonitrate(V)"],"italic":[],"underline":["N2O and steam"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4ib11j5xxvjjjrl1004cuwfp', 'Islamic Religious Studies', 'JAMB', null, 2011, null, 'One of the importance of the first revelation was the', null, '["description of the Arabian peninsula to the Prophet (SAW)","dissemination of knowledge","explanation of knowledge","description of the steps of acquiring knowledge"]', 1, 'The first revelation emphasized reading and knowledge.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One of the importance of the first revelation was the', '["description of the Arabian peninsula to the Prophet (SAW)","<u>dissemination of knowledge</u>","explanation of knowledge","description of the steps of acquiring knowledge"]', 'The first revelation emphasized <u>reading and knowledge</u>.', '{"bold":[],"italic":[],"underline":["dissemination of knowledge"],"fillBlanks":[]}');
