insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4iw6pynoszsom28lb5zz15lk', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the moment about the point (2, 3, -1) of a force F = 3i - 2j + 4k acting through the point (1, -2, 3).', null, '["-13i - 5j - 11k","13i + 5j + 11k","13i - 5j + 11k","-13i + 5j - 11k"]', 0, 'r = (1-2)i + (-2-3)j + (3+1)k = -i - 5j + 4k; M = r × F = -13i - 5j - 11k.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the moment about the point (2, 3, -1) of a force F = 3i - 2j + 4k acting through the point (1, -2, 3).', '["-13i - 5j - 11k","13i + 5j + 11k","13i - 5j + 11k","-13i + 5j - 11k"]', 'Moment = <u>-13i - 5j - 11k</u>.', '{"bold":[],"italic":[],"underline":["-13i - 5j - 11k"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4j8bk1fca6oz36bos882dn4d', 'Government', 'JAMB', null, 2020, null, 'An attribute that Nigeria shares with most non-aligned countries is', null, '["the state of her economy","her large population","her heterogeneous population","her large size."]', 0, 'The state of the economy is a shared attribute.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An attribute that Nigeria shares with most non-aligned countries is', '["<u>the state of her economy</u>","her large population","her heterogeneous population","her large size."]', '<u>The state of her economy</u>.', '{"bold":[],"italic":[],"underline":["the state of her economy"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4jaancasii53r5vf06ox0d0w', 'Islamic Religious Studies', 'JAMB', null, 2002, null, 'The uniqueness of the Glorious Qur''an, according to Q.39:28, lies in the fact that it is', null, '["highly educative","in brief form","revealed piecemeal","revealed in Arabic"]', 3, 'Q.39:28 describes the Qur''an as an Arabic Qur''an without crookedness.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The uniqueness of the Glorious Qur''an, according to Q.39:28, lies in the fact that it is', '["highly educative","in brief form","revealed piecemeal","<u>revealed in Arabic</u>"]', 'Q.39:28 describes the Qur''an as an <u>Arabic Qur''an</u> without crookedness.', '{"bold":[],"italic":[],"underline":["revealed in Arabic"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4jpt64050hrj28j0cwbgiwi7', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve for x given that: 5^x · 25^(x-1) = 125^(x+2).', null, '["-3","-4","no solution","-6"]', 2, '5^(3x-2) = 5^(3x+6) gives -2 = 6, so there is no solution.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Solve for x given that: 5^x · 25^(x-1) = 125^(x+2).', '["-3","-4","no solution","-6"]', '5^(3x-2) = 5^(3x+6) gives -2 = 6, so there is no solution.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4jvrun04d2scpytpo5xy3bj6', 'Chemistry', 'JAMB', null, 1998, null, '2FeCl2(s) + Cl2(g) → 2FeCl3(s). The reducing agent in the reaction above is', null, '["FeCl2","Cl2","FeCl3","Fe"]', 0, 'Fe²⁺ is oxidized to Fe³⁺, so FeCl2 is the reducing agent.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '2FeCl2(s) + Cl2(g) → 2FeCl3(s). The reducing agent in the reaction above is', '["FeCl2","Cl2","FeCl3","Fe"]', '<u>FeCl2 is the reducing agent</u>.', '{"bold":[],"italic":[],"underline":["FeCl2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4jy0xgv81prymugrpd78t2ju', 'General Mathematics', 'WAEC', null, 2020, null, 'If (1,2) is the midpoint of (3,a) and (b,6), find a + b.', null, '["5","6","-3","8"]', 2, '(3+b)/2 = 1 → b = -1; (a+6)/2 = 2 → a = -2; a + b = -3.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'If (1,2) is the midpoint of (3,a) and (b,6), find a + b.', '["5","6","-3","8"]', '(3+b)/2 = 1 → b = -1; (a+6)/2 = 2 → a = -2; a + b = -3.', null);
