insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4k4e5ebqa96uxukb81hple2g', 'General Mathematics', 'JAMB', null, 2020, null, 'The polar of (1, 2) with respect to the circle x² + y² = 9 is:', null, '["x + 2y = 9","2x + y = 9","x - 2y = 9","2x - y = 9"]', 0, 'Polar: x·1 + y·2 = 9 → x + 2y = 9.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The polar of (1, 2) with respect to the circle x² + y² = 9 is:', '["x + 2y = 9","2x + y = 9","x - 2y = 9","2x - y = 9"]', 'Polar: <u>x + 2y = 9</u>.', '{"bold":[],"italic":[],"underline":["x + 2y = 9"],"fillBlanks":[]}');
