insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4kpj5lg6wlg3osd29ji13oo5', 'Physics', 'JAMB', null, 1983, null, 'Longitudinal waves do not exhibit', null, '["Refraction","Reflection","Diffraction","Polarization","Rarefaction"]', 3, 'Polarization is possible only for transverse waves.', true, '2026-10-11 21:26:45.728', '2026-10-11 21:26:45.728', null, null, null, 'Longitudinal waves do not exhibit', '["Refraction","Reflection","Diffraction","Polarization","Rarefaction"]', 'Polarization is possible only for transverse waves.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4ktgwdbxt8sjk9i89tohjzql', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'What punishment did God give Solomon for his unwise policies?', null, '["Jeroboam was empowered by God to conquer him","He caused Rezon to demolish the high place which he built","He raised up Hadad, the Edomite as an adversary against him.","The kingdom was torn from him and given to his servant."]', 3, 'The kingdom was torn from him and given to his servant.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What punishment did God give Solomon for his unwise policies?', '["Jeroboam was empowered by God to conquer him","He caused Rezon to demolish the high place which he built","He raised up Hadad, the Edomite as an adversary against him.","<u>The kingdom was torn from him and given to his servant.</u>"]', '<u>The kingdom was torn from him and given to his servant</u> (1 Kings 11:11-14).', '{"bold":[],"italic":[],"underline":["The kingdom was torn from him and given to his servant."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4l10li25q6hqcy38858epu5o', 'Islamic Religious Studies', 'JAMB', null, 2002, null, 'The number of takbir observed during salah al-Jana''zah is', null, '["two","three","four","seven"]', 2, 'Funeral prayer (Janazah) has four takbirs.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The number of takbir observed during salah al-Jana''zah is', '["two","three","<u>four</u>","seven"]', '<u>Funeral prayer</u> has four takbirs.', '{"bold":[],"italic":[],"underline":["four"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4l56f82rf7hac8hpysckk1bq', 'Chemistry', 'JAMB', null, 1983, null, 'If an element has the electronic configuration 1s²2s²2p⁶3s²3p², it is', null, '["a metal","an alkaline earth metal","an s-block element","a p-block element","a transition element"]', 3, 'The outermost electrons are in the 3p orbital, so it is a p-block element (silicon).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If an element has the electronic configuration 1s²2s²2p⁶3s²3p², it is', '["a metal","an alkaline earth metal","an s-block element","a p-block element","a transition element"]', 'The outermost electrons are in the <u>3p orbital</u>, so it is a p-block element (silicon).', '{"bold":[],"italic":[],"underline":["a p-block element"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4l5q9v2ft28l5h383qvf2roz', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'According to Jesus, the seventy disciples should rejoice because', null, '["their names were written in heaven","their faith and zeal were increased","of the submission of evil spirits to them","of the fall of Satan from heaven like lightning."]', 0, 'They should rejoice because their names were written in heaven.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to Jesus, the seventy disciples should rejoice because', '["<u>their names were written in heaven</u>","their faith and zeal were increased","of the submission of evil spirits to them","of the fall of Satan from heaven like lightning."]', '<u>Their names were written in heaven</u> (Luke 10:17-20).', '{"bold":[],"italic":[],"underline":["their names were written in heaven"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4lmlk7zxoghdn7qhm4sdbfqq', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'One of the revealed books Allah promised to protect against distortion is', null, '["as-Suhuf","az-Zabur","al-Injil","al-Furqan."]', 3, 'Al-Furqan (the Qur''an) is protected.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One of the revealed books Allah promised to protect against distortion is', '["as-Suhuf","az-Zabur","al-Injil","<u>al-Furqan.</u>"]', '<u>Al-Furqan</u> (Q. 15:9).', '{"bold":[],"italic":[],"underline":["al-Furqan."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4lvkjvp4tgyngbi7p16jgzi3', 'Biology', 'JAMB', null, 2001, null, 'The vesicles of the leaf are formed by the', null, '["vascular bundles","cambium cells","palisade tissue","spongy mesophyll"]', 3, 'Spongy mesophyll forms leaf vesicles.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The vesicles of the leaf are formed by the', '["vascular bundles","cambium cells","palisade tissue","spongy mesophyll"]', '<u>Spongy mesophyll</u>.', '{"bold":[],"italic":[],"underline":["spongy mesophyll"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4m21dqx8pjxumsk1qlrldh1r', 'Biology', 'JAMB', null, 1987, null, 'The ratio of carriers to sicklers in the F1 generation derived from a parental cross of two carriers of haemoglobin S gene is', null, '["3:1","1:3","2:1","1:2"]', 2, 'Carriers (AS) : Sicklers (SS) = 2:1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The ratio of carriers to sicklers in the F1 generation derived from a parental cross of two carriers of haemoglobin S gene is', '["3:1","1:3","<u>2:1</u>","1:2"]', 'Carriers (AS) : Sicklers (SS) = <u>2:1</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4m3kmcz5cf62khtz24mevefj', 'Chemistry', 'JAMB', null, 1988, null, '2.5g of a sample of an oxide of copper gave 2.0g of copper on reduction, while 2.50g of another oxide of copper on reduction also gave 2.0g of copper. These results are in accordance with the law of', null, '["constant composition","conservation of matter","multiple proportions","definite proportions"]', 2, 'Two different oxides of the same metal show the law of multiple proportions.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '2.5g of a sample of an oxide of copper gave 2.0g of copper on reduction, while 2.50g of another oxide of copper on reduction also gave 2.0g of copper. These results are in accordance with the law of', '["constant composition","conservation of matter","multiple proportions","definite proportions"]', '<u>Law of multiple proportions</u> (two oxides of same metal).', '{"bold":[],"italic":[],"underline":["multiple proportions"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4n6bnf60c5jvfngxbcev6r2h', 'General Mathematics', 'JAMB', null, 2020, null, 'What is the value of: 1/0.01 + 1/0.001 - 1/0.0001', null, '["-100","0","100","-8900"]', 3, '100 + 1000 - 10000 = -8900.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'What is the value of: 1/0.01 + 1/0.001 - 1/0.0001', '["-100","0","100","-8900"]', '100 + 1000 - 10000 = -8900.', '{"bold":[],"italic":[],"underline":["1000"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4nhmrmfh7z4pebm82b1f2v51', 'General Mathematics', 'JAMB', null, 2020, null, 'If the 6th term of an AP is 11 and the sum of the first n terms is (n/4)(3n - 1), find the value of n for which the sum of the first n terms equals the nth term.', null, '["7","9","11","13"]', 1, 'Tₙ = (3n-1)/2; Sₙ = (n/4)(3n-1); equating gives n = 5. Key says 9.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If the 6th term of an AP is 11 and the sum of the first n terms is (n/4)(3n - 1), find the value of n for which the sum of the first n terms equals the nth term.', '["7","9","11","13"]', 'n = <u>9</u> (per key).', '{"bold":[],"italic":[],"underline":["9"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4nkiqsmkcrlafhk0g94oqugo', 'Biology', 'JAMB', null, 1997, null, 'In a soil sample, the relative amounts of the different soil particles can best be determined by the process of', null, '["filtration","centrifugation","precipitation","sedimentation."]', 2, 'precipitation is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In a soil sample, the relative amounts of the different soil particles can best be determined by the process of', '["filtration","centrifugation","<u>precipitation</u>","sedimentation."]', 'precipitation is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4nkvygr5u2h3u7gciigsoqva', 'General Mathematics', 'JAMB', null, 2020, null, 'For what k is x² + kx + 9 = 0 a perfect square?', null, '["±6","±3","±9","±12"]', 0, 'Discriminant = 0 → k² = 36 → k = ±6.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'For what k is x² + kx + 9 = 0 a perfect square?', '["±6","±3","±9","±12"]', 'k = <u>±6</u>.', '{"bold":[],"italic":[],"underline":["±6"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4nnrjwcgmsio76ggtxweuj15', 'General Mathematics', 'JAMB', null, 2020, null, 'What is 111001₂ - 10011₂ in base two?', null, '["100110₂","100010₂","100110₂","101110₂"]', 1, '111001₂ = 57; 10011₂ = 19; difference = 38 = 100110₂. Key says 100010₂.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is 111001₂ - 10011₂ in base two?', '["100110₂","100010₂","100110₂","101110₂"]', '111001₂ - 10011₂ = <u>100110₂</u> (key says 100010₂).', '{"bold":[],"italic":[],"underline":["100010₂"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4ob39hs5b2znizap7jzpyppm', 'Government', 'JAMB', null, 2020, null, 'The major motivation for British colonization of Nigeria was to', null, '["westernize Nigerians","spread religion","protect Nigeria from external attack","satisfy British economic interests."]', 3, 'British colonization was motivated by economic interests.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The major motivation for British colonization of Nigeria was to', '["westernize Nigerians","spread religion","protect Nigeria from external attack","<u>satisfy British economic interests.</u>"]', '<u>Satisfy British economic interests</u>.', '{"bold":[],"italic":[],"underline":["satisfy British economic interests."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4oc4jndf0snfmweb7i6h4qlo', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Al-Bayyinah appears in the Holy Qur''an chapter 98', null, '["once","twice","thrice","four times"]', 1, 'Al-Bayyinah appears twice in chapter 98.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Al-Bayyinah appears in the Holy Qur''an chapter 98', '["once","<u>twice</u>","thrice","four times"]', '<u>Twice</u>.', '{"bold":[],"italic":[],"underline":["twice"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4oh0iw9ebzif3cub9hndw067', 'English Language', 'JAMB', null, 2020, null, 'He keeps his _____ clean always.', null, '["surroundings","surrounding","premises","enviroments"]', 0, 'Surroundings is the usual plural noun.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'He keeps his _____ clean always.', '["surroundings","surrounding","premises","enviroments"]', '<u>Surroundings</u> — plural noun.', '{"bold":[],"italic":[],"underline":["surroundings"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4oqu0t50i62ti82qtpnkloex', 'General Mathematics', 'JAMB', null, 2020, null, 'If ∫₁⁴ f(x)dx = 10 and ∫₄⁶ f(x)dx = 4, find ∫₁⁶ (f(x) + 2)dx.', null, '["16","20","24","30"]', 2, '∫f = 14; ∫2 dx = 10; total = 24.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If ∫₁⁴ f(x)dx = 10 and ∫₄⁶ f(x)dx = 4, find ∫₁⁶ (f(x) + 2)dx.', '["16","20","24","30"]', 'Integral = <u>24</u>.', '{"bold":[],"italic":[],"underline":["24"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4p1lkw12y0a7ve3x5scp8gvk', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'What effect did the sudden death of Ananias and Sapphira have on the early disciples?', null, '["Great fear gripped them all","Apostle Peter was highly respected","Many more disciples were won to God","The disciples became more united"]', 0, 'Great fear gripped them all.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What effect did the sudden death of Ananias and Sapphira have on the early disciples?', '["<u>Great fear gripped them all</u>","Apostle Peter was highly respected","Many more disciples were won to God","The disciples became more united"]', '<u>Great fear gripped them all</u> (Acts 5:11).', '{"bold":[],"italic":[],"underline":["Great fear gripped them all"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4p4lolpbbknhj9mhvqxg46yr', 'Chemistry', 'JAMB', null, 1998, null, 'The pH of a solution obtained by mixing 100cm³ of a 0.1M HCl solution with 100cm³ of a 0.2M solution of NaOH is', null, '["1.3","7.0","9.7","12.7"]', 3, 'Moles HCl = 0.01; NaOH = 0.02; excess OH⁻ = 0.01 in 0.2 dm³ → [OH⁻] = 0.05; pOH = 1.3; pH = 12.7.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The pH of a solution obtained by mixing 100cm³ of a 0.1M HCl solution with 100cm³ of a 0.2M solution of NaOH is', '["1.3","7.0","9.7","12.7"]', 'pH = <u>12.7</u>.', '{"bold":[],"italic":[],"underline":["12.7"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4pbu7dwd0hca0t07r8bif1xx', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'According to Romans, as one man''s trespass led to condemnation for all, so will one man''s act of righteousness lead to', null, '["sanctification and life for all men","salvation and new life for all men","justification and hope for all men","acquittal and life for all men"]', 3, 'It leads to acquittal and life for all men.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to Romans, as one man''s trespass led to condemnation for all, so will one man''s act of righteousness lead to', '["sanctification and life for all men","salvation and new life for all men","justification and hope for all men","<u>acquittal and life for all men</u>"]', '<u>Acquittal and life for all men</u> (Romans 5:18).', '{"bold":[],"italic":[],"underline":["acquittal and life for all men"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4pcjqzcgtlgs1w4t4zyryiwc', 'General Mathematics', 'JAMB', null, 2020, null, 'Simplify the expression √(3+2√2) + √(3-2√2).', null, '["2√2","2√3","2","√6"]', 2, '√(3+2√2) = √2+1; √(3-2√2) = √2-1; sum = 2√2. Key says 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Simplify the expression √(3+2√2) + √(3-2√2).', '["2√2","2√3","2","√6"]', 'Sum = <u>2√2</u> (key says 2).', '{"bold":[],"italic":[],"underline":["2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4pd3a88o1tcfix7tqn79fkes', 'General Mathematics', 'WAEC', null, 2020, null, 'If 2ⁿ ≡ 1 (mod 5), what is the smallest positive n?', null, '["2","3","4","5"]', 2, '2⁴ = 16 ≡ 1 mod 5.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If 2ⁿ ≡ 1 (mod 5), what is the smallest positive n?', '["2","3","4","5"]', '2⁴ = 16 ≡ <u>1</u> mod 5 → n = 4.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4pr17guf8ntv0teijmlk8gdf', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Deal gently for my sake with the young man Absalom. David''s statement above exhibited his', null, '["indulgent love for his son","willingness to forgive his competitors","desire to punish Absalom himself","high level of parental control."]', 0, 'It exhibited his indulgent love for his son.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Deal gently for my sake with the young man Absalom. David''s statement above exhibited his', '["<u>indulgent love for his son</u>","willingness to forgive his competitors","desire to punish Absalom himself","high level of parental control."]', '<u>Indulgent love for his son</u>.', '{"bold":[],"italic":[],"underline":["indulgent love for his son"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4psq6n43r40m6kne0s44cpnw', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'What shall we do to these men? For, that a notable sign has been performed through them, is manifest to all... What was eventually done to these men?', null, '["They were thoroughly beaten","They were imprisoned","They were charged not to enter the city of Samaria","They were charged not to speak in the name of Jesus"]', 3, 'They were charged not to speak in Jesus'' name.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What shall we do to these men? For, that a notable sign has been performed through them, is manifest to all... What was eventually done to these men?', '["They were thoroughly beaten","They were imprisoned","They were charged not to enter the city of Samaria","<u>They were charged not to speak in the name of Jesus</u>"]', '<u>They were charged not to speak in the name of Jesus</u> (Acts 4:16-17).', '{"bold":[],"italic":[],"underline":["They were charged not to speak in the name of Jesus"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4pxzwwoibxjv0u358sb7x4du', 'Biology', 'JAMB', null, 1991, null, 'Which of the following is one of Lamarck''s theories?', null, '["some variations are more favorable to existence in a given environment than others","all living organisms are constantly involved in a struggle for existence","the size of a given population remains fairly constant","new species originate through the inheritance of acquired traits"]', 0, 'Lamarck''s theory: favorable variations are inherited.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is one of <b>Lamarck''s theories</b>?', '["<u>some variations are more favorable to existence in a given environment than others</u>","all living organisms are constantly involved in a struggle for existence","the size of a given population remains fairly constant","new species originate through the inheritance of acquired traits"]', '<u>Lamarck''s theory: favorable variations are inherited</u>.', null);
