insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4qem68yvp2gsyxlbyggs1py2', 'Chemistry', 'JAMB', null, 1991, null, 'Which of the following equilibria is <b>unaffected by a pressure change</b>?', null, '["2NaCl ⇌ 2Na + Cl2","H2 + I2 ⇌ 2HI","2O3 ⇌ 3O2","2NO2 ⇌ N2O4"]', 1, 'Equal gas moles on both sides → no pressure effect.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following equilibria is <b>unaffected by a pressure change</b>?', '["2NaCl ⇌ 2Na + Cl2","H2 + I2 ⇌ 2HI","2O3 ⇌ 3O2","2NO2 ⇌ N2O4"]', '<u>H2 + I2 ⇌ 2HI</u> (equal gas moles) is unaffected.', '{"bold":["unaffected by a pressure change"],"italic":[],"underline":["H2 + I2 ⇌ 2HI"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4qjmhuqkg3qjthitzgt95kbf', 'Islamic Religious Studies', 'JAMB', null, 2003, null, 'Taqrir, as a kind of Sunnah, means the', null, '["sayings of the Prophet (S.A.W) on religious matters","action or practice of the Prophet (S.A.W)","direct approach of the Prophet (S.A.W) to issues","Prophet''s (S.A.W) silent approval of the actions of others"]', 3, 'Taqrir refers to the Prophet''s silent approval of actions done in his presence.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Taqrir, as a kind of Sunnah, means the', '["sayings of the Prophet (S.A.W) on religious matters","action or practice of the Prophet (S.A.W)","direct approach of the Prophet (S.A.W) to issues","<u>Prophet''s (S.A.W) silent approval of the actions of others</u>"]', '<u>Taqrir</u> refers to the Prophet''s silent approval of actions.', '{"bold":[],"italic":[],"underline":["Prophet''s (S.A.W) silent approval of the actions of others"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4qkw0np8eczozv6wc8vd2go1', 'Chemistry', 'JAMB', null, 2024, null, 'Which of the following conducts electricity? I. Carbon(graphite) II. Carbon (diamond) III. S8 IV. P2O5', null, '["III only","I&III only","III & IV only","I only","I-III"]', 3, 'Graphite conducts electricity due to delocalized electrons; diamond, S8, and P2O5 do not.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following conducts electricity?<br>I. Carbon (graphite)<br>II. Carbon (diamond)<br>III. S8<br>IV. P2O5', '["III only","I&III only","III & IV only","<u>I only</u>","I-III"]', '<u>Graphite</u> conducts electricity due to delocalized electrons; diamond, S8, and P2O5 do not.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4qw0bl8bfqmg9tfhwed60gia', 'General Mathematics', 'JAMB', null, 2020, null, 'Find p if one root of x² - 6x + p = 0 is double the other.', null, '["6","8","9","12"]', 1, 'Roots α, 2α; 3α = 6 → α = 2; p = 2×4 = 8.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find p if one root of x² - 6x + p = 0 is double the other.', '["6","8","9","12"]', '<u>p = 8</u>.', '{"bold":[],"italic":[],"underline":["8"],"fillBlanks":[]}');
