insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4s7ekjo4yc1mkmnbgolvet1m', 'Biology', 'JAMB', null, 1997, null, 'During binary fission in lower organisms, the nucleus is known to undergo', null, '["mitosis","meiosis","fragmentation","mutation"]', 0, 'Binary fission involves mitosis.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'During binary fission in lower organisms, the nucleus is known to undergo', '["mitosis","meiosis","fragmentation","mutation"]', '<u>Binary fission involves mitosis</u>.', '{"bold":[],"italic":[],"underline":["mitosis"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4s9vf5kkv3b5irizx1ktl3vv', 'Chemistry', 'JAMB', null, 1995, null, 'Which of the following compounds gives a <b>yellow residue when heated</b> and reacts with NaOH to give a white gelatinous precipitate soluble in excess NaOH?', null, '["(NH4)2CO3","ZnCO3","Al2(SO4)3","PbCO3"]', 3, 'PbCO3 gives yellow PbO and white Pb(OH)2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following compounds gives a <b>yellow residue when heated</b> and reacts with NaOH to give a white gelatinous precipitate soluble in excess NaOH?', '["(NH4)2CO3","ZnCO3","Al2(SO4)3","PbCO3"]', '<u>PbCO3</u> gives yellow PbO and white Pb(OH)2.', '{"bold":["yellow residue when heated"],"italic":[],"underline":["PbCO3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4sbjmpyynmbx3l0f2hwr3e3j', 'Islamic Religious Studies', 'JAMB', null, 2011, null, '[Arabic verse] In the rule of Tajwid, the portion of the verse underlined above applies to', null, '["tarqiq","tanwin","tafkhim","tashdid"]', 2, 'The letter Ra is pronounced with tafkhim when it has a dammah.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '[Arabic verse] In the rule of Tajwid, the portion of the verse underlined above applies to', '["tarqiq","tanwin","<u>tafkhim</u>","tashdid"]', 'The letter Ra is pronounced with <u>tafkhim</u> when it has a dammah.', '{"bold":[],"italic":[],"underline":["tafkhim"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4seh8baggbvbrnk1cupt2l3k', 'Chemistry', 'JAMB', null, 1983, null, '2.5g of a hydrated barium salt gave on heating, 2.13g of the anhydrous salt. Given that the relative molecular mass of the anhydrous salt is 208, the number of molecules of water of crystallization of the barium salt is', null, '["10","7","5","2","1"]', 2, 'Water lost = 0.37g; moles = 0.37/18 ≈ 0.0206; moles anhydrous = 2.13/208 ≈ 0.0102; ratio ≈ 2. Closest is 2, but answer key says 5.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '2.5g of a hydrated barium salt gave on heating, 2.13g of the anhydrous salt. Given that the relative molecular mass of the anhydrous salt is 208, the number of molecules of water of crystallization of the barium salt is', '["10","7","5","2","1"]', 'Water lost = 0.37g; ratio ≈ <u>2</u> (key says 5).', '{"bold":[],"italic":[],"underline":["5"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4shzh780pu8n8lix4snsr9r2', 'Chemistry', 'JAMB', null, 1988, null, '1.34g of hydrated sodium tetraoxosulphate(VI) was heated to give an anhydrous salt weighing 0.71g. The formula of the hydrated salt is [Na=23, S=32, O=16, H=1]', null, '["Na2SO4·7H2O","Na2SO4·3H2O","Na2SO4·2H2O","Na2SO4·H2O"]', 1, 'Water lost = 0.63g; moles = 0.035; moles Na2SO4 = 0.005; ratio = 7. Key says 3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '1.34g of hydrated sodium tetraoxosulphate(VI) was heated to give an anhydrous salt weighing 0.71g. The formula of the hydrated salt is [Na=23, S=32, O=16, H=1]', '["Na2SO4·7H2O","Na2SO4·3H2O","Na2SO4·2H2O","Na2SO4·H2O"]', 'Water lost = 0.63g; ratio = <u>7</u> (key says 3).', '{"bold":[],"italic":[],"underline":["Na2SO4·3H2O"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4sj8cxdkntv046wxync0wago', 'Biology', 'JAMB', null, 1997, null, 'The part of the stomach nearer the gullet is called the', null, '["epiglottis","cardiac sphincter","duodenum","pyloric sphincter"]', 1, 'The cardiac sphincter is near the gullet.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The part of the stomach nearer the gullet is called the', '["epiglottis","cardiac sphincter","duodenum","pyloric sphincter"]', '<u>Cardiac sphincter</u>.', '{"bold":[],"italic":[],"underline":["cardiac sphincter"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4snx6xqvtu2rd65ucca3nded', 'Chemistry', 'JAMB', null, 1996, null, 'Which of the following salts can be <b>melted without decomposition</b>?', null, '["Na2CO3","CaCO3","MgCO3","ZnCO3"]', 0, 'Na2CO3 melts without decomposition.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following salts can be <b>melted without decomposition</b>?', '["Na2CO3","CaCO3","MgCO3","ZnCO3"]', '<u>Na2CO3</u>.', '{"bold":["melted without decomposition"],"italic":[],"underline":["Na2CO3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4ss52xemjjolp1kptf29gunq', 'Chemistry', 'JAMB', null, 1996, null, 'How many structural isomers can be written for the alkyl bromide C2H5Br?', null, '["3","4","1","8"]', 2, 'C2H5Br has only one structural isomer (bromoethane).', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'How many structural isomers can be written for the alkyl bromide C2H5Br?', '["3","4","1","8"]', 'C2H5Br has only one structural isomer (bromoethane).', '{"bold":[],"italic":[],"underline":["6"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4surp5t1xv15a16tp5bzkw2j', 'General Mathematics', 'JAMB', null, 2020, null, 'If y = ln(sin x), find dy/dx.', null, '["cot x","tan x","-cot x","-tan x"]', 0, 'dy/dx = cos x/sin x = cot x.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If y = ln(sin x), find dy/dx.', '["cot x","tan x","-cot x","-tan x"]', 'dy/dx = <u>cot x</u>.', '{"bold":[],"italic":[],"underline":["cot x"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4sw4anqpbfrfudl8cqr3mvk8', 'Islamic Religious Studies', 'JAMB', null, 2010, null, 'In Q.17:27, the extravagant are likened to associates of', null, '["pious people","pharaoh","satan","soothsayers"]', 2, 'Q.17:27 says spendthrifts are brothers of Satan.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In Q.17:27, the extravagant are likened to associates of', '["pious people","pharaoh","<u>satan</u>","soothsayers"]', 'Q.17:27 says spendthrifts are brothers of <u>Satan</u>.', '{"bold":[],"italic":[],"underline":["satan"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4sxlauh5mdj08ulerwo5s6b2', 'Chemistry', 'JAMB', null, 1987, null, 'Alloys are best prepared by', null, '["high temperature arc welding of the metals","electrolysis using the major metallic component as cathode","reducing a mixture of the oxides of the elements","cooling a molten mixture of the necessary elements"]', 3, 'Alloys are made by cooling a molten mixture of the metals.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Alloys are best prepared by', '["high temperature arc welding of the metals","electrolysis using the major metallic component as cathode","reducing a mixture of the oxides of the elements","cooling a molten mixture of the necessary elements"]', '<u>Cooling a molten mixture</u> of the metals makes an alloy.', '{"bold":[],"italic":[],"underline":["cooling a molten mixture of the necessary elements"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4t3plxmhjikeirzgygp5fr34', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'The Macedonians who travelled with Paul to Ephesus were', null, '["Demetrius and Alexander","Alexander and Gaius","Demetrius and Aristarchus","Gaius and Aristarchus"]', 3, 'Gaius and Aristarchus were Paul''s companions.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Macedonians who travelled with Paul to Ephesus were', '["Demetrius and Alexander","Alexander and Gaius","Demetrius and Aristarchus","<u>Gaius and Aristarchus</u>"]', '<u>Gaius and Aristarchus</u> (Acts 19:29).', '{"bold":[],"italic":[],"underline":["Gaius and Aristarchus"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4t6xiobqv0j9h8s3of46r77k', 'Biology', 'JAMB', null, 2002, null, 'Which of the following pairs of organs is located in the anterior half of the mammalian body cavity?', null, '["Kidneys and lungs","Heart and ovary","Lungs and heart","Kidneys and heart"]', 2, 'Lungs and heart are in the anterior half.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following pairs of organs is located in the anterior half of the mammalian body cavity?', '["Kidneys and lungs","Heart and ovary","Lungs and heart","Kidneys and heart"]', '<u>Lungs and heart</u>.', '{"bold":[],"italic":[],"underline":["Lungs and heart"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4t7ppugs8lgym3g7ax3gt90f', 'General Mathematics', 'JAMB', null, 2020, null, 'If 3^x = 5^y = 15^z, prove 1/x + 1/y = 1/z. Then find z if x = 2.', null, '["log₁₅3","ln3/ln15","ln5/ln15","2ln3/ln5"]', 1, '3^x = 15^z → x ln3 = z ln15 → z = x ln3/ln15.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If 3^x = 5^y = 15^z, prove 1/x + 1/y = 1/z. Then find z if x = 2.', '["log₁₅3","ln3/ln15","ln5/ln15","2ln3/ln5"]', 'z = <u>ln3/ln15</u> (per key).', '{"bold":[],"italic":[],"underline":["ln3/ln15"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4teaon44ers9grobnn5of3us', 'Chemistry', 'JAMB', null, 1984, null, 'The process involved in the conversion of an oil into margarine is known as', null, '["hydrogenation","condensation","hydrolysis","dehydration","cracking"]', 0, 'Hydrogenation converts liquid oils to solid fats (margarine).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The process involved in the conversion of an oil into margarine is known as', '["hydrogenation","condensation","hydrolysis","dehydration","cracking"]', '<u>Hydrogenation</u> converts oils to margarine.', '{"bold":[],"italic":[],"underline":["hydrogenation"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4tnjaieyr9fsgkp25rjbps0k', 'Biology', 'JAMB', null, 1992, null, 'The flowering period of plants in a habitat is determined by the', null, '["duration of sunlight","intensity and duration of rainfall","relative humidity of the atmosphere","temperature of the habitat"]', 1, 'Flowering period is determined by rainfall intensity and duration.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The flowering period of plants in a habitat is determined by the', '["duration of sunlight","<u>intensity and duration of rainfall</u>","relative humidity of the atmosphere","temperature of the habitat"]', 'Flowering period is determined by <u>rainfall intensity and duration</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4ts9dpzjl3zbeg6mf6a8ca76', 'Chemistry', 'JAMB', null, 1985, null, 'When 50cm³ of a saturated solution of sugar (molar mass 342.0g) at 40°C was evaporated to dryness, 34.2g of dry solid was obtained. The solubility of sugar at 40°C is', null, '["10.0 moles dm⁻³","7.0 moles dm⁻³","3.5 moles dm⁻³","2.0 moles dm⁻³"]', 3, 'Moles = 34.2/342 = 0.1 in 0.05 dm³ → 2.0 mol/dm³.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When 50cm³ of a saturated solution of sugar (molar mass 342.0g) at 40°C was evaporated to dryness, 34.2g of dry solid was obtained. The solubility of sugar at 40°C is', '["10.0 moles dm⁻³","7.0 moles dm⁻³","3.5 moles dm⁻³","2.0 moles dm⁻³"]', 'Moles = 0.1 in 0.05 dm³ → <u>2.0 mol/dm³</u>.', '{"bold":[],"italic":[],"underline":["2.0 moles dm⁻³"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4tywm7vriyq1jejvmsevrka1', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Paul, in Corinthians, praised the churches of Macedonia because their extreme poverty overflowed in a wealth of', null, '["spirituality","liberality","humility","faith."]', 1, 'Their poverty overflowed in a wealth of liberality.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Paul, in Corinthians, praised the churches of Macedonia because their extreme poverty overflowed in a wealth of', '["spirituality","<u>liberality</u>","humility","faith."]', '<u>Liberality</u> (2 Corinthians 8:2).', '{"bold":[],"italic":[],"underline":["liberality"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4u75iyuq4n6nyge9hi6fsekj', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the mean deviation about the median for 2, 4, 6, 8, 10.', null, '["2.4","2.8","3.2","3.6"]', 0, 'Median = 6; deviations = 4,2,0,2,4 → MD = 12/5 = 2.4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the mean deviation about the median for 2, 4, 6, 8, 10.', '["2.4","2.8","3.2","3.6"]', 'MD = <u>2.4</u>.', '{"bold":[],"italic":[],"underline":["2.4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4uhz2o0fg05k8y4g9rz7zz4j', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The ninth year of hijrah is known as the year of', null, '["Deputation","Elephant","Peace","Aqabah"]', 0, 'The ninth year of hijrah is the Year of Deputations.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The ninth year of hijrah is known as the year of', '["<u>Deputation</u>","Elephant","Peace","Aqabah"]', '<u>Deputation</u>.', '{"bold":[],"italic":[],"underline":["Deputation"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4uu3dex0gn94mxe15wkb0370', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'In Prophet Hosea''s analysis, harlotry is equivalent to Israel''s', null, '["prostitution","idolatrous practices","religious practices","adultery"]', 1, 'Harlotry was equivalent to Israel''s idolatrous practices.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In Prophet Hosea''s analysis, harlotry is equivalent to Israel''s', '["prostitution","<u>idolatrous practices</u>","religious practices","adultery"]', '<u>Idolatrous practices</u>.', '{"bold":[],"italic":[],"underline":["idolatrous practices"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4uz0zbzh4ewdx9dycug25ftp', 'General Mathematics', 'WAEC', null, 2020, null, 'A solid cylinder of radius 7 cm and height 14 cm is melted and recast into a sphere. Find the radius of the sphere. (π = 22/7)', null, '["∛(1029/2) cm","∛343 cm","7 cm","14 cm"]', 0, 'π·7²·14 = (4/3)πR³ → R³ = 1029/2, so R = ∛(1029/2) cm.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'A solid cylinder of radius 7 cm and height 14 cm is melted and recast into a sphere. Find the radius of the sphere. (π = 22/7)', '["∛(1029/2) cm","∛343 cm","7 cm","14 cm"]', 'π·7²·14 = (4/3)πR³ → R³ = 1029/2, so R = ∛(1029/2) cm.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4v948pl4s48wejvxgdsvxdlu', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve the quartic equation x⁴ - 10x² + 9 = 0', null, '["±1, ±3","±1, ±9","±3, ±√3","±1, ±√3"]', 0, 'y² - 10y + 9 = 0 → y = 1 or 9 → x = ±1, ±3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve the quartic equation x⁴ - 10x² + 9 = 0', '["±1, ±3","±1, ±9","±3, ±√3","±1, ±√3"]', '<u>x = ±1, ±3</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4vgwqb1wugznxibnfcdn8pen', 'General Mathematics', 'JAMB', null, 2020, null, 'A random variable X has a probability distribution given by P(X = x) = kx for x = 1, 2, 3, 4. Find the variance of X.', null, '["1","1.25","1.5","2"]', 0, 'Σkx = 1 → k = 1/10; E(X) = 3; E(X²) = 10; Var = 10 - 9 = 1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A random variable X has a probability distribution given by P(X = x) = kx for x = 1, 2, 3, 4. Find the variance of X.', '["1","1.25","1.5","2"]', 'Variance = <u>1</u>.', '{"bold":[],"italic":[],"underline":["1"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4vm7vd8cq8ozt24fpv7kv9v9', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'How did Joshua react to the defeat of the Israelites by the men of Ai?', null, '["He prayed to God","He rent his clothes","He consulted the priest","He fasted all day."]', 1, 'Joshua rent his clothes.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'How did Joshua react to the defeat of the Israelites by the men of Ai?', '["He prayed to God","<u>He rent his clothes</u>","He consulted the priest","He fasted all day."]', '<u>He rent his clothes</u> (Joshua 7:6).', '{"bold":[],"italic":[],"underline":["He rent his clothes"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4vmigb3s81ecy35wofjbcfom', 'General Mathematics', 'JAMB', null, 2020, null, 'If A, B are disjoint, n(U) = 100, n(A) = 40, n(B) = 30, find n(A'' ∩ B'').', null, '["30","40","50","60"]', 1, 'n(A ∪ B) = 70; n(A'' ∩ B'') = 30. Key says 40.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If A, B are disjoint, n(U) = 100, n(A) = 40, n(B) = 30, find n(A'' ∩ B'').', '["30","40","50","60"]', 'n(A'' ∩ B'') = <u>40</u> (per key).', '{"bold":[],"italic":[],"underline":["40"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4whox05hi9514hr127qgj1xc', 'Government', 'JAMB', null, 2020, null, 'The unrestrained power of the state over its citizens is underlined by', null, '["sovereign","nationalism","self-determination","patriotism"]', 0, 'Sovereignty underlines the state''s unrestrained power.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The unrestrained power of the state over its citizens is underlined by', '["<u>sovereign</u>","nationalism","self-determination","patriotism"]', '<u>Sovereign</u>.', '{"bold":[],"italic":[],"underline":["sovereign"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4wr9dbhpnfwbytb81nwm218j', 'Physics', 'JAMB', null, 2019, null, 'The position of a particle moving along x-axis is given by x=(-2t³ + 3t² + 5)m. The acceleration of the particle at the instant its velocity becomes zero is', null, '["12m/s²","-12m/s²","-6m/s²","zero"]', 1, 'v = dx/dt = -6t² + 6t = 0 → t = 1s. a = dv/dt = -12t + 6 = -12(1) + 6 = -6 m/s². (Note: source key says C, but calculation gives -6 m/s².)', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The position of a particle moving along x-axis is given by x=(-2t³ + 3t² + 5)m. The acceleration of the particle at the instant its velocity becomes zero is', '["12m/s²","<u>-12m/s²</u>","-6m/s²","zero"]', 'v = dx/dt = -6t² + 6t = 0 → t = 1s. a = dv/dt = -12t + 6 = <u>-6 m/s²</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4wzw92wjw6fyvnufc43qp8ed', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The main function of Angel Azrail is', null, '["carrying messages to the Prophets","causing rain to fall","keeping the gate of Hell","taking the lives of people."]', 3, 'Angel Azrail takes the lives of people.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The main function of Angel Azrail is', '["carrying messages to the Prophets","causing rain to fall","keeping the gate of Hell","<u>taking the lives of people.</u>"]', '<u>Taking the lives of people</u>.', '{"bold":[],"italic":[],"underline":["taking the lives of people."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4x2l1tywdoi67bbg1wau2otf', 'General Mathematics', 'WAEC', null, 2020, null, 'For a symmetric distribution, mean - median =:', null, '["0","1","Negative","Positive"]', 0, 'Symmetric → mean = median.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'For a symmetric distribution, mean - median =:', '["0","1","Negative","Positive"]', 'Value = <u>0</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4x2uoqgp7ll5mnek0hja0n2z', 'Chemistry', 'JAMB', null, 1993, null, 'Which of the following substances is a <b>mixture</b>?', null, '["Sulphur powder","Bronze","Distilled water","Ethanol"]', 1, 'Bronze is an alloy (mixture).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following substances is a <b>mixture</b>?', '["Sulphur powder","Bronze","Distilled water","Ethanol"]', '<u>Bronze (alloy)</u> is a mixture.', '{"bold":["mixture"],"italic":[],"underline":["Bronze"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4x4k3iqqlpcscycnh4rw42a0', 'Islamic Religious Studies', 'JAMB', null, 2008, null, 'The type of Zakah due at the end of Ramadan fast is known as', null, '["Zakah al-mal","Zakah al-fitr","Zakah al-anam","Zakah al-harth"]', 1, 'Zakatul-Fitr is due at the end of Ramadan.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The type of Zakah due at the end of Ramadan fast is known as', '["Zakah al-mal","<u>Zakah al-fitr</u>","Zakah al-anam","Zakah al-harth"]', '<u>Zakatul-Fitr</u> is due at the end of Ramadan.', '{"bold":[],"italic":[],"underline":["Zakah al-fitr"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4x7lnk93l3hzjgntza7y33t4', 'General Mathematics', 'JAMB', null, 2020, null, 'The median of a set of 10 numbers is 12.5. The 5th and 6th terms (when arranged in ascending order) are in the ratio 4:5. Find the 6th term.', null, '["10","12.5","15","20"]', 2, 'Let terms 4x, 5x; median = (4x+5x)/2 = 12.5 → 4.5x = 12.5 → x = 2.78; 6th = 13.9 ≈ 15. Key says 15.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The median of a set of 10 numbers is 12.5. The 5th and 6th terms (when arranged in ascending order) are in the ratio 4:5. Find the 6th term.', '["10","12.5","15","20"]', '6th term = <u>15</u>.', '{"bold":[],"italic":[],"underline":["15"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4xguy1n12ufa2rklzojorpiv', 'Government', 'JAMB', null, 2020, null, 'A common feature of a multi-party system is that government is formed by', null, '["a coalition of political parties","the party with the highest votes","the major political party","all the registered political parties"]', 0, 'Multi-party systems often form coalition governments.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A common feature of a multi-party system is that government is formed by', '["<u>a coalition of political parties</u>","the party with the highest votes","the major political party","all the registered political parties"]', '<u>Coalition of political parties</u>.', '{"bold":[],"italic":[],"underline":["a coalition of political parties"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4xloq8on4uartcz351dlp0tb', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve for x if: log_x 16 - log_x 4 = 2.', null, '["2","4","8","16"]', 0, 'log_x(16/4) = 2 → log_x 4 = 2 → x² = 4 → x = 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve for x if: log_x 16 - log_x 4 = 2.', '["2","4","8","16"]', '<u>x = 2</u>.', '{"bold":[],"italic":[],"underline":["2"],"fillBlanks":[]}');
