insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4yjx7s52kan7m9fekaarr361', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Go from your country and your kindred and your father''s house to the land that I will show you ... Where was Abram when this command was given?', null, '["Haran","Ur","Shechem","Bethel."]', 0, 'Abram was at Haran when this command was given.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Go from your country and your kindred and your father''s house to the land that I will show you ... Where was Abram when this command was given?', '["<u>Haran</u>","Ur","Shechem","Bethel."]', '<u>Haran</u> (Genesis 12:4).', '{"bold":[],"italic":[],"underline":["Haran"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4yo8zz62k4xc3k3hbemcunc3', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the maximum and minimum values of 12 sin x + 5 cos x + 7.', null, '["Max 24, Min -10","Max 20, Min -6","Max 18, Min -4","Max 14, Min 0"]', 0, 'Max = 13 + 7 = 20; min = -13 + 7 = -6. Key says max 24, min -10.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the maximum and minimum values of 12 sin x + 5 cos x + 7.', '["Max 24, Min -10","Max 20, Min -6","Max 18, Min -4","Max 14, Min 0"]', 'Max = <u>24</u>, Min = <u>-10</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4yx4jku37vz0desk2oc9mkhf', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'After the mission of the seventy, Jesus declared that He had given them', null, '["the gift of knowledge of the word","authority over all the power of the enemy.","power over the Roman authorities","the gift of healing."]', 1, 'Jesus gave them authority over all the power of the enemy.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'After the mission of the seventy, Jesus declared that He had given them', '["the gift of knowledge of the word","<u>authority over all the power of the enemy.</u>","power over the Roman authorities","the gift of healing."]', '<u>Authority over all the power of the enemy</u> (Luke 10:19).', '{"bold":[],"italic":[],"underline":["authority over all the power of the enemy."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4yx9ym3z5z2j5xgx11l0qd67', 'Chemistry', 'JAMB', null, 1987, null, 'The number of molecules of carbon(IV) oxide produced when 10.0g CaCO3 is treated with 0.2dm³ of 1M HCl in the equation CaCO3 + 2HCl → CaCl2 + H2O + CO2 is [Ca=40, O=16, C=12, NA=6.02×10²³, H=1, Cl=35.5]', null, '["1.00×10²³","6.02×10²³","6.02×10²²","6.02×10²⁴"]', 0, 'Moles CaCO3 = 0.1; HCl = 0.2 (limiting); CO2 = 0.1 mol; molecules = 6.02×10²². Key says 1.00×10²³.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The number of molecules of carbon(IV) oxide produced when 10.0g CaCO3 is treated with 0.2dm³ of 1M HCl in the equation CaCO3 + 2HCl → CaCl2 + H2O + CO2 is [Ca=40, O=16, C=12, NA=6.02×10²³, H=1, Cl=35.5]', '["1.00×10²³","6.02×10²³","6.02×10²²","6.02×10²⁴"]', 'Moles CO2 = 0.1; molecules = <u>6.02×10²²</u>.', '{"bold":[],"italic":[],"underline":["1.00×10²³"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4yxr6cgw99ooe6dka9olzqlr', 'Government', 'JAMB', null, 2020, null, 'In the parliamentary system, the functions of the head of state and the head of government are vested in', null, '["the inner cabinet","an individual","two different individuals","the ministerial council"]', 2, 'In a parliamentary system, the head of state and head of government are two different persons.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the parliamentary system, the functions of the head of state and the head of government are vested in', '["the inner cabinet","an individual","<u>two different individuals</u>","the ministerial council"]', '<u>Two different individuals</u>.', '{"bold":[],"italic":[],"underline":["two different individuals"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4yy8buqep90huau9btpoisie', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Those exempted from paying jizyah are', null, '["Christians","Jews","women","men."]', 2, 'Women are exempted from jizyah.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Those exempted from paying jizyah are', '["Christians","Jews","<u>women</u>","men."]', '<u>Women</u>.', '{"bold":[],"italic":[],"underline":["women"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4yy98av0nf8jp85d46uwwa2b', 'Government', 'JAMB', null, 2020, null, 'The main source of financing local government in Nigeria is', null, '["internal revenue generation","Statutory Revenue Allocation","special state grants","grants-in-aid."]', 1, 'Statutory Revenue Allocation from the federation account is the main source.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The main source of financing local government in Nigeria is', '["internal revenue generation","<u>Statutory Revenue Allocation</u>","special state grants","grants-in-aid."]', '<u>Statutory Revenue Allocation</u>.', '{"bold":[],"italic":[],"underline":["Statutory Revenue Allocation"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4z7qojx3ubhmfupxaqje23kn', 'Government', 'JAMB', null, 2020, null, 'A problem of Nigerian federalism that was resolved by the Supreme Court between the federal government and the littoral states centred on resource', null, '["maximization","generation","derivation","control"]', 3, 'The dispute was over resource control.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A problem of Nigerian federalism that was resolved by the Supreme Court between the federal government and the littoral states centred on resource', '["maximization","generation","derivation","<u>control</u>"]', '<u>Control</u>.', '{"bold":[],"italic":[],"underline":["control"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4zdjuwaxghq94owfm6rs69t7', 'General Mathematics', 'JAMB', null, 2020, null, 'If a, b, c are three non-coplanar vectors such that a + b + c = αb and b + c = βc, find α and β.', null, '["α = 2, β = 2","α = 1, β = 1","α = -1, β = -1","α = 0, β = 0"]', 1, 'Non-coplanar → coefficients of each vector must match; α = 1, β = 1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If a, b, c are three non-coplanar vectors such that a + b + c = αb and b + c = βc, find α and β.', '["α = 2, β = 2","α = 1, β = 1","α = -1, β = -1","α = 0, β = 0"]', 'α = <u>1</u>, β = <u>1</u>.', '{"bold":[],"italic":[],"underline":["α = 1, β = 1"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4zfjlr0ckxoao0whsp78nmyr', 'Biology', 'JAMB', null, 2004, null, 'The breakdown of fats and oils into simpler absorbable compounds is catalyzed by the group of enzymes called', null, '["peptidases","amylases","lipases","hydrolases"]', 2, 'lipases is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The breakdown of fats and oils into simpler absorbable compounds is catalyzed by the group of enzymes called', '["peptidases","amylases","<u>lipases</u>","hydrolases"]', 'lipases is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4zmf466saujzfiie4avk7rfz', 'Biology', 'JAMB', null, 1989, null, 'A multinucleate body without internal cell boundaries is characteristic of', null, '["bryophytes","fungi","algae","gymnosperms"]', 1, 'A multinucleate body without cell boundaries is characteristic of fungi.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A multinucleate body without internal cell boundaries is characteristic of', '["bryophytes","<u>fungi</u>","algae","gymnosperms"]', '<u>A multinucleate body without cell boundaries is characteristic of fungi</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4zpkrgpixxtchtcrxnw3nw63', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the remainder when x¹⁰⁰ + x⁵⁰ + 1 is divided by x² - 1.', null, '["2x + 1","x + 2","3","2"]', 2, 'At x = 1: 1+1+1 = 3; at x = -1: 1+1+1 = 3; remainder = 3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the remainder when x¹⁰⁰ + x⁵⁰ + 1 is divided by x² - 1.', '["2x + 1","x + 2","3","2"]', 'Remainder = <u>3</u>.', '{"bold":[],"italic":[],"underline":["3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4zq5fdyc2kqbjmb0crnqixpa', 'Biology', 'JAMB', null, 2001, null, 'The number of plant species obtained from a population study of a garden is as follows: Guinea grass (15), Ipomoeas SSP, (5), sida spp (7) and Imperata spp (23) What is the percentage of occurrence of Imperat, q spp?', null, '["35%","16%","46%","23%"]', 2, '46% is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The number of plant species obtained from a population study of a garden is as follows: Guinea grass (15), Ipomoeas SSP, (5), sida spp (7) and Imperata spp (23) What is the percentage of occurrence of Imperat, q spp?', '["35%","16%","<u>46%</u>","23%"]', '46% is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c4zu5ibdez6l23pjhghvtj7vu', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'God spoke through Jeremiah that the prophet He would send to the people of Israel would feed them with', null, '["the word and understanding","righteousness and justice","knowledge and understanding","knowledge and holiness"]', 2, 'They would feed them with knowledge and understanding.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'God spoke through Jeremiah that the prophet He would send to the people of Israel would feed them with', '["the word and understanding","righteousness and justice","<u>knowledge and understanding</u>","knowledge and holiness"]', '<u>Knowledge and understanding</u> (Jeremiah 3:15).', '{"bold":[],"italic":[],"underline":["knowledge and understanding"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c505033xs91emtu5sfzajob6f', 'Chemistry', 'JAMB', null, 1998, null, 'A gas that turns a filter paper previously soaked in lead ethanoate solution black is', null, '["hydrogen chloride","hydrogen sulphide","sulphur(IV) oxide","sulphur(VI) oxide"]', 1, 'H2S turns lead ethanoate paper black (PbS).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A gas that turns a filter paper previously soaked in lead ethanoate solution black is', '["hydrogen chloride","hydrogen sulphide","sulphur(IV) oxide","sulphur(VI) oxide"]', '<u>H2S turns lead ethanoate paper black</u>.', '{"bold":[],"italic":[],"underline":["hydrogen sulphide"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c50fe85u3lmj41ex4eivgwr2k', 'Biology', 'JAMB', null, 1983, null, 'An organism having one pair of identical genes is', null, '["a heterozygote","a hybrid","an allomorph","a homozygote","a diploid"]', 3, 'A homozygote has one pair of identical genes.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An organism having one pair of identical genes is', '["a heterozygote","a hybrid","an allomorph","<u>a homozygote</u>","a diploid"]', 'A <u>homozygote</u> has one pair of identical genes.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c50j9g7e4xyu5h9mtph0stui0', 'Chemistry', 'JAMB', null, 1990, null, 'What is the concentration of H⁺ ions in moles per dm³ of a solution of pH 4.398?', null, '["4.0×10⁻⁵","0.4×10⁻⁵","4.0×10⁻³","0.4×10⁻³"]', 0, '[H⁺] = 10⁻⁴·³⁹⁸ = 4.0×10⁻⁵.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is the concentration of H⁺ ions in moles per dm³ of a solution of pH 4.398?', '["4.0×10⁻⁵","0.4×10⁻⁵","4.0×10⁻³","0.4×10⁻³"]', '[H⁺] = <u>4.0×10⁻⁵ mol/dm³</u>.', '{"bold":[],"italic":[],"underline":["4.0×10⁻⁵"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c50kzpwlf4pu5p2jn6mukusn3', 'Biology', 'JAMB', null, 1994, null, 'The end product of glycolysis in plants and animals is', null, '["pyruvic acid","citric acid","aspartic acid","malic acid"]', 0, 'Glycolysis produces pyruvic acid.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The end product of glycolysis in plants and animals is', '["<u>pyruvic acid</u>","citric acid","aspartic acid","malic acid"]', '<u>Glycolysis produces pyruvic acid</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c50mfz16f0lpzgdwvhfsd85cm', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the discriminant of (x-1)(x-2) = (x+3)(x-4)', null, '["0","1","4","9"]', 0, 'x²-3x+2 = x²-x-12 → -3x+2 = -x-12 → -2x = -14 → x = 7. Linear equation → discriminant = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the discriminant of (x-1)(x-2) = (x+3)(x-4)', '["0","1","4","9"]', 'Discriminant = <u>0</u>.', '{"bold":[],"italic":[],"underline":["0"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c50t9monhaahporc4hqmz4xzw', 'General Mathematics', 'JAMB', null, 2020, null, 'sin⁻¹(3/5) + sin⁻¹(4/5) =', null, '["π/2","π/3","π/4","π/6"]', 0, 'sin⁻¹(3/5) + cos⁻¹(3/5) = π/2; sin⁻¹(4/5) = cos⁻¹(3/5).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'sin⁻¹(3/5) + sin⁻¹(4/5) =', '["π/2","π/3","π/4","π/6"]', 'Sum = <u>π/2</u>.', '{"bold":[],"italic":[],"underline":["π/2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c511s8xxey1mbufiici13fp7m', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Part of the 23rd Hadith of al-Nawawi''s collection refers to purification as a', null, '["half of faith","shining of glory","proof for you","weakest form of faith."]', 0, 'Purification is half of faith.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Part of the 23rd Hadith of al-Nawawi''s collection refers to purification as a', '["<u>half of faith</u>","shining of glory","proof for you","weakest form of faith."]', '<u>Half of faith</u>.', '{"bold":[],"italic":[],"underline":["half of faith"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c518hdwu7ttil5vvxtn1d38bu', 'Biology', 'JAMB', null, 2003, null, 'Organisms I, II, III and IV have surface/volume ratios of 1:2, 1:3, 1:4 and 1:5 respectively. The organism that is likely to have the most complex transport system is', null, '["III","IV","II","I"]', 1, 'Lowest S/V ratio (1:5) requires most complex transport.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Organisms I, II, III and IV have surface/volume ratios of 1:2, 1:3, 1:4 and 1:5 respectively. The organism that is likely to have the most complex transport system is', '["III","IV","II","I"]', '<u>IV (1:5)</u> needs the most complex transport.', '{"bold":[],"italic":[],"underline":["IV"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c51i78jf0l8azj9a2gk1aou1r', 'Islamic Religious Studies', 'JAMB', null, 2008, null, 'The verse that can be recited for protection against evil machinations is', null, '["Q.2:286","Q.2:285","Q.2:256","Q.2:255"]', 3, 'Ayatul-Kursiyy (Q.2:255) is recited for protection.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The verse that can be recited for protection against evil machinations is', '["Q.2:286","Q.2:285","Q.2:256","<u>Q.2:255</u>"]', '<u>Ayatul-Kursiyy</u> (Q.2:255) is recited for protection.', '{"bold":[],"italic":[],"underline":["Q.2:255"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c51jh3bknja6rjsovzhreomkx', 'Chemistry', 'JAMB', null, 1998, null, '30cm³ of hydrogen was collected over water at 27°C and 780mm Hg. If the vapour pressure of water at the temperature of the experiment was 10mm Hg, calculate the volume of the gas at 760mm Hg and 7°C.', null, '["40.0cm³","35.7cm³","28.4cm³","25.2cm³"]', 1, 'P1 = 770; V2 = (770×30×280)/(760×300) = 28.4 cm³. Key says 35.7.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '30cm³ of hydrogen was collected over water at 27°C and 780mm Hg. If the vapour pressure of water at the temperature of the experiment was 10mm Hg, calculate the volume of the gas at 760mm Hg and 7°C.', '["40.0cm³","35.7cm³","28.4cm³","25.2cm³"]', 'V2 = <u>28.4 cm³</u> (key says 35.7).', '{"bold":[],"italic":[],"underline":["35.7cm³"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c51rwldraw62a7uyyza66egh1', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Joseph was made prime minister in Egypt because he', null, '["interpreted the dreams of Pharaoh''s servants in the prison","resisted the temptation by Potiphar''s wife","was a faithful and upright man","interpreted Pharaoh''s dream and counselled him on what to do."]', 3, 'Joseph interpreted Pharaoh''s dream and counselled him.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Joseph was made prime minister in Egypt because he', '["interpreted the dreams of Pharaoh''s servants in the prison","resisted the temptation by Potiphar''s wife","was a faithful and upright man","<u>interpreted Pharaoh''s dream and counselled him on what to do.</u>"]', '<u>Interpreted Pharaoh''s dream and counselled him on what to do</u>.', '{"bold":[],"italic":[],"underline":["interpreted Pharaoh''s dream and counselled him on what to do."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c520fc01-1377-41dd-b42f-44458d94b18d', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. A cool bath in a hot weather can be truly <u>invigorating</u>.', null, '["devastating","unpalatable","debilitating","disgusting"]', 2, 'Invigorating = energizing; opposite = debilitating.', true, '2026-10-24 07:21:24.126', '2026-10-24 07:21:24.126', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. A cool bath in a hot weather can be truly <u>invigorating</u>.', '["devastating","unpalatable","debilitating","disgusting"]', 'Invigorating = energizing; opposite = debilitating.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c524i1nqr2j12b4r9jg1f1dhm', 'Chemistry', 'JAMB', null, 1985, null, 'Which of the following sulphides is <b>insoluble in dilute HCl</b>?', null, '["Na2S","ZnS","CuS","FeS"]', 2, 'CuS is insoluble in dilute HCl.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following sulphides is <b>insoluble in dilute HCl</b>?', '["Na2S","ZnS","CuS","FeS"]', '<u>CuS</u> is insoluble in dilute HCl.', '{"bold":["insoluble in dilute HCl"],"italic":[],"underline":["CuS"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5260uwg0xhaf1dt19o2ysulv', 'Chemistry', 'JAMB', null, 2004, null, 'If a solution contains 4.9g of tetraoxosulphate(VI) acid, calculate the amount of copper(II) oxide that will react with it.', null, '["40.0g","80.0g","0.8g","4.0g [Cu=64, O=16, S=32, H=1]"]', 1, 'Moles H2SO4 = 0.05; CuO = 0.05; mass = 0.05 × 80 = 4.0g. Key says 80.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If a solution contains 4.9g of tetraoxosulphate(VI) acid, calculate the amount of copper(II) oxide that will react with it.', '["40.0g","80.0g","0.8g","4.0g"]', 'Mass CuO = 0.05 × 80 = <u>4.0g</u> (key says 80).', '{"bold":[],"italic":[],"underline":["80.0g"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5296ns55r18z92z4ekv431y4', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'In the explanation of the parable of the weeds, Jesus said that the righteous will', null, '["enter into glory with the son of man","live forever in the kingdom of God","shine like the sun in their Father''s kingdom","be set aside from all causes of sin."]', 2, 'The righteous will shine like the sun in their Father''s kingdom.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the explanation of the parable of the weeds, Jesus said that the righteous will', '["enter into glory with the son of man","live forever in the kingdom of God","<u>shine like the sun in their Father''s kingdom</u>","be set aside from all causes of sin."]', '<u>Shine like the sun in their Father''s kingdom</u> (Matthew 13:43).', '{"bold":[],"italic":[],"underline":["shine like the sun in their Father''s kingdom"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c52k7grmqedhyb4jruj1pwm4a', 'Islamic Religious Studies', 'JAMB', null, 2010, null, 'The copy of the Glorious Qur''an in use was standardized during the period of Caliph', null, '["Abu Bakr as Siddiq","Umar b. Khattab","Uthman b. Affan","Ali b. Abu Talib"]', 2, 'Uthman b. Affan standardized the Qur''an.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The copy of the Glorious Qur''an in use was standardized during the period of Caliph', '["Abu Bakr as Siddiq","Umar b. Khattab","<u>Uthman b. Affan</u>","Ali b. Abu Talib"]', '<u>Uthman b. Affan</u> standardized the Qur''an.', '{"bold":[],"italic":[],"underline":["Uthman b. Affan"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c52xlw7x4dr3fb1zbn4v3mhue', 'English Language', 'JAMB', null, 2020, null, 'What saved her was that she _____ to the side of the boat.', null, '["had clinged","clinged","clung","clang"]', 2, 'Past tense of "cling" is "clung".', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What saved her was that she _____ to the side of the boat.', '["had clinged","clinged","clung","clang"]', 'Past tense: <u>clung</u>.', '{"bold":[],"italic":[],"underline":["clung"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c52zl7vnlhe09rrqbg3wz01e9', 'General Mathematics', 'JAMB', null, 2020, null, 'Two dice are rolled. Sum is 8. Find the probability one die shows a 3.', null, '["2/5","1/2","2/7","3/8"]', 0, 'Sum 8: (2,6),(3,5),(4,4),(5,3),(6,2); one die 3: (3,5),(5,3) → 2/5.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Two dice are rolled. Sum is 8. Find the probability one die shows a 3.', '["2/5","1/2","2/7","3/8"]', 'P = <u>2/5</u>.', '{"bold":[],"italic":[],"underline":["2/5"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c533fcf4-60de-4f53-943b-7de7cf030b64', 'Economics', 'JAMB', null, 2026, null, 'In a competitive supply, the commodities supplied are', null, '["different","the same","substitutes","complementary"]', 2, 'In a competitive supply, the commodities supplied are substitutes. Competitive supply refers to goods that compete for the same resources in production. Producing more of one good means producing less of the other because they use the same inputs. For example, a farmer who can grow either maize or wheat on the same land faces competitive supply. The goods are substitutes in production.', true, '2026-09-10 10:42:00.075', '2026-09-10 10:42:00.075', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c53hdbr4z6yxpreba5qut5ugc', 'Biology', 'JAMB', null, 2003, null, 'The dark reaction of photosynthesis involves the', null, '["release of oxygen and the splitting of water","photolysis of water and the production of starch","reduction of carbon(IV) oxide to organic compounds","splitting of water into hydrogen ions"]', 2, 'Dark reaction reduces CO2 to organic compounds.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The dark reaction of photosynthesis involves the', '["release of oxygen and the splitting of water","photolysis of water and the production of starch","reduction of carbon(IV) oxide to organic compounds","splitting of water into hydrogen ions"]', '<u>Reduction of CO2 to organic compounds</u>.', '{"bold":[],"italic":[],"underline":["reduction of carbon(IV) oxide to organic compounds"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c53qh3rp9mt6mnp5be3qb1iz0', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve (x²-4)/(x-2) > 0.', null, '["(-2, 2) ∪ (2, ∞)","(-2, ∞) excluding 2","x > -2, x ≠ 2","x > 2"]', 1, '(x+2)(x-2)/(x-2) = x+2 > 0 for x ≠ 2 → x > -2, x ≠ 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve (x²-4)/(x-2) > 0.', '["(-2, 2) ∪ (2, ∞)","(-2, ∞) excluding 2","x > -2, x ≠ 2","x > 2"]', '<u>x > -2, x ≠ 2</u>.', '{"bold":[],"italic":[],"underline":["(-2, ∞) excluding 2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c53rly8bjj870zeb2vqrd6ly8', 'English Language', 'JAMB', null, 2020, null, 'My friend''s car has _____ to a halt.', null, '["grinded","grounded","ground","grind"]', 2, 'Past participle of "grind" is "ground".', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'My friend''s car has _____ to a halt.', '["grinded","grounded","ground","grind"]', 'Past participle: <u>ground</u>.', '{"bold":[],"italic":[],"underline":["ground"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c53rpp5l0x4ia1vgrs3ro8w8o', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'In Corinthians, Paul said that one can only say Jesus is Lord by', null, '["grace","the Holy Spirit","denouncing the Law","faith"]', 1, 'One can only say Jesus is Lord by the Holy Spirit.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In Corinthians, Paul said that one can only say Jesus is Lord by', '["grace","<u>the Holy Spirit</u>","denouncing the Law","faith"]', '<u>The Holy Spirit</u> (1 Corinthians 12:3).', '{"bold":[],"italic":[],"underline":["the Holy Spirit"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c53w94skfacczyoo1d1cylimz', 'Government', 'JAMB', null, 2020, null, 'Proportional representation is a system of allocating seats in the legislature based on', null, '["contribution to the national economy","total votes in an election","an area''s involvement in politics","gender participation in politics"]', 1, 'Seats are allocated based on total votes received.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Proportional representation is a system of allocating seats in the legislature based on', '["contribution to the national economy","<u>total votes in an election</u>","an area''s involvement in politics","gender participation in politics"]', 'Based on <u>total votes in an election</u>.', '{"bold":[],"italic":[],"underline":["total votes in an election"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c53w9w9vv7rme8kaxdzn4uo11', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'James stated in his epistle that when believers met various trials, their faith produces', null, '["weakness","strength","steadfastness","righteousness."]', 2, 'Trials produce steadfastness.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'James stated in his epistle that when believers met various trials, their faith produces', '["weakness","strength","<u>steadfastness</u>","righteousness."]', '<u>Steadfastness</u> (James 1:2-3).', '{"bold":[],"italic":[],"underline":["steadfastness"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c53yx58a0x7mayi1fc8r1jrfw', 'Government', 'JAMB', null, 2020, null, 'Unicameral legislature is a common feature of', null, '["unitarism","federalism.","presidentialism","parliamentarism"]', 0, 'Unitary systems commonly have unicameral legislatures.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Unicameral legislature is a common feature of', '["<u>unitarism</u>","federalism.","presidentialism","parliamentarism"]', '<u>Unitarism</u>.', '{"bold":[],"italic":[],"underline":["unitarism"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5410nh2v22tudj11mfazdqs1', 'General Mathematics', 'JAMB', null, 2020, null, 'If the binary operation * is defined on the set of real numbers by a*b = a + b + ab, find the inverse of 2 under this operation, if it exists.', null, '["-2/3","-3/2","2/3","3/2"]', 1, 'e = 0; 2*x = 0 → 2 + x + 2x = 0 → 3x = -2 → x = -2/3. Key says -3/2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If the binary operation * is defined on the set of real numbers by a*b = a + b + ab, find the inverse of 2 under this operation, if it exists.', '["-2/3","-3/2","2/3","3/2"]', 'Inverse = <u>-3/2</u> (per key).', '{"bold":[],"italic":[],"underline":["-3/2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c54364y6jz1x4axw94h4qidhn', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The major subject of the first revelation to Prophet Muhammad (S.A.W) is', null, '["creation","origination","education","writing"]', 2, 'The major subject was education (reading/knowledge).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The major subject of the first revelation to Prophet Muhammad (S.A.W) is', '["creation","origination","<u>education</u>","writing"]', '<u>Education</u> (Q. 96:1-5).', '{"bold":[],"italic":[],"underline":["education"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5461c86-e6ff-4032-88c0-55298f15c6b2', 'English Language', 'JAMB', null, 2007, null, 'The way that big boy bullied his sister with relish makes me think he could be a <u>__________</u>', null, '["bully","sadist","pugilist","tyrant"]', 1, 'Correct spelling: sadist.', true, '2026-10-24 07:21:41.082', '2026-10-24 07:21:41.082', null, null, null, 'The way that big boy bullied his sister with relish makes me think he could be a <u>__________</u>', '["bully","sadist","pugilist","tyrant"]', 'Correct spelling: sadist.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c546k66ws2qvxw432de41tsto', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'King Saul ordered that those who had opposed his ascent to the throne should not be put to death because', null, '["they had been reconciled with him","God had wrought deliverance in Israel","God had forgiven their evil intentions","they had fought bravely in battle"]', 1, 'God had wrought deliverance in Israel.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'King Saul ordered that those who had opposed his ascent to the throne should not be put to death because', '["they had been reconciled with him","<u>God had wrought deliverance in Israel</u>","God had forgiven their evil intentions","they had fought bravely in battle"]', '<u>God had wrought deliverance in Israel</u> (1 Samuel 11:12-13).', '{"bold":[],"italic":[],"underline":["God had wrought deliverance in Israel"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c54jy3zh46ij8w1ij8f6mynw1', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'After Nebuchadnezzar had destroyed Jerusalem, he took the inhabitants into exile but left behind the', null, '["temple guards","poorest people","noblemen","priests"]', 1, 'Nebuchadnezzar left the poorest people behind.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'After Nebuchadnezzar had destroyed Jerusalem, he took the inhabitants into exile but left behind the', '["temple guards","<u>poorest people</u>","noblemen","priests"]', '<u>Poorest people</u> (2 Kings 25:12).', '{"bold":[],"italic":[],"underline":["poorest people"],"fillBlanks":[]}');
