insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c54z0cze6tsp8a4b0g52ruru3', 'Biology', 'JAMB', null, 1988, null, 'Which of these groups of animals is likely to be found in fresh water?', null, '["Blood worm, pond skater and scorpion","Blood worm, pond skater and dragonfly larva","Pond skates scorpion and dragonfly larva","Pond skater, blood worm and ant-lion"]', 1, 'Blood worm, pond skater, and dragonfly larva live in fresh water.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of these groups of animals is likely to be found in fresh water?', '["Blood worm, pond skater and scorpion","<u>Blood worm, pond skater and dragonfly larva</u>","Pond skates scorpion and dragonfly larva","Pond skater, blood worm and ant-lion"]', '<u>Blood worm, pond skater, and dragonfly larva</u> live in fresh water.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c54zmu29pen7rz1z3rl7nplkh', 'Biology', 'JAMB', null, 1991, null, 'Substances manufactured by the leaves are transported to other parts of the plant through the', null, '["xylem","companion cells","sieve tubes","cambium"]', 2, 'Substances are transported through sieve tubes.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Substances manufactured by the leaves are transported to other parts of the plant through the', '["xylem","companion cells","<u>sieve tubes</u>","cambium"]', 'Substances are transported through <u>sieve tubes</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c555v5dzqhfoe4galdcjtxrtg', 'General Mathematics', 'WAEC', null, 2020, null, 'If log_a(bc) = x, log_b(ca) = y and log_c(ab) = z, find 1/(x + 1) + 1/(y + 1) + 1/(z + 1).', null, '["0","1","2","3"]', 1, 'Identity: sum = 1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If log_a(bc) = x, log_b(ca) = y and log_c(ab) = z, find 1/(x + 1) + 1/(y + 1) + 1/(z + 1).', '["0","1","2","3"]', 'Sum = <u>1</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c557134f-c89e-4a15-b8d1-aa23cae3d287', 'English Language', 'JAMB', null, 2024, null, 'Choose the appropriate stress: matriculate', null, '["ma-tri-CU-late","ma-TRI-cu-late","MA-tri-cu-late","ma-tri-cu-LATE"]', 0, 'The stress in "matriculate" is on the third syllable: ma-tri-CU-late.', true, '2026-09-18 09:43:02.66', '2026-09-18 09:43:02.66', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c55drtsijkp6huczro6di6hrj', 'Islamic Religious Studies', 'JAMB', null, 2003, null, 'The Prophet (S.A.W) says: ''If one of you takes rope (goes to the bush) and comes back with a bunch of firewood, sells it ... is better than begging for alms ...'' The Hadith above focuses on', null, '["Dedication to service","dignity of labour","decent living","Muslim responsibility"]', 1, 'The Hadith emphasizes the dignity of labour over begging.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Prophet (S.A.W) says: ''If one of you takes rope (goes to the bush) and comes back with a bunch of firewood, sells it ... is better than begging for alms ...'' The Hadith above focuses on', '["Dedication to service","<u>dignity of labour</u>","decent living","Muslim responsibility"]', 'The Hadith emphasizes the <u>dignity of labour</u> over begging.', '{"bold":[],"italic":[],"underline":["dignity of labour"],"fillBlanks":[]}');
