insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c55p7kjx99b16wzft0738f1uz', 'Biology', 'JAMB', null, 1993, null, 'Which of the following organs or cell components are common to both the sporophyte and the gametophyte of a fern?', null, '["Rhizoids","Roots","Chloroplasts","Leaves"]', 2, 'Both sporophyte and gametophyte of a fern have chloroplasts.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following organs or cell components are common to both the sporophyte and the gametophyte of a fern?', '["Rhizoids","Roots","<u>Chloroplasts</u>","Leaves"]', 'Both sporophyte and gametophyte of a fern have <u>chloroplasts</u>.', null);
