insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c56a9b27-d57a-4fa7-81c5-35b90fc4b53a', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The chief will <u>launch</u> the fund-raising appeal.', null, '["make a speech at","eat his afternoon meal during","travel by boat to","start off"]', 3, 'Launch = start off.', true, '2026-10-24 01:01:44.794', '2026-10-24 01:01:44.794', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The chief will <u>launch</u> the fund-raising appeal.', '["make a speech at","eat his afternoon meal during","travel by boat to","<u>start off</u>"]', '<b>Launch</b> = <b>start off</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c56dsvod0hqov3xc21mq7ctjc', 'Chemistry', 'JAMB', null, 1988, null, 'The molar ratio of oxygen to nitrogen in dissolved air is 2:1 whereas the ratio is 4:1 in atmospheric air because', null, '["nitrogen is less soluble than oxygen","oxygen is heavier than nitrogen","nitrogen has a higher partial pressure in air","gases are hydrated in water"]', 0, 'Oxygen is more soluble in water than nitrogen, so dissolved air is richer in O2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The molar ratio of oxygen to nitrogen in dissolved air is 2:1 whereas the ratio is 4:1 in atmospheric air because', '["nitrogen is less soluble than oxygen","oxygen is heavier than nitrogen","nitrogen has a higher partial pressure in air","gases are hydrated in water"]', '<u>Oxygen is more soluble in water</u> than nitrogen.', '{"bold":[],"italic":[],"underline":["nitrogen is less soluble than oxygen"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c56mnzj4pryke4p8odtbwuc44', 'Chemistry', 'JAMB', null, 1985, null, 'Which of the following is <b>NOT correct</b> for the named organic compound in each case?', null, '["Butanoic acid solution gives effervescence with Na2CO3 solution","Glucose when reacted with Na2CrO4 at 0°C will show immediate discharge of colour","When but-2-ene is reacted with dilute KMnO4 the purple colour is discharged readily even at room temperature","When butan-2-ol is boiled with butanoic acid with a drop of concentrated H2SO4 a sweet smelling liquid is produced"]', 1, 'Glucose does not discharge Na2CrO4 colour at 0°C.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is <b>NOT correct</b> for the named organic compound in each case?', '["Butanoic acid solution gives effervescence with Na2CO3 solution","Glucose when reacted with Na2CrO4 at 0°C will show immediate discharge of colour","When but-2-ene is reacted with dilute KMnO4 the purple colour is discharged readily even at room temperature","When butan-2-ol is boiled with butanoic acid with a drop of concentrated H2SO4 a sweet smelling liquid is produced"]', '<u>Glucose does not discharge Na2CrO4 colour at 0°C</u>.', '{"bold":["NOT correct"],"italic":[],"underline":["Glucose when reacted with Na2CrO4 at 0°C will show immediate discharge of colour"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c56pv8frogmspkvq4deo4hrsv', 'General Mathematics', 'JAMB', null, 2020, null, 'If A = [[1, 2], [3, 4]], find (A⁻¹)ᵀ.', null, '["½[[-4,3],[2,-1]]","½[[-4,2],[3,-1]]","½[[4,-2],[-3,1]]","½[[4,-3],[-2,1]]"]', 3, 'A⁻¹ = ½[[4,-2],[-3,1]]; transpose = ½[[4,-3],[-2,1]].', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If A = [[1, 2], [3, 4]], find (A⁻¹)ᵀ.', '["½[[-4,3],[2,-1]]","½[[-4,2],[3,-1]]","½[[4,-2],[-3,1]]","½[[4,-3],[-2,1]]"]', '(A⁻¹)ᵀ = <u>½[[4,-3],[-2,1]]</u>.', '{"bold":[],"italic":[],"underline":["½[[4,-3],[-2,1]]"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c56qphml5uqmsdfgciwn3hmop', 'Chemistry', 'JAMB', null, 2024, null, 'Blood sample can be separated by I. Chromatography II. Centrifugation III. Crystallization IV. Fractional distillation', null, '["I-IV","II only","I&III only","I only","I&II only"]', 1, 'Blood samples are separated by centrifugation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Blood sample can be separated by<br>I. Chromatography<br>II. Centrifugation<br>III. Crystallization<br>IV. Fractional distillation', '["I-IV","<u>II only</u>","I&III only","I only","I&II only"]', 'Blood samples are separated by <u>centrifugation</u>.', null);
