insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c57ec490-1982-4dcf-baf9-cbc1b637fc20', 'Government', 'JAMB', null, 2026, null, 'The civil war started on _ and was led by _', null, '["Jan 1, 1966, Maj. Gen. Ojukwu","May 30, 1976, Lt. Col. Ojukwu","July 1, 1967, Lt. Col. Ojukwu","June 1, 1967, Lt. Col. Ojukwu"]', 2, 'The Nigerian Civil War started on July 1, 1967, and was led by Lt. Col. Chukwuemeka Odumegwu Ojukwu. The war began after the Eastern Region declared independence as the Republic of Biafra on May 30, 1967. The first shot was fired on July 1, 1967. The war ended in January 1970 with the defeat of Biafra. Ojukwu was the leader of the secessionist state.', true, '2026-09-10 10:45:05.983', '2026-09-10 10:45:05.983', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c57f45t8fd2qs6v1t38uejfw5', 'Chemistry', 'JAMB', null, 1993, null, 'The carbon atoms in ethane are', null, '["sp³ hybridized","sp³ hybridized","sp³ hybridized","sp hybridized"]', 0, 'Ethane carbons are sp³ hybridized.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The carbon atoms in ethane are', '["sp³ hybridized","sp³ hybridized","sp³ hybridized","sp hybridized"]', '<u>sp³ hybridized</u>.', '{"bold":[],"italic":[],"underline":["sp³ hybridized"],"fillBlanks":[]}');
