insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5854143-1a87-492d-8d10-38fcb187d9c9', 'Literature in English', 'JAMB', null, 2026, null, 'The journey motif in the novel primarily functions as a', null, '["Literal movement without symbolic implication","Representation of political instability in society","Metaphor for personal growth, endurance, and self-discovery","Device for introducing minor characters only"]', 2, 'The journey motif is a metaphor for personal growth, endurance, and self-discovery.', true, '2026-09-12 11:12:02.117', '2026-09-12 11:12:02.117', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5875xt5sl6t1wrodn5xu3lry', 'Biology', 'JAMB', null, 1986, null, 'If a woman who is a carrier of sickle cell trait (AS) married a man who is a sickler (SS) and they had four children how many of them would be normal', null, '["Three","Two","One","None"]', 3, 'None of the children would be normal (AA).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If a woman who is a carrier of sickle cell trait (AS) married a man who is a sickler (SS) and they had four children how many of them would be normal', '["Three","Two","One","<u>None</u>"]', '<u>None</u> of the children would be normal (AA).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c58ee3xk41e4mm6ty4tf5ke8k', 'Chemistry', 'JAMB', null, 1985, null, 'How many electrons are transferred in reducing one atom of Mn in the reaction MnO2 + 4HCl → MnCl2 + 2H2O + Cl2?', null, '["2","3","4","5"]', 0, 'Mn goes from +4 to +2, gaining 2 electrons.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'How many electrons are transferred in reducing one atom of Mn in the reaction MnO2 + 4HCl → MnCl2 + 2H2O + Cl2?', '["2","3","4","5"]', 'Mn goes from +4 to +2, <u>gaining 2 electrons</u>.', '{"bold":[],"italic":[],"underline":["2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c58n1dexs7hejdg5njh9telzo', 'Chemistry', 'JAMB', null, 1999, null, 'During Bromination, how many molecules of bromine is used ', null, '["I only","III only","I and II only","II and III only"]', 1, 'Compound III (with triple bond) takes up 2 Br2.', true, '2026-10-11 07:17:11.699', '2026-10-24 07:30:25.634', null, null, null, 'Which of the compounds above would react to take up two molecules of bromine during bromination?', '["I only","III only","I and II only","II and III only"]', '<u>Compound III</u> takes up 2 Br2.', '{"bold":[],"italic":[],"underline":["III only"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c58nl7knnbs4yvjhdo0ektixa', 'Chemistry', 'JAMB', null, 1996, null, 'A sample of a gas exerts a pressure of 8.2 atm when confined in a 2.93dm³ container at 20°C. The number of moles of gas in the sample is [R=0.082 litre atm/deg mole]', null, '["1.00","2.00","3.00","4.00"]', 0, 'n = PV/RT = (8.2 × 2.93)/(0.082 × 293) = 1.00 mol.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A sample of a gas exerts a pressure of 8.2 atm when confined in a 2.93dm³ container at 20°C. The number of moles of gas in the sample is [R=0.082 litre atm/deg mole]', '["1.00","2.00","3.00","4.00"]', 'n = <u>1.00 mol</u>.', '{"bold":[],"italic":[],"underline":["1.00"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c58q3bmuutkil7eyiiy21lf81', 'Biology', 'JAMB', null, 1997, null, 'Use the diagram to answer questions 14 and 15. The part that is similar to bone is labelled', null, '["IV","III","II","I"]', 2, 'Part II is similar to bone (dentine).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Use the diagram to answer questions 14 and 15. The part that is similar to bone is labelled', '["IV","III","II","I"]', '<u>Part II (dentine)</u> is similar to bone.', '{"bold":[],"italic":[],"underline":["II"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c591cwfo9nhfw92nt0adu7ysc', 'Islamic Religious Studies', 'JAMB', null, 2002, null, '''People come in search of knowledge, but knowledge does not seek people.'' The statement above was made to Caliph Harun ar-Rashid by', null, '["Imam Abu Hanifah","Imam Malik","Imam Shafi","Imam Hambali"]', 1, 'Imam Malik made this statement to Caliph Harun ar-Rashid.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '''People come in search of knowledge, but knowledge does not seek people.'' The statement above was made to Caliph Harun ar-Rashid by', '["Imam Abu Hanifah","<u>Imam Malik</u>","Imam Shafi","Imam Hambali"]', '<u>Imam Malik</u> made this statement to Caliph Harun ar-Rashid.', '{"bold":[],"italic":[],"underline":["Imam Malik"],"fillBlanks":[]}');
