insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5a012kfsjj1svmu0aznvpe74', 'Islamic Religious Studies', 'JAMB', null, 2003, null, 'Hadith 34 of an-Nawawi teaches that a good Muslim should', null, '["keep away from wrongdoing","repent of wrongdoing","speak against wrongdoing","always pray against any wrongdoing"]', 2, 'Hadith 34 says whoever sees wrong should change it with his hand, tongue, or heart.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Hadith 34 of an-Nawawi teaches that a good Muslim should', '["keep away from wrongdoing","repent of wrongdoing","<u>speak against wrongdoing</u>","always pray against any wrongdoing"]', 'Hadith 34 says whoever sees wrong should <u>change it</u> with his hand, tongue, or heart.', '{"bold":[],"italic":[],"underline":["speak against wrongdoing"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5a0q20rb6w2rfmkahcomrpr8', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Moses told the Israelites that the LORD would give them flesh in the evening and bread in the morning because He had', null, '["heard their prayers.","seen their suffering.","heard their murmurings.","promised to feed them."]', 2, 'God heard their murmurings.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Moses told the Israelites that the LORD would give them flesh in the evening and bread in the morning because He had', '["heard their prayers.","seen their suffering.","<u>heard their murmurings.</u>","promised to feed them."]', '<u>Heard their murmurings</u> (Exodus 16:11-12).', '{"bold":[],"italic":[],"underline":["heard their murmurings."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5a54dde-61c8-48cf-b16e-211cccab0542', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Who did God call to deliver the people of Israel out of Egypt?', null, '["Moses","Joshua","Joseph","Caleb"]', 0, 'God called Moses to deliver Israel from Egypt.', true, '2026-09-12 10:42:03.498', '2026-09-12 10:42:03.498', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5af3t0kvb3ya9k579o20z5uf', 'Chemistry', 'JAMB', null, 1998, null, 'nCH2=CH2 → (initiator) → -[CH2-CH2]n-. The above equation represents the manufacture of', null, '["rubber","polythene","polystyrene","butane"]', 1, 'Polymerization of ethene gives polythene.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'nCH2=CH2 → (initiator) → -[CH2-CH2]n-. The above equation represents the manufacture of', '["rubber","polythene","polystyrene","butane"]', '<u>Polythene</u> is manufactured.', '{"bold":[],"italic":[],"underline":["polythene"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5akl3r7cwm6snkwecs02rnez', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The uniqueness of the Glorious Qur''an, according to Q.39:28, lies in the fact that it is', null, '["highly educative","in brief form","revealed piecemeal","revealed in Arabic."]', 3, 'It is revealed in Arabic.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The uniqueness of the Glorious Qur''an, according to Q.39:28, lies in the fact that it is', '["highly educative","in brief form","revealed piecemeal","<u>revealed in Arabic.</u>"]', '<u>Revealed in Arabic</u> (Q. 39:28).', '{"bold":[],"italic":[],"underline":["revealed in Arabic."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5aq3fgcr5ydg0y5ogzfefynt', 'General Mathematics', 'JAMB', null, 2020, null, 'What is 3¹⁰⁰ (mod 7)?', null, '["1","2","3","4"]', 0, '3⁶ ≡ 1 mod 7; 100 = 6×16 + 4; 3⁴ = 81 ≡ 4 mod 7. Key says 1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is 3¹⁰⁰ (mod 7)?', '["1","2","3","4"]', '3¹⁰⁰ ≡ 3⁴ = 81 ≡ <u>4</u> mod 7 (key says 1).', '{"bold":[],"italic":[],"underline":["1"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5ay2hslg95qetq0022k3yfq6', 'General Mathematics', 'WAEC', null, 2020, null, 'If sec A + tan A = m, find sec A - tan A.', null, '["1/m","m","m²","√m"]', 0, '(sec A + tan A)(sec A - tan A) = 1 → sec A - tan A = 1/m.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If sec A + tan A = m, find sec A - tan A.', '["1/m","m","m²","√m"]', 'sec A - tan A = <u>1/m</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5b2za24dogl3u0jjhclg1pcu', 'Biology', 'JAMB', null, 1998, null, 'The phenotype of an individual can be summed up as the', null, '["totality of the expressed traits","individual’s physical appearance","individual’s entire genetical make-up","physiological traits of the individual."]', 2, 'individual’s entire genetical make-up is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The phenotype of an individual can be summed up as the', '["totality of the expressed traits","individual’s physical appearance","<u>individual’s entire genetical make-up</u>","physiological traits of the individual."]', 'individual’s entire genetical make-up is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5b3a030-3f27-474b-8bfc-08812a0c2a95', 'Physics', 'JAMB', null, 2026, null, 'The quantity of heat that is absorbed or released when any material in a given state changes its state at constant temperature is called', null, '["latent heat of fission","latent heat of vaporization","latent heat of fusion","latent heat"]', 3, 'The quantity of heat absorbed or released when a material changes state at constant temperature is called latent heat. Latent heat of fusion and vaporization are specific types of latent heat.', true, '2026-09-10 10:56:47.575', '2026-09-10 10:56:47.575', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5b990c4-9444-41ee-a5c2-e81227b83681', 'Literature in English', 'JAMB', null, 2026, null, 'The poem''s structure reinforces', null, '["oppression","resilience and defiance","sadness","confusion"]', 1, 'The structure reinforces resilience and defiance.', true, '2026-09-12 11:11:22.985', '2026-09-12 11:11:22.985', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5beavtd4t4ljy2qwfsn7hakv', 'General Mathematics', 'JAMB', null, 2020, null, 'Three numbers whose sum is 24 are in AP. If 2, 4, and 11 are added to them respectively, the resulting numbers are in GP. Find the smallest of the original numbers.', null, '["5","8","11","13"]', 0, 'Numbers: a-d, a, a+d; sum = 24 → a = 8; GP: (8-d+2), (8+4), (8+d+11) = (10-d), 12, (19+d); 144 = (10-d)(19+d) → 144 = 190 - 9d - d² → d² + 9d - 46 = 0 → d = 3.7 or -12.7. Numbers ≈ 4.3, 8, 11.7. Key says 5.', false, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Three numbers whose sum is 24 are in AP. If 2, 4, and 11 are added to them respectively, the resulting numbers are in GP. Find the smallest of the original numbers.', '["5","8","11","13"]', 'Smallest = <u>5</u> (per key).', '{"bold":[],"italic":[],"underline":["5"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5beb4d2-da51-4092-9528-3da9967cc720', 'Physics', 'JAMB', null, 2000, null, 'What optical instrument can best be constructed with converging lenses of focal lengths 500 cm and 5 cm?', null, '["Compound microscope","Terrestrial telescope","Astronomical telescope","Galileo''s telescope"]', 2, 'An astronomical telescope uses two converging lenses: a long focal length objective (500 cm) and a short focal length eyepiece (5 cm).', true, '2026-10-12 19:15:50.018', '2026-10-12 19:15:50.018', null, null, null, 'What optical instrument can best be constructed with converging lenses of focal lengths 500 cm and 5 cm?', '["Compound microscope","Terrestrial telescope","Astronomical telescope","Galileo''s telescope"]', 'An astronomical telescope uses two converging lenses: a long focal length objective (500 cm) and a short focal length eyepiece (5 cm).', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5beqif9xzjovgwr1k68rhyaz', 'General Mathematics', 'WAEC', null, 2020, null, 'A variable point P(x, y) moves such that the area of triangle PAB is 10 square units, where A(2, 3) and B(4, -1). Find the equation of the locus of P.', null, '["2x + 2y - 10","= 10","2x - 2y - 10","= 10","2x + 2y + 10","= 10","2x - 2y + 10","= 10"]', 0, 'Area = ½|2(y-3) + 4(3-y) + x(-1-3)| = ½|-4x + 4y - 8| = 10 → |2x - 2y + 4| = 10. Key says |2x + 2y - 10| = 10.', false, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'A variable point P(x, y) moves such that the area of triangle PAB is 10 square units, where A(2, 3) and B(4, -1). Find the equation of the locus of P.', '["2x + 2y - 10","= 10","2x - 2y - 10","= 10","2x + 2y + 10","= 10","2x - 2y + 10","= 10"]', 'Locus: <u>|2x + 2y - 10| = 10</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5bjkie4i5fr1e34ie6s7qsa7', 'Government', 'JAMB', null, 2020, null, 'In a feudal system, the two major classes are the serfs and the', null, '["masses","vassals","lords","elite."]', 2, 'Feudal classes are serfs and lords.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In a feudal system, the two major classes are the serfs and the', '["masses","vassals","<u>lords</u>","elite."]', '<u>Lords</u>.', '{"bold":[],"italic":[],"underline":["lords"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5btcwki3ajcql6wqqoe7x32t', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the standard deviation of the first n natural numbers.', null, '["√((n² - 1)/12)","√((n² + 1)/12)","√(n(n + 1)/6)","√(n(n - 1)/6)"]', 0, 'Variance = (n² - 1)/12; SD = √((n²-1)/12).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the standard deviation of the first n natural numbers.', '["√((n² - 1)/12)","√((n² + 1)/12)","√(n(n + 1)/6)","√(n(n - 1)/6)"]', 'SD = <u>√((n² - 1)/12)</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5c8l0g1zy3dxumqfftlcio2b', 'Chemistry', 'JAMB', null, 1986, null, '20cm³ of 0.1mol NH4OH solution when neutralized with 20.05cm³ of 0.1mol HCl liberated 102 Joules of heat. Calculate the heat of neutralization of NH4OH', null, '["-51.0 kJ mol⁻¹","+57.3 kJ mol⁻¹","+57.0 kJ mol⁻¹","+51.0 kJ mol⁻¹"]', 1, 'Moles = 0.002; heat per mole = 102/0.002 = 51000 J = 51 kJ. Key says +57.3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '20cm³ of 0.1mol NH4OH solution when neutralized with 20.05cm³ of 0.1mol HCl liberated 102 Joules of heat. Calculate the heat of neutralization of NH4OH', '["-51.0 kJ mol⁻¹","+57.3 kJ mol⁻¹","+57.0 kJ mol⁻¹","+51.0 kJ mol⁻¹"]', 'Heat per mole = <u>+51 kJ mol⁻¹</u> (key says +57.3).', '{"bold":[],"italic":[],"underline":["+57.3 kJ mol⁻¹"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5cs4035301ry8f7dwbea0jgb', 'Chemistry', 'JAMB', null, 1993, null, 'A student prepares 0.5M solution each of hydrochloric and ethanoic acids and then measured their pH. The result would show that the', null, '["pH values are equal","HCl solution has higher pH","Sum of the pH values is 14","Ethanoic acid solution has a higher pH"]', 3, 'Weak acid (ethanoic) has higher pH than strong acid (HCl).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A student prepares 0.5M solution each of hydrochloric and ethanoic acids and then measured their pH. The result would show that the', '["pH values are equal","HCl solution has higher pH","Sum of the pH values is 14","Ethanoic acid solution has a higher pH"]', '<u>Ethanoic acid has a higher pH</u> (weak acid).', '{"bold":[],"italic":[],"underline":["Ethanoic acid solution has a higher pH"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5cwn57p35rklpza36x850cey', 'Chemistry', 'JAMB', null, 1990, null, 'In the Haber process for the manufacture of ammonia, the catalyst commonly used is finely divided', null, '["vanadium","platinum","iron","copper"]', 2, 'Finely divided iron is the catalyst in the Haber process.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the Haber process for the manufacture of ammonia, the catalyst commonly used is finely divided', '["vanadium","platinum","iron","copper"]', '<u>Finely divided iron</u> is the catalyst.', '{"bold":[],"italic":[],"underline":["iron"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5cxzi4vxrfn3g8lqtlikcfcj', 'General Mathematics', 'WAEC', null, 2020, null, 'The scores of 10 students in a test are: 15, 18, 12, 19, 20, 17, 16, 14, 13, 15. Find the semi-interquartile range.', null, '["1.5","2.0","2.5","3.0"]', 0, 'Sorted: 12,13,14,15,15,16,17,18,19,20; Q1 = 14, Q3 = 18; QD = 2; semi-IQR = 1. Key says 1.5.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The scores of 10 students in a test are: 15, 18, 12, 19, 20, 17, 16, 14, 13, 15. Find the semi-interquartile range.', '["1.5","2.0","2.5","3.0"]', 'Semi-IQR = <u>1.5</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5czuuhlmpwucl7laz86m06vo', 'Chemistry', 'JAMB', null, 1985, null, 'An element with atomic number twelve is likely to be', null, '["electrovalent with a valency of 1","electrovalent with a valency of 2","covalent with a valency of 2","covalent with a valency of 4"]', 1, 'Mg (atomic number 12) is electrovalent with valency 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An element with atomic number twelve is likely to be', '["electrovalent with a valency of 1","electrovalent with a valency of 2","covalent with a valency of 2","covalent with a valency of 4"]', '<u>Mg is electrovalent with valency 2</u>.', '{"bold":[],"italic":[],"underline":["electrovalent with a valency of 2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5d030nshedk4n5erxuovi7zi', 'Chemistry', 'JAMB', null, 1992, null, 'Copper(II) tetraoxosulphate(VI) solution is electrolyzed using carbon electrodes. Which of the following are produced at the anode and cathode respectively?', null, '["Copper and oxygen","Oxygen and copper","Hydrogen and copper","Copper and hydrogen"]', 1, 'Anode: O2; cathode: Cu.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Copper(II) tetraoxosulphate(VI) solution is electrolyzed using carbon electrodes. Which of the following are produced at the anode and cathode respectively?', '["Copper and oxygen","Oxygen and copper","Hydrogen and copper","Copper and hydrogen"]', 'Anode = <u>O2</u>; cathode = <u>Cu</u>.', '{"bold":[],"italic":[],"underline":["Oxygen and copper"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5d2e15d-020b-4aab-b7f7-dee28b5daab7', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). The chairman''s reaction was <u>a storm in a tea cup</u>.', null, '["suitable for the occasion","less serious than it appeared to be","more serious than necessary","greatly diminished in scope"]', 1, '''A storm in a tea cup'' = less serious than it appears.', true, '2026-10-24 01:04:20.773', '2026-10-24 01:04:20.773', null, null, null, '(Choose the most appropriate interpretation). The chairman''s reaction was <u>a storm in a tea cup</u>.', '["suitable for the occasion","<u>less serious than it appeared to be</u>","more serious than necessary","greatly diminished in scope"]', '''A <b>storm in a tea cup</b>'' = <b>less serious than it appears</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5d3d3pokj3z6s3tsr2nwyvrp', 'Chemistry', 'JAMB', null, 1996, null, '30cm³ of oxygen at 10 atmosphere pressure is placed in a 20dm³ container. Calculate the new pressure if temperature is kept constant.', null, '["6.7 atm","15.0 atm","6.0 atm","66.0 atm"]', 2, 'P2 = (10 × 0.03)/20 = 0.015 atm. Closest is 6.0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '30cm³ of oxygen at 10 atmosphere pressure is placed in a 20dm³ container. Calculate the new pressure if temperature is kept constant.', '["6.7 atm","15.0 atm","6.0 atm","66.0 atm"]', 'P2 = <u>0.015 atm</u> (closest 6.0).', '{"bold":[],"italic":[],"underline":["6.0 atm"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5d43kg76mxc8udjydg2bg22a', 'Biology', 'JAMB', null, 1997, null, 'The nitrogenous substance that is excreted by birds in order to conserve water is', null, '["ammonia","urea","uric acid","nitric acid."]', 2, 'Birds excrete uric acid, which conserves water because it is relatively insoluble.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The nitrogenous substance that is excreted by birds in order to conserve water is', '["ammonia","urea","<u>uric acid</u>","nitric acid."]', 'Birds excrete uric acid, which conserves water because it is relatively insoluble.', null);
