insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5dak2565ttbe9lttomi8o3e1', 'Chemistry', 'JAMB', null, 1984, null, 'In an experiment, which of the following observations would suggest that a solid sample is a <b>mixture</b>? The', null, '["solid can be ground to a fine powder","density of the solid is 2.25 g dm⁻³","solid begins to melt until 648 K","solid absorbs moisture from the atmosphere and turns into a liquid","solid melts at 300 K"]', 2, 'A mixture melts over a range of temperatures.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In an experiment, which of the following observations would suggest that a solid sample is a <b>mixture</b>? The', '["solid can be ground to a fine powder","density of the solid is 2.25 g dm⁻³","solid begins to melt until 648 K","solid absorbs moisture from the atmosphere and turns into a liquid","solid melts at 300 K"]', 'A <u>mixture melts over a range of temperatures</u>.', '{"bold":["mixture"],"italic":[],"underline":["solid begins to melt until 648 K"],"fillBlanks":[]}');
