insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5dcmyzo6amjhcz9t8xuoqofo', 'Biology', 'JAMB', null, 1998, null, 'The procaryotic cell type is characterized by a', null, '["complex cytoplasm in which different regions are poorly defined .","localization of differ regions of the cell into tissues.","collection of organelles and macromolecular complexes","simple cytoplasm with well-defined regions."]', 3, 'simple cytoplasm with well-defined regions. is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The procaryotic cell type is characterized by a', '["complex cytoplasm in which different regions are poorly defined .","localization of differ regions of the cell into tissues.","collection of organelles and macromolecular complexes","<u>simple cytoplasm with well-defined regions.</u>"]', 'simple cytoplasm with well-defined regions. is the best answer because it matches the biological principle tested by the question.', null);
