insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5dg3xvs6sur4jdm7kxzh5f8w', 'Biology', 'JAMB', null, 1991, null, 'A soil consisting of alumina and iron (II) oxide is known as', null, '["loamy soil","clayey soil","laterite","podzol"]', 2, 'A soil of alumina and iron oxide is laterite.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A soil consisting of alumina and iron (II) oxide is known as', '["loamy soil","clayey soil","<u>laterite</u>","podzol"]', 'A soil of alumina and iron oxide is <u>laterite</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5dh0goo5d1v2kyr6deg6610r', 'Biology', 'JAMB', null, 1986, null, 'The three important organs that are situated close to the stomach are', null, '["kidney, liver and gall bladder","pancreas, liver and kidney","liver, kidney and spleen","gall bladder, pancreas and spleen"]', 1, 'The pancreas, liver, and kidney are close to the stomach.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The three important organs that are situated close to the stomach are', '["kidney, liver and gall bladder","<u>pancreas, liver and kidney</u>","liver, kidney and spleen","gall bladder, pancreas and spleen"]', 'The <u>pancreas, liver, and kidney</u> are close to the stomach.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5dpwxlldw5d3gl56tagoubew', 'General Mathematics', 'WAEC', null, 2020, null, 'A fair die is tossed twice. The probability that the sum of the outcomes is a prime number greater than 5 is:', null, '["1/6","2/9","7/36","11/36"]', 1, 'Primes above 5: 7 (6 ways) and 11 (2 ways); 8/36 = 2/9.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'A fair die is tossed twice. The probability that the sum of the outcomes is a prime number greater than 5 is:', '["1/6","2/9","7/36","11/36"]', 'Primes above 5: 7 (6 ways) and 11 (2 ways); 8/36 = 2/9.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5dsmjd299m72eh6yqa5rd0ii', 'Islamic Religious Studies', 'JAMB', null, 2020, null, '''People come in search of knowledge, but knowledge does not seek people.'' The statement above was made to Caliph Harun ar-Rashid by', null, '["Imam Abu Hanifah","Imam Malik","Imam Shafi''i","Imam Hambali."]', 1, 'Imam Malik made this statement.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '''People come in search of knowledge, but knowledge does not seek people.'' The statement above was made to Caliph Harun ar-Rashid by', '["Imam Abu Hanifah","<u>Imam Malik</u>","Imam Shafi''i","Imam Hambali."]', '<u>Imam Malik</u>.', '{"bold":[],"italic":[],"underline":["Imam Malik"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5du55q13fhqoill2jqtprmzj', 'Chemistry', 'JAMB', null, 1986, null, 'What is the consequence of increasing pressure on the equilibrium reaction ZnO(s) + H2(g) ⇌ Zn(s) + H2O(g)?', null, '["The equilibrium is driven to the left","The equilibrium is driven to the right","There is no effect","More ZnO(s) is produced"]', 2, 'Equal moles of gas on both sides, so pressure has no effect.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is the consequence of increasing pressure on the equilibrium reaction ZnO(s) + H2(g) ⇌ Zn(s) + H2O(g)?', '["The equilibrium is driven to the left","The equilibrium is driven to the right","There is no effect","More ZnO(s) is produced"]', '<u>No effect</u> (equal gas moles on both sides).', '{"bold":[],"italic":[],"underline":["There is no effect"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5e09sr8j24bn43cbsfpkbjbg', 'Government', 'JAMB', null, 2020, null, 'Who among the following served as Secretary-General of OPEC?', null, '["Aret Adams","Rilwanu Lukman","Jibril Aminu","Dan Ete"]', 1, 'Rilwanu Lukman served as Secretary-General of OPEC.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Who among the following served as Secretary-General of OPEC?', '["Aret Adams","<u>Rilwanu Lukman</u>","Jibril Aminu","Dan Ete"]', '<u>Rilwanu Lukman</u>.', '{"bold":[],"italic":[],"underline":["Rilwanu Lukman"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5e0oiyjvuzpnfnfigyrhxggv', 'General Mathematics', 'WAEC', null, 2020, null, 'Find ∫ x²/(x² + 1)² dx.', null, '["½(tan⁻¹x - x/(x² + 1)) + C","tan⁻¹x + x/(x² + 1) + C","tan⁻¹x - 1/(x² + 1) + C","tan⁻¹x + 1/(x² + 1) + C"]', 0, 'Substitution x = tan θ; result = ½(tan⁻¹x - x/(x²+1)) + C.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find ∫ x²/(x² + 1)² dx.', '["½(tan⁻¹x - x/(x² + 1)) + C","tan⁻¹x + x/(x² + 1) + C","tan⁻¹x - 1/(x² + 1) + C","tan⁻¹x + 1/(x² + 1) + C"]', 'Integral = <u>½(tan⁻¹x - x/(x² + 1)) + C</u>.', null);
