insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5e78hb57e2wpwr0inr91qehf', 'Government', 'JAMB', null, 2020, null, 'In theory, one major advantage of the one-party system is that it', null, '["eliminates intra-party conflict","promotes greater mass participation in government","serves as an instrument of national integration","guarantees social justice."]', 2, 'A one-party system can serve as an instrument of national integration.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In theory, one major advantage of the one-party system is that it', '["eliminates intra-party conflict","promotes greater mass participation in government","<u>serves as an instrument of national integration</u>","guarantees social justice."]', '<u>Serves as an instrument of national integration</u>.', '{"bold":[],"italic":[],"underline":["serves as an instrument of national integration"],"fillBlanks":[]}');
