insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5es7dcrvcsuiu4u36sq8fwpj', 'Chemistry', 'JAMB', null, 1984, null, 'The function of sulphur during the <b>vulcanization</b> of rubber is to', null, '["act as catalyst for the polymerization of rubber molecules","convert rubber from thermosetting to thermoplastic polymer","form chains which bind rubber molecules together","break down rubber polymer molecules","shorten the chain length of rubber polymer"]', 2, 'Sulphur forms cross-links between rubber chains.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The function of sulphur during the <b>vulcanization</b> of rubber is to', '["act as catalyst for the polymerization of rubber molecules","convert rubber from thermosetting to thermoplastic polymer","form chains which bind rubber molecules together","break down rubber polymer molecules","shorten the chain length of rubber polymer"]', '<u>Sulphur forms cross-links</u> between rubber chains.', '{"bold":["vulcanization"],"italic":[],"underline":["form chains which bind rubber molecules together"],"fillBlanks":[]}');
