insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5f0afc0-b779-4c87-9aa6-f185c004bf6a', 'Biology', 'JAMB', null, 2013, null, 'The solid part of the ecosystem is referred to as', null, '["Biosphere","Lithosphere","Atmosphere","Hydrosphere"]', 1, 'The solid part of the ecosystem is the lithosphere.', true, '2026-10-12 20:59:48.095', '2026-10-12 20:59:48.095', null, null, null, 'The solid part of the ecosystem is referred to as', '["Biosphere","Lithosphere","Atmosphere","Hydrosphere"]', 'The solid part of the ecosystem is the lithosphere.', '{"bold":["lithosphere"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5f9o9tewq53z99z353o0h9yl', 'Chemistry', 'JAMB', null, 1996, null, 'A given quantity of gas occupies a volume of 228cm³ at a pressure of 750mm Hg. What will be its volume at atmospheric pressure?', null, '["200cm³","225cm³","230cm³","235cm³"]', 1, 'V2 = (750 × 228)/760 = 225 cm³.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A given quantity of gas occupies a volume of 228cm³ at a pressure of 750mm Hg. What will be its volume at atmospheric pressure?', '["200cm³","225cm³","230cm³","235cm³"]', 'V2 = <u>225 cm³</u>.', '{"bold":[],"italic":[],"underline":["225cm³"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5fdc78f-80e5-4a50-a8fc-89a74e87aae1', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. His success may be described as <u>a pyrrhic victory</u>.', null, '["a deserving victory","costly","indecisive","an easy victory"]', 1, 'A pyrrhic victory = costly victory.', true, '2026-10-24 01:01:51.717', '2026-10-24 01:01:51.717', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. His success may be described as <u>a pyrrhic victory</u>.', '["a deserving victory","<u>costly</u>","indecisive","an easy victory"]', 'A <b>pyrrhic victory</b> = <b>costly</b> victory.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5fdvibcpv0cth80nybsmqkjh', 'Chemistry', 'JAMB', null, 1994, null, 'The number of electrons in the valence shell of an element of atomic number 14 is', null, '["1","2","3","4"]', 3, 'Silicon (atomic number 14) has 4 valence electrons.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The number of electrons in the valence shell of an element of atomic number 14 is', '["1","2","3","4"]', '<u>Silicon has 4 valence electrons</u>.', '{"bold":[],"italic":[],"underline":["4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5fhzk5s2hafvuhlapsm33bvj', 'General Mathematics', 'JAMB', null, 2020, null, 'The angles of a triangle are in the ratio 1:2:3. Find the ratio of the sides opposite these angles.', null, '["1:2:3","1:√3:2","1:√3:√2","√2:√3:1"]', 1, 'Angles 30°, 60°, 90°; sides ratio = 1:√3:2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The angles of a triangle are in the ratio 1:2:3. Find the ratio of the sides opposite these angles.', '["1:2:3","1:√3:2","1:√3:√2","√2:√3:1"]', 'Sides ratio = <u>1:√3:2</u>.', '{"bold":[],"italic":[],"underline":["1:√3:2"],"fillBlanks":[]}');
