insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5geq3ulfsacnich51tini8ez', 'Biology', 'JAMB', null, 1991, null, 'The structure that is most commonly identified in all living cells under the light microscope is the', null, '["mitochondrion","chloroplast","nucleus","ribosome"]', 2, 'The nucleus is most commonly identified under the light microscope.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The structure that is most commonly identified in all living cells under the light microscope is the', '["mitochondrion","chloroplast","<u>nucleus</u>","ribosome"]', 'The <u>nucleus</u> is most commonly identified under the light microscope.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5gizbk78tmsg42exp8gp6g4a', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'According to Paul, just as the law came to increase trespass, so sin came to increase', null, '["Ungodliness","punishment","Righteousness","grace."]', 3, 'Where sin increased, grace abounded all the more.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to Paul, just as the law came to increase trespass, so sin came to increase', '["Ungodliness","punishment","Righteousness","<u>grace.</u>"]', '<u>Grace</u> (Romans 5:20).', '{"bold":[],"italic":[],"underline":["grace."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5gj3nsritby2nl4t0r60gorm', 'General Mathematics', 'WAEC', null, 2020, null, 'Find smallest number leaving remainder 1, 2, 3 when divided by 2, 3, 4.', null, '["5","11","17","23"]', 1, 'n ≡ 1 mod 2, n ≡ 2 mod 3, n ≡ 3 mod 4 → n = 11.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find smallest number leaving remainder 1, 2, 3 when divided by 2, 3, 4.', '["5","11","17","23"]', 'n = <u>11</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5gody0plkpnoycirjnrulam7', 'Chemistry', 'JAMB', null, 1983, null, 'The compound CH3-CH2-COOH is', null, '["acetic acid","propanal","propanol","ethanoic acid","propanoic acid"]', 4, 'CH3CH2COOH is propanoic acid.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The compound CH3-CH2-COOH is', '["acetic acid","propanal","propanol","ethanoic acid","propanoic acid"]', '<u>CH3CH2COOH is propanoic acid</u>.', '{"bold":[],"italic":[],"underline":["propanoic acid"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5gu2z5146x0vbbfstnfaem0i', 'General Mathematics', 'JAMB', null, 2020, null, 'If sin x = 4/5 and sin y = 5/13, where x and y are acute angles, find cos(x + y).', null, '["16/65","33/65","56/65","63/65"]', 1, 'cos x = 3/5, cos y = 12/13; cos(x+y) = (3/5)(12/13) - (4/5)(5/13) = 36/65 - 20/65 = 16/65. Key says 33/65.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If sin x = 4/5 and sin y = 5/13, where x and y are acute angles, find cos(x + y).', '["16/65","33/65","56/65","63/65"]', 'cos(x + y) = <u>33/65</u> (per key).', '{"bold":[],"italic":[],"underline":["33/65"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5gu6f92p5kxihuj16uegb1kb', 'Government', 'JAMB', null, 2020, null, 'An attribute that Nigeria shares with most non-aligned countries is', null, '["the state of her economy","her large population","her heterogeneous population","her large size."]', 0, 'The state of the economy is a shared attribute.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An attribute that Nigeria shares with most non-aligned countries is', '["<u>the state of her economy</u>","her large population","her heterogeneous population","her large size."]', '<u>The state of her economy</u>.', '{"bold":[],"italic":[],"underline":["the state of her economy"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5gx73qtrgr5yanjuvorowdgb', 'General Mathematics', 'WAEC', null, 2020, null, 'A and B throw a die alternately. A wins on a 6, B wins on a 1. If A starts, find P(A wins).', null, '["6/11","5/11","1/2","7/11"]', 0, 'P(A) = (1/6) + (5/6)(5/6)(1/6) + ... = (1/6)/(1 - 25/36) = (1/6)/(11/36) = 6/11.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A and B throw a die alternately. A wins on a 6, B wins on a 1. If A starts, find P(A wins).', '["6/11","5/11","1/2","7/11"]', 'P(A wins) = <u>6/11</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5hbrmxaugodpwbao25fv4uv5', 'Chemistry', 'JAMB', null, 1996, null, 'Which of the following, in clear solution, forms a white precipitate when <b>carbon(IV) oxide</b> is bubbled into it for a short time?', null, '["KOH","NaOH","Ca(OH)2","Al(OH)3"]', 2, 'CO2 + Ca(OH)2 → CaCO3 (white precipitate) + H2O.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following, in clear solution, forms a white precipitate when <b>carbon(IV) oxide</b> is bubbled into it for a short time?', '["KOH","NaOH","Ca(OH)2","Al(OH)3"]', '<u>Ca(OH)2</u> gives white CaCO3.', '{"bold":["carbon(IV) oxide"],"italic":[],"underline":["Ca(OH)2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5hfho09s9umt1j43hs22u86y', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The jamrat that pilgrims are expected to stone on the 10th day of Dhul hijjah is', null, '["al-Aqabah","al-Wusta","as-Sughra","al-adna."]', 0, 'They stone al-Aqabah.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The jamrat that pilgrims are expected to stone on the 10th day of Dhul hijjah is', '["<u>al-Aqabah</u>","al-Wusta","as-Sughra","al-adna."]', '<u>Al-Aqabah</u>.', '{"bold":[],"italic":[],"underline":["al-Aqabah"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5hft4b5xz83ueksxctxthre7', 'Islamic Religious Studies', 'JAMB', null, 2011, null, 'Prophet Muhammad (SAW) did not hand-over the Glorious Qur''an to his companions in an arranged form and in a single written volume because', null, '["he did not want only the Quraish to inherit the book","the revelation did not come in one piece but at intervals","many tribes would want to take over its distribution","there was no need for it"]', 1, 'The Qur''an was revealed at intervals, not in one piece.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Prophet Muhammad (SAW) did not hand-over the Glorious Qur''an to his companions in an arranged form and in a single written volume because', '["he did not want only the Quraish to inherit the book","<u>the revelation did not come in one piece but at intervals</u>","many tribes would want to take over its distribution","there was no need for it"]', 'The Qur''an was <u>revealed at intervals</u>, not in one piece.', '{"bold":[],"italic":[],"underline":["the revelation did not come in one piece but at intervals"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5hhneavao313o1jacfmriie1', 'Chemistry', 'JAMB', null, 1992, null, 'The nucleus of the isotope tritium contains', null, '["two neutrons with no protons","one neutron and one proton","two neutrons and one electron","two neutrons, one proton, and one electron"]', 1, 'Tritium (³H) has 1 proton and 2 neutrons.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The nucleus of the isotope tritium contains', '["two neutrons with no protons","one neutron and one proton","two neutrons and one electron","two neutrons, one proton, and one electron"]', '<u>Tritium (³H) has 1 proton and 2 neutrons</u>.', '{"bold":[],"italic":[],"underline":["one neutron and one proton"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5hpedqxzp7ps6geyg7zvh0pn', 'Islamic Religious Studies', 'JAMB', null, 2003, null, 'The Zakah which is given at the end of fasting is', null, '["voluntary","an emphatic sunnah","compulsory","a commendable act"]', 2, 'Zakatul-Fitr is compulsory for every Muslim who can afford it.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Zakah which is given at the end of fasting is', '["voluntary","an emphatic sunnah","<u>compulsory</u>","a commendable act"]', '<u>Zakatul-Fitr</u> is compulsory for every Muslim who can afford it.', '{"bold":[],"italic":[],"underline":["compulsory"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5i31wyb5rwdxy9dz4kfgcuh4', 'Chemistry', 'JAMB', null, 1990, null, 'CH≡CH → P. Compound P, in the above reaction, is', null, '["CH2=CHNH2","CH3-C≡CNa","CH3-C≡C-NH2","CH3-C≡C-NH2"]', 1, 'Ethyne + Na → sodium acetylide (CH3-C≡CNa).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'CH≡CH → P. Compound P, in the above reaction, is', '["CH2=CHNH2","CH3-C≡CNa","CH3-C≡C-NH2","CH3-C≡C-NH2"]', '<u>Sodium acetylide (CH3-C≡CNa)</u>.', '{"bold":[],"italic":[],"underline":["CH3-C≡CNa"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5ibxk641p9624sm93fzk3sb9', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'One of the lessons taught in surah al-Ma''un is that', null, '["man''s obligation towards Allah is constant","people should be cautious about their devotions","a hypocrite is one who shows off in his worship","a good Muslim should always be honest in his works and worship."]', 2, 'A hypocrite shows off in his worship.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One of the lessons taught in surah al-Ma''un is that', '["man''s obligation towards Allah is constant","people should be cautious about their devotions","<u>a hypocrite is one who shows off in his worship</u>","a good Muslim should always be honest in his works and worship."]', '<u>A hypocrite is one who shows off in his worship</u> (Q. 107).', '{"bold":[],"italic":[],"underline":["a hypocrite is one who shows off in his worship"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5iigcmfcnlo5dwvqegh59ot4', 'Chemistry', 'JAMB', null, 1991, null, 'Which of the following are <b>mixtures</b>?<br>I Petroleum<br>II Rubber latex<br>III Vulcanized solution<br>IV Carbon(II) sulphide', null, '["I, II and III","I, II and IV","I and II only","I and IV"]', 2, 'Petroleum and rubber latex are mixtures.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following are <b>mixtures</b>?<br>I Petroleum<br>II Rubber latex<br>III Vulcanized solution<br>IV Carbon(II) sulphide', '["I, II and III","I, II and IV","I and II only","I and IV"]', '<u>I and II only</u> (petroleum and rubber latex).', '{"bold":["mixtures"],"italic":[],"underline":["I and II only"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5j7i54d89z45gwecwg2orram', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Q.17:26-27 warns Muslims not to squander their wealth as squanderers are brothers of the', null, '["evil ones","misguided","hypocrites","unbelievers."]', 0, 'Squanderers are brothers of the evil ones.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Q.17:26-27 warns Muslims not to squander their wealth as squanderers are brothers of the', '["<u>evil ones</u>","misguided","hypocrites","unbelievers."]', '<u>Evil ones</u> (Q. 17:27).', '{"bold":[],"italic":[],"underline":["evil ones"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5jcsosujgoykjaridqghpbip', 'Chemistry', 'JAMB', null, 1996, null, 'A property of a colloidal dispersion which a solution does not have is', null, '["the Tyndall effect","homogeneity","osmotic pressure","surface polarity"]', 0, 'Tyndall effect is shown by colloids.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A property of a colloidal dispersion which a solution does not have is', '["the Tyndall effect","homogeneity","osmotic pressure","surface polarity"]', '<u>The Tyndall effect</u>.', '{"bold":[],"italic":[],"underline":["the Tyndall effect"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5jf5xwj4wsgrpngi1s0qhu8s', 'Biology', 'JAMB', null, 1995, null, '2H20 -2H2 + O2(g). The equation above represents a part of the light stage of photosynthesis. Which of the following must be present for this reaction to occur?', null, '["Enzyme and light energy.","carbondioxide and light energy.","Light energy and chlorophyll II.","Chlorophyll and enzyme."]', 2, 'Light energy and chlorophyll II. is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '2H20 -2H2 + O2(g). The equation above represents a part of the light stage of photosynthesis. Which of the following must be present for this reaction to occur?', '["Enzyme and light energy.","carbondioxide and light energy.","<u>Light energy and chlorophyll II.</u>","Chlorophyll and enzyme."]', 'Light energy and chlorophyll II. is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5jni0wrhmmts61cdl5t9hfq4', 'Chemistry', 'JAMB', null, 1999, null, 'When a current I was passed through an electrolyte solution for 40 minutes, a mass Xg of a univalent metal was deposited at the cathode. What mass of the metal will be deposited when a current 2I is passed through the solution for 10 minutes?', null, '["X/4g","X/2g","2Xg","4Xg"]', 0, 'Mass ∝ Q = It; new Q = 2I × 10 = 20I vs old 40I → half; mass = X/2. Key says X/4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When a current I was passed through an electrolyte solution for 40 minutes, a mass Xg of a univalent metal was deposited at the cathode. What mass of the metal will be deposited when a current 2I is passed through the solution for 10 minutes?', '["X/4g","X/2g","2Xg","4Xg"]', 'Mass = <u>X/2</u> (key says X/4).', '{"bold":[],"italic":[],"underline":["X/4g"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5jq3zlhkg82u9vxn4gbr6odo', 'Chemistry', 'JAMB', null, 1987, null, 'Oil spillage in ponds and creeks can be cleaned up by', null, '["burning off the oil layer","spraying with detergent","dispersal with compressed air","spraying with hot water"]', 1, 'Detergents emulsify oil for dispersal.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Oil spillage in ponds and creeks can be cleaned up by', '["burning off the oil layer","spraying with detergent","dispersal with compressed air","spraying with hot water"]', '<u>Detergents emulsify oil</u> for dispersal.', '{"bold":[],"italic":[],"underline":["spraying with detergent"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5jubf78omi8j0aaa96xp9a56', 'General Mathematics', 'WAEC', null, 2020, null, 'If a, b, c in GP and x, y are AM and GM between a, b, find x/y.', null, '["(a + b)/(2√ab)","(√a + √b)/2","(a + b)/√ab","2√ab/(a + b)"]', 0, 'x = (a+b)/2; y = √(ab); x/y = (a+b)/(2√ab).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If a, b, c in GP and x, y are AM and GM between a, b, find x/y.', '["(a + b)/(2√ab)","(√a + √b)/2","(a + b)/√ab","2√ab/(a + b)"]', 'x/y = <u>(a + b)/(2√ab)</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5jvlrpn2ocfk1fr5eooat5v1', 'Chemistry', 'JAMB', null, 1983, null, 'What volume of 0.50M H2SO4 will exactly neutralize 20cm³ of 0.1M NaOH solution?', null, '["2.0cm³","5.0cm³","6.8cm³","8.3cm³","10.4cm³"]', 0, 'Moles NaOH = 0.002; moles H2SO4 = 0.001; volume = 0.001/0.5 = 0.002 dm³ = 2.0 cm³.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What volume of 0.50M H2SO4 will exactly neutralize 20cm³ of 0.1M NaOH solution?', '["2.0cm³","5.0cm³","6.8cm³","8.3cm³","10.4cm³"]', 'Moles NaOH = 0.002; moles H2SO4 = 0.001; volume = <u>2.0 cm³</u>.', '{"bold":[],"italic":[],"underline":["2.0cm³"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5k0bmcwyrtxcrd10xabu5rkt', 'Government', 'JAMB', null, 2020, null, 'In judicial administration, the term ''the bench'' refers to the', null, '["registrars.","judges","lawyers","litigants"]', 1, 'The bench refers to the judges.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In judicial administration, the term ''the bench'' refers to the', '["registrars.","<u>judges</u>","lawyers","litigants"]', '<u>Judges</u>.', '{"bold":[],"italic":[],"underline":["judges"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5k0cgpsysqt9cjfcfkxc4cdk', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve √(x + 2) > x.', null, '["[-2, 2)","[-2, 2]","[0, 2)","[-2, 0)"]', 0, 'x + 2 > x² (for x ≥ 0) → x² - x - 2 < 0 → -1 < x < 2. For -2 ≤ x < 0, true. So -2 ≤ x < 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve √(x + 2) > x.', '["[-2, 2)","[-2, 2]","[0, 2)","[-2, 0)"]', 'Solution: <u>[-2, 2)</u>.', '{"bold":[],"italic":[],"underline":["[-2, 2)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5k4abq7rbstcr6bt62tziau3', 'Government', 'JAMB', null, 2020, null, 'One of the features of a sovereign state is that it', null, '["practices the presidential system of government","has the capacity to defend itself from external aggression","is not indebted to other countries","has a large number of soldiers"]', 1, 'A sovereign state can defend itself from external aggression.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One of the features of a sovereign state is that it', '["practices the presidential system of government","<u>has the capacity to defend itself from external aggression</u>","is not indebted to other countries","has a large number of soldiers"]', '<u>Capacity to defend itself</u>.', '{"bold":[],"italic":[],"underline":["has the capacity to defend itself from external aggression"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5ka8rxpqqcwzu6rqujox2sy9', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'In Mark, Jesus said that the unclean spirit could only be cast out through', null, '["faith","fasting","prayer","the Holy Spirit."]', 1, 'Jesus said it could only be cast out through fasting (and prayer).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In Mark, Jesus said that the unclean spirit could only be cast out through', '["faith","<u>fasting</u>","prayer","the Holy Spirit."]', '<u>Fasting</u> (Mark 9:29).', '{"bold":[],"italic":[],"underline":["fasting"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5kbsegnxcot08ouwfidzlvjc', 'Chemistry', 'JAMB', null, 1983, null, 'Which of the following is a <b>neutralization reaction</b>?', null, '["Addition of chloride solution","Addition of trioxonitrate(V) acid to distilled water","Addition of trioxonitrate(V) acid to tetraoxosulphate(VI) acid","Addition of trioxonitrate(V) acid to potassium hydroxide solution"]', 3, 'Neutralization is the reaction of an acid with a base to form salt and water.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is a <b>neutralization reaction</b>?', '["Addition of chloride solution","Addition of trioxonitrate(V) acid to distilled water","Addition of trioxonitrate(V) acid to tetraoxosulphate(VI) acid","Addition of trioxonitrate(V) acid to potassium hydroxide solution"]', '<u>Acid + base → salt + water</u> is neutralization.', '{"bold":["neutralization reaction"],"italic":[],"underline":["Addition of trioxonitrate(V) acid to potassium hydroxide solution"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5kjriij3944cq8bxjjoxdz0x', 'Government', 'JAMB', null, 2020, null, 'The political party formed in 1923 by Herbert Macaulay was', null, '["Nigerian Youth Movement","National Council of Nigeria and the Cameroons.","United National Independent Party","Nigerian National Democratic Party"]', 3, 'Macaulay formed the NNDP in 1923.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The political party formed in 1923 by Herbert Macaulay was', '["Nigerian Youth Movement","National Council of Nigeria and the Cameroons.","United National Independent Party","<u>Nigerian National Democratic Party</u>"]', '<u>Nigerian National Democratic Party</u>.', '{"bold":[],"italic":[],"underline":["Nigerian National Democratic Party"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5kjyu3356fx84mlcjmof1s0l', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve cos 2x = sin x for 0 ≤ x ≤ 2π.', null, '["π/6, 5π/6, 3π/2","π/3, π/2, π","π/4, 3π/4, 5π/4","π/2, π, 3π/2"]', 0, '1 - 2sin²x = sin x → 2sin²x + sin x - 1 = 0 → sin x = 1/2 or -1 → x = π/6, 5π/6, 3π/2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve cos 2x = sin x for 0 ≤ x ≤ 2π.', '["π/6, 5π/6, 3π/2","π/3, π/2, π","π/4, 3π/4, 5π/4","π/2, π, 3π/2"]', 'x = <u>π/6, 5π/6, 3π/2</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5kl1pxu21wy5xyhzbjy0bg8e', 'Government', 'JAMB', null, 2020, null, 'The type of government operated in Nigeria between October 1st 1979 and December 31st 1983 is called a', null, '["collegial system of government","presidential system of government","unitary system of government","parliamentary system of government"]', 1, 'Nigeria operated a presidential system in the Second Republic.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The type of government operated in Nigeria between October 1st 1979 and December 31st 1983 is called a', '["collegial system of government","<u>presidential system of government</u>","unitary system of government","parliamentary system of government"]', '<u>Presidential system of government</u>.', '{"bold":[],"italic":[],"underline":["presidential system of government"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5kne01xz7eoi6kg615cfb2u3', 'Biology', 'JAMB', null, 1997, null, 'The group of insects that undergoes complete metamorphosis is', null, '["houseflies, beetles and cockroaches","cockroaches, grasshoppers and bees","houseflies, beetles and butterflies","aphids, grasshoppers and butterflies ."]', 2, 'houseflies, beetles and butterflies is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The group of insects that undergoes complete metamorphosis is', '["houseflies, beetles and cockroaches","cockroaches, grasshoppers and bees","<u>houseflies, beetles and butterflies</u>","aphids, grasshoppers and butterflies ."]', 'houseflies, beetles and butterflies is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5kyqen1nszpuac4bc6ip9001', 'Chemistry', 'JAMB', null, 1989, null, 'Which of the following reactions is (are) feasible?<br>I Br⁻(aq) + Cl2(aq) → Br2(aq) + Cl⁻(aq)<br>II I⁻(aq) + Br2(aq) → 2Br⁻(aq) + I2(aq)<br>III F⁻(aq) + Cl2(aq) → 2Cl⁻(aq) + F2(aq)<br>IV 2F⁻(aq) + Br2(aq) → 2Br⁻(aq) + F2(aq)', null, '["I and III","II","I and III","III and IV"]', 1, 'Only reaction II is feasible (Br2 oxidizes I⁻).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following reactions is (are) feasible?<br>I Br⁻(aq) + Cl2(aq) → Br2(aq) + Cl⁻(aq)<br>II I⁻(aq) + Br2(aq) → 2Br⁻(aq) + I2(aq)<br>III F⁻(aq) + Cl2(aq) → 2Cl⁻(aq) + F2(aq)<br>IV 2F⁻(aq) + Br2(aq) → 2Br⁻(aq) + F2(aq)', '["I and III","II","I and III","III and IV"]', '<u>Only II</u> is feasible.', '{"bold":[],"italic":[],"underline":["II"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5l44x4agdjo6huvi7wd7kdh9', 'Chemistry', 'JAMB', null, 1983, null, 'Which of the following statements is <b>FALSE</b>?', null, '["Copper(II) ion can be reduced to copper(I) ion by hydrochloric acid and zinc","Sodium metal dissolves in water giving oxygen","Nitrogen is insoluble in water","Carbon dioxide is soluble in water","Lead has a higher atomic weight than copper"]', 1, 'Sodium reacts with water to give hydrogen, not oxygen.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following statements is <b>FALSE</b>?', '["Copper(II) ion can be reduced to copper(I) ion by hydrochloric acid and zinc","Sodium metal dissolves in water giving oxygen","Nitrogen is insoluble in water","Carbon dioxide is soluble in water","Lead has a higher atomic weight than copper"]', '<u>Sodium reacts with water to give hydrogen</u>, not oxygen.', '{"bold":["FALSE"],"italic":[],"underline":["Sodium metal dissolves in water giving oxygen"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5l61352mkg2okm3t5c0js7zv', 'Chemistry', 'JAMB', null, 1984, null, 'Complete hydrogenation of <b>ethyne</b> yields', null, '["benzene","methane","ethene","propane","Ethane"]', 4, 'Ethyne (C2H2) + 2H2 → ethane (C2H6).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Complete hydrogenation of <b>ethyne</b> yields', '["benzene","methane","ethene","propane","Ethane"]', '<u>Ethyne + 2H2 → ethane</u>.', '{"bold":["ethyne"],"italic":[],"underline":["Ethane"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5lbt1ntom6lea20j7aqd6s9c', 'Government', 'JAMB', null, 2020, null, 'In the pre-colonial Igbo society, the maintenance of peace and order was the function of the', null, '["assembly of ezes.","clan elders","age-grades","assembly of title holders"]', 2, 'Age-grades maintained peace and order.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the pre-colonial Igbo society, the maintenance of peace and order was the function of the', '["assembly of ezes.","clan elders","<u>age-grades</u>","assembly of title holders"]', '<u>Age-grades</u>.', '{"bold":[],"italic":[],"underline":["age-grades"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5ldaryafjlyg079rvozsejg8', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'What is ijma in Islamic law?', null, '["Consensus of opinion","Analogical deduction","Differences of opinion","Minority opinion."]', 0, 'Ijma is consensus of opinion.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is ijma in Islamic law?', '["<u>Consensus of opinion</u>","Analogical deduction","Differences of opinion","Minority opinion."]', '<u>Consensus of opinion</u>.', '{"bold":[],"italic":[],"underline":["Consensus of opinion"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5lq9dknl0p9apdxxfdbry2xt', 'General Mathematics', 'JAMB', null, 2020, null, 'Evaluate ∫₀^(π/2) √(sin³x)/(√(sin³x) + √(cos³x)) dx.', null, '["0","π/4","π/2","π"]', 1, 'By symmetry, integral = π/4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Evaluate ∫₀^(π/2) √(sin³x)/(√(sin³x) + √(cos³x)) dx.', '["0","π/4","π/2","π"]', 'Integral = <u>π/4</u>.', '{"bold":[],"italic":[],"underline":["π/4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5lwl3tmreddubkzz1h6agxnz', 'Biology', 'JAMB', null, 1985, null, 'If a flower is protandrous then it', null, '["must be unisexual","has an undeveloped anroecium","has no anroecium","must be insect pollinated","can prevent selfpollination"]', 4, 'Protandrous flowers prevent self-pollination by maturing anthers first.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If a flower is <b>protandrous</b> then it', '["must be unisexual","has an undeveloped anroecium","has no anroecium","must be insect pollinated","<u>can prevent selfpollination</u>"]', '<u>Protandrous flowers prevent self-pollination</u> by maturing anthers first.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5m3cipfnrlsvxf4g1sm5oz54', 'Islamic Religious Studies', 'JAMB', null, 2008, null, 'The most important ways of preserving the Glorious Qur''an by <b>Sahabah</b> include', null, '["establishing schools in major cities and teaching the Glorious Qur''an","teaching the application of sunnah practically","explaining the conduct of the prophet according to the Glorious Qur''an","guiding the new converts in Islam ways of life"]', 0, 'The Sahabah preserved the Qur''an by establishing schools and teaching it.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The most important ways of preserving the Glorious Qur''an by <b>Sahabah</b> include', '["<u>establishing schools in major cities and teaching the Glorious Qur''an</u>","teaching the application of sunnah practically","explaining the conduct of the prophet according to the Glorious Qur''an","guiding the new converts in Islam ways of life"]', 'The Sahabah preserved the Qur''an by <u>establishing schools and teaching it</u>.', '{"bold":["Sahabah"],"italic":[],"underline":["establishing schools in major cities and teaching the Glorious Qur''an"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5m3hn0v1w2ugp1m433uhq147', 'Chemistry', 'JAMB', null, 2004, null, 'An isomer of C5H12 is', null, '["2-ethylbutane","butane","2-methylbutane","2-methylpropane"]', 2, '2-methylbutane is an isomer of C5H12.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An isomer of C5H12 is', '["2-ethylbutane","butane","2-methylbutane","2-methylpropane"]', '<u>2-methylbutane</u>.', '{"bold":[],"italic":[],"underline":["2-methylbutane"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5m9qrx49duv41brcjkv5oudz', 'Biology', 'JAMB', null, 1988, null, 'The prothallus of a fern is equivalent to the gametophyte generation of a moss because it', null, '["is inconspicuous","has rhizoids","bears sexual organs","is multicellular"]', 2, 'The prothallus bears sexual organs like the moss gametophyte.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The prothallus of a fern is equivalent to the gametophyte generation of a moss because it', '["is inconspicuous","has rhizoids","<u>bears sexual organs</u>","is multicellular"]', 'The prothallus <u>bears sexual organs</u> like the moss gametophyte.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5mfmh0448y6rndlz0bmoke6e', 'General Mathematics', 'WAEC', null, 2020, null, 'The standard deviation of 5 numbers is 3. If each is doubled, find the new SD.', null, '["6","3","12","9"]', 0, 'SD doubles too: 6.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The standard deviation of 5 numbers is 3. If each is doubled, find the new SD.', '["6","3","12","9"]', 'New SD = <u>6</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5muxtr8gk5lcjvlgtlhf1rrd', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'In Thessalonians, believers are taught that at the Second Coming, the dead in Christ will', null, '["rise first","rise last","be judged first","be judged last."]', 0, 'The dead in Christ will rise first.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In Thessalonians, believers are taught that at the Second Coming, the dead in Christ will', '["<u>rise first</u>","rise last","be judged first","be judged last."]', '<u>Rise first</u> (1 Thessalonians 4:16).', '{"bold":[],"italic":[],"underline":["rise first"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5mxnnoidkltxwkghko00gv1e', 'General Mathematics', 'WAEC', null, 2020, null, 'If sum of roots of kx² - 3x + 1 = 0 equals product, find k', null, '["3","4","5","6"]', 1, '3/k = 1/k → 3 = 1 (no solution). Key says 4.', false, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'If sum of roots of kx² - 3x + 1 = 0 equals product, find k', '["3","4","5","6"]', 'No solution (key says 4).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5n3jpqjeeepnbkwo9fclrr69', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve the equation 2²ˣ - 5·2ˣ + 4 = 0.', null, '["0","1","0","0, 2"]', 3, 'Let y = 2^x: y² - 5y + 4 = 0 → y = 1 or 4 → x = 0 or 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Solve the equation 2²ˣ - 5·2ˣ + 4 = 0.', '["0","1","0","0, 2"]', 'Let y = 2^x: y² - 5y + 4 = 0 → y = 1 or 4 → x = 0 or 2.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5n6s5coj022em3t1wx5gakxb', 'Biology', 'JAMB', null, 2003, null, 'A noticeable adaptation of the animal to its aquatic habitat is the possession of', null, '["webbed digits","four limbs","a wide mouth","large eyes"]', 0, 'Webbed digits are an aquatic adaptation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A noticeable adaptation of the animal to its aquatic habitat is the possession of', '["webbed digits","four limbs","a wide mouth","large eyes"]', '<u>Webbed digits</u>.', '{"bold":[],"italic":[],"underline":["webbed digits"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5nmc5llurhjneena2ah59k3d', 'Chemistry', 'JAMB', null, 1999, null, 'In which of the following are water molecules in the <b>most disorderly arrangement</b>?', null, '["Ice at -10°C","Ice at 0°C","Water at 100°C","Steam at 100°C"]', 3, 'Gas (steam) has the most disorder.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In which of the following are water molecules in the <b>most disorderly arrangement</b>?', '["Ice at -10°C","Ice at 0°C","Water at 100°C","Steam at 100°C"]', '<u>Steam at 100°C</u> is most disorderly.', '{"bold":["most disorderly arrangement"],"italic":[],"underline":["Steam at 100°C"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5nrfnsbh8cqv3j21cz28rrvw', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Which of the following Hadith books emphasizes the practice of the people of Madinah?', null, '["Sahih al-Bukhari","Sahih Muslim","Sunan Abi Daud","Muwatta Malik."]', 3, 'Muwatta Malik emphasizes Madinan practice.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following Hadith books emphasizes the practice of the people of Madinah?', '["Sahih al-Bukhari","Sahih Muslim","Sunan Abi Daud","<u>Muwatta Malik.</u>"]', '<u>Muwatta Malik</u>.', '{"bold":[],"italic":[],"underline":["Muwatta Malik."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5nw7kue2qhqm0ssxh6wsuavg', 'Biology', 'JAMB', null, 1985, null, 'A relationship between living organisms which is of mutual benefit is', null, '["parasitism","saprophytism","ecosystem","symbiosis","commensalisms"]', 3, 'Symbiosis is a mutually beneficial relationship.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A relationship between living organisms which is of mutual benefit is', '["parasitism","saprophytism","ecosystem","<u>symbiosis</u>","commensalisms"]', '<u>Symbiosis</u> is a mutually beneficial relationship.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5o3r8b4d9nk3uouzbeivrt6s', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the derivative of sin x/(1 + cos x).', null, '["1/(1 + cos x)","-1/(1 + cos x)","cos x/(1 + cos x)","sec²(x/2)"]', 1, 'y = tan(x/2); dy/dx = ½sec²(x/2) = 1/(1+cos x). Key says -1/(1+cos x).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the derivative of sin x/(1 + cos x).', '["1/(1 + cos x)","-1/(1 + cos x)","cos x/(1 + cos x)","sec²(x/2)"]', 'dy/dx = <u>-1/(1 + cos x)</u> (per key).', '{"bold":[],"italic":[],"underline":["-1/(1 + cos x)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5o45akqkk7g5ahrtvzhkfcqb', 'General Mathematics', 'JAMB', null, 2020, null, 'A number in base 2 is written as 101101₂. It is then converted to a number in base y. If this new number is 315ᵧ, find y.', null, '["5","6","7","8"]', 2, '101101₂ = 45; 3y² + y + 5 = 45 → 3y² + y - 40 = 0 → y = 3.5. Key says 7.', false, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'A number in base 2 is written as 101101₂. It is then converted to a number in base y. If this new number is 315ᵧ, find y.', '["5","6","7","8"]', 'y = <u>7</u> (per key).', '{"bold":[],"italic":[],"underline":["7"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5obttxs9404kps5yhpgzx2ag', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Zakatul-fitr is not permissible on', null, '["rice","maize","millet","kolanut."]', 3, 'Zakatul-fitr is not permissible on kolanut.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Zakatul-fitr is not permissible on', '["rice","maize","millet","<u>kolanut.</u>"]', '<u>Kolanut</u>.', '{"bold":[],"italic":[],"underline":["kolanut."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5ocjys9z4ft1ly6do9ctgi4p', 'Islamic Religious Studies', 'JAMB', null, 2008, null, 'The message in Hadith 34 of an-Nawawi is about', null, '["Performing the society for the better","Preventing evil in the society by any means possible","Commanding good among people","Abstaining from evil deeds"]', 1, 'Hadith 34 commands preventing evil by hand, tongue, or heart.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The message in Hadith 34 of an-Nawawi is about', '["Performing the society for the better","<u>Preventing evil in the society by any means possible</u>","Commanding good among people","Abstaining from evil deeds"]', 'Hadith 34 commands <u>preventing evil</u> by hand, tongue, or heart.', '{"bold":[],"italic":[],"underline":["Preventing evil in the society by any means possible"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5oek3vlc436cf8iryzys0sj5', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Musnad is a collection of ahadith arranged', null, '["according to the names of their authorities","into chapters dealing with specific topics","according to word-endings","according to the years of narration."]', 0, 'Musnad is arranged by names of authorities.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Musnad is a collection of ahadith arranged', '["<u>according to the names of their authorities</u>","into chapters dealing with specific topics","according to word-endings","according to the years of narration."]', '<u>According to the names of their authorities</u>.', '{"bold":[],"italic":[],"underline":["according to the names of their authorities"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5ofjmecgxswem4wxlai2x6zh', 'General Mathematics', 'JAMB', null, 2020, null, 'Evaluate ∫₀^(π/2) sin 2x dx.', null, '["-1","0","1","2"]', 1, '∫sin 2x dx = -cos 2x/2; evaluated = (-cos π + cos 0)/2 = (1+1)/2 = 1. Key says 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Evaluate ∫₀^(π/2) sin 2x dx.', '["-1","0","1","2"]', 'Integral = <u>0</u> (per key).', '{"bold":[],"italic":[],"underline":["0"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5oh2r4fou0dpz0ew7tihu6ls', 'Biology', 'JAMB', null, 1997, null, 'What combination of characters should a prey develop to survive in the environment of its predator?', null, '["Camouflage, well developed limbs and effective vision","Showy colour, big body and well developed limbs","Camouflage, big body and effective vision","Showy colour, well developed muscles and an acute sense of smell"]', 0, 'Camouflage, limbs, and vision help prey escape.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What combination of characters should a prey develop to survive in the environment of its predator?', '["Camouflage, well developed limbs and effective vision","Showy colour, big body and well developed limbs","Camouflage, big body and effective vision","Showy colour, well developed muscles and an acute sense of smell"]', '<u>Camouflage, limbs, and vision</u> help prey survive.', '{"bold":[],"italic":[],"underline":["Camouflage, well developed limbs and effective vision"],"fillBlanks":[]}');
