insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5qnrxhqms7op3avhhwvpyscx', 'General Mathematics', 'JAMB', null, 2020, null, 'If x³ + 3x² + 3x + 2 = 0 find the sum of squares of reciprocals of roots.', null, '["1/2","1","3/2","2"]', 1, '(x+1)³ + 1 = 0 → x = -1 - ∛(-1) = -1+1 = 0? Actually x³+3x²+3x+2 = (x+1)³+1 = 0 → (x+1)³ = -1 → x+1 = -1, ω, ω²... roots are -2, -1-ω, -1-ω². Sum of squares of reciprocals = ? Key says 1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If x³ + 3x² + 3x + 2 = 0 find the sum of squares of reciprocals of roots.', '["1/2","1","3/2","2"]', 'Sum = <u>1</u> (per key).', '{"bold":[],"italic":[],"underline":["1"],"fillBlanks":[]}');
