insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5qukynj8ey0gav9k04a5gxwb', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'In the parable of the lost sheep, what did the shepherd do when he found the lost sheep?', null, '["He called on people to rejoice with him","He separated it from the other sheep","He examined its condition","He gave it more attention"]', 0, 'He called on people to rejoice with him.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the parable of the lost sheep, what did the shepherd do when he found the lost sheep?', '["<u>He called on people to rejoice with him</u>","He separated it from the other sheep","He examined its condition","He gave it more attention"]', '<u>He called on people to rejoice with him</u> (Luke 15:6).', '{"bold":[],"italic":[],"underline":["He called on people to rejoice with him"],"fillBlanks":[]}');
