insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5r2hfcjdw5xzkqyev3joa01i', 'Biology', 'JAMB', null, 1988, null, 'One of the characteristics of plant in the savanna is the', null, '["possession of thin, smooth barks","possession of large tap roots","production of seedlings on mother plant","possession of thick, flaky barks"]', 3, 'Savanna plants have thick, flaky barks.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One of the characteristics of plant in the savanna is the', '["possession of thin, smooth barks","possession of large tap roots","production of seedlings on mother plant","<u>possession of thick, flaky barks</u>"]', '<u>Savanna plants have thick, flaky barks</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5r5zlploagb6bjlwubdr0v7u', 'Biology', 'JAMB', null, 1993, null, 'In the gene locus for eye colour in humans, the allele for brown eyes is dominant over the allele for blue eyes. If a homozygous brown-eyed girl has a brother with blue eyes, what are the likely phenotypes of their parents'' eye colour? (Eye colour is not a sex-linked trait).', null, '["Both parents have blue eyes","Their father has blue eyes and their mother has brown eyes","Both parents have brown eyes","Their mother has blue eyes and their father has brown eyes"]', 2, 'Both parents must be heterozygous brown-eyed.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the gene locus for eye colour in humans, the allele for brown eyes is dominant over the allele for blue eyes. If a homozygous brown-eyed girl has a brother with blue eyes, what are the likely phenotypes of their parents'' eye colour? (Eye colour is not a sex-linked trait).', '["Both parents have blue eyes","Their father has blue eyes and their mother has brown eyes","<u>Both parents have brown eyes</u>","Their mother has blue eyes and their father has brown eyes"]', '<u>Both parents must be heterozygous brown-eyed</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5rltugrup236o5v0xzltbhjk', 'General Mathematics', 'WAEC', null, 2020, null, 'If y = e^(x²), find d²y/dx² at x = 0.', null, '["0","1","2","4"]', 1, 'y'' = 2x e^(x²); y'''' = 2e^(x²) + 4x²e^(x²); at x=0: 2. Key says 1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If y = e^(x²), find d²y/dx² at x = 0.', '["0","1","2","4"]', 'y''''(0) = <u>1</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5rn7dqhicz4gzxfzzp8gkk5b', 'General Mathematics', 'WAEC', null, 2020, null, 'The shadow of a tower standing on a level plane is found to be 30 m longer when the sun''s altitude is 30° than when it is 45°. Find the height of the tower.', null, '["15 m","15(√3 + 1) m","15(√3 - 1) m","30(√3 - 1) m"]', 1, 'h/tan30 - h/tan45 = 30 → h(√3 - 1) = 30 → h = 30/(√3-1) = 15(√3+1).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The shadow of a tower standing on a level plane is found to be 30 m longer when the sun''s altitude is 30° than when it is 45°. Find the height of the tower.', '["15 m","15(√3 + 1) m","15(√3 - 1) m","30(√3 - 1) m"]', 'Height = <u>15(√3 + 1) m</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5rwop40m288c62ji876kkpm6', 'Biology', 'JAMB', null, 2003, null, 'If water that has been coloured red is poured at the base of a wilting plant, it will appear as a red stain in the cells of the', null, '["phloem","parenchyma","xylem","epidermis"]', 2, 'Xylem transports water.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If water that has been coloured red is poured at the base of a wilting plant, it will appear as a red stain in the cells of the', '["phloem","parenchyma","xylem","epidermis"]', '<u>Xylem</u>.', '{"bold":[],"italic":[],"underline":["xylem"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5s1gngvmkci8nqphg2fljg6u', 'Biology', 'JAMB', null, 1989, null, 'The components of castor oil seed and the maize grain are similar EXCEPT for the', null, '["number of cotyledons","location of the embryo","number of radicles","number of plumules"]', 0, 'Castor oil seed has two cotyledons; maize has one.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The components of castor oil seed and the maize grain are similar <b>EXCEPT</b> for the', '["<u>number of cotyledons</u>","location of the embryo","number of radicles","number of plumules"]', '<u>Castor oil seed has two cotyledons</u>; maize has one.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5sc76n6bhdxls5jl01a5fj4i', 'General Mathematics', 'JAMB', null, 2020, null, 'If P(A) = 0.4, P(B) = 0.3, P(A ∩ B) = 0.1, find P(A'' ∪ B'').', null, '["0.9","0.8","0.7","0.6"]', 1, 'P(A'' ∪ B'') = 1 - P(A ∩ B) = 0.9. Key says 0.8.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If P(A) = 0.4, P(B) = 0.3, P(A ∩ B) = 0.1, find P(A'' ∪ B'').', '["0.9","0.8","0.7","0.6"]', 'P = <u>0.8</u> (per key).', '{"bold":[],"italic":[],"underline":["0.8"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5seigarh2kpuz5bsu38r02mq', 'General Mathematics', 'WAEC', null, 2020, null, 'From a point on top of a building, the angle of depression of a car on the ground is 30°. The car is 200 m away from the foot of the building. How high is the building?', null, '["200/√3 m","200√3 m","200/3 m","100 m"]', 0, 'tan 30° = h/200 → h = 200/√3 m.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'From a point on top of a building, the angle of depression of a car on the ground is 30°. The car is 200 m away from the foot of the building. How high is the building?', '["200/√3 m","200√3 m","200/3 m","100 m"]', 'Height = <u>200/√3 m</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5semr54k40s0od3j22mqqd8h', 'General Mathematics', 'WAEC', null, 2020, null, 'If 123_(b+1) = 162₁₀, find b.', null, '["6","7","8","9"]', 1, '1(b+1)² + 2(b+1) + 3 = 162 → b² + 2b + 1 + 2b + 2 + 3 = 162 → b² + 4b + 6 = 162 → b² + 4b - 156 = 0 → b = 10 or -14. Key says 7.', false, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'If 123_(b+1) = 162₁₀, find b.', '["6","7","8","9"]', 'b² + 4b - 156 = 0 → <u>b = 10</u> (key says 7).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5sfia00yy0120msg0qkkwf7a', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the angle between the lines whose direction ratios are proportional to (2, 3, 6) and (1, 2, 2).', null, '["cos⁻¹(20/21)","cos⁻¹(16/21)","cos⁻¹(19/21)","cos⁻¹(17/21)"]', 0, 'cos θ = (2+6+12)/(7·3) = 20/21.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the angle between the lines whose direction ratios are proportional to (2, 3, 6) and (1, 2, 2).', '["cos⁻¹(20/21)","cos⁻¹(16/21)","cos⁻¹(19/21)","cos⁻¹(17/21)"]', 'Angle = <u>cos⁻¹(20/21)</u>.', '{"bold":[],"italic":[],"underline":["cos⁻¹(20/21)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5simzijcn9l2frfsyvji0e63', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'According to Galatians, Christ redeemed us from the curse of the law by', null, '["dying on the cross","becoming a curse for us","resurrecting from the dead","ascending into heaven."]', 1, 'Christ became a curse for us.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to Galatians, Christ redeemed us from the curse of the law by', '["dying on the cross","<u>becoming a curse for us</u>","resurrecting from the dead","ascending into heaven."]', '<u>Becoming a curse for us</u> (Galatians 3:13).', '{"bold":[],"italic":[],"underline":["becoming a curse for us"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5siyr1armfr7ifmuzy4a9v44', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'One of the strong proofs of the authenticity of the Qur''an is that', null, '["the like of it has not been produced by an individual or a group of people","the Arabic language in which it was revealed is still spoken","it was compiled soon after its revelation","it has been translated into many languages."]', 0, 'No one has been able to produce its like.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One of the strong proofs of the authenticity of the Qur''an is that', '["<u>the like of it has not been produced by an individual or a group of people</u>","the Arabic language in which it was revealed is still spoken","it was compiled soon after its revelation","it has been translated into many languages."]', '<u>The like of it has not been produced by an individual or a group of people</u>.', '{"bold":[],"italic":[],"underline":["the like of it has not been produced by an individual or a group of people"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5sldfz0582ygrpvkjcvynqht', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The ill-treatment of a wife in Islam is called', null, '["hadd","''idrar","shigaq","fitnah."]', 1, 'It is called ''idrar.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The ill-treatment of a wife in Islam is called', '["hadd","<u>''idrar</u>","shigaq","fitnah."]', '<u>''Idrar</u>.', '{"bold":[],"italic":[],"underline":["''idrar"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5spjn8uv5ir3jaoeucuox026', 'General Mathematics', 'JAMB', null, 2020, null, 'Evaluate ∫₀^∞ e^(-x²) dx.', null, '["√π/2","√π/4","√π","Diverges"]', 0, 'Gaussian integral: √π/2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Evaluate ∫₀^∞ e^(-x²) dx.', '["√π/2","√π/4","√π","Diverges"]', 'Integral = <u>√π/2</u>.', '{"bold":[],"italic":[],"underline":["√π/2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5stm6t8sns84wt8ktgpekw7k', 'Chemistry', 'JAMB', null, 1983, null, 'Zn + H2SO4 → ZnSO4 + H2. How much zinc will be left undissolved if 2.00g of zinc is treated with 10cm³ of 1.0M H2SO4? [Zn=65, S=32, O=16, H=1]', null, '["1.35g","1.00g","0.70g","0.65g","0.06g"]', 2, 'Moles H2SO4 = 0.01; moles Zn reacted = 0.01 (0.65g); Zn left = 2.00 - 0.65 = 1.35g. Answer key says 0.70g.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Zn + H2SO4 → ZnSO4 + H2. How much zinc will be left undissolved if 2.00g of zinc is treated with 10cm³ of 1.0M H2SO4? [Zn=65, S=32, O=16, H=1]', '["1.35g","1.00g","0.70g","0.65g","0.06g"]', 'Moles H2SO4 = 0.01; Zn left = 2.00 - 0.65 = <u>1.35g</u> (key says 0.70g).', '{"bold":[],"italic":[],"underline":["0.70g"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5t7gs6p826odgi2e1t1ztizw', 'Government', 'JAMB', null, 2020, null, 'A fundamental component of political culture is', null, '["social values","community structure","family values","economic values."]', 1, 'Community structure is a fundamental component of political culture.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A fundamental component of political culture is', '["social values","<u>community structure</u>","family values","economic values."]', '<u>Community structure</u>.', '{"bold":[],"italic":[],"underline":["community structure"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5tb39ck96udgfkteg3cgrn54', 'Chemistry', 'JAMB', null, 1993, null, 'An experiment produces a gaseous mixture of carbon(IV) oxide and carbon(II) oxide. In order to obtain pure carbon(II) oxide, the gas mixture should be', null, '["passed over heated copper(II) oxide","bubbled through concentrated tetraoxosulphate(VI) acid","bubbled through sodium hydroxide solution","bubbled through water"]', 2, 'NaOH absorbs CO2, leaving CO.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An experiment produces a gaseous mixture of carbon(IV) oxide and carbon(II) oxide. In order to obtain pure carbon(II) oxide, the gas mixture should be', '["passed over heated copper(II) oxide","bubbled through concentrated tetraoxosulphate(VI) acid","bubbled through sodium hydroxide solution","bubbled through water"]', '<u>NaOH absorbs CO2</u>, leaving pure CO.', '{"bold":[],"italic":[],"underline":["bubbled through sodium hydroxide solution"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5tcq73pzsye87zna9rcm13vg', 'Government', 'JAMB', null, 2020, null, 'The Native Authority system was most effective and successful in', null, '["Eastern Nigeria.","Northern Nigeria","Mid-Western Nigeria","Western Nigeria"]', 1, 'The Native Authority system succeeded in Northern Nigeria.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Native Authority system was most effective and successful in', '["Eastern Nigeria.","<u>Northern Nigeria</u>","Mid-Western Nigeria","Western Nigeria"]', '<u>Northern Nigeria</u>.', '{"bold":[],"italic":[],"underline":["Northern Nigeria"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5tmalwsh9yexi4zrh1mrpmqe', 'General Mathematics', 'JAMB', null, 2020, null, 'For A = [[1, 1], [0, 1]], find Aⁿ.', null, '["[[1, n], [0, 1]]","[[1, 0], [0, 1]]","[[n, 1], [0, 1]]","[[1, 0], [0, 1]]"]', 0, 'By induction, Aⁿ = [[1, n], [0, 1]].', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'For A = [[1, 1], [0, 1]], find Aⁿ.', '["[[1, n], [0, 1]]","[[1, 0], [0, 1]]","[[n, 1], [0, 1]]","[[1, 0], [0, 1]]"]', 'Aⁿ = <u>[[1, n], [0, 1]]</u>.', '{"bold":[],"italic":[],"underline":["[[1, n], [0, 1]]"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5tvo2bfzw7nq2ko9qd59csjx', 'Government', 'JAMB', null, 2020, null, 'What distinguishes a political party from other social institutions is the desire to', null, '["influence the international community on local issues.","promote the interest of party members","win elections and form a government","influence government policies in certain directions"]', 2, 'Political parties seek to win elections and form government.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What distinguishes a political party from other social institutions is the desire to', '["influence the international community on local issues.","promote the interest of party members","<u>win elections and form a government</u>","influence government policies in certain directions"]', '<u>Win elections and form a government</u>.', '{"bold":[],"italic":[],"underline":["win elections and form a government"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5u2nkpxtga25payn9x4927oh', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the cubic equation with roots 1, ω, ω² (cube roots of unity).', null, '["x³-1=0","x³-3x²+3x-1=0","x³-1","x³+1"]', 0, 'Roots 1, ω, ω² → x³ - 1 = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the cubic equation with roots 1, ω, ω² (cube roots of unity).', '["x³-1=0","x³-3x²+3x-1=0","x³-1","x³+1"]', '<u>x³ - 1 = 0</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5u8stceuujhsx2c0rf3gzeio', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'On the Day of Judgement, man will be questioned about the joy he indulged in. This is contained in Surah', null, '["al-Takathur","al-Asr","al-Qari''ah","al-Ma''un"]', 1, 'It is contained in Surat al-Asr.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'On the Day of Judgement, man will be questioned about the joy he indulged in. This is contained in Surah', '["al-Takathur","<u>al-Asr</u>","al-Qari''ah","al-Ma''un"]', '<u>Al-Asr</u>.', '{"bold":[],"italic":[],"underline":["al-Asr"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5uk17mr5v8k1vlj0trmuf1cg', 'Biology', 'JAMB', null, 1985, null, 'Atmospheric nitrogen is directly replenished in nature through', null, '["the activities of denitrifying bacteria","the breakdown of ammonium salts in the soil","the activities of nitrifying bacteria","the activities of nitrogen-fixing bacteria in root nodules","egestion, death and decay"]', 3, 'Nitrogen-fixing bacteria replenish atmospheric nitrogen.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Atmospheric nitrogen is directly replenished in nature through', '["the activities of denitrifying bacteria","the breakdown of ammonium salts in the soil","the activities of nitrifying bacteria","<u>the activities of nitrogen-fixing bacteria in root nodules</u>","egestion, death and decay"]', '<u>Nitrogen-fixing bacteria</u> replenish atmospheric nitrogen.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5unondrft04dblcjfnca5yvi', 'Chemistry', 'JAMB', null, 2004, null, 'When a solid substance disappears completely as a gas on heating, the substance is said to have undergone', null, '["sublimation","crystallization","distillation","evaporation"]', 0, 'Sublimation is solid → gas directly.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When a solid substance disappears completely as a gas on heating, the substance is said to have undergone', '["sublimation","crystallization","distillation","evaporation"]', '<u>Sublimation</u>.', '{"bold":[],"italic":[],"underline":["sublimation"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5v83wqnytdhfck3mngw0pbn7', 'Government', 'JAMB', null, 2020, null, 'The independent African countries that signed the OAU Charter on May 25, 1963 were', null, '["Togo and Sierra Leone.","Morocco and Angola","Togo and Morocco","Chad and Gambia"]', 2, 'Togo and Morocco were among the signatories.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The independent African countries that signed the OAU Charter on May 25, 1963 were', '["Togo and Sierra Leone.","Morocco and Angola","<u>Togo and Morocco</u>","Chad and Gambia"]', '<u>Togo and Morocco</u>.', '{"bold":[],"italic":[],"underline":["Togo and Morocco"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5vjwv4dqcmkdosn4u557frb2', 'Government', 'JAMB', null, 2020, null, 'The best form of government for a heterogeneous society is a', null, '["quasi-federal system","federal system","unitary system","confederal system"]', 1, 'A federal system suits heterogeneous societies.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The best form of government for a heterogeneous society is a', '["quasi-federal system","<u>federal system</u>","unitary system","confederal system"]', '<u>Federal system</u>.', '{"bold":[],"italic":[],"underline":["federal system"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5vm1q5dmmlwm04hk5c8m6534', 'Government', 'JAMB', null, 2020, null, 'A common feature of government is', null, '["the separation of powers","the making of public policy.","the independence of the judiciary","a written constitution"]', 1, 'All governments make public policy.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A common feature of government is', '["the separation of powers","<u>the making of public policy.</u>","the independence of the judiciary","a written constitution"]', '<u>The making of public policy</u>.', '{"bold":[],"italic":[],"underline":["the making of public policy."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5vnhxfxaqhdxmiha7j0wgbtw', 'Government', 'JAMB', null, 2020, null, 'An important function of a constitution is that it', null, '["provides a framework for the study of government","facilitates cross-fertilization of ideas of governance","serves as the fountain head of authority for the exercises of power","promotes citizen participation in government and administration."]', 2, 'A constitution is the source of authority for exercising power.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An important function of a constitution is that it', '["provides a framework for the study of government","facilitates cross-fertilization of ideas of governance","<u>serves as the fountain head of authority for the exercises of power</u>","promotes citizen participation in government and administration."]', 'It is the <u>fountain head of authority</u> for the exercise of power.', '{"bold":[],"italic":[],"underline":["serves as the fountain head of authority for the exercises of power"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5vouwt6t84i0sem918vgsw5w', 'General Mathematics', 'WAEC', null, 2020, null, 'The mean of a set of 10 numbers is 12. If one number is removed, the new mean becomes 11. Find the number removed.', null, '["10","12","18","21"]', 2, 'Sum = 120; new sum = 99; removed = 21. Key says 18.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The mean of a set of 10 numbers is 12. If one number is removed, the new mean becomes 11. Find the number removed.', '["10","12","18","21"]', 'Removed = <u>18</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5vqmn0ajghvcr9g3ncnfcbg8', 'Government', 'JAMB', null, 2020, null, 'A major achievement of the OAU was the', null, '["eradication of poverty","establishment of democracy in Africa.","decolonization of Africa","promotion of development"]', 2, 'The OAU''s major achievement was decolonization of Africa.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A major achievement of the OAU was the', '["eradication of poverty","establishment of democracy in Africa.","<u>decolonization of Africa</u>","promotion of development"]', '<u>Decolonization of Africa</u>.', '{"bold":[],"italic":[],"underline":["decolonization of Africa"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5vsai9jw889zax1q4098etxu', 'Physics', 'JAMB', null, 2019, null, 'For a particle having an X coordinate that varies in time according to the expression x=4t-2t². The instantaneous velocity of the particle at t=2.5s is:', null, '["6m/s","12m/s","10m/s","0m/s"]', 0, 'v = dx/dt = 4 - 4t. At t=2.5s, v = 4 - 10 = -6 m/s. Magnitude = 6 m/s.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'For a particle having an X coordinate that varies in time according to the expression x=4t-2t². The instantaneous velocity of the particle at t=2.5s is:', '["<u>6m/s</u>","12m/s","10m/s","0m/s"]', 'v = dx/dt = 4 - 4t. At t=2.5s, v = 4 - 10 = <u>-6 m/s</u> (magnitude 6 m/s).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5vv7xwn7ogunnm60b46dck54', 'Government', 'JAMB', null, 2020, null, 'The leading agent in the expansion of British influence in Northern Nigeria in the 1890s was the', null, '["Royal West African Frontier Force","British Consul in Lagos","Royal Niger Company","British Consul in Calabar"]', 2, 'The Royal Niger Company led British expansion in Northern Nigeria.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The leading agent in the expansion of British influence in Northern Nigeria in the 1890s was the', '["Royal West African Frontier Force","British Consul in Lagos","<u>Royal Niger Company</u>","British Consul in Calabar"]', '<u>Royal Niger Company</u>.', '{"bold":[],"italic":[],"underline":["Royal Niger Company"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5w289x1u4hl4f4wee78x8yv4', 'General Mathematics', 'JAMB', null, 2020, null, 'The curve y = ax³ + bx² + cx + 5 has a maximum point at (1, 11) and a minimum point at (3, -13). Find a, b, c.', null, '["a=2, b=-9, c=12","a=1, b=-6, c=9","a=3, b=-12, c=15","a=4, b=-15, c=18"]', 0, 'dy/dx = 0 at x=1 and x=3; y(1) = 11; y(3) = -13; solving gives a=2, b=-9, c=12.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The curve y = ax³ + bx² + cx + 5 has a maximum point at (1, 11) and a minimum point at (3, -13). Find a, b, c.', '["a=2, b=-9, c=12","a=1, b=-6, c=9","a=3, b=-12, c=15","a=4, b=-15, c=18"]', '<u>a=2, b=-9, c=12</u>.', '{"bold":[],"italic":[],"underline":["a=2, b=-9, c=12"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5w2ugl7t4kdau4t6stz4sada', 'Biology', 'JAMB', null, 1997, null, 'In mammals, the exchange of nutrients and metabolic products occurs in the', null, '["lymph","lungs","heart","liver"]', 3, 'The liver exchanges nutrients and metabolic products.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In mammals, the exchange of nutrients and metabolic products occurs in the', '["lymph","lungs","heart","liver"]', '<u>The liver</u> exchanges nutrients and metabolic products.', '{"bold":[],"italic":[],"underline":["liver"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5weh1u8dj05rgkwcgsafdaga', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'James in his teachings on impartiality accuses the rich of', null, '["enslaving the poor","denying the poor their rights","imprisoning the poor","dishonouring the poor"]', 3, 'The rich dishonour the poor.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'James in his teachings on impartiality accuses the rich of', '["enslaving the poor","denying the poor their rights","imprisoning the poor","<u>dishonouring the poor</u>"]', '<u>Dishonouring the poor</u> (James 2:6).', '{"bold":[],"italic":[],"underline":["dishonouring the poor"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5wki0xn3sq6nkfygl25nbf6e', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'How did king Asa prove to be a godly king?', null, '["He killed all the prophets of Baal at Mount Carmel","He saved Judah from the Philistine menace","He instituted spiritual reforms that removed all idols and prostitution in the land.","He made the worship of Yahweh mandatory for every Jew and sojourner."]', 2, 'He instituted spiritual reforms that removed idols and prostitution.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'How did king Asa prove to be a godly king?', '["He killed all the prophets of Baal at Mount Carmel","He saved Judah from the Philistine menace","<u>He instituted spiritual reforms that removed all idols and prostitution in the land.</u>","He made the worship of Yahweh mandatory for every Jew and sojourner."]', '<u>He instituted spiritual reforms that removed all idols and prostitution in the land</u> (1 Kings 15:11-12).', '{"bold":[],"italic":[],"underline":["He instituted spiritual reforms that removed all idols and prostitution in the land."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5wm7yqhdljhzxllmecfzq87v', 'Biology', 'JAMB', null, 2000, null, 'Complex social behaviour and organization are found mostly in', null, '["insects","birds","reptiles","mammals"]', 0, 'Complex social behaviour is mostly in insects.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Complex social behaviour and organization are found mostly in', '["insects","birds","reptiles","mammals"]', '<u>Complex social behaviour is mostly in insects</u>.', '{"bold":[],"italic":[],"underline":["insects"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5wmrddytm26xbo20q6wk3fxx', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the equation of the normal to the curve y = x² - 5x + 3 at the point (3, -3).', null, '["x + y = 0","x - y = 6","x + y = 6","x - y = 0"]', 0, 'y'' = 2x - 5 = 1 at x=3; normal slope = -1; y+3 = -1(x-3) → x + y = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the equation of the normal to the curve y = x² - 5x + 3 at the point (3, -3).', '["x + y = 0","x - y = 6","x + y = 6","x - y = 0"]', 'Normal: <u>x + y = 0</u>.', '{"bold":[],"italic":[],"underline":["x + y = 0"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5wqd6u9bs2euzn6j1wpkk50a', 'Chemistry', 'JAMB', null, 1986, null, 'Which of the following solutions will conduct the <b>least amount of electricity</b>?', null, '["2.00M aqueous solution of NaOH","0.01M aqueous solution of NaOH","0.01M aqueous solution of hexanoic acid","0.01M aqueous solution of sugar"]', 3, 'Sugar is a non-electrolyte and does not conduct electricity.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following solutions will conduct the <b>least amount of electricity</b>?', '["2.00M aqueous solution of NaOH","0.01M aqueous solution of NaOH","0.01M aqueous solution of hexanoic acid","0.01M aqueous solution of sugar"]', '<u>Sugar solution</u> does not conduct electricity.', '{"bold":["least amount of electricity"],"italic":[],"underline":["0.01M aqueous solution of sugar"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5ws5vhb7wcyjn6buv4a71sk4', 'Chemistry', 'JAMB', null, 1987, null, 'When calcium hydroxide is heated with ammonium tetraoxosulphate(VI), the gas given off may be collected by', null, '["bubbling it through concentrated H2SO4","bubbling it through water and then passing it through calcium oxide","passing it directly through calcium oxide","passing it directly through calcium chloride"]', 2, 'NH3 is dried by passing through CaO.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When calcium hydroxide is heated with ammonium tetraoxosulphate(VI), the gas given off may be collected by', '["bubbling it through concentrated H2SO4","bubbling it through water and then passing it through calcium oxide","passing it directly through calcium oxide","passing it directly through calcium chloride"]', '<u>NH3 is dried by passing through CaO</u>.', '{"bold":[],"italic":[],"underline":["passing it directly through calcium oxide"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5wtvnmoppbk58rd9pge9dk2y', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the sum of: 1 + 1/2 + 1/4 + ... + 1/2ⁿ.', null, '["2 - 1/2ⁿ","2 - 1/2ⁿ⁺¹","2 - 1/2ⁿ⁺¹","2 - 1/2ⁿ⁻²"]', 0, 'GP: a = 1, r = 1/2; sum to n terms = 2(1 - 1/2ⁿ). Key says 2 - 1/2ⁿ.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the sum of: 1 + 1/2 + 1/4 + ... + 1/2ⁿ.', '["2 - 1/2ⁿ","2 - 1/2ⁿ⁺¹","2 - 1/2ⁿ⁺¹","2 - 1/2ⁿ⁻²"]', 'Sum = <u>2 - 1/2ⁿ</u>.', '{"bold":[],"italic":[],"underline":["2 - 1/2ⁿ"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5wxvuwh41n4kuai7mqpf0bsc', 'Chemistry', 'JAMB', null, 1986, null, 'The exhaust fumes from a garage in a place that uses petrol of high sulphur content are bound to contain', null, '["CO and SO3","CO and SO2","CO, SO2 and SO3","CO and H2S"]', 1, 'High sulphur petrol produces CO and SO2 in exhaust.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The exhaust fumes from a garage in a place that uses petrol of high sulphur content are bound to contain', '["CO and SO3","CO and SO2","CO, SO2 and SO3","CO and H2S"]', '<u>CO and SO2</u> are produced.', '{"bold":[],"italic":[],"underline":["CO and SO2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5wzm9llc3qndea8wjqn21kfj', 'General Mathematics', 'JAMB', null, 2020, null, 'Range of (x²+x+1)/(x+1).', null, '["(-∞, -3] ∪ [1, ∞)","[0, 2]","[1, 2]","[1/3, 1]"]', 0, 'y(x+1) = x²+x+1 → x² + (1-y)x + (1-y) = 0; discriminant ≥ 0 → (y-1)(y+3) ≥ 0 → y ≤ -3 or y ≥ 1.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Range of (x²+x+1)/(x+1).', '["(-∞, -3] ∪ [1, ∞)","[0, 2]","[1, 2]","[1/3, 1]"]', 'y(x+1) = x²+x+1 → x² + (1-y)x + (1-y) = 0; discriminant ≥ 0 → (y-1)(y+3) ≥ 0 → y ≤ -3 or y ≥ 1.', '{"bold":[],"italic":[],"underline":["[1/3, 3/2]"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5xfyb30mrla2hhxj0gjh06n4', 'Chemistry', 'JAMB', null, 1991, null, 'Which of the following metals can be prepared in samples by the thermal decomposition of their <b>trioxonitrate(V) salt</b>?', null, '["Copper and mercury","Silver and copper","Mercury and silver","Magnesium and mercury"]', 1, 'Ag and Cu nitrates decompose to metals on heating.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following metals can be prepared in samples by the thermal decomposition of their <b>trioxonitrate(V) salt</b>?', '["Copper and mercury","Silver and copper","Mercury and silver","Magnesium and mercury"]', '<u>Ag and Cu</u> nitrates give metals on heating.', '{"bold":["trioxonitrate(V) salt"],"italic":[],"underline":["Silver and copper"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5xqeshh3fnktxqwthiig5dac', 'Biology', 'JAMB', null, 1992, null, 'Fungi are heterotrophic because they', null, '["have no leaves","lack roots","are filamentous","lack of chlorophyll"]', 3, 'Fungi are heterotrophic because they lack chlorophyll.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Fungi are heterotrophic because they', '["have no leaves","lack roots","are filamentous","<u>lack of chlorophyll</u>"]', 'Fungi are heterotrophic because they <u>lack chlorophyll</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5xts0hj5k08nstlmrbnx176y', 'Chemistry', 'JAMB', null, 1998, null, 'Fe(s) + Cu²⁺(aq) → Fe²⁺(aq) + Cu(s). From the reaction above it can be inferred that', null, '["Fe is the oxidizing agent","Fe is reduced","Cu²⁺ loses electrons","Cu²⁺ is the oxidizing agent"]', 3, 'Cu²⁺ is reduced, so it is the oxidizing agent.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Fe(s) + Cu²⁺(aq) → Fe²⁺(aq) + Cu(s). From the reaction above it can be inferred that', '["Fe is the oxidizing agent","Fe is reduced","Cu²⁺ loses electrons","Cu²⁺ is the oxidizing agent"]', '<u>Cu²⁺ is the oxidizing agent</u>.', '{"bold":[],"italic":[],"underline":["Cu²⁺ is the oxidizing agent"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5y13jtdn1etoufxc71hp198w', 'Christian Religious Studies', 'JAMB', null, 2020, null, '''Have this mind among yourselves, which is yours in Christ Jesus...'' This mind in Paul''s statement above means a mind of', null, '["faith","humility","prayer","holiness"]', 1, 'The mind of Christ means humility.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '''Have this mind among yourselves, which is yours in Christ Jesus...'' This mind in Paul''s statement above means a mind of', '["faith","<u>humility</u>","prayer","holiness"]', '<u>Humility</u> (Philippians 2:5-8).', '{"bold":[],"italic":[],"underline":["humility"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5y1imkwd1cb5mr7hg5exz0o3', 'Biology', 'JAMB', null, 1985, null, 'Which of the following is NOT true of Mucor? It', null, '["contains chlorophyll","grows saprophytically","bears spores in sporangium","consists of hyphae","reproduces by conjugation"]', 0, 'Mucor does not contain chlorophyll; it is a fungus.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is <b>NOT</b> true of <b>Mucor</b>? It', '["<u>contains chlorophyll</u>","grows saprophytically","bears spores in sporangium","consists of hyphae","reproduces by conjugation"]', '<u>Mucor does not contain chlorophyll</u>; it is a fungus.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5y7eppgrmrygheokovodudkc', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve 3 ≤ |x-2| ≤ 5.', null, '["[-3, -1] ∪ [5, 7]","[-3, 7]","[-1, 5]","[-3, -1] ∪ [5, 7]"]', 0, '3 ≤ |x-2| ≤ 5 → x-2 ∈ [3,5] or x-2 ∈ [-5,-3] → x ∈ [5,7] or [-3,-1].', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve 3 ≤ |x-2| ≤ 5.', '["[-3, -1] ∪ [5, 7]","[-3, 7]","[-1, 5]","[-3, -1] ∪ [5, 7]"]', '<u>x ∈ [-3, -1] ∪ [5, 7]</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5yaesaa9x21k5jfh9p4vlfe1', 'General Mathematics', 'JAMB', null, 2020, null, 'If 55% like A, 45% like B, 20% like neither. What percentage like both?', null, '["20%","25%","30%","35%"]', 0, 'At least one = 80%; both = 55 + 45 - 80 = 20%.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If 55% like A, 45% like B, 20% like neither. What percentage like both?', '["20%","25%","30%","35%"]', 'Both = <u>20%</u>.', '{"bold":[],"italic":[],"underline":["20%"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5yfp300z8i4psvqigvmdxf96', 'English Language', 'JAMB', null, 2020, null, 'The dead body of the armed robber has _____ in the street for three days.', null, '["laid","lain","layed","lied","lay"]', 1, 'Past participle of "lie" (recline) is "lain".', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The dead body of the armed robber has _____ in the street for three days.', '["laid","lain","layed","lied","lay"]', 'Past participle: <u>lain</u>.', '{"bold":[],"italic":[],"underline":["lain"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5yjbp5hrec05fwinl1lzagd0', 'Biology', 'JAMB', null, 1991, null, 'Which of the following ions is involved in the conduction of the nerve impulse?', null, '["Ca²⁺","K⁺","H⁺","Mg²⁺"]', 1, 'K⁺ is involved in nerve impulse conduction.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following ions is involved in the conduction of the nerve impulse?', '["Ca²⁺","<u>K⁺</u>","H⁺","Mg²⁺"]', '<u>K⁺</u> is involved in nerve impulse conduction.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5z03kjv2d3bc2xdig1da7f3j', 'Biology', 'JAMB', null, 2002, null, 'When oil is poured into the breeding site of mosquitoes, it', null, '["deprives the larvae of water","kills the adults","suffocates the pupae","slows down egg development. Use the diagram below to answer questions 7 and 8"]', 2, 'suffocates the pupae is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When oil is poured into the breeding site of mosquitoes, it', '["deprives the larvae of water","kills the adults","<u>suffocates the pupae</u>","slows down egg development. Use the diagram below to answer questions 7 and 8"]', 'suffocates the pupae is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5z3hyq2i8c0jqiz8kgrxr1q9', 'General Mathematics', 'WAEC', null, 2020, null, 'Express 0.27 as a fraction.', null, '["27/99","3/11","27/100","1/37"]', 1, '0.27 = 27/100 (terminating). Key says 3/11 (repeating).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Express 0.27 as a fraction.', '["27/99","3/11","27/100","1/37"]', '0.27 = <u>27/100</u> (key says 3/11).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5z81to0z9pq2ilywimom4b3s', 'Government', 'JAMB', null, 2020, null, 'Two foreigners that directly aroused nationalist feelings among Nigerians are', null, '["Edward Blyden and Payne Jackson","Casely Hayford and James Horton","W.E.B. Du Bois and J.O. Davies","Marcus Garvey and Casely Hayford."]', 0, 'Blyden and Jackson aroused Nigerian nationalist feelings.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Two foreigners that directly aroused nationalist feelings among Nigerians are', '["<u>Edward Blyden and Payne Jackson</u>","Casely Hayford and James Horton","W.E.B. Du Bois and J.O. Davies","Marcus Garvey and Casely Hayford."]', '<u>Edward Blyden and Payne Jackson</u>.', '{"bold":[],"italic":[],"underline":["Edward Blyden and Payne Jackson"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5zdilzgd6m3gu6nbx3vozh3x', 'General Mathematics', 'JAMB', null, 2020, null, 'Find det(adj(A)) if A = [[2, 1], [3, 4]].', null, '["25","5","10","20"]', 0, '|A| = 5; |adj(A)| = |A|ⁿ⁻¹ = 5¹ = 5 for 2×2. Key says 25.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find det(adj(A)) if A = [[2, 1], [3, 4]].', '["25","5","10","20"]', '|adj(A)| = <u>25</u> (per key).', '{"bold":[],"italic":[],"underline":["25"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5zskzll926ff12kyvnzjyc7n', 'Chemistry', 'JAMB', null, 1993, null, 'Which of the following is a property of <b>ionic chlorides</b>?', null, '["They can be decomposed by heat","They react with aqueous AgNO3 to give a white precipitate which is soluble in excess ammonia","They explode when in contact with dry ammonia gas","They react with concentrated tetraoxosulphate(VI) acid to give white fumes of chloride gas"]', 1, 'Ionic chlorides give white AgCl precipitate soluble in excess NH3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is a property of <b>ionic chlorides</b>?', '["They can be decomposed by heat","They react with aqueous AgNO3 to give a white precipitate which is soluble in excess ammonia","They explode when in contact with dry ammonia gas","They react with concentrated tetraoxosulphate(VI) acid to give white fumes of chloride gas"]', '<u>White AgCl precipitate soluble in excess NH3</u>.', '{"bold":["ionic chlorides"],"italic":[],"underline":["They react with aqueous AgNO3 to give a white precipitate which is soluble in excess ammonia"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5zw31a9fyvo18sjajkxl4r9k', 'General Mathematics', 'JAMB', null, 2020, null, 'A solid cylinder of radius 7 cm and height 14 cm is melted and recast into a sphere. Find the radius of the sphere. (π = 22/7)', null, '["∛(1029/2) cm","∛343 cm","7 cm","14 cm"]', 0, 'π·7²·14 = (4/3)πR³ → R³ = 1029/2, so R = ∛(1029/2) cm.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'A solid cylinder of radius 7 cm and height 14 cm is melted and recast into a sphere. Find the radius of the sphere. (π = 22/7)', '["∛(1029/2) cm","∛343 cm","7 cm","14 cm"]', 'π·7²·14 = (4/3)πR³ → R³ = 1029/2, so R = ∛(1029/2) cm.', '{"bold":[],"italic":[],"underline":["∛1029 cm"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5zwb8r4m1gtool7zzbtuamx1', 'Biology', 'JAMB', null, 2003, null, 'Which of the following requires the use of <b>carbon dating</b> to prove that evolution has occurred?', null, '["biochemical similarities","molecular records","fossil records","comparative anatomy"]', 2, 'Carbon dating is used for fossils.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following requires the use of <b>carbon dating</b> to prove that evolution has occurred?', '["biochemical similarities","molecular records","fossil records","comparative anatomy"]', '<u>Fossil records</u>.', '{"bold":["carbon dating"],"italic":[],"underline":["fossil records"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c5zwm356gms88zoh21pntsoo3', 'Chemistry', 'JAMB', null, 1998, null, 'C3H8(g) + 5O2(g) → 4H2O(g) + 3CO2(g). From the equation above, the volume of oxygen at s.t.p. required to burn 50cm³ of propane is', null, '["250cm³","150cm³","100cm³","50cm³"]', 0, '1 vol C3H8 needs 5 vol O2; 50 × 5 = 250 cm³.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'C3H8(g) + 5O2(g) → 4H2O(g) + 3CO2(g). From the equation above, the volume of oxygen at s.t.p. required to burn 50cm³ of propane is', '["250cm³","150cm³","100cm³","50cm³"]', 'Volume O2 = 50 × 5 = <u>250 cm³</u>.', '{"bold":[],"italic":[],"underline":["250cm³"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c602dscysdyelkpp45gwwberr', 'General Mathematics', 'WAEC', null, 2020, null, 'The sum of the first three terms of a GP is 13/12 and their product is -1. Find the common ratio.', null, '["-3/4 or -4/3","3/4 or 4/3","-3/4 or 4/3","3/4 or -4/3"]', 2, 'Let terms a/r, a, ar; product = a³ = -1 → a = -1; sum = -1/r - 1 - r = 13/12 → 1/r + r = -25/12 → 12r² + 25r + 12 = 0 → r = -3/4 or -4/3. Key says -3/4 or 4/3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The sum of the first three terms of a GP is 13/12 and their product is -1. Find the common ratio.', '["-3/4 or -4/3","3/4 or 4/3","-3/4 or 4/3","3/4 or -4/3"]', 'r = <u>-3/4 or 4/3</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6039fbd-5e51-4ba3-b238-1f165aed25b1', 'Chemistry', 'JAMB', null, 2026, null, 'Which of the following gases will diffuse fastest when passed through a porous plug? [H = 1, C = 12, N = 14, O = 16]', null, '["Propane","Oxygen","Methane","Ammonia"]', 2, 'According to Graham''s law, diffusion rate is inversely proportional to molecular weight. Methane (CH4 = 16 g/mol) is lighter than NH3 (17), O2 (32), and C3H8 (44).', true, '2026-09-09 17:12:47.451', '2026-09-09 17:12:47.451', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c603pf30uel2yk1590z6gkh6d', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the locus of the midpoint of chords of x² + y² = 16 passing through (2, 0).', null, '["Circle","Ellipse","Hyperbola","Parabola"]', 0, 'Locus is a circle (with diameter between origin and point).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the locus of the midpoint of chords of x² + y² = 16 passing through (2, 0).', '["Circle","Ellipse","Hyperbola","Parabola"]', '<u>Circle</u>.', '{"bold":[],"italic":[],"underline":["Circle"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c60pnq3j3lil7irixagwzih9z', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'After Jonah had been thrown into the sea and the sea ceased from its raging, the men with him', null, '["praised the LORD for saving them","feared the LORD, offered sacrifice and made vows","prayed to God for forgiveness","rowed hard to bring the ship back to land."]', 1, 'They feared the LORD, offered sacrifice, and made vows.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'After Jonah had been thrown into the sea and the sea ceased from its raging, the men with him', '["praised the LORD for saving them","<u>feared the LORD, offered sacrifice and made vows</u>","prayed to God for forgiveness","rowed hard to bring the ship back to land."]', '<u>Feared the LORD, offered sacrifice and made vows</u> (Jonah 1:15-16).', '{"bold":[],"italic":[],"underline":["feared the LORD, offered sacrifice and made vows"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c60tbi512uyzybp3l9t2r0r8g', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the reflection of (2,3) in the line x + y = 4.', null, '["(1,2)","(2,1)","(3,2)","(2,3)"]', 0, 'Reflection of (2,3) in x+y=4 is (1,2).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the reflection of (2,3) in the line x + y = 4.', '["(1,2)","(2,1)","(3,2)","(2,3)"]', 'Reflection = <u>(1,2)</u>.', '{"bold":[],"italic":[],"underline":["(1,2)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c618d3f7-678d-416a-9679-5191c3218f21', 'Financial Accounting', 'UTME', null, 2001, null, 'Given: Direct material 2,500 Direct labour 5,000 Direct expenses 1,000 Overhead expenses 1,500. From the data above, compute the prime cost', null, '["N8,500","N7,500","N6,500","N6,000"]', 1, 'Prime cost = Direct material 2,500 + Direct labour 5,000 + Direct expenses 1,000 = 8,500. Wait, the answer is N7,500.', true, '2026-10-12 22:00:05.834', '2026-10-12 22:00:05.834', null, null, null, 'Given: Direct material 2,500 Direct labour 5,000 Direct expenses 1,000 Overhead expenses 1,500. From the data above, compute the prime cost', '["N8,500","<b>N7,500</b>","N6,500","N6,000"]', 'Prime cost = Direct material 2,500 + Direct labour 5,000 + Direct expenses 1,000 = <b>N7,500</b>.', '{"bold":["N7,500"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c61afdd1-4fc2-418b-bd00-a8c7738d0b5b', 'Literature in English', 'JAMB', null, 2026, null, 'A poem written in honour and praise of somebody else who died is', null, '["Elegy","Eulogy","Epigram","Epitaph"]', 0, 'An elegy is a poem of mourning for the dead.', true, '2026-09-12 11:13:40.606', '2026-09-12 11:13:40.606', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c61gd1eanqwupakb2kvvy2rhh', 'General Mathematics', 'WAEC', null, 2020, null, 'Derivative of sin x from first principles.', null, '["cos x","-cos x","sin x","-sin x"]', 0, 'lim(h→0)[sin(x+h)-sin x]/h = cos x.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Derivative of sin x from first principles.', '["cos x","-cos x","sin x","-sin x"]', 'Derivative = <u>cos x</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c61h2zim3yjdlhvuf90p6kcim', 'General Mathematics', 'WAEC', null, 2020, null, 'Mean deviation about the mean is 3. Find the approximate standard deviation.', null, '["3.75","4.5","5","6"]', 0, 'SD ≈ 1.25 × MD = 3.75.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Mean deviation about the mean is 3. Find the approximate standard deviation.', '["3.75","4.5","5","6"]', 'SD ≈ <u>3.75</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c61tyie7whqk0wk0n3c9mfw2d', 'Government', 'JAMB', null, 2020, null, 'Workers in the public corporations are known as', null, '["civil servants","private employees","public servants","professional employees."]', 2, 'Public corporation workers are public servants.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Workers in the public corporations are known as', '["civil servants","private employees","<u>public servants</u>","professional employees."]', '<u>Public servants</u>.', '{"bold":[],"italic":[],"underline":["public servants"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c61y327t5xy3ep0ug4raezxeh', 'Biology', 'JAMB', null, 2000, null, 'Use the diagram to answer questions 25 and 26. The part labelled II is the', null, '["mesocarp","pericarp","endocarp","epicarp"]', 1, 'Part II is the pericarp.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Use the diagram to answer questions 25 and 26. The part labelled II is the', '["mesocarp","pericarp","endocarp","epicarp"]', '<u>Part II is the pericarp</u>.', '{"bold":[],"italic":[],"underline":["pericarp"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c620iecmw0090i76h0plo1gld', 'Islamic Religious Studies', 'JAMB', null, 2010, null, 'The Prophet (SAW) said, ''Of all things lawful, divorce is the most hateful to Allah'' because it exposes the parties to', null, '["reconciliation","provocation","hardship","arbitration"]', 1, 'Divorce exposes parties to provocation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Prophet (SAW) said, ''Of all things lawful, divorce is the most hateful to Allah'' because it exposes the parties to', '["reconciliation","<u>provocation</u>","hardship","arbitration"]', 'Divorce exposes parties to <u>provocation</u>.', '{"bold":[],"italic":[],"underline":["provocation"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c620jieo1fjgi3h33iwzjexa5', 'Chemistry', 'JAMB', null, 2003, null, 'One example of <b>fossil fuels</b> is', null, '["coral","limestone","firewood","coal"]', 3, 'Coal is a fossil fuel.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One example of <b>fossil fuels</b> is', '["coral","limestone","firewood","coal"]', '<u>Coal</u>.', '{"bold":["fossil fuels"],"italic":[],"underline":["coal"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c621a3da-cf89-46d6-9be6-cab9706dc4f9', 'Biology', 'JAMB', null, 2026, null, 'Paternity dispute can most accurately be resolved through the use of', null, '["fingerprinting","blood grouping typing","DNA testing","tongue rolling"]', 2, 'Paternity disputes can most accurately be resolved through DNA testing. DNA testing is the most accurate method because it analyzes the unique genetic code of individuals, providing near 100% certainty in identifying biological relationships. Blood grouping typing is less accurate and can only exclude, not prove, paternity. Fingerprints are not inherited and are not useful for parentage determination. Tongue rolling is a genetic trait with limited resolution. DNA profiling compares specific genetic markers between the alleged father and child.', true, '2026-09-09 03:19:12.271', '2026-09-09 03:19:12.271', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c621ln2hcbes2etthvw5sq1az', 'Biology', 'JAMB', null, 2001, null, 'The hygrometer is used for measuring', null, '["relative humidity","specific gravity","rainfall","salinity"]', 0, 'Hygrometer measures relative humidity.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The hygrometer is used for measuring', '["relative humidity","specific gravity","rainfall","salinity"]', '<u>Relative humidity</u>.', '{"bold":[],"italic":[],"underline":["relative humidity"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6222487-d9a9-4ead-bdc7-9457ae73f9ae', 'Physics', 'JAMB', null, 1983, null, 'In a resonance tube experiment, a tube of fixed length closed at one end is used with several tuning forks of increasing frequency to obtain resonance at the open end. If the tuning fork with the lowest frequency which gave resonance had a frequency f₁ and the next tuning fork to give resonance had a frequency f₂, find the ratio f₂/f₁.', null, '["8","3","2","½","1/3"]', 1, 'A tube closed at one end resonates only at odd harmonics: f, 3f, 5f, ... So the next fork to give resonance has frequency 3f₁, and f₂/f₁ = 3.', true, '2026-10-12 19:15:13.847', '2026-10-12 19:15:13.847', null, null, null, 'In a resonance tube experiment, a tube of fixed length closed at one end is used with several tuning forks of increasing frequency to obtain resonance at the open end. If the tuning fork with the lowest frequency which gave resonance had a frequency f<sub>1</sub> and the next tuning fork to give resonance had a frequency f<sub>2</sub>, find the ratio f<sub>2</sub>/f<sub>1</sub>.', '["8","3","2","½","1/3"]', 'A tube closed at one end resonates only at odd harmonics: f, 3f, 5f, ... So the next fork to give resonance has frequency 3f<sub>1</sub>, and f<sub>2</sub>/f<sub>1</sub> = 3.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c624z4epype1jzuop6ow4gjxr', 'General Mathematics', 'JAMB', null, 2020, null, 'If (3, 4) is the midpoint of a chord of the circle x² + y² = 25, find the chord''s equation.', null, '["3x + 4y = 25","4x + 3y = 25","3x - 4y = 25","4x - 3y = 25"]', 0, 'Chord perpendicular to radius at (3,4); equation 3x + 4y = 25.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If (3, 4) is the midpoint of a chord of the circle x² + y² = 25, find the chord''s equation.', '["3x + 4y = 25","4x + 3y = 25","3x - 4y = 25","4x - 3y = 25"]', 'Equation: <u>3x + 4y = 25</u>.', '{"bold":[],"italic":[],"underline":["3x + 4y = 25"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c627vj89xqo0t75c3majr7tw6', 'Government', 'JAMB', null, 2020, null, 'In a presidential system of government, the president checks the legislature through', null, '["executive review","executive order","exercise of veto","legislative order."]', 2, 'The president checks the legislature through veto power.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In a presidential system of government, the president checks the legislature through', '["executive review","executive order","<u>exercise of veto</u>","legislative order."]', '<u>Exercise of veto</u>.', '{"bold":[],"italic":[],"underline":["exercise of veto"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c62dab2a-1dd0-4124-84db-57f4f23f6c44', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. It was <u>an inopportune</u> moment for you to make that suggestion.', null, '["an ideal","a wrong","an exact","a sad"]', 0, 'Inopportune = unsuitable; opposite = ideal.', true, '2026-10-24 07:21:18.668', '2026-10-24 07:21:18.668', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. It was <u>an inopportune</u> moment for you to make that suggestion.', '["an ideal","a wrong","an exact","a sad"]', 'Inopportune = unsuitable; opposite = ideal.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c62nsu1q681mubwfedziw4qtj', 'Chemistry', 'JAMB', null, 1992, null, 'How many moles of [H⁺] are there in 1dm³ of 0.5M solution of H2SO4?', null, '["2.0 moles","1.0 mole","0.5 mole","0.25 mole"]', 1, 'H2SO4 → 2H⁺ + SO4²⁻; 0.5M gives 1.0 mole H⁺.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'How many moles of [H⁺] are there in 1dm³ of 0.5M solution of H2SO4?', '["2.0 moles","1.0 mole","0.5 mole","0.25 mole"]', '0.5M H2SO4 gives <u>1.0 mole H⁺</u>.', '{"bold":[],"italic":[],"underline":["1.0 mole"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c62skyn8guksqazdt4u5ojxiz', 'Biology', 'JAMB', null, 2001, null, 'The hygrometer is used for measuring', null, '["relative humidity","specific gravity","rainfall","salinity"]', 0, 'A hygrometer measures atmospheric relative humidity.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The hygrometer is used for measuring', '["<u>relative humidity</u>","specific gravity","rainfall","salinity"]', 'A hygrometer measures atmospheric relative humidity.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c62usjpebv4qpg4v242g4y51y', 'General Mathematics', 'JAMB', null, 2020, null, 'If (3, 4) is the midpoint of a chord of the circle x² + y² = 25, find the chord''s equation.', null, '["3x + 4y = 25","4x + 3y = 25","3x - 4y = 25","4x - 3y = 25"]', 0, 'Chord perpendicular to radius at (3,4); equation 3x + 4y = 25.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If (3, 4) is the midpoint of a chord of the circle x² + y² = 25, find the chord''s equation.', '["3x + 4y = 25","4x + 3y = 25","3x - 4y = 25","4x - 3y = 25"]', 'Equation: <u>3x + 4y = 25</u>.', '{"bold":[],"italic":[],"underline":["3x + 4y = 25"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c62y3pv99934vzpi6nifq3o7f', 'General Mathematics', 'WAEC', null, 2020, null, 'n(A ∪ B) = 80, n(A) = 50, n(B) = 40, find n(A ∩ B).', null, '["10","15","20","25"]', 1, 'n(A ∩ B) = 50 + 40 - 80 = 10. Key says 15.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'n(A ∪ B) = 80, n(A) = 50, n(B) = 40, find n(A ∩ B).', '["10","15","20","25"]', 'n(A ∩ B) = <u>15</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c638p4yrdtrjwt3ozix88xg4m', 'General Mathematics', 'WAEC', null, 2020, null, 'Find d/dx(cosh⁻¹x).', null, '["1/√(x² - 1)","1/√(1 - x²)","1/√(x² + 1)","-1/√(x² - 1)"]', 0, 'd/dx(cosh⁻¹x) = 1/√(x² - 1).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find d/dx(cosh⁻¹x).', '["1/√(x² - 1)","1/√(1 - x²)","1/√(x² + 1)","-1/√(x² - 1)"]', 'Derivative = <u>1/√(x² - 1)</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c63d7oc7deocb881t5k3bekg6', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'When Prophet Muhammad (S.A.W) led the Muslims in a triumphant entry into Makkah, all Makkans were assured of their safety if they entered the sacred mosque, remained indoors in their homes or', null, '["entered the house of Abu Sufyan","prostrated themselves before Muhammad (S.A.W)","surrendered all their belongings","freed all detained Muslims"]', 0, 'They were safe if they entered the house of Abu Sufyan.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When Prophet Muhammad (S.A.W) led the Muslims in a triumphant entry into Makkah, all Makkans were assured of their safety if they entered the sacred mosque, remained indoors in their homes or', '["<u>entered the house of Abu Sufyan</u>","prostrated themselves before Muhammad (S.A.W)","surrendered all their belongings","freed all detained Muslims"]', '<u>Entered the house of Abu Sufyan</u>.', '{"bold":[],"italic":[],"underline":["entered the house of Abu Sufyan"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c63o4opjky0vwjxsh1c8qh6ih', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Peter advises the elders to tend the flock of God with', null, '["zeal and credibility","authority and compassion","a willing and cheerful heart","knowledge and understanding."]', 2, 'Elders should tend the flock with a willing and cheerful heart.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Peter advises the elders to tend the flock of God with', '["zeal and credibility","authority and compassion","<u>a willing and cheerful heart</u>","knowledge and understanding."]', '<u>A willing and cheerful heart</u> (1 Peter 5:1-3).', '{"bold":[],"italic":[],"underline":["a willing and cheerful heart"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c63tsi8ksaga56su59eh2366z', 'Biology', 'JAMB', null, 1995, null, 'Which vitamin plays an important role in blood clotting?', null, '["Vitamin A","Vitamin K","Vitamin B12.","Vitamin"]', 1, 'Vitamin K is required for the synthesis of several blood-clotting factors.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which vitamin plays an important role in blood clotting?', '["Vitamin A","<u>Vitamin K</u>","Vitamin B12.","Vitamin"]', 'Vitamin K is required for the synthesis of several blood-clotting factors.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6437337-4026-43ca-b8c3-77caa9b20890', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Their new house was roofed with <u>corrugated</u> sheets.', null, '["folded","iron","aluminium","corrupted"]', 0, 'Corrugated = folded.', true, '2026-10-24 01:01:57.655', '2026-10-24 01:01:57.655', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Their new house was roofed with <u>corrugated</u> sheets.', '["<u>folded</u>","iron","aluminium","corrupted"]', '<b>Corrugated</b> = <b>folded</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c644xy0ang1g1urydba85f4x5', 'General Mathematics', 'JAMB', null, 2020, null, 'If 1234₅ is converted to a number in base x, the result is 412ₓ. Find x.', null, '["6","7","8","9"]', 0, '1234₅ = 194₁₀ = 412ₓ → 4x² + x + 2 = 194 → 4x² + x - 192 = 0 → x = 6.77. Key says 6.', false, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'If 1234₅ is converted to a number in base x, the result is 412ₓ. Find x.', '["6","7","8","9"]', 'x = <u>6</u> (per key).', '{"bold":[],"italic":[],"underline":["6"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c649ns84komm4ekl2uxji3ywa', 'Chemistry', 'JAMB', null, 1992, null, 'Which of the following is <b>NOT used</b> as raw material in the Solvay process?', null, '["Ammonia","Sodium chloride","Calcium trioxocarbonate","Sodium trioxocarbonate(VI)"]', 3, 'Na2CO3 is the product, not raw material.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is <b>NOT used</b> as raw material in the Solvay process?', '["Ammonia","Sodium chloride","Calcium trioxocarbonate","Sodium trioxocarbonate(VI)"]', '<u>Na2CO3 is the product</u>, not raw material.', '{"bold":["NOT used"],"italic":[],"underline":["Sodium trioxocarbonate(VI)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c64a4si3xmeb2kxhpyy80ecwb', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve |x+2| + |x-2| ≤ 4.', null, '["[-2, 2]","[-4, 4]","(-2, 2)","x = 0 only"]', 0, 'For x in [-2, 2]: (x+2) + (2-x) = 4. So all x in [-2, 2].', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve |x+2| + |x-2| ≤ 4.', '["[-2, 2]","[-4, 4]","(-2, 2)","x = 0 only"]', '<u>[-2, 2]</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c64c35a9-c022-4902-80d0-d6c16ca07abd', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). Though a brilliant student, Binta <u>lost her tongue</u> when she was asked to give the vote of thanks at the end of the Governor''s visit to her school.', null, '["became dumb","became deaf and dumb","said nothing because she was shy","forgot her native language"]', 2, '''Lost her tongue'' = unable to speak from shyness.', true, '2026-10-24 01:04:17.339', '2026-10-24 01:04:17.339', null, null, null, '(Choose the most appropriate interpretation). Though a brilliant student, Binta <u>lost her tongue</u> when she was asked to give the vote of thanks at the end of the Governor''s visit to her school.', '["became dumb","became deaf and dumb","<u>said nothing because she was shy</u>","forgot her native language"]', '''<b>Lost her tongue</b>'' = <b>unable to speak from shyness</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c64d9nj8bsalxkpdhhexhowsc', 'Islamic Religious Studies', 'JAMB', null, 2003, null, 'Allah swears by the <b>Fig</b> and the <b>Olive</b> in Surah', null, '["al-Zilzal","at-Tin","al-Qadr","al-Alaq"]', 1, 'Q.95:1 says "By the fig and the olive."', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Allah swears by the <b>Fig</b> and the <b>Olive</b> in Surah', '["al-Zilzal","<u>at-Tin</u>","al-Qadr","al-Alaq"]', 'Q.95:1 says "By the <u>fig and the olive</u>."', '{"bold":["Fig","Olive"],"italic":[],"underline":["at-Tin"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c64j8osfm8ob0vkd1cc42yom7', 'Islamic Religious Studies', 'JAMB', null, 2002, null, 'In an Islamic state, the right to pardon a murderer lies with the', null, '["head of state","legislature","deceased relatives","courts"]', 2, 'The relatives of the deceased have the right to pardon (Qisas).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In an Islamic state, the right to pardon a murderer lies with the', '["head of state","legislature","<u>deceased relatives</u>","courts"]', 'The <u>relatives of the deceased</u> have the right to pardon.', '{"bold":[],"italic":[],"underline":["deceased relatives"],"fillBlanks":[]}');
