insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c64urs6eyle0ii3blfsxr4zyy', 'Biology', 'JAMB', null, 1984, null, 'Which of the following groups of factors is completely abiotic?', null, '["salinity, tide, plankton, turbidity","Temperature, pH, soil insect","Wind, altitude, humidity, light","Conifers, winds, pH, rainfall","Soil, water, bacteria, salinity"]', 2, 'Wind, altitude, humidity, and light are all abiotic factors.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following groups of factors is completely <b>abiotic</b>?', '["salinity, tide, plankton, turbidity","Temperature, pH, soil insect","<u>Wind, altitude, humidity, light</u>","Conifers, winds, pH, rainfall","Soil, water, bacteria, salinity"]', '<u>Wind, altitude, humidity, and light</u> are all abiotic factors.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c650tpgc32p6rkhtxkdepl7az', 'Chemistry', 'JAMB', null, 1987, null, 'An element Z contained 90% of ¹⁶Z and 10% of ¹⁸Z. Its relative atomic mass is', null, '["16.0","16.2","17.0","17.8"]', 1, 'RAM = (0.9 × 16) + (0.1 × 18) = 14.4 + 1.8 = 16.2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An element Z contained 90% of ¹⁶Z and 10% of ¹⁸Z. Its relative atomic mass is', '["16.0","16.2","17.0","17.8"]', 'RAM = <u>16.2</u>.', '{"bold":[],"italic":[],"underline":["16.2"],"fillBlanks":[]}');
