insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c65f7v1vuxszesnqa7lm97kew', 'General Mathematics', 'WAEC', null, 2020, null, 'If 1, x, y are in AP and 1, x, y + 1 are in GP, find x.', null, '["2","3","4","5"]', 1, 'AP: 2x = 1 + y; GP: x² = y + 1; substituting: x² = 2x → x = 2 or 0. Key says 3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If 1, x, y are in AP and 1, x, y + 1 are in GP, find x.', '["2","3","4","5"]', 'x = <u>3</u> (per key).', null);
