insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c66ph20o5e3g3mw7m6gk5azcd', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the volume generated when the region bounded by y = √x, the y-axis, and the line y = 2 is rotated about the y-axis.', null, '["32π/5","16π/5","8π/5","4π/5"]', 0, 'V = π∫₀² y⁴ dy = 32π/5.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the volume generated when the region bounded by y = √x, the y-axis, and the line y = 2 is rotated about the y-axis.', '["32π/5","16π/5","8π/5","4π/5"]', 'Volume = <u>32π/5</u>.', '{"bold":[],"italic":[],"underline":["32π/5"],"fillBlanks":[]}');
