insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c690a0wzud7ok8853j0o791by', 'Biology', 'JAMB', null, 2002, null, 'A flower that has both stamens and pistil is said to be', null, '["staminate","pistillate","perfect","imperfect"]', 2, 'A flower with both stamens and pistil is perfect.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A flower that has both stamens and pistil is said to be', '["staminate","pistillate","perfect","imperfect"]', '<u>Perfect</u> (bisexual).', '{"bold":[],"italic":[],"underline":["perfect"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c691664e-2ec0-4152-89e4-c34354d0e8be', 'General Mathematics', 'JAMB', null, 2026, null, 'If y = cos³x find dy/dx', null, '["-3sinx cos²x","3sin²x cosx","-3cos²x sinx","3sec²x tanx"]', 0, 'y = cos³x. dy/dx = 3cos²x(-sinx) = -3sinx cos²x.', true, '2026-09-12 11:43:44.646', '2026-09-12 11:43:44.646', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c691ov24lxtgttfyoh0cshga5', 'Chemistry', 'JAMB', null, 1993, null, 'Which group of elements forms hydrides that are <b>pyramidal</b> in structure?', null, '["III","IV","V","VI"]', 2, 'Group V hydrides (NH3, PH3) are pyramidal.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which group of elements forms hydrides that are <b>pyramidal</b> in structure?', '["III","IV","V","VI"]', '<u>Group V</u> hydrides are pyramidal.', '{"bold":["pyramidal"],"italic":[],"underline":["V"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c693sa4bo1qqioah6x8byw31o', 'Government', 'JAMB', null, 2020, null, 'Decree 34 of 1966 was unacceptable to many Nigerians because it was', null, '["seen as an instrument of impoverishment","promulgated without consultation with the people","perceived to abolish the federal system","considered as alien."]', 2, 'Decree 34 was perceived to abolish the federal system.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Decree 34 of 1966 was unacceptable to many Nigerians because it was', '["seen as an instrument of impoverishment","promulgated without consultation with the people","<u>perceived to abolish the federal system</u>","considered as alien."]', '<u>Perceived to abolish the federal system</u>.', '{"bold":[],"italic":[],"underline":["perceived to abolish the federal system"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c694b83kctpr3q1c0u0q5cdve', 'Chemistry', 'JAMB', null, 1995, null, 'Chlorine, consisting of two isotopes of mass numbers 35 and 37, has an atomic mass of 35.5. The relative abundance of the isotope of mass number 37 is', null, '["20","25","50","75"]', 1, 'Let x = abundance of 37; 35(1-x) + 37x = 35.5 → 2x = 0.5 → x = 25%.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Chlorine, consisting of two isotopes of mass numbers 35 and 37, has an atomic mass of 35.5. The relative abundance of the isotope of mass number 37 is', '["20","25","50","75"]', 'Abundance of ³⁷Cl = <u>25%</u>.', '{"bold":[],"italic":[],"underline":["25"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c697df2f-6f8f-4283-b895-3fc47c0285ae', 'Literature in English', 'JAMB', null, 2026, null, 'A character whose name is the source of the title of the play or novel is referred to as', null, '["eponym character","eponymous character","stereotypical character","anti-hero"]', 1, 'An eponymous character is one whose name is the title.', true, '2026-09-12 11:05:39.673', '2026-09-12 11:05:39.673', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6985e76-4346-4123-912e-8af63bb5d140', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The workers suddenly became <u>restive</u>.', null, '["fidgety","calm","disorderly","submissive"]', 1, 'Restive = restless; opposite = calm.', true, '2026-10-24 07:21:23.614', '2026-10-24 07:21:23.614', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The workers suddenly became <u>restive</u>.', '["fidgety","calm","disorderly","submissive"]', 'Restive = restless; opposite = calm.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c69dfd80-db81-438e-bdec-6bf80d77ebae', 'Physics', 'JAMB', null, 1990, null, 'Which of the following is an essential physical property of the wires used for making fuses?', null, '["Low density","High thermal conductivity","Low electrical resistivity","Low melting point."]', 3, 'A fuse wire must melt easily when the current exceeds the safe value, so it needs a low melting point.', true, '2026-10-12 19:15:31.894', '2026-10-12 19:15:31.894', null, null, null, 'Which of the following is an essential physical property of the wires used for making fuses?', '["Low density","High thermal conductivity","Low electrical resistivity","Low melting point."]', 'A fuse wire must melt easily when the current exceeds the safe value, so it needs a low melting point.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c69hs2bm976gcrks70hw7nfow', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The jurist who made Tasawwuf compatible with the Shari''ah was', null, '["ibn Sina","ibn Khaldun","Ar-Razi","al-Ghazali."]', 3, 'Al-Ghazali made Tasawwuf compatible with Shari''ah.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The jurist who made Tasawwuf compatible with the Shari''ah was', '["ibn Sina","ibn Khaldun","Ar-Razi","<u>al-Ghazali.</u>"]', '<u>Al-Ghazali</u>.', '{"bold":[],"italic":[],"underline":["al-Ghazali."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6a1izu0s6l2xybda0arpa760', 'General Mathematics', 'WAEC', null, 2020, null, 'Two vectors are given by p = 3i - 2j + k and q = -i + j + 2k. Find a unit vector perpendicular to both p and q.', null, '["(-5i - 7j + k)/√75","(5i + 7j - k)/√75","(-5i - 7j + k)/√55","(5i + 7j - k)/√55"]', 1, 'p × q = -5i - 7j + k; unit = (-5i-7j+k)/√75. Key says (5i+7j-k)/√75.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Two vectors are given by p = 3i - 2j + k and q = -i + j + 2k. Find a unit vector perpendicular to both p and q.', '["(-5i - 7j + k)/√75","(5i + 7j - k)/√75","(-5i - 7j + k)/√55","(5i + 7j - k)/√55"]', 'Unit vector = <u>(5i + 7j - k)/√75</u> (per key).', null);
