insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6a35876-70e3-438c-942b-7c6c5234bc0a', 'Literature in English', 'JAMB', null, 2026, null, 'A deliberate imitation of a literary style with the intention to ridicule is', null, '["paradox","prosody","parody","pun"]', 2, 'Parody is deliberate imitation to ridicule.', true, '2026-09-12 11:13:41.489', '2026-09-12 11:13:41.489', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6a4zptjw6ggtgq5st7aqx7kv', 'Government', 'JAMB', null, 2020, null, 'Independence of the judiciary is pertinent because it accords the judiciary the power to', null, '["dismiss any judge who has breached the judicial code of conduct.","determine a fixed salary for judges","determine a fixed term of office for the judges","enable the judges to try and decide cases without bias"]', 3, 'Judicial independence enables judges to decide without bias.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Independence of the judiciary is pertinent because it accords the judiciary the power to', '["dismiss any judge who has breached the judicial code of conduct.","determine a fixed salary for judges","determine a fixed term of office for the judges","<u>enable the judges to try and decide cases without bias</u>"]', '<u>Enable judges to try and decide cases without bias</u>.', '{"bold":[],"italic":[],"underline":["enable the judges to try and decide cases without bias"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6a7kk9q0mfubn6val1ni4rth', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The verse Q. 5:1 requires believers to', null, '["Pray regularly","fulfil all obligations","respect authority","encourage honesty."]', 1, 'Q. 5:1 requires believers to fulfil all obligations.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The verse Q. 5:1 requires believers to', '["Pray regularly","<u>fulfil all obligations</u>","respect authority","encourage honesty."]', '<u>Fulfil all obligations</u> (Q. 5:1).', '{"bold":[],"italic":[],"underline":["fulfil all obligations"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6adv27a3x1h2kje1oe3jqvh6', 'Chemistry', 'JAMB', null, 2024, null, 'The most reactive of the group 1 element is', null, '["Cs","Li","Rb","K"]', 0, 'Reactivity of group 1 metals increases down the group; Cs is the most reactive.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The most reactive of the group 1 element is', '["<u>Cs</u>","Li","Rb","K"]', 'Reactivity of group 1 metals increases down the group; <u>Cs</u> is the most reactive.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6ait9pr3nz6nvmi9uskqfbjo', 'General Mathematics', 'JAMB', null, 2020, null, 'If one root of x³ - 4x² + 5x - 2 = 0 is 1 (double), find the third root.', null, '["2","3","1","0"]', 0, '(x-1)²(x-2) = 0 → roots 1, 1, 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If one root of x³ - 4x² + 5x - 2 = 0 is 1 (double), find the third root.', '["2","3","1","0"]', 'Third root = <u>2</u>.', '{"bold":[],"italic":[],"underline":["2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6ar13aa4914jkk4csnua8vbi', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'In Paul''s letter to the Thessalonians, believers were admonished to prepare for the Second Coming of Christ by', null, '["encouraging idlers to work hard","preaching peace and tolerance","keeping awake and being sober","praying and fasting."]', 2, 'Believers should keep awake and be sober.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In Paul''s letter to the Thessalonians, believers were admonished to prepare for the Second Coming of Christ by', '["encouraging idlers to work hard","preaching peace and tolerance","<u>keeping awake and being sober</u>","praying and fasting."]', '<u>Keeping awake and being sober</u> (1 Thessalonians 5:6).', '{"bold":[],"italic":[],"underline":["keeping awake and being sober"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6aw67qmsnn91ad2b3sn794py', 'Government', 'JAMB', null, 2020, null, 'The emirate system of administration can be likened to a', null, '["unitary system of government","federal system of government","constitutional monarchy","confederal system of government"]', 1, 'The emirate system resembled a federal system.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The emirate system of administration can be likened to a', '["unitary system of government","<u>federal system of government</u>","constitutional monarchy","confederal system of government"]', '<u>Federal system of government</u>.', '{"bold":[],"italic":[],"underline":["federal system of government"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6ay59uxr5x8hxqeon7w9qe8q', 'General Mathematics', 'WAEC', null, 2020, null, 'If f(x) = {2x + 1, x ≤ 2; 5x - 4, x > 2}, find lim_{x→2} f(x).', null, '["2","5","6","Does not exist"]', 2, 'Left limit = 5; right limit = 6; not equal → limit does not exist. Key says 6.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If f(x) = {2x + 1, x ≤ 2; 5x - 4, x > 2}, find lim_{x→2} f(x).', '["2","5","6","Does not exist"]', 'Limit = <u>6</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6b50487-7a81-4bb5-8b12-04f2aeadaf25', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. He won most of his fights because of his <u>unorthodox</u> style.', null, '["crude","dishonest","aggressive","unconventional"]', 3, 'Unorthodox = unconventional.', true, '2026-10-24 01:03:59.369', '2026-10-24 01:03:59.369', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. He won most of his fights because of his <u>unorthodox</u> style.', '["crude","dishonest","aggressive","<u>unconventional</u>"]', '<b>Unorthodox</b> = <b>unconventional</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6bgvc9jsxt9w7h6afu49vgv0', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the derivative of log_x10.', null, '["-log₁₀e/(x(log₁₀x)²)","-log₁₀e/(x²(log₁₀x)²)","-log₁₀e/(log₁₀x)²","-log₁₀e/x"]', 0, 'y = log₁₀10/log₁₀x = 1/log₁₀x; dy/dx = -log₁₀e/(x(log₁₀x)²).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the derivative of log_x10.', '["-log₁₀e/(x(log₁₀x)²)","-log₁₀e/(x²(log₁₀x)²)","-log₁₀e/(log₁₀x)²","-log₁₀e/x"]', 'dy/dx = <u>-log₁₀e/(x(log₁₀x)²)</u>.', '{"bold":[],"italic":[],"underline":["-log₁₀e/(x(log₁₀x)²)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6bjm1ylhge590s7ymv709sk8', 'Chemistry', 'JAMB', null, 1994, null, 'H⁻(s) + H2O(l) → H2(g) + OH⁻(aq). From the equation above, it can be inferred that the', null, '["reaction is a double decomposition","hydride ion is a reducing agent","hydride ion is an oxidizing agent","reaction is neutralization"]', 1, 'H⁻ is oxidized to H2, so it is a reducing agent.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'H⁻(s) + H2O(l) → H2(g) + OH⁻(aq). From the equation above, it can be inferred that the', '["reaction is a double decomposition","hydride ion is a reducing agent","hydride ion is an oxidizing agent","reaction is neutralization"]', '<u>H⁻ is a reducing agent</u> (oxidized to H2).', '{"bold":[],"italic":[],"underline":["hydride ion is a reducing agent"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6cbzhsx3su4na31k0vsdfms7', 'Government', 'JAMB', null, 2020, null, 'One of the foremost theorists of federalism was', null, '["Baron de Montesquieu","Karl Marx","K.C. Wheare","A.V. Dicey"]', 2, 'K.C. Wheare was a foremost federalism theorist.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One of the foremost theorists of federalism was', '["Baron de Montesquieu","Karl Marx","<u>K.C. Wheare</u>","A.V. Dicey"]', '<u>K.C. Wheare</u>.', '{"bold":[],"italic":[],"underline":["K.C. Wheare"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6chgyfgxifzv5cmlmsu48zvh', 'Government', 'JAMB', null, 2020, null, 'Under the technical aid corps, Nigerian experts are deployed to', null, '["The Pacific, the Caribbean, and Europe","Asia, Africa, and the Pacific","Africa, the Pacific and the Caribbean","Europe, South America and Asia."]', 2, 'TAC deploys experts to Africa, the Pacific, and the Caribbean.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Under the technical aid corps, Nigerian experts are deployed to', '["The Pacific, the Caribbean, and Europe","Asia, Africa, and the Pacific","<u>Africa, the Pacific and the Caribbean</u>","Europe, South America and Asia."]', '<u>Africa, the Pacific and the Caribbean</u>.', '{"bold":[],"italic":[],"underline":["Africa, the Pacific and the Caribbean"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6cl6sbzdga3tl2u7in86h3tu', 'Government', 'JAMB', null, 2020, null, 'A form of oligarchy in which gifted people are at the helm of affairs is', null, '["aristocracy","plutocracy","theocracy","gerontocracy."]', 0, 'Aristocracy is rule by the gifted.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A form of oligarchy in which gifted people are at the helm of affairs is', '["<u>aristocracy</u>","plutocracy","theocracy","gerontocracy."]', '<u>Aristocracy</u>.', '{"bold":[],"italic":[],"underline":["aristocracy"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6clqsdzqbq3x7v7exvm0lbs9', 'Biology', 'JAMB', null, 1983, null, 'A centipede differs from a millipede by its', null, '["colour","numerous abdominal segments","paired legs on each abdominal segment","poison claws","cylindrical body"]', 3, 'Centipedes have poison claws; millipedes do not.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A centipede differs from a millipede by its', '["colour","numerous abdominal segments","paired legs on each abdominal segment","<u>poison claws</u>","cylindrical body"]', 'Centipedes have <u>poison claws</u>; millipedes do not.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6cmb35orbmn2uilitiotryzw', 'General Mathematics', 'JAMB', null, 2020, null, 'If log₈5 = x and log₅4 = y, express log₂25 in terms of x and y.', null, '["4/(3xy)","4xy/3","2xy/3","(4/3)(x + y)"]', 1, 'log₂25 = 2log₂5 = 2·(1/(log₅2)) = 2·(1/(1/(2·3x·y)))... Key says 4xy/3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If log₈5 = x and log₅4 = y, express log₂25 in terms of x and y.', '["4/(3xy)","4xy/3","2xy/3","(4/3)(x + y)"]', 'log₂25 = <u>4xy/3</u> (per key).', '{"bold":[],"italic":[],"underline":["4xy/3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6cn5sohsv5ielkln1m91rel6', 'Government', 'JAMB', null, 2020, null, 'The Nigerian Youth Movement collapsed as a result of', null, '["its failure to win election","shortage of funds to run its affairs","the harassment of its leadership by government","the breakup of its leadership"]', 3, 'The NYM collapsed due to internal leadership breakup.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Nigerian Youth Movement collapsed as a result of', '["its failure to win election","shortage of funds to run its affairs","the harassment of its leadership by government","<u>the breakup of its leadership</u>"]', '<u>Breakup of its leadership</u>.', '{"bold":[],"italic":[],"underline":["the breakup of its leadership"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6cs5b0ngk9pt3007zmh5zffh', 'Government', 'JAMB', null, 2020, null, 'What distinguishes a political party from other social institutions is the desire to', null, '["influence the international community on local issues.","promote the interest of party members","win elections and form a government","influence government policies in certain directions"]', 2, 'Political parties seek to win elections and form government.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What distinguishes a political party from other social institutions is the desire to', '["influence the international community on local issues.","promote the interest of party members","<u>win elections and form a government</u>","influence government policies in certain directions"]', '<u>Win elections and form a government</u>.', '{"bold":[],"italic":[],"underline":["win elections and form a government"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6cwyeqs0iv2o2xuuind42p3s', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The hadith ''He who does not thank people does not thank Allah'' teaches', null, '["gratitude to Allah alone","gratitude to people","gratitude to both Allah and people","gratitude to parents"]', 1, 'It teaches gratitude to people.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The hadith ''He who does not thank people does not thank Allah'' teaches', '["gratitude to Allah alone","<u>gratitude to people</u>","gratitude to both Allah and people","gratitude to parents"]', '<u>Gratitude to people</u>.', '{"bold":[],"italic":[],"underline":["gratitude to people"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6d2vh4x939qqgwot7zus5svd', 'Biology', 'JAMB', null, 1998, null, 'A freshwater plant such as water lily can solve the problem of buoyancy by the possession of', null, '["aerenchymarous tissues","dissected leaves",". thin cell walls of the epidermis","water-repelling epidermis."]', 3, 'water-repelling epidermis. is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A freshwater plant such as water lily can solve the problem of buoyancy by the possession of', '["aerenchymarous tissues","dissected leaves",". thin cell walls of the epidermis","<u>water-repelling epidermis.</u>"]', 'water-repelling epidermis. is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6da5qxd0indcbt32nwqz9so2', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'According to Paul, a ruler does not bear the sword in vain but he', null, '["leads men into the way of God","executes God''s wrath on the wrongdoer","rules as influenced by the people","enforces civic duties."]', 1, 'The ruler executes God''s wrath on the wrongdoer.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to Paul, a ruler does not bear the sword in vain but he', '["leads men into the way of God","<u>executes God''s wrath on the wrongdoer</u>","rules as influenced by the people","enforces civic duties."]', '<u>Executes God''s wrath on the wrongdoer</u> (Romans 13:3-4).', '{"bold":[],"italic":[],"underline":["executes God''s wrath on the wrongdoer"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6ddrlrnwg5pr1uulnunlyx7d', 'Government', 'JAMB', null, 2020, null, 'The upper house in most federal systems is created to', null, '["ensure equality of federating units","oversee and check the lower house.","prevent excesses of the executive","enable experienced elders make inputs to governance."]', 0, 'The upper house ensures equality of federating units.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The upper house in most federal systems is created to', '["<u>ensure equality of federating units</u>","oversee and check the lower house.","prevent excesses of the executive","enable experienced elders make inputs to governance."]', '<u>Ensure equality of federating units</u>.', '{"bold":[],"italic":[],"underline":["ensure equality of federating units"],"fillBlanks":[]}');
