insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6djjzg4y5xph5hon0f2tdwrz', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'The promise to those who are persecuted for righteousness sake is that they will', null, '["see God","be called the sons of God","inherit the earth","inherit the kingdom of heaven."]', 3, 'They will inherit the kingdom of heaven.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The promise to those who are persecuted for righteousness sake is that they will', '["see God","be called the sons of God","inherit the earth","<u>inherit the kingdom of heaven.</u>"]', '<u>Inherit the kingdom of heaven</u> (Matthew 5:10).', '{"bold":[],"italic":[],"underline":["inherit the kingdom of heaven."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6dkh8p1xi2672u7ealfv6iur', 'Islamic Religious Studies', 'JAMB', null, 2002, null, 'Q.24:30 enjoins Muslims to', null, '["dress properly","be very attentive in prayers","guard against adultery","lower their gaze"]', 3, 'Q.24:30 commands believing men to lower their gaze.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Q.24:30 enjoins Muslims to', '["dress properly","be very attentive in prayers","guard against adultery","<u>lower their gaze</u>"]', 'Q.24:30 commands believing men to <u>lower their gaze</u>.', '{"bold":[],"italic":[],"underline":["lower their gaze"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6dr0wapzd4wvozdplhwmg9v5', 'General Mathematics', 'JAMB', null, 2020, null, 'If 3/8 of a number is 45, find 40% of it.', null, '["48","52","56","60"]', 0, 'Number = 45 × 8/3 = 120; 40% of 120 = 48.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If 3/8 of a number is 45, find 40% of it.', '["48","52","56","60"]', 'Number = 120; 40% = <u>48</u>.', '{"bold":[],"italic":[],"underline":["48"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6dx0vrxzouity19kvo8t4zzh', 'General Mathematics', 'JAMB', null, 2020, null, 'A circle through (1,2), (3,4), and (5,6) has its center at:', null, '["(3,4)","Not defined (collinear)","(2,3)","(0,0)"]', 1, 'Points collinear → no circle.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A circle through (1,2), (3,4), and (5,6) has its center at:', '["(3,4)","Not defined (collinear)","(2,3)","(0,0)"]', '<u>Not defined (collinear)</u>.', '{"bold":[],"italic":[],"underline":["Not defined (collinear)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6e0j1i4utoc5pczccn0e6o9v', 'Chemistry', 'JAMB', null, 1988, null, 'Which of the following is used in <b>fire extinguishers</b>?', null, '["Carbon(II) oxide","Carbon(IV) oxide","Sulphur(IV) oxide","Ammonia"]', 1, 'CO2 is used in fire extinguishers.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is used in <b>fire extinguishers</b>?', '["Carbon(II) oxide","Carbon(IV) oxide","Sulphur(IV) oxide","Ammonia"]', '<u>CO2</u> is used in fire extinguishers.', '{"bold":["fire extinguishers"],"italic":[],"underline":["Carbon(IV) oxide"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6e757z9uf3q7rscjy8nk617l', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Allah doth command you To render back your Trusts To those to whom they are due; And when ye judge Between man and man That ye judge with justice... (Q.4:58). Inherent in the Qur''anic verse above are the virtues of amanah and', null, '["diyafah","karamah","khusu","adalah."]', 3, 'The virtues are amanah and adalah (justice).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Allah doth command you To render back your Trusts To those to whom they are due; And when ye judge Between man and man That ye judge with justice... (Q.4:58). Inherent in the Qur''anic verse above are the virtues of amanah and', '["diyafah","karamah","khusu","<u>adalah.</u>"]', '<u>Amanah and adalah</u> (Q. 4:58).', '{"bold":[],"italic":[],"underline":["adalah."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6edyhwdumwy80fjx8p7sr4lu', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'In his letter to Philemon, Paul described Onesimus as his', null, '["brother","fellow worker","fellow prisoner","child"]', 3, 'Paul described Onesimus as his child.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In his letter to Philemon, Paul described Onesimus as his', '["brother","fellow worker","fellow prisoner","<u>child</u>"]', '<u>Child</u> (Philemon 1:10).', '{"bold":[],"italic":[],"underline":["child"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6eid5dssq63s0rw8o9pqpjgn', 'Biology', 'JAMB', null, 2003, null, 'If water that has been coloured red is poured at the base of a wilting plant, it will appear as a red stain in the cells of the', null, '["phloem","parenchyma","xylem","epidermis"]', 2, 'xylem is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If water that has been coloured red is poured at the base of a wilting plant, it will appear as a red stain in the cells of the', '["phloem","parenchyma","<u>xylem</u>","epidermis"]', 'xylem is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6esnj9kacjfy4dm8xnc63bja', 'Biology', 'JAMB', null, 1991, null, 'Environmental pollutants which can work through the media of water, soil and air include', null, '["carbon monoxide","noise","sulphur (IV) oxide","smoke"]', 0, 'Carbon monoxide pollutes water, soil, and air.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Environmental pollutants which can work through the media of water, soil and air include', '["<u>carbon monoxide</u>","noise","sulphur (IV) oxide","smoke"]', '<u>Carbon monoxide</u> pollutes water, soil, and air.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6eyov1oguyiel60s24eb9pcq', 'Chemistry', 'JAMB', null, 1988, null, '2.5g of a sample of an oxide of copper gave 2.0g of copper on reduction, while 2.50g of another oxide of copper on reduction also gave 2.0g of copper. These results are in accordance with the law of', null, '["constant composition","conservation of matter","multiple proportions","definite proportions"]', 2, 'Two different oxides of the same metal show the law of multiple proportions.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '2.5g of a sample of an oxide of copper gave 2.0g of copper on reduction, while 2.50g of another oxide of copper on reduction also gave 2.0g of copper. These results are in accordance with the law of', '["constant composition","conservation of matter","multiple proportions","definite proportions"]', '<u>Law of multiple proportions</u> (two oxides of same metal).', '{"bold":[],"italic":[],"underline":["multiple proportions"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6f2crfhr25cpnmx20jycqljd', 'General Mathematics', 'WAEC', null, 2020, null, 'On {0,1,2}, a*b = (a + b) mod 3. What is the identity?', null, '["0","1","2","none"]', 0, 'a*0 = a mod 3 = a → identity = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'On {0,1,2}, a*b = (a + b) mod 3. What is the identity?', '["0","1","2","none"]', 'Identity = <u>0</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6fdr1k8q5avpe7j9ma9m9325', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Prophet Ezekiel was set upon his feet to hear the LORD speak when', null, '["the spirit entered into him","he was made to touch the ephod","an angel of the LORD lifted him","a voice from heaven commanded him to do so."]', 0, 'The spirit entered into him.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Prophet Ezekiel was set upon his feet to hear the LORD speak when', '["<u>the spirit entered into him</u>","he was made to touch the ephod","an angel of the LORD lifted him","a voice from heaven commanded him to do so."]', '<u>The spirit entered into him</u> (Ezekiel 2:2).', '{"bold":[],"italic":[],"underline":["the spirit entered into him"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6g2oah683s7y1jf6gasa4i8b', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'A mature Muslim who wakes up only to discover that it was the first day of Ramadan is expected to', null, '["observe imsak and make up","start his fasting the next day","compensate the day with kaffarah","observe imsak without making up."]', 0, 'He observes imsak and makes up.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A mature Muslim who wakes up only to discover that it was the first day of Ramadan is expected to', '["<u>observe imsak and make up</u>","start his fasting the next day","compensate the day with kaffarah","observe imsak without making up."]', '<u>Observe imsak and make up</u>.', '{"bold":[],"italic":[],"underline":["observe imsak and make up"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6g3e5836rjdcctlk1wxopsqx', 'English Language', 'JAMB', null, 2020, null, 'The choice to go to the university or not is _____.', null, '["yours''","your","yours","your''s"]', 2, 'Possessive pronoun "yours" (no apostrophe).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The choice to go to the university or not is _____.', '["yours''","your","yours","your''s"]', '<u>Yours</u> — no apostrophe.', '{"bold":[],"italic":[],"underline":["yours"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6gd4akrirfbsx1splwamajir', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'In pre-Islamic period, the social practice of tribalism was known as', null, '["al-''asabiyyah","al-muru''ah","al-ghazwah","ad-diyafah."]', 0, 'It was known as al-''asabiyyah.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In pre-Islamic period, the social practice of tribalism was known as', '["<u>al-''asabiyyah</u>","al-muru''ah","al-ghazwah","ad-diyafah."]', '<u>Al-''asabiyyah</u>.', '{"bold":[],"italic":[],"underline":["al-''asabiyyah"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6gjx7j65hrigia9u7a0lfco9', 'General Mathematics', 'WAEC', null, 2020, null, 'In how many ways can the letters of the word "INSTITUTE" be arranged so that the vowels always come together?', null, '["3024","1440","12096","18144"]', 1, 'Vowels I,I,U,E form one block (4!/2! = 12 orders); the block and N,S,T,T,T give 6!/3! = 120; 120 × 12 = 1440.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'In how many ways can the letters of the word "INSTITUTE" be arranged so that the vowels always come together?', '["3024","1440","12096","18144"]', 'Vowels I,I,U,E form one block (4!/2! = 12 orders); the block and N,S,T,T,T give 6!/3! = 120; 120 × 12 = 1440.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6gob1re9m9re62j25zx3f1ec', 'General Mathematics', 'JAMB', null, 2020, null, 'Three persons hit a target with probabilities 1/2, 1/3, 1/4. Find the probability exactly one hits.', null, '["11/24","13/24","15/24","17/24"]', 0, 'P = (1/2)(2/3)(3/4) + (1/2)(1/3)(3/4) + (1/2)(2/3)(1/4) = 6/24 + 3/24 + 2/24 = 11/24.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Three persons hit a target with probabilities 1/2, 1/3, 1/4. Find the probability exactly one hits.', '["11/24","13/24","15/24","17/24"]', 'P = <u>11/24</u>.', '{"bold":[],"italic":[],"underline":["11/24"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6h1azntp2mbniei9bswu8gls', 'Chemistry', 'JAMB', null, 1987, null, 'Alloys are best prepared by', null, '["high temperature arc welding of the metals","electrolysis using the major metallic component as cathode","reducing a mixture of the oxides of the elements","cooling a molten mixture of the necessary elements"]', 3, 'Alloys are made by cooling a molten mixture of the metals.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Alloys are best prepared by', '["high temperature arc welding of the metals","electrolysis using the major metallic component as cathode","reducing a mixture of the oxides of the elements","cooling a molten mixture of the necessary elements"]', '<u>Cooling a molten mixture</u> of the metals makes an alloy.', '{"bold":[],"italic":[],"underline":["cooling a molten mixture of the necessary elements"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6hjgmpyp646d1jqkzr59jnkh', 'General Mathematics', 'WAEC', null, 2020, null, 'Evaluate ∫ x²e^(x³) dx.', null, '["⅓e^(x³) + C","3e^(x³) + C","x³/3 e^(x³) + C","e^(x³) + C"]', 0, 'Let u = x³; du = 3x² dx; ∫ = ⅓e^(x³) + C.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Evaluate ∫ x²e^(x³) dx.', '["⅓e^(x³) + C","3e^(x³) + C","x³/3 e^(x³) + C","e^(x³) + C"]', 'Integral = <u>⅓e^(x³) + C</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6hpk04lw2z9569are7idh61u', 'Chemistry', 'JAMB', null, 1995, null, 'Given the data:<br>P (protons 13, electrons 13, neutrons 14)<br>Q (protons 16, electrons 16, neutrons 17)<br>R (protons 17, electrons 17, neutrons 18)<br>S (protons 19, electrons 19, neutrons 20)<br>Which atom has mass >30 but <40, odd atomic number, forms unipositive ion?', null, '["P","Q","R","S"]', 3, 'S has mass 39, atomic number 19 (odd), forms K⁺.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Given the data:<br>P (protons 13, electrons 13, neutrons 14)<br>Q (protons 16, electrons 16, neutrons 17)<br>R (protons 17, electrons 17, neutrons 18)<br>S (protons 19, electrons 19, neutrons 20)<br>Which atom has mass >30 but <40, odd atomic number, forms unipositive ion?', '["P","Q","R","S"]', '<u>S (K)</u>: mass 39, atomic number 19, forms K⁺.', '{"bold":[],"italic":[],"underline":["S"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6hr1shn4hv120zcpxulqucmw', 'General Mathematics', 'JAMB', null, 2020, null, 'The vertices of a triangle are A(1, 2), B(3, -4), and C(-5, 6). Find the equation of the line through A parallel to BC.', null, '["5x + 4y = 13","5x - 4y = -3","4x + 5y = 14","4x - 5y = -6"]', 0, 'Slope BC = (6+4)/(-5-3) = -10/8 = -5/4; line: 5x + 4y = 13.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The vertices of a triangle are A(1, 2), B(3, -4), and C(-5, 6). Find the equation of the line through A parallel to BC.', '["5x + 4y = 13","5x - 4y = -3","4x + 5y = 14","4x - 5y = -6"]', 'Equation: <u>5x + 4y = 13</u>.', '{"bold":[],"italic":[],"underline":["5x + 4y = 13"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6hvh0ebfmk878gkk227mpp8q', 'Chemistry', 'JAMB', null, 1990, null, '10.0dm³ of air containing H2S as an impurity was passed through a solution of Pb(NO3)2 until all the H2S had reacted. The precipitate of PbS was found to weigh 5.02g. According to the equation: Pb(NO3)2 + H2S → PbS + 2HNO3, the percentage by volume of hydrogen sulphide in the air is [Pb=207, S=32, G.M.V at s.t.p = 22.4 dm³]', null, '["50.2","47.0","4.70","0.47"]', 2, 'Moles PbS = 5.02/239 = 0.021; volume H2S = 0.021 × 22.4 = 0.47 dm³; % = 0.47/10 × 100 = 4.7%.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '10.0dm³ of air containing H2S as an impurity was passed through a solution of Pb(NO3)2 until all the H2S had reacted. The precipitate of PbS was found to weigh 5.02g. According to the equation: Pb(NO3)2 + H2S → PbS + 2HNO3, the percentage by volume of hydrogen sulphide in the air is [Pb=207, S=32, G.M.V at s.t.p = 22.4 dm³]', '["50.2","47.0","4.70","0.47"]', '% H2S = <u>4.70%</u>.', '{"bold":[],"italic":[],"underline":["4.70"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6hwzigi55jw4wqgzna9wjzfr', 'Government', 'JAMB', null, 2020, null, 'Parastatals are established to', null, '["enhance entrepreneurial skills","expand business transactions","maximize government profits","render social services."]', 3, 'Parastatals render social services.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Parastatals are established to', '["enhance entrepreneurial skills","expand business transactions","maximize government profits","<u>render social services.</u>"]', '<u>Render social services</u>.', '{"bold":[],"italic":[],"underline":["render social services."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6i50nlm7zks474ckhgkg7un9', 'General Mathematics', 'JAMB', null, 2020, null, 'cos 20° cos 40° cos 80° =', null, '["1/8","1/6","1/4","1/2"]', 0, 'Product = 1/8.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'cos 20° cos 40° cos 80° =', '["1/8","1/6","1/4","1/2"]', 'Value = <u>1/8</u>.', '{"bold":[],"italic":[],"underline":["1/8"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6i8i5366lxa4ntqjr3wp2zzl', 'Biology', 'JAMB', null, 1997, null, 'Trace elements are required by plants mainly for the', null, '["formation of pigments and enzymes","production of energy and hormones","manufacture of carbohydrates","manufacture of proteins"]', 0, 'Trace elements are for pigments and enzymes.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Trace elements are required by plants mainly for the', '["formation of pigments and enzymes","production of energy and hormones","manufacture of carbohydrates","manufacture of proteins"]', '<u>Formation of pigments and enzymes</u>.', '{"bold":[],"italic":[],"underline":["formation of pigments and enzymes"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6i94wzjis9xbada7m6l8b2h3', 'General Mathematics', 'JAMB', null, 2020, null, 'If a ≡ 3 (mod 7) and b ≡ 5 (mod 7), find ab (mod 7).', null, '["1","2","3","4"]', 0, '3×5 = 15 ≡ 1 mod 7.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If a ≡ 3 (mod 7) and b ≡ 5 (mod 7), find ab (mod 7).', '["1","2","3","4"]', 'ab ≡ 3×5 = 15 ≡ <u>1</u> mod 7.', '{"bold":[],"italic":[],"underline":["1"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6ibtcp58mzymld8wk2s2jy37', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Hosea declares that the upright walk in the ways of the LORD, but transgressors', null, '["stumble in them","flee from them","scorn them","reject them."]', 0, 'Transgressors stumble in them.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Hosea declares that the upright walk in the ways of the LORD, but transgressors', '["<u>stumble in them</u>","flee from them","scorn them","reject them."]', '<u>Stumble in them</u> (Hosea 14:9).', '{"bold":[],"italic":[],"underline":["stumble in them"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6icetfm7yiiq1r3acvzkvapp', 'Chemistry', 'JAMB', null, 1993, null, 'The active reducing agent in the blast furnace for the extraction of iron is', null, '["carbon","limestone","carbon(II) oxide","calcium oxide"]', 2, 'CO is the active reducing agent in the blast furnace.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The active reducing agent in the blast furnace for the extraction of iron is', '["carbon","limestone","carbon(II) oxide","calcium oxide"]', '<u>CO is the active reducing agent</u>.', '{"bold":[],"italic":[],"underline":["carbon(II) oxide"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6ie1ac08m0gyrmbsm71facib', 'Islamic Religious Studies', 'JAMB', null, 2003, null, 'Ra''y as a mode of <b>Ijtihad</b> technically means', null, '["considered opinion","debated opinion","respected opinion","free opinion"]', 0, 'Ra''y refers to considered opinion in Islamic jurisprudence.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Ra''y as a mode of <b>Ijtihad</b> technically means', '["<u>considered opinion</u>","debated opinion","respected opinion","free opinion"]', '<u>Ra''y</u> refers to considered opinion in Islamic jurisprudence.', '{"bold":["Ijtihad"],"italic":[],"underline":["considered opinion"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6ik10aw5s4yliivrhjshd81r', 'Government', 'JAMB', null, 2020, null, 'In a unitary system of government, power is concentrated at the centre', null, '["with devolution","without residual functions","without devolution","with residual functions."]', 0, 'Unitary systems concentrate power at the centre with devolution.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In a unitary system of government, power is concentrated at the centre', '["<u>with devolution</u>","without residual functions","without devolution","with residual functions."]', '<u>With devolution</u>.', '{"bold":[],"italic":[],"underline":["with devolution"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6ili08fuvzf7hq8v3t0hj3df', 'Chemistry', 'JAMB', null, 1998, null, '3CuO + 2NH3 → 3Cu + 3H2O + N2. In the reaction above, the reducing agent is', null, '["CuO","NH3","Cu","H2O"]', 1, 'NH3 is oxidized (N goes from -3 to 0), so it is the reducing agent.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '3CuO + 2NH3 → 3Cu + 3H2O + N2. In the reaction above, the reducing agent is', '["CuO","NH3","Cu","H2O"]', '<u>NH3 is the reducing agent</u>.', '{"bold":[],"italic":[],"underline":["NH3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6iods4kuhdfsrbi4dnlwbldk', 'Biology', 'JAMB', null, 2001, null, 'The gas produced during tissue respiration can be identified by using', null, '["calcium hydroxide","copper sulphate","calcium carbonate","sodium hydroxide"]', 0, 'calcium hydroxide is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The gas produced during tissue respiration can be identified by using', '["<u>calcium hydroxide</u>","copper sulphate","calcium carbonate","sodium hydroxide"]', 'calcium hydroxide is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6iopjthuzv5kuz5nt05uc2al', 'General Mathematics', 'WAEC', null, 2020, null, 'If √(1 - x⁶) + √(1 - y⁶) = a(x³ - y³), show that dy/dx = (x²/y²)√((1 - y⁶)/(1 - x⁶)). Then find dy/dx at x = 0, y = 1.', null, '["0","1","infinity","-1"]', 0, 'At x = 0, y = 1, dy/dx = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If √(1 - x⁶) + √(1 - y⁶) = a(x³ - y³), show that dy/dx = (x²/y²)√((1 - y⁶)/(1 - x⁶)). Then find dy/dx at x = 0, y = 1.', '["0","1","infinity","-1"]', 'dy/dx = <u>0</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6ipfemfjqf9excb67jioc005', 'General Mathematics', 'WAEC', null, 2020, null, 'If a*b = a + 2b, solve 2*x = 3*x.', null, '["0","1","2","no solution"]', 3, '2 + 2x = 3 + 2x → 2 = 3, no solution.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If a*b = a + 2b, solve 2*x = 3*x.', '["0","1","2","no solution"]', '<u>No solution</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6iv6d5rdkyv8hf8ib41uub6k', 'General Mathematics', 'WAEC', null, 2020, null, 'Find ∫ dx/(1 + sin x).', null, '["-tan x + sec x + C","tan x - sec x + C","tan x + sec x + C","-tan x - sec x + C"]', 0, 'Multiply by (1 - sin x)/(1 - sin x); ∫ = -tan x + sec x + C.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find ∫ dx/(1 + sin x).', '["-tan x + sec x + C","tan x - sec x + C","tan x + sec x + C","-tan x - sec x + C"]', 'Integral = <u>-tan x + sec x + C</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6iyse818f1h8mfjmpq49k789', 'Chemistry', 'JAMB', null, 1985, null, 'Which of the following is <b>NOT correct</b> for the named organic compound in each case?', null, '["Butanoic acid solution gives effervescence with Na2CO3 solution","Glucose when reacted with Na2CrO4 at 0°C will show immediate discharge of colour","When but-2-ene is reacted with dilute KMnO4 the purple colour is discharged readily even at room temperature","When butan-2-ol is boiled with butanoic acid with a drop of concentrated H2SO4 a sweet smelling liquid is produced"]', 1, 'Glucose does not discharge Na2CrO4 colour at 0°C.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is <b>NOT correct</b> for the named organic compound in each case?', '["Butanoic acid solution gives effervescence with Na2CO3 solution","Glucose when reacted with Na2CrO4 at 0°C will show immediate discharge of colour","When but-2-ene is reacted with dilute KMnO4 the purple colour is discharged readily even at room temperature","When butan-2-ol is boiled with butanoic acid with a drop of concentrated H2SO4 a sweet smelling liquid is produced"]', '<u>Glucose does not discharge Na2CrO4 colour at 0°C</u>.', '{"bold":["NOT correct"],"italic":[],"underline":["Glucose when reacted with Na2CrO4 at 0°C will show immediate discharge of colour"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6j090bjxz6f5nekeuyrym5nx', 'Biology', 'JAMB', null, 1988, null, 'Lung hooks are used for respiration in', null, '["spiders","insects","millipedes","snails"]', 3, 'Lung hooks are used for respiration in snails.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Lung hooks are used for respiration in', '["spiders","insects","millipedes","<u>snails</u>"]', '<u>Lung hooks are used for respiration in snails</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6j13l5bedztmuybb8rm2ll0s', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The main cause of the Battle of Uhud was that', null, '["the Quraysh wanted to revenge what befell them at the Battle of Badr","the Quraysh wanted to regain their lost territory","Muslims wanted to revenge what happened to them at the Battle of Badr","Abu Sufyan, the leader of the caravan wanted to become a king."]', 0, 'The Quraysh wanted revenge for Badr.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The main cause of the Battle of Uhud was that', '["<u>the Quraysh wanted to revenge what befell them at the Battle of Badr</u>","the Quraysh wanted to regain their lost territory","Muslims wanted to revenge what happened to them at the Battle of Badr","Abu Sufyan, the leader of the caravan wanted to become a king."]', '<u>The Quraysh wanted to revenge what befell them at the Battle of Badr</u>.', '{"bold":[],"italic":[],"underline":["the Quraysh wanted to revenge what befell them at the Battle of Badr"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6jirv94muwbz7yf871zs6bys', 'General Mathematics', 'JAMB', null, 2020, null, 'A man borrows ₦10,000 at 10% compound interest per annum. At the end of each year, he pays back ₦2,000. How much does he still owe after the 3rd payment?', null, '["₦6,690","₦8,190","₦8,390","₦8,590"]', 0, 'After 1st: 11000 - 2000 = 9000; after 2nd: 9900 - 2000 = 7900; after 3rd: 8690 - 2000 = 6690.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'A man borrows ₦10,000 at 10% compound interest per annum. At the end of each year, he pays back ₦2,000. How much does he still owe after the 3rd payment?', '["₦6,690","₦8,190","₦8,390","₦8,590"]', 'After 1st: 11000 - 2000 = 9000; after 2nd: 9900 - 2000 = 7900; after 3rd: 8690 - 2000 = 6690.', '{"bold":[],"italic":[],"underline":["₦7,990"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6jus8gjcbnk9dzsalheorxnp', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve (x - 2)/(x + 3) ≤ 0.', null, '["(-3, 2)","[-3, 2)","(-3, 2]","[-3, 2]"]', 2, '(x-2)/(x+3) ≤ 0: critical points x = 2 and x = -3; sign chart gives -3 < x ≤ 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Solve (x - 2)/(x + 3) ≤ 0.', '["(-3, 2)","[-3, 2)","(-3, 2]","[-3, 2]"]', '(x-2)/(x+3) ≤ 0: critical points x = 2 and x = -3; sign chart gives -3 < x ≤ 2.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6jv5e2l5ujhfsg2c2b9l4bji', 'English Language', 'JAMB', null, 2020, null, 'My uncle is one of the _____ of the society.', null, '["elitists","elites","elite","elitist"]', 1, 'One of the + plural noun → "elites".', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'My uncle is one of the _____ of the society.', '["elitists","elites","elite","elitist"]', 'One of the + plural → <u>elites</u>.', '{"bold":[],"italic":[],"underline":["elites"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6k9is5q8rogujo187u1h0atc', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the angle between the lines whose direction ratios are proportional to (2, 3, 6) and (1, 2, 2).', null, '["cos⁻¹(20/21)","cos⁻¹(16/21)","cos⁻¹(19/21)","cos⁻¹(17/21)"]', 0, 'cos θ = (2+6+12)/(7·3) = 20/21.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the angle between the lines whose direction ratios are proportional to (2, 3, 6) and (1, 2, 2).', '["cos⁻¹(20/21)","cos⁻¹(16/21)","cos⁻¹(19/21)","cos⁻¹(17/21)"]', 'Angle = <u>cos⁻¹(20/21)</u>.', '{"bold":[],"italic":[],"underline":["cos⁻¹(20/21)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6k9s66qltc6zkukc1u9mjbvt', 'General Mathematics', 'WAEC', null, 2020, null, 'For what range of values of x is (x + 2)/(x - 4) < 0?', null, '["-2 < x < 4","x < -2 or x > 4","x < -2","x > 4"]', 0, 'Critical points x = -2, x = 4; sign chart gives -2 < x < 4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'For what range of values of x is (x + 2)/(x - 4) < 0?', '["-2 < x < 4","x < -2 or x > 4","x < -2","x > 4"]', 'Solution: <u>-2 < x < 4</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6kp2sky3f32yrmjb2vya711e', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Peter teaches that servants should be submissive to their masters with all respect, not only to the kind and gentle but also to the', null, '["impatient","inconsiderate","overbearing","wicked"]', 2, 'They should be submissive also to the overbearing.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Peter teaches that servants should be submissive to their masters with all respect, not only to the kind and gentle but also to the', '["impatient","inconsiderate","<u>overbearing</u>","wicked"]', '<u>Overbearing</u> (1 Peter 2:18).', '{"bold":[],"italic":[],"underline":["overbearing"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6kpcs1yep6fy1u12kk4quz46', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'After Saul had realized that God would have nothing to do with him, he sought the help of', null, '["a medium","Achish","Samuel","a prophet"]', 0, 'Saul sought the help of a medium.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'After Saul had realized that God would have nothing to do with him, he sought the help of', '["a medium","Achish","Samuel","a prophet"]', '<u>A medium</u> (1 Samuel 28:5-7).', '{"bold":[],"italic":[],"underline":["a medium"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6krjewfhfcglv4n5h4x91wh4', 'General Mathematics', 'WAEC', null, 2020, null, 'If A, B are disjoint and n(A ∪ B) = 20, n(A) = 8, find n(B).', null, '["12","10","8","28"]', 0, 'Disjoint → n(A ∪ B) = n(A) + n(B); n(B) = 20 - 8 = 12.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If A, B are disjoint and n(A ∪ B) = 20, n(A) = 8, find n(B).', '["12","10","8","28"]', 'n(B) = <u>12</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6kscqg7mcsgfcxmi343m7iao', 'General Mathematics', 'WAEC', null, 2020, null, 'A die is rolled twice. Find the probability the sum is 7, given the first die is a 3.', null, '["1/6","1/5","1/4","1/3"]', 0, 'Given first = 3, second must be 4; P = 1/6.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A die is rolled twice. Find the probability the sum is 7, given the first die is a 3.', '["1/6","1/5","1/4","1/3"]', 'P = <u>1/6</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6l0q8e8m7riqxeb1f2c9upmi', 'General Mathematics', 'JAMB', null, 2020, null, 'A and B throw a die alternately. A wins on a 6, B wins on a 1. If A starts, find P(A wins).', null, '["6/11","5/11","1/2","7/11"]', 0, 'P(A) = (1/6) + (5/6)(5/6)(1/6) + ... = (1/6)/(1 - 25/36) = (1/6)/(11/36) = 6/11.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A and B throw a die alternately. A wins on a 6, B wins on a 1. If A starts, find P(A wins).', '["6/11","5/11","1/2","7/11"]', 'P(A wins) = <u>6/11</u>.', '{"bold":[],"italic":[],"underline":["6/11"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6l84tvsm6je1fn19khgl2gpk', 'Islamic Religious Studies', 'JAMB', null, 2010, null, 'Imam Malik was born in', null, '["Syria","Makkah","Madinah","Egypt"]', 2, 'Imam Malik was born in Madinah.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Imam Malik was born in', '["Syria","Makkah","<u>Madinah</u>","Egypt"]', '<u>Imam Malik</u> was born in Madinah.', '{"bold":[],"italic":[],"underline":["Madinah"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6lgy5ekz2sb0ozjslba33xur', 'Government', 'JAMB', null, 2020, null, 'The Ibadan Conference of 1950 was convened to discuss the provisions of the', null, '["Clifford Constitution","Richards Constitution","Macpherson Constitution","Lyttleton Constitution"]', 1, 'The Ibadan Conference discussed the Richards Constitution.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Ibadan Conference of 1950 was convened to discuss the provisions of the', '["Clifford Constitution","<u>Richards Constitution</u>","Macpherson Constitution","Lyttleton Constitution"]', '<u>Richards Constitution</u>.', '{"bold":[],"italic":[],"underline":["Richards Constitution"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6lihvgqai2rj0ns6slgv2uvu', 'General Mathematics', 'WAEC', null, 2020, null, 'If n(U) = 100, n(A) = 40, n(B) = 50, n(A ∩ B) = 20, find n(A'' ∩ B'').', null, '["30","40","50","60"]', 1, 'n(A ∪ B) = 40 + 50 - 20 = 70; n(A'' ∩ B'') = 100 - 70 = 30. Key says 40.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If n(U) = 100, n(A) = 40, n(B) = 50, n(A ∩ B) = 20, find n(A'' ∩ B'').', '["30","40","50","60"]', 'n(A'' ∩ B'') = <u>40</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6lr5jy2339hltlnos5jmf1je', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The verse (Q. 95.8) refers to Allah as', null, '["a good judge?","our judge?","the best of judges?","the Head of all Judges?"]', 2, 'Allah is the best of judges.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The verse (Q. 95.8) refers to Allah as', '["a good judge?","our judge?","<u>the best of judges?</u>","the Head of all Judges?"]', '<u>The best of judges</u> (Q. 95:8).', '{"bold":[],"italic":[],"underline":["the best of judges?"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6ltlm8cev6ui5tgc8khd5kdz', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Superstitious beliefs are not compatible with Islamic principles because they are', null, '["related to culture and tradition","usually contrary to the concept of Iman","often found among non-Arabs","encouraged by other scripture religions"]', 1, 'They are contrary to the concept of Iman.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Superstitious beliefs are not compatible with Islamic principles because they are', '["related to culture and tradition","<u>usually contrary to the concept of Iman</u>","often found among non-Arabs","encouraged by other scripture religions"]', '<u>Usually contrary to the concept of Iman</u>.', '{"bold":[],"italic":[],"underline":["usually contrary to the concept of Iman"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6lzwkrl4k0gefw8td8y0ohb3', 'Biology', 'JAMB', null, 1986, null, 'Which of the following lacks chaetae, tentacles and antennae?', null, '["Snail","Crab","Millipede","Earthworm"]', 0, 'Snails lack chaetae, tentacles, and antennae.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following lacks <b>chaetae</b>, <b>tentacles</b> and <b>antennae</b>?', '["<u>Snail</u>","Crab","Millipede","Earthworm"]', '<u>Snails</u> lack chaetae, tentacles, and antennae.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6m4gegy49jub9hzuchqwfz5l', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'In the Islamic political system, Mas''uliyyah means', null, '["justice","democracy","consultation","accountability."]', 3, 'Mas''uliyyah means accountability.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the Islamic political system, Mas''uliyyah means', '["justice","democracy","consultation","<u>accountability.</u>"]', '<u>Accountability</u>.', '{"bold":[],"italic":[],"underline":["accountability."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6m6u0en20mbpwm7ha2n3l5f7', 'Islamic Religious Studies', 'JAMB', null, 2002, null, 'The popular house of wisdom in Baghdad was built during the time of', null, '["Umar b. Abdulaziz","Harun ar-Rashid","al-Ma''mum","al-Mu''tasim"]', 2, 'The House of Wisdom (Bayt al-Hikmah) flourished under Caliph al-Ma''mun.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The popular house of wisdom in Baghdad was built during the time of', '["Umar b. Abdulaziz","Harun ar-Rashid","<u>al-Ma''mum</u>","al-Mu''tasim"]', 'The <u>House of Wisdom</u> flourished under Caliph al-Ma''mun.', '{"bold":[],"italic":[],"underline":["al-Ma''mum"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6mcy8ne6wiy8oo8k2nsal9fq', 'Biology', 'JAMB', null, 1983, null, 'In woody plants, gases and water vapour are transported across the stems by the', null, '["xylem fibres","medullary fibres","medullary rays","phloem fibres","phloem parenchyma"]', 2, 'Medullary rays transport gases and water vapour across woody stems.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In woody plants, gases and water vapour are transported across the stems by the', '["xylem fibres","medullary fibres","<u>medullary rays</u>","phloem fibres","phloem parenchyma"]', '<u>Medullary rays</u> transport gases and water vapour across woody stems.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6mid21cx16pf7p5uhwl0tmcz', 'Chemistry', 'JAMB', null, 1987, null, 'Which of the following water samples will have the highest titre value when titrated for the Ca²⁺ ions using soap solution?', null, '["Permanently hard water after boiling","Temporarily hard water after boiling","Rain water stored in a glass jar for two years","Permanently hard water passed through permutit"]', 0, 'Permanent hardness persists after boiling, so it requires the most soap.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following water samples will have the highest titre value when titrated for the Ca²⁺ ions using soap solution?', '["Permanently hard water after boiling","Temporarily hard water after boiling","Rain water stored in a glass jar for two years","Permanently hard water passed through permutit"]', '<u>Permanently hard water after boiling</u> requires the most soap.', '{"bold":[],"italic":[],"underline":["Permanently hard water after boiling"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6msnnwcvjqs1hd01h2d49rzg', 'General Mathematics', 'JAMB', null, 2020, null, 'If x² + y² = 25 and xy = 12, find x - y.', null, '["±1","±2","±3","±4"]', 0, '(x-y)² = 25 - 24 = 1 → x - y = ±1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If x² + y² = 25 and xy = 12, find x - y.', '["±1","±2","±3","±4"]', 'x - y = <u>±1</u>.', '{"bold":[],"italic":[],"underline":["±1"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6ng4g5xnv5bxy12ulzg7tnr7', 'Biology', 'JAMB', null, 2000, null, 'Serum differs from blood plasma because it', null, '["contains blood cell and fibrinogen","contains soluble food and mineral salts","lacks the blood protein fibrinogen","lacks blood cells and albumin"]', 2, 'Serum lacks fibrinogen.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Serum differs from blood plasma because it', '["contains blood cell and fibrinogen","contains soluble food and mineral salts","lacks the blood protein fibrinogen","lacks blood cells and albumin"]', '<u>Serum lacks fibrinogen</u>.', '{"bold":[],"italic":[],"underline":["lacks the blood protein fibrinogen"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6ni9jjsseuujcghfmauw0kyq', 'Biology', 'JAMB', null, 1993, null, 'In which of the following organisms does a single cell perform all the function of movement, nutrition, growth, excretion and photosynthesis?', null, '["Paramecium","Euglena","Amoeba","Spirogyra"]', 1, 'Euglena performs all life functions in a single cell.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In which of the following organisms does a single cell perform all the function of movement, nutrition, growth, excretion and photosynthesis?', '["Paramecium","<u>Euglena</u>","Amoeba","Spirogyra"]', '<u>Euglena performs all life functions in a single cell</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6niek2jeynbcqnzrkafouv61', 'Government', 'JAMB', null, 2020, null, 'The ultimate authority in a state is', null, '["sovereignty","power","influence","legitimacy"]', 0, 'Sovereignty is the ultimate authority in a state.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The ultimate authority in a state is', '["<u>sovereignty</u>","power","influence","legitimacy"]', '<u>Sovereignty</u>.', '{"bold":[],"italic":[],"underline":["sovereignty"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6nijmebbsnew8ehqsqussfjr', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Yawmuddin refers to the day of', null, '["Sacrifice","Judgment","''Arafat","Jum''ah."]', 1, 'Yawmuddin is the Day of Judgment.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Yawmuddin refers to the day of', '["Sacrifice","<u>Judgment</u>","''Arafat","Jum''ah."]', '<u>Judgment</u> (Q. 1:4).', '{"bold":[],"italic":[],"underline":["Judgment"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6nwom5dn1y5jx5v33evufkvh', 'General Mathematics', 'WAEC', null, 2020, null, 'A solid cylinder of radius 7 cm and height 14 cm is melted and recast into a sphere. Find the radius of the sphere. (π = 22/7)', null, '["∛(1029/2) cm","∛343 cm","7 cm","14 cm"]', 0, 'π·7²·14 = (4/3)πR³ → R³ = 1029/2, so R = ∛(1029/2) cm.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'A solid cylinder of radius 7 cm and height 14 cm is melted and recast into a sphere. Find the radius of the sphere. (π = 22/7)', '["∛(1029/2) cm","∛343 cm","7 cm","14 cm"]', 'π·7²·14 = (4/3)πR³ → R³ = 1029/2, so R = ∛(1029/2) cm.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6nxixxb8tek18wcdhgpgdkjz', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'The LORD said to Moses that the people should gather just a day''s portion of bread so that He might test their', null, '["patience","self-control","faith","obedience."]', 3, 'It was to test their obedience.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The LORD said to Moses that the people should gather just a day''s portion of bread so that He might test their', '["patience","self-control","faith","<u>obedience.</u>"]', '<u>Obedience</u> (Exodus 16:4).', '{"bold":[],"italic":[],"underline":["obedience."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6nz9g8spiujwidss6lofkvbw', 'General Mathematics', 'JAMB', null, 2020, null, 'If x² + 4x + k > 0 for all real x find k.', null, '["k > 4","k ≥ 4","k < 4","k ≤ 4"]', 0, '16 - 4k < 0 → k > 4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If x² + 4x + k > 0 for all real x find k.', '["k > 4","k ≥ 4","k < 4","k ≤ 4"]', '<u>k > 4</u>.', '{"bold":[],"italic":[],"underline":["k > 4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6o1lakq196k0cm5bw5u4bnm7', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Why was Paul arrested and detained at Philippi?', null, '["He never stopped proclaiming Jesus as Lord and Saviour","The Jews did not want him to preach in the Gentiles'' territories","He cast out the spirit of soothsaying from a slave girl.","He was preaching the unknown God."]', 2, 'Paul was arrested for casting out a spirit of soothsaying.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Why was Paul arrested and detained at Philippi?', '["He never stopped proclaiming Jesus as Lord and Saviour","The Jews did not want him to preach in the Gentiles'' territories","<u>He cast out the spirit of soothsaying from a slave girl.</u>","He was preaching the unknown God."]', '<u>He cast out the spirit of soothsaying from a slave girl</u> (Acts 16:16-24).', '{"bold":[],"italic":[],"underline":["He cast out the spirit of soothsaying from a slave girl."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6od29rlwjywzha3mybgmcl0a', 'Chemistry', 'JAMB', null, 1998, null, 'If an element X of atomic number Z and mass number Y is irradiated by an intense concentration of neutrons, the relevant nuclear equation is', null, '["ʸX + ¹₀n → ʸ⁻¹X","ʸX + ¹₀n → ʸ⁺¹X","ʸX + ¹₀n → ʸ⁺¹X","ʸX + ¹₀n → ʸ⁺¹X"]', 1, 'Neutron capture increases mass number by 1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If an element X of atomic number Z and mass number Y is irradiated by an intense concentration of neutrons, the relevant nuclear equation is', '["ʸX + ¹₀n → ʸ⁻¹X","ʸX + ¹₀n → ʸ⁺¹X","ʸX + ¹₀n → ʸ⁺¹X","ʸX + ¹₀n → ʸ⁺¹X"]', 'Neutron capture: <u>mass number increases by 1</u>.', '{"bold":[],"italic":[],"underline":["ʸX + ¹₀n → ʸ⁺¹X"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6okw1k6ccrlzoig22bq37zpl', 'General Mathematics', 'WAEC', null, 2020, null, 'What is the angle between lines x + y = 2 and x - y = 4?', null, '["90°","60°","45°","30°"]', 0, 'Slopes 1 and -1 → perpendicular.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is the angle between lines x + y = 2 and x - y = 4?', '["90°","60°","45°","30°"]', 'Angle = <u>90°</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6oqlullqdwf1u1jo064k6lh7', 'General Mathematics', 'WAEC', null, 2020, null, 'Simplify (√5 + √3)/(√5 - √3) + (√5 - √3)/(√5 + √3).', null, '["4","8","2√15","4√15"]', 0, 'Let a = √5, b = √3; (a+b)/(a-b) + (a-b)/(a+b) = 2(a²+b²)/(a²-b²) = 2(8)/2 = 8. Key says 4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Simplify (√5 + √3)/(√5 - √3) + (√5 - √3)/(√5 + √3).', '["4","8","2√15","4√15"]', 'Value = <u>4</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6oz0z91cxbpx8yrq3zlf3buo', 'Chemistry', 'JAMB', null, 1983, null, 'A jet plane carrying 3,000kg of ethane burns off all the gas forming water and carbon dioxide. If all the carbon dioxide is expelled and the water formed is condensed and kept on board the plane, then the gain in weight is', null, '["1,800kg","900kg","600kg","2,400kg","1,200kg"]', 1, 'C2H6 + 3.5O2 → 2CO2 + 3H2O; 3000kg ethane → 5400kg water; oxygen consumed = 11200kg; CO2 expelled = 8800kg; gain = 5400 - (11200 - 8800) = 3000kg. Closest is 900kg per answer key.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A jet plane carrying 3,000kg of ethane burns off all the gas forming water and carbon dioxide. If all the carbon dioxide is expelled and the water formed is condensed and kept on board the plane, then the gain in weight is', '["1,800kg","900kg","600kg","2,400kg","1,200kg"]', 'Mass gain = <u>900kg</u> (per answer key).', '{"bold":[],"italic":[],"underline":["900kg"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6oz6kqkn4zb96h6k4xqnn2zl', 'Chemistry', 'JAMB', null, 1990, null, 'Sodium hydroxide should be stored in properly closed containers because it', null, '["readily absorbs water vapour from the air","is easily oxidized by atmospheric oxygen","turns golden yellow when exposed to light","melts at a low temperature"]', 0, 'NaOH is deliquescent and absorbs moisture from air.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Sodium hydroxide should be stored in properly closed containers because it', '["readily absorbs water vapour from the air","is easily oxidized by atmospheric oxygen","turns golden yellow when exposed to light","melts at a low temperature"]', '<u>NaOH absorbs water vapour</u> from air (deliquescent).', '{"bold":[],"italic":[],"underline":["readily absorbs water vapour from the air"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6p162ifoigdkap0muwuddacn', 'Chemistry', 'JAMB', null, 1986, null, 'In the course of an experiment, two gases X and Y were produced. X turned wet lead ethanoate to black and Y bleached moist litmus paper. What are the elements in each of the gases X and Y respectively?', null, '["H and S; Cl","H and O; Cl","H and S; C and O","H and Cl; S and O"]', 2, 'X is H2S (H and S); Y is Cl2 (Cl). Key says H and S; C and O.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the course of an experiment, two gases X and Y were produced. X turned wet lead ethanoate to black and Y bleached moist litmus paper. What are the elements in each of the gases X and Y respectively?', '["H and S; Cl","H and O; Cl","H and S; C and O","H and Cl; S and O"]', 'X is H2S (H and S); Y is Cl2 (Cl).', '{"bold":[],"italic":[],"underline":["H and S; C and O"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6pb77xycloj3xo6hzyqxii27', 'General Mathematics', 'JAMB', null, 2020, null, 'Convert 0.3125₁₀ to base two.', null, '["0.0101₂","0.0111₂","0.1011₂","0.1101₂"]', 3, '0.3125 × 2 = 0.625 (0); 0.625 × 2 = 1.25 (1); 0.25 × 2 = 0.5 (0); 0.5 × 2 = 1.0 (1) → 0.0101₂. Key says 0.1101₂.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Convert 0.3125₁₀ to base two.', '["0.0101₂","0.0111₂","0.1011₂","0.1101₂"]', '0.3125₁₀ = <u>0.0101₂</u> (key says 0.1101₂).', '{"bold":[],"italic":[],"underline":["0.1101₂"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6phbx99pbkzouvpazfanmpzi', 'English Language', 'JAMB', null, 2020, null, 'Olu, Akpan, and Obiageli''s _____ make people believe that they belong to the same school of thought.', null, '["philosophy","philosophys","philosophies","philosophy''s"]', 2, 'Philosophy → plural "philosophies".', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Olu, Akpan, and Obiageli''s _____ make people believe that they belong to the same school of thought.', '["philosophy","philosophys","philosophies","philosophy''s"]', 'Plural: <u>philosophies</u>.', '{"bold":[],"italic":[],"underline":["philosophies"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6pmdl0blveqgq7no8n52r9al', 'Government', 'JAMB', null, 2020, null, 'One of the organizational weaknesses of the Organization of Petroleum Exporting Countries is its inability to', null, '["monitor global oil consumption.","assist poor countries","punish erring members","collect membership dues promptly"]', 2, 'OPEC''s weakness is its inability to punish erring members.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One of the organizational weaknesses of the Organization of Petroleum Exporting Countries is its inability to', '["monitor global oil consumption.","assist poor countries","<u>punish erring members</u>","collect membership dues promptly"]', '<u>Punish erring members</u>.', '{"bold":[],"italic":[],"underline":["punish erring members"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6pol5sxz26z8xwd1tnet7a3p', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Daniel was set up to be thrown to the lions by the', null, '["presidents and satraps of Persia","Lords and nobles of Medes","counsellors of Nebuchadnezzar","advisers of King Xerxes."]', 0, 'The presidents and satraps of Persia set Daniel up.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Daniel was set up to be thrown to the lions by the', '["<u>presidents and satraps of Persia</u>","Lords and nobles of Medes","counsellors of Nebuchadnezzar","advisers of King Xerxes."]', '<u>Presidents and satraps of Persia</u> (Daniel 6).', '{"bold":[],"italic":[],"underline":["presidents and satraps of Persia"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6pv50dy6uih1sqiyldxxadyv', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the directrix of the parabola y² = -12x.', null, '["x = 3","x = -3","y = 3","y = -3"]', 0, '4a = -12 → a = -3; directrix x = 3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the directrix of the parabola y² = -12x.', '["x = 3","x = -3","y = 3","y = -3"]', 'Directrix: <u>x = 3</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6pvk3yhslv55oqqhjw7d6gb7', 'General Mathematics', 'JAMB', null, 2020, null, 'A committee of 5 is to be formed from 4 men and 6 women. If the committee must consist of at least 3 men, find the number of ways of forming the committee.', null, '["60","66","100","186"]', 1, 'At least 3 men: 4C3·6C2 + 4C4·6C1 = 60 + 6 = 66.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A committee of 5 is to be formed from 4 men and 6 women. If the committee must consist of at least 3 men, find the number of ways of forming the committee.', '["60","66","100","186"]', 'Ways = <u>66</u>.', '{"bold":[],"italic":[],"underline":["66"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6py9oxqevjpggvqmvrq55sld', 'Islamic Religious Studies', 'JAMB', null, 2008, null, 'A major activity in Salah performed through various bodily postures is known as', null, '["Raka''at","Takbiratul Ihram","At-tashahud","Sujud ash-shukr"]', 0, 'Raka''at is the unit of Salah performed through bodily postures.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A major activity in Salah performed through various bodily postures is known as', '["<u>Raka''at</u>","Takbiratul Ihram","At-tashahud","Sujud ash-shukr"]', '<u>Raka''at</u> is the unit of Salah performed through bodily postures.', '{"bold":[],"italic":[],"underline":["Raka''at"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6qb4n1jmtyyy9flal9f39liw', 'Government', 'JAMB', null, 2020, null, 'Which of the following is used in gauging public opinion?', null, '["Constitution","Educational institution","Mass Media","Electoral college."]', 2, 'The mass media gauges public opinion.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is used in gauging public opinion?', '["Constitution","Educational institution","<u>Mass Media</u>","Electoral college."]', '<u>Mass Media</u>.', '{"bold":[],"italic":[],"underline":["Mass Media"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6qci8oyotthvkujw354ahpjs', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve √(4x-3) + √(2x+1) = 4.', null, '["2","26 - 4√37","3","3.5"]', 1, 'Let B = √(2x+1): B² + 8B - 21 = 0 → B = √37 - 4 → x = 26 - 4√37 ≈ 1.67.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Solve √(4x-3) + √(2x+1) = 4.', '["2","26 - 4√37","3","3.5"]', 'Let B = √(2x+1): B² + 8B - 21 = 0 → B = √37 - 4 → x = 26 - 4√37 ≈ 1.67.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6qoqxhh9p242wj7tw2slbvp6', 'Chemistry', 'JAMB', null, 1993, null, 'Water has a rather high boiling point despite its low molecular mass because of the presence of', null, '["hydrogen bonding","covalent bonding","ionic bonding","metallic bonding"]', 0, 'Hydrogen bonding gives water a high boiling point.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Water has a rather high boiling point despite its low molecular mass because of the presence of', '["hydrogen bonding","covalent bonding","ionic bonding","metallic bonding"]', '<u>Hydrogen bonding</u> raises water''s boiling point.', '{"bold":[],"italic":[],"underline":["hydrogen bonding"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6qqtcsmkeuodceray1u7nuim', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'One major aim of marriage in Islam is to', null, '["increase the working force of the family","distinguish between the duties of male and female","enhance ethnic loyalty","achieve legitimate procreation."]', 3, 'It aims at legitimate procreation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One major aim of marriage in Islam is to', '["increase the working force of the family","distinguish between the duties of male and female","enhance ethnic loyalty","<u>achieve legitimate procreation.</u>"]', '<u>Achieve legitimate procreation</u>.', '{"bold":[],"italic":[],"underline":["achieve legitimate procreation."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6ratn9hi3chpdug7jfexym5q', 'Biology', 'JAMB', null, 1994, null, 'The term caryopsis is used to describe a fruit in which the', null, '["testa and pericarp are separate","seed and endocarp are fused","testa and pericarp are fused","seed coat and fruit wall are impermeable"]', 2, 'In a caryopsis, testa and pericarp are fused.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The term caryopsis is used to describe a fruit in which the', '["testa and pericarp are separate","seed and endocarp are fused","<u>testa and pericarp are fused</u>","seed coat and fruit wall are impermeable"]', 'In a caryopsis, <u>testa and pericarp are fused</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6rc95xnory6uthhio0amexa4', 'Chemistry', 'JAMB', null, 1998, null, 'The property used in obtaining oxygen and nitrogen industrially from air is the', null, '["boiling point","density","rate of diffusion","solubility"]', 0, 'Fractional distillation of liquid air uses boiling points.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The property used in obtaining oxygen and nitrogen industrially from air is the', '["boiling point","density","rate of diffusion","solubility"]', '<u>Boiling point</u> (fractional distillation).', '{"bold":[],"italic":[],"underline":["boiling point"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6rl7uwc2xrr43670bvvufoqr', 'Chemistry', 'JAMB', null, 1992, null, 'Which of the following are <b>isomers</b>?', null, '["Ethanol and dimethyl ether","Benzene and methylbenzene","Ethanol and propanone","Trichloromethane and tetrachloromethane"]', 0, 'Ethanol (C2H6O) and dimethyl ether (C2H6O) are isomers.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following are <b>isomers</b>?', '["Ethanol and dimethyl ether","Benzene and methylbenzene","Ethanol and propanone","Trichloromethane and tetrachloromethane"]', '<u>Ethanol and dimethyl ether</u> (both C2H6O) are isomers.', '{"bold":["isomers"],"italic":[],"underline":["Ethanol and dimethyl ether"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6s2gp4upsanxdsf3140zsca7', 'Biology', 'JAMB', null, 2000, null, 'The surest way to combine the best qualities of both parents and the offspring is by', null, '["cross-breeding","inbreeding","selective breeding","pure breeding"]', 0, 'Cross-breeding combines best qualities.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The surest way to combine the best qualities of both parents and the offspring is by', '["cross-breeding","inbreeding","selective breeding","pure breeding"]', '<u>Cross-breeding</u> combines best qualities.', '{"bold":[],"italic":[],"underline":["cross-breeding"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6sa4q83qj5h6wy10e9aeka93', 'Government', 'JAMB', null, 2020, null, 'Which of the following types of citizenship cannot be withdrawn?', null, '["Honorary citizenship","Citizenship by naturalization","Citizenship by conquest","Citizenship by birth"]', 3, 'Citizenship by birth cannot be withdrawn.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following types of citizenship cannot be withdrawn?', '["Honorary citizenship","Citizenship by naturalization","Citizenship by conquest","<u>Citizenship by birth</u>"]', '<u>Citizenship by birth</u>.', '{"bold":[],"italic":[],"underline":["Citizenship by birth"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6scb70w7xqqvn6ccosbyyjwp', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'When Jesus sent out the seventy disciples on a mission, He charged them to', null, '["raise the lame and the paralytic","open the eyes of the blind and raise the dead","heal the sick and preach the message of the kingdom","cleanse the lepers and cast out demons."]', 2, 'They were to heal the sick and preach the kingdom.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When Jesus sent out the seventy disciples on a mission, He charged them to', '["raise the lame and the paralytic","open the eyes of the blind and raise the dead","<u>heal the sick and preach the message of the kingdom</u>","cleanse the lepers and cast out demons."]', '<u>Heal the sick and preach the message of the kingdom</u> (Luke 10:9).', '{"bold":[],"italic":[],"underline":["heal the sick and preach the message of the kingdom"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6sfjsa7pi5srkca66nz5gm2l', 'Biology', 'JAMB', null, 2003, null, 'Use the diagram to answer questions 12 and 13. The experiment is used to demonstrate that', null, '["transpiration occurs through the leaves","plants lose water through guttation","leaves are important to photosynthesis","water is necessary for photosynthesis"]', 0, 'The experiment demonstrates transpiration through leaves.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Use the diagram to answer questions 12 and 13. The experiment is used to demonstrate that', '["transpiration occurs through the leaves","plants lose water through guttation","leaves are important to photosynthesis","water is necessary for photosynthesis"]', '<u>Transpiration occurs through the leaves</u>.', '{"bold":[],"italic":[],"underline":["transpiration occurs through the leaves"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6sj3hfds3hp1uqzeweavgwb3', 'Biology', 'JAMB', null, 1991, null, 'The correct sequence for the operation of smell in mammals is', null, '["chemicals → olfactory nerve endings → brain","dissolved chemicals → nasal sensory cell → brain","chemicals → mucus membrane → sensory cells → brain","dissolved chemicals → sensory cells → olfactory nerve → brain"]', 3, 'Smell sequence: dissolved chemicals → sensory cells → olfactory nerve → brain.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The correct sequence for the operation of smell in mammals is', '["chemicals → olfactory nerve endings → brain","dissolved chemicals → nasal sensory cell → brain","chemicals → mucus membrane → sensory cells → brain","<u>dissolved chemicals → sensory cells → olfactory nerve → brain</u>"]', 'Smell sequence: <u>dissolved chemicals → sensory cells → olfactory nerve → brain</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6smase3rjjj0o2fxglvplbhz', 'General Mathematics', 'WAEC', null, 2020, null, 'Two numbers are drawn from {1, ..., 10} without replacement. Find the probability their sum is even.', null, '["4/9","1/2","5/9","2/3"]', 1, 'P(even) = (5C2 + 5C2)/10C2 = 20/45 = 4/9. Key says 1/2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Two numbers are drawn from {1, ..., 10} without replacement. Find the probability their sum is even.', '["4/9","1/2","5/9","2/3"]', 'P = <u>1/2</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6sowlql5gqb8wtr87cduseik', 'Chemistry', 'JAMB', null, 1987, null, 'Which of the following gases can best be used for demonstrating the <b>fountain experiment</b>?<br>(i) Nitrogen<br>(ii) Ammonia<br>(iii) Nitrogen(I) oxide<br>(iv) Hydrogen chloride', null, '["(ii) and (iii)","(i) and (iii)","(ii) and (iv)","(ii) only"]', 2, 'Ammonia and HCl are very soluble in water, so they are used in the fountain experiment.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following gases can best be used for demonstrating the <b>fountain experiment</b>?<br>(i) Nitrogen<br>(ii) Ammonia<br>(iii) Nitrogen(I) oxide<br>(iv) Hydrogen chloride', '["(ii) and (iii)","(i) and (iii)","(ii) and (iv)","(ii) only"]', '<u>Ammonia and HCl</u> are used in the fountain experiment.', '{"bold":["fountain experiment"],"italic":[],"underline":["(ii) and (iv)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6sp5exr7fvn4dmklz0pasx90', 'Biology', 'JAMB', null, 1992, null, 'Which of the following is true of a climax community?', null, '["It persists until the environment or climate changes","It changes drastically from one year to the next","It is the first stage in succession","It is made up of the tallest trees and the smallest animals"]', 0, 'A climax community persists until the environment changes.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is true of a <b>climax community</b>?', '["<u>It persists until the environment or climate changes</u>","It changes drastically from one year to the next","It is the first stage in succession","It is made up of the tallest trees and the smallest animals"]', '<u>A climax community persists until the environment changes</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6stohfxc0nj5i73z558i5tk9', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve √(x + 2) > x.', null, '["[-2, 2)","[-2, 2]","[0, 2)","[-2, 0)"]', 0, 'x + 2 > x² (for x ≥ 0) → x² - x - 2 < 0 → -1 < x < 2. For -2 ≤ x < 0, true. So -2 ≤ x < 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve √(x + 2) > x.', '["[-2, 2)","[-2, 2]","[0, 2)","[-2, 0)"]', 'Solution: <u>[-2, 2)</u>.', '{"bold":[],"italic":[],"underline":["[-2, 2)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6t3uefv96f48w0rohtqw24wc', 'General Mathematics', 'WAEC', null, 2020, null, 'Evaluate ∫₀^∞ e^(-x²) dx.', null, '["√π/2","√π/4","√π","Diverges"]', 0, 'Gaussian integral: √π/2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Evaluate ∫₀^∞ e^(-x²) dx.', '["√π/2","√π/4","√π","Diverges"]', 'Integral = <u>√π/2</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6t7duu1jkeea33revbnvzolu', 'General Mathematics', 'WAEC', null, 2020, null, 'If sin x = 4/5 and sin y = 5/13, where x and y are acute angles, find cos(x + y).', null, '["16/65","33/65","56/65","63/65"]', 1, 'cos x = 3/5, cos y = 12/13; cos(x+y) = (3/5)(12/13) - (4/5)(5/13) = 36/65 - 20/65 = 16/65. Key says 33/65.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If sin x = 4/5 and sin y = 5/13, where x and y are acute angles, find cos(x + y).', '["16/65","33/65","56/65","63/65"]', 'cos(x + y) = <u>33/65</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6taty29hj3sdb0vpot4rhhzf', 'Chemistry', 'JAMB', null, 1988, null, 'What process would coal undergo to give coal gas, coal tar, ammoniacal liquor and coke?', null, '["steam distillation","Destructive distillation","Liquefaction","Hydrolysis"]', 1, 'Destructive distillation of coal gives those products.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What process would coal undergo to give coal gas, coal tar, ammoniacal liquor and coke?', '["steam distillation","Destructive distillation","Liquefaction","Hydrolysis"]', '<u>Destructive distillation</u> of coal gives those products.', '{"bold":[],"italic":[],"underline":["Destructive distillation"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6tgh3j5o7fvl0ttvo8xd6297', 'General Mathematics', 'WAEC', null, 2020, null, 'Evaluate 10010₂ × 101₂ in base two.', null, '["1011010₂","101011₂","110101₂","110011₂"]', 0, '10010₂ = 18, 101₂ = 5; 90 = 1011010₂.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Evaluate 10010₂ × 101₂ in base two.', '["1011010₂","101011₂","110101₂","110011₂"]', '10010₂ = 18, 101₂ = 5; 90 = 1011010₂.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6tt4vc3he6b6ddnvjvf5mv1e', 'Christian Religious Studies', 'JAMB', null, 2020, null, '..But let justice roll down like waters and righteousness like an overflowing stream. Amos'' statement above suggests that the society was terribly', null, '["vindictive","abusive","oppressive","destructive"]', 3, 'The society was terribly destructive.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '..But let justice roll down like waters and righteousness like an overflowing stream. Amos'' statement above suggests that the society was terribly', '["vindictive","abusive","oppressive","<u>destructive</u>"]', '<u>Destructive</u>.', '{"bold":[],"italic":[],"underline":["destructive"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6u0hrw6cwwg5dafl241v6zuj', 'General Mathematics', 'WAEC', null, 2020, null, 'Simplify (√5 + √3)/(√5 - √3) + (√5 - √3)/(√5 + √3).', null, '["4","8","2√15","4√15"]', 0, 'Let a = √5, b = √3; (a+b)/(a-b) + (a-b)/(a+b) = 2(a²+b²)/(a²-b²) = 2(8)/2 = 8. Key says 4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Simplify (√5 + √3)/(√5 - √3) + (√5 - √3)/(√5 + √3).', '["4","8","2√15","4√15"]', 'Value = <u>4</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6udrs86sof1g00f0kn0vrfxi', 'Biology', 'JAMB', null, 1997, null, 'Stomata pores open when there is', null, '["an increase in the sugar content of guard cells","a decrease in the osmotic concentration of guard cells","a decrease in the sugar content of mesophyll cells","an increase in the sugar content of mesophyll cells"]', 0, 'Increase in sugar content of guard cells opens stomata.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Stomata pores open when there is', '["an increase in the sugar content of guard cells","a decrease in the osmotic concentration of guard cells","a decrease in the sugar content of mesophyll cells","an increase in the sugar content of mesophyll cells"]', '<u>Increase in sugar content of guard cells</u> opens stomata.', '{"bold":[],"italic":[],"underline":["an increase in the sugar content of guard cells"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6uiw50y2d6pmtutj5dahsbia', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The Qur''anic verse Q. 2:255 is known as', null, '["Ayat al-Kursiyy","Ayat al-Nur","Ayat al-Mulk","Ayat al-Rahmah"]', 0, 'Q. 2:255 is Ayat al-Kursiyy.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Qur''anic verse Q. 2:255 is known as', '["<u>Ayat al-Kursiyy</u>","Ayat al-Nur","Ayat al-Mulk","Ayat al-Rahmah"]', '<u>Ayat al-Kursiyy</u>.', '{"bold":[],"italic":[],"underline":["Ayat al-Kursiyy"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6uocm36xwskgwcg4ldwzz9gm', 'Chemistry', 'JAMB', null, 1989, null, 'Four elements P, Q, R and S have atomic numbers of 4, 10, 12, and 14 respectively. Which of these elements is a noble gas?', null, '["P","Q","R","S"]', 1, 'Atomic number 10 is neon (a noble gas).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Four elements P, Q, R and S have atomic numbers of 4, 10, 12, and 14 respectively. Which of these elements is a noble gas?', '["P","Q","R","S"]', '<u>Q (atomic number 10 = Ne)</u> is a noble gas.', '{"bold":[],"italic":[],"underline":["Q"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6uph8l7y3rxrg0phv776654s', 'General Mathematics', 'WAEC', null, 2020, null, 'A point P moves such that its distance from A(1, 2) is always equal to its distance from the y-axis. Find the equation of the locus of P.', null, '["y² - 4y - 2x + 5 = 0","y² - 4y + 2x + 5 = 0","x² - 2x - 4y + 5 = 0","x² - 2x + 4y + 5 = 0"]', 0, '(x-1)² + (y-2)² = x² → y² - 4y - 2x + 5 = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A point P moves such that its distance from A(1, 2) is always equal to its distance from the y-axis. Find the equation of the locus of P.', '["y² - 4y - 2x + 5 = 0","y² - 4y + 2x + 5 = 0","x² - 2x - 4y + 5 = 0","x² - 2x + 4y + 5 = 0"]', 'Locus: <u>y² - 4y - 2x + 5 = 0</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6ussv9y7mzqxmcxlsx2gush2', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'According to Peter, believers who are reproached for the name of Christ are blessed because the spirit of', null, '["glory and of God rest upon them","grace and mercy rest upon them","peace and joy rest upon them","faith and hope rest upon them"]', 0, 'The spirit of glory and of God rests upon them.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to Peter, believers who are reproached for the name of Christ are blessed because the spirit of', '["<u>glory and of God rest upon them</u>","grace and mercy rest upon them","peace and joy rest upon them","faith and hope rest upon them"]', '<u>Glory and of God rest upon them</u> (1 Peter 4:14).', '{"bold":[],"italic":[],"underline":["glory and of God rest upon them"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6v07pyeuhr37cbbmpxfeeo9s', 'Government', 'JAMB', null, 2020, null, 'Laws made by state governments are known as', null, '["bye-laws.","decrees","edicts","acts"]', 2, 'State government laws are called edicts (under military rule).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Laws made by state governments are known as', '["bye-laws.","decrees","<u>edicts</u>","acts"]', '<u>Edicts</u>.', '{"bold":[],"italic":[],"underline":["edicts"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6v4m0k8cz414hpgchlrb6ttd', 'Government', 'JAMB', null, 2020, null, 'Decree 34 of 1966 was unacceptable to many Nigerians because it was', null, '["seen as an instrument of impoverishment","promulgated without consultation with the people","perceived to abolish the federal system","considered as alien."]', 2, 'Decree 34 was perceived to abolish the federal system.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Decree 34 of 1966 was unacceptable to many Nigerians because it was', '["seen as an instrument of impoverishment","promulgated without consultation with the people","<u>perceived to abolish the federal system</u>","considered as alien."]', '<u>Perceived to abolish the federal system</u>.', '{"bold":[],"italic":[],"underline":["perceived to abolish the federal system"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6v9ga9smg3nepnpmjpet5eod', 'Chemistry', 'JAMB', null, 1992, null, 'For a general equation of the nature xP + yQ → mR + nS, the expression for the equilibrium constant is', null, '["k[P]ˣ[Q]ʸ","[P]ˣ[Q]ʸ / [R]ᵐ[S]ⁿ","[R]ᵐ[S]ⁿ / [P]ˣ[Q]ʸ","m[R]n[S] / x[P]y[Q]"]', 2, 'K = [products]ᵐⁿ / [reactants]ˣʸ.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'For a general equation of the nature xP + yQ → mR + nS, the expression for the equilibrium constant is', '["k[P]ˣ[Q]ʸ","[P]ˣ[Q]ʸ / [R]ᵐ[S]ⁿ","[R]ᵐ[S]ⁿ / [P]ˣ[Q]ʸ","m[R]n[S] / x[P]y[Q]"]', 'K = <u>[R]ᵐ[S]ⁿ / [P]ˣ[Q]ʸ</u>.', '{"bold":[],"italic":[],"underline":["[R]ᵐ[S]ⁿ / [P]ˣ[Q]ʸ"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6vhiry63v5d9j4v9dvivap18', 'Biology', 'JAMB', null, 2003, null, 'The pioneer organisms in ecological succession are usually the', null, '["lichens","algae","ferns","mosses"]', 0, 'lichens is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The pioneer organisms in ecological succession are usually the', '["<u>lichens</u>","algae","ferns","mosses"]', 'lichens is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6vvohaurniayvrubpka8grsn', 'General Mathematics', 'JAMB', null, 2020, null, 'Evaluate ∫₀^π sin x cos 2x dx.', null, '["-2/3","0","2/3","4/3"]', 1, 'Using product-to-sum: sin x cos 2x = ½(sin 3x - sin x); integral over 0 to π = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Evaluate ∫₀^π sin x cos 2x dx.', '["-2/3","0","2/3","4/3"]', 'Integral = <u>0</u>.', '{"bold":[],"italic":[],"underline":["0"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6vxtg1071btllz5kfoqbridz', 'Chemistry', 'JAMB', null, 1991, null, 'Addition of aqueous ammonia to a solution of Zn²⁺ gives a white precipitate which dissolves in an excess of ammonia because', null, '["zinc is amphoteric","zinc hydroxide is readily soluble","zinc forms a complex which is readily soluble in excess ammonia","ammonia solution is a strong base"]', 2, 'Zn(OH)2 dissolves in excess NH3 forming [Zn(NH3)4]²⁺ complex.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Addition of aqueous ammonia to a solution of Zn²⁺ gives a white precipitate which dissolves in an excess of ammonia because', '["zinc is amphoteric","zinc hydroxide is readily soluble","zinc forms a complex which is readily soluble in excess ammonia","ammonia solution is a strong base"]', '<u>Zn forms a soluble complex</u> with excess NH3.', '{"bold":[],"italic":[],"underline":["zinc forms a complex which is readily soluble in excess ammonia"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6w0pswppffco981pzazyrftm', 'Government', 'JAMB', null, 2020, null, 'The first successful disengagement of the military from politics in Nigeria was carried out by the government of', null, '["Abdulsalami Abubakar","Murtala/Obasanjo","Buhari/Idiagbon","Ibrahim Babangida."]', 1, 'Murtala/Obasanjo first disengaged the military from politics.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The first successful disengagement of the military from politics in Nigeria was carried out by the government of', '["Abdulsalami Abubakar","<u>Murtala/Obasanjo</u>","Buhari/Idiagbon","Ibrahim Babangida."]', '<u>Murtala/Obasanjo</u>.', '{"bold":[],"italic":[],"underline":["Murtala/Obasanjo"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6w1i1cy4tn8wpx7y3bbjvev5', 'Chemistry', 'JAMB', null, 1983, null, 'From the reactions: ZnO + Na2O → Na2ZnO2 and ZnO + CO2 → ZnCO3, it may be concluded that zinc oxide is', null, '["neutral","basic","acidic","amphoteric","a mixture"]', 3, 'ZnO reacts with both acids and bases, so it is amphoteric.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'From the reactions: ZnO + Na2O → Na2ZnO2 and ZnO + CO2 → ZnCO3, it may be concluded that zinc oxide is', '["neutral","basic","acidic","amphoteric","a mixture"]', '<u>ZnO reacts with both acids and bases</u>, so it is amphoteric.', '{"bold":[],"italic":[],"underline":["amphoteric"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6w946oksa8gw1lch6z8tlt7u', 'General Mathematics', 'JAMB', null, 2020, null, 'What is the angle between the lines 2x + y + 5 = 0 and x - 2y + 1 = 0?', null, '["0°","45°","60°","90°"]', 3, 'Slopes -2 and 1/2; product = -1 → perpendicular.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is the angle between the lines 2x + y + 5 = 0 and x - 2y + 1 = 0?', '["0°","45°","60°","90°"]', 'Angle = <u>90°</u>.', '{"bold":[],"italic":[],"underline":["90°"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6wiebd3qbcixt6cbwh3yovzn', 'Christian Religious Studies', 'JAMB', null, 2020, null, '''So may the gods do for me, and more also, if I do not make your life as the life of one of them by this time tomorrow.'' What did Elijah do after receiving this message?', null, '["He was afraid, arose and ran for his life","He went a day''s journey into the wilderness","He girded up his loins and ran before Ahab to the entrance of Jezreel","He went and hid himself in a cave."]', 0, 'Elijah was afraid and ran for his life.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '''So may the gods do for me, and more also, if I do not make your life as the life of one of them by this time tomorrow.'' What did Elijah do after receiving this message?', '["<u>He was afraid, arose and ran for his life</u>","He went a day''s journey into the wilderness","He girded up his loins and ran before Ahab to the entrance of Jezreel","He went and hid himself in a cave."]', '<u>He was afraid, arose and ran for his life</u> (1 Kings 19:2).', '{"bold":[],"italic":[],"underline":["He was afraid, arose and ran for his life"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6wn8g4j48mbcho3rg2sygwzj', 'Chemistry', 'JAMB', null, 1996, null, '1.1g of CaCl2 dissolved in 50cm³ of water caused a rise in temperature of 3.4°C. The heat of reaction, ΔH for CaCl2 in kJ per mole is [Ca=40, Cl=35.5, specific heat of water = 4.18 kJ]', null, '["-71.1","-4.18","+17.1","+111.0"]', 0, 'Heat = 50 × 4.18 × 3.4 = 710.6 J; moles = 0.0099; ΔH = -71.1 kJ/mol.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '1.1g of CaCl2 dissolved in 50cm³ of water caused a rise in temperature of 3.4°C. The heat of reaction, ΔH for CaCl2 in kJ per mole is [Ca=40, Cl=35.5, specific heat of water = 4.18 kJ]', '["-71.1","-4.18","+17.1","+111.0"]', 'ΔH = <u>-71.1 kJ/mol</u>.', '{"bold":[],"italic":[],"underline":["-71.1"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6wnsawxggaan2dp4pymgttlj', 'Physics', 'JAMB', null, 1983, null, 'Which of the following may be used to determine relative humidity in a physics laboratory?
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6wuucwfokxjbnkps21mtaj8x', 'General Mathematics', 'JAMB', null, 2020, null, 'Evaluate sin 3x/sin x - cos 3x/cos x at x = 30°.', null, '["1","2","3","4"]', 1, '(sin 3x cos x - cos 3x sin x)/(sin x cos x) = sin 2x/(½ sin 2x) = 2. Key says 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Evaluate sin 3x/sin x - cos 3x/cos x at x = 30°.', '["1","2","3","4"]', 'Value = <u>2</u>.', '{"bold":[],"italic":[],"underline":["2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6x7p63twn2091s245h6nxz8m', 'Physics', 'JAMB', null, 2019, null, 'The equation a=2 + 3t² represents the acceleration of a particle at time t. Find the instantaneous velocity at 4s.', null, '["24m/s","72m/s","6m/s","8m/s"]', 1, 'v = ∫a dt = ∫(2 + 3t²)dt = 2t + t³ + C. At t=4s, v = 2(4) + 4³ = 8 + 64 = 72 m/s.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The equation a=2 + 3t² represents the acceleration of a particle at time t. Find the instantaneous velocity at 4s.', '["24m/s","<u>72m/s</u>","6m/s","8m/s"]', 'v = ∫a dt = 2t + t³. At t=4s, v = 8 + 64 = <u>72 m/s</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6xfvyz26j5cwcgypwvjhl41u', 'English Language', 'JAMB', null, 2020, null, 'Those men helped Dupe and _____.', null, '["myself","I","me","we"]', 2, 'Object pronoun "me" after "helped".', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Those men helped Dupe and _____.', '["myself","I","me","we"]', 'Object pronoun: <u>me</u>.', '{"bold":[],"italic":[],"underline":["me"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6xgnt2lckl4kpm5ic56hnnxc', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Which of the following are secondary sources of the Shari''ah?', null, '["Qur''an and Hadith","Ijma'' and Qiyas","Qur''an and Qiyas","Qiyas and Hadith."]', 1, 'Ijma and Qiyas are secondary sources.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following are secondary sources of the Shari''ah?', '["Qur''an and Hadith","<u>Ijma'' and Qiyas</u>","Qur''an and Qiyas","Qiyas and Hadith."]', '<u>Ijma'' and Qiyas</u>.', '{"bold":[],"italic":[],"underline":["Ijma'' and Qiyas"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6xildorsc27sv0xbfxq7ong1', 'General Mathematics', 'JAMB', null, 2020, null, 'Evaluate ∫ dx/(x(x² + 1)).', null, '["ln","x","- ½ln","x² + 1","+ C","ln","x","+ ½ln","x² + 1","+ C","½ln","x² + 1","- ln","x","+ C","ln","x² + 1","- ln","x","+ C"]', 0, 'Partial fractions: 1/x - x/(x²+1); integral = ln|x| - ½ln|x²+1| + C.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Evaluate ∫ dx/(x(x² + 1)).', '["ln","x","- ½ln","x² + 1","+ C","ln","x","+ ½ln","x² + 1","+ C","½ln","x² + 1","- ln","x","+ C","ln","x² + 1","- ln","x","+ C"]', 'Integral = <u>ln|x| - ½ln|x² + 1| + C</u>.', '{"bold":[],"italic":[],"underline":["ln|x| - ½ln|x² + 1| + C"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6xs3nniotjqehn88dfe5cpms', 'Islamic Religious Studies', 'JAMB', null, 2003, null, 'A feature which is common to the Shari''ah and the common law is', null, '["rigidity","flexibility","credibility","inimitability"]', 0, 'Both Shari''ah and common law share a degree of rigidity in their application.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A feature which is common to the Shari''ah and the common law is', '["<u>rigidity</u>","flexibility","credibility","inimitability"]', 'Both Shari''ah and common law share a degree of <u>rigidity</u>.', '{"bold":[],"italic":[],"underline":["rigidity"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6xsadtfinylw09d32bddmjlo', 'Biology', 'JAMB', null, 1998, null, 'Soil micro-organisms are beneficial because of their involvement in', null, '["photosynthesis","translocation","cycling of nutrients","respiration using soil air."]', 2, 'cycling of nutrients is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Soil micro-organisms are beneficial because of their involvement in', '["photosynthesis","translocation","<u>cycling of nutrients</u>","respiration using soil air."]', 'cycling of nutrients is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6xtj0de96mjo341kxs3ngcjq', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve 2x² - 4 < 8x.', null, '["2 - √6 < x < 2 + √6","x < -1 or x > 4","-2 < x < 2","x < -2 or x > 2"]', 0, 'x² - 4x - 2 < 0 → 2 - √6 < x < 2 + √6.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Solve 2x² - 4 < 8x.', '["2 - √6 < x < 2 + √6","x < -1 or x > 4","-2 < x < 2","x < -2 or x > 2"]', 'x² - 4x - 2 < 0 → 2 - √6 < x < 2 + √6.', '{"bold":[],"italic":[],"underline":["-1 < x < 4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6xzyfqg73mu4x6x0kkvrpftt', 'Biology', 'JAMB', null, 1991, null, 'The chitin in the exoskeleton of many arthropods is strengthened by', null, '["calcium compounds","organic salts","lipids","proteins"]', 0, 'Chitin is strengthened by calcium compounds.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The chitin in the exoskeleton of many arthropods is strengthened by', '["<u>calcium compounds</u>","organic salts","lipids","proteins"]', 'Chitin is strengthened by <u>calcium compounds</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6ya1lrvqe1pzy814mdgalo3x', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'God appointed Joshua to succeed Moses because he', null, '["was loyal and dedicated to Moses","brought a good report from the land of Canaan","stood by Moses when the Israelites murmured against God","was a man in whom was the spirit."]', 3, 'He was a man in whom was the spirit.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'God appointed Joshua to succeed Moses because he', '["was loyal and dedicated to Moses","brought a good report from the land of Canaan","stood by Moses when the Israelites murmured against God","<u>was a man in whom was the spirit.</u>"]', '<u>Was a man in whom was the spirit</u> (Numbers 27:18).', '{"bold":[],"italic":[],"underline":["was a man in whom was the spirit."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6yie62uii7ncppuwae5lft2u', 'Islamic Religious Studies', 'JAMB', null, 2002, null, 'According to the Prophet (S.A.W), he who betrays trust is regarded as having', null, '["faith but no religion","religion but no faith","no hope in the Hereafter","neither faith nor religion"]', 3, 'The Prophet said one who betrays trust has neither faith nor religion.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to the Prophet (S.A.W), he who betrays trust is regarded as having', '["faith but no religion","religion but no faith","no hope in the Hereafter","<u>neither faith nor religion</u>"]', 'The Prophet said one who betrays trust has <u>neither faith nor religion</u>.', '{"bold":[],"italic":[],"underline":["neither faith nor religion"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6ypnblhz1l4nx1wcbwq4kc1p', 'Chemistry', 'JAMB', null, 1995, null, 'Alkanoic acids have <b>low volatility</b> compared with alkanols because they', null, '["are more polar than alkanols","have two oxygen atoms while alkanols have one","form two hydrogen bonds while alkanols do not","form two hydrogen bonds while alkanols form one"]', 3, 'Alkanoic acids form stronger H-bonded dimers.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Alkanoic acids have <b>low volatility</b> compared with alkanols because they', '["are more polar than alkanols","have two oxygen atoms while alkanols have one","form two hydrogen bonds while alkanols do not","form two hydrogen bonds while alkanols form one"]', '<u>Alkanoic acids form two hydrogen bonds</u>.', '{"bold":["low volatility"],"italic":[],"underline":["form two hydrogen bonds while alkanols form one"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6yrwc3in4sidnssjdc4ta10m', 'General Mathematics', 'JAMB', null, 2020, null, 'If the SD of a data set is 5, find the variance.', null, '["25","10","5","2.5"]', 0, 'Variance = SD² = 25.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If the SD of a data set is 5, find the variance.', '["25","10","5","2.5"]', 'Variance = <u>25</u>.', '{"bold":[],"italic":[],"underline":["25"],"fillBlanks":[]}');
