insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6zb1gshjio8e38fyncm29ctm', 'General Mathematics', 'JAMB', null, 2020, null, 'If y = √(x + √(x + √(x + ...))), find dy/dx.', null, '["1/(2y-1)","1/(2y+1)","y/(2y-1)","y/(2y+1)"]', 0, 'y² = x + y → 2y dy/dx = 1 + dy/dx → dy/dx = 1/(2y-1).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If y = √(x + √(x + √(x + ...))), find dy/dx.', '["1/(2y-1)","1/(2y+1)","y/(2y-1)","y/(2y+1)"]', 'dy/dx = <u>1/(2y-1)</u>.', '{"bold":[],"italic":[],"underline":["1/(2y-1)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6zfw714vhojt5g9h97btpuci', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the geometric mean of 4 and 16.', null, '["8","10","12","14"]', 0, 'GM = √(4×16) = 8.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the geometric mean of 4 and 16.', '["8","10","12","14"]', 'GM = <u>8</u>.', '{"bold":[],"italic":[],"underline":["8"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6zodvu9cmfme1r9elszkc7ws', 'Chemistry', 'JAMB', null, 1991, null, 'One of the advantages of detergents over soap is that detergents', null, '["are easier to manufacture","foam more than soap","form soluble salts with hard water","are able to deter germs more than soap"]', 2, 'Detergents form soluble salts with hard water (no scum).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One of the advantages of detergents over soap is that detergents', '["are easier to manufacture","foam more than soap","form soluble salts with hard water","are able to deter germs more than soap"]', '<u>Detergents form soluble salts with hard water</u>.', '{"bold":[],"italic":[],"underline":["form soluble salts with hard water"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c6zq9uflu1rrhkr2t3ndu1is7', 'Government', 'JAMB', null, 2020, null, 'The standing committee of a legislature is one', null, '["whose members stand while deliberating","that has statutory responsibilities","that performs ad hoc function","that has all legislators as members."]', 1, 'Standing committees are permanent committees with statutory responsibilities, unlike ad hoc committees.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The standing committee of a legislature is one', '["whose members stand while deliberating","<u>that has statutory responsibilities</u>","that performs ad hoc function","that has all legislators as members."]', 'Standing committees have <u>statutory responsibilities</u>.', '{"bold":[],"italic":[],"underline":["that has statutory responsibilities"],"fillBlanks":[]}');
