insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c701x0ofy8199cbeu0naj8rjh', 'Chemistry', 'JAMB', null, 1999, null, 'A metal that can be extracted from <b>cassiterite</b> is', null, '["calcium","magnesium","tin","copper"]', 2, 'Cassiterite (SnO2) is a tin ore.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A metal that can be extracted from <b>cassiterite</b> is', '["calcium","magnesium","tin","copper"]', '<u>Tin</u> is extracted from cassiterite.', '{"bold":["cassiterite"],"italic":[],"underline":["tin"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c70703a6-0a78-46b6-a590-abb42e6f6698', 'English Language', 'JAMB', null, 2007, null, 'We did not understand what the magistrate said about <u>__________</u>', null, '["acid","insult","assault","touching and battery"]', 2, 'Correct form: assault and battery.', true, '2026-10-24 07:21:38.696', '2026-10-24 07:21:38.696', null, null, null, 'We did not understand what the magistrate said about <u>__________</u>', '["acid","insult","assault","touching and battery"]', 'Correct form: assault and battery.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c70e3548-4fe5-47cb-b9c0-dabe4f64b40b', 'Hausa', 'JAMB', null, 2010, null, 'Yadda ake samun tatsuniya a bakunan tsofaffi, haka ake samun kissa a bakunan malaman', null, '["fikihu","tsibbu","tarihi","hisabi."]', 2, 'Ake samun kissa a bakunan malaman tarihi.', true, '2026-10-13 10:37:24.623', '2026-10-13 10:37:24.623', null, null, null, 'Yadda ake samun tatsuniya a bakunan tsofaffi, haka ake samun kissa a bakunan malaman', '["fikihu","tsibbu","tarihi","hisabi."]', 'Ake samun kissa a bakunan malaman tarihi.', '{"bold":["tarihi"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c70i2zufndodmqs5f01q7a9xb', 'Government', 'JAMB', null, 2020, null, 'Nigeria''s high standing in the UN General Assembly is underscored by her', null, '["military strength","successes in UN elective offices","contribution to global peace","financial contributions"]', 2, 'Nigeria''s UN standing stems from contribution to global peace.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Nigeria''s high standing in the UN General Assembly is underscored by her', '["military strength","successes in UN elective offices","<u>contribution to global peace</u>","financial contributions"]', '<u>Contribution to global peace</u>.', '{"bold":[],"italic":[],"underline":["contribution to global peace"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c70z9hms0jow2tkvjw87rhskh', 'Chemistry', 'JAMB', null, 1999, null, 'Chlorine, bromine and iodine resemble one another in that they', null, '["dissolve in alkalis","react violently with hydrogen without heating","are liquids","displace one another from solutions of their salts"]', 3, 'Halogens displace one another from salt solutions.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Chlorine, bromine and iodine resemble one another in that they', '["dissolve in alkalis","react violently with hydrogen without heating","are liquids","displace one another from solutions of their salts"]', '<u>Halogens displace one another</u>.', '{"bold":[],"italic":[],"underline":["displace one another from solutions of their salts"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c712ex2ty2kn1yh17j5o9cuez', 'Chemistry', 'JAMB', null, 2004, null, 'Sodium metal is always kept under oil because it', null, '["is reduced by atmospheric nitrogen","readily reacts with water","reacts with oxygen and carbon(IV) oxide","reacts vigorously on exposure to air"]', 1, 'Na reacts vigorously with water/moisture.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Sodium metal is always kept under oil because it', '["is reduced by atmospheric nitrogen","readily reacts with water","reacts with oxygen and carbon(IV) oxide","reacts vigorously on exposure to air"]', '<u>Readily reacts with water</u>.', '{"bold":[],"italic":[],"underline":["readily reacts with water"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c712y6i4bumm4fbo8dt4fz5r0', 'Chemistry', 'JAMB', null, 1987, null, 'A stream of air was successively passed through three tubes X, Y, and Z containing a concentrated aqueous solution of KOH, red hot copper powder and fused calcium chloride respectively. What was the composition of gas emanating from tube Z?', null, '["CO2 and the inert gases","N2, CO2 and the inert gases","N2 and the inert gases","Water vapour, N2 and the inert gases"]', 2, 'KOH removes CO2; hot Cu removes O2; CaCl2 removes water; N2 and inert gases remain.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A stream of air was successively passed through three tubes X, Y, and Z containing a concentrated aqueous solution of KOH, red hot copper powder and fused calcium chloride respectively. What was the composition of gas emanating from tube Z?', '["CO2 and the inert gases","N2, CO2 and the inert gases","N2 and the inert gases","Water vapour, N2 and the inert gases"]', '<u>N2 and the inert gases</u> remain.', '{"bold":[],"italic":[],"underline":["N2 and the inert gases"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c714ycbw73p2p8wear69hv185', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve for y: 43_y = 21_(y+2).', null, '["5","6","7","8"]', 0, '4y + 3 = 2(y+2) + 1 = 2y + 5 → 2y = 2 → y = 1. But y > 4. No solution. Key says 5.', false, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Solve for y: 43_y = 21_(y+2).', '["5","6","7","8"]', '4y + 3 = 2y + 5 → <u>y = 1</u> (invalid, key says 5).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c71966w8x2an7c0mc0n9kkbad', 'Biology', 'JAMB', null, 1984, null, 'Mosses, liverworts and ferns can be grouped together because they', null, '["are all equatic plants","all grown in deserts","are seedless plants","have undifferentiated plant bodies","all produce colourless flowers"]', 2, 'Mosses, liverworts, and ferns are all seedless plants.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Mosses, liverworts and ferns can be grouped together because they', '["are all equatic plants","all grown in deserts","<u>are seedless plants</u>","have undifferentiated plant bodies","all produce colourless flowers"]', 'Mosses, liverworts, and ferns are all <u>seedless plants</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c719o1mormouxho162wzh1vz5', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the derivative of y = x ln x.', null, '["1","ln x","1 + ln x","x + ln x"]', 2, 'dy/dx = ln x + 1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the derivative of y = x ln x.', '["1","ln x","1 + ln x","x + ln x"]', 'dy/dx = <u>1 + ln x</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c719wkscdm49zphpucdtou5uc', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'A Hadith with uninterrupted chain of authorities traced back to the Prophet Muhammad (S.A.W) himself is described as', null, '["Mutawaitir","Mawquf","Maqtul","Muttasil-marfu"]', 0, 'It is Mutawaitir.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A Hadith with uninterrupted chain of authorities traced back to the Prophet Muhammad (S.A.W) himself is described as', '["<u>Mutawaitir</u>","Mawquf","Maqtul","Muttasil-marfu"]', '<u>Mutawaitir</u>.', '{"bold":[],"italic":[],"underline":["Mutawaitir"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c71l41ps1ce8ghypykqfm2yc4', 'Chemistry', 'JAMB', null, 2004, null, 'Carbon is <b>tetravalent</b> because', null, '["the 2s and 2p atomic orbitals hybridize","all the atomic orbitals of carbon hybridize","the electrons in all the orbitals of carbon are equivalent","the electrons in both the 2s and 2p orbitals are equivalent"]', 0, 'sp³ hybridization makes carbon tetravalent.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Carbon is <b>tetravalent</b> because', '["the 2s and 2p atomic orbitals hybridize","all the atomic orbitals of carbon hybridize","the electrons in all the orbitals of carbon are equivalent","the electrons in both the 2s and 2p orbitals are equivalent"]', '<u>2s and 2p orbitals hybridize</u> (sp³).', '{"bold":["tetravalent"],"italic":[],"underline":["the 2s and 2p atomic orbitals hybridize"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c71lkautyqcdn6ow5d6uo9ek0', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'It is necessary to circumcise them, and to charge them to keep the law of Moses. In response to the Pharisees'' statement above, Peter rebuked them by saying that God has', null, '["cleansed the Gentiles'' heart by faith","put the yoke upon the Gentiles'' neck","made circumcision for only those in leadership","chosen the Israelites among other people."]', 0, 'God cleansed the Gentiles'' heart by faith.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'It is necessary to circumcise them, and to charge them to keep the law of Moses. In response to the Pharisees'' statement above, Peter rebuked them by saying that God has', '["<u>cleansed the Gentiles'' heart by faith</u>","put the yoke upon the Gentiles'' neck","made circumcision for only those in leadership","chosen the Israelites among other people."]', '<u>Cleansed the Gentiles'' heart by faith</u> (Acts 15:9).', '{"bold":[],"italic":[],"underline":["cleansed the Gentiles'' heart by faith"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7208yjm8wacf9oc4dhj08bws', 'Government', 'JAMB', null, 2020, null, 'Legislative control of public corporations in Nigeria is effected through', null, '["acts of the National Assembly","bye-laws","the dissolution of their management","the reorganization of their boards"]', 0, 'Legislative control is through acts of the National Assembly.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Legislative control of public corporations in Nigeria is effected through', '["<u>acts of the National Assembly</u>","bye-laws","the dissolution of their management","the reorganization of their boards"]', '<u>Acts of the National Assembly</u>.', '{"bold":[],"italic":[],"underline":["acts of the National Assembly"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c725530c-63ed-4c8b-9c06-7e0acb659784', 'Physics', 'JAMB', null, 1988, null, 'Which of the following statements is TRUE of ultra-violet, visible and infra-red rays?', null, '["They are all electromagnetic waves with the same wavelength.","Ultra-violet rays have shorter wavelength than infra-red rays and produce fluorescence.","Infra-red rays have shorter wavelength than visible light and produce the sensation of heat.","The wavelengths increase in the sequence: visible, ultra-violet, infra-red."]', 1, 'Ultraviolet has a shorter wavelength than infra-red and makes some substances fluoresce. Infra-red is longer than visible, and the order of increasing wavelength is ultraviolet, visible, infra-red.', true, '2026-10-12 19:15:28.065', '2026-10-12 19:15:28.065', null, null, null, 'Which of the following statements is <b>TRUE</b> of ultra-violet, visible and infra-red rays?', '["They are all electromagnetic waves with the same wavelength.","Ultra-violet rays have shorter wavelength than infra-red rays and produce fluorescence.","Infra-red rays have shorter wavelength than visible light and produce the sensation of heat.","The wavelengths increase in the sequence: visible, ultra-violet, infra-red."]', 'Ultraviolet has a shorter wavelength than infra-red and makes some substances fluoresce. Infra-red is longer than visible, and the order of increasing wavelength is ultraviolet, visible, infra-red.', '{"bold":["TRUE"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c726dsrwgh3jjs8dleaik9gc5', 'Chemistry', 'JAMB', null, 2024, null, 'Mg+2HCl → MgCl2+ H2. What is the mass of magnesium that will react with 250cm3 of 0.5M HCl (Mg=24, Cl=35.5)', null, '["3","7.5","1.5","7.1"]', 2, 'Moles HCl = 0.25 × 0.5 = 0.125 mol. Moles Mg = 0.125/2 = 0.0625 mol. Mass = 0.0625 × 24 = 1.5 g.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Mg + 2HCl → MgCl2 + H2. What is the mass of magnesium that will react with 250cm3 of 0.5M HCl (Mg=24, Cl=35.5)', '["3","7.5","<u>1.5</u>","7.1"]', 'Moles HCl = 0.125 mol. Moles Mg = 0.0625 mol. Mass = 0.0625 × 24 = <u>1.5 g</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c726utk1kzz71hlbze8vntoib', 'General Mathematics', 'JAMB', null, 2020, null, 'If a, b, c are in GP, then 1/(a-b) + 1/(b-c) = ?', null, '["1/a","1/b","1/c","0"]', 1, 'Let b² = ac; 1/(a-b) + 1/(b-c) = (b-c+a-b)/((a-b)(b-c)) = (a-c)/((a-b)(b-c)); simplify → 1/b.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If a, b, c are in GP, then 1/(a-b) + 1/(b-c) = ?', '["1/a","1/b","1/c","0"]', 'Value = <u>1/b</u>.', '{"bold":[],"italic":[],"underline":["1/b"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c729o8tte5ngffn2glwth01dj', 'General Mathematics', 'WAEC', null, 2020, null, 'For A = [[1, 1], [0, 1]], find Aⁿ.', null, '["[[1, n], [0, 1]]","[[1, 0], [0, 1]]","[[n, 1], [0, 1]]","[[1, 0], [0, 1]]"]', 0, 'By induction, Aⁿ = [[1, n], [0, 1]].', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'For A = [[1, 1], [0, 1]], find Aⁿ.', '["[[1, n], [0, 1]]","[[1, 0], [0, 1]]","[[n, 1], [0, 1]]","[[1, 0], [0, 1]]"]', 'Aⁿ = <u>[[1, n], [0, 1]]</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c72a3ttnzpv1opu4sd2ohyojn', 'Chemistry', 'JAMB', null, 1995, null, '10.0dm³ of air containing H2S as an impurity was passed through a solution of Pb(NO3)2 until all the H2S had reacted. The precipitate of PbS was found to weigh 5.02g. According to the equation: Pb(NO3)2 + H2S → PbS + 2HNO3, the percentage by volume of hydrogen sulphide in the air is [Pb=207, S=32, G.M.V at s.t.p = 22.4 dm³]', null, '["50.2","47.0","4.70","0.47"]', 2, 'Moles PbS = 5.02/239 = 0.021; volume H2S = 0.021 × 22.4 = 0.47 dm³; % = 4.7%.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '10.0dm³ of air containing H2S as an impurity was passed through a solution of Pb(NO3)2 until all the H2S had reacted. The precipitate of PbS was found to weigh 5.02g. According to the equation: Pb(NO3)2 + H2S → PbS + 2HNO3, the percentage by volume of hydrogen sulphide in the air is [Pb=207, S=32, G.M.V at s.t.p = 22.4 dm³]', '["50.2","47.0","4.70","0.47"]', '% H2S = <u>4.70%</u>.', '{"bold":[],"italic":[],"underline":["4.70"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c72h486s2k0eg8dp1hgjs99mn', 'Biology', 'JAMB', null, 1993, null, 'The butterfly is of great economic importance because', null, '["of its use in scientific studies","it sucks nectar from flowers","it adds to the beauty of the environment","it pollinates flower of crops and other plants"]', 3, 'Butterflies pollinate crops and plants.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The butterfly is of great economic importance because', '["of its use in scientific studies","it sucks nectar from flowers","it adds to the beauty of the environment","<u>it pollinates flower of crops and other plants</u>"]', '<u>Butterflies pollinate crops and plants</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c72j5y6zbbicdi7yjp39q0b93', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve the equation 2^(2x) - 5·2^x + 4 = 0', null, '["0","1","0","0, 2"]', 3, 'Let y = 2^x: y² - 5y + 4 = 0 → y = 1 or 4 → x = 0 or 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Solve the equation 2^(2x) - 5·2^x + 4 = 0', '["0","1","0","0, 2"]', 'Let y = 2^x: y² - 5y + 4 = 0 → y = 1 or 4 → x = 0 or 2.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c72n0hx09abnookspatu019kf', 'Chemistry', 'JAMB', null, 1996, null, 'MnO4⁻ + 8H⁺ + ne⁻ → M²⁺ + 4H2O. Which is the value of n in the reaction above?', null, '["2","3","4","5"]', 3, 'Mn goes from +7 to +2, gaining 5 electrons.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'MnO4⁻ + 8H⁺ + ne⁻ → M²⁺ + 4H2O. Which is the value of n in the reaction above?', '["2","3","4","5"]', 'Mn gains <u>5 electrons</u>.', '{"bold":[],"italic":[],"underline":["5"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c72rtmt7esuebkl8oxozovrv0', 'Chemistry', 'JAMB', null, 1986, null, 'An element with atomic number twelve is likely to be', null, '["electrovalent with a valency of 1","electrovalent with a valency of 2","covalent with a valency of 2","covalent with a valency of 4"]', 1, 'Mg (atomic number 12) is electrovalent with valency 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An element with atomic number twelve is likely to be', '["electrovalent with a valency of 1","electrovalent with a valency of 2","covalent with a valency of 2","covalent with a valency of 4"]', '<u>Mg is electrovalent with valency 2</u>.', '{"bold":[],"italic":[],"underline":["electrovalent with a valency of 2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c72udeor9om1vpu79rfaz2urk', 'English Language', 'JAMB', null, 2020, null, 'You think she hasn''t got any friend? Of course, she''s got _____.', null, '["many more","quite much","quite a few","few"]', 2, 'Quite a few = a considerable number. Correct with plural count nouns.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'You think she hasn''t got any friend? Of course, she''s got _____.', '["many more","quite much","quite a few","few"]', '<u>Quite a few</u> = a considerable number.', '{"bold":[],"italic":[],"underline":["quite a few"],"fillBlanks":[]}');
