insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c73q9qh5ku2enkg201lxspeek', 'English Language', 'JAMB', null, 2020, null, 'No wonder those plants are dying. They _____ any water for ages.', null, '["didn''t have","hadn''t","haven''t had","haven''t"]', 2, 'For ages → present perfect "haven''t had".', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'No wonder those plants are dying. They _____ any water for ages.', '["didn''t have","hadn''t","haven''t had","haven''t"]', 'For ages → <u>haven''t had</u>.', '{"bold":[],"italic":[],"underline":["haven''t had"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7405534-ce9f-438d-ae90-41cfa8aab2f5', 'Biology', 'JAMB', null, 2005, null, 'Angiosperms and gymnosperms belong to the class', null, '["schizophyta","spermatophyte","pteridophyta","bryophyta"]', 1, 'Both angiosperms and gymnosperms produce seeds, classifying them as spermatophytes.', true, '2026-10-12 20:05:11.807', '2026-10-12 20:05:11.807', null, null, null, 'Angiosperms and gymnosperms belong to the class', '["schizophyta","spermatophyte","pteridophyta","bryophyta"]', 'Both angiosperms and gymnosperms produce seeds, classifying them as spermatophytes.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c741be6rzchiqia5a9ogmen7w', 'Government', 'JAMB', null, 2020, null, 'With the admission of Asian and African Countries to the Commonwealth, the Queen of England became the', null, '["patron of the Commonwealth","head of state of these countries","chairperson of the Commonwealth","head of government of these countries"]', 0, 'The Queen became the patron of the Commonwealth.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'With the admission of Asian and African Countries to the Commonwealth, the Queen of England became the', '["<u>patron of the Commonwealth</u>","head of state of these countries","chairperson of the Commonwealth","head of government of these countries"]', '<u>Patron of the Commonwealth</u>.', '{"bold":[],"italic":[],"underline":["patron of the Commonwealth"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c746a2e2-2380-4681-b54c-b4ae89301369', 'General Mathematics', 'JAMB', null, 2026, null, 'If y varies directly as the square root of x and y = 3 when x = 16. Calculate y when x = 64', null, '["12","3","5","6"]', 3, 'y = k√x. 3 = k(4). k = 3/4. y = (3/4)(8) = 6.', true, '2026-09-12 11:44:18.117', '2026-09-12 11:44:18.117', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c74qlhe6174jmp5uyq4tf183k', 'General Mathematics', 'JAMB', null, 2020, null, 'Find p if one root of x² - 6x + p = 0 is double the other.', null, '["6","8","9","12"]', 1, 'Roots α, 2α; 3α = 6 → α = 2; p = 2×4 = 8.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find p if one root of x² - 6x + p = 0 is double the other.', '["6","8","9","12"]', '<u>p = 8</u>.', '{"bold":[],"italic":[],"underline":["8"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7511332-cd4e-4e28-b7be-a0da3b4062d4', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The manager''s knowledge of the strike is of the <u>utmost</u> importance.', null, '["basic","genuine","standard","paramount"]', 3, 'Utmost = paramount.', true, '2026-10-24 01:01:53.268', '2026-10-24 01:01:53.268', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The manager''s knowledge of the strike is of the <u>utmost</u> importance.', '["basic","genuine","standard","<u>paramount</u>"]', '<b>Utmost</b> = <b>paramount</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c757010e-daac-4ad3-bdc5-5e1644e2089e', 'Physics', 'JAMB', null, 1999, null, 'The velocities of light in air and glass are 3.0 x 10⁸ m s⁻¹ and 2.0 x 10⁸ m s⁻¹ respectively. If the angle of refraction is 30°, the sine of the angle of incidence is', null, '["0.33","0.50","0.67","0.75"]', 3, 'sin i/sin r = vair/vglass = 1.5, so sin i = 1.5 x sin 30° = 0.75.', true, '2026-10-12 19:15:48.145', '2026-10-12 19:15:48.145', null, null, null, 'The velocities of light in air and glass are 3.0 x 10<sup>8</sup> m s<sup>-1</sup> and 2.0 x 10<sup>8</sup> m s<sup>-1</sup> respectively. If the angle of refraction is 30°, the sine of the angle of incidence is', '["0.33","0.50","0.67","0.75"]', 'sin i/sin r = v<sub>air</sub>/v<sub>glass</sub> = 1.5, so sin i = 1.5 x sin 30° = 0.75.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c758de23-1f35-4eff-b23c-3b63138b097c', 'Economics', 'JAMB', null, 2026, null, 'The full form of OPEC is', null, '["Oil and Petroleum Exporting Countries","Organ for Petrol Exportation Countries","Organization of Petroleum Exporting Countries","Organization of Petroleum Exploiting Countries"]', 2, 'OPEC stands for Organization of Petroleum Exporting Countries.', true, '2026-09-12 10:57:25.842', '2026-09-12 10:57:25.842', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c75a8wmmw15zlxpr65udj4tqb', 'General Mathematics', 'WAEC', null, 2020, null, 'Evaluate ∫₀¹ ln x dx.', null, '["-1","0","1","Divergent"]', 0, '∫ln x dx = x ln x - x; evaluated 0 to 1 = -1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Evaluate ∫₀¹ ln x dx.', '["-1","0","1","Divergent"]', 'Integral = <u>-1</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c75cf942jl1qlnvm6ru2mtatz', 'Chemistry', 'JAMB', null, 1999, null, 'Which of the following gases will diffuse fastest when passed through a porous plug?', null, '["Propane","Oxygen","Methane","Ammonia [H=1, C=12, N=14, O=16]"]', 3, 'NH3 (Mr=17) is the lightest among the options (excluding CH4 = 16). Wait, CH4 = 16 < NH3 = 17; so methane is fastest. Key says ammonia.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following gases will diffuse fastest when passed through a porous plug?', '["Propane","Oxygen","Methane","Ammonia"]', '<u>Methane (Mr=16)</u> is lightest; key says ammonia.', '{"bold":[],"italic":[],"underline":["Ammonia"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c75eyxhwg7xz51dhc3936t219', 'Chemistry', 'JAMB', null, 1996, null, 'The appropriate test paper to use in the above experiment is moist', null, '["litmus paper","potassium heptaoxodichromate(IV) paper","lead(II) trioxonitrate(V) paper","Universal indicator paper"]', 1, 'Dichromate paper detects SO2 (turns green).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The appropriate test paper to use in the above experiment is moist', '["litmus paper","potassium heptaoxodichromate(IV) paper","lead(II) trioxonitrate(V) paper","Universal indicator paper"]', '<u>Dichromate paper</u> detects SO2.', '{"bold":[],"italic":[],"underline":["potassium heptaoxodichromate(IV) paper"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c75k0rosl4uqlcrkmrkiy8n36', 'Physics', 'JAMB', null, 2021, null, 'Given the acceleration due to gravity to be 6.67 and radius 4×10⁶, the mass of the earth is', null, '["16×10²³kg","76×10²⁴kg","16×10²⁴kg","76×10²³kg"]', 2, 'g = GM/R² → M = gR²/G = 6.67×(4×10⁶)²/(6.67×10⁻¹¹) = 16×10²⁴ kg.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Given the acceleration due to gravity to be 6.67 and radius 4×10⁶, the mass of the earth is', '["16×10²³kg","76×10²⁴kg","<u>16×10²⁴kg</u>","76×10²³kg"]', 'M = gR²/G = <u>16×10²⁴ kg</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c75sr58eow5btutrhmz52xcuq', 'Chemistry', 'JAMB', null, 1989, null, 'A metal is extracted from its ore by the electrolysis of its molten chloride and it displaces lead from lead(II) trioxonitrate(V) solution. The metal is', null, '["copper","aluminium","zinc","sodium"]', 1, 'Al is extracted by electrolysis of molten chloride and displaces Pb.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A metal is extracted from its ore by the electrolysis of its molten chloride and it displaces lead from lead(II) trioxonitrate(V) solution. The metal is', '["copper","aluminium","zinc","sodium"]', '<u>Aluminium</u> fits both criteria.', '{"bold":[],"italic":[],"underline":["aluminium"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c76842vt7hs7owhpvnumg28np', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the shortest distance between the curves y² = 4x and x² = 4y.', null, '["0","2√2","4√2","8√2"]', 0, 'Curves intersect at origin; distance = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the shortest distance between the curves y² = 4x and x² = 4y.', '["0","2√2","4√2","8√2"]', 'Shortest distance = <u>0</u>.', '{"bold":[],"italic":[],"underline":["0"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c76dwc7b3d5m7s9ywrx1w51ah', 'Physics', 'JAMB', null, 2019, null, 'The period of a spring-mass system depends on the following except', null, '["mass of the system","spring constant","stiffness of the spring","amplitude of the motion"]', 3, 'The period of a spring-mass system is independent of amplitude.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The period of a <b>spring-mass system</b> depends on the following except', '["mass of the system","spring constant","stiffness of the spring","<u>amplitude of the motion</u>"]', 'The period of a spring-mass system is <u>independent of amplitude</u>.', null);
