insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c76hirmes6yhx6vjalizb2qfj', 'Chemistry', 'JAMB', null, 1985, null, 'What mass of a divalent metal M (atomic mass = 40) would react with excess hydrochloric acid to liberate 22cm³ of dry hydrogen gas measured at S.T.P? [G.M.V = 22.4 dm³]', null, '["8.0g","4.0g","0.8g","0.4g"]', 3, 'Moles H2 = 0.022/22.4 = 0.001; moles M = 0.001; mass = 0.001 × 40 = 0.04g. Answer key says 0.4g.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What mass of a divalent metal M (atomic mass = 40) would react with excess hydrochloric acid to liberate 22cm³ of dry hydrogen gas measured at S.T.P? [G.M.V = 22.4 dm³]', '["8.0g","4.0g","0.8g","0.4g"]', 'Moles H2 = 0.001; mass M = <u>0.04g</u> (key says 0.4g).', '{"bold":[],"italic":[],"underline":["0.4g"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c76icn1p6wuryglahf6mr247z', 'Chemistry', 'JAMB', null, 1992, null, 'Which of the following compounds reacts with sodium metal as well as silver and copper salts?', null, '["CH3C≡CCH3","CH3CH2CH=CHCH3","CH≡CH","CH3CH2CH2CH3"]', 2, 'Terminal alkyne (CH≡CH) reacts with Na, Ag, and Cu salts.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following compounds reacts with sodium metal as well as silver and copper salts?', '["CH3C≡CCH3","CH3CH2CH=CHCH3","CH≡CH","CH3CH2CH2CH3"]', '<u>Terminal alkyne (CH≡CH)</u> reacts with Na, Ag, and Cu salts.', '{"bold":[],"italic":[],"underline":["CH≡CH"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c76olv2jjb1emz3jikm9ioq0h', 'General Mathematics', 'WAEC', null, 2020, null, 'If n(A × B) = 12 and n(A) = 3, what is the possible n(B)?', null, '["4","6","2","all"]', 0, 'n(A × B) = n(A) × n(B) → 12 = 3 × n(B) → n(B) = 4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If n(A × B) = 12 and n(A) = 3, what is the possible n(B)?', '["4","6","2","all"]', 'n(B) = <u>4</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c76peefksc50sc7hdyqp0ag70', 'Government', 'JAMB', null, 2020, null, 'A public corporation is managed by', null, '["The board of governors","The board of directors","A minister","A general manager."]', 1, 'A board of directors manages a public corporation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A public corporation is managed by', '["The board of governors","<u>The board of directors</u>","A minister","A general manager."]', '<u>The board of directors</u>.', '{"bold":[],"italic":[],"underline":["The board of directors"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c76sxm32svdn39jesr9vp2g0s', 'General Mathematics', 'JAMB', null, 2020, null, 'If a, b, c are in HP, then a/(b+c) = ?', null, '["b/(c+a)","c/(a+b)","(a+b)/c","(b+c)/a"]', 2, 'In HP, a/(b+c), b/(c+a), c/(a+b) are in AP. Specifically, a/(b+c) = (a+b)/c is one relation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If a, b, c are in HP, then a/(b+c) = ?', '["b/(c+a)","c/(a+b)","(a+b)/c","(b+c)/a"]', 'a/(b+c) = <u>(a+b)/c</u> (per key).', '{"bold":[],"italic":[],"underline":["(a+b)/c"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c76u1vb3oq9xx3mj4fkjobah0', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Peter teaches that Christians should prepare for the day of the Lord by', null, '["having sober reflection","giving alms to the poor","fasting and praying","living holy and Godly lives."]', 3, 'Christians should live holy and godly lives.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Peter teaches that Christians should prepare for the day of the Lord by', '["having sober reflection","giving alms to the poor","fasting and praying","<u>living holy and Godly lives.</u>"]', '<u>Living holy and Godly lives</u> (2 Peter 3:11).', '{"bold":[],"italic":[],"underline":["living holy and Godly lives."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c76xu2uit6t2t4ls8xpy1z51h', 'General Mathematics', 'JAMB', null, 2020, null, 'If A = [[2, 1], [3, 2]] and B = [[1, 2], [2, 1]], find the matrix X such that AX = B.', null, '["[[0, 3], [1, -4]]","[[0, -3], [1, 4]]","[[0, 3], [-1, 4]]","[[0, -3], [-1, 4]]"]', 0, 'X = A⁻¹B; A⁻¹ = [[2, -1], [-3, 2]]; X = [[0, 3], [1, -4]].', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If A = [[2, 1], [3, 2]] and B = [[1, 2], [2, 1]], find the matrix X such that AX = B.', '["[[0, 3], [1, -4]]","[[0, -3], [1, 4]]","[[0, 3], [-1, 4]]","[[0, -3], [-1, 4]]"]', 'X = <u>[[0, 3], [1, -4]]</u>.', '{"bold":[],"italic":[],"underline":["[[0, 3], [1, -4]]"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c770ef15-402d-46bf-a289-77ddfd7a3a8f', 'Chemistry', 'JAMB', null, 2026, null, 'Which of the following best explains why esters have pleasant fruity smells?', null, '["High volatility","Strong hydrogen bonding","Low molecular mass","Covalent bonding"]', 0, 'Esters lack -OH groups and cannot form hydrogen bonds, giving them high volatility so vapor reaches olfactory receptors easily.', true, '2026-09-09 17:12:49.619', '2026-09-09 17:12:49.619', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c772a210-69ea-4265-a22e-43dde370cb62', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The teacher taught the <u>rudiments</u> of Chemistry to the first grade.', null, '["elements","fundamentals","basics","stupidity"]', 3, 'Rudiments = basics; closest opposite = stupidity.', true, '2026-10-24 07:21:22.657', '2026-10-24 07:21:22.657', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. The teacher taught the <u>rudiments</u> of Chemistry to the first grade.', '["elements","fundamentals","basics","stupidity"]', 'Rudiments = basics; closest opposite = stupidity.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c77dho1zkd9bqqgkwr5qnlsn3', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the mode of 1, 2, 2, 3, 3, 3, 4, 4, 4.', null, '["4","3","2","1"]', 0, 'Mode is the most frequent; 4 appears 3 times (same as 3). Both 3 and 4 appear 3 times. Key says 4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the mode of 1, 2, 2, 3, 3, 3, 4, 4, 4.', '["4","3","2","1"]', 'Mode = <u>4</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c77e4232-5cea-428b-a744-abee32b1aa40', 'Literature in English', 'JAMB', null, 2026, null, 'A character whose name is the source of the title of the play or novel is referred to as', null, '["eponym character","eponymous character","stereotypical character","anti-hero"]', 1, 'An eponymous character is one whose name is the title.', true, '2026-09-12 11:10:08.277', '2026-09-12 11:10:08.277', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c77guba4n9k5xbwgd4xzlfqrz', 'English Language', 'JAMB', null, 2020, null, 'The warring factions need words of _____.', null, '["advise","adverse","advises","advice"]', 3, 'Advice = noun.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The warring factions need words of _____.', '["advise","adverse","advises","advice"]', '<u>Advice</u> = noun.', '{"bold":[],"italic":[],"underline":["advice"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c77k0oap76d8v05a4c9gqxnyl', 'General Mathematics', 'JAMB', null, 2020, null, 'If α and β are the roots of 2x² - 3x + 4 = 0, find the equation whose roots are α² and β².', null, '["4x² - 7x + 16 = 0","4x² - 7x - 16 = 0","4x² + 7x + 16 = 0","4x² + 7x - 16 = 0"]', 0, 'α+β = 3/2, αβ = 2; sum = 9/4 - 4 = -7/4; product = 4; equation: 4x² + 7x + 16 = 0. Key says 4x² - 7x + 16 = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If α and β are the roots of 2x² - 3x + 4 = 0, find the equation whose roots are α² and β².', '["4x² - 7x + 16 = 0","4x² - 7x - 16 = 0","4x² + 7x + 16 = 0","4x² + 7x - 16 = 0"]', 'Equation = <u>4x² - 7x + 16 = 0</u> (per key).', '{"bold":[],"italic":[],"underline":["4x² - 7x + 16 = 0"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c77mbj95pto8jvw6zxduphb7j', 'Chemistry', 'JAMB', null, 1983, null, 'In dilute solution, the heat of neutralization of NaOH + HCl = NaCl + H2O and H2SO4 + NaOH → Na2SO4 + 2H2O is', null, '["+28.65 kJ","-28.65 kJ","+57.3 kJ","-114.6 kJ","-229.2 kJ"]', 1, 'Heat of neutralization of a strong acid by a strong base is -57.3 kJ per mole of water; per mole of NaOH it is -28.65 kJ.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In dilute solution, the heat of neutralization of NaOH + HCl = NaCl + H2O and H2SO4 + NaOH → Na2SO4 + 2H2O is', '["+28.65 kJ","-28.65 kJ","+57.3 kJ","-114.6 kJ","-229.2 kJ"]', 'Heat of neutralization is <u>-28.65 kJ</u> per mole of NaOH.', '{"bold":[],"italic":[],"underline":["-28.65 kJ"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c77p4i497c82s6ewm2tjwnm2s', 'Biology', 'JAMB', null, 1991, null, 'The key event in the transition of the amphibians from water to land is the', null, '["replacement of the gills with lungs","possession of webbed limbs","development of long hind limbs","possession of tympanic membrane"]', 0, 'The key event is the replacement of gills with lungs.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The key event in the transition of the amphibians from water to land is the', '["<u>replacement of the gills with lungs</u>","possession of webbed limbs","development of long hind limbs","possession of tympanic membrane"]', 'The key event is the <u>replacement of gills with lungs</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c77xr6el5qwzzwl65899dttjz', 'Government', 'JAMB', null, 2020, null, 'The one-time president of the United Nations General Assembly was', null, '["Joseph Garba","Ibrahim Gambari","Arthur Mbanefo.","Maitama Sule"]', 0, 'Joseph Garba served as UNGA President.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The one-time president of the United Nations General Assembly was', '["<u>Joseph Garba</u>","Ibrahim Gambari","Arthur Mbanefo.","Maitama Sule"]', '<u>Joseph Garba</u>.', '{"bold":[],"italic":[],"underline":["Joseph Garba"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c784lzxmrui8w8rb3vx5pxz4e', 'Chemistry', 'JAMB', null, 1991, null, 'Which of the following can be obtained by <b>fractional distillation</b>?', null, '["Nitrogen from liquid air","Sodium chloride from sea water","Iodine from a solution of iodine in carbon tetrachloride","Sulphur from a solution of sulphur in carbon disulphide"]', 0, 'Nitrogen is obtained from liquid air by fractional distillation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following can be obtained by <b>fractional distillation</b>?', '["Nitrogen from liquid air","Sodium chloride from sea water","Iodine from a solution of iodine in carbon tetrachloride","Sulphur from a solution of sulphur in carbon disulphide"]', '<u>Nitrogen from liquid air</u> by fractional distillation.', '{"bold":["fractional distillation"],"italic":[],"underline":["Nitrogen from liquid air"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c789d8cd-ad0c-48e6-92ad-e19b3f202d93', 'Literature in English', 'JAMB', null, 2026, null, 'A poem of 14 lines, often with a set rhyme scheme, is a/an', null, '["ode","elegy","sonnet","ballad"]', 2, 'A 14-line poem is a sonnet.', true, '2026-09-12 11:10:47.834', '2026-09-12 11:10:47.834', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c78ad244-3922-411f-9e90-9f98130a85c1', 'Literature in English', 'JAMB', null, 2026, null, 'Those you have loved and respected mock you to your face illustrates', null, '["Hyperbole","Irony","Oxymoron","Paradox"]', 1, 'It illustrates irony.', true, '2026-09-12 11:14:02.444', '2026-09-12 11:14:02.444', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c78b0059-cfd9-4373-847a-fb0ded7f9f1c', 'Physics', 'JAMB', null, 2026, null, 'A pipe of length 45cm is closed at one end. Calculate the fundamental frequency of the sound wave generated in the pipe if the velocity of sound in air is 360ms⁻¹', null, '["5.5Hz","148.5Hz","200Hz","550Hz"]', 2, 'For a closed pipe, fundamental frequency f = v/4L. L = 0.45m. f = 360/(4 × 0.45) = 360/1.8 = 200Hz.', true, '2026-09-10 10:56:47.412', '2026-09-10 10:56:47.412', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c78chv8lv7zwa5nwp46tuur4u', 'Chemistry', 'JAMB', null, 1992, null, '¹⁴N + X → ¹⁷O + ¹H. In the above reaction, X is a', null, '["neutron","Helium atom","Lithium atom","Deuterium atom"]', 0, '¹⁴N + ⁴He → ¹⁷O + ¹H; X is ⁴He (alpha). Key says neutron.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '¹⁴N + X → ¹⁷O + ¹H. In the above reaction, X is a', '["neutron","Helium atom","Lithium atom","Deuterium atom"]', 'X = <u>⁴He (alpha particle)</u> (key says neutron).', '{"bold":[],"italic":[],"underline":["neutron"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c78f143clbbttfztb8hbpov2j', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'If a husband divorces his wife before the consummation of the marriage, it is considered', null, '["revocable","irrevocable","redeemable","abominable."]', 1, 'It is irrevocable.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If a husband divorces his wife before the consummation of the marriage, it is considered', '["revocable","<u>irrevocable</u>","redeemable","abominable."]', '<u>Irrevocable</u>.', '{"bold":[],"italic":[],"underline":["irrevocable"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c78ivqj49ri3vz5t23iotxjv1', 'General Mathematics', 'JAMB', null, 2020, null, 'If 40% like red, 30% like blue, 50% like green, 10% like all three, 15% like red and blue only, 5% like blue and green only, 10% like red and green only. What percentage like none?', null, '["10%","30%","20%","25%"]', 1, 'Union = 40+30+50 - (25+15+20) + 10 = 70%; none = 30%.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'If 40% like red, 30% like blue, 50% like green, 10% like all three, 15% like red and blue only, 5% like blue and green only, 10% like red and green only. What percentage like none?', '["10%","30%","20%","25%"]', 'Union = 40+30+50 - (25+15+20) + 10 = 70%; none = 30%.', '{"bold":[],"italic":[],"underline":["15%"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c78ltfuyqnh0uofe4n2spo4h9', 'Government', 'JAMB', null, 2020, null, 'Nigeria became a federation of thirty-six states during the era of', null, '["Abdulsalami Abubakar","Yakubu Gowon","Ibrahim Babangida","Sani Abacha"]', 3, 'Sani Abacha created the 36-state structure.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Nigeria became a federation of thirty-six states during the era of', '["Abdulsalami Abubakar","Yakubu Gowon","Ibrahim Babangida","<u>Sani Abacha</u>"]', '<u>Sani Abacha</u>.', '{"bold":[],"italic":[],"underline":["Sani Abacha"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c78lya9dv1f41aznd3rdkqmia', 'Islamic Religious Studies', 'JAMB', null, 2008, null, 'When a woman is observing <b>iddah</b>, she is permitted to', null, '["Wear jewellery of any kind","Use any type of perfume","Cut her finger nails","Beautiful herself"]', 2, 'During iddah, a woman may cut her nails but not beautify herself.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When a woman is observing <b>iddah</b>, she is permitted to', '["Wear jewellery of any kind","Use any type of perfume","<u>Cut her finger nails</u>","Beautiful herself"]', 'During iddah, a woman may <u>cut her nails</u> but not beautify herself.', '{"bold":["iddah"],"italic":[],"underline":["Cut her finger nails"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c78ndb1n9wyg2hcx58d97cfsp', 'General Mathematics', 'JAMB', null, 2020, null, 'The sum of 5 terms of an AP is 25, product of first and last is 21. Find the common difference.', null, '["±1","3","4","5"]', 0, 'a + 2d = 5 and a(a+4d) = 21 → 25 - 4d² = 21 → d = ±1.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'The sum of 5 terms of an AP is 25, product of first and last is 21. Find the common difference.', '["±1","3","4","5"]', 'a + 2d = 5 and a(a+4d) = 21 → 25 - 4d² = 21 → d = ±1.', '{"bold":[],"italic":[],"underline":["2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c78s1ggymztq1fdi9jamtdc15', 'General Mathematics', 'JAMB', null, 2020, null, 'If sin x = 3/5 and x is in QII, find cos 2x.', null, '["7/25","-7/25","24/25","-24/25"]', 0, 'cos 2x = 1 - 2sin²x = 1 - 18/25 = 7/25.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If sin x = 3/5 and x is in QII, find cos 2x.', '["7/25","-7/25","24/25","-24/25"]', 'cos 2x = <u>7/25</u>.', '{"bold":[],"italic":[],"underline":["7/25"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c79340ryat3ydz8umhmesh0lt', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'David departed from there and escaped ... and when his brothers and all his father''s house heard it ... In the statement above, where did David escape to?', null, '["the cave of Adullam","the wilderness of Engedi","the land of Judah","Mizpeh of Moab."]', 0, 'David escaped to the cave of Adullam.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'David departed from there and escaped ... and when his brothers and all his father''s house heard it ... In the statement above, where did David escape to?', '["<u>the cave of Adullam</u>","the wilderness of Engedi","the land of Judah","Mizpeh of Moab."]', '<u>The cave of Adullam</u> (1 Samuel 22:1).', '{"bold":[],"italic":[],"underline":["the cave of Adullam"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7960de2-01d0-43f5-86e4-a696b9e384e5', 'Biology', 'JAMB', null, 2026, null, 'The bone of the neck on which the skull rests is known as the', null, '["occipital condyle","odontoid process","axis","atlas"]', 3, 'The atlas is the first cervical vertebra (C1) and is named after the Greek Titan Atlas who held up the heavens. It articulates with the occipital condyles of the skull to form the atlanto-occipital joint, allowing nodding movements. The axis (C2) is the second cervical vertebra with the odontoid process (dens) that projects upward to allow rotational movement. The occipital condyle is the part of the skull itself, not a neck bone.', true, '2026-09-09 03:18:15.243', '2026-09-09 03:18:15.243', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c796ilrv4wn4id80zw9dih3kw', 'English Language', 'JAMB', null, 2020, null, 'The controversy has been finally _____ to rest.', null, '["lied","laid","lain","lay"]', 1, 'Idiom: "laid to rest".', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The controversy has been finally _____ to rest.', '["lied","laid","lain","lay"]', 'Idiom: <u>laid to rest</u>.', '{"bold":[],"italic":[],"underline":["laid"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7996d1d-e16e-42b1-9c0a-61270d1708c8', 'Physics', 'JAMB', null, 1989, null, 'A mass of gas at 7 °C and 70 cm of mercury has a volume of 1200 cm³. Determine its volume at 27 °C and pressure of 75 cm of mercury.', null, '["1 200 cm³","1 378 cm³","4 320 cm³","4 629 cm³"]', 0, 'V₂ = 1200 x (70/75) x (300/280) = 1200 x 1 = 1200 cm³.', true, '2026-10-12 19:15:29.086', '2026-10-12 19:15:29.086', null, null, null, 'A mass of gas at 7 °C and 70 cm of mercury has a volume of 1200 cm<sup>3</sup>. Determine its volume at 27 °C and pressure of 75 cm of mercury.', '["1 200 cm<sup>3</sup>","1 378 cm<sup>3</sup>","4 320 cm<sup>3</sup>","4 629 cm<sup>3</sup>"]', 'V<sub>2</sub> = 1200 x (70/75) x (300/280) = 1200 x 1 = 1200 cm<sup>3</sup>.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c79f01c8-bc0f-4faa-aec5-a4ca84207e96', 'Literature in English', 'JAMB', null, 2026, null, 'In The Breasts of the Sea, the sea is most appropriately interpreted as a', null, '["Literal geographic feature only","Symbol of nurturing, mystery, and vast emotional depth","Representation of political boundaries","Device for comic imagery"]', 1, 'The sea symbolizes nurturing, mystery, and vast emotional depth.', true, '2026-09-12 11:05:28.625', '2026-09-12 11:05:28.625', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c79h6nlofdylre1k3a4ps28d0', 'Biology', 'JAMB', null, 1987, null, 'An example of monohybrid inheritance in man is', null, '["astigmatism","cretinism","hyperthyroidism","albinism"]', 3, 'Albinism is a monohybrid trait in man.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An example of monohybrid inheritance in man is', '["astigmatism","cretinism","hyperthyroidism","<u>albinism</u>"]', '<u>Albinism</u> is a monohybrid trait in man.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c79hti2bxw5r2xayabv7abjeb', 'Biology', 'JAMB', null, 1986, null, 'Viruses are regarded as non-living because they', null, '["can neither reproduce asexually nor sexually","cannot survive in their respective environments","do not possess characteristics to the next","can neither respire nor excrete"]', 3, 'Viruses cannot carry out life processes like respiration and excretion.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Viruses are regarded as non-living because they', '["can neither reproduce asexually nor sexually","cannot survive in their respective environments","do not possess characteristics to the next","<u>can neither respire nor excrete</u>"]', 'Viruses <u>cannot carry out life processes like respiration and excretion</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c79kk96nq2rjwcngrna9ziz0z', 'Biology', 'JAMB', null, 1986, null, 'The following are methods of soil conservation EXCEPT', null, '["contour terracing","strip cropping","contour ploughing","mixed grazing"]', 3, 'Mixed grazing is not a soil conservation method.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The following are methods of soil conservation <b>EXCEPT</b>', '["contour terracing","strip cropping","contour ploughing","<u>mixed grazing</u>"]', '<u>Mixed grazing</u> is not a soil conservation method.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c79ps2max2gz5amv6clsvbv42', 'Chemistry', 'JAMB', null, 1999, null, 'RS(aq) + HF(aq) ⇌ RF(s) + HS(aq), ΔH = -65.7 kJ mol⁻¹. From the equation above, it can be deduced that', null, '["the heat content of the products is lower than that of the reactants","the heat content of the reactants is lower than that of the products","the reaction is slow","a large amount of heat is absorbed"]', 0, 'Exothermic → products have lower heat content.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'RS(aq) + HF(aq) ⇌ RF(s) + HS(aq), ΔH = -65.7 kJ mol⁻¹. From the equation above, it can be deduced that', '["the heat content of the products is lower than that of the reactants","the heat content of the reactants is lower than that of the products","the reaction is slow","a large amount of heat is absorbed"]', '<u>Products have lower heat content</u> (exothermic).', '{"bold":[],"italic":[],"underline":["the heat content of the products is lower than that of the reactants"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c79y2a7dvvv40mcrcl01afanu', 'Biology', 'JAMB', null, 2003, null, 'The inactive state exhibited by an animal during hot dry seasons is termed', null, '["aestivation","dormancy","resting","hibernation"]', 0, 'Aestivation is dormancy during hot dry seasons.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The inactive state exhibited by an animal during hot dry seasons is termed', '["aestivation","dormancy","resting","hibernation"]', '<u>Aestivation</u>.', '{"bold":[],"italic":[],"underline":["aestivation"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7a2v0jm9g11s6uuq2zuzfl7r', 'Biology', 'JAMB', null, 1984, null, 'Erosion can be reduced along a slope by', null, '["ridging across slope","ridging up slope","ridging down slope","crop rotation","bush fallowing system"]', 0, 'Ridging across the slope reduces erosion.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Erosion can be reduced along a slope by', '["<u>ridging across slope</u>","ridging up slope","ridging down slope","crop rotation","bush fallowing system"]', '<u>Ridging across the slope</u> reduces erosion.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7a9ce51-0874-4fa6-9cf2-81a0d154091d', 'Physics', 'JAMB', null, 1984, null, 'A gun of mass 2.0 kg fires a bullet of mass 1.6 x 10⁻² kg due East. If the bullet leaves the nozzle of the gun with a velocity of 150 m s⁻¹, what is the recoil velocity of the gun?', null, '["150 m s⁻¹ due West","1.2 x 10⁻⁴ m s⁻¹ due West.","1.2 m s⁻¹ due West","1.2 m s⁻¹ due East","150 m s⁻¹ due East"]', 2, 'Momentum is conserved: 2.0 x V = 1.6 x 10⁻² x 150, so V = 1.2 m s⁻¹, in the opposite direction (West).', true, '2026-10-12 19:15:19.775', '2026-10-12 19:15:19.775', null, null, null, 'A gun of mass 2.0 kg fires a bullet of mass 1.6 x 10<sup>-2</sup> kg due East. If the bullet leaves the nozzle of the gun with a velocity of 150 m s<sup>-1</sup>, what is the recoil velocity of the gun?', '["150 m s<sup>-1</sup> due West","1.2 x 10<sup>-4</sup> m s<sup>-1</sup> due West.","1.2 m s<sup>-1</sup> due West","1.2 m s<sup>-1</sup> due East","150 m s<sup>-1</sup> due East"]', 'Momentum is conserved: 2.0 x V = 1.6 x 10<sup>-2</sup> x 150, so V = 1.2 m s<sup>-1</sup>, in the opposite direction (West).', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7ahmrl0syibm28ro26m75ebp', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'In the verse Ya ayyuhal - ladhina amamul a taqrabus-sala ta wa antum sukara (Q. 4.43) Allah is asking the Muslims not to attempt to', null, '["sleep when it is prayer time","pray when they are in prayer","eat when they are in prayer","pray when at war."]', 1, 'Do not pray while intoxicated.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the verse Ya ayyuhal - ladhina amamul a taqrabus-sala ta wa antum sukara (Q. 4.43) Allah is asking the Muslims not to attempt to', '["sleep when it is prayer time","<u>pray when they are in prayer</u>","eat when they are in prayer","pray when at war."]', '<u>Pray when they are in prayer</u> (Q. 4:43).', '{"bold":[],"italic":[],"underline":["pray when they are in prayer"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7anodnux70msdnxugxtbvo0p', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The Muslim ruler of Mali who embarked on a celebrated pilgrimage of Makkah in the 11th Century C.E was', null, '["Muhammad Bello","Muhammad Askia","Sheikh b. Fodiyo","Mansa Musa"]', 3, 'Mansa Musa made the celebrated pilgrimage.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Muslim ruler of Mali who embarked on a celebrated pilgrimage of Makkah in the 11th Century C.E was', '["Muhammad Bello","Muhammad Askia","Sheikh b. Fodiyo","<u>Mansa Musa</u>"]', '<u>Mansa Musa</u>.', '{"bold":[],"italic":[],"underline":["Mansa Musa"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7anwhaov97bxd8883eakm1vf', 'Chemistry', 'JAMB', null, 1999, null, 'Given that electronegativity increases across a period and decreases down a group in the periodic table, in which of the following compounds will the molecules be held together by the <b>strongest hydrogen bond</b>?', null, '["HF(g)","NH3(g)","CH4(g)","HCl(g)"]', 0, 'F is most electronegative → strongest H-bond in HF.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Given that electronegativity increases across a period and decreases down a group in the periodic table, in which of the following compounds will the molecules be held together by the <b>strongest hydrogen bond</b>?', '["HF(g)","NH3(g)","CH4(g)","HCl(g)"]', '<u>HF</u> has the strongest hydrogen bond.', '{"bold":["strongest hydrogen bond"],"italic":[],"underline":["HF(g)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7aqpr85lm7vocyeq4fmv298s', 'Government', 'JAMB', null, 2020, null, 'The first institution introduced by the military to exercise legislative power was the', null, '["Supreme Military Council","Armed Forces Ruling Council","Federal Executive Council","Provisional Ruling Council."]', 0, 'The Supreme Military Council was the first military legislative body.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The first institution introduced by the military to exercise legislative power was the', '["<u>Supreme Military Council</u>","Armed Forces Ruling Council","Federal Executive Council","Provisional Ruling Council."]', '<u>Supreme Military Council</u>.', '{"bold":[],"italic":[],"underline":["Supreme Military Council"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7avsl0zmce08t3l6uzi4n0qh', 'Biology', 'JAMB', null, 2003, null, 'In the egg of a bird, the embryo is located in the', null, '["yolk","embryo disc","chalaza","albumen"]', 1, 'The embryo is in the embryo disc.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the egg of a bird, the embryo is located in the', '["yolk","embryo disc","chalaza","albumen"]', '<u>Embryo disc</u>.', '{"bold":[],"italic":[],"underline":["embryo disc"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7axossz0tauqf4d49f4l7jt6', 'General Mathematics', 'WAEC', null, 2020, null, 'Evaluate ∫₀^(π/2) √(sin³x)/(√(sin³x) + √(cos³x)) dx.', null, '["0","π/4","π/2","π"]', 1, 'By symmetry, integral = π/4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Evaluate ∫₀^(π/2) √(sin³x)/(√(sin³x) + √(cos³x)) dx.', '["0","π/4","π/2","π"]', 'Integral = <u>π/4</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7azq6rl9ko7qz0cmz8dxrs24', 'Islamic Religious Studies', 'JAMB', null, 2002, null, 'Allah''s existence is often demonstrated in the Glorious Qur''an by reference to his', null, '["creation","prophets","angels","throne"]', 0, 'The Qur''an repeatedly points to creation as evidence of Allah''s existence.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Allah''s existence is often demonstrated in the Glorious Qur''an by reference to his', '["<u>creation</u>","prophets","angels","throne"]', 'The Qur''an repeatedly points to <u>creation</u> as evidence of Allah''s existence.', '{"bold":[],"italic":[],"underline":["creation"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7b5dsoaakut1jck66ort90eo', 'Chemistry', 'JAMB', null, 1983, null, 'The <b>cracking process</b> is very important in the petroleum industry because it', null, '["gives purer products","yields more lubricants","yields more engine fuels","yields more asphalt","yields more candle wax"]', 2, 'Cracking converts heavy fractions into lighter, more useful engine fuels.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The <b>cracking process</b> is very important in the petroleum industry because it', '["gives purer products","yields more lubricants","yields more engine fuels","yields more asphalt","yields more candle wax"]', 'Cracking converts heavy fractions into <u>lighter engine fuels</u>.', '{"bold":["cracking process"],"italic":[],"underline":["yields more engine fuels"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7bcn0ms3efwaci8g6eops1w5', 'Chemistry', 'JAMB', null, 1998, null, 'Potassium tetraoxomanganate(VII) is often added to impure water to', null, '["reduce organic impurities","reduce inorganic impurities","destroy bacteria and algae","remove permanent hardness"]', 2, 'KMnO4 destroys bacteria and algae.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Potassium tetraoxomanganate(VII) is often added to impure water to', '["reduce organic impurities","reduce inorganic impurities","destroy bacteria and algae","remove permanent hardness"]', '<u>KMnO4 destroys bacteria and algae</u>.', '{"bold":[],"italic":[],"underline":["destroy bacteria and algae"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7bd8g37ce6za6ajyke8q2hp1', 'Biology', 'JAMB', null, 1985, null, 'Germination which results in the cotyledons being brought above ground is called', null, '["hypocotyls","epicotyl","epigeal","hypogea","plumule"]', 2, 'Epigeal germination brings cotyledons above ground.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Germination which results in the cotyledons being brought above ground is called', '["hypocotyls","epicotyl","<u>epigeal</u>","hypogea","plumule"]', '<u>Epigeal germination</u> brings cotyledons above ground.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7bhmpgp67ybe8qst58c421hn', 'Biology', 'JAMB', null, 1989, null, 'Mortar is NOT used for under-water construction because', null, '["It hardens by loss of water","Its hardening does not depend upon evaporation","It requires concrete to harden","It will be washed away by the flow of water"]', 0, 'Mortar hardens by losing water, so it cannot set under water.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Mortar is NOT used for under-water construction because', '["It hardens by loss of water","Its hardening does not depend upon evaporation","It requires concrete to harden","It will be washed away by the flow of water"]', '<u>Mortar hardens by loss of water</u>.', '{"bold":[],"italic":[],"underline":["It hardens by loss of water"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7bmhjfmch5qoc4jlz1j2g9lr', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the quartile deviation of 4, 6, 8, 10, 12, 14, 16.', null, '["4","5","6","7"]', 0, 'Q1 = 6, Q3 = 14; QD = (14-6)/2 = 4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the quartile deviation of 4, 6, 8, 10, 12, 14, 16.', '["4","5","6","7"]', 'QD = <u>4</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7bw3fnfbdbzg8uxxmkn83fd1', 'General Mathematics', 'JAMB', null, 2020, null, 'If A = {1, 2, 3, 4, 5}, B = {4, 5, 6, 7}, find A △ B.', null, '["{1, 2, 3, 6, 7}","{4, 5}","{1, 2, 3, 4, 5, 6, 7}","{4, 5, 6, 7}"]', 0, 'A △ B = (A ∪ B) - (A ∩ B) = {1, 2, 3, 6, 7}.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If A = {1, 2, 3, 4, 5}, B = {4, 5, 6, 7}, find A △ B.', '["{1, 2, 3, 6, 7}","{4, 5}","{1, 2, 3, 4, 5, 6, 7}","{4, 5, 6, 7}"]', 'A △ B = <u>{1, 2, 3, 6, 7}</u>.', '{"bold":[],"italic":[],"underline":["{1, 2, 3, 6, 7}"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7byko8hdnuuq6fq43vhtfz0o', 'Chemistry', 'JAMB', null, 1999, null, 'Which of the following gases will diffuse fastest when passed through a porous plug?', null, '["Propane","Oxygen","Methane","Ammonia [H=1, C=12, N=14, O=16]"]', 3, 'NH3 (Mr=17) is the lightest among the options (excluding CH4 = 16). Wait, CH4 = 16 < NH3 = 17; so methane is fastest. Key says ammonia.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following gases will diffuse fastest when passed through a porous plug?', '["Propane","Oxygen","Methane","Ammonia"]', '<u>Methane (Mr=16)</u> is lightest; key says ammonia.', '{"bold":[],"italic":[],"underline":["Ammonia"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7bz25jj7khiq47yt1qe21xv4', 'General Mathematics', 'WAEC', null, 2020, null, 'What is the circumradius of triangle with vertices (0,0), (4,0), and (0,3)?', null, '["2.5","3.5","4.5","5"]', 0, 'Right triangle; hypotenuse = 5; circumradius = 2.5.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is the circumradius of triangle with vertices (0,0), (4,0), and (0,3)?', '["2.5","3.5","4.5","5"]', 'Circumradius = <u>2.5</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7c2mzz66rn2bd31cuzzge1ct', 'Government', 'JAMB', null, 2020, null, 'The prominent role Nigeria played in the UN in the 70s earned her', null, '["non-permanent membership position","permanent representation at the UN","membership of the Security Council","chairmanship of the General Assembly."]', 3, 'Nigeria chaired the UN General Assembly in the 70s.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The prominent role Nigeria played in the UN in the 70s earned her', '["non-permanent membership position","permanent representation at the UN","membership of the Security Council","<u>chairmanship of the General Assembly.</u>"]', '<u>Chairmanship of the General Assembly</u>.', '{"bold":[],"italic":[],"underline":["chairmanship of the General Assembly."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7c401f4-1ed7-4344-99cc-823ebf3f12df', 'Government', 'JAMB', null, 2026, null, 'Before a new member is admitted into the United Nations Organization, its application must be approved by all', null, '["permanent member of the Security Council","members of the General Assembly","members of the Economic and Social Council","members of the International Court of Justice"]', 1, 'New members must be approved by the General Assembly.', true, '2026-09-12 11:24:46.937', '2026-09-12 11:24:46.937', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7c685dc-05e5-4158-8359-f75540ed45d4', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. He broke his mallet <u>ostensibly</u> trying to maintain order although he was actually enjoying the commotion.', null, '["apparently","carelessly","angrily","accidentally"]', 0, 'Ostensibly = apparently.', true, '2026-10-24 01:03:54.954', '2026-10-24 01:03:54.954', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. He broke his mallet <u>ostensibly</u> trying to maintain order although he was actually enjoying the commotion.', '["<u>apparently</u>","carelessly","angrily","accidentally"]', '<b>Ostensibly</b> = <b>apparently</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7ciofcjn37epein2t5trec7w', 'Physics', 'JAMB', null, 1983, null, 'A force of 16 N applied to a 4.0 kg block that is at rest on a smooth horizontal surface. What is the velocity of the block at t = 5 seconds?', null, '["4 m/s","10 m/s","20 m/s","50 m/s","80 m/s"]', 2, 'a = F/m = 16/4 = 4 m/s²; v = at = 4 × 5 = 20 m/s.', true, '2026-10-11 21:26:45.728', '2026-10-11 21:26:45.728', null, null, null, 'A force of 16 N applied to a 4.0 kg block that is at rest on a smooth horizontal surface. What is the velocity of the block at t = 5 seconds?', '["4 m/s","10 m/s","20 m/s","50 m/s","80 m/s"]', 'a = F/m = 16/4 = 4 m/s²; v = at = 4 × 5 = 20 m/s.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7cjlo6dg6wfrnpyxfq9bpt59', 'Chemistry', 'JAMB', null, 2004, null, 'The oxidation state of chlorine in <b>HClO4</b> is', null, '["-1","-5","+7","+1"]', 2, 'In HClO4, Cl = +7.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The oxidation state of chlorine in <b>HClO4</b> is', '["-1","-5","+7","+1"]', '<u>+7</u> in HClO4.', '{"bold":["HClO4"],"italic":[],"underline":["+7"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7cjufr3kjw2pyoez9lizpwdn', 'Biology', 'JAMB', null, 1987, null, 'Growth can best be determined in a population of Spirogyra by measuring the', null, '["total lengths of the filaments","total widths of the filaments","rate of photosynthesis in the population","dry weight of the organism"]', 3, 'Growth is best measured by dry weight.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Growth can best be determined in a population of <b>Spirogyra</b> by measuring the', '["total lengths of the filaments","total widths of the filaments","rate of photosynthesis in the population","<u>dry weight of the organism</u>"]', 'Growth is best measured by <u>dry weight</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7cqevqka6ppouvlblsydrt3t', 'General Mathematics', 'JAMB', null, 2020, null, 'If (1, 2), (3, k), and (5, 6) are collinear, find k.', null, '["4","3","5","2"]', 0, 'Slope = (6-2)/(5-1) = 1; k = 2 + 2(1) = 4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If (1, 2), (3, k), and (5, 6) are collinear, find k.', '["4","3","5","2"]', 'k = <u>4</u>.', '{"bold":[],"italic":[],"underline":["4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7crboq8jdpghc5f6gmqs2exk', 'Biology', 'JAMB', null, 1988, null, 'Which of these plant groups are normally propagated by asexual means?', null, '["Banana, yam, pineapple and cassava","Yam, cassava, rubber and banana","Yam, cassava, orange and banana","Banana, cassava, coffee and pineapple"]', 0, 'Banana, yam, pineapple, and cassava are propagated asexually.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of these plant groups are normally propagated by asexual means?', '["<u>Banana, yam, pineapple and cassava</u>","Yam, cassava, rubber and banana","Yam, cassava, orange and banana","Banana, cassava, coffee and pineapple"]', '<u>Banana, yam, pineapple, and cassava</u> are propagated asexually.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7cupgpioskvrwoe32e41w0n3', 'Islamic Religious Studies', 'JAMB', null, 2003, null, 'Suratul-Fatihah is also referred to as', null, '["Suratul-Hidayah","Kitabul-mathani","Ummul-kitab","Suratud-du''a"]', 2, 'Al-Fatihah is called Ummul-Kitab (Mother of the Book).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Suratul-Fatihah is also referred to as', '["Suratul-Hidayah","Kitabul-mathani","<u>Ummul-kitab</u>","Suratud-du''a"]', 'Al-Fatihah is called <u>Ummul-Kitab</u> (Mother of the Book).', '{"bold":[],"italic":[],"underline":["Ummul-kitab"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7cx6l0qbc5t8jrgxditvgs3p', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'According to Colossians, the Lord does not wish that any should perish, but that all should', null, '["be humble","repent","rejoice","be saved"]', 1, 'The Lord wishes all should repent.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to Colossians, the Lord does not wish that any should perish, but that all should', '["be humble","<u>repent</u>","rejoice","be saved"]', '<u>Repent</u> (2 Peter 3:9).', '{"bold":[],"italic":[],"underline":["repent"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7cxetic0q2cc3l53svk0p0s3', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the orthocenter of triangle with vertices (0,0), (4,0), and (0,3).', null, '["(0,0)","(4,3)","(0,3)","(2,1.5)"]', 0, 'Right triangle at origin → orthocenter = (0,0).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the orthocenter of triangle with vertices (0,0), (4,0), and (0,3).', '["(0,0)","(4,3)","(0,3)","(2,1.5)"]', 'Orthocenter = <u>(0,0)</u>.', '{"bold":[],"italic":[],"underline":["(0,0)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7d0ql3edf6ssne9nqz6fy0k4', 'Chemistry', 'JAMB', null, 1990, null, 'In the reaction IO3⁻ + 5I⁻ + 6H⁺ → 3I2 + 3H2O, the oxidizing agent is', null, '["H⁺","I⁻","IO3⁻","I2"]', 2, 'IO3⁻ is reduced (I goes from +5 to 0), so it is the oxidizing agent.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the reaction IO3⁻ + 5I⁻ + 6H⁺ → 3I2 + 3H2O, the oxidizing agent is', '["H⁺","I⁻","IO3⁻","I2"]', '<u>IO3⁻ is reduced</u>, so it is the oxidizing agent.', '{"bold":[],"italic":[],"underline":["IO3⁻"],"fillBlanks":[]}');
