insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7h5bf1vtydnfpddevi8wy7rx', 'Biology', 'JAMB', null, 1983, null, 'Plants which can survive in places where the water supply is limited are', null, '["bryophytes","mesophytes","xerophytes","hydrophytes","pteridophytes"]', 2, 'Xerophytes are adapted to survive in dry conditions.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Plants which can survive in places where the water supply is limited are', '["bryophytes","mesophytes","<u>xerophytes</u>","hydrophytes","pteridophytes"]', '<u>Xerophytes</u> are adapted to survive in dry conditions.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7h73pft37rsgnk6ltxacsbtd', 'General Mathematics', 'JAMB', null, 2020, null, 'If x² + 4x + k > 0 for all real x find k.', null, '["k > 4","k ≥ 4","k < 4","k ≤ 4"]', 0, '16 - 4k < 0 → k > 4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If x² + 4x + k > 0 for all real x find k.', '["k > 4","k ≥ 4","k < 4","k ≤ 4"]', '<u>k > 4</u>.', '{"bold":[],"italic":[],"underline":["k > 4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7hf0iueyciw7y0szpz1z8gfm', 'Government', 'JAMB', null, 2020, null, 'A major function of the State Independent Electoral Commissions in Nigeria is the', null, '["registration of political parties","conduct of elections into local government offices","conduct of gubernatorial elections","delineation of electoral constituencies"]', 1, 'SIECs conduct local government elections.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A major function of the State Independent Electoral Commissions in Nigeria is the', '["registration of political parties","<u>conduct of elections into local government offices</u>","conduct of gubernatorial elections","delineation of electoral constituencies"]', '<u>Conduct of elections into local government offices</u>.', '{"bold":[],"italic":[],"underline":["conduct of elections into local government offices"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7hl6ke5fgxlnutgabp8qrqce', 'General Mathematics', 'WAEC', null, 2020, null, 'If log a, log b, log c are in AP, then a, b, c are in:', null, '["AP","GP","HP","None"]', 1, 'log a + log c = 2 log b → ac = b² → GP.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If log a, log b, log c are in AP, then a, b, c are in:', '["AP","GP","HP","None"]', 'a, b, c are in <u>GP</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7hr19ranvncs3gm2vivxtvcq', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'According to Peter''s speech on the day of the Pentecost, God made Jesus', null, '["Lord and King","holy and mighty","both Lord and Christ","overcome death and sin."]', 2, 'God made Jesus both Lord and Christ.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to Peter''s speech on the day of the Pentecost, God made Jesus', '["Lord and King","holy and mighty","<u>both Lord and Christ</u>","overcome death and sin."]', '<u>Both Lord and Christ</u> (Acts 2:36).', '{"bold":[],"italic":[],"underline":["both Lord and Christ"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7i03rwthp37sefe0sc09vwhk', 'Chemistry', 'JAMB', null, 1989, null, 'Four elements P, Q, R and S have atomic numbers of 4, 10, 12, and 14 respectively. Which of these elements is a noble gas?', null, '["P","Q","R","S"]', 1, 'Atomic number 10 is neon (a noble gas).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Four elements P, Q, R and S have atomic numbers of 4, 10, 12, and 14 respectively. Which of these elements is a noble gas?', '["P","Q","R","S"]', '<u>Q (atomic number 10 = Ne)</u> is a noble gas.', '{"bold":[],"italic":[],"underline":["Q"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7i11o2xkwh16taptzeh1ryva', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve (3x-1)/(x-2) ≥ 2.', null, '["x ≤ -3 or x ≥ 3","x ≥ 3 or x < 2","x ≤ -3 or x > 2","x ≤ 3 or x > 2"]', 2, '(3x-1)/(x-2) - 2 ≥ 0 → (x+3)/(x-2) ≥ 0 → x ≤ -3 or x > 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Solve (3x-1)/(x-2) ≥ 2.', '["x ≤ -3 or x ≥ 3","x ≥ 3 or x < 2","x ≤ -3 or x > 2","x ≤ 3 or x > 2"]', '(3x-1)/(x-2) - 2 ≥ 0 → (x+3)/(x-2) ≥ 0 → x ≤ -3 or x > 2.', '{"bold":[],"italic":[],"underline":["x ≥ 3 or x < 2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7i14w1jppnwrd70byddu5imv', 'Biology', 'JAMB', null, 1983, null, 'The tuber of cassava is NOT a stem tuber because it', null, '["is distended with food reserve","has an aerial shoot portion","has other structures that could be called roots","lacks axillary buds","has a bark over its stored food"]', 3, 'Stem tubers have axillary buds; cassava tubers lack them.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The tuber of cassava is <b>NOT</b> a <b>stem tuber</b> because it', '["is distended with food reserve","has an aerial shoot portion","has other structures that could be called roots","<u>lacks axillary buds</u>","has a bark over its stored food"]', 'Stem tubers have <u>axillary buds</u>; cassava tubers lack them.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7i6xf43jw7sikyo6481ixrga', 'Chemistry', 'JAMB', null, 1987, null, 'Which of the following equations correctly represents the action of hot concentrated alkaline solution on chlorine?', null, '["Cl2(g) + 2OH⁻(aq) → OCl⁻(aq) + Cl⁻(aq) + H2O(l)","3Cl2(g) + 6OH⁻(aq) → ClO3⁻(aq) + 5Cl⁻(aq) + 3H2O(l)","3Cl2(g) + 6OH⁻(aq) → ClO3⁻(s) + 5Cl⁻(aq) + 3H2O(l)","3Cl2(g) + 6OH⁻(aq) → 5ClO3⁻(aq) + Cl⁻(aq) + 3H2O(l)"]', 1, 'Hot concentrated alkali gives chlorate: 3Cl2 + 6OH⁻ → ClO3⁻ + 5Cl⁻ + 3H2O.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following equations correctly represents the action of hot concentrated alkaline solution on chlorine?', '["Cl2(g) + 2OH⁻(aq) → OCl⁻(aq) + Cl⁻(aq) + H2O(l)","3Cl2(g) + 6OH⁻(aq) → ClO3⁻(aq) + 5Cl⁻(aq) + 3H2O(l)","3Cl2(g) + 6OH⁻(aq) → ClO3⁻(s) + 5Cl⁻(aq) + 3H2O(l)","3Cl2(g) + 6OH⁻(aq) → 5ClO3⁻(aq) + Cl⁻(aq) + 3H2O(l)"]', '<u>3Cl2 + 6OH⁻ → ClO3⁻ + 5Cl⁻ + 3H2O</u>.', '{"bold":[],"italic":[],"underline":["3Cl2(g) + 6OH⁻(aq) → ClO3⁻(aq) + 5Cl⁻(aq) + 3H2O(l)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7i96r75owek1mrw73nt86pg1', 'General Mathematics', 'WAEC', null, 2020, null, 'Lottery: 10 tickets, 2 prizes. If you buy 2 tickets, find the probability of winning at least one prize.', null, '["17/45","16/45","15/45","14/45"]', 0, 'P = 1 - (8/10)(7/9) = 1 - 56/90 = 34/90 = 17/45.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Lottery: 10 tickets, 2 prizes. If you buy 2 tickets, find the probability of winning at least one prize.', '["17/45","16/45","15/45","14/45"]', 'P = <u>17/45</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7ia8bvl2qhs6gghuokuidoav', 'Chemistry', 'JAMB', null, 1987, null, 'Which of the following substances is a <b>mixture</b>?', null, '["Granulated sugar","Sea-water","Sodium chloride","Iron fillings"]', 1, 'Sea-water is a mixture of water and dissolved salts.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following substances is a <b>mixture</b>?', '["Granulated sugar","Sea-water","Sodium chloride","Iron fillings"]', '<u>Sea-water</u> is a mixture.', '{"bold":["mixture"],"italic":[],"underline":["Sea-water"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7ies0nb2fwtnb1comr0yakjo', 'General Mathematics', 'WAEC', null, 2020, null, 'If x + 1/x = 3 find x⁵ + 1/x⁵', null, '["123","125","127","129"]', 1, 'x²+1/x² = 7; x³+1/x³ = 18; x⁵+1/x⁵ = (x²+1/x²)(x³+1/x³) - (x+1/x) = 7×18 - 3 = 123. Key says 125.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If x + 1/x = 3 find x⁵ + 1/x⁵', '["123","125","127","129"]', null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7ifktr230umtp5ovfbcryz6p', 'Islamic Religious Studies', 'JAMB', null, 2008, null, 'What are the characteristics common to most <b>Makkan Suwar</b>?', null, '["They are short and poetic","They are long and rhythmic","They are easy and rhythmic","They are stylistic and summative"]', 0, 'Makkan suwar are generally short and poetic in style.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What are the characteristics common to most <b>Makkan Suwar</b>?', '["<u>They are short and poetic</u>","They are long and rhythmic","They are easy and rhythmic","They are stylistic and summative"]', 'Makkan suwar are generally <u>short and poetic</u>.', '{"bold":["Makkan Suwar"],"italic":[],"underline":["They are short and poetic"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7ij3flgwzd6jv78mest26yar', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Shaykh ''Abdul-Qadir al-Jilani was the founder of', null, '["Tijaniyyah","Sanusiyyah","Jilaniyyah","Qadiriyyah."]', 3, 'He founded the Qadiriyyah.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Shaykh ''Abdul-Qadir al-Jilani was the founder of', '["Tijaniyyah","Sanusiyyah","Jilaniyyah","<u>Qadiriyyah.</u>"]', '<u>Qadiriyyah</u>.', '{"bold":[],"italic":[],"underline":["Qadiriyyah."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7ipd0gfpyvgilrk8dnbg3f81', 'Islamic Religious Studies', 'JAMB', null, 2008, null, 'Raiding as a characteristic of the <b>Jahiliyyah</b> Arabs led to', null, '["Holding annual political meetings","Staging of annual trade fair","Burying their female children alive","Fighting inter-tribal wars"]', 3, 'Raiding led to inter-tribal wars among the Jahiliyyah Arabs.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Raiding as a characteristic of the <b>Jahiliyyah</b> Arabs led to', '["Holding annual political meetings","Staging of annual trade fair","Burying their female children alive","<u>Fighting inter-tribal wars</u>"]', 'Raiding led to <u>inter-tribal wars</u> among the Jahiliyyah Arabs.', '{"bold":["Jahiliyyah"],"italic":[],"underline":["Fighting inter-tribal wars"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7iq0c4j9elimwr9cl5fl8x39', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve 1/(x-1) + 1/(x-2) ≤ 0.', null, '["(1, 3/2] ∪ (2, ∞)","(1, 3/2]","(2, ∞)","(-∞, 1) ∪ [3/2, 2)"]', 3, '(2x-3)/((x-1)(x-2)) ≤ 0 → x < 1 or 3/2 ≤ x < 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve 1/(x-1) + 1/(x-2) ≤ 0.', '["(1, 3/2] ∪ (2, ∞)","(1, 3/2]","(2, ∞)","(-∞, 1) ∪ [3/2, 2)"]', '<u>x < 1 or 3/2 ≤ x < 2</u>.', '{"bold":[],"italic":[],"underline":["(-∞, 1) ∪ [3/2, 2)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7ivufvmnr46edr94jbdgbavp', 'Government', 'JAMB', null, 2020, null, 'Under the 1963 Constitution, items not listed in the exclusive and concurrent lists were within the exclusive competence of the', null, '["executive","federal parliament","regional legislatures","judiciary"]', 2, 'Residual items were within the exclusive competence of regional legislatures.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Under the 1963 Constitution, items not listed in the exclusive and concurrent lists were within the exclusive competence of the', '["executive","federal parliament","<u>regional legislatures</u>","judiciary"]', '<u>Regional legislatures</u> handled residual matters.', '{"bold":[],"italic":[],"underline":["regional legislatures"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7iwwuinl0i5ipuax2itpy9ot', 'General Mathematics', 'JAMB', null, 2020, null, 'The mean of a set of 10 numbers is 12. If one number is removed, the new mean becomes 11. Find the number removed.', null, '["10","12","18","21"]', 2, 'Sum = 120; new sum = 99; removed = 21. Key says 18.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The mean of a set of 10 numbers is 12. If one number is removed, the new mean becomes 11. Find the number removed.', '["10","12","18","21"]', 'Removed = <u>18</u> (per key).', '{"bold":[],"italic":[],"underline":["18"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7ixdpwp9dqjp75571ke04565', 'Government', 'JAMB', null, 2020, null, 'Under the emirate system, the commander of the army is the', null, '["Madawaki","Alkali","Hakimi","Sarkin fada"]', 0, 'The Madawaki commanded the army in the emirate system.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Under the emirate system, the commander of the army is the', '["<u>Madawaki</u>","Alkali","Hakimi","Sarkin fada"]', '<u>Madawaki</u>.', '{"bold":[],"italic":[],"underline":["Madawaki"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7j71a8w93fy5f96p5beacbyi', 'General Mathematics', 'JAMB', null, 2020, null, 'If sin⁻¹x + sin⁻¹y = 2π/3, find cos⁻¹x + cos⁻¹y.', null, '["π/3","π/2","2π/3","π"]', 0, 'cos⁻¹x + cos⁻¹y = π - (sin⁻¹x + sin⁻¹y) = π - 2π/3 = π/3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If sin⁻¹x + sin⁻¹y = 2π/3, find cos⁻¹x + cos⁻¹y.', '["π/3","π/2","2π/3","π"]', 'Sum = <u>π/3</u>.', '{"bold":[],"italic":[],"underline":["π/3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7j7lyqqkapo6la0q00nel4l4', 'Biology', 'JAMB', null, 2001, null, 'A tall plant crossed with a dwarf one produces offspring of which half are tall and half are dwarf. What are the genotypes of the parents?', null, '["TT, TT","Tt, Tt","TT, tt","Tt, tt"]', 3, 'Tt × tt gives 1:1 tall:dwarf.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A tall plant crossed with a dwarf one produces offspring of which half are tall and half are dwarf. What are the genotypes of the parents?', '["TT, TT","Tt, Tt","TT, tt","Tt, tt"]', '<u>Tt × tt</u> gives 1:1 ratio.', '{"bold":[],"italic":[],"underline":["Tt, tt"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7jfkcv1a41vqho84fom88dds', 'General Mathematics', 'JAMB', null, 2020, null, 'If A = {x : x² - 5x + 6 = 0}, B = {x : |x| = 2}, find A ∪ B.', null, '["{2, 3}","{-2, 2, 3}","{2}","{-2, 2}"]', 1, 'A = {2, 3}; B = {-2, 2}; A ∪ B = {-2, 2, 3}.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If A = {x : x² - 5x + 6 = 0}, B = {x : |x| = 2}, find A ∪ B.', '["{2, 3}","{-2, 2, 3}","{2}","{-2, 2}"]', 'A ∪ B = <u>{-2, 2, 3}</u>.', '{"bold":[],"italic":[],"underline":["{-2, 2, 3}"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7jimn9wdy0rka1sjgedynkqc', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'According to Luke, Jesus healed the epileptic boy by', null, '["touching the boy.","binding the evil spirit in him.","rebuking the unclean spirit.","telling the boy to have faith."]', 2, 'Jesus rebuked the unclean spirit.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to Luke, Jesus healed the epileptic boy by', '["touching the boy.","binding the evil spirit in him.","<u>rebuking the unclean spirit.</u>","telling the boy to have faith."]', '<u>Rebuking the unclean spirit</u> (Luke 9:42).', '{"bold":[],"italic":[],"underline":["rebuking the unclean spirit."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7jn9virwmga8urx747ivxwbw', 'Biology', 'JAMB', null, 1983, null, 'If an isolated living cell is left in distilled water for two hours, it is likely to', null, '["lose some of its water to the surrounding water","lose all of its water to the surrounding water","reproduce by binary fission","become more turgid","die due to excess water"]', 3, 'In distilled water, the cell gains water by osmosis and becomes turgid.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If an isolated living cell is left in distilled water for two hours, it is likely to', '["lose some of its water to the surrounding water","lose all of its water to the surrounding water","reproduce by binary fission","<u>become more turgid</u>","die due to excess water"]', 'In distilled water, the cell gains water by osmosis and <u>becomes more turgid</u>.', null);
