insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7jyo0lk3tsh928pa1e7pkrny', 'Chemistry', 'JAMB', null, 1999, null, 'Which of the following metals is <b>passive</b> to concentrated trioxonitrate(V) acid?', null, '["iron","tin","copper","zinc"]', 0, 'Iron is passivated by concentrated HNO3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following metals is <b>passive</b> to concentrated trioxonitrate(V) acid?', '["iron","tin","copper","zinc"]', '<u>Iron is passivated</u> by concentrated HNO3.', '{"bold":["passive"],"italic":[],"underline":["iron"],"fillBlanks":[]}');
