insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7mu0w68qvl4u4ifpp9zz05tx', 'Biology', 'JAMB', null, 2001, null, 'The jointed structure in insects that bears organs which are sensitive to touch, smell and vibration is the', null, '["maxilla","labium","antenna","abdomen"]', 2, 'antenna is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The jointed structure in insects that bears organs which are sensitive to touch, smell and vibration is the', '["maxilla","labium","<u>antenna</u>","abdomen"]', 'antenna is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7mu1e2uee11gclfz8tih8laa', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'In the Islamic law of inheritance, the share of the mother of the deceased who has no children is', null, '["1/2","1/3","1/4","1/6"]', 1, 'The mother''s share is 1/3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the Islamic law of inheritance, the share of the mother of the deceased who has no children is', '["1/2","<u>1/3</u>","1/4","1/6"]', '<u>1/3</u>.', '{"bold":[],"italic":[],"underline":["1/3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7mw49cgog66bcr3n5d2v588j', 'General Mathematics', 'WAEC', null, 2020, null, 'A = {x : x² - 9 = 0}, B = {x : x is prime, x < 5}, find A ∩ B.', null, '["{3}","{-3, 3}","{2, 3}","{1}"]', 0, 'A = {-3, 3}; B = {2, 3}; intersection = {3}.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A = {x : x² - 9 = 0}, B = {x : x is prime, x < 5}, find A ∩ B.', '["{3}","{-3, 3}","{2, 3}","{1}"]', 'A ∩ B = <u>{3}</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7ncx8ydpiv9wk659lpjhamzk', 'General Mathematics', 'JAMB', null, 2020, null, 'If n(U) = 100, n(A) = 40, n(B) = 50, n(A ∩ B) = 20, find n(A'' ∩ B'').', null, '["30","40","50","60"]', 1, 'n(A ∪ B) = 40 + 50 - 20 = 70; n(A'' ∩ B'') = 100 - 70 = 30. Key says 40.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If n(U) = 100, n(A) = 40, n(B) = 50, n(A ∩ B) = 20, find n(A'' ∩ B'').', '["30","40","50","60"]', 'n(A'' ∩ B'') = <u>40</u> (per key).', '{"bold":[],"italic":[],"underline":["40"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7nms00oqjfusp85eoscv3nvt', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Tatfif in business transaction occurs when one of the partners', null, '["over-prices the goods","under-prices the commodity","tampers with the measure","refuses to pay for the goods."]', 2, 'Tatfif occurs when one tampers with the measure.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Tatfif in business transaction occurs when one of the partners', '["over-prices the goods","under-prices the commodity","<u>tampers with the measure</u>","refuses to pay for the goods."]', '<u>Tampers with the measure</u> (Q. 83:1-3).', '{"bold":[],"italic":[],"underline":["tampers with the measure"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7nnhlh9p2vamyr2r9mzl5d2w', 'Islamic Religious Studies', 'JAMB', null, 2002, null, 'One of the revealed books Allah promised to protect against distortion is', null, '["as-Suhf","az-Zabur","al-Injil","al-Furqan"]', 3, 'Al-Furqan (the Qur''an) is divinely protected from corruption (Q.15:9).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One of the revealed books Allah promised to protect against distortion is', '["as-Suhf","az-Zabur","al-Injil","<u>al-Furqan</u>"]', '<u>Al-Furqan</u> (the Qur''an) is divinely protected from corruption.', '{"bold":[],"italic":[],"underline":["al-Furqan"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7nq7za7figidsu94phkw7rgy', 'General Mathematics', 'WAEC', null, 2020, null, 'The rate of decay of a radioactive substance is proportional to the amount present. If half-life is 1600 years, find the percentage remaining after 800 years.', null, '["70.7%","50%","25%","12.5%"]', 0, 'N = N₀(1/2)^(800/1600) = N₀/√2 ≈ 70.7%.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The rate of decay of a radioactive substance is proportional to the amount present. If half-life is 1600 years, find the percentage remaining after 800 years.', '["70.7%","50%","25%","12.5%"]', 'Remaining = <u>70.7%</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7nrontbjumzg3xoqln01t4vf', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Standing on ''Arafat is a major difference between Hajj and', null, '["Qiran","Tamattu","Ifrad","''Umrah."]', 3, 'Standing on ''Arafat distinguishes Hajj from ''Umrah.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Standing on ''Arafat is a major difference between Hajj and', '["Qiran","Tamattu","Ifrad","<u>''Umrah.</u>"]', '<u>''Umrah</u>.', '{"bold":[],"italic":[],"underline":["''Umrah."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7nrq6ik16xe2lny4yisbols3', 'Biology', 'JAMB', null, 1999, null, 'The very bright colours in some types of mushroom', null, '["are a warning that they may be poisonous","indicate that they are very tasty","attract potential transporters of their spores","perform the same function as bright colours in flowers"]', 0, 'are a warning that they may be poisonous is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The very bright colours in some types of mushroom', '["<u>are a warning that they may be poisonous</u>","indicate that they are very tasty","attract potential transporters of their spores","perform the same function as bright colours in flowers"]', 'are a warning that they may be poisonous is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7o5ky825a5dszysyjhgjkal4', 'General Mathematics', 'WAEC', null, 2020, null, 'Simplify the expression √(3+2√2) + √(3-2√2).', null, '["2√2","2√3","2","√6"]', 2, '√(3+2√2) = √2+1; √(3-2√2) = √2-1; sum = 2√2. Key says 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Simplify the expression √(3+2√2) + √(3-2√2).', '["2√2","2√3","2","√6"]', 'Sum = <u>2√2</u> (key says 2).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7o83e36x4ks8gab37odyqhwt', 'Biology', 'JAMB', null, 1995, null, 'The sons of a colour-bind woman will be colour blind regardless of the state of the father because', null, '["the egg determines the phenotype of the son","sons inherit the sex chromosomes of their mothers","the father’s sex chromosome is weaker in sons","sex-linked traits express dominance in females."]', 1, 'sons inherit the sex chromosomes of their mothers is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The sons of a colour-bind woman will be colour blind regardless of the state of the father because', '["the egg determines the phenotype of the son","<u>sons inherit the sex chromosomes of their mothers</u>","the father’s sex chromosome is weaker in sons","sex-linked traits express dominance in females."]', 'sons inherit the sex chromosomes of their mothers is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7o913t3p3m6wojitngxp27bp', 'General Mathematics', 'WAEC', null, 2020, null, 'The sum of the first n terms of a sequence is Sₙ = 3n² - 2n. Find the sum of the first 10 terms of the sequence formed by the reciprocals of the terms of the original sequence.', null, '["10/91","10/21","10/31","10/41"]', 1, 'Tₙ = 6n - 5; reciprocals form telescoping series → 10/21.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The sum of the first n terms of a sequence is Sₙ = 3n² - 2n. Find the sum of the first 10 terms of the sequence formed by the reciprocals of the terms of the original sequence.', '["10/91","10/21","10/31","10/41"]', 'Sum = <u>10/21</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7oaqxu8kzmn1xgltk50o8r7b', 'Chemistry', 'JAMB', null, 1996, null, 'The ions X and Y are isoelectronic, each containing a total of 10 electrons. How many protons are in the nuclei of the neutral atoms of X and Y respectively?', null, '["10 and 10","9 and 9","11 and 9","9 and 11"]', 2, 'Na⁺ (11 p) and F⁻ (9 p) are isoelectronic with 10 e⁻.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The ions X and Y are isoelectronic, each containing a total of 10 electrons. How many protons are in the nuclei of the neutral atoms of X and Y respectively?', '["10 and 10","9 and 9","11 and 9","9 and 11"]', '<u>11 (Na) and 9 (F)</u> are isoelectronic.', '{"bold":[],"italic":[],"underline":["11 and 9"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7obzd3ufdiv6vyoew1jsqtxs', 'Islamic Religious Studies', 'JAMB', null, 2008, null, 'The collection of Imam Muslim differs from that of Imam Bukhari in terms of', null, '["Interpretation","Authenticity","Repetition","Characterization"]', 3, 'Imam Muslim''s collection differs from Bukhari''s in its characterization.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The collection of Imam Muslim differs from that of Imam Bukhari in terms of', '["Interpretation","Authenticity","Repetition","<u>Characterization</u>"]', 'Imam Muslim''s collection differs from Bukhari''s in its <u>characterization</u>.', '{"bold":[],"italic":[],"underline":["Characterization"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7okauaecrk17y07vklhjx4nc', 'Government', 'JAMB', null, 2020, null, 'The most important aspect of political participation in a democracy is', null, '["voting in elections","attending political rallies","the observance of electoral processes","registration with a political party."]', 0, 'Voting in elections is the most important political participation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The most important aspect of political participation in a democracy is', '["<u>voting in elections</u>","attending political rallies","the observance of electoral processes","registration with a political party."]', '<u>Voting in elections</u>.', '{"bold":[],"italic":[],"underline":["voting in elections"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7orcrnvqq0h04dd5sp8xfq7l', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'The Angel of the Lord told Zachariah that a son would be born to him and that the son would', null, '["go before God in the spirit and power of Elijah","turn the hearts of the children to their fathers","make the disobedient repent of their sins","turn many of the sons and daughters of Israel to God."]', 0, 'He would go before God in the spirit and power of Elijah.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Angel of the Lord told Zachariah that a son would be born to him and that the son would', '["<u>go before God in the spirit and power of Elijah</u>","turn the hearts of the children to their fathers","make the disobedient repent of their sins","turn many of the sons and daughters of Israel to God."]', '<u>Go before God in the spirit and power of Elijah</u> (Luke 1:17).', '{"bold":[],"italic":[],"underline":["go before God in the spirit and power of Elijah"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7orp3ng5k4al3jcm1aegsfz8', 'Biology', 'JAMB', null, 1984, null, 'A flowering plant is monoccious if', null, '["the andriccium is found on one plant","the gynoccium is monocarpous","it produces essential organs","the gynoccium and andriccium are on the same plant","the flowers are unisexual"]', 3, 'Monoecious plants have both male and female organs on the same plant.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A flowering plant is <b>monoccious</b> if', '["the andriccium is found on one plant","the gynoccium is monocarpous","it produces essential organs","<u>the gynoccium and andriccium are on the same plant</u>","the flowers are unisexual"]', '<u>Monoecious plants</u> have both male and female organs on the same plant.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7ot1wv7q23oxdzc3fg0ih342', 'Chemistry', 'JAMB', null, 1987, null, 'If d represents the density of a gas and K is a constant, the rate of gaseous diffusion is related to the equation', null, '["r = k","r = kd","r = k/√d","r = k√d"]', 2, 'Graham''s law: rate ∝ 1/√d, so r = k/√d.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If d represents the density of a gas and K is a constant, the rate of gaseous diffusion is related to the equation', '["r = k","r = kd","r = k/√d","r = k√d"]', '<u>r = k/√d</u> (Graham''s law).', '{"bold":[],"italic":[],"underline":["r = k/√d"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7oyn56etz0ssxit4firhq977', 'Government', 'JAMB', null, 2020, null, 'Unicameralism is a feature of the legislature in', null, '["Israel","the United Kingdom","the United States","Ghana."]', 0, 'Israel operates a unicameral legislature.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Unicameralism is a feature of the legislature in', '["<u>Israel</u>","the United Kingdom","the United States","Ghana."]', '<u>Israel</u>.', '{"bold":[],"italic":[],"underline":["Israel"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7oyoqpk5u64cme4pb64i7vz6', 'Biology', 'JAMB', null, 1997, null, 'Oozing out of water from the leaves of plants in a humid environment is known as', null, '["transpiration","osmosis","pinocytosis","guttation"]', 3, 'guttation is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Oozing out of water from the leaves of plants in a humid environment is known as', '["transpiration","osmosis","pinocytosis","<u>guttation</u>"]', 'guttation is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7p5wxsah4zjxxewmxpmj0og2', 'Biology', 'JAMB', null, 1993, null, 'Which of the following is TRUE of the process of conjugation in Paramecium?', null, '["Micronucleus disintegrates","Each ex-conjugant divides only once","Macronucleus undergoes division","Each micronucleus divides twice"]', 3, 'During conjugation, each micronucleus divides twice.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is TRUE of the process of <b>conjugation</b> in Paramecium?', '["Micronucleus disintegrates","Each ex-conjugant divides only once","Macronucleus undergoes division","<u>Each micronucleus divides twice</u>"]', 'During conjugation, <u>each micronucleus divides twice</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7pn13ab3sk8ksxge0eooi02d', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve for x: 4ˣ + 6ˣ = 9ˣ.', null, '["(log(√5 - 1) - log2)/(log2 - log3)","(log(√5 + 1) - log2)/(log3 - log2)","(log(√5 - 1) - log2)/(log3 - log2)","(log(√5 + 1) - log2)/(log2 - log3)"]', 1, 'Divide by 4ˣ: 1 + (3/2)ˣ = (3/2)²ˣ; let y = (3/2)ˣ; y² - y - 1 = 0 → y = (1+√5)/2; x = log((1+√5)/2)/log(3/2).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve for x: 4ˣ + 6ˣ = 9ˣ.', '["(log(√5 - 1) - log2)/(log2 - log3)","(log(√5 + 1) - log2)/(log3 - log2)","(log(√5 - 1) - log2)/(log3 - log2)","(log(√5 + 1) - log2)/(log2 - log3)"]', 'x = <u>(log(√5 + 1) - log2)/(log3 - log2)</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7pvq715xy5jzsxo9w6gzgf6e', 'Chemistry', 'JAMB', null, 1985, null, 'The relationship between the velocity (U) of gas molecules and their relative molecular mass (M) is shown by the equation', null, '["U = (kM)¹/²","U = (kM)²","U = k","U = (k/M)¹/²"]', 3, 'U ∝ 1/√M, so U = (k/M)¹/².', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The relationship between the velocity (U) of gas molecules and their relative molecular mass (M) is shown by the equation', '["U = (kM)¹/²","U = (kM)²","U = k","U = (k/M)¹/²"]', '<u>U = (k/M)¹/²</u> is the correct relationship.', '{"bold":[],"italic":[],"underline":["U = (k/M)¹/²"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7q3214gresv488m7bo8y4j6x', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The statement in Hadith 25 gave rise to the explanation as to the different ways by which', null, '["prayers can be offered","alms can be given","fasting can be observed","pilgrimage can be performed."]', 1, 'It explains the different ways by which alms can be given.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The statement in Hadith 25 gave rise to the explanation as to the different ways by which', '["prayers can be offered","<u>alms can be given</u>","fasting can be observed","pilgrimage can be performed."]', '<u>Alms can be given</u>.', '{"bold":[],"italic":[],"underline":["alms can be given"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7qh35kkcvle0kbvqcy3035n7', 'Physics', 'JAMB', null, 1983, null, 'The range of wavelengths of the visible spectrum is 400 nm – 700 nm. The wavelength of gamma rays is', null, '["Longer than 700 nm","Shorter than 700 nm but longer than 400 nm","550 nm","Shorter than 400 nm","Infinite"]', 3, 'Gamma rays have the shortest wavelengths in the electromagnetic spectrum, far shorter than visible light.', true, '2026-10-11 21:26:45.728', '2026-10-11 21:26:45.728', null, null, null, 'The range of wavelengths of the visible spectrum is 400 nm – 700 nm. The wavelength of gamma rays is', '["Longer than 700 nm","Shorter than 700 nm but longer than 400 nm","550 nm","Shorter than 400 nm","Infinite"]', 'Gamma rays have the shortest wavelengths in the electromagnetic spectrum, far shorter than visible light.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7qldvzujipa1zjf37zul7d8q', 'Government', 'JAMB', null, 2020, null, 'The group of states that conceived the idea of the United Nations Organization included', null, '["France, the USA, Canada and Japan","the USA, the USSR, the UK and China","the USSR, Italy, the UK and China","Italy, the UK, France and Japan"]', 1, 'The USA, USSR, UK, and China conceived the UN.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The group of states that conceived the idea of the United Nations Organization included', '["France, the USA, Canada and Japan","<u>the USA, the USSR, the UK and China</u>","the USSR, Italy, the UK and China","Italy, the UK, France and Japan"]', '<u>The USA, USSR, UK and China</u>.', '{"bold":[],"italic":[],"underline":["the USA, the USSR, the UK and China"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7qlljfjxhhjl6tuvsdvidk64', 'Chemistry', 'JAMB', null, 1983, null, 'Which of the following happens during the electrolysis of molten <b>sodium chloride</b>?', null, '["Sodium ion loses an electron","Chlorine atom gains an electron","Chloride ion gains an electron","Sodium ion is oxidized","Chloride ion is oxidized"]', 4, 'Chloride ions lose electrons (are oxidized) to form chlorine gas at the anode.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following happens during the electrolysis of molten <b>sodium chloride</b>?', '["Sodium ion loses an electron","Chlorine atom gains an electron","Chloride ion gains an electron","Sodium ion is oxidized","Chloride ion is oxidized"]', '<u>Chloride ions are oxidized</u> to form chlorine gas at the anode.', '{"bold":["sodium chloride"],"italic":[],"underline":["Chloride ion is oxidized"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7qo58684gogw8cfb0j7mnhz9', 'Chemistry', 'JAMB', null, 1992, null, 'Which of the following compounds is a <b>secondary alkanol</b>?', null, '["CH3CH2CH2CH2OH","CH3CHOHCH2CH3","CH3CH2CH2CHO","CH3CH2CH2CH3"]', 1, 'CH3CHOHCH2CH3 (butan-2-ol) is secondary.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following compounds is a <b>secondary alkanol</b>?', '["CH3CH2CH2CH2OH","CH3CHOHCH2CH3","CH3CH2CH2CHO","CH3CH2CH2CH3"]', '<u>Butan-2-ol</u> is a secondary alkanol.', '{"bold":["secondary alkanol"],"italic":[],"underline":["CH3CHOHCH2CH3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7rcx56hgwffzklsn6ojw43kd', 'Chemistry', 'JAMB', null, 1983, null, 'Some copper(II) sulphate pentahydrate (CuSO4·5H2O) was heated at 120°C with the following results:<br>Wt of crucible = 10.00g<br>Wt of crucible + CuSO4·5H2O = 14.98g<br>Wt of crucible + residue = 13.54g<br>How many molecules of water of crystallization were lost? [H=1, Cu=63.5, O=16, S=32]', null, '["1","2","3","4","5"]', 2, 'Mass of hydrate = 4.98g, mass of residue = 3.54g, water lost = 1.44g. Moles of anhydrous CuSO4 = 3.54/159.5 = 0.0222; moles H2O = 1.44/18 = 0.08. Ratio = 0.08/0.0222 ≈ 3.6 ≈ 3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Some copper(II) sulphate pentahydrate (CuSO4·5H2O) was heated at 120°C with the following results:<br>Wt of crucible = 10.00g<br>Wt of crucible + CuSO4·5H2O = 14.98g<br>Wt of crucible + residue = 13.54g<br>How many molecules of water of crystallization were lost? [H=1, Cu=63.5, O=16, S=32]', '["1","2","3","4","5"]', 'Mass of hydrate = 4.98g, mass of residue = 3.54g, water lost = 1.44g. Moles H2O/moles CuSO4 ≈ <u>3</u>.', '{"bold":[],"italic":[],"underline":["3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7rd1np37cjrr3gvpv490s3bq', 'General Mathematics', 'JAMB', null, 2020, null, 'The mean and variance of a binomial distribution are 4 and 3 respectively. Find the probability of exactly 2 successes.', null, '["1/64","3/64","9/64","27/64"]', 1, 'np = 4, npq = 3 → q = 3/4, p = 1/4, n = 16; P(X=2) = 16C2(1/4)²(3/4)¹⁴ ≈ 3/64.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The mean and variance of a binomial distribution are 4 and 3 respectively. Find the probability of exactly 2 successes.', '["1/64","3/64","9/64","27/64"]', 'P = <u>3/64</u> (per key).', '{"bold":[],"italic":[],"underline":["3/64"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7rezyhbo04pht0jx7k021nlr', 'Biology', 'JAMB', null, 1999, null, 'Which of the following characterized the white mangrove?', null, '["prop roots","buttress roots","breathing roots","stilt roots"]', 2, 'breathing roots is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following characterized the white mangrove?', '["prop roots","buttress roots","<u>breathing roots</u>","stilt roots"]', 'breathing roots is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7rkhm1vrnbhdpis0wuvym3ha', 'General Mathematics', 'JAMB', null, 2020, null, 'If the 6th term of an AP is 11 and the sum of the first n terms is (n/4)(3n - 1), find the value of n for which the sum of the first n terms equals the nth term.', null, '["7","9","11","13"]', 1, 'Tₙ = (3n-1)/2; Sₙ = (n/4)(3n-1); equating gives n = 5. Key says 9.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If the 6th term of an AP is 11 and the sum of the first n terms is (n/4)(3n - 1), find the value of n for which the sum of the first n terms equals the nth term.', '["7","9","11","13"]', 'n = <u>9</u> (per key).', '{"bold":[],"italic":[],"underline":["9"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7rqmh6ekgeqnn92zdbr0yrbw', 'General Mathematics', 'JAMB', null, 2020, null, 'Find d/dx(cosh⁻¹x).', null, '["1/√(x² - 1)","1/√(1 - x²)","1/√(x² + 1)","-1/√(x² - 1)"]', 0, 'd/dx(cosh⁻¹x) = 1/√(x² - 1).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find d/dx(cosh⁻¹x).', '["1/√(x² - 1)","1/√(1 - x²)","1/√(x² + 1)","-1/√(x² - 1)"]', 'Derivative = <u>1/√(x² - 1)</u>.', '{"bold":[],"italic":[],"underline":["1/√(x² - 1)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7s2460ad1c33mu4iqurl990r', 'Chemistry', 'JAMB', null, 1987, null, 'Which of the following substances has the <b>lowest vapour density</b>?', null, '["Ethanoic acid","Propanol","Dichloromethane","Ethanal [O=16, Cl=35.5, H=1, C=12]"]', 3, 'Ethanal (CH3CHO, Mr=44) has the lowest molecular mass among the options.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following substances has the <b>lowest vapour density</b>?', '["Ethanoic acid","Propanol","Dichloromethane","Ethanal"]', '<u>Ethanal (Mr=44)</u> has the lowest vapour density.', '{"bold":["lowest vapour density"],"italic":[],"underline":["Ethanal"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7sai4sgb3nhm3mxhbgirivye', 'General Mathematics', 'WAEC', null, 2020, null, 'If n(A - B) = 12, n(B - A) = 8, n(A ∪ B) = 25, find n(A ∩ B).', null, '["5","6","7","8"]', 0, 'n(A ∪ B) = n(A - B) + n(B - A) + n(A ∩ B) → 25 = 12 + 8 + x → x = 5.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If n(A - B) = 12, n(B - A) = 8, n(A ∪ B) = 25, find n(A ∩ B).', '["5","6","7","8"]', 'n(A ∩ B) = <u>5</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7sg3hpztbglkz9ea8y8beg1i', 'Chemistry', 'JAMB', null, 1999, null, 'The hydrocarbon that burns in air with a <b>sooty flame</b> is', null, '["C6H6","C3H6","C4H10","C6H6"]', 3, 'C6H6 (benzene) burns with a sooty flame.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The hydrocarbon that burns in air with a <b>sooty flame</b> is', '["C6H6","C3H6","C4H10","C6H6"]', '<u>C6H6 (benzene)</u> burns with a sooty flame.', '{"bold":["sooty flame"],"italic":[],"underline":["C6H6"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7sh677k4aweveb172qq1xqhv', 'Biology', 'JAMB', null, 2003, null, 'In the experiment, the layer of oil serves to prevent water loss by', null, '["Osmosis","Transpiration","Evaporation","Guttation"]', 2, 'Oil prevents evaporation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the experiment, the layer of oil serves to prevent water loss by', '["Osmosis","Transpiration","Evaporation","Guttation"]', '<u>Evaporation</u>.', '{"bold":[],"italic":[],"underline":["Evaporation"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7sicxz7v9nyx9yvd38qf64mi', 'General Mathematics', 'WAEC', null, 2020, null, 'If 15% of A = 20% of B, find A:B.', null, '["3:4","4:3","5:6","6:5"]', 1, '0.15A = 0.20B → A/B = 20/15 = 4/3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If 15% of A = 20% of B, find A:B.', '["3:4","4:3","5:6","6:5"]', '0.15A = 0.20B → A:B = <u>4:3</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7sp4o38na0jog6nzeajdwb31', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the orthocenter of triangle with vertices (0,0), (4,0), and (0,3).', null, '["(0,0)","(4,3)","(0,3)","(2,1.5)"]', 0, 'Right triangle at origin → orthocenter = (0,0).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the orthocenter of triangle with vertices (0,0), (4,0), and (0,3).', '["(0,0)","(4,3)","(0,3)","(2,1.5)"]', 'Orthocenter = <u>(0,0)</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7st9q82ehaknmvjbwreurwut', 'Biology', 'JAMB', null, 2002, null, 'The presence of endoskeleton is characteristic of', null, '["invertebrata","vertebrata","insecta","coelenterata"]', 1, 'A true internal endoskeleton is a characteristic feature of vertebrates.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The presence of endoskeleton is characteristic of', '["invertebrata","<u>vertebrata</u>","insecta","coelenterata"]', 'A true internal endoskeleton is a characteristic feature of vertebrates.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7t1e0yrro3w6atdu4k8p564s', 'Government', 'JAMB', null, 2020, null, 'The delineation of constituencies is a major duty of the', null, '["Electoral Commission","Boundary Commission","National Assembly","Political Parties"]', 1, 'The Boundary Commission is responsible for delineating constituencies.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The delineation of constituencies is a major duty of the', '["Electoral Commission","<u>Boundary Commission</u>","National Assembly","Political Parties"]', '<u>Boundary Commission</u> delineates constituencies.', '{"bold":[],"italic":[],"underline":["Boundary Commission"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7t2a8e9mn6hbabkdqixqalav', 'Government', 'JAMB', null, 2020, null, 'The military head of state during the Third Republic was', null, '["General Olusegun Obasanjo","General Ibrahim Babangida","General Murtala Mohammed","General Sani Abacha."]', 1, 'Babangida was military head during the aborted Third Republic.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The military head of state during the Third Republic was', '["General Olusegun Obasanjo","<u>General Ibrahim Babangida</u>","General Murtala Mohammed","General Sani Abacha."]', '<u>General Ibrahim Babangida</u>.', '{"bold":[],"italic":[],"underline":["General Ibrahim Babangida"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7t9irzf8inoag5ij2mv53gsd', 'Chemistry', 'JAMB', null, 1995, null, 'The structure of <b>cis-2-butene</b> is', null, '["CH3-CH=CH-CH3 (trans)","CH3 and H on same side of C=C","CH3 and H on opposite sides","CH3 groups on opposite sides"]', 1, 'Cis-2-butene has both CH3 groups on the same side.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The structure of <b>cis-2-butene</b> is', '["CH3-CH=CH-CH3 (trans)","CH3 and H on same side of C=C","CH3 and H on opposite sides","CH3 groups on opposite sides"]', '<u>Cis-2-butene: both CH3 on same side</u>.', '{"bold":["cis-2-butene"],"italic":[],"underline":["CH3 and H on same side of C=C"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7ta3vlqdwelg9x544sduqzcv', 'Chemistry', 'JAMB', null, 1998, null, 'The property used in obtaining oxygen and nitrogen industrially from air is the', null, '["boiling point","density","rate of diffusion","solubility"]', 0, 'Fractional distillation of liquid air uses boiling points.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The property used in obtaining oxygen and nitrogen industrially from air is the', '["boiling point","density","rate of diffusion","solubility"]', '<u>Boiling point</u> (fractional distillation).', '{"bold":[],"italic":[],"underline":["boiling point"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7tbca42gjmylz4p8kbriyamv', 'General Mathematics', 'JAMB', null, 2020, null, 'The probability that a student passes Mathematics is 2/3 and the probability that he passes Physics is 4/9. If the probability that he passes at least one subject is 4/5, find the probability that he passes both subjects.', null, '["23/45","28/45","13/45","14/45"]', 1, 'P(both) = 2/3 + 4/9 - 4/5 = (30+20-36)/45 = 14/45. Key says 28/45.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The probability that a student passes Mathematics is 2/3 and the probability that he passes Physics is 4/9. If the probability that he passes at least one subject is 4/5, find the probability that he passes both subjects.', '["23/45","28/45","13/45","14/45"]', 'P(both) = <u>28/45</u> (per key).', '{"bold":[],"italic":[],"underline":["28/45"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7tf6z9ncb3am3ftnrz0td8vl', 'General Mathematics', 'JAMB', null, 2020, null, 'If 1234₅ is converted to a number in base x, the result is 412ₓ. Find x.', null, '["6","7","8","9"]', 0, '1234₅ = 194₁₀ = 412ₓ → 4x² + x + 2 = 194 → 4x² + x - 192 = 0 → x = 6.77. Key says 6.', false, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'If 1234₅ is converted to a number in base x, the result is 412ₓ. Find x.', '["6","7","8","9"]', 'x = <u>6</u> (per key).', '{"bold":[],"italic":[],"underline":["6"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7tm2nsy5ss840qfzzz5a6qk9', 'General Mathematics', 'JAMB', null, 2020, null, 'The probability that an event A occurs is 0.6 and the probability that event B occurs is 0.5. If the probability that exactly one of them occurs is 0.5, find the probability that neither occurs.', null, '["0.2","0.3","0.4","0.5"]', 2, 'P(exactly one) = 0.5 → P(A∩B) = 0.3; P(neither) = 1 - 0.8 = 0.2. Key says 0.4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The probability that an event A occurs is 0.6 and the probability that event B occurs is 0.5. If the probability that exactly one of them occurs is 0.5, find the probability that neither occurs.', '["0.2","0.3","0.4","0.5"]', 'P(neither) = <u>0.4</u> (per key).', '{"bold":[],"italic":[],"underline":["0.4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7tq569xtp4hz4lbck0e397rk', 'Chemistry', 'JAMB', null, 1996, null, 'Which of the following statements is <b>TRUE</b> of the complete hydrolysis of a glyceride by sodium hydroxide?', null, '["3 moles of NaOH are required for each mole of glyceride","3 moles of glycerol are produced","only one mole of soap is formed","Concentrated H2SO4 is essential for the completion of the reaction"]', 0, 'Complete hydrolysis requires 3 moles NaOH.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following statements is <b>TRUE</b> of the complete hydrolysis of a glyceride by sodium hydroxide?', '["3 moles of NaOH are required for each mole of glyceride","3 moles of glycerol are produced","only one mole of soap is formed","Concentrated H2SO4 is essential for the completion of the reaction"]', '<u>3 moles of NaOH</u> per mole of glyceride.', '{"bold":["TRUE"],"italic":[],"underline":["3 moles of NaOH are required for each mole of glyceride"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7ttjxpr3td1nywzfra6fflb0', 'General Mathematics', 'JAMB', null, 2020, null, 'Find 20! (mod 23).', null, '["1","22","0","11"]', 0, 'By Wilson''s theorem, 22! ≡ -1 mod 23; 22! = 22×21×20!; 22×21 ≡ (-1)(-2) = 2; 2×20! ≡ -1 → 20! ≡ -1×12 = -12 ≡ 11 mod 23. Key says 1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find 20! (mod 23).', '["1","22","0","11"]', '20! ≡ <u>11</u> mod 23 (key says 1).', '{"bold":[],"italic":[],"underline":["1"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7u0vnwrsodp3fn0xjqs0lnfr', 'Chemistry', 'JAMB', null, 1986, null, 'Which of the following is <b>NOT correct</b> for the named organic compound in each case?', null, '["Butanoic acid solution gives effervescence with Na2CO3 solution","Glucose when reacted with Na2CrO4 at 0°C will show immediate discharge of colour","When but-2-ene is reacted with dilute KMnO4 the purple colour is discharged readily even at room temperature","When butan-2-ol is boiled with butanoic acid with a drop of concentrated H2SO4 a sweet smelling liquid is produced"]', 1, 'Glucose does not discharge Na2CrO4 colour at 0°C.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is <b>NOT correct</b> for the named organic compound in each case?', '["Butanoic acid solution gives effervescence with Na2CO3 solution","Glucose when reacted with Na2CrO4 at 0°C will show immediate discharge of colour","When but-2-ene is reacted with dilute KMnO4 the purple colour is discharged readily even at room temperature","When butan-2-ol is boiled with butanoic acid with a drop of concentrated H2SO4 a sweet smelling liquid is produced"]', '<u>Glucose does not discharge Na2CrO4 colour at 0°C</u>.', '{"bold":["NOT correct"],"italic":[],"underline":["Glucose when reacted with Na2CrO4 at 0°C will show immediate discharge of colour"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7u5m9r6bznhdtyf5sjht8an1', 'English Language', 'JAMB', null, 2020, null, 'The government has a special programme for _____.', null, '["the poor","the poors","poor","poors"]', 0, 'The poor = poor people as a group.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The government has a special programme for _____.', '["the poor","the poors","poor","poors"]', '<u>The poor</u> = poor people as a group.', '{"bold":[],"italic":[],"underline":["the poor"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7ud8ph3tycepdspomgebviyw', 'General Mathematics', 'WAEC', null, 2020, null, 'If ∫₀^a dx/√(a² - x²) = π/3, find a.', null, '["√3/2","1","2/√3","2"]', 1, '∫ = sin⁻¹(x/a); evaluated = π/2. π/2 = π/3 impossible. Key says 1.', false, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'If ∫₀^a dx/√(a² - x²) = π/3, find a.', '["√3/2","1","2/√3","2"]', 'a = <u>1</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7uqyeemnu29nw59nlb5xu8mv', 'Biology', 'JAMB', null, 2002, null, 'A person that is obese must avoid meals containing', null, '["carrots and oranges","margarine and butter","beef and beans","rice and yam"]', 1, 'Obese persons avoid fats (margarine and butter).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A person that is obese must avoid meals containing', '["carrots and oranges","margarine and butter","beef and beans","rice and yam"]', '<u>Margarine and butter</u>.', '{"bold":[],"italic":[],"underline":["margarine and butter"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7uxpuoh9gx6qrri2p99835bv', 'General Mathematics', 'WAEC', null, 2020, null, 'If log₁₀((6x - 5)/(x - 3)) = 1, find the value of x.', null, '["5","25/4","8","10"]', 1, '(6x-5)/(x-3) = 10 → 4x = 25 → x = 25/4.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'If log₁₀((6x - 5)/(x - 3)) = 1, find the value of x.', '["5","25/4","8","10"]', '(6x-5)/(x-3) = 10 → 4x = 25 → x = 25/4.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7uyyt27po86jcqsz4wsssd51', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Fount (of abundance) was given to the Prophet (S.A.W) and made known to him in surah', null, '["al-Ma''un","al-Takathur","an-Nasr","al-Kawthar."]', 3, 'Al-Kawthar refers to the fount of abundance.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Fount (of abundance) was given to the Prophet (S.A.W) and made known to him in surah', '["al-Ma''un","al-Takathur","an-Nasr","<u>al-Kawthar.</u>"]', '<u>Al-Kawthar</u> (Q. 108:1).', '{"bold":[],"italic":[],"underline":["al-Kawthar."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7uz6qsg0qsv34pb4z6p3mx18', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Amos declared that the Jews who built houses of hewn stone would not dwell in them because they', null, '["swore falsely","persecuted the prophets","trampled upon the poor","worshipped other gods."]', 2, 'They trampled upon the poor.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Amos declared that the Jews who built houses of hewn stone would not dwell in them because they', '["swore falsely","persecuted the prophets","<u>trampled upon the poor</u>","worshipped other gods."]', '<u>Trampled upon the poor</u> (Amos 5:11).', '{"bold":[],"italic":[],"underline":["trampled upon the poor"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7v0hrpmhph919k7xz2idmn46', 'General Mathematics', 'WAEC', null, 2020, null, 'What is the area of quadrilateral with vertices (0,0), (4,0), (4,3), and (0,3)?', null, '["12","16","20","24"]', 0, 'Rectangle 4×3 = 12.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is the area of quadrilateral with vertices (0,0), (4,0), (4,3), and (0,3)?', '["12","16","20","24"]', 'Area = <u>12</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7vhhz8wqcrkt3v4y3j6wr2if', 'Biology', 'JAMB', null, 2003, null, 'A man and his wife are both heterozygous for the sickle- cell trait. The likely percentage of their offspring that will be either carriers or sicklers is', null, '["50%","25%","75%","100%"]', 1, '25% is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A man and his wife are both heterozygous for the sickle- cell trait. The likely percentage of their offspring that will be either carriers or sicklers is', '["50%","<u>25%</u>","75%","100%"]', '25% is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7vockev66tinm0x787zbrw3e', 'Chemistry', 'JAMB', null, 1983, null, 'Manganese(IV) oxide reacts with concentrated hydrochloric acid according to the equation MnO2 + xHCl → MnCl2 + Cl2 + yH2O. x and y are', null, '["2 and 5 respectively","2 and 4 respectively","4 and 2 respectively","4 and 1 respectively","4 and 3 respectively"]', 2, 'Balancing: MnO2 + 4HCl → MnCl2 + Cl2 + 2H2O; x=4, y=2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Manganese(IV) oxide reacts with concentrated hydrochloric acid according to the equation MnO2 + xHCl → MnCl2 + Cl2 + yH2O. x and y are', '["2 and 5 respectively","2 and 4 respectively","4 and 2 respectively","4 and 1 respectively","4 and 3 respectively"]', '<u>x=4, y=2</u>.', '{"bold":[],"italic":[],"underline":["4 and 2 respectively"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7vpkxlhca38hkpuimirc29ay', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Q.17:26-27 warns Muslims not to squander their wealth as squanderers are brothers of the', null, '["evil ones","misguided","hypocrites","unbelievers."]', 0, 'Squanderers are brothers of the evil ones.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Q.17:26-27 warns Muslims not to squander their wealth as squanderers are brothers of the', '["<u>evil ones</u>","misguided","hypocrites","unbelievers."]', '<u>Evil ones</u> (Q. 17:27).', '{"bold":[],"italic":[],"underline":["evil ones"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7vrfchioku8gff7vd9v2f6n1', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'The last event that boosted Gideon''s courage to go against the Midianites was the', null, '["appearance of the angel who called him a man of valour","sign in which God caused the dew to be on the fleece","test God gave Gideon''s men at the waterside","dream told by the Midianites about the barley bread"]', 3, 'The dream of the barley bread boosted Gideon''s courage.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The last event that boosted Gideon''s courage to go against the Midianites was the', '["appearance of the angel who called him a man of valour","sign in which God caused the dew to be on the fleece","test God gave Gideon''s men at the waterside","<u>dream told by the Midianites about the barley bread</u>"]', '<u>Dream told by the Midianites about the barley bread</u> (Judges 7:13-15).', '{"bold":[],"italic":[],"underline":["dream told by the Midianites about the barley bread"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7vrlpeblp0nndnzw8yyqdtz8', 'Government', 'JAMB', null, 2020, null, 'The major demand of the Third World countries on the United Nations in recent times is the', null, '["expansion of the permanent membership of the Security Council","Post of Secretary-General of the organization","withdrawal of the veto power from the Security Council","enforcement of resolutions on the superpower."]', 0, 'Third World countries demand expansion of permanent Security Council membership.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The major demand of the Third World countries on the United Nations in recent times is the', '["<u>expansion of the permanent membership of the Security Council</u>","Post of Secretary-General of the organization","withdrawal of the veto power from the Security Council","enforcement of resolutions on the superpower."]', '<u>Expansion of permanent Security Council membership</u>.', '{"bold":[],"italic":[],"underline":["expansion of the permanent membership of the Security Council"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7vsn9g169tt676yxb5bogqq2', 'Biology', 'JAMB', null, 1999, null, 'The correct sequence for the operation of smell in mammals is', null, '["chemicals àolfactory nerve endingsà brain","dissolved chemicals à nasal sensory cell àbrain","chemicals àmucus membrane à sensory cells à brain","dissolved chemicals à sensory cells àolfactory nerve à brain Use the diagram below to answer questions 29 and 30 hoolgist.com s://"]', 3, 'dissolved chemicals à sensory cells àolfactory nerve à brain Use the diagram below to answer questions 29 and 30 hoolgist.com s:// is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The correct sequence for the operation of smell in mammals is', '["chemicals àolfactory nerve endingsà brain","dissolved chemicals à nasal sensory cell àbrain","chemicals àmucus membrane à sensory cells à brain","<u>dissolved chemicals à sensory cells àolfactory nerve à brain Use the diagram below to answer questions 29 and 30 hoolgist.com s://</u>"]', 'dissolved chemicals à sensory cells àolfactory nerve à brain Use the diagram below to answer questions 29 and 30 hoolgist.com s:// is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7vy2zq3wajvjxj8x5f4qbqss', 'General Mathematics', 'WAEC', null, 2020, null, 'Find x if 9^x + 6^x = 4^(x+1).', null, '["log_{3/2}2","log_{2/3}2","log_3 2","log_2 3"]', 0, 'Divide by 4^x: (3/2)^2x + (3/2)^x = 4 → y² + y - 4 = 0 → y = (√17-1)/2. Key says log_{3/2}2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find x if 9^x + 6^x = 4^(x+1).', '["log_{3/2}2","log_{2/3}2","log_3 2","log_2 3"]', '<u>log_{3/2}2</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7w2ptilgmybduzsea1hm3wth', 'Biology', 'JAMB', null, 2003, null, 'The pioneer organisms in ecological succession are usually the', null, '["lichens","algae","ferns","mosses"]', 0, 'Lichens are pioneer organisms.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The pioneer organisms in ecological succession are usually the', '["lichens","algae","ferns","mosses"]', '<u>Lichens</u>.', '{"bold":[],"italic":[],"underline":["lichens"],"fillBlanks":[]}');
