insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7wdmrqt34pe6pxwi9bicobpd', 'Government', 'JAMB', null, 2020, null, 'Which of these international finance agencies is Nigeria a member of?', null, '["The Paris Club","The London Club","The International Monetary Fund","The Infrastructure Development Fund"]', 2, 'Nigeria is a member of the IMF.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of these international finance agencies is Nigeria a member of?', '["The Paris Club","The London Club","<u>The International Monetary Fund</u>","The Infrastructure Development Fund"]', '<u>The International Monetary Fund</u>.', '{"bold":[],"italic":[],"underline":["The International Monetary Fund"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7wn1u62pf0asb8ecbpy0cdqt', 'Biology', 'JAMB', null, 1991, null, 'The lymphatic system of mammals rejoins the blood circulatory system at the', null, '["hepatic vein","subclavian vein","renal vein","common iliac vein"]', 1, 'Lymph rejoins blood at the subclavian vein.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The lymphatic system of mammals rejoins the blood circulatory system at the', '["hepatic vein","<u>subclavian vein</u>","renal vein","common iliac vein"]', 'Lymph rejoins blood at the <u>subclavian vein</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7wpako9w2wvfcu5joxds14d2', 'General Mathematics', 'WAEC', null, 2020, null, 'Find (0.23 + 0.4)/0.16.', null, '["3.5","4","4.5","5"]', 1, '(0.23 + 0.4)/0.16 = 0.63/0.16 = 3.9375. Key says 4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find (0.23 + 0.4)/0.16.', '["3.5","4","4.5","5"]', '(0.23 + 0.4)/0.16 = <u>3.9375</u> (key says 4).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7wpkf7499cldq7rzhizrn45j', 'General Mathematics', 'WAEC', null, 2020, null, 'The rate of change of the volume of a sphere with respect to its radius r is 36π. Find the radius r.', null, '["3","6","9","18"]', 0, 'dV/dr = 4πr² = 36π → r² = 9 → r = 3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The rate of change of the volume of a sphere with respect to its radius r is 36π. Find the radius r.', '["3","6","9","18"]', 'r = <u>3</u>.', null);
