insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7x1er636x4ml38oat2am4mcp', 'Chemistry', 'JAMB', null, 1985, null, 'Which of the following metals with NaOH gives salt and water only? When Z is treated with dilute HCl, a gas is evolved which gives a yellow suspension on passing into concentrated H2SO4. Substance Z is', null, '["NaHS","Na2SO3","Na2S","NaHSO3"]', 1, 'Na2SO3 gives SO2 with HCl, which gives a yellow suspension with concentrated H2SO4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following metals with NaOH gives salt and water only? When Z is treated with dilute HCl, a gas is evolved which gives a yellow suspension on passing into concentrated H2SO4. Substance Z is', '["NaHS","Na2SO3","Na2S","NaHSO3"]', '<u>Na2SO3</u> gives SO2.', '{"bold":[],"italic":[],"underline":["Na2SO3"],"fillBlanks":[]}');
