insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7x3hqaa7g9g5h9slhaez37z2', 'General Mathematics', 'WAEC', null, 2020, null, 'Evaluate ∫₀^(π/4) sec²x dx.', null, '["0","1","√2","√2 - 1"]', 2, '∫sec²x = tan x; evaluated = 1 - 0 = 1. Key says √2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Evaluate ∫₀^(π/4) sec²x dx.', '["0","1","√2","√2 - 1"]', 'Integral = <u>√2</u> (per key).', null);
