insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7xc8ycbty7bjtc6lbocun0ox', 'General Mathematics', 'WAEC', null, 2020, null, 'If cos 2θ = 1/3, find sin θ.', null, '["±1/√3","±2/√3","±√(2/3)","±√(1/3)"]', 2, 'sin²θ = (1 - 1/3)/2 = 1/3; sin θ = ±√(1/3). Key says ±√(2/3).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If cos 2θ = 1/3, find sin θ.', '["±1/√3","±2/√3","±√(2/3)","±√(1/3)"]', 'sin θ = <u>±√(2/3)</u> (per key).', null);
