insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7ys78qheqwe89e2xtth5k1ol', 'General Mathematics', 'JAMB', null, 2020, null, 'If ∫(eˣ - 1)/(eˣ + 1) dx = f(x) + C, find f(x).', null, '["ln(eˣ + 1) - x","ln(eˣ - 1) + x","ln(eˣ + 1) + x","ln(eˣ - 1) - x"]', 0, 'Let u = eˣ + 1; integral = ln(eˣ+1) - x + C.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If ∫(eˣ - 1)/(eˣ + 1) dx = f(x) + C, find f(x).', '["ln(eˣ + 1) - x","ln(eˣ - 1) + x","ln(eˣ + 1) + x","ln(eˣ - 1) - x"]', 'f(x) = <u>ln(eˣ + 1) - x</u>.', '{"bold":[],"italic":[],"underline":["ln(eˣ + 1) - x"],"fillBlanks":[]}');
