insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7zpajq7b1ql3ulf1wm5x4qyo', 'General Mathematics', 'JAMB', null, 2020, null, 'If A, B are 3×3 with |A| = 2, |B| = -3, find |2AᵀB⁻¹|.', null, '["8/3","-16/3","-4/3","4/3"]', 1, '|2AᵀB⁻¹| = 2³·|A|/|B| = 8·2/(-3) = -16/3.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'If A, B are 3×3 with |A| = 2, |B| = -3, find |2AᵀB⁻¹|.', '["8/3","-16/3","-4/3","4/3"]', '|2AᵀB⁻¹| = 2³·|A|/|B| = 8·2/(-3) = -16/3.', '{"bold":[],"italic":[],"underline":["-8/3"],"fillBlanks":[]}');
