insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7zwbc9xra9ig5uolcnhpzcxc', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'According to Hosea, the LORD would not have pity upon children of his faithless wife because', null, '["they had not been faithful","they were rebellious children","their mother had played the harlot","their mother had not shown pity on them."]', 2, 'Their mother had played the harlot.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to Hosea, the LORD would not have pity upon children of his faithless wife because', '["they had not been faithful","they were rebellious children","<u>their mother had played the harlot</u>","their mother had not shown pity on them."]', '<u>Their mother had played the harlot</u> (Hosea 1-2).', '{"bold":[],"italic":[],"underline":["their mother had played the harlot"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c7zxjw5t14hxnckusl8gvr4lw', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Let us make man in our image, after our likeness ... In the statement above, "in our image" implies man', null, '["becoming God","being a representative of God to fellow men","being like God","becoming the exact picture of God"]', 2, 'Being made in God''s image implies being like God.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Let us make man in our image, after our likeness ... In the statement above, "in our image" implies man', '["becoming God","being a representative of God to fellow men","<u>being like God</u>","becoming the exact picture of God"]', '<u>Being like God</u>.', '{"bold":[],"italic":[],"underline":["being like God"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8033504-737b-4a1f-b5c2-da4259007684', 'English Language', 'JAMB', null, 2024, null, 'Choose the word that contains the sound represented by the given phonetic symbol: /b/', null, '["plumber","doubtful","slumber","debtor"]', 2, '"Slumber" contains the /b/ sound. The "b" in plumber, doubtful, and debtor is silent.', true, '2026-09-18 09:43:02.864', '2026-09-18 09:43:02.864', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c80aah80ed1zvdlllv7v2glmh', 'General Mathematics', 'JAMB', null, 2020, null, 'Find ∫xe^(x²)dx.', null, '["½e^(x²) + C","e^(x²) + C","2e^(x²) + C","½xe^(x²) + C"]', 0, 'Let u = x²; du = 2x dx → ½∫eᵘdu = ½e^(x²) + C.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find ∫xe^(x²)dx.', '["½e^(x²) + C","e^(x²) + C","2e^(x²) + C","½xe^(x²) + C"]', '∫ = <u>½e^(x²) + C</u>.', '{"bold":[],"italic":[],"underline":["½e^(x²) + C"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c80d91a7-ace7-46f8-bc17-85f6034a8128', 'Economics', 'JAMB', null, 2026, null, 'A situation in which a commodity is sold abroad below its cost of production in its home country is known as?', null, '["Dumping","Counter-trade","Free trade","Bilateral trade"]', 0, 'Dumping is the practice of selling goods in a foreign market at a price below the cost of production or below the price charged in the home market.', true, '2026-09-12 10:57:24.843', '2026-09-12 10:57:24.843', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c80ehombvtbf3rptsexy7mlyh', 'Biology', 'JAMB', null, 1993, null, 'The membrane surrounding the vacuole in a plant cell is called the', null, '["plasmalemma","tonoplast","nuclear membrane","endoplasmic reticulum"]', 1, 'The tonoplast surrounds the vacuole.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The membrane surrounding the vacuole in a plant cell is called the', '["plasmalemma","<u>tonoplast</u>","nuclear membrane","endoplasmic reticulum"]', 'The <u>tonoplast</u> surrounds the vacuole.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c80ot5uncunahyb76vj2tkcea', 'Chemistry', 'JAMB', null, 1994, null, 'When sodium ethanoate is treated with a few drops of concentrated tetraoxosulphate(VI) acid one of the products is', null, '["CH3COOH","CH3COOH","CH3COOC2H5","CH3COOCH3"]', 0, 'CH3COONa + H2SO4 → CH3COOH + NaHSO4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When sodium ethanoate is treated with a few drops of concentrated tetraoxosulphate(VI) acid one of the products is', '["CH3COOH","CH3COOH","CH3COOC2H5","CH3COOCH3"]', '<u>CH3COOH</u> is produced.', '{"bold":[],"italic":[],"underline":["CH3COOH"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c80p3xliphzxs9saeqa8aucm6', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'One of the sins of Manasseh for which the LORD sent bands of the Chaldeans, Syrians, Moabites and Ammonites to destroy Judah was', null, '["the release of a thousand captives","the shedding of innocent blood","his failure to obey God''s prophets","the arrest of the king of Babylon."]', 1, 'Manasseh shed innocent blood.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One of the sins of Manasseh for which the LORD sent bands of the Chaldeans, Syrians, Moabites and Ammonites to destroy Judah was', '["the release of a thousand captives","<u>the shedding of innocent blood</u>","his failure to obey God''s prophets","the arrest of the king of Babylon."]', '<u>The shedding of innocent blood</u> (2 Kings 24:2-4).', '{"bold":[],"italic":[],"underline":["the shedding of innocent blood"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c811eb9e-eb40-429b-809e-d088518e4f45', 'Financial Accounting', 'UTME', null, 2003, null, 'Which accounting concept supports the assertion that economic reality takes precedence over legal issues?', null, '["realization concept","substance over form","conservatism","measurement concept"]', 1, 'The substance over form concept supports the assertion that economic reality takes precedence over legal issues.', true, '2026-10-12 21:59:59.534', '2026-10-12 21:59:59.534', null, null, null, 'Which accounting concept supports the assertion that economic reality takes precedence over legal issues?', '["realization concept","<b>substance over form</b>","conservatism","measurement concept"]', 'The <b>substance over form</b> concept supports the assertion that economic reality takes precedence over legal issues.', '{"bold":["substance over form"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c813678fjuw1u7tkenpc57odv', 'Chemistry', 'JAMB', null, 1993, null, 'Argon is used in gas-filled electric lamps because it helps to', null, '["prevent the reduction of the lamp filament","prevent oxidation of lamp filament","make lamp filaments glow brightly","keep the atmosphere in the lamp inert"]', 1, 'Argon prevents oxidation of the filament.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Argon is used in gas-filled electric lamps because it helps to', '["prevent the reduction of the lamp filament","prevent oxidation of lamp filament","make lamp filaments glow brightly","keep the atmosphere in the lamp inert"]', '<u>Argon prevents oxidation</u> of the filament.', '{"bold":[],"italic":[],"underline":["prevent oxidation of lamp filament"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c814lqmt3g0h2o5004eobc5vi', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'God told Ezekiel that the house of Israel would not listen to him because they', null, '["were a people of foreign speech","had forsaken His laws","were of a stubborn heart","had not truly repented."]', 2, 'They were of a stubborn heart.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'God told Ezekiel that the house of Israel would not listen to him because they', '["were a people of foreign speech","had forsaken His laws","<u>were of a stubborn heart</u>","had not truly repented."]', '<u>Were of a stubborn heart</u> (Ezekiel 3:7).', '{"bold":[],"italic":[],"underline":["were of a stubborn heart"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c814q0f2ikaao7g95njjh3urb', 'Islamic Religious Studies', 'JAMB', null, 2002, null, 'The jamrat that pilgrims are expected to stone on the <b>10th day</b> of Dhul hijjah is', null, '["al-Aqabah","al-Wusta","as-Sughra","al-adna"]', 0, 'On the 10th of Dhul Hijjah, pilgrims stone Jamrat al-Aqabah.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The jamrat that pilgrims are expected to stone on the <b>10th day</b> of Dhul hijjah is', '["<u>al-Aqabah</u>","al-Wusta","as-Sughra","al-adna"]', 'On the 10th of Dhul Hijjah, pilgrims stone <u>Jamrat al-Aqabah</u>.', '{"bold":["10th day"],"italic":[],"underline":["al-Aqabah"],"fillBlanks":[]}');
