insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8ff9zkgeougy1edzipi8if3y', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'The consequence of Hiel''s building of Jericho was that he', null, '["lost two of his sons","was highly respected by his tribe","was killed by Ahab","was made a commander in Ahab''s army."]', 0, 'Hiel lost two of his sons.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The consequence of Hiel''s building of Jericho was that he', '["<u>lost two of his sons</u>","was highly respected by his tribe","was killed by Ahab","was made a commander in Ahab''s army."]', '<u>Lost two of his sons</u> (1 Kings 16:34).', '{"bold":[],"italic":[],"underline":["lost two of his sons"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8fgjl6vskt764pkh0pxkl31s', 'Government', 'JAMB', null, 2020, null, 'A political system which empowers the leader with the ultimate responsibility to execute laws is', null, '["parliamentarism","presidentialism","dictatorship","autocracy."]', 1, 'Presidentialism vests ultimate executive responsibility in the leader.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A political system which empowers the leader with the ultimate responsibility to execute laws is', '["parliamentarism","<u>presidentialism</u>","dictatorship","autocracy."]', '<u>Presidentialism</u>.', '{"bold":[],"italic":[],"underline":["presidentialism"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8fkzj6kds3xnzmc1v0z2qxju', 'Government', 'JAMB', null, 2020, null, 'One of the strong points of the multi-party system in Nigeria''s Fourth Republic is', null, '["the provision for a bicameral legislature","government interference","wider political participation","wider anti-democracy campaign."]', 2, 'Multi-party system allows wider political participation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One of the strong points of the multi-party system in Nigeria''s Fourth Republic is', '["the provision for a bicameral legislature","government interference","<u>wider political participation</u>","wider anti-democracy campaign."]', '<u>Wider political participation</u>.', '{"bold":[],"italic":[],"underline":["wider political participation"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8fnjmassl91jln53j1uz5spu', 'Government', 'JAMB', null, 2020, null, 'One judicial function performed by the executive is', null, '["granting of amnesty","implementing judicial orders","ensuring obedience to the law","appointing judges."]', 0, 'Granting amnesty is a judicial function of the executive.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One judicial function performed by the executive is', '["<u>granting of amnesty</u>","implementing judicial orders","ensuring obedience to the law","appointing judges."]', '<u>Granting of amnesty</u>.', '{"bold":[],"italic":[],"underline":["granting of amnesty"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8g5mji2kkmfn36gzdrhr9ws3', 'Islamic Religious Studies', 'JAMB', null, 2002, null, 'Q.17:26-27 warns Muslims not to squander their wealth as squanderers are brothers of the', null, '["evil ones","misguided","hypocrites","unbelievers"]', 0, 'Q.17:27 says spendthrifts are brothers of the devils.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Q.17:26-27 warns Muslims not to squander their wealth as squanderers are brothers of the', '["<u>evil ones</u>","misguided","hypocrites","unbelievers"]', 'Q.17:27 says spendthrifts are brothers of the <u>devils</u>.', '{"bold":[],"italic":[],"underline":["evil ones"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8ghfr9gqnytp8j4eadq323nw', 'Biology', 'JAMB', null, 1992, null, 'Malaria symptoms are caused by', null, '["toxins released into the blood as a result of the destruction of red blood cells","the multiplication of the malarial sporozoites in the liver","the invasion of the red blood cells by the trophozoites","the development of merozoites into gametocytes"]', 0, 'Malaria symptoms are caused by toxins from red blood cell destruction.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Malaria symptoms are caused by', '["<u>toxins released into the blood as a result of the destruction of red blood cells</u>","the multiplication of the malarial sporozoites in the liver","the invasion of the red blood cells by the trophozoites","the development of merozoites into gametocytes"]', '<u>Malaria symptoms are caused by toxins from red blood cell destruction</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8ghyzl2zxs90kzoz2ivxllqc', 'Islamic Religious Studies', 'JAMB', null, 2008, null, '[Arabic verse] The verse above teaches that Muslims should', null, '["Travel round the world and see wonders","Explore the earth and be learned","Go into the earth and see Allah''s creatures","Disperse into the land and earn a living"]', 3, 'Q.62:10 says disperse through the land and seek Allah''s bounty.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '[Arabic verse] The verse above teaches that Muslims should', '["Travel round the world and see wonders","Explore the earth and be learned","Go into the earth and see Allah''s creatures","<u>Disperse into the land and earn a living</u>"]', 'Q.62:10 says <u>disperse through the land and seek Allah''s bounty</u>.', '{"bold":[],"italic":[],"underline":["Disperse into the land and earn a living"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8gjdqceng43a2nb754yp8t7w', 'General Mathematics', 'JAMB', null, 2020, null, 'If 2ⁿ ≡ 1 (mod 5), what is the smallest positive n?', null, '["2","3","4","5"]', 2, '2⁴ = 16 ≡ 1 mod 5.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If 2ⁿ ≡ 1 (mod 5), what is the smallest positive n?', '["2","3","4","5"]', '2⁴ = 16 ≡ <u>1</u> mod 5 → n = 4.', '{"bold":[],"italic":[],"underline":["4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8gmj2ti8p2umeomlto8azvn0', 'Biology', 'JAMB', null, 1997, null, 'The part of the brain that regulates most <b>biological cycles</b> in humans is', null, '["olfactory lobe","optic lobe","medulla oblongata","pineal body"]', 3, 'The pineal body regulates biological cycles.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The part of the brain that regulates most <b>biological cycles</b> in humans is', '["olfactory lobe","optic lobe","medulla oblongata","pineal body"]', '<u>The pineal body regulates biological cycles</u>.', '{"bold":["biological cycles"],"italic":[],"underline":["pineal body"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8gslduje11y2uza371rnv72h', 'Islamic Religious Studies', 'JAMB', null, 2011, null, 'The entrenchment of an Islamic economic system is aimed at', null, '["controlling the world funds","restricting the unlawful acquisition of wealth","restricting men to particular occupations","promoting equitable distribution of wealth"]', 3, 'The Islamic economic system promotes equitable distribution.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The entrenchment of an Islamic economic system is aimed at', '["controlling the world funds","restricting the unlawful acquisition of wealth","restricting men to particular occupations","<u>promoting equitable distribution of wealth</u>"]', 'The Islamic economic system promotes <u>equitable distribution of wealth</u>.', '{"bold":[],"italic":[],"underline":["promoting equitable distribution of wealth"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8gtsq5q1wf0ecdp7oc7re6rg', 'Government', 'JAMB', null, 2020, null, 'Nigeria''s influence in OPEC is determined by the', null, '["volume of her oil reserve","sizes of her refineries","accessibility of her oil field","low sulphur content of her crude"]', 0, 'Nigeria''s OPEC influence is based on oil reserve volume.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Nigeria''s influence in OPEC is determined by the', '["<u>volume of her oil reserve</u>","sizes of her refineries","accessibility of her oil field","low sulphur content of her crude"]', '<u>Volume of her oil reserve</u>.', '{"bold":[],"italic":[],"underline":["volume of her oil reserve"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8gyfhj7q1oi994p0f3jbiix2', 'Government', 'JAMB', null, 2020, null, 'Indirect rule system of administration was more successful in northern Nigeria because', null, '["The natives showed little or no resistance","The people were mainly interested in being governed directly","Of the existence of an organized structure in the area","The Europeans ensured that the farmlands of the natives were not confiscated"]', 2, 'An organized structure made indirect rule succeed in the North.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Indirect rule system of administration was more successful in northern Nigeria because', '["The natives showed little or no resistance","The people were mainly interested in being governed directly","<u>Of the existence of an organized structure in the area</u>","The Europeans ensured that the farmlands of the natives were not confiscated"]', '<u>Existence of an organized structure in the area</u>.', '{"bold":[],"italic":[],"underline":["Of the existence of an organized structure in the area"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8h0rdrahshj2ea33ytyq97u3', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The Khulafa al-Rashidun reigned between', null, '["A.D.632 and 661","A.D.622 and 632","A.D.610 and 661","A.D.632 and 750."]', 0, 'The rightly guided caliphs reigned between 632 and 661 CE.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Khulafa al-Rashidun reigned between', '["<u>A.D.632 and 661</u>","A.D.622 and 632","A.D.610 and 661","A.D.632 and 750."]', '<u>A.D.632 and 661</u>.', '{"bold":[],"italic":[],"underline":["A.D.632 and 661"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8h1zl2iguvhfjfy0tc5frswk', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve (2x - 3)/(x + 1) > 1.', null, '["x > 4","x < -1 or x > 4","-1 < x < 4","x < -1"]', 1, '(2x - 3)/(x + 1) - 1 > 0 → (x - 4)/(x + 1) > 0 → x < -1 or x > 4. Key says x > 4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve (2x - 3)/(x + 1) > 1.', '["x < -1 or x > 4","x > 4","-1 < x < 4","x < -1"]', 'Solution: <u>x > 4</u> (per key).', '{"bold":[],"italic":[],"underline":["x > 4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8h72may54f5yihpsjrvqfear', 'Biology', 'JAMB', null, 2001, null, 'When specimen X is mixed with few drops of iodine solution, the appearance of a blue-black colour confirms that X is', null, '["Galactose","Starch","Sucrose","Glucose"]', 1, 'Iodine gives blue-black with starch.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When specimen X is mixed with few drops of iodine solution, the appearance of a blue-black colour confirms that X is', '["Galactose","Starch","Sucrose","Glucose"]', '<u>Starch</u> gives blue-black with iodine.', '{"bold":[],"italic":[],"underline":["Starch"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8h7nkaeb9n9qzrx8huxvoc3t', 'Chemistry', 'JAMB', null, 1987, null, 'Tetraoxosulphate(IV) acid is prepared using the chemical reaction SO3(g) + H2O → H2SO4(l). Given the heat of formation for SO3(g), H2O(l) and H2SO4(l) as -395 kJ mol⁻¹, -286 kJ mol⁻¹ and -811 kJ mol⁻¹ respectively, the heat change is', null, '["-1032 kJ","-130 kJ","+130 kJ","+1032 kJ"]', 1, 'ΔH = -811 - (-395 + -286) = -811 + 681 = -130 kJ.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Tetraoxosulphate(IV) acid is prepared using the chemical reaction SO3(g) + H2O → H2SO4(l). Given the heat of formation for SO3(g), H2O(l) and H2SO4(l) as -395 kJ mol⁻¹, -286 kJ mol⁻¹ and -811 kJ mol⁻¹ respectively, the heat change is', '["-1032 kJ","-130 kJ","+130 kJ","+1032 kJ"]', 'ΔH = <u>-130 kJ</u>.', '{"bold":[],"italic":[],"underline":["-130 kJ"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8h9lyg80bwbrsjcz73mb2dls', 'General Mathematics', 'WAEC', null, 2020, null, 'If a/b = 0.6 and b/c = 0.3 find a/c.', null, '["2/9","9/50","2/5","5/9"]', 1, 'a/c = 0.6 × 0.3 = 0.18 = 9/50.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'If a/b = 0.6 and b/c = 0.3 find a/c.', '["2/9","9/50","2/5","5/9"]', 'a/c = 0.6 × 0.3 = 0.18 = 9/50.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8hciazeetc2ng50zz4mi0y5s', 'Biology', 'JAMB', null, 1994, null, 'Some of the diseases caused by bacteria are', null, '["tuberculosis, gonorrhoea and syphilis","tuberculosis, gonorrhoea and AIDS","Poliomyelitis, syphilis and gonorrhoea","AIDS, cholera and tuberculosis"]', 3, 'Tuberculosis, gonorrhoea, and syphilis are caused by bacteria.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Some of the diseases caused by bacteria are', '["tuberculosis, gonorrhoea and syphilis","tuberculosis, gonorrhoea and AIDS","Poliomyelitis, syphilis and gonorrhoea","<u>tuberculosis, gonorrhoea and syphilis</u>"]', '<u>Tuberculosis, gonorrhoea, and syphilis are caused by bacteria</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8hlka7wbmb1khxml8lwz7r9x', 'Chemistry', 'JAMB', null, 1991, null, 'A sample of temporary hard water can be prepared in the laboratory by', null, '["dissolving calcium chloride in distilled water","saturating lime water with carbon(IV) oxide","saturating distilled water with calcium hydroxide","dissolving sodium hydrogen trioxocarbonate(IV) in some distilled water"]', 1, 'Temporary hard water contains Ca(HCO3)2, formed by saturating lime water with CO2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A sample of temporary hard water can be prepared in the laboratory by', '["dissolving calcium chloride in distilled water","saturating lime water with carbon(IV) oxide","saturating distilled water with calcium hydroxide","dissolving sodium hydrogen trioxocarbonate(IV) in some distilled water"]', '<u>Saturating lime water with CO2</u> gives temporary hard water.', '{"bold":[],"italic":[],"underline":["saturating lime water with carbon(IV) oxide"],"fillBlanks":[]}');
