insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8i7ibxohdlhyge3dg30yhwzf', 'Chemistry', 'JAMB', null, 1995, null, 'Smoke consists of', null, '["solid particles dispersed in liquid","solid or liquid particles dispersed in gas","gas or liquid particles dispersed in liquid","liquid particles dispersed in liquid"]', 1, 'Smoke is solid/liquid particles dispersed in gas.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Smoke consists of', '["solid particles dispersed in liquid","solid or liquid particles dispersed in gas","gas or liquid particles dispersed in liquid","liquid particles dispersed in liquid"]', '<u>Solid or liquid particles dispersed in gas</u>.', '{"bold":[],"italic":[],"underline":["solid or liquid particles dispersed in gas"],"fillBlanks":[]}');
