insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8ig990uga1bsocv7jdfc4q30', 'Biology', 'JAMB', null, 1984, null, 'In a Biuret test, some protein was mixed with sodium hydroxide solution. Which of the following chemicals should be added to the mixture for a positive result?', null, '["Mercurous nitrate","Copper sulphate","Mercuric nitrate","Sodium carbonate","Ammonium hydroxide"]', 1, 'Copper sulphate is added in the Biuret test for proteins.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In a <b>Biuret test</b>, some protein was mixed with sodium hydroxide solution. Which of the following chemicals should be added to the mixture for a positive result?', '["Mercurous nitrate","<u>Copper sulphate</u>","Mercuric nitrate","Sodium carbonate","Ammonium hydroxide"]', '<u>Copper sulphate</u> is added in the Biuret test for proteins.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8imlb27h52ip6tejj75ireiy', 'Biology', 'JAMB', null, 1987, null, 'In tapeworm, the two structures that run through the length of the body are the', null, '["nerve cord and the excreory duct","sperm duct and the nerve cord","genital pore and the excreory duct","sperm duct and the genital pore"]', 0, 'The nerve cord and excretory duct run the length of the tapeworm.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In tapeworm, the two structures that run through the length of the body are the', '["<u>nerve cord and the excreory duct</u>","sperm duct and the nerve cord","genital pore and the excreory duct","sperm duct and the genital pore"]', 'The <u>nerve cord and excretory duct</u> run the length of the tapeworm.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8its2ai0wvim0reyrf4ovwwh', 'English Language', 'JAMB', null, 2020, null, 'The _____ of NATO countries have been alerted about the possibility of an attack.', null, '["commanders-in-chiefs","commander-in-chiefs","commanders-in-chief","commander-in-chief"]', 2, 'Plural: "commanders-in-chief" (plural on the first noun).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The _____ of NATO countries have been alerted about the possibility of an attack.', '["commanders-in-chiefs","commander-in-chiefs","commanders-in-chief","commander-in-chief"]', 'Plural: <u>commanders-in-chief</u>.', '{"bold":[],"italic":[],"underline":["commanders-in-chief"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8itvjhna2uk8e23udn380k9r', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the center of the hyperbola 9x² - 16y² = 144.', null, '["(0, 0)","(4, 0)","(0, 3)","(3, 0)"]', 0, 'Center at origin.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the center of the hyperbola 9x² - 16y² = 144.', '["(0, 0)","(4, 0)","(0, 3)","(3, 0)"]', 'Center = <u>(0, 0)</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8jc9o92xqknumtg9aqcakqd6', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'What acts of righteousness did Isaiah admonish his people to demonstrate?', null, '["Helping the poor and offering sacrifices.","Learning to do good and seeking justice.","Defending the orphans and respecting the widows.","Avoiding evil and praying for others."]', 1, 'Isaiah admonished them to learn to do good and seek justice.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What acts of righteousness did Isaiah admonish his people to demonstrate?', '["Helping the poor and offering sacrifices.","<u>Learning to do good and seeking justice.</u>","Defending the orphans and respecting the widows.","Avoiding evil and praying for others."]', '<u>Learning to do good and seeking justice</u>.', '{"bold":[],"italic":[],"underline":["Learning to do good and seeking justice."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8jdaxl3gp1jpj3fsgaspl2ka', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the values of k for which the line y = kx + 3 is a tangent to the curve y = x² + 4x + 1.', null, '["k = -2 ± 2√3","k = 2 ± 2√3","k = -2 ± √3","k = 2 ± √3"]', 0, 'Discriminant = 0 → (k-4)² - 8 = 0 → k = 4 ± 2√2. Key says -2 ± 2√3.', false, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Find the values of k for which the line y = kx + 3 is a tangent to the curve y = x² + 4x + 1.', '["k = -2 ± 2√3","k = 2 ± 2√3","k = -2 ± √3","k = 2 ± √3"]', 'k = <u>-2 ± 2√3</u> (per key).', '{"bold":[],"italic":[],"underline":["k = -2 ± 2√3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8jdp204to86qlpz55qni1345', 'General Mathematics', 'JAMB', null, 2020, null, 'The mean and standard deviation of 15 numbers are 25 and 5 respectively. If each number is increased by 5 and then multiplied by 2, find the new standard deviation.', null, '["5","10","15","20"]', 1, 'SD scales by multiplier only: 5 × 2 = 10.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The mean and standard deviation of 15 numbers are 25 and 5 respectively. If each number is increased by 5 and then multiplied by 2, find the new standard deviation.', '["5","10","15","20"]', 'New SD = <u>10</u>.', '{"bold":[],"italic":[],"underline":["10"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8jfuect9ss0dcegwzvxbqbbp', 'Chemistry', 'JAMB', null, 2024, null, 'The most energetically favoured configuration is the ____', null, '["Excited state","Ground state","Lowest orbital","Higher orbital"]', 1, 'The ground state is the most energetically favoured configuration.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The most energetically favoured configuration is the ____', '["Excited state","<u>Ground state</u>","Lowest orbital","Higher orbital"]', 'The <u>ground state</u> is the most energetically favoured configuration.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8jkk1irxkrqj4kf6iw94gaeq', 'Government', 'JAMB', null, 2020, null, 'Socialism is a mode of production based on', null, '["state ownership of the means of production.","collective ownership of the means of production","national ownership of the means of production","mixed ownership of the means of production"]', 1, 'Socialism is based on collective ownership.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Socialism is a mode of production based on', '["state ownership of the means of production.","<u>collective ownership of the means of production</u>","national ownership of the means of production","mixed ownership of the means of production"]', '<u>Collective ownership of the means of production</u>.', '{"bold":[],"italic":[],"underline":["collective ownership of the means of production"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8jmucddmw8vetv8r2rfkvqdl', 'Christian Religious Studies', 'JAMB', null, 2020, null, '.... This Jesus God raised up, and of that we all are witnesses.... The statement above was made by Peter on the occasion of his', null, '["healing of the lame man at the gate called Beautiful","release from prison by the Jews","address to the disciples for the replacement","sermon on the day of Pentecost."]', 3, 'Peter said this during his sermon on the day of Pentecost.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '.... This Jesus God raised up, and of that we all are witnesses.... The statement above was made by Peter on the occasion of his', '["healing of the lame man at the gate called Beautiful","release from prison by the Jews","address to the disciples for the replacement","<u>sermon on the day of Pentecost.</u>"]', '<u>Sermon on the day of Pentecost</u> (Acts 2:32).', '{"bold":[],"italic":[],"underline":["sermon on the day of Pentecost."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8jvcicd6iehb973dyz6922ra', 'Islamic Religious Studies', 'JAMB', null, 2011, null, 'Members of the Prophet''s family that embraced Islam the first day did so, on the basis of his', null, '["truthfulness and uprightness","wealth and influence","love for them","family relation"]', 0, 'They embraced Islam due to his truthfulness and uprightness.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Members of the Prophet''s family that embraced Islam the first day did so, on the basis of his', '["<u>truthfulness and uprightness</u>","wealth and influence","love for them","family relation"]', 'They embraced Islam due to his <u>truthfulness and uprightness</u>.', '{"bold":[],"italic":[],"underline":["truthfulness and uprightness"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8k03bku2uo7p6c5lr0quvqvu', 'Chemistry', 'JAMB', null, 2024, null, 'Acetone reacts with HCN to form a cyanohydrin. It is an example of ____ reaction', null, '["Addition","Hydration","Acylation","Substitution"]', 0, 'The reaction of acetone with HCN to form cyanohydrin is an addition reaction.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Acetone reacts with HCN to form a <b>cyanohydrin</b>. It is an example of ____ reaction', '["<u>Addition</u>","Hydration","Acylation","Substitution"]', 'The reaction of acetone with HCN to form cyanohydrin is an <u>addition reaction</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8kkkbvnbtzi9eqhddocp8lmy', 'General Mathematics', 'WAEC', null, 2020, null, 'If log_a(bc) = x, log_b(ca) = y and log_c(ab) = z, find 1/(x + 1) + 1/(y + 1) + 1/(z + 1).', null, '["0","1","2","3"]', 1, 'Identity: sum = 1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If log_a(bc) = x, log_b(ca) = y and log_c(ab) = z, find 1/(x + 1) + 1/(y + 1) + 1/(z + 1).', '["0","1","2","3"]', 'Sum = <u>1</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8ko1hbgx33pbrjoe04ejw092', 'Government', 'JAMB', null, 2020, null, 'In the legislative process, a bill is a', null, '["motion accepted for debate","motion rejected after debate","proposal before the legislature","law passed by the legislature"]', 2, 'A bill is a proposed law before the legislature.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the legislative process, a bill is a', '["motion accepted for debate","motion rejected after debate","<u>proposal before the legislature</u>","law passed by the legislature"]', 'A bill is a <u>proposal before the legislature</u>.', '{"bold":[],"italic":[],"underline":["proposal before the legislature"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8ksm8ssbuexcsev8rnnx0qfx', 'General Mathematics', 'WAEC', null, 2020, null, 'On integers mod 5, a*b = (a + b) mod 5, find the inverse of 3.', null, '["2","3","4","1"]', 0, '3*2 = 5 ≡ 0 (mod 5); identity = 0; inverse of 3 = 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'On integers mod 5, a*b = (a + b) mod 5, find the inverse of 3.', '["2","3","4","1"]', 'Inverse = <u>2</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8ku9mxlk9dx0vr7vfcpap4eh', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'When the Babylonians captured King Zedekiah, they', null, '["killed him immediately","put out his eyes","assaulted his wives in his presence","took his sons to Babylon."]', 1, 'They put out Zedekiah''s eyes.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When the Babylonians captured King Zedekiah, they', '["killed him immediately","<u>put out his eyes</u>","assaulted his wives in his presence","took his sons to Babylon."]', '<u>Put out his eyes</u> (2 Kings 25:6-7).', '{"bold":[],"italic":[],"underline":["put out his eyes"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8l1wi1cscd0oz2bux6ed01t0', 'Government', 'JAMB', null, 2020, null, 'A major feature of authoritarianism is that government is', null, '["consensual","personalized","centralized","decentralized"]', 1, 'Authoritarian governments are typically personalized around a single leader.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A major feature of authoritarianism is that government is', '["consensual","<u>personalized</u>","centralized","decentralized"]', '<u>Personalized</u> rule is a major feature of authoritarianism.', '{"bold":[],"italic":[],"underline":["personalized"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8l2uyhjl18jdo723v4zk8fxp', 'General Mathematics', 'WAEC', null, 2020, null, 'A variable point P(x, y) moves so that its distance from the point A(2, 3) is twice its distance from the point B(-1, 0). Find the equation of its locus.', null, '["3x² + 3y² - 12x - 6y = 0","3x² + 3y² - 12x - 6y + 12 = 0","x² + y² - 4x - 2y + 4 = 0","x² + y² - 4x - 2y = 0"]', 0, '(x-2)² + (y-3)² = 4[(x+1)² + y²]; simplifying gives 3x² + 3y² - 12x - 6y = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A variable point P(x, y) moves so that its distance from the point A(2, 3) is twice its distance from the point B(-1, 0). Find the equation of its locus.', '["3x² + 3y² - 12x - 6y = 0","3x² + 3y² - 12x - 6y + 12 = 0","x² + y² - 4x - 2y + 4 = 0","x² + y² - 4x - 2y = 0"]', 'Locus: <u>3x² + 3y² - 12x - 6y = 0</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8l4zxssa0edn135ilmb7rr9n', 'General Mathematics', 'JAMB', null, 2020, null, 'Three persons hit a target with probabilities 1/2, 1/3, 1/4. Find the probability exactly one hits.', null, '["11/24","13/24","15/24","17/24"]', 0, 'P = (1/2)(2/3)(3/4) + (1/2)(1/3)(3/4) + (1/2)(2/3)(1/4) = 6/24 + 3/24 + 2/24 = 11/24.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Three persons hit a target with probabilities 1/2, 1/3, 1/4. Find the probability exactly one hits.', '["11/24","13/24","15/24","17/24"]', 'P = <u>11/24</u>.', '{"bold":[],"italic":[],"underline":["11/24"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8l8cex1bg868qhzkbropv1mu', 'General Mathematics', 'JAMB', null, 2020, null, 'Poisson distribution with λ = 4. Find P(X = 2).', null, '["8e⁻⁴","4e⁻⁴","2e⁻⁴","e⁻⁴"]', 0, 'P(X=2) = e⁻⁴·4²/2! = 8e⁻⁴.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Poisson distribution with λ = 4. Find P(X = 2).', '["8e⁻⁴","4e⁻⁴","2e⁻⁴","e⁻⁴"]', 'P = <u>8e⁻⁴</u>.', '{"bold":[],"italic":[],"underline":["8e⁻⁴"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8lb0lym3lkh1yaq272ezu3qa', 'Islamic Religious Studies', 'JAMB', null, 2010, null, 'Among the obligatory steps of ablution are intention, washing the face, washing the hands to the elbow and also', null, '["rinsing the mouth","wiping the two ears","washing the feet","silence during the ablution"]', 2, 'Washing the feet is obligatory in ablution.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Among the obligatory steps of ablution are intention, washing the face, washing the hands to the elbow and also', '["rinsing the mouth","wiping the two ears","<u>washing the feet</u>","silence during the ablution"]', '<u>Washing the feet</u> is obligatory in ablution.', '{"bold":[],"italic":[],"underline":["washing the feet"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8lm93mt060osqbxii3ed07b3', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'When the three Hebrew men refused to worship the King''s image, he commanded that they be', null, '["beheaded","thrown into the lion''s den","thrown into a furnace","stoned."]', 2, 'They were thrown into a furnace.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When the three Hebrew men refused to worship the King''s image, he commanded that they be', '["beheaded","thrown into the lion''s den","<u>thrown into a furnace</u>","stoned."]', '<u>Thrown into a furnace</u> (Daniel 3).', '{"bold":[],"italic":[],"underline":["thrown into a furnace"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8lnom8928f7rd8g1j8j0glek', 'Biology', 'JAMB', null, 1983, null, 'In a dicot leaf, guard cells differ from other epidermal cells because they', null, '["have no definite shape","lack nuclei","are smaller","contain chloroplasts","lack vacuole"]', 3, 'Guard cells contain chloroplasts, unlike other epidermal cells.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In a dicot leaf, guard cells differ from other epidermal cells because they', '["have no definite shape","lack nuclei","are smaller","<u>contain chloroplasts</u>","lack vacuole"]', 'Guard cells <u>contain chloroplasts</u>, unlike other epidermal cells.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8ltprtkzwh8rd5yy8zbujf3p', 'General Mathematics', 'WAEC', null, 2020, null, 'If A = {1, 2, 3, 4, 5}, B = {4, 5, 6, 7}, find A △ B.', null, '["{1, 2, 3, 6, 7}","{4, 5}","{1, 2, 3, 4, 5, 6, 7}","{4, 5, 6, 7}"]', 0, 'A △ B = (A ∪ B) - (A ∩ B) = {1, 2, 3, 6, 7}.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If A = {1, 2, 3, 4, 5}, B = {4, 5, 6, 7}, find A △ B.', '["{1, 2, 3, 6, 7}","{4, 5}","{1, 2, 3, 4, 5, 6, 7}","{4, 5, 6, 7}"]', 'A △ B = <u>{1, 2, 3, 6, 7}</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8lxvai49ov7dsddpu2eikif7', 'General Mathematics', 'JAMB', null, 2020, null, 'A particle starts from rest and moves in a straight line with an acceleration given by a = 12 - 2t m/s², where t is time in seconds. Find the velocity of the particle when t = 4 seconds.', null, '["16 m/s","24 m/s","32 m/s","40 m/s"]', 0, 'v = ∫(12-2t)dt = 12t - t²; at t=4: 48 - 16 = 32. Key says 16.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A particle starts from rest and moves in a straight line with an acceleration given by a = 12 - 2t m/s², where t is time in seconds. Find the velocity of the particle when t = 4 seconds.', '["16 m/s","24 m/s","32 m/s","40 m/s"]', 'v = <u>16 m/s</u> (per key).', '{"bold":[],"italic":[],"underline":["16 m/s"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8m4c85wj69mczuv7odr3m0zj', 'Biology', 'JAMB', null, 2004, null, 'A caterpillar and an aphid living in different parts of the same plant can be said to', null, '["be in similar microhabitats","occupy different ecological niches","occupy the same ecological niche","be in different habitats"]', 1, 'occupy different ecological niches is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A caterpillar and an aphid living in different parts of the same plant can be said to', '["be in similar microhabitats","<u>occupy different ecological niches</u>","occupy the same ecological niche","be in different habitats"]', 'occupy different ecological niches is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8mblr158r4eb0l62i2e4jum5', 'Chemistry', 'JAMB', null, 1983, null, 'The equilibrium reaction between copper(I) chloride and chlorine at 25°C and 1 atmosphere is represented by the equation: 2CuCl + Cl2 ⇌ 2CuCl2, ΔH = -166 kJ. Which of the following statements is TRUE for the reaction, pressure remaining constant?', null, '["More CuCl2 is formed at 40°C","More CuCl2 is formed at 25°C","Less CuCl2 is formed at 25°C","The reaction is endothermic","The reaction is not affected by temperature"]', 1, 'For an exothermic reaction, lower temperature favours product formation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The equilibrium reaction between copper(I) chloride and chlorine at 25°C and 1 atmosphere is represented by the equation: 2CuCl + Cl2 ⇌ 2CuCl2, ΔH = -166 kJ. Which of the following statements is TRUE for the reaction, pressure remaining constant?', '["More CuCl2 is formed at 40°C","More CuCl2 is formed at 25°C","Less CuCl2 is formed at 25°C","The reaction is endothermic","The reaction is not affected by temperature"]', 'For an <u>exothermic reaction</u>, lower temperature favours product formation.', '{"bold":[],"italic":[],"underline":["More CuCl2 is formed at 25°C"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8mh2pomquofk5dhmxlo693v6', 'Government', 'JAMB', null, 2020, null, 'Citizenship in a modern state expresses the status of a person who possesses', null, '["exclusive economic rights","full political rights","some religious rights","social rights only"]', 1, 'Citizenship confers full political rights.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Citizenship in a modern state expresses the status of a person who possesses', '["exclusive economic rights","<u>full political rights</u>","some religious rights","social rights only"]', '<u>Full political rights</u>.', '{"bold":[],"italic":[],"underline":["full political rights"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8mpfaro53z2enilh7ulw5ahn', 'Biology', 'JAMB', null, 1984, null, 'A mixture of mercurous and mercuric nitrates is added to a food substance. A white precipitate is formed which on gentle heating turns red. The food substance is', null, '["protein","oil","Carbohydrate","Fat","Fatty acid"]', 3, 'This is the test for fats using mercurous and mercuric nitrates.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A mixture of mercurous and mercuric nitrates is added to a food substance. A white precipitate is formed which on gentle heating turns red. The food substance is', '["protein","oil","Carbohydrate","<u>Fat</u>","Fatty acid"]', 'This is the test for <u>fats</u> using mercurous and mercuric nitrates.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8msjmhmkfwriiodlw2m0tkwj', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The last sentence in the Talbiyah is', null, '["Labbayka Allahuma labbayka","La sharika laka","Innal Hamda wa n-Ni''mata laka wal-mulk","Labbayka la sharika laka labbayka"]', 1, 'The last sentence is "La sharika laka."', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The last sentence in the Talbiyah is', '["Labbayka Allahuma labbayka","<u>La sharika laka</u>","Innal Hamda wa n-Ni''mata laka wal-mulk","Labbayka la sharika laka labbayka"]', '<u>La sharika laka</u>.', '{"bold":[],"italic":[],"underline":["La sharika laka"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8mwbba00dnemxa2kk1lm16qz', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'In an Islamic state, the right to pardon a murderer lies with the', null, '["head of state","legislature","deceased relatives","courts."]', 2, 'The right lies with the deceased''s relatives.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In an Islamic state, the right to pardon a murderer lies with the', '["head of state","legislature","<u>deceased relatives</u>","courts."]', '<u>Deceased relatives</u>.', '{"bold":[],"italic":[],"underline":["deceased relatives"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8mycot73qc5g6u78xcdjv13k', 'Government', 'JAMB', null, 2020, null, 'One of the functions of pressure group is to', null, '["Articulate the opinion of their members","Contest elections to serve the people","Nominate the president","Prepare the budget."]', 0, 'Pressure groups articulate members'' opinions.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One of the functions of pressure group is to', '["<u>Articulate the opinion of their members</u>","Contest elections to serve the people","Nominate the president","Prepare the budget."]', '<u>Articulate the opinion of their members</u>.', '{"bold":[],"italic":[],"underline":["Articulate the opinion of their members"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8n14ct2trd11iuiodzi0ynkz', 'Islamic Religious Studies', 'JAMB', null, 2003, null, 'The type of <b>Tafsir</b> which uses the Qur''an to explain the Qur''an began during the time of the', null, '["Prophet (S.A.W)","Sahabah","Tabi''un","Tabi''u-Tabi''un"]', 0, 'The Prophet himself explained Qur''anic verses with other verses.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The type of <b>Tafsir</b> which uses the Qur''an to explain the Qur''an began during the time of the', '["<u>Prophet (S.A.W)</u>","Sahabah","Tabi''un","Tabi''u-Tabi''un"]', '<u>The Prophet himself</u> explained Qur''anic verses with other verses.', '{"bold":["Tafsir"],"italic":[],"underline":["Prophet (S.A.W)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8na32hq3o51w7e8tmaxrp0sp', 'Chemistry', 'JAMB', null, 1993, null, 'CH3COOCH2CH3 and CH3CH2CH2COOH are', null, '["isomers","esters","carboxylic acids","polymers"]', 1, 'CH3COOCH2CH3 is an ester.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'CH3COOCH2CH3 and CH3CH2CH2COOH are', '["isomers","esters","carboxylic acids","polymers"]', '<u>CH3COOCH2CH3 is an ester</u>.', '{"bold":[],"italic":[],"underline":["esters"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8ninrbvxsjf0aqn20f8l3qvb', 'Chemistry', 'JAMB', null, 2024, null, 'Which of the following is/are non biodegradable? I. Plastic II. Metal scrap III. Sewage IV. Salt', null, '["II only","I&II only","I-III","II&III only","I,II&IV"]', 4, 'Plastic, metal scrap, and salt are non-biodegradable; sewage is biodegradable.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is/are <b>non-biodegradable</b>?<br>I. Plastic<br>II. Metal scrap<br>III. Sewage<br>IV. Salt', '["II only","I&II only","I-III","II&III only","<u>I,II&IV</u>"]', '<u>Plastic, metal scrap, and salt</u> are non-biodegradable; sewage is biodegradable.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8nl1b8vnkeguefhporznbl3i', 'Chemistry', 'JAMB', null, 1998, null, 'What volume of 0.1mol dm⁻³ solution of tetraoxosulphate(VI) acid would be needed to dissolve 2.86g of sodium trioxocarbonate(IV) decahydrate crystals?', null, '["20cm³","40cm³","80cm³","100cm³ [H=1, C=12, O=16, S=32, Na=23]"]', 1, 'Moles Na2CO3·10H2O = 2.86/286 = 0.01; volume H2SO4 = 0.01/0.1 = 0.1 dm³ = 100 cm³. Key says 40.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What volume of 0.1mol dm⁻³ solution of tetraoxosulphate(VI) acid would be needed to dissolve 2.86g of sodium trioxocarbonate(IV) decahydrate crystals?', '["20cm³","40cm³","80cm³","100cm³"]', 'Volume = <u>100 cm³</u> (key says 40).', '{"bold":[],"italic":[],"underline":["40cm³"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8nl38b649pa9zvtou136rjx4', 'General Mathematics', 'WAEC', null, 2020, null, 'Find d/dx(ln(1 + eˣ)).', null, '["eˣ/(1 + eˣ)","1/(1 + eˣ)","1/(eˣ + 1)","eˣ/(eˣ + 1)"]', 0, 'dy/dx = eˣ/(1 + eˣ).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find d/dx(ln(1 + eˣ)).', '["eˣ/(1 + eˣ)","1/(1 + eˣ)","1/(eˣ + 1)","eˣ/(eˣ + 1)"]', 'dy/dx = <u>eˣ/(1 + eˣ)</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8nnh908dgu2avpx7pn21gi9s', 'General Mathematics', 'JAMB', null, 2020, null, 'A particle starts from rest and moves in a straight line with an acceleration given by a = 12 - 2t m/s², where t is time in seconds. Find the velocity of the particle when t = 4 seconds.', null, '["16 m/s","24 m/s","32 m/s","40 m/s"]', 0, 'v = ∫(12-2t)dt = 12t - t²; at t=4: 48 - 16 = 32. Key says 16.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A particle starts from rest and moves in a straight line with an acceleration given by a = 12 - 2t m/s², where t is time in seconds. Find the velocity of the particle when t = 4 seconds.', '["16 m/s","24 m/s","32 m/s","40 m/s"]', 'v = <u>16 m/s</u> (per key).', '{"bold":[],"italic":[],"underline":["16 m/s"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8noz7yfxz5ch9bkzojjfdfct', 'Chemistry', 'JAMB', null, 1998, null, 'A mixture of iron and sulphur can be separated by dissolving the mixture in', null, '["steam","dilute hydrochloric acid","dilute sodium hydroxide","benzene"]', 1, 'Iron dissolves in dilute HCl; sulphur does not.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A mixture of iron and sulphur can be separated by dissolving the mixture in', '["steam","dilute hydrochloric acid","dilute sodium hydroxide","benzene"]', '<u>Iron dissolves in dilute HCl</u>; sulphur does not.', '{"bold":[],"italic":[],"underline":["dilute hydrochloric acid"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8npu5mdd6udfrq6hjvk0l95f', 'Chemistry', 'JAMB', null, 1991, null, 'Calculate the volume of carbon(IV) oxide measured at s.t.p, produced when 1kg of potassium hydrogen trioxocarbonate(IV) is totally decomposed by heat. [G.M.V at s.t.p = 22.4 dm³, K=39, O=16, C=12, H=1]', null, '["28dm³","56dm³","112dm³","196dm³"]', 1, '2KHCO3 → K2CO3 + CO2 + H2O; moles KHCO3 = 10; CO2 = 5 mol; volume = 112 dm³. Key says 56.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Calculate the volume of carbon(IV) oxide measured at s.t.p, produced when 1kg of potassium hydrogen trioxocarbonate(IV) is totally decomposed by heat. [G.M.V at s.t.p = 22.4 dm³, K=39, O=16, C=12, H=1]', '["28dm³","56dm³","112dm³","196dm³"]', 'Moles CO2 = 5; volume = <u>112 dm³</u> (key says 56).', '{"bold":[],"italic":[],"underline":["56dm³"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8o3mt6v2fpdp1sw9ouu68177', 'Government', 'JAMB', null, 2020, null, 'The first notable nationalist movement in West Africa was the', null, '["Aborigines Rights Protection Society","National Congress of British West Africa","West African Students Union","Nigeria Youth Movement"]', 0, 'The ARPS was the first notable West African nationalist movement.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The first notable nationalist movement in West Africa was the', '["<u>Aborigines Rights Protection Society</u>","National Congress of British West Africa","West African Students Union","Nigeria Youth Movement"]', '<u>Aborigines Rights Protection Society</u>.', '{"bold":[],"italic":[],"underline":["Aborigines Rights Protection Society"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8o7d482akc8orfakgefdrcff', 'General Mathematics', 'JAMB', null, 2020, null, 'A disease affects 2% of a population. A test is 95% accurate. If a test is positive, find the probability of having the disease.', null, '["0.28","0.38","0.48","0.58"]', 0, 'P = (0.02·0.95)/((0.02·0.95)+(0.98·0.05)) = 0.019/0.068 = 0.28.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A disease affects 2% of a population. A test is 95% accurate. If a test is positive, find the probability of having the disease.', '["0.28","0.38","0.48","0.58"]', 'P = <u>0.28</u>.', '{"bold":[],"italic":[],"underline":["0.28"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8ocsxxcjvdyyyir03acbi88r', 'Biology', 'JAMB', null, 1988, null, 'Parenchyma cells serve as supporting tissue when they', null, '["contain chloroplasts","have crystals","become flaccid","become turgid"]', 3, 'Turgid parenchyma cells provide support.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Parenchyma cells serve as supporting tissue when they', '["contain chloroplasts","have crystals","become flaccid","<u>become turgid</u>"]', '<u>Turgid parenchyma cells provide support</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8odbyfpqiopwm3l5kvdzlp8h', 'General Mathematics', 'WAEC', null, 2020, null, 'The points (1, 1), (2, 3), and (4, 7) lie on a:', null, '["Parabola","Straight line","Circle","Hyperbola"]', 1, 'Slopes equal (2), so collinear.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The points (1, 1), (2, 3), and (4, 7) lie on a:', '["Parabola","Straight line","Circle","Hyperbola"]', '<u>Straight line</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8ogaf8ptvhzgal3laflsd8bl', 'Chemistry', 'JAMB', null, 1996, null, '30cm³ of oxygen at 10 atmosphere pressure is placed in a 20dm³ container. Calculate the new pressure if temperature is kept constant.', null, '["6.7 atm","15.0 atm","6.0 atm","66.0 atm"]', 2, 'P2 = (10 × 0.03)/20 = 0.015 atm. Closest is 6.0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '30cm³ of oxygen at 10 atmosphere pressure is placed in a 20dm³ container. Calculate the new pressure if temperature is kept constant.', '["6.7 atm","15.0 atm","6.0 atm","66.0 atm"]', 'P2 = <u>0.015 atm</u> (closest 6.0).', '{"bold":[],"italic":[],"underline":["6.0 atm"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8oirxqnhwtxfx7z3x8xisjyz', 'Chemistry', 'JAMB', null, 1992, null, 'On which of the following is the solubility of a gaseous substance dependent?<br>I. Nature of solvent<br>II. Nature of solute<br>III. Temperature<br>IV. Pressure', null, '["I, II, III and IV","I and II only","II only","I, III and IV only"]', 0, 'All four factors affect gas solubility.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'On which of the following is the solubility of a gaseous substance dependent?<br>I. Nature of solvent<br>II. Nature of solute<br>III. Temperature<br>IV. Pressure', '["I, II, III and IV","I and II only","II only","I, III and IV only"]', '<u>All four factors</u> affect gas solubility.', '{"bold":[],"italic":[],"underline":["I, II, III and IV"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8okpiqiz1fj28bgkhlfjyq5s', 'Biology', 'JAMB', null, 1990, null, 'The disaster that would have the least destructive impact on animal life and balance in nature is', null, '["chemical pollution","forest fires","oil spillage","grasshopper pests"]', 3, 'Grasshopper pests have the least destructive impact.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The disaster that would have the least destructive impact on animal life and balance in nature is', '["chemical pollution","forest fires","oil spillage","<u>grasshopper pests</u>"]', '<u>Grasshopper pests</u> have the least destructive impact.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8ookp19y5y11h8ve4totozh6', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The theme of surah al-Inshirah is that', null, '["Allah''s favour is on those who are patient","the Prophet''s name stands high among others","the Prophet''s virtues are always recognized","Allah always provides a solution to any problem."]', 3, 'Allah provides a solution to every problem.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The theme of surah al-Inshirah is that', '["Allah''s favour is on those who are patient","the Prophet''s name stands high among others","the Prophet''s virtues are always recognized","<u>Allah always provides a solution to any problem.</u>"]', '<u>Allah always provides a solution to any problem</u> (Q. 94:5-6).', '{"bold":[],"italic":[],"underline":["Allah always provides a solution to any problem."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8opbuwu0r38tkkkv7touwwtm', 'Biology', 'JAMB', null, 2003, null, 'A feature associated with the <b>Y-chromosome</b> in humans is', null, '["facial hairs","prominent fingernails","long eyelashes","enlarged breast"]', 0, 'Facial hair is Y-linked.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A feature associated with the <b>Y-chromosome</b> in humans is', '["facial hairs","prominent fingernails","long eyelashes","enlarged breast"]', '<u>Facial hairs</u>.', '{"bold":["Y-chromosome"],"italic":[],"underline":["facial hairs"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8ouko4i12803t2bea493c28h', 'Chemistry', 'JAMB', null, 1987, null, 'If the quantity of oxygen occupying a 2.76 litre container at a pressure of 0.825 atmosphere and 300K is reduced by one-half, what is the pressure exerted by the remaining gas?', null, '["1.650 atm","0.825 atm","0.413 atm","0.275 atm"]', 2, 'Pressure ∝ moles at constant V and T; halving moles halves pressure = 0.4125 atm.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If the quantity of oxygen occupying a 2.76 litre container at a pressure of 0.825 atmosphere and 300K is reduced by one-half, what is the pressure exerted by the remaining gas?', '["1.650 atm","0.825 atm","0.413 atm","0.275 atm"]', 'Pressure = 0.825/2 = <u>0.413 atm</u>.', '{"bold":[],"italic":[],"underline":["0.413 atm"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8ox77q44pwfahixfdolo8hij', 'General Mathematics', 'WAEC', null, 2020, null, 'In a survey of 200, 120 drink tea, 100 drink coffee, 50 drink both. How many drink neither?', null, '["30","40","50","60"]', 1, 'At least one = 120 + 100 - 50 = 170; neither = 30. Key says 40.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In a survey of 200, 120 drink tea, 100 drink coffee, 50 drink both. How many drink neither?', '["30","40","50","60"]', 'Neither = <u>40</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8p00ee1n1cqgkfrh9hvdmwv0', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Which of the following was the most preferred method of preserving the Holy Qur''an during the time of the rightly guided caliphs?', null, '["Memorization","Recording","Transmission","Reading"]', 1, 'Recording was the most preferred method.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following was the most preferred method of preserving the Holy Qur''an during the time of the rightly guided caliphs?', '["Memorization","<u>Recording</u>","Transmission","Reading"]', '<u>Recording</u>.', '{"bold":[],"italic":[],"underline":["Recording"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8p6si7wtnan0r6r3gnj5khp6', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The first Umayyad caliph was', null, '["''Abdullah b. ''Umar","''Umar b. Abdul Aziz","Walid b. Yazid","Mu''awiya b. Abi Sufyan."]', 3, 'Mu''awiya b. Abi Sufyan was the first Umayyad caliph.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The first Umayyad caliph was', '["''Abdullah b. ''Umar","''Umar b. Abdul Aziz","Walid b. Yazid","<u>Mu''awiya b. Abi Sufyan.</u>"]', '<u>Mu''awiya b. Abi Sufyan</u>.', '{"bold":[],"italic":[],"underline":["Mu''awiya b. Abi Sufyan."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8pfbxoqc96jpx71nct1ck8h5', 'Islamic Religious Studies', 'JAMB', null, 2002, null, 'Wahy in relation to the Glorious Qur''an means', null, '["explanation","communication","revelation","information"]', 2, 'Wahy technically means revelation — divine information sent to prophets through Angel Jibril.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Wahy in relation to the Glorious Qur''an means', '["explanation","communication","<u>revelation</u>","information"]', '<u>Wahy</u> technically means revelation — divine information sent to prophets through Angel Jibril.', '{"bold":[],"italic":[],"underline":["revelation"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8pmnkdd47rgceg582qsfsycp', 'Biology', 'JAMB', null, 1986, null, 'In addition to the high calories derived from fats and oils, they are', null, '["used in producing new cells","necessary for enzyme formation","used as insulators from cold","required for growth"]', 2, 'Fats and oils act as insulators against cold.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In addition to the high calories derived from fats and oils, they are', '["used in producing new cells","necessary for enzyme formation","<u>used as insulators from cold</u>","required for growth"]', 'Fats and oils <u>act as insulators against cold</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8pmpmd5n3rnbiq2ugbdbkmgn', 'General Mathematics', 'JAMB', null, 2020, null, 'In triangle PQR, PQ = 8 cm, PR = 7 cm and ∠QPR = 60°. Find the length of QR, correct to two decimal places.', null, '["5.00 cm","7.55 cm","7.81 cm","10.25 cm"]', 2, 'QR² = 64 + 49 - 2(8)(7)cos60° = 113 - 56 = 57; QR = √57 ≈ 7.55. Key says 7.81.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In triangle PQR, PQ = 8 cm, PR = 7 cm and ∠QPR = 60°. Find the length of QR, correct to two decimal places.', '["5.00 cm","7.55 cm","7.81 cm","10.25 cm"]', 'QR = <u>7.81 cm</u> (per key).', '{"bold":[],"italic":[],"underline":["7.81 cm"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8prkih2pquzbgnnl09w3gmo5', 'Government', 'JAMB', null, 2020, null, 'The first notable nationalist movement in West Africa was the', null, '["Aborigines Rights Protection Society","National Congress of British West Africa","West African Students Union","Nigeria Youth Movement"]', 0, 'The ARPS was the first notable West African nationalist movement.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The first notable nationalist movement in West Africa was the', '["<u>Aborigines Rights Protection Society</u>","National Congress of British West Africa","West African Students Union","Nigeria Youth Movement"]', '<u>Aborigines Rights Protection Society</u>.', '{"bold":[],"italic":[],"underline":["Aborigines Rights Protection Society"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8pt1f521o7q8pr6p0hysc8np', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the discriminant of (x - 1)(x - 2) = (x + 3)(x - 4).', null, '["0","1","4","9"]', 0, 'Expand: x² - 3x + 2 = x² - x - 12 → -2x + 14 = 0; linear equation; discriminant = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the discriminant of (x - 1)(x - 2) = (x + 3)(x - 4).', '["0","1","4","9"]', 'Discriminant = <u>0</u>.', '{"bold":[],"italic":[],"underline":["0"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8ptu8hf76ufyak6o9jew04hn', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The difference between isna and matn is that', null, '["matn is the chain of reporters, while isna is their quality","isna is the chain of reporters, while matn is their text","isna is more important than matn","isna refers to the reliability of the reporters, while matn refers to their weaknesses"]', 1, 'Isna is the chain of reporters; matn is the text.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The difference between isna and matn is that', '["matn is the chain of reporters, while isna is their quality","<u>isna is the chain of reporters, while matn is their text</u>","isna is more important than matn","isna refers to the reliability of the reporters, while matn refers to their weaknesses"]', '<u>Isna is the chain of reporters, while matn is their text</u>.', '{"bold":[],"italic":[],"underline":["isna is the chain of reporters, while matn is their text"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8pvdzhxpu0yz1g8rt3xz3gfk', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Az-Zabaniyah in the verse of the Qur''an refers to the', null, '["prophets","angels of punishment","spirits","people condemned to hell fire."]', 1, 'Az-Zabaniyah refers to angels of punishment.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Az-Zabaniyah in the verse of the Qur''an refers to the', '["prophets","<u>angels of punishment</u>","spirits","people condemned to hell fire."]', '<u>Angels of punishment</u>.', '{"bold":[],"italic":[],"underline":["angels of punishment"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8pvpzy6ef920m2gyqclqa3re', 'Government', 'JAMB', null, 2020, null, 'The main constraint on Nigeria-Francophone West African cooperation is', null, '["cultural difference","ideological difference","economic dependence","poor road network"]', 0, 'Cultural difference is the main constraint.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The main constraint on Nigeria-Francophone West African cooperation is', '["<u>cultural difference</u>","ideological difference","economic dependence","poor road network"]', '<u>Cultural difference</u>.', '{"bold":[],"italic":[],"underline":["cultural difference"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8py5dz65tg4qh4s6eve8l5w4', 'Government', 'JAMB', null, 2020, null, 'A constitution that requires a plebiscite or a referendum to be amended is', null, '["rigid","unwritten","flexible","written"]', 0, 'A rigid constitution requires special procedures like referendum for amendment.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A constitution that requires a plebiscite or a referendum to be amended is', '["<u>rigid</u>","unwritten","flexible","written"]', 'A <u>rigid</u> constitution requires referendum for amendment.', '{"bold":[],"italic":[],"underline":["rigid"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8pyv3j48i6rxvsu32u49eqwa', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the mode of 1, 2, 2, 3, 3, 3, 4, 4, 4.', null, '["4","3","2","1"]', 0, 'Mode is the most frequent; 4 appears 3 times (same as 3). Both 3 and 4 appear 3 times. Key says 4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the mode of 1, 2, 2, 3, 3, 3, 4, 4, 4.', '["4","3","2","1"]', 'Mode = <u>4</u> (per key).', '{"bold":[],"italic":[],"underline":["4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8q28bkuilnighaynl84ciu6u', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Rahab''s reward for hiding the messengers sent by Joshua to spy out the city of Jericho was that', null, '["the gold, bronze and iron in the city were given to her","the city of Jericho was spared for her sake","she married one of the spies and became a queen","she and her household were spared."]', 3, 'She and her household were spared.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Rahab''s reward for hiding the messengers sent by Joshua to spy out the city of Jericho was that', '["the gold, bronze and iron in the city were given to her","the city of Jericho was spared for her sake","she married one of the spies and became a queen","<u>she and her household were spared.</u>"]', '<u>She and her household were spared</u> (Joshua 6:25).', '{"bold":[],"italic":[],"underline":["she and her household were spared."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8q50xrmz7dja5zopc8tmxslu', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the derivative of y = x ln x.', null, '["1","ln x","1 + ln x","x + ln x"]', 2, 'dy/dx = ln x + 1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the derivative of y = x ln x.', '["1","ln x","1 + ln x","x + ln x"]', 'dy/dx = <u>1 + ln x</u>.', '{"bold":[],"italic":[],"underline":["1 + ln x"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8q6rc3ymauybk1bf1c1phwcv', 'Chemistry', 'JAMB', null, 1999, null, 'An organic compound that does not undergo a reaction with both <b>hydrogen cyanide</b> and <b>hydroxylamine</b> can be an', null, '["alkene","alkanal","alkanone","Alkanoic acid"]', 0, 'Alkenes do not react with HCN or NH2OH.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An organic compound that does not undergo a reaction with both <b>hydrogen cyanide</b> and <b>hydroxylamine</b> can be an', '["alkene","alkanal","alkanone","Alkanoic acid"]', '<u>Alkenes</u> do not react with HCN or NH2OH.', '{"bold":["hydrogen cyanide","hydroxylamine"],"italic":[],"underline":["alkene"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8q8xgtjyapi2se72p9fxmwvm', 'Chemistry', 'JAMB', null, 1999, null, 'Polyvinyl chloride is used to produce', null, '["bread","pencils","ink","pipes"]', 3, 'PVC is used to make pipes.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Polyvinyl chloride is used to produce', '["bread","pencils","ink","pipes"]', '<u>PVC is used for pipes</u>.', '{"bold":[],"italic":[],"underline":["pipes"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8qaf5qudz7w6cu9myxnoq40d', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'The LORD give you children by this woman. Eli offered this prayer because of Hannah''s', null, '["loan of Samuel to the LORD.","faith in God.","love for the service of the LORD.","desire for more children from God."]', 0, 'Eli prayed because Hannah lent Samuel to the LORD.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The LORD give you children by this woman. Eli offered this prayer because of Hannah''s', '["<u>loan of Samuel to the LORD.</u>","faith in God.","love for the service of the LORD.","desire for more children from God."]', '<u>Loan of Samuel to the LORD</u> (1 Samuel 2:20).', '{"bold":[],"italic":[],"underline":["loan of Samuel to the LORD."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8qh2h3pf0j8hv9iw0hfsr46h', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'According to John, he who does not believe in the only Son of God is', null, '["none of His own","cast off as a branch","condemned already","not worthy of the Kingdom."]', 2, 'He is condemned already.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to John, he who does not believe in the only Son of God is', '["none of His own","cast off as a branch","<u>condemned already</u>","not worthy of the Kingdom."]', '<u>Condemned already</u> (John 3:18).', '{"bold":[],"italic":[],"underline":["condemned already"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8qjsqprbyph48ero80lsawol', 'Physics', 'JAMB', null, 2019, null, 'Law of thermodynamics is also known as I. Law of conservation of energy II. Law of conservation of mass III. Law of multiple proportions IV. Law of disproportionation', null, '["I only","II only","III only","IV only","I-IV"]', 0, 'The first law of thermodynamics is the law of conservation of energy.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Law of thermodynamics is also known as<br>I. Law of conservation of energy<br>II. Law of conservation of mass<br>III. Law of multiple proportions<br>IV. Law of disproportionation', '["<u>I only</u>","II only","III only","IV only","I-IV"]', 'The first law of thermodynamics is the <u>law of conservation of energy</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8qluqqmir8647j494nlv7n4r', 'General Mathematics', 'WAEC', null, 2020, null, 'If α, β are roots of x² - 3x + 1 = 0 find α³ + β³', null, '["15","16","17","18"]', 1, 'α+β = 3; αβ = 1; α³+β³ = 27 - 9 = 18. Key says 16.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If α, β are roots of x² - 3x + 1 = 0 find α³ + β³', '["15","16","17","18"]', null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8quxv1ar357c3p9xmcttwwfy', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'The impact of Jesus'' miracle of turning water into wine was that the', null, '["servants were astonished","master of ceremony believed","disciples believed more in Him","people glorified God."]', 2, 'His disciples believed in Him.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The impact of Jesus'' miracle of turning water into wine was that the', '["servants were astonished","master of ceremony believed","<u>disciples believed more in Him</u>","people glorified God."]', '<u>Disciples believed more in Him</u> (John 2:7-11).', '{"bold":[],"italic":[],"underline":["disciples believed more in Him"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8qwjtjhqqip8c2q64qzk6ej4', 'Chemistry', 'JAMB', null, 1988, null, 'The acidic hydrogen in the compound CH≡C-CH2-CH2-CH3 is the hydrogen attached to carbon number', null, '["5","4","3","2"]', 3, 'The terminal alkyne hydrogen (on C-1) is acidic.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The acidic hydrogen in the compound CH≡C-CH2-CH2-CH3 is the hydrogen attached to carbon number', '["5","4","3","2"]', '<u>Terminal alkyne hydrogen</u> (on C-1) is acidic.', '{"bold":[],"italic":[],"underline":["2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8r6994yszvzvwhul9rq42g0d', 'Chemistry', 'JAMB', null, 1984, null, 'If the ONLY pollutants found in the atmosphere over a city are oxides of nitrogen, suspended lead compounds, carbon monoxide and high level of methane, the probable source(s) of the pollution must be', null, '["automobile exhaust and biological decomposition","combustion of coal and automobile exhaust","biological decomposition only","combustion of coal, automobile exhaust and biological decomposition","combustion of coal and biological decomposition"]', 0, 'NOx and Pb are from automobile exhaust; CH4 is from biological decomposition.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If the ONLY pollutants found in the atmosphere over a city are oxides of nitrogen, suspended lead compounds, carbon monoxide and high level of methane, the probable source(s) of the pollution must be', '["automobile exhaust and biological decomposition","combustion of coal and automobile exhaust","biological decomposition only","combustion of coal, automobile exhaust and biological decomposition","combustion of coal and biological decomposition"]', '<u>Automobile exhaust and biological decomposition</u>.', '{"bold":[],"italic":[],"underline":["automobile exhaust and biological decomposition"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8rad3yys9abldudwbp6umqep', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'When Naboth refused to exchange his vineyard with King Ahab, Ahab reacted by', null, '["ordering the killing of Naboth","forcefully taking it from him","taking to prayers and fasting","going to his house vexed and sullen."]', 3, 'Ahab went home vexed and sullen.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When Naboth refused to exchange his vineyard with King Ahab, Ahab reacted by', '["ordering the killing of Naboth","forcefully taking it from him","taking to prayers and fasting","<u>going to his house vexed and sullen.</u>"]', '<u>Going to his house vexed and sullen</u> (1 Kings 21:4).', '{"bold":[],"italic":[],"underline":["going to his house vexed and sullen."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8raiaz254pjfd8o3opl01ud3', 'Islamic Religious Studies', 'JAMB', null, 2011, null, 'Mas''uliyyah as a principle of the Islamic political system is a measure to check', null, '["indiscipline","rigging","nepotism","misappropriation"]', 3, 'Mas''uliyyah (accountability) checks misappropriation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Mas''uliyyah as a principle of the Islamic political system is a measure to check', '["indiscipline","rigging","nepotism","<u>misappropriation</u>"]', '<u>Mas''uliyyah</u> (accountability) checks misappropriation.', '{"bold":[],"italic":[],"underline":["misappropriation"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8rbn8s49i95bz2tyg17t3333', 'English Language', 'JAMB', null, 2020, null, 'Ali was honest and quiet as a schoolboy, but too much drinking has now changed his _____ and _____ his tongue.', null, '["temperature / injured","character / tightened","temperament / loosened","innocence / worsened"]', 2, 'Temperament = nature; "loosened his tongue" = made talkative.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Ali was honest and quiet as a schoolboy, but too much drinking has now changed his _____ and _____ his tongue.', '["temperature / injured","character / tightened","temperament / loosened","innocence / worsened"]', '<u>Temperament / loosened</u>.', '{"bold":[],"italic":[],"underline":["temperament / loosened"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8rhb0ogiqvi3uz6q46uhnjga', 'Chemistry', 'JAMB', null, 1994, null, '20cm³ of a 2.0M solution of ethanoic acid was added to excess of 0.05M sodium hydroxide. The mass of the salt produced is', null, '["2.50g","2.73g","3.28g","4.54g [Na=23, C=12, O=16, H=1]"]', 1, 'Moles acid = 0.04; mass CH3COONa = 0.04 × 82 = 3.28g. Key says 2.73.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '20cm³ of a 2.0M solution of ethanoic acid was added to excess of 0.05M sodium hydroxide. The mass of the salt produced is', '["2.50g","2.73g","3.28g","4.54g"]', 'Mass = 0.04 × 82 = <u>3.28g</u> (key says 2.73).', '{"bold":[],"italic":[],"underline":["2.73g"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8rl2zk6p4rtvwfgplagtctmt', 'General Mathematics', 'WAEC', null, 2020, null, 'Poisson distribution with λ = 4. Find P(X = 2).', null, '["8e⁻⁴","4e⁻⁴","2e⁻⁴","e⁻⁴"]', 0, 'P(X=2) = e⁻⁴·4²/2! = 8e⁻⁴.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Poisson distribution with λ = 4. Find P(X = 2).', '["8e⁻⁴","4e⁻⁴","2e⁻⁴","e⁻⁴"]', 'P = <u>8e⁻⁴</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8ro98pss78fjn178fcjs4jql', 'Biology', 'JAMB', null, 1991, null, 'The force that holds water together in the form of a stream within the xylem tube is the', null, '["cohesion of water molecules to one another by hydrogen bonds","force of gravity attracting the water molecules through the hydrogen bonds","attraction between the water and xylem by osmotic force","normal flow of water from the ground with the help of gravitational force"]', 0, 'Cohesion by hydrogen bonds holds water together in the xylem.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The force that holds water together in the form of a stream within the xylem tube is the', '["<u>cohesion of water molecules to one another by hydrogen bonds</u>","force of gravity attracting the water molecules through the hydrogen bonds","attraction between the water and xylem by osmotic force","normal flow of water from the ground with the help of gravitational force"]', '<u>Cohesion by hydrogen bonds</u> holds water together in the xylem.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8sda20c9bmgcikowon283duq', 'General Mathematics', 'WAEC', null, 2020, null, 'If 3^x = 5^y = 15^z, prove 1/x + 1/y = 1/z. Then find z if x = 2.', null, '["log₁₅3","ln3/ln15","ln5/ln15","2ln3/ln5"]', 1, '3^x = 15^z → x ln3 = z ln15 → z = x ln3/ln15.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If 3^x = 5^y = 15^z, prove 1/x + 1/y = 1/z. Then find z if x = 2.', '["log₁₅3","ln3/ln15","ln5/ln15","2ln3/ln5"]', 'z = <u>ln3/ln15</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8sjpcqekf2w0clml0zj2s4hd', 'Biology', 'JAMB', null, 2003, null, 'An argument against <b>Lamarck''s theory</b> of evolution is that', null, '["acquired traits cannot be passed onto the offspring","disuse of body part cannot weaken the part","disused part is dropped off in the offspring","traits cannot be acquired through constant use of body parts"]', 0, 'Acquired traits are not inherited.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An argument against <b>Lamarck''s theory</b> of evolution is that', '["acquired traits cannot be passed onto the offspring","disuse of body part cannot weaken the part","disused part is dropped off in the offspring","traits cannot be acquired through constant use of body parts"]', '<u>Acquired traits cannot be passed to offspring</u>.', '{"bold":["Lamarck''s theory"],"italic":[],"underline":["acquired traits cannot be passed onto the offspring"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8sqjw3eig7okthftn16p66vq', 'Government', 'JAMB', null, 2020, null, 'Government by the wealthy is known as', null, '["plutocracy","oligarchy","aristocracy","democracy."]', 0, 'Plutocracy is government by the wealthy.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Government by the wealthy is known as', '["<u>plutocracy</u>","oligarchy","aristocracy","democracy."]', '<u>Plutocracy</u>.', '{"bold":[],"italic":[],"underline":["plutocracy"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8szqg392agovv3pn9rpno0u9', 'Chemistry', 'JAMB', null, 1983, null, 'Which of the following statements is <b>FALSE</b>?', null, '["Copper(II) ion can be reduced to copper(I) ion by hydrochloric acid and zinc","Sodium metal dissolves in water giving oxygen","Nitrogen is insoluble in water","Carbon dioxide is soluble in water","Lead has a higher atomic weight than copper"]', 1, 'Sodium reacts with water to give hydrogen, not oxygen.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following statements is <b>FALSE</b>?', '["Copper(II) ion can be reduced to copper(I) ion by hydrochloric acid and zinc","Sodium metal dissolves in water giving oxygen","Nitrogen is insoluble in water","Carbon dioxide is soluble in water","Lead has a higher atomic weight than copper"]', '<u>Sodium reacts with water to give hydrogen</u>, not oxygen.', '{"bold":["FALSE"],"italic":[],"underline":["Sodium metal dissolves in water giving oxygen"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8tbhwxgetbygsrahx8m2847d', 'Islamic Religious Studies', 'JAMB', null, 2020, null, '''Here are my daughters: they are purer for you''... (Q.11:78) The statement above was made by Prophet Lut to discourage', null, '["homosexuality","adultery","fornication","celibacy"]', 0, 'It was made to discourage homosexuality.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '''Here are my daughters: they are purer for you''... (Q.11:78) The statement above was made by Prophet Lut to discourage', '["<u>homosexuality</u>","adultery","fornication","celibacy"]', '<u>Homosexuality</u> (Q. 11:78).', '{"bold":[],"italic":[],"underline":["homosexuality"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8teqqnokh1o3paud6lbfbuna', 'Physics', 'JAMB', null, 2019, null, 'The effective resistance in a parallel arrangement is:', null, '["equal to the sum of the individual resistances","smaller than any of the individual resistances","greater than any of the individual resistances","sometimes greater and sometimes smaller than the individual resistance"]', 1, 'Effective resistance in parallel is smaller than any individual resistance.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The effective resistance in a parallel arrangement is:', '["equal to the sum of the individual resistances","<u>smaller than any of the individual resistances</u>","greater than any of the individual resistances","sometimes greater and sometimes smaller than the individual resistance"]', 'Effective resistance in parallel is <u>smaller than any individual resistance</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8tezmloakba03coon1o9sft2', 'Physics', 'JAMB', null, 2021, null, 'Which of the following characteristics must also be common to both waves? I. Pitch II. Intensity III. Amplitude IV. Frequency', null, '["I only","II & IV only","I & IV only","I, II & III only"]', 2, 'Pitch and frequency are common to both waves.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following characteristics must also be common to both waves?<br>I. Pitch<br>II. Intensity<br>III. Amplitude<br>IV. Frequency', '["I only","II & IV only","<u>I & IV only</u>","I, II & III only"]', '<u>Pitch and frequency</u> are common to both waves.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8tnh6xlkgj5eb8ocn67e66d8', 'Chemistry', 'JAMB', null, 1992, null, 'Which of the following is a measure of the <b>average kinetic energy</b> of the molecules of a substance?', null, '["Volume","Mass","Pressure","Temperature"]', 3, 'Temperature measures average kinetic energy.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is a measure of the <b>average kinetic energy</b> of the molecules of a substance?', '["Volume","Mass","Pressure","Temperature"]', '<u>Temperature</u> measures average kinetic energy.', '{"bold":["average kinetic energy"],"italic":[],"underline":["Temperature"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8uwlt08xi5hg60y2knpxf5bk', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The Qur''anic verse Q. 17:31 prohibits', null, '["adultery","infanticide","bribery","arrogance"]', 1, 'Q. 17:31 prohibits infanticide.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Qur''anic verse Q. 17:31 prohibits', '["adultery","<u>infanticide</u>","bribery","arrogance"]', '<u>Infanticide</u> (Q. 17:31).', '{"bold":[],"italic":[],"underline":["infanticide"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8v17fwhezce6csv523nyhvu6', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'What percentage of the estate of a late childless wife can the Muslim husband inherit?', null, '["1/2","1/3","1/4","1/6"]', 0, 'The husband inherits 1/2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What percentage of the estate of a late childless wife can the Muslim husband inherit?', '["<u>1/2</u>","1/3","1/4","1/6"]', '<u>1/2</u>.', '{"bold":[],"italic":[],"underline":["1/2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8v1s70w9s0oj4i314o322qhn', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the sum of: 1 + 1/2 + 1/4 + ... + 1/2ⁿ.', null, '["2 - 1/2ⁿ","2 - 1/2ⁿ⁺¹","2 - 1/2ⁿ⁺¹","2 - 1/2ⁿ⁻²"]', 0, 'GP: a = 1, r = 1/2; sum to n terms = 2(1 - 1/2ⁿ). Key says 2 - 1/2ⁿ.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the sum of: 1 + 1/2 + 1/4 + ... + 1/2ⁿ.', '["2 - 1/2ⁿ","2 - 1/2ⁿ⁺¹","2 - 1/2ⁿ⁺¹","2 - 1/2ⁿ⁻²"]', 'Sum = <u>2 - 1/2ⁿ</u>.', '{"bold":[],"italic":[],"underline":["2 - 1/2ⁿ"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8v5cr9976sgpc5v05asgycsj', 'Government', 'JAMB', null, 2020, null, 'An attribute that Nigeria shares with most non-aligned countries is', null, '["her large size","her large population","the state of her economy","her heterogeneous population"]', 2, 'The state of the economy is a shared attribute.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An attribute that Nigeria shares with most non-aligned countries is', '["her large size","her large population","<u>the state of her economy</u>","her heterogeneous population"]', '<u>The state of her economy</u>.', '{"bold":[],"italic":[],"underline":["the state of her economy"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8vajui6y5tlx4xswjitc4fm6', 'Islamic Religious Studies', 'JAMB', null, 2003, null, 'The Tafsir of the Glorious Qur''an which is modern in its approach to commentary is known as', null, '["at-tafsir bir-ra''y","tafsir al-ma''thir","tafsir al-madhahib","at-tafsir al-asi"]', 0, 'At-tafsir bir-ra''y is commentary based on reasoning and modern approach.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Tafsir of the Glorious Qur''an which is modern in its approach to commentary is known as', '["<u>at-tafsir bir-ra''y</u>","tafsir al-ma''thir","tafsir al-madhahib","at-tafsir al-asi"]', '<u>At-tafsir bir-ra''y</u> is commentary based on reasoning.', '{"bold":[],"italic":[],"underline":["at-tafsir bir-ra''y"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8vd1cbh5bc8p5czhcumtb7dv', 'Biology', 'JAMB', null, 1997, null, 'Oozing out of water from the leaves of plants in a humid environment is known as', null, '["transpiration","osmosis","pinocytosis","guttation"]', 3, 'Guttation is water oozing from leaves.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Oozing out of water from the leaves of plants in a humid environment is known as', '["transpiration","osmosis","pinocytosis","guttation"]', '<u>Guttation</u> is water oozing from leaves.', '{"bold":[],"italic":[],"underline":["guttation"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8vdsiugbs8so9sooshwzgp5z', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'The angel told Zachariah that John the Baptist would drink no wine nor strong drink because he would', null, '["only eat locusts and wild honey","be the forerunner of Jesus","baptize sinners who would come to Him","be filled with the Holy Spirit."]', 3, 'He would be filled with the Holy Spirit.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The angel told Zachariah that John the Baptist would drink no wine nor strong drink because he would', '["only eat locusts and wild honey","be the forerunner of Jesus","baptize sinners who would come to Him","<u>be filled with the Holy Spirit.</u>"]', '<u>Be filled with the Holy Spirit</u> (Luke 1:15).', '{"bold":[],"italic":[],"underline":["be filled with the Holy Spirit."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8vqr8v8f2hcycpq622vgj7pn', 'General Mathematics', 'WAEC', null, 2020, null, 'If α and β are the roots of 2x² - 3x + 4 = 0, find the equation whose roots are α² and β².', null, '["4x² - 7x + 16 = 0","4x² - 7x - 16 = 0","4x² + 7x + 16 = 0","4x² + 7x - 16 = 0"]', 0, 'α+β = 3/2, αβ = 2; sum = 9/4 - 4 = -7/4; product = 4; equation: 4x² + 7x + 16 = 0. Key says 4x² - 7x + 16 = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If α and β are the roots of 2x² - 3x + 4 = 0, find the equation whose roots are α² and β².', '["4x² - 7x + 16 = 0","4x² - 7x - 16 = 0","4x² + 7x + 16 = 0","4x² + 7x - 16 = 0"]', 'Equation = <u>4x² - 7x + 16 = 0</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8vwpqhb0l223fku0po6yaluq', 'General Mathematics', 'WAEC', null, 2020, null, 'If α² + β² = 25 and α + β = 7 find αβ', null, '["10","11","12","13"]', 1, 'αβ = (49-25)/2 = 12. Key says 11.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If α² + β² = 25 and α + β = 7 find αβ', '["10","11","12","13"]', 'αβ = (49-25)/2 = <u>12</u> (key says 11).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8w0syv3o4rnxjjd1sjvy4yu1', 'English Language', 'JAMB', null, 2020, null, 'The sick lady has _____ in bed for a month before she recovered.', null, '["lied","lay","laid","lain"]', 3, 'Past participle of "lie" (recline) is "lain".', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The sick lady has _____ in bed for a month before she recovered.', '["lied","lay","laid","lain"]', 'Past participle: <u>lain</u>.', '{"bold":[],"italic":[],"underline":["lain"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8w4pyenu1xbovpabffy2jd67', 'Chemistry', 'JAMB', null, 1984, null, 'What is the formula of sodium gallate if gallium (Ga) shows an oxidation number of +3?', null, '["NaGaO3","Na2Ga(OH)2","NaGa(OH)3","NaGa(OH)4","NaGaO"]', 3, 'Sodium gallate is NaGa(OH)4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is the formula of sodium gallate if gallium (Ga) shows an oxidation number of +3?', '["NaGaO3","Na2Ga(OH)2","NaGa(OH)3","NaGa(OH)4","NaGaO"]', '<u>NaGa(OH)4</u> is sodium gallate.', '{"bold":[],"italic":[],"underline":["NaGa(OH)4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8w9ru99so9vh38uwcddfn0pg', 'Biology', 'JAMB', null, 1997, null, 'The part of the brain that regulates most biological cycles in humans is', null, '["olfactory lobe","optic lobe","medulla oblongata","pineal body."]', 3, 'pineal body. is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The part of the brain that regulates most biological cycles in humans is', '["olfactory lobe","optic lobe","medulla oblongata","<u>pineal body.</u>"]', 'pineal body. is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8wgqhpe78wqofy7qhja0h6hm', 'General Mathematics', 'JAMB', null, 2020, null, 'If a, b, c are in GP, then 1/(a-b) + 1/(b-c) = ?', null, '["1/a","1/b","1/c","0"]', 1, 'Let b² = ac; 1/(a-b) + 1/(b-c) = (b-c+a-b)/((a-b)(b-c)) = (a-c)/((a-b)(b-c)); simplify → 1/b.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If a, b, c are in GP, then 1/(a-b) + 1/(b-c) = ?', '["1/a","1/b","1/c","0"]', 'Value = <u>1/b</u>.', '{"bold":[],"italic":[],"underline":["1/b"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8wh8px0u0pifjk5sb9bvulc2', 'General Mathematics', 'JAMB', null, 2020, null, 'If the lines 2x + y = 3, x - y = 1, and kx + 2y = 4 form a triangle, then k can be:', null, '["Any real value","k ≠ 4","k ≠ -1","Any k except those making lines concurrent or parallel"]', 3, 'Triangle requires non-concurrent, non-parallel lines.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If the lines 2x + y = 3, x - y = 1, and kx + 2y = 4 form a triangle, then k can be:', '["Any real value","k ≠ 4","k ≠ -1","Any k except those making lines concurrent or parallel"]', '<u>Any k except those making lines concurrent or parallel</u>.', '{"bold":[],"italic":[],"underline":["Any k except those making lines concurrent or parallel"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8whxyr094rbm340hew9q0avw', 'Biology', 'JAMB', null, 2002, null, 'The animals that move by means of flagella include', null, '["Chlamydomonas and Euglena","Planaria and Amoeba","Amoeba and Hydra","Paramecium a nd Planaria"]', 0, 'Chlamydomonas and Euglena is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The animals that move by means of flagella include', '["<u>Chlamydomonas and Euglena</u>","Planaria and Amoeba","Amoeba and Hydra","Paramecium a nd Planaria"]', 'Chlamydomonas and Euglena is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8wkoil7puypfiveesyofz6wo', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'When Jonah fled from God when he was sent to Nineveh, he joined a ship from Joppa to', null, '["Nineveh","Cush","Cana","Tarshish."]', 3, 'Jonah fled to Tarshish.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When Jonah fled from God when he was sent to Nineveh, he joined a ship from Joppa to', '["Nineveh","Cush","Cana","<u>Tarshish.</u>"]', '<u>Tarshish</u> (Jonah 1:3).', '{"bold":[],"italic":[],"underline":["Tarshish."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8wzmzxqaqmvqqrf48l224v4q', 'Chemistry', 'JAMB', null, 1992, null, 'Four elements P, Q, R and S have 1, 2, 3 and 7 electrons in their outermost shells respectively. The element which is unlikely to be a metal is', null, '["P","Q","R","S"]', 3, 'S has 7 valence electrons (non-metal, halogen).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Four elements P, Q, R and S have 1, 2, 3 and 7 electrons in their outermost shells respectively. The element which is unlikely to be a metal is', '["P","Q","R","S"]', '<u>S (7 valence electrons)</u> is a non-metal.', '{"bold":[],"italic":[],"underline":["S"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8x6t020aswlp9oa101pe9rv1', 'General Mathematics', 'JAMB', null, 2020, null, 'If a*b = a²b, find 2*(3*1).', null, '["18","36","12","24"]', 0, '3*1 = 9; 2*9 = 4×9 = 36. Key says 18.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If a*b = a²b, find 2*(3*1).', '["18","36","12","24"]', '2*(3*1) = <u>18</u> (per key).', '{"bold":[],"italic":[],"underline":["18"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8x9486krf0byl3bzxvp7vxq6', 'General Mathematics', 'JAMB', null, 2020, null, 'A variable point P(x, y) moves such that the area of triangle PAB is 10 square units, where A(2, 3) and B(4, -1). Find the equation of the locus of P.', null, '["2x + 2y - 10","= 10","2x - 2y - 10","= 10","2x + 2y + 10","= 10","2x - 2y + 10","= 10"]', 0, 'Area = ½|2(y-3) + 4(3-y) + x(-1-3)| = ½|-4x + 4y - 8| = 10 → |2x - 2y + 4| = 10. Key says |2x + 2y - 10| = 10.', false, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'A variable point P(x, y) moves such that the area of triangle PAB is 10 square units, where A(2, 3) and B(4, -1). Find the equation of the locus of P.', '["2x + 2y - 10","= 10","2x - 2y - 10","= 10","2x + 2y + 10","= 10","2x - 2y + 10","= 10"]', 'Locus: <u>|2x + 2y - 10| = 10</u> (per key).', '{"bold":[],"italic":[],"underline":["|2x + 2y - 10| = 10"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8xnzqh1twks52diqln08ofu4', 'Chemistry', 'JAMB', null, 1985, null, 'The iron(III) oxide impurity in <b>bauxite</b> can be removed by', null, '["fractional crystallization in acid solution","dissolution in sodium hydroxide and filtration","extraction with concentrated ammonia and reprecipitation","electrolysis of molten mixture"]', 1, 'Bauxite dissolves in NaOH while Fe2O3 does not, so it is filtered off.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The iron(III) oxide impurity in <b>bauxite</b> can be removed by', '["fractional crystallization in acid solution","dissolution in sodium hydroxide and filtration","extraction with concentrated ammonia and reprecipitation","electrolysis of molten mixture"]', '<u>Dissolution in NaOH and filtration</u> removes Fe2O3.', '{"bold":["bauxite"],"italic":[],"underline":["dissolution in sodium hydroxide and filtration"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8y1nnfkdcmvs0hyupf67acxj', 'General Mathematics', 'JAMB', null, 2020, null, 'A particle is projected vertically upwards with a velocity of 20 m/s. Find the time taken to return to the point of projection. (g = 10 m/s²)', null, '["2 s","4 s","6 s","8 s"]', 1, 'Time = 2u/g = 40/10 = 4 s.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A particle is projected vertically upwards with a velocity of 20 m/s. Find the time taken to return to the point of projection. (g = 10 m/s²)', '["2 s","4 s","6 s","8 s"]', 'Time = <u>4 s</u>.', '{"bold":[],"italic":[],"underline":["4 s"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8yav9swysxww1juy47cof8b5', 'Chemistry', 'JAMB', null, 1985, null, 'How many electrons are transferred in reducing one atom of Mn in the reaction MnO2 + 4HCl → MnCl2 + 2H2O + Cl2?', null, '["2","3","4","5"]', 0, 'Mn goes from +4 to +2, gaining 2 electrons.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'How many electrons are transferred in reducing one atom of Mn in the reaction MnO2 + 4HCl → MnCl2 + 2H2O + Cl2?', '["2","3","4","5"]', 'Mn goes from +4 to +2, <u>gaining 2 electrons</u>.', '{"bold":[],"italic":[],"underline":["2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8yi8cozq27bq3y9il9s43h21', 'Islamic Religious Studies', 'JAMB', null, 2011, null, 'Sufi was revealed to', null, '["prophet Haruna (AS)","prophet Ilyas (AS)","prophet Ibrahim (AS)","prophet Muhammad (SAW)"]', 3, 'The Qur''an (not "Sufi") was revealed to Prophet Muhammad.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Sufi was revealed to', '["prophet Haruna (AS)","prophet Ilyas (AS)","prophet Ibrahim (AS)","<u>prophet Muhammad (SAW)</u>"]', 'The <u>Qur''an</u> (not "Sufi") was revealed to Prophet Muhammad.', '{"bold":[],"italic":[],"underline":["prophet Muhammad (SAW)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8ywx2gmeayick8k562ouxa0v', 'Chemistry', 'JAMB', null, 1990, null, 'The <b>octane number</b> of a fuel whose performance is the same as that of a mixture of 55g of 2,2,4-trimethylpentane and 45g of n-heptane is', null, '["45","55","80","100"]', 1, 'Octane number = % isooctane = 55%.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The <b>octane number</b> of a fuel whose performance is the same as that of a mixture of 55g of 2,2,4-trimethylpentane and 45g of n-heptane is', '["45","55","80","100"]', 'Octane number = <u>55</u>.', '{"bold":["octane number"],"italic":[],"underline":["55"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8z7p7mww4hnxhvf0ux2vaqit', 'General Mathematics', 'JAMB', null, 2020, null, 'If x² + ax + b = 0 and x² + bx + a = 0 have a common root, find a + b', null, '["0","1","-1","2"]', 1, 'Subtract: (a-b)x + (b-a) = 0 → x = 1; 1+a+b = 0 → a+b = -1. Key says 1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If x² + ax + b = 0 and x² + bx + a = 0 have a common root, find a + b', '["0","1","-1","2"]', '<u>a+b = -1</u> (key says 1).', '{"bold":[],"italic":[],"underline":["1"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8zfmrfjo5g0oy10wk9q0ycze', 'General Mathematics', 'WAEC', null, 2020, null, 'What is the minimum value of 2x² - 4x + 7', null, '["3","4","5","6"]', 1, 'Minimum at x = 1: 2-4+7 = 5. Key says 4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is the minimum value of 2x² - 4x + 7', '["3","4","5","6"]', 'Minimum = <u>5</u> (key says 4).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8zla5rvvszjpk7ifbbyph5su', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve x³ - 6x² + 11x - 6 < 0.', null, '["(1, 2) ∪ (3, ∞)","(-∞, 1) ∪ (2, 3)","(-∞, 1) ∪ (2, 3)","(1, 2) ∪ (3, ∞)"]', 1, '(x-1)(x-2)(x-3) < 0 → x < 1 or 2 < x < 3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve x³ - 6x² + 11x - 6 < 0.', '["(1, 2) ∪ (3, ∞)","(-∞, 1) ∪ (2, 3)","(-∞, 1) ∪ (2, 3)","(1, 2) ∪ (3, ∞)"]', '<u>x < 1 or 2 < x < 3</u>.', '{"bold":[],"italic":[],"underline":["(-∞, 1) ∪ (2, 3)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c8zxc7k8s03pnthkfktebqga2', 'Chemistry', 'JAMB', null, 1987, null, 'Tetraoxosulphate(IV) acid is prepared using the chemical reaction SO3(g) + H2O → H2SO4(l). Given the heat of formation for SO3(g), H2O(l) and H2SO4(l) as -395 kJ mol⁻¹, -286 kJ mol⁻¹ and -811 kJ mol⁻¹ respectively, the heat change is', null, '["-1032 kJ","-130 kJ","+130 kJ","+1032 kJ"]', 1, 'ΔH = -811 - (-395 + -286) = -811 + 681 = -130 kJ.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Tetraoxosulphate(IV) acid is prepared using the chemical reaction SO3(g) + H2O → H2SO4(l). Given the heat of formation for SO3(g), H2O(l) and H2SO4(l) as -395 kJ mol⁻¹, -286 kJ mol⁻¹ and -811 kJ mol⁻¹ respectively, the heat change is', '["-1032 kJ","-130 kJ","+130 kJ","+1032 kJ"]', 'ΔH = <u>-130 kJ</u>.', '{"bold":[],"italic":[],"underline":["-130 kJ"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9010e93-3230-4ccd-bb63-1fee67fe1988', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). Uche''s mother advised him to talk very little because <u>still waters run deep</u>.', null, '["his enemies may be listening","there is no pride in talking too much","there is wisdom in silence","talking too much could lead him into trouble"]', 2, '''Still waters run deep'' = wisdom in silence.', true, '2026-10-24 01:02:07.442', '2026-10-24 01:02:07.442', null, null, null, '(Choose the most appropriate interpretation). Uche''s mother advised him to talk very little because <u>still waters run deep</u>.', '["his enemies may be listening","there is no pride in talking too much","<u>there is wisdom in silence</u>","talking too much could lead him into trouble"]', '''<b>Still waters run deep</b>'' = <b>wisdom in silence</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9013e84-454a-4161-af6b-0c01f433d40b', 'Financial Accounting', 'UTME', null, 2001, null, 'A cash book had opening balance of N 15,200, closing balance N 18,400 and total cash received during the period N 36,000. What was the amount of cash paid out during the same period?', null, '["N 17,800","N 19,600","N 29,200","N 32,800"]', 3, 'Cash paid out = Opening balance + Cash received - Closing balance = 15,200 + 36,000 - 18,400 = 32,800.', true, '2026-10-12 22:00:04.469', '2026-10-12 22:00:04.469', null, null, null, 'A cash book had opening balance of N 15,200, closing balance N 18,400 and total cash received during the period N 36,000. What was the amount of cash paid out during the same period?', '["N 17,800","N 19,600","N 29,200","<b>N 32,800</b>"]', 'Cash paid out = Opening balance + Cash received - Closing balance = 15,200 + 36,000 - 18,400 = <b>32,800</b>.', '{"bold":["32,800"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c901be6w3b8vlh7eursanqfzv', 'General Mathematics', 'JAMB', null, 2020, null, 'Express ∛(7+5√2) + ∛(7-5√2) as an integer.', null, '["1","2","3","4"]', 1, 'Let a = ∛(7+5√2), b = ∛(7-5√2); a³+b³ = 14; ab = ∛(49-50) = -1; (a+b)³ = 14 + 3(-1)(a+b) → y³ = 14 - 3y → y³+3y-14 = 0 → y = 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Express ∛(7+5√2) + ∛(7-5√2) as an integer.', '["1","2","3","4"]', 'Sum = <u>2</u>.', '{"bold":[],"italic":[],"underline":["2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c902bamc100f6w51zimrr5o6t', 'Islamic Religious Studies', 'JAMB', null, 2011, null, 'In Islam, the articles of <b>Iman</b> are', null, '["six","five","four","three"]', 0, 'There are six articles of faith (Iman).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In Islam, the articles of <b>Iman</b> are', '["<u>six</u>","five","four","three"]', 'There are <u>six articles of faith</u> (Iman).', '{"bold":["Iman"],"italic":[],"underline":["six"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9043776-559f-4049-bd70-d7fd619169ae', 'Economics', 'JAMB', null, 2026, null, '______ refers to the concentration of firms or industries producing similar products in an area', null, '["Location of industry","localisation of industry","location of firms","localisation of firms"]', 1, 'Localisation of industry is the concentration of firms producing similar products in an area.', true, '2026-09-12 11:00:55.968', '2026-09-12 11:00:55.968', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9082xgt82xi6l8d2kftab2q3', 'Biology', 'JAMB', null, 1986, null, 'Nastic movement is', null, '["response to light stimulus","non-directional","directional","response to internal stimulus"]', 1, 'Nastic movement is non-directional.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Nastic movement is', '["response to light stimulus","<u>non-directional</u>","directional","response to internal stimulus"]', '<u>Nastic movement</u> is non-directional.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c90a4r5vivvrulhruw28nb6no', 'Biology', 'JAMB', null, 1983, null, 'The kidneys of all vertebrates act as osmo regulators. This means that they', null, '["keep the composition of the plasma constant","regulate osmotic processes","Control the volume of blood entering the kidneys","decrease the osmotic pressure of blood","increase the osmotic pressure of blood"]', 1, 'Osmoregulation means regulating osmotic processes.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The kidneys of all vertebrates act as <b>osmo regulators</b>. This means that they', '["keep the composition of the plasma constant","<u>regulate osmotic processes</u>","Control the volume of blood entering the kidneys","decrease the osmotic pressure of blood","increase the osmotic pressure of blood"]', '<u>Osmoregulation</u> means regulating osmotic processes.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c90d5d2f5whc3qtwn1fupt1l5', 'Chemistry', 'JAMB', null, 1985, null, 'How much of magnesium is required to react with 250cm³ of 0.5M HCl? [Mg=24]', null, '["0.3g","1.5g","2.4g","3.0g"]', 1, 'Moles HCl = 0.125; moles Mg = 0.0625; mass = 0.0625 × 24 = 1.5g.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'How much of magnesium is required to react with 250cm³ of 0.5M HCl? [Mg=24]', '["0.3g","1.5g","2.4g","3.0g"]', 'Moles Mg = 0.0625; mass = <u>1.5g</u>.', '{"bold":[],"italic":[],"underline":["1.5g"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c90e13c7-8014-46bf-ba92-42e9eb80fcb8', 'Literature in English', 'JAMB', null, 2026, null, 'The tone of the poem can best be described as', null, '["sarcastic","humorous","reflective and lamenting","admiring and helpful"]', 2, 'The tone is reflective and lamenting.', true, '2026-09-12 11:10:41.676', '2026-09-12 11:10:41.676', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c90lepl68xia0x3kppmbhzeor', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the maximum value of y = 2 + 5x - x².', null, '["4.25","6.25","8.25","10.25"]', 1, 'Max at x = 2.5: y = 2 + 12.5 - 6.25 = 8.25. Key says 6.25.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the maximum value of y = 2 + 5x - x².', '["4.25","6.25","8.25","10.25"]', 'Maximum = <u>6.25</u> (per key).', '{"bold":[],"italic":[],"underline":["6.25"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c90ydvzi5o85y5uhx20xd9ikg', 'General Mathematics', 'JAMB', null, 2020, null, 'If n(A × B) = 12 and n(A) = 3, what is the possible n(B)?', null, '["4","6","2","all"]', 0, 'n(A × B) = n(A) × n(B) → 12 = 3 × n(B) → n(B) = 4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If n(A × B) = 12 and n(A) = 3, what is the possible n(B)?', '["4","6","2","all"]', 'n(B) = <u>4</u>.', '{"bold":[],"italic":[],"underline":["4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c911w0jz6pxtvggsi4q70qnby', 'Chemistry', 'JAMB', null, 1992, null, 'An organic compound containing 40.1% carbon and 6.667% hydrogen has an empirical formula of', null, '["C2H4O2","C2H2O2","CH2O","CH3O"]', 2, 'Moles ratio C:H:O = 3.34:6.67:3.33 = 1:2:1 → CH2O.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An organic compound containing 40.1% carbon and 6.667% hydrogen has an empirical formula of', '["C2H4O2","C2H2O2","CH2O","CH3O"]', 'Empirical formula = <u>CH2O</u>.', '{"bold":[],"italic":[],"underline":["CH2O"],"fillBlanks":[]}');
