insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c91f4ke497jpvx96zpl9nbvsc', 'Chemistry', 'JAMB', null, 1988, null, 'Aluminium is extracted commercially from its ore by', null, '["heating aluminium oxide with coke in a furnace","the electrolysis of fused aluminium oxide in cryolite","treating cryolite with sodium hydroxide solution under pressure","heating sodium aluminium silicate to a high temperature"]', 1, 'Al is extracted by electrolysis of fused Al2O3 in cryolite.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Aluminium is extracted commercially from its ore by', '["heating aluminium oxide with coke in a furnace","the electrolysis of fused aluminium oxide in cryolite","treating cryolite with sodium hydroxide solution under pressure","heating sodium aluminium silicate to a high temperature"]', '<u>Electrolysis of fused Al2O3 in cryolite</u>.', '{"bold":[],"italic":[],"underline":["the electrolysis of fused aluminium oxide in cryolite"],"fillBlanks":[]}');
