insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c91v4x52oss2h9j8z2aflzebr', 'General Mathematics', 'JAMB', null, 2020, null, 'Multiply 23₄ × 12₄ in base four.', null, '["1022₄","1002₄","1032₄","1122₄"]', 1, '23₄ = 11 and 12₄ = 6; product = 66 = 1×64 + 0×16 + 0×4 + 2 = 1002₄.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Multiply 23₄ × 12₄ in base four.', '["1022₄","1002₄","1032₄","1122₄"]', '23₄ = 11 and 12₄ = 6; product = 66 = 1×64 + 0×16 + 0×4 + 2 = 1002₄.', '{"bold":[],"italic":[],"underline":["1012₄"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c91zq5g65dtnji5ypam9k6m52', 'Chemistry', 'JAMB', null, 1988, null, 'Given the reactions:<br>(i) Fe(s) + X(NO3)2(aq) → Fe(NO3)2(aq) + X(s)<br>(ii) H2(g) + XO(s) → X(s) + H2O(g)<br>X is likely to be', null, '["copper","zinc","calcium","lead"]', 1, 'Zn is below Fe in reactivity but above H in the series.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Given the reactions:<br>(i) Fe(s) + X(NO3)2(aq) → Fe(NO3)2(aq) + X(s)<br>(ii) H2(g) + XO(s) → X(s) + H2O(g)<br>X is likely to be', '["copper","zinc","calcium","lead"]', '<u>Zinc</u> fits both reactions.', '{"bold":[],"italic":[],"underline":["zinc"],"fillBlanks":[]}');
