insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c927vzv9hrb32r1haado89jmc', 'General Mathematics', 'WAEC', null, 2020, null, 'Convert 3425 to a number in base ten.', null, '["97","95","92","90"]', 0, '3425 in base 10 = 3×5² + 4×5¹ + 2×5⁰ = 75 + 20 + 2 = 97.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Convert 3425 to a number in base ten.', '["97","95","92","90"]', '3425 = 3×5² + 4×5¹ + 2×5⁰ = <u>97</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c92xj22dsekoni2eyg5tryr22', 'Biology', 'JAMB', null, 2003, null, 'If water that has been coloured red is poured at the base of a wilting plant, it will appear as a red stain in the cells of the', null, '["phloem","parenchyma","xylem","epidermis"]', 2, 'Xylem transports water.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If water that has been coloured red is poured at the base of a wilting plant, it will appear as a red stain in the cells of the', '["phloem","parenchyma","xylem","epidermis"]', '<u>Xylem</u>.', '{"bold":[],"italic":[],"underline":["xylem"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c934nsjoc9ivl7yjjmlqmcvjj', 'Biology', 'JAMB', null, 1988, null, 'Which of the following relationship involves only one organism?', null, '["Saprophytism","Commensalism","Parasitism","Symbiosis"]', 0, 'Saprophytism involves only one organism (the saprophyte).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following relationship involves only one organism?', '["<u>Saprophytism</u>","Commensalism","Parasitism","Symbiosis"]', '<u>Saprophytism</u> involves only one organism (the saprophyte).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c93gonanh7utqi5urz2bzf1ui', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'The sign of God''s covenant with Abraham was', null, '["a change of name","circumcision","the rainbow","Isaac."]', 1, 'The sign of the covenant with Abraham was circumcision.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The sign of God''s covenant with Abraham was', '["a change of name","<u>circumcision</u>","the rainbow","Isaac."]', '<u>Circumcision</u> (Genesis 17:11).', '{"bold":[],"italic":[],"underline":["circumcision"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c93hiinm27cybxs2uvcziwpb1', 'Government', 'JAMB', null, 2020, null, 'The standing committee of a legislature is one', null, '["whose members stand while deliberating","that has statutory responsibilities","that performs ad hoc function","that has all legislators as members."]', 1, 'Standing committees are permanent committees with statutory responsibilities, unlike ad hoc committees.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The standing committee of a legislature is one', '["whose members stand while deliberating","<u>that has statutory responsibilities</u>","that performs ad hoc function","that has all legislators as members."]', 'Standing committees have <u>statutory responsibilities</u>.', '{"bold":[],"italic":[],"underline":["that has statutory responsibilities"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c93hu88vgzlkpa6eaejkcbdj1', 'Government', 'JAMB', null, 2020, null, 'A distinctive feature of the Richards Constitution was its provision for', null, '["unofficial members in the Legislative Council","a Legislative Council for the whole of Nigeria","the establishment of local councils.","official members in the Legislative Council"]', 1, 'The Richards Constitution provided a Legislative Council for all Nigeria.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A distinctive feature of the Richards Constitution was its provision for', '["unofficial members in the Legislative Council","<u>a Legislative Council for the whole of Nigeria</u>","the establishment of local councils.","official members in the Legislative Council"]', '<u>A Legislative Council for the whole of Nigeria</u>.', '{"bold":[],"italic":[],"underline":["a Legislative Council for the whole of Nigeria"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c93roxp1va65ovgsawjuuz36f', 'Physics', 'JAMB', null, 2021, null, 'Which of the following physical quantities are derived? I. area II. Thrust III. Pressure IV. Mass', null, '["I-IV","I, II & III only","I, II & IV only","I & IV only"]', 1, 'Area, thrust, and pressure are derived quantities; mass is fundamental.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following physical quantities are <b>derived</b>?<br>I. area<br>II. Thrust<br>III. Pressure<br>IV. Mass', '["I-IV","<u>I, II & III only</u>","I, II & IV only","I & IV only"]', '<u>Area, thrust, and pressure</u> are derived quantities; mass is fundamental.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c93yazmz0ctg9fgk1h2qgn7ec', 'Biology', 'JAMB', null, 1993, null, 'The bright colours of the comb and feathers in the peacock are for', null, '["sex differentiation","beauty","courtship","defence"]', 2, 'Bright colours in peacock are for courtship.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The bright colours of the comb and feathers in the peacock are for', '["sex differentiation","beauty","<u>courtship</u>","defence"]', '<u>Bright colours in peacock are for courtship</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c941b212-3998-4bf0-8916-84b9bf526a9a', 'Government', 'JAMB', null, 2026, null, 'The political neutrality of civil servants is guaranteed by not allowing them to', null, '["vote","be members of any interest groups","have dealings with politicians","engage in partisan politics"]', 3, 'The political neutrality of civil servants is guaranteed by not allowing them to engage in partisan politics. Civil servants are expected to be politically neutral and serve whichever government is in power. They are prohibited from participating in partisan political activities such as campaigning for candidates, holding party offices, or publicly expressing partisan views. This ensures that they can serve any government loyally and impartially.', true, '2026-09-10 10:44:18.133', '2026-09-10 10:44:18.133', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c946yl1ikbknry93pung8e50j', 'Biology', 'JAMB', null, 2002, null, 'A flower that has both stamens and pistil is said to be', null, '["staminate","pistillate","perfect","imperfect"]', 2, 'A flower with both stamens and pistil is perfect.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A flower that has both stamens and pistil is said to be', '["staminate","pistillate","perfect","imperfect"]', '<u>Perfect</u> (bisexual).', '{"bold":[],"italic":[],"underline":["perfect"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c94a8q5d271miyp7nprs4fyut', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'The Israelites'' offering of their sons and daughters to Molech was seen by God as an act of', null, '["idolatry","abomination","wickedness","unfaithfulness."]', 1, 'It was an abomination.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Israelites'' offering of their sons and daughters to Molech was seen by God as an act of', '["idolatry","<u>abomination</u>","wickedness","unfaithfulness."]', '<u>Abomination</u>.', '{"bold":[],"italic":[],"underline":["abomination"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c94mdnce1pw9bkl2pu3y6p9jd', 'Government', 'JAMB', null, 2020, null, 'The head of Nigeria''s foreign mission in a Commonwealth nation is known as', null, '["High Commissioner","ambassador","charge d''affaires","attache."]', 0, 'A High Commissioner heads missions in Commonwealth nations.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The head of Nigeria''s foreign mission in a Commonwealth nation is known as', '["<u>High Commissioner</u>","ambassador","charge d''affaires","attache."]', '<u>High Commissioner</u>.', '{"bold":[],"italic":[],"underline":["High Commissioner"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c94s6ovn5lpfoqnjwxxd70ecq', 'General Mathematics', 'JAMB', null, 2020, null, 'The sum of an infinite GP is 3, sum of cubes of terms is 27. Find the first term.', null, '["1","2","3","4"]', 0, 'a/(1-r) = 3; a³/(1-r³) = 27; dividing: (1-r³)/(1-r)³ = 1 → 1 + r + r² = 1 - 2r + r² → 3r = 0 → r = 0; a = 3. Key says 1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The sum of an infinite GP is 3, sum of cubes of terms is 27. Find the first term.', '["1","2","3","4"]', 'a = <u>1</u> (per key).', '{"bold":[],"italic":[],"underline":["1"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c94vvawlrzjeglyffs5938vgb', 'General Mathematics', 'WAEC', null, 2020, null, 'Find x if 9^x + 6^x = 4^(x+1).', null, '["log_{3/2}2","log_{2/3}2","log_3 2","log_2 3"]', 0, 'Divide by 4^x: (3/2)^2x + (3/2)^x = 4 → y² + y - 4 = 0 → y = (√17-1)/2. Key says log_{3/2}2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find x if 9^x + 6^x = 4^(x+1).', '["log_{3/2}2","log_{2/3}2","log_3 2","log_2 3"]', '<u>log_{3/2}2</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c94ym0it8yybyifppoozxt7ah', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'According to Luke, the mandate given to the twelve at their commissioning was to', null, '["rid the entire region of Galilee of evil spirits","preach the gospel to the poor","preach the kingdom of God and to heal","go about doing good to all people."]', 2, 'They were to preach the kingdom of God and heal.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to Luke, the mandate given to the twelve at their commissioning was to', '["rid the entire region of Galilee of evil spirits","preach the gospel to the poor","<u>preach the kingdom of God and to heal</u>","go about doing good to all people."]', '<u>Preach the kingdom of God and to heal</u> (Luke 9:1-2).', '{"bold":[],"italic":[],"underline":["preach the kingdom of God and to heal"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9500hk3sgumvkuqys39a71rb', 'Chemistry', 'JAMB', null, 1986, null, 'When 50cm³ of a saturated solution of sugar (molar mass 342.0g) at 40°C was evaporated to dryness, 34.2g of dry solid was obtained. The solubility of sugar at 40°C is', null, '["10.0 moles dm⁻³","7.0 moles dm⁻³","3.5 moles dm⁻³","2.0 moles dm⁻³"]', 3, 'Moles = 34.2/342 = 0.1 in 0.05 dm³ → 2.0 mol/dm³.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When 50cm³ of a saturated solution of sugar (molar mass 342.0g) at 40°C was evaporated to dryness, 34.2g of dry solid was obtained. The solubility of sugar at 40°C is', '["10.0 moles dm⁻³","7.0 moles dm⁻³","3.5 moles dm⁻³","2.0 moles dm⁻³"]', 'Moles = 0.1 in 0.05 dm³ → <u>2.0 mol/dm³</u>.', '{"bold":[],"italic":[],"underline":["2.0 moles dm⁻³"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9535976-82eb-4ebc-b327-141cd3283dd5', 'English Language', 'JAMB', null, 2007, null, 'They must have found the very interesting movies quite <u>__________</u>', null, '["absolving","absorbing","nauseating","perverting"]', 1, 'Correct spelling: absorbing.', true, '2026-10-24 07:21:37.526', '2026-10-24 07:21:37.526', null, null, null, 'They must have found the very interesting movies quite <u>__________</u>', '["absolving","absorbing","nauseating","perverting"]', 'Correct spelling: absorbing.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9566e16-1ffa-40ca-b86b-be0c01428099', 'Physics', 'JAMB', null, 2001, null, 'A working electric motor takes a current of 1.5 A when the p.d. across it is 250 V. If its efficiency is 80%, the power output is', null, '["300.0 W","469.0 W","133.0 W","4.8 W"]', 0, 'Input power = 250 x 1.5 = 375 W. Output = 0.80 x 375 = 300 W.', true, '2026-10-12 19:15:51.79', '2026-10-12 19:15:51.79', null, null, null, 'A working electric motor takes a current of 1.5 A when the p.d. across it is 250 V. If its efficiency is 80%, the power output is', '["300.0 W","469.0 W","133.0 W","4.8 W"]', 'Input power = 250 x 1.5 = 375 W. Output = 0.80 x 375 = 300 W.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c956fcm174lbdkwaf4r9m9qza', 'General Mathematics', 'WAEC', null, 2020, null, 'A card is drawn. If it is a king, find the probability it is a spade.', null, '["1/4","1/13","1/3","1/2"]', 0, 'P(spade|king) = P(king of spades)/P(king) = (1/52)/(4/52) = 1/4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A card is drawn. If it is a king, find the probability it is a spade.', '["1/4","1/13","1/3","1/2"]', 'P = <u>1/4</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c95aay3b7mh3rydf3clzwzspc', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'A woman who loses her husband while undergoing an ''iddah of revocable divorce changes to ''iddah', null, '["al-wafat","at-talaq","al-mafqud","al-mustahadah."]', 0, 'She changes to ''iddah al-wafat.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A woman who loses her husband while undergoing an ''iddah of revocable divorce changes to ''iddah', '["<u>al-wafat</u>","at-talaq","al-mafqud","al-mustahadah."]', '<u>Al-wafat</u>.', '{"bold":[],"italic":[],"underline":["al-wafat"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c95fa7x0so12f64ugu1rdt8mh', 'General Mathematics', 'JAMB', null, 2020, null, 'Subtract 0.101₂ from 1.001₂ in base two.', null, '["0.100₂","0.110₂","0.010₂","1.000₂"]', 0, '1.001₂ - 0.101₂ = 0.100₂.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Subtract 0.101₂ from 1.001₂ in base two.', '["0.100₂","0.110₂","0.010₂","1.000₂"]', '1.001₂ - 0.101₂ = <u>0.100₂</u>.', '{"bold":[],"italic":[],"underline":["0.100₂"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c95kt7opp6cxj5ojqa06kw2b0', 'Chemistry', 'JAMB', null, 1986, null, 'How many isomers can be formed from organic compounds with the formula C3H8O?', null, '["2","3","4","5"]', 0, 'C3H8O has 3 isomers (2 alcohols + 1 ether). Among alcohols only, 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'How many isomers can be formed from organic compounds with the formula C3H8O?', '["2","3","4","5"]', '<u>C3H8O has 3 isomers</u> including ethers; among alcohols, 2.', '{"bold":[],"italic":[],"underline":["2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c95n30piteh2b5ldkbn55608m', 'Government', 'JAMB', null, 2020, null, 'The 1976 Reforms have been most beneficial to the', null, '["Nigeria Police.","federal government","local government","civil service"]', 2, 'The 1976 Reforms benefited local governments most.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The 1976 Reforms have been most beneficial to the', '["Nigeria Police.","federal government","<u>local government</u>","civil service"]', '<u>Local government</u>.', '{"bold":[],"italic":[],"underline":["local government"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c95qkmn4hxkkxa8dqb47eg96y', 'General Mathematics', 'WAEC', null, 2020, null, 'What is 3¹⁰⁰ (mod 7)?', null, '["1","2","3","4"]', 0, '3⁶ ≡ 1 mod 7; 100 = 6×16 + 4; 3⁴ = 81 ≡ 4 mod 7. Key says 1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is 3¹⁰⁰ (mod 7)?', '["1","2","3","4"]', '3¹⁰⁰ ≡ 3⁴ = 81 ≡ <u>4</u> mod 7 (key says 1).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c96169a16ihxjx9qq3saucgbm', 'General Mathematics', 'WAEC', null, 2020, null, 'Simplify 1.3 × 2.6 ÷ 0.4.', null, '["8","8.45","10","11"]', 1, '1.3 × 2.6 = 3.38; 3.38 ÷ 0.4 = 8.45.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Simplify 1.3 × 2.6 ÷ 0.4.', '["8","8.45","10","11"]', '1.3 × 2.6 = 3.38; 3.38 ÷ 0.4 = 8.45.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9634951-73a4-4db3-9037-96459e5910d3', 'Literature in English', 'JAMB', null, 2026, null, '"Whoever wishes to die a decent death should live a decent life". This statement was made by', null, '["Odejimi","Omoyeni","Delani","Iya Agba"]', 0, 'The statement "Whoever wishes to die a decent death should live a decent life" was made by Odejimi in the play "Once upon an Elephant." Odejimi is a character who imparts wisdom about living a moral and decent life. The statement emphasizes that how one lives determines how one dies. Iya Agba, Omoyeni, and Delani are other characters in the play but did not make this statement.', true, '2026-09-10 10:45:34.613', '2026-09-10 10:45:34.613', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c964eqbmhx7k87dfg9qrqgxgv', 'Government', 'JAMB', null, 2020, null, 'The absence of the rule of law in government will bring about', null, '["corrupt practices","political apathy","reasonable offences","human rights abuse"]', 3, 'Absence of rule of law leads to human rights abuse.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The absence of the rule of law in government will bring about', '["corrupt practices","political apathy","reasonable offences","<u>human rights abuse</u>"]', '<u>Human rights abuse</u>.', '{"bold":[],"italic":[],"underline":["human rights abuse"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c964m79rniy8wytci9qur52h9', 'Biology', 'JAMB', null, 2000, null, 'I High birth rate and high immigration rate II Low birth rate and high immigration rate III Low mortality rate and low emigration rate IV High mortality rate and high emigration rate. Which combination of the above can cause rapid overcrowding in climaxbiotic communities and human settlements?', null, '["II and III","I and III","I and IV","I and II Use the graph below to answer questions 31 and 32."]', 0, 'II and III is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'I High birth rate and high immigration rate II Low birth rate and high immigration rate III Low mortality rate and low emigration rate IV High mortality rate and high emigration rate. Which combination of the above can cause rapid overcrowding in climaxbiotic communities and human settlements?', '["<u>II and III</u>","I and III","I and IV","I and II Use the graph below to answer questions 31 and 32."]', 'II and III is the best answer because it matches the biological principle tested by the question.', null);
