insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c96job4az3di9pdxjp908ueyo', 'Biology', 'JAMB', null, 1985, null, 'Which of the following is seed bearing?', null, '["Mosses","Whistling pine","Algal filaments","Livewort","Fern fronds"]', 1, 'Whistling pine is a gymnosperm and bears seeds.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is <b>seed bearing</b>?', '["Mosses","<u>Whistling pine</u>","Algal filaments","Livewort","Fern fronds"]', '<u>Whistling pine</u> is a gymnosperm and bears seeds.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c96k3aa61w4ogwhrwpnejunl2', 'Biology', 'JAMB', null, 1983, null, 'Which of the following structures is NOT found in the female agama lizard?', null, '["Pre-anal pads","Eardrum","Gular fold","Nasal scale","Nuchal crest"]', 0, 'Pre-anal pads are found only in male lizards for mating purposes.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following structures is <b>NOT</b> found in the female agama lizard?', '["<u>Pre-anal pads</u>","Eardrum","Gular fold","Nasal scale","Nuchal crest"]', '<u>Pre-anal pads</u> are found only in male lizards for mating purposes.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c97jt6vv4llqgucjziyasyu58', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'In the story of the transfiguration of Jesus, Moses and Elijah represented the', null, '["glory of God","Old Testament saints","law and the prophets","end of the age."]', 2, 'Moses and Elijah represented the law and the prophets.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the story of the transfiguration of Jesus, Moses and Elijah represented the', '["glory of God","Old Testament saints","<u>law and the prophets</u>","end of the age."]', '<u>Law and the prophets</u>.', '{"bold":[],"italic":[],"underline":["law and the prophets"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c97qw0shh70n7ba3vcmty7fmz', 'Islamic Religious Studies', 'JAMB', null, 2003, null, 'Suratul-Fatihah is also referred to as', null, '["Suratul-Hidayah","Kitabul-mathani","Ummul-kitab","Suratud-du''a"]', 2, 'Al-Fatihah is called Ummul-Kitab (Mother of the Book).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Suratul-Fatihah is also referred to as', '["Suratul-Hidayah","Kitabul-mathani","<u>Ummul-kitab</u>","Suratud-du''a"]', 'Al-Fatihah is called <u>Ummul-Kitab</u> (Mother of the Book).', '{"bold":[],"italic":[],"underline":["Ummul-kitab"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c97rx75cjsy9ju4tlxyzrwbd5', 'Chemistry', 'JAMB', null, 1994, null, 'At the same temperature and pressure, 50cm³ of nitrogen gas contains the same number of molecules as', null, '["25cm³ of methane","40cm³ of hydrogen","50cm³ of ammonia","100cm³ of chlorine"]', 2, 'Equal volumes of gases at same T and P contain equal molecules (Avogadro).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'At the same temperature and pressure, 50cm³ of nitrogen gas contains the same number of molecules as', '["25cm³ of methane","40cm³ of hydrogen","50cm³ of ammonia","100cm³ of chlorine"]', '<u>50cm³ of ammonia</u> (equal volume).', '{"bold":[],"italic":[],"underline":["50cm³ of ammonia"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c981k07t1yhfalamdd7gwhn8y', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Joseph''s brothers decided not to kill him because he', null, '["pleaded with them","was their brother and their flesh","was loved by their father","was the first son of his mother."]', 1, 'He was their brother and their flesh.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Joseph''s brothers decided not to kill him because he', '["pleaded with them","<u>was their brother and their flesh</u>","was loved by their father","was the first son of his mother."]', '<u>Was their brother and their flesh</u> (Genesis 37:26-27).', '{"bold":[],"italic":[],"underline":["was their brother and their flesh"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9864kw9hmbneqhsge6yqje39', 'Physics', 'JAMB', null, 1983, null, 'The total length of a spring when a mass of 200 g is hung from its end is 14 cm, while its total length is 16 cm when a mass of 300 g is hung from the same end. Calculate the unstretched length of the spring assuming Hooke''s law is obeyed.', null, '["9.33 cm","10.00 cm","10.66 cm","12.00 cm","15.00 cm"]', 1, 'An extra 100 g stretches the spring by 2 cm, so 200 g stretches it by 4 cm. Unstretched length = 14 − 4 = 10.00 cm.', true, '2026-10-11 21:26:45.728', '2026-10-11 21:26:45.728', null, null, null, 'The total length of a spring when a mass of 200 g is hung from its end is 14 cm, while its total length is 16 cm when a mass of 300 g is hung from the same end. Calculate the unstretched length of the spring assuming Hooke''s law is obeyed.', '["9.33 cm","10.00 cm","10.66 cm","12.00 cm","15.00 cm"]', 'An extra 100 g stretches the spring by 2 cm, so 200 g stretches it by 4 cm. Unstretched length = 14 − 4 = 10.00 cm.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9885j0gqv78ixgqrumf1nyxz', 'Chemistry', 'JAMB', null, 2024, null, 'The mass of an electron is I. Negative II. Less than that of the proton III. Equal to that of the proton IV. Zero at last V. Greater than that of proton', null, '["I&V only","III only","V only","I&II only","II only"]', 3, 'The electron has a negative charge and its mass is less than that of the proton.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The mass of an electron is<br>I. Negative<br>II. Less than that of the proton<br>III. Equal to that of the proton<br>IV. Zero at last<br>V. Greater than that of proton', '["I&V only","III only","V only","<u>I&II only</u>","II only"]', 'The electron has a <u>negative charge and its mass is less than that of the proton</u>.', null);
