insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c992hgwd2iq4qzxvb59u723lo', 'Government', 'JAMB', null, 2020, null, 'In a presidential system of government, the president checks the legislature through', null, '["executive review","executive order","exercise of veto","legislative order."]', 2, 'The president checks the legislature through veto power.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In a presidential system of government, the president checks the legislature through', '["executive review","executive order","<u>exercise of veto</u>","legislative order."]', '<u>Exercise of veto</u>.', '{"bold":[],"italic":[],"underline":["exercise of veto"],"fillBlanks":[]}');
