insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c99a8205-f3c3-41d4-87b5-a49272f3ab35', 'Financial Accounting', 'UTME', null, 2003, null, 'During the year ended 31st December 2001, Nuju Enterprises paid rent as follows Jan. 20 24 000 for a period of 4 months May 16 30 000 for a period of 5 months Oct. 15 36 000 for a period of 6 months. What is the overpaid portion of the rent?', null, '["N36 000","N18 000","N12 000","N6 000"]', 1, 'It is assumed that half of the payments have been utilized by 31st Dec 2001, so the overpayment is N18,000.', true, '2026-10-12 22:00:00.322', '2026-10-12 22:00:00.322', null, null, null, 'During the year ended 31st December 2001, Nuju Enterprises paid rent as follows Jan. 20 24 000 for a period of 4 months May 16 30 000 for a period of 5 months Oct. 15 36 000 for a period of 6 months. What is the overpaid portion of the rent?', '["N36 000","<b>N18 000</b>","N12 000","N6 000"]', 'It is assumed that half of the payments have been utilized by 31st Dec 2001, so the overpayment is <b>N18,000</b>.', '{"bold":["N18,000"],"italic":[],"underline":[],"fillBlanks":[]}');
