insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9a59ghwle1gc2x6xx7jfwg4x', 'Chemistry', 'JAMB', null, 2004, null, 'Which of these reagents can confirm the presence of a <b>triple bond</b>?', null, '["Bromine gas","Bromine water","Acidified KMnO4","Copper(I) chloride"]', 3, 'Terminal alkynes react with Cu2Cl2 to give a precipitate.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of these reagents can confirm the presence of a <b>triple bond</b>?', '["Bromine gas","Bromine water","Acidified KMnO4","Copper(I) chloride"]', '<u>Copper(I) chloride</u> confirms terminal triple bonds.', '{"bold":["triple bond"],"italic":[],"underline":["Copper(I) chloride"],"fillBlanks":[]}');
