insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9aalg17patsq7lkjw1057unx', 'Government', 'JAMB', null, 2020, null, 'The best form of government for a heterogeneous society is a', null, '["quasi-federal system","federal system","unitary system","confederal system"]', 1, 'A federal system suits heterogeneous societies.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The best form of government for a heterogeneous society is a', '["quasi-federal system","<u>federal system</u>","unitary system","confederal system"]', '<u>Federal system</u>.', '{"bold":[],"italic":[],"underline":["federal system"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9abcb8e-f788-4f42-b8c5-96c5105c1807', 'Literature in English', 'JAMB', null, 2026, null, 'The ''path'' in the title functions symbolically as', null, '["a literal road connecting villages","a spiritual journey with no cultural ties","continuity of cultural ties","a political movement for independence"]', 2, 'The path symbolizes the continuity of cultural ties.', true, '2026-09-12 11:11:57.917', '2026-09-12 11:11:57.917', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9b0722f-1938-4225-8954-050d7f587bd9', 'English Language', 'JAMB', null, 2007, null, 'Either the chief of the village or the leader of the farmers <u>---------</u> to be held responsible for the revolt.', null, '["were","are","is","have"]', 2, '''Eitherâ€¦or'' agrees with nearer ''leader''.', true, '2026-10-24 01:02:12.847', '2026-10-24 01:02:12.847', null, null, null, 'Either the chief of the village or the leader of the farmers <u>---------</u> to be held responsible for the revolt.', '["were","are","<u>is</u>","have"]', '''<b>Eitherâ€¦or</b>'' agrees with nearer ''<b>leader</b>''.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9b2cd6a-6530-4d8c-9819-b0bc1ce19035', 'English Language', 'JAMB', null, 2024, null, 'After thorough observation, the members of the team discovered that the captain was a broken reed. This means that the chairman was', null, '["a strong defender","a reliable supporter","an unreliable person","a wise counselor"]', 2, '"A broken reed" means an unreliable person.', true, '2026-09-18 09:43:02.504', '2026-09-18 09:43:02.504', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9b2i0ai2zjidu8z6dmb4cf93', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the slope of the tangent to y = ln(ln x) at x = e.', null, '["0","1/e","1","e"]', 1, 'dy/dx = 1/(x ln x); at x=e: 1/e.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the slope of the tangent to y = ln(ln x) at x = e.', '["0","1/e","1","e"]', 'Slope = <u>1/e</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9b35bddcbm5hunnri8imdp10', 'Chemistry', 'JAMB', null, 1994, null, 'When sodium ethanoate is treated with a few drops of concentrated tetraoxosulphate(VI) acid one of the products is', null, '["CH3COOH","CH3COOH","CH3COOC2H5","CH3COOCH3"]', 0, 'CH3COONa + H2SO4 → CH3COOH + NaHSO4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When sodium ethanoate is treated with a few drops of concentrated tetraoxosulphate(VI) acid one of the products is', '["CH3COOH","CH3COOH","CH3COOC2H5","CH3COOCH3"]', '<u>CH3COOH</u> is produced.', '{"bold":[],"italic":[],"underline":["CH3COOH"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9b4dbfa-00df-4f47-8651-c6e0aa9a0fe6', 'Biology', 'JAMB', null, 2005, null, 'The importance of practicing crop rotation in agriculture is to', null, '["maintain soil fertility","improve the nutritional value of crops","control soil erosion","ensure the growth of crops"]', 0, 'Crop rotation maintains soil fertility.', true, '2026-10-12 20:59:37.99', '2026-10-12 20:59:37.99', null, null, null, 'The importance of practicing crop rotation in agriculture is to', '["maintain soil fertility","improve the nutritional value of crops","control soil erosion","ensure the growth of crops"]', 'Crop rotation maintains soil fertility.', '{"bold":["maintains soil fertility"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9b99104-6973-4e73-a905-5fe97293ce6c', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. I think I''ll like to <u>reiterate</u> the points earlier made.', null, '["withdraw","change","challenge","repeat"]', 3, 'Reiterate = repeat.', true, '2026-10-24 01:01:43.516', '2026-10-24 01:01:43.516', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. I think I''ll like to <u>reiterate</u> the points earlier made.', '["withdraw","change","challenge","<u>repeat</u>"]', '<b>Reiterate</b> = <b>repeat</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9bi7asttd33rd1jqzndiptbe', 'Chemistry', 'JAMB', null, 1983, null, 'The balanced equation for the reaction of tetraoxosulphate(VI) acid with aluminium hydroxide to give water and aluminium tetraoxosulphate(VI) is', null, '["H2SO4 + AlSO4 → 2H2O + AlSO4","H2SO4 + AlOH → Al2O + Al2SO4","3H2SO4 + 2Al(OH)3 → 6H2O + Al2(SO4)3","H2SO4 + Al(OH)3 → H2O + Al2(SO4)3","H2SO4 + Al(OH)3 → H2O + Al2(SO4)3"]', 2, 'Balanced: 3H2SO4 + 2Al(OH)3 → 6H2O + Al2(SO4)3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The balanced equation for the reaction of tetraoxosulphate(VI) acid with aluminium hydroxide to give water and aluminium tetraoxosulphate(VI) is', '["H2SO4 + AlSO4 → 2H2O + AlSO4","H2SO4 + AlOH → Al2O + Al2SO4","3H2SO4 + 2Al(OH)3 → 6H2O + Al2(SO4)3","H2SO4 + Al(OH)3 → H2O + Al2(SO4)3","H2SO4 + Al(OH)3 → H2O + Al2(SO4)3"]', '<u>3H2SO4 + 2Al(OH)3 → 6H2O + Al2(SO4)3</u>.', '{"bold":[],"italic":[],"underline":["3H2SO4 + 2Al(OH)3 → 6H2O + Al2(SO4)3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9bn4v0n3nal0h9k4b2r5pta2', 'General Mathematics', 'JAMB', null, 2020, null, 'If x > 0 and x + 1/x ≥ 2, then x is:', null, '["all positive reals","x ≥ 1","0 < x ≤ 1","x > 0 only"]', 0, 'AM-GM: x + 1/x ≥ 2 for all x > 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If x > 0 and x + 1/x ≥ 2, then x is:', '["all positive reals","x ≥ 1","0 < x ≤ 1","x > 0 only"]', 'All positive reals.', '{"bold":[],"italic":[],"underline":["all positive reals"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9bqyejog7mefbofww1gcvrl2', 'Chemistry', 'JAMB', null, 1999, null, 'A gaseous metallic chloride MClx consists of 20.22% of M by mass. The formula of the chloride is', null, '["MCl","MCl2","MCl3","M2Cl6 [M=27, Cl=35.5]"]', 2, 'Mass Cl = 79.78%; moles M:Cl = 20.22/27 : 79.78/35.5 = 0.75:2.25 = 1:3 → MCl3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A gaseous metallic chloride MClx consists of 20.22% of M by mass. The formula of the chloride is', '["MCl","MCl2","MCl3","M2Cl6"]', '<u>MCl3</u>.', '{"bold":[],"italic":[],"underline":["MCl3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9cmwaa6y17hmxeemsey9ut49', 'Chemistry', 'JAMB', null, 1985, null, 'What is the consequence of increasing pressure on the equilibrium reaction ZnO(s) + H2(g) ⇌ Zn(s) + H2O(g)?', null, '["The equilibrium is driven to the left","The equilibrium is driven to the right","There is no effect","More ZnO(s) is produced"]', 2, 'Equal moles of gas on both sides, so pressure has no effect.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is the consequence of increasing pressure on the equilibrium reaction ZnO(s) + H2(g) ⇌ Zn(s) + H2O(g)?', '["The equilibrium is driven to the left","The equilibrium is driven to the right","There is no effect","More ZnO(s) is produced"]', '<u>No effect</u> (equal gas moles on both sides).', '{"bold":[],"italic":[],"underline":["There is no effect"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9cvjbdn7svzhfps6y8m4kux2', 'Chemistry', 'JAMB', null, 1983, null, 'When sodium dioxonitrate(III) (NaNO2) dissolves in water, the process is', null, '["Exothermic","Endothermic","Isothermic","Isomeric","Hygroscopic"]', 1, 'Dissolution of NaNO2 in water is endothermic (temperature drops).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When sodium dioxonitrate(III) (NaNO2) dissolves in water, the process is', '["Exothermic","Endothermic","Isothermic","Isomeric","Hygroscopic"]', 'Dissolution of NaNO2 in water is <u>endothermic</u>.', '{"bold":[],"italic":[],"underline":["Endothermic"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9cxyliagdq38oyalwyjs6ubb', 'Biology', 'JAMB', null, 1995, null, 'The sex of a foetus is determined during', null, '["meiosis","copulation","fertilization","placentation."]', 2, 'fertilization is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The sex of a foetus is determined during', '["meiosis","copulation","<u>fertilization</u>","placentation."]', 'fertilization is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9d34ff0-ef08-4704-9c0d-96d26101b15d', 'Biology', 'JAMB', null, 2013, null, 'Which of the following is the simplest living organism?', null, '["Amoeba","Chlamydomonas","Paramecium","Virus"]', 3, 'Virus is the simplest living organism.', true, '2026-10-12 20:59:46.568', '2026-10-12 20:59:46.568', null, null, null, 'Which of the following is the simplest living organism?', '["Amoeba","Chlamydomonas","Paramecium","Virus"]', 'Virus is the simplest living organism.', '{"bold":["Virus"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9d3693c-8039-4980-8a19-752fc07c7b73', 'Physics', 'JAMB', null, 2026, null, 'Which of the following is most strongly deflected by a magnetic field?', null, '["gamma rays","x rays","alpha particles","beta particles"]', 3, 'Beta particles are most strongly deflected by a magnetic field. They have a small mass and a negative charge, giving them a high charge-to-mass ratio. Alpha particles are heavier and less deflected. Gamma rays and X-rays are uncharged and not deflected.', true, '2026-09-10 10:56:40.544', '2026-09-10 10:56:40.544', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9d3yja9ml9wafkzycnelcpa1', 'Chemistry', 'JAMB', null, 1995, null, 'Which of the following samples will <b>react faster</b> with dilute trioxonitrate(V) acid?', null, '["5g of lumps of CaCO3 at 25°C","5g of powdered CaCO3 at 25°C","5g of lumps of CaCO3 at 50°C","5g of powdered CaCO3 at 50°C"]', 3, 'Powdered CaCO3 at 50°C has the highest surface area and temperature.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following samples will <b>react faster</b> with dilute trioxonitrate(V) acid?', '["5g of lumps of CaCO3 at 25°C","5g of powdered CaCO3 at 25°C","5g of lumps of CaCO3 at 50°C","5g of powdered CaCO3 at 50°C"]', '<u>Powdered CaCO3 at 50°C</u> reacts fastest.', '{"bold":["react faster"],"italic":[],"underline":["5g of powdered CaCO3 at 50°C"],"fillBlanks":[]}');
