insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9dbnacj5r1682q5rl9o1o0bi', 'Biology', 'JAMB', null, 1988, null, 'In the kidney the malpighian corpuscle is located in the', null, '["medulla","helium","cortex","pelvis"]', 2, 'The malpighian corpuscle is in the cortex.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the kidney the <b>malpighian corpuscle</b> is located in the', '["medulla","helium","<u>cortex</u>","pelvis"]', 'The malpighian corpuscle is in the <u>cortex</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9de76cd-d090-4d30-9852-8e06c73c8cec', 'English Language', 'JAMB', null, 2024, null, 'According to the passage, astronauts', null, '["are always successful","always do what is expected of them","know they may not return from their journey into space","have courage and mental stability"]', 2, 'The passage states that astronauts may have a slight foreboding about the contingency of their non-return, meaning they know they may not return.', true, '2026-09-18 10:16:10.209', '2026-09-18 10:16:10.209', '11a7b560-dd3b-4c82-b5ad-fe71fdd120ed', 1, 'COMPREHENSION', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9dwboki0m608yq0ifql5fx33', 'Government', 'JAMB', null, 2020, null, 'One of the sources of a constitution is', null, '["common law","corporate law","statutory law","constitutional law"]', 0, 'Common law is a source of constitution.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One of the sources of a constitution is', '["<u>common law</u>","corporate law","statutory law","constitutional law"]', '<u>Common law</u>.', '{"bold":[],"italic":[],"underline":["common law"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9e1cbr33b7fo55qwynp9bkd8', 'Biology', 'JAMB', null, 2001, null, 'Water fleas, wood lice and barnacles belong to the group', null, '["arachnida","crustacea","insecta","chilopoda"]', 1, 'Water fleas, wood lice, barnacles are crustaceans.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Water fleas, wood lice and barnacles belong to the group', '["arachnida","crustacea","insecta","chilopoda"]', '<u>Crustacea</u>.', '{"bold":[],"italic":[],"underline":["crustacea"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9e7ter4ywy2ym5z5si76mhcx', 'Government', 'JAMB', null, 2020, null, 'France introduced the policy of assimilation in her colonies primarily to', null, '["teach them the art of leadership","change their way of life","give them a sound education","discourage them from ritual killings."]', 1, 'Assimilation aimed to change the way of life of colonized people.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'France introduced the policy of assimilation in her colonies primarily to', '["teach them the art of leadership","<u>change their way of life</u>","give them a sound education","discourage them from ritual killings."]', '<u>Change their way of life</u>.', '{"bold":[],"italic":[],"underline":["change their way of life"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9ec09ka2fw04hzqecvxqfcc4', 'Government', 'JAMB', null, 2020, null, 'Nigeria supports the South-South cooperation as a foreign policy objective for mutual understanding among', null, '["nations south of the equator.","sub-Saharan African countries","developing countries","Asian and sub-Saharan African countries"]', 2, 'South-South cooperation fosters understanding among developing countries.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Nigeria supports the South-South cooperation as a foreign policy objective for mutual understanding among', '["nations south of the equator.","sub-Saharan African countries","<u>developing countries</u>","Asian and sub-Saharan African countries"]', '<u>Developing countries</u>.', '{"bold":[],"italic":[],"underline":["developing countries"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9ef761b-d68c-4be2-a0ef-4caf80fbc866', 'English Language', 'JAMB', null, 2007, null, 'We are not surprised he was not elected; every one of his constituents <u>------------</u> that he is unreliable.', null, '["know","knows","will know","do know"]', 1, '''Every one'' singular â†’ knows.', true, '2026-10-24 01:02:12.741', '2026-10-24 01:02:12.741', null, null, null, 'We are not surprised he was not elected; every one of his constituents <u>------------</u> that he is unreliable.', '["know","<u>knows</u>","will know","do know"]', '''<b>Every one</b>'' singular â†’ <b>knows</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9egujh1pfw0af85t13bfbnjr', 'General Mathematics', 'JAMB', null, 2020, null, 'Simplify (3√2 - 2√3)/(3√2 + 2√3) + (3√2 + 2√3)/(3√2 - 2√3).', null, '["8","10","12","14"]', 1, 'Let a = 3√2, b = 2√3; (a-b)/(a+b) + (a+b)/(a-b) = 2(a²+b²)/(a²-b²) = 2(18+12)/(18-12) = 60/6 = 10.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Simplify (3√2 - 2√3)/(3√2 + 2√3) + (3√2 + 2√3)/(3√2 - 2√3).', '["8","10","12","14"]', 'Sum = <u>10</u>.', '{"bold":[],"italic":[],"underline":["10"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9el4ervilvz9cmq8mqiftdl0', 'Chemistry', 'JAMB', null, 1994, null, '20cm³ of a 2.0M solution of ethanoic acid was added to excess of 0.05M sodium hydroxide. The mass of the salt produced is', null, '["2.50g","2.73g","3.28g","4.54g [Na=23, C=12, O=16, H=1]"]', 1, 'Moles acid = 0.04; mass CH3COONa = 0.04 × 82 = 3.28g. Key says 2.73.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '20cm³ of a 2.0M solution of ethanoic acid was added to excess of 0.05M sodium hydroxide. The mass of the salt produced is', '["2.50g","2.73g","3.28g","4.54g"]', 'Mass = 0.04 × 82 = <u>3.28g</u> (key says 2.73).', '{"bold":[],"italic":[],"underline":["2.73g"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9enui7h7po4xanlcoew0e7zn', 'Biology', 'JAMB', null, 1999, null, 'The biomass is likely to increase in the sequence', null, '["1 à2à4à5","1à3à4à5","3à5à6à7","5à4à3à1"]', 0, '1 à2à4à5 is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The biomass is likely to increase in the sequence', '["<u>1 à2à4à5</u>","1à3à4à5","3à5à6à7","5à4à3à1"]', '1 à2à4à5 is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9eogjvz49ias0lomottozb4k', 'Islamic Religious Studies', 'JAMB', null, 2010, null, 'What is expected of a believing Muslim when an important decision needs to be made?', null, '["Du''a","Da''awah","Istikhama","Istikharah"]', 3, 'A Muslim should perform Istikharah (seeking guidance).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is expected of a believing Muslim when an important decision needs to be made?', '["Du''a","Da''awah","Istikhama","<u>Istikharah</u>"]', 'A Muslim should perform <u>Istikharah</u>.', '{"bold":[],"italic":[],"underline":["Istikharah"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9eq7j4kbv5dr5dyzsc65hr6q', 'Biology', 'JAMB', null, 1988, null, 'In a mammal, the placenta performs functions similar to those of the', null, '["lungs, kidneys and digestive system","lungs, heart and nervous system","liver, intestines and reproductive system","intestines, heart and digestive system"]', 0, 'The placenta acts like lungs, kidneys, and digestive system.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In a mammal, the placenta performs functions similar to those of the', '["<u>lungs, kidneys and digestive system</u>","lungs, heart and nervous system","liver, intestines and reproductive system","intestines, heart and digestive system"]', 'The placenta acts like <u>lungs, kidneys, and digestive system</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9f0p3ktkqoim1u5doh7o1g2b', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'According to Isaiah, God sent him to', null, '["proclaim liberty to the captives","proclaim victory over Israel''s enemies","preach the gospel to the poor","proclaim the day of vengeance of the LORD"]', 3, 'God sent Isaiah to proclaim the day of vengeance of the LORD.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to Isaiah, God sent him to', '["proclaim liberty to the captives","proclaim victory over Israel''s enemies","preach the gospel to the poor","<u>proclaim the day of vengeance of the LORD</u>"]', '<u>Proclaim the day of vengeance of the LORD</u> (Isaiah 61:1-2).', '{"bold":[],"italic":[],"underline":["proclaim the day of vengeance of the LORD"],"fillBlanks":[]}');
