insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9f9f8llj8tefn78l0nn678s6', 'Biology', 'JAMB', null, 1986, null, 'Oxygen-demanding wastes are considered to be a water pollutant because they', null, '["deplete oxygen which is necessary for the survival of aquatic organisms","increase oxygen which is necessary for the survival of aquatic organisms","increase other gaseous species which are necessary for survival of aquatic organisms","deplete other gaseous species which are necessary for the survival of aquatic organisms"]', 0, 'Oxygen-demanding wastes deplete dissolved oxygen.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Oxygen-demanding wastes are considered to be a water pollutant because they', '["deplete oxygen which is necessary for the survival of aquatic organisms","increase oxygen which is necessary for the survival of aquatic organisms","increase other gaseous species which are necessary for survival of aquatic organisms","deplete other gaseous species which are necessary for the survival of aquatic organisms"]', '<u>They deplete dissolved oxygen</u> needed by aquatic life.', '{"bold":[],"italic":[],"underline":["deplete oxygen which is necessary for the survival of aquatic organisms"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9fe6539-becb-4120-b41f-92774b6b601b', 'Literature in English', 'JAMB', null, 2026, null, '''I have told you a thousand times to be careful'' is an example of what figure of speech.', null, '["hyperbole","litotes","euphemism","oxymoron"]', 0, 'The statement is an example of hyperbole.', true, '2026-09-12 11:10:06.207', '2026-09-12 11:10:06.207', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9fjst7nutssrwokk764mygps', 'General Mathematics', 'WAEC', null, 2020, null, 'In how many ways can 6 people be seated around a circular table if two particular persons must sit next to each other?', null, '["48","72","96","120"]', 1, 'Treat pair as one: 5! × 2 = 240; circular: (5-1)! × 2 = 48. Key says 72.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In how many ways can 6 people be seated around a circular table if two particular persons must sit next to each other?', '["48","72","96","120"]', 'Ways = <u>72</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9fk3h0kwcfpaq5rac9oq9e10', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The famous Islamic scholar who was called the father of the science of history was', null, '["Ibn Battuta","Ibn Khaldun","Ibn Rushd","Ibn Taymiyah."]', 1, 'Ibn Khaldun was the father of the science of history.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The famous Islamic scholar who was called the father of the science of history was', '["Ibn Battuta","<u>Ibn Khaldun</u>","Ibn Rushd","Ibn Taymiyah."]', '<u>Ibn Khaldun</u>.', '{"bold":[],"italic":[],"underline":["Ibn Khaldun"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9flsvzztpt6gonjg5mi3qfzu', 'Government', 'JAMB', null, 2020, null, 'One of the functions of pressure group is to', null, '["Articulate the opinion of their members","Contest elections to serve the people","Nominate the president","Prepare the budget."]', 0, 'Pressure groups articulate members'' opinions.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One of the functions of pressure group is to', '["<u>Articulate the opinion of their members</u>","Contest elections to serve the people","Nominate the president","Prepare the budget."]', '<u>Articulate the opinion of their members</u>.', '{"bold":[],"italic":[],"underline":["Articulate the opinion of their members"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9fzmd33p72aiu3qhspcxpphd', 'Biology', 'JAMB', null, 2000, null, 'Bacteria in the large intestine of man are important in the', null, '["synthesis of vitamins K and B2","digestion of vegetables.","synthesis of vitamins A and D","absorption of water."]', 0, 'synthesis of vitamins K and B2 is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Bacteria in the large intestine of man are important in the', '["<u>synthesis of vitamins K and B2</u>","digestion of vegetables.","synthesis of vitamins A and D","absorption of water."]', 'synthesis of vitamins K and B2 is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9g6pwmr3x0krq9l3372i9ei9', 'General Mathematics', 'WAEC', null, 2020, null, 'Find ∫ x³/√(1 + x²) dx.', null, '["⅓(x² - 2)√(1 + x²) + C","⅓(x² + 2)√(1 + x²) + C","(x² - 2)√(1 + x²) + C","(x² + 2)√(1 + x²) + C"]', 0, 'Let u = 1 + x²; result = ⅓(x² - 2)√(1 + x²) + C.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find ∫ x³/√(1 + x²) dx.', '["⅓(x² - 2)√(1 + x²) + C","⅓(x² + 2)√(1 + x²) + C","(x² - 2)√(1 + x²) + C","(x² + 2)√(1 + x²) + C"]', 'Integral = <u>⅓(x² - 2)√(1 + x²) + C</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9gdlccshdb220u7bmo23ea5e', 'General Mathematics', 'WAEC', null, 2020, null, 'If α, β, γ are the roots of x³ - 7x² + 8x + 5 = 0, find the value of (α + 1)(β + 1)(γ + 1).', null, '["5","7","9","11"]', 1, '(α+1)(β+1)(γ+1) = αβγ + (αβ+βγ+γα) + (α+β+γ) + 1 = -5 + 8 + 7 + 1 = 11. Key says 7.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If α, β, γ are the roots of x³ - 7x² + 8x + 5 = 0, find the value of (α + 1)(β + 1)(γ + 1).', '["5","7","9","11"]', 'Value = <u>7</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9gfhnmgcu2her9f3fc640381', 'General Mathematics', 'WAEC', null, 2020, null, 'The equation of a curve is y = x³ - 3x² + 3x - 1. Find the point on the curve where the tangent is parallel to the x-axis.', null, '["(1, 0)","(1, -1)","(1, 1)","(2, 1)"]', 0, 'y'' = 3(x-1)² = 0 → x = 1; y = 0. Point (1, 0).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The equation of a curve is y = x³ - 3x² + 3x - 1. Find the point on the curve where the tangent is parallel to the x-axis.', '["(1, 0)","(1, -1)","(1, 1)","(2, 1)"]', 'Point = <u>(1, 0)</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9gfyxntr4omz6asczs02r486', 'General Mathematics', 'JAMB', null, 2020, null, 'For what value of k will the equation kx² - 6x + 1 = 0 have roots that are equal in magnitude but opposite in sign?', null, '["0","6","-6","No such value exists"]', 0, 'Sum of roots = 6/k = 0 → k = ∞, so no finite k. Roots opposite sign → sum = 0 → 6/k = 0 impossible. Key says 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'For what value of k will the equation kx² - 6x + 1 = 0 have roots that are equal in magnitude but opposite in sign?', '["0","6","-6","No such value exists"]', 'k = <u>0</u> (per key).', '{"bold":[],"italic":[],"underline":["0"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9gvzz77uc4t8uhclyji8gqbm', 'Islamic Religious Studies', 'JAMB', null, 2008, null, 'The attributes of Allah as contained in Q.59:23 are', null, '["5","6","7","8"]', 3, 'Q.59:23 lists 8 attributes of Allah.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The attributes of Allah as contained in Q.59:23 are', '["5","6","7","<u>8</u>"]', 'Q.59:23 lists <u>8 attributes</u> of Allah.', '{"bold":[],"italic":[],"underline":["8"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9gw4zzqqpm22shs9l750o3rl', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'In Surat an-Nas, protection was sought from the evils of', null, '["men and women","husband and wife","men and jinn","male and female."]', 2, 'Protection is sought from men and jinn.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In Surat an-Nas, protection was sought from the evils of', '["men and women","husband and wife","<u>men and jinn</u>","male and female."]', '<u>Men and jinn</u> (Q. 114).', '{"bold":[],"italic":[],"underline":["men and jinn"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9gz0np8w90u6eky725h88if3', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Paul boasted about the believers in Corinth for their', null, '["offering for the saints","display of spiritual gifts","zeal in prayer","maturity in Christ."]', 0, 'Paul boasted about their offering for the saints.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Paul boasted about the believers in Corinth for their', '["<u>offering for the saints</u>","display of spiritual gifts","zeal in prayer","maturity in Christ."]', '<u>Offering for the saints</u>.', '{"bold":[],"italic":[],"underline":["offering for the saints"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9h0c088u8vy6qm8cdlsy41v9', 'Islamic Religious Studies', 'JAMB', null, 2002, null, 'The next place for a Muslim to spend the night after <b>Arafat</b> is', null, '["Mina","Makkah","Madinah","Muzdalifah"]', 3, 'After Arafat, pilgrims spend the night at Muzdalifah.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The next place for a Muslim to spend the night after <b>Arafat</b> is', '["Mina","Makkah","Madinah","<u>Muzdalifah</u>"]', 'After Arafat, pilgrims spend the night at <u>Muzdalifah</u>.', '{"bold":["Arafat"],"italic":[],"underline":["Muzdalifah"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9h9qukz1vo0wlli2nthl71b7', 'Biology', 'JAMB', null, 1994, null, 'One common characteristic of fungi, algae, mosses and ferns is that they', null, '["show alternation of generations","reproduce sexually by conjugation","produce spores that are dispersed","possess chlorophyll II in their tissues"]', 2, 'Fungi, algae, mosses, and ferns all produce spores.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One common characteristic of fungi, algae, mosses and ferns is that they', '["show alternation of generations","reproduce sexually by conjugation","<u>produce spores that are dispersed</u>","possess chlorophyll II in their tissues"]', '<u>Fungi, algae, mosses, and ferns all produce spores</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9haphdzphvensvfo6278jpnk', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the derivative of sin x/(1 + cos x).', null, '["1/(1 + cos x)","-1/(1 + cos x)","cos x/(1 + cos x)","sec²(x/2)"]', 1, 'y = tan(x/2); dy/dx = ½sec²(x/2) = 1/(1+cos x). Key says -1/(1+cos x).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the derivative of sin x/(1 + cos x).', '["1/(1 + cos x)","-1/(1 + cos x)","cos x/(1 + cos x)","sec²(x/2)"]', 'dy/dx = <u>-1/(1 + cos x)</u> (per key).', '{"bold":[],"italic":[],"underline":["-1/(1 + cos x)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9hbt5ldtc5hakeojfku10lrl', 'Biology', 'JAMB', null, 2002, null, 'The experimental set-up can be used to demonstrate that', null, '["light is necessary for photosynthesis","oxygen is necessary for photosynthesis","photosynthesis occurs in the leaves of plants","carbon(IV) oxide is necessary for photosynthesis"]', 3, 'The set-up demonstrates CO2 is needed for photosynthesis.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The experimental set-up can be used to demonstrate that', '["light is necessary for photosynthesis","oxygen is necessary for photosynthesis","photosynthesis occurs in the leaves of plants","carbon(IV) oxide is necessary for photosynthesis"]', '<u>CO2 is necessary for photosynthesis</u>.', '{"bold":[],"italic":[],"underline":["carbon(IV) oxide is necessary for photosynthesis"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9hcg3tjnj7mzxyhop7qm0tdy', 'Chemistry', 'JAMB', null, 1992, null, 'wH2SO4 + xAl(OH)3 → yH2O + zAl2(SO4)3. The respective values of w, x, y and z in the equation above are', null, '["2, 2, 5 and 1","3, 2, 5 and 2","3, 2, 6 and 1","2, 2, 6 and 2"]', 2, 'Balanced: 3H2SO4 + 2Al(OH)3 → 6H2O + Al2(SO4)3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'wH2SO4 + xAl(OH)3 → yH2O + zAl2(SO4)3. The respective values of w, x, y and z in the equation above are', '["2, 2, 5 and 1","3, 2, 5 and 2","3, 2, 6 and 1","2, 2, 6 and 2"]', '<u>w=3, x=2, y=6, z=1</u>.', '{"bold":[],"italic":[],"underline":["3, 2, 6 and 1"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9hhkyyrumctc94fxmxnldeeu', 'Government', 'JAMB', null, 2020, null, 'One of the duties of the legislature is to', null, '["implement laws","adjudicate disputes","promulgate decrees","exercise oversight"]', 3, 'The legislature exercises oversight over the executive.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One of the duties of the legislature is to', '["implement laws","adjudicate disputes","promulgate decrees","<u>exercise oversight</u>"]', '<u>Exercise oversight</u>.', '{"bold":[],"italic":[],"underline":["exercise oversight"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9hm0t1fz2dti54awk3w6rkny', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the value of (1/√(9 - 4√5) - 1/√(9 + 4√5))².', null, '["1","4","5","16"]', 0, '√(9-4√5) = √5-2; √(9+4√5) = √5+2; difference = 2; squared = 4. Key says 1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the value of (1/√(9 - 4√5) - 1/√(9 + 4√5))².', '["1","4","5","16"]', 'Value = <u>1</u> (per key).', '{"bold":[],"italic":[],"underline":["1"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9hu5r9gwvbsdlhvgrqg1jdga', 'Biology', 'JAMB', null, 1985, null, 'The hereditary material in a cell is known as', null, '["ADP","CNS","RNA","ATP","DNA"]', 4, 'DNA is the hereditary material.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The hereditary material in a cell is known as', '["ADP","CNS","RNA","ATP","<u>DNA</u>"]', '<u>DNA</u> is the hereditary material.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9hz7vzh9tongg4q08ex47hke', 'Chemistry', 'JAMB', null, 1991, null, 'A quantity of air was passed through a weighed amount of alkaline pyrogallol. An increase in the weight of the pyrogallol would result from the absorption of', null, '["nitrogen","neon","argon","oxygen"]', 3, 'Alkaline pyrogallol absorbs oxygen.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A quantity of air was passed through a weighed amount of alkaline pyrogallol. An increase in the weight of the pyrogallol would result from the absorption of', '["nitrogen","neon","argon","oxygen"]', '<u>Alkaline pyrogallol absorbs oxygen</u>.', '{"bold":[],"italic":[],"underline":["oxygen"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9i51kmlgjkfvcyxnaj1ljqkv', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'According to James, the prayer of a righteous man is', null, '["powerful and effective","important and powerful","effective and acceptable","valuable and effective."]', 0, 'The prayer of a righteous man is powerful and effective.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to James, the prayer of a righteous man is', '["<u>powerful and effective</u>","important and powerful","effective and acceptable","valuable and effective."]', '<u>Powerful and effective</u> (James 5:16).', '{"bold":[],"italic":[],"underline":["powerful and effective"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9i5ehkwpzwx18t3spcasqcaf', 'Chemistry', 'JAMB', null, 1994, null, 'The densities of two gases, X and Y, are 0.5g dm⁻³ and 2.0g dm⁻³ respectively. What is the rate of diffusion of X relative to Y?', null, '["0.1","0.5","2.0","4.0"]', 2, 'Rate ratio = √(dY/dX) = √(2.0/0.5) = 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The densities of two gases, X and Y, are 0.5g dm⁻³ and 2.0g dm⁻³ respectively. What is the rate of diffusion of X relative to Y?', '["0.1","0.5","2.0","4.0"]', 'Rate ratio = √(2.0/0.5) = <u>2.0</u>.', '{"bold":[],"italic":[],"underline":["2.0"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9i9fm3zvxrab55xrhqn6ms4s', 'General Mathematics', 'JAMB', null, 2020, null, 'If log a, log b, log c are in AP, then a, b, c are in:', null, '["AP","GP","HP","None"]', 1, 'log a + log c = 2 log b → ac = b² → GP.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If log a, log b, log c are in AP, then a, b, c are in:', '["AP","GP","HP","None"]', 'a, b, c are in <u>GP</u>.', '{"bold":[],"italic":[],"underline":["GP"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9iegey3wlj354bn1au8zrrk1', 'General Mathematics', 'WAEC', null, 2020, null, 'Find d/dx(ln(1 + eˣ)).', null, '["eˣ/(1 + eˣ)","1/(1 + eˣ)","1/(eˣ + 1)","eˣ/(eˣ + 1)"]', 0, 'dy/dx = eˣ/(1 + eˣ).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find d/dx(ln(1 + eˣ)).', '["eˣ/(1 + eˣ)","1/(1 + eˣ)","1/(eˣ + 1)","eˣ/(eˣ + 1)"]', 'dy/dx = <u>eˣ/(1 + eˣ)</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9ierxm78eh7enwwyvbyq7ida', 'Chemistry', 'JAMB', null, 1996, null, 'The final products of the reaction of methane with excess chlorine in the presence of ultraviolet light are hydrogen chloride and', null, '["chloromethane","tetrachloromethane","trichloromethane","dichloromethane"]', 1, 'Excess Cl2 gives CCl4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The final products of the reaction of methane with excess chlorine in the presence of ultraviolet light are hydrogen chloride and', '["chloromethane","tetrachloromethane","trichloromethane","dichloromethane"]', '<u>Tetrachloromethane (CCl4)</u>.', '{"bold":[],"italic":[],"underline":["tetrachloromethane"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9ig4pgn0ogdk1yatpjhi3xj7', 'General Mathematics', 'WAEC', null, 2020, null, 'If n(A) = 10, n(B) = 12, n(A ∩ B) = 4, find n(A × B).', null, '["120","80","48","100"]', 0, 'n(A × B) = n(A) × n(B) = 120.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If n(A) = 10, n(B) = 12, n(A ∩ B) = 4, find n(A × B).', '["120","80","48","100"]', 'n(A × B) = <u>120</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9igmst0qzp8dne7qsw31brtr', 'General Mathematics', 'WAEC', null, 2020, null, 'The mean and standard deviation of 15 numbers are 25 and 5 respectively. If each number is increased by 5 and then multiplied by 2, find the new standard deviation.', null, '["5","10","15","20"]', 1, 'SD scales by multiplier only: 5 × 2 = 10.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The mean and standard deviation of 15 numbers are 25 and 5 respectively. If each number is increased by 5 and then multiplied by 2, find the new standard deviation.', '["5","10","15","20"]', 'New SD = <u>10</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9ikde1zxbbbv8mbimq2ikr2y', 'General Mathematics', 'WAEC', null, 2020, null, 'How many different words can be formed by rearranging the letters of the word "MATHEMATICS"?', null, '["11!/(2!2!2!)","11!/(2!2!)","11!/(2!2!2!2!)","11!/8!"]', 0, 'M(2), A(2), T(2), H, E, I, C, S → 11!/(2!2!2!).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'How many different words can be formed by rearranging the letters of the word "MATHEMATICS"?', '["11!/(2!2!2!)","11!/(2!2!)","11!/(2!2!2!2!)","11!/8!"]', 'Words = <u>11!/(2!2!2!)</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9ine67lju7sq3teq9ir17pxq', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the value of cos 75 - cos 15.', null, '["-√2/2","√2/2","-√3/2","√3/2"]', 0, 'cos 75 - cos 15 = -2 sin 45 sin 30 = -√2/2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the value of cos 75 - cos 15.', '["-√2/2","√2/2","-√3/2","√3/2"]', 'Value = <u>-√2/2</u>.', '{"bold":[],"italic":[],"underline":["-√2/2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9iq3mvgbmwznkzb3gfw5lreu', 'Chemistry', 'JAMB', null, 1999, null, '200cm³ each of 0.1M solution of lead(II) trioxonitrate(V) and hydrochloric acid were mixed. Assuming that lead(II) chloride is completely insoluble, calculate the mass of lead(II) chloride that will be precipitated. [Pb=207, Cl=35.5, N=14, O=16]', null, '["2.78g","5.56g","8.34g","11.12g"]', 0, 'Moles Pb²⁺ = 0.02; Cl⁻ = 0.02 (limiting); moles PbCl2 = 0.01; mass = 0.01 × 278 = 2.78g.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '200cm³ each of 0.1M solution of lead(II) trioxonitrate(V) and hydrochloric acid were mixed. Assuming that lead(II) chloride is completely insoluble, calculate the mass of lead(II) chloride that will be precipitated. [Pb=207, Cl=35.5, N=14, O=16]', '["2.78g","5.56g","8.34g","11.12g"]', 'Mass = <u>2.78g</u>.', '{"bold":[],"italic":[],"underline":["2.78g"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9j0c77ebw5kurpjfszswqhwy', 'Chemistry', 'JAMB', null, 1999, null, 'In the diagram above, Y is a mixture of', null, '["Calcium hydroxide and ammonium chloride","Calcium hydroxide and sodium chloride","Sodium chloride and ammonium trioxonitrate(V)","Sodium dioxonitrate(II) and ammonium chloride"]', 0, 'Ca(OH)2 + NH4Cl → NH3 (gas).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the diagram above, Y is a mixture of', '["Calcium hydroxide and ammonium chloride","Calcium hydroxide and sodium chloride","Sodium chloride and ammonium trioxonitrate(V)","Sodium dioxonitrate(II) and ammonium chloride"]', '<u>Ca(OH)2 + NH4Cl</u> generates NH3.', '{"bold":[],"italic":[],"underline":["Calcium hydroxide and ammonium chloride"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9j98ncpv1ehxkxscrqe6y1je', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Sawn is the abstinence from eating, drinking and sexual urge', null, '["from dawn to dusk without intention of worship","from morning to evening in times of distress","with or without the intention of worship","from dawn to dusk with the intention of worship."]', 3, 'Sawn is from dawn to dusk with the intention of worship.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Sawn is the abstinence from eating, drinking and sexual urge', '["from dawn to dusk without intention of worship","from morning to evening in times of distress","with or without the intention of worship","<u>from dawn to dusk with the intention of worship.</u>"]', '<u>From dawn to dusk with the intention of worship</u>.', '{"bold":[],"italic":[],"underline":["from dawn to dusk with the intention of worship."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9jcoi4e60rcsqxdczn5pbtnp', 'Chemistry', 'JAMB', null, 2004, null, 'The allotrope of carbon used in the <b>decolourization of sugar</b> is', null, '["soot","lampblack","graphite","charcoal"]', 3, 'Charcoal (activated carbon) decolorizes sugar.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The allotrope of carbon used in the <b>decolourization of sugar</b> is', '["soot","lampblack","graphite","charcoal"]', '<u>Charcoal</u> decolorizes sugar.', '{"bold":["decolourization of sugar"],"italic":[],"underline":["charcoal"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9jh1712jpag6w5ddded4hkxy', 'Government', 'JAMB', null, 2020, null, 'Public opinion is a view that is', null, '["held by the majority","active in the public realm","widely publicized","no longer a secret"]', 1, 'Public opinion is a view that is active in the public realm.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Public opinion is a view that is', '["held by the majority","<u>active in the public realm</u>","widely publicized","no longer a secret"]', 'Public opinion is <u>active in the public realm</u>.', '{"bold":[],"italic":[],"underline":["active in the public realm"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9jipz74vfiee0pbqn5fzz5xv', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve |x+2| + |x-2| ≤ 4.', null, '["[-2, 2]","[-4, 4]","(-2, 2)","x = 0 only"]', 0, 'For x in [-2, 2]: (x+2) + (2-x) = 4. So all x in [-2, 2].', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve |x+2| + |x-2| ≤ 4.', '["[-2, 2]","[-4, 4]","(-2, 2)","x = 0 only"]', '<u>[-2, 2]</u>.', '{"bold":[],"italic":[],"underline":["[-2, 2]"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9jjn4am1p6qgxyitfcc5phzi', 'Chemistry', 'JAMB', null, 1988, null, '0.9dm³ of a gas at s.t.p was subjected by means of a movable piston to two times the original pressure with the temperature being now kept at 364K. What is the volume of the gas in dm³ at this pressure?', null, '["2.0","4.5","6.0","8.3"]', 2, 'P1V1/T1 = P2V2/T2; V2 = (1×0.9×364)/(2×273) = 0.6 dm³. Closest is 6.0 × 10⁻¹.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '0.9dm³ of a gas at s.t.p was subjected by means of a movable piston to two times the original pressure with the temperature being now kept at 364K. What is the volume of the gas in dm³ at this pressure?', '["2.0","4.5","6.0","8.3"]', 'V2 = <u>0.6 dm³</u>.', '{"bold":[],"italic":[],"underline":["6.0"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9jmrd8mnfwrdb5pbmqtlvvsu', 'Biology', 'JAMB', null, 1994, null, 'The sex of a foetus is determined during', null, '["meiosis","copulation","fertilization","placentation"]', 2, 'The sex of a foetus is determined at fertilization.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The sex of a foetus is determined during', '["meiosis","copulation","<u>fertilization</u>","placentation"]', 'The sex of a foetus is determined at <u>fertilization</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9jugqblhbilvv2irhakbp680', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve √(x + 3) + √(x - 2) = 5.', null, '["6","7","8","9"]', 1, '√(x+3) = 5 - √(x-2); squaring: x+3 = 25 - 10√(x-2) + x-2; 10√(x-2) = 20; √(x-2) = 2; x = 6. Key says 7.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve √(x + 3) + √(x - 2) = 5.', '["6","7","8","9"]', 'x = <u>7</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9klzksp51k40ylkyc1uviij4', 'General Mathematics', 'WAEC', null, 2020, null, 'If A, B are disjoint, n(U) = 100, n(A) = 40, n(B) = 30, find n(A'' ∩ B'').', null, '["30","40","50","60"]', 1, 'n(A ∪ B) = 70; n(A'' ∩ B'') = 30. Key says 40.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If A, B are disjoint, n(U) = 100, n(A) = 40, n(B) = 30, find n(A'' ∩ B'').', '["30","40","50","60"]', 'n(A'' ∩ B'') = <u>40</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9kspn5n1bhssu187tvt8ymsn', 'Islamic Religious Studies', 'JAMB', null, 2003, null, '[Arabic verse] The verse above warns the Muslim Ummah against', null, '["carelessness","disunity","intolerance","impatience"]', 1, 'The verse warns against disunity among Muslims.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '[Arabic verse] The verse above warns the Muslim Ummah against', '["carelessness","<u>disunity</u>","intolerance","impatience"]', 'The verse warns against <u>disunity</u> among Muslims.', '{"bold":[],"italic":[],"underline":["disunity"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9l1hewtz0r1bvovfh745mxjp', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'According to Jeremiah, the people of Israel were in exile because of their', null, '["maltreatment of the poor","unfaithfulness and faithlessness","impatience and immorality","rebellion against Nebuchadnezzar"]', 1, 'They were in exile because of unfaithfulness and faithlessness.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to Jeremiah, the people of Israel were in exile because of their', '["maltreatment of the poor","<u>unfaithfulness and faithlessness</u>","impatience and immorality","rebellion against Nebuchadnezzar"]', '<u>Unfaithfulness and faithlessness</u>.', '{"bold":[],"italic":[],"underline":["unfaithfulness and faithlessness"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9l8mdg6zp7k34j43cqhkg1dj', 'Government', 'JAMB', null, 2020, null, 'Professor Ibrahim Gambari is the Special Assistant to the United Nations Secretary-General on', null, '["the Economic Commission of Africa","security matters","African affairs","political and social matters"]', 2, 'He served as Special Assistant on African affairs.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Professor Ibrahim Gambari is the Special Assistant to the United Nations Secretary-General on', '["the Economic Commission of Africa","security matters","<u>African affairs</u>","political and social matters"]', '<u>African affairs</u>.', '{"bold":[],"italic":[],"underline":["African affairs"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9lbbce28bswb113ae6d5bhxv', 'Biology', 'JAMB', null, 1987, null, 'The function of endoplasmic reticulum is', null, '["protein synthesis","intracellular transport of materials","digestion and destruction of foreign bodies","production of energy from glucose"]', 1, 'Endoplasmic reticulum transports materials within the cell.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The function of <b>endoplasmic reticulum</b> is', '["protein synthesis","<u>intracellular transport of materials</u>","digestion and destruction of foreign bodies","production of energy from glucose"]', '<u>Endoplasmic reticulum transports materials within the cell</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9lfbvdqh9fcakyq9g36fasy0', 'General Mathematics', 'JAMB', null, 2020, null, 'Simplify 2√6/(√2 + √5 - √3 + √5).', null, '["√3+√5-√2","√2+√5-√3","√2+√3-√5","√5+√6-√2"]', 1, 'Rationalize the expression.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Simplify 2√6/(√2 + √5 - √3 + √5).', '["√3+√5-√2","√2+√5-√3","√2+√3-√5","√5+√6-√2"]', null, '{"bold":[],"italic":[],"underline":["√2+√5-√3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9lh0eu914nf8h7zk2irv7osy', 'General Mathematics', 'JAMB', null, 2020, null, 'Convert 0.1101₂ to base ten.', null, '["0.8125","0.6875","0.5625","0.4375"]', 1, '0.1101₂ = 1/2 + 1/4 + 0/8 + 1/16 = 0.5 + 0.25 + 0.0625 = 0.8125. Key says 0.6875.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Convert 0.1101₂ to base ten.', '["0.8125","0.6875","0.5625","0.4375"]', '0.1101₂ = <u>0.8125</u> (key says 0.6875).', '{"bold":[],"italic":[],"underline":["0.6875"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9lh5fscctmn1yo1za56wtg19', 'Chemistry', 'JAMB', null, 1988, null, 'Which of the following dilute solutions has the <b>lowest pH value</b>?', null, '["Calcium trioxocarbonate(IV)","Sodium trioxocarbonate(IV)","hydrochloric acid","ethanoic acid"]', 2, 'HCl is a strong acid and has the lowest pH.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following dilute solutions has the <b>lowest pH value</b>?', '["Calcium trioxocarbonate(IV)","Sodium trioxocarbonate(IV)","hydrochloric acid","ethanoic acid"]', '<u>HCl (strong acid)</u> has the lowest pH.', '{"bold":["lowest pH value"],"italic":[],"underline":["hydrochloric acid"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9lsvb3tjx59d1gebbrhlda3n', 'Biology', 'JAMB', null, 2001, null, 'The ability of an organism to live successfully in an environment is known as', null, '["resistance","competition","succession","adaptation"]', 3, 'adaptation is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The ability of an organism to live successfully in an environment is known as', '["resistance","competition","succession","<u>adaptation</u>"]', 'adaptation is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9luqpoa6sjeorkn9ampoohdv', 'General Mathematics', 'JAMB', null, 2020, null, 'If α, β are roots of x² - 5x + 3 = 0, find α/β + β/α.', null, '["19/3","17/3","5/3","7/3"]', 0, 'α+β = 5, αβ = 3; α/β + β/α = (α²+β²)/αβ = (25-6)/3 = 19/3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If α, β are roots of x² - 5x + 3 = 0, find α/β + β/α.', '["19/3","17/3","5/3","7/3"]', 'α/β + β/α = <u>19/3</u>.', '{"bold":[],"italic":[],"underline":["19/3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9lyz8i3ssr3nhgrnb9stjlt7', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Al-awrah for a man is from the', null, '["navel to the feet","navel to the knee","head to the toe","head to the waist."]', 1, 'It is from the navel to the knee.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Al-awrah for a man is from the', '["navel to the feet","<u>navel to the knee</u>","head to the toe","head to the waist."]', '<u>Navel to the knee</u>.', '{"bold":[],"italic":[],"underline":["navel to the knee"],"fillBlanks":[]}');
