insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9mtgv8r24qufgahngxqqubfa', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The message in Q. 2:219 is that wine and gambling are', null, '["good for man","bad for man","profitable for man","harmless to man"]', 1, 'Wine and gambling are bad for man.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The message in Q. 2:219 is that wine and gambling are', '["good for man","<u>bad for man</u>","profitable for man","harmless to man"]', '<u>Bad for man</u> (Q. 2:219).', '{"bold":[],"italic":[],"underline":["bad for man"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9n0j4xxklef96p6qn1jvj92k', 'Biology', 'JAMB', null, 2000, null, 'A cross between an albino female and a genetically normal male will result in offspring that are', null, '["all albino","all phenotypically normal","all genetically normally","half albino and half normal"]', 1, 'Albino (aa) × normal (AA) → all Aa (phenotypically normal).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A cross between an albino female and a genetically normal male will result in offspring that are', '["all albino","all phenotypically normal","all genetically normally","half albino and half normal"]', '<u>All phenotypically normal</u> (Aa).', '{"bold":[],"italic":[],"underline":["all phenotypically normal"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9n35860wnyx7uqfatkhnxoe3', 'Chemistry', 'JAMB', null, 1983, null, 'When the <b>kerosene fraction</b> from petrol is heated at high temperature, a lower boiling liquid is obtained. This process is known as', null, '["polymerization","refining","hydrogenation","cracking","fractional distillation"]', 3, 'Cracking breaks large hydrocarbon molecules into smaller ones.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When the <b>kerosene fraction</b> from petrol is heated at high temperature, a lower boiling liquid is obtained. This process is known as', '["polymerization","refining","hydrogenation","cracking","fractional distillation"]', '<u>Cracking</u> breaks large hydrocarbon molecules into smaller ones.', '{"bold":["kerosene fraction"],"italic":[],"underline":["cracking"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9n4oabuehqx662z7qmgi2jz0', 'Biology', 'JAMB', null, 2002, null, 'The mammalian erythrocytes differ from amphibian erythrocytes because they are', null, '["discoid and nucleated","discoid and enucleated","amoeboid and nucleated","amoeboid and enucleated"]', 1, 'Mammalian RBCs are discoid and enucleated.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The mammalian erythrocytes differ from amphibian erythrocytes because they are', '["discoid and nucleated","discoid and enucleated","amoeboid and nucleated","amoeboid and enucleated"]', '<u>Discoid and enucleated</u>.', '{"bold":[],"italic":[],"underline":["discoid and enucleated"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9na9q0ddmu0qb7grwz1bq8o1', 'Chemistry', 'JAMB', null, 2004, null, 'The oxidation state of chlorine in <b>HClO4</b> is', null, '["-1","-5","+7","+1"]', 2, 'In HClO4, Cl = +7.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The oxidation state of chlorine in <b>HClO4</b> is', '["-1","-5","+7","+1"]', '<u>+7</u> in HClO4.', '{"bold":["HClO4"],"italic":[],"underline":["+7"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9ndbduim810fvm52kmjsfo0l', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve 2x² - 4 < 8x.', null, '["2 - √6 < x < 2 + √6","x < -1 or x > 4","-2 < x < 2","x < -2 or x > 2"]', 0, 'x² - 4x - 2 < 0 → 2 - √6 < x < 2 + √6.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Solve 2x² - 4 < 8x.', '["2 - √6 < x < 2 + √6","x < -1 or x > 4","-2 < x < 2","x < -2 or x > 2"]', 'x² - 4x - 2 < 0 → 2 - √6 < x < 2 + √6.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9nkmuvnfe8qema79csleuu7b', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Lord, if you will, you can make me clean. The statement above was made by the', null, '["centurion servant","epileptic boy","leper","paralytic"]', 2, 'The leper made this statement.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Lord, if you will, you can make me clean. The statement above was made by the', '["centurion servant","epileptic boy","<u>leper</u>","paralytic"]', '<u>Leper</u> (Matthew 8:2).', '{"bold":[],"italic":[],"underline":["leper"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9nmzrkxhg1qhskdzmhnn0jyl', 'General Mathematics', 'WAEC', null, 2020, null, 'If A = {1, 2, 3, 4}, B = {2, 4, 6}, C = {3, 4, 5}, find (A ∩ B) ∪ (B ∩ C).', null, '["{4}","{2, 4}","{4, 6}","{2, 4, 6}"]', 1, 'A ∩ B = {2, 4}; B ∩ C = {4}; union = {2, 4}.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If A = {1, 2, 3, 4}, B = {2, 4, 6}, C = {3, 4, 5}, find (A ∩ B) ∪ (B ∩ C).', '["{4}","{2, 4}","{4, 6}","{2, 4, 6}"]', 'Union = <u>{2, 4}</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9noybq31rujftinzduxpk1kc', 'Chemistry', 'JAMB', null, 1987, null, 'The structure of <b>benzoic acid</b> is', null, '["C6H5COOH","C6H5OH","C6H5CHO","C6H5COCH3"]', 0, 'Benzoic acid is C6H5COOH.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The structure of <b>benzoic acid</b> is', '["C6H5COOH","C6H5OH","C6H5CHO","C6H5COCH3"]', '<u>Benzoic acid is C6H5COOH</u>.', '{"bold":["benzoic acid"],"italic":[],"underline":["C6H5COOH"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9nt48ohln6kdvf0wxmqbmlav', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'One of the lessons taught in surah al-Ma''un is that', null, '["man''s obligation towards Allah is constant","people should be cautious about their devotions","a hypocrite is one who shows off in his worship","a good Muslim should always be honest in his works and worship."]', 2, 'A hypocrite shows off in his worship.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One of the lessons taught in surah al-Ma''un is that', '["man''s obligation towards Allah is constant","people should be cautious about their devotions","<u>a hypocrite is one who shows off in his worship</u>","a good Muslim should always be honest in his works and worship."]', '<u>A hypocrite is one who shows off in his worship</u> (Q. 107).', '{"bold":[],"italic":[],"underline":["a hypocrite is one who shows off in his worship"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9nzjr9zbzlmm5f31gvuzptx8', 'Biology', 'JAMB', null, 1988, null, 'Which of the following has the greatest influence on the distribution of animals in marine and fresh water habitats?', null, '["pH","Salinity","Water current","Turbidity"]', 1, 'Salinity has the greatest influence on aquatic animal distribution.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following has the greatest influence on the distribution of animals in marine and fresh water habitats?', '["pH","<u>Salinity</u>","Water current","Turbidity"]', '<u>Salinity</u> has the greatest influence on aquatic animal distribution.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9o238b8ymbw2zhlajrmjufsf', 'General Mathematics', 'WAEC', null, 2020, null, 'Find remainder when 7⁷ is divided by 5.', null, '["2","3","4","1"]', 1, '7 ≡ 2 mod 5; 2⁷ = 128 ≡ 3 mod 5.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find remainder when 7⁷ is divided by 5.', '["2","3","4","1"]', '7⁷ ≡ 2⁷ = 128 ≡ <u>3</u> mod 5.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9oiynvyckcmmwc6c7sl237p5', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the quadratic with roots α + 1/β, β + 1/α where α, β are roots of x² - 3x + 1 = 0.', null, '["x² - 6x + 7 = 0","x² - 6x + 8 = 0","x² - 5x + 6 = 0","x² - 5x + 4 = 0"]', 0, 'α+β = 3, αβ = 1; sum of new roots = 6; product = 7 → x² - 6x + 7 = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the quadratic with roots α + 1/β, β + 1/α where α, β are roots of x² - 3x + 1 = 0.', '["x² - 6x + 7 = 0","x² - 6x + 8 = 0","x² - 5x + 6 = 0","x² - 5x + 4 = 0"]', 'Quadratic = <u>x² - 6x + 7 = 0</u>.', '{"bold":[],"italic":[],"underline":["x² - 6x + 7 = 0"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9ol53ij4uyizt7jadelr4zux', 'Government', 'JAMB', null, 2020, null, 'The abolition of the state ministries of local governments in 1989 entails that local governments', null, '["no longer have anything to do with state government","are no longer subordinate to state governments","have more control over their funds","are equal to the states"]', 2, 'Local governments gained more control over funds.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The abolition of the state ministries of local governments in 1989 entails that local governments', '["no longer have anything to do with state government","are no longer subordinate to state governments","<u>have more control over their funds</u>","are equal to the states"]', '<u>More control over their funds</u>.', '{"bold":[],"italic":[],"underline":["have more control over their funds"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9opuvkp6ubu1d9gxsm4wyqac', 'Biology', 'JAMB', null, 2003, null, 'The umbrella-shaped fruiting body of a fully developed mushroom is the', null, '["mycelium","basidium","pileus","stipe Use the diagram above to answer question 2 and 3."]', 2, 'pileus is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The umbrella-shaped fruiting body of a fully developed mushroom is the', '["mycelium","basidium","<u>pileus</u>","stipe Use the diagram above to answer question 2 and 3."]', 'pileus is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9ouqt2362mp8ss9zwa9vy8no', 'Biology', 'JAMB', null, 2002, null, 'Use the diagram to answer questions 43 and 44. The gland usually found in the position labelled is the', null, '["adrenal","thyroid","pancreatic","pituitary"]', 2, 'The gland in that position is the pancreatic gland.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Use the diagram to answer questions 43 and 44. The gland usually found in the position labelled is the', '["adrenal","thyroid","pancreatic","pituitary"]', '<u>Pancreatic gland</u>.', '{"bold":[],"italic":[],"underline":["pancreatic"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9oxenor0uwt5vlte8pbq78mh', 'General Mathematics', 'WAEC', null, 2020, null, 'Three cards are drawn. Find the probability that at least one is an ace.', null, '["1 - (48/52)(47/51)(46/50)","1 - (48/52)(47/51)(45/50)","Both A and B","Neither"]', 0, 'P(at least one ace) = 1 - P(no ace).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Three cards are drawn. Find the probability that at least one is an ace.', '["1 - (48/52)(47/51)(46/50)","1 - (48/52)(47/51)(45/50)","Both A and B","Neither"]', 'P = <u>1 - (48/52)(47/51)(46/50)</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9pjheq8ibgioit9zczsn5f1v', 'Chemistry', 'JAMB', null, 1994, null, 'The reaction taking place in flask G is known as', null, '["hydrolysis","double decomposition","dehydration","pyrolysis"]', 2, 'Ethanol + concentrated H2SO4 → ethene (dehydration).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The reaction taking place in flask G is known as', '["hydrolysis","double decomposition","dehydration","pyrolysis"]', '<u>Dehydration</u> of ethanol to ethene.', '{"bold":[],"italic":[],"underline":["dehydration"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9pnccf931565oioj1611u8ch', 'General Mathematics', 'WAEC', null, 2020, null, 'The line y = mx + c is a tangent to the curve y = x² - 4x + 5. Find the possible value(s) of m.', null, '["m = 2 only","m = -2 only","m = 2 or -2","m = 0 only"]', 2, 'Tangent: discriminant = 0 → (m+4)² - 4(5-c) = 0; various m possible. Key says m = 2 or -2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The line y = mx + c is a tangent to the curve y = x² - 4x + 5. Find the possible value(s) of m.', '["m = 2 only","m = -2 only","m = 2 or -2","m = 0 only"]', 'm = <u>2 or -2</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9pv8n7omp92bnd48yd3qdj1e', 'Government', 'JAMB', null, 2020, null, 'The designation of ministers as Chief Executive and accounting officers was recommended by a commission headed by', null, '["Jerome Udaji","Simeon Adebo","S. J. Cookey","Dotun Phillips"]', 3, 'The Dotun Phillips commission made this recommendation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The designation of ministers as Chief Executive and accounting officers was recommended by a commission headed by', '["Jerome Udaji","Simeon Adebo","S. J. Cookey","<u>Dotun Phillips</u>"]', '<u>Dotun Phillips</u>.', '{"bold":[],"italic":[],"underline":["Dotun Phillips"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9pzfny5erujqofmhqztvdq8h', 'General Mathematics', 'JAMB', null, 2020, null, 'What is the area of quadrilateral with vertices (0,0), (4,0), (4,3), and (0,3)?', null, '["12","16","20","24"]', 0, 'Rectangle 4×3 = 12.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is the area of quadrilateral with vertices (0,0), (4,0), (4,3), and (0,3)?', '["12","16","20","24"]', 'Area = <u>12</u>.', '{"bold":[],"italic":[],"underline":["12"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9q7lh7x6g8aj5g34cqo5gvrg', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Following the death of Stephen, the only group of believers not scattered by the great persecution against the Jerusalem Church were the', null, '["deacons","apostles","prophets","disciples"]', 1, 'The apostles were not scattered.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Following the death of Stephen, the only group of believers not scattered by the great persecution against the Jerusalem Church were the', '["deacons","<u>apostles</u>","prophets","disciples"]', '<u>Apostles</u> (Acts 8:1).', '{"bold":[],"italic":[],"underline":["apostles"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9qvtmfqa93i0dpq2k9j1ok17', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'In Colossians, Christians are advised to be diligent at work because in so doing, they are', null, '["serving God","exalting themselves","challenging unbelievers","worthy of heaven"]', 0, 'They are serving God.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In Colossians, Christians are advised to be diligent at work because in so doing, they are', '["<u>serving God</u>","exalting themselves","challenging unbelievers","worthy of heaven"]', '<u>Serving God</u> (Colossians 3:23).', '{"bold":[],"italic":[],"underline":["serving God"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9r8xdts3clot0oman16jcg4e', 'Chemistry', 'JAMB', null, 2004, null, 'when Zinc goes from Zn to Zn²⁺, it has been_____________________', null, '["displaced","oxidized","reduced","decomposed"]', 1, 'Zn is oxidized to Zn²⁺.', true, '2026-10-11 07:17:11.699', '2026-10-24 07:28:59.139', null, null, null, 'In the reaction above, Zinc has been', '["displaced","oxidized","reduced","decomposed"]', '<u>Zinc is oxidized</u>.', '{"bold":[],"italic":[],"underline":["oxidized"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9rbnw0mayhnv7ctx6ecc66hf', 'Chemistry', 'JAMB', null, 1985, null, 'In the course of an experiment, two gases X and Y were produced. X turned wet lead ethanoate to black and Y bleached moist litmus paper. What are the elements in each of the gases X and Y respectively?', null, '["H and S; Cl","H and O; Cl","H and S; C and O","H and Cl; S and O"]', 2, 'X is H2S (H and S); Y is Cl2 (Cl). Answer key says H and S; C and O.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the course of an experiment, two gases X and Y were produced. X turned wet lead ethanoate to black and Y bleached moist litmus paper. What are the elements in each of the gases X and Y respectively?', '["H and S; Cl","H and O; Cl","H and S; C and O","H and Cl; S and O"]', 'X is H2S (H and S); Y is Cl2 (Cl).', '{"bold":[],"italic":[],"underline":["H and S; C and O"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9rujqtg7wbyper16tw2h14r5', 'General Mathematics', 'WAEC', null, 2020, null, 'If A³ = 0, find (I - A)⁻¹.', null, '["I + A + A²","I - A + A²","I - A","I + A"]', 0, '(I-A)(I+A+A²) = I - A³ = I.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If A³ = 0, find (I - A)⁻¹.', '["I + A + A²","I - A + A²","I - A","I + A"]', '(I - A)⁻¹ = <u>I + A + A²</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9se5uvrca5x907kkiyaxcalc', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the inverse of 5 under a*b = a + b - 5 on reals, given identity e = 5.', null, '["5","-5","0","10"]', 1, '5*x = 5 → 5+x-5 = 5 → x = 5. Key says -5.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the inverse of 5 under a*b = a + b - 5 on reals, given identity e = 5.', '["5","-5","0","10"]', 'Inverse = <u>-5</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9sfeuhmlltsj2x0ligmlgpcv', 'General Mathematics', 'WAEC', null, 2020, null, 'From an external point T, tangents TP and TQ are drawn to a circle with center O. A third tangent touches the circle at R and meets TP and TQ at X and Y respectively. If the radius is 6 cm and OT = 10 cm, find the perimeter of triangle TXY.', null, '["12 cm","14 cm","16 cm","20 cm"]', 2, 'Tangent length = 8; perimeter = 2 × 8 = 16 cm.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'From an external point T, tangents TP and TQ are drawn to a circle with center O. A third tangent touches the circle at R and meets TP and TQ at X and Y respectively. If the radius is 6 cm and OT = 10 cm, find the perimeter of triangle TXY.', '["12 cm","14 cm","16 cm","20 cm"]', 'Perimeter = <u>16 cm</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9sict1fk8jl8hdlndah0e2lp', 'Biology', 'JAMB', null, 1989, null, 'The pancreatic juice contains the enzymes amylopsin,', null, '["pepsin and trypsinogen","rennin and steapsin","steapsin and trypsinogen","steapsin and ptyalin"]', 2, 'Pancreatic juice contains steapsin and trypsinogen.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The pancreatic juice contains the enzymes amylopsin,', '["pepsin and trypsinogen","rennin and steapsin","<u>steapsin and trypsinogen</u>","steapsin and ptyalin"]', 'Pancreatic juice contains <u>steapsin and trypsinogen</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9snq8feg12zdau43y6fl64y1', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Jesus told the parable of the lost sheep in order to illustrate that', null, '["every believer ought to rejoice with those who rejoice","no person can hide from God","God''s love is unlimited","there is joy in heaven over a sinner who repents."]', 3, 'It illustrates joy in heaven over a repentant sinner.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Jesus told the parable of the lost sheep in order to illustrate that', '["every believer ought to rejoice with those who rejoice","no person can hide from God","God''s love is unlimited","<u>there is joy in heaven over a sinner who repents.</u>"]', '<u>There is joy in heaven over a sinner who repents</u> (Luke 15:4-7).', '{"bold":[],"italic":[],"underline":["there is joy in heaven over a sinner who repents."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9sojf9lxgw4x3cwa0lgacnr2', 'Chemistry', 'JAMB', null, 2004, null, 'Given that ΔHf[CO] is -110.4 kJ mol⁻¹ and ΔHf[CO2] is -393.5 kJ mol⁻¹, the energy change for the reaction CO(g) + ½O2(g) → CO2(g) is', null, '["-282.6kJ","+503.7kJ","-503.7kJ","+282.6kJ"]', 0, 'ΔH = -393.5 - (-110.4) = -282.6 kJ.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Given that ΔHf[CO] is -110.4 kJ mol⁻¹ and ΔHf[CO2] is -393.5 kJ mol⁻¹, the energy change for the reaction CO(g) + ½O2(g) → CO2(g) is', '["-282.6kJ","+503.7kJ","-503.7kJ","+282.6kJ"]', 'ΔH = <u>-282.6 kJ</u>.', '{"bold":[],"italic":[],"underline":["-282.6kJ"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9sqb7ajli7k9s1te29ehip0s', 'General Mathematics', 'JAMB', null, 2020, null, 'If 123_(b+1) = 162₁₀, find b.', null, '["6","7","8","9"]', 1, '1(b+1)² + 2(b+1) + 3 = 162 → b² + 2b + 1 + 2b + 2 + 3 = 162 → b² + 4b + 6 = 162 → b² + 4b - 156 = 0 → b = 10 or -14. Key says 7.', false, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'If 123_(b+1) = 162₁₀, find b.', '["6","7","8","9"]', 'b² + 4b - 156 = 0 → <u>b = 10</u> (key says 7).', '{"bold":[],"italic":[],"underline":["7"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9sr23vney1wj0593j4bvn1yy', 'Chemistry', 'JAMB', null, 2019, null, 'Which of the following pairs is an example of position isomerism?', null, '["CH3-CH2-CH2-CH3 and CH3-CH(CH3)-CH3","CH3-CH2-CH=CH2 and CH3-CH=CH-CH3","CH3-CH2OH and CH2-O-CH3","CH3-C(CH3)2-CH3 and CH3-CH2-CH2-CH2-CH3"]', 1, 'The double bond is in different positions in the two compounds.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following pairs is an example of <b>position isomerism</b>?', '["CH3-CH2-CH2-CH3 and CH3-CH(CH3)-CH3","<u>CH3-CH2-CH=CH2 and CH3-CH=CH-CH3</u>","CH3-CH2OH and CH2-O-CH3","CH3-C(CH3)2-CH3 and CH3-CH2-CH2-CH2-CH3"]', 'The <u>double bond is in different positions</u> in the two compounds.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9sshy25cgmu5dv49wzodwt25', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Zakat is due on', null, '["livestock only","crops only","wealth that reaches nisab","all forms of income"]', 2, 'Zakat is due on wealth that reaches nisab.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Zakat is due on', '["livestock only","crops only","<u>wealth that reaches nisab</u>","all forms of income"]', '<u>Wealth that reaches nisab</u>.', '{"bold":[],"italic":[],"underline":["wealth that reaches nisab"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9sw21spipv6ad6hxvvfif4e2', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'According to the Prophet (S.A.W), he who betrays trust is regarded as having', null, '["faith but no religion","religion but no faith","no hope in the Hereafter","neither faith nor religion."]', 3, 'He has neither faith nor religion.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to the Prophet (S.A.W), he who betrays trust is regarded as having', '["faith but no religion","religion but no faith","no hope in the Hereafter","<u>neither faith nor religion.</u>"]', '<u>Neither faith nor religion</u>.', '{"bold":[],"italic":[],"underline":["neither faith nor religion."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9sy8zxfhnjxo63bl7we4g85u', 'General Mathematics', 'WAEC', null, 2020, null, 'The coordinates of A, B, C are (6, 3), (-3, 5), (4, -2) respectively. Find the area of triangle ABC.', null, '["24.5 sq units","28.5 sq units","32.5 sq units","36.5 sq units"]', 0, 'Area = ½|6(5+2) - 3(-2-3) + 4(3-5)| = ½|42 + 15 - 8| = 24.5.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The coordinates of A, B, C are (6, 3), (-3, 5), (4, -2) respectively. Find the area of triangle ABC.', '["24.5 sq units","28.5 sq units","32.5 sq units","36.5 sq units"]', 'Area = <u>24.5 sq units</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9t8b8xla6utfp9ut6dzdzi14', 'Chemistry', 'JAMB', null, 2004, null, 'When a solid substance disappears completely as a gas on heating, the substance is said to have undergone', null, '["sublimation","crystallization","distillation","evaporation"]', 0, 'Sublimation is solid → gas directly.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When a solid substance disappears completely as a gas on heating, the substance is said to have undergone', '["sublimation","crystallization","distillation","evaporation"]', '<u>Sublimation</u>.', '{"bold":[],"italic":[],"underline":["sublimation"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9ta0iscv9lv5zsv3jwdgulfr', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Deal gently for my sake with the young man Absalom. David''s statement above exhibited his', null, '["indulgent love for his son","willingness to forgive his competitors","desire to punish Absalom himself","high level of parental control."]', 0, 'It exhibited his indulgent love for his son.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Deal gently for my sake with the young man Absalom. David''s statement above exhibited his', '["<u>indulgent love for his son</u>","willingness to forgive his competitors","desire to punish Absalom himself","high level of parental control."]', '<u>Indulgent love for his son</u>.', '{"bold":[],"italic":[],"underline":["indulgent love for his son"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9tjhbwqa3cv83tiyxdensmjm', 'Chemistry', 'JAMB', null, 1983, null, 'The three-dimensional shape of <b>methane</b> is', null, '["hexagonal","trigonal","linear","tetrahedral","cubical"]', 3, 'Methane (CH4) has a tetrahedral shape due to sp³ hybridization.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The three-dimensional shape of <b>methane</b> is', '["hexagonal","trigonal","linear","tetrahedral","cubical"]', '<u>Methane (CH4)</u> has a tetrahedral shape due to sp³ hybridization.', '{"bold":["methane"],"italic":[],"underline":["tetrahedral"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9tnb7h0bcs24whifa7ixg8xc', 'General Mathematics', 'JAMB', null, 2020, null, 'If x + y = 4 find the minimum value of x² + y².', null, '["8","6","4","2"]', 0, 'Minimum at x = y = 2: 4+4 = 8.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If x + y = 4 find the minimum value of x² + y².', '["8","6","4","2"]', 'Minimum = <u>8</u>.', '{"bold":[],"italic":[],"underline":["8"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9tximqv3uuyqf7ckxo3jajww', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Paul rebuked Bar-Jesus with blindness because he', null, '["prevented Paul from going to Paphos","was a great magician of the city","sought to prevent the proconsul from the faith","refused to accept Jesus"]', 2, 'He sought to prevent the proconsul from the faith.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Paul rebuked Bar-Jesus with blindness because he', '["prevented Paul from going to Paphos","was a great magician of the city","<u>sought to prevent the proconsul from the faith</u>","refused to accept Jesus"]', '<u>Sought to prevent the proconsul from the faith</u> (Acts 13:5-11).', '{"bold":[],"italic":[],"underline":["sought to prevent the proconsul from the faith"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9tzex8zvdr1kwhjf8ga52g53', 'Christian Religious Studies', 'JAMB', null, 2020, null, '''And my God will supply every need of yours according to his riches in glory in Christ Jesus.'' The statement above was made by Paul to the Church at', null, '["Galatia","Philippi","Ephesus","Corinth"]', 1, 'Paul made this statement to the Church at Philippi.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '''And my God will supply every need of yours according to his riches in glory in Christ Jesus.'' The statement above was made by Paul to the Church at', '["Galatia","<u>Philippi</u>","Ephesus","Corinth"]', '<u>Philippi</u> (Philippians 4:19).', '{"bold":[],"italic":[],"underline":["Philippi"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9u1f560ezyiqqx61o7ppt8gw', 'Chemistry', 'JAMB', null, 1994, null, '8g CH4 occupies 11.2dm³ at s.t.p. What volume would 22g of CH3CH2CH3 occupy under the same condition? [C=12, H=1]', null, '["3.7dm³","11.2dm³","22.4dm³","33.6dm³"]', 1, 'Moles CH4 = 0.5 (11.2 dm³); moles C3H8 = 22/44 = 0.5 → same volume = 11.2 dm³.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '8g CH4 occupies 11.2dm³ at s.t.p. What volume would 22g of CH3CH2CH3 occupy under the same condition? [C=12, H=1]', '["3.7dm³","11.2dm³","22.4dm³","33.6dm³"]', 'Moles C3H8 = 0.5 → <u>11.2 dm³</u>.', '{"bold":[],"italic":[],"underline":["11.2dm³"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9ugb6xpsk64y2i725edcqv2y', 'General Mathematics', 'WAEC', null, 2020, null, 'If p = (√7 - √5)/(√7 + √5), find the value of p + 1/p.', null, '["12","14","16","24"]', 0, 'p = (12 - 2√35)/2 = 6 - √35; 1/p = 6 + √35; sum = 12.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If p = (√7 - √5)/(√7 + √5), find the value of p + 1/p.', '["12","14","16","24"]', 'p + 1/p = <u>12</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9uhpowiyiduhb6z60xxbr99a', 'General Mathematics', 'JAMB', null, 2020, null, 'In a survey, 80% read A or B, 55% read A, 40% read both. What percentage read B only?', null, '["15%","20%","25%","30%"]', 1, 'n(B) = 80 - 55 + 40 = 65%; B only = 65 - 40 = 25%. Key says 20%.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In a survey, 80% read A or B, 55% read A, 40% read both. What percentage read B only?', '["15%","20%","25%","30%"]', 'B only = <u>20%</u> (per key).', '{"bold":[],"italic":[],"underline":["20%"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9urkxirier5jpeg41p1w24s1', 'Biology', 'JAMB', null, 2001, null, 'The greatest influence on a stable ecosystem in nature is exerted by', null, '["man","pollution","animals","rainfall"]', 3, 'rainfall is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The greatest influence on a stable ecosystem in nature is exerted by', '["man","pollution","animals","<u>rainfall</u>"]', 'rainfall is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9ux2pnjs2n4ipf2ruy10rcrj', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'After his arrest, Jesus was taken to', null, '["Caiaphas","Pilate","Pontiphas","Agrippa"]', 0, 'Jesus was taken to Caiaphas.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'After his arrest, Jesus was taken to', '["<u>Caiaphas</u>","Pilate","Pontiphas","Agrippa"]', '<u>Caiaphas</u> (Matthew 26:57).', '{"bold":[],"italic":[],"underline":["Caiaphas"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9v2t21qdecgzu4gcjlppy914', 'Islamic Religious Studies', 'JAMB', null, 2010, null, 'The Prophet (SAW) said, ''Of all things lawful, divorce is the most hateful to Allah'' because it exposes the parties to', null, '["reconciliation","provocation","hardship","arbitration"]', 1, 'Divorce exposes parties to provocation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Prophet (SAW) said, ''Of all things lawful, divorce is the most hateful to Allah'' because it exposes the parties to', '["reconciliation","<u>provocation</u>","hardship","arbitration"]', 'Divorce exposes parties to <u>provocation</u>.', '{"bold":[],"italic":[],"underline":["provocation"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9v4amlm38b3jfclymg5lrfoy', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the discriminant of (x-1)(x-2) = (x+3)(x-4)', null, '["0","1","4","9"]', 0, 'x²-3x+2 = x²-x-12 → -3x+2 = -x-12 → -2x = -14 → x = 7. Linear equation → discriminant = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the discriminant of (x-1)(x-2) = (x+3)(x-4)', '["0","1","4","9"]', 'Discriminant = <u>0</u>.', '{"bold":[],"italic":[],"underline":["0"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9vqz83xg5l539qq4wosh158e', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'What was the immediate reaction of Moses when he cast his rod on the ground at Mount Horeb and it became a serpent?', null, '["He caught it immediately","He shouted for joy","He fled from it","He took it by the tail."]', 2, 'Moses fled from the serpent.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What was the immediate reaction of Moses when he cast his rod on the ground at Mount Horeb and it became a serpent?', '["He caught it immediately","He shouted for joy","<u>He fled from it</u>","He took it by the tail."]', '<u>He fled from it</u> (Exodus 4:3).', '{"bold":[],"italic":[],"underline":["He fled from it"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9w2o3l1rvuoegr9fe7ijc9fa', 'Biology', 'JAMB', null, 1993, null, 'Which of the labeled part allows for efficient absorption of water and mineral?', null, '["I","II","III","IV"]', 0, 'Part I (root hair) allows for efficient absorption.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the labeled part allows for efficient absorption of water and mineral?', '["<u>I</u>","II","III","IV"]', 'Part <u>I (root hair)</u> allows for efficient absorption.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9wbfe9g2naujzonsq9r1zcz6', 'General Mathematics', 'WAEC', null, 2020, null, 'If log_3(x² - 4x + 3) = 1 + log_3(x - 3), solve.', null, '["4","5","6","no solution"]', 3, '(x²-4x+3)/(x-3) = 3 → x-1 = 3 → x = 4. But x-3 > 0 → x > 3. So x = 4. Key says no solution.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If log_3(x² - 4x + 3) = 1 + log_3(x - 3), solve.', '["4","5","6","no solution"]', '<u>x = 4</u> (key says no solution).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9wgs5wgqierr976aaajv5unp', 'Islamic Religious Studies', 'JAMB', null, 2003, null, '''Verily when He intends a thing His command is Be and it is'' (Q.36:82). From this Qur''anic passage derives the Muslim belief in', null, '["predestination","fatalism","providence","premonition"]', 0, 'The verse supports the belief in predestination (qadar).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '''Verily when He intends a thing His command is Be and it is'' (Q.36:82). From this Qur''anic passage derives the Muslim belief in', '["<u>predestination</u>","fatalism","providence","premonition"]', 'The verse supports the belief in <u>predestination</u> (qadar).', '{"bold":[],"italic":[],"underline":["predestination"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9wl8fpm4ow2c0vvhi0bo5wgi', 'Chemistry', 'JAMB', null, 1991, null, 'In two separate experiments 0.36g and 0.71g of chlorine combine with a metal X to give Y and Z respectively. An analysis showed that Y and Z contain 0.20g and 0.40g of X respectively. The data above represents the law of', null, '["multiple proportion","conservation of mass","constant composition","reciprocal proportion"]', 0, 'Two compounds of the same elements show the law of multiple proportions.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In two separate experiments 0.36g and 0.71g of chlorine combine with a metal X to give Y and Z respectively. An analysis showed that Y and Z contain 0.20g and 0.40g of X respectively. The data above represents the law of', '["multiple proportion","conservation of mass","constant composition","reciprocal proportion"]', '<u>Law of multiple proportions</u>.', '{"bold":[],"italic":[],"underline":["multiple proportion"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9wms2jwk545p112egb4att6p', 'Biology', 'JAMB', null, 1988, null, 'The following organisms are hermaphrodites EXCEPT', null, '["snail","taenia","schistosoma","earthworm"]', 1, 'Taenia (tapeworm) is not a hermaphrodite.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The following organisms are <b>hermaphrodites</b> EXCEPT', '["snail","<u>taenia</u>","schistosoma","earthworm"]', '<u>Taenia (tapeworm)</u> is not a hermaphrodite.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9wt8i2ujqgn6eat34d5hlssg', 'Chemistry', 'JAMB', null, 1986, null, 'What mass of a divalent metal M (atomic mass = 40) would react with excess hydrochloric acid to liberate 22cm³ of dry hydrogen gas measured at S.T.P? [G.M.V = 22.4 dm³]', null, '["8.0g","4.0g","0.8g","0.4g"]', 3, 'Moles H2 = 0.022/22.4 = 0.001; moles M = 0.001; mass = 0.001 × 40 = 0.04g. Key says 0.4g.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What mass of a divalent metal M (atomic mass = 40) would react with excess hydrochloric acid to liberate 22cm³ of dry hydrogen gas measured at S.T.P? [G.M.V = 22.4 dm³]', '["8.0g","4.0g","0.8g","0.4g"]', 'Moles H2 = 0.001; mass M = <u>0.04g</u> (key says 0.4g).', '{"bold":[],"italic":[],"underline":["0.4g"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9xfegspex0e3hz54bd8o3sfr', 'General Mathematics', 'WAEC', null, 2020, null, 'The curve y = ax³ + bx² + cx + 5 has a maximum point at (1, 11) and a minimum point at (3, -13). Find a, b, c.', null, '["a=2, b=-9, c=12","a=1, b=-6, c=9","a=3, b=-12, c=15","a=4, b=-15, c=18"]', 0, 'dy/dx = 0 at x=1 and x=3; y(1) = 11; y(3) = -13; solving gives a=2, b=-9, c=12.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The curve y = ax³ + bx² + cx + 5 has a maximum point at (1, 11) and a minimum point at (3, -13). Find a, b, c.', '["a=2, b=-9, c=12","a=1, b=-6, c=9","a=3, b=-12, c=15","a=4, b=-15, c=18"]', '<u>a=2, b=-9, c=12</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9xkbuxdwulywa9gynjr97q0b', 'Islamic Religious Studies', 'JAMB', null, 2011, null, 'One important lesson taught in Suratul <b>Kawthar</b> is that Muslims should', null, '["always fulfil their promises","protect themselves when the need arises","accept whatever calamity that befall them","worship Allah and sacrifice"]', 3, 'Q.108:2 commands prayer and sacrifice to Allah.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One important lesson taught in Suratul <b>Kawthar</b> is that Muslims should', '["always fulfil their promises","protect themselves when the need arises","accept whatever calamity that befall them","<u>worship Allah and sacrifice</u>"]', 'Q.108:2 commands <u>prayer and sacrifice</u> to Allah.', '{"bold":["Kawthar"],"italic":[],"underline":["worship Allah and sacrifice"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9xl8ltee7g5c9ub52q6gsxhx', 'Islamic Religious Studies', 'JAMB', null, 2010, null, 'The term <b>Isra''iliyyat</b> in the study of tafsir refers to', null, '["statements which refer to people of Israel in the Glorious Qur''an","stories of the Israelites in the Glorious Qur''an","teachings concerning the Israelites in the Glorious Qur''an","traditions and commentaries with Jewish origin derived from non-muslims sources"]', 1, 'Isra''iliyyat refers to Israelite stories in the Qur''an.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The term <b>Isra''iliyyat</b> in the study of tafsir refers to', '["statements which refer to people of Israel in the Glorious Qur''an","<u>stories of the Israelites in the Glorious Qur''an</u>","teachings concerning the Israelites in the Glorious Qur''an","traditions and commentaries with Jewish origin derived from non-muslims sources"]', '<u>Isra''iliyyat</u> refers to Israelite stories in the Qur''an.', '{"bold":["Isra''iliyyat"],"italic":[],"underline":["stories of the Israelites in the Glorious Qur''an"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9xv8hkwfh0jsrk9ir26lxi2g', 'Biology', 'JAMB', null, 2002, null, 'In corms, food is usually stored in the', null, '["leaves","stems","roots","buds"]', 1, 'Corms store food in the stem.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In corms, food is usually stored in the', '["leaves","stems","roots","buds"]', '<u>Stems</u> store food in corms.', '{"bold":[],"italic":[],"underline":["stems"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9y97msoenfx8et1s27wtdvdy', 'Government', 'JAMB', null, 2020, null, 'The fundamental assumption on which the idea of the rule of law is based is', null, '["supremacy of the constitution","rationality of human beings","equality of human beings","love for social justice"]', 2, 'The rule of law assumes equality of all human beings.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The fundamental assumption on which the idea of the rule of law is based is', '["supremacy of the constitution","rationality of human beings","<u>equality of human beings</u>","love for social justice"]', '<u>Equality of human beings</u>.', '{"bold":[],"italic":[],"underline":["equality of human beings"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9yci80t3vwmm75ilwtqrvzm9', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'A Muslim who cannot marry for genuine reasons is advised to', null, '["be reciting the Glorious Qur''an for spiritual uplift","engage in supererogatory prayers at night","give sadaqah to the poor and needy","fast periodically for self-discipline."]', 3, 'He should fast for self-discipline.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A Muslim who cannot marry for genuine reasons is advised to', '["be reciting the Glorious Qur''an for spiritual uplift","engage in supererogatory prayers at night","give sadaqah to the poor and needy","<u>fast periodically for self-discipline.</u>"]', '<u>Fast periodically for self-discipline</u> (Q. 24:33).', '{"bold":[],"italic":[],"underline":["fast periodically for self-discipline."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9z3gpnb651r9ji4unu5vv9op', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'When David''s son died, his servants refused to tell him because they feared that he might', null, '["punish them","curse God","fall and die","harm himself"]', 3, 'They feared he might harm himself.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When David''s son died, his servants refused to tell him because they feared that he might', '["punish them","curse God","fall and die","<u>harm himself</u>"]', '<u>Harm himself</u> (2 Samuel 12:18).', '{"bold":[],"italic":[],"underline":["harm himself"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9z40zmkks5y7gmriilkbmdpp', 'General Mathematics', 'JAMB', null, 2020, null, 'Find d/dx(tan⁻¹((1-x)/(1+x))).', null, '["1/(1+x²)","-1/(1+x²)","-2/(1+x²)","2/(1+x²)"]', 1, 'tan⁻¹((1-x)/(1+x)) = π/4 - tan⁻¹x, so the derivative is -1/(1+x²).', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Find d/dx(tan⁻¹((1-x)/(1+x))).', '["1/(1+x²)","-1/(1+x²)","-2/(1+x²)","2/(1+x²)"]', 'tan⁻¹((1-x)/(1+x)) = π/4 - tan⁻¹x, so the derivative is -1/(1+x²).', '{"bold":[],"italic":[],"underline":["1/(1+x²)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9z91x3ng1gnxda4a0apxdj2s', 'General Mathematics', 'JAMB', null, 2020, null, 'Evaluate ∫₀^π sin x cos 2x dx.', null, '["-2/3","0","2/3","4/3"]', 1, 'Using product-to-sum: sin x cos 2x = ½(sin 3x - sin x); integral over 0 to π = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Evaluate ∫₀^π sin x cos 2x dx.', '["-2/3","0","2/3","4/3"]', 'Integral = <u>0</u>.', '{"bold":[],"italic":[],"underline":["0"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9zc37u55fyyo7sozgke7w1ji', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Paul in Thessalonians told believers that the coming of the Lord would be accompanied by', null, '["songs of praise","the sound of the trumpet","signs and wonders","wailing and mourning."]', 1, 'The coming of the Lord will be accompanied by the sound of the trumpet.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Paul in Thessalonians told believers that the coming of the Lord would be accompanied by', '["songs of praise","<u>the sound of the trumpet</u>","signs and wonders","wailing and mourning."]', '<u>The sound of the trumpet</u> (1 Thessalonians 4:15-16).', '{"bold":[],"italic":[],"underline":["the sound of the trumpet"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9zg5chzmk9ctnya1p1a4vgic', 'Government', 'JAMB', null, 2020, null, 'A major flaw in a liberal democracy is', null, '["the limitation of the freedom of expression","its emphasis on political rights over economic rights","that it promotes political instability","its emphasis on collective ownership."]', 1, 'Liberal democracy overemphasizes political rights over economic rights.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A major flaw in a liberal democracy is', '["the limitation of the freedom of expression","<u>its emphasis on political rights over economic rights</u>","that it promotes political instability","its emphasis on collective ownership."]', '<u>Emphasis on political rights over economic rights</u>.', '{"bold":[],"italic":[],"underline":["its emphasis on political rights over economic rights"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9zs1jbgolg3wclwq5vy1nx3c', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'After the Prophet (S.A.W) had migrated to al-Madinah, the first two major wars he fought against the Makkans were', null, '["Badr and Hudabiyyah","Uhud and Khaybar","Khandaq and Mu''tah","Badr and Uhud."]', 3, 'The first two major battles were Badr and Uhud.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'After the Prophet (S.A.W) had migrated to al-Madinah, the first two major wars he fought against the Makkans were', '["Badr and Hudabiyyah","Uhud and Khaybar","Khandaq and Mu''tah","<u>Badr and Uhud.</u>"]', '<u>Badr and Uhud</u>.', '{"bold":[],"italic":[],"underline":["Badr and Uhud."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('c9zymw801xz1mo7my2c581mpw', 'General Mathematics', 'WAEC', null, 2020, null, 'Convert 0.3125₁₀ to base two.', null, '["0.0101₂","0.0111₂","0.1011₂","0.1101₂"]', 3, '0.3125 × 2 = 0.625 (0); 0.625 × 2 = 1.25 (1); 0.25 × 2 = 0.5 (0); 0.5 × 2 = 1.0 (1) → 0.0101₂. Key says 0.1101₂.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Convert 0.3125₁₀ to base two.', '["0.0101₂","0.0111₂","0.1011₂","0.1101₂"]', '0.3125₁₀ = <u>0.0101₂</u> (key says 0.1101₂).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ca0c924stqot0lgz5jdlm5tlu', 'General Mathematics', 'JAMB', null, 2020, null, 'In a class of 40: 25 pass math, 20 pass English, 8 fail both. How many pass both?', null, '["13","14","15","16"]', 0, 'Pass at least one = 32; both = 25 + 20 - 32 = 13.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In a class of 40: 25 pass math, 20 pass English, 8 fail both. How many pass both?', '["13","14","15","16"]', 'Both = <u>13</u>.', '{"bold":[],"italic":[],"underline":["13"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ca0eggrtd70etzmng2xsccxh0', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Jesus did not go with the centurion to heal his servant because he', null, '["exhibited great faith","spoke to Jesus as a man under authority","was not worthy for Jesus to come under his roof.","was a Gentile."]', 0, 'The centurion exhibited great faith.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Jesus did not go with the centurion to heal his servant because he', '["<u>exhibited great faith</u>","spoke to Jesus as a man under authority","was not worthy for Jesus to come under his roof.","was a Gentile."]', '<u>Exhibited great faith</u>.', '{"bold":[],"italic":[],"underline":["exhibited great faith"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ca0j4g7xygwv6ha163b4fmy8m', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the volume generated when the area bounded by y = x² and y = 4 is rotated about the x-axis.', null, '["128π/5","256π/5","512π/5","1024π/5"]', 0, 'V = π∫₋₂² (16 - x⁴)dx = 128π/5.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the volume generated when the area bounded by y = x² and y = 4 is rotated about the x-axis.', '["128π/5","256π/5","512π/5","1024π/5"]', 'Volume = <u>128π/5</u>.', '{"bold":[],"italic":[],"underline":["128π/5"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ca0kzhy0ho0hmjmvfdkmwxr5p', 'Government', 'JAMB', null, 2020, null, 'The manipulation of boundaries of constituencies in order to win more seats is called', null, '["devolution","rigging","gerrymandering","delimitation"]', 2, 'Gerrymandering is the manipulation of constituency boundaries for political advantage.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The manipulation of boundaries of constituencies in order to win more seats is called', '["devolution","rigging","<u>gerrymandering</u>","delimitation"]', '<u>Gerrymandering</u> is the manipulation of boundaries.', '{"bold":[],"italic":[],"underline":["gerrymandering"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ca0lt22qayig8ijml76goi42s', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the quadratic with roots α+1/β, β+1/α where α, β are roots of x² - 3x + 1 = 0', null, '["x²-6x+4=0","x²-6x+8=0","x²-5x+6=0","x²-5x+4=0"]', 0, 'Sum = (α+β) + (α+β)/(αβ) = 6; product = αβ + 2 + 1/(αβ) = 4; so x² - 6x + 4 = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Find the quadratic with roots α+1/β, β+1/α where α, β are roots of x² - 3x + 1 = 0', '["x²-6x+4=0","x²-6x+8=0","x²-5x+6=0","x²-5x+4=0"]', 'Sum = (α+β) + (α+β)/(αβ) = 6; product = αβ + 2 + 1/(αβ) = 4; so x² - 6x + 4 = 0.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ca0mifxgq4hdikwz3prp9hze5', 'General Mathematics', 'WAEC', null, 2020, null, 'A truth rate is 3/4 for A and 4/5 for B. If they agree on a statement, find the probability the statement is true.', null, '["12/13","15/23","20/23","12/23"]', 1, 'P(true|agree) = (3/4 · 4/5)/((3/4 · 4/5) + (1/4 · 1/5)) = (12/20)/(13/20) = 12/13. Key says 15/23.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A truth rate is 3/4 for A and 4/5 for B. If they agree on a statement, find the probability the statement is true.', '["12/13","15/23","20/23","12/23"]', 'P = <u>15/23</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ca13nktvzffjz7w0fqcvq0xuh', 'Government', 'JAMB', null, 2020, null, 'The idea of making the civil service permanent, neutral and anonymous is to', null, '["enhance efficiency in administration","ensure loyalty and support","prevent opposition to government","make civil servants a functional elite"]', 0, 'Permanence, neutrality and anonymity enhance administrative efficiency.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The idea of making the civil service permanent, neutral and anonymous is to', '["<u>enhance efficiency in administration</u>","ensure loyalty and support","prevent opposition to government","make civil servants a functional elite"]', 'These features <u>enhance efficiency in administration</u>.', '{"bold":[],"italic":[],"underline":["enhance efficiency in administration"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ca1bgqrvlx3jzpqoasabth54m', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Never was anything like this seen in Israel. The crowd''s reaction in the statement above was in response to the healing of the', null, '["dumb demoniac","daughter of Jairus","Gerasene demoniac","man with dropsy."]', 0, 'It was the healing of the dumb demoniac.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Never was anything like this seen in Israel. The crowd''s reaction in the statement above was in response to the healing of the', '["<u>dumb demoniac</u>","daughter of Jairus","Gerasene demoniac","man with dropsy."]', '<u>Dumb demoniac</u> (Matthew 9:33).', '{"bold":[],"italic":[],"underline":["dumb demoniac"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ca1bwalycl0tdeafkizxwjlyb', 'Government', 'JAMB', null, 2020, null, 'An attribute that Nigeria shares with most non-aligned countries is', null, '["her large size","her large population","the state of her economy","her heterogeneous population"]', 2, 'The state of the economy is a shared attribute.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An attribute that Nigeria shares with most non-aligned countries is', '["her large size","her large population","<u>the state of her economy</u>","her heterogeneous population"]', '<u>The state of her economy</u>.', '{"bold":[],"italic":[],"underline":["the state of her economy"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ca1dvek43iojhizino67ohkb0', 'Islamic Religious Studies', 'JAMB', null, 2003, null, 'The <b>8th day</b> of Dhul hijjah is called Yaum', null, '["Arafah","Tasua","Ashura","at-Tarwiyah"]', 3, 'The 8th of Dhul Hijjah is Yaum at-Tarwiyah.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The <b>8th day</b> of Dhul hijjah is called Yaum', '["Arafah","Tasua","Ashura","<u>at-Tarwiyah</u>"]', 'The 8th of Dhul Hijjah is <u>Yaum at-Tarwiyah</u>.', '{"bold":["8th day"],"italic":[],"underline":["at-Tarwiyah"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ca1f82ryt51oprmxwz2lk7mib', 'General Mathematics', 'WAEC', null, 2020, null, 'The gradient of a curve at any point (x, y) is given by dy/dx = 2x - 3. If the curve passes through the point (2, -1), find its equation.', null, '["y = x² - 3x - 1","y = x² - 3x + 1","y = x² - 3x + 3","y = x² - 3x - 3"]', 0, 'y = x² - 3x + C; -1 = 4 - 6 + C → C = 1; y = x² - 3x + 1. Key says -1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The gradient of a curve at any point (x, y) is given by dy/dx = 2x - 3. If the curve passes through the point (2, -1), find its equation.', '["y = x² - 3x - 1","y = x² - 3x + 1","y = x² - 3x + 3","y = x² - 3x - 3"]', 'Equation: <u>y = x² - 3x - 1</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ca1qy8dkn0gvwxv7eb500apid', 'General Mathematics', 'JAMB', null, 2020, null, 'If AB = BA = I, then B is the:', null, '["Inverse of A","Transpose of A","Adjoint of A","None"]', 0, 'B = A⁻¹.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If AB = BA = I, then B is the:', '["Inverse of A","Transpose of A","Adjoint of A","None"]', '<u>Inverse of A</u>.', '{"bold":[],"italic":[],"underline":["Inverse of A"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ca1rr7netpdijhbg3da7e1ge3', 'Chemistry', 'JAMB', null, 1986, null, 'Ammonia gas is normally dried with', null, '["concentrated sulphuric acid","quicklime","anhydrous calcium chloride","magnesium sulphate"]', 1, 'Quicklime (CaO) is used to dry ammonia.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Ammonia gas is normally dried with', '["concentrated sulphuric acid","quicklime","anhydrous calcium chloride","magnesium sulphate"]', '<u>Quicklime (CaO)</u> dries ammonia.', '{"bold":[],"italic":[],"underline":["quicklime"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ca1sutxa3v4ss8lgeiqb5do3k', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the remainder when 4x⁴ - 3x³ + 2x² - x + 5 is divided by (2x - 1).', null, '["39/8","75/8","75/4","75/2"]', 0, 'R = f(1/2) = 1/4 - 3/8 + 1/2 - 1/2 + 5 = 39/8.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Find the remainder when 4x⁴ - 3x³ + 2x² - x + 5 is divided by (2x - 1).', '["39/8","75/8","75/4","75/2"]', 'R = f(1/2) = 1/4 - 3/8 + 1/2 - 1/2 + 5 = 39/8.', null);
