insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ca208wb9u11fkgwgmidhse9jw', 'Chemistry', 'JAMB', null, 1993, null, 'A balanced chemical equation obeys the law of', null, '["Conservation of mass","Definite proportions","Multiple proportions","Conservation of energy"]', 0, 'Balanced equations obey conservation of mass.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A balanced chemical equation obeys the law of', '["Conservation of mass","Definite proportions","Multiple proportions","Conservation of energy"]', '<u>Conservation of mass</u>.', '{"bold":[],"italic":[],"underline":["Conservation of mass"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ca24d1a3-6584-4f0d-bbe6-19a0caf293b1', 'Government', 'JAMB', null, 2026, null, 'The Armed Forces Ruling Council was introduced by', null, '["Maj. Gen. Ibrahim Babangida","Gen. Sanni Abacha","Lt. Col. Yakubu Gowon","Brig. Muritala Muhammed"]', 0, 'The Armed Forces Ruling Council (AFRC) was introduced by Major General Ibrahim Babangida. Babangida came to power in 1985 and established the AFRC as the highest decision-making body of his military government. It replaced the Supreme Military Council (SMC) that had existed under previous military regimes. The AFRC governed Nigeria until 1993 when Babangida stepped aside.', true, '2026-09-10 10:45:05.449', '2026-09-10 10:45:05.449', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ca258703-7352-4e66-a8a6-dcd48a054b86', 'Hausa', 'JAMB', null, 2011, null, 'Makasudin ''Wakar ''Yan Baka'' ta Sa''adu Zungur shi ne', null, '["hana hassada","hana zunde","dakile almubazzaranci","dakile jita-jita."]', 3, 'Makasudin wakar shi ne dakile jita-jita.', true, '2026-10-13 10:37:22.694', '2026-10-13 10:37:22.694', null, null, null, 'Makasudin ''Wakar ''Yan Baka'' ta Sa''adu Zungur shi ne', '["hana hassada","hana zunde","dakile almubazzaranci","dakile jita-jita."]', 'Makasudin wakar shi ne dakile jita-jita.', '{"bold":["dakile jita-jita"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ca28aac3-256b-4bb9-bdcd-cafd820b679a', 'Biology', 'JAMB', null, 0, null, 'answer the questions above ', 'https://res.cloudinary.com/kwi1uv0g/image/upload/v1791839847/questions/apto9c5cwp6h8way2snl.jpg', '["a","b","c","d"]', 0, 'Part I points to the Golgi apparatus or lysosomes/ribosomes cluster.   Part II points to the mitochondria.   Part III points to the cytoplasm.   Part IV points to the endoplasmic reticulum, which appears as a network of folded membranes extending near the nucleus. ', true, '2026-10-12 21:17:57.858', '2026-10-12 21:17:57.858', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ca2bi0saq9tnigz12gp4ogppt', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The five most important prophets in Islam were', null, '["Yahya, Zakariyya, Dawud, Sulayman, Adam","Muhammad, Nuh, Ibrahim, Musa, Isa","Muhammad, Nuh, Dhul-kifl, Idris, Harun","Ibrahim, Musa, Isa, Adam, Ayyub."]', 1, 'The five most important prophets are Muhammad, Nuh, Ibrahim, Musa, and Isa.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The five most important prophets in Islam were', '["Yahya, Zakariyya, Dawud, Sulayman, Adam","<u>Muhammad, Nuh, Ibrahim, Musa, Isa</u>","Muhammad, Nuh, Dhul-kifl, Idris, Harun","Ibrahim, Musa, Isa, Adam, Ayyub."]', '<u>Muhammad, Nuh, Ibrahim, Musa, Isa</u>.', '{"bold":[],"italic":[],"underline":["Muhammad, Nuh, Ibrahim, Musa, Isa"],"fillBlanks":[]}');
