insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ca2jnld1mkhvmfhptzc3in4ig', 'Biology', 'JAMB', null, 1997, null, 'During binary fission in lower organisms, the nucleus is known to undergo', null, '["mitosis","meiosis","fragmentation","mutation."]', 1, 'meiosis is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'During binary fission in lower organisms, the nucleus is known to undergo', '["mitosis","<u>meiosis</u>","fragmentation","mutation."]', 'meiosis is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ca2lsxhr04nqwbbfaueffjplv', 'Chemistry', 'JAMB', null, 1987, null, 'The number of molecules of carbon(IV) oxide produced when 10.0g CaCO3 is treated with 0.2dm³ of 1M HCl in the equation CaCO3 + 2HCl → CaCl2 + H2O + CO2 is [Ca=40, O=16, C=12, NA=6.02×10²³, H=1, Cl=35.5]', null, '["1.00×10²³","6.02×10²³","6.02×10²²","6.02×10²⁴"]', 0, 'Moles CaCO3 = 0.1; HCl = 0.2 (limiting); CO2 = 0.1 mol; molecules = 6.02×10²². Key says 1.00×10²³.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The number of molecules of carbon(IV) oxide produced when 10.0g CaCO3 is treated with 0.2dm³ of 1M HCl in the equation CaCO3 + 2HCl → CaCl2 + H2O + CO2 is [Ca=40, O=16, C=12, NA=6.02×10²³, H=1, Cl=35.5]', '["1.00×10²³","6.02×10²³","6.02×10²²","6.02×10²⁴"]', 'Moles CO2 = 0.1; molecules = <u>6.02×10²²</u>.', '{"bold":[],"italic":[],"underline":["1.00×10²³"],"fillBlanks":[]}');
