insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ca4bnfvs574npvn0p5qr1jj6x', 'Chemistry', 'JAMB', null, 1996, null, 'Which of the following equilibria is <b>unaffected by a pressure change</b>?', null, '["2NaCl ⇌ 2Na + Cl2","H2 + I2 ⇌ 2HI","2O3 ⇌ 3O2","2NO2 ⇌ N2O4"]', 1, 'Equal gas moles on both sides.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following equilibria is <b>unaffected by a pressure change</b>?', '["2NaCl ⇌ 2Na + Cl2","H2 + I2 ⇌ 2HI","2O3 ⇌ 3O2","2NO2 ⇌ N2O4"]', '<u>H2 + I2 ⇌ 2HI</u>.', '{"bold":["unaffected by a pressure change"],"italic":[],"underline":["H2 + I2 ⇌ 2HI"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ca4d66c5-ff62-488b-96e5-83ebbd3d5fc7', 'Physics', 'JAMB', null, 2026, null, 'Which property is unique to Longitudinal waves?', null, '["all of the above","I only","All except II","I & iv only","none of above"]', 2, 'Polarization is unique to transverse waves, not longitudinal waves. Longitudinal waves can undergo reflection, refraction, and diffraction, but not polarization. So the answer is ''All except II'' (all except polarization).', true, '2026-09-10 10:56:43.144', '2026-09-10 10:56:43.144', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ca4i6lsya8p5wa3c1erwu6wjz', 'Chemistry', 'JAMB', null, 1993, null, 'Catalytic hydrogenation of <b>benzene</b> produces', null, '["an aromatic hydrocarbon","margarine","cyclohexane","D.D.T"]', 2, 'Benzene + 3H2 → cyclohexane.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Catalytic hydrogenation of <b>benzene</b> produces', '["an aromatic hydrocarbon","margarine","cyclohexane","D.D.T"]', '<u>Cyclohexane</u> is produced.', '{"bold":["benzene"],"italic":[],"underline":["cyclohexane"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ca4kubswl31i80c0e6qryoyra', 'General Mathematics', 'WAEC', null, 2020, null, 'If xʸ = yˣ, find dy/dx.', null, '["y(y - x ln y)/(x(y - ln y))","y(x ln y - y)/(x(y ln x - x))","y(x - y ln x)/(x(y - x ln y))","y(x ln y + y)/(x(y ln x + x))"]', 0, 'Implicit differentiation yields y(y - x ln y)/(x(y - ln y)).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If xʸ = yˣ, find dy/dx.', '["y(y - x ln y)/(x(y - ln y))","y(x ln y - y)/(x(y ln x - x))","y(x - y ln x)/(x(y - x ln y))","y(x ln y + y)/(x(y ln x + x))"]', 'dy/dx = <u>y(y - x ln y)/(x(y - ln y))</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ca4mm8wdan1y539dulo6bhc84', 'General Mathematics', 'JAMB', null, 2020, null, 'If ∫(eˣ - 1)/(eˣ + 1) dx = f(x) + C, find f(x).', null, '["ln(eˣ + 1) - x","ln(eˣ - 1) + x","ln(eˣ + 1) + x","ln(eˣ - 1) - x"]', 0, 'Let u = eˣ + 1; integral = ln(eˣ+1) - x + C.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If ∫(eˣ - 1)/(eˣ + 1) dx = f(x) + C, find f(x).', '["ln(eˣ + 1) - x","ln(eˣ - 1) + x","ln(eˣ + 1) + x","ln(eˣ - 1) - x"]', 'f(x) = <u>ln(eˣ + 1) - x</u>.', '{"bold":[],"italic":[],"underline":["ln(eˣ + 1) - x"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ca4psskh2tvricjofluw5jpf9', 'General Mathematics', 'WAEC', null, 2020, null, 'A bag contains 5R, 4G, 3B balls. Two balls are drawn without replacement. Find the probability both are the same color.', null, '["19/66","20/66","21/66","22/66"]', 0, 'P = (5C2 + 4C2 + 3C2)/12C2 = (10+6+3)/66 = 19/66.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A bag contains 5R, 4G, 3B balls. Two balls are drawn without replacement. Find the probability both are the same color.', '["19/66","20/66","21/66","22/66"]', 'P = <u>19/66</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ca4py0rbaqcwbomuqctyo7din', 'General Mathematics', 'JAMB', null, 2020, null, 'A = [[1, 2], [3, 4]], find A² - 5A - 2I.', null, '["zero matrix","identity","null","singular"]', 0, 'By Cayley-Hamilton, A² - 5A - 2I = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A = [[1, 2], [3, 4]], find A² - 5A - 2I.', '["zero matrix","identity","null","singular"]', '<u>Zero matrix</u>.', '{"bold":[],"italic":[],"underline":["zero matrix"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ca4qrful27uc9v4vl4a7gfp3j', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve √(x+3) + √(x-2) = 5', null, '["6","7","8","9"]', 0, 'x=6: √9+√4 = 3+2 = 5.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve √(x+3) + √(x-2) = 5', '["6","7","8","9"]', '<u>x = 6</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ca4xwwyrgxh0flwu2pkg0qhb0', 'General Mathematics', 'JAMB', null, 2020, null, 'For what k is x² + kx + 9 = 0 a perfect square?', null, '["±6","±3","±9","±12"]', 0, 'k² = 36 → k = ±6.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'For what k is x² + kx + 9 = 0 a perfect square?', '["±6","±3","±9","±12"]', '<u>k = ±6</u>.', '{"bold":[],"italic":[],"underline":["±6"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ca546d8b-396b-4edd-bc13-87928e499d12', 'Government', 'JAMB', null, 2026, null, 'Which of the following was not a function of FEDECO during the Second Republic?', null, '["swearing in of elected candidates","organizing, conducting and supervising all elections","arranging for the registration of persons qualified to vote","providing guidelines, rules and regulations for political parties"]', 0, 'Swearing in elected candidates was not a function of FEDECO.', true, '2026-09-12 11:24:42.547', '2026-09-12 11:24:42.547', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ca5942af-e642-4448-8dab-e30e069ccc32', 'Biology', 'JAMB', null, 2005, null, 'The function of the fluid-filled pericardium is to', null, '["reduce the friction caused by the pumping movements of the heart","supply the heart with oxygen and nutrients","prevent disease organisms from attacking the heart","reduce the intensity of the pumping action of the heart"]', 0, 'Pericardial fluid lubricates the heart, reducing friction as it beats against surrounding tissues.', true, '2026-10-12 20:05:12.066', '2026-10-12 20:05:12.066', null, null, null, 'The function of the fluid-filled pericardium is to', '["reduce the friction caused by the pumping movements of the heart","supply the heart with oxygen and nutrients","prevent disease organisms from attacking the heart","reduce the intensity of the pumping action of the heart"]', 'Pericardial fluid lubricates the heart, reducing friction as it beats against surrounding tissues.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ca5r41h9vlasi7npx80ors9a0', 'Chemistry', 'JAMB', null, 1996, null, 'Which of the following equivalent solutions, Na2CO3, Na2SO4, FeCl3, NH4Cl and CH3COONa, have <b>pH greater than 7</b>?', null, '["FeCl3 and NH4Cl","Na2CO3, CH3COONa and Na2SO4","Na2CO3 and CH3COONa","FeCl3, CH3COONa and NH4Cl"]', 2, 'Na2CO3 and CH3COONa are basic salts.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following equivalent solutions, Na2CO3, Na2SO4, FeCl3, NH4Cl and CH3COONa, have <b>pH greater than 7</b>?', '["FeCl3 and NH4Cl","Na2CO3, CH3COONa and Na2SO4","Na2CO3 and CH3COONa","FeCl3, CH3COONa and NH4Cl"]', '<u>Na2CO3 and CH3COONa</u>.', '{"bold":["pH greater than 7"],"italic":[],"underline":["Na2CO3 and CH3COONa"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ca5uhz4l0lpkkr8qbvkgzuhws', 'General Mathematics', 'JAMB', null, 2020, null, 'The points (1, 1), (2, 3), and (4, 7) lie on a:', null, '["Parabola","Straight line","Circle","Hyperbola"]', 1, 'Slopes equal (2), so collinear.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The points (1, 1), (2, 3), and (4, 7) lie on a:', '["Parabola","Straight line","Circle","Hyperbola"]', '<u>Straight line</u>.', '{"bold":[],"italic":[],"underline":["Straight line"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ca61d8a7-8221-4843-a4e2-22d697097ca5', 'Physics', 'JAMB', null, 1999, null, 'An astronomical telescope is said to be in normal adjustment when the', null, '["Eye is accommodated","Focal length of objective lens is longer than that of eye piece","Final image is at the near point of the eye","Final image is at infinity."]', 3, 'In normal adjustment the lenses are separated by fo + fe, so the final image is at infinity and the eye is relaxed.', true, '2026-10-12 19:15:48.037', '2026-10-12 19:15:48.037', null, null, null, 'An astronomical telescope is said to be in normal adjustment when the', '["Eye is accommodated","Focal length of objective lens is longer than that of eye piece","Final image is at the near point of the eye","Final image is at infinity."]', 'In normal adjustment the lenses are separated by f<sub>o</sub> + f<sub>e</sub>, so the final image is at infinity and the eye is relaxed.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ca650e01-9dce-4302-985e-1094edc31862', 'English Language', 'JAMB', null, 2024, null, '28', null, '["releases","withholds","regulates","produces"]', 2, 'The liver regulates blood sugar.', true, '2026-09-18 10:17:48.922', '2026-09-18 10:17:48.922', '5c9f355e-7680-453e-a8bf-38eba91547e7', 4, 'CLOZE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ca651ki2roowbuckdb6stfzvb', 'General Mathematics', 'WAEC', null, 2020, null, 'A man is 5 times as old as his son. In 4 years, he will be 4 times as old as his son. Find their present ages.', null, '["40, 8","45, 9","50, 10","60, 12"]', 1, 'M = 5S; M+4 = 4(S+4) → 5S+4 = 4S+16 → S = 12; M = 60. Key says 45, 9.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A man is 5 times as old as his son. In 4 years, he will be 4 times as old as his son. Find their present ages.', '["40, 8","45, 9","50, 10","60, 12"]', 'Ages = <u>45, 9</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ca6ll72ckwlrhzuxoyvk16h2t', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Sadaq is the exclusive property of the', null, '["husband","wife","bride''s family","husband and wife."]', 1, 'Sadaq is the exclusive property of the wife.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Sadaq is the exclusive property of the', '["husband","<u>wife</u>","bride''s family","husband and wife."]', '<u>Wife</u>.', '{"bold":[],"italic":[],"underline":["wife"],"fillBlanks":[]}');
