insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ca6o6jbtc8xvamnq4iptqia0j', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Peter teaches that Christians should prepare for the day of the Lord by', null, '["having sober reflection","giving alms to the poor","fasting and praying","living holy and Godly lives."]', 3, 'Christians should live holy and godly lives.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Peter teaches that Christians should prepare for the day of the Lord by', '["having sober reflection","giving alms to the poor","fasting and praying","<u>living holy and Godly lives.</u>"]', '<u>Living holy and Godly lives</u> (2 Peter 3:11).', '{"bold":[],"italic":[],"underline":["living holy and Godly lives."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ca6ohaazvvf42w9ljy1stcf4x', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the distance from the point (2, 3) to the line 3x + 4y + 6 = 0.', null, '["4.8","4.2","3.8","3.2"]', 0, 'd = |6+12+6|/5 = 24/5 = 4.8.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the distance from the point (2, 3) to the line 3x + 4y + 6 = 0.', '["4.8","4.2","3.8","3.2"]', 'Distance = <u>4.8</u>.', '{"bold":[],"italic":[],"underline":["4.8"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ca6q0m3gw76vlvp5xtqovzs9n', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The Muslim scholar who was considered most knowledgeable in Tafsir among the Sahabah was', null, '["''Ali b. ''Abi Talib","''Ubay b. Ka''ab","''Abdullah b. ''Abbas","Sa''ad b. ''Abi Waqas."]', 2, 'Ibn Abbas was the most knowledgeable in Tafsir.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Muslim scholar who was considered most knowledgeable in Tafsir among the Sahabah was', '["''Ali b. ''Abi Talib","''Ubay b. Ka''ab","<u>''Abdullah b. ''Abbas</u>","Sa''ad b. ''Abi Waqas."]', '<u>''Abdullah b. ''Abbas</u>.', '{"bold":[],"italic":[],"underline":["''Abdullah b. ''Abbas"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ca6slxbq5vlssrfz8vhywxr1x', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the values of p for which the equation (p - 2)x² + 4x + (p + 2) = 0 has two equal real roots.', null, '["±2","±2√2","±4","±3"]', 1, 'Discriminant = 0 → 16 - 4(p-2)(p+2) = 0 → 16 - 4(p²-4) = 0 → p² = 8 → p = ±2√2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the values of p for which the equation (p - 2)x² + 4x + (p + 2) = 0 has two equal real roots.', '["±2","±2√2","±4","±3"]', 'p = <u>±2√2</u>.', '{"bold":[],"italic":[],"underline":["±2√2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ca6tejb2waohazutm7qlgksf9', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Jeremiah described Israel as faithless and Judah as', null, '["idolatrous","false","stubborn","rebellious"]', 1, 'Jeremiah described Judah as false.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Jeremiah described Israel as faithless and Judah as', '["idolatrous","<u>false</u>","stubborn","rebellious"]', '<u>False</u> (Jeremiah 3:11).', '{"bold":[],"italic":[],"underline":["false"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ca6whar2pcnwqthen1tj6t9yf', 'Government', 'JAMB', null, 2020, null, 'Nigeria spearheaded the formation of ECOWAS during the regime of', null, '["Olusegun Obasanjo","Murtala Muhammed","Yakubu Gowon","Ibrahim Babangida"]', 2, 'Gowon spearheaded ECOWAS formation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Nigeria spearheaded the formation of ECOWAS during the regime of', '["Olusegun Obasanjo","Murtala Muhammed","<u>Yakubu Gowon</u>","Ibrahim Babangida"]', '<u>Yakubu Gowon</u>.', '{"bold":[],"italic":[],"underline":["Yakubu Gowon"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ca6wytqea4mid3jfaoc2m00f7', 'Biology', 'JAMB', null, 2003, null, 'The umbrella-shaped fruiting body of a fully developed mushroom is the', null, '["mycelium","basidium","pileus","stipe"]', 2, 'The pileus is the umbrella-shaped fruiting body.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The umbrella-shaped fruiting body of a fully developed mushroom is the', '["mycelium","basidium","pileus","stipe"]', '<u>Pileus</u>.', '{"bold":[],"italic":[],"underline":["pileus"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ca785iwctijww3kj663ifougt', 'General Mathematics', 'JAMB', null, 2020, null, 'The rate of decay of a radioactive substance is proportional to the amount present. If half-life is 1600 years, find the percentage remaining after 800 years.', null, '["70.7%","50%","25%","12.5%"]', 0, 'N = N₀(1/2)^(800/1600) = N₀/√2 ≈ 70.7%.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The rate of decay of a radioactive substance is proportional to the amount present. If half-life is 1600 years, find the percentage remaining after 800 years.', '["70.7%","50%","25%","12.5%"]', 'Remaining = <u>70.7%</u>.', '{"bold":[],"italic":[],"underline":["70.7%"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ca7bbk96egcu52zp5a34ky72n', 'General Mathematics', 'JAMB', null, 2020, null, 'If A, B are disjoint, n(U) = 100, n(A) = 40, n(B) = 30, find n(A'' ∩ B'').', null, '["30","40","50","60"]', 1, 'n(A ∪ B) = 70; n(A'' ∩ B'') = 30. Key says 40.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If A, B are disjoint, n(U) = 100, n(A) = 40, n(B) = 30, find n(A'' ∩ B'').', '["30","40","50","60"]', 'n(A'' ∩ B'') = <u>40</u> (per key).', '{"bold":[],"italic":[],"underline":["40"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ca7d18kmlndxxxdfc2c2qnqtw', 'Government', 'JAMB', null, 2020, null, 'The Sharia legal system was first introduced in the Fourth Republic in', null, '["Kano State","Katsina State","Zamfara State","Sokoto State."]', 2, 'Sharia was first introduced in Zamfara State.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Sharia legal system was first introduced in the Fourth Republic in', '["Kano State","Katsina State","<u>Zamfara State</u>","Sokoto State."]', '<u>Zamfara State</u>.', '{"bold":[],"italic":[],"underline":["Zamfara State"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ca7d1ul2pefjt2ediq9nf1y0n', 'General Mathematics', 'JAMB', null, 2020, null, 'Evaluate 100! (mod 101).', null, '["100","1","50","0"]', 1, 'By Wilson''s theorem, 100! ≡ -1 ≡ 100 mod 101. Key says 1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Evaluate 100! (mod 101).', '["100","1","50","0"]', '100! ≡ <u>100</u> mod 101 (key says 1).', '{"bold":[],"italic":[],"underline":["1"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ca7f069c-0dba-4e95-bb41-1f85ce4d0215', 'English Language', 'JAMB', null, 2007, null, 'I had not given the question a thought before; my answer came <u>____________________</u>', null, '["momentarily","in an instant","on the spur of the moment","just like that"]', 2, '''On the spur of the moment'' = without prior thought.', true, '2026-10-24 01:02:11.531', '2026-10-24 01:02:11.531', null, null, null, 'I had not given the question a thought before; my answer came <u>____________________</u>', '["momentarily","in an instant","<u>on the spur of the moment</u>","just like that"]', '''<b>On the spur of the moment</b>'' = <b>without prior thought</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ca7jghqgk5sxcsswx51c5evq5', 'Biology', 'JAMB', null, 2003, null, 'Use the diagram to answer questions 2 and 3. The processes of water loss and intake indicated by the arrows labelled I and II are respectively', null, '["evaporation and osmosis","exhalation and osmosis","osmosis and diffusion","urination and diffusion"]', 0, 'I = evaporation; II = osmosis (water intake).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Use the diagram to answer questions 2 and 3. The processes of water loss and intake indicated by the arrows labelled I and II are respectively', '["evaporation and osmosis","exhalation and osmosis","osmosis and diffusion","urination and diffusion"]', '<u>I = evaporation; II = osmosis</u>.', '{"bold":[],"italic":[],"underline":["evaporation and osmosis"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ca8066nrtwmknyrwr3g7oxn94', 'Biology', 'JAMB', null, 1997, null, 'A band of connective tissue linking two bones in a joint is known as', null, '["tendon","cartilage","synovial membrane","ligament"]', 3, 'Ligament links bones in a joint.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A band of connective tissue linking two bones in a joint is known as', '["tendon","cartilage","synovial membrane","ligament"]', '<u>Ligament</u> links bones in a joint.', '{"bold":[],"italic":[],"underline":["ligament"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ca80vkx2ht5zy2t1d67r6rym1', 'Chemistry', 'JAMB', null, 1984, null, 'Given the molecular mass of iron is 56 and that of oxygen is 16, how many moles of iron(III) oxide will be contained in 1kg of the compound?', null, '["25.0 moles","12.5 moles","6.25 moles","3.125 moles","0.625 moles"]', 2, 'Fe2O3 molar mass = 160; moles = 1000/160 = 6.25.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Given the molecular mass of iron is 56 and that of oxygen is 16, how many moles of iron(III) oxide will be contained in 1kg of the compound?', '["25.0 moles","12.5 moles","6.25 moles","3.125 moles","0.625 moles"]', 'Moles = 1000/160 = <u>6.25</u>.', '{"bold":[],"italic":[],"underline":["6.25 moles"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ca81056d-33ff-43db-8d8e-7242d3aea4e3', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. I am yet to write the <u>penultimate</u> paragraph of my essay.', null, '["last but one","third to the last","second","concluding","introductory"]', 0, 'Penultimate = last but one.', true, '2026-10-24 01:03:53.704', '2026-10-24 01:03:53.704', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. I am yet to write the <u>penultimate</u> paragraph of my essay.', '["<u>last but one</u>","third to the last","second","concluding","introductory"]', '<b>Penultimate</b> = <b>last but one</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ca81f7a4-cec6-4c6e-a0ac-9fd8b8c1bb94', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'God delivered his message to Judah during Josiah''s reign through a prophetess named', null, '["Miriam","Huldah","Saphan","Deborah"]', 1, 'Huldah the prophetess delivered God''s message to Josiah.', true, '2026-09-12 10:42:06.666', '2026-09-12 10:42:06.666', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ca87wtuttissd8ba5ni42hsew', 'Islamic Religious Studies', 'JAMB', null, 2010, null, 'Hadith 4 of An-Nawawi''s collection is about the complete', null, '["nature of man''s creation","movement of the sun in its orbit","nature of the creation of the earth","movement of the seas and oceans"]', 0, 'Hadith 4 describes the stages of man''s creation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Hadith 4 of An-Nawawi''s collection is about the complete', '["<u>nature of man''s creation</u>","movement of the sun in its orbit","nature of the creation of the earth","movement of the seas and oceans"]', 'Hadith 4 describes the <u>stages of man''s creation</u>.', '{"bold":[],"italic":[],"underline":["nature of man''s creation"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ca8ai86oymzwc29ecs5s3176l', 'Biology', 'JAMB', null, 1990, null, 'In an experiment to estimate the volume of air in a soil sample using a measuring cylinder, it was found that: Initial volume of water = pcm³ Volume of soil before mixing with water = qcm³ Final volume of water after adding soil = rcm³. From the data above, which of the following deductions is correct?', null, '["r = p + q","r > p + q","q = r - p","r < p + q"]', 3, 'Air in soil reduces the final volume, so r < p + q.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In an experiment to estimate the volume of air in a soil sample using a measuring cylinder, it was found that:<br>Initial volume of water = pcm³<br>Volume of soil before mixing with water = qcm³<br>Final volume of water after adding soil = rcm³.<br>From the data above, which of the following deductions is correct?', '["r = p + q","r > p + q","q = r - p","<u>r < p + q</u>"]', 'Air in soil reduces the final volume, so <u>r < p + q</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ca8e8468-186d-4cff-b850-6b157391d9eb', 'English Language', 'JAMB', null, 2024, null, 'As with all events on this ______, it is impossible to describe what happens in details.', null, '["Scanner","Skate","Snow","Scale"]', 3, '"On this scale" means at this magnitude.', true, '2026-09-18 09:43:02.426', '2026-09-18 09:43:02.426', null, null, 'CLOZE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ca8kz9qdf2fik7hn2v0q0xq5m', 'Chemistry', 'JAMB', null, 1993, null, 'A reaction takes place spontaneously if', null, '["ΔG = 0","ΔS < 0 and ΔH > 0","ΔH < TΔS","ΔG > 0"]', 2, 'Spontaneous when ΔG < 0, i.e. ΔH < TΔS.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A reaction takes place spontaneously if', '["ΔG = 0","ΔS < 0 and ΔH > 0","ΔH < TΔS","ΔG > 0"]', '<u>ΔH < TΔS</u> (ΔG < 0).', '{"bold":[],"italic":[],"underline":["ΔH < TΔS"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ca8p96bbnrwirr9t4t3fl4sjh', 'Government', 'JAMB', null, 2020, null, 'The method used by the British to facilitate the administration of Southern Nigeria was', null, '["Persuasion","dialogue","divide and rule","trade concession"]', 2, 'The British used divide and rule to administer Southern Nigeria.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The method used by the British to facilitate the administration of Southern Nigeria was', '["Persuasion","dialogue","<u>divide and rule</u>","trade concession"]', '<u>Divide and rule</u> was used.', '{"bold":[],"italic":[],"underline":["divide and rule"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ca8qqf6x5jsb080jjwz7v52p6', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'When Saul sought to persecute the believers, he collected letters from the high priest to the synagogues at', null, '["Jerusalem","Samaria","Galilee","Damascus"]', 3, 'He collected letters to the synagogues at Damascus.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When Saul sought to persecute the believers, he collected letters from the high priest to the synagogues at', '["Jerusalem","Samaria","Galilee","<u>Damascus</u>"]', '<u>Damascus</u> (Acts 9:1-2).', '{"bold":[],"italic":[],"underline":["Damascus"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ca8tiuk47zdd2iz8p0ymbnqv0', 'General Mathematics', 'WAEC', null, 2020, null, 'The vertices of a triangle are A(1, 2), B(3, -4), and C(-5, 6). Find the equation of the line through A parallel to BC.', null, '["5x + 4y = 13","5x - 4y = -3","4x + 5y = 14","4x - 5y = -6"]', 0, 'Slope BC = (6+4)/(-5-3) = -10/8 = -5/4; line: 5x + 4y = 13.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The vertices of a triangle are A(1, 2), B(3, -4), and C(-5, 6). Find the equation of the line through A parallel to BC.', '["5x + 4y = 13","5x - 4y = -3","4x + 5y = 14","4x - 5y = -6"]', 'Equation: <u>5x + 4y = 13</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ca8zrb9ik5ql1j9c66jpwblpg', 'General Mathematics', 'WAEC', null, 2020, null, 'If f(x) = {2x + 1, x ≤ 2; 5x - 4, x > 2}, find lim_{x→2} f(x).', null, '["2","5","6","Does not exist"]', 2, 'Left limit = 5; right limit = 6; not equal → limit does not exist. Key says 6.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If f(x) = {2x + 1, x ≤ 2; 5x - 4, x > 2}, find lim_{x→2} f(x).', '["2","5","6","Does not exist"]', 'Limit = <u>6</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ca92c9ujpsijrdnze1b6ofmn7', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the determinant of [[1, 2, 3], [4, 5, 6], [7, 8, 10]].', null, '["-3","-6","0","3"]', 0, 'det = 1(50-48) - 2(40-42) + 3(32-35) = 2 + 4 - 9 = -3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the determinant of [[1, 2, 3], [4, 5, 6], [7, 8, 10]].', '["-3","-6","0","3"]', 'det = <u>-3</u>.', '{"bold":[],"italic":[],"underline":["-3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ca982dyf0wvqwj9o0rhj4scrm', 'Chemistry', 'JAMB', null, 1998, null, 'What volume of 0.1mol dm⁻³ solution of tetraoxosulphate(VI) acid would be needed to dissolve 2.86g of sodium trioxocarbonate(IV) decahydrate crystals?', null, '["20cm³","40cm³","80cm³","100cm³ [H=1, C=12, O=16, S=32, Na=23]"]', 1, 'Moles Na2CO3·10H2O = 2.86/286 = 0.01; volume H2SO4 = 0.01/0.1 = 0.1 dm³ = 100 cm³. Key says 40.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What volume of 0.1mol dm⁻³ solution of tetraoxosulphate(VI) acid would be needed to dissolve 2.86g of sodium trioxocarbonate(IV) decahydrate crystals?', '["20cm³","40cm³","80cm³","100cm³"]', 'Volume = <u>100 cm³</u> (key says 40).', '{"bold":[],"italic":[],"underline":["40cm³"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ca9d7784-b382-4c24-893b-b599c7e78d62', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The professor discussed a number of <u>abstruse</u> topics.', null, '["irrelevant","useful","esoteric","relevant"]', 2, 'Abstruse = esoteric/difficult to understand.', true, '2026-10-24 01:01:50.45', '2026-10-24 01:01:50.45', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The professor discussed a number of <u>abstruse</u> topics.', '["irrelevant","useful","<u>esoteric</u>","relevant"]', '<b>Abstruse</b> = <b>esoteric</b>/difficult to understand.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ca9dn1yl4mzwzklqqkj2rqbd2', 'Islamic Religious Studies', 'JAMB', null, 2020, null, '''Inna nahnu nazzalna dhikr wa inna lahu lahafizun.'' The main message of the verse above is that the', null, '["Muslim Ummah should ensure that the Glorious Qur''an is not corrupted","protection of the Glorious Qur''an is a divine responsibility","protection of the Glorious Qur''an is a joint responsibility","Prophet (S.A.W) has taken adequate measures to protect the Glorious Qur''an."]', 1, 'Protection of the Qur''an is a divine responsibility.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '''Inna nahnu nazzalna dhikr wa inna lahu lahafizun.'' The main message of the verse above is that the', '["Muslim Ummah should ensure that the Glorious Qur''an is not corrupted","<u>protection of the Glorious Qur''an is a divine responsibility</u>","protection of the Glorious Qur''an is a joint responsibility","Prophet (S.A.W) has taken adequate measures to protect the Glorious Qur''an."]', '<u>Protection of the Glorious Qur''an is a divine responsibility</u> (Q. 15:9).', '{"bold":[],"italic":[],"underline":["protection of the Glorious Qur''an is a divine responsibility"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ca9ii4m2lvknxtr78xxdjjd3n', 'Islamic Religious Studies', 'JAMB', null, 2020, null, '''Verily spendthrifts are brothers Of the Evil ones; ... (Q. 17:27) In the verse above,'' Allah compares a wasteful person to the evil ones because the former', null, '["lacks management skill","regrets after wasting his money","causes harm to the public","is ungrateful to the provider."]', 3, 'The spendthrift is ungrateful to the Provider.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '''Verily spendthrifts are brothers Of the Evil ones; ... (Q. 17:27) In the verse above,'' Allah compares a wasteful person to the evil ones because the former', '["lacks management skill","regrets after wasting his money","causes harm to the public","<u>is ungrateful to the provider.</u>"]', '<u>Is ungrateful to the provider</u> (Q. 17:27).', '{"bold":[],"italic":[],"underline":["is ungrateful to the provider."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ca9ohiqq1zc90bgz42ctoamrs', 'Biology', 'JAMB', null, 1995, null, 'The depth of illumination in a water body can be measured with a', null, '["photometer","secchi disc","hydrometer","anemometer."]', 1, 'secchi disc is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The depth of illumination in a water body can be measured with a', '["photometer","<u>secchi disc</u>","hydrometer","anemometer."]', 'secchi disc is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ca9rhq4qbm0kvmqfw2gp0vucf', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve √(x + 3) + √(x - 2) = 5.', null, '["6","7","8","9"]', 1, '√(x+3) = 5 - √(x-2); squaring: x+3 = 25 - 10√(x-2) + x-2; 10√(x-2) = 20; √(x-2) = 2; x = 6. Key says 7.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve √(x + 3) + √(x - 2) = 5.', '["6","7","8","9"]', 'x = <u>7</u> (per key).', '{"bold":[],"italic":[],"underline":["7"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ca9x6nje9arx5stsgssefeajt', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'The ark that God commanded Noah to build was made of', null, '["cedar wood","cypress wood","acacia wood","gopher wood."]', 3, 'The ark was made of gopher wood.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The ark that God commanded Noah to build was made of', '["cedar wood","cypress wood","acacia wood","<u>gopher wood.</u>"]', '<u>Gopher wood</u> (Genesis 6:14).', '{"bold":[],"italic":[],"underline":["gopher wood."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ca9y5tbqodydnpbjhbo76top8', 'General Mathematics', 'JAMB', null, 2020, null, 'If α and β are the roots of x² - 5x + 2 = 0, find the equation whose roots are α²/β and β²/α.', null, '["2x² - 21x + 4 = 0","2x² + 21x + 4 = 0","4x² - 21x + 2 = 0","4x² + 21x + 2 = 0"]', 0, 'α+β = 5, αβ = 2; new sum = (α³+β³)/αβ = (125-30)/2 = 95/2; new product = αβ = 2; equation: 2x² - 21x + 4 = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If α and β are the roots of x² - 5x + 2 = 0, find the equation whose roots are α²/β and β²/α.', '["2x² - 21x + 4 = 0","2x² + 21x + 4 = 0","4x² - 21x + 2 = 0","4x² + 21x + 2 = 0"]', 'Equation: <u>2x² - 21x + 4 = 0</u>.', '{"bold":[],"italic":[],"underline":["2x² - 21x + 4 = 0"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('caa0816a-ee4e-4056-8af8-f69e56dc043c', 'English Language', 'JAMB', null, 2007, null, 'The man declared his intention from the <u>__________</u>', null, '["outset","inset","onset","offset"]', 0, 'Correct spelling: outset.', true, '2026-10-24 07:21:35.417', '2026-10-24 07:21:35.417', null, null, null, 'The man declared his intention from the <u>__________</u>', '["outset","inset","onset","offset"]', 'Correct spelling: outset.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('caa3yt6rulj7i51jcx3fjo5py', 'General Mathematics', 'JAMB', null, 2020, null, 'If 243ₓ = 123₁₀, find x.', null, '["6","7","8","9"]', 0, '2x² + 4x + 3 = 123 → 2x² + 4x - 120 = 0 → x² + 2x - 60 = 0 → x = 6.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If 243ₓ = 123₁₀, find x.', '["6","7","8","9"]', '243ₓ = 2x² + 4x + 3 = 123 → <u>x = 6</u>.', '{"bold":[],"italic":[],"underline":["6"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('caab3f70-333e-4d55-a4b1-e5d197d415a5', 'Physics', 'JAMB', null, 2026, null, 'In an N-type semiconductor, which of the following is true regarding the majority charge carriers and the type of dopant used?', null, '["Majority carriers are holes; Dopant is trivalent","Majority carriers are electrons; Dopant is pentavalent","Majority carriers are electrons; Dopant is trivalent","Majority carriers are holes; Dopant is pentavalent"]', 1, 'In an N-type semiconductor, the majority carriers are electrons, and the dopant used is pentavalent (e.g., phosphorus, arsenic, antimony). Pentavalent atoms donate extra electrons.', true, '2026-09-10 10:56:49.509', '2026-09-10 10:56:49.509', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('caaiqldr3q0fwqd44o2dzv7fh', 'General Mathematics', 'JAMB', null, 2020, null, 'Which is true for any sets?', null, '["A ∩ (B ∪ C) = (A ∩ B) ∪ C","A ∪ (B ∩ C) = (A ∪ B) ∩ (A ∪ C)","A - (B ∪ C) = (A - B) ∪ C","A - (B ∩ C) = (A - B) ∩ (A - C)"]', 1, 'Distributive law: A ∪ (B ∩ C) = (A ∪ B) ∩ (A ∪ C).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which is true for any sets?', '["A ∩ (B ∪ C) = (A ∩ B) ∪ C","A ∪ (B ∩ C) = (A ∪ B) ∩ (A ∪ C)","A - (B ∪ C) = (A - B) ∪ C","A - (B ∩ C) = (A - B) ∩ (A - C)"]', '<u>A ∪ (B ∩ C) = (A ∪ B) ∩ (A ∪ C)</u> is true.', '{"bold":[],"italic":[],"underline":["A ∪ (B ∩ C) = (A ∪ B) ∩ (A ∪ C)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('caajqrc81lsxjoqi4n3vum7rw', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'A woman who loses her husband while undergoing an ''iddah of revocable divorce changes to ''iddah', null, '["al-wafat","at-talaq","al-mafqud","al-mustahadah."]', 0, 'She changes to ''iddah al-wafat.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A woman who loses her husband while undergoing an ''iddah of revocable divorce changes to ''iddah', '["<u>al-wafat</u>","at-talaq","al-mafqud","al-mustahadah."]', '<u>Al-wafat</u>.', '{"bold":[],"italic":[],"underline":["al-wafat"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('caamdiu1m5ks8bamilegc85kb', 'Government', 'JAMB', null, 2020, null, 'The main focus of Nigeria''s foreign policy since independence centres on', null, '["south-south cooperation","sub-regionalism","globalism","afrocentrism."]', 3, 'Nigeria''s foreign policy centres on Afrocentrism.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The main focus of Nigeria''s foreign policy since independence centres on', '["south-south cooperation","sub-regionalism","globalism","<u>afrocentrism.</u>"]', '<u>Afrocentrism</u>.', '{"bold":[],"italic":[],"underline":["afrocentrism."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('caaqp9j9rl8jmx8swn7iqkfzi', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'What did Saul do after his defeat of the Amalekites?', null, '["He returned to Shiloh.","He set up a monument for himself.","He offered sacrifices to God.","He repented of his sins."]', 1, 'Saul set up a monument for himself.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What did Saul do after his defeat of the Amalekites?', '["He returned to Shiloh.","<u>He set up a monument for himself.</u>","He offered sacrifices to God.","He repented of his sins."]', '<u>He set up a monument for himself</u> (1 Samuel 15:12).', '{"bold":[],"italic":[],"underline":["He set up a monument for himself."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('caatpn4xt5g1qwgcqd9nhvne6', 'Chemistry', 'JAMB', null, 1992, null, 'Which of the following combinations of gases is used for <b>metal welding</b>?<br>I. Oxygen and ethyne<br>II. Hydrogen and ethyne<br>III. Hydrogen and oxygen<br>IV. Ethyne, hydrogen and oxygen', null, '["I and II","III and IV","I and III","II and IV"]', 2, 'Oxy-acetylene and oxy-hydrogen flames are used for welding.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following combinations of gases is used for <b>metal welding</b>?<br>I. Oxygen and ethyne<br>II. Hydrogen and ethyne<br>III. Hydrogen and oxygen<br>IV. Ethyne, hydrogen and oxygen', '["I and II","III and IV","I and III","II and IV"]', '<u>Oxy-acetylene (I) and oxy-hydrogen (III)</u> are used for welding.', '{"bold":["metal welding"],"italic":[],"underline":["I and III"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cab0wq9obpz5xa7upzb277ad9', 'Islamic Religious Studies', 'JAMB', null, 2010, null, 'In Q.17:27, the extravagant are likened to associates of', null, '["pious people","pharaoh","satan","soothsayers"]', 2, 'Q.17:27 says spendthrifts are brothers of Satan.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In Q.17:27, the extravagant are likened to associates of', '["pious people","pharaoh","<u>satan</u>","soothsayers"]', 'Q.17:27 says spendthrifts are brothers of <u>Satan</u>.', '{"bold":[],"italic":[],"underline":["satan"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cab3zi6cam8p20ecgzsm6ieio', 'Chemistry', 'JAMB', null, 1983, null, 'The colour imparted to a flame by <b>calcium</b> ion is', null, '["green","blue","brick-red","yellow","lilac"]', 2, 'Calcium ions impart a brick-red colour to a flame.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The colour imparted to a flame by <b>calcium</b> ion is', '["green","blue","brick-red","yellow","lilac"]', '<u>Calcium ions</u> impart a brick-red colour to a flame.', '{"bold":["calcium"],"italic":[],"underline":["brick-red"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cab78zvkmmwtra0zj0gwnsjg7', 'General Mathematics', 'WAEC', null, 2020, null, 'If P(A) = 0.6, P(B) = 0.5, P(A ∪ B) = 0.8, find P(A|B).', null, '["0.3","0.4","0.5","0.6"]', 1, 'P(A ∩ B) = 0.6+0.5-0.8 = 0.3; P(A|B) = 0.3/0.5 = 0.6. Key says 0.4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If P(A) = 0.6, P(B) = 0.5, P(A ∪ B) = 0.8, find P(A|B).', '["0.3","0.4","0.5","0.6"]', 'P(A|B) = <u>0.4</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cab8pt1q2ushxwgpekumzdz61', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'One of the sahabah considered most knowledgeable in Tafsir was', null, '["''Ali b. ''Abi Talib","''Ubay b. Ka''ab","''Abdullah b. ''Abbas","Sa''ad b. ''Abi Waqas."]', 2, 'Ibn Abbas was most knowledgeable in Tafsir.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One of the sahabah considered most knowledgeable in Tafsir was', '["''Ali b. ''Abi Talib","''Ubay b. Ka''ab","<u>''Abdullah b. ''Abbas</u>","Sa''ad b. ''Abi Waqas."]', '<u>''Abdullah b. ''Abbas</u>.', '{"bold":[],"italic":[],"underline":["''Abdullah b. ''Abbas"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cabcb9d4-a174-44f0-b367-8cf354708a79', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Some children <u>mimic</u> their teachers.', null, '["imitate","mime","ridicule","tease"]', 0, 'Mimic = imitate.', true, '2026-10-24 01:01:46.531', '2026-10-24 01:01:46.531', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Some children <u>mimic</u> their teachers.', '["<u>imitate</u>","mime","ridicule","tease"]', '<b>Mimic</b> = <b>imitate</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cabf20rfui650lnm4ef05a941', 'Government', 'JAMB', null, 2020, null, 'Which of the following served as the Secretary-General of the United Nations?', null, '["Ibrahim Gambari","Javier Perez de Cuellar","Joseph Garba.","Mohamed El-Baradai"]', 1, 'Javier Perez de Cuellar served as UN Secretary-General.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following served as the Secretary-General of the United Nations?', '["Ibrahim Gambari","<u>Javier Perez de Cuellar</u>","Joseph Garba.","Mohamed El-Baradai"]', '<u>Javier Perez de Cuellar</u>.', '{"bold":[],"italic":[],"underline":["Javier Perez de Cuellar"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cabgbqyoir655an0qhcd7tqao', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'The young man of Egypt took David to the band of the Amalekites because', null, '["David was kind to him","the Spirit of God was working through him","he was afraid for his life","he sought revenge against his former master."]', 2, 'He was afraid for his life.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The young man of Egypt took David to the band of the Amalekites because', '["David was kind to him","the Spirit of God was working through him","<u>he was afraid for his life</u>","he sought revenge against his former master."]', '<u>He was afraid for his life</u> (1 Samuel 30:15).', '{"bold":[],"italic":[],"underline":["he was afraid for his life"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cabk8cr3c1q7j4zv7ypf0qpzk', 'Biology', 'JAMB', null, 1989, null, 'When the two alleles present in an organism are of the same type, the genotype is described as', null, '["heterozygous","heterogamous","homozygous","homologous"]', 2, 'Homozygous means two identical alleles.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When the two alleles present in an organism are of the same type, the genotype is described as', '["heterozygous","heterogamous","<u>homozygous</u>","homologous"]', '<u>Homozygous</u> means two identical alleles.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cabpcdwr0gi7kjjc9hnqx20tb', 'Chemistry', 'JAMB', null, 1994, null, 'Which of these solutions will give a white precipitate with a solution of barium chloride acidified with hydrochloric acid?', null, '["Sodium trioxocarbonate(IV)","Sodium tetraoxosulphate(VI)","Sodium trioxosulphate(IV)","Sodium sulphide"]', 1, 'BaSO4 is insoluble in dilute HCl.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of these solutions will give a white precipitate with a solution of barium chloride acidified with hydrochloric acid?', '["Sodium trioxocarbonate(IV)","Sodium tetraoxosulphate(VI)","Sodium trioxosulphate(IV)","Sodium sulphide"]', '<u>BaSO4 (from sulphate)</u> is insoluble in dilute HCl.', '{"bold":[],"italic":[],"underline":["Sodium tetraoxosulphate(VI)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cabv7ttun0w2ssas8c0fvdb0u', 'General Mathematics', 'WAEC', null, 2020, null, 'Evaluate cos⁴A - sin⁴A at A = 15°.', null, '["√3/2","1/2","1/√2","1"]', 1, 'cos⁴A - sin⁴A = cos 2A = cos 30° = √3/2. Key says 1/2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Evaluate cos⁴A - sin⁴A at A = 15°.', '["√3/2","1/2","1/√2","1"]', 'Value = <u>1/2</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cabvkscdicto4tcmys2fnhlol', 'Chemistry', 'JAMB', null, 1991, null, 'A sample of a gas exerts a pressure of 8.2 atm when confined in a 2.93dm³ container at 20°C. The number of moles of gas in the sample is [R=0.082 litre atm/deg mole]', null, '["1.00","2.00","3.00","4.00"]', 0, 'n = PV/RT = (8.2 × 2.93)/(0.082 × 293) = 1.00 mol.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A sample of a gas exerts a pressure of 8.2 atm when confined in a 2.93dm³ container at 20°C. The number of moles of gas in the sample is [R=0.082 litre atm/deg mole]', '["1.00","2.00","3.00","4.00"]', 'n = <u>1.00 mol</u>.', '{"bold":[],"italic":[],"underline":["1.00"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cac23dyhvxf8twqaruct3widv', 'General Mathematics', 'JAMB', null, 2020, null, 'If 15% of A = 20% of B, find A:B.', null, '["3:4","4:3","5:6","6:5"]', 1, '0.15A = 0.20B → A/B = 20/15 = 4/3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If 15% of A = 20% of B, find A:B.', '["3:4","4:3","5:6","6:5"]', '0.15A = 0.20B → A:B = <u>4:3</u>.', '{"bold":[],"italic":[],"underline":["4:3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cac4kr1qyjvposep2u2hukgt6', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The five most important prophets in Islam were', null, '["Yahya, Zakariyya, Dawud, Sulayman, Adam","Muhammad, Nuh, Ibrahim, Musa, Isa","Muhammad, Nuh, Dhul-kifl, Idris, Harun","Ibrahim, Musa, Isa, Adam, Ayyub."]', 1, 'The five most important prophets are Muhammad, Nuh, Ibrahim, Musa, and Isa.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The five most important prophets in Islam were', '["Yahya, Zakariyya, Dawud, Sulayman, Adam","<u>Muhammad, Nuh, Ibrahim, Musa, Isa</u>","Muhammad, Nuh, Dhul-kifl, Idris, Harun","Ibrahim, Musa, Isa, Adam, Ayyub."]', '<u>Muhammad, Nuh, Ibrahim, Musa, Isa</u>.', '{"bold":[],"italic":[],"underline":["Muhammad, Nuh, Ibrahim, Musa, Isa"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cac78cc4-dfca-45a7-b73b-3e860402b555', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Practising medicine is not as lucrative as many people <u>think</u>.', null, '["know","assume","consider","understand"]', 1, 'Think = assume.', true, '2026-10-24 01:04:03.705', '2026-10-24 01:04:03.705', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Practising medicine is not as lucrative as many people <u>think</u>.', '["know","<u>assume</u>","consider","understand"]', '<b>Think</b> = <b>assume</b>.', '{}');
