insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cackcyluno2nd8mdllf72jdrq', 'Chemistry', 'JAMB', null, 1995, null, 'X(g) → X⁺(g) + e⁻. The type of energy involved in the above transformation is', null, '["ionization energy","sublimation energy","lattice energy","electron affinity"]', 0, 'Ionization energy removes an electron from a gaseous atom.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'X(g) → X⁺(g) + e⁻. The type of energy involved in the above transformation is', '["ionization energy","sublimation energy","lattice energy","electron affinity"]', '<u>Ionization energy</u> removes an electron.', '{"bold":[],"italic":[],"underline":["ionization energy"],"fillBlanks":[]}');
