insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cacx8qnjm5eqj7zli6qgehfuz', 'General Mathematics', 'JAMB', null, 2020, null, 'Evaluate ∫e^(2x) sin 3x dx.', null, '["e^(2x)(2sin 3x - 3cos 3x)/13 + C","e^(2x)(3sin 3x - 2cos 3x)/13 + C","e^(2x)(3sin 3x + 2cos 3x)/13 + C","e^(2x)(3sin 3x + 2cos 3x)/13 + C"]', 0, 'Integration by parts twice: result = e^(2x)(2sin 3x - 3cos 3x)/13 + C.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Evaluate ∫e^(2x) sin 3x dx.', '["e^(2x)(2sin 3x - 3cos 3x)/13 + C","e^(2x)(3sin 3x - 2cos 3x)/13 + C","e^(2x)(3sin 3x + 2cos 3x)/13 + C","e^(2x)(3sin 3x + 2cos 3x)/13 + C"]', 'Integral = <u>e^(2x)(2sin 3x - 3cos 3x)/13 + C</u>.', '{"bold":[],"italic":[],"underline":["e^(2x)(2sin 3x - 3cos 3x)/13 + C"],"fillBlanks":[]}');
