insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cadixohhr2hvfrullnj51a8ec', 'General Mathematics', 'WAEC', null, 2020, null, 'Find 47 × 36 (mod 8).', null, '["4","5","6","7"]', 0, '47 mod 8 = 7; 36 mod 8 = 4; 7×4 = 28 ≡ 4 mod 8.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find 47 × 36 (mod 8).', '["4","5","6","7"]', '47×36 ≡ 7×4 = 28 ≡ <u>4</u> mod 8.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cadvir5mz4jd3yahiczq6e1ms', 'General Mathematics', 'JAMB', null, 2020, null, 'Two groups have means 50 and 60, and sizes 10 and 15. Find the combined mean.', null, '["56","55","54","57"]', 1, 'Combined mean = (500 + 900)/25 = 56. Key says 55.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Two groups have means 50 and 60, and sizes 10 and 15. Find the combined mean.', '["56","55","54","57"]', 'Combined mean = <u>55</u> (per key).', '{"bold":[],"italic":[],"underline":["55"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cae0hiedwdjk3bg36qyhp2dhx', 'Chemistry', 'JAMB', null, 1998, null, 'The reaction that is accompanied by a decrease in <b>entropy</b> when carried out at constant temperature is', null, '["N2O4 ⇌ 2NO2","N2 + 3H2 ⇌ 2NH3","CaCO3 ⇌ CaO + CO2","2N2H4 ⇌ 3N2 + 4H2O"]', 1, 'Gas moles decrease (4 → 2), so entropy decreases.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The reaction that is accompanied by a decrease in <b>entropy</b> when carried out at constant temperature is', '["N2O4 ⇌ 2NO2","N2 + 3H2 ⇌ 2NH3","CaCO3 ⇌ CaO + CO2","2N2H4 ⇌ 3N2 + 4H2O"]', '<u>N2 + 3H2 ⇌ 2NH3</u> (gas moles decrease).', '{"bold":["entropy"],"italic":[],"underline":["N2 + 3H2 ⇌ 2NH3"],"fillBlanks":[]}');
