insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('caeq8yk1i3cyllgkyp3284bka', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The hadith ''He who does not thank people does not thank Allah'' teaches', null, '["gratitude to Allah alone","gratitude to people","gratitude to both Allah and people","gratitude to parents"]', 1, 'It teaches gratitude to people.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The hadith ''He who does not thank people does not thank Allah'' teaches', '["gratitude to Allah alone","<u>gratitude to people</u>","gratitude to both Allah and people","gratitude to parents"]', '<u>Gratitude to people</u>.', '{"bold":[],"italic":[],"underline":["gratitude to people"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('caetjamyb1zu9vf2ely3azwnc', 'Chemistry', 'JAMB', null, 1992, null, 'Which of the following equilibria shows little or no net reaction when the volume of the system is <b>decreased</b>?', null, '["H2(g) + I2(g) → 2HI(g)","2NO(g) → N2O(g)","PCl5(g) → PCl3(g) + Cl2(g)","ZnO(s) + CO(g) → ZnCO3(s)"]', 0, 'Equal gas moles on both sides → no effect from volume change.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following equilibria shows little or no net reaction when the volume of the system is <b>decreased</b>?', '["H2(g) + I2(g) → 2HI(g)","2NO(g) → N2O(g)","PCl5(g) → PCl3(g) + Cl2(g)","ZnO(s) + CO(g) → ZnCO3(s)"]', '<u>Equal gas moles on both sides</u> → no effect.', '{"bold":["volume of the system is decreased"],"italic":[],"underline":["H2(g) + I2(g) → 2HI(g)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('caexxbp0dh9lmgouvkbkz0spg', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the equation of the tangent to the circle x² + y² = 25 at the point (3, 4).', null, '["3x + 4y = 25","4x + 3y = 25","3x - 4y = 25","4x - 3y = 25"]', 0, 'Tangent: x·3 + y·4 = 25 → 3x + 4y = 25.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the equation of the tangent to the circle x² + y² = 25 at the point (3, 4).', '["3x + 4y = 25","4x + 3y = 25","3x - 4y = 25","4x - 3y = 25"]', 'Tangent: <u>3x + 4y = 25</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('caeydv310tudzs93pwy5te3oj', 'Biology', 'JAMB', null, 2000, null, 'In mammals, re-absorption of salt takes place in', null, '["IV","III","II","I"]', 1, 'Reabsorption of salt occurs in part III.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In mammals, re-absorption of salt takes place in', '["IV","III","II","I"]', '<u>Part III</u> reabsorbs salt.', '{"bold":[],"italic":[],"underline":["III"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('caf0e033-4477-416b-b440-581114b6e264', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Your extreme patience sometimes <u>infuriates</u> me.', null, '["impresses","annoys","frustrates","amuses"]', 1, 'Infuriates = annoys greatly.', true, '2026-10-24 01:01:42.978', '2026-10-24 01:01:42.978', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Your extreme patience sometimes <u>infuriates</u> me.', '["impresses","<u>annoys</u>","frustrates","amuses"]', '<b>Infuriates</b> = <b>annoys</b> greatly.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('caf42mtl12qqd2n8mhdy76rsn', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'What was Nehemiah''s initial reaction to the news about the ruins of Jerusalem?', null, '["He tasked the people on what to contribute.","He called volunteers to assist him.","He fasted and prayed for forgiveness of sins.","He asked for permission to travel home."]', 2, 'Nehemiah fasted and prayed.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What was Nehemiah''s initial reaction to the news about the ruins of Jerusalem?', '["He tasked the people on what to contribute.","He called volunteers to assist him.","<u>He fasted and prayed for forgiveness of sins.</u>","He asked for permission to travel home."]', '<u>He fasted and prayed for forgiveness of sins</u> (Nehemiah 1:2-9).', '{"bold":[],"italic":[],"underline":["He fasted and prayed for forgiveness of sins."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('caf4wctjjunqmth596oe5zs5y', 'General Mathematics', 'WAEC', null, 2020, null, 'If A³ = 0, find (I - A)⁻¹.', null, '["I + A + A²","I - A + A²","I - A","I + A"]', 0, '(I-A)(I+A+A²) = I - A³ = I.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If A³ = 0, find (I - A)⁻¹.', '["I + A + A²","I - A + A²","I - A","I + A"]', '(I - A)⁻¹ = <u>I + A + A²</u>.', null);
