insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cafrez2h19l34w2seagleqvc1', 'Biology', 'JAMB', null, 2001, null, 'Amphibians are normally found', null, '["on dry land and in water","in water and on moist land","on moist land","in water"]', 1, 'Amphibians live in water and on moist land.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Amphibians are normally found', '["on dry land and in water","in water and on moist land","on moist land","in water"]', '<u>Water and moist land</u>.', '{"bold":[],"italic":[],"underline":["in water and on moist land"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cafsfuynavrkruw6vzajjwt6e', 'Biology', 'JAMB', null, 1993, null, 'Which group of plants would be the first colonizers in an ecological succession changing rocks to soil?', null, '["Mosses","Ferns","Lichens","Grasses"]', 2, 'Lichens are the first colonizers of bare rocks.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which group of plants would be the first colonizers in an ecological succession changing rocks to soil?', '["Mosses","Ferns","<u>Lichens</u>","Grasses"]', '<u>Lichens are the first colonizers of bare rocks</u>.', null);
