insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cag2x1a1avgvube8frhg7we8y', 'General Mathematics', 'JAMB', null, 2020, null, 'The sum to n terms: 1 + 11 + 111 + 1111 + ...', null, '["(10ⁿ⁺¹ - 9n - 10)/81","(10ⁿ - 9n - 10)/81","(10ⁿ⁺¹ - 9n + 10)/81","(10ⁿ - 9n + 10)/81"]', 0, 'Sum = (10/9)(10ⁿ - 1)/9 - n/9 = (10ⁿ⁺¹ - 9n - 10)/81.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The sum to n terms: 1 + 11 + 111 + 1111 + ...', '["(10ⁿ⁺¹ - 9n - 10)/81","(10ⁿ - 9n - 10)/81","(10ⁿ⁺¹ - 9n + 10)/81","(10ⁿ - 9n + 10)/81"]', 'Sum = <u>(10ⁿ⁺¹ - 9n - 10)/81</u>.', '{"bold":[],"italic":[],"underline":["(10ⁿ⁺¹ - 9n - 10)/81"],"fillBlanks":[]}');
