insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cahnvkeugjc7e9s08nddjovz5', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Isaiah emphasized holiness above all things because God', null, '["knew their hearts were right with him","was not interested in their sacrifices","who called them is holy","was searching their sinful hearts."]', 1, 'God was not interested in their sacrifices.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Isaiah emphasized holiness above all things because God', '["knew their hearts were right with him","<u>was not interested in their sacrifices</u>","who called them is holy","was searching their sinful hearts."]', '<u>Was not interested in their sacrifices</u>.', '{"bold":[],"italic":[],"underline":["was not interested in their sacrifices"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cahwor364k610c9odnf7ik99g', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'When Prophet Muhammad (S.A.W) led the Muslims in a triumphant entry into Makkah, all Makkans were assured of their safety if they entered the sacred mosque, remained indoors in their homes or', null, '["entered the house of Abu Sufyan","prostrated themselves before Muhammad (S.A.W)","surrendered all their belongings","freed all detained Muslims"]', 0, 'They were safe if they entered the house of Abu Sufyan.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When Prophet Muhammad (S.A.W) led the Muslims in a triumphant entry into Makkah, all Makkans were assured of their safety if they entered the sacred mosque, remained indoors in their homes or', '["<u>entered the house of Abu Sufyan</u>","prostrated themselves before Muhammad (S.A.W)","surrendered all their belongings","freed all detained Muslims"]', '<u>Entered the house of Abu Sufyan</u>.', '{"bold":[],"italic":[],"underline":["entered the house of Abu Sufyan"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cahxh3trx48r9mgubmvv5zcif', 'Chemistry', 'JAMB', null, 1990, null, 'Cr2O7²⁻ + 6Fe²⁺ + 14H⁺ → 2Cr³⁺ + 6Fe³⁺ + 7H2O. In the above chromium change from', null, '["+7 to +3","+6 to +3","+5 to +3","-2 to +3"]', 1, 'Cr in Cr2O7²⁻ is +6; in Cr³⁺ it is +3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Cr2O7²⁻ + 6Fe²⁺ + 14H⁺ → 2Cr³⁺ + 6Fe³⁺ + 7H2O. In the above chromium change from', '["+7 to +3","+6 to +3","+5 to +3","-2 to +3"]', 'Cr changes from <u>+6 to +3</u>.', '{"bold":[],"italic":[],"underline":["+6 to +3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cai2wd8sxh1puxoehentq1k8h', 'Chemistry', 'JAMB', null, 1983, null, 'The balanced equation for the reaction of tetraoxosulphate(VI) acid with aluminium hydroxide to give water and aluminium tetraoxosulphate(VI) is', null, '["H2SO4 + AlSO4 → 2H2O + AlSO4","H2SO4 + AlOH → Al2O + Al2SO4","3H2SO4 + 2Al(OH)3 → 6H2O + Al2(SO4)3","H2SO4 + Al(OH)3 → H2O + Al2(SO4)3","H2SO4 + Al(OH)3 → H2O + Al2(SO4)3"]', 2, 'Balanced: 3H2SO4 + 2Al(OH)3 → 6H2O + Al2(SO4)3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The balanced equation for the reaction of tetraoxosulphate(VI) acid with aluminium hydroxide to give water and aluminium tetraoxosulphate(VI) is', '["H2SO4 + AlSO4 → 2H2O + AlSO4","H2SO4 + AlOH → Al2O + Al2SO4","3H2SO4 + 2Al(OH)3 → 6H2O + Al2(SO4)3","H2SO4 + Al(OH)3 → H2O + Al2(SO4)3","H2SO4 + Al(OH)3 → H2O + Al2(SO4)3"]', '<u>3H2SO4 + 2Al(OH)3 → 6H2O + Al2(SO4)3</u>.', '{"bold":[],"italic":[],"underline":["3H2SO4 + 2Al(OH)3 → 6H2O + Al2(SO4)3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cai5cyadbkamyyatm6w79b8gn', 'Islamic Religious Studies', 'JAMB', null, 2010, null, 'Al-Kawthar in the Glorious Qur''an is otherwise called a', null, '["river in paradise","garden in paradise","light in paradise","fruit in paradise"]', 0, 'Q.108:1 describes Al-Kawthar as a river in Paradise.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Al-Kawthar in the Glorious Qur''an is otherwise called a', '["<u>river in paradise</u>","garden in paradise","light in paradise","fruit in paradise"]', '<u>Q.108:1</u> describes Al-Kawthar as a river in Paradise.', '{"bold":[],"italic":[],"underline":["river in paradise"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cai7emuyene3gzmiknmq6jrrh', 'Government', 'JAMB', null, 2020, null, 'An intra-party activity for the selection of candidates for elective positions is known as', null, '["primary election","general election","mid-term election","bye-election."]', 0, 'Primary elections select party candidates.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An intra-party activity for the selection of candidates for elective positions is known as', '["<u>primary election</u>","general election","mid-term election","bye-election."]', '<u>Primary election</u>.', '{"bold":[],"italic":[],"underline":["primary election"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cai9r4rbm21uy6yi82vrf9jsj', 'General Mathematics', 'WAEC', null, 2020, null, 'If (h, 3) lies on the line joining (1,2) and (3,4), find h.', null, '["2","3","4","5"]', 0, 'Slope = 1; (3-2)/(h-1) = 1 → h = 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If (h, 3) lies on the line joining (1,2) and (3,4), find h.', '["2","3","4","5"]', 'h = <u>2</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('caibp0lg1wj2zw2c60zlyy7cc', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'A''ishah''s role in the transmission of Hadith is next in significance to that of', null, '["Abu Hurayrah","Imam Bukhari","Abu Sa''id al-Khudri","Abu Bakr as-Siddiq."]', 0, 'A''ishah''s role is next to Abu Hurayrah.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A''ishah''s role in the transmission of Hadith is next in significance to that of', '["<u>Abu Hurayrah</u>","Imam Bukhari","Abu Sa''id al-Khudri","Abu Bakr as-Siddiq."]', '<u>Abu Hurayrah</u>.', '{"bold":[],"italic":[],"underline":["Abu Hurayrah"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('caij9hnfvpvqfzmbmch2pv8fy', 'Government', 'JAMB', null, 2020, null, 'In Nigeria, promotion of judges is the responsibility of the', null, '["Judicial Service Commission","Chief Justice of the Federation.","Attorney-General and Minister of Justice","National Judicial Council"]', 0, 'The Judicial Service Commission handles judges'' promotion.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In Nigeria, promotion of judges is the responsibility of the', '["<u>Judicial Service Commission</u>","Chief Justice of the Federation.","Attorney-General and Minister of Justice","National Judicial Council"]', '<u>Judicial Service Commission</u>.', '{"bold":[],"italic":[],"underline":["Judicial Service Commission"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('caikm2ktel6am4wgtbztxwd8i', 'Biology', 'JAMB', null, 1990, null, 'Which of the following are adaptations of animals to aquatic habitats?', null, '["Gills streamlined bodies and laurelings","Lateral line, streamlined bodies and lungs","Gills, scaly skin and lungs","Gills, streamlined bodies and spiracles"]', 1, 'Lateral line, streamlined bodies, and lungs are aquatic adaptations.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following are adaptations of animals to aquatic habitats?', '["Gills streamlined bodies and laurelings","<u>Lateral line, streamlined bodies and lungs</u>","Gills, scaly skin and lungs","Gills, streamlined bodies and spiracles"]', '<u>Lateral line, streamlined bodies, and lungs</u> are aquatic adaptations.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('caio95ve4jvogvn7okvhnfh84', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve |x² - 4| = 3x.', null, '["1, 4","1, -4","-1, 4","-1, -4"]', 0, 'x²-4 = 3x → x²-3x-4 = 0 → x = 4 or -1. Check x=-1: |1-4| = 3 ≠ -3. So x=4. Also x²-4 = -3x → x²+3x-4 = 0 → x = 1 or -4. Check x=1: |1-4| = 3 = 3. So x=1,4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve |x² - 4| = 3x.', '["1, 4","1, -4","-1, 4","-1, -4"]', '<u>x = 1, 4</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cairikun1h329or69h7xxuuez', 'General Mathematics', 'WAEC', null, 2020, null, 'The coordinates of A, B, C are (6, 3), (-3, 5), (4, -2) respectively. Find the area of triangle ABC.', null, '["24.5 sq units","28.5 sq units","32.5 sq units","36.5 sq units"]', 0, 'Area = ½|6(5+2) - 3(-2-3) + 4(3-5)| = ½|42 + 15 - 8| = 24.5.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The coordinates of A, B, C are (6, 3), (-3, 5), (4, -2) respectively. Find the area of triangle ABC.', '["24.5 sq units","28.5 sq units","32.5 sq units","36.5 sq units"]', 'Area = <u>24.5 sq units</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('caiydd78fb02siwxms39oob8y', 'Biology', 'JAMB', null, 2001, null, 'The transportation of oxygen and carbon(IV) oxide in mammals is carried out by', null, '["leucocytes","thrombocytes","phagocytes","erythrocytes"]', 3, 'Erythrocytes (red blood cells) transport O2 and CO2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The transportation of oxygen and carbon(IV) oxide in mammals is carried out by', '["leucocytes","thrombocytes","phagocytes","erythrocytes"]', '<u>Erythrocytes</u> transport O2 and CO2.', '{"bold":[],"italic":[],"underline":["erythrocytes"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('caiyqus19wzrvr8ju6zehf7h9', 'Chemistry', 'JAMB', null, 2004, null, 'Vulcanization involves the removal of', null, '["the single bond","a double bond","a polymer","a monomer"]', 1, 'Vulcanization removes double bonds in rubber.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Vulcanization involves the removal of', '["the single bond","a double bond","a polymer","a monomer"]', '<u>Removes a double bond</u>.', '{"bold":[],"italic":[],"underline":["a double bond"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('caj1baezxzq0j9awr50sinyxk', 'Biology', 'JAMB', null, 1992, null, 'The excretory organ in insect is the', null, '["kidney","malpighian tubule","flame cell","nephridium"]', 1, 'Malpighian tubules are excretory organs in insects.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The excretory organ in insect is the', '["kidney","<u>malpighian tubule</u>","flame cell","nephridium"]', '<u>Malpighian tubules</u> are excretory organs in insects.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('caj7f41ux5id0q912sk2dy02c', 'Biology', 'JAMB', null, 2001, null, 'The veins of the leaf are formed by the', null, '["vascular bundles","cambium cells","palisade tissue","spongy mesophyll Use the diagram below to answer questions 22 and 23"]', 0, 'vascular bundles is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The veins of the leaf are formed by the', '["<u>vascular bundles</u>","cambium cells","palisade tissue","spongy mesophyll Use the diagram below to answer questions 22 and 23"]', 'vascular bundles is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cajegh2a356njgr300q69y2nc', 'English Language', 'JAMB', null, 2020, null, 'The officer _____ that he was not supposed to talk to the press on the matter.', null, '["could have known","shall know","should have known","will know"]', 2, 'Should have known = past obligation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The officer _____ that he was not supposed to talk to the press on the matter.', '["could have known","shall know","should have known","will know"]', '<u>Should have known</u> = past duty.', '{"bold":[],"italic":[],"underline":["should have known"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cajejc949nofb1xvvqohtnkdq', 'Physics', 'JAMB', null, 2019, null, 'Which of the following statements is not correct about steel and soft iron?', null, '["Steel is more magnetized and soft iron","permanent magnets are usually made of steel","soft iron is more readily magnetized than steel","soft iron more readily loses its magnetism than steel"]', 0, 'Steel has low susceptibility and high retentivity; soft iron is more readily magnetized.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following statements is <b>not correct</b> about steel and soft iron?', '["<u>Steel is more magnetized and soft iron</u>","permanent magnets are usually made of steel","soft iron is more readily magnetized than steel","soft iron more readily loses its magnetism than steel"]', '<u>Steel has low susceptibility and high retentivity</u>; soft iron is more readily magnetized.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cajm9uixrblsm0sohj0hvcils', 'Chemistry', 'JAMB', null, 1986, null, '200cm³ of oxygen diffuse through a porous plug in 50 seconds. How long will 80cm³ of methane (CH4) take to diffuse through the same porous plug under the same conditions? [C=12, O=16, H=1]', null, '["20 sec","20 sec","14 sec","7 sec"]', 2, 'Rate O2 = 4 cm³/s; rate CH4 = 4 × √(32/16) = 5.66 cm³/s; time = 80/5.66 ≈ 14s.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '200cm³ of oxygen diffuse through a porous plug in 50 seconds. How long will 80cm³ of methane (CH4) take to diffuse through the same porous plug under the same conditions? [C=12, O=16, H=1]', '["20 sec","20 sec","14 sec","7 sec"]', 'Time = 80/5.66 ≈ <u>14s</u>.', '{"bold":[],"italic":[],"underline":["14 sec"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cajsk690do5ztg0psfuayp4jt', 'General Mathematics', 'JAMB', null, 2020, null, 'How many numbers greater than 4000 can be formed using the digits 2, 3, 4, 5, 6 without repetition?', null, '["72","84","96","108"]', 1, '4-digit numbers > 4000: 3 × 4 × 3 × 2 = 72. Key says 84.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'How many numbers greater than 4000 can be formed using the digits 2, 3, 4, 5, 6 without repetition?', '["72","84","96","108"]', 'Numbers = <u>84</u> (per key).', '{"bold":[],"italic":[],"underline":["84"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cajuevjr9q6a870b18hizfnm6', 'Biology', 'JAMB', null, 2002, null, 'The addition of lime to clay soil serve to', null, '["aid water retention","close up the texture","prevent water-logging","improve capillary action"]', 2, 'prevent water-logging is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The addition of lime to clay soil serve to', '["aid water retention","close up the texture","<u>prevent water-logging</u>","improve capillary action"]', 'prevent water-logging is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cajzl4jsyko6vv3pyal42f3uo', 'General Mathematics', 'JAMB', null, 2020, null, 'If log_a b = 3 and log_b a = 2 find log_a √b.', null, '["0.5","0.75","1","1.5"]', 1, 'log_a √b = (1/2) log_a b = 1.5. But log_a b = 3 and log_b a = 2 are inconsistent (product should be 1). Key says 0.75.', false, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'If log_a b = 3 and log_b a = 2 find log_a √b.', '["0.5","0.75","1","1.5"]', '(1/2)(3) = <u>1.5</u> (key says 0.75).', '{"bold":[],"italic":[],"underline":["0.75"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cak04pw0clchuq0aqnata7u8i', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'According to Paul in Corinthians, generosity produces', null, '["righteousness","salvation","the grace of God","thanksgiving to God."]', 3, 'Generosity produces thanksgiving to God.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to Paul in Corinthians, generosity produces', '["righteousness","salvation","the grace of God","<u>thanksgiving to God.</u>"]', '<u>Thanksgiving to God</u> (2 Corinthians 9:11).', '{"bold":[],"italic":[],"underline":["thanksgiving to God."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cakfxwz1x8hn5st9m4rvichuk', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The Qur''anic verse Q. 17:23 enjoins', null, '["worship of Allah alone","kindness to parents","kindness to neighbours","kindness to orphans"]', 0, 'It enjoins worship of Allah alone.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Qur''anic verse Q. 17:23 enjoins', '["<u>worship of Allah alone</u>","kindness to parents","kindness to neighbours","kindness to orphans"]', '<u>Worship of Allah alone</u> (Q. 17:23).', '{"bold":[],"italic":[],"underline":["worship of Allah alone"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cakjygcra981cs66y2zpjchyg', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the eccentricity of the ellipse 9x² + 16y² = 144.', null, '["√7/4","√7/3","5/4","3/4"]', 0, 'a² = 16, b² = 9; e = √(1 - 9/16) = √7/4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the eccentricity of the ellipse 9x² + 16y² = 144.', '["√7/4","√7/3","5/4","3/4"]', 'Eccentricity = <u>√7/4</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cakogowafhe6z9osskqx0iwyi', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Suratul-Kawthar concerns the Prophet''s', null, '["birthday","marriage to Khadijah","loss of his son","triumphant entry into Makkah."]', 2, 'Surat al-Kawthar concerns the loss of his son.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Suratul-Kawthar concerns the Prophet''s', '["birthday","marriage to Khadijah","<u>loss of his son</u>","triumphant entry into Makkah."]', '<u>Loss of his son</u>.', '{"bold":[],"italic":[],"underline":["loss of his son"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cakytniagsjdesj1lkxtge0ts', 'General Mathematics', 'JAMB', null, 2020, null, 'cos 20° cos 40° cos 80° =', null, '["1/8","1/6","1/4","1/2"]', 0, 'Product = 1/8.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'cos 20° cos 40° cos 80° =', '["1/8","1/6","1/4","1/2"]', 'Value = <u>1/8</u>.', '{"bold":[],"italic":[],"underline":["1/8"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('calnug93hghxc4dmaix8ewfxh', 'General Mathematics', 'JAMB', null, 2020, null, 'Find ∫ dx/(x√(x² - 4)).', null, '["½sec⁻¹(","x","/2) + C","½sec⁻¹(x/2) + C","sec⁻¹(","x","/2) + C","sec⁻¹(x/2) + C"]', 0, 'Standard integral: ½sec⁻¹(|x|/2) + C.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find ∫ dx/(x√(x² - 4)).', '["½sec⁻¹(","x","/2) + C","½sec⁻¹(x/2) + C","sec⁻¹(","x","/2) + C","sec⁻¹(x/2) + C"]', 'Integral = <u>½sec⁻¹(|x|/2) + C</u>.', '{"bold":[],"italic":[],"underline":["½sec⁻¹(|x|/2) + C"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('calpfhtrkm3xwhf3waulbq2qx', 'General Mathematics', 'WAEC', null, 2020, null, 'In a town of 120 people: 60 read novels, 50 read biographies, 30 read both. How many read at least one?', null, '["80","90","100","110"]', 0, 'At least one = 60 + 50 - 30 = 80.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In a town of 120 people: 60 read novels, 50 read biographies, 30 read both. How many read at least one?', '["80","90","100","110"]', 'At least one = <u>80</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('caltlae658wtvbdbrf6og9m0o', 'Chemistry', 'JAMB', null, 1996, null, 'CH3CH2CH2CH2Br + alc.KOH → CH3CH=CHCH3 + CH3CH2CH=CH2. The above reaction is an example of', null, '["dehydration","dehydrohalogenation","neutralization","a fission reaction"]', 1, 'Removal of HBr = dehydrohalogenation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'CH3CH2CH2CH2Br + alc.KOH → CH3CH=CHCH3 + CH3CH2CH=CH2. The above reaction is an example of', '["dehydration","dehydrohalogenation","neutralization","a fission reaction"]', '<u>Dehydrohalogenation</u>.', '{"bold":[],"italic":[],"underline":["dehydrohalogenation"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('caluauwg34il7oikz7oncsnwk', 'General Mathematics', 'JAMB', null, 2020, null, 'Find d/dx(ln(1 + eˣ)).', null, '["eˣ/(1 + eˣ)","1/(1 + eˣ)","1/(eˣ + 1)","eˣ/(eˣ + 1)"]', 0, 'dy/dx = eˣ/(1 + eˣ).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find d/dx(ln(1 + eˣ)).', '["eˣ/(1 + eˣ)","1/(1 + eˣ)","1/(eˣ + 1)","eˣ/(eˣ + 1)"]', 'dy/dx = <u>eˣ/(1 + eˣ)</u>.', '{"bold":[],"italic":[],"underline":["eˣ/(1 + eˣ)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cam0e5veu5fcin0qjfupaalfb', 'Government', 'JAMB', null, 2020, null, 'Where the constitution is supreme, unconstitutional acts of the executive and the legislature can be checked by the courts through', null, '["recall","judicial review","vote of no confidence","impeachment"]', 1, 'Judicial review allows courts to declare unconstitutional acts of the executive and legislature null and void.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Where the constitution is supreme, unconstitutional acts of the executive and the legislature can be checked by the courts through', '["recall","<u>judicial review</u>","vote of no confidence","impeachment"]', '<u>Judicial review</u> is the check on unconstitutional acts.', '{"bold":[],"italic":[],"underline":["judicial review"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cam6823ve1s4xt6sczastdfeh', 'Chemistry', 'JAMB', null, 1987, null, 'An isotope has an atomic number of 17 and a mass number of 36. Which of the following gives the correct number of neutrons and protons in an atom of the isotope?', null, '["Neutrons 19, Protons 17","Neutrons 17, Protons 36","Neutrons 19, Protons 17","Neutrons 36, Protons 17"]', 2, 'Protons = atomic number = 17; neutrons = mass number - atomic number = 36 - 17 = 19.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An isotope has an atomic number of 17 and a mass number of 36. Which of the following gives the correct number of neutrons and protons in an atom of the isotope?', '["Neutrons 19, Protons 17","Neutrons 17, Protons 36","Neutrons 19, Protons 17","Neutrons 36, Protons 17"]', 'Protons = 17; neutrons = <u>19</u>.', '{"bold":[],"italic":[],"underline":["Neutrons 19, Protons 17"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cam6ppbn08zja35l1rsarfugq', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the determinant of [[1, 2, 3], [4, 5, 6], [7, 8, 10]].', null, '["-3","-6","0","3"]', 0, 'det = 1(50-48) - 2(40-42) + 3(32-35) = 2 + 4 - 9 = -3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the determinant of [[1, 2, 3], [4, 5, 6], [7, 8, 10]].', '["-3","-6","0","3"]', 'det = <u>-3</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cam884ij3g6wxlcan1j3w9nvr', 'Islamic Religious Studies', 'JAMB', null, 2011, null, 'One of the conditions that make prayer obligatory on believers is', null, '["social status","reciting the Qur''an with proper Tajweed","following pious Imam","attainment of maturity"]', 3, 'Maturity (bulugh) is a condition for prayer obligation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One of the conditions that make prayer obligatory on believers is', '["social status","reciting the Qur''an with proper Tajweed","following pious Imam","<u>attainment of maturity</u>"]', '<u>Maturity (bulugh)</u> is a condition for prayer obligation.', '{"bold":[],"italic":[],"underline":["attainment of maturity"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('can12bkwr9l2cw54c68djype4', 'General Mathematics', 'JAMB', null, 2020, null, 'If n(A) = 10, n(B) = 12, n(A ∩ B) = 4, find n(A × B).', null, '["120","80","48","100"]', 0, 'n(A × B) = n(A) × n(B) = 120.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If n(A) = 10, n(B) = 12, n(A ∩ B) = 4, find n(A × B).', '["120","80","48","100"]', 'n(A × B) = <u>120</u>.', '{"bold":[],"italic":[],"underline":["120"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('canaxa1pquihvjj94kbm5w3b4', 'Chemistry', 'JAMB', null, 1995, null, 'In the reaction IO3⁻ + 5I⁻ + 6H⁺ → 3I2 + 3H2O, the oxidizing agent is', null, '["H⁺","I⁻","IO3⁻","I2"]', 2, 'IO3⁻ is reduced (I goes from +5 to 0).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the reaction IO3⁻ + 5I⁻ + 6H⁺ → 3I2 + 3H2O, the oxidizing agent is', '["H⁺","I⁻","IO3⁻","I2"]', '<u>IO3⁻ is reduced</u>, so it is the oxidizing agent.', '{"bold":[],"italic":[],"underline":["IO3⁻"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cani2n6up72e4j2arpqv15j86', 'Chemistry', 'JAMB', null, 1983, null, 'Manganese(IV) oxide reacts with concentrated hydrochloric acid according to the equation MnO2 + xHCl → MnCl2 + Cl2 + yH2O. x and y are', null, '["2 and 5 respectively","2 and 4 respectively","4 and 2 respectively","4 and 1 respectively","4 and 3 respectively"]', 2, 'Balancing: MnO2 + 4HCl → MnCl2 + Cl2 + 2H2O; x=4, y=2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Manganese(IV) oxide reacts with concentrated hydrochloric acid according to the equation MnO2 + xHCl → MnCl2 + Cl2 + yH2O. x and y are', '["2 and 5 respectively","2 and 4 respectively","4 and 2 respectively","4 and 1 respectively","4 and 3 respectively"]', '<u>x=4, y=2</u>.', '{"bold":[],"italic":[],"underline":["4 and 2 respectively"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('canio0wjvd0v63djnr87xvjsi', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the median of 1, 3, 5, 7, 9, 11, 13.', null, '["7","6","7.5","8"]', 0, 'Middle value = 7.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the median of 1, 3, 5, 7, 9, 11, 13.', '["7","6","7.5","8"]', 'Median = <u>7</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cansac3yxbj917nu3ijwwtiz3', 'Biology', 'JAMB', null, 2003, null, 'A limiting factor in a plant population near a chemical factory is likely to be', null, '["humidity","pH","wind","light"]', 1, 'pH is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A limiting factor in a plant population near a chemical factory is likely to be', '["humidity","<u>pH</u>","wind","light"]', 'pH is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('canu36kz6migsorquwsp3zvgy', 'General Mathematics', 'JAMB', null, 2020, null, 'If A² = I, then A is:', null, '["Involutory","Idempotent","Nilpotent","Orthogonal"]', 0, 'A² = I → involutory.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If A² = I, then A is:', '["Involutory","Idempotent","Nilpotent","Orthogonal"]', '<u>Involutory</u>.', '{"bold":[],"italic":[],"underline":["Involutory"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('canxanpq3vijs8qtdw0dfq52w', 'Chemistry', 'JAMB', null, 1995, null, 'Which of the following is a <b>physical change</b>?', null, '["The bubbling of chlorine into water","The bubbling of chlorine into a jar containing hydrogen","The dissolution of sodium chloride in water","The passing of steam over heated iron"]', 2, 'Dissolution of NaCl is a physical change.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is a <b>physical change</b>?', '["The bubbling of chlorine into water","The bubbling of chlorine into a jar containing hydrogen","The dissolution of sodium chloride in water","The passing of steam over heated iron"]', '<u>Dissolution of NaCl</u> is a physical change.', '{"bold":["physical change"],"italic":[],"underline":["The dissolution of sodium chloride in water"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('canycnt9sjc2vj6ptnfcta7ef', 'Chemistry', 'JAMB', null, 1990, null, 'In the reaction 2HI(g) ⇌ H2(g) + I2(g), ΔH = 10 kJ, the concentration of iodine in the equilibrium mixture can be increased by', null, '["raising the pressure","lowering the pressure","raising the temperature","adding a catalyst"]', 2, 'Endothermic reaction favours higher temperature for product formation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the reaction 2HI(g) ⇌ H2(g) + I2(g), ΔH = 10 kJ, the concentration of iodine in the equilibrium mixture can be increased by', '["raising the pressure","lowering the pressure","raising the temperature","adding a catalyst"]', '<u>Raising the temperature</u> favours I2 formation.', '{"bold":[],"italic":[],"underline":["raising the temperature"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cao0nbw3giron2n8lan011ohl', 'Biology', 'JAMB', null, 2003, null, 'Spines and shells on animals are adaptations for', null, '["physical defence","camouflage","chemical defence","mimicry"]', 0, 'Spines and shells are for physical defence.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Spines and shells on animals are adaptations for', '["physical defence","camouflage","chemical defence","mimicry"]', '<u>Physical defence</u>.', '{"bold":[],"italic":[],"underline":["physical defence"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cao1pcd1fmbwideowurwukuqd', 'General Mathematics', 'JAMB', null, 2020, null, 'The standard deviation of 5 numbers is 3. If each is doubled, find the new SD.', null, '["6","3","12","9"]', 0, 'SD doubles too: 6.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The standard deviation of 5 numbers is 3. If each is doubled, find the new SD.', '["6","3","12","9"]', 'New SD = <u>6</u>.', '{"bold":[],"italic":[],"underline":["6"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cao28gnhc613qsorhchlmvsvd', 'English Language', 'JAMB', null, 2020, null, 'After two years of courtship, Jide is finally _____ Ngozi next Sunday.', null, '["being married to","marrying","married to","being married by"]', 1, 'Active: "Jide is marrying Ngozi".', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'After two years of courtship, Jide is finally _____ Ngozi next Sunday.', '["being married to","marrying","married to","being married by"]', '<u>Marrying</u> = active.', '{"bold":[],"italic":[],"underline":["marrying"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cao3ouli7hbxmhg3au2hzbw4f', 'General Mathematics', 'JAMB', null, 2020, null, 'If the lines x + 2y = 5, 3x - y = 4, and kx + 5y = 8 are concurrent, find k.', null, '["5","1/13","7","8"]', 1, 'Lines 1 and 2 meet at (13/7, 11/7); k(13/7) + 5(11/7) = 8 → k = 1/13.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'If the lines x + 2y = 5, 3x - y = 4, and kx + 5y = 8 are concurrent, find k.', '["5","1/13","7","8"]', 'Lines 1 and 2 meet at (13/7, 11/7); k(13/7) + 5(11/7) = 8 → k = 1/13.', '{"bold":[],"italic":[],"underline":["6"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cao7osef6enqbhzzcdcv1yo9o', 'General Mathematics', 'WAEC', null, 2020, null, 'Evaluate (12 + 15) × (9 - 4) (mod 11).', null, '["6","3","8","9"]', 1, '27 × 5 = 135 = 12×11 + 3, so the result is 3 (mod 11).', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Evaluate (12 + 15) × (9 - 4) (mod 11).', '["6","3","8","9"]', '27 × 5 = 135 = 12×11 + 3, so the result is 3 (mod 11).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cao93a6kbsrfbsg8a485i9uxl', 'Biology', 'JAMB', null, 2003, null, 'The most important hormone that induces the <b>ripening of fruit</b> is', null, '["Cytokinin","Indole acetic acid","Ethylene","Gibberellin"]', 2, 'Ethylene induces fruit ripening.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The most important hormone that induces the <b>ripening of fruit</b> is', '["Cytokinin","Indole acetic acid","Ethylene","Gibberellin"]', '<u>Ethylene</u> ripens fruit.', '{"bold":["ripening of fruit"],"italic":[],"underline":["Ethylene"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('caofzya974unalyl30b259aph', 'Biology', 'JAMB', null, 1994, null, 'Which of the following is NOT involved in the transport of substances in the body?', null, '["Lymph","Plasma","Leucocytes","Erythrocytes"]', 2, 'Leucocytes are not involved in transport.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is <b>NOT</b> involved in the transport of substances in the body?', '["Lymph","Plasma","<u>Leucocytes</u>","Erythrocytes"]', '<u>Leucocytes are not involved in transport</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('caov4nvxl5vrualofllmoio8r', 'Islamic Religious Studies', 'JAMB', null, 2002, null, 'If a husband divorces his wife before the consumption of the marriage, it is considered', null, '["revocable","irrevocable","redeemable","abominable"]', 1, 'Divorce before consummation is irrevocable (talaq bain).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If a husband divorces his wife before the consumption of the marriage, it is considered', '["revocable","<u>irrevocable</u>","redeemable","abominable"]', 'Divorce before consummation is <u>irrevocable</u> (talaq bain).', '{"bold":[],"italic":[],"underline":["irrevocable"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cap371yr1tmkelp2fp07f679j', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the median of 1, 3, 5, 7, 9, 11, 13.', null, '["7","6","7.5","8"]', 0, 'Middle value = 7.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the median of 1, 3, 5, 7, 9, 11, 13.', '["7","6","7.5","8"]', 'Median = <u>7</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cap4akqg1159g2w2sjz3iwz8i', 'Islamic Religious Studies', 'JAMB', null, 2008, null, 'Qiyas in Islamic law refers to', null, '["Measurement","Analogical deduction","Intelligent work","evaluation"]', 1, 'Qiyas means analogical deduction in Islamic law.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Qiyas in Islamic law refers to', '["Measurement","<u>Analogical deduction</u>","Intelligent work","evaluation"]', '<u>Qiyas</u> means analogical deduction in Islamic law.', '{"bold":[],"italic":[],"underline":["Analogical deduction"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cap5kjs17wv2dsbrexlfst4qu', 'Government', 'JAMB', null, 2020, null, 'The primary function of the Code of Conduct Bureau is to', null, '["Receive declaration of assets","Ensure due process by public officers","Ensure minimum standard of morality","Retain custody of declarations."]', 2, 'The CCB ensures minimum standards of morality.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The primary function of the Code of Conduct Bureau is to', '["Receive declaration of assets","Ensure due process by public officers","<u>Ensure minimum standard of morality</u>","Retain custody of declarations."]', '<u>Ensure minimum standard of morality</u>.', '{"bold":[],"italic":[],"underline":["Ensure minimum standard of morality"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('capefry57zg78xtszb3ksuf2n', 'General Mathematics', 'JAMB', null, 2020, null, 'The sum of the first n terms of a sequence is 2n² + 3n. Find the nth term.', null, '["4n + 1","4n - 1","4n + 5","4n - 5"]', 0, 'Tₙ = Sₙ - Sₙ₋₁ = 2n² + 3n - 2(n-1)² - 3(n-1) = 4n + 1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The sum of the first n terms of a sequence is 2n² + 3n. Find the nth term.', '["4n + 1","4n - 1","4n + 5","4n - 5"]', 'Tₙ = <u>4n + 1</u>.', '{"bold":[],"italic":[],"underline":["4n + 1"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('capkw8ijs8036kk9jg1uwx1yh', 'Chemistry', 'JAMB', null, 2004, null, 'Which of the following gases can be collected by the method of <b>downward delivery</b>?', null, '["Oxygen","Hydrogen","Chlorine","Ammonia"]', 2, 'Chlorine (denser than air) is collected by downward delivery.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following gases can be collected by the method of <b>downward delivery</b>?', '["Oxygen","Hydrogen","Chlorine","Ammonia"]', '<u>Chlorine</u> by downward delivery.', '{"bold":["downward delivery"],"italic":[],"underline":["Chlorine"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('capo34kq96m4lqtz1vt6avihi', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'God promised the faithless Israelites that if they repented of their sins and returned to Him, He would', null, '["fill them with His knowledge","deliver their enemies into their hands","give them shepherds after His own heart","give them favour in the sight of the nations."]', 2, 'God promised shepherds after His own heart.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'God promised the faithless Israelites that if they repented of their sins and returned to Him, He would', '["fill them with His knowledge","deliver their enemies into their hands","<u>give them shepherds after His own heart</u>","give them favour in the sight of the nations."]', '<u>Give them shepherds after His own heart</u> (Jeremiah 3:12-15).', '{"bold":[],"italic":[],"underline":["give them shepherds after His own heart"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('capv5b1evhuv7sycseem3ooyx', 'Biology', 'JAMB', null, 1997, null, 'Toads and lizards in an ecosystem depend on a limited quantity of food. This is an example of', null, '["parasitism","intraspecific competition","predation","interspecific competition."]', 3, 'interspecific competition. is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Toads and lizards in an ecosystem depend on a limited quantity of food. This is an example of', '["parasitism","intraspecific competition","predation","<u>interspecific competition.</u>"]', 'interspecific competition. is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('caq99v8jdt9uz5jzn4i7eiwsz', 'Chemistry', 'JAMB', null, 1991, null, 'How many grams of bromine will be required to completely react with 10g of propyne? [C=12, H=1, Br=80]', null, '["20g","40g","60g","80g"]', 1, 'Moles propyne = 10/40 = 0.25; Br2 = 0.5 mol = 80g. Key says 40.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'How many grams of bromine will be required to completely react with 10g of propyne? [C=12, H=1, Br=80]', '["20g","40g","60g","80g"]', 'Br2 = 0.5 mol = <u>80g</u> (key says 40).', '{"bold":[],"italic":[],"underline":["40g"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('caqfy7saxr4i9x53ezk5slctk', 'Chemistry', 'JAMB', null, 1996, null, 'Which of the following ions is a <b>pollutant in drinking water</b> even in trace amounts?', null, '["Ca²⁺","Hg²⁺","Mg²⁺","Fe²⁺"]', 1, 'Hg²⁺ is toxic even in trace amounts.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following ions is a <b>pollutant in drinking water</b> even in trace amounts?', '["Ca²⁺","Hg²⁺","Mg²⁺","Fe²⁺"]', '<u>Hg²⁺ is toxic</u>.', '{"bold":["pollutant in drinking water"],"italic":[],"underline":["Hg²⁺"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('caqge71p604quor5zvw7q4l7c', 'Biology', 'JAMB', null, 1995, null, 'When a healthy shoot of a flowering plant is illuminated from one side, auxins accumulate on the', null, '["non-illuminated side of the shoot","illuminated side of the shoot","upper side of the shoot","lower side of the shoot. Use the diagram below to answer questions 21 and 22."]', 0, 'Auxin accumulates on the shaded side of a shoot, promoting unequal growth and bending toward light.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When a healthy shoot of a flowering plant is illuminated from one side, auxins accumulate on the', '["<u>non-illuminated side of the shoot</u>","illuminated side of the shoot","upper side of the shoot","lower side of the shoot. Use the diagram below to answer questions 21 and 22."]', 'Auxin accumulates on the shaded side of a shoot, promoting unequal growth and bending toward light.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('caqi0955a3l90cr6skkzaq5jm', 'Government', 'JAMB', null, 2020, null, 'Under the 1999 Constitution, the power to declare war is vested in the', null, '["National Security Council.","legislature","executive","National Council of States"]', 2, 'The executive declares war (with legislative approval).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Under the 1999 Constitution, the power to declare war is vested in the', '["National Security Council.","legislature","<u>executive</u>","National Council of States"]', '<u>Executive</u>.', '{"bold":[],"italic":[],"underline":["executive"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('caql34yw6whbou6je0bxzn93k', 'Biology', 'JAMB', null, 2003, null, 'The stunted growth of a leguminous plant suffering from <b>nitrogen deficiency</b> may be corrected by inoculating the soil with', null, '["saprophytic bacteria","rhizobium","denitrifying bacteria","nitrosomonas"]', 1, 'Rhizobium fixes nitrogen in legume roots.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The stunted growth of a leguminous plant suffering from <b>nitrogen deficiency</b> may be corrected by inoculating the soil with', '["saprophytic bacteria","rhizobium","denitrifying bacteria","nitrosomonas"]', '<u>Rhizobium</u> fixes nitrogen.', '{"bold":["nitrogen deficiency"],"italic":[],"underline":["rhizobium"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('caqzfrkxvbuk7wxkop0hf4vy2', 'Chemistry', 'JAMB', null, 1996, null, 'Which of the following equilibria is <b>unaffected by a pressure change</b>?', null, '["2NaCl ⇌ 2Na + Cl2","H2 + I2 ⇌ 2HI","2O3 ⇌ 3O2","2NO2 ⇌ N2O4"]', 1, 'Equal gas moles on both sides.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following equilibria is <b>unaffected by a pressure change</b>?', '["2NaCl ⇌ 2Na + Cl2","H2 + I2 ⇌ 2HI","2O3 ⇌ 3O2","2NO2 ⇌ N2O4"]', '<u>H2 + I2 ⇌ 2HI</u>.', '{"bold":["unaffected by a pressure change"],"italic":[],"underline":["H2 + I2 ⇌ 2HI"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('car5jy5xdbefdj78b1el2jc5j', 'Chemistry', 'JAMB', null, 1991, null, 'One of the advantages of detergents over soap is that detergents', null, '["are easier to manufacture","foam more than soap","form soluble salts with hard water","are able to deter germs more than soap"]', 2, 'Detergents form soluble salts with hard water (no scum).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One of the advantages of detergents over soap is that detergents', '["are easier to manufacture","foam more than soap","form soluble salts with hard water","are able to deter germs more than soap"]', '<u>Detergents form soluble salts with hard water</u>.', '{"bold":[],"italic":[],"underline":["form soluble salts with hard water"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('car70c5nq4rm6ann7aevxw8sb', 'Biology', 'JAMB', null, 1988, null, 'The main function of the choroid is', null, '["protection of the eye ball","transmission of light","supply of nutrients to tissues of the eye","converging light"]', 2, 'The choroid supplies nutrients to eye tissues.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The main function of the <b>choroid</b> is', '["protection of the eye ball","transmission of light","<u>supply of nutrients to tissues of the eye</u>","converging light"]', 'The choroid <u>supplies nutrients to eye tissues</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cargza5771i89j89mmf8gq3d2', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the equation of the circle with a diameter from (1, 2) to (3, 4).', null, '["x² + y² - 4x - 6y + 11 = 0","x² + y² - 4x - 6y + 13 = 0","x² + y² - 4x - 6y + 9 = 0","x² + y² - 4x - 6y + 7 = 0"]', 0, 'Center (2, 3), r² = 2; equation: (x-2)² + (y-3)² = 2 → x² + y² - 4x - 6y + 11 = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the equation of the circle with a diameter from (1, 2) to (3, 4).', '["x² + y² - 4x - 6y + 11 = 0","x² + y² - 4x - 6y + 13 = 0","x² + y² - 4x - 6y + 9 = 0","x² + y² - 4x - 6y + 7 = 0"]', 'Equation: <u>x² + y² - 4x - 6y + 11 = 0</u>.', '{"bold":[],"italic":[],"underline":["x² + y² - 4x - 6y + 11 = 0"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('carh6p6wicc3u41y8tmk3sst7', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the angle between the circles x² + y² = 4 and (x - 2)² + y² = 4.', null, '["120°","60°","90°","30°"]', 0, 'Centers distance 2; radii 2, 2; cos θ = (4+4-4)/(2·2·2) = 1/2 → θ = 60°. Angle between circles = 120°.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the angle between the circles x² + y² = 4 and (x - 2)² + y² = 4.', '["120°","60°","90°","30°"]', 'Angle = <u>120°</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('carlg2h04cgii588ujugzzjv7', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'David''s victory over the Amalekites who raided Ziklag was due to', null, '["the great army that followed him to fight the Amalekites","his swearing to the Egyptian servant of the Amalekites not to kill or harm him","his prayer in seeking the approval of God before pursuing them","the fact that David was a mighty man in battle."]', 2, 'He sought God''s approval before pursuing them.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'David''s victory over the Amalekites who raided Ziklag was due to', '["the great army that followed him to fight the Amalekites","his swearing to the Egyptian servant of the Amalekites not to kill or harm him","<u>his prayer in seeking the approval of God before pursuing them</u>","the fact that David was a mighty man in battle."]', '<u>His prayer in seeking the approval of God before pursuing them</u> (1 Samuel 30:8).', '{"bold":[],"italic":[],"underline":["his prayer in seeking the approval of God before pursuing them"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('carsa2jgu30iawi70ab5gn6sn', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the range of m so that x² + (m - 3)x + m = 0 has real roots.', null, '["m ≤ 1 or m ≥ 9","m ≤ -1 or m ≥ 9","m ≤ 1 or m ≥ 8","m ≤ -2 or m ≥ 7"]', 0, 'Discriminant (m-3)² - 4m ≥ 0 → m² - 10m + 9 ≥ 0 → (m-1)(m-9) ≥ 0 → m ≤ 1 or m ≥ 9.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the range of m so that x² + (m - 3)x + m = 0 has real roots.', '["m ≤ 1 or m ≥ 9","m ≤ -1 or m ≥ 9","m ≤ 1 or m ≥ 8","m ≤ -2 or m ≥ 7"]', 'Range = <u>m ≤ 1 or m ≥ 9</u>.', '{"bold":[],"italic":[],"underline":["m ≤ 1 or m ≥ 9"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cartsmlwrkzg14tsjjqpwboz7', 'General Mathematics', 'WAEC', null, 2020, null, 'If A = {x : x is a factor of 12}, B = {x : x is a factor of 18}, find A ∩ B.', null, '["{1,2,3,6}","{1,2,3,4,6}","{1,2,3,6,9}","{1,2,3}"]', 0, 'A = {1,2,3,4,6,12}; B = {1,2,3,6,9,18}; A ∩ B = {1,2,3,6}.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If A = {x : x is a factor of 12}, B = {x : x is a factor of 18}, find A ∩ B.', '["{1,2,3,6}","{1,2,3,4,6}","{1,2,3,6,9}","{1,2,3}"]', 'A ∩ B = <u>{1,2,3,6}</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('carzcx9zfu9qr2ymll4g5173v', 'General Mathematics', 'JAMB', null, 2020, null, 'On {0,1,2}, a*b = (a + b) mod 3. What is the identity?', null, '["0","1","2","none"]', 0, 'a*0 = a mod 3 = a → identity = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'On {0,1,2}, a*b = (a + b) mod 3. What is the identity?', '["0","1","2","none"]', 'Identity = <u>0</u>.', '{"bold":[],"italic":[],"underline":["0"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cas02blx7r72gh1epau6e90m0', 'English Language', 'JAMB', null, 2020, null, 'The African extended system gives security to _____ members.', null, '["his","her","its","their"]', 2, 'Its agrees with singular "system".', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The African extended system gives security to _____ members.', '["his","her","its","their"]', 'Its agrees with "system".', '{"bold":[],"italic":[],"underline":["its"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cas2odfeahh1m1kwsah0ef0sl', 'General Mathematics', 'JAMB', null, 2020, null, 'The set of all subsets of a set is called:', null, '["Power set","Universal set","Complement","Union"]', 0, 'The set of all subsets is the power set.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The set of all subsets of a set is called:', '["Power set","Universal set","Complement","Union"]', '<u>Power set</u>.', '{"bold":[],"italic":[],"underline":["Power set"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cascrth6vsp0prshk7u8lop0k', 'General Mathematics', 'JAMB', null, 2020, null, 'If y = (eˣ + e⁻ˣ)/(eˣ - e⁻ˣ), find dy/dx.', null, '["-4/(eˣ - e⁻ˣ)²","4/(eˣ - e⁻ˣ)²","(eˣ - e⁻ˣ)/(eˣ + e⁻ˣ)","(eˣ + e⁻ˣ)/(eˣ - e⁻ˣ)"]', 0, 'y = coth x; dy/dx = -csch²x = -4/(eˣ - e⁻ˣ)².', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If y = (eˣ + e⁻ˣ)/(eˣ - e⁻ˣ), find dy/dx.', '["-4/(eˣ - e⁻ˣ)²","4/(eˣ - e⁻ˣ)²","(eˣ - e⁻ˣ)/(eˣ + e⁻ˣ)","(eˣ + e⁻ˣ)/(eˣ - e⁻ˣ)"]', 'dy/dx = <u>-4/(eˣ - e⁻ˣ)²</u>.', '{"bold":[],"italic":[],"underline":["-4/(eˣ - e⁻ˣ)²"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('casn995v2jw4h3hk3vk0kusn5', 'Chemistry', 'JAMB', null, 1986, null, 'The reaction Mg + H2O → MgO + H2 takes place only in the presence of', null, '["excess Mg ribbon","excess cold water","very hot water","steam"]', 3, 'Mg reacts with steam, not cold water.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The reaction Mg + H2O → MgO + H2 takes place only in the presence of', '["excess Mg ribbon","excess cold water","very hot water","steam"]', '<u>Mg reacts with steam</u>.', '{"bold":[],"italic":[],"underline":["steam"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('caso20rz7r44clm9lwtw1gori', 'Biology', 'JAMB', null, 1999, null, 'In which of the following organisms does each cell combine the function of nutrition, reproduction and growth?', null, '["Rhizopus","Dryopteris","Brachymenium","Spirogyra"]', 3, 'Spirogyra is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In which of the following organisms does each cell combine the function of nutrition, reproduction and growth?', '["Rhizopus","Dryopteris","Brachymenium","<u>Spirogyra</u>"]', 'Spirogyra is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('casxkep64qed2ol5uc9jjw3xi', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve the quartic equation x⁴ - 10x² + 9 = 0', null, '["±1, ±3","±1, ±9","±3, ±√3","±1, ±√3"]', 0, 'y² - 10y + 9 = 0 → y = 1 or 9 → x = ±1, ±3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve the quartic equation x⁴ - 10x² + 9 = 0', '["±1, ±3","±1, ±9","±3, ±√3","±1, ±√3"]', '<u>x = ±1, ±3</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cat29i5rnovn8l9u2shpon3mv', 'English Language', 'JAMB', null, 2020, null, 'The officer _____ that he was not supposed to talk to the press on the matter.', null, '["could have known","should have known","shall know","will know"]', 1, 'Should have known = past obligation/expectation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The officer _____ that he was not supposed to talk to the press on the matter.', '["could have known","should have known","shall know","will know"]', '<u>Should have known</u> = past duty.', '{"bold":[],"italic":[],"underline":["should have known"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cat2encls6iuiiz8icj2t0r8f', 'Chemistry', 'JAMB', null, 1993, null, 'During the electrolysis of a salt of metal M, a current of 0.05A flows for 32 minutes 10 seconds and deposits 0.325g of M. What is the charge of the metal ion? [M=65, F=96500 C mol⁻¹]', null, '["1","2","3","4"]', 1, 'Q = 0.05 × 1930 = 96.5C; moles e⁻ = 0.001; moles M = 0.005; n = 0.001/0.005 = 0.2. Key says 2.', false, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'During the electrolysis of a salt of metal M, a current of 0.05A flows for 32 minutes 10 seconds and deposits 0.325g of M. What is the charge of the metal ion? [M=65, F=96500 C mol⁻¹]', '["1","2","3","4"]', 'Charge = <u>2</u> (per key).', '{"bold":[],"italic":[],"underline":["2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cat2p4ukowte2pdc421n4f1c1', 'Chemistry', 'JAMB', null, 1995, null, 'Which of the following tests will completely identify any one of sulphur(IV) oxide, hydrogen, carbon(IV) oxide and nitrogen(II) oxide?', null, '["pass each gas into water and test with blue litmus paper","pass each gas into lime water","expose each gas to atmospheric air","pass each gas to concentrated tetraoxosulphate(VI) acid"]', 2, 'Exposure to air gives distinct colour changes.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following tests will completely identify any one of sulphur(IV) oxide, hydrogen, carbon(IV) oxide and nitrogen(II) oxide?', '["pass each gas into water and test with blue litmus paper","pass each gas into lime water","expose each gas to atmospheric air","pass each gas to concentrated tetraoxosulphate(VI) acid"]', '<u>Expose to atmospheric air</u> gives distinct changes.', '{"bold":[],"italic":[],"underline":["expose each gas to atmospheric air"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('catg6sj6aga2dfu690tz96xai', 'Physics', 'JAMB', null, 2021, null, 'If the half-life is 5.0×10⁶s and a sample of nuclear material contains 3×10⁻⁶g, calculate the decay constant', null, '["2.5×10⁻¹s","1.4×10⁻⁷s","1.8×10⁻⁶s","15s"]', 1, 'λ = 0.693/T½ = 0.693/(5.0×10⁶) = 1.4×10⁻⁷ s⁻¹.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If the half-life is 5.0×10⁶s and a sample of nuclear material contains 3×10⁻⁶g, calculate the decay constant', '["2.5×10⁻¹s","<u>1.4×10⁻⁷s</u>","1.8×10⁻⁶s","15s"]', 'λ = 0.693/T½ = <u>1.4×10⁻⁷ s⁻¹</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('catker8v2fyea8idvcow9lz7k', 'Islamic Religious Studies', 'JAMB', null, 2011, null, 'Prophet Muhammad (SAW) did not hand-over the Glorious Qur''an to his companions in an arranged form and in a single written volume because', null, '["he did not want only the Quraish to inherit the book","the revelation did not come in one piece but at intervals","many tribes would want to take over its distribution","there was no need for it"]', 1, 'The Qur''an was revealed at intervals, not in one piece.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Prophet Muhammad (SAW) did not hand-over the Glorious Qur''an to his companions in an arranged form and in a single written volume because', '["he did not want only the Quraish to inherit the book","<u>the revelation did not come in one piece but at intervals</u>","many tribes would want to take over its distribution","there was no need for it"]', 'The Qur''an was <u>revealed at intervals</u>, not in one piece.', '{"bold":[],"italic":[],"underline":["the revelation did not come in one piece but at intervals"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('catzyzc1u2eo8jh7295vittys', 'General Mathematics', 'JAMB', null, 2020, null, 'The line y = x + 2 meets the circle x² + y² = 4 at points A and B. Find the equation of the circle on AB as diameter.', null, '["x² + y² + 2x - 2y = 0","x² + y² - 2x + 2y = 0","x² + y² + 2x + 2y = 0","x² + y² - 2x - 2y = 0"]', 0, 'A(-2,0), B(0,2); center (-1,1); radius √2; equation: x² + y² + 2x - 2y = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The line y = x + 2 meets the circle x² + y² = 4 at points A and B. Find the equation of the circle on AB as diameter.', '["x² + y² + 2x - 2y = 0","x² + y² - 2x + 2y = 0","x² + y² + 2x + 2y = 0","x² + y² - 2x - 2y = 0"]', 'Equation: <u>x² + y² + 2x - 2y = 0</u>.', '{"bold":[],"italic":[],"underline":["x² + y² + 2x - 2y = 0"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cau4s1iox3vs6l3swwcyq3zxa', 'Physics', 'JAMB', null, 2019, null, 'A house is supplied with a 240V a.c mains. To operate a doorbell rated at 8V, a transformer is used. If the number of turns in the primary coil is 900, calculate the number of turns in the secondary coil.', null, '["30","240","248","450"]', 0, 'Ns/Np = Vs/Vp = 8/240. Ns = 900 × 8/240 = 30.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A house is supplied with a 240V a.c mains. To operate a doorbell rated at 8V, a transformer is used. If the number of turns in the primary coil is 900, calculate the number of turns in the secondary coil.', '["<u>30</u>","240","248","450"]', 'Ns = 900 × 8/240 = <u>30</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cau622xu11dcz36fgbegoay9i', 'Government', 'JAMB', null, 2020, null, 'The principle of checks and balances reinforces separation of powers in order to', null, '["make the legislature more powerful","prevent the emergence of dictatorship","protect the powers of the executive","prevent an unconstitutional change of Government"]', 1, 'Checks and balances prevent dictatorship.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The principle of checks and balances reinforces separation of powers in order to', '["make the legislature more powerful","<u>prevent the emergence of dictatorship</u>","protect the powers of the executive","prevent an unconstitutional change of Government"]', 'Checks and balances <u>prevent dictatorship</u>.', '{"bold":[],"italic":[],"underline":["prevent the emergence of dictatorship"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cau8c2se5w3059hm9apv5cg6p', 'Physics', 'JAMB', null, 2019, null, 'The cross-sectional area of a pipe is 25m². What is the volumetric flow rate if water velocity is 10m/s?', null, '["200m³/s","300m³/s","250m³/s","240m³/s"]', 2, 'Q = A × v = 25 × 10 = 250 m³/s.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The cross-sectional area of a pipe is 25m². What is the volumetric flow rate if water velocity is 10m/s?', '["200m³/s","300m³/s","<u>250m³/s</u>","240m³/s"]', 'Q = A × v = 25 × 10 = <u>250 m³/s</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cau9bl4c1835i8mv40h6fzt4x', 'Physics', 'JAMB', null, 2021, null, 'Calculate the current in three 6 ohms resistors connected in parallel with 12V', null, '["2A","3A","0.67A","6A"]', 3, '1/R = 3/6 → R = 2Ω. I = V/R = 12/2 = 6A.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Calculate the current in three 6 ohms resistors connected in parallel with 12V', '["2A","3A","0.67A","<u>6A</u>"]', '1/R = 3/6 → R = 2Ω. I = 12/2 = <u>6A</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('caub48uqtbp3zx7ri4145aqz0', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Where the father is the only heir who survives his son, he will inherit', null, '["one sixth of his property","one third of his property","half of his property","the whole of his property."]', 3, 'He inherits the whole property.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Where the father is the only heir who survives his son, he will inherit', '["one sixth of his property","one third of his property","half of his property","<u>the whole of his property.</u>"]', '<u>The whole of his property</u>.', '{"bold":[],"italic":[],"underline":["the whole of his property."],"fillBlanks":[]}');
