insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cav0kx997ozrna8kb1wzfkm9j', 'Chemistry', 'JAMB', null, 1987, null, 'The basicity of <b>tetraoxophosphate(V) acid</b> is', null, '["7","5","4","3"]', 3, 'H3PO4 has 3 replaceable hydrogen ions.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The basicity of <b>tetraoxophosphate(V) acid</b> is', '["7","5","4","3"]', '<u>H3PO4 has 3 replaceable H⁺ ions</u>.', '{"bold":["tetraoxophosphate(V) acid"],"italic":[],"underline":["3"],"fillBlanks":[]}');
