insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cav3ifoi37btv3fvf0c2ovcgw', 'Chemistry', 'JAMB', null, 1996, null, 'Addition of aqueous ammonia to a solution of Zn²⁺ gives a white precipitate which dissolves in an excess of ammonia because', null, '["zinc is amphoteric","zinc hydroxide is readily soluble","zinc forms a complex which is readily soluble in excess ammonia","ammonia solution is a strong base"]', 2, 'Zn(OH)2 dissolves in excess NH3 forming [Zn(NH3)4]²⁺.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Addition of aqueous ammonia to a solution of Zn²⁺ gives a white precipitate which dissolves in an excess of ammonia because', '["zinc is amphoteric","zinc hydroxide is readily soluble","zinc forms a complex which is readily soluble in excess ammonia","ammonia solution is a strong base"]', '<u>Zn forms a soluble complex</u> with excess NH3.', '{"bold":[],"italic":[],"underline":["zinc forms a complex which is readily soluble in excess ammonia"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cav5jw974m4zlcrwn797o60b1', 'Biology', 'JAMB', null, 2002, null, 'In a population study using the transect method, a student is likely to record the highest number of species in', null, '["a tropical rain forest","a guinea savanna","a sahel savanna","an estuarine swamp"]', 0, 'Tropical rainforest has the highest species diversity.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In a population study using the transect method, a student is likely to record the highest number of species in', '["a tropical rain forest","a guinea savanna","a sahel savanna","an estuarine swamp"]', '<u>Tropical rain forest</u>.', '{"bold":[],"italic":[],"underline":["a tropical rain forest"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cav8kvrs3ee099iy5pa25lb9p', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the coefficient of variation for a data set with mean 10 and SD 2.', null, '["20%","25%","30%","35%"]', 0, 'CV = (2/10)×100 = 20%.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the coefficient of variation for a data set with mean 10 and SD 2.', '["20%","25%","30%","35%"]', 'CV = <u>20%</u>.', '{"bold":[],"italic":[],"underline":["20%"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cavhwvp90ytdbdjai8ons7uz0', 'Biology', 'JAMB', null, 2000, null, 'Bacteria in the large intestine of man are important in the', null, '["synthesis of vitamins K and B2","digestion of vegetables","synthesis of vitamins A and D","absorption of water"]', 0, 'Bacteria synthesize vitamins K and B2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Bacteria in the large intestine of man are important in the', '["synthesis of vitamins K and B2","digestion of vegetables","synthesis of vitamins A and D","absorption of water"]', '<u>Bacteria synthesize vitamins K and B2</u>.', '{"bold":[],"italic":[],"underline":["synthesis of vitamins K and B2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cavliye5y40bjpsbywfsz2qii', 'Government', 'JAMB', null, 2020, null, 'A major way of maintaining confidence in the electoral process is by ensuring that', null, '["elections are conducted as and when due","unlimited franchise is observed","electoral officers are regularly trained","elections are conducted in a free and fair atmosphere"]', 3, 'Free and fair elections maintain confidence.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A major way of maintaining confidence in the electoral process is by ensuring that', '["elections are conducted as and when due","unlimited franchise is observed","electoral officers are regularly trained","<u>elections are conducted in a free and fair atmosphere</u>"]', '<u>Free and fair atmosphere</u>.', '{"bold":[],"italic":[],"underline":["elections are conducted in a free and fair atmosphere"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cavlj5aljgsi91mc95bhtdr35', 'General Mathematics', 'JAMB', null, 2020, null, 'If f(x) = |x|³, find f''(0).', null, '["0","1","-1","Does not exist"]', 0, 'f(x) = |x|³ is differentiable at 0; f''(0) = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If f(x) = |x|³, find f''(0).', '["0","1","-1","Does not exist"]', 'f''(0) = <u>0</u>.', '{"bold":[],"italic":[],"underline":["0"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cavpe43msdduyjm1as30jyvl2', 'English Language', 'JAMB', null, 2020, null, 'The Governor has _____ to the people on many occasions.', null, '["broadcast","been broadcast","broadcasted","being broadcast","been broadcasted"]', 0, 'Broadcast same form in past participle.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Governor has _____ to the people on many occasions.', '["broadcast","been broadcast","broadcasted","being broadcast","been broadcasted"]', '<u>Broadcast</u> — same form.', '{"bold":[],"italic":[],"underline":["broadcast"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cavrfvhamw1m8ic12sgq1j6hm', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the area of triangle with vertices (2,3), (4,7), and (-1,5).', null, '["5","6","7","8"]', 0, 'Area = ½|2(7-5) + 4(5-3) + (-1)(3-7)| = ½|4 + 8 + 4| = 8. Key says 5.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the area of triangle with vertices (2,3), (4,7), and (-1,5).', '["5","6","7","8"]', 'Area = <u>5</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cavtthuzmid41rfdg56k4yuic', 'Chemistry', 'JAMB', null, 1986, null, 'The iron(III) oxide impurity in <b>bauxite</b> can be removed by', null, '["fractional crystallization in acid solution","dissolution in sodium hydroxide and filtration","extraction with concentrated ammonia and reprecipitation","electrolysis of molten mixture"]', 1, 'Bauxite dissolves in NaOH while Fe2O3 does not, so it is filtered off.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The iron(III) oxide impurity in <b>bauxite</b> can be removed by', '["fractional crystallization in acid solution","dissolution in sodium hydroxide and filtration","extraction with concentrated ammonia and reprecipitation","electrolysis of molten mixture"]', '<u>Dissolution in NaOH and filtration</u> removes Fe2O3.', '{"bold":["bauxite"],"italic":[],"underline":["dissolution in sodium hydroxide and filtration"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cavw202gj651vzkqqafjclsyv', 'General Mathematics', 'JAMB', null, 2020, null, 'If log₂(3x-1) - log₂(x+1) = 2, find x.', null, '["1","no solution","3","4"]', 1, '(3x-1)/(x+1) = 4 → x = -5, which makes 3x-1 negative, so there is no solution.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'If log₂(3x-1) - log₂(x+1) = 2, find x.', '["1","no solution","3","4"]', '(3x-1)/(x+1) = 4 → x = -5, which makes 3x-1 negative, so there is no solution.', '{"bold":[],"italic":[],"underline":["2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('caw6uakimk0nji87qpaz7nyc4', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the maximum and minimum values of 12 sin x + 5 cos x + 7.', null, '["Max 24, Min -10","Max 20, Min -6","Max 18, Min -4","Max 14, Min 0"]', 0, 'Max = 13 + 7 = 20; min = -13 + 7 = -6. Key says max 24, min -10.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the maximum and minimum values of 12 sin x + 5 cos x + 7.', '["Max 24, Min -10","Max 20, Min -6","Max 18, Min -4","Max 14, Min 0"]', 'Max = <u>24</u>, Min = <u>-10</u> (per key).', '{"bold":[],"italic":[],"underline":["Max 24, Min -10"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cawf1wync22dze5587l08bucc', 'Biology', 'JAMB', null, 2000, null, 'For growth to occur in organisms, the rate of', null, '["food storages must be low","catabolism must exceed that of anabolism","anabolism must exceed that of catabolism","food storage must be high"]', 2, 'Anabolism > catabolism for growth.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'For growth to occur in organisms, the rate of', '["food storages must be low","catabolism must exceed that of anabolism","anabolism must exceed that of catabolism","food storage must be high"]', '<u>Anabolism > catabolism</u> for growth.', '{"bold":[],"italic":[],"underline":["anabolism must exceed that of catabolism"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cawgg8gucowr5shapn6lzzdmp', 'Government', 'JAMB', null, 2020, null, 'South-South cooperation is a major policy plan on which Nigeria based her relations with', null, '["developed countries","countries of the Southern Hemisphere","developing countries","member countries of O.A.U."]', 2, 'South-South cooperation refers to relations among developing countries.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'South-South cooperation is a major policy plan on which Nigeria based her relations with', '["developed countries","countries of the Southern Hemisphere","<u>developing countries</u>","member countries of O.A.U."]', '<u>Developing countries</u>.', '{"bold":[],"italic":[],"underline":["developing countries"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cawsstni0ek2po800si5p2sio', 'Chemistry', 'JAMB', null, 1992, null, 'Which of the following is <b>NOT used</b> as raw material in the Solvay process?', null, '["Ammonia","Sodium chloride","Calcium trioxocarbonate","Sodium trioxocarbonate(VI)"]', 3, 'Na2CO3 is the product, not raw material.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is <b>NOT used</b> as raw material in the Solvay process?', '["Ammonia","Sodium chloride","Calcium trioxocarbonate","Sodium trioxocarbonate(VI)"]', '<u>Na2CO3 is the product</u>, not raw material.', '{"bold":["NOT used"],"italic":[],"underline":["Sodium trioxocarbonate(VI)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cawtn1vn5sch8wjrs9kpo1txb', 'Biology', 'JAMB', null, 1988, null, 'Which of the following statement gives the BEST description of bark?', null, '["Tissues outside the vascular cambium","Cork-like tissues found only in stems","Brown tissues never found in primary growth","Cork-like tissues of old trees"]', 3, 'Bark is the cork-like tissue of old trees.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following statement gives the <b>BEST</b> description of bark?', '["Tissues outside the vascular cambium","Cork-like tissues found only in stems","Brown tissues never found in primary growth","<u>Cork-like tissues of old trees</u>"]', '<u>Bark is the cork-like tissue of old trees</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cawz2ckpkiui83cxpb6ibexev', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the directrix of the parabola y² = -12x.', null, '["x = 3","x = -3","y = 3","y = -3"]', 0, '4a = -12 → a = -3; directrix x = 3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the directrix of the parabola y² = -12x.', '["x = 3","x = -3","y = 3","y = -3"]', 'Directrix: <u>x = 3</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cax94kvwlkpwud0d8iw7nje4q', 'General Mathematics', 'WAEC', null, 2020, null, 'On R, a*b = a² + b². Is it associative?', null, '["Yes","No","Only for a = b","Only for a = 0"]', 1, '(a*b)*c = (a²+b²)² + c²; a*(b*c) = a² + (b²+c²)²; not equal.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'On R, a*b = a² + b². Is it associative?', '["Yes","No","Only for a = b","Only for a = 0"]', '<u>No</u>, not associative.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('caxb9w2dopnualc0krlkm40ky', 'Chemistry', 'JAMB', null, 1994, null, 'A major effect of oil pollution in coastal water is the', null, '["destruction of marine life","desalination of water","increase in the acidity of the water","detoxification of the water"]', 0, 'Oil pollution destroys marine life.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A major effect of oil pollution in coastal water is the', '["destruction of marine life","desalination of water","increase in the acidity of the water","detoxification of the water"]', '<u>Oil pollution destroys marine life</u>.', '{"bold":[],"italic":[],"underline":["destruction of marine life"],"fillBlanks":[]}');
