insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('caxg72lz96spjenv0hk1zd47u', 'General Mathematics', 'JAMB', null, 2020, null, 'If AB = BA = I, then B is the:', null, '["Inverse of A","Transpose of A","Adjoint of A","None"]', 0, 'B = A⁻¹.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If AB = BA = I, then B is the:', '["Inverse of A","Transpose of A","Adjoint of A","None"]', '<u>Inverse of A</u>.', '{"bold":[],"italic":[],"underline":["Inverse of A"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('caxns8i41q5o0s3fkmkkjvi0y', 'Government', 'JAMB', null, 2020, null, 'The bringing of a session of a parliament to an end through royal proclamation is known as', null, '["political impasse","dissolution of parliament","vote of no confidence","prorogation of parliament."]', 3, 'Prorogation ends a parliamentary session by royal proclamation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The bringing of a session of a parliament to an end through royal proclamation is known as', '["political impasse","dissolution of parliament","vote of no confidence","<u>prorogation of parliament.</u>"]', '<u>Prorogation of parliament</u>.', '{"bold":[],"italic":[],"underline":["prorogation of parliament."],"fillBlanks":[]}');
