insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('caymcctfygz6ao6bqnkdw3u0t', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Solomon''s wisdom surpassed the wisdom of all the people of the East and all wisdom of Egypt because he', null, '["judged difficult cases","got his wisdom from God","prayed and fasted daily","employed the service of seers."]', 1, 'He got his wisdom from God.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solomon''s wisdom surpassed the wisdom of all the people of the East and all wisdom of Egypt because he', '["judged difficult cases","<u>got his wisdom from God</u>","prayed and fasted daily","employed the service of seers."]', '<u>Got his wisdom from God</u> (1 Kings 4:29-30).', '{"bold":[],"italic":[],"underline":["got his wisdom from God"],"fillBlanks":[]}');
