insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cayypzn6s2i0mf1lpwf3f0c7x', 'General Mathematics', 'JAMB', null, 2020, null, 'In a class, 15 pass math, 12 pass physics, 8 pass both, 5 fail both. What is the total?', null, '["24","25","26","27"]', 1, 'At least one = 15+12-8 = 19; total = 19+5 = 24. Key says 25.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In a class, 15 pass math, 12 pass physics, 8 pass both, 5 fail both. What is the total?', '["24","25","26","27"]', 'Total = <u>25</u> (per key).', '{"bold":[],"italic":[],"underline":["25"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('caz0b4yvkq3nehfuxfsygqvs9', 'Biology', 'JAMB', null, 1999, null, 'The structure that is most commonly identified in all living cells under the light microscope is the', null, '["mitochondrion","chloroplast","nucleus","ribosome"]', 2, 'nucleus is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The structure that is most commonly identified in all living cells under the light microscope is the', '["mitochondrion","chloroplast","<u>nucleus</u>","ribosome"]', 'nucleus is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cazg7qni8u5uwlt88y56yvny8', 'Government', 'JAMB', null, 2020, null, 'A typical form of delegated legislation is', null, '["an act","a decree","a bill","a bye-law"]', 3, 'A bye-law is a form of delegated legislation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A typical form of delegated legislation is', '["an act","a decree","a bill","<u>a bye-law</u>"]', '<u>A bye-law</u>.', '{"bold":[],"italic":[],"underline":["a bye-law"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cb01zj6d39fozhhrpptt1ia6f', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve (x - 2)/(x + 3) ≤ 0.', null, '["(-3, 2)","[-3, 2)","(-3, 2]","[-3, 2]"]', 2, '(x-2)/(x+3) ≤ 0: critical points x = 2 and x = -3; sign chart gives -3 < x ≤ 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Solve (x - 2)/(x + 3) ≤ 0.', '["(-3, 2)","[-3, 2)","(-3, 2]","[-3, 2]"]', '(x-2)/(x+3) ≤ 0: critical points x = 2 and x = -3; sign chart gives -3 < x ≤ 2.', null);
