insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cb0867a7-408a-40a2-ba7a-181fcc3fb56c', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Jide says he read in the papers that our uncle has been declared a <u>persona non grata</u> by the French government.', null, '["unwelcome guest","impersonator","ungrateful person","unofficial guest"]', 0, 'Persona non grata = unwelcome guest.', true, '2026-10-24 01:03:59.425', '2026-10-24 01:03:59.425', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Jide says he read in the papers that our uncle has been declared a <u>persona non grata</u> by the French government.', '["<u>unwelcome guest</u>","impersonator","ungrateful person","unofficial guest"]', '<b>Persona non grata</b> = <b>unwelcome guest</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cb0gudidgzpfm7p0q60ve5v53', 'Government', 'JAMB', null, 2020, null, 'The Independent National Electoral Commission has the power to prepare and maintain the register of', null, '["political parties","constituencies","voters","electoral candidate"]', 2, 'INEC prepares and maintains the register of voters.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Independent National Electoral Commission has the power to prepare and maintain the register of', '["political parties","constituencies","<u>voters</u>","electoral candidate"]', 'Register of <u>voters</u>.', '{"bold":[],"italic":[],"underline":["voters"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cb0sj8cppqk1o7a8u9pjlb0wy', 'Biology', 'JAMB', null, 2002, null, 'The excessive use of agro-chemicals could lead to the pollution of', null, '["the lithosphere","the atmosphere","fresh water","space"]', 2, 'fresh water is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The excessive use of agro-chemicals could lead to the pollution of', '["the lithosphere","the atmosphere","<u>fresh water</u>","space"]', 'fresh water is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cb0uvxwnma0b62272ix26xp41', 'Biology', 'JAMB', null, 2003, null, 'If a DNA strand has a base sequence TCA, its complementary strand must be', null, '["ATG","GAT","AGT","TAG"]', 2, 'T→A, C→G, A→T = AGT.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If a DNA strand has a base sequence TCA, its complementary strand must be', '["ATG","GAT","AGT","TAG"]', 'Complementary strand = <u>AGT</u>.', '{"bold":[],"italic":[],"underline":["AGT"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cb10gmb1rt7dp3x2clx265seq', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve (2x - 3)/(x + 1) > 1.', null, '["x > 4","x < -1 or x > 4","-1 < x < 4","x < -1"]', 1, '(2x - 3)/(x + 1) - 1 > 0 → (x - 4)/(x + 1) > 0 → x < -1 or x > 4. Key says x > 4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve (2x - 3)/(x + 1) > 1.', '["x < -1 or x > 4","x > 4","-1 < x < 4","x < -1"]', 'Solution: <u>x > 4</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cb11epgas2k5b7rxev6mn938g', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'In an Islamic state, the right to pardon a murderer lies with the', null, '["head of state","legislature","deceased relatives","courts."]', 2, 'The right lies with the deceased''s relatives.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In an Islamic state, the right to pardon a murderer lies with the', '["head of state","legislature","<u>deceased relatives</u>","courts."]', '<u>Deceased relatives</u>.', '{"bold":[],"italic":[],"underline":["deceased relatives"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cb1692ff-eb6a-410f-9596-ed943b66f3c7', 'Physics', 'JAMB', null, 2026, null, 'Which of the following phenomenon is called photoelectric effect?', null, '["high energy electrons impinge on a metallic anode which then emits photons","a high photons emits photons as it slowed down","a metal absorbs quanta of light and then emits electron","two electrons are created from quanta of light"]', 2, 'The photoelectric effect is the phenomenon where a metal absorbs quanta of light (photons) and then emits electrons. This was explained by Einstein using the photon theory of light.', true, '2026-09-10 10:56:46.331', '2026-09-10 10:56:46.331', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cb1e4ad7-6a35-4588-a8a8-37fb0783c1f7', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Stephen was blamed for leaving his door <u>ajar</u> during the heavy rainfall.', null, '["unlocked","unbolted","open","keyless","locked"]', 2, 'Ajar = slightly open.', true, '2026-10-24 01:03:53.812', '2026-10-24 01:03:53.812', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Stephen was blamed for leaving his door <u>ajar</u> during the heavy rainfall.', '["unlocked","unbolted","<u>open</u>","keyless","locked"]', '<b>Ajar</b> = slightly <b>open</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cb1kh67oe5xu2c4ur6fg6rqye', 'Chemistry', 'JAMB', null, 1998, null, 'A common characteristic shared by iron and aluminium is that both', null, '["are extracted by reduction methods","form only basic oxides","show oxidation states of +2 and +3","form soluble hydroxides"]', 0, 'Both are extracted by reduction methods.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A common characteristic shared by iron and aluminium is that both', '["are extracted by reduction methods","form only basic oxides","show oxidation states of +2 and +3","form soluble hydroxides"]', '<u>Both are extracted by reduction methods</u>.', '{"bold":[],"italic":[],"underline":["are extracted by reduction methods"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cb1m6zmqey4aheu46sthzh9ls', 'Chemistry', 'JAMB', null, 1984, null, 'Hydrogen diffuses through a porous plug', null, '["at the same rate as oxygen","at a slower rate than oxygen","twice as fast as oxygen","three times as fast as oxygen","four times as fast as oxygen"]', 4, 'Rate ∝ 1/√M; H2 (M=2) vs O2 (M=32); ratio = √(32/2) = 4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Hydrogen diffuses through a porous plug', '["at the same rate as oxygen","at a slower rate than oxygen","twice as fast as oxygen","three times as fast as oxygen","four times as fast as oxygen"]', 'Rate ratio = √(32/2) = <u>4 times as fast</u>.', '{"bold":[],"italic":[],"underline":["four times as fast as oxygen"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cb1s9l89zbg602urs0f0l13w8', 'Government', 'JAMB', null, 2020, null, 'Under the 1963 Constitution, items not listed in the exclusive and concurrent lists were within the exclusive competence of the', null, '["executive","federal parliament","regional legislatures","judiciary"]', 2, 'Residual items were within the exclusive competence of regional legislatures.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Under the 1963 Constitution, items not listed in the exclusive and concurrent lists were within the exclusive competence of the', '["executive","federal parliament","<u>regional legislatures</u>","judiciary"]', '<u>Regional legislatures</u> handled residual matters.', '{"bold":[],"italic":[],"underline":["regional legislatures"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cb22p7vkpma4me7laibg04f8y', 'Chemistry', 'JAMB', null, 1993, null, 'The phenomenon whereby sodium trioxocarbonate(IV) decahydrate loses some of its water of crystallization on exposure to the atmosphere is known as', null, '["deliquescence","hygroscopy","effervescence","efflorescence"]', 3, 'Efflorescence is loss of water of crystallization to air.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The phenomenon whereby sodium trioxocarbonate(IV) decahydrate loses some of its water of crystallization on exposure to the atmosphere is known as', '["deliquescence","hygroscopy","effervescence","efflorescence"]', '<u>Efflorescence</u> is loss of water of crystallization.', '{"bold":[],"italic":[],"underline":["efflorescence"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cb245xyxp7pdxs3nnstuf8zwi', 'Government', 'JAMB', null, 2020, null, 'Nigeria''s high standing in the UN General Assembly is underscored by her', null, '["military strength","successes in UN elective offices","contribution to global peace","financial contributions"]', 2, 'Nigeria''s UN standing stems from contribution to global peace.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Nigeria''s high standing in the UN General Assembly is underscored by her', '["military strength","successes in UN elective offices","<u>contribution to global peace</u>","financial contributions"]', '<u>Contribution to global peace</u>.', '{"bold":[],"italic":[],"underline":["contribution to global peace"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cb27exww8zmaez0alruhmrgca', 'General Mathematics', 'JAMB', null, 2020, null, 'Differentiate y = x^sin x.', null, '["x^sin x(sin x/x + cos x ln x)","x^sin x(sin x/x - cos x ln x)","x^sin x(cos x ln x + sin x/x)","x^sin x(cos x ln x - sin x/x)"]', 0, 'Logarithmic differentiation gives x^sin x(sin x/x + cos x ln x).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Differentiate y = x^sin x.', '["x^sin x(sin x/x + cos x ln x)","x^sin x(sin x/x - cos x ln x)","x^sin x(cos x ln x + sin x/x)","x^sin x(cos x ln x - sin x/x)"]', 'dy/dx = <u>x^sin x(sin x/x + cos x ln x)</u>.', '{"bold":[],"italic":[],"underline":["x^sin x(sin x/x + cos x ln x)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cb2a3d80-a34d-4907-8750-1e1f7ee748ac', 'Economics', 'JAMB', null, 2026, null, 'Given that Q = 20 - 4p and Q = 6p + 12. Determine the equilibrium quantity.', null, '["14.2","16.8","20.8","30.2"]', 1, 'At equilibrium, 20 - 4p = 6p + 12. Solving: 20 - 12 = 6p + 4p, giving 8 = 10p, so p = 0.8. Substituting p = 0.8 into Q = 20 - 4(0.8) = 20 - 3.2 = 16.8. Therefore, the equilibrium quantity is 16.8.', true, '2026-09-10 10:41:59.913', '2026-09-10 10:41:59.913', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cb2e5650-87ce-40d1-a34a-a7550d1051fa', 'Government', 'JAMB', null, 2026, null, 'General Muritala created _ states', null, '["12","11","7","6"]', 0, 'General Muritala Muhammed created 12 states in Nigeria. In 1967, General Yakubu Gowon had created 12 states. However, General Muritala Muhammed created 7 additional states in 1976, bringing the total to 19 states. The question asks how many states Muritala created, which was 7 new states, but the option 12 refers to the total number of states after his creation. Based on the options, the answer is 12 states (the total after his creation).', true, '2026-09-10 10:45:05.502', '2026-09-10 10:45:05.502', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cb2fdanen5541yrbjoqyoyd5t', 'General Mathematics', 'JAMB', null, 2020, null, 'Find ∫ √((1 - x)/(1 + x)) dx.', null, '["sin⁻¹x + √(1 - x²) + C","sin⁻¹x - √(1 - x²) + C","cos⁻¹x - √(1 - x²) + C","cos⁻¹x + √(1 - x²) + C"]', 0, 'Trig substitution x = cos θ; result = sin⁻¹x + √(1 - x²) + C.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find ∫ √((1 - x)/(1 + x)) dx.', '["sin⁻¹x + √(1 - x²) + C","sin⁻¹x - √(1 - x²) + C","cos⁻¹x - √(1 - x²) + C","cos⁻¹x + √(1 - x²) + C"]', 'Integral = <u>sin⁻¹x + √(1 - x²) + C</u>.', '{"bold":[],"italic":[],"underline":["sin⁻¹x + √(1 - x²) + C"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cb2t2sbv7u4umpppkwb3lqae8', 'Chemistry', 'JAMB', null, 1999, null, 'Polyvinyl chloride is used to produce', null, '["bread","pencils","ink","pipes"]', 3, 'PVC is used to make pipes.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Polyvinyl chloride is used to produce', '["bread","pencils","ink","pipes"]', '<u>PVC is used for pipes</u>.', '{"bold":[],"italic":[],"underline":["pipes"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cb2womdgetzssjtp88inq7tfw', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'In Colossians, Paul admonished believers not to lie to one another because they', null, '["had put off the old nature with its practices","had known the truth from the very beginning","were waiting for the second coming of Christ","were joint heirs with Christ in the kingdom."]', 0, 'They had put off the old nature with its practices.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In Colossians, Paul admonished believers not to lie to one another because they', '["<u>had put off the old nature with its practices</u>","had known the truth from the very beginning","were waiting for the second coming of Christ","were joint heirs with Christ in the kingdom."]', '<u>Had put off the old nature with its practices</u> (Colossians 3:9).', '{"bold":[],"italic":[],"underline":["had put off the old nature with its practices"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cb2zu2iopt0y7uc072f6jaxvq', 'Islamic Religious Studies', 'JAMB', null, 2010, null, 'Prophet Muhammad''s (SAW) answer to Angel Jibril when he was asked to recite was', null, '["I am not a scholar","I am not a judge","I cannot read","I cannot preach"]', 2, 'The Prophet replied "Ma ana bi qari" (I cannot read).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Prophet Muhammad''s (SAW) answer to Angel Jibril when he was asked to recite was', '["I am not a scholar","I am not a judge","<u>I cannot read</u>","I cannot preach"]', 'The Prophet replied <u>"Ma ana bi qari"</u> (I cannot read).', '{"bold":[],"italic":[],"underline":["I cannot read"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cb34mxoohypkbh069gngsa12t', 'Biology', 'JAMB', null, 2002, null, 'The carnassial teeth of a carnivorous animal consist of the', null, '["last upper premolar and the first lower molar","last upper molar and the last lower molar","first upper premolar and the first lower molar","first upper molar and the first lower molar"]', 0, 'Carnassial teeth = last upper premolar + first lower molar.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The carnassial teeth of a carnivorous animal consist of the', '["last upper premolar and the first lower molar","last upper molar and the last lower molar","first upper premolar and the first lower molar","first upper molar and the first lower molar"]', '<u>Last upper premolar and first lower molar</u>.', '{"bold":[],"italic":[],"underline":["last upper premolar and the first lower molar"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cb3b92245r2c82qm23cvfto3d', 'General Mathematics', 'WAEC', null, 2020, null, 'Convert 0.1101₂ to base ten.', null, '["0.8125","0.6875","0.5625","0.4375"]', 1, '0.1101₂ = 1/2 + 1/4 + 0/8 + 1/16 = 0.5 + 0.25 + 0.0625 = 0.8125. Key says 0.6875.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Convert 0.1101₂ to base ten.', '["0.8125","0.6875","0.5625","0.4375"]', '0.1101₂ = <u>0.8125</u> (key says 0.6875).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cb3mss4a4cdjhxl5p6hm6p169', 'Chemistry', 'JAMB', null, 1998, null, '30cm³ of hydrogen was collected over water at 27°C and 780mm Hg. If the vapour pressure of water at the temperature of the experiment was 10mm Hg, calculate the volume of the gas at 760mm Hg and 7°C.', null, '["40.0cm³","35.7cm³","28.4cm³","25.2cm³"]', 1, 'P1 = 770; V2 = (770×30×280)/(760×300) = 28.4 cm³. Key says 35.7.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '30cm³ of hydrogen was collected over water at 27°C and 780mm Hg. If the vapour pressure of water at the temperature of the experiment was 10mm Hg, calculate the volume of the gas at 760mm Hg and 7°C.', '["40.0cm³","35.7cm³","28.4cm³","25.2cm³"]', 'V2 = <u>28.4 cm³</u> (key says 35.7).', '{"bold":[],"italic":[],"underline":["35.7cm³"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cb43gyxtp6szg223aurdinkmd', 'Government', 'JAMB', null, 2020, null, 'The primary aim of pressure groups is to', null, '["attract people''s attention","protect the interest of members","capture political power","fight corrupt officials."]', 1, 'Pressure groups protect members'' interests.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The primary aim of pressure groups is to', '["attract people''s attention","<u>protect the interest of members</u>","capture political power","fight corrupt officials."]', '<u>Protect the interest of members</u>.', '{"bold":[],"italic":[],"underline":["protect the interest of members"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cb46evg65ud1ewu7mlvclmc64', 'Chemistry', 'JAMB', null, 1983, null, 'The hybridization of the carbon atom in <b>ethylene</b> is', null, '["sp³","sp³","sp²","sp","s"]', 2, 'Ethylene (C2H4) has sp² hybridized carbons.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The hybridization of the carbon atom in <b>ethylene</b> is', '["sp³","sp³","sp²","sp","s"]', '<u>Ethylene (C2H4)</u> has sp² hybridized carbons.', '{"bold":["ethylene"],"italic":[],"underline":["sp²"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cb4epd0yryq9y98eorb8w9vs5', 'Biology', 'JAMB', null, 2004, null, 'Which of the following is an example of intraspecific competition?', null, '["Yam and potato shoots growing out through the same window","A lizard and an ant-eater chasing an i nsect","A worker termite and a soldier in a limited space","A hawk and an eagle targeting the same chicken"]', 3, 'A hawk and an eagle targeting the same chicken is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is an example of intraspecific competition?', '["Yam and potato shoots growing out through the same window","A lizard and an ant-eater chasing an i nsect","A worker termite and a soldier in a limited space","<u>A hawk and an eagle targeting the same chicken</u>"]', 'A hawk and an eagle targeting the same chicken is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cb4gw8wd38v7cgnh3fp6xo0n5', 'General Mathematics', 'WAEC', null, 2020, null, 'Subtract 234₆ from 512₆.', null, '["234₆","242₆","354₆","432₆"]', 0, '512₆ = 188; 234₆ = 94; 188 - 94 = 94 = 234₆.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Subtract 234₆ from 512₆.', '["234₆","242₆","354₆","432₆"]', '512₆ - 234₆ = <u>234₆</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cb4nhgrmtj56zpz530pjdazsc', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Where the husband and wife mutually agree to terminate their marriage contract without anything against each other, such a dissolution is termed', null, '["ila''","fashk","khul","mubara''ah"]', 3, 'It is termed mubara''ah.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Where the husband and wife mutually agree to terminate their marriage contract without anything against each other, such a dissolution is termed', '["ila''","fashk","khul","<u>mubara''ah</u>"]', '<u>Mubara''ah</u>.', '{"bold":[],"italic":[],"underline":["mubara''ah"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cb4s9apm46gpl1qeqttvyppik', 'Biology', 'JAMB', null, 1990, null, 'Short-sightedness can be corrected by lenses which are', null, '["convex","biconvex","plano-convex","concave"]', 3, 'Short-sightedness is corrected by concave lenses.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Short-sightedness can be corrected by lenses which are', '["convex","biconvex","plano-convex","<u>concave</u>"]', '<u>Short-sightedness is corrected by concave lenses</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cb4traar4c6dtxx84fo733zet', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Where did Elijah kill all the prophets of Baal after the contest with Ahab?', null, '["Kishon","Carmel","Zarephath","Cherith."]', 0, 'Elijah killed them at the brook Kishon.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Where did Elijah kill all the prophets of Baal after the contest with Ahab?', '["<u>Kishon</u>","Carmel","Zarephath","Cherith."]', '<u>Kishon</u> (1 Kings 18:40).', '{"bold":[],"italic":[],"underline":["Kishon"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cb4xfmsbufvl8n183vacibdsi', 'Chemistry', 'JAMB', null, 2024, null, 'Sugar and salt are separated by', null, '["Dissolution followed by Evaporation then filtration","Evaporation then filtration","Dissolution followed by filtration then Evaporation","Distillation"]', 2, 'Sugar and salt are separated by dissolution, filtration (to remove insoluble impurities), then evaporation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Sugar and salt are separated by', '["Dissolution followed by Evaporation then filtration","Evaporation then filtration","<u>Dissolution followed by filtration then Evaporation</u>","Distillation"]', 'Sugar and salt are separated by <u>dissolution, filtration, then evaporation</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cb534np34etoqm67jyg6cfriw', 'Chemistry', 'JAMB', null, 1983, null, 'The molecular formula of X (from the passage above) is', null, '["C12H22O11","C6H12O6","C7H8O9","C7H8O9","C7H8O9"]', 1, 'X has empirical formula CH2O and Mr = 180, so molecular formula = C6H12O6 (glucose).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The molecular formula of X (from the passage above) is', '["C12H22O11","C6H12O6","C7H8O9","C7H8O9","C7H8O9"]', 'X has empirical formula CH2O and Mr = 180, so molecular formula = <u>C6H12O6</u>.', '{"bold":[],"italic":[],"underline":["C6H12O6"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cb545upukwft0j5co89y4ust4', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'To ensure the authenticity of the compiled text of the Holy Qur''an, extracts written on various materials were cross-checked with texts', null, '["written by the Prophet (S.A.W) himself","recalled from memory by early memorizers","delivered by angel Jibril to the Prophet (S.A.W)","written by Zayd bin Thabit"]', 1, 'Extracts were cross-checked with texts recalled from memory by early memorizers.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'To ensure the authenticity of the compiled text of the Holy Qur''an, extracts written on various materials were cross-checked with texts', '["written by the Prophet (S.A.W) himself","<u>recalled from memory by early memorizers</u>","delivered by angel Jibril to the Prophet (S.A.W)","written by Zayd bin Thabit"]', '<u>Recalled from memory by early memorizers</u>.', '{"bold":[],"italic":[],"underline":["recalled from memory by early memorizers"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cb582ed1-183f-441e-980a-e09060311a6a', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. It is a <u>unique</u> opportunity for her to demonstrate the reality of her faith.', null, '["strange","usual","golden","unusual"]', 1, 'Unique = one of a kind; opposite = usual.', true, '2026-10-24 07:21:14.375', '2026-10-24 07:21:14.375', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. It is a <u>unique</u> opportunity for her to demonstrate the reality of her faith.', '["strange","usual","golden","unusual"]', 'Unique = one of a kind; opposite = usual.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cb5f73ff-91ac-4718-b6f0-9538bce50bc4', 'Financial Accounting', 'UTME', null, 2004, null, 'A rent received by a trader for sub-letting part of his business premises should be added to the', null, '["gross profit","total profit","net profit","total revenue"]', 0, 'Rent received from sub-letting part of business should be posted to the credit side of profit and loss account as an addition to gross profit carried down from trading account.', true, '2026-10-12 22:00:02.149', '2026-10-12 22:00:02.149', null, null, null, 'A rent received by a trader for sub-letting part of his business premises should be added to the', '["<b>gross profit</b>","total profit","net profit","total revenue"]', 'Rent received from sub-letting part of business should be posted to the credit side of profit and loss account as an addition to <b>gross profit</b> carried down from trading account.', '{"bold":["gross profit"],"italic":[],"underline":[],"fillBlanks":[]}');
