insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cb6idlu29rmrhyo87yn1p31or', 'General Mathematics', 'JAMB', null, 2020, null, 'If the lines 2x + y = 3, x - y = 1, and kx + 2y = 4 form a triangle, then k can be:', null, '["Any real value","k ≠ 4","k ≠ -1","Any k except those making lines concurrent or parallel"]', 3, 'Triangle requires non-concurrent, non-parallel lines.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If the lines 2x + y = 3, x - y = 1, and kx + 2y = 4 form a triangle, then k can be:', '["Any real value","k ≠ 4","k ≠ -1","Any k except those making lines concurrent or parallel"]', '<u>Any k except those making lines concurrent or parallel</u>.', '{"bold":[],"italic":[],"underline":["Any k except those making lines concurrent or parallel"],"fillBlanks":[]}');
