insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cb6t0tm42b6zt0f6bmu3gj6tk', 'Biology', 'JAMB', null, 1997, null, 'The speed of wind can be measured with an instrument called', null, '["hydrometer","secchi disc","anemometer","wind vane."]', 2, 'anemometer is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The speed of wind can be measured with an instrument called', '["hydrometer","secchi disc","<u>anemometer</u>","wind vane."]', 'anemometer is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cb6xivz10b4jqfndajp4ybj1b', 'General Mathematics', 'JAMB', null, 2020, null, 'If xʸ = yˣ, find dy/dx.', null, '["y(y - x ln y)/(x(y - ln y))","y(x ln y - y)/(x(y ln x - x))","y(x - y ln x)/(x(y - x ln y))","y(x ln y + y)/(x(y ln x + x))"]', 0, 'Implicit differentiation yields y(y - x ln y)/(x(y - ln y)).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If xʸ = yˣ, find dy/dx.', '["y(y - x ln y)/(x(y - ln y))","y(x ln y - y)/(x(y ln x - x))","y(x - y ln x)/(x(y - x ln y))","y(x ln y + y)/(x(y ln x + x))"]', 'dy/dx = <u>y(y - x ln y)/(x(y - ln y))</u>.', '{"bold":[],"italic":[],"underline":["y(y - x ln y)/(x(y - ln y))"],"fillBlanks":[]}');
