insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbajmog2owvroxjzvbjfxhr5k', 'Government', 'JAMB', null, 2020, null, 'The political party formed in 1923 by Herbert Macaulay was', null, '["Nigerian Youth Movement","National Council of Nigeria and the Cameroons.","United National Independent Party","Nigerian National Democratic Party"]', 3, 'Macaulay formed the NNDP in 1923.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The political party formed in 1923 by Herbert Macaulay was', '["Nigerian Youth Movement","National Council of Nigeria and the Cameroons.","United National Independent Party","<u>Nigerian National Democratic Party</u>"]', '<u>Nigerian National Democratic Party</u>.', '{"bold":[],"italic":[],"underline":["Nigerian National Democratic Party"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbaqg79utok2ophbvk3gzs6u6', 'Biology', 'JAMB', null, 1994, null, 'In which of the following vertebrates does the skin function as a respiratory surface?', null, '["Rat","Lizard","Fish","Frog"]', 3, 'The frog uses its skin as a respiratory surface.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In which of the following vertebrates does the skin function as a respiratory surface?', '["Rat","Lizard","Fish","<u>Frog</u>"]', '<u>The frog uses its skin as a respiratory surface</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbb43204-a7f4-425c-98a0-5e1f0b167554', 'English Language', 'JAMB', null, 2007, null, 'A gang of robbers <u>__________</u> arrested by the police', null, '["has been","has being","have been","have being"]', 0, 'Singular ''gang'' â†’ has been.', true, '2026-10-24 01:04:30.5', '2026-10-24 01:04:30.5', null, null, null, 'A gang of robbers <u>__________</u> arrested by the police', '["<u>has been</u>","has being","have been","have being"]', 'Singular ''<b>gang</b>'' â†’ <b>has been</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbb55jmpg5wd1zo5321q565jd', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the length of the latus rectum of the ellipse x²/25 + y²/9 = 1.', null, '["18/5","16/5","14/5","12/5"]', 0, 'Latus rectum = 2b²/a = 18/5.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the length of the latus rectum of the ellipse x²/25 + y²/9 = 1.', '["18/5","16/5","14/5","12/5"]', 'Length = <u>18/5</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbb58igyka8uwqhtxullry15w', 'Government', 'JAMB', null, 2020, null, 'One major function of the Authority of Heads of State and Government of ECOWAS is', null, '["organizing international conferences","appointing staff of the Secretariat","appointing the Executive Secretary","preparing the budget of the Community."]', 2, 'The Authority appoints the Executive Secretary.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One major function of the Authority of Heads of State and Government of ECOWAS is', '["organizing international conferences","appointing staff of the Secretariat","<u>appointing the Executive Secretary</u>","preparing the budget of the Community."]', '<u>Appointing the Executive Secretary</u>.', '{"bold":[],"italic":[],"underline":["appointing the Executive Secretary"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbb7u1gnhzrd90wwo6ln9n0r6', 'Chemistry', 'JAMB', null, 1986, null, 'The reaction Mg + H2O → MgO + H2 takes place only in the presence of', null, '["excess Mg ribbon","excess cold water","very hot water","steam"]', 3, 'Mg reacts with steam, not cold water.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The reaction Mg + H2O → MgO + H2 takes place only in the presence of', '["excess Mg ribbon","excess cold water","very hot water","steam"]', '<u>Mg reacts with steam</u>.', '{"bold":[],"italic":[],"underline":["steam"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbb867c2-7427-41f0-8fbc-d248a762c451', 'Physics', 'JAMB', null, 1985, null, 'A force of 100 N stretches an elastic string to a total length of 20 cm. If an additional force of 100 N stretches the string 5 cm further, find the natural length of the string.', null, '["15 cm","12 cm","10 cm","8 cm","5 cm"]', 0, 'Each 100 N produces 5 cm extension (Hooke''s law). The first 100 N therefore gave 5 cm, so natural length = 20 - 5 = 15 cm.', true, '2026-10-12 19:15:20.986', '2026-10-12 19:15:20.986', null, null, null, 'A force of 100 N stretches an elastic string to a total length of 20 cm. If an additional force of 100 N stretches the string 5 cm further, find the natural length of the string.', '["15 cm","12 cm","10 cm","8 cm","5 cm"]', 'Each 100 N produces 5 cm extension (Hooke''s law). The first 100 N therefore gave 5 cm, so natural length = 20 - 5 = 15 cm.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbb886da-85a1-445a-bd74-be95e94cf0f8', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). ''<u>To be in the red</u>'' is to be ______________', null, '["in debt","rich","a socialist","red","dressed in red"]', 0, '''In the red'' means owing money.', true, '2026-10-24 01:04:13.228', '2026-10-24 01:04:13.228', null, null, null, '(Choose the most appropriate interpretation). ''<u>To be in the red</u>'' is to be ______________', '["<u>in debt</u>","rich","a socialist","red","dressed in red"]', '''<b>In the red</b>'' means <b>owing money</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbbrfn3rs5gtmxiqtjm04q53j', 'Physics', 'JAMB', null, 1983, null, 'The electrochemical equivalent of a metal is 0.126 × 10⁻⁶ kg/C. The mass of the metal that a current of 5 A will deposit from a suitable bath in 1 hour is', null, '["0.0378 × 10⁻³ kg","0.227 × 10⁻³ kg","0.378 × 10⁻³ kg","0.595 × 10⁻³ kg","2.268 × 10⁻³ kg"]', 4, 'm = zIt = 0.126 × 10⁻⁶ × 5 × 3600 = 2.268 × 10⁻³ kg.', true, '2026-10-11 21:26:45.728', '2026-10-11 21:26:45.728', null, null, null, 'The electrochemical equivalent of a metal is 0.126 × 10⁻⁶ kg/C. The mass of the metal that a current of 5 A will deposit from a suitable bath in 1 hour is', '["0.0378 × 10⁻³ kg","0.227 × 10⁻³ kg","0.378 × 10⁻³ kg","0.595 × 10⁻³ kg","2.268 × 10⁻³ kg"]', 'm = zIt = 0.126 × 10⁻⁶ × 5 × 3600 = 2.268 × 10⁻³ kg.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbc5eo3r2couevegfo6vs9mkw', 'Chemistry', 'JAMB', null, 1991, null, 'The solubility of copper(II) tetraoxosulphate(VI) is 75g in 100g of water at 100°C and 25g in 100g of water at 30°C. What mass of the salt would crystallize, if 50g of copper(II) tetraoxosulphate(VI) solution saturated at 100°C were cooled to 30°C?', null, '["57.5g","42.9g","28.6g","14.3g"]', 1, 'In 50g saturated solution at 100°C: salt = 50 × 75/175 = 21.4g; water = 28.6g; at 30°C, salt dissolved = 28.6 × 25/100 = 7.15g; crystallized = 21.4 - 7.15 = 14.3g. Key says 42.9.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The solubility of copper(II) tetraoxosulphate(VI) is 75g in 100g of water at 100°C and 25g in 100g of water at 30°C. What mass of the salt would crystallize, if 50g of copper(II) tetraoxosulphate(VI) solution saturated at 100°C were cooled to 30°C?', '["57.5g","42.9g","28.6g","14.3g"]', 'Crystallized = <u>14.3g</u> (key says 42.9).', '{"bold":[],"italic":[],"underline":["42.9g"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbccmnxkkqmwtd8k06j63m1kw', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The Prophet described as ruhullah in the Qur''an is', null, '["Musa","Isa","Ibrahim","Ismail"]', 1, 'Prophet Isa is described as ruhullah.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Prophet described as ruhullah in the Qur''an is', '["Musa","<u>Isa</u>","Ibrahim","Ismail"]', '<u>Isa</u> (Q. 4:171).', '{"bold":[],"italic":[],"underline":["Isa"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbcf15a8-d131-4eff-9763-1452b203d106', 'English Language', 'JAMB', null, 2024, null, 'The man is not as powerful as he once was, his influence has considerably ______', null, '["toppled","quelled","diminished","discarded"]', 2, '"Diminished" means reduced or decreased.', true, '2026-09-18 09:43:02.276', '2026-09-18 09:43:02.276', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbck2vuiwh1nizov9e3pahdco', 'Biology', 'JAMB', null, 1986, null, 'An instrument that can be used to demonstrate phototropism and geotropism in plants is the', null, '["auxanometer","potometer","kinostat","photometer"]', 2, 'The klinostat demonstrates phototropism and geotropism.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An instrument that can be used to demonstrate <b>phototropism</b> and <b>geotropism</b> in plants is the', '["auxanometer","potometer","<u>kinostat</u>","photometer"]', 'The <u>klinostat</u> demonstrates phototropism and geotropism.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbcq2h8wmuot4lc8ya8x51jw2', 'Biology', 'JAMB', null, 1992, null, 'Which of the following is true of the children of a haemophiliic man who marries a woman that is not haemophiliic and does not carry the trait?', null, '["All their sons will be haemophiliic","All their daughter will be haemophiliic","All their daughters will be carriers","All their sons will be carriers"]', 2, 'All daughters will be carriers; sons will be normal.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is true of the children of a <b>haemophiliic man</b> who marries a woman that is not haemophiliic and does not carry the trait?', '["All their sons will be haemophiliic","All their daughter will be haemophiliic","<u>All their daughters will be carriers</u>","All their sons will be carriers"]', '<u>All daughters will be carriers</u>; sons will be normal.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbd7gvkr0o98sp9vrdzhdacme', 'Government', 'JAMB', null, 2020, null, 'The judiciary controls the executive in federal states through', null, '["Judicial review","Motions","Delegated legislation","Judicial overview"]', 0, 'The judiciary controls through judicial review.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The judiciary controls the executive in federal states through', '["<u>Judicial review</u>","Motions","Delegated legislation","Judicial overview"]', '<u>Judicial review</u>.', '{"bold":[],"italic":[],"underline":["Judicial review"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbdestk53nu2ra2pe8tc31lkt', 'General Mathematics', 'WAEC', null, 2020, null, 'What is the sum of first n natural numbers whose squares are odd numbers.', null, '["n(2n-1)(2n+1)/3","n(2n+1)(2n-1)/6","n(n+1)(2n+1)/6","n²(2n+1)"]', 0, 'Sum of odd squares = n(4n²-1)/3 = n(2n-1)(2n+1)/3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is the sum of first n natural numbers whose squares are odd numbers.', '["n(2n-1)(2n+1)/3","n(2n+1)(2n-1)/6","n(n+1)(2n+1)/6","n²(2n+1)"]', 'Sum = <u>n(4n²-1)/3</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbdjysr6ccvad95tqg6ovv26b', 'Chemistry', 'JAMB', null, 1999, null, 'Hydrogen is used in oxy-hydrogen flames for melting metals because it', null, '["evolves a lot of heat when burnt","combines explosively with oxygen","is a very light gas","is a rocket fuel"]', 0, 'H2 evolves much heat when burnt.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Hydrogen is used in oxy-hydrogen flames for melting metals because it', '["evolves a lot of heat when burnt","combines explosively with oxygen","is a very light gas","is a rocket fuel"]', '<u>H2 evolves much heat</u> when burnt.', '{"bold":[],"italic":[],"underline":["evolves a lot of heat when burnt"],"fillBlanks":[]}');
