insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbdy2i3cg9div3nv8ytla56r6', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Which of the following terms is most closely related to divorce?', null, '["zawaj","''iddah","mahr","idrar"]', 1, '''Iddah is the waiting period after divorce.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following terms is most closely related to divorce?', '["zawaj","<u>''iddah</u>","mahr","idrar"]', '<u>''Iddah</u>.', '{"bold":[],"italic":[],"underline":["''iddah"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbe0c693-934a-4bcf-b6ec-c7931ee04ec5', 'Financial Accounting', 'UTME', null, 2004, null, 'How much should the petty cashier receive after period 2?', 'https://res.cloudinary.com/kwi1uv0g/image/upload/v1791841660/questions/uyeb5hwi1y2svbycwykx.jpg', '["N150","N250","N350","N500"]', 2, 'The petty cashier should receive N350 after period 2.', true, '2026-10-12 22:00:02.001', '2026-10-12 22:00:02.001', null, null, null, 'How much should the petty cashier receive after period 2?', '["N150","N250","<b>N350</b>","N500"]', 'The petty cashier should receive <b>N350</b> after period 2.', '{"bold":["N350"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbe0jm12r94r73kkqygpipz8z', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'The presiding judge at the Jerusalem Council was', null, '["Peter","James","Barnabas","Paul."]', 1, 'James presided over the Jerusalem Council.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The presiding judge at the Jerusalem Council was', '["Peter","<u>James</u>","Barnabas","Paul."]', '<u>James</u> (Acts 15:13).', '{"bold":[],"italic":[],"underline":["James"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbe63d22-8060-4329-baf8-53636274665f', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. After fifty years, he could not find anyone who was <u>contemporary with</u> him at college.', null, '["friendly with","contested against","strange to","belonged to"]', 2, 'Contemporary with = of same era; opposite = strange to.', true, '2026-10-24 07:21:25.281', '2026-10-24 07:21:25.281', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. After fifty years, he could not find anyone who was <u>contemporary with</u> him at college.', '["friendly with","contested against","strange to","belonged to"]', 'Contemporary with = of same era; opposite = strange to.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbe92f9e-8c83-4c70-9226-d05ae1a8514d', 'English Language', 'JAMB', null, 2024, null, '3', null, '["money","cash","wages","incentives"]', 2, 'Employees demand higher wages (pay for work done).', true, '2026-09-18 10:17:48.767', '2026-09-18 10:17:48.767', '274e150d-fca1-4c72-9c33-e5e119534874', 3, 'CLOZE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbeba3a9-fac0-4f60-af6d-96db23d726df', 'Physics', 'JAMB', null, 2026, null, 'What is not the SI unit of Pressure? I. Nm⁻² II. atm III. mmHg IV. Pa', null, '["I only","All except IV","none of above","I & II only","all of above"]', 1, 'The SI unit of pressure is the pascal (Pa), which is Nm⁻². atm (atmosphere) and mmHg (millimeters of mercury) are not SI units. So the answer is ''All except IV'' (all except Pa).', true, '2026-09-10 10:56:43.036', '2026-09-10 10:56:43.036', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbec8d92-7b47-4f61-b16d-d3a480f86e86', 'Biology', 'JAMB', null, 2003, null, 'Nervous control differs from hormonal control in that the former', null, '["involves only chemical transmission","is a slower process","produces short-term changes","has no specific pathway"]', 2, 'Nerve impulses trigger rapid responses that last for a very short duration.', true, '2026-10-12 20:05:11.509', '2026-10-12 20:05:11.509', null, null, null, 'Nervous control differs from hormonal control in that the former', '["involves only chemical transmission","is a slower process","produces short-term changes","has no specific pathway"]', 'Nerve impulses trigger rapid responses that last for a very short duration.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbed54lrt1b25ecm4lg1n3o5n', 'Biology', 'JAMB', null, 1987, null, 'Which of the following features of Euglena is found only in animals?', null, '["Paramylium granules","Flagellum","Pellicle","Pyrenoid"]', 0, 'Paramylium granules are found only in animals.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following features of <b>Euglena</b> is found only in animals?', '["<u>Paramylium granules</u>","Flagellum","Pellicle","Pyrenoid"]', '<u>Paramylium granules</u> are found only in animals.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbef7243-0b0d-448a-bad0-de81b24d02de', 'Physics', 'JAMB', null, 1998, null, 'A steel wire of length 0.50 m is stretched between two fixed points and its fundamental frequency is 200 Hz. The speed of the wave in the wire is', null, '["100 m s⁻¹","120 m s⁻¹","200 m s⁻¹","250 m s⁻¹"]', 2, 'For the fundamental, λ = 2L = 1.0 m. v = fλ = 200 x 1.0 = 200 m s⁻¹.', true, '2026-10-12 19:15:45.891', '2026-10-12 19:15:45.891', null, null, null, 'A steel wire of length 0.50 m is stretched between two fixed points and its fundamental frequency is 200 Hz. The speed of the wave in the wire is', '["100 m s<sup>-1</sup>","120 m s<sup>-1</sup>","200 m s<sup>-1</sup>","250 m s<sup>-1</sup>"]', 'For the fundamental, λ = 2L = 1.0 m. v = fλ = 200 x 1.0 = 200 m s<sup>-1</sup>.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbeq77bwdozt5i77gklp1gmp3', 'Islamic Religious Studies', 'JAMB', null, 2002, null, 'Allah''s existence is often demonstrated in the Glorious Qur''an by reference to his', null, '["creation","prophets","angels","throne"]', 0, 'The Qur''an repeatedly points to creation as evidence of Allah''s existence.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Allah''s existence is often demonstrated in the Glorious Qur''an by reference to his', '["<u>creation</u>","prophets","angels","throne"]', 'The Qur''an repeatedly points to <u>creation</u> as evidence of Allah''s existence.', '{"bold":[],"italic":[],"underline":["creation"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbeuqx2km24zgk7gyigojcqek', 'Government', 'JAMB', null, 2020, null, 'Power differs from influence in that it is', null, '["persuasive while influence is directive","coercive while influence is harmful","coercive while influence is persuasive","coercive while influence of a legislature."]', 2, 'Power is coercive (can compel obedience), while influence is persuasive (works through attraction and persuasion).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Power differs from influence in that it is', '["persuasive while influence is directive","coercive while influence is harmful","<u>coercive while influence is persuasive</u>","coercive while influence of a legislature."]', 'Power is <u>coercive</u> while influence is <u>persuasive</u>.', '{"bold":[],"italic":[],"underline":["coercive while influence is persuasive"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbev1sq7p3qdbqs97gppaqgx6', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'The response of Eli after Samuel had told him the Lord''s message as regards his sons'' acts of blasphemy was that', null, '["He was the LORD, and should do what pleased Him","He would punish his sons for their sins","the LORD should spare his sons","he would not allow them to serve in the Temple"]', 0, 'Eli said: "It is the LORD; let him do what seems good to him."', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The response of Eli after Samuel had told him the Lord''s message as regards his sons'' acts of blasphemy was that', '["<u>He was the LORD, and should do what pleased Him</u>","He would punish his sons for their sins","the LORD should spare his sons","he would not allow them to serve in the Temple"]', '<u>He was the LORD, and should do what pleased Him</u> (1 Samuel 3:18).', '{"bold":[],"italic":[],"underline":["He was the LORD, and should do what pleased Him"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbewcjzuhp734wzeeznltkuws', 'Chemistry', 'JAMB', null, 1987, null, 'If 24.83cm³ of 0.15M NaOH is titrated to its end point with 39.45cm³ of HCl, what is the molarity of the HCl?', null, '["0.094M","0.150M","0.940M","1.500M"]', 0, 'M1V1 = M2V2; M2 = (0.15 × 24.83)/39.45 = 0.094M.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If 24.83cm³ of 0.15M NaOH is titrated to its end point with 39.45cm³ of HCl, what is the molarity of the HCl?', '["0.094M","0.150M","0.940M","1.500M"]', 'M2 = <u>0.094M</u>.', '{"bold":[],"italic":[],"underline":["0.094M"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbezgsmnfevlcovsgls3swqq2', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'The Jewish religious leaders arrested and imprisoned the apostles the second time because', null, '["the high priest and the Sadducees were jealous.","they disobeyed the law.","the high priest and the Sadducees accused them of treason.","they performed miracles in the name of Jesus."]', 0, 'The high priest and Sadducees were jealous.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Jewish religious leaders arrested and imprisoned the apostles the second time because', '["<u>the high priest and the Sadducees were jealous.</u>","they disobeyed the law.","the high priest and the Sadducees accused them of treason.","they performed miracles in the name of Jesus."]', '<u>The high priest and the Sadducees were jealous</u> (Acts 5:17).', '{"bold":[],"italic":[],"underline":["the high priest and the Sadducees were jealous."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbf1elrlhf9r21yjvbdwqk8b7', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Consequent upon the murder of Naboth by Ahab and Jezebel, God declared that', null, '["He would require the blood of Naboth from Ahab''s hand","Ahab''s descendants would never ascend the throne in Israel","dogs would lick Ahab''s blood where they had licked Naboth''s","the sword would not depart from the house of Ahab"]', 2, 'Dogs would lick Ahab''s blood where they licked Naboth''s.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Consequent upon the murder of Naboth by Ahab and Jezebel, God declared that', '["He would require the blood of Naboth from Ahab''s hand","Ahab''s descendants would never ascend the throne in Israel","<u>dogs would lick Ahab''s blood where they had licked Naboth''s</u>","the sword would not depart from the house of Ahab"]', '<u>Dogs would lick Ahab''s blood where they had licked Naboth''s</u> (1 Kings 21:19).', '{"bold":[],"italic":[],"underline":["dogs would lick Ahab''s blood where they had licked Naboth''s"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbf1f3v6jr7l5j20hzgfk7due', 'Chemistry', 'JAMB', null, 2024, null, 'Which of the following are products of acid hydrolysis of sucrose? I. Fructose II. Maltose III. Glucose IV. Cellulose', null, '["III only","I-III","I&III only","I only","II&III"]', 2, 'Acid hydrolysis of sucrose yields glucose and fructose.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following are products of <b>acid hydrolysis</b> of sucrose?<br>I. Fructose<br>II. Maltose<br>III. Glucose<br>IV. Cellulose', '["III only","I-III","<u>I&III only</u>","I only","II&III"]', 'Acid hydrolysis of sucrose yields <u>glucose and fructose</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbf4kall7xoafya9dz9f37lt4', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'The man who stirred up the people against Paul in Ephesus was', null, '["Aristarchus","Demetrius","Alexander","Gaius."]', 1, 'Demetrius stirred up the people against Paul.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The man who stirred up the people against Paul in Ephesus was', '["Aristarchus","<u>Demetrius</u>","Alexander","Gaius."]', '<u>Demetrius</u> (Acts 19:24-28).', '{"bold":[],"italic":[],"underline":["Demetrius"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbfb8817-e7f5-4503-b41e-d8fc49db86ee', 'Physics', 'JAMB', null, 2002, null, 'Blowing air over a liquid aids evaporation by', null, '["Decreasing its vapour pressure","Decreasing its density","Increasing its surface area","Increasing its temperature"]', 0, 'Moving air carries away the vapour above the liquid, which lowers the vapour pressure there so more molecules can escape.', true, '2026-10-12 19:15:53.6', '2026-10-12 19:15:53.6', null, null, null, 'Blowing air over a liquid aids evaporation by', '["Decreasing its vapour pressure","Decreasing its density","Increasing its surface area","Increasing its temperature"]', 'Moving air carries away the vapour above the liquid, which lowers the vapour pressure there so more molecules can escape.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbfhzs0b9r6h3oc81yramf54r', 'Chemistry', 'JAMB', null, 1998, null, 'The lines observed in the simple hydrogen spectrum are due to emission of', null, '["electron from the atom","energy by proton transition","energy by electron transition","neutrons from the atom"]', 2, 'Hydrogen spectrum lines are due to electron transitions.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The lines observed in the simple hydrogen spectrum are due to emission of', '["electron from the atom","energy by proton transition","energy by electron transition","neutrons from the atom"]', '<u>Electron transitions</u> produce the lines.', '{"bold":[],"italic":[],"underline":["energy by electron transition"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbfqhlporrgbpey05u61jo4cx', 'General Mathematics', 'WAEC', null, 2020, null, 'If A = {1, 2, 3, 4}, B = {2, 4, 6}, C = {3, 4, 5}, find (A ∩ B) ∪ (B ∩ C).', null, '["{4}","{2, 4}","{4, 6}","{2, 4, 6}"]', 1, 'A ∩ B = {2, 4}; B ∩ C = {4}; union = {2, 4}.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If A = {1, 2, 3, 4}, B = {2, 4, 6}, C = {3, 4, 5}, find (A ∩ B) ∪ (B ∩ C).', '["{4}","{2, 4}","{4, 6}","{2, 4, 6}"]', 'Union = <u>{2, 4}</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbfsqni135opv9pb56f71vsdv', 'Biology', 'JAMB', null, 1991, null, 'Yellowing of leaves is a symptom associated with deficiency of', null, '["iron, calcium and magnesium","nitrogen, sulphur and potassium","sulphur, phosphorus and iron","magnesium, nitrogen and iron"]', 3, 'Yellowing of leaves is associated with magnesium, nitrogen, and iron deficiency.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Yellowing of leaves is a symptom associated with deficiency of', '["iron, calcium and magnesium","nitrogen, sulphur and potassium","sulphur, phosphorus and iron","<u>magnesium, nitrogen and iron</u>"]', 'Yellowing of leaves is associated with <u>magnesium, nitrogen, and iron deficiency</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbfv7gwd8dnwr1t1hj0nnkz8e', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the inverse of 5 under a*b = a + b - 5 on reals, given identity e = 5.', null, '["5","-5","0","10"]', 1, '5*x = 5 → 5+x-5 = 5 → x = 5. Key says -5.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the inverse of 5 under a*b = a + b - 5 on reals, given identity e = 5.', '["5","-5","0","10"]', 'Inverse = <u>-5</u> (per key).', '{"bold":[],"italic":[],"underline":["-5"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbgfv2knu6lhxu1iv7tpy59sk', 'Biology', 'JAMB', null, 2002, null, 'A step in the movement of energy through an ecosystem is a description that best fits the term', null, '["food chain","trophic level","pyramid of numbers","food web"]', 1, 'Trophic level = a step in energy flow.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A step in the movement of energy through an ecosystem is a description that best fits the term', '["food chain","trophic level","pyramid of numbers","food web"]', '<u>Trophic level</u>.', '{"bold":[],"italic":[],"underline":["trophic level"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbhbei6krusjrx1gzpmjktobc', 'Government', 'JAMB', null, 2020, null, 'A tactic employed by pressure groups to achieve their objectives is', null, '["memorandum","propaganda","electioneering campaign","lobbying"]', 3, 'Lobbying is a tactic used by pressure groups.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A tactic employed by pressure groups to achieve their objectives is', '["memorandum","propaganda","electioneering campaign","<u>lobbying</u>"]', '<u>Lobbying</u>.', '{"bold":[],"italic":[],"underline":["lobbying"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbhh762b7q6kp7owi71bmfj8c', 'General Mathematics', 'JAMB', null, 2020, null, 'Range of m so that x² + mx + 9 > 0 for all real x.', null, '["-6 < m < 6","m < -6 or m > 6","-3 < m < 3","m < -3 or m > 3"]', 0, 'Discriminant < 0 → m² < 36 → -6 < m < 6.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Range of m so that x² + mx + 9 > 0 for all real x.', '["-6 < m < 6","m < -6 or m > 6","-3 < m < 3","m < -3 or m > 3"]', 'Range: <u>-6 < m < 6</u>.', '{"bold":[],"italic":[],"underline":["-6 < m < 6"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbhlxirm3oen152h4oudu1zjr', 'English Language', 'JAMB', null, 2020, null, 'He was not a very _____ student when I first met him but the years _____ his character ultimately.', null, '["mature / mature","matured / mature","mature / matured","matured / matured"]', 2, 'Adjective "mature"; verb "matured".', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'He was not a very _____ student when I first met him but the years _____ his character ultimately.', '["mature / mature","matured / mature","mature / matured","matured / matured"]', '<u>Mature / matured</u>.', '{"bold":[],"italic":[],"underline":["mature / matured"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbhnunwwd8jmj791w525adb6e', 'Chemistry', 'JAMB', null, 1992, null, '¹⁴N + X → ¹⁷O + ¹H. In the above reaction, X is a', null, '["neutron","Helium atom","Lithium atom","Deuterium atom"]', 0, '¹⁴N + ⁴He → ¹⁷O + ¹H; X is ⁴He (alpha). Key says neutron.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '¹⁴N + X → ¹⁷O + ¹H. In the above reaction, X is a', '["neutron","Helium atom","Lithium atom","Deuterium atom"]', 'X = <u>⁴He (alpha particle)</u> (key says neutron).', '{"bold":[],"italic":[],"underline":["neutron"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbhwn2agq4g14trso3tp3jtdu', 'Chemistry', 'JAMB', null, 2019, null, 'When two gases having volumes 1litre and 2litres are at the same temperature, then the ratio of the average kinetic energy of the molecules in the two gases', null, '["1:1","1:2","2:1","3:1"]', 0, 'Average kinetic energy depends only on temperature, so at the same temperature the ratio is 1:1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When two gases having volumes 1litre and 2litres are at the same temperature, then the ratio of the average <b>kinetic energy</b> of the molecules in the two gases', '["<u>1:1</u>","1:2","2:1","3:1"]', 'Average kinetic energy depends only on <u>temperature</u>, so at the same temperature the ratio is 1:1.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbi8sbr57wlsu2fiifcg0f3bz', 'Chemistry', 'JAMB', null, 1993, null, 'Water can be identified by the use of', null, '["anhydrous copper(II) tetraoxosulphate(VI)","anhydrous sodium trioxocarbonate(IV)","potassium heptaoxochromate(VII)","copper(II) trioxocarbonate(IV)"]', 0, 'Anhydrous CuSO4 turns blue with water.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Water can be identified by the use of', '["anhydrous copper(II) tetraoxosulphate(VI)","anhydrous sodium trioxocarbonate(IV)","potassium heptaoxochromate(VII)","copper(II) trioxocarbonate(IV)"]', '<u>Anhydrous CuSO4 turns blue</u> with water.', '{"bold":[],"italic":[],"underline":["anhydrous copper(II) tetraoxosulphate(VI)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbidhf79qh8rie4psqzbychyq', 'Chemistry', 'JAMB', null, 1985, null, 'When ethanol is heated with excess concentrated sulphuric acid, the ethanol is', null, '["oxidized to ethene","polymerized to polyethene","dehydrated to ethene","dehydrated to ethyne"]', 2, 'Concentrated H2SO4 dehydrates ethanol to ethene.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When ethanol is heated with excess concentrated sulphuric acid, the ethanol is', '["oxidized to ethene","polymerized to polyethene","dehydrated to ethene","dehydrated to ethyne"]', '<u>Concentrated H2SO4 dehydrates ethanol to ethene</u>.', '{"bold":[],"italic":[],"underline":["dehydrated to ethene"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbioxp2uiptn876wishq9qtd1', 'Chemistry', 'JAMB', null, 1985, null, 'Which of the following metals with NaOH gives salt and water only? When Z is treated with dilute HCl, a gas is evolved which gives a yellow suspension on passing into concentrated H2SO4. Substance Z is', null, '["NaHS","Na2SO3","Na2S","NaHSO3"]', 1, 'Na2SO3 gives SO2 with HCl, which gives a yellow suspension with concentrated H2SO4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following metals with NaOH gives salt and water only? When Z is treated with dilute HCl, a gas is evolved which gives a yellow suspension on passing into concentrated H2SO4. Substance Z is', '["NaHS","Na2SO3","Na2S","NaHSO3"]', '<u>Na2SO3</u> gives SO2.', '{"bold":[],"italic":[],"underline":["Na2SO3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbirc1j39qdu38bmsoif3kign', 'General Mathematics', 'JAMB', null, 2020, null, 'A solid cylinder of radius 7 cm and height 14 cm is melted and recast into a sphere. Find the radius of the sphere. (π = 22/7)', null, '["∛(1029/2) cm","∛343 cm","7 cm","14 cm"]', 0, 'π·7²·14 = (4/3)πR³ → R³ = 1029/2, so R = ∛(1029/2) cm.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'A solid cylinder of radius 7 cm and height 14 cm is melted and recast into a sphere. Find the radius of the sphere. (π = 22/7)', '["∛(1029/2) cm","∛343 cm","7 cm","14 cm"]', 'π·7²·14 = (4/3)πR³ → R³ = 1029/2, so R = ∛(1029/2) cm.', '{"bold":[],"italic":[],"underline":["∛1029 cm"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbirldyuls50uh8419gwz1xkj', 'Chemistry', 'JAMB', null, 1994, null, 'A mixture of sand, ammonium chloride and sodium chloride is best separated by', null, '["sublimation followed by addition of water and filtration","sublimation followed by addition of water and evaporation","addition of water followed by filtration and sublimation","addition of water followed by crystallization and sublimation"]', 1, 'NH4Cl sublimes; NaCl dissolves and is recovered by evaporation; sand is filtered.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A mixture of sand, ammonium chloride and sodium chloride is best separated by', '["sublimation followed by addition of water and filtration","sublimation followed by addition of water and evaporation","addition of water followed by filtration and sublimation","addition of water followed by crystallization and sublimation"]', '<u>Sublimation → dissolution → filtration → evaporation</u>.', '{"bold":[],"italic":[],"underline":["sublimation followed by addition of water and evaporation"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbiy2tvxq93qixr2zj83ted6i', 'General Mathematics', 'JAMB', null, 2020, null, 'If a, b, c in GP and x, y are AM and GM between a, b, find x/y.', null, '["(a + b)/(2√ab)","(√a + √b)/2","(a + b)/√ab","2√ab/(a + b)"]', 0, 'x = (a+b)/2; y = √(ab); x/y = (a+b)/(2√ab).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If a, b, c in GP and x, y are AM and GM between a, b, find x/y.', '["(a + b)/(2√ab)","(√a + √b)/2","(a + b)/√ab","2√ab/(a + b)"]', 'x/y = <u>(a + b)/(2√ab)</u>.', '{"bold":[],"italic":[],"underline":["(a + b)/(2√ab)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbj4uzuxqssur7t24br4wkp70', 'Chemistry', 'JAMB', null, 1987, null, 'Local black soap is made by boiling palm oil with liquid extract of ash. The function of the ash is to provide the', null, '["acid","ester of alkanoic acid","alkali","alkanol"]', 2, 'Ash provides the alkali (K2CO3) for saponification.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Local black soap is made by boiling palm oil with liquid extract of ash. The function of the ash is to provide the', '["acid","ester of alkanoic acid","alkali","alkanol"]', '<u>Ash provides the alkali</u> for saponification.', '{"bold":[],"italic":[],"underline":["alkali"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbj9p9slkmmy7dffvi2xt6z4h', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Behold, the days are coming ... when I will send a famine on the land ... Famine in the statement above means', null, '["lack of food","unavailability of the word of God","failure of the farms to produce","lack of water."]', 1, 'Famine means unavailability of the word of God.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Behold, the days are coming ... when I will send a famine on the land ... Famine in the statement above means', '["lack of food","<u>unavailability of the word of God</u>","failure of the farms to produce","lack of water."]', '<u>Unavailability of the word of God</u> (Amos 8:11).', '{"bold":[],"italic":[],"underline":["unavailability of the word of God"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbjmazyc07uar9r3sg75uyw99', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'In the days of Uzziah, Isaiah saw a vision concerning', null, '["Samaria and Judah","Judah and Jerusalem","Samaria and Jerusalem","Judah and Israel."]', 1, 'Isaiah''s vision concerned Judah and Jerusalem.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the days of Uzziah, Isaiah saw a vision concerning', '["Samaria and Judah","<u>Judah and Jerusalem</u>","Samaria and Jerusalem","Judah and Israel."]', '<u>Judah and Jerusalem</u> (Isaiah 2:1).', '{"bold":[],"italic":[],"underline":["Judah and Jerusalem"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbjqkrs7fyso68bxbnsemkket', 'Chemistry', 'JAMB', null, 2024, null, 'What''s the maximum number a f orbital can contain?', null, '["7","10","14","8"]', 2, 'An f orbital can hold a maximum of 14 electrons.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What''s the maximum number a <b>f orbital</b> can contain?', '["7","10","<u>14</u>","8"]', 'An <u>f orbital</u> can hold a maximum of 14 electrons.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbjti4x5tw0dplkj1o344pc2j', 'Government', 'JAMB', null, 2020, null, 'A meeting of the legislature is usually brought to an end with', null, '["a dissolution","an adjournment","suspension","a prorogation"]', 1, 'A legislative meeting ends with an adjournment.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A meeting of the legislature is usually brought to an end with', '["a dissolution","<u>an adjournment</u>","suspension","a prorogation"]', '<u>Adjournment</u>.', '{"bold":[],"italic":[],"underline":["an adjournment"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbjvonah1c5qakqt2ga3yy89d', 'Chemistry', 'JAMB', null, 1999, null, 'The method that can be used to convert <b>hard water to soft water</b> is', null, '["Chlorination","Passage over activated charcoal","the use of an ion exchange resin","aeration"]', 2, 'Ion exchange resin softens hard water.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The method that can be used to convert <b>hard water to soft water</b> is', '["Chlorination","Passage over activated charcoal","the use of an ion exchange resin","aeration"]', '<u>Ion exchange resin</u> softens hard water.', '{"bold":["hard water to soft water"],"italic":[],"underline":["the use of an ion exchange resin"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbjx2qq3oxja4exhxfngk8xrl', 'General Mathematics', 'JAMB', null, 2020, null, 'Differentiate y = e^sin x · ln(cos x).', null, '["e^sin x[cos x ln(cos x) - tan x]","e^sin x[cos x ln(cos x) + tan x]","e^sin x[sin x ln(cos x) - tan x]","e^sin x[sin x ln(cos x) + tan x]"]', 0, 'Product rule: dy/dx = e^sin x[cos x ln(cos x) - tan x].', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Differentiate y = e^sin x · ln(cos x).', '["e^sin x[cos x ln(cos x) - tan x]","e^sin x[cos x ln(cos x) + tan x]","e^sin x[sin x ln(cos x) - tan x]","e^sin x[sin x ln(cos x) + tan x]"]', 'dy/dx = <u>e^sin x[cos x ln(cos x) - tan x]</u>.', '{"bold":[],"italic":[],"underline":["e^sin x[cos x ln(cos x) - tan x]"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbjyx7y4z6gy9tkvfa2mpw8n9', 'Chemistry', 'JAMB', null, 1985, null, 'Which of the following will <b>react further</b> with oxygen to form a higher oxide?', null, '["NO and H2O","CO and CO2","SO2 and NO","CO2 and H2O"]', 2, 'SO2 and NO can be further oxidized to SO3 and NO2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following will <b>react further</b> with oxygen to form a higher oxide?', '["NO and H2O","CO and CO2","SO2 and NO","CO2 and H2O"]', '<u>SO2 and NO</u> can be further oxidized.', '{"bold":["react further"],"italic":[],"underline":["SO2 and NO"],"fillBlanks":[]}');
