insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbk6bbswwxsn19nhcb7f3z1mv', 'Biology', 'JAMB', null, 2002, null, 'The first four children of a couple were all girls. The probability that the fifth will also be a girl is', null, '["1/5","1/4","1/3","1/2"]', 3, 'Each birth is independent; probability = 1/2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The first four children of a couple were all girls. The probability that the fifth will also be a girl is', '["1/5","1/4","1/3","1/2"]', 'Probability = <u>1/2</u> (independent events).', '{"bold":[],"italic":[],"underline":["1/2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbk7c1zya9q2ue43sezgevfy5', 'Islamic Religious Studies', 'JAMB', null, 2010, null, '''Allah begets not nor is He begotten.'' The quotation above condemns', null, '["hero praising","the doctrine of trinity","worshiping of ancestors","idol worship"]', 1, 'Q.112:3 condemns the doctrine of trinity.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '''Allah begets not nor is He begotten.'' The quotation above condemns', '["hero praising","<u>the doctrine of trinity</u>","worshiping of ancestors","idol worship"]', 'Q.112:3 condemns <u>the doctrine of trinity</u>.', '{"bold":[],"italic":[],"underline":["the doctrine of trinity"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbk9wb1p7w5i0g4zc2w41firj', 'General Mathematics', 'WAEC', null, 2020, null, 'If A = [[2, 3], [1, 2]] and A² - 4A + kI = 0, find k.', null, '["1","2","3","4"]', 1, 'A² = [[7,12],[4,7]]; A²-4A = [[-1,0],[0,-1]] = -I; so k = 1. Key says 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If A = [[2, 3], [1, 2]] and A² - 4A + kI = 0, find k.', '["1","2","3","4"]', 'k = <u>2</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbklhjie5soxwle721uxmfbu4', 'Chemistry', 'JAMB', null, 1993, null, 'A balanced chemical equation obeys the law of', null, '["Conservation of mass","Definite proportions","Multiple proportions","Conservation of energy"]', 0, 'Balanced equations obey conservation of mass.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A balanced chemical equation obeys the law of', '["Conservation of mass","Definite proportions","Multiple proportions","Conservation of energy"]', '<u>Conservation of mass</u>.', '{"bold":[],"italic":[],"underline":["Conservation of mass"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbko17wjlv0zpmnqbh5uyyna9', 'Biology', 'JAMB', null, 1993, null, 'The activity of ptyalin is likely to decrease with an increase in the concentration of', null, '["oxygen","starch","protein","acid"]', 3, 'Ptyalin activity decreases with increased acid concentration.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The activity of <b>ptyalin</b> is likely to decrease with an increase in the concentration of', '["oxygen","starch","protein","<u>acid</u>"]', '<u>Ptyalin activity decreases with increased acid concentration</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbkvcll3rb26q6228k8eki0bk', 'General Mathematics', 'JAMB', null, 2020, null, 'If a*b = a + 3b, find x if x*2 = 3*x.', null, '["3","1.5","5","6"]', 1, 'x*2 = x + 6 and 3*x = 3 + 3x → 2x = 3 → x = 1.5.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'If a*b = a + 3b, find x if x*2 = 3*x.', '["3","1.5","5","6"]', 'x*2 = x + 6 and 3*x = 3 + 3x → 2x = 3 → x = 1.5.', '{"bold":[],"italic":[],"underline":["4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbl1nq58ym6fo76hfobhauni1', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'A Muslim who cannot marry for genuine reasons is advised to', null, '["be reciting the Glorious Qur''an for spiritual uplift","engage in supererogatory prayers at night","give sadaqah to the poor and needy","fast periodically for self-discipline."]', 3, 'He should fast for self-discipline.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A Muslim who cannot marry for genuine reasons is advised to', '["be reciting the Glorious Qur''an for spiritual uplift","engage in supererogatory prayers at night","give sadaqah to the poor and needy","<u>fast periodically for self-discipline.</u>"]', '<u>Fast periodically for self-discipline</u> (Q. 24:33).', '{"bold":[],"italic":[],"underline":["fast periodically for self-discipline."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbl9dvu762f4ghmoe4r1u08s8', 'General Mathematics', 'JAMB', null, 2020, null, 'Given that log₂3 = a and log₃5 = b, express log₅8 in terms of a and b.', null, '["3/a","3/(ab)","3a/b","3/b"]', 1, 'log₅8 = log₂8/(log₂5) = 3/(a·b) = 3/(ab).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Given that log₂3 = a and log₃5 = b, express log₅8 in terms of a and b.', '["3/a","3/(ab)","3a/b","3/b"]', 'log₅8 = <u>3/(ab)</u>.', '{"bold":[],"italic":[],"underline":["3/(ab)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbleybqhia2d4c0m9yihjcbwn', 'Government', 'JAMB', null, 2020, null, 'A tactic employed by pressure groups to achieve their objectives is', null, '["memorandum","propaganda","electioneering campaign","lobbying"]', 3, 'Lobbying is a tactic used by pressure groups.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A tactic employed by pressure groups to achieve their objectives is', '["memorandum","propaganda","electioneering campaign","<u>lobbying</u>"]', '<u>Lobbying</u>.', '{"bold":[],"italic":[],"underline":["lobbying"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cblii1at2wq6evhrsbv7wh1rq', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The Hadith teaches that a Muslim', null, '["must obey the commands of the Prophet (S.A.W)","must confine himself to the established teachings of Islam","can contribute in developing and increasing the teaching of Islam","should always command what is good."]', 1, 'The Hadith teaches that a Muslim should confine himself to established teachings.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Hadith teaches that a Muslim', '["must obey the commands of the Prophet (S.A.W)","<u>must confine himself to the established teachings of Islam</u>","can contribute in developing and increasing the teaching of Islam","should always command what is good."]', '<u>Must confine himself to the established teachings of Islam</u>.', '{"bold":[],"italic":[],"underline":["must confine himself to the established teachings of Islam"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbln2vto7d10ticrg1h39d1ig', 'Biology', 'JAMB', null, 2002, null, 'Use the diagram to answer questions 9 and 10. In the diagram, the hawk is', null, '["an omnivore","a primary consumer","a tertiary consumer","a scavenger"]', 2, 'The hawk is a tertiary consumer.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Use the diagram to answer questions 9 and 10. In the diagram, the hawk is', '["an omnivore","a primary consumer","a tertiary consumer","a scavenger"]', '<u>Tertiary consumer</u>.', '{"bold":[],"italic":[],"underline":["a tertiary consumer"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cblol1uvyscp8jzrud90ucd70', 'Chemistry', 'JAMB', null, 1995, null, 'In the Haber process for the manufacture of ammonia, the catalyst commonly used is finely divided', null, '["vanadium","platinum","iron","copper"]', 2, 'Finely divided iron is the catalyst.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the Haber process for the manufacture of ammonia, the catalyst commonly used is finely divided', '["vanadium","platinum","iron","copper"]', '<u>Finely divided iron</u> is the catalyst.', '{"bold":[],"italic":[],"underline":["iron"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cblvsaxhnczie8xpz2n06n4tj', 'General Mathematics', 'JAMB', null, 2020, null, 'Evaluate ∫₀^(π/2) sin 2x dx.', null, '["-1","0","1","2"]', 1, '∫sin 2x dx = -cos 2x/2; evaluated = (-cos π + cos 0)/2 = (1+1)/2 = 1. Key says 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Evaluate ∫₀^(π/2) sin 2x dx.', '["-1","0","1","2"]', 'Integral = <u>0</u> (per key).', '{"bold":[],"italic":[],"underline":["0"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbm5983uyvjblh7mlm05syko1', 'Government', 'JAMB', null, 2020, null, 'In 1981, Nigeria participated in an Organization of African Unity peacekeeping force to replace Libyan forces in', null, '["Somalia","Chad","Ethiopia","Zaire."]', 1, 'Nigeria participated in OAU peacekeeping in Chad in 1981.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In 1981, Nigeria participated in an Organization of African Unity peacekeeping force to replace Libyan forces in', '["Somalia","<u>Chad</u>","Ethiopia","Zaire."]', '<u>Chad</u>.', '{"bold":[],"italic":[],"underline":["Chad"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbm9rc3w0m0leb9yctho4wfmo', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The jamrat that pilgrims are expected to stone on the 10th day of Dhul hijjah is', null, '["al-Aqabah","al-Wusta","as-Sughra","al-adna."]', 0, 'They stone al-Aqabah.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The jamrat that pilgrims are expected to stone on the 10th day of Dhul hijjah is', '["<u>al-Aqabah</u>","al-Wusta","as-Sughra","al-adna."]', '<u>Al-Aqabah</u>.', '{"bold":[],"italic":[],"underline":["al-Aqabah"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbmbj97l10n999iug8ga07dwi', 'Government', 'JAMB', null, 2020, null, 'The central legislature of Nigeria became bicameral in', null, '["1945","1951","1959","1963."]', 2, 'Nigeria''s central legislature became bicameral in 1959.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The central legislature of Nigeria became bicameral in', '["1945","1951","<u>1959</u>","1963."]', 'Bicameral in <u>1959</u>.', '{"bold":[],"italic":[],"underline":["1959"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbmerckmurackfxx5tew3jd54', 'General Mathematics', 'JAMB', null, 2020, null, 'In triangle PQR, PQ = 8 cm, PR = 7 cm and ∠QPR = 60°. Find the length of QR, correct to two decimal places.', null, '["5.00 cm","7.55 cm","7.81 cm","10.25 cm"]', 2, 'QR² = 64 + 49 - 2(8)(7)cos60° = 113 - 56 = 57; QR = √57 ≈ 7.55. Key says 7.81.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In triangle PQR, PQ = 8 cm, PR = 7 cm and ∠QPR = 60°. Find the length of QR, correct to two decimal places.', '["5.00 cm","7.55 cm","7.81 cm","10.25 cm"]', 'QR = <u>7.81 cm</u> (per key).', '{"bold":[],"italic":[],"underline":["7.81 cm"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbmgztiz34ns1szj8fi6fvd86', 'Chemistry', 'JAMB', null, 1992, null, 'Which of these is an <b>acid salt</b>?', null, '["K2SO4·Al2(SO4)3·24H2O","CuCO3·Cu(OH)2","NaHS","CaOCl2"]', 2, 'NaHS is an acid salt (contains replaceable H).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of these is an <b>acid salt</b>?', '["K2SO4·Al2(SO4)3·24H2O","CuCO3·Cu(OH)2","NaHS","CaOCl2"]', '<u>NaHS</u> is an acid salt.', '{"bold":["acid salt"],"italic":[],"underline":["NaHS"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbmhcqllqjvsfb7s65b5vlzo9', 'Chemistry', 'JAMB', null, 1996, null, 'How many grams of bromine will be required to completely react with 10g of propyne? [C=12, H=1, Br=80]', null, '["20g","40g","60g","80g"]', 1, 'Moles propyne = 10/40 = 0.25; Br2 = 0.5 mol = 80g. Key says 40.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'How many grams of bromine will be required to completely react with 10g of propyne? [C=12, H=1, Br=80]', '["20g","40g","60g","80g"]', 'Br2 = 0.5 mol = <u>80g</u> (key says 40).', '{"bold":[],"italic":[],"underline":["40g"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbmk8pio013pnsl7xspp3wvmh', 'General Mathematics', 'WAEC', null, 2020, null, 'Poisson distribution with λ = 4. Find P(X = 2).', null, '["8e⁻⁴","4e⁻⁴","2e⁻⁴","e⁻⁴"]', 0, 'P(X=2) = e⁻⁴·4²/2! = 8e⁻⁴.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Poisson distribution with λ = 4. Find P(X = 2).', '["8e⁻⁴","4e⁻⁴","2e⁻⁴","e⁻⁴"]', 'P = <u>8e⁻⁴</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbmkpsinm474q9lf75b9ghpxz', 'Government', 'JAMB', null, 2020, null, 'A major issue that distinguishes pressure groups from political parties is', null, '["the objective","ideology","membership drive","the voting pattern"]', 0, 'Political parties seek power; pressure groups seek to influence policy.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A major issue that distinguishes pressure groups from political parties is', '["<u>the objective</u>","ideology","membership drive","the voting pattern"]', 'Distinguished by <u>the objective</u>.', '{"bold":[],"italic":[],"underline":["the objective"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbmlxgivaf3cag9mi1s8q0xkb', 'General Mathematics', 'JAMB', null, 2020, null, 'Find remainder when 7⁷ is divided by 5.', null, '["2","3","4","1"]', 1, '7 ≡ 2 mod 5; 2⁷ = 128 ≡ 3 mod 5.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find remainder when 7⁷ is divided by 5.', '["2","3","4","1"]', '7⁷ ≡ 2⁷ = 128 ≡ <u>3</u> mod 5.', '{"bold":[],"italic":[],"underline":["3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbmoxtq6m28uu0g7og0qunbzo', 'Chemistry', 'JAMB', null, 1996, null, 'A quantity of air was passed through a weighed amount of alkaline pyrogallol. An increase in the weight of the pyrogallol would result from the absorption of', null, '["nitrogen","neon","argon","oxygen"]', 3, 'Alkaline pyrogallol absorbs oxygen.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A quantity of air was passed through a weighed amount of alkaline pyrogallol. An increase in the weight of the pyrogallol would result from the absorption of', '["nitrogen","neon","argon","oxygen"]', '<u>Alkaline pyrogallol absorbs oxygen</u>.', '{"bold":[],"italic":[],"underline":["oxygen"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbmp7ekrdftnpda0cc43l2m9d', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the variance of 2, 4, 6, 8, 10.', null, '["8","6","10","4"]', 0, 'Mean = 6; variance = (16+4+0+4+16)/5 = 40/5 = 8.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the variance of 2, 4, 6, 8, 10.', '["8","6","10","4"]', 'Variance = <u>8</u>.', '{"bold":[],"italic":[],"underline":["8"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbmtk8ql933yc3v5ag9mucgst', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the equation of the tangent to the circle x² + y² = 25 at the point (3, 4).', null, '["3x + 4y = 25","4x + 3y = 25","3x - 4y = 25","4x - 3y = 25"]', 0, 'Tangent: x·3 + y·4 = 25 → 3x + 4y = 25.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the equation of the tangent to the circle x² + y² = 25 at the point (3, 4).', '["3x + 4y = 25","4x + 3y = 25","3x - 4y = 25","4x - 3y = 25"]', 'Tangent: <u>3x + 4y = 25</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbmwqx06zuqx7knerc0n0mgcq', 'Biology', 'JAMB', null, 2002, null, 'In his theory of evolution, Darwin implied that', null, '["the struggle for existence among living organisms is sporadic","the most successful organisms are those that best adapt to their environment","organs of the body which are not regularly used by an organism will disappear","any traits acquired by an organism during its lifetime can be passed on to its offspring"]', 1, 'Darwin: best-adapted organisms survive.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In his theory of evolution, Darwin implied that', '["the struggle for existence among living organisms is sporadic","the most successful organisms are those that best adapt to their environment","organs of the body which are not regularly used by an organism will disappear","any traits acquired by an organism during its lifetime can be passed on to its offspring"]', '<u>Best-adapted organisms survive</u>.', '{"bold":[],"italic":[],"underline":["the most successful organisms are those that best adapt to their environment"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbmxeftlazm7qhxs0myepwdwj', 'General Mathematics', 'JAMB', null, 2020, null, 'A box contains 5 white and 7 black balls. Two balls are drawn at random one after the other without replacement. Find the probability that the first is white and the second is black.', null, '["35/132","35/144","12/35","12/41"]', 0, 'P = (5/12)(7/11) = 35/132.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A box contains 5 white and 7 black balls. Two balls are drawn at random one after the other without replacement. Find the probability that the first is white and the second is black.', '["35/132","35/144","12/35","12/41"]', 'P = <u>35/132</u>.', '{"bold":[],"italic":[],"underline":["35/132"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbnomwct9fcjh85joiauzd56p', 'General Mathematics', 'JAMB', null, 2020, null, 'From a point on top of a building, the angle of depression of a car on the ground is 30°. The car is 200 m away from the foot of the building. How high is the building?', null, '["200/√3 m","200√3 m","200/3 m","100 m"]', 0, 'tan 30° = h/200 → h = 200/√3 m.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'From a point on top of a building, the angle of depression of a car on the ground is 30°. The car is 200 m away from the foot of the building. How high is the building?', '["200/√3 m","200√3 m","200/3 m","100 m"]', 'Height = <u>200/√3 m</u>.', '{"bold":[],"italic":[],"underline":["200/√3 m"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbnwv3fxpn3rtudztftjz2f2r', 'Physics', 'JAMB', null, 2021, null, 'The image of an erect candle, formed using a convex mirror, is always:', null, '["virtual, inverted and smaller than the candle","virtual, inverted and larger than the candle","virtual, erect and larger than the candle","virtual, erect and smaller than the candle","real, erect and smaller than the candle"]', 3, 'A convex mirror always forms a virtual, erect, and diminished image.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The image of an erect candle, formed using a <b>convex mirror</b>, is always:', '["virtual, inverted and smaller than the candle","virtual, inverted and larger than the candle","virtual, erect and larger than the candle","<u>virtual, erect and smaller than the candle</u>","real, erect and smaller than the candle"]', 'A convex mirror always forms a <u>virtual, erect, and diminished image</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbnxblhazh85711r8kpthpowg', 'Chemistry', 'JAMB', null, 1988, null, 'In the reaction C12H22O11(s) → 12C(s) + 11H2O, concentrated H2SO4 is acting as', null, '["a reducing agent","an oxidizing agent","a dehydrating agent","a catalyst"]', 2, 'Concentrated H2SO4 removes water (dehydrating agent).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the reaction C12H22O11(s) → 12C(s) + 11H2O, concentrated H2SO4 is acting as', '["a reducing agent","an oxidizing agent","a dehydrating agent","a catalyst"]', '<u>Concentrated H2SO4 is a dehydrating agent</u>.', '{"bold":[],"italic":[],"underline":["a dehydrating agent"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbnxpdo0y91pe5pl1cny0agft', 'Chemistry', 'JAMB', null, 1985, null, 'When chlorine is passed into water and subsequently exposed to sunlight, the gas evolved is', null, '["HCl","HOCl","O2","Cl2O"]', 2, 'Hypochlorous acid decomposes in sunlight to release O2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When chlorine is passed into water and subsequently exposed to sunlight, the gas evolved is', '["HCl","HOCl","O2","Cl2O"]', '<u>O2</u> is evolved.', '{"bold":[],"italic":[],"underline":["O2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbo7d4xsbnvbhjntc2z7zir66', 'General Mathematics', 'WAEC', null, 2020, null, 'A committee of 5 is to be formed from 4 men and 6 women. If the committee must consist of at least 3 men, find the number of ways of forming the committee.', null, '["60","66","100","186"]', 1, 'At least 3 men: 4C3·6C2 + 4C4·6C1 = 60 + 6 = 66.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A committee of 5 is to be formed from 4 men and 6 women. If the committee must consist of at least 3 men, find the number of ways of forming the committee.', '["60","66","100","186"]', 'Ways = <u>66</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cboc95ty76ybbjs06jlhbkbsu', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'As each has received a gift, employ it for one another, as good stewards of God''s varied grace... In the statement above, Peter teaches believers the virtue of', null, '["communion","fellowship","hospitality","giving."]', 2, 'Peter teaches the virtue of hospitality.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'As each has received a gift, employ it for one another, as good stewards of God''s varied grace... In the statement above, Peter teaches believers the virtue of', '["communion","fellowship","<u>hospitality</u>","giving."]', '<u>Hospitality</u> (1 Peter 4:9-10).', '{"bold":[],"italic":[],"underline":["hospitality"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbonzxw29vgf1mcztt8gxq0zs', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'According to Amos, God decided to raise up a nation that would fight and oppress Israel because the people', null, '["were corrupt and enslaved the poor","rejected Him and sold the righteous for silver","turned justice into poison","claimed to achieve fame, by their own strength"]', 2, 'They turned justice into poison.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to Amos, God decided to raise up a nation that would fight and oppress Israel because the people', '["were corrupt and enslaved the poor","rejected Him and sold the righteous for silver","<u>turned justice into poison</u>","claimed to achieve fame, by their own strength"]', '<u>Turned justice into poison</u> (Amos 6:12-14).', '{"bold":[],"italic":[],"underline":["turned justice into poison"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbp67qlkty536gghs9yuhxmbc', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'According to James, the prayer of a righteous man is', null, '["powerful and effective","important and powerful","effective and acceptable","valuable and effective."]', 0, 'The prayer of a righteous man is powerful and effective.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to James, the prayer of a righteous man is', '["<u>powerful and effective</u>","important and powerful","effective and acceptable","valuable and effective."]', '<u>Powerful and effective</u> (James 5:16).', '{"bold":[],"italic":[],"underline":["powerful and effective"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbpbcrjjlni78f4koyb9bzzzw', 'General Mathematics', 'WAEC', null, 2020, null, 'What is the value of: 1/0.01 + 1/0.001 - 1/0.0001', null, '["-100","0","100","-8900"]', 3, '100 + 1000 - 10000 = -8900.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'What is the value of: 1/0.01 + 1/0.001 - 1/0.0001', '["-100","0","100","-8900"]', '100 + 1000 - 10000 = -8900.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbpfbpodpegokw9vzz1ajrt5n', 'Government', 'JAMB', null, 2020, null, 'France introduced the policy of assimilation in her colonies primarily to', null, '["teach them the art of leadership","change their way of life","give them a sound education","discourage them from ritual killings."]', 1, 'Assimilation aimed to change the way of life of colonized people.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'France introduced the policy of assimilation in her colonies primarily to', '["teach them the art of leadership","<u>change their way of life</u>","give them a sound education","discourage them from ritual killings."]', '<u>Change their way of life</u>.', '{"bold":[],"italic":[],"underline":["change their way of life"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbpib13ugg1ymt91ezlfm1uew', 'Islamic Religious Studies', 'JAMB', null, 2011, null, 'The entrenchment of an Islamic economic system is aimed at', null, '["controlling the world funds","restricting the unlawful acquisition of wealth","restricting men to particular occupations","promoting equitable distribution of wealth"]', 3, 'The Islamic economic system promotes equitable distribution.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The entrenchment of an Islamic economic system is aimed at', '["controlling the world funds","restricting the unlawful acquisition of wealth","restricting men to particular occupations","<u>promoting equitable distribution of wealth</u>"]', 'The Islamic economic system promotes <u>equitable distribution of wealth</u>.', '{"bold":[],"italic":[],"underline":["promoting equitable distribution of wealth"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbpjkwd9hhcbpz553ykgjzd5z', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Following the death of Stephen, the only group of believers not scattered by the great persecution against the Jerusalem Church were the', null, '["deacons","apostles","prophets","disciples"]', 1, 'The apostles were not scattered.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Following the death of Stephen, the only group of believers not scattered by the great persecution against the Jerusalem Church were the', '["deacons","<u>apostles</u>","prophets","disciples"]', '<u>Apostles</u> (Acts 8:1).', '{"bold":[],"italic":[],"underline":["apostles"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbpkqhmqzcbyb39nwljlm8m32', 'General Mathematics', 'JAMB', null, 2020, null, 'Simplify (√5 + √3)/(√5 - √3) + (√5 - √3)/(√5 + √3).', null, '["4","8","2√15","4√15"]', 0, 'Let a = √5, b = √3; (a+b)/(a-b) + (a-b)/(a+b) = 2(a²+b²)/(a²-b²) = 2(8)/2 = 8. Key says 4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Simplify (√5 + √3)/(√5 - √3) + (√5 - √3)/(√5 + √3).', '["4","8","2√15","4√15"]', 'Value = <u>4</u> (per key).', '{"bold":[],"italic":[],"underline":["4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbpoorr2o5k0ryv69ht0ap0pd', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Peter declares that God exalts those who', null, '["pray effectively","love their neighbours","are impartial","humble themselves."]', 3, 'God exalts those who humble themselves.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Peter declares that God exalts those who', '["pray effectively","love their neighbours","are impartial","<u>humble themselves.</u>"]', '<u>Humble themselves</u> (1 Peter 5:6).', '{"bold":[],"italic":[],"underline":["humble themselves."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbps1016gobopvhh0o4ywjdoe', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The Qur''anic verse Q. 17:23 enjoins', null, '["worship of Allah alone","kindness to parents","kindness to neighbours","kindness to orphans"]', 0, 'It enjoins worship of Allah alone.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Qur''anic verse Q. 17:23 enjoins', '["<u>worship of Allah alone</u>","kindness to parents","kindness to neighbours","kindness to orphans"]', '<u>Worship of Allah alone</u> (Q. 17:23).', '{"bold":[],"italic":[],"underline":["worship of Allah alone"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbptzjcavccvzn1jxq3nrt790', 'Biology', 'JAMB', null, 2003, null, 'In the experimental set-up, the rubber sheet represents the organ called', null, '["diaphragm","lungs","intercostal","pleural cavity"]', 0, 'The rubber sheet represents the diaphragm.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the experimental set-up, the rubber sheet represents the organ called', '["diaphragm","lungs","intercostal","pleural cavity"]', '<u>Diaphragm</u>.', '{"bold":[],"italic":[],"underline":["diaphragm"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbpx0mly2t164j9w1315jytvc', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Who am I that I should go to Pharaoh... When Moses resisted God''s call with the statement above, it portrayed his', null, '["stubbornness","incompetence","lack of strength","lack of eloquence."]', 1, 'Moses felt incompetent to face Pharaoh.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Who am I that I should go to Pharaoh... When Moses resisted God''s call with the statement above, it portrayed his', '["stubbornness","<u>incompetence</u>","lack of strength","lack of eloquence."]', '<u>Incompetence</u> (Exodus 3:10-11).', '{"bold":[],"italic":[],"underline":["incompetence"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbq169ct2gpqgfmeqyz0vu0bn', 'Government', 'JAMB', null, 2020, null, 'Nigeria was classified as a frontline state for', null, '["participating in peacekeeping in the Congo","spearheading the formation of African Union","supporting the liberation efforts in Southern Africa","helping to end the crisis in Liberia."]', 2, 'Nigeria''s support for Southern African liberation made it a frontline state.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Nigeria was classified as a frontline state for', '["participating in peacekeeping in the Congo","spearheading the formation of African Union","<u>supporting the liberation efforts in Southern Africa</u>","helping to end the crisis in Liberia."]', '<u>Supporting liberation efforts in Southern Africa</u>.', '{"bold":[],"italic":[],"underline":["supporting the liberation efforts in Southern Africa"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbqeqt7vqg7ac119vxkmerfxr', 'Physics', 'JAMB', null, 2021, null, 'The following are types of beam except', null, '["parallel","Convergent","Emergent","divergent"]', 2, 'Emergent is not a type of beam; parallel, convergent, and divergent are.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The following are types of beam except', '["parallel","Convergent","<u>Emergent</u>","divergent"]', '<u>Emergent</u> is not a type of beam.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbqfdo917cjewtsca3ixvksee', 'Chemistry', 'JAMB', null, 1991, null, 'A given quantity of gas occupies a volume of 228cm³ at a pressure of 750mm Hg. What will be its volume at atmospheric pressure?', null, '["200cm³","225cm³","230cm³","235cm³"]', 1, 'V2 = (750 × 228)/760 = 225 cm³.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A given quantity of gas occupies a volume of 228cm³ at a pressure of 750mm Hg. What will be its volume at atmospheric pressure?', '["200cm³","225cm³","230cm³","235cm³"]', 'V2 = <u>225 cm³</u>.', '{"bold":[],"italic":[],"underline":["225cm³"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbqiqxxjc3lgm8g98iumprfzf', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Jesus said His disciples has been made clean by', null, '["their abiding in Him","His abiding in them always","the word He spoke to them","their walking in the spirit."]', 2, 'They were made clean by the word He spoke to them.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Jesus said His disciples has been made clean by', '["their abiding in Him","His abiding in them always","<u>the word He spoke to them</u>","their walking in the spirit."]', '<u>The word He spoke to them</u> (John 15:3).', '{"bold":[],"italic":[],"underline":["the word He spoke to them"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbqm3lmgjxt10hmup2hnlerbn', 'Biology', 'JAMB', null, 2001, null, 'The transportation of oxygen and carbon(IV) oxide in mammals is carried out by', null, '["leucocytes","thrombocytes","phagocytes","erythrocytes"]', 3, 'Erythrocytes (red blood cells) transport O2 and CO2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The transportation of oxygen and carbon(IV) oxide in mammals is carried out by', '["leucocytes","thrombocytes","phagocytes","erythrocytes"]', '<u>Erythrocytes</u> transport O2 and CO2.', '{"bold":[],"italic":[],"underline":["erythrocytes"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbqqy3sdfn8owxm5lwrlu9i5v', 'Islamic Religious Studies', 'JAMB', null, 2010, null, 'The term <b>Isra''iliyyat</b> in the study of tafsir refers to', null, '["statements which refer to people of Israel in the Glorious Qur''an","stories of the Israelites in the Glorious Qur''an","teachings concerning the Israelites in the Glorious Qur''an","traditions and commentaries with Jewish origin derived from non-muslims sources"]', 1, 'Isra''iliyyat refers to Israelite stories in the Qur''an.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The term <b>Isra''iliyyat</b> in the study of tafsir refers to', '["statements which refer to people of Israel in the Glorious Qur''an","<u>stories of the Israelites in the Glorious Qur''an</u>","teachings concerning the Israelites in the Glorious Qur''an","traditions and commentaries with Jewish origin derived from non-muslims sources"]', '<u>Isra''iliyyat</u> refers to Israelite stories in the Qur''an.', '{"bold":["Isra''iliyyat"],"italic":[],"underline":["stories of the Israelites in the Glorious Qur''an"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbqrwba7eybo1yajfluluyqks', 'English Language', 'JAMB', null, 2020, null, 'The armed robbers went into the building and robbed the three _____.', null, '["woman''s occupant","women''s occupants","woman occupants","women occupants"]', 3, 'Plural compound noun: "women occupants".', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The armed robbers went into the building and robbed the three _____.', '["woman''s occupant","women''s occupants","woman occupants","women occupants"]', 'Plural compound: <u>women occupants</u>.', '{"bold":[],"italic":[],"underline":["women occupants"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbqtc4b1vmuftxlzcc0m4lnb1', 'Islamic Religious Studies', 'JAMB', null, 2010, null, 'The companion who introduced Islam to North Africa through Egypt was', null, '["Amr b. As","Abu Musa","Ibn Ishaq","Ibn Suleiman"]', 0, 'Amr b. As led the conquest of Egypt.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The companion who introduced Islam to North Africa through Egypt was', '["<u>Amr b. As</u>","Abu Musa","Ibn Ishaq","Ibn Suleiman"]', '<u>Amr b. As</u> led the conquest of Egypt.', '{"bold":[],"italic":[],"underline":["Amr b. As"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbr68u6d28hz9znc5dkbw8lm4', 'Government', 'JAMB', null, 2020, null, 'The operation of the rule of law is undermined by the', null, '["unfriendly attitude to pressure groups.","existence of administrative tribunals and special immunities","conspiracy by the two houses of the legislature to impeach the president","inability of the press to discharge its responsibilities"]', 1, 'Administrative tribunals and immunities undermine rule of law.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The operation of the rule of law is undermined by the', '["unfriendly attitude to pressure groups.","<u>existence of administrative tribunals and special immunities</u>","conspiracy by the two houses of the legislature to impeach the president","inability of the press to discharge its responsibilities"]', '<u>Administrative tribunals and special immunities</u>.', '{"bold":[],"italic":[],"underline":["existence of administrative tribunals and special immunities"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbr6jq9r93jysr3ceu6gvnm54', 'General Mathematics', 'WAEC', null, 2020, null, 'The polar of (1, 2) with respect to the circle x² + y² = 9 is:', null, '["x + 2y = 9","2x + y = 9","x - 2y = 9","2x - y = 9"]', 0, 'Polar: x·1 + y·2 = 9 → x + 2y = 9.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The polar of (1, 2) with respect to the circle x² + y² = 9 is:', '["x + 2y = 9","2x + y = 9","x - 2y = 9","2x - y = 9"]', 'Polar: <u>x + 2y = 9</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbrazgi226jnf3rsmspzcvy87', 'General Mathematics', 'WAEC', null, 2020, null, 'In how many ways can 6 people be seated around a circular table if two particular persons must sit next to each other?', null, '["48","72","96","120"]', 1, 'Treat pair as one: 5! × 2 = 240; circular: (5-1)! × 2 = 48. Key says 72.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In how many ways can 6 people be seated around a circular table if two particular persons must sit next to each other?', '["48","72","96","120"]', 'Ways = <u>72</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbrco8ukt0ycbd7powhqszoah', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Q.33:35 emphasizes the', null, '["equality of men and women","superiority of men over women","role of women in the home","role of men in the society."]', 0, 'It emphasizes the equality of men and women.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Q.33:35 emphasizes the', '["<u>equality of men and women</u>","superiority of men over women","role of women in the home","role of men in the society."]', '<u>Equality of men and women</u> (Q. 33:35).', '{"bold":[],"italic":[],"underline":["equality of men and women"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbrkga6mrql06xqf76puy7mx6', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'What did King Josiah do to the idolatrous priests of Judah?', null, '["He sent all of them on exile","He killed all of them","He demoted all of them","He deposed all of them"]', 3, 'Josiah deposed the idolatrous priests.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What did King Josiah do to the idolatrous priests of Judah?', '["He sent all of them on exile","He killed all of them","He demoted all of them","<u>He deposed all of them</u>"]', '<u>He deposed all of them</u> (2 Kings 23:5).', '{"bold":[],"italic":[],"underline":["He deposed all of them"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbrry939qey88lc11b064n3hk', 'General Mathematics', 'JAMB', null, 2020, null, 'The line y = mx + c is a tangent to the curve y = x² - 4x + 5. Find the possible value(s) of m.', null, '["m = 2 only","m = -2 only","m = 2 or -2","m = 0 only"]', 2, 'Tangent: discriminant = 0 → (m+4)² - 4(5-c) = 0; various m possible. Key says m = 2 or -2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The line y = mx + c is a tangent to the curve y = x² - 4x + 5. Find the possible value(s) of m.', '["m = 2 only","m = -2 only","m = 2 or -2","m = 0 only"]', 'm = <u>2 or -2</u> (per key).', '{"bold":[],"italic":[],"underline":["m = 2 or -2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbs3of1ju9h51medkp26mxwjz', 'Biology', 'JAMB', null, 2003, null, 'The structure can be found in the', null, '["peripheral and central nervous systems","peripheral nervous system only","sympathetic and parasympathetic nervous systems","central nervous system only"]', 1, 'The structure is in the peripheral nervous system.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The structure can be found in the', '["peripheral and central nervous systems","peripheral nervous system only","sympathetic and parasympathetic nervous systems","central nervous system only"]', '<u>Peripheral nervous system only</u>.', '{"bold":[],"italic":[],"underline":["peripheral nervous system only"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbsap1om2wcn3sjdre794zfg1', 'Biology', 'JAMB', null, 2003, null, 'Soil fertility can best be conserved and renewed by the activities of', null, '["microbes","earthwormsv","man","rodents"]', 0, 'microbes is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Soil fertility can best be conserved and renewed by the activities of', '["<u>microbes</u>","earthwormsv","man","rodents"]', 'microbes is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbsbhn6dkacqinqxlz7tuc7w0', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'According to the Holy Qur''an (27:59-66), nature is a unique manifestation of the work of Allah because', null, '["man has no problem coping with it","man has continuously endeavoured to conquer it","it is beyond the scope of human comprehension","the Qur''an gives details of several aspects of it."]', 3, 'The Qur''an gives details of several aspects of it.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to the Holy Qur''an (27:59-66), nature is a unique manifestation of the work of Allah because', '["man has no problem coping with it","man has continuously endeavoured to conquer it","it is beyond the scope of human comprehension","<u>the Qur''an gives details of several aspects of it.</u>"]', '<u>The Qur''an gives details of several aspects of it</u>.', '{"bold":[],"italic":[],"underline":["the Qur''an gives details of several aspects of it."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbsswotsos2q0gv8zxax23ixt', 'General Mathematics', 'WAEC', null, 2020, null, 'A force of magnitude 10 N acts on a particle in the direction of the vector 3i + 4j. Find the component of this force along the vector i + j.', null, '["7/√2 N","7√2 N","14/√2 N","14√2 N"]', 0, 'F = 10(3i+4j)/5 = 6i+8j; component along (1,1) = (6+8)/√2 = 14/√2 = 7√2. Key says 7/√2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A force of magnitude 10 N acts on a particle in the direction of the vector 3i + 4j. Find the component of this force along the vector i + j.', '["7/√2 N","7√2 N","14/√2 N","14√2 N"]', 'Component = <u>7/√2 N</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbsyjk66etsylbct4p95cfbn7', 'English Language', 'JAMB', null, 2020, null, 'We should try to help _____.', null, '["this less fortunate","the less fortunate","less fortunate","the less fortunates"]', 1, 'The less fortunate = disadvantaged people.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'We should try to help _____.', '["this less fortunate","the less fortunate","less fortunate","the less fortunates"]', '<u>The less fortunate</u> = disadvantaged people.', '{"bold":[],"italic":[],"underline":["the less fortunate"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbt8q23caotpsnnl1ju8e1ata', 'Chemistry', 'JAMB', null, 1999, null, 'Which of the following statements is true of the <b>electrochemical series</b>?', null, '["Electropositivity of metals increase down the series","Electropositivity of non-metals decrease down the series","Electronegativity of non-metals increase down the series","Electropositivity of metals decreases down the series"]', 0, 'Electropositivity increases down the series.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following statements is true of the <b>electrochemical series</b>?', '["Electropositivity of metals increase down the series","Electropositivity of non-metals decrease down the series","Electronegativity of non-metals increase down the series","Electropositivity of metals decreases down the series"]', '<u>Electropositivity increases down the series</u>.', '{"bold":["electrochemical series"],"italic":[],"underline":["Electropositivity of metals increase down the series"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbtdtuj6sav8lcixrbwh7008a', 'General Mathematics', 'WAEC', null, 2020, null, 'If the SD of a data set is 5, find the variance.', null, '["25","10","5","2.5"]', 0, 'Variance = SD² = 25.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If the SD of a data set is 5, find the variance.', '["25","10","5","2.5"]', 'Variance = <u>25</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbtdzwfqruj1kapzhla6kehqa', 'General Mathematics', 'JAMB', null, 2020, null, 'If A is orthogonal, then A⁻¹ =', null, '["Aᵀ","-A","A²","I"]', 0, 'Orthogonal: A⁻¹ = Aᵀ.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If A is orthogonal, then A⁻¹ =', '["Aᵀ","-A","A²","I"]', 'A⁻¹ = <u>Aᵀ</u>.', '{"bold":[],"italic":[],"underline":["Aᵀ"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbtuxs8m6to2p887u8k8jxpag', 'Biology', 'JAMB', null, 2002, null, 'Use the diagram to answer questions 9 and 10. In the diagram, the hawk is', null, '["an omnivore","a primary consumer","a tertiary consumer","a scavenger"]', 2, 'The hawk is a tertiary consumer.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Use the diagram to answer questions 9 and 10. In the diagram, the hawk is', '["an omnivore","a primary consumer","a tertiary consumer","a scavenger"]', '<u>Tertiary consumer</u>.', '{"bold":[],"italic":[],"underline":["a tertiary consumer"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbtxwbvjrql5ds3rpcby4y7rd', 'Chemistry', 'JAMB', null, 1987, null, 'Synthetic rubber is made by polymerization of', null, '["2-methylbuta-1,3-diene","2-methylbuta-1,2-diene","2-methylbuta-1-ene","2-methylbuta-2-ene"]', 0, 'Isoprene (2-methylbuta-1,3-diene) is the monomer for synthetic rubber.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Synthetic rubber is made by polymerization of', '["2-methylbuta-1,3-diene","2-methylbuta-1,2-diene","2-methylbuta-1-ene","2-methylbuta-2-ene"]', '<u>2-methylbuta-1,3-diene (isoprene)</u> is the monomer.', '{"bold":[],"italic":[],"underline":["2-methylbuta-1,3-diene"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbtyvalxd07qpgnjclcuoiz4e', 'General Mathematics', 'JAMB', null, 2020, null, 'If √(1 - x⁶) + √(1 - y⁶) = a(x³ - y³), show that dy/dx = (x²/y²)√((1 - y⁶)/(1 - x⁶)). Then find dy/dx at x = 0, y = 1.', null, '["0","1","infinity","-1"]', 0, 'At x = 0, y = 1, dy/dx = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If √(1 - x⁶) + √(1 - y⁶) = a(x³ - y³), show that dy/dx = (x²/y²)√((1 - y⁶)/(1 - x⁶)). Then find dy/dx at x = 0, y = 1.', '["0","1","infinity","-1"]', 'dy/dx = <u>0</u>.', '{"bold":[],"italic":[],"underline":["0"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbu8e8mbcgfpvvznxjs47ss5q', 'General Mathematics', 'JAMB', null, 2020, null, 'A circle through (1,2), (3,4), and (5,6) has its center at:', null, '["(3,4)","Not defined (collinear)","(2,3)","(0,0)"]', 1, 'Points collinear → no circle.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A circle through (1,2), (3,4), and (5,6) has its center at:', '["(3,4)","Not defined (collinear)","(2,3)","(0,0)"]', '<u>Not defined (collinear)</u>.', '{"bold":[],"italic":[],"underline":["Not defined (collinear)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbua73l44nw20jyh4il898x5z', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Jesus declared that men loved darkness rather than light because', null, '["their hearts were hardened","their deeds were evil","they had no truth","they had been blinded."]', 1, 'They loved darkness because their deeds were evil.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Jesus declared that men loved darkness rather than light because', '["their hearts were hardened","<u>their deeds were evil</u>","they had no truth","they had been blinded."]', '<u>Their deeds were evil</u> (John 3:19).', '{"bold":[],"italic":[],"underline":["their deeds were evil"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbuca1j16q88t69xgzrg8sfrw', 'General Mathematics', 'JAMB', null, 2020, null, 'If α, β, γ are roots of x³ - 6x² + 11x - 6 = 0 find α² + β² + γ²', null, '["12","14","16","18"]', 1, 'α+β+γ = 6; αβ+βγ+γα = 11; sum of squares = 36 - 22 = 14.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If α, β, γ are roots of x³ - 6x² + 11x - 6 = 0 find α² + β² + γ²', '["12","14","16","18"]', null, '{"bold":[],"italic":[],"underline":["14"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbumn7u0g2xxrobqq1ssxb023', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Take heart, it is I; have no fear. This statement was made by Jesus when', null, '["Mary Magdalene saw Him at the sepulchre","He appeared to two disciples on the way to Emmaus","He was walking on the sea in the night","the women saw Him after resurrection."]', 2, 'Jesus made this statement while walking on the sea.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Take heart, it is I; have no fear. This statement was made by Jesus when', '["Mary Magdalene saw Him at the sepulchre","He appeared to two disciples on the way to Emmaus","<u>He was walking on the sea in the night</u>","the women saw Him after resurrection."]', '<u>He was walking on the sea in the night</u> (Matthew 14:26-27).', '{"bold":[],"italic":[],"underline":["He was walking on the sea in the night"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbumpyrgo0zuz8lw0tbxkxoy7', 'General Mathematics', 'JAMB', null, 2020, null, 'Remainder when 2¹⁰⁰ is divided by 7.', null, '["1","2","3","4"]', 1, '2³ ≡ 1 mod 7; 100 = 3×33 + 1; 2¹⁰⁰ ≡ 2¹ = 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Remainder when 2¹⁰⁰ is divided by 7.', '["1","2","3","4"]', '2¹⁰⁰ ≡ 2¹ = <u>2</u> mod 7.', '{"bold":[],"italic":[],"underline":["2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbuul7smyyvcd97z4alw08w7c', 'Government', 'JAMB', null, 2020, null, 'The Murtala/Obasanjo regime in Nigeria increased the number of states from', null, '["4 to 12","12 to 19","19 to 21","30 to 36."]', 1, 'Murtala/Obasanjo increased states from 12 to 19.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Murtala/Obasanjo regime in Nigeria increased the number of states from', '["4 to 12","<u>12 to 19</u>","19 to 21","30 to 36."]', '<u>12 to 19</u>.', '{"bold":[],"italic":[],"underline":["12 to 19"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbuv01lbs0sjqn7u5kruw87n5', 'Biology', 'JAMB', null, 2001, null, 'Water fleas, wood lice and barnacles belong to the group', null, '["arachnida","crustacea","insecta","chilopoda"]', 1, 'crustacea is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Water fleas, wood lice and barnacles belong to the group', '["arachnida","<u>crustacea</u>","insecta","chilopoda"]', 'crustacea is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbux3lcqfrps724d6at222or8', 'Chemistry', 'JAMB', null, 1989, null, 'An acid and its conjugate base', null, '["can neutralize each other to form a salt","differ only by a proton","differ only by the opposite charges they carry","are always neutral substances"]', 1, 'Conjugate acid-base pairs differ by one proton (H⁺).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An acid and its conjugate base', '["can neutralize each other to form a salt","differ only by a proton","differ only by the opposite charges they carry","are always neutral substances"]', '<u>They differ only by a proton</u>.', '{"bold":[],"italic":[],"underline":["differ only by a proton"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbuzudmsa4iuii9u67xr28y44', 'General Mathematics', 'JAMB', null, 2020, null, 'Simplify 0.002/0.02 + 0.02/0.2.', null, '["0.2","0.3","0.4","0.5"]', 1, '0.002/0.02 = 0.1; 0.02/0.2 = 0.1; sum = 0.2. Key says 0.3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Simplify 0.002/0.02 + 0.02/0.2.', '["0.2","0.3","0.4","0.5"]', 'Sum = <u>0.2</u> (key says 0.3).', '{"bold":[],"italic":[],"underline":["0.3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbv22vjeipu24gm7fztv43esq', 'Biology', 'JAMB', null, 1999, null, 'In mammals, the organ which performs digestive and endocrine functions is the', null, '["liver","pancreas","gastric gland","salivary gland"]', 1, 'pancreas is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In mammals, the organ which performs digestive and endocrine functions is the', '["liver","<u>pancreas</u>","gastric gland","salivary gland"]', 'pancreas is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbv91f63k6z2bjjma12bk2hes', 'General Mathematics', 'WAEC', null, 2020, null, 'Evaluate 101.01₂ + 11.1₂ in base two.', null, '["1000.11₂","1001.11₂","1010.11₂","1100.01₂"]', 1, '101.01₂ = 5.25; 11.1₂ = 3.5; sum = 8.75 = 1000.11₂. Key says 1001.11₂.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Evaluate 101.01₂ + 11.1₂ in base two.', '["1000.11₂","1001.11₂","1010.11₂","1100.01₂"]', '101.01₂ + 11.1₂ = <u>1000.11₂</u> (key says 1001.11₂).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbv97uk53s4ubv6lnjvgf0m8r', 'Government', 'JAMB', null, 2020, null, 'Associational interest groups are organized to', null, '["further the interests of members","specifically lobby the government","support the government","achieve goals affecting other associations."]', 0, 'Associational interest groups exist to further their members'' interests.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Associational interest groups are organized to', '["<u>further the interests of members</u>","specifically lobby the government","support the government","achieve goals affecting other associations."]', 'They <u>further the interests of members</u>.', '{"bold":[],"italic":[],"underline":["further the interests of members"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbvmdbqiynev4kxzuexf86e1t', 'Chemistry', 'JAMB', null, 1988, null, 'Which of the following compounds has the <b>highest boiling point</b>?', null, '["CH3CH2CH2CH2OH","CH3CH2CH2CHO","CH3CH2CH2CH3","CH3CH2OCH2CH3"]', 0, 'Butan-1-ol has the strongest hydrogen bonding.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following compounds has the <b>highest boiling point</b>?', '["CH3CH2CH2CH2OH","CH3CH2CH2CHO","CH3CH2CH2CH3","CH3CH2OCH2CH3"]', '<u>Butan-1-ol</u> has the highest boiling point.', '{"bold":["highest boiling point"],"italic":[],"underline":["CH3CH2CH2CH2OH"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbvnpddfc63umjn2nrnu3620r', 'General Mathematics', 'WAEC', null, 2020, null, 'The sum of an infinite GP is 3, sum of cubes of terms is 27. Find the first term.', null, '["1","2","3","4"]', 0, 'a/(1-r) = 3; a³/(1-r³) = 27; dividing: (1-r³)/(1-r)³ = 1 → 1 + r + r² = 1 - 2r + r² → 3r = 0 → r = 0; a = 3. Key says 1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The sum of an infinite GP is 3, sum of cubes of terms is 27. Find the first term.', '["1","2","3","4"]', 'a = <u>1</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbvpufeq0tc9bqbmaogjs7py2', 'General Mathematics', 'JAMB', null, 2020, null, 'cos 36° - cos 72° =', null, '["1/2","1/3","1/4","1/6"]', 0, 'cos 36° - cos 72° = 1/2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'cos 36° - cos 72° =', '["1/2","1/3","1/4","1/6"]', 'Value = <u>1/2</u>.', '{"bold":[],"italic":[],"underline":["1/2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbvvvl4gxjjbemw3qghj8f6h5', 'Biology', 'JAMB', null, 1991, null, 'The construction of dams may lead to an increase in the prevalence of', null, '["typhoid fever, measles and yellow fever","tuberculosis, leprosy and typhanosomiasis","guinea worm, malaria and tuberculosis","malaria, bilharziasis and onchocerciasis"]', 3, 'Dams increase prevalence of malaria, bilharziasis, and onchocerciasis.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The construction of dams may lead to an increase in the prevalence of', '["typhoid fever, measles and yellow fever","tuberculosis, leprosy and typhanosomiasis","guinea worm, malaria and tuberculosis","<u>malaria, bilharziasis and onchocerciasis</u>"]', 'Dams increase prevalence of <u>malaria, bilharziasis, and onchocerciasis</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbw2ite8yqnz4wuzmmc4b64f0', 'Government', 'JAMB', null, 2020, null, 'Power differs from influence in that it is', null, '["persuasive while influence is directive","coercive while influence is harmful","coercive while influence is persuasive","coercive while influence of a legislature."]', 2, 'Power is coercive (can compel obedience), while influence is persuasive (works through attraction and persuasion).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Power differs from influence in that it is', '["persuasive while influence is directive","coercive while influence is harmful","<u>coercive while influence is persuasive</u>","coercive while influence of a legislature."]', 'Power is <u>coercive</u> while influence is <u>persuasive</u>.', '{"bold":[],"italic":[],"underline":["coercive while influence is persuasive"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbw647lp2qqbojwajniv5kthg', 'Biology', 'JAMB', null, 1983, null, 'The dental formula 1/3: c/1: pm/4: m/2 / 3 = 42 represents that of a', null, '["rabbit","full grown man","young child","dog","sheep"]', 3, 'The dental formula i3/3 c1/1 pm4/4 m2/3 = 42 is that of a dog.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The dental formula 1/3: c/1: pm/4: m/2 / 3 = 42 represents that of a', '["rabbit","full grown man","young child","<u>dog</u>","sheep"]', 'The dental formula i3/3 c1/1 pm4/4 m2/3 = 42 is that of a <u>dog</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbw7b5faa3a8fpzrqr2f0ejhr', 'General Mathematics', 'WAEC', null, 2020, null, 'Binomial distribution with n = 5, p = 0.2. Find P(X ≤ 1).', null, '["0.73728","0.4096","0.32768","0.67232"]', 0, 'P(X=0) + P(X=1) = 0.8⁵ + 5(0.2)(0.8)⁴ = 0.32768 + 0.4096 = 0.73728.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Binomial distribution with n = 5, p = 0.2. Find P(X ≤ 1).', '["0.73728","0.4096","0.32768","0.67232"]', 'P = <u>0.73728</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbw9ct508ik4whck9rfrcwbvy', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the quartile deviation of 4, 6, 8, 10, 12, 14, 16.', null, '["4","5","6","7"]', 0, 'Q1 = 6, Q3 = 14; QD = (14-6)/2 = 4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the quartile deviation of 4, 6, 8, 10, 12, 14, 16.', '["4","5","6","7"]', 'QD = <u>4</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbwgbxdhudaz6xw1hesy5rqcl', 'General Mathematics', 'WAEC', null, 2020, null, 'If a*b = ab + a + b, find x such that x*2 = 0.', null, '["-2/3","2/3","-1","1"]', 0, 'x*2 = 2x + x + 2 = 3x + 2 = 0 → x = -2/3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If a*b = ab + a + b, find x such that x*2 = 0.', '["-2/3","2/3","-1","1"]', 'x = <u>-2/3</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbwkkf94ajn5tzvqda7fsf2m9', 'Chemistry', 'JAMB', null, 1991, null, 'The final products of the reaction of methane with excess chlorine in the presence of ultraviolet light are hydrogen chloride and', null, '["chloromethane","tetrachloromethane","trichloromethane","dichloromethane"]', 1, 'Excess Cl2 gives CCl4 (tetrachloromethane).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The final products of the reaction of methane with excess chlorine in the presence of ultraviolet light are hydrogen chloride and', '["chloromethane","tetrachloromethane","trichloromethane","dichloromethane"]', '<u>Tetrachloromethane (CCl4)</u> is the final product.', '{"bold":[],"italic":[],"underline":["tetrachloromethane"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbwqsnbcwfauxbsz0jx2jcjpt', 'Chemistry', 'JAMB', null, 1993, null, '4.0g of sodium hydroxide in 250cm³ of solution contains', null, '["0.40 moles per dm³","0.10 moles per dm³","0.04 moles per dm³","0.02 moles per dm³"]', 1, 'Moles NaOH = 0.1; conc = 0.1/0.25 = 0.4M. Key says 0.10.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '4.0g of sodium hydroxide in 250cm³ of solution contains', '["0.40 moles per dm³","0.10 moles per dm³","0.04 moles per dm³","0.02 moles per dm³"]', 'Conc = 0.1/0.25 = <u>0.4M</u> (key says 0.10).', '{"bold":[],"italic":[],"underline":["0.10 moles per dm³"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbwvty8da2w23scdyzixfp2uf', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the base b given that: 44_b = 61_(b+1).', null, '["5","6","7","8"]', 1, '4b + 4 = 6(b+1) + 1 = 6b + 7 → 2b = -3 → b = -1.5. No valid solution. Key says 6.', false, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Find the base b given that: 44_b = 61_(b+1).', '["5","6","7","8"]', '4b + 4 = 6b + 7 → <u>b = -1.5</u> (invalid, key says 6).', '{"bold":[],"italic":[],"underline":["6"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbxfmkkvzy1afk9vke0gsqjzg', 'General Mathematics', 'JAMB', null, 2020, null, 'Given a*b = 2a - b. Is it commutative?', null, '["Yes","No","Only if a = b","None"]', 1, '2a-b ≠ 2b-a generally.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Given a*b = 2a - b. Is it commutative?', '["Yes","No","Only if a = b","None"]', '<u>No</u>, not commutative.', '{"bold":[],"italic":[],"underline":["No"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbxkxoyb1pamroes9o9rji7nv', 'Chemistry', 'JAMB', null, 1998, null, 'Potassium tetraoxomanganate(VII) is often added to impure water to', null, '["reduce organic impurities","reduce inorganic impurities","destroy bacteria and algae","remove permanent hardness"]', 2, 'KMnO4 destroys bacteria and algae.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Potassium tetraoxomanganate(VII) is often added to impure water to', '["reduce organic impurities","reduce inorganic impurities","destroy bacteria and algae","remove permanent hardness"]', '<u>KMnO4 destroys bacteria and algae</u>.', '{"bold":[],"italic":[],"underline":["destroy bacteria and algae"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbxq8z8nqcy2ago3sopid8oa6', 'Biology', 'JAMB', null, 1987, null, 'If a plant, homozygous for round and yellow (RR;YY), is crossed with a wrinkled green type (rr;yy) all of the resulting seed will be', null, '["blue and wrinkled","round and yellow","wrinkled and yellow","round and greenish-yellow"]', 1, 'The F1 generation will all be round and yellow.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If a plant, homozygous for round and yellow (RR;YY), is crossed with a wrinkled green type (rr;yy) all of the resulting seed will be', '["blue and wrinkled","<u>round and yellow</u>","wrinkled and yellow","round and greenish-yellow"]', 'The F1 generation will all be <u>round and yellow</u>.', null);
