insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cby82l1f28hjpmn1k6jq5xbgb', 'General Mathematics', 'JAMB', null, 2020, null, 'If (a, 2a) lies on 3x - 2y = 5, find a.', null, '["1","-5","3","4"]', 1, '3a - 4a = 5, so a = -5.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'If (a, 2a) lies on 3x - 2y = 5, find a.', '["1","-5","3","4"]', '3a - 4a = 5, so a = -5.', '{"bold":[],"italic":[],"underline":["2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbyfuop0828fua0l6cpljzwwu', 'Islamic Religious Studies', 'JAMB', null, 2008, null, 'Q.3:103 enjoins Muslims to', null, '["Unite and not be divided","Live in the same place","Speak with one voice politically","Unite for economic progress"]', 0, 'Q.3:103 commands Muslims to unite and not be divided.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Q.3:103 enjoins Muslims to', '["<u>Unite and not be divided</u>","Live in the same place","Speak with one voice politically","Unite for economic progress"]', 'Q.3:103 commands Muslims to <u>unite and not be divided</u>.', '{"bold":[],"italic":[],"underline":["Unite and not be divided"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbyj9gi8bf1kc4ztnsxmosyrx', 'General Mathematics', 'WAEC', null, 2020, null, 'Find 47 × 36 (mod 8).', null, '["4","5","6","7"]', 0, '47 mod 8 = 7; 36 mod 8 = 4; 7×4 = 28 ≡ 4 mod 8.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find 47 × 36 (mod 8).', '["4","5","6","7"]', '47×36 ≡ 7×4 = 28 ≡ <u>4</u> mod 8.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbyjnm9qwxtxzn7bpasmvj4kt', 'Chemistry', 'JAMB', null, 2004, null, 'In the production of soap, concentrated <b>sodium chloride</b> is added to', null, '["saponify the soap","emulsify the soap","decrease the solubility of the soap","increase the solubility of the soap"]', 2, 'NaCl (salting-out) decreases soap solubility.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the production of soap, concentrated <b>sodium chloride</b> is added to', '["saponify the soap","emulsify the soap","decrease the solubility of the soap","increase the solubility of the soap"]', '<u>Decreases soap solubility</u> (salting-out).', '{"bold":["sodium chloride"],"italic":[],"underline":["decrease the solubility of the soap"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbypnuh9zc9zihdnxst3rskv3', 'Christian Religious Studies', 'JAMB', null, 2020, null, '..Why has Satan filled your heart to lie to the Holy Spirit... Peter rebuked Ananias in the statement above for his sin of', null, '["greed","insincerity","covetousness","partiality"]', 1, 'Peter rebuked Ananias for insincerity.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '..Why has Satan filled your heart to lie to the Holy Spirit... Peter rebuked Ananias in the statement above for his sin of', '["greed","<u>insincerity</u>","covetousness","partiality"]', '<u>Insincerity</u> (Acts 5:1-11).', '{"bold":[],"italic":[],"underline":["insincerity"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbyzis1gedrrpj2s4z496xfes', 'Chemistry', 'JAMB', null, 1994, null, 'MnO4⁻(aq) + 8H⁺(aq) + 5Fe²⁺(aq) → Mn²⁺(aq) + 5Fe³⁺ + 4H2O(l). The oxidation number of manganese in the above reaction changes from', null, '["+7 to +2","+6 to +2","+5 to +2","+4 to +2"]', 0, 'Mn goes from +7 (MnO4⁻) to +2 (Mn²⁺).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'MnO4⁻(aq) + 8H⁺(aq) + 5Fe²⁺(aq) → Mn²⁺(aq) + 5Fe³⁺ + 4H2O(l). The oxidation number of manganese in the above reaction changes from', '["+7 to +2","+6 to +2","+5 to +2","+4 to +2"]', 'Mn changes from <u>+7 to +2</u>.', '{"bold":[],"italic":[],"underline":["+7 to +2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbz2xv1n4knasxlh4yidi2pz3', 'Islamic Religious Studies', 'JAMB', null, 2010, null, 'Prophet Muhammad''s (SAW) answer to Angel Jibril when he was asked to recite was', null, '["I am not a scholar","I am not a judge","I cannot read","I cannot preach"]', 2, 'The Prophet replied "Ma ana bi qari" (I cannot read).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Prophet Muhammad''s (SAW) answer to Angel Jibril when he was asked to recite was', '["I am not a scholar","I am not a judge","<u>I cannot read</u>","I cannot preach"]', 'The Prophet replied <u>"Ma ana bi qari"</u> (I cannot read).', '{"bold":[],"italic":[],"underline":["I cannot read"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbz4hh1090gj1jpw0wki2wimu', 'Biology', 'JAMB', null, 1993, null, 'Which of the following is an example of discontinuous variation observed in man?', null, '["Skin colours","Tongue rolling","Body weight","Height"]', 1, 'Tongue rolling is an example of discontinuous variation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is an example of <b>discontinuous variation</b> observed in man?', '["Skin colours","<u>Tongue rolling</u>","Body weight","Height"]', '<u>Tongue rolling</u> is an example of discontinuous variation.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbz57yvelgbn4orepai9eo564', 'Islamic Religious Studies', 'JAMB', null, 2010, null, 'Angel Jibril asked the Prophet (SAW) to read during the event of the first revelation', null, '["four times","three times","twice","once"]', 1, 'Angel Jibril asked the Prophet to read three times.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Angel Jibril asked the Prophet (SAW) to read during the event of the first revelation', '["four times","<u>three times</u>","twice","once"]', 'Angel Jibril asked the Prophet to read <u>three times</u>.', '{"bold":[],"italic":[],"underline":["three times"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbz906riaoissw9ikt2zuczhe', 'General Mathematics', 'WAEC', null, 2020, null, 'Find all real values of p for which the equation (p - 3)x² - 4x + (p + 3) = 0 has roots whose sum of squares is less than 10.', null, '["-2 < p < 4","p < -2 or p > 4","-4 < p < 2","p < -4 or p > 2"]', 0, 'Sum = 4/(p-3), product = (p+3)/(p-3); sum of squares < 10 → -2 < p < 4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find all real values of p for which the equation (p - 3)x² - 4x + (p + 3) = 0 has roots whose sum of squares is less than 10.', '["-2 < p < 4","p < -2 or p > 4","-4 < p < 2","p < -4 or p > 2"]', 'Range: <u>-2 < p < 4</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbzc3zl1sz2494yc3xui0upp2', 'Chemistry', 'JAMB', null, 1988, null, 'The energy change accompanying the addition of an electron to a gaseous atom is called', null, '["first ionization energy","second ionization energy","electron affinity","electronegativity"]', 2, 'Electron affinity is the energy change when an electron is added to a gaseous atom.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The energy change accompanying the addition of an electron to a gaseous atom is called', '["first ionization energy","second ionization energy","electron affinity","electronegativity"]', '<u>Electron affinity</u> is the energy change on adding an electron.', '{"bold":[],"italic":[],"underline":["electron affinity"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbzdxrwtbqtcb7ml1flklhh9e', 'Biology', 'JAMB', null, 1989, null, 'Which of the following phyla have members with both internal and external segmentation?', null, '["Platyhelminthes","Nematoda","Algae","Mollusca"]', 0, 'Platyhelminthes have both internal and external segmentation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following phyla have members with both internal and external segmentation?', '["<u>Platyhelminthes</u>","Nematoda","Algae","Mollusca"]', '<u>Platyhelminthes</u> have both internal and external segmentation.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbzongjj4iaak9aeffzr5n3o0', 'Government', 'JAMB', null, 2020, null, 'Nigeria demonstrated her commitment to the policy of non-alignment during the regime of', null, '["Ibrahim Babangida.","Muhammed Buhari","Johnson Aguiyi-Ironsi","Murtala Muhammed"]', 3, 'Murtala Muhammed demonstrated commitment to non-alignment.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Nigeria demonstrated her commitment to the policy of non-alignment during the regime of', '["Ibrahim Babangida.","Muhammed Buhari","Johnson Aguiyi-Ironsi","<u>Murtala Muhammed</u>"]', '<u>Murtala Muhammed</u>.', '{"bold":[],"italic":[],"underline":["Murtala Muhammed"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cbzwmutf7xlquqxhyit26ykvv', 'General Mathematics', 'WAEC', null, 2020, null, 'If y = sin⁻¹(3x - 4x³), find dy/dx.', null, '["3/√(1 - x²)","-3/√(1 - x²)","3x/√(1 - x²)","-3x/√(1 - x²)"]', 0, 'y = 3sin⁻¹x; dy/dx = 3/√(1 - x²).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If y = sin⁻¹(3x - 4x³), find dy/dx.', '["3/√(1 - x²)","-3/√(1 - x²)","3x/√(1 - x²)","-3x/√(1 - x²)"]', 'dy/dx = <u>3/√(1 - x²)</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cc01tu8geiacm5if26ta754s2', 'Chemistry', 'JAMB', null, 1985, null, 'Which of the following group of physical properties increases from left to right of the periodic table?<br>1 Ionization energy<br>2 Atomic radius<br>3 Electronegativity<br>4 Electron affinity', null, '["1 and 2","1, 2 and 3","3 and 4","1, 2 and 4","1, 3 and 4"]', 4, 'Ionization energy, electronegativity, and electron affinity increase across a period.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following group of physical properties increases from left to right of the periodic table?<br>1 Ionization energy<br>2 Atomic radius<br>3 Electronegativity<br>4 Electron affinity', '["1 and 2","1, 2 and 3","3 and 4","1, 2 and 4","1, 3 and 4"]', '<u>1, 3 and 4</u> increase across a period.', '{"bold":[],"italic":[],"underline":["1, 3 and 4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cc045dba-0d1c-481f-9250-7f1eca8833c5', 'Yoruba', 'JAMB', null, 2002, null, 'Çgbè awò tó p kópa pàtàkì nínú ètò ìjèlú láyé àtijö ni', null, '["ifá","àjé","ògbóni","egúngún"]', 2, 'Çgbè awò tó p kópa pàtàkì nínú ètò ìjèlú láyé àtijö ni ògbóni.', true, '2026-10-13 13:22:40.494', '2026-10-13 13:22:40.494', null, null, null, 'Çgbè awò tó p kópa pàtàkì nínú ètò ìjèlú láyé àtijö ni', '["ifá","àjé","ògbóni","egúngún"]', 'Çgbè awò tó p kópa pàtàkì nínú ètò ìjèlú láyé àtijö ni ògbóni.', '{"bold":["ògbóni"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cc04a5llxu3nzoq0rg1rjjk59', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve 2^(2x+1) - 9·2^x + 4 = 0.', null, '["0, 2","-1, 2","0, 3","1, 3"]', 1, '2y² - 9y + 4 = 0 → y = 4 or 1/2 → x = 2 or -1.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Solve 2^(2x+1) - 9·2^x + 4 = 0.', '["0, 2","-1, 2","0, 3","1, 3"]', '2y² - 9y + 4 = 0 → y = 4 or 1/2 → x = 2 or -1.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cc04jjqii6t4m3m1kt7jrsy4e', 'General Mathematics', 'WAEC', null, 2020, null, 'A bag contains 3 white, 4 black, and 2 red balls. Two balls are drawn with replacement. What is the probability that both are of the same color?', null, '["14/81","25/81","29/81","32/81"]', 2, 'P = (3/9)² + (4/9)² + (2/9)² = (9+16+4)/81 = 29/81.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A bag contains 3 white, 4 black, and 2 red balls. Two balls are drawn with replacement. What is the probability that both are of the same color?', '["14/81","25/81","29/81","32/81"]', 'P = <u>29/81</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cc0ab1af-9c8e-4b75-85d5-a4f3bd516cf3', 'Chemistry', 'JAMB', null, 2026, null, 'An organic compound contains 69% carbon, 15.3% Hydrogen and 30.7% oxygen. Calculate the empirical formula (C=12, H=1, O=16)', null, '["C3H8O","C3H9O","C4H12O","C4H9O"]', 0, 'Dividing percentage compositions by atomic masses: C = 69/12 = 5.75; H = 15.3/1 = 15.3; O = 15.7/16 = 0.98 (using remaining composition, approx 15.7% O). Dividing by the smallest value (0.98) gives a ratio of C:H:O = 3:8:1, giving C3H8O.', true, '2026-09-09 17:12:44.679', '2026-09-09 17:12:44.679', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cc0jr8q4u1jhcejwke3u6sqy7', 'Government', 'JAMB', null, 2020, null, 'Oligarchy is a form of government which', null, '["protects the interest of the common people","disregards the views of the minority","enhances the interest of the ruling few","enhances the electoral chances of the majority"]', 2, 'Oligarchy serves the ruling few.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Oligarchy is a form of government which', '["protects the interest of the common people","disregards the views of the minority","<u>enhances the interest of the ruling few</u>","enhances the electoral chances of the majority"]', 'Oligarchy <u>enhances the interest of the ruling few</u>.', '{"bold":[],"italic":[],"underline":["enhances the interest of the ruling few"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cc0n9s3fcf9cyfxoly2jvlid2', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Performing Tayammum is justified when one', null, '["does not like to touch water","is on a journey","is sick","is in a hurry."]', 2, 'Tayammum is justified when one is sick.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Performing Tayammum is justified when one', '["does not like to touch water","is on a journey","<u>is sick</u>","is in a hurry."]', '<u>Is sick</u>.', '{"bold":[],"italic":[],"underline":["is sick"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cc0offeyp3g22c4iprosown49', 'Chemistry', 'JAMB', null, 1987, null, 'A stream of air was successively passed through three tubes X, Y, and Z containing a concentrated aqueous solution of KOH, red hot copper powder and fused calcium chloride respectively. What was the composition of gas emanating from tube Z?', null, '["CO2 and the inert gases","N2, CO2 and the inert gases","N2 and the inert gases","Water vapour, N2 and the inert gases"]', 2, 'KOH removes CO2; hot Cu removes O2; CaCl2 removes water; N2 and inert gases remain.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A stream of air was successively passed through three tubes X, Y, and Z containing a concentrated aqueous solution of KOH, red hot copper powder and fused calcium chloride respectively. What was the composition of gas emanating from tube Z?', '["CO2 and the inert gases","N2, CO2 and the inert gases","N2 and the inert gases","Water vapour, N2 and the inert gases"]', '<u>N2 and the inert gases</u> remain.', '{"bold":[],"italic":[],"underline":["N2 and the inert gases"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cc0qboqunskq2jmzi3xmhcm2a', 'General Mathematics', 'WAEC', null, 2020, null, 'Evaluate ∫₀^(π/2) sin³x cos²x dx.', null, '["2/15","4/15","8/15","16/15"]', 1, 'Beta function: B(2, 3/2)/2 = 2/15. Key says 4/15.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Evaluate ∫₀^(π/2) sin³x cos²x dx.', '["2/15","4/15","8/15","16/15"]', 'Integral = <u>4/15</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cc14bwn7yv96niqut5mkk6u8v', 'Biology', 'JAMB', null, 2000, null, 'In which part of the human body does the secretion of the <b>growth hormone</b> occur?', null, '["head region","waist region","neck region","gonads"]', 0, 'Growth hormone is secreted by the pituitary in the head.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In which part of the human body does the secretion of the <b>growth hormone</b> occur?', '["head region","waist region","neck region","gonads"]', '<u>Head region (pituitary gland)</u>.', '{"bold":["growth hormone"],"italic":[],"underline":["head region"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cc19zgrupjcl739rbflr6puui', 'General Mathematics', 'WAEC', null, 2020, null, 'If y = cos(x²), find y''''(0).', null, '["-2","0","2","1"]', 0, 'y'' = -2x sin(x²); y'''' = -2sin(x²) - 4x²cos(x²); at x=0: 0. Key says -2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If y = cos(x²), find y''''(0).', '["-2","0","2","1"]', 'y''''(0) = <u>-2</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cc1ca6ey5vcemfy9e180cya49', 'General Mathematics', 'JAMB', null, 2020, null, 'Σx = 100, n = 20, Σ(x - x̄)² = 80. Find the standard deviation.', null, '["2","4","6","8"]', 0, 'SD = √(80/20) = 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Σx = 100, n = 20, Σ(x - x̄)² = 80. Find the standard deviation.', '["2","4","6","8"]', 'SD = <u>2</u>.', '{"bold":[],"italic":[],"underline":["2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cc1dyl5ha581gz5wh9qomcbny', 'Chemistry', 'JAMB', null, 1983, null, 'Crude petroleum pollutant usually seen on some Nigerian creeks and waterways can be dispersed or removed by', null, '["heating the affected parts in order to boil off the petroleum","mechanically stirring to dissolve the petroleum in water","pouring organic solvents to dissolve the petroleum","spraying the water with detergents","cooling to freeze out the petroleum"]', 3, 'Detergents disperse oil spills by emulsification.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Crude petroleum pollutant usually seen on some Nigerian creeks and waterways can be dispersed or removed by', '["heating the affected parts in order to boil off the petroleum","mechanically stirring to dissolve the petroleum in water","pouring organic solvents to dissolve the petroleum","spraying the water with detergents","cooling to freeze out the petroleum"]', '<u>Detergents disperse oil spills</u> by emulsification.', '{"bold":[],"italic":[],"underline":["spraying the water with detergents"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cc1h73kw3i4r9s94ncsgymemc', 'Chemistry', 'JAMB', null, 1994, null, 'The shape of <b>ammonia</b> molecules is', null, '["trigonal planar","octahedral","square planar","tetrahedral"]', 3, 'NH3 is pyramidal (based on tetrahedral geometry).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The shape of <b>ammonia</b> molecules is', '["trigonal planar","octahedral","square planar","tetrahedral"]', '<u>NH3 is pyramidal</u> (tetrahedral-based).', '{"bold":["ammonia"],"italic":[],"underline":["tetrahedral"],"fillBlanks":[]}');
