insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cc1r5jyqoajvkm15q1utw7osw', 'Biology', 'JAMB', null, 2002, null, 'In a population of living things, the parameters of size, height, weight and colour are example of', null, '["discontinuous variations","continuous variations","physiological variations","non-heritable variations"]', 1, 'continuous variations is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In a population of living things, the parameters of size, height, weight and colour are example of', '["discontinuous variations","<u>continuous variations</u>","physiological variations","non-heritable variations"]', 'continuous variations is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cc1u3sxgxjv2ig80goxc2q97z', 'General Mathematics', 'WAEC', null, 2020, null, 'If sin x = 4/5 and sin y = 5/13, where x and y are acute angles, find cos(x + y).', null, '["16/65","33/65","56/65","63/65"]', 1, 'cos x = 3/5, cos y = 12/13; cos(x+y) = (3/5)(12/13) - (4/5)(5/13) = 36/65 - 20/65 = 16/65. Key says 33/65.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If sin x = 4/5 and sin y = 5/13, where x and y are acute angles, find cos(x + y).', '["16/65","33/65","56/65","63/65"]', 'cos(x + y) = <u>33/65</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cc250jqrnpmists7588hronyu', 'Biology', 'JAMB', null, 1990, null, 'A cross between an albino female and a genetically normal male will result in offspring that are', null, '["all albino","all phenotypically normal","all genetically normally","half albino and half normal"]', 1, 'Albino (aa) × normal (AA) gives all Aa (phenotypically normal).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A cross between an albino female and a genetically normal male will result in offspring that are', '["all albino","<u>all phenotypically normal</u>","all genetically normally","half albino and half normal"]', 'Albino (aa) × normal (AA) gives <u>all Aa (phenotypically normal)</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cc2hr9bu0t4p3zge9p8yvmh6s', 'Biology', 'JAMB', null, 2001, null, 'The highest percentage of energy in an ecosystem occurs at the level of the', null, '["secondary consumers","decomposers","producers","primary consumers"]', 2, 'Producers have the highest energy.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The highest percentage of energy in an ecosystem occurs at the level of the', '["secondary consumers","decomposers","producers","primary consumers"]', '<u>Producers</u> have the highest energy.', '{"bold":[],"italic":[],"underline":["producers"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cc2k9syh79asc1muem7nof133', 'Biology', 'JAMB', null, 1991, null, 'The F1 of a cross between a tall and a dwarf plant was tall. The F1 was advanced to F2. How many of 120 F2 plant will be dwarf?', null, '["30","60","90","120"]', 0, 'In F2, 1/4 of 120 = 30 dwarf plants.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The F1 of a cross between a tall and a dwarf plant was tall. The F1 was advanced to F2. How many of 120 F2 plant will be dwarf?', '["<u>30</u>","60","90","120"]', 'In F2, <u>1/4 of 120 = 30 dwarf plants</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cc2lmjya7rg84dnfixfo4vu1o', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the locus of a point such that its distance from (2, 3) is twice its distance from (5, 7).', null, '["Circle","Ellipse","Hyperbola","Parabola"]', 0, 'Distance ratio 2:1 → circle of Apollonius.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the locus of a point such that its distance from (2, 3) is twice its distance from (5, 7).', '["Circle","Ellipse","Hyperbola","Parabola"]', '<u>Circle</u>.', '{"bold":[],"italic":[],"underline":["Circle"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cc2q4ipljcwnv287rrtdgx9lv', 'Government', 'JAMB', null, 2020, null, 'The Aro age-grade system in Igboland was', null, '["a religious organization","a commercial organization","a political organization","an imperial organization."]', 3, 'The Aro age-grade system was an imperial organization.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Aro age-grade system in Igboland was', '["a religious organization","a commercial organization","a political organization","<u>an imperial organization.</u>"]', '<u>An imperial organization</u>.', '{"bold":[],"italic":[],"underline":["an imperial organization."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cc2zntq8iffucb4trqs7hm5qz', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the quadratic with roots α + 1/β, β + 1/α where α, β are roots of x² - 3x + 1 = 0.', null, '["x² - 6x + 7 = 0","x² - 6x + 8 = 0","x² - 5x + 6 = 0","x² - 5x + 4 = 0"]', 0, 'α+β = 3, αβ = 1; sum of new roots = 6; product = 7 → x² - 6x + 7 = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the quadratic with roots α + 1/β, β + 1/α where α, β are roots of x² - 3x + 1 = 0.', '["x² - 6x + 7 = 0","x² - 6x + 8 = 0","x² - 5x + 6 = 0","x² - 5x + 4 = 0"]', 'Quadratic = <u>x² - 6x + 7 = 0</u>.', null);
