insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cc36e80rshs6ueucjrkw63vv6', 'General Mathematics', 'WAEC', null, 2020, null, 'A = [[0, 1], [1, 0]], find the eigenvalues.', null, '["1, -1","1, 1","-1, -1","0, 1"]', 0, 'λ² - 1 = 0 → λ = ±1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A = [[0, 1], [1, 0]], find the eigenvalues.', '["1, -1","1, 1","-1, -1","0, 1"]', 'Eigenvalues = <u>1, -1</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cc36i7azsjyddlhpsklirafdn', 'General Mathematics', 'JAMB', null, 2020, null, 'If 70% like music, 50% like sports, 30% like both. What percentage like neither?', null, '["10%","15%","20%","25%"]', 0, 'At least one = 90%; neither = 10%.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If 70% like music, 50% like sports, 30% like both. What percentage like neither?', '["10%","15%","20%","25%"]', 'Neither = <u>10%</u>.', '{"bold":[],"italic":[],"underline":["10%"],"fillBlanks":[]}');
