insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cc3ax45gl9pru9jywqg8xoep6', 'Physics', 'JAMB', null, 1983, null, 'Which of the following arrangements in the sequence shown can be used to obtain a pure spectrum of white light?', null, '["Source, slit, converging lens, prism, converging lens, screen.","Source, slit, diverging lens, screen.","Source, converging lens, prism, diverging lens, screen.","Source, slit, prism, diverging lens, screen"]', 0, 'A pure spectrum needs a slit to define the beam, a collimating lens, a prism to disperse the light, and a converging lens to focus each colour on the screen.', true, '2026-10-11 21:26:45.728', '2026-10-11 21:26:45.728', null, null, null, 'Which of the following arrangements in the sequence shown can be used to obtain a pure spectrum of white light?', '["Source, slit, converging lens, prism, converging lens, screen.","Source, slit, diverging lens, screen.","Source, converging lens, prism, diverging lens, screen.","Source, slit, prism, diverging lens, screen"]', 'A pure spectrum needs a slit to define the beam, a collimating lens, a prism to disperse the light, and a converging lens to focus each colour on the screen.', null);
