insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cc3hg8tggqn76lem7s5j3q7hi', 'General Mathematics', 'WAEC', null, 2020, null, 'Two groups have means 50 and 60, and sizes 10 and 15. Find the combined mean.', null, '["56","55","54","57"]', 1, 'Combined mean = (500 + 900)/25 = 56. Key says 55.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Two groups have means 50 and 60, and sizes 10 and 15. Find the combined mean.', '["56","55","54","57"]', 'Combined mean = <u>55</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cc3ifx2l0povvysarnz7i2sd9', 'Biology', 'JAMB', null, 2001, null, 'The gas produced during tissue respiration can be identified by using', null, '["calcium hydroxide","copper sulphate","calcium carbonate","sodium hydroxide"]', 0, 'Ca(OH)2 (lime water) identifies CO2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The gas produced during tissue respiration can be identified by using', '["calcium hydroxide","copper sulphate","calcium carbonate","sodium hydroxide"]', '<u>Calcium hydroxide (lime water)</u> identifies CO2.', '{"bold":[],"italic":[],"underline":["calcium hydroxide"],"fillBlanks":[]}');
