insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cc3q7tn3smdn5yyzdh2tyi2mn', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'According to Paul, the purpose of the law is', null, '["to bring about justification by faith","the fulfillment of divine promises","to promote faith in the crucified Christ","to increase the knowledge of sin."]', 0, 'The law was our custodian until Christ came, that we might be justified by faith.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to Paul, the purpose of the law is', '["<u>to bring about justification by faith</u>","the fulfillment of divine promises","to promote faith in the crucified Christ","to increase the knowledge of sin."]', '<u>To bring about justification by faith</u> (Galatians 3:24).', '{"bold":[],"italic":[],"underline":["to bring about justification by faith"],"fillBlanks":[]}');
