insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cc46p9ll1yp82zh7rkqe23ex1', 'General Mathematics', 'WAEC', null, 2020, null, 'If the SD of a data set is 5, find the variance.', null, '["25","10","5","2.5"]', 0, 'Variance = SD² = 25.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If the SD of a data set is 5, find the variance.', '["25","10","5","2.5"]', 'Variance = <u>25</u>.', null);
