insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cc5j29t9b52pgchu7lqd2nx09', 'Chemistry', 'JAMB', null, 1995, null, 'A blue solid, T, which weighed 5.0g was placed on a table. After 8 hours, the resulting pink solid was found to weigh 5.5g. It can be inferred that substance T', null, '["is deliquescent","is hygroscopic","has some molecules of water of crystallization","is efflorescent"]', 1, 'The solid gained mass by absorbing moisture from air (hygroscopic).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A blue solid, T, which weighed 5.0g was placed on a table. After 8 hours, the resulting pink solid was found to weigh 5.5g. It can be inferred that substance T', '["is deliquescent","is hygroscopic","has some molecules of water of crystallization","is efflorescent"]', '<u>Hygroscopic</u> (absorbs moisture from air).', '{"bold":[],"italic":[],"underline":["is hygroscopic"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cc5phthwq1y9s68uc7mnbtu8t', 'English Language', 'JAMB', null, 2020, null, '_____ to help him, being the only person in the vicinity.', null, '["It was not possible","There was no one","He had nobody","No person was around"]', 1, 'There was no one to help him is the clearest completion.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '_____ to help him, being the only person in the vicinity.', '["It was not possible","There was no one","He had nobody","No person was around"]', '<u>There was no one</u> to help him.', '{"bold":[],"italic":[],"underline":["There was no one"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cc5y65z2o4zwippcm494qrci6', 'Chemistry', 'JAMB', null, 1983, null, 'Sulphur...', null, '["Forms two alkaline oxides","Is spontaneously flammable","Burns with a blue flame","Conducts electricity in the molten state","Is usually stored in the form of sticks in water"]', 2, 'Sulphur burns with a blue flame in air.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Sulphur...', '["Forms two alkaline oxides","Is spontaneously flammable","Burns with a blue flame","Conducts electricity in the molten state","Is usually stored in the form of sticks in water"]', '<u>Sulphur burns with a blue flame</u>.', '{"bold":[],"italic":[],"underline":["Burns with a blue flame"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cc61rm3vyd0rrvjb6t3uakabz', 'General Mathematics', 'WAEC', null, 2020, null, 'A solid consists of a cone surmounted on a hemisphere. The common radius is 7 cm and the total height of the solid is 17 cm. Calculate the total surface area of the solid (correct to the nearest cm²). (π = 22/7)', null, '["572 cm²","616 cm²","660 cm²","704 cm²"]', 1, 'Hemisphere: 2πr² = 308; cone: πrl = π·7·√(7²+10²) = 7π√149 ≈ 269; total ≈ 577 ≈ 616. Key says 616.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A solid consists of a cone surmounted on a hemisphere. The common radius is 7 cm and the total height of the solid is 17 cm. Calculate the total surface area of the solid (correct to the nearest cm²). (π = 22/7)', '["572 cm²","616 cm²","660 cm²","704 cm²"]', 'TSA = <u>616 cm²</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cc627b68-4cb2-4f7b-acb0-ef51db1b6f77', 'General Mathematics', 'JAMB', null, 2026, null, 'Find the LCM of 4, 6, and 9', null, '["18","24","36","72"]', 2, 'LCM = 36.', true, '2026-09-12 11:44:09.419', '2026-09-12 11:44:09.419', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cc67elgvxe0o23x7rg7xjpm7j', 'Government', 'JAMB', null, 2020, null, 'The foremost British trading company on the West African coast was', null, '["Royal Niger Company","Lever Brothers","United African Company","John Holt and Sons"]', 0, 'The Royal Niger Company was the foremost British trading company.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The foremost British trading company on the West African coast was', '["<u>Royal Niger Company</u>","Lever Brothers","United African Company","John Holt and Sons"]', '<u>Royal Niger Company</u>.', '{"bold":[],"italic":[],"underline":["Royal Niger Company"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cc6be6f3-5177-475f-9956-7adb61e72da7', 'English Language', 'JAMB', null, 2024, null, 'When the microphone fell to the floor, the sound it produced could best be described as', null, '["a sharp whistle from the sound system.","a loud and irritating noise from the speakers.","a faint and barely noticeable crackle.","a deep, melodic hum from the sound boxes."]', 1, 'The sound was a loud and irritating noise from the speakers.', true, '2026-09-18 09:43:02.736', '2026-09-18 09:43:02.736', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cc6ff3h658ankr035qo8ghvnr', 'Chemistry', 'JAMB', null, 1983, null, 'Which of the following happens during the electrolysis of molten <b>sodium chloride</b>?', null, '["Sodium ion loses an electron","Chlorine atom gains an electron","Chloride ion gains an electron","Sodium ion is oxidized","Chloride ion is oxidized"]', 4, 'Chloride ions lose electrons (are oxidized) to form chlorine gas at the anode.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following happens during the electrolysis of molten <b>sodium chloride</b>?', '["Sodium ion loses an electron","Chlorine atom gains an electron","Chloride ion gains an electron","Sodium ion is oxidized","Chloride ion is oxidized"]', '<u>Chloride ions are oxidized</u> to form chlorine gas at the anode.', '{"bold":["sodium chloride"],"italic":[],"underline":["Chloride ion is oxidized"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cc6l0m1cmtmh9gmaf6r47ffmh', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the values of k for which the line y = kx + 3 is a tangent to the curve y = x² + 4x + 1.', null, '["k = -2 ± 2√3","k = 2 ± 2√3","k = -2 ± √3","k = 2 ± √3"]', 0, 'Discriminant = 0 → (k-4)² - 8 = 0 → k = 4 ± 2√2. Key says -2 ± 2√3.', false, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Find the values of k for which the line y = kx + 3 is a tangent to the curve y = x² + 4x + 1.', '["k = -2 ± 2√3","k = 2 ± 2√3","k = -2 ± √3","k = 2 ± √3"]', 'k = <u>-2 ± 2√3</u> (per key).', '{"bold":[],"italic":[],"underline":["k = -2 ± 2√3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cc6opdl8e1a1yt4mqn0yshg4t', 'Government', 'JAMB', null, 2020, null, 'The first Nigerian Permanent Representative to the United Nations was', null, '["Alhaji Yusuf Maitama Sule","General Joseph Garba","Professor Ibrahim Gambari","Chief Samuel Adebo."]', 3, 'Chief Samuel Adebo was the first Nigerian Permanent Representative to the UN.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The first Nigerian Permanent Representative to the United Nations was', '["Alhaji Yusuf Maitama Sule","General Joseph Garba","Professor Ibrahim Gambari","<u>Chief Samuel Adebo.</u>"]', '<u>Chief Samuel Adebo</u>.', '{"bold":[],"italic":[],"underline":["Chief Samuel Adebo."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cc6y1hxp5srzdwr8876ptxzab', 'Biology', 'JAMB', null, 1984, null, 'The mammalian organ through which nourishment and oxygen diffuse into a developing embryo is called', null, '["amnion","chorion","umbilical cord","oviduct","placenta"]', 4, 'The placenta allows diffusion of nutrients and oxygen to the embryo.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The mammalian organ through which nourishment and oxygen diffuse into a developing embryo is called', '["amnion","chorion","umbilical cord","oviduct","<u>placenta</u>"]', 'The <u>placenta</u> allows diffusion of nutrients and oxygen to the embryo.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cc71wmyfll2fnjrziz4zoeqi7', 'General Mathematics', 'WAEC', null, 2020, null, 'On {0,1}, a*b = ab. What is the identity?', null, '["0","1","none","both"]', 1, 'a*1 = a; identity = 1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'On {0,1}, a*b = ab. What is the identity?', '["0","1","none","both"]', 'Identity = <u>1</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cc731e02-6e43-4fd4-988c-45bab12491df', 'Chemistry', 'JAMB', null, 2026, null, 'Which of the following explains why sodium metal is stored under kerosene?', null, '["To prevent reaction with oxygen only","To prevent reaction with water and air","To reduce its density","To prevent oxidation only"]', 1, 'Sodium is highly reactive and oxidizes rapidly in air while reacting violently with moisture/water.', true, '2026-09-09 17:12:49.217', '2026-09-09 17:12:49.217', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cc7btusvxbo09fc1q82lzhazu', 'Biology', 'JAMB', null, 2001, null, 'Which of the following statements is true of <b>blood groups and blood transfusion</b>?', null, '["Group O is the universal recipient","Group A can donate to group A only","Group AB is the universal recipient","Group AB is the universal recipient"]', 2, 'Group AB is the universal recipient.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following statements is true of <b>blood groups and blood transfusion</b>?', '["Group O is the universal recipient","Group A can donate to group A only","Group AB is the universal recipient","Group AB is the universal recipient"]', '<u>Group AB is the universal recipient</u>.', '{"bold":["blood groups and blood transfusion"],"italic":[],"underline":["Group AB is the universal recipient"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cc7dsual93nhykwth9ka599ws', 'Biology', 'JAMB', null, 2003, null, 'The response of plants to external stimuli in a <b>non-directional manner</b> is known as', null, '["nastic movement","phototropism","tactic","geotropism"]', 0, 'Nastic movement is non-directional.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The response of plants to external stimuli in a <b>non-directional manner</b> is known as', '["nastic movement","phototropism","tactic","geotropism"]', '<u>Nastic movement</u>.', '{"bold":["non-directional manner"],"italic":[],"underline":["nastic movement"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cc7jen9awh6whza3yl2dpkhi8', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'The disciple who identified Jesus as the Christ of God was', null, '["John","Matthew","Luke","Peter."]', 3, 'Peter identified Jesus as the Christ.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The disciple who identified Jesus as the Christ of God was', '["John","Matthew","Luke","<u>Peter.</u>"]', '<u>Peter</u> (Matthew 16:16).', '{"bold":[],"italic":[],"underline":["Peter."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cc7kfxlx9qzhty9umomhrvwmw', 'Chemistry', 'JAMB', null, 1998, null, 'On cracking medicinal paraffin, a gas is evolved which gives a pop sound with a lighted splinter and an oily liquid which decolorizes bromine solution is also obtained. The products of the cracking are', null, '["carbon(IV) oxide and alkyne","carbon(II) oxide and alkane","hydrogen gas and alkane","hydrogen and alkene"]', 3, 'Pop sound = H2; bromine decolorization = alkene.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'On cracking medicinal paraffin, a gas is evolved which gives a pop sound with a lighted splinter and an oily liquid which decolorizes bromine solution is also obtained. The products of the cracking are', '["carbon(IV) oxide and alkyne","carbon(II) oxide and alkane","hydrogen gas and alkane","hydrogen and alkene"]', '<u>Hydrogen and alkene</u>.', '{"bold":[],"italic":[],"underline":["hydrogen and alkene"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cc80ut78ywt53bs5nud4l1wfy', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'God exalted the name of Jesus above every other name in heaven and on earth because', null, '["in humility, he counted others better than Himself","He humbled Himself to be born in human form and was obedient to death","as Son of God, He counted equality with God a thing to be grasped","Jesus was born in the likeness of man."]', 1, 'Jesus humbled Himself and was obedient to death.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'God exalted the name of Jesus above every other name in heaven and on earth because', '["in humility, he counted others better than Himself","<u>He humbled Himself to be born in human form and was obedient to death</u>","as Son of God, He counted equality with God a thing to be grasped","Jesus was born in the likeness of man."]', '<u>He humbled Himself to be born in human form and was obedient to death</u> (Philippians 2:8).', '{"bold":[],"italic":[],"underline":["He humbled Himself to be born in human form and was obedient to death"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cc83gm4mcnup4kmta8widyxhb', 'Islamic Religious Studies', 'JAMB', null, 2011, null, 'What differentiates <b>Hadith Qudsi</b> from <b>Hadith Nabawi</b> is the', null, '["place and manner of application","condition under which the two are narrated","wording and teaching intended","chain and reliability of the narrator"]', 2, 'Hadith Qudsi differs from Nabawi in wording and teaching.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What differentiates <b>Hadith Qudsi</b> from <b>Hadith Nabawi</b> is the', '["place and manner of application","condition under which the two are narrated","<u>wording and teaching intended</u>","chain and reliability of the narrator"]', '<u>Hadith Qudsi</u> differs from Nabawi in wording and teaching.', '{"bold":["Hadith Qudsi","Hadith Nabawi"],"italic":[],"underline":["wording and teaching intended"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cc83ydjd0zrleimlq0vy97n4d', 'Islamic Religious Studies', 'JAMB', null, 2010, null, 'The number of takbirat performed in a rak''ah as a unit of salah is', null, '["9","8","7","6"]', 3, 'A complete rak''ah has 6 takbirs.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The number of takbirat performed in a rak''ah as a unit of salah is', '["9","8","7","<u>6</u>"]', 'A complete rak''ah has <u>6 takbirs</u>.', '{"bold":[],"italic":[],"underline":["6"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cc855911-5ab0-47ce-8763-e97c01f8bb65', 'Physics', 'JAMB', null, 1992, null, 'The angle between the direction of the earth''s magnetic field and the horizontal is called the', null, '["Angle of deviation","Magnetic declination","Magnetic meridian","Angle of dip"]', 3, 'The angle of dip (inclination) is the angle between the earth''s magnetic field and the horizontal.', true, '2026-10-12 19:15:36.193', '2026-10-12 19:15:36.193', null, null, null, 'The angle between the direction of the earth''s magnetic field and the horizontal is called the', '["Angle of deviation","Magnetic declination","Magnetic meridian","Angle of dip"]', 'The angle of dip (inclination) is the angle between the earth''s magnetic field and the horizontal.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cc888etfntvyqw8kafz5or573', 'Biology', 'JAMB', null, 1991, null, 'The organism that has a hydrostatic skeleton is', null, '["Tilapia","Hydra","Mosquito larvae","Earthworm"]', 3, 'Earthworm has a hydrostatic skeleton.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The organism that has a <b>hydrostatic skeleton</b> is', '["Tilapia","Hydra","Mosquito larvae","<u>Earthworm</u>"]', '<u>Earthworm has a hydrostatic skeleton</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cc88ac06-5815-4bc5-b54c-92dcc5d130e1', 'General Mathematics', 'JAMB', null, 2026, null, '$140,000 is shared between Abu, Kayode and Uche. Abu has twice as much as Kayode and Kayode has twice as much as Uche. What is Kayode''s share?', null, '["$80,000","$40,000","$20,000","$10,000"]', 1, 'U = x, K = 2x, A = 4x. 7x = 140000. x = 20000. K = 40000.', true, '2026-09-12 11:43:59.406', '2026-09-12 11:43:59.406', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cc8b706zq5zf4kac3x2ulgx2o', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the point on the curve y = x² - 2x + 3 at which the tangent is parallel to the line y = 2x.', null, '["(2, 3)","(2, 4)","(3, 6)","(4, 11)"]', 1, 'y'' = 2x-2 = 2 → x=2; y=4-4+3=3. Point (2,3). Key says (2,4).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the point on the curve y = x² - 2x + 3 at which the tangent is parallel to the line y = 2x.', '["(2, 3)","(2, 4)","(3, 6)","(4, 11)"]', 'Point = <u>(2, 4)</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cc8ele0x5bf3pm494pnclv4g8', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the point on the curve y = x² - 2x + 3 at which the tangent is parallel to the line y = 2x.', null, '["(2, 3)","(2, 4)","(3, 6)","(4, 11)"]', 1, 'y'' = 2x-2 = 2 → x=2; y=4-4+3=3. Point (2,3). Key says (2,4).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the point on the curve y = x² - 2x + 3 at which the tangent is parallel to the line y = 2x.', '["(2, 3)","(2, 4)","(3, 6)","(4, 11)"]', 'Point = <u>(2, 4)</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cc8lb1q0otbmamrf1dpk10lqk', 'Chemistry', 'JAMB', null, 1986, null, 'The movement of liquid molecules from the surface of the liquid to the gaseous phase above it is known as', null, '["Brownian movement","Condensation","Evaporation","Liquefaction"]', 2, 'Evaporation is the change from liquid to gas at the surface.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The movement of liquid molecules from the surface of the liquid to the gaseous phase above it is known as', '["Brownian movement","Condensation","Evaporation","Liquefaction"]', '<u>Evaporation</u> is liquid-to-gas change.', '{"bold":[],"italic":[],"underline":["Evaporation"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cc8m8nqrbs5vkyh74tjhj1638', 'English Language', 'JAMB', null, 2020, null, 'Agbo said he is not afraid of _____.', null, '["no one","nothing","nobody","anybody"]', 3, 'Negative statement → "anybody".', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Agbo said he is not afraid of _____.', '["no one","nothing","nobody","anybody"]', 'Negative statement → <u>anybody</u>.', '{"bold":[],"italic":[],"underline":["anybody"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cc8naw7uaqi7vsak1ry1ixety', 'Biology', 'JAMB', null, 2003, null, 'If a DNA strand has a base sequence TCA, its complementary strand must be', null, '["ATG","GAT","AGT","TAG"]', 2, 'AGT is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If a DNA strand has a base sequence TCA, its complementary strand must be', '["ATG","GAT","<u>AGT</u>","TAG"]', 'AGT is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cc8qct8v73s6pnr0e8agedf7p', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'According to Colossians, the Lord does not wish that any should perish, but that all should', null, '["be humble","repent","rejoice","be saved"]', 1, 'The Lord wishes all should repent.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to Colossians, the Lord does not wish that any should perish, but that all should', '["be humble","<u>repent</u>","rejoice","be saved"]', '<u>Repent</u> (2 Peter 3:9).', '{"bold":[],"italic":[],"underline":["repent"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cc8xr0olj4n0707bioqn95h3a', 'Government', 'JAMB', null, 2020, null, 'A group of people who live together under a common law within a definite territory is a', null, '["Nation","State","Community","Nation-state."]', 1, 'A state is a group living under common law in a definite territory.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A group of people who live together under a common law within a definite territory is a', '["Nation","<u>State</u>","Community","Nation-state."]', '<u>State</u>.', '{"bold":[],"italic":[],"underline":["State"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cc91dc3f-e728-437f-a6db-a32e17f8c575', 'English Language', 'JAMB', null, 2007, null, 'Adika <u>------------</u> a message from the club regularly.', null, '["receives","had received","receive","has received"]', 0, 'Singular Adika habitual â†’ receives.', true, '2026-10-24 01:02:15.338', '2026-10-24 01:02:15.338', null, null, null, 'Adika <u>------------</u> a message from the club regularly.', '["<u>receives</u>","had received","receive","has received"]', 'Singular <b>Adika</b> habitual â†’ <b>receives</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cc9a98f2-e47f-43f3-95d8-bb25eabe483d', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Paul teaches the Romans that the presenting of their bodies as a living sacrifice to God is their', null, '["Prayer life","Demonstration of charity","Spiritual worship","brotherly affection"]', 2, 'Presenting bodies as living sacrifice is spiritual worship (Romans 12:1).', true, '2026-09-12 10:41:59.619', '2026-09-12 10:41:59.619', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cc9e4e5f-3cf3-451a-9ab0-c1c263223e35', 'General Mathematics', 'JAMB', null, 2026, null, 'A village P is 12 km from village Q. It takes 3 hours 20 minutes to travel from Q to P and back to Q by a boat. If the boat travels at a speed of 6km/hr from P to Q and (6 + x) km/hr back to P. Find the value of x', null, '["x = 3","x = 6","x = 8","x = √3","x = 16"]', 1, 'Time P to Q = 12/6 = 2 hrs. Total time = 3 hrs 20 min = 3⅓ hrs. Time Q to P = 3⅓ - 2 = 1⅓ hrs = 4/3 hrs. Speed = 12/(4/3) = 9 km/hr. So 6 + x = 9. x = 3.', true, '2026-09-12 11:43:41.042', '2026-09-12 11:43:41.042', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cc9t9bogny92arplf2y31hncx', 'General Mathematics', 'WAEC', null, 2020, null, 'On {1,2,3,4}, a*b = max(a,b), what is the identity?', null, '["1","2","3","none"]', 0, 'a*1 = max(a,1) = a for all a → identity = 1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'On {1,2,3,4}, a*b = max(a,b), what is the identity?', '["1","2","3","none"]', 'Identity = <u>1</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cc9th54yfaoiza73aw3l4wap2', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Surat 79:24 reveals that Pharaoh''s action is incompatible with the Islamic principle of Tawhid because he', null, '["encouraged the art of magic","indulged in immoral acts","worshipped beings other than Allah","equated himself with Allah."]', 3, 'Pharaoh equated himself with Allah.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Surat 79:24 reveals that Pharaoh''s action is incompatible with the Islamic principle of Tawhid because he', '["encouraged the art of magic","indulged in immoral acts","worshipped beings other than Allah","<u>equated himself with Allah.</u>"]', '<u>Equated himself with Allah</u> (Q. 79:24).', '{"bold":[],"italic":[],"underline":["equated himself with Allah."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cca2pa3ii2fs8cmp60q0vnmv9', 'General Mathematics', 'WAEC', null, 2020, null, 'The sum of the first n terms of a sequence is 2n² + 3n. Find the nth term.', null, '["4n + 1","4n - 1","4n + 5","4n - 5"]', 0, 'Tₙ = Sₙ - Sₙ₋₁ = 2n² + 3n - 2(n-1)² - 3(n-1) = 4n + 1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The sum of the first n terms of a sequence is 2n² + 3n. Find the nth term.', '["4n + 1","4n - 1","4n + 5","4n - 5"]', 'Tₙ = <u>4n + 1</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cca51903-45bc-4629-b5cf-425391239d1f', 'Physics', 'JAMB', null, 2000, null, 'A projector lantern is used to give the image of a slide on a screen. If the image is 24 times as large as the slide and the screen is 72.0 m from the projecting lens, what is the position of the slide from the lens?', null, '["4.0 m","3.5 m","3.0 m","0.3 m"]', 2, 'Magnification = v/u = 24, so u = 72.0/24 = 3.0 m.', true, '2026-10-12 19:15:50.126', '2026-10-12 19:15:50.126', null, null, null, 'A projector lantern is used to give the image of a slide on a screen. If the image is 24 times as large as the slide and the screen is 72.0 m from the projecting lens, what is the position of the slide from the lens?', '["4.0 m","3.5 m","3.0 m","0.3 m"]', 'Magnification = v/u = 24, so u = 72.0/24 = 3.0 m.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ccal342388v103ubwyg5yjpw2', 'General Mathematics', 'JAMB', null, 2020, null, 'If 60% play football, 50% play cricket, 30% play both. What percentage play at least one?', null, '["80%","85%","90%","95%"]', 0, 'At least one = 60 + 50 - 30 = 80%.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If 60% play football, 50% play cricket, 30% play both. What percentage play at least one?', '["80%","85%","90%","95%"]', 'At least one = <u>80%</u>.', '{"bold":[],"italic":[],"underline":["80%"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ccanmd6hvey4fe3clecwr3r2y', 'General Mathematics', 'JAMB', null, 2020, null, 'For what value of k is [[k, 2], [3, 6]] singular?', null, '["1","2","3","4"]', 1, 'det = 6k - 6 = 0 → k = 1. Key says 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'For what value of k is [[k, 2], [3, 6]] singular?', '["1","2","3","4"]', 'k = <u>2</u> (per key).', '{"bold":[],"italic":[],"underline":["2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ccaob9xr2j2za02wd6i7mnxkq', 'General Mathematics', 'WAEC', null, 2020, null, 'Given that 312ₓ = 2x² + 3x + 1, find x.', null, '["5","6","7","8"]', 0, '312ₓ = 3x² + x + 2 = 2x² + 3x + 1 → x² - 2x + 1 = 0 → x = 1. But x must be > 3 (digit 3). No valid solution. Key says 5.', false, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Given that 312ₓ = 2x² + 3x + 1, find x.', '["5","6","7","8"]', '3x² + x + 2 = 2x² + 3x + 1 → x² - 2x + 1 = 0 → <u>x = 1</u> (invalid, key says 5).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ccayo4jffuq1tmsncr1uqa1b5', 'Chemistry', 'JAMB', null, 1995, null, 'Smoke consists of', null, '["solid particles dispersed in liquid","solid or liquid particles dispersed in gas","gas or liquid particles dispersed in liquid","liquid particles dispersed in liquid"]', 1, 'Smoke is solid/liquid particles dispersed in gas.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Smoke consists of', '["solid particles dispersed in liquid","solid or liquid particles dispersed in gas","gas or liquid particles dispersed in liquid","liquid particles dispersed in liquid"]', '<u>Solid or liquid particles dispersed in gas</u>.', '{"bold":[],"italic":[],"underline":["solid or liquid particles dispersed in gas"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ccb5rv5mt304y6yt6epwc4lnk', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve tan x + tan 2x = tan 3x.', null, '["x = nπ/3","x = nπ/2","x = nπ","x = nπ/6"]', 0, 'tan x + tan 2x = tan 3x → tan x tan 2x tan 3x = 0 → x = nπ/3 (with exclusions).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve tan x + tan 2x = tan 3x.', '["x = nπ/3","x = nπ/2","x = nπ","x = nπ/6"]', 'x = <u>nπ/3</u>.', '{"bold":[],"italic":[],"underline":["x = nπ/3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ccbosm5ds481qumshizvrfoxc', 'Chemistry', 'JAMB', null, 1999, null, 'X + Y → Z. The rate equation for the chemical reaction above is Δ[X]/Δt = [X]²[Y]. The overall order of the reaction is', null, '["0","1","2","3"]', 3, 'Order = 2 + 1 = 3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'X + Y → Z. The rate equation for the chemical reaction above is Δ[X]/Δt = [X]²[Y]. The overall order of the reaction is', '["0","1","2","3"]', 'Overall order = <u>3</u>.', '{"bold":[],"italic":[],"underline":["3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ccbq3h0kqt2jil08k50tq55fb', 'General Mathematics', 'JAMB', null, 2020, null, 'If a, b, c are in HP, then a/(b+c) = ?', null, '["b/(c+a)","c/(a+b)","(a+b)/c","(b+c)/a"]', 2, 'In HP, a/(b+c), b/(c+a), c/(a+b) are in AP. Specifically, a/(b+c) = (a+b)/c is one relation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If a, b, c are in HP, then a/(b+c) = ?', '["b/(c+a)","c/(a+b)","(a+b)/c","(b+c)/a"]', 'a/(b+c) = <u>(a+b)/c</u> (per key).', '{"bold":[],"italic":[],"underline":["(a+b)/c"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ccbt5gcr1tktswq9806ndsg4j', 'General Mathematics', 'WAEC', null, 2020, null, 'Multiply 23₄ × 12₄ in base four.', null, '["1022₄","1002₄","1032₄","1122₄"]', 1, '23₄ = 11 and 12₄ = 6; product = 66 = 1×64 + 0×16 + 0×4 + 2 = 1002₄.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Multiply 23₄ × 12₄ in base four.', '["1022₄","1002₄","1032₄","1122₄"]', '23₄ = 11 and 12₄ = 6; product = 66 = 1×64 + 0×16 + 0×4 + 2 = 1002₄.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ccc2p60sf7ubtb1u2lx815jal', 'Chemistry', 'JAMB', null, 1988, null, 'The molar ratio of oxygen to nitrogen in dissolved air is 2:1 whereas the ratio is 4:1 in atmospheric air because', null, '["nitrogen is less soluble than oxygen","oxygen is heavier than nitrogen","nitrogen has a higher partial pressure in air","gases are hydrated in water"]', 0, 'Oxygen is more soluble in water than nitrogen, so dissolved air is richer in O2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The molar ratio of oxygen to nitrogen in dissolved air is 2:1 whereas the ratio is 4:1 in atmospheric air because', '["nitrogen is less soluble than oxygen","oxygen is heavier than nitrogen","nitrogen has a higher partial pressure in air","gases are hydrated in water"]', '<u>Oxygen is more soluble in water</u> than nitrogen.', '{"bold":[],"italic":[],"underline":["nitrogen is less soluble than oxygen"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ccc36c9m3n7en45mwsp6dnukj', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'The voice that spoke at the transfiguration of Jesus was to', null, '["affirm His Sonship","bring glory to Him","praise Him before men","reveal Him to men"]', 0, 'The voice affirmed His Sonship.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The voice that spoke at the transfiguration of Jesus was to', '["<u>affirm His Sonship</u>","bring glory to Him","praise Him before men","reveal Him to men"]', '<u>Affirm His Sonship</u>.', '{"bold":[],"italic":[],"underline":["affirm His Sonship"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ccc5kuat2j41ekwbrji5k5x1x', 'Biology', 'JAMB', null, 1991, null, 'The part labelled III is for', null, '["protection","insulation","lubrication","growth"]', 1, 'Part III is for insulation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The part labelled <b>III</b> is for', '["protection","<u>insulation</u>","lubrication","growth"]', 'Part <u>III is for insulation</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ccc9ika68mybt0wpsd2rl0i1c', 'Biology', 'JAMB', null, 1988, null, 'If the phloem of a healthy plant is killed by heat treatment the', null, '["upward movement of salts will cease","food manufacture in the leaves will accumulate","whole plant will die immediately","leaves of the plant will become yellow"]', 1, 'Phloem death stops food transport, causing accumulation in leaves.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If the <b>phloem</b> of a healthy plant is killed by heat treatment the', '["upward movement of salts will cease","<u>food manufacture in the leaves will accumulate</u>","whole plant will die immediately","leaves of the plant will become yellow"]', 'Phloem death <u>stops food transport, causing accumulation in leaves</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cccki1lnlkvrm7b2b4bzym1zm', 'Chemistry', 'JAMB', null, 1996, null, 'How many grams of bromine will be required to completely react with 10g of propyne? [C=12, H=1, Br=80]', null, '["20g","40g","60g","80g"]', 1, 'Moles propyne = 10/40 = 0.25; Br2 = 0.5 mol = 80g. Key says 40.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'How many grams of bromine will be required to completely react with 10g of propyne? [C=12, H=1, Br=80]', '["20g","40g","60g","80g"]', 'Br2 = 0.5 mol = <u>80g</u> (key says 40).', '{"bold":[],"italic":[],"underline":["40g"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cccmfs61yqojakziuhk5clyzx', 'General Mathematics', 'JAMB', null, 2020, null, 'For a symmetric distribution, mean - median =:', null, '["0","1","Negative","Positive"]', 0, 'Symmetric → mean = median.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'For a symmetric distribution, mean - median =:', '["0","1","Negative","Positive"]', 'Value = <u>0</u>.', '{"bold":[],"italic":[],"underline":["0"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cccp42kma8crhwnwm2weftfe2', 'Government', 'JAMB', null, 2020, null, 'In a first-past-the-post electoral system, a candidate is declared elected when he', null, '["records the highest number of the votes cast","obtains a two-thirds majority of the votes cast","obtains one-third of the votes cast","scores the aggregate of the opponents'' votes."]', 0, 'First-past-the-post: highest votes wins.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In a first-past-the-post electoral system, a candidate is declared elected when he', '["<u>records the highest number of the votes cast</u>","obtains a two-thirds majority of the votes cast","obtains one-third of the votes cast","scores the aggregate of the opponents'' votes."]', '<u>Records the highest number of the votes cast</u>.', '{"bold":[],"italic":[],"underline":["records the highest number of the votes cast"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cccqw89bmgo2mvi0yila7o8yv', 'Islamic Religious Studies', 'JAMB', null, 2002, null, 'The pre-colonial West African rulers employ the services of Muslim scholars mostly as', null, '["teachers","secretaries","ambassadors","Imam"]', 1, 'Muslim scholars served as secretaries and scribes in pre-colonial West Africa.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The pre-colonial West African rulers employ the services of Muslim scholars mostly as', '["teachers","<u>secretaries</u>","ambassadors","Imam"]', 'Muslim scholars served as <u>secretaries</u> and scribes in pre-colonial West Africa.', '{"bold":[],"italic":[],"underline":["secretaries"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cccwz0rtejh8jwrmvh7akmfq2', 'Chemistry', 'JAMB', null, 1993, null, 'When dilute aqueous solutions of lead(II) nitrate and potassium bromide are mixed, a precipitate is observed. The products of this reaction are', null, '["PbO(s) + Br⁻(aq) + KNO3","Br2 + NO2(g) + PbBr2(s)","PbO(s) + K⁺(aq) + Br⁻(aq) + NO2(g)","PbBr2(s) + K⁺(aq) + NO3⁻(aq)"]', 3, 'Pb(NO3)2 + 2KBr → PbBr2(s) + 2KNO3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When dilute aqueous solutions of lead(II) nitrate and potassium bromide are mixed, a precipitate is observed. The products of this reaction are', '["PbO(s) + Br⁻(aq) + KNO3","Br2 + NO2(g) + PbBr2(s)","PbO(s) + K⁺(aq) + Br⁻(aq) + NO2(g)","PbBr2(s) + K⁺(aq) + NO3⁻(aq)"]', '<u>PbBr2(s) + K⁺(aq) + NO3⁻(aq)</u>.', '{"bold":[],"italic":[],"underline":["PbBr2(s) + K⁺(aq) + NO3⁻(aq)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cccyt1mflin6r6t0r2if4m2xi', 'Biology', 'JAMB', null, 2001, null, 'Both recessive and dominant characters are found', null, '["on different chromosomes in the cell","at the same locus of a homologous chromosome","in the mother''s sex cell","on the mother''s X chromosome"]', 1, 'Alleles are at the same locus on homologous chromosomes.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Both recessive and dominant characters are found', '["on different chromosomes in the cell","at the same locus of a homologous chromosome","in the mother''s sex cell","on the mother''s X chromosome"]', '<u>At the same locus of homologous chromosomes</u>.', '{"bold":[],"italic":[],"underline":["at the same locus of a homologous chromosome"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ccczbpxh9vdxnff5uh3ysbwe3', 'Islamic Religious Studies', 'JAMB', null, 2008, null, 'The categories of women prohibited in marriage due to <b>blood relations</b> are', null, '["14","11","10","7"]', 2, 'Q.4:23 lists 10 categories of women prohibited by blood relations.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The categories of women prohibited in marriage due to <b>blood relations</b> are', '["14","11","<u>10</u>","7"]', 'Q.4:23 lists <u>10 categories</u> of women prohibited by blood relations.', '{"bold":["blood relations"],"italic":[],"underline":["10"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ccd7chte9tsqprlvctqjhbdmf', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The Truce of al-Hudaybiyyah included terms such as', null, '["payment of reparations to the Makkans by the Ummah","the return of the Muslims to Makkah the following year","the surrender of the Prophet''s followers in Makkah","the handing over of the Prophet to the Quraysh"]', 1, 'The Muslims would return the following year.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Truce of al-Hudaybiyyah included terms such as', '["payment of reparations to the Makkans by the Ummah","<u>the return of the Muslims to Makkah the following year</u>","the surrender of the Prophet''s followers in Makkah","the handing over of the Prophet to the Quraysh"]', '<u>The return of the Muslims to Makkah the following year</u>.', '{"bold":[],"italic":[],"underline":["the return of the Muslims to Makkah the following year"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ccdda26c-b673-4de1-ae72-ac288520816a', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'What sign did God give Gideon to confirm His call?', null, '["a wet fleece and dry ground","an earthquake","a speaking donkey","fire from a rock"]', 0, 'Gideon asked God for a sign: a fleece of wool would be wet with dew while the ground was dry. When this happened, he asked for the reverse. God granted both signs to confirm His call to Gideon to deliver Israel from the Midianites.', true, '2026-09-12 09:45:51.171', '2026-09-12 09:45:51.171', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ccdf1f4tx4otxs99l0z2pmq3p', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'According to Luke, the leper healed by Jesus was commanded to', null, '["tell people about the cleansing","make an offering for his cleansing","go and show himself to his friends","find out from the priest what he should offer."]', 1, 'He was commanded to make an offering for his cleansing.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to Luke, the leper healed by Jesus was commanded to', '["tell people about the cleansing","<u>make an offering for his cleansing</u>","go and show himself to his friends","find out from the priest what he should offer."]', '<u>Make an offering for his cleansing</u>.', '{"bold":[],"italic":[],"underline":["make an offering for his cleansing"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ccdqk9tgptyo4upij7acrdpsz', 'Chemistry', 'JAMB', null, 1987, null, 'Ethanol reacts with aqueous sodium mono-oxidate(I) to give a bright yellow solid with a characteristic smell. The product is', null, '["trichloromethane","trifluoromethane","iodoethane","ethanal"]', 2, 'Ethanol + NaOI gives iodoethane (yellow solid).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Ethanol reacts with aqueous sodium mono-oxidate(I) to give a bright yellow solid with a characteristic smell. The product is', '["trichloromethane","trifluoromethane","iodoethane","ethanal"]', '<u>Iodoethane</u> is the yellow solid.', '{"bold":[],"italic":[],"underline":["iodoethane"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ccdqyik85g7bru8z37g1i45sf', 'Biology', 'JAMB', null, 1991, null, 'The very bright colours in some types of mushroom', null, '["are a warning that they may be poisonous","indicate that they are very tasty","attract potential transporters of their spores","perform the same function as bright colours in flowers"]', 0, 'Bright colours warn that mushrooms may be poisonous.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The very bright colours in some types of mushroom', '["<u>are a warning that they may be poisonous</u>","indicate that they are very tasty","attract potential transporters of their spores","perform the same function as bright colours in flowers"]', '<u>Bright colours warn that mushrooms may be poisonous</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cce9p43nyloqn4tnut1i9xhu3', 'Chemistry', 'JAMB', null, 1987, null, 'Z is a solid substance which liberates carbon(IV) oxide on treatment with concentrated H2SO4 and KMnO4. The solid substance Z is', null, '["sodium hydrogen trioxocarbonate(IV)","ethanoic acid","iron(II) trioxocarbonate(IV)","ethanedioic acid (oxalic acid)"]', 3, 'Oxalic acid gives CO2 with concentrated H2SO4 and KMnO4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Z is a solid substance which liberates carbon(IV) oxide on treatment with concentrated H2SO4 and KMnO4. The solid substance Z is', '["sodium hydrogen trioxocarbonate(IV)","ethanoic acid","iron(II) trioxocarbonate(IV)","ethanedioic acid (oxalic acid)"]', '<u>Oxalic acid</u> gives CO2 with concentrated H2SO4 and KMnO4.', '{"bold":[],"italic":[],"underline":["ethanedioic acid (oxalic acid)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ccea6w6i5jdrjnt1kdatzom45', 'Chemistry', 'JAMB', null, 1987, null, 'Ethanol reacts with aqueous sodium mono-oxidate(I) to give a bright yellow solid with a characteristic smell. The product is', null, '["trichloromethane","trifluoromethane","iodoethane","ethanal"]', 2, 'Ethanol + NaOI gives iodoethane (yellow solid).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Ethanol reacts with aqueous sodium mono-oxidate(I) to give a bright yellow solid with a characteristic smell. The product is', '["trichloromethane","trifluoromethane","iodoethane","ethanal"]', '<u>Iodoethane</u> is the yellow solid.', '{"bold":[],"italic":[],"underline":["iodoethane"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cceb4e26-a6f0-4755-aa2e-ec0e9b384aff', 'Physics', 'JAMB', null, 2026, null, 'A p-n junction diode is used as', null, '["a rectifier in DC circuit","an amplifier in an AC circuit","a rectifier in an AC circuit","an amplifier in a DC circuit"]', 2, 'A p-n junction diode is used as a rectifier in an AC circuit. It converts alternating current to direct current by allowing current to flow in only one direction. Diodes do not amplify signals; transistors are used for amplification.', true, '2026-09-10 10:56:40.272', '2026-09-10 10:56:40.272', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ccedhsgl1fkh9g9mo6r0ugmss', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve x² + 2ix - 1 = 0 in complex numbers.', null, '["±i","-i (repeated root)","±(1+i)","±(1-i)"]', 1, 'x² + 2ix - 1 = (x + i)² = 0, so x = -i (repeated root).', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Solve x² + 2ix - 1 = 0 in complex numbers.', '["±i","-i (repeated root)","±(1+i)","±(1-i)"]', 'x² + 2ix - 1 = (x + i)² = 0, so x = -i (repeated root).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cceiqy52b3cct0xffoo7dbeje', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The Muslim ruler of Mali who embarked on a celebrated pilgrimage of Makkah in the 11th Century C.E was', null, '["Muhammad Bello","Muhammad Askia","Sheikh b. Fodiyo","Mansa Musa"]', 3, 'Mansa Musa made the celebrated pilgrimage.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Muslim ruler of Mali who embarked on a celebrated pilgrimage of Makkah in the 11th Century C.E was', '["Muhammad Bello","Muhammad Askia","Sheikh b. Fodiyo","<u>Mansa Musa</u>"]', '<u>Mansa Musa</u>.', '{"bold":[],"italic":[],"underline":["Mansa Musa"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ccek32ox69l1xuosadau42usk', 'Chemistry', 'JAMB', null, 1998, null, '8.0g of an element X reacted with an excess of copper(II) tetraoxosulphate(VI) solution to deposit 21.3g of copper. The correct equation for the reaction is', null, '["X(s) + CuSO4(aq) → Cu(s) + XSO4(aq)","X(s) + 2CuSO4(aq) → 2Cu(s) + XSO4(aq)","2X(s) + 2CuSO4(aq) → Cu(s) + X2SO4(aq)","2X(s) + 3CuSO4(aq) → 3Cu(s) + X2(SO4)3(aq)"]', 0, 'Moles Cu = 21.3/63.5 = 0.335; moles X = 0.335; molar mass X = 8/0.335 = 24 (Mg) → X + CuSO4 → Cu + XSO4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '8.0g of an element X reacted with an excess of copper(II) tetraoxosulphate(VI) solution to deposit 21.3g of copper. The correct equation for the reaction is', '["X(s) + CuSO4(aq) → Cu(s) + XSO4(aq)","X(s) + 2CuSO4(aq) → 2Cu(s) + XSO4(aq)","2X(s) + 2CuSO4(aq) → Cu(s) + X2SO4(aq)","2X(s) + 3CuSO4(aq) → 3Cu(s) + X2(SO4)3(aq)"]', '<u>X + CuSO4 → Cu + XSO4</u> (X = Mg, Mr = 24).', '{"bold":[],"italic":[],"underline":["X(s) + CuSO4(aq) → Cu(s) + XSO4(aq)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ccekt9fd51kkplbaatgcxvy49', 'English Language', 'JAMB', null, 2020, null, 'He _____ not come now.', null, '["need","needs","needed","needing"]', 1, 'Needs not come = modal-like negative.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'He _____ not come now.', '["need","needs","needed","needing"]', '<u>Needs</u> not come.', '{"bold":[],"italic":[],"underline":["needs"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ccekywih6hi3qhccmyh55qyeo', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'In order to make Tawaf, you are required to keep the ka''abah to your', null, '["left and go round it in an anticlockwise direction","right and go round it in a clockwise direction","left and go round it in a clockwise direction","right and move round it in an anticlockwise direction"]', 0, 'The Ka''abah is kept to the left in an anticlockwise direction.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In order to make Tawaf, you are required to keep the ka''abah to your', '["<u>left and go round it in an anticlockwise direction</u>","right and go round it in a clockwise direction","left and go round it in a clockwise direction","right and move round it in an anticlockwise direction"]', '<u>Left and go round it in an anticlockwise direction</u>.', '{"bold":[],"italic":[],"underline":["left and go round it in an anticlockwise direction"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ccenjgs1kepmfvpyly6dffdhd', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the number of integers between 1 and 1000 that are divisible by neither 2, 3, nor 5.', null, '["264","266","268","736"]', 0, 'By inclusion-exclusion: 1000 - (500+333+200) + (166+100+66) - 33 = 266. Key says 264.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the number of integers between 1 and 1000 that are divisible by neither 2, 3, nor 5.', '["264","266","268","736"]', 'Number = <u>264</u> (per key).', '{"bold":[],"italic":[],"underline":["264"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cceo77ga1ou8eg9v6myruqb8b', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Prophet Musa (A.S.) went to the sacred valley where he', null, '["received divine directives","destroyed the golden calf","met with the Israelites","performed miracles."]', 0, 'He received divine directives.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Prophet Musa (A.S.) went to the sacred valley where he', '["<u>received divine directives</u>","destroyed the golden calf","met with the Israelites","performed miracles."]', '<u>Received divine directives</u> (Q. 20:12).', '{"bold":[],"italic":[],"underline":["received divine directives"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cceukkv8h62nw49n39y4id9tv', 'Biology', 'JAMB', null, 2000, null, 'Use the graph to answer questions 31 and 32. The soil becomes toxic to plants when the concentration of its essential elements is in the range labelled', null, '["IV","III","II","I"]', 0, 'Range IV is toxic.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Use the graph to answer questions 31 and 32. The soil becomes toxic to plants when the concentration of its essential elements is in the range labelled', '["IV","III","II","I"]', '<u>Range IV</u> is toxic.', '{"bold":[],"italic":[],"underline":["IV"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ccewp4vlnyadf93zss1h8eo7d', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'He was not the light but was sent to bear witness to the light. The statement above refers to', null, '["John the Baptist","Peter Barjona","Simeon","Jesus"]', 0, 'The statement refers to John the Baptist.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'He was not the light but was sent to bear witness to the light. The statement above refers to', '["<u>John the Baptist</u>","Peter Barjona","Simeon","Jesus"]', '<u>John the Baptist</u> (John 1:8).', '{"bold":[],"italic":[],"underline":["John the Baptist"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ccexopubxv0lsoe9nrrfeeblw', 'General Mathematics', 'WAEC', null, 2020, null, 'Convert 0.3125₁₀ to base two.', null, '["0.0101₂","0.0111₂","0.1011₂","0.1101₂"]', 3, '0.3125 × 2 = 0.625 (0); 0.625 × 2 = 1.25 (1); 0.25 × 2 = 0.5 (0); 0.5 × 2 = 1.0 (1) → 0.0101₂. Key says 0.1101₂.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Convert 0.3125₁₀ to base two.', '["0.0101₂","0.0111₂","0.1011₂","0.1101₂"]', '0.3125₁₀ = <u>0.0101₂</u> (key says 0.1101₂).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ccf0fsa5wen4pqkv33b2fhud7', 'Government', 'JAMB', null, 2020, null, 'The main source of financing local government in Nigeria is', null, '["internal revenue generation","Statutory Revenue Allocation","special state grants","grants-in-aid."]', 1, 'Statutory Revenue Allocation from the federation account is the main source.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The main source of financing local government in Nigeria is', '["internal revenue generation","<u>Statutory Revenue Allocation</u>","special state grants","grants-in-aid."]', '<u>Statutory Revenue Allocation</u>.', '{"bold":[],"italic":[],"underline":["Statutory Revenue Allocation"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ccf2vcrl52l7pqanyrv8c7dtv', 'Government', 'JAMB', null, 2020, null, 'The method used to determine the possible outcome of an electoral contest is', null, '["press review","plebiscite","opinion poll","referendum"]', 2, 'Opinion polls determine likely electoral outcomes.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The method used to determine the possible outcome of an electoral contest is', '["press review","plebiscite","<u>opinion poll</u>","referendum"]', '<u>Opinion poll</u>.', '{"bold":[],"italic":[],"underline":["opinion poll"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ccfbw6otdzyrv088555hjiw94', 'Biology', 'JAMB', null, 1983, null, 'The path taken by glucose from the ileum to the heart is', null, '["ileum- hepatic portal vein- hepatic artery-vena cava- heart","ileum- hepatic portal artery- hepatic artery-venacave- heart","ileum- hepatic portal vein-vena cava- heart","ileum- hepatic vein vena cava heart","ileum- hepatic portal vein- hepatic vein-vena cava heart"]', 2, 'Glucose travels via the hepatic portal vein then vena cava to the heart.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The path taken by <b>glucose</b> from the ileum to the heart is', '["ileum- hepatic portal vein- hepatic artery-vena cava- heart","ileum- hepatic portal artery- hepatic artery-venacave- heart","<u>ileum- hepatic portal vein-vena cava- heart</u>","ileum- hepatic vein vena cava heart","ileum- hepatic portal vein- hepatic vein-vena cava heart"]', 'Glucose travels via the <u>hepatic portal vein then vena cava</u> to the heart.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ccfvvyj8pc63obd607gg1wv7o', 'General Mathematics', 'WAEC', null, 2020, null, 'Given a*b = 2a - b. Is it commutative?', null, '["Yes","No","Only if a = b","None"]', 1, '2a-b ≠ 2b-a generally.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Given a*b = 2a - b. Is it commutative?', '["Yes","No","Only if a = b","None"]', '<u>No</u>, not commutative.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ccg2ohphf37ljd74ssgbhkiec', 'Chemistry', 'JAMB', null, 1994, null, 'A mixture of sand, ammonium chloride and sodium chloride is best separated by', null, '["sublimation followed by addition of water and filtration","sublimation followed by addition of water and evaporation","addition of water followed by filtration and sublimation","addition of water followed by crystallization and sublimation"]', 1, 'NH4Cl sublimes; NaCl dissolves and is recovered by evaporation; sand is filtered.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A mixture of sand, ammonium chloride and sodium chloride is best separated by', '["sublimation followed by addition of water and filtration","sublimation followed by addition of water and evaporation","addition of water followed by filtration and sublimation","addition of water followed by crystallization and sublimation"]', '<u>Sublimation → dissolution → filtration → evaporation</u>.', '{"bold":[],"italic":[],"underline":["sublimation followed by addition of water and evaporation"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ccg4vpq8gpdmscv1019jr96ez', 'General Mathematics', 'WAEC', null, 2020, null, 'The line y = mx + c is a tangent to the curve y = x² - 4x + 5. Find the possible value(s) of m.', null, '["m = 2 only","m = -2 only","m = 2 or -2","m = 0 only"]', 2, 'Tangent: discriminant = 0 → (m+4)² - 4(5-c) = 0; various m possible. Key says m = 2 or -2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The line y = mx + c is a tangent to the curve y = x² - 4x + 5. Find the possible value(s) of m.', '["m = 2 only","m = -2 only","m = 2 or -2","m = 0 only"]', 'm = <u>2 or -2</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ccg7vsdcc44bhq3vupcky3sbp', 'Government', 'JAMB', null, 2020, null, 'An electoral process in which candidates are selected for elective offices by party members is', null, '["primary election","bye election","electoral college","general election."]', 0, 'Primary elections select candidates by party members.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An electoral process in which candidates are selected for elective offices by party members is', '["<u>primary election</u>","bye election","electoral college","general election."]', '<u>Primary election</u>.', '{"bold":[],"italic":[],"underline":["primary election"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ccgbub1dcxb9w3ww419p49i3l', 'Government', 'JAMB', null, 2020, null, 'The Nigeria-Cameroun crisis over the Bakassi peninsula occurred owing to the interpretation of the treaty of 1913 and the', null, '["resolution of the OAU","Maroua Accord","decision of the ECOWAS Tribunal","decision of the International Court of Justice"]', 3, 'The ICJ decided the Bakassi dispute.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Nigeria-Cameroun crisis over the Bakassi peninsula occurred owing to the interpretation of the treaty of 1913 and the', '["resolution of the OAU","Maroua Accord","decision of the ECOWAS Tribunal","<u>decision of the International Court of Justice</u>"]', '<u>Decision of the International Court of Justice</u>.', '{"bold":[],"italic":[],"underline":["decision of the International Court of Justice"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ccgqk76gidd0p81rjt9fxkekh', 'Chemistry', 'JAMB', null, 1999, null, 'How many grammes of bromine will saturate 5.2g of but-1-ene-3-yne?', null, '["64.0g","48.0g","32.0g","16.0g [C=12, H=1, Br=80]"]', 1, 'Moles = 5.2/52 = 0.1; Br2 = 0.3 mol = 48g.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'How many grammes of bromine will saturate 5.2g of but-1-ene-3-yne?', '["64.0g","48.0g","32.0g","16.0g"]', 'Br2 = 0.3 mol = <u>48.0g</u>.', '{"bold":[],"italic":[],"underline":["48.0g"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cch15xbgjf096qc6vm63xpb7b', 'General Mathematics', 'WAEC', null, 2020, null, 'If x² + 4x + k > 0 for all real x, find k.', null, '["k > 4","k ≥ 4","k < 4","k ≤ 4"]', 0, 'Discriminant < 0 → 16 - 4k < 0 → k > 4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If x² + 4x + k > 0 for all real x, find k.', '["k > 4","k ≥ 4","k < 4","k ≤ 4"]', 'k > 4.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cchqoqbyrw8qafgqb1jernjnm', 'General Mathematics', 'WAEC', null, 2020, null, 'Simplify the expression √(3+2√2) + √(3-2√2).', null, '["2√2","2√3","2","√6"]', 2, '√(3+2√2) = √2+1; √(3-2√2) = √2-1; sum = 2√2. Key says 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Simplify the expression √(3+2√2) + √(3-2√2).', '["2√2","2√3","2","√6"]', 'Sum = <u>2√2</u> (key says 2).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cciae9dw087elqkj6hd3hswts', 'Islamic Religious Studies', 'JAMB', null, 2011, null, 'The teachings of <b>Uthman b. Fodio</b> are remembered today as it relates to', null, '["idol worshiping","marrying more than four wives","all form of syncreticism","taxing of farm produce"]', 2, 'Uthman b. Fodio fought against syncretism.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The teachings of <b>Uthman b. Fodio</b> are remembered today as it relates to', '["idol worshiping","marrying more than four wives","<u>all form of syncreticism</u>","taxing of farm produce"]', '<u>Uthman b. Fodio</u> fought against syncretism.', '{"bold":["Uthman b. Fodio"],"italic":[],"underline":["all form of syncreticism"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ccicj6pjdjov89m3z0i64iwkp', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Those exempted from paying jizyah are', null, '["Christians","Jews","women","men."]', 2, 'Women are exempted from jizyah.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Those exempted from paying jizyah are', '["Christians","Jews","<u>women</u>","men."]', '<u>Women</u>.', '{"bold":[],"italic":[],"underline":["women"],"fillBlanks":[]}');
