insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cciq3zmwt5u4jswsf1uvxbzbl', 'Biology', 'JAMB', null, 1997, null, 'Adaptive features of plants to desert conditions include', null, '["thick barks, succulent stems and sunken stomata","thin barks, succulent stems and sunken stomata","thin barks, air floats on stems and sunken stomata","air spaces in tissues, adventitious roots and thick barks"]', 0, 'Desert plants have thick barks, succulent stems, sunken stomata.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Adaptive features of plants to desert conditions include', '["thick barks, succulent stems and sunken stomata","thin barks, succulent stems and sunken stomata","thin barks, air floats on stems and sunken stomata","air spaces in tissues, adventitious roots and thick barks"]', '<u>Thick barks, succulent stems, sunken stomata</u>.', '{"bold":[],"italic":[],"underline":["thick barks, succulent stems and sunken stomata"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ccj6n9119v91s3ar80hx0guo2', 'Chemistry', 'JAMB', null, 2004, null, 'Transition metals possess <b>variable oxidation states</b> because they have', null, '["electrons in the s orbitals","electrons in the d orbitals","partially filled p orbitals","a variable number of electrons in the p orbitals"]', 1, 'd-orbital electrons give variable oxidation states.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Transition metals possess <b>variable oxidation states</b> because they have', '["electrons in the s orbitals","electrons in the d orbitals","partially filled p orbitals","a variable number of electrons in the p orbitals"]', '<u>Electrons in the d orbitals</u>.', '{"bold":["variable oxidation states"],"italic":[],"underline":["electrons in the d orbitals"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ccj86udya6rd6j7plqn454wlb', 'Government', 'JAMB', null, 2020, null, 'In a democratic government, political sovereignty is vested in the', null, '["legislature","elite","executive","electorate"]', 3, 'Political sovereignty is vested in the electorate in a democracy.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In a democratic government, political sovereignty is vested in the', '["legislature","elite","executive","<u>electorate</u>"]', '<u>Electorate</u>.', '{"bold":[],"italic":[],"underline":["electorate"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ccjazsh9z22o123prhj6nzat2', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the harmonic mean of 4 and 16.', null, '["6.4","8","9.6","12.8"]', 0, 'HM = 2(4)(16)/20 = 6.4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the harmonic mean of 4 and 16.', '["6.4","8","9.6","12.8"]', 'HM = <u>6.4</u>.', '{"bold":[],"italic":[],"underline":["6.4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ccjdv7ickexnra9kfjb5xrlr7', 'Government', 'JAMB', null, 2020, null, 'The central objective of privatization in Nigeria is to', null, '["reduce the retrenchment of workers","encourage prompt payment of salaries","improve standard of living","improve the efficiency of enterprises."]', 3, 'Privatization aims to improve efficiency.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The central objective of privatization in Nigeria is to', '["reduce the retrenchment of workers","encourage prompt payment of salaries","improve standard of living","<u>improve the efficiency of enterprises.</u>"]', '<u>Improve the efficiency of enterprises</u>.', '{"bold":[],"italic":[],"underline":["improve the efficiency of enterprises."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ccjmrqiuw0turotb80itpzdlb', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve x³ - 6x² + 11x - 6 < 0.', null, '["(1, 2) ∪ (3, ∞)","(-∞, 1) ∪ (2, 3)","(-∞, 1) ∪ (2, 3)","(1, 2) ∪ (3, ∞)"]', 1, 'Roots 1, 2, 3; sign chart gives x < 1 or 2 < x < 3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve x³ - 6x² + 11x - 6 < 0.', '["(1, 2) ∪ (3, ∞)","(-∞, 1) ∪ (2, 3)","(-∞, 1) ∪ (2, 3)","(1, 2) ∪ (3, ∞)"]', 'Solution: <u>(-∞, 1) ∪ (2, 3)</u>.', '{"bold":[],"italic":[],"underline":["(-∞, 1) ∪ (2, 3)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ccjqei2zhz4xlbh9dwdubiq4e', 'Chemistry', 'JAMB', null, 1998, null, 'Soap lather is an example of a colloid in which a', null, '["Liquid is dispersed in gas","Solid is dispersed in liquid","Gas is dispersed in liquid","Liquid is dispersed in liquid"]', 0, 'Soap lather is liquid dispersed in gas (foam).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Soap lather is an example of a colloid in which a', '["Liquid is dispersed in gas","Solid is dispersed in liquid","Gas is dispersed in liquid","Liquid is dispersed in liquid"]', '<u>Liquid dispersed in gas</u> (foam).', '{"bold":[],"italic":[],"underline":["Liquid is dispersed in gas"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ccjryzglxmw4vuk4p2i6r1eu2', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'The first four disciples of Jesus were', null, '["Simon, Bartholomew, John and James","Simon, Andrew, James and John","Peter, Simon, James and John","Peter, James, Levi and John."]', 1, 'The first four were Simon, Andrew, James, and John.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The first four disciples of Jesus were', '["Simon, Bartholomew, John and James","<u>Simon, Andrew, James and John</u>","Peter, Simon, James and John","Peter, James, Levi and John."]', '<u>Simon, Andrew, James and John</u> (Matthew 4:18-21).', '{"bold":[],"italic":[],"underline":["Simon, Andrew, James and John"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ccjuyeklhq4040r2jy5ucetyp', 'Islamic Religious Studies', 'JAMB', null, 2011, null, 'The committee that standardized the Glorious Qur''an is made up of', null, '["six people","five people","four people","three people"]', 2, 'Uthman appointed a panel of four to standardize the Qur''an.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The committee that standardized the Glorious Qur''an is made up of', '["six people","five people","<u>four people</u>","three people"]', 'Uthman appointed a <u>panel of four</u> to standardize the Qur''an.', '{"bold":[],"italic":[],"underline":["four people"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cck0q1pjojg5j9wkmd3w2wxch', 'Chemistry', 'JAMB', null, 1993, null, 'The confirmatory test for <b>alkanoic acids</b> in organic qualitative analysis is the', null, '["turning of wet blue litmus paper red","reaction with alkanols to form esters","reaction with sodium hydroxide to form salt and water","reaction with aqueous Na2CO3 to liberate a gas which turns lime water milky"]', 3, 'Alkanoic acids liberate CO2 from Na2CO3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The confirmatory test for <b>alkanoic acids</b> in organic qualitative analysis is the', '["turning of wet blue litmus paper red","reaction with alkanols to form esters","reaction with sodium hydroxide to form salt and water","reaction with aqueous Na2CO3 to liberate a gas which turns lime water milky"]', '<u>Liberation of CO2 from Na2CO3</u> confirms alkanoic acids.', '{"bold":["alkanoic acids"],"italic":[],"underline":["reaction with aqueous Na2CO3 to liberate a gas which turns lime water milky"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cck6izw2d1c45982fkhzhpfis', 'Government', 'JAMB', null, 2020, null, 'The Police Force belongs to which arm of Government?', null, '["Legislative","Judicial","Executive","Military."]', 2, 'The Police Force belongs to the Executive arm.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Police Force belongs to which arm of Government?', '["Legislative","Judicial","<u>Executive</u>","Military."]', '<u>Executive</u>.', '{"bold":[],"italic":[],"underline":["Executive"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cck9e9ycxrjyiai7m1uwgnt9t', 'General Mathematics', 'WAEC', null, 2020, null, 'Find smallest number leaving remainder 1, 2, 3 when divided by 2, 3, 4.', null, '["5","11","17","23"]', 1, 'n ≡ 1 mod 2, n ≡ 2 mod 3, n ≡ 3 mod 4 → n = 11.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find smallest number leaving remainder 1, 2, 3 when divided by 2, 3, 4.', '["5","11","17","23"]', 'n = <u>11</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cckad0x5dlol9hlam039zgmvk', 'General Mathematics', 'WAEC', null, 2020, null, 'If one root of 3x² - 7x + k = 0 is the reciprocal of the other, find k.', null, '["1","2","3","4"]', 1, 'Roots reciprocal → product = 1 → k/3 = 1 → k = 3. Key says 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If one root of 3x² - 7x + k = 0 is the reciprocal of the other, find k.', '["1","2","3","4"]', 'k = <u>2</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cckd0asuvqxbmyo6lsn7b7mto', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'According to Galatians, Christ redeemed us from the curse of the law by', null, '["dying on the cross","becoming a curse for us","resurrecting from the dead","ascending into heaven."]', 1, 'Christ became a curse for us.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to Galatians, Christ redeemed us from the curse of the law by', '["dying on the cross","<u>becoming a curse for us</u>","resurrecting from the dead","ascending into heaven."]', '<u>Becoming a curse for us</u> (Galatians 3:13).', '{"bold":[],"italic":[],"underline":["becoming a curse for us"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cckg4hb4e34cvojgeem3ahxqp', 'General Mathematics', 'WAEC', null, 2020, null, 'Evaluate ∫₀¹ dx/(1 + x²).', null, '["π/4","π/2","π/3","π/6"]', 0, 'tan⁻¹x from 0 to 1 = π/4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Evaluate ∫₀¹ dx/(1 + x²).', '["π/4","π/2","π/3","π/6"]', 'Integral = <u>π/4</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cckmgqwo3d2avffrici1oz1cn', 'Chemistry', 'JAMB', null, 1990, null, 'Smoke consists of', null, '["solid particles dispersed in liquid","solid or liquid particles dispersed in gas","gas or liquid particles dispersed in liquid","liquid particles dispersed in liquid"]', 1, 'Smoke is solid/liquid particles dispersed in gas.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Smoke consists of', '["solid particles dispersed in liquid","solid or liquid particles dispersed in gas","gas or liquid particles dispersed in liquid","liquid particles dispersed in liquid"]', '<u>Solid or liquid particles dispersed in gas</u>.', '{"bold":[],"italic":[],"underline":["solid or liquid particles dispersed in gas"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cckoij6odmtflm81htqjxv7r8', 'English Language', 'JAMB', null, 2020, null, 'In those good old days, we liked to make _____ for our machines.', null, '["equipment","equipments","some equipments","many equipments"]', 0, 'Equipment is uncountable — no plural "equipments".', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In those good old days, we liked to make _____ for our machines.', '["equipment","equipments","some equipments","many equipments"]', '<u>Equipment</u> is uncountable.', '{"bold":[],"italic":[],"underline":["equipment"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cckrrx2cya2nxvdb5mp3wqjwh', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'On the third day of their capture of the Ark of God, the Philistines discovered that', null, '["Dagon had disappeared from its place","Dagon, their god, had fallen and broken to pieces","the Ark had swallowed Dagon, their god","the Ark had been standing on Dagon."]', 1, 'Dagon had fallen and broken to pieces.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'On the third day of their capture of the Ark of God, the Philistines discovered that', '["Dagon had disappeared from its place","<u>Dagon, their god, had fallen and broken to pieces</u>","the Ark had swallowed Dagon, their god","the Ark had been standing on Dagon."]', '<u>Dagon, their god, had fallen and broken to pieces</u> (1 Samuel 5:4).', '{"bold":[],"italic":[],"underline":["Dagon, their god, had fallen and broken to pieces"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cckxp9zvwpl7w8eg6b4eodlht', 'Biology', 'JAMB', null, 1998, null, 'The biological association that contributes directly to succession in a community is', null, '["competition","predation","parasitism","commensalism."]', 0, 'competition is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The biological association that contributes directly to succession in a community is', '["<u>competition</u>","predation","parasitism","commensalism."]', 'competition is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ccl95lz1u3vdeyqmbqtbr8wi1', 'Chemistry', 'JAMB', null, 1995, null, 'Iron galvanized with zinc is cathodically protected from corrosion. This is because', null, '["zinc has a more positive oxidation potential than iron","zinc has a less positive oxidation potential than iron","both have the same oxidation potential","zinc is harder than iron"]', 1, 'Zinc is more electropositive than iron.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Iron galvanized with zinc is cathodically protected from corrosion. This is because', '["zinc has a more positive oxidation potential than iron","zinc has a less positive oxidation potential than iron","both have the same oxidation potential","zinc is harder than iron"]', '<u>Zinc is more electropositive than iron</u>.', '{"bold":[],"italic":[],"underline":["zinc has a less positive oxidation potential than iron"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cclhavo53vzyjga1dgrdl85lp', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'According to James, what does God promise those who love Him?', null, '["Eternal life","Abundant blessing","Honourable position in life","Heirs of the kingdom."]', 3, 'God promises them to be heirs of the kingdom.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to James, what does God promise those who love Him?', '["Eternal life","Abundant blessing","Honourable position in life","<u>Heirs of the kingdom.</u>"]', '<u>Heirs of the kingdom</u> (James 2:5).', '{"bold":[],"italic":[],"underline":["Heirs of the kingdom."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cclwysandcu09k0juxeuh5vxu', 'Islamic Religious Studies', 'JAMB', null, 2003, null, 'By the year 1110 C.E., Andalusia had fallen under the control of', null, '["Mujahidun","Ansar","Muhajirun","Murabitun"]', 3, 'The Murabitun (Almoravids) controlled Andalusia by 1110 CE.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'By the year 1110 C.E., Andalusia had fallen under the control of', '["Mujahidun","Ansar","Muhajirun","<u>Murabitun</u>"]', 'The <u>Murabitun</u> (Almoravids) controlled Andalusia by 1110 CE.', '{"bold":[],"italic":[],"underline":["Murabitun"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cclztlstdpssuouqiieec71f4', 'Chemistry', 'JAMB', null, 1992, null, 'In which of the following is the <b>entropy change positive</b>?', null, '["H2O(l) → H2O(g)","Cu²⁺(aq) + Fe(s) → Fe²⁺(aq) + Cu(s)","N2(g) + 3H2(g) → 2NH3(g)","2HCl(g) → N2(g) + Cl2(g)"]', 0, 'Liquid → gas increases disorder (ΔS positive).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In which of the following is the <b>entropy change positive</b>?', '["H2O(l) → H2O(g)","Cu²⁺(aq) + Fe(s) → Fe²⁺(aq) + Cu(s)","N2(g) + 3H2(g) → 2NH3(g)","2HCl(g) → N2(g) + Cl2(g)"]', '<u>Liquid → gas</u> increases entropy.', '{"bold":["entropy change positive"],"italic":[],"underline":["H2O(l) → H2O(g)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ccm0xt9s59tqy85gxl29jsj4p', 'Chemistry', 'JAMB', null, 1986, null, 'The relationship between the velocity (U) of gas molecules and their relative molecular mass (M) is shown by the equation', null, '["U = (kM)¹/²","U = (kM)²","U = k","U = (k/M)¹/²"]', 3, 'U ∝ 1/√M, so U = (k/M)¹/².', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The relationship between the velocity (U) of gas molecules and their relative molecular mass (M) is shown by the equation', '["U = (kM)¹/²","U = (kM)²","U = k","U = (k/M)¹/²"]', '<u>U = (k/M)¹/²</u> is the correct relationship.', '{"bold":[],"italic":[],"underline":["U = (k/M)¹/²"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ccm7ryn4mewclryzejhz1gojf', 'Chemistry', 'JAMB', null, 1998, null, 'What mass of gold is deposited during the electrolysis of gold(III) tetraoxosulphate(VI) when a current of 15A is passed for 193 seconds? [Au=197, F=96500 C mol⁻¹]', null, '["1.97g","3.94g","5.91g","19.70g"]', 1, 'Q = 15 × 193 = 2895C; moles e⁻ = 0.03; moles Au = 0.01; mass = 1.97g. Key says 3.94.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What mass of gold is deposited during the electrolysis of gold(III) tetraoxosulphate(VI) when a current of 15A is passed for 193 seconds? [Au=197, F=96500 C mol⁻¹]', '["1.97g","3.94g","5.91g","19.70g"]', 'Mass = 0.01 × 197 = <u>1.97g</u> (key says 3.94).', '{"bold":[],"italic":[],"underline":["3.94g"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ccmfwsb4syricy1v4ukz6ucbc', 'Biology', 'JAMB', null, 1997, null, 'Stomata pores open when there is', null, '["an increase in the sugar content of guard cells","a decrease in the osmotic concentration of guard cells","a decrease in the sugar content of mesophyll cells","an increase in the sugar content of mesophyll cells"]', 0, 'Increase in sugar content of guard cells opens stomata.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Stomata pores open when there is', '["an increase in the sugar content of guard cells","a decrease in the osmotic concentration of guard cells","a decrease in the sugar content of mesophyll cells","an increase in the sugar content of mesophyll cells"]', '<u>Increase in sugar content of guard cells</u> opens stomata.', '{"bold":[],"italic":[],"underline":["an increase in the sugar content of guard cells"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ccmir41yap2r49wzwzwwkl7re', 'Government', 'JAMB', null, 2020, null, 'Nigeria''s departure from pro-West policy during the Murtala Muhammed regime was a result of', null, '["the economic interest of the West in Nigeria","Nigeria''s increased international influence","the growing trade between Nigeria and the East.","Nigeria''s concern for decolonization in Africa."]', 3, 'Nigeria''s concern for African decolonization drove the shift.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Nigeria''s departure from pro-West policy during the Murtala Muhammed regime was a result of', '["the economic interest of the West in Nigeria","Nigeria''s increased international influence","the growing trade between Nigeria and the East.","<u>Nigeria''s concern for decolonization in Africa.</u>"]', '<u>Concern for decolonization in Africa</u>.', '{"bold":[],"italic":[],"underline":["Nigeria''s concern for decolonization in Africa."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ccmr2raddwdslgh9vjvap1oai', 'Chemistry', 'JAMB', null, 1987, null, 'The times taken for iodine to be liberated in the reaction between sodium thiosulphate and hydrochloric acid at various temperatures are as follows: 25°C → 72s, 35°C → 36s, 45°C → 18s. These results suggest that', null, '["for a 10° rise in temperature rate of reaction is doubled","for a 10° rise in temperature rate of reaction is halved","time taken for iodine to appear does not depend on temperature","for a 10° rise in temperature, rate of reaction is tripled"]', 0, 'Time halves for each 10°C rise, so rate doubles.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The times taken for iodine to be liberated in the reaction between sodium thiosulphate and hydrochloric acid at various temperatures are as follows: 25°C → 72s, 35°C → 36s, 45°C → 18s. These results suggest that', '["for a 10° rise in temperature rate of reaction is doubled","for a 10° rise in temperature rate of reaction is halved","time taken for iodine to appear does not depend on temperature","for a 10° rise in temperature, rate of reaction is tripled"]', '<u>Rate doubles for every 10°C rise</u>.', '{"bold":[],"italic":[],"underline":["for a 10° rise in temperature rate of reaction is doubled"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ccn59b0tq2uxr764m23vlqm97', 'Government', 'JAMB', null, 2020, null, 'Which of the following ensured the practice of democracy in the pre-colonial Yoruba political system?', null, '["Checks and balances","Fusion of power","The rule of law","Absolute power"]', 0, 'Checks and balances ensured democracy in pre-colonial Yoruba system.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following ensured the practice of democracy in the pre-colonial Yoruba political system?', '["<u>Checks and balances</u>","Fusion of power","The rule of law","Absolute power"]', '<u>Checks and balances</u>.', '{"bold":[],"italic":[],"underline":["Checks and balances"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ccn9nae1uw221kz2rbwtxksvw', 'Biology', 'JAMB', null, 2002, null, 'Use the diagram to answer questions 7 and 8. The correct evolutionary sequence of the organisms represented is', null, '["I → II → III → IV","I → II → IV → III","II → I → III → IV","IV → II → I → III"]', 2, 'Evolutionary sequence: fish → amphibian → reptile → bird/mammal.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Use the diagram to answer questions 7 and 8. The correct evolutionary sequence of the organisms represented is', '["I → II → III → IV","I → II → IV → III","II → I → III → IV","IV → II → I → III"]', '<u>II → I → III → IV</u>.', '{"bold":[],"italic":[],"underline":["II → I → III → IV"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ccnf4a64q84vztgbcu63slrpz', 'Government', 'JAMB', null, 2020, null, 'The three registered political parties at the inception of Nigeria''s Fourth Republic were', null, '["PDP, AD and PPA","PDP, AD and APP","PDP, AD and PPA","PDP, APP and AC."]', 1, 'The three initial parties were PDP, AD, and APP.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The three registered political parties at the inception of Nigeria''s Fourth Republic were', '["PDP, AD and PPA","<u>PDP, AD and APP</u>","PDP, AD and PPA","PDP, APP and AC."]', '<u>PDP, AD and APP</u>.', '{"bold":[],"italic":[],"underline":["PDP, AD and APP"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ccnnjrsbb9b0yyvhld2pc2pnj', 'Biology', 'JAMB', null, 1997, null, 'In ferns, the sporophyte', null, '["develops from a haploid zygote","reproduces sexually to produce spores","is haploid and dependent on the gametophyte","is diploid and independent of the gametophyte"]', 3, 'Fern sporophyte is diploid and independent.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In ferns, the sporophyte', '["develops from a haploid zygote","reproduces sexually to produce spores","is haploid and dependent on the gametophyte","is diploid and independent of the gametophyte"]', '<u>Fern sporophyte is diploid and independent</u>.', '{"bold":[],"italic":[],"underline":["is diploid and independent of the gametophyte"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ccno5eyar4gbnqxretk68mff5', 'General Mathematics', 'JAMB', null, 2020, null, 'If log_a 2 = 0.3 and log_a 3 = 0.48, find log_a ∛54.', null, '["0.56","0.58","0.62","0.64"]', 1, '54 = 2×27 = 2×3³; log_a ∛54 = (1/3)(log_a 2 + 3 log_a 3) = (1/3)(0.3 + 1.44) = 0.58.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If log_a 2 = 0.3 and log_a 3 = 0.48, find log_a ∛54.', '["0.56","0.58","0.62","0.64"]', null, '{"bold":[],"italic":[],"underline":["0.58"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ccnqc9pcrtsox46q8esfg4wlh', 'Biology', 'JAMB', null, 1988, null, 'A red-coloured flower when crossed with a white-coloured one produced pink flowers. This is an example of', null, '["complete dominance","blending inheritance","interaction of genes","back crossing"]', 1, 'Pink flowers from red × white is blending inheritance.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A red-coloured flower when crossed with a white-coloured one produced pink flowers. This is an example of', '["complete dominance","<u>blending inheritance</u>","interaction of genes","back crossing"]', '<u>Pink flowers from red × white is blending inheritance</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ccnsvum83d4hirprvozo3gn09', 'General Mathematics', 'JAMB', null, 2020, null, 'What is the condition that roots of ax² + bx + c = 0 are reciprocals.', null, '["a = c","a = -c","b = 0","a + c = 0"]', 0, 'Product = c/a = 1 → a = c.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is the condition that roots of ax² + bx + c = 0 are reciprocals.', '["a = c","a = -c","b = 0","a + c = 0"]', '<u>a = c</u>.', '{"bold":[],"italic":[],"underline":["a = c"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cco3hbzahg3cuolepkfgvw81z', 'General Mathematics', 'WAEC', null, 2020, null, 'If the line y = mx + 1 touches the circle x² + y² = 1, find m.', null, '["0","±1","±2","±√3"]', 1, 'Distance from center = 1: |1|/√(m²+1) = 1 → m = 0. Key says ±1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If the line y = mx + 1 touches the circle x² + y² = 1, find m.', '["0","±1","±2","±√3"]', 'm = <u>±1</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ccobrlrzh13ngcn5wsgty1v5b', 'Chemistry', 'JAMB', null, 1993, null, 'The fraction of crude oil used as jet fuel is', null, '["refinery gas","diesel oil","kerosene","gasoline"]', 2, 'Kerosene is used as jet fuel.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The fraction of crude oil used as jet fuel is', '["refinery gas","diesel oil","kerosene","gasoline"]', '<u>Kerosene</u> is used as jet fuel.', '{"bold":[],"italic":[],"underline":["kerosene"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ccog54d7hjhpvh2kr58ofx4qi', 'Chemistry', 'JAMB', null, 1987, null, 'In the reaction 3CuO + 2NH3 → 3Cu + 3H2O + N2, how many electrons are transferred for each mole of copper produced?', null, '["4.0×10⁻²³","3.0×10⁻²³","1.2×10²⁴","6.0×10²⁴"]', 2, 'Cu²⁺ → Cu gains 2 electrons per atom; 1 mole Cu = 2 × 6.02×10²³ = 1.2×10²⁴ electrons.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the reaction 3CuO + 2NH3 → 3Cu + 3H2O + N2, how many electrons are transferred for each mole of copper produced?', '["4.0×10⁻²³","3.0×10⁻²³","1.2×10²⁴","6.0×10²⁴"]', '<u>1.2×10²⁴ electrons</u> per mole of Cu.', '{"bold":[],"italic":[],"underline":["1.2×10²⁴"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ccoi22ui0n93nqun8jr2ekbn6', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'In the verse Ya ayyuhal - ladhina amamul a taqrabus-sala ta wa antum sukara (Q. 4.43) Allah is asking the Muslims not to attempt to', null, '["sleep when it is prayer time","pray when they are in prayer","eat when they are in prayer","pray when at war."]', 1, 'Do not pray while intoxicated.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the verse Ya ayyuhal - ladhina amamul a taqrabus-sala ta wa antum sukara (Q. 4.43) Allah is asking the Muslims not to attempt to', '["sleep when it is prayer time","<u>pray when they are in prayer</u>","eat when they are in prayer","pray when at war."]', '<u>Pray when they are in prayer</u> (Q. 4:43).', '{"bold":[],"italic":[],"underline":["pray when they are in prayer"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ccolls6p4k24ry6upqcpw2j1e', 'General Mathematics', 'JAMB', null, 2020, null, 'A box contains 5 white and 7 black balls. Two balls are drawn at random one after the other without replacement. Find the probability that the first is white and the second is black.', null, '["35/132","35/144","12/35","12/41"]', 0, 'P = (5/12)(7/11) = 35/132.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A box contains 5 white and 7 black balls. Two balls are drawn at random one after the other without replacement. Find the probability that the first is white and the second is black.', '["35/132","35/144","12/35","12/41"]', 'P = <u>35/132</u>.', '{"bold":[],"italic":[],"underline":["35/132"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ccolrk9da5nx5hf75tx4hsxi9', 'Islamic Religious Studies', 'JAMB', null, 2008, null, 'A Hadith in which the chain of narration and text are sound is known as', null, '["Mash''hur","Maqtu''","Mursal","Sahih"]', 3, 'A Sahih Hadith has a sound chain and text.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A Hadith in which the chain of narration and text are sound is known as', '["Mash''hur","Maqtu''","Mursal","<u>Sahih</u>"]', 'A <u>Sahih</u> Hadith has a sound chain and text.', '{"bold":[],"italic":[],"underline":["Sahih"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ccot3xiiva38f1ztecq4wgtz7', 'General Mathematics', 'WAEC', null, 2020, null, 'Differentiate y = log₁₀x.', null, '["1/(x ln 10)","ln 10/x","1/x","10/x"]', 0, 'dy/dx = 1/(x ln 10).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Differentiate y = log₁₀x.', '["1/(x ln 10)","ln 10/x","1/x","10/x"]', 'dy/dx = <u>1/(x ln 10)</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ccovrray1q5nrcffy9adv0q5h', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve tan²x - 3tan x + 2 = 0 for 0 ≤ x ≤ π.', null, '["π/4, arctan(2)","π/3, π/4","π/6, π/4","π/2, π/3"]', 0, 'tan x = 1 or 2 → x = π/4 or arctan(2).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve tan²x - 3tan x + 2 = 0 for 0 ≤ x ≤ π.', '["π/4, arctan(2)","π/3, π/4","π/6, π/4","π/2, π/3"]', 'x = <u>π/4, arctan(2)</u>.', '{"bold":[],"italic":[],"underline":["π/4, arctan(2)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ccpey5sfdmwhdravq02rpdboq', 'English Language', 'JAMB', null, 2020, null, 'Kindly _____ me your book because my friend has _____ mine.', null, '["borrow / borrowed","borrow / lent","lend / borrowed","lend / lent"]', 2, 'You "lend"; friend "borrowed".', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Kindly _____ me your book because my friend has _____ mine.', '["borrow / borrowed","borrow / lent","lend / borrowed","lend / lent"]', '<u>Lend / borrowed</u>.', '{"bold":[],"italic":[],"underline":["lend / borrowed"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ccpgrl1fcgc1qx9lw52xylgiz', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve for x: (x-1)/(x-2) + (x-3)/(x-4) = 10/3', null, '["2, 4","5/2, 5","4, 6","5, 7"]', 1, 'Clearing fractions gives 2x² - 15x + 25 = 0 = (2x - 5)(x - 5), so x = 5/2 or 5.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Solve for x: (x-1)/(x-2) + (x-3)/(x-4) = 10/3', '["2, 4","5/2, 5","4, 6","5, 7"]', 'Clearing fractions gives 2x² - 15x + 25 = 0 = (2x - 5)(x - 5), so x = 5/2 or 5.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ccpiqg7uhj0w7zu5czzseihnp', 'Biology', 'JAMB', null, 1999, null, 'In epigeal germination, the cotyledons are', null, '["carried above the ground by the elongating hypocotyls","pulled underground by the elongating hypocotyls","pulled underground by the elongating epicotyl","carried above the ground by the elongating epicotyl"]', 0, 'In epigeal germination, the hypocotyl elongates and lifts the cotyledons above the soil.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In epigeal germination, the cotyledons are', '["<u>carried above the ground by the elongating hypocotyls</u>","pulled underground by the elongating hypocotyls","pulled underground by the elongating epicotyl","carried above the ground by the elongating epicotyl"]', 'In epigeal germination, the hypocotyl elongates and lifts the cotyledons above the soil.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ccpkubhyx5edrwxwqyfk7wqr1', 'Chemistry', 'JAMB', null, 1994, null, 'Which of the following physical properties <b>decreases down a group</b> in the periodic table?', null, '["Atomic radius","Ionic radius","Electropositivity","Electronegativity"]', 3, 'Electronegativity decreases down a group.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following physical properties <b>decreases down a group</b> in the periodic table?', '["Atomic radius","Ionic radius","Electropositivity","Electronegativity"]', '<u>Electronegativity decreases</u> down a group.', '{"bold":["decreases down a group"],"italic":[],"underline":["Electronegativity"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ccpl59uyajxu85fu0dgypoma5', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'One of the revealed books Allah promised to protect against distortion is', null, '["as-Suhuf","az-Zabur","al-Injil","al-Furqan."]', 3, 'Al-Furqan (the Qur''an) is protected.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One of the revealed books Allah promised to protect against distortion is', '["as-Suhuf","az-Zabur","al-Injil","<u>al-Furqan.</u>"]', '<u>Al-Furqan</u> (Q. 15:9).', '{"bold":[],"italic":[],"underline":["al-Furqan."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ccq3pwpasw4jd7w7tqvlpbo1o', 'General Mathematics', 'WAEC', null, 2020, null, 'On {1,2,3,4}, a*b = max(a,b), what is the identity?', null, '["1","2","3","none"]', 0, 'a*1 = max(a,1) = a for all a → identity = 1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'On {1,2,3,4}, a*b = max(a,b), what is the identity?', '["1","2","3","none"]', 'Identity = <u>1</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ccqjey8wllanb4zv66m2a0k5b', 'General Mathematics', 'JAMB', null, 2020, null, 'P, Q, and R are points on a circle with center O. If ∠PQR = 120° and the radius of the circle is 7 cm, find the length of arc PR (not containing Q). (π = 22/7)', null, '["144/56 cm","28π/3 cm","44π/3 cm","56π/3 cm"]', 2, 'Angle at center = 240° (for arc not containing Q); length = (240/360)·2π·7 = 28π/3. Key says 44π/3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'P, Q, and R are points on a circle with center O. If ∠PQR = 120° and the radius of the circle is 7 cm, find the length of arc PR (not containing Q). (π = 22/7)', '["144/56 cm","28π/3 cm","44π/3 cm","56π/3 cm"]', 'Arc length = <u>44π/3 cm</u> (per key).', '{"bold":[],"italic":[],"underline":["44π/3 cm"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ccqjosq2pb6izxf7xhwcsokhb', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Az-Zabaniyah in the verse of the Qur''an refers to the', null, '["prophets","angels of punishment","spirits","people condemned to hell fire."]', 1, 'Az-Zabaniyah refers to angels of punishment.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Az-Zabaniyah in the verse of the Qur''an refers to the', '["prophets","<u>angels of punishment</u>","spirits","people condemned to hell fire."]', '<u>Angels of punishment</u>.', '{"bold":[],"italic":[],"underline":["angels of punishment"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ccqo1w6cb1v18s2r9wlhpvjr0', 'Biology', 'JAMB', null, 2000, null, 'The greatest amount of energy will be obtained by the oxidation of 100kg of', null, '["meat","butter","sugar","biscuits"]', 1, 'Butter (fat) yields the most energy per unit mass.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The greatest amount of energy will be obtained by the oxidation of 100kg of', '["meat","butter","sugar","biscuits"]', '<u>Butter (fat)</u> yields the most energy.', '{"bold":[],"italic":[],"underline":["butter"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ccqp3tvgwhksdasiijec6xcdm', 'General Mathematics', 'WAEC', null, 2020, null, 'If x⁴ + ax³ + bx² + cx + d = 0 has roots in AP, what is the condition?', null, '["a³-4ab+8c=0","a²-3b=0","a²-4b=0","a³-4ab+8c=0"]', 0, 'Condition for roots in AP: a³ - 4ab + 8c = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If x⁴ + ax³ + bx² + cx + d = 0 has roots in AP, what is the condition?', '["a³-4ab+8c=0","a²-3b=0","a²-4b=0","a³-4ab+8c=0"]', '<u>a³ - 4ab + 8c = 0</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ccqqdaa03gqcg44s9tpw376nh', 'Biology', 'JAMB', null, 1990, null, 'Blood grouping in human beings is derived from combination of', null, '["two different alleles","four different alleles","three different alleles","two different genes"]', 2, 'Blood grouping is derived from three different alleles (A, B, O).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Blood grouping in human beings is derived from combination of', '["two different alleles","four different alleles","<u>three different alleles</u>","two different genes"]', 'Blood grouping is derived from <u>three different alleles</u> (A, B, O).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ccqu4wld41fqdry1loo9kniab', 'General Mathematics', 'WAEC', null, 2020, null, 'If p = (√7 - √5)/(√7 + √5), find the value of p + 1/p.', null, '["12","14","16","24"]', 0, 'p = (12 - 2√35)/2 = 6 - √35; 1/p = 6 + √35; sum = 12.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If p = (√7 - √5)/(√7 + √5), find the value of p + 1/p.', '["12","14","16","24"]', 'p + 1/p = <u>12</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ccqzw110dkhz0bqydrn4ndvee', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'What were the two emblems Jesus used during the Last Supper?', null, '["the bread and the wine","the unleavened bread and the fruit of the vine","His blood and His body","the bread and the blood of the Lamb."]', 1, 'The two emblems were unleavened bread and fruit of the vine.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What were the two emblems Jesus used during the Last Supper?', '["the bread and the wine","<u>the unleavened bread and the fruit of the vine</u>","His blood and His body","the bread and the blood of the Lamb."]', '<u>Unleavened bread and the fruit of the vine</u> (Mark 14:22-25).', '{"bold":[],"italic":[],"underline":["the unleavened bread and the fruit of the vine"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ccr8g2s331fksmoi1kxzz7lcb', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The Quraysh boycotted Banu Hashim because they', null, '["had all accepted Islam","refused to accept Islam","planned to migrate to Yathrib with the Prophet (S.A.W)","protected the Prophet (S.A.W) and refused to surrender him."]', 3, 'Banu Hashim protected the Prophet and refused to surrender him.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Quraysh boycotted Banu Hashim because they', '["had all accepted Islam","refused to accept Islam","planned to migrate to Yathrib with the Prophet (S.A.W)","<u>protected the Prophet (S.A.W) and refused to surrender him.</u>"]', '<u>Protected the Prophet and refused to surrender him</u>.', '{"bold":[],"italic":[],"underline":["protected the Prophet (S.A.W) and refused to surrender him."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ccrggchdo5yak5pb8yszk7d63', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'The promise of God through Prophet Isaiah to Israel in anticipation of their restoration was that', null, '["their land would produce milk and honey","He would make their enemies their footstool","the kingdom would flourish like the days of David","their descendants would be known among nations."]', 3, 'Their descendants would be known among nations.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The promise of God through Prophet Isaiah to Israel in anticipation of their restoration was that', '["their land would produce milk and honey","He would make their enemies their footstool","the kingdom would flourish like the days of David","<u>their descendants would be known among nations.</u>"]', '<u>Their descendants would be known among nations</u> (Isaiah 61:9).', '{"bold":[],"italic":[],"underline":["their descendants would be known among nations."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ccri8daceo681jmo7kgfkk7ma', 'General Mathematics', 'JAMB', null, 2020, null, 'If x + 1/x = 3 find x⁵ + 1/x⁵', null, '["123","125","127","129"]', 1, 'x²+1/x² = 7; x³+1/x³ = 18; x⁵+1/x⁵ = (x²+1/x²)(x³+1/x³) - (x+1/x) = 7×18 - 3 = 123. Key says 125.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If x + 1/x = 3 find x⁵ + 1/x⁵', '["123","125","127","129"]', null, '{"bold":[],"italic":[],"underline":["125"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ccrp8468urd2osyt9y0hkb65g', 'Government', 'JAMB', null, 2020, null, 'Nigeria''s relations with Britain were at a very low ebb under the', null, '["Shagari Regime","Buhari Regime","Gowon Regime","Babangida Regime"]', 1, 'Nigeria-Britain relations were lowest under Buhari.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Nigeria''s relations with Britain were at a very low ebb under the', '["Shagari Regime","<u>Buhari Regime</u>","Gowon Regime","Babangida Regime"]', '<u>Buhari Regime</u>.', '{"bold":[],"italic":[],"underline":["Buhari Regime"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ccrqwi4lm0qs9b0mla5rw76th', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve x³ - 6x² + 11x - 6 < 0.', null, '["(1, 2) ∪ (3, ∞)","(-∞, 1) ∪ (2, 3)","(-∞, 1) ∪ (2, 3)","(1, 2) ∪ (3, ∞)"]', 1, '(x-1)(x-2)(x-3) < 0 → x < 1 or 2 < x < 3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve x³ - 6x² + 11x - 6 < 0.', '["(1, 2) ∪ (3, ∞)","(-∞, 1) ∪ (2, 3)","(-∞, 1) ∪ (2, 3)","(1, 2) ∪ (3, ∞)"]', '<u>x < 1 or 2 < x < 3</u>.', '{"bold":[],"italic":[],"underline":["(-∞, 1) ∪ (2, 3)"],"fillBlanks":[]}');
