insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cd4po0t3l99h7uynhi6ot4ikp', 'Chemistry', 'JAMB', null, 1994, null, 'Elements X, Y and Z belong to groups 1, V and VII respectively. Which of the following is TRUE about the bond types of XZ and YZ3?', null, '["Both are electrovalent","Both are covalent","XZ is electrovalent and YZ3 is covalent","XZ is covalent and YZ3 is electrovalent"]', 2, 'XZ (metal + non-metal) = ionic; YZ3 (non-metal + non-metal) = covalent.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Elements X, Y and Z belong to groups 1, V and VII respectively. Which of the following is TRUE about the bond types of XZ and YZ3?', '["Both are electrovalent","Both are covalent","XZ is electrovalent and YZ3 is covalent","XZ is covalent and YZ3 is electrovalent"]', '<u>XZ ionic; YZ3 covalent</u>.', '{"bold":["TRUE"],"italic":[],"underline":["XZ is electrovalent and YZ3 is covalent"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cd4qw0wsjkqdz5etywgixblp0', 'Chemistry', 'JAMB', null, 1994, null, 'Which of the following compounds is a <b>base</b>?', null, '["CO2","CaO","H3PO3","CH3COOH"]', 1, 'CaO is a basic oxide (base).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following compounds is a <b>base</b>?', '["CO2","CaO","H3PO3","CH3COOH"]', '<u>CaO is a basic oxide</u>.', '{"bold":["base"],"italic":[],"underline":["CaO"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cd4tn2zeu5n71ttef559lk0w4', 'Biology', 'JAMB', null, 1998, null, 'The basic point of impact by changes which produce mutation is the', null, '["gametes","chromosomes","phenotype","zygote. hoolgist.com"]', 1, 'chromosomes is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The basic point of impact by changes which produce mutation is the', '["gametes","<u>chromosomes</u>","phenotype","zygote. hoolgist.com"]', 'chromosomes is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cd4w52yrjkdsa2l3ugba4zo3w', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Two Christian virtues to be learned in the story of the Good Samaritan are', null, '["kindness and fairness","justice and humility","compassion and humility","compassion and mercy"]', 3, 'The Good Samaritan teaches compassion and mercy.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Two Christian virtues to be learned in the story of the Good Samaritan are', '["kindness and fairness","justice and humility","compassion and humility","<u>compassion and mercy</u>"]', '<u>Compassion and mercy</u>.', '{"bold":[],"italic":[],"underline":["compassion and mercy"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cd4yuwlenst13olfgnvf5usct', 'General Mathematics', 'WAEC', null, 2020, null, 'A bag contains 5 red, 4 blue, and 3 green balls. Three balls are drawn at random without replacement. What is the probability that they are all of different colors?', null, '["1/11","3/11","5/11","10/11"]', 1, 'P = (5·4·3)/12C3 = 60/220 = 3/11.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A bag contains 5 red, 4 blue, and 3 green balls. Three balls are drawn at random without replacement. What is the probability that they are all of different colors?', '["1/11","3/11","5/11","10/11"]', 'P = <u>3/11</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cd50w7kh0fdkmgoagtb0iie5t', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Peter in his teaching on humility, admonishes Christians to', null, '["safeguard their faith","seek things that are above","be gentle in spirit","avoid life''s anxiety"]', 3, 'They should avoid life''s anxiety.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Peter in his teaching on humility, admonishes Christians to', '["safeguard their faith","seek things that are above","be gentle in spirit","<u>avoid life''s anxiety</u>"]', '<u>Avoid life''s anxiety</u> (1 Peter 5:5-7).', '{"bold":[],"italic":[],"underline":["avoid life''s anxiety"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cd57se2yulqva4wjwc77d4i4s', 'Chemistry', 'JAMB', null, 1987, null, 'If d represents the density of a gas and K is a constant, the rate of gaseous diffusion is related to the equation', null, '["r = k","r = kd","r = k/√d","r = k√d"]', 2, 'Graham''s law: rate ∝ 1/√d, so r = k/√d.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If d represents the density of a gas and K is a constant, the rate of gaseous diffusion is related to the equation', '["r = k","r = kd","r = k/√d","r = k√d"]', '<u>r = k/√d</u> (Graham''s law).', '{"bold":[],"italic":[],"underline":["r = k/√d"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cd59vaedfhhe5nepwhj9qzres', 'Biology', 'JAMB', null, 1985, null, 'Oxygen-demanding wastes are considered to be a water pollutant because they', null, '["deplete oxygen which is necessary for the survival of aquatic organisms","increase oxygen which is necessary for the survival of aquatic organisms","increase other gaseous species which are necessary for survival of aquatic organisms","deplete other gaseous species which are necessary for the survival of aquatic organisms"]', 0, 'Oxygen-demanding wastes deplete dissolved oxygen.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Oxygen-demanding wastes are considered to be a water pollutant because they', '["deplete oxygen which is necessary for the survival of aquatic organisms","increase oxygen which is necessary for the survival of aquatic organisms","increase other gaseous species which are necessary for survival of aquatic organisms","deplete other gaseous species which are necessary for the survival of aquatic organisms"]', '<u>They deplete dissolved oxygen</u> needed by aquatic life.', '{"bold":[],"italic":[],"underline":["deplete oxygen which is necessary for the survival of aquatic organisms"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cd5b8vixdgxmm5gf1ar1rqb0g', 'Government', 'JAMB', null, 2020, null, 'The centre piece of Nigeria''s foreign policy covers only', null, '["Latin America","Asia","Europe","Africa"]', 3, 'Africa is the centre-piece of Nigeria''s foreign policy.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The centre piece of Nigeria''s foreign policy covers only', '["Latin America","Asia","Europe","<u>Africa</u>"]', '<u>Africa</u>.', '{"bold":[],"italic":[],"underline":["Africa"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cd5ihov8270jex24esjgnor2v', 'Chemistry', 'JAMB', null, 1989, null, 'The products of the thermal decomposition of <b>ammonium trioxonitrate(V)</b> are', null, '["NO and oxygen","NH3 and oxygen","nitrogen and water","N2O and water"]', 3, 'NH4NO3 → N2O + 2H2O on heating.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The products of the thermal decomposition of <b>ammonium trioxonitrate(V)</b> are', '["NO and oxygen","NH3 and oxygen","nitrogen and water","N2O and water"]', '<u>NH4NO3 → N2O + 2H2O</u>.', '{"bold":["ammonium trioxonitrate(V)"],"italic":[],"underline":["N2O and water"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cd5je5oqjorrcp8g5es8jzyte', 'Biology', 'JAMB', null, 1990, null, 'The production of violet colouration, when dilute NaOH solution is added to a solution of food substance, followed by drops of 1% CUSO solution while shaking indicates the presence of', null, '["protein","carbohydrates","fats","reducing sugar"]', 0, 'The Biuret test for protein gives a violet colouration.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The production of violet colouration, when dilute NaOH solution is added to a solution of food substance, followed by drops of 1% CUSO solution while shaking indicates the presence of', '["<u>protein</u>","carbohydrates","fats","reducing sugar"]', 'The <u>Biuret test for protein</u> gives a violet colouration.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cd5mks3i82mtkycw76qshogmg', 'Biology', 'JAMB', null, 2000, null, 'Peripheral arrangement of vascular tissues in dicots is a characteristic of the internal structure of the', null, '["leaf","petiole","stem","root"]', 2, 'Peripheral vascular arrangement is in the stem.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Peripheral arrangement of vascular tissues in dicots is a characteristic of the internal structure of the', '["leaf","petiole","stem","root"]', '<u>Stem</u> has peripheral vascular arrangement.', '{"bold":[],"italic":[],"underline":["stem"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cd5yxi6is5zmpvmvxsvafj6ta', 'Biology', 'JAMB', null, 1995, null, 'The end product of glycolysis in plants and animals is', null, '["pyruvic acid","citric acid","aspartic acid","malic acid."]', 0, 'Glycolysis breaks glucose down to pyruvic acid.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The end product of glycolysis in plants and animals is', '["<u>pyruvic acid</u>","citric acid","aspartic acid","malic acid."]', 'Glycolysis breaks glucose down to pyruvic acid.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cd5zp935ueluacjrv2tg0xgwp', 'Chemistry', 'JAMB', null, 1987, null, 'Magnesium ribbon was allowed to burn inside a given gas P leaving a white solid residue Q. Addition of water to Q liberated a gas which produced dense white fumes with a drop of hydrochloric acid. The gas P was', null, '["nitrogen","chlorine","oxygen","sulphur(IV) oxide"]', 0, 'Mg + N2 → Mg3N2; Mg3N2 + H2O → NH3; NH3 + HCl → NH4Cl (white fumes).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Magnesium ribbon was allowed to burn inside a given gas P leaving a white solid residue Q. Addition of water to Q liberated a gas which produced dense white fumes with a drop of hydrochloric acid. The gas P was', '["nitrogen","chlorine","oxygen","sulphur(IV) oxide"]', '<u>Nitrogen</u> gives Mg3N2 → NH3 → white fumes with HCl.', '{"bold":[],"italic":[],"underline":["nitrogen"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cd61npd2s27k56gzpjd3w1fjq', 'General Mathematics', 'WAEC', null, 2020, null, 'If f(x) = |x|³, find f''(0).', null, '["0","1","-1","Does not exist"]', 0, 'f(x) = |x|³ is differentiable at 0; f''(0) = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If f(x) = |x|³, find f''(0).', '["0","1","-1","Does not exist"]', 'f''(0) = <u>0</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cd65qqpvzx8qw1pbsi1l3cspm', 'Physics', 'JAMB', null, 2021, null, 'The electrons responsible for the properties and reaction of an element is', null, '["active electrons","valence electrons","Net electron","Octet electron"]', 1, 'Valence electrons determine the chemical properties of an element.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The electrons responsible for the properties and reaction of an element is', '["active electrons","<u>valence electrons</u>","Net electron","Octet electron"]', '<u>Valence electrons</u> determine the chemical properties of an element.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cd67c3d0-9374-4be6-850b-ded7d08eed75', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'During the voyage to Rome, some people thought that Paul was a god because', null, '["he caused rain to fall","an angel appeared to him","he was not harmed by a viper","he broke his chains easily"]', 2, 'Paul was not harmed by a viper, so people thought he was a god.', true, '2026-09-12 10:41:03.268', '2026-09-12 10:41:03.268', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cd68k9kq1lzavv33wtfqrmhyf', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve √(x + 2) > x.', null, '["[-2, 2)","[-2, 2]","[0, 2)","[-2, 0)"]', 0, 'x + 2 > x² (for x ≥ 0) → x² - x - 2 < 0 → -1 < x < 2. For -2 ≤ x < 0, true. So -2 ≤ x < 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve √(x + 2) > x.', '["[-2, 2)","[-2, 2]","[0, 2)","[-2, 0)"]', 'Solution: <u>[-2, 2)</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cd6a0itzgh69vjec516d09p16', 'Islamic Religious Studies', 'JAMB', null, 2011, null, 'The battle that served as a pointer to the compilation of the Glorious Qur''an was fought at', null, '["Khandaq","Uhud","Tabuk","Yamamah"]', 3, 'The Battle of Yamamah led to the compilation of the Qur''an.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The battle that served as a pointer to the compilation of the Glorious Qur''an was fought at', '["Khandaq","Uhud","Tabuk","<u>Yamamah</u>"]', 'The <u>Battle of Yamamah</u> led to the compilation of the Qur''an.', '{"bold":[],"italic":[],"underline":["Yamamah"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cd6fwsjh97dhpfh9m51tleh56', 'General Mathematics', 'JAMB', null, 2020, null, 'If 243ₓ = 123₁₀, find x.', null, '["6","7","8","9"]', 0, '2x² + 4x + 3 = 123 → 2x² + 4x - 120 = 0 → x² + 2x - 60 = 0 → x = 6.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If 243ₓ = 123₁₀, find x.', '["6","7","8","9"]', '243ₓ = 2x² + 4x + 3 = 123 → <u>x = 6</u>.', '{"bold":[],"italic":[],"underline":["6"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cd6nrzbh70zwsbmd01nfgyj9a', 'General Mathematics', 'WAEC', null, 2020, null, 'If a*b = a + 2b, solve 2*x = 3*x.', null, '["0","1","2","no solution"]', 3, '2 + 2x = 3 + 2x → 2 = 3, no solution.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If a*b = a + 2b, solve 2*x = 3*x.', '["0","1","2","no solution"]', '<u>No solution</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cd6tsul9u1oskhr708vql6wx6', 'Chemistry', 'JAMB', null, 1988, null, 'An increase in temperature causes an increase in the pressure of a gas because there is an increase in the', null, '["average velocity of the molecules","number of collisions between the molecules","density of the molecules","free mean path between each molecule and other"]', 3, 'Increasing temperature increases molecular motion and collision frequency.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An increase in temperature causes an increase in the pressure of a gas because there is an increase in the', '["average velocity of the molecules","number of collisions between the molecules","density of the molecules","free mean path between each molecule and other"]', 'Increasing temperature increases <u>molecular motion and collision frequency</u>.', '{"bold":[],"italic":[],"underline":["free mean path between each molecule and other"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cd6xhuyj9a3cid7tvqng6k7re', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The sources of the Shari''ah include', null, '["Qur''an, Hadith and common law","Hadith, Qiyas and parliamentary proceedings","Qiyas, Ta''wil and Falsafah","Qur''an, Ijma and Qiyas."]', 3, 'The sources include Qur''an, Ijma, and Qiyas.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The sources of the Shari''ah include', '["Qur''an, Hadith and common law","Hadith, Qiyas and parliamentary proceedings","Qiyas, Ta''wil and Falsafah","<u>Qur''an, Ijma and Qiyas.</u>"]', '<u>Qur''an, Ijma and Qiyas</u>.', '{"bold":[],"italic":[],"underline":["Qur''an, Ijma and Qiyas."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cd70c71vcig4w76foy6fasen3', 'General Mathematics', 'WAEC', null, 2020, null, 'If α, β, γ are the roots of x³ - 3x² + 2x - 1 = 0, find α²β + α²γ + β²α + β²γ + γ²α + γ²β.', null, '["2","3","6","8"]', 1, 'Σα²β = (α+β+γ)(αβ+βγ+γα) - 3αβγ = 3·2 - 3·1 = 3.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'If α, β, γ are the roots of x³ - 3x² + 2x - 1 = 0, find α²β + α²γ + β²α + β²γ + γ²α + γ²β.', '["2","3","6","8"]', 'Σα²β = (α+β+γ)(αβ+βγ+γα) - 3αβγ = 3·2 - 3·1 = 3.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cd71eaf6-aa9a-4434-8d9f-aef3ed5b0102', 'Physics', 'JAMB', null, 1991, null, '4 g of a radioactive material of half-life 10 days is spilled on a laboratory floor. How long would it take to disintegrate 3.5 g of the material?', null, '["1¼ days","8¾ days","30 days","80 days."]', 2, 'If 3.5 g disintegrates, 0.5 g remains, which is 1/8 of 4 g. That takes 3 half-lives = 30 days.', true, '2026-10-12 19:15:34.535', '2026-10-12 19:15:34.535', null, null, null, '4 g of a radioactive material of half-life 10 days is spilled on a laboratory floor. How long would it take to disintegrate 3.5 g of the material?', '["1¼ days","8¾ days","30 days","80 days."]', 'If 3.5 g disintegrates, 0.5 g remains, which is 1/8 of 4 g. That takes 3 half-lives = 30 days.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cd73e581-a427-4461-a043-4862b6a8a964', 'Physics', 'JAMB', null, 1993, null, 'Two forces of magnitudes 7 N and 3 N act at right angles to each other. The angle θ between the resultant and the 7 N force is given by', null, '["cos θ = 3/7","sin θ = 3/7","tan θ = 3/7","cot θ = 3/7"]', 2, 'The resultant makes angle θ with the 7 N force, with opposite side 3 and adjacent side 7, so tan θ = 3/7.', true, '2026-10-12 19:15:37.002', '2026-10-12 19:15:37.002', null, null, null, 'Two forces of magnitudes 7 N and 3 N act at right angles to each other. The angle θ between the resultant and the 7 N force is given by', '["cos θ = 3/7","sin θ = 3/7","tan θ = 3/7","cot θ = 3/7"]', 'The resultant makes angle θ with the 7 N force, with opposite side 3 and adjacent side 7, so tan θ = 3/7.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cd74d094-28c6-48bd-be36-04f679ee8589', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The leader has the <u>unstinting</u> support of his party.', null, '["unsparing","laudable","uninspiring","cautious"]', 0, 'Unstinting = unsparing.', true, '2026-10-24 01:01:52.035', '2026-10-24 01:01:52.035', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The leader has the <u>unstinting</u> support of his party.', '["<u>unsparing</u>","laudable","uninspiring","cautious"]', '<b>Unstinting</b> = <b>unsparing</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cd75idntva3fa85cnf4coo3qv', 'Chemistry', 'JAMB', null, 2019, null, 'Which of the following is an halide ore?', null, '["Cassiterite","Anglesite","Siderite","Carnalite"]', 3, 'Carnallite (KCl·MgCl2·6H2O) is a halide ore.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is an <b>halide ore</b>?', '["Cassiterite","Anglesite","Siderite","<u>Carnalite</u>"]', '<u>Carnallite (KCl·MgCl2·6H2O)</u> is a halide ore.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cd785fa2-42fd-4b09-9824-febf817f3dea', 'Yoruba', 'JAMB', null, 2007, null, 'Be ìtumõ ‘The committee will look into the crisis’.', null, '["Ìgbìmõ yóò dá sí aàwõ náà","Ìgbìmõ á lè dá sí aàwõ náà","Ìgbìmo lè dá sí aàwò náà","Ìgbìmõ á ti dá sí aàwõ náà."]', 0, 'Ìtumõ tó péye ni Ìgbìmõ yóò dá sí aàwõ náà.', true, '2026-10-13 13:23:31.685', '2026-10-13 13:23:31.685', null, null, null, 'Be ìtumõ ‘The committee will look into the crisis’.', '["Ìgbìmõ yóò dá sí aàwõ náà","Ìgbìmõ á lè dá sí aàwõ náà","Ìgbìmo lè dá sí aàwò náà","Ìgbìmõ á ti dá sí aàwõ náà."]', 'Ìtumõ tó péye ni Ìgbìmõ yóò dá sí aàwõ náà.', '{"bold":["Ìgbìmõ yóò dá sí aàwõ náà"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cd7gh82hgl7b9k1t2xf8ibd7w', 'General Mathematics', 'JAMB', null, 2020, null, 'If log_a b = 3 and log_b a = 2 find log_a √b.', null, '["0.5","0.75","1","1.5"]', 1, 'log_a √b = (1/2) log_a b = 1.5. But log_a b = 3 and log_b a = 2 are inconsistent (product should be 1). Key says 0.75.', false, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'If log_a b = 3 and log_b a = 2 find log_a √b.', '["0.5","0.75","1","1.5"]', '(1/2)(3) = <u>1.5</u> (key says 0.75).', '{"bold":[],"italic":[],"underline":["0.75"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cd7i37vps8ryrh0eiltct7jq0', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'In Surat an-Nas, protection was sought from the evils of', null, '["men and women","husband and wife","men and jinn","male and female."]', 2, 'Protection is sought from men and jinn.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In Surat an-Nas, protection was sought from the evils of', '["men and women","husband and wife","<u>men and jinn</u>","male and female."]', '<u>Men and jinn</u> (Q. 114).', '{"bold":[],"italic":[],"underline":["men and jinn"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cd7iofen5i12kq88i9iquqyco', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve (x-2)/(x+3) ≤ 0.', null, '["(-3, 2)","[-3, 2)","(-3, 2]","[-3, 2]"]', 2, '(x-2)/(x+3) ≤ 0: critical points x = 2 and x = -3; sign chart gives -3 < x ≤ 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Solve (x-2)/(x+3) ≤ 0.', '["(-3, 2)","[-3, 2)","(-3, 2]","[-3, 2]"]', '(x-2)/(x+3) ≤ 0: critical points x = 2 and x = -3; sign chart gives -3 < x ≤ 2.', '{"bold":[],"italic":[],"underline":["[-3, 2)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cd7jw7gdgueqwu2pa4t1x43lz', 'English Language', 'JAMB', null, 2020, null, 'When he had arranged the furniture, he _____ the picture on the wall.', null, '["hanged","hung","hang","hunged"]', 1, 'Hung for suspending a picture.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When he had arranged the furniture, he _____ the picture on the wall.', '["hanged","hung","hang","hunged"]', '<u>Hung</u> for a picture.', '{"bold":[],"italic":[],"underline":["hung"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cd7qorix8d8200ezguhorn984', 'Biology', 'JAMB', null, 1999, null, 'Which of the following is one of Lamarck’s theories?', null, '["some variations are more favorable to existence in a given environment than others","all living organisms are constantly involved in a struggle for existence","the size of a given population remains fairly constant","new species originate through the inheritance of acquired traits."]', 3, 'Lamarck proposed inheritance of acquired characteristics.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is one of Lamarck’s theories?', '["some variations are more favorable to existence in a given environment than others","all living organisms are constantly involved in a struggle for existence","the size of a given population remains fairly constant","<u>new species originate through the inheritance of acquired traits.</u>"]', 'Lamarck proposed inheritance of acquired characteristics.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cd7w6i1tb3chzuct55yx6zogh', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'According to John, Jesus said the work of God is', null, '["preaching the gospel","healing the sick","feeding the hungry who are in need","believing in Him who he had sent."]', 3, 'The work of God is to believe in Him whom He has sent.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to John, Jesus said the work of God is', '["preaching the gospel","healing the sick","feeding the hungry who are in need","<u>believing in Him who he had sent.</u>"]', '<u>Believing in Him who he had sent</u> (John 6:29).', '{"bold":[],"italic":[],"underline":["believing in Him who he had sent."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cd84ccae-33ee-4b3f-8362-d5454be27848', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation).The corrupt official had to leave the public service <u>willy-nilly</u>.', null, '["unprepared","reluctantly","willingly","compulsorily","by retirement"]', 1, '''Willy-nilly'' = whether willing or not/reluctantly.', true, '2026-10-24 01:04:15.946', '2026-10-24 01:04:15.946', null, null, null, '(Choose the most appropriate interpretation).The corrupt official had to leave the public service <u>willy-nilly</u>.', '["unprepared","<u>reluctantly</u>","willingly","compulsorily","by retirement"]', '''<b>Willy-nilly</b>'' = whether willing or not/<b>reluctantly</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cd86n3pqlkmfqhyfawbb6m2p3', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the sum of n terms: 1² + 3² + 5² + ...', null, '["n(4n² - 1)/3","n(2n - 1)(2n + 1)/3","n(2n + 1)(2n - 1)/6","n(4n² + 1)/3"]', 0, 'Sum = n(2n-1)(2n+1)/3 = n(4n²-1)/3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the sum of n terms: 1² + 3² + 5² + ...', '["n(4n² - 1)/3","n(2n - 1)(2n + 1)/3","n(2n + 1)(2n - 1)/6","n(4n² + 1)/3"]', 'Sum = <u>n(4n² - 1)/3</u>.', '{"bold":[],"italic":[],"underline":["n(4n² - 1)/3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cd8777c7-e52e-4dc0-aded-921e01b166cf', 'Literature in English', 'JAMB', null, 2026, null, 'The expression ''colo'' means', null, '["prim and proper","out of date","in-fashion","outside of brain"]', 1, '''Colo'' means out of date.', true, '2026-09-12 11:10:05.685', '2026-09-12 11:10:05.685', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cd89f6d7-31fb-48a5-80bd-74262e78c6c9', 'English Language', 'JAMB', null, 2007, null, 'When Ajike met her <u>__________</u> husband at the party, she felt like reconciling with him.', null, '["estranged","strange","caring","loving"]', 0, 'Correct spelling: estranged.', true, '2026-10-24 07:21:38.338', '2026-10-24 07:21:38.338', null, null, null, 'When Ajike met her <u>__________</u> husband at the party, she felt like reconciling with him.', '["estranged","strange","caring","loving"]', 'Correct spelling: estranged.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cd8dfnujqrkh7ozefxjor8ddp', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Identify the surah to which the ayah belongs.', null, '["at-Tin","al-Fajr","ad-Duha","al-''Alaq"]', 2, 'The ayah belongs to Surat ad-Duha.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Identify the surah to which the ayah belongs.', '["at-Tin","al-Fajr","<u>ad-Duha</u>","al-''Alaq"]', '<u>Ad-Duha</u>.', '{"bold":[],"italic":[],"underline":["ad-Duha"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cd8h5l9t25tz3e2ctdrhwiknk', 'Chemistry', 'JAMB', null, 2004, null, 'A given volume of methane diffuses in 20s. How long will it take the same volume of sulphur(VI) oxide to diffuse under the same conditions?', null, '["40s","60s","20s","5s [C=12, H=1, S=32, O=16]"]', 0, 'Rate ∝ 1/√M; t(SO2)/t(CH4) = √(64/16) = 2; t = 40s.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A given volume of methane diffuses in 20s. How long will it take the same volume of sulphur(VI) oxide to diffuse under the same conditions?', '["40s","60s","20s","5s"]', 'Time = 20 × 2 = <u>40s</u>.', '{"bold":[],"italic":[],"underline":["40s"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cd8jd45uqx7rd149m2v8xdg1l', 'Chemistry', 'JAMB', null, 1986, null, 'What reaction takes place when palm-oil is added to potash and foams are observed?', null, '["Neutralization","Saponification","Etherification","Salting-out"]', 1, 'Saponification is the alkaline hydrolysis of fats to form soap.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What reaction takes place when palm-oil is added to potash and foams are observed?', '["Neutralization","Saponification","Etherification","Salting-out"]', '<u>Saponification</u> is the alkaline hydrolysis of fats.', '{"bold":[],"italic":[],"underline":["Saponification"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cd8mka6k9lvm3e9s49g1uxn3y', 'Biology', 'JAMB', null, 1993, null, 'The failure of transport and respiratory systems in plants as well as the presence of reddish colour in stems and leaves result from the deficiency of', null, '["magnesium","nitrogen","potassium","phosphorus"]', 1, 'Nitrogen deficiency causes reddish colour and poor transport.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The failure of transport and respiratory systems in plants as well as the presence of reddish colour in stems and leaves result from the deficiency of', '["magnesium","<u>nitrogen</u>","potassium","phosphorus"]', '<u>Nitrogen deficiency</u> causes reddish colour and poor transport.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cd8pdrarutsqlknmp7elv98d8', 'Biology', 'JAMB', null, 1995, null, 'During the bending of the arm, the biceps muscle', null, '["contracts and the triceps muscle relaxes","relaxes and the triceps muscle contracts","and the triceps muscle contract","and the triceps muscle relax."]', 0, 'contracts and the triceps muscle relaxes is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'During the bending of the arm, the biceps muscle', '["<u>contracts and the triceps muscle relaxes</u>","relaxes and the triceps muscle contracts","and the triceps muscle contract","and the triceps muscle relax."]', 'contracts and the triceps muscle relaxes is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cd8v4qzmahuiz9cezqc54onud', 'Government', 'JAMB', null, 2020, null, 'In which of the following systems is the power of the component units more than that of the central government?', null, '["Monarchical","Unitary","Federal","Confederal"]', 3, 'In a confederation, component units have more power than the centre.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In which of the following systems is the power of the component units more than that of the central government?', '["Monarchical","Unitary","Federal","<u>Confederal</u>"]', '<u>Confederal</u>.', '{"bold":[],"italic":[],"underline":["Confederal"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cd9118qzpuml9zfasg9v8vpzd', 'Chemistry', 'JAMB', null, 1983, null, 'Which among the elements 1. Carbon 2. Oxygen 3. Copper 4. Bromine 5. Zinc will <b>NOT react</b> with either water or steam?', null, '["1 and 2","2 and 3","3 and 4","1, 2, and 3","2, 3 and 5"]', 2, 'Copper and bromine do not react with water or steam.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which among the elements 1. Carbon 2. Oxygen 3. Copper 4. Bromine 5. Zinc will <b>NOT react</b> with either water or steam?', '["1 and 2","2 and 3","3 and 4","1, 2, and 3","2, 3 and 5"]', '<u>Copper and bromine</u> do not react with water or steam.', '{"bold":["NOT react"],"italic":[],"underline":["3 and 4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cd9374ctcakwx2up3uheazglg', 'Chemistry', 'JAMB', null, 2004, null, 'Chlorine consisting of two isotopes of mass numbers 35 and 37 in the ratio 3:1 has an atomic mass of 35.5. Calculate the relative abundance of the isotope of mass number 37.', null, '["60","20","75","25"]', 3, 'Abundance of 37 = 25%.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Chlorine consisting of two isotopes of mass numbers 35 and 37 in the ratio 3:1 has an atomic mass of 35.5. Calculate the relative abundance of the isotope of mass number 37.', '["60","20","75","25"]', 'Abundance = <u>25%</u>.', '{"bold":[],"italic":[],"underline":["25"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cd95f0b4-5d9e-413c-8603-7ccbd325dba2', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. They attacked all regulations designed to <u>emasculate</u> student militancy.', null, '["condone","isolate","punish","strengthen"]', 3, 'Emasculate = weaken; opposite = strengthen.', true, '2026-10-24 07:21:19.325', '2026-10-24 07:21:19.325', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. They attacked all regulations designed to <u>emasculate</u> student militancy.', '["condone","isolate","punish","strengthen"]', 'Emasculate = weaken; opposite = strengthen.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cd9kn32d6645j84smy7lwo24f', 'Islamic Religious Studies', 'JAMB', null, 2008, null, 'A Hadith in which the chain of narration and text are sound is known as', null, '["Mash''hur","Maqtu''","Mursal","Sahih"]', 3, 'A Sahih Hadith has a sound chain and text.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A Hadith in which the chain of narration and text are sound is known as', '["Mash''hur","Maqtu''","Mursal","<u>Sahih</u>"]', 'A <u>Sahih</u> Hadith has a sound chain and text.', '{"bold":[],"italic":[],"underline":["Sahih"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cd9pqqeao329wixu8fvt18mga', 'Government', 'JAMB', null, 2020, null, 'One major advantage of the unitary system is that it tends to make government', null, '["Popular among the masses","Strong and stable","Free of controversy","Distant from the people"]', 1, 'Unitary systems make government strong and stable.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One major advantage of the unitary system is that it tends to make government', '["Popular among the masses","<u>Strong and stable</u>","Free of controversy","Distant from the people"]', '<u>Strong and stable</u>.', '{"bold":[],"italic":[],"underline":["Strong and stable"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cd9vayz557cw9sewvht44ap48', 'Chemistry', 'JAMB', null, 1983, null, 'The flame used by welders in cutting metals is', null, '["butane gas flame","acetylene flame","kerosene flame","oxy-acetylene flame","oxygen flame"]', 3, 'The oxy-acetylene flame is used for welding/cutting metals due to its high temperature.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The flame used by welders in cutting metals is', '["butane gas flame","acetylene flame","kerosene flame","oxy-acetylene flame","oxygen flame"]', 'The <u>oxy-acetylene flame</u> is used for welding/cutting metals due to its high temperature.', '{"bold":[],"italic":[],"underline":["oxy-acetylene flame"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cd9wwc36z0qh1iio0ztp00bta', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the probability that a family with exactly 4 children has at least 3 boys.', null, '["1/4","5/16","3/8","1/2"]', 1, 'P = 4C3(1/2)⁴ + 4C4(1/2)⁴ = 4/16 + 1/16 = 5/16.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the probability that a family with exactly 4 children has at least 3 boys.', '["1/4","5/16","3/8","1/2"]', 'P = <u>5/16</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cd9zlvcfpdy0m0d47ch7l5l6c', 'General Mathematics', 'WAEC', null, 2020, null, 'If A, B are 3×3 with |A| = 2, |B| = -3, find |2AᵀB⁻¹|.', null, '["8/3","-16/3","-4/3","4/3"]', 1, '|2AᵀB⁻¹| = 2³·|A|/|B| = 8·2/(-3) = -16/3.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'If A, B are 3×3 with |A| = 2, |B| = -3, find |2AᵀB⁻¹|.', '["8/3","-16/3","-4/3","4/3"]', '|2AᵀB⁻¹| = 2³·|A|/|B| = 8·2/(-3) = -16/3.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cda2of78avbt1gqtv4jwsblvb', 'General Mathematics', 'WAEC', null, 2020, null, 'If a, b, c are in GP, then 1/(a-b) + 1/(b-c) = ?', null, '["1/a","1/b","1/c","0"]', 1, 'Let b² = ac; 1/(a-b) + 1/(b-c) = (b-c+a-b)/((a-b)(b-c)) = (a-c)/((a-b)(b-c)); simplify → 1/b.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If a, b, c are in GP, then 1/(a-b) + 1/(b-c) = ?', '["1/a","1/b","1/c","0"]', 'Value = <u>1/b</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cda3666gwh2nz8n2tsiqc0ngm', 'General Mathematics', 'WAEC', null, 2020, null, 'If (1, 2), (3, k), and (5, 6) are collinear, find k.', null, '["4","3","5","2"]', 0, 'Slope = (6-2)/(5-1) = 1; k = 2 + 2(1) = 4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If (1, 2), (3, k), and (5, 6) are collinear, find k.', '["4","3","5","2"]', 'k = <u>4</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cda3z6fqh94mx6ppq9tz0yg2w', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'The people who told Saul that David was hiding in the hill of Hachilah were the', null, '["Ziphites","Hittites","Kenites","Cherethites."]', 0, 'The Ziphites told Saul.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The people who told Saul that David was hiding in the hill of Hachilah were the', '["<u>Ziphites</u>","Hittites","Kenites","Cherethites."]', '<u>Ziphites</u> (1 Samuel 26:1).', '{"bold":[],"italic":[],"underline":["Ziphites"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cda8qzpcajftcitp1o2tsfc1s', 'Biology', 'JAMB', null, 1998, null, 'A group of organisms of different species living in a particular area is described as a', null, '["colony","community","population","niche."]', 3, 'niche. is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A group of organisms of different species living in a particular area is described as a', '["colony","community","population","<u>niche.</u>"]', 'niche. is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdacwnaux9eljsw6og4l71xtu', 'Biology', 'JAMB', null, 1986, null, 'Two main distinguishing features of the cervical vertebrae are the presence of', null, '["short neural spine and vertebral canal","prezygapophysis and cervical ribs","large centrum and cervical ribs","vertebral canal and large centrum"]', 1, 'Cervical vertebrae have prezygapophysis and cervical ribs.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Two main distinguishing features of the cervical vertebrae are the presence of', '["short neural spine and vertebral canal","<u>prezygapophysis and cervical ribs</u>","large centrum and cervical ribs","vertebral canal and large centrum"]', 'Cervical vertebrae have <u>prezygapophysis and cervical ribs</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdaf1f54-1c0d-409c-9a5a-85489ce9dce0', 'Biology', 'JAMB', null, 2002, null, 'In a population study using the transect method, a student is likely to record the highest number of species in', null, '["a tropical rain forest","a guinea savanna","a sahel savanna","an estuarine swamp"]', 0, 'Tropical rainforests have the highest species diversity.', true, '2026-10-12 20:59:30.751', '2026-10-12 20:59:30.751', null, null, null, 'In a population study using the transect method, a student is likely to record the highest number of species in', '["a tropical rain forest","a guinea savanna","a sahel savanna","an estuarine swamp"]', 'Tropical rainforests have the highest species diversity.', '{"bold":["Tropical rainforests"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdao2uzlvscrmgihunfi1bskp', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'In his exhortation on interpersonal relationship, Peter recommends that the elders should', null, '["give no room for wine","live exemplary lives","have the willingness to give","be shepherds of the flock of God"]', 1, 'Elders should live exemplary lives.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In his exhortation on interpersonal relationship, Peter recommends that the elders should', '["give no room for wine","<u>live exemplary lives</u>","have the willingness to give","be shepherds of the flock of God"]', '<u>Live exemplary lives</u> (1 Peter 5:3).', '{"bold":[],"italic":[],"underline":["live exemplary lives"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdap5cm1igimbprugiiru2pqi', 'Chemistry', 'JAMB', null, 1983, null, 'Zn + H2SO4 → ZnSO4 + H2. The rate of the above reaction will be greatly increased if', null, '["the zinc is in the powdered form","a greater volume of the acid is used","a smaller volume of the acid is used","the reaction vessel is immersed in an ice-bath","the zinc is in the form of pellets"]', 0, 'Powdered zinc has a larger surface area, increasing reaction rate.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Zn + H2SO4 → ZnSO4 + H2. The rate of the above reaction will be greatly increased if', '["the zinc is in the powdered form","a greater volume of the acid is used","a smaller volume of the acid is used","the reaction vessel is immersed in an ice-bath","the zinc is in the form of pellets"]', '<u>Powdered zinc</u> has a larger surface area.', '{"bold":[],"italic":[],"underline":["the zinc is in the powdered form"],"fillBlanks":[]}');
