insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdayu01erviz2miz53jxic0f6', 'Islamic Religious Studies', 'JAMB', null, 2003, null, 'The initial idea to preserve the Glorious Qur''an was mooted by', null, '["Abu Bakr As-Saddiq","Umar b. Khattab","Zaid b. Thabit","Uthman b. Affan"]', 1, 'Umar b. Khattab first suggested the compilation of the Qur''an after the Battle of Yamamah.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The initial idea to preserve the Glorious Qur''an was mooted by', '["Abu Bakr As-Saddiq","<u>Umar b. Khattab</u>","Zaid b. Thabit","Uthman b. Affan"]', '<u>Umar b. Khattab</u> first suggested the compilation of the Qur''an.', '{"bold":[],"italic":[],"underline":["Umar b. Khattab"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdb04q1b3au6w2et60hbdbpms', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The uniqueness of the Glorious Qur''an, according to Q.39:28, lies in the fact that it is', null, '["highly educative","in brief form","revealed piecemeal","revealed in Arabic."]', 3, 'It is revealed in Arabic.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The uniqueness of the Glorious Qur''an, according to Q.39:28, lies in the fact that it is', '["highly educative","in brief form","revealed piecemeal","<u>revealed in Arabic.</u>"]', '<u>Revealed in Arabic</u> (Q. 39:28).', '{"bold":[],"italic":[],"underline":["revealed in Arabic."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdb13wjedfrbmlzdoi9tu54on', 'Government', 'JAMB', null, 2020, null, 'The application of the principle of separation of powers seems impracticable because power is', null, '["fused","separated","delegated","centralized"]', 0, 'In practice, power is often fused.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The application of the principle of separation of powers seems impracticable because power is', '["<u>fused</u>","separated","delegated","centralized"]', 'Power is <u>fused</u> in practice.', '{"bold":[],"italic":[],"underline":["fused"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdb44ihddy0favkhjc67itdl0', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Lord, if you will, you can make me clean. The statement above was made by the', null, '["centurion servant","epileptic boy","leper","paralytic"]', 2, 'The leper made this statement.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Lord, if you will, you can make me clean. The statement above was made by the', '["centurion servant","epileptic boy","<u>leper</u>","paralytic"]', '<u>Leper</u> (Matthew 8:2).', '{"bold":[],"italic":[],"underline":["leper"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdb49eb7-01ff-40d2-ac46-421b76abb232', 'Literature in English', 'JAMB', null, 2026, null, 'In She Walks in Beauty, the contrast between ''dark'' and ''bright'' primarily emphasizes', null, '["Moral conflict","Physical environment","Harmonious balance in beauty","Supernatural imagery"]', 2, 'The contrast emphasizes harmonious balance in beauty.', true, '2026-09-12 11:05:12.745', '2026-09-12 11:05:12.745', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdb4lubh6n7mcel3y184z3zzz', 'English Language', 'JAMB', null, 2020, null, 'There are several _____ in the farmyard.', null, '["sheep","ewe","lamb","goat"]', 0, 'Plural of "sheep" is "sheep".', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'There are several _____ in the farmyard.', '["sheep","ewe","lamb","goat"]', 'Plural of "sheep" is <u>sheep</u>.', '{"bold":[],"italic":[],"underline":["sheep"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdb4o10nl120fszi27h6qwsbe', 'General Mathematics', 'WAEC', null, 2020, null, 'If 20% fail math, 15% fail physics, 10% fail both. What percentage pass both?', null, '["75%","80%","85%","90%"]', 1, 'Fail at least one = 20 + 15 - 10 = 25%; pass both = 75%. Key says 80%.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If 20% fail math, 15% fail physics, 10% fail both. What percentage pass both?', '["75%","80%","85%","90%"]', 'Pass both = <u>80%</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdb871c9-99f4-49e9-ab91-dde19c87b627', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Many states practise the ideals of <u>democracy</u>.', null, '["government by elections","government by representatives","government by civilians","government by all the people","oligarchy"]', 3, 'Democracy = government by all the people.', true, '2026-10-24 01:03:53.597', '2026-10-24 01:03:53.597', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Many states practise the ideals of <u>democracy</u>.', '["government by elections","government by representatives","government by civilians","<u>government by all the people</u>","oligarchy"]', '<b>Democracy</b> = <b>government by all the people</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdbd0tu3sukoau5ti6tjtisoa', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The battle of Siffin led to the emergence of the', null, '["Khawarij","Ahl al-Sunnah","Munafiqun","Umayyads"]', 0, 'The Battle of Siffin led to the emergence of the Khawarij.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The battle of Siffin led to the emergence of the', '["<u>Khawarij</u>","Ahl al-Sunnah","Munafiqun","Umayyads"]', '<u>Khawarij</u>.', '{"bold":[],"italic":[],"underline":["Khawarij"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdbd738b-1b0a-44ad-856d-d220cd4aa9c5', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. He <u>deprecated</u> the attempts made to unseat him.', null, '["resisted","condemned","despised","challenged"]', 1, 'Deprecated = condemned.', true, '2026-10-24 01:04:09.178', '2026-10-24 01:04:09.178', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. He <u>deprecated</u> the attempts made to unseat him.', '["resisted","<u>condemned</u>","despised","challenged"]', '<b>Deprecated</b> = <b>condemned</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdbeoh8bg6isi3d3a8645m5tf', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve x⁴ - 5x² + 4 = 0 in reals.', null, '["±1, ±2","±1, ±4","±2, ±3","±1, ±2"]', 0, 'y² - 5y + 4 = 0 → y = 1 or 4 → x = ±1, ±2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve x⁴ - 5x² + 4 = 0 in reals.', '["±1, ±2","±1, ±4","±2, ±3","±1, ±2"]', '<u>x = ±1, ±2</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdbwg8tmg8xysyihj14m4q7lj', 'General Mathematics', 'WAEC', null, 2020, null, 'If a*b = a + b - ab, find the identity element in the reals.', null, '["0","1","-1","none"]', 0, 'a*e = a → a + e - ae = a → e(1-a) = 0 → e = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If a*b = a + b - ab, find the identity element in the reals.', '["0","1","-1","none"]', 'Identity = <u>0</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdc24ebd-38de-4fbf-a857-71fb78612ccd', 'Financial Accounting', 'UTME', null, 2004, null, 'Given: N Rent 10 000 Rates 5 000 Capital 50 000 Salaries 14 000 Cash 26 000 Creditors 5 000. The total trial balance is', 'https://res.cloudinary.com/kwi1uv0g/image/upload/v1791841637/questions/x5ijms83cwu7wviwqyhb.jpg', '["N110 00","N65 000","N55 000","N45 000"]', 2, 'Rent 10000 + Rates 5000 + Salaries 14000 + Cash 26000 = 55000. Creditors 5000 + Capital 50000 = 55000. Total trial balance = 55,000.', true, '2026-10-12 22:00:01.803', '2026-10-12 22:00:01.803', null, null, null, 'Given: N Rent 10 000 Rates 5 000 Capital 50 000 Salaries 14 000 Cash 26 000 Creditors 5 000. The total trial balance is', '["N110 00","N65 000","<b>N55 000</b>","N45 000"]', 'Rent 10000 + Rates 5000 + Salaries 14000 + Cash 26000 = 55000. Creditors 5000 + Capital 50000 = 55000. Total trial balance = <b>55,000</b>.', '{"bold":["55,000"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdc2726f-a4f8-40d7-ba5a-e8626173a20e', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Eze''s skin now looks <u>flabby</u> as a result of his changed circumstances.', null, '["neat","firm","weak","oily"]', 1, 'Flabby = loose; opposite = firm.', true, '2026-10-24 07:21:16.279', '2026-10-24 07:21:16.279', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Eze''s skin now looks <u>flabby</u> as a result of his changed circumstances.', '["neat","firm","weak","oily"]', 'Flabby = loose; opposite = firm.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdc3eckbteebv6ad5mx3fqqbg', 'Government', 'JAMB', null, 2020, null, 'The difference between commercialized and privatized companies is that in the former', null, '["public ownership is dominant.","government subsidizes costs.","profit motive is recessive.","private ownership is dominant."]', 0, 'In commercialized companies, public ownership is dominant.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The difference between commercialized and privatized companies is that in the former', '["<u>public ownership is dominant.</u>","government subsidizes costs.","profit motive is recessive.","private ownership is dominant."]', '<u>Public ownership is dominant</u>.', '{"bold":[],"italic":[],"underline":["public ownership is dominant."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdc3si0kfoq7sm56kt1yxg0lg', 'General Mathematics', 'WAEC', null, 2020, null, 'Find d/dx(cosh⁻¹x).', null, '["1/√(x² - 1)","1/√(1 - x²)","1/√(x² + 1)","-1/√(x² - 1)"]', 0, 'd/dx(cosh⁻¹x) = 1/√(x² - 1).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find d/dx(cosh⁻¹x).', '["1/√(x² - 1)","1/√(1 - x²)","1/√(x² + 1)","-1/√(x² - 1)"]', 'Derivative = <u>1/√(x² - 1)</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdc62871-c5d5-42d0-9e35-5828d037a42b', 'Economics', 'JAMB', null, 2026, null, 'The only essential attribute of a good currency is', null, '["Scarcity","Homogeneity","Acceptability","Cognizability"]', 2, 'Acceptability is the only essential attribute of good currency. Money must be generally accepted by everyone as a medium of exchange. Without acceptability, money cannot function as a medium of exchange, unit of account, store of value, or standard of deferred payment. While scarcity, homogeneity, and cognizability are desirable qualities, acceptability is the fundamental requirement for money to serve its functions.', true, '2026-09-10 10:42:54.645', '2026-09-10 10:42:54.645', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdc7eb2b-8181-4317-8f8a-44462f14edc2', 'Physics', 'JAMB', null, 1989, null, 'A vibrator of frequency 60 Hz is used in generating transverse stationary waves in a long thin wire. If the average distance between successive nodes on the wire is 45 cm, find the speed of the transverse waves in the wire.', null, '["27 m s⁻¹","54 m s⁻¹","90 m s⁻¹","108 m s⁻¹"]', 1, 'Successive nodes are λ/2 apart, so λ = 90 cm = 0.9 m. v = fλ = 60 x 0.9 = 54 m s⁻¹.', true, '2026-10-12 19:15:29.25', '2026-10-12 19:15:29.25', null, null, null, 'A vibrator of frequency 60 Hz is used in generating transverse stationary waves in a long thin wire. If the average distance between successive nodes on the wire is 45 cm, find the speed of the transverse waves in the wire.', '["27 m s<sup>-1</sup>","54 m s<sup>-1</sup>","90 m s<sup>-1</sup>","108 m s<sup>-1</sup>"]', 'Successive nodes are λ/2 apart, so λ = 90 cm = 0.9 m. v = fλ = 60 x 0.9 = 54 m s<sup>-1</sup>.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdcd3g3f2tm12sefndiofanmg', 'Chemistry', 'JAMB', null, 1993, null, 'NaCl(s) + H2SO4(l) → HCl(g) + NaHSO4(s). In the reaction above, H2SO4 behaves as', null, '["a strong acid","an oxidizing agent","a good solvent","a dehydrating agent"]', 0, 'H2SO4 acts as a strong acid, displacing HCl.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'NaCl(s) + H2SO4(l) → HCl(g) + NaHSO4(s). In the reaction above, H2SO4 behaves as', '["a strong acid","an oxidizing agent","a good solvent","a dehydrating agent"]', '<u>H2SO4 acts as a strong acid</u>.', '{"bold":[],"italic":[],"underline":["a strong acid"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdce9535-de14-41ba-8d5a-c568f12e8900', 'Physics', 'JAMB', null, 2026, null, 'Photometer is used to measure', null, '["Kinetic energy of liberated electrons","Intensity of light","frequency of light","wavelength of light"]', 1, 'A photometer is used to measure the intensity of light. It compares the luminous intensity of different light sources or measures the intensity of a single source.', true, '2026-09-10 10:56:49.855', '2026-09-10 10:56:49.855', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdcf53a1-2f6b-4ee6-833b-40bedeb80ddd', 'Economics', 'JAMB', null, 2026, null, 'A production possibility curve shows', null, '["how much of resources a society uses to produce a particular commodity","the rate of inflation","the rate of unemployment in an economy","the various combinations of the commodities that can be produced","all of the above"]', 3, 'A production possibility curve (PPC) shows the various combinations of two commodities that can be produced with given resources and technology. It illustrates the concept of opportunity cost, scarcity, and efficiency. Points on the curve represent efficient production, points inside represent inefficiency, and points outside are unattainable. The PPC does not show inflation or unemployment rates.', true, '2026-09-10 10:41:19.971', '2026-09-10 10:41:19.971', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdch6v7kddzh953flkiyo0oak', 'General Mathematics', 'WAEC', null, 2020, null, 'Evaluate the expression 2^(log₂3) × 3^(log₃2).', null, '["5","6","7","8"]', 1, '2^(log₂3) = 3; 3^(log₃2) = 2; product = 6.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Evaluate the expression 2^(log₂3) × 3^(log₃2).', '["5","6","7","8"]', null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdcj7msyopk717ry8y6jrlhbd', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Zedekiah, the king of Judah, was captured by the army of the Chaldeans', null, '["at Riblah","in the plains of Jericho","at Arabah","on the outskirts of Jerusalem."]', 1, 'He was captured in the plains of Jericho.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Zedekiah, the king of Judah, was captured by the army of the Chaldeans', '["at Riblah","<u>in the plains of Jericho</u>","at Arabah","on the outskirts of Jerusalem."]', '<u>In the plains of Jericho</u> (2 Kings 25:5).', '{"bold":[],"italic":[],"underline":["in the plains of Jericho"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdckav43v4vfg3kouijotwdvx', 'General Mathematics', 'WAEC', null, 2020, null, 'What is the equation of the perpendicular bisector of the segment joining (1,2) and (3,4)?', null, '["x + y = 5","x - y = 0","x + y = 3","x - y = 2"]', 0, 'Midpoint (2,3); slope of segment = 1; perpendicular slope = -1; y-3 = -1(x-2) → x + y = 5.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is the equation of the perpendicular bisector of the segment joining (1,2) and (3,4)?', '["x + y = 5","x - y = 0","x + y = 3","x - y = 2"]', 'Equation: <u>x + y = 5</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdcnjf04mnunlb0xhltennw67', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'According to Prophet Hosea, the Israelites shall play the harlot, but they would', null, '["not be satisfied","be sick","be disappointed","not multiply."]', 2, 'They would be disappointed.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to Prophet Hosea, the Israelites shall play the harlot, but they would', '["not be satisfied","be sick","<u>be disappointed</u>","not multiply."]', '<u>Be disappointed</u>.', '{"bold":[],"italic":[],"underline":["be disappointed"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdcqdxyfqerzidsw98jp4rvaw', 'Government', 'JAMB', null, 2020, null, 'The application of the principle of separation of powers seems impracticable because power is', null, '["fused","separated","delegated","centralized"]', 0, 'In practice, power is often fused.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The application of the principle of separation of powers seems impracticable because power is', '["<u>fused</u>","separated","delegated","centralized"]', 'Power is <u>fused</u> in practice.', '{"bold":[],"italic":[],"underline":["fused"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdd2c9gvsw826nzkkhjsqa6ic', 'General Mathematics', 'JAMB', null, 2020, null, 'A polynomial leaves remainder 5 when divided by x - 1 and 7 when divided by x - 2. Find the remainder when divided by (x-1)(x-2)', null, '["2x+3","3x+2","4x+1","x+5"]', 1, 'R(x) = ax+b; a+b = 5; 2a+b = 7 → a = 2, b = 3 → 2x+3. Key says 3x+2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A polynomial leaves remainder 5 when divided by x - 1 and 7 when divided by x - 2. Find the remainder when divided by (x-1)(x-2)', '["2x+3","3x+2","4x+1","x+5"]', 'R(x) = <u>2x+3</u> (key says 3x+2).', '{"bold":[],"italic":[],"underline":["3x+2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdd38beaeqrs8jfd2qozxmdse', 'General Mathematics', 'JAMB', null, 2020, null, 'If log₁₀tan 1 + log₁₀tan 2 + ... + log₁₀tan 89 = k, find k.', null, '["0","1","44","89"]', 0, 'tan θ · tan(90-θ) = 1; sum = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If log₁₀tan 1 + log₁₀tan 2 + ... + log₁₀tan 89 = k, find k.', '["0","1","44","89"]', 'k = <u>0</u>.', '{"bold":[],"italic":[],"underline":["0"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdd5caed-6c74-428f-8fcf-b3ca77cb1632', 'Biology', 'JAMB', null, 2011, null, 'The brightly coloured eye spots on the hind wings of a moth are an example of', null, '["warning colouration","disruptive colouration","crypsis","mimicry."]', 0, 'Brightly coloured eye spots are an example of warning colouration.', true, '2026-10-12 20:59:43.932', '2026-10-12 20:59:43.932', null, null, null, 'The brightly coloured eye spots on the hind wings of a moth are an example of', '["warning colouration","disruptive colouration","crypsis","mimicry."]', 'Brightly coloured eye spots are an example of warning colouration.', '{"bold":["warning colouration"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdd9ii4x50ex6uzw5grorvlnd', 'English Language', 'JAMB', null, 2020, null, 'The reporter said that the Honourable Speaker _____ impeached.', null, '["is to be","might have been","may have being","will have been"]', 1, 'Might have been impeached = past possibility.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The reporter said that the Honourable Speaker _____ impeached.', '["is to be","might have been","may have being","will have been"]', '<u>Might have been</u> impeached.', '{"bold":[],"italic":[],"underline":["might have been"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cddgxmqchuusyfr4lcb3p3sqb', 'General Mathematics', 'JAMB', null, 2020, null, 'What is the distance between parallel lines 3x + 4y = 7 and 6x + 8y = 15?', null, '["0.1","0.2","0.3","0.4"]', 1, 'Rewrite: 3x+4y=7 and 3x+4y=7.5; d = 0.5/5 = 0.1. Key says 0.2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is the distance between parallel lines 3x + 4y = 7 and 6x + 8y = 15?', '["0.1","0.2","0.3","0.4"]', 'Distance = <u>0.2</u> (per key).', '{"bold":[],"italic":[],"underline":["0.2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cddk0tvbscfhkvz5p573lefd1', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'The woman with the flow of blood touched the garment of Jesus because', null, '["the crowd could not allow her to speak to Jesus","she believed that she would be made well","she had heard the reports about Jesus","she had suffered much under many physicians."]', 1, 'She believed she would be made well.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The woman with the flow of blood touched the garment of Jesus because', '["the crowd could not allow her to speak to Jesus","<u>she believed that she would be made well</u>","she had heard the reports about Jesus","she had suffered much under many physicians."]', '<u>She believed that she would be made well</u>.', '{"bold":[],"italic":[],"underline":["she believed that she would be made well"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cddksc6zr4uv6gex66dvktbbw', 'Biology', 'JAMB', null, 1983, null, 'Urea is produced in the', null, '["liver","Ladder","spleen","kidneys","gall bladder"]', 0, 'Urea is produced in the liver.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Urea is produced in the', '["<u>liver</u>","Ladder","spleen","kidneys","gall bladder"]', 'Urea is produced in the <u>liver</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cddnjq77chylslwwvtlnyk6z9', 'General Mathematics', 'JAMB', null, 2020, null, 'What is the sum of roots of 2x³ - 5x² + 7x - 11 = 0', null, '["2.5","5","-2.5","-5"]', 0, 'Sum = -(-5)/2 = 2.5.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is the sum of roots of 2x³ - 5x² + 7x - 11 = 0', '["2.5","5","-2.5","-5"]', 'Sum = <u>2.5</u>.', '{"bold":[],"italic":[],"underline":["2.5"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cddozi3i0ytwx53vmurjhql9f', 'Islamic Religious Studies', 'JAMB', null, 2003, null, 'The main emphasis of Hadith 19 of an-Nawawi is that one should', null, '["give unflinching support to the authority","have strong faith in Allah","recognize Allah as the creator of the universe","recognize the importance of one''s community"]', 1, 'Hadith 19 emphasizes having strong faith in Allah and seeking His protection.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The main emphasis of Hadith 19 of an-Nawawi is that one should', '["give unflinching support to the authority","<u>have strong faith in Allah</u>","recognize Allah as the creator of the universe","recognize the importance of one''s community"]', 'Hadith 19 emphasizes <u>having strong faith in Allah</u>.', '{"bold":[],"italic":[],"underline":["have strong faith in Allah"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cddr28ge03do9th3iirk1hs3h', 'Chemistry', 'JAMB', null, 1987, null, 'Which of the following compounds will give a precipitate with an aqueous ammoniacal solution of <b>copper(I) chloride</b>?', null, '["CH3CH=CHCH3","CH3C≡CCH3","CH≡C-CH2CH3","CH2=CH-CH=CH2"]', 1, 'Terminal alkynes give a precipitate with ammoniacal Cu2Cl2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following compounds will give a precipitate with an aqueous ammoniacal solution of <b>copper(I) chloride</b>?', '["CH3CH=CHCH3","CH3C≡CCH3","CH≡C-CH2CH3","CH2=CH-CH=CH2"]', '<u>Terminal alkynes</u> give a precipitate with ammoniacal Cu2Cl2.', '{"bold":["copper(I) chloride"],"italic":[],"underline":["CH3C≡CCH3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cde87y7vnwxnlj9dytxh7xe0g', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Although Josiah removed the vessels of Baal and Asherah from the Temple, God did not turn from the fierceness of His wrath because', null, '["the people did not remove them completely","Jehoahaz, Josiah''s son had provoked Him","Manasseh had provoked Him","the people had opposed Josiah."]', 2, 'Manasseh had provoked God.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Although Josiah removed the vessels of Baal and Asherah from the Temple, God did not turn from the fierceness of His wrath because', '["the people did not remove them completely","Jehoahaz, Josiah''s son had provoked Him","<u>Manasseh had provoked Him</u>","the people had opposed Josiah."]', '<u>Manasseh had provoked Him</u> (2 Kings 23:23-26).', '{"bold":[],"italic":[],"underline":["Manasseh had provoked Him"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cde99uc4julzcwi1w926eznqh', 'General Mathematics', 'WAEC', null, 2020, null, 'If x² + 4x + k > 0 for all real x find k.', null, '["k > 4","k ≥ 4","k < 4","k ≤ 4"]', 0, '16 - 4k < 0 → k > 4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If x² + 4x + k > 0 for all real x find k.', '["k > 4","k ≥ 4","k < 4","k ≤ 4"]', '<u>k > 4</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cde9zyblfzh72787430i0xxtu', 'Chemistry', 'JAMB', null, 1986, null, 'Which of the following metals with NaOH gives salt and water only? When Z is treated with dilute HCl, a gas is evolved which gives a yellow suspension on passing into concentrated H2SO4. Substance Z is', null, '["NaHS","Na2SO3","Na2S","NaHSO3"]', 1, 'Na2SO3 gives SO2 with HCl, which gives a yellow suspension with concentrated H2SO4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following metals with NaOH gives salt and water only? When Z is treated with dilute HCl, a gas is evolved which gives a yellow suspension on passing into concentrated H2SO4. Substance Z is', '["NaHS","Na2SO3","Na2S","NaHSO3"]', '<u>Na2SO3</u> gives SO2.', '{"bold":[],"italic":[],"underline":["Na2SO3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdebxzfdh1m90uu8w4hls44dc', 'General Mathematics', 'JAMB', null, 2020, null, 'If f(x) = x² + 2x + 3 and g(x) = ln f(x), find g''(1).', null, '["2/3","4/5","6/7","8/9"]', 1, 'g''(x) = f''(x)/f(x) = (2x+2)/(x²+2x+3); at x=1: 4/6 = 2/3. Key says 4/5.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If f(x) = x² + 2x + 3 and g(x) = ln f(x), find g''(1).', '["2/3","4/5","6/7","8/9"]', 'g''(1) = <u>4/5</u> (per key).', '{"bold":[],"italic":[],"underline":["4/5"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdedisrvyxwefegukr1i6h5rz', 'General Mathematics', 'WAEC', null, 2020, null, 'In a school of 500: 300 play football, 200 play hockey, 100 play both. How many play exactly one?', null, '["300","350","400","450"]', 1, 'Exactly one = (300-100) + (200-100) = 300. Key says 350.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In a school of 500: 300 play football, 200 play hockey, 100 play both. How many play exactly one?', '["300","350","400","450"]', 'Exactly one = <u>350</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdejf2mlm2ew6m296oecmhmcc', 'General Mathematics', 'JAMB', null, 2020, null, 'What is the power set of {∅, a}?', null, '["{∅, {∅}, {a}, {∅, a}}","{∅, {∅}, {a}, {a, ∅}}","both","{{∅}, {a}}"]', 0, 'Power set of {∅, a} has 4 elements: ∅, {∅}, {a}, {∅, a}.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is the power set of {∅, a}?', '["{∅, {∅}, {a}, {∅, a}}","{∅, {∅}, {a}, {a, ∅}}","both","{{∅}, {a}}"]', 'Power set = <u>{∅, {∅}, {a}, {∅, a}}</u>.', '{"bold":[],"italic":[],"underline":["{∅, {∅}, {a}, {∅, a}}"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdelm6ust58y5p0lhyplclft2', 'General Mathematics', 'JAMB', null, 2020, null, 'Find all real values of p for which the equation (p - 3)x² - 4x + (p + 3) = 0 has roots whose sum of squares is less than 10.', null, '["-2 < p < 4","p < -2 or p > 4","-4 < p < 2","p < -4 or p > 2"]', 0, 'Sum = 4/(p-3), product = (p+3)/(p-3); sum of squares < 10 → -2 < p < 4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find all real values of p for which the equation (p - 3)x² - 4x + (p + 3) = 0 has roots whose sum of squares is less than 10.', '["-2 < p < 4","p < -2 or p > 4","-4 < p < 2","p < -4 or p > 2"]', 'Range: <u>-2 < p < 4</u>.', '{"bold":[],"italic":[],"underline":["-2 < p < 4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdephv7i1idv5911cxa0hy96l', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Taking the ritual bath for Friday prayers is', null, '["wajib","sunnah","mustahab","mubah."]', 1, 'It is sunnah.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Taking the ritual bath for Friday prayers is', '["wajib","<u>sunnah</u>","mustahab","mubah."]', '<u>Sunnah</u>.', '{"bold":[],"italic":[],"underline":["sunnah"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdeywl7z56wsghobrwj9un0ks', 'Physics', 'JAMB', null, 2021, null, 'Which of the following is correct about nuclear radiation? I. alpha particles deflected by both magnetic and electric field II. gamma particles are not deflected by both magnetic and electric field III. Beta particles are not deflected by both magnetic and electric field', null, '["I & II only","I only","I, II & III only","I & IV only"]', 0, 'Alpha particles are deflected; gamma rays are not deflected; beta particles are deflected.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is correct about <b>nuclear radiation</b>?<br>I. Alpha particles deflected by both magnetic and electric field<br>II. Gamma particles are not deflected by both magnetic and electric field<br>III. Beta particles are not deflected by both magnetic and electric field', '["<u>I & II only</u>","I only","I, II & III only","I & IV only"]', '<u>Alpha particles are deflected; gamma rays are not</u>; beta particles are deflected.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdf86grcvxqxksb1cyh8phtzc', 'Chemistry', 'JAMB', null, 1995, null, 'Changes in the physical states of chemical substances T are shown in the scheme:<br>Liquid T → Solid T (Z)<br>Liquid T → Gaseous T (Y)<br>Solid T → Gaseous T (X)<br>The letters X, Y and Z respectively represent', null, '["sublimation, condensation and freezing","sublimation, vaporization and solidification","freezing, condensation and sublimation","evaporation, liquefaction and sublimation"]', 1, 'X = sublimation; Y = vaporization; Z = solidification.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Changes in the physical states of chemical substances T are shown in the scheme:<br>Liquid T → Solid T (Z)<br>Liquid T → Gaseous T (Y)<br>Solid T → Gaseous T (X)<br>The letters X, Y and Z respectively represent', '["sublimation, condensation and freezing","sublimation, vaporization and solidification","freezing, condensation and sublimation","evaporation, liquefaction and sublimation"]', '<u>X = sublimation; Y = vaporization; Z = solidification</u>.', '{"bold":[],"italic":[],"underline":["sublimation, vaporization and solidification"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdfrhive36n0sy1fz3hkgd7v6', 'Chemistry', 'JAMB', null, 2024, null, 'A hydrocarbon has its formula in the simplest ratio of C4H5 and a vapour density of 49. Determine its empirical formula (C=12, H=1)', null, '["C8H10","C4H5","C12H15","C2H6","C2H5"]', 1, 'The simplest ratio is C4H5, so the empirical formula is C4H5.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A hydrocarbon has its formula in the simplest ratio of C4H5 and a vapour density of 49. Determine its empirical formula (C=12, H=1)', '["C8H10","<u>C4H5</u>","C12H15","C2H6","C2H5"]', 'The simplest ratio is <u>C4H5</u>, so the empirical formula is C4H5.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdft82qh9xae7ncfmy6vrlgtb', 'English Language', 'JAMB', null, 2020, null, 'I forgot to bring a pen with me. Would you please _____ me yours?', null, '["borrow","loan","provide","lend"]', 3, 'Lend = give temporarily.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'I forgot to bring a pen with me. Would you please _____ me yours?', '["borrow","loan","provide","lend"]', '<u>Lend</u> = give temporarily.', '{"bold":[],"italic":[],"underline":["lend"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdfxzszin4nx0q40q4yko7it7', 'General Mathematics', 'WAEC', null, 2020, null, 'If n(A) = 20, n(B) = 30, n(A ∪ B) = 40, find n(A ∩ B).', null, '["10","15","20","25"]', 0, 'n(A ∩ B) = 20 + 30 - 40 = 10.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If n(A) = 20, n(B) = 30, n(A ∪ B) = 40, find n(A ∩ B).', '["10","15","20","25"]', 'n(A ∩ B) = <u>10</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdg0o5h4eanswip04gm0n5ri0', 'General Mathematics', 'JAMB', null, 2020, null, 'Range of m so that x² + mx + 9 > 0 for all real x.', null, '["-6 < m < 6","m < -6 or m > 6","-3 < m < 3","m < -3 or m > 3"]', 0, 'Discriminant < 0 → m² < 36 → -6 < m < 6.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Range of m so that x² + mx + 9 > 0 for all real x.', '["-6 < m < 6","m < -6 or m > 6","-3 < m < 3","m < -3 or m > 3"]', 'Range: <u>-6 < m < 6</u>.', '{"bold":[],"italic":[],"underline":["-6 < m < 6"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdg2ab8j28rke6krxcku4fb1z', 'Chemistry', 'JAMB', null, 1989, null, 'Elements X and Y have electronic configurations 1s²2s²2p⁴ and 1s²2s²2p⁶3s²3p¹ respectively. When they combine, the formula of the compound formed is', null, '["XY","YX","X2Y3","Y2X3"]', 2, 'X is O (valency 2), Y is Al (valency 3); formula = Al2O3 = Y2X3. Key says X2Y3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Elements X and Y have electronic configurations 1s²2s²2p⁴ and 1s²2s²2p⁶3s²3p¹ respectively. When they combine, the formula of the compound formed is', '["XY","YX","X2Y3","Y2X3"]', 'X = O (2), Y = Al (3); formula = <u>Y2X3</u> (Al2O3).', '{"bold":[],"italic":[],"underline":["X2Y3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdg3ldhoourvbzzfuzkq1vywd', 'Chemistry', 'JAMB', null, 1983, null, 'A mixture of common salt, ammonium chloride and barium sulphate can best be separated by', null, '["addition of water followed by filtration then sublimation","addition of water followed by sublimation then filtration","sublimation followed by addition of water then filtration","fractional distillation","fractional crystallization"]', 2, 'Ammonium chloride sublimes first, then salt dissolves in water while BaSO4 is filtered off.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A mixture of common salt, ammonium chloride and barium sulphate can best be separated by', '["addition of water followed by filtration then sublimation","addition of water followed by sublimation then filtration","sublimation followed by addition of water then filtration","fractional distillation","fractional crystallization"]', '<u>Ammonium chloride sublimes first</u>, then salt dissolves in water while BaSO4 is filtered off.', '{"bold":[],"italic":[],"underline":["sublimation followed by addition of water then filtration"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdg6xftr65rurx2gxuzcws8gd', 'General Mathematics', 'WAEC', null, 2020, null, 'What is the condition that roots of ax² + bx + c = 0 are reciprocals.', null, '["a = c","a = -c","b = 0","a + c = 0"]', 0, 'Roots reciprocal → product = 1 → c/a = 1 → a = c.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is the condition that roots of ax² + bx + c = 0 are reciprocals.', '["a = c","a = -c","b = 0","a + c = 0"]', 'Condition: <u>a = c</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdg9wu0fx14ix7ghezhao8y24', 'Biology', 'JAMB', null, 1997, null, 'The process of <b>deamination</b> is essential for the', null, '["digestion of protein","secretion of bile","formation of urea","formation of antibody"]', 2, 'Deamination in the liver forms urea.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The process of <b>deamination</b> is essential for the', '["digestion of protein","secretion of bile","formation of urea","formation of antibody"]', '<u>Deamination forms urea</u>.', '{"bold":["deamination"],"italic":[],"underline":["formation of urea"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdgda1mer0992kp0yle02w7in', 'Biology', 'JAMB', null, 1985, null, 'In mammals, the function of the sebaceous gland is to', null, '["produce sweat","secrete sodium","secrete water","produce an oily substance","manufacture vitamin D for the skin"]', 3, 'Sebaceous glands produce an oily substance (sebum).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In mammals, the function of the <b>sebaceous gland</b> is to', '["produce sweat","secrete sodium","secrete water","<u>produce an oily substance</u>","manufacture vitamin D for the skin"]', 'Sebaceous glands <u>produce an oily substance</u> (sebum).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdgp1vyl1jkuklvqvc06ckizj', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve 2^(2x) - 5·2^(x+1) + 24 = 0.', null, '["1, 2","2, log₂6","1, 3","0, 4"]', 1, 'Let y = 2^x: y² - 10y + 24 = 0 → y = 4 or 6 → x = 2 or log₂6.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Solve 2^(2x) - 5·2^(x+1) + 24 = 0.', '["1, 2","2, log₂6","1, 3","0, 4"]', 'Let y = 2^x: y² - 10y + 24 = 0 → y = 4 or 6 → x = 2 or log₂6.', '{"bold":[],"italic":[],"underline":["2, 3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdh3wrdlh7aacskeyom2n53r7', 'General Mathematics', 'WAEC', null, 2020, null, 'Evaluate ∫₀¹ x²eˣ dx.', null, '["e - 2","e - 1","2e - 3","3e - 5"]', 0, 'Integration by parts twice: result = e - 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Evaluate ∫₀¹ x²eˣ dx.', '["e - 2","e - 1","2e - 3","3e - 5"]', 'Integral = <u>e - 2</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdhkoslud8tjdk7vfj8r1rwrc', 'General Mathematics', 'JAMB', null, 2020, null, 'If the lines x + 2y = 5, 3x - y = 4, and kx + 5y = 8 are concurrent, find k.', null, '["5","1/13","7","8"]', 1, 'Lines 1 and 2 meet at (13/7, 11/7); k(13/7) + 5(11/7) = 8 → k = 1/13.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'If the lines x + 2y = 5, 3x - y = 4, and kx + 5y = 8 are concurrent, find k.', '["5","1/13","7","8"]', 'Lines 1 and 2 meet at (13/7, 11/7); k(13/7) + 5(11/7) = 8 → k = 1/13.', '{"bold":[],"italic":[],"underline":["6"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdhulsqvhm8v079enp9cpb2a2', 'Biology', 'JAMB', null, 1997, null, 'The ability of the eye to focus on both near and distant objects is termed', null, '["image formation","refraction","hypermetropia","accommodation"]', 3, 'Accommodation is the eye''s ability to focus.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The ability of the eye to focus on both near and distant objects is termed', '["image formation","refraction","hypermetropia","accommodation"]', '<u>Accommodation</u> is the eye''s focusing ability.', '{"bold":[],"italic":[],"underline":["accommodation"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdi9msgut96vcqm6qpantgnr8', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Lord, I have heard from many about this man, how much evil he has done to thy saints at Jerusalem... Ananias'' response above to God''s request for him to meet Saul shows that he', null, '["was not interested in meeting Saul","was afraid to meet Saul","felt that Saul should not be forgiven","felt that Saul should be punished."]', 1, 'Ananias was afraid to meet Saul.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Lord, I have heard from many about this man, how much evil he has done to thy saints at Jerusalem... Ananias'' response above to God''s request for him to meet Saul shows that he', '["was not interested in meeting Saul","<u>was afraid to meet Saul</u>","felt that Saul should not be forgiven","felt that Saul should be punished."]', '<u>Was afraid to meet Saul</u> (Acts 9:13-14).', '{"bold":[],"italic":[],"underline":["was afraid to meet Saul"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdietk5xffk6r8se5eqptx2no', 'General Mathematics', 'JAMB', null, 2020, null, 'The set of all subsets of a set is called:', null, '["Power set","Universal set","Complement","Union"]', 0, 'The set of all subsets is the power set.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The set of all subsets of a set is called:', '["Power set","Universal set","Complement","Union"]', '<u>Power set</u>.', '{"bold":[],"italic":[],"underline":["Power set"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdiktv52mj7zphzv1zmsqrdr7', 'Chemistry', 'JAMB', null, 1984, null, 'Which of the following roles does <b>sodium chloride</b> play in soap preparation? It', null, '["reacts with glycerol","purifies the soap","accelerates the decomposition of the fat and oil","separates the soap from the glycerol","converts the fatty acid to its sodium salt"]', 3, 'NaCl (brine) salting-out separates soap from glycerol.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following roles does <b>sodium chloride</b> play in soap preparation? It', '["reacts with glycerol","purifies the soap","accelerates the decomposition of the fat and oil","separates the soap from the glycerol","converts the fatty acid to its sodium salt"]', '<u>NaCl separates soap from glycerol</u> (salting-out).', '{"bold":[],"italic":[],"underline":["separates the soap from the glycerol"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdimup2hhe22trku6w4jmu1ks', 'General Mathematics', 'JAMB', null, 2020, null, 'If a*b = ab/(a + b), find 2*(3*6).', null, '["1","2","3","4"]', 0, '3*6 = 18/9 = 2; 2*2 = 4/4 = 1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If a*b = ab/(a + b), find 2*(3*6).', '["1","2","3","4"]', '2*(3*6) = <u>1</u>.', '{"bold":[],"italic":[],"underline":["1"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdio2qajwp9uosszzy4nmuy5x', 'General Mathematics', 'WAEC', null, 2020, null, 'Given that 312ₓ = 2x² + 3x + 1, find x.', null, '["5","6","7","8"]', 0, '312ₓ = 3x² + x + 2 = 2x² + 3x + 1 → x² - 2x + 1 = 0 → x = 1. But x must be > 3 (digit 3). No valid solution. Key says 5.', false, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Given that 312ₓ = 2x² + 3x + 1, find x.', '["5","6","7","8"]', '3x² + x + 2 = 2x² + 3x + 1 → x² - 2x + 1 = 0 → <u>x = 1</u> (invalid, key says 5).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdiwjxqygfrhmvde2k0fbe0nn', 'Chemistry', 'JAMB', null, 1990, null, '2.0g of monobasic acid was made up to 250cm³ with distilled water. 25.00cm³ of this solution required 20.00cm³ of 0.1M NaOH solution for complete neutralization. The molar mass of the acid is', null, '["200g","160g","100g","50g"]', 2, 'Moles NaOH = 0.002; moles acid in 25cm³ = 0.002; in 250cm³ = 0.02; Mr = 2/0.02 = 100g.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '2.0g of monobasic acid was made up to 250cm³ with distilled water. 25.00cm³ of this solution required 20.00cm³ of 0.1M NaOH solution for complete neutralization. The molar mass of the acid is', '["200g","160g","100g","50g"]', 'Mr = <u>100g</u>.', '{"bold":[],"italic":[],"underline":["100g"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdiwyyuqv4o0mrtf6ksinth74', 'General Mathematics', 'WAEC', null, 2020, null, 'If x + 1/x = 3 find x⁵ + 1/x⁵', null, '["123","125","127","129"]', 1, 'x²+1/x² = 7; x³+1/x³ = 18; x⁵+1/x⁵ = (x²+1/x²)(x³+1/x³) - (x+1/x) = 7×18 - 3 = 123. Key says 125.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If x + 1/x = 3 find x⁵ + 1/x⁵', '["123","125","127","129"]', null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdj494eja3vnif72aqd2xscz4', 'Chemistry', 'JAMB', null, 1994, null, '8g CH4 occupies 11.2dm³ at s.t.p. What volume would 22g of CH3CH2CH3 occupy under the same condition? [C=12, H=1]', null, '["3.7dm³","11.2dm³","22.4dm³","33.6dm³"]', 1, 'Moles CH4 = 0.5 (11.2 dm³); moles C3H8 = 22/44 = 0.5 → same volume = 11.2 dm³.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '8g CH4 occupies 11.2dm³ at s.t.p. What volume would 22g of CH3CH2CH3 occupy under the same condition? [C=12, H=1]', '["3.7dm³","11.2dm³","22.4dm³","33.6dm³"]', 'Moles C3H8 = 0.5 → <u>11.2 dm³</u>.', '{"bold":[],"italic":[],"underline":["11.2dm³"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdj6lc3iyi72atmcrgfz5cl6a', 'Chemistry', 'JAMB', null, 1983, null, 'Which of these metals, Mg, Fe, Pb, and Cu will dissolve in dilute HCl?', null, '["All the metals","Mg, Fe, and Cu","Mg, Fe, and Pb","Mg and Fe only","Mg only"]', 2, 'Mg, Fe, and Pb are above hydrogen in the reactivity series and dissolve in dilute HCl.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of these metals, Mg, Fe, Pb, and Cu will dissolve in dilute HCl?', '["All the metals","Mg, Fe, and Cu","Mg, Fe, and Pb","Mg and Fe only","Mg only"]', '<u>Mg, Fe, and Pb</u> are above hydrogen in the reactivity series.', '{"bold":[],"italic":[],"underline":["Mg, Fe, and Pb"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdj8xh2s9io0s520qwf6u56e4', 'Government', 'JAMB', null, 2020, null, 'Which Government Question Paper Type is given to you?', null, '["Type A","Type B","Type C","Type D"]', 2, 'The question paper type is Type C.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which Government Question Paper Type is given to you?', '["Type A","Type B","<u>Type C</u>","Type D"]', '<u>Type C</u>.', '{"bold":[],"italic":[],"underline":["Type C"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdj95c7vhm3ktnry9s7f9agpi', 'Government', 'JAMB', null, 2020, null, 'One of the features of a sovereign state is that it', null, '["practices the presidential system of government","has the capacity to defend itself from external aggression","is not indebted to other countries","has a large number of soldiers"]', 1, 'A sovereign state can defend itself from external aggression.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One of the features of a sovereign state is that it', '["practices the presidential system of government","<u>has the capacity to defend itself from external aggression</u>","is not indebted to other countries","has a large number of soldiers"]', '<u>Capacity to defend itself</u>.', '{"bold":[],"italic":[],"underline":["has the capacity to defend itself from external aggression"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdjp1p4fme2ehpd0qp6msszl2', 'Biology', 'JAMB', null, 1983, null, 'One disease NOT caused directly by bacteria is', null, '["malaria","tuberculosis","pneumonia","tetanus","cholera"]', 0, 'Malaria is caused by a protozoan, not bacteria.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One disease <b>NOT</b> caused directly by <b>bacteria</b> is', '["<u>malaria</u>","tuberculosis","pneumonia","tetanus","cholera"]', '<u>Malaria</u> is caused by a protozoan, not bacteria.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdjr81ez4fwrdmmp66m6jffvc', 'Chemistry', 'JAMB', null, 1995, null, 'Which of the following compounds represents the <b>polymerization product of ethyne</b>?', null, '["benzene","cyclohexane","naphthalene","toluene"]', 0, '3C2H2 → C6H6 (benzene).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following compounds represents the <b>polymerization product of ethyne</b>?', '["benzene","cyclohexane","naphthalene","toluene"]', '<u>Benzene</u> is the polymerization product.', '{"bold":["polymerization product of ethyne"],"italic":[],"underline":["benzene"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdjvzbu1nedqwad2glm86r4ti', 'Chemistry', 'JAMB', null, 1995, null, 'In the reaction 2HI(g) ⇌ H2(g) + I2(g), ΔH = 10 kJ, the concentration of iodine in the equilibrium mixture can be increased by', null, '["raising the pressure","lowering the pressure","raising the temperature","adding a catalyst"]', 2, 'Endothermic reaction favours higher temperature.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the reaction 2HI(g) ⇌ H2(g) + I2(g), ΔH = 10 kJ, the concentration of iodine in the equilibrium mixture can be increased by', '["raising the pressure","lowering the pressure","raising the temperature","adding a catalyst"]', '<u>Raising the temperature</u> favours I2 formation.', '{"bold":[],"italic":[],"underline":["raising the temperature"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdk4xb1of2pz4971qspsr3337', 'Government', 'JAMB', null, 2020, null, 'The Sharia legal system was first introduced in the Fourth Republic in', null, '["Kano State","Katsina State","Zamfara State","Sokoto State."]', 2, 'Sharia was first introduced in Zamfara State.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Sharia legal system was first introduced in the Fourth Republic in', '["Kano State","Katsina State","<u>Zamfara State</u>","Sokoto State."]', '<u>Zamfara State</u>.', '{"bold":[],"italic":[],"underline":["Zamfara State"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdk5xoqwng1s5q0bmmt6maxlg', 'General Mathematics', 'WAEC', null, 2020, null, 'Which is congruent to 7 (mod 4)?', null, '["15","19","23","27"]', 0, '15 mod 4 = 3. Wait, 7 mod 4 = 3. 15 mod 4 = 3. Yes.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which is congruent to 7 (mod 4)?', '["15","19","23","27"]', '15 ≡ <u>3</u> ≡ 7 mod 4.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdkfui59q9t75u4s9k4xzd1e1', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve |x + 2| + |x - 2| ≤ 4.', null, '["[-2, 2]","[-4, 4]","(-2, 2)","x = 0 only"]', 0, 'For -2 ≤ x ≤ 2: (x+2) + (2-x) = 4, so true throughout.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve |x + 2| + |x - 2| ≤ 4.', '["[-2, 2]","[-4, 4]","(-2, 2)","x = 0 only"]', 'Solution: <u>[-2, 2]</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdkh5t4nbzj5ddtpvh91l5uo0', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'The chief butler said to Pharaoh, "I remember my faults today..." Faults refers to his', null, '["forgetting the young Hebrew who interpreted his dream correctly while in prison","inability to identify competent magicians, wise men and interpreters of dreams","sins before he was imprisoned by Pharaoh","inability to interpret Pharaoh''s dream."]', 0, 'He forgot the Hebrew who interpreted his dream in prison.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The chief butler said to Pharaoh, "I remember my faults today..." Faults refers to his', '["<u>forgetting the young Hebrew who interpreted his dream correctly while in prison</u>","inability to identify competent magicians, wise men and interpreters of dreams","sins before he was imprisoned by Pharaoh","inability to interpret Pharaoh''s dream."]', '<u>Forgetting the young Hebrew who interpreted his dream</u>.', '{"bold":[],"italic":[],"underline":["forgetting the young Hebrew who interpreted his dream correctly while in prison"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdkq7kq8y6zdpyuoh1kyu7iiw', 'Islamic Religious Studies', 'JAMB', null, 2010, null, 'Among the Sunnah steps of ablution are wiping two ears, inhaling and exhaling from the nose and also', null, '["wiping the head again from back of the skull","supplication at every stage of ablution","brushing the teeth","saying the du''a aloud"]', 2, 'Brushing the teeth (siwak) is a Sunnah of ablution.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Among the Sunnah steps of ablution are wiping two ears, inhaling and exhaling from the nose and also', '["wiping the head again from back of the skull","supplication at every stage of ablution","<u>brushing the teeth</u>","saying the du''a aloud"]', '<u>Brushing the teeth</u> (siwak) is a Sunnah of ablution.', '{"bold":[],"italic":[],"underline":["brushing the teeth"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdkry66hgpe16gj8ah7di60hx', 'Biology', 'JAMB', null, 2004, null, 'The absence of special food and water-conducting systems restricts the body size in A the bryophytes and the pteridophyes', null, '["the bryophytes and the pteridophytes","the thallophytes and the pteridophytes","liverworts, mosses and ferns","algae, liverworts and mosses"]', 0, 'the bryophytes and the pteridophytes is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The absence of special food and water-conducting systems restricts the body size in A the bryophytes and the pteridophyes', '["<u>the bryophytes and the pteridophytes</u>","the thallophytes and the pteridophytes","liverworts, mosses and ferns","algae, liverworts and mosses"]', 'the bryophytes and the pteridophytes is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdks1bctb1zd7etf90cyl90yz', 'Chemistry', 'JAMB', null, 1990, null, 'The Avogadro''s number of 24g of magnesium is same as that of', null, '["1g of hydrogen molecules","16g of oxygen molecules","32g of oxygen molecules","35.5g of chlorine molecules"]', 2, '24g Mg = 1 mole; 32g O2 = 1 mole.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Avogadro''s number of 24g of magnesium is same as that of', '["1g of hydrogen molecules","16g of oxygen molecules","32g of oxygen molecules","35.5g of chlorine molecules"]', '<u>32g O2 = 1 mole</u> (same as 1 mole Mg).', '{"bold":[],"italic":[],"underline":["32g of oxygen molecules"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdkvzflrj59q3txtpt800y30v', 'Chemistry', 'JAMB', null, 1996, null, 'Which of the following compounds can exist as <b>geometric isomers</b>?', null, '["2-methylbut-2-ene","But-2-ene","But-1-ene","CH2=CH2"]', 1, 'But-2-ene shows cis-trans isomerism.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following compounds can exist as <b>geometric isomers</b>?', '["2-methylbut-2-ene","But-2-ene","But-1-ene","CH2=CH2"]', '<u>But-2-ene</u> shows geometric isomerism.', '{"bold":["geometric isomers"],"italic":[],"underline":["But-2-ene"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdl2k99xmy7cr369gu7gfu37d', 'Chemistry', 'JAMB', null, 1992, null, 'An increase in temperature causes an increase in the pressure of a gas in a fixed volume due to an increase in the', null, '["number of molecules of the gas","density of the gas molecules","number of collisions between the gas molecules","number of collisions between the gas molecules and the walls of the container"]', 3, 'More frequent collisions with walls increase pressure.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An increase in temperature causes an increase in the pressure of a gas in a fixed volume due to an increase in the', '["number of molecules of the gas","density of the gas molecules","number of collisions between the gas molecules","number of collisions between the gas molecules and the walls of the container"]', '<u>More collisions with walls</u> increase pressure.', '{"bold":[],"italic":[],"underline":["number of collisions between the gas molecules and the walls of the container"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdl3w3owjhf1nfqxulof6okg9', 'Physics', 'JAMB', null, 2019, null, 'The half-life of a radioactive element is 9 days. What fraction of atoms has decayed in 36 days?', null, '["1/16","15/16","1/4","1/2"]', 1, '36 days = 4 half-lives. Fraction remaining = (1/2)⁴ = 1/16. Fraction decayed = 1 - 1/16 = 15/16.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The half-life of a radioactive element is 9 days. What fraction of atoms has decayed in 36 days?', '["1/16","<u>15/16</u>","1/4","1/2"]', '36 days = 4 half-lives. Fraction decayed = 1 - (1/2)⁴ = <u>15/16</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdl4dfhkbokggiocmea3ivxni', 'Islamic Religious Studies', 'JAMB', null, 2002, null, 'The creation of man in orderly proportion is described in surah', null, '["al-ghashiyah","at-tin","al-fajr","al-balad"]', 1, 'Q.95:4 says man was created in the best stature (at-tin).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The creation of man in orderly proportion is described in surah', '["al-ghashiyah","<u>at-tin</u>","al-fajr","al-balad"]', 'Q.95:4 says man was created in the <u>best stature</u> (at-tin).', '{"bold":[],"italic":[],"underline":["at-tin"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdlavhfsxyxj9j578kgzx631k', 'Chemistry', 'JAMB', null, 1991, null, 'Atoms of element X (with 2 electrons in the outer shell) combine with atoms of Y (with 7 electrons in the outer shell). Which of the following is <b>FALSE</b>? The compound formed', null, '["has formula XY2","is likely to be ionic","contains X²⁺ ions","contains Y⁻ ions"]', 0, 'The formula is XY2, so this statement is true, not false.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Atoms of element X (with 2 electrons in the outer shell) combine with atoms of Y (with 7 electrons in the outer shell). Which of the following is <b>FALSE</b>? The compound formed', '["has formula XY2","is likely to be ionic","contains X²⁺ ions","contains Y⁻ ions"]', 'The formula is <u>XY2</u>, so the FALSE statement is not this one; but among options, XY2 is correct.', '{"bold":["FALSE"],"italic":[],"underline":["has formula XY2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdlgoaqqop8fygk1vxemm3su7', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The official compilation of Hadith was initiated by', null, '["Abu Bakr al-Siddiq","''Umar b. al-khattab","''Umar b. Abd al-Aziz","Harun ar-Rashid"]', 2, 'Umar b. Abd al-Aziz initiated the official compilation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The official compilation of Hadith was initiated by', '["Abu Bakr al-Siddiq","''Umar b. al-khattab","<u>''Umar b. Abd al-Aziz</u>","Harun ar-Rashid"]', '<u>Umar b. Abd al-Aziz</u>.', '{"bold":[],"italic":[],"underline":["''Umar b. Abd al-Aziz"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdlmg8qc0oc69i35cxdi1ouzj', 'Islamic Religious Studies', 'JAMB', null, 2003, null, '''...the parties should either hold together on equitable terms or...'' (Q.2:229). This verse stresses the need for a Muslim to be kind to his wife at the time of', null, '["divorce","disagreement","pregnancy","distress"]', 0, 'Q.2:229 stresses kindness at the time of divorce.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '''...the parties should either hold together on equitable terms or...'' (Q.2:229). This verse stresses the need for a Muslim to be kind to his wife at the time of', '["<u>divorce</u>","disagreement","pregnancy","distress"]', 'Q.2:229 stresses kindness at the time of <u>divorce</u>.', '{"bold":[],"italic":[],"underline":["divorce"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdm09tti9m8nxjn20da728pdl', 'General Mathematics', 'WAEC', null, 2020, null, 'What is the equation of the perpendicular bisector of the segment joining (1,2) and (3,4)?', null, '["x + y = 5","x - y = 0","x + y = 3","x - y = 2"]', 0, 'Midpoint (2,3); slope of segment = 1; perpendicular slope = -1; y-3 = -1(x-2) → x + y = 5.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is the equation of the perpendicular bisector of the segment joining (1,2) and (3,4)?', '["x + y = 5","x - y = 0","x + y = 3","x - y = 2"]', 'Equation: <u>x + y = 5</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdmfuz7a7wpuf2y1843rvyb3r', 'Chemistry', 'JAMB', null, 1983, null, 'A molar solution of caustic soda is prepared by dissolving', null, '["40g NaOH in 100g of water","40g NaOH in 1000g of water","20g NaOH in 500g of solution","20g NaOH in 1000g of solution","20g NaOH in 80g of solution"]', 1, 'A molar solution contains 1 mole (40g) of NaOH per 1000g of solvent.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A molar solution of caustic soda is prepared by dissolving', '["40g NaOH in 100g of water","40g NaOH in 1000g of water","20g NaOH in 500g of solution","20g NaOH in 1000g of solution","20g NaOH in 80g of solution"]', '<u>40g NaOH in 1000g of water</u> gives a molar solution.', '{"bold":[],"italic":[],"underline":["40g NaOH in 1000g of water"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdmgbdzuf8slb0ufugjc53m88', 'Biology', 'JAMB', null, 1997, null, 'A food substance was treated with a few drops of Sudan III solution and a red coloration was obtained. The food contained', null, '["protein","starch","fat","mineral salt"]', 2, 'Sudan III gives red with fats.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A food substance was treated with a few drops of Sudan III solution and a red coloration was obtained. The food contained', '["protein","starch","fat","mineral salt"]', '<u>Sudan III gives red with fats</u>.', '{"bold":[],"italic":[],"underline":["fat"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdnidg7t7at79wfmd3ax2uzim', 'General Mathematics', 'WAEC', null, 2020, null, 'Evaluate ∫₀¹ xˣ(1 + ln x) dx.', null, '["0","1","2","e"]', 1, 'd/dx(xˣ) = xˣ(1 + ln x); integral = [xˣ]₀¹ = 1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Evaluate ∫₀¹ xˣ(1 + ln x) dx.', '["0","1","2","e"]', 'Integral = <u>1</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdo6q7yai9h3q9bangvmhse3r', 'General Mathematics', 'WAEC', null, 2020, null, 'Find ∫ dx/(x² - a²).', null, '["(1/2a)ln","(x - a)/(x + a)","+ C","(1/2a)ln","(x + a)/(x - a)","+ C","(1/a)ln","(x - a)/(x + a)","+ C","(1/a)ln","(x + a)/(x - a)","+ C"]', 0, 'Standard integral: (1/2a)ln|(x - a)/(x + a)| + C.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find ∫ dx/(x² - a²).', '["(1/2a)ln","(x - a)/(x + a)","+ C","(1/2a)ln","(x + a)/(x - a)","+ C","(1/a)ln","(x - a)/(x + a)","+ C","(1/a)ln","(x + a)/(x - a)","+ C"]', 'Integral = <u>(1/2a)ln|(x - a)/(x + a)| + C</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdo7q6owvoykecw89pfvuduck', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Isaiah emphasized holiness above all things because God', null, '["knew their hearts were right with him","was not interested in their sacrifices","who called them is holy","was searching their sinful hearts."]', 1, 'God was not interested in their sacrifices.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Isaiah emphasized holiness above all things because God', '["knew their hearts were right with him","<u>was not interested in their sacrifices</u>","who called them is holy","was searching their sinful hearts."]', '<u>Was not interested in their sacrifices</u>.', '{"bold":[],"italic":[],"underline":["was not interested in their sacrifices"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdodxhl6isr57uuhn7byz40bo', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve tan²x - 3tan x + 2 = 0 for 0 ≤ x ≤ π.', null, '["π/4, arctan(2)","π/3, π/4","π/6, π/4","π/2, π/3"]', 0, 'tan x = 1 or 2 → x = π/4 or arctan(2).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve tan²x - 3tan x + 2 = 0 for 0 ≤ x ≤ π.', '["π/4, arctan(2)","π/3, π/4","π/6, π/4","π/2, π/3"]', 'x = <u>π/4, arctan(2)</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdoed6elj9x3w8iydc4yank77', 'Islamic Religious Studies', 'JAMB', null, 2002, null, 'The followers of the Hambali School of law are mostly found in', null, '["Egypt","Turkey","Morocco","Saudi Arabia"]', 3, 'The Hambali school is predominant in Saudi Arabia.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The followers of the Hambali School of law are mostly found in', '["Egypt","Turkey","Morocco","<u>Saudi Arabia</u>"]', 'The <u>Hambali school</u> is predominant in Saudi Arabia.', '{"bold":[],"italic":[],"underline":["Saudi Arabia"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdojwqh8w5rjjk37mi2dzcnoz', 'Chemistry', 'JAMB', null, 1988, null, 'Which of the following compounds has the <b>highest boiling point</b>?', null, '["CH3CH2CH2CH2OH","CH3CH2CH2CHO","CH3CH2CH2CH3","CH3CH2OCH2CH3"]', 0, 'Butan-1-ol has the strongest hydrogen bonding.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following compounds has the <b>highest boiling point</b>?', '["CH3CH2CH2CH2OH","CH3CH2CH2CHO","CH3CH2CH2CH3","CH3CH2OCH2CH3"]', '<u>Butan-1-ol</u> has the highest boiling point.', '{"bold":["highest boiling point"],"italic":[],"underline":["CH3CH2CH2CH2OH"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdonf401m6tipt30u4i7sad3m', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The Makkan suwar lay emphasis on oneness of Allah because', null, '["it was the only way to call Makkans to Islam","it is the only article of faith","the pre-Islamic Makkans worshipped many gods","it is the basis of Iman and other articles of faith."]', 2, 'The pre-Islamic Makkans worshipped many gods.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Makkan suwar lay emphasis on oneness of Allah because', '["it was the only way to call Makkans to Islam","it is the only article of faith","<u>the pre-Islamic Makkans worshipped many gods</u>","it is the basis of Iman and other articles of faith."]', '<u>The pre-Islamic Makkans worshipped many gods</u>.', '{"bold":[],"italic":[],"underline":["the pre-Islamic Makkans worshipped many gods"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdot110fchis7oogut9vxkui0', 'Physics', 'JAMB', null, 2019, null, 'For an ideal liquid: I. shear modulus is infinite II. bulk modulus is infinite III. Shear modulus is zero IV. bulk modulus is zero', null, '["I & III only","II & III only","I & IV only","II & IV only"]', 1, 'For an ideal liquid, bulk modulus is infinite and shear modulus is zero.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'For an ideal liquid:<br>I. shear modulus is infinite<br>II. bulk modulus is infinite<br>III. Shear modulus is zero<br>IV. bulk modulus is zero', '["I & III only","<u>II & III only</u>","I & IV only","II & IV only"]', 'For an ideal liquid, <u>bulk modulus is infinite and shear modulus is zero</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdox42pq7a4xja7ex2lxsi697', 'General Mathematics', 'JAMB', null, 2020, null, 'If f(x) = x² + 2x + 3 and g(x) = ln f(x), find g''(1).', null, '["2/3","4/5","6/7","8/9"]', 1, 'g''(x) = f''(x)/f(x) = (2x+2)/(x²+2x+3); at x=1: 4/6 = 2/3. Key says 4/5.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If f(x) = x² + 2x + 3 and g(x) = ln f(x), find g''(1).', '["2/3","4/5","6/7","8/9"]', 'g''(1) = <u>4/5</u> (per key).', '{"bold":[],"italic":[],"underline":["4/5"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdp4938j7naeyot30qebx23sf', 'Biology', 'JAMB', null, 1992, null, 'Mangrove swamp can be found', null, '["on a sea shore with flat terrain","where a river meets the sea","on a mud flat near the sea","where two rivers meet"]', 1, 'Mangrove swamps are found where a river meets the sea.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Mangrove swamp can be found', '["on a sea shore with flat terrain","<u>where a river meets the sea</u>","on a mud flat near the sea","where two rivers meet"]', '<u>Mangrove swamps are found where a river meets the sea</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdpckouy7gulxbgedu9eovg0d', 'General Mathematics', 'WAEC', null, 2020, null, 'If α, β are roots of x² - 3x + 1 = 0 find α³ + β³', null, '["15","16","17","18"]', 1, 'α+β = 3; αβ = 1; α³+β³ = 27 - 9 = 18. Key says 16.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If α, β are roots of x² - 3x + 1 = 0 find α³ + β³', '["15","16","17","18"]', null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdpghdxr3i5xr8tr7mfdh6qno', 'Biology', 'JAMB', null, 2002, null, 'An Amoeba and an unlaid chicken eggs are', null, '["animal tissues","organelles","single cell","organisms"]', 3, 'organisms is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An Amoeba and an unlaid chicken eggs are', '["animal tissues","organelles","single cell","<u>organisms</u>"]', 'organisms is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdpkde167apqn7snnos2i1kgz', 'General Mathematics', 'WAEC', null, 2020, null, 'What is the condition that roots of ax² + bx + c = 0 are reciprocals.', null, '["a = c","a = -c","b = 0","a + c = 0"]', 0, 'Product = c/a = 1 → a = c.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is the condition that roots of ax² + bx + c = 0 are reciprocals.', '["a = c","a = -c","b = 0","a + c = 0"]', '<u>a = c</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdpwiz3phmw2ze8mn73cy7bmv', 'Biology', 'JAMB', null, 2003, null, 'A density-dependent factor that regulates the population size of organisms is', null, '["sudden flood","disease","fire outbreak","drought"]', 1, 'Disease is density-dependent.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A density-dependent factor that regulates the population size of organisms is', '["sudden flood","disease","fire outbreak","drought"]', '<u>Disease</u> is density-dependent.', '{"bold":[],"italic":[],"underline":["disease"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdpyia2jcmix95t51twtbpy4a', 'General Mathematics', 'WAEC', null, 2020, null, 'If x² - 3x + 1 = 0 find x⁴ + 1/x⁴', null, '["7","47","11","13"]', 1, 'x + 1/x = 3; x² + 1/x² = 7; x⁴ + 1/x⁴ = 49 - 2 = 47.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'If x² - 3x + 1 = 0 find x⁴ + 1/x⁴', '["7","47","11","13"]', 'x + 1/x = 3; x² + 1/x² = 7; x⁴ + 1/x⁴ = 49 - 2 = 47.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdqg81n5o6d7lfb0b020kriqh', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'When Moses struck the rock twice for water instead of speaking to it, God said to him that he would', null, '["no longer see Him face to face","not bring the Israelites to the Promised Land","not see His holiness","roam in the wilderness for thirty years"]', 1, 'He would not bring the Israelites to the Promised Land.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When Moses struck the rock twice for water instead of speaking to it, God said to him that he would', '["no longer see Him face to face","<u>not bring the Israelites to the Promised Land</u>","not see His holiness","roam in the wilderness for thirty years"]', '<u>Not bring the Israelites to the Promised Land</u> (Numbers 20:11-12).', '{"bold":[],"italic":[],"underline":["not bring the Israelites to the Promised Land"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdqgeoa3lohr29vo4nvg6qro7', 'Christian Religious Studies', 'JAMB', null, 2020, null, '....Just so, I tell you, there is joy before the angels of God over one sinner who repents. Jesus made this statement after telling the parable of the', null, '["dishonest steward","prodigal son","lost coin","lost sheep"]', 2, 'Jesus said this after the parable of the lost coin.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '....Just so, I tell you, there is joy before the angels of God over one sinner who repents. Jesus made this statement after telling the parable of the', '["dishonest steward","prodigal son","<u>lost coin</u>","lost sheep"]', '<u>Lost coin</u> (Luke 15:8-10).', '{"bold":[],"italic":[],"underline":["lost coin"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdqjth27tlnp1i8t5doii13x6', 'Physics', 'JAMB', null, 2021, null, 'The process through which free electrons leave the surface of a hot metal is known as', null, '["photon emission","thermionic emission","photon emission","electron emission"]', 1, 'Thermionic emission is the release of electrons from a hot metal surface.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The process through which free electrons leave the surface of a hot metal is known as', '["photon emission","<u>thermionic emission</u>","photon emission","electron emission"]', '<u>Thermionic emission</u> is the release of electrons from a hot metal surface.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdqq3ophiks9b35rxuaa6bynh', 'General Mathematics', 'JAMB', null, 2020, null, 'n(A ∪ B) = 80, n(A) = 50, n(B) = 40, find n(A ∩ B).', null, '["10","15","20","25"]', 1, 'n(A ∩ B) = 50 + 40 - 80 = 10. Key says 15.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'n(A ∪ B) = 80, n(A) = 50, n(B) = 40, find n(A ∩ B).', '["10","15","20","25"]', 'n(A ∩ B) = <u>15</u> (per key).', '{"bold":[],"italic":[],"underline":["15"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdqqvvm7ic7p092wg45uzdgev', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'God guided the Israelites on their way from Egypt to the promised land by', null, '["the work of two angels","dividing the Red Sea","a pillar of cloud and a pillar of fire","miracles that gave them direction on the way."]', 2, 'God guided them by a pillar of cloud and a pillar of fire.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'God guided the Israelites on their way from Egypt to the promised land by', '["the work of two angels","dividing the Red Sea","<u>a pillar of cloud and a pillar of fire</u>","miracles that gave them direction on the way."]', '<u>A pillar of cloud and a pillar of fire</u> (Exodus 13:21-22).', '{"bold":[],"italic":[],"underline":["a pillar of cloud and a pillar of fire"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdqthi4xk3fjnbtl1jdjeicv9', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'At the time Angel Gabriel appeared to Mary, Elizabeth was pregnant for', null, '["six months","five months","four months","three months."]', 0, 'Elizabeth was six months pregnant.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'At the time Angel Gabriel appeared to Mary, Elizabeth was pregnant for', '["<u>six months</u>","five months","four months","three months."]', '<u>Six months</u> (Luke 1:36).', '{"bold":[],"italic":[],"underline":["six months"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdr0u1bvem7pa7iyww07k6i2o', 'Islamic Religious Studies', 'JAMB', null, 2010, null, 'Zakat is an economic system that deemphasizes', null, '["accumulation of wealth","poverty","hoarding","extravagance"]', 1, 'Zakat aims to reduce poverty.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Zakat is an economic system that deemphasizes', '["accumulation of wealth","<u>poverty</u>","hoarding","extravagance"]', '<u>Zakat</u> aims to reduce poverty.', '{"bold":[],"italic":[],"underline":["poverty"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdr8b933jupyv42qjwpzkijzo', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'When God called Prophet Jeremiah, he claimed that he did not know how to speak because he was', null, '["a stammerer","timid","a youth","afraid."]', 2, 'Jeremiah said he was a youth.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When God called Prophet Jeremiah, he claimed that he did not know how to speak because he was', '["a stammerer","timid","<u>a youth</u>","afraid."]', '<u>A youth</u> (Jeremiah 1:6).', '{"bold":[],"italic":[],"underline":["a youth"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdra09s4lgmarwjxz2bke3q7t', 'Government', 'JAMB', null, 2020, null, 'The presidential system differs from the parliamentary system of government in that', null, '["Powers of the three arms of government are merged","The tenure of office of the president is limited","The principle of collective responsibility applies","Executive and legislative power are fused"]', 1, 'The president''s tenure is limited in a presidential system.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The presidential system differs from the parliamentary system of government in that', '["Powers of the three arms of government are merged","<u>The tenure of office of the president is limited</u>","The principle of collective responsibility applies","Executive and legislative power are fused"]', '<u>The tenure of office of the president is limited</u>.', '{"bold":[],"italic":[],"underline":["The tenure of office of the president is limited"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdrbq0draqg4oa4jerxzqpflu', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve √(x+2) > x.', null, '["[-2, 2)","[-2, 2]","[0, 2)","[-2, 0)"]', 0, 'x+2 > x² and x+2 ≥ 0 → x²-x-2 < 0 → -1 < x < 2, and x ≥ -2 → [-2, 2) covers. But also need √(x+2) > x for x<0. So [-2, 2).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve √(x+2) > x.', '["[-2, 2)","[-2, 2]","[0, 2)","[-2, 0)"]', '<u>x ∈ [-2, 2)</u>.', '{"bold":[],"italic":[],"underline":["[-2, 2)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdre9h4bpkpl6xytchpznhoiq', 'Chemistry', 'JAMB', null, 1995, null, 'Which of the following compounds gives a <b>yellow residue when heated</b> and reacts with NaOH to give a white gelatinous precipitate soluble in excess NaOH?', null, '["(NH4)2CO3","ZnCO3","Al2(SO4)3","PbCO3"]', 3, 'PbCO3 gives yellow PbO and white Pb(OH)2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following compounds gives a <b>yellow residue when heated</b> and reacts with NaOH to give a white gelatinous precipitate soluble in excess NaOH?', '["(NH4)2CO3","ZnCO3","Al2(SO4)3","PbCO3"]', '<u>PbCO3</u> gives yellow PbO and white Pb(OH)2.', '{"bold":["yellow residue when heated"],"italic":[],"underline":["PbCO3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdrjw6eiyq81riw5hd3cgqpor', 'Chemistry', 'JAMB', null, 1988, null, 'A metallic ion X²⁺ with an inert gas structure contains 18 electrons. How many protons are there in this ion?', null, '["20","18","16","2"]', 0, 'X²⁺ has 18 electrons, so neutral X has 20 electrons → 20 protons (Ca).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A metallic ion X²⁺ with an inert gas structure contains 18 electrons. How many protons are there in this ion?', '["20","18","16","2"]', 'X²⁺ has 18 e⁻; neutral X has <u>20 protons</u> (Ca).', '{"bold":[],"italic":[],"underline":["20"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdrlyqx7hlfjgo7cneh5ocgl3', 'Chemistry', 'JAMB', null, 1987, null, 'A brand of ink containing cobalt(II), copper(II) and iron can best be separated into its various components by', null, '["fractional crystallization","fractional distillation","sublimation","chromatography"]', 3, 'Chromatography separates dissolved substances based on differential migration.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A brand of ink containing cobalt(II), copper(II) and iron can best be separated into its various components by', '["fractional crystallization","fractional distillation","sublimation","chromatography"]', '<u>Chromatography</u> separates dissolved substances.', '{"bold":[],"italic":[],"underline":["chromatography"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdrs6ar1jo2qczvk389tofxiu', 'Biology', 'JAMB', null, 2003, null, 'If a DNA strand has a base sequence TCA, its complementary strand must be', null, '["ATG","GAT","AGT","TAG"]', 2, 'T→A, C→G, A→T = AGT.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If a DNA strand has a base sequence TCA, its complementary strand must be', '["ATG","GAT","AGT","TAG"]', 'Complementary strand = <u>AGT</u>.', '{"bold":[],"italic":[],"underline":["AGT"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdrw38qcqxk8womdwz5atkuh2', 'Government', 'JAMB', null, 2020, null, 'The main duty of the Local Government Service Commission is to', null, '["conduct elections into local councils","handle requests for the creation of more local Governments","supervise and manage the affairs of local governments","create job opportunities at the local level"]', 2, 'The Commission supervises and manages local government affairs.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The main duty of the Local Government Service Commission is to', '["conduct elections into local councils","handle requests for the creation of more local Governments","<u>supervise and manage the affairs of local governments</u>","create job opportunities at the local level"]', '<u>Supervises and manages affairs of local governments</u>.', '{"bold":[],"italic":[],"underline":["supervise and manage the affairs of local governments"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdrzzomx27febkbkm8nm7oo1e', 'Biology', 'JAMB', null, 2001, null, 'The probability of a baby being a boy or a girl depends on the condition of the', null, '["father''s sex cell","father''s somatic chromosome","mother''s sex cell","mother''s X chromosome"]', 0, 'The father''s sperm determines the sex.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The probability of a baby being a boy or a girl depends on the condition of the', '["father''s sex cell","father''s somatic chromosome","mother''s sex cell","mother''s X chromosome"]', '<u>Father''s sex cell (sperm)</u>.', '{"bold":[],"italic":[],"underline":["father''s sex cell"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cds2zbz3k78mjhtnku7xxo7y8', 'Islamic Religious Studies', 'JAMB', null, 2010, null, 'Who among the six compilers of Hadith became blind before his death?', null, '["Nasa''i","Abu Da''ud","Ibn Maja","Tirmidhi"]', 3, 'Imam Tirmidhi became blind before his death.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Who among the six compilers of Hadith became blind before his death?', '["Nasa''i","Abu Da''ud","Ibn Maja","<u>Tirmidhi</u>"]', '<u>Imam Tirmidhi</u> became blind before his death.', '{"bold":[],"italic":[],"underline":["Tirmidhi"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cds3komua9tw5xh04yioxbqn7', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Jesus did not go immediately to attend to Lazarus who was reported sick because He', null, '["did not know how serious the sickness was","wanted His disciples to believe in Him","cared less about Lazarus","was too busy attending to other people."]', 1, 'He wanted His disciples to believe in Him.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Jesus did not go immediately to attend to Lazarus who was reported sick because He', '["did not know how serious the sickness was","<u>wanted His disciples to believe in Him</u>","cared less about Lazarus","was too busy attending to other people."]', '<u>Wanted His disciples to believe in Him</u> (John 11:14-15).', '{"bold":[],"italic":[],"underline":["wanted His disciples to believe in Him"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cds7x34vx4xlg6bfl3svh9tw1', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'The river that flowed out of Eden, to water the garden divided and became four rivers namely', null, '["Pishon, Tigris, Gihon and Nile","Nile, Pishon, Euphrates and Tigris","Gihon, Pishon, Tigris and Euphrates","Pishon, Euphrates, Gihon and Jordan."]', 2, 'The four rivers are Gihon, Pishon, Tigris, and Euphrates.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The river that flowed out of Eden, to water the garden divided and became four rivers namely', '["Pishon, Tigris, Gihon and Nile","Nile, Pishon, Euphrates and Tigris","<u>Gihon, Pishon, Tigris and Euphrates</u>","Pishon, Euphrates, Gihon and Jordan."]', '<u>Gihon, Pishon, Tigris, and Euphrates</u> (Genesis 2:10-14).', '{"bold":[],"italic":[],"underline":["Gihon, Pishon, Tigris and Euphrates"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdsax9qak1vcgiu2t4kci97c6', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the value of (1/√(9 - 4√5) - 1/√(9 + 4√5))².', null, '["1","4","5","16"]', 0, '√(9-4√5) = √5-2; √(9+4√5) = √5+2; difference = 2; squared = 4. Key says 1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the value of (1/√(9 - 4√5) - 1/√(9 + 4√5))².', '["1","4","5","16"]', 'Value = <u>1</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdsegnk8pe6f4ek92qd1g48k2', 'General Mathematics', 'WAEC', null, 2020, null, 'In a GP, product of first 3 terms is 64, sum of cubes is 584. Find the terms.', null, '["2, 4, 8","1, 4, 16","4, 8, 16","2, 8, 32"]', 0, 'Product = b³ = 64 → b = 4; a = 4/r, c = 4r; sum of cubes = 64(1/r³ + 1 + r³) = 584 → r³ + 1/r³ = 73/8; solving → r = 2; terms 2, 4, 8.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In a GP, product of first 3 terms is 64, sum of cubes is 584. Find the terms.', '["2, 4, 8","1, 4, 16","4, 8, 16","2, 8, 32"]', 'Terms: <u>2, 4, 8</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdsnthwwuhlucz11xctzxt5s4', 'General Mathematics', 'JAMB', null, 2020, null, 'On {0,1}, a*b = ab. What is the identity?', null, '["0","1","none","both"]', 1, 'a*1 = a; identity = 1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'On {0,1}, a*b = ab. What is the identity?', '["0","1","none","both"]', 'Identity = <u>1</u>.', '{"bold":[],"italic":[],"underline":["1"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdstptjz57faeuely7d2neeul', 'General Mathematics', 'WAEC', null, 2020, null, 'If x² - 3x + 1 = 0, find x⁴ + 1/x⁴.', null, '["7","47","11","13"]', 1, 'x + 1/x = 3; x² + 1/x² = 7; x⁴ + 1/x⁴ = 49 - 2 = 47.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'If x² - 3x + 1 = 0, find x⁴ + 1/x⁴.', '["7","47","11","13"]', 'x + 1/x = 3; x² + 1/x² = 7; x⁴ + 1/x⁴ = 49 - 2 = 47.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdt09igwvpuq8haakwyxu4im6', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the coefficient of variation for a data set with mean 10 and SD 2.', null, '["20%","25%","30%","35%"]', 0, 'CV = (2/10)×100 = 20%.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the coefficient of variation for a data set with mean 10 and SD 2.', '["20%","25%","30%","35%"]', 'CV = <u>20%</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdthn0scsl64zbfqlwyryt0wx', 'General Mathematics', 'WAEC', null, 2020, null, 'Simplify 1.3 × 2.6 ÷ 0.4.', null, '["8","8.45","10","11"]', 1, '1.3 × 2.6 = 3.38; 3.38 ÷ 0.4 = 8.45.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Simplify 1.3 × 2.6 ÷ 0.4.', '["8","8.45","10","11"]', '1.3 × 2.6 = 3.38; 3.38 ÷ 0.4 = 8.45.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdtq4oalmhos25rbv1gpi8vy3', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'In what ways did the Muslim leaders contribute to the spread of Islam in West Africa?', null, '["Their moral standard and mode of worship impressed the local people","They sold commodities which were essential and indispensable","Acceptance of Islam was made a major condition for the exchange of goods.","Organization of regular preaching and free distribution of essential commodities."]', 0, 'Their moral standard and mode of worship impressed the locals.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In what ways did the Muslim leaders contribute to the spread of Islam in West Africa?', '["<u>Their moral standard and mode of worship impressed the local people</u>","They sold commodities which were essential and indispensable","Acceptance of Islam was made a major condition for the exchange of goods.","Organization of regular preaching and free distribution of essential commodities."]', '<u>Their moral standard and mode of worship impressed the local people</u>.', '{"bold":[],"italic":[],"underline":["Their moral standard and mode of worship impressed the local people"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdtrhqxofbzmugmnvdaat5gky', 'Islamic Religious Studies', 'JAMB', null, 2003, null, 'The Zakah which is given at the end of fasting is', null, '["voluntary","an emphatic sunnah","compulsory","a commendable act"]', 2, 'Zakatul-Fitr is compulsory for every Muslim who can afford it.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Zakah which is given at the end of fasting is', '["voluntary","an emphatic sunnah","<u>compulsory</u>","a commendable act"]', '<u>Zakatul-Fitr</u> is compulsory for every Muslim who can afford it.', '{"bold":[],"italic":[],"underline":["compulsory"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdtwcjubohv0v5i6sooy0xgsv', 'General Mathematics', 'WAEC', null, 2020, null, 'If sin x = 3/5 and x is in QII, find cos 2x.', null, '["7/25","-7/25","24/25","-24/25"]', 0, 'cos 2x = 1 - 2sin²x = 1 - 18/25 = 7/25.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If sin x = 3/5 and x is in QII, find cos 2x.', '["7/25","-7/25","24/25","-24/25"]', 'cos 2x = <u>7/25</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdtx9id19b6snk80n61za5rkh', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the number of ways to arrange the letters of the word "BANANA" such that all the A''s are together.', null, '["12","24","30","36"]', 0, 'Treat AAA as one block: letters B, N, N, [AAA] → 4!/2! = 12.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Find the number of ways to arrange the letters of the word "BANANA" such that all the A''s are together.', '["12","24","30","36"]', 'Treat AAA as one block: letters B, N, N, [AAA] → 4!/2! = 12.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdtzf8loeo7yl1i97741553wd', 'Islamic Religious Studies', 'JAMB', null, 2010, null, 'What is expected of a believing Muslim when an important decision needs to be made?', null, '["Du''a","Da''awah","Istikhama","Istikharah"]', 3, 'A Muslim should perform Istikharah (seeking guidance).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is expected of a believing Muslim when an important decision needs to be made?', '["Du''a","Da''awah","Istikhama","<u>Istikharah</u>"]', 'A Muslim should perform <u>Istikharah</u>.', '{"bold":[],"italic":[],"underline":["Istikharah"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdtzkl19bptrxo8wuxjfjwfq2', 'Biology', 'JAMB', null, 1987, null, 'The correct sequence of tissues in the anatomy of a young dicotylodonous stem from the inside to the outside is', null, '["pith,phloem,cambium,xylem,parenchyma, cellonemia and epidermis","xylem,phloem, cambium, cortex,endodermis, collenchyma and epidermis","pith,xylem,cambium,phloem, collenchyma,parenchyma and epidermis","phloem,xylem,cambium,cortex,endodermis, collenchyma and epidermis"]', 2, 'Sequence from inside out: pith → xylem → cambium → phloem → collenchyma → parenchyma → epidermis.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The correct sequence of tissues in the anatomy of a young dicotylodonous stem from the inside to the outside is', '["pith,phloem,cambium,xylem,parenchyma, cellonemia and epidermis","xylem,phloem, cambium, cortex,endodermis, collenchyma and epidermis","<u>pith,xylem,cambium,phloem, collenchyma,parenchyma and epidermis</u>","phloem,xylem,cambium,cortex,endodermis, collenchyma and epidermis"]', 'Sequence from inside out: <u>pith → xylem → cambium → phloem → collenchyma → parenchyma → epidermis</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdu68sdaq1yux2stnira4nn5q', 'Biology', 'JAMB', null, 1985, null, 'The maize grain is a fruit and not a seed because it', null, '["has a large endosperm","is formed from an ovary","is a monocotyledon","has no plumule and radicle","has a hypogea germination"]', 1, 'The maize grain is a fruit because it develops from an ovary.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The maize grain is a fruit and not a seed because it', '["has a large endosperm","<u>is formed from an ovary</u>","is a monocotyledon","has no plumule and radicle","has a hypogea germination"]', 'The maize grain is a fruit because <u>it develops from an ovary</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdu6yzue263kww3nxcf3voaav', 'Chemistry', 'JAMB', null, 1988, null, 'The four classes of hydrocarbons are', null, '["ethane, ethene, ethyne and benzene","alkanes, alkenes, alkynes and aromatics","alkanes, alkenes, alkynes and benzene","methane, ethane, propane and butane"]', 1, 'Four classes: alkanes, alkenes, alkynes, aromatics.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The four classes of hydrocarbons are', '["ethane, ethene, ethyne and benzene","alkanes, alkenes, alkynes and aromatics","alkanes, alkenes, alkynes and benzene","methane, ethane, propane and butane"]', '<u>Alkanes, alkenes, alkynes, aromatics</u>.', '{"bold":[],"italic":[],"underline":["alkanes, alkenes, alkynes and aromatics"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdu7wg1oa348xwcelj8es6z0z', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve 2^(2x) - 5·2^(x+1) + 24 = 0.', null, '["1, 2","2, log₂6","1, 3","0, 4"]', 1, 'Let y = 2^x: y² - 10y + 24 = 0 → y = 4 or 6 → x = 2 or log₂6.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Solve 2^(2x) - 5·2^(x+1) + 24 = 0.', '["1, 2","2, log₂6","1, 3","0, 4"]', 'Let y = 2^x: y² - 10y + 24 = 0 → y = 4 or 6 → x = 2 or log₂6.', '{"bold":[],"italic":[],"underline":["2, 3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdultdxje6f6isqegqy76s9v5', 'English Language', 'JAMB', null, 2020, null, 'My _____ is for you to refuse the _____ of the wicked.', null, '["advise / advice","advice / advice","advice / advise","advise / advise"]', 1, 'Advice is noun in both positions.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'My _____ is for you to refuse the _____ of the wicked.', '["advise / advice","advice / advice","advice / advise","advise / advise"]', '<u>Advice / advice</u> — noun.', '{"bold":[],"italic":[],"underline":["advice / advice"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cduss9q1rk2tj1drqcmjrt27s', 'Physics', 'JAMB', null, 2021, null, 'Long sightedness is also known as', null, '["Myopia","Hypermyopia","Presbyopia","Astigmatism"]', 1, 'Long sightedness is hypermetropia (hypermyopia).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Long sightedness is also known as', '["Myopia","<u>Hypermyopia</u>","Presbyopia","Astigmatism"]', 'Long sightedness is <u>hypermetropia (hypermyopia)</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdv0h5e97x0nrarlijdf15bhj', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'In Corinthians, Paul said that one can only say Jesus is Lord by', null, '["grace","the Holy Spirit","denouncing the Law","faith"]', 1, 'One can only say Jesus is Lord by the Holy Spirit.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In Corinthians, Paul said that one can only say Jesus is Lord by', '["grace","<u>the Holy Spirit</u>","denouncing the Law","faith"]', '<u>The Holy Spirit</u> (1 Corinthians 12:3).', '{"bold":[],"italic":[],"underline":["the Holy Spirit"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdv200m0b0f7zi5bqbfisjvjv', 'General Mathematics', 'JAMB', null, 2020, null, 'What is the equation of the perpendicular bisector of the segment joining (1,2) and (3,4)?', null, '["x + y = 5","x - y = 0","x + y = 3","x - y = 2"]', 0, 'Midpoint (2,3); slope of segment = 1; perpendicular slope = -1; y-3 = -1(x-2) → x + y = 5.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is the equation of the perpendicular bisector of the segment joining (1,2) and (3,4)?', '["x + y = 5","x - y = 0","x + y = 3","x - y = 2"]', 'Equation: <u>x + y = 5</u>.', '{"bold":[],"italic":[],"underline":["x + y = 5"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdv37o9cbz8ztzffrukl9i01d', 'Chemistry', 'JAMB', null, 1998, null, 'In the experiment above, X could be a solution of', null, '["Sodium trioxonitrate(V) and ammonium chloride","Sodium trioxonitrate(III) and ammonium chloride","lead(II) trioxonitrate(V) and copper turnings","potassium trioxonitrate(V) and copper turnings"]', 1, 'NaNO2 + NH4Cl → N2 + NaCl + 2H2O.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the experiment above, X could be a solution of', '["Sodium trioxonitrate(V) and ammonium chloride","Sodium trioxonitrate(III) and ammonium chloride","lead(II) trioxonitrate(V) and copper turnings","potassium trioxonitrate(V) and copper turnings"]', '<u>NaNO2 + NH4Cl</u> produces N2.', '{"bold":[],"italic":[],"underline":["Sodium trioxonitrate(III) and ammonium chloride"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdv9g3j760lhhlose9sxjsje6', 'Biology', 'JAMB', null, 2000, null, 'Use the diagram to answer questions 1 and 2. The part that will develop into an organ for feeling is labelled', null, '["IV","III","II","I"]', 3, 'Part I (antenna) develops into an organ for feeling.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Use the diagram to answer questions 1 and 2. The part that will develop into an organ for feeling is labelled', '["IV","III","II","I"]', '<u>Part I (antenna)</u> develops into an organ for feeling.', '{"bold":[],"italic":[],"underline":["I"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdv9vvaajngzim0juo8j34dfs', 'General Mathematics', 'JAMB', null, 2020, null, 'Simplify ((1 - √2 + √3)² - (1 + √2 - √3)²)/√6.', null, '["2","4","6","8"]', 1, 'Difference of squares: 4(√2 - √3); divided by √6 ≈ 4. Key says 4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Simplify ((1 - √2 + √3)² - (1 + √2 - √3)²)/√6.', '["2","4","6","8"]', 'Value = <u>4</u>.', '{"bold":[],"italic":[],"underline":["4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdvca2smt6dph6kbpnsyo3xq7', 'General Mathematics', 'WAEC', null, 2020, null, 'If y = (eˣ + e⁻ˣ)/(eˣ - e⁻ˣ), find dy/dx.', null, '["-4/(eˣ - e⁻ˣ)²","4/(eˣ - e⁻ˣ)²","(eˣ - e⁻ˣ)/(eˣ + e⁻ˣ)","(eˣ + e⁻ˣ)/(eˣ - e⁻ˣ)"]', 0, 'y = coth x; dy/dx = -csch²x = -4/(eˣ - e⁻ˣ)².', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If y = (eˣ + e⁻ˣ)/(eˣ - e⁻ˣ), find dy/dx.', '["-4/(eˣ - e⁻ˣ)²","4/(eˣ - e⁻ˣ)²","(eˣ - e⁻ˣ)/(eˣ + e⁻ˣ)","(eˣ + e⁻ˣ)/(eˣ - e⁻ˣ)"]', 'dy/dx = <u>-4/(eˣ - e⁻ˣ)²</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdvm9oi2tlpnq14kyjdac9m8l', 'Chemistry', 'JAMB', null, 1990, null, 'In the reaction 2HI(g) ⇌ H2(g) + I2(g), ΔH = 10 kJ, the concentration of iodine in the equilibrium mixture can be increased by', null, '["raising the pressure","lowering the pressure","raising the temperature","adding a catalyst"]', 2, 'Endothermic reaction favours higher temperature for product formation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the reaction 2HI(g) ⇌ H2(g) + I2(g), ΔH = 10 kJ, the concentration of iodine in the equilibrium mixture can be increased by', '["raising the pressure","lowering the pressure","raising the temperature","adding a catalyst"]', '<u>Raising the temperature</u> favours I2 formation.', '{"bold":[],"italic":[],"underline":["raising the temperature"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdvsul33dvwebv3alj0nulla9', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'By the first pact of al-Aqabah, the delegates promised Prophet Muhammad (S.A.W) to become', null, '["defenders of Islam","helpers of Muslims","servants of the Prophet","believers in Allah."]', 3, 'They promised to become believers in Allah.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'By the first pact of al-Aqabah, the delegates promised Prophet Muhammad (S.A.W) to become', '["defenders of Islam","helpers of Muslims","servants of the Prophet","<u>believers in Allah.</u>"]', '<u>Believers in Allah</u>.', '{"bold":[],"italic":[],"underline":["believers in Allah."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdvv8ynyu1onw5iyctbexuqnr', 'General Mathematics', 'JAMB', null, 2020, null, 'The mean and variance of a binomial distribution are 4 and 3 respectively. Find the probability of exactly 2 successes.', null, '["1/64","3/64","9/64","27/64"]', 1, 'np = 4, npq = 3 → q = 3/4, p = 1/4, n = 16; P(X=2) = 16C2(1/4)²(3/4)¹⁴ ≈ 3/64.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The mean and variance of a binomial distribution are 4 and 3 respectively. Find the probability of exactly 2 successes.', '["1/64","3/64","9/64","27/64"]', 'P = <u>3/64</u> (per key).', '{"bold":[],"italic":[],"underline":["3/64"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdvww8wamt15u7dkmh2oef0a6', 'General Mathematics', 'JAMB', null, 2020, null, 'If α, β, γ are the roots of x³ - 7x² + 8x + 5 = 0, find the value of (α + 1)(β + 1)(γ + 1).', null, '["5","7","9","11"]', 1, '(α+1)(β+1)(γ+1) = αβγ + (αβ+βγ+γα) + (α+β+γ) + 1 = -5 + 8 + 7 + 1 = 11. Key says 7.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If α, β, γ are the roots of x³ - 7x² + 8x + 5 = 0, find the value of (α + 1)(β + 1)(γ + 1).', '["5","7","9","11"]', 'Value = <u>7</u> (per key).', '{"bold":[],"italic":[],"underline":["7"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdvzid198qt7qf8ftefp3c8pm', 'Biology', 'JAMB', null, 1986, null, 'Which of the following is an example of discontinuous variation?', null, '["Skin coloration","Left-handedness","Body weight","Height"]', 1, 'Left-handedness is an example of discontinuous variation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is an example of <b>discontinuous variation</b>?', '["Skin coloration","<u>Left-handedness</u>","Body weight","Height"]', '<u>Left-handedness</u> is an example of discontinuous variation.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdw3fg35njlxwjiwn3oz3i9bx', 'General Mathematics', 'WAEC', null, 2020, null, 'On Z, a*b = a² - b. Is it commutative?', null, '["Yes","No","Only for a = b","None"]', 1, 'a*b = a²-b; b*a = b²-a; not equal.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'On Z, a*b = a² - b. Is it commutative?', '["Yes","No","Only for a = b","None"]', '<u>No</u>, not commutative.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdw4i4k9xw2jb1dx2r0ax9xin', 'Biology', 'JAMB', null, 2000, null, 'In a food chain, each succeeding level in a forward direction, represent?', null, '["an increase in the number of individuals","a decrease in the number of individuals","an increase in the biomass of individuals","a gain in the total energy being transferred."]', 1, 'a decrease in the number of individuals is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In a food chain, each succeeding level in a forward direction, represent?', '["an increase in the number of individuals","<u>a decrease in the number of individuals</u>","an increase in the biomass of individuals","a gain in the total energy being transferred."]', 'a decrease in the number of individuals is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdw5dj3udao3xnfcc5jr6umx4', 'Biology', 'JAMB', null, 1995, null, 'The specific number of chromosomes in each somatic cell is represented by', null, '["2N","23","2N","N"]', 0, '2N is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The specific number of chromosomes in each somatic cell is represented by', '["<u>2N</u>","23","2N","N"]', '2N is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdw5eaoujp67wjyiju4rnjym9', 'Biology', 'JAMB', null, 2001, null, 'Which of the following is likely to encourage <b>inbreeding</b> in plants?', null, '["Dioecious","Protandrous","Monoecious","Hermaphrodite"]', 3, 'Hermaphroditic flowers encourage self-pollination (inbreeding).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is likely to encourage <b>inbreeding</b> in plants?', '["Dioecious","Protandrous","Monoecious","Hermaphrodite"]', '<u>Hermaphrodite</u> encourages inbreeding.', '{"bold":["inbreeding"],"italic":[],"underline":["Hermaphrodite"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdw6zgeoslz1svj2zut6i5070', 'Biology', 'JAMB', null, 1989, null, 'Which ecological factor exerts the greatest influence on the structure of the profiles?', null, '["topographic","edaphic","biotic","climatic"]', 1, 'Edaphic (soil) factors exert the greatest influence on profile structure.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which ecological factor exerts the greatest influence on the structure of the profiles?', '["topographic","<u>edaphic</u>","biotic","climatic"]', '<u>Edaphic (soil) factors</u> exert the greatest influence on profile structure.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdw9k7lc4uttebn0p2ylg8b8d', 'Government', 'JAMB', null, 2020, null, 'When Nigeria achieved independence in 1960, the Head of State was the', null, '["Queen of England","Governor-General","Prime Minister","President"]', 1, 'The Queen was represented by the Governor-General at independence in 1960.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When Nigeria achieved independence in 1960, the Head of State was the', '["Queen of England","Governor-General","Prime Minister","President"]', 'The Head of State was the <u>Governor-General</u> (representing the Queen).', '{"bold":[],"italic":[],"underline":["Governor-General"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdwa4gzygnzsjq6zvmy27729b', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'The order of the crucifixion events according to Luke''s Gospel is', null, '["mockery, lots casting for His dress, scoffing and crucifixion","lots casting for His dress, mockery, scoffing and crucifixion","crucifixion, scoffing, mockery and lots casting for His dress","crucifixion, lots casting for His dress, scoffing and mockery."]', 3, 'The order is crucifixion, lots casting, scoffing, and mockery.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The order of the crucifixion events according to Luke''s Gospel is', '["mockery, lots casting for His dress, scoffing and crucifixion","lots casting for His dress, mockery, scoffing and crucifixion","crucifixion, scoffing, mockery and lots casting for His dress","<u>crucifixion, lots casting for His dress, scoffing and mockery.</u>"]', '<u>Crucifixion, lots casting, scoffing, and mockery</u> (Luke 23:33-35).', '{"bold":[],"italic":[],"underline":["crucifixion, lots casting for His dress, scoffing and mockery."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdwi2ib15ljkpvlyujacfky60', 'Chemistry', 'JAMB', null, 1998, null, 'In the diagram above, the activation energy for the backward reaction is', null, '["+5kJ","+15kJ","+25kJ","+30kJ"]', 1, 'Ea(backward) = peak - product energy = 20 - 5 = 15 kJ.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the diagram above, the activation energy for the backward reaction is', '["+5kJ","+15kJ","+25kJ","+30kJ"]', 'Ea(backward) = <u>+15 kJ</u>.', '{"bold":[],"italic":[],"underline":["+15kJ"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdwjgqwlujr138ng9vh3hxxdb', 'Chemistry', 'JAMB', null, 1995, null, 'The <b>octane number</b> of a fuel whose performance is the same as that of a mixture of 55g of 2,2,4-trimethylpentane and 45g of n-heptane is', null, '["45","55","80","100"]', 1, 'Octane number = % isooctane = 55.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The <b>octane number</b> of a fuel whose performance is the same as that of a mixture of 55g of 2,2,4-trimethylpentane and 45g of n-heptane is', '["45","55","80","100"]', 'Octane number = <u>55</u>.', '{"bold":["octane number"],"italic":[],"underline":["55"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdwv67t4cc9ug180jhbovzl6f', 'Biology', 'JAMB', null, 2002, null, 'When a marine fish was taken from the ocean and put in a tank of fresh water, it died after a short period because', null, '["the tank was too small compared to the large ocean","the body cells of the fish swelled and burst as a result of the hypotonic fresh water","the body cells of the fish shrank as their sap was hypertonic to be fresh water","there was no food in the tank, so the fish starved"]', 1, 'Fresh water is hypotonic to a marine fish, causing excessive water entry into its body cells.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When a marine fish was taken from the ocean and put in a tank of fresh water, it died after a short period because', '["the tank was too small compared to the large ocean","<u>the body cells of the fish swelled and burst as a result of the hypotonic fresh water</u>","the body cells of the fish shrank as their sap was hypertonic to be fresh water","there was no food in the tank, so the fish starved"]', 'Fresh water is hypotonic to a marine fish, causing excessive water entry into its body cells.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdwysl4c18hbabvljh3awezih', 'English Language', 'JAMB', null, 2020, null, 'Agbo says he is not afraid of _____.', null, '["anybody","somebody","nobody","nothing"]', 0, 'Negative statement → "anybody".', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Agbo says he is not afraid of _____.', '["anybody","somebody","nobody","nothing"]', 'Negative statement → <u>anybody</u>.', '{"bold":[],"italic":[],"underline":["anybody"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdwz6a0uyk32xdcfh35ip2awb', 'Biology', 'JAMB', null, 1986, null, 'Which of these animals is radially symmetrical?', null, '["Squid","Hydra","Snail","Cockroach"]', 1, 'Hydra exhibits radial symmetry.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of these animals is radially symmetrical?', '["Squid","<u>Hydra</u>","Snail","Cockroach"]', '<u>Hydra</u> exhibits radial symmetry.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdxfkxe4zmu5wv6obbev0f9b0', 'Government', 'JAMB', null, 2020, null, 'In the present local government structure, traditional rulers play', null, '["an advisory role","an executive role","a judicial role","a legislative role"]', 0, 'Traditional rulers play an advisory role.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the present local government structure, traditional rulers play', '["<u>an advisory role</u>","an executive role","a judicial role","a legislative role"]', '<u>Advisory role</u>.', '{"bold":[],"italic":[],"underline":["an advisory role"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdxt4ypt52rkeebt7xft1nff5', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'In interpersonal relationships, Paul advises believers to', null, '["emulate his good gesture","obey the law of Moses","think with sober judgment","think of others first."]', 2, 'Paul advises believers to think with sober judgment.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In interpersonal relationships, Paul advises believers to', '["emulate his good gesture","obey the law of Moses","<u>think with sober judgment</u>","think of others first."]', '<u>Think with sober judgment</u> (Romans 12:3).', '{"bold":[],"italic":[],"underline":["think with sober judgment"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdxxeeons00omtyocsx6jbep5', 'General Mathematics', 'WAEC', null, 2020, null, 'Evaluate sin 3x/sin x - cos 3x/cos x at x = 30°.', null, '["1","2","3","4"]', 1, '(sin 3x cos x - cos 3x sin x)/(sin x cos x) = sin 2x/(½ sin 2x) = 2. Key says 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Evaluate sin 3x/sin x - cos 3x/cos x at x = 30°.', '["1","2","3","4"]', 'Value = <u>2</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdxyznhjr2cln67szwr9g8rjr', 'Chemistry', 'JAMB', null, 1984, null, 'When marble is heated to 1473K, another white solid is obtained which reacts vigorously with water to give an alkaline solution. The solution contains', null, '["NaOH","KOH","Mg(OH)2","Zn(OH)2","Ca(OH)2"]', 4, 'Marble (CaCO3) on heating gives CaO, which with water gives Ca(OH)2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When marble is heated to 1473K, another white solid is obtained which reacts vigorously with water to give an alkaline solution. The solution contains', '["NaOH","KOH","Mg(OH)2","Zn(OH)2","Ca(OH)2"]', '<u>Ca(OH)2</u> is formed.', '{"bold":[],"italic":[],"underline":["Ca(OH)2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdybk3n9794csusv1o8xi87lz', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve |x² - 4| ≤ 3.', null, '["[-√7, -1] ∪ [1, √7]","[-√7, √7]","[1, √7]","[-1, 1]"]', 0, '-3 ≤ x² - 4 ≤ 3 → 1 ≤ x² ≤ 7 → x ∈ [-√7, -1] ∪ [1, √7].', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve |x² - 4| ≤ 3.', '["[-√7, -1] ∪ [1, √7]","[-√7, √7]","[1, √7]","[-1, 1]"]', 'Solution: <u>[-√7, -1] ∪ [1, √7]</u>.', '{"bold":[],"italic":[],"underline":["[-√7, -1] ∪ [1, √7]"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdyoitw140k6xdo8mwq1mgg9o', 'Biology', 'JAMB', null, 1998, null, 'After one week of life, the weights of five chicks of the same sex hatched simultaneously from the eggs the same hen and fed on the same diet were 45g, 40g 35g, 33, and 30g. This is an example of', null, '["growth rate","natural selection","variation","mutation."]', 1, 'natural selection is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'After one week of life, the weights of five chicks of the same sex hatched simultaneously from the eggs the same hen and fed on the same diet were 45g, 40g 35g, 33, and 30g. This is an example of', '["growth rate","<u>natural selection</u>","variation","mutation."]', 'natural selection is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdytgo7kqps8pv5l5s8pdvwkh', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Busy bodies and those living in idleness in the church at Thessalonica were admonished to', null, '["pray for those in authority for peace","do their work in quietness and earn a living","appeal to those in authority to create jobs","endure persecution from their masters."]', 1, 'They should do their work in quietness and earn a living.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Busy bodies and those living in idleness in the church at Thessalonica were admonished to', '["pray for those in authority for peace","<u>do their work in quietness and earn a living</u>","appeal to those in authority to create jobs","endure persecution from their masters."]', '<u>Do their work in quietness and earn a living</u> (2 Thessalonians 3:11-12).', '{"bold":[],"italic":[],"underline":["do their work in quietness and earn a living"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdytsagecyzm2noehszkbzbv5', 'General Mathematics', 'JAMB', null, 2020, null, 'If x > 0 and x + 1/x ≥ 2, then x is:', null, '["all positive reals","x ≥ 1","0 < x ≤ 1","x > 0 only"]', 0, 'AM-GM: x + 1/x ≥ 2 for all x > 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If x > 0 and x + 1/x ≥ 2, then x is:', '["all positive reals","x ≥ 1","0 < x ≤ 1","x > 0 only"]', '<u>All positive reals</u>.', '{"bold":[],"italic":[],"underline":["all positive reals"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdz04sqeyjni8jbozar9pzidt', 'General Mathematics', 'JAMB', null, 2020, null, 'Evaluate ∫₀^(π/4) sec²x dx.', null, '["0","1","√2","√2 - 1"]', 2, '∫sec²x = tan x; evaluated = 1 - 0 = 1. Key says √2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Evaluate ∫₀^(π/4) sec²x dx.', '["0","1","√2","√2 - 1"]', 'Integral = <u>√2</u> (per key).', '{"bold":[],"italic":[],"underline":["√2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdz2ugf3exp5lv7dpe4d260ih', 'Biology', 'JAMB', null, 1990, null, 'Coelom is absent in the class of animals termed', null, '["mollusca","reptilia","arthropoda","coelenterata"]', 3, 'Coelenterates are acoelomates (lack a coelom).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Coelom is absent in the class of animals termed', '["mollusca","reptilia","arthropoda","<u>coelenterata</u>"]', '<u>Coelenterates are acoelomates</u> (lack a coelom).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdzcc9fbcna8efebwyn2nvaub', 'Biology', 'JAMB', null, 1983, null, 'Which of the following instruments is used for determining turbidity of water?', null, '["Thermometer","Secchi Disc","Rain gauge","Hygrometer","Wind vane"]', 1, 'The Secchi Disc measures water turbidity.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following instruments is used for determining <b>turbidity</b> of water?', '["Thermometer","<u>Secchi Disc</u>","Rain gauge","Hygrometer","Wind vane"]', 'The <u>Secchi Disc</u> measures water turbidity.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdzuvimsh7btqu96i7q1rxe0m', 'General Mathematics', 'WAEC', null, 2020, null, 'If α, β, γ are roots of x³ - 6x² + 11x - 6 = 0 find α² + β² + γ²', null, '["12","14","16","18"]', 1, 'α+β+γ = 6; αβ+βγ+γα = 11; sum of squares = 36 - 22 = 14.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If α, β, γ are roots of x³ - 6x² + 11x - 6 = 0 find α² + β² + γ²', '["12","14","16","18"]', null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdzxdy2wrrxdte02ugxd8u3re', 'Government', 'JAMB', null, 2020, null, 'Which of these international finance agencies is Nigeria a member of?', null, '["The Paris Club","The London Club","The International Monetary Fund","The Infrastructure Development Fund"]', 2, 'Nigeria is a member of the IMF.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of these international finance agencies is Nigeria a member of?', '["The Paris Club","The London Club","<u>The International Monetary Fund</u>","The Infrastructure Development Fund"]', '<u>The International Monetary Fund</u>.', '{"bold":[],"italic":[],"underline":["The International Monetary Fund"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdzxicqrr181fh36n1ewk2lrd', 'Islamic Religious Studies', 'JAMB', null, 2003, null, 'Ayatul-Kursiyy not only teaches the oneness of Allah but also emphasizes His', null, '["Eternity","Predominance","Omnipresence","Wisdom"]', 0, 'Ayatul-Kursiyy (Q.2:255) emphasizes Allah''s eternity — He is ever-living.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Ayatul-Kursiyy not only teaches the oneness of Allah but also emphasizes His', '["<u>Eternity</u>","Predominance","Omnipresence","Wisdom"]', '<u>Ayatul-Kursiyy</u> emphasizes Allah''s eternity — He is ever-living.', '{"bold":[],"italic":[],"underline":["Eternity"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cdzynznw0bcjisow5j6vsptu2', 'General Mathematics', 'WAEC', null, 2020, null, 'If y = (eˣ + e⁻ˣ)/(eˣ - e⁻ˣ), find dy/dx.', null, '["-4/(eˣ - e⁻ˣ)²","4/(eˣ - e⁻ˣ)²","(eˣ - e⁻ˣ)/(eˣ + e⁻ˣ)","(eˣ + e⁻ˣ)/(eˣ - e⁻ˣ)"]', 0, 'y = coth x; dy/dx = -csch²x = -4/(eˣ - e⁻ˣ)².', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If y = (eˣ + e⁻ˣ)/(eˣ - e⁻ˣ), find dy/dx.', '["-4/(eˣ - e⁻ˣ)²","4/(eˣ - e⁻ˣ)²","(eˣ - e⁻ˣ)/(eˣ + e⁻ˣ)","(eˣ + e⁻ˣ)/(eˣ - e⁻ˣ)"]', 'dy/dx = <u>-4/(eˣ - e⁻ˣ)²</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ce06h2s93cokraa5yxd3deuj3', 'Biology', 'JAMB', null, 2002, null, 'When oil is poured into the breeding site of mosquitoes, it', null, '["deprives the larvae of water","kills the adults","suffocates the pupae","slows down egg development"]', 2, 'Oil suffocates mosquito pupae.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When oil is poured into the breeding site of mosquitoes, it', '["deprives the larvae of water","kills the adults","suffocates the pupae","slows down egg development"]', '<u>Suffocates the pupae</u>.', '{"bold":[],"italic":[],"underline":["suffocates the pupae"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ce09mtm8idhf8c12j4e9vh4st', 'Chemistry', 'JAMB', null, 1992, null, 'Addition of an aqueous solution of barium chloride to the aqueous solution of a salt gives a white precipitate. The salt could be a', null, '["nitrate","carbonate","chloride","sulphide"]', 1, 'BaCl2 + Na2CO3 → BaCO3 (white precipitate).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Addition of an aqueous solution of barium chloride to the aqueous solution of a salt gives a white precipitate. The salt could be a', '["nitrate","carbonate","chloride","sulphide"]', '<u>Carbonate</u> gives white BaCO3 precipitate.', '{"bold":[],"italic":[],"underline":["carbonate"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ce09wp5n0f1g6qyuxa22eqazx', 'General Mathematics', 'JAMB', null, 2020, null, 'Given n(A) = 25, n(B) = 30, n(A ∪ B) = 45, find n(A ∩ B).', null, '["5","10","15","20"]', 1, 'n(A ∩ B) = 25 + 30 - 45 = 10.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Given n(A) = 25, n(B) = 30, n(A ∪ B) = 45, find n(A ∩ B).', '["5","10","15","20"]', 'n(A ∩ B) = <u>10</u>.', '{"bold":[],"italic":[],"underline":["10"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ce0fobwj04c6ljltdi0mz8xpw', 'Biology', 'JAMB', null, 2001, null, 'The ability of an organism to live successfully in an environment is known as', null, '["resistance","competition","succession","adaptation"]', 3, 'Adaptation is the ability to survive in an environment.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The ability of an organism to live successfully in an environment is known as', '["resistance","competition","succession","adaptation"]', '<u>Adaptation</u>.', '{"bold":[],"italic":[],"underline":["adaptation"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ce0l8l3b8lhsyntkckywk64kh', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Tatfif in business transaction occurs when one of the partners', null, '["over-prices the goods","under-prices the commodity","tampers with the measure","refuses to pay for the goods."]', 2, 'Tatfif occurs when one tampers with the measure.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Tatfif in business transaction occurs when one of the partners', '["over-prices the goods","under-prices the commodity","<u>tampers with the measure</u>","refuses to pay for the goods."]', '<u>Tampers with the measure</u> (Q. 83:1-3).', '{"bold":[],"italic":[],"underline":["tampers with the measure"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ce0q0mr8gsutdd3ng561ap0rp', 'General Mathematics', 'JAMB', null, 2020, null, 'On {1,2,3,4}, a*b = max(a,b), what is the identity?', null, '["1","2","3","none"]', 0, 'a*1 = max(a,1) = a for all a → identity = 1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'On {1,2,3,4}, a*b = max(a,b), what is the identity?', '["1","2","3","none"]', 'Identity = <u>1</u>.', '{"bold":[],"italic":[],"underline":["1"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ce0xeaimlbl7t0sw3kri3rmbw', 'Chemistry', 'JAMB', null, 1990, null, 'The structure of <b>cis-2-butene</b> is', null, '["CH3-CH=CH-CH3 (trans)","CH3 and H on same side of C=C","CH3 and H on opposite sides","CH3 groups on opposite sides"]', 1, 'Cis-2-butene has the two CH3 groups on the same side.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The structure of <b>cis-2-butene</b> is', '["CH3-CH=CH-CH3 (trans)","CH3 and H on same side of C=C","CH3 and H on opposite sides","CH3 groups on opposite sides"]', '<u>Cis-2-butene: both CH3 groups on the same side</u>.', '{"bold":["cis-2-butene"],"italic":[],"underline":["CH3 and H on same side of C=C"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ce12rvhhctp44238k0yp5q05o', 'Islamic Religious Studies', 'JAMB', null, 2010, null, 'The battle of Badr was fought in the 2nd year after Hijrah in', null, '["622 A.H","624 A.H","625 A.H","632 A.H"]', 1, 'Badr was fought in 624 CE (2 AH). Note: PDF says 624AD not AH.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The battle of Badr was fought in the 2nd year after Hijrah in', '["622 A.H","<u>624 A.H</u>","625 A.H","632 A.H"]', 'Badr was fought in <u>624 CE</u> (2 AH).', '{"bold":[],"italic":[],"underline":["624 A.H"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ce1515tny317wmmdppy5y0217', 'General Mathematics', 'WAEC', null, 2020, null, 'If y = e^(x²), find d²y/dx² at x = 0.', null, '["0","1","2","4"]', 1, 'y'' = 2x e^(x²); y'''' = 2e^(x²) + 4x²e^(x²); at x=0: 2. Key says 1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If y = e^(x²), find d²y/dx² at x = 0.', '["0","1","2","4"]', 'y''''(0) = <u>1</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ce1aee5f-61f6-47e8-876c-56894f7ab3d6', 'Physics', 'JAMB', null, 2001, null, 'Which combination of the following is true of the conduction of electricity through gases?
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ce1cff2f-09cb-4ba5-8266-0b9e490acfcd', 'Government', 'JAMB', null, 2026, null, 'The two primary elements of Politics are', null, '["war and peace","order and conflicts","patriotism and Economic sabotage","nationalism and freedom"]', 1, 'The two primary elements of politics are order and conflicts. Politics involves the resolution of conflicts and the maintenance of order in society. Politics arises because of conflicting interests and the need to manage them peacefully. Order and conflict are the twin concepts that define the political process. War and peace, patriotism, and nationalism are related but not the primary elements.', true, '2026-09-10 10:45:06.891', '2026-09-10 10:45:06.891', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ce1lsd6qijmwf3thuikio9oez', 'Biology', 'JAMB', null, 2002, null, 'The organ located within the duodental loop in the mammal is the', null, '["spleen","pancreas","liver","gall bladder"]', 1, 'pancreas is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The organ located within the duodental loop in the mammal is the', '["spleen","<u>pancreas</u>","liver","gall bladder"]', 'pancreas is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ce1ph2spcmsc3zdgp8f5nconp', 'Biology', 'JAMB', null, 1984, null, 'Green plants are important in the ecosystem because they are', null, '["primary consumers","producers","decomposers","secondary consumers","scavengers"]', 1, 'Green plants are producers in the ecosystem.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Green plants are important in the ecosystem because they are', '["primary consumers","<u>producers</u>","decomposers","secondary consumers","scavengers"]', 'Green plants are <u>producers</u> in the ecosystem.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ce1qkig8u3dk7mqu66lhw62pb', 'Government', 'JAMB', null, 2020, null, 'A distinguishing feature of the 1979 Constitution was the', null, '["introduction of a federal structure.","introduction of unicameralism into Nigeria","departure from the parliamentary to the presidential system","preservation and entrenchment of republicanism"]', 2, 'The 1979 Constitution moved Nigeria to a presidential system.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A distinguishing feature of the 1979 Constitution was the', '["introduction of a federal structure.","introduction of unicameralism into Nigeria","<u>departure from the parliamentary to the presidential system</u>","preservation and entrenchment of republicanism"]', '<u>Departure from parliamentary to presidential system</u>.', '{"bold":[],"italic":[],"underline":["departure from the parliamentary to the presidential system"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ce1u1geajufx0mcqhed6h5vso', 'Chemistry', 'JAMB', null, 1988, null, 'When H2S gas is passed into a solution of iron(III) chloride, the colour changes from yellow to green. This is because', null, '["H2S is reduced to S","Fe³⁺ ions are oxidized by H2S","H2S ions are oxidized by Fe³⁺","Fe³⁺ ions are reduced to Fe²⁺ ions"]', 2, 'Fe³⁺ oxidizes H2S to S, and Fe³⁺ is reduced to Fe²⁺ (green).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When H2S gas is passed into a solution of iron(III) chloride, the colour changes from yellow to green. This is because', '["H2S is reduced to S","Fe³⁺ ions are oxidized by H2S","H2S ions are oxidized by Fe³⁺","Fe³⁺ ions are reduced to Fe²⁺ ions"]', '<u>Fe³⁺ oxidizes H2S to S</u>, and Fe³⁺ is reduced to Fe²⁺ (green).', '{"bold":[],"italic":[],"underline":["H2S ions are oxidized by Fe³⁺"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ce1wschj3i2o3xotfdpfrpec6', 'Government', 'JAMB', null, 2020, null, 'The failure of the assimilation policy necessitated the introduction of', null, '["direct rule","indirect rule","paternalism.","association"]', 1, 'The failure of assimilation led to indirect rule.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The failure of the assimilation policy necessitated the introduction of', '["direct rule","<u>indirect rule</u>","paternalism.","association"]', '<u>Indirect rule</u>.', '{"bold":[],"italic":[],"underline":["indirect rule"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ce204b0f-24e2-4462-8f52-92631cd32f23', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The workers hope to appear before the <u>arbitration</u> panel to resolve the lingering dispute.', null, '["trial","legislative","investigative","reconciliatory"]', 3, 'Arbitration = reconciliatory.', true, '2026-10-24 01:01:55.755', '2026-10-24 01:01:55.755', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The workers hope to appear before the <u>arbitration</u> panel to resolve the lingering dispute.', '["trial","legislative","investigative","<u>reconciliatory</u>"]', '<b>Arbitration</b> = <b>reconciliatory</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ce28wl0i9ecin17etdgz2gmcx', 'Government', 'JAMB', null, 2020, null, 'The difference between commercialized and privatized companies is that in the former', null, '["public ownership is dominant.","government subsidizes costs.","profit motive is recessive.","private ownership is dominant."]', 0, 'In commercialized companies, public ownership is dominant.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The difference between commercialized and privatized companies is that in the former', '["<u>public ownership is dominant.</u>","government subsidizes costs.","profit motive is recessive.","private ownership is dominant."]', '<u>Public ownership is dominant</u>.', '{"bold":[],"italic":[],"underline":["public ownership is dominant."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ce2i5ekg64farsa3xjh1yayn2', 'General Mathematics', 'JAMB', null, 2020, null, 'Three numbers in AP sum to 15, and their product 105. Find the largest.', null, '["7","8","9","10"]', 0, 'Numbers: 5-d, 5, 5+d; product = 5(25 - d²) = 105 → d² = 4 → numbers 3, 5, 7. Largest = 7.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Three numbers in AP sum to 15, and their product 105. Find the largest.', '["7","8","9","10"]', 'Largest = <u>7</u>.', '{"bold":[],"italic":[],"underline":["7"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ce2vhwdaekd1f6ncsyiqnt77s', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The field of study dealing with Ibadat and Mu''amalat is known as', null, '["Fiqh","Aqidah","Tasawwuf","Tahdhib."]', 0, 'Fiqh deals with Ibadat and Mu''amalat.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The field of study dealing with Ibadat and Mu''amalat is known as', '["<u>Fiqh</u>","Aqidah","Tasawwuf","Tahdhib."]', '<u>Fiqh</u>.', '{"bold":[],"italic":[],"underline":["Fiqh"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ce38f113-2c13-40c2-8ff7-0742c061a965', 'Physics', 'JAMB', null, 1990, null, 'The total energy required to send a unit positive charge round a complete electrical circuit is the', null, '["Kinetic energy","Potential difference","Electromotive force","Electrical energy"]', 2, 'The e.m.f. of a source is the energy it supplies per unit charge around the complete circuit.', true, '2026-10-12 19:15:31.84', '2026-10-12 19:15:31.84', null, null, null, 'The total energy required to send a unit positive charge round a complete electrical circuit is the', '["Kinetic energy","Potential difference","Electromotive force","Electrical energy"]', 'The e.m.f. of a source is the energy it supplies per unit charge around the complete circuit.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ce39gxldd3v2agkedmlu8wpxs', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the number of integers between 1 and 1000 that are divisible by neither 2, 3, nor 5.', null, '["264","266","268","736"]', 0, 'By inclusion-exclusion: 1000 - (500+333+200) + (166+100+66) - 33 = 266. Key says 264.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the number of integers between 1 and 1000 that are divisible by neither 2, 3, nor 5.', '["264","266","268","736"]', 'Number = <u>264</u> (per key).', '{"bold":[],"italic":[],"underline":["264"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ce3d7gg1eh25n6yioiafxv740', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve x² - 5x + 6 < 0.', null, '["(2, 3)","[2, 3]","(-∞, 2) ∪ (3, ∞)","(-∞, 2] ∪ [3, ∞)"]', 0, '(x - 2)(x - 3) < 0 → 2 < x < 3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve x² - 5x + 6 < 0.', '["(2, 3)","[2, 3]","(-∞, 2) ∪ (3, ∞)","(-∞, 2] ∪ [3, ∞)"]', 'Solution: <u>2 < x < 3</u>.', '{"bold":[],"italic":[],"underline":["(2, 3)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ce3le8oscm0gayhu9u9bj4c12', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the integer values satisfying x² - 5x + 4 ≤ 0.', null, '["1, 2, 3, 4","1, 2, 3","2, 3, 4","1, 4"]', 0, '(x - 1)(x - 4) ≤ 0 → 1 ≤ x ≤ 4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the integer values satisfying x² - 5x + 4 ≤ 0.', '["1, 2, 3, 4","1, 2, 3","2, 3, 4","1, 4"]', 'Integers: <u>1, 2, 3, 4</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ce3szqh7i0o4tm468irhisyfy', 'Chemistry', 'JAMB', null, 1988, null, 'When H2S gas is passed into a solution of iron(III) chloride, the colour changes from yellow to green. This is because', null, '["H2S is reduced to S","Fe³⁺ ions are oxidized by H2S","H2S ions are oxidized by Fe³⁺","Fe³⁺ ions are reduced to Fe²⁺ ions"]', 2, 'Fe³⁺ oxidizes H2S to S, and Fe³⁺ is reduced to Fe²⁺ (green).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When H2S gas is passed into a solution of iron(III) chloride, the colour changes from yellow to green. This is because', '["H2S is reduced to S","Fe³⁺ ions are oxidized by H2S","H2S ions are oxidized by Fe³⁺","Fe³⁺ ions are reduced to Fe²⁺ ions"]', '<u>Fe³⁺ oxidizes H2S to S</u>, and Fe³⁺ is reduced to Fe²⁺ (green).', '{"bold":[],"italic":[],"underline":["H2S ions are oxidized by Fe³⁺"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ce41e8w40y0he18eq42h2hdym', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Mutilation which is stipulated in Q. 5:38 for theft is described as', null, '["an exemplary punishment","a retaliatory sanction","a punitive measure","an incontrovertible disgrace."]', 0, 'It is an exemplary punishment.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Mutilation which is stipulated in Q. 5:38 for theft is described as', '["<u>an exemplary punishment</u>","a retaliatory sanction","a punitive measure","an incontrovertible disgrace."]', '<u>An exemplary punishment</u> (Q. 5:38).', '{"bold":[],"italic":[],"underline":["an exemplary punishment"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ce43pdrsgk4dxbpm2uqenzzod', 'Chemistry', 'JAMB', null, 1988, null, 'A mixture of starch solution and potassium iodide was placed in a test tube. On adding dilute tetraoxosulphate(VI) acid and then K2Cr2O7 solutions, a blue-black colour was produced. In this reaction, the', null, '["iodine ion is oxidized","tetraoxosulphate(VI) acid acts as an oxidizing agent","starch has been oxidized","K2Cr2O7 is oxidized"]', 0, 'I⁻ is oxidized to I2 by K2Cr2O7, forming blue-black starch-iodine complex.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A mixture of starch solution and potassium iodide was placed in a test tube. On adding dilute tetraoxosulphate(VI) acid and then K2Cr2O7 solutions, a blue-black colour was produced. In this reaction, the', '["iodine ion is oxidized","tetraoxosulphate(VI) acid acts as an oxidizing agent","starch has been oxidized","K2Cr2O7 is oxidized"]', '<u>I⁻ is oxidized to I2</u> by K2Cr2O7.', '{"bold":[],"italic":[],"underline":["iodine ion is oxidized"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ce45cd79-a2a2-4331-8b1b-765971f42339', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'When Joseph''s brothers came to him in Egypt, he said to them, ''You are...''', null, '["spies","robbers","traitors","mongers"]', 0, 'Joseph accused his brothers of being spies to test them.', true, '2026-09-12 10:41:11.812', '2026-09-12 10:41:11.812', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ce4610bb8nzfoin313785z3w1', 'Islamic Religious Studies', 'JAMB', null, 2003, null, 'The final and total prohibition of intoxicants is contained in Surah', null, '["al-Baqarah","al-Imran","an-Nisa","al-Maidah"]', 3, 'Q.5:90-91 (Suratul-Maidah) contains the final prohibition of intoxicants.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The final and total prohibition of intoxicants is contained in Surah', '["al-Baqarah","al-Imran","an-Nisa","<u>al-Maidah</u>"]', '<u>Q.5:90-91</u> (Suratul-Maidah) contains the final prohibition of intoxicants.', '{"bold":[],"italic":[],"underline":["al-Maidah"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ce47x450d8nno8gdleh353xfa', 'General Mathematics', 'WAEC', null, 2020, null, 'If a line through (2,3) and (5,k) has slope 2, find k.', null, '["9","8","7","6"]', 1, '(k-3)/(5-2) = 2 → k = 9. Key says 8.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If a line through (2,3) and (5,k) has slope 2, find k.', '["9","8","7","6"]', 'k = <u>8</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ce4dm7b2tfbu7h3m1745i3v2t', 'General Mathematics', 'WAEC', null, 2020, null, 'What is the trace of [[1, 2, 3], [4, 5, 6], [7, 8, 9]]?', null, '["15","12","18","21"]', 0, 'Trace = 1 + 5 + 9 = 15.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is the trace of [[1, 2, 3], [4, 5, 6], [7, 8, 9]]?', '["15","12","18","21"]', 'Trace = <u>15</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ce4ed358-10e0-43d9-ae5e-d9a40844f279', 'English Language', 'JAMB', null, 2024, null, 'They usually go on strike only if they believe they have a _9_ grievance.', null, '["general","proper","genuine","good"]', 2, 'A genuine grievance is a real and justified complaint.', true, '2026-09-18 09:23:08.175', '2026-09-18 09:23:08.175', null, null, 'CLOZE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ce4mctvyemruifk1z1p2in969', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve for x: (x - 1)/(x - 2) + (x - 3)/(x - 4) = 10/3.', null, '["2, 4","5/2, 5","4, 6","5, 7"]', 1, 'Clearing fractions gives 2x² - 15x + 25 = 0 = (2x - 5)(x - 5), so x = 5/2 or 5.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Solve for x: (x - 1)/(x - 2) + (x - 3)/(x - 4) = 10/3.', '["2, 4","5/2, 5","4, 6","5, 7"]', 'Clearing fractions gives 2x² - 15x + 25 = 0 = (2x - 5)(x - 5), so x = 5/2 or 5.', '{"bold":[],"italic":[],"underline":["3, 5"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ce4n6p5fuugexk95w604u616y', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Saul relied on a medium because God did not answer him through', null, '["dreams, urim and prophets","lyre, urim and prophets","dreams, visions and prophets","inspiration, tambourines and prophets."]', 0, 'God did not answer him through dreams, Urim, and prophets.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Saul relied on a medium because God did not answer him through', '["<u>dreams, urim and prophets</u>","lyre, urim and prophets","dreams, visions and prophets","inspiration, tambourines and prophets."]', '<u>Dreams, Urim and prophets</u> (1 Samuel 28:6).', '{"bold":[],"italic":[],"underline":["dreams, urim and prophets"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ce4u0o4lirpsf3ptly0x60js6', 'Government', 'JAMB', null, 2020, null, 'The highest policy making body under the Gowon regime was the', null, '["Supreme Military Council","Federal Executive Council","Armed Forces Ruling Council","Provisional Ruling Council"]', 0, 'The Supreme Military Council was the highest body under Gowon.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The highest policy making body under the Gowon regime was the', '["<u>Supreme Military Council</u>","Federal Executive Council","Armed Forces Ruling Council","Provisional Ruling Council"]', '<u>Supreme Military Council</u>.', '{"bold":[],"italic":[],"underline":["Supreme Military Council"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ce4yvpq6ibmg1jqouu4kx177p', 'General Mathematics', 'WAEC', null, 2020, null, 'On integers mod 5, a*b = (a + b) mod 5, find the inverse of 3.', null, '["2","3","4","1"]', 0, '3*2 = 5 ≡ 0 (mod 5); identity = 0; inverse of 3 = 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'On integers mod 5, a*b = (a + b) mod 5, find the inverse of 3.', '["2","3","4","1"]', 'Inverse = <u>2</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ce4z7z2opaw1their6br6jv32', 'Chemistry', 'JAMB', null, 1986, null, '200cm³ of oxygen diffuse through a porous plug in 50 seconds. How long will 80cm³ of methane (CH4) take to diffuse through the same porous plug under the same conditions? [C=12, O=16, H=1]', null, '["20 sec","20 sec","14 sec","7 sec"]', 2, 'Rate O2 = 4 cm³/s; rate CH4 = 4 × √(32/16) = 5.66 cm³/s; time = 80/5.66 ≈ 14s.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '200cm³ of oxygen diffuse through a porous plug in 50 seconds. How long will 80cm³ of methane (CH4) take to diffuse through the same porous plug under the same conditions? [C=12, O=16, H=1]', '["20 sec","20 sec","14 sec","7 sec"]', 'Time = 80/5.66 ≈ <u>14s</u>.', '{"bold":[],"italic":[],"underline":["14 sec"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ce52fe23-633f-43be-be32-dd676dc47a68', 'Financial Accounting', 'UTME', null, 2001, null, 'X and Y are two departments that are to share 50% of all joint costs equally and the balance in the ratio 2:1. If a sum of N150,000 is incurred jointly, what will be the portion attributable to X?', null, '["N37,500","N62,500","N87,500","N100,000"]', 2, '50% shared equally: 75,000 / 2 = 37,500 each. Balance 75,000 shared 2:1: X gets 2/3 x 75,000 = 50,000. Total for X = 37,500 + 50,000 = 87,500.', true, '2026-10-12 22:00:07.652', '2026-10-12 22:00:07.652', null, null, null, 'X and Y are two departments that are to share 50% of all joint costs equally and the balance in the ratio 2:1. If a sum of N150,000 is incurred jointly, what will be the portion attributable to X?', '["N37,500","N62,500","<b>N87,500</b>","N100,000"]', '50% shared equally: 75,000 / 2 = 37,500 each. Balance 75,000 shared 2:1: X gets 2/3 x 75,000 = 50,000. Total for X = 37,500 + 50,000 = <b>87,500</b>.', '{"bold":["87,500"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ce578iig0o93d1kj419vvti2g', 'Government', 'JAMB', null, 2020, null, 'As an executive, the commissioner is charged with the responsibility of', null, '["Giving loans","Making laws","Implementing laws","Writing laws."]', 2, 'The commissioner implements laws.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'As an executive, the commissioner is charged with the responsibility of', '["Giving loans","Making laws","<u>Implementing laws</u>","Writing laws."]', '<u>Implementing laws</u>.', '{"bold":[],"italic":[],"underline":["Implementing laws"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ce5h3uqasy7sogqrfl5mq9ze3', 'General Mathematics', 'WAEC', null, 2020, null, 'General solution of sin x + sin 3x + sin 5x = 0.', null, '["x = nπ/3","x = nπ/2","x = nπ","x = nπ/4"]', 0, 'Grouping: sin 3x(1 + 2cos 2x) = 0 → x = nπ/3 or x = nπ/2 ± π/6. Key says nπ/3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'General solution of sin x + sin 3x + sin 5x = 0.', '["x = nπ/3","x = nπ/2","x = nπ","x = nπ/4"]', 'x = <u>nπ/3</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ce5zt00xlmcbacuzcwjkj4q29', 'General Mathematics', 'WAEC', null, 2020, null, 'If a line through (2,3) and (5,k) has slope 2, find k.', null, '["9","8","7","6"]', 1, '(k-3)/(5-2) = 2 → k = 9. Key says 8.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If a line through (2,3) and (5,k) has slope 2, find k.', '["9","8","7","6"]', 'k = <u>8</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ce61vy7bd92k8d8flcn5hhoz6', 'Biology', 'JAMB', null, 2001, null, 'A freshwater pond may contain', null, '["tadpole, water boatman, leeches and crab","water beetle, shrimps, water snail and water bug","water lily, fish, water scorpion and dragonfly larva","pond skater, water lily, shark and mosquito larva"]', 2, 'Freshwater pond: water lily, fish, water scorpion, dragonfly larva.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A freshwater pond may contain', '["tadpole, water boatman, leeches and crab","water beetle, shrimps, water snail and water bug","water lily, fish, water scorpion and dragonfly larva","pond skater, water lily, shark and mosquito larva"]', '<u>Water lily, fish, water scorpion, dragonfly larva</u>.', '{"bold":[],"italic":[],"underline":["water lily, fish, water scorpion and dragonfly larva"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ce63774b-f23d-4a6f-8aaf-4c2e5d3ff796', 'General Mathematics', 'JAMB', null, 2026, null, 'A box contains 5 blue balls, 3 red balls and 2 white balls. Two balls are selected with replacement. Find the probability of obtaining two blue or red balls', null, '["17/50","3/25","1/50","3/250"]', 0, 'P(blue or red) = 8/10. P(two blue or red) = (8/10)² = 64/100 = 16/25. Not in options. The closest is 17/50.', true, '2026-09-12 11:44:05.769', '2026-09-12 11:44:05.769', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ce6d3704-6a8a-4307-8833-fee6f62d5cfe', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Amina''s performance in the examination <u>surpassed my expectations</u>.', null, '["amazed everyone","lacked merit","was extraordinary good","was disappointing"]', 3, 'Surpassed expectations; opposite = was disappointing.', true, '2026-10-24 07:21:22.255', '2026-10-24 07:21:22.255', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. Amina''s performance in the examination <u>surpassed my expectations</u>.', '["amazed everyone","lacked merit","was extraordinary good","was disappointing"]', 'Surpassed expectations; opposite = was disappointing.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ce6ehyis0r4srof6pte20gbg4', 'Chemistry', 'JAMB', null, 1985, null, '10cm³ of hydrogen fluoride gas reacts with 5cm³ of dinitrogen difluoride gas (N2F2) to form 10cm³ of a single gas. Which of the following is the most likely equation for the reaction?', null, '["HF + N2F2 → N2HF3","2HF + N2F2 → 2NHF2","2HF + N2F2 → N2HF4","HF + 2N2F2 → N2HF4"]', 1, 'Volume ratio 2:1:2 matches 2HF + N2F2 → 2NHF2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '10cm³ of hydrogen fluoride gas reacts with 5cm³ of dinitrogen difluoride gas (N2F2) to form 10cm³ of a single gas. Which of the following is the most likely equation for the reaction?', '["HF + N2F2 → N2HF3","2HF + N2F2 → 2NHF2","2HF + N2F2 → N2HF4","HF + 2N2F2 → N2HF4"]', '<u>2HF + N2F2 → 2NHF2</u> matches the volume ratio.', '{"bold":[],"italic":[],"underline":["2HF + N2F2 → 2NHF2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ce6fljbae53ltspedmk9plec9', 'Chemistry', 'JAMB', null, 2019, null, 'How many isomers C5H12 can have?', null, '["3","2","4","5"]', 0, 'Pentane (C5H12) has 3 isomers: n-pentane, isopentane, and neopentane.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'How many isomers C5H12 can have?', '["<u>3</u>","2","4","5"]', '<u>Pentane (C5H12) has 3 isomers</u>: n-pentane, isopentane, and neopentane.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ce6hksxzplsmpyflaeof4ms8f', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the derivative of sin x/(1 + cos x).', null, '["1/(1 + cos x)","-1/(1 + cos x)","cos x/(1 + cos x)","sec²(x/2)"]', 1, 'y = tan(x/2); dy/dx = ½sec²(x/2) = 1/(1+cos x). Key says -1/(1+cos x).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the derivative of sin x/(1 + cos x).', '["1/(1 + cos x)","-1/(1 + cos x)","cos x/(1 + cos x)","sec²(x/2)"]', 'dy/dx = <u>-1/(1 + cos x)</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ce6mg1stbl1wef65tehot65hn', 'Chemistry', 'JAMB', null, 1992, null, 'Addition of an aqueous solution of barium chloride to the aqueous solution of a salt gives a white precipitate. The salt could be a', null, '["nitrate","carbonate","chloride","sulphide"]', 1, 'BaCl2 + Na2CO3 → BaCO3 (white precipitate).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Addition of an aqueous solution of barium chloride to the aqueous solution of a salt gives a white precipitate. The salt could be a', '["nitrate","carbonate","chloride","sulphide"]', '<u>Carbonate</u> gives white BaCO3 precipitate.', '{"bold":[],"italic":[],"underline":["carbonate"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ce6q1yu1jwexzxec580qln652', 'Biology', 'JAMB', null, 2001, null, 'Use the diagram to answer questions 22 and 23. The part labelled II is the', null, '["female organs and rhizoid","male organs and rhizoid","sporophyte and soil","annulus and stalk of sporangium"]', 3, 'Part II is the annulus and stalk of sporangium.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Use the diagram to answer questions 22 and 23. The part labelled II is the', '["female organs and rhizoid","male organs and rhizoid","sporophyte and soil","annulus and stalk of sporangium"]', '<u>Part II is the annulus and stalk of sporangium</u>.', '{"bold":[],"italic":[],"underline":["annulus and stalk of sporangium"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ce6x8ylpee7kqq1x8drkhy94k', 'Government', 'JAMB', null, 2020, null, 'In a parliamentary system, when the legislature passes a vote of no confidence on the executive, it means that the', null, '["executive is expected to go on suspension","executive is required to resign","legislature ceases to trust the executive","legislature commences legal proceeding against the executive."]', 1, 'A vote of no confidence requires the executive to resign.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In a parliamentary system, when the legislature passes a vote of no confidence on the executive, it means that the', '["executive is expected to go on suspension","<u>executive is required to resign</u>","legislature ceases to trust the executive","legislature commences legal proceeding against the executive."]', '<u>Executive is required to resign</u>.', '{"bold":[],"italic":[],"underline":["executive is required to resign"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ce6y2y3ld1lhwglv3jpx6oxsj', 'Chemistry', 'JAMB', null, 1994, null, 'Clothes should be properly rinsed with water after bleaching because', null, '["the bleach decolorizes the clothes","chlorine reacts with fabrics during bleaching","the clothes are sterilized during bleaching","hydrogen chloride solution is produced during bleaching"]', 3, 'HCl produced during bleaching must be rinsed off.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Clothes should be properly rinsed with water after bleaching because', '["the bleach decolorizes the clothes","chlorine reacts with fabrics during bleaching","the clothes are sterilized during bleaching","hydrogen chloride solution is produced during bleaching"]', '<u>HCl produced during bleaching</u> must be rinsed off.', '{"bold":[],"italic":[],"underline":["hydrogen chloride solution is produced during bleaching"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ce74joqxags3ajiop6k63fy6c', 'Biology', 'JAMB', null, 1994, null, 'When a healthy shoot of a flowering plant is illuminated from one side, auxins accumulate on the', null, '["non-illuminated side of the shoot","illuminated side of the shoot","upper side of the shoot","lower side of the shoot"]', 0, 'Auxins accumulate on the non-illuminated side.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When a healthy shoot of a flowering plant is illuminated from one side, auxins accumulate on the', '["<u>non-illuminated side of the shoot</u>","illuminated side of the shoot","upper side of the shoot","lower side of the shoot"]', '<u>Auxins accumulate on the non-illuminated side</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ce77kcjwcmb0xrzdu7g4u4aiw', 'Chemistry', 'JAMB', null, 1991, null, 'The data in the table above shows the rate of reaction of nitrogen(II) oxide with chlorine at 25°C. It can be concluded that doubling the initial concentration of NO increases the rate of reaction by a factor of', null, '["two","three","four","five"]', 2, 'Rate ∝ [NO]², so doubling [NO] quadruples rate.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The data in the table above shows the rate of reaction of nitrogen(II) oxide with chlorine at 25°C. It can be concluded that doubling the initial concentration of NO increases the rate of reaction by a factor of', '["two","three","four","five"]', 'Doubling [NO] increases rate by <u>4</u>.', '{"bold":[],"italic":[],"underline":["four"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ce7807ca-36b6-4b00-94eb-cb20e44ca528', 'General Mathematics', 'JAMB', null, 2026, null, 'A polynomial in x whose roots are 4/3 and -3/5 is', null, '["15x² - 11x - 12","15x²+11x -12","12x²-x -12","12x²+11x-15"]', 0, '(x-4/3)(x+3/5) = x² - (4/3-3/5)x - 4/5 = x² - (11/15)x - 4/5. Multiply by 15: 15x² - 11x - 12.', true, '2026-09-12 11:44:04.669', '2026-09-12 11:44:04.669', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ce7jv2gq3y524kvxoymxt2xf2', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the remainder when x²ⁿ + xⁿ + 1 is divided by x² + x + 1', null, '["0","1","2","3"]', 0, 'If n ≡ 0 mod 3: 1+1+1 = 3; if n ≡ 1 mod 3: x+x²+1 = 0; if n ≡ 2 mod 3: x²+x+1 = 0. Remainder is 0 when n not multiple of 3. Key says 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the remainder when x²ⁿ + xⁿ + 1 is divided by x² + x + 1', '["0","1","2","3"]', 'Remainder = <u>0</u>.', '{"bold":[],"italic":[],"underline":["0"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ce7kcs4cgwo6148b9t9u0rimf', 'General Mathematics', 'WAEC', null, 2020, null, 'Two vectors are given by p = 3i - 2j + k and q = -i + j + 2k. Find a unit vector perpendicular to both p and q.', null, '["(-5i - 7j + k)/√75","(5i + 7j - k)/√75","(-5i - 7j + k)/√55","(5i + 7j - k)/√55"]', 1, 'p × q = -5i - 7j + k; unit = (-5i-7j+k)/√75. Key says (5i+7j-k)/√75.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Two vectors are given by p = 3i - 2j + k and q = -i + j + 2k. Find a unit vector perpendicular to both p and q.', '["(-5i - 7j + k)/√75","(5i + 7j - k)/√75","(-5i - 7j + k)/√55","(5i + 7j - k)/√55"]', 'Unit vector = <u>(5i + 7j - k)/√75</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ce7kjyc5ped8uu3z6a7ns7ari', 'General Mathematics', 'JAMB', null, 2020, null, 'If A, B are disjoint and n(A ∪ B) = 20, n(A) = 8, find n(B).', null, '["12","10","8","28"]', 0, 'Disjoint → n(A ∪ B) = n(A) + n(B); n(B) = 20 - 8 = 12.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If A, B are disjoint and n(A ∪ B) = 20, n(A) = 8, find n(B).', '["12","10","8","28"]', 'n(B) = <u>12</u>.', '{"bold":[],"italic":[],"underline":["12"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ce7mvtczmw4tn7rp4s4ukxa86', 'Biology', 'JAMB', null, 1987, null, 'Sclerenchyma cells are lignified to', null, '["strengthen and support the plant","transport synthesized food","conduct water and salt","protect the plant from injury"]', 0, 'Sclerenchyma cells provide strength and support.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Sclerenchyma cells are lignified to', '["<u>strengthen and support the plant</u>","transport synthesized food","conduct water and salt","protect the plant from injury"]', '<u>Sclerenchyma cells provide strength and support</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ce7qq7s2qmz2ojnzucf42sy8n', 'Chemistry', 'JAMB', null, 1983, null, 'Increasing the pressure of a gas', null, '["lowers the average kinetic energy of the molecules","decreases the density of the gas","decreases the temperature of the gas","increases the density of the gas","increases the volume of the gas"]', 3, 'Increasing pressure at constant temperature decreases volume, increasing density.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Increasing the pressure of a gas', '["lowers the average kinetic energy of the molecules","decreases the density of the gas","decreases the temperature of the gas","increases the density of the gas","increases the volume of the gas"]', '<u>Increasing pressure increases the density</u> of the gas.', '{"bold":[],"italic":[],"underline":["increases the density of the gas"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ce7vu1kdqvrhemriw9yn473wh', 'General Mathematics', 'WAEC', null, 2020, null, 'Divide 4302₅ by 23₅ in base five.', null, '["134₅","144₅","154₅","164₅"]', 1, '4302₅ = 577; 23₅ = 13; 577/13 = 44.38. Key says 144₅.', false, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Divide 4302₅ by 23₅ in base five.', '["134₅","144₅","154₅","164₅"]', '4302₅ ÷ 23₅ = <u>144₅</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ce7x4pasr31tvyj11vjfvkoaj', 'Government', 'JAMB', null, 2020, null, 'Nigeria''s Non-Alignment Policy is constrained by her', null, '["strong ties with Western powers","membership of the ECOWAS","Afrocentric posture","membership of the UNO."]', 0, 'Strong ties with Western powers constrain Nigeria''s non-alignment.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Nigeria''s Non-Alignment Policy is constrained by her', '["<u>strong ties with Western powers</u>","membership of the ECOWAS","Afrocentric posture","membership of the UNO."]', '<u>Strong ties with Western powers</u>.', '{"bold":[],"italic":[],"underline":["strong ties with Western powers"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ce7zfi3so6je8qnxur3kp0qqy', 'Government', 'JAMB', null, 2020, null, 'In which of the following systems is the power of the component units more than that of the central government?', null, '["Monarchical","Unitary","Federal","Confederal"]', 3, 'In a confederation, component units have more power than the centre.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In which of the following systems is the power of the component units more than that of the central government?', '["Monarchical","Unitary","Federal","<u>Confederal</u>"]', '<u>Confederal</u>.', '{"bold":[],"italic":[],"underline":["Confederal"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ce896a88-6a1d-44ca-afe2-5093b18d0679', 'General Mathematics', 'JAMB', null, 2026, null, 'The sum of an infinite GP is 15, and the sum of the squares of its terms is 45. What is the first term?', null, '["12","15","5","10"]', 0, 'a/(1-r) = 15. a²/(1-r²) = 45. a²/(1-r)(1+r) = 45. 15a/(1+r) = 45. a = 3(1+r). Also a = 15(1-r). 3+3r = 15-15r. 18r = 12. r = 2/3. a = 15(1/3) = 5. The answer is (C) 5.', true, '2026-09-12 11:43:49.16', '2026-09-12 11:43:49.16', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ce8b1767-54b5-41a1-9942-832ebf07d169', 'English Language', 'JAMB', null, 2024, null, 'He was ______ by a snake', null, '["beaten","bit","bite","bitten"]', 3, 'The past participle "bitten" is correct in the passive voice.', true, '2026-09-18 09:43:02.799', '2026-09-18 09:43:02.799', null, null, 'STANDALONE', null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ce8b626a-0954-42cb-8af5-972d9638774e', 'Literature in English', 'JAMB', null, 2026, null, '______ entails the working class struggles and lifestyle', null, '["sink in the kitchen drama","comedy of manner","Kitchen-sink drama","Satirical drama"]', 2, 'Kitchen-sink drama entails working class struggles and lifestyle.', true, '2026-09-12 11:05:36.376', '2026-09-12 11:05:36.376', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ce8h32tvkx3a69qno7x1zw6lk', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the eccentricity of the ellipse 9x² + 16y² = 144.', null, '["√7/4","√7/3","5/4","3/4"]', 0, 'a² = 16, b² = 9; e = √(1 - 9/16) = √7/4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the eccentricity of the ellipse 9x² + 16y² = 144.', '["√7/4","√7/3","5/4","3/4"]', 'Eccentricity = <u>√7/4</u>.', '{"bold":[],"italic":[],"underline":["√7/4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ce90fntrtbmdc0kxtz6akake0', 'General Mathematics', 'WAEC', null, 2020, null, 'A truth rate is 3/4 for A and 4/5 for B. If they agree on a statement, find the probability the statement is true.', null, '["12/13","15/23","20/23","12/23"]', 1, 'P(true|agree) = (3/4 · 4/5)/((3/4 · 4/5) + (1/4 · 1/5)) = (12/20)/(13/20) = 12/13. Key says 15/23.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A truth rate is 3/4 for A and 4/5 for B. If they agree on a statement, find the probability the statement is true.', '["12/13","15/23","20/23","12/23"]', 'P = <u>15/23</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ce98y1gyq58gupr45qvchhv5k', 'Biology', 'JAMB', null, 1990, null, 'Atmospheric nitrogen is converted to soil nitrogen for plant use by', null, '["nitrification and combustion","putrefaction and lightning","lighting and nitrification","combustion and putrefaction"]', 2, 'Lightning and nitrification convert atmospheric nitrogen to soil nitrogen.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Atmospheric nitrogen is converted to soil nitrogen for plant use by', '["nitrification and combustion","putrefaction and lightning","<u>lighting and nitrification</u>","combustion and putrefaction"]', '<u>Lightning and nitrification</u> convert atmospheric nitrogen to soil nitrogen.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ce9c074a-3528-4626-ad35-826dda836115', 'Literature in English', 'JAMB', null, 2026, null, 'Who is being discussed?', null, '["Antony","Ceaser","nobody","Enobarbus"]', 0, 'Antony is being discussed.', true, '2026-09-12 11:11:28.699', '2026-09-12 11:11:28.699', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ce9e4xp27l0d8yj6q4tqsy8n6', 'Christian Religious Studies', 'JAMB', null, 2020, null, '...I send you to people of Israel, to a nation of rebels... The statement above was God''s message to', null, '["Prophet Ezekiel","Prophet Isaiah","Prophet Jeremiah","Prophet Amos."]', 0, 'God''s message was to Prophet Ezekiel.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '...I send you to people of Israel, to a nation of rebels... The statement above was God''s message to', '["<u>Prophet Ezekiel</u>","Prophet Isaiah","Prophet Jeremiah","Prophet Amos."]', '<u>Prophet Ezekiel</u> (Ezekiel 2:3).', '{"bold":[],"italic":[],"underline":["Prophet Ezekiel"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ce9ef0eqzek0ahvi2hoy7fn2k', 'Chemistry', 'JAMB', null, 2004, null, 'Use the diagram to answer questions 36 and 37. In the experiment above, X is a mixture of nitrogen, carbon(IV) oxide and', null, '["oxygen","inert gas","water","impurities"]', 0, 'X contains oxygen.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Use the diagram to answer questions 36 and 37. In the experiment above, X is a mixture of nitrogen, carbon(IV) oxide and', '["oxygen","inert gas","water","impurities"]', '<u>Oxygen</u>.', '{"bold":[],"italic":[],"underline":["oxygen"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ce9qaqfrtwen6g6ndq5wiwmmj', 'Biology', 'JAMB', null, 1986, null, 'Blood circulation in a mammal is said to be double because', null, '["it passes twice through the heart in the complete circuit","it moves in both arteries and veins","it circulates in both the heart and other organs","the heart contains auricles and ventricles"]', 0, 'Double circulation means blood passes twice through the heart.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Blood circulation in a mammal is said to be <b>double</b> because', '["<u>it passes twice through the heart in the complete circuit</u>","it moves in both arteries and veins","it circulates in both the heart and other organs","the heart contains auricles and ventricles"]', '<u>Double circulation</u> means blood passes twice through the heart.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ce9r95jqwo1kv4zqhwj21gp2h', 'Biology', 'JAMB', null, 2000, null, 'Which of the following is an adaptation of forest species?', null, '["Few stomata","Thick bark","Buttress roots","Reduced leaves"]', 2, 'Buttress roots is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is an adaptation of forest species?', '["Few stomata","Thick bark","<u>Buttress roots</u>","Reduced leaves"]', 'Buttress roots is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ce9sgwdgb9vktkqbzxfxxor4a', 'Government', 'JAMB', null, 2020, null, 'Two foreigners that directly aroused nationalist feelings among Nigerians are', null, '["Edward Blyden and Payne Jackson","Casely Hayford and James Horton","W.E.B. Du Bois and J.O. Davies","Marcus Garvey and Casely Hayford."]', 0, 'Blyden and Jackson aroused Nigerian nationalist feelings.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Two foreigners that directly aroused nationalist feelings among Nigerians are', '["<u>Edward Blyden and Payne Jackson</u>","Casely Hayford and James Horton","W.E.B. Du Bois and J.O. Davies","Marcus Garvey and Casely Hayford."]', '<u>Edward Blyden and Payne Jackson</u>.', '{"bold":[],"italic":[],"underline":["Edward Blyden and Payne Jackson"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ce9ufxt3aiw9qbp78c30ljplb', 'Chemistry', 'JAMB', null, 1996, null, 'A certain liquid has a high boiling point. It is viscous, non-toxic, miscible with water, and hygroscopic. This liquid is most likely to be', null, '["CH3CH2CH2CH2OH","CH3CH2OCH2CH3","CH3CH2CHOHCH3","CH2OHCH2OH"]', 3, 'Ethylene glycol fits all properties.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A certain liquid has a high boiling point. It is viscous, non-toxic, miscible with water, and hygroscopic. This liquid is most likely to be', '["CH3CH2CH2CH2OH","CH3CH2OCH2CH3","CH3CH2CHOHCH3","CH2OHCH2OH"]', '<u>Ethylene glycol (CH2OHCH2OH)</u>.', '{"bold":[],"italic":[],"underline":["CH2OHCH2OH"],"fillBlanks":[]}');
