insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ceam2vzjku4rpool9dr66njjn', 'English Language', 'JAMB', null, 2020, null, 'Two men were caught with the missing car, but neither of them had admitted _____ it.', null, '["to steal it","to have stolen","stole","stealing"]', 3, 'Admit + gerund → "admitted stealing".', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Two men were caught with the missing car, but neither of them had admitted _____ it.', '["to steal it","to have stolen","stole","stealing"]', 'Admit + gerund → <u>admitted stealing</u>.', '{"bold":[],"italic":[],"underline":["stealing"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ceardncz47mycv8k8hl4g0e87', 'Chemistry', 'JAMB', null, 1991, null, 'How many structural isomers can be written for the alkyl bromide C2H5Br?', null, '["3","4","1","8"]', 2, 'C2H5Br has only one structural isomer (bromoethane).', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'How many structural isomers can be written for the alkyl bromide C2H5Br?', '["3","4","1","8"]', 'C2H5Br has only one structural isomer (bromoethane).', '{"bold":[],"italic":[],"underline":["6"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ceasrxrt5ea9nhl6xxo9lw57g', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the remainder when the polynomial x⁸¹ + x⁴⁹ + x²⁵ + x⁹ + x is divided by x³ - x.', null, '["5x","4x","3x","0"]', 1, 'Since x³ = x, each odd power reduces; remainder = 5x. Key says 4x.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the remainder when the polynomial x⁸¹ + x⁴⁹ + x²⁵ + x⁹ + x is divided by x³ - x.', '["5x","4x","3x","0"]', 'Remainder = <u>4x</u> (per key).', null);
