insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cec8xbw9s15oz92d47szuty9m', 'Chemistry', 'JAMB', null, 2004, null, 'A chemical reaction is always associated with', null, '["a change in the nature of the reactants","the formation of new substances","a change in the volume of the reactants","an increase in the composition of one of the substances"]', 1, 'Chemical reactions form new substances.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A chemical reaction is always associated with', '["a change in the nature of the reactants","the formation of new substances","a change in the volume of the reactants","an increase in the composition of one of the substances"]', '<u>Formation of new substances</u>.', '{"bold":[],"italic":[],"underline":["the formation of new substances"],"fillBlanks":[]}');
