insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cecb8zz2ndi74k9rbvur7pcu8', 'General Mathematics', 'JAMB', null, 2020, null, 'Find 47 × 36 (mod 8).', null, '["4","5","6","7"]', 0, '47 mod 8 = 7; 36 mod 8 = 4; 7×4 = 28 ≡ 4 mod 8.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find 47 × 36 (mod 8).', '["4","5","6","7"]', '47×36 ≡ 7×4 = 28 ≡ <u>4</u> mod 8.', '{"bold":[],"italic":[],"underline":["4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ceccda7qfp4gsakuftdpuvjje', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Which of the following Prophets, according to the Qur''an, lived for not less than nine hundred and fifty years?', null, '["Adam","Nuh","Ibrahim","Musa"]', 1, 'Prophet Nuh lived for 950 years.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following Prophets, according to the Qur''an, lived for not less than nine hundred and fifty years?', '["Adam","<u>Nuh</u>","Ibrahim","Musa"]', '<u>Nuh</u> (Q. 29:14).', '{"bold":[],"italic":[],"underline":["Nuh"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ceclm1btq8hpo5xvqdrw10lrj', 'Biology', 'JAMB', null, 2000, null, 'Which of the following features are all associated with <b>monocots</b>?', null, '["Fibrous root system, branched network of veins and one seed leaf","Fibrous root system, two seed leaves and floral parts in threes","One seed leaf, petals in threes or groups of threes and parallel venation of leaves","One seed leaf, net-veined leaves and petals in three or multiples of three"]', 2, 'Monocots: one seed leaf, floral parts in threes, parallel venation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following features are all associated with <b>monocots</b>?', '["Fibrous root system, branched network of veins and one seed leaf","Fibrous root system, two seed leaves and floral parts in threes","One seed leaf, petals in threes or groups of threes and parallel venation of leaves","One seed leaf, net-veined leaves and petals in three or multiples of three"]', '<u>One seed leaf, floral parts in threes, parallel venation</u>.', '{"bold":["monocots"],"italic":[],"underline":["One seed leaf, petals in threes or groups of threes and parallel venation of leaves"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cecrikwke0eplysanezvs1gfa', 'Chemistry', 'JAMB', null, 1999, null, '56.00cm³ of a gas at s.t.p weighed 0.11g. What is the vapour density of the gas?', null, '["11.00","22.00","33.00","44.00 [Molar volume of a gas at s.t.p = 22.4 dm³]"]', 1, 'Moles = 0.056/22.4 = 0.0025; Mr = 0.11/0.0025 = 44; VD = 44/2 = 22.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '56.00cm³ of a gas at s.t.p weighed 0.11g. What is the vapour density of the gas?', '["11.00","22.00","33.00","44.00"]', 'VD = <u>22.00</u>.', '{"bold":[],"italic":[],"underline":["22.00"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cecsoi0df5cegnvy21n7l9hp5', 'Christian Religious Studies', 'JAMB', null, 2020, null, '...The fathers have eaten sour grapes, and the children''s teeth are set on edge... The parable above in the land of Israel means that', null, '["parents are punished for the sins of their children","children are punished for the sins of their parents","parents are punished for the sins of their grandparents","great grandchildren are punished for the sins of their forefathers."]', 1, 'The parable means children are punished for the sins of their parents.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '...The fathers have eaten sour grapes, and the children''s teeth are set on edge... The parable above in the land of Israel means that', '["parents are punished for the sins of their children","<u>children are punished for the sins of their parents</u>","parents are punished for the sins of their grandparents","great grandchildren are punished for the sins of their forefathers."]', '<u>Children are punished for the sins of their parents</u>.', '{"bold":[],"italic":[],"underline":["children are punished for the sins of their parents"],"fillBlanks":[]}');
