insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ced2wipq781d9l9zxq3f9hse1', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'The appointment of deacons became necessary because of the complaint by the', null, '["Pharisees","Sadducees","Gentile converts","Hellenists."]', 3, 'The Hellenists complained.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The appointment of deacons became necessary because of the complaint by the', '["Pharisees","Sadducees","Gentile converts","<u>Hellenists.</u>"]', '<u>Hellenists</u> (Acts 6:1).', '{"bold":[],"italic":[],"underline":["Hellenists."],"fillBlanks":[]}');
