insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cedmf15ps21zj3pgs74bmqj9m', 'General Mathematics', 'JAMB', null, 2020, null, 'If α² + β² = 25 and α + β = 7, find αβ.', null, '["10","11","12","13"]', 2, 'α² + β² = (α+β)² - 2αβ → 25 = 49 - 2αβ → 2αβ = 24 → αβ = 12.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If α² + β² = 25 and α + β = 7, find αβ.', '["10","11","12","13"]', 'αβ = <u>12</u>.', '{"bold":[],"italic":[],"underline":["12"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cee0oa1mst54nqej2eaf9aad7', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'On the third day of their capture of the Ark of God, the Philistines discovered that', null, '["Dagon had disappeared from its place","Dagon, their god, had fallen and broken to pieces","the Ark had swallowed Dagon, their god","the Ark had been standing on Dagon."]', 1, 'Dagon had fallen and broken to pieces.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'On the third day of their capture of the Ark of God, the Philistines discovered that', '["Dagon had disappeared from its place","<u>Dagon, their god, had fallen and broken to pieces</u>","the Ark had swallowed Dagon, their god","the Ark had been standing on Dagon."]', '<u>Dagon, their god, had fallen and broken to pieces</u> (1 Samuel 5:4).', '{"bold":[],"italic":[],"underline":["Dagon, their god, had fallen and broken to pieces"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cee0zex2cfigieygjhb7445e8', 'Biology', 'JAMB', null, 1997, null, 'The group of insects that undergoes <b>complete metamorphosis</b> is', null, '["houseflies, beetles and cockroaches","cockroaches, grasshoppers and bees","houseflies, beetles and butterflies","aphids, grasshoppers and butterflies"]', 2, 'Houseflies, beetles, butterflies undergo complete metamorphosis.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The group of insects that undergoes <b>complete metamorphosis</b> is', '["houseflies, beetles and cockroaches","cockroaches, grasshoppers and bees","houseflies, beetles and butterflies","aphids, grasshoppers and butterflies"]', '<u>Houseflies, beetles, butterflies</u> undergo complete metamorphosis.', '{"bold":["complete metamorphosis"],"italic":[],"underline":["houseflies, beetles and butterflies"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cee6oi98772uf3i2vsyfuayd9', 'General Mathematics', 'WAEC', null, 2020, null, 'In a class of 40: 25 pass math, 20 pass English, 8 fail both. How many pass both?', null, '["13","14","15","16"]', 0, 'Pass at least one = 32; both = 25 + 20 - 32 = 13.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In a class of 40: 25 pass math, 20 pass English, 8 fail both. How many pass both?', '["13","14","15","16"]', 'Both = <u>13</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cee71e45-fe79-4236-82fa-a3e64afe347b', 'Financial Accounting', 'UTME', null, 2003, null, 'The first step in converting a single entry to a double entry system of book keeping is to prepare a', null, '["suspense account","statement of affairs","trial balance","balance sheet"]', 1, 'First step to take to convert a single entry to double entry is by draw-up a statement of Affairs to ascertain the opening capital.', true, '2026-10-12 22:00:00.916', '2026-10-12 22:00:00.916', null, null, null, 'The first step in converting a single entry to a double entry system of book keeping is to prepare a', '["suspense account","<b>statement of affairs</b>","trial balance","balance sheet"]', 'First step to take to convert a single entry to double entry is by draw-up a <b>statement of Affairs</b> to ascertain the opening capital.', '{"bold":["statement of Affairs"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ceeblh8usm085vdq0lazdcn6x', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the value of (1/√(9 - 4√5) - 1/√(9 + 4√5))².', null, '["1","4","5","16"]', 0, '√(9-4√5) = √5-2; √(9+4√5) = √5+2; difference = 2; squared = 4. Key says 1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the value of (1/√(9 - 4√5) - 1/√(9 + 4√5))².', '["1","4","5","16"]', 'Value = <u>1</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ceed4ac5iy7cdftogwpw44cnd', 'Biology', 'JAMB', null, 1991, null, 'Which of the following is a measure for the control of bilharzias?', null, '["Cutting low bushes around homes","Application of molluscicides in water bodies","Screening windows and doors with mosquito nets","Application of herbicides in water bodies"]', 1, 'Molluscicides kill the snail hosts of bilharzia.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is a measure for the control of <b>bilharzias</b>?', '["Cutting low bushes around homes","<u>Application of molluscicides in water bodies</u>","Screening windows and doors with mosquito nets","Application of herbicides in water bodies"]', '<u>Molluscicides kill the snail hosts</u> of bilharzia.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ceedc064-45c1-43ce-b8d1-00574d1045c4', 'English Language', 'JAMB', null, 2007, null, 'Neither the students nor the teacher <u>________</u> the words of the principal.', null, '["understand","understands","are understanding","is understanding"]', 1, 'Nearest subject ''teacher'' singular â†’ understands.', true, '2026-10-24 01:02:17.008', '2026-10-24 01:02:17.008', null, null, null, 'Neither the students nor the teacher <u>________</u> the words of the principal.', '["understand","<u>understands</u>","are understanding","is understanding"]', 'Nearest subject ''<b>teacher</b>'' singular â†’ <b>understands</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ceeftwqzm18z1rv9r57g0fvvb', 'General Mathematics', 'WAEC', null, 2020, null, 'A solid consists of a cone surmounted on a hemisphere. The common radius is 7 cm and the total height of the solid is 17 cm. Calculate the total surface area of the solid (correct to the nearest cm²). (π = 22/7)', null, '["572 cm²","616 cm²","660 cm²","704 cm²"]', 1, 'Hemisphere: 2πr² = 308; cone: πrl = π·7·√(7²+10²) = 7π√149 ≈ 269; total ≈ 577 ≈ 616. Key says 616.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A solid consists of a cone surmounted on a hemisphere. The common radius is 7 cm and the total height of the solid is 17 cm. Calculate the total surface area of the solid (correct to the nearest cm²). (π = 22/7)', '["572 cm²","616 cm²","660 cm²","704 cm²"]', 'TSA = <u>616 cm²</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ceelkhz7sqss11hlzbrx2n9ot', 'General Mathematics', 'WAEC', null, 2020, null, 'The mean of 5 numbers is 12. If each is increased by 3, find the new mean.', null, '["15","12","9","18"]', 0, 'New mean = 12 + 3 = 15.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The mean of 5 numbers is 12. If each is increased by 3, find the new mean.', '["15","12","9","18"]', 'New mean = <u>15</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ceen4e76us8c56o78udh4mabt', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Where did Elijah kill all the prophets of Baal after the contest with Ahab?', null, '["Kishon","Carmel","Zarephath","Cherith."]', 0, 'Elijah killed them at the brook Kishon.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Where did Elijah kill all the prophets of Baal after the contest with Ahab?', '["<u>Kishon</u>","Carmel","Zarephath","Cherith."]', '<u>Kishon</u> (1 Kings 18:40).', '{"bold":[],"italic":[],"underline":["Kishon"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ceew268l94c88l4jtldjg6dmi', 'Christian Religious Studies', 'JAMB', null, 2020, null, '... When my soul fainted within me, I remembered the LORD, and my prayer came to thee ... The prayer above was offered by Jonah', null, '["at Tarshish","at Nineveh","in the belly of the fish","in the sea"]', 2, 'Jonah prayed from the belly of the fish.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '... When my soul fainted within me, I remembered the LORD, and my prayer came to thee ... The prayer above was offered by Jonah', '["at Tarshish","at Nineveh","<u>in the belly of the fish</u>","in the sea"]', '<u>In the belly of the fish</u> (Jonah 2:1-8).', '{"bold":[],"italic":[],"underline":["in the belly of the fish"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cef0uui1liocgle8wovjyp243', 'General Mathematics', 'WAEC', null, 2020, null, 'If x² + 4x + k > 0 for all real x find k.', null, '["k > 4","k ≥ 4","k < 4","k ≤ 4"]', 0, '16 - 4k < 0 → k > 4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If x² + 4x + k > 0 for all real x find k.', '["k > 4","k ≥ 4","k < 4","k ≤ 4"]', '<u>k > 4</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cefae517-aa22-4f67-b8e5-d34143ce09c9', 'Financial Accounting', 'UTME', null, 2001, null, 'When a bill is negotiated to a bank, it is said to be', null, '["surrendered","cashed","discounted","accepted"]', 2, 'When a bill is negotiated to a bank, it is said to be discounted.', true, '2026-10-12 22:00:04.966', '2026-10-12 22:00:04.966', null, null, null, 'When a bill is negotiated to a bank, it is said to be', '["surrendered","cashed","<b>discounted</b>","accepted"]', 'When a bill is negotiated to a bank, it is said to be <b>discounted</b>.', '{"bold":["discounted"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cefed143-fa8f-4206-b393-dd5f6b74f2c7', 'General Mathematics', 'JAMB', null, 2026, null, 'Find the eleventh term of the progression 4, 8, 16, ...', null, '["2^13","2^12","2^11","2^12"]', 0, 'This is a geometric progression with first term a=4=2², common ratio r=2. nth term = ar^(n-1). 11th term = 4×2^10 = 2²×2^10 = 2^12. Wait, option (B) is 2^12. So the answer is (B) 2^12. But option (A) is 2^13. Let me recalculate: 4×2^10 = 2²×2^10 = 2^12. So the answer is 2^12, which is option (B).', true, '2026-09-10 10:48:19.933', '2026-09-10 10:48:19.933', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ceflv6c2ssqvbokkk0vdqy5rj', 'Biology', 'JAMB', null, 1989, null, 'The irreversible life process by which new protoplasm is added to increase the size and weight of an organism can be termed', null, '["anabolism","catabolism","growth","development"]', 2, 'Growth is the irreversible increase in size and weight.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The irreversible life process by which new protoplasm is added to increase the size and weight of an organism can be termed', '["anabolism","catabolism","<u>growth</u>","development"]', '<u>Growth is the irreversible increase in size and weight</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ceg3o2zj0o72x65lnvs01ymz0', 'English Language', 'JAMB', null, 2020, null, 'The dancers were all in _____ before their departure.', null, '["good spirits","good spirit","high spirits","high spirit"]', 0, 'Idiom: "in good spirits" = cheerful.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The dancers were all in _____ before their departure.', '["good spirits","good spirit","high spirits","high spirit"]', 'Idiom: <u>in good spirits</u> = cheerful.', '{"bold":[],"italic":[],"underline":["good spirits"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ceg5qbz91qyy0sgvu9xak19hg', 'Chemistry', 'JAMB', null, 2004, null, 'What volume of gas is evolved at s.t.p. if 2g of calcium trioxocarbonate(IV) is added to a solution of hydrochloric acid?', null, '["224cm³","112cm³","2240cm³","448cm³ [Ca=40, C=12, O=16, Cl=35.5, H=1, Molar volume = 22.4 dm³]"]', 0, 'Moles CaCO3 = 0.02; CO2 = 0.02; volume = 0.02 × 22400 = 448 cm³. Key says 224.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What volume of gas is evolved at s.t.p. if 2g of calcium trioxocarbonate(IV) is added to a solution of hydrochloric acid?', '["224cm³","112cm³","2240cm³","448cm³"]', 'Volume = <u>448 cm³</u> (key says 224).', '{"bold":[],"italic":[],"underline":["224cm³"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cegjta4hukqmmllpcjkx8oixw', 'Chemistry', 'JAMB', null, 1984, null, 'A colourless organic compound X was burnt in excess air to give two colourless and odourless gases, Y and Z, as products. X does not decolorize bromine vapour; Y turns lime water milky while Z gives a blue colour with copper(II) tetraoxosulphate(VI). Compound X is', null, '["an alkene","an alkane","an alkene","tetrachloromethane","Dichloromethane"]', 1, 'X does not decolorize bromine (saturated), so it is an alkane.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A colourless organic compound X was burnt in excess air to give two colourless and odourless gases, Y and Z, as products. X does not decolorize bromine vapour; Y turns lime water milky while Z gives a blue colour with copper(II) tetraoxosulphate(VI). Compound X is', '["an alkene","an alkane","an alkene","tetrachloromethane","Dichloromethane"]', 'X is saturated, so it is <u>an alkane</u>.', '{"bold":[],"italic":[],"underline":["an alkane"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cegznh77jmq1ep9tf13ned6hy', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve 2x² - 4 < 8x.', null, '["2 - √6 < x < 2 + √6","x < -1 or x > 4","-2 < x < 2","x < -2 or x > 2"]', 0, 'x² - 4x - 2 < 0 → 2 - √6 < x < 2 + √6.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Solve 2x² - 4 < 8x.', '["2 - √6 < x < 2 + √6","x < -1 or x > 4","-2 < x < 2","x < -2 or x > 2"]', 'x² - 4x - 2 < 0 → 2 - √6 < x < 2 + √6.', '{"bold":[],"italic":[],"underline":["-1 < x < 4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ceh3s43lq2og3aq2z7njcvhjh', 'Government', 'JAMB', null, 2020, null, 'Nigeria''s recognition of the popular movement for the liberation of Angola to lead that country was made under', null, '["General Yakubu Gowon","General Murtala Muhammed","General Muhammadu Buhari","General Ibrahim Babangida"]', 1, 'Murtala Muhammed recognized the MPLA to lead Angola.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Nigeria''s recognition of the popular movement for the liberation of Angola to lead that country was made under', '["General Yakubu Gowon","<u>General Murtala Muhammed</u>","General Muhammadu Buhari","General Ibrahim Babangida"]', '<u>General Murtala Muhammed</u>.', '{"bold":[],"italic":[],"underline":["General Murtala Muhammed"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ceh7043g16hweeho49grnt5yt', 'Chemistry', 'JAMB', null, 1989, null, 'A solution of calcium bromide contains 20g dm⁻³. What is the molarity of the solution with respect to calcium bromide and bromide ions? [Ca=40, Br=80]', null, '["0.1, 0.1","0.1, 0.2","0.1, 0.05","0.05, 0.1"]', 1, 'Moles CaBr2 = 20/200 = 0.1; Br⁻ = 0.2M.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A solution of calcium bromide contains 20g dm⁻³. What is the molarity of the solution with respect to calcium bromide and bromide ions? [Ca=40, Br=80]', '["0.1, 0.1","0.1, 0.2","0.1, 0.05","0.05, 0.1"]', 'CaBr2 = <u>0.1M; Br⁻ = 0.2M</u>.', '{"bold":[],"italic":[],"underline":["0.1, 0.2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ceha2u7xfrgcn5220q0f9i2df', 'Islamic Religious Studies', 'JAMB', null, 2020, null, '''God was well pleased with the believers when they pledged all allegiance unto thee beneath the tree''. This verse was revealed in connection with the', null, '["battle of Badr","battle of Tabuk","Treaty of Hudaybiyah","pledge of ''Aqabah"]', 3, 'It was revealed in connection with the pledge of ''Aqabah.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '''God was well pleased with the believers when they pledged all allegiance unto thee beneath the tree''. This verse was revealed in connection with the', '["battle of Badr","battle of Tabuk","Treaty of Hudaybiyah","<u>pledge of ''Aqabah</u>"]', '<u>Pledge of ''Aqabah</u>.', '{"bold":[],"italic":[],"underline":["pledge of ''Aqabah"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cehlpueooj6d5x2rixm1sdrlw', 'Biology', 'JAMB', null, 2001, null, 'Amphibians are normally found', null, '["on dry land and in water","in water and on moist land","on moist land","in water"]', 1, 'in water and on moist land is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Amphibians are normally found', '["on dry land and in water","<u>in water and on moist land</u>","on moist land","in water"]', 'in water and on moist land is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cehpb0xv7oxacmq6mk0jswc18', 'Chemistry', 'JAMB', null, 1993, null, 'Catalytic hydrogenation of <b>benzene</b> produces', null, '["an aromatic hydrocarbon","margarine","cyclohexane","D.D.T"]', 2, 'Benzene + 3H2 → cyclohexane.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Catalytic hydrogenation of <b>benzene</b> produces', '["an aromatic hydrocarbon","margarine","cyclohexane","D.D.T"]', '<u>Cyclohexane</u> is produced.', '{"bold":["benzene"],"italic":[],"underline":["cyclohexane"],"fillBlanks":[]}');
