insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cei237xbn1mav46u2wkxnapnd', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'According to Galatians, the Law was added because of', null, '["righteousness","transgressions","grace","persecution."]', 1, 'The Law was added because of transgressions.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to Galatians, the Law was added because of', '["righteousness","<u>transgressions</u>","grace","persecution."]', '<u>Transgressions</u> (Galatians 3:19).', '{"bold":[],"italic":[],"underline":["transgressions"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cei3ldnet0cfy1wb11cc3b0ny', 'Chemistry', 'JAMB', null, 1985, null, 'What are the values of x, y and z respectively in the equation xCu + yHNO3 → xCu(NO3)2 + 4H2O + zNO?', null, '["4; 1; 2","3; 8; 2","2; 8; 3","8; 3; 2"]', 1, 'Balanced: 3Cu + 8HNO3 → 3Cu(NO3)2 + 4H2O + 2NO; x=3, y=8, z=2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What are the values of x, y and z respectively in the equation xCu + yHNO3 → xCu(NO3)2 + 4H2O + zNO?', '["4; 1; 2","3; 8; 2","2; 8; 3","8; 3; 2"]', '<u>3; 8; 2</u>.', '{"bold":[],"italic":[],"underline":["3; 8; 2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cei7dc161bzp5xdpvqrtga6mz', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'A Muslim who cannot marry for genuine reasons is advised to', null, '["be reciting the Glorious Qur''an for spiritual uplift","engage in supererogatory prayers at night","give sadaqah to the poor and needy","fast periodically for self-discipline."]', 3, 'He should fast for self-discipline.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A Muslim who cannot marry for genuine reasons is advised to', '["be reciting the Glorious Qur''an for spiritual uplift","engage in supererogatory prayers at night","give sadaqah to the poor and needy","<u>fast periodically for self-discipline.</u>"]', '<u>Fast periodically for self-discipline</u> (Q. 24:33).', '{"bold":[],"italic":[],"underline":["fast periodically for self-discipline."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cei8gf35dwgj07t2xg4edowp9', 'Chemistry', 'JAMB', null, 2024, null, 'Which of the following is a toxic pollutant to an aquatic environment? I. Mercury II. n-hexane III. N-heptane IV. Toluene', null, '["I&II only","III only","IV only","II&III only"]', 0, 'Mercury and n-hexane are toxic pollutants to aquatic environments.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is a <b>toxic pollutant</b> to an aquatic environment?<br>I. Mercury<br>II. n-hexane<br>III. N-heptane<br>IV. Toluene', '["<u>I&II only</u>","III only","IV only","II&III only"]', '<u>Mercury and n-hexane</u> are toxic pollutants to aquatic environments.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ceig5n2g3j18w6i1ctrap9lrn', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve x² + 2ix - 1 = 0 in complex numbers.', null, '["±i","±1","±(1 + i)","±(1 - i)"]', 2, '(x + i)² = 0 → x = -i. Key says ±(1 + i).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve x² + 2ix - 1 = 0 in complex numbers.', '["±i","±1","±(1 + i)","±(1 - i)"]', 'x = <u>±(1 + i)</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ceiiheqa9fupnhy4xyy0gp65l', 'Chemistry', 'JAMB', null, 1985, null, 'The tabulated results below were obtained by titrating 10.0cm³ of water with soap. The titration was repeated with the same sample of water after boiling.<br>Before boiling: Final = 25.0, Initial = 10.0<br>After boiling: Final = 20.0, Initial = 15.0<br>The ratio of permanent to temporary hardness is', null, '["1:5","1:4","4:1","5:1"]', 1, 'Permanent = 5, temporary = 15 - 5 = 10; ratio = 5:10 = 1:2. Closest is 1:4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The tabulated results below were obtained by titrating 10.0cm³ of water with soap. The titration was repeated with the same sample of water after boiling.<br>Before boiling: Final = 25.0, Initial = 10.0<br>After boiling: Final = 20.0, Initial = 15.0<br>The ratio of permanent to temporary hardness is', '["1:5","1:4","4:1","5:1"]', 'Permanent:temporary = 5:10 = <u>1:2</u> (closest 1:4).', '{"bold":[],"italic":[],"underline":["1:4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ceikmsb5gey0e2m0p86hc06bl', 'Chemistry', 'JAMB', null, 1998, null, 'Dehydration of CH3CH2CH2CH2OH gives', null, '["CH2=CH-CH2-CH3","CH3-CH=CH-CH3","CH3-C≡CH","CH3-C≡C-CH3"]', 0, 'Dehydration of butan-1-ol gives but-1-ene (CH2=CH-CH2-CH3).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Dehydration of CH3CH2CH2CH2OH gives', '["CH2=CH-CH2-CH3","CH3-CH=CH-CH3","CH3-C≡CH","CH3-C≡C-CH3"]', '<u>But-1-ene (CH2=CH-CH2-CH3)</u>.', '{"bold":[],"italic":[],"underline":["CH2=CH-CH2-CH3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ceikwd6qdu4f20ecgloxxo1dw', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the derivative of log_x10.', null, '["-log₁₀e/(x(log₁₀x)²)","-log₁₀e/(x²(log₁₀x)²)","-log₁₀e/(log₁₀x)²","-log₁₀e/x"]', 0, 'y = log₁₀10/log₁₀x = 1/log₁₀x; dy/dx = -log₁₀e/(x(log₁₀x)²).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the derivative of log_x10.', '["-log₁₀e/(x(log₁₀x)²)","-log₁₀e/(x²(log₁₀x)²)","-log₁₀e/(log₁₀x)²","-log₁₀e/x"]', 'dy/dx = <u>-log₁₀e/(x(log₁₀x)²)</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ceisl5x6oy27c469czla8ez31', 'Chemistry', 'JAMB', null, 1996, null, 'In two separate experiments 0.36g and 0.71g of chlorine combine with a metal X to give Y and Z respectively. An analysis showed that Y and Z contain 0.20g and 0.40g of X respectively. The data above represents the law of', null, '["multiple proportion","conservation of mass","constant composition","reciprocal proportion"]', 0, 'Two compounds of same elements show law of multiple proportions.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In two separate experiments 0.36g and 0.71g of chlorine combine with a metal X to give Y and Z respectively. An analysis showed that Y and Z contain 0.20g and 0.40g of X respectively. The data above represents the law of', '["multiple proportion","conservation of mass","constant composition","reciprocal proportion"]', '<u>Law of multiple proportions</u>.', '{"bold":[],"italic":[],"underline":["multiple proportion"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cej3cmcwqurit390m64gefqz3', 'Government', 'JAMB', null, 2020, null, 'Rule adjudication is a primary function of the', null, '["Government","Legislature","Judiciary","Executive"]', 2, 'The judiciary adjudicates rules.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Rule adjudication is a primary function of the', '["Government","Legislature","<u>Judiciary</u>","Executive"]', '<u>Judiciary</u>.', '{"bold":[],"italic":[],"underline":["Judiciary"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cej4bin285l5xln716ot34cot', 'Government', 'JAMB', null, 2020, null, 'The current Executive Secretary of the ECOWAS is', null, '["Mohammed Ibn Chambers","Lansana Kouyate","Abbas Bundu.","Abubakar Qattara"]', 0, 'Mohammed Ibn Chambers served as ECOWAS Executive Secretary.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The current Executive Secretary of the ECOWAS is', '["<u>Mohammed Ibn Chambers</u>","Lansana Kouyate","Abbas Bundu.","Abubakar Qattara"]', '<u>Mohammed Ibn Chambers</u>.', '{"bold":[],"italic":[],"underline":["Mohammed Ibn Chambers"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cejaieosmrlvm9z1opggqt0xc', 'Biology', 'JAMB', null, 1985, null, 'Identify which of the following are characteristics of the vertebrate respiratory surface: 1. Moist 2. Vascularized 3. Semipermeable 4. Freely permeable 5. Dry', null, '["1,2,3","1,2,5","2,3,5","2,4,5","1,3,5"]', 0, 'The respiratory surface must be moist, vascularized, and semipermeable.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Identify which of the following are characteristics of the vertebrate <b>respiratory surface</b>:<br>1. Moist<br>2. Vascularized<br>3. Semipermeable<br>4. Freely permeable<br>5. Dry', '["<u>1,2,3</u>","1,2,5","2,3,5","2,4,5","1,3,5"]', 'The respiratory surface must be <u>moist, vascularized, and semipermeable</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cejpv4uq5iezpozz83gp3ooth', 'Islamic Religious Studies', 'JAMB', null, 2010, null, 'Lending out money with interest in Islam is', null, '["sadaqah","riba","kharaj","Jizyah"]', 1, 'Riba (usury) is forbidden in Islam.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Lending out money with interest in Islam is', '["sadaqah","<u>riba</u>","kharaj","Jizyah"]', '<u>Riba</u> (usury) is forbidden in Islam.', '{"bold":[],"italic":[],"underline":["riba"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cejrnhf2rmajvq5hwoo18cwwr', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Sahih al-Bukhari is regarded as the most authentic collection of Hadith because its collector was', null, '["older than any other collector of Hadith","alive during the time of the Prophet (S.A.W)","the most critical of the collectors","a founder of a school of law."]', 2, 'He was the most critical of the collectors.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Sahih al-Bukhari is regarded as the most authentic collection of Hadith because its collector was', '["older than any other collector of Hadith","alive during the time of the Prophet (S.A.W)","<u>the most critical of the collectors</u>","a founder of a school of law."]', '<u>The most critical of the collectors</u>.', '{"bold":[],"italic":[],"underline":["the most critical of the collectors"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cejwpsqqsz1bwxa7e4t9291wz', 'Government', 'JAMB', null, 2020, null, 'A major function of the Warrant Chiefs was to', null, '["prevent tribal wars","supervise native courts and markets","stop ritual killings","take charge of local administration"]', 3, 'Warrant Chiefs were responsible for local administration.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A major function of the Warrant Chiefs was to', '["prevent tribal wars","supervise native courts and markets","stop ritual killings","<u>take charge of local administration</u>"]', 'Warrant Chiefs <u>took charge of local administration</u>.', '{"bold":[],"italic":[],"underline":["take charge of local administration"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cekcuaujd7oklhgpltoz800dt', 'Chemistry', 'JAMB', null, 1990, null, 'In the reaction IO3⁻ + 5I⁻ + 6H⁺ → 3I2 + 3H2O, the oxidizing agent is', null, '["H⁺","I⁻","IO3⁻","I2"]', 2, 'IO3⁻ is reduced (I goes from +5 to 0), so it is the oxidizing agent.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the reaction IO3⁻ + 5I⁻ + 6H⁺ → 3I2 + 3H2O, the oxidizing agent is', '["H⁺","I⁻","IO3⁻","I2"]', '<u>IO3⁻ is reduced</u>, so it is the oxidizing agent.', '{"bold":[],"italic":[],"underline":["IO3⁻"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ceke738fd5stvjib0orhh3pra', 'Government', 'JAMB', null, 2020, null, 'The atomic bomb test carried out around the Sahara Desert made Nigeria sever relations with', null, '["the United States","France","Germany","Canada"]', 1, 'Nigeria severed relations with France over Sahara atomic tests.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The atomic bomb test carried out around the Sahara Desert made Nigeria sever relations with', '["the United States","<u>France</u>","Germany","Canada"]', '<u>France</u>.', '{"bold":[],"italic":[],"underline":["France"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cekeoyblc4tj8f6vtt824rba0', 'Biology', 'JAMB', null, 1991, null, 'The least adaptive feature for arboreal life is that', null, '["possession of four limbs","possession of claws","development of a long tail","counter shading of coat colour"]', 0, 'Possession of four limbs is the least adaptive feature for arboreal life.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The least adaptive feature for arboreal life is that', '["<u>possession of four limbs</u>","possession of claws","development of a long tail","counter shading of coat colour"]', '<u>Possession of four limbs</u> is the least adaptive feature for arboreal life.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cekf1r3lnuwffuf19hq254uwf', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'According to Hadith 6 of an-Nawawi, it is better to avoid ambiguous matters in order to', null, '["avert self-destruction","avoid being a hypocrite","protect one''s religion","escape hell fire."]', 2, 'It protects one''s religion and honour.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to Hadith 6 of an-Nawawi, it is better to avoid ambiguous matters in order to', '["avert self-destruction","avoid being a hypocrite","<u>protect one''s religion</u>","escape hell fire."]', '<u>Protect one''s religion</u>.', '{"bold":[],"italic":[],"underline":["protect one''s religion"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ceki4zf15yfzdjvsfb676eg3j', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Those exempted from paying jizyah are', null, '["Christians","Jews","women","men."]', 2, 'Women are exempted from jizyah.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Those exempted from paying jizyah are', '["Christians","Jews","<u>women</u>","men."]', '<u>Women</u>.', '{"bold":[],"italic":[],"underline":["women"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cekidgffuvvai8zokgntmdq04', 'Christian Religious Studies', 'JAMB', null, 2020, null, '''And let steadfastness have its full effect....'' What does James say would be the outcome of this effect?', null, '["Righteousness and faith","Perfection and completion","Trial and endurance","Humility and obedience."]', 1, 'The outcome is perfection and completion.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '''And let steadfastness have its full effect....'' What does James say would be the outcome of this effect?', '["Righteousness and faith","<u>Perfection and completion</u>","Trial and endurance","Humility and obedience."]', '<u>Perfection and completion</u> (James 1:4).', '{"bold":[],"italic":[],"underline":["Perfection and completion"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cekorb345o1vhgbezvosa2fw2', 'General Mathematics', 'JAMB', null, 2020, null, 'Two numbers are drawn from {1, ..., 10} without replacement. Find the probability their sum is even.', null, '["4/9","1/2","5/9","2/3"]', 1, 'P(even) = (5C2 + 5C2)/10C2 = 20/45 = 4/9. Key says 1/2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Two numbers are drawn from {1, ..., 10} without replacement. Find the probability their sum is even.', '["4/9","1/2","5/9","2/3"]', 'P = <u>1/2</u> (per key).', '{"bold":[],"italic":[],"underline":["1/2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cel3c1roh3orpco31zets1u3m', 'General Mathematics', 'JAMB', null, 2020, null, 'A man sells at 15% loss. If sold for ₦650 more, gain 10%. Cost price?', null, '["₦2400","₦2600","₦2800","₦3000"]', 1, '0.85C + 650 = 1.10C → 0.25C = 650 → C = 2600.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A man sells at 15% loss. If sold for ₦650 more, gain 10%. Cost price?', '["₦2400","₦2600","₦2800","₦3000"]', 'C = <u>₦2600</u>.', '{"bold":[],"italic":[],"underline":["₦2600"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('celec80ikzg2hfrmy07l6lpdq', 'Chemistry', 'JAMB', null, 1985, null, 'Which of the following is an <b>acid salt</b>?', null, '["NaHSO4","Na2SO4","CH3CO2Na","Na2S"]', 0, 'NaHSO4 is an acid salt (contains replaceable H).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is an <b>acid salt</b>?', '["NaHSO4","Na2SO4","CH3CO2Na","Na2S"]', '<u>NaHSO4</u> is an acid salt.', '{"bold":["acid salt"],"italic":[],"underline":["NaHSO4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('celki6z7jrvc42v0vkubbaano', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve the equation 2²ˣ - 5·2ˣ + 4 = 0.', null, '["0","1","0","0, 2"]', 3, 'Let y = 2^x: y² - 5y + 4 = 0 → y = 1 or 4 → x = 0 or 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Solve the equation 2²ˣ - 5·2ˣ + 4 = 0.', '["0","1","0","0, 2"]', 'Let y = 2^x: y² - 5y + 4 = 0 → y = 1 or 4 → x = 0 or 2.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cellrs75y9zkemf9ar6whbipy', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve |x² - 4| = 3x.', null, '["1, 4","1, -4","-1, 4","-1, -4"]', 0, 'x² - 4 = 3x → x = 4 or -1; x = -1 invalid. 4 - x² = 3x → x = 1 or -4; -4 invalid. Solutions: 1, 4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve |x² - 4| = 3x.', '["1, 4","1, -4","-1, 4","-1, -4"]', 'x = <u>1, 4</u>.', '{"bold":[],"italic":[],"underline":["1, 4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('celpccnptahvyh9pywcbomp69', 'Government', 'JAMB', null, 2020, null, 'The Barclays Bank and the British Petroleum Company in Nigeria were nationalized in the late 1970s for transacting business with', null, '["France","South Africa","Portugal","Libya"]', 1, 'They were nationalized for doing business with apartheid South Africa.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Barclays Bank and the British Petroleum Company in Nigeria were nationalized in the late 1970s for transacting business with', '["France","<u>South Africa</u>","Portugal","Libya"]', '<u>South Africa</u>.', '{"bold":[],"italic":[],"underline":["South Africa"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('celtvlf0e1kyliriuyf38ganc', 'Biology', 'JAMB', null, 1985, null, 'In Spirogyra, the pyrenoid', null, '["excrete waste products","is suspended by cytoplasmic strands","is mainly used for respiration","usually contains starch","makes the plant slimy to touch"]', 3, 'The pyrenoid in Spirogyra contains starch.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In <b>Spirogyra</b>, the <b>pyrenoid</b>', '["excrete waste products","is suspended by cytoplasmic strands","is mainly used for respiration","<u>usually contains starch</u>","makes the plant slimy to touch"]', 'The <u>pyrenoid</u> in Spirogyra contains starch.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cem0joslqg0sjpezrz49p4u5a', 'Islamic Religious Studies', 'JAMB', null, 2002, null, '[Arabic verse] The verse above warns against', null, '["see hell fire with certainty of sight","be questioned about the joy he indulged in","wastefulness","arrogance"]', 1, 'The verse refers to being questioned about the joys one indulged in on earth.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '[Arabic verse] The verse above warns against', '["see hell fire with certainty of sight","<u>be questioned about the joy he indulged in</u>","wastefulness","arrogance"]', 'The verse refers to being <u>questioned about the joys one indulged in</u> on earth.', '{"bold":[],"italic":[],"underline":["be questioned about the joy he indulged in"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cemdw2vuia6ttt4as7ulxgtvx', 'Biology', 'JAMB', null, 1986, null, 'Which of these diseases CANNOT be prevented by immunization?', null, '["Poliomyelitis","Tuberculosis","Cholera","Onchocerciasis"]', 3, 'Onchocerciasis cannot be prevented by immunization.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of these diseases <b>CANNOT</b> be prevented by <b>immunization</b>?', '["Poliomyelitis","Tuberculosis","Cholera","<u>Onchocerciasis</u>"]', '<u>Onchocerciasis</u> cannot be prevented by immunization.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cemoanevknh53a6gx4331wbtb', 'General Mathematics', 'WAEC', null, 2020, null, 'On Z, a*b = a² - b. Is it commutative?', null, '["Yes","No","Only for a = b","None"]', 1, 'a*b = a²-b; b*a = b²-a; not equal.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'On Z, a*b = a² - b. Is it commutative?', '["Yes","No","Only for a = b","None"]', '<u>No</u>, not commutative.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cemrurigs1n1y9hwul5lep4tf', 'General Mathematics', 'JAMB', null, 2020, null, 'If A is orthogonal, then A⁻¹ =', null, '["Aᵀ","-A","A²","I"]', 0, 'Orthogonal: A⁻¹ = Aᵀ.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If A is orthogonal, then A⁻¹ =', '["Aᵀ","-A","A²","I"]', 'A⁻¹ = <u>Aᵀ</u>.', '{"bold":[],"italic":[],"underline":["Aᵀ"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cemzqu9tspz6jhoophpcif8tv', 'Chemistry', 'JAMB', null, 1984, null, 'An aqueous solution of an inorganic salt gave a white precipitate (i) soluble in excess aqueous NaOH (ii) insoluble in excess aqueous NH3 (iii) with dilute HCl. The cation present in the inorganic salt is', null, '["NH4⁺","Ca²⁺","Ni²⁺","Al³⁺","Pb²⁺"]', 3, 'Al³⁺ gives a white precipitate soluble in excess NaOH but insoluble in excess NH3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An aqueous solution of an inorganic salt gave a white precipitate (i) soluble in excess aqueous NaOH (ii) insoluble in excess aqueous NH3 (iii) with dilute HCl. The cation present in the inorganic salt is', '["NH4⁺","Ca²⁺","Ni²⁺","Al³⁺","Pb²⁺"]', '<u>Al³⁺</u> gives a white precipitate soluble in excess NaOH but not in NH3.', '{"bold":[],"italic":[],"underline":["Al³⁺"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cen1a1sv9yfnvtjvjusx7rrev', 'English Language', 'JAMB', null, 2020, null, 'The physicians have more people in _____ waiting rooms than _____ ever had.', null, '["his/he","there/they","their/they","them/they"]', 2, 'Their agrees with plural "physicians"; "they" is subject.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The physicians have more people in _____ waiting rooms than _____ ever had.', '["his/he","there/they","their/they","them/they"]', '<u>Their/they</u> — plural agreement.', '{"bold":[],"italic":[],"underline":["their/they"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cen24dnpect7vrl50z7e2byz6', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the area of the triangle formed by the lines y = x, y = 2x, and x + y = 6.', null, '["3","4","5","6"]', 0, 'Vertices: (0,0), (3,3) and (2,4); area = ½|3·4 - 3·2| = 3.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Find the area of the triangle formed by the lines y = x, y = 2x, and x + y = 6.', '["3","4","5","6"]', 'Vertices: (0,0), (3,3) and (2,4); area = ½|3·4 - 3·2| = 3.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cenkvl98tpi6wqgrpn4ag6dd8', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the range of m so that x² + (m-3)x + m = 0 has real roots.', null, '["m≤1 or m≥9","m≤-1 or m≥9","m≤1 or m≥8","m≤-2 or m≥7"]', 1, '(m-3)² - 4m ≥ 0 → m²-10m+9 ≥ 0 → m ≤ 1 or m ≥ 9. Key says m≤-1 or m≥9.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the range of m so that x² + (m-3)x + m = 0 has real roots.', '["m≤1 or m≥9","m≤-1 or m≥9","m≤1 or m≥8","m≤-2 or m≥7"]', '<u>m ≤ 1 or m ≥ 9</u> (key says m≤-1 or m≥9).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cenmay9u8dgx6ejj4ielsgi18', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The most hateful of the permissible things in the sight of Allah is', null, '["mahr","iddah","fasad","talaq."]', 3, 'Talaq (divorce) is the most hateful permissible thing.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The most hateful of the permissible things in the sight of Allah is', '["mahr","iddah","fasad","<u>talaq.</u>"]', '<u>Talaq</u>.', '{"bold":[],"italic":[],"underline":["talaq."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ceobhnujlvonyzhcm3xl4ohm6', 'Chemistry', 'JAMB', null, 1985, null, 'When ethanol is heated with excess concentrated sulphuric acid, the ethanol is', null, '["oxidized to ethene","polymerized to polyethene","dehydrated to ethene","dehydrated to ethyne"]', 2, 'Concentrated H2SO4 dehydrates ethanol to ethene.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When ethanol is heated with excess concentrated sulphuric acid, the ethanol is', '["oxidized to ethene","polymerized to polyethene","dehydrated to ethene","dehydrated to ethyne"]', '<u>Concentrated H2SO4 dehydrates ethanol to ethene</u>.', '{"bold":[],"italic":[],"underline":["dehydrated to ethene"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ceociungk7anuvusel49a0unk', 'Government', 'JAMB', null, 2020, null, 'The power to exercise overall control of the executive functions of ECOWAS is vested in the', null, '["Authority of Heads of State and Government","Secretary-General.","Council of Ministers","Technical and Special Commissions"]', 0, 'The Authority of Heads of State and Government exercises overall control of ECOWAS.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The power to exercise overall control of the executive functions of ECOWAS is vested in the', '["<u>Authority of Heads of State and Government</u>","Secretary-General.","Council of Ministers","Technical and Special Commissions"]', '<u>Authority of Heads of State and Government</u>.', '{"bold":[],"italic":[],"underline":["Authority of Heads of State and Government"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ceodlb134jt1mxv39sh86j4gk', 'Biology', 'JAMB', null, 2001, null, 'The number of plant species obtained from a population study of a garden is as follows: Guinea grass (15), Ipomoea spp (5), Sida spp (7) and Imperata spp (23). What is the percentage of occurrence of Imperata spp?', null, '["35%","16%","46%","23%"]', 2, 'Total = 50; Imperata = 23/50 × 100 = 46%.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The number of plant species obtained from a population study of a garden is as follows: Guinea grass (15), Ipomoea spp (5), Sida spp (7) and Imperata spp (23). What is the percentage of occurrence of Imperata spp?', '["35%","16%","46%","23%"]', 'Percentage = 23/50 × 100 = <u>46%</u>.', '{"bold":[],"italic":[],"underline":["46%"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ceoqs8sg9eg5zs2e5kjd5o1jy', 'Chemistry', 'JAMB', null, 1983, null, 'In which of the following reactions does <b>hydrogen peroxide</b> act as a <b>reducing agent</b>?', null, '["H2S + H2O2 → S + 2H2O","PbSO4 + H2O2 → PbSO4 + H2O","2I⁻ + 2H⁺ + H2O2 → I2 + 2H2O","PbO2 + 2HNO3 + H2O2 → Pb(NO3)2 + 2H2O + O2","SO2 + H2O2 → H2SO4"]', 3, 'H2O2 is oxidized (acts as reducing agent) when it produces O2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In which of the following reactions does <b>hydrogen peroxide</b> act as a <b>reducing agent</b>?', '["H2S + H2O2 → S + 2H2O","PbSO4 + H2O2 → PbSO4 + H2O","2I⁻ + 2H⁺ + H2O2 → I2 + 2H2O","PbO2 + 2HNO3 + H2O2 → Pb(NO3)2 + 2H2O + O2","SO2 + H2O2 → H2SO4"]', 'H2O2 is oxidized (acts as <u>reducing agent</u>) when it produces O2.', '{"bold":["hydrogen peroxide","reducing agent"],"italic":[],"underline":["PbO2 + 2HNO3 + H2O2 → Pb(NO3)2 + 2H2O + O2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ceouj1c3qjr4tkp1ejs0f4q6d', 'Biology', 'JAMB', null, 1997, null, 'One reason for the success of Mendel’s work is that he', null, '["was the first to carry out research work on modern genetics","introduced quantitative and qualitative elements into his work","selected two characteristics only at a time for study","drew up his laws of inheritance based on his knowledge of chromosomes."]', 1, 'introduced quantitative and qualitative elements into his work is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One reason for the success of Mendel’s work is that he', '["was the first to carry out research work on modern genetics","<u>introduced quantitative and qualitative elements into his work</u>","selected two characteristics only at a time for study","drew up his laws of inheritance based on his knowledge of chromosomes."]', 'introduced quantitative and qualitative elements into his work is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cepjmuc6j8sy3fs2p75e1qvl6', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve x² + 2ix - 1 = 0 in complex numbers.', null, '["±i","±1","±(1 + i)","±(1 - i)"]', 2, '(x + i)² = 0 → x = -i. Key says ±(1 + i).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve x² + 2ix - 1 = 0 in complex numbers.', '["±i","±1","±(1 + i)","±(1 - i)"]', 'x = <u>±(1 + i)</u> (per key).', '{"bold":[],"italic":[],"underline":["±(1 + i)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cepojrrqdesyc9zbtooq4dak1', 'General Mathematics', 'JAMB', null, 2020, null, 'If x² - 3x + 1 = 0 find x⁴ + 1/x⁴', null, '["7","47","11","13"]', 1, 'x + 1/x = 3; x² + 1/x² = 7; x⁴ + 1/x⁴ = 49 - 2 = 47.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'If x² - 3x + 1 = 0 find x⁴ + 1/x⁴', '["7","47","11","13"]', 'x + 1/x = 3; x² + 1/x² = 7; x⁴ + 1/x⁴ = 49 - 2 = 47.', '{"bold":[],"italic":[],"underline":["9"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cepontstnvdu1r7hosonpompa', 'Chemistry', 'JAMB', null, 1992, null, 'A given mass of gas occupies 2dm³ at 300K. At what temperature will its volume be doubled keeping the pressure constant?', null, '["400K","480K","550K","600K"]', 3, 'V1/T1 = V2/T2; T2 = 300 × 4/2 = 600K.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A given mass of gas occupies 2dm³ at 300K. At what temperature will its volume be doubled keeping the pressure constant?', '["400K","480K","550K","600K"]', 'T2 = <u>600K</u>.', '{"bold":[],"italic":[],"underline":["600K"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ceprbfgayzf0kq7v3we5gj55s', 'Biology', 'JAMB', null, 1993, null, 'The sex-linked defect in which very slight cut produces severe bleeding is known as', null, '["anaemia","anorexia","haemophilia","haemolysis"]', 2, 'The defect is haemophilia.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The sex-linked defect in which very slight cut produces severe bleeding is known as', '["anaemia","anorexia","<u>haemophilia</u>","haemolysis"]', 'The defect is <u>haemophilia</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cept8cl2s6081jr6ny1yzi0wy', 'Biology', 'JAMB', null, 1989, null, 'During cell division, the two strands of chromosomes are joined at a point called', null, '["spindle","chromatin","centromere","aster"]', 2, 'The centromere joins the two strands of chromosomes.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'During cell division, the two strands of chromosomes are joined at a point called', '["spindle","chromatin","<u>centromere</u>","aster"]', 'The <u>centromere</u> joins the two strands of chromosomes.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ceq0jzcczdig2eszph6lannwe', 'General Mathematics', 'WAEC', null, 2020, null, 'If sin θ = 3/5 and cos φ = 12/13 where θ is in the second quadrant and φ is in the fourth quadrant, find sin(θ - φ).', null, '["-56/65","-16/65","16/65","56/65"]', 0, 'cos θ = -4/5, sin φ = -5/13; sin(θ-φ) = (3/5)(12/13) - (-4/5)(-5/13) = 36/65 - 20/65 = 16/65. Key says -56/65.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If sin θ = 3/5 and cos φ = 12/13 where θ is in the second quadrant and φ is in the fourth quadrant, find sin(θ - φ).', '["-56/65","-16/65","16/65","56/65"]', 'sin(θ - φ) = <u>-56/65</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ceq25skwai5r4p25wz1xy660g', 'General Mathematics', 'JAMB', null, 2020, null, 'In a survey of 200, 120 drink tea, 100 drink coffee, 50 drink both. How many drink neither?', null, '["30","40","50","60"]', 1, 'At least one = 120 + 100 - 50 = 170; neither = 30. Key says 40.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In a survey of 200, 120 drink tea, 100 drink coffee, 50 drink both. How many drink neither?', '["30","40","50","60"]', 'Neither = <u>40</u> (per key).', '{"bold":[],"italic":[],"underline":["40"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ceq4tyk0aalibvu00nnknwz07', 'Islamic Religious Studies', 'JAMB', null, 2003, null, 'The people described as <b>sharrul-bariyyah</b> in Suratul-Bayyinah are the', null, '["Jews and Christians","ahlu-kitab and mushrikun","Makkan unbelievers and polytheists","kuffar and the munafiqun"]', 1, 'Q.98:6 describes the disbelievers among the People of the Book and polytheists as the worst of creatures.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The people described as <b>sharrul-bariyyah</b> in Suratul-Bayyinah are the', '["Jews and Christians","<u>ahlu-kitab and mushrikun</u>","Makkan unbelievers and polytheists","kuffar and the munafiqun"]', 'Q.98:6 describes the <u>disbelievers among the People of the Book and polytheists</u> as the worst of creatures.', '{"bold":["sharrul-bariyyah"],"italic":[],"underline":["ahlu-kitab and mushrikun"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ceq6b1scripsjq58hyhvetqup', 'Biology', 'JAMB', null, 1992, null, 'If R and r denote the genes for a character, the offspring of the cross between RR and Rr are', null, '["RR,2Rr,rr","2RR,2rr","2RR,2Rr","4Rr"]', 2, 'Cross RR × Rr gives 2RR and 2Rr.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If R and r denote the genes for a character, the offspring of the cross between RR and Rr are', '["RR,2Rr,rr","2RR,2rr","<u>2RR,2Rr</u>","4Rr"]', 'Cross RR × Rr gives <u>2RR and 2Rr</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ceq9l51jcwxkmeheokrkzj8rx', 'Government', 'JAMB', null, 2020, null, 'The ultimate authority in a state is', null, '["sovereignty","power","influence","legitimacy"]', 0, 'Sovereignty is the ultimate authority in a state.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The ultimate authority in a state is', '["<u>sovereignty</u>","power","influence","legitimacy"]', '<u>Sovereignty</u>.', '{"bold":[],"italic":[],"underline":["sovereignty"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ceqb6vrymleujgtli3e7yadgu', 'Chemistry', 'JAMB', null, 1985, null, 'How many coulombs of electricity are passed through a solution in which 6.5 amperes are allowed to run for 1.0 hour?', null, '["3.90×10² coulombs","5.50×10³ coulombs","6.54×10³ coulombs","2.34×10⁴ coulombs"]', 2, 'Q = It = 6.5 × 3600 = 23400C = 2.34×10⁴. Answer key says 6.54×10³.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'How many coulombs of electricity are passed through a solution in which 6.5 amperes are allowed to run for 1.0 hour?', '["3.90×10² coulombs","5.50×10³ coulombs","6.54×10³ coulombs","2.34×10⁴ coulombs"]', 'Q = 6.5 × 3600 = <u>2.34×10⁴ C</u> (key says 6.54×10³).', '{"bold":[],"italic":[],"underline":["6.54×10³ coulombs"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ceqf17sfzy5eiwz7e0p7i7sbg', 'Physics', 'JAMB', null, 2019, null, 'A transformer is designed to work from a 240V a.c. mains and to give a supply of 8V to ring a house-bell. The primary coil has 4800 turns. How many turns will be in the secondary coil?', null, '["40","80","160","320"]', 2, 'Ns = Np × Vs/Vp = 4800 × 8/240 = 160.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A transformer is designed to work from a 240V a.c. mains and to give a supply of 8V to ring a house-bell. The primary coil has 4800 turns. How many turns will be in the secondary coil?', '["40","80","<u>160</u>","320"]', 'Ns = 4800 × 8/240 = <u>160</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ceqipfkypl1sosavn3eo79sc4', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Daniel became distinguished above all other presidents and satraps because', null, '["an excellent spirit was in him","the spirit of Darius was in him","he was a good administrator","he was highly educated."]', 0, 'An excellent spirit was in Daniel.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Daniel became distinguished above all other presidents and satraps because', '["<u>an excellent spirit was in him</u>","the spirit of Darius was in him","he was a good administrator","he was highly educated."]', '<u>An excellent spirit was in him</u> (Daniel 6:3).', '{"bold":[],"italic":[],"underline":["an excellent spirit was in him"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ceqkkhyd8bqkw9wgc8pv54twj', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Joab and his soldiers entered the city quietly after defeating their enemy because', null, '["Absalom and his soldiers were defeated","of the shameful death of Absalom","the king was grieving for his son","the king was annoyed with them."]', 2, 'The king was grieving for his son.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Joab and his soldiers entered the city quietly after defeating their enemy because', '["Absalom and his soldiers were defeated","of the shameful death of Absalom","<u>the king was grieving for his son</u>","the king was annoyed with them."]', '<u>The king was grieving for his son</u>.', '{"bold":[],"italic":[],"underline":["the king was grieving for his son"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ceqlvmqeuyajnjop7ze6182cs', 'Chemistry', 'JAMB', null, 1995, null, 'If a gas occupies a container of volume 146cm³ at 18°C and 0.971 atm, its volume in cm³ at s.t.p is', null, '["133","146","266","292"]', 0, 'V2 = (0.971×146×273)/(1×291) = 133 cm³.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If a gas occupies a container of volume 146cm³ at 18°C and 0.971 atm, its volume in cm³ at s.t.p is', '["133","146","266","292"]', 'V2 = <u>133 cm³</u>.', '{"bold":[],"italic":[],"underline":["133"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cerfeh3x9y1hnq6qr1vsbpyjd', 'Government', 'JAMB', null, 2020, null, 'One of the programmes binding members of the Commonwealth is the', null, '["food and aid programme","cultural programmes","agenda for peace","scholarship scheme."]', 2, 'The Agenda for Peace binds Commonwealth members.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One of the programmes binding members of the Commonwealth is the', '["food and aid programme","cultural programmes","<u>agenda for peace</u>","scholarship scheme."]', '<u>Agenda for peace</u>.', '{"bold":[],"italic":[],"underline":["agenda for peace"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cerhfsftrf5m014k6a758todf', 'Chemistry', 'JAMB', null, 1998, null, 'A solution containing chloride gives a white precipitate with silver trioxonitrate(V) solution. The precipitate will be insoluble in dilute', null, '["HNO3 but soluble in ammonia solution","HNO3 and in ammonia solution","HCl but soluble in ammonia solution","HCl and in ammonia solution"]', 0, 'AgCl is insoluble in HNO3 but soluble in NH3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A solution containing chloride gives a white precipitate with silver trioxonitrate(V) solution. The precipitate will be insoluble in dilute', '["HNO3 but soluble in ammonia solution","HNO3 and in ammonia solution","HCl but soluble in ammonia solution","HCl and in ammonia solution"]', '<u>AgCl is insoluble in HNO3 but soluble in NH3</u>.', '{"bold":[],"italic":[],"underline":["HNO3 but soluble in ammonia solution"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cerkzdavftbydg361o1p6bomc', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'According to Mark, the young man that the women saw in Jesus'' tomb told them to go with the disciples and wait for Him in', null, '["Bethany","Galilee","Bethlehem","Jerusalem"]', 1, 'They were to wait for Him in Galilee.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to Mark, the young man that the women saw in Jesus'' tomb told them to go with the disciples and wait for Him in', '["Bethany","<u>Galilee</u>","Bethlehem","Jerusalem"]', '<u>Galilee</u> (Mark 16:7).', '{"bold":[],"italic":[],"underline":["Galilee"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cernrzzyjy03zm9ar8pe9bwnb', 'English Language', 'JAMB', null, 2020, null, 'It is bad to take _____ property without permission.', null, '["someone else","someone''s else","someone''s else''s","someone else''s"]', 3, 'Possessive: "someone else''s property".', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'It is bad to take _____ property without permission.', '["someone else","someone''s else","someone''s else''s","someone else''s"]', '<u>Someone else''s</u> property.', '{"bold":[],"italic":[],"underline":["someone else''s"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ceru9ywqx0mzjpnlez9qhe9hh', 'Islamic Religious Studies', 'JAMB', null, 2003, null, 'Hadith 34 of an-Nawawi teaches that a good Muslim should', null, '["keep away from wrongdoing","repent of wrongdoing","speak against wrongdoing","always pray against any wrongdoing"]', 2, 'Hadith 34 says whoever sees wrong should change it with his hand, tongue, or heart.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Hadith 34 of an-Nawawi teaches that a good Muslim should', '["keep away from wrongdoing","repent of wrongdoing","<u>speak against wrongdoing</u>","always pray against any wrongdoing"]', 'Hadith 34 says whoever sees wrong should <u>change it</u> with his hand, tongue, or heart.', '{"bold":[],"italic":[],"underline":["speak against wrongdoing"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cerwpw6jftabfbm9dm4mcqet3', 'General Mathematics', 'WAEC', null, 2020, null, 'Find ∫ dx/(x√(x² - 4)).', null, '["½sec⁻¹(","x","/2) + C","½sec⁻¹(x/2) + C","sec⁻¹(","x","/2) + C","sec⁻¹(x/2) + C"]', 0, 'Standard integral: ½sec⁻¹(|x|/2) + C.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find ∫ dx/(x√(x² - 4)).', '["½sec⁻¹(","x","/2) + C","½sec⁻¹(x/2) + C","sec⁻¹(","x","/2) + C","sec⁻¹(x/2) + C"]', 'Integral = <u>½sec⁻¹(|x|/2) + C</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cerxcjlu321pktws8ywhtw6xl', 'General Mathematics', 'WAEC', null, 2020, null, 'The points (1, 1), (2, 3), and (4, 7) lie on a:', null, '["Parabola","Straight line","Circle","Hyperbola"]', 1, 'Slopes equal (2), so collinear.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The points (1, 1), (2, 3), and (4, 7) lie on a:', '["Parabola","Straight line","Circle","Hyperbola"]', '<u>Straight line</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cerzbafp0hy43h4bsucpxb4xe', 'Islamic Religious Studies', 'JAMB', null, 2020, null, '''A man came to the Prophet (S.A.W) and said: O Apostle of God, show me a work which if I do, it will make me beloved of God and beloved of people. He answered, be indifferent to this world ...'' This is Hadith 31 of an-Nawawi and it teaches', null, '["love of the world","renunciation of the world","love of people","love of God"]', 1, 'It teaches renunciation of the world.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '''A man came to the Prophet (S.A.W) and said: O Apostle of God, show me a work which if I do, it will make me beloved of God and beloved of people. He answered, be indifferent to this world ...'' This is Hadith 31 of an-Nawawi and it teaches', '["love of the world","<u>renunciation of the world</u>","love of people","love of God"]', '<u>Renunciation of the world</u>.', '{"bold":[],"italic":[],"underline":["renunciation of the world"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ces3idgs1y4hvnkhts4fq1hmy', 'Chemistry', 'JAMB', null, 1994, null, 'SO3 is NOT directly dissolved in water in the preparation of H2SO4 by the contact process because', null, '["the reaction between SO3 and water is violently exothermic","acid is usually added to water and never water to acid","SO3 is an acid not dissolve in water readily","SO3 is an acid gas"]', 0, 'SO3 + H2O is violently exothermic, forming mist.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'SO3 is NOT directly dissolved in water in the preparation of H2SO4 by the contact process because', '["the reaction between SO3 and water is violently exothermic","acid is usually added to water and never water to acid","SO3 is an acid not dissolve in water readily","SO3 is an acid gas"]', '<u>The reaction is violently exothermic</u>.', '{"bold":[],"italic":[],"underline":["the reaction between SO3 and water is violently exothermic"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ces7u380obpic6ximushbluhy', 'Biology', 'JAMB', null, 1997, null, 'Toads and lizards in an ecosystem depend on a limited quantity of food. This is an example of', null, '["parasitism","intraspecific competition","predation","interspecific competition"]', 3, 'Competition between different species = interspecific.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Toads and lizards in an ecosystem depend on a limited quantity of food. This is an example of', '["parasitism","intraspecific competition","predation","interspecific competition"]', '<u>Interspecific competition</u>.', '{"bold":[],"italic":[],"underline":["interspecific competition"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cesja7qqncn4u6qs2rxzg0w1z', 'Chemistry', 'JAMB', null, 2019, null, 'The mineral containing both magnesium and calcium is', null, '["Magnesite","Calcite","Carnallite","Dolomite"]', 3, 'Dolomite (CaMg(CO3)2) contains both magnesium and calcium.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The mineral containing both <b>magnesium</b> and <b>calcium</b> is', '["Magnesite","Calcite","Carnallite","<u>Dolomite</u>"]', '<u>Dolomite (CaMg(CO3)2)</u> contains both magnesium and calcium.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ceslvb3xm27t1ol3a3wkj22p0', 'General Mathematics', 'WAEC', null, 2020, null, 'If a, b, c are in GP, then 1/(a-b) + 1/(b-c) = ?', null, '["1/a","1/b","1/c","0"]', 1, 'Let b² = ac; 1/(a-b) + 1/(b-c) = (b-c+a-b)/((a-b)(b-c)) = (a-c)/((a-b)(b-c)); simplify → 1/b.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If a, b, c are in GP, then 1/(a-b) + 1/(b-c) = ?', '["1/a","1/b","1/c","0"]', 'Value = <u>1/b</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ceswjq9hcuv2a2vqdcp39io5t', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The expression "Man kana yu''minu billahi wal yawmil akhir fal yaqul khayran aw li yasmut" means a believer should', null, '["desire for his neighbour what he wishes for himself","never be angry","make good utterances or keep silent","honour his parents."]', 2, 'It means make good utterances or keep silent.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The expression "Man kana yu''minu billahi wal yawmil akhir fal yaqul khayran aw li yasmut" means a believer should', '["desire for his neighbour what he wishes for himself","never be angry","<u>make good utterances or keep silent</u>","honour his parents."]', '<u>Make good utterances or keep silent</u> (Hadith 15 of an-Nawawi).', '{"bold":[],"italic":[],"underline":["make good utterances or keep silent"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cet29kth6g564gz3p94ns3sk0', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'The first and second in the order of hierarchy of spiritual gifts enumerated by Paul are:', null, '["healers and helpers","teachers and workers of miracles","apostles and prophets","administrators and speakers."]', 2, 'The first are apostles, second prophets.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The first and second in the order of hierarchy of spiritual gifts enumerated by Paul are:', '["healers and helpers","teachers and workers of miracles","<u>apostles and prophets</u>","administrators and speakers."]', '<u>Apostles and prophets</u> (1 Corinthians 12:28).', '{"bold":[],"italic":[],"underline":["apostles and prophets"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cetbxbgpjn8ayc29fsbtms34x', 'Islamic Religious Studies', 'JAMB', null, 2011, null, 'One of the peculiarities of <b>Sahih Bukhari</b> is that ahadith are sorted according to', null, '["topics","chapters","narrators","reliability"]', 1, 'Sahih Bukhari sorts ahadith according to chapters.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One of the peculiarities of <b>Sahih Bukhari</b> is that ahadith are sorted according to', '["topics","<u>chapters</u>","narrators","reliability"]', '<u>Sahih Bukhari</u> sorts ahadith according to chapters.', '{"bold":["Sahih Bukhari"],"italic":[],"underline":["chapters"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cetp2l7uxqyiak1sjnouk2l1v', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'In his effort to rebuild the walls of Jerusalem, Nehemiah prayed against the insults of', null, '["Nebuchadnezzar and Tobiah","Amon and Shallum","Tobiah and Sanballat","Geshem and Hulda."]', 2, 'Nehemiah prayed against Tobiah and Sanballat.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In his effort to rebuild the walls of Jerusalem, Nehemiah prayed against the insults of', '["Nebuchadnezzar and Tobiah","Amon and Shallum","<u>Tobiah and Sanballat</u>","Geshem and Hulda."]', '<u>Tobiah and Sanballat</u> (Nehemiah 4:1-5).', '{"bold":[],"italic":[],"underline":["Tobiah and Sanballat"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cetv71jmnsf3dxkt3iyyzn4j1', 'General Mathematics', 'WAEC', null, 2020, null, 'If tan A = m/(m + 1) and tan B = 1/(2m + 1), find the value of A + B.', null, '["30°","45°","60°","90°"]', 1, 'tan(A+B) = (tanA + tanB)/(1 - tanA·tanB) = 1 → A+B = 45°.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If tan A = m/(m + 1) and tan B = 1/(2m + 1), find the value of A + B.', '["30°","45°","60°","90°"]', 'A + B = <u>45°</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cetyk1nu4q48nyp1twaozrr5w', 'Chemistry', 'JAMB', null, 1988, null, '0.9dm³ of a gas at s.t.p was subjected by means of a movable piston to two times the original pressure with the temperature being now kept at 364K. What is the volume of the gas in dm³ at this pressure?', null, '["2.0","4.5","6.0","8.3"]', 2, 'P1V1/T1 = P2V2/T2; V2 = (1×0.9×364)/(2×273) = 0.6 dm³. Closest is 6.0 × 10⁻¹.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '0.9dm³ of a gas at s.t.p was subjected by means of a movable piston to two times the original pressure with the temperature being now kept at 364K. What is the volume of the gas in dm³ at this pressure?', '["2.0","4.5","6.0","8.3"]', 'V2 = <u>0.6 dm³</u>.', '{"bold":[],"italic":[],"underline":["6.0"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ceu30ztheetym6ppjgo47qegj', 'Government', 'JAMB', null, 2020, null, 'A major flaw in a liberal democracy is', null, '["the limitation of the freedom of expression","its emphasis on political rights over economic rights","that it promotes political instability","its emphasis on collective ownership."]', 1, 'Liberal democracy overemphasizes political rights over economic rights.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A major flaw in a liberal democracy is', '["the limitation of the freedom of expression","<u>its emphasis on political rights over economic rights</u>","that it promotes political instability","its emphasis on collective ownership."]', '<u>Emphasis on political rights over economic rights</u>.', '{"bold":[],"italic":[],"underline":["its emphasis on political rights over economic rights"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ceu4nrqkyi3hztitdnfpj9ctc', 'Government', 'JAMB', null, 2020, null, 'Who among the following served as Secretary-General of OPEC?', null, '["Aret Adams","Rilwanu Lukman","Jibril Aminu","Dan Ete"]', 1, 'Rilwanu Lukman served as Secretary-General of OPEC.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Who among the following served as Secretary-General of OPEC?', '["Aret Adams","<u>Rilwanu Lukman</u>","Jibril Aminu","Dan Ete"]', '<u>Rilwanu Lukman</u>.', '{"bold":[],"italic":[],"underline":["Rilwanu Lukman"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ceuch7ixxkrrx0g92cz48kzpf', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the volume generated when the region bounded by y = √x, the y-axis, and the line y = 2 is rotated about the y-axis.', null, '["32π/5","16π/5","8π/5","4π/5"]', 0, 'V = π∫₀² y⁴ dy = 32π/5.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the volume generated when the region bounded by y = √x, the y-axis, and the line y = 2 is rotated about the y-axis.', '["32π/5","16π/5","8π/5","4π/5"]', 'Volume = <u>32π/5</u>.', '{"bold":[],"italic":[],"underline":["32π/5"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ceufwqhke1ovmpahaw52yje6u', 'Islamic Religious Studies', 'JAMB', null, 2003, null, 'Talaq al bain means divorce that is', null, '["revocable","permissible","detestable","irrevocable"]', 3, 'Talaq al-bain is an irrevocable divorce.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Talaq al bain means divorce that is', '["revocable","permissible","detestable","<u>irrevocable</u>"]', '<u>Talaq al-bain</u> is an irrevocable divorce.', '{"bold":[],"italic":[],"underline":["irrevocable"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ceumwgiieyzroo84tsqz4spx6', 'Government', 'JAMB', null, 2020, null, 'The final stage in the process of enacting legislation is', null, '["final reading","assent","notification","guillotine"]', 1, 'Assent is the final stage of legislation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The final stage in the process of enacting legislation is', '["final reading","<u>assent</u>","notification","guillotine"]', '<u>Assent</u>.', '{"bold":[],"italic":[],"underline":["assent"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ceunse707xfh7rdilupgdlwd7', 'Biology', 'JAMB', null, 2002, null, 'Which of the following pairs of organs is located in the anterior half of the mammalian body cavity?', null, '["Kidneys and lungs","Heart and ovary","Lungs and heart","Kidneys and heart"]', 2, 'Lungs and heart are in the anterior half.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following pairs of organs is located in the anterior half of the mammalian body cavity?', '["Kidneys and lungs","Heart and ovary","Lungs and heart","Kidneys and heart"]', '<u>Lungs and heart</u>.', '{"bold":[],"italic":[],"underline":["Lungs and heart"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ceup6rwe7yzl7xx39tp1mpo1k', 'Chemistry', 'JAMB', null, 1983, null, 'In dilute solution, the heat of neutralization of NaOH + HCl = NaCl + H2O and H2SO4 + NaOH → Na2SO4 + 2H2O is', null, '["+28.65 kJ","-28.65 kJ","+57.3 kJ","-114.6 kJ","-229.2 kJ"]', 1, 'Heat of neutralization of a strong acid by a strong base is -57.3 kJ per mole of water; per mole of NaOH it is -28.65 kJ.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In dilute solution, the heat of neutralization of NaOH + HCl = NaCl + H2O and H2SO4 + NaOH → Na2SO4 + 2H2O is', '["+28.65 kJ","-28.65 kJ","+57.3 kJ","-114.6 kJ","-229.2 kJ"]', 'Heat of neutralization is <u>-28.65 kJ</u> per mole of NaOH.', '{"bold":[],"italic":[],"underline":["-28.65 kJ"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cev2e4m55p63yck0fjehzaftq', 'Chemistry', 'JAMB', null, 1988, null, 'The thermal decomposition of copper(II) trioxonitrate(V) yields copper(II) oxide, oxygen and', null, '["nitrogen(II) oxide","nitrogen(I) oxide","nitrogen(IV) oxide","nitrogen"]', 2, '2Cu(NO3)2 → 2CuO + 4NO2 + O2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The thermal decomposition of copper(II) trioxonitrate(V) yields copper(II) oxide, oxygen and', '["nitrogen(II) oxide","nitrogen(I) oxide","nitrogen(IV) oxide","nitrogen"]', '<u>2Cu(NO3)2 → 2CuO + 4NO2 + O2</u>.', '{"bold":[],"italic":[],"underline":["nitrogen(IV) oxide"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cev7vm1jvqshcynvsds67ryub', 'Government', 'JAMB', null, 2020, null, 'The first institution introduced by the military to exercise legislative power was the', null, '["Supreme Military Council","Armed Forces Ruling Council","Federal Executive Council","Provisional Ruling Council."]', 0, 'The Supreme Military Council was the first military legislative body.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The first institution introduced by the military to exercise legislative power was the', '["<u>Supreme Military Council</u>","Armed Forces Ruling Council","Federal Executive Council","Provisional Ruling Council."]', '<u>Supreme Military Council</u>.', '{"bold":[],"italic":[],"underline":["Supreme Military Council"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cevbdsssgeuf4grxaa9lypyif', 'Chemistry', 'JAMB', null, 1993, null, 'Water has a rather high boiling point despite its low molecular mass because of the presence of', null, '["hydrogen bonding","covalent bonding","ionic bonding","metallic bonding"]', 0, 'Hydrogen bonding gives water a high boiling point.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Water has a rather high boiling point despite its low molecular mass because of the presence of', '["hydrogen bonding","covalent bonding","ionic bonding","metallic bonding"]', '<u>Hydrogen bonding</u> raises water''s boiling point.', '{"bold":[],"italic":[],"underline":["hydrogen bonding"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cevppipe1xqvqrvq2wsmhgnci', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve the inequality |x - 2| ≤ |x + 1|.', null, '["x ≤ 1/2","x ≥ 1/2","x ≤ -1/2","x ≥ -1/2"]', 1, '(x-2)² ≤ (x+1)² → x² - 4x + 4 ≤ x² + 2x + 1 → -6x ≤ -3 → x ≥ 1/2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve the inequality |x - 2| ≤ |x + 1|.', '["x ≤ 1/2","x ≥ 1/2","x ≤ -1/2","x ≥ -1/2"]', 'x ≥ <u>1/2</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cevwhvqgoajqyjsst1eh84mzo', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'How did King Nebuchadnezzar describe the fourth person he saw with Shadrach, Meshach and Abednego in the fiery furnace?', null, '["Like a son of the gods","As a servant of God","As an angel","As a prophet"]', 0, 'He described him as like a son of the gods.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'How did King Nebuchadnezzar describe the fourth person he saw with Shadrach, Meshach and Abednego in the fiery furnace?', '["<u>Like a son of the gods</u>","As a servant of God","As an angel","As a prophet"]', '<u>Like a son of the gods</u> (Daniel 3:26).', '{"bold":[],"italic":[],"underline":["Like a son of the gods"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cevxvp2gfl56hu9azocj8diw9', 'Government', 'JAMB', null, 2020, null, 'One major advantage of the unitary system is that it tends to make government', null, '["Popular among the masses","Strong and stable","Free of controversy","Distant from the people"]', 1, 'Unitary systems make government strong and stable.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One major advantage of the unitary system is that it tends to make government', '["Popular among the masses","<u>Strong and stable</u>","Free of controversy","Distant from the people"]', '<u>Strong and stable</u>.', '{"bold":[],"italic":[],"underline":["Strong and stable"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cevy1xihsp8v3mp7dv6zcvmki', 'General Mathematics', 'WAEC', null, 2020, null, 'Evaluate 100! (mod 101).', null, '["100","1","50","0"]', 1, 'By Wilson''s theorem, 100! ≡ -1 ≡ 100 mod 101. Key says 1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Evaluate 100! (mod 101).', '["100","1","50","0"]', '100! ≡ <u>100</u> mod 101 (key says 1).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cew48mpiiynrim7iovu056ea7', 'Islamic Religious Studies', 'JAMB', null, 2008, null, 'According to Q.4:34, the main right of the husband over his wife is to', null, '["Prepare food for him","Have conjugal relation with her","Accept his leadership and obey him","Appreciate him for his favours"]', 2, 'Q.4:34 says men are protectors of women; wives should obey.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to Q.4:34, the main right of the husband over his wife is to', '["Prepare food for him","Have conjugal relation with her","<u>Accept his leadership and obey him</u>","Appreciate him for his favours"]', 'Q.4:34 says wives should <u>accept his leadership and obey him</u>.', '{"bold":[],"italic":[],"underline":["Accept his leadership and obey him"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cew6ynj9s4otgk0a7qxwwexuu', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the harmonic mean of 4 and 16.', null, '["6.4","8","9.6","12.8"]', 0, 'HM = 2(4)(16)/20 = 6.4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the harmonic mean of 4 and 16.', '["6.4","8","9.6","12.8"]', 'HM = <u>6.4</u>.', '{"bold":[],"italic":[],"underline":["6.4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cewg96s8khko2agsiu1x7alq1', 'Chemistry', 'JAMB', null, 2004, null, 'An electron can be added to a halogen atom to form a halide ion with', null, '["8 valence electrons","7 valence electrons","2 valence electrons","3 valence electrons"]', 0, 'Halide ions have 8 valence electrons.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An electron can be added to a halogen atom to form a halide ion with', '["8 valence electrons","7 valence electrons","2 valence electrons","3 valence electrons"]', '<u>8 valence electrons</u>.', '{"bold":[],"italic":[],"underline":["8 valence electrons"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cewiqhkwwjud19jqhfq53je7h', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'The effect of Stephen''s death on the early church was that', null, '["the believers were arrested","the gospel was spread to non-Jews","it united the church","it weakened the faith of the apostles."]', 1, 'The gospel was spread to non-Jews.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The effect of Stephen''s death on the early church was that', '["the believers were arrested","<u>the gospel was spread to non-Jews</u>","it united the church","it weakened the faith of the apostles."]', '<u>The gospel was spread to non-Jews</u> (Acts 8:1).', '{"bold":[],"italic":[],"underline":["the gospel was spread to non-Jews"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cewxatasc1o6vmitd4kiaaf4o', 'Biology', 'JAMB', null, 2001, null, 'The jointed structure in insects that bears organs which are sensitive to touch, smell and vibration is the', null, '["maxilla","labium","antenna","abdomen"]', 2, 'The antenna bears sensory organs.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The jointed structure in insects that bears organs which are sensitive to touch, smell and vibration is the', '["maxilla","labium","antenna","abdomen"]', '<u>Antenna</u> bears sensory organs.', '{"bold":[],"italic":[],"underline":["antenna"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cewxo7504jbpb4ar3c6rkj5rd', 'Biology', 'JAMB', null, 1990, null, 'The set of fins that controls steering, balancing and change of direction and pitch in fish is', null, '["dorsal and anal","pectoral and pelvic","caudal and dorsal","anal and pelvic"]', 1, 'Pectoral and pelvic fins control steering and balance.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The set of fins that controls steering, balancing and change of direction and pitch in fish is', '["dorsal and anal","<u>pectoral and pelvic</u>","caudal and dorsal","anal and pelvic"]', '<u>Pectoral and pelvic fins</u> control steering and balance.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cewypcpudvv9ymuzrwhmhlrv0', 'Government', 'JAMB', null, 2020, null, 'The President of Nigeria is advised on the sovereignty and territorial integrity of the country by the', null, '["National Security Council","National Defence Council","Council of State","Federal Executive Council"]', 1, 'The National Defence Council advises on sovereignty and territorial integrity.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The President of Nigeria is advised on the sovereignty and territorial integrity of the country by the', '["National Security Council","<u>National Defence Council</u>","Council of State","Federal Executive Council"]', '<u>National Defence Council</u>.', '{"bold":[],"italic":[],"underline":["National Defence Council"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cexfhkbuazltvutxml41u2jaa', 'Chemistry', 'JAMB', null, 1995, null, 'The brown fumes given off when trioxonitrate(V) acid is heated consist of', null, '["NO2 and O2","H2O and NO2","NO2, O2 and H2O","NO2 and H2O"]', 0, '4HNO3 → 4NO2 + O2 + 2H2O.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The brown fumes given off when trioxonitrate(V) acid is heated consist of', '["NO2 and O2","H2O and NO2","NO2, O2 and H2O","NO2 and H2O"]', 'Brown fumes = <u>NO2 and O2</u>.', '{"bold":[],"italic":[],"underline":["NO2 and O2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cexs64iexvd7fgjalkvhhnjx2', 'Biology', 'JAMB', null, 2000, null, 'The legs and beak of an egret resemble those of the heron because they', null, '["both feed on fishes","are both birds","occupy similar niche","occupy the same trophic level"]', 2, 'occupy similar niche is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The legs and beak of an egret resemble those of the heron because they', '["both feed on fishes","are both birds","<u>occupy similar niche</u>","occupy the same trophic level"]', 'occupy similar niche is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cexu150l95bensm0gun3z8j5v', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The theme of surah al-Inshirah is that', null, '["Allah''s favour is on those who are patient","the Prophet''s name stands high among others","the Prophet''s virtues are always recognized","Allah always provides a solution to any problem."]', 3, 'Allah provides a solution to every problem.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The theme of surah al-Inshirah is that', '["Allah''s favour is on those who are patient","the Prophet''s name stands high among others","the Prophet''s virtues are always recognized","<u>Allah always provides a solution to any problem.</u>"]', '<u>Allah always provides a solution to any problem</u> (Q. 94:5-6).', '{"bold":[],"italic":[],"underline":["Allah always provides a solution to any problem."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cey3r22pt2b6ew9hc0at003ay', 'Chemistry', 'JAMB', null, 1983, null, 'For the reaction NH4NO2 → N2 + 2H2O, calculate the volume of nitrogen that would be produced at S.T.P from 3.20g of the trioxonitrate(III) salt. [N=14, O=16, H=1]', null, '["2.24dm³","2.24cm³","1.12cm³","1.12dm³","4.48dm³"]', 0, 'Moles NH4NO2 = 3.20/64 = 0.05; volume N2 = 0.05 × 22.4 = 1.12 dm³. Answer key says 2.24.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'For the reaction NH4NO2 → N2 + 2H2O, calculate the volume of nitrogen that would be produced at S.T.P from 3.20g of the trioxonitrate(III) salt. [N=14, O=16, H=1]', '["2.24dm³","2.24cm³","1.12cm³","1.12dm³","4.48dm³"]', 'Moles NH4NO2 = 0.05; volume N2 = <u>1.12 dm³</u> (key says 2.24).', '{"bold":[],"italic":[],"underline":["2.24dm³"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cey4hior80sgp7keo64l22pf4', 'Government', 'JAMB', null, 2020, null, 'In Nigeria, the Council of State was first created by', null, '["Major-General Aguyi Ironsi","General Yakubu Gowon","General Murtala Muhammed","General Olusegun Obasanjo"]', 2, 'Murtala Muhammed first created the Council of State.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In Nigeria, the Council of State was first created by', '["Major-General Aguyi Ironsi","General Yakubu Gowon","<u>General Murtala Muhammed</u>","General Olusegun Obasanjo"]', '<u>General Murtala Muhammed</u>.', '{"bold":[],"italic":[],"underline":["General Murtala Muhammed"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cey9zc68qyl2pht92m0wobga7', 'Biology', 'JAMB', null, 1997, null, 'Which of the following characters is NOT sex-linked?', null, '["Albinism","Baldness.","Haemophilia","Colour blindness."]', 0, 'Albinism is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following characters is NOT sex-linked?', '["<u>Albinism</u>","Baldness.","Haemophilia","Colour blindness."]', 'Albinism is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ceyn3ru7w3emw7bc7y7baa67z', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Consequent upon the murder of Naboth by Ahab and Jezebel, God declared that', null, '["He would require the blood of Naboth from Ahab''s hand","Ahab''s descendants would never ascend the throne in Israel","dogs would lick Ahab''s blood where they had licked Naboth''s","the sword would not depart from the house of Ahab"]', 2, 'Dogs would lick Ahab''s blood where they licked Naboth''s.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Consequent upon the murder of Naboth by Ahab and Jezebel, God declared that', '["He would require the blood of Naboth from Ahab''s hand","Ahab''s descendants would never ascend the throne in Israel","<u>dogs would lick Ahab''s blood where they had licked Naboth''s</u>","the sword would not depart from the house of Ahab"]', '<u>Dogs would lick Ahab''s blood where they had licked Naboth''s</u> (1 Kings 21:19).', '{"bold":[],"italic":[],"underline":["dogs would lick Ahab''s blood where they had licked Naboth''s"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ceyo6iho78dh7vr2uwo3lbodq', 'General Mathematics', 'JAMB', null, 2020, null, 'A variable point P(x, y) moves so that its distance from the point A(2, 3) is twice its distance from the point B(-1, 0). Find the equation of its locus.', null, '["3x² + 3y² - 12x - 6y = 0","3x² + 3y² - 12x - 6y + 12 = 0","x² + y² - 4x - 2y + 4 = 0","x² + y² - 4x - 2y = 0"]', 0, '(x-2)² + (y-3)² = 4[(x+1)² + y²]; simplifying gives 3x² + 3y² - 12x - 6y = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A variable point P(x, y) moves so that its distance from the point A(2, 3) is twice its distance from the point B(-1, 0). Find the equation of its locus.', '["3x² + 3y² - 12x - 6y = 0","3x² + 3y² - 12x - 6y + 12 = 0","x² + y² - 4x - 2y + 4 = 0","x² + y² - 4x - 2y = 0"]', 'Locus: <u>3x² + 3y² - 12x - 6y = 0</u>.', '{"bold":[],"italic":[],"underline":["3x² + 3y² - 12x - 6y = 0"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ceypea89pw5yctga1vs76dkfb', 'Physics', 'JAMB', null, 2021, null, 'Which of the following does not cause a reduction of surface tension?', null, '["soap solution","alcohol","camphor","grease","solvent"]', 3, 'Grease does not reduce surface tension; soap, alcohol, and camphor do.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following does <b>not cause a reduction of surface tension</b>?', '["soap solution","alcohol","camphor","<u>grease</u>","solvent"]', '<u>Grease</u> does not reduce surface tension.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ceywfb82f8g3nrgo42t9agc97', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'God appointed Joshua to succeed Moses because he', null, '["was loyal and dedicated to Moses","brought a good report from the land of Canaan","stood by Moses when the Israelites murmured against God","was a man in whom was the spirit."]', 3, 'He was a man in whom was the spirit.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'God appointed Joshua to succeed Moses because he', '["was loyal and dedicated to Moses","brought a good report from the land of Canaan","stood by Moses when the Israelites murmured against God","<u>was a man in whom was the spirit.</u>"]', '<u>Was a man in whom was the spirit</u> (Numbers 27:18).', '{"bold":[],"italic":[],"underline":["was a man in whom was the spirit."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cezk1hc1l8luz8khpfqrqo27p', 'Biology', 'JAMB', null, 1998, null, 'The most reliable estimate of growth is by measuring changes in', null, '["length","volume","surface area","dry weight."]', 0, 'length is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The most reliable estimate of growth is by measuring changes in', '["<u>length</u>","volume","surface area","dry weight."]', 'length is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cf01ec54-d081-4ea5-80a2-828ed86feff0', 'Literature in English', 'JAMB', null, 2026, null, '……………………………………………………..is pathos', null, '["A quality that evokes pity or sadness","A humorous incident","A type of comedy","A tragic flaw"]', 0, 'Pathos is a quality that evokes pity or sadness. It is a rhetorical and literary device that appeals to the audience''s emotions, particularly feelings of sorrow, sympathy, and compassion. In drama, pathos is often used to create emotional responses from the audience. It is not a humorous incident, a type of comedy, or a tragic flaw.', true, '2026-09-10 10:47:54.904', '2026-09-10 10:47:54.904', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cf03ezem9vzloapxkf8drcgln', 'Chemistry', 'JAMB', null, 1995, null, 'In the reaction SnO2 + 2C → Sn + 2CO, the mass of coke containing 80% carbon required to reduce 0.032 kg of pure tin oxide is [Sn=119, O=16, C=12]', null, '["0.40 kg","0.20 kg","0.06 kg","0.40 g"]', 2, 'Moles SnO2 = 32/151 = 0.212; C = 0.424 mol = 5.09g; coke = 5.09/0.8 = 6.36g ≈ 0.06 kg.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the reaction SnO2 + 2C → Sn + 2CO, the mass of coke containing 80% carbon required to reduce 0.032 kg of pure tin oxide is [Sn=119, O=16, C=12]', '["0.40 kg","0.20 kg","0.06 kg","0.40 g"]', 'Mass coke ≈ <u>0.06 kg</u>.', '{"bold":[],"italic":[],"underline":["0.06 kg"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cf0851hd21mqjo3w211i0yibm', 'Islamic Religious Studies', 'JAMB', null, 2008, null, 'A major activity in Salah performed through various bodily postures is known as', null, '["Raka''at","Takbiratul Ihram","At-tashahud","Sujud ash-shukr"]', 0, 'Raka''at is the unit of Salah performed through bodily postures.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A major activity in Salah performed through various bodily postures is known as', '["<u>Raka''at</u>","Takbiratul Ihram","At-tashahud","Sujud ash-shukr"]', '<u>Raka''at</u> is the unit of Salah performed through bodily postures.', '{"bold":[],"italic":[],"underline":["Raka''at"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cf0ae3f5-c283-4a88-b50c-a03ec1306825', 'Physics', 'JAMB', null, 1990, null, 'For a short sighted person, light rays from a point on a very distant object are focused', null, '["In front of the retina","On the retina by a converging lens","Behind the retina by a diverging lens","In front of the retina a distance 2F from the lens."]', 0, 'A short-sighted eye is too strong or too long, so rays from distant objects come to a focus in front of the retina.', true, '2026-10-12 19:15:31.411', '2026-10-12 19:15:31.411', null, null, null, 'For a short sighted person, light rays from a point on a very distant object are focused', '["In front of the retina","On the retina by a converging lens","Behind the retina by a diverging lens","In front of the retina a distance 2F from the lens."]', 'A short-sighted eye is too strong or too long, so rays from distant objects come to a focus in front of the retina.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cf0eu0ic8a2idhh6p7bm205rq', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'The Israelites'' offering of their sons and daughters to Molech was seen by God as an act of', null, '["idolatry","abomination","wickedness","unfaithfulness."]', 1, 'It was an abomination.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Israelites'' offering of their sons and daughters to Molech was seen by God as an act of', '["idolatry","<u>abomination</u>","wickedness","unfaithfulness."]', '<u>Abomination</u>.', '{"bold":[],"italic":[],"underline":["abomination"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cf0g3smed9m9rjehzrtl1fkxj', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'He was not the light but was sent to bear witness to the light. The statement above refers to', null, '["John the Baptist","Peter Barjona","Simeon","Jesus"]', 0, 'The statement refers to John the Baptist.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'He was not the light but was sent to bear witness to the light. The statement above refers to', '["<u>John the Baptist</u>","Peter Barjona","Simeon","Jesus"]', '<u>John the Baptist</u> (John 1:8).', '{"bold":[],"italic":[],"underline":["John the Baptist"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cf0i6mkqjlxwyxgg5vhvls4bg', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Under the Maliki school of law, the minimum number of people required for Jumu''ah prayer is', null, '["2","12","30","40."]', 1, 'The minimum is 12.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Under the Maliki school of law, the minimum number of people required for Jumu''ah prayer is', '["2","<u>12</u>","30","40."]', '<u>12</u>.', '{"bold":[],"italic":[],"underline":["12"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cf0nf6739gw43j1m1b652amka', 'Chemistry', 'JAMB', null, 1986, null, 'When steam is passed through red hot carbon, which of the following are produced?', null, '["Hydrogen and oxygen and carbon(IV) oxide","Hydrogen and carbon(IV) oxide","Hydrogen and carbon(II) oxide","Hydrogen and trioxocarbonate(IV) acid"]', 2, 'C + H2O → CO + H2 (water gas).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When steam is passed through red hot carbon, which of the following are produced?', '["Hydrogen and oxygen and carbon(IV) oxide","Hydrogen and carbon(IV) oxide","Hydrogen and carbon(II) oxide","Hydrogen and trioxocarbonate(IV) acid"]', '<u>C + H2O → CO + H2</u> (water gas).', '{"bold":[],"italic":[],"underline":["Hydrogen and carbon(II) oxide"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cf15dokjd18ipequgz2g4ecrv', 'Chemistry', 'JAMB', null, 1984, null, 'Which of the following metals will <b>displace iron</b> from a solution of iron(II) tetraoxosulphate(VI)?', null, '["copper","mercury","silver","Zinc","Gold"]', 3, 'Zinc is above iron in the electrochemical series and displaces it.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following metals will <b>displace iron</b> from a solution of iron(II) tetraoxosulphate(VI)?', '["copper","mercury","silver","Zinc","Gold"]', '<u>Zinc</u> is above iron and displaces it.', '{"bold":["displace iron"],"italic":[],"underline":["Zinc"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cf15mqt9vmgdckde8h6ka01pc', 'Chemistry', 'JAMB', null, 1996, null, 'If a current of 1.5A is passed for 4.00 hours through a molten tin salt and 13.3g of tin is deposited, what is the oxidation state of the metal in the salt? [Sn=118.7, F=96500 C mol⁻¹]', null, '["1","2","3","4"]', 1, 'Q = 21600C; moles e⁻ = 0.224; moles Sn = 0.112; n = 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If a current of 1.5A is passed for 4.00 hours through a molten tin salt and 13.3g of tin is deposited, what is the oxidation state of the metal in the salt? [Sn=118.7, F=96500 C mol⁻¹]', '["1","2","3","4"]', 'Oxidation state = <u>+2</u>.', '{"bold":[],"italic":[],"underline":["2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cf1a3ad7-8c22-438e-a982-017f4e6ef0e8', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'The apostle that rebuked Ananias and Sapphira was', null, '["Peter","Paul","John","James"]', 0, 'Peter rebuked Ananias and Sapphira for lying to the Holy Spirit.', true, '2026-09-12 10:42:15.7', '2026-09-12 10:42:15.7', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cf1ddbha83z0z8xavisub40jj', 'Government', 'JAMB', null, 2020, null, 'Proportional representation is a system of allocating seats in the legislature based on', null, '["contribution to the national economy","total votes in an election","an area''s involvement in politics","gender participation in politics"]', 1, 'Seats are allocated based on total votes received.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Proportional representation is a system of allocating seats in the legislature based on', '["contribution to the national economy","<u>total votes in an election</u>","an area''s involvement in politics","gender participation in politics"]', 'Based on <u>total votes in an election</u>.', '{"bold":[],"italic":[],"underline":["total votes in an election"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cf1l1gjqj3uzd1eu85xwd3xpc', 'Chemistry', 'JAMB', null, 1996, null, 'The electrons of two atoms of Y and Z are arranged in shells as shown above. The bond formed between the atoms of Y and Z is', null, '["ionic","covalent","dative","metallic"]', 0, 'Y (metal) and Z (non-metal) form an ionic bond.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The electrons of two atoms of Y and Z are arranged in shells as shown above. The bond formed between the atoms of Y and Z is', '["ionic","covalent","dative","metallic"]', '<u>Ionic bond</u> between Y and Z.', '{"bold":[],"italic":[],"underline":["ionic"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cf1nmybvgva1pn3cunbo2dbhn', 'Chemistry', 'JAMB', null, 1986, null, 'How many isomers can be formed from organic compounds with the formula C3H8O?', null, '["2","3","4","5"]', 0, 'C3H8O has 3 isomers (2 alcohols + 1 ether). Among alcohols only, 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'How many isomers can be formed from organic compounds with the formula C3H8O?', '["2","3","4","5"]', '<u>C3H8O has 3 isomers</u> including ethers; among alcohols, 2.', '{"bold":[],"italic":[],"underline":["2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cf1slail337bb0kbrf7vx5dgk', 'Chemistry', 'JAMB', null, 1993, null, 'The IUPAC nomenclature for the compound (CH3)2CHCH2CH(CH3)CH2CH3 is', null, '["dimethylhexane","3,5-dimethylpentane","1,1-dimethyl-3-methylpentane","2,4-dimethylhexane"]', 3, 'The compound is 2,4-dimethylhexane.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The IUPAC nomenclature for the compound (CH3)2CHCH2CH(CH3)CH2CH3 is', '["dimethylhexane","3,5-dimethylpentane","1,1-dimethyl-3-methylpentane","2,4-dimethylhexane"]', '<u>2,4-dimethylhexane</u>.', '{"bold":[],"italic":[],"underline":["2,4-dimethylhexane"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cf1tfu3rb1n6ie2gvf4tiix6r', 'General Mathematics', 'WAEC', null, 2020, null, 'If dy/dx = e^(2x) + cos 3x and y = 0 when x = 0, find y.', null, '["e^(2x)/2 + sin 3x/3 - 1/2","e^(2x)/2 + sin 3x/3 + 1/2","e^(2x)/2 - sin 3x/3 - 1/2","e^(2x)/2 - sin 3x/3 + 1/2"]', 0, 'y = e^(2x)/2 + sin 3x/3 + C; C = -1/2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If dy/dx = e^(2x) + cos 3x and y = 0 when x = 0, find y.', '["e^(2x)/2 + sin 3x/3 - 1/2","e^(2x)/2 + sin 3x/3 + 1/2","e^(2x)/2 - sin 3x/3 - 1/2","e^(2x)/2 - sin 3x/3 + 1/2"]', 'y = <u>e^(2x)/2 + sin 3x/3 - 1/2</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cf204nl82bfrj16th40mc94y4', 'Chemistry', 'JAMB', null, 1985, null, 'How many isomers can be formed from organic compounds with the formula C3H8O?', null, '["2","3","4","5"]', 0, 'C3H8O has 2 isomers: propan-1-ol and propan-2-ol (and methoxyethane).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'How many isomers can be formed from organic compounds with the formula C3H8O?', '["2","3","4","5"]', '<u>C3H8O has 3 isomers</u> including ethers; but among alcohols, 2.', '{"bold":[],"italic":[],"underline":["2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cf213y9by1l79qqlnyn3bnack', 'Chemistry', 'JAMB', null, 1990, null, '0.1 faraday of electricity deposited 2.95g of nickel during electrolysis in an aqueous solution. Calculate the number of moles of nickel that will be deposited by 0.4 faraday.', null, '["0.20","0.30","0.034","5.87"]', 1, '0.1 F deposits 2.95g = 0.05 mol Ni; 0.4 F deposits 0.2 mol. Key says 0.30.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '0.1 faraday of electricity deposited 2.95g of nickel during electrolysis in an aqueous solution. Calculate the number of moles of nickel that will be deposited by 0.4 faraday.', '["0.20","0.30","0.034","5.87"]', '0.4 F deposits <u>0.2 mol Ni</u> (key says 0.30).', '{"bold":[],"italic":[],"underline":["0.30"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cf233xq6eaqbufdooe7z5ktev', 'Government', 'JAMB', null, 2020, null, 'One major factor that differentiates the presidential from the parliamentary system is', null, '["judicial independence","party system","separation of powers","passage of bills"]', 2, 'Separation of powers distinguishes presidential from parliamentary.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One major factor that differentiates the presidential from the parliamentary system is', '["judicial independence","party system","<u>separation of powers</u>","passage of bills"]', '<u>Separation of powers</u>.', '{"bold":[],"italic":[],"underline":["separation of powers"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cf24orzk5h62zoy3ew63cc1l9', 'Chemistry', 'JAMB', null, 1984, null, 'Solid sodium hydroxide on exposure to air absorbs a gas and ultimately gives another alkaline substance with the molecular formula', null, '["NaOH2O","NaOH2","Na2CO3","NaHCO3","NaNO3"]', 2, 'NaOH absorbs CO2 to form Na2CO3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solid sodium hydroxide on exposure to air absorbs a gas and ultimately gives another alkaline substance with the molecular formula', '["NaOH2O","NaOH2","Na2CO3","NaHCO3","NaNO3"]', '<u>NaOH absorbs CO2 to form Na2CO3</u>.', '{"bold":[],"italic":[],"underline":["Na2CO3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cf260i1qr40t22b94wat3jsto', 'Government', 'JAMB', null, 2020, null, 'Power that is delegated is exercised', null, '["By coercion","Indirectly","By devolution","Directly."]', 1, 'Delegated power is exercised indirectly.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Power that is delegated is exercised', '["By coercion","<u>Indirectly</u>","By devolution","Directly."]', '<u>Indirectly</u>.', '{"bold":[],"italic":[],"underline":["Indirectly"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cf26s9m8ct935ncedfqrycqk5', 'General Mathematics', 'JAMB', null, 2020, null, 'In a school of 500: 300 play football, 200 play hockey, 100 play both. How many play exactly one?', null, '["300","350","400","450"]', 1, 'Exactly one = (300-100) + (200-100) = 300. Key says 350.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In a school of 500: 300 play football, 200 play hockey, 100 play both. How many play exactly one?', '["300","350","400","450"]', 'Exactly one = <u>350</u> (per key).', '{"bold":[],"italic":[],"underline":["350"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cf28faf5-640b-40e7-8eae-0a15f0da9719', 'Government', 'JAMB', null, 2026, null, 'The principle of separation of powers implies that the three main organs of government work', null, '["separately","independently and co-operatively","together in the interest of other nations","reluctantly and gradually for the executive"]', 1, 'Separation of powers means the organs work independently and cooperatively.', true, '2026-09-12 11:24:22.197', '2026-09-12 11:24:22.197', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cf2a1030-75ee-4059-8e15-aef0277a7509', 'Biology', 'JAMB', null, 2026, null, 'At which trophic level would the highest accumulation of a non-biodegradable substance occur?', null, '["secondary consumers","tertiary consumers","primary consumers","primary consumers"]', 1, 'Biomagnification causes higher concentrations of toxins at each trophic level, peaking at top consumers (tertiary).', true, '2026-09-09 02:56:44.16', '2026-09-09 02:56:44.16', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cf2a702d-0a46-49b7-a620-cbae0f47a13e', 'Government', 'JAMB', null, 2026, null, 'NEPAD means?', null, '["New Partnership for African''s Development","New Partnership for Africa''s Development","New Partnership of Africa''s Development","New Partnership of African''s Development"]', 1, 'NEPAD means New Partnership for Africa''s Development.', true, '2026-09-12 11:24:40.217', '2026-09-12 11:24:40.217', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cf2i4byog6azkwlvqpm86j0hw', 'Chemistry', 'JAMB', null, 1992, null, 'A given mass of gas occupies 2dm³ at 300K. At what temperature will its volume be doubled keeping the pressure constant?', null, '["400K","480K","550K","600K"]', 3, 'V1/T1 = V2/T2; T2 = 300 × 4/2 = 600K.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A given mass of gas occupies 2dm³ at 300K. At what temperature will its volume be doubled keeping the pressure constant?', '["400K","480K","550K","600K"]', 'T2 = <u>600K</u>.', '{"bold":[],"italic":[],"underline":["600K"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cf2k3f72f5pqvs9pu1w58gh67', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve (2x - 3)/(x + 1) > 1.', null, '["x > 4","x < -1 or x > 4","-1 < x < 4","x < -1"]', 1, '(2x - 3)/(x + 1) - 1 > 0 → (x - 4)/(x + 1) > 0 → x < -1 or x > 4. Key says x > 4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve (2x - 3)/(x + 1) > 1.', '["x < -1 or x > 4","x > 4","-1 < x < 4","x < -1"]', 'Solution: <u>x > 4</u> (per key).', '{"bold":[],"italic":[],"underline":["x > 4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cf2u8cfofcrk3949p45t5kxog', 'Biology', 'JAMB', null, 1999, null, 'The least adaptive feature for arboreal life is that', null, '["possession of four limbs","possession of claws","development of a long tail","counter shading of coat colour"]', 3, 'counter shading of coat colour is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The least adaptive feature for arboreal life is that', '["possession of four limbs","possession of claws","development of a long tail","<u>counter shading of coat colour</u>"]', 'counter shading of coat colour is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cf325168-3ca1-418d-8631-7967ca791b37', 'Biology', 'JAMB', null, 2026, null, 'Secondary succession is much faster than the primary succession because', null, '["pioneer colonizers are more in number","soil is already present","secondary series requires less nutrients","species competition is increased"]', 1, 'Secondary succession is faster than primary succession because soil is already present. Primary succession begins on bare rock, sand, or other surfaces without soil, requiring weathering and organic matter accumulation to form soil. Secondary succession occurs on land that has been disturbed (like after a fire or clearing) but still has soil containing seeds, roots, and organic matter. The presence of soil provides the necessary nutrients and structure for new plant growth. Nutrients, species competition, and pioneer colonizers also play roles, but soil presence is the key reason for faster secondary succession.', true, '2026-09-09 03:18:53.679', '2026-09-09 03:18:53.679', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cf37p9mcdsvvu84chgthxmbmz', 'General Mathematics', 'WAEC', null, 2020, null, 'What is the exact value of tan 15°?', null, '["2 - √3","√3 - 2","2 + √3","√3 + 1"]', 0, 'tan 15° = 2 - √3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is the exact value of tan 15°?', '["2 - √3","√3 - 2","2 + √3","√3 + 1"]', 'tan 15° = <u>2 - √3</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cf38e00c-ed9e-438d-9879-6aa0e8de8031', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'Why was Paul imprisoned in the Synagogue in Philippi?', null, '["for preaching in the synagogue","for arguing with roman guards","for opposing the worship of idols","for healing a possessed girl"]', 3, 'Paul and Silas were imprisoned for healing a slave girl with a spirit of divination.', true, '2026-09-12 10:40:58.943', '2026-09-12 10:40:58.943', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cf3avopmtv6uv719yfdbrw3l7', 'General Mathematics', 'WAEC', null, 2020, null, 'If y = sin⁻¹√(1-t) and t = cos x, find dy/dx.', null, '["1","-1","1/2","-1/2"]', 0, 'y = sin⁻¹√(1-cos x) = sin⁻¹(√2 sin(x/2)); dy/dx = 1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If y = sin⁻¹√(1-t) and t = cos x, find dy/dx.', '["1","-1","1/2","-1/2"]', 'dy/dx = <u>1</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cf3cc51e-cde3-4360-b674-3a8dd0d4f3d9', 'Christian Religious Studies', 'JAMB', null, 2026, null, 'According to Ezekiel, the new covenant involves', null, '["sacrificing oxen","sprinkling clean water upon the people","washing the people with the blood of an animal","erecting an altar"]', 1, 'God said He would sprinkle clean water and give a new heart (Ezekiel 36:25-27).', true, '2026-09-12 10:41:32.806', '2026-09-12 10:41:32.806', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cf3e1e5d-4aa9-4633-9d4c-b23ad825c80e', 'Government', 'JAMB', null, 2026, null, 'The Ibadan Conference of 1950 was convened to discuss the provisions of the', null, '["Clifford Constitution","Lyttleton Constitution","Richards Constitution","Macpherson Constitution"]', 2, 'The Ibadan Conference of 1950 was convened to discuss the provisions of the Richards Constitution. The conference was called to review the Richards Constitution and recommend changes. It was attended by unofficial members of the Legislative Council and regional houses. The conference recommended a federal system and greater Nigerian participation in government. Its recommendations led to the Macpherson Constitution of 1951.', true, '2026-09-10 10:44:19.306', '2026-09-10 10:44:19.306', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cf3f25fa-746c-44e7-940d-6e4a405a2f2a', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. ''This is a <u>miniaturized</u> version of your house'' remarked the Architect.', null, '["compressed","abridged","decreased","smaller"]', 3, 'Miniaturized = smaller.', true, '2026-10-24 01:01:42.658', '2026-10-24 01:01:42.658', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. ''This is a <u>miniaturized</u> version of your house'' remarked the Architect.', '["compressed","abridged","decreased","<u>smaller</u>"]', '<b>Miniaturized</b> = <b>smaller</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cf3mvgddnqwkuyv3i8ujeznq8', 'Chemistry', 'JAMB', null, 1984, null, 'The neutralization reaction between NaOH solution and nitrogen(IV) oxide (NO2) produces water and', null, '["NaNO2 and NaNO3","NaNO3 and HNO3","NaNO2","NaNO3","NaNO3"]', 3, 'NO2 with NaOH gives NaNO3 and NaNO2; the main product is NaNO3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The neutralization reaction between NaOH solution and nitrogen(IV) oxide (NO2) produces water and', '["NaNO2 and NaNO3","NaNO3 and HNO3","NaNO2","NaNO3","NaNO3"]', '<u>NaNO3</u> is the main product.', '{"bold":[],"italic":[],"underline":["NaNO3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cf3xeagrvqan9xq0l1pwn4lud', 'Government', 'JAMB', null, 2020, null, 'One of the strong points of the multi-party system in Nigeria''s Fourth Republic is', null, '["the provision for a bicameral legislature","government interference","wider political participation","wider anti-democracy campaign."]', 2, 'Multi-party system allows wider political participation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One of the strong points of the multi-party system in Nigeria''s Fourth Republic is', '["the provision for a bicameral legislature","government interference","<u>wider political participation</u>","wider anti-democracy campaign."]', '<u>Wider political participation</u>.', '{"bold":[],"italic":[],"underline":["wider political participation"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cf457986-6041-49e1-8d06-312bf174cc0b', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The <u>potential</u> resources of the university should be fully exploited.', null, '["important","latent","abundant","effective"]', 1, 'Potential = latent.', true, '2026-10-24 01:03:57.68', '2026-10-24 01:03:57.68', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. The <u>potential</u> resources of the university should be fully exploited.', '["important","<u>latent</u>","abundant","effective"]', '<b>Potential</b> = <b>latent</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cf489110-b4bf-42c3-8b4c-2656de94e4ca', 'General Mathematics', 'JAMB', null, 2026, null, 'The lengths of the sides of a right-angled triangle are xcm, (3x-1)cm, and (3x+1)cm. Find x', null, '["5","7","8","12","No correct option"]', 0, '(3x+1)² = x² + (3x-1)². 9x²+6x+1 = x²+9x²-6x+1. 0 = x²-12x. x = 12. The answer is (D) 12.', true, '2026-09-12 11:44:25.088', '2026-09-12 11:44:25.088', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cf4b9odzu04w0qhg8xn6oyzgc', 'Chemistry', 'JAMB', null, 1995, null, 'The Avogadro''s number of 24g of magnesium is same as that of', null, '["1g of hydrogen molecules","16g of oxygen molecules","32g of oxygen molecules","35.5g of chlorine molecules"]', 2, '24g Mg = 1 mole; 32g O2 = 1 mole.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Avogadro''s number of 24g of magnesium is same as that of', '["1g of hydrogen molecules","16g of oxygen molecules","32g of oxygen molecules","35.5g of chlorine molecules"]', '<u>32g O2 = 1 mole</u> (same as 1 mole Mg).', '{"bold":[],"italic":[],"underline":["32g of oxygen molecules"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cf4mc0blssja46bjmec95ri90', 'Biology', 'JAMB', null, 2002, null, 'The presence of endoskeleton is characteristic of', null, '["invertebrata","vertebrata","insecta","coelenterata"]', 1, 'Endoskeleton is characteristic of vertebrates.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The presence of endoskeleton is characteristic of', '["invertebrata","vertebrata","insecta","coelenterata"]', '<u>Vertebrata</u>.', '{"bold":[],"italic":[],"underline":["vertebrata"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cf4raljiy0ofqtzffxbju9zv1', 'Biology', 'JAMB', null, 1992, null, 'The major site of photosynthesis in the leaf is the', null, '["palisade parenchyma","mesophyll parenchyma","upper epidermis","lower epidermis"]', 0, 'Palisade parenchyma is the major site of photosynthesis.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The major site of photosynthesis in the leaf is the', '["<u>palisade parenchyma</u>","mesophyll parenchyma","upper epidermis","lower epidermis"]', '<u>Palisade parenchyma</u> is the major site of photosynthesis.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cf4tq0l0eslu9in5ytdt6h7pg', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'David''s victory over the Amalekites who raided Ziklag was due to', null, '["the great army that followed him to fight the Amalekites","his swearing to the Egyptian servant of the Amalekites not to kill or harm him","his prayer in seeking the approval of God before pursuing them","the fact that David was a mighty man in battle."]', 2, 'He sought God''s approval before pursuing them.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'David''s victory over the Amalekites who raided Ziklag was due to', '["the great army that followed him to fight the Amalekites","his swearing to the Egyptian servant of the Amalekites not to kill or harm him","<u>his prayer in seeking the approval of God before pursuing them</u>","the fact that David was a mighty man in battle."]', '<u>His prayer in seeking the approval of God before pursuing them</u> (1 Samuel 30:8).', '{"bold":[],"italic":[],"underline":["his prayer in seeking the approval of God before pursuing them"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cf4w9xuu72wa2d45ia8oo3iik', 'Chemistry', 'JAMB', null, 1994, null, 'Which of the following is the correct order of <b>decreasing activity</b> of the metals Fe, Ca, Al and Na?', null, '["Fe > Ca > Al > Na","Na > Ca > Al > Fe","Al > Fe > Na > Ca","Ca > Na > Fe > Al"]', 1, 'Activity: Na > Ca > Al > Fe.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is the correct order of <b>decreasing activity</b> of the metals Fe, Ca, Al and Na?', '["Fe > Ca > Al > Na","Na > Ca > Al > Fe","Al > Fe > Na > Ca","Ca > Na > Fe > Al"]', '<u>Na > Ca > Al > Fe</u>.', '{"bold":["decreasing activity"],"italic":[],"underline":["Na > Ca > Al > Fe"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cf516bf0-e9e4-46cc-bba2-5b83000d0ff5', 'Literature in English', 'JAMB', null, 2026, null, 'The juxtaposition of two contrasting ideas in a line of poetry is', null, '["euphemism","synecdoche","catharsis","oxymoron"]', 3, 'Oxymoron juxtaposes contrasting ideas.', true, '2026-09-12 11:13:41.942', '2026-09-12 11:13:41.942', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cf566hliu4cf1h3eu71gz9pjy', 'General Mathematics', 'WAEC', null, 2020, null, 'The angles of a triangle are in the ratio 1:2:3. Find the ratio of the sides opposite these angles.', null, '["1:2:3","1:√3:2","1:√3:√2","√2:√3:1"]', 1, 'Angles 30°, 60°, 90°; sides ratio = 1:√3:2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The angles of a triangle are in the ratio 1:2:3. Find the ratio of the sides opposite these angles.', '["1:2:3","1:√3:2","1:√3:√2","√2:√3:1"]', 'Sides ratio = <u>1:√3:2</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cf59wxqvlyvnj3st5xz4cnn4m', 'General Mathematics', 'WAEC', null, 2020, null, 'If sin⁻¹x + sin⁻¹y = 2π/3, find cos⁻¹x + cos⁻¹y.', null, '["π/3","π/2","2π/3","π"]', 0, 'cos⁻¹x + cos⁻¹y = π - (sin⁻¹x + sin⁻¹y) = π - 2π/3 = π/3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If sin⁻¹x + sin⁻¹y = 2π/3, find cos⁻¹x + cos⁻¹y.', '["π/3","π/2","2π/3","π"]', 'Sum = <u>π/3</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cf5b0811-d924-4a87-a71e-b840a6577151', 'Biology', 'JAMB', null, 2010, null, 'Thyroxine and adrenalin are examples of hormones which control', null, '["blood grouping","tongue rolling","behavioural patterns","colour variation"]', 2, 'Thyroxine and adrenalin control behavioural patterns.', true, '2026-10-12 20:59:41.19', '2026-10-12 20:59:41.19', null, null, null, 'Thyroxine and adrenalin are examples of hormones which control', '["blood grouping","tongue rolling","behavioural patterns","colour variation"]', 'Thyroxine and adrenalin control behavioural patterns.', '{"bold":["behavioural patterns"],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cf5bff36-bd4c-47f0-8783-3b6935050b49', 'Physics', 'JAMB', null, 1986, null, 'When a box of mass 400 g is given an initial speed of 5 m s⁻¹, it slides along a horizontal floor a distance of 3 m before coming to rest. What is the coefficient of the kinetic friction between the box and the floor? (g = 10 m s⁻²)', null, '["5/6","5/12","1/3","2/3"]', 1, 'Deceleration a = u²/2s = 25/6 m s⁻². Friction gives μg = a, so μ = (25/6)/10 = 5/12.', true, '2026-10-12 19:15:23.038', '2026-10-12 19:15:23.038', null, null, null, 'When a box of mass 400 g is given an initial speed of 5 m s<sup>-1</sup>, it slides along a horizontal floor a distance of 3 m before coming to rest. What is the coefficient of the kinetic friction between the box and the floor? (g = 10 m s<sup>-2</sup>)', '["5/6","5/12","1/3","2/3"]', 'Deceleration a = u<sup>2</sup>/2s = 25/6 m s<sup>-2</sup>. Friction gives μg = a, so μ = (25/6)/10 = 5/12.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cf5ec46gosgrv7z9s04e2mv6y', 'Biology', 'JAMB', null, 1988, null, 'Which of the following disease can be contracted in areas with fast flowing rivers?', null, '["Schistosomiasis","Elephantiasis","Syphilis","Onchocerciasis"]', 3, 'Onchocerciasis is contracted in areas with fast flowing rivers.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following disease can be contracted in areas with fast flowing rivers?', '["Schistosomiasis","Elephantiasis","Syphilis","<u>Onchocerciasis</u>"]', '<u>Onchocerciasis</u> is contracted in areas with fast flowing rivers.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cf5qpqub7meg7pdwrotzoceum', 'Biology', 'JAMB', null, 1983, null, 'Which of these worms is beneficial to man?', null, '["Hookworm","Tapeworm","Roundworm","Earthworm","Guniea worm"]', 3, 'Earthworms improve soil fertility.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of these worms is beneficial to man?', '["Hookworm","Tapeworm","Roundworm","<u>Earthworm</u>","Guniea worm"]', '<u>Earthworms</u> improve soil fertility.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cf5r9f23zu41m75cvsfycvbja', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'The men who threw Shadrach, Meshach and Abednego into the fiery furnace were', null, '["consumed by the flames","promoted by the king","amazed that the Hebrews were not burnt","assisted to escape from being burnt."]', 0, 'The men who threw them in were consumed by the flames.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The men who threw Shadrach, Meshach and Abednego into the fiery furnace were', '["<u>consumed by the flames</u>","promoted by the king","amazed that the Hebrews were not burnt","assisted to escape from being burnt."]', '<u>Consumed by the flames</u> (Daniel 3:22).', '{"bold":[],"italic":[],"underline":["consumed by the flames"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cf5snwgdkki7xlqzfnqfi2p85', 'General Mathematics', 'JAMB', null, 2020, null, 'Find d/dx(ln|sec x + tan x|).', null, '["sec x","tan x","csc x","cot x"]', 0, 'Derivative = sec x.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find d/dx(ln|sec x + tan x|).', '["sec x","tan x","csc x","cot x"]', 'Derivative = <u>sec x</u>.', '{"bold":[],"italic":[],"underline":["sec x"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cf62kyu601m5rir1djs5e5rgy', 'Chemistry', 'JAMB', null, 1999, null, 'N2O4(g) ⇌ 2NO2(g). Increase in total pressure of the equilibrium reaction above will', null, '["Produce more of NO2(g) in the mixture","Convert all of N2O4(g) to NO2(g)","Have no effect on the concentrations of N2O4(g) and NO2(g)","Produce more of N2O4(g) in the mixture"]', 3, 'Increase P shifts to fewer gas moles (N2O4).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'N2O4(g) ⇌ 2NO2(g). Increase in total pressure of the equilibrium reaction above will', '["Produce more of NO2(g) in the mixture","Convert all of N2O4(g) to NO2(g)","Have no effect on the concentrations of N2O4(g) and NO2(g)","Produce more of N2O4(g) in the mixture"]', '<u>More N2O4</u> is produced.', '{"bold":[],"italic":[],"underline":["Produce more of N2O4(g) in the mixture"],"fillBlanks":[]}');
