insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cf7gmqv21316nhgc9j7feu513', 'General Mathematics', 'WAEC', null, 2020, null, 'If one root of x³ - 4x² + 5x - 2 = 0 is 1 (double), find the third root.', null, '["2","3","1","0"]', 0, '(x-1)²(x-2) = 0 → roots 1, 1, 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If one root of x³ - 4x² + 5x - 2 = 0 is 1 (double), find the third root.', '["2","3","1","0"]', 'Third root = <u>2</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cf7tk3zcl01bmp6n3cknrb4u8', 'Biology', 'JAMB', null, 1986, null, 'Which is the correct order of water loss from the leaf? 1 Mesophyll 2 Veins 3 Substantial cavity 4 Stomata', null, '["3-2-1-4","2-3-1-4","2-1-3-4","1-2-3-4"]', 2, 'Water loss order: Veins (2) → Mesophyll (1) → Substantial cavity (3) → Stomata (4).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which is the correct order of water loss from the leaf?<br>1 Mesophyll<br>2 Veins<br>3 Substantial cavity<br>4 Stomata', '["3-2-1-4","2-3-1-4","<u>2-1-3-4</u>","1-2-3-4"]', 'Water loss order: <u>Veins (2) → Mesophyll (1) → Substantial cavity (3) → Stomata (4)</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cf8181f6-24e0-4274-9b30-93bfb812658d', 'English Language', 'JAMB', null, 2007, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. He is known for making <u>threadbare</u> arguments as a scholar.', null, '["justified","baseless","empty","militant"]', 0, 'Threadbare = weak/hackneyed; opposite = justified.', true, '2026-10-24 07:21:27.776', '2026-10-24 07:21:27.776', null, null, null, 'Choose the option opposite in meaning to the word(s) or phrase in italics and underlined. He is known for making <u>threadbare</u> arguments as a scholar.', '["justified","baseless","empty","militant"]', 'Threadbare = weak/hackneyed; opposite = justified.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cf8740z1iz4o5aeo2q32jer7s', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'According to Paul''s letter to the Philippians, Christ demonstrated His humility by', null, '["dying on the cross","taking the form of a servant","praying for His enemies","washing the feet of His disciples."]', 1, 'Christ took the form of a servant.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to Paul''s letter to the Philippians, Christ demonstrated His humility by', '["dying on the cross","<u>taking the form of a servant</u>","praying for His enemies","washing the feet of His disciples."]', '<u>Taking the form of a servant</u> (Philippians 2:5-7).', '{"bold":[],"italic":[],"underline":["taking the form of a servant"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cf8806e8-9b74-4888-a87b-be62dcbac49a', 'English Language', 'JAMB', null, 2007, null, '(Choose the most appropriate interpretation). The cooperate existence of any nation is in jeopardy if her leaders <u>pay lip service to her unity</u>', null, '["injured his foot while entering his office","started off badly","made a costly mistake","stepped on the wrong toes"]', 3, 'Note: garbled source. Closest option chosen.', true, '2026-10-24 01:04:20.612', '2026-10-24 01:04:20.612', null, null, null, '(Choose the most appropriate interpretation). The cooperate existence of any nation is in jeopardy if her leaders <u>pay lip service to her unity</u>', '["injured his foot while entering his office","started off badly","made a costly mistake","<u>stepped on the wrong toes</u>"]', 'Note: <b>garbled source</b>. Closest option chosen.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cf8a6e79-b50e-47ef-8859-bd29a0da5cc7', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. That <u>fateful</u> decision changed the company''s outlook in many ways.', null, '["disastrous","unsuccessful","wonderful","uncontrollable"]', 0, 'Fateful = disastrous.', true, '2026-10-24 01:01:53.482', '2026-10-24 01:01:53.482', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. That <u>fateful</u> decision changed the company''s outlook in many ways.', '["<u>disastrous</u>","unsuccessful","wonderful","uncontrollable"]', '<b>Fateful</b> = <b>disastrous</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cf8bb479-7267-49b7-8537-b40fa38a1675', 'English Language', 'JAMB', null, 2007, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Her findings <u>exploded</u> widely held beliefs about learning.', null, '["challenged","projected","debunked","confirmed"]', 2, 'Exploded = debunked.', true, '2026-10-24 01:01:55.65', '2026-10-24 01:01:55.65', null, null, null, 'Choose the option nearest in meaning to the word(s) or phrase in italics and underlined. Her findings <u>exploded</u> widely held beliefs about learning.', '["challenged","projected","<u>debunked</u>","confirmed"]', '<b>Exploded</b> = <b>debunked</b>.', '{}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cf8c854f-e1d8-4b47-8205-dba257c93a64', 'Biology', 'JAMB', null, 2026, null, 'The primary structure responsible for pumping blood for circulation in mammals is the', null, '["Veins","Right auricle","Arteries","Left ventricle"]', 3, 'The left ventricle is the primary structure responsible for pumping blood for circulation in mammals. It has the thickest walls of all heart chambers because it must pump blood through the systemic circulation to the entire body. The right ventricle pumps blood to the lungs. Veins return blood to the heart. Arteries carry blood away from the heart. The left ventricle''s powerful contractions create the blood pressure that drives systemic circulation.', true, '2026-09-09 03:19:03.807', '2026-09-09 03:19:03.807', null, null, null, null, null, null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cf8f3655-8af8-43d9-885a-775e223ffab4', 'Financial Accounting', 'UTME', null, 2004, null, 'What are the appropriate recording procedures for entries in the trial balance?', null, '["source document, ledger and trial balance","ledgers, trial balance and source document","cash account, ledger and trial balance","ledger, source document and trial balance"]', 0, 'The appropriate recording procedures for entries in the trial balance are source document, ledger and trial balance.', true, '2026-10-12 22:00:01.853', '2026-10-12 22:00:01.853', null, null, null, 'What are the appropriate recording procedures for entries in the trial balance?', '["<b>source document, ledger and trial balance</b>","ledgers, trial balance and source document","cash account, ledger and trial balance","ledger, source document and trial balance"]', 'The appropriate recording procedures for entries in the trial balance are <b>source document, ledger and trial balance</b>.', '{"bold":["source document, ledger and trial balance"],"italic":[],"underline":[],"fillBlanks":[]}');
