insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cf939507-dde2-41c6-8536-7d3ba2470e72', 'Physics', 'JAMB', null, 2004, null, 'A machine whose efficiency is 60% has a velocity ratio of 5. If a force of 500 N is applied to lift a load P, what is the magnitude of P?', null, '["750 N","4166 N","50 N","1500 N"]', 3, 'MA = efficiency x VR = 0.6 x 5 = 3. Load = MA x effort = 3 x 500 = 1500 N.', true, '2026-10-12 19:15:58.606', '2026-10-12 19:15:58.606', null, null, null, 'A machine whose efficiency is 60% has a velocity ratio of 5. If a force of 500 N is applied to lift a load P, what is the magnitude of P?', '["750 N","4166 N","50 N","1500 N"]', 'MA = efficiency x VR = 0.6 x 5 = 3. Load = MA x effort = 3 x 500 = 1500 N.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cf97xsv2wr8uuuvmzw125s05i', 'Chemistry', 'JAMB', null, 1994, null, 'Which of these metals <b>CANNOT replace hydrogen</b> from alkaline solutions?', null, '["Aluminium","Zinc","Tin","Iron"]', 3, 'Iron does not react with alkaline solutions to release H2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of these metals <b>CANNOT replace hydrogen</b> from alkaline solutions?', '["Aluminium","Zinc","Tin","Iron"]', '<u>Iron</u> cannot replace hydrogen from alkaline solutions.', '{"bold":["CANNOT replace hydrogen"],"italic":[],"underline":["Iron"],"fillBlanks":[]}');
