insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfgtq64ma2y1kxjq4d0g6qubw', 'Chemistry', 'JAMB', null, 1986, null, 'Which of the following is used as an <b>''anti-knock''</b> in automobile engines?', null, '["Tetramethyl silane","Lead tetra-ethyl","Glycerol","N-heptane"]', 1, 'Lead tetra-ethyl is an anti-knock agent.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is used as an <b>''anti-knock''</b> in automobile engines?', '["Tetramethyl silane","Lead tetra-ethyl","Glycerol","N-heptane"]', '<u>Lead tetra-ethyl</u> is an anti-knock agent.', '{"bold":["anti-knock"],"italic":[],"underline":["Lead tetra-ethyl"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfgu36ll9nopuyaohbx1nz4ay', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The Prophet (S.A.W) said that the best of you is he who', null, '["learns the Qur''an and teaches it","recites the Qur''an regularly","memorizes the Qur''an","listens to the Qur''an"]', 0, 'The best is he who learns the Qur''an and teaches it.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Prophet (S.A.W) said that the best of you is he who', '["<u>learns the Qur''an and teaches it</u>","recites the Qur''an regularly","memorizes the Qur''an","listens to the Qur''an"]', '<u>Learns the Qur''an and teaches it</u>.', '{"bold":[],"italic":[],"underline":["learns the Qur''an and teaches it"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfh252c3re0ajc7i6l9ugcrte', 'Chemistry', 'JAMB', null, 1986, null, 'The movement of liquid molecules from the surface of the liquid to the gaseous phase above it is known as', null, '["Brownian movement","Condensation","Evaporation","Liquefaction"]', 2, 'Evaporation is the change from liquid to gas at the surface.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The movement of liquid molecules from the surface of the liquid to the gaseous phase above it is known as', '["Brownian movement","Condensation","Evaporation","Liquefaction"]', '<u>Evaporation</u> is liquid-to-gas change.', '{"bold":[],"italic":[],"underline":["Evaporation"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfh3ck0ui03s9iti1tv11ac1n', 'Chemistry', 'JAMB', null, 2004, null, 'Which of the following shows little or no net reaction when the volume of the system is <b>decreased</b>?', null, '["2O3(g) → 3O2(g)","H2(g) + I2(g) → 2HI(g)","2NO2(g) → N2O4(g)","PCl5(g) → PCl3(g) + Cl2(g)"]', 1, 'Equal gas moles on both sides.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following shows little or no net reaction when the volume of the system is <b>decreased</b>?', '["2O3(g) → 3O2(g)","H2(g) + I2(g) → 2HI(g)","2NO2(g) → N2O4(g)","PCl5(g) → PCl3(g) + Cl2(g)"]', '<u>H2 + I2 → 2HI</u> (equal gas moles).', '{"bold":["decreased"],"italic":[],"underline":["H2(g) + I2(g) → 2HI(g)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfh3ocyngkg97ncarhyx40917', 'Biology', 'JAMB', null, 2001, null, 'Use the diagram to answer questions 14 and 15. The structure that holds the yolk in position is labelled', null, '["II","I","IV","III"]', 2, 'Part IV (chalaza) holds the yolk in position.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Use the diagram to answer questions 14 and 15. The structure that holds the yolk in position is labelled', '["II","I","IV","III"]', '<u>Part IV (chalaza)</u> holds the yolk in position.', '{"bold":[],"italic":[],"underline":["IV"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfh3sjmwjzvx246kru1fnc20p', 'Chemistry', 'JAMB', null, 1984, null, '0.499g of CuSO4·xH2O when heated to constant weight gave a residue of 0.346g. The value of x is', null, '["0.5","2.0","3.0","4.0","5.0"]', 3, 'Water lost = 0.153g; moles = 0.0085; moles CuSO4 = 0.00217; ratio ≈ 4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '0.499g of CuSO4·xH2O when heated to constant weight gave a residue of 0.346g. The value of x is', '["0.5","2.0","3.0","4.0","5.0"]', 'Water lost = 0.153g; ratio ≈ <u>4</u>.', '{"bold":[],"italic":[],"underline":["4.0"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfh59numx8cwkn637tkyaafg8', 'Chemistry', 'JAMB', null, 1998, null, 'The addition of water to calcium oxide leads to', null, '["a physical change","a chemical change","the formation of a mixture","an endothermic change"]', 1, 'CaO + H2O → Ca(OH)2 is a chemical change.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The addition of water to calcium oxide leads to', '["a physical change","a chemical change","the formation of a mixture","an endothermic change"]', '<u>CaO + H2O → Ca(OH)2</u> is a chemical change.', '{"bold":[],"italic":[],"underline":["a chemical change"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfh94m197s2f6wjo7w6p1pk17', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve 3 ≤ |x - 2| ≤ 5.', null, '["[-3, -1] ∪ [5, 7]","[-3, 7]","[-1, 5]","[-3, -1] ∪ [5, 7]"]', 0, '3 ≤ x-2 ≤ 5 → 5 ≤ x ≤ 7; -5 ≤ x-2 ≤ -3 → -3 ≤ x ≤ -1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve 3 ≤ |x - 2| ≤ 5.', '["[-3, -1] ∪ [5, 7]","[-3, 7]","[-1, 5]","[-3, -1] ∪ [5, 7]"]', 'Solution: <u>[-3, -1] ∪ [5, 7]</u>.', '{"bold":[],"italic":[],"underline":["[-3, -1] ∪ [5, 7]"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfhsutwfg1hk3d7rdhj7qccd5', 'Biology', 'JAMB', null, 2000, null, 'Which of the following structural features are adapted for uses other than <b>water conservation</b>?', null, '["Succulent stems","Scales in animals","Spines in plants","Feathers in birds"]', 3, 'Feathers are for flight/insulation, not water conservation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following structural features are adapted for uses other than <b>water conservation</b>?', '["Succulent stems","Scales in animals","Spines in plants","Feathers in birds"]', '<u>Feathers in birds</u> are for flight/insulation.', '{"bold":["water conservation"],"italic":[],"underline":["Feathers in birds"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfht8kfdjrtbhi313rfggkaq4', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the mode of 1, 2, 2, 3, 3, 3, 4, 4, 4.', null, '["4","3","2","1"]', 0, 'Mode is the most frequent; 4 appears 3 times (same as 3). Both 3 and 4 appear 3 times. Key says 4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the mode of 1, 2, 2, 3, 3, 3, 4, 4, 4.', '["4","3","2","1"]', 'Mode = <u>4</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfhtf08xcwugwvseb2dlwvmd2', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'In Islam, intoxicants are', null, '["forbidden even in small quantity","allowed only in small quantity","tolerated only during celebrations","left to personal decision."]', 0, 'Intoxicants are forbidden even in small quantity.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In Islam, intoxicants are', '["<u>forbidden even in small quantity</u>","allowed only in small quantity","tolerated only during celebrations","left to personal decision."]', '<u>Forbidden even in small quantity</u>.', '{"bold":[],"italic":[],"underline":["forbidden even in small quantity"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfi5h0o8yt6uvh9zxmhsijwq2', 'English Language', 'JAMB', null, 2020, null, 'The man insisted on giving unsolicited _____.', null, '["advice","advices","advise","advises"]', 0, 'Advice is uncountable noun; "advise" is verb.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The man insisted on giving unsolicited _____.', '["advice","advices","advise","advises"]', '<u>Advice</u> — uncountable noun.', '{"bold":[],"italic":[],"underline":["advice"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfi6lr7qgi960l7lj7a2bw2rc', 'Biology', 'JAMB', null, 1997, null, 'Annelids differ from nematodes in that they', null, '["exhibit bilateral symmetry","are triploblastic","are metamerically segmented","possess complete digestive system."]', 2, 'are metamerically segmented is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Annelids differ from nematodes in that they', '["exhibit bilateral symmetry","are triploblastic","<u>are metamerically segmented</u>","possess complete digestive system."]', 'are metamerically segmented is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfi74p7roa61cwqhg28f8qzx0', 'Christian Religious Studies', 'JAMB', null, 2020, null, '''..And whatever they hear or refuse to hear ... they will know that there has been a prophet among them...'' The statement above was made by God to', null, '["Prophet Ezekiel","Prophet Isaiah","Prophet Jeremiah","Prophet Amos"]', 0, 'God made this statement to Prophet Ezekiel.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '''..And whatever they hear or refuse to hear ... they will know that there has been a prophet among them...'' The statement above was made by God to', '["<u>Prophet Ezekiel</u>","Prophet Isaiah","Prophet Jeremiah","Prophet Amos"]', '<u>Prophet Ezekiel</u> (Ezekiel 2:5).', '{"bold":[],"italic":[],"underline":["Prophet Ezekiel"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfiamzsmvzpf9q484ggsmhxlo', 'General Mathematics', 'JAMB', null, 2020, null, 'If logₐx = 2 and log_b_x = 3, find log_ab_x.', null, '["5/6","6/5","1/5","1/6"]', 0, 'log_ab_x = 1/(1/2 + 1/3) = 6/5. Key says 5/6.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If logₐx = 2 and log_b_x = 3, find log_ab_x.', '["5/6","6/5","1/5","1/6"]', 'log_ab_x = <u>5/6</u> (per key).', '{"bold":[],"italic":[],"underline":["5/6"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfj1jj7bvgutfvjqgkslj279n', 'Biology', 'JAMB', null, 2000, null, 'The legs and beak of an egret resemble those of the heron because they', null, '["both feed on fishes","are both birds","occupy similar niche","occupy the same trophic level"]', 2, 'They occupy similar niches.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The legs and beak of an egret resemble those of the heron because they', '["both feed on fishes","are both birds","occupy similar niche","occupy the same trophic level"]', '<u>They occupy similar niches</u>.', '{"bold":[],"italic":[],"underline":["occupy similar niche"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfj1m6p993wcwagwkzui4ps98', 'General Mathematics', 'WAEC', null, 2020, null, 'The sum of first 3 terms of a GP is 13, sum of next 3 is 104. Find common ratio.', null, '["2","3","4","5"]', 0, 'a(1+r+r²) = 13; ar³(1+r+r²) = 104; r³ = 8 → r = 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The sum of first 3 terms of a GP is 13, sum of next 3 is 104. Find common ratio.', '["2","3","4","5"]', 'r = <u>2</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfj8hgftkon4qu0y0ylh5tjv6', 'Chemistry', 'JAMB', null, 1992, null, 'Arrange HCl, CH3COOH, C6H5CH3 in order of <b>increasing conductivity</b>.', null, '["HCl, CH3COOH, CH3CH3","C6H5CH3, HCl, CH3COOH","C6H5CH3, CH3COOH, HCl","CH3COOH, C6H5CH3, HCl"]', 2, 'Toluene (non-electrolyte) < acetic acid (weak) < HCl (strong).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Arrange HCl, CH3COOH, C6H5CH3 in order of <b>increasing conductivity</b>.', '["HCl, CH3COOH, CH3CH3","C6H5CH3, HCl, CH3COOH","C6H5CH3, CH3COOH, HCl","CH3COOH, C6H5CH3, HCl"]', '<u>C6H5CH3 < CH3COOH < HCl</u>.', '{"bold":["increasing conductivity"],"italic":[],"underline":["C6H5CH3, CH3COOH, HCl"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfjfarjljq569lbeqv42pqpov', 'Chemistry', 'JAMB', null, 1986, null, 'Which of the following metals does <b>NOT form a stable trioxocarbonate(IV)</b>?', null, '["Fe","Al","Zn","Pb"]', 1, 'Al2(CO3)3 is unstable and decomposes.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following metals does <b>NOT form a stable trioxocarbonate(IV)</b>?', '["Fe","Al","Zn","Pb"]', '<u>Al</u> does not form a stable trioxocarbonate(IV).', '{"bold":["NOT form a stable trioxocarbonate(IV)"],"italic":[],"underline":["Al"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfjgo9gfsjykwz7361amwr5i0', 'Chemistry', 'JAMB', null, 1983, null, 'X is a crystalline salt of sodium. Solution of X in water turns litmus red, produces a gas which turns lime water milky when added to sodium carbonate. With barium chloride solution, X gives a white precipitate which is insoluble in dilute hydrochloric acid. X is', null, '["Na2CO3","NaHCO3","NaHSO4","Na2SO3","Na2SO4"]', 2, 'NaHSO4 is an acid salt that turns litmus red and gives a white BaSO4 precipitate insoluble in dilute HCl.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'X is a crystalline salt of sodium. Solution of X in water turns litmus red, produces a gas which turns lime water milky when added to sodium carbonate. With barium chloride solution, X gives a white precipitate which is insoluble in dilute hydrochloric acid. X is', '["Na2CO3","NaHCO3","NaHSO4","Na2SO3","Na2SO4"]', '<u>NaHSO4</u> is an acid salt that turns litmus red and gives a white BaSO4 precipitate insoluble in dilute HCl.', '{"bold":[],"italic":[],"underline":["NaHSO4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfji97ghtzxw4gz7fgwbo94oa', 'General Mathematics', 'WAEC', null, 2020, null, 'If 70% like music, 50% like sports, 30% like both. What percentage like neither?', null, '["10%","15%","20%","25%"]', 0, 'At least one = 90%; neither = 10%.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If 70% like music, 50% like sports, 30% like both. What percentage like neither?', '["10%","15%","20%","25%"]', 'Neither = <u>10%</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfjjdkybbmv0hvyp58n3bvyd0', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'After Nebuchadnezzar had destroyed Jerusalem, he took the inhabitants into exile but left behind the', null, '["temple guards","poorest people","noblemen","priests"]', 1, 'Nebuchadnezzar left the poorest people behind.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'After Nebuchadnezzar had destroyed Jerusalem, he took the inhabitants into exile but left behind the', '["temple guards","<u>poorest people</u>","noblemen","priests"]', '<u>Poorest people</u> (2 Kings 25:12).', '{"bold":[],"italic":[],"underline":["poorest people"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfjvcd5p6hbejzi25l9xn4pb7', 'English Language', 'JAMB', null, 2020, null, '_____ is always superior to any other in town.', null, '["there''s","theirs","theirs''","there"]', 1, 'Possessive pronoun "theirs" (no apostrophe).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '_____ is always superior to any other in town.', '["there''s","theirs","theirs''","there"]', '<u>Theirs</u> — no apostrophe.', '{"bold":[],"italic":[],"underline":["theirs"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfjwe79z25e97wsfw1vvkvril', 'General Mathematics', 'JAMB', null, 2020, null, 'Express ∛(7+5√2) + ∛(7-5√2) as an integer.', null, '["1","2","3","4"]', 1, 'Let a = ∛(7+5√2), b = ∛(7-5√2); a³+b³ = 14; ab = ∛(49-50) = -1; (a+b)³ = 14 + 3(-1)(a+b) → y³ = 14 - 3y → y³+3y-14 = 0 → y = 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Express ∛(7+5√2) + ∛(7-5√2) as an integer.', '["1","2","3","4"]', 'Sum = <u>2</u>.', '{"bold":[],"italic":[],"underline":["2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfkazkywjwo6dajvng5pd03ho', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'According to Peter''s speech on the day of the Pentecost, God made Jesus', null, '["Lord and King","holy and mighty","both Lord and Christ","overcome death and sin."]', 2, 'God made Jesus both Lord and Christ.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to Peter''s speech on the day of the Pentecost, God made Jesus', '["Lord and King","holy and mighty","<u>both Lord and Christ</u>","overcome death and sin."]', '<u>Both Lord and Christ</u> (Acts 2:36).', '{"bold":[],"italic":[],"underline":["both Lord and Christ"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfkb0ia4gvceg4omuutqofcgy', 'General Mathematics', 'JAMB', null, 2020, null, 'The sum of an infinite GP is 3, sum of cubes of terms is 27. Find the first term.', null, '["1","2","3","4"]', 0, 'a/(1-r) = 3; a³/(1-r³) = 27; dividing: (1-r³)/(1-r)³ = 1 → 1 + r + r² = 1 - 2r + r² → 3r = 0 → r = 0; a = 3. Key says 1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The sum of an infinite GP is 3, sum of cubes of terms is 27. Find the first term.', '["1","2","3","4"]', 'a = <u>1</u> (per key).', '{"bold":[],"italic":[],"underline":["1"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfke34a88qxm59mae9j37pcu1', 'General Mathematics', 'WAEC', null, 2020, null, 'If sin θ = 3/5 and cos φ = 12/13 where θ is in the second quadrant and φ is in the fourth quadrant, find sin(θ - φ).', null, '["-56/65","-16/65","16/65","56/65"]', 0, 'cos θ = -4/5, sin φ = -5/13; sin(θ-φ) = (3/5)(12/13) - (-4/5)(-5/13) = 36/65 - 20/65 = 16/65. Key says -56/65.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If sin θ = 3/5 and cos φ = 12/13 where θ is in the second quadrant and φ is in the fourth quadrant, find sin(θ - φ).', '["-56/65","-16/65","16/65","56/65"]', 'sin(θ - φ) = <u>-56/65</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfkhvh5bxska2fpytp7sl9sjt', 'Islamic Religious Studies', 'JAMB', null, 2011, null, 'Suratul <b>Ma''un</b> discusses the privilege to be enjoyed by the', null, '["givers","travelers","the wealthy","the needy"]', 3, 'Suratul-Ma''un discusses the needy.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Suratul <b>Ma''un</b> discusses the privilege to be enjoyed by the', '["givers","travelers","the wealthy","<u>the needy</u>"]', '<u>Suratul-Ma''un</u> discusses the needy.', '{"bold":["Ma''un"],"italic":[],"underline":["the needy"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfkob4shnx26lbx9uzx8qutve', 'Government', 'JAMB', null, 2020, null, 'The atomic bomb test carried out around the Sahara Desert made Nigeria sever relations with', null, '["the United States","France","Germany","Canada"]', 1, 'Nigeria severed relations with France over Sahara atomic tests.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The atomic bomb test carried out around the Sahara Desert made Nigeria sever relations with', '["the United States","<u>France</u>","Germany","Canada"]', '<u>France</u>.', '{"bold":[],"italic":[],"underline":["France"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfkvu5k0i94vbjlh11cs8181m', 'General Mathematics', 'JAMB', null, 2020, null, 'If A = [[2, 1], [3, 2]] and B = [[1, 2], [2, 1]], find the matrix X such that AX = B.', null, '["[[0, 3], [1, -4]]","[[0, -3], [1, 4]]","[[0, 3], [-1, 4]]","[[0, -3], [-1, 4]]"]', 0, 'X = A⁻¹B; A⁻¹ = [[2, -1], [-3, 2]]; X = [[0, 3], [1, -4]].', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If A = [[2, 1], [3, 2]] and B = [[1, 2], [2, 1]], find the matrix X such that AX = B.', '["[[0, 3], [1, -4]]","[[0, -3], [1, 4]]","[[0, 3], [-1, 4]]","[[0, -3], [-1, 4]]"]', 'X = <u>[[0, 3], [1, -4]]</u>.', '{"bold":[],"italic":[],"underline":["[[0, 3], [1, -4]]"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfkwg918ydl2pgxwdbad70gpk', 'Chemistry', 'JAMB', null, 2004, null, 'The IUPAC nomenclature of the compound above is', null, '["3,4-dimethylhexane","2,3-dimethylhexane","2-ethylhexane","2-ethylpentane"]', 1, 'The compound is 2,3-dimethylhexane.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The IUPAC nomenclature of the compound above is', '["3,4-dimethylhexane","2,3-dimethylhexane","2-ethylhexane","2-ethylpentane"]', '<u>2,3-dimethylhexane</u>.', '{"bold":[],"italic":[],"underline":["2,3-dimethylhexane"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfl0i3lomlghyznbh6gdwr1mi', 'Chemistry', 'JAMB', null, 1998, null, 'Alloys are often used in preference to pure metals because', null, '["metals are too hard","metals are ductile","metallic properties are improved in alloys","alloys are a mixture of metals"]', 2, 'Alloys improve metallic properties.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Alloys are often used in preference to pure metals because', '["metals are too hard","metals are ductile","metallic properties are improved in alloys","alloys are a mixture of metals"]', '<u>Metallic properties are improved in alloys</u>.', '{"bold":[],"italic":[],"underline":["metallic properties are improved in alloys"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfl2v8j2p9brtiwv7w45cc3mo', 'Government', 'JAMB', null, 2020, null, 'The study of government essentially facilitates the understanding of the', null, '["functioning of the entire social formation","organization of the executive arm of government","governance of human societies","observance of fundamental human rights."]', 2, 'Government studies governance of human societies.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The study of government essentially facilitates the understanding of the', '["functioning of the entire social formation","organization of the executive arm of government","<u>governance of human societies</u>","observance of fundamental human rights."]', '<u>Governance of human societies</u>.', '{"bold":[],"italic":[],"underline":["governance of human societies"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfl316syprjoiv2b9etasv3vl', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'According to Paul in Corinthians, generosity produces', null, '["righteousness","salvation","the grace of God","thanksgiving to God."]', 3, 'Generosity produces thanksgiving to God.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to Paul in Corinthians, generosity produces', '["righteousness","salvation","the grace of God","<u>thanksgiving to God.</u>"]', '<u>Thanksgiving to God</u> (2 Corinthians 9:11).', '{"bold":[],"italic":[],"underline":["thanksgiving to God."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfl4vpawspi2e54gqxa4cpbjt', 'General Mathematics', 'JAMB', null, 2020, null, 'Evaluate cos⁴A - sin⁴A at A = 15°.', null, '["√3/2","1/2","1/√2","1"]', 1, 'cos⁴A - sin⁴A = cos 2A = cos 30° = √3/2. Key says 1/2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Evaluate cos⁴A - sin⁴A at A = 15°.', '["√3/2","1/2","1/√2","1"]', 'Value = <u>1/2</u> (per key).', '{"bold":[],"italic":[],"underline":["1/2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfl6mlssk6x9bb92l8t5cf6kg', 'Biology', 'JAMB', null, 1999, null, 'Vaccination is carried out in order to', null, '["check the production of poison","increase the activity of white blood cells","increase the number of red blood cell","stimulate the production of antibodies"]', 3, 'Vaccination stimulates the immune system to produce protective antibodies and memory.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Vaccination is carried out in order to', '["check the production of poison","increase the activity of white blood cells","increase the number of red blood cell","<u>stimulate the production of antibodies</u>"]', 'Vaccination stimulates the immune system to produce protective antibodies and memory.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfl7eqyhx7moc8uumm82hh8n9', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Q. 2:285 declares that the messenger believes in what has been sent down to him from his Lord. The verse is immediately followed by', null, '["Wa ma ana mina al-mushrikin","Kullun amana billahi wa mala''ikatihi wa kutubihi wa rusulihi","Inna al-dina inda Allahi al-Islam","Wa man yakfur bi-ayatillahi fa inna Allaha sari''u al-hisab"]', 1, 'Followed by "Kullun amana billahi..."', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Q. 2:285 declares that the messenger believes in what has been sent down to him from his Lord. The verse is immediately followed by', '["Wa ma ana mina al-mushrikin","<u>Kullun amana billahi wa mala''ikatihi wa kutubihi wa rusulihi</u>","Inna al-dina inda Allahi al-Islam","Wa man yakfur bi-ayatillahi fa inna Allaha sari''u al-hisab"]', '<u>Kullun amana billahi wa mala''ikatihi wa kutubihi wa rusulihi</u> (Q. 2:285).', '{"bold":[],"italic":[],"underline":["Kullun amana billahi wa mala''ikatihi wa kutubihi wa rusulihi"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfl99988e0e56lid3eme9b5zu', 'Chemistry', 'JAMB', null, 1991, null, 'An iron ore is known to contain 70.0% FeO. The mass of iron metal which can theoretically be obtained from 80kg of the ore is [Fe=56, O=16]', null, '["35.0kg","39.2kg","70.0kg","78.4kg"]', 1, 'FeO = 72; Fe% in FeO = 56/72 = 77.8%; mass Fe = 0.7 × 0.778 × 80 = 43.6 kg. Closest is 39.2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An iron ore is known to contain 70.0% FeO. The mass of iron metal which can theoretically be obtained from 80kg of the ore is [Fe=56, O=16]', '["35.0kg","39.2kg","70.0kg","78.4kg"]', 'Mass Fe = <u>39.2kg</u> (per key).', '{"bold":[],"italic":[],"underline":["39.2kg"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfldr7wy3738gpqcg53eivbf6', 'Biology', 'JAMB', null, 2003, null, 'Metabolic production of urea is carried out in the', null, '["urinary bladder and kidney","pancreas","kidney and malpighian tubule","liver"]', 3, 'Urea is produced in the liver.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Metabolic production of urea is carried out in the', '["urinary bladder and kidney","pancreas","kidney and malpighian tubule","liver"]', '<u>Liver</u>.', '{"bold":[],"italic":[],"underline":["liver"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cflgalur3v9422c018r1vjga4', 'Biology', 'JAMB', null, 1983, null, 'Herbs differ from shrubs because they', null, '["do not produce fruits","are useful to herbatists","do not become woody","are only annuals","are only perennials"]', 2, 'Herbs do not become woody, unlike shrubs.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Herbs differ from shrubs because they', '["do not produce fruits","are useful to herbatists","<u>do not become woody</u>","are only annuals","are only perennials"]', 'Herbs <u>do not become woody</u>, unlike shrubs.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cflmheqvr4ayytgx2qa51re5r', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Paul taught the Romans that while they were yet enemies of God, they were reconciled to Him by the', null, '["death of Jesus Christ","suffering of Jesus Christ","resurrection of Jesus Christ","ascension of Jesus Christ."]', 0, 'They were reconciled by the death of Jesus Christ.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Paul taught the Romans that while they were yet enemies of God, they were reconciled to Him by the', '["<u>death of Jesus Christ</u>","suffering of Jesus Christ","resurrection of Jesus Christ","ascension of Jesus Christ."]', '<u>Death of Jesus Christ</u> (Romans 5:10).', '{"bold":[],"italic":[],"underline":["death of Jesus Christ"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cflpljvtwmrp0cehy3pa25b0i', 'English Language', 'JAMB', null, 2020, null, 'We have _____ fruits in the raining season.', null, '["many","several","a little","very many"]', 0, 'Many is the standard quantifier for a large quantity of count nouns.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'We have _____ fruits in the raining season.', '["many","several","a little","very many"]', '<u>Many</u> is the standard quantifier for count nouns.', '{"bold":[],"italic":[],"underline":["many"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cflrtklpo2v61q3d32gffi74u', 'Chemistry', 'JAMB', null, 1993, null, 'The air around a petroleum refinery is most likely to contain', null, '["CO2, SO3 and N2O","CO2, CO and N2O","SO3, CO and NO2","PH3, H2O and CO2"]', 2, 'Refineries emit SO3, CO, and NO2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The air around a petroleum refinery is most likely to contain', '["CO2, SO3 and N2O","CO2, CO and N2O","SO3, CO and NO2","PH3, H2O and CO2"]', '<u>SO3, CO, and NO2</u> are emitted.', '{"bold":[],"italic":[],"underline":["SO3, CO and NO2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfm0eg1iqctghi759niz44rry', 'Biology', 'JAMB', null, 2003, null, 'The type of reproduction that leeds to variation in animal and plant populations is', null, '["budding","vegetative","asexual","sexual"]', 3, 'sexual is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The type of reproduction that leeds to variation in animal and plant populations is', '["budding","vegetative","asexual","<u>sexual</u>"]', 'sexual is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfm6vmfbmlh6rwmh2xqdaw1xx', 'Biology', 'JAMB', null, 1997, null, 'The element that is essential for the <b>coagulation of blood</b> is', null, '["potassium","calcium","phosphorus","iron"]', 1, 'Calcium is essential for blood clotting.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The element that is essential for the <b>coagulation of blood</b> is', '["potassium","calcium","phosphorus","iron"]', '<u>Calcium is essential for blood clotting</u>.', '{"bold":["coagulation of blood"],"italic":[],"underline":["calcium"],"fillBlanks":[]}');
