insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfn96kd4n88z0vkhhqttp1lyz', 'Chemistry', 'JAMB', null, 1986, null, 'The iron(III) oxide impurity in <b>bauxite</b> can be removed by', null, '["fractional crystallization in acid solution","dissolution in sodium hydroxide and filtration","extraction with concentrated ammonia and reprecipitation","electrolysis of molten mixture"]', 1, 'Bauxite dissolves in NaOH while Fe2O3 does not, so it is filtered off.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The iron(III) oxide impurity in <b>bauxite</b> can be removed by', '["fractional crystallization in acid solution","dissolution in sodium hydroxide and filtration","extraction with concentrated ammonia and reprecipitation","electrolysis of molten mixture"]', '<u>Dissolution in NaOH and filtration</u> removes Fe2O3.', '{"bold":["bauxite"],"italic":[],"underline":["dissolution in sodium hydroxide and filtration"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfnff3trth92h0hzol9injrwr', 'Biology', 'JAMB', null, 2004, null, 'The type of reproduction that is common to both Hydra and yeast is', null, '["grafting","budding","conjugation","binary fission"]', 1, 'budding is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The type of reproduction that is common to both Hydra and yeast is', '["grafting","<u>budding</u>","conjugation","binary fission"]', 'budding is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfnh10rsc45ms3a53bh3drzui', 'Chemistry', 'JAMB', null, 1987, null, 'Which of the following substances is a <b>mixture</b>?', null, '["Granulated sugar","Sea-water","Sodium chloride","Iron fillings"]', 1, 'Sea-water is a mixture of water and dissolved salts.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following substances is a <b>mixture</b>?', '["Granulated sugar","Sea-water","Sodium chloride","Iron fillings"]', '<u>Sea-water</u> is a mixture.', '{"bold":["mixture"],"italic":[],"underline":["Sea-water"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfnqu95a0uhha8i4arwaqluwo', 'Chemistry', 'JAMB', null, 1990, null, '2.0g of monobasic acid was made up to 250cm³ with distilled water. 25.00cm³ of this solution required 20.00cm³ of 0.1M NaOH solution for complete neutralization. The molar mass of the acid is', null, '["200g","160g","100g","50g"]', 2, 'Moles NaOH = 0.002; moles acid in 25cm³ = 0.002; in 250cm³ = 0.02; Mr = 2/0.02 = 100g.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '2.0g of monobasic acid was made up to 250cm³ with distilled water. 25.00cm³ of this solution required 20.00cm³ of 0.1M NaOH solution for complete neutralization. The molar mass of the acid is', '["200g","160g","100g","50g"]', 'Mr = <u>100g</u>.', '{"bold":[],"italic":[],"underline":["100g"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfnu0troutqtj4l0io6lxl3rx', 'Chemistry', 'JAMB', null, 1991, null, '1.1g of CaCl2 dissolved in 50cm³ of water caused a rise in temperature of 3.4°C. The heat of reaction, ΔH for CaCl2 in kJ per mole is [Ca=40, Cl=35.5, specific heat of water = 4.18 kJ]', null, '["-71.1","-4.18","+17.1","+111.0"]', 0, 'Heat = 50 × 4.18 × 3.4 = 710.6 J; moles = 1.1/111 = 0.0099; ΔH = -71.1 kJ/mol.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '1.1g of CaCl2 dissolved in 50cm³ of water caused a rise in temperature of 3.4°C. The heat of reaction, ΔH for CaCl2 in kJ per mole is [Ca=40, Cl=35.5, specific heat of water = 4.18 kJ]', '["-71.1","-4.18","+17.1","+111.0"]', 'ΔH = <u>-71.1 kJ/mol</u>.', '{"bold":[],"italic":[],"underline":["-71.1"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfo2kiuj7dvz56e1lqnw9rpt4', 'Government', 'JAMB', null, 2020, null, 'Professor Ibrahim Gambari is the Special Assistant to the United Nations Secretary-General on', null, '["the Economic Commission of Africa","security matters","African affairs","political and social matters"]', 2, 'He served as Special Assistant on African affairs.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Professor Ibrahim Gambari is the Special Assistant to the United Nations Secretary-General on', '["the Economic Commission of Africa","security matters","<u>African affairs</u>","political and social matters"]', '<u>African affairs</u>.', '{"bold":[],"italic":[],"underline":["African affairs"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfochw8bfgj1sfei3t0mwmq33', 'Government', 'JAMB', null, 2020, null, 'In Nigeria, the agency mainly responsible for the maintenance of internal peace and security is the', null, '["Army","Navy","Civil Defence Corps","Police."]', 3, 'The Police maintain internal peace and security.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In Nigeria, the agency mainly responsible for the maintenance of internal peace and security is the', '["Army","Navy","Civil Defence Corps","<u>Police.</u>"]', '<u>Police</u>.', '{"bold":[],"italic":[],"underline":["Police."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfodms11f6m2aj0nt8401s8c1', 'Biology', 'JAMB', null, 1991, null, 'The depth of illumination in a water body can be measured with a', null, '["photometer","secchi disc","hydrometer","anemometer"]', 1, 'A Secchi disc measures illumination depth.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The depth of illumination in a water body can be measured with a', '["photometer","<u>secchi disc</u>","hydrometer","anemometer"]', 'A <u>Secchi disc</u> measures illumination depth.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfopvis5mer5zxyu8n257jba0', 'General Mathematics', 'JAMB', null, 2020, null, 'In a class of 40 students, 25 passed Mathematics, 20 passed Physics, and 8 passed both. What is the probability that a student selected at random passed at least one of the subjects?', null, '["7/8","37/40","5/8","5/40"]', 1, 'At least one = 25 + 20 - 8 = 37; P = 37/40.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In a class of 40 students, 25 passed Mathematics, 20 passed Physics, and 8 passed both. What is the probability that a student selected at random passed at least one of the subjects?', '["7/8","37/40","5/8","5/40"]', 'P = <u>37/40</u>.', '{"bold":[],"italic":[],"underline":["37/40"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfopx6omov1mk07mh8hzjo0p0', 'Chemistry', 'JAMB', null, 1996, null, 'An iron ore is known to contain 70.0% FeO. The mass of iron metal which can theoretically be obtained from 80kg of the ore is [Fe=56, O=16]', null, '["35.0kg","39.2kg","70.0kg","78.4kg"]', 1, 'FeO = 72; Fe% = 77.8%; mass Fe = 0.7 × 0.778 × 80 = 43.6 kg. Closest is 39.2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An iron ore is known to contain 70.0% FeO. The mass of iron metal which can theoretically be obtained from 80kg of the ore is [Fe=56, O=16]', '["35.0kg","39.2kg","70.0kg","78.4kg"]', 'Mass Fe = <u>39.2kg</u> (per key).', '{"bold":[],"italic":[],"underline":["39.2kg"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfots7zzajuizrsia3wk3t43y', 'Chemistry', 'JAMB', null, 1996, null, 'Which of the following can be obtained by <b>fractional distillation</b>?', null, '["Nitrogen from liquid air","Sodium chloride from sea water","Iodine from a solution of iodine in carbon tetrachloride","Sulphur from a solution of sulphur in carbon disulphide"]', 0, 'Nitrogen from liquid air by fractional distillation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following can be obtained by <b>fractional distillation</b>?', '["Nitrogen from liquid air","Sodium chloride from sea water","Iodine from a solution of iodine in carbon tetrachloride","Sulphur from a solution of sulphur in carbon disulphide"]', '<u>Nitrogen from liquid air</u>.', '{"bold":["fractional distillation"],"italic":[],"underline":["Nitrogen from liquid air"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfoyef5cnvi9ievtjdmoumt1j', 'General Mathematics', 'JAMB', null, 2020, null, 'If y = tan⁻¹(2x/(1 - x²)), find dy/dx.', null, '["2/(1 + x²)","2/(1 - x²)","1/(1 + x²)","2x/(1 + x²)"]', 0, 'y = 2tan⁻¹x; dy/dx = 2/(1+x²).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If y = tan⁻¹(2x/(1 - x²)), find dy/dx.', '["2/(1 + x²)","2/(1 - x²)","1/(1 + x²)","2x/(1 + x²)"]', 'dy/dx = <u>2/(1 + x²)</u>.', '{"bold":[],"italic":[],"underline":["2/(1 + x²)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfp4xa37h5fsi2bdzgejlue5q', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Al-awrah for a man is from the', null, '["navel to the feet","navel to the knee","head to the toe","head to the waist."]', 1, 'It is from the navel to the knee.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Al-awrah for a man is from the', '["navel to the feet","<u>navel to the knee</u>","head to the toe","head to the waist."]', '<u>Navel to the knee</u>.', '{"bold":[],"italic":[],"underline":["navel to the knee"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfpjgzurby26a1muuk5akrsrj', 'Biology', 'JAMB', null, 1987, null, 'Epiphytes growing on the branches of trees provide an example of the relationship known as', null, '["parasitism","commensalism","apophytism","holophytism"]', 1, 'Epiphytes on trees is an example of commensalism.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Epiphytes growing on the branches of trees provide an example of the relationship known as', '["parasitism","<u>commensalism</u>","apophytism","holophytism"]', '<u>Epiphytes on trees</u> is an example of commensalism.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfpnird4oofywx7h0u9nkgfvf', 'Chemistry', 'JAMB', null, 1991, null, 'Ethene when passed into concentrated H2SO4 is rapidly absorbed. The product is diluted with water and then warmed to produce', null, '["ethanol","diethyl ether","ethanal","diethyl sulphate"]', 0, 'Ethene + H2SO4 → ethyl hydrogen sulphate → ethanol on hydrolysis.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Ethene when passed into concentrated H2SO4 is rapidly absorbed. The product is diluted with water and then warmed to produce', '["ethanol","diethyl ether","ethanal","diethyl sulphate"]', '<u>Ethanol</u> is produced.', '{"bold":[],"italic":[],"underline":["ethanol"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfprjj6j627lxjsqg46638d19', 'Islamic Religious Studies', 'JAMB', null, 2003, null, 'The forms of revelations are explained in', null, '["Q. 40:51","Q. 41:50","Q. 42:51","Q. 43:50"]', 2, 'Q.42:51 explains the three forms of revelation: inspiration, from behind a veil, and through a messenger.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The forms of revelations are explained in', '["Q. 40:51","Q. 41:50","<u>Q. 42:51</u>","Q. 43:50"]', '<u>Q.42:51</u> explains the three forms of revelation.', '{"bold":[],"italic":[],"underline":["Q. 42:51"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfpwrp9bndhian5ojqcyjhrwu', 'General Mathematics', 'JAMB', null, 2020, null, 'The resultant of two forces P and Q is 250 N. If P = 150 N and the angle between P and the resultant is 30°, find the magnitude of Q and the angle it makes with the resultant.', null, '["201.4 N, 21.8°","150.2 N, 45.6°","250.0 N, 60.0°","111.2 N, 32.5°"]', 0, 'Using sine/cosine rules: Q ≈ 201.4 N; angle ≈ 21.8°.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The resultant of two forces P and Q is 250 N. If P = 150 N and the angle between P and the resultant is 30°, find the magnitude of Q and the angle it makes with the resultant.', '["201.4 N, 21.8°","150.2 N, 45.6°","250.0 N, 60.0°","111.2 N, 32.5°"]', 'Q = <u>201.4 N, 21.8°</u>.', '{"bold":[],"italic":[],"underline":["201.4 N, 21.8°"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfq1rmyvqewxm71hh6k083xic', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'The Last Supper took place during the Passover on the first day of', null, '["the week","unleavened bread","abstinence from blood","the month."]', 1, 'It was on the first day of Unleavened Bread.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Last Supper took place during the Passover on the first day of', '["the week","<u>unleavened bread</u>","abstinence from blood","the month."]', '<u>Unleavened bread</u> (Mark 14:12).', '{"bold":[],"italic":[],"underline":["unleavened bread"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfq65y8fz1upctoadof3cd6xf', 'Government', 'JAMB', null, 2020, null, 'A major contentious issue confronting Nigerian federalism is', null, '["poverty","health care delivery","education","revenue allocation"]', 3, 'Revenue allocation is a contentious federalism issue.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A major contentious issue confronting Nigerian federalism is', '["poverty","health care delivery","education","<u>revenue allocation</u>"]', '<u>Revenue allocation</u>.', '{"bold":[],"italic":[],"underline":["revenue allocation"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfqrn1sooebscyjewv34k4gcm', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'It is finished. The statement above by Jesus on the cross implies that', null, '["His association with the Jews is finished","His association with His disciples is finished","His work of redemption is finished","the work of the enemy is finished."]', 2, 'It means His work of redemption is finished.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'It is finished. The statement above by Jesus on the cross implies that', '["His association with the Jews is finished","His association with His disciples is finished","<u>His work of redemption is finished</u>","the work of the enemy is finished."]', '<u>His work of redemption is finished</u> (John 19:30).', '{"bold":[],"italic":[],"underline":["His work of redemption is finished"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfr2gys4amzn0n0c52ocqjf4x', 'Chemistry', 'JAMB', null, 1991, null, 'How many grams of bromine will be required to completely react with 10g of propyne? [C=12, H=1, Br=80]', null, '["20g","40g","60g","80g"]', 1, 'Moles propyne = 10/40 = 0.25; Br2 = 0.5 mol = 80g. Key says 40.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'How many grams of bromine will be required to completely react with 10g of propyne? [C=12, H=1, Br=80]', '["20g","40g","60g","80g"]', 'Br2 = 0.5 mol = <u>80g</u> (key says 40).', '{"bold":[],"italic":[],"underline":["40g"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfr7vh66o0e7ynaf8gyidp0fh', 'Biology', 'JAMB', null, 2000, null, 'The <b>mutation theory</b> of organic evolution was propounded by', null, '["Gregor Mendel","Hugo Vries","Jean Lamarck","Charles Darwin"]', 1, 'Hugo de Vries propounded the mutation theory.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The <b>mutation theory</b> of organic evolution was propounded by', '["Gregor Mendel","Hugo Vries","Jean Lamarck","Charles Darwin"]', '<u>Hugo de Vries</u> propounded the mutation theory.', '{"bold":["mutation theory"],"italic":[],"underline":["Hugo Vries"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfri29xukd8jw6ggl6xak759q', 'General Mathematics', 'JAMB', null, 2020, null, 'In a GP, product of first 3 terms is 64, sum of cubes is 584. Find the terms.', null, '["2, 4, 8","1, 4, 16","4, 8, 16","2, 8, 32"]', 0, 'Product = b³ = 64 → b = 4; a = 4/r, c = 4r; sum of cubes = 64(1/r³ + 1 + r³) = 584 → r³ + 1/r³ = 73/8; solving → r = 2; terms 2, 4, 8.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In a GP, product of first 3 terms is 64, sum of cubes is 584. Find the terms.', '["2, 4, 8","1, 4, 16","4, 8, 16","2, 8, 32"]', 'Terms: <u>2, 4, 8</u>.', '{"bold":[],"italic":[],"underline":["2, 4, 8"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfrll1knhbncs1afgrraxljfn', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Saul was rejected as king over Israel because he disobeyed God''s command to utterly destroy the', null, '["Syrians","Amalekites","Philistines","Assyrians"]', 1, 'Saul was rejected for not destroying the Amalekites.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Saul was rejected as king over Israel because he disobeyed God''s command to utterly destroy the', '["Syrians","<u>Amalekites</u>","Philistines","Assyrians"]', '<u>Amalekites</u> (1 Samuel 15).', '{"bold":[],"italic":[],"underline":["Amalekites"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfrp2x74etm2f52cwlxvy89z0', 'General Mathematics', 'JAMB', null, 2020, null, 'A fair die is tossed twice. The probability that the sum of the outcomes is a prime number greater than 5 is:', null, '["1/6","2/9","7/36","11/36"]', 1, 'Primes above 5: 7 (6 ways) and 11 (2 ways); 8/36 = 2/9.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'A fair die is tossed twice. The probability that the sum of the outcomes is a prime number greater than 5 is:', '["1/6","2/9","7/36","11/36"]', 'Primes above 5: 7 (6 ways) and 11 (2 ways); 8/36 = 2/9.', '{"bold":[],"italic":[],"underline":["5/36"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfrqspl33u3fb59wr7s6at9pc', 'Biology', 'JAMB', null, 2003, null, 'The cell component that is present in a prokaryotic cell is the', null, '["ribosome","mitochondrion","chloroplast","nuclear envelope"]', 0, 'Prokaryotic cells lack membrane-bound organelles but contain ribosomes.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The cell component that is present in a prokaryotic cell is the', '["<u>ribosome</u>","mitochondrion","chloroplast","nuclear envelope"]', 'Prokaryotic cells lack membrane-bound organelles but contain ribosomes.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfrs05nn72qwx4i0anpuc5zvm', 'General Mathematics', 'WAEC', null, 2020, null, 'The remainder when x³ + kx² + 3x - 2 divided by x - 1 equals the remainder when divided by x + 1 find k', null, '["3","no such value of k","1","0"]', 1, 'f(1) = k + 2 and f(-1) = k - 6 can never be equal, so no such k exists.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'The remainder when x³ + kx² + 3x - 2 divided by x - 1 equals the remainder when divided by x + 1 find k', '["3","no such value of k","1","0"]', 'f(1) = k + 2 and f(-1) = k - 6 can never be equal, so no such k exists.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfs2jbxwbdmt2dsptf5054gyq', 'General Mathematics', 'WAEC', null, 2020, null, 'If a > b > 0, which is true?', null, '["a/b > 1","b/a > 1","a² < b²","1/a > 1/b"]', 0, 'a > b > 0 → a/b > 1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If a > b > 0, which is true?', '["a/b > 1","b/a > 1","a² < b²","1/a > 1/b"]', 'a/b > 1.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfsdnvfbsdr5tqo719szpixby', 'Chemistry', 'JAMB', null, 1996, null, 'The final products of the reaction of methane with excess chlorine in the presence of ultraviolet light are hydrogen chloride and', null, '["chloromethane","tetrachloromethane","trichloromethane","dichloromethane"]', 1, 'Excess Cl2 gives CCl4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The final products of the reaction of methane with excess chlorine in the presence of ultraviolet light are hydrogen chloride and', '["chloromethane","tetrachloromethane","trichloromethane","dichloromethane"]', '<u>Tetrachloromethane (CCl4)</u>.', '{"bold":[],"italic":[],"underline":["tetrachloromethane"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfse1hyawdsjg8youxjvp05f5', 'Government', 'JAMB', null, 2020, null, 'The Barclays Bank and the British Petroleum Company in Nigeria were nationalized in the late 1970s for transacting business with', null, '["France","South Africa","Portugal","Libya"]', 1, 'They were nationalized for doing business with apartheid South Africa.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Barclays Bank and the British Petroleum Company in Nigeria were nationalized in the late 1970s for transacting business with', '["France","<u>South Africa</u>","Portugal","Libya"]', '<u>South Africa</u>.', '{"bold":[],"italic":[],"underline":["South Africa"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfsh80enu34z0e3956qjjncxc', 'Biology', 'JAMB', null, 1988, null, 'Which of the following structures is common to Euglena, white blood cell and Amoeba?', null, '["Vacuole","Cell wall","Cilia","Cell membrane"]', 3, 'All three have a cell membrane.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following structures is common to <b>Euglena</b>, white blood cell and <b>Amoeba</b>?', '["Vacuole","Cell wall","Cilia","<u>Cell membrane</u>"]', 'All three have a <u>cell membrane</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfsijgx8yik0r58ds02ipod5z', 'Government', 'JAMB', null, 2020, null, 'Under Nigeria''s Second Republic, the Senate was under the leadership of', null, '["Godwin Ume-Ezeoke","John Wash Pam","J.S. Tarka","Joseph Wayas"]', 3, 'Joseph Wayas led the Senate in the Second Republic.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Under Nigeria''s Second Republic, the Senate was under the leadership of', '["Godwin Ume-Ezeoke","John Wash Pam","J.S. Tarka","<u>Joseph Wayas</u>"]', '<u>Joseph Wayas</u>.', '{"bold":[],"italic":[],"underline":["Joseph Wayas"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfso5266gnlfb7xklavgkbrkk', 'General Mathematics', 'JAMB', null, 2020, null, 'In a school of 100 students: 50 drink tea, 60 drink coffee, 30 drink both. How many drink tea but not coffee?', null, '["20","25","30","35"]', 0, 'Tea only = 50 - 30 = 20.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In a school of 100 students: 50 drink tea, 60 drink coffee, 30 drink both. How many drink tea but not coffee?', '["20","25","30","35"]', 'Tea only = <u>20</u>.', '{"bold":[],"italic":[],"underline":["20"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfstfl65aa7rbi1o4qbcjj9af', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Paul admonishes the Corinthians to forgive the penitent offender so that', null, '["the offender may have peace of mind","it may be a lesson to other believers","forgiveness would demonstrate Christian love","the offender may not be overwhelmed by excessive sorrow"]', 3, 'So that the offender may not be overwhelmed by excessive sorrow.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Paul admonishes the Corinthians to forgive the penitent offender so that', '["the offender may have peace of mind","it may be a lesson to other believers","forgiveness would demonstrate Christian love","<u>the offender may not be overwhelmed by excessive sorrow</u>"]', '<u>The offender may not be overwhelmed by excessive sorrow</u> (2 Corinthians 2:7).', '{"bold":[],"italic":[],"underline":["the offender may not be overwhelmed by excessive sorrow"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cft29pc1inf7lbc174mr4mh5k', 'Biology', 'JAMB', null, 1998, null, 'One of the ways in which body cells differ from gamete cells is in the', null, '["type of centromeres they contain","number of chromosome pairs they contain","type of chromatids they contain","number of chromosomes they contain."]', 3, 'number of chromosomes they contain. is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One of the ways in which body cells differ from gamete cells is in the', '["type of centromeres they contain","number of chromosome pairs they contain","type of chromatids they contain","<u>number of chromosomes they contain.</u>"]', 'number of chromosomes they contain. is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cftriuu7nybutdzfivyfrie1n', 'Biology', 'JAMB', null, 1983, null, 'Banana, plantain and pineapple can be grouped together because they', null, '["produce small seeds","are multiple fruits","produce suckers","have runners","have bulbs"]', 1, 'Banana, plantain, and pineapple are multiple fruits.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Banana, plantain and pineapple can be grouped together because they', '["produce small seeds","<u>are multiple fruits</u>","produce suckers","have runners","have bulbs"]', 'Banana, plantain, and pineapple are <u>multiple fruits</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cftxk2jlhgf0og6eq9hkz915k', 'General Mathematics', 'JAMB', null, 2020, null, 'The polar of (1, 2) with respect to the circle x² + y² = 9 is:', null, '["x + 2y = 9","2x + y = 9","x - 2y = 9","2x - y = 9"]', 0, 'Polar: x·1 + y·2 = 9 → x + 2y = 9.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The polar of (1, 2) with respect to the circle x² + y² = 9 is:', '["x + 2y = 9","2x + y = 9","x - 2y = 9","2x - y = 9"]', 'Polar: <u>x + 2y = 9</u>.', '{"bold":[],"italic":[],"underline":["x + 2y = 9"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfu0o4taucrgo6cklqsur1mvr', 'Chemistry', 'JAMB', null, 1994, null, 'A pure solid usually melts', null, '["over a wide range of temperature","over a narrow range of temperature","at a lower temperature than the impure one","at the same temperature as the impure one"]', 1, 'A pure solid melts sharply over a narrow range.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A pure solid usually melts', '["over a wide range of temperature","over a narrow range of temperature","at a lower temperature than the impure one","at the same temperature as the impure one"]', '<u>A pure solid melts over a narrow range</u>.', '{"bold":[],"italic":[],"underline":["over a narrow range of temperature"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfu0z4cyd5g3ey3s1oeodfd9e', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'At Gibeon, the LORD appeared to Solomon in a', null, '["vision","trance","dream","whirlwind."]', 2, 'The LORD appeared to Solomon in a dream.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'At Gibeon, the LORD appeared to Solomon in a', '["vision","trance","<u>dream</u>","whirlwind."]', '<u>Dream</u> (1 Kings 3:5).', '{"bold":[],"italic":[],"underline":["dream"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfu1z7yivwn9kaj33bquti1gu', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve the equation 2^(2x) - 5·2^x + 4 = 0', null, '["0","1","0","0, 2"]', 3, 'Let y = 2^x: y² - 5y + 4 = 0 → y = 1 or 4 → x = 0 or 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Solve the equation 2^(2x) - 5·2^x + 4 = 0', '["0","1","0","0, 2"]', 'Let y = 2^x: y² - 5y + 4 = 0 → y = 1 or 4 → x = 0 or 2.', '{"bold":[],"italic":[],"underline":["0"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfu3ypjipwwijwfxs3gw4gbf2', 'Biology', 'JAMB', null, 2000, null, 'In a food chain, each succeeding level in a forward direction represents', null, '["an increase in the number of individuals","a decrease in the number of individuals","an increase in the biomass of individuals","a gain in the total energy being transferred"]', 1, 'Fewer individuals at higher trophic levels.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In a food chain, each succeeding level in a forward direction represents', '["an increase in the number of individuals","a decrease in the number of individuals","an increase in the biomass of individuals","a gain in the total energy being transferred"]', '<u>Decrease in number of individuals</u>.', '{"bold":[],"italic":[],"underline":["a decrease in the number of individuals"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfu6dh5301bgzh6dk1drjgjas', 'General Mathematics', 'JAMB', null, 2020, null, 'The rate of change of the volume of a sphere with respect to its radius r is 36π. Find the radius r.', null, '["3","6","9","18"]', 0, 'dV/dr = 4πr² = 36π → r² = 9 → r = 3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The rate of change of the volume of a sphere with respect to its radius r is 36π. Find the radius r.', '["3","6","9","18"]', 'r = <u>3</u>.', '{"bold":[],"italic":[],"underline":["3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfua9xzmbtqifgwojn7u0sj7x', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve (3x-1)/(x-2) ≥ 2.', null, '["x ≤ -3 or x ≥ 3","x ≥ 3 or x < 2","x ≤ -3 or x > 2","x ≤ 3 or x > 2"]', 2, '(3x-1)/(x-2) - 2 ≥ 0 → (x+3)/(x-2) ≥ 0 → x ≤ -3 or x > 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Solve (3x-1)/(x-2) ≥ 2.', '["x ≤ -3 or x ≥ 3","x ≥ 3 or x < 2","x ≤ -3 or x > 2","x ≤ 3 or x > 2"]', '(3x-1)/(x-2) - 2 ≥ 0 → (x+3)/(x-2) ≥ 0 → x ≤ -3 or x > 2.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfueba6223h2hthhk7dhvrrmw', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'God''s covenant with Noah after the flood is that He will', null, '["never destroy the earth with flood","make him fruitful and dominate the earth","make him and his descendants great","make all creatures on earth serve him."]', 0, 'He will never destroy the earth with flood.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'God''s covenant with Noah after the flood is that He will', '["<u>never destroy the earth with flood</u>","make him fruitful and dominate the earth","make him and his descendants great","make all creatures on earth serve him."]', '<u>Never destroy the earth with flood</u>.', '{"bold":[],"italic":[],"underline":["never destroy the earth with flood"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfuk94h0m77tv3upm42si96wn', 'Biology', 'JAMB', null, 2000, null, 'I High birth rate and high immigration rate<br>II Low birth rate and high immigration rate<br>III Low mortality rate and low emigration rate<br>IV High mortality rate and high emigration rate.<br>Which combination can cause rapid overcrowding?', null, '["II and III","I and III","I and IV","I and II"]', 1, 'High birth rate, high immigration, low mortality, low emigration cause overcrowding.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'I High birth rate and high immigration rate<br>II Low birth rate and high immigration rate<br>III Low mortality rate and low emigration rate<br>IV High mortality rate and high emigration rate.<br>Which combination can cause rapid overcrowding?', '["II and III","I and III","I and IV","I and II"]', '<u>I and III</u> cause overcrowding.', '{"bold":[],"italic":[],"underline":["I and III"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfush5jajak0xe4n5zuwh7ka0', 'General Mathematics', 'JAMB', null, 2020, null, 'If α² + β² = 25 and α + β = 7, find αβ.', null, '["10","11","12","13"]', 2, 'α² + β² = (α+β)² - 2αβ → 25 = 49 - 2αβ → 2αβ = 24 → αβ = 12.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If α² + β² = 25 and α + β = 7, find αβ.', '["10","11","12","13"]', 'αβ = <u>12</u>.', '{"bold":[],"italic":[],"underline":["12"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfv0m3hl7t938o7vt16ht5euv', 'Biology', 'JAMB', null, 2002, null, 'Examples of competitors are', null, '["lizard and mouse","snake and lizard","grasshopper and mouse","rabbit and snake"]', 2, 'Grasshopper and mouse compete for vegetation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Examples of competitors are', '["lizard and mouse","snake and lizard","grasshopper and mouse","rabbit and snake"]', '<u>Grasshopper and mouse</u> compete.', '{"bold":[],"italic":[],"underline":["grasshopper and mouse"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfv1oe494tbrpkakrk8oqc31a', 'Chemistry', 'JAMB', null, 1988, null, 'What are the possible oxidation numbers for an element if its atomic number is 17?', null, '["-1 and 7","-1 and 6","-3 and 5","-2 and 6"]', 0, 'Chlorine (atomic number 17) shows -1 and +7 oxidation states.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What are the possible oxidation numbers for an element if its atomic number is 17?', '["-1 and 7","-1 and 6","-3 and 5","-2 and 6"]', '<u>Chlorine shows -1 and +7</u> oxidation states.', '{"bold":[],"italic":[],"underline":["-1 and 7"],"fillBlanks":[]}');
