insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfvzrmf60vnfye3378gk9bomk', 'General Mathematics', 'WAEC', null, 2020, null, 'What is the condition that roots of ax² + bx + c = 0 are reciprocals.', null, '["a = c","a = -c","b = 0","a + c = 0"]', 0, 'Roots reciprocal → product = 1 → c/a = 1 → a = c.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is the condition that roots of ax² + bx + c = 0 are reciprocals.', '["a = c","a = -c","b = 0","a + c = 0"]', 'Condition: <u>a = c</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfw37mvq4ouxmrxrls501b52i', 'Government', 'JAMB', null, 2020, null, 'The final interpretation of the provision of a federal constitution is vested in the', null, '["highest legislative body","highest court of the land","head of state","Council of State"]', 1, 'The highest court interprets the constitution.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The final interpretation of the provision of a federal constitution is vested in the', '["highest legislative body","<u>highest court of the land</u>","head of state","Council of State"]', '<u>The highest court of the land</u>.', '{"bold":[],"italic":[],"underline":["highest court of the land"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfwbbqfhp7f3vtqx0oa3u3pg6', 'Government', 'JAMB', null, 2020, null, 'Nigerian nationalism was described as two-phased by', null, '["John Payne Jackson","James Coleman","Herbert Macaulay","Nnamdi Azikiwe"]', 1, 'James Coleman described Nigerian nationalism as two-phased.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Nigerian nationalism was described as two-phased by', '["John Payne Jackson","<u>James Coleman</u>","Herbert Macaulay","Nnamdi Azikiwe"]', '<u>James Coleman</u>.', '{"bold":[],"italic":[],"underline":["James Coleman"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfwf1kz7oth6wx80rpf0o1r5p', 'Physics', 'JAMB', null, 2021, null, 'Which of the following produces both transverse and longitudinal waves?', null, '["moving piston","sound","water","stretched string"]', 2, 'Water waves can exhibit both transverse and longitudinal characteristics.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following produces both <b>transverse and longitudinal waves</b>?', '["moving piston","sound","<u>water</u>","stretched string"]', '<u>Water waves</u> can exhibit both transverse and longitudinal characteristics.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfwgjqyb6jx31n0nxv3ml7zba', 'Government', 'JAMB', null, 2020, null, 'A member of the Commonwealth that still recognizes the British Monarch as its Head of State is', null, '["Singapore","Ghana","India","Australia"]', 3, 'Australia recognizes the British Monarch as Head of State.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A member of the Commonwealth that still recognizes the British Monarch as its Head of State is', '["Singapore","Ghana","India","<u>Australia</u>"]', '<u>Australia</u>.', '{"bold":[],"italic":[],"underline":["Australia"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfwhp5gnqvbgu7079ciz7uq53', 'Biology', 'JAMB', null, 1987, null, 'Poliomyelitis is an infectious disease caused by', null, '["virus","protozoan","bacterium","fungus"]', 0, 'Poliomyelitis is caused by a virus.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Poliomyelitis is an infectious disease caused by', '["<u>virus</u>","protozoan","bacterium","fungus"]', '<u>Poliomyelitis is caused by a virus</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfwrrbcxegvtfwixw0iuazfsv', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve x³ - 6x² + 11x - 6 < 0.', null, '["(1, 2) ∪ (3, ∞)","(-∞, 1) ∪ (2, 3)","(-∞, 1) ∪ (2, 3)","(1, 2) ∪ (3, ∞)"]', 1, '(x-1)(x-2)(x-3) < 0 → x < 1 or 2 < x < 3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve x³ - 6x² + 11x - 6 < 0.', '["(1, 2) ∪ (3, ∞)","(-∞, 1) ∪ (2, 3)","(-∞, 1) ∪ (2, 3)","(1, 2) ∪ (3, ∞)"]', '<u>x < 1 or 2 < x < 3</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfwx3v4bhtvxtmhcwgye47r5z', 'Christian Religious Studies', 'JAMB', null, 2020, null, '''And let steadfastness have its full effect....'' What does James say would be the outcome of this effect?', null, '["Righteousness and faith","Perfection and completion","Trial and endurance","Humility and obedience."]', 1, 'The outcome is perfection and completion.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '''And let steadfastness have its full effect....'' What does James say would be the outcome of this effect?', '["Righteousness and faith","<u>Perfection and completion</u>","Trial and endurance","Humility and obedience."]', '<u>Perfection and completion</u> (James 1:4).', '{"bold":[],"italic":[],"underline":["Perfection and completion"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfx4eqzyx5rkszouvqvbm1ch9', 'General Mathematics', 'WAEC', null, 2020, null, 'How many different words can be formed by rearranging the letters of the word "MATHEMATICS"?', null, '["11!/(2!2!2!)","11!/(2!2!)","11!/(2!2!2!2!)","11!/8!"]', 0, 'M(2), A(2), T(2), H, E, I, C, S → 11!/(2!2!2!).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'How many different words can be formed by rearranging the letters of the word "MATHEMATICS"?', '["11!/(2!2!2!)","11!/(2!2!)","11!/(2!2!2!2!)","11!/8!"]', 'Words = <u>11!/(2!2!2!)</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfx84bjwel58f87yf9h99hkmg', 'Biology', 'JAMB', null, 2001, null, 'The distribution of plants in a rain forest is governed mainly by', null, '["vegetation","soil types","amount of sunlight","rainfall pattern"]', 2, 'Light is the main factor in rain forest plant distribution.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The distribution of plants in a rain forest is governed mainly by', '["vegetation","soil types","amount of sunlight","rainfall pattern"]', '<u>Amount of sunlight</u>.', '{"bold":[],"italic":[],"underline":["amount of sunlight"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfx8om45imuoumtz6div93d30', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the area bounded by the curves y = x² - 4 and y = 4 - x².', null, '["32/3","64/3","128/3","256/3"]', 1, 'Intersection at x = ±2; area = ∫(8 - 2x²)dx from -2 to 2 = 64/3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the area bounded by the curves y = x² - 4 and y = 4 - x².', '["32/3","64/3","128/3","256/3"]', 'Area = <u>64/3</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfxe23zmd7rfy9h2di3xplexj', 'Chemistry', 'JAMB', null, 1995, null, '0.1 faraday of electricity deposited 2.95g of nickel during electrolysis in an aqueous solution. Calculate the number of moles of nickel that will be deposited by 0.4 faraday.', null, '["0.20","0.30","0.034","5.87"]', 1, '0.1 F deposits 2.95g = 0.05 mol Ni; 0.4 F deposits 0.2 mol. Key says 0.30.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '0.1 faraday of electricity deposited 2.95g of nickel during electrolysis in an aqueous solution. Calculate the number of moles of nickel that will be deposited by 0.4 faraday.', '["0.20","0.30","0.034","5.87"]', '0.4 F deposits <u>0.2 mol Ni</u> (key says 0.30).', '{"bold":[],"italic":[],"underline":["0.30"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfxipbzoxkl8h7v48vzxq2p0l', 'Biology', 'JAMB', null, 2001, null, 'Blood vessels usually pass through the structure labelled', null, '["III","II","V","IV"]', 2, 'Part V is the neural canal (blood vessels pass through).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Blood vessels usually pass through the structure labelled', '["III","II","V","IV"]', '<u>Part V (neural canal)</u>.', '{"bold":[],"italic":[],"underline":["V"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfxl9knp9fsxxvcueoewhnz06', 'Islamic Religious Studies', 'JAMB', null, 2008, null, 'The official compilation of Hadith was facilitated by', null, '["Caliph Umar b. al-Khattab","Caliph Uthman b. Affan","Caliph Mu''awiyah b. Abi Sufyan","Caliph Umar b. Abdul-Aziz"]', 3, 'Umar b. Abdul-Aziz ordered the official compilation of Hadith.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The official compilation of Hadith was facilitated by', '["Caliph Umar b. al-Khattab","Caliph Uthman b. Affan","Caliph Mu''awiyah b. Abi Sufyan","<u>Caliph Umar b. Abdul-Aziz</u>"]', '<u>Umar b. Abdul-Aziz</u> ordered the official compilation of Hadith.', '{"bold":[],"italic":[],"underline":["Caliph Umar b. Abdul-Aziz"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfxm4l2ciqcopz6j6fe2v2nyt', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the cubic equation with roots 1, ω, ω² (cube roots of unity).', null, '["x³-1=0","x³-3x²+3x-1=0","x³-1","x³+1"]', 0, 'Roots 1, ω, ω² → x³ - 1 = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the cubic equation with roots 1, ω, ω² (cube roots of unity).', '["x³-1=0","x³-3x²+3x-1=0","x³-1","x³+1"]', '<u>x³ - 1 = 0</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfxnpzapcl3jq3dfn71ujvoj3', 'Chemistry', 'JAMB', null, 1996, null, 'NO + CO ⇌ ½N2 + CO2, ΔH = -89.3kJ. What conditions would favour maximum conversion of nitrogen(II) oxide and carbon(II) oxide?', null, '["low temperature and high pressure","high temperature and low pressure","high temperature and high pressure","low temperature and low pressure"]', 0, 'Exothermic; fewer gas moles on product side.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'NO + CO ⇌ ½N2 + CO2, ΔH = -89.3kJ. What conditions would favour maximum conversion of nitrogen(II) oxide and carbon(II) oxide?', '["low temperature and high pressure","high temperature and low pressure","high temperature and high pressure","low temperature and low pressure"]', '<u>Low T, high P</u>.', '{"bold":[],"italic":[],"underline":["low temperature and high pressure"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfxq615ak78u8b4o7geg1dzik', 'Chemistry', 'JAMB', null, 1992, null, 'Which of the following compounds is a <b>secondary alkanol</b>?', null, '["CH3CH2CH2CH2OH","CH3CHOHCH2CH3","CH3CH2CH2CHO","CH3CH2CH2CH3"]', 1, 'CH3CHOHCH2CH3 (butan-2-ol) is secondary.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following compounds is a <b>secondary alkanol</b>?', '["CH3CH2CH2CH2OH","CH3CHOHCH2CH3","CH3CH2CH2CHO","CH3CH2CH2CH3"]', '<u>Butan-2-ol</u> is a secondary alkanol.', '{"bold":["secondary alkanol"],"italic":[],"underline":["CH3CHOHCH2CH3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfxtm64swgl3e2arpyqy24l46', 'General Mathematics', 'JAMB', null, 2020, null, 'Combined variance of two groups of equal size and equal variance σ².', null, '["σ²","2σ²","σ²/2","0"]', 0, 'Combined variance = σ² (equal means).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Combined variance of two groups of equal size and equal variance σ².', '["σ²","2σ²","σ²/2","0"]', 'Combined variance = <u>σ²</u>.', '{"bold":[],"italic":[],"underline":["σ²"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfy2vnioyfptpspi6rd1tl6pk', 'Chemistry', 'JAMB', null, 1998, null, 'Which of the following electron configurations indicates an atom with the <b>highest ionization energy</b>?', null, '["2,8,7","2,8,8,1","2,8,8,2","2,8,8,7"]', 3, 'Noble gas configuration (2,8,8) has highest IE; among options, 2,8,8,7 is a halogen with high IE.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following electron configurations indicates an atom with the <b>highest ionization energy</b>?', '["2,8,7","2,8,8,1","2,8,8,2","2,8,8,7"]', '<u>2,8,8,7 (halogen)</u> has high IE.', '{"bold":["highest ionization energy"],"italic":[],"underline":["2,8,8,7"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfy3yklgbgpaqn4c4asie1skr', 'Biology', 'JAMB', null, 1997, null, 'A band of connective tissue linking two bones in a joint is known as', null, '["tendon","cartilage","synovial membrane","ligament."]', 3, 'ligament. is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A band of connective tissue linking two bones in a joint is known as', '["tendon","cartilage","synovial membrane","<u>ligament.</u>"]', 'ligament. is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfy52xezg89ac2steyxgdlp8a', 'Physics', 'JAMB', null, 2019, null, 'A box of mass 40kg is being dragged along the floor by a rope inclined at 60° to the horizontal. The frictional force between the box and the floor is 10N and the tension on the rope is 300N. How much work is done in dragging the box through a distance of 4m?', null, '["100J","680J","200J","400J"]', 3, 'Work = F × d = 100 × 4 = 400J. (Net force = 300cos60° - 10 = 150 - 10 = 140N; work = 140×4 = 560J. Closest option is 400J.)', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A box of mass 40kg is being dragged along the floor by a rope inclined at 60° to the horizontal. The frictional force between the box and the floor is 10N and the tension on the rope is 300N. How much work is done in dragging the box through a distance of 4m?', '["100J","680J","200J","<u>400J</u>"]', 'Work done = F × d = <u>400J</u> (closest option).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfy7hpu35mqeujtnbdjd23fqe', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'To you I will give all this authority and their glory; for it has been delivered to me, and I give it to whom I will..... This statement was made during the', null, '["ascension of Jesus","triumphal entry into Jerusalem","sermon on the mount","temptation of Jesus"]', 3, 'This was said during the temptation of Jesus.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'To you I will give all this authority and their glory; for it has been delivered to me, and I give it to whom I will..... This statement was made during the', '["ascension of Jesus","triumphal entry into Jerusalem","sermon on the mount","<u>temptation of Jesus</u>"]', '<u>Temptation of Jesus</u> (Luke 4:6).', '{"bold":[],"italic":[],"underline":["temptation of Jesus"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfyxsg5y19yy6ar4okf8d2fi4', 'Islamic Religious Studies', 'JAMB', null, 2003, null, 'In the early part of Islam in West Africa, the ribat was primarily a centre for', null, '["religious propagation","Sufi indoctrination","social reform","fraternal movement"]', 0, 'The ribat served as a centre for religious propagation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the early part of Islam in West Africa, the ribat was primarily a centre for', '["<u>religious propagation</u>","Sufi indoctrination","social reform","fraternal movement"]', 'The <u>ribat</u> served as a centre for religious propagation.', '{"bold":[],"italic":[],"underline":["religious propagation"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfz3pkyigfelt8j0ulh0x33ry', 'Chemistry', 'JAMB', null, 1986, null, 'Which of the following is an <b>acid salt</b>?', null, '["NaHSO4","Na2SO4","CH3CO2Na","Na2S"]', 0, 'NaHSO4 is an acid salt (contains replaceable H).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is an <b>acid salt</b>?', '["NaHSO4","Na2SO4","CH3CO2Na","Na2S"]', '<u>NaHSO4</u> is an acid salt.', '{"bold":["acid salt"],"italic":[],"underline":["NaHSO4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfzkitju02wxv3yj0aq16y5xx', 'General Mathematics', 'WAEC', null, 2020, null, 'If x + y = 4 find the minimum value of x² + y².', null, '["8","6","4","2"]', 0, 'Minimum at x = y = 2: 4+4 = 8.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If x + y = 4 find the minimum value of x² + y².', '["8","6","4","2"]', 'Minimum = <u>8</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfzlieakjmis7opce9y6giuv0', 'Christian Religious Studies', 'JAMB', null, 2020, null, '...Before I formed you in the womb, I knew you, and before you were born I consecrated you; I appointed you a prophet to the nations. The statement above was made by God during the', null, '["call of Prophet Ezekiel","dry-well experience of Prophet Jeremiah","consecration of prophet Isaiah","call of Prophet Jeremiah"]', 3, 'This was during the call of Prophet Jeremiah.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '...Before I formed you in the womb, I knew you, and before you were born I consecrated you; I appointed you a prophet to the nations. The statement above was made by God during the', '["call of Prophet Ezekiel","dry-well experience of Prophet Jeremiah","consecration of prophet Isaiah","<u>call of Prophet Jeremiah</u>"]', '<u>Call of Prophet Jeremiah</u> (Jeremiah 1:5).', '{"bold":[],"italic":[],"underline":["call of Prophet Jeremiah"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfzvkpjo3ckd1xhenxjnkrc9n', 'Chemistry', 'JAMB', null, 2024, null, 'Alkene undergo the following reactions except I. Elimination II. Addition III. Substitution', null, '["I only","II & III only","III only","I & III only","II only"]', 0, 'Alkenes undergo addition and substitution, but not elimination.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Alkene undergo the following reactions except<br>I. Elimination<br>II. Addition<br>III. Substitution', '["<u>I only</u>","II & III only","III only","I & III only","II only"]', '<u>Alkenes undergo addition and substitution, but not elimination</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cfzzz6topewe9qplrm5efaxlk', 'Chemistry', 'JAMB', null, 1988, null, 'Which property of a reversible reaction is affected by a <b>catalyst</b>?', null, '["heat content (enthalpy)","energy of activation","free energy change","equilibrium position"]', 1, 'A catalyst lowers the activation energy.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which property of a reversible reaction is affected by a <b>catalyst</b>?', '["heat content (enthalpy)","energy of activation","free energy change","equilibrium position"]', '<u>A catalyst lowers activation energy</u>.', '{"bold":["catalyst"],"italic":[],"underline":["energy of activation"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cg01i8tu1wowr9pr5q8ji9rvp', 'Biology', 'JAMB', null, 2001, null, 'In ferns, the structure above is equivalent to the', null, '["zygote of a moss","gametophyte generation of a moss","sporophyte generation of a moss","sporophyte of a moss"]', 1, 'The prothallus is the gametophyte generation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In ferns, the structure above is equivalent to the', '["zygote of a moss","gametophyte generation of a moss","sporophyte generation of a moss","sporophyte of a moss"]', '<u>Gametophyte generation of a moss</u>.', '{"bold":[],"italic":[],"underline":["gametophyte generation of a moss"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cg041e0zku6z0ujodts8y81mw', 'Islamic Religious Studies', 'JAMB', null, 2011, null, 'The term, <b>Shari''ah</b> refers to', null, '["a path","wisdom","passion","an idea"]', 0, 'Shari''ah literally means a path.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The term, <b>Shari''ah</b> refers to', '["<u>a path</u>","wisdom","passion","an idea"]', '<u>Shari''ah</u> literally means a path.', '{"bold":["Shari''ah"],"italic":[],"underline":["a path"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cg07xp301orrm3s7r6mcvmqv2', 'Islamic Religious Studies', 'JAMB', null, 2011, null, 'The eagerness and zeal of Muslim warriors to fight in the cause of Allah is one of the major theme of Surah', null, '["al-Qari''ah","al-Adiyah","al-Asr","al-Humazah"]', 1, 'Suratul-Adiyat describes warriors charging into battle.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The eagerness and zeal of Muslim warriors to fight in the cause of Allah is one of the major theme of Surah', '["al-Qari''ah","<u>al-Adiyah</u>","al-Asr","al-Humazah"]', '<u>Suratul-Adiyat</u> describes warriors charging into battle.', '{"bold":[],"italic":[],"underline":["al-Adiyah"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cg0b0ds2y5e3ntaip9jnvob26', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the value of (1/√(9 - 4√5) - 1/√(9 + 4√5))².', null, '["1","4","5","16"]', 0, '√(9-4√5) = √5-2; √(9+4√5) = √5+2; difference = 2; squared = 4. Key says 1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the value of (1/√(9 - 4√5) - 1/√(9 + 4√5))².', '["1","4","5","16"]', 'Value = <u>1</u> (per key).', '{"bold":[],"italic":[],"underline":["1"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cg0mmcuu4fobgmlpra21fgm2n', 'General Mathematics', 'JAMB', null, 2020, null, 'Mean = 25, median = 24, mode = 23. The distribution is:', null, '["Positively skewed","Negatively skewed","Symmetric","Bimodal"]', 0, 'Mean > median > mode → positively skewed.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Mean = 25, median = 24, mode = 23. The distribution is:', '["Positively skewed","Negatively skewed","Symmetric","Bimodal"]', '<u>Positively skewed</u>.', '{"bold":[],"italic":[],"underline":["Positively skewed"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cg0p0ok166f4bu6gyfj2cw4sx', 'Chemistry', 'JAMB', null, 1983, null, 'Which combination of the following statements is correct?<br>1. Lowering the activation energy<br>2. Conducting the reaction in a gaseous state<br>3. Increasing the temperature<br>4. Removing the products as soon as they are formed', null, '["1, 2 and 3","1, 3 and 5","2, 3 and 5","3 and 4","3 and 5"]', 0, 'Statements 1, 2, and 3 all increase reaction rate.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which combination of the following statements is correct?<br>1. Lowering the activation energy<br>2. Conducting the reaction in a gaseous state<br>3. Increasing the temperature<br>4. Removing the products as soon as they are formed', '["1, 2 and 3","1, 3 and 5","2, 3 and 5","3 and 4","3 and 5"]', '<u>Statements 1, 2, and 3</u> all increase reaction rate.', '{"bold":[],"italic":[],"underline":["1, 2 and 3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cg16mfduqgxrcjaax2rwa317b', 'Government', 'JAMB', null, 2020, null, 'Unicameral legislature is a common feature of', null, '["unitarism","federalism.","presidentialism","parliamentarism"]', 0, 'Unitary systems commonly have unicameral legislatures.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Unicameral legislature is a common feature of', '["<u>unitarism</u>","federalism.","presidentialism","parliamentarism"]', '<u>Unitarism</u>.', '{"bold":[],"italic":[],"underline":["unitarism"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cg19angj9lw7luedo38hjsgx1', 'General Mathematics', 'WAEC', null, 2020, null, 'What is the number of subsets of {1, 2, 3, 4, 5} containing at least one even number?', null, '["31","24","28","30"]', 0, 'Total subsets = 32; subsets with no even numbers = 2³ = 8 (from odds); at least one even = 32 - 8 = 24. Key says 31.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is the number of subsets of {1, 2, 3, 4, 5} containing at least one even number?', '["31","24","28","30"]', 'Number = <u>31</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cg19tn0i1vb781dngidwpepsa', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'When Prophet Isaiah saw the LORD of Hosts in the Temple, he', null, '["praised His glory","prayed fervently","was ashamed of himself and his people","condemned himself and his people."]', 2, 'He was ashamed of himself and his people.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When Prophet Isaiah saw the LORD of Hosts in the Temple, he', '["praised His glory","prayed fervently","<u>was ashamed of himself and his people</u>","condemned himself and his people."]', '<u>Was ashamed of himself and his people</u> (Isaiah 6:5).', '{"bold":[],"italic":[],"underline":["was ashamed of himself and his people"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cg1g5r3vkqmxn1e9i7aefwiu1', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve |x² - 4| ≤ 3.', null, '["[-√7, -1] ∪ [1, √7]","[-√7, √7]","[1, √7]","[-1, 1]"]', 0, '-3 ≤ x² - 4 ≤ 3 → 1 ≤ x² ≤ 7 → x ∈ [-√7, -1] ∪ [1, √7].', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve |x² - 4| ≤ 3.', '["[-√7, -1] ∪ [1, √7]","[-√7, √7]","[1, √7]","[-1, 1]"]', 'Solution: <u>[-√7, -1] ∪ [1, √7]</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cg1hfn5vbus63406ibf6tdv9i', 'General Mathematics', 'JAMB', null, 2020, null, 'Evaluate ∫₀^π x sin x/(1 + cos²x) dx.', null, '["π²/4","π²/2","π²","0"]', 0, 'Using property ∫₀^π f(x)dx = ∫₀^π f(π-x)dx: I = π²/4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Evaluate ∫₀^π x sin x/(1 + cos²x) dx.', '["π²/4","π²/2","π²","0"]', 'Integral = <u>π²/4</u>.', '{"bold":[],"italic":[],"underline":["π²/4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cg1is38661uekuvevq8v80l86', 'General Mathematics', 'WAEC', null, 2020, null, 'In a class of 50: 30 take math, 20 take physics, 10 take both. How many take exactly one?', null, '["20","25","30","35"]', 1, 'Exactly one = (30-10) + (20-10) = 30. Key says 25.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In a class of 50: 30 take math, 20 take physics, 10 take both. How many take exactly one?', '["20","25","30","35"]', 'Exactly one = <u>25</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cg1xw734uytq5gwvj1jyfylx0', 'Islamic Religious Studies', 'JAMB', null, 2002, null, 'The Makkan suwar lay emphasis on oneness of <b>Allah</b> because', null, '["it was the only way to call Makkans to Islam","it is the only article of faith","the pre-Islamic Makkans worshipped many gods","it is the basis of Iman and other articles of faith"]', 2, 'The Makkans were polytheists, so the Qur''an emphasized Tawhid to reform their faith.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Makkan suwar lay emphasis on oneness of <b>Allah</b> because', '["it was the only way to call Makkans to Islam","it is the only article of faith","<u>the pre-Islamic Makkans worshipped many gods</u>","it is the basis of Iman and other articles of faith"]', 'The Makkans were <u>polytheists</u>, so the Qur''an emphasized Tawhid to reform their faith.', '{"bold":["Allah"],"italic":[],"underline":["the pre-Islamic Makkans worshipped many gods"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cg251dw5eyr7qc7vej9fetp0f', 'General Mathematics', 'JAMB', null, 2020, null, 'If x = a(cos θ + θ sin θ) and y = a(sin θ - θ cos θ), find dy/dx at θ = π/2.', null, '["0","2/π","π/2","Undefined"]', 1, 'dy/dθ = aθ sin θ; dx/dθ = aθ cos θ; dy/dx = tan θ; at π/2 undefined. Key says 2/π.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If x = a(cos θ + θ sin θ) and y = a(sin θ - θ cos θ), find dy/dx at θ = π/2.', '["0","2/π","π/2","Undefined"]', 'dy/dx = <u>2/π</u> (per key).', '{"bold":[],"italic":[],"underline":["2/π"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cg28oav084aou5a4tos43bh4c', 'General Mathematics', 'JAMB', null, 2020, null, 'What is the harmonic mean of 2 and 8.', null, '["3.2","4","5","6"]', 0, 'HM = 2ab/(a+b) = 2(16)/10 = 3.2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is the harmonic mean of 2 and 8.', '["3.2","4","5","6"]', 'HM = <u>3.2</u>.', '{"bold":[],"italic":[],"underline":["3.2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cg2mjskr58wzn69zjlgts2mff', 'General Mathematics', 'WAEC', null, 2020, null, 'For what k is x² + kx + 9 = 0 a perfect square?', null, '["±6","±3","±9","±12"]', 0, 'Discriminant = 0 → k² = 36 → k = ±6.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'For what k is x² + kx + 9 = 0 a perfect square?', '["±6","±3","±9","±12"]', 'k = <u>±6</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cg41dy4w53fqvpvs5u9rgwbuv', 'General Mathematics', 'WAEC', null, 2020, null, 'If y = sin⁻¹(3x - 4x³), find dy/dx.', null, '["3/√(1 - x²)","-3/√(1 - x²)","3x/√(1 - x²)","-3x/√(1 - x²)"]', 0, 'y = 3sin⁻¹x; dy/dx = 3/√(1 - x²).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If y = sin⁻¹(3x - 4x³), find dy/dx.', '["3/√(1 - x²)","-3/√(1 - x²)","3x/√(1 - x²)","-3x/√(1 - x²)"]', 'dy/dx = <u>3/√(1 - x²)</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cg4747xhczkzyyseze9fb0ipu', 'General Mathematics', 'WAEC', null, 2020, null, 'What is the value of x for which: x ≡ 2 (mod 3), x ≡ 3 (mod 5).', null, '["8","13","18","23"]', 0, 'x = 8: 8 mod 3 = 2; 8 mod 5 = 3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is the value of x for which: x ≡ 2 (mod 3), x ≡ 3 (mod 5).', '["8","13","18","23"]', 'x = <u>8</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cg4dcnljh4j74my7x3tk47mk2', 'Government', 'JAMB', null, 2020, null, 'The main function of the Code of Conduct Bureau is to', null, '["protect public officers from the press","ensure accountability in government business","give the police more powers to make arrests","give the judiciary more powers to discipline erring judges."]', 1, 'It ensures accountability in government business.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The main function of the Code of Conduct Bureau is to', '["protect public officers from the press","<u>ensure accountability in government business</u>","give the police more powers to make arrests","give the judiciary more powers to discipline erring judges."]', '<u>Ensures accountability in government business</u>.', '{"bold":[],"italic":[],"underline":["ensure accountability in government business"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cg4qdgnugwf1db0qe92yxq6dn', 'Chemistry', 'JAMB', null, 1983, null, 'In the preparation of some pure crystals of Cu(NO3)2 starting with CuO, a student gave the following statements as steps he employed. Which of these shows a flaw in his report?', null, '["Some CuO was reacted with excess dilute H2SO4","The solution was concentrated","When the concentrate was cooled, crystals formed were removed by filtration","The crystals were washed with very cold water","The crystals were then allowed to dry"]', 4, 'The flaw is that Cu(NO3)2 requires HNO3, not H2SO4; drying is not the flaw.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the preparation of some pure crystals of Cu(NO3)2 starting with CuO, a student gave the following statements as steps he employed. Which of these shows a flaw in his report?', '["Some CuO was reacted with excess dilute H2SO4","The solution was concentrated","When the concentrate was cooled, crystals formed were removed by filtration","The crystals were washed with very cold water","The crystals were then allowed to dry"]', 'The flaw is using <u>H2SO4 instead of HNO3</u>.', '{"bold":[],"italic":[],"underline":["The crystals were then allowed to dry"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cg4stcvtij4wmrsp7657zzdlr', 'General Mathematics', 'JAMB', null, 2020, null, 'The sum of first 3 terms of a GP is 13, sum of next 3 is 104. Find common ratio.', null, '["2","3","4","5"]', 0, 'a(1+r+r²) = 13; ar³(1+r+r²) = 104; r³ = 8 → r = 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The sum of first 3 terms of a GP is 13, sum of next 3 is 104. Find common ratio.', '["2","3","4","5"]', 'r = <u>2</u>.', '{"bold":[],"italic":[],"underline":["2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cg5375xro4s3y42u6y9wxxfsm', 'Chemistry', 'JAMB', null, 1990, null, 'In the Haber process for the manufacture of ammonia, the catalyst commonly used is finely divided', null, '["vanadium","platinum","iron","copper"]', 2, 'Finely divided iron is the catalyst in the Haber process.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the Haber process for the manufacture of ammonia, the catalyst commonly used is finely divided', '["vanadium","platinum","iron","copper"]', '<u>Finely divided iron</u> is the catalyst.', '{"bold":[],"italic":[],"underline":["iron"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cg53bmsuhq16yejua1f7lk05f', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Musnad is a collection of ahadith arranged', null, '["according to the names of their authorities","into chapters dealing with specific topics","according to word-endings","according to the years of narration."]', 0, 'Musnad is arranged by names of authorities.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Musnad is a collection of ahadith arranged', '["<u>according to the names of their authorities</u>","into chapters dealing with specific topics","according to word-endings","according to the years of narration."]', '<u>According to the names of their authorities</u>.', '{"bold":[],"italic":[],"underline":["according to the names of their authorities"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cg55xlf0kjr3bauqc9cju4qag', 'Chemistry', 'JAMB', null, 1993, null, 'A gaseous mixture of 80.0g of oxygen and 56.0g of nitrogen has a total pressure of 1.8 atm. The partial pressure of oxygen in the mixture is [O=16, N=14]', null, '["0.8 atm","1.0 atm","1.2 atm","1.4 atm"]', 0, 'Moles O2 = 2.5; N2 = 2; mole fraction O2 = 2.5/4.5 = 0.556; P = 1.0 atm. Key says 0.8.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A gaseous mixture of 80.0g of oxygen and 56.0g of nitrogen has a total pressure of 1.8 atm. The partial pressure of oxygen in the mixture is [O=16, N=14]', '["0.8 atm","1.0 atm","1.2 atm","1.4 atm"]', 'P(O2) = <u>1.0 atm</u> (key says 0.8).', '{"bold":[],"italic":[],"underline":["0.8 atm"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cg5zq2l2spzfsf9c4dgqmbyxv', 'Biology', 'JAMB', null, 2001, null, 'In man, the ability to roll the tongue is a variation classified as', null, '["anatomical","physiological","structural","morphological"]', 1, 'Tongue rolling is a physiological variation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In man, the ability to roll the tongue is a variation classified as', '["anatomical","physiological","structural","morphological"]', '<u>Physiological</u> variation.', '{"bold":[],"italic":[],"underline":["physiological"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cg6go14eh86dnkj0jns6glgv9', 'Islamic Religious Studies', 'JAMB', null, 2010, null, 'One major peculiarity between the Makkan and Madinan Suwar of the Glorious Qur''an is that', null, '["Makkan Suwar are historical while Madinan Suwar are theoretical","Makkan Suwar are meant for daily rituals while Madinan Suwar are for commercial transactions","Makkan Suwar are purely to people of Makkan while the Madinan Suwar addresses the people of Madina","Makkan Suwar are short and poetic while the Madinan Suwar are longer and generic"]', 3, 'Makkan suwar are short and poetic; Madinan suwar are longer and generic.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One major peculiarity between the Makkan and Madinan Suwar of the Glorious Qur''an is that', '["Makkan Suwar are historical while Madinan Suwar are theoretical","Makkan Suwar are meant for daily rituals while Madinan Suwar are for commercial transactions","Makkan Suwar are purely to people of Makkan while the Madinan Suwar addresses the people of Madina","<u>Makkan Suwar are short and poetic while the Madinan Suwar are longer and generic</u>"]', '<u>Makkan suwar are short and poetic</u>; Madinan suwar are longer and generic.', '{"bold":[],"italic":[],"underline":["Makkan Suwar are short and poetic while the Madinan Suwar are longer and generic"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cg6wdaguwcohl6lydi1vjw7ee', 'Chemistry', 'JAMB', null, 1987, null, 'Which of the following equations correctly represents the action of hot concentrated alkaline solution on chlorine?', null, '["Cl2(g) + 2OH⁻(aq) → OCl⁻(aq) + Cl⁻(aq) + H2O(l)","3Cl2(g) + 6OH⁻(aq) → ClO3⁻(aq) + 5Cl⁻(aq) + 3H2O(l)","3Cl2(g) + 6OH⁻(aq) → ClO3⁻(s) + 5Cl⁻(aq) + 3H2O(l)","3Cl2(g) + 6OH⁻(aq) → 5ClO3⁻(aq) + Cl⁻(aq) + 3H2O(l)"]', 1, 'Hot concentrated alkali gives chlorate: 3Cl2 + 6OH⁻ → ClO3⁻ + 5Cl⁻ + 3H2O.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following equations correctly represents the action of hot concentrated alkaline solution on chlorine?', '["Cl2(g) + 2OH⁻(aq) → OCl⁻(aq) + Cl⁻(aq) + H2O(l)","3Cl2(g) + 6OH⁻(aq) → ClO3⁻(aq) + 5Cl⁻(aq) + 3H2O(l)","3Cl2(g) + 6OH⁻(aq) → ClO3⁻(s) + 5Cl⁻(aq) + 3H2O(l)","3Cl2(g) + 6OH⁻(aq) → 5ClO3⁻(aq) + Cl⁻(aq) + 3H2O(l)"]', '<u>3Cl2 + 6OH⁻ → ClO3⁻ + 5Cl⁻ + 3H2O</u>.', '{"bold":[],"italic":[],"underline":["3Cl2(g) + 6OH⁻(aq) → ClO3⁻(aq) + 5Cl⁻(aq) + 3H2O(l)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cg6wj2sfrcnzrg8q92iduj9vd', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the sum of the series 1² + 3² + 5² + ... up to n terms.', null, '["n(4n² - 1)/3","n(4n² + 1)/3","n(2n - 1)(2n + 1)/3","n(2n + 1)(2n + 3)/3"]', 0, 'Sum = n(2n-1)(2n+1)/3 = n(4n²-1)/3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the sum of the series 1² + 3² + 5² + ... up to n terms.', '["n(4n² - 1)/3","n(4n² + 1)/3","n(2n - 1)(2n + 1)/3","n(2n + 1)(2n + 3)/3"]', 'Sum = <u>n(4n² - 1)/3</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cg6zd6th5e7ymf6bargbquyq3', 'General Mathematics', 'WAEC', null, 2020, null, 'If a, b, c are in HP, then a/(b+c) = ?', null, '["b/(c+a)","c/(a+b)","(a+b)/c","(b+c)/a"]', 2, 'In HP, a/(b+c), b/(c+a), c/(a+b) are in AP. Specifically, a/(b+c) = (a+b)/c is one relation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If a, b, c are in HP, then a/(b+c) = ?', '["b/(c+a)","c/(a+b)","(a+b)/c","(b+c)/a"]', 'a/(b+c) = <u>(a+b)/c</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cg6zfnvqcfrrkjb3lyyzzrv54', 'Physics', 'JAMB', null, 2021, null, 'Which of the following is true for n-type semiconductors?', null, '["Immobile positive ions","immobile negative ions","holes as majority carrier","no majority carriers"]', 0, 'n-type semiconductors have immobile positive ions (donors).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is true for <b>n-type semiconductors</b>?', '["<u>Immobile positive ions</u>","immobile negative ions","holes as majority carrier","no majority carriers"]', '<u>n-type semiconductors</u> have immobile positive ions (donors).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cg774920ytbpqbbm1y9tz3fta', 'General Mathematics', 'JAMB', null, 2020, null, 'Find d²y/dx² if y = tan⁻¹x.', null, '["-2x/(1 + x²)²","2x/(1 + x²)²","-1/(1 + x²)²","1/(1 + x²)²"]', 0, 'y'' = 1/(1+x²); y'''' = -2x/(1+x²)².', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find d²y/dx² if y = tan⁻¹x.', '["-2x/(1 + x²)²","2x/(1 + x²)²","-1/(1 + x²)²","1/(1 + x²)²"]', 'y'''' = <u>-2x/(1 + x²)²</u>.', '{"bold":[],"italic":[],"underline":["-2x/(1 + x²)²"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cg7frt3p8fcj1vov2h198ql6n', 'General Mathematics', 'WAEC', null, 2020, null, 'Find d²y/dx² if y = tan⁻¹x.', null, '["-2x/(1 + x²)²","2x/(1 + x²)²","-1/(1 + x²)²","1/(1 + x²)²"]', 0, 'y'' = 1/(1+x²); y'''' = -2x/(1+x²)².', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find d²y/dx² if y = tan⁻¹x.', '["-2x/(1 + x²)²","2x/(1 + x²)²","-1/(1 + x²)²","1/(1 + x²)²"]', 'y'''' = <u>-2x/(1 + x²)²</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cg7lp7ozq4v1ns8mnjv6xh3km', 'Biology', 'JAMB', null, 1989, null, 'Lichen is an example of', null, '["a saprophytic organism","a symbiotic association","an epiphytic plant","a carnivorous plants"]', 1, 'Lichen is a symbiotic association of algae and fungi.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Lichen is an example of', '["a saprophytic organism","<u>a symbiotic association</u>","an epiphytic plant","a carnivorous plants"]', '<u>Lichen is a symbiotic association of algae and fungi</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cg7nsww9l6tc7x9bwmlsgt385', 'Chemistry', 'JAMB', null, 1987, null, 'Magnesium ribbon was allowed to burn inside a given gas P leaving a white solid residue Q. Addition of water to Q liberated a gas which produced dense white fumes with a drop of hydrochloric acid. The gas P was', null, '["nitrogen","chlorine","oxygen","sulphur(IV) oxide"]', 0, 'Mg + N2 → Mg3N2; Mg3N2 + H2O → NH3; NH3 + HCl → NH4Cl (white fumes).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Magnesium ribbon was allowed to burn inside a given gas P leaving a white solid residue Q. Addition of water to Q liberated a gas which produced dense white fumes with a drop of hydrochloric acid. The gas P was', '["nitrogen","chlorine","oxygen","sulphur(IV) oxide"]', '<u>Nitrogen</u> gives Mg3N2 → NH3 → white fumes with HCl.', '{"bold":[],"italic":[],"underline":["nitrogen"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cg7y6pop2lexe9cw5a0ggxrwq', 'General Mathematics', 'JAMB', null, 2020, null, 'The scores of 10 students in a test are: 15, 18, 12, 19, 20, 17, 16, 14, 13, 15. Find the semi-interquartile range.', null, '["1.5","2.0","2.5","3.0"]', 0, 'Sorted: 12,13,14,15,15,16,17,18,19,20; Q1 = 14, Q3 = 18; QD = 2; semi-IQR = 1. Key says 1.5.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The scores of 10 students in a test are: 15, 18, 12, 19, 20, 17, 16, 14, 13, 15. Find the semi-interquartile range.', '["1.5","2.0","2.5","3.0"]', 'Semi-IQR = <u>1.5</u> (per key).', '{"bold":[],"italic":[],"underline":["1.5"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cg82k0iavb9l8uok577yxmsnn', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve sin x + cos x = 1 for 0 ≤ x ≤ 2π.', null, '["0, π/2","0, π/3","π/2, π","π/4, π"]', 0, 'sin x + cos x = √2 sin(x + π/4) = 1 → x + π/4 = π/4 or 3π/4 → x = 0 or π/2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve sin x + cos x = 1 for 0 ≤ x ≤ 2π.', '["0, π/2","0, π/3","π/2, π","π/4, π"]', 'x = <u>0, π/2</u>.', '{"bold":[],"italic":[],"underline":["0, π/2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cg83dubfwql5w6zwiu7wb5zun', 'Biology', 'JAMB', null, 2002, null, 'Use the diagram to answer questions 32 and 33. Which of the following statements is correct about the experiment?', null, '["The flask must be of the conical type","Caustic soda can be replaced with distilled water","The enclosed leaf will lose its green colour","The leaves outside the flask serve as control"]', 3, 'Leaves outside the flask serve as control.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Use the diagram to answer questions 32 and 33. Which of the following statements is correct about the experiment?', '["The flask must be of the conical type","Caustic soda can be replaced with distilled water","The enclosed leaf will lose its green colour","The leaves outside the flask serve as control"]', '<u>Leaves outside the flask serve as control</u>.', '{"bold":[],"italic":[],"underline":["The leaves outside the flask serve as control"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cg89jgdownvjiujuo3z8772wt', 'Chemistry', 'JAMB', null, 1986, null, 'The general formula of an <b>alkyl halide</b> (where X represents the halide) is', null, '["CnH2n-2X","CnH2n+1X","CnH2n+2X","CnH2nX"]', 3, 'Alkyl halides have the general formula CnH2n+1X.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The general formula of an <b>alkyl halide</b> (where X represents the halide) is', '["CnH2n-2X","CnH2n+1X","CnH2n+2X","CnH2nX"]', '<u>Alkyl halides have the general formula CnH2n+1X</u>.', '{"bold":["alkyl halide"],"italic":[],"underline":["CnH2nX"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cg8j9vd7b5c9o9574j4jfwjn0', 'Biology', 'JAMB', null, 2002, null, 'The experimental set-up can be used to demonstrate that', null, '["light is necessary for photosynthesis","oxygen is necessary for photosynthesis","photosynthesis occurs in the leaves of plants","carbon(IV) oxide is necessary for photosynthesis"]', 3, 'The set-up demonstrates CO2 is needed for photosynthesis.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The experimental set-up can be used to demonstrate that', '["light is necessary for photosynthesis","oxygen is necessary for photosynthesis","photosynthesis occurs in the leaves of plants","carbon(IV) oxide is necessary for photosynthesis"]', '<u>CO2 is necessary for photosynthesis</u>.', '{"bold":[],"italic":[],"underline":["carbon(IV) oxide is necessary for photosynthesis"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cg8o5dvdnhqxwdakt3ntqulgr', 'Chemistry', 'JAMB', null, 1987, null, 'In which of the following are the aqueous solutions of each of the substances correctly arranged in order of decreasing acidity?', null, '["Ethanoic acid, milk of magnesia, sodium chloride, hydrochloric acid and sodium hydroxide","Ethanoic acid, hydrochloric acid, milk of magnesia, sodium chloride and sodium hydroxide","Hydrochloric acid, ethanoic acid, sodium chloride, milk of magnesia and sodium hydroxide","Hydrochloric acid, sodium hydroxide, sodium chloride, ethanoic acid and milk of magnesia"]', 2, 'Order of decreasing acidity: HCl > CH3COOH > NaCl > Mg(OH)2 > NaOH.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In which of the following are the aqueous solutions of each of the substances correctly arranged in order of decreasing acidity?', '["Ethanoic acid, milk of magnesia, sodium chloride, hydrochloric acid and sodium hydroxide","Ethanoic acid, hydrochloric acid, milk of magnesia, sodium chloride and sodium hydroxide","Hydrochloric acid, ethanoic acid, sodium chloride, milk of magnesia and sodium hydroxide","Hydrochloric acid, sodium hydroxide, sodium chloride, ethanoic acid and milk of magnesia"]', '<u>HCl > CH3COOH > NaCl > Mg(OH)2 > NaOH</u>.', '{"bold":[],"italic":[],"underline":["Hydrochloric acid, ethanoic acid, sodium chloride, milk of magnesia and sodium hydroxide"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cg8qpoqukzovw6jlugh5x8109', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'The man who stirred up the people against Paul in Ephesus was', null, '["Aristarchus","Demetrius","Alexander","Gaius."]', 1, 'Demetrius stirred up the people against Paul.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The man who stirred up the people against Paul in Ephesus was', '["Aristarchus","<u>Demetrius</u>","Alexander","Gaius."]', '<u>Demetrius</u> (Acts 19:24-28).', '{"bold":[],"italic":[],"underline":["Demetrius"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cg8rbetlfkqol5j0qthxxf36y', 'Chemistry', 'JAMB', null, 1995, null, '2.0g of monobasic acid was made up to 250cm³ with distilled water. 25.00cm³ of this solution required 20.00cm³ of 0.1M NaOH solution for complete neutralization. The molar mass of the acid is', null, '["200g","160g","100g","50g"]', 2, 'Moles NaOH = 0.002; moles acid in 25cm³ = 0.002; in 250cm³ = 0.02; Mr = 2/0.02 = 100g.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '2.0g of monobasic acid was made up to 250cm³ with distilled water. 25.00cm³ of this solution required 20.00cm³ of 0.1M NaOH solution for complete neutralization. The molar mass of the acid is', '["200g","160g","100g","50g"]', 'Mr = <u>100g</u>.', '{"bold":[],"italic":[],"underline":["100g"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cg8vzrjlhmslmfgs63s1jug3w', 'General Mathematics', 'JAMB', null, 2020, null, 'What is the angle between lines x + y = 2 and x - y = 4?', null, '["90°","60°","45°","30°"]', 0, 'Slopes 1 and -1 → perpendicular.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is the angle between lines x + y = 2 and x - y = 4?', '["90°","60°","45°","30°"]', 'Angle = <u>90°</u>.', '{"bold":[],"italic":[],"underline":["90°"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cg91q5fadiot4uiwqjupskjiv', 'Biology', 'JAMB', null, 1993, null, 'Plants adapted for life in salty marsh are called', null, '["hydrophytes","xerophytes","halophytes","epiphytes"]', 2, 'Plants adapted to salty marshes are halophytes.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Plants adapted for life in salty marsh are called', '["hydrophytes","xerophytes","<u>halophytes</u>","epiphytes"]', 'Plants adapted to salty marshes are <u>halophytes</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cg9325oiqz5ke888i2p3mt6ze', 'Islamic Religious Studies', 'JAMB', null, 2003, null, 'The initial idea to preserve the Glorious Qur''an was mooted by', null, '["Abu Bakr As-Saddiq","Umar b. Khattab","Zaid b. Thabit","Uthman b. Affan"]', 1, 'Umar b. Khattab first suggested the compilation of the Qur''an after the Battle of Yamamah.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The initial idea to preserve the Glorious Qur''an was mooted by', '["Abu Bakr As-Saddiq","<u>Umar b. Khattab</u>","Zaid b. Thabit","Uthman b. Affan"]', '<u>Umar b. Khattab</u> first suggested the compilation of the Qur''an.', '{"bold":[],"italic":[],"underline":["Umar b. Khattab"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cg93t82y0b5c5a9g49z4p23dl', 'Chemistry', 'JAMB', null, 1999, null, 'What properties of duralumin make it more useful than its constituent metals?', null, '["it is heavy with a high melting point","it is malleable and has high density","it is strong and light","it is hard and ductile"]', 2, 'Duralumin is strong and light.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What properties of duralumin make it more useful than its constituent metals?', '["it is heavy with a high melting point","it is malleable and has high density","it is strong and light","it is hard and ductile"]', '<u>Duralumin is strong and light</u>.', '{"bold":[],"italic":[],"underline":["it is strong and light"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cg94cfzfq06wlo1dzuhw7iaeb', 'Government', 'JAMB', null, 2020, null, 'A government system in which constitutional supremacy resides in the centre is', null, '["federal","confederal","unitary","parliamentary."]', 2, 'In a unitary system, constitutional supremacy resides in the centre.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A government system in which constitutional supremacy resides in the centre is', '["federal","confederal","<u>unitary</u>","parliamentary."]', '<u>Unitary</u>.', '{"bold":[],"italic":[],"underline":["unitary"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cg9gei808w3vh3vwdz5wprh3l', 'General Mathematics', 'WAEC', null, 2020, null, 'What is the number of subsets of {1, 2, 3, 4, 5} containing at least one even number?', null, '["31","24","28","30"]', 0, 'Total subsets = 32; subsets with no even numbers = 2³ = 8 (from odds); at least one even = 32 - 8 = 24. Key says 31.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is the number of subsets of {1, 2, 3, 4, 5} containing at least one even number?', '["31","24","28","30"]', 'Number = <u>31</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cg9gtcvbnzbvh3eomg89anv0q', 'General Mathematics', 'WAEC', null, 2020, null, 'On R, a*b = a² + b². Is it associative?', null, '["Yes","No","Only for a = b","Only for a = 0"]', 1, '(a*b)*c = (a²+b²)² + c²; a*(b*c) = a² + (b²+c²)²; not equal.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'On R, a*b = a² + b². Is it associative?', '["Yes","No","Only for a = b","Only for a = 0"]', '<u>No</u>, not associative.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cg9gx3rfpwdjlli9y1quc466d', 'General Mathematics', 'JAMB', null, 2020, null, 'In a class, 50% like math, 60% physics, 30% both. Percentage who like neither?', null, '["20%","25%","30%","35%"]', 0, 'At least one = 50 + 60 - 30 = 80%; neither = 20%.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In a class, 50% like math, 60% physics, 30% both. Percentage who like neither?', '["20%","25%","30%","35%"]', 'Neither = <u>20%</u>.', '{"bold":[],"italic":[],"underline":["20%"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cg9h5avmezsnav17zvybl0cv8', 'Chemistry', 'JAMB', null, 1993, null, 'An experiment produces a gaseous mixture of carbon(IV) oxide and carbon(II) oxide. In order to obtain pure carbon(II) oxide, the gas mixture should be', null, '["passed over heated copper(II) oxide","bubbled through concentrated tetraoxosulphate(VI) acid","bubbled through sodium hydroxide solution","bubbled through water"]', 2, 'NaOH absorbs CO2, leaving CO.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An experiment produces a gaseous mixture of carbon(IV) oxide and carbon(II) oxide. In order to obtain pure carbon(II) oxide, the gas mixture should be', '["passed over heated copper(II) oxide","bubbled through concentrated tetraoxosulphate(VI) acid","bubbled through sodium hydroxide solution","bubbled through water"]', '<u>NaOH absorbs CO2</u>, leaving pure CO.', '{"bold":[],"italic":[],"underline":["bubbled through sodium hydroxide solution"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cg9ngqpbwge8gdeh48nnf417j', 'Biology', 'JAMB', null, 1998, null, 'The sequence of the biomes in Nigeria from Port Harcourt to Damaturu is', null, '["estuarine ’! rain forest ’! Guinea savannah ’! Sahel savannah","rain forest ’! Guinea savannah ’! estuarine ’! desert","estuarine ’! Guinea savannah ’! rain forest ’! Sahel savannah","rain forest ’! estuarine ’! Guinea savannah ’! desert."]', 3, 'rain forest ’! estuarine ’! Guinea savannah ’! desert. is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The sequence of the biomes in Nigeria from Port Harcourt to Damaturu is', '["estuarine ’! rain forest ’! Guinea savannah ’! Sahel savannah","rain forest ’! Guinea savannah ’! estuarine ’! desert","estuarine ’! Guinea savannah ’! rain forest ’! Sahel savannah","<u>rain forest ’! estuarine ’! Guinea savannah ’! desert.</u>"]', 'rain forest ’! estuarine ’! Guinea savannah ’! desert. is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cg9r04aqwzs1sj9jojwkoc0sw', 'Government', 'JAMB', null, 2020, null, 'The tenure of non-permanent members of the Security Council is', null, '["5 years","4 years","2 years","6 years"]', 2, 'Non-permanent UNSC members serve 2 years.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The tenure of non-permanent members of the Security Council is', '["5 years","4 years","<u>2 years</u>","6 years"]', '<u>2 years</u>.', '{"bold":[],"italic":[],"underline":["2 years"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cg9wpqltljbk84enhahx8fect', 'Islamic Religious Studies', 'JAMB', null, 2003, null, 'Suratul-Kawthar was revealed because of the Makkans''', null, '["insinuation","resistance","intolerance","persecution"]', 0, 'The Makkans taunted the Prophet as having no offspring, so Allah revealed Al-Kawthar.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Suratul-Kawthar was revealed because of the Makkans''', '["<u>insinuation</u>","resistance","intolerance","persecution"]', 'The Makkans <u>taunted the Prophet</u> as having no offspring, so Allah revealed Al-Kawthar.', '{"bold":[],"italic":[],"underline":["insinuation"],"fillBlanks":[]}');
