insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cga8ghxlnzf2tbrlf5ay8agcr', 'Physics', 'JAMB', null, 2021, null, 'A body accelerating will have a constant speed if it is', null, '["Falling from a height","In equilibrium","moving on a straight line","none of the above"]', 2, 'A body moving in a straight line with constant speed has zero acceleration; but if accelerating, speed changes. Closest answer: moving on a straight line.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A body accelerating will have a constant speed if it is', '["Falling from a height","In equilibrium","<u>moving on a straight line</u>","none of the above"]', 'A body moving in a <u>straight line</u> with constant speed has zero acceleration.', null);
