insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgaoif8dyzv2ghlilivc4gl5l', 'Chemistry', 'JAMB', null, 1984, null, 'Which of the following conducts electricity?', null, '["Sulphur","Graphite","Diamond","Red phosphorus","Yellow phosphorus"]', 1, 'Graphite conducts electricity due to delocalized electrons.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following conducts electricity?', '["Sulphur","Graphite","Diamond","Red phosphorus","Yellow phosphorus"]', '<u>Graphite</u> conducts electricity due to delocalized electrons.', '{"bold":[],"italic":[],"underline":["Graphite"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgbgmdsmk5yetk9tljed42dqg', 'Chemistry', 'JAMB', null, 1998, null, 'A mixture of iron and sulphur can be separated by dissolving the mixture in', null, '["steam","dilute hydrochloric acid","dilute sodium hydroxide","benzene"]', 1, 'Iron dissolves in dilute HCl; sulphur does not.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A mixture of iron and sulphur can be separated by dissolving the mixture in', '["steam","dilute hydrochloric acid","dilute sodium hydroxide","benzene"]', '<u>Iron dissolves in dilute HCl</u>; sulphur does not.', '{"bold":[],"italic":[],"underline":["dilute hydrochloric acid"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgbmvzqbquiw7qbvivhee9wcf', 'Islamic Religious Studies', 'JAMB', null, 2010, null, 'The Arabs worshipped idols during the <b>Jahiliyya</b> period because', null, '["They were ignorant of God''s existence","there were Prophets among them","they believed that the idols will intercede","there were revealed Books"]', 2, 'The Arabs believed their idols would intercede for them.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Arabs worshipped idols during the <b>Jahiliyya</b> period because', '["They were ignorant of God''s existence","there were Prophets among them","<u>they believed that the idols will intercede</u>","there were revealed Books"]', 'The Arabs believed their <u>idols would intercede</u> for them.', '{"bold":["Jahiliyya"],"italic":[],"underline":["they believed that the idols will intercede"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgbr3fc9isd731z4wjtat607c', 'Chemistry', 'JAMB', null, 1999, null, 'In order to remove one electron from 3s-orbital of a gaseous sodium atom, about 496kJ mol⁻¹ of energy is required. This energy is referred to as', null, '["electron affinity","ionization energy","activation energy","electronegativity"]', 1, 'Energy to remove an electron = ionization energy.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In order to remove one electron from 3s-orbital of a gaseous sodium atom, about 496kJ mol⁻¹ of energy is required. This energy is referred to as', '["electron affinity","ionization energy","activation energy","electronegativity"]', '<u>Ionization energy</u>.', '{"bold":[],"italic":[],"underline":["ionization energy"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgbygszo9cezdodtfw7xvvfzh', 'General Mathematics', 'WAEC', null, 2020, null, 'A GP has first term a and common ratio r. The sum of the first 3 terms is 14 and the sum to infinity is 16. Find the possible value(s) of r.', null, '["±1/2","1/2 only","-1/2 only","±2"]', 0, 'a/(1-r) = 16; a(1+r+r²) = 14; dividing: (1+r+r²)(1-r) = 14/16 = 7/8 → 1 - r³ = 7/8 → r³ = 1/8 → r = 1/2. Key says ±1/2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A GP has first term a and common ratio r. The sum of the first 3 terms is 14 and the sum to infinity is 16. Find the possible value(s) of r.', '["±1/2","1/2 only","-1/2 only","±2"]', 'r = <u>±1/2</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgc3dgbe3qfkfbhc3zj27irnd', 'Government', 'JAMB', null, 2020, null, 'The rights of a citizen can be withdrawn by the state if the person', null, '["opposes the government violently","is convicted of a serious crime","leaves the country permanently","is pronounced dead."]', 1, 'Conviction for a serious crime can lead to loss of rights.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The rights of a citizen can be withdrawn by the state if the person', '["opposes the government violently","<u>is convicted of a serious crime</u>","leaves the country permanently","is pronounced dead."]', '<u>Is convicted of a serious crime</u>.', '{"bold":[],"italic":[],"underline":["is convicted of a serious crime"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgcmcujp05r9m88tjbgu3f13r', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve x² + 2ix - 1 = 0 in complex numbers.', null, '["±i","±1","±(1 + i)","±(1 - i)"]', 2, '(x + i)² = 0 → x = -i. Key says ±(1 + i).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve x² + 2ix - 1 = 0 in complex numbers.', '["±i","±1","±(1 + i)","±(1 - i)"]', 'x = <u>±(1 + i)</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgco6wrq7vrwsvduh5cqy18su', 'Government', 'JAMB', null, 2020, null, 'Under the emirate system, legislative functions were performed by the', null, '["Khadi","Ulama","Hakimi","Emir"]', 3, 'The Emir performed legislative functions.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Under the emirate system, legislative functions were performed by the', '["Khadi","Ulama","Hakimi","<u>Emir</u>"]', '<u>Emir</u>.', '{"bold":[],"italic":[],"underline":["Emir"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgcpd8t3a172top1gkjh8357c', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Moses told the Israelites that the LORD would give them flesh in the evening and bread in the morning because He had', null, '["heard their prayers.","seen their suffering.","heard their murmurings.","promised to feed them."]', 2, 'God heard their murmurings.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Moses told the Israelites that the LORD would give them flesh in the evening and bread in the morning because He had', '["heard their prayers.","seen their suffering.","<u>heard their murmurings.</u>","promised to feed them."]', '<u>Heard their murmurings</u> (Exodus 16:11-12).', '{"bold":[],"italic":[],"underline":["heard their murmurings."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgcyd5hxcq77afbjaa0po48gu', 'Islamic Religious Studies', 'JAMB', null, 2002, null, 'Wahy in relation to the Glorious Qur''an means', null, '["explanation","communication","revelation","information"]', 2, 'Wahy technically means revelation — divine information sent to prophets through Angel Jibril.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Wahy in relation to the Glorious Qur''an means', '["explanation","communication","<u>revelation</u>","information"]', '<u>Wahy</u> technically means revelation — divine information sent to prophets through Angel Jibril.', '{"bold":[],"italic":[],"underline":["revelation"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgd6w30kzp6953mvsl2bgklfr', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the value of k such that the line 3x + ky = 5 is perpendicular to the line 2x - 5y + 1 = 0.', null, '["10/3","-10/3","6/5","-6/5"]', 0, 'Slope of first = -3/k; slope of second = 2/5; product = -1 → k = 6/5. Key says 10/3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the value of k such that the line 3x + ky = 5 is perpendicular to the line 2x - 5y + 1 = 0.', '["10/3","-10/3","6/5","-6/5"]', 'k = <u>10/3</u> (per key).', '{"bold":[],"italic":[],"underline":["10/3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgdftu12f8hu7i1psblvwyaos', 'Chemistry', 'JAMB', null, 1994, null, 'For a gas, the relative molecular mass is equal to 2Y. What is Y?', null, '["The mass of the gas","The vapour density of the gas","The volume of the gas","The temperature of the gas"]', 1, 'Relative molecular mass = 2 × vapour density, so Y = vapour density.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'For a gas, the relative molecular mass is equal to 2Y. What is Y?', '["The mass of the gas","The vapour density of the gas","The volume of the gas","The temperature of the gas"]', '<u>Y = vapour density</u>.', '{"bold":[],"italic":[],"underline":["The vapour density of the gas"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgdu4b1otf27hl1jjvd3fht15', 'Biology', 'JAMB', null, 1987, null, 'The function of the clitellum in the earthworm is to', null, '["aid digestion","prevent desiccation","assist locomotion","secrete cocoon"]', 3, 'The clitellum secretes the cocoon.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The function of the <b>clitellum</b> in the earthworm is to', '["aid digestion","prevent desiccation","assist locomotion","<u>secrete cocoon</u>"]', 'The clitellum <u>secretes the cocoon</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cge0mq6a291ery4rtczg7p3ud', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve 3x ≡ 7 (mod 10).', null, '["1","5","7","9"]', 3, '3×9 = 27 ≡ 7 mod 10.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve 3x ≡ 7 (mod 10).', '["1","5","7","9"]', '3×9 = 27 ≡ <u>7</u> mod 10 → x = 9.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cge2ixwxbmc4vti7thzsw29g0', 'Chemistry', 'JAMB', null, 1998, null, 'One mole of a hydrocarbon contains 6g of hydrogen. If the molecular weight is 54, the hydrocarbon is an', null, '["alkanone","alkane","alkene","alkyne"]', 3, 'C = 48g (4 mol), H = 6g (6 mol) → C4H6 = alkyne.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One mole of a hydrocarbon contains 6g of hydrogen. If the molecular weight is 54, the hydrocarbon is an', '["alkanone","alkane","alkene","alkyne"]', '<u>C4H6 (alkyne)</u>.', '{"bold":[],"italic":[],"underline":["alkyne"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cge65kcl1qswbu56fm156z8v3', 'General Mathematics', 'WAEC', null, 2020, null, 'Two numbers are selected at random (without replacement) from the first six positive integers. Find the probability that the sum is 8 given that one of the numbers is odd.', null, '["1/5","1/12","3/5","4/5"]', 1, 'Pairs with at least one odd = 15 - 3 = 12; only {3,5} sums to 8, so P = 1/12.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Two numbers are selected at random (without replacement) from the first six positive integers. Find the probability that the sum is 8 given that one of the numbers is odd.', '["1/5","1/12","3/5","4/5"]', 'Pairs with at least one odd = 15 - 3 = 12; only {3,5} sums to 8, so P = 1/12.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cge6m0ep4oueh7pf2s44uw5hj', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The verse Wa la sawfa yu''tika rabbuka fatarda is immediately preceded by', null, '["a lam yajidka yatiman fa ''awa","wa rafa na laka dhikruka","Walal-akhiratu khayrun laka minal ula","thumma latus alunna yawma idhin ''anin-na im."]', 2, 'Preceded by "Walal-akhiratu khayrun laka minal ula."', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The verse Wa la sawfa yu''tika rabbuka fatarda is immediately preceded by', '["a lam yajidka yatiman fa ''awa","wa rafa na laka dhikruka","<u>Walal-akhiratu khayrun laka minal ula</u>","thumma latus alunna yawma idhin ''anin-na im."]', '<u>Walal-akhiratu khayrun laka minal ula</u> (Q. 93:4).', '{"bold":[],"italic":[],"underline":["Walal-akhiratu khayrun laka minal ula"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgecc88xjnvqlyrr9zxl7aydh', 'Chemistry', 'JAMB', null, 1987, null, 'The greater the difference in electronegativity between bonded atoms, the', null, '["lower the polarity of the bond","higher the polarity of the bond","weaker the bond","higher the possibility of the substance formed being a molecule"]', 1, 'Greater electronegativity difference → higher bond polarity.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The greater the difference in electronegativity between bonded atoms, the', '["lower the polarity of the bond","higher the polarity of the bond","weaker the bond","higher the possibility of the substance formed being a molecule"]', 'Greater electronegativity difference → <u>higher bond polarity</u>.', '{"bold":[],"italic":[],"underline":["higher the polarity of the bond"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgeiy8almewtw2b0o3l4uh1wd', 'Government', 'JAMB', null, 2020, null, 'The highest organ of the state during the Babangida Regime was the', null, '["Provisional Ruling Council","Armed Forces Ruling Council","Supreme Military Council","Federal Executive Council"]', 1, 'The AFRC was the highest organ during Babangida''s regime.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The highest organ of the state during the Babangida Regime was the', '["Provisional Ruling Council","<u>Armed Forces Ruling Council</u>","Supreme Military Council","Federal Executive Council"]', '<u>Armed Forces Ruling Council</u>.', '{"bold":[],"italic":[],"underline":["Armed Forces Ruling Council"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgejgzwf4uybnv9b8t1bxexm1', 'Chemistry', 'JAMB', null, 1989, null, '20.00cm³ of a solution containing 0.53g of anhydrous Na2CO3 in 100cm³ requires 25.00cm³ of H2SO4 for complete neutralization. The concentration of the acid solution in moles per dm³ is [H=1, C=12, O=16, Na=23, S=32]', null, '["0.02","0.04","0.06","0.08"]', 0, 'Moles Na2CO3 in 20cm³ = 0.001; H2SO4 = 0.001; conc = 0.001/0.025 = 0.04M. Key says 0.02.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '20.00cm³ of a solution containing 0.53g of anhydrous Na2CO3 in 100cm³ requires 25.00cm³ of H2SO4 for complete neutralization. The concentration of the acid solution in moles per dm³ is [H=1, C=12, O=16, Na=23, S=32]', '["0.02","0.04","0.06","0.08"]', 'Moles H2SO4 = 0.001; conc = <u>0.04M</u> (key says 0.02).', '{"bold":[],"italic":[],"underline":["0.02"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgf6uk717heies3mz3putasvj', 'Chemistry', 'JAMB', null, 1989, null, 'The scale of a chemical balance is made of iron plate and coated with copper electrolytically because', null, '["iron is less susceptible to corrosion than copper","copper is less susceptible to corrosion than iron","copper is less susceptible to corrosion than iron","copper and iron are equally susceptible to corrosion"]', 1, 'Copper is less susceptible to corrosion than iron.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The scale of a chemical balance is made of iron plate and coated with copper electrolytically because', '["iron is less susceptible to corrosion than copper","copper is less susceptible to corrosion than iron","copper is less susceptible to corrosion than iron","copper and iron are equally susceptible to corrosion"]', '<u>Copper is less susceptible to corrosion</u> than iron.', '{"bold":[],"italic":[],"underline":["copper is less susceptible to corrosion than iron"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgf8wh6aj7bhl0yo68fcn3jr1', 'English Language', 'JAMB', null, 2020, null, 'When you _____ an opponent''s point in a debate, you must do so politely.', null, '["refute","rebuke","reject","refuse"]', 0, 'Refute = disprove an argument.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When you _____ an opponent''s point in a debate, you must do so politely.', '["refute","rebuke","reject","refuse"]', '<u>Refute</u> = disprove.', '{"bold":[],"italic":[],"underline":["refute"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgf94r2dcnuq5rgcm5p8p4rnu', 'Physics', 'JAMB', null, 2019, null, 'Which of the following laws states that "good absorbers of heat are good emitters"?', null, '["Stefan''s law","Kirchoff''s law","Planck''s law","Wien''s law"]', 1, 'Kirchhoff''s law states that good absorbers are good emitters.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following laws states that "good absorbers of heat are good emitters"?', '["Stefan''s law","<u>Kirchoff''s law</u>","Planck''s law","Wien''s law"]', '<u>Kirchhoff''s law</u> states that good absorbers are good emitters.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgfibqv6pjwqnk0155trfzexv', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the harmonic mean of 4 and 16.', null, '["6.4","8","9.6","12.8"]', 0, 'HM = 2(4)(16)/20 = 6.4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the harmonic mean of 4 and 16.', '["6.4","8","9.6","12.8"]', 'HM = <u>6.4</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgfjx6s3jkvorw7tivu5iupjk', 'Christian Religious Studies', 'JAMB', null, 2020, null, '''So may the gods do for me, and more also, if I do not make your life as the life of one of them by this time tomorrow.'' What did Elijah do after receiving this message?', null, '["He was afraid, arose and ran for his life","He went a day''s journey into the wilderness","He girded up his loins and ran before Ahab to the entrance of Jezreel","He went and hid himself in a cave."]', 0, 'Elijah was afraid and ran for his life.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '''So may the gods do for me, and more also, if I do not make your life as the life of one of them by this time tomorrow.'' What did Elijah do after receiving this message?', '["<u>He was afraid, arose and ran for his life</u>","He went a day''s journey into the wilderness","He girded up his loins and ran before Ahab to the entrance of Jezreel","He went and hid himself in a cave."]', '<u>He was afraid, arose and ran for his life</u> (1 Kings 19:2).', '{"bold":[],"italic":[],"underline":["He was afraid, arose and ran for his life"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgfk5we7mr90m9atogk2w479t', 'Physics', 'JAMB', null, 2021, null, 'When heat falls on a body', null, '["It is absorbed in the body","it is reflected through the body","It is transmitted through the body","all of the above"]', 3, 'Heat can be absorbed, reflected, or transmitted when it falls on a body.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When heat falls on a body', '["It is absorbed in the body","it is reflected through the body","It is transmitted through the body","<u>all of the above</u>"]', 'Heat can be <u>absorbed, reflected, or transmitted</u> when it falls on a body.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgfo6pkoqmhokhykbp5j87q8w', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Which of the following are secondary sources of the Shari''ah?', null, '["Qur''an and Hadith","Ijma'' and Qiyas","Qur''an and Qiyas","Qiyas and Hadith."]', 1, 'Ijma and Qiyas are secondary sources.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following are secondary sources of the Shari''ah?', '["Qur''an and Hadith","<u>Ijma'' and Qiyas</u>","Qur''an and Qiyas","Qiyas and Hadith."]', '<u>Ijma'' and Qiyas</u>.', '{"bold":[],"italic":[],"underline":["Ijma'' and Qiyas"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgfrmu3ghlwduvckevzczd8cn', 'Chemistry', 'JAMB', null, 1995, null, 'Which of the following metals will <b>liberate hydrogen</b> from steam or dilute acid?', null, '["copper","iron","lead","mercury"]', 1, 'Iron is above hydrogen in the reactivity series.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following metals will <b>liberate hydrogen</b> from steam or dilute acid?', '["copper","iron","lead","mercury"]', '<u>Iron</u> liberates hydrogen.', '{"bold":["liberate hydrogen"],"italic":[],"underline":["iron"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgfrshf730xe38beyccg7d5a3', 'Government', 'JAMB', null, 2020, null, 'In a democracy, sovereign authority is exercised by the', null, '["legislature","people","executive","electorate"]', 1, 'Sovereign authority in a democracy is exercised by the people.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In a democracy, sovereign authority is exercised by the', '["legislature","<u>people</u>","executive","electorate"]', '<u>People</u>.', '{"bold":[],"italic":[],"underline":["people"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgfs8rw9zi83k3qf6y6h8mm8y', 'Government', 'JAMB', null, 2020, null, 'The major function of the civil service is', null, '["providing relevant information on government","keeping records of the activities of government","promoting the interest of civil servants","advising government and implementing its policies"]', 3, 'The civil service advises government and implements policies.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The major function of the civil service is', '["providing relevant information on government","keeping records of the activities of government","promoting the interest of civil servants","<u>advising government and implementing its policies</u>"]', '<u>Advising government and implementing its policies</u>.', '{"bold":[],"italic":[],"underline":["advising government and implementing its policies"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgg0j68ghtjd0oftjirhdi78n', 'Government', 'JAMB', null, 2020, null, 'An unwritten constitution is', null, '["entirely based on case laws","completely sourced from parliamentary law","partially written, and based on convention","completely unwritten and based on convention."]', 2, 'An unwritten constitution is partly written and based on conventions.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An unwritten constitution is', '["entirely based on case laws","completely sourced from parliamentary law","<u>partially written, and based on convention</u>","completely unwritten and based on convention."]', '<u>Partially written and based on convention</u>.', '{"bold":[],"italic":[],"underline":["partially written, and based on convention"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cggdzm4euw8zz6gcbvx1kwcga', 'Chemistry', 'JAMB', null, 1985, null, 'When steam is passed through red hot carbon, which of the following are produced?', null, '["Hydrogen and oxygen and carbon(IV) oxide","Hydrogen and carbon(IV) oxide","Hydrogen and carbon(II) oxide","Hydrogen and trioxocarbonate(IV) acid"]', 2, 'C + H2O → CO + H2 (water gas).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When steam is passed through red hot carbon, which of the following are produced?', '["Hydrogen and oxygen and carbon(IV) oxide","Hydrogen and carbon(IV) oxide","Hydrogen and carbon(II) oxide","Hydrogen and trioxocarbonate(IV) acid"]', '<u>C + H2O → CO + H2</u> (water gas).', '{"bold":[],"italic":[],"underline":["Hydrogen and carbon(II) oxide"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgglfmc7qhdzt75zhr58l0i8y', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The conversion of ''Umar b. al-Khattab was a turning point in the history of Islam because', null, '["it encouraged the actualization of the Prophet''s mission","the entire Quraysh were immediately converted to Islam","he publicly announced his migration to al-Madinah and was not challenged","the boycott of Banu Hashim was terminated"]', 0, 'It encouraged the actualization of the Prophet''s mission.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The conversion of ''Umar b. al-Khattab was a turning point in the history of Islam because', '["<u>it encouraged the actualization of the Prophet''s mission</u>","the entire Quraysh were immediately converted to Islam","he publicly announced his migration to al-Madinah and was not challenged","the boycott of Banu Hashim was terminated"]', '<u>It encouraged the actualization of the Prophet''s mission</u>.', '{"bold":[],"italic":[],"underline":["it encouraged the actualization of the Prophet''s mission"],"fillBlanks":[]}');
