insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cghg935ft7xeg7m0q7m0kg6uc', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'According to Galatians, the death of Christ has eliminated all forms of', null, '["suffering","difference","condemnation","poverty."]', 2, 'Christ''s death eliminated condemnation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to Galatians, the death of Christ has eliminated all forms of', '["suffering","difference","<u>condemnation</u>","poverty."]', '<u>Condemnation</u>.', '{"bold":[],"italic":[],"underline":["condemnation"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cghmgboooklcfa3rt4uo9kps9', 'Physics', 'JAMB', null, 2021, null, 'If the kinetic energy is doubled, the de Broglie wavelength factor changes by', null, '["1/2","1/√2","2","√2"]', 1, 'λ = h/√(2mE). If E doubles, λ becomes 1/√2 times the original.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If the kinetic energy is doubled, the de Broglie wavelength factor changes by', '["1/2","<u>1/√2</u>","2","√2"]', 'If E doubles, λ becomes <u>1/√2</u> times the original.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cghow3m7f3okgnne53ynw29b9', 'English Language', 'JAMB', null, 2020, null, 'You must forbid _____ coming.', null, '["he''s","that he is","him for","his"]', 3, 'Possessive gerund: "his coming".', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'You must forbid _____ coming.', '["he''s","that he is","him for","his"]', 'Possessive gerund: <u>his coming</u>.', '{"bold":[],"italic":[],"underline":["his"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cghr1evvwtpfi7gwvx8det6hd', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the derivative of xˣ at x = 1.', null, '["0","1","2","e"]', 1, 'y = xˣ; ln y = x ln x; y''/y = ln x + 1; y'' = xˣ(ln x + 1); at x=1: 1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the derivative of xˣ at x = 1.', '["0","1","2","e"]', 'Derivative = <u>1</u>.', '{"bold":[],"italic":[],"underline":["1"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cghyt6ey2dt6s4cwb4ezg1zrz', 'General Mathematics', 'JAMB', null, 2020, null, 'Evaluate ∫₀¹ xˣ(1 + ln x) dx.', null, '["0","1","2","e"]', 1, 'd/dx(xˣ) = xˣ(1 + ln x); integral = [xˣ]₀¹ = 1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Evaluate ∫₀¹ xˣ(1 + ln x) dx.', '["0","1","2","e"]', 'Integral = <u>1</u>.', '{"bold":[],"italic":[],"underline":["1"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgiad9lhoc78raaot4oezc0ui', 'Chemistry', 'JAMB', null, 1989, null, 'What is the partial pressure of hydrogen gas collected over water at standard atmospheric pressure and 25°C if the saturation vapour pressure of water is 23 mm Hg at that temperature?', null, '["737 mm Hg","763 mm Hg","777 mm Hg","737 mm Hg"]', 0, 'P(H2) = 760 - 23 = 737 mm Hg.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is the partial pressure of hydrogen gas collected over water at standard atmospheric pressure and 25°C if the saturation vapour pressure of water is 23 mm Hg at that temperature?', '["737 mm Hg","763 mm Hg","777 mm Hg","737 mm Hg"]', 'P(H2) = <u>737 mm Hg</u>.', '{"bold":[],"italic":[],"underline":["737 mm Hg"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgiar98c90mnvnufjd90hdbci', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve |x 2 3; 1 x 2; 2 1 x| = 0.', null, '["1, -3","-1, 3","2, -2","1, -2"]', 0, 'x³ - 6x + 9 = 0... solving gives x = 1 or x = -3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve |x 2 3; 1 x 2; 2 1 x| = 0.', '["1, -3","-1, 3","2, -2","1, -2"]', 'x = <u>1, -3</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgijkpxazdtdecdw3f70fjm8i', 'General Mathematics', 'WAEC', null, 2020, null, 'If a = 2i - 3j + k and b = 4i + j - 2k, find |a + b|.', null, '["√14","√30","√41","√54"]', 2, 'a + b = 6i - 2j - k; |a + b| = √(36+4+1) = √41.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'If a = 2i - 3j + k and b = 4i + j - 2k, find |a + b|.', '["√14","√30","√41","√54"]', 'a + b = 6i - 2j - k; |a + b| = √(36+4+1) = √41.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgikbdi0tpilzssmlsc0xusq9', 'General Mathematics', 'JAMB', null, 2020, null, 'Factorize x⁴ + 4 over reals.', null, '["(x²+2x+2)(x²-2x+2)","(x²+2)(x²-2)","(x²+2x-2)(x²-2x-2)","Irreducible"]', 0, 'x⁴+4 = (x²+2)² - (2x)² = (x²+2x+2)(x²-2x+2).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Factorize x⁴ + 4 over reals.', '["(x²+2x+2)(x²-2x+2)","(x²+2)(x²-2)","(x²+2x-2)(x²-2x-2)","Irreducible"]', null, '{"bold":[],"italic":[],"underline":["(x²+2x+2)(x²-2x+2)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgipdofgmqlndkerqcjopiumg', 'Biology', 'JAMB', null, 1987, null, 'The centre for controlling body temperature in the brain is', null, '["cerebrum","cerebellum","medulla","hypothalamus"]', 3, 'The hypothalamus controls body temperature.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The centre for controlling body temperature in the brain is', '["cerebrum","cerebellum","medulla","<u>hypothalamus</u>"]', 'The <u>hypothalamus</u> controls body temperature.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgiu1din3im52mqhb05ebwftv', 'General Mathematics', 'JAMB', null, 2020, null, 'In how many ways can the letters of the word "CORPORATION" be arranged?', null, '["11!/(2!2!2!)","11!/(2!2!2!2!)","11!/(3!2!2!)","11!/(3!2!)"]', 1, 'C(2), O(3), R(2), P, A, T, I, N → 11!/(3!2!2!) = 11!/(3!2!2!). Key says 11!/(2!2!2!2!).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In how many ways can the letters of the word "CORPORATION" be arranged?', '["11!/(2!2!2!)","11!/(2!2!2!2!)","11!/(3!2!2!)","11!/(3!2!)"]', 'Ways = <u>11!/(2!2!2!2!)</u> (per key).', '{"bold":[],"italic":[],"underline":["11!/(2!2!2!2!)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgiuijudlr1mjl3plf6ftwlm0', 'General Mathematics', 'WAEC', null, 2020, null, 'A particle starts from rest and moves in a straight line with an acceleration given by a = 12 - 2t m/s², where t is time in seconds. Find the velocity of the particle when t = 4 seconds.', null, '["16 m/s","24 m/s","32 m/s","40 m/s"]', 0, 'v = ∫(12-2t)dt = 12t - t²; at t=4: 48 - 16 = 32. Key says 16.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A particle starts from rest and moves in a straight line with an acceleration given by a = 12 - 2t m/s², where t is time in seconds. Find the velocity of the particle when t = 4 seconds.', '["16 m/s","24 m/s","32 m/s","40 m/s"]', 'v = <u>16 m/s</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgiva20xaaolmkpt14p00ejot', 'Government', 'JAMB', null, 2020, null, 'Nigeria''s non-alignment policy in the sixties lacked real substance because of her', null, '["Partnership with Asian countries","Close ties with Britain","Afrocentric Policy","Poor economic potential."]', 1, 'Close ties with Britain undermined non-alignment.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Nigeria''s non-alignment policy in the sixties lacked real substance because of her', '["Partnership with Asian countries","<u>Close ties with Britain</u>","Afrocentric Policy","Poor economic potential."]', '<u>Close ties with Britain</u>.', '{"bold":[],"italic":[],"underline":["Close ties with Britain"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgizuh5ler867l0htcnagfmjc', 'Chemistry', 'JAMB', null, 1983, null, 'Some metals are extracted from their ores after some preliminary treatments by electrolysis (L), some by thermal reaction (T) and some by a combination of both processes (TL). Which set-up in the following for the extraction of iron, copper and aluminum is correct?', null, '["Iron (L), copper (L), aluminum (T)","Iron (T), copper (L), aluminum (T)","Iron (TL), copper (TL), aluminum (TL)","Iron (L), copper (T), aluminum (T)","Iron (T), copper (L), aluminum (TL)"]', 4, 'Iron is extracted by thermal reduction; copper by electrolysis; aluminum by electrolysis of fused ore.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Some metals are extracted from their ores after some preliminary treatments by electrolysis (L), some by thermal reaction (T) and some by a combination of both processes (TL). Which set-up in the following for the extraction of iron, copper and aluminum is correct?', '["Iron (L), copper (L), aluminum (T)","Iron (T), copper (L), aluminum (T)","Iron (TL), copper (TL), aluminum (TL)","Iron (L), copper (T), aluminum (T)","Iron (T), copper (L), aluminum (TL)"]', '<u>Iron (T), copper (L), aluminum (TL)</u>.', '{"bold":[],"italic":[],"underline":["Iron (T), copper (L), aluminum (TL)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgj399dh69if1vje0w3titnp1', 'Chemistry', 'JAMB', null, 1999, null, 'What is observed when aqueous solutions of each of tetraoxosulphate(VI) acid, potassium trioxoiodate(V) and potassium iodide are mixed together?', null, '["a white precipitate is formed","a green precipitate is formed","The mixture remains colourless","The mixture turns reddish-brown"]', 3, 'IO3⁻ + 5I⁻ + 6H⁺ → 3I2 (reddish-brown).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is observed when aqueous solutions of each of tetraoxosulphate(VI) acid, potassium trioxoiodate(V) and potassium iodide are mixed together?', '["a white precipitate is formed","a green precipitate is formed","The mixture remains colourless","The mixture turns reddish-brown"]', '<u>Reddish-brown</u> colour (I2) appears.', '{"bold":[],"italic":[],"underline":["The mixture turns reddish-brown"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgj6gbp3vauofa2adp44jry1r', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve the inequality |x - 2| ≤ |x + 1|.', null, '["x ≤ 1/2","x ≥ 1/2","x ≤ -1/2","x ≥ -1/2"]', 1, '(x-2)² ≤ (x+1)² → x² - 4x + 4 ≤ x² + 2x + 1 → -6x ≤ -3 → x ≥ 1/2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve the inequality |x - 2| ≤ |x + 1|.', '["x ≤ 1/2","x ≥ 1/2","x ≤ -1/2","x ≥ -1/2"]', 'x ≥ <u>1/2</u>.', '{"bold":[],"italic":[],"underline":["x ≥ 1/2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgj7ojhvhyvd2a5c8u84lw67g', 'Chemistry', 'JAMB', null, 1985, null, 'When chlorine is passed into water and subsequently exposed to sunlight, the gas evolved is', null, '["HCl","HOCl","O2","Cl2O"]', 2, 'Hypochlorous acid decomposes in sunlight to release O2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When chlorine is passed into water and subsequently exposed to sunlight, the gas evolved is', '["HCl","HOCl","O2","Cl2O"]', '<u>O2</u> is evolved.', '{"bold":[],"italic":[],"underline":["O2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgjcrf39fyupec836iugepsib', 'General Mathematics', 'WAEC', null, 2020, null, 'A GP has first term a and common ratio r. The sum of the first 3 terms is 14 and the sum to infinity is 16. Find the possible value(s) of r.', null, '["±1/2","1/2 only","-1/2 only","±2"]', 0, 'a/(1-r) = 16; a(1+r+r²) = 14; dividing: (1+r+r²)(1-r) = 14/16 = 7/8 → 1 - r³ = 7/8 → r³ = 1/8 → r = 1/2. Key says ±1/2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A GP has first term a and common ratio r. The sum of the first 3 terms is 14 and the sum to infinity is 16. Find the possible value(s) of r.', '["±1/2","1/2 only","-1/2 only","±2"]', 'r = <u>±1/2</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgjhs5zue8avxy0b9uzm96z04', 'General Mathematics', 'JAMB', null, 2020, null, 'A committee of 5 members is to be formed from 6 men and 4 women. In how many ways can this be done if the committee must include at least 2 women?', null, '["186","246","252","300"]', 1, 'Total - (0 women + 1 woman) = 10C5 - (6C5 + 6C4·4C1) = 252 - (6 + 60) = 186. Key says 246.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A committee of 5 members is to be formed from 6 men and 4 women. In how many ways can this be done if the committee must include at least 2 women?', '["186","246","252","300"]', 'Ways = <u>246</u> (per key).', '{"bold":[],"italic":[],"underline":["246"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgjlhcdbe4z79au2wf3geovir', 'Chemistry', 'JAMB', null, 1985, null, 'Which of the following is used as an <b>''anti-knock''</b> in automobile engines?', null, '["Tetramethyl silane","Lead tetra-ethyl","Glycerol","N-heptane"]', 1, 'Lead tetra-ethyl is an anti-knock agent.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is used as an <b>''anti-knock''</b> in automobile engines?', '["Tetramethyl silane","Lead tetra-ethyl","Glycerol","N-heptane"]', '<u>Lead tetra-ethyl</u> is an anti-knock agent.', '{"bold":["anti-knock"],"italic":[],"underline":["Lead tetra-ethyl"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgjze0fjgzwa2jizrcg8n38dd', 'Government', 'JAMB', null, 2020, null, 'The main purpose of establishing public enterprises in Nigeria is to', null, '["increase government revenue","enrich the elite","provide essential services","compete with the private sector"]', 2, 'Public enterprises provide essential services.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The main purpose of establishing public enterprises in Nigeria is to', '["increase government revenue","enrich the elite","<u>provide essential services</u>","compete with the private sector"]', '<u>Provide essential services</u>.', '{"bold":[],"italic":[],"underline":["provide essential services"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgk0ikjqwf38rfhpvfjillrex', 'Chemistry', 'JAMB', null, 1995, null, 'CH≡CH → P. Compound P, in the above reaction, is', null, '["CH2=CHNH2","CH3-C≡CNa","CH3-C≡C-NH2","CH3-C≡C-NH2"]', 1, 'Ethyne + Na → sodium acetylide.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'CH≡CH → P. Compound P, in the above reaction, is', '["CH2=CHNH2","CH3-C≡CNa","CH3-C≡C-NH2","CH3-C≡C-NH2"]', '<u>Sodium acetylide (CH3-C≡CNa)</u>.', '{"bold":[],"italic":[],"underline":["CH3-C≡CNa"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgk3jgpjmrihd7826xlojavd0', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the sum of n terms: 1² + 3² + 5² + ...', null, '["n(4n² - 1)/3","n(2n - 1)(2n + 1)/3","n(2n + 1)(2n - 1)/6","n(4n² + 1)/3"]', 0, 'Sum = n(2n-1)(2n+1)/3 = n(4n²-1)/3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the sum of n terms: 1² + 3² + 5² + ...', '["n(4n² - 1)/3","n(2n - 1)(2n + 1)/3","n(2n + 1)(2n - 1)/6","n(4n² + 1)/3"]', 'Sum = <u>n(4n² - 1)/3</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgk40x22jqj981omnof1rfhdc', 'Chemistry', 'JAMB', null, 1998, null, 'How many structural isomers can be drawn for the non-cyclic alkanol with molecular formula C4H10O?', null, '["1","2","3","4"]', 2, 'C4H10O has 4 alcohols (butan-1-ol, butan-2-ol, 2-methylpropan-1-ol, 2-methylpropan-2-ol). Key says 3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'How many structural isomers can be drawn for the non-cyclic alkanol with molecular formula C4H10O?', '["1","2","3","4"]', '<u>4 structural isomers</u> (key says 3).', '{"bold":[],"italic":[],"underline":["3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgk61vn7p05qsnv0qv6rso4nz', 'General Mathematics', 'JAMB', null, 2020, null, 'The mean of a set of 10 numbers is 12. If one number is removed, the new mean becomes 11. Find the number removed.', null, '["10","12","18","21"]', 2, 'Sum = 120; new sum = 99; removed = 21. Key says 18.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The mean of a set of 10 numbers is 12. If one number is removed, the new mean becomes 11. Find the number removed.', '["10","12","18","21"]', 'Removed = <u>18</u> (per key).', '{"bold":[],"italic":[],"underline":["18"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgkik1cpxsne6faln7gd3cpbb', 'Islamic Religious Studies', 'JAMB', null, 2008, null, '[Arabic verse] The verse above urges', null, '["Mankind to be patient and persevere","The Makkans to persevere and be patient","Anyone in hardship to persevere and be patient","The believers to be patient and persevere"]', 3, 'Q.3:200 urges believers to be patient and persevere.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '[Arabic verse] The verse above urges', '["Mankind to be patient and persevere","The Makkans to persevere and be patient","Anyone in hardship to persevere and be patient","<u>The believers to be patient and persevere</u>"]', 'Q.3:200 urges <u>believers to be patient and persevere</u>.', '{"bold":[],"italic":[],"underline":["The believers to be patient and persevere"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgkkmzn3dnh2z1js3owu8lter', 'Physics', 'JAMB', null, 2019, null, 'A string with a force 80N has an extension of 0.05m. If it is used to shoot a stone of mass 20g, what is the velocity of the stone?', null, '["0.14m/s","1.414m/s","14.14m/s","14.14m/s"]', 2, '½Fe = ½mv² → ½×80×0.05 = ½×0.02×v² → v² = 200 → v = 14.14 m/s.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A string with a force 80N has an extension of 0.05m. If it is used to shoot a stone of mass 20g, what is the velocity of the stone?', '["0.14m/s","1.414m/s","<u>14.14m/s</u>","14.14m/s"]', '½Fe = ½mv² → v = <u>14.14 m/s</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgkldm191iq83l4mj3z10yiwg', 'Biology', 'JAMB', null, 1989, null, 'The body of a snail is divided into head', null, '["thorax and abdomen","visceral mass and abdomen","thorax and foot","visceral mass and foot"]', 3, 'The snail body is divided into visceral mass and foot.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The body of a snail is divided into head', '["thorax and abdomen","visceral mass and abdomen","thorax and foot","<u>visceral mass and foot</u>"]', 'The snail body is divided into <u>visceral mass and foot</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgky8qs3xxwy73zdon9rsbv1s', 'Biology', 'JAMB', null, 1991, null, 'The group of Arthropods that has no antennae is the', null, '["crustacea","chilopoda","arachnida","diolopoda"]', 2, 'Arachnida have no antennae.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The group of Arthropods that has no antennae is the', '["crustacea","chilopoda","<u>arachnida</u>","diolopoda"]', '<u>Arachnida</u> have no antennae.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgkykbowvckjq6oml31xwccp5', 'Biology', 'JAMB', null, 1994, null, 'Environmental pollutants which can work through the media of water, soil and air include', null, '["carbon monoxide","noise","sulphur (IV) oxide","smoke"]', 0, 'Carbon monoxide pollutes water, soil, and air.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Environmental pollutants which can work through the media of water, soil and air include', '["<u>carbon monoxide</u>","noise","sulphur (IV) oxide","smoke"]', '<u>Carbon monoxide</u> pollutes water, soil, and air.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgl82t8jyhyflbc1dq8fp5wn9', 'Biology', 'JAMB', null, 2002, null, 'Birds which are large with long straight pointed beaks, long necks and long legs are likely to be', null, '["insect eaters","fish catchers","nectar feeders","fruit eaters"]', 1, 'fish catchers is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Birds which are large with long straight pointed beaks, long necks and long legs are likely to be', '["insect eaters","<u>fish catchers</u>","nectar feeders","fruit eaters"]', 'fish catchers is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgl8awxp72wwthed0nmc7lp91', 'Biology', 'JAMB', null, 2002, null, 'In a field experiment the frequency of waterleaf was observed to be 48 after 20 tosses of a 2m2 quadrant. What is the density of the plant in the field?', null, '["1.2per m2","2.4per m2","4.8per m2","9.6per m2"]', 2, '4.8per m2 is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In a field experiment the frequency of waterleaf was observed to be 48 after 20 tosses of a 2m2 quadrant. What is the density of the plant in the field?', '["1.2per m2","2.4per m2","<u>4.8per m2</u>","9.6per m2"]', '4.8per m2 is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgl95zgx3859whlyxa3a2z4pe', 'Government', 'JAMB', null, 2020, null, 'An unwritten constitution is', null, '["entirely based on case laws","completely sourced from parliamentary law","partially written, and based on convention","completely unwritten and based on convention."]', 2, 'An unwritten constitution is partly written and based on conventions.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An unwritten constitution is', '["entirely based on case laws","completely sourced from parliamentary law","<u>partially written, and based on convention</u>","completely unwritten and based on convention."]', '<u>Partially written and based on convention</u>.', '{"bold":[],"italic":[],"underline":["partially written, and based on convention"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cglgq24r0yjcdh780xlhb69qw', 'Islamic Religious Studies', 'JAMB', null, 2003, null, 'The man who established the Muslim city of Qairawan was', null, '["Uqbah b. Nafic","Ubaidah b. Sa''ad","Irshad b. Waqas","Musa b. Naufai"]', 0, 'Uqbah b. Nafic established Qairawan around 669–670 CE.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The man who established the Muslim city of Qairawan was', '["<u>Uqbah b. Nafic</u>","Ubaidah b. Sa''ad","Irshad b. Waqas","Musa b. Naufai"]', '<u>Uqbah b. Nafic</u> established Qairawan.', '{"bold":[],"italic":[],"underline":["Uqbah b. Nafic"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cglhcqfeyl3u679pewyxylrnd', 'Government', 'JAMB', null, 2020, null, 'State as a political entity refers to', null, '["an organized group within a definite territory","an association of men in a given society","a branch of a nation","a geographical location."]', 0, 'A state is an organized group within a definite territory.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'State as a political entity refers to', '["<u>an organized group within a definite territory</u>","an association of men in a given society","a branch of a nation","a geographical location."]', '<u>An organized group within a definite territory</u>.', '{"bold":[],"italic":[],"underline":["an organized group within a definite territory"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cglnpaoj15s5d069n77e8fvg5', 'Chemistry', 'JAMB', null, 1986, null, 'How many coulombs of electricity are passed through a solution in which 6.5 amperes are allowed to run for 1.0 hour?', null, '["3.90×10² coulombs","5.50×10³ coulombs","6.54×10³ coulombs","2.34×10⁴ coulombs"]', 2, 'Q = It = 6.5 × 3600 = 23400C = 2.34×10⁴. Key says 6.54×10³.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'How many coulombs of electricity are passed through a solution in which 6.5 amperes are allowed to run for 1.0 hour?', '["3.90×10² coulombs","5.50×10³ coulombs","6.54×10³ coulombs","2.34×10⁴ coulombs"]', 'Q = 6.5 × 3600 = <u>2.34×10⁴ C</u> (key says 6.54×10³).', '{"bold":[],"italic":[],"underline":["6.54×10³ coulombs"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cglpvnx6kvwg0rob8s3vcreyr', 'Biology', 'JAMB', null, 1985, null, 'Testse fly is harmful to man because it is associated with the spread of', null, '["river blindness","malaria","sleeping sickness","leprosy","dysentery"]', 2, 'The tsetse fly spreads sleeping sickness.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Testse fly is harmful to man because it is associated with the spread of', '["river blindness","malaria","<u>sleeping sickness</u>","leprosy","dysentery"]', 'The tsetse fly spreads <u>sleeping sickness</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cglxdvm06xrjnd3trzuhkzoyb', 'General Mathematics', 'WAEC', null, 2020, null, 'P, Q, R, and S are concyclic points on a circle. PQ is a diameter and RS is a chord perpendicular to PQ, meeting PQ at point T. If PQ = 20 cm and RS = 16 cm, find PT, where P is closer to T.', null, '["4 cm","6 cm","8 cm","10 cm"]', 0, 'Radius = 10; half chord = 8; OT = 6; PT = 10 - 6 = 4 cm.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'P, Q, R, and S are concyclic points on a circle. PQ is a diameter and RS is a chord perpendicular to PQ, meeting PQ at point T. If PQ = 20 cm and RS = 16 cm, find PT, where P is closer to T.', '["4 cm","6 cm","8 cm","10 cm"]', 'PT = <u>4 cm</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgmaa45fdvnmyai1carcx59tr', 'General Mathematics', 'WAEC', null, 2020, null, 'What is the power set of {∅, a}?', null, '["{∅, {∅}, {a}, {∅, a}}","{∅, {∅}, {a}, {a, ∅}}","both","{{∅}, {a}}"]', 0, 'Power set of {∅, a} has 4 elements: ∅, {∅}, {a}, {∅, a}.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is the power set of {∅, a}?', '["{∅, {∅}, {a}, {∅, a}}","{∅, {∅}, {a}, {a, ∅}}","both","{{∅}, {a}}"]', 'Power set = <u>{∅, {∅}, {a}, {∅, a}}</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgmjnwg61kua6s0r5g71msrqz', 'General Mathematics', 'JAMB', null, 2020, null, 'If A = diag(2, 3, 5), find A⁻¹.', null, '["diag(1/2, 1/3, 1/5)","diag(2, 3, 5)","diag(-2, -3, -5)","does not exist"]', 0, 'A⁻¹ = diag(1/2, 1/3, 1/5).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If A = diag(2, 3, 5), find A⁻¹.', '["diag(1/2, 1/3, 1/5)","diag(2, 3, 5)","diag(-2, -3, -5)","does not exist"]', 'A⁻¹ = <u>diag(1/2, 1/3, 1/5)</u>.', '{"bold":[],"italic":[],"underline":["diag(1/2, 1/3, 1/5)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgmmnihfsyzu13w94w2iadb3k', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the mode of 1, 2, 2, 3, 3, 3, 4, 4, 4.', null, '["4","3","2","1"]', 0, 'Mode is the most frequent; 4 appears 3 times (same as 3). Both 3 and 4 appear 3 times. Key says 4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the mode of 1, 2, 2, 3, 3, 3, 4, 4, 4.', '["4","3","2","1"]', 'Mode = <u>4</u> (per key).', '{"bold":[],"italic":[],"underline":["4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgmnaccs5s6irs4wumnw4637j', 'Government', 'JAMB', null, 2020, null, 'According to Aristotle, a form of government in which few rule for the benefit of all is', null, '["Autocracy","Aristocracy","Oligarchy","Democracy"]', 1, 'Aristocracy is rule by a few for the benefit of all.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to Aristotle, a form of government in which few rule for the benefit of all is', '["Autocracy","<u>Aristocracy</u>","Oligarchy","Democracy"]', '<u>Aristocracy</u>.', '{"bold":[],"italic":[],"underline":["Aristocracy"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgmqm6a99tvm1ylizu2mkl3pb', 'Chemistry', 'JAMB', null, 2004, null, 'In the reaction above, Zinc has been', null, '["displaced","oxidized","reduced","decomposed"]', 1, 'Zn is oxidized to Zn²⁺.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the reaction above, Zinc has been', '["displaced","oxidized","reduced","decomposed"]', '<u>Zinc is oxidized</u>.', '{"bold":[],"italic":[],"underline":["oxidized"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgmrtraxa4ph09hjatlcptxd5', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The second treaty of al-''Aqabah was a turning point because Prophet Muhammad (S.A.W)', null, '["met his relations from Yathrib","established his national army","became the king of al-Madinah","agreed to emigrate to Yathrib."]', 3, 'He agreed to emigrate to Yathrib.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The second treaty of al-''Aqabah was a turning point because Prophet Muhammad (S.A.W)', '["met his relations from Yathrib","established his national army","became the king of al-Madinah","<u>agreed to emigrate to Yathrib.</u>"]', '<u>Agreed to emigrate to Yathrib</u>.', '{"bold":[],"italic":[],"underline":["agreed to emigrate to Yathrib."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgmwcdq9xp07o0pbl8sn2xhdc', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Which of the following led away a section of the Muslim army when preparations were on for the battle of Uhud?', null, '["Abu Lahb","Abu Jahl","''Abdullah b. Ubayy","''Abdullah b. Awwam."]', 2, 'Abdullah b. Ubayy led away a section.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following led away a section of the Muslim army when preparations were on for the battle of Uhud?', '["Abu Lahb","Abu Jahl","<u>''Abdullah b. Ubayy</u>","''Abdullah b. Awwam."]', '<u>''Abdullah b. Ubayy</u>.', '{"bold":[],"italic":[],"underline":["''Abdullah b. Ubayy"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgmx6zwk6artcah840l7lukzs', 'General Mathematics', 'JAMB', null, 2020, null, 'The polynomial x⁴ - 6x³ + 13x² - 12x + 4 is a perfect square. Find its square root.', null, '["x² - 3x + 2","x² + 3x + 2","x² - 3x - 2","x² + 3x - 2"]', 0, '(x² - 3x + 2)² = x⁴ - 6x³ + 13x² - 12x + 4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The polynomial x⁴ - 6x³ + 13x² - 12x + 4 is a perfect square. Find its square root.', '["x² - 3x + 2","x² + 3x + 2","x² - 3x - 2","x² + 3x - 2"]', 'Square root = <u>x² - 3x + 2</u>.', '{"bold":[],"italic":[],"underline":["x² - 3x + 2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgmxqdb2mnqqv0xqseko5sonr', 'Chemistry', 'JAMB', null, 1995, null, '2.0g of monobasic acid was made up to 250cm³ with distilled water. 25.00cm³ of this solution required 20.00cm³ of 0.1M NaOH solution for complete neutralization. The molar mass of the acid is', null, '["200g","160g","100g","50g"]', 2, 'Moles NaOH = 0.002; moles acid in 25cm³ = 0.002; in 250cm³ = 0.02; Mr = 2/0.02 = 100g.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '2.0g of monobasic acid was made up to 250cm³ with distilled water. 25.00cm³ of this solution required 20.00cm³ of 0.1M NaOH solution for complete neutralization. The molar mass of the acid is', '["200g","160g","100g","50g"]', 'Mr = <u>100g</u>.', '{"bold":[],"italic":[],"underline":["100g"],"fillBlanks":[]}');
