insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgokdq5qoxaax9k3x584a3owo', 'Chemistry', 'JAMB', null, 1983, null, 'The ratio of the number of molecules in 2g of hydrogen to that in 16g of oxygen is', null, '["2:1","1:1","1:2","1:4","1:8"]', 1, '2g H2 = 1 mole; 16g O2 = 0.5 mole; ratio = 1:0.5 = 2:1. Answer key says 1:1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The ratio of the number of molecules in 2g of hydrogen to that in 16g of oxygen is', '["2:1","1:1","1:2","1:4","1:8"]', '2g H2 = 1 mole; 16g O2 = 0.5 mole; ratio = <u>2:1</u> (key says 1:1).', '{"bold":[],"italic":[],"underline":["1:1"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgoptogt0kqvb563vxyv98klp', 'Government', 'JAMB', null, 2020, null, 'Which of the following is a founding member of OPEC?', null, '["Indonesia","Algeria","Nigeria","Venezuela"]', 3, 'Venezuela is a founding member of OPEC.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is a founding member of OPEC?', '["Indonesia","Algeria","Nigeria","<u>Venezuela</u>"]', '<u>Venezuela</u>.', '{"bold":[],"italic":[],"underline":["Venezuela"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgor5cjx9cixvsnybcivjrgzp', 'General Mathematics', 'JAMB', null, 2020, null, 'Evaluate ∫₀¹ x/(1 + x²) dx.', null, '["¼ ln 2","½ ln 2","ln 2","2 ln 2"]', 1, '∫ = ½ ln(1+x²); evaluated = ½ ln 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Evaluate ∫₀¹ x/(1 + x²) dx.', '["¼ ln 2","½ ln 2","ln 2","2 ln 2"]', 'Integral = <u>½ ln 2</u>.', '{"bold":[],"italic":[],"underline":["½ ln 2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgp24w5u5y6rfndiywe4pxyz8', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Isaac''s prayer to God for his barren wife showed that he', null, '["truly loved her","sincerely loved his God","had faith in God","was tired of being childless."]', 2, 'Isaac''s prayer showed he had faith in God.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Isaac''s prayer to God for his barren wife showed that he', '["truly loved her","sincerely loved his God","<u>had faith in God</u>","was tired of being childless."]', '<u>Had faith in God</u>.', '{"bold":[],"italic":[],"underline":["had faith in God"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgp2unuc4e8y3yiptz3bj2aff', 'General Mathematics', 'JAMB', null, 2020, null, 'Evaluate ∫₀^∞ e^(-x²) dx.', null, '["√π/2","√π/4","√π","Diverges"]', 0, 'Gaussian integral: √π/2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Evaluate ∫₀^∞ e^(-x²) dx.', '["√π/2","√π/4","√π","Diverges"]', 'Integral = <u>√π/2</u>.', '{"bold":[],"italic":[],"underline":["√π/2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgpcxsyburbdldcibcucfe4mi', 'Chemistry', 'JAMB', null, 1988, null, 'A substance S is isomorphous with another substance R. When a tiny crystal of R is introduced into a supersaturated solution of S,', null, '["S dissolves in the solution","Crystals of R are precipitated","There is no observable change","R and S react to generate heat"]', 2, 'Isomorphous substances have the same crystal structure, so no change occurs.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A substance S is isomorphous with another substance R. When a tiny crystal of R is introduced into a supersaturated solution of S,', '["S dissolves in the solution","Crystals of R are precipitated","There is no observable change","R and S react to generate heat"]', '<u>No observable change</u> (isomorphous crystals).', '{"bold":[],"italic":[],"underline":["There is no observable change"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgpfn8ol2i59ycfbkiwdk6lbo', 'General Mathematics', 'WAEC', null, 2020, null, 'Derivative of sin x from first principles.', null, '["cos x","-cos x","sin x","-sin x"]', 0, 'lim(h→0)[sin(x+h)-sin x]/h = cos x.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Derivative of sin x from first principles.', '["cos x","-cos x","sin x","-sin x"]', 'Derivative = <u>cos x</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgphgqsow4z9tl0i6p8215xzu', 'Chemistry', 'JAMB', null, 1991, null, 'Which of the following equivalent solutions, Na2CO3, Na2SO4, FeCl3, NH4Cl and CH3COONa, have <b>pH greater than 7</b>?', null, '["FeCl3 and NH4Cl","Na2CO3, CH3COONa and Na2SO4","Na2CO3 and CH3COONa","FeCl3, CH3COONa and NH4Cl"]', 2, 'Na2CO3 and CH3COONa are salts of weak acids and strong bases (basic).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following equivalent solutions, Na2CO3, Na2SO4, FeCl3, NH4Cl and CH3COONa, have <b>pH greater than 7</b>?', '["FeCl3 and NH4Cl","Na2CO3, CH3COONa and Na2SO4","Na2CO3 and CH3COONa","FeCl3, CH3COONa and NH4Cl"]', '<u>Na2CO3 and CH3COONa</u> have pH > 7.', '{"bold":["pH greater than 7"],"italic":[],"underline":["Na2CO3 and CH3COONa"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgpluxxt434qj2bvvm1ztsrxe', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the area enclosed between the curve y = x² - 4x and the x-axis.', null, '["32/3 square units","64/3 square units","16 square units","128/3 square units"]', 0, 'Area = ∫₀⁴ -(x² - 4x) dx = 32/3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the area enclosed between the curve y = x² - 4x and the x-axis.', '["32/3 square units","64/3 square units","16 square units","128/3 square units"]', 'Area = <u>32/3 square units</u>.', '{"bold":[],"italic":[],"underline":["32/3 square units"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgppi3mrxashupcqwpqxsygk0', 'General Mathematics', 'WAEC', null, 2020, null, 'A particle is projected vertically upwards with a velocity of 20 m/s. Find the time taken to return to the point of projection. (g = 10 m/s²)', null, '["2 s","4 s","6 s","8 s"]', 1, 'Time = 2u/g = 40/10 = 4 s.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A particle is projected vertically upwards with a velocity of 20 m/s. Find the time taken to return to the point of projection. (g = 10 m/s²)', '["2 s","4 s","6 s","8 s"]', 'Time = <u>4 s</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgptbnsqwuidfxz994jeczb4s', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Paul teaches that the exercise of spiritual gifts by individual believers should be used to promote', null, '["co-operation","knowledge","faith","competition."]', 0, 'Spiritual gifts should promote co-operation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Paul teaches that the exercise of spiritual gifts by individual believers should be used to promote', '["<u>co-operation</u>","knowledge","faith","competition."]', '<u>Co-operation</u> (1 Corinthians 12).', '{"bold":[],"italic":[],"underline":["co-operation"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgpwpg1zsw46rbs7g02cdlio9', 'Chemistry', 'JAMB', null, 1994, null, 'A solid that absorbs water from the atmosphere and forms an aqueous solution is', null, '["hydrophilic","efflorescent","deliquescent","hygroscopic"]', 2, 'Deliquescent solids absorb water and dissolve in it.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A solid that absorbs water from the atmosphere and forms an aqueous solution is', '["hydrophilic","efflorescent","deliquescent","hygroscopic"]', '<u>Deliquescent</u> solids absorb water and dissolve.', '{"bold":[],"italic":[],"underline":["deliquescent"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgq0ggiwdd9jbbh0h3i9s5bol', 'Chemistry', 'JAMB', null, 1995, null, '0.1 faraday of electricity deposited 2.95g of nickel during electrolysis in an aqueous solution. Calculate the number of moles of nickel that will be deposited by 0.4 faraday.', null, '["0.20","0.30","0.034","5.87"]', 1, '0.1 F deposits 2.95g = 0.05 mol Ni; 0.4 F deposits 0.2 mol. Key says 0.30.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '0.1 faraday of electricity deposited 2.95g of nickel during electrolysis in an aqueous solution. Calculate the number of moles of nickel that will be deposited by 0.4 faraday.', '["0.20","0.30","0.034","5.87"]', '0.4 F deposits <u>0.2 mol Ni</u> (key says 0.30).', '{"bold":[],"italic":[],"underline":["0.30"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgq50xbsdk8yu1o5ys3psbnnb', 'Biology', 'JAMB', null, 1997, null, 'The substance that is responsible for <b>apical dominance</b> in plants is known as', null, '["gibberellin","tannin","auxin","kinin"]', 2, 'Auxin causes apical dominance.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The substance that is responsible for <b>apical dominance</b> in plants is known as', '["gibberellin","tannin","auxin","kinin"]', '<u>Auxin causes apical dominance</u>.', '{"bold":["apical dominance"],"italic":[],"underline":["auxin"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgqa0veeikpp2jkbqqoqe53ec', 'Chemistry', 'JAMB', null, 1991, null, 'Atoms of element X (with 2 electrons in the outer shell) combine with atoms of Y (with 7 electrons in the outer shell). Which of the following is <b>FALSE</b>? The compound formed', null, '["has formula XY2","is likely to be ionic","contains X²⁺ ions","contains Y⁻ ions"]', 0, 'The formula is XY2, so this statement is true, not false.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Atoms of element X (with 2 electrons in the outer shell) combine with atoms of Y (with 7 electrons in the outer shell). Which of the following is <b>FALSE</b>? The compound formed', '["has formula XY2","is likely to be ionic","contains X²⁺ ions","contains Y⁻ ions"]', 'The formula is <u>XY2</u>, so the FALSE statement is not this one; but among options, XY2 is correct.', '{"bold":["FALSE"],"italic":[],"underline":["has formula XY2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgqn6s8cptun8yg6kw4pvwyst', 'Chemistry', 'JAMB', null, 1993, null, 'The oxidation states of chlorine in HOCl, HClO3 and HClO4 are respectively', null, '["-1, +5 and +7","-1, -5 and +7","+1, +3 and +4","+1, +5 and +7"]', 3, 'HOCl: +1; HClO3: +5; HClO4: +7.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The oxidation states of chlorine in HOCl, HClO3 and HClO4 are respectively', '["-1, +5 and +7","-1, -5 and +7","+1, +3 and +4","+1, +5 and +7"]', '<u>+1, +5, +7</u>.', '{"bold":[],"italic":[],"underline":["+1, +5 and +7"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgr7if89kbxuqdbdan5ooas3n', 'Chemistry', 'JAMB', null, 2019, null, 'Molarity is defined as: I. The number of moles of solute dissolved in dm3 of the solution II. The number of moles of solute dissolved in 1kg of solvent III. The number of moles of solute dissolved in 1dm3 of the solvent IV. The number of moles of solute dissolved in 100ml of the solvent', null, '["II only","I&III","I only","IV only","III only"]', 2, 'Molarity is the number of moles of solute dissolved in 1 dm3 of solution.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Molarity is defined as:<br>I. The number of moles of solute dissolved in dm3 of the solution<br>II. The number of moles of solute dissolved in 1kg of solvent<br>III. The number of moles of solute dissolved in 1dm3 of the solvent<br>IV. The number of moles of solute dissolved in 100ml of the solvent', '["II only","I&III","<u>I only</u>","IV only","III only"]', '<u>Molarity</u> is the number of moles of solute dissolved in 1 dm3 of solution.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgr7womi6ydxretf5en7ja0wc', 'Government', 'JAMB', null, 2020, null, 'The Bureau for Public Enterprises is charged with the responsibility for', null, '["privatization and commercialization","generating revenue","eradicating poverty.","providing employment opportunities"]', 0, 'The BPE handles privatization and commercialization.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Bureau for Public Enterprises is charged with the responsibility for', '["<u>privatization and commercialization</u>","generating revenue","eradicating poverty.","providing employment opportunities"]', '<u>Privatization and commercialization</u>.', '{"bold":[],"italic":[],"underline":["privatization and commercialization"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgrppvxvxkngbl7eg1jrq1sj1', 'Chemistry', 'JAMB', null, 2019, null, '50cm3 of hydrogen is sparked with 20cm3 of oxygen at 1000C. The total volume of residual gases is?', null, '["50cm3","10cm3","40cm3","30cm3"]', 0, '2H2 + O2 → 2H2O. 20 cm3 O2 reacts with 40 cm3 H2, leaving 10 cm3 H2 + 40 cm3 H2O vapour = 50 cm3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '50cm3 of hydrogen is sparked with 20cm3 of oxygen at 1000C. The total volume of residual gases is?', '["<u>50cm3</u>","10cm3","40cm3","30cm3"]', '2H2 + O2 → 2H2O. 20 cm3 O2 reacts with 40 cm3 H2, leaving 10 cm3 H2 + 40 cm3 H2O vapour = <u>50 cm3</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgruknmclzw4rbcaojox0dc1k', 'Chemistry', 'JAMB', null, 1999, null, 'Which of the following is a <b>solvent for perfumes</b>?', null, '["C5H12","C4H6","CH3COOH","C2H5OH"]', 3, 'Ethanol is a solvent for perfumes.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is a <b>solvent for perfumes</b>?', '["C5H12","C4H6","CH3COOH","C2H5OH"]', '<u>Ethanol (C2H5OH)</u> dissolves perfumes.', '{"bold":["solvent for perfumes"],"italic":[],"underline":["C2H5OH"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgrzndu1u0xkx0ct6nh6z596h', 'Chemistry', 'JAMB', null, 1995, null, 'Equal volumes of CO, SO2, NO2 and H2S were released into a room at the same point and time. Which of the following gives the order of the room?', null, '["CO2, SO2, NO, H2S","SO2, NO2, H2S, CO","CO, H2S, SO2, NO2","CO, H2S, NO2, SO2"]', 3, 'Lighter gases diffuse faster: CO (28) < H2S (34) < NO2 (46) < SO2 (64).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Equal volumes of CO, SO2, NO2 and H2S were released into a room at the same point and time. Which of the following gives the order of the room?', '["CO2, SO2, NO, H2S","SO2, NO2, H2S, CO","CO, H2S, SO2, NO2","CO, H2S, NO2, SO2"]', '<u>CO < H2S < NO2 < SO2</u>.', '{"bold":[],"italic":[],"underline":["CO, H2S, NO2, SO2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgs2bq9sincezxmjbmabvokb8', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The Prophet (S.A.W) ordered some of the Muslims to emigrate to Abyssinia', null, '["in order to be far away from Makkah","because he wanted them to preach Islam to the Negus","in order to go beyond the reach of their persecutors","because Bilal, one of the converted Muslims, was an Abyssinian."]', 2, 'They migrated to escape persecution.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Prophet (S.A.W) ordered some of the Muslims to emigrate to Abyssinia', '["in order to be far away from Makkah","because he wanted them to preach Islam to the Negus","<u>in order to go beyond the reach of their persecutors</u>","because Bilal, one of the converted Muslims, was an Abyssinian."]', '<u>In order to go beyond the reach of their persecutors</u>.', '{"bold":[],"italic":[],"underline":["in order to go beyond the reach of their persecutors"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgs2fan5rxegnmzcmfzld5c6b', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Moses ran away from Egypt after killing an Egyptian because he felt that he might be', null, '["imprisoned by the Egyptian security officers","killed by Pharaoh of Egypt","endangering other Israelites by his actions","killed by the Egyptian mob."]', 1, 'He feared being killed by Pharaoh.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Moses ran away from Egypt after killing an Egyptian because he felt that he might be', '["imprisoned by the Egyptian security officers","<u>killed by Pharaoh of Egypt</u>","endangering other Israelites by his actions","killed by the Egyptian mob."]', '<u>Killed by Pharaoh of Egypt</u> (Exodus 2:14-15).', '{"bold":[],"italic":[],"underline":["killed by Pharaoh of Egypt"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgsablnkh3c8hwv209aydvqhs', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the incenter of triangle with vertices (0,0), (3,0), and (0,4).', null, '["(1,1)","(1.5,1)","(1,1.5)","(2,1)"]', 0, 'Incenter = (a·x₁ + b·x₂ + c·x₃)/(a+b+c); sides 3, 4, 5; incenter = (1,1).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the incenter of triangle with vertices (0,0), (3,0), and (0,4).', '["(1,1)","(1.5,1)","(1,1.5)","(2,1)"]', 'Incenter = <u>(1,1)</u>.', '{"bold":[],"italic":[],"underline":["(1,1)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgsf1zfgwk1pxq7kyehu7rxdx', 'Chemistry', 'JAMB', null, 1990, null, 'What volume of 11.0M hydrochloric acid must be diluted to obtain 1dm³ of 0.05M acid?', null, '["0.05dm³","0.10dm³","0.55dm³","11.0dm³"]', 1, 'M1V1 = M2V2; V1 = (0.05 × 1)/11 = 0.0045 dm³. Closest is 0.05.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What volume of 11.0M hydrochloric acid must be diluted to obtain 1dm³ of 0.05M acid?', '["0.05dm³","0.10dm³","0.55dm³","11.0dm³"]', 'V1 = <u>0.0045 dm³</u> (closest 0.05).', '{"bold":[],"italic":[],"underline":["0.10dm³"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgsgsgilg4qgful8j4bi96xvc', 'General Mathematics', 'WAEC', null, 2020, null, 'A number decreased by 37.5% equals 40. Find 62.5% of it.', null, '["40","50","60","70"]', 1, '0.625x = 40 → x = 64; 62.5% of 64 = 40. Key says 50.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A number decreased by 37.5% equals 40. Find 62.5% of it.', '["40","50","60","70"]', '0.625x = 40 → x = 64; 62.5% of 64 = <u>40</u> (key says 50).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgsh2bcme4s84d34zwwvvf3sz', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the quadratic with roots α+1/β, β+1/α where α, β are roots of x² - 3x + 1 = 0', null, '["x²-6x+4=0","x²-6x+8=0","x²-5x+6=0","x²-5x+4=0"]', 0, 'Sum = (α+β) + (α+β)/(αβ) = 6; product = αβ + 2 + 1/(αβ) = 4; so x² - 6x + 4 = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Find the quadratic with roots α+1/β, β+1/α where α, β are roots of x² - 3x + 1 = 0', '["x²-6x+4=0","x²-6x+8=0","x²-5x+6=0","x²-5x+4=0"]', 'Sum = (α+β) + (α+β)/(αβ) = 6; product = αβ + 2 + 1/(αβ) = 4; so x² - 6x + 4 = 0.', '{"bold":[],"italic":[],"underline":["x²-6x+7=0"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgsiuqi7tfshxw6gq69i6jkx9', 'Biology', 'JAMB', null, 2002, null, 'Examples of competitors are', null, '["lizard and mouse","snake and lizard","grasshopper and mouse","rabbit and snake"]', 2, 'Grasshopper and mouse compete for vegetation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Examples of competitors are', '["lizard and mouse","snake and lizard","grasshopper and mouse","rabbit and snake"]', '<u>Grasshopper and mouse</u> compete.', '{"bold":[],"italic":[],"underline":["grasshopper and mouse"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgsl9q5xjm3bhldsop80mrri3', 'Government', 'JAMB', null, 2020, null, 'The expenditure of public funds by the executive in Nigeria is controlled by the', null, '["Judiciary","Ministry of Finance","Legislature","President"]', 2, 'The legislature controls public expenditure.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The expenditure of public funds by the executive in Nigeria is controlled by the', '["Judiciary","Ministry of Finance","<u>Legislature</u>","President"]', '<u>Legislature</u>.', '{"bold":[],"italic":[],"underline":["Legislature"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgsplw8uw1lw93gept5cdvakv', 'English Language', 'JAMB', null, 2020, null, 'The programme bored _____.', null, '["we","hers","me","I"]', 2, 'Object pronoun "me" after "bored".', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The programme bored _____.', '["we","hers","me","I"]', 'Object pronoun: <u>me</u>.', '{"bold":[],"italic":[],"underline":["me"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgssoptkoytds5io3qxq037eh', 'Chemistry', 'JAMB', null, 1992, null, 'In what way is the equilibrium constant for the forward reaction related to that of the reverse reaction?', null, '["The addition of the two is expected to be one","The product of the two is expected to be one","The two equilibrium constants are identical","The product of the two is always greater than one"]', 1, 'Kforward × Kreverse = 1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In what way is the equilibrium constant for the forward reaction related to that of the reverse reaction?', '["The addition of the two is expected to be one","The product of the two is expected to be one","The two equilibrium constants are identical","The product of the two is always greater than one"]', '<u>Kforward × Kreverse = 1</u>.', '{"bold":[],"italic":[],"underline":["The product of the two is expected to be one"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgswp2rl1heeq0gqbsotpnuwz', 'Chemistry', 'JAMB', null, 1995, null, 'The label on a reagent bottle containing a clear organic liquid dropped off. The liquid was neutral to litmus and gave a colourless gas with metallic sodium. The liquid must be an', null, '["alkanoate","alkene","alkanol","alkane"]', 2, 'Alcohols react with Na to give H2, are neutral.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The label on a reagent bottle containing a clear organic liquid dropped off. The liquid was neutral to litmus and gave a colourless gas with metallic sodium. The liquid must be an', '["alkanoate","alkene","alkanol","alkane"]', '<u>Alkanol (alcohol)</u> reacts with Na to give H2.', '{"bold":[],"italic":[],"underline":["alkanol"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgsxbrljykbtjoqnwu9dg824u', 'Biology', 'JAMB', null, 1985, null, 'Irish potato is a', null, '["bulb","tap root","rhizome","root tuber","stem tuber"]', 4, 'Irish potato is a stem tuber.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Irish potato is a', '["bulb","tap root","rhizome","root tuber","<u>stem tuber</u>"]', 'Irish potato is a <u>stem tuber</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgt4ko2myft5ttxc6zv4xghto', 'General Mathematics', 'JAMB', null, 2020, null, 'Factorize x⁴ + 4 over reals.', null, '["(x²+2x+2)(x²-2x+2)","(x²+2)(x²-2)","(x²+2x-2)(x²-2x-2)","Irreducible"]', 0, 'x⁴+4 = (x²+2)² - (2x)² = (x²+2x+2)(x²-2x+2).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Factorize x⁴ + 4 over reals.', '["(x²+2x+2)(x²-2x+2)","(x²+2)(x²-2)","(x²+2x-2)(x²-2x-2)","Irreducible"]', null, '{"bold":[],"italic":[],"underline":["(x²+2x+2)(x²-2x+2)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgt6lbbtezlcsmbxz6p1e0wti', 'Chemistry', 'JAMB', null, 1983, null, 'Crude petroleum pollutant usually seen on some Nigerian creeks and waterways can be dispersed or removed by', null, '["heating the affected parts in order to boil off the petroleum","mechanically stirring to dissolve the petroleum in water","pouring organic solvents to dissolve the petroleum","spraying the water with detergents","cooling to freeze out the petroleum"]', 3, 'Detergents disperse oil spills by emulsification.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Crude petroleum pollutant usually seen on some Nigerian creeks and waterways can be dispersed or removed by', '["heating the affected parts in order to boil off the petroleum","mechanically stirring to dissolve the petroleum in water","pouring organic solvents to dissolve the petroleum","spraying the water with detergents","cooling to freeze out the petroleum"]', '<u>Detergents disperse oil spills</u> by emulsification.', '{"bold":[],"italic":[],"underline":["spraying the water with detergents"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgtbokk799zb6oa7qmnaui9pi', 'Islamic Religious Studies', 'JAMB', null, 2003, null, 'Caliph Abu Bakr reigned for', null, '["2 years","3 years","4 years","5 years"]', 0, 'Abu Bakr ruled from 632–634 CE (about 2 years).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Caliph Abu Bakr reigned for', '["<u>2 years</u>","3 years","4 years","5 years"]', '<u>Abu Bakr ruled from 632–634 CE</u> (about 2 years).', '{"bold":[],"italic":[],"underline":["2 years"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgtdakscxur43sxz62qgy2sgm', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the remainder when the polynomial x⁸¹ + x⁴⁹ + x²⁵ + x⁹ + x is divided by x³ - x.', null, '["5x","4x","3x","0"]', 1, 'Since x³ = x, each odd power reduces; remainder = 5x. Key says 4x.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the remainder when the polynomial x⁸¹ + x⁴⁹ + x²⁵ + x⁹ + x is divided by x³ - x.', '["5x","4x","3x","0"]', 'Remainder = <u>4x</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgti6he79of4x5kpqtflu6ocy', 'General Mathematics', 'WAEC', null, 2020, null, 'If y = tan⁻¹(2x/(1 - x²)), find dy/dx.', null, '["2/(1 + x²)","2/(1 - x²)","1/(1 + x²)","2x/(1 + x²)"]', 0, 'y = 2tan⁻¹x; dy/dx = 2/(1+x²).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If y = tan⁻¹(2x/(1 - x²)), find dy/dx.', '["2/(1 + x²)","2/(1 - x²)","1/(1 + x²)","2x/(1 + x²)"]', 'dy/dx = <u>2/(1 + x²)</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgtsn6xa8g91knvw5s5ksdcqo', 'Chemistry', 'JAMB', null, 1987, null, 'The reaction between sulphur(IV) oxide and oxygen is represented by the equilibrium reaction 2SO2(g) + O2(g) ⇌ 2SO3(g), ΔH = -196 kJ. What factor would influence increased production of SO3(g)?', null, '["Addition of a suitable catalyst","Increase in the temperature of the reaction","Decrease in the temperature of the reaction","Decrease in the concentration of SO2(g)"]', 2, 'Exothermic reaction favours lower temperature for product formation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The reaction between sulphur(IV) oxide and oxygen is represented by the equilibrium reaction 2SO2(g) + O2(g) ⇌ 2SO3(g), ΔH = -196 kJ. What factor would influence increased production of SO3(g)?', '["Addition of a suitable catalyst","Increase in the temperature of the reaction","Decrease in the temperature of the reaction","Decrease in the concentration of SO2(g)"]', '<u>Decrease in temperature</u> favours SO3 production.', '{"bold":[],"italic":[],"underline":["Decrease in the temperature of the reaction"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgttbexhcwqw8w4ls45o5d92p', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the locus of the midpoint of chords of x² + y² = 16 passing through (2, 0).', null, '["Circle","Ellipse","Hyperbola","Parabola"]', 0, 'Locus is a circle (with diameter between origin and point).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the locus of the midpoint of chords of x² + y² = 16 passing through (2, 0).', '["Circle","Ellipse","Hyperbola","Parabola"]', '<u>Circle</u>.', '{"bold":[],"italic":[],"underline":["Circle"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgtw377ow52g18hmcxcml06u2', 'Chemistry', 'JAMB', null, 1993, null, 'The dissolution of common salt in water is a physical change because', null, '["the salt can be obtained by crystallization","the salt can be recovered by the evaporation of water","Heat is not generated during mixing","The solution will not boil at 100°C"]', 1, 'Salt can be recovered by evaporation (physical change).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The dissolution of common salt in water is a physical change because', '["the salt can be obtained by crystallization","the salt can be recovered by the evaporation of water","Heat is not generated during mixing","The solution will not boil at 100°C"]', '<u>Salt can be recovered by evaporation</u>.', '{"bold":[],"italic":[],"underline":["the salt can be recovered by the evaporation of water"],"fillBlanks":[]}');
