insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgtzg5eonj00n00d5lp4femcx', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Jonah''s explanation to the LORD for resisting His first call teaches us that God is', null, '["quick to anger","not sincere in His call","repentant of evil","not ready to act fast."]', 2, 'God is repentant of evil.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Jonah''s explanation to the LORD for resisting His first call teaches us that God is', '["quick to anger","not sincere in His call","<u>repentant of evil</u>","not ready to act fast."]', '<u>Repentant of evil</u> (Jonah 4:2).', '{"bold":[],"italic":[],"underline":["repentant of evil"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgugw8r4am89xoxugmx2f5al6', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The expressions Iqra'', ''allama and al-qalam in Surat al-''Alaq emphasize the importance of', null, '["humility","knowledge","worship","generosity."]', 1, 'They emphasize the importance of knowledge.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The expressions Iqra'', ''allama and al-qalam in Surat al-''Alaq emphasize the importance of', '["humility","<u>knowledge</u>","worship","generosity."]', '<u>Knowledge</u> (Q. 96).', '{"bold":[],"italic":[],"underline":["knowledge"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgurs8wiocszgkwjee7hwdo2n', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the length of the latus rectum of the ellipse x²/25 + y²/9 = 1.', null, '["18/5","16/5","14/5","12/5"]', 0, 'Latus rectum = 2b²/a = 18/5.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the length of the latus rectum of the ellipse x²/25 + y²/9 = 1.', '["18/5","16/5","14/5","12/5"]', 'Length = <u>18/5</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgutwz8rna96rlci0uq5asu99', 'Biology', 'JAMB', null, 1993, null, 'The smallest living organisms which share the characteristics of both living and non-living matter are', null, '["bacteria","fungi","viruses","protozoa"]', 2, 'Viruses share characteristics of living and non-living matter.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The smallest living organisms which share the characteristics of both living and non-living matter are', '["bacteria","fungi","<u>viruses</u>","protozoa"]', '<u>Viruses</u> share characteristics of living and non-living matter.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cguvd8zhxrm5uxd51qeh11yao', 'Biology', 'JAMB', null, 2000, null, 'In an experiment to estimate the volume of air in a soil sample using a measuring cylinder, it was found that:<br>Initial volume of water = pcm³<br>Volume of soil before mixing with water = qcm³<br>Final volume of water after adding soil = rcm³<br>From the data above, which of the following deductions is correct?', null, '["r = p + q","r > p + q","q = r - p","r < p + q"]', 3, 'Air in soil reduces final volume, so r < p + q.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In an experiment to estimate the volume of air in a soil sample using a measuring cylinder, it was found that:<br>Initial volume of water = pcm³<br>Volume of soil before mixing with water = qcm³<br>Final volume of water after adding soil = rcm³<br>From the data above, which of the following deductions is correct?', '["r = p + q","r > p + q","q = r - p","r < p + q"]', '<u>r < p + q</u> (air reduces final volume).', '{"bold":[],"italic":[],"underline":["r < p + q"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgv36r47o1et0sbk6n3maiyr7', 'Chemistry', 'JAMB', null, 1991, null, 'A sample of temporary hard water can be prepared in the laboratory by', null, '["dissolving calcium chloride in distilled water","saturating lime water with carbon(IV) oxide","saturating distilled water with calcium hydroxide","dissolving sodium hydrogen trioxocarbonate(IV) in some distilled water"]', 1, 'Temporary hard water contains Ca(HCO3)2, formed by saturating lime water with CO2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A sample of temporary hard water can be prepared in the laboratory by', '["dissolving calcium chloride in distilled water","saturating lime water with carbon(IV) oxide","saturating distilled water with calcium hydroxide","dissolving sodium hydrogen trioxocarbonate(IV) in some distilled water"]', '<u>Saturating lime water with CO2</u> gives temporary hard water.', '{"bold":[],"italic":[],"underline":["saturating lime water with carbon(IV) oxide"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgv91jeubid6ws0mva8ngmz6p', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The man who analyzed the first encounter of the Prophet (S.A.W) with Angel Jibril was', null, '["Hatib b. Abi Balta''a","Waraqah b. Nawfal","Arqam b. Arqam","''Uthman b. ''Affan."]', 1, 'Waraqah b. Nawfal analyzed the first encounter.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The man who analyzed the first encounter of the Prophet (S.A.W) with Angel Jibril was', '["Hatib b. Abi Balta''a","<u>Waraqah b. Nawfal</u>","Arqam b. Arqam","''Uthman b. ''Affan."]', '<u>Waraqah b. Nawfal</u>.', '{"bold":[],"italic":[],"underline":["Waraqah b. Nawfal"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgveza7ilhulh3gsevujj302g', 'General Mathematics', 'WAEC', null, 2020, null, 'Evaluate 5¹⁰ (mod 11).', null, '["1","5","10","2"]', 0, 'By Fermat''s little theorem, 5¹⁰ ≡ 1 mod 11.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Evaluate 5¹⁰ (mod 11).', '["1","5","10","2"]', '5¹⁰ ≡ <u>1</u> mod 11.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgvf52dmwntsiz6xo4edro7m9', 'General Mathematics', 'JAMB', null, 2020, null, 'Binomial distribution with n = 5, p = 0.2. Find P(X ≤ 1).', null, '["0.73728","0.4096","0.32768","0.67232"]', 0, 'P(X=0) + P(X=1) = 0.8⁵ + 5(0.2)(0.8)⁴ = 0.32768 + 0.4096 = 0.73728.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Binomial distribution with n = 5, p = 0.2. Find P(X ≤ 1).', '["0.73728","0.4096","0.32768","0.67232"]', 'P = <u>0.73728</u>.', '{"bold":[],"italic":[],"underline":["0.73728"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgvfnki02qir8jqst7xreni31', 'Biology', 'JAMB', null, 1992, null, 'The flow of air and water in or out of the mesophyll layer of a leaf is controlled by the', null, '["stomata","lenticles","air spaces","guard cells"]', 0, 'Stomata control air and water flow in leaves.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The flow of air and water in or out of the mesophyll layer of a leaf is controlled by the', '["<u>stomata</u>","lenticles","air spaces","guard cells"]', '<u>Stomata</u> control air and water flow in leaves.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgvitt8bi1xecyjl0k80dqknb', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Which of the following led away a section of the Muslim army when preparations were on for the battle of Uhud?', null, '["Abu Lahb","Abu Jahl","''Abdullah b. Ubayy","''Abdullah b. Awwam."]', 2, 'Abdullah b. Ubayy led away a section.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following led away a section of the Muslim army when preparations were on for the battle of Uhud?', '["Abu Lahb","Abu Jahl","<u>''Abdullah b. Ubayy</u>","''Abdullah b. Awwam."]', '<u>''Abdullah b. Ubayy</u>.', '{"bold":[],"italic":[],"underline":["''Abdullah b. Ubayy"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgw0iypmjpl8ml5zj88rk27xu', 'Chemistry', 'JAMB', null, 1993, null, 'NH3 + H2O → NH4⁺ + OH⁻. It may be deduced from the reaction above that', null, '["a redox reaction has occurred","H3O⁺ acts as an oxidizing agent","H3O⁺ acts as an acid","Water acts as an acid"]', 3, 'Water donates a proton (acid) to NH3 (base).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'NH3 + H2O → NH4⁺ + OH⁻. It may be deduced from the reaction above that', '["a redox reaction has occurred","H3O⁺ acts as an oxidizing agent","H3O⁺ acts as an acid","Water acts as an acid"]', '<u>Water acts as an acid</u> (proton donor).', '{"bold":[],"italic":[],"underline":["Water acts as an acid"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgw9sghf5ewa9dcrp2horg4pn', 'Chemistry', 'JAMB', null, 1994, null, 'An increase in temperature causes an increase in the pressure of a gas because', null, '["it decreases the number of collisions between the molecules","the molecules of the gas bombard the walls of the container more frequently","it increases the number of collisions between the molecules","it causes the molecules to combine"]', 1, 'More frequent bombardment of walls increases pressure.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An increase in temperature causes an increase in the pressure of a gas because', '["it decreases the number of collisions between the molecules","the molecules of the gas bombard the walls of the container more frequently","it increases the number of collisions between the molecules","it causes the molecules to combine"]', '<u>More frequent bombardment of walls</u> increases pressure.', '{"bold":[],"italic":[],"underline":["the molecules of the gas bombard the walls of the container more frequently"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgwfja4xfhmq3meqhacdhaby4', 'Government', 'JAMB', null, 2020, null, 'Under the emirate system, legislative functions were performed by the', null, '["Khadi","Ulama","Hakimi","Emir"]', 3, 'The Emir performed legislative functions.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Under the emirate system, legislative functions were performed by the', '["Khadi","Ulama","Hakimi","<u>Emir</u>"]', '<u>Emir</u>.', '{"bold":[],"italic":[],"underline":["Emir"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgwl29q82rubm94f6kw15gl6y', 'Chemistry', 'JAMB', null, 1994, null, 'The general formula of <b>alkanones</b> is', null, '["RCHO","RCO","RCOOH","RCOOR"]', 1, 'Alkanones have the general formula RCO (ketone).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The general formula of <b>alkanones</b> is', '["RCHO","RCO","RCOOH","RCOOR"]', '<u>RCO (ketone)</u>.', '{"bold":["alkanones"],"italic":[],"underline":["RCO"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgwlyoxm7r61idgb9xtzphp4p', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'The LORD repented of the evil which He intended for His people because Moses', null, '["reminded Him of His promise to Abraham, Isaac and Israel","made the people drink of the water of the burnt calf","burnt the golden calf which the people made","broke the tablets out of his hands."]', 0, 'Moses reminded God of His promise to Abraham, Isaac, and Israel.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The LORD repented of the evil which He intended for His people because Moses', '["<u>reminded Him of His promise to Abraham, Isaac and Israel</u>","made the people drink of the water of the burnt calf","burnt the golden calf which the people made","broke the tablets out of his hands."]', '<u>Reminded Him of His promise to Abraham, Isaac and Israel</u> (Exodus 32:12-13).', '{"bold":[],"italic":[],"underline":["reminded Him of His promise to Abraham, Isaac and Israel"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgwmdr6ktwmy447igm5j1hgjt', 'General Mathematics', 'WAEC', null, 2020, null, 'If (a, 2a) lies on 3x - 2y = 5, find a.', null, '["1","-5","3","4"]', 1, '3a - 4a = 5, so a = -5.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'If (a, 2a) lies on 3x - 2y = 5, find a.', '["1","-5","3","4"]', '3a - 4a = 5, so a = -5.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgwu1afzz4zxmk3fewmrzyn9s', 'Biology', 'JAMB', null, 2000, null, 'The inner ear contains two main organs, namely, the', null, '["eardrum and eustachinan tube","cochlea and semi-circular canals","oval window and ossicles","pinna and cochlea"]', 1, 'cochlea and semi-circular canals is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The inner ear contains two main organs, namely, the', '["eardrum and eustachinan tube","<u>cochlea and semi-circular canals</u>","oval window and ossicles","pinna and cochlea"]', 'cochlea and semi-circular canals is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgx5oqulumtwe6y22p1jh4mr9', 'Government', 'JAMB', null, 2020, null, 'In judicial administration, the term ''the bench'' refers to the', null, '["registrars.","judges","lawyers","litigants"]', 1, 'The bench refers to the judges.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In judicial administration, the term ''the bench'' refers to the', '["registrars.","<u>judges</u>","lawyers","litigants"]', '<u>Judges</u>.', '{"bold":[],"italic":[],"underline":["judges"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgx82zw741wxozx13pu9ce3l5', 'Chemistry', 'JAMB', null, 1996, null, '50cm³ of sulphur(IV) oxide, 800cm³ of ammonia, 450cm³ of hydrogen chloride, 1.0cm³ of water at 15°C. Which is suitable for demonstrating the <b>fountain experiment</b>?', null, '["Sulphur(IV) oxide and hydrogen chloride","Carbon(IV) oxide and ammonia","Ammonia and hydrogen chloride","Carbon(IV) oxide and sulphur(IV) oxide"]', 2, 'NH3 and HCl are very soluble.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '50cm³ of sulphur(IV) oxide, 800cm³ of ammonia, 450cm³ of hydrogen chloride, 1.0cm³ of water at 15°C. Which is suitable for demonstrating the <b>fountain experiment</b>?', '["Sulphur(IV) oxide and hydrogen chloride","Carbon(IV) oxide and ammonia","Ammonia and hydrogen chloride","Carbon(IV) oxide and sulphur(IV) oxide"]', '<u>Ammonia and HCl</u>.', '{"bold":["fountain experiment"],"italic":[],"underline":["Ammonia and hydrogen chloride"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgxakta49wey0icw4904zz3el', 'Islamic Religious Studies', 'JAMB', null, 2008, null, 'In congregational Salah, a person who comes late is expected to', null, '["pronounce the taslim to indicate his arrival","say subhanallah so that the Imam can note his presence","recite the iqama before joining the congregation","make takbiratul ihram and join the Imam"]', 3, 'A latecomer makes takbiratul ihram and joins the Imam.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In congregational Salah, a person who comes late is expected to', '["pronounce the taslim to indicate his arrival","say subhanallah so that the Imam can note his presence","recite the iqama before joining the congregation","<u>make takbiratul ihram and join the Imam</u>"]', 'A latecomer makes <u>takbiratul ihram and joins the Imam</u>.', '{"bold":[],"italic":[],"underline":["make takbiratul ihram and join the Imam"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgxbcwc2xykekcwewgftz2mx0', 'Chemistry', 'JAMB', null, 1998, null, 'Mg²⁺(aq) + 2e⁻ → Mg(s) E° = -2.370; Zn²⁺(aq) + 2e⁻ → Zn(s) E° = -0.763; Cd²⁺(aq) + 2e⁻ → Cd(s) E° = -0.403; Cu²⁺(aq) + 2e⁻ → Cu(s) E° = +0.403. In the electrochemical series above, the strongest reducing agent is', null, '["Cu(s)","Cd(s)","Zn(s)","Mg(s)"]', 3, 'Mg has the most negative E° (strongest reducing agent).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Mg²⁺(aq) + 2e⁻ → Mg(s) E° = -2.370; Zn²⁺(aq) + 2e⁻ → Zn(s) E° = -0.763; Cd²⁺(aq) + 2e⁻ → Cd(s) E° = -0.403; Cu²⁺(aq) + 2e⁻ → Cu(s) E° = +0.403. In the electrochemical series above, the strongest reducing agent is', '["Cu(s)","Cd(s)","Zn(s)","Mg(s)"]', '<u>Mg (most negative E°)</u> is the strongest reducing agent.', '{"bold":[],"italic":[],"underline":["Mg(s)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgxfk3mjv9bb7yrx30u6brjt5', 'General Mathematics', 'WAEC', null, 2020, null, 'The sum of an infinite GP is 4, sum of squares of terms is 12. Find the first term.', null, '["24/7","2.5","3","1.5"]', 0, 'a/(1-r) = 4 and a²/(1-r²) = 12 → (1-r)/(1+r) = 3/4 → r = 1/7, a = 24/7.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'The sum of an infinite GP is 4, sum of squares of terms is 12. Find the first term.', '["24/7","2.5","3","1.5"]', 'a/(1-r) = 4 and a²/(1-r²) = 12 → (1-r)/(1+r) = 3/4 → r = 1/7, a = 24/7.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgxgqdoc2fqycsncqqvqwswor', 'General Mathematics', 'JAMB', null, 2020, null, 'If log_a(bc) = x, log_b(ca) = y and log_c(ab) = z, find 1/(x + 1) + 1/(y + 1) + 1/(z + 1).', null, '["0","1","2","3"]', 1, 'Identity: sum = 1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If log_a(bc) = x, log_b(ca) = y and log_c(ab) = z, find 1/(x + 1) + 1/(y + 1) + 1/(z + 1).', '["0","1","2","3"]', 'Sum = <u>1</u>.', '{"bold":[],"italic":[],"underline":["1"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgxjb6dwbyoo1c665c5ok0m3t', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Nehemiah in exile functioned as the king''s', null, '["guard","secretary","cupbearer","adviser."]', 2, 'Nehemiah was the king''s cupbearer.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Nehemiah in exile functioned as the king''s', '["guard","secretary","<u>cupbearer</u>","adviser."]', '<u>Cupbearer</u> (Nehemiah 1:11).', '{"bold":[],"italic":[],"underline":["cupbearer"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgxsps8nwil8h7ld7zxjlxyra', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'During the reign of Caliph ''Ali, the seat of administration moved from al-Madinah to', null, '["Basra","Damascus","Mecca","Kufah."]', 3, 'The seat moved to Kufah.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'During the reign of Caliph ''Ali, the seat of administration moved from al-Madinah to', '["Basra","Damascus","Mecca","<u>Kufah.</u>"]', '<u>Kufah</u>.', '{"bold":[],"italic":[],"underline":["Kufah."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgy0rkwc0ol4zo1c0v9qyueb7', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Taking the ritual bath for Friday prayers is', null, '["wajib","sunnah","mustahab","mubah."]', 1, 'It is sunnah.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Taking the ritual bath for Friday prayers is', '["wajib","<u>sunnah</u>","mustahab","mubah."]', '<u>Sunnah</u>.', '{"bold":[],"italic":[],"underline":["sunnah"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgyb7nguw4m9s1b8y5t2hjfxu', 'Biology', 'JAMB', null, 1992, null, 'The blood vessel which carries blood from the alimentary canal to the liver is the', null, '["hepatic artery","hepatic vein","hepatic portal vein","mesenteric artery"]', 2, 'The hepatic portal vein carries blood to the liver.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The blood vessel which carries blood from the alimentary canal to the liver is the', '["hepatic artery","hepatic vein","<u>hepatic portal vein</u>","mesenteric artery"]', 'The <u>hepatic portal vein</u> carries blood to the liver.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgybqdm09cvq67ui2tbsm0rdu', 'Chemistry', 'JAMB', null, 1994, null, 'An increase in temperature causes an increase in the pressure of a gas because', null, '["it decreases the number of collisions between the molecules","the molecules of the gas bombard the walls of the container more frequently","it increases the number of collisions between the molecules","it causes the molecules to combine"]', 1, 'More frequent bombardment of walls increases pressure.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An increase in temperature causes an increase in the pressure of a gas because', '["it decreases the number of collisions between the molecules","the molecules of the gas bombard the walls of the container more frequently","it increases the number of collisions between the molecules","it causes the molecules to combine"]', '<u>More frequent bombardment of walls</u> increases pressure.', '{"bold":[],"italic":[],"underline":["the molecules of the gas bombard the walls of the container more frequently"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgybz9wa8rmkm4srp5hy3qkpl', 'Government', 'JAMB', null, 2020, null, 'Judicial administration in respect of national code of conduct lies with the', null, '["Public Complaints Commission","Judicial Service Commission","Code of Conduct Bureau.","Code of Conduct Tribunal"]', 3, 'The Code of Conduct Tribunal handles judicial administration of the code of conduct.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Judicial administration in respect of national code of conduct lies with the', '["Public Complaints Commission","Judicial Service Commission","Code of Conduct Bureau.","<u>Code of Conduct Tribunal</u>"]', '<u>Code of Conduct Tribunal</u>.', '{"bold":[],"italic":[],"underline":["Code of Conduct Tribunal"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgyg2abew2ono267d6waz5dv6', 'Chemistry', 'JAMB', null, 1995, null, 'COOH-COOH + H2O ⇌ COOH-COONa + NaOH. The above reaction is an example of', null, '["displacement reaction","a neutralization reaction","an elimination reaction","Saponification"]', 1, 'Acid + base → salt + water = neutralization.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'COOH-COOH + H2O ⇌ COOH-COONa + NaOH. The above reaction is an example of', '["displacement reaction","a neutralization reaction","an elimination reaction","Saponification"]', '<u>Neutralization</u>.', '{"bold":[],"italic":[],"underline":["a neutralization reaction"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgyhsnsfrpa4nttbr5txovzh0', 'General Mathematics', 'WAEC', null, 2020, null, 'Combined variance of two groups of equal size and equal variance σ².', null, '["σ²","2σ²","σ²/2","0"]', 0, 'Combined variance = σ² (equal means).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Combined variance of two groups of equal size and equal variance σ².', '["σ²","2σ²","σ²/2","0"]', 'Combined variance = <u>σ²</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgyjo6x6ugw9lus0m4xcey6el', 'General Mathematics', 'WAEC', null, 2020, null, 'What is the angle between the lines 2x + y + 5 = 0 and x - 2y + 1 = 0?', null, '["0°","45°","60°","90°"]', 3, 'Slopes -2 and 1/2; product = -1 → perpendicular.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is the angle between the lines 2x + y + 5 = 0 and x - 2y + 1 = 0?', '["0°","45°","60°","90°"]', 'Angle = <u>90°</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgyy0bbfs3k48utuarzq1sn62', 'Biology', 'JAMB', null, 1991, null, 'Some of the diseases caused by bacteria are', null, '["tuberculosis, gonorrhoea and syphilis","tuberculosis, gonorrhoea and AIDS","Poliomyelitis, syphilis and gonorrhoea","AIDS, cholera and tuberculosis"]', 3, 'Tuberculosis, gonorrhoea, and syphilis are caused by bacteria.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Some of the diseases caused by bacteria are', '["tuberculosis, gonorrhoea and syphilis","tuberculosis, gonorrhoea and AIDS","Poliomyelitis, syphilis and gonorrhoea","<u>tuberculosis, gonorrhoea and syphilis</u>"]', '<u>Tuberculosis, gonorrhoea, and syphilis are caused by bacteria</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgz6ouz4vkhqj3m3wyb6m9r7k', 'Biology', 'JAMB', null, 2001, null, 'The highest percentage of energy in an ecosystem occurs at the level of the', null, '["secondary consumers","decomposers","producers","primary consumers"]', 2, 'Producers have the highest energy.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The highest percentage of energy in an ecosystem occurs at the level of the', '["secondary consumers","decomposers","producers","primary consumers"]', '<u>Producers</u> have the highest energy.', '{"bold":[],"italic":[],"underline":["producers"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgz8ee9934nx9q1m5rm5sc8z4', 'General Mathematics', 'JAMB', null, 2020, null, 'If sum of roots of kx² - 3x + 1 = 0 equals product, find k', null, '["3","4","5","6"]', 1, '3/k = 1/k → 3 = 1 (no solution). Key says 4.', false, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'If sum of roots of kx² - 3x + 1 = 0 equals product, find k', '["3","4","5","6"]', 'No solution (key says 4).', '{"bold":[],"italic":[],"underline":["4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgzbqw1rgzzufk6myhvpxtsz9', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the sum of the series 1² + 3² + 5² + ... up to n terms.', null, '["n(4n² - 1)/3","n(4n² + 1)/3","n(2n - 1)(2n + 1)/3","n(2n + 1)(2n + 3)/3"]', 0, 'Sum = n(2n-1)(2n+1)/3 = n(4n²-1)/3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the sum of the series 1² + 3² + 5² + ... up to n terms.', '["n(4n² - 1)/3","n(4n² + 1)/3","n(2n - 1)(2n + 1)/3","n(2n + 1)(2n + 3)/3"]', 'Sum = <u>n(4n² - 1)/3</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgzw4jvh35qz2zhya3q5wegg1', 'General Mathematics', 'WAEC', null, 2020, null, 'In a class of 40 students, 25 passed Mathematics, 20 passed Physics, and 8 passed both. What is the probability that a student selected at random passed at least one of the subjects?', null, '["7/8","37/40","5/8","5/40"]', 1, 'At least one = 25 + 20 - 8 = 37; P = 37/40.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In a class of 40 students, 25 passed Mathematics, 20 passed Physics, and 8 passed both. What is the probability that a student selected at random passed at least one of the subjects?', '["7/8","37/40","5/8","5/40"]', 'P = <u>37/40</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cgzy4woe04a789xybiynmxfyb', 'Government', 'JAMB', null, 2020, null, 'The Igbo political system was based on', null, '["age grades","family ties","Umunna","Umuada"]', 2, 'The Igbo political system was based on Umunna.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Igbo political system was based on', '["age grades","family ties","<u>Umunna</u>","Umuada"]', '<u>Umunna</u>.', '{"bold":[],"italic":[],"underline":["Umunna"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ch07uvtr04ohcsf8x5whvj6fa', 'Islamic Religious Studies', 'JAMB', null, 2010, null, 'Who among the six compilers of Hadith became blind before his death?', null, '["Nasa''i","Abu Da''ud","Ibn Maja","Tirmidhi"]', 3, 'Imam Tirmidhi became blind before his death.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Who among the six compilers of Hadith became blind before his death?', '["Nasa''i","Abu Da''ud","Ibn Maja","<u>Tirmidhi</u>"]', '<u>Imam Tirmidhi</u> became blind before his death.', '{"bold":[],"italic":[],"underline":["Tirmidhi"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ch0e6c9xwilrxep4z206tswnn', 'General Mathematics', 'WAEC', null, 2020, null, 'If ∫₁⁴ f(x)dx = 10 and ∫₄⁶ f(x)dx = 4, find ∫₁⁶ (f(x) + 2)dx.', null, '["16","20","24","30"]', 2, '∫f = 14; ∫2 dx = 10; total = 24.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If ∫₁⁴ f(x)dx = 10 and ∫₄⁶ f(x)dx = 4, find ∫₁⁶ (f(x) + 2)dx.', '["16","20","24","30"]', 'Integral = <u>24</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ch0j4102pp8j7vd2ps8razro4', 'Chemistry', 'JAMB', null, 1986, null, 'Which of the following group of physical properties increases from left to right of the periodic table?<br>1 Ionization energy<br>2 Atomic radius<br>3 Electronegativity<br>4 Electron affinity', null, '["1 and 2","1, 2 and 3","3 and 4","1, 2 and 4","1, 3 and 4"]', 4, 'Ionization energy, electronegativity, and electron affinity increase across a period.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following group of physical properties increases from left to right of the periodic table?<br>1 Ionization energy<br>2 Atomic radius<br>3 Electronegativity<br>4 Electron affinity', '["1 and 2","1, 2 and 3","3 and 4","1, 2 and 4","1, 3 and 4"]', '<u>1, 3 and 4</u> increase across a period.', '{"bold":[],"italic":[],"underline":["1, 3 and 4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ch0qlylrp52hbyanev11fsa59', 'Biology', 'JAMB', null, 1984, null, 'Which of the following is NOT a waste product of plants?', null, '["Tannis","Oxygen","Carbondioxide","Sap","Alkaloids"]', 3, 'Sap is not a waste product; it is a transport fluid.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is <b>NOT</b> a waste product of plants?', '["Tannis","Oxygen","Carbondioxide","<u>Sap</u>","Alkaloids"]', '<u>Sap</u> is not a waste product; it is a transport fluid.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ch0tqipdks90f1dqqbe5dko1t', 'General Mathematics', 'JAMB', null, 2020, null, 'If n(U) = 100, n(A) = 40, n(B) = 50, n(A ∩ B) = 20, find n(A'' ∩ B'').', null, '["30","40","50","60"]', 1, 'n(A ∪ B) = 40 + 50 - 20 = 70; n(A'' ∩ B'') = 100 - 70 = 30. Key says 40.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If n(U) = 100, n(A) = 40, n(B) = 50, n(A ∩ B) = 20, find n(A'' ∩ B'').', '["30","40","50","60"]', 'n(A'' ∩ B'') = <u>40</u> (per key).', '{"bold":[],"italic":[],"underline":["40"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ch0xwx3co8xxj8lumij04goj3', 'General Mathematics', 'JAMB', null, 2020, null, 'Derivative of sin x from first principles.', null, '["cos x","-cos x","sin x","-sin x"]', 0, 'lim(h→0)[sin(x+h)-sin x]/h = cos x.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Derivative of sin x from first principles.', '["cos x","-cos x","sin x","-sin x"]', 'Derivative = <u>cos x</u>.', '{"bold":[],"italic":[],"underline":["cos x"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ch14ix385pt87edak0e7cusgs', 'Biology', 'JAMB', null, 1989, null, 'Aged erythrocytes are destroyed in the', null, '["pancreas","liver","lymph nodes","kidney"]', 1, 'Aged erythrocytes are destroyed in the liver.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Aged erythrocytes are destroyed in the', '["pancreas","<u>liver</u>","lymph nodes","kidney"]', 'Aged erythrocytes are destroyed in the <u>liver</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ch159enxspe6bo35wb7cokotx', 'General Mathematics', 'WAEC', null, 2020, null, 'Range of m so that x² + mx + 9 > 0 for all real x.', null, '["-6 < m < 6","m < -6 or m > 6","-3 < m < 3","m < -3 or m > 3"]', 0, 'Discriminant < 0 → m² < 36 → -6 < m < 6.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Range of m so that x² + mx + 9 > 0 for all real x.', '["-6 < m < 6","m < -6 or m > 6","-3 < m < 3","m < -3 or m > 3"]', 'Range: <u>-6 < m < 6</u>.', null);
