insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ch1iuzvvl6jj8hfjfg2cvie6p', 'Biology', 'JAMB', null, 1988, null, 'Which of the following sets of organism represents the correct trend from simple to complex structural organization? 1 Mollusca 2 Platyhelminthes 3 Nematoda 4 Protozoa', null, '["4→1→2→3","4→3→2→1","4→2→1→3","4→2→3→1"]', 3, 'Trend: Protozoa (4) → Platyhelminthes (2) → Nematoda (3) → Mollusca (1).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following sets of organism represents the correct trend from simple to complex structural organization?<br>1 Mollusca<br>2 Platyhelminthes<br>3 Nematoda<br>4 Protozoa', '["4→1→2→3","4→3→2→1","4→2→1→3","<u>4→2→3→1</u>"]', 'Trend: <u>Protozoa (4) → Platyhelminthes (2) → Nematoda (3) → Mollusca (1)</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ch22mddni1gq72fdu6gcxbgtt', 'Chemistry', 'JAMB', null, 1987, null, 'Which is the correct set of results for tests conducted respectively on fresh lime and ethanol?', null, '["Add crystals of NaHCO3: Gas evolved / No gas evolved","Test with methyl orange: Turns colourless / No change","Taste: Bitter / Sour","Add a piece of sodium: No gas evolved / H2 evolved"]', 0, 'Lime juice (acid) reacts with NaHCO3 to give CO2; ethanol does not.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which is the correct set of results for tests conducted respectively on fresh lime and ethanol?', '["Add crystals of NaHCO3: Gas evolved / No gas evolved","Test with methyl orange: Turns colourless / No change","Taste: Bitter / Sour","Add a piece of sodium: No gas evolved / H2 evolved"]', '<u>Lime juice reacts with NaHCO3</u> to give CO2; ethanol does not.', '{"bold":[],"italic":[],"underline":["Add crystals of NaHCO3: Gas evolved / No gas evolved"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ch2gugj1hp7n1varedc9jhtoq', 'Chemistry', 'JAMB', null, 1994, null, 'When sodium is added to ethanol, the products are', null, '["sodium hydroxide and water","sodium hydroxide and hydrogen","sodium ethoxide and water","sodium ethoxide and hydrogen"]', 3, '2C2H5OH + 2Na → 2C2H5ONa + H2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When sodium is added to ethanol, the products are', '["sodium hydroxide and water","sodium hydroxide and hydrogen","sodium ethoxide and water","sodium ethoxide and hydrogen"]', '<u>Sodium ethoxide and hydrogen</u>.', '{"bold":[],"italic":[],"underline":["sodium ethoxide and hydrogen"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ch2i0aj0klh9kw98fe3plok03', 'Biology', 'JAMB', null, 1995, null, 'Birds maintain their body temperature with the help of their', null, '["blood which maintains constant temperature","feathers which cover the body","skin which conserves moisture","veins which transport fluid of constant temperature to all body tissues."]', 1, 'feathers which cover the body is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Birds maintain their body temperature with the help of their', '["blood which maintains constant temperature","<u>feathers which cover the body</u>","skin which conserves moisture","veins which transport fluid of constant temperature to all body tissues."]', 'feathers which cover the body is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ch3aklax1v9it70dogk2rgcmi', 'Chemistry', 'JAMB', null, 1985, null, 'The number of atoms of chlorine present in 5.85g of NaCl is [Na=23, Cl=35.5, Avogadro''s Number = 6.02×10²³]', null, '["6.02×10²²","5.85×10²³","6.02×10²³","5.85×10²⁴"]', 2, 'Moles NaCl = 5.85/58.5 = 0.1; atoms Cl = 0.1 × 6.02×10²³ = 6.02×10²². Answer key says 6.02×10²³.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The number of atoms of chlorine present in 5.85g of NaCl is [Na=23, Cl=35.5, Avogadro''s Number = 6.02×10²³]', '["6.02×10²²","5.85×10²³","6.02×10²³","5.85×10²⁴"]', 'Moles NaCl = 0.1; atoms Cl = <u>6.02×10²²</u> (key says 6.02×10²³).', '{"bold":[],"italic":[],"underline":["6.02×10²³"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ch3b2qpr26d2wvyji3s1k0gil', 'Biology', 'JAMB', null, 2000, null, 'The pollutants that contribute to the depletion of the ozone layer in the atmosphere are', null, '["radioactive materials","oxides of sulphur","oxides of carbon","chlorofluorocarbons"]', 3, 'Chlorofluorocarbons can release chlorine radicals that destroy stratospheric ozone.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The pollutants that contribute to the depletion of the ozone layer in the atmosphere are', '["radioactive materials","oxides of sulphur","oxides of carbon","<u>chlorofluorocarbons</u>"]', 'Chlorofluorocarbons can release chlorine radicals that destroy stratospheric ozone.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ch3d3dcbv7rzlz048kv8zq5lm', 'Biology', 'JAMB', null, 2002, null, 'A hormone secreted at IV serves to', null, '["facilitate the development of facial hairs","raise the level of calcium ions in the blood","lower blood glucose level","make the body react to emergencies"]', 2, 'Insulin (from pancreas) lowers blood glucose.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A hormone secreted at IV serves to', '["facilitate the development of facial hairs","raise the level of calcium ions in the blood","lower blood glucose level","make the body react to emergencies"]', '<u>Lowers blood glucose level</u>.', '{"bold":[],"italic":[],"underline":["lower blood glucose level"],"fillBlanks":[]}');
