insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ch3nhi6mtvighiqu425n5goo1', 'Chemistry', 'JAMB', null, 1984, null, 'Which of the following compounds is <b>NOT the correct product</b> formed when the parent metal is heated in air?', null, '["Calcium oxide (CaO)","Sodium oxide (Na2O)","Copper(II) oxide (CuO)","Tri-iron tetroxide (Fe3O4)","Aluminium oxide (Al2O3)"]', 1, 'Sodium forms Na2O2 (peroxide), not Na2O, when heated in air.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following compounds is <b>NOT the correct product</b> formed when the parent metal is heated in air?', '["Calcium oxide (CaO)","Sodium oxide (Na2O)","Copper(II) oxide (CuO)","Tri-iron tetroxide (Fe3O4)","Aluminium oxide (Al2O3)"]', '<u>Sodium forms Na2O2</u>, not Na2O, when heated in air.', '{"bold":["NOT the correct product"],"italic":[],"underline":["Sodium oxide (Na2O)"],"fillBlanks":[]}');
