insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ch4p8ly0e5lybsxrbo4y51otb', 'Government', 'JAMB', null, 2020, null, 'During the Civil War, the major power that expressed moral support for Biafra''s self-determination was', null, '["France","China","the United States","Great Britain"]', 0, 'France expressed moral support for Biafra.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'During the Civil War, the major power that expressed moral support for Biafra''s self-determination was', '["<u>France</u>","China","the United States","Great Britain"]', '<u>France</u>.', '{"bold":[],"italic":[],"underline":["France"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ch4q9jggkyaqyul16oztr28iy', 'Chemistry', 'JAMB', null, 1994, null, 'One mole of a hydrocarbon contains 48g of carbon. If its vapour density is 28, the hydrocarbon is', null, '["an alkane","an alkene","an alkyne","aromatic"]', 1, 'Mr = 56; C = 4 (48g), H = 8 → C4H8 (alkene).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One mole of a hydrocarbon contains 48g of carbon. If its vapour density is 28, the hydrocarbon is', '["an alkane","an alkene","an alkyne","aromatic"]', '<u>C4H8 (alkene)</u>.', '{"bold":[],"italic":[],"underline":["an alkene"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ch4tcubemeebr5p9qcz23v1dd', 'Chemistry', 'JAMB', null, 1994, null, 'Which of the following is <b>TRUE</b> of Le Chatelier''s principle for an exothermic reaction?', null, '["Increase in temperature will cause an increase in equilibrium constant","Increase in temperature will cause a decrease in the equilibrium constant","Addition of catalyst will cause an increase in the equilibrium constant","Addition of catalyst will cause a decrease in the equilibrium constant"]', 1, 'For exothermic, higher T decreases K.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is <b>TRUE</b> of Le Chatelier''s principle for an exothermic reaction?', '["Increase in temperature will cause an increase in equilibrium constant","Increase in temperature will cause a decrease in the equilibrium constant","Addition of catalyst will cause an increase in the equilibrium constant","Addition of catalyst will cause a decrease in the equilibrium constant"]', '<u>Higher T decreases K</u> for exothermic reactions.', '{"bold":["TRUE"],"italic":[],"underline":["Increase in temperature will cause a decrease in the equilibrium constant"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ch548nehl3ldfeiatjoaoeubc', 'General Mathematics', 'JAMB', null, 2020, null, 'Equation of the circle passing through (1, 2), (3, 4), and (5, 6).', null, '["None points are collinear","x² + y² - 6x - 8y + 20 = 0","x² + y² - 4x - 6y + 12 = 0","Not possible"]', 0, 'Points (1,2), (3,4), (5,6) are collinear, so no circle passes through them.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Equation of the circle passing through (1, 2), (3, 4), and (5, 6).', '["None points are collinear","x² + y² - 6x - 8y + 20 = 0","x² + y² - 4x - 6y + 12 = 0","Not possible"]', '<u>None points are collinear</u>.', '{"bold":[],"italic":[],"underline":["None points are collinear"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ch56jvhk20el26vp2b73af48d', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Q.24:30 enjoins Muslims to', null, '["dress properly","be very attentive in prayers","guard against adultery","lower their gaze."]', 3, 'It enjoins lowering the gaze.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Q.24:30 enjoins Muslims to', '["dress properly","be very attentive in prayers","guard against adultery","<u>lower their gaze.</u>"]', '<u>Lower their gaze</u> (Q. 24:30).', '{"bold":[],"italic":[],"underline":["lower their gaze."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ch56usohksl0xs3rdr9x2jecs', 'Government', 'JAMB', null, 2020, null, 'The first Nigerian Permanent Representative to the United Nations was', null, '["Alhaji Yusuf Maitama Sule","General Joseph Garba","Professor Ibrahim Gambari","Chief Samuel Adebo."]', 3, 'Chief Samuel Adebo was the first Nigerian Permanent Representative to the UN.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The first Nigerian Permanent Representative to the United Nations was', '["Alhaji Yusuf Maitama Sule","General Joseph Garba","Professor Ibrahim Gambari","<u>Chief Samuel Adebo.</u>"]', '<u>Chief Samuel Adebo</u>.', '{"bold":[],"italic":[],"underline":["Chief Samuel Adebo."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ch58o0hidekezw32pir9o56m4', 'Chemistry', 'JAMB', null, 1984, null, 'A colourless organic compound X was burnt in excess air to give two colourless and odourless gases, Y and Z, as products. X does not decolorize bromine vapour; Y turns lime water milky while Z gives a blue colour with copper(II) tetraoxosulphate(VI). Compound X is', null, '["an alkene","an alkane","an alkene","tetrachloromethane","Dichloromethane"]', 1, 'X does not decolorize bromine (saturated), so it is an alkane.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A colourless organic compound X was burnt in excess air to give two colourless and odourless gases, Y and Z, as products. X does not decolorize bromine vapour; Y turns lime water milky while Z gives a blue colour with copper(II) tetraoxosulphate(VI). Compound X is', '["an alkene","an alkane","an alkene","tetrachloromethane","Dichloromethane"]', 'X is saturated, so it is <u>an alkane</u>.', '{"bold":[],"italic":[],"underline":["an alkane"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ch59b2i9npmua60sz3qdq2aqz', 'Chemistry', 'JAMB', null, 2019, null, 'Which of the following compounds is composed of Al, Si, O and H? I. Espom salt II. Limestone III. Clay IV. Urea', null, '["I&II","IV only","III only","I&III","I only"]', 2, 'Clay contains Al, Si, O and H.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following compounds is composed of Al, Si, O and H?<br>I. Epsom salt<br>II. Limestone<br>III. Clay<br>IV. Urea', '["I&II","IV only","<u>III only</u>","I&III","I only"]', '<u>Clay</u> contains Al, Si, O and H.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ch5euanc5smaeoqm7pp0hyvov', 'Chemistry', 'JAMB', null, 1989, null, 'The substance ZnO dissolves in sodium hydroxide solution and mineral acid solution to give soluble products in each case. ZnO is therefore referred to as', null, '["an allotropic acid","an atmorphic oxide","a peroxide","a dioxide"]', 1, 'ZnO is amphoteric (reacts with both acid and base).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The substance ZnO dissolves in sodium hydroxide solution and mineral acid solution to give soluble products in each case. ZnO is therefore referred to as', '["an allotropic acid","an amphoteric oxide","a peroxide","a dioxide"]', '<u>ZnO is amphoteric</u>.', '{"bold":[],"italic":[],"underline":["an atmorphic oxide"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ch5hbh3qfturxf0d6u9jua0rx', 'Biology', 'JAMB', null, 1998, null, 'The manufacture of carbohydrates by plants takes place only in', null, '["the leaves","the green stems","chlorophylous parts","flowering plants."]', 2, 'chlorophylous parts is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The manufacture of carbohydrates by plants takes place only in', '["the leaves","the green stems","<u>chlorophylous parts</u>","flowering plants."]', 'chlorophylous parts is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ch5i4vw919ozxa1c5pasc78ic', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve 2^(2x) - 5·2^(x+1) + 24 = 0.', null, '["1, 2","2, log₂6","1, 3","0, 4"]', 1, 'Let y = 2^x: y² - 10y + 24 = 0 → y = 4 or 6 → x = 2 or log₂6.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Solve 2^(2x) - 5·2^(x+1) + 24 = 0.', '["1, 2","2, log₂6","1, 3","0, 4"]', 'Let y = 2^x: y² - 10y + 24 = 0 → y = 4 or 6 → x = 2 or log₂6.', null);
