insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ch5vqzcl6j8i1ectxtz17dij7', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'In Shariah, makruh is an action which is', null, '["encouraged and rewarded","allowed but not rewarded","disallowed and punished","discouraged but not punished."]', 3, 'Makruh is discouraged but not punished.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In Shariah, makruh is an action which is', '["encouraged and rewarded","allowed but not rewarded","disallowed and punished","<u>discouraged but not punished.</u>"]', '<u>Discouraged but not punished</u>.', '{"bold":[],"italic":[],"underline":["discouraged but not punished."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ch5xf4aasxwkiqne4lt0qx3po', 'Government', 'JAMB', null, 2020, null, 'In the local government administration, the traditional ruler is usually', null, '["the chairman of the council","a member of the council","a ceremonial head","the supervisor of projects"]', 2, 'Traditional rulers serve as ceremonial heads.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the local government administration, the traditional ruler is usually', '["the chairman of the council","a member of the council","<u>a ceremonial head</u>","the supervisor of projects"]', '<u>Ceremonial head</u>.', '{"bold":[],"italic":[],"underline":["a ceremonial head"],"fillBlanks":[]}');
