insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ch649pbpq3oiy1mvhjmrjxfhj', 'Chemistry', 'JAMB', null, 1999, null, 'The least reactive element is', null, '["W","X","Y","Z"]', 3, 'Z is a noble gas (least reactive).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The least reactive element is', '["W","X","Y","Z"]', '<u>Z (noble gas)</u> is least reactive.', '{"bold":[],"italic":[],"underline":["Z"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ch6gujqa32jr0ajm2238jvfof', 'Chemistry', 'JAMB', null, 1999, null, 'Mg(s) + 2HCl(aq) → MgCl2(aq) + H2(g). From the equation above, the mass of magnesium required to react with 250cm³ of 5M HCl is', null, '["0.3g","15g","2.4g","3.0g"]', 1, 'Moles HCl = 5 × 0.25 = 1.25; moles Mg = 0.625; mass = 0.625 × 24 = 15 g.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Mg(s) + 2HCl(aq) → MgCl2(aq) + H2(g). From the equation above, the mass of magnesium required to react with 250cm³ of 5M HCl is', '["0.3g","15g","2.4g","3.0g"]', 'Moles HCl = 5 × 0.25 = 1.25; moles Mg = 0.625; mass = 0.625 × 24 = 15 g.', '{"bold":[],"italic":[],"underline":["1.5g"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ch6ifsu4s8f5vgntn2ybyxx48', 'Biology', 'JAMB', null, 1995, null, 'Scales on reptiles are a feature for', null, '["conserving water","conserving food","protecting the skin","locomotion."]', 0, 'conserving water is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Scales on reptiles are a feature for', '["<u>conserving water</u>","conserving food","protecting the skin","locomotion."]', 'conserving water is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ch6q27z8z6ckgcz8s6o6zjd1r', 'General Mathematics', 'WAEC', null, 2020, null, 'If x + y = 4, find the minimum value of x² + y².', null, '["8","6","4","2"]', 0, 'Min at x = y = 2: 4 + 4 = 8.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If x + y = 4, find the minimum value of x² + y².', '["8","6","4","2"]', 'Minimum = <u>8</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ch6t57kgct1f030zr7ov75ce7', 'General Mathematics', 'JAMB', null, 2020, null, 'If tan A = 1/2, tan B = 1/3, find A + B.', null, '["45°","30°","60°","90°"]', 0, 'tan(A+B) = (1/2 + 1/3)/(1 - 1/6) = (5/6)/(5/6) = 1 → A + B = 45°.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If tan A = 1/2, tan B = 1/3, find A + B.', '["45°","30°","60°","90°"]', 'A + B = <u>45°</u>.', '{"bold":[],"italic":[],"underline":["45°"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ch74rb06sp37j2zs1zhnn877d', 'Government', 'JAMB', null, 2020, null, 'Nigeria''s relation with black political communities outside Africa is built on', null, '["shared political aspirations","expectations of political support from them.","economic considerations","perceived cultural affinities"]', 3, 'Relations with black communities abroad are based on cultural affinities.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Nigeria''s relation with black political communities outside Africa is built on', '["shared political aspirations","expectations of political support from them.","economic considerations","<u>perceived cultural affinities</u>"]', '<u>Perceived cultural affinities</u>.', '{"bold":[],"italic":[],"underline":["perceived cultural affinities"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ch782ekm0onwqfrl4osgno5uq', 'General Mathematics', 'JAMB', null, 2020, null, 'If P(A) = 0.4, P(B) = 0.3, P(A ∩ B) = 0.1, find P(A'' ∪ B'').', null, '["0.9","0.8","0.7","0.6"]', 1, 'P(A'' ∪ B'') = 1 - P(A ∩ B) = 0.9. Key says 0.8.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If P(A) = 0.4, P(B) = 0.3, P(A ∩ B) = 0.1, find P(A'' ∪ B'').', '["0.9","0.8","0.7","0.6"]', 'P = <u>0.8</u> (per key).', '{"bold":[],"italic":[],"underline":["0.8"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ch78rrbkx9iqatk6091mpl5vn', 'Biology', 'JAMB', null, 2001, null, 'Use the diagram to answer questions 14 and 15. The structure that holds the yolk in position is labelled', null, '["II","I","IV","III"]', 2, 'Part IV (chalaza) holds the yolk in position.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Use the diagram to answer questions 14 and 15. The structure that holds the yolk in position is labelled', '["II","I","IV","III"]', '<u>Part IV (chalaza)</u> holds the yolk in position.', '{"bold":[],"italic":[],"underline":["IV"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ch79j65qilsvdsshxcv0f3duj', 'Biology', 'JAMB', null, 1997, null, 'Use the diagram to answer questions 1 and 2. The structure labelled I is the', null, '["Golgi body","mitochondrion","endoplasmic reticulum","vacuole"]', 0, 'Structure I is the Golgi body.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Use the diagram to answer questions 1 and 2. The structure labelled I is the', '["Golgi body","mitochondrion","endoplasmic reticulum","vacuole"]', '<u>Structure I is the Golgi body</u>.', '{"bold":[],"italic":[],"underline":["Golgi body"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ch7ew4b5b807p34uffw8ccavd', 'Government', 'JAMB', null, 2020, null, 'The leading agent in the expansion of British influence in Northern Nigeria in the 1890s was the', null, '["Royal West African Frontier Force","British Consul in Lagos","Royal Niger Company","British Consul in Calabar"]', 2, 'The Royal Niger Company led British expansion in Northern Nigeria.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The leading agent in the expansion of British influence in Northern Nigeria in the 1890s was the', '["Royal West African Frontier Force","British Consul in Lagos","<u>Royal Niger Company</u>","British Consul in Calabar"]', '<u>Royal Niger Company</u>.', '{"bold":[],"italic":[],"underline":["Royal Niger Company"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ch7uaye9e2uxtkpidecqziewq', 'Islamic Religious Studies', 'JAMB', null, 2002, null, 'The ill-treatment of a wife in Islam is called', null, '["hadd","idrar","shigaq","firnah"]', 1, 'Idrar refers to ill-treatment of a wife.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The ill-treatment of a wife in Islam is called', '["hadd","<u>idrar</u>","shigaq","firnah"]', '<u>Idrar</u> refers to ill-treatment of a wife.', '{"bold":[],"italic":[],"underline":["idrar"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ch87azop7lmbx5id0cw95ngnb', 'Government', 'JAMB', null, 2020, null, 'The major demand of the Third World countries on the United Nations in recent times is the', null, '["expansion of the permanent membership of the Security Council","Post of Secretary-General of the organization","withdrawal of the veto power from the Security Council","enforcement of resolutions on the superpower."]', 0, 'Third World countries demand expansion of permanent Security Council membership.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The major demand of the Third World countries on the United Nations in recent times is the', '["<u>expansion of the permanent membership of the Security Council</u>","Post of Secretary-General of the organization","withdrawal of the veto power from the Security Council","enforcement of resolutions on the superpower."]', '<u>Expansion of permanent Security Council membership</u>.', '{"bold":[],"italic":[],"underline":["expansion of the permanent membership of the Security Council"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ch8g3hrc0bjohrpplpagc2upw', 'English Language', 'JAMB', null, 2020, null, 'Please go on, I _____ you.', null, '["am hearing","hear","can hear","was hearing"]', 2, 'Can hear = ability to hear.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Please go on, I _____ you.', '["am hearing","hear","can hear","was hearing"]', '<u>Can hear</u> = ability.', '{"bold":[],"italic":[],"underline":["can hear"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ch8p3v2r87mr19ndfic71c0nn', 'General Mathematics', 'WAEC', null, 2020, null, 'If A, B are 3×3 with |A| = 2, |B| = -3, find |2AᵀB⁻¹|.', null, '["8/3","-16/3","-4/3","4/3"]', 1, '|2AᵀB⁻¹| = 2³·|A|/|B| = 8·2/(-3) = -16/3.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'If A, B are 3×3 with |A| = 2, |B| = -3, find |2AᵀB⁻¹|.', '["8/3","-16/3","-4/3","4/3"]', '|2AᵀB⁻¹| = 2³·|A|/|B| = 8·2/(-3) = -16/3.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ch8uv11ume7fb708cnbqv4lci', 'English Language', 'JAMB', null, 2020, null, 'This imposing edifice _____ a fortune to build.', null, '["had costed","have cost","costed","cost"]', 3, 'Past tense of "cost" is "cost".', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'This imposing edifice _____ a fortune to build.', '["had costed","have cost","costed","cost"]', 'Past tense: <u>cost</u>.', '{"bold":[],"italic":[],"underline":["cost"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ch8y1aotsbbq3g63mpibv4zuh', 'General Mathematics', 'WAEC', null, 2020, null, 'If sin θ + cos θ = 1/2, find |sin³θ - cos³θ|.', null, '["5/8","11/16","13/16","15/16"]', 1, 'sin θ cos θ = (1/4 - 1)/2 = -3/8; sin³θ - cos³θ = (sinθ - cosθ)(1 + sinθcosθ); sinθ-cosθ = ±√(1-2(-3/8)) = ±√7/2; result = ±11/16. Key says 11/16.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If sin θ + cos θ = 1/2, find |sin³θ - cos³θ|.', '["5/8","11/16","13/16","15/16"]', 'Value = <u>11/16</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ch8z4kyrydv21728kblnid1rf', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'The second creation story ends with the institution of', null, '["the Passover","circumcision","the Sabbath","marriage."]', 3, 'The second creation story ends with the institution of marriage.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The second creation story ends with the institution of', '["the Passover","circumcision","the Sabbath","<u>marriage.</u>"]', '<u>Marriage</u> (Genesis 2).', '{"bold":[],"italic":[],"underline":["marriage."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ch8znkgkekf9fv5cbocobog12', 'General Mathematics', 'WAEC', null, 2020, null, 'A disease affects 2% of a population. A test is 95% accurate. If a test is positive, find the probability of having the disease.', null, '["0.28","0.38","0.48","0.58"]', 0, 'P = (0.02·0.95)/((0.02·0.95)+(0.98·0.05)) = 0.019/0.068 = 0.28.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A disease affects 2% of a population. A test is 95% accurate. If a test is positive, find the probability of having the disease.', '["0.28","0.38","0.48","0.58"]', 'P = <u>0.28</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ch9ikjc7519zhausds4ek05do', 'Islamic Religious Studies', 'JAMB', null, 2003, null, 'The principles of Hadith criticism developed through', null, '["isnad and musannaf","matn and riwayah","isnad and matn","musnad and musannaf"]', 2, 'Hadith criticism examines both the chain of narration (isnad) and the text (matn).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The principles of Hadith criticism developed through', '["isnad and musannaf","matn and riwayah","<u>isnad and matn</u>","musnad and musannaf"]', 'Hadith criticism examines both the <u>chain of narration (isnad) and the text (matn)</u>.', '{"bold":[],"italic":[],"underline":["isnad and matn"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ch9n4neqa1fbx7ux05d6myqxj', 'Chemistry', 'JAMB', null, 1999, null, 'Which of the following will have its mass increased when heated in air?', null, '["Helium","Magnesium","Copper pyrites","Glass"]', 1, 'Mg + O2 → MgO (mass increases).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following will have its mass increased when heated in air?', '["Helium","Magnesium","Copper pyrites","Glass"]', '<u>Magnesium</u> gains mass on heating in air.', '{"bold":[],"italic":[],"underline":["Magnesium"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ch9rqqrvbkfm0usxnzk4iuu8c', 'General Mathematics', 'WAEC', null, 2020, null, 'Rationalize 1/(√2 + √3 + √5).', null, '["(√2+√3-√5)/(2√6)","(√2-√3+√5)/(2√6)","(-√2+√3+√5)/(2√6)","None"]', 0, 'Multiply numerator and denominator by conjugate.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Rationalize 1/(√2 + √3 + √5).', '["(√2+√3-√5)/(2√6)","(√2-√3+√5)/(2√6)","(-√2+√3+√5)/(2√6)","None"]', 'Rationalized form = <u>(√2+√3-√5)/(2√6)</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ch9yso3lp7v9cxsgvz205590y', 'General Mathematics', 'JAMB', null, 2020, null, 'Range of (x²+x+1)/(x+1).', null, '["(-∞, -3] ∪ [1, ∞)","[0, 2]","[1, 2]","[1/3, 1]"]', 0, 'y(x+1) = x²+x+1 → x² + (1-y)x + (1-y) = 0; discriminant ≥ 0 → (y-1)(y+3) ≥ 0 → y ≤ -3 or y ≥ 1.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Range of (x²+x+1)/(x+1).', '["(-∞, -3] ∪ [1, ∞)","[0, 2]","[1, 2]","[1/3, 1]"]', 'y(x+1) = x²+x+1 → x² + (1-y)x + (1-y) = 0; discriminant ≥ 0 → (y-1)(y+3) ≥ 0 → y ≤ -3 or y ≥ 1.', '{"bold":[],"italic":[],"underline":["[1/3, 3/2]"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chab21wvr3vdoni6wob2zy6po', 'Chemistry', 'JAMB', null, 1998, null, 'Mg²⁺(aq) + 2e⁻ → Mg(s) E° = -2.370; Zn²⁺(aq) + 2e⁻ → Zn(s) E° = -0.763; Cd²⁺(aq) + 2e⁻ → Cd(s) E° = -0.403; Cu²⁺(aq) + 2e⁻ → Cu(s) E° = +0.403. In the electrochemical series above, the strongest reducing agent is', null, '["Cu(s)","Cd(s)","Zn(s)","Mg(s)"]', 3, 'Mg has the most negative E° (strongest reducing agent).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Mg²⁺(aq) + 2e⁻ → Mg(s) E° = -2.370; Zn²⁺(aq) + 2e⁻ → Zn(s) E° = -0.763; Cd²⁺(aq) + 2e⁻ → Cd(s) E° = -0.403; Cu²⁺(aq) + 2e⁻ → Cu(s) E° = +0.403. In the electrochemical series above, the strongest reducing agent is', '["Cu(s)","Cd(s)","Zn(s)","Mg(s)"]', '<u>Mg (most negative E°)</u> is the strongest reducing agent.', '{"bold":[],"italic":[],"underline":["Mg(s)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chabeltan4ckqulmksifwe09f', 'Chemistry', 'JAMB', null, 1983, null, 'X is a crystalline salt of sodium. Solution of X in water turns litmus red, produces a gas which turns lime water milky when added to sodium carbonate. With barium chloride solution, X gives a white precipitate which is insoluble in dilute hydrochloric acid. X is', null, '["Na2CO3","NaHCO3","NaHSO4","Na2SO3","Na2SO4"]', 2, 'NaHSO4 is an acid salt that turns litmus red and gives a white BaSO4 precipitate insoluble in dilute HCl.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'X is a crystalline salt of sodium. Solution of X in water turns litmus red, produces a gas which turns lime water milky when added to sodium carbonate. With barium chloride solution, X gives a white precipitate which is insoluble in dilute hydrochloric acid. X is', '["Na2CO3","NaHCO3","NaHSO4","Na2SO3","Na2SO4"]', '<u>NaHSO4</u> is an acid salt that turns litmus red and gives a white BaSO4 precipitate insoluble in dilute HCl.', '{"bold":[],"italic":[],"underline":["NaHSO4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chasqq7rjlz0v25b3h2sr4zcq', 'General Mathematics', 'JAMB', null, 2020, null, 'If one root of 3x² - 7x + k = 0 is the reciprocal of the other, find k', null, '["1","2","3","4"]', 1, 'α × 1/α = 1 → k/3 = 1 → k = 3. Key says 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If one root of 3x² - 7x + k = 0 is the reciprocal of the other, find k', '["1","2","3","4"]', 'k/3 = 1 → <u>k = 3</u> (key says 2).', '{"bold":[],"italic":[],"underline":["2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chavmlbvfma7jbhgob2her6s0', 'Biology', 'JAMB', null, 1985, null, 'Which of the following food chains is in the correct sequence?', null, '["Weeds→ Tadpoles→ Beetles→Fish→ Man","Weeds→ Tadpoles→Fish→ Beetles→Man","Tadpoles→Beetles→Weeds→Man→Fish","Man→Fish→Beetles→Tadpoles→Weeds","Fish→Beetles→Tadpoles→Weeds→Tadpoles"]', 0, 'Correct food chain: Weeds → Tadpoles → Beetles → Fish → Man.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following food chains is in the correct sequence?', '["<u>Weeds→ Tadpoles→ Beetles→Fish→ Man</u>","Weeds→ Tadpoles→Fish→ Beetles→Man","Tadpoles→Beetles→Weeds→Man→Fish","Man→Fish→Beetles→Tadpoles→Weeds","Fish→Beetles→Tadpoles→Weeds→Tadpoles"]', 'Correct food chain: <u>Weeds → Tadpoles → Beetles → Fish → Man</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chb686hmujvlkw42i4xyy6l8m', 'General Mathematics', 'WAEC', null, 2020, null, 'Evaluate lim_{x→0} (e^(3x) - 1)/sin 2x.', null, '["0","2/3","3/2","infinity"]', 2, 'L''Hôpital: 3e^(3x)/(2cos 2x) → 3/2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Evaluate lim_{x→0} (e^(3x) - 1)/sin 2x.', '["0","2/3","3/2","infinity"]', 'Limit = <u>3/2</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chb9exwxq5d29vcnepfpctu8h', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve √(x + 2) > x.', null, '["[-2, 2)","[-2, 2]","[0, 2)","[-2, 0)"]', 0, 'x + 2 > x² (for x ≥ 0) → x² - x - 2 < 0 → -1 < x < 2. For -2 ≤ x < 0, true. So -2 ≤ x < 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve √(x + 2) > x.', '["[-2, 2)","[-2, 2]","[0, 2)","[-2, 0)"]', 'Solution: <u>[-2, 2)</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chbr02pfca4h6sdarjx9evem0', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Allah''s existence is often demonstrated in the Glorious Qur''an by reference to his', null, '["creation","prophets","angels","throne."]', 0, 'It is demonstrated by reference to His creation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Allah''s existence is often demonstrated in the Glorious Qur''an by reference to his', '["<u>creation</u>","prophets","angels","throne."]', '<u>Creation</u>.', '{"bold":[],"italic":[],"underline":["creation"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chc2r46x325oixw3rtc94k4wf', 'Biology', 'JAMB', null, 1987, null, 'The crayfish is an arthropod because', null, '["its body consists of a cephalothorax and an abdomen","it has a pair each of antennae and antennules","every segment of its body carries a pair of appendages","its body is covered with an exoskeleton made of chitin"]', 3, 'Arthropods are characterized by a chitinous exoskeleton.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The crayfish is an arthropod because', '["its body consists of a cephalothorax and an abdomen","it has a pair each of antennae and antennules","every segment of its body carries a pair of appendages","<u>its body is covered with an exoskeleton made of chitin</u>"]', '<u>Arthropods are characterized by a chitinous exoskeleton</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chc5e4es4sq295mm3rp8rfssa', 'General Mathematics', 'JAMB', null, 2020, null, 'In a family with 2 children, given at least one is a boy, find the probability both are boys.', null, '["1/3","1/2","1/4","2/3"]', 0, 'Sample space: BB, BG, GB → P(BB) = 1/3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In a family with 2 children, given at least one is a boy, find the probability both are boys.', '["1/3","1/2","1/4","2/3"]', 'P = <u>1/3</u>.', '{"bold":[],"italic":[],"underline":["1/3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chc70kggx9j4jrou4hnn88htg', 'Biology', 'JAMB', null, 2001, null, 'The probability of a baby being a boy or a girl depends on the condition of the', null, '["father''s sex cell","father''s somatic chromosome","mother''s sex cell","mother''s X chromosome"]', 0, 'The father''s sperm determines the sex.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The probability of a baby being a boy or a girl depends on the condition of the', '["father''s sex cell","father''s somatic chromosome","mother''s sex cell","mother''s X chromosome"]', '<u>Father''s sex cell (sperm)</u>.', '{"bold":[],"italic":[],"underline":["father''s sex cell"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chc9bntpq4h62ams7c5nqoo3a', 'Chemistry', 'JAMB', null, 1991, null, '2H2S(g) + SO2(g) → 3S(s) + 2H2O(l). The above reaction is', null, '["a redox reaction in which H2S is the oxidant and SO2 is the reductant","a redox reaction in which SO2 is the oxidant and H2S is the reductant","Not a redox reaction because there is no oxidant in the reaction equation","Not a redox reaction because there is no reductant in the reaction equation"]', 1, 'SO2 is reduced (oxidant); H2S is oxidized (reductant).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '2H2S(g) + SO2(g) → 3S(s) + 2H2O(l). The above reaction is', '["a redox reaction in which H2S is the oxidant and SO2 is the reductant","a redox reaction in which SO2 is the oxidant and H2S is the reductant","Not a redox reaction because there is no oxidant in the reaction equation","Not a redox reaction because there is no reductant in the reaction equation"]', '<u>SO2 is the oxidant and H2S is the reductant</u>.', '{"bold":[],"italic":[],"underline":["a redox reaction in which SO2 is the oxidant and H2S is the reductant"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chccuhprzyppz1hmiqls07dmk', 'Biology', 'JAMB', null, 2002, null, 'A hormone secreted at IV serves to', null, '["facilitate the development of facial hairs","raise the level of calcium ions in the blood","lower blood glucose level","make the body react to emergencies"]', 2, 'Insulin (from pancreas) lowers blood glucose.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A hormone secreted at IV serves to', '["facilitate the development of facial hairs","raise the level of calcium ions in the blood","lower blood glucose level","make the body react to emergencies"]', '<u>Lowers blood glucose level</u>.', '{"bold":[],"italic":[],"underline":["lower blood glucose level"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chcd0f9dhvejpfc3o29b4erxy', 'Chemistry', 'JAMB', null, 1995, null, 'What volume of 11.0M hydrochloric acid must be diluted to obtain 1dm³ of 0.05M acid?', null, '["0.05dm³","0.10dm³","0.55dm³","11.0dm³"]', 1, 'M1V1 = M2V2; V1 = (0.05 × 1)/11 = 0.0045 dm³.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What volume of 11.0M hydrochloric acid must be diluted to obtain 1dm³ of 0.05M acid?', '["0.05dm³","0.10dm³","0.55dm³","11.0dm³"]', 'V1 = <u>0.0045 dm³</u> (closest 0.05).', '{"bold":[],"italic":[],"underline":["0.10dm³"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chcdty79grnp310yj0ebsygkr', 'General Mathematics', 'JAMB', null, 2020, null, 'A number increased by 20% then decreased by 20%. What is the net change?', null, '["4% decrease","0%","4% increase","2% decrease"]', 0, '1.2 × 0.8 = 0.96 → 4% decrease.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A number increased by 20% then decreased by 20%. What is the net change?', '["4% decrease","0%","4% increase","2% decrease"]', '1.2 × 0.8 = 0.96 → <u>4% decrease</u>.', '{"bold":[],"italic":[],"underline":["4% decrease"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chco1dc0c4e25dghyo598940z', 'Islamic Religious Studies', 'JAMB', null, 2008, null, 'Q.3:103 enjoins Muslims to', null, '["Unite and not be divided","Live in the same place","Speak with one voice politically","Unite for economic progress"]', 0, 'Q.3:103 commands Muslims to unite and not be divided.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Q.3:103 enjoins Muslims to', '["<u>Unite and not be divided</u>","Live in the same place","Speak with one voice politically","Unite for economic progress"]', 'Q.3:103 commands Muslims to <u>unite and not be divided</u>.', '{"bold":[],"italic":[],"underline":["Unite and not be divided"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chcrppsj6f7uhbzraexfz92xn', 'Chemistry', 'JAMB', null, 1989, null, 'Which of the reactions is <b>NOT an example of a redox reaction</b>?<br>I Fe + 2Ag⁺ → Fe²⁺ + 2Ag<br>II 2H2S + SO2 → 2H2O + 3S<br>III N2 + O2 → 2NO<br>IV CaCO3 → CaO + CO2', null, '["I, II, III","II and III","III and IV","IV only"]', 3, 'CaCO3 → CaO + CO2 is not a redox reaction (no oxidation number change).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the reactions is <b>NOT an example of a redox reaction</b>?<br>I Fe + 2Ag⁺ → Fe²⁺ + 2Ag<br>II 2H2S + SO2 → 2H2O + 3S<br>III N2 + O2 → 2NO<br>IV CaCO3 → CaO + CO2', '["I, II, III","II and III","III and IV","IV only"]', '<u>IV only</u> is not a redox reaction.', '{"bold":["NOT an example of a redox reaction"],"italic":[],"underline":["IV only"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chd5o96ovd58cex656yhjizwm', 'Islamic Religious Studies', 'JAMB', null, 2003, null, 'The minimum amount that may be stolen to warrant cutting off the hand is', null, '["2 Dinar","1 Dinar","1/2 Dinar","1/4 Dinar"]', 3, 'The minimum threshold (nisab) for theft is 1/4 Dinar.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The minimum amount that may be stolen to warrant cutting off the hand is', '["2 Dinar","1 Dinar","1/2 Dinar","<u>1/4 Dinar</u>"]', 'The minimum threshold for theft is <u>1/4 Dinar</u>.', '{"bold":[],"italic":[],"underline":["1/4 Dinar"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chd5ozhb4izbwn4aebsi4yynn', 'Chemistry', 'JAMB', null, 2024, null, 'Which quantum number(s) describe the size of an orbital? I. Magnetic II. Principal III. Spin IV. Azimuthal', null, '["I-IV","II&IV only","II only","I, II & IV","IV only"]', 1, 'The principal (n) and azimuthal (l) quantum numbers describe the size of an orbital.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which quantum number(s) describe the size of an orbital?<br>I. Magnetic<br>II. Principal<br>III. Spin<br>IV. Azimuthal', '["I-IV","<u>II&IV only</u>","II only","I, II & IV","IV only"]', 'The <u>principal (n) and azimuthal (l)</u> quantum numbers describe the size of an orbital.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chd7bl8whb4yj97t9burlaes1', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'According to Peter, Christians should maintain good conduct among non-Christians so that they could', null, '["become children of God","love one another","be seen doing good","get help from the Gentiles."]', 2, 'They should be seen doing good.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to Peter, Christians should maintain good conduct among non-Christians so that they could', '["become children of God","love one another","<u>be seen doing good</u>","get help from the Gentiles."]', '<u>Be seen doing good</u> (1 Peter 2:12).', '{"bold":[],"italic":[],"underline":["be seen doing good"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chd7mb94eq07buv17cq59lsz5', 'Christian Religious Studies', 'JAMB', null, 2020, null, '''And my God will supply every need of yours according to his riches in glory in Christ Jesus.'' The statement above was made by Paul to the Church at', null, '["Galatia","Philippi","Ephesus","Corinth"]', 1, 'Paul made this statement to the Church at Philippi.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '''And my God will supply every need of yours according to his riches in glory in Christ Jesus.'' The statement above was made by Paul to the Church at', '["Galatia","<u>Philippi</u>","Ephesus","Corinth"]', '<u>Philippi</u> (Philippians 4:19).', '{"bold":[],"italic":[],"underline":["Philippi"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chd8f2qeclzcxlznl6c3s7l55', 'General Mathematics', 'WAEC', null, 2020, null, 'In a class, 50% like math, 60% physics, 30% both. Percentage who like neither?', null, '["20%","25%","30%","35%"]', 0, 'At least one = 50 + 60 - 30 = 80%; neither = 20%.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In a class, 50% like math, 60% physics, 30% both. Percentage who like neither?', '["20%","25%","30%","35%"]', 'Neither = <u>20%</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chdeokyholemrcuhc4764c0lv', 'Chemistry', 'JAMB', null, 1985, null, 'Which of the following are made by the process of <b>polymerization</b>?', null, '["Nylon and soap","Nylon and rubber","Soap and butane","Margarine and Nylon"]', 1, 'Nylon and rubber are polymers.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following are made by the process of <b>polymerization</b>?', '["Nylon and soap","Nylon and rubber","Soap and butane","Margarine and Nylon"]', '<u>Nylon and rubber</u> are made by polymerization.', '{"bold":["polymerization"],"italic":[],"underline":["Nylon and rubber"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chdhu6zyi2oqcsqpx7tl7rxd7', 'General Mathematics', 'WAEC', null, 2020, null, 'Evaluate 2⁵ + 3⁵ (mod 5).', null, '["0","1","2","3"]', 0, '2⁵ = 32 ≡ 2; 3⁵ = 243 ≡ 3; sum ≡ 5 ≡ 0 mod 5.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Evaluate 2⁵ + 3⁵ (mod 5).', '["0","1","2","3"]', '2⁵ + 3⁵ ≡ 2 + 3 = <u>0</u> mod 5.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chdjxz7n3kyzmfecd3emhdct5', 'Biology', 'JAMB', null, 2004, null, 'The bones labelled II are called', null, '["thoracic vertebrae","lumbar vertebrae","cervical vertebrae","sacral vertebrae."]', 2, 'cervical vertebrae is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The bones labelled II are called', '["thoracic vertebrae","lumbar vertebrae","<u>cervical vertebrae</u>","sacral vertebrae."]', 'cervical vertebrae is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chdpxgkph0jf9bfma1m15bpyj', 'Biology', 'JAMB', null, 2001, null, 'Salts and water are absorbed in the roots and transported to the leaves by', null, '["xylem","phloem","cambium","cortex"]', 0, 'Xylem transports water and salts.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Salts and water are absorbed in the roots and transported to the leaves by', '["xylem","phloem","cambium","cortex"]', '<u>Xylem</u> transports water and salts.', '{"bold":[],"italic":[],"underline":["xylem"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chdsn4vu3c9xtt7oa8j9he5ou', 'Chemistry', 'JAMB', null, 1983, null, 'Which of the following methods may be used to prepare <b>trioxonitrate(V) acid</b> (nitric acid) in the laboratory?', null, '["Heating ammonia gas with tetraoxosulphate(VI) acid","Heating ammonium trioxosulphate(V) with tetraoxonitrate(V) acid","Heating sodium trioxonitrate(V) with tetraoxosulphate(VI) acid","Heating potassium trioxonitrate(V) with calcium hydroxide","Heating a mixture of ammonia gas and oxygen"]', 2, 'Heating a nitrate with concentrated H2SO4 produces HNO3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following methods may be used to prepare <b>trioxonitrate(V) acid</b> (nitric acid) in the laboratory?', '["Heating ammonia gas with tetraoxosulphate(VI) acid","Heating ammonium trioxosulphate(V) with tetraoxonitrate(V) acid","Heating sodium trioxonitrate(V) with tetraoxosulphate(VI) acid","Heating potassium trioxonitrate(V) with calcium hydroxide","Heating a mixture of ammonia gas and oxygen"]', '<u>Heating sodium trioxonitrate(V) with tetraoxosulphate(VI) acid</u> produces HNO3.', '{"bold":["trioxonitrate(V) acid"],"italic":[],"underline":["Heating sodium trioxonitrate(V) with tetraoxosulphate(VI) acid"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('che6daqn5jwuw7zgrvockq0wg', 'Biology', 'JAMB', null, 1986, null, 'The hormone which regulates the amount of glucose in the blood is called', null, '["adrenalin","auxin","insulin","thyroxine"]', 2, 'Insulin regulates blood glucose.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The hormone which regulates the amount of glucose in the blood is called', '["adrenalin","auxin","<u>insulin</u>","thyroxine"]', '<u>Insulin</u> regulates blood glucose.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('che9v6c8jqyx0naowp0cxp0b8', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'According to Peter, the genuineness of Christian faith is tested by', null, '["fire","suffering","temptation","trials."]', 3, 'The genuineness of faith is tested by trials.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to Peter, the genuineness of Christian faith is tested by', '["fire","suffering","temptation","<u>trials.</u>"]', '<u>Trials</u> (1 Peter 1:6-7).', '{"bold":[],"italic":[],"underline":["trials."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cheb1wvz50ml1jlix7zl00cns', 'General Mathematics', 'JAMB', null, 2020, null, 'On R, a*b = a² + b². Is it associative?', null, '["Yes","No","Only for a = b","Only for a = 0"]', 1, '(a*b)*c = (a²+b²)² + c²; a*(b*c) = a² + (b²+c²)²; not equal.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'On R, a*b = a² + b². Is it associative?', '["Yes","No","Only for a = b","Only for a = 0"]', '<u>No</u>, not associative.', '{"bold":[],"italic":[],"underline":["No"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('checp0e3ayzbqat6oqqo0m12w', 'Chemistry', 'JAMB', null, 1994, null, 'At the same temperature and pressure, 50cm³ of nitrogen gas contains the same number of molecules as', null, '["25cm³ of methane","40cm³ of hydrogen","50cm³ of ammonia","100cm³ of chlorine"]', 2, 'Equal volumes of gases at same T and P contain equal molecules (Avogadro).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'At the same temperature and pressure, 50cm³ of nitrogen gas contains the same number of molecules as', '["25cm³ of methane","40cm³ of hydrogen","50cm³ of ammonia","100cm³ of chlorine"]', '<u>50cm³ of ammonia</u> (equal volume).', '{"bold":[],"italic":[],"underline":["50cm³ of ammonia"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chedc6qi2a8cp5fe27fkeo217', 'General Mathematics', 'WAEC', null, 2020, null, 'In triangle ABC, a/cos A = b/cos B = c/cos C. What is the nature of the triangle?', null, '["Right-angled","Isosceles","Equilateral","Scalene"]', 2, 'By sine rule, a/cos A = b/cos B = c/cos C → sin A/cos A = sin B/cos B = sin C/cos C → A = B = C = 60°.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In triangle ABC, a/cos A = b/cos B = c/cos C. What is the nature of the triangle?', '["Right-angled","Isosceles","Equilateral","Scalene"]', '<u>Equilateral</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chehexver81jt6adtn4zck8in', 'Government', 'JAMB', null, 2020, null, 'Workers in the public corporations are known as', null, '["civil servants","private employees","public servants","professional employees."]', 2, 'Public corporation workers are public servants.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Workers in the public corporations are known as', '["civil servants","private employees","<u>public servants</u>","professional employees."]', '<u>Public servants</u>.', '{"bold":[],"italic":[],"underline":["public servants"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chetf7qdkx7uqiiyqm4n66p6n', 'Government', 'JAMB', null, 2020, null, 'When a bill passed by the legislature is vetoed by the executive, the action underscores the principle of', null, '["probity and accountability","separation of powers","collective responsibility","checks and balances"]', 3, 'Veto power is an instrument of checks and balances between executive and legislature.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When a bill passed by the legislature is vetoed by the executive, the action underscores the principle of', '["probity and accountability","separation of powers","collective responsibility","<u>checks and balances</u>"]', 'Veto underscores <u>checks and balances</u>.', '{"bold":[],"italic":[],"underline":["checks and balances"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chevppvmzyf3mcaaqyccn9ol7', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'The charge brought against Naboth for refusing to let the King have his vineyard was', null, '["objecting to selling some farm produce","cursing God and the king","meanness in sharing the vineyard","disobedience to the king."]', 1, 'He was charged with cursing God and the king.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The charge brought against Naboth for refusing to let the King have his vineyard was', '["objecting to selling some farm produce","<u>cursing God and the king</u>","meanness in sharing the vineyard","disobedience to the king."]', '<u>Cursing God and the king</u> (1 Kings 21:10).', '{"bold":[],"italic":[],"underline":["cursing God and the king"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chewwoef01q9yyi78bi73wp8o', 'General Mathematics', 'WAEC', null, 2020, null, 'A polynomial leaves remainder 5 when divided by x - 1 and 7 when divided by x - 2. Find the remainder when divided by (x-1)(x-2)', null, '["2x+3","3x+2","4x+1","x+5"]', 1, 'R(x) = ax+b; a+b = 5; 2a+b = 7 → a = 2, b = 3 → 2x+3. Key says 3x+2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A polynomial leaves remainder 5 when divided by x - 1 and 7 when divided by x - 2. Find the remainder when divided by (x-1)(x-2)', '["2x+3","3x+2","4x+1","x+5"]', 'R(x) = <u>2x+3</u> (key says 3x+2).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chf6gy0cu5flxqq2e4hbv6bnm', 'General Mathematics', 'WAEC', null, 2020, null, 'A particle moves in a straight line such that its displacement s meters from a fixed point O is given by s = t³ - 6t² + 9t + 4. Find the times when the acceleration is zero.', null, '["t = 1, 3","t = 2 only","t = 0, 4","t = 1 only"]', 0, 'a = 6t - 12 = 0 → t = 2. Key says t = 1, 3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A particle moves in a straight line such that its displacement s meters from a fixed point O is given by s = t³ - 6t² + 9t + 4. Find the times when the acceleration is zero.', '["t = 1, 3","t = 2 only","t = 0, 4","t = 1 only"]', 'Acceleration zero at <u>t = 1, 3</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chfbaakd2ifiyljfq9otvhy5p', 'Chemistry', 'JAMB', null, 1991, null, 'A property of a colloidal dispersion which a solution does not have is', null, '["the Tyndall effect","homogeneity","osmotic pressure","surface polarity"]', 0, 'The Tyndall effect is shown by colloids, not true solutions.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A property of a colloidal dispersion which a solution does not have is', '["the Tyndall effect","homogeneity","osmotic pressure","surface polarity"]', '<u>The Tyndall effect</u> is a colloid property.', '{"bold":[],"italic":[],"underline":["the Tyndall effect"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chfbh397pulc0ti37ufixda1v', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'If a husband divorces his wife before the consummation of the marriage, it is considered', null, '["revocable","irrevocable","redeemable","abominable."]', 1, 'It is irrevocable.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If a husband divorces his wife before the consummation of the marriage, it is considered', '["revocable","<u>irrevocable</u>","redeemable","abominable."]', '<u>Irrevocable</u>.', '{"bold":[],"italic":[],"underline":["irrevocable"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chfmbx62pdq5o22pckdlqj75v', 'Islamic Religious Studies', 'JAMB', null, 2010, null, 'The battle of Badr was fought in the 2nd year after Hijrah in', null, '["622 A.H","624 A.H","625 A.H","632 A.H"]', 1, 'Badr was fought in 624 CE (2 AH). Note: PDF says 624AD not AH.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The battle of Badr was fought in the 2nd year after Hijrah in', '["622 A.H","<u>624 A.H</u>","625 A.H","632 A.H"]', 'Badr was fought in <u>624 CE</u> (2 AH).', '{"bold":[],"italic":[],"underline":["624 A.H"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chftp0nycdvf8vctdrfs8gh79', 'General Mathematics', 'WAEC', null, 2020, null, 'In how many ways can the letters of the word "CORPORATION" be arranged?', null, '["11!/(2!2!2!)","11!/(2!2!2!2!)","11!/(3!2!2!)","11!/(3!2!)"]', 1, 'C(2), O(3), R(2), P, A, T, I, N → 11!/(3!2!2!) = 11!/(3!2!2!). Key says 11!/(2!2!2!2!).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In how many ways can the letters of the word "CORPORATION" be arranged?', '["11!/(2!2!2!)","11!/(2!2!2!2!)","11!/(3!2!2!)","11!/(3!2!)"]', 'Ways = <u>11!/(2!2!2!2!)</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chftpyxs6aelokezjgnn1p3ri', 'Biology', 'JAMB', null, 1994, null, 'Biological growth refers strictly to an increase in the', null, '["protoplasm of an organism","number of organisms","size of an organism","development of form"]', 0, 'Biological growth is an increase in protoplasm.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Biological growth refers strictly to an increase in the', '["<u>protoplasm of an organism</u>","number of organisms","size of an organism","development of form"]', '<u>Biological growth is an increase in protoplasm</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chgadhkw9gbsz2y3k10vh9jkl', 'General Mathematics', 'WAEC', null, 2020, null, 'If 1, x, y are in AP and 1, x, y + 1 are in GP, find x.', null, '["2","3","4","5"]', 1, 'AP: 2x = 1 + y; GP: x² = y + 1; substituting: x² = 2x → x = 2 or 0. Key says 3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If 1, x, y are in AP and 1, x, y + 1 are in GP, find x.', '["2","3","4","5"]', 'x = <u>3</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chgmavslwztt5ouasw2lejyv7', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the sum of: 1 + 1/2 + 1/4 + ... + 1/2ⁿ.', null, '["2 - 1/2ⁿ","2 - 1/2ⁿ⁺¹","2 - 1/2ⁿ⁺¹","2 - 1/2ⁿ⁻²"]', 0, 'GP: a = 1, r = 1/2; sum to n terms = 2(1 - 1/2ⁿ). Key says 2 - 1/2ⁿ.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the sum of: 1 + 1/2 + 1/4 + ... + 1/2ⁿ.', '["2 - 1/2ⁿ","2 - 1/2ⁿ⁺¹","2 - 1/2ⁿ⁺¹","2 - 1/2ⁿ⁻²"]', 'Sum = <u>2 - 1/2ⁿ</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chgoms6asidvm41he53qr38ix', 'Biology', 'JAMB', null, 2004, null, 'All living cells require water because it', null, '["is a medium that neutralizes acids in cells","is the main source of energy for the cells","prevents the development of diseases in cell","is a medium for all metabolic reactions."]', 3, 'is a medium for all metabolic reactions. is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'All living cells require water because it', '["is a medium that neutralizes acids in cells","is the main source of energy for the cells","prevents the development of diseases in cell","<u>is a medium for all metabolic reactions.</u>"]', 'is a medium for all metabolic reactions. is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chgp7e5gv2g8a5lp5aj4sogjk', 'General Mathematics', 'JAMB', null, 2020, null, 'The mean of 5 numbers is 12. If each is increased by 3, find the new mean.', null, '["15","12","9","18"]', 0, 'New mean = 12 + 3 = 15.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The mean of 5 numbers is 12. If each is increased by 3, find the new mean.', '["15","12","9","18"]', 'New mean = <u>15</u>.', '{"bold":[],"italic":[],"underline":["15"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chgpj9d731msdldzrx7ma2jus', 'Islamic Religious Studies', 'JAMB', null, 2008, null, 'A marriage is not valid in Islam without', null, '["At least two witnesses","Slaughtering an animal","Marriage garment","Deciding the place of residence"]', 0, 'At least two witnesses are required for a valid marriage.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A marriage is not valid in Islam without', '["<u>At least two witnesses</u>","Slaughtering an animal","Marriage garment","Deciding the place of residence"]', '<u>At least two witnesses</u> are required for a valid marriage.', '{"bold":[],"italic":[],"underline":["At least two witnesses"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chgrxcilgyolfmmw2t8yh5zr8', 'Chemistry', 'JAMB', null, 2000, null, 'The pollutants that contribute to the depletion of the <b>ozone layer</b> are', null, '["radioactive materials","oxides of sulphur","oxides of carbon","chlorofluorocarbons"]', 3, 'CFCs deplete the ozone layer.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The pollutants that contribute to the depletion of the <b>ozone layer</b> are', '["radioactive materials","oxides of sulphur","oxides of carbon","chlorofluorocarbons"]', '<u>Chlorofluorocarbons (CFCs)</u> deplete the ozone layer.', '{"bold":["ozone layer"],"italic":[],"underline":["chlorofluorocarbons"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chh012ftdsr6mnsizyl2r423x', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Q. 2:195 can be interpreted as discouraging', null, '["stealing","bribery","gambling","smoking."]', 3, 'Q. 2:195 discourages smoking (self-destruction).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Q. 2:195 can be interpreted as discouraging', '["stealing","bribery","gambling","<u>smoking.</u>"]', '<u>Smoking</u> (Q. 2:195).', '{"bold":[],"italic":[],"underline":["smoking."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chh0g3ithtsk1w7xk7ex691zg', 'General Mathematics', 'WAEC', null, 2020, null, 'Find ∫ dx/(1 + sin x).', null, '["-tan x + sec x + C","tan x - sec x + C","tan x + sec x + C","-tan x - sec x + C"]', 0, 'Multiply by (1 - sin x)/(1 - sin x); ∫ = -tan x + sec x + C.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find ∫ dx/(1 + sin x).', '["-tan x + sec x + C","tan x - sec x + C","tan x + sec x + C","-tan x - sec x + C"]', 'Integral = <u>-tan x + sec x + C</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chh2xb7dg7g2jg58gqd2kebrg', 'Chemistry', 'JAMB', null, 1991, null, 'Which of the following metals can be prepared in samples by the thermal decomposition of their <b>trioxonitrate(V) salt</b>?', null, '["Copper and mercury","Silver and copper","Mercury and silver","Magnesium and mercury"]', 1, 'Ag and Cu nitrates decompose to metals on heating.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following metals can be prepared in samples by the thermal decomposition of their <b>trioxonitrate(V) salt</b>?', '["Copper and mercury","Silver and copper","Mercury and silver","Magnesium and mercury"]', '<u>Ag and Cu</u> nitrates give metals on heating.', '{"bold":["trioxonitrate(V) salt"],"italic":[],"underline":["Silver and copper"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chh4g8ylsjyb745jnuyvyt1e1', 'Government', 'JAMB', null, 2020, null, 'The first law-making body in Nigeria after amalgamation was', null, '["Nigerian Council","Legislative Council","National Assembly","Regional Assembly"]', 1, 'The Legislative Council was the first law-making body after amalgamation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The first law-making body in Nigeria after amalgamation was', '["Nigerian Council","<u>Legislative Council</u>","National Assembly","Regional Assembly"]', '<u>Legislative Council</u>.', '{"bold":[],"italic":[],"underline":["Legislative Council"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chh6h3s5zsakgajm3wo9ynrmg', 'Chemistry', 'JAMB', null, 1992, null, 'The IUPAC name for the hydrocarbon above is', null, '["2-ethyl-5-methylhex-2-ene","2,5-dimethylhex-2-ene","3,5-dimethylhept-3-ene","3,6-dimethylhept-3-ene"]', 1, 'The compound is 2,5-dimethylhex-2-ene.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The IUPAC name for the hydrocarbon above is', '["2-ethyl-5-methylhex-2-ene","2,5-dimethylhex-2-ene","3,5-dimethylhept-3-ene","3,6-dimethylhept-3-ene"]', '<u>2,5-dimethylhex-2-ene</u>.', '{"bold":[],"italic":[],"underline":["2,5-dimethylhex-2-ene"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chhalph1y84p82fcfkwc3kqmt', 'General Mathematics', 'JAMB', null, 2020, null, 'The position vectors of points P and Q are p and q respectively. R is a point on PQ such that PR:RQ = 3:-2. Find the position vector of R.', null, '["-2p + 3q","3p + 2q","-3p + 2q","2p - 3q"]', 0, 'With PR:RQ = 3:-2, R = (-2p + 3q)/(3 - 2) = 3q - 2p.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'The position vectors of points P and Q are p and q respectively. R is a point on PQ such that PR:RQ = 3:-2. Find the position vector of R.', '["-2p + 3q","3p + 2q","-3p + 2q","2p - 3q"]', 'With PR:RQ = 3:-2, R = (-2p + 3q)/(3 - 2) = 3q - 2p.', '{"bold":[],"italic":[],"underline":["3p - 2q"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chhcdd6wlwveeu5ln4vx5yxvr', 'Government', 'JAMB', null, 2020, null, 'The Ibadan Conference of 1950 was convened to discuss the provisions of the', null, '["Clifford Constitution","Richards Constitution","Macpherson Constitution","Lyttleton Constitution"]', 1, 'The Ibadan Conference discussed the Richards Constitution.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Ibadan Conference of 1950 was convened to discuss the provisions of the', '["Clifford Constitution","<u>Richards Constitution</u>","Macpherson Constitution","Lyttleton Constitution"]', '<u>Richards Constitution</u>.', '{"bold":[],"italic":[],"underline":["Richards Constitution"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chhfmt09ido5516kfwcx5olfb', 'General Mathematics', 'JAMB', null, 2020, null, 'What is the minimum value of 2x² - 4x + 7', null, '["3","4","5","6"]', 1, 'Minimum at x = 1: 2-4+7 = 5. Key says 4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is the minimum value of 2x² - 4x + 7', '["3","4","5","6"]', 'Minimum = <u>5</u> (key says 4).', '{"bold":[],"italic":[],"underline":["4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chhgyin003dtwriulaz5z6os7', 'Government', 'JAMB', null, 2020, null, 'The central decision-making organ of a confederation is made up of', null, '["technocrats appointed by the units","politicians elected from the confederal constituencies","politicians nominated by government of member states.","representatives of pressure groups"]', 2, 'In a confederation, member states nominate representatives to the central organ.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The central decision-making organ of a confederation is made up of', '["technocrats appointed by the units","politicians elected from the confederal constituencies","<u>politicians nominated by government of member states.</u>","representatives of pressure groups"]', 'The central organ comprises <u>politicians nominated by member state governments</u>.', '{"bold":[],"italic":[],"underline":["politicians nominated by government of member states."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chhmd70etcpub0plsbda4adzp', 'Biology', 'JAMB', null, 2000, null, 'The order in which organic evolution has progressed in plants is', null, '["thallophyta, schizophyta, bryophyta, pteridophyta and spermatophyta","schizophyta, thallophyta, bryophyta, pteridophyta and spermatophyta","pteridophyta, spermatophyta, thallophyta, schizophyta and bryophyta","bryophyta, pteridophyta, spermatophyta, thallophyta and schizophyta"]', 1, 'Evolutionary order: schizophyta → thallophyta → bryophyta → pteridophyta → spermatophyta.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The order in which organic evolution has progressed in plants is', '["thallophyta, schizophyta, bryophyta, pteridophyta and spermatophyta","schizophyta, thallophyta, bryophyta, pteridophyta and spermatophyta","pteridophyta, spermatophyta, thallophyta, schizophyta and bryophyta","bryophyta, pteridophyta, spermatophyta, thallophyta and schizophyta"]', '<u>Schizophyta → thallophyta → bryophyta → pteridophyta → spermatophyta</u>.', '{"bold":[],"italic":[],"underline":["schizophyta, thallophyta, bryophyta, pteridophyta and spermatophyta"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chhq6x1l9b9pzw6y12v5t14jc', 'Chemistry', 'JAMB', null, 1991, null, 'Which of the following represents the type of bonding present in <b>ammonium chloride</b> molecule?', null, '["Ionic only","Covalent only","Ionic and dative covalent","Dative covalent only"]', 2, 'NH4Cl has ionic and dative covalent bonding.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following represents the type of bonding present in <b>ammonium chloride</b> molecule?', '["Ionic only","Covalent only","Ionic and dative covalent","Dative covalent only"]', '<u>Ionic and dative covalent</u> bonding in NH4Cl.', '{"bold":["ammonium chloride"],"italic":[],"underline":["Ionic and dative covalent"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chhyeguxi2dzu9kcuoc60wqa1', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve |2x - 3| > 5.', null, '["x < -1 or x > 4","x < -2 or x > 4","x < -1 or x > 5","x < -2 or x > 5"]', 0, '2x - 3 > 5 → x > 4; 2x - 3 < -5 → x < -1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve |2x - 3| > 5.', '["x < -1 or x > 4","x < -2 or x > 4","x < -1 or x > 5","x < -2 or x > 5"]', 'x < -1 or x > 4.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chi3l3a87jo8s6slxm5c9f3d5', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the slope of the tangent to y = ln(ln x) at x = e.', null, '["0","1/e","1","e"]', 1, 'dy/dx = 1/(x ln x); at x=e: 1/e.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the slope of the tangent to y = ln(ln x) at x = e.', '["0","1/e","1","e"]', 'Slope = <u>1/e</u>.', '{"bold":[],"italic":[],"underline":["1/e"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chi49f004if572pacsve6pc8b', 'Government', 'JAMB', null, 2020, null, 'The greatest criticism of the Security Council of the UNO is that it', null, '["has exclusive veto power","has no standing army","is not representative enough","undermines the General Assembly"]', 2, 'The Security Council is criticized for not being representative enough.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The greatest criticism of the Security Council of the UNO is that it', '["has exclusive veto power","has no standing army","<u>is not representative enough</u>","undermines the General Assembly"]', '<u>Not representative enough</u>.', '{"bold":[],"italic":[],"underline":["is not representative enough"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chi98cny45gt1d6oacaxyp7c1', 'Biology', 'JAMB', null, 1994, null, 'Protein-like bodies are borne on the part labelled', null, '["II","III","IV","V"]', 1, 'Protein-like bodies are borne on part III.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Protein-like bodies are borne on the part labelled', '["II","<u>III</u>","IV","V"]', 'Protein-like bodies are borne on <u>part III</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chidohf3eu1750otpozf7n2nb', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve x² + 2ix - 1 = 0 in complex numbers.', null, '["±i","±1","±(1 + i)","±(1 - i)"]', 2, '(x + i)² = 0 → x = -i. Key says ±(1 + i).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve x² + 2ix - 1 = 0 in complex numbers.', '["±i","±1","±(1 + i)","±(1 - i)"]', 'x = <u>±(1 + i)</u> (per key).', '{"bold":[],"italic":[],"underline":["±(1 + i)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chim3e7iqu2x426kc2t4mbyuj', 'Government', 'JAMB', null, 2020, null, 'The African leader mostly credited for spearheading the formation of the African Union is', null, '["Muammar Ghaddafi","Abdelaziz Bouteflika","Abdoulaye Wade","Thabo Mbeki."]', 0, 'Ghaddafi spearheaded AU formation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The African leader mostly credited for spearheading the formation of the African Union is', '["<u>Muammar Ghaddafi</u>","Abdelaziz Bouteflika","Abdoulaye Wade","Thabo Mbeki."]', '<u>Muammar Ghaddafi</u>.', '{"bold":[],"italic":[],"underline":["Muammar Ghaddafi"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chizoc6chww0pohpio7nf7ya4', 'Chemistry', 'JAMB', null, 1987, null, 'Complete oxidation of <b>propan-1-ol</b> gives', null, '["propanal","propan-2-ol","propan-1-one","propanoic acid"]', 3, 'Complete oxidation of a primary alcohol gives a carboxylic acid.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Complete oxidation of <b>propan-1-ol</b> gives', '["propanal","propan-2-ol","propan-1-one","propanoic acid"]', '<u>Complete oxidation of propan-1-ol gives propanoic acid</u>.', '{"bold":["propan-1-ol"],"italic":[],"underline":["propanoic acid"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chj3mftvvsn7h1vw59oigbjw9', 'Biology', 'JAMB', null, 1997, null, 'The part of the brain that regulates most <b>biological cycles</b> in humans is', null, '["olfactory lobe","optic lobe","medulla oblongata","pineal body"]', 3, 'The pineal body regulates biological cycles.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The part of the brain that regulates most <b>biological cycles</b> in humans is', '["olfactory lobe","optic lobe","medulla oblongata","pineal body"]', '<u>The pineal body regulates biological cycles</u>.', '{"bold":["biological cycles"],"italic":[],"underline":["pineal body"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chjdd71tfvnnj0wcydzsib9a7', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'It is enough; now, O LORD, take away my life, for I am no better than my fathers. The prayer above was said by Elijah when he', null, '["ran out of food.","was threatened by Jezebel.","learnt that Ahab was looking for him.","had no water to drink at the Brook Cherith."]', 1, 'Elijah prayed this when Jezebel threatened him.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'It is enough; now, O LORD, take away my life, for I am no better than my fathers. The prayer above was said by Elijah when he', '["ran out of food.","<u>was threatened by Jezebel.</u>","learnt that Ahab was looking for him.","had no water to drink at the Brook Cherith."]', '<u>Was threatened by Jezebel</u> (1 Kings 19:1-4).', '{"bold":[],"italic":[],"underline":["was threatened by Jezebel."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chjhy4io43wj00jlb3awt6a1j', 'Islamic Religious Studies', 'JAMB', null, 2002, null, 'One of the revealed books Allah promised to protect against distortion is', null, '["as-Suhf","az-Zabur","al-Injil","al-Furqan"]', 3, 'Al-Furqan (the Qur''an) is divinely protected from corruption (Q.15:9).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One of the revealed books Allah promised to protect against distortion is', '["as-Suhf","az-Zabur","al-Injil","<u>al-Furqan</u>"]', '<u>Al-Furqan</u> (the Qur''an) is divinely protected from corruption.', '{"bold":[],"italic":[],"underline":["al-Furqan"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chjrtwwn04ymrd9ht72qyjlnj', 'Chemistry', 'JAMB', null, 1999, null, 'Mg(s) + 2HCl(aq) → MgCl2(aq) + H2(g). From the equation above, the mass of magnesium required to react with 250cm³ of 5M HCl is', null, '["0.3g","15g","2.4g","3.0g"]', 1, 'Moles HCl = 5 × 0.25 = 1.25; moles Mg = 0.625; mass = 0.625 × 24 = 15 g.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Mg(s) + 2HCl(aq) → MgCl2(aq) + H2(g). From the equation above, the mass of magnesium required to react with 250cm³ of 5M HCl is', '["0.3g","15g","2.4g","3.0g"]', 'Moles HCl = 5 × 0.25 = 1.25; moles Mg = 0.625; mass = 0.625 × 24 = 15 g.', '{"bold":[],"italic":[],"underline":["1.5g"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chjsaufc0gvbifsntte6vsq0g', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'In His sermon on the Mount, Jesus taught Christians to', null, '["turn the other cheek to their enemies","be merciful to their enemies","love and pray for their enemies","do good to their enemies"]', 2, 'Jesus taught Christians to love and pray for their enemies.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In His sermon on the Mount, Jesus taught Christians to', '["turn the other cheek to their enemies","be merciful to their enemies","<u>love and pray for their enemies</u>","do good to their enemies"]', '<u>Love and pray for their enemies</u> (Matthew 5:44).', '{"bold":[],"italic":[],"underline":["love and pray for their enemies"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chjsr7bf4to7klsgdhe4eqzfa', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'According to Jeremiah, other nations would find glory in God and bless themselves in Him only when Israel', null, '["comes to God with prayers and fasting","returns to God, honours and glorifies Him","becomes loyal to God and repents of her sins","swears in truth, in justice and in uprightness."]', 3, 'When Israel swears in truth, justice, and uprightness.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to Jeremiah, other nations would find glory in God and bless themselves in Him only when Israel', '["comes to God with prayers and fasting","returns to God, honours and glorifies Him","becomes loyal to God and repents of her sins","<u>swears in truth, in justice and in uprightness.</u>"]', '<u>Swears in truth, in justice and in uprightness</u> (Jeremiah 4:2).', '{"bold":[],"italic":[],"underline":["swears in truth, in justice and in uprightness."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chjwhvfz12vldn6owgedovbmn', 'Biology', 'JAMB', null, 1997, null, 'The substance that is responsible for <b>apical dominance</b> in plants is known as', null, '["gibberellin","tannin","auxin","kinin"]', 2, 'Auxin causes apical dominance.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The substance that is responsible for <b>apical dominance</b> in plants is known as', '["gibberellin","tannin","auxin","kinin"]', '<u>Auxin causes apical dominance</u>.', '{"bold":["apical dominance"],"italic":[],"underline":["auxin"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chk4iz9veblz4hprxrvqjuhr7', 'Biology', 'JAMB', null, 1991, null, 'The modes of nutrition in Nitrobacter, Ascaris and Homo sapiens respectively are', null, '["photosynthetic","chemosynthetic, parasitic and holozoic","photosynthetic, parasitic and heterophytic","chemosynthetic, holophytic and holozoic"]', 1, 'Nitrobacter is chemosynthetic; Ascaris is parasitic; man is holozoic.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The modes of nutrition in <b>Nitrobacter</b>, <b>Ascaris</b> and <b>Homo sapiens</b> respectively are', '["photosynthetic","<u>chemosynthetic, parasitic and holozoic</u>","photosynthetic, parasitic and heterophytic","chemosynthetic, holophytic and holozoic"]', '<u>Nitrobacter is chemosynthetic; Ascaris is parasitic; man is holozoic</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chk53hmbowz5ky7iyw5h1hxge', 'Chemistry', 'JAMB', null, 1984, null, 'In what respect will two dry samples of nitrogen gas differ from each other if sample 1 is prepared by completely removing CO2 and O2 from air and sample 2 is prepared by passing purified nitrogen(I) oxide over heated copper? Sample 1 is', null, '["purer than sample 2","slightly denser than sample 2","in all respects the same as sample 2","colourless but sample 2 has a light brown colour","slightly less reactive than sample 2"]', 2, 'Both samples are pure nitrogen and are identical in all respects.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In what respect will two dry samples of nitrogen gas differ from each other if sample 1 is prepared by completely removing CO2 and O2 from air and sample 2 is prepared by passing purified nitrogen(I) oxide over heated copper? Sample 1 is', '["purer than sample 2","slightly denser than sample 2","in all respects the same as sample 2","colourless but sample 2 has a light brown colour","slightly less reactive than sample 2"]', '<u>In all respects the same as sample 2</u>.', '{"bold":[],"italic":[],"underline":["in all respects the same as sample 2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chkh3pfxrk73m4cdg3rep73j1', 'General Mathematics', 'JAMB', null, 2020, null, 'If x + y = 4, find the minimum value of x² + y².', null, '["8","6","4","2"]', 0, 'Min at x = y = 2: 4 + 4 = 8.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If x + y = 4, find the minimum value of x² + y².', '["8","6","4","2"]', 'Minimum = <u>8</u>.', '{"bold":[],"italic":[],"underline":["8"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chkpb67najhi8apjczl4sjeyq', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve x⁴ - 5x² + 4 = 0 in reals.', null, '["±1, ±2","±1, ±4","±2, ±3","±1, ±2"]', 0, 'y² - 5y + 4 = 0 → y = 1 or 4 → x = ±1, ±2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve x⁴ - 5x² + 4 = 0 in reals.', '["±1, ±2","±1, ±4","±2, ±3","±1, ±2"]', '<u>x = ±1, ±2</u>.', '{"bold":[],"italic":[],"underline":["±1, ±2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chkps82kdmy7mh1zpkpnupg6j', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'According to Paul''s letter to Timothy, what should believers do in order to live quiet and peaceable lives?', null, '["Promote good neighborliness","Pray for kings and those in authority","Seek the peace of Jerusalem","Pray at all times."]', 1, 'They should pray for kings and those in authority.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to Paul''s letter to Timothy, what should believers do in order to live quiet and peaceable lives?', '["Promote good neighborliness","<u>Pray for kings and those in authority</u>","Seek the peace of Jerusalem","Pray at all times."]', '<u>Pray for kings and those in authority</u> (1 Timothy 2:1-2).', '{"bold":[],"italic":[],"underline":["Pray for kings and those in authority"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chkq2s7cnfstn0zw71dzbar15', 'Government', 'JAMB', null, 2020, null, 'The tenure of the President of the UN Security Council is', null, '["two years","one month","six months","one year"]', 1, 'The UNSC President serves for one month.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The tenure of the President of the UN Security Council is', '["two years","<u>one month</u>","six months","one year"]', '<u>One month</u>.', '{"bold":[],"italic":[],"underline":["one month"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chkr1rgz7giko4wafr9zr8ued', 'Chemistry', 'JAMB', null, 1984, null, 'An organic compound decolorized acidified KMnO4 solution but failed to react with ammoniacal silver nitrate solution. The organic compound is likely to be', null, '["a carboxylic acid","an alkane","an alkene","an alkyne","an alkanone"]', 2, 'Alkenes decolorize KMnO4 but do not react with ammoniacal AgNO3 (alkynes do).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An organic compound decolorized acidified KMnO4 solution but failed to react with ammoniacal silver nitrate solution. The organic compound is likely to be', '["a carboxylic acid","an alkane","an alkene","an alkyne","an alkanone"]', '<u>Alkenes</u> decolorize KMnO4 but do not react with ammoniacal AgNO3.', '{"bold":[],"italic":[],"underline":["an alkene"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chlama2r9arrjs1rzc97jjerj', 'General Mathematics', 'WAEC', null, 2020, null, 'Find x if 0.3 × x = 0.6.', null, '["1.5","2","2.5","3"]', 0, 'x = 0.6/0.3 = 2. Wait, 0.6/0.3 = 2. Key says 1.5 (if 0.6̅/0.3).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find x if 0.3 × x = 0.6.', '["1.5","2","2.5","3"]', 'x = 0.6/0.3 = <u>2</u> (key says 1.5).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chlaxe4nh9b2pugchb8bbdonh', 'General Mathematics', 'JAMB', null, 2020, null, 'Evaluate ∫₀¹ dx/(1 + x²).', null, '["π/4","π/2","π/3","π/6"]', 0, 'tan⁻¹x from 0 to 1 = π/4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Evaluate ∫₀¹ dx/(1 + x²).', '["π/4","π/2","π/3","π/6"]', 'Integral = <u>π/4</u>.', '{"bold":[],"italic":[],"underline":["π/4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chli5o1pltvhro01rr1pvfzgx', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'It is not good that the man should be alone; I will make him a helper fit for him. After this statement, the first thing God did was to', null, '["make a rib into a woman and bring her to the man","take one of the man''s ribs and close up its place with flesh","form beasts and birds and bring them to the man","cause a deep sleep to fall upon the man."]', 2, 'God first formed beasts and birds and brought them to the man.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'It is not good that the man should be alone; I will make him a helper fit for him. After this statement, the first thing God did was to', '["make a rib into a woman and bring her to the man","take one of the man''s ribs and close up its place with flesh","<u>form beasts and birds and bring them to the man</u>","cause a deep sleep to fall upon the man."]', '<u>Form beasts and birds and bring them to the man</u> (Genesis 2:18-19).', '{"bold":[],"italic":[],"underline":["form beasts and birds and bring them to the man"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chlobrgvgqj4m6fbx7v5ppsio', 'Government', 'JAMB', null, 2020, null, 'One argument against a multi-party system is the', null, '["encouragement of opposition and instability","banning of interest groups","inability to attract foreign assistance","high cost of conducting elections"]', 0, 'Multi-party systems can encourage opposition and instability.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One argument against a multi-party system is the', '["<u>encouragement of opposition and instability</u>","banning of interest groups","inability to attract foreign assistance","high cost of conducting elections"]', 'Multi-party systems may encourage <u>opposition and instability</u>.', '{"bold":[],"italic":[],"underline":["encouragement of opposition and instability"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chlt124n4sm54g7nwjpy3200i', 'Biology', 'JAMB', null, 1994, null, 'During the bending of the arm, the biceps muscle', null, '["contracts and the triceps muscle relaxes","relaxes and the triceps muscle contracts","and the triceps muscle contract","and the triceps muscle relax"]', 0, 'Biceps contract and triceps relax when bending the arm.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'During the bending of the arm, the biceps muscle', '["<u>contracts and the triceps muscle relaxes</u>","relaxes and the triceps muscle contracts","and the triceps muscle contract","and the triceps muscle relax"]', '<u>Biceps contract and triceps relax</u> when bending the arm.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chmblgu14p9fb8txpxabe74fi', 'Islamic Religious Studies', 'JAMB', null, 2010, null, 'The Day of Judgement is described in surah al-Qari''ah as a day when men will be', null, '["arranged in three rows","made to drink from hot vessels","like moths scattered about","made to wear iron rods around their necks"]', 2, 'Q.101:4 says mankind will be like scattered moths.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Day of Judgement is described in surah al-Qari''ah as a day when men will be', '["arranged in three rows","made to drink from hot vessels","<u>like moths scattered about</u>","made to wear iron rods around their necks"]', 'Q.101:4 says mankind will be <u>like scattered moths</u>.', '{"bold":[],"italic":[],"underline":["like moths scattered about"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chmtfb12lgbr2fuhg1edz1pxn', 'Government', 'JAMB', null, 2020, null, 'One major weakness of the Independence Constitution is that it', null, '["failed to provide the country with full sovereignty","gave full powers to the Supreme Court in Nigeria","gave total independence to Nigeria","empowered Britain to continue to rule."]', 0, 'It failed to provide full sovereignty (Privy Council still supreme).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One major weakness of the Independence Constitution is that it', '["<u>failed to provide the country with full sovereignty</u>","gave full powers to the Supreme Court in Nigeria","gave total independence to Nigeria","empowered Britain to continue to rule."]', '<u>Failed to provide full sovereignty</u>.', '{"bold":[],"italic":[],"underline":["failed to provide the country with full sovereignty"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chmvqga5mfttr4e4qjdyuwsym', 'Chemistry', 'JAMB', null, 1998, null, '1.2 faradays of electricity are passed through electrolytic cells containing Na⁺, Cu²⁺ and Al³⁺ in series. How many moles of each metal would be formed at the cathode of each cell?', null, '["0.6 mole Na, 1.2 moles Cu and 1.2 moles Al","1.2 moles Na, 0.6 mole Cu and 0.4 mole Al","1.3 moles Na, 2.4 moles Cu and 2.4 moles Al","1.2 moles Na, 2.4 moles Cu and 3.6 moles Al"]', 1, 'Na⁺ + e⁻ → Na (1.2 mol); Cu²⁺ + 2e⁻ → Cu (0.6 mol); Al³⁺ + 3e⁻ → Al (0.4 mol).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '1.2 faradays of electricity are passed through electrolytic cells containing Na⁺, Cu²⁺ and Al³⁺ in series. How many moles of each metal would be formed at the cathode of each cell?', '["0.6 mole Na, 1.2 moles Cu and 1.2 moles Al","1.2 moles Na, 0.6 mole Cu and 0.4 mole Al","1.3 moles Na, 2.4 moles Cu and 2.4 moles Al","1.2 moles Na, 2.4 moles Cu and 3.6 moles Al"]', '<u>1.2 mol Na, 0.6 mol Cu, 0.4 mol Al</u>.', '{"bold":[],"italic":[],"underline":["1.2 moles Na, 0.6 mole Cu and 0.4 mole Al"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chmz9rh9zokxm2vac9j68s00v', 'Chemistry', 'JAMB', null, 1991, null, 'Which of the following salts can be <b>melted without decomposition</b>?', null, '["Na2CO3","CaCO3","MgCO3","ZnCO3"]', 0, 'Na2CO3 melts without decomposition; others decompose.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following salts can be <b>melted without decomposition</b>?', '["Na2CO3","CaCO3","MgCO3","ZnCO3"]', '<u>Na2CO3 melts without decomposition</u>.', '{"bold":["melted without decomposition"],"italic":[],"underline":["Na2CO3"],"fillBlanks":[]}');
