insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cho0im681n69uxw022vi21ls5', 'General Mathematics', 'JAMB', null, 2020, null, 'Rationalize 1/(√2 + √3 + √5).', null, '["(√2+√3-√5)/(2√6)","(√2-√3+√5)/(2√6)","(-√2+√3+√5)/(2√6)","None"]', 0, 'Multiply numerator and denominator by conjugate.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Rationalize 1/(√2 + √3 + √5).', '["(√2+√3-√5)/(2√6)","(√2-√3+√5)/(2√6)","(-√2+√3+√5)/(2√6)","None"]', 'Rationalized form = <u>(√2+√3-√5)/(2√6)</u>.', '{"bold":[],"italic":[],"underline":["(√2+√3-√5)/(2√6)"],"fillBlanks":[]}');
