insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cho53gom52sf0g72fzivqal6s', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the identity for a*b = a + b + 3.', null, '["-3","0","3","none"]', 0, 'a*e = a → a+e+3 = a → e = -3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the identity for a*b = a + b + 3.', '["-3","0","3","none"]', 'Identity = <u>-3</u>.', null);
