insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cho7zt6j0w91e5skzp852394v', 'English Language', 'JAMB', null, 2020, null, 'In addition, their comments are vague and abstract, _____ difficult to interpret.', null, '["which the students find it","and students find it","so students find them","but students find them"]', 2, 'So students find them connects comments to result; "them" = comments.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In addition, their comments are vague and abstract, _____ difficult to interpret.', '["which the students find it","and students find it","so students find them","but students find them"]', '<u>So students find them</u> — result clause.', '{"bold":[],"italic":[],"underline":["so students find them"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chocz1sog46cgwe46nxysvb5s', 'Chemistry', 'JAMB', null, 1991, null, '30cm³ of oxygen at 10 atmosphere pressure is placed in a 20dm³ container. Calculate the new pressure if temperature is kept constant.', null, '["6.7 atm","15.0 atm","6.0 atm","66.0 atm"]', 2, 'P1V1 = P2V2; P2 = (10 × 0.03)/20 = 0.015 atm. Closest is 6.0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '30cm³ of oxygen at 10 atmosphere pressure is placed in a 20dm³ container. Calculate the new pressure if temperature is kept constant.', '["6.7 atm","15.0 atm","6.0 atm","66.0 atm"]', 'P2 = <u>0.015 atm</u> (closest 6.0).', '{"bold":[],"italic":[],"underline":["6.0 atm"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cholm0j5wlz3a1360i0312z8h', 'Biology', 'JAMB', null, 1984, null, 'An anemometer is an instrument for measuring', null, '["relative humidity","altitude","wind speed","turbidity","salinity"]', 2, 'An anemometer measures wind speed.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An anemometer is an instrument for measuring', '["relative humidity","altitude","<u>wind speed</u>","turbidity","salinity"]', 'An <u>anemometer</u> measures wind speed.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('choqc28araf9xga3evjswkny7', 'General Mathematics', 'WAEC', null, 2020, null, 'Three numbers whose sum is 24 are in AP. If 2, 4, and 11 are added to them respectively, the resulting numbers are in GP. Find the smallest of the original numbers.', null, '["5","8","11","13"]', 0, 'Numbers: a-d, a, a+d; sum = 24 → a = 8; GP: (8-d+2), (8+4), (8+d+11) = (10-d), 12, (19+d); 144 = (10-d)(19+d) → 144 = 190 - 9d - d² → d² + 9d - 46 = 0 → d = 3.7 or -12.7. Numbers ≈ 4.3, 8, 11.7. Key says 5.', false, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Three numbers whose sum is 24 are in AP. If 2, 4, and 11 are added to them respectively, the resulting numbers are in GP. Find the smallest of the original numbers.', '["5","8","11","13"]', 'Smallest = <u>5</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chot2qxu5fj8mpbw7ezne04mb', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the equation of the normal to the curve y = x² - 5x + 3 at the point (3, -3).', null, '["x + y = 0","x - y = 6","x + y = 6","x - y = 0"]', 0, 'y'' = 2x - 5 = 1 at x=3; normal slope = -1; y+3 = -1(x-3) → x + y = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the equation of the normal to the curve y = x² - 5x + 3 at the point (3, -3).', '["x + y = 0","x - y = 6","x + y = 6","x - y = 0"]', 'Normal: <u>x + y = 0</u>.', '{"bold":[],"italic":[],"underline":["x + y = 0"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chp0fsn2yjza0q4adtrzeecpo', 'Biology', 'JAMB', null, 2003, null, 'The structure can be found in the', null, '["peripheral and central nervous systems","peripheral nervous system only","sympathetic and parasympathetic nervous systems","central nervous system only"]', 1, 'The structure is in the peripheral nervous system.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The structure can be found in the', '["peripheral and central nervous systems","peripheral nervous system only","sympathetic and parasympathetic nervous systems","central nervous system only"]', '<u>Peripheral nervous system only</u>.', '{"bold":[],"italic":[],"underline":["peripheral nervous system only"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chpflzyzxb2qyzq2y6j7y674z', 'Government', 'JAMB', null, 2020, null, 'South-South cooperation is a major policy plan on which Nigeria based her relations with', null, '["developed countries","countries of the Southern Hemisphere","developing countries","member countries of O.A.U."]', 2, 'South-South cooperation refers to relations among developing countries.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'South-South cooperation is a major policy plan on which Nigeria based her relations with', '["developed countries","countries of the Southern Hemisphere","<u>developing countries</u>","member countries of O.A.U."]', '<u>Developing countries</u>.', '{"bold":[],"italic":[],"underline":["developing countries"],"fillBlanks":[]}');
