insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chplimaxc6dl1usfeww7189v4', 'General Mathematics', 'JAMB', null, 2020, null, 'Find a polynomial with roots α+1, β+1, γ+1 if α, β, γ are roots of x³ - 2x² + 3x - 4 = 0', null, '["y³-5y²+10y-8","y³-5y²+9y-8","y³-4y²+8y-6","y³-6y²+11y-6"]', 0, 'Substitute y = x+1 → x = y-1; (y-1)³ - 2(y-1)² + 3(y-1) - 4 = 0 → y³-5y²+10y-8 = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find a polynomial with roots α+1, β+1, γ+1 if α, β, γ are roots of x³ - 2x² + 3x - 4 = 0', '["y³-5y²+10y-8","y³-5y²+9y-8","y³-4y²+8y-6","y³-6y²+11y-6"]', null, '{"bold":[],"italic":[],"underline":["y³-5y²+10y-8"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chpqoymnwz4jzx7o9nnlrxzx9', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve (3x-1)/(x-2) ≥ 2.', null, '["x ≤ -3 or x ≥ 3","x ≥ 3 or x < 2","x ≤ -3 or x > 2","x ≤ 3 or x > 2"]', 2, '(3x-1)/(x-2) - 2 ≥ 0 → (x+3)/(x-2) ≥ 0 → x ≤ -3 or x > 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Solve (3x-1)/(x-2) ≥ 2.', '["x ≤ -3 or x ≥ 3","x ≥ 3 or x < 2","x ≤ -3 or x > 2","x ≤ 3 or x > 2"]', '(3x-1)/(x-2) - 2 ≥ 0 → (x+3)/(x-2) ≥ 0 → x ≤ -3 or x > 2.', null);
