insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chpzux39i1pfmwkm01vxj7gff', 'Chemistry', 'JAMB', null, 1988, null, 'The energy change accompanying the addition of an electron to a gaseous atom is called', null, '["first ionization energy","second ionization energy","electron affinity","electronegativity"]', 2, 'Electron affinity is the energy change when an electron is added to a gaseous atom.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The energy change accompanying the addition of an electron to a gaseous atom is called', '["first ionization energy","second ionization energy","electron affinity","electronegativity"]', '<u>Electron affinity</u> is the energy change on adding an electron.', '{"bold":[],"italic":[],"underline":["electron affinity"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chqyfz4njxnoi4lh2qx8nzew1', 'Government', 'JAMB', null, 2020, null, 'The independent African countries that signed the OAU Charter on May 25, 1963 were', null, '["Togo and Sierra Leone.","Morocco and Angola","Togo and Morocco","Chad and Gambia"]', 2, 'Togo and Morocco were among the signatories.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The independent African countries that signed the OAU Charter on May 25, 1963 were', '["Togo and Sierra Leone.","Morocco and Angola","<u>Togo and Morocco</u>","Chad and Gambia"]', '<u>Togo and Morocco</u>.', '{"bold":[],"italic":[],"underline":["Togo and Morocco"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chrashqaf5j497auxvzymaocv', 'Biology', 'JAMB', null, 2003, null, 'One distinctive feature in the life history of liverworts is that they exhibit', null, '["vegetative reproduction","alternation of generation","sexual reproduction","asexual reproduction"]', 1, 'Liverworts show alternation of generations.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One distinctive feature in the life history of liverworts is that they exhibit', '["vegetative reproduction","alternation of generation","sexual reproduction","asexual reproduction"]', '<u>Alternation of generation</u>.', '{"bold":[],"italic":[],"underline":["alternation of generation"],"fillBlanks":[]}');
