insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chrtiybkdvwzhq0m769ezwgfg', 'Islamic Religious Studies', 'JAMB', null, 2003, null, 'Taharah is a symbolic preparation of the', null, '["soul","body","clothes","place"]', 0, 'Taharah (purification) is a symbolic preparation of the soul.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Taharah is a symbolic preparation of the', '["<u>soul</u>","body","clothes","place"]', '<u>Taharah</u> (purification) is a symbolic preparation of the soul.', '{"bold":[],"italic":[],"underline":["soul"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chrveqva0sa1hxkp703sfutui', 'General Mathematics', 'WAEC', null, 2020, null, 'If one root of 3x² - 7x + k = 0 is the reciprocal of the other, find k', null, '["1","2","3","4"]', 1, 'α × 1/α = 1 → k/3 = 1 → k = 3. Key says 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If one root of 3x² - 7x + k = 0 is the reciprocal of the other, find k', '["1","2","3","4"]', 'k/3 = 1 → <u>k = 3</u> (key says 2).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chs3b81es4fg3ls797fmvfq50', 'General Mathematics', 'WAEC', null, 2020, null, 'For A = [[1, 1], [0, 1]], find Aⁿ.', null, '["[[1, n], [0, 1]]","[[1, 0], [0, 1]]","[[n, 1], [0, 1]]","[[1, 0], [0, 1]]"]', 0, 'By induction, Aⁿ = [[1, n], [0, 1]].', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'For A = [[1, 1], [0, 1]], find Aⁿ.', '["[[1, n], [0, 1]]","[[1, 0], [0, 1]]","[[n, 1], [0, 1]]","[[1, 0], [0, 1]]"]', 'Aⁿ = <u>[[1, n], [0, 1]]</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chsbg08c003wvb4sscpydw1cj', 'General Mathematics', 'JAMB', null, 2020, null, 'If √(1 - x⁶) + √(1 - y⁶) = a(x³ - y³), show that dy/dx = (x²/y²)√((1 - y⁶)/(1 - x⁶)). Then find dy/dx at x = 0, y = 1.', null, '["0","1","infinity","-1"]', 0, 'At x = 0, y = 1, dy/dx = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If √(1 - x⁶) + √(1 - y⁶) = a(x³ - y³), show that dy/dx = (x²/y²)√((1 - y⁶)/(1 - x⁶)). Then find dy/dx at x = 0, y = 1.', '["0","1","infinity","-1"]', 'dy/dx = <u>0</u>.', '{"bold":[],"italic":[],"underline":["0"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chsfd0moi6bgyg7ueekw5hbat', 'Islamic Religious Studies', 'JAMB', null, 2008, null, '[Arabic verse] The Hadith above warns Muslims against charity with', null, '["useless things","ill-gotten wealth","evil intention","cheap things"]', 1, 'Allah is good and accepts only that which is good.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '[Arabic verse] The Hadith above warns Muslims against charity with', '["useless things","<u>ill-gotten wealth</u>","evil intention","cheap things"]', 'Allah is good and accepts only that which is <u>good</u>.', '{"bold":[],"italic":[],"underline":["ill-gotten wealth"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chsolbu633hegzkzn0wbntnt8', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve for x and y: 4ˣ · 2ʸ = 16 · 2³ˣ and 9ˣ⁺ʸ = 27ʸ⁻¹.', null, '["x = 1, y = 5","x = 2, y = -5","x = 2, y = 5","x = -2, y = -5"]', 0, '2x + y = 4 + 3x → y = x + 4; 2x + 2y = 3y - 3 → y = 2x + 3; so x = 1, y = 5.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Solve for x and y: 4ˣ · 2ʸ = 16 · 2³ˣ and 9ˣ⁺ʸ = 27ʸ⁻¹.', '["x = 1, y = 5","x = 2, y = -5","x = 2, y = 5","x = -2, y = -5"]', '2x + y = 4 + 3x → y = x + 4; 2x + 2y = 3y - 3 → y = 2x + 3; so x = 1, y = 5.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chsqejzz69a755k2u6hdi9zpj', 'Government', 'JAMB', null, 2020, null, 'The leaders who spearheaded the transformation of the Organization of African Unity into the African Union are from', null, '["Nigeria, Liberia and Kenya","Algeria, Libya and Morocco.","South Africa, Libya and Zambia","Nigeria, Libya and South Africa"]', 3, 'Nigeria, Libya, and South Africa spearheaded the AU.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The leaders who spearheaded the transformation of the Organization of African Unity into the African Union are from', '["Nigeria, Liberia and Kenya","Algeria, Libya and Morocco.","South Africa, Libya and Zambia","<u>Nigeria, Libya and South Africa</u>"]', '<u>Nigeria, Libya and South Africa</u>.', '{"bold":[],"italic":[],"underline":["Nigeria, Libya and South Africa"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cht2xavz65rliegupr9j5ljyw', 'Islamic Religious Studies', 'JAMB', null, 2002, null, '''People come in search of knowledge, but knowledge does not seek people.'' The statement above was made to Caliph Harun ar-Rashid by', null, '["Imam Abu Hanifah","Imam Malik","Imam Shafi","Imam Hambali"]', 1, 'Imam Malik made this statement to Caliph Harun ar-Rashid.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '''People come in search of knowledge, but knowledge does not seek people.'' The statement above was made to Caliph Harun ar-Rashid by', '["Imam Abu Hanifah","<u>Imam Malik</u>","Imam Shafi","Imam Hambali"]', '<u>Imam Malik</u> made this statement to Caliph Harun ar-Rashid.', '{"bold":[],"italic":[],"underline":["Imam Malik"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cht45rkqdqtbamr2eup5mfqgd', 'General Mathematics', 'WAEC', null, 2020, null, 'Evaluate cos⁴A - sin⁴A at A = 15°.', null, '["√3/2","1/2","1/√2","1"]', 1, 'cos⁴A - sin⁴A = cos 2A = cos 30° = √3/2. Key says 1/2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Evaluate cos⁴A - sin⁴A at A = 15°.', '["√3/2","1/2","1/√2","1"]', 'Value = <u>1/2</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cht4bpm7dch2yxb4g5rbd33gr', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the variance of 2, 4, 6, 8, 10.', null, '["8","6","10","4"]', 0, 'Mean = 6; variance = (16+4+0+4+16)/5 = 40/5 = 8.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the variance of 2, 4, 6, 8, 10.', '["8","6","10","4"]', 'Variance = <u>8</u>.', '{"bold":[],"italic":[],"underline":["8"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chtau5wmbk73ddw45m9q653jl', 'Chemistry', 'JAMB', null, 1992, null, 'Arrange HCl, CH3COOH, C6H5CH3 in order of <b>increasing conductivity</b>.', null, '["HCl, CH3COOH, CH3CH3","C6H5CH3, HCl, CH3COOH","C6H5CH3, CH3COOH, HCl","CH3COOH, C6H5CH3, HCl"]', 2, 'Toluene (non-electrolyte) < acetic acid (weak) < HCl (strong).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Arrange HCl, CH3COOH, C6H5CH3 in order of <b>increasing conductivity</b>.', '["HCl, CH3COOH, CH3CH3","C6H5CH3, HCl, CH3COOH","C6H5CH3, CH3COOH, HCl","CH3COOH, C6H5CH3, HCl"]', '<u>C6H5CH3 < CH3COOH < HCl</u>.', '{"bold":["increasing conductivity"],"italic":[],"underline":["C6H5CH3, CH3COOH, HCl"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chtjz163vpkr3suvt4xs13sob', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the equation of the tangent to the circle x² + y² - 4x + 6y - 12 = 0 at the point (5, 1).', null, '["3x + 4y - 19 = 0","3x - 4y + 19 = 0","3x - 4y - 11 = 0","3x + 4y - 11 = 0"]', 0, 'Center (2, -3); radius to (5,1) slope = 4/3; tangent slope = -3/4; equation: 3x + 4y = 19.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the equation of the tangent to the circle x² + y² - 4x + 6y - 12 = 0 at the point (5, 1).', '["3x + 4y - 19 = 0","3x - 4y + 19 = 0","3x - 4y - 11 = 0","3x + 4y - 11 = 0"]', 'Tangent: <u>3x + 4y - 19 = 0</u>.', '{"bold":[],"italic":[],"underline":["3x + 4y - 19 = 0"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chtw82dfdu4s2t3vy9vvgr61q', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The first male adult to embrace Islam after the commencement of Islamic da''wah in Makkah was', null, '["Umar","Abu Bakr","Uthman","Ali."]', 1, 'Abu Bakr was the first male adult to embrace Islam.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The first male adult to embrace Islam after the commencement of Islamic da''wah in Makkah was', '["Umar","<u>Abu Bakr</u>","Uthman","Ali."]', '<u>Abu Bakr</u>.', '{"bold":[],"italic":[],"underline":["Abu Bakr"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chtzjmallzdphl0olawdu8rwh', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'According to Romans, justification is by faith through', null, '["works of righteousness","redemption in Christ","being filled with the Holy Spirit","obedience to the law."]', 1, 'Justification is through redemption in Christ.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to Romans, justification is by faith through', '["works of righteousness","<u>redemption in Christ</u>","being filled with the Holy Spirit","obedience to the law."]', '<u>Redemption in Christ</u> (Romans 3:24).', '{"bold":[],"italic":[],"underline":["redemption in Christ"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chu3djnr2cdtygc9fzgf6ty0c', 'General Mathematics', 'WAEC', null, 2020, null, 'In triangle PQR, PQ = 8 cm, PR = 7 cm and ∠QPR = 60°. Find the length of QR, correct to two decimal places.', null, '["5.00 cm","7.55 cm","7.81 cm","10.25 cm"]', 2, 'QR² = 64 + 49 - 2(8)(7)cos60° = 113 - 56 = 57; QR = √57 ≈ 7.55. Key says 7.81.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In triangle PQR, PQ = 8 cm, PR = 7 cm and ∠QPR = 60°. Find the length of QR, correct to two decimal places.', '["5.00 cm","7.55 cm","7.81 cm","10.25 cm"]', 'QR = <u>7.81 cm</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chu40is1h95wgirlylbh68sst', 'Chemistry', 'JAMB', null, 2004, null, 'Which of these reagents can confirm the presence of a <b>triple bond</b>?', null, '["Bromine gas","Bromine water","Acidified KMnO4","Copper(I) chloride"]', 3, 'Terminal alkynes react with Cu2Cl2 to give a precipitate.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of these reagents can confirm the presence of a <b>triple bond</b>?', '["Bromine gas","Bromine water","Acidified KMnO4","Copper(I) chloride"]', '<u>Copper(I) chloride</u> confirms terminal triple bonds.', '{"bold":["triple bond"],"italic":[],"underline":["Copper(I) chloride"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chu8mlm78e3n15r3n0sct3oqc', 'Chemistry', 'JAMB', null, 1985, null, 'Ammonia gas is normally dried with', null, '["concentrated sulphuric acid","quicklime","anhydrous calcium chloride","magnesium sulphate"]', 1, 'Quicklime (CaO) is used to dry ammonia.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Ammonia gas is normally dried with', '["concentrated sulphuric acid","quicklime","anhydrous calcium chloride","magnesium sulphate"]', '<u>Quicklime (CaO)</u> dries ammonia.', '{"bold":[],"italic":[],"underline":["quicklime"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chude0cfrpngs0wyzin97p94m', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'One of the sahabah considered most knowledgeable in Tafsir was', null, '["''Ali b. ''Abi Talib","''Ubay b. Ka''ab","''Abdullah b. ''Abbas","Sa''ad b. ''Abi Waqas."]', 2, 'Ibn Abbas was most knowledgeable.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One of the sahabah considered most knowledgeable in Tafsir was', '["''Ali b. ''Abi Talib","''Ubay b. Ka''ab","<u>''Abdullah b. ''Abbas</u>","Sa''ad b. ''Abi Waqas."]', '<u>''Abdullah b. ''Abbas</u>.', '{"bold":[],"italic":[],"underline":["''Abdullah b. ''Abbas"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chue9vlzqiq4hoe5hjj06mlfp', 'General Mathematics', 'WAEC', null, 2020, null, 'Simplify 1/(1+√2) + 1/(√2+√3) + ... + 1/(√99+√100).', null, '["7","8","9","10"]', 1, 'Telescoping: (√2-1) + (√3-√2) + ... + (√100-√99) = 10-1 = 9. Key says 8.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Simplify 1/(1+√2) + 1/(√2+√3) + ... + 1/(√99+√100).', '["7","8","9","10"]', 'Sum = <u>9</u> (key says 8).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chuhyif5l7eqw3g00oukm9g20', 'General Mathematics', 'JAMB', null, 2020, null, 'If tan A = 1/2, tan B = 1/3, find A + B.', null, '["45°","30°","60°","90°"]', 0, 'tan(A+B) = (1/2 + 1/3)/(1 - 1/6) = (5/6)/(5/6) = 1 → A + B = 45°.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If tan A = 1/2, tan B = 1/3, find A + B.', '["45°","30°","60°","90°"]', 'A + B = <u>45°</u>.', '{"bold":[],"italic":[],"underline":["45°"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chuiygzbieqgzg0s8irhtnqsq', 'General Mathematics', 'WAEC', null, 2020, null, 'A man sells at 15% loss. If sold for ₦650 more, gain 10%. Cost price?', null, '["₦2400","₦2600","₦2800","₦3000"]', 1, '0.85C + 650 = 1.10C → 0.25C = 650 → C = 2600.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A man sells at 15% loss. If sold for ₦650 more, gain 10%. Cost price?', '["₦2400","₦2600","₦2800","₦3000"]', 'C = <u>₦2600</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chujdt7a37zsi7rju5zrry5f6', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Saul visited the witch of Endor when he was besieged by the', null, '["Philistines","Amorites","Amalekites","Moabites"]', 0, 'Saul was besieged by the Philistines.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Saul visited the witch of Endor when he was besieged by the', '["<u>Philistines</u>","Amorites","Amalekites","Moabites"]', '<u>Philistines</u> (1 Samuel 28:5-7).', '{"bold":[],"italic":[],"underline":["Philistines"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chunc0qcfsei484m4rthyo48v', 'Chemistry', 'JAMB', null, 1995, null, 'Which of the following samples will <b>react faster</b> with dilute trioxonitrate(V) acid?', null, '["5g of lumps of CaCO3 at 25°C","5g of powdered CaCO3 at 25°C","5g of lumps of CaCO3 at 50°C","5g of powdered CaCO3 at 50°C"]', 3, 'Powdered CaCO3 at 50°C has the highest surface area and temperature.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following samples will <b>react faster</b> with dilute trioxonitrate(V) acid?', '["5g of lumps of CaCO3 at 25°C","5g of powdered CaCO3 at 25°C","5g of lumps of CaCO3 at 50°C","5g of powdered CaCO3 at 50°C"]', '<u>Powdered CaCO3 at 50°C</u> reacts fastest.', '{"bold":["react faster"],"italic":[],"underline":["5g of powdered CaCO3 at 50°C"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chuqjlr11mcrs218gn9l74lj3', 'Biology', 'JAMB', null, 1999, null, 'Substances manufactured by the leaves are transported to other parts of the plant through the', null, '["xylem","companion cells","sieve tubes","cambium"]', 2, 'sieve tubes is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Substances manufactured by the leaves are transported to other parts of the plant through the', '["xylem","companion cells","<u>sieve tubes</u>","cambium"]', 'sieve tubes is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chusmd7cdzsbhl1uhkanixwht', 'Chemistry', 'JAMB', null, 1996, null, 'Which of the following statements is <b>TRUE</b> of the complete hydrolysis of a glyceride by sodium hydroxide?', null, '["3 moles of NaOH are required for each mole of glyceride","3 moles of glycerol are produced","only one mole of soap is formed","Concentrated H2SO4 is essential for the completion of the reaction"]', 0, 'Complete hydrolysis requires 3 moles NaOH.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following statements is <b>TRUE</b> of the complete hydrolysis of a glyceride by sodium hydroxide?', '["3 moles of NaOH are required for each mole of glyceride","3 moles of glycerol are produced","only one mole of soap is formed","Concentrated H2SO4 is essential for the completion of the reaction"]', '<u>3 moles of NaOH</u> per mole of glyceride.', '{"bold":["TRUE"],"italic":[],"underline":["3 moles of NaOH are required for each mole of glyceride"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chuy104uvz4jkpuiboj89hf3x', 'General Mathematics', 'JAMB', null, 2020, null, 'The angles of a triangle are in the ratio 1:2:3. Find the ratio of the sides opposite these angles.', null, '["1:2:3","1:√3:2","1:√3:√2","√2:√3:1"]', 1, 'Angles 30°, 60°, 90°; sides ratio = 1:√3:2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The angles of a triangle are in the ratio 1:2:3. Find the ratio of the sides opposite these angles.', '["1:2:3","1:√3:2","1:√3:√2","√2:√3:1"]', 'Sides ratio = <u>1:√3:2</u>.', '{"bold":[],"italic":[],"underline":["1:√3:2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chv06ojp4thc4xj9j9vqh0o3y', 'Chemistry', 'JAMB', null, 1994, null, 'In an electrolytic set-up to protect iron from corrosion, the iron is', null, '["made the cathode","made the anode","used with a metal of lower electropositive potential","initially coated with tin"]', 0, 'Iron is made the cathode (cathodic protection).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In an electrolytic set-up to protect iron from corrosion, the iron is', '["made the cathode","made the anode","used with a metal of lower electropositive potential","initially coated with tin"]', '<u>Iron is made the cathode</u>.', '{"bold":[],"italic":[],"underline":["made the cathode"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chvb8vh6fs3xpph882o1r102c', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the maximum and minimum values of 12 sin x + 5 cos x + 7.', null, '["Max 24, Min -10","Max 20, Min -6","Max 18, Min -4","Max 14, Min 0"]', 0, 'Max = 13 + 7 = 20; min = -13 + 7 = -6. Key says max 24, min -10.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the maximum and minimum values of 12 sin x + 5 cos x + 7.', '["Max 24, Min -10","Max 20, Min -6","Max 18, Min -4","Max 14, Min 0"]', 'Max = <u>24</u>, Min = <u>-10</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chvlejakak2b8nl2ihzq05fcc', 'Islamic Religious Studies', 'JAMB', null, 2003, null, 'The main emphasis of Hadith 19 of an-Nawawi is that one should', null, '["give unflinching support to the authority","have strong faith in Allah","recognize Allah as the creator of the universe","recognize the importance of one''s community"]', 1, 'Hadith 19 emphasizes having strong faith in Allah and seeking His protection.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The main emphasis of Hadith 19 of an-Nawawi is that one should', '["give unflinching support to the authority","<u>have strong faith in Allah</u>","recognize Allah as the creator of the universe","recognize the importance of one''s community"]', 'Hadith 19 emphasizes <u>having strong faith in Allah</u>.', '{"bold":[],"italic":[],"underline":["have strong faith in Allah"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chvu3gew8vljjkr0q7srfo9b2', 'Biology', 'JAMB', null, 1997, null, 'Use the diagram to answer questions 1 and 2. The structure labelled I is the', null, '["Golgi body","mitochondrion","endoplasmic reticulum","vacuole"]', 0, 'Structure I is the Golgi body.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Use the diagram to answer questions 1 and 2. The structure labelled I is the', '["Golgi body","mitochondrion","endoplasmic reticulum","vacuole"]', '<u>Structure I is the Golgi body</u>.', '{"bold":[],"italic":[],"underline":["Golgi body"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chvyxtmovqzwgy61g8tp6td63', 'Islamic Religious Studies', 'JAMB', null, 2003, null, 'The <b>8th day</b> of Dhul hijjah is called Yaum', null, '["Arafah","Tasua","Ashura","at-Tarwiyah"]', 3, 'The 8th of Dhul Hijjah is Yaum at-Tarwiyah.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The <b>8th day</b> of Dhul hijjah is called Yaum', '["Arafah","Tasua","Ashura","<u>at-Tarwiyah</u>"]', 'The 8th of Dhul Hijjah is <u>Yaum at-Tarwiyah</u>.', '{"bold":["8th day"],"italic":[],"underline":["at-Tarwiyah"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chw94zsaki3pbqoo2nffszwhl', 'General Mathematics', 'WAEC', null, 2020, null, 'A random variable X has mean 5 and variance 4. Find E(X²).', null, '["25","29","33","37"]', 1, 'E(X²) = Var(X) + (E(X))² = 4 + 25 = 29.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A random variable X has mean 5 and variance 4. Find E(X²).', '["25","29","33","37"]', 'E(X²) = <u>29</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chwb3ttu5g8terp3dfnk15ozy', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The most hateful of the permissible things in the sight of Allah is', null, '["mahr","iddah","fasad","talaq."]', 3, 'Talaq (divorce) is the most hateful permissible thing.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The most hateful of the permissible things in the sight of Allah is', '["mahr","iddah","fasad","<u>talaq.</u>"]', '<u>Talaq</u>.', '{"bold":[],"italic":[],"underline":["talaq."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chwh2bgt6tft4iwprwtw5dsxr', 'English Language', 'JAMB', null, 2020, null, 'I was still sleeping when the national news _____ this morning.', null, '["were broadcast","was broadcast","were broadcasted","was broadcasted"]', 1, 'News is singular → "was broadcast".', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'I was still sleeping when the national news _____ this morning.', '["were broadcast","was broadcast","were broadcasted","was broadcasted"]', 'News is singular → <u>was broadcast</u>.', '{"bold":[],"italic":[],"underline":["was broadcast"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chwrkc0qpa3fyx3o2r10wk8u5', 'Government', 'JAMB', null, 2020, null, 'An electoral system in which parties are assigned seats in the parliament according to votes cast is', null, '["absolute majority","simple majority","proportional representation","indirect election."]', 2, 'Proportional representation assigns seats based on votes.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An electoral system in which parties are assigned seats in the parliament according to votes cast is', '["absolute majority","simple majority","<u>proportional representation</u>","indirect election."]', '<u>Proportional representation</u>.', '{"bold":[],"italic":[],"underline":["proportional representation"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chwtwovqfq2h14vory5yybpc5', 'English Language', 'JAMB', null, 2020, null, 'The principal said he _____ the visitors that day that he _____ exhausted.', null, '["had been having / felt","has been having / feels","was having / feels","is having / felt"]', 2, 'Was having … feels — best tense sequence for reported speech among options.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The principal said he _____ the visitors that day that he _____ exhausted.', '["had been having / felt","has been having / feels","was having / feels","is having / felt"]', '<u>Was having / feels</u>.', '{"bold":[],"italic":[],"underline":["was having / feels"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chwvdtvy5vxwalir14sqgxst8', 'Biology', 'JAMB', null, 2004, null, 'The most common characteristic of the fungal hyphae is the possession of', null, '["cell-like partitions formed by cross-walls","cell-like compartments with one nucleus each","a multicellular mycelium in the substrate","cell walls that are both rigid and chitinous Use the diagram below to answer question 32 and 33."]', 3, 'cell walls that are both rigid and chitinous Use the diagram below to answer question 32 and 33. is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The most common characteristic of the fungal hyphae is the possession of', '["cell-like partitions formed by cross-walls","cell-like compartments with one nucleus each","a multicellular mycelium in the substrate","<u>cell walls that are both rigid and chitinous Use the diagram below to answer question 32 and 33.</u>"]', 'cell walls that are both rigid and chitinous Use the diagram below to answer question 32 and 33. is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chwx3wrmkrfsg2avoah1jzbdi', 'Biology', 'JAMB', null, 1989, null, 'Which of the following characteristics is common to Amoeba and Paramecium?', null, '["Oral groove","Trichocyst","Contractile vacuole","Cilia"]', 2, 'Both Amoeba and Paramecium have contractile vacuoles.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following characteristics is common to <b>Amoeba</b> and <b>Paramecium</b>?', '["Oral groove","Trichocyst","<u>Contractile vacuole</u>","Cilia"]', 'Both Amoeba and Paramecium have <u>contractile vacuoles</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chwxyfa2mg2dvtsel1sj29jnd', 'Government', 'JAMB', null, 2020, null, 'Capitalism is a system of economic organization based on', null, '["a mixed economy that takes all interest into consideration","individual ownership of the means of production","very fair distribution of the means of production","trading among people who own and control their items of trade"]', 1, 'Capitalism is based on individual ownership of production means.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Capitalism is a system of economic organization based on', '["a mixed economy that takes all interest into consideration","<u>individual ownership of the means of production</u>","very fair distribution of the means of production","trading among people who own and control their items of trade"]', '<u>Individual ownership of the means of production</u>.', '{"bold":[],"italic":[],"underline":["individual ownership of the means of production"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chwyp4b8gvri1g5vv4er1w3kc', 'Biology', 'JAMB', null, 1987, null, 'The vitamin which is important in the formation of the retina pigments is', null, '["vitamin A","vitamin B","vitamin C","vitamin D"]', 0, 'Vitamin A is important for retina pigments.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The vitamin which is important in the formation of the <b>retina pigments</b> is', '["<u>vitamin A</u>","vitamin B","vitamin C","vitamin D"]', '<u>Vitamin A</u> is important for retina pigments.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chxonbfqd2epa6l92cy5qp1br', 'General Mathematics', 'JAMB', null, 2020, null, 'If dy/dx = e^(2x) + cos 3x and y = 0 when x = 0, find y.', null, '["e^(2x)/2 + sin 3x/3 - 1/2","e^(2x)/2 + sin 3x/3 + 1/2","e^(2x)/2 - sin 3x/3 - 1/2","e^(2x)/2 - sin 3x/3 + 1/2"]', 0, 'y = e^(2x)/2 + sin 3x/3 + C; C = -1/2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If dy/dx = e^(2x) + cos 3x and y = 0 when x = 0, find y.', '["e^(2x)/2 + sin 3x/3 - 1/2","e^(2x)/2 + sin 3x/3 + 1/2","e^(2x)/2 - sin 3x/3 - 1/2","e^(2x)/2 - sin 3x/3 + 1/2"]', 'y = <u>e^(2x)/2 + sin 3x/3 - 1/2</u>.', '{"bold":[],"italic":[],"underline":["e^(2x)/2 + sin 3x/3 - 1/2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chxp6ngy8de4rnpiz9jgc6h2p', 'Chemistry', 'JAMB', null, 1993, null, 'NaCl(s) + H2SO4(l) → HCl(g) + NaHSO4(s). In the reaction above, H2SO4 behaves as', null, '["a strong acid","an oxidizing agent","a good solvent","a dehydrating agent"]', 0, 'H2SO4 acts as a strong acid, displacing HCl.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'NaCl(s) + H2SO4(l) → HCl(g) + NaHSO4(s). In the reaction above, H2SO4 behaves as', '["a strong acid","an oxidizing agent","a good solvent","a dehydrating agent"]', '<u>H2SO4 acts as a strong acid</u>.', '{"bold":[],"italic":[],"underline":["a strong acid"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chxr4b32qqrl7stp9psjof0iy', 'Government', 'JAMB', null, 2020, null, 'An elected legislator in a presidential system can lose his seat by', null, '["a vote of no confidence","impeachment","cross-carpeting","recall"]', 3, 'Recall removes an elected legislator.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An elected legislator in a presidential system can lose his seat by', '["a vote of no confidence","impeachment","cross-carpeting","<u>recall</u>"]', '<u>Recall</u>.', '{"bold":[],"italic":[],"underline":["recall"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chy4c8zbi89gatkuy7ggtn9sg', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'According to Paul, before his conversion, he persecuted the church violently to', null, '["destroy it","have it conform to the law","make it desirable to the Gentiles","purge it."]', 0, 'He persecuted the church to destroy it.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to Paul, before his conversion, he persecuted the church violently to', '["<u>destroy it</u>","have it conform to the law","make it desirable to the Gentiles","purge it."]', '<u>Destroy it</u> (Galatians 1:13).', '{"bold":[],"italic":[],"underline":["destroy it"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chyg6f2u2cvap9676aags8prs', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The messenger of Allah sent to the people of Thamud was', null, '["Isa (A.S)","Musa (A.S)","Hud (A.S)","Salih (A.S)."]', 3, 'Salih was sent to Thamud.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The messenger of Allah sent to the people of Thamud was', '["Isa (A.S)","Musa (A.S)","Hud (A.S)","<u>Salih (A.S).</u>"]', '<u>Salih (A.S)</u> (Q. 7:73).', '{"bold":[],"italic":[],"underline":["Salih (A.S)."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chyt1c8rzx949jyms2aonqxtb', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve √(x+2) > x.', null, '["[-2, 2)","[-2, 2]","[0, 2)","[-2, 0)"]', 0, 'x+2 > x² and x+2 ≥ 0 → x²-x-2 < 0 → -1 < x < 2, and x ≥ -2 → [-2, 2) covers. But also need √(x+2) > x for x<0. So [-2, 2).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve √(x+2) > x.', '["[-2, 2)","[-2, 2]","[0, 2)","[-2, 0)"]', '<u>x ∈ [-2, 2)</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chyw3jn020lm2g9elwgmnfubj', 'Government', 'JAMB', null, 2020, null, 'Associations whose main interest is to influence public policies without having to capture power are', null, '["communal groups.","trade unions","political parties","pressure groups"]', 3, 'Pressure groups influence policy without capturing power.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Associations whose main interest is to influence public policies without having to capture power are', '["communal groups.","trade unions","political parties","<u>pressure groups</u>"]', '<u>Pressure groups</u>.', '{"bold":[],"italic":[],"underline":["pressure groups"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chyyozy280es95h9cgu48j576', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the base b given that: 44_b = 61_(b+1).', null, '["5","6","7","8"]', 1, '4b + 4 = 6(b+1) + 1 = 6b + 7 → 2b = -3 → b = -1.5. No valid solution. Key says 6.', false, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Find the base b given that: 44_b = 61_(b+1).', '["5","6","7","8"]', '4b + 4 = 6b + 7 → <u>b = -1.5</u> (invalid, key says 6).', '{"bold":[],"italic":[],"underline":["6"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chzshre8cpd85cy6xdyqbggy8', 'Islamic Religious Studies', 'JAMB', null, 2011, null, 'The victory of the Roman Empire over the Persian Empire after the Persians had defeated the Romans as stated in the Glorious Qur''an (Q.30:2-3) is an evidence of the', null, '["beauty of the words of the Glorious Qur''an","historical nature of the Glorious Qur''an","simplicity of the wordings of the Glorious Qur''an","authenticity of the Glorious Qur''an"]', 3, 'Q.30:2-3 predicted a future event, proving the Qur''an''s authenticity.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The victory of the Roman Empire over the Persian Empire after the Persians had defeated the Romans as stated in the Glorious Qur''an (Q.30:2-3) is an evidence of the', '["beauty of the words of the Glorious Qur''an","historical nature of the Glorious Qur''an","simplicity of the wordings of the Glorious Qur''an","<u>authenticity of the Glorious Qur''an</u>"]', 'Q.30:2-3 <u>predicted a future event</u>, proving the Qur''an''s authenticity.', '{"bold":[],"italic":[],"underline":["authenticity of the Glorious Qur''an"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chzx9ddl6shux1v0wn4b6yy2l', 'General Mathematics', 'WAEC', null, 2020, null, 'Two dice are rolled. Sum is 8. Find the probability one die shows a 3.', null, '["2/5","1/2","2/7","3/8"]', 0, 'Sum 8: (2,6),(3,5),(4,4),(5,3),(6,2); one die 3: (3,5),(5,3) → 2/5.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Two dice are rolled. Sum is 8. Find the probability one die shows a 3.', '["2/5","1/2","2/7","3/8"]', 'P = <u>2/5</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('chzzkztnthjzxg1480ttz1gcj', 'Chemistry', 'JAMB', null, 1998, null, 'nCH2=CH2 → (initiator) → -[CH2-CH2]n-. The above equation represents the manufacture of', null, '["rubber","polythene","polystyrene","butane"]', 1, 'Polymerization of ethene gives polythene.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'nCH2=CH2 → (initiator) → -[CH2-CH2]n-. The above equation represents the manufacture of', '["rubber","polythene","polystyrene","butane"]', '<u>Polythene</u> is manufactured.', '{"bold":[],"italic":[],"underline":["polythene"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ci08v3wadzuk60bbsg0y7zj72', 'General Mathematics', 'JAMB', null, 2020, null, 'If x² + y² = 25 and xy = 12, find x - y.', null, '["±1","±2","±3","±4"]', 0, '(x-y)² = 25 - 24 = 1 → x - y = ±1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If x² + y² = 25 and xy = 12, find x - y.', '["±1","±2","±3","±4"]', 'x - y = <u>±1</u>.', '{"bold":[],"italic":[],"underline":["±1"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ci0gi72c5h0ue1h98n0dqkdd8', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'The Last Supper took place during the Passover on the first day of', null, '["the week","unleavened bread","abstinence from blood","the month."]', 1, 'It was on the first day of Unleavened Bread.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Last Supper took place during the Passover on the first day of', '["the week","<u>unleavened bread</u>","abstinence from blood","the month."]', '<u>Unleavened bread</u> (Mark 14:12).', '{"bold":[],"italic":[],"underline":["unleavened bread"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ci0gonbno0q9cm6m9kg2fx763', 'Biology', 'JAMB', null, 1989, null, 'Viruses are considered to be living organisms because they', null, '["possess transmittable characters","move from one place to another","respond to stimulation","ingest food materials"]', 0, 'Viruses possess transmittable characters.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Viruses are considered to be living organisms because they', '["<u>possess transmittable characters</u>","move from one place to another","respond to stimulation","ingest food materials"]', '<u>Viruses possess transmittable characters</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ci0jc2jhyriiw07ft78u500fi', 'Biology', 'JAMB', null, 1992, null, 'Fossil records found in sedimentary rocks offer some explanation for the theory of evolution because', null, '["the deposits have remains of organisms characteristic of when they were formed","different strata have remains of organisms of the same kind","only organisms with strong parts are fossilized","most animals and plant fossils bear little resemblance to present day living specimens"]', 0, 'Fossil deposits show organisms characteristic of their time.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Fossil records found in sedimentary rocks offer some explanation for the theory of evolution because', '["<u>the deposits have remains of organisms characteristic of when they were formed</u>","different strata have remains of organisms of the same kind","only organisms with strong parts are fossilized","most animals and plant fossils bear little resemblance to present day living specimens"]', '<u>Fossil deposits show organisms characteristic of their time</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ci0m1has0a6r4ybr6fmu85coo', 'Christian Religious Studies', 'JAMB', null, 2020, null, '...Behold, your king is coming to you, humble, and mounted on an ass... The prophecy in the statement above was fulfilled during Jesus''', null, '["triumphal entry","baptism by John","birth in a manger","transfiguration"]', 0, 'It was fulfilled during the triumphal entry.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '...Behold, your king is coming to you, humble, and mounted on an ass... The prophecy in the statement above was fulfilled during Jesus''', '["<u>triumphal entry</u>","baptism by John","birth in a manger","transfiguration"]', '<u>Triumphal entry</u> (Matthew 21:5).', '{"bold":[],"italic":[],"underline":["triumphal entry"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ci0n0m573dujnvvko8imn9gb3', 'General Mathematics', 'WAEC', null, 2020, null, 'In a class, 50% like math, 60% physics, 30% both. Percentage who like neither?', null, '["20%","25%","30%","35%"]', 0, 'At least one = 50 + 60 - 30 = 80%; neither = 20%.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In a class, 50% like math, 60% physics, 30% both. Percentage who like neither?', '["20%","25%","30%","35%"]', 'Neither = <u>20%</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ci0onmk2lfz7ufserr0xtjl1c', 'Chemistry', 'JAMB', null, 1995, null, 'Coal fire should not be used in poorly ventilated rooms because', null, '["of the accumulation of CO2 which causes deep sleep","it is usually too hot","of the accumulation of CO which causes suffocation","it removes most of the gases in the room"]', 2, 'CO from incomplete combustion causes suffocation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Coal fire should not be used in poorly ventilated rooms because', '["of the accumulation of CO2 which causes deep sleep","it is usually too hot","of the accumulation of CO which causes suffocation","it removes most of the gases in the room"]', '<u>CO accumulation causes suffocation</u>.', '{"bold":[],"italic":[],"underline":["of the accumulation of CO which causes suffocation"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ci0z1xugo1jk3xzt2f7ykuzbe', 'General Mathematics', 'WAEC', null, 2020, null, 'In a class, 15 pass math, 12 pass physics, 8 pass both, 5 fail both. What is the total?', null, '["24","25","26","27"]', 1, 'At least one = 15+12-8 = 19; total = 19+5 = 24. Key says 25.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In a class, 15 pass math, 12 pass physics, 8 pass both, 5 fail both. What is the total?', '["24","25","26","27"]', 'Total = <u>25</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ci1elly4ekcceywyudjkcgrye', 'Government', 'JAMB', null, 2020, null, 'The unrestrained power of the state over its citizens is underlined by', null, '["sovereign","nationalism","self-determination","patriotism"]', 0, 'Sovereignty underlines the state''s unrestrained power.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The unrestrained power of the state over its citizens is underlined by', '["<u>sovereign</u>","nationalism","self-determination","patriotism"]', '<u>Sovereign</u>.', '{"bold":[],"italic":[],"underline":["sovereign"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ci1isr1jtz1fzgi2bp3z9uoty', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Father Abraham, have mercy upon me, and send Lazarus ... Abraham could not grant the rich man''s request above because', null, '["his dogs used to lick Lazarus'' sores.","he had no pity on the rich man.","there was a chasm between them.","the rich man lived in luxury while on earth."]', 2, 'There was a great chasm between them.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Father Abraham, have mercy upon me, and send Lazarus ... Abraham could not grant the rich man''s request above because', '["his dogs used to lick Lazarus'' sores.","he had no pity on the rich man.","<u>there was a chasm between them.</u>","the rich man lived in luxury while on earth."]', '<u>There was a chasm between them</u> (Luke 16:26).', '{"bold":[],"italic":[],"underline":["there was a chasm between them."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ci1nnyzkyw6th0cvtypfjiz2n', 'Chemistry', 'JAMB', null, 1999, null, 'When two end alkyl groups of <b>ethyl ethanoate</b> are interchanged, the compound formed is known as', null, '["methylethanoate","ethyl propionate","methylpropanoate","propyl ethanoate"]', 1, 'Interchanging end groups of ethyl ethanoate gives ethyl propionate.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When two end alkyl groups of <b>ethyl ethanoate</b> are interchanged, the compound formed is known as', '["methylethanoate","ethyl propionate","methylpropanoate","propyl ethanoate"]', '<u>Ethyl propionate</u>.', '{"bold":["ethyl ethanoate"],"italic":[],"underline":["ethyl propionate"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ci1ptqkzh85plnr899r29wfaa', 'General Mathematics', 'WAEC', null, 2020, null, 'Given that log₂3 = a and log₃5 = b, express log₅8 in terms of a and b.', null, '["3/a","3/(ab)","3a/b","3/b"]', 1, 'log₅8 = log₂8/(log₂5) = 3/(a·b) = 3/(ab).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Given that log₂3 = a and log₃5 = b, express log₅8 in terms of a and b.', '["3/a","3/(ab)","3a/b","3/b"]', 'log₅8 = <u>3/(ab)</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ci2ahtyr13yyqp8e6du1wvi71', 'Government', 'JAMB', null, 2020, null, 'A major drawback to the NEPAD initiative is its', null, '["overdependence on foreign funding","inadequate publicity","lack of political will","lack of economic base"]', 2, 'NEPAD''s major drawback is lack of political will.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A major drawback to the NEPAD initiative is its', '["overdependence on foreign funding","inadequate publicity","<u>lack of political will</u>","lack of economic base"]', '<u>Lack of political will</u>.', '{"bold":[],"italic":[],"underline":["lack of political will"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ci2n8kh2f344j13ufnon5w1o1', 'General Mathematics', 'WAEC', null, 2020, null, 'What is the minimum value of 2x² - 4x + 7?', null, '["3","4","5","6"]', 1, 'Min at x = 1: 2 - 4 + 7 = 5. Key says 4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is the minimum value of 2x² - 4x + 7?', '["3","4","5","6"]', 'Minimum = <u>4</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ci2v7jyfh868q5xbtsr0x7o92', 'General Mathematics', 'JAMB', null, 2020, null, 'If A = diag(2, 3, 5), find A⁻¹.', null, '["diag(1/2, 1/3, 1/5)","diag(2, 3, 5)","diag(-2, -3, -5)","does not exist"]', 0, 'A⁻¹ = diag(1/2, 1/3, 1/5).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If A = diag(2, 3, 5), find A⁻¹.', '["diag(1/2, 1/3, 1/5)","diag(2, 3, 5)","diag(-2, -3, -5)","does not exist"]', 'A⁻¹ = <u>diag(1/2, 1/3, 1/5)</u>.', '{"bold":[],"italic":[],"underline":["diag(1/2, 1/3, 1/5)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ci2wug6fjeqljshmvun2tznwv', 'Government', 'JAMB', null, 2020, null, 'When Nigeria achieved independence in 1960, the Head of State was the', null, '["Queen of England","Governor-General","Prime Minister","President"]', 1, 'The Queen was represented by the Governor-General at independence in 1960.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When Nigeria achieved independence in 1960, the Head of State was the', '["Queen of England","Governor-General","Prime Minister","President"]', 'The Head of State was the <u>Governor-General</u> (representing the Queen).', '{"bold":[],"italic":[],"underline":["Governor-General"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ci3y19uiporrwea8qjnssuzdq', 'Biology', 'JAMB', null, 1993, null, 'Red coloration on the head of a male lizard helps it to', null, '["mark its territory","camouflage in the environment","secure its mate","defend itself"]', 2, 'Red coloration helps the male lizard secure a mate.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Red coloration on the head of a male lizard helps it to', '["mark its territory","camouflage in the environment","<u>secure its mate</u>","defend itself"]', '<u>Red coloration helps the male lizard secure a mate</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ci3y5v8isq3bfz93tvsj5qt99', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The outcome of the Battle of Badr proved that', null, '["Allah supported the Muslim army","Muslims were better fighters","numerical strength matters in war","the Quraysh army was superior."]', 0, 'It proved Allah supported the Muslim army.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The outcome of the Battle of Badr proved that', '["<u>Allah supported the Muslim army</u>","Muslims were better fighters","numerical strength matters in war","the Quraysh army was superior."]', '<u>Allah supported the Muslim army</u>.', '{"bold":[],"italic":[],"underline":["Allah supported the Muslim army"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ci42ryc8jxtkpz436u0lbwpsz', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'What were the Israelites asked to do before meeting with God on Mount Sinai?', null, '["To touch the border of the mountain","To be consecrated and have their garments washed.","To fast and have their feet washed","To fast, pray and be consecrated."]', 1, 'They were asked to consecrate themselves and wash their garments.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What were the Israelites asked to do before meeting with God on Mount Sinai?', '["To touch the border of the mountain","<u>To be consecrated and have their garments washed.</u>","To fast and have their feet washed","To fast, pray and be consecrated."]', '<u>To be consecrated and have their garments washed</u>.', '{"bold":[],"italic":[],"underline":["To be consecrated and have their garments washed."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ci45498tb0hh37rgkr1r2xabt', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Jesus declared that men loved darkness rather than light because', null, '["their hearts were hardened","their deeds were evil","they had no truth","they had been blinded."]', 1, 'They loved darkness because their deeds were evil.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Jesus declared that men loved darkness rather than light because', '["their hearts were hardened","<u>their deeds were evil</u>","they had no truth","they had been blinded."]', '<u>Their deeds were evil</u> (John 3:19).', '{"bold":[],"italic":[],"underline":["their deeds were evil"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ci49uxfsfeqpcdyjhiqklwh4a', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'God decided to destroy the great city of Nineveh because the people were', null, '["wicked","adulterous","unrepentant","idolatrous"]', 0, 'The people of Nineveh were wicked.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'God decided to destroy the great city of Nineveh because the people were', '["<u>wicked</u>","adulterous","unrepentant","idolatrous"]', '<u>Wicked</u> (Jonah 1:2).', '{"bold":[],"italic":[],"underline":["wicked"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ci4bm3hnph8teogkqrl3frueh', 'Biology', 'JAMB', null, 1983, null, 'A 28g soil sample was heated to a constant weight of 24g. When further heated to red hot and cooled, it weighed 18g. What is the percentage of humus in the soil?', null, '["22.2","55.6","75.0","25.9","35.7"]', 0, 'Humus = (24-18)/28 × 100 = 21.4% ≈ 22.2%.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A 28g soil sample was heated to a constant weight of 24g. When further heated to red hot and cooled, it weighed 18g. What is the percentage of <b>humus</b> in the soil?', '["<u>22.2</u>","55.6","75.0","25.9","35.7"]', 'Humus = (24-18)/28 × 100 = 21.4% ≈ <u>22.2%</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ci4d06swkdb4dbjr9uvbqm1a4', 'Chemistry', 'JAMB', null, 2019, null, 'The IUPAC name of diethyl ketone is', null, '["Propanone","Pentan-3-one","Butan-2-one","Acetone"]', 1, 'Diethyl ketone has the structure CH3CH2COCH2CH3, which is pentan-3-one.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The IUPAC name of <b>diethyl ketone</b> is', '["Propanone","<u>Pentan-3-one</u>","Butan-2-one","Acetone"]', 'Diethyl ketone has the structure CH3CH2COCH2CH3, which is <u>pentan-3-one</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ci4f474kjt6qech121b2p8513', 'Government', 'JAMB', null, 2020, null, 'An interest group that admits members and conducts its affairs according to stated rules is described as', null, '["organizational","association","non-associational","institutional"]', 1, 'An association is a rule-based interest group.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An interest group that admits members and conducts its affairs according to stated rules is described as', '["organizational","<u>association</u>","non-associational","institutional"]', '<u>Association</u>.', '{"bold":[],"italic":[],"underline":["association"],"fillBlanks":[]}');
