insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ci4xaiq3dkd2xdcp2njukkmma', 'General Mathematics', 'JAMB', null, 2020, null, 'Lottery: 10 tickets, 2 prizes. If you buy 2 tickets, find the probability of winning at least one prize.', null, '["17/45","16/45","15/45","14/45"]', 0, 'P = 1 - (8/10)(7/9) = 1 - 56/90 = 34/90 = 17/45.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Lottery: 10 tickets, 2 prizes. If you buy 2 tickets, find the probability of winning at least one prize.', '["17/45","16/45","15/45","14/45"]', 'P = <u>17/45</u>.', '{"bold":[],"italic":[],"underline":["17/45"],"fillBlanks":[]}');
