insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ci6pv6bk7ebq0d9hwgl0s5vmc', 'Chemistry', 'JAMB', null, 1985, null, 'An element with atomic number twelve is likely to be', null, '["electrovalent with a valency of 1","electrovalent with a valency of 2","covalent with a valency of 2","covalent with a valency of 4"]', 1, 'Mg (atomic number 12) is electrovalent with valency 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An element with atomic number twelve is likely to be', '["electrovalent with a valency of 1","electrovalent with a valency of 2","covalent with a valency of 2","covalent with a valency of 4"]', '<u>Mg is electrovalent with valency 2</u>.', '{"bold":[],"italic":[],"underline":["electrovalent with a valency of 2"],"fillBlanks":[]}');
