insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ci70c6d0rxdq8ummpi2d45y6b', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'When the people of Israel did what was evil in the sight of the LORD, he gave them into the hand of the Philistines for', null, '["thirty years","fifty years","twenty years","forty years"]', 3, 'He gave them into the hand of the Philistines for forty years.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When the people of Israel did what was evil in the sight of the LORD, he gave them into the hand of the Philistines for', '["thirty years","fifty years","twenty years","<u>forty years</u>"]', '<u>Forty years</u> (Judges 13:1).', '{"bold":[],"italic":[],"underline":["forty years"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ci7fwlvaix3jdxwcr2fdtxz8w', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the range of m so that x² + (m-3)x + m = 0 has real roots.', null, '["m≤1 or m≥9","m≤-1 or m≥9","m≤1 or m≥8","m≤-2 or m≥7"]', 1, '(m-3)² - 4m ≥ 0 → m²-10m+9 ≥ 0 → m ≤ 1 or m ≥ 9. Key says m≤-1 or m≥9.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the range of m so that x² + (m-3)x + m = 0 has real roots.', '["m≤1 or m≥9","m≤-1 or m≥9","m≤1 or m≥8","m≤-2 or m≥7"]', '<u>m ≤ 1 or m ≥ 9</u> (key says m≤-1 or m≥9).', null);
