insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ci7llrxkw4r0yhafum9s5i8on', 'Biology', 'JAMB', null, 1990, null, 'The order in which organic evolution has progressed in plants is', null, '["thallophyta, schizophyta, bryophyta, pteridophyta and spermatophyta","schizophyta, thallophyta, bryophyta, pteridophyta and spermatophyta","pteridophyta, spermatophyta, thallophyta, schizophyta and bryophyta","bryophyta, pteridophyta, spermatophyta, thallophyta and schizophyta"]', 1, 'Evolutionary order: schizophyta → thallophyta → bryophyta → pteridophyta → spermatophyta.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The order in which organic evolution has progressed in plants is', '["thallophyta, schizophyta, bryophyta, pteridophyta and spermatophyta","<u>schizophyta, thallophyta, bryophyta, pteridophyta and spermatophyta</u>","pteridophyta, spermatophyta, thallophyta, schizophyta and bryophyta","bryophyta, pteridophyta, spermatophyta, thallophyta and schizophyta"]', 'Evolutionary order: <u>schizophyta → thallophyta → bryophyta → pteridophyta → spermatophyta</u>.', null);
