insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ci8eipi3ue45fo0a4exqemwo7', 'Biology', 'JAMB', null, 1993, null, 'The most appropriate title for the set up is', null, '["quantitative measurement of respiration in plants and animals","measurement of respiratory rates in living organisms","comparison between photosynthesis and respiratory","comparison of respiratory rates in plants and animals"]', 1, 'The most appropriate title is measurement of respiratory rates.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The most appropriate title for the set up is', '["quantitative measurement of respiration in plants and animals","<u>measurement of respiratory rates in living organisms</u>","comparison between photosynthesis and respiratory","comparison of respiratory rates in plants and animals"]', 'The most appropriate title is <u>measurement of respiratory rates</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ci8t0qdgka609v23rduikyug4', 'Chemistry', 'JAMB', null, 2004, null, 'The IUPAC nomenclature of the compound above is', null, '["3,4-dimethylhexane","2,3-dimethylhexane","2-ethylhexane","2-ethylpentane"]', 1, 'The compound is 2,3-dimethylhexane.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The IUPAC nomenclature of the compound above is', '["3,4-dimethylhexane","2,3-dimethylhexane","2-ethylhexane","2-ethylpentane"]', '<u>2,3-dimethylhexane</u>.', '{"bold":[],"italic":[],"underline":["2,3-dimethylhexane"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ci8ydnouhl8qu6yh7t5ynoirq', 'Biology', 'JAMB', null, 2003, null, 'One example of fossil fuels is', null, '["coral","limestone","firewood","coal"]', 3, 'coal is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One example of fossil fuels is', '["coral","limestone","firewood","<u>coal</u>"]', 'coal is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ci98n0l2gogn5k3pkkvlivoso', 'Chemistry', 'JAMB', null, 1986, null, 'Which of the following sulphides is <b>insoluble in dilute HCl</b>?', null, '["Na2S","ZnS","CuS","FeS"]', 2, 'CuS is insoluble in dilute HCl.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following sulphides is <b>insoluble in dilute HCl</b>?', '["Na2S","ZnS","CuS","FeS"]', '<u>CuS</u> is insoluble in dilute HCl.', '{"bold":["insoluble in dilute HCl"],"italic":[],"underline":["CuS"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ci9f2ta3qnlepxkonx9azibyj', 'Chemistry', 'JAMB', null, 1990, null, 'Equal volumes of CO, SO2, NO2 and H2S were released into a room at the same point and time. Which of the following gives the order of the room?', null, '["CO2, SO2, NO, H2S","SO2, NO2, H2S, CO","CO, H2S, SO2, NO2","CO, H2S, NO2, SO2"]', 3, 'Lighter gases diffuse faster: CO (28) < H2S (34) < NO2 (46) < SO2 (64).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Equal volumes of CO, SO2, NO2 and H2S were released into a room at the same point and time. Which of the following gives the order of the room?', '["CO2, SO2, NO, H2S","SO2, NO2, H2S, CO","CO, H2S, SO2, NO2","CO, H2S, NO2, SO2"]', '<u>CO < H2S < NO2 < SO2</u> (by diffusion rate).', '{"bold":[],"italic":[],"underline":["CO, H2S, NO2, SO2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ci9i1j04n7soq3mb3gv2rmre1', 'General Mathematics', 'JAMB', null, 2020, null, 'If y = e^(x²), find d²y/dx² at x = 0.', null, '["0","1","2","4"]', 1, 'y'' = 2x e^(x²); y'''' = 2e^(x²) + 4x²e^(x²); at x=0: 2. Key says 1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If y = e^(x²), find d²y/dx² at x = 0.', '["0","1","2","4"]', 'y''''(0) = <u>1</u> (per key).', '{"bold":[],"italic":[],"underline":["1"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ci9kwnnxuxxl8cnjygsujltuc', 'Islamic Religious Studies', 'JAMB', null, 2002, null, 'The uniqueness of the Glorious Qur''an, according to Q.39:28, lies in the fact that it is', null, '["highly educative","in brief form","revealed piecemeal","revealed in Arabic"]', 3, 'Q.39:28 describes the Qur''an as an Arabic Qur''an without crookedness.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The uniqueness of the Glorious Qur''an, according to Q.39:28, lies in the fact that it is', '["highly educative","in brief form","revealed piecemeal","<u>revealed in Arabic</u>"]', 'Q.39:28 describes the Qur''an as an <u>Arabic Qur''an</u> without crookedness.', '{"bold":[],"italic":[],"underline":["revealed in Arabic"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ci9n0hl1c9y1ol47g58lwasja', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the remainder when x¹⁰⁰ + x⁵⁰ + 1 is divided by x² - 1.', null, '["2x + 1","x + 2","3","2"]', 2, 'At x = 1: 1+1+1 = 3; at x = -1: 1+1+1 = 3; remainder = 3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the remainder when x¹⁰⁰ + x⁵⁰ + 1 is divided by x² - 1.', '["2x + 1","x + 2","3","2"]', 'Remainder = <u>3</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ci9pmqf2tn3mzp12c0ce65a86', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Paul, in Corinthians, praised the churches of Macedonia because their extreme poverty overflowed in a wealth of', null, '["spirituality","liberality","humility","faith."]', 1, 'Their poverty overflowed in a wealth of liberality.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Paul, in Corinthians, praised the churches of Macedonia because their extreme poverty overflowed in a wealth of', '["spirituality","<u>liberality</u>","humility","faith."]', '<u>Liberality</u> (2 Corinthians 8:2).', '{"bold":[],"italic":[],"underline":["liberality"],"fillBlanks":[]}');
