insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ci9wgsirkndb9ft11k89bpc5z', 'English Language', 'JAMB', null, 2020, null, 'Remember this matter is strictly _____.', null, '["between you and I","among you and I","between you and me","between you and myself"]', 2, 'Between + object pronoun "me".', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Remember this matter is strictly _____.', '["between you and I","among you and I","between you and me","between you and myself"]', 'Between + object: <u>between you and me</u>.', '{"bold":[],"italic":[],"underline":["between you and me"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ci9xgoqhk8ol67gzuf0h9qnpd', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'In Colossians, Christians are advised to be diligent at work because in so doing, they are', null, '["serving God","exalting themselves","challenging unbelievers","worthy of heaven"]', 0, 'They are serving God.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In Colossians, Christians are advised to be diligent at work because in so doing, they are', '["<u>serving God</u>","exalting themselves","challenging unbelievers","worthy of heaven"]', '<u>Serving God</u> (Colossians 3:23).', '{"bold":[],"italic":[],"underline":["serving God"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ci9zluauws02f925is1ii70ae', 'Chemistry', 'JAMB', null, 1996, null, 'A sample of a gas exerts a pressure of 8.2 atm when confined in a 2.93dm³ container at 20°C. The number of moles of gas in the sample is [R=0.082 litre atm/deg mole]', null, '["1.00","2.00","3.00","4.00"]', 0, 'n = PV/RT = (8.2 × 2.93)/(0.082 × 293) = 1.00 mol.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A sample of a gas exerts a pressure of 8.2 atm when confined in a 2.93dm³ container at 20°C. The number of moles of gas in the sample is [R=0.082 litre atm/deg mole]', '["1.00","2.00","3.00","4.00"]', 'n = <u>1.00 mol</u>.', '{"bold":[],"italic":[],"underline":["1.00"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cia7of7y3togcfmuzqfjhebg9', 'Chemistry', 'JAMB', null, 1988, null, 'Which of the following substances is a <b>basic salt</b>?', null, '["Na2CO3","Mg(OH)Cl","NaHCO3","K2SO4·Al2(SO4)3·24H2O"]', 1, 'Mg(OH)Cl is a basic salt (contains OH⁻).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following substances is a <b>basic salt</b>?', '["Na2CO3","Mg(OH)Cl","NaHCO3","K2SO4·Al2(SO4)3·24H2O"]', '<u>Mg(OH)Cl is a basic salt</u>.', '{"bold":["basic salt"],"italic":[],"underline":["Mg(OH)Cl"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ciaayt6oybfhnlhgk02xk82sl', 'General Mathematics', 'WAEC', null, 2020, null, 'If y = sin⁻¹√(1-t) and t = cos x, find dy/dx.', null, '["1","-1","1/2","-1/2"]', 0, 'y = sin⁻¹√(1-cos x) = sin⁻¹(√2 sin(x/2)); dy/dx = 1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If y = sin⁻¹√(1-t) and t = cos x, find dy/dx.', '["1","-1","1/2","-1/2"]', 'dy/dx = <u>1</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ciagcwrw9j965byhe0m4v48c9', 'Biology', 'JAMB', null, 2001, null, 'The stem of a typical aquatic plant usually has many', null, '["air cavities","intercellular spaces","water cavities","water-conducting cells."]', 0, 'air cavities is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The stem of a typical aquatic plant usually has many', '["<u>air cavities</u>","intercellular spaces","water cavities","water-conducting cells."]', 'air cavities is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ciamycvtt5hd4gv6gm1cashj3', 'Chemistry', 'JAMB', null, 1999, null, 'When two end alkyl groups of <b>ethyl ethanoate</b> are interchanged, the compound formed is known as', null, '["methylethanoate","ethyl propionate","methylpropanoate","propyl ethanoate"]', 1, 'Interchanging end groups of ethyl ethanoate gives ethyl propionate.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When two end alkyl groups of <b>ethyl ethanoate</b> are interchanged, the compound formed is known as', '["methylethanoate","ethyl propionate","methylpropanoate","propyl ethanoate"]', '<u>Ethyl propionate</u>.', '{"bold":["ethyl ethanoate"],"italic":[],"underline":["ethyl propionate"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ciaov2ci482q330ypko2cg1tq', 'General Mathematics', 'JAMB', null, 2020, null, 'A point P moves such that its distance from A(1, 2) is always equal to its distance from the y-axis. Find the equation of the locus of P.', null, '["y² - 4y - 2x + 5 = 0","y² - 4y + 2x + 5 = 0","x² - 2x - 4y + 5 = 0","x² - 2x + 4y + 5 = 0"]', 0, '(x-1)² + (y-2)² = x² → y² - 4y - 2x + 5 = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A point P moves such that its distance from A(1, 2) is always equal to its distance from the y-axis. Find the equation of the locus of P.', '["y² - 4y - 2x + 5 = 0","y² - 4y + 2x + 5 = 0","x² - 2x - 4y + 5 = 0","x² - 2x + 4y + 5 = 0"]', 'Locus: <u>y² - 4y - 2x + 5 = 0</u>.', '{"bold":[],"italic":[],"underline":["y² - 4y - 2x + 5 = 0"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ciappjwnzif0a6h8goc7e59ib', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Paul and Barnabas were sent out on the first missionary work from Antioch to Seleucia by the', null, '["Holy Spirit","church elders","other disciples","prophets and teachers"]', 0, 'They were sent by the Holy Spirit.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Paul and Barnabas were sent out on the first missionary work from Antioch to Seleucia by the', '["<u>Holy Spirit</u>","church elders","other disciples","prophets and teachers"]', '<u>Holy Spirit</u> (Acts 13:4).', '{"bold":[],"italic":[],"underline":["Holy Spirit"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ciapx8lw5xg6vwcsp5i734fbg', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve the equation 2²ˣ - 5·2ˣ + 4 = 0.', null, '["0","1","0","0, 2"]', 3, 'Let y = 2^x: y² - 5y + 4 = 0 → y = 1 or 4 → x = 0 or 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Solve the equation 2²ˣ - 5·2ˣ + 4 = 0.', '["0","1","0","0, 2"]', 'Let y = 2^x: y² - 5y + 4 = 0 → y = 1 or 4 → x = 0 or 2.', '{"bold":[],"italic":[],"underline":["1"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ciaz3yh9mk15xqeqzlyc22ha0', 'Chemistry', 'JAMB', null, 1988, null, 'Suitable reagents for the laboratory preparation of nitrogen are', null, '["sodium trioxonitrate(III) and ammonium chloride","sodium trioxonitrate(V) and ammonium chloride","sodium chloride and ammonium trioxonitrate(V)","sodium chloride and ammonium trioxonitrate(III)"]', 1, 'NaNO2 + NH4Cl → N2 + NaCl + 2H2O.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Suitable reagents for the laboratory preparation of nitrogen are', '["sodium trioxonitrate(III) and ammonium chloride","sodium trioxonitrate(V) and ammonium chloride","sodium chloride and ammonium trioxonitrate(V)","sodium chloride and ammonium trioxonitrate(III)"]', '<u>NaNO2 + NH4Cl</u> gives N2.', '{"bold":[],"italic":[],"underline":["sodium trioxonitrate(V) and ammonium chloride"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cib6um4376oqjhhk4087td043', 'General Mathematics', 'JAMB', null, 2020, null, 'If a*b = a + 3b, find x if x*2 = 3*x.', null, '["3","1.5","5","6"]', 1, 'x*2 = x + 6 and 3*x = 3 + 3x → 2x = 3 → x = 1.5.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'If a*b = a + 3b, find x if x*2 = 3*x.', '["3","1.5","5","6"]', 'x*2 = x + 6 and 3*x = 3 + 3x → 2x = 3 → x = 1.5.', '{"bold":[],"italic":[],"underline":["4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cib7bfh0f65ij9445ym261duq', 'Chemistry', 'JAMB', null, 1990, null, 'In the reaction SnO2 + 2C → Sn + 2CO, the mass of coke containing 80% carbon required to reduce 0.032 kg of pure tin oxide is [Sn=119, O=16, C=12]', null, '["0.40 kg","0.20 kg","0.06 kg","0.40 g"]', 2, 'Moles SnO2 = 32/151 = 0.212; C needed = 0.424 mol = 5.09g; coke = 5.09/0.8 = 6.36g ≈ 0.06 kg.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the reaction SnO2 + 2C → Sn + 2CO, the mass of coke containing 80% carbon required to reduce 0.032 kg of pure tin oxide is [Sn=119, O=16, C=12]', '["0.40 kg","0.20 kg","0.06 kg","0.40 g"]', 'Mass coke ≈ <u>0.06 kg</u>.', '{"bold":[],"italic":[],"underline":["0.06 kg"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cib7ly0qvtlfjt3tcl7hd1m11', 'Chemistry', 'JAMB', null, 1998, null, 'Which of the following electron configurations indicates an atom with the <b>highest ionization energy</b>?', null, '["2,8,7","2,8,8,1","2,8,8,2","2,8,8,7"]', 3, 'Noble gas configuration (2,8,8) has highest IE; among options, 2,8,8,7 is a halogen with high IE.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following electron configurations indicates an atom with the <b>highest ionization energy</b>?', '["2,8,7","2,8,8,1","2,8,8,2","2,8,8,7"]', '<u>2,8,8,7 (halogen)</u> has high IE.', '{"bold":["highest ionization energy"],"italic":[],"underline":["2,8,8,7"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cibciawugj8fsoaqbkoy24bdc', 'Government', 'JAMB', null, 2020, null, 'The law of libel limits a citizen''s right to freedom of', null, '["movement","association","expression.","worship"]', 2, 'Libel law limits freedom of expression.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The law of libel limits a citizen''s right to freedom of', '["movement","association","<u>expression.</u>","worship"]', '<u>Expression</u>.', '{"bold":[],"italic":[],"underline":["expression."],"fillBlanks":[]}');
