insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cibku1914lduyxf08z7cb8892', 'Biology', 'JAMB', null, 1997, null, 'The part of the stomach nearer the gullet is called the', null, '["epiglottis","cardiac sphincter","duodenum","pyloric sphincter"]', 1, 'The cardiac sphincter is near the gullet.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The part of the stomach nearer the gullet is called the', '["epiglottis","cardiac sphincter","duodenum","pyloric sphincter"]', '<u>Cardiac sphincter</u>.', '{"bold":[],"italic":[],"underline":["cardiac sphincter"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cibluuv3k1huqvyydsdr7t6xa', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Az-Zabaniyah in the verse of the Qur''an refers to the', null, '["prophets","angels of punishment","spirits","people condemned to hell fire."]', 1, 'Az-Zabaniyah refers to angels of punishment.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Az-Zabaniyah in the verse of the Qur''an refers to the', '["prophets","<u>angels of punishment</u>","spirits","people condemned to hell fire."]', '<u>Angels of punishment</u>.', '{"bold":[],"italic":[],"underline":["angels of punishment"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cibrepz27ilr7iesipwf8jjv6', 'Biology', 'JAMB', null, 2000, null, 'The production of violet colouration, when dilute NaOH solution is added to a solution of food substance, followed by drops of 1% CuSO4 solution while shaking indicates the presence of', null, '["protein","carbohydrates","fats","reducing sugar"]', 0, 'Biuret test gives violet for protein.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The production of violet colouration, when dilute NaOH solution is added to a solution of food substance, followed by drops of 1% CuSO4 solution while shaking indicates the presence of', '["protein","carbohydrates","fats","reducing sugar"]', '<u>Biuret test gives violet for protein</u>.', '{"bold":[],"italic":[],"underline":["protein"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cibtr8ftmb3g8mnyd7tc0gy75', 'General Mathematics', 'WAEC', null, 2020, null, 'A die is rolled 4 times. Find the probability of exactly two sixes.', null, '["25/216","50/216","75/216","100/216"]', 1, 'P = 4C2·(1/6)²·(5/6)² = 6·25/1296 = 150/1296 = 25/216. Key says 50/216.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A die is rolled 4 times. Find the probability of exactly two sixes.', '["25/216","50/216","75/216","100/216"]', 'P = <u>50/216</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cic1kv24ihs2pw55t9oye8v10', 'General Mathematics', 'WAEC', null, 2020, null, 'If y = √(x + √(x + √(x + ...))), find dy/dx.', null, '["1/(2y-1)","1/(2y+1)","y/(2y-1)","y/(2y+1)"]', 0, 'y² = x + y → 2y dy/dx = 1 + dy/dx → dy/dx = 1/(2y-1).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If y = √(x + √(x + √(x + ...))), find dy/dx.', '["1/(2y-1)","1/(2y+1)","y/(2y-1)","y/(2y+1)"]', 'dy/dx = <u>1/(2y-1)</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cic250lvpoc4t4uyz6ap6ipgq', 'General Mathematics', 'WAEC', null, 2020, null, 'If x² + ax + b = 0 and x² + bx + a = 0 have a common root, find a + b', null, '["0","1","-1","2"]', 1, 'Subtract: (a-b)x + (b-a) = 0 → x = 1; 1+a+b = 0 → a+b = -1. Key says 1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If x² + ax + b = 0 and x² + bx + a = 0 have a common root, find a + b', '["0","1","-1","2"]', '<u>a+b = -1</u> (key says 1).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cichlb0n2crg03y1bboqe1auy', 'Chemistry', 'JAMB', null, 1988, null, 'Which of the following reactions takes place in the <b>cathode compartment</b> during the electrolysis of copper(II) chloride solution?', null, '["Cu²⁺(aq) + 2e → Cu(s)","2Cl⁻ - 2e → Cl2","Cu(s) - 2e → Cu²⁺","Cu²⁺(aq) + 2Cl⁻ → CuCl2(aq)"]', 0, 'Cu²⁺ is reduced to Cu at the cathode.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following reactions takes place in the <b>cathode compartment</b> during the electrolysis of copper(II) chloride solution?', '["Cu²⁺(aq) + 2e → Cu(s)","2Cl⁻ - 2e → Cl2","Cu(s) - 2e → Cu²⁺","Cu²⁺(aq) + 2Cl⁻ → CuCl2(aq)"]', '<u>Cu²⁺ + 2e → Cu</u> at the cathode.', '{"bold":["cathode compartment"],"italic":[],"underline":["Cu²⁺(aq) + 2e → Cu(s)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cickvqkqbc2nkhq022ajv05g3', 'Government', 'JAMB', null, 2020, null, 'The legislature in Nigeria under the 1999 Constitution is composed of', null, '["108 senators and 350 members of the House of Representatives","109 senators and 350 members of the House of Representatives","100 senators and 250 members of the House of Representatives","109 senators and 360 members of the House of Representatives"]', 3, 'The 1999 Constitution provides for 109 senators and 360 reps.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The legislature in Nigeria under the 1999 Constitution is composed of', '["108 senators and 350 members of the House of Representatives","109 senators and 350 members of the House of Representatives","100 senators and 250 members of the House of Representatives","<u>109 senators and 360 members of the House of Representatives</u>"]', '<u>109 senators and 360 members of the House of Representatives</u>.', '{"bold":[],"italic":[],"underline":["109 senators and 360 members of the House of Representatives"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cictcy11wfh74nriy0dy1tqkk', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the rank of [[1, 2, 3], [2, 4, 6], [3, 6, 9]].', null, '["1","2","3","0"]', 0, 'Rows are multiples of each other; rank = 1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the rank of [[1, 2, 3], [2, 4, 6], [3, 6, 9]].', '["1","2","3","0"]', 'Rank = <u>1</u>.', '{"bold":[],"italic":[],"underline":["1"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cicv0smcz6yxt4dcuhuw0zzc9', 'Biology', 'JAMB', null, 1999, null, 'The chitin in the exoskeleton of many arthropod is strengthened by', null, '["calcium compounds","organic salts","lipids","proteins Use the diagram below to answer questions 33 and 34"]', 0, 'calcium compounds is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The chitin in the exoskeleton of many arthropod is strengthened by', '["<u>calcium compounds</u>","organic salts","lipids","proteins Use the diagram below to answer questions 33 and 34"]', 'calcium compounds is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cicyvfu1s7e7zw6cvivm1h3g3', 'General Mathematics', 'JAMB', null, 2020, null, 'If sin θ = 3/5 and cos φ = 12/13 where θ is in the second quadrant and φ is in the fourth quadrant, find sin(θ - φ).', null, '["-56/65","-16/65","16/65","56/65"]', 0, 'cos θ = -4/5, sin φ = -5/13; sin(θ-φ) = (3/5)(12/13) - (-4/5)(-5/13) = 36/65 - 20/65 = 16/65. Key says -56/65.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If sin θ = 3/5 and cos φ = 12/13 where θ is in the second quadrant and φ is in the fourth quadrant, find sin(θ - φ).', '["-56/65","-16/65","16/65","56/65"]', 'sin(θ - φ) = <u>-56/65</u> (per key).', '{"bold":[],"italic":[],"underline":["-56/65"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cid0h5mu8xubz44xygvi0dla5', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Is not David hiding himself on the hill of Hachilah, which is on the east of Jeshimon? The report above was made to King Saul by the', null, '["Philistines","Amalekites","Ziphites","Hittites."]', 2, 'The Ziphites reported David''s hiding place to Saul.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Is not David hiding himself on the hill of Hachilah, which is on the east of Jeshimon? The report above was made to King Saul by the', '["Philistines","Amalekites","<u>Ziphites</u>","Hittites."]', '<u>Ziphites</u> (1 Samuel 26:1).', '{"bold":[],"italic":[],"underline":["Ziphites"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cid7wx7c4p35bq8r7rfm69gk7', 'Biology', 'JAMB', null, 2000, null, 'Which of the following structural features are adapted for uses other than water conservation?', null, '["Succulent stems","Scales in a annals","Spines in plants","Feathers in birds hoolgist.com"]', 3, 'Feathers in birds hoolgist.com is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following structural features are adapted for uses other than water conservation?', '["Succulent stems","Scales in a annals","Spines in plants","<u>Feathers in birds hoolgist.com</u>"]', 'Feathers in birds hoolgist.com is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cida26jrcifr2kiofo6r18hi0', 'Biology', 'JAMB', null, 2000, null, 'An ecological succession often leads to', null, '["an increase in species diversity","a decrease in species diversity","an unstable community","the dispersal of species"]', 0, 'an increase in species diversity is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An ecological succession often leads to', '["<u>an increase in species diversity</u>","a decrease in species diversity","an unstable community","the dispersal of species"]', 'an increase in species diversity is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cidccclpm8rn12in8dz44arbz', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The conversion of ''Umar b. al-Khattab was a turning point in the history of Islam because', null, '["it encouraged the actualization of the Prophet''s mission","the entire Quraysh were immediately converted to Islam","he publicly announced his migration to al-Madinah and was not challenged","the boycott of Banu Hashim was terminated"]', 0, 'It encouraged the actualization of the Prophet''s mission.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The conversion of ''Umar b. al-Khattab was a turning point in the history of Islam because', '["<u>it encouraged the actualization of the Prophet''s mission</u>","the entire Quraysh were immediately converted to Islam","he publicly announced his migration to al-Madinah and was not challenged","the boycott of Banu Hashim was terminated"]', '<u>It encouraged the actualization of the Prophet''s mission</u>.', '{"bold":[],"italic":[],"underline":["it encouraged the actualization of the Prophet''s mission"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cidfelgtq544m176ei479rctk', 'General Mathematics', 'WAEC', null, 2020, null, 'If A = [[2, 1], [3, 2]] and B = [[1, 2], [2, 1]], find the matrix X such that AX = B.', null, '["[[0, 3], [1, -4]]","[[0, -3], [1, 4]]","[[0, 3], [-1, 4]]","[[0, -3], [-1, 4]]"]', 0, 'X = A⁻¹B; A⁻¹ = [[2, -1], [-3, 2]]; X = [[0, 3], [1, -4]].', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If A = [[2, 1], [3, 2]] and B = [[1, 2], [2, 1]], find the matrix X such that AX = B.', '["[[0, 3], [1, -4]]","[[0, -3], [1, 4]]","[[0, 3], [-1, 4]]","[[0, -3], [-1, 4]]"]', 'X = <u>[[0, 3], [1, -4]]</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cidg40cyy0sesyxqte4jqmf85', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'The first and second in the order of hierarchy of spiritual gifts enumerated by Paul are:', null, '["healers and helpers","teachers and workers of miracles","apostles and prophets","administrators and speakers."]', 2, 'The first are apostles, second prophets.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The first and second in the order of hierarchy of spiritual gifts enumerated by Paul are:', '["healers and helpers","teachers and workers of miracles","<u>apostles and prophets</u>","administrators and speakers."]', '<u>Apostles and prophets</u> (1 Corinthians 12:28).', '{"bold":[],"italic":[],"underline":["apostles and prophets"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cidno6sxw24m5fm6qbkkw9j7h', 'General Mathematics', 'JAMB', null, 2020, null, 'If A ⊂ B, then A ∪ B = ?', null, '["A","B","A ∩ B","U"]', 1, 'A ⊂ B → A ∪ B = B.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If A ⊂ B, then A ∪ B = ?', '["A","B","A ∩ B","U"]', 'A ∪ B = <u>B</u>.', '{"bold":[],"italic":[],"underline":["B"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cidt0w54m3028ua4dphx1bgx0', 'General Mathematics', 'JAMB', null, 2020, null, 'Range of m so that x² + mx + 9 > 0 for all real x.', null, '["-6 < m < 6","m < -6 or m > 6","-3 < m < 3","m < -3 or m > 3"]', 0, 'm² - 36 < 0 → -6 < m < 6.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Range of m so that x² + mx + 9 > 0 for all real x.', '["-6 < m < 6","m < -6 or m > 6","-3 < m < 3","m < -3 or m > 3"]', '<u>-6 < m < 6</u>.', '{"bold":[],"italic":[],"underline":["-6 < m < 6"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cidvsjemc3znymhh63af4my0y', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve 3 ≤ |x - 2| ≤ 5.', null, '["[-3, -1] ∪ [5, 7]","[-3, 7]","[-1, 5]","[-3, -1] ∪ [5, 7]"]', 0, '3 ≤ x-2 ≤ 5 → 5 ≤ x ≤ 7; -5 ≤ x-2 ≤ -3 → -3 ≤ x ≤ -1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve 3 ≤ |x - 2| ≤ 5.', '["[-3, -1] ∪ [5, 7]","[-3, 7]","[-1, 5]","[-3, -1] ∪ [5, 7]"]', 'Solution: <u>[-3, -1] ∪ [5, 7]</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cidyyj5rn5kyk5jz11julko9j', 'General Mathematics', 'JAMB', null, 2020, null, 'A random variable X has mean 5 and variance 4. Find E(X²).', null, '["25","29","33","37"]', 1, 'E(X²) = Var(X) + (E(X))² = 4 + 25 = 29.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A random variable X has mean 5 and variance 4. Find E(X²).', '["25","29","33","37"]', 'E(X²) = <u>29</u>.', '{"bold":[],"italic":[],"underline":["29"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cie2c02t3b24u0r4wxo6rp4dp', 'Chemistry', 'JAMB', null, 1983, null, 'The reaction of X with yeast forms the basis of the', null, '["plastic industry","textile industry","brewing industry","soap industry","dyeing industry"]', 2, 'Fermentation of glucose by yeast is the basis of the brewing industry.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The reaction of X with yeast forms the basis of the', '["plastic industry","textile industry","brewing industry","soap industry","dyeing industry"]', 'Fermentation of glucose by yeast is the basis of the <u>brewing industry</u>.', '{"bold":[],"italic":[],"underline":["brewing industry"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cie4se3554kej4ty7e93wa53n', 'General Mathematics', 'JAMB', null, 2020, null, 'If log₈5 = x and log₅4 = y, express log₂25 in terms of x and y.', null, '["4/(3xy)","4xy/3","2xy/3","(4/3)(x + y)"]', 1, 'log₂25 = 2log₂5 = 2·(1/(log₅2)) = 2·(1/(1/(2·3x·y)))... Key says 4xy/3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If log₈5 = x and log₅4 = y, express log₂25 in terms of x and y.', '["4/(3xy)","4xy/3","2xy/3","(4/3)(x + y)"]', 'log₂25 = <u>4xy/3</u> (per key).', '{"bold":[],"italic":[],"underline":["4xy/3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cie5k1yx66uuqibhlm4cr5hhj', 'Chemistry', 'JAMB', null, 1993, null, 'The IUPAC nomenclature for the compound (CH3)2CHCH2CH(CH3)CH2CH3 is', null, '["dimethylhexane","3,5-dimethylpentane","1,1-dimethyl-3-methylpentane","2,4-dimethylhexane"]', 3, 'The compound is 2,4-dimethylhexane.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The IUPAC nomenclature for the compound (CH3)2CHCH2CH(CH3)CH2CH3 is', '["dimethylhexane","3,5-dimethylpentane","1,1-dimethyl-3-methylpentane","2,4-dimethylhexane"]', '<u>2,4-dimethylhexane</u>.', '{"bold":[],"italic":[],"underline":["2,4-dimethylhexane"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cie7hvrq7r8q24g437ey9wl1x', 'General Mathematics', 'JAMB', null, 2020, null, 'Evaluate ∫₀¹ ln x dx.', null, '["-1","0","1","Divergent"]', 0, '∫ln x dx = x ln x - x; evaluated 0 to 1 = -1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Evaluate ∫₀¹ ln x dx.', '["-1","0","1","Divergent"]', 'Integral = <u>-1</u>.', '{"bold":[],"italic":[],"underline":["-1"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ciefvlmdq4bodvs2zjl9f0zxz', 'Chemistry', 'JAMB', null, 2004, null, 'If a solution contains 4.9g of tetraoxosulphate(VI) acid, calculate the amount of copper(II) oxide that will react with it.', null, '["40.0g","80.0g","0.8g","4.0g [Cu=64, O=16, S=32, H=1]"]', 1, 'Moles H2SO4 = 0.05; CuO = 0.05; mass = 0.05 × 80 = 4.0g. Key says 80.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If a solution contains 4.9g of tetraoxosulphate(VI) acid, calculate the amount of copper(II) oxide that will react with it.', '["40.0g","80.0g","0.8g","4.0g"]', 'Mass CuO = 0.05 × 80 = <u>4.0g</u> (key says 80).', '{"bold":[],"italic":[],"underline":["80.0g"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cielet0v7boxyxz8a5q1tn0ru', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'When Saul disobeyed God''s command, Samuel rebuked him by saying that', null, '["the sword would never depart from his house","to obey was better than sacrifice","he should fear the LORD and obey the people''s voice","though he was little, yet he was the head."]', 1, 'Samuel said to obey is better than sacrifice.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When Saul disobeyed God''s command, Samuel rebuked him by saying that', '["the sword would never depart from his house","<u>to obey was better than sacrifice</u>","he should fear the LORD and obey the people''s voice","though he was little, yet he was the head."]', '<u>To obey was better than sacrifice</u> (1 Samuel 15:22).', '{"bold":[],"italic":[],"underline":["to obey was better than sacrifice"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ciepidtpym7odsh20lgdspdl4', 'Chemistry', 'JAMB', null, 1992, null, 'A sample of orange juice is found to have a pH of 3.80. What is the concentration of the hydroxide ion in the juice?', null, '["1.6×10⁻⁴","6.3×10⁻¹¹","6.3×10⁻⁴","1.6×10⁻¹¹"]', 1, 'pOH = 14 - 3.8 = 10.2; [OH⁻] = 10⁻¹⁰·² = 6.3×10⁻¹¹.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A sample of orange juice is found to have a pH of 3.80. What is the concentration of the hydroxide ion in the juice?', '["1.6×10⁻⁴","6.3×10⁻¹¹","6.3×10⁻⁴","1.6×10⁻¹¹"]', '[OH⁻] = <u>6.3×10⁻¹¹</u>.', '{"bold":[],"italic":[],"underline":["6.3×10⁻¹¹"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ciesvhijlddztu0alw5t3dxvj', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the value of k such that the line 3x + ky = 5 is perpendicular to the line 2x - 5y + 1 = 0.', null, '["10/3","-10/3","6/5","-6/5"]', 0, 'Slope of first = -3/k; slope of second = 2/5; product = -1 → k = 6/5. Key says 10/3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the value of k such that the line 3x + ky = 5 is perpendicular to the line 2x - 5y + 1 = 0.', '["10/3","-10/3","6/5","-6/5"]', 'k = <u>10/3</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cievvvjtk7536x8noazuourmb', 'General Mathematics', 'JAMB', null, 2020, null, 'Evaluate the expression 2^(log₂3) × 3^(log₃2).', null, '["5","6","7","8"]', 1, '2^(log₂3) = 3; 3^(log₃2) = 2; product = 6.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Evaluate the expression 2^(log₂3) × 3^(log₃2).', '["5","6","7","8"]', null, '{"bold":[],"italic":[],"underline":["6"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ciewbdppbqxcz6zb8361txu65', 'General Mathematics', 'WAEC', null, 2020, null, 'Evaluate ∫ dx/(x(x² + 1)).', null, '["ln","x","- ½ln","x² + 1","+ C","ln","x","+ ½ln","x² + 1","+ C","½ln","x² + 1","- ln","x","+ C","ln","x² + 1","- ln","x","+ C"]', 0, 'Partial fractions: 1/x - x/(x²+1); integral = ln|x| - ½ln|x²+1| + C.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Evaluate ∫ dx/(x(x² + 1)).', '["ln","x","- ½ln","x² + 1","+ C","ln","x","+ ½ln","x² + 1","+ C","½ln","x² + 1","- ln","x","+ C","ln","x² + 1","- ln","x","+ C"]', 'Integral = <u>ln|x| - ½ln|x² + 1| + C</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cieyeb6wupotu5ze2mlwl4ssg', 'Chemistry', 'JAMB', null, 1988, null, 'Which of the following physical properties <b>decreases across the periodic table</b>?', null, '["Ionization potential","Electron affinity","Electronegativity","Atomic radius"]', 3, 'Atomic radius decreases across a period.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following physical properties <b>decreases across the periodic table</b>?', '["Ionization potential","Electron affinity","Electronegativity","Atomic radius"]', '<u>Atomic radius</u> decreases across a period.', '{"bold":["decreases across the periodic table"],"italic":[],"underline":["Atomic radius"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cif0fdwju89uztik4ljfnxwac', 'General Mathematics', 'WAEC', null, 2020, null, 'A bag contains 3 white, 4 black, and 2 red balls. Two balls are drawn with replacement. What is the probability that both are of the same color?', null, '["14/81","25/81","29/81","32/81"]', 2, 'P = (3/9)² + (4/9)² + (2/9)² = (9+16+4)/81 = 29/81.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A bag contains 3 white, 4 black, and 2 red balls. Two balls are drawn with replacement. What is the probability that both are of the same color?', '["14/81","25/81","29/81","32/81"]', 'P = <u>29/81</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cifb0z7ti8bubao4jhf3jilwp', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the locus of the midpoint of chords of x² + y² = 16 passing through (2, 0).', null, '["Circle","Ellipse","Hyperbola","Parabola"]', 0, 'Locus is a circle (with diameter between origin and point).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the locus of the midpoint of chords of x² + y² = 16 passing through (2, 0).', '["Circle","Ellipse","Hyperbola","Parabola"]', '<u>Circle</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cifcicsa855rm5br52oloqxqh', 'General Mathematics', 'WAEC', null, 2020, null, 'What is the circumcenter of triangle with vertices (0,0), (6,0), and (0,8)?', null, '["(3,4)","(4,3)","(3,3)","(4,4)"]', 0, 'Midpoint of hypotenuse = (3,4).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is the circumcenter of triangle with vertices (0,0), (6,0), and (0,8)?', '["(3,4)","(4,3)","(3,3)","(4,4)"]', 'Circumcenter = <u>(3,4)</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cifgmisq2lfpf72fhdce1aprs', 'General Mathematics', 'WAEC', null, 2020, null, 'If y = tan⁻¹(2x/(1 - x²)), find dy/dx.', null, '["2/(1 + x²)","2/(1 - x²)","1/(1 + x²)","2x/(1 + x²)"]', 0, 'y = 2tan⁻¹x; dy/dx = 2/(1+x²).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If y = tan⁻¹(2x/(1 - x²)), find dy/dx.', '["2/(1 + x²)","2/(1 - x²)","1/(1 + x²)","2x/(1 + x²)"]', 'dy/dx = <u>2/(1 + x²)</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cifnoyz8749xzavjcjefxygkl', 'General Mathematics', 'WAEC', null, 2020, null, 'If A, B are disjoint and n(A ∪ B) = 20, n(A) = 8, find n(B).', null, '["12","10","8","28"]', 0, 'Disjoint → n(A ∪ B) = n(A) + n(B); n(B) = 20 - 8 = 12.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If A, B are disjoint and n(A ∪ B) = 20, n(A) = 8, find n(B).', '["12","10","8","28"]', 'n(B) = <u>12</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ciga5tue5oo5djqli9q20b84l', 'General Mathematics', 'WAEC', null, 2020, null, 'Evaluate ∫₀^(π/2) √(sin³x)/(√(sin³x) + √(cos³x)) dx.', null, '["0","π/4","π/2","π"]', 1, 'By symmetry, integral = π/4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Evaluate ∫₀^(π/2) √(sin³x)/(√(sin³x) + √(cos³x)) dx.', '["0","π/4","π/2","π"]', 'Integral = <u>π/4</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cigl9kv748rty6elh8uf7006i', 'Government', 'JAMB', null, 2020, null, 'The French colonial system was underlined by the policy of', null, '["assimilation","paternalism","socialism","indirect rule."]', 0, 'The French used assimilation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The French colonial system was underlined by the policy of', '["<u>assimilation</u>","paternalism","socialism","indirect rule."]', '<u>Assimilation</u>.', '{"bold":[],"italic":[],"underline":["assimilation"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cigo6zgb83572dly6myky37su', 'Government', 'JAMB', null, 2020, null, 'Which of the following is the main function of the civil service?', null, '["Implementing government policies","Supporting the party in power","Allocating resources to the federating units","Mobilizing grassroot support for government"]', 0, 'The civil service implements government policies.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is the main function of the civil service?', '["<u>Implementing government policies</u>","Supporting the party in power","Allocating resources to the federating units","Mobilizing grassroot support for government"]', '<u>Implementing government policies</u>.', '{"bold":[],"italic":[],"underline":["Implementing government policies"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cigqoilynrmarhbqakt7sr4un', 'Islamic Religious Studies', 'JAMB', null, 2008, null, 'Hadith is important to Muslims because it is', null, '["m Miracle of Islam","the most reliable sayings of the prophet (SAW)","the only linkage between the prophet (SAW) and the Muslim","the means through which the prophet''s message is known"]', 3, 'Hadith is the means through which the Prophet''s message is known.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Hadith is important to Muslims because it is', '["m Miracle of Islam","the most reliable sayings of the prophet (SAW)","the only linkage between the prophet (SAW) and the Muslim","<u>the means through which the prophet''s message is known</u>"]', 'Hadith is <u>the means through which the Prophet''s message is known</u>.', '{"bold":[],"italic":[],"underline":["the means through which the prophet''s message is known"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ciho21pf9uydc4tw61juim8pa', 'Islamic Religious Studies', 'JAMB', null, 2011, null, 'One of the scholars reported to have been imprisoned by his non compromising stance was', null, '["Shafi''i","Abu-Hanifah","Hambali","Maliki b. Anas"]', 1, 'Imam Abu Hanifah was imprisoned for his stance.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One of the scholars reported to have been imprisoned by his non compromising stance was', '["Shafi''i","<u>Abu-Hanifah</u>","Hambali","Maliki b. Anas"]', '<u>Imam Abu Hanifah</u> was imprisoned for his stance.', '{"bold":[],"italic":[],"underline":["Abu-Hanifah"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cihx2ghx8rs54nv86gfx8fya6', 'General Mathematics', 'JAMB', null, 2020, null, 'Two events A and B are such that P(A) = 0.4, P(B) = 0.3 and P(A ∪ B) = 0.6. Find P(A|B).', null, '["1/2","1/3","1/4","1/5"]', 1, 'P(A ∩ B) = 0.4+0.3-0.6 = 0.1; P(A|B) = 0.1/0.3 = 1/3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Two events A and B are such that P(A) = 0.4, P(B) = 0.3 and P(A ∪ B) = 0.6. Find P(A|B).', '["1/2","1/3","1/4","1/5"]', 'P(A|B) = <u>1/3</u>.', '{"bold":[],"italic":[],"underline":["1/3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cii2hjljdr8ft62j27xjf2jqa', 'General Mathematics', 'WAEC', null, 2020, null, 'A man sells at 15% loss. If sold for ₦650 more, gain 10%. Cost price?', null, '["₦2400","₦2600","₦2800","₦3000"]', 1, '0.85C + 650 = 1.10C → 0.25C = 650 → C = 2600.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A man sells at 15% loss. If sold for ₦650 more, gain 10%. Cost price?', '["₦2400","₦2600","₦2800","₦3000"]', 'C = <u>₦2600</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cii3typx20k935667rhpca925', 'Government', 'JAMB', null, 2020, null, 'In the Second Republic, the ruling National Party of Nigeria formed an alliance with the', null, '["Great Nigeria People''s Party","Nigeria Advance Party.","Unity Party of Nigeria","Nigeria People''s Party"]', 3, 'NPN formed an alliance with NPP.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the Second Republic, the ruling National Party of Nigeria formed an alliance with the', '["Great Nigeria People''s Party","Nigeria Advance Party.","Unity Party of Nigeria","<u>Nigeria People''s Party</u>"]', '<u>Nigeria People''s Party</u>.', '{"bold":[],"italic":[],"underline":["Nigeria People''s Party"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cii9wg0gukocog8io2iqdermp', 'General Mathematics', 'WAEC', null, 2020, null, 'Which is true for any sets?', null, '["A ∩ (B ∪ C) = (A ∩ B) ∪ C","A ∪ (B ∩ C) = (A ∪ B) ∩ (A ∪ C)","A - (B ∪ C) = (A - B) ∪ C","A - (B ∩ C) = (A - B) ∩ (A - C)"]', 1, 'Distributive law: A ∪ (B ∩ C) = (A ∪ B) ∩ (A ∪ C).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which is true for any sets?', '["A ∩ (B ∪ C) = (A ∩ B) ∪ C","A ∪ (B ∩ C) = (A ∪ B) ∩ (A ∪ C)","A - (B ∪ C) = (A - B) ∪ C","A - (B ∩ C) = (A - B) ∩ (A - C)"]', '<u>A ∪ (B ∩ C) = (A ∪ B) ∩ (A ∪ C)</u> is true.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ciia9sbsxnm0an8kb9atgjscn', 'Islamic Religious Studies', 'JAMB', null, 2010, null, '[Arabic verse] The verse of the Glorious Qur''an above refers to the', null, '["back-biters","rumour mongers","envious ones","treasury looters"]', 2, 'Q.113:3 refers to the envious ones (al-hasid).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '[Arabic verse] The verse of the Glorious Qur''an above refers to the', '["back-biters","rumour mongers","<u>envious ones</u>","treasury looters"]', 'Q.113:3 refers to the <u>envious ones</u> (al-hasid).', '{"bold":[],"italic":[],"underline":["envious ones"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ciihgp2dqonv19v7qgzrgdcw3', 'General Mathematics', 'JAMB', null, 2020, null, 'Two vectors are given by p = 3i - 2j + k and q = -i + j + 2k. Find a unit vector perpendicular to both p and q.', null, '["(-5i - 7j + k)/√75","(5i + 7j - k)/√75","(-5i - 7j + k)/√55","(5i + 7j - k)/√55"]', 1, 'p × q = -5i - 7j + k; unit = (-5i-7j+k)/√75. Key says (5i+7j-k)/√75.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Two vectors are given by p = 3i - 2j + k and q = -i + j + 2k. Find a unit vector perpendicular to both p and q.', '["(-5i - 7j + k)/√75","(5i + 7j - k)/√75","(-5i - 7j + k)/√55","(5i + 7j - k)/√55"]', 'Unit vector = <u>(5i + 7j - k)/√75</u> (per key).', '{"bold":[],"italic":[],"underline":["(5i + 7j - k)/√75"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ciil9if50074wj00a7ky53kn5', 'General Mathematics', 'JAMB', null, 2020, null, 'In a class of 35, 20 take math, 18 physics, and 5 take neither. How many take both?', null, '["6","7","8","9"]', 1, 'At least one = 30; both = 20 + 18 - 30 = 8. Key says 7.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In a class of 35, 20 take math, 18 physics, and 5 take neither. How many take both?', '["6","7","8","9"]', 'Both = <u>7</u> (per key).', '{"bold":[],"italic":[],"underline":["7"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cijbmdv9vfnmh62ymendgggt8', 'Chemistry', 'JAMB', null, 1991, null, 'Which of the following statements is <b>TRUE</b> of the complete hydrolysis of a glyceride by sodium hydroxide?', null, '["3 moles of NaOH are required for each mole of glyceride","3 moles of glycerol are produced","only one mole of soap is formed","Concentrated H2SO4 is essential for the completion of the reaction"]', 0, 'Complete hydrolysis of a triglyceride requires 3 moles of NaOH.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following statements is <b>TRUE</b> of the complete hydrolysis of a glyceride by sodium hydroxide?', '["3 moles of NaOH are required for each mole of glyceride","3 moles of glycerol are produced","only one mole of soap is formed","Concentrated H2SO4 is essential for the completion of the reaction"]', '<u>3 moles of NaOH</u> are required per mole of glyceride.', '{"bold":["TRUE"],"italic":[],"underline":["3 moles of NaOH are required for each mole of glyceride"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cijkp5nxzsuph0zjf9g41yjmj', 'Chemistry', 'JAMB', null, 2004, null, 'Hardness of water is caused by the presence of the ions of', null, '["calcium and magnesium","calcium and sodium","magnesium and silver","sodium and potassium"]', 0, 'Ca²⁺ and Mg²⁺ cause water hardness.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Hardness of water is caused by the presence of the ions of', '["calcium and magnesium","calcium and sodium","magnesium and silver","sodium and potassium"]', '<u>Calcium and magnesium</u> ions.', '{"bold":[],"italic":[],"underline":["calcium and magnesium"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cijxmo8ja1w4o30t7z8ro7uyp', 'Biology', 'JAMB', null, 1994, null, 'A man with blood group A is married to a woman with blood group A. Which of the following group combinations is possible if the family has three children?', null, '["B,A,AB","O,A,B","B,AB,AB","A,O,A"]', 3, 'Two A parents can have A and O children.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A man with blood group A is married to a woman with blood group A. Which of the following group combinations is possible if the family has three children?', '["B,A,AB","O,A,B","B,AB,AB","<u>A,O,A</u>"]', 'Two A parents can have <u>A and O children</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cik0rbnqmij4558ya8s6si1bv', 'General Mathematics', 'JAMB', null, 2020, null, 'If the SD of a data set is 5, find the variance.', null, '["25","10","5","2.5"]', 0, 'Variance = SD² = 25.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If the SD of a data set is 5, find the variance.', '["25","10","5","2.5"]', 'Variance = <u>25</u>.', '{"bold":[],"italic":[],"underline":["25"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cik18ko44kt0cnf65bfegtmry', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the rank of [[1, 2, 3], [2, 4, 6], [3, 6, 9]].', null, '["1","2","3","0"]', 0, 'Rows are multiples of each other; rank = 1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the rank of [[1, 2, 3], [2, 4, 6], [3, 6, 9]].', '["1","2","3","0"]', 'Rank = <u>1</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cikob1wfric35sfqzjuip6m72', 'Biology', 'JAMB', null, 2002, null, 'Birds which are large with long straight pointed beaks, long necks and long legs are likely to be', null, '["insect eaters","fish catchers","nectar feeders","fruit eaters"]', 1, 'Long straight beaks, necks, legs = fish catchers (herons, egrets).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Birds which are large with long straight pointed beaks, long necks and long legs are likely to be', '["insect eaters","fish catchers","nectar feeders","fruit eaters"]', '<u>Fish catchers</u>.', '{"bold":[],"italic":[],"underline":["fish catchers"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cikr3agkwdz0osshttdypbl63', 'Chemistry', 'JAMB', null, 2024, null, 'Which of the following is a mixture? I. Rusting of iron II. Melting of ice cream III. Burning of phosphorus IV. Urine', null, '["I&II only","I&III","II&IV","I-III","I-IV"]', 2, 'Melting of ice cream (physical change) and urine (mixture) are mixtures; rusting and burning are chemical changes.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is a mixture?<br>I. Rusting of iron<br>II. Melting of ice cream<br>III. Burning of phosphorus<br>IV. Urine', '["I&II only","I&III","<u>II&IV</u>","I-III","I-IV"]', '<u>Melting of ice cream and urine</u> are mixtures; rusting and burning are chemical changes.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ciku1y4r1zcybyoa3w1dw77ly', 'Biology', 'JAMB', null, 1993, null, 'The water-retention capacity of a soil indicates its', null, '["fertility","capillarity","aeration level","pH level"]', 1, 'Water-retention capacity indicates capillarity.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The water-retention capacity of a soil indicates its', '["fertility","<u>capillarity</u>","aeration level","pH level"]', 'Water-retention capacity indicates <u>capillarity</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cil6f99fqjfscgjjkkti3dnnx', 'General Mathematics', 'JAMB', null, 2020, null, 'Evaluate ∫e^(2x) sin 3x dx.', null, '["e^(2x)(2sin 3x - 3cos 3x)/13 + C","e^(2x)(3sin 3x - 2cos 3x)/13 + C","e^(2x)(3sin 3x + 2cos 3x)/13 + C","e^(2x)(3sin 3x + 2cos 3x)/13 + C"]', 0, 'Integration by parts twice: result = e^(2x)(2sin 3x - 3cos 3x)/13 + C.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Evaluate ∫e^(2x) sin 3x dx.', '["e^(2x)(2sin 3x - 3cos 3x)/13 + C","e^(2x)(3sin 3x - 2cos 3x)/13 + C","e^(2x)(3sin 3x + 2cos 3x)/13 + C","e^(2x)(3sin 3x + 2cos 3x)/13 + C"]', 'Integral = <u>e^(2x)(2sin 3x - 3cos 3x)/13 + C</u>.', '{"bold":[],"italic":[],"underline":["e^(2x)(2sin 3x - 3cos 3x)/13 + C"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cilgd51hjvf6ayb1k980ctsbs', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The battle of Khandaq was known as such because the', null, '["encounter took place near Khandaq","Muslims dug a trench as a war strategy","hypocrites protected Khandaq from enemies","Quraysh fell into a trench."]', 1, 'The Muslims dug a trench as a war strategy.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The battle of Khandaq was known as such because the', '["encounter took place near Khandaq","<u>Muslims dug a trench as a war strategy</u>","hypocrites protected Khandaq from enemies","Quraysh fell into a trench."]', '<u>Muslims dug a trench as a war strategy</u>.', '{"bold":[],"italic":[],"underline":["Muslims dug a trench as a war strategy"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cilszcw3es8lz19f1opscpeha', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve x² + 2ix - 1 = 0 in complex numbers.', null, '["±i","-i (repeated root)","±(1+i)","±(1-i)"]', 1, 'x² + 2ix - 1 = (x + i)² = 0, so x = -i (repeated root).', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Solve x² + 2ix - 1 = 0 in complex numbers.', '["±i","-i (repeated root)","±(1+i)","±(1-i)"]', 'x² + 2ix - 1 = (x + i)² = 0, so x = -i (repeated root).', '{"bold":[],"italic":[],"underline":["±1"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cim9d44fzrwxxflsy66rfxg02', 'Islamic Religious Studies', 'JAMB', null, 2011, null, 'Tajwid as one of the science of the Glorious Qur''an is important because', null, '["it allows for the understanding of history of the Glorious Qur''an","it provides the basis for the deeper understanding of the Glorious Qur''an","it provides the knowledge of correct pronunciation and recitation of the Glorious Qur''an","it increases the ability to recite and communicate in Arabic"]', 2, 'Tajwid teaches correct pronunciation and recitation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Tajwid as one of the science of the Glorious Qur''an is important because', '["it allows for the understanding of history of the Glorious Qur''an","it provides the basis for the deeper understanding of the Glorious Qur''an","<u>it provides the knowledge of correct pronunciation and recitation of the Glorious Qur''an</u>","it increases the ability to recite and communicate in Arabic"]', '<u>Tajwid</u> teaches correct pronunciation and recitation.', '{"bold":[],"italic":[],"underline":["it provides the knowledge of correct pronunciation and recitation of the Glorious Qur''an"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cimc9vb5x4hpp9wkxr7lwxvfy', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve 1/(x-1) + 1/(x-2) ≤ 0.', null, '["(1, 3/2] ∪ (2, ∞)","(1, 3/2]","(2, ∞)","(-∞, 1) ∪ [3/2, 2)"]', 3, '(2x-3)/((x-1)(x-2)) ≤ 0 → x < 1 or 3/2 ≤ x < 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve 1/(x-1) + 1/(x-2) ≤ 0.', '["(1, 3/2] ∪ (2, ∞)","(1, 3/2]","(2, ∞)","(-∞, 1) ∪ [3/2, 2)"]', '<u>x < 1 or 3/2 ≤ x < 2</u>.', '{"bold":[],"italic":[],"underline":["(-∞, 1) ∪ [3/2, 2)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cimgx8gpfjgrlbkuh1pvzmgyl', 'Biology', 'JAMB', null, 2002, null, 'In which of the following groups of fruits is the pericarp inseparable from the seed coat?', null, '["Nut","Follicle","Cypsela","Caryopsis"]', 3, 'Caryopsis has pericarp fused with seed coat.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In which of the following groups of fruits is the pericarp inseparable from the seed coat?', '["Nut","Follicle","Cypsela","Caryopsis"]', '<u>Caryopsis</u>.', '{"bold":[],"italic":[],"underline":["Caryopsis"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cimuzs8ide59xbb95tjwil29s', 'Chemistry', 'JAMB', null, 1987, null, 'When water drops are added to calcium carbide in a container and the gas produced is passed through a flame, it gives', null, '["oxyethylene flame","oxyhydrocarbon flame","oxyacetylene flame","oxymethane flame"]', 2, 'CaC2 + H2O → C2H2 (acetylene); burnt with O2 gives oxyacetylene flame.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When water drops are added to calcium carbide in a container and the gas produced is passed through a flame, it gives', '["oxyethylene flame","oxyhydrocarbon flame","oxyacetylene flame","oxymethane flame"]', '<u>Oxyacetylene flame</u> is produced.', '{"bold":[],"italic":[],"underline":["oxyacetylene flame"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cin0zdetk5gfx61aisqhrad5s', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve 1/(x - 1) + 1/(x - 2) ≤ 0.', null, '["(1, 3/2] ∪ (2, ∞)","(1, 3/2]","(2, ∞)","(-∞, 1) ∪ [3/2, 2)"]', 0, '(2x - 3)/((x-1)(x-2)) ≤ 0; sign chart gives 1 < x ≤ 3/2 or x > 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve 1/(x - 1) + 1/(x - 2) ≤ 0.', '["(1, 3/2] ∪ (2, ∞)","(1, 3/2]","(2, ∞)","(-∞, 1) ∪ [3/2, 2)"]', 'Solution: <u>(1, 3/2] ∪ (2, ∞)</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cinnlpkhotn4fymszlvpbm0z0', 'Chemistry', 'JAMB', null, 1998, null, 'A common characteristic shared by iron and aluminium is that both', null, '["are extracted by reduction methods","form only basic oxides","show oxidation states of +2 and +3","form soluble hydroxides"]', 0, 'Both are extracted by reduction methods.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A common characteristic shared by iron and aluminium is that both', '["are extracted by reduction methods","form only basic oxides","show oxidation states of +2 and +3","form soluble hydroxides"]', '<u>Both are extracted by reduction methods</u>.', '{"bold":[],"italic":[],"underline":["are extracted by reduction methods"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cinvf3igudkghis81ry6epa6h', 'Islamic Religious Studies', 'JAMB', null, 2002, null, 'Taftif in business transaction occurs when one of the partners', null, '["over-prices the goods","under-prices the commodity","tampers with the measure","refuses to pay for the goods"]', 2, 'Taftif means giving short measure (Q.83:1-3).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Taftif in business transaction occurs when one of the partners', '["over-prices the goods","under-prices the commodity","<u>tampers with the measure</u>","refuses to pay for the goods"]', '<u>Taftif</u> means giving short measure.', '{"bold":[],"italic":[],"underline":["tampers with the measure"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cio2rkdirlowq6v4jtchitz0e', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'In the law of inheritance, the term al-wasiyyah refers to', null, '["charity","benefit","bequest","gift"]', 2, 'Al-wasiyyah refers to a bequest.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the law of inheritance, the term al-wasiyyah refers to', '["charity","benefit","<u>bequest</u>","gift"]', '<u>Bequest</u>.', '{"bold":[],"italic":[],"underline":["bequest"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cioasq4yt09tgu6cvakpi5woq', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the derivative of log_x10.', null, '["-log₁₀e/(x(log₁₀x)²)","-log₁₀e/(x²(log₁₀x)²)","-log₁₀e/(log₁₀x)²","-log₁₀e/x"]', 0, 'y = log₁₀10/log₁₀x = 1/log₁₀x; dy/dx = -log₁₀e/(x(log₁₀x)²).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the derivative of log_x10.', '["-log₁₀e/(x(log₁₀x)²)","-log₁₀e/(x²(log₁₀x)²)","-log₁₀e/(log₁₀x)²","-log₁₀e/x"]', 'dy/dx = <u>-log₁₀e/(x(log₁₀x)²)</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cioexo8xcrdxzgiqe6z74p7sq', 'Chemistry', 'JAMB', null, 2024, null, 'Alkenes react with the following strong acids except i. HBr ii. H2SO4 iii. NaOH', null, '["III only","I only","I&II only","I&III only","II only"]', 0, 'NaOH is a base, not an acid; alkenes do not react with it.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Alkenes react with the following strong acids except<br>i. HBr<br>ii. H2SO4<br>iii. NaOH', '["<u>III only</u>","I only","I&II only","I&III only","II only"]', '<u>NaOH is a base</u>, not an acid; alkenes do not react with it.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ciokfa6zcoly2gjo7hylqnw8c', 'Chemistry', 'JAMB', null, 1985, null, 'In the course of an experiment, two gases X and Y were produced. X turned wet lead ethanoate to black and Y bleached moist litmus paper. What are the elements in each of the gases X and Y respectively?', null, '["H and S; Cl","H and O; Cl","H and S; C and O","H and Cl; S and O"]', 2, 'X is H2S (H and S); Y is Cl2 (Cl). Answer key says H and S; C and O.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the course of an experiment, two gases X and Y were produced. X turned wet lead ethanoate to black and Y bleached moist litmus paper. What are the elements in each of the gases X and Y respectively?', '["H and S; Cl","H and O; Cl","H and S; C and O","H and Cl; S and O"]', 'X is H2S (H and S); Y is Cl2 (Cl).', '{"bold":[],"italic":[],"underline":["H and S; C and O"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cioob3y2vv84d8btwiwcsc3wq', 'Chemistry', 'JAMB', null, 1983, null, 'An example of a <b>neutral oxide</b> is', null, '["Al2O3","NO2","CO2","CO","SO2"]', 3, 'CO is a neutral oxide.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An example of a <b>neutral oxide</b> is', '["Al2O3","NO2","CO2","CO","SO2"]', '<u>CO is a neutral oxide</u>.', '{"bold":["neutral oxide"],"italic":[],"underline":["CO"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ciotivj63441ch35t5sllg1n9', 'Chemistry', 'JAMB', null, 1989, null, 'Three liquids X, Y and Z containing only hydrogen and carbon were burnt on a spoon. X and Y burnt with sooty flames while Z did not. Y is able to discharge the colour of bromine water whereas X and Z cannot. Which of the liquids would be aromatic in nature?', null, '["X and Z","Y","X","Z"]', 2, 'X is aromatic (sooty flame, does not decolorize bromine).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Three liquids X, Y and Z containing only hydrogen and carbon were burnt on a spoon. X and Y burnt with sooty flames while Z did not. Y is able to discharge the colour of bromine water whereas X and Z cannot. Which of the liquids would be aromatic in nature?', '["X and Z","Y","X","Z"]', '<u>X is aromatic</u> (sooty flame, no bromine decolorization).', '{"bold":[],"italic":[],"underline":["X"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cip4sumpaepr6mwiqgmf3ddes', 'Government', 'JAMB', null, 2020, null, 'Which of the following advocates equitable distribution of wealth?', null, '["Socialism","Plutocracy","Capitalism","Aristocracy."]', 0, 'Socialism advocates equitable wealth distribution.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following advocates equitable distribution of wealth?', '["<u>Socialism</u>","Plutocracy","Capitalism","Aristocracy."]', '<u>Socialism</u>.', '{"bold":[],"italic":[],"underline":["Socialism"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cipifqtcodgyrygurzzw5o6eq', 'Islamic Religious Studies', 'JAMB', null, 2011, null, 'The outcome of the Prophet''s visit to <b>Cave Hira</b> was', null, '["compilation of the Glorious Qur''an","revelation of the Glorious Qur''an","award of chieftaincy title by the Makkan aristocrats","his resolve to migrate to Madinah"]', 1, 'The first revelation came to the Prophet in Cave Hira.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The outcome of the Prophet''s visit to <b>Cave Hira</b> was', '["compilation of the Glorious Qur''an","<u>revelation of the Glorious Qur''an</u>","award of chieftaincy title by the Makkan aristocrats","his resolve to migrate to Madinah"]', '<u>The first revelation</u> came to the Prophet in Cave Hira.', '{"bold":["Cave Hira"],"italic":[],"underline":["revelation of the Glorious Qur''an"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cipywtca6race9jk3al6rbbtc', 'Chemistry', 'JAMB', null, 1996, null, 'Oxygen gas can be prepared by heating', null, '["ammonium trioxonitrate(V)","ammonium trioxonitrate(III)","potassium trioxochlorate(V)","manganese(IV) oxide"]', 2, '2KClO3 → 2KCl + 3O2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Oxygen gas can be prepared by heating', '["ammonium trioxonitrate(V)","ammonium trioxonitrate(III)","potassium trioxochlorate(V)","manganese(IV) oxide"]', '<u>2KClO3 → 2KCl + 3O2</u>.', '{"bold":[],"italic":[],"underline":["potassium trioxochlorate(V)"],"fillBlanks":[]}');
