insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ciqjbvj2g2dal5xryawtlbsy9', 'Government', 'JAMB', null, 2020, null, 'A typical form of delegated legislation is', null, '["an act","a decree","a bill","a bye-law"]', 3, 'A bye-law is a form of delegated legislation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A typical form of delegated legislation is', '["an act","a decree","a bill","<u>a bye-law</u>"]', '<u>A bye-law</u>.', '{"bold":[],"italic":[],"underline":["a bye-law"],"fillBlanks":[]}');
