insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cirlfpaunxx5kjuwmd6z8wfko', 'General Mathematics', 'JAMB', null, 2020, null, 'Evaluate 100! (mod 101).', null, '["100","1","50","0"]', 1, 'By Wilson''s theorem, 100! ≡ -1 ≡ 100 mod 101. Key says 1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Evaluate 100! (mod 101).', '["100","1","50","0"]', '100! ≡ <u>100</u> mod 101 (key says 1).', '{"bold":[],"italic":[],"underline":["1"],"fillBlanks":[]}');
