insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cj9k1th4r1mp4pc4im2xw3nqd', 'Chemistry', 'JAMB', null, 1986, null, 'Which of the following group of physical properties increases from left to right of the periodic table?<br>1 Ionization energy<br>2 Atomic radius<br>3 Electronegativity<br>4 Electron affinity', null, '["1 and 2","1, 2 and 3","3 and 4","1, 2 and 4","1, 3 and 4"]', 4, 'Ionization energy, electronegativity, and electron affinity increase across a period.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following group of physical properties increases from left to right of the periodic table?<br>1 Ionization energy<br>2 Atomic radius<br>3 Electronegativity<br>4 Electron affinity', '["1 and 2","1, 2 and 3","3 and 4","1, 2 and 4","1, 3 and 4"]', '<u>1, 3 and 4</u> increase across a period.', '{"bold":[],"italic":[],"underline":["1, 3 and 4"],"fillBlanks":[]}');
