insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cj9sf6wb7vwpcs974jc4zqtz5', 'Government', 'JAMB', null, 2020, null, 'Which question paper type of government is given to you?', null, '["Type D","Type I","Type B","Type U"]', 3, 'The question paper type is Type U.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which question paper type of government is given to you?', '["Type D","Type I","Type B","<u>Type U</u>"]', '<u>Type U</u>.', '{"bold":[],"italic":[],"underline":["Type U"],"fillBlanks":[]}');
