insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cj9wdx3amr81ms67utnc2tr4c', 'Biology', 'JAMB', null, 2001, null, 'Carbon(IV) oxide content of the atmosphere is least affected by', null, '["cutting down and clearing of forest","forest fires","burning of fossil fuels","plant and animal respiration"]', 3, 'Respiration is part of the natural carbon cycle.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Carbon(IV) oxide content of the atmosphere is least affected by', '["cutting down and clearing of forest","forest fires","burning of fossil fuels","plant and animal respiration"]', '<u>Plant and animal respiration</u> is part of the natural cycle.', '{"bold":[],"italic":[],"underline":["plant and animal respiration"],"fillBlanks":[]}');
