insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjarnrgnzq4sfn2dh2yipxegf', 'Biology', 'JAMB', null, 1994, null, 'In a food chain involving a primary producer, a primary consumer as well as a secondary consumer, the sharing of trophic energy is in the form that the', null, '["primary consumer has more energy than the primary producer","secondary consumer takes up all the energy contents of the primary consumer","energy is shared equally between the three groups of organism","secondary consumer gets only a small portion of the energy contained in the primary producer"]', 3, 'The secondary consumer gets only a small portion of energy.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In a food chain involving a primary producer, a primary consumer as well as a secondary consumer, the sharing of trophic energy is in the form that the', '["primary consumer has more energy than the primary producer","secondary consumer takes up all the energy contents of the primary consumer","energy is shared equally between the three groups of organism","<u>secondary consumer gets only a small portion of the energy contained in the primary producer</u>"]', 'The <u>secondary consumer gets only a small portion of energy</u>.', null);
