insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjasjefzhiabxaiwoa36zil6m', 'Biology', 'JAMB', null, 1999, null, 'From an evolutionary standpoint, the older a fossil- bearing rock is the more likely it is to contain', null, '["aves as opposed to amphibians","invertebrates as opposed vertebrates","angiosperms as opposed to algae","vertebrates as opposed to invertebrates."]', 1, 'invertebrates as opposed vertebrates is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'From an evolutionary standpoint, the older a fossil- bearing rock is the more likely it is to contain', '["aves as opposed to amphibians","<u>invertebrates as opposed vertebrates</u>","angiosperms as opposed to algae","vertebrates as opposed to invertebrates."]', 'invertebrates as opposed vertebrates is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjax6o4b32w84q0c32cjo7gpi', 'Chemistry', 'JAMB', null, 2004, null, 'Which of these compounds is a <b>normal salt</b>?', null, '["Na2CO3","NaHCO3","NaHSO4","NaHS"]', 0, 'Na2CO3 is a normal salt.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of these compounds is a <b>normal salt</b>?', '["Na2CO3","NaHCO3","NaHSO4","NaHS"]', '<u>Na2CO3</u> is a normal salt.', '{"bold":["normal salt"],"italic":[],"underline":["Na2CO3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjb40pplc8ojycj9lpkjduxuw', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the remainder when the polynomial x⁸¹ + x⁴⁹ + x²⁵ + x⁹ + x is divided by x³ - x.', null, '["5x","4x","3x","0"]', 1, 'Since x³ = x, each odd power reduces; remainder = 5x. Key says 4x.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the remainder when the polynomial x⁸¹ + x⁴⁹ + x²⁵ + x⁹ + x is divided by x³ - x.', '["5x","4x","3x","0"]', 'Remainder = <u>4x</u> (per key).', '{"bold":[],"italic":[],"underline":["4x"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjbcbp6uiyn43juzqcvkm2ahx', 'Biology', 'JAMB', null, 1997, null, 'Adaptive features of plants to desert conditions include', null, '["thick barks, succulent stems and sunken stomata","thin barks, succulent stems and sunken stomata","thin barks, air floats on stems and sunken stomata","air spaces in tissues, adventitious roots and thick barks."]', 0, 'thick barks, succulent stems and sunken stomata is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Adaptive features of plants to desert conditions include', '["<u>thick barks, succulent stems and sunken stomata</u>","thin barks, succulent stems and sunken stomata","thin barks, air floats on stems and sunken stomata","air spaces in tissues, adventitious roots and thick barks."]', 'thick barks, succulent stems and sunken stomata is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjbgdzixfj6fvz7n6f0vu7ay7', 'Christian Religious Studies', 'JAMB', null, 2020, null, '''Do you want me to release for you the King of the Jews?'' According to Mark, Pilate asked the question above because he', null, '["wanted to release Barabbas instead of Jesus","perceived that the Jews were envious of Jesus","was not willing to release Jesus","was afraid of riot of the Jews"]', 1, 'Pilate perceived the Jews were envious of Jesus.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '''Do you want me to release for you the King of the Jews?'' According to Mark, Pilate asked the question above because he', '["wanted to release Barabbas instead of Jesus","<u>perceived that the Jews were envious of Jesus</u>","was not willing to release Jesus","was afraid of riot of the Jews"]', '<u>Perceived that the Jews were envious of Jesus</u> (Mark 15:9-10).', '{"bold":[],"italic":[],"underline":["perceived that the Jews were envious of Jesus"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjbggi6bha4lxlke84ifuiiw5', 'Government', 'JAMB', null, 2020, null, 'The fundamental rights of citizens include rights to', null, '["free education, employment and freedom of thought","life, speech and association","life, liberty and property","association, property and social security"]', 1, 'Fundamental rights include right to life, speech, and association.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The fundamental rights of citizens include rights to', '["free education, employment and freedom of thought","<u>life, speech and association</u>","life, liberty and property","association, property and social security"]', 'Rights to <u>life, speech and association</u>.', '{"bold":[],"italic":[],"underline":["life, speech and association"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjbk17w30dukkkginf77ez5bg', 'General Mathematics', 'WAEC', null, 2020, null, 'Two cards are drawn without replacement from a deck. Find the probability both are kings.', null, '["1/221","1/169","1/13","4/663"]', 0, 'P = (4/52)(3/51) = 1/221.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Two cards are drawn without replacement from a deck. Find the probability both are kings.', '["1/221","1/169","1/13","4/663"]', 'P = <u>1/221</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjbnfm6v8taqlf82xszz9bu7r', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'At Gibeon, the LORD appeared to Solomon in a', null, '["vision","trance","dream","whirlwind."]', 2, 'The LORD appeared to Solomon in a dream.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'At Gibeon, the LORD appeared to Solomon in a', '["vision","trance","<u>dream</u>","whirlwind."]', '<u>Dream</u> (1 Kings 3:5).', '{"bold":[],"italic":[],"underline":["dream"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjbs2kd8l3szi6cwla535l9ci', 'General Mathematics', 'JAMB', null, 2020, null, 'On R, a*b = a + b - 2. Find the inverse of 4.', null, '["0","-4","4","2"]', 0, 'e = 2; 4*x = 2 → 4+x-2 = 2 → x = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'On R, a*b = a + b - 2. Find the inverse of 4.', '["0","-4","4","2"]', 'Inverse = <u>0</u>.', '{"bold":[],"italic":[],"underline":["0"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjbt2is32ptikgiug8ou7pozj', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'According to Galatians, Christians are redeemed in Christ to', null, '["receive the blessing of Abraham","be justified","become sons of the Kingdom","receive the Holy Spirit."]', 0, 'They are redeemed to receive the blessing of Abraham.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to Galatians, Christians are redeemed in Christ to', '["<u>receive the blessing of Abraham</u>","be justified","become sons of the Kingdom","receive the Holy Spirit."]', '<u>Receive the blessing of Abraham</u> (Galatians 3:13-14).', '{"bold":[],"italic":[],"underline":["receive the blessing of Abraham"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjbx7aelbx1ksg1jgv8jfzazr', 'Biology', 'JAMB', null, 1992, null, 'A major difference between platyhelminthes and coelenterates is that platyhelminthes', null, '["are multicellular","have developed a mesoderm","reproduce sexually","reproduce asexually"]', 1, 'Platyhelminthes have developed a mesoderm.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A major difference between <b>platyhelminthes</b> and <b>coelenterates</b> is that platyhelminthes', '["are multicellular","<u>have developed a mesoderm</u>","reproduce sexually","reproduce asexually"]', '<u>Platyhelminthes have developed a mesoderm</u>.', null);
