insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjcj6lw6nz0bpa6c4dwo43f5l', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'One of the sins of Manasseh for which the LORD sent bands of the Chaldeans, Syrians, Moabites and Ammonites to destroy Judah was', null, '["the release of a thousand captives","the shedding of innocent blood","his failure to obey God''s prophets","the arrest of the king of Babylon."]', 1, 'Manasseh shed innocent blood.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One of the sins of Manasseh for which the LORD sent bands of the Chaldeans, Syrians, Moabites and Ammonites to destroy Judah was', '["the release of a thousand captives","<u>the shedding of innocent blood</u>","his failure to obey God''s prophets","the arrest of the king of Babylon."]', '<u>The shedding of innocent blood</u> (2 Kings 24:2-4).', '{"bold":[],"italic":[],"underline":["the shedding of innocent blood"],"fillBlanks":[]}');
