insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cje0fz8iv4ike6mt2uri2y9go', 'Islamic Religious Studies', 'JAMB', null, 2020, null, '''A man came to the Prophet (S.A.W) and said: O Apostle of God, show me a work which if I do, it will make me beloved of God and beloved of people. He answered, be indifferent to this world ...'' This is Hadith 31 of an-Nawawi and it teaches', null, '["love of the world","renunciation of the world","love of people","love of God"]', 1, 'It teaches renunciation of the world.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '''A man came to the Prophet (S.A.W) and said: O Apostle of God, show me a work which if I do, it will make me beloved of God and beloved of people. He answered, be indifferent to this world ...'' This is Hadith 31 of an-Nawawi and it teaches', '["love of the world","<u>renunciation of the world</u>","love of people","love of God"]', '<u>Renunciation of the world</u>.', '{"bold":[],"italic":[],"underline":["renunciation of the world"],"fillBlanks":[]}');
