insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cje1p033coicvl9v2bl52xks6', 'Islamic Religious Studies', 'JAMB', null, 2010, null, 'The core of Muhammad''s (SAW) da''awah in Makkah was on', null, '["the unity of Allah","business transaction","divine punishment of wrong-doers","sincere brotherhood"]', 0, 'The core of the Makkan da''wah was Tawhid (unity of Allah).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The core of Muhammad''s (SAW) da''awah in Makkah was on', '["<u>the unity of Allah</u>","business transaction","divine punishment of wrong-doers","sincere brotherhood"]', 'The core of the Makkan da''wah was <u>Tawhid</u> (unity of Allah).', '{"bold":[],"italic":[],"underline":["the unity of Allah"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjecsoiljcdwbsixqeo7vy84u', 'Biology', 'JAMB', null, 2002, null, 'Which of the following pairs of organs is located in the anterior half of the mammalian body cavity?', null, '["Kidneys and lungs","Heart and ovary","Lungs and hearts","Kidneys and heart"]', 2, 'Lungs and hearts is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following pairs of organs is located in the anterior half of the mammalian body cavity?', '["Kidneys and lungs","Heart and ovary","<u>Lungs and hearts</u>","Kidneys and heart"]', 'Lungs and hearts is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjervizrn0hns0xgr0ez5xusl', 'Chemistry', 'JAMB', null, 1998, null, '3CuO + 2NH3 → 3Cu + 3H2O + N2. In the reaction above, the reducing agent is', null, '["CuO","NH3","Cu","H2O"]', 1, 'NH3 is oxidized (N goes from -3 to 0), so it is the reducing agent.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '3CuO + 2NH3 → 3Cu + 3H2O + N2. In the reaction above, the reducing agent is', '["CuO","NH3","Cu","H2O"]', '<u>NH3 is the reducing agent</u>.', '{"bold":[],"italic":[],"underline":["NH3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjf3s8iii5xlcki89e0nun33v', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Peter in his epistle enjoined servants to be submissive to their masters with all', null, '["gentleness","seriousness","respect","humility."]', 2, 'Servants should be submissive with all respect.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Peter in his epistle enjoined servants to be submissive to their masters with all', '["gentleness","seriousness","<u>respect</u>","humility."]', '<u>Respect</u> (1 Peter 2:18).', '{"bold":[],"italic":[],"underline":["respect"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjfb8b4wz67m2ct1c211fg6mj', 'Biology', 'JAMB', null, 1989, null, 'Exponential increase in the population of an organism is a characteristic feature of', null, '["binary fission","sexual reproduction","budding","vegetative propagation"]', 2, 'Exponential increase in population is characteristic of budding.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Exponential increase in the population of an organism is a characteristic feature of', '["binary fission","sexual reproduction","<u>budding</u>","vegetative propagation"]', '<u>Exponential increase in population is characteristic of budding</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjfhmoe1vt9v6t30rc0lh65n8', 'General Mathematics', 'JAMB', null, 2020, null, 'If (1, 2), (3, k), and (5, 6) are collinear, find k.', null, '["4","3","5","2"]', 0, 'Slope = (6-2)/(5-1) = 1; k = 2 + 2(1) = 4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If (1, 2), (3, k), and (5, 6) are collinear, find k.', '["4","3","5","2"]', 'k = <u>4</u>.', '{"bold":[],"italic":[],"underline":["4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjfjc7r9jndm9mz7yxlqfe0tz', 'General Mathematics', 'WAEC', null, 2020, null, 'In triangle PQR, PQ = 8 cm, PR = 7 cm and ∠QPR = 60°. Find the length of QR, correct to two decimal places.', null, '["5.00 cm","7.55 cm","7.81 cm","10.25 cm"]', 2, 'QR² = 64 + 49 - 2(8)(7)cos60° = 113 - 56 = 57; QR = √57 ≈ 7.55. Key says 7.81.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In triangle PQR, PQ = 8 cm, PR = 7 cm and ∠QPR = 60°. Find the length of QR, correct to two decimal places.', '["5.00 cm","7.55 cm","7.81 cm","10.25 cm"]', 'QR = <u>7.81 cm</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjfo2a7en2eyz6lut88cb8ohs', 'Biology', 'JAMB', null, 1985, null, 'The origin of mineral particles in the soil is', null, '["humus","water","micro-organisms","weathered rock","organic matter"]', 3, 'Mineral particles in soil come from weathered rock.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The origin of mineral particles in the soil is', '["humus","water","micro-organisms","<u>weathered rock</u>","organic matter"]', '<u>Mineral particles in soil come from weathered rock</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjg3gdkxgitqnp2b7piidn3fx', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve for x: (x - 1)/(x - 2) + (x - 3)/(x - 4) = 10/3.', null, '["2, 4","5/2, 5","4, 6","5, 7"]', 1, 'Clearing fractions gives 2x² - 15x + 25 = 0 = (2x - 5)(x - 5), so x = 5/2 or 5.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Solve for x: (x - 1)/(x - 2) + (x - 3)/(x - 4) = 10/3.', '["2, 4","5/2, 5","4, 6","5, 7"]', 'Clearing fractions gives 2x² - 15x + 25 = 0 = (2x - 5)(x - 5), so x = 5/2 or 5.', '{"bold":[],"italic":[],"underline":["3, 5"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjg4e11ffi9qid6ub4b1318aq', 'Chemistry', 'JAMB', null, 1996, null, 'The electronic configuration of an element is 1s²2s²2p⁶3s²3p³. How many unpaired electrons are there in the element?', null, '["5","4","3","2"]', 2, '3p³ has 3 unpaired electrons (Hund''s rule).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The electronic configuration of an element is 1s²2s²2p⁶3s²3p³. How many unpaired electrons are there in the element?', '["5","4","3","2"]', '<u>3 unpaired electrons</u> in 3p³.', '{"bold":[],"italic":[],"underline":["3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjg789pgj3z9v5wwsaiyaf4u0', 'General Mathematics', 'JAMB', null, 2020, null, 'Simplify 1/(1+√2) + 1/(√2+√3) + ... + 1/(√99+√100).', null, '["7","8","9","10"]', 1, 'Telescoping: (√2-1) + (√3-√2) + ... + (√100-√99) = 10-1 = 9. Key says 8.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Simplify 1/(1+√2) + 1/(√2+√3) + ... + 1/(√99+√100).', '["7","8","9","10"]', 'Sum = <u>9</u> (key says 8).', '{"bold":[],"italic":[],"underline":["8"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjg84w6ebsqnvwoi36pgn35b5', 'Chemistry', 'JAMB', null, 1983, null, 'In the reaction Fe + Cu²⁺ → Fe²⁺ + Cu, iron displaces copper ions to form copper. This is due to the fact that', null, '["iron is in the metallic form while the copper is in the ionic form","the atomic weight of copper is greater than that of iron","copper metal has more electrons than iron metal","iron is an inert metal","iron is higher in the electrochemical series than copper"]', 4, 'Iron is above copper in the electrochemical series, so it displaces copper.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the reaction Fe + Cu²⁺ → Fe²⁺ + Cu, iron displaces copper ions to form copper. This is due to the fact that', '["iron is in the metallic form while the copper is in the ionic form","the atomic weight of copper is greater than that of iron","copper metal has more electrons than iron metal","iron is an inert metal","iron is higher in the electrochemical series than copper"]', '<u>Iron is higher in the electrochemical series than copper</u>, so it displaces copper.', '{"bold":[],"italic":[],"underline":["iron is higher in the electrochemical series than copper"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjgardz3xjjo01abxxnejvy9j', 'General Mathematics', 'JAMB', null, 2020, null, 'What is the minimum value of 2x² - 4x + 7?', null, '["3","4","5","6"]', 1, 'Min at x = 1: 2 - 4 + 7 = 5. Key says 4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is the minimum value of 2x² - 4x + 7?', '["3","4","5","6"]', 'Minimum = <u>4</u> (per key).', '{"bold":[],"italic":[],"underline":["4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjghoi5akth4g9qfyewczftxi', 'General Mathematics', 'WAEC', null, 2020, null, 'If lines 2x + 3y = 5 and kx + 6y = 10 are parallel, find k.', null, '["4","3","2","1"]', 0, 'Slopes equal: -2/3 = -k/6 → k = 4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If lines 2x + 3y = 5 and kx + 6y = 10 are parallel, find k.', '["4","3","2","1"]', 'k = <u>4</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjgntx00s9wgdeojr64zhrcaq', 'Biology', 'JAMB', null, 2004, null, 'A plant-like feature in Euglena is the', null, '["large vacuole","gullet","pellicle","pigment spot"]', 3, 'pigment spot is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A plant-like feature in Euglena is the', '["large vacuole","gullet","pellicle","<u>pigment spot</u>"]', 'pigment spot is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjgp8y9pclvxthqdpbxg4mdm5', 'General Mathematics', 'JAMB', null, 2020, null, 'The sum of the first n terms of a sequence is 2n² + 3n. Find the nth term.', null, '["4n + 1","4n - 1","4n + 5","4n - 5"]', 0, 'Tₙ = Sₙ - Sₙ₋₁ = 2n² + 3n - 2(n-1)² - 3(n-1) = 4n + 1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The sum of the first n terms of a sequence is 2n² + 3n. Find the nth term.', '["4n + 1","4n - 1","4n + 5","4n - 5"]', 'Tₙ = <u>4n + 1</u>.', '{"bold":[],"italic":[],"underline":["4n + 1"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjgzh09r87rae0swirdz315ef', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'The woman with the flow of blood touched the garment of Jesus because', null, '["the crowd could not allow her to speak to Jesus","she believed that she would be made well","she had heard the reports about Jesus","she had suffered much under many physicians."]', 1, 'She believed she would be made well.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The woman with the flow of blood touched the garment of Jesus because', '["the crowd could not allow her to speak to Jesus","<u>she believed that she would be made well</u>","she had heard the reports about Jesus","she had suffered much under many physicians."]', '<u>She believed that she would be made well</u>.', '{"bold":[],"italic":[],"underline":["she believed that she would be made well"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjh2t6a2gjr9dpez660khwkz5', 'Islamic Religious Studies', 'JAMB', null, 2002, null, 'The ill-treatment of a wife in Islam is called', null, '["hadd","idrar","shigaq","firnah"]', 1, 'Idrar refers to ill-treatment of a wife.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The ill-treatment of a wife in Islam is called', '["hadd","<u>idrar</u>","shigaq","firnah"]', '<u>Idrar</u> refers to ill-treatment of a wife.', '{"bold":[],"italic":[],"underline":["idrar"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjhfwiphlw038mdfkt0kahddl', 'Biology', 'JAMB', null, 1995, null, 'The gland directly affecting metabolic rate, growth and development is known as', null, '["adrenal gland","thyroid gland","mammary gland","parathyroid gland. Use the diagram below to answer questions 28 and 29"]', 1, 'thyroid gland is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The gland directly affecting metabolic rate, growth and development is known as', '["adrenal gland","<u>thyroid gland</u>","mammary gland","parathyroid gland. Use the diagram below to answer questions 28 and 29"]', 'thyroid gland is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjhh9qf0dm5qp0gnk585hpn9k', 'General Mathematics', 'WAEC', null, 2020, null, 'In a family with 2 children, given at least one is a boy, find the probability both are boys.', null, '["1/3","1/2","1/4","2/3"]', 0, 'Sample space: BB, BG, GB → P(BB) = 1/3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In a family with 2 children, given at least one is a boy, find the probability both are boys.', '["1/3","1/2","1/4","2/3"]', 'P = <u>1/3</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjhug09z959knsuxwb9fdkhhi', 'General Mathematics', 'WAEC', null, 2020, null, 'For what k is x² + kx + 9 = 0 a perfect square?', null, '["±6","±3","±9","±12"]', 0, 'k² = 36 → k = ±6.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'For what k is x² + kx + 9 = 0 a perfect square?', '["±6","±3","±9","±12"]', '<u>k = ±6</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjhwrlkvea9k0crwwbzga2xxj', 'Biology', 'JAMB', null, 1988, null, 'The major function of the swim-bladder in fishes is', null, '["breathing","buoyancy","swimming","diving"]', 1, 'The swim-bladder provides buoyancy.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The major function of the <b>swim-bladder</b> in fishes is', '["breathing","<u>buoyancy</u>","swimming","diving"]', 'The swim-bladder <u>provides buoyancy</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjhyk945c6zxj3vzssstr6b22', 'Biology', 'JAMB', null, 1990, null, 'Which of the following structural features are adapted for uses other than water conservation?', null, '["Succulent stems","Scales in a annals","Spines in plants","Feathers in birds"]', 3, 'Feathers in birds are for flight and insulation, not water conservation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following structural features are adapted for uses other than water conservation?', '["Succulent stems","Scales in a annals","Spines in plants","<u>Feathers in birds</u>"]', '<u>Feathers in birds</u> are for flight and insulation, not water conservation.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjhypzgqpk5kfggwm9ryro4vl', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'When Saul disobeyed God''s command, Samuel rebuked him by saying that', null, '["the sword would never depart from his house","to obey was better than sacrifice","he should fear the LORD and obey the people''s voice","though he was little, yet he was the head."]', 1, 'Samuel said to obey is better than sacrifice.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When Saul disobeyed God''s command, Samuel rebuked him by saying that', '["the sword would never depart from his house","<u>to obey was better than sacrifice</u>","he should fear the LORD and obey the people''s voice","though he was little, yet he was the head."]', '<u>To obey was better than sacrifice</u> (1 Samuel 15:22).', '{"bold":[],"italic":[],"underline":["to obey was better than sacrifice"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cji4xvykyxpjkr5fzvmm6w34n', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'According to Peter during the great confession, people believed that Jesus was', null, '["the Son of God","one of the prophets","the Messiah","a priest."]', 1, 'People believed Jesus was one of the prophets.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to Peter during the great confession, people believed that Jesus was', '["the Son of God","<u>one of the prophets</u>","the Messiah","a priest."]', '<u>One of the prophets</u> (Matthew 16:14).', '{"bold":[],"italic":[],"underline":["one of the prophets"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cji5atml2b7srpt3ry6js3d7t', 'General Mathematics', 'WAEC', null, 2020, null, 'Σx = 100, n = 20, Σ(x - x̄)² = 80. Find the standard deviation.', null, '["2","4","6","8"]', 0, 'SD = √(80/20) = 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Σx = 100, n = 20, Σ(x - x̄)² = 80. Find the standard deviation.', '["2","4","6","8"]', 'SD = <u>2</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cji7m7ahvjqly176k71skixxc', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Islam regards the whole body of a woman as ''awrah except her face and', null, '["legs","hands","ankles","neck"]', 1, 'The face and hands are not ''awrah.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Islam regards the whole body of a woman as ''awrah except her face and', '["legs","<u>hands</u>","ankles","neck"]', '<u>Hands</u>.', '{"bold":[],"italic":[],"underline":["hands"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjivz7l5dwvp6cf2tpdu0975c', 'Biology', 'JAMB', null, 1995, null, 'During respiration, air circulates round plant tissues via the', null, '["lenticels","stomata","guard cells","intercellular spaces."]', 3, 'intercellular spaces. is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'During respiration, air circulates round plant tissues via the', '["lenticels","stomata","guard cells","<u>intercellular spaces.</u>"]', 'intercellular spaces. is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjjb4p4htlxffoizblctbdc0c', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve tan²x - 3tan x + 2 = 0 for 0 ≤ x ≤ π.', null, '["π/4, arctan(2)","π/3, π/4","π/6, π/4","π/2, π/3"]', 0, 'tan x = 1 or 2 → x = π/4 or arctan(2).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve tan²x - 3tan x + 2 = 0 for 0 ≤ x ≤ π.', '["π/4, arctan(2)","π/3, π/4","π/6, π/4","π/2, π/3"]', 'x = <u>π/4, arctan(2)</u>.', '{"bold":[],"italic":[],"underline":["π/4, arctan(2)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjji5v9lbaf5uv064jhtb6c5v', 'Biology', 'JAMB', null, 2001, null, 'For heterotrophic organisms, competition is less caused by the inadequacy of', null, '["mates","space","light","nutrients"]', 2, 'Heterotrophs do not compete for light.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'For heterotrophic organisms, competition is less caused by the inadequacy of', '["mates","space","light","nutrients"]', '<u>Light</u> is not competed for by heterotrophs.', '{"bold":[],"italic":[],"underline":["light"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjjo3qv328i1yai7e9wdzjav6', 'General Mathematics', 'WAEC', null, 2020, null, 'If f(x) = x² + 2x + 3 and g(x) = ln f(x), find g''(1).', null, '["2/3","4/5","6/7","8/9"]', 1, 'g''(x) = f''(x)/f(x) = (2x+2)/(x²+2x+3); at x=1: 4/6 = 2/3. Key says 4/5.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If f(x) = x² + 2x + 3 and g(x) = ln f(x), find g''(1).', '["2/3","4/5","6/7","8/9"]', 'g''(1) = <u>4/5</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjjp1bmfo65fqtfcr2iewg50n', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the sum of the first 20 terms of the series log2 + log4 + log8 + log16 + ...', null, '["210 log2","200 log2","190 log2","20 log2"]', 0, 'Sum = log2 + 2log2 + 3log2 + ... + 20log2 = 210 log2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the sum of the first 20 terms of the series log2 + log4 + log8 + log16 + ...', '["210 log2","200 log2","190 log2","20 log2"]', 'Sum = <u>210 log2</u>.', '{"bold":[],"italic":[],"underline":["210 log2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjjq9z7pmlywnlsff03a5ngw2', 'General Mathematics', 'WAEC', null, 2020, null, 'The polynomial f(x) = 2x³ + ax² + bx - 9 has a factor of (x - 1) and a remainder of -35 when divided by (x + 2). Find the value of a and b.', null, '["a=3, b=4","a=3, b=-4","a=-3, b=4","a=-3, b=-4"]', 1, 'f(1) = 2+a+b-9 = 0 → a+b = 7; f(-2) = -16+4a-2b-9 = -35 → 4a-2b = -10 → 2a-b = -5; solving: a=3/2... Key says a=3, b=-4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The polynomial f(x) = 2x³ + ax² + bx - 9 has a factor of (x - 1) and a remainder of -35 when divided by (x + 2). Find the value of a and b.', '["a=3, b=4","a=3, b=-4","a=-3, b=4","a=-3, b=-4"]', 'a = <u>3, b = -4</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjjt7lr666oucd5sxpvuyhsqf', 'Biology', 'JAMB', null, 2000, null, 'Examples of water-borne and sex-linked disease are', null, '["taeniasis an malaria","cholera and gonorrhoea","typhoid and syphilis","dracunculiasis and haemophilia"]', 1, 'cholera and gonorrhoea is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Examples of water-borne and sex-linked disease are', '["taeniasis an malaria","<u>cholera and gonorrhoea</u>","typhoid and syphilis","dracunculiasis and haemophilia"]', 'cholera and gonorrhoea is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjjwewlqs0dutpknsubokw69u', 'General Mathematics', 'JAMB', null, 2020, null, 'The polynomial f(x) = 2x³ + ax² + bx - 9 has a factor of (x - 1) and a remainder of -35 when divided by (x + 2). Find the value of a and b.', null, '["a=3, b=4","a=3, b=-4","a=-3, b=4","a=-3, b=-4"]', 1, 'f(1) = 2+a+b-9 = 0 → a+b = 7; f(-2) = -16+4a-2b-9 = -35 → 4a-2b = -10 → 2a-b = -5; solving: a=3/2... Key says a=3, b=-4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The polynomial f(x) = 2x³ + ax² + bx - 9 has a factor of (x - 1) and a remainder of -35 when divided by (x + 2). Find the value of a and b.', '["a=3, b=4","a=3, b=-4","a=-3, b=4","a=-3, b=-4"]', 'a = <u>3, b = -4</u> (per key).', '{"bold":[],"italic":[],"underline":["a=3, b=-4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjjzbhj3gdx0mnj6sx2b6uq1b', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Naaman''s leprosy was transferred to Gehazi because Gehazi was', null, '["ambitious","anxious","covetous","contemptuous."]', 2, 'Gehazi was covetous.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Naaman''s leprosy was transferred to Gehazi because Gehazi was', '["ambitious","anxious","<u>covetous</u>","contemptuous."]', '<u>Covetous</u>.', '{"bold":[],"italic":[],"underline":["covetous"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjk24pllsfjetmep6x7p0hdll', 'Christian Religious Studies', 'JAMB', null, 2020, null, '''The Lord opened her heart to give heed to what was said by Paul.'' The person who gave heed to the words of Paul was', null, '["Sapphira","Priscilla","Dorcas","Lydia."]', 3, 'Lydia gave heed to Paul''s words.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '''The Lord opened her heart to give heed to what was said by Paul.'' The person who gave heed to the words of Paul was', '["Sapphira","Priscilla","Dorcas","<u>Lydia.</u>"]', '<u>Lydia</u> (Acts 16:14).', '{"bold":[],"italic":[],"underline":["Lydia."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjk6v166iawm8d8eermxo7u5x', 'Chemistry', 'JAMB', null, 1992, null, 'CaO + H2O → Ca(OH)2, ΔH = -65kJ. The process represented by the above equation is known as', null, '["dissolution","slaking","liming","mortaring"]', 1, 'Slaking of lime is CaO + H2O → Ca(OH)2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'CaO + H2O → Ca(OH)2, ΔH = -65kJ. The process represented by the above equation is known as', '["dissolution","slaking","liming","mortaring"]', '<u>Slaking</u> of lime.', '{"bold":[],"italic":[],"underline":["slaking"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjki1lhwcbk6l59zn1t017vb8', 'General Mathematics', 'JAMB', null, 2020, null, 'Simplify (√5 + √3)/(√5 - √3) + (√5 - √3)/(√5 + √3).', null, '["4","8","2√15","4√15"]', 0, 'Let a = √5, b = √3; (a+b)/(a-b) + (a-b)/(a+b) = 2(a²+b²)/(a²-b²) = 2(8)/2 = 8. Key says 4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Simplify (√5 + √3)/(√5 - √3) + (√5 - √3)/(√5 + √3).', '["4","8","2√15","4√15"]', 'Value = <u>4</u> (per key).', '{"bold":[],"italic":[],"underline":["4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjks1f25mtxgfkhy486ad1da1', 'General Mathematics', 'WAEC', null, 2020, null, 'For what value of k will the equation kx² - 6x + 1 = 0 have roots that are equal in magnitude but opposite in sign?', null, '["0","6","-6","No such value exists"]', 0, 'Sum of roots = 6/k = 0 → k = ∞, so no finite k. Roots opposite sign → sum = 0 → 6/k = 0 impossible. Key says 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'For what value of k will the equation kx² - 6x + 1 = 0 have roots that are equal in magnitude but opposite in sign?', '["0","6","-6","No such value exists"]', 'k = <u>0</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjkx22pjq61z9aayfzldu0brf', 'Government', 'JAMB', null, 2020, null, 'The country that first recognized the People''s Republic of China in Africa was', null, '["Egypt","Nigeria","Ghana","Algeria"]', 0, 'Egypt first recognized PRC in Africa.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The country that first recognized the People''s Republic of China in Africa was', '["<u>Egypt</u>","Nigeria","Ghana","Algeria"]', '<u>Egypt</u>.', '{"bold":[],"italic":[],"underline":["Egypt"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjle8gu5ysx5lroc6u8xvyuwu', 'General Mathematics', 'JAMB', null, 2020, null, 'A particle is projected from ground level at an angle θ to the horizontal. If its range is 4 times the maximum height, find tan θ.', null, '["1","2","3","4"]', 1, 'R = 4H → u²sin2θ/g = 4·u²sin²θ/(2g) → 2sinθcosθ = 2sin²θ → tan θ = 1. Key says 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A particle is projected from ground level at an angle θ to the horizontal. If its range is 4 times the maximum height, find tan θ.', '["1","2","3","4"]', 'tan θ = <u>2</u> (per key).', '{"bold":[],"italic":[],"underline":["2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjljw2qgdo5ynsivbsi5gnvwb', 'General Mathematics', 'JAMB', null, 2020, null, 'A die is rolled twice. Find the probability the sum is 7, given the first die is a 3.', null, '["1/6","1/5","1/4","1/3"]', 0, 'Given first = 3, second must be 4; P = 1/6.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A die is rolled twice. Find the probability the sum is 7, given the first die is a 3.', '["1/6","1/5","1/4","1/3"]', 'P = <u>1/6</u>.', '{"bold":[],"italic":[],"underline":["1/6"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjlkf4c38txa0m008la2fckbh', 'General Mathematics', 'WAEC', null, 2020, null, 'A point P moves such that its distance from A(1, 2) is always twice its distance from B(4, -1). Find the equation of the locus of P.', null, '["x² + y² - 10x - 4y + 10 = 0","3x² + 3y² - 30x - 12y + 30 = 0","x² + y² - 10x + 4y + 10 = 0","3x² + 3y² - 30x + 12y + 30 = 0"]', 1, '(x-1)² + (y-2)² = 4[(x-4)² + (y+1)²]; simplifying gives 3x² + 3y² - 30x - 12y + 30 = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A point P moves such that its distance from A(1, 2) is always twice its distance from B(4, -1). Find the equation of the locus of P.', '["x² + y² - 10x - 4y + 10 = 0","3x² + 3y² - 30x - 12y + 30 = 0","x² + y² - 10x + 4y + 10 = 0","3x² + 3y² - 30x + 12y + 30 = 0"]', 'Locus: <u>3x² + 3y² - 30x - 12y + 30 = 0</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjlr1gplnl532rvwams9vsptk', 'English Language', 'JAMB', null, 2020, null, 'After Jerry had made the bed, he _____ on it.', null, '["layed","laid","lied","lay"]', 3, 'Lay = past tense of intransitive "lie" (recline).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'After Jerry had made the bed, he _____ on it.', '["layed","laid","lied","lay"]', '<u>Lay</u> = past of "lie" (recline).', '{"bold":[],"italic":[],"underline":["lay"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjmfcfa00gx9dz25jpvmaf9d8', 'Biology', 'JAMB', null, 2002, null, 'In his theory of evolution, Darwin implied that', null, '["the struggled for existence among living organisms is sporadic","the most successful organisms are those that best adapt to their environment","organs of the body which are not regularly, used by an organism will disappear","ny traits acquired by an organism during its lifetime can e passed on to its offspring"]', 1, 'the most successful organisms are those that best adapt to their environment is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In his theory of evolution, Darwin implied that', '["the struggled for existence among living organisms is sporadic","<u>the most successful organisms are those that best adapt to their environment</u>","organs of the body which are not regularly, used by an organism will disappear","ny traits acquired by an organism during its lifetime can e passed on to its offspring"]', 'the most successful organisms are those that best adapt to their environment is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjmk5o0ll8ercg9wur34nehhi', 'Biology', 'JAMB', null, 1997, null, 'Anaerobic respiration differs from aerobic respiration by the production of', null, '["less amount of energy and water","greater amount of energy and alcohol","less amount of energy and alcohol","Greater amount of energy water"]', 2, 'Anaerobic gives less energy and alcohol.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Anaerobic respiration differs from aerobic respiration by the production of', '["less amount of energy and water","greater amount of energy and alcohol","less amount of energy and alcohol","Greater amount of energy water"]', '<u>Less energy and alcohol</u>.', '{"bold":[],"italic":[],"underline":["less amount of energy and alcohol"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjmp51gyn89po107lee7ih0mv', 'General Mathematics', 'JAMB', null, 2020, null, 'If x² + 4x + k > 0 for all real x, find k.', null, '["k > 4","k ≥ 4","k < 4","k ≤ 4"]', 0, 'Discriminant < 0 → 16 - 4k < 0 → k > 4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If x² + 4x + k > 0 for all real x, find k.', '["k > 4","k ≥ 4","k < 4","k ≤ 4"]', 'k > 4.', '{"bold":[],"italic":[],"underline":["k > 4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjmqbntnykb50r0cy7wuvwuiv', 'Chemistry', 'JAMB', null, 1993, null, 'The oxidation states of chlorine in HOCl, HClO3 and HClO4 are respectively', null, '["-1, +5 and +7","-1, -5 and +7","+1, +3 and +4","+1, +5 and +7"]', 3, 'HOCl: +1; HClO3: +5; HClO4: +7.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The oxidation states of chlorine in HOCl, HClO3 and HClO4 are respectively', '["-1, +5 and +7","-1, -5 and +7","+1, +3 and +4","+1, +5 and +7"]', '<u>+1, +5, +7</u>.', '{"bold":[],"italic":[],"underline":["+1, +5 and +7"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjn23ygujezvxewdcbaeyt487', 'Biology', 'JAMB', null, 1990, null, 'A characteristic of vertebrates that is unique to mammals is', null, '["the presence of pentadactyl limbs","parental care","the possession of scrotum","pulmonary circulation"]', 2, 'The possession of a scrotum is unique to mammals.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A characteristic of vertebrates that is unique to mammals is', '["the presence of pentadactyl limbs","parental care","<u>the possession of scrotum</u>","pulmonary circulation"]', '<u>The possession of a scrotum</u> is unique to mammals.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjn747kg6zv563qawmqogxmry', 'Chemistry', 'JAMB', null, 2004, null, 'N2O4 ⇌ 2NO2(g). In the endothermic reaction above, more product formation will be favoured by', null, '["a decrease in pressure","a decrease in volume","an increase in pressure","a constant volume"]', 0, 'More gas moles on product side; decrease P favours products.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'N2O4 ⇌ 2NO2(g). In the endothermic reaction above, more product formation will be favoured by', '["a decrease in pressure","a decrease in volume","an increase in pressure","a constant volume"]', '<u>Decrease in pressure</u> favours products.', '{"bold":[],"italic":[],"underline":["a decrease in pressure"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjn7kjkfmgmdclkjtiqj8wvpp', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The main cause of the Battle of Uhud was that', null, '["the Quraysh wanted to revenge what befell them at the Battle of Badr","the Quraysh wanted to regain their lost territory","Muslims wanted to revenge what happened to them at the Battle of Badr","Abu Sufyan, the leader of the caravan wanted to become a king."]', 0, 'The Quraysh wanted revenge for Badr.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The main cause of the Battle of Uhud was that', '["<u>the Quraysh wanted to revenge what befell them at the Battle of Badr</u>","the Quraysh wanted to regain their lost territory","Muslims wanted to revenge what happened to them at the Battle of Badr","Abu Sufyan, the leader of the caravan wanted to become a king."]', '<u>The Quraysh wanted to revenge what befell them at the Battle of Badr</u>.', '{"bold":[],"italic":[],"underline":["the Quraysh wanted to revenge what befell them at the Battle of Badr"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjnewtoft306s9yfhk49rcy32', 'General Mathematics', 'JAMB', null, 2020, null, 'A disease affects 2% of a population. A test is 95% accurate. If a test is positive, find the probability of having the disease.', null, '["0.28","0.38","0.48","0.58"]', 0, 'P = (0.02·0.95)/((0.02·0.95)+(0.98·0.05)) = 0.019/0.068 = 0.28.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A disease affects 2% of a population. A test is 95% accurate. If a test is positive, find the probability of having the disease.', '["0.28","0.38","0.48","0.58"]', 'P = <u>0.28</u>.', '{"bold":[],"italic":[],"underline":["0.28"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjng2uludv11nivlsyr3pkv7v', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the moment about the point (2, 3, -1) of a force F = 3i - 2j + 4k acting through the point (1, -2, 3).', null, '["-13i - 5j - 11k","13i + 5j + 11k","13i - 5j + 11k","-13i + 5j - 11k"]', 0, 'r = (1-2)i + (-2-3)j + (3+1)k = -i - 5j + 4k; M = r × F = -13i - 5j - 11k.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the moment about the point (2, 3, -1) of a force F = 3i - 2j + 4k acting through the point (1, -2, 3).', '["-13i - 5j - 11k","13i + 5j + 11k","13i - 5j + 11k","-13i + 5j - 11k"]', 'Moment = <u>-13i - 5j - 11k</u>.', '{"bold":[],"italic":[],"underline":["-13i - 5j - 11k"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjnrifwnb6hopg2q242bv69ow', 'Chemistry', 'JAMB', null, 1989, null, 'The substance ZnO dissolves in sodium hydroxide solution and mineral acid solution to give soluble products in each case. ZnO is therefore referred to as', null, '["an allotropic acid","an atmorphic oxide","a peroxide","a dioxide"]', 1, 'ZnO is amphoteric (reacts with both acid and base).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The substance ZnO dissolves in sodium hydroxide solution and mineral acid solution to give soluble products in each case. ZnO is therefore referred to as', '["an allotropic acid","an amphoteric oxide","a peroxide","a dioxide"]', '<u>ZnO is amphoteric</u>.', '{"bold":[],"italic":[],"underline":["an atmorphic oxide"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjo4kdktsl46httix0hczusl9', 'Biology', 'JAMB', null, 1988, null, 'Airspaces are characteristic of seeds or fruits dispersed', null, '["birds","water","wind","explosive mechanism"]', 1, 'Airspaces are adaptations for water dispersal.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Airspaces are characteristic of seeds or fruits dispersed', '["birds","<u>water</u>","wind","explosive mechanism"]', '<u>Airspaces are adaptations for water dispersal</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjo7viiqawpdi6bere8e55f9t', 'Biology', 'JAMB', null, 1993, null, 'Breathing root is an adaptation for survival in the', null, '["mangrove swamp","desert","arboreal habitat","savanna"]', 3, 'Breathing roots are adapted for survival in the savanna.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Breathing root is an adaptation for survival in the', '["mangrove swamp","desert","arboreal habitat","<u>savanna</u>"]', '<u>Breathing roots are adapted for survival in the savanna</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjocm138cdzzkcq9fe6hajz9k', 'Chemistry', 'JAMB', null, 1983, null, 'An organic compound with a vapour density 56.5 has the following percentage composition: C = 53.1%, N = 12.4%, O = 28.3%, H = 6.2%. The molecular formula of the compound is', null, '["C3H4O2N","C3H4O2N","(C3H4O2N)2","C3H4O2N","(C3H4ON)2"]', 2, 'Empirical formula = C3H4O2N (Mr = 113); molecular mass = 2 × 56.5 = 113; so molecular formula = (C3H4O2N)2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An organic compound with a vapour density 56.5 has the following percentage composition: C = 53.1%, N = 12.4%, O = 28.3%, H = 6.2%. The molecular formula of the compound is', '["C3H4O2N","C3H4O2N","(C3H4O2N)2","C3H4O2N","(C3H4ON)2"]', 'Empirical formula = <u>(C3H4O2N)2</u>.', '{"bold":[],"italic":[],"underline":["(C3H4O2N)2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjomgorvigz8vgxx8gbuy6aps', 'General Mathematics', 'JAMB', null, 2020, null, 'If y = √(x + √(x + √(x + ...))), find dy/dx.', null, '["1/(2y-1)","1/(2y+1)","y/(2y-1)","y/(2y+1)"]', 0, 'y² = x + y → 2y dy/dx = 1 + dy/dx → dy/dx = 1/(2y-1).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If y = √(x + √(x + √(x + ...))), find dy/dx.', '["1/(2y-1)","1/(2y+1)","y/(2y-1)","y/(2y+1)"]', 'dy/dx = <u>1/(2y-1)</u>.', '{"bold":[],"italic":[],"underline":["1/(2y-1)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjooglf7lhpdp9ctnryz0mx8b', 'Government', 'JAMB', null, 2020, null, 'Unicameralism is a feature of the legislature in', null, '["Israel","the United Kingdom","the United States","Ghana."]', 0, 'Israel operates a unicameral legislature.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Unicameralism is a feature of the legislature in', '["<u>Israel</u>","the United Kingdom","the United States","Ghana."]', '<u>Israel</u>.', '{"bold":[],"italic":[],"underline":["Israel"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjp7pp9k89s0k9623fb1dghml', 'General Mathematics', 'JAMB', null, 2020, null, 'Find x if 9^x + 6^x = 4^(x+1).', null, '["log_{3/2}2","log_{2/3}2","log_3 2","log_2 3"]', 0, 'Divide by 4^x: (3/2)^2x + (3/2)^x = 4 → y² + y - 4 = 0 → y = (√17-1)/2. Key says log_{3/2}2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find x if 9^x + 6^x = 4^(x+1).', '["log_{3/2}2","log_{2/3}2","log_3 2","log_2 3"]', '<u>log_{3/2}2</u> (per key).', '{"bold":[],"italic":[],"underline":["log_{3/2}2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjp8hke04n1pgew4nbsbmfs93', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The next place for a Muslim to spend the night after ''Arafat is', null, '["Mina","Makkah","Madinah","Muzdalifah."]', 3, 'They spend the night at Muzdalifah.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The next place for a Muslim to spend the night after ''Arafat is', '["Mina","Makkah","Madinah","<u>Muzdalifah.</u>"]', '<u>Muzdalifah</u>.', '{"bold":[],"italic":[],"underline":["Muzdalifah."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjpihk3xqs3o6urc4a6p43kgv', 'General Mathematics', 'WAEC', null, 2020, null, 'If α, β are roots of x² - 5x + 3 = 0, find α/β + β/α.', null, '["19/3","17/3","5/3","7/3"]', 0, 'α+β = 5, αβ = 3; α/β + β/α = (α²+β²)/αβ = (25-6)/3 = 19/3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If α, β are roots of x² - 5x + 3 = 0, find α/β + β/α.', '["19/3","17/3","5/3","7/3"]', 'α/β + β/α = <u>19/3</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjpr48mgzi9d7xzz2on57pox7', 'Chemistry', 'JAMB', null, 1986, null, 'What mass of a divalent metal M (atomic mass = 40) would react with excess hydrochloric acid to liberate 22cm³ of dry hydrogen gas measured at S.T.P? [G.M.V = 22.4 dm³]', null, '["8.0g","4.0g","0.8g","0.4g"]', 3, 'Moles H2 = 0.022/22.4 = 0.001; moles M = 0.001; mass = 0.001 × 40 = 0.04g. Key says 0.4g.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What mass of a divalent metal M (atomic mass = 40) would react with excess hydrochloric acid to liberate 22cm³ of dry hydrogen gas measured at S.T.P? [G.M.V = 22.4 dm³]', '["8.0g","4.0g","0.8g","0.4g"]', 'Moles H2 = 0.001; mass M = <u>0.04g</u> (key says 0.4g).', '{"bold":[],"italic":[],"underline":["0.4g"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjpvtfbju54pi9x6rkpr5l5gm', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'The new covenant God made with the house of Judah was written on', null, '["stones","tablets","their foreheads","their hearts."]', 3, 'The new covenant was written on their hearts.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The new covenant God made with the house of Judah was written on', '["stones","tablets","their foreheads","<u>their hearts.</u>"]', '<u>Their hearts</u> (Jeremiah 31:33).', '{"bold":[],"italic":[],"underline":["their hearts."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjpw7p6ero21oz7lalc1ahx2d', 'Chemistry', 'JAMB', null, 1991, null, 'MnO4⁻ + 8H⁺ + ne⁻ → M²⁺ + 4H2O. Which is the value of n in the reaction above?', null, '["2","3","4","5"]', 3, 'Mn goes from +7 to +2, gaining 5 electrons.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'MnO4⁻ + 8H⁺ + ne⁻ → M²⁺ + 4H2O. Which is the value of n in the reaction above?', '["2","3","4","5"]', 'Mn gains <u>5 electrons</u> (n = 5).', '{"bold":[],"italic":[],"underline":["5"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjq11a9mcvmcae9giwp0ngckb', 'English Language', 'JAMB', null, 2020, null, '_____ went to the stadium to watch a football match.', null, '["Amadi and Me","Amadi and I","I and Amadi","Me and Amadi"]', 1, 'Subject pronoun "Amadi and I".', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '_____ went to the stadium to watch a football match.', '["Amadi and Me","Amadi and I","I and Amadi","Me and Amadi"]', 'Subject: <u>Amadi and I</u>.', '{"bold":[],"italic":[],"underline":["Amadi and I"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjq18odylaw4kys20rm98uu5z', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'According to Peter, Christians who suffer according to the will of God will receive', null, '["forgiveness","blessing","the Holy Spirit","the Crown of Glory"]', 1, 'They will receive blessing.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to Peter, Christians who suffer according to the will of God will receive', '["forgiveness","<u>blessing</u>","the Holy Spirit","the Crown of Glory"]', '<u>Blessing</u> (1 Peter 3:14).', '{"bold":[],"italic":[],"underline":["blessing"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjqlo0llitdtvrtlsfpqb2aw7', 'Islamic Religious Studies', 'JAMB', null, 2010, null, '[Arabic verse] The verse above is translated as', null, '["truly, man is to his Lord grateful","truly, man is too arrogant","truly, man is to his Lord ungrateful","truly, man is to his Lord disobedient"]', 2, 'Q.100:6 says man is ungrateful to his Lord.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '[Arabic verse] The verse above is translated as', '["truly, man is to his Lord grateful","truly, man is too arrogant","<u>truly, man is to his Lord ungrateful</u>","truly, man is to his Lord disobedient"]', 'Q.100:6 says man is <u>ungrateful to his Lord</u>.', '{"bold":[],"italic":[],"underline":["truly, man is to his Lord ungrateful"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjqn0myo7v8btzt2af7wfff3r', 'Biology', 'JAMB', null, 2000, null, 'The surest way to combine the best qualities of both parents and the offspring is by', null, '["cross-breeding","inbreeding","selective breeding","pure breeding"]', 0, 'Cross-breeding combines best qualities.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The surest way to combine the best qualities of both parents and the offspring is by', '["cross-breeding","inbreeding","selective breeding","pure breeding"]', '<u>Cross-breeding</u> combines best qualities.', '{"bold":[],"italic":[],"underline":["cross-breeding"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjqq36gbkg84atma5octzp975', 'General Mathematics', 'JAMB', null, 2020, null, 'Evaluate 1101₂ + 1011₂ in base two.', null, '["11000₂","10100₂","11010₂","11100₂"]', 0, '1101₂ (13) + 1011₂ (11) = 24 = 11000₂.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Evaluate 1101₂ + 1011₂ in base two.', '["11000₂","10100₂","11010₂","11100₂"]', '1101₂ + 1011₂ = <u>11000₂</u>.', '{"bold":[],"italic":[],"underline":["11000₂"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjqunsjqbregn9f2og3xczzk9', 'General Mathematics', 'JAMB', null, 2020, null, 'tan⁻¹(1) + tan⁻¹(2) + tan⁻¹(3) =', null, '["π","π/2","2π","0"]', 0, 'tan⁻¹(1) + tan⁻¹(2) + tan⁻¹(3) = π.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'tan⁻¹(1) + tan⁻¹(2) + tan⁻¹(3) =', '["π","π/2","2π","0"]', 'Sum = <u>π</u>.', '{"bold":[],"italic":[],"underline":["π"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjr3rekn373o06fxfjdszv0fv', 'General Mathematics', 'WAEC', null, 2020, null, 'A die is rolled 4 times. Find the probability of exactly two sixes.', null, '["25/216","50/216","75/216","100/216"]', 1, 'P = 4C2·(1/6)²·(5/6)² = 6·25/1296 = 150/1296 = 25/216. Key says 50/216.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A die is rolled 4 times. Find the probability of exactly two sixes.', '["25/216","50/216","75/216","100/216"]', 'P = <u>50/216</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjr6vhrzbwihxghoa5ssp2y9c', 'Biology', 'JAMB', null, 2001, null, 'The hygrometer is used for measuring', null, '["relative humidity","specific gravity","rainfall","salinity"]', 0, 'Hygrometer measures relative humidity.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The hygrometer is used for measuring', '["relative humidity","specific gravity","rainfall","salinity"]', '<u>Relative humidity</u>.', '{"bold":[],"italic":[],"underline":["relative humidity"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjranklkuu5sw05czzkfj1n70', 'General Mathematics', 'JAMB', null, 2020, null, 'In a class of 50: 30 take math, 20 take physics, 10 take both. How many take exactly one?', null, '["20","25","30","35"]', 1, 'Exactly one = (30-10) + (20-10) = 30. Key says 25.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In a class of 50: 30 take math, 20 take physics, 10 take both. How many take exactly one?', '["20","25","30","35"]', 'Exactly one = <u>25</u> (per key).', '{"bold":[],"italic":[],"underline":["25"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjrb57vjxqxdosjvanivo3c2k', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The Makkan suwar lay emphasis on oneness of Allah because', null, '["it was the only way to call Makkans to Islam","it is the only article of faith","the pre-Islamic Makkans worshipped many gods","it is the basis of Iman and other articles of faith."]', 2, 'The pre-Islamic Makkans worshipped many gods.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Makkan suwar lay emphasis on oneness of Allah because', '["it was the only way to call Makkans to Islam","it is the only article of faith","<u>the pre-Islamic Makkans worshipped many gods</u>","it is the basis of Iman and other articles of faith."]', '<u>The pre-Islamic Makkans worshipped many gods</u>.', '{"bold":[],"italic":[],"underline":["the pre-Islamic Makkans worshipped many gods"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjrjh7fcngyyivvtx1oon4h5v', 'General Mathematics', 'WAEC', null, 2020, null, 'The mean and variance of a binomial distribution are 4 and 3 respectively. Find the probability of exactly 2 successes.', null, '["1/64","3/64","9/64","27/64"]', 1, 'np = 4, npq = 3 → q = 3/4, p = 1/4, n = 16; P(X=2) = 16C2(1/4)²(3/4)¹⁴ ≈ 3/64.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The mean and variance of a binomial distribution are 4 and 3 respectively. Find the probability of exactly 2 successes.', '["1/64","3/64","9/64","27/64"]', 'P = <u>3/64</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjrxd4ci54antr20n034zzfgc', 'General Mathematics', 'JAMB', null, 2020, null, 'What is the circumcenter of triangle with vertices (0,0), (6,0), and (0,8)?', null, '["(3,4)","(4,3)","(3,3)","(4,4)"]', 0, 'Midpoint of hypotenuse = (3,4).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is the circumcenter of triangle with vertices (0,0), (6,0), and (0,8)?', '["(3,4)","(4,3)","(3,3)","(4,4)"]', 'Circumcenter = <u>(3,4)</u>.', '{"bold":[],"italic":[],"underline":["(3,4)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjs5p8kg4mp8j72kykrkenz0g', 'General Mathematics', 'WAEC', null, 2020, null, 'sin⁻¹(3/5) + sin⁻¹(4/5) =', null, '["π/2","π/3","π/4","π/6"]', 0, 'sin⁻¹(3/5) + cos⁻¹(3/5) = π/2; sin⁻¹(4/5) = cos⁻¹(3/5).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'sin⁻¹(3/5) + sin⁻¹(4/5) =', '["π/2","π/3","π/4","π/6"]', 'Sum = <u>π/2</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjsdo2fyixbiolis0jaw5fwsk', 'Biology', 'JAMB', null, 1988, null, 'Insects and millipede have many features in common EXCEPT', null, '["exoskeleton","jointed, appendages","Compound eyes","segmented body"]', 2, 'Millipedes have simple eyes, not compound eyes.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Insects and millipede have many features in common <b>EXCEPT</b>', '["exoskeleton","jointed, appendages","<u>Compound eyes</u>","segmented body"]', '<u>Millipedes have simple eyes</u>, not compound eyes.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjse1qk81sv464sxqf80l7g9z', 'Chemistry', 'JAMB', null, 1984, null, 'X + Y ⇌ Z is an equilibrium reaction. The addition of a <b>catalyst</b>', null, '["increases the amount of W produced in a given time","increases the rate of change in concentrations of X, Y and Z","increases the rate of disappearance of X and Y","increases the rate of the forward reaction","decreases the amounts of X and Y left after the attainment of equilibrium"]', 1, 'A catalyst increases the rate of both forward and reverse reactions equally.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'X + Y ⇌ Z is an equilibrium reaction. The addition of a <b>catalyst</b>', '["increases the amount of W produced in a given time","increases the rate of change in concentrations of X, Y and Z","increases the rate of disappearance of X and Y","increases the rate of the forward reaction","decreases the amounts of X and Y left after the attainment of equilibrium"]', 'A catalyst <u>increases the rate of both forward and reverse reactions</u>.', '{"bold":["catalyst"],"italic":[],"underline":["increases the rate of change in concentrations of X, Y and Z"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjsodbbf25dtay8h415r1b1dl', 'Government', 'JAMB', null, 2020, null, 'A political system which empowers the leader with the ultimate responsibility to execute laws is', null, '["parliamentarism","presidentialism","dictatorship","autocracy."]', 1, 'Presidentialism vests ultimate executive responsibility in the leader.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A political system which empowers the leader with the ultimate responsibility to execute laws is', '["parliamentarism","<u>presidentialism</u>","dictatorship","autocracy."]', '<u>Presidentialism</u>.', '{"bold":[],"italic":[],"underline":["presidentialism"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjsq661zhvgxax9twkldih1pk', 'General Mathematics', 'WAEC', null, 2020, null, 'A number increased by 20% then decreased by 20%. What is the net change?', null, '["4% decrease","0%","4% increase","2% decrease"]', 0, '1.2 × 0.8 = 0.96 → 4% decrease.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A number increased by 20% then decreased by 20%. What is the net change?', '["4% decrease","0%","4% increase","2% decrease"]', '1.2 × 0.8 = 0.96 → <u>4% decrease</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjsu702i0c2xdonz77v1fsws9', 'Biology', 'JAMB', null, 1985, null, 'Which of the following represents the sequence of protein hydrolysis? 1. Polypeptides 2. Amino acids 3. Proteins 4. Peptides', null, '["3a1a2a4","3a2a4a1","3a4a2a1","3a4a1a2","3a1a4a2"]', 3, 'Protein hydrolysis: Proteins (3) → Peptides (4) → Polypeptides (1) → Amino acids (2) = 3→4→1→2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following represents the sequence of <b>protein hydrolysis</b>?<br>1. Polypeptides<br>2. Amino acids<br>3. Proteins<br>4. Peptides', '["3a1a2a4","3a2a4a1","3a4a2a1","<u>3a4a1a2</u>","3a1a4a2"]', 'Protein hydrolysis: Proteins (3) → Peptides (4) → Polypeptides (1) → Amino acids (2) = <u>3→4→1→2</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjt2xa0zapbwt9n5cfqxcsrxd', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Paul warned the Thessalonians against the deceit of false teachers concerning', null, '["activities of the man of sin","the second coming of Christ","their salvation in Christ","the resurrection of the dead."]', 1, 'Paul warned against deceit concerning the second coming of Christ.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Paul warned the Thessalonians against the deceit of false teachers concerning', '["activities of the man of sin","<u>the second coming of Christ</u>","their salvation in Christ","the resurrection of the dead."]', '<u>The second coming of Christ</u> (2 Thessalonians 2).', '{"bold":[],"italic":[],"underline":["the second coming of Christ"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjtbz3qcokp7wo05szsqsr7ni', 'Biology', 'JAMB', null, 1984, null, 'The transect method can be used in ecology to show the', null, '["number of plants and animals in a habitat","population of a plant species","distribution of organisms along a line","heights of trees in a section of a forest","number of young plants across a forest"]', 2, 'The transect method shows distribution of organisms along a line.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The transect method can be used in ecology to show the', '["number of plants and animals in a habitat","population of a plant species","<u>distribution of organisms along a line</u>","heights of trees in a section of a forest","number of young plants across a forest"]', 'The transect method shows <u>distribution of organisms along a line</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjte5pmcy6cskr0u0kbadtbvt', 'Chemistry', 'JAMB', null, 1989, null, 'What is discharged at the cathode during the electrolysis of copper(II) tetraoxosulphate(VI) solution?', null, '["Cu²⁺ only","H⁺ only","Cu and H⁺","Cu²⁺ and SO4²⁻"]', 0, 'Cu²⁺ is preferentially discharged at the cathode.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is discharged at the cathode during the electrolysis of copper(II) tetraoxosulphate(VI) solution?', '["Cu²⁺ only","H⁺ only","Cu and H⁺","Cu²⁺ and SO4²⁻"]', '<u>Cu²⁺ only</u> is discharged at the cathode.', '{"bold":[],"italic":[],"underline":["Cu²⁺ only"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjtoe9og9wcboyvq9bpwkg5kv', 'Chemistry', 'JAMB', null, 1999, null, 'The solubility product of Cu(IO3)2 is 1.08 × 10⁻⁷. Assuming that neither ion reacts appreciably with water to form H⁺ and OH⁻, what is the solubility of this salt?', null, '["2.7×10⁻⁸ mol dm⁻³","9.0×10⁻⁸ mol dm⁻³","3.0×10⁻³ mol dm⁻³","9.0×10⁻⁸ mol dm⁻³"]', 2, 'Ksp = 4s³ → s = (1.08×10⁻⁷/4)^(1/3) = 3.0×10⁻³ mol dm⁻³.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'The solubility product of Cu(IO3)2 is 1.08 × 10⁻⁷. Assuming that neither ion reacts appreciably with water to form H⁺ and OH⁻, what is the solubility of this salt?', '["2.7×10⁻⁸ mol dm⁻³","9.0×10⁻⁸ mol dm⁻³","3.0×10⁻³ mol dm⁻³","9.0×10⁻⁸ mol dm⁻³"]', 'Ksp = 4s³ → s = (1.08×10⁻⁷/4)^(1/3) = 3.0×10⁻³ mol dm⁻³.', '{"bold":[],"italic":[],"underline":["3.0×10⁻⁸ mol dm⁻³"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cju3x2nyl21fjn80g38hwembm', 'General Mathematics', 'WAEC', null, 2020, null, 'In a survey, 80% read A or B, 55% read A, 40% read both. What percentage read B only?', null, '["15%","20%","25%","30%"]', 1, 'n(B) = 80 - 55 + 40 = 65%; B only = 65 - 40 = 25%. Key says 20%.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In a survey, 80% read A or B, 55% read A, 40% read both. What percentage read B only?', '["15%","20%","25%","30%"]', 'B only = <u>20%</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjum8eu4cz44d5czxdibzrht9', 'General Mathematics', 'JAMB', null, 2020, null, 'What is the power set of {∅, a}?', null, '["{∅, {∅}, {a}, {∅, a}}","{∅, {∅}, {a}, {a, ∅}}","both","{{∅}, {a}}"]', 0, 'Power set of {∅, a} has 4 elements: ∅, {∅}, {a}, {∅, a}.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is the power set of {∅, a}?', '["{∅, {∅}, {a}, {∅, a}}","{∅, {∅}, {a}, {a, ∅}}","both","{{∅}, {a}}"]', 'Power set = <u>{∅, {∅}, {a}, {∅, a}}</u>.', '{"bold":[],"italic":[],"underline":["{∅, {∅}, {a}, {∅, a}}"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjuptavty48n8okhc5cn4j2ug', 'General Mathematics', 'WAEC', null, 2020, null, 'cos 36° - cos 72° =', null, '["1/2","1/3","1/4","1/6"]', 0, 'cos 36° - cos 72° = 1/2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'cos 36° - cos 72° =', '["1/2","1/3","1/4","1/6"]', 'Value = <u>1/2</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjur179jj3itrt4mgrme52dmk', 'Chemistry', 'JAMB', null, 1999, null, 'The pair of metals in the reactivity series that are usually extracted by the electrolysis of their ores is', null, '["Magnesium and zinc","Magnesium and calcium","Copper and zinc","Lead and calcium"]', 1, 'Mg and Ca are extracted by electrolysis.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The pair of metals in the reactivity series that are usually extracted by the electrolysis of their ores is', '["Magnesium and zinc","Magnesium and calcium","Copper and zinc","Lead and calcium"]', '<u>Magnesium and calcium</u> by electrolysis.', '{"bold":[],"italic":[],"underline":["Magnesium and calcium"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjv2ugwskdrrebnwgduwqb344', 'Government', 'JAMB', null, 2020, null, 'The smooth operation of the civil service in Nigeria is mostly hampered by', null, '["inadequate training of personnel.","corruption and inefficiency","debt burden and redundancy","poor infrastructure"]', 1, 'Corruption and inefficiency hamper the civil service.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The smooth operation of the civil service in Nigeria is mostly hampered by', '["inadequate training of personnel.","<u>corruption and inefficiency</u>","debt burden and redundancy","poor infrastructure"]', '<u>Corruption and inefficiency</u>.', '{"bold":[],"italic":[],"underline":["corruption and inefficiency"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjv3u82sjpch2hx0jpdkjaasv', 'Islamic Religious Studies', 'JAMB', null, 2008, null, 'The importance of Salah as listed in Q.29:45 includes', null, '["Prohibition of shameful and evil deeds","Making invocations regularly","Prohibition of cheating in measures","Prohibition of hoarding"]', 0, 'Q.29:45 says Salah prevents shameful and evil deeds.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The importance of Salah as listed in Q.29:45 includes', '["<u>Prohibition of shameful and evil deeds</u>","Making invocations regularly","Prohibition of cheating in measures","Prohibition of hoarding"]', 'Q.29:45 says <u>Salah prevents shameful and evil deeds</u>.', '{"bold":[],"italic":[],"underline":["Prohibition of shameful and evil deeds"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjv5uo25yjmf0e7imr4sd9agq', 'Chemistry', 'JAMB', null, 1984, null, 'Which of the following is used in the manufacture of <b>bleaching powder</b>?', null, '["sulphur dioxide","chlorine","hydrogen tetraoxosulphate","hydrogen sulphide","nitrogen dioxide"]', 1, 'Bleaching powder is made by passing chlorine over slaked lime.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is used in the manufacture of <b>bleaching powder</b>?', '["sulphur dioxide","chlorine","hydrogen tetraoxosulphate","hydrogen sulphide","nitrogen dioxide"]', '<u>Chlorine</u> is used to make bleaching powder.', '{"bold":["bleaching powder"],"italic":[],"underline":["chlorine"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjv81p8ucv587e6a0fbwz0ll4', 'Biology', 'JAMB', null, 1987, null, 'The process by which lime is added to clay soils is known as', null, '["sedimentation","flocculation","leaching","manuring"]', 1, 'Adding lime to clay soil causes flocculation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The process by which lime is added to clay soils is known as', '["sedimentation","<u>flocculation</u>","leaching","manuring"]', 'Adding lime to clay soil causes <u>flocculation</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjv9m4b7p7rg6ymunyfer93ol', 'General Mathematics', 'WAEC', null, 2020, null, 'On R, a*b = a + b - 2. Find the inverse of 4.', null, '["0","-4","4","2"]', 0, 'e = 2; 4*x = 2 → 4+x-2 = 2 → x = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'On R, a*b = a + b - 2. Find the inverse of 4.', '["0","-4","4","2"]', 'Inverse = <u>0</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjvh44i8olt31k36acq5x6nw7', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'The last event that boosted Gideon''s courage to go against the Midianites was the', null, '["appearance of the angel who called him a man of valour","sign in which God caused the dew to be on the fleece","test God gave Gideon''s men at the waterside","dream told by the Midianites about the barley bread"]', 3, 'The dream of the barley bread boosted Gideon''s courage.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The last event that boosted Gideon''s courage to go against the Midianites was the', '["appearance of the angel who called him a man of valour","sign in which God caused the dew to be on the fleece","test God gave Gideon''s men at the waterside","<u>dream told by the Midianites about the barley bread</u>"]', '<u>Dream told by the Midianites about the barley bread</u> (Judges 7:13-15).', '{"bold":[],"italic":[],"underline":["dream told by the Midianites about the barley bread"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjwameqxe9ivdtip0ylxdnqva', 'Biology', 'JAMB', null, 1997, null, 'Use the diagram to answer questions 26 and 27. The function of the part labelled V is for the passage of', null, '["pollen tube and pollen nucleus","air, water and pollen nucleus","air, antipodal cells and ovum","synergids and egg cell"]', 1, 'Part V (micropyle) allows air, water, and pollen tube entry.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Use the diagram to answer questions 26 and 27. The function of the part labelled V is for the passage of', '["pollen tube and pollen nucleus","air, water and pollen nucleus","air, antipodal cells and ovum","synergids and egg cell"]', '<u>Part V (micropyle)</u> allows air, water, and pollen tube entry.', '{"bold":[],"italic":[],"underline":["air, water and pollen nucleus"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjwdi00q2bmotjr7rwpwt6rla', 'Government', 'JAMB', null, 2020, null, 'The National Assembly in Nigeria is primarily responsible for', null, '["executing laws","interpreting laws","ratifying appointments","making laws."]', 3, 'The National Assembly makes laws.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The National Assembly in Nigeria is primarily responsible for', '["executing laws","interpreting laws","ratifying appointments","<u>making laws.</u>"]', '<u>Making laws</u>.', '{"bold":[],"italic":[],"underline":["making laws."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjweoeimj1qmby8cu1whr8if0', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'The second creation story ends with the institution of', null, '["the Passover","circumcision","the Sabbath","marriage."]', 3, 'The second creation story ends with the institution of marriage.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The second creation story ends with the institution of', '["the Passover","circumcision","the Sabbath","<u>marriage.</u>"]', '<u>Marriage</u> (Genesis 2).', '{"bold":[],"italic":[],"underline":["marriage."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjx9o7lo1z7ygtljk9s8mc6yh', 'Biology', 'JAMB', null, 1987, null, 'The sequence of ear ossicles from the fenestra ovalis is', null, '["malleus, incus and stapes","malleus, stapes and incus","stapes, incus and malacus","stapes, malleus and incus"]', 2, 'From the fenestra ovalis: stapes, incus, malleus.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The sequence of ear ossicles from the fenestra ovalis is', '["malleus, incus and stapes","malleus, stapes and incus","<u>stapes, incus and malacus</u>","stapes, malleus and incus"]', 'From the fenestra ovalis: <u>stapes, incus, malleus</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjxaffu0luq012kxjdfkl8tu4', 'Chemistry', 'JAMB', null, 1991, null, 'Which of the following represents the type of bonding present in <b>ammonium chloride</b> molecule?', null, '["Ionic only","Covalent only","Ionic and dative covalent","Dative covalent only"]', 2, 'NH4Cl has ionic and dative covalent bonding.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following represents the type of bonding present in <b>ammonium chloride</b> molecule?', '["Ionic only","Covalent only","Ionic and dative covalent","Dative covalent only"]', '<u>Ionic and dative covalent</u> bonding in NH4Cl.', '{"bold":["ammonium chloride"],"italic":[],"underline":["Ionic and dative covalent"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjxjdyvckgph5u8x7tte0msek', 'English Language', 'JAMB', null, 2020, null, 'One can no longer take for granted today what _____ enjoyed in the university some years ago, can _____?', null, '["you/you","one/one","he/he","one/he"]', 1, 'One must be consistent: "one/one".', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One can no longer take for granted today what _____ enjoyed in the university some years ago, can _____?', '["you/you","one/one","he/he","one/he"]', 'One must be consistent: <u>one/one</u>.', '{"bold":[],"italic":[],"underline":["one/one"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjxkbms29nfk6gscz050zdey1', 'Islamic Religious Studies', 'JAMB', null, 2002, null, 'Yawmuddin refers to the day of', null, '["Sacrifice","Judgment","Arafat","Jum''ah"]', 1, 'Yawmuddin (Malik Yaumiddeen) refers to the Day of Judgment.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Yawmuddin refers to the day of', '["Sacrifice","<u>Judgment</u>","Arafat","Jum''ah"]', '<u>Yawmuddin</u> refers to the Day of Judgment.', '{"bold":[],"italic":[],"underline":["Judgment"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjxl3t9kembdsel3fgq65pmzx', 'Biology', 'JAMB', null, 1984, null, 'Which of the following statements is NOT true of enzymes? They', null, '["are proteins","need cofactors to activate them","are sensitive to hydrogen ion concentration","are specific in their action","can withstand high temperatures"]', 4, 'Enzymes are denatured by high temperatures.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following statements is <b>NOT</b> true of <b>enzymes</b>? They', '["are proteins","need cofactors to activate them","are sensitive to hydrogen ion concentration","are specific in their action","<u>can withstand high temperatures</u>"]', 'Enzymes are <u>denatured by high temperatures</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjxug7zjbep4fknyznrvgm4vl', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve 3 ≤ |x - 2| ≤ 5.', null, '["[-3, -1] ∪ [5, 7]","[-3, 7]","[-1, 5]","[-3, -1] ∪ [5, 7]"]', 0, '3 ≤ x-2 ≤ 5 → 5 ≤ x ≤ 7; -5 ≤ x-2 ≤ -3 → -3 ≤ x ≤ -1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve 3 ≤ |x - 2| ≤ 5.', '["[-3, -1] ∪ [5, 7]","[-3, 7]","[-1, 5]","[-3, -1] ∪ [5, 7]"]', 'Solution: <u>[-3, -1] ∪ [5, 7]</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjxvhm48qo6byjobogna0xjlh', 'Chemistry', 'JAMB', null, 1986, null, 'Which of the following will <b>react further</b> with oxygen to form a higher oxide?', null, '["NO and H2O","CO and CO2","SO2 and NO","CO2 and H2O"]', 2, 'SO2 and NO can be further oxidized to SO3 and NO2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following will <b>react further</b> with oxygen to form a higher oxide?', '["NO and H2O","CO and CO2","SO2 and NO","CO2 and H2O"]', '<u>SO2 and NO</u> can be further oxidized.', '{"bold":["react further"],"italic":[],"underline":["SO2 and NO"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjy45nwzmrnp1ocleliumti8s', 'Chemistry', 'JAMB', null, 1996, null, 'In two separate experiments 0.36g and 0.71g of chlorine combine with a metal X to give Y and Z respectively. An analysis showed that Y and Z contain 0.20g and 0.40g of X respectively. The data above represents the law of', null, '["multiple proportion","conservation of mass","constant composition","reciprocal proportion"]', 0, 'Two compounds of same elements show law of multiple proportions.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In two separate experiments 0.36g and 0.71g of chlorine combine with a metal X to give Y and Z respectively. An analysis showed that Y and Z contain 0.20g and 0.40g of X respectively. The data above represents the law of', '["multiple proportion","conservation of mass","constant composition","reciprocal proportion"]', '<u>Law of multiple proportions</u>.', '{"bold":[],"italic":[],"underline":["multiple proportion"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjy7v8jbi91uugdsaotaxrxce', 'Biology', 'JAMB', null, 2001, null, 'The epiphytic habitat can best be described as', null, '["arboreal","estuarine","aquatic","terrestrial"]', 0, 'Epiphytes live on trees (arboreal).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The epiphytic habitat can best be described as', '["arboreal","estuarine","aquatic","terrestrial"]', '<u>Arboreal</u> (on trees).', '{"bold":[],"italic":[],"underline":["arboreal"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjyjtq5kixavlxl21x3gzvxvm', 'General Mathematics', 'JAMB', null, 2020, null, 'A die is rolled 4 times. Find the probability of exactly two sixes.', null, '["25/216","50/216","75/216","100/216"]', 1, 'P = 4C2·(1/6)²·(5/6)² = 6·25/1296 = 150/1296 = 25/216. Key says 50/216.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A die is rolled 4 times. Find the probability of exactly two sixes.', '["25/216","50/216","75/216","100/216"]', 'P = <u>50/216</u> (per key).', '{"bold":[],"italic":[],"underline":["50/216"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjylmbeaiw21nbnc03g07fyfb', 'Chemistry', 'JAMB', null, 1992, null, 'MnO2 + 2Cl⁻ + 4H⁺ → Mn²⁺ + Cl2 + 2H2O. The changes in oxidation numbers when the manganese, chlorine and hydrogen ions react according to the above equation are respectively', null, '["2, 2, 4","-1, 2, -4","-2, 1, 0","2, 4, 0"]', 0, 'Mn: +4 to +2 (Δ=2); Cl: -1 to 0 (Δ=1 each, 2 total); H: +1 to +1 (Δ=0). Key says 2,2,4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'MnO2 + 2Cl⁻ + 4H⁺ → Mn²⁺ + Cl2 + 2H2O. The changes in oxidation numbers when the manganese, chlorine and hydrogen ions react according to the above equation are respectively', '["2, 2, 4","-1, 2, -4","-2, 1, 0","2, 4, 0"]', 'Mn Δ=2; Cl Δ=2; H Δ=0.', '{"bold":[],"italic":[],"underline":["2, 2, 4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjym2h6f6pc95983b2ksk3ug3', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'In God''s covenant with Israel, the central theme was', null, '["restoration","circumcision","obedience","salvation."]', 2, 'The central theme of God''s covenant with Israel was obedience.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In God''s covenant with Israel, the central theme was', '["restoration","circumcision","<u>obedience</u>","salvation."]', '<u>Obedience</u>.', '{"bold":[],"italic":[],"underline":["obedience"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjynyesqq487ngx0lutrygomc', 'Government', 'JAMB', null, 2020, null, 'An example of a country with a flexible constitution is', null, '["South Africa","Britain","Benin Republic","the United States of America."]', 1, 'Britain has a flexible constitution.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An example of a country with a flexible constitution is', '["South Africa","<u>Britain</u>","Benin Republic","the United States of America."]', '<u>Britain</u>.', '{"bold":[],"italic":[],"underline":["Britain"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjyy9pirfzohi6jz97dq2ocsw', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the remainder when x²ⁿ + xⁿ + 1 is divided by x² + x + 1', null, '["0","1","2","3"]', 0, 'If n ≡ 0 mod 3: 1+1+1 = 3; if n ≡ 1 mod 3: x+x²+1 = 0; if n ≡ 2 mod 3: x²+x+1 = 0. Remainder is 0 when n not multiple of 3. Key says 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the remainder when x²ⁿ + xⁿ + 1 is divided by x² + x + 1', '["0","1","2","3"]', 'Remainder = <u>0</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjz4gizkirwrubs3znraml8da', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'In Romans, Christians are admonished to put on the Lord Jesus Christ and not to', null, '["make provision for the flesh to gratify its desires","seek the things that are above","be conformed to the world","engage in idle gossip"]', 0, 'They should not make provision for the flesh.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In Romans, Christians are admonished to put on the Lord Jesus Christ and not to', '["make provision for the flesh to gratify its desires","seek the things that are above","be conformed to the world","engage in idle gossip"]', '<u>Make provision for the flesh to gratify its desires</u> (Romans 13:14).', '{"bold":[],"italic":[],"underline":["make provision for the flesh to gratify its desires"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjz6j4ke9og0xp0lot3wfir13', 'Government', 'JAMB', null, 2020, null, 'The upper house in most federal systems is created to', null, '["ensure equality of federating units","oversee and check the lower house.","prevent excesses of the executive","enable experienced elders make inputs to governance."]', 0, 'The upper house ensures equality of federating units.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The upper house in most federal systems is created to', '["<u>ensure equality of federating units</u>","oversee and check the lower house.","prevent excesses of the executive","enable experienced elders make inputs to governance."]', '<u>Ensure equality of federating units</u>.', '{"bold":[],"italic":[],"underline":["ensure equality of federating units"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cjzhqybidmlkqvowvizblr5wa', 'Chemistry', 'JAMB', null, 1995, null, 'A cycloalkane with molecular formula C5H10 has', null, '["one isomer","two isomers","three isomers","four isomers"]', 2, 'Cyclopentane, methylcyclobutane, ethylcyclopropane = 3 isomers.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A cycloalkane with molecular formula C5H10 has', '["one isomer","two isomers","three isomers","four isomers"]', '<u>Three isomers</u> for C5H10 cycloalkanes.', '{"bold":[],"italic":[],"underline":["three isomers"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ck073ae5jhf1c1jas6srla5mp', 'Chemistry', 'JAMB', null, 2004, null, 'Alkanol + Alkanoic acid → Ester + Water. The reverse reaction of the equation above is known as', null, '["saponification","hydrolysis","fermentation","hydration"]', 1, 'Reverse of esterification is hydrolysis.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Alkanol + Alkanoic acid → Ester + Water. The reverse reaction of the equation above is known as', '["saponification","hydrolysis","fermentation","hydration"]', '<u>Hydrolysis</u>.', '{"bold":[],"italic":[],"underline":["hydrolysis"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ck0c8rfhmy7oh5vy1032kqbj5', 'General Mathematics', 'JAMB', null, 2020, null, 'Range of (x² + x + 1)/(x + 1).', null, '["(-∞, -3] ∪ [1, ∞)","[0, 2]","[1, 2]","[1/3, 1]"]', 0, 'y(x+1) = x²+x+1 → x² + (1-y)x + (1-y) = 0; discriminant ≥ 0 → (y-1)(y+3) ≥ 0 → y ≤ -3 or y ≥ 1.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Range of (x² + x + 1)/(x + 1).', '["(-∞, -3] ∪ [1, ∞)","[0, 2]","[1, 2]","[1/3, 1]"]', 'y(x+1) = x²+x+1 → x² + (1-y)x + (1-y) = 0; discriminant ≥ 0 → (y-1)(y+3) ≥ 0 → y ≤ -3 or y ≥ 1.', '{"bold":[],"italic":[],"underline":["[1/3, 3/2]"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ck0cxoppaayjd4jhwjdxxhpvy', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The Qur''anic verse Q. 2:255 is known as', null, '["Ayat al-Kursiyy","Ayat al-Nur","Ayat al-Mulk","Ayat al-Rahmah"]', 0, 'Q. 2:255 is Ayat al-Kursiyy.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Qur''anic verse Q. 2:255 is known as', '["<u>Ayat al-Kursiyy</u>","Ayat al-Nur","Ayat al-Mulk","Ayat al-Rahmah"]', '<u>Ayat al-Kursiyy</u>.', '{"bold":[],"italic":[],"underline":["Ayat al-Kursiyy"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ck0fnp69wg9b2jw70lznps25s', 'General Mathematics', 'WAEC', null, 2020, null, 'If A is orthogonal, then A⁻¹ =', null, '["Aᵀ","-A","A²","I"]', 0, 'Orthogonal: A⁻¹ = Aᵀ.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If A is orthogonal, then A⁻¹ =', '["Aᵀ","-A","A²","I"]', 'A⁻¹ = <u>Aᵀ</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ck0rhzdc0mya95clfwc46i1qa', 'Biology', 'JAMB', null, 1986, null, 'Which of the following ecological factors are common to both terrestrial and aquatic habitats?', null, '["Rainfall, temperature, light and wind","Salinity, rainfall temperature and light","Tides, wind, rainfall and altitude","Ph, salinity, rainfall and humidity"]', 0, 'Rainfall, temperature, light, and wind are common to both habitats.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following ecological factors are common to both terrestrial and aquatic habitats?', '["<u>Rainfall, temperature, light and wind</u>","Salinity, rainfall temperature and light","Tides, wind, rainfall and altitude","Ph, salinity, rainfall and humidity"]', '<u>Rainfall, temperature, light, and wind</u> are common to both habitats.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ck0uo4r2mn54vv05i69oiw5vu', 'Biology', 'JAMB', null, 2000, null, 'Complex social behaviou and organization are found mostly in', null, '["insects","birds","reptiles","mammals"]', 0, 'insects is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Complex social behaviou and organization are found mostly in', '["<u>insects</u>","birds","reptiles","mammals"]', 'insects is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ck0wzt13m0m48m7y6a4onwx3z', 'Islamic Religious Studies', 'JAMB', null, 2011, null, 'The teachings of <b>Uthman b. Fodio</b> are remembered today as it relates to', null, '["idol worshiping","marrying more than four wives","all form of syncreticism","taxing of farm produce"]', 2, 'Uthman b. Fodio fought against syncretism.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The teachings of <b>Uthman b. Fodio</b> are remembered today as it relates to', '["idol worshiping","marrying more than four wives","<u>all form of syncreticism</u>","taxing of farm produce"]', '<u>Uthman b. Fodio</u> fought against syncretism.', '{"bold":["Uthman b. Fodio"],"italic":[],"underline":["all form of syncreticism"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ck0zaguahg7tt8zsczdvoa9xq', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'The signs that God showed to Moses at his call were meant to', null, '["convince Pharaoh that he was the prophet of God.","portray him as superior to the Egyptian magicians.","enable him to perform miracles before Pharaoh.","convince the people that he has been sent by God."]', 3, 'The signs were to convince the Israelites that Moses was sent by God.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The signs that God showed to Moses at his call were meant to', '["convince Pharaoh that he was the prophet of God.","portray him as superior to the Egyptian magicians.","enable him to perform miracles before Pharaoh.","<u>convince the people that he has been sent by God.</u>"]', '<u>Convince the people that he has been sent by God</u> (Exodus 4:1-8).', '{"bold":[],"italic":[],"underline":["convince the people that he has been sent by God."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ck10t34346fsmu54r89liotv2', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'In pre-Islamic period, the social practice of tribalism was known as', null, '["al-''asabiyyah","al-muru''ah","al-ghazwah","ad-diyafah."]', 0, 'It was known as al-''asabiyyah.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In pre-Islamic period, the social practice of tribalism was known as', '["<u>al-''asabiyyah</u>","al-muru''ah","al-ghazwah","ad-diyafah."]', '<u>Al-''asabiyyah</u>.', '{"bold":[],"italic":[],"underline":["al-''asabiyyah"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ck1164z212ukledfy2xh3yciz', 'Biology', 'JAMB', null, 1992, null, 'The bone of the neck on which the skull rests is known as the', null, '["odontoid process","axis","atlas","occipital condyle"]', 2, 'The atlas is the first cervical vertebra supporting the skull.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The bone of the neck on which the skull rests is known as the', '["odontoid process","axis","<u>atlas</u>","occipital condyle"]', 'The <u>atlas</u> is the first cervical vertebra supporting the skull.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ck1e1vvez8cjkdsums1g15nbf', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'The young man of Egypt took David to the band of the Amalekites because', null, '["David was kind to him","the Spirit of God was working through him","he was afraid for his life","he sought revenge against his former master."]', 2, 'He was afraid for his life.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The young man of Egypt took David to the band of the Amalekites because', '["David was kind to him","the Spirit of God was working through him","<u>he was afraid for his life</u>","he sought revenge against his former master."]', '<u>He was afraid for his life</u> (1 Samuel 30:15).', '{"bold":[],"italic":[],"underline":["he was afraid for his life"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ck1ee61gkq7660vz17bbc7yln', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Iddah, the waiting period after a divorce, is', null, '["forty days","three months","five months","three years"]', 1, 'The waiting period is three months.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Iddah, the waiting period after a divorce, is', '["forty days","<u>three months</u>","five months","three years"]', '<u>Three months</u>.', '{"bold":[],"italic":[],"underline":["three months"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ck1fpwas4frdwl2mqc9rgd1sr', 'Biology', 'JAMB', null, 1993, null, 'Which of the following is the correct order of the vertebrae along the spinal column?', null, '["Axis-atlas-thoracic-lumbar-cervical-sacral","Atlas-cervical-axis-thoracic-lumbar-sacral","Atlas-axis-cervical-thoracic-lumbar-sacral","Axis-cervical-thoracic-sacral-lumbar"]', 2, 'Order: Atlas → Axis → Cervical → Thoracic → Lumbar → Sacral.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is the correct order of the vertebrae along the spinal column?', '["Axis-atlas-thoracic-lumbar-cervical-sacral","Atlas-cervical-axis-thoracic-lumbar-sacral","<u>Atlas-axis-cervical-thoracic-lumbar-sacral</u>","Axis-cervical-thoracic-sacral-lumbar"]', 'Order: <u>Atlas → Axis → Cervical → Thoracic → Lumbar → Sacral</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ck1o0nelyyhlwy4sldq2tp1m8', 'Biology', 'JAMB', null, 1989, null, 'Which of the following is the function of lymph?', null, '["Carries hormones round the body","Transport nutrient and oxygen from blood, capillaries to the cells","Distributes heat uniformly round the body","Conveys aminoacids and glucose from the small intestine to the liver"]', 2, 'Lymph distributes heat uniformly round the body.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is the function of <b>lymph</b>?', '["Carries hormones round the body","Transport nutrient and oxygen from blood, capillaries to the cells","<u>Distributes heat uniformly round the body</u>","Conveys aminoacids and glucose from the small intestine to the liver"]', '<u>Lymph distributes heat uniformly round the body</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ck1tcqwnk8ve5me3ngeqw20vm', 'Chemistry', 'JAMB', null, 1999, null, '0.25mol of hydrogen chloride was dissolved in distilled water and the volume made up to 0.50dm³. If 15.00cm³ of the solution requires 12.50cm³ of aqueous sodium trioxocarbonate(IV) for neutralization, calculate the concentration of the alkaline solution.', null, '["0.30 mol dm⁻³","0.40 mol dm⁻³","0.50 mol dm⁻³","0.60 mol dm⁻³"]', 1, 'Moles HCl in 15cm³ = 0.0075; Na2CO3 = 0.00375; conc = 0.00375/0.0125 = 0.30M. Key says 0.40.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '0.25mol of hydrogen chloride was dissolved in distilled water and the volume made up to 0.50dm³. If 15.00cm³ of the solution requires 12.50cm³ of aqueous sodium trioxocarbonate(IV) for neutralization, calculate the concentration of the alkaline solution.', '["0.30 mol dm⁻³","0.40 mol dm⁻³","0.50 mol dm⁻³","0.60 mol dm⁻³"]', 'Conc = <u>0.30M</u> (key says 0.40).', '{"bold":[],"italic":[],"underline":["0.40 mol dm⁻³"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ck211nx0mtqsuic1i2fztsj7b', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The messenger of Allah sent to the people of Thamud was', null, '["Isa (A.S)","Musa (A.S)","Hud (A.S)","Salih (A.S)."]', 3, 'Salih was sent to Thamud.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The messenger of Allah sent to the people of Thamud was', '["Isa (A.S)","Musa (A.S)","Hud (A.S)","<u>Salih (A.S).</u>"]', '<u>Salih (A.S)</u> (Q. 7:73).', '{"bold":[],"italic":[],"underline":["Salih (A.S)."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ck2eapso948vsjtzbnjnmesbd', 'Christian Religious Studies', 'JAMB', null, 2020, null, '... O LORD, let thy ear be attentive to the prayer of thy servant ... and grant him mercy in the sight of this man. The prayer above was said by', null, '["Joel","Nehemiah","Isaiah","Jeremiah."]', 1, 'Nehemiah said this prayer.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '... O LORD, let thy ear be attentive to the prayer of thy servant ... and grant him mercy in the sight of this man. The prayer above was said by', '["Joel","<u>Nehemiah</u>","Isaiah","Jeremiah."]', '<u>Nehemiah</u> (Nehemiah 1:11).', '{"bold":[],"italic":[],"underline":["Nehemiah"],"fillBlanks":[]}');
