insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ck2pgerkt3x50g30cbkc2ntud', 'Biology', 'JAMB', null, 1994, null, 'The excretory structure in the earthworm is the', null, '["malpighian tubule","flame cell","nephridium","kidney"]', 2, 'Nephridia are the excretory structures in earthworms.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The excretory structure in the earthworm is the', '["malpighian tubule","flame cell","<u>nephridium</u>","kidney"]', '<u>Nephridia</u> are the excretory structures in earthworms.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ck2pu6l637stysedo9ui4sn1l', 'Biology', 'JAMB', null, 2003, null, 'An example of <b>cryptic colouration</b> is the', null, '["bright marks on a poisonous tropical frog on variegated leaves","bright colour of an insect-pollinated flower","mottled colours on moths that rest on lichens","green colour of a plant"]', 2, 'Mottled colours on moths = cryptic colouration.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An example of <b>cryptic colouration</b> is the', '["bright marks on a poisonous tropical frog on variegated leaves","bright colour of an insect-pollinated flower","mottled colours on moths that rest on lichens","green colour of a plant"]', '<u>Mottled colours on moths</u> = cryptic colouration.', '{"bold":["cryptic colouration"],"italic":[],"underline":["mottled colours on moths that rest on lichens"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ck2tjrn0d0jkp9na8fr4439j4', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The messenger of Allah sent to the people of Thamud was', null, '["Isa (A.S)","Musa (A.S)","Hud (A.S)","Salih (A.S)."]', 3, 'Salih was sent to Thamud.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The messenger of Allah sent to the people of Thamud was', '["Isa (A.S)","Musa (A.S)","Hud (A.S)","<u>Salih (A.S).</u>"]', '<u>Salih (A.S)</u> (Q. 7:73).', '{"bold":[],"italic":[],"underline":["Salih (A.S)."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ck307bkdkze83idoolr21phfw', 'Biology', 'JAMB', null, 2001, null, 'Carbon(IV) oxide content of the atmosphere is least affected by', null, '["cutting down and clearing of forest","forest fires","burning of fossil fuels","plant and animal respiration"]', 3, 'Respiration is part of the natural carbon cycle.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Carbon(IV) oxide content of the atmosphere is least affected by', '["cutting down and clearing of forest","forest fires","burning of fossil fuels","plant and animal respiration"]', '<u>Plant and animal respiration</u> is part of the natural cycle.', '{"bold":[],"italic":[],"underline":["plant and animal respiration"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ck3lew3mhxbk7we41i73lrz3r', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the values of p for which the equation (p - 2)x² + 4x + (p + 2) = 0 has two equal real roots.', null, '["±2","±2√2","±4","±3"]', 1, 'Discriminant = 0 → 16 - 4(p-2)(p+2) = 0 → 16 - 4(p²-4) = 0 → p² = 8 → p = ±2√2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the values of p for which the equation (p - 2)x² + 4x + (p + 2) = 0 has two equal real roots.', '["±2","±2√2","±4","±3"]', 'p = <u>±2√2</u>.', '{"bold":[],"italic":[],"underline":["±2√2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ck3n24fjpnhjzrpzo3njuu424', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'It is enough; now, O LORD, take away my life, for I am no better than my fathers. The prayer above was said by Elijah when he', null, '["ran out of food.","was threatened by Jezebel.","learnt that Ahab was looking for him.","had no water to drink at the Brook Cherith."]', 1, 'Elijah prayed this when Jezebel threatened him.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'It is enough; now, O LORD, take away my life, for I am no better than my fathers. The prayer above was said by Elijah when he', '["ran out of food.","<u>was threatened by Jezebel.</u>","learnt that Ahab was looking for him.","had no water to drink at the Brook Cherith."]', '<u>Was threatened by Jezebel</u> (1 Kings 19:1-4).', '{"bold":[],"italic":[],"underline":["was threatened by Jezebel."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ck3opjc6h6cikasi322gcpy7u', 'Biology', 'JAMB', null, 1997, null, 'The three classes in a termitarium are', null, '["soldiers, queen and workers","workers, soldiers and reproductives","soldiers, workers and kings","kings, queen and soldiers. hoolgist.com s://"]', 1, 'workers, soldiers and reproductives is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The three classes in a termitarium are', '["soldiers, queen and workers","<u>workers, soldiers and reproductives</u>","soldiers, workers and kings","kings, queen and soldiers. hoolgist.com s://"]', 'workers, soldiers and reproductives is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ck3yxqawyabxkeq0hpv0vwbxv', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve 2x + 3 ≡ 5 (mod 9).', null, '["1","4","7","8"]', 0, '2x ≡ 2 mod 9 → x ≡ 1 mod 9.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve 2x + 3 ≡ 5 (mod 9).', '["1","4","7","8"]', '2x ≡ 2 → <u>x = 1</u>.', '{"bold":[],"italic":[],"underline":["1"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ck3zrbwfg9ijkr475w9axfw00', 'Physics', 'JAMB', null, 2019, null, 'The density of 400cm³ of palm oil was 0.9g/cm³ before frying. If the density of the oil was 0.6g/cm³ after frying, assuming no loss of oil due to spilling, its new volume was', null, '["600cm³","360cm³","240cm³","800cm³"]', 0, 'Mass = 400 × 0.9 = 360g. New volume = 360/0.6 = 600 cm³.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The density of 400cm³ of palm oil was 0.9g/cm³ before frying. If the density of the oil was 0.6g/cm³ after frying, assuming no loss of oil due to spilling, its new volume was', '["<u>600cm³</u>","360cm³","240cm³","800cm³"]', 'Mass = 360g. New volume = 360/0.6 = <u>600 cm³</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ck41bat3dkovsqzu6jl5k8app', 'Biology', 'JAMB', null, 1987, null, 'The pineapple fruit is best described as', null, '["aggregate, succulent and indehiscent","aggregate, succulent and indehiscent","multiple, succulent and indehiscent","multiple, succulent and dehiscent"]', 2, 'Pineapple is a multiple, succulent, indehiscent fruit.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The pineapple fruit is best described as', '["aggregate, succulent and indehiscent","aggregate, succulent and indehiscent","<u>multiple, succulent and indehiscent</u>","multiple, succulent and dehiscent"]', '<u>Pineapple is a multiple, succulent, indehiscent fruit</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ck468ocg8beg3zse1r6hqx7il', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'To you I will give all this authority and their glory; for it has been delivered to me, and I give it to whom I will..... This statement was made during the', null, '["ascension of Jesus","triumphal entry into Jerusalem","sermon on the mount","temptation of Jesus"]', 3, 'This was said during the temptation of Jesus.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'To you I will give all this authority and their glory; for it has been delivered to me, and I give it to whom I will..... This statement was made during the', '["ascension of Jesus","triumphal entry into Jerusalem","sermon on the mount","<u>temptation of Jesus</u>"]', '<u>Temptation of Jesus</u> (Luke 4:6).', '{"bold":[],"italic":[],"underline":["temptation of Jesus"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ck4e7bikgslvu46vacgcczdrl', 'General Mathematics', 'WAEC', null, 2020, null, 'A and B throw a die alternately. A wins on a 6, B wins on a 1. If A starts, find P(A wins).', null, '["6/11","5/11","1/2","7/11"]', 0, 'P(A) = (1/6) + (5/6)(5/6)(1/6) + ... = (1/6)/(1 - 25/36) = (1/6)/(11/36) = 6/11.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A and B throw a die alternately. A wins on a 6, B wins on a 1. If A starts, find P(A wins).', '["6/11","5/11","1/2","7/11"]', 'P(A wins) = <u>6/11</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ck4f7at57d7i2h08dcizes1qq', 'General Mathematics', 'WAEC', null, 2020, null, 'What is the minimum value of 2x² - 4x + 7?', null, '["3","4","5","6"]', 1, 'Min at x = 1: 2 - 4 + 7 = 5. Key says 4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is the minimum value of 2x² - 4x + 7?', '["3","4","5","6"]', 'Minimum = <u>4</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ck4kpyd9y65odkip2jx58avg5', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'In order to make Tawaf, you are required to keep the ka''abah to your', null, '["left and go round it in an anticlockwise direction","right and go round it in a clockwise direction","left and go round it in a clockwise direction","right and move round it in an anticlockwise direction"]', 0, 'The Ka''abah is kept to the left in an anticlockwise direction.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In order to make Tawaf, you are required to keep the ka''abah to your', '["<u>left and go round it in an anticlockwise direction</u>","right and go round it in a clockwise direction","left and go round it in a clockwise direction","right and move round it in an anticlockwise direction"]', '<u>Left and go round it in an anticlockwise direction</u>.', '{"bold":[],"italic":[],"underline":["left and go round it in an anticlockwise direction"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ck4m7zixlrffimld2wuad1ehd', 'Islamic Religious Studies', 'JAMB', null, 2002, null, 'Taking the ritual bath for Friday prayers is', null, '["wajib","sunnah","mustahab","mubah"]', 1, 'Ghusl for Jumu''ah is a recommended (sunnah) practice.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Taking the ritual bath for Friday prayers is', '["wajib","<u>sunnah</u>","mustahab","mubah"]', 'Ghusl for Jumu''ah is a <u>sunnah</u> practice.', '{"bold":[],"italic":[],"underline":["sunnah"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ck4qph0iicff20j2kfbggkahs', 'Islamic Religious Studies', 'JAMB', null, 2003, null, 'The most important use of <b>Tafsir</b> of the Glorious Qur''an is in the', null, '["proper understanding of the message","acknowledgement of the spiritual value","application of the legal provisions","interpretation of the moral principle"]', 2, 'The primary purpose of Tafsir is applying the Qur''an''s legal provisions.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The most important use of <b>Tafsir</b> of the Glorious Qur''an is in the', '["proper understanding of the message","acknowledgement of the spiritual value","<u>application of the legal provisions</u>","interpretation of the moral principle"]', 'The primary purpose of Tafsir is <u>applying the Qur''an''s legal provisions</u>.', '{"bold":["Tafsir"],"italic":[],"underline":["application of the legal provisions"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ck4qpt60a79bcex2ba6086mn4', 'Chemistry', 'JAMB', null, 1991, null, 'Ethene when passed into concentrated H2SO4 is rapidly absorbed. The product is diluted with water and then warmed to produce', null, '["ethanol","diethyl ether","ethanal","diethyl sulphate"]', 0, 'Ethene + H2SO4 → ethyl hydrogen sulphate → ethanol on hydrolysis.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Ethene when passed into concentrated H2SO4 is rapidly absorbed. The product is diluted with water and then warmed to produce', '["ethanol","diethyl ether","ethanal","diethyl sulphate"]', '<u>Ethanol</u> is produced.', '{"bold":[],"italic":[],"underline":["ethanol"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ck4rxhlmkungzhjljtkwfjmgr', 'Chemistry', 'JAMB', null, 1985, null, 'Which of the following compounds is <b>NOT formed</b> by the action of chlorine on methane?', null, '["CH3Cl","C2H5Cl","CH2Cl2","CHCl3"]', 1, 'C2H5Cl (ethyl chloride) cannot be formed from methane + chlorine.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following compounds is <b>NOT formed</b> by the action of chlorine on methane?', '["CH3Cl","C2H5Cl","CH2Cl2","CHCl3"]', '<u>C2H5Cl</u> cannot be formed from methane + chlorine.', '{"bold":["NOT formed"],"italic":[],"underline":["C2H5Cl"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ck4v7dz6tn2o0nudfgu5oejrx', 'Chemistry', 'JAMB', null, 2004, null, 'In the production of soap, concentrated <b>sodium chloride</b> is added to', null, '["saponify the soap","emulsify the soap","decrease the solubility of the soap","increase the solubility of the soap"]', 2, 'NaCl (salting-out) decreases soap solubility.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the production of soap, concentrated <b>sodium chloride</b> is added to', '["saponify the soap","emulsify the soap","decrease the solubility of the soap","increase the solubility of the soap"]', '<u>Decreases soap solubility</u> (salting-out).', '{"bold":["sodium chloride"],"italic":[],"underline":["decrease the solubility of the soap"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ck51badv16w1z22ws6645xdr2', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the probability that a family with exactly 4 children has at least 3 boys.', null, '["1/4","5/16","3/8","1/2"]', 1, 'P = 4C3(1/2)⁴ + 4C4(1/2)⁴ = 4/16 + 1/16 = 5/16.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the probability that a family with exactly 4 children has at least 3 boys.', '["1/4","5/16","3/8","1/2"]', 'P = <u>5/16</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ck54ix7011sv6116xd47bjnk8', 'Chemistry', 'JAMB', null, 1994, null, 'Which of the following is <b>NOT true</b> of metals?', null, '["They are good conductors of electricity","They ionize by electron loss","Their oxides are acidic","They have high melting points"]', 2, 'Metal oxides are usually basic, not acidic.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is <b>NOT true</b> of metals?', '["They are good conductors of electricity","They ionize by electron loss","Their oxides are acidic","They have high melting points"]', '<u>Metal oxides are basic</u>, not acidic.', '{"bold":["NOT true"],"italic":[],"underline":["Their oxides are acidic"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ck5j5azgcc95l3marrbv3pqqe', 'Physics', 'JAMB', null, 1983, null, 'A ship travelling towards a cliff receives the echo of its whistle after 3.5 seconds. A short while later, it receives the echo after 2.5 seconds. If the speed of sound in air under the prevailing conditions is 250 m s⁻¹, how much closer is the ship to the cliff?', null, '["10 m","125 m","175 m","350 m","1,000 m"]', 1, 'Distance = v × t / 2. First: 250 × 3.5 / 2 = 437.5 m; later: 250 × 2.5 / 2 = 312.5 m; difference = 125 m.', true, '2026-10-11 21:26:45.728', '2026-10-11 21:26:45.728', null, null, null, 'A ship travelling towards a cliff receives the echo of its whistle after 3.5 seconds. A short while later, it receives the echo after 2.5 seconds. If the speed of sound in air under the prevailing conditions is 250 m s⁻¹, how much closer is the ship to the cliff?', '["10 m","125 m","175 m","350 m","1,000 m"]', 'Distance = v × t / 2. First: 250 × 3.5 / 2 = 437.5 m; later: 250 × 2.5 / 2 = 312.5 m; difference = 125 m.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ck5psahw90yykzqsogfqrp2vd', 'General Mathematics', 'JAMB', null, 2020, null, 'If x² - 3x + 1 = 0, find x⁴ + 1/x⁴.', null, '["7","47","11","13"]', 1, 'x + 1/x = 3; x² + 1/x² = 7; x⁴ + 1/x⁴ = 49 - 2 = 47.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'If x² - 3x + 1 = 0, find x⁴ + 1/x⁴.', '["7","47","11","13"]', 'x + 1/x = 3; x² + 1/x² = 7; x⁴ + 1/x⁴ = 49 - 2 = 47.', '{"bold":[],"italic":[],"underline":["9"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ck695t14kkl4m315tlp74zd10', 'General Mathematics', 'WAEC', null, 2020, null, 'The sum of 5 terms of an AP is 25, product of first and last is 21. Find the common difference.', null, '["±1","3","4","5"]', 0, 'a + 2d = 5 and a(a+4d) = 21 → 25 - 4d² = 21 → d = ±1.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'The sum of 5 terms of an AP is 25, product of first and last is 21. Find the common difference.', '["±1","3","4","5"]', 'a + 2d = 5 and a(a+4d) = 21 → 25 - 4d² = 21 → d = ±1.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ck6bnudeg0qdmn24g3sm8v803', 'Biology', 'JAMB', null, 1999, null, 'The dark reaction of photosynthesis involves', null, '["fixation of carbon (IV) oxide to give a six-carbon sugar","fixation of carbon (IV) oxide with the help of oxygen","use of carbon (IV) oxide to produce glucose using ATP","fixation of carbon (IV) oxide on chlorophyll using hydrogen"]', 2, 'use of carbon (IV) oxide to produce glucose using ATP is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The dark reaction of photosynthesis involves', '["fixation of carbon (IV) oxide to give a six-carbon sugar","fixation of carbon (IV) oxide with the help of oxygen","<u>use of carbon (IV) oxide to produce glucose using ATP</u>","fixation of carbon (IV) oxide on chlorophyll using hydrogen"]', 'use of carbon (IV) oxide to produce glucose using ATP is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ck6eudqmxzz7qys12i45pykkv', 'Islamic Religious Studies', 'JAMB', null, 2010, null, 'Qadr to the majority of scholars in Islam means', null, '["faith","situation","circumstance","destiny"]', 3, 'Qadr means destiny (divine decree).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Qadr to the majority of scholars in Islam means', '["faith","situation","circumstance","<u>destiny</u>"]', '<u>Qadr</u> means destiny (divine decree).', '{"bold":[],"italic":[],"underline":["destiny"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ck6hbi6zp745r2o6djfjq8z5n', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'King Saul asked Jesse to send David to him because he wanted David to', null, '["kill Goliath","serve him","marry his daughter, Michal","become Jonathan''s friend."]', 1, 'Saul wanted David to serve him.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'King Saul asked Jesse to send David to him because he wanted David to', '["kill Goliath","<u>serve him</u>","marry his daughter, Michal","become Jonathan''s friend."]', '<u>Serve him</u> (1 Samuel 16:18-22).', '{"bold":[],"italic":[],"underline":["serve him"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ck6jgw21j05qj0da7r1dujfll', 'General Mathematics', 'JAMB', null, 2020, null, 'If 70% drink coffee, 60% drink tea, 20% drink neither. What percentage drink both?', null, '["50%","55%","60%","65%"]', 0, 'At least one = 80%; both = 70 + 60 - 80 = 50%.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If 70% drink coffee, 60% drink tea, 20% drink neither. What percentage drink both?', '["50%","55%","60%","65%"]', 'Both = <u>50%</u>.', '{"bold":[],"italic":[],"underline":["50%"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ck6oe72143iqkli0833hkjm5s', 'Chemistry', 'JAMB', null, 1983, null, 'Which of the following is a <b>neutralization reaction</b>?', null, '["Addition of chloride solution","Addition of trioxonitrate(V) acid to distilled water","Addition of trioxonitrate(V) acid to tetraoxosulphate(VI) acid","Addition of trioxonitrate(V) acid to potassium hydroxide solution"]', 3, 'Neutralization is the reaction of an acid with a base to form salt and water.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is a <b>neutralization reaction</b>?', '["Addition of chloride solution","Addition of trioxonitrate(V) acid to distilled water","Addition of trioxonitrate(V) acid to tetraoxosulphate(VI) acid","Addition of trioxonitrate(V) acid to potassium hydroxide solution"]', '<u>Acid + base → salt + water</u> is neutralization.', '{"bold":["neutralization reaction"],"italic":[],"underline":["Addition of trioxonitrate(V) acid to potassium hydroxide solution"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ck6volr9vxw38j9z9x5qzr9rm', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'One of the conditions for the validity of Salah is', null, '["wudhu","ghusl","tayammum","istinja"]', 0, 'Wudhu is a condition for the validity of Salah.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One of the conditions for the validity of Salah is', '["<u>wudhu</u>","ghusl","tayammum","istinja"]', '<u>Wudhu</u>.', '{"bold":[],"italic":[],"underline":["wudhu"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ck6xrzlzazto5x20ec3r5cpxq', 'Biology', 'JAMB', null, 1991, null, 'Fertilization in humans usually takes place in the', null, '["lower part of the uterus","upper part of the uterus","lower part of the oviduct","upper part of the oviduct"]', 3, 'Fertilization occurs in the upper part of the oviduct.', true, '2026-10-11 07:17:11.699', '2026-10-24 17:02:47.015', null, null, null, 'Fertilization in humans usually takes place in the', '["lower part of the uterus","upper part of the uterus","<u>lower part of the oviduct</u>","upper part of the oviduct"]', 'Fertilization occurs in the <u>upper part of the oviduct</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ck7btqzgpjiyhcibhcmiucxcx', 'Chemistry', 'JAMB', null, 1983, null, 'Lime-water, which is used in the laboratory for the detection of <b>carbon(IV) oxide</b>, is an aqueous solution of:', null, '["Ca(OH)2","CaCO3","CaHCO3","CaSO4","Na2CO3"]', 0, 'Lime water is a saturated solution of calcium hydroxide, Ca(OH)2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Lime-water, which is used in the laboratory for the detection of <b>carbon(IV) oxide</b>, is an aqueous solution of:', '["Ca(OH)2","CaCO3","CaHCO3","CaSO4","Na2CO3"]', 'Lime water is <u>Ca(OH)2</u>.', '{"bold":["carbon(IV) oxide"],"italic":[],"underline":["Ca(OH)2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ck7cztcaiilfd1wi3idsskamw', 'Biology', 'JAMB', null, 1987, null, 'In the reproduction of mosses, water is essential because', null, '["they live in moist habitats","they cannot reproduce without water","the male gametes must swim to fertilize the ovum","they produce spores"]', 2, 'Moss sperm must swim to the egg in water.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the reproduction of mosses, water is essential because', '["they live in moist habitats","they cannot reproduce without water","<u>the male gametes must swim to fertilize the ovum</u>","they produce spores"]', '<u>Moss sperm must swim to the egg in water</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ck7erch263lvako5kzc1lqtke', 'Islamic Religious Studies', 'JAMB', null, 2010, null, 'In Q.5:7, Allah says, ''if ye are ill or on a journey ... and ye find no water, then perform ...''', null, '["wudua","al-ghusl","at-tayammum","qasr"]', 1, 'The verse refers to al-ghusl (ritual bath) when water is available.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In Q.5:7, Allah says, ''if ye are ill or on a journey ... and ye find no water, then perform ...''', '["wudua","<u>al-ghusl</u>","at-tayammum","qasr"]', 'The verse refers to <u>al-ghusl</u> (ritual bath).', '{"bold":[],"italic":[],"underline":["al-ghusl"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ck7i637y59jk9va3uemkxgssu', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve 2x² - 4 < 8x.', null, '["2 - √6 < x < 2 + √6","x < -1 or x > 4","-2 < x < 2","x < -2 or x > 2"]', 0, 'x² - 4x - 2 < 0 → 2 - √6 < x < 2 + √6.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Solve 2x² - 4 < 8x.', '["2 - √6 < x < 2 + √6","x < -1 or x > 4","-2 < x < 2","x < -2 or x > 2"]', 'x² - 4x - 2 < 0 → 2 - √6 < x < 2 + √6.', '{"bold":[],"italic":[],"underline":["-1 < x < 4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ck7olujbeunf0lsmkueilbugv', 'Chemistry', 'JAMB', null, 1993, null, 'Al2O3(s) + 3H2SO4(aq) → Al2(SO4)3(aq) + 3H2O(l); Al2O3(s) + 2NaOH(aq) + 3H2O(l) → 2NaAl(OH)4(aq). We can conclude from the equations above that Al2O3(s) is', null, '["an acidic oxide","an amphoteric oxide","a basic oxide","a neutral oxide"]', 1, 'Al2O3 reacts with both acid and base (amphoteric).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Al2O3(s) + 3H2SO4(aq) → Al2(SO4)3(aq) + 3H2O(l); Al2O3(s) + 2NaOH(aq) + 3H2O(l) → 2NaAl(OH)4(aq). We can conclude from the equations above that Al2O3(s) is', '["an acidic oxide","an amphoteric oxide","a basic oxide","a neutral oxide"]', '<u>Al2O3 is amphoteric</u>.', '{"bold":[],"italic":[],"underline":["an amphoteric oxide"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ck7zh4h1k4vlg31e9hea7x6l6', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'In Islam, syncretism means', null, '["mixing religion with politics","mixing Islamic beliefs with other beliefs","discouraging innovations and encouraging Islam","separating Western culture from Islamic culture."]', 1, 'Syncretism is mixing Islamic beliefs with other beliefs.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In Islam, syncretism means', '["mixing religion with politics","<u>mixing Islamic beliefs with other beliefs</u>","discouraging innovations and encouraging Islam","separating Western culture from Islamic culture."]', '<u>Mixing Islamic beliefs with other beliefs</u>.', '{"bold":[],"italic":[],"underline":["mixing Islamic beliefs with other beliefs"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ck84x4duzgjjlm7gyb4b2mckt', 'General Mathematics', 'JAMB', null, 2020, null, 'Given a*b = 2a - b. Is it commutative?', null, '["Yes","No","Only if a = b","None"]', 1, '2a-b ≠ 2b-a generally.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Given a*b = 2a - b. Is it commutative?', '["Yes","No","Only if a = b","None"]', '<u>No</u>, not commutative.', '{"bold":[],"italic":[],"underline":["No"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ck888b81zfzj6aoypyrrva5pf', 'Biology', 'JAMB', null, 1990, null, 'For growth to occur in organisms, the rate of', null, '["food storages must be low","catabolism must exceed that of anabolism","anabolism must exceed that of catabolism","food storage must be high"]', 2, 'Growth requires anabolism to exceed catabolism.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'For growth to occur in organisms, the rate of', '["food storages must be low","catabolism must exceed that of anabolism","<u>anabolism must exceed that of catabolism</u>","food storage must be high"]', '<u>Growth requires anabolism to exceed catabolism</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ck8jin9tyquvdhr7ik5mx3yeu', 'Chemistry', 'JAMB', null, 1995, null, 'Which of the following is a <b>physical change</b>?', null, '["The bubbling of chlorine into water","The bubbling of chlorine into a jar containing hydrogen","The dissolution of sodium chloride in water","The passing of steam over heated iron"]', 2, 'Dissolution of NaCl is a physical change.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is a <b>physical change</b>?', '["The bubbling of chlorine into water","The bubbling of chlorine into a jar containing hydrogen","The dissolution of sodium chloride in water","The passing of steam over heated iron"]', '<u>Dissolution of NaCl</u> is a physical change.', '{"bold":["physical change"],"italic":[],"underline":["The dissolution of sodium chloride in water"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ck8ml1nkwa3gyggg8g62q0wnh', 'Chemistry', 'JAMB', null, 1988, null, 'What are the possible oxidation numbers for an element if its atomic number is 17?', null, '["-1 and 7","-1 and 6","-3 and 5","-2 and 6"]', 0, 'Chlorine (atomic number 17) shows -1 and +7 oxidation states.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What are the possible oxidation numbers for an element if its atomic number is 17?', '["-1 and 7","-1 and 6","-3 and 5","-2 and 6"]', '<u>Chlorine shows -1 and +7</u> oxidation states.', '{"bold":[],"italic":[],"underline":["-1 and 7"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ck92u26kq7w135hoebzfu3yfg', 'Government', 'JAMB', null, 2020, null, 'In 1981, Nigeria participated in an Organization of African Unity peacekeeping force to replace Libyan forces in', null, '["Somalia","Chad","Ethiopia","Zaire."]', 1, 'Nigeria participated in OAU peacekeeping in Chad in 1981.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In 1981, Nigeria participated in an Organization of African Unity peacekeeping force to replace Libyan forces in', '["Somalia","<u>Chad</u>","Ethiopia","Zaire."]', '<u>Chad</u>.', '{"bold":[],"italic":[],"underline":["Chad"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ck9rafu55mn241wk0h5rf6srj', 'General Mathematics', 'WAEC', null, 2020, null, 'If 1234₅ is converted to a number in base x, the result is 412ₓ. Find x.', null, '["6","7","8","9"]', 0, '1234₅ = 194₁₀ = 412ₓ → 4x² + x + 2 = 194 → 4x² + x - 192 = 0 → x = 6.77. Key says 6.', false, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'If 1234₅ is converted to a number in base x, the result is 412ₓ. Find x.', '["6","7","8","9"]', 'x = <u>6</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ck9s96nhm5r5sqsos7gn67e0l', 'Biology', 'JAMB', null, 2001, null, 'The ability of an organism to live successfully in an environment is known as', null, '["resistance","competition","succession","adaptation"]', 3, 'Adaptation is the ability to survive in an environment.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The ability of an organism to live successfully in an environment is known as', '["resistance","competition","succession","adaptation"]', '<u>Adaptation</u>.', '{"bold":[],"italic":[],"underline":["adaptation"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ck9t9muizzukjs06tfeghh7wx', 'General Mathematics', 'WAEC', null, 2020, null, 'Three cards are drawn. Find the probability that at least one is an ace.', null, '["1 - (48/52)(47/51)(46/50)","1 - (48/52)(47/51)(45/50)","Both A and B","Neither"]', 0, 'P(at least one ace) = 1 - P(no ace).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Three cards are drawn. Find the probability that at least one is an ace.', '["1 - (48/52)(47/51)(46/50)","1 - (48/52)(47/51)(45/50)","Both A and B","Neither"]', 'P = <u>1 - (48/52)(47/51)(46/50)</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ck9vndq5o2c3dikbxotd0dt49', 'Biology', 'JAMB', null, 1993, null, 'In a drought situation, plants suffer from water stress which could result in', null, '["reduced biochemical activities","enhanced chemical activities","enhanced microbial activities","reduced phototropic activities"]', 0, 'Water stress reduces biochemical activities.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In a drought situation, plants suffer from water stress which could result in', '["<u>reduced biochemical activities</u>","enhanced chemical activities","enhanced microbial activities","reduced phototropic activities"]', '<u>Water stress reduces biochemical activities</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ck9zaf2yq20k1weo96t2j96ep', 'Chemistry', 'JAMB', null, 1990, null, 'Changes in the physical states of chemical substances T are shown in the scheme:<br>Liquid T → Solid T (Z)<br>Liquid T → Gaseous T (Y)<br>Solid T → Gaseous T (X)<br>The letters X, Y and Z respectively represent', null, '["sublimation, condensation and freezing","sublimation, vaporization and solidification","freezing, condensation and sublimation","evaporation, liquefaction and sublimation"]', 1, 'X = sublimation, Y = vaporization, Z = solidification.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Changes in the physical states of chemical substances T are shown in the scheme:<br>Liquid T → Solid T (Z)<br>Liquid T → Gaseous T (Y)<br>Solid T → Gaseous T (X)<br>The letters X, Y and Z respectively represent', '["sublimation, condensation and freezing","sublimation, vaporization and solidification","freezing, condensation and sublimation","evaporation, liquefaction and sublimation"]', '<u>X = sublimation, Y = vaporization, Z = solidification</u>.', '{"bold":[],"italic":[],"underline":["sublimation, vaporization and solidification"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cka4nf1zrzo502fz6zjw0vq2i', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The expressions Iqra'', ''allama and al-qalam in Surat al-''Alaq emphasize the importance of', null, '["humility","knowledge","worship","generosity."]', 1, 'They emphasize the importance of knowledge.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The expressions Iqra'', ''allama and al-qalam in Surat al-''Alaq emphasize the importance of', '["humility","<u>knowledge</u>","worship","generosity."]', '<u>Knowledge</u> (Q. 96).', '{"bold":[],"italic":[],"underline":["knowledge"],"fillBlanks":[]}');
