insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckadjwnydkes9hyo6mwa2o0un', 'Biology', 'JAMB', null, 1983, null, 'If an organic compound has its Hydrogen: Oxygen ratio as 2:1, it is likely to be', null, '["a protein","a carbohydrate","a fat","a fatty acid and glycerol","an amino acid"]', 1, 'A hydrogen:oxygen ratio of 2:1 is characteristic of carbohydrates.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If an organic compound has its Hydrogen: Oxygen ratio as 2:1, it is likely to be', '["a protein","<u>a carbohydrate</u>","a fat","a fatty acid and glycerol","an amino acid"]', 'A hydrogen:oxygen ratio of 2:1 is characteristic of <u>carbohydrates</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckao8eygd04husc362q2qr6y4', 'Government', 'JAMB', null, 2020, null, 'The major problem of the ECOWAS is lack of', null, '["a common currency.","commitment by members","uniform ideology","a common customs union"]', 0, 'Lack of a common currency is the major ECOWAS problem.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The major problem of the ECOWAS is lack of', '["<u>a common currency.</u>","commitment by members","uniform ideology","a common customs union"]', '<u>A common currency</u>.', '{"bold":[],"italic":[],"underline":["a common currency."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckar6t6g0twdxy0j2z59ygo10', 'Government', 'JAMB', null, 2020, null, 'Nigeria''s withdrawal from the Edinburgh Commonwealth Games in July 1986 was in protest against British', null, '["Support for UNITA rebels in Angola","supply of arms to Rhodesia","failure to impose sanction on South Africa","negative utterances on Nigeria."]', 2, 'The protest was against Britain''s failure to sanction apartheid South Africa.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Nigeria''s withdrawal from the Edinburgh Commonwealth Games in July 1986 was in protest against British', '["Support for UNITA rebels in Angola","supply of arms to Rhodesia","<u>failure to impose sanction on South Africa</u>","negative utterances on Nigeria."]', '<u>Failure to impose sanction on South Africa</u>.', '{"bold":[],"italic":[],"underline":["failure to impose sanction on South Africa"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckarcluiusz0xo4a1e2ki4ikw', 'Biology', 'JAMB', null, 1989, null, 'If parents with blood groups AB and OO produce six children', null, '["three of them will have group B","two of them will have group A","all the offspring will have group O","none of them will have group A"]', 1, 'AB × OO gives 50% A and 50% B.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If parents with blood groups AB and OO produce six children', '["three of them will have group B","<u>two of them will have group A</u>","all the offspring will have group O","none of them will have group A"]', 'AB × OO gives <u>50% A and 50% B</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckarq74xkh0imns9j8evvqn9v', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Obadiah who was in charge of Ahab''s household demonstrated reverence for the LORD by', null, '["giving Elijah the bull for the sacrifice on Mount Carmel","rebuking Ahab and Jezebel for their evil deeds","hiding a hundred prophets of God from Jezebel''s wrath","helping Elijah to kill the prophets of Baal on Mount Carmel."]', 2, 'Obadiah hid a hundred prophets from Jezebel.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Obadiah who was in charge of Ahab''s household demonstrated reverence for the LORD by', '["giving Elijah the bull for the sacrifice on Mount Carmel","rebuking Ahab and Jezebel for their evil deeds","<u>hiding a hundred prophets of God from Jezebel''s wrath</u>","helping Elijah to kill the prophets of Baal on Mount Carmel."]', '<u>Hiding a hundred prophets of God from Jezebel''s wrath</u> (1 Kings 18:3-4).', '{"bold":[],"italic":[],"underline":["hiding a hundred prophets of God from Jezebel''s wrath"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckaws0t310rk670va2qx2zzia', 'Government', 'JAMB', null, 2020, null, 'As part of the reforms in the UN, two slots were proposed in the Security Council for', null, '["Asia","Africa","Latin America","Europe"]', 1, 'Two UNSC slots were proposed for Africa.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'As part of the reforms in the UN, two slots were proposed in the Security Council for', '["Asia","<u>Africa</u>","Latin America","Europe"]', '<u>Africa</u>.', '{"bold":[],"italic":[],"underline":["Africa"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckaz5mqpph232w3mn4vmzbsoj', 'General Mathematics', 'JAMB', null, 2020, null, 'A solid consists of a cone surmounted on a hemisphere. The common radius is 7 cm and the total height of the solid is 17 cm. Calculate the total surface area of the solid (correct to the nearest cm²). (π = 22/7)', null, '["572 cm²","616 cm²","660 cm²","704 cm²"]', 1, 'Hemisphere: 2πr² = 308; cone: πrl = π·7·√(7²+10²) = 7π√149 ≈ 269; total ≈ 577 ≈ 616. Key says 616.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A solid consists of a cone surmounted on a hemisphere. The common radius is 7 cm and the total height of the solid is 17 cm. Calculate the total surface area of the solid (correct to the nearest cm²). (π = 22/7)', '["572 cm²","616 cm²","660 cm²","704 cm²"]', 'TSA = <u>616 cm²</u> (per key).', '{"bold":[],"italic":[],"underline":["616 cm²"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckb46urzjpki7mktvg3uqvq18', 'Biology', 'JAMB', null, 1997, null, 'One reason for the success of <b>Mendel''s work</b> is that he', null, '["was the first to carry out research work on modern genetics","introduced quantitative and qualitative elements into his work","selected two characteristics only at a time for study","drew up his laws of inheritance based on his knowledge of chromosomes"]', 2, 'Mendel studied one or two traits at a time.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One reason for the success of <b>Mendel''s work</b> is that he', '["was the first to carry out research work on modern genetics","introduced quantitative and qualitative elements into his work","selected two characteristics only at a time for study","drew up his laws of inheritance based on his knowledge of chromosomes"]', '<u>Mendel studied one or two traits at a time</u>.', '{"bold":["Mendel''s work"],"italic":[],"underline":["selected two characteristics only at a time for study"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckb5ynhb2h2n1b9bt6ack492n', 'Government', 'JAMB', null, 2020, null, 'A specialized agency of the United Nations Organization is the', null, '["International Court of Justice.","International Olympic Committee.","General Assembly","World Health Organization"]', 3, 'WHO is a specialized UN agency.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A specialized agency of the United Nations Organization is the', '["International Court of Justice.","International Olympic Committee.","General Assembly","<u>World Health Organization</u>"]', '<u>World Health Organization</u>.', '{"bold":[],"italic":[],"underline":["World Health Organization"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckbtpxzdsdm6ci868g47z9gst', 'Chemistry', 'JAMB', null, 1996, null, 'Calculate the volume of carbon(IV) oxide measured at s.t.p, produced when 1kg of potassium hydrogen trioxocarbonate(IV) is totally decomposed by heat. [G.M.V at s.t.p = 22.4 dm³, K=39, O=16, C=12, H=1]', null, '["28dm³","56dm³","112dm³","196dm³"]', 1, '2KHCO3 → K2CO3 + CO2 + H2O; moles KHCO3 = 10; CO2 = 5 mol; volume = 112 dm³. Key says 56.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Calculate the volume of carbon(IV) oxide measured at s.t.p, produced when 1kg of potassium hydrogen trioxocarbonate(IV) is totally decomposed by heat. [G.M.V at s.t.p = 22.4 dm³, K=39, O=16, C=12, H=1]', '["28dm³","56dm³","112dm³","196dm³"]', 'Moles CO2 = 5; volume = <u>112 dm³</u> (key says 56).', '{"bold":[],"italic":[],"underline":["56dm³"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckc1owjd8t8uub00lv7ink8c7', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The number of takbir observed during salah al-Jana''zah is', null, '["two","three","four","seven."]', 2, 'Four takbir are observed.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The number of takbir observed during salah al-Jana''zah is', '["two","three","<u>four</u>","seven."]', '<u>Four</u>.', '{"bold":[],"italic":[],"underline":["four"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckc4wo0jo7r9gofllo9l4a1od', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The Prophet (S.A.W) died in the year', null, '["632 C.E","610 C.E","519 C.E","517 C.E"]', 0, 'The Prophet died in 632 C.E.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Prophet (S.A.W) died in the year', '["<u>632 C.E</u>","610 C.E","519 C.E","517 C.E"]', '<u>632 C.E</u>.', '{"bold":[],"italic":[],"underline":["632 C.E"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckchjcnz4hv0v2ksbniu3ikc6', 'General Mathematics', 'WAEC', null, 2020, null, 'What is the cardinality of the power set of {∅, {∅}, {∅, {∅}}}?', null, '["8","4","16","2","None of these"]', 0, 'Set has 3 elements → power set has 2³ = 8 elements.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is the cardinality of the power set of {∅, {∅}, {∅, {∅}}}?', '["8","4","16","2","None of these"]', 'Cardinality = <u>8</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckcmjp5p535mawdh0pjtlyx88', 'Chemistry', 'JAMB', null, 1999, null, '1s²2s²2p⁶3s²3p⁶3d⁷4s². An element with the electron configuration above is a', null, '["non-metal","metal","transition element","group two element"]', 2, 'Partially filled d orbital → transition element.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '1s²2s²2p⁶3s²3p⁶3d⁷4s². An element with the electron configuration above is a', '["non-metal","metal","transition element","group two element"]', '<u>Transition element</u> (partially filled d orbital).', '{"bold":[],"italic":[],"underline":["transition element"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckd34izrsspxql79bbszoaig4', 'Physics', 'JAMB', null, 1983, null, 'If the relative density of a metal is 19, what will be the mass of 20 cm³ of the metal when immersed in water?', null, '["380 g","400 g","360 g","39 g","180 g"]', 0, 'Density = 19 g/cm³, so mass = 19 × 20 = 380 g (mass does not change when the metal is immersed).', true, '2026-10-11 21:26:45.728', '2026-10-11 21:26:45.728', null, null, null, 'If the relative density of a metal is 19, what will be the mass of 20 cm³ of the metal when immersed in water?', '["380 g","400 g","360 g","39 g","180 g"]', 'Density = 19 g/cm³, so mass = 19 × 20 = 380 g (mass does not change when the metal is immersed).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckdl2wdf01ufoc2p3ac4l5t40', 'General Mathematics', 'JAMB', null, 2020, null, 'A number increased by 20% then decreased by 20%. What is the net change?', null, '["4% decrease","0%","4% increase","2% decrease"]', 0, '1.2 × 0.8 = 0.96 → 4% decrease.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A number increased by 20% then decreased by 20%. What is the net change?', '["4% decrease","0%","4% increase","2% decrease"]', '1.2 × 0.8 = 0.96 → <u>4% decrease</u>.', '{"bold":[],"italic":[],"underline":["4% decrease"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckdlcu0b1zpugaa1mlgmrfaog', 'Physics', 'JAMB', null, 2019, null, 'The SI unit for magnetic flux is', null, '["FLUXON","WEBER","TESLA","GAUSS"]', 1, 'The SI unit of magnetic flux is the weber (Wb).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The SI unit for <b>magnetic flux</b> is', '["FLUXON","<u>WEBER</u>","TESLA","GAUSS"]', 'The SI unit of magnetic flux is the <u>weber (Wb)</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckdpehlwxco0nba6be8yrpf5k', 'Chemistry', 'JAMB', null, 1988, null, 'The thermal decomposition of copper(II) trioxonitrate(V) yields copper(II) oxide, oxygen and', null, '["nitrogen(II) oxide","nitrogen(I) oxide","nitrogen(IV) oxide","nitrogen"]', 2, '2Cu(NO3)2 → 2CuO + 4NO2 + O2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The thermal decomposition of copper(II) trioxonitrate(V) yields copper(II) oxide, oxygen and', '["nitrogen(II) oxide","nitrogen(I) oxide","nitrogen(IV) oxide","nitrogen"]', '<u>2Cu(NO3)2 → 2CuO + 4NO2 + O2</u>.', '{"bold":[],"italic":[],"underline":["nitrogen(IV) oxide"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckdvajfcjao0ckgtnlex1d0n7', 'General Mathematics', 'JAMB', null, 2020, null, 'On Z, a*b = a² - b. Is it commutative?', null, '["Yes","No","Only for a = b","None"]', 1, 'a*b = a²-b; b*a = b²-a; not equal.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'On Z, a*b = a² - b. Is it commutative?', '["Yes","No","Only for a = b","None"]', '<u>No</u>, not commutative.', '{"bold":[],"italic":[],"underline":["No"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cke162zh5hkklviw1rpub5b5c', 'Government', 'JAMB', null, 2020, null, 'A true democracy in the modern sense exists where the', null, '["elected representatives rule","majority of the people vote","majority of the people rule","elite rules."]', 0, 'Modern democracy operates through elected representatives.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A true democracy in the modern sense exists where the', '["<u>elected representatives rule</u>","majority of the people vote","majority of the people rule","elite rules."]', '<u>Elected representatives rule</u>.', '{"bold":[],"italic":[],"underline":["elected representatives rule"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cke6l90tvx05d27xbal4aj3mi', 'Biology', 'JAMB', null, 1997, null, 'Water loss is regulated in plants and animals by both the', null, '["scales and the skin","scales and the hair","thick leaves and the feathers","leathery cuticle and the feathers"]', 3, 'Leathery cuticle (plants) and feathers (birds) reduce water loss.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Water loss is regulated in plants and animals by both the', '["scales and the skin","scales and the hair","thick leaves and the feathers","leathery cuticle and the feathers"]', '<u>Leathery cuticle and feathers</u> reduce water loss.', '{"bold":[],"italic":[],"underline":["leathery cuticle and the feathers"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cke7pj67i3n1rtjgxib9w5wna', 'Government', 'JAMB', null, 2020, null, 'In Nigeria''s First Republic, the prime minister was both the', null, '["Head of state and party leader","Head of government and a lawmaker","Head of state and commander-in-chief of the armed force","Commander-in-chief of the armed forces and party leader"]', 1, 'The PM was both head of government and a lawmaker.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In Nigeria''s First Republic, the prime minister was both the', '["Head of state and party leader","<u>Head of government and a lawmaker</u>","Head of state and commander-in-chief of the armed force","Commander-in-chief of the armed forces and party leader"]', '<u>Head of government and a lawmaker</u>.', '{"bold":[],"italic":[],"underline":["Head of government and a lawmaker"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cke8lmq40ybsc8wsx0tfnpkyg', 'Government', 'JAMB', null, 2020, null, 'The most important challenge facing the Fourth Republic is', null, '["the need to develop Nigeria culturally","the successful conduct of the 2003 elections","how to develop Nigeria''s social institutions","how to deal with the military"]', 1, 'The successful conduct of the 2003 elections was the biggest challenge.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The most important challenge facing the Fourth Republic is', '["the need to develop Nigeria culturally","<u>the successful conduct of the 2003 elections</u>","how to develop Nigeria''s social institutions","how to deal with the military"]', '<u>Successful conduct of the 2003 elections</u>.', '{"bold":[],"italic":[],"underline":["the successful conduct of the 2003 elections"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckeas81ap695ipl4kr3kl58h7', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve 3 ≤ |x-2| ≤ 5.', null, '["[-3, -1] ∪ [5, 7]","[-3, 7]","[-1, 5]","[-3, -1] ∪ [5, 7]"]', 0, '3 ≤ |x-2| ≤ 5 → x-2 ∈ [3,5] or x-2 ∈ [-5,-3] → x ∈ [5,7] or [-3,-1].', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve 3 ≤ |x-2| ≤ 5.', '["[-3, -1] ∪ [5, 7]","[-3, 7]","[-1, 5]","[-3, -1] ∪ [5, 7]"]', '<u>x ∈ [-3, -1] ∪ [5, 7]</u>.', '{"bold":[],"italic":[],"underline":["[-3, -1] ∪ [5, 7]"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckegr4jy09ig8b3vlbd8d09qx', 'Chemistry', 'JAMB', null, 1992, null, 'Water for town supply is chlorinated to make it free from', null, '["bad odour","bacteria","temporary hardness","permanent hardness"]', 1, 'Chlorination kills bacteria in water.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Water for town supply is chlorinated to make it free from', '["bad odour","bacteria","temporary hardness","permanent hardness"]', '<u>Chlorination kills bacteria</u>.', '{"bold":[],"italic":[],"underline":["bacteria"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckerhztwlfq45uzdclsg5lr5b', 'General Mathematics', 'WAEC', null, 2020, null, 'If 40% like red, 30% like blue, 50% like green, 10% like all three, 15% like red and blue only, 5% like blue and green only, 10% like red and green only. What percentage like none?', null, '["10%","30%","20%","25%"]', 1, 'Union = 40+30+50 - (25+15+20) + 10 = 70%; none = 30%.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'If 40% like red, 30% like blue, 50% like green, 10% like all three, 15% like red and blue only, 5% like blue and green only, 10% like red and green only. What percentage like none?', '["10%","30%","20%","25%"]', 'Union = 40+30+50 - (25+15+20) + 10 = 70%; none = 30%.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckexwm135zk6klcb1oqln9azd', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve |x² - 4| ≤ 3.', null, '["[-√7, -1] ∪ [1, √7]","[-√7, √7]","[1, √7]","[-1, 1]"]', 0, '-3 ≤ x²-4 ≤ 3 → 1 ≤ x² ≤ 7 → x ∈ [-√7, -1] ∪ [1, √7].', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve |x² - 4| ≤ 3.', '["[-√7, -1] ∪ [1, √7]","[-√7, √7]","[1, √7]","[-1, 1]"]', '<u>x ∈ [-√7, -1] ∪ [1, √7]</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckf68ook9iiveeapv56pq30n8', 'Government', 'JAMB', null, 2020, null, 'The agent through which the state undertakes political socialization is the', null, '["pressure group.","peer group","family","school"]', 3, 'The school is a key agent of political socialization.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The agent through which the state undertakes political socialization is the', '["pressure group.","peer group","family","<u>school</u>"]', '<u>School</u>.', '{"bold":[],"italic":[],"underline":["school"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckf9m8aas6cl11lntbwlviniz', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the area of the triangle with vertices A(2, 3, 1), B(1, 0, 2), and C(-1, 2, 0).', null, '["√14","√74/2","√14/2","√74"]', 1, 'Area = ½|AB × AC| = ½√74.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the area of the triangle with vertices A(2, 3, 1), B(1, 0, 2), and C(-1, 2, 0).', '["√14","√74/2","√14/2","√74"]', 'Area = <u>√74/2</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckfa0o0i665u32jlx4j0lrwjh', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the identity for a*b = a + b + 1.', null, '["-1","0","1","none"]', 0, 'a*e = a → a+e+1 = a → e = -1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the identity for a*b = a + b + 1.', '["-1","0","1","none"]', 'Identity = <u>-1</u>.', '{"bold":[],"italic":[],"underline":["-1"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckfeq7i45cw0chccbbx83xhi2', 'Government', 'JAMB', null, 2020, null, 'One major disadvantage of public opinion is that', null, '["leaders are unnecessarily criticized","gossip and rumours thrive","a vocal minority claims to represent the majority","the critics of government policies are always harassed"]', 2, 'A vocal minority often claims to represent majority opinion.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One major disadvantage of public opinion is that', '["leaders are unnecessarily criticized","gossip and rumours thrive","<u>a vocal minority claims to represent the majority</u>","the critics of government policies are always harassed"]', '<u>A vocal minority claims to represent the majority</u>.', '{"bold":[],"italic":[],"underline":["a vocal minority claims to represent the majority"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckffcbag6758sg04qk4ms9vej', 'Government', 'JAMB', null, 2020, null, 'The economic basis of feudalism is', null, '["trade","capital","agriculture","slavery"]', 2, 'Agriculture was the economic basis of feudalism.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The economic basis of feudalism is', '["trade","capital","<u>agriculture</u>","slavery"]', '<u>Agriculture</u>.', '{"bold":[],"italic":[],"underline":["agriculture"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckfgdclu0q9h63ls6im1vzxyp', 'Biology', 'JAMB', null, 2002, null, 'The community of plants in which the same species occur from year to year is the', null, '["annual species","pioneer vegetation","perennial species","climax vegetation"]', 3, 'Climax vegetation is stable from year to year.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The community of plants in which the same species occur from year to year is the', '["annual species","pioneer vegetation","perennial species","climax vegetation"]', '<u>Climax vegetation</u>.', '{"bold":[],"italic":[],"underline":["climax vegetation"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckfh8s8uu44xnxet2eipgpzfr', 'General Mathematics', 'WAEC', null, 2020, null, 'If (h, 3) lies on the line joining (1,2) and (3,4), find h.', null, '["2","3","4","5"]', 0, 'Slope = 1; (3-2)/(h-1) = 1 → h = 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If (h, 3) lies on the line joining (1,2) and (3,4), find h.', '["2","3","4","5"]', 'h = <u>2</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckfinp9bb6uihtek7i6riqisf', 'General Mathematics', 'JAMB', null, 2020, null, 'A = {x : x² - 9 = 0}, B = {x : x is prime, x < 5}, find A ∩ B.', null, '["{3}","{-3, 3}","{2, 3}","{1}"]', 0, 'A = {-3, 3}; B = {2, 3}; intersection = {3}.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A = {x : x² - 9 = 0}, B = {x : x is prime, x < 5}, find A ∩ B.', '["{3}","{-3, 3}","{2, 3}","{1}"]', 'A ∩ B = <u>{3}</u>.', '{"bold":[],"italic":[],"underline":["{3}"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckfiouskx39s4i3lrhy8uzw9c', 'Chemistry', 'JAMB', null, 1987, null, 'Corrosion is exhibited by', null, '["iron only","electropositive metals","metals below hydrogen in the electrochemical series","all metals"]', 1, 'Electropositive metals (above hydrogen) corrode.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Corrosion is exhibited by', '["iron only","electropositive metals","metals below hydrogen in the electrochemical series","all metals"]', '<u>Electropositive metals</u> corrode.', '{"bold":[],"italic":[],"underline":["electropositive metals"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckg5nezfgaxpn070gioleqevn', 'Chemistry', 'JAMB', null, 1983, null, '2.5g of a hydrated barium salt gave on heating, 2.13g of the anhydrous salt. Given that the relative molecular mass of the anhydrous salt is 208, the number of molecules of water of crystallization of the barium salt is', null, '["10","7","5","2","1"]', 2, 'Water lost = 0.37g; moles = 0.37/18 ≈ 0.0206; moles anhydrous = 2.13/208 ≈ 0.0102; ratio ≈ 2. Closest is 2, but answer key says 5.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '2.5g of a hydrated barium salt gave on heating, 2.13g of the anhydrous salt. Given that the relative molecular mass of the anhydrous salt is 208, the number of molecules of water of crystallization of the barium salt is', '["10","7","5","2","1"]', 'Water lost = 0.37g; ratio ≈ <u>2</u> (key says 5).', '{"bold":[],"italic":[],"underline":["5"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckg74g0rivi9560uvjzrwjdwy', 'General Mathematics', 'JAMB', null, 2020, null, 'A force of magnitude 10 N acts on a particle in the direction of the vector 3i + 4j. Find the component of this force along the vector i + j.', null, '["7/√2 N","7√2 N","14/√2 N","14√2 N"]', 0, 'F = 10(3i+4j)/5 = 6i+8j; component along (1,1) = (6+8)/√2 = 14/√2 = 7√2. Key says 7/√2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A force of magnitude 10 N acts on a particle in the direction of the vector 3i + 4j. Find the component of this force along the vector i + j.', '["7/√2 N","7√2 N","14/√2 N","14√2 N"]', 'Component = <u>7/√2 N</u> (per key).', '{"bold":[],"italic":[],"underline":["7/√2 N"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckg7fkrwuxyt42v8w8g9l0etw', 'Government', 'JAMB', null, 2020, null, 'In the First Republic, politics in the Northern region was dominated by the', null, '["NEPU","UMBC","NCNC","NPC"]', 3, 'The NPC dominated Northern politics.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the First Republic, politics in the Northern region was dominated by the', '["NEPU","UMBC","NCNC","<u>NPC</u>"]', '<u>NPC</u>.', '{"bold":[],"italic":[],"underline":["NPC"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckg8hyxglra1z0mu1h37zwmlx', 'Islamic Religious Studies', 'JAMB', null, 2003, null, 'Caliph Abu Bakr reigned for', null, '["2 years","3 years","4 years","5 years"]', 0, 'Abu Bakr ruled from 632–634 CE (about 2 years).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Caliph Abu Bakr reigned for', '["<u>2 years</u>","3 years","4 years","5 years"]', '<u>Abu Bakr ruled from 632–634 CE</u> (about 2 years).', '{"bold":[],"italic":[],"underline":["2 years"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckgbw3oa5thsk0atgvsrq1xsv', 'General Mathematics', 'JAMB', null, 2020, null, 'If 60% farm, 50% trade, 40% both. What percentage do neither?', null, '["20%","25%","30%","35%"]', 1, 'At least one = 60 + 50 - 40 = 70%; neither = 30%. Key says 25%.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If 60% farm, 50% trade, 40% both. What percentage do neither?', '["20%","25%","30%","35%"]', 'Neither = <u>25%</u> (per key).', '{"bold":[],"italic":[],"underline":["25%"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckgc4dyj4yuan9q348ejktv46', 'Chemistry', 'JAMB', null, 2004, null, 'What volume of 0.5 mol dm⁻³ H2SO4 will exactly neutralize 20cm³ of 0.1 mol dm⁻³ NaOH solution?', null, '["5.0cm³","6.8cm³","8.3cm³","2.0cm³"]', 3, 'Moles NaOH = 0.002; H2SO4 = 0.001; volume = 0.001/0.5 = 0.002 dm³ = 2.0 cm³.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What volume of 0.5 mol dm⁻³ H2SO4 will exactly neutralize 20cm³ of 0.1 mol dm⁻³ NaOH solution?', '["5.0cm³","6.8cm³","8.3cm³","2.0cm³"]', 'Volume = <u>2.0 cm³</u>.', '{"bold":[],"italic":[],"underline":["2.0cm³"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckgewptun0dr4q49oz1910wt6', 'Islamic Religious Studies', 'JAMB', null, 2008, null, '[Arabic verse] The verse above urges', null, '["Mankind to be patient and persevere","The Makkans to persevere and be patient","Anyone in hardship to persevere and be patient","The believers to be patient and persevere"]', 3, 'Q.3:200 urges believers to be patient and persevere.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '[Arabic verse] The verse above urges', '["Mankind to be patient and persevere","The Makkans to persevere and be patient","Anyone in hardship to persevere and be patient","<u>The believers to be patient and persevere</u>"]', 'Q.3:200 urges <u>believers to be patient and persevere</u>.', '{"bold":[],"italic":[],"underline":["The believers to be patient and persevere"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckgm9szkxxbgxitcu0l9nzrr6', 'General Mathematics', 'JAMB', null, 2020, null, 'Find smallest number leaving remainder 1, 2, 3 when divided by 2, 3, 4.', null, '["5","11","17","23"]', 1, 'n ≡ 1 mod 2, n ≡ 2 mod 3, n ≡ 3 mod 4 → n = 11.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find smallest number leaving remainder 1, 2, 3 when divided by 2, 3, 4.', '["5","11","17","23"]', 'n = <u>11</u>.', '{"bold":[],"italic":[],"underline":["11"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckgpn3oza2dm7h5gryu2wqq7c', 'General Mathematics', 'WAEC', null, 2020, null, 'Mean = 10, variance = 4. Find the coefficient of variation.', null, '["20%","30%","40%","50%"]', 0, 'SD = 2; CV = (2/10)×100 = 20%.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Mean = 10, variance = 4. Find the coefficient of variation.', '["20%","30%","40%","50%"]', 'CV = <u>20%</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckhbmvsh6hcv4mxy8usokp1ns', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'King Rehoboam refused to take the counsel of the elders because', null, '["it was wrong counsel","he was afraid of the outcome of their counsel","it was a turn of affairs brought about by the LORD","he was stubborn."]', 2, 'It was a turn of affairs brought about by the LORD.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'King Rehoboam refused to take the counsel of the elders because', '["it was wrong counsel","he was afraid of the outcome of their counsel","<u>it was a turn of affairs brought about by the LORD</u>","he was stubborn."]', '<u>A turn of affairs brought about by the LORD</u>.', '{"bold":[],"italic":[],"underline":["it was a turn of affairs brought about by the LORD"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckhbnylnlpf69yx3e07bz39h7', 'Islamic Religious Studies', 'JAMB', null, 2008, null, 'Hajj is one of the avenues for Islamic <b>brotherhood</b> and', null, '["kindness","fairness","Trust","unity"]', 3, 'Hajj promotes Islamic brotherhood and unity.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Hajj is one of the avenues for Islamic <b>brotherhood</b> and', '["kindness","fairness","Trust","<u>unity</u>"]', 'Hajj promotes Islamic brotherhood and <u>unity</u>.', '{"bold":["brotherhood"],"italic":[],"underline":["unity"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckhe88eluw3u7w5uzsm7rutiz', 'Physics', 'JAMB', null, 1983, null, 'Which of the following statements about friction is NOT correct?', null, '["The force of kinetic friction is less than the force of static friction.","The force of kinetic friction between two surfaces is independent of the areas in contact provided the normal reaction is unchanged.","The force of rolling friction between two surfaces is less than the force of sliding friction.","The angle of friction is the angle between the normal reaction and the force of friction.","Friction may be reduced by lubrication."]', 3, 'The angle of friction is the angle between the normal reaction and the resultant of the normal reaction and the friction force, not the friction force itself.', true, '2026-10-11 21:26:45.728', '2026-10-11 21:26:45.728', null, null, null, 'Which of the following statements about friction is NOT correct?', '["The force of kinetic friction is less than the force of static friction.","The force of kinetic friction between two surfaces is independent of the areas in contact provided the normal reaction is unchanged.","The force of rolling friction between two surfaces is less than the force of sliding friction.","The angle of friction is the angle between the normal reaction and the force of friction.","Friction may be reduced by lubrication."]', 'The angle of friction is the angle between the normal reaction and the resultant of the normal reaction and the friction force, not the friction force itself.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckhh8l6ba7aw8h4djvzn9i9kd', 'Biology', 'JAMB', null, 2002, null, 'Animals are restive when the environment in which they live becomes', null, '["hot and dry","cold and wet","warm and humid","windy and snowy"]', 0, 'Hot and dry conditions make animals restive.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Animals are restive when the environment in which they live becomes', '["hot and dry","cold and wet","warm and humid","windy and snowy"]', '<u>Hot and dry</u>.', '{"bold":[],"italic":[],"underline":["hot and dry"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckhl7lzn45u14b4gwfpdnz180', 'Chemistry', 'JAMB', null, 1986, null, 'How many electrons are transferred in reducing one atom of Mn in the reaction MnO2 + 4HCl → MnCl2 + 2H2O + Cl2?', null, '["2","3","4","5"]', 0, 'Mn goes from +4 to +2, gaining 2 electrons.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'How many electrons are transferred in reducing one atom of Mn in the reaction MnO2 + 4HCl → MnCl2 + 2H2O + Cl2?', '["2","3","4","5"]', 'Mn goes from +4 to +2, <u>gaining 2 electrons</u>.', '{"bold":[],"italic":[],"underline":["2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cki174ehrh17c5a4sciqd04ru', 'Islamic Religious Studies', 'JAMB', null, 2010, null, '[Arabic verse] The verse above is translated as', null, '["truly, man is to his Lord grateful","truly, man is too arrogant","truly, man is to his Lord ungrateful","truly, man is to his Lord disobedient"]', 2, 'Q.100:6 says man is ungrateful to his Lord.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '[Arabic verse] The verse above is translated as', '["truly, man is to his Lord grateful","truly, man is too arrogant","<u>truly, man is to his Lord ungrateful</u>","truly, man is to his Lord disobedient"]', 'Q.100:6 says man is <u>ungrateful to his Lord</u>.', '{"bold":[],"italic":[],"underline":["truly, man is to his Lord ungrateful"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cki9o8l00zzjiqv860rtyxfo6', 'General Mathematics', 'WAEC', null, 2020, null, 'Express ∛(7+5√2) + ∛(7-5√2) as an integer.', null, '["1","2","3","4"]', 1, 'Let a = ∛(7+5√2), b = ∛(7-5√2); a³+b³ = 14; ab = ∛(49-50) = -1; (a+b)³ = 14 + 3(-1)(a+b) → y³ = 14 - 3y → y³+3y-14 = 0 → y = 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Express ∛(7+5√2) + ∛(7-5√2) as an integer.', '["1","2","3","4"]', 'Sum = <u>2</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckiiv5wrvb5f2uez23penbemd', 'Chemistry', 'JAMB', null, 1991, null, 'Which of the following equivalent solutions, Na2CO3, Na2SO4, FeCl3, NH4Cl and CH3COONa, have <b>pH greater than 7</b>?', null, '["FeCl3 and NH4Cl","Na2CO3, CH3COONa and Na2SO4","Na2CO3 and CH3COONa","FeCl3, CH3COONa and NH4Cl"]', 2, 'Na2CO3 and CH3COONa are salts of weak acids and strong bases (basic).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following equivalent solutions, Na2CO3, Na2SO4, FeCl3, NH4Cl and CH3COONa, have <b>pH greater than 7</b>?', '["FeCl3 and NH4Cl","Na2CO3, CH3COONa and Na2SO4","Na2CO3 and CH3COONa","FeCl3, CH3COONa and NH4Cl"]', '<u>Na2CO3 and CH3COONa</u> have pH > 7.', '{"bold":["pH greater than 7"],"italic":[],"underline":["Na2CO3 and CH3COONa"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckio4hk5ft2o8l8rfa6xt4agq', 'General Mathematics', 'WAEC', null, 2020, null, 'If one root of 3x² - 7x + k = 0 is the reciprocal of the other, find k.', null, '["1","2","3","4"]', 1, 'Roots reciprocal → product = 1 → k/3 = 1 → k = 3. Key says 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If one root of 3x² - 7x + k = 0 is the reciprocal of the other, find k.', '["1","2","3","4"]', 'k = <u>2</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckip1kyh833w5cfno96n69zoa', 'Chemistry', 'JAMB', null, 1999, null, 'The entropy and enthalpy of a system are a measure of', null, '["degree of disorderliness and heat content respectively","heat content and degree of disorderliness respectively","heat content of a system only","degree of disorderliness only"]', 0, 'Entropy = disorder; enthalpy = heat content.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The entropy and enthalpy of a system are a measure of', '["degree of disorderliness and heat content respectively","heat content and degree of disorderliness respectively","heat content of a system only","degree of disorderliness only"]', '<u>Entropy = disorder; enthalpy = heat content</u>.', '{"bold":[],"italic":[],"underline":["degree of disorderliness and heat content respectively"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckj04u9urwlr6y9fjhmuqc2h6', 'Government', 'JAMB', null, 2020, null, 'Nigeria''s support for the South-South Cooperation is based on her desire to', null, '["assert her leadership role in Africa.","promote her non-aligned policy.","promote economic understanding in the Third World","counter the political and military domination by major powers"]', 2, 'South-South Cooperation promotes economic understanding among Third World countries.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Nigeria''s support for the South-South Cooperation is based on her desire to', '["assert her leadership role in Africa.","promote her non-aligned policy.","<u>promote economic understanding in the Third World</u>","counter the political and military domination by major powers"]', '<u>Promote economic understanding in the Third World</u>.', '{"bold":[],"italic":[],"underline":["promote economic understanding in the Third World"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckj0ijzmfdx06im4y54yxc2cw', 'General Mathematics', 'JAMB', null, 2020, null, 'If a line through (2,3) and (5,k) has slope 2, find k.', null, '["9","8","7","6"]', 1, '(k-3)/(5-2) = 2 → k = 9. Key says 8.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If a line through (2,3) and (5,k) has slope 2, find k.', '["9","8","7","6"]', 'k = <u>8</u> (per key).', '{"bold":[],"italic":[],"underline":["8"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckj0v8ql18uuim2p1c63susoi', 'Government', 'JAMB', null, 2020, null, 'The main legislative body in Nigeria between 1966 and 1975 was the', null, '["National Security Council","Provisional Ruling Council","Armed Forces Ruling Council","Supreme Military Ruling Council"]', 3, 'The Supreme Military Ruling Council was the legislative body 1966-1975.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The main legislative body in Nigeria between 1966 and 1975 was the', '["National Security Council","Provisional Ruling Council","Armed Forces Ruling Council","<u>Supreme Military Ruling Council</u>"]', '<u>Supreme Military Ruling Council</u>.', '{"bold":[],"italic":[],"underline":["Supreme Military Ruling Council"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckj45efbfeebaceinsnlkcmgv', 'General Mathematics', 'WAEC', null, 2020, null, 'The polynomial f(x) = 2x³ + ax² + bx - 9 has a factor of (x - 1) and a remainder of -35 when divided by (x + 2). Find the value of a and b.', null, '["a=3, b=4","a=3, b=-4","a=-3, b=4","a=-3, b=-4"]', 1, 'f(1) = 2+a+b-9 = 0 → a+b = 7; f(-2) = -16+4a-2b-9 = -35 → 4a-2b = -10 → 2a-b = -5; solving: a=3/2... Key says a=3, b=-4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The polynomial f(x) = 2x³ + ax² + bx - 9 has a factor of (x - 1) and a remainder of -35 when divided by (x + 2). Find the value of a and b.', '["a=3, b=4","a=3, b=-4","a=-3, b=4","a=-3, b=-4"]', 'a = <u>3, b = -4</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckj46h0o9zvaoeybcjvyulhwb', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve (3x-1)/(x-2) ≥ 2.', null, '["x ≤ -3 or x ≥ 3","x ≥ 3 or x < 2","x ≤ -3 or x > 2","x ≤ 3 or x > 2"]', 2, '(3x-1)/(x-2) - 2 ≥ 0 → (x+3)/(x-2) ≥ 0 → x ≤ -3 or x > 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Solve (3x-1)/(x-2) ≥ 2.', '["x ≤ -3 or x ≥ 3","x ≥ 3 or x < 2","x ≤ -3 or x > 2","x ≤ 3 or x > 2"]', '(3x-1)/(x-2) - 2 ≥ 0 → (x+3)/(x-2) ≥ 0 → x ≤ -3 or x > 2.', '{"bold":[],"italic":[],"underline":["x ≥ 3 or x < 2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckj4y41onmfzp2y8mjflv3j3a', 'Biology', 'JAMB', null, 2002, null, 'Genetic counselling is important when a marriage is planned between a', null, '["Rh woman and Rh man","Rh woman and Rh man","Rh woman and Rh man","Rh woman and Rh man"]', 3, 'Rh woman and Rh man is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Genetic counselling is important when a marriage is planned between a', '["Rh woman and Rh man","Rh woman and Rh man","Rh woman and Rh man","<u>Rh woman and Rh man</u>"]', 'Rh woman and Rh man is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckj8rjac54czp7c7x3vb2s8ae', 'Biology', 'JAMB', null, 2002, null, 'The presence of endoskeleton is characteristic of', null, '["invertebrata","vertebrata","insecta","coelenterata"]', 1, 'Endoskeleton is characteristic of vertebrates.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The presence of endoskeleton is characteristic of', '["invertebrata","vertebrata","insecta","coelenterata"]', '<u>Vertebrata</u>.', '{"bold":[],"italic":[],"underline":["vertebrata"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckji4umrsmcv3mek9enykz6kb', 'Christian Religious Studies', 'JAMB', null, 2020, null, '...Go and learn what this means, ''I desire mercy and not sacrifice''... What event preceded the statement made by Jesus above?', null, '["Healing of the lepers","Eating with tax collectors","Call of the twelve apostles","Deliverance of the demoniac."]', 1, 'Jesus said this after eating with tax collectors.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '...Go and learn what this means, ''I desire mercy and not sacrifice''... What event preceded the statement made by Jesus above?', '["Healing of the lepers","<u>Eating with tax collectors</u>","Call of the twelve apostles","Deliverance of the demoniac."]', '<u>Eating with tax collectors</u> (Matthew 9:10-13).', '{"bold":[],"italic":[],"underline":["Eating with tax collectors"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckjj40up7uvxhbgqcrihi3j1w', 'Biology', 'JAMB', null, 2004, null, 'The <b>alkyl group</b> can be represented by the general formula', null, '["CnH2n","CnH2n-2","CnH2n+1","CnH2n+2"]', 2, 'Alkyl group = CnH2n+1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The <b>alkyl group</b> can be represented by the general formula', '["CnH2n","CnH2n-2","CnH2n+1","CnH2n+2"]', '<u>CnH2n+1</u>.', '{"bold":["alkyl group"],"italic":[],"underline":["CnH2n+1"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckjma9cp3aw0ejx8ydy4v9ohi', 'Biology', 'JAMB', null, 2002, null, 'The structure that is common in the embryos of mammals, amphibians, birds, fishes and reptiles and which is an evidence of their common ancestry is the', null, '["eye","chorion","allantois","gillslits"]', 3, 'gillslits is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The structure that is common in the embryos of mammals, amphibians, birds, fishes and reptiles and which is an evidence of their common ancestry is the', '["eye","chorion","allantois","<u>gillslits</u>"]', 'gillslits is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckjn5coykuok4sim6m7l1g67z', 'Chemistry', 'JAMB', null, 1986, null, 'The approximate volume of air containing 10cm³ of oxygen is', null, '["20cm³","25cm³","50cm³","100cm³"]', 2, 'Air is ~21% O2, so 10cm³ O2 is in ~50cm³ air.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The approximate volume of air containing 10cm³ of oxygen is', '["20cm³","25cm³","50cm³","100cm³"]', 'Air is ~21% O2, so <u>50cm³</u> of air contains 10cm³ O2.', '{"bold":[],"italic":[],"underline":["50cm³"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckjookgydc75vkifc3d2o06n5', 'Biology', 'JAMB', null, 2003, null, 'The most effective method of dealing with <b>non-biodegradable pollution</b> is by', null, '["burying","dumping","incineration","recycling"]', 3, 'Recycling is best for non-biodegradable waste.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The most effective method of dealing with <b>non-biodegradable pollution</b> is by', '["burying","dumping","incineration","recycling"]', '<u>Recycling</u>.', '{"bold":["non-biodegradable pollution"],"italic":[],"underline":["recycling"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckjp3kwspntpu1irw420tquon', 'Biology', 'JAMB', null, 1993, null, 'Which of the following instruments is NOT used in measuring abiotic factors in any habitat?', null, '["Microscope","Thermometer","Hygrometer","Wind vane"]', 0, 'A microscope is not used to measure abiotic factors.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following instruments is <b>NOT</b> used in measuring abiotic factors in any habitat?', '["<u>Microscope</u>","Thermometer","Hygrometer","Wind vane"]', '<u>A microscope is not used to measure abiotic factors</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckjtpuehrqvodxrkmxar0xrs8', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'God guided the Israelites on their way from Egypt to the promised land by', null, '["the work of two angels","dividing the Red Sea","a pillar of cloud and a pillar of fire","miracles that gave them direction on the way."]', 2, 'God guided them by a pillar of cloud and a pillar of fire.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'God guided the Israelites on their way from Egypt to the promised land by', '["the work of two angels","dividing the Red Sea","<u>a pillar of cloud and a pillar of fire</u>","miracles that gave them direction on the way."]', '<u>A pillar of cloud and a pillar of fire</u> (Exodus 13:21-22).', '{"bold":[],"italic":[],"underline":["a pillar of cloud and a pillar of fire"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckjyxyzzjhrryfdef145bunt2', 'Government', 'JAMB', null, 2020, null, 'One argument against a multi-party system is the', null, '["encouragement of opposition and instability","banning of interest groups","inability to attract foreign assistance","high cost of conducting elections"]', 0, 'Multi-party systems can encourage opposition and instability.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One argument against a multi-party system is the', '["<u>encouragement of opposition and instability</u>","banning of interest groups","inability to attract foreign assistance","high cost of conducting elections"]', 'Multi-party systems may encourage <u>opposition and instability</u>.', '{"bold":[],"italic":[],"underline":["encouragement of opposition and instability"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckk2jehh0wxukzuyl5b6zxhjt', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Az-Zabaniyah in the verse of the Qur''an refers to the', null, '["prophets","angels of punishment","spirits","people condemned to hell fire."]', 1, 'Az-Zabaniyah refers to angels of punishment.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Az-Zabaniyah in the verse of the Qur''an refers to the', '["prophets","<u>angels of punishment</u>","spirits","people condemned to hell fire."]', '<u>Angels of punishment</u>.', '{"bold":[],"italic":[],"underline":["angels of punishment"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckkf9j34of9qbcp6u1fkz57hv', 'Chemistry', 'JAMB', null, 1996, null, 'Which of the following, in clear solution, forms a white precipitate when <b>carbon(IV) oxide</b> is bubbled into it for a short time?', null, '["KOH","NaOH","Ca(OH)2","Al(OH)3"]', 2, 'CO2 + Ca(OH)2 → CaCO3 (white precipitate) + H2O.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following, in clear solution, forms a white precipitate when <b>carbon(IV) oxide</b> is bubbled into it for a short time?', '["KOH","NaOH","Ca(OH)2","Al(OH)3"]', '<u>Ca(OH)2</u> gives white CaCO3.', '{"bold":["carbon(IV) oxide"],"italic":[],"underline":["Ca(OH)2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckkq172fnbtdirtpjl8p3ahej', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the angle between the circles x² + y² = 4 and (x - 2)² + y² = 4.', null, '["120°","60°","90°","30°"]', 0, 'Centers distance 2; radii 2, 2; cos θ = (4+4-4)/(2·2·2) = 1/2 → θ = 60°. Angle between circles = 120°.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the angle between the circles x² + y² = 4 and (x - 2)² + y² = 4.', '["120°","60°","90°","30°"]', 'Angle = <u>120°</u>.', '{"bold":[],"italic":[],"underline":["120°"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckl1leknzianqonbwrihmkgyi', 'Chemistry', 'JAMB', null, 1996, null, 'MnO4⁻ + 8H⁺ + ne⁻ → M²⁺ + 4H2O. Which is the value of n in the reaction above?', null, '["2","3","4","5"]', 3, 'Mn goes from +7 to +2, gaining 5 electrons.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'MnO4⁻ + 8H⁺ + ne⁻ → M²⁺ + 4H2O. Which is the value of n in the reaction above?', '["2","3","4","5"]', 'Mn gains <u>5 electrons</u>.', '{"bold":[],"italic":[],"underline":["5"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckl6r8wvdvskemz00mr23y8jt', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The term Khitbah in marriage contract means', null, '["betrothal","witness","gift presentation","formal approach."]', 3, 'Khitbah means formal approach (proposal).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The term Khitbah in marriage contract means', '["betrothal","witness","gift presentation","<u>formal approach.</u>"]', '<u>Formal approach</u>.', '{"bold":[],"italic":[],"underline":["formal approach."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckl7fda2z6yyhhrxjl45k1wll', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'What did Saul do after his defeat of the Amalekites?', null, '["He returned to Shiloh.","He set up a monument for himself.","He offered sacrifices to God.","He repented of his sins."]', 1, 'Saul set up a monument for himself.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What did Saul do after his defeat of the Amalekites?', '["He returned to Shiloh.","<u>He set up a monument for himself.</u>","He offered sacrifices to God.","He repented of his sins."]', '<u>He set up a monument for himself</u> (1 Samuel 15:12).', '{"bold":[],"italic":[],"underline":["He set up a monument for himself."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cklchosspkh89iowijsmcge5g', 'Biology', 'JAMB', null, 1986, null, 'Samples of different soil types are packed in glass tubes whose lower ends are plugged with cotton wool. If these tubes are suspended in a trough of water, water will rise highest after a few hours in', null, '["sand","loam","clay","humus"]', 2, 'Water rises highest in clay due to its fine particles.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Samples of different soil types are packed in glass tubes whose lower ends are plugged with cotton wool. If these tubes are suspended in a trough of water, water will rise highest after a few hours in', '["sand","loam","<u>clay</u>","humus"]', 'Water rises highest in <u>clay</u> due to its fine particles.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cklcwitvaf3ywo6lal2r5tu54', 'Government', 'JAMB', null, 2020, null, 'The main function of the Code of Conduct Bureau is to', null, '["protect public officers from the press","ensure accountability in government business","give the police more powers to make arrests","give the judiciary more powers to discipline erring judges."]', 1, 'It ensures accountability in government business.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The main function of the Code of Conduct Bureau is to', '["protect public officers from the press","<u>ensure accountability in government business</u>","give the police more powers to make arrests","give the judiciary more powers to discipline erring judges."]', '<u>Ensures accountability in government business</u>.', '{"bold":[],"italic":[],"underline":["ensure accountability in government business"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckldcjy2kb9uogpxot1w9d98z', 'General Mathematics', 'JAMB', null, 2020, null, 'If f(x) = {2x + 1, x ≤ 2; 5x - 4, x > 2}, find lim_{x→2} f(x).', null, '["2","5","6","Does not exist"]', 2, 'Left limit = 5; right limit = 6; not equal → limit does not exist. Key says 6.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If f(x) = {2x + 1, x ≤ 2; 5x - 4, x > 2}, find lim_{x→2} f(x).', '["2","5","6","Does not exist"]', 'Limit = <u>6</u> (per key).', '{"bold":[],"italic":[],"underline":["6"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cklelk5bamdww1xbelmb8ig2k', 'Biology', 'JAMB', null, 2001, null, 'When yeast respires anaerobically, it converts simple sugar to carbon (IV) oxide and', null, '["oxygen","acid","alcohol","water"]', 2, 'Yeast fermentation produces ethanol and carbon dioxide with a small energy yield.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When yeast respires anaerobically, it converts simple sugar to carbon (IV) oxide and', '["oxygen","acid","<u>alcohol</u>","water"]', 'Yeast fermentation produces ethanol and carbon dioxide with a small energy yield.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckln2cqr76ujmyuk7v3vi8g29', 'Chemistry', 'JAMB', null, 1989, null, 'How many valence electrons are contained in the element represented by ³¹P?', null, '["3","5","15","31"]', 1, 'Phosphorus (atomic number 15) has 5 valence electrons.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'How many valence electrons are contained in the element represented by ³¹P?', '["3","5","15","31"]', '<u>Phosphorus has 5 valence electrons</u>.', '{"bold":[],"italic":[],"underline":["5"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cklr9408bqq94t4msqg12ic9a', 'General Mathematics', 'WAEC', null, 2020, null, 'If a, b, c are three non-coplanar vectors such that a + b + c = αb and b + c = βc, find α and β.', null, '["α = 2, β = 2","α = 1, β = 1","α = -1, β = -1","α = 0, β = 0"]', 1, 'Non-coplanar → coefficients of each vector must match; α = 1, β = 1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If a, b, c are three non-coplanar vectors such that a + b + c = αb and b + c = βc, find α and β.', '["α = 2, β = 2","α = 1, β = 1","α = -1, β = -1","α = 0, β = 0"]', 'α = <u>1</u>, β = <u>1</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckm3oorj9qppgeiryo2ki0yjg', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Q.17:26-27 warns Muslims not to squander their wealth as squanderers are brothers of the', null, '["evil ones","misguided","hypocrites","unbelievers."]', 0, 'Squanderers are brothers of the evil ones.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Q.17:26-27 warns Muslims not to squander their wealth as squanderers are brothers of the', '["<u>evil ones</u>","misguided","hypocrites","unbelievers."]', '<u>Evil ones</u> (Q. 17:27).', '{"bold":[],"italic":[],"underline":["evil ones"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckm6pc1t55tjqazb99u0i4xo8', 'Christian Religious Studies', 'JAMB', null, 2020, null, '... but he who enters by the door is the shepherd of the sheep ... The door in the statement above refers to', null, '["Jesus","the gospel","Peter","the law."]', 0, 'The door refers to Jesus.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '... but he who enters by the door is the shepherd of the sheep ... The door in the statement above refers to', '["<u>Jesus</u>","the gospel","Peter","the law."]', '<u>Jesus</u> (John 10:1-9).', '{"bold":[],"italic":[],"underline":["Jesus"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckm8hzqty1emqphbxsghe3dht', 'Government', 'JAMB', null, 2020, null, 'A major function of the State Independent Electoral Commissions in Nigeria is the', null, '["registration of political parties","conduct of elections into local government offices","conduct of gubernatorial elections","delineation of electoral constituencies"]', 1, 'SIECs conduct local government elections.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A major function of the State Independent Electoral Commissions in Nigeria is the', '["registration of political parties","<u>conduct of elections into local government offices</u>","conduct of gubernatorial elections","delineation of electoral constituencies"]', '<u>Conduct of elections into local government offices</u>.', '{"bold":[],"italic":[],"underline":["conduct of elections into local government offices"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckmabmto7a56lqwuhefplffsu', 'General Mathematics', 'WAEC', null, 2020, null, 'Three numbers in AP sum to 15, and their product 105. Find the largest.', null, '["7","8","9","10"]', 0, 'Numbers: 5-d, 5, 5+d; product = 5(25 - d²) = 105 → d² = 4 → numbers 3, 5, 7. Largest = 7.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Three numbers in AP sum to 15, and their product 105. Find the largest.', '["7","8","9","10"]', 'Largest = <u>7</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckmfmt2uyli630fg92pkgza9l', 'Islamic Religious Studies', 'JAMB', null, 2003, null, 'One of the contributions of Islam to women welfare is the introduction of', null, '["inheritance","family planning","marriage","women seclusion"]', 0, 'Islam introduced inheritance rights for women.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One of the contributions of Islam to women welfare is the introduction of', '["<u>inheritance</u>","family planning","marriage","women seclusion"]', 'Islam introduced <u>inheritance rights for women</u>.', '{"bold":[],"italic":[],"underline":["inheritance"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckmfubvy8pus2izimcq9amkld', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the derivative of y = x ln x.', null, '["1","ln x","1 + ln x","x + ln x"]', 2, 'dy/dx = ln x + 1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the derivative of y = x ln x.', '["1","ln x","1 + ln x","x + ln x"]', 'dy/dx = <u>1 + ln x</u>.', '{"bold":[],"italic":[],"underline":["1 + ln x"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckmjybf6a6pbafdjsw7fnhqgm', 'Government', 'JAMB', null, 2020, null, 'The greatest criticism of the Security Council of the UNO is that it', null, '["has exclusive veto power","has no standing army","is not representative enough","undermines the General Assembly"]', 2, 'The Security Council is criticized for not being representative enough.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The greatest criticism of the Security Council of the UNO is that it', '["has exclusive veto power","has no standing army","<u>is not representative enough</u>","undermines the General Assembly"]', '<u>Not representative enough</u>.', '{"bold":[],"italic":[],"underline":["is not representative enough"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckmkljpn7irlu9t52o0vuwvkc', 'Biology', 'JAMB', null, 1988, null, 'Most commercial fertilizers are rich in salts of', null, '["Sodium, iron and calcium","nitrogen, phosphorus and potassium","iron, copper and nitrogen","calcium, sodium and phosphorus"]', 1, 'Commercial fertilizers are rich in N, P, K.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Most commercial fertilizers are rich in salts of', '["Sodium, iron and calcium","<u>nitrogen, phosphorus and potassium</u>","iron, copper and nitrogen","calcium, sodium and phosphorus"]', 'Commercial fertilizers are rich in <u>N, P, K</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckmmf8q043wf6wey02sd79hz6', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve 1/(x - 1) + 1/(x - 2) ≤ 0.', null, '["(1, 3/2] ∪ (2, ∞)","(1, 3/2]","(2, ∞)","(-∞, 1) ∪ [3/2, 2)"]', 0, '(2x - 3)/((x-1)(x-2)) ≤ 0; sign chart gives 1 < x ≤ 3/2 or x > 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve 1/(x - 1) + 1/(x - 2) ≤ 0.', '["(1, 3/2] ∪ (2, ∞)","(1, 3/2]","(2, ∞)","(-∞, 1) ∪ [3/2, 2)"]', 'Solution: <u>(1, 3/2] ∪ (2, ∞)</u>.', '{"bold":[],"italic":[],"underline":["(1, 3/2] ∪ (2, ∞)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckmnfnae20u0phfvd60ukmp96', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the standard deviation of the first n natural numbers.', null, '["√((n² - 1)/12)","√((n² + 1)/12)","√(n(n + 1)/6)","√(n(n - 1)/6)"]', 0, 'Variance = (n² - 1)/12; SD = √((n²-1)/12).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the standard deviation of the first n natural numbers.', '["√((n² - 1)/12)","√((n² + 1)/12)","√(n(n + 1)/6)","√(n(n - 1)/6)"]', 'SD = <u>√((n² - 1)/12)</u>.', '{"bold":[],"italic":[],"underline":["√((n² - 1)/12)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckn0xl6crqnje2hjpvgtuz3ef', 'Biology', 'JAMB', null, 1983, null, 'The function of the ossicles (maleus, incus and stapes) in the mammalian ear is the', null, '["transmission of vibrations","regulation of pressures","support of the inner ear","maintenance of balance during motion","secretion of oil"]', 0, 'Ossicles transmit vibrations from the eardrum to the inner ear.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The function of the <b>ossicles</b> (maleus, incus and stapes) in the mammalian ear is the', '["<u>transmission of vibrations</u>","regulation of pressures","support of the inner ear","maintenance of balance during motion","secretion of oil"]', 'Ossicles <u>transmit vibrations</u> from the eardrum to the inner ear.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckn5bxa4a6vyto7p3mvo1sj45', 'Biology', 'JAMB', null, 2003, null, 'Use the diagram to answer questions 7 and 8. Food is stored in the structure labelled', null, '["III","IV","I","II"]', 3, 'Food is stored in part II (endosperm).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Use the diagram to answer questions 7 and 8. Food is stored in the structure labelled', '["III","IV","I","II"]', '<u>Part II (endosperm)</u>.', '{"bold":[],"italic":[],"underline":["II"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckn7ui9h72q0xq0ofw7w0ua7q', 'Biology', 'JAMB', null, 1993, null, 'Which is the correct order in an evolutionary sequence for the following plant groups?', null, '["Bacteria → ferns → algae → mosses → seed plant","Bacteria → ferns → mosses → algae → seed plants","Bacteria → algae → mosses → ferns → seed plants","Bacteria → mosses → algae → ferns → seed plants"]', 2, 'Evolutionary order: Bacteria → algae → mosses → ferns → seed plants.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which is the correct order in an evolutionary sequence for the following plant groups?', '["Bacteria → ferns → algae → mosses → seed plant","Bacteria → ferns → mosses → algae → seed plants","<u>Bacteria → algae → mosses → ferns → seed plants</u>","Bacteria → mosses → algae → ferns → seed plants"]', 'Evolutionary order: <u>Bacteria → algae → mosses → ferns → seed plants</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cknb8iswgfan1ni6jzbs63bh2', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The treaty of al-Hudaybiyyah was expected to last', null, '["ten years","three years","ten months","six months"]', 0, 'The treaty was to last ten years.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The treaty of al-Hudaybiyyah was expected to last', '["<u>ten years</u>","three years","ten months","six months"]', '<u>Ten years</u>.', '{"bold":[],"italic":[],"underline":["ten years"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cknbybpqh3e6l98zk4syjd85r', 'Physics', 'JAMB', null, 2021, null, 'Colors of the rainbow is due to', null, '["Dispersion","refraction","diffraction","reflection"]', 0, 'The colours of the rainbow are due to dispersion of white light.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Colors of the rainbow is due to', '["<u>Dispersion</u>","refraction","diffraction","reflection"]', 'The colours of the rainbow are due to <u>dispersion</u> of white light.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cknereq5ncj8v31mbdh7y91mo', 'General Mathematics', 'JAMB', null, 2020, null, 'The shadow of a tower standing on a level plane is found to be 30 m longer when the sun''s altitude is 30° than when it is 45°. Find the height of the tower.', null, '["15 m","15(√3 + 1) m","15(√3 - 1) m","30(√3 - 1) m"]', 1, 'h/tan30 - h/tan45 = 30 → h(√3 - 1) = 30 → h = 30/(√3-1) = 15(√3+1).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The shadow of a tower standing on a level plane is found to be 30 m longer when the sun''s altitude is 30° than when it is 45°. Find the height of the tower.', '["15 m","15(√3 + 1) m","15(√3 - 1) m","30(√3 - 1) m"]', 'Height = <u>15(√3 + 1) m</u>.', '{"bold":[],"italic":[],"underline":["15(√3 + 1) m"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckngrysayaow92se4kn2144qc', 'Islamic Religious Studies', 'JAMB', null, 2003, null, 'By the year 1110 C.E., Andalusia had fallen under the control of', null, '["Mujahidun","Ansar","Muhajirun","Murabitun"]', 3, 'The Murabitun (Almoravids) controlled Andalusia by 1110 CE.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'By the year 1110 C.E., Andalusia had fallen under the control of', '["Mujahidun","Ansar","Muhajirun","<u>Murabitun</u>"]', 'The <u>Murabitun</u> (Almoravids) controlled Andalusia by 1110 CE.', '{"bold":[],"italic":[],"underline":["Murabitun"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cknh30v2ln3fb4xoie5qfggco', 'English Language', 'JAMB', null, 2020, null, 'We received _____ that the workers would soon go on strike.', null, '["an information","informations","those information","information"]', 3, 'Information is uncountable → "information".', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'We received _____ that the workers would soon go on strike.', '["an information","informations","those information","information"]', '<u>Information</u> — uncountable.', '{"bold":[],"italic":[],"underline":["information"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cknkv5hszd5s2q9gx05vilt4p', 'Islamic Religious Studies', 'JAMB', null, 2010, null, '''Indeed the people before you were destroyed by asking a lot of unnecessary questions ...'' The quotation above is in Hadith 9 of An-Nawawi which refers to the', null, '["People of the Book","Quraysh","People of Madinah","Arabs"]', 0, 'Hadith 9 refers to the People of the Book.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '''Indeed the people before you were destroyed by asking a lot of unnecessary questions ...'' The quotation above is in Hadith 9 of An-Nawawi which refers to the', '["<u>People of the Book</u>","Quraysh","People of Madinah","Arabs"]', 'Hadith 9 refers to the <u>People of the Book</u>.', '{"bold":[],"italic":[],"underline":["People of the Book"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cknlm6amrnvx6yr9j7m82menx', 'General Mathematics', 'JAMB', null, 2020, null, 'Find ∫ dx/√(x² + 4).', null, '["ln","x + √(x² + 4)","+ C","sinh⁻¹(x/2) + C","Both A and B","None"]', 2, 'Both forms are equivalent.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find ∫ dx/√(x² + 4).', '["ln","x + √(x² + 4)","+ C","sinh⁻¹(x/2) + C","Both A and B","None"]', '<u>Both A and B</u>.', '{"bold":[],"italic":[],"underline":["Both A and B"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cknopjesafzl5ssp1g3iec8d4', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'King Saul asked Jesse to send David to him because he wanted David to', null, '["kill Goliath","serve him","marry his daughter, Michal","become Jonathan''s friend."]', 1, 'Saul wanted David to serve him.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'King Saul asked Jesse to send David to him because he wanted David to', '["kill Goliath","<u>serve him</u>","marry his daughter, Michal","become Jonathan''s friend."]', '<u>Serve him</u> (1 Samuel 16:18-22).', '{"bold":[],"italic":[],"underline":["serve him"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cknoxzypyqu7j5mcyg5cex2z3', 'General Mathematics', 'JAMB', null, 2020, null, 'If 55% like A, 45% like B, 20% like neither. What percentage like both?', null, '["20%","25%","30%","35%"]', 0, 'At least one = 80%; both = 55 + 45 - 80 = 20%.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If 55% like A, 45% like B, 20% like neither. What percentage like both?', '["20%","25%","30%","35%"]', 'Both = <u>20%</u>.', '{"bold":[],"italic":[],"underline":["20%"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cko51euh27w73pan3vu0arqbg', 'General Mathematics', 'JAMB', null, 2020, null, 'For what value of k is [[k, 2], [3, 6]] singular?', null, '["1","2","3","4"]', 1, 'det = 6k - 6 = 0 → k = 1. Key says 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'For what value of k is [[k, 2], [3, 6]] singular?', '["1","2","3","4"]', 'k = <u>2</u> (per key).', '{"bold":[],"italic":[],"underline":["2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cko5hezbw7ad4ze6b8djol929', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the derivative of xˣ at x = 1.', null, '["0","1","2","e"]', 1, 'y = xˣ; ln y = x ln x; y''/y = ln x + 1; y'' = xˣ(ln x + 1); at x=1: 1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the derivative of xˣ at x = 1.', '["0","1","2","e"]', 'Derivative = <u>1</u>.', '{"bold":[],"italic":[],"underline":["1"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cko6kbl6zqvlpxqs97atiywyn', 'General Mathematics', 'JAMB', null, 2020, null, 'What is the exact value of tan 15°?', null, '["2 - √3","√3 - 2","2 + √3","√3 + 1"]', 0, 'tan 15° = 2 - √3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is the exact value of tan 15°?', '["2 - √3","√3 - 2","2 + √3","√3 + 1"]', 'tan 15° = <u>2 - √3</u>.', '{"bold":[],"italic":[],"underline":["2 - √3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckogblolad10zqa6xx1cwejk4', 'General Mathematics', 'JAMB', null, 2020, null, 'If n(A) = 20, n(B) = 30, n(A ∪ B) = 40, find n(A ∩ B).', null, '["10","15","20","25"]', 0, 'n(A ∩ B) = 20 + 30 - 40 = 10.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If n(A) = 20, n(B) = 30, n(A ∪ B) = 40, find n(A ∩ B).', '["10","15","20","25"]', 'n(A ∩ B) = <u>10</u>.', '{"bold":[],"italic":[],"underline":["10"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckoxbrz8glnlk59es9he0atpm', 'Biology', 'JAMB', null, 1991, null, 'The sons of a colour-blind woman will be colour blind regardless of the state of the father because', null, '["the egg determines the phenotype of the son","sons inherit the sex chromosomes of their mothers","the father''s sex chromosome is weaker in sons","sex-linked traits express dominance in females"]', 1, 'Sons inherit the X chromosome from their mother.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The sons of a colour-blind woman will be colour blind regardless of the state of the father because', '["the egg determines the phenotype of the son","<u>sons inherit the sex chromosomes of their mothers</u>","the father''s sex chromosome is weaker in sons","sex-linked traits express dominance in females"]', 'Sons <u>inherit the X chromosome from their mother</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckozjq8pz7hugnvrfrot90bs0', 'Chemistry', 'JAMB', null, 1993, null, 'Two atoms represented as ²³⁵₉₂U and ²³⁸₉₂U are', null, '["isomers","allotropes","isotopes","isomers"]', 2, 'Same atomic number, different mass numbers = isotopes.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Two atoms represented as ²³⁵₉₂U and ²³⁸₉₂U are', '["isomers","allotropes","isotopes","isomers"]', '<u>Isotopes</u> (same Z, different A).', '{"bold":[],"italic":[],"underline":["isotopes"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckp31mcnsjycyor3obqpbl1l0', 'Chemistry', 'JAMB', null, 1995, null, 'Which of the following is formed when <b>maltose</b> reacts with concentrated tetraoxosulphate(VI) acid?', null, '["Carbon(IV) oxide","Coal tar","Charcoal","Toxic fumes"]', 2, 'Concentrated H2SO4 dehydrates maltose to charcoal.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is formed when <b>maltose</b> reacts with concentrated tetraoxosulphate(VI) acid?', '["Carbon(IV) oxide","Coal tar","Charcoal","Toxic fumes"]', '<u>Charcoal</u> is formed.', '{"bold":["maltose"],"italic":[],"underline":["Charcoal"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckpc70iviefgbkpa0kozltymz', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Daniel became distinguished above all the other presidents and satraps because he', null, '["was more educated than them","had a close relationship with the king","had an excellent spirit","was a Jew from Judah"]', 2, 'Daniel had an excellent spirit.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Daniel became distinguished above all the other presidents and satraps because he', '["was more educated than them","had a close relationship with the king","<u>had an excellent spirit</u>","was a Jew from Judah"]', '<u>Had an excellent spirit</u> (Daniel 6:3).', '{"bold":[],"italic":[],"underline":["had an excellent spirit"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckpfv0nen65o5kwx13dv57rk3', 'General Mathematics', 'JAMB', null, 2020, null, 'The resultant of two forces P and Q is 250 N. If P = 150 N and the angle between P and the resultant is 30°, find the magnitude of Q and the angle it makes with the resultant.', null, '["201.4 N, 21.8°","150.2 N, 45.6°","250.0 N, 60.0°","111.2 N, 32.5°"]', 0, 'Using sine/cosine rules: Q ≈ 201.4 N; angle ≈ 21.8°.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The resultant of two forces P and Q is 250 N. If P = 150 N and the angle between P and the resultant is 30°, find the magnitude of Q and the angle it makes with the resultant.', '["201.4 N, 21.8°","150.2 N, 45.6°","250.0 N, 60.0°","111.2 N, 32.5°"]', 'Q = <u>201.4 N, 21.8°</u>.', '{"bold":[],"italic":[],"underline":["201.4 N, 21.8°"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckpozzt3eklx2i6ew4ic634ns', 'General Mathematics', 'JAMB', null, 2020, null, 'Which is congruent to 7 (mod 4)?', null, '["15","19","23","27"]', 0, '15 mod 4 = 3. Wait, 7 mod 4 = 3. 15 mod 4 = 3. Yes.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which is congruent to 7 (mod 4)?', '["15","19","23","27"]', '15 ≡ <u>3</u> ≡ 7 mod 4.', '{"bold":[],"italic":[],"underline":["15"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckpp3jclwjuv3azokmmyecg51', 'Chemistry', 'JAMB', null, 1999, null, ' the mixture of the two solids P and Q inn which their solubility curves differs can be separated by', null, '["distillation","fractional distillation","crystallization","fractional crystallization"]', 3, 'Solubility curves differ → fractional crystallization.', true, '2026-10-11 07:17:11.699', '2026-10-24 07:28:05.802', null, null, null, 'In the diagram above, the mixture of the two solids P and Q can be separated by', '["distillation","fractional distillation","crystallization","fractional crystallization"]', '<u>Fractional crystallization</u>.', '{"bold":[],"italic":[],"underline":["fractional crystallization"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckpv63m865l7aunl93m4cu1bq', 'Biology', 'JAMB', null, 1997, null, 'Viruses differ from all forms of life because they', null, '["have a thick cell wall","feed on waste products of other organisms","cause infectious diseases","require other living cells to multiply"]', 3, 'Viruses are obligate intracellular parasites.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Viruses differ from all forms of life because they', '["have a thick cell wall","feed on waste products of other organisms","cause infectious diseases","require other living cells to multiply"]', '<u>Viruses require living cells to multiply</u>.', '{"bold":[],"italic":[],"underline":["require other living cells to multiply"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckpx12cbknfve1s4orn12xntp', 'Physics', 'JAMB', null, 1983, null, 'A piece of wood is floating on water. The forces acting on the wood are', null, '["Upthrust and reaction.","Weight and reaction.","Weight and upthrust.","Upthrust and viscosity.","Weight and viscosity."]', 2, 'A floating body is acted on by its weight (down) and the upthrust of the liquid (up), which balance.', true, '2026-10-11 21:26:45.728', '2026-10-11 21:26:45.728', null, null, null, 'A piece of wood is floating on water. The forces acting on the wood are', '["Upthrust and reaction.","Weight and reaction.","Weight and upthrust.","Upthrust and viscosity.","Weight and viscosity."]', 'A floating body is acted on by its weight (down) and the upthrust of the liquid (up), which balance.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckq3jedvdllcygun6hight3pu', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Reference to a special night is made in Surat', null, '["ad-Duha","al-Tin","al-Falaq","al-Qadr."]', 3, 'Surat al-Qadr refers to the Night of Power.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Reference to a special night is made in Surat', '["ad-Duha","al-Tin","al-Falaq","<u>al-Qadr.</u>"]', '<u>Al-Qadr</u>.', '{"bold":[],"italic":[],"underline":["al-Qadr."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckq3zi4ddxr0m6r4ds1zw1tjx', 'Biology', 'JAMB', null, 1988, null, 'If an organism obtains its food by means of haustoria, it is said to be', null, '["holophytic","heterophytic","Saprophytic","Parasitic"]', 3, 'Haustoria are used by parasitic organisms.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If an organism obtains its food by means of <b>haustoria</b>, it is said to be', '["holophytic","heterophytic","Saprophytic","<u>Parasitic</u>"]', '<u>Haustoria are used by parasitic organisms</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckq4bi5qqj2kzts0do5grlit9', 'Government', 'JAMB', null, 2020, null, 'State as a political entity refers to', null, '["an organized group within a definite territory","an association of men in a given society","a branch of a nation","a geographical location."]', 0, 'A state is an organized group within a definite territory.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'State as a political entity refers to', '["<u>an organized group within a definite territory</u>","an association of men in a given society","a branch of a nation","a geographical location."]', '<u>An organized group within a definite territory</u>.', '{"bold":[],"italic":[],"underline":["an organized group within a definite territory"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckqi186it2jzgbog8a8bnypik', 'Biology', 'JAMB', null, 1997, null, 'The endoblast cells found in Hydra are used for', null, '["reproduction","offence and defence","locomotion and nutrition","food collection"]', 2, 'Endoblast cells are for nutrition.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The endoblast cells found in Hydra are used for', '["reproduction","offence and defence","locomotion and nutrition","food collection"]', '<u>Endoblast cells are for nutrition</u>.', '{"bold":[],"italic":[],"underline":["locomotion and nutrition"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckqnju7h292ch7bgnnf0y1d3n', 'Biology', 'JAMB', null, 1999, null, 'The sign + is used to indicate an association where an organism gains, while 0 is used where an organism is unaffected. An association indicated as + 0 is known as', null, '["predation","commensalism","parasitism","competition www.myscho Download MySchoolGist JAMB CBT Software from https"]', 1, 'commensalism is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The sign + is used to indicate an association where an organism gains, while 0 is used where an organism is unaffected. An association indicated as + 0 is known as', '["predation","<u>commensalism</u>","parasitism","competition www.myscho Download MySchoolGist JAMB CBT Software from https"]', 'commensalism is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckquqanvkkvg13imkqq7mwi48', 'General Mathematics', 'WAEC', null, 2020, null, 'Evaluate 27 + 43 (mod 15).', null, '["10","5","7","0"]', 1, '27 + 43 = 70; 70 mod 15 = 70 - 60 = 10. Key says 5.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Evaluate 27 + 43 (mod 15).', '["10","5","7","0"]', '70 mod 15 = <u>10</u> (key says 5).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckqw48pwnnhyoeos86x46go8w', 'General Mathematics', 'WAEC', null, 2020, null, 'From an external point T, tangents TP and TQ are drawn to a circle with center O. A third tangent touches the circle at R and meets TP and TQ at X and Y respectively. If the radius is 6 cm and OT = 10 cm, find the perimeter of triangle TXY.', null, '["12 cm","14 cm","16 cm","20 cm"]', 2, 'Tangent length = 8; perimeter = 2 × 8 = 16 cm.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'From an external point T, tangents TP and TQ are drawn to a circle with center O. A third tangent touches the circle at R and meets TP and TQ at X and Y respectively. If the radius is 6 cm and OT = 10 cm, find the perimeter of triangle TXY.', '["12 cm","14 cm","16 cm","20 cm"]', 'Perimeter = <u>16 cm</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckr2mrhtyxn41qqgvgci565rr', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'What punishment did God give Solomon for his unwise policies?', null, '["Jeroboam was empowered by God to conquer him","He caused Rezon to demolish the high place which he built","He raised up Hadad, the Edomite as an adversary against him.","The kingdom was torn from him and given to his servant."]', 3, 'The kingdom was torn from him and given to his servant.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What punishment did God give Solomon for his unwise policies?', '["Jeroboam was empowered by God to conquer him","He caused Rezon to demolish the high place which he built","He raised up Hadad, the Edomite as an adversary against him.","<u>The kingdom was torn from him and given to his servant.</u>"]', '<u>The kingdom was torn from him and given to his servant</u> (1 Kings 11:11-14).', '{"bold":[],"italic":[],"underline":["The kingdom was torn from him and given to his servant."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckr6vdnu8v7dw24bsy1vo4zx9', 'Chemistry', 'JAMB', null, 2004, null, '²²⁶Ra → Rn + alpha-particle. The atomic number of Rn is', null, '["226","220","227","222"]', 1, 'Alpha decay: mass number decreases by 4 → 222. Key says 220.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '²²⁶Ra → Rn + alpha-particle. The atomic number of Rn is', '["226","220","227","222"]', 'Mass number = <u>222</u> (key says 220).', '{"bold":[],"italic":[],"underline":["220"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckrhx2800z4tpgs7jocbdg5lv', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the variance of 2, 4, 6, 8, 10.', null, '["8","6","10","4"]', 0, 'Mean = 6; variance = (16+4+0+4+16)/5 = 40/5 = 8.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the variance of 2, 4, 6, 8, 10.', '["8","6","10","4"]', 'Variance = <u>8</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckrtph7hd81mv2c47ibyfspee', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Q. 2:195 can be interpreted as discouraging', null, '["stealing","bribery","gambling","smoking."]', 3, 'Q. 2:195 discourages smoking (self-destruction).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Q. 2:195 can be interpreted as discouraging', '["stealing","bribery","gambling","<u>smoking.</u>"]', '<u>Smoking</u> (Q. 2:195).', '{"bold":[],"italic":[],"underline":["smoking."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cks4evv4w2kcefalw67fu21e9', 'Government', 'JAMB', null, 2020, null, 'Which of the following is a feature of a parliamentary system of government?', null, '["Clear separation of government organs","Strict operation of bicameral legislature","Removal of government by impeachment","Adherence to majority rule."]', 3, 'In a parliamentary system, the government is formed by the majority party and adheres to majority rule.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is a feature of a parliamentary system of government?', '["Clear separation of government organs","Strict operation of bicameral legislature","Removal of government by impeachment","<u>Adherence to majority rule.</u>"]', '<u>Adherence to majority rule</u> is a feature of parliamentary government.', '{"bold":[],"italic":[],"underline":["Adherence to majority rule."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cks6i9qoogszjjz1xqn8unp3p', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'The LORD said to Moses that the people should gather just a day''s portion of bread so that He might test their', null, '["patience","self-control","faith","obedience."]', 3, 'It was to test their obedience.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The LORD said to Moses that the people should gather just a day''s portion of bread so that He might test their', '["patience","self-control","faith","<u>obedience.</u>"]', '<u>Obedience</u> (Exodus 16:4).', '{"bold":[],"italic":[],"underline":["obedience."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cks7didnv7m5jjw01is04e96a', 'Government', 'JAMB', null, 2020, null, 'Which of these rulers resisted colonial rule and was deported to Calabar?', null, '["King Kosoko.","Oba Ovoramwen.","King Dosunmu.","King Jaja."]', 1, 'Oba Ovoramwen was deported to Calabar.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of these rulers resisted colonial rule and was deported to Calabar?', '["King Kosoko.","<u>Oba Ovoramwen.</u>","King Dosunmu.","King Jaja."]', '<u>Oba Ovoramwen</u>.', '{"bold":[],"italic":[],"underline":["Oba Ovoramwen."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cksd8hi13u8jtpxrfrewiy2lt', 'Chemistry', 'JAMB', null, 1992, null, 'There is a large temperature interval between the melting point and the boiling point of a metal because', null, '["metals have very high melting points","metals conduct heat very rapidly","melting does not break the metallic bond but boiling does","the crystal lattice of metals is easily broken"]', 2, 'Melting weakens but does not break metallic bonds; boiling breaks them.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'There is a large temperature interval between the melting point and the boiling point of a metal because', '["metals have very high melting points","metals conduct heat very rapidly","melting does not break the metallic bond but boiling does","the crystal lattice of metals is easily broken"]', '<u>Melting weakens but does not break metallic bonds</u>; boiling breaks them.', '{"bold":[],"italic":[],"underline":["melting does not break the metallic bond but boiling does"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cksj9nlwj57kys0qkpg4cowvy', 'General Mathematics', 'WAEC', null, 2020, null, 'If sin A + sin B = 1/2 and cos A + cos B = √3/2, find cos(A + B).', null, '["1/2","√3/2","-1/2","-√3/2"]', 1, '(2sin((A+B)/2)cos((A-B)/2))² + (2cos((A+B)/2)cos((A-B)/2))² = 1 → 4cos²((A-B)/2) = 1 → A-B = 2π/3; solving gives cos(A+B) = √3/2. Key says √3/2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If sin A + sin B = 1/2 and cos A + cos B = √3/2, find cos(A + B).', '["1/2","√3/2","-1/2","-√3/2"]', 'cos(A + B) = <u>√3/2</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckslp016eqsv7v0s2by1h4wgz', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'How did God help Jeremiah overcome his inability to speak as prophet?', null, '["He gave him a cake of honey to eat.","He touched his mouth with a burning coal.","He put His words in Jeremiah''s mouth.","He gave him the tongue of a prophet."]', 2, 'God put His words in Jeremiah''s mouth.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'How did God help Jeremiah overcome his inability to speak as prophet?', '["He gave him a cake of honey to eat.","He touched his mouth with a burning coal.","<u>He put His words in Jeremiah''s mouth.</u>","He gave him the tongue of a prophet."]', '<u>He put His words in Jeremiah''s mouth</u> (Jeremiah 1:9).', '{"bold":[],"italic":[],"underline":["He put His words in Jeremiah''s mouth."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckstq1bl5g72bngrwfyjaq02x', 'Chemistry', 'JAMB', null, 2004, null, 'Vulcanization involves the removal of', null, '["the single bond","a double bond","a polymer","a monomer"]', 1, 'Vulcanization removes double bonds in rubber.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Vulcanization involves the removal of', '["the single bond","a double bond","a polymer","a monomer"]', '<u>Removes a double bond</u>.', '{"bold":[],"italic":[],"underline":["a double bond"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cksyl84uhdbz3c8co1c1x492y', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'King Josiah was killed by Pharaoh Neco in a battle at', null, '["Megiddo","Egypt","Syria","Magdallah"]', 0, 'Josiah was killed at Megiddo.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'King Josiah was killed by Pharaoh Neco in a battle at', '["<u>Megiddo</u>","Egypt","Syria","Magdallah"]', '<u>Megiddo</u> (2 Kings 23:29).', '{"bold":[],"italic":[],"underline":["Megiddo"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckszyoz00f8mjhj7gulcjjm7x', 'General Mathematics', 'WAEC', null, 2020, null, 'If 243ₓ = 123₁₀, find x.', null, '["6","7","8","9"]', 0, '2x² + 4x + 3 = 123 → 2x² + 4x - 120 = 0 → x² + 2x - 60 = 0 → x = 6.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If 243ₓ = 123₁₀, find x.', '["6","7","8","9"]', '243ₓ = 2x² + 4x + 3 = 123 → <u>x = 6</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cktbqjyxdogj82c4gy7i9ph1j', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Taking the ritual bath for Friday prayers is', null, '["wajib","sunnah","mustahab","mubah."]', 1, 'It is sunnah.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Taking the ritual bath for Friday prayers is', '["wajib","<u>sunnah</u>","mustahab","mubah."]', '<u>Sunnah</u>.', '{"bold":[],"italic":[],"underline":["sunnah"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cktur2zjhxr5iucdt7r1n5w04', 'Chemistry', 'JAMB', null, 1998, null, '2X(g) + Y(g) → Z(g). In the equation above, the rate of formation of Z is found to be independent of the concentration of Y and to quadruple when the concentration of X is doubled. The rate equation for the reaction is', null, '["R = k[X][Y]","R = k[X]²[Y]","R = k[X]²[Y]⁰","R = k[X]²[Y]⁰"]', 2, 'Rate ∝ [X]², independent of [Y] → R = k[X]².', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '2X(g) + Y(g) → Z(g). In the equation above, the rate of formation of Z is found to be independent of the concentration of Y and to quadruple when the concentration of X is doubled. The rate equation for the reaction is', '["R = k[X][Y]","R = k[X]²[Y]","R = k[X]²[Y]⁰","R = k[X]²[Y]⁰"]', 'Rate = <u>k[X]²</u> (independent of Y).', '{"bold":[],"italic":[],"underline":["R = k[X]²[Y]⁰"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cku1x706i0oshcqva25cvy117', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the equation of the tangent to the circle x² + y² - 4x + 6y - 12 = 0 at the point (5, 1).', null, '["3x + 4y - 19 = 0","3x - 4y + 19 = 0","3x - 4y - 11 = 0","3x + 4y - 11 = 0"]', 0, 'Center (2, -3); radius to (5,1) slope = 4/3; tangent slope = -3/4; equation: 3x + 4y = 19.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the equation of the tangent to the circle x² + y² - 4x + 6y - 12 = 0 at the point (5, 1).', '["3x + 4y - 19 = 0","3x - 4y + 19 = 0","3x - 4y - 11 = 0","3x + 4y - 11 = 0"]', 'Tangent: <u>3x + 4y - 19 = 0</u>.', '{"bold":[],"italic":[],"underline":["3x + 4y - 19 = 0"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cku4kz966bghth419zjy0pymx', 'Islamic Religious Studies', 'JAMB', null, 2011, null, 'Islam as a monotheistic religion expects that every faithful follower should', null, '["not tell lies","serve Allah without associates","praise the Prophets as enjoined by Allah","perform Salat"]', 1, 'Monotheism requires serving Allah without associates.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Islam as a monotheistic religion expects that every faithful follower should', '["not tell lies","<u>serve Allah without associates</u>","praise the Prophets as enjoined by Allah","perform Salat"]', 'Monotheism requires <u>serving Allah without associates</u>.', '{"bold":[],"italic":[],"underline":["serve Allah without associates"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckuaxv3ivlsnqfih2mssal0fg', 'Biology', 'JAMB', null, 1988, null, 'In the mammalian respiratory system, exchange of gases occurs in the', null, '["lungs","bronchi","bronchioles","alveoli"]', 3, 'Gas exchange occurs in the alveoli.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the mammalian respiratory system, exchange of gases occurs in the', '["lungs","bronchi","bronchioles","<u>alveoli</u>"]', '<u>Gas exchange occurs in the alveoli</u>.', null);
