insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckui7jhw785mdifz2gqiwssfr', 'General Mathematics', 'WAEC', null, 2020, null, 'If sin θ = 12/13 and cos φ = 3/5, where θ is obtuse and φ is acute, find sin(θ - φ).', null, '["56/65","-56/65","16/65","-16/65"]', 0, 'cos θ = -5/13; sin φ = 4/5; sin(θ-φ) = (12/13)(3/5) - (-5/13)(4/5) = 36/65 + 20/65 = 56/65.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If sin θ = 12/13 and cos φ = 3/5, where θ is obtuse and φ is acute, find sin(θ - φ).', '["56/65","-56/65","16/65","-16/65"]', 'sin(θ - φ) = <u>56/65</u>.', null);
