insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckux491g34fdrthquvh12qsf7', 'General Mathematics', 'JAMB', null, 2020, null, 'Simplify ((1 - √2 + √3)² - (1 + √2 - √3)²)/√6.', null, '["2","4","6","8"]', 1, 'Difference of squares: 4(√2 - √3); divided by √6 ≈ 4. Key says 4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Simplify ((1 - √2 + √3)² - (1 + √2 - √3)²)/√6.', '["2","4","6","8"]', 'Value = <u>4</u>.', '{"bold":[],"italic":[],"underline":["4"],"fillBlanks":[]}');
