insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckx7r3nht3ve1v8jx79t50gxq', 'General Mathematics', 'WAEC', null, 2020, null, 'Range of (x² + x + 1)/(x + 1).', null, '["(-∞, -3] ∪ [1, ∞)","[0, 2]","[1, 2]","[1/3, 1]"]', 0, 'y(x+1) = x²+x+1 → x² + (1-y)x + (1-y) = 0; discriminant ≥ 0 → (y-1)(y+3) ≥ 0 → y ≤ -3 or y ≥ 1.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Range of (x² + x + 1)/(x + 1).', '["(-∞, -3] ∪ [1, ∞)","[0, 2]","[1, 2]","[1/3, 1]"]', 'y(x+1) = x²+x+1 → x² + (1-y)x + (1-y) = 0; discriminant ≥ 0 → (y-1)(y+3) ≥ 0 → y ≤ -3 or y ≥ 1.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckxd1af4q8jddvuqnk6guj58w', 'Chemistry', 'JAMB', null, 1995, null, 'Coal fire should not be used in poorly ventilated rooms because', null, '["of the accumulation of CO2 which causes deep sleep","it is usually too hot","of the accumulation of CO which causes suffocation","it removes most of the gases in the room"]', 2, 'CO from incomplete combustion causes suffocation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Coal fire should not be used in poorly ventilated rooms because', '["of the accumulation of CO2 which causes deep sleep","it is usually too hot","of the accumulation of CO which causes suffocation","it removes most of the gases in the room"]', '<u>CO accumulation causes suffocation</u>.', '{"bold":[],"italic":[],"underline":["of the accumulation of CO which causes suffocation"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckxi5s6817awkrbemptnmvc18', 'General Mathematics', 'JAMB', null, 2020, null, 'Evaluate ∫₀¹ ln x dx.', null, '["-1","0","1","Divergent"]', 0, '∫ln x dx = x ln x - x; evaluated 0 to 1 = -1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Evaluate ∫₀¹ ln x dx.', '["-1","0","1","Divergent"]', 'Integral = <u>-1</u>.', '{"bold":[],"italic":[],"underline":["-1"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckxksbssf7kpkzxmhuyqijget', 'Chemistry', 'JAMB', null, 2004, null, 'Sodium metal is always kept under oil because it', null, '["is reduced by atmospheric nitrogen","readily reacts with water","reacts with oxygen and carbon(IV) oxide","reacts vigorously on exposure to air"]', 1, 'Na reacts vigorously with water/moisture.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Sodium metal is always kept under oil because it', '["is reduced by atmospheric nitrogen","readily reacts with water","reacts with oxygen and carbon(IV) oxide","reacts vigorously on exposure to air"]', '<u>Readily reacts with water</u>.', '{"bold":[],"italic":[],"underline":["readily reacts with water"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckxvmn20jyo4wbraafvwt14fi', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'What was Samson''s major achievement as Israel''s leader?', null, '["He suppressed the Philistines","He captured the city of Jericho","He saved the Israelites from the Amorites","He secured permanent independence for Israel."]', 0, 'Samson suppressed the Philistines.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What was Samson''s major achievement as Israel''s leader?', '["<u>He suppressed the Philistines</u>","He captured the city of Jericho","He saved the Israelites from the Amorites","He secured permanent independence for Israel."]', '<u>He suppressed the Philistines</u> (Judges 16:23-24).', '{"bold":[],"italic":[],"underline":["He suppressed the Philistines"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckxyntdhwjwwlhmuxkt073t8m', 'Biology', 'JAMB', null, 1989, null, 'A physiological adaptation of plants to the problem of excessive water loss is', null, '["reduction in the number of stomata","reversal of the normal stomatal rhythm","possession of shallow roots","possession of waxy cuticle"]', 3, 'A waxy cuticle reduces water loss.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A physiological adaptation of plants to the problem of excessive water loss is', '["reduction in the number of stomata","reversal of the normal stomatal rhythm","possession of shallow roots","<u>possession of waxy cuticle</u>"]', '<u>A waxy cuticle reduces water loss</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cky4q0aedy3xorcc0lovaanyv', 'Government', 'JAMB', null, 2020, null, 'The major motivation for British colonization of Nigeria was to', null, '["westernize Nigerians","spread religion","protect Nigeria from external attack","satisfy British economic interests."]', 3, 'British colonization was motivated by economic interests.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The major motivation for British colonization of Nigeria was to', '["westernize Nigerians","spread religion","protect Nigeria from external attack","<u>satisfy British economic interests.</u>"]', '<u>Satisfy British economic interests</u>.', '{"bold":[],"italic":[],"underline":["satisfy British economic interests."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckye9b6154valvtvu9vuy3ubg', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'The two sons of Samuel that became judges in Israel were', null, '["Joel and Abijah","Abimelech and Abijah","Hophni and Phinehas","Joel and Abimelech"]', 0, 'Samuel''s sons were Joel and Abijah.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The two sons of Samuel that became judges in Israel were', '["<u>Joel and Abijah</u>","Abimelech and Abijah","Hophni and Phinehas","Joel and Abimelech"]', '<u>Joel and Abijah</u> (1 Samuel 8:2).', '{"bold":[],"italic":[],"underline":["Joel and Abijah"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ckyltv3fm8uybk2v8ef449pim', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve √(x+2) > x.', null, '["[-2, 2)","[-2, 2]","[0, 2)","[-2, 0)"]', 0, 'x+2 > x² and x+2 ≥ 0 → x²-x-2 < 0 → -1 < x < 2, and x ≥ -2 → [-2, 2) covers. But also need √(x+2) > x for x<0. So [-2, 2).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve √(x+2) > x.', '["[-2, 2)","[-2, 2]","[0, 2)","[-2, 0)"]', '<u>x ∈ [-2, 2)</u>.', null);
