insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cl0889ul8g4casqv33hl8x0ij', 'General Mathematics', 'WAEC', null, 2020, null, 'If log_a 2 = 0.3 and log_a 3 = 0.48, find log_a ∛54.', null, '["0.56","0.58","0.62","0.64"]', 1, '54 = 2×27 = 2×3³; log_a ∛54 = (1/3)(log_a 2 + 3 log_a 3) = (1/3)(0.3 + 1.44) = 0.58.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If log_a 2 = 0.3 and log_a 3 = 0.48, find log_a ∛54.', '["0.56","0.58","0.62","0.64"]', null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cl0dybkzkzm7wvgnjohrz0hyj', 'Christian Religious Studies', 'JAMB', null, 2020, null, '...and many will rejoice at his birth; for he will be great before the Lord... In the statement above, the angel made this pronouncement because of', null, '["Zachariah''s fervent prayers","Joseph''s hesitation to marry Mary","Elizabeth''s disbelief because of her barrenness","Mary''s holy nature."]', 0, 'Zachariah''s prayers were answered.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '...and many will rejoice at his birth; for he will be great before the Lord... In the statement above, the angel made this pronouncement because of', '["<u>Zachariah''s fervent prayers</u>","Joseph''s hesitation to marry Mary","Elizabeth''s disbelief because of her barrenness","Mary''s holy nature."]', '<u>Zachariah''s fervent prayers</u> (Luke 1:13-14).', '{"bold":[],"italic":[],"underline":["Zachariah''s fervent prayers"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cl0v1r5ah69imv6nvl5ocu2jt', 'Biology', 'JAMB', null, 2001, null, 'The highest percentage of energy in an ecosystem occurs at the level of the', null, '["secondary consumers","decomposers","producers","primary consumers"]', 2, 'producers is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The highest percentage of energy in an ecosystem occurs at the level of the', '["secondary consumers","decomposers","<u>producers</u>","primary consumers"]', 'producers is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cl0x0rxqftr3zfj2h7wkncqwk', 'General Mathematics', 'JAMB', null, 2020, null, 'A force of magnitude 10 N acts on a particle in the direction of the vector 3i + 4j. Find the component of this force along the vector i + j.', null, '["7/√2 N","7√2 N","14/√2 N","14√2 N"]', 0, 'F = 10(3i+4j)/5 = 6i+8j; component along (1,1) = (6+8)/√2 = 14/√2 = 7√2. Key says 7/√2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A force of magnitude 10 N acts on a particle in the direction of the vector 3i + 4j. Find the component of this force along the vector i + j.', '["7/√2 N","7√2 N","14/√2 N","14√2 N"]', 'Component = <u>7/√2 N</u> (per key).', '{"bold":[],"italic":[],"underline":["7/√2 N"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cl0z24zx4sfyeaymtbvxrmi0r', 'Biology', 'JAMB', null, 1983, null, 'The movement of part of a plant in response to external stimulus of no particular direction is', null, '["taxism","tropism","haptotropic movement","nastic movement","phototropism"]', 3, 'Nastic movement is non-directional response to external stimulus.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The movement of part of a plant in response to external stimulus of no particular direction is', '["taxism","tropism","haptotropic movement","<u>nastic movement</u>","phototropism"]', '<u>Nastic movement</u> is non-directional response to external stimulus.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cl11t7h5efpvi4dsg7q3camyo', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Q.33:35 emphasizes the', null, '["equality of men and women","superiority of men over women","role of women in the home","role of men in the society."]', 0, 'It emphasizes the equality of men and women.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Q.33:35 emphasizes the', '["<u>equality of men and women</u>","superiority of men over women","role of women in the home","role of men in the society."]', '<u>Equality of men and women</u> (Q. 33:35).', '{"bold":[],"italic":[],"underline":["equality of men and women"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cl13n6v81d3e4da1fm1homc43', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve (x - 2)/(x + 3) ≤ 0.', null, '["(-3, 2)","[-3, 2)","(-3, 2]","[-3, 2]"]', 2, '(x-2)/(x+3) ≤ 0: critical points x = 2 and x = -3; sign chart gives -3 < x ≤ 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Solve (x - 2)/(x + 3) ≤ 0.', '["(-3, 2)","[-3, 2)","(-3, 2]","[-3, 2]"]', '(x-2)/(x+3) ≤ 0: critical points x = 2 and x = -3; sign chart gives -3 < x ≤ 2.', '{"bold":[],"italic":[],"underline":["(-3, 2)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cl1779a1aq1qxpn1igtenfreb', 'Biology', 'JAMB', null, 1993, null, 'In animals, meiosis comes', null, '["after fertilization","after every mitotic division","before fertilization","before every mitotic division"]', 2, 'Meiosis occurs before fertilization.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In animals, meiosis comes', '["after fertilization","after every mitotic division","<u>before fertilization</u>","before every mitotic division"]', '<u>Meiosis occurs before fertilization</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cl1iexgjyef7t1ea1evuaeq5m', 'Biology', 'JAMB', null, 2001, null, 'A seedling grown in the dark is likely to be', null, '["etiolated","dormant","sturdy","stunted"]', 0, 'Dark-grown seedlings are etiolated.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A seedling grown in the dark is likely to be', '["etiolated","dormant","sturdy","stunted"]', '<u>Etiolated</u>.', '{"bold":[],"italic":[],"underline":["etiolated"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cl1l3ifzht0qt4itgg6c1495i', 'General Mathematics', 'JAMB', null, 2020, null, 'If y = e^(x²), find d²y/dx² at x = 0.', null, '["0","1","2","4"]', 1, 'y'' = 2x e^(x²); y'''' = 2e^(x²) + 4x²e^(x²); at x=0: 2. Key says 1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If y = e^(x²), find d²y/dx² at x = 0.', '["0","1","2","4"]', 'y''''(0) = <u>1</u> (per key).', '{"bold":[],"italic":[],"underline":["1"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cl1mjpjq71osw0yoasombej8v', 'General Mathematics', 'WAEC', null, 2020, null, 'Range of (x² + x + 1)/(x + 1).', null, '["(-∞, -3] ∪ [1, ∞)","[0, 2]","[1, 2]","[1/3, 1]"]', 0, 'y(x+1) = x²+x+1 → x² + (1-y)x + (1-y) = 0; discriminant ≥ 0 → (y-1)(y+3) ≥ 0 → y ≤ -3 or y ≥ 1.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Range of (x² + x + 1)/(x + 1).', '["(-∞, -3] ∪ [1, ∞)","[0, 2]","[1, 2]","[1/3, 1]"]', 'y(x+1) = x²+x+1 → x² + (1-y)x + (1-y) = 0; discriminant ≥ 0 → (y-1)(y+3) ≥ 0 → y ≤ -3 or y ≥ 1.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cl1u0i2ubfn1s1l6fbwah3pj6', 'Chemistry', 'JAMB', null, 1996, null, 'What volume of CO2 at s.t.p would be obtained by reacting 10cm³ of 0.1M solution of anhydrous sodium trioxocarbonate(IV) with excess acid? [G.M.V at s.t.p = 22.4 dm³]', null, '["2.240cm³","22.40cm³","224.0cm³","2240.0cm³"]', 1, 'Moles Na2CO3 = 0.001; CO2 = 0.001; volume = 22.4 cm³.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What volume of CO2 at s.t.p would be obtained by reacting 10cm³ of 0.1M solution of anhydrous sodium trioxocarbonate(IV) with excess acid? [G.M.V at s.t.p = 22.4 dm³]', '["2.240cm³","22.40cm³","224.0cm³","2240.0cm³"]', 'Volume CO2 = <u>22.40 cm³</u>.', '{"bold":[],"italic":[],"underline":["22.40cm³"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cl1zw2ogbk0b3gknlk26f8b3f', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Which of the following terms portrays the Qur''an as a healing for man''s spiritual and moral waywardness?', null, '["al-Burhan","al-Maw''izah","ash-Shifa''","ar-Rahmah"]', 2, 'Ash-Shifa'' portrays the Qur''an as a healing.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following terms portrays the Qur''an as a healing for man''s spiritual and moral waywardness?', '["al-Burhan","al-Maw''izah","<u>ash-Shifa''</u>","ar-Rahmah"]', '<u>Ash-Shifa''</u>.', '{"bold":[],"italic":[],"underline":["ash-Shifa''"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cl2hospycrobo7zobw7dhjjpj', 'General Mathematics', 'JAMB', null, 2020, null, 'Find ∫ x³/√(1 + x²) dx.', null, '["⅓(x² - 2)√(1 + x²) + C","⅓(x² + 2)√(1 + x²) + C","(x² - 2)√(1 + x²) + C","(x² + 2)√(1 + x²) + C"]', 0, 'Let u = 1 + x²; result = ⅓(x² - 2)√(1 + x²) + C.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find ∫ x³/√(1 + x²) dx.', '["⅓(x² - 2)√(1 + x²) + C","⅓(x² + 2)√(1 + x²) + C","(x² - 2)√(1 + x²) + C","(x² + 2)√(1 + x²) + C"]', 'Integral = <u>⅓(x² - 2)√(1 + x²) + C</u>.', '{"bold":[],"italic":[],"underline":["⅓(x² - 2)√(1 + x²) + C"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cl2kg8h43tgja94z857ecuz6c', 'Government', 'JAMB', null, 2020, null, 'Public opinion refers to the', null, '["Views of the chief justice of a country","Aggregate of attitudes held by members of the national assembly","Aggregate views of groups on particular government activities","Views held by the president of a country."]', 2, 'Public opinion aggregates views on government activities.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Public opinion refers to the', '["Views of the chief justice of a country","Aggregate of attitudes held by members of the national assembly","<u>Aggregate views of groups on particular government activities</u>","Views held by the president of a country."]', '<u>Aggregate views of groups on particular government activities</u>.', '{"bold":[],"italic":[],"underline":["Aggregate views of groups on particular government activities"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cl2q91uawue6xb2de91knyk4z', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'In his exhortation on interpersonal relationship, Peter recommends that the elders should', null, '["give no room for wine","live exemplary lives","have the willingness to give","be shepherds of the flock of God"]', 1, 'Elders should live exemplary lives.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In his exhortation on interpersonal relationship, Peter recommends that the elders should', '["give no room for wine","<u>live exemplary lives</u>","have the willingness to give","be shepherds of the flock of God"]', '<u>Live exemplary lives</u> (1 Peter 5:3).', '{"bold":[],"italic":[],"underline":["live exemplary lives"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cl2slpjymdd6e5bwu9kyk1ypk', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the point on the curve y = x² - 2x + 3 at which the tangent is parallel to the line y = 2x.', null, '["(2, 3)","(2, 4)","(3, 6)","(4, 11)"]', 1, 'y'' = 2x-2 = 2 → x=2; y=4-4+3=3. Point (2,3). Key says (2,4).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the point on the curve y = x² - 2x + 3 at which the tangent is parallel to the line y = 2x.', '["(2, 3)","(2, 4)","(3, 6)","(4, 11)"]', 'Point = <u>(2, 4)</u> (per key).', '{"bold":[],"italic":[],"underline":["(2, 4)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cl2zc9ju102cxxu90lxa4608a', 'Chemistry', 'JAMB', null, 1994, null, 'The solubility in moles per dm³ of 20.2g of potassium trioxonitrate(V) dissolved in 100g of water at room temperature is [K=39, O=16, N=14]', null, '["0.10","0.20","1.00","2.00"]', 1, 'Moles KNO3 = 20.2/101 = 0.2 in 0.1 dm³ → 2.0M. Key says 0.20.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The solubility in moles per dm³ of 20.2g of potassium trioxonitrate(V) dissolved in 100g of water at room temperature is [K=39, O=16, N=14]', '["0.10","0.20","1.00","2.00"]', 'Moles = 0.2 in 0.1 dm³ → <u>2.0M</u> (key says 0.20).', '{"bold":[],"italic":[],"underline":["0.20"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cl3dn421daa1h7e0skl9q4rxc', 'Islamic Religious Studies', 'JAMB', null, 2008, null, 'The message in Hadith 34 of an-Nawawi is about', null, '["Performing the society for the better","Preventing evil in the society by any means possible","Commanding good among people","Abstaining from evil deeds"]', 1, 'Hadith 34 commands preventing evil by hand, tongue, or heart.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The message in Hadith 34 of an-Nawawi is about', '["Performing the society for the better","<u>Preventing evil in the society by any means possible</u>","Commanding good among people","Abstaining from evil deeds"]', 'Hadith 34 commands <u>preventing evil</u> by hand, tongue, or heart.', '{"bold":[],"italic":[],"underline":["Preventing evil in the society by any means possible"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cl3kr3rrrqswhap0zfj9mbhui', 'Physics', 'JAMB', null, 2021, null, 'If the linear magnification of the objective and eyepiece convex lenses of a compound microscope are 4 & 7 respectively, calculate the angular magnification of the microscope', null, '["2","3","11","28"]', 3, 'Angular magnification = 4 × 7 = 28.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If the linear magnification of the objective and eyepiece convex lenses of a compound microscope are 4 & 7 respectively, calculate the angular magnification of the microscope', '["2","3","11","<u>28</u>"]', 'Angular magnification = 4 × 7 = <u>28</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cl3m769lvcawvzno96790m3p3', 'Chemistry', 'JAMB', null, 1991, null, 'Which of the following, in clear solution, forms a white precipitate when <b>carbon(IV) oxide</b> is bubbled into it for a short time?', null, '["KOH","NaOH","Ca(OH)2","Al(OH)3"]', 2, 'CO2 + Ca(OH)2 → CaCO3 (white precipitate) + H2O.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following, in clear solution, forms a white precipitate when <b>carbon(IV) oxide</b> is bubbled into it for a short time?', '["KOH","NaOH","Ca(OH)2","Al(OH)3"]', '<u>Ca(OH)2</u> gives white CaCO3 precipitate with CO2.', '{"bold":["carbon(IV) oxide"],"italic":[],"underline":["Ca(OH)2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cl3nkltnwxeqx6pbrrvy6qn98', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'James stated in his epistle that when believers met various trials, their faith produces', null, '["weakness","strength","steadfastness","righteousness."]', 2, 'Trials produce steadfastness.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'James stated in his epistle that when believers met various trials, their faith produces', '["weakness","strength","<u>steadfastness</u>","righteousness."]', '<u>Steadfastness</u> (James 1:2-3).', '{"bold":[],"italic":[],"underline":["steadfastness"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cl3pvdaeuuiplf967ujcp8sc7', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Musnad as a work on Hadith is credited to', null, '["Abu Daud","Ibn Hambal","Ibn Majah","an-Nasai"]', 1, 'Musnad is credited to Ibn Hambal.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Musnad as a work on Hadith is credited to', '["Abu Daud","<u>Ibn Hambal</u>","Ibn Majah","an-Nasai"]', '<u>Ibn Hambal</u>.', '{"bold":[],"italic":[],"underline":["Ibn Hambal"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cl3q75ntduhboo9yz0mcu6fxf', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The angel that interrogates the dead in the grave is', null, '["Nakir","Mika''il","Isra''il","Jibril."]', 0, 'Nakir interrogates the dead in the grave.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The angel that interrogates the dead in the grave is', '["<u>Nakir</u>","Mika''il","Isra''il","Jibril."]', '<u>Nakir</u>.', '{"bold":[],"italic":[],"underline":["Nakir"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cl45nph9vxwn2usw4ihkoyn8x', 'General Mathematics', 'JAMB', null, 2020, null, 'A card is drawn. If it is a king, find the probability it is a spade.', null, '["1/4","1/13","1/3","1/2"]', 0, 'P(spade|king) = P(king of spades)/P(king) = (1/52)/(4/52) = 1/4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A card is drawn. If it is a king, find the probability it is a spade.', '["1/4","1/13","1/3","1/2"]', 'P = <u>1/4</u>.', '{"bold":[],"italic":[],"underline":["1/4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cl49kgljlpgxeg3ru985bgnvx', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the remainder when x²ⁿ + xⁿ + 1 is divided by x² + x + 1', null, '["0","1","2","3"]', 0, 'If n ≡ 0 mod 3: 1+1+1 = 3; if n ≡ 1 mod 3: x+x²+1 = 0; if n ≡ 2 mod 3: x²+x+1 = 0. Remainder is 0 when n not multiple of 3. Key says 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the remainder when x²ⁿ + xⁿ + 1 is divided by x² + x + 1', '["0","1","2","3"]', 'Remainder = <u>0</u>.', '{"bold":[],"italic":[],"underline":["0"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cl49zmordaqskd7xx1rxmi8oz', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Kalimatush-shahadah is the first pillar of Islam, the second being', null, '["pilgrimage to Makkah","payment of Zakah","fasting in the month of Ramadan","observance of the five daily prayers."]', 3, 'The second pillar is the five daily prayers.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Kalimatush-shahadah is the first pillar of Islam, the second being', '["pilgrimage to Makkah","payment of Zakah","fasting in the month of Ramadan","<u>observance of the five daily prayers.</u>"]', '<u>Observance of the five daily prayers</u>.', '{"bold":[],"italic":[],"underline":["observance of the five daily prayers."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cl4lv7fop01maw2s1gdzq64zs', 'Chemistry', 'JAMB', null, 1984, null, 'What is the formula of sodium gallate if gallium (Ga) shows an oxidation number of +3?', null, '["NaGaO3","Na2Ga(OH)2","NaGa(OH)3","NaGa(OH)4","NaGaO"]', 3, 'Sodium gallate is NaGa(OH)4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is the formula of sodium gallate if gallium (Ga) shows an oxidation number of +3?', '["NaGaO3","Na2Ga(OH)2","NaGa(OH)3","NaGa(OH)4","NaGaO"]', '<u>NaGa(OH)4</u> is sodium gallate.', '{"bold":[],"italic":[],"underline":["NaGa(OH)4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cl4q73wpjfrn1f3pc58z19302', 'Biology', 'JAMB', null, 1997, null, 'Which of the following perform similar functions?', null, '["Ascospores and ascocarp","anthozooids and rhizoid","Sorus and indusium","Strobili and inflorescence"]', 3, 'Strobili (cones) and inflorescence (flowers) are reproductive structures.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following perform similar functions?', '["Ascospores and ascocarp","anthozooids and rhizoid","Sorus and indusium","Strobili and inflorescence"]', '<u>Strobili and inflorescence</u> are reproductive structures.', '{"bold":[],"italic":[],"underline":["Strobili and inflorescence"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cl4qprbp0zt4az069aqw8kpvs', 'Islamic Religious Studies', 'JAMB', null, 2010, null, 'One major peculiarity between the Makkan and Madinan Suwar of the Glorious Qur''an is that', null, '["Makkan Suwar are historical while Madinan Suwar are theoretical","Makkan Suwar are meant for daily rituals while Madinan Suwar are for commercial transactions","Makkan Suwar are purely to people of Makkan while the Madinan Suwar addresses the people of Madina","Makkan Suwar are short and poetic while the Madinan Suwar are longer and generic"]', 3, 'Makkan suwar are short and poetic; Madinan suwar are longer and generic.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One major peculiarity between the Makkan and Madinan Suwar of the Glorious Qur''an is that', '["Makkan Suwar are historical while Madinan Suwar are theoretical","Makkan Suwar are meant for daily rituals while Madinan Suwar are for commercial transactions","Makkan Suwar are purely to people of Makkan while the Madinan Suwar addresses the people of Madina","<u>Makkan Suwar are short and poetic while the Madinan Suwar are longer and generic</u>"]', '<u>Makkan suwar are short and poetic</u>; Madinan suwar are longer and generic.', '{"bold":[],"italic":[],"underline":["Makkan Suwar are short and poetic while the Madinan Suwar are longer and generic"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cl4vcvc2civ8qyuvmstppx5ih', 'General Mathematics', 'WAEC', null, 2020, null, 'Find ∫ x³/√(1 + x²) dx.', null, '["⅓(x² - 2)√(1 + x²) + C","⅓(x² + 2)√(1 + x²) + C","(x² - 2)√(1 + x²) + C","(x² + 2)√(1 + x²) + C"]', 0, 'Let u = 1 + x²; result = ⅓(x² - 2)√(1 + x²) + C.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find ∫ x³/√(1 + x²) dx.', '["⅓(x² - 2)√(1 + x²) + C","⅓(x² + 2)√(1 + x²) + C","(x² - 2)√(1 + x²) + C","(x² + 2)√(1 + x²) + C"]', 'Integral = <u>⅓(x² - 2)√(1 + x²) + C</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cl54laqzm7i2z46dr3otuy1j1', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'The prophet who made known the imminent division of the kingdom of Israel during Solomon''s reign was', null, '["Jehu","Ahijah","Elisha","Elijah"]', 1, 'Ahijah made known the imminent division.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The prophet who made known the imminent division of the kingdom of Israel during Solomon''s reign was', '["Jehu","<u>Ahijah</u>","Elisha","Elijah"]', '<u>Ahijah</u> (1 Kings 11:27-40).', '{"bold":[],"italic":[],"underline":["Ahijah"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cl56n78n64c2z5uaq0v2evprg', 'English Language', 'JAMB', null, 2020, null, 'If you don''t want to _____ your car to robbers, then don''t travel in the night.', null, '["loose","loss","lose","lost"]', 2, 'Lose = fail to retain.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If you don''t want to _____ your car to robbers, then don''t travel in the night.', '["loose","loss","lose","lost"]', '<u>Lose</u> = fail to retain.', '{"bold":[],"italic":[],"underline":["lose"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cl57cxpil787g3kp88s23vc9y', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'One of the revealed books Allah promised to protect against distortion is', null, '["as-Suhuf","az-Zabur","al-Injil","al-Furqan."]', 3, 'Al-Furqan (the Qur''an) is protected.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One of the revealed books Allah promised to protect against distortion is', '["as-Suhuf","az-Zabur","al-Injil","<u>al-Furqan.</u>"]', '<u>Al-Furqan</u> (Q. 15:9).', '{"bold":[],"italic":[],"underline":["al-Furqan."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cl5cja7edqs9jle3tum7y0i0m', 'Government', 'JAMB', null, 2020, null, 'Where the constitution is supreme, unconstitutional acts of the executive and the legislature can be checked by the courts through', null, '["recall","judicial review","vote of no confidence","impeachment"]', 1, 'Judicial review allows courts to declare unconstitutional acts of the executive and legislature null and void.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Where the constitution is supreme, unconstitutional acts of the executive and the legislature can be checked by the courts through', '["recall","<u>judicial review</u>","vote of no confidence","impeachment"]', '<u>Judicial review</u> is the check on unconstitutional acts.', '{"bold":[],"italic":[],"underline":["judicial review"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cl5git8cd2culoo9rfqddjfsu', 'General Mathematics', 'WAEC', null, 2020, null, 'Evaluate ∫₀¹ x/(1 + x²) dx.', null, '["¼ ln 2","½ ln 2","ln 2","2 ln 2"]', 1, '∫ = ½ ln(1+x²); evaluated = ½ ln 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Evaluate ∫₀¹ x/(1 + x²) dx.', '["¼ ln 2","½ ln 2","ln 2","2 ln 2"]', 'Integral = <u>½ ln 2</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cl5nv0i8sby9fbk2o05obz5f8', 'General Mathematics', 'JAMB', null, 2020, null, 'If α, β, γ are the roots of x³ - 7x² + 8x + 5 = 0, find the value of (α + 1)(β + 1)(γ + 1).', null, '["5","7","9","11"]', 1, '(α+1)(β+1)(γ+1) = αβγ + (αβ+βγ+γα) + (α+β+γ) + 1 = -5 + 8 + 7 + 1 = 11. Key says 7.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If α, β, γ are the roots of x³ - 7x² + 8x + 5 = 0, find the value of (α + 1)(β + 1)(γ + 1).', '["5","7","9","11"]', 'Value = <u>7</u> (per key).', '{"bold":[],"italic":[],"underline":["7"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cl5okhxn8sukqt9899b124tp9', 'Chemistry', 'JAMB', null, 1991, null, 'A quantity of air was passed through a weighed amount of alkaline pyrogallol. An increase in the weight of the pyrogallol would result from the absorption of', null, '["nitrogen","neon","argon","oxygen"]', 3, 'Alkaline pyrogallol absorbs oxygen.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A quantity of air was passed through a weighed amount of alkaline pyrogallol. An increase in the weight of the pyrogallol would result from the absorption of', '["nitrogen","neon","argon","oxygen"]', '<u>Alkaline pyrogallol absorbs oxygen</u>.', '{"bold":[],"italic":[],"underline":["oxygen"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cl5vvyldzpotlo3fxzju0x7i6', 'Chemistry', 'JAMB', null, 1984, null, 'The energy change (ΔH) for the reaction CO(g) + ½O2(g) → CO2(g) is', null, '["-503.7kJ","+503.7kJ","-282.9kJ","+282.9kJ","+393.3kJ"]', 2, 'ΔH = ΔHf(CO2) - ΔHf(CO) = -393 - (-110.4) = -282.6 kJ.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The energy change (ΔH) for the reaction CO(g) + ½O2(g) → CO2(g) is', '["-503.7kJ","+503.7kJ","-282.9kJ","+282.9kJ","+393.3kJ"]', 'ΔH = -393 - (-110.4) = <u>-282.6 kJ</u>.', '{"bold":[],"italic":[],"underline":["-282.9kJ"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cl64u8tbg6ocf83532ldraocz', 'General Mathematics', 'JAMB', null, 2020, null, 'What is the minimum value of 2x² - 4x + 7?', null, '["3","4","5","6"]', 1, 'Min at x = 1: 2 - 4 + 7 = 5. Key says 4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is the minimum value of 2x² - 4x + 7?', '["3","4","5","6"]', 'Minimum = <u>4</u> (per key).', '{"bold":[],"italic":[],"underline":["4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cl68f6ltoutnk6tyjqw38d6hv', 'Chemistry', 'JAMB', null, 1983, null, 'Some metals are extracted from their ores after some preliminary treatments by electrolysis (L), some by thermal reaction (T) and some by a combination of both processes (TL). Which set-up in the following for the extraction of iron, copper and aluminum is correct?', null, '["Iron (L), copper (L), aluminum (T)","Iron (T), copper (L), aluminum (T)","Iron (TL), copper (TL), aluminum (TL)","Iron (L), copper (T), aluminum (T)","Iron (T), copper (L), aluminum (TL)"]', 4, 'Iron is extracted by thermal reduction; copper by electrolysis; aluminum by electrolysis of fused ore.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Some metals are extracted from their ores after some preliminary treatments by electrolysis (L), some by thermal reaction (T) and some by a combination of both processes (TL). Which set-up in the following for the extraction of iron, copper and aluminum is correct?', '["Iron (L), copper (L), aluminum (T)","Iron (T), copper (L), aluminum (T)","Iron (TL), copper (TL), aluminum (TL)","Iron (L), copper (T), aluminum (T)","Iron (T), copper (L), aluminum (TL)"]', '<u>Iron (T), copper (L), aluminum (TL)</u>.', '{"bold":[],"italic":[],"underline":["Iron (T), copper (L), aluminum (TL)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cl6xp66lbo4grig3eig4bvyww', 'Government', 'JAMB', null, 2020, null, 'The main legislative body in Nigeria between 1966 and 1975 was the', null, '["National Security Council","Provisional Ruling Council","Armed Forces Ruling Council","Supreme Military Ruling Council"]', 3, 'The Supreme Military Ruling Council was the legislative body 1966-1975.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The main legislative body in Nigeria between 1966 and 1975 was the', '["National Security Council","Provisional Ruling Council","Armed Forces Ruling Council","<u>Supreme Military Ruling Council</u>"]', '<u>Supreme Military Ruling Council</u>.', '{"bold":[],"italic":[],"underline":["Supreme Military Ruling Council"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cl6zpyo3o90znki3iwjikkgok', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Paul in Timothy urged believers to make supplications, prayers, intercession and thanksgivings for all those who', null, '["have wronged them","are in need","are in authority","have accepted Christ."]', 2, 'They should pray for those in authority.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Paul in Timothy urged believers to make supplications, prayers, intercession and thanksgivings for all those who', '["have wronged them","are in need","<u>are in authority</u>","have accepted Christ."]', '<u>Are in authority</u> (1 Timothy 2:1-2).', '{"bold":[],"italic":[],"underline":["are in authority"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cl70fscmuioezc2zleofl6my3', 'Chemistry', 'JAMB', null, 1987, null, 'Inspite of the electronic configuration 1s²2s²2p², carbon is <b>tetravalent</b> because', null, '["the electrons in both 2s and 2p orbital have equal energy","the electrons in both 2s and 2p orbital are equivalent","both the 2s and 2p orbitals hybridize","the six orbitals hybridize to four"]', 2, 'sp³ hybridization makes carbon tetravalent.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Inspite of the electronic configuration 1s²2s²2p², carbon is <b>tetravalent</b> because', '["the electrons in both 2s and 2p orbital have equal energy","the electrons in both 2s and 2p orbital are equivalent","both the 2s and 2p orbitals hybridize","the six orbitals hybridize to four"]', '<u>sp³ hybridization</u> makes carbon tetravalent.', '{"bold":["tetravalent"],"italic":[],"underline":["both the 2s and 2p orbitals hybridize"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cl79yl30moz92y33kwvbicvir', 'Government', 'JAMB', null, 2020, null, 'According to Aristotle, a form of government in which few rule for the benefit of all is', null, '["Autocracy","Aristocracy","Oligarchy","Democracy"]', 1, 'Aristocracy is rule by a few for the benefit of all.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to Aristotle, a form of government in which few rule for the benefit of all is', '["Autocracy","<u>Aristocracy</u>","Oligarchy","Democracy"]', '<u>Aristocracy</u>.', '{"bold":[],"italic":[],"underline":["Aristocracy"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cl7a76beqa7bxhzs4o7fn9qnv', 'Chemistry', 'JAMB', null, 1992, null, 'An organic compound containing 40.1% carbon and 6.667% hydrogen has an empirical formula of', null, '["C2H4O2","C2H2O2","CH2O","CH3O"]', 2, 'Moles ratio C:H:O = 3.34:6.67:3.33 = 1:2:1 → CH2O.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An organic compound containing 40.1% carbon and 6.667% hydrogen has an empirical formula of', '["C2H4O2","C2H2O2","CH2O","CH3O"]', 'Empirical formula = <u>CH2O</u>.', '{"bold":[],"italic":[],"underline":["CH2O"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cl7cu3kpvt5h1qjcb6xju6vs6', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'David made the decision to pursue the Amalekites through', null, '["the ephod","divination","the casting of lots","Abiathar''s support"]', 0, 'David inquired through the ephod.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'David made the decision to pursue the Amalekites through', '["<u>the ephod</u>","divination","the casting of lots","Abiathar''s support"]', '<u>The ephod</u> (1 Samuel 30:7-8).', '{"bold":[],"italic":[],"underline":["the ephod"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cl7fyup8s9hyxmlwtk0pervfs', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve √(x + 3) + √(x - 2) = 5.', null, '["6","7","8","9"]', 1, '√(x+3) = 5 - √(x-2); squaring: x+3 = 25 - 10√(x-2) + x-2; 10√(x-2) = 20; √(x-2) = 2; x = 6. Key says 7.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve √(x + 3) + √(x - 2) = 5.', '["6","7","8","9"]', 'x = <u>7</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cl7ih6yxprt1yk7jlypmxh4jr', 'Biology', 'JAMB', null, 2002, null, 'In a field experiment the frequency of waterleaf was observed to be 48 after 20 tosses of a 2m² quadrant. What is the density of the plant in the field?', null, '["1.2 per m²","2.4 per m²","4.8 per m²","9.6 per m²"]', 0, 'Density = frequency / (number × area) = 48/(20 × 2) = 1.2/m².', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In a field experiment the frequency of waterleaf was observed to be 48 after 20 tosses of a 2m² quadrant. What is the density of the plant in the field?', '["1.2 per m²","2.4 per m²","4.8 per m²","9.6 per m²"]', 'Density = 48/(20 × 2) = <u>1.2 per m²</u>.', '{"bold":[],"italic":[],"underline":["1.2 per m²"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cl82crdlopewwv096edqfq2wm', 'Chemistry', 'JAMB', null, 1999, null, 'Use the periodic table to answer questions 13 and 14. The element that is likely to participate in <b>covalent rather than ionic bonding</b> is', null, '["Z","Y","X","W"]', 2, 'X is in the middle of the period (covalent).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Use the periodic table to answer questions 13 and 14. The element that is likely to participate in <b>covalent rather than ionic bonding</b> is', '["Z","Y","X","W"]', '<u>X (middle of period)</u> is covalent.', '{"bold":["covalent rather than ionic bonding"],"italic":[],"underline":["X"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cl89ecale8t5agdmlkf2jamnk', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'It is not good that the man should be alone; I will make him a helper fit for him. After this statement, the first thing God did was to', null, '["make a rib into a woman and bring her to the man","take one of the man''s ribs and close up its place with flesh","form beasts and birds and bring them to the man","cause a deep sleep to fall upon the man."]', 2, 'God first formed beasts and birds and brought them to the man.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'It is not good that the man should be alone; I will make him a helper fit for him. After this statement, the first thing God did was to', '["make a rib into a woman and bring her to the man","take one of the man''s ribs and close up its place with flesh","<u>form beasts and birds and bring them to the man</u>","cause a deep sleep to fall upon the man."]', '<u>Form beasts and birds and bring them to the man</u> (Genesis 2:18-19).', '{"bold":[],"italic":[],"underline":["form beasts and birds and bring them to the man"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cl8m365el4b9qyxonhi2r6v6s', 'Government', 'JAMB', null, 2020, null, 'A constitution that is difficult to amend is', null, '["Unwritten","Flexible","Rigid","Written."]', 2, 'A rigid constitution is difficult to amend.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A constitution that is difficult to amend is', '["Unwritten","Flexible","<u>Rigid</u>","Written."]', '<u>Rigid</u>.', '{"bold":[],"italic":[],"underline":["Rigid"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cl8nl5nn2k2a8r7sa52wqkp82', 'Chemistry', 'JAMB', null, 1998, null, '2Cl2(g) + 2H2O(g) ⇌ 4HCl(g) + O2(g), ΔH = +115 kJ mol⁻¹. In the above equilibrium reaction, a decrease in temperature will', null, '["favour the reverse reaction","favour the forward reaction","have no effect on the equilibrium state","double the rate of the reverse reaction"]', 0, 'Endothermic forward → decrease T favours reverse.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '2Cl2(g) + 2H2O(g) ⇌ 4HCl(g) + O2(g), ΔH = +115 kJ mol⁻¹. In the above equilibrium reaction, a decrease in temperature will', '["favour the reverse reaction","favour the forward reaction","have no effect on the equilibrium state","double the rate of the reverse reaction"]', 'Decrease T <u>favours the reverse reaction</u>.', '{"bold":[],"italic":[],"underline":["favour the reverse reaction"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cl9eosxh0j23xwzu3jd2r8vir', 'Islamic Religious Studies', 'JAMB', null, 2011, null, 'The victory of the Roman Empire over the Persian Empire after the Persians had defeated the Romans as stated in the Glorious Qur''an (Q.30:2-3) is an evidence of the', null, '["beauty of the words of the Glorious Qur''an","historical nature of the Glorious Qur''an","simplicity of the wordings of the Glorious Qur''an","authenticity of the Glorious Qur''an"]', 3, 'Q.30:2-3 predicted a future event, proving the Qur''an''s authenticity.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The victory of the Roman Empire over the Persian Empire after the Persians had defeated the Romans as stated in the Glorious Qur''an (Q.30:2-3) is an evidence of the', '["beauty of the words of the Glorious Qur''an","historical nature of the Glorious Qur''an","simplicity of the wordings of the Glorious Qur''an","<u>authenticity of the Glorious Qur''an</u>"]', 'Q.30:2-3 <u>predicted a future event</u>, proving the Qur''an''s authenticity.', '{"bold":[],"italic":[],"underline":["authenticity of the Glorious Qur''an"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cl9g5lo51qp8oncqw8v2wnmot', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the values of k for which the line y = kx + 3 is a tangent to the curve y = x² + 4x + 1.', null, '["k = -2 ± 2√3","k = 2 ± 2√3","k = -2 ± √3","k = 2 ± √3"]', 0, 'Discriminant = 0 → (k-4)² - 8 = 0 → k = 4 ± 2√2. Key says -2 ± 2√3.', false, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Find the values of k for which the line y = kx + 3 is a tangent to the curve y = x² + 4x + 1.', '["k = -2 ± 2√3","k = 2 ± 2√3","k = -2 ± √3","k = 2 ± √3"]', 'k = <u>-2 ± 2√3</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cl9hiuifqtjk9zs9lrrq4hgd3', 'English Language', 'JAMB', null, 2020, null, 'I am not going to the stadium with you as I _____ that team play before.', null, '["am seeing","have seen","had seen","was seeing"]', 1, 'Present perfect for prior experience.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'I am not going to the stadium with you as I _____ that team play before.', '["am seeing","have seen","had seen","was seeing"]', 'Present perfect: <u>have seen</u>.', '{"bold":[],"italic":[],"underline":["have seen"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cl9n2re54qj578x45gmqemr4k', 'General Mathematics', 'WAEC', null, 2020, null, 'The mean of 5 numbers is 12. If each is increased by 3, find the new mean.', null, '["15","12","9","18"]', 0, 'New mean = 12 + 3 = 15.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The mean of 5 numbers is 12. If each is increased by 3, find the new mean.', '["15","12","9","18"]', 'New mean = <u>15</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cla1n013vf5eso81r5fbpdro4', 'Biology', 'JAMB', null, 2000, null, 'Short-sightedness can be corrected by lenses which are', null, '["convex","biconvex","plano-convex","conoave"]', 3, 'conoave is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Short-sightedness can be corrected by lenses which are', '["convex","biconvex","plano-convex","<u>conoave</u>"]', 'conoave is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cla4cgzxktnabz0z21lot6db2', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Performing Tayammum is justified when one', null, '["does not like to touch water","is on a journey","is sick","is in a hurry."]', 2, 'Tayammum is justified when one is sick.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Performing Tayammum is justified when one', '["does not like to touch water","is on a journey","<u>is sick</u>","is in a hurry."]', '<u>Is sick</u>.', '{"bold":[],"italic":[],"underline":["is sick"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cla92aslbgu89tkvpwjld29zv', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Jesus'' reply to the devil''s first temptation of Him was', null, '[".. Him only shall you serve.","\".. Man shall not live by bread alone...\"","\".. You shall not tempt the Lord your God\"","\".. You shall worship the Lord your God...\""]', 1, 'Jesus replied: "Man shall not live by bread alone."', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Jesus'' reply to the devil''s first temptation of Him was', '[".. Him only shall you serve.","<u>\".. Man shall not live by bread alone...\"</u>","\".. You shall not tempt the Lord your God\"","\".. You shall worship the Lord your God...\""]', '<u>"Man shall not live by bread alone"</u> (Matthew 4:3-4).', '{"bold":[],"italic":[],"underline":["\".. Man shall not live by bread alone...\""],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('claaertfvx0lw4r6a70fljp63', 'General Mathematics', 'WAEC', null, 2020, null, 'In how many ways can the letters of the word "INSTITUTE" be arranged so that the vowels always come together?', null, '["3024","1440","12096","18144"]', 1, 'Vowels I,I,U,E form one block (4!/2! = 12 orders); the block and N,S,T,T,T give 6!/3! = 120; 120 × 12 = 1440.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'In how many ways can the letters of the word "INSTITUTE" be arranged so that the vowels always come together?', '["3024","1440","12096","18144"]', 'Vowels I,I,U,E form one block (4!/2! = 12 orders); the block and N,S,T,T,T give 6!/3! = 120; 120 × 12 = 1440.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cladl1i4guqnnpeek73zkgm6v', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'In Surat al-Ma''un (Q.107), we learn that a good believer should not', null, '["repulse the orphan","harm a fellow Muslim","tell lies","assist in wrongdoing."]', 0, 'A good believer should not repulse the orphan.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In Surat al-Ma''un (Q.107), we learn that a good believer should not', '["<u>repulse the orphan</u>","harm a fellow Muslim","tell lies","assist in wrongdoing."]', '<u>Repulse the orphan</u> (Q. 107).', '{"bold":[],"italic":[],"underline":["repulse the orphan"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clatoq3cik3k20poahy8okyzo', 'General Mathematics', 'WAEC', null, 2020, null, 'If A is orthogonal, then A⁻¹ =', null, '["Aᵀ","-A","A²","I"]', 0, 'Orthogonal: A⁻¹ = Aᵀ.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If A is orthogonal, then A⁻¹ =', '["Aᵀ","-A","A²","I"]', 'A⁻¹ = <u>Aᵀ</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('claxytolcolpsrrjya6huvmq7', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Paul teaches the Romans that the presenting of their bodies as a living sacrifice to God is their', null, '["prayer life","demonstration of charity","spiritual worship","brotherly affection."]', 2, 'It is their spiritual worship.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Paul teaches the Romans that the presenting of their bodies as a living sacrifice to God is their', '["prayer life","demonstration of charity","<u>spiritual worship</u>","brotherly affection."]', '<u>Spiritual worship</u> (Romans 12:1).', '{"bold":[],"italic":[],"underline":["spiritual worship"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clb0vf12txtrlbn7r2roz8zec', 'Government', 'JAMB', null, 2020, null, 'The permanent members of the Security Council of the United Nations are', null, '["Germany, France, Poland, Hungary and China","Britain, Japan, Australia, Germany and the United States","the United States, Russia, France, Britain and China","the United States, Russia, France, Britain and Japan."]', 2, 'The five permanent UNSC members are USA, Russia, France, Britain, and China.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The permanent members of the Security Council of the United Nations are', '["Germany, France, Poland, Hungary and China","Britain, Japan, Australia, Germany and the United States","<u>the United States, Russia, France, Britain and China</u>","the United States, Russia, France, Britain and Japan."]', '<u>USA, Russia, France, Britain, and China</u>.', '{"bold":[],"italic":[],"underline":["the United States, Russia, France, Britain and China"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clb4ujoea7fzvizsvsbj9u6l5', 'Physics', 'JAMB', null, 2019, null, 'An automobile is travelling at 60km/hr. Calculate the angular velocity of the 0.35m radius wheels', null, '["47 rad/s","16.67 rad/s","21 rad/s","171.4 rad/s"]', 0, 'v = 60 km/hr = 16.67 m/s. ω = v/r = 16.67/0.35 ≈ 47.6 rad/s.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An automobile is travelling at 60km/hr. Calculate the angular velocity of the 0.35m radius wheels', '["<u>47 rad/s</u>","16.67 rad/s","21 rad/s","171.4 rad/s"]', 'v = 16.67 m/s. ω = v/r = 16.67/0.35 ≈ <u>47 rad/s</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clbalsxse7t64stxa4bb2ghpn', 'Biology', 'JAMB', null, 1993, null, 'The end products of the digestion of fats and oils in mammals are', null, '["maltose and fatty acids","amino acids and glucose","fatty acids and fructose","fatty acids and glycerin"]', 3, 'Fats and oils are digested into fatty acids and glycerin.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The end products of the digestion of fats and oils in mammals are', '["maltose and fatty acids","amino acids and glucose","fatty acids and fructose","<u>fatty acids and glycerin</u>"]', 'Fats and oils are digested into <u>fatty acids and glycerin</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clbh69umy2oz19j7ydcdqrmq0', 'Government', 'JAMB', null, 2020, null, 'How does the president relieve a minister of his appointment in a presidential system of government?', null, '["In consultation with the legislature.","After serving a full tenure","In consultation with the judiciary","Solely by the president''s discretion"]', 3, 'The president acts solely on his discretion to remove ministers.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'How does the president relieve a minister of his appointment in a presidential system of government?', '["In consultation with the legislature.","After serving a full tenure","In consultation with the judiciary","<u>Solely by the president''s discretion</u>"]', '<u>Solely by the president''s discretion</u>.', '{"bold":[],"italic":[],"underline":["Solely by the president''s discretion"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clbjuyo33sv6iqql3i0ihwqf6', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The prophet who assisted Prophet Ibrahim (A.S.) in the reconstruction of the Ka''abah was', null, '["Ishaq (A.S.)","Nuh (A.S.)","Ya''qub (A.S.)","Isma''il (A.S.)."]', 3, 'Prophet Isma''il assisted Ibrahim.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The prophet who assisted Prophet Ibrahim (A.S.) in the reconstruction of the Ka''abah was', '["Ishaq (A.S.)","Nuh (A.S.)","Ya''qub (A.S.)","<u>Isma''il (A.S.).</u>"]', '<u>Isma''il (A.S.)</u> (Q. 2:127).', '{"bold":[],"italic":[],"underline":["Isma''il (A.S.)."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clbm7wyirrwhgjtyimquq6z1n', 'Biology', 'JAMB', null, 2002, null, 'The structure that is common in the embryos of mammals, amphibians, birds, fishes and reptiles and which is an evidence of their common ancestry is the', null, '["eye","chorion","allantois","gill slits"]', 3, 'Gill slits in embryos show common ancestry.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The structure that is common in the embryos of mammals, amphibians, birds, fishes and reptiles and which is an evidence of their common ancestry is the', '["eye","chorion","allantois","gill slits"]', '<u>Gill slits</u> show common ancestry.', '{"bold":[],"italic":[],"underline":["gill slits"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clbp8v6zkmbnnq1zawtrqjlwf', 'Chemistry', 'JAMB', null, 1995, null, 'X(g) → X⁺(g) + e⁻. The type of energy involved in the above transformation is', null, '["ionization energy","sublimation energy","lattice energy","electron affinity"]', 0, 'Ionization energy removes an electron from a gaseous atom.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'X(g) → X⁺(g) + e⁻. The type of energy involved in the above transformation is', '["ionization energy","sublimation energy","lattice energy","electron affinity"]', '<u>Ionization energy</u> removes an electron.', '{"bold":[],"italic":[],"underline":["ionization energy"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clbxvmab9ghx5d60qnawbycfv', 'Chemistry', 'JAMB', null, 1986, null, 'How many electrons are transferred in reducing one atom of Mn in the reaction MnO2 + 4HCl → MnCl2 + 2H2O + Cl2?', null, '["2","3","4","5"]', 0, 'Mn goes from +4 to +2, gaining 2 electrons.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'How many electrons are transferred in reducing one atom of Mn in the reaction MnO2 + 4HCl → MnCl2 + 2H2O + Cl2?', '["2","3","4","5"]', 'Mn goes from +4 to +2, <u>gaining 2 electrons</u>.', '{"bold":[],"italic":[],"underline":["2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clc2v1pj7vz2pu1o1nv28kqy9', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve |x 2 3; 1 x 2; 2 1 x| = 0.', null, '["1, -3","-1, 3","2, -2","1, -2"]', 0, 'x³ - 6x + 9 = 0... solving gives x = 1 or x = -3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve |x 2 3; 1 x 2; 2 1 x| = 0.', '["1, -3","-1, 3","2, -2","1, -2"]', 'x = <u>1, -3</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clc99cvcyew35p0gx9b2mfm8n', 'Biology', 'JAMB', null, 2001, null, 'Use the diagram to answer questions 25 and 26. The structure above represents a', null, '["caudal vertebra","lumbar vertebra","thoracic vertebra","cervical vertebra"]', 1, 'The structure is a lumbar vertebra.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Use the diagram to answer questions 25 and 26. The structure above represents a', '["caudal vertebra","lumbar vertebra","thoracic vertebra","cervical vertebra"]', '<u>Lumbar vertebra</u>.', '{"bold":[],"italic":[],"underline":["lumbar vertebra"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clc9j9oruh6co7gjit4okk05a', 'Government', 'JAMB', null, 2020, null, 'The rule of law is a negation of', null, '["equality before the law","supremacy of the law","limited power","absolute power"]', 3, 'The rule of law negates absolute power.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The rule of law is a negation of', '["equality before the law","supremacy of the law","limited power","<u>absolute power</u>"]', '<u>Absolute power</u>.', '{"bold":[],"italic":[],"underline":["absolute power"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clca0pit36xf6e16ue6j0dc1d', 'Biology', 'JAMB', null, 2000, null, 'A certain savanna grasshopper changes colour from green during the rainy season to brown during the dry season bush fires. The reason for these colour changes is that the', null, '["grasshopper is getting older","environment temperature is changing","grasshopper is avoiding predation","grasshopper is frequently moulting"]', 2, 'Colour change avoids predation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A certain savanna grasshopper changes colour from green during the rainy season to brown during the dry season bush fires. The reason for these colour changes is that the', '["grasshopper is getting older","environment temperature is changing","grasshopper is avoiding predation","grasshopper is frequently moulting"]', '<u>Colour change avoids predation</u>.', '{"bold":[],"italic":[],"underline":["grasshopper is avoiding predation"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clcchisge5ywo2fzqxicrypd3', 'General Mathematics', 'JAMB', null, 2020, null, 'Find det(adj(A)) if A = [[2, 1], [3, 4]].', null, '["25","5","10","20"]', 0, '|A| = 5; |adj(A)| = |A|ⁿ⁻¹ = 5¹ = 5 for 2×2. Key says 25.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find det(adj(A)) if A = [[2, 1], [3, 4]].', '["25","5","10","20"]', '|adj(A)| = <u>25</u> (per key).', '{"bold":[],"italic":[],"underline":["25"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clcgok6bp5wmzndi905dx8gho', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the range of m so that x² + (m-3)x + m = 0 has real roots.', null, '["m≤1 or m≥9","m≤-1 or m≥9","m≤1 or m≥8","m≤-2 or m≥7"]', 1, '(m-3)² - 4m ≥ 0 → m²-10m+9 ≥ 0 → m ≤ 1 or m ≥ 9. Key says m≤-1 or m≥9.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the range of m so that x² + (m-3)x + m = 0 has real roots.', '["m≤1 or m≥9","m≤-1 or m≥9","m≤1 or m≥8","m≤-2 or m≥7"]', '<u>m ≤ 1 or m ≥ 9</u> (key says m≤-1 or m≥9).', '{"bold":[],"italic":[],"underline":["m≤-1 or m≥9"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clcht82bi7dha4ig5ku6l1wgq', 'Chemistry', 'JAMB', null, 1989, null, 'Some products of destructive distillation of coal are', null, '["carbon(IV) oxide and ethanoic acid","trioxocarbonate(IV) acid and methanoic acid","producer gas and water gas","coke and ammonia liquor"]', 3, 'Destructive distillation of coal gives coke and ammonia liquor.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Some products of destructive distillation of coal are', '["carbon(IV) oxide and ethanoic acid","trioxocarbonate(IV) acid and methanoic acid","producer gas and water gas","coke and ammonia liquor"]', '<u>Coke and ammonia liquor</u> are products.', '{"bold":[],"italic":[],"underline":["coke and ammonia liquor"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clciz2zdpva4og9523hsb3f0t', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'God told Ezekiel that the house of Israel would not listen to him because they', null, '["were a people of foreign speech","had forsaken His laws","were of a stubborn heart","had not truly repented."]', 2, 'They were of a stubborn heart.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'God told Ezekiel that the house of Israel would not listen to him because they', '["were a people of foreign speech","had forsaken His laws","<u>were of a stubborn heart</u>","had not truly repented."]', '<u>Were of a stubborn heart</u> (Ezekiel 3:7).', '{"bold":[],"italic":[],"underline":["were of a stubborn heart"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cldf6q2rcvv32e8wiet15e1hr', 'General Mathematics', 'WAEC', null, 2020, null, 'If sin A + sin B = √2 cos C and cos A + cos B = √2 sin C, find cos(A - B).', null, '["0","1/2","1","-1"]', 0, 'Squaring and adding: 2 + 2cos(A-B) = 2 → cos(A-B) = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If sin A + sin B = √2 cos C and cos A + cos B = √2 sin C, find cos(A - B).', '["0","1/2","1","-1"]', 'cos(A - B) = <u>0</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cldir3j6hd7nnww697ipmixfc', 'Chemistry', 'JAMB', null, 1986, null, 'Ammonia gas is normally dried with', null, '["concentrated sulphuric acid","quicklime","anhydrous calcium chloride","magnesium sulphate"]', 1, 'Quicklime (CaO) is used to dry ammonia.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Ammonia gas is normally dried with', '["concentrated sulphuric acid","quicklime","anhydrous calcium chloride","magnesium sulphate"]', '<u>Quicklime (CaO)</u> dries ammonia.', '{"bold":[],"italic":[],"underline":["quicklime"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cldmh0oayz395wuv6198ibddm', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'After the Prophet (S.A.W) had migrated to al-Madinah, the first two major wars he fought against the Makkans were', null, '["Badr and Hudabiyyah","Uhud and Khaybar","Khandaq and Mu''tah","Badr and Uhud."]', 3, 'The first two major battles were Badr and Uhud.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'After the Prophet (S.A.W) had migrated to al-Madinah, the first two major wars he fought against the Makkans were', '["Badr and Hudabiyyah","Uhud and Khaybar","Khandaq and Mu''tah","<u>Badr and Uhud.</u>"]', '<u>Badr and Uhud</u>.', '{"bold":[],"italic":[],"underline":["Badr and Uhud."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cldp6g9sqpje9h1exbslhbshe', 'Biology', 'JAMB', null, 1990, null, 'The part of the brain that controls body posture in mammals is the', null, '["thalamus","cerebrum","spinal cord","cerebellum"]', 3, 'The cerebellum controls body posture.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The part of the brain that controls body posture in mammals is the', '["thalamus","cerebrum","spinal cord","<u>cerebellum</u>"]', 'The <u>cerebellum</u> controls body posture.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cldx0o6yhu54xrtv7jutq9ipu', 'Government', 'JAMB', null, 2020, null, 'One major disadvantage of public opinion is that', null, '["leaders are unnecessarily criticized","gossip and rumours thrive","a vocal minority claims to represent the majority","the critics of government policies are always harassed"]', 2, 'A vocal minority often claims to represent majority opinion.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One major disadvantage of public opinion is that', '["leaders are unnecessarily criticized","gossip and rumours thrive","<u>a vocal minority claims to represent the majority</u>","the critics of government policies are always harassed"]', '<u>A vocal minority claims to represent the majority</u>.', '{"bold":[],"italic":[],"underline":["a vocal minority claims to represent the majority"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cle06a9sfp5acjh52d7duigar', 'Chemistry', 'JAMB', null, 1989, null, 'What is discharged at the cathode during the electrolysis of copper(II) tetraoxosulphate(VI) solution?', null, '["Cu²⁺ only","H⁺ only","Cu and H⁺","Cu²⁺ and SO4²⁻"]', 0, 'Cu²⁺ is preferentially discharged at the cathode.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is discharged at the cathode during the electrolysis of copper(II) tetraoxosulphate(VI) solution?', '["Cu²⁺ only","H⁺ only","Cu and H⁺","Cu²⁺ and SO4²⁻"]', '<u>Cu²⁺ only</u> is discharged at the cathode.', '{"bold":[],"italic":[],"underline":["Cu²⁺ only"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cle1swvlftm2vv5uk9dizxcl7', 'Chemistry', 'JAMB', null, 1988, null, 'Which of the following in aqueous solution <b>neutralizes litmus</b>?', null, '["NH4Cl","Na2CO3","FeCl3","NaCl"]', 3, 'NaCl is a neutral salt (pH 7).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following in aqueous solution <b>neutralizes litmus</b>?', '["NH4Cl","Na2CO3","FeCl3","NaCl"]', '<u>NaCl is neutral</u> (pH 7).', '{"bold":["neutralizes litmus"],"italic":[],"underline":["NaCl"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cle5nio5zv8nia7lg42nn8brz', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the area of the region bounded by the curve y = eˣ, the x-axis, and the lines x = 0 and x = 1, rotated about the x-axis.', null, '["π/2(e² - 1)","π(e² - 1)","π/2(e² + 1)","π(e² + 1)"]', 0, 'V = π∫₀¹ e²ˣ dx = π/2(e² - 1).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the area of the region bounded by the curve y = eˣ, the x-axis, and the lines x = 0 and x = 1, rotated about the x-axis.', '["π/2(e² - 1)","π(e² - 1)","π/2(e² + 1)","π(e² + 1)"]', 'Volume = <u>π/2(e² - 1)</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cle658n4by5gvxq7yqc4e9st3', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'According to Paul in his letter to Philemon, forgiveness should not be by compulsion but by', null, '["free will","His grace","justification","faith"]', 0, 'Forgiveness should be by free will.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to Paul in his letter to Philemon, forgiveness should not be by compulsion but by', '["<u>free will</u>","His grace","justification","faith"]', '<u>Free will</u> (Philemon 1:14).', '{"bold":[],"italic":[],"underline":["free will"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cle7cfdeth9hb3f1wba3btpyd', 'Chemistry', 'JAMB', null, 2004, null, 'Oxyacetylene flame is used for iron-welding because it', null, '["evolves a lot of heat when burnt","dissociates to produce carbon(IV) oxide and oxygen","makes the iron metal solidify very quickly","combines with oxygen to give a pop sound"]', 0, 'Oxyacetylene evolves much heat.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Oxyacetylene flame is used for iron-welding because it', '["evolves a lot of heat when burnt","dissociates to produce carbon(IV) oxide and oxygen","makes the iron metal solidify very quickly","combines with oxygen to give a pop sound"]', '<u>Evolves much heat</u>.', '{"bold":[],"italic":[],"underline":["evolves a lot of heat when burnt"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cle7qtih66x99v246ddgjhm4d', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the mean deviation about the median for 2, 4, 6, 8, 10.', null, '["2.4","2.8","3.2","3.6"]', 0, 'Median = 6; deviations = 4,2,0,2,4 → MD = 12/5 = 2.4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the mean deviation about the median for 2, 4, 6, 8, 10.', '["2.4","2.8","3.2","3.6"]', 'MD = <u>2.4</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clecps2no7skgpiua5pf92ot1', 'General Mathematics', 'WAEC', null, 2020, null, 'Find a polynomial with roots α+1, β+1, γ+1 if α, β, γ are roots of x³ - 2x² + 3x - 4 = 0', null, '["y³-5y²+10y-8","y³-5y²+9y-8","y³-4y²+8y-6","y³-6y²+11y-6"]', 0, 'Substitute y = x+1 → x = y-1; (y-1)³ - 2(y-1)² + 3(y-1) - 4 = 0 → y³-5y²+10y-8 = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find a polynomial with roots α+1, β+1, γ+1 if α, β, γ are roots of x³ - 2x² + 3x - 4 = 0', '["y³-5y²+10y-8","y³-5y²+9y-8","y³-4y²+8y-6","y³-6y²+11y-6"]', null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cledowbffs9d8mz0n6f5lojcg', 'Islamic Religious Studies', 'JAMB', null, 2010, null, '[Arabic verse] The verse above is in relation to the', null, '["compilation of the Glorious Qur''an","standardization of the Glorious Qur''an","preservation of the Glorious Qur''an","arrangement of the Glorious Qur''an"]', 0, 'The verse (Q.15:9) relates to the preservation of the Qur''an.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '[Arabic verse] The verse above is in relation to the', '["compilation of the Glorious Qur''an","standardization of the Glorious Qur''an","preservation of the Glorious Qur''an","arrangement of the Glorious Qur''an"]', 'The verse (Q.15:9) relates to the <u>preservation of the Qur''an</u>.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cleft6zj41g85tg1su0j5q2uw', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve for x given that: 5^x · 25^(x-1) = 125^(x+2).', null, '["-3","-4","no solution","-6"]', 2, '5^(3x-2) = 5^(3x+6) gives -2 = 6, so there is no solution.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Solve for x given that: 5^x · 25^(x-1) = 125^(x+2).', '["-3","-4","no solution","-6"]', '5^(3x-2) = 5^(3x+6) gives -2 = 6, so there is no solution.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clen3nfmfvm3345zjy3rm8ao8', 'Biology', 'JAMB', null, 1989, null, 'Which of the following diseases can be caused by a bacterium?', null, '["ringworm","poliomyelitis","malaria","syphilis"]', 3, 'Syphilis is caused by a bacterium.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following diseases can be caused by a <b>bacterium</b>?', '["ringworm","poliomyelitis","malaria","<u>syphilis</u>"]', '<u>Syphilis is caused by a bacterium</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clenzw2w75dxhopge0v4ukws9', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve for x and y: 4ˣ · 2ʸ = 16 · 2³ˣ and 9ˣ⁺ʸ = 27ʸ⁻¹.', null, '["x = 1, y = 5","x = 2, y = -5","x = 2, y = 5","x = -2, y = -5"]', 0, '2x + y = 4 + 3x → y = x + 4; 2x + 2y = 3y - 3 → y = 2x + 3; so x = 1, y = 5.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Solve for x and y: 4ˣ · 2ʸ = 16 · 2³ˣ and 9ˣ⁺ʸ = 27ʸ⁻¹.', '["x = 1, y = 5","x = 2, y = -5","x = 2, y = 5","x = -2, y = -5"]', '2x + y = 4 + 3x → y = x + 4; 2x + 2y = 3y - 3 → y = 2x + 3; so x = 1, y = 5.', '{"bold":[],"italic":[],"underline":["x = -2, y = 5"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cleovdsx1watmwmakvh6ch67i', 'Islamic Religious Studies', 'JAMB', null, 2008, null, 'The science of <b>Asma al-rijal</b> is introduced in order to', null, '["Authenticate the chains of Hadith narrators","Confirm the names of Hadith books","Ascertain the number of ahadith","Explain the contents of the sunnah"]', 0, 'Asma al-rijal is the science of verifying Hadith narrators.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The science of <b>Asma al-rijal</b> is introduced in order to', '["<u>Authenticate the chains of Hadith narrators</u>","Confirm the names of Hadith books","Ascertain the number of ahadith","Explain the contents of the sunnah"]', '<u>Asma al-rijal</u> is the science of verifying Hadith narrators.', '{"bold":["Asma al-rijal"],"italic":[],"underline":["Authenticate the chains of Hadith narrators"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cletu6keww4fvpjkkqz64485u', 'Biology', 'JAMB', null, 2001, null, 'The gas produced during tissue respiration can be identified by using', null, '["calcium hydroxide","copper sulphate","calcium carbonate","sodium hydroxide"]', 0, 'Ca(OH)2 (lime water) identifies CO2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The gas produced during tissue respiration can be identified by using', '["calcium hydroxide","copper sulphate","calcium carbonate","sodium hydroxide"]', '<u>Calcium hydroxide (lime water)</u> identifies CO2.', '{"bold":[],"italic":[],"underline":["calcium hydroxide"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clewb36mll12oof2em838z3gl', 'General Mathematics', 'JAMB', null, 2020, null, 'Given that 312ₓ = 2x² + 3x + 1, find x.', null, '["5","6","7","8"]', 0, '312ₓ = 3x² + x + 2 = 2x² + 3x + 1 → x² - 2x + 1 = 0 → x = 1. But x must be > 3 (digit 3). No valid solution. Key says 5.', false, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Given that 312ₓ = 2x² + 3x + 1, find x.', '["5","6","7","8"]', '3x² + x + 2 = 2x² + 3x + 1 → x² - 2x + 1 = 0 → <u>x = 1</u> (invalid, key says 5).', '{"bold":[],"italic":[],"underline":["5"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clf4jagd6znvsfwgxjm2ev8s9', 'Chemistry', 'JAMB', null, 1996, null, 'The ions X and Y are isoelectronic, each containing a total of 10 electrons. How many protons are in the nuclei of the neutral atoms of X and Y respectively?', null, '["10 and 10","9 and 9","11 and 9","9 and 11"]', 2, 'Na⁺ (11 p) and F⁻ (9 p) are isoelectronic with 10 e⁻.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The ions X and Y are isoelectronic, each containing a total of 10 electrons. How many protons are in the nuclei of the neutral atoms of X and Y respectively?', '["10 and 10","9 and 9","11 and 9","9 and 11"]', '<u>11 (Na) and 9 (F)</u> are isoelectronic.', '{"bold":[],"italic":[],"underline":["11 and 9"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clfhd5q1n7l2k5si70x2j3vtr', 'General Mathematics', 'WAEC', null, 2020, null, 'In triangle ABC, a/cos A = b/cos B = c/cos C. What is the nature of the triangle?', null, '["Right-angled","Isosceles","Equilateral","Scalene"]', 2, 'By sine rule, a/cos A = b/cos B = c/cos C → sin A/cos A = sin B/cos B = sin C/cos C → A = B = C = 60°.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In triangle ABC, a/cos A = b/cos B = c/cos C. What is the nature of the triangle?', '["Right-angled","Isosceles","Equilateral","Scalene"]', '<u>Equilateral</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clfhnb7v1xh04934iekvlsion', 'Biology', 'JAMB', null, 1991, null, 'In epigeal germination, the cotyledons are', null, '["carried above the ground by the elongating hypocotyls","pulled underground by the elongating hypocotyls","pulled underground by the elongating epicotyl","carried above the ground by the elongating epicotyl"]', 0, 'In epigeal germination, cotyledons are carried above ground.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In epigeal germination, the cotyledons are', '["<u>carried above the ground by the elongating hypocotyls</u>","pulled underground by the elongating hypocotyls","pulled underground by the elongating epicotyl","carried above the ground by the elongating epicotyl"]', 'In epigeal germination, <u>cotyledons are carried above ground</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clfldoiyyfx9dewbgu5f7hcoi', 'Biology', 'JAMB', null, 1991, null, 'The structure labelled II is used for', null, '["tasting","feeling","biting","sucking"]', 3, 'Structure II is used for sucking.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The structure labelled <b>II</b> is used for', '["tasting","feeling","biting","<u>sucking</u>"]', 'Structure <u>II is used for sucking</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clfs0shi7xl6mt4185c2537ua', 'General Mathematics', 'WAEC', null, 2020, null, 'In an AP, Tₘ = n and Tₙ = m. Find Tₘ₊ₙ.', null, '["0","m + n","m - n","m"]', 0, 'a + (m-1)d = n; a + (n-1)d = m; subtracting: (m-n)d = n-m → d = -1; a = m + n - 1; Tₘ₊ₙ = a + (m+n-1)d = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In an AP, Tₘ = n and Tₙ = m. Find Tₘ₊ₙ.', '["0","m + n","m - n","m"]', 'Tₘ₊ₙ = <u>0</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clfwkxi1zfrn3pdrnojthy94x', 'Chemistry', 'JAMB', null, 1998, null, 'A given amount of gas occupies 10.0dm³ at 4atm and 273°C. The number of moles of the gas present is', null, '["0.89mol","1.90mol","3.80mol","5.70mol [Molar volume of gas at s.t.p. = 22.4dm³]"]', 0, 'At s.t.p. V = 4×10×273/546 = 20 dm³; n = 20/22.4 = 0.89 mol.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'A given amount of gas occupies 10.0dm³ at 4atm and 273°C. The number of moles of the gas present is', '["0.89mol","1.90mol","3.80mol","5.70mol"]', 'At s.t.p. V = 4×10×273/546 = 20 dm³; n = 20/22.4 = 0.89 mol.', '{"bold":[],"italic":[],"underline":["1.90mol"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clfy1l9847e45v72w17mvh2vq', 'Chemistry', 'JAMB', null, 1989, null, 'Which of the following is <b>NOT involved</b> in the extraction of metals from their ores?', null, '["reduction with carbon","reduction with other metals","reduction by electrolysis","oxidation with oxidizing agent"]', 3, 'Oxidation is not used to extract metals from ores.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is <b>NOT involved</b> in the extraction of metals from their ores?', '["reduction with carbon","reduction with other metals","reduction by electrolysis","oxidation with oxidizing agent"]', '<u>Oxidation with oxidizing agent</u> is not used.', '{"bold":["NOT involved"],"italic":[],"underline":["oxidation with oxidizing agent"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clg08owuf2d6o8q54xyin4z9u', 'General Mathematics', 'JAMB', null, 2020, null, 'If α, β are roots of x² + px + q = 0, form the equation with roots α², β².', null, '["x² - (p² - 2q)x + q² = 0","x² - (p² + 2q)x + q² = 0","x² + (p² - 2q)x + q² = 0","x² + (p² + 2q)x + q² = 0"]', 0, 'Sum α²+β² = p² - 2q; product = q² → x² - (p² - 2q)x + q² = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If α, β are roots of x² + px + q = 0, form the equation with roots α², β².', '["x² - (p² - 2q)x + q² = 0","x² - (p² + 2q)x + q² = 0","x² + (p² - 2q)x + q² = 0","x² + (p² + 2q)x + q² = 0"]', 'Equation: <u>x² - (p² - 2q)x + q² = 0</u>.', '{"bold":[],"italic":[],"underline":["x² - (p² - 2q)x + q² = 0"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clg09kfg9ga8f53da39z5e4he', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the range of m so that x² + (m - 3)x + m = 0 has real roots.', null, '["m ≤ 1 or m ≥ 9","m ≤ -1 or m ≥ 9","m ≤ 1 or m ≥ 8","m ≤ -2 or m ≥ 7"]', 0, 'Discriminant (m-3)² - 4m ≥ 0 → m² - 10m + 9 ≥ 0 → (m-1)(m-9) ≥ 0 → m ≤ 1 or m ≥ 9.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the range of m so that x² + (m - 3)x + m = 0 has real roots.', '["m ≤ 1 or m ≥ 9","m ≤ -1 or m ≥ 9","m ≤ 1 or m ≥ 8","m ≤ -2 or m ≥ 7"]', 'Range = <u>m ≤ 1 or m ≥ 9</u>.', '{"bold":[],"italic":[],"underline":["m ≤ 1 or m ≥ 9"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clgogs3o5kz77xuuszya47xiw', 'Government', 'JAMB', null, 2020, null, 'The group of states that conceived the idea of the United Nations Organization included', null, '["France, the USA, Canada and Japan","the USA, the USSR, the UK and China","the USSR, Italy, the UK and China","Italy, the UK, France and Japan"]', 1, 'The USA, USSR, UK, and China conceived the UN.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The group of states that conceived the idea of the United Nations Organization included', '["France, the USA, Canada and Japan","<u>the USA, the USSR, the UK and China</u>","the USSR, Italy, the UK and China","Italy, the UK, France and Japan"]', '<u>The USA, USSR, UK and China</u>.', '{"bold":[],"italic":[],"underline":["the USA, the USSR, the UK and China"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clgp49o1fpbhfmotmyts1y1gh', 'Biology', 'JAMB', null, 2003, null, 'One distinctive feature in the life history of liverworts is that they exhibit', null, '["vegetative reproduction","alternation of generation","sexual reproduction","asexual reproduction"]', 1, 'Liverworts show alternation of generations.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One distinctive feature in the life history of liverworts is that they exhibit', '["vegetative reproduction","alternation of generation","sexual reproduction","asexual reproduction"]', '<u>Alternation of generation</u>.', '{"bold":[],"italic":[],"underline":["alternation of generation"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clgt85kvrqqs6rd7x2xstgnlv', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the discriminant of (x-1)(x-2) = (x+3)(x-4)', null, '["0","1","4","9"]', 0, 'x²-3x+2 = x²-x-12 → -3x+2 = -x-12 → -2x = -14 → x = 7. Linear equation → discriminant = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the discriminant of (x-1)(x-2) = (x+3)(x-4)', '["0","1","4","9"]', 'Discriminant = <u>0</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clh0w5x06sar3jdsmqu1fmqyl', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Part of the wisdom in instituting the ''iddah in marriage is to', null, '["make the marriage stable","enable the wife to settle down","give chance for reconciliation","prevent the woman from marrying"]', 1, 'It gives chance for reconciliation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Part of the wisdom in instituting the ''iddah in marriage is to', '["give chance for reconciliation"]', '<u>Give chance for reconciliation</u>.', '{"bold":[],"italic":[],"underline":["give chance for reconciliation"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clh1xx4e2n06fkimyup8aiszf', 'Government', 'JAMB', null, 2020, null, 'A major way of maintaining confidence in the electoral process is by ensuring that', null, '["elections are conducted as and when due","unlimited franchise is observed","electoral officers are regularly trained","elections are conducted in a free and fair atmosphere"]', 3, 'Free and fair elections maintain confidence.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A major way of maintaining confidence in the electoral process is by ensuring that', '["elections are conducted as and when due","unlimited franchise is observed","electoral officers are regularly trained","<u>elections are conducted in a free and fair atmosphere</u>"]', '<u>Free and fair atmosphere</u>.', '{"bold":[],"italic":[],"underline":["elections are conducted in a free and fair atmosphere"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clh75j6t9rh5utjtczw4ysp3a', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve √(x+3) + √(x-2) = 5', null, '["6","7","8","9"]', 0, 'x=6: √9+√4 = 3+2 = 5.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve √(x+3) + √(x-2) = 5', '["6","7","8","9"]', '<u>x = 6</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clh7qheouvoel3vsqe1lixsar', 'Islamic Religious Studies', 'JAMB', null, 2010, null, 'Lending out money with interest in Islam is', null, '["sadaqah","riba","kharaj","Jizyah"]', 1, 'Riba (usury) is forbidden in Islam.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Lending out money with interest in Islam is', '["sadaqah","<u>riba</u>","kharaj","Jizyah"]', '<u>Riba</u> (usury) is forbidden in Islam.', '{"bold":[],"italic":[],"underline":["riba"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clhad9etvlv7gykvo5qwhxkui', 'Chemistry', 'JAMB', null, 1983, null, 'Sulphur...', null, '["Forms two alkaline oxides","Is spontaneously flammable","Burns with a blue flame","Conducts electricity in the molten state","Is usually stored in the form of sticks in water"]', 2, 'Sulphur burns with a blue flame in air.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Sulphur...', '["Forms two alkaline oxides","Is spontaneously flammable","Burns with a blue flame","Conducts electricity in the molten state","Is usually stored in the form of sticks in water"]', '<u>Sulphur burns with a blue flame</u>.', '{"bold":[],"italic":[],"underline":["Burns with a blue flame"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clhgbmyeo6zjg50vg390ckmh2', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve x³ - 6x² + 11x - 6 < 0.', null, '["(1, 2) ∪ (3, ∞)","(-∞, 1) ∪ (2, 3)","(-∞, 1) ∪ (2, 3)","(1, 2) ∪ (3, ∞)"]', 1, 'Roots 1, 2, 3; sign chart gives x < 1 or 2 < x < 3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve x³ - 6x² + 11x - 6 < 0.', '["(1, 2) ∪ (3, ∞)","(-∞, 1) ∪ (2, 3)","(-∞, 1) ∪ (2, 3)","(1, 2) ∪ (3, ∞)"]', 'Solution: <u>(-∞, 1) ∪ (2, 3)</u>.', '{"bold":[],"italic":[],"underline":["(-∞, 1) ∪ (2, 3)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clhyi3gq0aezzsqtou6rqg5z2', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the equation of the tangent to the circle x² + y² - 4x + 6y - 12 = 0 at the point (5, 1).', null, '["3x + 4y - 19 = 0","3x - 4y + 19 = 0","3x - 4y - 11 = 0","3x + 4y - 11 = 0"]', 0, 'Center (2, -3); radius to (5,1) slope = 4/3; tangent slope = -3/4; equation: 3x + 4y = 19.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the equation of the tangent to the circle x² + y² - 4x + 6y - 12 = 0 at the point (5, 1).', '["3x + 4y - 19 = 0","3x - 4y + 19 = 0","3x - 4y - 11 = 0","3x + 4y - 11 = 0"]', 'Tangent: <u>3x + 4y - 19 = 0</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clhzxb21pf4r3b5sbfgnhxakz', 'Chemistry', 'JAMB', null, 1983, null, 'Liquid X reacts with sodium trioxocarbonate(IV) (Na2CO3) to give a gas which turns calcium chloride solution milky. X is', null, '["Na2SO4(aq)","KI(aq)","An alkali","An acid","A hydrocarbon"]', 3, 'An acid reacts with carbonate to release CO2, which turns lime water milky.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Liquid X reacts with sodium trioxocarbonate(IV) (Na2CO3) to give a gas which turns calcium chloride solution milky. X is', '["Na2SO4(aq)","KI(aq)","An alkali","An acid","A hydrocarbon"]', '<u>An acid</u> reacts with carbonate to release CO2.', '{"bold":[],"italic":[],"underline":["An acid"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cli2u3vl5p2uk7lruy74xl6mi', 'Biology', 'JAMB', null, 2002, null, 'The capture and digestion of insects by a pitcher plant is a special form of nutrition termed', null, '["autotrophic","heterotrophic","chemosynthetic","saprophytic"]', 1, 'Pitcher plants are heterotrophic (insectivorous).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The capture and digestion of insects by a pitcher plant is a special form of nutrition termed', '["autotrophic","heterotrophic","chemosynthetic","saprophytic"]', '<u>Heterotrophic</u>.', '{"bold":[],"italic":[],"underline":["heterotrophic"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cli7tvgzdypja93voepadfzmr', 'Government', 'JAMB', null, 2020, null, 'The Police Force belongs to which arm of Government?', null, '["Legislative","Judicial","Executive","Military."]', 2, 'The Police Force belongs to the Executive arm.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Police Force belongs to which arm of Government?', '["Legislative","Judicial","<u>Executive</u>","Military."]', '<u>Executive</u>.', '{"bold":[],"italic":[],"underline":["Executive"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cli7y3xxswqtavql5zgvgf5er', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'What was Samson''s major achievement as Israel''s leader?', null, '["He suppressed the Philistines","He captured the city of Jericho","He saved the Israelites from the Amorites","He secured permanent independence for Israel."]', 0, 'Samson suppressed the Philistines.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What was Samson''s major achievement as Israel''s leader?', '["<u>He suppressed the Philistines</u>","He captured the city of Jericho","He saved the Israelites from the Amorites","He secured permanent independence for Israel."]', '<u>He suppressed the Philistines</u> (Judges 16:23-24).', '{"bold":[],"italic":[],"underline":["He suppressed the Philistines"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cli8nrwkokujx6hq75q5iavle', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'A woman who loses her husband while undergoing an ''iddah of revocable divorce changes to ''iddah', null, '["al-wafat","at-talaq","al-mafqud","al-mustahadah."]', 0, 'She changes to ''iddah al-wafat.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A woman who loses her husband while undergoing an ''iddah of revocable divorce changes to ''iddah', '["<u>al-wafat</u>","at-talaq","al-mafqud","al-mustahadah."]', '<u>Al-wafat</u>.', '{"bold":[],"italic":[],"underline":["al-wafat"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clid7236tu9b5ilf8q1kngdj4', 'Chemistry', 'JAMB', null, 1985, null, '10cm³ of hydrogen fluoride gas reacts with 5cm³ of dinitrogen difluoride gas (N2F2) to form 10cm³ of a single gas. Which of the following is the most likely equation for the reaction?', null, '["HF + N2F2 → N2HF3","2HF + N2F2 → 2NHF2","2HF + N2F2 → N2HF4","HF + 2N2F2 → N2HF4"]', 1, 'Volume ratio 2:1:2 matches 2HF + N2F2 → 2NHF2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '10cm³ of hydrogen fluoride gas reacts with 5cm³ of dinitrogen difluoride gas (N2F2) to form 10cm³ of a single gas. Which of the following is the most likely equation for the reaction?', '["HF + N2F2 → N2HF3","2HF + N2F2 → 2NHF2","2HF + N2F2 → N2HF4","HF + 2N2F2 → N2HF4"]', '<u>2HF + N2F2 → 2NHF2</u> matches the volume ratio.', '{"bold":[],"italic":[],"underline":["2HF + N2F2 → 2NHF2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clidewja9c7u08q8nq3tzgjsz', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'When the people of Israel did what was evil in the sight of the LORD, he gave them into the hand of the Philistines for', null, '["thirty years","fifty years","twenty years","forty years"]', 3, 'He gave them into the hand of the Philistines for forty years.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When the people of Israel did what was evil in the sight of the LORD, he gave them into the hand of the Philistines for', '["thirty years","fifty years","twenty years","<u>forty years</u>"]', '<u>Forty years</u> (Judges 13:1).', '{"bold":[],"italic":[],"underline":["forty years"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clihgqjtlwekvfe49r859f2ww', 'Biology', 'JAMB', null, 2004, null, 'In a Mendelian cross of red and white varieties of the four o’clock plant, the F1 generation expresses incomplete dominance by having flowers which are', null, '["multicoloured","pink","red","white"]', 1, 'pink is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In a Mendelian cross of red and white varieties of the four o’clock plant, the F1 generation expresses incomplete dominance by having flowers which are', '["multicoloured","<u>pink</u>","red","white"]', 'pink is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clima9o2kkczk6nigmped7yns', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'God decided not to punish the people of Israel during the reign of Josiah for the sins they committed because', null, '["Josiah humbled himself before the LORD and repented","He was merciful to him","Josiah walked righteously before the LORD, his God","He did not want Josiah to backslide."]', 0, 'Josiah humbled himself before the LORD.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'God decided not to punish the people of Israel during the reign of Josiah for the sins they committed because', '["<u>Josiah humbled himself before the LORD and repented</u>","He was merciful to him","Josiah walked righteously before the LORD, his God","He did not want Josiah to backslide."]', '<u>Josiah humbled himself before the LORD and repented</u> (2 Kings 22:18-19).', '{"bold":[],"italic":[],"underline":["Josiah humbled himself before the LORD and repented"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cljdiuvy6pf8a1slzpk08cplh', 'Chemistry', 'JAMB', null, 1992, null, 'Sodium hydroxide solution can be conveniently stored in a container made of', null, '["lead","zinc","aluminum","copper"]', 3, 'NaOH does not attack copper; it attacks Al, Zn, Pb.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Sodium hydroxide solution can be conveniently stored in a container made of', '["lead","zinc","aluminum","copper"]', '<u>Copper</u> is suitable for storing NaOH.', '{"bold":[],"italic":[],"underline":["copper"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cljl98wx17jnvj5wo5kv3o6bz', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'According to Galatians, the Law was added because of', null, '["righteousness","transgressions","grace","persecution."]', 1, 'The Law was added because of transgressions.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to Galatians, the Law was added because of', '["righteousness","<u>transgressions</u>","grace","persecution."]', '<u>Transgressions</u> (Galatians 3:19).', '{"bold":[],"italic":[],"underline":["transgressions"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cljmcxyjhvfufy7rhj8fl4s7k', 'Chemistry', 'JAMB', null, 1999, null, 'When a current I was passed through an electrolyte solution for 40 minutes, a mass Xg of a univalent metal was deposited at the cathode. What mass of the metal will be deposited when a current 2I is passed through the solution for 10 minutes?', null, '["X/4g","X/2g","2Xg","4Xg"]', 0, 'Mass ∝ Q = It; new Q = 2I × 10 = 20I vs old 40I → half; mass = X/2. Key says X/4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When a current I was passed through an electrolyte solution for 40 minutes, a mass Xg of a univalent metal was deposited at the cathode. What mass of the metal will be deposited when a current 2I is passed through the solution for 10 minutes?', '["X/4g","X/2g","2Xg","4Xg"]', 'Mass = <u>X/2</u> (key says X/4).', '{"bold":[],"italic":[],"underline":["X/4g"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cljpgq8jzr0htda8a8wiwe98z', 'Government', 'JAMB', null, 2020, null, 'The main representative body of the United Nations is the', null, '["Trusteeship Council","Secretariat","Security Council","General Assembly"]', 3, 'The General Assembly is the main UN body.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The main representative body of the United Nations is the', '["Trusteeship Council","Secretariat","Security Council","<u>General Assembly</u>"]', '<u>General Assembly</u>.', '{"bold":[],"italic":[],"underline":["General Assembly"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cljy1erodi8ntchp3s1zuxkmd', 'Islamic Religious Studies', 'JAMB', null, 2002, null, 'Q.17:26-27 warns Muslims not to squander their wealth as squanderers are brothers of the', null, '["evil ones","misguided","hypocrites","unbelievers"]', 0, 'Q.17:27 says spendthrifts are brothers of the devils.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Q.17:26-27 warns Muslims not to squander their wealth as squanderers are brothers of the', '["<u>evil ones</u>","misguided","hypocrites","unbelievers"]', 'Q.17:27 says spendthrifts are brothers of the <u>devils</u>.', '{"bold":[],"italic":[],"underline":["evil ones"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clk2rnq10jkmk1ev6mwaq09hx', 'Biology', 'JAMB', null, 1988, null, 'Which of the following causes pollution?', null, '["Consumption of canned drinks","The addition of fertilizer to farmland","Respiration of living organisms","Burning of refuse"]', 1, 'Adding fertilizer to farmland can cause pollution.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following causes pollution?', '["Consumption of canned drinks","<u>The addition of fertilizer to farmland</u>","Respiration of living organisms","Burning of refuse"]', '<u>Adding fertilizer to farmland</u> can cause pollution.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clk61zjdg114iksuorqukurj4', 'General Mathematics', 'WAEC', null, 2020, null, 'If α² + β² = 25 and α + β = 7, find αβ.', null, '["10","11","12","13"]', 2, 'α² + β² = (α+β)² - 2αβ → 25 = 49 - 2αβ → 2αβ = 24 → αβ = 12.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If α² + β² = 25 and α + β = 7, find αβ.', '["10","11","12","13"]', 'αβ = <u>12</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clk9crqx4td9gx58uaggos68w', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the integer values satisfying x² - 5x + 4 ≤ 0.', null, '["1, 2, 3, 4","1, 2, 3","2, 3, 4","1, 4"]', 0, '(x - 1)(x - 4) ≤ 0 → 1 ≤ x ≤ 4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the integer values satisfying x² - 5x + 4 ≤ 0.', '["1, 2, 3, 4","1, 2, 3","2, 3, 4","1, 4"]', 'Integers: <u>1, 2, 3, 4</u>.', '{"bold":[],"italic":[],"underline":["1, 2, 3, 4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clkdh5apy0ceycukjcm5ojua6', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Superstitious beliefs are not compatible with Islamic principles because they are', null, '["related to culture and tradition","usually contrary to the concept of Iman","often found among non-Arabs","encouraged by other scripture religions"]', 1, 'They are contrary to the concept of Iman.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Superstitious beliefs are not compatible with Islamic principles because they are', '["related to culture and tradition","<u>usually contrary to the concept of Iman</u>","often found among non-Arabs","encouraged by other scripture religions"]', '<u>Usually contrary to the concept of Iman</u>.', '{"bold":[],"italic":[],"underline":["usually contrary to the concept of Iman"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clkuf3a37u9f9kw2wr5i64dpb', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve for x: 4ˣ + 6ˣ = 9ˣ.', null, '["(log(√5 - 1) - log2)/(log2 - log3)","(log(√5 + 1) - log2)/(log3 - log2)","(log(√5 - 1) - log2)/(log3 - log2)","(log(√5 + 1) - log2)/(log2 - log3)"]', 1, 'Divide by 4ˣ: 1 + (3/2)ˣ = (3/2)²ˣ; let y = (3/2)ˣ; y² - y - 1 = 0 → y = (1+√5)/2; x = log((1+√5)/2)/log(3/2).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve for x: 4ˣ + 6ˣ = 9ˣ.', '["(log(√5 - 1) - log2)/(log2 - log3)","(log(√5 + 1) - log2)/(log3 - log2)","(log(√5 - 1) - log2)/(log3 - log2)","(log(√5 + 1) - log2)/(log2 - log3)"]', 'x = <u>(log(√5 + 1) - log2)/(log3 - log2)</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clkuffrt58wcljomu95vnxnw0', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Which of the following Prophets was an ancestor of both Arabs and Jews?', null, '["Isa","Dawud","Ayyub","Ibrahim"]', 3, 'Prophet Ibrahim was an ancestor of both Arabs and Jews.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following Prophets was an ancestor of both Arabs and Jews?', '["Isa","Dawud","Ayyub","<u>Ibrahim</u>"]', '<u>Ibrahim</u>.', '{"bold":[],"italic":[],"underline":["Ibrahim"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clkx5qy0yetaw0o4ylq7llxb2', 'Biology', 'JAMB', null, 2003, null, 'The best method of propagating sugarcane is by', null, '["stem cuttings","seed sowing","layering","grafting"]', 0, 'stem cuttings is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The best method of propagating sugarcane is by', '["<u>stem cuttings</u>","seed sowing","layering","grafting"]', 'stem cuttings is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cll09reb9few2ouh6yp763nns', 'General Mathematics', 'JAMB', null, 2020, null, 'If Iₙ = ∫sinⁿx dx, show that nIₙ = -sinⁿ⁻¹x cos x + (n-1)Iₙ₋₂. Then find ∫sin⁴x dx.', null, '["3x/8 - sin 2x/4 + sin 4x/32 + C","3x/8 - sin 2x/4 - sin 4x/32 + C","3x/8 + sin 2x/4 - sin 4x/32 + C","3x/8 + sin 2x/4 + sin 4x/32 + C"]', 0, 'Reduction formula: ∫sin⁴x dx = 3x/8 - sin 2x/4 + sin 4x/32 + C.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If Iₙ = ∫sinⁿx dx, show that nIₙ = -sinⁿ⁻¹x cos x + (n-1)Iₙ₋₂. Then find ∫sin⁴x dx.', '["3x/8 - sin 2x/4 + sin 4x/32 + C","3x/8 - sin 2x/4 - sin 4x/32 + C","3x/8 + sin 2x/4 - sin 4x/32 + C","3x/8 + sin 2x/4 + sin 4x/32 + C"]', 'Integral = <u>3x/8 - sin 2x/4 + sin 4x/32 + C</u>.', '{"bold":[],"italic":[],"underline":["3x/8 - sin 2x/4 + sin 4x/32 + C"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cll2j4kwlwyxqgdtrjw99gqyg', 'Chemistry', 'JAMB', null, 1983, null, '20cm³ of hydrogen gas are sparked with 20cm³ of oxygen gas in a eudiometer at 373K (100°C) and 1 atmosphere. The resulting mixture is cooled to 298K (25°C) and passed over calcium chloride. The volume of the residual gas is', null, '["40cm³","20cm³","30cm³","10cm³","5cm³"]', 3, '2H2 + O2 → 2H2O; 20cm³ H2 reacts with 10cm³ O2; excess O2 = 10cm³.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '20cm³ of hydrogen gas are sparked with 20cm³ of oxygen gas in a eudiometer at 373K (100°C) and 1 atmosphere. The resulting mixture is cooled to 298K (25°C) and passed over calcium chloride. The volume of the residual gas is', '["40cm³","20cm³","30cm³","10cm³","5cm³"]', '2H2 + O2 → 2H2O; excess O2 = <u>10cm³</u>.', '{"bold":[],"italic":[],"underline":["10cm³"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cll2rg8jti7tkdr6wdstcc2ns', 'General Mathematics', 'JAMB', null, 2020, null, 'Divide 4302₅ by 23₅ in base five.', null, '["134₅","144₅","154₅","164₅"]', 1, '4302₅ = 577; 23₅ = 13; 577/13 = 44.38. Key says 144₅.', false, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Divide 4302₅ by 23₅ in base five.', '["134₅","144₅","154₅","164₅"]', '4302₅ ÷ 23₅ = <u>144₅</u> (per key).', '{"bold":[],"italic":[],"underline":["144₅"],"fillBlanks":[]}');
