insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clls2fkehswexub1xvmlu9so6', 'General Mathematics', 'JAMB', null, 2020, null, 'What is the trace of [[1, 2, 3], [4, 5, 6], [7, 8, 9]]?', null, '["15","12","18","21"]', 0, 'Trace = 1 + 5 + 9 = 15.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is the trace of [[1, 2, 3], [4, 5, 6], [7, 8, 9]]?', '["15","12","18","21"]', 'Trace = <u>15</u>.', '{"bold":[],"italic":[],"underline":["15"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clm1143qkxissiegr41ebklpk', 'Biology', 'JAMB', null, 1997, null, 'Virus differ from all forms of life because they A have a thick cell wall', null, '["have a thick cell wall","feed on waste products of other organisms","cause infectious diseases","require other living cells to multiply"]', 3, 'require other living cells to multiply is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Virus differ from all forms of life because they A have a thick cell wall', '["have a thick cell wall","feed on waste products of other organisms","cause infectious diseases","<u>require other living cells to multiply</u>"]', 'require other living cells to multiply is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clm3f728s2fflysix9cfx7he6', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'After Jonah had been thrown into the sea and the sea ceased from its raging, the men with him', null, '["praised the LORD for saving them","feared the LORD, offered sacrifice and made vows","prayed to God for forgiveness","rowed hard to bring the ship back to land."]', 1, 'They feared the LORD, offered sacrifice, and made vows.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'After Jonah had been thrown into the sea and the sea ceased from its raging, the men with him', '["praised the LORD for saving them","<u>feared the LORD, offered sacrifice and made vows</u>","prayed to God for forgiveness","rowed hard to bring the ship back to land."]', '<u>Feared the LORD, offered sacrifice and made vows</u> (Jonah 1:15-16).', '{"bold":[],"italic":[],"underline":["feared the LORD, offered sacrifice and made vows"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clm6t2awflnccede1nsmyjhia', 'Biology', 'JAMB', null, 2001, null, 'Blood vessels usually pass through the structure labelled', null, '["III","II","V","IV"]', 2, 'Part V is the neural canal (blood vessels pass through).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Blood vessels usually pass through the structure labelled', '["III","II","V","IV"]', '<u>Part V (neural canal)</u>.', '{"bold":[],"italic":[],"underline":["V"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clm7ho5ezn86fynhho4xr9jsv', 'General Mathematics', 'WAEC', null, 2020, null, 'The equation of a curve is y = x³ - 3x² + 3x - 1. Find the point on the curve where the tangent is parallel to the x-axis.', null, '["(1, 0)","(1, -1)","(1, 1)","(2, 1)"]', 0, 'y'' = 3(x-1)² = 0 → x = 1; y = 0. Point (1, 0).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The equation of a curve is y = x³ - 3x² + 3x - 1. Find the point on the curve where the tangent is parallel to the x-axis.', '["(1, 0)","(1, -1)","(1, 1)","(2, 1)"]', 'Point = <u>(1, 0)</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clmd4fpaaeishc08d6t649lj7', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'What was the offence of Ananias and Sapphira?', null, '["They kept all the proceeds of the sold land","They kept some of the proceeds of the sold land","They did not sell the land as earlier promised","They sold another person''s land."]', 1, 'They kept back some of the proceeds.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What was the offence of Ananias and Sapphira?', '["They kept all the proceeds of the sold land","<u>They kept some of the proceeds of the sold land</u>","They did not sell the land as earlier promised","They sold another person''s land."]', '<u>They kept some of the proceeds of the sold land</u> (Acts 5:1-11).', '{"bold":[],"italic":[],"underline":["They kept some of the proceeds of the sold land"],"fillBlanks":[]}');
