insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clmo4kwuaqetxuez05gg1xzlw', 'Biology', 'JAMB', null, 2003, null, 'An argument against <b>Lamarck''s theory</b> of evolution is that', null, '["acquired traits cannot be passed onto the offspring","disuse of body part cannot weaken the part","disused part is dropped off in the offspring","traits cannot be acquired through constant use of body parts"]', 0, 'Acquired traits are not inherited.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An argument against <b>Lamarck''s theory</b> of evolution is that', '["acquired traits cannot be passed onto the offspring","disuse of body part cannot weaken the part","disused part is dropped off in the offspring","traits cannot be acquired through constant use of body parts"]', '<u>Acquired traits cannot be passed to offspring</u>.', '{"bold":["Lamarck''s theory"],"italic":[],"underline":["acquired traits cannot be passed onto the offspring"],"fillBlanks":[]}');
