insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cln1i11b6q6v6ddgjasjtzeej', 'Chemistry', 'JAMB', null, 1998, null, 'The reactions represented by the equations above demonstrate the', null, '["basic properties of ammonia","acidic properties of ammonia","reducing properties of ammonia","oxidizing properties of ammonia"]', 2, 'NH3 reduces CuO to Cu (reducing properties).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The reactions represented by the equations above demonstrate the', '["basic properties of ammonia","acidic properties of ammonia","reducing properties of ammonia","oxidizing properties of ammonia"]', '<u>Reducing properties of ammonia</u>.', '{"bold":[],"italic":[],"underline":["reducing properties of ammonia"],"fillBlanks":[]}');
