insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clomgvat9e0ej0plw028q12d5', 'Chemistry', 'JAMB', null, 1996, null, 'Which of the following are the products of the reaction between CH3COOH and Cl2 in sunlight?', null, '["ClCH2COOH + HCl","CH3COCl + HOCl","CH3COOCl + HCl","CH3COCl + H2O"]', 0, 'CH3COOH + Cl2 → ClCH2COOH + HCl.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following are the products of the reaction between CH3COOH and Cl2 in sunlight?', '["ClCH2COOH + HCl","CH3COCl + HOCl","CH3COOCl + HCl","CH3COCl + H2O"]', '<u>ClCH2COOH + HCl</u>.', '{"bold":[],"italic":[],"underline":["ClCH2COOH + HCl"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cloqjnmnsij67iydvqzv6r68k', 'Chemistry', 'JAMB', null, 1991, null, 'In two separate experiments 0.36g and 0.71g of chlorine combine with a metal X to give Y and Z respectively. An analysis showed that Y and Z contain 0.20g and 0.40g of X respectively. The data above represents the law of', null, '["multiple proportion","conservation of mass","constant composition","reciprocal proportion"]', 0, 'Two compounds of the same elements show the law of multiple proportions.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In two separate experiments 0.36g and 0.71g of chlorine combine with a metal X to give Y and Z respectively. An analysis showed that Y and Z contain 0.20g and 0.40g of X respectively. The data above represents the law of', '["multiple proportion","conservation of mass","constant composition","reciprocal proportion"]', '<u>Law of multiple proportions</u>.', '{"bold":[],"italic":[],"underline":["multiple proportion"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clousj73ksn6f575efzl8n33u', 'General Mathematics', 'WAEC', null, 2020, null, 'The line y = x + 2 meets the circle x² + y² = 4 at points A and B. Find the equation of the circle on AB as diameter.', null, '["x² + y² + 2x - 2y = 0","x² + y² - 2x + 2y = 0","x² + y² + 2x + 2y = 0","x² + y² - 2x - 2y = 0"]', 0, 'A(-2,0), B(0,2); center (-1,1); radius √2; equation: x² + y² + 2x - 2y = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The line y = x + 2 meets the circle x² + y² = 4 at points A and B. Find the equation of the circle on AB as diameter.', '["x² + y² + 2x - 2y = 0","x² + y² - 2x + 2y = 0","x² + y² + 2x + 2y = 0","x² + y² - 2x - 2y = 0"]', 'Equation: <u>x² + y² + 2x - 2y = 0</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clov4ywg21qrcrotmt4wgqqg0', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve {x + 2y = 5; 3x + 4y = 11} using matrix inverse.', null, '["(1, 2)","(2, 1.5)","(3, 1)","(1, 2.5)"]', 0, 'x = 1, y = 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve {x + 2y = 5; 3x + 4y = 11} using matrix inverse.', '["(1, 2)","(2, 1.5)","(3, 1)","(1, 2.5)"]', 'Solution: <u>(1, 2)</u>.', '{"bold":[],"italic":[],"underline":["(1, 2)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cloznuyuabdxsxsbcuh1pkkay', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve: x⁴ - 5x² + 4 = 0', null, '["±1, ±2","±1, ±3","±2, ±3","±1, ±4"]', 0, 'y² - 5y + 4 = 0 → y = 1 or 4 → x = ±1, ±2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve: x⁴ - 5x² + 4 = 0', '["±1, ±2","±1, ±3","±2, ±3","±1, ±4"]', '<u>x = ±1, ±2</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clpbea5v8tizh0i0g1t3kgeoq', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'On the Day of Judgement, man will be questioned about the joy he indulged in. This is contained in Surah', null, '["al-Takathur","al-Asr","al-Qari''ah","al-Ma''un"]', 1, 'It is contained in Surat al-Asr.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'On the Day of Judgement, man will be questioned about the joy he indulged in. This is contained in Surah', '["al-Takathur","<u>al-Asr</u>","al-Qari''ah","al-Ma''un"]', '<u>Al-Asr</u>.', '{"bold":[],"italic":[],"underline":["al-Asr"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clpea6krncu3375q6kp8rfya8', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'According to the Prophet (S.A.W), he who betrays trust is regarded as having', null, '["faith but no religion","religion but no faith","no hope in the Hereafter","neither faith nor religion."]', 3, 'He has neither faith nor religion.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to the Prophet (S.A.W), he who betrays trust is regarded as having', '["faith but no religion","religion but no faith","no hope in the Hereafter","<u>neither faith nor religion.</u>"]', '<u>Neither faith nor religion</u>.', '{"bold":[],"italic":[],"underline":["neither faith nor religion."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clpheuoeiuo1ld5cxooy3akc4', 'Biology', 'JAMB', null, 2001, null, 'The part labelled IV is the', null, '["albumen","germinal disc","sturdy","stunted"]', 1, 'Part IV is the germinal disc.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The part labelled IV is the', '["albumen","germinal disc","sturdy","stunted"]', '<u>Part IV is the germinal disc</u>.', '{"bold":[],"italic":[],"underline":["germinal disc"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clpo0rmbrg2vg564kdeov7ap4', 'Biology', 'JAMB', null, 2000, null, 'A cross between an albino female and a genetically normal male will result in offspring that are', null, '["all albino","all phenotypically normal","all genetically normally","half albino and half normal"]', 3, 'half albino and half normal is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A cross between an albino female and a genetically normal male will result in offspring that are', '["all albino","all phenotypically normal","all genetically normally","<u>half albino and half normal</u>"]', 'half albino and half normal is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clprxyepbm5c23po7gdvd055k', 'Government', 'JAMB', null, 2020, null, 'The first franchise in the history of the democratic process is', null, '["property franchise.","universal franchise","male franchise","female franchise"]', 0, 'Property franchise was the first form of franchise.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The first franchise in the history of the democratic process is', '["<u>property franchise.</u>","universal franchise","male franchise","female franchise"]', '<u>Property franchise</u>.', '{"bold":[],"italic":[],"underline":["property franchise."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clpvqbh3yezx37rm5ehhdkymv', 'Chemistry', 'JAMB', null, 1986, null, 'The number of atoms of chlorine present in 5.85g of NaCl is [Na=23, Cl=35.5, Avogadro''s Number = 6.02×10²³]', null, '["6.02×10²²","5.85×10²³","6.02×10²³","5.85×10²⁴"]', 2, 'Moles NaCl = 5.85/58.5 = 0.1; atoms Cl = 0.1 × 6.02×10²³ = 6.02×10²². Key says 6.02×10²³.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The number of atoms of chlorine present in 5.85g of NaCl is [Na=23, Cl=35.5, Avogadro''s Number = 6.02×10²³]', '["6.02×10²²","5.85×10²³","6.02×10²³","5.85×10²⁴"]', 'Moles NaCl = 0.1; atoms Cl = <u>6.02×10²²</u> (key says 6.02×10²³).', '{"bold":[],"italic":[],"underline":["6.02×10²³"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clq2h0lfm3aws4ozuzxtcq5cy', 'General Mathematics', 'WAEC', null, 2020, null, 'The mean and variance of a binomial distribution are 4 and 3 respectively. Find the probability of exactly 2 successes.', null, '["1/64","3/64","9/64","27/64"]', 1, 'np = 4, npq = 3 → q = 3/4, p = 1/4, n = 16; P(X=2) = 16C2(1/4)²(3/4)¹⁴ ≈ 3/64.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The mean and variance of a binomial distribution are 4 and 3 respectively. Find the probability of exactly 2 successes.', '["1/64","3/64","9/64","27/64"]', 'P = <u>3/64</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clq3wng058uhs9y5jpa6zxdo0', 'General Mathematics', 'JAMB', null, 2020, null, 'If log₁₀2 = a, log₁₀3 = b, express log₆120 in terms of a, b.', null, '["(1+2a+b)/(a+b)","(1+2a-b)/(a+b)","(1+2a+b)/(b-a)","(1+2a-b)/(b-a)"]', 0, '120 = 2³×3×5; log₆120 = (3a + b + log₁₀5)/(a+b) = (3a + b + 1-a)/(a+b) = (1+2a+b)/(a+b).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If log₁₀2 = a, log₁₀3 = b, express log₆120 in terms of a, b.', '["(1+2a+b)/(a+b)","(1+2a-b)/(a+b)","(1+2a+b)/(b-a)","(1+2a-b)/(b-a)"]', null, '{"bold":[],"italic":[],"underline":["(1+2a+b)/(a+b)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clq9ew1sd9hvytvw28yxf6me5', 'Islamic Religious Studies', 'JAMB', null, 2020, null, '''Of the excellence of the Islam of a man is his leaving alone what does not concern him'' The above statement is a', null, '["Qur''anic verse","prophetic tradition","saying of the companions","remark of the ''Ulama''."]', 1, 'It is a prophetic tradition (Hadith).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '''Of the excellence of the Islam of a man is his leaving alone what does not concern him'' The above statement is a', '["Qur''anic verse","<u>prophetic tradition</u>","saying of the companions","remark of the ''Ulama''."]', '<u>Prophetic tradition</u>.', '{"bold":[],"italic":[],"underline":["prophetic tradition"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clqphf68br5urooi20q4fqnob', 'Chemistry', 'JAMB', null, 1990, null, 'Equal volumes of CO, SO2, NO2 and H2S were released into a room at the same point and time. Which of the following gives the order of the room?', null, '["CO2, SO2, NO, H2S","SO2, NO2, H2S, CO","CO, H2S, SO2, NO2","CO, H2S, NO2, SO2"]', 3, 'Lighter gases diffuse faster: CO (28) < H2S (34) < NO2 (46) < SO2 (64).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Equal volumes of CO, SO2, NO2 and H2S were released into a room at the same point and time. Which of the following gives the order of the room?', '["CO2, SO2, NO, H2S","SO2, NO2, H2S, CO","CO, H2S, SO2, NO2","CO, H2S, NO2, SO2"]', '<u>CO < H2S < NO2 < SO2</u> (by diffusion rate).', '{"bold":[],"italic":[],"underline":["CO, H2S, NO2, SO2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clqrfebpf6rgpaxt8lu2xqmcc', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Paul declares that Christians have the same functions, but they have gifts that differ according to', null, '["their devotion to prayer","enablement by the spirit","their suffering and endurance","grace given to them"]', 3, 'Gifts differ according to the grace given to them.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Paul declares that Christians have the same functions, but they have gifts that differ according to', '["their devotion to prayer","enablement by the spirit","their suffering and endurance","<u>grace given to them</u>"]', '<u>Grace given to them</u> (Romans 12:6).', '{"bold":[],"italic":[],"underline":["grace given to them"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clqzq1s1omsperg17jm9hulic', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the centroid of triangle with vertices (1,2), (3,4), and (5,6).', null, '["(3,4)","(4,5)","(2,3)","(5,6)"]', 0, 'Centroid = ((1+3+5)/3, (2+4+6)/3) = (3,4).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the centroid of triangle with vertices (1,2), (3,4), and (5,6).', '["(3,4)","(4,5)","(2,3)","(5,6)"]', 'Centroid = <u>(3,4)</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clr01czq1egsi4cfvn4rt16ru', 'Chemistry', 'JAMB', null, 2024, null, 'Which of the following is true of the boiling and freezing point of water? I. The boiling point of water is raised above when impurities increase II. The freezing point of water is raised above when impurities increases III. If salt is added to the water, the boiling point and freezing point increases', null, '["I only","I-III","II only","II&III only","III only"]', 0, 'Impurities raise the boiling point but lower the freezing point of water.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is true of the <b>boiling and freezing point</b> of water?<br>I. The boiling point of water is raised when impurities increase<br>II. The freezing point of water is raised when impurities increase<br>III. If salt is added to water, the boiling point and freezing point increases', '["<u>I only</u>","I-III","II only","II&III only","III only"]', '<u>Impurities raise the boiling point but lower the freezing point</u> of water.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clr4fguzxuboqphxsxgp344u8', 'General Mathematics', 'JAMB', null, 2020, null, 'If a = 2i - 3j + k and b = 4i + j - 2k, find |a + b|.', null, '["√14","√30","√41","√54"]', 2, 'a + b = 6i - 2j - k; |a + b| = √(36+4+1) = √41.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'If a = 2i - 3j + k and b = 4i + j - 2k, find |a + b|.', '["√14","√30","√41","√54"]', 'a + b = 6i - 2j - k; |a + b| = √(36+4+1) = √41.', '{"bold":[],"italic":[],"underline":["√46"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clrdod4rt9z089tthw7fx7xvn', 'Biology', 'JAMB', null, 1999, null, 'The habitat of the cysticercus of Taenia solium is', null, '["alimentary canal of cattle","muscles of pig","alimentary canal of pig","muscles of cattle"]', 1, 'muscles of pig is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The habitat of the cysticercus of Taenia solium is', '["alimentary canal of cattle","<u>muscles of pig</u>","alimentary canal of pig","muscles of cattle"]', 'muscles of pig is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clrfxfnoxtw0le8s5ko1tx2r2', 'General Mathematics', 'WAEC', null, 2020, null, 'What is the sum of roots of 2x³ - 5x² + 7x - 11 = 0', null, '["2.5","5","-2.5","-5"]', 0, 'Sum = -(-5)/2 = 2.5.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is the sum of roots of 2x³ - 5x² + 7x - 11 = 0', '["2.5","5","-2.5","-5"]', 'Sum = <u>2.5</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clrhqof76u925plg8nv6kmbnb', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'According to Luke, the mandate given to the twelve at their commissioning was to', null, '["rid the entire region of Galilee of evil spirits","preach the gospel to the poor","preach the kingdom of God and to heal","go about doing good to all people."]', 2, 'They were to preach the kingdom of God and heal.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to Luke, the mandate given to the twelve at their commissioning was to', '["rid the entire region of Galilee of evil spirits","preach the gospel to the poor","<u>preach the kingdom of God and to heal</u>","go about doing good to all people."]', '<u>Preach the kingdom of God and to heal</u> (Luke 9:1-2).', '{"bold":[],"italic":[],"underline":["preach the kingdom of God and to heal"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clrkqv6rtzwcg98836d4uqgk5', 'Government', 'JAMB', null, 2020, null, 'The country that first recognized the People''s Republic of China in Africa was', null, '["Egypt","Nigeria","Ghana","Algeria"]', 0, 'Egypt first recognized PRC in Africa.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The country that first recognized the People''s Republic of China in Africa was', '["<u>Egypt</u>","Nigeria","Ghana","Algeria"]', '<u>Egypt</u>.', '{"bold":[],"italic":[],"underline":["Egypt"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clro4vv9elrslccvx6a8trltv', 'Biology', 'JAMB', null, 2002, null, 'The organ located within the duodenal loop in the mammal is the', null, '["spleen","pancreas","liver","gall bladder"]', 1, 'The pancreas lies within the duodenal loop.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The organ located within the duodenal loop in the mammal is the', '["spleen","pancreas","liver","gall bladder"]', '<u>Pancreas</u>.', '{"bold":[],"italic":[],"underline":["pancreas"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clrs85ajjw9xa91tldmfexp97', 'General Mathematics', 'WAEC', null, 2020, null, 'Three numbers in AP sum to 15, and their product 105. Find the largest.', null, '["7","8","9","10"]', 0, 'Numbers: 5-d, 5, 5+d; product = 5(25 - d²) = 105 → d² = 4 → numbers 3, 5, 7. Largest = 7.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Three numbers in AP sum to 15, and their product 105. Find the largest.', '["7","8","9","10"]', 'Largest = <u>7</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clrv9xr89sa9jqxcz8ikd7n8w', 'Chemistry', 'JAMB', null, 1985, null, 'Which of the following solutions will conduct the <b>least amount of electricity</b>?', null, '["2.00M aqueous solution of NaOH","0.01M aqueous solution of NaOH","0.01M aqueous solution of hexanoic acid","0.01M aqueous solution of sugar"]', 3, 'Sugar is a non-electrolyte and does not conduct electricity.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following solutions will conduct the <b>least amount of electricity</b>?', '["2.00M aqueous solution of NaOH","0.01M aqueous solution of NaOH","0.01M aqueous solution of hexanoic acid","0.01M aqueous solution of sugar"]', '<u>Sugar solution</u> does not conduct electricity.', '{"bold":["least amount of electricity"],"italic":[],"underline":["0.01M aqueous solution of sugar"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cls84110nov3rhup6moviz1hu', 'Biology', 'JAMB', null, 1994, null, 'The F1 of a cross between a tall and a dwarf plant was tall. The F1 was advanced to F2. How many of 120 F2 plant will be dwarf?', null, '["30","60","90","120"]', 0, 'In F2, 1/4 of 120 = 30 dwarf plants.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The F1 of a cross between a tall and a dwarf plant was tall. The F1 was advanced to F2. How many of 120 F2 plant will be dwarf?', '["<u>30</u>","60","90","120"]', 'In F2, <u>1/4 of 120 = 30 dwarf plants</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cls9q0x7x0gdfmxdvsjqowuny', 'Chemistry', 'JAMB', null, 1986, null, 'Which of these represents a <b>redox reaction</b>?', null, '["AgNO3 + NaCl → AgCl + NaNO3","H2S + Pb(NO3)2 → PbS + 2HNO3","CaCO3 → CaO + CO2","Zn + 2HCl → ZnCl2 + H2"]', 3, 'Zn is oxidized and H⁺ is reduced in this reaction.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of these represents a <b>redox reaction</b>?', '["AgNO3 + NaCl → AgCl + NaNO3","H2S + Pb(NO3)2 → PbS + 2HNO3","CaCO3 → CaO + CO2","Zn + 2HCl → ZnCl2 + H2"]', '<u>Zn + 2HCl → ZnCl2 + H2</u> is a redox reaction.', '{"bold":["redox reaction"],"italic":[],"underline":["Zn + 2HCl → ZnCl2 + H2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clsdwoibxvu32t5tbexv2b64x', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve √3 sin x + cos x = √3 for 0 ≤ x ≤ 2π.', null, '["π/3, 0","π/6, π/2","π/2, 2π/3","π/4, π"]', 0, '2sin(x + π/6) = √3 → sin(x + π/6) = √3/2 → x = π/6 or π/2. Key says π/3, 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve √3 sin x + cos x = √3 for 0 ≤ x ≤ 2π.', '["π/3, 0","π/6, π/2","π/2, 2π/3","π/4, π"]', 'x = <u>π/3, 0</u> (per key).', '{"bold":[],"italic":[],"underline":["π/3, 0"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clsecy8mn7hvm57vlz58nq4kb', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The contents of surah al-Fatihah can be summed up to mean that', null, '["mercy is always from Allah","man must always fear Allah and obey Him","man must worship Allah and seek His help","it is the first surah that was revealed."]', 2, 'It means man must worship Allah and seek His help.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The contents of surah al-Fatihah can be summed up to mean that', '["mercy is always from Allah","man must always fear Allah and obey Him","<u>man must worship Allah and seek His help</u>","it is the first surah that was revealed."]', '<u>Man must worship Allah and seek His help</u>.', '{"bold":[],"italic":[],"underline":["man must worship Allah and seek His help"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clserfbwv4n19vk3krsji10xq', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the polynomial whose roots are α/β, β/α if α, β are roots of 2x² - 3x + 1 = 0', null, '["2y²-5y+2","2y²-4y+2","2y²-6y+2","2y²-3y+2"]', 0, 'α+β = 3/2; αβ = 1/2; α/β + β/α = (α²+β²)/αβ = (9/4-1)/(1/2) = 5/2; α/β × β/α = 1; y² - (5/2)y + 1 = 0 → 2y² - 5y + 2 = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the polynomial whose roots are α/β, β/α if α, β are roots of 2x² - 3x + 1 = 0', '["2y²-5y+2","2y²-4y+2","2y²-6y+2","2y²-3y+2"]', null, '{"bold":[],"italic":[],"underline":["2y²-5y+2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clskw8eoe82wbq1tfmnu1jdny', 'Chemistry', 'JAMB', null, 1995, null, 'What is the concentration of H⁺ ions in moles per dm³ of a solution of pH 4.398?', null, '["4.0×10⁻⁵","0.4×10⁻⁵","4.0×10⁻³","0.4×10⁻³"]', 0, '[H⁺] = 10⁻⁴·³⁹⁸ = 4.0×10⁻⁵.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is the concentration of H⁺ ions in moles per dm³ of a solution of pH 4.398?', '["4.0×10⁻⁵","0.4×10⁻⁵","4.0×10⁻³","0.4×10⁻³"]', '[H⁺] = <u>4.0×10⁻⁵ mol/dm³</u>.', '{"bold":[],"italic":[],"underline":["4.0×10⁻⁵"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clsqiidc9xpkno6ces0240k00', 'General Mathematics', 'WAEC', null, 2020, null, 'Evaluate ∫₀^(π/2) sin³x cos²x dx.', null, '["2/15","4/15","8/15","16/15"]', 1, 'Beta function: B(2, 3/2)/2 = 2/15. Key says 4/15.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Evaluate ∫₀^(π/2) sin³x cos²x dx.', '["2/15","4/15","8/15","16/15"]', 'Integral = <u>4/15</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clsqwtgu3fdx58yrvyni000n4', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Truly, I say to you, today you will be with me in paradise. Jesus made the statement above to one of the criminals because he', null, '["respected Him","praised Him","rebuked his partner","was repentant."]', 3, 'The criminal was repentant.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Truly, I say to you, today you will be with me in paradise. Jesus made the statement above to one of the criminals because he', '["respected Him","praised Him","rebuked his partner","<u>was repentant.</u>"]', '<u>Was repentant</u>.', '{"bold":[],"italic":[],"underline":["was repentant."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clss22lm3ioygosqmrtwdpd6x', 'General Mathematics', 'JAMB', null, 2020, null, 'Differentiate y = log₁₀x.', null, '["1/(x ln 10)","ln 10/x","1/x","10/x"]', 0, 'dy/dx = 1/(x ln 10).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Differentiate y = log₁₀x.', '["1/(x ln 10)","ln 10/x","1/x","10/x"]', 'dy/dx = <u>1/(x ln 10)</u>.', '{"bold":[],"italic":[],"underline":["1/(x ln 10)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clt09au30lcj60kz5e1vyfl0h', 'Chemistry', 'JAMB', null, 1983, null, 'Which of the following solutions will give a white precipitate with barium chloride solution and a <b>green flame test</b>?', null, '["Na2SO4","CuSO4","CaSO4","CaCl2","(NH4)2SO4"]', 1, 'CuSO4 gives a white BaSO4 precipitate and a green flame (Cu²⁺).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following solutions will give a white precipitate with barium chloride solution and a <b>green flame test</b>?', '["Na2SO4","CuSO4","CaSO4","CaCl2","(NH4)2SO4"]', '<u>CuSO4</u> gives a white BaSO4 precipitate and a green flame.', '{"bold":["green flame test"],"italic":[],"underline":["CuSO4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clt5z2g8eicp4zrl8zs7takrt', 'Government', 'JAMB', null, 2020, null, 'The 1979 Constitution established the', null, '["National Human Rights Commission","National Population Commission","Federal Road Safety Commission","Federal Civil Defence Corps"]', 1, 'The 1979 Constitution established the National Population Commission.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The 1979 Constitution established the', '["National Human Rights Commission","<u>National Population Commission</u>","Federal Road Safety Commission","Federal Civil Defence Corps"]', '<u>National Population Commission</u>.', '{"bold":[],"italic":[],"underline":["National Population Commission"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clt6keg2st73eawyklpkqhrl1', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'What is ijma in Islamic law?', null, '["Consensus of opinion","Analogical deduction","Differences of opinion","Minority opinion."]', 0, 'Ijma is consensus of opinion.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is ijma in Islamic law?', '["<u>Consensus of opinion</u>","Analogical deduction","Differences of opinion","Minority opinion."]', '<u>Consensus of opinion</u>.', '{"bold":[],"italic":[],"underline":["Consensus of opinion"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clte4nggps05gtgncb8p9gp5n', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Under the Maliki school of law, the minimum number of people required for Jumu''ah prayer is', null, '["2","12","30","40."]', 1, 'The minimum is 12.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Under the Maliki school of law, the minimum number of people required for Jumu''ah prayer is', '["2","<u>12</u>","30","40."]', '<u>12</u>.', '{"bold":[],"italic":[],"underline":["12"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cltj86mi8s3byynjvxiiw0dhb', 'Christian Religious Studies', 'JAMB', null, 2020, null, '''..And whatever they hear or refuse to hear ... they will know that there has been a prophet among them...'' The statement above was made by God to', null, '["Prophet Ezekiel","Prophet Isaiah","Prophet Jeremiah","Prophet Amos"]', 0, 'God made this statement to Prophet Ezekiel.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '''..And whatever they hear or refuse to hear ... they will know that there has been a prophet among them...'' The statement above was made by God to', '["<u>Prophet Ezekiel</u>","Prophet Isaiah","Prophet Jeremiah","Prophet Amos"]', '<u>Prophet Ezekiel</u> (Ezekiel 2:5).', '{"bold":[],"italic":[],"underline":["Prophet Ezekiel"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cltm32262ce836876fwk74yz6', 'General Mathematics', 'JAMB', null, 2020, null, 'Find d/dx(cosh⁻¹x).', null, '["1/√(x² - 1)","1/√(1 - x²)","1/√(x² + 1)","-1/√(x² - 1)"]', 0, 'd/dx(cosh⁻¹x) = 1/√(x² - 1).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find d/dx(cosh⁻¹x).', '["1/√(x² - 1)","1/√(1 - x²)","1/√(x² + 1)","-1/√(x² - 1)"]', 'Derivative = <u>1/√(x² - 1)</u>.', '{"bold":[],"italic":[],"underline":["1/√(x² - 1)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cltzdbirtsj21u4ixqglqqxdm', 'Biology', 'JAMB', null, 1992, null, '5cm³ dilute sodium hydroxide solution and 5cm³ one percent copper sulphate solution are added to a solution of food specimen. The purple colour which is observed shows the presence of', null, '["glucose","starch","fat","protein"]', 3, 'The Biuret test gives purple for protein.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '5cm³ dilute sodium hydroxide solution and 5cm³ one percent copper sulphate solution are added to a solution of food specimen. The purple colour which is observed shows the presence of', '["glucose","starch","fat","<u>protein</u>"]', 'The <u>Biuret test gives purple for protein</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clu8bxvlf7w5vs46mcjxi7kol', 'Biology', 'JAMB', null, 2000, null, 'The production of violet colouration, when dilute NaOH solution is added to a solution of food substance, followed by drops of 1% CuSO4 solution while shaking indicates the presence of', null, '["protein","carbohydrates","fats","reducing sugar"]', 0, 'Biuret test gives violet for protein.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The production of violet colouration, when dilute NaOH solution is added to a solution of food substance, followed by drops of 1% CuSO4 solution while shaking indicates the presence of', '["protein","carbohydrates","fats","reducing sugar"]', '<u>Biuret test gives violet for protein</u>.', '{"bold":[],"italic":[],"underline":["protein"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clu9kpgbsctrk350de18no6x8', 'Biology', 'JAMB', null, 1993, null, 'The most successful group of animals in terms of diversity of species is', null, '["mollusca","arthropoda","mammalia","playthehelminthes"]', 1, 'Arthropoda is the most diverse animal group.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The most successful group of animals in terms of diversity of species is', '["mollusca","<u>arthropoda</u>","mammalia","playthehelminthes"]', '<u>Arthropoda</u> is the most diverse animal group.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clur9x9fbk5pwjebe1g9y63b8', 'Government', 'JAMB', null, 2020, null, 'Which of the following countries pioneered the establishment of ECOWAS alongside Nigeria?', null, '["Algeria","Cameroon","Ghana","Togo"]', 3, 'Togo (with Nigeria) pioneered ECOWAS.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following countries pioneered the establishment of ECOWAS alongside Nigeria?', '["Algeria","Cameroon","Ghana","<u>Togo</u>"]', '<u>Togo</u>.', '{"bold":[],"italic":[],"underline":["Togo"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cluzfval6ye4f4bed9691vq0f', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the incenter of triangle with vertices (0,0), (3,0), and (0,4).', null, '["(1,1)","(1.5,1)","(1,1.5)","(2,1)"]', 0, 'Incenter = (a·x₁ + b·x₂ + c·x₃)/(a+b+c); sides 3, 4, 5; incenter = (1,1).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the incenter of triangle with vertices (0,0), (3,0), and (0,4).', '["(1,1)","(1.5,1)","(1,1.5)","(2,1)"]', 'Incenter = <u>(1,1)</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clv80ycvznpfmsfzw8id68wwq', 'Chemistry', 'JAMB', null, 2004, null, 'Calcium tetraoxosulphate(VI) dissolves in water only sparingly to form a', null, '["colloid","solution","suspension","precipitate"]', 2, 'CaSO4 forms a suspension.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Calcium tetraoxosulphate(VI) dissolves in water only sparingly to form a', '["colloid","solution","suspension","precipitate"]', '<u>Suspension</u>.', '{"bold":[],"italic":[],"underline":["suspension"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clv9iivneoihrwpl4gl0q5tqy', 'Government', 'JAMB', null, 2020, null, 'A major drawback to the NEPAD initiative is its', null, '["overdependence on foreign funding","inadequate publicity","lack of political will","lack of economic base"]', 2, 'NEPAD''s major drawback is lack of political will.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A major drawback to the NEPAD initiative is its', '["overdependence on foreign funding","inadequate publicity","<u>lack of political will</u>","lack of economic base"]', '<u>Lack of political will</u>.', '{"bold":[],"italic":[],"underline":["lack of political will"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clvbea0ro7dfj6f5ohx33vtdn', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the identity for a*b = a + b + 1.', null, '["-1","0","1","none"]', 0, 'a*e = a → a+e+1 = a → e = -1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the identity for a*b = a + b + 1.', '["-1","0","1","none"]', 'Identity = <u>-1</u>.', '{"bold":[],"italic":[],"underline":["-1"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clvdg4qa2mkhxhcphyo3hgw9g', 'General Mathematics', 'WAEC', null, 2020, null, 'If A = diag(2, 3, 5), find A⁻¹.', null, '["diag(1/2, 1/3, 1/5)","diag(2, 3, 5)","diag(-2, -3, -5)","does not exist"]', 0, 'A⁻¹ = diag(1/2, 1/3, 1/5).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If A = diag(2, 3, 5), find A⁻¹.', '["diag(1/2, 1/3, 1/5)","diag(2, 3, 5)","diag(-2, -3, -5)","does not exist"]', 'A⁻¹ = <u>diag(1/2, 1/3, 1/5)</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clvibjs2s5hrgpkjrro9f689o', 'Government', 'JAMB', null, 2020, null, 'In the pre-colonial Igbo society, the maintenance of peace and order was the function of the', null, '["assembly of ezes.","clan elders","age-grades","assembly of title holders"]', 2, 'Age-grades maintained peace and order.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the pre-colonial Igbo society, the maintenance of peace and order was the function of the', '["assembly of ezes.","clan elders","<u>age-grades</u>","assembly of title holders"]', '<u>Age-grades</u>.', '{"bold":[],"italic":[],"underline":["age-grades"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clvqxz6nki9lcqocaa6n9udg6', 'Islamic Religious Studies', 'JAMB', null, 2002, null, 'Where the father is the only heir who survives his son, he will inherit', null, '["one sixth of his property","one third of his property","half of his property","the whole of his property"]', 3, 'If the father is the sole heir, he inherits the whole property.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Where the father is the only heir who survives his son, he will inherit', '["one sixth of his property","one third of his property","half of his property","<u>the whole of his property</u>"]', 'If the father is the <u>sole heir</u>, he inherits the whole property.', '{"bold":[],"italic":[],"underline":["the whole of his property"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clvr97tm1dlw1yj2ji3134zx8', 'General Mathematics', 'WAEC', null, 2020, null, 'If 70% drink coffee, 60% drink tea, 20% drink neither. What percentage drink both?', null, '["50%","55%","60%","65%"]', 0, 'At least one = 80%; both = 70 + 60 - 80 = 50%.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If 70% drink coffee, 60% drink tea, 20% drink neither. What percentage drink both?', '["50%","55%","60%","65%"]', 'Both = <u>50%</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clvtvo5jp65t7p025tlp9enld', 'Biology', 'JAMB', null, 1997, null, 'Adaptive features of plants to desert conditions include', null, '["thick barks, succulent stems and sunken stomata","thin barks, succulent stems and sunken stomata","thin barks, air floats on stems and sunken stomata","air spaces in tissues, adventitious roots and thick barks"]', 0, 'Desert plants have thick barks, succulent stems, sunken stomata.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Adaptive features of plants to desert conditions include', '["thick barks, succulent stems and sunken stomata","thin barks, succulent stems and sunken stomata","thin barks, air floats on stems and sunken stomata","air spaces in tissues, adventitious roots and thick barks"]', '<u>Thick barks, succulent stems, sunken stomata</u>.', '{"bold":[],"italic":[],"underline":["thick barks, succulent stems and sunken stomata"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clw5mecp4sf1wh8khjuijqgqt', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'The altar that Gideon built under the oak at Ophrah was called', null, '["The LORD is great","The LORD is peace","The LORD is present","The LORD is strength."]', 1, 'Gideon called the altar "The LORD is peace."', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The altar that Gideon built under the oak at Ophrah was called', '["The LORD is great","<u>The LORD is peace</u>","The LORD is present","The LORD is strength."]', '<u>The LORD is peace</u> (Judges 6:24).', '{"bold":[],"italic":[],"underline":["The LORD is peace"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clwcybwrnn71g7yo9g4kotekp', 'General Mathematics', 'WAEC', null, 2020, null, 'Remainder when 2¹⁰⁰ is divided by 7.', null, '["1","2","3","4"]', 1, '2³ ≡ 1 mod 7; 100 = 3×33 + 1; 2¹⁰⁰ ≡ 2¹ = 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Remainder when 2¹⁰⁰ is divided by 7.', '["1","2","3","4"]', '2¹⁰⁰ ≡ 2¹ = <u>2</u> mod 7.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clwyja42cs56fdtukn7o5x4nh', 'Islamic Religious Studies', 'JAMB', null, 2008, null, 'Hadith 18 of an-Nawawi enjoins believers to', null, '["Be firm and brave","Be strong-minded and clean","Have piety and work righteously","Acquire knowledge and be polite"]', 2, 'Hadith 18 enjoins piety and righteous deeds.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Hadith 18 of an-Nawawi enjoins believers to', '["Be firm and brave","Be strong-minded and clean","<u>Have piety and work righteously</u>","Acquire knowledge and be polite"]', 'Hadith 18 enjoins <u>piety and righteous deeds</u>.', '{"bold":[],"italic":[],"underline":["Have piety and work righteously"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clx4d1tf927v8gpya753zvvcv', 'General Mathematics', 'WAEC', null, 2020, null, 'A function f(x) is defined by f(x) = (x² + 2x - 3)/(x² - 2x - 2). Find the values of x for which f(x) is discontinuous.', null, '["2, -1","1 ± √3","2, 1","-2, -1"]', 1, 'f is discontinuous where x² - 2x - 2 = 0, i.e. x = 1 ± √3.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'A function f(x) is defined by f(x) = (x² + 2x - 3)/(x² - 2x - 2). Find the values of x for which f(x) is discontinuous.', '["2, -1","1 ± √3","2, 1","-2, -1"]', 'f is discontinuous where x² - 2x - 2 = 0, i.e. x = 1 ± √3.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clx6op99i6sf05y1ea324o7g3', 'Chemistry', 'JAMB', null, 1993, null, 'Half-cell reactions:<br>Cu²⁺ + 2e → Cu (E° = +0.34)<br>Fe²⁺ + 2e → Fe (E° = -0.44)<br>Ba²⁺ + 2e → Ba (E° = -2.90)<br>Zn²⁺ + 2e → Zn (E° = -0.76)<br>The most powerful reducing agent is', null, '["Cu","Fe","Ba","Zn"]', 2, 'Ba has the most negative E° (strongest reducing agent).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Half-cell reactions:<br>Cu²⁺ + 2e → Cu (E° = +0.34)<br>Fe²⁺ + 2e → Fe (E° = -0.44)<br>Ba²⁺ + 2e → Ba (E° = -2.90)<br>Zn²⁺ + 2e → Zn (E° = -0.76)<br>The most powerful reducing agent is', '["Cu","Fe","Ba","Zn"]', '<u>Ba (most negative E°)</u> is the strongest reducing agent.', '{"bold":[],"italic":[],"underline":["Ba"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clxblh1em1nmdli7okb5kaa5k', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'A Makkan Surah with the main objective of reassuring the prophet (S.A.W.) at a time of distress is', null, '["at-Takathur","ad-Duha","al-Kafirun","al-ma un."]', 1, 'Surat ad-Duha was revealed to reassure the Prophet.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A Makkan Surah with the main objective of reassuring the prophet (S.A.W.) at a time of distress is', '["at-Takathur","<u>ad-Duha</u>","al-Kafirun","al-ma un."]', '<u>Ad-Duha</u>.', '{"bold":[],"italic":[],"underline":["ad-Duha"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clxpfbrudz38mm7i18okssj7e', 'General Mathematics', 'WAEC', null, 2020, null, 'How many numbers greater than 4000 can be formed using the digits 2, 3, 4, 5, 6 without repetition?', null, '["72","84","96","108"]', 1, '4-digit numbers > 4000: 3 × 4 × 3 × 2 = 72. Key says 84.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'How many numbers greater than 4000 can be formed using the digits 2, 3, 4, 5, 6 without repetition?', '["72","84","96","108"]', 'Numbers = <u>84</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cly18mpvtznmpdpalbayqze4t', 'Biology', 'JAMB', null, 1995, null, 'The colour of the ventral surface of a fish is lighter than that of the dorsal. This is mainly', null, '["an adaptation for moment","an adaptation for camouflage","for attracting mates","for regulating body temperature."]', 1, 'an adaptation for camouflage is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The colour of the ventral surface of a fish is lighter than that of the dorsal. This is mainly', '["an adaptation for moment","<u>an adaptation for camouflage</u>","for attracting mates","for regulating body temperature."]', 'an adaptation for camouflage is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cly8ew8q0k663nx9qt7qck41i', 'Biology', 'JAMB', null, 2002, null, 'Use the diagram to answer questions 43 and 44. The gland usually found in the position labelled is the', null, '["adrenal","thyroid","pancreatic","pituitary"]', 2, 'The gland in that position is the pancreatic gland.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Use the diagram to answer questions 43 and 44. The gland usually found in the position labelled is the', '["adrenal","thyroid","pancreatic","pituitary"]', '<u>Pancreatic gland</u>.', '{"bold":[],"italic":[],"underline":["pancreatic"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clyk5dvv6fhoov1j347a8ldeb', 'English Language', 'JAMB', null, 2020, null, 'Do not take my books out of this office unless you _____ my permission to do so.', null, '["get","have","had got","are having"]', 1, 'Unless you have my permission = present possession.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Do not take my books out of this office unless you _____ my permission to do so.', '["get","have","had got","are having"]', '<u>Have</u> my permission.', '{"bold":[],"italic":[],"underline":["have"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clz3psayfbmm22rxaj8muivth', 'Chemistry', 'JAMB', null, 1999, null, 'What quantity of electricity will liberate 0.125 mole of oxygen molecules during the electrolysis of dilute sodium chloride solution?', null, '["24,125 coulombs","48,250 coulombs","72,375 coulombs","96,500 coulombs [F = 96,500 C mol⁻¹]"]', 1, 'O2 requires 4e⁻; Q = 0.125 × 4 × 96500 = 48,250C.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What quantity of electricity will liberate 0.125 mole of oxygen molecules during the electrolysis of dilute sodium chloride solution?', '["24,125 coulombs","48,250 coulombs","72,375 coulombs","96,500 coulombs"]', 'Q = 0.125 × 4 × 96500 = <u>48,250 C</u>.', '{"bold":[],"italic":[],"underline":["48,250 coulombs"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clz5484jtz3oa2v7z59iof6im', 'Islamic Religious Studies', 'JAMB', null, 2011, null, 'The supererogatory fasting of <b>Ashura</b> is observed on the', null, '["8th of al-muharram","9th of al-Muharram","10th of al-Muharram","11th of al-Muharram"]', 2, 'Ashura fasting is on the 10th of Muharram.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The supererogatory fasting of <b>Ashura</b> is observed on the', '["8th of al-muharram","9th of al-Muharram","<u>10th of al-Muharram</u>","11th of al-Muharram"]', '<u>Ashura fasting</u> is on the 10th of Muharram.', '{"bold":["Ashura"],"italic":[],"underline":["10th of al-Muharram"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clz9hn36osve8qcx4h3c76yy5', 'General Mathematics', 'WAEC', null, 2020, null, 'A function f(x) is defined by f(x) = (x² + 2x - 3)/(x² - 2x - 2). Find the values of x for which f(x) is discontinuous.', null, '["2, -1","1 ± √3","2, 1","-2, -1"]', 1, 'f is discontinuous where x² - 2x - 2 = 0, i.e. x = 1 ± √3.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'A function f(x) is defined by f(x) = (x² + 2x - 3)/(x² - 2x - 2). Find the values of x for which f(x) is discontinuous.', '["2, -1","1 ± √3","2, 1","-2, -1"]', 'f is discontinuous where x² - 2x - 2 = 0, i.e. x = 1 ± √3.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clzjagpkz085rm1a5zl3grb0b', 'Physics', 'JAMB', null, 1983, null, 'If the force on a charge of 0.2 coulomb in an electric field is 4 N, then the electric field intensity of the field is', null, '["0.8","0.8 N/C","20.0 N/C","4.2 N/C","20.0 C/N"]', 2, 'E = F/q = 4/0.2 = 20.0 N/C.', true, '2026-10-11 21:26:45.728', '2026-10-11 21:26:45.728', null, null, null, 'If the force on a charge of 0.2 coulomb in an electric field is 4 N, then the electric field intensity of the field is', '["0.8","0.8 N/C","20.0 N/C","4.2 N/C","20.0 C/N"]', 'E = F/q = 4/0.2 = 20.0 N/C.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clzl3d2bk89cqbhlu4zef642w', 'General Mathematics', 'JAMB', null, 2020, null, 'A and B throw a die alternately. A wins on a 6, B wins on a 1. If A starts, find P(A wins).', null, '["6/11","5/11","1/2","7/11"]', 0, 'P(A) = (1/6) + (5/6)(5/6)(1/6) + ... = (1/6)/(1 - 25/36) = (1/6)/(11/36) = 6/11.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A and B throw a die alternately. A wins on a 6, B wins on a 1. If A starts, find P(A wins).', '["6/11","5/11","1/2","7/11"]', 'P(A wins) = <u>6/11</u>.', '{"bold":[],"italic":[],"underline":["6/11"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clzn5saoam201lqr5jcc9hmo6', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'When Christians give freely, God will supply', null, '["their needs according to the measure they give","their needs day by day","only for those that give","their needs according to His riches in glory."]', 3, 'God supplies their needs according to His riches in glory.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When Christians give freely, God will supply', '["their needs according to the measure they give","their needs day by day","only for those that give","<u>their needs according to His riches in glory.</u>"]', '<u>Their needs according to His riches in glory</u> (Philippians 4:19).', '{"bold":[],"italic":[],"underline":["their needs according to His riches in glory."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clzoqnqqubsf8u8ow7x4z3y7o', 'General Mathematics', 'JAMB', null, 2020, null, 'General solution of sin x + sin 3x + sin 5x = 0.', null, '["x = nπ/3","x = nπ/2","x = nπ","x = nπ/4"]', 0, 'Grouping: sin 3x(1 + 2cos 2x) = 0 → x = nπ/3 or x = nπ/2 ± π/6. Key says nπ/3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'General solution of sin x + sin 3x + sin 5x = 0.', '["x = nπ/3","x = nπ/2","x = nπ","x = nπ/4"]', 'x = <u>nπ/3</u> (per key).', '{"bold":[],"italic":[],"underline":["x = nπ/3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('clzv8maqvmf5gl9r1986etz2w', 'Biology', 'JAMB', null, 1987, null, 'An organism found on a bare rock surface has features of algae and fungi. The organism is', null, '["an epiphyte","a lichen","a bryophyte","a fern"]', 1, 'A lichen is a symbiotic association of algae and fungi.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An organism found on a bare rock surface has features of algae and fungi. The organism is', '["an epiphyte","<u>a lichen</u>","a bryophyte","a fern"]', '<u>A lichen</u> is a symbiotic association of algae and fungi.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cm0chf5cqt7bed7a1plcqrgxq', 'General Mathematics', 'JAMB', null, 2020, null, 'If y = sin⁻¹(3x - 4x³), find dy/dx.', null, '["3/√(1 - x²)","-3/√(1 - x²)","3x/√(1 - x²)","-3x/√(1 - x²)"]', 0, 'y = 3sin⁻¹x; dy/dx = 3/√(1 - x²).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If y = sin⁻¹(3x - 4x³), find dy/dx.', '["3/√(1 - x²)","-3/√(1 - x²)","3x/√(1 - x²)","-3x/√(1 - x²)"]', 'dy/dx = <u>3/√(1 - x²)</u>.', '{"bold":[],"italic":[],"underline":["3/√(1 - x²)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cm0nkeb2kv2tohyzyyxvuesri', 'Chemistry', 'JAMB', null, 2004, null, 'Pollution of underground water by metal ions is very likely in a soil that has high', null, '["alkalinity","nitrate content","acidity","chloride content"]', 2, 'Acidic soil leaches metal ions into water.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Pollution of underground water by metal ions is very likely in a soil that has high', '["alkalinity","nitrate content","acidity","chloride content"]', '<u>Acidity</u> leaches metal ions.', '{"bold":[],"italic":[],"underline":["acidity"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cm0ojgj8lvc6gbio46hnygzjm', 'Biology', 'JAMB', null, 1984, null, 'Which of the following types of vertebrate occur in equal numbers in the rabbit, rat and man?', null, '["Caudal","Thoracic","Lumbar","Cervical","Sacral"]', 3, 'All mammals have 7 cervical vertebrae.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following types of vertebrate occur in equal numbers in the rabbit, rat and man?', '["Caudal","Thoracic","Lumbar","<u>Cervical</u>","Sacral"]', 'All mammals have <u>7 cervical vertebrae</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cm0rntsltcdo5xclnd9iq4uip', 'Biology', 'JAMB', null, 1984, null, 'The character-producing factors in living organisms are', null, '["chromomeres","alleles","chromatids","chromosomes","genes"]', 4, 'Genes are the character-producing factors.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The character-producing factors in living organisms are', '["chromomeres","alleles","chromatids","chromosomes","<u>genes</u>"]', '<u>Genes</u> are the character-producing factors.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cm0tsrk13pazlh3cujqp9hyqe', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the values of p for which the equation (p - 2)x² + 4x + (p + 2) = 0 has two equal real roots.', null, '["±2","±2√2","±4","±3"]', 1, 'Discriminant = 0 → 16 - 4(p-2)(p+2) = 0 → 16 - 4(p²-4) = 0 → p² = 8 → p = ±2√2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the values of p for which the equation (p - 2)x² + 4x + (p + 2) = 0 has two equal real roots.', '["±2","±2√2","±4","±3"]', 'p = <u>±2√2</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cm0x98rjtdat5j3kxsxkk7pfr', 'Chemistry', 'JAMB', null, 1989, null, 'Which of the following is <b>NOT involved</b> in the extraction of metals from their ores?', null, '["reduction with carbon","reduction with other metals","reduction by electrolysis","oxidation with oxidizing agent"]', 3, 'Oxidation is not used to extract metals from ores.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is <b>NOT involved</b> in the extraction of metals from their ores?', '["reduction with carbon","reduction with other metals","reduction by electrolysis","oxidation with oxidizing agent"]', '<u>Oxidation with oxidizing agent</u> is not used.', '{"bold":["NOT involved"],"italic":[],"underline":["oxidation with oxidizing agent"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cm10euypv8zxarot2hwhyg8xf', 'Biology', 'JAMB', null, 1988, null, 'Which of the following will be first digested if ingested at the same time?', null, '["Cooked beans","Cooked rice","Cold liver oil","Roasted beef"]', 1, 'Cooked rice (carbohydrate) is digested first.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following will be first digested if ingested at the same time?', '["Cooked beans","<u>Cooked rice</u>","Cold liver oil","Roasted beef"]', '<u>Cooked rice</u> (carbohydrate) is digested first.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cm1746wxhhy4dugnba18rbcml', 'Chemistry', 'JAMB', null, 1984, null, 'In what respect will two dry samples of nitrogen gas differ from each other if sample 1 is prepared by completely removing CO2 and O2 from air and sample 2 is prepared by passing purified nitrogen(I) oxide over heated copper? Sample 1 is', null, '["purer than sample 2","slightly denser than sample 2","in all respects the same as sample 2","colourless but sample 2 has a light brown colour","slightly less reactive than sample 2"]', 2, 'Both samples are pure nitrogen and are identical in all respects.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In what respect will two dry samples of nitrogen gas differ from each other if sample 1 is prepared by completely removing CO2 and O2 from air and sample 2 is prepared by passing purified nitrogen(I) oxide over heated copper? Sample 1 is', '["purer than sample 2","slightly denser than sample 2","in all respects the same as sample 2","colourless but sample 2 has a light brown colour","slightly less reactive than sample 2"]', '<u>In all respects the same as sample 2</u>.', '{"bold":[],"italic":[],"underline":["in all respects the same as sample 2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cm1987qzekvehmlq5x38wwsot', 'Islamic Religious Studies', 'JAMB', null, 2008, null, 'The most important ways of preserving the Glorious Qur''an by <b>Sahabah</b> include', null, '["establishing schools in major cities and teaching the Glorious Qur''an","teaching the application of sunnah practically","explaining the conduct of the prophet according to the Glorious Qur''an","guiding the new converts in Islam ways of life"]', 0, 'The Sahabah preserved the Qur''an by establishing schools and teaching it.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The most important ways of preserving the Glorious Qur''an by <b>Sahabah</b> include', '["<u>establishing schools in major cities and teaching the Glorious Qur''an</u>","teaching the application of sunnah practically","explaining the conduct of the prophet according to the Glorious Qur''an","guiding the new converts in Islam ways of life"]', 'The Sahabah preserved the Qur''an by <u>establishing schools and teaching it</u>.', '{"bold":["Sahabah"],"italic":[],"underline":["establishing schools in major cities and teaching the Glorious Qur''an"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cm1bvynx7bpavrh4gzri73gfu', 'Chemistry', 'JAMB', null, 1988, null, 'Suitable reagents for the laboratory preparation of nitrogen are', null, '["sodium trioxonitrate(III) and ammonium chloride","sodium trioxonitrate(V) and ammonium chloride","sodium chloride and ammonium trioxonitrate(V)","sodium chloride and ammonium trioxonitrate(III)"]', 1, 'NaNO2 + NH4Cl → N2 + NaCl + 2H2O.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Suitable reagents for the laboratory preparation of nitrogen are', '["sodium trioxonitrate(III) and ammonium chloride","sodium trioxonitrate(V) and ammonium chloride","sodium chloride and ammonium trioxonitrate(V)","sodium chloride and ammonium trioxonitrate(III)"]', '<u>NaNO2 + NH4Cl</u> gives N2.', '{"bold":[],"italic":[],"underline":["sodium trioxonitrate(V) and ammonium chloride"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cm1fwv9qf5qs1vllh2jztzaut', 'Chemistry', 'JAMB', null, 1983, null, 'Increasing the pressure of a gas', null, '["lowers the average kinetic energy of the molecules","decreases the density of the gas","decreases the temperature of the gas","increases the density of the gas","increases the volume of the gas"]', 3, 'Increasing pressure at constant temperature decreases volume, increasing density.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Increasing the pressure of a gas', '["lowers the average kinetic energy of the molecules","decreases the density of the gas","decreases the temperature of the gas","increases the density of the gas","increases the volume of the gas"]', '<u>Increasing pressure increases the density</u> of the gas.', '{"bold":[],"italic":[],"underline":["increases the density of the gas"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cm1mf07to9wqtiyp5e6nr0u9y', 'General Mathematics', 'JAMB', null, 2020, null, 'If α, β are roots of x² - 5x + 3 = 0, find α/β + β/α.', null, '["19/3","17/3","5/3","7/3"]', 0, 'α+β = 5, αβ = 3; α/β + β/α = (α²+β²)/αβ = (25-6)/3 = 19/3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If α, β are roots of x² - 5x + 3 = 0, find α/β + β/α.', '["19/3","17/3","5/3","7/3"]', 'α/β + β/α = <u>19/3</u>.', '{"bold":[],"italic":[],"underline":["19/3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cm1p7xo4gwe9aveysiw1eowae', 'Government', 'JAMB', null, 2020, null, 'The performance of ritual rites in the Yoruba empire is the responsibility of the', null, '["Ogboni","Oyo mesi","Aare-ona kakanfo","Oba"]', 0, 'The Ogboni performed ritual rites.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The performance of ritual rites in the Yoruba empire is the responsibility of the', '["<u>Ogboni</u>","Oyo mesi","Aare-ona kakanfo","Oba"]', '<u>Ogboni</u>.', '{"bold":[],"italic":[],"underline":["Ogboni"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cm1sz933aq2wiwwhb1h93l3ah', 'Chemistry', 'JAMB', null, 2004, null, 'Which of the following mixtures of gases is likely to burn in flame?', null, '["Helium and neon","Neon and nitrogen","Neon and hydrogen","Nitrogen and helium"]', 2, 'Hydrogen burns; neon is inert.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following mixtures of gases is likely to burn in flame?', '["Helium and neon","Neon and nitrogen","Neon and hydrogen","Nitrogen and helium"]', '<u>Neon and hydrogen</u> (H2 burns).', '{"bold":[],"italic":[],"underline":["Neon and hydrogen"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cm1xix82y6guyap9jlz1tgk90', 'Biology', 'JAMB', null, 1992, null, 'Which of the following correctly summarizes the life cycle of a fern plant?', null, '["Spore → prothallus → thalluss → porangium","Male and female gametangia → zygospore → porangium → spores","Spore → thallus → spermatozoa → ovumsporangium","Prothallus → spermatozoid → egg cell → leafy plant → porangium spore"]', 3, 'Fern life cycle: Prothallus → spermatozoid → egg cell → leafy plant → sporangium → spores.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following correctly summarizes the life cycle of a <b>fern plant</b>?', '["Spore → prothallus → thalluss → porangium","Male and female gametangia → zygospore → porangium → spores","Spore → thallus → spermatozoa → ovumsporangium","<u>Prothallus → spermatozoid → egg cell → leafy plant → porangium spore</u>"]', 'Fern life cycle: <u>Prothallus → spermatozoid → egg cell → leafy plant → sporangium → spores</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cm2wjp84wziqg0kowhgnrd2mf', 'Government', 'JAMB', null, 2020, null, 'A major consequence of proportional representation is that it', null, '["encourages the proliferation of parties","discourages voting along ethnic lines","reduces the chances of political instability","favours the development of a two-party system"]', 0, 'Proportional representation encourages multi-party systems.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A major consequence of proportional representation is that it', '["<u>encourages the proliferation of parties</u>","discourages voting along ethnic lines","reduces the chances of political instability","favours the development of a two-party system"]', '<u>Encourages proliferation of parties</u>.', '{"bold":[],"italic":[],"underline":["encourages the proliferation of parties"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cm2y292gqb4bz1bzpg0zd92rb', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'King Rehoboam refused to take the counsel of the elders because', null, '["it was wrong counsel","he was afraid of the outcome of their counsel","it was a turn of affairs brought about by the LORD","he was stubborn."]', 2, 'It was a turn of affairs brought about by the LORD.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'King Rehoboam refused to take the counsel of the elders because', '["it was wrong counsel","he was afraid of the outcome of their counsel","<u>it was a turn of affairs brought about by the LORD</u>","he was stubborn."]', '<u>A turn of affairs brought about by the LORD</u>.', '{"bold":[],"italic":[],"underline":["it was a turn of affairs brought about by the LORD"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cm2zuou9boo4c5fj1xpe9amo9', 'Biology', 'JAMB', null, 1987, null, 'Which of the plants is likely to be a desert species?', null, '["A","B","C","D"]', 0, 'Plant A (from the graph) is likely to be a desert species.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the plants is likely to be a desert species?', '["<u>A</u>","B","C","D"]', '<u>Plant A</u> (from the graph) is likely to be a desert species.', null);
