insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cm6jbaaf7f49tgkry4koflu32', 'Biology', 'JAMB', null, 1985, null, 'In a mammal, stimulus is transferred from the receptor muscle to the central nervous system through the', null, '["motor neurons","effector muscles","dendrites","sensory neurons","synapses"]', 3, 'Sensory neurons transmit stimuli to the CNS.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In a mammal, stimulus is transferred from the receptor muscle to the central nervous system through the', '["motor neurons","effector muscles","dendrites","<u>sensory neurons</u>","synapses"]', '<u>Sensory neurons</u> transmit stimuli to the CNS.', null);
