insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cm6mpryo28dtonpwfexk21lyf', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'As each has received a gift, employ it for one another, as good stewards of God''s varied grace... In the statement above, Peter teaches believers the virtue of', null, '["communion","fellowship","hospitality","giving."]', 2, 'Peter teaches the virtue of hospitality.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'As each has received a gift, employ it for one another, as good stewards of God''s varied grace... In the statement above, Peter teaches believers the virtue of', '["communion","fellowship","<u>hospitality</u>","giving."]', '<u>Hospitality</u> (1 Peter 4:9-10).', '{"bold":[],"italic":[],"underline":["hospitality"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cm6nm7zvc58qsg4zf9myl2giv', 'Chemistry', 'JAMB', null, 1995, null, 'What volume of 11.0M hydrochloric acid must be diluted to obtain 1dm³ of 0.05M acid?', null, '["0.05dm³","0.10dm³","0.55dm³","11.0dm³"]', 1, 'M1V1 = M2V2; V1 = (0.05 × 1)/11 = 0.0045 dm³.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What volume of 11.0M hydrochloric acid must be diluted to obtain 1dm³ of 0.05M acid?', '["0.05dm³","0.10dm³","0.55dm³","11.0dm³"]', 'V1 = <u>0.0045 dm³</u> (closest 0.05).', '{"bold":[],"italic":[],"underline":["0.10dm³"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cm71paf1dk7giiytaop77disi', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Josiah''s religious reforms led to the', null, '["killing of the worthless priests in the cities of Judah","keeping of the Passover in Jerusalem","killing of the male cult prostitutes who were in the Temple","renovation of the Jerusalem Temple."]', 1, 'His reforms led to the keeping of the Passover in Jerusalem.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Josiah''s religious reforms led to the', '["killing of the worthless priests in the cities of Judah","<u>keeping of the Passover in Jerusalem</u>","killing of the male cult prostitutes who were in the Temple","renovation of the Jerusalem Temple."]', '<u>Keeping of the Passover in Jerusalem</u>.', '{"bold":[],"italic":[],"underline":["keeping of the Passover in Jerusalem"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cm73qyhq27rqt4il6cbh8uryz', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve x² - 5x + 6 < 0.', null, '["(2, 3)","[2, 3]","(-∞, 2) ∪ (3, ∞)","(-∞, 2] ∪ [3, ∞)"]', 0, '(x-2)(x-3) < 0 → 2 < x < 3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve x² - 5x + 6 < 0.', '["(2, 3)","[2, 3]","(-∞, 2) ∪ (3, ∞)","(-∞, 2] ∪ [3, ∞)"]', '<u>2 < x < 3</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cm770y8qd1ib08v680xa2xdmn', 'Islamic Religious Studies', 'JAMB', null, 2011, null, 'The minimum number of witnesses in an Islamic marriage is', null, '["four males","three males","two males","one male"]', 2, 'At least two witnesses are required for marriage.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The minimum number of witnesses in an Islamic marriage is', '["four males","three males","<u>two males</u>","one male"]', 'At least <u>two witnesses</u> are required for marriage.', '{"bold":[],"italic":[],"underline":["two males"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cm7cz996antdbfg88j1ic196b', 'Government', 'JAMB', null, 2020, null, 'A major shortcoming of the Ombudsman is', null, '["lack of adequate resources","its inability to restrain bureaucratic excesses","lack of clear-cut mandate","lack of executive power to enforce decisions."]', 3, 'The Ombudsman lacks executive power to enforce decisions.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A major shortcoming of the Ombudsman is', '["lack of adequate resources","its inability to restrain bureaucratic excesses","lack of clear-cut mandate","<u>lack of executive power to enforce decisions.</u>"]', '<u>Lack of executive power to enforce decisions</u>.', '{"bold":[],"italic":[],"underline":["lack of executive power to enforce decisions."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cm7gv64khj160evsjuphe67f6', 'Chemistry', 'JAMB', null, 1993, null, 'As the difference in electronegativity between bonded atoms increases, polarity of the bond', null, '["decreases","increases","remains unchanged","reduces to zero"]', 1, 'Greater electronegativity difference → higher polarity.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'As the difference in electronegativity between bonded atoms increases, polarity of the bond', '["decreases","increases","remains unchanged","reduces to zero"]', '<u>Polarity increases</u> with electronegativity difference.', '{"bold":[],"italic":[],"underline":["increases"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cm87j7bgc8ds1uq07m54v8stb', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'God decided to destroy the great city of Nineveh because the people were', null, '["wicked","adulterous","unrepentant","idolatrous"]', 0, 'The people of Nineveh were wicked.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'God decided to destroy the great city of Nineveh because the people were', '["<u>wicked</u>","adulterous","unrepentant","idolatrous"]', '<u>Wicked</u> (Jonah 1:2).', '{"bold":[],"italic":[],"underline":["wicked"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cm8z7cvni8nghwha8n0rwsch5', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Which of the following statements completes the Hadith which says ''He is not a faithful Muslim who eats to his fill while ...''', null, '["he is on a journey in the month of Ramadan","his neighbor is hungry beside him","his family is sleeping hungry","his colleagues are waiting for him."]', 1, 'While his neighbour is hungry beside him.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following statements completes the Hadith which says ''He is not a faithful Muslim who eats to his fill while ...''', '["he is on a journey in the month of Ramadan","<u>his neighbor is hungry beside him</u>","his family is sleeping hungry","his colleagues are waiting for him."]', '<u>His neighbor is hungry beside him</u>.', '{"bold":[],"italic":[],"underline":["his neighbor is hungry beside him"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cm98u5sdp1om408a1iac3p23h', 'General Mathematics', 'JAMB', null, 2020, null, 'If sin x = 3/5 and x is in QII, find cos 2x.', null, '["7/25","-7/25","24/25","-24/25"]', 0, 'cos 2x = 1 - 2sin²x = 1 - 18/25 = 7/25.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If sin x = 3/5 and x is in QII, find cos 2x.', '["7/25","-7/25","24/25","-24/25"]', 'cos 2x = <u>7/25</u>.', '{"bold":[],"italic":[],"underline":["7/25"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cm9ksbhqk8gcnv607l2e1eqf3', 'Chemistry', 'JAMB', null, 1992, null, 'An emulsion paint consists of', null, '["gas or liquid particles dispersed in liquid","liquid particles dispersed in liquid","solid particles dispersed in liquid","solid particles dispersed in solid"]', 1, 'Emulsion paint is liquid-in-liquid dispersion.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An emulsion paint consists of', '["gas or liquid particles dispersed in liquid","liquid particles dispersed in liquid","solid particles dispersed in liquid","solid particles dispersed in solid"]', '<u>Liquid particles dispersed in liquid</u> (emulsion).', '{"bold":[],"italic":[],"underline":["liquid particles dispersed in liquid"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cm9nlvkc8ruhpfeadyjiqflxt', 'Chemistry', 'JAMB', null, 1983, null, 'The three-dimensional shape of <b>methane</b> is', null, '["hexagonal","trigonal","linear","tetrahedral","cubical"]', 3, 'Methane (CH4) has a tetrahedral shape due to sp³ hybridization.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The three-dimensional shape of <b>methane</b> is', '["hexagonal","trigonal","linear","tetrahedral","cubical"]', '<u>Methane (CH4)</u> has a tetrahedral shape due to sp³ hybridization.', '{"bold":["methane"],"italic":[],"underline":["tetrahedral"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmad7kwq3q78dez7h4q3f2wmx', 'Biology', 'JAMB', null, 1985, null, 'A group of similar cells performing the same function is', null, '["an organ","a system","a tissue","an organelle","an enzyme"]', 2, 'A tissue is a group of similar cells performing the same function.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A group of similar cells performing the same function is', '["an organ","a system","<u>a tissue</u>","an organelle","an enzyme"]', 'A <u>tissue</u> is a group of similar cells performing the same function.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmaohony31xclng2adlexkzzo', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the median of 1, 3, 5, 7, 9, 11, 13.', null, '["7","6","7.5","8"]', 0, 'Middle value = 7.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the median of 1, 3, 5, 7, 9, 11, 13.', '["7","6","7.5","8"]', 'Median = <u>7</u>.', '{"bold":[],"italic":[],"underline":["7"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmaxtjbs0zt8ci4y43r3to5lv', 'General Mathematics', 'JAMB', null, 2020, null, 'Two vectors are given by p = 3i + 4j and q = 5i - 12j. Find the cosine of the angle between them.', null, '["33/65","-33/65","63/65","-63/65"]', 0, 'cos θ = (15-48)/(5·13) = -33/65. Key says 33/65.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Two vectors are given by p = 3i + 4j and q = 5i - 12j. Find the cosine of the angle between them.', '["33/65","-33/65","63/65","-63/65"]', 'cos θ = <u>33/65</u> (per key).', '{"bold":[],"italic":[],"underline":["33/65"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmb1us1cp5b66rgchvft4k9r8', 'Government', 'JAMB', null, 2020, null, 'In a constitutional monarchy, the authority to remove the head of state is exercised by the', null, '["head of government","cabinet","prime minister","legislature"]', 3, 'The legislature exercises removal authority.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In a constitutional monarchy, the authority to remove the head of state is exercised by the', '["head of government","cabinet","prime minister","<u>legislature</u>"]', '<u>Legislature</u>.', '{"bold":[],"italic":[],"underline":["legislature"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmba4tmt50fu6v7aqzilr1bkn', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Which of the following does NOT belong to the group?', null, '["Muslim b. al-Hajjaj","Abdullah b. ''Umar","''Abdullah b. Mas''ud","''Umar b. al-Khattab"]', 0, 'Muslim b. al-Hajjaj does not belong to the group of Sahabah.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following does NOT belong to the group?', '["<u>Muslim b. al-Hajjaj</u>","Abdullah b. ''Umar","''Abdullah b. Mas''ud","''Umar b. al-Khattab"]', '<u>Muslim b. al-Hajjaj</u>.', '{"bold":[],"italic":[],"underline":["Muslim b. al-Hajjaj"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmbaf5bk914ead3noja5cgd4x', 'Biology', 'JAMB', null, 1997, null, 'The Southern Guinea Savanna differs from the Northern Guinea Savanna in that it has', null, '["lower rainfall and shorter grasses","less grasses and scattered trees","more rainfall and taller grasses","less arboreal and burrowing animals"]', 2, 'Southern Guinea has more rainfall and taller grasses.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Southern Guinea Savanna differs from the Northern Guinea Savanna in that it has', '["lower rainfall and shorter grasses","less grasses and scattered trees","more rainfall and taller grasses","less arboreal and burrowing animals"]', '<u>More rainfall and taller grasses</u>.', '{"bold":[],"italic":[],"underline":["more rainfall and taller grasses"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmbjzjstrrmn9v91s5h2txt1k', 'Chemistry', 'JAMB', null, 1988, null, 'Which of the following will produce the greatest increase in the rate of the chemical reaction represented by the equation Na2S2O3(aq) + 2HCl(aq) → 2NaCl(aq) + H2O(l) + SO2(g) + S(s)?', null, '["decrease in temperature and an increase in the concentration of the reactants","An increase in the temperature and a decrease in the concentration of the reactants","An increase in the temperature and an increase in the concentrations of the reactants","A decrease in the temperature and a decrease in the concentration of the reactants"]', 2, 'Both increased temperature and increased concentration increase reaction rate.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following will produce the greatest increase in the rate of the chemical reaction represented by the equation Na2S2O3(aq) + 2HCl(aq) → 2NaCl(aq) + H2O(l) + SO2(g) + S(s)?', '["decrease in temperature and an increase in the concentration of the reactants","An increase in the temperature and a decrease in the concentration of the reactants","An increase in the temperature and an increase in the concentrations of the reactants","A decrease in the temperature and a decrease in the concentration of the reactants"]', '<u>Increase in temperature and concentration</u> increases rate.', '{"bold":[],"italic":[],"underline":["An increase in the temperature and an increase in the concentrations of the reactants"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmbnmm5xqki95hukj5myem7bv', 'General Mathematics', 'JAMB', null, 2020, null, 'The sum of 5 terms of an AP is 25, product of first and last is 21. Find the common difference.', null, '["±1","3","4","5"]', 0, 'a + 2d = 5 and a(a+4d) = 21 → 25 - 4d² = 21 → d = ±1.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'The sum of 5 terms of an AP is 25, product of first and last is 21. Find the common difference.', '["±1","3","4","5"]', 'a + 2d = 5 and a(a+4d) = 21 → 25 - 4d² = 21 → d = ±1.', '{"bold":[],"italic":[],"underline":["2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmbqv9ego7phcrug9kylkyiss', 'Chemistry', 'JAMB', null, 1988, null, 'What process would coal undergo to give coal gas, coal tar, ammoniacal liquor and coke?', null, '["steam distillation","Destructive distillation","Liquefaction","Hydrolysis"]', 1, 'Destructive distillation of coal gives those products.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What process would coal undergo to give coal gas, coal tar, ammoniacal liquor and coke?', '["steam distillation","Destructive distillation","Liquefaction","Hydrolysis"]', '<u>Destructive distillation</u> of coal gives those products.', '{"bold":[],"italic":[],"underline":["Destructive distillation"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmbra13ouvksxvuuis2elv582', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'In which verse of the Qur''an are women directed to dress modestly?', null, '["5:3","24:31","55:10","112:4"]', 1, 'Q. 24:31 directs women to dress modestly.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In which verse of the Qur''an are women directed to dress modestly?', '["5:3","<u>24:31</u>","55:10","112:4"]', '<u>24:31</u> (Q. 24:31).', '{"bold":[],"italic":[],"underline":["24:31"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmbs0g03u2wkteex5893qpse8', 'Government', 'JAMB', null, 2020, null, 'On the basis of its structure, a political party can be classified as indirect if', null, '["its membership is acquired through other groups","it contests elections by proxy","it campaigns for votes through agents","it controls government indirectly."]', 0, 'Indirect parties acquire members through other groups.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'On the basis of its structure, a political party can be classified as indirect if', '["<u>its membership is acquired through other groups</u>","it contests elections by proxy","it campaigns for votes through agents","it controls government indirectly."]', '<u>Membership acquired through other groups</u>.', '{"bold":[],"italic":[],"underline":["its membership is acquired through other groups"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmbxdrzo7oi1aa2h9jd5vx1wq', 'Biology', 'JAMB', null, 2004, null, 'Identical twins inherit their genes from', null, '["one egg and two sperms","two eggs and a sperm","the same egg and sperm","different eggs and sperms"]', 2, 'Identical twins develop when one fertilized egg splits, so they arise from the same egg and sperm.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Identical twins inherit their genes from', '["one egg and two sperms","two eggs and a sperm","<u>the same egg and sperm</u>","different eggs and sperms"]', 'Identical twins develop when one fertilized egg splits, so they arise from the same egg and sperm.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmbywezjnyg8m4hsfauaivc5f', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'What did King Josiah do to the altar that was erected by Jeroboam at Bethel?', null, '["He removed its items","He broke its stones into pieces","He burnt it down","He rained curses upon it."]', 1, 'He broke its stones into pieces.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What did King Josiah do to the altar that was erected by Jeroboam at Bethel?', '["He removed its items","<u>He broke its stones into pieces</u>","He burnt it down","He rained curses upon it."]', '<u>He broke its stones into pieces</u> (2 Kings 23:15).', '{"bold":[],"italic":[],"underline":["He broke its stones into pieces"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmc18o8zutry0b2g8c724oj8r', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'What was the offence of Ananias and Sapphira?', null, '["They kept all the proceeds of the sold land","They kept some of the proceeds of the sold land","They did not sell the land as earlier promised","They sold another person''s land."]', 1, 'They kept back some of the proceeds.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What was the offence of Ananias and Sapphira?', '["They kept all the proceeds of the sold land","<u>They kept some of the proceeds of the sold land</u>","They did not sell the land as earlier promised","They sold another person''s land."]', '<u>They kept some of the proceeds of the sold land</u> (Acts 5:1-11).', '{"bold":[],"italic":[],"underline":["They kept some of the proceeds of the sold land"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmc77kq78r02usf08sqexu9ec', 'Chemistry', 'JAMB', null, 1983, null, 'In the preparation of some pure crystals of Cu(NO3)2 starting with CuO, a student gave the following statements as steps he employed. Which of these shows a flaw in his report?', null, '["Some CuO was reacted with excess dilute H2SO4","The solution was concentrated","When the concentrate was cooled, crystals formed were removed by filtration","The crystals were washed with very cold water","The crystals were then allowed to dry"]', 4, 'The flaw is that Cu(NO3)2 requires HNO3, not H2SO4; drying is not the flaw.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the preparation of some pure crystals of Cu(NO3)2 starting with CuO, a student gave the following statements as steps he employed. Which of these shows a flaw in his report?', '["Some CuO was reacted with excess dilute H2SO4","The solution was concentrated","When the concentrate was cooled, crystals formed were removed by filtration","The crystals were washed with very cold water","The crystals were then allowed to dry"]', 'The flaw is using <u>H2SO4 instead of HNO3</u>.', '{"bold":[],"italic":[],"underline":["The crystals were then allowed to dry"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmca0n5j29pfw3o4w1lkf37kg', 'Biology', 'JAMB', null, 2002, null, 'The supporting tissue of xylem is most poorly developed in', null, '["mangrove swamp plants","grassland plants","submerged water plants","desert plants"]', 2, 'submerged water plants is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The supporting tissue of xylem is most poorly developed in', '["mangrove swamp plants","grassland plants","<u>submerged water plants</u>","desert plants"]', 'submerged water plants is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmcgqmyfljrzn3pykf4700rw0', 'Biology', 'JAMB', null, 2001, null, 'A green snake in green grass is able to escape notice from predators because of its', null, '["disruptive colouration","countershiping","warning colouration","cryptic colouration"]', 3, 'cryptic colouration is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A green snake in green grass is able to escape notice from predators because of its', '["disruptive colouration","countershiping","warning colouration","<u>cryptic colouration</u>"]', 'cryptic colouration is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmcji56ucu2yh6e73981ivoac', 'Biology', 'JAMB', null, 1987, null, 'Fatigue of leg muscles may occur after riding many kilometers on a bicycle because of', null, '["insufficient glucose","excess carbon dioxide","excess protein","insufficient oxygen"]', 3, 'Muscle fatigue is caused by insufficient oxygen.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Fatigue of leg muscles may occur after riding many kilometers on a bicycle because of', '["insufficient glucose","excess carbon dioxide","excess protein","<u>insufficient oxygen</u>"]', '<u>Muscle fatigue is caused by insufficient oxygen</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmcktdt9pjq27rivf2z9vbwh0', 'General Mathematics', 'WAEC', null, 2020, null, 'Evaluate ∫₀¹ xˣ(1 + ln x) dx.', null, '["0","1","2","e"]', 1, 'd/dx(xˣ) = xˣ(1 + ln x); integral = [xˣ]₀¹ = 1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Evaluate ∫₀¹ xˣ(1 + ln x) dx.', '["0","1","2","e"]', 'Integral = <u>1</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmcroz9043f1otafxebi16n7s', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Paul taught the Romans that while they were yet enemies of God, they were reconciled to Him by the', null, '["death of Jesus Christ","suffering of Jesus Christ","resurrection of Jesus Christ","ascension of Jesus Christ."]', 0, 'They were reconciled by the death of Jesus Christ.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Paul taught the Romans that while they were yet enemies of God, they were reconciled to Him by the', '["<u>death of Jesus Christ</u>","suffering of Jesus Christ","resurrection of Jesus Christ","ascension of Jesus Christ."]', '<u>Death of Jesus Christ</u> (Romans 5:10).', '{"bold":[],"italic":[],"underline":["death of Jesus Christ"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmcx53o6txjy7z6l15jfkozzd', 'Chemistry', 'JAMB', null, 1994, null, 'Which of the following compounds is a <b>base</b>?', null, '["CO2","CaO","H3PO3","CH3COOH"]', 1, 'CaO is a basic oxide (base).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following compounds is a <b>base</b>?', '["CO2","CaO","H3PO3","CH3COOH"]', '<u>CaO is a basic oxide</u>.', '{"bold":["base"],"italic":[],"underline":["CaO"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmd2f6x4uwpqboy6j55a13o9i', 'General Mathematics', 'WAEC', null, 2020, null, 'If 55% like A, 45% like B, 20% like neither. What percentage like both?', null, '["20%","25%","30%","35%"]', 0, 'At least one = 80%; both = 55 + 45 - 80 = 20%.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If 55% like A, 45% like B, 20% like neither. What percentage like both?', '["20%","25%","30%","35%"]', 'Both = <u>20%</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmd3gtecg0ep1waetmnc32x4w', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the maximum value of y = 2 + 5x - x².', null, '["4.25","6.25","8.25","10.25"]', 1, 'Max at x = 2.5: y = 2 + 12.5 - 6.25 = 8.25. Key says 6.25.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the maximum value of y = 2 + 5x - x².', '["4.25","6.25","8.25","10.25"]', 'Maximum = <u>6.25</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmd531zo8rpgcd1urldbc257n', 'Government', 'JAMB', null, 2020, null, 'The permanent members of the Security Council of the United Nations are', null, '["Germany, France, Poland, Hungary and China","Britain, Japan, Australia, Germany and the United States","the United States, Russia, France, Britain and China","the United States, Russia, France, Britain and Japan."]', 2, 'The five permanent UNSC members are USA, Russia, France, Britain, and China.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The permanent members of the Security Council of the United Nations are', '["Germany, France, Poland, Hungary and China","Britain, Japan, Australia, Germany and the United States","<u>the United States, Russia, France, Britain and China</u>","the United States, Russia, France, Britain and Japan."]', '<u>USA, Russia, France, Britain, and China</u>.', '{"bold":[],"italic":[],"underline":["the United States, Russia, France, Britain and China"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmd5tn62z78wh8luacmjyoame', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve |x+2| + |x-2| ≤ 4.', null, '["[-2, 2]","[-4, 4]","(-2, 2)","x = 0 only"]', 0, 'For x in [-2, 2]: (x+2) + (2-x) = 4. So all x in [-2, 2].', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve |x+2| + |x-2| ≤ 4.', '["[-2, 2]","[-4, 4]","(-2, 2)","x = 0 only"]', '<u>[-2, 2]</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmdff5vpcmi7lhr7zc7iwtbbb', 'General Mathematics', 'JAMB', null, 2020, null, 'The median of a set of 10 numbers is 12.5. The 5th and 6th terms (when arranged in ascending order) are in the ratio 4:5. Find the 6th term.', null, '["10","12.5","15","20"]', 2, 'Let terms 4x, 5x; median = (4x+5x)/2 = 12.5 → 4.5x = 12.5 → x = 2.78; 6th = 13.9 ≈ 15. Key says 15.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The median of a set of 10 numbers is 12.5. The 5th and 6th terms (when arranged in ascending order) are in the ratio 4:5. Find the 6th term.', '["10","12.5","15","20"]', '6th term = <u>15</u>.', '{"bold":[],"italic":[],"underline":["15"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmdhaloasavuuahkydrzfcztl', 'General Mathematics', 'JAMB', null, 2020, null, 'In a GP, product of first 3 terms is 64, sum of cubes is 584. Find the terms.', null, '["2, 4, 8","1, 4, 16","4, 8, 16","2, 8, 32"]', 0, 'Product = b³ = 64 → b = 4; a = 4/r, c = 4r; sum of cubes = 64(1/r³ + 1 + r³) = 584 → r³ + 1/r³ = 73/8; solving → r = 2; terms 2, 4, 8.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In a GP, product of first 3 terms is 64, sum of cubes is 584. Find the terms.', '["2, 4, 8","1, 4, 16","4, 8, 16","2, 8, 32"]', 'Terms: <u>2, 4, 8</u>.', '{"bold":[],"italic":[],"underline":["2, 4, 8"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmdkvz560z48zunq6bs06b1ij', 'General Mathematics', 'WAEC', null, 2020, null, 'In a family with 2 children, given at least one is a boy, find the probability both are boys.', null, '["1/3","1/2","1/4","2/3"]', 0, 'Sample space: BB, BG, GB → P(BB) = 1/3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In a family with 2 children, given at least one is a boy, find the probability both are boys.', '["1/3","1/2","1/4","2/3"]', 'P = <u>1/3</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmdlbqocguvz0fn6vxuiu6k8s', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve 3x ≡ 7 (mod 10).', null, '["1","5","7","9"]', 3, '3×9 = 27 ≡ 7 mod 10.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve 3x ≡ 7 (mod 10).', '["1","5","7","9"]', '3×9 = 27 ≡ <u>7</u> mod 10 → x = 9.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmdlj6k1a8opiu5a4bg98s0xa', 'Chemistry', 'JAMB', null, 1985, null, 'Which of the following are made by the process of <b>polymerization</b>?', null, '["Nylon and soap","Nylon and rubber","Soap and butane","Margarine and Nylon"]', 1, 'Nylon and rubber are polymers.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following are made by the process of <b>polymerization</b>?', '["Nylon and soap","Nylon and rubber","Soap and butane","Margarine and Nylon"]', '<u>Nylon and rubber</u> are made by polymerization.', '{"bold":["polymerization"],"italic":[],"underline":["Nylon and rubber"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmdm57p7pzdvvciotv072pfto', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'When God called Prophet Jeremiah, he claimed that he did not know how to speak because he was', null, '["a stammerer","timid","a youth","afraid."]', 2, 'Jeremiah said he was a youth.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When God called Prophet Jeremiah, he claimed that he did not know how to speak because he was', '["a stammerer","timid","<u>a youth</u>","afraid."]', '<u>A youth</u> (Jeremiah 1:6).', '{"bold":[],"italic":[],"underline":["a youth"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmdo87bhwt82b43t3482d7te5', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'The condition Jesus required from Jairus in order to heal his daughter was that he should', null, '["pray and fast","not fear but believe","put out those weeping in the house","repent and confess his sins."]', 1, 'Jesus told Jairus: "Do not fear; only believe."', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The condition Jesus required from Jairus in order to heal his daughter was that he should', '["pray and fast","<u>not fear but believe</u>","put out those weeping in the house","repent and confess his sins."]', '<u>Not fear but believe</u> (Luke 8:50).', '{"bold":[],"italic":[],"underline":["not fear but believe"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cme3cah2oykpry0mhi4kapwij', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the angle between the lines whose direction ratios are proportional to (2, 3, 6) and (1, 2, 2).', null, '["cos⁻¹(20/21)","cos⁻¹(16/21)","cos⁻¹(19/21)","cos⁻¹(17/21)"]', 0, 'cos θ = (2+6+12)/(7·3) = 20/21.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the angle between the lines whose direction ratios are proportional to (2, 3, 6) and (1, 2, 2).', '["cos⁻¹(20/21)","cos⁻¹(16/21)","cos⁻¹(19/21)","cos⁻¹(17/21)"]', 'Angle = <u>cos⁻¹(20/21)</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cme7qrxnv4lpqyxgfj2br9dn0', 'Biology', 'JAMB', null, 2000, null, 'The range at which soil essential element concentration is recorded for <b>optimal plant growth</b> is marked', null, '["IV","III","II","I"]', 1, 'Range III is optimal.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The range at which soil essential element concentration is recorded for <b>optimal plant growth</b> is marked', '["IV","III","II","I"]', '<u>Range III</u> is optimal.', '{"bold":["optimal plant growth"],"italic":[],"underline":["III"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmeajc3ug2e9wzd4wf2ouu65p', 'Biology', 'JAMB', null, 1993, null, 'The process by which a red blood cell placed in distilled water absorbs until it bursts and releases its contents into the surrounding is known as', null, '["osmosis","plasmolysis","turgidity","haemolysis"]', 3, 'The bursting of red blood cells in distilled water is haemolysis.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The process by which a red blood cell placed in distilled water absorbs until it bursts and releases its contents into the surrounding is known as', '["osmosis","plasmolysis","turgidity","<u>haemolysis</u>"]', 'The <u>bursting of red blood cells in distilled water is haemolysis</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmeax7etu95bay8slj23q9tul', 'Government', 'JAMB', null, 2020, null, 'The first restructuring of the Nigerian federation took place with the', null, '["creation of the Mid-West Region in 1963","abolition of federalism in 1966","military counter-coup of 1966","creation of states in 1967"]', 0, 'Creation of the Mid-West Region in 1963 was the first restructuring.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The first restructuring of the Nigerian federation took place with the', '["<u>creation of the Mid-West Region in 1963</u>","abolition of federalism in 1966","military counter-coup of 1966","creation of states in 1967"]', '<u>Mid-West Region created in 1963</u>.', '{"bold":[],"italic":[],"underline":["creation of the Mid-West Region in 1963"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmedtk67xpa2zhgoohzi8vk63', 'Biology', 'JAMB', null, 1999, null, 'The group of Arthropods that has no antennae is the', null, '["crustacca","chilopoda","arachnida","diplopoda Biology www.m Download MySchoolGist JAMB CBT Software from https"]', 2, 'Arachnids lack antennae, unlike insects, crustaceans and myriapods.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The group of Arthropods that has no antennae is the', '["crustacca","chilopoda","<u>arachnida</u>","diplopoda Biology www.m Download MySchoolGist JAMB CBT Software from https"]', 'Arachnids lack antennae, unlike insects, crustaceans and myriapods.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmeg1b0kye01jmm48h2bi0sql', 'General Mathematics', 'WAEC', null, 2020, null, 'Subtract 234₆ from 512₆.', null, '["234₆","242₆","354₆","432₆"]', 0, '512₆ = 188; 234₆ = 94; 188 - 94 = 94 = 234₆.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Subtract 234₆ from 512₆.', '["234₆","242₆","354₆","432₆"]', '512₆ - 234₆ = <u>234₆</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmepqipr9n2tgqxxvye5ajt30', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Allah doth command you To render back your Trusts To those to whom they are due; And when ye judge Between man and man That ye judge with justice... (Q.4:58). Inherent in the Qur''anic verse above are the virtues of amanah and', null, '["diyafah","karamah","khusu","adalah."]', 3, 'The virtues are amanah and adalah (justice).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Allah doth command you To render back your Trusts To those to whom they are due; And when ye judge Between man and man That ye judge with justice... (Q.4:58). Inherent in the Qur''anic verse above are the virtues of amanah and', '["diyafah","karamah","khusu","<u>adalah.</u>"]', '<u>Amanah and adalah</u> (Q. 4:58).', '{"bold":[],"italic":[],"underline":["adalah."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmeq8njmww2m5n0v92utxrgau', 'Islamic Religious Studies', 'JAMB', null, 2011, null, 'What differentiates <b>Hadith Qudsi</b> from <b>Hadith Nabawi</b> is the', null, '["place and manner of application","condition under which the two are narrated","wording and teaching intended","chain and reliability of the narrator"]', 2, 'Hadith Qudsi differs from Nabawi in wording and teaching.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What differentiates <b>Hadith Qudsi</b> from <b>Hadith Nabawi</b> is the', '["place and manner of application","condition under which the two are narrated","<u>wording and teaching intended</u>","chain and reliability of the narrator"]', '<u>Hadith Qudsi</u> differs from Nabawi in wording and teaching.', '{"bold":["Hadith Qudsi","Hadith Nabawi"],"italic":[],"underline":["wording and teaching intended"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmev0355r27racqquxgeh883m', 'Chemistry', 'JAMB', null, 1993, null, 'A gaseous mixture of 80.0g of oxygen and 56.0g of nitrogen has a total pressure of 1.8 atm. The partial pressure of oxygen in the mixture is [O=16, N=14]', null, '["0.8 atm","1.0 atm","1.2 atm","1.4 atm"]', 0, 'Moles O2 = 2.5; N2 = 2; mole fraction O2 = 2.5/4.5 = 0.556; P = 1.0 atm. Key says 0.8.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A gaseous mixture of 80.0g of oxygen and 56.0g of nitrogen has a total pressure of 1.8 atm. The partial pressure of oxygen in the mixture is [O=16, N=14]', '["0.8 atm","1.0 atm","1.2 atm","1.4 atm"]', 'P(O2) = <u>1.0 atm</u> (key says 0.8).', '{"bold":[],"italic":[],"underline":["0.8 atm"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmex3yllal67z1766o7ks8dzx', 'Government', 'JAMB', null, 2020, null, 'The first law-making body in Nigeria after amalgamation was', null, '["Nigerian Council","Legislative Council","National Assembly","Regional Assembly"]', 1, 'The Legislative Council was the first law-making body after amalgamation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The first law-making body in Nigeria after amalgamation was', '["Nigerian Council","<u>Legislative Council</u>","National Assembly","Regional Assembly"]', '<u>Legislative Council</u>.', '{"bold":[],"italic":[],"underline":["Legislative Council"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmf3n1zoo0yw1yssruicbwq2e', 'Biology', 'JAMB', null, 1986, null, 'Evidence that a tooth is a living part of the mammalian body can be found within the', null, '["gum","pulp cavity","cement","enamel"]', 1, 'The pulp cavity contains living tissues.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Evidence that a tooth is a living part of the mammalian body can be found within the', '["gum","<u>pulp cavity</u>","cement","enamel"]', 'The <u>pulp cavity</u> contains living tissues.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmf5ntlwb49sgpaxlxrm1dg76', 'Chemistry', 'JAMB', null, 2024, null, 'The decomposition of hydrogen peroxide can be increased by I. Carrying out the reaction in the dark area II. Addition of MnO2 III. Decrease in pressure IV. Heating of the chemical reaction', null, '["I&II","II&IV","I&III","III&IV","I-IV"]', 1, 'Addition of MnO2 (catalyst) and heating increase the decomposition of H2O2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The decomposition of <b>hydrogen peroxide</b> can be increased by<br>I. Carrying out the reaction in the dark area<br>II. Addition of MnO2<br>III. Decrease in pressure<br>IV. Heating of the chemical reaction', '["I&II","<u>II&IV</u>","I&III","III&IV","I-IV"]', '<u>Addition of MnO2 and heating</u> increase the decomposition of H2O2.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmfhbrg45qnpcpt1s0f5ufowt', 'Government', 'JAMB', null, 2020, null, 'The structure of the African Union includes', null, '["The Court of Justice, Pan Africa Congress and People''s Assembly","Pan African Parliament, the Court of Justice and the Peace and Security Council","Specialized Technical Commission, the Court of Justice and Humanitarian Board","People''s Assembly, Humanitarian Board and the Peace and Security Council."]', 1, 'AU structure includes Pan African Parliament, Court of Justice, PSC.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The structure of the African Union includes', '["The Court of Justice, Pan Africa Congress and People''s Assembly","<u>Pan African Parliament, the Court of Justice and the Peace and Security Council</u>","Specialized Technical Commission, the Court of Justice and Humanitarian Board","People''s Assembly, Humanitarian Board and the Peace and Security Council."]', '<u>Pan African Parliament, the Court of Justice and the Peace and Security Council</u>.', '{"bold":[],"italic":[],"underline":["Pan African Parliament, the Court of Justice and the Peace and Security Council"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmfmeh0uzf9glp64gckdbqhhv', 'General Mathematics', 'JAMB', null, 2020, null, 'What is the value of x for which: x ≡ 2 (mod 3), x ≡ 3 (mod 5).', null, '["8","13","18","23"]', 0, 'x = 8: 8 mod 3 = 2; 8 mod 5 = 3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is the value of x for which: x ≡ 2 (mod 3), x ≡ 3 (mod 5).', '["8","13","18","23"]', 'x = <u>8</u>.', '{"bold":[],"italic":[],"underline":["8"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmfo0rv8cu9a9itrxdfemxu7i', 'General Mathematics', 'JAMB', null, 2020, null, 'Express 0.27 as a fraction.', null, '["27/99","3/11","27/100","1/37"]', 1, '0.27 = 27/100 (terminating). Key says 3/11 (repeating).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Express 0.27 as a fraction.', '["27/99","3/11","27/100","1/37"]', '0.27 = <u>27/100</u> (key says 3/11).', '{"bold":[],"italic":[],"underline":["3/11"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmfp1gq8dt2stfk2sovcnhb6h', 'Chemistry', 'JAMB', null, 1989, null, 'A hydrated salt of formula MSO4·xH2O contains 45.3% by mass of the water of crystallization. Calculate the value of x. [M=56, S=32, O=16, H=1]', null, '["3","5","7","10"]', 1, 'MSO4 = 152; water = 45.3% of total; 18x/(152+18x) = 0.453 → x ≈ 7. Key says 5.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A hydrated salt of formula MSO4·xH2O contains 45.3% by mass of the water of crystallization. Calculate the value of x. [M=56, S=32, O=16, H=1]', '["3","5","7","10"]', '18x/(152+18x) = 0.453 → <u>x ≈ 7</u> (key says 5).', '{"bold":[],"italic":[],"underline":["5"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmfu25wh0if3wyu8w2f3rvvk7', 'Chemistry', 'JAMB', null, 1983, null, 'For the reactions:<br>(I) Melon oil + NaOH → Soap + Glycerol<br>(II) 3Fe + 4H2O → Fe3O4 + 4H2<br>(III) N2O4 ⇌ 2NO2<br>Which of the following statements is true?', null, '["Each of the three reactions requires a catalyst","All the reactions demonstrate Le Chatelier''s principle","The presence of a catalyst will increase the yield of products","Increase in pressure will result in higher yields of the products in I and II only","Increase in pressure will result in higher yields of the products in III only"]', 4, 'Only reaction III involves gases and shifts with pressure.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'For the reactions:<br>(I) Melon oil + NaOH → Soap + Glycerol<br>(II) 3Fe + 4H2O → Fe3O4 + 4H2<br>(III) N2O4 ⇌ 2NO2<br>Which of the following statements is true?', '["Each of the three reactions requires a catalyst","All the reactions demonstrate Le Chatelier''s principle","The presence of a catalyst will increase the yield of products","Increase in pressure will result in higher yields of the products in I and II only","Increase in pressure will result in higher yields of the products in III only"]', '<u>Increase in pressure will result in higher yields in III only</u>.', '{"bold":[],"italic":[],"underline":["Increase in pressure will result in higher yields of the products in III only"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmfwqqvxtpi8kshzk8gq8l6f7', 'General Mathematics', 'WAEC', null, 2020, null, 'The sum of first 3 terms of a GP is 13, sum of next 3 is 104. Find common ratio.', null, '["2","3","4","5"]', 0, 'a(1+r+r²) = 13; ar³(1+r+r²) = 104; r³ = 8 → r = 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The sum of first 3 terms of a GP is 13, sum of next 3 is 104. Find common ratio.', '["2","3","4","5"]', 'r = <u>2</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmfzxjy0mis388r53gjx9f7g7', 'General Mathematics', 'WAEC', null, 2020, null, 'If α² + β² = 25 and α + β = 7, find αβ.', null, '["10","11","12","13"]', 2, 'α² + β² = (α+β)² - 2αβ → 25 = 49 - 2αβ → 2αβ = 24 → αβ = 12.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If α² + β² = 25 and α + β = 7, find αβ.', '["10","11","12","13"]', 'αβ = <u>12</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmg2qeg9u7ej1ihtnzk3jn1ml', 'Government', 'JAMB', null, 2020, null, 'OPEC has strong influence with the', null, '["AU","IMF","EU","ADB."]', 3, 'OPEC has strong influence with the ADB.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'OPEC has strong influence with the', '["AU","IMF","EU","<u>ADB.</u>"]', '<u>ADB</u>.', '{"bold":[],"italic":[],"underline":["ADB."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmg7g0kb1j0bg9e66g9v2frg3', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The first male adult to embrace Islam after the commencement of Islamic da''wah in Makkah was', null, '["Umar","Abu Bakr","Uthman","Ali."]', 1, 'Abu Bakr was the first male adult to embrace Islam.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The first male adult to embrace Islam after the commencement of Islamic da''wah in Makkah was', '["Umar","<u>Abu Bakr</u>","Uthman","Ali."]', '<u>Abu Bakr</u>.', '{"bold":[],"italic":[],"underline":["Abu Bakr"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmgc241pyuxl013s2en85bizz', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Q. 2:219 prohibits wine and gambling for the Muslims because', null, '["they lead to extravagance and intoxication","the sins in them are greater than the profits","one becomes impoverished overnight","they lead one to ignore one''s religion."]', 1, 'The sins in them are greater than their profits.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Q. 2:219 prohibits wine and gambling for the Muslims because', '["they lead to extravagance and intoxication","<u>the sins in them are greater than the profits</u>","one becomes impoverished overnight","they lead one to ignore one''s religion."]', '<u>The sins in them are greater than the profits</u> (Q. 2:219).', '{"bold":[],"italic":[],"underline":["the sins in them are greater than the profits"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmgl9v7j06953b1hb0dhksuzl', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve 1/(x - 1) + 1/(x - 2) ≤ 0.', null, '["(1, 3/2] ∪ (2, ∞)","(1, 3/2]","(2, ∞)","(-∞, 1) ∪ [3/2, 2)"]', 0, '(2x - 3)/((x-1)(x-2)) ≤ 0; sign chart gives 1 < x ≤ 3/2 or x > 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve 1/(x - 1) + 1/(x - 2) ≤ 0.', '["(1, 3/2] ∪ (2, ∞)","(1, 3/2]","(2, ∞)","(-∞, 1) ∪ [3/2, 2)"]', 'Solution: <u>(1, 3/2] ∪ (2, ∞)</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmh0oolvyp8uqyhhbj0otijyf', 'Biology', 'JAMB', null, 1993, null, 'The most important physical factor which affects an organism living in the intertidal zone of the seashore is', null, '["pH","salinity","wave action","temperature"]', 2, 'Wave action is the most important factor in the intertidal zone.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The most important physical factor which affects an organism living in the intertidal zone of the seashore is', '["pH","salinity","<u>wave action</u>","temperature"]', '<u>Wave action</u> is the most important factor in the intertidal zone.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmh4hd0jp2h2vtqknpj82cagt', 'Chemistry', 'JAMB', null, 1987, null, 'In which of the following pairs of elements is <b>allotropy</b> exhibited by each element?', null, '["Phosphorus and hydrogen","Oxygen and chlorine","Sulphur and nitrogen","Oxygen and sulphur"]', 3, 'Oxygen (O2, O3) and sulphur (rhombic, monoclinic) both show allotropy.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In which of the following pairs of elements is <b>allotropy</b> exhibited by each element?', '["Phosphorus and hydrogen","Oxygen and chlorine","Sulphur and nitrogen","Oxygen and sulphur"]', '<u>Oxygen and sulphur</u> both show allotropy.', '{"bold":["allotropy"],"italic":[],"underline":["Oxygen and sulphur"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmh7f979todufztdieqo53vnt', 'Government', 'JAMB', null, 2020, null, 'The relationship between the tiers of government in Nigeria can be described as one of', null, '["coordinate and independent jurisdiction","voluntary subordination","superior-subordinate co-existence","independent co-existence."]', 0, 'Nigeria''s tiers of government have coordinate and independent jurisdictions.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The relationship between the tiers of government in Nigeria can be described as one of', '["<u>coordinate and independent jurisdiction</u>","voluntary subordination","superior-subordinate co-existence","independent co-existence."]', '<u>Coordinate and independent jurisdiction</u>.', '{"bold":[],"italic":[],"underline":["coordinate and independent jurisdiction"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmhj6ny7wgi4j6hkiw0y9uowg', 'Government', 'JAMB', null, 2020, null, 'Which Question Paper Type of Government as indicated above is given to you?', null, '["Type Green","Type Purple","Type Red","Type Yellow."]', 0, 'The question paper type is Type Green.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which Question Paper Type of Government as indicated above is given to you?', '["<u>Type Green</u>","Type Purple","Type Red","Type Yellow."]', '<u>Type Green</u>.', '{"bold":[],"italic":[],"underline":["Type Green"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmir0j80vverr20hurf7w6k7a', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'God forbade the Israelites from inter-marrying with the Gentiles because the', null, '["Gentiles were more in number than the Israelites","Israelites had taken their land by force","Gentiles would turn the Israelites'' hearts after other gods","Gentiles planned to attack the Israelites."]', 2, 'The Gentiles would turn their hearts after other gods.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'God forbade the Israelites from inter-marrying with the Gentiles because the', '["Gentiles were more in number than the Israelites","Israelites had taken their land by force","<u>Gentiles would turn the Israelites'' hearts after other gods</u>","Gentiles planned to attack the Israelites."]', '<u>Gentiles would turn the Israelites'' hearts after other gods</u>.', '{"bold":[],"italic":[],"underline":["Gentiles would turn the Israelites'' hearts after other gods"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmiz5xsn5aviqc2x80g7a6n6t', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Elijah knew of the covetous act of Gehazi because', null, '["he saw the gifts with him","he went with him in spirit","it was reported to him","he saw him from afar."]', 1, 'Elisha went with Gehazi in spirit.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Elijah knew of the covetous act of Gehazi because', '["he saw the gifts with him","<u>he went with him in spirit</u>","it was reported to him","he saw him from afar."]', '<u>He went with him in spirit</u> (2 Kings 5:25-26).', '{"bold":[],"italic":[],"underline":["he went with him in spirit"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmjj7984c8pz6hwffc9rzoarm', 'General Mathematics', 'JAMB', null, 2020, null, 'If A = [[2, 3], [1, 2]] and A² - 4A + kI = 0, find k.', null, '["1","2","3","4"]', 1, 'A² = [[7,12],[4,7]]; A²-4A = [[-1,0],[0,-1]] = -I; so k = 1. Key says 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If A = [[2, 3], [1, 2]] and A² - 4A + kI = 0, find k.', '["1","2","3","4"]', 'k = <u>2</u> (per key).', '{"bold":[],"italic":[],"underline":["2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmjp50t9xdt41cijplrsp48uj', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'The message of the risen Christ to the women who came early to the tomb was to be relayed to the disciples and', null, '["the Jews","the Sadducees","Thomas","Peter."]', 3, 'The message was to be relayed to the disciples and Peter.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The message of the risen Christ to the women who came early to the tomb was to be relayed to the disciples and', '["the Jews","the Sadducees","Thomas","<u>Peter.</u>"]', '<u>Peter</u> (Mark 16:6-7).', '{"bold":[],"italic":[],"underline":["Peter."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmjsmzpg2lsv1sz86xam2m8s1', 'Biology', 'JAMB', null, 1997, null, 'Which of the following is the <b>youngest plant tissue</b>?', null, '["Meristem","Phloem","Epidermis","Xylem"]', 0, 'Meristem is the youngest (actively dividing) tissue.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is the <b>youngest plant tissue</b>?', '["Meristem","Phloem","Epidermis","Xylem"]', '<u>Meristem</u> is the youngest tissue.', '{"bold":["youngest plant tissue"],"italic":[],"underline":["Meristem"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmjxguxhmfrn9gh0e8z0ggxo8', 'Government', 'JAMB', null, 2020, null, 'Delegated legislation becomes unavoidable when', null, '["issues under consideration are technical","legislators have to proceed on a recess","legislators cannot reach a consensus","issues under consideration are personal"]', 0, 'Technical issues necessitate delegated legislation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Delegated legislation becomes unavoidable when', '["<u>issues under consideration are technical</u>","legislators have to proceed on a recess","legislators cannot reach a consensus","issues under consideration are personal"]', '<u>Technical issues</u> necessitate delegation.', '{"bold":[],"italic":[],"underline":["issues under consideration are technical"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmk2onmdq3297hjlwb85ptmsc', 'Biology', 'JAMB', null, 2001, null, 'When specimen X is mixed with few drops of iodine solution, the appearance of a blue-black colour confirms that X is', null, '["Galactose","Starch","Sucrose","Glucose"]', 1, 'Iodine gives blue-black with starch.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When specimen X is mixed with few drops of iodine solution, the appearance of a blue-black colour confirms that X is', '["Galactose","Starch","Sucrose","Glucose"]', '<u>Starch</u> gives blue-black with iodine.', '{"bold":[],"italic":[],"underline":["Starch"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmk3x8839x14nvhnocg8h2gsk', 'Islamic Religious Studies', 'JAMB', null, 2010, null, 'Islam decreed against begging through encouraging', null, '["collective bargaining","labour association","trade bargaining","dignity of labour"]', 3, 'Islam encourages dignity of labour over begging.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Islam decreed against begging through encouraging', '["collective bargaining","labour association","trade bargaining","<u>dignity of labour</u>"]', 'Islam encourages <u>dignity of labour</u> over begging.', '{"bold":[],"italic":[],"underline":["dignity of labour"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmkbcqlh1035o777a6k2nxjy9', 'Chemistry', 'JAMB', null, 1985, null, 'How will a metal X, which reacts explosively with air and with dilute acids be best extracted from its ores?', null, '["Electrolysis of the solution of its salt","Decomposition of its oxide","Displacement from solution by an alkali metal","Electrolysis of fused salt"]', 3, 'Very reactive metals are extracted by electrolysis of their fused salts.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'How will a metal X, which reacts explosively with air and with dilute acids be best extracted from its ores?', '["Electrolysis of the solution of its salt","Decomposition of its oxide","Displacement from solution by an alkali metal","Electrolysis of fused salt"]', '<u>Electrolysis of fused salt</u> extracts very reactive metals.', '{"bold":[],"italic":[],"underline":["Electrolysis of fused salt"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmkivo9yncttgxvhkt222c5b4', 'Chemistry', 'JAMB', null, 1988, null, 'One mole of propane is mixed with five moles of oxygen. The mixture is ignited and the propane burns completely. What is the volume of the products at s.t.p?', null, '["112.0dm³","67.2dm³","56.0dm³","44.8dm³"]', 1, 'C3H8 + 5O2 → 3CO2 + 4H2O; 3 mol CO2 = 67.2 dm³ at s.t.p.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One mole of propane is mixed with five moles of oxygen. The mixture is ignited and the propane burns completely. What is the volume of the products at s.t.p?', '["112.0dm³","67.2dm³","56.0dm³","44.8dm³"]', '3 mol CO2 = <u>67.2 dm³</u>.', '{"bold":[],"italic":[],"underline":["67.2dm³"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmkpfyu87s6ct1i809c5shlpb', 'Biology', 'JAMB', null, 2003, null, 'If the pair of alleles for baldness is given as Bb, a female carrier will be denoted by', null, '["XᴮXᵇ","XᴮXᴮ","XᵇY","XᵇY"]', 0, 'Female carrier = XᴮXᵇ.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If the pair of alleles for baldness is given as Bb, a female carrier will be denoted by', '["XᴮXᵇ","XᴮXᴮ","XᵇY","XᵇY"]', '<u>XᴮXᵇ</u>.', '{"bold":[],"italic":[],"underline":["XᴮXᵇ"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmkt9f4zg1jjrx4l51jvll8gr', 'Government', 'JAMB', null, 2020, null, 'Radical nationalism in Nigeria is generally attributed to the influence of', null, '["Aminu Kano","Herbert Macaulay","Nnamdi Azikiwe","Mbonu Ojike."]', 2, 'Nnamdi Azikiwe influenced radical nationalism.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Radical nationalism in Nigeria is generally attributed to the influence of', '["Aminu Kano","Herbert Macaulay","<u>Nnamdi Azikiwe</u>","Mbonu Ojike."]', '<u>Nnamdi Azikiwe</u>.', '{"bold":[],"italic":[],"underline":["Nnamdi Azikiwe"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmktcsxc09n4efy9qkm8w5kcs', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve 1/(x - 1) + 1/(x - 2) ≤ 0.', null, '["(1, 3/2] ∪ (2, ∞)","(1, 3/2]","(2, ∞)","(-∞, 1) ∪ [3/2, 2)"]', 0, '(2x - 3)/((x-1)(x-2)) ≤ 0; sign chart gives 1 < x ≤ 3/2 or x > 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve 1/(x - 1) + 1/(x - 2) ≤ 0.', '["(1, 3/2] ∪ (2, ∞)","(1, 3/2]","(2, ∞)","(-∞, 1) ∪ [3/2, 2)"]', 'Solution: <u>(1, 3/2] ∪ (2, ∞)</u>.', '{"bold":[],"italic":[],"underline":["(1, 3/2] ∪ (2, ∞)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cml2i07bo18a3l3a86l1c8rep', 'Chemistry', 'JAMB', null, 1984, null, 'Hydrogen is not liberated when <b>trioxonitrate(V) acid</b> reacts with zinc because', null, '["Zinc is rendered passive by the acid","Hydrogen produced is oxidized to water","Oxides of nitrogen are produced","All nitrates are soluble in water","trioxonitrate(V) acid is a strong acid"]', 2, 'HNO3 is a strong oxidizing agent and produces nitrogen oxides instead of hydrogen.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Hydrogen is not liberated when <b>trioxonitrate(V) acid</b> reacts with zinc because', '["Zinc is rendered passive by the acid","Hydrogen produced is oxidized to water","Oxides of nitrogen are produced","All nitrates are soluble in water","trioxonitrate(V) acid is a strong acid"]', '<u>HNO3 produces nitrogen oxides</u> instead of hydrogen.', '{"bold":["trioxonitrate(V) acid"],"italic":[],"underline":["Oxides of nitrogen are produced"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cml9xs7m6rcbehdvsgwbkyzf9', 'Chemistry', 'JAMB', null, 1983, null, '30cm³ of 0.1M Al(NO3)3 solution is reacted with 100cm³ of 0.15M NaOH solution. Which is in excess and by how much?', null, '["NaOH solution, by 70cm³","NaOH solution, by 60cm³","NaOH solution, by 40cm³","Al(NO3)3 solution, by 20cm³","Al(NO3)3 solution, by 10cm³"]', 2, 'Moles Al³⁺ = 0.003; moles OH⁻ = 0.015; OH⁻ needed = 0.009; excess OH⁻ = 0.006; excess volume = 40cm³.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '30cm³ of 0.1M Al(NO3)3 solution is reacted with 100cm³ of 0.15M NaOH solution. Which is in excess and by how much?', '["NaOH solution, by 70cm³","NaOH solution, by 60cm³","NaOH solution, by 40cm³","Al(NO3)3 solution, by 20cm³","Al(NO3)3 solution, by 10cm³"]', '<u>NaOH solution, by 40cm³</u>.', '{"bold":[],"italic":[],"underline":["NaOH solution, by 40cm³"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmlam05kggvurzye15khh1utj', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Busy bodies and those living in idleness in the church at Thessalonica were admonished to', null, '["pray for those in authority for peace","do their work in quietness and earn a living","appeal to those in authority to create jobs","endure persecution from their masters."]', 1, 'They should do their work in quietness and earn a living.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Busy bodies and those living in idleness in the church at Thessalonica were admonished to', '["pray for those in authority for peace","<u>do their work in quietness and earn a living</u>","appeal to those in authority to create jobs","endure persecution from their masters."]', '<u>Do their work in quietness and earn a living</u> (2 Thessalonians 3:11-12).', '{"bold":[],"italic":[],"underline":["do their work in quietness and earn a living"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmlanrzd73jur2zuosyjksjca', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Daniel became distinguished above all other presidents and satraps because', null, '["an excellent spirit was in him","the spirit of Darius was in him","he was a good administrator","he was highly educated."]', 0, 'An excellent spirit was in Daniel.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Daniel became distinguished above all other presidents and satraps because', '["<u>an excellent spirit was in him</u>","the spirit of Darius was in him","he was a good administrator","he was highly educated."]', '<u>An excellent spirit was in him</u> (Daniel 6:3).', '{"bold":[],"italic":[],"underline":["an excellent spirit was in him"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmlb5547k9sn5dts6nejnrl3u', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'According to Hosea, what would God abolish from the land after making a covenant with Israel?', null, '["The bow","Famine","Foreign gods","Baal"]', 0, 'God would abolish the bow from the land.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to Hosea, what would God abolish from the land after making a covenant with Israel?', '["<u>The bow</u>","Famine","Foreign gods","Baal"]', '<u>The bow</u> (Hosea 2:17-18).', '{"bold":[],"italic":[],"underline":["The bow"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmlc0fqwg6a62rmkpscrwo80p', 'Islamic Religious Studies', 'JAMB', null, 2008, null, 'The complete Glorious Qur''an was taken from <b>Lawh al-mahfuz</b> to the lowest of the heavens known as', null, '["Bait al-Izzah","Bait al-Maqdis","Bait al-Haram","Bait al-Hikmah"]', 0, 'The Qur''an descended from Lawh al-Mahfuz to Bait al-Izzah (the lowest heaven).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The complete Glorious Qur''an was taken from <b>Lawh al-mahfuz</b> to the lowest of the heavens known as', '["<u>Bait al-Izzah</u>","Bait al-Maqdis","Bait al-Haram","Bait al-Hikmah"]', 'The Qur''an descended from Lawh al-Mahfuz to <u>Bait al-Izzah</u>.', '{"bold":["Lawh al-mahfuz"],"italic":[],"underline":["Bait al-Izzah"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmlcraijupawbwzvpyjsb6xx9', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the range of m so that x² + (m - 3)x + m = 0 has real roots.', null, '["m ≤ 1 or m ≥ 9","m ≤ -1 or m ≥ 9","m ≤ 1 or m ≥ 8","m ≤ -2 or m ≥ 7"]', 0, 'Discriminant (m-3)² - 4m ≥ 0 → m² - 10m + 9 ≥ 0 → (m-1)(m-9) ≥ 0 → m ≤ 1 or m ≥ 9.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the range of m so that x² + (m - 3)x + m = 0 has real roots.', '["m ≤ 1 or m ≥ 9","m ≤ -1 or m ≥ 9","m ≤ 1 or m ≥ 8","m ≤ -2 or m ≥ 7"]', 'Range = <u>m ≤ 1 or m ≥ 9</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmlcxygfiyzruqy9qju14w0lj', 'Biology', 'JAMB', null, 1997, null, 'Which is the most important pollutant of the marine environment in Nigeria?', null, '["Insecticides","Sewage","Oil","Inorganic fertilizers."]', 3, 'Inorganic fertilizers. is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which is the most important pollutant of the marine environment in Nigeria?', '["Insecticides","Sewage","Oil","<u>Inorganic fertilizers.</u>"]', 'Inorganic fertilizers. is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmld43jg2fth2hv1ls1a4mxyr', 'Chemistry', 'JAMB', null, 1990, null, 'In the reaction SnO2 + 2C → Sn + 2CO, the mass of coke containing 80% carbon required to reduce 0.032 kg of pure tin oxide is [Sn=119, O=16, C=12]', null, '["0.40 kg","0.20 kg","0.06 kg","0.40 g"]', 2, 'Moles SnO2 = 32/151 = 0.212; C needed = 0.424 mol = 5.09g; coke = 5.09/0.8 = 6.36g ≈ 0.06 kg.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the reaction SnO2 + 2C → Sn + 2CO, the mass of coke containing 80% carbon required to reduce 0.032 kg of pure tin oxide is [Sn=119, O=16, C=12]', '["0.40 kg","0.20 kg","0.06 kg","0.40 g"]', 'Mass coke ≈ <u>0.06 kg</u>.', '{"bold":[],"italic":[],"underline":["0.06 kg"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmlhrm7o51spf7ao61nwpiti6', 'Islamic Religious Studies', 'JAMB', null, 2003, null, 'Apart from being a renowned philosopher, Ibn Rushd was also', null, '["a jurist","an astronomer","a scientist","a mathematician"]', 0, 'Ibn Rushd (Averroes) was also a jurist.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Apart from being a renowned philosopher, Ibn Rushd was also', '["<u>a jurist</u>","an astronomer","a scientist","a mathematician"]', '<u>Ibn Rushd</u> was also a jurist.', '{"bold":[],"italic":[],"underline":["a jurist"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmljariduvj7jhjsh4soi1nqo', 'General Mathematics', 'WAEC', null, 2020, null, 'If log₂(3x-1) - log₂(x+1) = 2, find x.', null, '["1","no solution","3","4"]', 1, '(3x-1)/(x+1) = 4 → x = -5, which makes 3x-1 negative, so there is no solution.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'If log₂(3x-1) - log₂(x+1) = 2, find x.', '["1","no solution","3","4"]', '(3x-1)/(x+1) = 4 → x = -5, which makes 3x-1 negative, so there is no solution.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmlmy3lvbd9lycjs84d273ouh', 'Biology', 'JAMB', null, 1998, null, 'In snails, the hard calcareous shells are secreted by the', null, '["radula","ctendium","pneumostome","mantle Use the diagram below to answer questions 5 and 6."]', 3, 'mantle Use the diagram below to answer questions 5 and 6. is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In snails, the hard calcareous shells are secreted by the', '["radula","ctendium","pneumostome","<u>mantle Use the diagram below to answer questions 5 and 6.</u>"]', 'mantle Use the diagram below to answer questions 5 and 6. is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmlpxba6cmdq1luvlsg1cxadi', 'Government', 'JAMB', null, 2020, null, 'The majority of the OPEC members are from', null, '["Latin America","the Middle East","Asia","African"]', 1, 'Most OPEC members are from the Middle East.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The majority of the OPEC members are from', '["Latin America","<u>the Middle East</u>","Asia","African"]', '<u>The Middle East</u>.', '{"bold":[],"italic":[],"underline":["the Middle East"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmm1ukbsgwl7u8gs1pbax642r', 'Biology', 'JAMB', null, 1985, null, 'Which of the following organs regulates the amount of amino acids and glucose in the body?', null, '["Kidney","Liver","Pancreas","Spleen","Stomach"]', 1, 'The liver regulates amino acids and glucose levels.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following organs regulates the amount of <b>amino acids</b> and <b>glucose</b> in the body?', '["Kidney","<u>Liver</u>","Pancreas","Spleen","Stomach"]', 'The <u>liver</u> regulates amino acids and glucose levels.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmm9fp70d1swf5j611klujr3l', 'General Mathematics', 'WAEC', null, 2020, null, 'A variable point P(x, y) moves such that the area of triangle PAB is 10 square units, where A(2, 3) and B(4, -1). Find the equation of the locus of P.', null, '["2x + 2y - 10","= 10","2x - 2y - 10","= 10","2x + 2y + 10","= 10","2x - 2y + 10","= 10"]', 0, 'Area = ½|2(y-3) + 4(3-y) + x(-1-3)| = ½|-4x + 4y - 8| = 10 → |2x - 2y + 4| = 10. Key says |2x + 2y - 10| = 10.', false, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'A variable point P(x, y) moves such that the area of triangle PAB is 10 square units, where A(2, 3) and B(4, -1). Find the equation of the locus of P.', '["2x + 2y - 10","= 10","2x - 2y - 10","= 10","2x + 2y + 10","= 10","2x - 2y + 10","= 10"]', 'Locus: <u>|2x + 2y - 10| = 10</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmmbp78otthxhpexs9tw1sdf8', 'General Mathematics', 'WAEC', null, 2020, null, 'In a school of 100 students: 50 drink tea, 60 drink coffee, 30 drink both. How many drink tea but not coffee?', null, '["20","25","30","35"]', 0, 'Tea only = 50 - 30 = 20.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In a school of 100 students: 50 drink tea, 60 drink coffee, 30 drink both. How many drink tea but not coffee?', '["20","25","30","35"]', 'Tea only = <u>20</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmmd1qwppmd3iybi6gmcpmw92', 'Government', 'JAMB', null, 2020, null, 'A public corporation is managed by', null, '["The board of governors","The board of directors","A minister","A general manager."]', 1, 'A board of directors manages a public corporation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A public corporation is managed by', '["The board of governors","<u>The board of directors</u>","A minister","A general manager."]', '<u>The board of directors</u>.', '{"bold":[],"italic":[],"underline":["The board of directors"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmn32iyg2kc17t0vgr1y7swjr', 'Biology', 'JAMB', null, 1997, null, 'The appendicular skeleton is composed of the pectoral girdle', null, '["pelvic girdle, fore and hind limbs","pelvic girdle and fore limbs","lumbar vertebrae and pelvic girdle","lumbar vertebrae, fore and hind limbs"]', 0, 'pelvic girdle, fore and hind limbs is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The appendicular skeleton is composed of the pectoral girdle', '["<u>pelvic girdle, fore and hind limbs</u>","pelvic girdle and fore limbs","lumbar vertebrae and pelvic girdle","lumbar vertebrae, fore and hind limbs"]', 'pelvic girdle, fore and hind limbs is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmnjc6lccsbv3zaelz823dkv0', 'Chemistry', 'JAMB', null, 1996, null, 'Atoms of element X (with 2 electrons in the outer shell) combine with atoms of Y (with 7 electrons in the outer shell). Which of the following is <b>FALSE</b>? The compound formed', null, '["has formula XY2","is likely to be ionic","contains X²⁺ ions","contains Y⁻ ions"]', 0, 'The formula XY2 is correct, so this is not FALSE.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Atoms of element X (with 2 electrons in the outer shell) combine with atoms of Y (with 7 electrons in the outer shell). Which of the following is <b>FALSE</b>? The compound formed', '["has formula XY2","is likely to be ionic","contains X²⁺ ions","contains Y⁻ ions"]', 'Formula = <u>XY2</u> is correct.', '{"bold":["FALSE"],"italic":[],"underline":["has formula XY2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmnlfasoxhd63riuh0eow5vox', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The first Qur''anic verse revealed, instructed the Prophet (S.A.W) to', null, '["engage in preaching and warning","seek knowledge through reading","keep vigil the night long","read the minds of people."]', 1, 'The first verse instructed him to read (seek knowledge).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The first Qur''anic verse revealed, instructed the Prophet (S.A.W) to', '["engage in preaching and warning","<u>seek knowledge through reading</u>","keep vigil the night long","read the minds of people."]', '<u>Seek knowledge through reading</u> (Q. 96:1).', '{"bold":[],"italic":[],"underline":["seek knowledge through reading"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmnnmgypoqc2y64h2wmg4bfm4', 'General Mathematics', 'JAMB', null, 2020, null, 'Water is poured into a conical tank at the rate of 3 m³/min. The tank has a vertical height of 10 m and a top radius of 5 m. Find the rate at which the water level is rising when the water is 4 m deep.', null, '["3/(4π) m/min","4/(3π) m/min","3/(2π) m/min","3/(3π) m/min"]', 0, 'V = (1/3)πr²h with r = h/2; dV/dt = 3; dh/dt = 3/(4π) when h = 4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Water is poured into a conical tank at the rate of 3 m³/min. The tank has a vertical height of 10 m and a top radius of 5 m. Find the rate at which the water level is rising when the water is 4 m deep.', '["3/(4π) m/min","4/(3π) m/min","3/(2π) m/min","3/(3π) m/min"]', 'Rate = <u>3/(4π) m/min</u>.', '{"bold":[],"italic":[],"underline":["3/(4π) m/min"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmnqb7hfxxe0ts5bxfe0c9idi', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve (2x-3)/(x+1) > 1.', null, '["x > 4","x < -1 or x > 4","-1 < x < 4","x < -1"]', 0, '(2x-3)/(x+1) - 1 > 0 → (x-4)/(x+1) > 0 → x < -1 or x > 4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve (2x-3)/(x+1) > 1.', '["x > 4","x < -1 or x > 4","-1 < x < 4","x < -1"]', '<u>x < -1 or x > 4</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmntsdm24ww9xisomguif2sey', 'Islamic Religious Studies', 'JAMB', null, 2020, null, '''Iyyaka na''budu wa iyyaka nasta''in'' The verse above is an expression of man''s absolute', null, '["loyalty to Allah","dependence on Allah","obedience to Allah","humility to Allah."]', 0, 'It is an expression of absolute loyalty to Allah.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '''Iyyaka na''budu wa iyyaka nasta''in'' The verse above is an expression of man''s absolute', '["<u>loyalty to Allah</u>","dependence on Allah","obedience to Allah","humility to Allah."]', '<u>Loyalty to Allah</u> (Q. 1:5).', '{"bold":[],"italic":[],"underline":["loyalty to Allah"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmnzims0u9xwglfqqwe635zg0', 'General Mathematics', 'WAEC', null, 2020, null, 'In a class of 40 students, 25 passed Mathematics, 20 passed Physics, and 8 passed both. What is the probability that a student selected at random passed at least one of the subjects?', null, '["7/8","37/40","5/8","5/40"]', 1, 'At least one = 25 + 20 - 8 = 37; P = 37/40.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In a class of 40 students, 25 passed Mathematics, 20 passed Physics, and 8 passed both. What is the probability that a student selected at random passed at least one of the subjects?', '["7/8","37/40","5/8","5/40"]', 'P = <u>37/40</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmo3bqj5igiklb8x0qjtnmrsl', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve |x² - 4| ≤ 3.', null, '["[-√7, -1] ∪ [1, √7]","[-√7, √7]","[1, √7]","[-1, 1]"]', 0, '-3 ≤ x²-4 ≤ 3 → 1 ≤ x² ≤ 7 → x ∈ [-√7, -1] ∪ [1, √7].', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve |x² - 4| ≤ 3.', '["[-√7, -1] ∪ [1, √7]","[-√7, √7]","[1, √7]","[-1, 1]"]', '<u>x ∈ [-√7, -1] ∪ [1, √7]</u>.', '{"bold":[],"italic":[],"underline":["[-√7, -1] ∪ [1, √7]"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmo61mswt6g6z26r13yxadcim', 'General Mathematics', 'WAEC', null, 2020, null, 'If log_3(x² - 4x + 3) = 1 + log_3(x - 3), solve.', null, '["4","5","6","no solution"]', 3, '(x²-4x+3)/(x-3) = 3 → x-1 = 3 → x = 4. But x-3 > 0 → x > 3. So x = 4. Key says no solution.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If log_3(x² - 4x + 3) = 1 + log_3(x - 3), solve.', '["4","5","6","no solution"]', '<u>x = 4</u> (key says no solution).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmoekn9qwwpjhj1albqw7r8vv', 'Chemistry', 'JAMB', null, 1987, null, 'Oil spillage in ponds and creeks can be cleaned up by', null, '["burning off the oil layer","spraying with detergent","dispersal with compressed air","spraying with hot water"]', 1, 'Detergents emulsify oil for dispersal.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Oil spillage in ponds and creeks can be cleaned up by', '["burning off the oil layer","spraying with detergent","dispersal with compressed air","spraying with hot water"]', '<u>Detergents emulsify oil</u> for dispersal.', '{"bold":[],"italic":[],"underline":["spraying with detergent"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmogh8rfuhk5zr6x8g6ve8kgu', 'Chemistry', 'JAMB', null, 1995, null, 'The structure of <b>cis-2-butene</b> is', null, '["CH3-CH=CH-CH3 (trans)","CH3 and H on same side of C=C","CH3 and H on opposite sides","CH3 groups on opposite sides"]', 1, 'Cis-2-butene has both CH3 groups on the same side.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The structure of <b>cis-2-butene</b> is', '["CH3-CH=CH-CH3 (trans)","CH3 and H on same side of C=C","CH3 and H on opposite sides","CH3 groups on opposite sides"]', '<u>Cis-2-butene: both CH3 on same side</u>.', '{"bold":["cis-2-butene"],"italic":[],"underline":["CH3 and H on same side of C=C"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmojpy5n705qwq24ufcxxzz2u', 'Islamic Religious Studies', 'JAMB', null, 2008, null, 'Which of the following vitiates <b>Salah</b>?', null, '["Intoxication","Adornment","Falsehood","Yawning"]', 0, 'Intoxication invalidates Salah.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following vitiates <b>Salah</b>?', '["<u>Intoxication</u>","Adornment","Falsehood","Yawning"]', '<u>Intoxication</u> invalidates Salah.', '{"bold":["Salah"],"italic":[],"underline":["Intoxication"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmot39eggodx2z6cfx011iur4', 'Government', 'JAMB', null, 2020, null, 'In which of the following is the ceremonial and executive power fused?', null, '["Presidential system of government","Federal system of government","Parliamentary system of government","Unitary system of government"]', 0, 'In a presidential system, ceremonial and executive power are fused.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In which of the following is the ceremonial and executive power fused?', '["<u>Presidential system of government</u>","Federal system of government","Parliamentary system of government","Unitary system of government"]', '<u>Presidential system of government</u>.', '{"bold":[],"italic":[],"underline":["Presidential system of government"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmp0j6nkd5np92laqlq9h7goo', 'Biology', 'JAMB', null, 1986, null, 'A major limitation in the use of the potometer for measuring the rate of transpiration is that', null, '["it is made of breakable glass material","it measures the rate of water intake","it measures the rate of water loss through the stem only","the movement of the air bubble in the potometer cannot be timed accurately"]', 1, 'The potometer measures water intake, not actual water loss.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A major limitation in the use of the <b>potometer</b> for measuring the rate of transpiration is that', '["it is made of breakable glass material","<u>it measures the rate of water intake</u>","it measures the rate of water loss through the stem only","the movement of the air bubble in the potometer cannot be timed accurately"]', 'The potometer <u>measures water intake, not actual water loss</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmp8pwil41ivslylqlfq79l7a', 'Chemistry', 'JAMB', null, 1993, null, 'Al2O3(s) + 3H2SO4(aq) → Al2(SO4)3(aq) + 3H2O(l); Al2O3(s) + 2NaOH(aq) + 3H2O(l) → 2NaAl(OH)4(aq). We can conclude from the equations above that Al2O3(s) is', null, '["an acidic oxide","an amphoteric oxide","a basic oxide","a neutral oxide"]', 1, 'Al2O3 reacts with both acid and base (amphoteric).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Al2O3(s) + 3H2SO4(aq) → Al2(SO4)3(aq) + 3H2O(l); Al2O3(s) + 2NaOH(aq) + 3H2O(l) → 2NaAl(OH)4(aq). We can conclude from the equations above that Al2O3(s) is', '["an acidic oxide","an amphoteric oxide","a basic oxide","a neutral oxide"]', '<u>Al2O3 is amphoteric</u>.', '{"bold":[],"italic":[],"underline":["an amphoteric oxide"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmphi90a5i4dtogqw32n3tad6', 'General Mathematics', 'WAEC', null, 2020, null, 'Evaluate ∫ x²e^(x³) dx.', null, '["⅓e^(x³) + C","3e^(x³) + C","x³/3 e^(x³) + C","e^(x³) + C"]', 0, 'Let u = x³; du = 3x² dx; ∫ = ⅓e^(x³) + C.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Evaluate ∫ x²e^(x³) dx.', '["⅓e^(x³) + C","3e^(x³) + C","x³/3 e^(x³) + C","e^(x³) + C"]', 'Integral = <u>⅓e^(x³) + C</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmpmd9lis0ynrwpdt83oewq23', 'Chemistry', 'JAMB', null, 1999, null, 'Which of the following is a <b>solvent for perfumes</b>?', null, '["C5H12","C4H6","CH3COOH","C2H5OH"]', 3, 'Ethanol is a solvent for perfumes.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is a <b>solvent for perfumes</b>?', '["C5H12","C4H6","CH3COOH","C2H5OH"]', '<u>Ethanol (C2H5OH)</u> dissolves perfumes.', '{"bold":["solvent for perfumes"],"italic":[],"underline":["C2H5OH"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmpmmum1e8xg3no22u83m7lde', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Before the cock crowed, Peter denied Jesus three times. Who was the first person to recognize him as one of the disciples?', null, '["one of the rulers","the high Priest","a maid","a bystander."]', 2, 'A maid was the first to recognize Peter.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Before the cock crowed, Peter denied Jesus three times. Who was the first person to recognize him as one of the disciples?', '["one of the rulers","the high Priest","<u>a maid</u>","a bystander."]', '<u>A maid</u> (Matthew 26:69).', '{"bold":[],"italic":[],"underline":["a maid"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmprfxnoysi9dr8cy8xkr0rma', 'Islamic Religious Studies', 'JAMB', null, 2020, null, '''wa lam yakun lahu kufuwan ahad'' This verse of the Qur''an (112:4) says that Allah', null, '["is childless","is unique","has no parents","has no favourites."]', 1, 'It says Allah is unique.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '''wa lam yakun lahu kufuwan ahad'' This verse of the Qur''an (112:4) says that Allah', '["is childless","<u>is unique</u>","has no parents","has no favourites."]', '<u>Is unique</u> (Q. 112:4).', '{"bold":[],"italic":[],"underline":["is unique"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmpvo5myku60uw2b2dt8s0cvz', 'Biology', 'JAMB', null, 2001, null, 'Use the diagram to answer questions 22 and 23. The part labelled II is the', null, '["female organs and rhizoid","male organs and rhizoid","sporophyte and soil","annulus and stalk of sporangium"]', 3, 'Part II is the annulus and stalk of sporangium.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Use the diagram to answer questions 22 and 23. The part labelled II is the', '["female organs and rhizoid","male organs and rhizoid","sporophyte and soil","annulus and stalk of sporangium"]', '<u>Part II is the annulus and stalk of sporangium</u>.', '{"bold":[],"italic":[],"underline":["annulus and stalk of sporangium"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmq01zxc593g2haoidvqzq2lg', 'Chemistry', 'JAMB', null, 1990, null, 'Given the data:<br>P (protons 13, electrons 13, neutrons 14)<br>Q (protons 16, electrons 16, neutrons 17)<br>R (protons 17, electrons 17, neutrons 18)<br>S (protons 19, electrons 19, neutrons 20)<br>Which atom can be described by: relative atomic mass >30 but <40; odd atomic number; forms a unipositive ion in solution?', null, '["P","Q","R","S"]', 3, 'S has mass 39, atomic number 19 (odd), forms K⁺.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Given the data:<br>P (protons 13, electrons 13, neutrons 14)<br>Q (protons 16, electrons 16, neutrons 17)<br>R (protons 17, electrons 17, neutrons 18)<br>S (protons 19, electrons 19, neutrons 20)<br>Which atom can be described by: relative atomic mass >30 but <40; odd atomic number; forms a unipositive ion in solution?', '["P","Q","R","S"]', '<u>S (K)</u>: mass 39, atomic number 19, forms K⁺.', '{"bold":[],"italic":[],"underline":["S"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmq76102qful3ms1cukeqlf7r', 'General Mathematics', 'JAMB', null, 2020, null, 'Find ∫ dx/(x² - a²).', null, '["(1/2a)ln","(x - a)/(x + a)","+ C","(1/2a)ln","(x + a)/(x - a)","+ C","(1/a)ln","(x - a)/(x + a)","+ C","(1/a)ln","(x + a)/(x - a)","+ C"]', 0, 'Standard integral: (1/2a)ln|(x - a)/(x + a)| + C.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find ∫ dx/(x² - a²).', '["(1/2a)ln","(x - a)/(x + a)","+ C","(1/2a)ln","(x + a)/(x - a)","+ C","(1/a)ln","(x - a)/(x + a)","+ C","(1/a)ln","(x + a)/(x - a)","+ C"]', 'Integral = <u>(1/2a)ln|(x - a)/(x + a)| + C</u>.', '{"bold":[],"italic":[],"underline":["(1/2a)ln|(x - a)/(x + a)| + C"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmqg61ea7zk9rqfyejuypqhc9', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the probability that a family with exactly 4 children has at least 3 boys.', null, '["1/4","5/16","3/8","1/2"]', 1, 'P = 4C3(1/2)⁴ + 4C4(1/2)⁴ = 4/16 + 1/16 = 5/16.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the probability that a family with exactly 4 children has at least 3 boys.', '["1/4","5/16","3/8","1/2"]', 'P = <u>5/16</u>.', '{"bold":[],"italic":[],"underline":["5/16"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmqr7wj6xppt4cllg8v1p7po2', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve (x-2)/(x+3) ≤ 0.', null, '["(-3, 2)","[-3, 2)","(-3, 2]","[-3, 2]"]', 2, '(x-2)/(x+3) ≤ 0: critical points x = 2 and x = -3; sign chart gives -3 < x ≤ 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Solve (x-2)/(x+3) ≤ 0.', '["(-3, 2)","[-3, 2)","(-3, 2]","[-3, 2]"]', '(x-2)/(x+3) ≤ 0: critical points x = 2 and x = -3; sign chart gives -3 < x ≤ 2.', '{"bold":[],"italic":[],"underline":["[-3, 2)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmqsv76ns95dngmiit8v2pf2u', 'Government', 'JAMB', null, 2020, null, 'The political neutrality of civil servants implies that they', null, '["are not allowed to join any organization or group","have no dealings with politicians","are not allowed to be involved in partisan politics","are not allowed to vote"]', 2, 'Civil servants are barred from partisan politics to maintain neutrality.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The political neutrality of civil servants implies that they', '["are not allowed to join any organization or group","have no dealings with politicians","<u>are not allowed to be involved in partisan politics</u>","are not allowed to vote"]', 'They are not allowed to be involved in <u>partisan politics</u>.', '{"bold":[],"italic":[],"underline":["are not allowed to be involved in partisan politics"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmqt0ct0lbq0p88vgk3c0fefe', 'General Mathematics', 'JAMB', null, 2020, null, 'Equation of the circle passing through (1, 2), (3, 4), and (5, 6).', null, '["None points are collinear","x² + y² - 6x - 8y + 20 = 0","x² + y² - 4x - 6y + 12 = 0","Not possible"]', 0, 'Points (1,2), (3,4), (5,6) are collinear, so no circle passes through them.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Equation of the circle passing through (1, 2), (3, 4), and (5, 6).', '["None points are collinear","x² + y² - 6x - 8y + 20 = 0","x² + y² - 4x - 6y + 12 = 0","Not possible"]', '<u>None points are collinear</u>.', '{"bold":[],"italic":[],"underline":["None points are collinear"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmqwv99ktfofm0y98afekb5jc', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Elijah decreed that there would be neither rain nor dew for three years because', null, '["Nebat the son of Rehoboam convinced Ahab to kill him","Ahab had forsaken the commandment of God by erecting an altar for Baal","Jezebel the wife of Ahab killed Obadiah","He was sure that he would be fed by the ravens."]', 1, 'Ahab erected an altar for Baal.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Elijah decreed that there would be neither rain nor dew for three years because', '["Nebat the son of Rehoboam convinced Ahab to kill him","<u>Ahab had forsaken the commandment of God by erecting an altar for Baal</u>","Jezebel the wife of Ahab killed Obadiah","He was sure that he would be fed by the ravens."]', '<u>Ahab had forsaken the commandment of God by erecting an altar for Baal</u> (1 Kings 16:31-33).', '{"bold":[],"italic":[],"underline":["Ahab had forsaken the commandment of God by erecting an altar for Baal"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmqzag71ohd30sk057deaztfo', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the length of the latus rectum of the ellipse x²/25 + y²/9 = 1.', null, '["18/5","16/5","14/5","12/5"]', 0, 'Latus rectum = 2b²/a = 18/5.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the length of the latus rectum of the ellipse x²/25 + y²/9 = 1.', '["18/5","16/5","14/5","12/5"]', 'Length = <u>18/5</u>.', '{"bold":[],"italic":[],"underline":["18/5"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmr3dyidb4iijdjique36gxwx', 'Islamic Religious Studies', 'JAMB', null, 2003, null, 'As Allah''s creative work is discussed in Q.27:59-64, the passage intermittently cautions man against', null, '["distrust","disobedience","extravagance","exploitation"]', 1, 'The passage cautions against disobedience to Allah.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'As Allah''s creative work is discussed in Q.27:59-64, the passage intermittently cautions man against', '["distrust","<u>disobedience</u>","extravagance","exploitation"]', 'The passage cautions against <u>disobedience</u> to Allah.', '{"bold":[],"italic":[],"underline":["disobedience"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmr5susmrubvcuhm4eyenj13p', 'Chemistry', 'JAMB', null, 1991, null, 'Calculate the volume of carbon(IV) oxide measured at s.t.p, produced when 1kg of potassium hydrogen trioxocarbonate(IV) is totally decomposed by heat. [G.M.V at s.t.p = 22.4 dm³, K=39, O=16, C=12, H=1]', null, '["28dm³","56dm³","112dm³","196dm³"]', 1, '2KHCO3 → K2CO3 + CO2 + H2O; moles KHCO3 = 10; CO2 = 5 mol; volume = 112 dm³. Key says 56.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Calculate the volume of carbon(IV) oxide measured at s.t.p, produced when 1kg of potassium hydrogen trioxocarbonate(IV) is totally decomposed by heat. [G.M.V at s.t.p = 22.4 dm³, K=39, O=16, C=12, H=1]', '["28dm³","56dm³","112dm³","196dm³"]', 'Moles CO2 = 5; volume = <u>112 dm³</u> (key says 56).', '{"bold":[],"italic":[],"underline":["56dm³"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmr8djzr6ugrveknhdi5eh4sa', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'What were the two emblems Jesus used during the Last Supper?', null, '["the bread and the wine","the unleavened bread and the fruit of the vine","His blood and His body","the bread and the blood of the Lamb."]', 1, 'The two emblems were unleavened bread and fruit of the vine.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What were the two emblems Jesus used during the Last Supper?', '["the bread and the wine","<u>the unleavened bread and the fruit of the vine</u>","His blood and His body","the bread and the blood of the Lamb."]', '<u>Unleavened bread and the fruit of the vine</u> (Mark 14:22-25).', '{"bold":[],"italic":[],"underline":["the unleavened bread and the fruit of the vine"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmrggqmjmmkl9sk8okrddkk0h', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'At the time Angel Gabriel appeared to Mary, Elizabeth was pregnant for', null, '["six months","five months","four months","three months."]', 0, 'Elizabeth was six months pregnant.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'At the time Angel Gabriel appeared to Mary, Elizabeth was pregnant for', '["<u>six months</u>","five months","four months","three months."]', '<u>Six months</u> (Luke 1:36).', '{"bold":[],"italic":[],"underline":["six months"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmrp0h0e05o309281t0rmt9bf', 'General Mathematics', 'WAEC', null, 2020, null, 'If 123_(b+1) = 162₁₀, find b.', null, '["6","7","8","9"]', 1, '1(b+1)² + 2(b+1) + 3 = 162 → b² + 2b + 1 + 2b + 2 + 3 = 162 → b² + 4b + 6 = 162 → b² + 4b - 156 = 0 → b = 10 or -14. Key says 7.', false, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'If 123_(b+1) = 162₁₀, find b.', '["6","7","8","9"]', 'b² + 4b - 156 = 0 → <u>b = 10</u> (key says 7).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cms62fl6l5isf6z6u21zv1x5c', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'In which verse of the Qur''an are women directed to dress modestly?', null, '["5:3","24:31","55:10","112:4"]', 1, 'Q. 24:31 directs women to dress modestly.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In which verse of the Qur''an are women directed to dress modestly?', '["5:3","<u>24:31</u>","55:10","112:4"]', '<u>24:31</u> (Q. 24:31).', '{"bold":[],"italic":[],"underline":["24:31"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cms692jmh5vtqxh0i4045b36t', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'The Hebrew midwives who obeyed God rather than Pharaoh were blessed with', null, '["favour from all the Israelites","long life in Canaan","resources","families."]', 3, 'God gave them families.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Hebrew midwives who obeyed God rather than Pharaoh were blessed with', '["favour from all the Israelites","long life in Canaan","resources","<u>families.</u>"]', '<u>Families</u> (Exodus 1:20-21).', '{"bold":[],"italic":[],"underline":["families."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmsgxs491oza1in0oina23q1p', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The success of the business venture which Muhammad (S.A.W) carried out for Khadijah was due mainly to', null, '["Khadijah''s love for him","the fact that he was a prophet","his dedication and honesty","the skill and hardwork of his assistants."]', 2, 'His dedication and honesty made the business successful.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The success of the business venture which Muhammad (S.A.W) carried out for Khadijah was due mainly to', '["Khadijah''s love for him","the fact that he was a prophet","<u>his dedication and honesty</u>","the skill and hardwork of his assistants."]', '<u>His dedication and honesty</u>.', '{"bold":[],"italic":[],"underline":["his dedication and honesty"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmsjxxrv8z8ml8skfijroeehk', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'God did not lead the Israelites by the way of the land of the Philistines although that was near because', null, '["He wanted them to learn through hardship in the wilderness","the Egyptians would have overtaken them","they were afraid of the Philistines","He did not want them to see war and return to Egypt."]', 3, 'God did not want them to see war and return to Egypt.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'God did not lead the Israelites by the way of the land of the Philistines although that was near because', '["He wanted them to learn through hardship in the wilderness","the Egyptians would have overtaken them","they were afraid of the Philistines","<u>He did not want them to see war and return to Egypt.</u>"]', '<u>He did not want them to see war and return to Egypt</u> (Exodus 13:17).', '{"bold":[],"italic":[],"underline":["He did not want them to see war and return to Egypt."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmsqflhkk9ttqg67f5yreln5m', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve |x² - 4| = 3x.', null, '["1, 4","1, -4","-1, 4","-1, -4"]', 0, 'x²-4 = 3x → x²-3x-4 = 0 → x = 4 or -1. Check x=-1: |1-4| = 3 ≠ -3. So x=4. Also x²-4 = -3x → x²+3x-4 = 0 → x = 1 or -4. Check x=1: |1-4| = 3 = 3. So x=1,4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve |x² - 4| = 3x.', '["1, 4","1, -4","-1, 4","-1, -4"]', '<u>x = 1, 4</u>.', '{"bold":[],"italic":[],"underline":["1, 4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmss407h4n9fmde2g9ub151c9', 'English Language', 'JAMB', null, 2020, null, 'He claimed that Mr. Okoli''s utterance was tantamount to defamation of character, so he sued him for _____.', null, '["damage","some damage","a damage","damages"]', 3, 'Damages = compensation awarded in a lawsuit.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'He claimed that Mr. Okoli''s utterance was tantamount to defamation of character, so he sued him for _____.', '["damage","some damage","a damage","damages"]', '<u>Damages</u> = court compensation.', '{"bold":[],"italic":[],"underline":["damages"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmsycogqqonanb748z36n59ao', 'Chemistry', 'JAMB', null, 1989, null, 'A solution of calcium bromide contains 20g dm⁻³. What is the molarity of the solution with respect to calcium bromide and bromide ions? [Ca=40, Br=80]', null, '["0.1, 0.1","0.1, 0.2","0.1, 0.05","0.05, 0.1"]', 1, 'Moles CaBr2 = 20/200 = 0.1; Br⁻ = 0.2M.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A solution of calcium bromide contains 20g dm⁻³. What is the molarity of the solution with respect to calcium bromide and bromide ions? [Ca=40, Br=80]', '["0.1, 0.1","0.1, 0.2","0.1, 0.05","0.05, 0.1"]', 'CaBr2 = <u>0.1M; Br⁻ = 0.2M</u>.', '{"bold":[],"italic":[],"underline":["0.1, 0.2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmsziioakt4hihd9qaq48670l', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Paul teaches that the exercise of spiritual gifts by individual believers should be used to promote', null, '["co-operation","knowledge","faith","competition."]', 0, 'Spiritual gifts should promote co-operation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Paul teaches that the exercise of spiritual gifts by individual believers should be used to promote', '["<u>co-operation</u>","knowledge","faith","competition."]', '<u>Co-operation</u> (1 Corinthians 12).', '{"bold":[],"italic":[],"underline":["co-operation"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmt92dcjoh6kf9o451owmcsn1', 'Government', 'JAMB', null, 2020, null, 'The most important aspect of political participation in a democracy is', null, '["voting in elections","attending political rallies","the observance of electoral processes","registration with a political party."]', 0, 'Voting in elections is the most important political participation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The most important aspect of political participation in a democracy is', '["<u>voting in elections</u>","attending political rallies","the observance of electoral processes","registration with a political party."]', '<u>Voting in elections</u>.', '{"bold":[],"italic":[],"underline":["voting in elections"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmtb3egulwv65wseixnxznjz9', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve: x⁴ - 5x² + 4 = 0', null, '["±1, ±2","±1, ±3","±2, ±3","±1, ±4"]', 0, 'y² - 5y + 4 = 0 → y = 1 or 4 → x = ±1, ±2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve: x⁴ - 5x² + 4 = 0', '["±1, ±2","±1, ±3","±2, ±3","±1, ±4"]', '<u>x = ±1, ±2</u>.', '{"bold":[],"italic":[],"underline":["±1, ±2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmtcmy8sju9datysgwmgla4yx', 'Biology', 'JAMB', null, 1992, null, 'Which enzymes are contained in the pancreatic juice?', null, '["Pytalin, lipase and pepsin","Maltase, erepsin and trypsin","Rennin, surcarse and lipase","Amylase, lipase and trypsin"]', 3, 'Pancreatic juice contains amylase, lipase, and trypsin.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which enzymes are contained in the <b>pancreatic juice</b>?', '["Pytalin, lipase and pepsin","Maltase, erepsin and trypsin","Rennin, surcarse and lipase","<u>Amylase, lipase and trypsin</u>"]', 'Pancreatic juice contains <u>amylase, lipase, and trypsin</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmtcxku3pk1l0vez6vp0kz4ra', 'General Mathematics', 'WAEC', null, 2020, null, 'A point P moves such that its distance from A(1, 2) is always equal to its distance from the y-axis. Find the equation of the locus of P.', null, '["y² - 4y - 2x + 5 = 0","y² - 4y + 2x + 5 = 0","x² - 2x - 4y + 5 = 0","x² - 2x + 4y + 5 = 0"]', 0, '(x-1)² + (y-2)² = x² → y² - 4y - 2x + 5 = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A point P moves such that its distance from A(1, 2) is always equal to its distance from the y-axis. Find the equation of the locus of P.', '["y² - 4y - 2x + 5 = 0","y² - 4y + 2x + 5 = 0","x² - 2x - 4y + 5 = 0","x² - 2x + 4y + 5 = 0"]', 'Locus: <u>y² - 4y - 2x + 5 = 0</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmtt9wctytp0lf5k7u2f5e3a1', 'Chemistry', 'JAMB', null, 1983, null, 'An element is <b>electronegative</b> if', null, '["it has a tendency to exist in the gaseous form","its ions dissolve readily in water","it has a tendency to lose electrons","it has a tendency to gain electrons","it readily forms covalent bonds"]', 3, 'Electronegativity is the tendency to gain electrons.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An element is <b>electronegative</b> if', '["it has a tendency to exist in the gaseous form","its ions dissolve readily in water","it has a tendency to lose electrons","it has a tendency to gain electrons","it readily forms covalent bonds"]', '<u>Electronegativity is the tendency to gain electrons</u>.', '{"bold":["electronegative"],"italic":[],"underline":["it has a tendency to gain electrons"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmu1qre9v9f0uey9qdhkibymh', 'Chemistry', 'JAMB', null, 1985, null, 'Which of the following compounds is <b>NOT formed</b> by the action of chlorine on methane?', null, '["CH3Cl","C2H5Cl","CH2Cl2","CHCl3"]', 1, 'C2H5Cl (ethyl chloride) cannot be formed from methane + chlorine.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following compounds is <b>NOT formed</b> by the action of chlorine on methane?', '["CH3Cl","C2H5Cl","CH2Cl2","CHCl3"]', '<u>C2H5Cl</u> cannot be formed from methane + chlorine.', '{"bold":["NOT formed"],"italic":[],"underline":["C2H5Cl"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmu7g86xpmzizqf0clgu2i86c', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'According to the Gospel of John, Jesus is the true vine while the vinedresser is', null, '["the Holy Spirit","His father","the gardener","His mother."]', 1, 'His Father is the vinedresser.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to the Gospel of John, Jesus is the true vine while the vinedresser is', '["the Holy Spirit","<u>His father</u>","the gardener","His mother."]', '<u>His father</u> (John 15:1).', '{"bold":[],"italic":[],"underline":["His father"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmu7mxzfu1qeyv77t9hk4kluv', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve 1/(x-1) + 1/(x-2) ≤ 0.', null, '["(1, 3/2] ∪ (2, ∞)","(1, 3/2]","(2, ∞)","(-∞, 1) ∪ [3/2, 2)"]', 3, '(2x-3)/((x-1)(x-2)) ≤ 0 → x < 1 or 3/2 ≤ x < 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve 1/(x-1) + 1/(x-2) ≤ 0.', '["(1, 3/2] ∪ (2, ∞)","(1, 3/2]","(2, ∞)","(-∞, 1) ∪ [3/2, 2)"]', '<u>x < 1 or 3/2 ≤ x < 2</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmug96jhra9iyrsrwxf2vwn2p', 'Biology', 'JAMB', null, 2001, null, 'Which of the following organisms does <b>not exist as a single free-living cell</b>?', null, '["Paramecium","Volvox","Amoeba","Chlamydomonas"]', 1, 'Volvox forms colonies.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following organisms does <b>not exist as a single free-living cell</b>?', '["Paramecium","Volvox","Amoeba","Chlamydomonas"]', '<u>Volvox</u> forms colonies.', '{"bold":["not exist as a single free-living cell"],"italic":[],"underline":["Volvox"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmumdpiftc5tixw5az4f9arnz', 'Chemistry', 'JAMB', null, 1987, null, 'What mass of magnesium would be obtained by passing a current of 2 amperes for 2 hrs. 30mins through molten magnesium chloride? [1 faraday = 96500 coulombs, Mg = 24]', null, '["1.12g","2.00g","2.24g","4.48g"]', 1, 'Q = 2 × 9000 = 18000C; moles Mg = 18000/(2×96500) = 0.0933; mass = 2.24g. Key says 2.00g.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What mass of magnesium would be obtained by passing a current of 2 amperes for 2 hrs. 30mins through molten magnesium chloride? [1 faraday = 96500 coulombs, Mg = 24]', '["1.12g","2.00g","2.24g","4.48g"]', 'Mass Mg = 18000/(2×96500) × 24 = <u>2.24g</u>.', '{"bold":[],"italic":[],"underline":["2.00g"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmuolqlmj9yuzkxovpwz3cdr1', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the quadratic with roots α+1/β, β+1/α where α, β are roots of x² - 3x + 1 = 0', null, '["x²-6x+4=0","x²-6x+8=0","x²-5x+6=0","x²-5x+4=0"]', 0, 'Sum = (α+β) + (α+β)/(αβ) = 6; product = αβ + 2 + 1/(αβ) = 4; so x² - 6x + 4 = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Find the quadratic with roots α+1/β, β+1/α where α, β are roots of x² - 3x + 1 = 0', '["x²-6x+4=0","x²-6x+8=0","x²-5x+6=0","x²-5x+4=0"]', 'Sum = (α+β) + (α+β)/(αβ) = 6; product = αβ + 2 + 1/(αβ) = 4; so x² - 6x + 4 = 0.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmup7rqqr9sai8hya6mahij0s', 'Chemistry', 'JAMB', null, 1986, null, 'Which of the following contains an <b>efflorescent</b>, a <b>deliquescent</b> and a <b>hygroscopic</b> substance respectively?', null, '["Na2SO4, concentrated H2SO4, CaCl2","Na2CO3·H2O, FeSO4·7H2O, concentrated H2SO4","Na2CO3·10H2O, FeCl3, concentrated H2SO4","Concentrated H2SO4, FeSO4·7H2O, MgCl2"]', 2, 'Na2CO3·10H2O is efflorescent; FeCl3 is deliquescent; concentrated H2SO4 is hygroscopic.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following contains an <b>efflorescent</b>, a <b>deliquescent</b> and a <b>hygroscopic</b> substance respectively?', '["Na2SO4, concentrated H2SO4, CaCl2","Na2CO3·H2O, FeSO4·7H2O, concentrated H2SO4","Na2CO3·10H2O, FeCl3, concentrated H2SO4","Concentrated H2SO4, FeSO4·7H2O, MgCl2"]', '<u>Na2CO3·10H2O (efflorescent), FeCl3 (deliquescent), concentrated H2SO4 (hygroscopic)</u>.', '{"bold":["efflorescent","deliquescent","hygroscopic"],"italic":[],"underline":["Na2CO3·10H2O, FeCl3, concentrated H2SO4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmuqecn7gar2351891d4nlbvq', 'English Language', 'JAMB', null, 2020, null, 'How I wish I _____ my mother''s advice.', null, '["had heeded","heed","heeded","will heed"]', 0, 'Had heeded = past regret.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'How I wish I _____ my mother''s advice.', '["had heeded","heed","heeded","will heed"]', '<u>Had heeded</u> = past regret.', '{"bold":[],"italic":[],"underline":["had heeded"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmvbz0506j3h2crbsq42aevlq', 'General Mathematics', 'JAMB', null, 2020, null, 'Evaluate ∫₀^π x sin x/(1 + cos²x) dx.', null, '["π²/4","π²/2","π²","0"]', 0, 'Using property ∫₀^π f(x)dx = ∫₀^π f(π-x)dx: I = π²/4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Evaluate ∫₀^π x sin x/(1 + cos²x) dx.', '["π²/4","π²/2","π²","0"]', 'Integral = <u>π²/4</u>.', '{"bold":[],"italic":[],"underline":["π²/4"],"fillBlanks":[]}');
