insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmw0caddm022fln7udxf94mrv', 'Physics', 'JAMB', null, 1983, null, 'The speed of light in vacuum is 3.0 × 10⁸ m s⁻¹. If the refractive index of a transparent liquid is 4/3, then the speed of light in the liquid is', null, '["0.44 × 10⁸ m s⁻¹","2.25 × 10⁸ m s⁻¹","3.0 × 10⁸ m s⁻¹","4.0 × 10⁸ m s⁻¹","4.33 × 10⁸ m s⁻¹"]', 1, 'v = c/n = 3.0 × 10⁸ ÷ 4/3 = 2.25 × 10⁸ m s⁻¹.', true, '2026-10-11 21:26:45.728', '2026-10-11 21:26:45.728', null, null, null, 'The speed of light in vacuum is 3.0 × 10⁸ m s⁻¹. If the refractive index of a transparent liquid is 4/3, then the speed of light in the liquid is', '["0.44 × 10⁸ m s⁻¹","2.25 × 10⁸ m s⁻¹","3.0 × 10⁸ m s⁻¹","4.0 × 10⁸ m s⁻¹","4.33 × 10⁸ m s⁻¹"]', 'v = c/n = 3.0 × 10⁸ ÷ 4/3 = 2.25 × 10⁸ m s⁻¹.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmw2hbctqa801se8in4iw5mg5', 'Biology', 'JAMB', null, 2004, null, 'The eggs of birds contain relatively larger quantities of yolk than those of amphibians and reptiles because', null, '["embryonic development is longer in birds","birds lay shelled eggs","birds are generally bigger in size","those of birds are fertilized internally."]', 0, 'embryonic development is longer in birds is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The eggs of birds contain relatively larger quantities of yolk than those of amphibians and reptiles because', '["<u>embryonic development is longer in birds</u>","birds lay shelled eggs","birds are generally bigger in size","those of birds are fertilized internally."]', 'embryonic development is longer in birds is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmweg9fa8c1jb6gsq0icqvu78', 'Islamic Religious Studies', 'JAMB', null, 2020, null, '''Surely, we created man of the best stature, then, we reduced him to the lowest of the low save those who believe and good works''. This quotation is from Surat', null, '["al-Asr","al-Alaq","at-Tin","al-Qadr"]', 2, 'This quotation is from Surat at-Tin.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '''Surely, we created man of the best stature, then, we reduced him to the lowest of the low save those who believe and good works''. This quotation is from Surat', '["al-Asr","al-Alaq","<u>at-Tin</u>","al-Qadr"]', '<u>At-Tin</u> (Q. 95:4-6).', '{"bold":[],"italic":[],"underline":["at-Tin"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmwjb0gljr4a6eo6qwgr37das', 'Islamic Religious Studies', 'JAMB', null, 2011, null, 'Allah commands Muslims to observe and fulfil agreements with the non-Muslims, if the later do not', null, '["betray","fight","oppress","break the agreement"]', 3, 'Agreements with non-Muslims must be kept unless they break them.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Allah commands Muslims to observe and fulfil agreements with the non-Muslims, if the later do not', '["betray","fight","oppress","<u>break the agreement</u>"]', 'Agreements must be kept unless they <u>break the agreement</u>.', '{"bold":[],"italic":[],"underline":["break the agreement"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmwmqceq72nugeuezzs38p8r8', 'Chemistry', 'JAMB', null, 1992, null, 'The characteristic reaction of <b>carbonyl compounds</b> is', null, '["Substitution","Elimination","Addition","Saponification"]', 2, 'Carbonyl compounds undergo nucleophilic addition.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The characteristic reaction of <b>carbonyl compounds</b> is', '["Substitution","Elimination","Addition","Saponification"]', '<u>Addition</u> is characteristic of carbonyl compounds.', '{"bold":["carbonyl compounds"],"italic":[],"underline":["Addition"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmwnyfg9ajk4m0cgk24cpn288', 'General Mathematics', 'WAEC', null, 2020, null, 'A mixture has milk:water = 7:5. Add 9L water → 7:8. Find original milk.', null, '["21 L","28 L","35 L","42 L"]', 2, '7x/(5x+9) = 7/8 → 56x = 35x + 63 → 21x = 63 → x = 3; milk = 21L. Key says 35L.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A mixture has milk:water = 7:5. Add 9L water → 7:8. Find original milk.', '["21 L","28 L","35 L","42 L"]', '7x/(5x+9) = 7/8 → x = 3; milk = <u>21L</u> (key says 35L).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmwprmqanp9m25xkbwhoyz70g', 'Islamic Religious Studies', 'JAMB', null, 2011, null, 'One of the importance of the first revelation was the', null, '["description of the Arabian peninsula to the Prophet (SAW)","dissemination of knowledge","explanation of knowledge","description of the steps of acquiring knowledge"]', 1, 'The first revelation emphasized reading and knowledge.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One of the importance of the first revelation was the', '["description of the Arabian peninsula to the Prophet (SAW)","<u>dissemination of knowledge</u>","explanation of knowledge","description of the steps of acquiring knowledge"]', 'The first revelation emphasized <u>reading and knowledge</u>.', '{"bold":[],"italic":[],"underline":["dissemination of knowledge"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cmwzenjye538z8ggeqtlqowan', 'Biology', 'JAMB', null, 1988, null, 'Spirogyra, Euglena and Chlamydomonas share many characteristics EXCEPT', null, '["nutrition","reproduction","mobility","irritability"]', 2, 'Spirogyra is non-motile; Euglena and Chlamydomonas are motile.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Spirogyra, Euglena and Chlamydomonas share many characteristics <b>EXCEPT</b>', '["nutrition","reproduction","<u>mobility</u>","irritability"]', '<u>Spirogyra is non-motile</u>; Euglena and Chlamydomonas are motile.', null);
