insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cn11f36q177eoxze6agiz7xqa', 'Chemistry', 'JAMB', null, 1996, null, 'Manganese(IV) oxide is known to hasten the decomposition of hydrogen peroxide. Its main action is to', null, '["increase the surface area of the reactants","increase the concentration of the reactants","lower the activation energy for the reaction","lower the heat of reaction, ΔH, for the reaction"]', 2, 'MnO2 is a catalyst; it lowers activation energy.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Manganese(IV) oxide is known to hasten the decomposition of hydrogen peroxide. Its main action is to', '["increase the surface area of the reactants","increase the concentration of the reactants","lower the activation energy for the reaction","lower the heat of reaction, ΔH, for the reaction"]', '<u>MnO2 lowers activation energy</u>.', '{"bold":[],"italic":[],"underline":["lower the activation energy for the reaction"],"fillBlanks":[]}');
