insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cn32jk53cdnau8didwgpx0dma', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'In Surah al-Qari''ah, mankind is compared to', null, '["scattered moths","laden camels","pampered creatures","humiliated beasts."]', 0, 'Mankind is compared to scattered moths.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In Surah al-Qari''ah, mankind is compared to', '["<u>scattered moths</u>","laden camels","pampered creatures","humiliated beasts."]', '<u>Scattered moths</u> (Q. 101:4).', '{"bold":[],"italic":[],"underline":["scattered moths"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cn33fa2o9gcemvzlx8kalm5dy', 'Government', 'JAMB', null, 2020, null, 'The countries in which Nigeria participated in the ECOMOG peace-keeping operations were', null, '["Sierra Leone and Cote d''Ivoire","Liberia and Sierra Leone.","Liberia and Guinea","Senegal and Cote d''Ivoire"]', 1, 'Nigeria participated in ECOMOG in Liberia and Sierra Leone.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The countries in which Nigeria participated in the ECOMOG peace-keeping operations were', '["Sierra Leone and Cote d''Ivoire","<u>Liberia and Sierra Leone.</u>","Liberia and Guinea","Senegal and Cote d''Ivoire"]', '<u>Liberia and Sierra Leone</u>.', '{"bold":[],"italic":[],"underline":["Liberia and Sierra Leone."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cn33y5c2tfvp7wcerwvokd7y5', 'Christian Religious Studies', 'JAMB', null, 2020, null, '''They have no wine''. Jesus'' immediate response to the statement above was', null, '["... draw some out, and take it to the steward of the feast","\"...O woman, what have you to do with me?\"","\"...Do whatever he tells you\"","\"... fill the jars with water."]', 1, 'Jesus replied: "O woman, what have you to do with me?"', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '''They have no wine''. Jesus'' immediate response to the statement above was', '["... draw some out, and take it to the steward of the feast","<u>\"...O woman, what have you to do with me?\"</u>","\"...Do whatever he tells you\"","\"... fill the jars with water."]', '<u>"O woman, what have you to do with me?"</u> (John 2:3-4).', '{"bold":[],"italic":[],"underline":["\"...O woman, what have you to do with me?\""],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cn37tz144nr3e562fd9fnr0b6', 'Biology', 'JAMB', null, 2001, null, 'An association between the root nodule of a leguminous plants and rhizobium sp is known as', null, '["commensalism","mycorrhiza","parasitism","symbiosis"]', 3, 'symbiosis is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An association between the root nodule of a leguminous plants and rhizobium sp is known as', '["commensalism","mycorrhiza","parasitism","<u>symbiosis</u>"]', 'symbiosis is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cn3bm7h40d08la73ihj3dait4', 'General Mathematics', 'WAEC', null, 2020, null, 'If ∫₀^a dx/√(a² - x²) = π/3, find a.', null, '["√3/2","1","2/√3","2"]', 1, '∫ = sin⁻¹(x/a); evaluated = π/2. π/2 = π/3 impossible. Key says 1.', false, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'If ∫₀^a dx/√(a² - x²) = π/3, find a.', '["√3/2","1","2/√3","2"]', 'a = <u>1</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cn3c76y65bz65fpi0ipbri8s4', 'Biology', 'JAMB', null, 2004, null, 'Epigeal germination of a seed is characterized by', null, '["lack of growth of the hypocotyls","more rapid elongation of the hypocotyls than the epicotyl","more rapid elongation of the epicotyl than the hypocotyl","equal growth rate of both the hypocotyl and epicotyl."]', 1, 'In epigeal germination, the hypocotyl elongates and lifts the cotyledons above the soil.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Epigeal germination of a seed is characterized by', '["lack of growth of the hypocotyls","<u>more rapid elongation of the hypocotyls than the epicotyl</u>","more rapid elongation of the epicotyl than the hypocotyl","equal growth rate of both the hypocotyl and epicotyl."]', 'In epigeal germination, the hypocotyl elongates and lifts the cotyledons above the soil.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cn3klmuo7kd12mdsmmtjglx01', 'Chemistry', 'JAMB', null, 1994, null, 'A solid that absorbs water from the atmosphere and forms an aqueous solution is', null, '["hydrophilic","efflorescent","deliquescent","hygroscopic"]', 2, 'Deliquescent solids absorb water and dissolve in it.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A solid that absorbs water from the atmosphere and forms an aqueous solution is', '["hydrophilic","efflorescent","deliquescent","hygroscopic"]', '<u>Deliquescent</u> solids absorb water and dissolve.', '{"bold":[],"italic":[],"underline":["deliquescent"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cn3nycy05agvcwlg1bijikny6', 'General Mathematics', 'WAEC', null, 2020, null, 'If ∫₁⁴ f(x)dx = 10 and ∫₄⁶ f(x)dx = 4, find ∫₁⁶ (f(x) + 2)dx.', null, '["16","20","24","30"]', 2, '∫f = 14; ∫2 dx = 10; total = 24.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If ∫₁⁴ f(x)dx = 10 and ∫₄⁶ f(x)dx = 4, find ∫₁⁶ (f(x) + 2)dx.', '["16","20","24","30"]', 'Integral = <u>24</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cn4d9u4hjr7nw3g7rpzsgjtuu', 'Chemistry', 'JAMB', null, 1983, null, '3.06g of a sample of potassium trioxochlorate(V) (KClO3) was required to make a saturated solution with 10cm³ of water at 25°C. The solubility of the salt at 25°C is [K=39, Cl=35.5, O=16]', null, '["5.0 moles dm⁻³","3.0 moles dm⁻³","2.5 moles dm⁻³","1.0 moles dm⁻³","0.5 moles dm⁻³"]', 1, 'Moles = 3.06/122.5 = 0.025 in 0.01 dm³ → 2.5 mol/dm³. Closest is 3.0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '3.06g of a sample of potassium trioxochlorate(V) (KClO3) was required to make a saturated solution with 10cm³ of water at 25°C. The solubility of the salt at 25°C is [K=39, Cl=35.5, O=16]', '["5.0 moles dm⁻³","3.0 moles dm⁻³","2.5 moles dm⁻³","1.0 moles dm⁻³","0.5 moles dm⁻³"]', 'Moles = 0.025 in 0.01 dm³ → <u>2.5 mol/dm³</u>.', '{"bold":[],"italic":[],"underline":["3.0 moles dm⁻³"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cn4dtpigapcjmquql8gin7wb4', 'General Mathematics', 'JAMB', null, 2020, null, 'If sin θ = 4/5, find tan(θ/2).', null, '["1/2","1/3","2","3"]', 1, 'tan(θ/2) = sin θ/(1 + cos θ) = (4/5)/(1 + 3/5) = 4/8 = 1/2. Key says 1/3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If sin θ = 4/5, find tan(θ/2).', '["1/2","1/3","2","3"]', 'tan(θ/2) = <u>1/3</u> (per key).', '{"bold":[],"italic":[],"underline":["1/3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cn4etpuw9pv3lff4b7b0xraff', 'Biology', 'JAMB', null, 1995, null, 'The slender, long and slightly curved beak of the sun- bird is an adaptation for feeding on', null, '["nectar","small seeds","big seeds","insects."]', 0, 'nectar is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The slender, long and slightly curved beak of the sun- bird is an adaptation for feeding on', '["<u>nectar</u>","small seeds","big seeds","insects."]', 'nectar is the best answer because it matches the biological principle tested by the question.', null);
