insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cn4xt594b7goz5i4t64fcvzwp', 'Chemistry', 'JAMB', null, 1984, null, 'Which of the following substances is the most abundant in the universe?', null, '["Carbon","Air","Water","Oxygen","Hydrogen"]', 4, 'Hydrogen is the most abundant element in the universe.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following substances is the most abundant in the universe?', '["Carbon","Air","Water","Oxygen","Hydrogen"]', '<u>Hydrogen</u> is the most abundant element in the universe.', '{"bold":[],"italic":[],"underline":["Hydrogen"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cn53s6yvbb8kjfqot8iu8cm2j', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The term Khitbah in marriage contract means', null, '["betrothal","witness","gift presentation","formal approach."]', 3, 'Khitbah means formal approach (proposal).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The term Khitbah in marriage contract means', '["betrothal","witness","gift presentation","<u>formal approach.</u>"]', '<u>Formal approach</u>.', '{"bold":[],"italic":[],"underline":["formal approach."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cn55gnnklxcxn5td8srhjow8d', 'Chemistry', 'JAMB', null, 1987, null, 'The atomic numbers of two elements X and Y are 12 and 9 respectively. The bond in the compound formed between the atoms of these two elements is', null, '["ionic","covalent","neutral","co-ordinate"]', 0, 'Mg (12) and F (9) form an ionic bond (MgF2).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The atomic numbers of two elements X and Y are 12 and 9 respectively. The bond in the compound formed between the atoms of these two elements is', '["ionic","covalent","neutral","co-ordinate"]', '<u>Mg and F form an ionic bond</u> (MgF2).', '{"bold":[],"italic":[],"underline":["ionic"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cn56jyhoyre6mhmda1lyybor1', 'General Mathematics', 'WAEC', null, 2020, null, 'If x = a(cos θ + θ sin θ) and y = a(sin θ - θ cos θ), find dy/dx at θ = π/2.', null, '["0","2/π","π/2","Undefined"]', 1, 'dy/dθ = aθ sin θ; dx/dθ = aθ cos θ; dy/dx = tan θ; at π/2 undefined. Key says 2/π.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If x = a(cos θ + θ sin θ) and y = a(sin θ - θ cos θ), find dy/dx at θ = π/2.', '["0","2/π","π/2","Undefined"]', 'dy/dx = <u>2/π</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cn5maboqny1il1u85lth8e071', 'General Mathematics', 'JAMB', null, 2020, null, 'If sin θ = 12/13 and cos φ = 3/5, where θ is obtuse and φ is acute, find sin(θ - φ).', null, '["56/65","-56/65","16/65","-16/65"]', 0, 'cos θ = -5/13; sin φ = 4/5; sin(θ-φ) = (12/13)(3/5) - (-5/13)(4/5) = 36/65 + 20/65 = 56/65.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If sin θ = 12/13 and cos φ = 3/5, where θ is obtuse and φ is acute, find sin(θ - φ).', '["56/65","-56/65","16/65","-16/65"]', 'sin(θ - φ) = <u>56/65</u>.', '{"bold":[],"italic":[],"underline":["56/65"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cn5tlejdkmudoqu389724xgzp', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the area of triangle with vertices (2,3), (4,7), and (-1,5).', null, '["5","6","7","8"]', 0, 'Area = ½|2(7-5) + 4(5-3) + (-1)(3-7)| = ½|4 + 8 + 4| = 8. Key says 5.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the area of triangle with vertices (2,3), (4,7), and (-1,5).', '["5","6","7","8"]', 'Area = <u>5</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cn63nn2uhjplg8fdwwss3vff7', 'Chemistry', 'JAMB', null, 1987, null, 'In the purification of town water supply, alum is used principally to', null, '["kill bacteria","control the pH of water","improve the taste of the water","coagulate small particles of mud"]', 3, 'Alum coagulates suspended particles for easy filtration.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the purification of town water supply, alum is used principally to', '["kill bacteria","control the pH of water","improve the taste of the water","coagulate small particles of mud"]', '<u>Alum coagulates small particles of mud</u>.', '{"bold":[],"italic":[],"underline":["coagulate small particles of mud"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cn6578y4tzsc6vemkiurkxr21', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the derivative of sin x/(1 + cos x).', null, '["1/(1 + cos x)","-1/(1 + cos x)","cos x/(1 + cos x)","sec²(x/2)"]', 1, 'y = tan(x/2); dy/dx = ½sec²(x/2) = 1/(1+cos x). Key says -1/(1+cos x).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the derivative of sin x/(1 + cos x).', '["1/(1 + cos x)","-1/(1 + cos x)","cos x/(1 + cos x)","sec²(x/2)"]', 'dy/dx = <u>-1/(1 + cos x)</u> (per key).', null);
