insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cn6cycboi9ti0i4zdn807et43', 'Biology', 'JAMB', null, 1990, null, 'The older fossil-bearing rocks, in contrast to the more recent ones, are more likely to contain', null, '["animals rather than plant remains","invertebrates rather than birds","flowering plants rather than mosses","reptiles rather that fishes"]', 1, 'Older rocks contain invertebrates rather than birds.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The older fossil-bearing rocks, in contrast to the more recent ones, are more likely to contain', '["animals rather than plant remains","<u>invertebrates rather than birds</u>","flowering plants rather than mosses","reptiles rather that fishes"]', 'Older rocks contain <u>invertebrates rather than birds</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cn6ena86wy1lkl7e6h33wfr0r', 'Government', 'JAMB', null, 2020, null, 'The centre piece of Nigeria''s foreign policy covers only', null, '["Latin America","Asia","Europe","Africa"]', 3, 'Africa is the centre-piece of Nigeria''s foreign policy.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The centre piece of Nigeria''s foreign policy covers only', '["Latin America","Asia","Europe","<u>Africa</u>"]', '<u>Africa</u>.', '{"bold":[],"italic":[],"underline":["Africa"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cn6fxwte2nlzno97u8tzjindf', 'General Mathematics', 'JAMB', null, 2020, null, 'Angle between lines 2x - y + 3 = 0 and x + 3y - 4 = 0.', null, '["45°","60°","90°","30°"]', 2, 'm₁ = 2, m₂ = -1/3; m₁m₂ = -1 → perpendicular.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Angle between lines 2x - y + 3 = 0 and x + 3y - 4 = 0.', '["45°","60°","90°","30°"]', 'Angle = <u>90°</u>.', '{"bold":[],"italic":[],"underline":["90°"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cn6prm3fh2ltanuzqrhlvb5c3', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Which of the following sets, according to Ayatul Kursiyy, is Allah not susceptible to?', null, '["Thirst or hunger","Slumber or sleep","Fear or terror","Sickness or pain."]', 1, 'Allah is not susceptible to slumber or sleep.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following sets, according to Ayatul Kursiyy, is Allah not susceptible to?', '["Thirst or hunger","<u>Slumber or sleep</u>","Fear or terror","Sickness or pain."]', '<u>Slumber or sleep</u> (Q. 2:255).', '{"bold":[],"italic":[],"underline":["Slumber or sleep"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cn6sl6c1kmalgyg7agwwzxqba', 'General Mathematics', 'JAMB', null, 2020, null, 'If 70% drink coffee, 60% drink tea, 20% drink neither. What percentage drink both?', null, '["50%","55%","60%","65%"]', 0, 'At least one = 80%; both = 70 + 60 - 80 = 50%.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If 70% drink coffee, 60% drink tea, 20% drink neither. What percentage drink both?', '["50%","55%","60%","65%"]', 'Both = <u>50%</u>.', '{"bold":[],"italic":[],"underline":["50%"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cn712d0nrv18yz6vfy0yspog1', 'Islamic Religious Studies', 'JAMB', null, 2010, null, '[Arabic verse] The verse of the Glorious Qur''an above is on the importance of knowledge and the description of Allah as', null, '["the Supreme","the most Gracious","the Grand Teacher","the Grand Supplier"]', 2, 'Q.96:5 describes Allah as the One who taught man.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '[Arabic verse] The verse of the Glorious Qur''an above is on the importance of knowledge and the description of Allah as', '["the Supreme","the most Gracious","<u>the Grand Teacher</u>","the Grand Supplier"]', 'Q.96:5 describes Allah as <u>the Grand Teacher</u>.', '{"bold":[],"italic":[],"underline":["the Grand Teacher"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cn75jowd478q27ks7r5jsn4cy', 'Biology', 'JAMB', null, 2002, null, 'Genetic counselling is important when a marriage is planned between a', null, '["Rh⁺ woman and Rh⁻ man","Rh⁻ woman and Rh⁺ man","Rh⁻ woman and Rh⁻ man","Rh⁺ woman and Rh⁺ man"]', 1, 'Rh⁻ woman + Rh⁺ man risks Rh incompatibility.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Genetic counselling is important when a marriage is planned between a', '["Rh⁺ woman and Rh⁻ man","Rh⁻ woman and Rh⁺ man","Rh⁻ woman and Rh⁻ man","Rh⁺ woman and Rh⁺ man"]', '<u>Rh⁻ woman and Rh⁺ man</u>.', '{"bold":[],"italic":[],"underline":["Rh⁻ woman and Rh⁺ man"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cn7g87tcscp1qc6jdaete155r', 'Biology', 'JAMB', null, 2000, null, 'In a group of male Agama lizards, the one brightest head colour is the', null, '["dominant","youngest","oldest","largest"]', 2, 'oldest is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In a group of male Agama lizards, the one brightest head colour is the', '["dominant","youngest","<u>oldest</u>","largest"]', 'oldest is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cn7ib34nz1g96p2b22s3sqf60', 'General Mathematics', 'WAEC', null, 2020, null, 'Three persons hit a target with probabilities 1/2, 1/3, 1/4. Find the probability exactly one hits.', null, '["11/24","13/24","15/24","17/24"]', 0, 'P = (1/2)(2/3)(3/4) + (1/2)(1/3)(3/4) + (1/2)(2/3)(1/4) = 6/24 + 3/24 + 2/24 = 11/24.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Three persons hit a target with probabilities 1/2, 1/3, 1/4. Find the probability exactly one hits.', '["11/24","13/24","15/24","17/24"]', 'P = <u>11/24</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cn7lolbd5fd2e2s8bm1bltgf9', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the values of p for which the equation (p - 2)x² + 4x + (p + 2) = 0 has two equal real roots.', null, '["±2","±2√2","±4","±3"]', 1, 'Discriminant = 0 → 16 - 4(p-2)(p+2) = 0 → 16 - 4(p²-4) = 0 → p² = 8 → p = ±2√2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the values of p for which the equation (p - 2)x² + 4x + (p + 2) = 0 has two equal real roots.', '["±2","±2√2","±4","±3"]', 'p = <u>±2√2</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cn7mfaxxjohilx9xpjvclacn2', 'Chemistry', 'JAMB', null, 1991, null, 'Oxygen gas can be prepared by heating', null, '["ammonium trioxonitrate(V)","ammonium trioxonitrate(III)","potassium trioxochlorate(V)","manganese(IV) oxide"]', 2, '2KClO3 → 2KCl + 3O2 on heating.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Oxygen gas can be prepared by heating', '["ammonium trioxonitrate(V)","ammonium trioxonitrate(III)","potassium trioxochlorate(V)","manganese(IV) oxide"]', '<u>2KClO3 → 2KCl + 3O2</u>.', '{"bold":[],"italic":[],"underline":["potassium trioxochlorate(V)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cn7rlkbss8ukut5aw0ufwbt8j', 'Chemistry', 'JAMB', null, 1995, null, 'The solubility in moles per dm³ of 20g of CuSO4 dissolved in 100g of water at 18°C is', null, '["0.13","0.25","1.25","2.00 [Cu=63.5, S=32, O=16]"]', 2, 'Moles CuSO4 = 20/159.5 = 0.125 in 0.1 dm³ → 1.25 mol/dm³.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The solubility in moles per dm³ of 20g of CuSO4 dissolved in 100g of water at 18°C is', '["0.13","0.25","1.25","2.00"]', 'Moles = 0.125 in 0.1 dm³ → <u>1.25 mol/dm³</u>.', '{"bold":[],"italic":[],"underline":["1.25"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cn7toga6kzc8mrs3xzxmusrxx', 'General Mathematics', 'JAMB', null, 2020, null, 'Find ∫ x²/(x² + 1)² dx.', null, '["½(tan⁻¹x - x/(x² + 1)) + C","tan⁻¹x + x/(x² + 1) + C","tan⁻¹x - 1/(x² + 1) + C","tan⁻¹x + 1/(x² + 1) + C"]', 0, 'Substitution x = tan θ; result = ½(tan⁻¹x - x/(x²+1)) + C.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find ∫ x²/(x² + 1)² dx.', '["½(tan⁻¹x - x/(x² + 1)) + C","tan⁻¹x + x/(x² + 1) + C","tan⁻¹x - 1/(x² + 1) + C","tan⁻¹x + 1/(x² + 1) + C"]', 'Integral = <u>½(tan⁻¹x - x/(x² + 1)) + C</u>.', '{"bold":[],"italic":[],"underline":["½(tan⁻¹x - x/(x² + 1)) + C"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cn84hfcvjweb0dda1hfare3nn', 'Biology', 'JAMB', null, 1983, null, 'In Rhizopus, carbonhydrate is stored in the form of', null, '["glucose","paramylon","glycogen","starch","oil"]', 2, 'Rhizopus stores carbohydrate as glycogen.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In <b>Rhizopus</b>, carbonhydrate is stored in the form of', '["glucose","paramylon","<u>glycogen</u>","starch","oil"]', '<u>Rhizopus</u> stores carbohydrate as <u>glycogen</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cn8ayaub79kgs94j0s6p15mgo', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the locus of a point such that its distance from (2, 3) is twice its distance from (5, 7).', null, '["Circle","Ellipse","Hyperbola","Parabola"]', 0, 'Distance ratio 2:1 → circle of Apollonius.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the locus of a point such that its distance from (2, 3) is twice its distance from (5, 7).', '["Circle","Ellipse","Hyperbola","Parabola"]', '<u>Circle</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cn8c4r8t9vwm1d0uvykvtqw5p', 'Chemistry', 'JAMB', null, 1999, null, 'In which of the following are water molecules in the <b>most disorderly arrangement</b>?', null, '["Ice at -10°C","Ice at 0°C","Water at 100°C","Steam at 100°C"]', 3, 'Gas (steam) has the most disorder.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In which of the following are water molecules in the <b>most disorderly arrangement</b>?', '["Ice at -10°C","Ice at 0°C","Water at 100°C","Steam at 100°C"]', '<u>Steam at 100°C</u> is most disorderly.', '{"bold":["most disorderly arrangement"],"italic":[],"underline":["Steam at 100°C"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cn8imxi0r3rldswqq72dc3z5r', 'Chemistry', 'JAMB', null, 1999, null, 'Given that electronegativity increases across a period and decreases down a group in the periodic table, in which of the following compounds will the molecules be held together by the <b>strongest hydrogen bond</b>?', null, '["HF(g)","NH3(g)","CH4(g)","HCl(g)"]', 0, 'F is most electronegative → strongest H-bond in HF.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Given that electronegativity increases across a period and decreases down a group in the periodic table, in which of the following compounds will the molecules be held together by the <b>strongest hydrogen bond</b>?', '["HF(g)","NH3(g)","CH4(g)","HCl(g)"]', '<u>HF</u> has the strongest hydrogen bond.', '{"bold":["strongest hydrogen bond"],"italic":[],"underline":["HF(g)"],"fillBlanks":[]}');
