insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cn8pwj9gfgbsfddmajx6vhoat', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the volume generated when the area bounded by y = x² and y = 4 is rotated about the x-axis.', null, '["128π/5","256π/5","512π/5","1024π/5"]', 0, 'V = π∫₋₂² (16 - x⁴)dx = 128π/5.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the volume generated when the area bounded by y = x² and y = 4 is rotated about the x-axis.', '["128π/5","256π/5","512π/5","1024π/5"]', 'Volume = <u>128π/5</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cn8t8epfvpxqvwouecomsbfya', 'General Mathematics', 'WAEC', null, 2020, null, 'The line y = x + 2 meets the circle x² + y² = 4 at points A and B. Find the equation of the circle on AB as diameter.', null, '["x² + y² + 2x - 2y = 0","x² + y² - 2x + 2y = 0","x² + y² + 2x + 2y = 0","x² + y² - 2x - 2y = 0"]', 0, 'A(-2,0), B(0,2); center (-1,1); radius √2; equation: x² + y² + 2x - 2y = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The line y = x + 2 meets the circle x² + y² = 4 at points A and B. Find the equation of the circle on AB as diameter.', '["x² + y² + 2x - 2y = 0","x² + y² - 2x + 2y = 0","x² + y² + 2x + 2y = 0","x² + y² - 2x - 2y = 0"]', 'Equation: <u>x² + y² + 2x - 2y = 0</u>.', null);
