insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cn9aktj6bc3c5bk734wmrzyg7', 'Islamic Religious Studies', 'JAMB', null, 2011, null, 'The term, <b>Shari''ah</b> refers to', null, '["a path","wisdom","passion","an idea"]', 0, 'Shari''ah literally means a path.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The term, <b>Shari''ah</b> refers to', '["<u>a path</u>","wisdom","passion","an idea"]', '<u>Shari''ah</u> literally means a path.', '{"bold":["Shari''ah"],"italic":[],"underline":["a path"],"fillBlanks":[]}');
