insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cn9giqfclvo7o8dn3k0jjy0sq', 'Government', 'JAMB', null, 2020, null, 'A major factor that influenced the formation of Nigeria''s foreign policy in the First Republic was', null, '["geographical location","the colonial legacy","economic consideration","the parliamentary system"]', 1, 'Colonial legacy influenced Nigeria''s foreign policy in the First Republic.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A major factor that influenced the formation of Nigeria''s foreign policy in the First Republic was', '["geographical location","<u>the colonial legacy</u>","economic consideration","the parliamentary system"]', '<u>Colonial legacy</u>.', '{"bold":[],"italic":[],"underline":["the colonial legacy"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cn9q7ocavkoahwvgbw8yrrdkn', 'Government', 'JAMB', null, 2020, null, 'Associations whose main interest is to influence public policies without having to capture power are', null, '["communal groups.","trade unions","political parties","pressure groups"]', 3, 'Pressure groups influence policy without capturing power.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Associations whose main interest is to influence public policies without having to capture power are', '["communal groups.","trade unions","political parties","<u>pressure groups</u>"]', '<u>Pressure groups</u>.', '{"bold":[],"italic":[],"underline":["pressure groups"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnaadcm28cs9s0hxoksmli0ph', 'Chemistry', 'JAMB', null, 1990, null, 'Which of the following is formed when <b>maltose</b> reacts with concentrated tetraoxosulphate(VI) acid?', null, '["Carbon(IV) oxide","Coal tar","Charcoal","Toxic fumes"]', 2, 'Concentrated H2SO4 dehydrates maltose to charcoal (carbon).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is formed when <b>maltose</b> reacts with concentrated tetraoxosulphate(VI) acid?', '["Carbon(IV) oxide","Coal tar","Charcoal","Toxic fumes"]', '<u>Charcoal (carbon)</u> is formed.', '{"bold":["maltose"],"italic":[],"underline":["Charcoal"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnahh7q4uwst2aub6dd0qz0u8', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Q. 2:256 says that there is no compulsion in religion because', null, '["truth stands out clear from error","man is free to choose his religion","religion is a personal affair","faith is a matter of the heart"]', 0, 'Truth stands out clear from error.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Q. 2:256 says that there is no compulsion in religion because', '["<u>truth stands out clear from error</u>","man is free to choose his religion","religion is a personal affair","faith is a matter of the heart"]', '<u>Truth stands out clear from error</u> (Q. 2:256).', '{"bold":[],"italic":[],"underline":["truth stands out clear from error"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnaotqdour3r7mjqwpc1wxlzr', 'Chemistry', 'JAMB', null, 1995, null, 'The effluent of an industrial plant used in the electrolysis of concentrated brine, with a flowing mercury cathode may contain impurities like', null, '["oxygen","hydrogen","mercury(II) chloride","hydrogen chloride"]', 2, 'Mercury cathode cells can release mercury compounds as impurities.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The effluent of an industrial plant used in the electrolysis of concentrated brine, with a flowing mercury cathode may contain impurities like', '["oxygen","hydrogen","mercury(II) chloride","hydrogen chloride"]', '<u>Mercury(II) chloride</u> can be an impurity.', '{"bold":[],"italic":[],"underline":["mercury(II) chloride"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnaujnsy6mc8flgb23l5lqq11', 'General Mathematics', 'WAEC', null, 2020, null, 'A committee of 5 is to be formed from 4 men and 6 women. If the committee must consist of at least 3 men, find the number of ways of forming the committee.', null, '["60","66","100","186"]', 1, 'At least 3 men: 4C3·6C2 + 4C4·6C1 = 60 + 6 = 66.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A committee of 5 is to be formed from 4 men and 6 women. If the committee must consist of at least 3 men, find the number of ways of forming the committee.', '["60","66","100","186"]', 'Ways = <u>66</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnausado5gxkzmfd9qavvqhic', 'English Language', 'JAMB', null, 2020, null, 'If the arrangement does not work out, it''s _____ who lose.', null, '["you and me","them and she","you and I","me and you."]', 2, 'Subject pronoun "you and I" before "lose".', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If the arrangement does not work out, it''s _____ who lose.', '["you and me","them and she","you and I","me and you."]', 'Subject: <u>you and I</u>.', '{"bold":[],"italic":[],"underline":["you and I"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnbas0dc4k7nct35agsvzzdp2', 'Biology', 'JAMB', null, 1992, null, 'In mammalian development, the function of the yolk is to', null, '["supply nutrients to the embryo","acts as the shock-absorber to the foetus","supply air to the embryo","facilitate the process of excretion in the foetus"]', 0, 'The yolk supplies nutrients to the embryo.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In mammalian development, the function of the <b>yolk</b> is to', '["<u>supply nutrients to the embryo</u>","acts as the shock-absorber to the foetus","supply air to the embryo","facilitate the process of excretion in the foetus"]', 'The yolk <u>supplies nutrients to the embryo</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnbcw65od8equce8gw8wuz9vc', 'Chemistry', 'JAMB', null, 1995, null, 'The volume occupied by 1.58g of a gas at s.t.p is 500cm³. What is the relative molecular mass of the gas?', null, '["28","32","344","71"]', 2, 'Moles = 0.5/22.4 = 0.0223; Mr = 1.58/0.0223 = 71. Key says 344.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The volume occupied by 1.58g of a gas at s.t.p is 500cm³. What is the relative molecular mass of the gas?', '["28","32","344","71"]', 'Moles = 0.0223; Mr = <u>71</u> (key says 344).', '{"bold":[],"italic":[],"underline":["344"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnbdrz0kn018pzu6cixbw3ct4', 'Islamic Religious Studies', 'JAMB', null, 2002, null, 'The number of lashes prescribed for the consumption of alcohol is', null, '["forty","sixty","eighty","hundred"]', 2, 'Eighty lashes is the prescribed penalty for alcohol consumption.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The number of lashes prescribed for the consumption of alcohol is', '["forty","sixty","<u>eighty</u>","hundred"]', '<u>Eighty lashes</u> is the prescribed penalty for alcohol consumption.', '{"bold":[],"italic":[],"underline":["eighty"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnbk6msmubpmcmsjkyxi3seze', 'Chemistry', 'JAMB', null, 1999, null, 'The solution with the <b>lowest pH value</b> is', null, '["5ml of M/10 HCl","10ml of M/10 HCl","15ml of M/10 HCl","20ml of M/10 HCl"]', 3, 'pH depends on concentration, not volume; all have same pH. But if HCl is added to water, larger volume of same conc. — all same pH. Key says 20ml.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The solution with the <b>lowest pH value</b> is', '["5ml of M/10 HCl","10ml of M/10 HCl","15ml of M/10 HCl","20ml of M/10 HCl"]', 'All have <u>same pH</u> (same concentration); key says 20ml.', '{"bold":["lowest pH value"],"italic":[],"underline":["20ml of M/10 HCl"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnbmaw29nmdf0yaz4whihjx8o', 'General Mathematics', 'JAMB', null, 2020, null, 'What is the cardinality of the power set of {∅, {∅}, {∅, {∅}}}?', null, '["8","4","16","2","None of these"]', 0, 'Set has 3 elements → power set has 2³ = 8 elements.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is the cardinality of the power set of {∅, {∅}, {∅, {∅}}}?', '["8","4","16","2","None of these"]', 'Cardinality = <u>8</u>.', '{"bold":[],"italic":[],"underline":["8"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnbruydy5d3ohfws9wfy0gm2h', 'Biology', 'JAMB', null, 2000, null, 'Which of the following features are all associated with <b>monocots</b>?', null, '["Fibrous root system, branched network of veins and one seed leaf","Fibrous root system, two seed leaves and floral parts in threes","One seed leaf, petals in threes or groups of threes and parallel venation of leaves","One seed leaf, net-veined leaves and petals in three or multiples of three"]', 2, 'Monocots: one seed leaf, floral parts in threes, parallel venation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following features are all associated with <b>monocots</b>?', '["Fibrous root system, branched network of veins and one seed leaf","Fibrous root system, two seed leaves and floral parts in threes","One seed leaf, petals in threes or groups of threes and parallel venation of leaves","One seed leaf, net-veined leaves and petals in three or multiples of three"]', '<u>One seed leaf, floral parts in threes, parallel venation</u>.', '{"bold":["monocots"],"italic":[],"underline":["One seed leaf, petals in threes or groups of threes and parallel venation of leaves"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnbsomk5nbguvzg2kbhblxyne', 'Chemistry', 'JAMB', null, 2004, null, 'According to Charles'' law, the volume of a gas becomes zero at', null, '["-100°C","-273°C","-373°C","0°C"]', 1, 'Volume becomes zero at absolute zero (-273°C).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to Charles'' law, the volume of a gas becomes zero at', '["-100°C","-273°C","-373°C","0°C"]', '<u>-273°C</u> (absolute zero).', '{"bold":[],"italic":[],"underline":["-273°C"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnc30anljlq74xcxc3tg4z312', 'Chemistry', 'JAMB', null, 1993, null, 'How many moles of oxygen molecules would be produced from the decomposition of 2.5 moles of potassium trioxochlorate(V)?', null, '["2.50","3.50","3.75","7.50"]', 2, '2KClO3 → 2KCl + 3O2; 2.5 mol KClO3 gives 3.75 mol O2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'How many moles of oxygen molecules would be produced from the decomposition of 2.5 moles of potassium trioxochlorate(V)?', '["2.50","3.50","3.75","7.50"]', '<u>3.75 mol O2</u>.', '{"bold":[],"italic":[],"underline":["3.75"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnc9h2x1l5bz0e51f2vtf9mb0', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the shortest distance between the curves y² = 4x and x² = 4y.', null, '["0","2√2","4√2","8√2"]', 0, 'Curves intersect at origin; distance = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the shortest distance between the curves y² = 4x and x² = 4y.', '["0","2√2","4√2","8√2"]', 'Shortest distance = <u>0</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cncln9ebfimjz68ah6zje1hlx', 'General Mathematics', 'WAEC', null, 2020, null, 'If 40% like red, 30% like blue, 50% like green, 10% like all three, 15% like red and blue only, 5% like blue and green only, 10% like red and green only. What percentage like none?', null, '["10%","30%","20%","25%"]', 1, 'Union = 40+30+50 - (25+15+20) + 10 = 70%; none = 30%.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'If 40% like red, 30% like blue, 50% like green, 10% like all three, 15% like red and blue only, 5% like blue and green only, 10% like red and green only. What percentage like none?', '["10%","30%","20%","25%"]', 'Union = 40+30+50 - (25+15+20) + 10 = 70%; none = 30%.', null);
