insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cndl3nvig8rc0f3q7hxrfeg2z', 'Chemistry', 'JAMB', null, 1987, null, 'Which of the following statements is CORRECT if 1 Faraday of electricity is passed through 1 M CuSO4 solution for 1 minute?', null, '["The pH of the solution at the cathode decreases","The pH of the solution at the anode decreases","1 mole of Cu will be liberated at the cathode","60 moles of Cu will be liberated at the anode"]', 1, 'At the anode, OH⁻ is discharged, leaving H⁺, so pH decreases.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following statements is CORRECT if 1 Faraday of electricity is passed through 1 M CuSO4 solution for 1 minute?', '["The pH of the solution at the cathode decreases","The pH of the solution at the anode decreases","1 mole of Cu will be liberated at the cathode","60 moles of Cu will be liberated at the anode"]', '<u>At the anode, pH decreases</u> (OH⁻ discharged).', '{"bold":["CORRECT"],"italic":[],"underline":["The pH of the solution at the anode decreases"],"fillBlanks":[]}');
