insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnequpss9xpc9zvvgo2nvp3ao', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'According to Jeremiah, the role of the shepherds which God will give to His people is to', null, '["feed the people with knowledge and understanding","heal the guilt of the people","gather the scattered children of Israel together.","lead them to greener pastures."]', 0, 'They will feed the people with knowledge and understanding.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to Jeremiah, the role of the shepherds which God will give to His people is to', '["<u>feed the people with knowledge and understanding</u>","heal the guilt of the people","gather the scattered children of Israel together.","lead them to greener pastures."]', '<u>Feed the people with knowledge and understanding</u> (Jeremiah 3:15).', '{"bold":[],"italic":[],"underline":["feed the people with knowledge and understanding"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnetbxmdphd89etzf98cs0agh', 'Government', 'JAMB', null, 2020, null, 'The method used to determine the possible outcome of an electoral contest is', null, '["press review","plebiscite","opinion poll","referendum"]', 2, 'Opinion polls determine likely electoral outcomes.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The method used to determine the possible outcome of an electoral contest is', '["press review","plebiscite","<u>opinion poll</u>","referendum"]', '<u>Opinion poll</u>.', '{"bold":[],"italic":[],"underline":["opinion poll"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cneudcjognityavkebql1gcp0', 'Biology', 'JAMB', null, 1984, null, 'If an animal is very active and has good muscular control, it is likely to have well-developed', null, '["olfactory lobes","cerebral hemispheres","optic lobes","cerebellum","spinal cord"]', 3, 'The cerebellum controls muscular coordination.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If an animal is very active and has good muscular control, it is likely to have well-developed', '["olfactory lobes","cerebral hemispheres","optic lobes","<u>cerebellum</u>","spinal cord"]', 'The <u>cerebellum</u> controls muscular coordination.', null);
