insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnfqzuojrem0cwf6k0pz8e4ge', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The collections regarded as the most authentic in Hadith literature are those of', null, '["Bukhari and Muslim","Bukhari and Abu Dawud","Ibn Majah and at-Tirmidhi","Imam Malik and Ibn Hanbal."]', 0, 'Bukhari and Muslim are the most authentic.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The collections regarded as the most authentic in Hadith literature are those of', '["<u>Bukhari and Muslim</u>","Bukhari and Abu Dawud","Ibn Majah and at-Tirmidhi","Imam Malik and Ibn Hanbal."]', '<u>Bukhari and Muslim</u>.', '{"bold":[],"italic":[],"underline":["Bukhari and Muslim"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnfu33vfdplczxe0dtnqzrvzh', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The uniqueness of the Glorious Qur''an, according to Q.39:28, lies in the fact that it is', null, '["highly educative","in brief form","revealed piecemeal","revealed in Arabic."]', 3, 'It is revealed in Arabic.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The uniqueness of the Glorious Qur''an, according to Q.39:28, lies in the fact that it is', '["highly educative","in brief form","revealed piecemeal","<u>revealed in Arabic.</u>"]', '<u>Revealed in Arabic</u> (Q. 39:28).', '{"bold":[],"italic":[],"underline":["revealed in Arabic."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnfvp0j3bqjr61ldrse3295od', 'Government', 'JAMB', null, 2020, null, 'The pre-colonial Tiv society can best be described as', null, '["republican","aristocratic","feudalistic.","monarchical"]', 0, 'Tiv society was republican.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The pre-colonial Tiv society can best be described as', '["<u>republican</u>","aristocratic","feudalistic.","monarchical"]', '<u>Republican</u>.', '{"bold":[],"italic":[],"underline":["republican"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cng3s6n3cyojvz9g785rcnj27', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Imam Ash-shafi''i studied under two of his predecessors. These are', null, '["Abu Hurayrah and Malik","Malik and Abu Hanifah","Abu Hanifah and ''Umar","''Umar and Abu Bakr."]', 1, 'He studied under Malik and Abu Hanifah.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Imam Ash-shafi''i studied under two of his predecessors. These are', '["Abu Hurayrah and Malik","<u>Malik and Abu Hanifah</u>","Abu Hanifah and ''Umar","''Umar and Abu Bakr."]', '<u>Malik and Abu Hanifah</u>.', '{"bold":[],"italic":[],"underline":["Malik and Abu Hanifah"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cng5glvgave38sbnyofptwv2y', 'Biology', 'JAMB', null, 2002, null, 'To select and retain the desirable trait of large body size with farmer has observed in his herd, the farmer needs to', null, '["feed the animals in the herd with more food","cross-breed his animals with a different herd","inbreed the animals in his herd","prevent diseases in his herd"]', 1, 'cross-breed his animals with a different herd is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'To select and retain the desirable trait of large body size with farmer has observed in his herd, the farmer needs to', '["feed the animals in the herd with more food","<u>cross-breed his animals with a different herd</u>","inbreed the animals in his herd","prevent diseases in his herd"]', 'cross-breed his animals with a different herd is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cngiv8abzqq8azvcjits7lqx1', 'Biology', 'JAMB', null, 1988, null, 'The mineral nutrient that easily gets leached out of the soil is', null, '["phosphorus","calcium","magnesium","nitrate"]', 3, 'Nitrate is easily leached out of the soil.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The mineral nutrient that easily gets leached out of the soil is', '["phosphorus","calcium","magnesium","<u>nitrate</u>"]', '<u>Nitrate</u> is easily leached out of the soil.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cngmcwp87w5ovhk1m1jskr2qi', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve |x 2 3; 1 x 2; 2 1 x| = 0.', null, '["1, -3","-1, 3","2, -2","1, -2"]', 0, 'x³ - 6x + 9 = 0... solving gives x = 1 or x = -3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve |x 2 3; 1 x 2; 2 1 x| = 0.', '["1, -3","-1, 3","2, -2","1, -2"]', 'x = <u>1, -3</u>.', '{"bold":[],"italic":[],"underline":["1, -3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cngo8z51dg4b79mrnbak2zsh4', 'General Mathematics', 'WAEC', null, 2020, null, 'If one root of 3x² - 7x + k = 0 is the reciprocal of the other, find k', null, '["1","2","3","4"]', 1, 'α × 1/α = 1 → k/3 = 1 → k = 3. Key says 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If one root of 3x² - 7x + k = 0 is the reciprocal of the other, find k', '["1","2","3","4"]', 'k/3 = 1 → <u>k = 3</u> (key says 2).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnguqz9gfxgm5yjpwvo9uwv72', 'Biology', 'JAMB', null, 1998, null, 'The natural tendency of organism as they evolve is to', null, '["decrease in size","increase in number","develop specialized structures","feed indiscriminately."]', 2, 'develop specialized structures is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The natural tendency of organism as they evolve is to', '["decrease in size","increase in number","<u>develop specialized structures</u>","feed indiscriminately."]', 'develop specialized structures is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnh83r31iwhlfhy9l3a0ki8n3', 'Biology', 'JAMB', null, 2003, null, 'The type of reproduction that leads to <b>variation</b> in animal and plant populations is', null, '["budding","vegetative","asexual","sexual"]', 3, 'Sexual reproduction creates variation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The type of reproduction that leads to <b>variation</b> in animal and plant populations is', '["budding","vegetative","asexual","sexual"]', '<u>Sexual reproduction</u>.', '{"bold":["variation"],"italic":[],"underline":["sexual"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnhah30jpu4800jnhsmi5po4b', 'Chemistry', 'JAMB', null, 1983, null, 'In the reaction M + N ⇌ P, ΔH = +Q kJ. Which of the following would increase the concentration of the product?', null, '["Decreasing the concentration of N","Increasing the concentration of P","Adding a suitable catalyst","Decreasing the temperature"]', 3, 'For an endothermic reaction (+ΔH), decreasing temperature shifts equilibrium to the right (product side).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the reaction M + N ⇌ P, ΔH = +Q kJ. Which of the following would increase the concentration of the product?', '["Decreasing the concentration of N","Increasing the concentration of P","Adding a suitable catalyst","Decreasing the temperature"]', 'For an <u>endothermic reaction</u>, decreasing temperature shifts equilibrium to the right.', '{"bold":[],"italic":[],"underline":["Decreasing the temperature"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnhg804x6i9h9offa8b8c22lo', 'Chemistry', 'JAMB', null, 1988, null, 'Which of the following substances is a <b>basic salt</b>?', null, '["Na2CO3","Mg(OH)Cl","NaHCO3","K2SO4·Al2(SO4)3·24H2O"]', 1, 'Mg(OH)Cl is a basic salt (contains OH⁻).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following substances is a <b>basic salt</b>?', '["Na2CO3","Mg(OH)Cl","NaHCO3","K2SO4·Al2(SO4)3·24H2O"]', '<u>Mg(OH)Cl is a basic salt</u>.', '{"bold":["basic salt"],"italic":[],"underline":["Mg(OH)Cl"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnhjz3qcir02trfgbwkyou6m6', 'General Mathematics', 'WAEC', null, 2020, null, 'If α and β are the roots of 2x² - 3x + 4 = 0, find the equation whose roots are α² and β².', null, '["4x² - 7x + 16 = 0","4x² - 7x - 16 = 0","4x² + 7x + 16 = 0","4x² + 7x - 16 = 0"]', 0, 'α+β = 3/2, αβ = 2; sum = 9/4 - 4 = -7/4; product = 4; equation: 4x² + 7x + 16 = 0. Key says 4x² - 7x + 16 = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If α and β are the roots of 2x² - 3x + 4 = 0, find the equation whose roots are α² and β².', '["4x² - 7x + 16 = 0","4x² - 7x - 16 = 0","4x² + 7x + 16 = 0","4x² + 7x - 16 = 0"]', 'Equation = <u>4x² - 7x + 16 = 0</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnhuc39abcsqmkq7c4s6wzad8', 'Biology', 'JAMB', null, 1989, null, 'Double fertilization is a unique feature of', null, '["angiosperms","bryophytes","pteridophytes","algae"]', 0, 'Double fertilization is unique to angiosperms.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Double fertilization is a unique feature of', '["<u>angiosperms</u>","bryophytes","pteridophytes","algae"]', '<u>Double fertilization is unique to angiosperms</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cni9bz6wqzy6xc98r4mkzml5r', 'Government', 'JAMB', null, 2020, null, 'The most important challenge facing the Fourth Republic is', null, '["the need to develop Nigeria culturally","the successful conduct of the 2003 elections","how to develop Nigeria''s social institutions","how to deal with the military"]', 1, 'The successful conduct of the 2003 elections was the biggest challenge.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The most important challenge facing the Fourth Republic is', '["the need to develop Nigeria culturally","<u>the successful conduct of the 2003 elections</u>","how to develop Nigeria''s social institutions","how to deal with the military"]', '<u>Successful conduct of the 2003 elections</u>.', '{"bold":[],"italic":[],"underline":["the successful conduct of the 2003 elections"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnihfvk4l81agkxg3m9gyapb6', 'Chemistry', 'JAMB', null, 2019, null, 'What mass of a divalent metal M (atomic mass 40) would react with excess hydrochloric acid to liberate 224cm3 of dry hydrogen gas measured at stp.? (G.M.V.=22.4dm3)', null, '["8g","0.04g","10g"]', 2, 'Moles H2 = 0.224/22.4 = 0.01 mol. Moles M = 0.01 mol (1:1 with H2 for divalent metal). Mass = 0.01 × 40 = 0.4 g.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What mass of a divalent metal M (atomic mass 40) would react with excess hydrochloric acid to liberate 224cm3 of dry hydrogen gas measured at stp.? (G.M.V.=22.4dm3)', '["8g","0.04g","<u>0.4g</u>"]', 'Moles H2 = 0.01 mol. Moles M = 0.01 mol. Mass = 0.01 × 40 = <u>0.4 g</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnimxb8jl7ad8ds9nj3zio1w1', 'Biology', 'JAMB', null, 2001, null, 'A seedling grown in the dark is likely to be', null, '["etiolated","dormant","sturdy","stunted"]', 0, 'Dark-grown seedlings are etiolated.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A seedling grown in the dark is likely to be', '["etiolated","dormant","sturdy","stunted"]', '<u>Etiolated</u>.', '{"bold":[],"italic":[],"underline":["etiolated"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cniqnvmgvvpv940120pit937w', 'General Mathematics', 'JAMB', null, 2020, null, 'Which is true?', null, '["36 ≡ 1 (mod 7)","36 ≡ 2 (mod 7)","36 ≡ 3 (mod 7)","36 ≡ 4 (mod 7)"]', 0, '36 mod 7 = 1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which is true?', '["36 ≡ 1 (mod 7)","36 ≡ 2 (mod 7)","36 ≡ 3 (mod 7)","36 ≡ 4 (mod 7)"]', '36 ≡ <u>1</u> mod 7.', '{"bold":[],"italic":[],"underline":["36 ≡ 1 (mod 7)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cniup4bdjbdyje8qr4hi61seg', 'English Language', 'JAMB', null, 2020, null, 'What saved her was that she _____ to the side of the boat.', null, '["had clinged","dung","clung","clang","clinged"]', 2, 'Past tense of "cling" is "clung".', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What saved her was that she _____ to the side of the boat.', '["had clinged","dung","clung","clang","clinged"]', '<u>Clung</u> = past of "cling".', '{"bold":[],"italic":[],"underline":["clung"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cniwk6o0zbkx4e0gqmmyi8qvc', 'Chemistry', 'JAMB', null, 1985, null, 'How much of magnesium is required to react with 250cm³ of 0.5M HCl? [Mg=24]', null, '["0.3g","1.5g","2.4g","3.0g"]', 1, 'Moles HCl = 0.125; moles Mg = 0.0625; mass = 0.0625 × 24 = 1.5g.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'How much of magnesium is required to react with 250cm³ of 0.5M HCl? [Mg=24]', '["0.3g","1.5g","2.4g","3.0g"]', 'Moles Mg = 0.0625; mass = <u>1.5g</u>.', '{"bold":[],"italic":[],"underline":["1.5g"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cniws372zzelnueqwon2y0nle', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve (x² - 4)/(x - 2) > 0.', null, '["(-2, 2) ∪ (2, ∞)","(-2, ∞) excluding 2","x > -2, x ≠ 2","x > 2"]', 1, '(x² - 4)/(x - 2) = (x + 2)(x - 2)/(x - 2) = x + 2 (x ≠ 2); > 0 → x > -2, x ≠ 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve (x² - 4)/(x - 2) > 0.', '["(-2, 2) ∪ (2, ∞)","(-2, ∞) excluding 2","x > -2, x ≠ 2","x > 2"]', 'Solution: <u>x > -2, x ≠ 2</u>.', '{"bold":[],"italic":[],"underline":["(-2, ∞) excluding 2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnjd5of59ydbi0m3z348t70k7', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The theme of surah al-Inshirah is that', null, '["Allah''s favour is on those who are patient","the Prophet''s name stands high among others","the Prophet''s virtues are always recognized","Allah always provides a solution to any problem."]', 3, 'Allah provides a solution to every problem.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The theme of surah al-Inshirah is that', '["Allah''s favour is on those who are patient","the Prophet''s name stands high among others","the Prophet''s virtues are always recognized","<u>Allah always provides a solution to any problem.</u>"]', '<u>Allah always provides a solution to any problem</u> (Q. 94:5-6).', '{"bold":[],"italic":[],"underline":["Allah always provides a solution to any problem."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnjdgwf2tef3syy53op7zt704', 'Chemistry', 'JAMB', null, 1993, null, 'The phenomenon whereby sodium trioxocarbonate(IV) decahydrate loses some of its water of crystallization on exposure to the atmosphere is known as', null, '["deliquescence","hygroscopy","effervescence","efflorescence"]', 3, 'Efflorescence is loss of water of crystallization to air.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The phenomenon whereby sodium trioxocarbonate(IV) decahydrate loses some of its water of crystallization on exposure to the atmosphere is known as', '["deliquescence","hygroscopy","effervescence","efflorescence"]', '<u>Efflorescence</u> is loss of water of crystallization.', '{"bold":[],"italic":[],"underline":["efflorescence"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnjhg1elg18zpw93txy8op68e', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Saul visited the witch of Endor when he was besieged by the', null, '["Philistines","Amorites","Amalekites","Moabites"]', 0, 'Saul was besieged by the Philistines.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Saul visited the witch of Endor when he was besieged by the', '["<u>Philistines</u>","Amorites","Amalekites","Moabites"]', '<u>Philistines</u> (1 Samuel 28:5-7).', '{"bold":[],"italic":[],"underline":["Philistines"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnjkw8z8akphnru7mb1fz0otx', 'Chemistry', 'JAMB', null, 1983, null, 'Which of the following pairs of gases will <b>NOT react further</b> with oxygen at a temperature between 30°C and 400°C?', null, '["SO2 and NH3","CO2 and H2","NO2 and SO3","SO3 and NO","CO and HF"]', 3, 'SO3 and NO are already fully oxidized and will not react further with oxygen.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following pairs of gases will <b>NOT react further</b> with oxygen at a temperature between 30°C and 400°C?', '["SO2 and NH3","CO2 and H2","NO2 and SO3","SO3 and NO","CO and HF"]', '<u>SO3 and NO</u> are already fully oxidized.', '{"bold":["NOT react further"],"italic":[],"underline":["SO3 and NO"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnjqxaapfz1sulaimqwh28e52', 'English Language', 'JAMB', null, 2020, null, 'The man _____ the police arrested was later released on bail.', null, '["who","whose","whom","which"]', 2, 'Whom is object of "arrested".', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The man _____ the police arrested was later released on bail.', '["who","whose","whom","which"]', 'Whom is object → <u>whom</u>.', '{"bold":[],"italic":[],"underline":["whom"],"fillBlanks":[]}');
