insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnk26v0cqu5jgkzq0cc8gg3ke', 'Chemistry', 'JAMB', null, 1996, null, 'The electronic configuration of an element is 1s²2s²2p⁶3s²3p³. How many unpaired electrons are there in the element?', null, '["5","4","3","2"]', 2, '3p³ has 3 unpaired electrons (Hund''s rule).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The electronic configuration of an element is 1s²2s²2p⁶3s²3p³. How many unpaired electrons are there in the element?', '["5","4","3","2"]', '<u>3 unpaired electrons</u> in 3p³.', '{"bold":[],"italic":[],"underline":["3"],"fillBlanks":[]}');
