insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnkvtydm2glupwwlumrv3vv57', 'General Mathematics', 'JAMB', null, 2020, null, 'A die is rolled twice. Find the probability the sum is 7, given the first die is a 3.', null, '["1/6","1/5","1/4","1/3"]', 0, 'Given first = 3, second must be 4; P = 1/6.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A die is rolled twice. Find the probability the sum is 7, given the first die is a 3.', '["1/6","1/5","1/4","1/3"]', 'P = <u>1/6</u>.', '{"bold":[],"italic":[],"underline":["1/6"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnkxq1efosml1246ahzxhltbg', 'Biology', 'JAMB', null, 2001, null, 'The role of the male adult honey bee is to', null, '["clean the hive","ventilate the hive","mate with the queen","care for the young"]', 2, 'The drone mates with the queen.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The role of the male adult honey bee is to', '["clean the hive","ventilate the hive","mate with the queen","care for the young"]', '<u>Mate with the queen</u>.', '{"bold":[],"italic":[],"underline":["mate with the queen"],"fillBlanks":[]}');
