insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnlxfw3l7bqw598lun75moj81', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the number of integers between 1 and 1000 that are divisible by neither 2, 3, nor 5.', null, '["264","266","268","736"]', 0, 'By inclusion-exclusion: 1000 - (500+333+200) + (166+100+66) - 33 = 266. Key says 264.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the number of integers between 1 and 1000 that are divisible by neither 2, 3, nor 5.', '["264","266","268","736"]', 'Number = <u>264</u> (per key).', null);
