insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnlysyk1a0rto0wv49vpp2wvo', 'Islamic Religious Studies', 'JAMB', null, 2003, null, 'The Prophet (S.A.W) says: ''If one of you takes rope (goes to the bush) and comes back with a bunch of firewood, sells it ... is better than begging for alms ...'' The Hadith above focuses on', null, '["Dedication to service","dignity of labour","decent living","Muslim responsibility"]', 1, 'The Hadith emphasizes the dignity of labour over begging.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Prophet (S.A.W) says: ''If one of you takes rope (goes to the bush) and comes back with a bunch of firewood, sells it ... is better than begging for alms ...'' The Hadith above focuses on', '["Dedication to service","<u>dignity of labour</u>","decent living","Muslim responsibility"]', 'The Hadith emphasizes the <u>dignity of labour</u> over begging.', '{"bold":[],"italic":[],"underline":["dignity of labour"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnm1imtocsg1rui3as1gev8uy', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Muhammad rasulullah in the kalimatu sh-shahadah means that Muhammad (S.A.W.) is to Allah a', null, '["prophet","messenger","servant","slave"]', 1, 'Rasulullah means messenger of Allah.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Muhammad rasulullah in the kalimatu sh-shahadah means that Muhammad (S.A.W.) is to Allah a', '["prophet","<u>messenger</u>","servant","slave"]', '<u>Messenger</u>.', '{"bold":[],"italic":[],"underline":["messenger"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnm1wduvmniwoh5atqd1dhmjo', 'Christian Religious Studies', 'JAMB', null, 2020, null, '''Have this mind among yourselves, which is yours in Christ Jesus...'' This mind in Paul''s statement above means a mind of', null, '["faith","humility","prayer","holiness"]', 1, 'The mind of Christ means humility.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '''Have this mind among yourselves, which is yours in Christ Jesus...'' This mind in Paul''s statement above means a mind of', '["faith","<u>humility</u>","prayer","holiness"]', '<u>Humility</u> (Philippians 2:5-8).', '{"bold":[],"italic":[],"underline":["humility"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnm4e5wqzarypnnkcf8dxddgq', 'General Mathematics', 'WAEC', null, 2020, null, 'A = [[0, 1], [1, 0]], find the eigenvalues.', null, '["1, -1","1, 1","-1, -1","0, 1"]', 0, 'λ² - 1 = 0 → λ = ±1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A = [[0, 1], [1, 0]], find the eigenvalues.', '["1, -1","1, 1","-1, -1","0, 1"]', 'Eigenvalues = <u>1, -1</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnm4jq4bxzg335e8ypxrk03et', 'Islamic Religious Studies', 'JAMB', null, 2011, null, 'One of the moral lessons in Q.17:23 apart from obedience to parents is', null, '["resilience","repentance","perseverance","honesty"]', 2, 'Q.17:23 teaches perseverance along with obedience to parents.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One of the moral lessons in Q.17:23 apart from obedience to parents is', '["resilience","repentance","<u>perseverance</u>","honesty"]', 'Q.17:23 teaches <u>perseverance</u> along with obedience to parents.', '{"bold":[],"italic":[],"underline":["perseverance"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnm5ykc41eahm64go6gypzd1d', 'General Mathematics', 'JAMB', null, 2020, null, 'If ∫₀^a dx/√(a² - x²) = π/3, find a.', null, '["√3/2","1","2/√3","2"]', 1, '∫ = sin⁻¹(x/a); evaluated = π/2. π/2 = π/3 impossible. Key says 1.', false, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'If ∫₀^a dx/√(a² - x²) = π/3, find a.', '["√3/2","1","2/√3","2"]', 'a = <u>1</u> (per key).', '{"bold":[],"italic":[],"underline":["1"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnm9hm2mdufm1i779xjjcr2s2', 'Chemistry', 'JAMB', null, 1995, null, 'Changes in the physical states of chemical substances T are shown in the scheme:<br>Liquid T → Solid T (Z)<br>Liquid T → Gaseous T (Y)<br>Solid T → Gaseous T (X)<br>The letters X, Y and Z respectively represent', null, '["sublimation, condensation and freezing","sublimation, vaporization and solidification","freezing, condensation and sublimation","evaporation, liquefaction and sublimation"]', 1, 'X = sublimation; Y = vaporization; Z = solidification.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Changes in the physical states of chemical substances T are shown in the scheme:<br>Liquid T → Solid T (Z)<br>Liquid T → Gaseous T (Y)<br>Solid T → Gaseous T (X)<br>The letters X, Y and Z respectively represent', '["sublimation, condensation and freezing","sublimation, vaporization and solidification","freezing, condensation and sublimation","evaporation, liquefaction and sublimation"]', '<u>X = sublimation; Y = vaporization; Z = solidification</u>.', '{"bold":[],"italic":[],"underline":["sublimation, vaporization and solidification"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnmdyngw9t7fv3ir4loyyu1hg', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'David made the decision to pursue the Amalekites through', null, '["the ephod","divination","the casting of lots","Abiathar''s support"]', 0, 'David inquired through the ephod.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'David made the decision to pursue the Amalekites through', '["<u>the ephod</u>","divination","the casting of lots","Abiathar''s support"]', '<u>The ephod</u> (1 Samuel 30:7-8).', '{"bold":[],"italic":[],"underline":["the ephod"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnmgltgxz5ewnd0ynnby4p3id', 'Chemistry', 'JAMB', null, 1988, null, '1.34g of hydrated sodium tetraoxosulphate(VI) was heated to give an anhydrous salt weighing 0.71g. The formula of the hydrated salt is [Na=23, S=32, O=16, H=1]', null, '["Na2SO4·7H2O","Na2SO4·3H2O","Na2SO4·2H2O","Na2SO4·H2O"]', 1, 'Water lost = 0.63g; moles = 0.035; moles Na2SO4 = 0.005; ratio = 7. Key says 3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '1.34g of hydrated sodium tetraoxosulphate(VI) was heated to give an anhydrous salt weighing 0.71g. The formula of the hydrated salt is [Na=23, S=32, O=16, H=1]', '["Na2SO4·7H2O","Na2SO4·3H2O","Na2SO4·2H2O","Na2SO4·H2O"]', 'Water lost = 0.63g; ratio = <u>7</u> (key says 3).', '{"bold":[],"italic":[],"underline":["Na2SO4·3H2O"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnmosjjjnkp4be5r2xe9cihpe', 'English Language', 'JAMB', null, 2020, null, 'I pointed to an object in the sky, but they _____ it.', null, '["can''t see","weren''t seeing","aren''t seeing","couldn''t see"]', 3, 'Couldn''t see = past inability.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'I pointed to an object in the sky, but they _____ it.', '["can''t see","weren''t seeing","aren''t seeing","couldn''t see"]', '<u>Couldn''t see</u> = past inability.', '{"bold":[],"italic":[],"underline":["couldn''t see"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnmwlrsupcjdo9c1wsbf87qnf', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The pre-colonial West African rulers employed the services of Muslim scholars mostly as', null, '["teachers","secretaries","ambassadors","Imams."]', 1, 'They were mostly employed as secretaries.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The pre-colonial West African rulers employed the services of Muslim scholars mostly as', '["teachers","<u>secretaries</u>","ambassadors","Imams."]', '<u>Secretaries</u>.', '{"bold":[],"italic":[],"underline":["secretaries"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnmz11378o4fu0mmhlxk8619v', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the standard deviation of the first n natural numbers.', null, '["√((n² - 1)/12)","√((n² + 1)/12)","√(n(n + 1)/6)","√(n(n - 1)/6)"]', 0, 'Variance = (n² - 1)/12; SD = √((n²-1)/12).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the standard deviation of the first n natural numbers.', '["√((n² - 1)/12)","√((n² + 1)/12)","√(n(n + 1)/6)","√(n(n - 1)/6)"]', 'SD = <u>√((n² - 1)/12)</u>.', '{"bold":[],"italic":[],"underline":["√((n² - 1)/12)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnn24aag468y3ldvrxf7ybmff', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'David''s inaction to Amnon''s incest with Tamar showed his', null, '["ability to forgive as a leader","wisdom and strength of character","lack of control over his children","excessive love for Amnon."]', 2, 'It showed his lack of control over his children.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'David''s inaction to Amnon''s incest with Tamar showed his', '["ability to forgive as a leader","wisdom and strength of character","<u>lack of control over his children</u>","excessive love for Amnon."]', '<u>Lack of control over his children</u>.', '{"bold":[],"italic":[],"underline":["lack of control over his children"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnn3prwikubmm5ojynn3nafyg', 'Islamic Religious Studies', 'JAMB', null, 2008, null, 'Hadith 18 of an-Nawawi enjoins believers to', null, '["Be firm and brave","Be strong-minded and clean","Have piety and work righteously","Acquire knowledge and be polite"]', 2, 'Hadith 18 enjoins piety and righteous deeds.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Hadith 18 of an-Nawawi enjoins believers to', '["Be firm and brave","Be strong-minded and clean","<u>Have piety and work righteously</u>","Acquire knowledge and be polite"]', 'Hadith 18 enjoins <u>piety and righteous deeds</u>.', '{"bold":[],"italic":[],"underline":["Have piety and work righteously"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnnfzsrzabkklay6n367p8nfo', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Ibrahim is described in the Holy Qur''an as', null, '["yahudi","mu''min","nasara","hanif."]', 3, 'Ibrahim is described as hanif.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Ibrahim is described in the Holy Qur''an as', '["yahudi","mu''min","nasara","<u>hanif.</u>"]', '<u>Hanif</u> (Q. 3:67).', '{"bold":[],"italic":[],"underline":["hanif."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnnj18x825i7eone0wydus3x6', 'Chemistry', 'JAMB', null, 1999, null, 'A gaseous metallic chloride MClx consists of 20.22% of M by mass. The formula of the chloride is', null, '["MCl","MCl2","MCl3","M2Cl6 [M=27, Cl=35.5]"]', 2, 'Mass Cl = 79.78%; moles M:Cl = 20.22/27 : 79.78/35.5 = 0.75:2.25 = 1:3 → MCl3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A gaseous metallic chloride MClx consists of 20.22% of M by mass. The formula of the chloride is', '["MCl","MCl2","MCl3","M2Cl6"]', '<u>MCl3</u>.', '{"bold":[],"italic":[],"underline":["MCl3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnnmsncfh6bq8ayqlg515p61p', 'General Mathematics', 'WAEC', null, 2020, null, 'If log_a b = 3 and log_b a = 2 find log_a √b.', null, '["0.5","0.75","1","1.5"]', 1, 'log_a √b = (1/2) log_a b = 1.5. But log_a b = 3 and log_b a = 2 are inconsistent (product should be 1). Key says 0.75.', false, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'If log_a b = 3 and log_b a = 2 find log_a √b.', '["0.5","0.75","1","1.5"]', '(1/2)(3) = <u>1.5</u> (key says 0.75).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnns2a9k9qv9yswkvngz23vrh', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'In the hadith that ends with ''..piety is based right here ...'', the Prophet (S.A.W.) meant the', null, '["heart","tongue","eye","hand"]', 0, 'The Prophet meant the heart.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the hadith that ends with ''..piety is based right here ...'', the Prophet (S.A.W.) meant the', '["<u>heart</u>","tongue","eye","hand"]', '<u>Heart</u>.', '{"bold":[],"italic":[],"underline":["heart"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnnv7f8c1zlkf70hvkx8fbzxl', 'General Mathematics', 'JAMB', null, 2020, null, 'On R, a*b = a + b - 2. Find the inverse of 4.', null, '["0","-4","4","2"]', 0, 'e = 2; 4*x = 2 → 4+x-2 = 2 → x = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'On R, a*b = a + b - 2. Find the inverse of 4.', '["0","-4","4","2"]', 'Inverse = <u>0</u>.', '{"bold":[],"italic":[],"underline":["0"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnnzmonf08xk2mtvkzl55pinv', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'When the glory of the LORD appeared to Moses and Aaron in the wilderness of Zin, the Lord said they should', null, '["tell the rock before their eyes to yield its water","strike the rock with rod to bring out water for them","fetch water for the people and their cattle","tell the people to go round the rock."]', 0, 'God said they should tell the rock to yield its water.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When the glory of the LORD appeared to Moses and Aaron in the wilderness of Zin, the Lord said they should', '["<u>tell the rock before their eyes to yield its water</u>","strike the rock with rod to bring out water for them","fetch water for the people and their cattle","tell the people to go round the rock."]', '<u>Tell the rock before their eyes to yield its water</u> (Numbers 20:6-8).', '{"bold":[],"italic":[],"underline":["tell the rock before their eyes to yield its water"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cno0g8ktrfisl0rkbsulop2hz', 'General Mathematics', 'WAEC', null, 2020, null, 'Two events A and B are such that P(A) = 0.4, P(B) = 0.3 and P(A ∪ B) = 0.6. Find P(A|B).', null, '["1/2","1/3","1/4","1/5"]', 1, 'P(A ∩ B) = 0.4+0.3-0.6 = 0.1; P(A|B) = 0.1/0.3 = 1/3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Two events A and B are such that P(A) = 0.4, P(B) = 0.3 and P(A ∪ B) = 0.6. Find P(A|B).', '["1/2","1/3","1/4","1/5"]', 'P(A|B) = <u>1/3</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cno2kv5fpr0n0uxh52ns1ye3p', 'Government', 'JAMB', null, 2020, null, 'The Eastern and Western regions of Nigeria achieved the status of self-government in', null, '["1959","1957","1950","1955"]', 1, 'Eastern and Western regions attained self-government in 1957.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Eastern and Western regions of Nigeria achieved the status of self-government in', '["1959","<u>1957</u>","1950","1955"]', '<u>1957</u>.', '{"bold":[],"italic":[],"underline":["1957"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cno51hc6e5ctnidvcmkww7km1', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The verse Q. 5:1 requires believers to', null, '["Pray regularly","fulfil all obligations","respect authority","encourage honesty."]', 1, 'Q. 5:1 requires believers to fulfil all obligations.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The verse Q. 5:1 requires believers to', '["Pray regularly","<u>fulfil all obligations</u>","respect authority","encourage honesty."]', '<u>Fulfil all obligations</u> (Q. 5:1).', '{"bold":[],"italic":[],"underline":["fulfil all obligations"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnoakhdu5fdxo8nhat4w0rqym', 'Biology', 'JAMB', null, 2001, null, 'Most monocots are easily recognized by their', null, '["short leaves with petioles","long and sword-like leaves","long and palm-like leaves","short leaves with many veinlets"]', 1, 'long and sword-like leaves is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Most monocots are easily recognized by their', '["short leaves with petioles","<u>long and sword-like leaves</u>","long and palm-like leaves","short leaves with many veinlets"]', 'long and sword-like leaves is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnod7clq379d0jd9p2se8nju1', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'It is finished. The statement above by Jesus on the cross implies that', null, '["His association with the Jews is finished","His association with His disciples is finished","His work of redemption is finished","the work of the enemy is finished."]', 2, 'It means His work of redemption is finished.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'It is finished. The statement above by Jesus on the cross implies that', '["His association with the Jews is finished","His association with His disciples is finished","<u>His work of redemption is finished</u>","the work of the enemy is finished."]', '<u>His work of redemption is finished</u> (John 19:30).', '{"bold":[],"italic":[],"underline":["His work of redemption is finished"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnoid6gwjhvmxgmxkytr9wtpo', 'English Language', 'JAMB', null, 2020, null, 'The dead body of the armed robber has _____ in the street for three days.', null, '["laid","lain","layed","lied","lay"]', 1, 'Past participle of "lie" (recline) is "lain".', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The dead body of the armed robber has _____ in the street for three days.', '["laid","lain","layed","lied","lay"]', 'Past participle: <u>lain</u>.', '{"bold":[],"italic":[],"underline":["lain"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnotcmg5tnfu0kskr2m0pu399', 'General Mathematics', 'JAMB', null, 2020, null, 'If log₁₀2 = a, log₁₀3 = b, express log₆120 in terms of a, b.', null, '["(1+2a+b)/(a+b)","(1+2a-b)/(a+b)","(1+2a+b)/(b-a)","(1+2a-b)/(b-a)"]', 0, '120 = 2³×3×5; log₆120 = (3a + b + log₁₀5)/(a+b) = (3a + b + 1-a)/(a+b) = (1+2a+b)/(a+b).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If log₁₀2 = a, log₁₀3 = b, express log₆120 in terms of a, b.', '["(1+2a+b)/(a+b)","(1+2a-b)/(a+b)","(1+2a+b)/(b-a)","(1+2a-b)/(b-a)"]', null, '{"bold":[],"italic":[],"underline":["(1+2a+b)/(a+b)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnoyjd0m24wcg49n6x235hgkl', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve for x: 4ˣ + 6ˣ = 9ˣ.', null, '["(log(√5 - 1) - log2)/(log2 - log3)","(log(√5 + 1) - log2)/(log3 - log2)","(log(√5 - 1) - log2)/(log3 - log2)","(log(√5 + 1) - log2)/(log2 - log3)"]', 1, 'Divide by 4ˣ: 1 + (3/2)ˣ = (3/2)²ˣ; let y = (3/2)ˣ; y² - y - 1 = 0 → y = (1+√5)/2; x = log((1+√5)/2)/log(3/2).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve for x: 4ˣ + 6ˣ = 9ˣ.', '["(log(√5 - 1) - log2)/(log2 - log3)","(log(√5 + 1) - log2)/(log3 - log2)","(log(√5 - 1) - log2)/(log3 - log2)","(log(√5 + 1) - log2)/(log2 - log3)"]', 'x = <u>(log(√5 + 1) - log2)/(log3 - log2)</u>.', '{"bold":[],"italic":[],"underline":["(log(√5 + 1) - log2)/(log3 - log2)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnp4k1qupqql596n8opemjqoc', 'Biology', 'JAMB', null, 1986, null, 'The equation that can be used to summarize the process of anaerobic breakdown of sugar is', null, '["C6H12O6 + 2C2H5OH + 2CO2","6CO2 + 6H2O → C6H12O6 + 6O2","C6H12O6 + 6O2 → CO2 + 6H2O + energy","C6H12O6 → C2H5OH + 2CO2 + energy"]', 3, 'Anaerobic breakdown: C6H12O6 → C2H5OH + 2CO2 + energy.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The equation that can be used to summarize the process of <b>anaerobic breakdown</b> of sugar is', '["C6H12O6 + 2C2H5OH + 2CO2","6CO2 + 6H2O → C6H12O6 + 6O2","C6H12O6 + 6O2 → CO2 + 6H2O + energy","<u>C6H12O6 → C2H5OH + 2CO2 + energy</u>"]', 'Anaerobic breakdown: <u>C6H12O6 → C2H5OH + 2CO2 + energy</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnp5si7fci4ijbgtr2lt2qt0e', 'Biology', 'JAMB', null, 2001, null, 'Most monocots are easily recognized by their', null, '["short leaves with petioles","long and sword-like leaves","long and palm-like leaves","short leaves with many veins"]', 1, 'Monocots have long, sword-like leaves.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Most monocots are easily recognized by their', '["short leaves with petioles","long and sword-like leaves","long and palm-like leaves","short leaves with many veins"]', '<u>Long sword-like leaves</u>.', '{"bold":[],"italic":[],"underline":["long and sword-like leaves"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnp819iu4cxzx0d363xbhq743', 'General Mathematics', 'JAMB', null, 2020, null, 'If x² + ax + b = 0 and x² + bx + a = 0 have a common root, find a + b.', null, '["0","1","-1","2"]', 0, 'Subtracting: (a-b)(x-1) = 0 → x = 1; 1 + a + b = 0 → a + b = -1. If a = b, infinite. Key says 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If x² + ax + b = 0 and x² + bx + a = 0 have a common root, find a + b.', '["0","1","-1","2"]', 'a + b = <u>0</u> (per key).', '{"bold":[],"italic":[],"underline":["0"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnpah555wlxilgd5p62nqgy91', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The Hadith teaches that a Muslim', null, '["must obey the commands of the Prophet (S.A.W)","must confine himself to the established teachings of Islam","can contribute in developing and increasing the teaching of Islam","should always command what is good."]', 1, 'The Hadith teaches that a Muslim should confine himself to established teachings.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Hadith teaches that a Muslim', '["must obey the commands of the Prophet (S.A.W)","<u>must confine himself to the established teachings of Islam</u>","can contribute in developing and increasing the teaching of Islam","should always command what is good."]', '<u>Must confine himself to the established teachings of Islam</u>.', '{"bold":[],"italic":[],"underline":["must confine himself to the established teachings of Islam"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnparp9wxujchcsmx6iz3zokr', 'General Mathematics', 'JAMB', null, 2020, null, 'If log₁₀tan 1 + log₁₀tan 2 + ... + log₁₀tan 89 = k, find k.', null, '["0","1","44","89"]', 0, 'tan θ · tan(90-θ) = 1; sum = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If log₁₀tan 1 + log₁₀tan 2 + ... + log₁₀tan 89 = k, find k.', '["0","1","44","89"]', 'k = <u>0</u>.', '{"bold":[],"italic":[],"underline":["0"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnpce5zcvntw5eg9wq4t4vtuc', 'Islamic Religious Studies', 'JAMB', null, 2003, null, 'The institution of learning referred to as <b>ummu-d-duniyah</b> is', null, '["al-Azhar university","Sankore University","University of Madinah","University of Khartoum"]', 0, 'Al-Azhar University is referred to as Umm al-Dunya (Mother of the World).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The institution of learning referred to as <b>ummu-d-duniyah</b> is', '["<u>al-Azhar university</u>","Sankore University","University of Madinah","University of Khartoum"]', '<u>Al-Azhar University</u> is referred to as Umm al-Dunya.', '{"bold":["ummu-d-duniyah"],"italic":[],"underline":["al-Azhar university"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnphavnn90r3h7e80ds0abj0c', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Hiram, King of Tyre, was friendly with King Solomon because he', null, '["loved the wisdom of Solomon","loved David, Solomon''s father","was afraid of war","wanted to assist Solomon."]', 1, 'Hiram was friendly with Solomon because he loved David.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Hiram, King of Tyre, was friendly with King Solomon because he', '["loved the wisdom of Solomon","<u>loved David, Solomon''s father</u>","was afraid of war","wanted to assist Solomon."]', '<u>Loved David, Solomon''s father</u> (1 Kings 5:1).', '{"bold":[],"italic":[],"underline":["loved David, Solomon''s father"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnpife2rcoae032o2bvkjr2f8', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'In His sermon on the Mount, Jesus taught Christians to', null, '["turn the other cheek to their enemies","be merciful to their enemies","love and pray for their enemies","do good to their enemies"]', 2, 'Jesus taught Christians to love and pray for their enemies.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In His sermon on the Mount, Jesus taught Christians to', '["turn the other cheek to their enemies","be merciful to their enemies","<u>love and pray for their enemies</u>","do good to their enemies"]', '<u>Love and pray for their enemies</u> (Matthew 5:44).', '{"bold":[],"italic":[],"underline":["love and pray for their enemies"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnpoktoola0eky8hsdoamewg5', 'General Mathematics', 'JAMB', null, 2020, null, 'If a, b, c, d are in GP, then (a - d)² = ?', null, '["(b - c)² + (c - a)² + (d - b)²","(b - c)² + (c - a)² + (d - a)²","(b + c)² + (a - d)²","(a + b)² - (c + d)²"]', 0, 'Identity for GP: (a-d)² = (b-c)² + (c-a)² + (d-b)².', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If a, b, c, d are in GP, then (a - d)² = ?', '["(b - c)² + (c - a)² + (d - b)²","(b - c)² + (c - a)² + (d - a)²","(b + c)² + (a - d)²","(a + b)² - (c + d)²"]', 'Identity holds.', '{"bold":[],"italic":[],"underline":["(b - c)² + (c - a)² + (d - b)²"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnppa5w2gj06600m52de56i09', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'According to Corinthians, variety of gifts are inspired by', null, '["fervent prayers","angels of God","constant fasting","the same Spirit."]', 3, 'Variety of gifts are inspired by the same Spirit.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to Corinthians, variety of gifts are inspired by', '["fervent prayers","angels of God","constant fasting","<u>the same Spirit.</u>"]', '<u>The same Spirit</u> (1 Corinthians 12:4).', '{"bold":[],"italic":[],"underline":["the same Spirit."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnq349m0fork3yjjkwtooymjb', 'Christian Religious Studies', 'JAMB', null, 2020, null, '...Before I formed you in the womb, I knew you, and before you were born I consecrated you; I appointed you a prophet to the nations. The statement above was made by God during the', null, '["call of Prophet Ezekiel","dry-well experience of Prophet Jeremiah","consecration of prophet Isaiah","call of Prophet Jeremiah"]', 3, 'This was during the call of Prophet Jeremiah.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '...Before I formed you in the womb, I knew you, and before you were born I consecrated you; I appointed you a prophet to the nations. The statement above was made by God during the', '["call of Prophet Ezekiel","dry-well experience of Prophet Jeremiah","consecration of prophet Isaiah","<u>call of Prophet Jeremiah</u>"]', '<u>Call of Prophet Jeremiah</u> (Jeremiah 1:5).', '{"bold":[],"italic":[],"underline":["call of Prophet Jeremiah"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnq6ht05gr8bfdj7th2ppvlxk', 'English Language', 'JAMB', null, 2020, null, 'The keepers themselves are sometimes _____ by the bees.', null, '["stinged","stang","stung","sting"]', 2, 'Past participle of "sting" is "stung".', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The keepers themselves are sometimes _____ by the bees.', '["stinged","stang","stung","sting"]', 'Past participle: <u>stung</u>.', '{"bold":[],"italic":[],"underline":["stung"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnqcks3448v7llvlxgvpshzrl', 'General Mathematics', 'JAMB', null, 2020, null, 'What is the minimum value of 2x² - 4x + 7', null, '["3","4","5","6"]', 1, 'Minimum at x = 1: 2-4+7 = 5. Key says 4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is the minimum value of 2x² - 4x + 7', '["3","4","5","6"]', 'Minimum = <u>5</u> (key says 4).', '{"bold":[],"italic":[],"underline":["4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnqh5lv73s8bav3ktwzts6fh5', 'Government', 'JAMB', null, 2020, null, 'The two military coups that toppled civilian regimes in Nigeria were those of', null, '["July 1966 and August 1985","January 1966 and December 1983","February 1976 and December 1983","January 1966 and July 1975."]', 1, 'January 1966 and December 1983 coups toppled civilian regimes.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The two military coups that toppled civilian regimes in Nigeria were those of', '["July 1966 and August 1985","<u>January 1966 and December 1983</u>","February 1976 and December 1983","January 1966 and July 1975."]', '<u>January 1966 and December 1983</u>.', '{"bold":[],"italic":[],"underline":["January 1966 and December 1983"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnqlkl8jly5v76iy995rqdfmu', 'Chemistry', 'JAMB', null, 1984, null, 'Which of the following roles does <b>sodium chloride</b> play in soap preparation? It', null, '["reacts with glycerol","purifies the soap","accelerates the decomposition of the fat and oil","separates the soap from the glycerol","converts the fatty acid to its sodium salt"]', 3, 'NaCl (brine) salting-out separates soap from glycerol.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following roles does <b>sodium chloride</b> play in soap preparation? It', '["reacts with glycerol","purifies the soap","accelerates the decomposition of the fat and oil","separates the soap from the glycerol","converts the fatty acid to its sodium salt"]', '<u>NaCl separates soap from glycerol</u> (salting-out).', '{"bold":[],"italic":[],"underline":["separates the soap from the glycerol"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnqmhggmvjr6nf3klzo08ghzz', 'Chemistry', 'JAMB', null, 1985, null, 'The reaction Mg + H2O → MgO + H2 takes place only in the presence of', null, '["excess Mg ribbon","excess cold water","very hot water","steam"]', 3, 'Mg reacts with steam, not cold water.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The reaction Mg + H2O → MgO + H2 takes place only in the presence of', '["excess Mg ribbon","excess cold water","very hot water","steam"]', '<u>Mg reacts with steam</u>.', '{"bold":[],"italic":[],"underline":["steam"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnqo6mxm8feyhkhnllmveimmm', 'General Mathematics', 'WAEC', null, 2020, null, 'If (a, 2a) lies on 3x - 2y = 5, find a.', null, '["1","-5","3","4"]', 1, '3a - 4a = 5, so a = -5.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'If (a, 2a) lies on 3x - 2y = 5, find a.', '["1","-5","3","4"]', '3a - 4a = 5, so a = -5.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnqq3cos89gttjiisdctjwy5b', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Jesus did not go with the centurion to heal his servant because he', null, '["exhibited great faith","spoke to Jesus as a man under authority","was not worthy for Jesus to come under his roof.","was a Gentile."]', 0, 'The centurion exhibited great faith.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Jesus did not go with the centurion to heal his servant because he', '["<u>exhibited great faith</u>","spoke to Jesus as a man under authority","was not worthy for Jesus to come under his roof.","was a Gentile."]', '<u>Exhibited great faith</u>.', '{"bold":[],"italic":[],"underline":["exhibited great faith"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnqrsbf91hkuruxcgad6ch6m7', 'Chemistry', 'JAMB', null, 1993, null, 'Bronze is an alloy which will react to', null, '["Silver and copper","Silver and gold","Copper and nickel","Copper and tin"]', 3, 'Bronze is an alloy of copper and tin (copper and zinc make brass).', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Bronze is an alloy which will react to', '["Silver and copper","Silver and gold","Copper and nickel","Copper and tin"]', 'Bronze is an alloy of copper and tin (copper and zinc make brass).', '{"bold":[],"italic":[],"underline":["Copper and zinc"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnqti6qmrbkeitqm65ju3l6tf', 'General Mathematics', 'JAMB', null, 2020, null, 'In a school, 60% of students offered Arts, 50% offered Sciences, and 20% offered neither. What percentage offered both Arts and Sciences?', null, '["10%","20%","30%","40%"]', 1, 'At least one = 80%; both = 60 + 50 - 80 = 30%. Key says 20%.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In a school, 60% of students offered Arts, 50% offered Sciences, and 20% offered neither. What percentage offered both Arts and Sciences?', '["10%","20%","30%","40%"]', 'Both = <u>20%</u> (per key).', '{"bold":[],"italic":[],"underline":["20%"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnqtosdlclrkx383q2unr7i09', 'Biology', 'JAMB', null, 1984, null, 'Which of the following statements is NOT true of the piliferous layer of a root? It', null, '["has a very thin cuticle","is the outermost layer of the cortex","may bear root hairs","breaks down as the root ages","is replaced by cork in old roots"]', 1, 'The piliferous layer is the outermost layer of the root, not the cortex.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following statements is <b>NOT</b> true of the piliferous layer of a root? It', '["has a very thin cuticle","<u>is the outermost layer of the cortex</u>","may bear root hairs","breaks down as the root ages","is replaced by cork in old roots"]', 'The piliferous layer is the <u>outermost layer of the root</u>, not the cortex.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnqxw25jpqaxoqeyiy16zfo8g', 'Government', 'JAMB', null, 2020, null, 'In Nigeria''s First Republic, the prime minister was both the', null, '["Head of state and party leader","Head of government and a lawmaker","Head of state and commander-in-chief of the armed force","Commander-in-chief of the armed forces and party leader"]', 1, 'The PM was both head of government and a lawmaker.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In Nigeria''s First Republic, the prime minister was both the', '["Head of state and party leader","<u>Head of government and a lawmaker</u>","Head of state and commander-in-chief of the armed force","Commander-in-chief of the armed forces and party leader"]', '<u>Head of government and a lawmaker</u>.', '{"bold":[],"italic":[],"underline":["Head of government and a lawmaker"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnr10k2cliv9yyj8n67o9hszf', 'Biology', 'JAMB', null, 2000, null, 'The scapula and the ischium are part of the', null, '["pectoral girdle","pelvic girdle","appendicular skeleton","hind limb"]', 2, 'appendicular skeleton is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The scapula and the ischium are part of the', '["pectoral girdle","pelvic girdle","<u>appendicular skeleton</u>","hind limb"]', 'appendicular skeleton is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnr17dpthfqmr5ovv0l04ync2', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Take away all iniquity; accept that which is good.... What was the iniquity Hosea was referring to in the statement above?', null, '["Adultery","Ignorance","Idolatry","Injustice."]', 2, 'The iniquity was idolatry.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Take away all iniquity; accept that which is good.... What was the iniquity Hosea was referring to in the statement above?', '["Adultery","Ignorance","<u>Idolatry</u>","Injustice."]', '<u>Idolatry</u> (Hosea 14:1-3).', '{"bold":[],"italic":[],"underline":["Idolatry"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnr6zzn3aqf6o1t9vr1rhjao7', 'Physics', 'JAMB', null, 1983, null, 'The refractive index of a liquid is 1.5. If the velocity of light in vacuum is 3.0 × 10⁸ m s⁻¹, the velocity of light in the liquid is', null, '["1.5 × 10⁸ m s⁻¹","2.0 × 10⁸ m s⁻¹","3.0 × 10⁸ m s⁻¹","4.5 × 10⁸ m s⁻¹","9.0 × 10⁸ m s⁻¹"]', 1, 'v = c/n = 3.0 × 10⁸ / 1.5 = 2.0 × 10⁸ m s⁻¹.', true, '2026-10-11 21:26:45.728', '2026-10-11 21:26:45.728', null, null, null, 'The refractive index of a liquid is 1.5. If the velocity of light in vacuum is 3.0 × 10⁸ m s⁻¹, the velocity of light in the liquid is', '["1.5 × 10⁸ m s⁻¹","2.0 × 10⁸ m s⁻¹","3.0 × 10⁸ m s⁻¹","4.5 × 10⁸ m s⁻¹","9.0 × 10⁸ m s⁻¹"]', 'v = c/n = 3.0 × 10⁸ / 1.5 = 2.0 × 10⁸ m s⁻¹.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnra1xmr0qoio3bamfy5t94ph', 'Chemistry', 'JAMB', null, 1995, null, 'The effluent of an industrial plant used in the electrolysis of concentrated brine, with a flowing mercury cathode may contain impurities like', null, '["oxygen","hydrogen","mercury(II) chloride","hydrogen chloride"]', 2, 'Mercury cathode cells can release mercury compounds as impurities.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The effluent of an industrial plant used in the electrolysis of concentrated brine, with a flowing mercury cathode may contain impurities like', '["oxygen","hydrogen","mercury(II) chloride","hydrogen chloride"]', '<u>Mercury(II) chloride</u> can be an impurity.', '{"bold":[],"italic":[],"underline":["mercury(II) chloride"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnrmv8l4pf6e7wiititi6769a', 'Biology', 'JAMB', null, 1994, null, 'The mammalian organ which acts both as a digestive and as an endocrine organ is the', null, '["oesophagus","liver","pancreas","spleen"]', 2, 'The pancreas is both digestive and endocrine.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The mammalian organ which acts both as a digestive and as an endocrine organ is the', '["oesophagus","liver","<u>pancreas</u>","spleen"]', 'The <u>pancreas is both digestive and endocrine</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnroojj5ncgrt6vs1o63328ew', 'Biology', 'JAMB', null, 2002, null, 'An Amoeba and an unlaid chicken egg are', null, '["animal tissues","organelles","single cell","organisms"]', 2, 'Amoeba and unlaid egg are single cells.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An Amoeba and an unlaid chicken egg are', '["animal tissues","organelles","single cell","organisms"]', '<u>Single cell</u>.', '{"bold":[],"italic":[],"underline":["single cell"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnrqkny9qtufl1gydm9r0lp9m', 'Islamic Religious Studies', 'JAMB', null, 2010, null, '''Indeed the people before you were destroyed by asking a lot of unnecessary questions ...'' The quotation above is in Hadith 9 of An-Nawawi which refers to the', null, '["People of the Book","Quraysh","People of Madinah","Arabs"]', 0, 'Hadith 9 refers to the People of the Book.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '''Indeed the people before you were destroyed by asking a lot of unnecessary questions ...'' The quotation above is in Hadith 9 of An-Nawawi which refers to the', '["<u>People of the Book</u>","Quraysh","People of Madinah","Arabs"]', 'Hadith 9 refers to the <u>People of the Book</u>.', '{"bold":[],"italic":[],"underline":["People of the Book"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cns3fwcusxqanqoxlaa6nqatp', 'Chemistry', 'JAMB', null, 1989, null, 'The catalyst used in the <b>contact process</b> for the manufacture of tetraoxosulphate(VI) acid is', null, '["Manganese(IV) oxide","Manganese(II) tetraoxosulphate(IV)","Vanadium(V) oxide","Iron metal"]', 2, 'V2O5 is the catalyst in the contact process.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The catalyst used in the <b>contact process</b> for the manufacture of tetraoxosulphate(VI) acid is', '["Manganese(IV) oxide","Manganese(II) tetraoxosulphate(IV)","Vanadium(V) oxide","Iron metal"]', '<u>V2O5</u> is the catalyst in the contact process.', '{"bold":["contact process"],"italic":[],"underline":["Vanadium(V) oxide"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cns4jz0tuuciapvvzl8p8ma1n', 'General Mathematics', 'WAEC', null, 2020, null, 'If cos 2θ = 1/3, find sin θ.', null, '["±1/√3","±2/√3","±√(2/3)","±√(1/3)"]', 2, 'sin²θ = (1 - 1/3)/2 = 1/3; sin θ = ±√(1/3). Key says ±√(2/3).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If cos 2θ = 1/3, find sin θ.', '["±1/√3","±2/√3","±√(2/3)","±√(1/3)"]', 'sin θ = <u>±√(2/3)</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cns5q2n3i7mi6zkcjr2h4sgvq', 'Chemistry', 'JAMB', null, 1996, null, '1.1g of CaCl2 dissolved in 50cm³ of water caused a rise in temperature of 3.4°C. The heat of reaction, ΔH for CaCl2 in kJ per mole is [Ca=40, Cl=35.5, specific heat of water = 4.18 kJ]', null, '["-71.1","-4.18","+17.1","+111.0"]', 0, 'Heat = 50 × 4.18 × 3.4 = 710.6 J; moles = 0.0099; ΔH = -71.1 kJ/mol.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '1.1g of CaCl2 dissolved in 50cm³ of water caused a rise in temperature of 3.4°C. The heat of reaction, ΔH for CaCl2 in kJ per mole is [Ca=40, Cl=35.5, specific heat of water = 4.18 kJ]', '["-71.1","-4.18","+17.1","+111.0"]', 'ΔH = <u>-71.1 kJ/mol</u>.', '{"bold":[],"italic":[],"underline":["-71.1"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cns9uyghnpjrkxn6a6xnckefz', 'Biology', 'JAMB', null, 2002, null, 'The first four children of a couple were all girls. The probability that the fifth will also be a girl is', null, '["1/5","¼","1/3","½"]', 3, '½ is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The first four children of a couple were all girls. The probability that the fifth will also be a girl is', '["1/5","¼","1/3","<u>½</u>"]', '½ is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnsafst2k8g7sq03yb5k89tsk', 'Biology', 'JAMB', null, 2003, null, 'The cell component that is present in a prokaryotic cell is the', null, '["ribosome","mitochondrion","chloroplast","nuclear envelope"]', 0, 'Ribosomes are present in prokaryotic cells.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The cell component that is present in a prokaryotic cell is the', '["ribosome","mitochondrion","chloroplast","nuclear envelope"]', '<u>Ribosomes</u> are in prokaryotes.', '{"bold":[],"italic":[],"underline":["ribosome"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnsiyi882xx4049l0h74uvvfc', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Jeremiah described Israel as faithless and Judah as', null, '["idolatrous","false","stubborn","rebellious"]', 1, 'Jeremiah described Judah as false.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Jeremiah described Israel as faithless and Judah as', '["idolatrous","<u>false</u>","stubborn","rebellious"]', '<u>False</u> (Jeremiah 3:11).', '{"bold":[],"italic":[],"underline":["false"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnsmgpckgvntd1bt7cod3t10e', 'Chemistry', 'JAMB', null, 1986, null, 'The exhaust fumes from a garage in a place that uses petrol of high sulphur content are bound to contain', null, '["CO and SO3","CO and SO2","CO, SO2 and SO3","CO and H2S"]', 1, 'High sulphur petrol produces CO and SO2 in exhaust.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The exhaust fumes from a garage in a place that uses petrol of high sulphur content are bound to contain', '["CO and SO3","CO and SO2","CO, SO2 and SO3","CO and H2S"]', '<u>CO and SO2</u> are produced.', '{"bold":[],"italic":[],"underline":["CO and SO2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnsmo4ndex9b7kkzez276wdye', 'Chemistry', 'JAMB', null, 2019, null, 'The main chemical constituent of clay is', null, '["Silicon oxide","aluminum borosilicate","Zeolites","aluminum silicate"]', 3, 'Clay is mainly composed of aluminium silicate.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The main chemical constituent of clay is', '["Silicon oxide","aluminum borosilicate","Zeolites","<u>aluminum silicate</u>"]', 'Clay is mainly composed of <u>aluminium silicate</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnswc6hk1hbaqtts0s37neabs', 'General Mathematics', 'JAMB', null, 2020, null, 'If one root of 3x² - 7x + k = 0 is the reciprocal of the other, find k', null, '["1","2","3","4"]', 1, 'α × 1/α = 1 → k/3 = 1 → k = 3. Key says 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If one root of 3x² - 7x + k = 0 is the reciprocal of the other, find k', '["1","2","3","4"]', 'k/3 = 1 → <u>k = 3</u> (key says 2).', '{"bold":[],"italic":[],"underline":["2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnsygz36yxvjyekt6kw3fvgok', 'Chemistry', 'JAMB', null, 1990, null, 'Na2C2O4 + CaCl2 → CaC2O4 + 2NaCl. Given a solution of 1.9g of sodium oxalate in 50g of water at room temperature, calculate the minimum volume of 0.1M calcium oxalate required to produce maximum calcium oxalate using the above equation.', null, '["1.40×10² dm³","1.40×10² cm³","1.40×10⁻² dm³","1.40×10⁻² cm³"]', 2, 'Moles Na2C2O4 = 1.9/134 = 0.0142; volume = 0.0142/0.1 = 0.142 dm³. Closest is 1.40×10⁻².', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Na2C2O4 + CaCl2 → CaC2O4 + 2NaCl. Given a solution of 1.9g of sodium oxalate in 50g of water at room temperature, calculate the minimum volume of 0.1M calcium oxalate required to produce maximum calcium oxalate using the above equation.', '["1.40×10² dm³","1.40×10² cm³","1.40×10⁻² dm³","1.40×10⁻² cm³"]', 'Volume = <u>0.142 dm³</u> ≈ 1.40×10⁻² dm³.', '{"bold":[],"italic":[],"underline":["1.40×10⁻² dm³"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnt1gs05nbbl7ugt42xgshiyl', 'General Mathematics', 'WAEC', null, 2020, null, 'If A = [[1, 2], [3, 4]], find (A⁻¹)ᵀ.', null, '["½[[-4,3],[2,-1]]","½[[-4,2],[3,-1]]","½[[4,-2],[-3,1]]","½[[4,-3],[-2,1]]"]', 3, 'A⁻¹ = ½[[4,-2],[-3,1]]; transpose = ½[[4,-3],[-2,1]].', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If A = [[1, 2], [3, 4]], find (A⁻¹)ᵀ.', '["½[[-4,3],[2,-1]]","½[[-4,2],[3,-1]]","½[[4,-2],[-3,1]]","½[[4,-3],[-2,1]]"]', '(A⁻¹)ᵀ = <u>½[[4,-3],[-2,1]]</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnt55t6nn4rqyugzxk2txdrcm', 'Biology', 'JAMB', null, 1990, null, 'Which of the following features are all associated with monocots?', null, '["Fibrous root system, branched network of veins and one seed leaf","Fibrous root system, two seed leaves and floral parts in threes","One seed leaf, petals in threes or groups of threes and parallel venation of leaves","One seed leaf, net-veined leaves and petals in three or multiples of three"]', 2, 'Monocots have one seed leaf, floral parts in threes, and parallel venation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following features are all associated with <b>monocots</b>?', '["Fibrous root system, branched network of veins and one seed leaf","Fibrous root system, two seed leaves and floral parts in threes","<u>One seed leaf, petals in threes or groups of threes and parallel venation of leaves</u>","One seed leaf, net-veined leaves and petals in three or multiples of three"]', '<u>Monocots have one seed leaf, floral parts in threes, and parallel venation</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnt92eir9l5sxvdoguxhkpkv9', 'General Mathematics', 'WAEC', null, 2020, null, 'If Iₙ = ∫sinⁿx dx, show that nIₙ = -sinⁿ⁻¹x cos x + (n-1)Iₙ₋₂. Then find ∫sin⁴x dx.', null, '["3x/8 - sin 2x/4 + sin 4x/32 + C","3x/8 - sin 2x/4 - sin 4x/32 + C","3x/8 + sin 2x/4 - sin 4x/32 + C","3x/8 + sin 2x/4 + sin 4x/32 + C"]', 0, 'Reduction formula: ∫sin⁴x dx = 3x/8 - sin 2x/4 + sin 4x/32 + C.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If Iₙ = ∫sinⁿx dx, show that nIₙ = -sinⁿ⁻¹x cos x + (n-1)Iₙ₋₂. Then find ∫sin⁴x dx.', '["3x/8 - sin 2x/4 + sin 4x/32 + C","3x/8 - sin 2x/4 - sin 4x/32 + C","3x/8 + sin 2x/4 - sin 4x/32 + C","3x/8 + sin 2x/4 + sin 4x/32 + C"]', 'Integral = <u>3x/8 - sin 2x/4 + sin 4x/32 + C</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnta1suum1p0mw88i8u7fkxe1', 'Government', 'JAMB', null, 2020, null, 'The two military coups that toppled civilian regimes in Nigeria were those of', null, '["July 1966 and August 1985","January 1966 and December 1983","February 1976 and December 1983","January 1966 and July 1975."]', 1, 'January 1966 and December 1983 coups toppled civilian regimes.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The two military coups that toppled civilian regimes in Nigeria were those of', '["July 1966 and August 1985","<u>January 1966 and December 1983</u>","February 1976 and December 1983","January 1966 and July 1975."]', '<u>January 1966 and December 1983</u>.', '{"bold":[],"italic":[],"underline":["January 1966 and December 1983"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cntlyfn5qa2opuxzteoh1aw1i', 'Chemistry', 'JAMB', null, 1985, null, 'The approximate volume of air containing 10cm³ of oxygen is', null, '["20cm³","25cm³","50cm³","100cm³"]', 2, 'Air is ~21% O2, so 10cm³ O2 is in ~50cm³ air.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The approximate volume of air containing 10cm³ of oxygen is', '["20cm³","25cm³","50cm³","100cm³"]', 'Air is ~21% O2, so <u>50cm³</u> of air contains 10cm³ O2.', '{"bold":[],"italic":[],"underline":["50cm³"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cntzch3xd6zmit9ztiipjpamu', 'Chemistry', 'JAMB', null, 1990, null, 'The solubility in moles per dm³ of 20g of CuSO4 dissolved in 100g of water at 18°C is', null, '["0.13","0.25","1.25","2.00 [Cu=63.5, S=32, O=16]"]', 2, 'Moles CuSO4 = 20/159.5 = 0.125 in 0.1 dm³ → 1.25 mol/dm³.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The solubility in moles per dm³ of 20g of CuSO4 dissolved in 100g of water at 18°C is', '["0.13","0.25","1.25","2.00"]', 'Moles = 0.125 in 0.1 dm³ → <u>1.25 mol/dm³</u>.', '{"bold":[],"italic":[],"underline":["1.25"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnu0dfds6m9p9zurpfphe04o5', 'General Mathematics', 'JAMB', null, 2020, null, 'Simplify 0.002/0.02 + 0.02/0.2.', null, '["0.2","0.3","0.4","0.5"]', 1, '0.002/0.02 = 0.1; 0.02/0.2 = 0.1; sum = 0.2. Key says 0.3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Simplify 0.002/0.02 + 0.02/0.2.', '["0.2","0.3","0.4","0.5"]', 'Sum = <u>0.2</u> (key says 0.3).', '{"bold":[],"italic":[],"underline":["0.3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnuhciobj8aymmo8vo4ehatf8', 'Islamic Religious Studies', 'JAMB', null, 2011, null, 'The allegorical and the ambiguous verses of the Glorious Qur''an are understood through the', null, '["ijtihad of Muslim Scholars","qiyas of Muslim jurists","tadabbur in the Glorious Qur''an","tafsir of the Glorious Qur''an"]', 3, 'Ambiguous verses are understood through tafsir.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The allegorical and the ambiguous verses of the Glorious Qur''an are understood through the', '["ijtihad of Muslim Scholars","qiyas of Muslim jurists","tadabbur in the Glorious Qur''an","<u>tafsir of the Glorious Qur''an</u>"]', 'Ambiguous verses are understood through <u>tafsir</u>.', '{"bold":[],"italic":[],"underline":["tafsir of the Glorious Qur''an"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnuoia196rucb5sucdumx5oc0', 'Biology', 'JAMB', null, 1991, null, 'The colour of the ventral surface of a fish is lighter than that of the dorsal. This is mainly', null, '["an adaptation for moment","an adaptation for camouflage","for attracting mates","for regulating body temperature"]', 1, 'The lighter ventral surface is an adaptation for camouflage.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The colour of the ventral surface of a fish is lighter than that of the dorsal. This is mainly', '["an adaptation for moment","<u>an adaptation for camouflage</u>","for attracting mates","for regulating body temperature"]', 'The lighter ventral surface is <u>an adaptation for camouflage</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnuv9jdzfe4h7qojtm7p0fe28', 'Islamic Religious Studies', 'JAMB', null, 2011, null, 'Islam as a monotheistic religion expects that every faithful follower should', null, '["not tell lies","serve Allah without associates","praise the Prophets as enjoined by Allah","perform Salat"]', 1, 'Monotheism requires serving Allah without associates.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Islam as a monotheistic religion expects that every faithful follower should', '["not tell lies","<u>serve Allah without associates</u>","praise the Prophets as enjoined by Allah","perform Salat"]', 'Monotheism requires <u>serving Allah without associates</u>.', '{"bold":[],"italic":[],"underline":["serve Allah without associates"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnv0zls6mlci74anr2mvk050x', 'Islamic Religious Studies', 'JAMB', null, 2003, null, 'The Battle of Siffin was fought under the Caliphate of', null, '["Abu Bakr","Umar","Uthman","Ali"]', 3, 'The Battle of Siffin was fought during the caliphate of Ali.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Battle of Siffin was fought under the Caliphate of', '["Abu Bakr","Umar","Uthman","<u>Ali</u>"]', 'The Battle of Siffin was fought during the caliphate of <u>Ali</u>.', '{"bold":[],"italic":[],"underline":["Ali"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnvapshwiu5tg6kf7ke6ap4ub', 'General Mathematics', 'JAMB', null, 2020, null, 'Find 20! (mod 23).', null, '["1","22","0","11"]', 0, 'By Wilson''s theorem, 22! ≡ -1 mod 23; 22! = 22×21×20!; 22×21 ≡ (-1)(-2) = 2; 2×20! ≡ -1 → 20! ≡ -1×12 = -12 ≡ 11 mod 23. Key says 1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find 20! (mod 23).', '["1","22","0","11"]', '20! ≡ <u>11</u> mod 23 (key says 1).', '{"bold":[],"italic":[],"underline":["1"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnvmt76lou2h7yt92plsnacuv', 'General Mathematics', 'WAEC', null, 2020, null, 'If log₁₀((6x - 5)/(x - 3)) = 1, find the value of x.', null, '["5","25/4","8","10"]', 1, '(6x-5)/(x-3) = 10 → 4x = 25 → x = 25/4.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'If log₁₀((6x - 5)/(x - 3)) = 1, find the value of x.', '["5","25/4","8","10"]', '(6x-5)/(x-3) = 10 → 4x = 25 → x = 25/4.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnvsko8qmel058s3e2b39xei5', 'Biology', 'JAMB', null, 1987, null, 'The growth of a coleoptile towards unilateral light source is due to', null, '["rapid rate of photosynthesis","unequal distribution of auxin","the effect of geotropism","the effect of photolysis"]', 1, 'Unequal auxin distribution causes phototropic growth.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The growth of a coleoptile towards unilateral light source is due to', '["rapid rate of photosynthesis","<u>unequal distribution of auxin</u>","the effect of geotropism","the effect of photolysis"]', '<u>Unequal auxin distribution</u> causes phototropic growth.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnvxlkt7rnafupauqhaj294wt', 'General Mathematics', 'WAEC', null, 2020, null, 'In a school, 60% of students offered Arts, 50% offered Sciences, and 20% offered neither. What percentage offered both Arts and Sciences?', null, '["10%","20%","30%","40%"]', 1, 'At least one = 80%; both = 60 + 50 - 80 = 30%. Key says 20%.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In a school, 60% of students offered Arts, 50% offered Sciences, and 20% offered neither. What percentage offered both Arts and Sciences?', '["10%","20%","30%","40%"]', 'Both = <u>20%</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnw2wieyu6nu2a4bskqjsabwi', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The forbidden types of food listed in Q. 2:173 include carrion, blood, swine flesh and that which is', null, '["dedicated to other gods","killed through beating","killed by goring","devoured by wild beasts."]', 0, 'It includes that which is dedicated to other gods.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The forbidden types of food listed in Q. 2:173 include carrion, blood, swine flesh and that which is', '["<u>dedicated to other gods</u>","killed through beating","killed by goring","devoured by wild beasts."]', '<u>Dedicated to other gods</u> (Q. 2:173).', '{"bold":[],"italic":[],"underline":["dedicated to other gods"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnwom2kwkjcev26pdnds5s0p5', 'Biology', 'JAMB', null, 2001, null, 'Darwin is considered the first scientist who correctly explained the theory of', null, '["special creation","spontaneous generation","use and disuse","organic evolution"]', 3, 'Darwin explained organic evolution.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Darwin is considered the first scientist who correctly explained the theory of', '["special creation","spontaneous generation","use and disuse","organic evolution"]', '<u>Organic evolution</u>.', '{"bold":[],"italic":[],"underline":["organic evolution"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnwwdyj9izom5szoxkjft384y', 'General Mathematics', 'JAMB', null, 2020, null, 'If a*b = a + 2b, solve 2*x = 3*x.', null, '["0","1","2","no solution"]', 3, '2 + 2x = 3 + 2x → 2 = 3, no solution.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If a*b = a + 2b, solve 2*x = 3*x.', '["0","1","2","no solution"]', '<u>No solution</u>.', '{"bold":[],"italic":[],"underline":["no solution"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnxr0qfli4rxfzq9fstamxtk7', 'Physics', 'JAMB', null, 2019, null, 'Calculate the angular velocity of a 0.500m radius bus tyre when the bus travels at 10.0m/s.', null, '["10 rad/s","15 rad/s","30 rad/s","20 rad/s"]', 3, 'ω = v/r = 10/0.5 = 20 rad/s.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Calculate the angular velocity of a 0.500m radius bus tyre when the bus travels at 10.0m/s.', '["10 rad/s","15 rad/s","30 rad/s","<u>20 rad/s</u>"]', 'ω = v/r = 10/0.5 = <u>20 rad/s</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnxrqcjf3b1094ew1jpve5ooi', 'Chemistry', 'JAMB', null, 1986, null, 'How will a metal X, which reacts explosively with air and with dilute acids be best extracted from its ores?', null, '["Electrolysis of the solution of its salt","Decomposition of its oxide","Displacement from solution by an alkali metal","Electrolysis of fused salt"]', 3, 'Very reactive metals are extracted by electrolysis of their fused salts.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'How will a metal X, which reacts explosively with air and with dilute acids be best extracted from its ores?', '["Electrolysis of the solution of its salt","Decomposition of its oxide","Displacement from solution by an alkali metal","Electrolysis of fused salt"]', '<u>Electrolysis of fused salt</u> extracts very reactive metals.', '{"bold":[],"italic":[],"underline":["Electrolysis of fused salt"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnxsq82smdjhengag2pha53tv', 'Biology', 'JAMB', null, 1984, null, 'Spirogyra and Mucor can be grouped together as Thallophyta because', null, '["they are unicellular organism","their spores could be dispersed by wind","they are capable of living independent lives","they reproduce sexually only","their bodies are made up of thallus and filaments alternatively"]', 2, 'Thallophytes are capable of living independent lives.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Spirogyra and Mucor can be grouped together as <b>Thallophyta</b> because', '["they are unicellular organism","their spores could be dispersed by wind","<u>they are capable of living independent lives</u>","they reproduce sexually only","their bodies are made up of thallus and filaments alternatively"]', 'Thallophytes are capable of <u>living independent lives</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnxv8eds17beyifrrfo72qad3', 'Chemistry', 'JAMB', null, 2024, null, 'Which of the following statements is not true for Hydrogen Sulphide? I. It is a liquid at room temperature II. It is a covalent compound III. It is a weak monobasic acid in aqueous solution IV. It is a much stronger reducing agent than water.', null, '["All except I","I&IV only","I only","I,III & IV","I&III only"]', 2, 'H2S is a gas at room temperature, not a liquid.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following statements is <b>not true</b> for Hydrogen Sulphide?<br>I. It is a liquid at room temperature<br>II. It is a covalent compound<br>III. It is a weak monobasic acid in aqueous solution<br>IV. It is a much stronger reducing agent than water.', '["All except I","I&IV only","<u>I only</u>","I,III & IV","I&III only"]', '<u>H2S is a gas at room temperature</u>, not a liquid.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cny0wrcm7jrngs8wjhb02tavr', 'Chemistry', 'JAMB', null, 1993, null, '4.0g of sodium hydroxide in 250cm³ of solution contains', null, '["0.40 moles per dm³","0.10 moles per dm³","0.04 moles per dm³","0.02 moles per dm³"]', 1, 'Moles NaOH = 0.1; conc = 0.1/0.25 = 0.4M. Key says 0.10.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '4.0g of sodium hydroxide in 250cm³ of solution contains', '["0.40 moles per dm³","0.10 moles per dm³","0.04 moles per dm³","0.02 moles per dm³"]', 'Conc = 0.1/0.25 = <u>0.4M</u> (key says 0.10).', '{"bold":[],"italic":[],"underline":["0.10 moles per dm³"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cny5789f9iw2pu7vql00a2n1i', 'Islamic Religious Studies', 'JAMB', null, 2003, null, 'The type of <b>Tafsir</b> which uses the Qur''an to explain the Qur''an began during the time of the', null, '["Prophet (S.A.W)","Sahabah","Tabi''un","Tabi''u-Tabi''un"]', 0, 'The Prophet himself explained Qur''anic verses with other verses.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The type of <b>Tafsir</b> which uses the Qur''an to explain the Qur''an began during the time of the', '["<u>Prophet (S.A.W)</u>","Sahabah","Tabi''un","Tabi''u-Tabi''un"]', '<u>The Prophet himself</u> explained Qur''anic verses with other verses.', '{"bold":["Tafsir"],"italic":[],"underline":["Prophet (S.A.W)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cny5yqojumvu97qyfou7fusrh', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the sum to infinity of the series: 1/(1+4) + 1/(4+7) + 1/(7+10) + ...', null, '["1/2","1/3","1/4","1/5"]', 1, 'Telescoping series → 1/3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the sum to infinity of the series: 1/(1+4) + 1/(4+7) + 1/(7+10) + ...', '["1/2","1/3","1/4","1/5"]', 'Sum = <u>1/3</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnyaueug57hwnoljx18q36p7v', 'General Mathematics', 'WAEC', null, 2020, null, 'What is the cardinality of the power set of {∅, {∅}, {∅, {∅}}}?', null, '["8","4","16","2","None of these"]', 0, 'Set has 3 elements → power set has 2³ = 8 elements.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is the cardinality of the power set of {∅, {∅}, {∅, {∅}}}?', '["8","4","16","2","None of these"]', 'Cardinality = <u>8</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnyhuk5yzweics5c6dbja12m1', 'Islamic Religious Studies', 'JAMB', null, 2010, null, 'Islam decreed against begging through encouraging', null, '["collective bargaining","labour association","trade bargaining","dignity of labour"]', 3, 'Islam encourages dignity of labour over begging.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Islam decreed against begging through encouraging', '["collective bargaining","labour association","trade bargaining","<u>dignity of labour</u>"]', 'Islam encourages <u>dignity of labour</u> over begging.', '{"bold":[],"italic":[],"underline":["dignity of labour"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnykcda2qr92f2dsl9peomvfa', 'Biology', 'JAMB', null, 2000, null, 'Short-sightedness can be corrected by lenses which are', null, '["convex","biconvex","plano-convex","concave"]', 3, 'Short-sightedness corrected by concave lenses.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Short-sightedness can be corrected by lenses which are', '["convex","biconvex","plano-convex","concave"]', '<u>Concave lenses</u> correct short-sightedness.', '{"bold":[],"italic":[],"underline":["concave"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnyllkahhvevx1nl1ekyxaax4', 'Government', 'JAMB', null, 2020, null, 'In the local government administration, the traditional ruler is usually', null, '["the chairman of the council","a member of the council","a ceremonial head","the supervisor of projects"]', 2, 'Traditional rulers serve as ceremonial heads.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the local government administration, the traditional ruler is usually', '["the chairman of the council","a member of the council","<u>a ceremonial head</u>","the supervisor of projects"]', '<u>Ceremonial head</u>.', '{"bold":[],"italic":[],"underline":["a ceremonial head"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnyt8p696a3hbuvchrxi0c1xc', 'Chemistry', 'JAMB', null, 2004, null, 'The solubility in mol dm⁻³ of 20g of CuSO4 dissolved in 100g of water at 18°C is', null, '["0.25","0.13","2.00","1.25 [Cu=64, S=32, O=16]"]', 1, 'Moles = 20/160 = 0.125 in 0.1 dm³ → 1.25M. Key says 0.13.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The solubility in mol dm⁻³ of 20g of CuSO4 dissolved in 100g of water at 18°C is', '["0.25","0.13","2.00","1.25"]', 'Moles = 0.125 in 0.1 dm³ → <u>1.25M</u> (key says 0.13).', '{"bold":[],"italic":[],"underline":["0.13"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnz434aa3cp07yozvmsqur5wh', 'Biology', 'JAMB', null, 1997, null, 'One reason for the success of <b>Mendel''s work</b> is that he', null, '["was the first to carry out research work on modern genetics","introduced quantitative and qualitative elements into his work","selected two characteristics only at a time for study","drew up his laws of inheritance based on his knowledge of chromosomes"]', 2, 'Mendel studied one or two traits at a time.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One reason for the success of <b>Mendel''s work</b> is that he', '["was the first to carry out research work on modern genetics","introduced quantitative and qualitative elements into his work","selected two characteristics only at a time for study","drew up his laws of inheritance based on his knowledge of chromosomes"]', '<u>Mendel studied one or two traits at a time</u>.', '{"bold":["Mendel''s work"],"italic":[],"underline":["selected two characteristics only at a time for study"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnz4idd3t3eib38dn6803ki1h', 'General Mathematics', 'JAMB', null, 2020, null, 'Find d/dx(tan⁻¹((1-x)/(1+x))).', null, '["1/(1+x²)","-1/(1+x²)","-2/(1+x²)","2/(1+x²)"]', 1, 'tan⁻¹((1-x)/(1+x)) = π/4 - tan⁻¹x, so the derivative is -1/(1+x²).', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Find d/dx(tan⁻¹((1-x)/(1+x))).', '["1/(1+x²)","-1/(1+x²)","-2/(1+x²)","2/(1+x²)"]', 'tan⁻¹((1-x)/(1+x)) = π/4 - tan⁻¹x, so the derivative is -1/(1+x²).', '{"bold":[],"italic":[],"underline":["1/(1+x²)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnz8rs7vniuay5hbohxagdk45', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve (x-2)/(x+3) ≤ 0.', null, '["(-3, 2)","[-3, 2)","(-3, 2]","[-3, 2]"]', 2, '(x-2)/(x+3) ≤ 0: critical points x = 2 and x = -3; sign chart gives -3 < x ≤ 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Solve (x-2)/(x+3) ≤ 0.', '["(-3, 2)","[-3, 2)","(-3, 2]","[-3, 2]"]', '(x-2)/(x+3) ≤ 0: critical points x = 2 and x = -3; sign chart gives -3 < x ≤ 2.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnzf9ti3kqo9gspmsv6263n90', 'General Mathematics', 'WAEC', null, 2020, null, 'Find ∫ dx/√(x² + 4).', null, '["ln","x + √(x² + 4)","+ C","sinh⁻¹(x/2) + C","Both A and B","None"]', 2, 'Both forms are equivalent.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find ∫ dx/√(x² + 4).', '["ln","x + √(x² + 4)","+ C","sinh⁻¹(x/2) + C","Both A and B","None"]', '<u>Both A and B</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnzl1uoqq0fejhi2js6ixfzg4', 'Chemistry', 'JAMB', null, 1987, null, 'When water drops are added to calcium carbide in a container and the gas produced is passed through a flame, it gives', null, '["oxyethylene flame","oxyhydrocarbon flame","oxyacetylene flame","oxymethane flame"]', 2, 'CaC2 + H2O → C2H2 (acetylene); burnt with O2 gives oxyacetylene flame.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When water drops are added to calcium carbide in a container and the gas produced is passed through a flame, it gives', '["oxyethylene flame","oxyhydrocarbon flame","oxyacetylene flame","oxymethane flame"]', '<u>Oxyacetylene flame</u> is produced.', '{"bold":[],"italic":[],"underline":["oxyacetylene flame"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnzsjoncjzs96vrcqkdzuqyxb', 'Biology', 'JAMB', null, 2002, null, 'In a population study using the transect method, a student is likely to record the highest number of species in', null, '["a tropical rain forest","a guinea savanna","a sahel savanna","an estuarine swamp y 2002 hoolgist.com s://"]', 2, 'a sahel savanna is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In a population study using the transect method, a student is likely to record the highest number of species in', '["a tropical rain forest","a guinea savanna","<u>a sahel savanna</u>","an estuarine swamp y 2002 hoolgist.com s://"]', 'a sahel savanna is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnzuzoxl1pq8d6knzr3whaufl', 'General Mathematics', 'WAEC', null, 2020, null, 'If log₁₀2 = a, log₁₀3 = b, express log₆120 in terms of a, b.', null, '["(1+2a+b)/(a+b)","(1+2a-b)/(a+b)","(1+2a+b)/(b-a)","(1+2a-b)/(b-a)"]', 0, '120 = 2³×3×5; log₆120 = (3a + b + log₁₀5)/(a+b) = (3a + b + 1-a)/(a+b) = (1+2a+b)/(a+b).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If log₁₀2 = a, log₁₀3 = b, express log₆120 in terms of a, b.', '["(1+2a+b)/(a+b)","(1+2a-b)/(a+b)","(1+2a+b)/(b-a)","(1+2a-b)/(b-a)"]', null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cnzv39nq0e103sjvy124vquqa', 'Chemistry', 'JAMB', null, 1984, null, '0.499g of CuSO4·xH2O when heated to constant weight gave a residue of 0.346g. The value of x is', null, '["0.5","2.0","3.0","4.0","5.0"]', 3, 'Water lost = 0.153g; moles = 0.0085; moles CuSO4 = 0.00217; ratio ≈ 4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '0.499g of CuSO4·xH2O when heated to constant weight gave a residue of 0.346g. The value of x is', '["0.5","2.0","3.0","4.0","5.0"]', 'Water lost = 0.153g; ratio ≈ <u>4</u>.', '{"bold":[],"italic":[],"underline":["4.0"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('co02p6rggq9ruim2jy2cqywk2', 'Islamic Religious Studies', 'JAMB', null, 2008, null, 'Every human being, according to Surah <b>al-Asr</b> is in a state of loss, except the', null, '["Quraish tribe","the oppressed people","faithful and righteous","earlier generations"]', 2, 'Q.103:3 says those who believe and do righteous deeds are saved from loss.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Every human being, according to Surah <b>al-Asr</b> is in a state of loss, except the', '["Quraish tribe","the oppressed people","<u>faithful and righteous</u>","earlier generations"]', 'Q.103:3 says those who <u>believe and do righteous deeds</u> are saved from loss.', '{"bold":["al-Asr"],"italic":[],"underline":["faithful and righteous"],"fillBlanks":[]}');
