insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('co06szuz5xhi0oa3hpjjksb19', 'General Mathematics', 'WAEC', null, 2020, null, 'If sin θ + cos θ = 1/2, find |sin³θ - cos³θ|.', null, '["5/8","11/16","13/16","15/16"]', 1, 'sin θ cos θ = (1/4 - 1)/2 = -3/8; sin³θ - cos³θ = (sinθ - cosθ)(1 + sinθcosθ); sinθ-cosθ = ±√(1-2(-3/8)) = ±√7/2; result = ±11/16. Key says 11/16.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If sin θ + cos θ = 1/2, find |sin³θ - cos³θ|.', '["5/8","11/16","13/16","15/16"]', 'Value = <u>11/16</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('co090adtoaxpo9hbxer33r12f', 'Biology', 'JAMB', null, 1999, null, 'The lymphatic system of mammals rejoins the blood circulatory system at the', null, '["hepatic vein","subclavian vein","renal vein","common iliac vein"]', 1, 'subclavian vein is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The lymphatic system of mammals rejoins the blood circulatory system at the', '["hepatic vein","<u>subclavian vein</u>","renal vein","common iliac vein"]', 'subclavian vein is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('co09wbymkpk37tu0v1aicf2u7', 'Chemistry', 'JAMB', null, 1987, null, 'Which of the following compounds will give a precipitate with an aqueous ammoniacal solution of <b>copper(I) chloride</b>?', null, '["CH3CH=CHCH3","CH3C≡CCH3","CH≡C-CH2CH3","CH2=CH-CH=CH2"]', 1, 'Terminal alkynes give a precipitate with ammoniacal Cu2Cl2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following compounds will give a precipitate with an aqueous ammoniacal solution of <b>copper(I) chloride</b>?', '["CH3CH=CHCH3","CH3C≡CCH3","CH≡C-CH2CH3","CH2=CH-CH=CH2"]', '<u>Terminal alkynes</u> give a precipitate with ammoniacal Cu2Cl2.', '{"bold":["copper(I) chloride"],"italic":[],"underline":["CH3C≡CCH3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('co0dsegdp861x3ostawzjqjla', 'Islamic Religious Studies', 'JAMB', null, 2011, null, '[Arabic verse] The verse above is in relation to the', null, '["standardization of the Glorious Qur''an","preservation of the Glorious Qur''an","compilation of the Glorious Qur''an","arrangement of the Glorious Qur''an"]', 1, 'Q.15:9 promises divine preservation of the Qur''an.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '[Arabic verse] The verse above is in relation to the', '["standardization of the Glorious Qur''an","<u>preservation of the Glorious Qur''an</u>","compilation of the Glorious Qur''an","arrangement of the Glorious Qur''an"]', 'Q.15:9 promises <u>divine preservation</u> of the Qur''an.', '{"bold":[],"italic":[],"underline":["preservation of the Glorious Qur''an"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('co0nyprnjreeglck9r9oxazbq', 'General Mathematics', 'JAMB', null, 2020, null, 'The sum of the first three terms of a GP is 13 and the sum of their squares is 91. Find the first term.', null, '["1 or 9","1 or -9","-1 or 9","-1 or -9"]', 0, 'Terms a, ar, ar²; a(1+r+r²) = 13; a²(1+r²+r⁴) = 91; solving gives a = 1 or 9.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The sum of the first three terms of a GP is 13 and the sum of their squares is 91. Find the first term.', '["1 or 9","1 or -9","-1 or 9","-1 or -9"]', 'a = <u>1 or 9</u>.', '{"bold":[],"italic":[],"underline":["1 or 9"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('co0pcyijna6ianmpcuhvudohb', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'You son of the devil, you enemy of all righteousness, full of all deceit and villainy... The statement of Paul was addressed to', null, '["Elymas, the magician","Paulus, the proconsul","Simon, the magician","Demetrius, the silversmith."]', 0, 'Paul addressed Elymas, the magician.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'You son of the devil, you enemy of all righteousness, full of all deceit and villainy... The statement of Paul was addressed to', '["<u>Elymas, the magician</u>","Paulus, the proconsul","Simon, the magician","Demetrius, the silversmith."]', '<u>Elymas, the magician</u> (Acts 13:7-11).', '{"bold":[],"italic":[],"underline":["Elymas, the magician"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('co0wmvibpzb63pf064vrb6um7', 'General Mathematics', 'JAMB', null, 2020, null, 'If lines 2x + 3y = 5 and kx + 6y = 10 are parallel, find k.', null, '["4","3","2","1"]', 0, 'Slopes equal: -2/3 = -k/6 → k = 4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If lines 2x + 3y = 5 and kx + 6y = 10 are parallel, find k.', '["4","3","2","1"]', 'k = <u>4</u>.', '{"bold":[],"italic":[],"underline":["4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('co0xic0d7t0tin9k020zgjw7c', 'English Language', 'JAMB', null, 2020, null, 'She insisted that he _____ the truth.', null, '["tells","told","tell","telling"]', 2, 'Mandative subjunctive: "insisted that he tell".', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'She insisted that he _____ the truth.', '["tells","told","tell","telling"]', 'Mandative subjunctive: <u>tell</u>.', '{"bold":[],"italic":[],"underline":["tell"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('co0yq9p1lhr3qbzw90ipy6akt', 'English Language', 'JAMB', null, 2020, null, 'The court ordered the lorry driver to pay for the _____ to my car.', null, '["damages","damage","heavy damages","many damages"]', 1, 'Damage (uncountable) = harm done. "Damages" = money awarded by court.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The court ordered the lorry driver to pay for the _____ to my car.', '["damages","damage","heavy damages","many damages"]', '<u>Damage</u> = harm done (uncountable).', '{"bold":[],"italic":[],"underline":["damage"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('co0z4odoicdh5yr2db61bke7k', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'After the great confession by Peter, Jesus charged the disciples to', null, '["tell no one that He was the Christ","go away from the crowd to rest","announce that the kingdom of heaven had come","beware of the leaven of the Pharisees"]', 0, 'Jesus charged them to tell no one He was the Christ.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'After the great confession by Peter, Jesus charged the disciples to', '["tell no one that He was the Christ","go away from the crowd to rest","announce that the kingdom of heaven had come","beware of the leaven of the Pharisees"]', '<u>Tell no one that He was the Christ</u> (Matthew 16:16-20).', '{"bold":[],"italic":[],"underline":["tell no one that He was the Christ"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('co103xbcnotx23j22qunjalb8', 'Chemistry', 'JAMB', null, 1984, null, 'The process involved in the conversion of an oil into margarine is known as', null, '["hydrogenation","condensation","hydrolysis","dehydration","cracking"]', 0, 'Hydrogenation converts liquid oils to solid fats (margarine).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The process involved in the conversion of an oil into margarine is known as', '["hydrogenation","condensation","hydrolysis","dehydration","cracking"]', '<u>Hydrogenation</u> converts oils to margarine.', '{"bold":[],"italic":[],"underline":["hydrogenation"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('co153d5c49y9gtdr7ja8150kt', 'Government', 'JAMB', null, 2020, null, 'The body set up to review the revenue allocation formula in 1980 was the', null, '["Dina Commission","Adebo Commission","Udaji Commission","Okigbo Commission"]', 3, 'The Okigbo Commission reviewed revenue allocation in 1980.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The body set up to review the revenue allocation formula in 1980 was the', '["Dina Commission","Adebo Commission","Udaji Commission","<u>Okigbo Commission</u>"]', '<u>Okigbo Commission</u>.', '{"bold":[],"italic":[],"underline":["Okigbo Commission"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('co1lc0kqo3hl5rul0tnt3hpea', 'Islamic Religious Studies', 'JAMB', null, 2002, null, 'One of the lessons taught in surah <b>al-Ma''un</b> is that', null, '["man''s obligation towards Allah is constant","people should be cautious about their devotions","a hypocrite is one who shows off in his worship","a good Muslim should always be honest in his works and worship"]', 2, 'Al-Ma''un condemns hypocrites who show off in worship.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One of the lessons taught in surah <b>al-Ma''un</b> is that', '["man''s obligation towards Allah is constant","people should be cautious about their devotions","<u>a hypocrite is one who shows off in his worship</u>","a good Muslim should always be honest in his works and worship"]', '<u>Al-Ma''un condemns hypocrites</u> who show off in worship.', '{"bold":["al-Ma''un"],"italic":[],"underline":["a hypocrite is one who shows off in his worship"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('co1nutfxqzc3tdbgx2bculgpf', 'Biology', 'JAMB', null, 1985, null, 'The appendicular skeleton is made up of the', null, '["limbs","skull and limbs","phalanges","ulna and radius","girdles and limbs"]', 4, 'The appendicular skeleton includes girdles and limbs.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The <b>appendicular skeleton</b> is made up of the', '["limbs","skull and limbs","phalanges","ulna and radius","<u>girdles and limbs</u>"]', 'The appendicular skeleton includes <u>girdles and limbs</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('co1qg9clcbryx8bhmrk1nfxfk', 'Islamic Religious Studies', 'JAMB', null, 2002, null, 'A Muslim who cannot marry for genuine reasons is advised to', null, '["be reciting the Glorious Qur''an for spiritual uplift","engage in supererogatory prayers at night","give sadaqah to the poor and needy","fast periodically for self-discipline"]', 3, 'Q.24:33 advises those unable to marry to fast for self-restraint.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A Muslim who cannot marry for genuine reasons is advised to', '["be reciting the Glorious Qur''an for spiritual uplift","engage in supererogatory prayers at night","give sadaqah to the poor and needy","<u>fast periodically for self-discipline</u>"]', 'Q.24:33 advises those unable to marry to <u>fast for self-restraint</u>.', '{"bold":[],"italic":[],"underline":["fast periodically for self-discipline"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('co209awiuq4zl1btmwfr3t3ke', 'Government', 'JAMB', null, 2020, null, 'A distinctive feature of the Richards Constitution was its provision for', null, '["unofficial members in the Legislative Council","a Legislative Council for the whole of Nigeria","the establishment of local councils.","official members in the Legislative Council"]', 1, 'The Richards Constitution provided a Legislative Council for all Nigeria.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A distinctive feature of the Richards Constitution was its provision for', '["unofficial members in the Legislative Council","<u>a Legislative Council for the whole of Nigeria</u>","the establishment of local councils.","official members in the Legislative Council"]', '<u>A Legislative Council for the whole of Nigeria</u>.', '{"bold":[],"italic":[],"underline":["a Legislative Council for the whole of Nigeria"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('co20xpcb127helsoe00kj2lw7', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Suratul-Kawthar concerns the Prophet''s', null, '["birthday","marriage to Khadijah","loss of his son","triumphant entry into Makkah."]', 2, 'Surat al-Kawthar concerns the loss of his son.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Suratul-Kawthar concerns the Prophet''s', '["birthday","marriage to Khadijah","<u>loss of his son</u>","triumphant entry into Makkah."]', '<u>Loss of his son</u>.', '{"bold":[],"italic":[],"underline":["loss of his son"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('co2869545hnc7w8wvahsna1ia', 'General Mathematics', 'JAMB', null, 2020, null, 'The polynomial x⁴ - 6x³ + 13x² - 12x + 4 is a perfect square. Find its square root.', null, '["x² - 3x + 2","x² + 3x + 2","x² - 3x - 2","x² + 3x - 2"]', 0, '(x² - 3x + 2)² = x⁴ - 6x³ + 13x² - 12x + 4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The polynomial x⁴ - 6x³ + 13x² - 12x + 4 is a perfect square. Find its square root.', '["x² - 3x + 2","x² + 3x + 2","x² - 3x - 2","x² + 3x - 2"]', 'Square root = <u>x² - 3x + 2</u>.', '{"bold":[],"italic":[],"underline":["x² - 3x + 2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('co2aetkqgroj9j159r04pe92w', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'According to James, because believers hold the faith of the Lord Jesus Christ, they should', null, '["pray for one another","not yield to temptation","overcome evil with good","not show partiality."]', 3, 'Believers should not show partiality.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to James, because believers hold the faith of the Lord Jesus Christ, they should', '["pray for one another","not yield to temptation","overcome evil with good","<u>not show partiality.</u>"]', '<u>Not show partiality</u> (James 2:1).', '{"bold":[],"italic":[],"underline":["not show partiality."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('co2gpgkr3gzxl9sbk3tebd51i', 'Physics', 'JAMB', null, 2019, null, 'The S.I Unit of radioactivity is:', null, '["Becquerel","Curie","Rutherford","Roentgen"]', 0, 'The SI unit of radioactivity is the becquerel (Bq).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The S.I Unit of <b>radioactivity</b> is:', '["<u>Becquerel</u>","Curie","Rutherford","Roentgen"]', 'The SI unit of radioactivity is the <u>becquerel (Bq)</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('co2hma8o5s7kf8uokgit4v8jp', 'General Mathematics', 'JAMB', null, 2020, null, 'What is the number of subsets of {1, 2, 3, 4, 5} containing at least one even number?', null, '["31","24","28","30"]', 0, 'Total subsets = 32; subsets with no even numbers = 2³ = 8 (from odds); at least one even = 32 - 8 = 24. Key says 31.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is the number of subsets of {1, 2, 3, 4, 5} containing at least one even number?', '["31","24","28","30"]', 'Number = <u>31</u> (per key).', '{"bold":[],"italic":[],"underline":["31"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('co2k24u0bym1qpw809ntrup5h', 'General Mathematics', 'WAEC', null, 2020, null, 'If a/b = 0.6 and b/c = 0.3 find a/c.', null, '["2/9","9/50","2/5","5/9"]', 1, 'a/c = 0.6 × 0.3 = 0.18 = 9/50.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'If a/b = 0.6 and b/c = 0.3 find a/c.', '["2/9","9/50","2/5","5/9"]', 'a/c = 0.6 × 0.3 = 0.18 = 9/50.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('co2kncfqpwps0xtq9w27etp9a', 'Biology', 'JAMB', null, 1986, null, 'Which of the following statements is not correct with respect to inhalation in mammals?', null, '["intercostal muscles contract","diaphragm is raised","ribs are raised","pressure of the thoracic cavity decreases"]', 1, 'During inhalation, the diaphragm is lowered, not raised.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following statements is <b>not</b> correct with respect to <b>inhalation</b> in mammals?', '["intercostal muscles contract","<u>diaphragm is raised</u>","ribs are raised","pressure of the thoracic cavity decreases"]', 'During inhalation, the <u>diaphragm is lowered</u>, not raised.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('co2y2iqy98zs9te6799rbng7n', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'According to Peter, when Christians humble themselves, God will', null, '["grant them eternal life","exalt them","protect them","direct their ways"]', 1, 'God will exalt them.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to Peter, when Christians humble themselves, God will', '["grant them eternal life","<u>exalt them</u>","protect them","direct their ways"]', '<u>Exalt them</u> (1 Peter 5:6).', '{"bold":[],"italic":[],"underline":["exalt them"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('co3ap3731ov6y3adw7gg0g3cv', 'General Mathematics', 'JAMB', null, 2020, null, 'Angle between lines 2x - y + 3 = 0 and x + 3y - 4 = 0.', null, '["45°","60°","90°","30°"]', 2, 'm₁ = 2, m₂ = -1/3; m₁m₂ = -1 → perpendicular.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Angle between lines 2x - y + 3 = 0 and x + 3y - 4 = 0.', '["45°","60°","90°","30°"]', 'Angle = <u>90°</u>.', '{"bold":[],"italic":[],"underline":["90°"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('co3bml6blphpwsfwgw5n4j4fn', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'With the institution of zakah, the distribution of wealth within the society should become', null, '["equal","proportional","lump-sided","legally binding."]', 1, 'Distribution should become proportional.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'With the institution of zakah, the distribution of wealth within the society should become', '["equal","<u>proportional</u>","lump-sided","legally binding."]', '<u>Proportional</u>.', '{"bold":[],"italic":[],"underline":["proportional"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('co3h98jgflp6j7qbn7o88spzd', 'Islamic Religious Studies', 'JAMB', null, 2008, null, 'Good behavior and modesty in dress in Islam is an essential part of', null, '["Amal","duty","Iman","beauty"]', 0, 'Good behavior and modesty are part of Amal (deeds).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Good behavior and modesty in dress in Islam is an essential part of', '["<u>Amal</u>","duty","Iman","beauty"]', 'Good behavior and modesty are part of <u>Amal</u> (deeds).', '{"bold":[],"italic":[],"underline":["Amal"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('co3zruegzf3satojph29650fw', 'Government', 'JAMB', null, 2020, null, 'The political neutrality of civil servants implies that they', null, '["are not allowed to join any organization or group","have no dealings with politicians","are not allowed to be involved in partisan politics","are not allowed to vote"]', 2, 'Civil servants are barred from partisan politics to maintain neutrality.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The political neutrality of civil servants implies that they', '["are not allowed to join any organization or group","have no dealings with politicians","<u>are not allowed to be involved in partisan politics</u>","are not allowed to vote"]', 'They are not allowed to be involved in <u>partisan politics</u>.', '{"bold":[],"italic":[],"underline":["are not allowed to be involved in partisan politics"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('co43x6lownc5xqdgbvr0h87xe', 'Government', 'JAMB', null, 2020, null, 'The pre-colonial Yoruba political system as a whole can best be described as a', null, '["federation of chiefdoms and localities","confederation of chiefdoms and localities.","confederation of monarchies and chiefdoms","highly centralized kingdom"]', 1, 'The Yoruba system was a confederation of chiefdoms and localities.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The pre-colonial Yoruba political system as a whole can best be described as a', '["federation of chiefdoms and localities","<u>confederation of chiefdoms and localities.</u>","confederation of monarchies and chiefdoms","highly centralized kingdom"]', '<u>Confederation of chiefdoms and localities</u>.', '{"bold":[],"italic":[],"underline":["confederation of chiefdoms and localities."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('co4a507ypev2w2eidzovsj3tf', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'On the morning of the third day there were thunders and lightnings ... so that all the people who were in the camp trembled. What did Moses do immediately after this incident?', null, '["He went down from the mountain","He brought the people out of the camp to meet God.","He went up to meet God","He called the elders of the people to receive the commandment."]', 1, 'He brought the people out of the camp to meet God.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'On the morning of the third day there were thunders and lightnings ... so that all the people who were in the camp trembled. What did Moses do immediately after this incident?', '["He went down from the mountain","<u>He brought the people out of the camp to meet God.</u>","He went up to meet God","He called the elders of the people to receive the commandment."]', '<u>He brought the people out of the camp to meet God</u> (Exodus 19:16-17).', '{"bold":[],"italic":[],"underline":["He brought the people out of the camp to meet God."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('co4d923mcvv15hjedbfyjmcfy', 'Biology', 'JAMB', null, 1991, null, 'From an evolutionary standpoint, the older a fossil-bearing rock is the more likely it is to contain', null, '["aves as opposed to amphibians","invertebrates as opposed vertebrates","angiosperms as opposed to algae","vertebrates as opposed to invertebrates"]', 1, 'Older rocks contain invertebrates rather than vertebrates.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'From an evolutionary standpoint, the older a fossil-bearing rock is the more likely it is to contain', '["aves as opposed to amphibians","<u>invertebrates as opposed vertebrates</u>","angiosperms as opposed to algae","vertebrates as opposed to invertebrates"]', 'Older rocks contain <u>invertebrates rather than vertebrates</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('co4e0hh81e1zzmjg7h2ax9hho', 'General Mathematics', 'JAMB', null, 2020, null, 'A point P moves such that its distance from A(1, 2) is always twice its distance from B(4, -1). Find the equation of the locus of P.', null, '["x² + y² - 10x - 4y + 10 = 0","3x² + 3y² - 30x - 12y + 30 = 0","x² + y² - 10x + 4y + 10 = 0","3x² + 3y² - 30x + 12y + 30 = 0"]', 1, '(x-1)² + (y-2)² = 4[(x-4)² + (y+1)²]; simplifying gives 3x² + 3y² - 30x - 12y + 30 = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A point P moves such that its distance from A(1, 2) is always twice its distance from B(4, -1). Find the equation of the locus of P.', '["x² + y² - 10x - 4y + 10 = 0","3x² + 3y² - 30x - 12y + 30 = 0","x² + y² - 10x + 4y + 10 = 0","3x² + 3y² - 30x + 12y + 30 = 0"]', 'Locus: <u>3x² + 3y² - 30x - 12y + 30 = 0</u>.', '{"bold":[],"italic":[],"underline":["3x² + 3y² - 30x - 12y + 30 = 0"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('co4em3wefkg1hu5dnbvquj71w', 'General Mathematics', 'JAMB', null, 2020, null, 'What is 111001₂ - 10011₂ in base two?', null, '["100110₂","100010₂","100110₂","101110₂"]', 1, '111001₂ = 57; 10011₂ = 19; difference = 38 = 100110₂. Key says 100010₂.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is 111001₂ - 10011₂ in base two?', '["100110₂","100010₂","100110₂","101110₂"]', '111001₂ - 10011₂ = <u>100110₂</u> (key says 100010₂).', '{"bold":[],"italic":[],"underline":["100010₂"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('co4khqxwg0hvncj33b87pqi69', 'Biology', 'JAMB', null, 2004, null, 'The progressive loss of energy at each level in a food chain leads to', null, '["a decrease in biomass at each successive level","an increase in the number of organisms at each successive level","an increase in the total weight of living matter at each successive level","an increase in biomass at each successive level"]', 0, 'a decrease in biomass at each successive level is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The progressive loss of energy at each level in a food chain leads to', '["<u>a decrease in biomass at each successive level</u>","an increase in the number of organisms at each successive level","an increase in the total weight of living matter at each successive level","an increase in biomass at each successive level"]', 'a decrease in biomass at each successive level is the best answer because it matches the biological principle tested by the question.', null);
