insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('co4xc96tq3pqx3nug1ldb8czu', 'Physics', 'JAMB', null, 2021, null, 'A bottle weighs 10g in air, it weighs 100g when filled with oil and 111g when filled with water. Calculate the relative density of the oil', null, '["1.8","0.9","0.7","10"]', 1, 'Mass of oil = 90g, mass of water = 101g. RD = 90/101 ≈ 0.89 ≈ 0.9.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A bottle weighs 10g in air, it weighs 100g when filled with oil and 111g when filled with water. Calculate the relative density of the oil', '["1.8","<u>0.9</u>","0.7","10"]', 'RD = 90/101 ≈ <u>0.9</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('co4xlc3fhw214cimo09eutjab', 'General Mathematics', 'WAEC', null, 2020, null, 'If (3, 4) is the midpoint of a chord of the circle x² + y² = 25, find the chord''s equation.', null, '["3x + 4y = 25","4x + 3y = 25","3x - 4y = 25","4x - 3y = 25"]', 0, 'Chord perpendicular to radius at (3,4); equation 3x + 4y = 25.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If (3, 4) is the midpoint of a chord of the circle x² + y² = 25, find the chord''s equation.', '["3x + 4y = 25","4x + 3y = 25","3x - 4y = 25","4x - 3y = 25"]', 'Equation: <u>3x + 4y = 25</u>.', null);
