insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('co6lyowqi9rd9tmz0rggbfcj6', 'Biology', 'JAMB', null, 1993, null, 'In Amoeba, osmoregulation is carried out by the', null, '["pseudopodium","food vacuole","contractile vacuole","nucleus"]', 2, 'Osmoregulation in Amoeba is by the contractile vacuole.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In Amoeba, <b>osmoregulation</b> is carried out by the', '["pseudopodium","food vacuole","<u>contractile vacuole</u>","nucleus"]', '<u>Osmoregulation in Amoeba is by the contractile vacuole</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('co6xtu0eu8e786pajm1acra3y', 'Chemistry', 'JAMB', null, 1996, null, 'Ethene when passed into concentrated H2SO4 is rapidly absorbed. The product is diluted with water and then warmed to produce', null, '["ethanol","diethyl ether","ethanal","diethyl sulphate"]', 0, 'Ethene + H2SO4 → ethyl hydrogen sulphate → ethanol.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Ethene when passed into concentrated H2SO4 is rapidly absorbed. The product is diluted with water and then warmed to produce', '["ethanol","diethyl ether","ethanal","diethyl sulphate"]', '<u>Ethanol</u>.', '{"bold":[],"italic":[],"underline":["ethanol"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('co6zp19iguov8u5ta9pir7cg8', 'Chemistry', 'JAMB', null, 1998, null, '8.0g of an element X reacted with an excess of copper(II) tetraoxosulphate(VI) solution to deposit 21.3g of copper. The correct equation for the reaction is', null, '["X(s) + CuSO4(aq) → Cu(s) + XSO4(aq)","X(s) + 2CuSO4(aq) → 2Cu(s) + XSO4(aq)","2X(s) + 2CuSO4(aq) → Cu(s) + X2SO4(aq)","2X(s) + 3CuSO4(aq) → 3Cu(s) + X2(SO4)3(aq)"]', 0, 'Moles Cu = 21.3/63.5 = 0.335; moles X = 0.335; molar mass X = 8/0.335 = 24 (Mg) → X + CuSO4 → Cu + XSO4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '8.0g of an element X reacted with an excess of copper(II) tetraoxosulphate(VI) solution to deposit 21.3g of copper. The correct equation for the reaction is', '["X(s) + CuSO4(aq) → Cu(s) + XSO4(aq)","X(s) + 2CuSO4(aq) → 2Cu(s) + XSO4(aq)","2X(s) + 2CuSO4(aq) → Cu(s) + X2SO4(aq)","2X(s) + 3CuSO4(aq) → 3Cu(s) + X2(SO4)3(aq)"]', '<u>X + CuSO4 → Cu + XSO4</u> (X = Mg, Mr = 24).', '{"bold":[],"italic":[],"underline":["X(s) + CuSO4(aq) → Cu(s) + XSO4(aq)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('co71e4nea23dvf3el4qvctixa', 'Biology', 'JAMB', null, 1991, null, 'The structure labelled II is known as', null, '["sweat gland","lymph vessel","blood vessel","nerve ending"]', 2, 'Structure II is a blood vessel.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The structure labelled <b>II</b> is known as', '["sweat gland","lymph vessel","<u>blood vessel</u>","nerve ending"]', 'Structure <u>II is a blood vessel</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('co780tglmcqigdg52rux50ieg', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the eccentricity of the ellipse 9x² + 16y² = 144.', null, '["√7/4","√7/3","5/4","3/4"]', 0, 'a² = 16, b² = 9; e = √(1 - 9/16) = √7/4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the eccentricity of the ellipse 9x² + 16y² = 144.', '["√7/4","√7/3","5/4","3/4"]', 'Eccentricity = <u>√7/4</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('co7cq6igk9xzza9xn3ylclnc0', 'General Mathematics', 'JAMB', null, 2020, null, 'If α, β are roots of x² - 3x + 1 = 0 find α³ + β³', null, '["15","16","17","18"]', 1, 'α+β = 3; αβ = 1; α³+β³ = 27 - 9 = 18. Key says 16.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If α, β are roots of x² - 3x + 1 = 0 find α³ + β³', '["15","16","17","18"]', null, '{"bold":[],"italic":[],"underline":["16"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('co7elteoe5bedjpkq3w6oajpr', 'Chemistry', 'JAMB', null, 2004, null, 'It is difficult to achieve an orderly arrangement of the molecules of a gas because they', null, '["can collide with one another in the container","are too small in size","have little force of attraction between them","have no definite shape"]', 2, 'Gases have weak intermolecular forces.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'It is difficult to achieve an orderly arrangement of the molecules of a gas because they', '["can collide with one another in the container","are too small in size","have little force of attraction between them","have no definite shape"]', '<u>Weak intermolecular forces</u>.', '{"bold":[],"italic":[],"underline":["have little force of attraction between them"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('co7nx50jd08tbvpeql2hvrzxu', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Saul was rejected as king over Israel because he disobeyed God''s command to utterly destroy the', null, '["Syrians","Amalekites","Philistines","Assyrians"]', 1, 'Saul was rejected for not destroying the Amalekites.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Saul was rejected as king over Israel because he disobeyed God''s command to utterly destroy the', '["Syrians","<u>Amalekites</u>","Philistines","Assyrians"]', '<u>Amalekites</u> (1 Samuel 15).', '{"bold":[],"italic":[],"underline":["Amalekites"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('co7o1bx474m2h995kyeodb26r', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'David''s immediate reaction to the news that the hearts of the Israelites have gone after Absalom was to', null, '["mobilize his army","plead with Absalom","weep for Judah","flee to the wilderness"]', 3, 'David fled to the wilderness.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'David''s immediate reaction to the news that the hearts of the Israelites have gone after Absalom was to', '["mobilize his army","plead with Absalom","weep for Judah","<u>flee to the wilderness</u>"]', '<u>Flee to the wilderness</u> (2 Samuel 15:14).', '{"bold":[],"italic":[],"underline":["flee to the wilderness"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('co7rezpsiueb94r2pvlg84qjb', 'General Mathematics', 'WAEC', null, 2020, null, 'If sum of roots of kx² - 3x + 1 = 0 equals product, find k.', null, '["3","4","5","6"]', 1, '3/k = 1/k → impossible. Key says 4.', false, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'If sum of roots of kx² - 3x + 1 = 0 equals product, find k.', '["3","4","5","6"]', 'k = <u>4</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('co7xibcu2n75a99djjnnfwgl2', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'The order of the crucifixion events according to Luke''s Gospel is', null, '["mockery, lots casting for His dress, scoffing and crucifixion","lots casting for His dress, mockery, scoffing and crucifixion","crucifixion, scoffing, mockery and lots casting for His dress","crucifixion, lots casting for His dress, scoffing and mockery."]', 3, 'The order is crucifixion, lots casting, scoffing, and mockery.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The order of the crucifixion events according to Luke''s Gospel is', '["mockery, lots casting for His dress, scoffing and crucifixion","lots casting for His dress, mockery, scoffing and crucifixion","crucifixion, scoffing, mockery and lots casting for His dress","<u>crucifixion, lots casting for His dress, scoffing and mockery.</u>"]', '<u>Crucifixion, lots casting, scoffing, and mockery</u> (Luke 23:33-35).', '{"bold":[],"italic":[],"underline":["crucifixion, lots casting for His dress, scoffing and mockery."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('co89fg90y11v1da9wpthfzeq6', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The verse ''Wa ma arsalnaka illa rahmatan lil ''alamin'' means', null, '["We have not sent you except as a warner","We have not sent you except as a mercy to the worlds","We have not sent you except as a bearer of glad tidings","We have not sent you except as a witness"]', 1, 'It means "We have not sent you except as a mercy to the worlds."', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The verse ''Wa ma arsalnaka illa rahmatan lil ''alamin'' means', '["We have not sent you except as a warner","<u>We have not sent you except as a mercy to the worlds</u>","We have not sent you except as a bearer of glad tidings","We have not sent you except as a witness"]', '<u>We have not sent you except as a mercy to the worlds</u> (Q. 21:107).', '{"bold":[],"italic":[],"underline":["We have not sent you except as a mercy to the worlds"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('co8fqr17f92ibgb95mzfb2h5a', 'Islamic Religious Studies', 'JAMB', null, 2011, null, 'The presentation of <b>Sermon</b> is an obligation on the Imam when leading', null, '["all the prayers","funeral prayers","Friday prayers","Eid prayers"]', 2, 'The sermon (khutbah) is obligatory for Friday prayers.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The presentation of <b>Sermon</b> is an obligation on the Imam when leading', '["all the prayers","funeral prayers","<u>Friday prayers</u>","Eid prayers"]', 'The <u>sermon (khutbah)</u> is obligatory for Friday prayers.', '{"bold":["Sermon"],"italic":[],"underline":["Friday prayers"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('co8g0nuexapun8e2ujmuhy91s', 'General Mathematics', 'JAMB', null, 2020, null, 'The equation of a curve is y = x³ - 3x² + 3x - 1. Find the point on the curve where the tangent is parallel to the x-axis.', null, '["(1, 0)","(1, -1)","(1, 1)","(2, 1)"]', 0, 'y'' = 3(x-1)² = 0 → x = 1; y = 0. Point (1, 0).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The equation of a curve is y = x³ - 3x² + 3x - 1. Find the point on the curve where the tangent is parallel to the x-axis.', '["(1, 0)","(1, -1)","(1, 1)","(2, 1)"]', 'Point = <u>(1, 0)</u>.', '{"bold":[],"italic":[],"underline":["(1, 0)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('co8spfhjkcqifhrx0h1x2rxuu', 'Biology', 'JAMB', null, 1997, null, 'Which organism in the food-web illustrated above is an <b>omnivore</b>?', null, '["Weevils","Rat","Hawk","Praying mantis"]', 1, 'The rat is an omnivore.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which organism in the food-web illustrated above is an <b>omnivore</b>?', '["Weevils","Rat","Hawk","Praying mantis"]', '<u>The rat is an omnivore</u>.', '{"bold":["omnivore"],"italic":[],"underline":["Rat"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('co8u0k793l0hqo6wi2pmdkil9', 'Government', 'JAMB', null, 2020, null, 'An indication that Africa is still the centre-piece of Nigeria''s foreign policy was the creation of the', null, '["Ministry of Integration and Cooperation in Africa","Nigeria Institute of Policy and Strategic Studies","Ministry of Foreign Affairs.","Nigerian Institute of International Affairs"]', 0, 'The Ministry of Integration and Cooperation in Africa reflects Africa-focused policy.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An indication that Africa is still the centre-piece of Nigeria''s foreign policy was the creation of the', '["<u>Ministry of Integration and Cooperation in Africa</u>","Nigeria Institute of Policy and Strategic Studies","Ministry of Foreign Affairs.","Nigerian Institute of International Affairs"]', '<u>Ministry of Integration and Cooperation in Africa</u>.', '{"bold":[],"italic":[],"underline":["Ministry of Integration and Cooperation in Africa"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('co8xtn3snjlyznbpn1kreqh4r', 'General Mathematics', 'WAEC', null, 2020, null, 'Evaluate lim_{x→0} (e^(3x) - 1)/sin 2x.', null, '["0","2/3","3/2","infinity"]', 2, 'L''Hôpital: 3e^(3x)/(2cos 2x) → 3/2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Evaluate lim_{x→0} (e^(3x) - 1)/sin 2x.', '["0","2/3","3/2","infinity"]', 'Limit = <u>3/2</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('co8zv15cf1ah84cm5rj285ph4', 'Chemistry', 'JAMB', null, 1999, null, 'The salt that reacts with dilute hydrochloric acid to produce a pungent smelling gas which decolorizes acidified purple potassium tetraoxomanganate(VII) solution is', null, '["Na2SO4","Na2SO3","Na2S","Na2CO3"]', 1, 'Na2SO3 + HCl → SO2 (pungent, decolorizes KMnO4).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The salt that reacts with dilute hydrochloric acid to produce a pungent smelling gas which decolorizes acidified purple potassium tetraoxomanganate(VII) solution is', '["Na2SO4","Na2SO3","Na2S","Na2CO3"]', '<u>Na2SO3</u> gives SO2.', '{"bold":[],"italic":[],"underline":["Na2SO3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('co8zv9a3g6cld0jgn98pgvf7g', 'General Mathematics', 'JAMB', null, 2020, null, 'Given that 312ₓ = 2x² + 3x + 1, find x.', null, '["5","6","7","8"]', 0, '312ₓ = 3x² + x + 2 = 2x² + 3x + 1 → x² - 2x + 1 = 0 → x = 1. But x must be > 3 (digit 3). No valid solution. Key says 5.', false, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Given that 312ₓ = 2x² + 3x + 1, find x.', '["5","6","7","8"]', '3x² + x + 2 = 2x² + 3x + 1 → x² - 2x + 1 = 0 → <u>x = 1</u> (invalid, key says 5).', '{"bold":[],"italic":[],"underline":["5"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('co972xdzdklguji4ayf3z6g3d', 'General Mathematics', 'WAEC', null, 2020, null, 'The probability that a student passes Mathematics is 2/3 and the probability that he passes Physics is 4/9. If the probability that he passes at least one subject is 4/5, find the probability that he passes both subjects.', null, '["23/45","28/45","13/45","14/45"]', 1, 'P(both) = 2/3 + 4/9 - 4/5 = (30+20-36)/45 = 14/45. Key says 28/45.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The probability that a student passes Mathematics is 2/3 and the probability that he passes Physics is 4/9. If the probability that he passes at least one subject is 4/5, find the probability that he passes both subjects.', '["23/45","28/45","13/45","14/45"]', 'P(both) = <u>28/45</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('co98zcdp9ufvt43iwg7th2gpk', 'General Mathematics', 'JAMB', null, 2020, null, 'If the binary operation * is defined on the set of real numbers by a*b = a + b + ab, find the inverse of 2 under this operation, if it exists.', null, '["-2/3","-3/2","2/3","3/2"]', 1, 'e = 0; 2*x = 0 → 2 + x + 2x = 0 → 3x = -2 → x = -2/3. Key says -3/2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If the binary operation * is defined on the set of real numbers by a*b = a + b + ab, find the inverse of 2 under this operation, if it exists.', '["-2/3","-3/2","2/3","3/2"]', 'Inverse = <u>-3/2</u> (per key).', '{"bold":[],"italic":[],"underline":["-3/2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('co9hwh4qx4r17gpsh249ubu7y', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve |x + 2| + |x - 2| ≤ 4.', null, '["[-2, 2]","[-4, 4]","(-2, 2)","x = 0 only"]', 0, 'For -2 ≤ x ≤ 2: (x+2) + (2-x) = 4, so true throughout.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve |x + 2| + |x - 2| ≤ 4.', '["[-2, 2]","[-4, 4]","(-2, 2)","x = 0 only"]', 'Solution: <u>[-2, 2]</u>.', '{"bold":[],"italic":[],"underline":["[-2, 2]"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('co9px0ls1tq3ow9nze78hy0ol', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The attribute of Allah which emphasizes His holiness is', null, '["Al-Khaliq","As-Salam","Al-Quddus","Ar-Rahman."]', 2, 'Al-Quddus emphasizes His holiness.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The attribute of Allah which emphasizes His holiness is', '["Al-Khaliq","As-Salam","<u>Al-Quddus</u>","Ar-Rahman."]', '<u>Al-Quddus</u>.', '{"bold":[],"italic":[],"underline":["Al-Quddus"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('co9r8eirx10jvi77ye36mipd5', 'Biology', 'JAMB', null, 1992, null, 'An example of a <b>polysaccharide</b> is', null, '["dextrose","mannose","glucose","starch"]', 3, 'Starch is a polysaccharide.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An example of a <b>polysaccharide</b> is', '["dextrose","mannose","glucose","starch"]', '<u>Starch is a polysaccharide</u>.', '{"bold":["polysaccharide"],"italic":[],"underline":["starch"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('co9upxcldcgi586lp15d6qbrp', 'Biology', 'JAMB', null, 1992, null, 'A tissue can best be defined as', null, '["an aggregate of similar cells","an aggregate of cells performing a similar function","an aggregate of similar cells performing the same function","a mixture of different cell types performing the same function"]', 2, 'A tissue is an aggregate of similar cells performing the same function.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A tissue can best be defined as', '["an aggregate of similar cells","an aggregate of cells performing a similar function","<u>an aggregate of similar cells performing the same function</u>","a mixture of different cell types performing the same function"]', 'A <u>tissue</u> is an aggregate of similar cells performing the same function.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('co9zxhbe39ph22xivncs47bru', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the coefficient of variation for a data set with mean 10 and SD 2.', null, '["20%","25%","30%","35%"]', 0, 'CV = (2/10)×100 = 20%.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the coefficient of variation for a data set with mean 10 and SD 2.', '["20%","25%","30%","35%"]', 'CV = <u>20%</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('coa4ng1l0f7kppmqzt16m1qnh', 'Chemistry', 'JAMB', null, 1994, null, 'When sodium is added to ethanol, the products are', null, '["sodium hydroxide and water","sodium hydroxide and hydrogen","sodium ethoxide and water","sodium ethoxide and hydrogen"]', 3, '2C2H5OH + 2Na → 2C2H5ONa + H2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When sodium is added to ethanol, the products are', '["sodium hydroxide and water","sodium hydroxide and hydrogen","sodium ethoxide and water","sodium ethoxide and hydrogen"]', '<u>Sodium ethoxide and hydrogen</u>.', '{"bold":[],"italic":[],"underline":["sodium ethoxide and hydrogen"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('coacg51rek2jiq0qrbfut8qfl', 'Chemistry', 'JAMB', null, 1988, null, 'Detergents have the general formula', null, '["R(CH2)nOH","RSO3Na⁺","RCO2Na⁺","RCO2H"]', 1, 'Detergents are sodium alkyl sulphonates (RSO3Na).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Detergents have the general formula', '["R(CH2)nOH","RSO3Na⁺","RCO2Na⁺","RCO2H"]', '<u>RSO3Na⁺</u> is the detergent formula.', '{"bold":[],"italic":[],"underline":["RSO3Na⁺"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('coacyohmbv93ms5jekdc9m3nc', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve |2x - 3| > 5.', null, '["x < -1 or x > 4","x < -2 or x > 4","x < -1 or x > 5","x < -2 or x > 5"]', 0, '2x - 3 > 5 → x > 4; 2x - 3 < -5 → x < -1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve |2x - 3| > 5.', '["x < -1 or x > 4","x < -2 or x > 4","x < -1 or x > 5","x < -2 or x > 5"]', 'x < -1 or x > 4.', '{"bold":[],"italic":[],"underline":["x < -1 or x > 4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('coahm5nuksccje040a23n0k34', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The admonition against arrogance in Q. 31:18 is directed to the son of', null, '["Ibrahim","Musa","Luqman","Yusuf."]', 2, 'It is directed to the son of Luqman.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The admonition against arrogance in Q. 31:18 is directed to the son of', '["Ibrahim","Musa","<u>Luqman</u>","Yusuf."]', '<u>Luqman</u> (Q. 31:18).', '{"bold":[],"italic":[],"underline":["Luqman"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('coakqznr9t16aiukf40wbvewa', 'General Mathematics', 'WAEC', null, 2020, null, 'If a ≡ 3 (mod 7) and b ≡ 5 (mod 7), find ab (mod 7).', null, '["1","2","3","4"]', 0, '3×5 = 15 ≡ 1 mod 7.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If a ≡ 3 (mod 7) and b ≡ 5 (mod 7), find ab (mod 7).', '["1","2","3","4"]', 'ab ≡ 3×5 = 15 ≡ <u>1</u> mod 7.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cobbsyogun9yu0ddox6i14yyg', 'Chemistry', 'JAMB', null, 1994, null, 'Which of the following is <b>NOT true</b> of metals?', null, '["They are good conductors of electricity","They ionize by electron loss","Their oxides are acidic","They have high melting points"]', 2, 'Metal oxides are usually basic, not acidic.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is <b>NOT true</b> of metals?', '["They are good conductors of electricity","They ionize by electron loss","Their oxides are acidic","They have high melting points"]', '<u>Metal oxides are basic</u>, not acidic.', '{"bold":["NOT true"],"italic":[],"underline":["Their oxides are acidic"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cobg3a53grseo8hl0joofpypo', 'General Mathematics', 'JAMB', null, 2020, null, 'If x² - 3x + 1 = 0, find x⁴ + 1/x⁴.', null, '["7","47","11","13"]', 1, 'x + 1/x = 3; x² + 1/x² = 7; x⁴ + 1/x⁴ = 49 - 2 = 47.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'If x² - 3x + 1 = 0, find x⁴ + 1/x⁴.', '["7","47","11","13"]', 'x + 1/x = 3; x² + 1/x² = 7; x⁴ + 1/x⁴ = 49 - 2 = 47.', '{"bold":[],"italic":[],"underline":["9"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cobhxu5ojc3u6w4i8uyl2ko11', 'Biology', 'JAMB', null, 1993, null, 'Which of the following sets is made up of decomposers?', null, '["Rhizopus, earthworm and protozoa","Mushroom, rhizopus and bacteria","Bacteria, earthworm and nematodes","Earthworm, sedges and platyhelminthes"]', 1, 'Mushroom, rhizopus, and bacteria are decomposers.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following sets is made up of <b>decomposers</b>?', '["Rhizopus, earthworm and protozoa","<u>Mushroom, rhizopus and bacteria</u>","Bacteria, earthworm and nematodes","Earthworm, sedges and platyhelminthes"]', '<u>Mushroom, rhizopus, and bacteria are decomposers</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cobk6fwz50oddkavyrkh4mack', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'According to Peter, when Christians humble themselves, God will', null, '["grant them eternal life","exalt them","protect them","direct their ways"]', 1, 'God will exalt them.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to Peter, when Christians humble themselves, God will', '["grant them eternal life","<u>exalt them</u>","protect them","direct their ways"]', '<u>Exalt them</u> (1 Peter 5:6).', '{"bold":[],"italic":[],"underline":["exalt them"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cobk9jxnxh9zijdww4tbqj2hz', 'General Mathematics', 'WAEC', null, 2020, null, 'A force of magnitude 10 N acts on a particle in the direction of the vector 3i + 4j. Find the component of this force along the vector i + j.', null, '["7/√2 N","7√2 N","14/√2 N","14√2 N"]', 0, 'F = 10(3i+4j)/5 = 6i+8j; component along (1,1) = (6+8)/√2 = 14/√2 = 7√2. Key says 7/√2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A force of magnitude 10 N acts on a particle in the direction of the vector 3i + 4j. Find the component of this force along the vector i + j.', '["7/√2 N","7√2 N","14/√2 N","14√2 N"]', 'Component = <u>7/√2 N</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cobq86pyulhd7fpzeyac3qm6b', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'King Saul ordered that those who had opposed his ascent to the throne should not be put to death because', null, '["they had been reconciled with him","God had wrought deliverance in Israel","God had forgiven their evil intentions","they had fought bravely in battle"]', 1, 'God had wrought deliverance in Israel.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'King Saul ordered that those who had opposed his ascent to the throne should not be put to death because', '["they had been reconciled with him","<u>God had wrought deliverance in Israel</u>","God had forgiven their evil intentions","they had fought bravely in battle"]', '<u>God had wrought deliverance in Israel</u> (1 Samuel 11:12-13).', '{"bold":[],"italic":[],"underline":["God had wrought deliverance in Israel"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cobsk7tb1bgb51gumrecef0fd', 'Chemistry', 'JAMB', null, 1988, null, 'Which of the following dilute solutions has the <b>lowest pH value</b>?', null, '["Calcium trioxocarbonate(IV)","Sodium trioxocarbonate(IV)","hydrochloric acid","ethanoic acid"]', 2, 'HCl is a strong acid and has the lowest pH.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following dilute solutions has the <b>lowest pH value</b>?', '["Calcium trioxocarbonate(IV)","Sodium trioxocarbonate(IV)","hydrochloric acid","ethanoic acid"]', '<u>HCl (strong acid)</u> has the lowest pH.', '{"bold":["lowest pH value"],"italic":[],"underline":["hydrochloric acid"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cobuagj7lctoc3sv9p7az5ddm', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The Prophet (S.A.W) ordered some of the Muslims to emigrate to Abyssinia', null, '["in order to be far away from Makkah","because he wanted them to preach Islam to the Negus","in order to go beyond the reach of their persecutors","because Bilal, one of the converted Muslims, was an Abyssinian."]', 2, 'They migrated to escape persecution.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Prophet (S.A.W) ordered some of the Muslims to emigrate to Abyssinia', '["in order to be far away from Makkah","because he wanted them to preach Islam to the Negus","<u>in order to go beyond the reach of their persecutors</u>","because Bilal, one of the converted Muslims, was an Abyssinian."]', '<u>In order to go beyond the reach of their persecutors</u>.', '{"bold":[],"italic":[],"underline":["in order to go beyond the reach of their persecutors"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('coc0nmlrzkbrowuwff6mcj7ce', 'General Mathematics', 'WAEC', null, 2020, null, 'If 3/8 of a number is 45, find 40% of it.', null, '["48","52","56","60"]', 0, 'Number = 45 × 8/3 = 120; 40% of 120 = 48.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If 3/8 of a number is 45, find 40% of it.', '["48","52","56","60"]', 'Number = 120; 40% = <u>48</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('coccn9t4t3mj951v6lmzlu78j', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'From which chapter of the Qur''an is the verse which declares ''Certainly, we created man in the best make''?', null, '["87","95","97","99"]', 1, 'It is from chapter 95 (Surat at-Tin).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'From which chapter of the Qur''an is the verse which declares ''Certainly, we created man in the best make''?', '["87","<u>95</u>","97","99"]', '<u>95</u> (Surat at-Tin).', '{"bold":[],"italic":[],"underline":["95"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cochw048250f54c7o35bgquqe', 'Islamic Religious Studies', 'JAMB', null, 2008, null, 'Zihar occurs when a husband compares his', null, '["Wife with himself","Wife with his daughter","Daughter with her friend","Wife with the back of his mother"]', 3, 'Zihar is comparing one''s wife''s back to one''s mother.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Zihar occurs when a husband compares his', '["Wife with himself","Wife with his daughter","Daughter with her friend","<u>Wife with the back of his mother</u>"]', '<u>Zihar</u> is comparing one''s wife''s back to one''s mother.', '{"bold":[],"italic":[],"underline":["Wife with the back of his mother"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cocjdtq9mfae8juxg7ozhs71j', 'General Mathematics', 'WAEC', null, 2020, null, 'Two vectors are given by p = 3i + 4j and q = 5i - 12j. Find the cosine of the angle between them.', null, '["33/65","-33/65","63/65","-63/65"]', 0, 'cos θ = (15-48)/(5·13) = -33/65. Key says 33/65.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Two vectors are given by p = 3i + 4j and q = 5i - 12j. Find the cosine of the angle between them.', '["33/65","-33/65","63/65","-63/65"]', 'cos θ = <u>33/65</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cocpiu3y1azn7yydc3k8372oj', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve for x if: log_x 16 - log_x 4 = 2.', null, '["2","4","8","16"]', 0, 'log_x(16/4) = 2 → log_x 4 = 2 → x² = 4 → x = 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve for x if: log_x 16 - log_x 4 = 2.', '["2","4","8","16"]', '<u>x = 2</u>.', null);
