insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cocygkp5l16xe3y1jhmndxluv', 'General Mathematics', 'WAEC', null, 2020, null, 'Mean deviation about the mean is 3. Find the approximate standard deviation.', null, '["3.75","4.5","5","6"]', 0, 'SD ≈ 1.25 × MD = 3.75.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Mean deviation about the mean is 3. Find the approximate standard deviation.', '["3.75","4.5","5","6"]', 'SD ≈ <u>3.75</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cod2frk3sfh5f9wewm9axi3yu', 'Biology', 'JAMB', null, 1988, null, 'If an animal has diastema, it would NOT possess', null, '["incisors","canines","premolars","molars"]', 1, 'Diastema means the animal lacks canines.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If an animal has <b>diastema</b>, it would <b>NOT</b> possess', '["incisors","<u>canines</u>","premolars","molars"]', 'Diastema means the animal <u>lacks canines</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('coda3m6adrrr39zuz71vep1su', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve sin x + cos x = 1 for 0 ≤ x ≤ 2π.', null, '["0, π/2","0, π/3","π/2, π","π/4, π"]', 0, 'sin x + cos x = √2 sin(x + π/4) = 1 → x + π/4 = π/4 or 3π/4 → x = 0 or π/2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve sin x + cos x = 1 for 0 ≤ x ≤ 2π.', '["0, π/2","0, π/3","π/2, π","π/4, π"]', 'x = <u>0, π/2</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('codhjhxw2rauim4ztd6q18enf', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Which of the following sets, according to Ayatul Kursiyy, is Allah not susceptible to?', null, '["Thirst or hunger","Slumber or sleep","Fear or terror","Sickness or pain."]', 1, 'Allah is not susceptible to slumber or sleep.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following sets, according to Ayatul Kursiyy, is Allah not susceptible to?', '["Thirst or hunger","<u>Slumber or sleep</u>","Fear or terror","Sickness or pain."]', '<u>Slumber or sleep</u> (Q. 2:255).', '{"bold":[],"italic":[],"underline":["Slumber or sleep"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('codw0dymbb7ryshkk8dk60d3j', 'Biology', 'JAMB', null, 1986, null, 'The swollen shoot disease of cocoa tree is caused by a', null, '["virus","fungus","bacterium","protozoan"]', 0, 'Swollen shoot disease is caused by a virus.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The <b>swollen shoot disease</b> of cocoa tree is caused by a', '["<u>virus</u>","fungus","bacterium","protozoan"]', '<u>Swollen shoot disease</u> is caused by a virus.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('coe756a4i147bdixlhg91nf2v', 'Islamic Religious Studies', 'JAMB', null, 2020, null, '''Verily Allah has prescribed the best behavior with regard to everything ...'' The above quotation from Hadith 17 of an-Nawawi''s collection emphasizes the ethics of', null, '["Eating and drinking","slaughtering animals","behaving in public","matrimonial relations."]', 1, 'It emphasizes the ethics of slaughtering animals.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '''Verily Allah has prescribed the best behavior with regard to everything ...'' The above quotation from Hadith 17 of an-Nawawi''s collection emphasizes the ethics of', '["Eating and drinking","<u>slaughtering animals</u>","behaving in public","matrimonial relations."]', '<u>Slaughtering animals</u>.', '{"bold":[],"italic":[],"underline":["slaughtering animals"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('coe868vltj5n6ssywrmh1j7ol', 'Islamic Religious Studies', 'JAMB', null, 2002, null, 'The number of lashes prescribed for the consumption of alcohol is', null, '["forty","sixty","eighty","hundred"]', 2, 'Eighty lashes is the prescribed penalty for alcohol consumption.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The number of lashes prescribed for the consumption of alcohol is', '["forty","sixty","<u>eighty</u>","hundred"]', '<u>Eighty lashes</u> is the prescribed penalty for alcohol consumption.', '{"bold":[],"italic":[],"underline":["eighty"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('coenqugkdu64ixw2sbgh9ys04', 'Biology', 'JAMB', null, 2003, null, 'An example of <b>cryptic colouration</b> is the', null, '["bright marks on a poisonous tropical frog on variegated leaves","bright colour of an insect-pollinated flower","mottled colours on moths that rest on lichens","green colour of a plant"]', 2, 'Mottled colours on moths = cryptic colouration.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An example of <b>cryptic colouration</b> is the', '["bright marks on a poisonous tropical frog on variegated leaves","bright colour of an insect-pollinated flower","mottled colours on moths that rest on lichens","green colour of a plant"]', '<u>Mottled colours on moths</u> = cryptic colouration.', '{"bold":["cryptic colouration"],"italic":[],"underline":["mottled colours on moths that rest on lichens"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('coeqofizfdeaw12ynrgbu0m8p', 'Chemistry', 'JAMB', null, 1983, null, 'Consecutive members of an <b>alkane</b> homologous series differ by', null, '["CH","CH2","CH3","CH4","CnH2n+2"]', 1, 'Consecutive members of a homologous series differ by a CH2 unit.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Consecutive members of an <b>alkane</b> homologous series differ by', '["CH","CH2","CH3","CH4","CnH2n+2"]', 'Consecutive members of a homologous series differ by a <u>CH2 unit</u>.', '{"bold":["alkane"],"italic":[],"underline":["CH2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('coes51limmvqjj7nk765408fc', 'General Mathematics', 'JAMB', null, 2020, null, 'Two dice are rolled. Sum is 8. Find the probability one die shows a 3.', null, '["2/5","1/2","2/7","3/8"]', 0, 'Sum 8: (2,6),(3,5),(4,4),(5,3),(6,2); one die 3: (3,5),(5,3) → 2/5.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Two dice are rolled. Sum is 8. Find the probability one die shows a 3.', '["2/5","1/2","2/7","3/8"]', 'P = <u>2/5</u>.', '{"bold":[],"italic":[],"underline":["2/5"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('coewcjdtgpjqnp2u3gestoakh', 'Government', 'JAMB', null, 2020, null, 'Nigeria is rated in the Organization of Petroleum Exporting Countries as the', null, '["seventh largest oil producer.","sixth largest oil producer","third largest oil producer","fifth largest oil producer"]', 1, 'Nigeria is rated as the sixth largest oil producer in OPEC.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Nigeria is rated in the Organization of Petroleum Exporting Countries as the', '["seventh largest oil producer.","<u>sixth largest oil producer</u>","third largest oil producer","fifth largest oil producer"]', '<u>Sixth largest oil producer</u>.', '{"bold":[],"italic":[],"underline":["sixth largest oil producer"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cof6ihig0222dxz9okttx0e8e', 'Biology', 'JAMB', null, 1990, null, 'The parts labelled I and II make up the', null, '["glomerulus","convoluted tubules","malpighian body","bowman''s capsule"]', 2, 'Parts I and II make up the malpighian body.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The parts labelled I and II make up the', '["glomerulus","convoluted tubules","<u>malpighian body</u>","bowman''s capsule"]', 'Parts <u>I and II make up the malpighian body</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cofa901ctgcyfmzawfwmrh91z', 'Biology', 'JAMB', null, 2003, null, 'If the pair of alleles for baldness is given as Bb, a female carrier will be denoted by', null, '["XᴮXᵇ","XᴮXᴮ","XᵇY","XᵇY"]', 0, 'Female carrier = XᴮXᵇ.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If the pair of alleles for baldness is given as Bb, a female carrier will be denoted by', '["XᴮXᵇ","XᴮXᴮ","XᵇY","XᵇY"]', '<u>XᴮXᵇ</u>.', '{"bold":[],"italic":[],"underline":["XᴮXᵇ"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cofby4lvo9kt5frx0yw7i6ovx', 'Chemistry', 'JAMB', null, 1993, null, 'Which of the following represents <b>saponification</b>?', null, '["reaction of carboxylic acids with sodium hydroxide","reaction of alkanoates with acids","reaction of carboxylic acids with sodium alcohols","reaction of alkanoates with sodium hydroxide"]', 3, 'Saponification is alkaline hydrolysis of esters (alkanoates).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following represents <b>saponification</b>?', '["reaction of carboxylic acids with sodium hydroxide","reaction of alkanoates with acids","reaction of carboxylic acids with sodium alcohols","reaction of alkanoates with sodium hydroxide"]', '<u>Alkanoates + NaOH</u> is saponification.', '{"bold":["saponification"],"italic":[],"underline":["reaction of alkanoates with sodium hydroxide"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('coflha324ikrix1axx94vfvmz', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The Qur''anic verse Q. 17:31 prohibits', null, '["adultery","infanticide","bribery","arrogance"]', 1, 'Q. 17:31 prohibits infanticide.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Qur''anic verse Q. 17:31 prohibits', '["adultery","<u>infanticide</u>","bribery","arrogance"]', '<u>Infanticide</u> (Q. 17:31).', '{"bold":[],"italic":[],"underline":["infanticide"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cofuu9gzgca8hxbv2j7eaekvp', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The pre-colonial West African rulers employed the services of Muslim scholars mostly as', null, '["teachers","secretaries","ambassadors","Imams."]', 1, 'They were mostly employed as secretaries.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The pre-colonial West African rulers employed the services of Muslim scholars mostly as', '["teachers","<u>secretaries</u>","ambassadors","Imams."]', '<u>Secretaries</u>.', '{"bold":[],"italic":[],"underline":["secretaries"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cog41zc0gqd4jutp9svio211z', 'General Mathematics', 'JAMB', null, 2020, null, 'A bag contains 5R, 4G, 3B balls. Two balls are drawn without replacement. Find the probability both are the same color.', null, '["19/66","20/66","21/66","22/66"]', 0, 'P = (5C2 + 4C2 + 3C2)/12C2 = (10+6+3)/66 = 19/66.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A bag contains 5R, 4G, 3B balls. Two balls are drawn without replacement. Find the probability both are the same color.', '["19/66","20/66","21/66","22/66"]', 'P = <u>19/66</u>.', '{"bold":[],"italic":[],"underline":["19/66"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cog88cncutvqbjuocekwwyrbc', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Behold, the days are coming ... when I will send a famine on the land ... Famine in the statement above means', null, '["lack of food","unavailability of the word of God","failure of the farms to produce","lack of water."]', 1, 'Famine means unavailability of the word of God.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Behold, the days are coming ... when I will send a famine on the land ... Famine in the statement above means', '["lack of food","<u>unavailability of the word of God</u>","failure of the farms to produce","lack of water."]', '<u>Unavailability of the word of God</u> (Amos 8:11).', '{"bold":[],"italic":[],"underline":["unavailability of the word of God"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cogxqp4hkk39j5g422tbwzstx', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'The LORD repented of the evil which He intended for His people because Moses', null, '["reminded Him of His promise to Abraham, Isaac and Israel","made the people drink of the water of the burnt calf","burnt the golden calf which the people made","broke the tablets out of his hands."]', 0, 'Moses reminded God of His promise to Abraham, Isaac, and Israel.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The LORD repented of the evil which He intended for His people because Moses', '["<u>reminded Him of His promise to Abraham, Isaac and Israel</u>","made the people drink of the water of the burnt calf","burnt the golden calf which the people made","broke the tablets out of his hands."]', '<u>Reminded Him of His promise to Abraham, Isaac and Israel</u> (Exodus 32:12-13).', '{"bold":[],"italic":[],"underline":["reminded Him of His promise to Abraham, Isaac and Israel"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('coh20nwecv4yp562v70u09xg8', 'General Mathematics', 'WAEC', null, 2020, null, 'If n(A) = 35, n(B) = 45, n(A ∪ B) = 60, find n(A ∩ B).', null, '["20","25","30","35"]', 0, 'n(A ∩ B) = 35 + 45 - 60 = 20.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If n(A) = 35, n(B) = 45, n(A ∪ B) = 60, find n(A ∩ B).', '["20","25","30","35"]', 'n(A ∩ B) = <u>20</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('coh8xi90pgr2vk3p4ucabun7y', 'Chemistry', 'JAMB', null, 2004, null, 'The mass of silver deposited when a current of 10A is passed through a solution of silver salt for 4830s is', null, '["54.0g","27.0g","13.5g","108.0g [Ag=108, F=96500 C mol⁻¹]"]', 1, 'Q = 10 × 4830 = 48300C; moles Ag = 0.5; mass = 54g.', true, '2026-10-11 07:17:11.699', '2026-10-17 10:29:25.194', null, null, null, 'The mass of silver deposited when a current of 10A is passed through a solution of silver salt for 4830s is', '["54.0g","27.0g","13.5g","108.0g"]', 'Mass = 0.5 × 108 = <u>54.0g</u> (key says 27).', '{"bold":[],"italic":[],"underline":["27.0g"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('coha3g4ny18yxghcfj9c1fui3', 'Chemistry', 'JAMB', null, 2024, null, 'Electrons are filled into degenerate orbitals singly before pairing up, this is in accordance with ____', null, '["Hund''s rule","Pauli exclusion principle","Aufbau principle","Spdf notation"]', 0, 'Hund''s rule states that degenerate orbitals are singly occupied before pairing.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Electrons are filled into degenerate orbitals singly before pairing up, this is in accordance with ____', '["<u>Hund''s rule</u>","Pauli exclusion principle","Aufbau principle","Spdf notation"]', '<u>Hund''s rule</u> states that degenerate orbitals are singly occupied before pairing.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cohlwr3mekpikuxqgnbswigj8', 'Biology', 'JAMB', null, 1985, null, 'In lower plants like mosses, the structure which performs the functions of roots of higher plants is called', null, '["root hairs","rootlets","hyphae","rhizoids","thalli"]', 3, 'Rhizoids perform root functions in mosses.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In lower plants like mosses, the structure which performs the functions of roots of higher plants is called', '["root hairs","rootlets","hyphae","<u>rhizoids</u>","thalli"]', '<u>Rhizoids</u> perform root functions in mosses.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cohnxyoy502q7pkg55qx30f7t', 'General Mathematics', 'WAEC', null, 2020, null, 'Simplify (0.3 × 0.03) / 0.003.', null, '["3","0.3","30","300"]', 0, '(0.3 × 0.03) / 0.003 = 0.009/0.003 = 3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Simplify (0.3 × 0.03) / 0.003.', '["3","0.3","30","300"]', '(0.3 × 0.03) / 0.003 = <u>3</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cohpkvsccgg7wglcduuy76ydq', 'Chemistry', 'JAMB', null, 1992, null, 'Calculate the mass, in kilograms, of magnesium produced by the electrolysis of magnesium(II) chloride in a cell operating for 24 hours at 500 amperes. [F=96500C, Mg=24]', null, '["2.7","5.4","10.8","21.7"]', 1, 'Q = 500 × 86400 = 4.32×10⁷ C; moles e⁻ = 447.7; moles Mg = 223.8; mass = 5.37 kg.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Calculate the mass, in kilograms, of magnesium produced by the electrolysis of magnesium(II) chloride in a cell operating for 24 hours at 500 amperes. [F=96500C, Mg=24]', '["2.7","5.4","10.8","21.7"]', 'Mass ≈ <u>5.4 kg</u>.', '{"bold":[],"italic":[],"underline":["5.4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cohq02puvaypnelp9xl3kw779', 'Islamic Religious Studies', 'JAMB', null, 2008, null, 'The first major written work of ahadith was', null, '["Sahih Muslim","Sunan Ibn Majah","Muwata Malik","Musnad Ahmad"]', 2, 'The Muwatta of Imam Malik is the first major written Hadith work.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The first major written work of ahadith was', '["Sahih Muslim","Sunan Ibn Majah","<u>Muwata Malik</u>","Musnad Ahmad"]', 'The <u>Muwatta of Imam Malik</u> is the first major written Hadith work.', '{"bold":[],"italic":[],"underline":["Muwata Malik"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cohskb0qsze095qx497mwe1j6', 'General Mathematics', 'WAEC', null, 2020, null, 'If AM of two numbers = 10, GM = 8, find HM.', null, '["6.4","7.2","8.5","9"]', 0, 'AM × HM = GM² → HM = 64/10 = 6.4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If AM of two numbers = 10, GM = 8, find HM.', '["6.4","7.2","8.5","9"]', 'HM = <u>6.4</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('coi6bxe48ry1vllbmy8d9g3is', 'Government', 'JAMB', null, 2020, null, 'Which of the following is used in gauging public opinion?', null, '["Constitution","Educational institution","Mass Media","Electoral college."]', 2, 'The mass media gauges public opinion.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is used in gauging public opinion?', '["Constitution","Educational institution","<u>Mass Media</u>","Electoral college."]', '<u>Mass Media</u>.', '{"bold":[],"italic":[],"underline":["Mass Media"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('coirypbqwoeh6zt1sc5bq8v72', 'General Mathematics', 'JAMB', null, 2020, null, 'If 2ⁿ ≡ 1 (mod 5), what is the smallest positive n?', null, '["2","3","4","5"]', 2, '2⁴ = 16 ≡ 1 mod 5.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If 2ⁿ ≡ 1 (mod 5), what is the smallest positive n?', '["2","3","4","5"]', '2⁴ = 16 ≡ <u>1</u> mod 5 → n = 4.', '{"bold":[],"italic":[],"underline":["4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('coiy1bufq64nbpjqxl608b9oo', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The extract from Hadith No. 1 of an-Nawawi is followed by', null, '["Wa innama likulli imri''in ma ra''a","Wa innal mu''minuna ikhwatun","Wa innal halala bayyinun","Wa innama likulli imri''in ma nawa"]', 3, 'Hadith 1 of an-Nawawi is followed by "Wa innama likulli imri''in ma nawa."', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The extract from Hadith No. 1 of an-Nawawi is followed by', '["Wa innama likulli imri''in ma ra''a","Wa innal mu''minuna ikhwatun","Wa innal halala bayyinun","<u>Wa innama likulli imri''in ma nawa</u>"]', '<u>Wa innama likulli imri''in ma nawa</u>.', '{"bold":[],"italic":[],"underline":["Wa innama likulli imri''in ma nawa"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('coj9j0ffupwfu48fos1gk0r5r', 'Chemistry', 'JAMB', null, 1993, null, 'At 25°C and 1 atm, a gas occupies a volume of 1.50dm³. What volume will it occupy at 100°C at 1 atm?', null, '["1.88dm³","6.00dm³","18.80dm³","60.00dm³"]', 0, 'V2 = 1.5 × 373/298 = 1.88 dm³.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'At 25°C and 1 atm, a gas occupies a volume of 1.50dm³. What volume will it occupy at 100°C at 1 atm?', '["1.88dm³","6.00dm³","18.80dm³","60.00dm³"]', 'V2 = <u>1.88 dm³</u>.', '{"bold":[],"italic":[],"underline":["1.88dm³"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cojas3su78dv2v6yijctihekh', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'After his arrest, Jesus was taken to', null, '["Caiaphas","Pilate","Pontiphas","Agrippa"]', 0, 'Jesus was taken to Caiaphas.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'After his arrest, Jesus was taken to', '["<u>Caiaphas</u>","Pilate","Pontiphas","Agrippa"]', '<u>Caiaphas</u> (Matthew 26:57).', '{"bold":[],"italic":[],"underline":["Caiaphas"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cojbpuqn9kjsp8cjstf37sxlw', 'General Mathematics', 'WAEC', null, 2020, null, 'If sin A + sin B = √2 cos C and cos A + cos B = √2 sin C, find cos(A - B).', null, '["0","1/2","1","-1"]', 0, 'Squaring and adding: 2 + 2cos(A-B) = 2 → cos(A-B) = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If sin A + sin B = √2 cos C and cos A + cos B = √2 sin C, find cos(A - B).', '["0","1/2","1","-1"]', 'cos(A - B) = <u>0</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cojhovseauoqhmsmb5xz5xflt', 'Physics', 'JAMB', null, 2019, null, 'An induction coil is generally used to', null, '["rectify an alternating current","produce a large input voltage","smooth a pulsating direct current","produce a large output voltage"]', 3, 'An induction coil is used to produce a large output voltage from a low input voltage.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An <b>induction coil</b> is generally used to', '["rectify an alternating current","produce a large input voltage","smooth a pulsating direct current","<u>produce a large output voltage</u>"]', 'An induction coil is used to <u>produce a large output voltage</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('coju771qpn9b408u3lfzwitb7', 'Government', 'JAMB', null, 2020, null, 'A collegial executive is a government in which power is vested with the', null, '["president","monarch","committee","parliament"]', 2, 'A collegial executive vests power in a committee.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A collegial executive is a government in which power is vested with the', '["president","monarch","<u>committee</u>","parliament"]', '<u>Committee</u>.', '{"bold":[],"italic":[],"underline":["committee"],"fillBlanks":[]}');
