insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cokbli4ro15t6vugo4jf94zpn', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'The angel told Zachariah that John the Baptist would drink no wine nor strong drink because he would', null, '["only eat locusts and wild honey","be the forerunner of Jesus","baptize sinners who would come to Him","be filled with the Holy Spirit."]', 3, 'He would be filled with the Holy Spirit.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The angel told Zachariah that John the Baptist would drink no wine nor strong drink because he would', '["only eat locusts and wild honey","be the forerunner of Jesus","baptize sinners who would come to Him","<u>be filled with the Holy Spirit.</u>"]', '<u>Be filled with the Holy Spirit</u> (Luke 1:15).', '{"bold":[],"italic":[],"underline":["be filled with the Holy Spirit."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cokej7rabvxwk71skt711e2vd', 'Biology', 'JAMB', null, 1984, null, 'Underground stems which grow horizontally through the soil are', null, '["blubs","rhizomes","runners","corms","stolons"]', 1, 'Rhizomes are underground stems growing horizontally.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Underground stems which grow horizontally through the soil are', '["blubs","<u>rhizomes</u>","runners","corms","stolons"]', '<u>Rhizomes</u> are underground stems growing horizontally.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cokjw8fva6h82ekv8yi21znqd', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Amaziah the priest of Bethel accused Amos, before Jeroboam the king of Israel, of', null, '["conspiracy","rebellion","libel","sabotage"]', 0, 'Amaziah accused Amos of conspiracy.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Amaziah the priest of Bethel accused Amos, before Jeroboam the king of Israel, of', '["<u>conspiracy</u>","rebellion","libel","sabotage"]', '<u>Conspiracy</u> (Amos 7:10).', '{"bold":[],"italic":[],"underline":["conspiracy"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cokk613emiku0f96ox5boacit', 'Chemistry', 'JAMB', null, 1995, null, 'The label on a reagent bottle containing a clear organic liquid dropped off. The liquid was neutral to litmus and gave a colourless gas with metallic sodium. The liquid must be an', null, '["alkanoate","alkene","alkanol","alkane"]', 2, 'Alcohols react with Na to give H2, are neutral.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The label on a reagent bottle containing a clear organic liquid dropped off. The liquid was neutral to litmus and gave a colourless gas with metallic sodium. The liquid must be an', '["alkanoate","alkene","alkanol","alkane"]', '<u>Alkanol (alcohol)</u> reacts with Na to give H2.', '{"bold":[],"italic":[],"underline":["alkanol"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cokojbtumi1uaytx9ykt9jmtv', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'According to Hosea, the LORD would not have pity upon children of his faithless wife because', null, '["they had not been faithful","they were rebellious children","their mother had played the harlot","their mother had not shown pity on them."]', 2, 'Their mother had played the harlot.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to Hosea, the LORD would not have pity upon children of his faithless wife because', '["they had not been faithful","they were rebellious children","<u>their mother had played the harlot</u>","their mother had not shown pity on them."]', '<u>Their mother had played the harlot</u> (Hosea 1-2).', '{"bold":[],"italic":[],"underline":["their mother had played the harlot"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cokt4m0qb6a8gingtihl6de9m', 'General Mathematics', 'JAMB', null, 2020, null, 'In a class of 40 students, 25 passed Mathematics, 20 passed Physics, and 8 passed both. What is the probability that a student selected at random passed at least one of the subjects?', null, '["7/8","37/40","5/8","5/40"]', 1, 'At least one = 25 + 20 - 8 = 37; P = 37/40.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In a class of 40 students, 25 passed Mathematics, 20 passed Physics, and 8 passed both. What is the probability that a student selected at random passed at least one of the subjects?', '["7/8","37/40","5/8","5/40"]', 'P = <u>37/40</u>.', '{"bold":[],"italic":[],"underline":["37/40"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cokt835le1bwzrhinw1yo9nlu', 'General Mathematics', 'JAMB', null, 2020, null, 'Find ∫ √((1 - x)/(1 + x)) dx.', null, '["sin⁻¹x + √(1 - x²) + C","sin⁻¹x - √(1 - x²) + C","cos⁻¹x - √(1 - x²) + C","cos⁻¹x + √(1 - x²) + C"]', 0, 'Trig substitution x = cos θ; result = sin⁻¹x + √(1 - x²) + C.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find ∫ √((1 - x)/(1 + x)) dx.', '["sin⁻¹x + √(1 - x²) + C","sin⁻¹x - √(1 - x²) + C","cos⁻¹x - √(1 - x²) + C","cos⁻¹x + √(1 - x²) + C"]', 'Integral = <u>sin⁻¹x + √(1 - x²) + C</u>.', '{"bold":[],"italic":[],"underline":["sin⁻¹x + √(1 - x²) + C"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cokwuzpxc3h7gm45wpybxe2ty', 'Biology', 'JAMB', null, 1986, null, 'In an ecosystem, animals which feed directly on plants are called', null, '["secondary consumers","primary consumers","producers","predators"]', 1, 'Animals feeding directly on plants are primary consumers.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In an ecosystem, animals which feed directly on plants are called', '["secondary consumers","<u>primary consumers</u>","producers","predators"]', 'Animals feeding directly on plants are <u>primary consumers</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('col272q5q1zaqrzp4or51mvxz', 'Biology', 'JAMB', null, 2000, null, 'Which of the following is an adaptation of <b>forest species</b>?', null, '["Few stomata","Thick bark","Buttress roots","Reduced leaves"]', 2, 'Buttress roots are a forest adaptation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is an adaptation of <b>forest species</b>?', '["Few stomata","Thick bark","Buttress roots","Reduced leaves"]', '<u>Buttress roots</u> are a forest adaptation.', '{"bold":["forest species"],"italic":[],"underline":["Buttress roots"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('col9ym3ayzqwkspadm7c2fo3t', 'General Mathematics', 'WAEC', null, 2020, null, 'If 2ⁿ ≡ 1 (mod 5), what is the smallest positive n?', null, '["2","3","4","5"]', 2, '2⁴ = 16 ≡ 1 mod 5.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If 2ⁿ ≡ 1 (mod 5), what is the smallest positive n?', '["2","3","4","5"]', '2⁴ = 16 ≡ <u>1</u> mod 5 → n = 4.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('colc96uxo76gzeillqlaezxen', 'General Mathematics', 'WAEC', null, 2020, null, 'The rate of change of the volume of a sphere with respect to its radius r is 36π. Find the radius r.', null, '["3","6","9","18"]', 0, 'dV/dr = 4πr² = 36π → r² = 9 → r = 3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The rate of change of the volume of a sphere with respect to its radius r is 36π. Find the radius r.', '["3","6","9","18"]', 'r = <u>3</u>.', null);
