insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('comi70x7yr6slqbrlsxgtldyc', 'Biology', 'JAMB', null, 2000, null, 'The order in which organic evolution has progressed in plants is', null, '["thallophyta, schizophyta, bryophyta, pteridophyta and spermatophyta","schizophyta, thallophyta, bryophyta, pteridophyta and spermatophyta","pteridophyata, spermatophyta, thallophyta, schizophyta and bryophyta","bryophyta, pteridophyta, spermatophyta, thallophyta and schizophyta. Biolog www.myscho Download MySchoolGist JAMB CBT Software from https"]', 1, 'schizophyta, thallophyta, bryophyta, pteridophyta and spermatophyta is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The order in which organic evolution has progressed in plants is', '["thallophyta, schizophyta, bryophyta, pteridophyta and spermatophyta","<u>schizophyta, thallophyta, bryophyta, pteridophyta and spermatophyta</u>","pteridophyata, spermatophyta, thallophyta, schizophyta and bryophyta","bryophyta, pteridophyta, spermatophyta, thallophyta and schizophyta. Biolog www.myscho Download MySchoolGist JAMB CBT Software from https"]', 'schizophyta, thallophyta, bryophyta, pteridophyta and spermatophyta is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('comkk0mtraep969d9xux0oqk7', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Asa removed the abominable image his mother made for Asherah and burnt it at', null, '["the brook Cherith","the brook Kidron","Ramah","Tirzah."]', 1, 'Asa burnt it at the brook Kidron.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Asa removed the abominable image his mother made for Asherah and burnt it at', '["the brook Cherith","<u>the brook Kidron</u>","Ramah","Tirzah."]', '<u>The brook Kidron</u> (1 Kings 15:13).', '{"bold":[],"italic":[],"underline":["the brook Kidron"],"fillBlanks":[]}');
