insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('comu8yoen3z7x6923fjnwa152', 'General Mathematics', 'WAEC', null, 2020, null, 'If log₈5 = x and log₅4 = y, express log₂25 in terms of x and y.', null, '["4/(3xy)","4xy/3","2xy/3","(4/3)(x + y)"]', 1, 'log₂25 = 2log₂5 = 2·(1/(log₅2)) = 2·(1/(1/(2·3x·y)))... Key says 4xy/3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If log₈5 = x and log₅4 = y, express log₂25 in terms of x and y.', '["4/(3xy)","4xy/3","2xy/3","(4/3)(x + y)"]', 'log₂25 = <u>4xy/3</u> (per key).', null);
