insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('con90j9ww8v2mrdx1oyqojoxt', 'Chemistry', 'JAMB', null, 1991, null, 'CH3CH2CH2CH2Br + alc.KOH → CH3CH=CHCH3 + CH3CH2CH=CH2. The above reaction is an example of', null, '["dehydration","dehydrohalogenation","neutralization","a fission reaction"]', 1, 'Removal of HBr from an alkyl halide is dehydrohalogenation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'CH3CH2CH2CH2Br + alc.KOH → CH3CH=CHCH3 + CH3CH2CH=CH2. The above reaction is an example of', '["dehydration","dehydrohalogenation","neutralization","a fission reaction"]', '<u>Dehydrohalogenation</u> (removal of HBr).', '{"bold":[],"italic":[],"underline":["dehydrohalogenation"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cone4ajx9ly11hru5zqfph1xo', 'General Mathematics', 'JAMB', null, 2020, null, 'If AM of two numbers = 10, GM = 8, find HM.', null, '["6.4","7.2","8.5","9"]', 0, 'AM × HM = GM² → HM = 64/10 = 6.4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If AM of two numbers = 10, GM = 8, find HM.', '["6.4","7.2","8.5","9"]', 'HM = <u>6.4</u>.', '{"bold":[],"italic":[],"underline":["6.4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('coneiafwdb4inbb6iuzpc5mst', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'The seeds that fell among the thorns in the parable of the sower refer to people that heard the word of God but', null, '["the criticism of others quenched it","the cares of the world choked it","the evil one snatched it","had no faith to nurture it"]', 1, 'The cares of the world choked it.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The seeds that fell among the thorns in the parable of the sower refer to people that heard the word of God but', '["the criticism of others quenched it","<u>the cares of the world choked it</u>","the evil one snatched it","had no faith to nurture it"]', '<u>The cares of the world choked it</u> (Matthew 13:22).', '{"bold":[],"italic":[],"underline":["the cares of the world choked it"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('conn64r9jsvmr15sknoom1ld5', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'After the dedication of the Temple, Ezra studied the law of the LORD in order to', null, '["defend the Jews against the Babylonians","become the first judge in Jerusalem","enhance his prophetic status","teach His statutes and ordinances in Israel."]', 3, 'He studied the law to teach God''s statutes and ordinances in Israel.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'After the dedication of the Temple, Ezra studied the law of the LORD in order to', '["defend the Jews against the Babylonians","become the first judge in Jerusalem","enhance his prophetic status","<u>teach His statutes and ordinances in Israel.</u>"]', '<u>Teach His statutes and ordinances in Israel</u> (Ezra 7:10).', '{"bold":[],"italic":[],"underline":["teach His statutes and ordinances in Israel."],"fillBlanks":[]}');
