insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('conyy9rggll9139e6fryllnur', 'Chemistry', 'JAMB', null, 1987, null, 'Corrosion is exhibited by', null, '["iron only","electropositive metals","metals below hydrogen in the electrochemical series","all metals"]', 1, 'Electropositive metals (above hydrogen) corrode.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Corrosion is exhibited by', '["iron only","electropositive metals","metals below hydrogen in the electrochemical series","all metals"]', '<u>Electropositive metals</u> corrode.', '{"bold":[],"italic":[],"underline":["electropositive metals"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('coo2dv43ao6eo3ne6y6r8ebfc', 'Government', 'JAMB', null, 2020, null, 'A common feature of the earlier political parties in Nigeria was that they', null, '["were formed by the government","started as socio-cultural organizations","were backed by the colonialists.","were non-elitist in nature"]', 1, 'Earlier parties started as socio-cultural organizations.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A common feature of the earlier political parties in Nigeria was that they', '["were formed by the government","<u>started as socio-cultural organizations</u>","were backed by the colonialists.","were non-elitist in nature"]', '<u>Started as socio-cultural organizations</u>.', '{"bold":[],"italic":[],"underline":["started as socio-cultural organizations"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('coo9vycm4yei2q17y9iznc4cz', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the base b given that: 44_b = 61_(b+1).', null, '["5","6","7","8"]', 1, '4b + 4 = 6(b+1) + 1 = 6b + 7 → 2b = -3 → b = -1.5. No valid solution. Key says 6.', false, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Find the base b given that: 44_b = 61_(b+1).', '["5","6","7","8"]', '4b + 4 = 6b + 7 → <u>b = -1.5</u> (invalid, key says 6).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('coojjksst8ckof6ab7p5fzbvd', 'Government', 'JAMB', null, 2020, null, 'Judicial administration in respect of national code of conduct lies with the', null, '["Public Complaints Commission","Judicial Service Commission","Code of Conduct Bureau.","Code of Conduct Tribunal"]', 3, 'The Code of Conduct Tribunal handles judicial administration of the code of conduct.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Judicial administration in respect of national code of conduct lies with the', '["Public Complaints Commission","Judicial Service Commission","Code of Conduct Bureau.","<u>Code of Conduct Tribunal</u>"]', '<u>Code of Conduct Tribunal</u>.', '{"bold":[],"italic":[],"underline":["Code of Conduct Tribunal"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('coowf8369tcn73rfcv569xc05', 'Physics', 'JAMB', null, 1983, null, 'A train has an initial velocity of 44 m/s and an acceleration of –4 m/s². Its velocity after 10 seconds is', null, '["2 m/s","4 m/s","8 m/s","12 m/s","16 m/s"]', 1, 'v = u + at = 44 + (–4)(10) = 4 m/s.', true, '2026-10-11 21:26:45.728', '2026-10-11 21:26:45.728', null, null, null, 'A train has an initial velocity of 44 m/s and an acceleration of –4 m/s². Its velocity after 10 seconds is', '["2 m/s","4 m/s","8 m/s","12 m/s","16 m/s"]', 'v = u + at = 44 + (–4)(10) = 4 m/s.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cop5taeixvbctv4iwzv3ciuo2', 'Biology', 'JAMB', null, 2001, null, 'A tall plant crossed with a dwarf on produces offspring of which half are tall and half are dwarf what are the genotypes of the parents?', null, '["TT, TT","Tt, Tt","TT, tt","Tt, Tt"]', 1, 'Tt, Tt is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A tall plant crossed with a dwarf on produces offspring of which half are tall and half are dwarf what are the genotypes of the parents?', '["TT, TT","<u>Tt, Tt</u>","TT, tt","Tt, Tt"]', 'Tt, Tt is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('copjvwtwxbt906vida04ag1f3', 'Islamic Religious Studies', 'JAMB', null, 2020, null, '''Verily Allah has prescribed the best behavior with regard to everything ...'' The above quotation from Hadith 17 of an-Nawawi''s collection emphasizes the ethics of', null, '["Eating and drinking","slaughtering animals","behaving in public","matrimonial relations."]', 1, 'It emphasizes the ethics of slaughtering animals.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '''Verily Allah has prescribed the best behavior with regard to everything ...'' The above quotation from Hadith 17 of an-Nawawi''s collection emphasizes the ethics of', '["Eating and drinking","<u>slaughtering animals</u>","behaving in public","matrimonial relations."]', '<u>Slaughtering animals</u>.', '{"bold":[],"italic":[],"underline":["slaughtering animals"],"fillBlanks":[]}');
