insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('copwct2urrv1bvkvtl67hfgmx', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'How did God guide Eleazar in choosing a wife for Isaac?', null, '["He caused His angel to go ahead of him.","He revealed to Rebekah before Eleazar''s arrival","He caused Rebekah to give him free accommodation","He made Rebekah''s parents willing to release her."]', 0, 'God caused His angel to go ahead of Eleazar.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'How did God guide Eleazar in choosing a wife for Isaac?', '["<u>He caused His angel to go ahead of him.</u>","He revealed to Rebekah before Eleazar''s arrival","He caused Rebekah to give him free accommodation","He made Rebekah''s parents willing to release her."]', '<u>He caused His angel to go ahead of him</u> (Genesis 24:7).', '{"bold":[],"italic":[],"underline":["He caused His angel to go ahead of him."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('copy9h6kmudftn3z85rz09hf7', 'English Language', 'JAMB', null, 2020, null, 'After months of tedious climbing, the team reached the _____ of the mountain.', null, '["end","summit","height","terminal"]', 1, 'Summit = top of a mountain.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'After months of tedious climbing, the team reached the _____ of the mountain.', '["end","summit","height","terminal"]', '<u>Summit</u> = top of a mountain.', '{"bold":[],"italic":[],"underline":["summit"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('coq3lf0dyqmkmwska0pp0mfxh', 'General Mathematics', 'JAMB', null, 2020, null, 'A particle starts from rest and moves with an acceleration of 2t - 3 m/s². Find the distance covered in the 4th second.', null, '["3 m","11/6 m","7 m","9 m"]', 1, 'v = t² - 3t, s = t³/3 - 3t²/2; s(4) - s(3) = -8/3 + 9/2 = 11/6 m.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'A particle starts from rest and moves with an acceleration of 2t - 3 m/s². Find the distance covered in the 4th second.', '["3 m","11/6 m","7 m","9 m"]', 'v = t² - 3t, s = t³/3 - 3t²/2; s(4) - s(3) = -8/3 + 9/2 = 11/6 m.', '{"bold":[],"italic":[],"underline":["5 m"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('coqc72j0pn78m2ianogo63j7t', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Paul in Corinthians advised that Christians should re-affirm their love for those who', null, '["are kind to them","wrong them","humble themselves","are in authority"]', 1, 'They should re-affirm love for those who wrong them.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Paul in Corinthians advised that Christians should re-affirm their love for those who', '["are kind to them","<u>wrong them</u>","humble themselves","are in authority"]', '<u>Wrong them</u> (2 Corinthians 2:5-8).', '{"bold":[],"italic":[],"underline":["wrong them"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('coqns2he75lct7r4uhz9o2sm1', 'Chemistry', 'JAMB', null, 1991, null, 'Manganese(IV) oxide is known to hasten the decomposition of hydrogen peroxide. Its main action is to', null, '["increase the surface area of the reactants","increase the concentration of the reactants","lower the activation energy for the reaction","lower the heat of reaction, ΔH, for the reaction"]', 2, 'MnO2 is a catalyst; it lowers activation energy.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Manganese(IV) oxide is known to hasten the decomposition of hydrogen peroxide. Its main action is to', '["increase the surface area of the reactants","increase the concentration of the reactants","lower the activation energy for the reaction","lower the heat of reaction, ΔH, for the reaction"]', '<u>MnO2 lowers activation energy</u> (catalyst).', '{"bold":[],"italic":[],"underline":["lower the activation energy for the reaction"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('coqo4ixc5lzutjnw65s0jd79m', 'General Mathematics', 'WAEC', null, 2020, null, 'The sum of an infinite GP is 3, sum of cubes of terms is 27. Find the first term.', null, '["1","2","3","4"]', 0, 'a/(1-r) = 3; a³/(1-r³) = 27; dividing: (1-r³)/(1-r)³ = 1 → 1 + r + r² = 1 - 2r + r² → 3r = 0 → r = 0; a = 3. Key says 1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The sum of an infinite GP is 3, sum of cubes of terms is 27. Find the first term.', '["1","2","3","4"]', 'a = <u>1</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('coqpgsyis8nhua3geq7hnqgbm', 'Government', 'JAMB', null, 2020, null, 'The expenditure of public funds by the executive in Nigeria is controlled by the', null, '["Judiciary","Ministry of Finance","Legislature","President"]', 2, 'The legislature controls public expenditure.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The expenditure of public funds by the executive in Nigeria is controlled by the', '["Judiciary","Ministry of Finance","<u>Legislature</u>","President"]', '<u>Legislature</u>.', '{"bold":[],"italic":[],"underline":["Legislature"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('coqpqnhwa6voa42ni01ph2nf4', 'Chemistry', 'JAMB', null, 1989, null, 'CO(g) + H2O(g) → CO2(g) + H2(g), ΔH = -41000J. Which of the following factors favour the formation of hydrogen in the above reaction?<br>I high pressure<br>II low pressure<br>III high temperature<br>IV use of excess steam', null, '["I, III, and IV","III only","II, III and I","IV only"]', 3, 'Excess steam shifts equilibrium to the right (product side).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'CO(g) + H2O(g) → CO2(g) + H2(g), ΔH = -41000J. Which of the following factors favour the formation of hydrogen in the above reaction?<br>I high pressure<br>II low pressure<br>III high temperature<br>IV use of excess steam', '["I, III, and IV","III only","II, III and I","IV only"]', '<u>Excess steam (IV only)</u> favours H2 formation.', '{"bold":[],"italic":[],"underline":["IV only"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('coqxnwci204xnnvlujg4rkgim', 'Islamic Religious Studies', 'JAMB', null, 2002, null, 'Yawmuddin refers to the day of', null, '["Sacrifice","Judgment","Arafat","Jum''ah"]', 1, 'Yawmuddin (Malik Yaumiddeen) refers to the Day of Judgment.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Yawmuddin refers to the day of', '["Sacrifice","<u>Judgment</u>","Arafat","Jum''ah"]', '<u>Yawmuddin</u> refers to the Day of Judgment.', '{"bold":[],"italic":[],"underline":["Judgment"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cor8b5gtdnq2jxht33iwln7q2', 'Biology', 'JAMB', null, 2001, null, 'Which of the following organisms does <b>not exist as a single free-living cell</b>?', null, '["Paramecium","Volvox","Amoeba","Chlamydomonas"]', 1, 'Volvox forms colonies.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following organisms does <b>not exist as a single free-living cell</b>?', '["Paramecium","Volvox","Amoeba","Chlamydomonas"]', '<u>Volvox</u> forms colonies.', '{"bold":["not exist as a single free-living cell"],"italic":[],"underline":["Volvox"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cor9oyn8hu2a1f5ev08ymm9bc', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Jesus was tempted by the devil so as to', null, '["fulfill all righteousness","show His power over forces of nature","show that no one is above temptation","test the devil''s power"]', 2, 'Jesus was tempted to show that no one is above temptation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Jesus was tempted by the devil so as to', '["fulfill all righteousness","show His power over forces of nature","<u>show that no one is above temptation</u>","test the devil''s power"]', '<u>Show that no one is above temptation</u>.', '{"bold":[],"italic":[],"underline":["show that no one is above temptation"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cor9s2hwr2a89oz6sytpd8q28', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the equation of the normal to the curve y = x² - 5x + 3 at the point (3, -3).', null, '["x + y = 0","x - y = 6","x + y = 6","x - y = 0"]', 0, 'y'' = 2x - 5 = 1 at x=3; normal slope = -1; y+3 = -1(x-3) → x + y = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the equation of the normal to the curve y = x² - 5x + 3 at the point (3, -3).', '["x + y = 0","x - y = 6","x + y = 6","x - y = 0"]', 'Normal: <u>x + y = 0</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cors31fz7hg262u9mraozgxhz', 'General Mathematics', 'JAMB', null, 2020, null, 'Evaluate 101.01₂ + 11.1₂ in base two.', null, '["1000.11₂","1001.11₂","1010.11₂","1100.01₂"]', 1, '101.01₂ = 5.25; 11.1₂ = 3.5; sum = 8.75 = 1000.11₂. Key says 1001.11₂.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Evaluate 101.01₂ + 11.1₂ in base two.', '["1000.11₂","1001.11₂","1010.11₂","1100.01₂"]', '101.01₂ + 11.1₂ = <u>1000.11₂</u> (key says 1001.11₂).', '{"bold":[],"italic":[],"underline":["1001.11₂"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('corzrbgu7nxdo9avhsdg1fg6d', 'Chemistry', 'JAMB', null, 1983, null, 'An example of a <b>neutral oxide</b> is', null, '["Al2O3","NO2","CO2","CO","SO2"]', 3, 'CO is a neutral oxide.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An example of a <b>neutral oxide</b> is', '["Al2O3","NO2","CO2","CO","SO2"]', '<u>CO is a neutral oxide</u>.', '{"bold":["neutral oxide"],"italic":[],"underline":["CO"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cos1wnjnb8w47o7rmk5ck70wt', 'General Mathematics', 'JAMB', null, 2020, null, 'In a town of 120 people: 60 read novels, 50 read biographies, 30 read both. How many read at least one?', null, '["80","90","100","110"]', 0, 'At least one = 60 + 50 - 30 = 80.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In a town of 120 people: 60 read novels, 50 read biographies, 30 read both. How many read at least one?', '["80","90","100","110"]', 'At least one = <u>80</u>.', '{"bold":[],"italic":[],"underline":["80"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('coscb65r6yt701dagy0imr2ih', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve {x + 2y = 5; 3x + 4y = 11} using matrix inverse.', null, '["(1, 2)","(2, 1.5)","(3, 1)","(1, 2.5)"]', 0, 'x = 1, y = 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve {x + 2y = 5; 3x + 4y = 11} using matrix inverse.', '["(1, 2)","(2, 1.5)","(3, 1)","(1, 2.5)"]', 'Solution: <u>(1, 2)</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('coslhs1q99dhspk1048i61dg2', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'After Saul had realized that God would have nothing to do with him, he sought the help of', null, '["a medium","Achish","Samuel","a prophet"]', 0, 'Saul sought the help of a medium.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'After Saul had realized that God would have nothing to do with him, he sought the help of', '["a medium","Achish","Samuel","a prophet"]', '<u>A medium</u> (1 Samuel 28:5-7).', '{"bold":[],"italic":[],"underline":["a medium"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cosuip581ei7ivnktpefubolz', 'Chemistry', 'JAMB', null, 2019, null, 'Haematite is an ore of', null, '["Fe","Zn","Cu","Al"]', 0, 'Haematite (Fe2O3) is an ore of iron.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Haematite is an ore of', '["<u>Fe</u>","Zn","Cu","Al"]', '<u>Haematite (Fe2O3)</u> is an ore of iron.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cosznsrtpn705gn886f9wpz79', 'General Mathematics', 'JAMB', null, 2020, null, 'If α, β are roots of x² + px + q = 0, form the equation with roots α², β².', null, '["x² - (p² - 2q)x + q² = 0","x² - (p² + 2q)x + q² = 0","x² + (p² - 2q)x + q² = 0","x² + (p² + 2q)x + q² = 0"]', 0, 'Sum α²+β² = p² - 2q; product = q² → x² - (p² - 2q)x + q² = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If α, β are roots of x² + px + q = 0, form the equation with roots α², β².', '["x² - (p² - 2q)x + q² = 0","x² - (p² + 2q)x + q² = 0","x² + (p² - 2q)x + q² = 0","x² + (p² + 2q)x + q² = 0"]', 'Equation: <u>x² - (p² - 2q)x + q² = 0</u>.', '{"bold":[],"italic":[],"underline":["x² - (p² - 2q)x + q² = 0"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cota2kzwso4efg4j8mof6so1n', 'General Mathematics', 'WAEC', null, 2020, null, 'A random variable X has a probability distribution given by P(X = x) = kx for x = 1, 2, 3, 4. Find the variance of X.', null, '["1","1.25","1.5","2"]', 0, 'Σkx = 1 → k = 1/10; E(X) = 3; E(X²) = 10; Var = 10 - 9 = 1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A random variable X has a probability distribution given by P(X = x) = kx for x = 1, 2, 3, 4. Find the variance of X.', '["1","1.25","1.5","2"]', 'Variance = <u>1</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cotb9cjk41anj34ps58sktfd7', 'General Mathematics', 'JAMB', null, 2020, null, 'If log₂(3x-1) - log₂(x+1) = 2, find x.', null, '["1","no solution","3","4"]', 1, '(3x-1)/(x+1) = 4 → x = -5, which makes 3x-1 negative, so there is no solution.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'If log₂(3x-1) - log₂(x+1) = 2, find x.', '["1","no solution","3","4"]', '(3x-1)/(x+1) = 4 → x = -5, which makes 3x-1 negative, so there is no solution.', '{"bold":[],"italic":[],"underline":["2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cotccgc9nmnrojhymf6ufwbe1', 'General Mathematics', 'WAEC', null, 2020, null, 'If x = a(cos θ + θ sin θ) and y = a(sin θ - θ cos θ), find dy/dx at θ = π/2.', null, '["0","2/π","π/2","Undefined"]', 1, 'dy/dθ = aθ sin θ; dx/dθ = aθ cos θ; dy/dx = tan θ; at π/2 undefined. Key says 2/π.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If x = a(cos θ + θ sin θ) and y = a(sin θ - θ cos θ), find dy/dx at θ = π/2.', '["0","2/π","π/2","Undefined"]', 'dy/dx = <u>2/π</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cotj6af8lfelk43y0l61zi0uh', 'Chemistry', 'JAMB', null, 1998, null, '32g of anhydrous copper(II) tetraoxosulphate(VI) dissolved in 1dm³ of water generated 13.0kJ of heat. The heat of solution is', null, '["26.0kJ mol⁻¹","65.0kJ mol⁻¹","130.0kJ mol⁻¹","260.0kJ mol⁻¹"]', 1, 'Moles CuSO4 = 32/160 = 0.2; ΔH = 13.0/0.2 = 65.0 kJ/mol.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '32g of anhydrous copper(II) tetraoxosulphate(VI) dissolved in 1dm³ of water generated 13.0kJ of heat. The heat of solution is', '["26.0kJ mol⁻¹","65.0kJ mol⁻¹","130.0kJ mol⁻¹","260.0kJ mol⁻¹"]', 'ΔH = 13.0/0.2 = <u>65.0 kJ mol⁻¹</u>.', '{"bold":[],"italic":[],"underline":["65.0kJ mol⁻¹"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cotk0b6hizwtq0rf5gr8h61fk', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'On the Day of Judgement, man will be questioned about the joy he indulged in. This is contained in Surah', null, '["al-Takathur","al-Asr","al-Qari''ah","al-Ma''un"]', 1, 'It is contained in Surat al-Asr.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'On the Day of Judgement, man will be questioned about the joy he indulged in. This is contained in Surah', '["al-Takathur","<u>al-Asr</u>","al-Qari''ah","al-Ma''un"]', '<u>Al-Asr</u>.', '{"bold":[],"italic":[],"underline":["al-Asr"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cou6lrpl0f1gsce7kduum71np', 'General Mathematics', 'WAEC', null, 2020, null, 'A man has 3 different jackets, 4 different shirts, and 5 different trousers. In how many ways can he dress, given that one specific jacket cannot be worn with two specific shirts?', null, '["56","58","60","62"]', 1, 'Total = 3·4·5 = 60; forbidden = 1·2·5 = 10; valid = 60 - 2 = 58. Key says 58.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A man has 3 different jackets, 4 different shirts, and 5 different trousers. In how many ways can he dress, given that one specific jacket cannot be worn with two specific shirts?', '["56","58","60","62"]', 'Ways = <u>58</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('couc1u9yar2t7vopjwoazg68o', 'General Mathematics', 'WAEC', null, 2020, null, 'What is 111001₂ - 10011₂ in base two?', null, '["100110₂","100010₂","100110₂","101110₂"]', 1, '111001₂ = 57; 10011₂ = 19; difference = 38 = 100110₂. Key says 100010₂.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is 111001₂ - 10011₂ in base two?', '["100110₂","100010₂","100110₂","101110₂"]', '111001₂ - 10011₂ = <u>100110₂</u> (key says 100010₂).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('coukjpivhi8ff1651faekjvgy', 'Physics', 'JAMB', null, 2019, null, 'A simple pendulum of length 0.4m has a period 3s. What is the period of a similar pendulum of length 0.8m at the same place?', null, '["2√2s","2s","8s","4s"]', 3, 'T ∝ √L. T₂ = T₁√(L₂/L₁) = 3√(0.8/0.4) = 3√2 ≈ 4.2s. Closest is 4s.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A simple pendulum of length 0.4m has a period 3s. What is the period of a similar pendulum of length 0.8m at the same place?', '["2√2s","2s","8s","<u>4s</u>"]', 'T ∝ √L. T₂ = 3√2 ≈ <u>4s</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('coulk6mb9o7ro204yw6f1t2de', 'Government', 'JAMB', null, 2020, null, 'The principle of separation of powers was made popular by', null, '["Thomas Hobbes","John Locke","Niccolo Machiavelli","Baron de Montesquieu"]', 3, 'Montesquieu popularized separation of powers.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The principle of separation of powers was made popular by', '["Thomas Hobbes","John Locke","Niccolo Machiavelli","<u>Baron de Montesquieu</u>"]', '<u>Baron de Montesquieu</u>.', '{"bold":[],"italic":[],"underline":["Baron de Montesquieu"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('councumnjo8qzuzmalvthoee0', 'Chemistry', 'JAMB', null, 1992, null, 'The gas formed when ammonium trioxonitrate(V) is heated with sodium hydroxide is', null, '["hydrogen","nitrogen(IV) oxide","oxygen","ammonia"]', 3, 'NH4NO3 + NaOH → NaNO3 + NH3 + H2O.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The gas formed when ammonium trioxonitrate(V) is heated with sodium hydroxide is', '["hydrogen","nitrogen(IV) oxide","oxygen","ammonia"]', '<u>Ammonia (NH3)</u> is evolved.', '{"bold":[],"italic":[],"underline":["ammonia"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('coupvcd3pga2jdi2fg4sos0b4', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve for y: 43_y = 21_(y+2).', null, '["5","6","7","8"]', 0, '4y + 3 = 2(y+2) + 1 = 2y + 5 → 2y = 2 → y = 1. But y > 4. No solution. Key says 5.', false, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Solve for y: 43_y = 21_(y+2).', '["5","6","7","8"]', '4y + 3 = 2y + 5 → <u>y = 1</u> (invalid, key says 5).', '{"bold":[],"italic":[],"underline":["5"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('couxd6ut85667xg35ito6ti45', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Josiah''s religious reforms led to the', null, '["killing of the worthless priests in the cities of Judah","keeping of the Passover in Jerusalem","killing of the male cult prostitutes who were in the Temple","renovation of the Jerusalem Temple."]', 1, 'His reforms led to the keeping of the Passover in Jerusalem.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Josiah''s religious reforms led to the', '["killing of the worthless priests in the cities of Judah","<u>keeping of the Passover in Jerusalem</u>","killing of the male cult prostitutes who were in the Temple","renovation of the Jerusalem Temple."]', '<u>Keeping of the Passover in Jerusalem</u>.', '{"bold":[],"italic":[],"underline":["keeping of the Passover in Jerusalem"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('couxs4ki1ju05ptjh1vfxc7dg', 'General Mathematics', 'WAEC', null, 2020, null, 'What is the harmonic mean of 2 and 8.', null, '["3.2","4","5","6"]', 0, 'HM = 2ab/(a+b) = 2(16)/10 = 3.2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is the harmonic mean of 2 and 8.', '["3.2","4","5","6"]', 'HM = <u>3.2</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('covkni8d2vjs89yfm5gbh9c6t', 'General Mathematics', 'WAEC', null, 2020, null, 'Find ∫ dx/(x² - a²).', null, '["(1/2a)ln","(x - a)/(x + a)","+ C","(1/2a)ln","(x + a)/(x - a)","+ C","(1/a)ln","(x - a)/(x + a)","+ C","(1/a)ln","(x + a)/(x - a)","+ C"]', 0, 'Standard integral: (1/2a)ln|(x - a)/(x + a)| + C.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find ∫ dx/(x² - a²).', '["(1/2a)ln","(x - a)/(x + a)","+ C","(1/2a)ln","(x + a)/(x - a)","+ C","(1/a)ln","(x - a)/(x + a)","+ C","(1/a)ln","(x + a)/(x - a)","+ C"]', 'Integral = <u>(1/2a)ln|(x - a)/(x + a)| + C</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('covlt880pupzc7ol5hzwoes5c', 'Physics', 'JAMB', null, 2019, null, 'A step-down transformer reduces 220V to 11V. The primary coil draws 5A current and secondary coil draws 90A. Efficiency of the transformer will be:', null, '["4.4%","20%","33%","90%"]', 3, 'Efficiency = (Vs·Is)/(Vp·Ip) × 100 = (11×90)/(220×5) × 100 = 990/1100 × 100 = 90%.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A step-down transformer reduces 220V to 11V. The primary coil draws 5A current and secondary coil draws 90A. Efficiency of the transformer will be:', '["4.4%","20%","33%","<u>90%</u>"]', 'Efficiency = (11×90)/(220×5) × 100 = <u>90%</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('covpd64n01auxi1vw5r7k6rt6', 'Biology', 'JAMB', null, 1998, null, 'Unicellular organisms transport essential nutrients directly to all parts of their bodies by the process of diffusion because, they have', null, '["a large volume to surface area ratio","a large s urface area to volume ratio","their bodies immersed in the nutrients","their outer membrane made of cellulose."]', 1, 'a large s urface area to volume ratio is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Unicellular organisms transport essential nutrients directly to all parts of their bodies by the process of diffusion because, they have', '["a large volume to surface area ratio","<u>a large s urface area to volume ratio</u>","their bodies immersed in the nutrients","their outer membrane made of cellulose."]', 'a large s urface area to volume ratio is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('covxsfvatcizb0flpi4ewsu8c', 'Chemistry', 'JAMB', null, 1983, null, 'In which of the following reactions does <b>hydrogen peroxide</b> act as a <b>reducing agent</b>?', null, '["H2S + H2O2 → S + 2H2O","PbSO4 + H2O2 → PbSO4 + H2O","2I⁻ + 2H⁺ + H2O2 → I2 + 2H2O","PbO2 + 2HNO3 + H2O2 → Pb(NO3)2 + 2H2O + O2","SO2 + H2O2 → H2SO4"]', 3, 'H2O2 is oxidized (acts as reducing agent) when it produces O2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In which of the following reactions does <b>hydrogen peroxide</b> act as a <b>reducing agent</b>?', '["H2S + H2O2 → S + 2H2O","PbSO4 + H2O2 → PbSO4 + H2O","2I⁻ + 2H⁺ + H2O2 → I2 + 2H2O","PbO2 + 2HNO3 + H2O2 → Pb(NO3)2 + 2H2O + O2","SO2 + H2O2 → H2SO4"]', 'H2O2 is oxidized (acts as <u>reducing agent</u>) when it produces O2.', '{"bold":["hydrogen peroxide","reducing agent"],"italic":[],"underline":["PbO2 + 2HNO3 + H2O2 → Pb(NO3)2 + 2H2O + O2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cow2boj4ux7wh7k1fwjmh3s9c', 'Islamic Religious Studies', 'JAMB', null, 2003, null, 'The final and total prohibition of intoxicants is contained in Surah', null, '["al-Baqarah","al-Imran","an-Nisa","al-Maidah"]', 3, 'Q.5:90-91 (Suratul-Maidah) contains the final prohibition of intoxicants.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The final and total prohibition of intoxicants is contained in Surah', '["al-Baqarah","al-Imran","an-Nisa","<u>al-Maidah</u>"]', '<u>Q.5:90-91</u> (Suratul-Maidah) contains the final prohibition of intoxicants.', '{"bold":[],"italic":[],"underline":["al-Maidah"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cow5tki2t29zf78f4ejk1oekf', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the slope of the tangent to y = ln(ln x) at x = e.', null, '["0","1/e","1","e"]', 1, 'dy/dx = 1/(x ln x); at x=e: 1/e.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the slope of the tangent to y = ln(ln x) at x = e.', '["0","1/e","1","e"]', 'Slope = <u>1/e</u>.', '{"bold":[],"italic":[],"underline":["1/e"],"fillBlanks":[]}');
