insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cowjgiphbg2w95yj51dio22wg', 'Government', 'JAMB', null, 2020, null, 'A political party is different from a pressure group in its', null, '["Strategy","Source of finance","Objective","Organization"]', 2, 'Political parties differ from pressure groups in objective.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A political party is different from a pressure group in its', '["Strategy","Source of finance","<u>Objective</u>","Organization"]', '<u>Objective</u>.', '{"bold":[],"italic":[],"underline":["Objective"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cowniniooovw1wkl1dpld1jcm', 'Chemistry', 'JAMB', null, 1989, null, 'Bleaching powder, CaOCl2·H2O, deteriorates on exposure to air because', null, '["it loses its water of crystallization","atmospheric nitrogen displaces chlorine from it","carbon(IV) oxide of the atmosphere displaces chlorine from it","bleaching agents should be stored in solution"]', 2, 'CO2 in air displaces chlorine from bleaching powder.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Bleaching powder, CaOCl2·H2O, deteriorates on exposure to air because', '["it loses its water of crystallization","atmospheric nitrogen displaces chlorine from it","carbon(IV) oxide of the atmosphere displaces chlorine from it","bleaching agents should be stored in solution"]', '<u>CO2 displaces chlorine</u> from bleaching powder.', '{"bold":[],"italic":[],"underline":["carbon(IV) oxide of the atmosphere displaces chlorine from it"],"fillBlanks":[]}');
