insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cox2esbx6ecfbwug7akilms6j', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Which of the following books was written by Ibn Sina?', null, '["Kitab al-Hayawan","Al-Bayan wa at-Tabyin","Ihya'' as-Sunnah","Al-Qanun fi at-Tibb."]', 3, 'Al-Qanun fi at-Tibb was written by Ibn Sina.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following books was written by Ibn Sina?', '["Kitab al-Hayawan","Al-Bayan wa at-Tabyin","Ihya'' as-Sunnah","<u>Al-Qanun fi at-Tibb.</u>"]', '<u>Al-Qanun fi at-Tibb</u>.', '{"bold":[],"italic":[],"underline":["Al-Qanun fi at-Tibb."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('coxdm6q9ey9w96g8iiveo4xdp', 'General Mathematics', 'JAMB', null, 2020, null, 'If A³ = 0, find (I - A)⁻¹.', null, '["I + A + A²","I - A + A²","I - A","I + A"]', 0, '(I-A)(I+A+A²) = I - A³ = I.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If A³ = 0, find (I - A)⁻¹.', '["I + A + A²","I - A + A²","I - A","I + A"]', '(I - A)⁻¹ = <u>I + A + A²</u>.', '{"bold":[],"italic":[],"underline":["I + A + A²"],"fillBlanks":[]}');
