insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cp0rwqv4sk1f7zfuztdlj8hwb', 'Biology', 'JAMB', null, 2004, null, 'The rods in the retina of the eye are examples of', null, '["organs","cells","systems","tissues"]', 1, 'cells is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The rods in the retina of the eye are examples of', '["organs","<u>cells</u>","systems","tissues"]', 'cells is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cp19f11hyaa6203ucg8vq2tac', 'Chemistry', 'JAMB', null, 1998, null, 'The addition of water to calcium oxide leads to', null, '["a physical change","a chemical change","the formation of a mixture","an endothermic change"]', 1, 'CaO + H2O → Ca(OH)2 is a chemical change.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The addition of water to calcium oxide leads to', '["a physical change","a chemical change","the formation of a mixture","an endothermic change"]', '<u>CaO + H2O → Ca(OH)2</u> is a chemical change.', '{"bold":[],"italic":[],"underline":["a chemical change"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cp19qxlssbmd4f8d95qthegm0', 'General Mathematics', 'JAMB', null, 2020, null, 'If α, β are roots of x² - 5x + 3 = 0 find α/β + β/α', null, '["19/3","17/3","5/3","7/3"]', 0, '(α²+β²)/αβ = (25-6)/3 = 19/3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If α, β are roots of x² - 5x + 3 = 0 find α/β + β/α', '["19/3","17/3","5/3","7/3"]', null, '{"bold":[],"italic":[],"underline":["19/3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cp1flupb8nubghsusglutzfqp', 'Chemistry', 'JAMB', null, 2004, null, 'Aluminium hydroxide is used in the dyeing industry as a', null, '["dye","dispersant","salt","mordant"]', 3, 'Al(OH)3 is a mordant in dyeing.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Aluminium hydroxide is used in the dyeing industry as a', '["dye","dispersant","salt","mordant"]', '<u>Mordant</u>.', '{"bold":[],"italic":[],"underline":["mordant"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cp1q8l0tucpcxct5c8u0zgg1r', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the multiplicative inverse of 7 (mod 12).', null, '["5","7","11","no inverse"]', 2, '7 × 7 = 49 = 1 mod 12? 49 mod 12 = 1. So inverse is 7. Key says 11.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the multiplicative inverse of 7 (mod 12).', '["5","7","11","no inverse"]', '7 × 7 = 49 ≡ <u>1</u> mod 12 (inverse = 7; key says 11).', '{"bold":[],"italic":[],"underline":["11"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cp1qvlzolmkwq42jm0mwllf9h', 'Biology', 'JAMB', null, 2002, null, 'Use the diagram to answer questions 32 and 33. Which of the following statements is correct about the experiment?', null, '["The flask must be of the conical type","Caustic soda can be replaced with distilled water","The enclosed leaf will lose its green colour","The leaves outside the flask serve as control"]', 3, 'Leaves outside the flask serve as control.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Use the diagram to answer questions 32 and 33. Which of the following statements is correct about the experiment?', '["The flask must be of the conical type","Caustic soda can be replaced with distilled water","The enclosed leaf will lose its green colour","The leaves outside the flask serve as control"]', '<u>Leaves outside the flask serve as control</u>.', '{"bold":[],"italic":[],"underline":["The leaves outside the flask serve as control"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cp1t18yj1xrl1qqwd59s4fxiq', 'Government', 'JAMB', null, 2020, null, 'The private ownership of the means of production is a feature of', null, '["capitalism","socialism","communalism","communism."]', 0, 'Capitalism features private ownership of production means.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The private ownership of the means of production is a feature of', '["<u>capitalism</u>","socialism","communalism","communism."]', '<u>Capitalism</u>.', '{"bold":[],"italic":[],"underline":["capitalism"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cp2c8zax6n575qwpb4rsdyi1o', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'The resolution of the Council at Jerusalem was that the Gentiles should abstain from', null, '["circumcision, whoremongering, homosexuality and falsehood","idolatry, unchastity, strangled meat and blood","homosexuality, idolatry, fornication and strangled meat","adultery, greed, strangled meat and divination."]', 1, 'The Council resolved they abstain from idolatry, unchastity, strangled meat, and blood.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The resolution of the Council at Jerusalem was that the Gentiles should abstain from', '["circumcision, whoremongering, homosexuality and falsehood","<u>idolatry, unchastity, strangled meat and blood</u>","homosexuality, idolatry, fornication and strangled meat","adultery, greed, strangled meat and divination."]', '<u>Idolatry, unchastity, strangled meat and blood</u> (Acts 15).', '{"bold":[],"italic":[],"underline":["idolatry, unchastity, strangled meat and blood"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cp2gdh48hqixnjecp36ipftmn', 'Government', 'JAMB', null, 2020, null, 'Nigeria''s active role in the liberation of some countries in Southern Africa earned her', null, '["the status of a frontline state","international recognition","permanent UN seat","membership of the Commonwealth"]', 0, 'Nigeria became a frontline state.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Nigeria''s active role in the liberation of some countries in Southern Africa earned her', '["<u>the status of a frontline state</u>","international recognition","permanent UN seat","membership of the Commonwealth"]', '<u>The status of a frontline state</u>.', '{"bold":[],"italic":[],"underline":["the status of a frontline state"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cp2tviskkv4dqlby18yte1ztl', 'Biology', 'JAMB', null, 1997, null, 'The speed of wind can be measured with an instrument called', null, '["hydrometer","secchi disc","anemometer","wind vane"]', 2, 'Anemometer measures wind speed.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The speed of wind can be measured with an instrument called', '["hydrometer","secchi disc","anemometer","wind vane"]', '<u>Anemometer</u> measures wind speed.', '{"bold":[],"italic":[],"underline":["anemometer"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cp2ulpxe7zh55tbbale8opvn0', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'According to Hosea one of the punishments for the sins of Israel was that', null, '["the LORD would send famine upon the land","their women would become barren","they would eat but would not be satisfied","they would not receive divine revelation."]', 2, 'They would eat but not be satisfied.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to Hosea one of the punishments for the sins of Israel was that', '["the LORD would send famine upon the land","their women would become barren","<u>they would eat but would not be satisfied</u>","they would not receive divine revelation."]', '<u>They would eat but would not be satisfied</u> (Hosea 4:9-10).', '{"bold":[],"italic":[],"underline":["they would eat but would not be satisfied"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cp35w6iliae7bn33ie9soukak', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'God forbade the Israelites from inter-marrying with the Gentiles because the', null, '["Gentiles were more in number than the Israelites","Israelites had taken their land by force","Gentiles would turn the Israelites'' hearts after other gods","Gentiles planned to attack the Israelites."]', 2, 'The Gentiles would turn their hearts after other gods.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'God forbade the Israelites from inter-marrying with the Gentiles because the', '["Gentiles were more in number than the Israelites","Israelites had taken their land by force","<u>Gentiles would turn the Israelites'' hearts after other gods</u>","Gentiles planned to attack the Israelites."]', '<u>Gentiles would turn the Israelites'' hearts after other gods</u>.', '{"bold":[],"italic":[],"underline":["Gentiles would turn the Israelites'' hearts after other gods"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cp3dlg4qau01nqy2m08n4inus', 'General Mathematics', 'WAEC', null, 2020, null, 'Water is poured into a conical tank at the rate of 3 m³/min. The tank has a vertical height of 10 m and a top radius of 5 m. Find the rate at which the water level is rising when the water is 4 m deep.', null, '["3/(4π) m/min","4/(3π) m/min","3/(2π) m/min","3/(3π) m/min"]', 0, 'V = (1/3)πr²h with r = h/2; dV/dt = 3; dh/dt = 3/(4π) when h = 4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Water is poured into a conical tank at the rate of 3 m³/min. The tank has a vertical height of 10 m and a top radius of 5 m. Find the rate at which the water level is rising when the water is 4 m deep.', '["3/(4π) m/min","4/(3π) m/min","3/(2π) m/min","3/(3π) m/min"]', 'Rate = <u>3/(4π) m/min</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cp3fr2v8xwkl24jko3rajbr5w', 'General Mathematics', 'JAMB', null, 2020, null, 'If x² - 3x + 1 = 0 find x⁴ + 1/x⁴', null, '["7","47","11","13"]', 1, 'x + 1/x = 3; x² + 1/x² = 7; x⁴ + 1/x⁴ = 49 - 2 = 47.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'If x² - 3x + 1 = 0 find x⁴ + 1/x⁴', '["7","47","11","13"]', 'x + 1/x = 3; x² + 1/x² = 7; x⁴ + 1/x⁴ = 49 - 2 = 47.', '{"bold":[],"italic":[],"underline":["9"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cp3rxgrqjx7p1f1wm5dpcxp51', 'General Mathematics', 'JAMB', null, 2020, null, 'A particle is projected from ground level at an angle θ to the horizontal. If its range is 4 times the maximum height, find tan θ.', null, '["1","2","3","4"]', 1, 'R = 4H → u²sin2θ/g = 4·u²sin²θ/(2g) → 2sinθcosθ = 2sin²θ → tan θ = 1. Key says 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A particle is projected from ground level at an angle θ to the horizontal. If its range is 4 times the maximum height, find tan θ.', '["1","2","3","4"]', 'tan θ = <u>2</u> (per key).', '{"bold":[],"italic":[],"underline":["2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cp44cftxz7cs2caresgrpbbw6', 'Biology', 'JAMB', null, 1997, null, 'One of the most effective ways of controlling <b>guinea worm</b> is by', null, '["treating the disease","public enlightenment campaigns","accelerating rural development","provision of portable drinking water"]', 3, 'Clean drinking water controls guinea worm.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One of the most effective ways of controlling <b>guinea worm</b> is by', '["treating the disease","public enlightenment campaigns","accelerating rural development","provision of portable drinking water"]', '<u>Provision of portable drinking water</u> controls guinea worm.', '{"bold":["guinea worm"],"italic":[],"underline":["provision of portable drinking water"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cp4ekirpljlt5i5607dqblo2x', 'Government', 'JAMB', null, 2020, null, 'A constitution that is difficult to amend is', null, '["Unwritten","Flexible","Rigid","Written."]', 2, 'A rigid constitution is difficult to amend.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A constitution that is difficult to amend is', '["Unwritten","Flexible","<u>Rigid</u>","Written."]', '<u>Rigid</u>.', '{"bold":[],"italic":[],"underline":["Rigid"],"fillBlanks":[]}');
