insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cp4o88ealvkc35x5k0l6kf23a', 'General Mathematics', 'JAMB', null, 2020, null, 'What is the value of: 1/0.01 + 1/0.001 - 1/0.0001', null, '["-100","0","100","-8900"]', 3, '100 + 1000 - 10000 = -8900.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'What is the value of: 1/0.01 + 1/0.001 - 1/0.0001', '["-100","0","100","-8900"]', '100 + 1000 - 10000 = -8900.', '{"bold":[],"italic":[],"underline":["1000"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cp4rnvudx0vt7igzpmd3l0rh8', 'Biology', 'JAMB', null, 1998, null, 'The nucleus is considered the control organelle of a cell because it', null, '["contains the genetic material","contains the nuclear sap","is bounded by the nuclear membrane","is located at the centre of the cell."]', 0, 'The nucleus controls cell activities and contains the cell''s genetic material.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The nucleus is considered the control organelle of a cell because it', '["<u>contains the genetic material</u>","contains the nuclear sap","is bounded by the nuclear membrane","is located at the centre of the cell."]', 'The nucleus controls cell activities and contains the cell''s genetic material.', null);
