insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpfmc5qotx4u9yeg942aggcdr', 'Biology', 'JAMB', null, 1995, null, 'Which of the following does a virus have in common with animal cells?', null, '["Nucleus","DNA","Glycogen","Cytoplasm."]', 1, 'Viruses contain genetic material such as DNA, but they do not have a cellular nucleus or cytoplasm.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following does a virus have in common with animal cells?', '["Nucleus","<u>DNA</u>","Glycogen","Cytoplasm."]', 'Viruses contain genetic material such as DNA, but they do not have a cellular nucleus or cytoplasm.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpfsokyqh22h7qefo585wabvy', 'Biology', 'JAMB', null, 1997, null, 'After a heavy rainfall and the formation of a large pond, the most likely sequence of changes in the vegetation of the pond is', null, '["Euglena- water lily –Spirogyra-grass","water lily – Spirogyra grass – Euglena","Spirogyra – Euglena – grass – water lily","Euglena – Spirogyra – water lily – grass."]', 3, 'Euglena – Spirogyra – water lily – grass. is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'After a heavy rainfall and the formation of a large pond, the most likely sequence of changes in the vegetation of the pond is', '["Euglena- water lily –Spirogyra-grass","water lily – Spirogyra grass – Euglena","Spirogyra – Euglena – grass – water lily","<u>Euglena – Spirogyra – water lily – grass.</u>"]', 'Euglena – Spirogyra – water lily – grass. is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpfwso4uunxb68pcxm5csht98', 'Biology', 'JAMB', null, 1984, null, 'Which of the following cell constituents is NOT common in both plants and animals?', null, '["Mitochondria","Chloroplasts","Ribosomes","Golgi apparatus","Vacoules"]', 1, 'Chloroplasts are found only in plant cells.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following cell constituents is <b>NOT</b> common in both plants and animals?', '["Mitochondria","<u>Chloroplasts</u>","Ribosomes","Golgi apparatus","Vacoules"]', '<u>Chloroplasts</u> are found only in plant cells.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpg0qx5peljrds7smo8t4yfss', 'Biology', 'JAMB', null, 1992, null, 'In the absence of oxygen, the pyruvic acid produced during glycolysis is converted to CO2 and', null, '["water","glycerol","ethanol","citric acid"]', 2, 'In anaerobic respiration, pyruvic acid is converted to ethanol and CO2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the absence of oxygen, the pyruvic acid produced during glycolysis is converted to CO2 and', '["water","glycerol","<u>ethanol</u>","citric acid"]', 'In anaerobic respiration, <u>pyruvic acid is converted to ethanol and CO2</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpg4xwk81y2356bu66pwamycy', 'Government', 'JAMB', null, 2020, null, 'A specialized agency of the United Nations Organization is the', null, '["International Court of Justice.","International Olympic Committee.","General Assembly","World Health Organization"]', 3, 'WHO is a specialized UN agency.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A specialized agency of the United Nations Organization is the', '["International Court of Justice.","International Olympic Committee.","General Assembly","<u>World Health Organization</u>"]', '<u>World Health Organization</u>.', '{"bold":[],"italic":[],"underline":["World Health Organization"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpg52shjjrd1umu10bgev1k88', 'Chemistry', 'JAMB', null, 2004, null, 'Carbon is <b>tetravalent</b> because', null, '["the 2s and 2p atomic orbitals hybridize","all the atomic orbitals of carbon hybridize","the electrons in all the orbitals of carbon are equivalent","the electrons in both the 2s and 2p orbitals are equivalent"]', 0, 'sp³ hybridization makes carbon tetravalent.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Carbon is <b>tetravalent</b> because', '["the 2s and 2p atomic orbitals hybridize","all the atomic orbitals of carbon hybridize","the electrons in all the orbitals of carbon are equivalent","the electrons in both the 2s and 2p orbitals are equivalent"]', '<u>2s and 2p orbitals hybridize</u> (sp³).', '{"bold":["tetravalent"],"italic":[],"underline":["the 2s and 2p atomic orbitals hybridize"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpg5i8ay5rgnepl3gevxrhz9w', 'Physics', 'JAMB', null, 1983, null, 'The difference of potential between the terminals of a cell is 2.2 volts. When a 4 ohm resistor is connected across the terminals of this cell, the potential difference is 2 volts. What is the internal resistance of the cell?', null, '["0.10 ohms","0.25 ohms","0.40 ohms","2.50 ohms","4.00 ohms"]', 2, 'I = 2/4 = 0.5 A; lost volts = 2.2 − 2 = 0.2 V; r = 0.2/0.5 = 0.40 Ω.', true, '2026-10-11 21:26:45.728', '2026-10-11 21:26:45.728', null, null, null, 'The difference of potential between the terminals of a cell is 2.2 volts. When a 4 ohm resistor is connected across the terminals of this cell, the potential difference is 2 volts. What is the internal resistance of the cell?', '["0.10 ohms","0.25 ohms","0.40 ohms","2.50 ohms","4.00 ohms"]', 'I = 2/4 = 0.5 A; lost volts = 2.2 − 2 = 0.2 V; r = 0.2/0.5 = 0.40 Ω.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpgeoclzbp2pynubr58nrgkiw', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'According to Paul, the purpose of the law is', null, '["to bring about justification by faith","the fulfillment of divine promises","to promote faith in the crucified Christ","to increase the knowledge of sin."]', 0, 'The law was our custodian until Christ came, that we might be justified by faith.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to Paul, the purpose of the law is', '["<u>to bring about justification by faith</u>","the fulfillment of divine promises","to promote faith in the crucified Christ","to increase the knowledge of sin."]', '<u>To bring about justification by faith</u> (Galatians 3:24).', '{"bold":[],"italic":[],"underline":["to bring about justification by faith"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpgmjak7meutegm2qr2rvsqbm', 'English Language', 'JAMB', null, 2020, null, 'If you keep playing with this door handle, it will get _____.', null, '["loose","lose","lost","loosing","loosed"]', 0, 'Loose = not firmly fixed (adjective).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If you keep playing with this door handle, it will get _____.', '["loose","lose","lost","loosing","loosed"]', '<u>Loose</u> = not firmly fixed.', '{"bold":[],"italic":[],"underline":["loose"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpgsq8d00a1vyocwwmudhbq80', 'General Mathematics', 'JAMB', null, 2020, null, 'Two vectors are given by p = 3i + 4j and q = 5i - 12j. Find the cosine of the angle between them.', null, '["33/65","-33/65","63/65","-63/65"]', 0, 'cos θ = (15-48)/(5·13) = -33/65. Key says 33/65.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Two vectors are given by p = 3i + 4j and q = 5i - 12j. Find the cosine of the angle between them.', '["33/65","-33/65","63/65","-63/65"]', 'cos θ = <u>33/65</u> (per key).', '{"bold":[],"italic":[],"underline":["33/65"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpgwsm250g59nciuy0uxnp7jo', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'The new commandment Jesus gave to His disciples was that they should', null, '["teach one another","lay down their lives for one another","comfort one another","love one another."]', 3, 'They should love one another.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The new commandment Jesus gave to His disciples was that they should', '["teach one another","lay down their lives for one another","comfort one another","<u>love one another.</u>"]', '<u>Love one another</u> (John 13:34).', '{"bold":[],"italic":[],"underline":["love one another."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cph2pmbfuly3cjjqz26ash1ob', 'General Mathematics', 'WAEC', null, 2020, null, 'If a, b, c, d are in GP, then (a - d)² = ?', null, '["(b - c)² + (c - a)² + (d - b)²","(b - c)² + (c - a)² + (d - a)²","(b + c)² + (a - d)²","(a + b)² - (c + d)²"]', 0, 'Identity for GP: (a-d)² = (b-c)² + (c-a)² + (d-b)².', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If a, b, c, d are in GP, then (a - d)² = ?', '["(b - c)² + (c - a)² + (d - b)²","(b - c)² + (c - a)² + (d - a)²","(b + c)² + (a - d)²","(a + b)² - (c + d)²"]', 'Identity holds.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cph9xhv7h946tkru4ltyqs7zv', 'Biology', 'JAMB', null, 2000, null, 'Use the diagram to answer questions 25 and 26. The part labelled II is the', null, '["mesocarp","pericarp","endocarp","epicarp"]', 1, 'Part II is the pericarp.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Use the diagram to answer questions 25 and 26. The part labelled II is the', '["mesocarp","pericarp","endocarp","epicarp"]', '<u>Part II is the pericarp</u>.', '{"bold":[],"italic":[],"underline":["pericarp"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cphq0ehon1zhpn9h7bisv228e', 'Biology', 'JAMB', null, 2001, null, 'Which of the following statements is true of blood groups and blood transfusion?', null, '["Group O is the universal recipient","Group A can donate to group A only","Group AB is the universal recipient","Group B can donate to group B only"]', 2, 'Group AB is the universal recipient is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following statements is true of blood groups and blood transfusion?', '["Group O is the universal recipient","Group A can donate to group A only","<u>Group AB is the universal recipient</u>","Group B can donate to group B only"]', 'Group AB is the universal recipient is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpic3b5jwcyout6cqf0lzojcg', 'Biology', 'JAMB', null, 2001, null, 'An association between the root nodule of a leguminous plant and <b>Rhizobium</b> sp is known as', null, '["commensalism","mycorrhiza","parasitism","symbiosis"]', 3, 'Rhizobium and legume roots form a symbiotic relationship.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An association between the root nodule of a leguminous plant and <b>Rhizobium</b> sp is known as', '["commensalism","mycorrhiza","parasitism","symbiosis"]', '<u>Symbiosis</u> (mutualism) between Rhizobium and legume.', '{"bold":["Rhizobium"],"italic":[],"underline":["symbiosis"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpiceq6r2hdz9hhe8nsvoehvu', 'Chemistry', 'JAMB', null, 1994, null, 'The solubility in moles per dm³ of 20.2g of potassium trioxonitrate(V) dissolved in 100g of water at room temperature is [K=39, O=16, N=14]', null, '["0.10","0.20","1.00","2.00"]', 1, 'Moles KNO3 = 20.2/101 = 0.2 in 0.1 dm³ → 2.0M. Key says 0.20.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The solubility in moles per dm³ of 20.2g of potassium trioxonitrate(V) dissolved in 100g of water at room temperature is [K=39, O=16, N=14]', '["0.10","0.20","1.00","2.00"]', 'Moles = 0.2 in 0.1 dm³ → <u>2.0M</u> (key says 0.20).', '{"bold":[],"italic":[],"underline":["0.20"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpijrik1jdopbvoi1bvve7ufq', 'Biology', 'JAMB', null, 1997, null, 'The companion cells are part of the', null, '["pericycle","phloem","pith","xylem"]', 1, 'Companion cells are in the phloem.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The companion cells are part of the', '["pericycle","phloem","pith","xylem"]', '<u>Companion cells are in the phloem</u>.', '{"bold":[],"italic":[],"underline":["phloem"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpj7u4p3dnlcmyr42190m1mvd', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the area bounded by the curves y = x² - 4 and y = 4 - x².', null, '["32/3","64/3","128/3","256/3"]', 1, 'Intersection at x = ±2; area = ∫(8 - 2x²)dx from -2 to 2 = 64/3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the area bounded by the curves y = x² - 4 and y = 4 - x².', '["32/3","64/3","128/3","256/3"]', 'Area = <u>64/3</u>.', '{"bold":[],"italic":[],"underline":["64/3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpj9f48wul5fqg21cmnogk5jh', 'Biology', 'JAMB', null, 1983, null, 'In the onion bulb, food is stored in the', null, '["stem","lateral buds","cotyledons","outer scale leaves","leaf bases"]', 4, 'Food is stored in the fleshy leaf bases of the onion bulb.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the onion bulb, food is stored in the', '["stem","lateral buds","cotyledons","outer scale leaves","<u>leaf bases</u>"]', 'Food is stored in the fleshy <u>leaf bases</u> of the onion bulb.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpjjqf6a6zm622vwufrmghfrl', 'Chemistry', 'JAMB', null, 1988, null, 'Chlorine is produced commercially by', null, '["electrolysis of dilute hydrochloric acid","electrolysis of brine","neutralization of hydrogen chloride","heating potassium trioxochlorate(V)"]', 1, 'Chlorine is produced commercially by electrolysis of brine.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Chlorine is produced commercially by', '["electrolysis of dilute hydrochloric acid","electrolysis of brine","neutralization of hydrogen chloride","heating potassium trioxochlorate(V)"]', '<u>Electrolysis of brine</u> produces chlorine commercially.', '{"bold":[],"italic":[],"underline":["electrolysis of brine"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpjocpgxflog4zif5x0rpfnxv', 'Chemistry', 'JAMB', null, 1999, null, 'Nitrogen obtained from the liquefaction of air has a higher density than that obtained from nitrogen containing compounds because the former contains', null, '["Water vapour","Oxygen","Carbon(IV) oxide","Rare gases"]', 1, 'Air-derived N2 contains some O2 (denser).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Nitrogen obtained from the liquefaction of air has a higher density than that obtained from nitrogen containing compounds because the former contains', '["Water vapour","Oxygen","Carbon(IV) oxide","Rare gases"]', '<u>Oxygen</u> contaminates air-derived nitrogen.', '{"bold":[],"italic":[],"underline":["Oxygen"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpkarfblsxknjma8seqed19lq', 'General Mathematics', 'JAMB', null, 2020, null, 'Evaluate ∫₀¹ dx/(1 + x²).', null, '["π/4","π/2","π/3","π/6"]', 0, 'tan⁻¹x from 0 to 1 = π/4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Evaluate ∫₀¹ dx/(1 + x²).', '["π/4","π/2","π/3","π/6"]', 'Integral = <u>π/4</u>.', '{"bold":[],"italic":[],"underline":["π/4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpkbor5zhr2lwyg5l3tmdhj3g', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'What did King Josiah do to the idolatrous priests of Judah?', null, '["He sent all of them on exile","He killed all of them","He demoted all of them","He deposed all of them"]', 3, 'Josiah deposed the idolatrous priests.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What did King Josiah do to the idolatrous priests of Judah?', '["He sent all of them on exile","He killed all of them","He demoted all of them","<u>He deposed all of them</u>"]', '<u>He deposed all of them</u> (2 Kings 23:5).', '{"bold":[],"italic":[],"underline":["He deposed all of them"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpklwj5g79g2xpvzzywk1ru5l', 'Government', 'JAMB', null, 2020, null, 'One of the duties of the legislature is to', null, '["implement laws","adjudicate disputes","promulgate decrees","exercise oversight"]', 3, 'The legislature exercises oversight over the executive.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One of the duties of the legislature is to', '["implement laws","adjudicate disputes","promulgate decrees","<u>exercise oversight</u>"]', '<u>Exercise oversight</u>.', '{"bold":[],"italic":[],"underline":["exercise oversight"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpl5ennmsuwanebbjykg6lqky', 'Chemistry', 'JAMB', null, 1986, null, 'What are the values of x, y and z respectively in the equation xCu + yHNO3 → xCu(NO3)2 + 4H2O + zNO?', null, '["4; 1; 2","3; 8; 2","2; 8; 3","8; 3; 2"]', 1, 'Balanced: 3Cu + 8HNO3 → 3Cu(NO3)2 + 4H2O + 2NO; x=3, y=8, z=2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What are the values of x, y and z respectively in the equation xCu + yHNO3 → xCu(NO3)2 + 4H2O + zNO?', '["4; 1; 2","3; 8; 2","2; 8; 3","8; 3; 2"]', '<u>3; 8; 2</u>.', '{"bold":[],"italic":[],"underline":["3; 8; 2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cplc4mbcx2fk431kpbiygupga', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'King Josiah ordered Shaphan, the secretary to the house of the LORD not to account for the money given to repair the Temple because', null, '["he wanted to benefit from it","the people were honest","the money was too small","much money was collected."]', 1, 'The people were honest.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'King Josiah ordered Shaphan, the secretary to the house of the LORD not to account for the money given to repair the Temple because', '["he wanted to benefit from it","<u>the people were honest</u>","the money was too small","much money was collected."]', '<u>The people were honest</u>.', '{"bold":[],"italic":[],"underline":["the people were honest"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpldn3p2n5egticzxnfk43jwd', 'Chemistry', 'JAMB', null, 2004, null, 'When steam is passed over red-hot carbon, the substances produced are', null, '["hydrogen and carbon(II) oxide","hydrogen and carbon(IV) oxide","hydrogen and trioxocarbonate(IV) acid","hydrogen, oxygen and carbon(IV) oxide"]', 0, 'C + H2O → CO + H2 (water gas).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When steam is passed over red-hot carbon, the substances produced are', '["hydrogen and carbon(II) oxide","hydrogen and carbon(IV) oxide","hydrogen and trioxocarbonate(IV) acid","hydrogen, oxygen and carbon(IV) oxide"]', '<u>Hydrogen and carbon(II) oxide</u>.', '{"bold":[],"italic":[],"underline":["hydrogen and carbon(II) oxide"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cplrwb8428wp27i6xda30i7tf', 'English Language', 'JAMB', null, 2020, null, 'I am looking forward _____ from you.', null, '["of hearing","to hear","for hearing","to hearing"]', 3, 'Look forward to + gerund → "to hearing".', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'I am looking forward _____ from you.', '["of hearing","to hear","for hearing","to hearing"]', 'Look forward to + gerund → <u>to hearing</u>.', '{"bold":[],"italic":[],"underline":["to hearing"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpls9883tiwml0o12tvmenazb', 'Biology', 'JAMB', null, 1988, null, 'If the gall bladder of a mammal is damaged, which of the following will be most seriously affected?', null, '["Glycolysis","Digestion of starch","Digestion of fats and oils","Digestion of proteins"]', 2, 'The gall bladder stores bile for fat digestion.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If the <b>gall bladder</b> of a mammal is damaged, which of the following will be most seriously affected?', '["Glycolysis","Digestion of starch","<u>Digestion of fats and oils</u>","Digestion of proteins"]', 'The gall bladder <u>stores bile for fat digestion</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cplwp2ia48l586c8khn637wco', 'General Mathematics', 'WAEC', null, 2020, null, 'If the binary operation * is defined on the set of real numbers by a*b = a + b + ab, find the inverse of 2 under this operation, if it exists.', null, '["-2/3","-3/2","2/3","3/2"]', 1, 'e = 0; 2*x = 0 → 2 + x + 2x = 0 → 3x = -2 → x = -2/3. Key says -3/2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If the binary operation * is defined on the set of real numbers by a*b = a + b + ab, find the inverse of 2 under this operation, if it exists.', '["-2/3","-3/2","2/3","3/2"]', 'Inverse = <u>-3/2</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cplyfgx12rr109g876g7h6g5a', 'English Language', 'JAMB', null, 2020, null, 'Didn''t _____ draw your attention to the entry requirements?', null, '["anyone","somebody","someone","everyone"]', 0, 'Negative question → "anyone".', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Didn''t _____ draw your attention to the entry requirements?', '["anyone","somebody","someone","everyone"]', 'Negative question → <u>anyone</u>.', '{"bold":[],"italic":[],"underline":["anyone"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpm070klg8nw0fgwor70s2qtx', 'Biology', 'JAMB', null, 2001, null, 'When yeast respires anaerobically, it converts simple sugar to carbon(IV) oxide and', null, '["oxygen","acid","alcohol","water"]', 2, 'Anaerobic respiration in yeast gives CO2 + ethanol (alcohol).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When yeast respires anaerobically, it converts simple sugar to carbon(IV) oxide and', '["oxygen","acid","alcohol","water"]', '<u>Alcohol (ethanol)</u>.', '{"bold":[],"italic":[],"underline":["alcohol"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpm2jxvdnqfoe9kmry28nccw7', 'Biology', 'JAMB', null, 2003, null, 'The presence of sunken stomata and the folding of leaves are adaptations to', null, '["prevent entry of pathogens","prevent guttation","remove excess water","reduce water loss"]', 3, 'Sunken stomata and folded leaves reduce water loss.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The presence of sunken stomata and the folding of leaves are adaptations to', '["prevent entry of pathogens","prevent guttation","remove excess water","reduce water loss"]', '<u>Reduce water loss</u>.', '{"bold":[],"italic":[],"underline":["reduce water loss"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpmb6pcik8x12zdv72tcjh65j', 'General Mathematics', 'JAMB', null, 2020, null, 'If sin θ + cos θ = 1/2, find |sin³θ - cos³θ|.', null, '["5/8","11/16","13/16","15/16"]', 1, 'sin θ cos θ = (1/4 - 1)/2 = -3/8; sin³θ - cos³θ = (sinθ - cosθ)(1 + sinθcosθ); sinθ-cosθ = ±√(1-2(-3/8)) = ±√7/2; result = ±11/16. Key says 11/16.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If sin θ + cos θ = 1/2, find |sin³θ - cos³θ|.', '["5/8","11/16","13/16","15/16"]', 'Value = <u>11/16</u>.', '{"bold":[],"italic":[],"underline":["11/16"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpmrza5gxd8xyl8r4mudk0lob', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'According to Paul in his letter to Philemon, forgiveness should not be by compulsion but by', null, '["free will","His grace","justification","faith"]', 0, 'Forgiveness should be by free will.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to Paul in his letter to Philemon, forgiveness should not be by compulsion but by', '["<u>free will</u>","His grace","justification","faith"]', '<u>Free will</u> (Philemon 1:14).', '{"bold":[],"italic":[],"underline":["free will"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpmsblerhvpunrs1in9i62bt4', 'Government', 'JAMB', null, 2020, null, 'The 1976 Reforms have been most beneficial to the', null, '["Nigeria Police.","federal government","local government","civil service"]', 2, 'The 1976 Reforms benefited local governments most.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The 1976 Reforms have been most beneficial to the', '["Nigeria Police.","federal government","<u>local government</u>","civil service"]', '<u>Local government</u>.', '{"bold":[],"italic":[],"underline":["local government"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpmw0cglbmbfa9y10728uwytc', 'General Mathematics', 'WAEC', null, 2020, null, 'A random variable X has mean 5 and variance 4. Find E(X²).', null, '["25","29","33","37"]', 1, 'E(X²) = Var(X) + (E(X))² = 4 + 25 = 29.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A random variable X has mean 5 and variance 4. Find E(X²).', '["25","29","33","37"]', 'E(X²) = <u>29</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpn3nw2q2a2uysfj2ev3vzqjp', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the moment about the point (2, 3, -1) of a force F = 3i - 2j + 4k acting through the point (1, -2, 3).', null, '["-13i - 5j - 11k","13i + 5j + 11k","13i - 5j + 11k","-13i + 5j - 11k"]', 0, 'r = (1-2)i + (-2-3)j + (3+1)k = -i - 5j + 4k; M = r × F = -13i - 5j - 11k.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the moment about the point (2, 3, -1) of a force F = 3i - 2j + 4k acting through the point (1, -2, 3).', '["-13i - 5j - 11k","13i + 5j + 11k","13i - 5j + 11k","-13i + 5j - 11k"]', 'Moment = <u>-13i - 5j - 11k</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpn4zh3m0u5773og3ow7gp52i', 'Government', 'JAMB', null, 2020, null, 'A group of people who live together under a common law within a definite territory is a', null, '["Nation","State","Community","Nation-state."]', 1, 'A state is a group living under common law in a definite territory.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A group of people who live together under a common law within a definite territory is a', '["Nation","<u>State</u>","Community","Nation-state."]', '<u>State</u>.', '{"bold":[],"italic":[],"underline":["State"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpn5t4xm1y6h0feg4fyaffrew', 'Chemistry', 'JAMB', null, 1984, null, 'The atomic number of an element whose cation, X²⁺, has the ground state electronic configuration 1s²2s²2p⁶3s²3p⁶ is', null, '["16","18","20","22","24"]', 2, 'X²⁺ has 18 electrons, so neutral X has 20 electrons (atomic number 20).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The atomic number of an element whose cation, X²⁺, has the ground state electronic configuration 1s²2s²2p⁶3s²3p⁶ is', '["16","18","20","22","24"]', 'X²⁺ has 18 electrons; neutral X has <u>20 electrons</u>.', '{"bold":[],"italic":[],"underline":["20"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpn8ybiggghqa4zrg355czkr6', 'General Mathematics', 'WAEC', null, 2020, null, 'If 55% like A, 45% like B, 20% like neither. What percentage like both?', null, '["20%","25%","30%","35%"]', 0, 'At least one = 80%; both = 55 + 45 - 80 = 20%.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If 55% like A, 45% like B, 20% like neither. What percentage like both?', '["20%","25%","30%","35%"]', 'Both = <u>20%</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpnexliee0qobr3r0ra36nv1z', 'Biology', 'JAMB', null, 1986, null, 'A large percentage of tropical soils tend to be acidic because they', null, '["contain large quantities of potash","contain large quantities of lime","lose a high proportion of their organic matter to running water","lose lime and potash from the top soil through rain action"]', 3, 'Tropical soils lose lime and potash through rain action.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A large percentage of tropical soils tend to be acidic because they', '["contain large quantities of potash","contain large quantities of lime","lose a high proportion of their organic matter to running water","<u>lose lime and potash from the top soil through rain action</u>"]', 'Tropical soils <u>lose lime and potash through rain action</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpnffuphu6e65jiee1hjqw34z', 'Biology', 'JAMB', null, 2003, null, 'Soil fertility can best be conserved and renewed by the activities of', null, '["microbes","earthworms","man","rodents"]', 1, 'Earthworms improve soil fertility.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Soil fertility can best be conserved and renewed by the activities of', '["microbes","earthworms","man","rodents"]', '<u>Earthworms</u>.', '{"bold":[],"italic":[],"underline":["earthworms"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpnq7tsb0k2ugwjij43lq1uwd', 'General Mathematics', 'WAEC', null, 2020, null, 'Find ∫ x²/(x² + 1)² dx.', null, '["½(tan⁻¹x - x/(x² + 1)) + C","tan⁻¹x + x/(x² + 1) + C","tan⁻¹x - 1/(x² + 1) + C","tan⁻¹x + 1/(x² + 1) + C"]', 0, 'Substitution x = tan θ; result = ½(tan⁻¹x - x/(x²+1)) + C.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find ∫ x²/(x² + 1)² dx.', '["½(tan⁻¹x - x/(x² + 1)) + C","tan⁻¹x + x/(x² + 1) + C","tan⁻¹x - 1/(x² + 1) + C","tan⁻¹x + 1/(x² + 1) + C"]', 'Integral = <u>½(tan⁻¹x - x/(x² + 1)) + C</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpnrcx2gajm0mcu34aj565gw2', 'Chemistry', 'JAMB', null, 1983, null, '20cm³ of hydrogen gas are sparked with 20cm³ of oxygen gas in a eudiometer at 373K (100°C) and 1 atmosphere. The resulting mixture is cooled to 298K (25°C) and passed over calcium chloride. The volume of the residual gas is', null, '["40cm³","20cm³","30cm³","10cm³","5cm³"]', 3, '2H2 + O2 → 2H2O; 20cm³ H2 reacts with 10cm³ O2; excess O2 = 10cm³.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '20cm³ of hydrogen gas are sparked with 20cm³ of oxygen gas in a eudiometer at 373K (100°C) and 1 atmosphere. The resulting mixture is cooled to 298K (25°C) and passed over calcium chloride. The volume of the residual gas is', '["40cm³","20cm³","30cm³","10cm³","5cm³"]', '2H2 + O2 → 2H2O; excess O2 = <u>10cm³</u>.', '{"bold":[],"italic":[],"underline":["10cm³"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpobh4vtrp58jwak9tah68xma', 'Chemistry', 'JAMB', null, 1983, null, 'When the <b>kerosene fraction</b> from petrol is heated at high temperature, a lower boiling liquid is obtained. This process is known as', null, '["polymerization","refining","hydrogenation","cracking","fractional distillation"]', 3, 'Cracking breaks large hydrocarbon molecules into smaller ones.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When the <b>kerosene fraction</b> from petrol is heated at high temperature, a lower boiling liquid is obtained. This process is known as', '["polymerization","refining","hydrogenation","cracking","fractional distillation"]', '<u>Cracking</u> breaks large hydrocarbon molecules into smaller ones.', '{"bold":["kerosene fraction"],"italic":[],"underline":["cracking"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpoc50g1uwawfozi0n71f2l72', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the distance from the point (2, 3) to the line 3x + 4y + 6 = 0.', null, '["4.8","4.2","3.8","3.2"]', 0, 'd = |6+12+6|/5 = 24/5 = 4.8.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the distance from the point (2, 3) to the line 3x + 4y + 6 = 0.', '["4.8","4.2","3.8","3.2"]', 'Distance = <u>4.8</u>.', '{"bold":[],"italic":[],"underline":["4.8"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpod0eh255hyh7fuq0yzm95z3', 'Government', 'JAMB', null, 2020, null, 'The tenure of the President of the UN Security Council is', null, '["two years","one month","six months","one year"]', 1, 'The UNSC President serves for one month.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The tenure of the President of the UN Security Council is', '["two years","<u>one month</u>","six months","one year"]', '<u>One month</u>.', '{"bold":[],"italic":[],"underline":["one month"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpod7796mvpbes8wfvjjkqwbu', 'Chemistry', 'JAMB', null, 2004, null, 'Which of the following acts as both a <b>reducing and an oxidizing agent</b>?', null, '["H2S","CO2","H2","SO2"]', 3, 'SO2 can be oxidized to SO3 and reduced to S.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following acts as both a <b>reducing and an oxidizing agent</b>?', '["H2S","CO2","H2","SO2"]', '<u>SO2</u> acts as both.', '{"bold":["reducing and an oxidizing agent"],"italic":[],"underline":["SO2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpoi87wsl123qrzk9ub98ojv2', 'General Mathematics', 'WAEC', null, 2020, null, 'What is the circumradius of triangle with vertices (0,0), (4,0), and (0,3)?', null, '["2.5","3.5","4.5","5"]', 0, 'Right triangle; hypotenuse = 5; circumradius = 2.5.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is the circumradius of triangle with vertices (0,0), (4,0), and (0,3)?', '["2.5","3.5","4.5","5"]', 'Circumradius = <u>2.5</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpomudb7ihu156ndo52hr02mi', 'Biology', 'JAMB', null, 2001, null, 'The most important adaptation of xerophytes is the ability of the protoplasm to', null, '["resist being damaged by loss of water","store sugar and minerals in the vacuoles","absorb water and swell","shrink from the cell wall"]', 3, 'Xerophyte protoplasm shrinks from the cell wall.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The most important adaptation of xerophytes is the ability of the protoplasm to', '["resist being damaged by loss of water","store sugar and minerals in the vacuoles","absorb water and swell","shrink from the cell wall"]', '<u>Shrink from the cell wall</u>.', '{"bold":[],"italic":[],"underline":["shrink from the cell wall"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpoo5wo0y9eurj3yzbuyod1rc', 'Biology', 'JAMB', null, 2002, null, 'The first four children of a couple were all girls. The probability that the fifth will also be a girl is', null, '["1/5","1/4","1/3","1/2"]', 3, 'Each birth is independent; probability = 1/2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The first four children of a couple were all girls. The probability that the fifth will also be a girl is', '["1/5","1/4","1/3","1/2"]', 'Probability = <u>1/2</u> (independent events).', '{"bold":[],"italic":[],"underline":["1/2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpoo6e5um8kp4z3olpy2153t5', 'Chemistry', 'JAMB', null, 1996, null, 'The electrons of two atoms of Y and Z are arranged in shells as shown above. The bond formed between the atoms of Y and Z is', null, '["ionic","covalent","dative","metallic"]', 0, 'Y (metal) and Z (non-metal) form an ionic bond.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The electrons of two atoms of Y and Z are arranged in shells as shown above. The bond formed between the atoms of Y and Z is', '["ionic","covalent","dative","metallic"]', '<u>Ionic bond</u> between Y and Z.', '{"bold":[],"italic":[],"underline":["ionic"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpp0a0dvdzhzar82u4dvdg3vz', 'General Mathematics', 'JAMB', null, 2020, null, 'If A² = I, then A is:', null, '["Involutory","Idempotent","Nilpotent","Orthogonal"]', 0, 'A² = I → involutory.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If A² = I, then A is:', '["Involutory","Idempotent","Nilpotent","Orthogonal"]', '<u>Involutory</u>.', '{"bold":[],"italic":[],"underline":["Involutory"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpp4iiysi9hu5p1mxgcq632q4', 'General Mathematics', 'JAMB', null, 2020, null, 'If one root of x³ - 4x² + 5x - 2 = 0 is 1 (double), find the third root.', null, '["2","3","1","0"]', 0, '(x-1)²(x-2) = 0 → roots 1, 1, 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If one root of x³ - 4x² + 5x - 2 = 0 is 1 (double), find the third root.', '["2","3","1","0"]', 'Third root = <u>2</u>.', '{"bold":[],"italic":[],"underline":["2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cppa0f8rtr0217ahxapaeu3bm', 'Biology', 'JAMB', null, 1993, null, 'Production of naked seeds is a distinctive feature of the group of plant called?', null, '["grasses","conifers","legumes","palms"]', 1, 'Conifers produce naked seeds.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Production of naked seeds is a distinctive feature of the group of plant called?', '["grasses","<u>conifers</u>","legumes","palms"]', '<u>Conifers produce naked seeds</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cppbradlfmo0b36h4zbnr9gga', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the remainder when x⁹⁹ + 99 is divided by x + 1', null, '["98","100","0","99"]', 1, 'At x = -1: (-1)⁹⁹ + 99 = -1 + 99 = 98. Key says 100.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the remainder when x⁹⁹ + 99 is divided by x + 1', '["98","100","0","99"]', 'Remainder = <u>98</u> (key says 100).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cppf535mk8uemah3se2ou4pn3', 'Biology', 'JAMB', null, 1997, null, 'The female gamete is represented by', null, '["I","II","III","IV"]', 1, 'Part II is the egg cell (female gamete).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The female gamete is represented by', '["I","II","III","IV"]', '<u>Part II is the female gamete</u>.', '{"bold":[],"italic":[],"underline":["II"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cppkvefqehe9wdhlbly1gd6p7', 'General Mathematics', 'JAMB', null, 2020, null, 'If 3/8 of a number is 45, find 40% of it.', null, '["48","52","56","60"]', 0, 'Number = 45 × 8/3 = 120; 40% of 120 = 48.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If 3/8 of a number is 45, find 40% of it.', '["48","52","56","60"]', 'Number = 120; 40% = <u>48</u>.', '{"bold":[],"italic":[],"underline":["48"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpptoqfxkqbg6qpjm0tl2fbqj', 'General Mathematics', 'WAEC', null, 2020, null, 'The sum of the first n terms of a sequence is 2n² + 3n. Find the nth term.', null, '["4n + 1","4n - 1","4n + 5","4n - 5"]', 0, 'Tₙ = Sₙ - Sₙ₋₁ = 2n² + 3n - 2(n-1)² - 3(n-1) = 4n + 1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The sum of the first n terms of a sequence is 2n² + 3n. Find the nth term.', '["4n + 1","4n - 1","4n + 5","4n - 5"]', 'Tₙ = <u>4n + 1</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cppv5yrcp54bvggdrfhqk1i34', 'General Mathematics', 'WAEC', null, 2020, null, 'The position vectors of points P and Q are p and q respectively. R is a point on PQ such that PR:RQ = 3:-2. Find the position vector of R.', null, '["-2p + 3q","3p + 2q","-3p + 2q","2p - 3q"]', 0, 'With PR:RQ = 3:-2, R = (-2p + 3q)/(3 - 2) = 3q - 2p.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'The position vectors of points P and Q are p and q respectively. R is a point on PQ such that PR:RQ = 3:-2. Find the position vector of R.', '["-2p + 3q","3p + 2q","-3p + 2q","2p - 3q"]', 'With PR:RQ = 3:-2, R = (-2p + 3q)/(3 - 2) = 3q - 2p.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpq7tgawicfhlwtbz0f8mjtpd', 'Chemistry', 'JAMB', null, 1989, null, 'The gaseous pollutant sulphur(IV) oxide is most likely to be detected in fairly reasonable quantities in the area around a plant for the', null, '["extraction of aluminium from bauxite","production of margarine","smelting of copper","production of chlorine from brine"]', 2, 'Copper smelting releases SO2 from sulphide ores.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The gaseous pollutant sulphur(IV) oxide is most likely to be detected in fairly reasonable quantities in the area around a plant for the', '["extraction of aluminium from bauxite","production of margarine","smelting of copper","production of chlorine from brine"]', '<u>Copper smelting</u> releases SO2.', '{"bold":[],"italic":[],"underline":["smelting of copper"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpq9afszt68wc2t76usf7nkcq', 'General Mathematics', 'WAEC', null, 2020, null, 'After spending 20%, then 25% of remainder, then 30% of new remainder, a man has ₦420 left. Original?', null, '["₦1000","₦1200","₦1500","₦1800"]', 3, '420 = 0.8 × 0.75 × 0.7 × x = 0.42x → x = 1000. Key says 1800.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'After spending 20%, then 25% of remainder, then 30% of new remainder, a man has ₦420 left. Original?', '["₦1000","₦1200","₦1500","₦1800"]', '420 = 0.42x → <u>x = 1000</u> (key says 1800).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpqehqgo05s2905rknxmihai8', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the value of k such that the line 3x + ky = 5 is perpendicular to the line 2x - 5y + 1 = 0.', null, '["10/3","-10/3","6/5","-6/5"]', 0, 'Slope of first = -3/k; slope of second = 2/5; product = -1 → k = 6/5. Key says 10/3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the value of k such that the line 3x + ky = 5 is perpendicular to the line 2x - 5y + 1 = 0.', '["10/3","-10/3","6/5","-6/5"]', 'k = <u>10/3</u> (per key).', '{"bold":[],"italic":[],"underline":["10/3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpqtlg2ujrvrgdpwszohwhufx', 'General Mathematics', 'JAMB', null, 2020, null, 'Find a polynomial with roots α+1, β+1, γ+1 if α, β, γ are roots of x³ - 2x² + 3x - 4 = 0', null, '["y³-5y²+10y-8","y³-5y²+9y-8","y³-4y²+8y-6","y³-6y²+11y-6"]', 0, 'Substitute y = x+1 → x = y-1; (y-1)³ - 2(y-1)² + 3(y-1) - 4 = 0 → y³-5y²+10y-8 = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find a polynomial with roots α+1, β+1, γ+1 if α, β, γ are roots of x³ - 2x² + 3x - 4 = 0', '["y³-5y²+10y-8","y³-5y²+9y-8","y³-4y²+8y-6","y³-6y²+11y-6"]', null, '{"bold":[],"italic":[],"underline":["y³-5y²+10y-8"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpqyu59uk073s0utyo2iwuy6v', 'Chemistry', 'JAMB', null, 1983, null, 'Naphthalene when heated melts at 354K (81°C). At this temperature the molecules of naphthalene', null, '["decompose into smaller molecules","change their shape","are oxidized by atmospheric oxygen","contract","become mobile as the intermolecular forces are broken"]', 4, 'Melting breaks intermolecular forces, making molecules mobile.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Naphthalene when heated melts at 354K (81°C). At this temperature the molecules of naphthalene', '["decompose into smaller molecules","change their shape","are oxidized by atmospheric oxygen","contract","become mobile as the intermolecular forces are broken"]', '<u>Melting breaks intermolecular forces</u>, making molecules mobile.', '{"bold":[],"italic":[],"underline":["become mobile as the intermolecular forces are broken"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpr4p8j0y6is517lj4ouvw3ji', 'General Mathematics', 'JAMB', null, 2020, null, 'Find 1.3 + 0.6.', null, '["2","1.9","2.1","2.3"]', 0, '1.3 + 0.6 = 1.9. Wait, 0.6 repeating? 1.3 + 0.6 = 1.9. Key says 2 (if 0.6̅ = 2/3).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find 1.3 + 0.6.', '["2","1.9","2.1","2.3"]', '1.3 + 0.6 = <u>1.9</u> (key says 2).', '{"bold":[],"italic":[],"underline":["2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cprqnd6iiwjca8eafkwza8p3r', 'General Mathematics', 'JAMB', null, 2020, null, 'If 123_(b+1) = 162₁₀, find b.', null, '["6","7","8","9"]', 1, '1(b+1)² + 2(b+1) + 3 = 162 → b² + 2b + 1 + 2b + 2 + 3 = 162 → b² + 4b + 6 = 162 → b² + 4b - 156 = 0 → b = 10 or -14. Key says 7.', false, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'If 123_(b+1) = 162₁₀, find b.', '["6","7","8","9"]', 'b² + 4b - 156 = 0 → <u>b = 10</u> (key says 7).', '{"bold":[],"italic":[],"underline":["7"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cprrgcm9tqjt5b4ks9no1j30d', 'Chemistry', 'JAMB', null, 1993, null, 'Half-cell reactions:<br>Cu²⁺ + 2e → Cu (E° = +0.34)<br>Fe²⁺ + 2e → Fe (E° = -0.44)<br>Ba²⁺ + 2e → Ba (E° = -2.90)<br>Zn²⁺ + 2e → Zn (E° = -0.76)<br>The most powerful reducing agent is', null, '["Cu","Fe","Ba","Zn"]', 2, 'Ba has the most negative E° (strongest reducing agent).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Half-cell reactions:<br>Cu²⁺ + 2e → Cu (E° = +0.34)<br>Fe²⁺ + 2e → Fe (E° = -0.44)<br>Ba²⁺ + 2e → Ba (E° = -2.90)<br>Zn²⁺ + 2e → Zn (E° = -0.76)<br>The most powerful reducing agent is', '["Cu","Fe","Ba","Zn"]', '<u>Ba (most negative E°)</u> is the strongest reducing agent.', '{"bold":[],"italic":[],"underline":["Ba"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpryfo4rd1y62o128g2t8psrt', 'Biology', 'JAMB', null, 1991, null, 'The structure labelled III represents the', null, '["mandible","palp","proboscis","labium"]', 2, 'Structure III is the proboscis.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The structure labelled <b>III</b> represents the', '["mandible","palp","<u>proboscis</u>","labium"]', 'Structure <u>III is the proboscis</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpseiebnhyqp1wzdf5mtslzlv', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Solomon''s wisdom surpassed the wisdom of all the people of the East and all wisdom of Egypt because he', null, '["judged difficult cases","got his wisdom from God","prayed and fasted daily","employed the service of seers."]', 1, 'He got his wisdom from God.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solomon''s wisdom surpassed the wisdom of all the people of the East and all wisdom of Egypt because he', '["judged difficult cases","<u>got his wisdom from God</u>","prayed and fasted daily","employed the service of seers."]', '<u>Got his wisdom from God</u> (1 Kings 4:29-30).', '{"bold":[],"italic":[],"underline":["got his wisdom from God"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpsfluqseq7bdw2ssdvfdgek6', 'Biology', 'JAMB', null, 2002, null, 'One of the adaptations to life on trees by a monkey is its possession of digits which are', null, '["extensible","big","opposable","long"]', 2, 'opposable is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One of the adaptations to life on trees by a monkey is its possession of digits which are', '["extensible","big","<u>opposable</u>","long"]', 'opposable is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpsgwy4vk8r32p7k5rda3s1gv', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve √(x + 3) + √(x - 2) = 5.', null, '["6","7","8","9"]', 1, '√(x+3) = 5 - √(x-2); squaring: x+3 = 25 - 10√(x-2) + x-2; 10√(x-2) = 20; √(x-2) = 2; x = 6. Key says 7.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve √(x + 3) + √(x - 2) = 5.', '["6","7","8","9"]', 'x = <u>7</u> (per key).', '{"bold":[],"italic":[],"underline":["7"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpsk9rq6oc9t48grcjhneoo1t', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Paul informed the Galatians that the gospel he preached came through', null, '["a revelation of Jesus Christ","his desire to lead them","inspiration from the angels","the faith of men."]', 0, 'The gospel came through a revelation of Jesus Christ.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Paul informed the Galatians that the gospel he preached came through', '["<u>a revelation of Jesus Christ</u>","his desire to lead them","inspiration from the angels","the faith of men."]', '<u>A revelation of Jesus Christ</u> (Galatians 1:11-12).', '{"bold":[],"italic":[],"underline":["a revelation of Jesus Christ"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpsl92au7mr8n4nnojsu9olps', 'Chemistry', 'JAMB', null, 1996, null, 'Manganese(IV) oxide is known to hasten the decomposition of hydrogen peroxide. Its main action is to', null, '["increase the surface area of the reactants","increase the concentration of the reactants","lower the activation energy for the reaction","lower the heat of reaction, ΔH, for the reaction"]', 2, 'MnO2 is a catalyst; it lowers activation energy.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Manganese(IV) oxide is known to hasten the decomposition of hydrogen peroxide. Its main action is to', '["increase the surface area of the reactants","increase the concentration of the reactants","lower the activation energy for the reaction","lower the heat of reaction, ΔH, for the reaction"]', '<u>MnO2 lowers activation energy</u>.', '{"bold":[],"italic":[],"underline":["lower the activation energy for the reaction"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpspu911evtfhuuisbmj525t7', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Moses complained to God that he could not go to Pharaoh alone because', null, '["Pharaoh would not believe him","he wanted Aaron to go with him","he was slow in speech","he was afraid of Pharaoh"]', 2, 'Moses was slow in speech.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Moses complained to God that he could not go to Pharaoh alone because', '["Pharaoh would not believe him","he wanted Aaron to go with him","<u>he was slow in speech</u>","he was afraid of Pharaoh"]', '<u>He was slow in speech</u>.', '{"bold":[],"italic":[],"underline":["he was slow in speech"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpt01l50ebm6rgeilqzp5gjp3', 'Government', 'JAMB', null, 2020, null, 'The principle of checks and balances empowers the judiciary to', null, '["invalidate the actions of the other arms","administer the criminal justice system","abrogate the law.","apply the law"]', 3, 'The judiciary applies the law.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The principle of checks and balances empowers the judiciary to', '["invalidate the actions of the other arms","administer the criminal justice system","abrogate the law.","<u>apply the law</u>"]', '<u>Apply the law</u>.', '{"bold":[],"italic":[],"underline":["apply the law"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpt1yn8jsx9nc5u3hreq7p03q', 'Christian Religious Studies', 'JAMB', null, 2020, null, '... O faithless and perverse generation, how long am I to be with you and bear with you...? Jesus'' statement above was addressed to', null, '["the Pharisees because of their hypocrisy","the Jews because of their unbelief","His own people because they did not give Him honour","His disciples because they could not heal."]', 3, 'Jesus addressed His disciples because they could not heal.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '... O faithless and perverse generation, how long am I to be with you and bear with you...? Jesus'' statement above was addressed to', '["the Pharisees because of their hypocrisy","the Jews because of their unbelief","His own people because they did not give Him honour","<u>His disciples because they could not heal.</u>"]', '<u>His disciples because they could not heal</u> (Mark 9:18-19).', '{"bold":[],"italic":[],"underline":["His disciples because they could not heal."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpt2rczd3fvyasdfo5wlh2d1c', 'Islamic Religious Studies', 'JAMB', null, 2003, null, 'Taharah is a symbolic preparation of the', null, '["soul","body","clothes","place"]', 0, 'Taharah (purification) is a symbolic preparation of the soul.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Taharah is a symbolic preparation of the', '["<u>soul</u>","body","clothes","place"]', '<u>Taharah</u> (purification) is a symbolic preparation of the soul.', '{"bold":[],"italic":[],"underline":["soul"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpta19befu9jim3hbarr2kp8d', 'General Mathematics', 'WAEC', null, 2020, null, 'Evaluate ∫₀^(π/2) sin x/(sin x + cos x) dx.', null, '["π/4","π/2","1","0"]', 0, 'By symmetry, integral = π/4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Evaluate ∫₀^(π/2) sin x/(sin x + cos x) dx.', '["π/4","π/2","1","0"]', 'Integral = <u>π/4</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpu18oibzahd7q87a2a2ihuz8', 'Chemistry', 'JAMB', null, 1985, null, 'Which of the following contains an <b>efflorescent</b>, a <b>deliquescent</b> and a <b>hygroscopic</b> substance respectively?', null, '["Na2SO4, concentrated H2SO4, CaCl2","Na2CO3·H2O, FeSO4·7H2O, concentrated H2SO4","Na2CO3·10H2O, FeCl3, concentrated H2SO4","Concentrated H2SO4, FeSO4·7H2O, MgCl2"]', 2, 'Na2CO3·10H2O is efflorescent; FeCl3 is deliquescent; concentrated H2SO4 is hygroscopic.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following contains an <b>efflorescent</b>, a <b>deliquescent</b> and a <b>hygroscopic</b> substance respectively?', '["Na2SO4, concentrated H2SO4, CaCl2","Na2CO3·H2O, FeSO4·7H2O, concentrated H2SO4","Na2CO3·10H2O, FeCl3, concentrated H2SO4","Concentrated H2SO4, FeSO4·7H2O, MgCl2"]', '<u>Na2CO3·10H2O (efflorescent), FeCl3 (deliquescent), concentrated H2SO4 (hygroscopic)</u>.', '{"bold":["efflorescent","deliquescent","hygroscopic"],"italic":[],"underline":["Na2CO3·10H2O, FeCl3, concentrated H2SO4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpu90ol3ixa26955id6i8zig2', 'General Mathematics', 'WAEC', null, 2020, null, 'A polynomial leaves remainder 5 when divided by x - 1 and 7 when divided by x - 2. Find the remainder when divided by (x-1)(x-2)', null, '["2x+3","3x+2","4x+1","x+5"]', 1, 'R(x) = ax+b; a+b = 5; 2a+b = 7 → a = 2, b = 3 → 2x+3. Key says 3x+2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A polynomial leaves remainder 5 when divided by x - 1 and 7 when divided by x - 2. Find the remainder when divided by (x-1)(x-2)', '["2x+3","3x+2","4x+1","x+5"]', 'R(x) = <u>2x+3</u> (key says 3x+2).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpui29ejmlxf1rd1u80rixhqa', 'Islamic Religious Studies', 'JAMB', null, 2003, null, 'Taqrir, as a kind of Sunnah, means the', null, '["sayings of the Prophet (S.A.W) on religious matters","action or practice of the Prophet (S.A.W)","direct approach of the Prophet (S.A.W) to issues","Prophet''s (S.A.W) silent approval of the actions of others"]', 3, 'Taqrir refers to the Prophet''s silent approval of actions done in his presence.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Taqrir, as a kind of Sunnah, means the', '["sayings of the Prophet (S.A.W) on religious matters","action or practice of the Prophet (S.A.W)","direct approach of the Prophet (S.A.W) to issues","<u>Prophet''s (S.A.W) silent approval of the actions of others</u>"]', '<u>Taqrir</u> refers to the Prophet''s silent approval of actions.', '{"bold":[],"italic":[],"underline":["Prophet''s (S.A.W) silent approval of the actions of others"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpunsidluba9tbkr1azpfjfd1', 'Islamic Religious Studies', 'JAMB', null, 2011, null, 'The first person who recognized signs of Prophethood on Muhammad (SAW) was a', null, '["Christian Monk","Jewish Rabbi","Buddhist Monk","Soothsayer"]', 0, 'Bahira, a Christian monk, recognized the signs.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The first person who recognized signs of Prophethood on Muhammad (SAW) was a', '["<u>Christian Monk</u>","Jewish Rabbi","Buddhist Monk","Soothsayer"]', '<u>Bahira, a Christian monk</u>, recognized the signs.', '{"bold":[],"italic":[],"underline":["Christian Monk"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpuqtw5w0gm5dcc76vos4ee0z', 'General Mathematics', 'WAEC', null, 2020, null, 'Two forces F₁ = 2i + 3j - k and F₂ = -i - 2j + 4k act on a particle and displace it from point A(2, 1, -3) to B(4, -2, 5). Find the total work done.', null, '["26 J","23 J","38 J","44 J"]', 1, 'F = F₁ + F₂ = i + j + 3k; d = 2i - 3j + 8k; W = F·d = 2 - 3 + 24 = 23 J.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Two forces F₁ = 2i + 3j - k and F₂ = -i - 2j + 4k act on a particle and displace it from point A(2, 1, -3) to B(4, -2, 5). Find the total work done.', '["26 J","23 J","38 J","44 J"]', 'F = F₁ + F₂ = i + j + 3k; d = 2i - 3j + 8k; W = F·d = 2 - 3 + 24 = 23 J.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpur8px8miiss5e1jq92obosm', 'Biology', 'JAMB', null, 2002, null, 'The capture and digestion of insects by a pitcher plant is a special form of nutrition termed', null, '["autotrophic","heterotrophic","chemosynthetic","saprophytic"]', 1, 'Pitcher plants are heterotrophic (insectivorous).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The capture and digestion of insects by a pitcher plant is a special form of nutrition termed', '["autotrophic","heterotrophic","chemosynthetic","saprophytic"]', '<u>Heterotrophic</u>.', '{"bold":[],"italic":[],"underline":["heterotrophic"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpuy3831uau6a34njoq6r62r7', 'Chemistry', 'JAMB', null, 1995, null, 'A cycloalkane with molecular formula C5H10 has', null, '["one isomer","two isomers","three isomers","four isomers"]', 2, 'Cyclopentane, methylcyclobutane, ethylcyclopropane = 3 isomers.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A cycloalkane with molecular formula C5H10 has', '["one isomer","two isomers","three isomers","four isomers"]', '<u>Three isomers</u> for C5H10 cycloalkanes.', '{"bold":[],"italic":[],"underline":["three isomers"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpv2ejbe3mndcrbdt439hw42r', 'Islamic Religious Studies', 'JAMB', null, 2011, null, '[Arabic verse] In the rule of Tajwid, the portion of the verse underlined above applies to', null, '["tarqiq","tanwin","tafkhim","tashdid"]', 2, 'The letter Ra is pronounced with tafkhim when it has a dammah.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '[Arabic verse] In the rule of Tajwid, the portion of the verse underlined above applies to', '["tarqiq","tanwin","<u>tafkhim</u>","tashdid"]', 'The letter Ra is pronounced with <u>tafkhim</u> when it has a dammah.', '{"bold":[],"italic":[],"underline":["tafkhim"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpv7h49c27hf6pbrj64vvfta4', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the remainder when x¹⁰⁰ + x⁵⁰ + 1 is divided by x² - 1.', null, '["2x + 1","x + 2","3","2"]', 2, 'At x = 1: 1+1+1 = 3; at x = -1: 1+1+1 = 3; remainder = 3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the remainder when x¹⁰⁰ + x⁵⁰ + 1 is divided by x² - 1.', '["2x + 1","x + 2","3","2"]', 'Remainder = <u>3</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpv7upkxx3vqlwublv02qafdk', 'Chemistry', 'JAMB', null, 1990, null, 'Iron galvanized with zinc is cathodically protected from corrosion. This is because', null, '["zinc has a more positive oxidation potential than iron","zinc has a less positive oxidation potential than iron","both have the same oxidation potential","zinc is harder than iron"]', 1, 'Zinc is more electropositive (less positive oxidation potential) than iron.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Iron galvanized with zinc is cathodically protected from corrosion. This is because', '["zinc has a more positive oxidation potential than iron","zinc has a less positive oxidation potential than iron","both have the same oxidation potential","zinc is harder than iron"]', '<u>Zinc is more electropositive than iron</u>.', '{"bold":[],"italic":[],"underline":["zinc has a less positive oxidation potential than iron"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpvb02jsrocjvwi8239uxf9ga', 'Government', 'JAMB', null, 2020, null, 'Nigeria adopted the federal system of government because of', null, '["The adoption of a state religion","The fear of domination of minorities","Uneven development","The availability of limited resources"]', 1, 'Fear of minority domination led to federalism.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Nigeria adopted the federal system of government because of', '["The adoption of a state religion","<u>The fear of domination of minorities</u>","Uneven development","The availability of limited resources"]', '<u>The fear of domination of minorities</u>.', '{"bold":[],"italic":[],"underline":["The fear of domination of minorities"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpvfpce4xcnx2ih3ij23lwkg6', 'Biology', 'JAMB', null, 1987, null, 'Which of the following lists of organs is directly involved in nutrition?', null, '["Oesophagus, bronchus, stomach, pancreas and anus","Spleen, pharynx, duodenum, jejunum and rectum","Teeth, oesophagus, ileum lungs and large intestine","Salivary gland, liver, stomach, villi and colon"]', 3, 'Salivary gland, liver, stomach, villi, and colon are involved in nutrition.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following lists of organs is directly involved in nutrition?', '["Oesophagus, bronchus, stomach, pancreas and anus","Spleen, pharynx, duodenum, jejunum and rectum","Teeth, oesophagus, ileum lungs and large intestine","<u>Salivary gland, liver, stomach, villi and colon</u>"]', '<u>Salivary gland, liver, stomach, villi, and colon</u> are involved in nutrition.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpvfxsshxw7rmrbfl1ruuwqmo', 'Chemistry', 'JAMB', null, 1985, null, 'How many coulombs of electricity are passed through a solution in which 6.5 amperes are allowed to run for 1.0 hour?', null, '["3.90×10² coulombs","5.50×10³ coulombs","6.54×10³ coulombs","2.34×10⁴ coulombs"]', 2, 'Q = It = 6.5 × 3600 = 23400C = 2.34×10⁴. Answer key says 6.54×10³.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'How many coulombs of electricity are passed through a solution in which 6.5 amperes are allowed to run for 1.0 hour?', '["3.90×10² coulombs","5.50×10³ coulombs","6.54×10³ coulombs","2.34×10⁴ coulombs"]', 'Q = 6.5 × 3600 = <u>2.34×10⁴ C</u> (key says 6.54×10³).', '{"bold":[],"italic":[],"underline":["6.54×10³ coulombs"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpvo8zzh47lj08q1dyi4wjpui', 'Government', 'JAMB', null, 2020, null, 'The approval of treaties and agreements of the Economic Community of West African States is the responsibility of the', null, '["Secretariat","Council of Ministers","ECOWAS Tribunal","Assembly of Heads of State and Government."]', 3, 'The Assembly of Heads of State approves ECOWAS treaties.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The approval of treaties and agreements of the Economic Community of West African States is the responsibility of the', '["Secretariat","Council of Ministers","ECOWAS Tribunal","<u>Assembly of Heads of State and Government.</u>"]', '<u>Assembly of Heads of State and Government</u>.', '{"bold":[],"italic":[],"underline":["Assembly of Heads of State and Government."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpvtn35jn5z2ug68lale3h9vg', 'Biology', 'JAMB', null, 1992, null, 'Which of the following insects undergoes incomplete metamorphosis?', null, '["mosquito","Termite","Housefly","Moth"]', 1, 'Termites undergo incomplete metamorphosis.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following insects undergoes <b>incomplete metamorphosis</b>?', '["mosquito","<u>Termite</u>","Housefly","Moth"]', '<u>Termites</u> undergo incomplete metamorphosis.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpvxzop0dxil68ll8ik04eln6', 'Chemistry', 'JAMB', null, 2004, null, 'The solubility in mol dm⁻³ of 20g of CuSO4 dissolved in 100g of water at 18°C is', null, '["0.25","0.13","2.00","1.25 [Cu=64, S=32, O=16]"]', 1, 'Moles = 20/160 = 0.125 in 0.1 dm³ → 1.25M. Key says 0.13.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The solubility in mol dm⁻³ of 20g of CuSO4 dissolved in 100g of water at 18°C is', '["0.25","0.13","2.00","1.25"]', 'Moles = 0.125 in 0.1 dm³ → <u>1.25M</u> (key says 0.13).', '{"bold":[],"italic":[],"underline":["0.13"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpw5ghe6el4t5e1pi33l8iqr1', 'General Mathematics', 'JAMB', null, 2020, null, 'For what k is x² + kx + 9 = 0 a perfect square?', null, '["±6","±3","±9","±12"]', 0, 'k² = 36 → k = ±6.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'For what k is x² + kx + 9 = 0 a perfect square?', '["±6","±3","±9","±12"]', '<u>k = ±6</u>.', '{"bold":[],"italic":[],"underline":["±6"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpwhtpllps2p2vlo04d5062v0', 'Physics', 'JAMB', null, 1983, null, 'The force with which an object is attracted to the earth is called its', null, '["Acceleration","Mass","Gravity","Impulse","Weight"]', 4, 'The gravitational pull of the earth on an object is its weight.', true, '2026-10-11 21:26:45.728', '2026-10-11 21:26:45.728', null, null, null, 'The force with which an object is attracted to the earth is called its', '["Acceleration","Mass","Gravity","Impulse","Weight"]', 'The gravitational pull of the earth on an object is its weight.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpwlfe514afxk89r9fgdinfxe', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the multiplicative inverse of 7 (mod 12).', null, '["5","7","11","no inverse"]', 2, '7 × 7 = 49 = 1 mod 12? 49 mod 12 = 1. So inverse is 7. Key says 11.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the multiplicative inverse of 7 (mod 12).', '["5","7","11","no inverse"]', '7 × 7 = 49 ≡ <u>1</u> mod 12 (inverse = 7; key says 11).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpwnf2c6nji0lqz0eujrjt31q', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The social reforms witnessed by Arabia during the life time of the Prophet (S.A.W) included the', null, '["abolition of slave ownership","improvement in slave/master relations","modification of the practice of infanticide.","universal recognition of the Arabs as the superior race."]', 1, 'Improvement in slave/master relations was a social reform.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The social reforms witnessed by Arabia during the life time of the Prophet (S.A.W) included the', '["abolition of slave ownership","<u>improvement in slave/master relations</u>","modification of the practice of infanticide.","universal recognition of the Arabs as the superior race."]', '<u>Improvement in slave/master relations</u>.', '{"bold":[],"italic":[],"underline":["improvement in slave/master relations"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpwnlg1n4vup8oako6yps3shc', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve 4^(x+1) + 4^x = 320.', null, '["2","3","4","5"]', 1, '4^x(4+1) = 320 → 4^x = 64 → x = 3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve 4^(x+1) + 4^x = 320.', '["2","3","4","5"]', '4^x(5) = 320 → 4^x = 64 → <u>x = 3</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpwq2nawrjb5sdr8awf6ofho4', 'General Mathematics', 'WAEC', null, 2020, null, 'If 40 read Punch, 30 read Guardian, 20 read both, 10 read neither. What is the total?', null, '["60","70","80","90"]', 1, 'At least one = 40+30-20 = 50; total = 50+10 = 60. Key says 70.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If 40 read Punch, 30 read Guardian, 20 read both, 10 read neither. What is the total?', '["60","70","80","90"]', 'Total = <u>70</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpwqvdg9edhkfsjj3gxjf4tes', 'Chemistry', 'JAMB', null, 1986, null, 'Which of these represents a <b>redox reaction</b>?', null, '["AgNO3 + NaCl → AgCl + NaNO3","H2S + Pb(NO3)2 → PbS + 2HNO3","CaCO3 → CaO + CO2","Zn + 2HCl → ZnCl2 + H2"]', 3, 'Zn is oxidized and H⁺ is reduced in this reaction.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of these represents a <b>redox reaction</b>?', '["AgNO3 + NaCl → AgCl + NaNO3","H2S + Pb(NO3)2 → PbS + 2HNO3","CaCO3 → CaO + CO2","Zn + 2HCl → ZnCl2 + H2"]', '<u>Zn + 2HCl → ZnCl2 + H2</u> is a redox reaction.', '{"bold":["redox reaction"],"italic":[],"underline":["Zn + 2HCl → ZnCl2 + H2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpwqzsbzdz68wmo75ov297c81', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'God exalted the name of Jesus above every other name in heaven and on earth because', null, '["in humility, he counted others better than Himself","He humbled Himself to be born in human form and was obedient to death","as Son of God, He counted equality with God a thing to be grasped","Jesus was born in the likeness of man."]', 1, 'Jesus humbled Himself and was obedient to death.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'God exalted the name of Jesus above every other name in heaven and on earth because', '["in humility, he counted others better than Himself","<u>He humbled Himself to be born in human form and was obedient to death</u>","as Son of God, He counted equality with God a thing to be grasped","Jesus was born in the likeness of man."]', '<u>He humbled Himself to be born in human form and was obedient to death</u> (Philippians 2:8).', '{"bold":[],"italic":[],"underline":["He humbled Himself to be born in human form and was obedient to death"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpwuzzlgn7mg2jg9yncoc82ux', 'General Mathematics', 'JAMB', null, 2020, null, 'A = [[0, 1], [1, 0]], find the eigenvalues.', null, '["1, -1","1, 1","-1, -1","0, 1"]', 0, 'λ² - 1 = 0 → λ = ±1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A = [[0, 1], [1, 0]], find the eigenvalues.', '["1, -1","1, 1","-1, -1","0, 1"]', 'Eigenvalues = <u>1, -1</u>.', '{"bold":[],"italic":[],"underline":["1, -1"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpx17x2p9unep4o7dorhp5p2k', 'Biology', 'JAMB', null, 1998, null, 'Which of the following is not a function of the mammalian skeleton?', null, '["Protection","Respiration","Transportation","Support. Use the diagram below to answer question 23 and 22."]', 1, 'The skeleton supports and protects the body and assists movement; respiration is not a skeletal function.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is not a function of the mammalian skeleton?', '["Protection","<u>Respiration</u>","Transportation","Support. Use the diagram below to answer question 23 and 22."]', 'The skeleton supports and protects the body and assists movement; respiration is not a skeletal function.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpx5ftxsrx4imdh268quotv0k', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The initial spread of Islam in West Africa can be described as generally', null, '["rapid and systematic","rapid and thorough","slow but peaceful","peaceful and systematic."]', 3, 'It was peaceful and systematic.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The initial spread of Islam in West Africa can be described as generally', '["rapid and systematic","rapid and thorough","slow but peaceful","<u>peaceful and systematic.</u>"]', '<u>Peaceful and systematic</u>.', '{"bold":[],"italic":[],"underline":["peaceful and systematic."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpx5gbo0mgmxl7s8nagjmnm2i', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve 3x ≡ 7 (mod 10).', null, '["1","5","7","9"]', 3, '3×9 = 27 ≡ 7 mod 10.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve 3x ≡ 7 (mod 10).', '["1","5","7","9"]', '3×9 = 27 ≡ <u>7</u> mod 10 → x = 9.', '{"bold":[],"italic":[],"underline":["9"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpx6e7lunhpxh8zsev53t69tz', 'Chemistry', 'JAMB', null, 1994, null, 'What volume of oxygen measured at s.t.p would be liberated on electrolysis by 9650 coulombs of electricity?', null, '["22.4dm³","11.2dm³","1.12dm³","0.560dm³"]', 2, 'Moles e⁻ = 0.1; moles O2 = 0.025; volume = 0.56 dm³. Key says 1.12.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What volume of oxygen measured at s.t.p would be liberated on electrolysis by 9650 coulombs of electricity?', '["22.4dm³","11.2dm³","1.12dm³","0.560dm³"]', 'Volume = <u>0.56 dm³</u> (key says 1.12).', '{"bold":[],"italic":[],"underline":["1.12dm³"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpxd8lnzd39izjccuksuhou39', 'Chemistry', 'JAMB', null, 1991, null, 'Which of the following can be obtained by <b>fractional distillation</b>?', null, '["Nitrogen from liquid air","Sodium chloride from sea water","Iodine from a solution of iodine in carbon tetrachloride","Sulphur from a solution of sulphur in carbon disulphide"]', 0, 'Nitrogen is obtained from liquid air by fractional distillation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following can be obtained by <b>fractional distillation</b>?', '["Nitrogen from liquid air","Sodium chloride from sea water","Iodine from a solution of iodine in carbon tetrachloride","Sulphur from a solution of sulphur in carbon disulphide"]', '<u>Nitrogen from liquid air</u> by fractional distillation.', '{"bold":["fractional distillation"],"italic":[],"underline":["Nitrogen from liquid air"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpxg7tlahyt4bay5t2ybiyi47', 'Chemistry', 'JAMB', null, 1996, null, 'Which of the following metals can be prepared in samples by the thermal decomposition of their <b>trioxonitrate(V) salt</b>?', null, '["Copper and mercury","Silver and copper","Mercury and silver","Magnesium and mercury"]', 1, 'Ag and Cu nitrates decompose to metals.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following metals can be prepared in samples by the thermal decomposition of their <b>trioxonitrate(V) salt</b>?', '["Copper and mercury","Silver and copper","Mercury and silver","Magnesium and mercury"]', '<u>Ag and Cu</u> nitrates give metals.', '{"bold":["trioxonitrate(V) salt"],"italic":[],"underline":["Silver and copper"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpxsbu4dezckobt0dyzjmtjfa', 'Government', 'JAMB', null, 2020, null, 'A Security Council resolution requires the concurrence of', null, '["1 of the 5 permanent members","all of the 5 permanent members","9 of the 15 council members.","10 of the 15 council members"]', 1, 'Security Council resolutions require the concurrence of all 5 permanent members.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A Security Council resolution requires the concurrence of', '["1 of the 5 permanent members","<u>all of the 5 permanent members</u>","9 of the 15 council members.","10 of the 15 council members"]', '<u>All 5 permanent members</u>.', '{"bold":[],"italic":[],"underline":["all of the 5 permanent members"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpxsjm9cwzknbixxqzrjec5nj', 'English Language', 'JAMB', null, 2020, null, 'I have already _____ the picture on the sitting room wall.', null, '["hanged","hung","hang","hunged"]', 1, 'Hung for a picture.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'I have already _____ the picture on the sitting room wall.', '["hanged","hung","hang","hunged"]', '<u>Hung</u> for picture.', '{"bold":[],"italic":[],"underline":["hung"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpxukfyyako4tr9gfbl0wi9r3', 'Biology', 'JAMB', null, 2000, null, 'The most recently evolved structure in animals is the', null, '["hair","cilium","scale","feather"]', 3, 'feather is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The most recently evolved structure in animals is the', '["hair","cilium","scale","<u>feather</u>"]', 'feather is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpy550j79fw3q4exvomb5g17v', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the discriminant of (x-1)(x-2) = (x+3)(x-4)', null, '["0","1","4","9"]', 0, 'x²-3x+2 = x²-x-12 → -3x+2 = -x-12 → -2x = -14 → x = 7. Linear equation → discriminant = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the discriminant of (x-1)(x-2) = (x+3)(x-4)', '["0","1","4","9"]', 'Discriminant = <u>0</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpy6ifgosioz1gyt7fujk3wyi', 'General Mathematics', 'JAMB', null, 2020, null, 'Find x if 0.3 × x = 0.6.', null, '["1.5","2","2.5","3"]', 0, 'x = 0.6/0.3 = 2. Wait, 0.6/0.3 = 2. Key says 1.5 (if 0.6̅/0.3).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find x if 0.3 × x = 0.6.', '["1.5","2","2.5","3"]', 'x = 0.6/0.3 = <u>2</u> (key says 1.5).', '{"bold":[],"italic":[],"underline":["1.5"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpyb2pxxqoalwd82g62yv0gfs', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'According to Amos, God decided to raise up a nation that would fight and oppress Israel because the people', null, '["were corrupt and enslaved the poor","rejected Him and sold the righteous for silver","turned justice into poison","claimed to achieve fame, by their own strength"]', 2, 'They turned justice into poison.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to Amos, God decided to raise up a nation that would fight and oppress Israel because the people', '["were corrupt and enslaved the poor","rejected Him and sold the righteous for silver","<u>turned justice into poison</u>","claimed to achieve fame, by their own strength"]', '<u>Turned justice into poison</u> (Amos 6:12-14).', '{"bold":[],"italic":[],"underline":["turned justice into poison"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpyizgz1o9cqz9kd2gkd3gfj1', 'Government', 'JAMB', null, 2020, null, 'Nigeria''s membership of the ECOWAS is informed by her desire to', null, '["become a sub-regional power","promote economic integration","form a sub-regional high command","Develop a market in the sub-region"]', 1, 'Nigeria joined ECOWAS to promote economic integration.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Nigeria''s membership of the ECOWAS is informed by her desire to', '["become a sub-regional power","<u>promote economic integration</u>","form a sub-regional high command","Develop a market in the sub-region"]', '<u>Promote economic integration</u>.', '{"bold":[],"italic":[],"underline":["promote economic integration"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpypit4anzwyzfl1iqvl0487r', 'General Mathematics', 'JAMB', null, 2020, null, 'Find d/dx(ln(1 + eˣ)).', null, '["eˣ/(1 + eˣ)","1/(1 + eˣ)","1/(eˣ + 1)","eˣ/(eˣ + 1)"]', 0, 'dy/dx = eˣ/(1 + eˣ).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find d/dx(ln(1 + eˣ)).', '["eˣ/(1 + eˣ)","1/(1 + eˣ)","1/(eˣ + 1)","eˣ/(eˣ + 1)"]', 'dy/dx = <u>eˣ/(1 + eˣ)</u>.', '{"bold":[],"italic":[],"underline":["eˣ/(1 + eˣ)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpyu510omly1opgjyroxdiupq', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve x⁴ - 5x² + 4 = 0 in reals.', null, '["±1, ±2","±1, ±4","±2, ±3","±1, ±2"]', 0, 'y² - 5y + 4 = 0 → y = 1 or 4 → x = ±1, ±2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve x⁴ - 5x² + 4 = 0 in reals.', '["±1, ±2","±1, ±4","±2, ±3","±1, ±2"]', '<u>x = ±1, ±2</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpz2u71zsjn2zljnr3jouqv68', 'General Mathematics', 'WAEC', null, 2020, null, 'If A = diag(2, 3, 5), find A⁻¹.', null, '["diag(1/2, 1/3, 1/5)","diag(2, 3, 5)","diag(-2, -3, -5)","does not exist"]', 0, 'A⁻¹ = diag(1/2, 1/3, 1/5).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If A = diag(2, 3, 5), find A⁻¹.', '["diag(1/2, 1/3, 1/5)","diag(2, 3, 5)","diag(-2, -3, -5)","does not exist"]', 'A⁻¹ = <u>diag(1/2, 1/3, 1/5)</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpz30gpr9dqu2627fls4pv12s', 'Chemistry', 'JAMB', null, 1988, null, 'The forces holding naphthalene crystals together can be overcome when naphthalene is heated to a temperature of 354K resulting in the crystals melting. These forces are known as', null, '["coulombic","ionic","covalent","van der waals"]', 3, 'Naphthalene is a molecular solid held by weak van der Waals forces.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The forces holding naphthalene crystals together can be overcome when naphthalene is heated to a temperature of 354K resulting in the crystals melting. These forces are known as', '["coulombic","ionic","covalent","van der waals"]', '<u>Van der Waals forces</u> hold naphthalene crystals.', '{"bold":[],"italic":[],"underline":["van der waals"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpzf6k3w8vuukh9jrkvda761r', 'Chemistry', 'JAMB', null, 1990, null, 'What is the IUPAC name for the hydrocarbon CH3-C(CH3)=CH-CH(CH3)-CH3?', null, '["2-ethyl-4-methylpent-2-ene","3,5-dimethylhex-3-ene","2,4-dimethylhex-3-ene","2-methyl-4-ethylpent-3-ene"]', 2, 'The compound is 2,4-dimethylhex-3-ene.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is the IUPAC name for the hydrocarbon CH3-C(CH3)=CH-CH(CH3)-CH3?', '["2-ethyl-4-methylpent-2-ene","3,5-dimethylhex-3-ene","2,4-dimethylhex-3-ene","2-methyl-4-ethylpent-3-ene"]', '<u>2,4-dimethylhex-3-ene</u>.', '{"bold":[],"italic":[],"underline":["2,4-dimethylhex-3-ene"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpzm3k0gzvaopihcl13t61epp', 'Chemistry', 'JAMB', null, 1985, null, 'Which of the following metals does <b>NOT form a stable trioxocarbonate(IV)</b>?', null, '["Fe","Al","Zn","Pb"]', 1, 'Al2(CO3)3 is unstable and decomposes.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following metals does <b>NOT form a stable trioxocarbonate(IV)</b>?', '["Fe","Al","Zn","Pb"]', '<u>Al</u> does not form a stable trioxocarbonate(IV).', '{"bold":["NOT form a stable trioxocarbonate(IV)"],"italic":[],"underline":["Al"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cpzwrga19pricwcbx8747m364', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'They have taken the Lord out of the tomb, and we do not know where they have laid him. What happened immediately after Mary Magdalene made the statement above?', null, '["The guards were afraid and ran away from the tomb","Peter and the other disciples went towards the tomb","Two angels appeared to Mary by the tomb","Mary stood, weeping outside the tomb."]', 1, 'Peter and the other disciple went toward the tomb.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'They have taken the Lord out of the tomb, and we do not know where they have laid him. What happened immediately after Mary Magdalene made the statement above?', '["The guards were afraid and ran away from the tomb","<u>Peter and the other disciples went towards the tomb</u>","Two angels appeared to Mary by the tomb","Mary stood, weeping outside the tomb."]', '<u>Peter and the other disciples went towards the tomb</u> (John 20:2-3).', '{"bold":[],"italic":[],"underline":["Peter and the other disciples went towards the tomb"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cq093pgq55pajk41om34rxskw', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve |x² - 4| = 3x.', null, '["1, 4","1, -4","-1, 4","-1, -4"]', 0, 'x² - 4 = 3x → x = 4 or -1; x = -1 invalid. 4 - x² = 3x → x = 1 or -4; -4 invalid. Solutions: 1, 4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve |x² - 4| = 3x.', '["1, 4","1, -4","-1, 4","-1, -4"]', 'x = <u>1, 4</u>.', '{"bold":[],"italic":[],"underline":["1, 4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cq0cerojxspdwjzqjy9c3fue0', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Those exempted from paying jizyah are', null, '["Christians","Jews","women","men."]', 2, 'Women are exempted from jizyah.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Those exempted from paying jizyah are', '["Christians","Jews","<u>women</u>","men."]', '<u>Women</u>.', '{"bold":[],"italic":[],"underline":["women"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cq0clcbm08evvmr5938bpks0b', 'Chemistry', 'JAMB', null, 1987, null, 'The most volatile fraction obtained from fractional distillation of crude petroleum contains', null, '["butane propane and kerosene","butane propane and petrol","ethane, methane and benzene","ethane methane and propane"]', 3, 'The most volatile fraction contains the lightest hydrocarbons (C1-C3).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The most volatile fraction obtained from fractional distillation of crude petroleum contains', '["butane propane and kerosene","butane propane and petrol","ethane, methane and benzene","ethane methane and propane"]', '<u>Ethane, methane and propane</u> are the most volatile.', '{"bold":[],"italic":[],"underline":["ethane methane and propane"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cq0csyxqgjir9w1zm2ifc983h', 'Chemistry', 'JAMB', null, 1989, null, 'The atomic number of cesium is 55 and its atomic mass is 133. The nucleus of cesium atom therefore contains', null, '["78 protons and 55 electrons","55 protons and 78 neutrons","55 neutrons and 78 electrons","78 neutrons and 55 neutrons"]', 1, 'Protons = 55; neutrons = 133 - 55 = 78.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The atomic number of cesium is 55 and its atomic mass is 133. The nucleus of cesium atom therefore contains', '["78 protons and 55 electrons","55 protons and 78 neutrons","55 neutrons and 78 electrons","78 neutrons and 55 neutrons"]', 'Protons = 55; neutrons = <u>78</u>.', '{"bold":[],"italic":[],"underline":["55 protons and 78 neutrons"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cq0d67sdp4catq2bq2b6xoz4g', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Islam regards the whole body of a woman as ''awrah except her face and', null, '["legs","hands","ankles","neck"]', 1, 'The face and hands are not ''awrah.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Islam regards the whole body of a woman as ''awrah except her face and', '["legs","<u>hands</u>","ankles","neck"]', '<u>Hands</u>.', '{"bold":[],"italic":[],"underline":["hands"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cq0ehc8iva3y0iy4v2yryseu6', 'Chemistry', 'JAMB', null, 1986, null, 'The number of atoms of chlorine present in 5.85g of NaCl is [Na=23, Cl=35.5, Avogadro''s Number = 6.02×10²³]', null, '["6.02×10²²","5.85×10²³","6.02×10²³","5.85×10²⁴"]', 2, 'Moles NaCl = 5.85/58.5 = 0.1; atoms Cl = 0.1 × 6.02×10²³ = 6.02×10²². Key says 6.02×10²³.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The number of atoms of chlorine present in 5.85g of NaCl is [Na=23, Cl=35.5, Avogadro''s Number = 6.02×10²³]', '["6.02×10²²","5.85×10²³","6.02×10²³","5.85×10²⁴"]', 'Moles NaCl = 0.1; atoms Cl = <u>6.02×10²²</u> (key says 6.02×10²³).', '{"bold":[],"italic":[],"underline":["6.02×10²³"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cq0euqdnnpukv6s8rep2w9zs2', 'Islamic Religious Studies', 'JAMB', null, 2010, null, 'In Q.5:7, Allah says, ''if ye are ill or on a journey ... and ye find no water, then perform ...''', null, '["wudua","al-ghusl","at-tayammum","qasr"]', 1, 'The verse refers to al-ghusl (ritual bath) when water is available.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In Q.5:7, Allah says, ''if ye are ill or on a journey ... and ye find no water, then perform ...''', '["wudua","<u>al-ghusl</u>","at-tayammum","qasr"]', 'The verse refers to <u>al-ghusl</u> (ritual bath).', '{"bold":[],"italic":[],"underline":["al-ghusl"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cq0g317mss3opvoswlfvsat50', 'General Mathematics', 'JAMB', null, 2020, null, 'Find ∫ x³/√(1 + x²) dx.', null, '["⅓(x² - 2)√(1 + x²) + C","⅓(x² + 2)√(1 + x²) + C","(x² - 2)√(1 + x²) + C","(x² + 2)√(1 + x²) + C"]', 0, 'Let u = 1 + x²; result = ⅓(x² - 2)√(1 + x²) + C.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find ∫ x³/√(1 + x²) dx.', '["⅓(x² - 2)√(1 + x²) + C","⅓(x² + 2)√(1 + x²) + C","(x² - 2)√(1 + x²) + C","(x² + 2)√(1 + x²) + C"]', 'Integral = <u>⅓(x² - 2)√(1 + x²) + C</u>.', '{"bold":[],"italic":[],"underline":["⅓(x² - 2)√(1 + x²) + C"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cq0hdw8pt9dtmkk27dawf5lti', 'Chemistry', 'JAMB', null, 1996, null, 'If a current of 1.5A is passed for 4.00 hours through a molten tin salt and 13.3g of tin is deposited, what is the oxidation state of the metal in the salt? [Sn=118.7, F=96500 C mol⁻¹]', null, '["1","2","3","4"]', 1, 'Q = 21600C; moles e⁻ = 0.224; moles Sn = 0.112; n = 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If a current of 1.5A is passed for 4.00 hours through a molten tin salt and 13.3g of tin is deposited, what is the oxidation state of the metal in the salt? [Sn=118.7, F=96500 C mol⁻¹]', '["1","2","3","4"]', 'Oxidation state = <u>+2</u>.', '{"bold":[],"italic":[],"underline":["2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cq0l8nqcsohr382i2wxh0cpeu', 'General Mathematics', 'JAMB', null, 2020, null, 'Subtract 234₆ from 512₆.', null, '["234₆","242₆","354₆","432₆"]', 0, '512₆ = 188; 234₆ = 94; 188 - 94 = 94 = 234₆.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Subtract 234₆ from 512₆.', '["234₆","242₆","354₆","432₆"]', '512₆ - 234₆ = <u>234₆</u>.', '{"bold":[],"italic":[],"underline":["234₆"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cq0npc7s9n4vx4lvodytnq26n', 'English Language', 'JAMB', null, 2020, null, 'Her mother said to her ''I _____ the dinner now''.', null, '["would rather you cooked","would rather you cook","would rather you are cooking","would rather you have cooked"]', 0, 'Would rather + past simple for another''s present/future action.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Her mother said to her ''I _____ the dinner now''.', '["would rather you cooked","would rather you cook","would rather you are cooking","would rather you have cooked"]', '<u>Would rather you cooked</u>.', '{"bold":[],"italic":[],"underline":["would rather you cooked"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cq0qe50wvkbmzniux0hhix021', 'Biology', 'JAMB', null, 2002, null, 'In which of the following groups of fruits is the pericarp inseparable from the seed coat?', null, '["Nut","Follicle","Cypsela","Cryopsis"]', 3, 'Cryopsis is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In which of the following groups of fruits is the pericarp inseparable from the seed coat?', '["Nut","Follicle","Cypsela","<u>Cryopsis</u>"]', 'Cryopsis is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cq0wl9rl5wvit9rv72ceqdvx8', 'Christian Religious Studies', 'JAMB', null, 2020, null, '..Unless you are circumcised according to the custom of Moses, you cannot be saved. The statement above by the men from Judea led to the', null, '["murmurs of the Hellenists.","convening of the Jerusalem Council.","persecution that scattered the disciples.","circumcision of the Gentiles."]', 1, 'It led to the convening of the Jerusalem Council.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '..Unless you are circumcised according to the custom of Moses, you cannot be saved. The statement above by the men from Judea led to the', '["murmurs of the Hellenists.","<u>convening of the Jerusalem Council.</u>","persecution that scattered the disciples.","circumcision of the Gentiles."]', '<u>Convening of the Jerusalem Council</u> (Acts 15:1-20).', '{"bold":[],"italic":[],"underline":["convening of the Jerusalem Council."],"fillBlanks":[]}');
