insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cq1dbf7gae0ib2jo0mi1w9w2h', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the locus of a point such that its distance from (2, 3) is twice its distance from (5, 7).', null, '["Circle","Ellipse","Hyperbola","Parabola"]', 0, 'Distance ratio 2:1 → circle of Apollonius.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the locus of a point such that its distance from (2, 3) is twice its distance from (5, 7).', '["Circle","Ellipse","Hyperbola","Parabola"]', '<u>Circle</u>.', '{"bold":[],"italic":[],"underline":["Circle"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cq1jw1i889ivqm47j22x230y3', 'General Mathematics', 'JAMB', null, 2020, null, 'Find additive inverse of 8 (mod 13).', null, '["5","6","7","8"]', 1, '8 + x ≡ 0 mod 13 → x = 5. Key says 6.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find additive inverse of 8 (mod 13).', '["5","6","7","8"]', '8 + 5 = 13 ≡ <u>0</u> → x = 5 (key says 6).', '{"bold":[],"italic":[],"underline":["6"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cq1k1gzgvh2wuz6f6qzh7tqjy', 'Chemistry', 'JAMB', null, 1998, null, 'Terylene is synthesized from ethane-1,2-diol and benzene-1,4-dicarboxylic acid by', null, '["addition reaction","condensation reaction","elimination reaction","substitution reaction"]', 1, 'Terylene is formed by condensation polymerization.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Terylene is synthesized from ethane-1,2-diol and benzene-1,4-dicarboxylic acid by', '["addition reaction","condensation reaction","elimination reaction","substitution reaction"]', '<u>Condensation reaction</u>.', '{"bold":[],"italic":[],"underline":["condensation reaction"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cq1wup4slwn90t16d510nz87f', 'Biology', 'JAMB', null, 1997, null, 'The group of insects that undergoes <b>complete metamorphosis</b> is', null, '["houseflies, beetles and cockroaches","cockroaches, grasshoppers and bees","houseflies, beetles and butterflies","aphids, grasshoppers and butterflies"]', 2, 'Houseflies, beetles, butterflies undergo complete metamorphosis.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The group of insects that undergoes <b>complete metamorphosis</b> is', '["houseflies, beetles and cockroaches","cockroaches, grasshoppers and bees","houseflies, beetles and butterflies","aphids, grasshoppers and butterflies"]', '<u>Houseflies, beetles, butterflies</u> undergo complete metamorphosis.', '{"bold":["complete metamorphosis"],"italic":[],"underline":["houseflies, beetles and butterflies"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cq2f5ap0khv52jjjsvkwcar2s', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Jesus said His disciples has been made clean by', null, '["their abiding in Him","His abiding in them always","the word He spoke to them","their walking in the spirit."]', 2, 'They were made clean by the word He spoke to them.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Jesus said His disciples has been made clean by', '["their abiding in Him","His abiding in them always","<u>the word He spoke to them</u>","their walking in the spirit."]', '<u>The word He spoke to them</u> (John 15:3).', '{"bold":[],"italic":[],"underline":["the word He spoke to them"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cq2hgz10ckcej8v0a1h983ajg', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'David''s immediate reaction to the news that the hearts of the Israelites have gone after Absalom was to', null, '["mobilize his army","plead with Absalom","weep for Judah","flee to the wilderness"]', 3, 'David fled to the wilderness.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'David''s immediate reaction to the news that the hearts of the Israelites have gone after Absalom was to', '["mobilize his army","plead with Absalom","weep for Judah","<u>flee to the wilderness</u>"]', '<u>Flee to the wilderness</u> (2 Samuel 15:14).', '{"bold":[],"italic":[],"underline":["flee to the wilderness"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cq2l1n4ajkvvzrjrby5ptnlk0', 'General Mathematics', 'WAEC', null, 2020, null, 'If log_a 2 = 0.3 and log_a 3 = 0.48, find log_a ∛54.', null, '["0.56","0.58","0.62","0.64"]', 1, '54 = 2×27 = 2×3³; log_a ∛54 = (1/3)(log_a 2 + 3 log_a 3) = (1/3)(0.3 + 1.44) = 0.58.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If log_a 2 = 0.3 and log_a 3 = 0.48, find log_a ∛54.', '["0.56","0.58","0.62","0.64"]', null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cq2pbira4ujyu71eyjhfjswb2', 'Christian Religious Studies', 'JAMB', null, 2020, null, '... When my soul fainted within me, I remembered the LORD, and my prayer came to thee ... The prayer above was offered by Jonah', null, '["at Tarshish","at Nineveh","in the belly of the fish","in the sea"]', 2, 'Jonah prayed from the belly of the fish.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '... When my soul fainted within me, I remembered the LORD, and my prayer came to thee ... The prayer above was offered by Jonah', '["at Tarshish","at Nineveh","<u>in the belly of the fish</u>","in the sea"]', '<u>In the belly of the fish</u> (Jonah 2:1-8).', '{"bold":[],"italic":[],"underline":["in the belly of the fish"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cq2pcuwjazsf7tk4y2et4b8sl', 'Chemistry', 'JAMB', null, 1989, null, 'The combustion of ethene, C2H4, is given by the equation C2H4 + 3O2 → 2CO2 + 2H2O, ΔH = -1428 kJ. If the molar heats of formation of water and carbon(IV) oxide are -286 kJ and -396 kJ respectively, calculate the molar heat of formation of ethane in kJ.', null, '["-2792","+2792","-64","+64"]', 2, 'ΔHf(C2H4) = 2(-396) + 2(-286) - (-1428) = -1364 + 1428 = +64. Key says -64.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The combustion of ethene, C2H4, is given by the equation C2H4 + 3O2 → 2CO2 + 2H2O, ΔH = -1428 kJ. If the molar heats of formation of water and carbon(IV) oxide are -286 kJ and -396 kJ respectively, calculate the molar heat of formation of ethane in kJ.', '["-2792","+2792","-64","+64"]', 'ΔHf = 2(-396) + 2(-286) - (-1428) = <u>+64 kJ</u>.', '{"bold":[],"italic":[],"underline":["-64"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cq2xr62btsgbn6hajdoviso7n', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Paul described the gifts he received from the Philippians as', null, '["peace offering","pleasing to God","treasure in heaven","free-will offering."]', 1, 'Paul described their gifts as pleasing to God.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Paul described the gifts he received from the Philippians as', '["peace offering","<u>pleasing to God</u>","treasure in heaven","free-will offering."]', '<u>Pleasing to God</u> (Philippians 4:18).', '{"bold":[],"italic":[],"underline":["pleasing to God"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cq3bacm5she5ieni9uhsew9jh', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'King Josiah was killed by Pharaoh Neco in a battle at', null, '["Megiddo","Egypt","Syria","Magdallah"]', 0, 'Josiah was killed at Megiddo.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'King Josiah was killed by Pharaoh Neco in a battle at', '["<u>Megiddo</u>","Egypt","Syria","Magdallah"]', '<u>Megiddo</u> (2 Kings 23:29).', '{"bold":[],"italic":[],"underline":["Megiddo"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cq3ctinjyh04x1wo5fharw26x', 'Chemistry', 'JAMB', null, 1984, null, 'Copper sulphate solution is electrolyzed using platinum electrodes. A current of 0.193 amperes is passed for 2hrs. How many grams of copper are deposited? [Cu=63.5, F=96500C]', null, '["0.457g","0.500g","0.882g","0.914g","1.00g"]', 0, 'Q = 0.193 × 7200 = 1389.6C; moles Cu = 1389.6/(2×96500) = 0.0072; mass = 0.457g.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Copper sulphate solution is electrolyzed using platinum electrodes. A current of 0.193 amperes is passed for 2hrs. How many grams of copper are deposited? [Cu=63.5, F=96500C]', '["0.457g","0.500g","0.882g","0.914g","1.00g"]', 'Mass Cu = <u>0.457g</u>.', '{"bold":[],"italic":[],"underline":["0.457g"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cq3d2cfxgu3s4ijz3sjcn1icq', 'Government', 'JAMB', null, 2020, null, 'The rule of law is a negation of', null, '["equality before the law","supremacy of the law","limited power","absolute power"]', 3, 'The rule of law negates absolute power.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The rule of law is a negation of', '["equality before the law","supremacy of the law","limited power","<u>absolute power</u>"]', '<u>Absolute power</u>.', '{"bold":[],"italic":[],"underline":["absolute power"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cq3lbqhgbybv344sk3m4aijog', 'Biology', 'JAMB', null, 1984, null, 'The removal of a man''s pancreas by surgical operation can affect only the digestion of', null, '["starch","starch, protein and fats","oils and fats","proteins","carbohydrate and fats"]', 1, 'The pancreas produces enzymes for starch, protein, and fat digestion.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The removal of a man''s pancreas by surgical operation can affect only the digestion of', '["starch","<u>starch, protein and fats</u>","oils and fats","proteins","carbohydrate and fats"]', 'The pancreas produces enzymes for <u>starch, protein, and fat digestion</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cq3r8bmpoao44yetz25mpbdrb', 'Government', 'JAMB', null, 2020, null, 'The central decision-making organ of a confederation is made up of', null, '["technocrats appointed by the units","politicians elected from the confederal constituencies","politicians nominated by government of member states.","representatives of pressure groups"]', 2, 'In a confederation, member states nominate representatives to the central organ.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The central decision-making organ of a confederation is made up of', '["technocrats appointed by the units","politicians elected from the confederal constituencies","<u>politicians nominated by government of member states.</u>","representatives of pressure groups"]', 'The central organ comprises <u>politicians nominated by member state governments</u>.', '{"bold":[],"italic":[],"underline":["politicians nominated by government of member states."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cq3yoqfgvc6iho8ajpymdtqy8', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve |2x - 3| > 5.', null, '["x < -1 or x > 4","x < -2 or x > 4","x < -1 or x > 5","x < -2 or x > 5"]', 0, '2x - 3 > 5 → x > 4; 2x - 3 < -5 → x < -1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve |2x - 3| > 5.', '["x < -1 or x > 4","x < -2 or x > 4","x < -1 or x > 5","x < -2 or x > 5"]', 'x < -1 or x > 4.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cq44zsk1azad5smi40h2f5xh2', 'Christian Religious Studies', 'JAMB', null, 2020, null, '....for if this plan or this undertaking is of men, it will fail; but if it is of God, you will not be able to overthrow them.... The "them" in Gamaliel''s statement above refers to', null, '["Paul and Timothy","Peter and John","Peter and the apostles","Paul and Silas."]', 2, 'them refers to Peter and the apostles.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '....for if this plan or this undertaking is of men, it will fail; but if it is of God, you will not be able to overthrow them.... The "them" in Gamaliel''s statement above refers to', '["Paul and Timothy","Peter and John","<u>Peter and the apostles</u>","Paul and Silas."]', '<u>Peter and the apostles</u> (Acts 5:38-39).', '{"bold":[],"italic":[],"underline":["Peter and the apostles"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cq496ms1pjs1vhlry1cph0q0a', 'Biology', 'JAMB', null, 2003, null, 'Spines and shells on animals are adaptations for', null, '["physical defence","camouflage","chemical defence","mimicry"]', 0, 'physical defence is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Spines and shells on animals are adaptations for', '["<u>physical defence</u>","camouflage","chemical defence","mimicry"]', 'physical defence is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cq4adkmfbati4l85cn4fbo53e', 'General Mathematics', 'WAEC', null, 2020, null, 'Simplify 1/(1+√2) + 1/(√2+√3) + ... + 1/(√99+√100).', null, '["7","8","9","10"]', 1, 'Telescoping: (√2-1) + (√3-√2) + ... + (√100-√99) = 10-1 = 9. Key says 8.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Simplify 1/(1+√2) + 1/(√2+√3) + ... + 1/(√99+√100).', '["7","8","9","10"]', 'Sum = <u>9</u> (key says 8).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cq4ej881mv8jhvsbsrsycta77', 'Chemistry', 'JAMB', null, 1993, null, 'NH3 + H2O → NH4⁺ + OH⁻. It may be deduced from the reaction above that', null, '["a redox reaction has occurred","H3O⁺ acts as an oxidizing agent","H3O⁺ acts as an acid","Water acts as an acid"]', 3, 'Water donates a proton (acid) to NH3 (base).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'NH3 + H2O → NH4⁺ + OH⁻. It may be deduced from the reaction above that', '["a redox reaction has occurred","H3O⁺ acts as an oxidizing agent","H3O⁺ acts as an acid","Water acts as an acid"]', '<u>Water acts as an acid</u> (proton donor).', '{"bold":[],"italic":[],"underline":["Water acts as an acid"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cq4exc7i2gerwzgc9fzngmku8', 'General Mathematics', 'WAEC', null, 2020, null, 'Find x if 0.3 × x = 0.6.', null, '["1.5","2","2.5","3"]', 0, 'x = 0.6/0.3 = 2. Wait, 0.6/0.3 = 2. Key says 1.5 (if 0.6̅/0.3).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find x if 0.3 × x = 0.6.', '["1.5","2","2.5","3"]', 'x = 0.6/0.3 = <u>2</u> (key says 1.5).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cq4lwm81bvjrawkyd10ybb8vn', 'Chemistry', 'JAMB', null, 1983, null, 'In the Haber process for the manufacture of ammonia, finely divided iron is used as', null, '["an ionizing agent","a reducing agent","a catalyst","a dehydrating agent","an oxidizing agent"]', 2, 'Iron is the catalyst in the Haber process.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the Haber process for the manufacture of ammonia, finely divided iron is used as', '["an ionizing agent","a reducing agent","a catalyst","a dehydrating agent","an oxidizing agent"]', '<u>Iron is the catalyst</u> in the Haber process.', '{"bold":[],"italic":[],"underline":["a catalyst"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cq500z4up5qwm6s5iy1u98n57', 'Chemistry', 'JAMB', null, 1984, null, 'In the reaction H2O(g) + C(s) ⇌ H2(g) + CO(g), which of the following has <b>no effect</b> on the equilibrium position?', null, '["Adding argon to the system","Lowering the temperature","Adding hydrogen to the system","Decreasing the pressure","Increasing the temperature"]', 0, 'Adding an inert gas at constant volume has no effect on equilibrium.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the reaction H2O(g) + C(s) ⇌ H2(g) + CO(g), which of the following has <b>no effect</b> on the equilibrium position?', '["Adding argon to the system","Lowering the temperature","Adding hydrogen to the system","Decreasing the pressure","Increasing the temperature"]', '<u>Adding argon</u> at constant volume has no effect.', '{"bold":["no effect"],"italic":[],"underline":["Adding argon to the system"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cq52mtyc8rvqsfqqyvpunjf75', 'Chemistry', 'JAMB', null, 1996, null, '50cm³ of sulphur(IV) oxide, 800cm³ of ammonia, 450cm³ of hydrogen chloride, 1.0cm³ of water at 15°C. Which is suitable for demonstrating the <b>fountain experiment</b>?', null, '["Sulphur(IV) oxide and hydrogen chloride","Carbon(IV) oxide and ammonia","Ammonia and hydrogen chloride","Carbon(IV) oxide and sulphur(IV) oxide"]', 2, 'NH3 and HCl are very soluble.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '50cm³ of sulphur(IV) oxide, 800cm³ of ammonia, 450cm³ of hydrogen chloride, 1.0cm³ of water at 15°C. Which is suitable for demonstrating the <b>fountain experiment</b>?', '["Sulphur(IV) oxide and hydrogen chloride","Carbon(IV) oxide and ammonia","Ammonia and hydrogen chloride","Carbon(IV) oxide and sulphur(IV) oxide"]', '<u>Ammonia and HCl</u>.', '{"bold":["fountain experiment"],"italic":[],"underline":["Ammonia and hydrogen chloride"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cq5amc7yk394r9mcqwwvwghvt', 'General Mathematics', 'WAEC', null, 2020, null, 'If α, β, γ are the roots of x³ - 7x² + 8x + 5 = 0, find the value of (α + 1)(β + 1)(γ + 1).', null, '["5","7","9","11"]', 1, '(α+1)(β+1)(γ+1) = αβγ + (αβ+βγ+γα) + (α+β+γ) + 1 = -5 + 8 + 7 + 1 = 11. Key says 7.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If α, β, γ are the roots of x³ - 7x² + 8x + 5 = 0, find the value of (α + 1)(β + 1)(γ + 1).', '["5","7","9","11"]', 'Value = <u>7</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cq66bt6bw90l2zk5yl1435zuk', 'General Mathematics', 'JAMB', null, 2020, null, 'Evaluate lim_{x→0} (e^(3x) - 1)/sin 2x.', null, '["0","2/3","3/2","infinity"]', 2, 'L''Hôpital: 3e^(3x)/(2cos 2x) → 3/2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Evaluate lim_{x→0} (e^(3x) - 1)/sin 2x.', '["0","2/3","3/2","infinity"]', 'Limit = <u>3/2</u>.', '{"bold":[],"italic":[],"underline":["3/2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cq68y7aos1chnxx2gf63u12tp', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The memorization, recording and compilation of the Qur''an ensured its', null, '["divine nature","divine authority","authenticity","eternity"]', 2, 'These ensured the authenticity of the Qur''an.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The memorization, recording and compilation of the Qur''an ensured its', '["divine nature","divine authority","<u>authenticity</u>","eternity"]', '<u>Authenticity</u>.', '{"bold":[],"italic":[],"underline":["authenticity"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cq6cjpmo7veis5m4wefriar7p', 'Chemistry', 'JAMB', null, 1999, null, 'The salt that reacts with dilute hydrochloric acid to produce a pungent smelling gas which decolorizes acidified purple potassium tetraoxomanganate(VII) solution is', null, '["Na2SO4","Na2SO3","Na2S","Na2CO3"]', 1, 'Na2SO3 + HCl → SO2 (pungent, decolorizes KMnO4).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The salt that reacts with dilute hydrochloric acid to produce a pungent smelling gas which decolorizes acidified purple potassium tetraoxomanganate(VII) solution is', '["Na2SO4","Na2SO3","Na2S","Na2CO3"]', '<u>Na2SO3</u> gives SO2.', '{"bold":[],"italic":[],"underline":["Na2SO3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cq6imtucetkw5yxjnp7buf4vk', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'To maintain the quality of Taqwa one has to be', null, '["wealthy","disciplined","poor","a leader"]', 1, 'One has to be disciplined.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'To maintain the quality of Taqwa one has to be', '["wealthy","<u>disciplined</u>","poor","a leader"]', '<u>Disciplined</u>.', '{"bold":[],"italic":[],"underline":["disciplined"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cq6kfuxq0rnh9mqz4cvlvdw53', 'General Mathematics', 'JAMB', null, 2020, null, 'The standard deviation of 5 numbers is 3. If each is doubled, find the new SD.', null, '["6","3","12","9"]', 0, 'SD doubles too: 6.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The standard deviation of 5 numbers is 3. If each is doubled, find the new SD.', '["6","3","12","9"]', 'New SD = <u>6</u>.', '{"bold":[],"italic":[],"underline":["6"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cq6m5hmgr5bzdhesmf7j1uwvo', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'According to Peter, Christians should maintain good conduct among non-Christians so that they could', null, '["become children of God","love one another","be seen doing good","get help from the Gentiles."]', 2, 'They should be seen doing good.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to Peter, Christians should maintain good conduct among non-Christians so that they could', '["become children of God","love one another","<u>be seen doing good</u>","get help from the Gentiles."]', '<u>Be seen doing good</u> (1 Peter 2:12).', '{"bold":[],"italic":[],"underline":["be seen doing good"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cq6poehxqcz1qgr7ujkn0fhek', 'Government', 'JAMB', null, 2020, null, 'In a confederation, the constituency that a member of legislature represents is a', null, '["nation-state","region","senatorial district","parliamentary constituency"]', 0, 'Confederal legislators represent nation-states.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In a confederation, the constituency that a member of legislature represents is a', '["<u>nation-state</u>","region","senatorial district","parliamentary constituency"]', '<u>Nation-state</u>.', '{"bold":[],"italic":[],"underline":["nation-state"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cq6pyajqn58f6rd7w662x0mql', 'Chemistry', 'JAMB', null, 1995, null, 'What is the IUPAC name for the hydrocarbon CH3-C(CH3)=CH-CH(CH3)-CH3?', null, '["2-ethyl-4-methylpent-2-ene","3,5-dimethylhex-3-ene","2,4-dimethylhex-3-ene","2-methyl-4-ethylpent-3-ene"]', 2, 'The compound is 2,4-dimethylhex-3-ene.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is the IUPAC name for the hydrocarbon CH3-C(CH3)=CH-CH(CH3)-CH3?', '["2-ethyl-4-methylpent-2-ene","3,5-dimethylhex-3-ene","2,4-dimethylhex-3-ene","2-methyl-4-ethylpent-3-ene"]', '<u>2,4-dimethylhex-3-ene</u>.', '{"bold":[],"italic":[],"underline":["2,4-dimethylhex-3-ene"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cq6w1ku314vomspwed7if2yu5', 'Government', 'JAMB', null, 2020, null, 'Political values are required in any given society through', null, '["political re-orientation","political campaign","political socialization","political indoctrination"]', 2, 'Political values are transmitted through political socialization.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Political values are required in any given society through', '["political re-orientation","political campaign","<u>political socialization</u>","political indoctrination"]', '<u>Political socialization</u>.', '{"bold":[],"italic":[],"underline":["political socialization"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cq71d385eexi7mhigvqirbabf', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'In Surah al-Qari''ah, mankind is compared to', null, '["scattered moths","laden camels","pampered creatures","humiliated beasts."]', 0, 'Mankind is compared to scattered moths.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In Surah al-Qari''ah, mankind is compared to', '["<u>scattered moths</u>","laden camels","pampered creatures","humiliated beasts."]', '<u>Scattered moths</u> (Q. 101:4).', '{"bold":[],"italic":[],"underline":["scattered moths"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cq760ukzk769xyl0pe07nn3d2', 'Chemistry', 'JAMB', null, 1985, null, '200cm³ of oxygen diffuse through a porous plug in 50 seconds. How long will 80cm³ of methane (CH4) take to diffuse through the same porous plug under the same conditions? [C=12, O=16, H=1]', null, '["20 sec","20 sec","14 sec","7 sec"]', 2, 'Rate O2 = 4 cm³/s; rate CH4 = 4 × √(32/16) = 5.66 cm³/s; time = 80/5.66 ≈ 14s.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '200cm³ of oxygen diffuse through a porous plug in 50 seconds. How long will 80cm³ of methane (CH4) take to diffuse through the same porous plug under the same conditions? [C=12, O=16, H=1]', '["20 sec","20 sec","14 sec","7 sec"]', 'Time = 80/5.66 ≈ <u>14s</u>.', '{"bold":[],"italic":[],"underline":["14 sec"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cq7bdl9f1jkswn8b1m8g5yym0', 'Islamic Religious Studies', 'JAMB', null, 2002, null, 'The messenger of Allah sent to the people of <b>Tamud</b> was', null, '["Isa (A.S)","Musa (A.S)","Hud (A.S)","Salih (A.S)"]', 3, 'Prophet Salih was sent to the people of Thamud.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The messenger of Allah sent to the people of <b>Tamud</b> was', '["Isa (A.S)","Musa (A.S)","Hud (A.S)","<u>Salih (A.S)</u>"]', '<u>Prophet Salih</u> was sent to the people of Thamud.', '{"bold":["Tamud"],"italic":[],"underline":["Salih (A.S)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cq7isyv4kx077bk0kyrai1wyj', 'General Mathematics', 'JAMB', null, 2020, null, 'If xʸ = yˣ, find dy/dx.', null, '["y(y - x ln y)/(x(y - ln y))","y(x ln y - y)/(x(y ln x - x))","y(x - y ln x)/(x(y - x ln y))","y(x ln y + y)/(x(y ln x + x))"]', 0, 'Implicit differentiation yields y(y - x ln y)/(x(y - ln y)).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If xʸ = yˣ, find dy/dx.', '["y(y - x ln y)/(x(y - ln y))","y(x ln y - y)/(x(y ln x - x))","y(x - y ln x)/(x(y - x ln y))","y(x ln y + y)/(x(y ln x + x))"]', 'dy/dx = <u>y(y - x ln y)/(x(y - ln y))</u>.', '{"bold":[],"italic":[],"underline":["y(y - x ln y)/(x(y - ln y))"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cq7pp5tbg4565y8lkyd6wp9b0', 'Government', 'JAMB', null, 2020, null, 'The Arthur Richards Constitution was designed to last for', null, '["nine years","five years","twelve years","six years"]', 0, 'The Richards Constitution was designed to last nine years.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Arthur Richards Constitution was designed to last for', '["<u>nine years</u>","five years","twelve years","six years"]', '<u>Nine years</u>.', '{"bold":[],"italic":[],"underline":["nine years"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cq7s52ipxap16d4ezrvkp5fh0', 'Chemistry', 'JAMB', null, 1994, null, 'Which of the following physical properties <b>decreases down a group</b> in the periodic table?', null, '["Atomic radius","Ionic radius","Electropositivity","Electronegativity"]', 3, 'Electronegativity decreases down a group.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following physical properties <b>decreases down a group</b> in the periodic table?', '["Atomic radius","Ionic radius","Electropositivity","Electronegativity"]', '<u>Electronegativity decreases</u> down a group.', '{"bold":["decreases down a group"],"italic":[],"underline":["Electronegativity"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cq81eqify4vuwjt08w191bkth', 'Biology', 'JAMB', null, 2000, null, 'Use the graph to answer questions 31 and 32. The soil becomes toxic to plants when the concentration of its essential elements is in the range labelled', null, '["IV","III","II","I"]', 0, 'Range IV is toxic.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Use the graph to answer questions 31 and 32. The soil becomes toxic to plants when the concentration of its essential elements is in the range labelled', '["IV","III","II","I"]', '<u>Range IV</u> is toxic.', '{"bold":[],"italic":[],"underline":["IV"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cq81hoewwvbl8u9rqfd74v77i', 'Chemistry', 'JAMB', null, 1996, null, 'Atoms of element X (with 2 electrons in the outer shell) combine with atoms of Y (with 7 electrons in the outer shell). Which of the following is <b>FALSE</b>? The compound formed', null, '["has formula XY2","is likely to be ionic","contains X²⁺ ions","contains Y⁻ ions"]', 0, 'The formula XY2 is correct, so this is not FALSE.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Atoms of element X (with 2 electrons in the outer shell) combine with atoms of Y (with 7 electrons in the outer shell). Which of the following is <b>FALSE</b>? The compound formed', '["has formula XY2","is likely to be ionic","contains X²⁺ ions","contains Y⁻ ions"]', 'Formula = <u>XY2</u> is correct.', '{"bold":["FALSE"],"italic":[],"underline":["has formula XY2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cq8b5gvfyhj2mrz5ptzs9v64h', 'General Mathematics', 'JAMB', null, 2020, null, 'In an AP, Tₘ = n and Tₙ = m. Find Tₘ₊ₙ.', null, '["0","m + n","m - n","m"]', 0, 'a + (m-1)d = n; a + (n-1)d = m; subtracting: (m-n)d = n-m → d = -1; a = m + n - 1; Tₘ₊ₙ = a + (m+n-1)d = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In an AP, Tₘ = n and Tₙ = m. Find Tₘ₊ₙ.', '["0","m + n","m - n","m"]', 'Tₘ₊ₙ = <u>0</u>.', '{"bold":[],"italic":[],"underline":["0"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cq8clbgjeh6hrar50y4841xkr', 'Biology', 'JAMB', null, 1991, null, 'The specific number of chromosomes in each somatic cell is represented by', null, '["2^N","23","2N","N"]', 2, 'The specific number of chromosomes in somatic cells is 2N.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The specific number of chromosomes in each somatic cell is represented by', '["2^N","23","<u>2N</u>","N"]', 'The specific number of chromosomes in somatic cells is <u>2N</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cq8hi441gcr2g3d0nr30sz8yo', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve |2x - 3| > 5.', null, '["x < -1 or x > 4","x < -2 or x > 4","x < -1 or x > 5","x < -2 or x > 5"]', 0, '2x - 3 > 5 → x > 4; 2x - 3 < -5 → x < -1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve |2x - 3| > 5.', '["x < -1 or x > 4","x < -2 or x > 4","x < -1 or x > 5","x < -2 or x > 5"]', 'x < -1 or x > 4.', '{"bold":[],"italic":[],"underline":["x < -1 or x > 4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cq8jwlqthbhorwysb1nvs3ln0', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'After the healing of the demoniac in the country of the Gerasenes, the people begged Jesus to', null, '["stay with them","visit them always","go away from them","heal their sick"]', 2, 'The people begged Jesus to go away from them.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'After the healing of the demoniac in the country of the Gerasenes, the people begged Jesus to', '["stay with them","visit them always","<u>go away from them</u>","heal their sick"]', '<u>Go away from them</u> (Mark 5:1-17).', '{"bold":[],"italic":[],"underline":["go away from them"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cq8konsaszihl5mz91uvh2shg', 'Chemistry', 'JAMB', null, 1995, null, 'Iron galvanized with zinc is cathodically protected from corrosion. This is because', null, '["zinc has a more positive oxidation potential than iron","zinc has a less positive oxidation potential than iron","both have the same oxidation potential","zinc is harder than iron"]', 1, 'Zinc is more electropositive than iron.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Iron galvanized with zinc is cathodically protected from corrosion. This is because', '["zinc has a more positive oxidation potential than iron","zinc has a less positive oxidation potential than iron","both have the same oxidation potential","zinc is harder than iron"]', '<u>Zinc is more electropositive than iron</u>.', '{"bold":[],"italic":[],"underline":["zinc has a less positive oxidation potential than iron"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cq8lyambke5ggkjr27ngoxlb3', 'Government', 'JAMB', null, 2020, null, 'In the First Republic, the official opposition party was the', null, '["Action Group","Northern People''s Congress","Northern Elements Progressive Union","National Council of Nigeria and the Cameroons"]', 0, 'The Action Group was the official opposition.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the First Republic, the official opposition party was the', '["<u>Action Group</u>","Northern People''s Congress","Northern Elements Progressive Union","National Council of Nigeria and the Cameroons"]', '<u>Action Group</u>.', '{"bold":[],"italic":[],"underline":["Action Group"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cq8pe7s5fawijxczaydy064ll', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve 2x + 3 ≡ 5 (mod 9).', null, '["1","4","7","8"]', 0, '2x ≡ 2 mod 9 → x ≡ 1 mod 9.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve 2x + 3 ≡ 5 (mod 9).', '["1","4","7","8"]', '2x ≡ 2 → <u>x = 1</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cq8qung44cd0bbeqmnnniv4ra', 'Biology', 'JAMB', null, 1992, null, 'A population is defined as a collection of similar organisms that', null, '["behave in the same way","interbreed freely","are found in the same habitat","eat the same food"]', 1, 'A population is a collection of organisms that interbreed freely.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A population is defined as a collection of similar organisms that', '["behave in the same way","<u>interbreed freely</u>","are found in the same habitat","eat the same food"]', 'A population is a collection of organisms that <u>interbreed freely</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cq8xeznu78s4sbrmgexy1e7yj', 'Biology', 'JAMB', null, 2003, null, 'Mycorrhiza is an association between fungi and', null, '["roots of higher plants","ilamentous algae","bacteria","protozoans"]', 0, 'roots of higher plants is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Mycorrhiza is an association between fungi and', '["<u>roots of higher plants</u>","ilamentous algae","bacteria","protozoans"]', 'roots of higher plants is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cq8xtx76t6rk34jwwuxrbvb4c', 'General Mathematics', 'WAEC', null, 2020, null, 'If x² - 3x + 1 = 0 find x⁴ + 1/x⁴', null, '["7","47","11","13"]', 1, 'x + 1/x = 3; x² + 1/x² = 7; x⁴ + 1/x⁴ = 49 - 2 = 47.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'If x² - 3x + 1 = 0 find x⁴ + 1/x⁴', '["7","47","11","13"]', 'x + 1/x = 3; x² + 1/x² = 7; x⁴ + 1/x⁴ = 49 - 2 = 47.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cq90hjnuo5n3emommde17fg4p', 'Physics', 'JAMB', null, 2019, null, 'The SI unit of magnetic flux density is', null, '["THE TESLA","THE HENRY","THE VOLT","THE VOLT-SECOND"]', 0, 'Magnetic flux density is measured in tesla (T).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The SI unit of <b>magnetic flux density</b> is', '["<u>THE TESLA</u>","THE HENRY","THE VOLT","THE VOLT-SECOND"]', 'Magnetic flux density is measured in <u>tesla (T)</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cq90sqr4rxunxnyctn3mx2d5k', 'General Mathematics', 'JAMB', null, 2020, null, 'Find x if 9^x + 6^x = 4^(x+1).', null, '["log_{3/2}2","log_{2/3}2","log_3 2","log_2 3"]', 0, 'Divide by 4^x: (3/2)^2x + (3/2)^x = 4 → y² + y - 4 = 0 → y = (√17-1)/2. Key says log_{3/2}2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find x if 9^x + 6^x = 4^(x+1).', '["log_{3/2}2","log_{2/3}2","log_3 2","log_2 3"]', '<u>log_{3/2}2</u> (per key).', '{"bold":[],"italic":[],"underline":["log_{3/2}2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cq978yjka3z4ofnko9ft4s1kw', 'Chemistry', 'JAMB', null, 1991, null, 'CH3CH2CH2CH2Br + alc.KOH → CH3CH=CHCH3 + CH3CH2CH=CH2. The above reaction is an example of', null, '["dehydration","dehydrohalogenation","neutralization","a fission reaction"]', 1, 'Removal of HBr from an alkyl halide is dehydrohalogenation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'CH3CH2CH2CH2Br + alc.KOH → CH3CH=CHCH3 + CH3CH2CH=CH2. The above reaction is an example of', '["dehydration","dehydrohalogenation","neutralization","a fission reaction"]', '<u>Dehydrohalogenation</u> (removal of HBr).', '{"bold":[],"italic":[],"underline":["dehydrohalogenation"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cq9d9325pix335gn51txh1b0k', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'When you read loudly while praying Zuhr in one of the rak''at, you are expected to', null, '["repeat your prayer","make a qabli sujud","make a ba''di sujud","recite the qunut."]', 2, 'You should make a ba''di sujud.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When you read loudly while praying Zuhr in one of the rak''at, you are expected to', '["repeat your prayer","make a qabli sujud","<u>make a ba''di sujud</u>","recite the qunut."]', '<u>Make a ba''di sujud</u>.', '{"bold":[],"italic":[],"underline":["make a ba''di sujud"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cq9ogt8jwagfzu82rx40umqce', 'Biology', 'JAMB', null, 1993, null, 'The correct order in a food chain involving the organisms (1) Grasses, (2) Hawks, (3) Snakes, (4) Grasshopper, (5) Lizards is', null, '["1 2 3 4 5","5 4 3 2 1","1 4 5 3 2","3 2 4 5 1"]', 2, 'Food chain: Grasses → Grasshopper → Lizards → Snakes → Hawks = 1 4 5 3 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The correct order in a food chain involving the organisms (1) Grasses, (2) Hawks, (3) Snakes, (4) Grasshopper, (5) Lizards is', '["1 2 3 4 5","5 4 3 2 1","<u>1 4 5 3 2</u>","3 2 4 5 1"]', 'Food chain: <u>Grasses → Grasshopper → Lizards → Snakes → Hawks = 1 4 5 3 2</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cq9td662qwg49dc7ha4e5z7f9', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'One of the spiritual objectives of as-salah is that it', null, '["develops self-restraint","encourages self-indulgence","promotes social status","increases wealth."]', 0, 'It develops self-restraint.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One of the spiritual objectives of as-salah is that it', '["<u>develops self-restraint</u>","encourages self-indulgence","promotes social status","increases wealth."]', '<u>Develops self-restraint</u>.', '{"bold":[],"italic":[],"underline":["develops self-restraint"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqa2csbdjg78iqois7whw30f4', 'Biology', 'JAMB', null, 2003, null, 'The stunted growth of a leguminous plant suffering from <b>nitrogen deficiency</b> may be corrected by inoculating the soil with', null, '["saprophytic bacteria","rhizobium","denitrifying bacteria","nitrosomonas"]', 1, 'Rhizobium fixes nitrogen in legume roots.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The stunted growth of a leguminous plant suffering from <b>nitrogen deficiency</b> may be corrected by inoculating the soil with', '["saprophytic bacteria","rhizobium","denitrifying bacteria","nitrosomonas"]', '<u>Rhizobium</u> fixes nitrogen.', '{"bold":["nitrogen deficiency"],"italic":[],"underline":["rhizobium"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqa60j5r0dlab4cbu941iw10e', 'Chemistry', 'JAMB', null, 1989, null, 'What is the partial pressure of hydrogen gas collected over water at standard atmospheric pressure and 25°C if the saturation vapour pressure of water is 23 mm Hg at that temperature?', null, '["737 mm Hg","763 mm Hg","777 mm Hg","737 mm Hg"]', 0, 'P(H2) = 760 - 23 = 737 mm Hg.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is the partial pressure of hydrogen gas collected over water at standard atmospheric pressure and 25°C if the saturation vapour pressure of water is 23 mm Hg at that temperature?', '["737 mm Hg","763 mm Hg","777 mm Hg","737 mm Hg"]', 'P(H2) = <u>737 mm Hg</u>.', '{"bold":[],"italic":[],"underline":["737 mm Hg"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqa8v778lyzrx2o6rmi14leas', 'Biology', 'JAMB', null, 1999, null, 'The most important environmental factor which epiphytes in the rain forest compete for is', null, '["water","nutrient","light","space"]', 2, 'light is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The most important environmental factor which epiphytes in the rain forest compete for is', '["water","nutrient","<u>light</u>","space"]', 'light is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqa92hfze2c57bwq1lzn6s1d5', 'Physics', 'JAMB', null, 2021, null, 'The relationship between alpha particles and helium is', null, '["they are both deflected by magnetic field","they both have two protons and two neutrons","they both are not charged","none of the above"]', 1, 'Alpha particles are helium nuclei with 2 protons and 2 neutrons.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The relationship between <b>alpha particles</b> and <b>helium</b> is', '["they are both deflected by magnetic field","<u>they both have two protons and two neutrons</u>","they both are not charged","none of the above"]', '<u>Alpha particles are helium nuclei</u> with 2 protons and 2 neutrons.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqaakaof7m7cbh3gdv574r60f', 'Government', 'JAMB', null, 2020, null, 'Which Government Question Paper Type is given to you?', null, '["Type A","Type B","Type C","Type D"]', 2, 'The question paper type is Type C.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which Government Question Paper Type is given to you?', '["Type A","Type B","<u>Type C</u>","Type D"]', '<u>Type C</u>.', '{"bold":[],"italic":[],"underline":["Type C"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqaatfgokuycgxh2uyoach6b0', 'Biology', 'JAMB', null, 2003, null, 'The most effective method of dealing with non- biodegradable pollution is by', null, '["burying","dumping","incineration","recycling"]', 3, 'recycling is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The most effective method of dealing with non- biodegradable pollution is by', '["burying","dumping","incineration","<u>recycling</u>"]', 'recycling is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqan47nzzcq73it1om6czjcrm', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve x² - 5x + 6 < 0.', null, '["(2, 3)","[2, 3]","(-∞, 2) ∪ (3, ∞)","(-∞, 2] ∪ [3, ∞)"]', 0, '(x-2)(x-3) < 0 → 2 < x < 3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve x² - 5x + 6 < 0.', '["(2, 3)","[2, 3]","(-∞, 2) ∪ (3, ∞)","(-∞, 2] ∪ [3, ∞)"]', '<u>2 < x < 3</u>.', '{"bold":[],"italic":[],"underline":["(2, 3)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqaq7lcqfrwp6hq3m9wskn444', 'Chemistry', 'JAMB', null, 1998, null, 'The reaction that is accompanied by a decrease in <b>entropy</b> when carried out at constant temperature is', null, '["N2O4 ⇌ 2NO2","N2 + 3H2 ⇌ 2NH3","CaCO3 ⇌ CaO + CO2","2N2H4 ⇌ 3N2 + 4H2O"]', 1, 'Gas moles decrease (4 → 2), so entropy decreases.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The reaction that is accompanied by a decrease in <b>entropy</b> when carried out at constant temperature is', '["N2O4 ⇌ 2NO2","N2 + 3H2 ⇌ 2NH3","CaCO3 ⇌ CaO + CO2","2N2H4 ⇌ 3N2 + 4H2O"]', '<u>N2 + 3H2 ⇌ 2NH3</u> (gas moles decrease).', '{"bold":["entropy"],"italic":[],"underline":["N2 + 3H2 ⇌ 2NH3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqas7c123yehuheweg8ir8648', 'General Mathematics', 'WAEC', null, 2020, null, 'If a, b, c in GP and x, y are AM and GM between a, b, find x/y.', null, '["(a + b)/(2√ab)","(√a + √b)/2","(a + b)/√ab","2√ab/(a + b)"]', 0, 'x = (a+b)/2; y = √(ab); x/y = (a+b)/(2√ab).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If a, b, c in GP and x, y are AM and GM between a, b, find x/y.', '["(a + b)/(2√ab)","(√a + √b)/2","(a + b)/√ab","2√ab/(a + b)"]', 'x/y = <u>(a + b)/(2√ab)</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqatxfq8s2faxhiighgy2qjpx', 'General Mathematics', 'WAEC', null, 2020, null, 'The variance of the numbers 4, 5, 6, 8, and x is 6.8. Find x.', null, '["2","7","10","12"]', 1, 'Mean = (23+x)/5; variance = 6.8; solving → x = 7.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The variance of the numbers 4, 5, 6, 8, and x is 6.8. Find x.', '["2","7","10","12"]', 'x = <u>7</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqav24dyfierwqdurxpew9f2i', 'Biology', 'JAMB', null, 2000, null, 'Coelom is absent in the class of animals termed', null, '["mollusca","reptilia","arthropoda","coelenterata"]', 3, 'Coelenterates are acoelomates.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Coelom is absent in the class of animals termed', '["mollusca","reptilia","arthropoda","coelenterata"]', '<u>Coelenterates are acoelomates</u>.', '{"bold":[],"italic":[],"underline":["coelenterata"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqb5ip2e3bap5mzgh9v2nj7iz', 'Chemistry', 'JAMB', null, 1983, null, 'Which combination of the following statements is correct?<br>1. Lowering the activation energy<br>2. Conducting the reaction in a gaseous state<br>3. Increasing the temperature<br>4. Removing the products as soon as they are formed', null, '["1, 2 and 3","1, 3 and 5","2, 3 and 5","3 and 4","3 and 5"]', 0, 'Statements 1, 2, and 3 all increase reaction rate.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which combination of the following statements is correct?<br>1. Lowering the activation energy<br>2. Conducting the reaction in a gaseous state<br>3. Increasing the temperature<br>4. Removing the products as soon as they are formed', '["1, 2 and 3","1, 3 and 5","2, 3 and 5","3 and 4","3 and 5"]', '<u>Statements 1, 2, and 3</u> all increase reaction rate.', '{"bold":[],"italic":[],"underline":["1, 2 and 3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqb5w5rqe9kurh8kngyikoa0n', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'According to Luke, Jesus'' last words on the cross were', null, '["Woman, behold your Son!","\"Father, into thy hands I commit my spirit!\"","\"I thirst\"","\"Father, forgive them; for they know not what they do\"."]', 1, 'Jesus'' last words were "Father, into thy hands I commit my spirit!"', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to Luke, Jesus'' last words on the cross were', '["Woman, behold your Son!","<u>\"Father, into thy hands I commit my spirit!\"</u>","\"I thirst\"","\"Father, forgive them; for they know not what they do\"."]', '<u>"Father, into thy hands I commit my spirit!"</u> (Luke 23:46).', '{"bold":[],"italic":[],"underline":["\"Father, into thy hands I commit my spirit!\""],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqb8cf4zuo0va7kgktva2cm4y', 'Chemistry', 'JAMB', null, 1984, null, 'Complete hydrogenation of <b>ethyne</b> yields', null, '["benzene","methane","ethene","propane","Ethane"]', 4, 'Ethyne (C2H2) + 2H2 → ethane (C2H6).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Complete hydrogenation of <b>ethyne</b> yields', '["benzene","methane","ethene","propane","Ethane"]', '<u>Ethyne + 2H2 → ethane</u>.', '{"bold":["ethyne"],"italic":[],"underline":["Ethane"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqbbohjes4tykd2h4304h29bv', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the polynomial whose roots are α/β, β/α if α, β are roots of 2x² - 3x + 1 = 0', null, '["2y²-5y+2","2y²-4y+2","2y²-6y+2","2y²-3y+2"]', 0, 'α+β = 3/2; αβ = 1/2; α/β + β/α = (α²+β²)/αβ = (9/4-1)/(1/2) = 5/2; α/β × β/α = 1; y² - (5/2)y + 1 = 0 → 2y² - 5y + 2 = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the polynomial whose roots are α/β, β/α if α, β are roots of 2x² - 3x + 1 = 0', '["2y²-5y+2","2y²-4y+2","2y²-6y+2","2y²-3y+2"]', null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqbgeuyyqc1eknmsuidvvxghx', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the range of 2, 5, 8, 11, 14, 17.', null, '["15","14","13","12"]', 0, 'Range = 17 - 2 = 15.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the range of 2, 5, 8, 11, 14, 17.', '["15","14","13","12"]', 'Range = <u>15</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqbqig0mciouewsl62zpff6wl', 'General Mathematics', 'WAEC', null, 2020, null, 'If 60% farm, 50% trade, 40% both. What percentage do neither?', null, '["20%","25%","30%","35%"]', 1, 'At least one = 60 + 50 - 40 = 70%; neither = 30%. Key says 25%.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If 60% farm, 50% trade, 40% both. What percentage do neither?', '["20%","25%","30%","35%"]', 'Neither = <u>25%</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqbummtfmv8v96k0o7ji9p8pq', 'General Mathematics', 'WAEC', null, 2020, null, 'P, Q, and R are points on a circle with center O. If ∠PQR = 120° and the radius of the circle is 7 cm, find the length of arc PR (not containing Q). (π = 22/7)', null, '["144/56 cm","28π/3 cm","44π/3 cm","56π/3 cm"]', 2, 'Angle at center = 240° (for arc not containing Q); length = (240/360)·2π·7 = 28π/3. Key says 44π/3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'P, Q, and R are points on a circle with center O. If ∠PQR = 120° and the radius of the circle is 7 cm, find the length of arc PR (not containing Q). (π = 22/7)', '["144/56 cm","28π/3 cm","44π/3 cm","56π/3 cm"]', 'Arc length = <u>44π/3 cm</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqbxgvjc4jhhesh55xdu3r9jf', 'English Language', 'JAMB', null, 2020, null, 'The Secretary-General was shocked at the number of _____.', null, '["children soldiers","child''s soldiers","child soldiers","childish soldiers"]', 2, 'Standard compound: "child soldiers".', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Secretary-General was shocked at the number of _____.', '["children soldiers","child''s soldiers","child soldiers","childish soldiers"]', 'Standard compound: <u>child soldiers</u>.', '{"bold":[],"italic":[],"underline":["child soldiers"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqc6mct5gtgc6n0il9trujzbo', 'Biology', 'JAMB', null, 2002, null, 'Plants tend to prevent overcrowding by means of efficient', null, '["water uptake","seed germination","pollination","seed dispersal"]', 3, 'Seed dispersal prevents overcrowding.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Plants tend to prevent overcrowding by means of efficient', '["water uptake","seed germination","pollination","seed dispersal"]', '<u>Seed dispersal</u>.', '{"bold":[],"italic":[],"underline":["seed dispersal"],"fillBlanks":[]}');
