insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqcy6jlvuz1p5h7zht9mfrg1i', 'Biology', 'JAMB', null, 2000, null, 'A certain savanna grasshopper changes colour from green during the rainy season to brown during the dry season bush fires. The reason for these colour changes is that the', null, '["grasshopper is getting older","environment temperature is changing","grasshopper is avoiding predation","grasshopper is frequently moulting"]', 2, 'grasshopper is avoiding predation is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A certain savanna grasshopper changes colour from green during the rainy season to brown during the dry season bush fires. The reason for these colour changes is that the', '["grasshopper is getting older","environment temperature is changing","<u>grasshopper is avoiding predation</u>","grasshopper is frequently moulting"]', 'grasshopper is avoiding predation is the best answer because it matches the biological principle tested by the question.', null);
