insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqfkmiv1xe1qucymi5sjhwzd2', 'Chemistry', 'JAMB', null, 1984, null, 'Mixing of aqueous solution of barium hydroxide and sodium tetraoxocarbonate(IV) yields a white precipitate of', null, '["barium oxide","sodium tetraoxocarbonate(IV)","sodium oxide","sodium hydroxide","barium tetraoxocarbonate"]', 4, 'Ba(OH)2 + Na2CO3 → BaCO3 (white precipitate) + 2NaOH.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Mixing of aqueous solution of barium hydroxide and sodium tetraoxocarbonate(IV) yields a white precipitate of', '["Barium oxide","sodium tetraoxocarbonate(IV)","sodium oxide","sodium hydroxide","barium tetraoxocarbonate"]', '<u>BaCO3 (barium tetraoxocarbonate)</u> is the white precipitate.', '{"bold":[],"italic":[],"underline":["barium tetraoxocarbonate"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqfl2gz94g3wgtivst4ebr0by', 'Biology', 'JAMB', null, 2001, null, 'Which of the following groups is the most advanced?', null, '["Pteridophytes","Bryophytes","Thallophytes","Gymnosperms"]', 3, 'Gymnosperms are the most advanced among the options.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following groups is the most advanced?', '["Pteridophytes","Bryophytes","Thallophytes","Gymnosperms"]', '<u>Gymnosperms</u> are most advanced.', '{"bold":[],"italic":[],"underline":["Gymnosperms"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqfru5r3sbqagvndocmf9pnob', 'General Mathematics', 'WAEC', null, 2020, null, 'For what k is x² + kx + 9 = 0 a perfect square?', null, '["±6","±3","±9","±12"]', 0, 'k² = 36 → k = ±6.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'For what k is x² + kx + 9 = 0 a perfect square?', '["±6","±3","±9","±12"]', '<u>k = ±6</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqfy0q1g7w739qrrygckrwtlj', 'Chemistry', 'JAMB', null, 1983, null, 'Which of the following methods may be used to prepare <b>trioxonitrate(V) acid</b> (nitric acid) in the laboratory?', null, '["Heating ammonia gas with tetraoxosulphate(VI) acid","Heating ammonium trioxosulphate(V) with tetraoxonitrate(V) acid","Heating sodium trioxonitrate(V) with tetraoxosulphate(VI) acid","Heating potassium trioxonitrate(V) with calcium hydroxide","Heating a mixture of ammonia gas and oxygen"]', 2, 'Heating a nitrate with concentrated H2SO4 produces HNO3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following methods may be used to prepare <b>trioxonitrate(V) acid</b> (nitric acid) in the laboratory?', '["Heating ammonia gas with tetraoxosulphate(VI) acid","Heating ammonium trioxosulphate(V) with tetraoxonitrate(V) acid","Heating sodium trioxonitrate(V) with tetraoxosulphate(VI) acid","Heating potassium trioxonitrate(V) with calcium hydroxide","Heating a mixture of ammonia gas and oxygen"]', '<u>Heating sodium trioxonitrate(V) with tetraoxosulphate(VI) acid</u> produces HNO3.', '{"bold":["trioxonitrate(V) acid"],"italic":[],"underline":["Heating sodium trioxonitrate(V) with tetraoxosulphate(VI) acid"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqg0n73we4vcqsccb53pe72t8', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve (x² - 4)/(x - 2) > 0.', null, '["(-2, 2) ∪ (2, ∞)","(-2, ∞) excluding 2","x > -2, x ≠ 2","x > 2"]', 1, '(x² - 4)/(x - 2) = (x + 2)(x - 2)/(x - 2) = x + 2 (x ≠ 2); > 0 → x > -2, x ≠ 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve (x² - 4)/(x - 2) > 0.', '["(-2, 2) ∪ (2, ∞)","(-2, ∞) excluding 2","x > -2, x ≠ 2","x > 2"]', 'Solution: <u>x > -2, x ≠ 2</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqgau6rw1uzab6jpmge2p3gu4', 'General Mathematics', 'WAEC', null, 2020, null, 'Out of 100 students: 50 take math, 40 take English, 30 take both. How many take exactly one?', null, '["30","40","50","60"]', 1, 'Exactly one = (50-30) + (40-30) = 20 + 10 = 30. Key says 40.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Out of 100 students: 50 take math, 40 take English, 30 take both. How many take exactly one?', '["30","40","50","60"]', 'Exactly one = <u>40</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqgcrg55vjunl20ts81chppwn', 'Biology', 'JAMB', null, 2002, null, 'The carnassial teeth of a carnivorous animal consist of the', null, '["last upper premolar and the first lower molar","last upper molar and the last lower molar","first upper premolar and the first lower molar","first upper molar and the first lower molar"]', 0, 'Carnassial teeth = last upper premolar + first lower molar.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The carnassial teeth of a carnivorous animal consist of the', '["last upper premolar and the first lower molar","last upper molar and the last lower molar","first upper premolar and the first lower molar","first upper molar and the first lower molar"]', '<u>Last upper premolar and first lower molar</u>.', '{"bold":[],"italic":[],"underline":["last upper premolar and the first lower molar"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqgdvpiprkf2ea0qbp3nv681z', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve 4^(x+1) + 4^x = 320.', null, '["2","3","4","5"]', 1, '4^x(4+1) = 320 → 4^x = 64 → x = 3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve 4^(x+1) + 4^x = 320.', '["2","3","4","5"]', '4^x(5) = 320 → 4^x = 64 → <u>x = 3</u>.', '{"bold":[],"italic":[],"underline":["3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqghxj0svy9fq6s7wujb9951p', 'Government', 'JAMB', null, 2020, null, 'Which of the following is the main function of the civil service?', null, '["Implementing government policies","Supporting the party in power","Allocating resources to the federating units","Mobilizing grassroot support for government"]', 0, 'The civil service implements government policies.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is the main function of the civil service?', '["<u>Implementing government policies</u>","Supporting the party in power","Allocating resources to the federating units","Mobilizing grassroot support for government"]', '<u>Implementing government policies</u>.', '{"bold":[],"italic":[],"underline":["Implementing government policies"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqgj932fnmuk7aj2uyu92hzkr', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'It is necessary to circumcise them, and to charge them to keep the law of Moses. In response to the Pharisees'' statement above, Peter rebuked them by saying that God has', null, '["cleansed the Gentiles'' heart by faith","put the yoke upon the Gentiles'' neck","made circumcision for only those in leadership","chosen the Israelites among other people."]', 0, 'God cleansed the Gentiles'' heart by faith.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'It is necessary to circumcise them, and to charge them to keep the law of Moses. In response to the Pharisees'' statement above, Peter rebuked them by saying that God has', '["<u>cleansed the Gentiles'' heart by faith</u>","put the yoke upon the Gentiles'' neck","made circumcision for only those in leadership","chosen the Israelites among other people."]', '<u>Cleansed the Gentiles'' heart by faith</u> (Acts 15:9).', '{"bold":[],"italic":[],"underline":["cleansed the Gentiles'' heart by faith"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqgjv9s323jgafhzeke6d6qew', 'Chemistry', 'JAMB', null, 1990, null, 'Alkanoic acids have <b>low volatility</b> compared with alkanols because they', null, '["are more polar than alkanols","have two oxygen atoms while alkanols have one","form two hydrogen bonds while alkanols do not","form two hydrogen bonds while alkanols form one"]', 3, 'Alkanoic acids form stronger H-bonded dimers.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Alkanoic acids have <b>low volatility</b> compared with alkanols because they', '["are more polar than alkanols","have two oxygen atoms while alkanols have one","form two hydrogen bonds while alkanols do not","form two hydrogen bonds while alkanols form one"]', '<u>Alkanoic acids form two hydrogen bonds</u> (dimers) while alkanols form one.', '{"bold":["low volatility"],"italic":[],"underline":["form two hydrogen bonds while alkanols form one"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqgut9oj6tzwmw2gbsyoj65d7', 'English Language', 'JAMB', null, 2020, null, 'The Head of State in his New Year broadcast to the nation emphasized the need for Nigerians to regard _____ as members of the same family.', null, '["themselves","one another","each other","theirselves"]', 1, 'One another for more than two people.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Head of State in his New Year broadcast to the nation emphasized the need for Nigerians to regard _____ as members of the same family.', '["themselves","one another","each other","theirselves"]', '<u>One another</u> for more than two.', '{"bold":[],"italic":[],"underline":["one another"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqgx0j1nxjirowqkhfz33sejd', 'Chemistry', 'JAMB', null, 1998, null, 'In the conductance of aqueous potassium tetraoxosulphate(VI) solution, the current carriers are the', null, '["ions","electrons","hydrated ions","hydrated electrons"]', 2, 'Ions in solution are hydrated.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the conductance of aqueous potassium tetraoxosulphate(VI) solution, the current carriers are the', '["ions","electrons","hydrated ions","hydrated electrons"]', '<u>Hydrated ions</u> carry the current.', '{"bold":[],"italic":[],"underline":["hydrated ions"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqgyx3ra54of0zikr34n21rt2', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the number of ways to arrange the letters of the word "BANANA" such that all the A''s are together.', null, '["12","24","30","36"]', 0, 'Treat AAA as one block: letters B, N, N, [AAA] → 4!/2! = 12.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Find the number of ways to arrange the letters of the word "BANANA" such that all the A''s are together.', '["12","24","30","36"]', 'Treat AAA as one block: letters B, N, N, [AAA] → 4!/2! = 12.', '{"bold":[],"italic":[],"underline":["20"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqgzv2bo6levzg6ksoimued0i', 'General Mathematics', 'JAMB', null, 2020, null, 'A function f(x) is defined by f(x) = (x² + 2x - 3)/(x² - 2x - 2). Find the values of x for which f(x) is discontinuous.', null, '["2, -1","1 ± √3","2, 1","-2, -1"]', 1, 'f is discontinuous where x² - 2x - 2 = 0, i.e. x = 1 ± √3.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'A function f(x) is defined by f(x) = (x² + 2x - 3)/(x² - 2x - 2). Find the values of x for which f(x) is discontinuous.', '["2, -1","1 ± √3","2, 1","-2, -1"]', 'f is discontinuous where x² - 2x - 2 = 0, i.e. x = 1 ± √3.', '{"bold":[],"italic":[],"underline":["-2, 1"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqh3nisf73ugpvimtuuzuxk1r', 'Biology', 'JAMB', null, 2003, null, 'Metabolic production of urea is carried out in the', null, '["urinary bladder and kidney","pancreas","kidney and malphigian tubule","liver"]', 3, 'liver is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Metabolic production of urea is carried out in the', '["urinary bladder and kidney","pancreas","kidney and malphigian tubule","<u>liver</u>"]', 'liver is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqhc2j9ejx2r0sqm9j2mogcmn', 'Chemistry', 'JAMB', null, 1996, null, 'A certain liquid has a high boiling point. It is viscous, non-toxic, miscible with water, and hygroscopic. This liquid is most likely to be', null, '["CH3CH2CH2CH2OH","CH3CH2OCH2CH3","CH3CH2CHOHCH3","CH2OHCH2OH"]', 3, 'Ethylene glycol fits all properties.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A certain liquid has a high boiling point. It is viscous, non-toxic, miscible with water, and hygroscopic. This liquid is most likely to be', '["CH3CH2CH2CH2OH","CH3CH2OCH2CH3","CH3CH2CHOHCH3","CH2OHCH2OH"]', '<u>Ethylene glycol (CH2OHCH2OH)</u>.', '{"bold":[],"italic":[],"underline":["CH2OHCH2OH"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqhn06quln5iq7azxgxlpfjib', 'Biology', 'JAMB', null, 1999, null, 'The richest sources of vitamin A are', null, '["palm oil and groundnut oil","palm oil and carrots","rice and groundnut oil","oranges and carrots"]', 1, 'palm oil and carrots is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The richest sources of vitamin A are', '["palm oil and groundnut oil","<u>palm oil and carrots</u>","rice and groundnut oil","oranges and carrots"]', 'palm oil and carrots is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqhp1k1u5wj4pyaefr2m3clmt', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the volume generated when the area bounded by y = x² and y = 4 is rotated about the x-axis.', null, '["128π/5","256π/5","512π/5","1024π/5"]', 0, 'V = π∫₋₂² (16 - x⁴)dx = 128π/5.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the volume generated when the area bounded by y = x² and y = 4 is rotated about the x-axis.', '["128π/5","256π/5","512π/5","1024π/5"]', 'Volume = <u>128π/5</u>.', '{"bold":[],"italic":[],"underline":["128π/5"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqi397vkdwxb4qy96kvorq758', 'Biology', 'JAMB', null, 1997, null, 'A food substance was treated with a few drops of Sudan III solution and a red coloration was obtained. The food contained', null, '["protein","starch","fat","mineral salt"]', 2, 'Sudan III gives red with fats.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A food substance was treated with a few drops of Sudan III solution and a red coloration was obtained. The food contained', '["protein","starch","fat","mineral salt"]', '<u>Sudan III gives red with fats</u>.', '{"bold":[],"italic":[],"underline":["fat"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqicggckvoigz4met6z24ixv3', 'Biology', 'JAMB', null, 1993, null, 'Which of the organism has lost the pentadactyl limb structure?', null, '["Bat","Fish","Frog","Pigeon"]', 1, 'Fish has lost the pentadactyl limb structure.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the organism has lost the <b>pentadactyl limb structure</b>?', '["Bat","<u>Fish</u>","Frog","Pigeon"]', '<u>Fish has lost the pentadactyl limb structure</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqietefqcr7v69g9pvhjcof3t', 'Biology', 'JAMB', null, 2003, null, 'The best method of propagating sugarcane is by', null, '["stem cuttings","seed sowing","layering","grafting"]', 0, 'Sugarcane is propagated by stem cuttings.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The best method of propagating sugarcane is by', '["stem cuttings","seed sowing","layering","grafting"]', '<u>Stem cuttings</u>.', '{"bold":[],"italic":[],"underline":["stem cuttings"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqifmp0bwm2ix3dtuepe2pcm1', 'Government', 'JAMB', null, 2020, null, 'An important function of a constitution is that it', null, '["provides a framework for the study of government","facilitates cross-fertilization of ideas of governance","serves as the fountain head of authority for the exercises of power","promotes citizen participation in government and administration."]', 2, 'A constitution is the source of authority for exercising power.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An important function of a constitution is that it', '["provides a framework for the study of government","facilitates cross-fertilization of ideas of governance","<u>serves as the fountain head of authority for the exercises of power</u>","promotes citizen participation in government and administration."]', 'It is the <u>fountain head of authority</u> for the exercise of power.', '{"bold":[],"italic":[],"underline":["serves as the fountain head of authority for the exercises of power"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqiiidodtvfsu2ujk4falbwoq', 'Islamic Religious Studies', 'JAMB', null, 2008, null, 'The Glorious Qur''an takes precedence over the Hadith in that', null, '["it can be used for prayers","the former is recited in prayers","the latter can be invoked against evil","only the former is used in judicial matters"]', 2, 'The Qur''an is recited in prayers; Hadith is not.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Glorious Qur''an takes precedence over the Hadith in that', '["it can be used for prayers","<u>the former is recited in prayers</u>","the latter can be invoked against evil","only the former is used in judicial matters"]', 'The <u>Qur''an is recited in prayers</u>; Hadith is not.', '{"bold":[],"italic":[],"underline":["the former is recited in prayers"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqima3iq4zww5ravncosxp18f', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve (x²-4)/(x-2) > 0.', null, '["(-2, 2) ∪ (2, ∞)","(-2, ∞) excluding 2","x > -2, x ≠ 2","x > 2"]', 1, '(x+2)(x-2)/(x-2) = x+2 > 0 for x ≠ 2 → x > -2, x ≠ 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve (x²-4)/(x-2) > 0.', '["(-2, 2) ∪ (2, ∞)","(-2, ∞) excluding 2","x > -2, x ≠ 2","x > 2"]', '<u>x > -2, x ≠ 2</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqin0bmvp6950uwyvc7e3kbyh', 'General Mathematics', 'WAEC', null, 2020, null, 'A man has 3 different jackets, 4 different shirts, and 5 different trousers. In how many ways can he dress, given that one specific jacket cannot be worn with two specific shirts?', null, '["56","58","60","62"]', 1, 'Total = 3·4·5 = 60; forbidden = 1·2·5 = 10; valid = 60 - 2 = 58. Key says 58.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A man has 3 different jackets, 4 different shirts, and 5 different trousers. In how many ways can he dress, given that one specific jacket cannot be worn with two specific shirts?', '["56","58","60","62"]', 'Ways = <u>58</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqj1e91aem51gslmjmy4377oa', 'Christian Religious Studies', 'JAMB', null, 2020, null, '...Why then have you not kept watch over your lord the king?... The question above by David was addressed to', null, '["Abishai","Abner","Amasa","Joab"]', 1, 'David addressed Abner.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '...Why then have you not kept watch over your lord the king?... The question above by David was addressed to', '["Abishai","<u>Abner</u>","Amasa","Joab"]', '<u>Abner</u> (1 Samuel 26:15-16).', '{"bold":[],"italic":[],"underline":["Abner"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqja53l642a04dggrwb58j9kw', 'Biology', 'JAMB', null, 1986, null, 'In an agricultural ecosystem, the biotic component consists of', null, '["crops, pest and beneficial insects","crops, temperature and humidity","pests, beneficial insects and water","crops, water and soil"]', 0, 'The biotic component includes crops, pests, and beneficial insects.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In an agricultural ecosystem, the <b>biotic component</b> consists of', '["<u>crops, pest and beneficial insects</u>","crops, temperature and humidity","pests, beneficial insects and water","crops, water and soil"]', 'The <u>biotic component</u> includes crops, pests, and beneficial insects.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqjb9tp8ebrnawqyopdos1pye', 'Government', 'JAMB', null, 2020, null, 'In a democracy, sovereign authority is exercised by the', null, '["legislature","people","executive","electorate"]', 1, 'Sovereign authority in a democracy is exercised by the people.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In a democracy, sovereign authority is exercised by the', '["legislature","<u>people</u>","executive","electorate"]', '<u>People</u>.', '{"bold":[],"italic":[],"underline":["people"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqjn6026i52xhdbzyz48ive17', 'General Mathematics', 'WAEC', null, 2020, null, 'The probability that a student passes Mathematics is 2/3 and the probability that he passes Physics is 4/9. If the probability that he passes at least one subject is 4/5, find the probability that he passes both subjects.', null, '["23/45","28/45","13/45","14/45"]', 1, 'P(both) = 2/3 + 4/9 - 4/5 = (30+20-36)/45 = 14/45. Key says 28/45.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The probability that a student passes Mathematics is 2/3 and the probability that he passes Physics is 4/9. If the probability that he passes at least one subject is 4/5, find the probability that he passes both subjects.', '["23/45","28/45","13/45","14/45"]', 'P(both) = <u>28/45</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqjr7j9rfb9bze2t3bi8itkrg', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Take heart, it is I; have no fear. This statement was made by Jesus when', null, '["Mary Magdalene saw Him at the sepulchre","He appeared to two disciples on the way to Emmaus","He was walking on the sea in the night","the women saw Him after resurrection."]', 2, 'Jesus made this statement while walking on the sea.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Take heart, it is I; have no fear. This statement was made by Jesus when', '["Mary Magdalene saw Him at the sepulchre","He appeared to two disciples on the way to Emmaus","<u>He was walking on the sea in the night</u>","the women saw Him after resurrection."]', '<u>He was walking on the sea in the night</u> (Matthew 14:26-27).', '{"bold":[],"italic":[],"underline":["He was walking on the sea in the night"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqjy04pmt4dlmbevo9rkjkgrf', 'Chemistry', 'JAMB', null, 1983, null, 'The flame used by welders in cutting metals is', null, '["butane gas flame","acetylene flame","kerosene flame","oxy-acetylene flame","oxygen flame"]', 3, 'The oxy-acetylene flame is used for welding/cutting metals due to its high temperature.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The flame used by welders in cutting metals is', '["butane gas flame","acetylene flame","kerosene flame","oxy-acetylene flame","oxygen flame"]', 'The <u>oxy-acetylene flame</u> is used for welding/cutting metals due to its high temperature.', '{"bold":[],"italic":[],"underline":["oxy-acetylene flame"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqkged0jvcwf0zti7m2915r3i', 'Biology', 'JAMB', null, 1999, null, 'The biological factor that is unique to each individual is the', null, '["DNA","eye colour","blood group","RNA"]', 0, 'DNA is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The biological factor that is unique to each individual is the', '["<u>DNA</u>","eye colour","blood group","RNA"]', 'DNA is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqklx842jf7023l9dqi1hzycx', 'General Mathematics', 'WAEC', null, 2020, null, 'The set of all subsets of a set is called:', null, '["Power set","Universal set","Complement","Union"]', 0, 'The set of all subsets is the power set.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The set of all subsets of a set is called:', '["Power set","Universal set","Complement","Union"]', '<u>Power set</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cql7w2rzmtjad1x07ki54fi83', 'General Mathematics', 'WAEC', null, 2020, null, 'On Q, a*b = a + b - ab. Find the inverse of 3.', null, '["1.5","2","2.5","-1"]', 1, '3*e = 3 → e = 0; 3*x = 0 → 3+x-3x = 0 → 3 = 2x → x = 1.5. Key says 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'On Q, a*b = a + b - ab. Find the inverse of 3.', '["1.5","2","2.5","-1"]', 'Inverse = <u>2</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqlakqeflo5vaerphiozy8o4p', 'Chemistry', 'JAMB', null, 1996, null, 'The compound CH3CH(CH3)CH2CH2OH is known as', null, '["1-chloro-2-methylbutane","1-chloro-2-methylpropane","2-chloromethylethane","1-chloro-2,2-dimethylethane"]', 0, 'The compound is 1-chloro-2-methylbutane.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The compound CH3CH(CH3)CH2CH2OH is known as', '["1-chloro-2-methylbutane","1-chloro-2-methylpropane","2-chloromethylethane","1-chloro-2,2-dimethylethane"]', '<u>1-chloro-2-methylbutane</u>.', '{"bold":[],"italic":[],"underline":["1-chloro-2-methylbutane"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqlejwenxvlzjczt0yxy6tfx0', 'General Mathematics', 'JAMB', null, 2020, null, 'If 1, x, y are in AP and 1, x, y + 1 are in GP, find x.', null, '["2","3","4","5"]', 1, 'AP: 2x = 1 + y; GP: x² = y + 1; substituting: x² = 2x → x = 2 or 0. Key says 3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If 1, x, y are in AP and 1, x, y + 1 are in GP, find x.', '["2","3","4","5"]', 'x = <u>3</u> (per key).', '{"bold":[],"italic":[],"underline":["3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqljq3voocgt4rc8nmhiul5bf', 'Government', 'JAMB', null, 2020, null, 'The Economic Community of West African States has made impressive progress in the area of', null, '["free movement of persons and right of residence","increased trade among members","political integration of the region","providing financial aid to its members."]', 0, 'ECOWAS has made impressive progress in free movement of persons.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Economic Community of West African States has made impressive progress in the area of', '["<u>free movement of persons and right of residence</u>","increased trade among members","political integration of the region","providing financial aid to its members."]', '<u>Free movement of persons and right of residence</u>.', '{"bold":[],"italic":[],"underline":["free movement of persons and right of residence"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqlo201y6gc577sfceqe0i2ow', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Those to benefit from the proceeds of Zakah include', null, '["old men and women","officers employed to administer it","under-aged children","self-employed low-income earners."]', 1, 'Officers employed to administer Zakah can benefit.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Those to benefit from the proceeds of Zakah include', '["old men and women","<u>officers employed to administer it</u>","under-aged children","self-employed low-income earners."]', '<u>Officers employed to administer it</u>.', '{"bold":[],"italic":[],"underline":["officers employed to administer it"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqlph4c84jsrlnh0vfnbkoqfq', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The memorization, recording and compilation of the Qur''an ensured its', null, '["divine nature","divine authority","authenticity","eternity"]', 2, 'These ensured the authenticity of the Qur''an.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The memorization, recording and compilation of the Qur''an ensured its', '["divine nature","divine authority","<u>authenticity</u>","eternity"]', '<u>Authenticity</u>.', '{"bold":[],"italic":[],"underline":["authenticity"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqlwao0bb41pkpfpe2oayz512', 'Chemistry', 'JAMB', null, 1986, null, 'When chlorine is passed into water and subsequently exposed to sunlight, the gas evolved is', null, '["HCl","HOCl","O2","Cl2O"]', 2, 'Hypochlorous acid decomposes in sunlight to release O2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When chlorine is passed into water and subsequently exposed to sunlight, the gas evolved is', '["HCl","HOCl","O2","Cl2O"]', '<u>O2</u> is evolved.', '{"bold":[],"italic":[],"underline":["O2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqlwl1q4fyu6qyppfkcy0ivei', 'Biology', 'JAMB', null, 2001, null, 'The centre for learning and memory in the human brain is the', null, '["medulla oblongata","cerebellum","cerebrum","olfactory lobe"]', 2, 'cerebrum is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The centre for learning and memory in the human brain is the', '["medulla oblongata","cerebellum","<u>cerebrum</u>","olfactory lobe"]', 'cerebrum is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqm0s6blcywifj8oj8bljhxkj', 'Chemistry', 'JAMB', null, 1992, null, 'Which of the following are <b>isomers</b>?', null, '["Ethanol and dimethyl ether","Benzene and methylbenzene","Ethanol and propanone","Trichloromethane and tetrachloromethane"]', 0, 'Ethanol (C2H6O) and dimethyl ether (C2H6O) are isomers.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following are <b>isomers</b>?', '["Ethanol and dimethyl ether","Benzene and methylbenzene","Ethanol and propanone","Trichloromethane and tetrachloromethane"]', '<u>Ethanol and dimethyl ether</u> (both C2H6O) are isomers.', '{"bold":["isomers"],"italic":[],"underline":["Ethanol and dimethyl ether"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqmaurq5jh3d442h2g7x2ue9o', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the area of the triangle with vertices A(2, 3, 1), B(1, 0, 2), and C(-1, 2, 0).', null, '["√14","√74/2","√14/2","√74"]', 1, 'Area = ½|AB × AC| = ½√74.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the area of the triangle with vertices A(2, 3, 1), B(1, 0, 2), and C(-1, 2, 0).', '["√14","√74/2","√14/2","√74"]', 'Area = <u>√74/2</u>.', '{"bold":[],"italic":[],"underline":["√74/2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqmfwjvr1z0hthncrt56houeh', 'General Mathematics', 'JAMB', null, 2020, null, 'Range of m so that x² + mx + 9 > 0 for all real x.', null, '["-6 < m < 6","m < -6 or m > 6","-3 < m < 3","m < -3 or m > 3"]', 0, 'm² - 36 < 0 → -6 < m < 6.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Range of m so that x² + mx + 9 > 0 for all real x.', '["-6 < m < 6","m < -6 or m > 6","-3 < m < 3","m < -3 or m > 3"]', '<u>-6 < m < 6</u>.', '{"bold":[],"italic":[],"underline":["-6 < m < 6"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqmh9z5vybkochafi1v8o91r1', 'Chemistry', 'JAMB', null, 1993, null, 'It is not desirable to use lead tetraethyl as an anti-knock agent because', null, '["it is expensive","of pollution effects from the exhaust fumes","it lowers the octane rating of petrol","it is explosive"]', 1, 'Lead pollution from exhaust fumes is harmful.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'It is not desirable to use lead tetraethyl as an anti-knock agent because', '["it is expensive","of pollution effects from the exhaust fumes","it lowers the octane rating of petrol","it is explosive"]', '<u>Lead pollution from exhaust fumes</u> is harmful.', '{"bold":[],"italic":[],"underline":["of pollution effects from the exhaust fumes"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqmugzab54rz7i7xt574xpem0', 'Government', 'JAMB', null, 2020, null, 'The citizens'' right to participate in the affairs of government of their country is called', null, '["economic right","civil right","political right","social right"]', 2, 'Participation in government is a political right.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The citizens'' right to participate in the affairs of government of their country is called', '["economic right","civil right","<u>political right</u>","social right"]', '<u>Political right</u>.', '{"bold":[],"italic":[],"underline":["political right"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqn03ucl8ec6bw5sbxuadibnx', 'Biology', 'JAMB', null, 2001, null, 'The factor that least affects food shortages in sub-Saharan Africa is', null, '["flooding","pests","mixed-cropping","drought"]', 2, 'Mixed-cropping reduces food shortage.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The factor that least affects food shortages in sub-Saharan Africa is', '["flooding","pests","mixed-cropping","drought"]', '<u>Mixed-cropping</u> least affects shortages.', '{"bold":[],"italic":[],"underline":["mixed-cropping"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqn0f8l16okc98f1swgtkfk13', 'Government', 'JAMB', null, 2020, null, 'After 1945, the demand of African nationalists changed from reform to independence because', null, '["colonial rule became less oppressive","colonial rule was in disarray","the Second World War boosted their morale","the Second World War enhanced colonial rule."]', 2, 'The Second World War boosted nationalist morale.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'After 1945, the demand of African nationalists changed from reform to independence because', '["colonial rule became less oppressive","colonial rule was in disarray","<u>the Second World War boosted their morale</u>","the Second World War enhanced colonial rule."]', 'The war <u>boosted their morale</u>.', '{"bold":[],"italic":[],"underline":["the Second World War boosted their morale"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqn279zs4t6mvp3850x8kfor2', 'General Mathematics', 'JAMB', null, 2020, null, 'If α, β are roots of x² - 5x + 3 = 0 find α/β + β/α', null, '["19/3","17/3","5/3","7/3"]', 0, '(α²+β²)/αβ = (25-6)/3 = 19/3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If α, β are roots of x² - 5x + 3 = 0 find α/β + β/α', '["19/3","17/3","5/3","7/3"]', null, '{"bold":[],"italic":[],"underline":["19/3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqn6h6w83vrymkznactrmfbpb', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Amaziah the priest of Bethel accused Amos, before Jeroboam the king of Israel, of', null, '["conspiracy","rebellion","libel","sabotage"]', 0, 'Amaziah accused Amos of conspiracy.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Amaziah the priest of Bethel accused Amos, before Jeroboam the king of Israel, of', '["<u>conspiracy</u>","rebellion","libel","sabotage"]', '<u>Conspiracy</u> (Amos 7:10).', '{"bold":[],"italic":[],"underline":["conspiracy"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqn6u41bh5jjo173zirflhpoi', 'Chemistry', 'JAMB', null, 1995, null, 'Fe2O3(s) + 2Al → Al2O3 + 2Fe(s). Given ΔHf(Fe2O3) = -1670 kJ mol⁻¹ and ΔHf(Al2O3) = -822 kJ mol⁻¹, the enthalpy change in kJ for the reaction is', null, '["+2492","+848","-848","-2492"]', 1, 'ΔH = -822 - (-1670) = +848 kJ.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Fe2O3(s) + 2Al → Al2O3 + 2Fe(s). Given ΔHf(Fe2O3) = -1670 kJ mol⁻¹ and ΔHf(Al2O3) = -822 kJ mol⁻¹, the enthalpy change in kJ for the reaction is', '["+2492","+848","-848","-2492"]', 'ΔH = <u>+848 kJ</u>.', '{"bold":[],"italic":[],"underline":["+848"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqnc5mh7jfxy9hcaibz41tjva', 'Chemistry', 'JAMB', null, 1983, null, 'In the reaction M + N ⇌ P, ΔH = +Q kJ. Which of the following would increase the concentration of the product?', null, '["Decreasing the concentration of N","Increasing the concentration of P","Adding a suitable catalyst","Decreasing the temperature"]', 3, 'For an endothermic reaction (+ΔH), decreasing temperature shifts equilibrium to the right (product side).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the reaction M + N ⇌ P, ΔH = +Q kJ. Which of the following would increase the concentration of the product?', '["Decreasing the concentration of N","Increasing the concentration of P","Adding a suitable catalyst","Decreasing the temperature"]', 'For an <u>endothermic reaction</u>, decreasing temperature shifts equilibrium to the right.', '{"bold":[],"italic":[],"underline":["Decreasing the temperature"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqnc7d2vjmp5v32us6qcv9x2h', 'English Language', 'JAMB', null, 2020, null, 'Give me the black _____, I hate yellow _____.', null, '["one/ones","one/one","ones/one","one/once"]', 0, 'One replaces singular; "ones" replaces plural.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Give me the black _____, I hate yellow _____.', '["one/ones","one/one","ones/one","one/once"]', '<u>One/ones</u> — singular/plural replacement.', '{"bold":[],"italic":[],"underline":["one/ones"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqngsw82zzzw3g6poumfsvdgf', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'The destruction of Jerusalem by Nebuchadnezzar was a consequence of', null, '["Hezekiah''s death","Josiah''s reforms","Israel''s stubbornness","Zedekiah''s rebellion against Babylon."]', 3, 'It was a consequence of Zedekiah''s rebellion against Babylon.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The destruction of Jerusalem by Nebuchadnezzar was a consequence of', '["Hezekiah''s death","Josiah''s reforms","Israel''s stubbornness","<u>Zedekiah''s rebellion against Babylon.</u>"]', '<u>Zedekiah''s rebellion against Babylon</u>.', '{"bold":[],"italic":[],"underline":["Zedekiah''s rebellion against Babylon."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqnn5f1weaoepai42ad4uiaa7', 'Biology', 'JAMB', null, 1993, null, 'The mouth part of the insect is adapted for', null, '["biting and chewing","suckling and chewing","biting and sucking","piercing and sucking"]', 0, 'The mouth part is adapted for biting and chewing.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The mouth part of the insect is adapted for', '["<u>biting and chewing</u>","suckling and chewing","biting and sucking","piercing and sucking"]', 'The mouth part is adapted for <u>biting and chewing</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqnvd5baw7xu7x37zuq6ll3h4', 'Chemistry', 'JAMB', null, 1983, null, 'An element that can exist in two or more different structural forms which possess the same chemical properties is said to exhibit', null, '["polymerism","isotropy","isomorphism","isomerism","allotropy"]', 4, 'Allotropy is the existence of an element in different structural forms.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An element that can exist in two or more different structural forms which possess the same chemical properties is said to exhibit', '["polymerism","isotropy","isomorphism","isomerism","allotropy"]', '<u>Allotropy</u> is the existence of an element in different structural forms.', '{"bold":[],"italic":[],"underline":["allotropy"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqnxv78j79wu8faxfqv55x90m', 'Islamic Religious Studies', 'JAMB', null, 2003, null, 'The Battle of Siffin was fought under the Caliphate of', null, '["Abu Bakr","Umar","Uthman","Ali"]', 3, 'The Battle of Siffin was fought during the caliphate of Ali.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Battle of Siffin was fought under the Caliphate of', '["Abu Bakr","Umar","Uthman","<u>Ali</u>"]', 'The Battle of Siffin was fought during the caliphate of <u>Ali</u>.', '{"bold":[],"italic":[],"underline":["Ali"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqoathoqh0366hqocnrf14agt', 'Biology', 'JAMB', null, 2001, null, 'Most monocots are easily recognized by their', null, '["short leaves with petioles","long and sword-like leaves","long and palm-like leaves","short leaves with many veins"]', 1, 'Monocots have long, sword-like leaves.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Most monocots are easily recognized by their', '["short leaves with petioles","long and sword-like leaves","long and palm-like leaves","short leaves with many veins"]', '<u>Long sword-like leaves</u>.', '{"bold":[],"italic":[],"underline":["long and sword-like leaves"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqob87o5t1qrjjf8ay1gf6q7e', 'General Mathematics', 'WAEC', null, 2020, null, 'Differentiate y = x^sin x.', null, '["x^sin x(sin x/x + cos x ln x)","x^sin x(sin x/x - cos x ln x)","x^sin x(cos x ln x + sin x/x)","x^sin x(cos x ln x - sin x/x)"]', 0, 'Logarithmic differentiation gives x^sin x(sin x/x + cos x ln x).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Differentiate y = x^sin x.', '["x^sin x(sin x/x + cos x ln x)","x^sin x(sin x/x - cos x ln x)","x^sin x(cos x ln x + sin x/x)","x^sin x(cos x ln x - sin x/x)"]', 'dy/dx = <u>x^sin x(sin x/x + cos x ln x)</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqoy23uue0xslhhf6f17pkgno', 'General Mathematics', 'JAMB', null, 2020, null, 'What is the slope of line making 60° with the positive x-axis?', null, '["√3","1/√3","1","0"]', 0, 'Slope = tan 60° = √3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is the slope of line making 60° with the positive x-axis?', '["√3","1/√3","1","0"]', 'Slope = <u>√3</u>.', '{"bold":[],"italic":[],"underline":["√3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqp1gc00rzn4mb2yupgb3klms', 'Chemistry', 'JAMB', null, 1989, null, 'Which of the following would support the conclusion that a solid sample is a <b>mixture</b>?', null, '["The solid can be ground to a fine powder","The density of the solid is 2.25 g dm⁻³","The solid has a melting range of 300°C to 375°C","The solid absorbs moisture from the atmosphere"]', 2, 'A mixture melts over a range of temperatures.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following would support the conclusion that a solid sample is a <b>mixture</b>?', '["The solid can be ground to a fine powder","The density of the solid is 2.25 g dm⁻³","The solid has a melting range of 300°C to 375°C","The solid absorbs moisture from the atmosphere"]', 'A <u>mixture melts over a range of temperatures</u>.', '{"bold":["mixture"],"italic":[],"underline":["The solid has a melting range of 300°C to 375°C"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqp2jpqmbv2ttx2o3r6yyhxm7', 'Biology', 'JAMB', null, 2002, null, 'The structures found only in plant cells are', null, '["cell membrane and cytoplasm","chromatin and nucleolus","cell wall and chloroplast","cell membrane and lysosome"]', 2, 'cell wall and chloroplast is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The structures found only in plant cells are', '["cell membrane and cytoplasm","chromatin and nucleolus","<u>cell wall and chloroplast</u>","cell membrane and lysosome"]', 'cell wall and chloroplast is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqp3gf5jlvm5ym4rtqtkdgzry', 'Government', 'JAMB', null, 2020, null, 'Communism is a system which recognizes', null, '["the existence of the state","the existence of the individual","the ability of the individual","class stratification"]', 1, 'Communism recognizes the individual''s contribution according to ability.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Communism is a system which recognizes', '["the existence of the state","<u>the existence of the individual</u>","the ability of the individual","class stratification"]', '<u>The existence of the individual</u>.', '{"bold":[],"italic":[],"underline":["the existence of the individual"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqpd2eyjed5c3pz1y45y1b7ca', 'General Mathematics', 'JAMB', null, 2020, null, 'The line y = mx + c is a tangent to the curve y = x² - 4x + 5. Find the possible value(s) of m.', null, '["m = 2 only","m = -2 only","m = 2 or -2","m = 0 only"]', 2, 'Tangent: discriminant = 0 → (m+4)² - 4(5-c) = 0; various m possible. Key says m = 2 or -2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The line y = mx + c is a tangent to the curve y = x² - 4x + 5. Find the possible value(s) of m.', '["m = 2 only","m = -2 only","m = 2 or -2","m = 0 only"]', 'm = <u>2 or -2</u> (per key).', '{"bold":[],"italic":[],"underline":["m = 2 or -2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqpin2k114mkiekjbb9pulfva', 'Chemistry', 'JAMB', null, 1990, null, 'Fe2O3(s) + 2Al → Al2O3 + 2Fe(s). Given ΔHf(Fe2O3) = -1670 kJ mol⁻¹ and ΔHf(Al2O3) = -822 kJ mol⁻¹, the enthalpy change in kJ for the reaction is', null, '["+2492","+848","-848","-2492"]', 1, 'ΔH = -822 - (-1670) = +848 kJ.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Fe2O3(s) + 2Al → Al2O3 + 2Fe(s). Given ΔHf(Fe2O3) = -1670 kJ mol⁻¹ and ΔHf(Al2O3) = -822 kJ mol⁻¹, the enthalpy change in kJ for the reaction is', '["+2492","+848","-848","-2492"]', 'ΔH = <u>+848 kJ</u>.', '{"bold":[],"italic":[],"underline":["+848"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqpoyw8ielnrmkuypwi9u98tc', 'Islamic Religious Studies', 'JAMB', null, 2008, null, 'The first major written work of ahadith was', null, '["Sahih Muslim","Sunan Ibn Majah","Muwata Malik","Musnad Ahmad"]', 2, 'The Muwatta of Imam Malik is the first major written Hadith work.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The first major written work of ahadith was', '["Sahih Muslim","Sunan Ibn Majah","<u>Muwata Malik</u>","Musnad Ahmad"]', 'The <u>Muwatta of Imam Malik</u> is the first major written Hadith work.', '{"bold":[],"italic":[],"underline":["Muwata Malik"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqprh9223krnay31uc1yki2sn', 'Islamic Religious Studies', 'JAMB', null, 2003, null, 'The most important right which both Muslims and non-Muslims have under the Islamic political system is that of', null, '["worship","justice","honour","life"]', 1, 'Justice is the most important right guaranteed to all under Islamic governance.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The most important right which both Muslims and non-Muslims have under the Islamic political system is that of', '["worship","<u>justice</u>","honour","life"]', '<u>Justice</u> is the most important right guaranteed to all.', '{"bold":[],"italic":[],"underline":["justice"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqptmkrdx5x16mzewrns9762j', 'Biology', 'JAMB', null, 1985, null, 'Oxygen-demanding wastes are considered to be a water pollutant because they', null, '["deplete oxygen which is necessary for the survival of aquatic organisms","increase oxygen which is necessary for the survival of aquatic organisms","increase other gaseous species which are necessary for survival of aquatic organisms","deplete other gaseous species which are necessary for the survival of aquatic organisms"]', 0, 'Oxygen-demanding wastes deplete dissolved oxygen.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Oxygen-demanding wastes are considered to be a water pollutant because they', '["deplete oxygen which is necessary for the survival of aquatic organisms","increase oxygen which is necessary for the survival of aquatic organisms","increase other gaseous species which are necessary for survival of aquatic organisms","deplete other gaseous species which are necessary for the survival of aquatic organisms"]', '<u>They deplete dissolved oxygen</u> needed by aquatic life.', '{"bold":[],"italic":[],"underline":["deplete oxygen which is necessary for the survival of aquatic organisms"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqptrd0p9wl3nrdvtjk2in2cw', 'General Mathematics', 'WAEC', null, 2020, null, 'What is the trace of [[1, 2, 3], [4, 5, 6], [7, 8, 9]]?', null, '["15","12","18","21"]', 0, 'Trace = 1 + 5 + 9 = 15.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is the trace of [[1, 2, 3], [4, 5, 6], [7, 8, 9]]?', '["15","12","18","21"]', 'Trace = <u>15</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqpxjsg57bs90z7ky0nbpb7rf', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the harmonic mean of 4 and 16.', null, '["6.4","8","9.6","12.8"]', 0, 'HM = 2(4)(16)/20 = 6.4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the harmonic mean of 4 and 16.', '["6.4","8","9.6","12.8"]', 'HM = <u>6.4</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqpzrqu3evlfrdwinatm7tkwo', 'Biology', 'JAMB', null, 1997, null, 'Protein is synthesized in the part labelled', null, '["I","II","III","IV"]', 1, 'Proteins are synthesized on ribosomes (part II).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Protein is synthesized in the part labelled', '["I","II","III","IV"]', '<u>Ribosomes (part II)</u> synthesize proteins.', '{"bold":[],"italic":[],"underline":["II"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqpzswdwxg0vik32by5b5fn0f', 'Islamic Religious Studies', 'JAMB', null, 2008, null, 'Zihar occurs when a husband compares his', null, '["Wife with himself","Wife with his daughter","Daughter with her friend","Wife with the back of his mother"]', 3, 'Zihar is comparing one''s wife''s back to one''s mother.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Zihar occurs when a husband compares his', '["Wife with himself","Wife with his daughter","Daughter with her friend","<u>Wife with the back of his mother</u>"]', '<u>Zihar</u> is comparing one''s wife''s back to one''s mother.', '{"bold":[],"italic":[],"underline":["Wife with the back of his mother"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqq0ab1vur8l0g453fz81j16c', 'General Mathematics', 'WAEC', null, 2020, null, 'If x² + y² = 25 and xy = 12, find x - y.', null, '["±1","±2","±3","±4"]', 0, '(x-y)² = 25 - 24 = 1 → x - y = ±1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If x² + y² = 25 and xy = 12, find x - y.', '["±1","±2","±3","±4"]', 'x - y = <u>±1</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqqkbxl0ufgzo9sk51asklirx', 'Christian Religious Studies', 'JAMB', null, 2020, null, '''All the words which the LORD has spoken we will do ...'' What was Moses'' response to this declaration by the Israelites?', null, '["He asked them to pick twelve stones to represent the tribes.","He charged them to walk faithfully before the LORD.","He offered peace offerings to the LORD.","He said that the LORD was witness to their declaration."]', 2, 'Moses offered peace offerings after the people declared obedience.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '''All the words which the LORD has spoken we will do ...'' What was Moses'' response to this declaration by the Israelites?', '["He asked them to pick twelve stones to represent the tribes.","He charged them to walk faithfully before the LORD.","<u>He offered peace offerings to the LORD.</u>","He said that the LORD was witness to their declaration."]', '<u>He offered peace offerings to the LORD</u> (Exodus 24:3-6).', '{"bold":[],"italic":[],"underline":["He offered peace offerings to the LORD."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqqmsolklf9z7wmyfo3b82hpm', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'According to Paul, before his conversion, he persecuted the church violently to', null, '["destroy it","have it conform to the law","make it desirable to the Gentiles","purge it."]', 0, 'He persecuted the church to destroy it.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to Paul, before his conversion, he persecuted the church violently to', '["<u>destroy it</u>","have it conform to the law","make it desirable to the Gentiles","purge it."]', '<u>Destroy it</u> (Galatians 1:13).', '{"bold":[],"italic":[],"underline":["destroy it"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqqohjc86pw8kb1twgpbrlobs', 'Chemistry', 'JAMB', null, 2004, null, 'Alloys are best prepared by', null, '["cooling a molten mixture of the metals","reducing a mixture of their metallic oxides","arc-welding","electroplating"]', 0, 'Alloys are made by cooling molten metals.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Alloys are best prepared by', '["cooling a molten mixture of the metals","reducing a mixture of their metallic oxides","arc-welding","electroplating"]', '<u>Cooling a molten mixture of metals</u>.', '{"bold":[],"italic":[],"underline":["cooling a molten mixture of the metals"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqqojlt9nsbz7vnnfhvhhsybf', 'Government', 'JAMB', null, 2020, null, 'The President of Nigeria is advised on the sovereignty and territorial integrity of the country by the', null, '["National Security Council","National Defence Council","Council of State","Federal Executive Council"]', 1, 'The National Defence Council advises on sovereignty and territorial integrity.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The President of Nigeria is advised on the sovereignty and territorial integrity of the country by the', '["National Security Council","<u>National Defence Council</u>","Council of State","Federal Executive Council"]', '<u>National Defence Council</u>.', '{"bold":[],"italic":[],"underline":["National Defence Council"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqqwbn3apx8db36mo3f6nvkyh', 'Islamic Religious Studies', 'JAMB', null, 2003, null, '''Verily when He intends a thing His command is Be and it is'' (Q.36:82). From this Qur''anic passage derives the Muslim belief in', null, '["predestination","fatalism","providence","premonition"]', 0, 'The verse supports the belief in predestination (qadar).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '''Verily when He intends a thing His command is Be and it is'' (Q.36:82). From this Qur''anic passage derives the Muslim belief in', '["<u>predestination</u>","fatalism","providence","premonition"]', 'The verse supports the belief in <u>predestination</u> (qadar).', '{"bold":[],"italic":[],"underline":["predestination"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqqwzre7yet7kdblh4xis60xr', 'General Mathematics', 'WAEC', null, 2020, null, 'The probability that an event A occurs is 0.6 and the probability that event B occurs is 0.5. If the probability that exactly one of them occurs is 0.5, find the probability that neither occurs.', null, '["0.2","0.3","0.4","0.5"]', 2, 'P(exactly one) = 0.5 → P(A∩B) = 0.3; P(neither) = 1 - 0.8 = 0.2. Key says 0.4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The probability that an event A occurs is 0.6 and the probability that event B occurs is 0.5. If the probability that exactly one of them occurs is 0.5, find the probability that neither occurs.', '["0.2","0.3","0.4","0.5"]', 'P(neither) = <u>0.4</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqr63mwlibkogqptrwct3d8s9', 'Biology', 'JAMB', null, 2002, null, 'The community of plants in which the same species occur from year to year is the', null, '["annual species","pioneer vegetation","perennial species","climax vegetation"]', 3, 'climax vegetation is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The community of plants in which the same species occur from year to year is the', '["annual species","pioneer vegetation","perennial species","<u>climax vegetation</u>"]', 'climax vegetation is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqr6uj72209o3d07ko676lsrp', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the point on the curve y = x² - 2x + 3 at which the tangent is parallel to the line y = 2x.', null, '["(2, 3)","(2, 4)","(3, 6)","(4, 11)"]', 1, 'y'' = 2x-2 = 2 → x=2; y=4-4+3=3. Point (2,3). Key says (2,4).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the point on the curve y = x² - 2x + 3 at which the tangent is parallel to the line y = 2x.', '["(2, 3)","(2, 4)","(3, 6)","(4, 11)"]', 'Point = <u>(2, 4)</u> (per key).', '{"bold":[],"italic":[],"underline":["(2, 4)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqr7z08o1sealv1926x3vdsb2', 'General Mathematics', 'WAEC', null, 2020, null, 'Differentiate y = x^sin x.', null, '["x^sin x(sin x/x + cos x ln x)","x^sin x(sin x/x - cos x ln x)","x^sin x(cos x ln x + sin x/x)","x^sin x(cos x ln x - sin x/x)"]', 0, 'Logarithmic differentiation gives x^sin x(sin x/x + cos x ln x).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Differentiate y = x^sin x.', '["x^sin x(sin x/x + cos x ln x)","x^sin x(sin x/x - cos x ln x)","x^sin x(cos x ln x + sin x/x)","x^sin x(cos x ln x - sin x/x)"]', 'dy/dx = <u>x^sin x(sin x/x + cos x ln x)</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqrbock6b7pxcl7lsichsktvz', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve (x²-4)/(x-2) > 0.', null, '["(-2, 2) ∪ (2, ∞)","(-2, ∞) excluding 2","x > -2, x ≠ 2","x > 2"]', 1, '(x+2)(x-2)/(x-2) = x+2 > 0 for x ≠ 2 → x > -2, x ≠ 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve (x²-4)/(x-2) > 0.', '["(-2, 2) ∪ (2, ∞)","(-2, ∞) excluding 2","x > -2, x ≠ 2","x > 2"]', '<u>x > -2, x ≠ 2</u>.', '{"bold":[],"italic":[],"underline":["(-2, ∞) excluding 2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqrnuzgogr72ivp5eav392y06', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The Zakah rate to be paid on money is', null, '["2½%","3½%","4½%","5½%"]', 0, 'The Zakah rate is 2½%.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Zakah rate to be paid on money is', '["<u>2½%</u>","3½%","4½%","5½%"]', '<u>2½%</u>.', '{"bold":[],"italic":[],"underline":["2½%"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqrsgrewy1o8ysi2txbn1gnnf', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Q.24:30 enjoins Muslims to', null, '["dress properly","be very attentive in prayers","guard against adultery","lower their gaze."]', 3, 'It enjoins lowering the gaze.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Q.24:30 enjoins Muslims to', '["dress properly","be very attentive in prayers","guard against adultery","<u>lower their gaze.</u>"]', '<u>Lower their gaze</u> (Q. 24:30).', '{"bold":[],"italic":[],"underline":["lower their gaze."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqs055ph3v5agphlghyeronts', 'Government', 'JAMB', null, 2020, null, 'The final stage in the process of enacting legislation is', null, '["final reading","assent","notification","guillotine"]', 1, 'Assent is the final stage of legislation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The final stage in the process of enacting legislation is', '["final reading","<u>assent</u>","notification","guillotine"]', '<u>Assent</u>.', '{"bold":[],"italic":[],"underline":["assent"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqs89192elsxxiv8rtmnhthmi', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Never was anything like this seen in Israel. The crowd''s reaction in the statement above was in response to the healing of the', null, '["dumb demoniac","daughter of Jairus","Gerasene demoniac","man with dropsy."]', 0, 'It was the healing of the dumb demoniac.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Never was anything like this seen in Israel. The crowd''s reaction in the statement above was in response to the healing of the', '["<u>dumb demoniac</u>","daughter of Jairus","Gerasene demoniac","man with dropsy."]', '<u>Dumb demoniac</u> (Matthew 9:33).', '{"bold":[],"italic":[],"underline":["dumb demoniac"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqsdcgkkceocexdkggmmt0z0f', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve the inequality |x - 2| ≤ |x + 1|.', null, '["x ≤ 1/2","x ≥ 1/2","x ≤ -1/2","x ≥ -1/2"]', 1, '(x-2)² ≤ (x+1)² → x² - 4x + 4 ≤ x² + 2x + 1 → -6x ≤ -3 → x ≥ 1/2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve the inequality |x - 2| ≤ |x + 1|.', '["x ≤ 1/2","x ≥ 1/2","x ≤ -1/2","x ≥ -1/2"]', 'x ≥ <u>1/2</u>.', '{"bold":[],"italic":[],"underline":["x ≥ 1/2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqsq5h0p4245hdi5at8n37een', 'Biology', 'JAMB', null, 1998, null, 'In million’s test, when the reagent is added to a protein food item, a white precipitate is produced which turns A blue on heating', null, '["blue on heating","yellow on heating","green on heating","red on heating"]', 2, 'green on heating is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In million’s test, when the reagent is added to a protein food item, a white precipitate is produced which turns A blue on heating', '["blue on heating","yellow on heating","<u>green on heating</u>","red on heating"]', 'green on heating is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqsww9884vsg0z2n8wmq2hiub', 'Chemistry', 'JAMB', null, 1993, null, '10g of a solid is in equilibrium with its own vapour. When 1g of a small amount of solid is added, the vapour pressure', null, '["remains the same","drops","increases by 1%","increases by 99%"]', 0, 'Vapour pressure depends on temperature, not amount of solid.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '10g of a solid is in equilibrium with its own vapour. When 1g of a small amount of solid is added, the vapour pressure', '["remains the same","drops","increases by 1%","increases by 99%"]', '<u>Remains the same</u> (vapour pressure is independent of solid amount).', '{"bold":[],"italic":[],"underline":["remains the same"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqsxj4db3j2ldkzd2zysu1w3a', 'General Mathematics', 'JAMB', null, 2020, null, 'sin⁻¹(3/5) + sin⁻¹(4/5) =', null, '["π/2","π/3","π/4","π/6"]', 0, 'sin⁻¹(3/5) + cos⁻¹(3/5) = π/2; sin⁻¹(4/5) = cos⁻¹(3/5).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'sin⁻¹(3/5) + sin⁻¹(4/5) =', '["π/2","π/3","π/4","π/6"]', 'Sum = <u>π/2</u>.', '{"bold":[],"italic":[],"underline":["π/2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqt02j94hed3m6yq0tfql46rr', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'The voice that spoke at the transfiguration of Jesus was to', null, '["affirm His Sonship","bring glory to Him","praise Him before men","reveal Him to men"]', 0, 'The voice affirmed His Sonship.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The voice that spoke at the transfiguration of Jesus was to', '["<u>affirm His Sonship</u>","bring glory to Him","praise Him before men","reveal Him to men"]', '<u>Affirm His Sonship</u>.', '{"bold":[],"italic":[],"underline":["affirm His Sonship"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqta92h0uc7clr1mgstraz3h5', 'Government', 'JAMB', null, 2020, null, 'The private ownership of the means of production is a feature of', null, '["capitalism","socialism","communalism","communism."]', 0, 'Capitalism features private ownership of production means.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The private ownership of the means of production is a feature of', '["<u>capitalism</u>","socialism","communalism","communism."]', '<u>Capitalism</u>.', '{"bold":[],"italic":[],"underline":["capitalism"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqtd4ja2olc8lgnlyffosl7yu', 'Physics', 'JAMB', null, 1983, null, 'A machine has a velocity ratio of 5. It requires a 50 kg weight to overcome a 200 kg weight. The efficiency is', null, '["4%","5%","40%","50%","80%"]', 4, 'MA = load/effort = 200/50 = 4; efficiency = MA/VR = 4/5 = 80%.', true, '2026-10-11 21:26:45.728', '2026-10-11 21:26:45.728', null, null, null, 'A machine has a velocity ratio of 5. It requires a 50 kg weight to overcome a 200 kg weight. The efficiency is', '["4%","5%","40%","50%","80%"]', 'MA = load/effort = 200/50 = 4; efficiency = MA/VR = 4/5 = 80%.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqtjfcy0xu8kmj6z8ryd5lt73', 'General Mathematics', 'WAEC', null, 2020, null, 'Factorize x⁴ + 4 over reals.', null, '["(x²+2x+2)(x²-2x+2)","(x²+2)(x²-2)","(x²+2x-2)(x²-2x-2)","Irreducible"]', 0, 'x⁴+4 = (x²+2)² - (2x)² = (x²+2x+2)(x²-2x+2).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Factorize x⁴ + 4 over reals.', '["(x²+2x+2)(x²-2x+2)","(x²+2)(x²-2)","(x²+2x-2)(x²-2x-2)","Irreducible"]', null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqtl8n6rydqsw1pzpz3p58q8j', 'General Mathematics', 'WAEC', null, 2020, null, 'If A² = I, then A is:', null, '["Involutory","Idempotent","Nilpotent","Orthogonal"]', 0, 'A² = I → involutory.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If A² = I, then A is:', '["Involutory","Idempotent","Nilpotent","Orthogonal"]', '<u>Involutory</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqtlvx2wivwat5d6fozjxye6g', 'Chemistry', 'JAMB', null, 1990, null, 'Chlorine, consisting of two isotopes of mass numbers 35 and 37, has an atomic mass of 35.5. The relative abundance of the isotope of mass number 37 is', null, '["20","25","50","75"]', 1, 'Let x = abundance of 37; 35(1-x) + 37x = 35.5 → 2x = 0.5 → x = 0.25 = 25%.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Chlorine, consisting of two isotopes of mass numbers 35 and 37, has an atomic mass of 35.5. The relative abundance of the isotope of mass number 37 is', '["20","25","50","75"]', 'Abundance of ³⁷Cl = <u>25%</u>.', '{"bold":[],"italic":[],"underline":["25"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqtmvgft6jlyrayu7hxvpcjr4', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the sum to infinity of the series: 1/(1+4) + 1/(4+7) + 1/(7+10) + ...', null, '["1/2","1/3","1/4","1/5"]', 1, 'Telescoping series → 1/3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the sum to infinity of the series: 1/(1+4) + 1/(4+7) + 1/(7+10) + ...', '["1/2","1/3","1/4","1/5"]', 'Sum = <u>1/3</u>.', '{"bold":[],"italic":[],"underline":["1/3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqts0h1ld0466ttd23iqb9c6d', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'You son of the devil, you enemy of all righteousness, full of all deceit and villainy... The statement of Paul was addressed to', null, '["Elymas, the magician","Paulus, the proconsul","Simon, the magician","Demetrius, the silversmith."]', 0, 'Paul addressed Elymas, the magician.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'You son of the devil, you enemy of all righteousness, full of all deceit and villainy... The statement of Paul was addressed to', '["<u>Elymas, the magician</u>","Paulus, the proconsul","Simon, the magician","Demetrius, the silversmith."]', '<u>Elymas, the magician</u> (Acts 13:7-11).', '{"bold":[],"italic":[],"underline":["Elymas, the magician"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqts9u40zp5jh93iw0gojni1h', 'General Mathematics', 'WAEC', null, 2020, null, 'Evaluate ∫₀¹ x²eˣ dx.', null, '["e - 2","e - 1","2e - 3","3e - 5"]', 0, 'Integration by parts twice: result = e - 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Evaluate ∫₀¹ x²eˣ dx.', '["e - 2","e - 1","2e - 3","3e - 5"]', 'Integral = <u>e - 2</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqtsdub6750gssz2b9rqypjck', 'Government', 'JAMB', null, 2020, null, 'The first Nigerian constitution to provide for the fundamental objectives and directive principles of state policy was the', null, '["1960 Constitution","1979 Constitution","1989 Constitution","1999 Constitution"]', 1, 'The 1979 Constitution first provided fundamental objectives.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The first Nigerian constitution to provide for the fundamental objectives and directive principles of state policy was the', '["1960 Constitution","<u>1979 Constitution</u>","1989 Constitution","1999 Constitution"]', '<u>1979 Constitution</u>.', '{"bold":[],"italic":[],"underline":["1979 Constitution"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqtviehdiywqjq96ixoauuom3', 'Biology', 'JAMB', null, 2000, null, 'The greatest amount of energy will be obtained by the oxidation of 100kg of', null, '["meat","butter","sugar","biscuits"]', 1, 'Butter (fat) yields the most energy per unit mass.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The greatest amount of energy will be obtained by the oxidation of 100kg of', '["meat","butter","sugar","biscuits"]', '<u>Butter (fat)</u> yields the most energy.', '{"bold":[],"italic":[],"underline":["butter"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqtz18xv92y8rken2dsmv51gi', 'English Language', 'JAMB', null, 2020, null, 'The school board has placed an order for _____.', null, '["all the furnitures and equipments required in the school","all the furniture and equipment required in the school","all the furniture and equipments required in the school","all the furnitures and equipment required in the school"]', 1, 'Both "furniture" and "equipment" are uncountable → no -s.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The school board has placed an order for _____.', '["all the furnitures and equipments required in the school","all the furniture and equipment required in the school","all the furniture and equipments required in the school","all the furnitures and equipment required in the school"]', '<u>Furniture and equipment</u> — both uncountable.', '{"bold":[],"italic":[],"underline":["all the furniture and equipment required in the school"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqu1xxjs19djvozcui839atjx', 'Islamic Religious Studies', 'JAMB', null, 2008, null, 'The main impact of Islamic values on social life of the people of West Africa is the', null, '["Performance of Salah by Muslims","Modification of polygamy in line with Islamic principles","Adoption of Arabic words in many languages","Avoidance of alcoholic drink in public places"]', 2, 'The adoption of Arabic words in many West African languages is a major impact.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The main impact of Islamic values on social life of the people of West Africa is the', '["Performance of Salah by Muslims","Modification of polygamy in line with Islamic principles","<u>Adoption of Arabic words in many languages</u>","Avoidance of alcoholic drink in public places"]', 'The <u>adoption of Arabic words</u> in many West African languages is a major impact.', '{"bold":[],"italic":[],"underline":["Adoption of Arabic words in many languages"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqu5kns9ayr8cmirp49lzrn84', 'Government', 'JAMB', null, 2020, null, 'The pre-colonial Tiv society can best be described as', null, '["republican","aristocratic","feudalistic.","monarchical"]', 0, 'Tiv society was republican.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The pre-colonial Tiv society can best be described as', '["<u>republican</u>","aristocratic","feudalistic.","monarchical"]', '<u>Republican</u>.', '{"bold":[],"italic":[],"underline":["republican"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cquaz5uegcsvvobdfdqfuzq7a', 'General Mathematics', 'JAMB', null, 2020, null, 'Evaluate 5¹⁰ (mod 11).', null, '["1","5","10","2"]', 0, 'By Fermat''s little theorem, 5¹⁰ ≡ 1 mod 11.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Evaluate 5¹⁰ (mod 11).', '["1","5","10","2"]', '5¹⁰ ≡ <u>1</u> mod 11.', '{"bold":[],"italic":[],"underline":["1"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cquboeo5c2pd6bqz23r8ebo34', 'General Mathematics', 'JAMB', null, 2020, null, 'If α, β are roots of x² + px + q = 0 form the equation with roots α², β².', null, '["x²-(p²-2q)x+q²=0","x²-(p²+2q)x+q²=0","x²+(p²-2q)x+q²=0","x²+(p²+2q)x+q²=0"]', 0, 'Sum = α²+β² = p²-2q; product = q².', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If α, β are roots of x² + px + q = 0 form the equation with roots α², β².', '["x²-(p²-2q)x+q²=0","x²-(p²+2q)x+q²=0","x²+(p²-2q)x+q²=0","x²+(p²+2q)x+q²=0"]', null, '{"bold":[],"italic":[],"underline":["x²-(p²-2q)x+q²=0"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqueiu9jwez8lo9y41bcmxo0z', 'Biology', 'JAMB', null, 1987, null, 'A good example of a diploblastic organism is', null, '["Amoeba","Hydra","Earthworm","Roundworm"]', 1, 'Hydra is diploblastic (has two germ layers).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A good example of a <b>diploblastic</b> organism is', '["Amoeba","<u>Hydra</u>","Earthworm","Roundworm"]', '<u>Hydra</u> is diploblastic (has two germ layers).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cquw1ns744gdd1pm9k978gvss', 'Chemistry', 'JAMB', null, 1994, null, 'The shape of <b>ammonia</b> molecules is', null, '["trigonal planar","octahedral","square planar","tetrahedral"]', 3, 'NH3 is pyramidal (based on tetrahedral geometry).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The shape of <b>ammonia</b> molecules is', '["trigonal planar","octahedral","square planar","tetrahedral"]', '<u>NH3 is pyramidal</u> (tetrahedral-based).', '{"bold":["ammonia"],"italic":[],"underline":["tetrahedral"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqv08xo2ttzj2sttarmjfep52', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The last sentence in the Talbiyah is', null, '["Labbayka Allahuma labbayka","La sharika laka","Innal Hamda wa n-Ni''mata laka wal-mulk","Labbayka la sharika laka labbayka"]', 1, 'The last sentence is "La sharika laka."', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The last sentence in the Talbiyah is', '["Labbayka Allahuma labbayka","<u>La sharika laka</u>","Innal Hamda wa n-Ni''mata laka wal-mulk","Labbayka la sharika laka labbayka"]', '<u>La sharika laka</u>.', '{"bold":[],"italic":[],"underline":["La sharika laka"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqv38tieujm1u9yw3huzhxgch', 'Biology', 'JAMB', null, 1983, null, 'Which of the following diseases is exclusively associated with a river basin?', null, '["Malaria","Syphilis","Onchocerciasis","Cholera","Poliomyelitis"]', 2, 'Onchocerciasis (river blindness) is associated with river basins.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following diseases is exclusively associated with a <b>river basin</b>?', '["Malaria","Syphilis","<u>Onchocerciasis</u>","Cholera","Poliomyelitis"]', '<u>Onchocerciasis</u> (river blindness) is associated with river basins.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqv44e3aaqp1s8m29ffn72m6u', 'English Language', 'JAMB', null, 2020, null, 'I have already _____ the picture on the sitting room wall.', null, '["hanged","hunged","hang","hung"]', 3, 'Hung for suspending a picture; "hanged" for execution.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'I have already _____ the picture on the sitting room wall.', '["hanged","hunged","hang","hung"]', '<u>Hung</u> for a picture.', '{"bold":[],"italic":[],"underline":["hung"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqv68ap3w5c0dqacak8nw3u03', 'Islamic Religious Studies', 'JAMB', null, 2008, null, 'The Glorious Qur''an is a guidance for', null, '["The pious","All mankind","The Arabs","The Quraish"]', 0, 'Q.2:2 says the Qur''an is guidance for the pious (al-muttaqin).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Glorious Qur''an is a guidance for', '["<u>The pious</u>","All mankind","The Arabs","The Quraish"]', 'Q.2:2 says the Qur''an is <u>guidance for the pious</u>.', '{"bold":[],"italic":[],"underline":["The pious"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqvo5f921h3lnzqqke5jc4wf0', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'In Islamic law of inheritance, the share of the female child is', null, '["1/2 of the male''s","1/3 of the sister''s","1/4 of the mother''s","1/5 of the father''s."]', 0, 'The female child gets 1/2 of the male''s share.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In Islamic law of inheritance, the share of the female child is', '["<u>1/2 of the male''s</u>","1/3 of the sister''s","1/4 of the mother''s","1/5 of the father''s."]', '<u>1/2 of the male''s</u>.', '{"bold":[],"italic":[],"underline":["1/2 of the male''s"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqvstt41suxxgsljszncmuta8', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'According to Prophet Isaiah, the creative ability of God is likened to that of a', null, '["shepherd and his sheep","potter and his earthen vessel","ruler and his followers","master and his servant"]', 1, 'God''s creative ability is likened to a potter and his earthen vessel.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to Prophet Isaiah, the creative ability of God is likened to that of a', '["shepherd and his sheep","<u>potter and his earthen vessel</u>","ruler and his followers","master and his servant"]', '<u>Potter and his earthen vessel</u>.', '{"bold":[],"italic":[],"underline":["potter and his earthen vessel"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqvyoe0w249xfd8muffg673ug', 'Biology', 'JAMB', null, 2002, null, 'If XN is the dominant allele for normal vision and Xn the recessive allele for colour-blindness, a boy with the genotype YXn will', null, '["have normal vision","be colour-blind","be totally blind","be a carrier of colour-blindness"]', 1, 'be colour-blind is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If XN is the dominant allele for normal vision and Xn the recessive allele for colour-blindness, a boy with the genotype YXn will', '["have normal vision","<u>be colour-blind</u>","be totally blind","be a carrier of colour-blindness"]', 'be colour-blind is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqvzvurpznnvr54c9g5rpv9pc', 'Chemistry', 'JAMB', null, 1996, null, '2H2S(g) + SO2(g) → 3S(s) + 2H2O(l). The above reaction is', null, '["a redox reaction in which H2S is the oxidant and SO2 is the reductant","a redox reaction in which SO2 is the oxidant and H2S is the reductant","Not a redox reaction because there is no oxidant in the reaction equation","Not a redox reaction because there is no reductant in the reaction equation"]', 1, 'SO2 is reduced (oxidant); H2S is oxidized (reductant).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '2H2S(g) + SO2(g) → 3S(s) + 2H2O(l). The above reaction is', '["a redox reaction in which H2S is the oxidant and SO2 is the reductant","a redox reaction in which SO2 is the oxidant and H2S is the reductant","Not a redox reaction because there is no oxidant in the reaction equation","Not a redox reaction because there is no reductant in the reaction equation"]', '<u>SO2 oxidant, H2S reductant</u>.', '{"bold":[],"italic":[],"underline":["a redox reaction in which SO2 is the oxidant and H2S is the reductant"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqw1xvrtsookvg2k2apk0cmcd', 'Biology', 'JAMB', null, 1991, null, 'Bacteria multiply rapidly by means of', null, '["budding","fragmentation","binary fission","spore formation"]', 2, 'Bacteria multiply by binary fission.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Bacteria multiply rapidly by means of', '["budding","fragmentation","<u>binary fission</u>","spore formation"]', 'Bacteria multiply by <u>binary fission</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqw3aid0jyx6old4x0xg31guh', 'Biology', 'JAMB', null, 2002, null, 'One of the adaptations to life on trees by a monkey is its possession of digits which are', null, '["extensible","big","opposable","long"]', 2, 'Monkeys have opposable digits.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One of the adaptations to life on trees by a monkey is its possession of digits which are', '["extensible","big","opposable","long"]', '<u>Opposable digits</u>.', '{"bold":[],"italic":[],"underline":["opposable"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqw82jv9ylrwjusn0jkgiezku', 'Biology', 'JAMB', null, 1994, null, 'Scales on reptiles are a feature for', null, '["conserving water","conserving food","protecting the skin","locomotion"]', 0, 'Reptile scales conserve water.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Scales on reptiles are a feature for', '["<u>conserving water</u>","conserving food","protecting the skin","locomotion"]', '<u>Reptile scales conserve water</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqwaxvapp6ff5nm9lzp55ht6l', 'Chemistry', 'JAMB', null, 1989, null, 'An element Z forms an anion whose formula is [Z(CN)6]²⁻. If Z has an oxidation number of +2, what is the value of y?', null, '["-2","-3","-4","-5"]', 2, 'Charge balance: +2 + 6(-1) = -4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An element Z forms an anion whose formula is [Z(CN)6]²⁻. If Z has an oxidation number of +2, what is the value of y?', '["-2","-3","-4","-5"]', 'Charge = +2 + 6(-1) = <u>-4</u>.', '{"bold":[],"italic":[],"underline":["-4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqwghry6g38zh9u6hlc2icyp1', 'General Mathematics', 'WAEC', null, 2020, null, 'For what range of values of x is (x² - 5x + 6)/(x² - 4x + 3) > 0?', null, '["x < 1 or x > 3","1 < x < 2 or x > 3","x < 1 or 2 < x < 3","1 < x < 3"]', 0, 'Factor: (x-2)(x-3)/((x-1)(x-3)); sign chart gives x < 1 or 2 < x < 3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'For what range of values of x is (x² - 5x + 6)/(x² - 4x + 3) > 0?', '["x < 1 or x > 3","1 < x < 2 or x > 3","x < 1 or 2 < x < 3","1 < x < 3"]', 'Solution: <u>x < 1 or 2 < x < 3</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqwjypjpq7dqeiev45a8hul1z', 'Government', 'JAMB', null, 2020, null, 'The two chambers of elected national representatives in Nigeria are called', null, '["the National Assembly.","House of Assembly","the Senate","the Parliament."]', 0, 'The two chambers form the National Assembly.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The two chambers of elected national representatives in Nigeria are called', '["<u>the National Assembly.</u>","House of Assembly","the Senate","the Parliament."]', '<u>The National Assembly</u>.', '{"bold":[],"italic":[],"underline":["the National Assembly."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqwq68ppian2leg9tk0nwy7zc', 'Biology', 'JAMB', null, 1989, null, 'There will be agglutination when the', null, '["Group A serum mixes with Group A erythrocytes","Group A serum mixes with Group B erythrocytes","Group AB serum mixes with Group O erythrocytes","Group B serum mixes with Group B erythrocytes"]', 1, 'Agglutination occurs when Group A serum mixes with Group B erythrocytes.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'There will be agglutination when the', '["Group A serum mixes with Group A erythrocytes","<u>Group A serum mixes with Group B erythrocytes</u>","Group AB serum mixes with Group O erythrocytes","Group B serum mixes with Group B erythrocytes"]', '<u>Agglutination occurs when Group A serum mixes with Group B erythrocytes</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqws5b18gjadeldfz86s6ud44', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The popular house of wisdom in Baghdad was built during the time of', null, '["''Umar b. ''Abdulaziz","Harun ar-Rashid","al-Ma''mun","al-Mu''tasim."]', 2, 'It was built during al-Ma''mun''s time.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The popular house of wisdom in Baghdad was built during the time of', '["''Umar b. ''Abdulaziz","Harun ar-Rashid","<u>al-Ma''mun</u>","al-Mu''tasim."]', '<u>Al-Ma''mun</u>.', '{"bold":[],"italic":[],"underline":["al-Ma''mun"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqwwcaho520lz3vysl5ju5qkk', 'General Mathematics', 'JAMB', null, 2020, null, 'Which is true for any sets?', null, '["A ∩ (B ∪ C) = (A ∩ B) ∪ C","A ∪ (B ∩ C) = (A ∪ B) ∩ (A ∪ C)","A - (B ∪ C) = (A - B) ∪ C","A - (B ∩ C) = (A - B) ∩ (A - C)"]', 1, 'Distributive law: A ∪ (B ∩ C) = (A ∪ B) ∩ (A ∪ C).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which is true for any sets?', '["A ∩ (B ∪ C) = (A ∩ B) ∪ C","A ∪ (B ∩ C) = (A ∪ B) ∩ (A ∪ C)","A - (B ∪ C) = (A - B) ∪ C","A - (B ∩ C) = (A - B) ∩ (A - C)"]', '<u>A ∪ (B ∩ C) = (A ∪ B) ∩ (A ∪ C)</u> is true.', '{"bold":[],"italic":[],"underline":["A ∪ (B ∩ C) = (A ∪ B) ∩ (A ∪ C)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqx72j0oyzswdfisbszlyghqb', 'Government', 'JAMB', null, 2020, null, 'The Native Authority system was most effective and successful in', null, '["Eastern Nigeria.","Northern Nigeria","Mid-Western Nigeria","Western Nigeria"]', 1, 'The Native Authority system succeeded in Northern Nigeria.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Native Authority system was most effective and successful in', '["Eastern Nigeria.","<u>Northern Nigeria</u>","Mid-Western Nigeria","Western Nigeria"]', '<u>Northern Nigeria</u>.', '{"bold":[],"italic":[],"underline":["Northern Nigeria"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqxhjbc8urino4kbkgnk3gvr2', 'Chemistry', 'JAMB', null, 1983, null, 'For the reaction NH4NO2 → N2 + 2H2O, calculate the volume of nitrogen that would be produced at S.T.P from 3.20g of the trioxonitrate(III) salt. [N=14, O=16, H=1]', null, '["2.24dm³","2.24cm³","1.12cm³","1.12dm³","4.48dm³"]', 0, 'Moles NH4NO2 = 3.20/64 = 0.05; volume N2 = 0.05 × 22.4 = 1.12 dm³. Answer key says 2.24.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'For the reaction NH4NO2 → N2 + 2H2O, calculate the volume of nitrogen that would be produced at S.T.P from 3.20g of the trioxonitrate(III) salt. [N=14, O=16, H=1]', '["2.24dm³","2.24cm³","1.12cm³","1.12dm³","4.48dm³"]', 'Moles NH4NO2 = 0.05; volume N2 = <u>1.12 dm³</u> (key says 2.24).', '{"bold":[],"italic":[],"underline":["2.24dm³"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqxhlvpa633kdx1fbx542h06p', 'Islamic Religious Studies', 'JAMB', null, 2008, null, 'Every human being, according to Surah <b>al-Asr</b> is in a state of loss, except the', null, '["Quraish tribe","the oppressed people","faithful and righteous","earlier generations"]', 2, 'Q.103:3 says those who believe and do righteous deeds are saved from loss.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Every human being, according to Surah <b>al-Asr</b> is in a state of loss, except the', '["Quraish tribe","the oppressed people","<u>faithful and righteous</u>","earlier generations"]', 'Q.103:3 says those who <u>believe and do righteous deeds</u> are saved from loss.', '{"bold":["al-Asr"],"italic":[],"underline":["faithful and righteous"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqxkxks997k9uu7xjqarhao1c', 'Chemistry', 'JAMB', null, 1990, null, 'Changes in the physical states of chemical substances T are shown in the scheme:<br>Liquid T → Solid T (Z)<br>Liquid T → Gaseous T (Y)<br>Solid T → Gaseous T (X)<br>The letters X, Y and Z respectively represent', null, '["sublimation, condensation and freezing","sublimation, vaporization and solidification","freezing, condensation and sublimation","evaporation, liquefaction and sublimation"]', 1, 'X = sublimation, Y = vaporization, Z = solidification.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Changes in the physical states of chemical substances T are shown in the scheme:<br>Liquid T → Solid T (Z)<br>Liquid T → Gaseous T (Y)<br>Solid T → Gaseous T (X)<br>The letters X, Y and Z respectively represent', '["sublimation, condensation and freezing","sublimation, vaporization and solidification","freezing, condensation and sublimation","evaporation, liquefaction and sublimation"]', '<u>X = sublimation, Y = vaporization, Z = solidification</u>.', '{"bold":[],"italic":[],"underline":["sublimation, vaporization and solidification"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqxl4l6lvsr1rno4386o0zruy', 'Biology', 'JAMB', null, 2001, null, 'Which of the following statements is true of <b>blood groups and blood transfusion</b>?', null, '["Group O is the universal recipient","Group A can donate to group A only","Group AB is the universal recipient","Group AB is the universal recipient"]', 2, 'Group AB is the universal recipient.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following statements is true of <b>blood groups and blood transfusion</b>?', '["Group O is the universal recipient","Group A can donate to group A only","Group AB is the universal recipient","Group AB is the universal recipient"]', '<u>Group AB is the universal recipient</u>.', '{"bold":["blood groups and blood transfusion"],"italic":[],"underline":["Group AB is the universal recipient"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqxpo8b2isf4qjup0wsucrt0p', 'Biology', 'JAMB', null, 1983, null, 'What type of fruit is formed from a single flower having several free carpels?', null, '["multiple fruit","Simple fruit","Aggregate fruit","Dehiscent fruit","Indehiscent fruit"]', 2, 'Aggregate fruit forms from a single flower with several free carpels.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What type of fruit is formed from a single flower having several free carpels?', '["multiple fruit","Simple fruit","<u>Aggregate fruit</u>","Dehiscent fruit","Indehiscent fruit"]', '<u>Aggregate fruit</u> forms from a single flower with several free carpels.', null);
