insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqyd8p4k6bcr1c81y7kwgfzj6', 'Islamic Religious Studies', 'JAMB', null, 2011, null, '[Arabic verse] The verse above is in relation to the', null, '["standardization of the Glorious Qur''an","preservation of the Glorious Qur''an","compilation of the Glorious Qur''an","arrangement of the Glorious Qur''an"]', 1, 'Q.15:9 promises divine preservation of the Qur''an.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '[Arabic verse] The verse above is in relation to the', '["standardization of the Glorious Qur''an","<u>preservation of the Glorious Qur''an</u>","compilation of the Glorious Qur''an","arrangement of the Glorious Qur''an"]', 'Q.15:9 promises <u>divine preservation</u> of the Qur''an.', '{"bold":[],"italic":[],"underline":["preservation of the Glorious Qur''an"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqyf201jex39mc4h8jzpg99dt', 'General Mathematics', 'JAMB', null, 2020, null, 'Convert 0.3125₁₀ to base two.', null, '["0.0101₂","0.0111₂","0.1011₂","0.1101₂"]', 3, '0.3125 × 2 = 0.625 (0); 0.625 × 2 = 1.25 (1); 0.25 × 2 = 0.5 (0); 0.5 × 2 = 1.0 (1) → 0.0101₂. Key says 0.1101₂.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Convert 0.3125₁₀ to base two.', '["0.0101₂","0.0111₂","0.1011₂","0.1101₂"]', '0.3125₁₀ = <u>0.0101₂</u> (key says 0.1101₂).', '{"bold":[],"italic":[],"underline":["0.1101₂"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqygu6u2bre7uq41zw4lwvc3h', 'Government', 'JAMB', null, 2020, null, 'A major source of revenue in the post-1976 local government in Nigeria is', null, '["Grants and loans","The joint state-local government account","Internally generated revenue","The federation account."]', 3, 'The federation account is the major LG revenue source.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A major source of revenue in the post-1976 local government in Nigeria is', '["Grants and loans","The joint state-local government account","Internally generated revenue","<u>The federation account.</u>"]', '<u>The federation account</u>.', '{"bold":[],"italic":[],"underline":["The federation account."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqyjd4ygidtjj5yinhdqe54bz', 'General Mathematics', 'JAMB', null, 2020, null, 'For what value of k will the equation kx² - 6x + 1 = 0 have roots that are equal in magnitude but opposite in sign?', null, '["0","6","-6","No such value exists"]', 0, 'Sum of roots = 6/k = 0 → k = ∞, so no finite k. Roots opposite sign → sum = 0 → 6/k = 0 impossible. Key says 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'For what value of k will the equation kx² - 6x + 1 = 0 have roots that are equal in magnitude but opposite in sign?', '["0","6","-6","No such value exists"]', 'k = <u>0</u> (per key).', '{"bold":[],"italic":[],"underline":["0"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqyl06ur68ud65qglpmpvn85g', 'Biology', 'JAMB', null, 2000, null, 'The older fossil-bearing rocks, in contrast to the more recent ones, are more likely to contain', null, '["animals rather than plant remains","invertebrates rather than birds","flowering plants rather than mosses","reptiles rather than fishes"]', 1, 'Older rocks contain invertebrates rather than birds.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The older fossil-bearing rocks, in contrast to the more recent ones, are more likely to contain', '["animals rather than plant remains","invertebrates rather than birds","flowering plants rather than mosses","reptiles rather than fishes"]', '<u>Invertebrates rather than birds</u>.', '{"bold":[],"italic":[],"underline":["invertebrates rather than birds"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqymg3kfbxu94w7emdq6fjr0f', 'Biology', 'JAMB', null, 1997, null, 'Protein is synthesized in the part labelled', null, '["I","II","III","IV"]', 1, 'Proteins are synthesized on ribosomes (part II).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Protein is synthesized in the part labelled', '["I","II","III","IV"]', '<u>Ribosomes (part II)</u> synthesize proteins.', '{"bold":[],"italic":[],"underline":["II"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqyqstjiei49e34mcmyfsc7us', 'Chemistry', 'JAMB', null, 1987, null, 'The structure of <b>benzoic acid</b> is', null, '["C6H5COOH","C6H5OH","C6H5CHO","C6H5COCH3"]', 0, 'Benzoic acid is C6H5COOH.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The structure of <b>benzoic acid</b> is', '["C6H5COOH","C6H5OH","C6H5CHO","C6H5COCH3"]', '<u>Benzoic acid is C6H5COOH</u>.', '{"bold":["benzoic acid"],"italic":[],"underline":["C6H5COOH"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqyroyci90im5l4el08zyeaol', 'Chemistry', 'JAMB', null, 1983, null, 'Which of the following mixtures would result in a solution of <b>pH greater than 7</b>?', null, '["25.00 cm³ of 0.05 M H2SO4 and 25.00 cm³ of 0.50 M Na2CO3","25.00 cm³ of 0.50 M H2SO4 and 25.00 cm³ of 0.10 M NaHCO3","25.00 cm³ of 0.11 M H2SO4 and 25.00 cm³ of 0.10 M NaOH","25.00 cm³ of 0.11 M H2SO4 and 50.00 cm³ of 0.50 M NaOH","25.00 cm³ of 0.25 M H2SO4 and 50.00 cm³ of 0.20 M NaOH"]', 0, 'Excess Na2CO3 (a base) makes the solution alkaline.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following mixtures would result in a solution of <b>pH greater than 7</b>?', '["25.00 cm³ of 0.05 M H2SO4 and 25.00 cm³ of 0.50 M Na2CO3","25.00 cm³ of 0.50 M H2SO4 and 25.00 cm³ of 0.10 M NaHCO3","25.00 cm³ of 0.11 M H2SO4 and 25.00 cm³ of 0.10 M NaOH","25.00 cm³ of 0.11 M H2SO4 and 50.00 cm³ of 0.50 M NaOH","25.00 cm³ of 0.25 M H2SO4 and 50.00 cm³ of 0.20 M NaOH"]', '<u>Excess Na2CO3</u> makes the solution alkaline.', '{"bold":["pH greater than 7"],"italic":[],"underline":["25.00 cm³ of 0.05 M H2SO4 and 25.00 cm³ of 0.50 M Na2CO3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqyrrakcpktoe19ll3zl9tk90', 'Government', 'JAMB', null, 2020, null, 'The civil service embraces all workers in', null, '["all private corporations","public and private companies","government ministries","public corporations"]', 2, 'The civil service comprises workers in government ministries.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The civil service embraces all workers in', '["all private corporations","public and private companies","<u>government ministries</u>","public corporations"]', '<u>Government ministries</u>.', '{"bold":[],"italic":[],"underline":["government ministries"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqz7t60i65trvdrs5ci8prkvh', 'General Mathematics', 'JAMB', null, 2020, null, 'What is the trace of [[1, 2, 3], [4, 5, 6], [7, 8, 9]]?', null, '["15","12","18","21"]', 0, 'Trace = 1 + 5 + 9 = 15.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is the trace of [[1, 2, 3], [4, 5, 6], [7, 8, 9]]?', '["15","12","18","21"]', 'Trace = <u>15</u>.', '{"bold":[],"italic":[],"underline":["15"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqzbunpo57gzud7stqh32k8qm', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Two Christian virtues to be learned in the story of the Good Samaritan are', null, '["kindness and fairness","justice and humility","compassion and humility","compassion and mercy"]', 3, 'The Good Samaritan teaches compassion and mercy.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Two Christian virtues to be learned in the story of the Good Samaritan are', '["kindness and fairness","justice and humility","compassion and humility","<u>compassion and mercy</u>"]', '<u>Compassion and mercy</u>.', '{"bold":[],"italic":[],"underline":["compassion and mercy"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqzc09yuaf5a8oo0tumy9v6f4', 'General Mathematics', 'JAMB', null, 2020, null, 'Water is poured into a conical tank at the rate of 3 m³/min. The tank has a vertical height of 10 m and a top radius of 5 m. Find the rate at which the water level is rising when the water is 4 m deep.', null, '["3/(4π) m/min","4/(3π) m/min","3/(2π) m/min","3/(3π) m/min"]', 0, 'V = (1/3)πr²h with r = h/2; dV/dt = 3; dh/dt = 3/(4π) when h = 4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Water is poured into a conical tank at the rate of 3 m³/min. The tank has a vertical height of 10 m and a top radius of 5 m. Find the rate at which the water level is rising when the water is 4 m deep.', '["3/(4π) m/min","4/(3π) m/min","3/(2π) m/min","3/(3π) m/min"]', 'Rate = <u>3/(4π) m/min</u>.', '{"bold":[],"italic":[],"underline":["3/(4π) m/min"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqzdzdwytlx32fyb9cpoo6c5v', 'Chemistry', 'JAMB', null, 1986, null, '10cm³ of hydrogen fluoride gas reacts with 5cm³ of dinitrogen difluoride gas (N2F2) to form 10cm³ of a single gas. Which of the following is the most likely equation for the reaction?', null, '["HF + N2F2 → N2HF3","2HF + N2F2 → 2NHF2","2HF + N2F2 → N2HF4","HF + 2N2F2 → N2HF4"]', 1, 'Volume ratio 2:1:2 matches 2HF + N2F2 → 2NHF2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '10cm³ of hydrogen fluoride gas reacts with 5cm³ of dinitrogen difluoride gas (N2F2) to form 10cm³ of a single gas. Which of the following is the most likely equation for the reaction?', '["HF + N2F2 → N2HF3","2HF + N2F2 → 2NHF2","2HF + N2F2 → N2HF4","HF + 2N2F2 → N2HF4"]', '<u>2HF + N2F2 → 2NHF2</u> matches the volume ratio.', '{"bold":[],"italic":[],"underline":["2HF + N2F2 → 2NHF2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqzh7bhf3v0fjxn6qly7cqjjg', 'Biology', 'JAMB', null, 2003, null, 'An example of a <b>caryopsis</b> is', null, '["coconut","tomato","guava","maize grain"]', 3, 'Maize grain is a caryopsis.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An example of a <b>caryopsis</b> is', '["coconut","tomato","guava","maize grain"]', '<u>Maize grain</u> is a caryopsis.', '{"bold":["caryopsis"],"italic":[],"underline":["maize grain"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cqzqfu3kpcz65r1egjkh2947l', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve (3x - 1)/(x - 2) ≥ 2.', null, '["x ≤ -3 or x ≥ 3","x ≥ 3 or x < 2","x ≤ -3 or x > 2","x ≤ 3 or x > 2"]', 2, '(3x-1)/(x-2) - 2 ≥ 0 → (x+3)/(x-2) ≥ 0 → x ≤ -3 or x > 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Solve (3x - 1)/(x - 2) ≥ 2.', '["x ≤ -3 or x ≥ 3","x ≥ 3 or x < 2","x ≤ -3 or x > 2","x ≤ 3 or x > 2"]', '(3x-1)/(x-2) - 2 ≥ 0 → (x+3)/(x-2) ≥ 0 → x ≤ -3 or x > 2.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cr05biv20o6gdkh5xbrbyd70c', 'General Mathematics', 'JAMB', null, 2020, null, 'Two events A and B are such that P(A) = 0.4, P(B) = 0.3 and P(A ∪ B) = 0.6. Find P(A|B).', null, '["1/2","1/3","1/4","1/5"]', 1, 'P(A ∩ B) = 0.4+0.3-0.6 = 0.1; P(A|B) = 0.1/0.3 = 1/3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Two events A and B are such that P(A) = 0.4, P(B) = 0.3 and P(A ∪ B) = 0.6. Find P(A|B).', '["1/2","1/3","1/4","1/5"]', 'P(A|B) = <u>1/3</u>.', '{"bold":[],"italic":[],"underline":["1/3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cr09yepv5hm1rpvqpn7i37vr4', 'General Mathematics', 'JAMB', null, 2020, null, 'If sin θ = 12/13 and cos φ = 3/5, where θ is obtuse and φ is acute, find sin(θ - φ).', null, '["56/65","-56/65","16/65","-16/65"]', 0, 'cos θ = -5/13; sin φ = 4/5; sin(θ-φ) = (12/13)(3/5) - (-5/13)(4/5) = 36/65 + 20/65 = 56/65.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If sin θ = 12/13 and cos φ = 3/5, where θ is obtuse and φ is acute, find sin(θ - φ).', '["56/65","-56/65","16/65","-16/65"]', 'sin(θ - φ) = <u>56/65</u>.', '{"bold":[],"italic":[],"underline":["56/65"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cr0bf4mhgl93eobhml9e5eg11', 'Islamic Religious Studies', 'JAMB', null, 2008, null, 'The importance of Salah as listed in Q.29:45 includes', null, '["Prohibition of shameful and evil deeds","Making invocations regularly","Prohibition of cheating in measures","Prohibition of hoarding"]', 0, 'Q.29:45 says Salah prevents shameful and evil deeds.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The importance of Salah as listed in Q.29:45 includes', '["<u>Prohibition of shameful and evil deeds</u>","Making invocations regularly","Prohibition of cheating in measures","Prohibition of hoarding"]', 'Q.29:45 says <u>Salah prevents shameful and evil deeds</u>.', '{"bold":[],"italic":[],"underline":["Prohibition of shameful and evil deeds"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cr0bguehig81bgxcpdyo4ddgt', 'General Mathematics', 'JAMB', null, 2020, null, 'If Iₙ = ∫sinⁿx dx, show that nIₙ = -sinⁿ⁻¹x cos x + (n-1)Iₙ₋₂. Then find ∫sin⁴x dx.', null, '["3x/8 - sin 2x/4 + sin 4x/32 + C","3x/8 - sin 2x/4 - sin 4x/32 + C","3x/8 + sin 2x/4 - sin 4x/32 + C","3x/8 + sin 2x/4 + sin 4x/32 + C"]', 0, 'Reduction formula: ∫sin⁴x dx = 3x/8 - sin 2x/4 + sin 4x/32 + C.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If Iₙ = ∫sinⁿx dx, show that nIₙ = -sinⁿ⁻¹x cos x + (n-1)Iₙ₋₂. Then find ∫sin⁴x dx.', '["3x/8 - sin 2x/4 + sin 4x/32 + C","3x/8 - sin 2x/4 - sin 4x/32 + C","3x/8 + sin 2x/4 - sin 4x/32 + C","3x/8 + sin 2x/4 + sin 4x/32 + C"]', 'Integral = <u>3x/8 - sin 2x/4 + sin 4x/32 + C</u>.', '{"bold":[],"italic":[],"underline":["3x/8 - sin 2x/4 + sin 4x/32 + C"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cr0eziizpjg1risku8ltxdjlf', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'In Thessalonians, believers are taught that at the Second Coming, the dead in Christ will', null, '["rise first","rise last","be judged first","be judged last."]', 0, 'The dead in Christ will rise first.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In Thessalonians, believers are taught that at the Second Coming, the dead in Christ will', '["<u>rise first</u>","rise last","be judged first","be judged last."]', '<u>Rise first</u> (1 Thessalonians 4:16).', '{"bold":[],"italic":[],"underline":["rise first"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cr0g1cduxukgp80kovqb8ab35', 'Islamic Religious Studies', 'JAMB', null, 2003, null, 'A feature which is common to the Shari''ah and the common law is', null, '["rigidity","flexibility","credibility","inimitability"]', 0, 'Both Shari''ah and common law share a degree of rigidity in their application.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A feature which is common to the Shari''ah and the common law is', '["<u>rigidity</u>","flexibility","credibility","inimitability"]', 'Both Shari''ah and common law share a degree of <u>rigidity</u>.', '{"bold":[],"italic":[],"underline":["rigidity"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cr0g7claxo2j1mzt8uq6a1r4d', 'English Language', 'JAMB', null, 2020, null, 'Sorry, I can''t go to the theatre with you as I have _____ to do.', null, '["many works","a work","plenty work","much work"]', 3, 'Work meaning tasks is uncountable → "much work".', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Sorry, I can''t go to the theatre with you as I have _____ to do.', '["many works","a work","plenty work","much work"]', '<u>Much work</u> — "work" is uncountable here.', '{"bold":[],"italic":[],"underline":["much work"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cr0s3gvue0pden1t52ek05pcf', 'Biology', 'JAMB', null, 2004, null, 'The opening of the stoma is controlled by the', null, '["presence of guard cells","decrease in solute concentration in the guard cells","increase in solute concentration in the guard cells","presence of a pore. Use the diagram below to answer questions 3 and 4"]', 0, 'presence of guard cells is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The opening of the stoma is controlled by the', '["<u>presence of guard cells</u>","decrease in solute concentration in the guard cells","increase in solute concentration in the guard cells","presence of a pore. Use the diagram below to answer questions 3 and 4"]', 'presence of guard cells is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cr14ceuumdeknz5ogiljkk6ud', 'General Mathematics', 'WAEC', null, 2020, null, 'If f(x) = |x|³, find f''(0).', null, '["0","1","-1","Does not exist"]', 0, 'f(x) = |x|³ is differentiable at 0; f''(0) = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If f(x) = |x|³, find f''(0).', '["0","1","-1","Does not exist"]', 'f''(0) = <u>0</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cr1bbesmldifb0zzm7ism2gpy', 'General Mathematics', 'JAMB', null, 2020, null, 'Evaluate (12 + 15) × (9 - 4) (mod 11).', null, '["6","3","8","9"]', 1, '27 × 5 = 135 = 12×11 + 3, so the result is 3 (mod 11).', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Evaluate (12 + 15) × (9 - 4) (mod 11).', '["6","3","8","9"]', '27 × 5 = 135 = 12×11 + 3, so the result is 3 (mod 11).', '{"bold":[],"italic":[],"underline":["7"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cr1iqbkyiupi52ygmntkny2hu', 'Chemistry', 'JAMB', null, 1993, null, 'Water can be identified by the use of', null, '["anhydrous copper(II) tetraoxosulphate(VI)","anhydrous sodium trioxocarbonate(IV)","potassium heptaoxochromate(VII)","copper(II) trioxocarbonate(IV)"]', 0, 'Anhydrous CuSO4 turns blue with water.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Water can be identified by the use of', '["anhydrous copper(II) tetraoxosulphate(VI)","anhydrous sodium trioxocarbonate(IV)","potassium heptaoxochromate(VII)","copper(II) trioxocarbonate(IV)"]', '<u>Anhydrous CuSO4 turns blue</u> with water.', '{"bold":[],"italic":[],"underline":["anhydrous copper(II) tetraoxosulphate(VI)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cr1jnrvxdfa69v72bwblx2mdt', 'Chemistry', 'JAMB', null, 1996, null, 'Addition of aqueous ammonia to a solution of Zn²⁺ gives a white precipitate which dissolves in an excess of ammonia because', null, '["zinc is amphoteric","zinc hydroxide is readily soluble","zinc forms a complex which is readily soluble in excess ammonia","ammonia solution is a strong base"]', 2, 'Zn(OH)2 dissolves in excess NH3 forming [Zn(NH3)4]²⁺.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Addition of aqueous ammonia to a solution of Zn²⁺ gives a white precipitate which dissolves in an excess of ammonia because', '["zinc is amphoteric","zinc hydroxide is readily soluble","zinc forms a complex which is readily soluble in excess ammonia","ammonia solution is a strong base"]', '<u>Zn forms a soluble complex</u> with excess NH3.', '{"bold":[],"italic":[],"underline":["zinc forms a complex which is readily soluble in excess ammonia"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cr1zship16192f98av5ww3jrs', 'Chemistry', 'JAMB', null, 1985, null, 'The general formula of an <b>alkyl halide</b> (where X represents the halide) is', null, '["CnH2n-2X","CnH2n+1X","CnH2n+2X","CnH2nX"]', 3, 'Alkyl halides have the general formula CnH2n+1X.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The general formula of an <b>alkyl halide</b> (where X represents the halide) is', '["CnH2n-2X","CnH2n+1X","CnH2n+2X","CnH2nX"]', '<u>Alkyl halides have the general formula CnH2n+1X</u>.', '{"bold":["alkyl halide"],"italic":[],"underline":["CnH2nX"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cr25lqnk45qw7xzpw8nxmoikf', 'Chemistry', 'JAMB', null, 2019, null, 'Monds process is used in extraction of which metal?', null, '["Zinc","Copper","Nickel","Chromium"]', 2, 'Mond''s process is used for the extraction and purification of nickel.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Mond''s process is used in extraction of which metal?', '["Zinc","Copper","<u>Nickel</u>","Chromium"]', '<u>Mond''s process</u> is used for the extraction and purification of nickel.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cr27a2nl6ivrp6ov0viez72ow', 'Government', 'JAMB', null, 2020, null, 'A common feature of the earlier political parties in Nigeria was that they', null, '["were formed by the government","started as socio-cultural organizations","were backed by the colonialists.","were non-elitist in nature"]', 1, 'Earlier parties started as socio-cultural organizations.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A common feature of the earlier political parties in Nigeria was that they', '["were formed by the government","<u>started as socio-cultural organizations</u>","were backed by the colonialists.","were non-elitist in nature"]', '<u>Started as socio-cultural organizations</u>.', '{"bold":[],"italic":[],"underline":["started as socio-cultural organizations"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cr2arzqimv1i26qry28qugvh8', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The uniqueness of the Glorious Qur''an, according to Q.39:28, lies in the fact that it is', null, '["highly educative","in brief form","revealed piecemeal","revealed in Arabic."]', 3, 'It is revealed in Arabic.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The uniqueness of the Glorious Qur''an, according to Q.39:28, lies in the fact that it is', '["highly educative","in brief form","revealed piecemeal","<u>revealed in Arabic.</u>"]', '<u>Revealed in Arabic</u> (Q. 39:28).', '{"bold":[],"italic":[],"underline":["revealed in Arabic."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cr2axwg5hyy12lyes287yds8u', 'English Language', 'JAMB', null, 2020, null, 'The highly appreciative audience clapped _____ hands and showered _____.', null, '["their/encomiums","its/encomiums","their/invectives","its/invectives"]', 0, 'Their agrees with audience; "encomiums" = praise.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The highly appreciative audience clapped _____ hands and showered _____.', '["their/encomiums","its/encomiums","their/invectives","its/invectives"]', '<u>Their/encomiums</u> — praise.', '{"bold":[],"italic":[],"underline":["their/encomiums"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cr2etx0uaf0amrykgi5czejgt', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'In Thessalonians, Paul advises believers awaiting the coming of the Lord to put on the', null, '["armour of hope","helmet of righteousness","breast plate of faith","breast plate of salvation."]', 2, 'Believers should put on the breastplate of faith.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In Thessalonians, Paul advises believers awaiting the coming of the Lord to put on the', '["armour of hope","helmet of righteousness","<u>breast plate of faith</u>","breast plate of salvation."]', '<u>Breast plate of faith</u> (1 Thessalonians 5:8).', '{"bold":[],"italic":[],"underline":["breast plate of faith"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cr2pxowgobnewnxwf7t2ngbp4', 'Government', 'JAMB', null, 2020, null, 'A meeting of the legislature is usually brought to an end with', null, '["a dissolution","an adjournment","suspension","a prorogation"]', 1, 'A legislative meeting ends with an adjournment.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A meeting of the legislature is usually brought to an end with', '["a dissolution","<u>an adjournment</u>","suspension","a prorogation"]', '<u>Adjournment</u>.', '{"bold":[],"italic":[],"underline":["an adjournment"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cr2qxwzfd82qlyyjwrdif3bmk', 'Christian Religious Studies', 'JAMB', null, 2020, null, '''All the words which the LORD has spoken we will do ...'' What was Moses'' response to this declaration by the Israelites?', null, '["He asked them to pick twelve stones to represent the tribes.","He charged them to walk faithfully before the LORD.","He offered peace offerings to the LORD.","He said that the LORD was witness to their declaration."]', 2, 'Moses offered peace offerings after the people declared obedience.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '''All the words which the LORD has spoken we will do ...'' What was Moses'' response to this declaration by the Israelites?', '["He asked them to pick twelve stones to represent the tribes.","He charged them to walk faithfully before the LORD.","<u>He offered peace offerings to the LORD.</u>","He said that the LORD was witness to their declaration."]', '<u>He offered peace offerings to the LORD</u> (Exodus 24:3-6).', '{"bold":[],"italic":[],"underline":["He offered peace offerings to the LORD."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cr31popmjyj58mwxhmlcyjhzp', 'Islamic Religious Studies', 'JAMB', null, 2020, null, '''Surely, we created man of the best stature, then, we reduced him to the lowest of the low save those who believe and good works''. This quotation is from Surat', null, '["al-Asr","al-Alaq","at-Tin","al-Qadr"]', 2, 'This quotation is from Surat at-Tin.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '''Surely, we created man of the best stature, then, we reduced him to the lowest of the low save those who believe and good works''. This quotation is from Surat', '["al-Asr","al-Alaq","<u>at-Tin</u>","al-Qadr"]', '<u>At-Tin</u> (Q. 95:4-6).', '{"bold":[],"italic":[],"underline":["at-Tin"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cr33ho0p3kga705tsm6j1zh4y', 'Biology', 'JAMB', null, 1993, null, 'Which path does sound entering the human ear follow?', null, '["Oval window-ossicles-ear drum","ear drum-oval window-ossicles","Ear drum-ossicles-oval window","Ossicles-ear drum-oval window"]', 2, 'Sound path: Ear drum → Ossicles → Oval window.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which path does sound entering the human ear follow?', '["Oval window-ossicles-ear drum","ear drum-oval window-ossicles","<u>Ear drum-ossicles-oval window</u>","Ossicles-ear drum-oval window"]', 'Sound path: <u>Ear drum → Ossicles → Oval window</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cr38we8f0yufdwpzh3cgpbv8u', 'General Mathematics', 'JAMB', null, 2020, null, 'If log₁₀((6x - 5)/(x - 3)) = 1, find the value of x.', null, '["5","25/4","8","10"]', 1, '(6x-5)/(x-3) = 10 → 4x = 25 → x = 25/4.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'If log₁₀((6x - 5)/(x - 3)) = 1, find the value of x.', '["5","25/4","8","10"]', '(6x-5)/(x-3) = 10 → 4x = 25 → x = 25/4.', '{"bold":[],"italic":[],"underline":["7"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cr3lc233rlbi186ro49q3nzzg', 'General Mathematics', 'JAMB', null, 2020, null, 'The points (2, 5), (4, 7), and (6, 9) lie on a:', null, '["Circle","Parabola","Straight line","Hyperbola"]', 2, 'Slope is constant (1), so collinear.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The points (2, 5), (4, 7), and (6, 9) lie on a:', '["Circle","Parabola","Straight line","Hyperbola"]', '<u>Straight line</u>.', '{"bold":[],"italic":[],"underline":["Straight line"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cr3oza4nrrwr6vp6h482ilgcm', 'General Mathematics', 'JAMB', null, 2020, null, 'Evaluate 2⁵ + 3⁵ (mod 5).', null, '["0","1","2","3"]', 0, '2⁵ = 32 ≡ 2; 3⁵ = 243 ≡ 3; sum ≡ 5 ≡ 0 mod 5.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Evaluate 2⁵ + 3⁵ (mod 5).', '["0","1","2","3"]', '2⁵ + 3⁵ ≡ 2 + 3 = <u>0</u> mod 5.', '{"bold":[],"italic":[],"underline":["0"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cr410s1uunptpldswszb1p6q4', 'Chemistry', 'JAMB', null, 1998, null, 'A solid begins to melt when', null, '["constituent particles acquire a greater kinetic energy","energy of vibration of particles of the solid is less than the intermolecular forces","constituent particles acquire energy above the average kinetic energy","energy of vibration of particles of the solid equals the intermolecular forces"]', 3, 'Melting occurs when vibrational energy equals intermolecular forces.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A solid begins to melt when', '["constituent particles acquire a greater kinetic energy","energy of vibration of particles of the solid is less than the intermolecular forces","constituent particles acquire energy above the average kinetic energy","energy of vibration of particles of the solid equals the intermolecular forces"]', '<u>Vibrational energy equals intermolecular forces</u> at melting.', '{"bold":[],"italic":[],"underline":["energy of vibration of particles of the solid equals the intermolecular forces"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cr4aufk1x9wen6eu93hk0zybg', 'Chemistry', 'JAMB', null, 1995, null, 'In the reaction IO3⁻ + 5I⁻ + 6H⁺ → 3I2 + 3H2O, the oxidizing agent is', null, '["H⁺","I⁻","IO3⁻","I2"]', 2, 'IO3⁻ is reduced (I goes from +5 to 0).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the reaction IO3⁻ + 5I⁻ + 6H⁺ → 3I2 + 3H2O, the oxidizing agent is', '["H⁺","I⁻","IO3⁻","I2"]', '<u>IO3⁻ is reduced</u>, so it is the oxidizing agent.', '{"bold":[],"italic":[],"underline":["IO3⁻"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cr4iw0e1xatg2qht9gipemamn', 'Biology', 'JAMB', null, 2003, null, 'The part of the mammalian digestive system where <b>absorption of nutrients</b> takes place is the', null, '["duodenum","colon","ileum","oesophagus"]', 2, 'The ileum absorbs nutrients.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The part of the mammalian digestive system where <b>absorption of nutrients</b> takes place is the', '["duodenum","colon","ileum","oesophagus"]', '<u>Ileum</u> absorbs nutrients.', '{"bold":["absorption of nutrients"],"italic":[],"underline":["ileum"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cr4m4tssbcid0lv5tmgwiprr1', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve √(x+2) > x.', null, '["[-2, 2)","[-2, 2]","[0, 2)","[-2, 0)"]', 0, 'x+2 > x² and x+2 ≥ 0 → x²-x-2 < 0 → -1 < x < 2, and x ≥ -2 → [-2, 2) covers. But also need √(x+2) > x for x<0. So [-2, 2).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve √(x+2) > x.', '["[-2, 2)","[-2, 2]","[0, 2)","[-2, 0)"]', '<u>x ∈ [-2, 2)</u>.', '{"bold":[],"italic":[],"underline":["[-2, 2)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cr4nhmei16kce1wrdf78pefnf', 'Government', 'JAMB', null, 2020, null, 'Who was the political head of the Old Oyo Empire?', null, '["Bashorun","Aremo","Oyomesi","Alaafin."]', 3, 'The Alaafin was the political head of the Old Oyo Empire.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Who was the political head of the Old Oyo Empire?', '["Bashorun","Aremo","Oyomesi","<u>Alaafin.</u>"]', '<u>Alaafin</u>.', '{"bold":[],"italic":[],"underline":["Alaafin."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cr4peyd69r8bjsr2iy4monxas', 'Chemistry', 'JAMB', null, 1987, null, 'What mass of magnesium would be obtained by passing a current of 2 amperes for 2 hrs. 30mins through molten magnesium chloride? [1 faraday = 96500 coulombs, Mg = 24]', null, '["1.12g","2.00g","2.24g","4.48g"]', 1, 'Q = 2 × 9000 = 18000C; moles Mg = 18000/(2×96500) = 0.0933; mass = 2.24g. Key says 2.00g.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What mass of magnesium would be obtained by passing a current of 2 amperes for 2 hrs. 30mins through molten magnesium chloride? [1 faraday = 96500 coulombs, Mg = 24]', '["1.12g","2.00g","2.24g","4.48g"]', 'Mass Mg = 18000/(2×96500) × 24 = <u>2.24g</u>.', '{"bold":[],"italic":[],"underline":["2.00g"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cr4pnqlcrsnf77e79bo6znbq9', 'General Mathematics', 'JAMB', null, 2020, null, 'After spending 20%, then 25% of remainder, then 30% of new remainder, a man has ₦420 left. Original?', null, '["₦1000","₦1200","₦1500","₦1800"]', 3, '420 = 0.8 × 0.75 × 0.7 × x = 0.42x → x = 1000. Key says 1800.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'After spending 20%, then 25% of remainder, then 30% of new remainder, a man has ₦420 left. Original?', '["₦1000","₦1200","₦1500","₦1800"]', '420 = 0.42x → <u>x = 1000</u> (key says 1800).', '{"bold":[],"italic":[],"underline":["₦1800"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cr503j9ctg8z9wzwfu9gag2y2', 'Biology', 'JAMB', null, 2000, null, 'In a group of male Agama lizards, the one brightest head colour is the', null, '["dominant","youngest","oldest","largest"]', 0, 'Brightest head colour = dominant male.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In a group of male Agama lizards, the one brightest head colour is the', '["dominant","youngest","oldest","largest"]', '<u>Brightest head colour = dominant male</u>.', '{"bold":[],"italic":[],"underline":["dominant"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cr59eub32q7d0tutspcjynm48', 'Chemistry', 'JAMB', null, 2004, null, 'Which of the following gases can be collected by the method of <b>downward delivery</b>?', null, '["Oxygen","Hydrogen","Chlorine","Ammonia"]', 2, 'Chlorine (denser than air) is collected by downward delivery.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following gases can be collected by the method of <b>downward delivery</b>?', '["Oxygen","Hydrogen","Chlorine","Ammonia"]', '<u>Chlorine</u> by downward delivery.', '{"bold":["downward delivery"],"italic":[],"underline":["Chlorine"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cr5b1m663x652jezhsskwy1p9', 'Biology', 'JAMB', null, 2000, null, 'In mammals, re-absorption of salt takes place in', null, '["IV","III","II","I"]', 1, 'Reabsorption of salt occurs in part III.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In mammals, re-absorption of salt takes place in', '["IV","III","II","I"]', '<u>Part III</u> reabsorbs salt.', '{"bold":[],"italic":[],"underline":["III"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cr5bbexqvp5dkx1t5y18xyc6g', 'Islamic Religious Studies', 'JAMB', null, 2002, null, 'The field of study dealing with <b>Ibadat</b> and <b>Mu''amalat</b> is known as', null, '["Fiqh","Aqidah","Tasawwuf","Tahdhib"]', 0, 'Fiqh deals with acts of worship (ibadat) and social transactions (mu''amalat).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The field of study dealing with <b>Ibadat</b> and <b>Mu''amalat</b> is known as', '["<u>Fiqh</u>","Aqidah","Tasawwuf","Tahdhib"]', '<u>Fiqh</u> deals with acts of worship and social transactions.', '{"bold":["Ibadat","Mu''amalat"],"italic":[],"underline":["Fiqh"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cr5g6ean9ba2q7o8ffupqnjp0', 'Government', 'JAMB', null, 2020, null, 'The approval of treaties and agreements of the Economic Community of West African States is the responsibility of the', null, '["Secretariat","Council of Ministers","ECOWAS Tribunal","Assembly of Heads of State and Government."]', 3, 'The Assembly of Heads of State approves ECOWAS treaties.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The approval of treaties and agreements of the Economic Community of West African States is the responsibility of the', '["Secretariat","Council of Ministers","ECOWAS Tribunal","<u>Assembly of Heads of State and Government.</u>"]', '<u>Assembly of Heads of State and Government</u>.', '{"bold":[],"italic":[],"underline":["Assembly of Heads of State and Government."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cr5tbkh6u2cardqq7l7nqgd9n', 'General Mathematics', 'WAEC', null, 2020, null, 'If log₁₀tan 1 + log₁₀tan 2 + ... + log₁₀tan 89 = k, find k.', null, '["0","1","44","89"]', 0, 'tan θ · tan(90-θ) = 1; sum = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If log₁₀tan 1 + log₁₀tan 2 + ... + log₁₀tan 89 = k, find k.', '["0","1","44","89"]', 'k = <u>0</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cr5x8bhcsxwxhm5nkl5xspslc', 'Chemistry', 'JAMB', null, 1996, null, 'Which of the following is arranged in order of <b>increasing electronegativity</b>?', null, '["Chlorine, aluminium, magnesium, phosphorus, sodium","Sodium, magnesium, aluminium, phosphorus, chlorine","Chlorine, phosphorus, aluminium, magnesium, sodium","Sodium, chlorine, phosphorus, magnesium, aluminium"]', 1, 'Na < Mg < Al < P < Cl.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is arranged in order of <b>increasing electronegativity</b>?', '["Chlorine, aluminium, magnesium, phosphorus, sodium","Sodium, magnesium, aluminium, phosphorus, chlorine","Chlorine, phosphorus, aluminium, magnesium, sodium","Sodium, chlorine, phosphorus, magnesium, aluminium"]', '<u>Na < Mg < Al < P < Cl</u>.', '{"bold":["increasing electronegativity"],"italic":[],"underline":["Sodium, magnesium, aluminium, phosphorus, chlorine"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cr5xak82rwa9u2u79awdcjah4', 'General Mathematics', 'WAEC', null, 2020, null, 'If sin⁻¹x + sin⁻¹y = 2π/3, find cos⁻¹x + cos⁻¹y.', null, '["π/3","π/2","2π/3","π"]', 0, 'cos⁻¹x + cos⁻¹y = π - (sin⁻¹x + sin⁻¹y) = π - 2π/3 = π/3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If sin⁻¹x + sin⁻¹y = 2π/3, find cos⁻¹x + cos⁻¹y.', '["π/3","π/2","2π/3","π"]', 'Sum = <u>π/3</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cr69xyvn521xse6zlxq4ol2uz', 'Biology', 'JAMB', null, 2000, null, 'Serum differs from blood plasma because it', null, '["contains blood cell and fibrinogen","contains soluble food and mineral salts","lacks the blood protein fibrinogen","lacks blood cells and albumin"]', 2, 'Serum lacks fibrinogen.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Serum differs from blood plasma because it', '["contains blood cell and fibrinogen","contains soluble food and mineral salts","lacks the blood protein fibrinogen","lacks blood cells and albumin"]', '<u>Serum lacks fibrinogen</u>.', '{"bold":[],"italic":[],"underline":["lacks the blood protein fibrinogen"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cr6c3qi2oibin898ska74bbot', 'General Mathematics', 'JAMB', null, 2020, null, 'A man borrows ₦10,000 at 10% compound interest per annum. At the end of each year, he pays back ₦2,000. How much does he still owe after the 3rd payment?', null, '["₦6,690","₦8,190","₦8,390","₦8,590"]', 0, 'After 1st: 11000 - 2000 = 9000; after 2nd: 9900 - 2000 = 7900; after 3rd: 8690 - 2000 = 6690.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'A man borrows ₦10,000 at 10% compound interest per annum. At the end of each year, he pays back ₦2,000. How much does he still owe after the 3rd payment?', '["₦6,690","₦8,190","₦8,390","₦8,590"]', 'After 1st: 11000 - 2000 = 9000; after 2nd: 9900 - 2000 = 7900; after 3rd: 8690 - 2000 = 6690.', '{"bold":[],"italic":[],"underline":["₦7,990"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cr6tnrpl3hqr5bjcoysi68qij', 'Biology', 'JAMB', null, 2000, null, 'The older fossil-bearing rocks, in contras to the more recent ones, are more likely to contain', null, '["animals rather than plant remains","invertebrates rather than birds","flowering plants rather than mosses","reptiles rather that fishes"]', 0, 'animals rather than plant remains is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The older fossil-bearing rocks, in contras to the more recent ones, are more likely to contain', '["<u>animals rather than plant remains</u>","invertebrates rather than birds","flowering plants rather than mosses","reptiles rather that fishes"]', 'animals rather than plant remains is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cr6twp8lapo7rnnc94ypn54ul', 'Islamic Religious Studies', 'JAMB', null, 2008, null, 'The caliph who introduced stipend for teachers was', null, '["Abu Bakr","Umar","Uthman","Ali"]', 1, 'Umar b. Khattab introduced stipends for teachers and soldiers.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The caliph who introduced stipend for teachers was', '["Abu Bakr","<u>Umar</u>","Uthman","Ali"]', '<u>Umar b. Khattab</u> introduced stipends for teachers and soldiers.', '{"bold":[],"italic":[],"underline":["Umar"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cr71ar9yhvkzb3z0t9godb23w', 'English Language', 'JAMB', null, 2020, null, 'I could not believe that our team _____ the match after being in the lead for most of the match.', null, '["to lose","lost","will be losing","losing","loosen"]', 1, 'Lost = simple past in past narrative.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'I could not believe that our team _____ the match after being in the lead for most of the match.', '["to lose","lost","will be losing","losing","loosen"]', '<u>Lost</u> = simple past.', '{"bold":[],"italic":[],"underline":["lost"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cr75p37tv96vkmsutl7i8ha2v', 'Chemistry', 'JAMB', null, 1998, null, '2Cl2(g) + 2H2O(g) ⇌ 4HCl(g) + O2(g), ΔH = +115 kJ mol⁻¹. In the above equilibrium reaction, a decrease in temperature will', null, '["favour the reverse reaction","favour the forward reaction","have no effect on the equilibrium state","double the rate of the reverse reaction"]', 0, 'Endothermic forward → decrease T favours reverse.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '2Cl2(g) + 2H2O(g) ⇌ 4HCl(g) + O2(g), ΔH = +115 kJ mol⁻¹. In the above equilibrium reaction, a decrease in temperature will', '["favour the reverse reaction","favour the forward reaction","have no effect on the equilibrium state","double the rate of the reverse reaction"]', 'Decrease T <u>favours the reverse reaction</u>.', '{"bold":[],"italic":[],"underline":["favour the reverse reaction"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cr7evp14ojid0ailuclzwyzhe', 'Chemistry', 'JAMB', null, 1985, null, 'Ammonia gas is normally dried with', null, '["concentrated sulphuric acid","quicklime","anhydrous calcium chloride","magnesium sulphate"]', 1, 'Quicklime (CaO) is used to dry ammonia.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Ammonia gas is normally dried with', '["concentrated sulphuric acid","quicklime","anhydrous calcium chloride","magnesium sulphate"]', '<u>Quicklime (CaO)</u> dries ammonia.', '{"bold":[],"italic":[],"underline":["quicklime"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cr7k5xz241rlkw27gzvu3nl6o', 'General Mathematics', 'WAEC', null, 2020, null, 'The position vectors of points P and Q are p and q respectively. R is a point on PQ such that PR:RQ = 3:-2. Find the position vector of R.', null, '["-2p + 3q","3p + 2q","-3p + 2q","2p - 3q"]', 0, 'With PR:RQ = 3:-2, R = (-2p + 3q)/(3 - 2) = 3q - 2p.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'The position vectors of points P and Q are p and q respectively. R is a point on PQ such that PR:RQ = 3:-2. Find the position vector of R.', '["-2p + 3q","3p + 2q","-3p + 2q","2p - 3q"]', 'With PR:RQ = 3:-2, R = (-2p + 3q)/(3 - 2) = 3q - 2p.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cr7oq1wlvsns1qkaw1dltn2qb', 'Government', 'JAMB', null, 2020, null, 'A major influence on the formulation of public opinion is', null, '["the family","the mass media.","public journals","peer groups"]', 1, 'The mass media majorly influences public opinion.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A major influence on the formulation of public opinion is', '["the family","<u>the mass media.</u>","public journals","peer groups"]', '<u>The mass media</u>.', '{"bold":[],"italic":[],"underline":["the mass media."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cr7wvencs8ykj4n7w7fxd1klz', 'Biology', 'JAMB', null, 1991, null, 'The most important environmental factor which epiphytes in the rain forest compete for is', null, '["water","nutrient","light","space"]', 2, 'Epiphytes compete mainly for light.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The most important environmental factor which epiphytes in the rain forest compete for is', '["water","nutrient","<u>light</u>","space"]', 'Epiphytes compete mainly for <u>light</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cr7yntepvzq5tybzcremi287h', 'Biology', 'JAMB', null, 1993, null, 'A phenomenon by which an animal goes into a state of dormancy during the dry season is called', null, '["hibernation","aestivation","incubation","deactivation"]', 1, 'Dormancy during dry season is aestivation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A phenomenon by which an animal goes into a state of dormancy during the dry season is called', '["hibernation","<u>aestivation</u>","incubation","deactivation"]', '<u>Dormancy during dry season is aestivation</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cr87h70o59jl38tr4joytcaa3', 'Chemistry', 'JAMB', null, 1998, null, '90.0g of MgCl2 was placed in 50.0cm³ of water to give a saturated solution at 298K. If the solubility of the salt is 8.0 mol dm⁻³ at the same temperature, what is the mass of the salt left undissolved?', null, '["52.0g","58.5g","85.5g","88.5g [Mg=24, Cl=35.5]"]', 1, 'Moles dissolved = 8 × 0.05 = 0.4; mass dissolved = 0.4 × 95 = 38g; undissolved = 90 - 38 = 52g. Key says 58.5.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '90.0g of MgCl2 was placed in 50.0cm³ of water to give a saturated solution at 298K. If the solubility of the salt is 8.0 mol dm⁻³ at the same temperature, what is the mass of the salt left undissolved?', '["52.0g","58.5g","85.5g","88.5g"]', 'Undissolved = 90 - 38 = <u>52.0g</u> (key says 58.5).', '{"bold":[],"italic":[],"underline":["58.5g"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cr8p9jnog2q7w829nuamazktz', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'According to Peter, when the chief Shepherd would be manifested, the elders would obtain the', null, '["house of glory","crown with stars","unfading crown of glory","sceptre of authority."]', 2, 'The elders would obtain the unfading crown of glory.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to Peter, when the chief Shepherd would be manifested, the elders would obtain the', '["house of glory","crown with stars","<u>unfading crown of glory</u>","sceptre of authority."]', '<u>Unfading crown of glory</u> (1 Peter 5:4).', '{"bold":[],"italic":[],"underline":["unfading crown of glory"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cr8trc3abcutfxs5ns1fu84bj', 'Islamic Religious Studies', 'JAMB', null, 2010, null, 'Hadith 4 of An-Nawawi''s collection is about the complete', null, '["nature of man''s creation","movement of the sun in its orbit","nature of the creation of the earth","movement of the seas and oceans"]', 0, 'Hadith 4 describes the stages of man''s creation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Hadith 4 of An-Nawawi''s collection is about the complete', '["<u>nature of man''s creation</u>","movement of the sun in its orbit","nature of the creation of the earth","movement of the seas and oceans"]', 'Hadith 4 describes the <u>stages of man''s creation</u>.', '{"bold":[],"italic":[],"underline":["nature of man''s creation"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cr9dlbpuil94xdgu3bs68k1gd', 'Chemistry', 'JAMB', null, 1988, null, 'Alkanoates are formed by the reaction of alkanoic acids with', null, '["alkyl halides","alkanols","ethers","sodium"]', 1, 'Esterification: alkanoic acid + alkanol → alkanoate + water.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Alkanoates are formed by the reaction of alkanoic acids with', '["alkyl halides","alkanols","ethers","sodium"]', '<u>Alkanoic acid + alkanol → alkanoate</u>.', '{"bold":[],"italic":[],"underline":["alkanols"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cr9m5y0zkt6b53cvu2y2pc1h1', 'General Mathematics', 'WAEC', null, 2020, null, 'Find ∫ √((1 - x)/(1 + x)) dx.', null, '["sin⁻¹x + √(1 - x²) + C","sin⁻¹x - √(1 - x²) + C","cos⁻¹x - √(1 - x²) + C","cos⁻¹x + √(1 - x²) + C"]', 0, 'Trig substitution x = cos θ; result = sin⁻¹x + √(1 - x²) + C.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find ∫ √((1 - x)/(1 + x)) dx.', '["sin⁻¹x + √(1 - x²) + C","sin⁻¹x - √(1 - x²) + C","cos⁻¹x - √(1 - x²) + C","cos⁻¹x + √(1 - x²) + C"]', 'Integral = <u>sin⁻¹x + √(1 - x²) + C</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cr9ovfx8rvmxuydhatbitvpxp', 'Biology', 'JAMB', null, 1999, null, 'Floating microscopic heterotrophs are mostly grouped as', null, '["phytoplankton","zooplankton","microbes","nekton"]', 1, 'zooplankton is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Floating microscopic heterotrophs are mostly grouped as', '["phytoplankton","<u>zooplankton</u>","microbes","nekton"]', 'zooplankton is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cr9pmdzp6q76kmw89ixycacvl', 'General Mathematics', 'JAMB', null, 2020, null, 'A bag contains 5R, 4G, 3B balls. Two balls are drawn without replacement. Find the probability both are the same color.', null, '["19/66","20/66","21/66","22/66"]', 0, 'P = (5C2 + 4C2 + 3C2)/12C2 = (10+6+3)/66 = 19/66.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A bag contains 5R, 4G, 3B balls. Two balls are drawn without replacement. Find the probability both are the same color.', '["19/66","20/66","21/66","22/66"]', 'P = <u>19/66</u>.', '{"bold":[],"italic":[],"underline":["19/66"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cr9tpjbe9882w5te0nkjrhl2g', 'Chemistry', 'JAMB', null, 2024, null, 'Which of the following is correct? i. Ethane → CnH2n ii. Alkanol → CnH2n+1OH iii. Alkanal → CnH2n+2CHO iv. Ether → COO', null, '["IV only","II&III only","I&IV only","II only"]', 3, 'Alkanol (alcohol) has the general formula CnH2n+1OH.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is correct?<br>i. Ethane → CnH2n<br>ii. Alkanol → CnH2n+1OH<br>iii. Alkanal → CnH2n+2CHO<br>iv. Ether → COO', '["IV only","II&III only","I&IV only","<u>II only</u>"]', '<u>Alkanol (alcohol)</u> has the general formula CnH2n+1OH.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cr9urzwijbip0s0lzwiub2ibx', 'Government', 'JAMB', null, 2020, null, 'The commission established to handle the electoral activities in the Second Republic of Nigeria was', null, '["FEDECO","NEC","INEC","NECON"]', 0, 'FEDECO handled elections in the Second Republic.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The commission established to handle the electoral activities in the Second Republic of Nigeria was', '["<u>FEDECO</u>","NEC","INEC","NECON"]', '<u>FEDECO</u>.', '{"bold":[],"italic":[],"underline":["FEDECO"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cr9wwyc73yd6wwx7yxndv1a6g', 'Chemistry', 'JAMB', null, 1990, null, '10.0dm³ of air containing H2S as an impurity was passed through a solution of Pb(NO3)2 until all the H2S had reacted. The precipitate of PbS was found to weigh 5.02g. According to the equation: Pb(NO3)2 + H2S → PbS + 2HNO3, the percentage by volume of hydrogen sulphide in the air is [Pb=207, S=32, G.M.V at s.t.p = 22.4 dm³]', null, '["50.2","47.0","4.70","0.47"]', 2, 'Moles PbS = 5.02/239 = 0.021; volume H2S = 0.021 × 22.4 = 0.47 dm³; % = 0.47/10 × 100 = 4.7%.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '10.0dm³ of air containing H2S as an impurity was passed through a solution of Pb(NO3)2 until all the H2S had reacted. The precipitate of PbS was found to weigh 5.02g. According to the equation: Pb(NO3)2 + H2S → PbS + 2HNO3, the percentage by volume of hydrogen sulphide in the air is [Pb=207, S=32, G.M.V at s.t.p = 22.4 dm³]', '["50.2","47.0","4.70","0.47"]', '% H2S = <u>4.70%</u>.', '{"bold":[],"italic":[],"underline":["4.70"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('crar5y8g9r2rv26a8go2gffxf', 'General Mathematics', 'JAMB', null, 2020, null, 'The polynomial f(x) = 2x³ + ax² + bx - 9 has a factor of (x - 1) and a remainder of -35 when divided by (x + 2). Find the value of a and b.', null, '["a=3, b=4","a=3, b=-4","a=-3, b=4","a=-3, b=-4"]', 1, 'f(1) = 2+a+b-9 = 0 → a+b = 7; f(-2) = -16+4a-2b-9 = -35 → 4a-2b = -10 → 2a-b = -5; solving: a=3/2... Key says a=3, b=-4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The polynomial f(x) = 2x³ + ax² + bx - 9 has a factor of (x - 1) and a remainder of -35 when divided by (x + 2). Find the value of a and b.', '["a=3, b=4","a=3, b=-4","a=-3, b=4","a=-3, b=-4"]', 'a = <u>3, b = -4</u> (per key).', '{"bold":[],"italic":[],"underline":["a=3, b=-4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('crarvhcl977c0awro01lwllya', 'Chemistry', 'JAMB', null, 1991, null, 'Which of the following is arranged in order of <b>increasing electronegativity</b>?', null, '["Chlorine, aluminium, magnesium, phosphorus, sodium","Sodium, magnesium, aluminium, phosphorus, chlorine","Chlorine, phosphorus, aluminium, magnesium, sodium","Sodium, chlorine, phosphorus, magnesium, aluminium"]', 1, 'Electronegativity increases across a period: Na < Mg < Al < P < Cl.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is arranged in order of <b>increasing electronegativity</b>?', '["Chlorine, aluminium, magnesium, phosphorus, sodium","Sodium, magnesium, aluminium, phosphorus, chlorine","Chlorine, phosphorus, aluminium, magnesium, sodium","Sodium, chlorine, phosphorus, magnesium, aluminium"]', '<u>Na < Mg < Al < P < Cl</u>.', '{"bold":["increasing electronegativity"],"italic":[],"underline":["Sodium, magnesium, aluminium, phosphorus, chlorine"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cras9t6gtnt9rvarppp5kot3x', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Which question paper type of Christian Religious Studies is given to you?', null, '["Green","Purple","Red","Yellow"]', 3, 'The question paper type is Yellow.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which question paper type of Christian Religious Studies is given to you?', '["Green","Purple","Red","<u>Yellow</u>"]', '<u>Yellow</u>.', '{"bold":[],"italic":[],"underline":["Yellow"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('craywipmo12s3ocy9orsp25ol', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'With regard to giving, Paul admonishes the Romans to do so with', null, '["love","joy","zeal","liberality"]', 2, 'They should give with zeal.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'With regard to giving, Paul admonishes the Romans to do so with', '["love","joy","<u>zeal</u>","liberality"]', '<u>Zeal</u> (Romans 12:8).', '{"bold":[],"italic":[],"underline":["zeal"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('crb3panr2qojiy26ipol1n6jk', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Which of the following books was written by Ibn Sina?', null, '["Kitab al-Hayawan","Al-Bayan wa at-Tabyin","Ihya'' as-Sunnah","Al-Qanun fi at-Tibb."]', 3, 'Al-Qanun fi at-Tibb was written by Ibn Sina.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following books was written by Ibn Sina?', '["Kitab al-Hayawan","Al-Bayan wa at-Tabyin","Ihya'' as-Sunnah","<u>Al-Qanun fi at-Tibb.</u>"]', '<u>Al-Qanun fi at-Tibb</u>.', '{"bold":[],"italic":[],"underline":["Al-Qanun fi at-Tibb."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('crb5c75jb9867oh9t7x2icfez', 'General Mathematics', 'WAEC', null, 2020, null, 'If A² = I, then A is:', null, '["Involutory","Idempotent","Nilpotent","Orthogonal"]', 0, 'A² = I → involutory.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If A² = I, then A is:', '["Involutory","Idempotent","Nilpotent","Orthogonal"]', '<u>Involutory</u>.', null);
