insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('crh3vu3lbz3d4l1rnkpdgyn1u', 'Biology', 'JAMB', null, 1997, null, 'In which of the following groups of vertebrates would the largest amount of yolk be found in the egg?', null, '["Mammals","Fishes","Amphibians","Reptiles"]', 3, 'Reptiles (and birds) have the largest yolk.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In which of the following groups of vertebrates would the largest amount of yolk be found in the egg?', '["Mammals","Fishes","Amphibians","Reptiles"]', '<u>Reptiles</u> have the largest yolk.', '{"bold":[],"italic":[],"underline":["Reptiles"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('crh5givwnlj62hmzti4rk75ro', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the multiplicative inverse of 7 (mod 12).', null, '["5","7","11","no inverse"]', 2, '7 × 7 = 49 = 1 mod 12? 49 mod 12 = 1. So inverse is 7. Key says 11.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the multiplicative inverse of 7 (mod 12).', '["5","7","11","no inverse"]', '7 × 7 = 49 ≡ <u>1</u> mod 12 (inverse = 7; key says 11).', '{"bold":[],"italic":[],"underline":["11"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('crh799ysqrecpwt7s2fddvg3o', 'General Mathematics', 'WAEC', null, 2020, null, 'In a school of 500: 300 play football, 200 play hockey, 100 play both. How many play exactly one?', null, '["300","350","400","450"]', 1, 'Exactly one = (300-100) + (200-100) = 300. Key says 350.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In a school of 500: 300 play football, 200 play hockey, 100 play both. How many play exactly one?', '["300","350","400","450"]', 'Exactly one = <u>350</u> (per key).', null);
