insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('crhjmj9x2gfdx5s3jbqtkiezf', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Lord, I have heard from many about this man, how much evil he has done to thy saints at Jerusalem... Ananias'' response above to God''s request for him to meet Saul shows that he', null, '["was not interested in meeting Saul","was afraid to meet Saul","felt that Saul should not be forgiven","felt that Saul should be punished."]', 1, 'Ananias was afraid to meet Saul.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Lord, I have heard from many about this man, how much evil he has done to thy saints at Jerusalem... Ananias'' response above to God''s request for him to meet Saul shows that he', '["was not interested in meeting Saul","<u>was afraid to meet Saul</u>","felt that Saul should not be forgiven","felt that Saul should be punished."]', '<u>Was afraid to meet Saul</u> (Acts 9:13-14).', '{"bold":[],"italic":[],"underline":["was afraid to meet Saul"],"fillBlanks":[]}');
