insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('crhuds4zf4suw74b1opzg8jlj', 'Chemistry', 'JAMB', null, 1990, null, 'Alkanoic acids have <b>low volatility</b> compared with alkanols because they', null, '["are more polar than alkanols","have two oxygen atoms while alkanols have one","form two hydrogen bonds while alkanols do not","form two hydrogen bonds while alkanols form one"]', 3, 'Alkanoic acids form stronger H-bonded dimers.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Alkanoic acids have <b>low volatility</b> compared with alkanols because they', '["are more polar than alkanols","have two oxygen atoms while alkanols have one","form two hydrogen bonds while alkanols do not","form two hydrogen bonds while alkanols form one"]', '<u>Alkanoic acids form two hydrogen bonds</u> (dimers) while alkanols form one.', '{"bold":["low volatility"],"italic":[],"underline":["form two hydrogen bonds while alkanols form one"],"fillBlanks":[]}');
