insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('crjlsbk1fqwgejrwxa9gwc47i', 'Chemistry', 'JAMB', null, 1983, null, 'A piece of burning sulphur will continue to burn in a gas jar of oxygen to give misty fumes which readily dissolve in water. The resulting liquid is', null, '["sulphur (IV) trioxide","tetraoxosulphate(VI) acid","trioxosulphate(IV) acid","dioxosulphate(II) acid","hydrogen sulphide"]', 2, 'SO2 dissolves in water to form trioxosulphate(IV) acid (H2SO3).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A piece of burning sulphur will continue to burn in a gas jar of oxygen to give misty fumes which readily dissolve in water. The resulting liquid is', '["sulphur (IV) trioxide","tetraoxosulphate(VI) acid","trioxosulphate(IV) acid","dioxosulphate(II) acid","hydrogen sulphide"]', 'SO2 dissolves in water to form <u>trioxosulphate(IV) acid (H2SO3)</u>.', '{"bold":[],"italic":[],"underline":["trioxosulphate(IV) acid"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('crjqdhsw4murir87v47t7zlbc', 'Chemistry', 'JAMB', null, 1984, null, 'Copper sulphate solution is electrolyzed using platinum electrodes. A current of 0.193 amperes is passed for 2hrs. How many grams of copper are deposited? [Cu=63.5, F=96500C]', null, '["0.457g","0.500g","0.882g","0.914g","1.00g"]', 0, 'Q = 0.193 × 7200 = 1389.6C; moles Cu = 1389.6/(2×96500) = 0.0072; mass = 0.457g.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Copper sulphate solution is electrolyzed using platinum electrodes. A current of 0.193 amperes is passed for 2hrs. How many grams of copper are deposited? [Cu=63.5, F=96500C]', '["0.457g","0.500g","0.882g","0.914g","1.00g"]', 'Mass Cu = <u>0.457g</u>.', '{"bold":[],"italic":[],"underline":["0.457g"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('crjw2zgdwx2i5v6xnk8d4xq1b', 'Chemistry', 'JAMB', null, 1996, null, 'Copper(II) tetraoxosulphate(VI) is widely used as a', null, '["Fertilizer","Fungicide","Disinfectant","Purifier"]', 1, 'CuSO4 is widely used as a fungicide.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Copper(II) tetraoxosulphate(VI) is widely used as a', '["Fertilizer","Fungicide","Disinfectant","Purifier"]', '<u>CuSO4 is a fungicide</u>.', '{"bold":[],"italic":[],"underline":["Fungicide"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('crk7l6j3k5pnlapocktfbac45', 'Physics', 'JAMB', null, 2019, null, 'Two closed vessels contain equal volumes of boiling water and are identical except that one is blackened on the outside while the other is polished. Which of the following is correct?', null, '["The black vessel will cool faster because a black surface radiates heat faster than a polished one","The polished vessel will cool faster because it reflects heat better","The polished vessel will cool faster because it will absorb less from the room","The polished vessel will cool faster because a polished surface is a good radiator"]', 0, 'Black surfaces are good radiators/emitters of heat, so the black vessel cools faster.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Two closed vessels contain equal volumes of boiling water and are identical except that one is blackened on the outside while the other is polished. Which of the following is correct?', '["<u>The black vessel will cool faster because a black surface radiates heat faster than a polished one</u>","The polished vessel will cool faster because it reflects heat better","The polished vessel will cool faster because it will absorb less from the room","The polished vessel will cool faster because a polished surface is a good radiator"]', '<u>Black surfaces are good radiators</u> of heat, so the black vessel cools faster.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('crkk6kc6rbxhoi8ehzi44vrzd', 'Chemistry', 'JAMB', null, 1990, null, 'The effluent of an industrial plant used in the electrolysis of concentrated brine, with a flowing mercury cathode may contain impurities like', null, '["oxygen","hydrogen","mercury(II) chloride","hydrogen chloride"]', 2, 'Mercury cathode cells can release mercury compounds as impurities.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The effluent of an industrial plant used in the electrolysis of concentrated brine, with a flowing mercury cathode may contain impurities like', '["oxygen","hydrogen","mercury(II) chloride","hydrogen chloride"]', '<u>Mercury(II) chloride</u> can be an impurity.', '{"bold":[],"italic":[],"underline":["mercury(II) chloride"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('crklntoycak8z0nioq8gx23a0', 'English Language', 'JAMB', null, 2020, null, '_____ been no official reaction to your request yet.', null, '["There''s","Theres''","Theirs","Their''s"]', 0, 'There''s = "There has" in this context.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '_____ been no official reaction to your request yet.', '["There''s","Theres''","Theirs","Their''s"]', '<u>There''s</u> = There has.', '{"bold":[],"italic":[],"underline":["There''s"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('crl08vhtwnhawzpvmcep0sz5y', 'Chemistry', 'JAMB', null, 1997, null, 'In a soil sample, the relative amounts of the different soil particles can best be determined by the process of', null, '["filtration","centrifugation","precipitation","sedimentation"]', 3, 'Sedimentation determines soil particle sizes.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In a soil sample, the relative amounts of the different soil particles can best be determined by the process of', '["filtration","centrifugation","precipitation","sedimentation"]', '<u>Sedimentation</u> determines soil particle sizes.', '{"bold":[],"italic":[],"underline":["sedimentation"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('crl18ykj7thrp0ldcpqbf63ip', 'Chemistry', 'JAMB', null, 1992, null, 'Which of these statements is <b>TRUE</b> about carbon(IV) oxide?', null, '["It supports combustion","It is strong acidic in water","It is very soluble in water","It supports the burning of magnesium to produce magnesium oxide"]', 3, 'Mg burns in CO2 to form MgO and C.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of these statements is <b>TRUE</b> about carbon(IV) oxide?', '["It supports combustion","It is strong acidic in water","It is very soluble in water","It supports the burning of magnesium to produce magnesium oxide"]', '<u>Mg burns in CO2</u> to form MgO.', '{"bold":["TRUE"],"italic":[],"underline":["It supports the burning of magnesium to produce magnesium oxide"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('crlgudb5bywu9zelw5rqj31o4', 'Islamic Religious Studies', 'JAMB', null, 2010, null, '''Allah begets not nor is He begotten.'' The quotation above condemns', null, '["hero praising","the doctrine of trinity","worshiping of ancestors","idol worship"]', 1, 'Q.112:3 condemns the doctrine of trinity.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '''Allah begets not nor is He begotten.'' The quotation above condemns', '["hero praising","<u>the doctrine of trinity</u>","worshiping of ancestors","idol worship"]', 'Q.112:3 condemns <u>the doctrine of trinity</u>.', '{"bold":[],"italic":[],"underline":["the doctrine of trinity"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('crli9vkhvyezu3zp7l0z2722j', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the volume generated when the region bounded by y = √x, the y-axis, and the line y = 2 is rotated about the y-axis.', null, '["32π/5","16π/5","8π/5","4π/5"]', 0, 'V = π∫₀² y⁴ dy = 32π/5.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the volume generated when the region bounded by y = √x, the y-axis, and the line y = 2 is rotated about the y-axis.', '["32π/5","16π/5","8π/5","4π/5"]', 'Volume = <u>32π/5</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('crliyl0couwtk6bn03zmv6rsc', 'Chemistry', 'JAMB', null, 1984, null, 'A correct electrochemical series can be obtained from K, Na, Ca, Al, Mg, Zn, Fe, Pb, H, Cu, Hg, Ag, Au by interchanging', null, '["Al and Mg","Zn and Fe","Zn and Pb","Pb and H","Au and Hg"]', 4, 'Au and Hg are interchanged to get the correct electrochemical series.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A correct electrochemical series can be obtained from K, Na, Ca, Al, Mg, Zn, Fe, Pb, H, Cu, Hg, Ag, Au by interchanging', '["Al and Mg","Zn and Fe","Zn and Pb","Pb and H","Au and Hg"]', '<u>Au and Hg</u> are interchanged.', '{"bold":[],"italic":[],"underline":["Au and Hg"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('crlobwpf8t9taahuitlgj4aqy', 'Chemistry', 'JAMB', null, 1995, null, '10.0dm³ of air containing H2S as an impurity was passed through a solution of Pb(NO3)2 until all the H2S had reacted. The precipitate of PbS was found to weigh 5.02g. According to the equation: Pb(NO3)2 + H2S → PbS + 2HNO3, the percentage by volume of hydrogen sulphide in the air is [Pb=207, S=32, G.M.V at s.t.p = 22.4 dm³]', null, '["50.2","47.0","4.70","0.47"]', 2, 'Moles PbS = 5.02/239 = 0.021; volume H2S = 0.021 × 22.4 = 0.47 dm³; % = 4.7%.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '10.0dm³ of air containing H2S as an impurity was passed through a solution of Pb(NO3)2 until all the H2S had reacted. The precipitate of PbS was found to weigh 5.02g. According to the equation: Pb(NO3)2 + H2S → PbS + 2HNO3, the percentage by volume of hydrogen sulphide in the air is [Pb=207, S=32, G.M.V at s.t.p = 22.4 dm³]', '["50.2","47.0","4.70","0.47"]', '% H2S = <u>4.70%</u>.', '{"bold":[],"italic":[],"underline":["4.70"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('crlorhdh6pu1osk29ykwgzi1u', 'Government', 'JAMB', null, 2020, null, 'Government by the wealthy is known as', null, '["plutocracy","oligarchy","aristocracy","democracy."]', 0, 'Plutocracy is government by the wealthy.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Government by the wealthy is known as', '["<u>plutocracy</u>","oligarchy","aristocracy","democracy."]', '<u>Plutocracy</u>.', '{"bold":[],"italic":[],"underline":["plutocracy"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('crlr691vq089nbrmytk787w65', 'Chemistry', 'JAMB', null, 1987, null, 'A quantity of electricity liberates 3.6g of silver from its salt. What mass of aluminium will be liberated from its salt by the same quantity of electricity?', null, '["2.7g","1.2g","0.9g","0.3g"]', 2, 'Eq Ag = 108; Eq Al = 9; mass Al = (3.6/108) × 9 = 0.3g. Key says 0.9g.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A quantity of electricity liberates 3.6g of silver from its salt. What mass of aluminium will be liberated from its salt by the same quantity of electricity?', '["2.7g","1.2g","0.9g","0.3g"]', 'Mass Al = <u>0.3g</u> (key says 0.9g).', '{"bold":[],"italic":[],"underline":["0.9g"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('crlw310vjn40pmteevxch87e9', 'Chemistry', 'JAMB', null, 1995, null, 'Which of the following metals will <b>liberate hydrogen</b> from steam or dilute acid?', null, '["copper","iron","lead","mercury"]', 1, 'Iron is above hydrogen in the reactivity series.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following metals will <b>liberate hydrogen</b> from steam or dilute acid?', '["copper","iron","lead","mercury"]', '<u>Iron</u> liberates hydrogen.', '{"bold":["liberate hydrogen"],"italic":[],"underline":["iron"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('crm7189ayyec93kw9usxdo8ww', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the multiplicative inverse of 7 (mod 12).', null, '["5","7","11","no inverse"]', 2, '7 × 7 = 49 = 1 mod 12? 49 mod 12 = 1. So inverse is 7. Key says 11.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the multiplicative inverse of 7 (mod 12).', '["5","7","11","no inverse"]', '7 × 7 = 49 ≡ <u>1</u> mod 12 (inverse = 7; key says 11).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('crm79cdmwqvcw9xu4mnhuk2qy', 'General Mathematics', 'JAMB', null, 2020, null, 'The remainder when x³ + kx² + 3x - 2 divided by x - 1 equals the remainder when divided by x + 1 find k', null, '["3","no such value of k","1","0"]', 1, 'f(1) = k + 2 and f(-1) = k - 6 can never be equal, so no such k exists.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'The remainder when x³ + kx² + 3x - 2 divided by x - 1 equals the remainder when divided by x + 1 find k', '["3","no such value of k","1","0"]', 'f(1) = k + 2 and f(-1) = k - 6 can never be equal, so no such k exists.', '{"bold":[],"italic":[],"underline":["2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('crmcdah1d18oxplv3bdj916tb', 'Biology', 'JAMB', null, 1990, null, 'The most recently evolved structure in animals is the', null, '["hair","cilium","scale","feather"]', 0, 'Hair is the most recently evolved structure.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The most recently evolved structure in animals is the', '["<u>hair</u>","cilium","scale","feather"]', '<u>Hair</u> is the most recently evolved structure.', null);
