insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('crmsbnkbn2fdob1choind8a8p', 'Government', 'JAMB', null, 2020, null, 'The independence of the judiciary can be undermined through the', null, '["politicization of the appointment of judges","appointment of the minister of justice as the Attorney-General","confirmation of the appointment of judges by the legislature.","payment of salaries of judicial officers by government"]', 0, 'Politicization of judges'' appointment undermines judicial independence.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The independence of the judiciary can be undermined through the', '["politicization of the appointment of judges","appointment of the minister of justice as the Attorney-General","confirmation of the appointment of judges by the legislature.","payment of salaries of judicial officers by government"]', '<u>Politicization of the appointment of judges</u>.', '{"bold":[],"italic":[],"underline":["politicization of the appointment of judges"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('crmuwdvm56w7yg0tsl4b32tsq', 'General Mathematics', 'WAEC', null, 2020, null, 'If n(A) = 20, n(B) = 30, n(A ∪ B) = 40, find n(A ∩ B).', null, '["10","15","20","25"]', 0, 'n(A ∩ B) = 20 + 30 - 40 = 10.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If n(A) = 20, n(B) = 30, n(A ∪ B) = 40, find n(A ∩ B).', '["10","15","20","25"]', 'n(A ∩ B) = <u>10</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('crn1h227f6w24kdhwkswsx8uz', 'Biology', 'JAMB', null, 1995, null, 'From which group of animals are the mammals generally believed to have most recently evolved?', null, '["Reptiles.","Fishes.","Amphibians.","Birds. hoolgist.com"]', 0, 'Reptiles. is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'From which group of animals are the mammals generally believed to have most recently evolved?', '["<u>Reptiles.</u>","Fishes.","Amphibians.","Birds. hoolgist.com"]', 'Reptiles. is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('crn1ky7lehgv7oykho5c7d8qb', 'Chemistry', 'JAMB', null, 1988, null, 'Which of the following acts both as <b>reducing and as oxidizing agent</b>?', null, '["H2","SO2","H2S","C"]', 1, 'SO2 can be oxidized to SO3 and reduced to S.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following acts both as <b>reducing and as oxidizing agent</b>?', '["H2","SO2","H2S","C"]', '<u>SO2</u> can act as both oxidizing and reducing agent.', '{"bold":["reducing and as oxidizing agent"],"italic":[],"underline":["SO2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('crn5a2ojrcb773hgo08yvzx5f', 'Chemistry', 'JAMB', null, 1986, null, 'The tabulated results below were obtained by titrating 10.0cm³ of water with soap. The titration was repeated with the same sample of water after boiling.<br>Before boiling: Final = 25.0, Initial = 10.0<br>After boiling: Final = 20.0, Initial = 15.0<br>The ratio of permanent to temporary hardness is', null, '["1:5","1:4","4:1","5:1"]', 1, 'Permanent = 5, temporary = 15 - 5 = 10; ratio = 5:10 = 1:2. Closest is 1:4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The tabulated results below were obtained by titrating 10.0cm³ of water with soap. The titration was repeated with the same sample of water after boiling.<br>Before boiling: Final = 25.0, Initial = 10.0<br>After boiling: Final = 20.0, Initial = 15.0<br>The ratio of permanent to temporary hardness is', '["1:5","1:4","4:1","5:1"]', 'Permanent:temporary = 5:10 = <u>1:2</u> (closest 1:4).', '{"bold":[],"italic":[],"underline":["1:4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('crna9bdodswn9cvjwr50wl1p5', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the center of the hyperbola 9x² - 16y² = 144.', null, '["(0, 0)","(4, 0)","(0, 3)","(3, 0)"]', 0, 'Center at origin.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the center of the hyperbola 9x² - 16y² = 144.', '["(0, 0)","(4, 0)","(0, 3)","(3, 0)"]', 'Center = <u>(0, 0)</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('crnatkxa5498nekvugi9q391c', 'Biology', 'JAMB', null, 1991, null, 'The loud cry made by a brooding hen when a predator is around is meant to', null, '["alert the poultry attendants","attract cocks to come and fight the predator","advertise the boundaries of its territory to intruders","warn its chicks and other chickens of impending danger"]', 3, 'The cry warns chicks and other chickens of danger.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The loud cry made by a brooding hen when a predator is around is meant to', '["alert the poultry attendants","attract cocks to come and fight the predator","advertise the boundaries of its territory to intruders","<u>warn its chicks and other chickens of impending danger</u>"]', 'The cry <u>warns chicks and other chickens of danger</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('crnbhqmtsom41etzznqtgb523', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The period of custody of a baby girl after her mother has been divorced lasts until she is', null, '["married","mature","10 years old","5 years old."]', 0, 'The period lasts until she is married.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The period of custody of a baby girl after her mother has been divorced lasts until she is', '["<u>married</u>","mature","10 years old","5 years old."]', '<u>Married</u>.', '{"bold":[],"italic":[],"underline":["married"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('crnc6rgzd6b8ow2d7yqjf8xzz', 'Biology', 'JAMB', null, 2001, null, 'The stem of a typical aquatic plant usually has many', null, '["air cavities","intercellular spaces","water cavities","water-conducting cells"]', 1, 'Aquatic plants have many intercellular spaces.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The stem of a typical aquatic plant usually has many', '["air cavities","intercellular spaces","water cavities","water-conducting cells"]', '<u>Intercellular spaces</u>.', '{"bold":[],"italic":[],"underline":["intercellular spaces"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('crnfhcyg7gbwgc6re7t8mnjtn', 'General Mathematics', 'JAMB', null, 2020, null, 'Two cards are drawn without replacement from a deck. Find the probability both are kings.', null, '["1/221","1/169","1/13","4/663"]', 0, 'P = (4/52)(3/51) = 1/221.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Two cards are drawn without replacement from a deck. Find the probability both are kings.', '["1/221","1/169","1/13","4/663"]', 'P = <u>1/221</u>.', '{"bold":[],"italic":[],"underline":["1/221"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('crnh13gf7tlkyydqap9jlb0cw', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve |x² - 4| = 3x.', null, '["1, 4","1, -4","-1, 4","-1, -4"]', 0, 'x²-4 = 3x → x²-3x-4 = 0 → x = 4 or -1. Check x=-1: |1-4| = 3 ≠ -3. So x=4. Also x²-4 = -3x → x²+3x-4 = 0 → x = 1 or -4. Check x=1: |1-4| = 3 = 3. So x=1,4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve |x² - 4| = 3x.', '["1, 4","1, -4","-1, 4","-1, -4"]', '<u>x = 1, 4</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('crnqarux4t93da1f7heaisyy6', 'Biology', 'JAMB', null, 1988, null, 'Taxism differs from tropism because', null, '["the whole organism is affected","it is a directional movement","it is a response to multi-directional stimuli","part of the organism is affected"]', 0, 'Taxism affects the whole organism; tropism affects a part.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Taxism differs from tropism because', '["<u>the whole organism is affected</u>","it is a directional movement","it is a response to multi-directional stimuli","part of the organism is affected"]', '<u>Taxism affects the whole organism</u>; tropism affects a part.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('crnxlg474rqk3w3d11940hti9', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the coefficient of x⁴ in the binomial expansion of (1 + x + x²)⁵.', null, '["15","25","35","45"]', 3, 'Coefficients of (1+x+x²)⁵ are 1, 5, 15, 30, 45, ... so the coefficient of x⁴ is 45.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Find the coefficient of x⁴ in the binomial expansion of (1 + x + x²)⁵.', '["15","25","35","45"]', 'Coefficients of (1+x+x²)⁵ are 1, 5, 15, 30, 45, ... so the coefficient of x⁴ is 45.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('crnzdhpau5j5r8ny9t3l5v8ru', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'King Josiah ordered an inquiry about the words of the book that was found in the Temple because', null, '["he realized that God was angry with Israel","the people demanded a prophetic interpretation of the book","he was very excited about the discovery","no one was able to read the words of the book"]', 0, 'He realized God was angry with Israel.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'King Josiah ordered an inquiry about the words of the book that was found in the Temple because', '["<u>he realized that God was angry with Israel</u>","the people demanded a prophetic interpretation of the book","he was very excited about the discovery","no one was able to read the words of the book"]', '<u>He realized that God was angry with Israel</u> (2 Kings 22:13).', '{"bold":[],"italic":[],"underline":["he realized that God was angry with Israel"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cro0o5c35xgiv8d13d0pyzqfv', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the derivative of log_x10.', null, '["-log₁₀e/(x(log₁₀x)²)","-log₁₀e/(x²(log₁₀x)²)","-log₁₀e/(log₁₀x)²","-log₁₀e/x"]', 0, 'y = log₁₀10/log₁₀x = 1/log₁₀x; dy/dx = -log₁₀e/(x(log₁₀x)²).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the derivative of log_x10.', '["-log₁₀e/(x(log₁₀x)²)","-log₁₀e/(x²(log₁₀x)²)","-log₁₀e/(log₁₀x)²","-log₁₀e/x"]', 'dy/dx = <u>-log₁₀e/(x(log₁₀x)²)</u>.', '{"bold":[],"italic":[],"underline":["-log₁₀e/(x(log₁₀x)²)"],"fillBlanks":[]}');
