insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cro6fhnoi6eodzcfk8w0w9gxd', 'Biology', 'JAMB', null, 1991, null, 'In plant cells, the chloroplasts are located', null, '["inside the cell wall","outside the protoplasm","within the vacuole","within the cytoplasm"]', 3, 'Chloroplasts are located within the cytoplasm.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In plant cells, the chloroplasts are located', '["inside the cell wall","outside the protoplasm","within the vacuole","<u>within the cytoplasm</u>"]', 'Chloroplasts are located <u>within the cytoplasm</u>.', null);
