insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('crox7dx3wriceuuvw9q9gtgqq', 'Chemistry', 'JAMB', null, 1987, null, '5g of ammonium trioxonitrate(V) on dissolution in water cooled its surrounding water and container by 1.6kJ. What is the heat of solution of NH4NO3? [N=14, O=16, H=1]', null, '["+51.4 kJ mol⁻¹","+25.6 kJ mol⁻¹","+12.9 kJ mol⁻¹","-6.4 kJ mol⁻¹"]', 0, 'Moles = 5/80 = 0.0625; ΔH = 1.6/0.0625 = +25.6 kJ/mol. Key says +51.4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '5g of ammonium trioxonitrate(V) on dissolution in water cooled its surrounding water and container by 1.6kJ. What is the heat of solution of NH4NO3? [N=14, O=16, H=1]', '["+51.4 kJ mol⁻¹","+25.6 kJ mol⁻¹","+12.9 kJ mol⁻¹","-6.4 kJ mol⁻¹"]', 'ΔH = 1.6/0.0625 = <u>+25.6 kJ mol⁻¹</u> (key says +51.4).', '{"bold":[],"italic":[],"underline":["+51.4 kJ mol⁻¹"],"fillBlanks":[]}');
