insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('crpdz6ml7i1qtqp3hry3m8yvu', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The number of takbir observed during salah al-Jana''zah is', null, '["two","three","four","seven."]', 2, 'Four takbir are observed.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The number of takbir observed during salah al-Jana''zah is', '["two","three","<u>four</u>","seven."]', '<u>Four</u>.', '{"bold":[],"italic":[],"underline":["four"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('crpfs3lezmh0m6tv4n8qs89vg', 'Chemistry', 'JAMB', null, 1985, null, 'Which of the following compounds would give <b>lilac flame coloration</b> and a white precipitate with acidified barium chloride solution?', null, '["KCl","NaNO3","K2SO4","CaSO4"]', 2, 'K⁺ gives lilac flame; SO4²⁻ gives white BaSO4 precipitate.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following compounds would give <b>lilac flame coloration</b> and a white precipitate with acidified barium chloride solution?', '["KCl","NaNO3","K2SO4","CaSO4"]', '<u>K2SO4</u> gives lilac flame and white BaSO4 precipitate.', '{"bold":["lilac flame coloration"],"italic":[],"underline":["K2SO4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('crpmaoir5sdg8bfn1iu0k099r', 'General Mathematics', 'JAMB', null, 2020, null, 'Find det [[1, 1, 1], [a, b, c], [a², b², c²]].', null, '["(a-b)(b-c)(c-a)","(a+b)(b+c)(c+a)","abc(a-b)(b-c)","(a-b)(b-c)"]', 0, 'Vandermonde determinant = (a-b)(b-c)(c-a).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find det [[1, 1, 1], [a, b, c], [a², b², c²]].', '["(a-b)(b-c)(c-a)","(a+b)(b+c)(c+a)","abc(a-b)(b-c)","(a-b)(b-c)"]', 'det = <u>(a-b)(b-c)(c-a)</u>.', '{"bold":[],"italic":[],"underline":["(a-b)(b-c)(c-a)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('crq4eg3xxr6zb9ab2d3nm08wt', 'General Mathematics', 'JAMB', null, 2020, null, 'For a symmetric distribution, mean - median =:', null, '["0","1","Negative","Positive"]', 0, 'Symmetric → mean = median.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'For a symmetric distribution, mean - median =:', '["0","1","Negative","Positive"]', 'Value = <u>0</u>.', '{"bold":[],"italic":[],"underline":["0"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('crqdwd9cjlltd5o0ebj65167y', 'General Mathematics', 'WAEC', null, 2020, null, 'What is the product of roots of 3x⁴ - 2x³ + 5x² - 7x + 1 = 0', null, '["1/3","-1/3","1","-1"]', 0, 'Product = 1/3 (constant/leading coefficient for even degree).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is the product of roots of 3x⁴ - 2x³ + 5x² - 7x + 1 = 0', '["1/3","-1/3","1","-1"]', 'Product = <u>1/3</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('crqj5y4c1k7olw2ueypdqtf6y', 'General Mathematics', 'WAEC', null, 2020, null, 'If x³ + 3x² + 3x + 2 = 0 find the sum of squares of reciprocals of roots.', null, '["1/2","1","3/2","2"]', 1, '(x+1)³ + 1 = 0 → x = -1 - ∛(-1) = -1+1 = 0? Actually x³+3x²+3x+2 = (x+1)³+1 = 0 → (x+1)³ = -1 → x+1 = -1, ω, ω²... roots are -2, -1-ω, -1-ω². Sum of squares of reciprocals = ? Key says 1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If x³ + 3x² + 3x + 2 = 0 find the sum of squares of reciprocals of roots.', '["1/2","1","3/2","2"]', 'Sum = <u>1</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('crqka0wumtty8x0xuk4folww2', 'Government', 'JAMB', null, 2020, null, 'The main focus of Nigeria''s foreign policy since independence centres on', null, '["south-south cooperation","sub-regionalism","globalism","afrocentrism."]', 3, 'Nigeria''s foreign policy centres on Afrocentrism.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The main focus of Nigeria''s foreign policy since independence centres on', '["south-south cooperation","sub-regionalism","globalism","<u>afrocentrism.</u>"]', '<u>Afrocentrism</u>.', '{"bold":[],"italic":[],"underline":["afrocentrism."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('crqsjff9h8f9tb3lg3mcixgow', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'When Jonah fled from God when he was sent to Nineveh, he joined a ship from Joppa to', null, '["Nineveh","Cush","Cana","Tarshish."]', 3, 'Jonah fled to Tarshish.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When Jonah fled from God when he was sent to Nineveh, he joined a ship from Joppa to', '["Nineveh","Cush","Cana","<u>Tarshish.</u>"]', '<u>Tarshish</u> (Jonah 1:3).', '{"bold":[],"italic":[],"underline":["Tarshish."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('crqyt3cfctkn3qfn23za9fvm2', 'Biology', 'JAMB', null, 1986, null, 'For effective functioning of a bird''s quill feather, hooks fit on the ridges of the', null, '["vane","rachis","barbules","barbs"]', 2, 'Hooks fit on the ridges of the barbules.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'For effective functioning of a bird''s quill feather, hooks fit on the ridges of the', '["vane","rachis","<u>barbules</u>","barbs"]', 'Hooks fit on the ridges of the <u>barbules</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('crr58iefvsar3c1fsy83ey91j', 'General Mathematics', 'JAMB', null, 2020, null, 'A bag contains 5 red, 4 blue, and 3 green balls. Three balls are drawn at random without replacement. What is the probability that they are all of different colors?', null, '["1/11","3/11","5/11","10/11"]', 1, 'P = (5·4·3)/12C3 = 60/220 = 3/11.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A bag contains 5 red, 4 blue, and 3 green balls. Three balls are drawn at random without replacement. What is the probability that they are all of different colors?', '["1/11","3/11","5/11","10/11"]', 'P = <u>3/11</u>.', '{"bold":[],"italic":[],"underline":["3/11"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('crr6jyjya4p9af7ic16hkow7d', 'Chemistry', 'JAMB', null, 1989, null, 'The scale of a chemical balance is made of iron plate and coated with copper electrolytically because', null, '["iron is less susceptible to corrosion than copper","copper is less susceptible to corrosion than iron","copper is less susceptible to corrosion than iron","copper and iron are equally susceptible to corrosion"]', 1, 'Copper is less susceptible to corrosion than iron.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The scale of a chemical balance is made of iron plate and coated with copper electrolytically because', '["iron is less susceptible to corrosion than copper","copper is less susceptible to corrosion than iron","copper is less susceptible to corrosion than iron","copper and iron are equally susceptible to corrosion"]', '<u>Copper is less susceptible to corrosion</u> than iron.', '{"bold":[],"italic":[],"underline":["copper is less susceptible to corrosion than iron"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('crrinsai0awi94u6dukpnhwma', 'Biology', 'JAMB', null, 2003, null, 'An insect whose economic importance is both harmful and beneficial is the', null, '["butterfly","mosquito","blackfly","tsetsefly"]', 0, 'Butterfly is both harmful (larva) and beneficial (pollinator).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An insect whose economic importance is both harmful and beneficial is the', '["butterfly","mosquito","blackfly","tsetsefly"]', '<u>Butterfly</u> is both harmful and beneficial.', '{"bold":[],"italic":[],"underline":["butterfly"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('crrixibvr97xliwwrjkhlpn7m', 'General Mathematics', 'JAMB', null, 2020, null, 'In how many ways can the letters of the word "CORPORATION" be arranged?', null, '["11!/(2!2!2!)","11!/(2!2!2!2!)","11!/(3!2!2!)","11!/(3!2!)"]', 1, 'C(2), O(3), R(2), P, A, T, I, N → 11!/(3!2!2!) = 11!/(3!2!2!). Key says 11!/(2!2!2!2!).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In how many ways can the letters of the word "CORPORATION" be arranged?', '["11!/(2!2!2!)","11!/(2!2!2!2!)","11!/(3!2!2!)","11!/(3!2!)"]', 'Ways = <u>11!/(2!2!2!2!)</u> (per key).', '{"bold":[],"italic":[],"underline":["11!/(2!2!2!2!)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('crrnn5y1dp6k5qmvpgh4s7u8v', 'Biology', 'JAMB', null, 2000, null, 'For growth to occur in organisms, the rate of', null, '["food storages must be low","catabolism must exceed that of anabolism","anabolism must exceed that of catabolism","food storage must be high"]', 2, 'Anabolism > catabolism for growth.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'For growth to occur in organisms, the rate of', '["food storages must be low","catabolism must exceed that of anabolism","anabolism must exceed that of catabolism","food storage must be high"]', '<u>Anabolism > catabolism</u> for growth.', '{"bold":[],"italic":[],"underline":["anabolism must exceed that of catabolism"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('crrsua16g9zh39kmjwyakn4e9', 'Government', 'JAMB', null, 2020, null, 'Nigeria''s non-alignment policy in the sixties lacked real substance because of her', null, '["Partnership with Asian countries","Close ties with Britain","Afrocentric Policy","Poor economic potential."]', 1, 'Close ties with Britain undermined non-alignment.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Nigeria''s non-alignment policy in the sixties lacked real substance because of her', '["Partnership with Asian countries","<u>Close ties with Britain</u>","Afrocentric Policy","Poor economic potential."]', '<u>Close ties with Britain</u>.', '{"bold":[],"italic":[],"underline":["Close ties with Britain"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('crsa1uy2zs7bcssbl4ry54gee', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Imam Ash-shafi''i studied under two of his predecessors. These are', null, '["Abu Hurayrah and Malik","Malik and Abu Hanifah","Abu Hanifah and ''Umar","''Umar and Abu Bakr."]', 1, 'He studied under Malik and Abu Hanifah.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Imam Ash-shafi''i studied under two of his predecessors. These are', '["Abu Hurayrah and Malik","<u>Malik and Abu Hanifah</u>","Abu Hanifah and ''Umar","''Umar and Abu Bakr."]', '<u>Malik and Abu Hanifah</u>.', '{"bold":[],"italic":[],"underline":["Malik and Abu Hanifah"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('crsbb1xyle11j416wnr38xm4v', 'Biology', 'JAMB', null, 1990, null, 'The mutation theory of organic evolution was propounded by', null, '["Gregor Mendel","Hugo Vries","Jean Lamarck","Charles Darwin"]', 1, 'Hugo de Vries propounded the mutation theory.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The <b>mutation theory</b> of organic evolution was propounded by', '["Gregor Mendel","<u>Hugo Vries</u>","Jean Lamarck","Charles Darwin"]', '<u>Hugo de Vries</u> propounded the mutation theory.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('crsdxalfbnzaaoj8i2st5slrw', 'Physics', 'JAMB', null, 1983, null, 'A short response time is obtained in a liquid-in-glass thermometer when the', null, '["Bulb is large and thick-walled.","Stem is long and thin.","Bulb is small and thick-walled.","Bulb is of high density and the bore is large.","Bulb is thin-walled and the liquid is a good conductor of heat."]', 4, 'Heat must reach the liquid quickly, so the bulb should be thin-walled and the liquid a good conductor of heat.', true, '2026-10-11 21:26:45.728', '2026-10-11 21:26:45.728', null, null, null, 'A short response time is obtained in a liquid-in-glass thermometer when the', '["Bulb is large and thick-walled.","Stem is long and thin.","Bulb is small and thick-walled.","Bulb is of high density and the bore is large.","Bulb is thin-walled and the liquid is a good conductor of heat."]', 'Heat must reach the liquid quickly, so the bulb should be thin-walled and the liquid a good conductor of heat.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('crsi7qs61xrbd8lmcsj6tk2wf', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Jesus said anyone who put his hand to the plough and looked back would not be', null, '["rich on earth","a good teacher","fit for the kingdom of God","able to perform miracles."]', 2, 'He would not be fit for the kingdom of God.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Jesus said anyone who put his hand to the plough and looked back would not be', '["rich on earth","a good teacher","<u>fit for the kingdom of God</u>","able to perform miracles."]', '<u>Fit for the kingdom of God</u> (Luke 9:62).', '{"bold":[],"italic":[],"underline":["fit for the kingdom of God"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('crsk05xn88yt2yf4ow3yqqpm3', 'Biology', 'JAMB', null, 2003, null, 'Soil fertility can best be conserved and renewed by the activities of', null, '["microbes","earthworms","man","rodents"]', 1, 'Earthworms improve soil fertility.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Soil fertility can best be conserved and renewed by the activities of', '["microbes","earthworms","man","rodents"]', '<u>Earthworms</u>.', '{"bold":[],"italic":[],"underline":["earthworms"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('crswpx9z4s2aaoz6o2z4vtxiq', 'Chemistry', 'JAMB', null, 1999, null, 'A pair of compounds that can be used to generate a gas which has physiological effect on human beings is', null, '["sodium trioxonitrate(V) and calcium chloride","sodium dioxonitrate(III) and ammonium chloride","sodium trioxonitrate(V) and ammonium chloride","sodium dioxonitrate(III) and potassium chloride"]', 1, 'NaNO2 + NH4Cl → N2 (physiologically inert) or NH4NO2 → N2. But N2O from NH4NO3 has physiological effect. Key says NaNO2 + NH4Cl.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A pair of compounds that can be used to generate a gas which has physiological effect on human beings is', '["sodium trioxonitrate(V) and calcium chloride","sodium dioxonitrate(III) and ammonium chloride","sodium trioxonitrate(V) and ammonium chloride","sodium dioxonitrate(III) and potassium chloride"]', '<u>NaNO2 + NH4Cl</u> (per key).', '{"bold":[],"italic":[],"underline":["sodium dioxonitrate(III) and ammonium chloride"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('crswy0vuiuswl1id8g0c23227', 'Biology', 'JAMB', null, 1984, null, 'Exoskeleton is NOT found in the', null, '["maggot","mosquito larva","earthworm","caterpillar","termite"]', 2, 'Earthworms have a hydrostatic skeleton, not an exoskeleton.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Exoskeleton is <b>NOT</b> found in the', '["maggot","mosquito larva","<u>earthworm</u>","caterpillar","termite"]', '<u>Earthworms</u> have a hydrostatic skeleton, not an exoskeleton.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('crtdkaw72r04f68vojsmieag7', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Hiram, King of Tyre, was friendly with King Solomon because he', null, '["loved the wisdom of Solomon","loved David, Solomon''s father","was afraid of war","wanted to assist Solomon."]', 1, 'Hiram was friendly with Solomon because he loved David.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Hiram, King of Tyre, was friendly with King Solomon because he', '["loved the wisdom of Solomon","<u>loved David, Solomon''s father</u>","was afraid of war","wanted to assist Solomon."]', '<u>Loved David, Solomon''s father</u> (1 Kings 5:1).', '{"bold":[],"italic":[],"underline":["loved David, Solomon''s father"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('crtgtg1sfsnle75hac1hlsqcg', 'General Mathematics', 'JAMB', null, 2020, null, 'A number decreased by 37.5% equals 40. Find 62.5% of it.', null, '["40","50","60","70"]', 1, '0.625x = 40 → x = 64; 62.5% of 64 = 40. Key says 50.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A number decreased by 37.5% equals 40. Find 62.5% of it.', '["40","50","60","70"]', '0.625x = 40 → x = 64; 62.5% of 64 = <u>40</u> (key says 50).', '{"bold":[],"italic":[],"underline":["50"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('crtrueogetfhgqgn5a4n7m10m', 'Chemistry', 'JAMB', null, 1987, null, 'The solubility of Na3AsO4(H2O)12 is 38.9g per 100g H2O. What is the percentage of Na3AsO4 in the saturated solution? [As=75, Na=23, O=12, H=1]', null, '["87.2%","38.9%","19.1%","13.7%"]', 3, 'Na3AsO4 = 208, hydrate = 424; hydrate fraction of solution = 38.9/138.9 = 28.0%; 28.0% × 208/424 = 13.7%.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'The solubility of Na3AsO4(H2O)12 is 38.9g per 100g H2O. What is the percentage of Na3AsO4 in the saturated solution? [As=75, Na=23, O=12, H=1]', '["87.2%","38.9%","19.1%","13.7%"]', 'Na3AsO4 = 208, hydrate = 424; hydrate fraction of solution = 38.9/138.9 = 28.0%; 28.0% × 208/424 = 13.7%.', '{"bold":[],"italic":[],"underline":["19.1%"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('crtx3ue3k2wvrihwdqivef1st', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'A Muslim who cannot marry for genuine reasons is advised to', null, '["be reciting the Glorious Qur''an for spiritual uplift","engage in supererogatory prayers at night","give sadaqah to the poor and needy","fast periodically for self-discipline."]', 3, 'He should fast for self-discipline.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A Muslim who cannot marry for genuine reasons is advised to', '["be reciting the Glorious Qur''an for spiritual uplift","engage in supererogatory prayers at night","give sadaqah to the poor and needy","<u>fast periodically for self-discipline.</u>"]', '<u>Fast periodically for self-discipline</u> (Q. 24:33).', '{"bold":[],"italic":[],"underline":["fast periodically for self-discipline."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('crtxjnsgq4e9c6ktibivwua8b', 'General Mathematics', 'WAEC', null, 2020, null, 'If n(A) = 10, n(B) = 12, n(A ∩ B) = 4, find n(A × B).', null, '["120","80","48","100"]', 0, 'n(A × B) = n(A) × n(B) = 120.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If n(A) = 10, n(B) = 12, n(A ∩ B) = 4, find n(A × B).', '["120","80","48","100"]', 'n(A × B) = <u>120</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cru721qyw2zmf3vhjdh62126q', 'Government', 'JAMB', null, 2020, null, 'A major problem of the defunct Organization of African Unity was', null, '["language barrier","inadequate resources","cultural diversity","ideological differences."]', 1, 'Inadequate resources was a major OAU problem.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A major problem of the defunct Organization of African Unity was', '["language barrier","<u>inadequate resources</u>","cultural diversity","ideological differences."]', '<u>Inadequate resources</u>.', '{"bold":[],"italic":[],"underline":["inadequate resources"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cru8duanzuzg5gry46qgen5nt', 'Government', 'JAMB', null, 2020, null, 'Government owned companies operating in the economic sector are referred to as', null, '["public investments","public services.","public enterprises","public utilities"]', 2, 'Government-owned economic companies are public enterprises.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Government owned companies operating in the economic sector are referred to as', '["public investments","public services.","<u>public enterprises</u>","public utilities"]', '<u>Public enterprises</u>.', '{"bold":[],"italic":[],"underline":["public enterprises"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('crua7k3xzy0qpqixwy1o7fr8g', 'Chemistry', 'JAMB', null, 1998, null, 'In the conductance of aqueous potassium tetraoxosulphate(VI) solution, the current carriers are the', null, '["ions","electrons","hydrated ions","hydrated electrons"]', 2, 'Ions in solution are hydrated.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the conductance of aqueous potassium tetraoxosulphate(VI) solution, the current carriers are the', '["ions","electrons","hydrated ions","hydrated electrons"]', '<u>Hydrated ions</u> carry the current.', '{"bold":[],"italic":[],"underline":["hydrated ions"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('crukli9ad0julp1164spfixv1', 'Chemistry', 'JAMB', null, 1998, null, 'The oxide that remains unchanged when heated in hydrogen is', null, '["CuO","Fe2O3","PbO2","ZnO"]', 3, 'ZnO is not reduced by hydrogen.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The oxide that remains unchanged when heated in hydrogen is', '["CuO","Fe2O3","PbO2","ZnO"]', '<u>ZnO is not reduced by hydrogen</u>.', '{"bold":[],"italic":[],"underline":["ZnO"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('crunrmncgg1fgupvcm2cxwhzz', 'Biology', 'JAMB', null, 1997, null, 'Oozing out of water from the leaves of plants in a humid environment is known as', null, '["transpiration","osmosis","pinocytosis","guttation"]', 3, 'Guttation is water oozing from leaves.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Oozing out of water from the leaves of plants in a humid environment is known as', '["transpiration","osmosis","pinocytosis","guttation"]', '<u>Guttation</u> is water oozing from leaves.', '{"bold":[],"italic":[],"underline":["guttation"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cruznsy3djtkyumtb0k5clc1f', 'General Mathematics', 'WAEC', null, 2020, null, 'Which is true?', null, '["36 ≡ 1 (mod 7)","36 ≡ 2 (mod 7)","36 ≡ 3 (mod 7)","36 ≡ 4 (mod 7)"]', 0, '36 mod 7 = 1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which is true?', '["36 ≡ 1 (mod 7)","36 ≡ 2 (mod 7)","36 ≡ 3 (mod 7)","36 ≡ 4 (mod 7)"]', '36 ≡ <u>1</u> mod 7.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('crv6jds4uhrj1ibjqzsj3kah7', 'Islamic Religious Studies', 'JAMB', null, 2008, null, 'The official compilation of Hadith was facilitated by', null, '["Caliph Umar b. al-Khattab","Caliph Uthman b. Affan","Caliph Mu''awiyah b. Abi Sufyan","Caliph Umar b. Abdul-Aziz"]', 3, 'Umar b. Abdul-Aziz ordered the official compilation of Hadith.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The official compilation of Hadith was facilitated by', '["Caliph Umar b. al-Khattab","Caliph Uthman b. Affan","Caliph Mu''awiyah b. Abi Sufyan","<u>Caliph Umar b. Abdul-Aziz</u>"]', '<u>Umar b. Abdul-Aziz</u> ordered the official compilation of Hadith.', '{"bold":[],"italic":[],"underline":["Caliph Umar b. Abdul-Aziz"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('crvkxcniawan0n2fmtedsnsfq', 'Government', 'JAMB', null, 2020, null, 'One of the foremost theorists of federalism was', null, '["Baron de Montesquieu","Karl Marx","K.C. Wheare","A.V. Dicey"]', 2, 'K.C. Wheare was a foremost federalism theorist.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One of the foremost theorists of federalism was', '["Baron de Montesquieu","Karl Marx","<u>K.C. Wheare</u>","A.V. Dicey"]', '<u>K.C. Wheare</u>.', '{"bold":[],"italic":[],"underline":["K.C. Wheare"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('crvti05b53l5l0ilodp1lltoh', 'Chemistry', 'JAMB', null, 1994, null, 'Crude copper could be purified by the electrolysis of concentrated copper(II) chloride if the crude copper is', null, '["made both the anode and the cathode","made the cathode","made the anode","dissolved in the solution"]', 2, 'Crude copper is made the anode; pure Cu deposits on cathode.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Crude copper could be purified by the electrolysis of concentrated copper(II) chloride if the crude copper is', '["made both the anode and the cathode","made the cathode","made the anode","dissolved in the solution"]', '<u>Crude copper is the anode</u>.', '{"bold":[],"italic":[],"underline":["made the anode"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('crvyrbwdbv038oolhv9tq2hxd', 'Biology', 'JAMB', null, 2002, null, 'The carnassial teeth of a carnivorous animal consists of the', null, '["last upper premolar and the first lower molar","last upper molar and the last lower molar","first upper premolar and the first lower molar","first upper molar and the first lower molar"]', 0, 'Carnassial teeth are specialized shearing teeth of carnivores, especially the last upper premolar and first lower molar.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The carnassial teeth of a carnivorous animal consists of the', '["<u>last upper premolar and the first lower molar</u>","last upper molar and the last lower molar","first upper premolar and the first lower molar","first upper molar and the first lower molar"]', 'Carnassial teeth are specialized shearing teeth of carnivores, especially the last upper premolar and first lower molar.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('crw1dyfrlczmxk2ffo27xvs30', 'Biology', 'JAMB', null, 1998, null, 'In a water culture experiment, a plant showed poor growth and yellowing of the leaves. These may be due to deficiency of', null, '["copper","iron","magnesium","calcium."]', 1, 'iron is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In a water culture experiment, a plant showed poor growth and yellowing of the leaves. These may be due to deficiency of', '["copper","<u>iron</u>","magnesium","calcium."]', 'iron is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('crw7vipbuqtsspw2wmugjr5c0', 'Chemistry', 'JAMB', null, 1983, null, 'Solutions X, Y, and Z have pH values 3.0, 5.0 and 9.0 respectively. Which of the following statements is correct?', null, '["All the solutions are acidic","All solutions are basic","Y and Z are more acidic than water","Y is more acidic than X","Z is the least acidic"]', 4, 'pH 9 is basic, so among the acidic ones (3 and 5), pH 9 is least acidic overall.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solutions X, Y, and Z have pH values 3.0, 5.0 and 9.0 respectively. Which of the following statements is correct?', '["All the solutions are acidic","All solutions are basic","Y and Z are more acidic than water","Y is more acidic than X","Z is the least acidic"]', 'pH 9 is basic, so among the acidic ones, <u>pH 9 is least acidic</u>.', '{"bold":[],"italic":[],"underline":["Z is the least acidic"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('crwano5upttqj978e8ajchiit', 'Biology', 'JAMB', null, 2003, null, 'The cell component that is present in a prokaryotic cell is the', null, '["ribosome","mitochondrion","chloroplast","nuclear envelope"]', 0, 'Ribosomes are present in prokaryotic cells.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The cell component that is present in a prokaryotic cell is the', '["ribosome","mitochondrion","chloroplast","nuclear envelope"]', '<u>Ribosomes</u> are in prokaryotes.', '{"bold":[],"italic":[],"underline":["ribosome"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('crwehjztnj15ugaxejrelwqxf', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the variance of 2, 4, 6, 8, 10.', null, '["8","6","10","4"]', 0, 'Mean = 6; variance = (16+4+0+4+16)/5 = 40/5 = 8.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the variance of 2, 4, 6, 8, 10.', '["8","6","10","4"]', 'Variance = <u>8</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('crwwj7cwzm12basjcnlvzk70w', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve for x given that: 5^x · 25^(x-1) = 125^(x+2).', null, '["-3","-4","no solution","-6"]', 2, '5^(3x-2) = 5^(3x+6) gives -2 = 6, so there is no solution.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Solve for x given that: 5^x · 25^(x-1) = 125^(x+2).', '["-3","-4","no solution","-6"]', '5^(3x-2) = 5^(3x+6) gives -2 = 6, so there is no solution.', '{"bold":[],"italic":[],"underline":["-5"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('crwyu04c4lwg8vf84igynyolg', 'Biology', 'JAMB', null, 1983, null, 'In what order do the following structures develop during the metamorphosis of the toad? 1. External gills 2. Internal gills 3. Forelimbs 4. Hindlimbs 5. Mouth', null, '["12345","15243","1345","53412","54321"]', 4, 'The correct order is: Mouth (5) → External gills (4) → Internal gills (3) → Forelimbs (2) → Hindlimbs (1) = 54321.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In what order do the following structures develop during the metamorphosis of the toad?<br>1. External gills<br>2. Internal gills<br>3. Forelimbs<br>4. Hindlimbs<br>5. Mouth', '["12345","15243","1345","53412","<u>54321</u>"]', 'The correct order is: Mouth (5) → External gills (4) → Internal gills (3) → Forelimbs (2) → Hindlimbs (1) = <u>54321</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('crx2zsz1taf83jx2yrr442u9o', 'Biology', 'JAMB', null, 1991, null, 'The dark reaction of photosynthesis involves', null, '["fixation of carbon (IV) oxide to give a six-carbon sugar","fixation of carbon (IV) oxide with the help of oxygen","use of carbon (IV) oxide to produce glucose using ATP","ufixation of carbon (IV) oxide on chlorophyll using hydrogen"]', 0, 'The dark reaction fixes CO2 to give a six-carbon sugar.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The dark reaction of photosynthesis involves', '["<u>fixation of carbon (IV) oxide to give a six-carbon sugar</u>","fixation of carbon (IV) oxide with the help of oxygen","use of carbon (IV) oxide to produce glucose using ATP","ufixation of carbon (IV) oxide on chlorophyll using hydrogen"]', 'The dark reaction <u>fixes CO2 to give a six-carbon sugar</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('crx4g2co4zsltufu90p33hn4b', 'Biology', 'JAMB', null, 2004, null, 'In the internal structure of plants, a wide pith in the centre is common to', null, '["dicot root and monocot stems","dicot stems and monocot stems","dicot stem and monocot roots","dicot roots and monocot roots."]', 0, 'dicot root and monocot stems is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the internal structure of plants, a wide pith in the centre is common to', '["<u>dicot root and monocot stems</u>","dicot stems and monocot stems","dicot stem and monocot roots","dicot roots and monocot roots."]', 'dicot root and monocot stems is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('crxk6fjwrk8ehmxhuvhj9ix50', 'General Mathematics', 'JAMB', null, 2020, null, 'Bag 1: 3W, 5B; Bag 2: 4W, 6B. A random bag is chosen and a ball is white. Find the probability it came from Bag 1.', null, '["15/31","16/31","17/31","18/31"]', 0, 'P = (1/2·3/8)/((1/2·3/8) + (1/2·4/10)) = (3/16)/((3/16)+(2/10)) = 15/31.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Bag 1: 3W, 5B; Bag 2: 4W, 6B. A random bag is chosen and a ball is white. Find the probability it came from Bag 1.', '["15/31","16/31","17/31","18/31"]', 'P = <u>15/31</u>.', '{"bold":[],"italic":[],"underline":["15/31"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cry05o88ozd6r5eo72nfx2bpv', 'Chemistry', 'JAMB', null, 1998, null, 'The soil around a battery manufacturing factory is likely to contain a high concentration of', null, '["Ca²⁺ salts","Pb²⁺ salts","Mg²⁺ salts","Al³⁺ salts"]', 1, 'Lead-acid batteries release Pb²⁺ salts.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The soil around a battery manufacturing factory is likely to contain a high concentration of', '["Ca²⁺ salts","Pb²⁺ salts","Mg²⁺ salts","Al³⁺ salts"]', '<u>Pb²⁺ salts</u> from lead-acid batteries.', '{"bold":[],"italic":[],"underline":["Pb²⁺ salts"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cry1b925ieoj10vdia1g8xjfl', 'General Mathematics', 'JAMB', null, 2020, null, 'Evaluate ∫₀¹ xˣ(1 + ln x) dx.', null, '["0","1","2","e"]', 1, 'd/dx(xˣ) = xˣ(1 + ln x); integral = [xˣ]₀¹ = 1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Evaluate ∫₀¹ xˣ(1 + ln x) dx.', '["0","1","2","e"]', 'Integral = <u>1</u>.', '{"bold":[],"italic":[],"underline":["1"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cry6y89i576n265bg4dv4qx7e', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Jesus did not go immediately to attend to Lazarus who was reported sick because He', null, '["did not know how serious the sickness was","wanted His disciples to believe in Him","cared less about Lazarus","was too busy attending to other people."]', 1, 'He wanted His disciples to believe in Him.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Jesus did not go immediately to attend to Lazarus who was reported sick because He', '["did not know how serious the sickness was","<u>wanted His disciples to believe in Him</u>","cared less about Lazarus","was too busy attending to other people."]', '<u>Wanted His disciples to believe in Him</u> (John 11:14-15).', '{"bold":[],"italic":[],"underline":["wanted His disciples to believe in Him"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cry7vfeieqbopu45fkajp6kfr', 'Chemistry', 'JAMB', null, 1998, null, 'Terylene is synthesized from ethane-1,2-diol and benzene-1,4-dicarboxylic acid by', null, '["addition reaction","condensation reaction","elimination reaction","substitution reaction"]', 1, 'Terylene is formed by condensation polymerization.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Terylene is synthesized from ethane-1,2-diol and benzene-1,4-dicarboxylic acid by', '["addition reaction","condensation reaction","elimination reaction","substitution reaction"]', '<u>Condensation reaction</u>.', '{"bold":[],"italic":[],"underline":["condensation reaction"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cry8sd9kqa2yfgjgydevrb7m0', 'Government', 'JAMB', null, 2020, null, 'Socialism is a mode of production based on', null, '["state ownership of the means of production.","collective ownership of the means of production","national ownership of the means of production","mixed ownership of the means of production"]', 1, 'Socialism is based on collective ownership.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Socialism is a mode of production based on', '["state ownership of the means of production.","<u>collective ownership of the means of production</u>","national ownership of the means of production","mixed ownership of the means of production"]', '<u>Collective ownership of the means of production</u>.', '{"bold":[],"italic":[],"underline":["collective ownership of the means of production"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cry9sxpo4nzt2y4ku9hn7rwmy', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'In Colossians, Paul admonished believers not to lie to one another because they', null, '["had put off the old nature with its practices","had known the truth from the very beginning","were waiting for the second coming of Christ","were joint heirs with Christ in the kingdom."]', 0, 'They had put off the old nature with its practices.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In Colossians, Paul admonished believers not to lie to one another because they', '["<u>had put off the old nature with its practices</u>","had known the truth from the very beginning","were waiting for the second coming of Christ","were joint heirs with Christ in the kingdom."]', '<u>Had put off the old nature with its practices</u> (Colossians 3:9).', '{"bold":[],"italic":[],"underline":["had put off the old nature with its practices"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('crytoo8hh0i0gupo8lka5ziv9', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the range of 2, 5, 8, 11, 14, 17.', null, '["15","14","13","12"]', 0, 'Range = 17 - 2 = 15.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the range of 2, 5, 8, 11, 14, 17.', '["15","14","13","12"]', 'Range = <u>15</u>.', '{"bold":[],"italic":[],"underline":["15"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cryzlawp01tpzkz5sgp7alegi', 'Chemistry', 'JAMB', null, 2004, null, 'Which of the following hydrogen halides has the <b>highest entropy</b> value?', null, '["HBr","HF","HI","HCl"]', 2, 'Entropy increases with molecular size; HI has highest entropy.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following hydrogen halides has the <b>highest entropy</b> value?', '["HBr","HF","HI","HCl"]', '<u>HI</u> has the highest entropy.', '{"bold":["highest entropy"],"italic":[],"underline":["HI"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('crzexq9i2gcq9e8tb8d0t6wyl', 'Biology', 'JAMB', null, 1984, null, 'Which of the following is NOT regarded as a pollutant on land or in the air?', null, '["Noise","Smoke","Sulphur dioxide","Carbon monoxide","Nitrogen"]', 4, 'Nitrogen is a major component of air and not a pollutant.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is <b>NOT</b> regarded as a <b>pollutant</b> on land or in the air?', '["Noise","Smoke","Sulphur dioxide","Carbon monoxide","<u>Nitrogen</u>"]', '<u>Nitrogen</u> is a major component of air and not a pollutant.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('crzfa5mq7th1x3wbpc64m5pbf', 'General Mathematics', 'WAEC', null, 2020, null, 'If xʸ = yˣ, find dy/dx.', null, '["y(y - x ln y)/(x(y - ln y))","y(x ln y - y)/(x(y ln x - x))","y(x - y ln x)/(x(y - x ln y))","y(x ln y + y)/(x(y ln x + x))"]', 0, 'Implicit differentiation yields y(y - x ln y)/(x(y - ln y)).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If xʸ = yˣ, find dy/dx.', '["y(y - x ln y)/(x(y - ln y))","y(x ln y - y)/(x(y ln x - x))","y(x - y ln x)/(x(y - x ln y))","y(x ln y + y)/(x(y ln x + x))"]', 'dy/dx = <u>y(y - x ln y)/(x(y - ln y))</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('crzhppz3ox3fasnqqyzp76dsi', 'Biology', 'JAMB', null, 1987, null, 'One of the functions of UNICEF is to', null, '["prevent and control major diseases","prevent disease outbreak by administering vaccines","improve the health and nutrition of children and nursing mothers","monitor environment pollution"]', 2, 'UNICEF works to improve health and nutrition of children and mothers.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One of the functions of <b>UNICEF</b> is to', '["prevent and control major diseases","prevent disease outbreak by administering vaccines","<u>improve the health and nutrition of children and nursing mothers</u>","monitor environment pollution"]', '<u>UNICEF works to improve health and nutrition of children and mothers</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('crznn6fpinmvjkxn1ddtdpfjl', 'Biology', 'JAMB', null, 1987, null, 'In a plant exhibiting alternation of generations, the diploid multicellular stage is known as', null, '["gametophyte","spermatophyte","holophyte","sporophyte"]', 3, 'The diploid multicellular stage is the sporophyte.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In a plant exhibiting alternation of generations, the diploid multicellular stage is known as', '["gametophyte","spermatophyte","holophyte","<u>sporophyte</u>"]', 'The diploid multicellular stage is the <u>sporophyte</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('crznxk8554n8e6suwqo33qwjx', 'Islamic Religious Studies', 'JAMB', null, 2008, null, 'Excluded from inheritance is a', null, '["Brother from the estate of his deceased brother","Man after the death of his wife","Person who kills his father for his estate","Woman because of her gender"]', 2, 'A murderer is excluded from inheriting his victim''s estate.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Excluded from inheritance is a', '["Brother from the estate of his deceased brother","Man after the death of his wife","<u>Person who kills his father for his estate</u>","Woman because of her gender"]', 'A <u>murderer is excluded</u> from inheriting his victim''s estate.', '{"bold":[],"italic":[],"underline":["Person who kills his father for his estate"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('crzt3unfzmjqpgbfxnguwzr90', 'Government', 'JAMB', null, 2020, null, 'Colonization of Africa was mainly motivated by', null, '["security considerations","economic reasons","religious reasons","cultural factors."]', 1, 'Economic reasons mainly motivated colonization.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Colonization of Africa was mainly motivated by', '["security considerations","<u>economic reasons</u>","religious reasons","cultural factors."]', '<u>Economic reasons</u>.', '{"bold":[],"italic":[],"underline":["economic reasons"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('crzxedgss0nytrp0fumtbs59k', 'Biology', 'JAMB', null, 2001, null, 'The jointed structure in insects that bears organs which are sensitive to touch, smell and vibration is the', null, '["maxilla","labium","antenna","abdomen"]', 2, 'The antenna bears sensory organs.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The jointed structure in insects that bears organs which are sensitive to touch, smell and vibration is the', '["maxilla","labium","antenna","abdomen"]', '<u>Antenna</u> bears sensory organs.', '{"bold":[],"italic":[],"underline":["antenna"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('crzymtgkol3yt9vs6obaqygob', 'General Mathematics', 'JAMB', null, 2020, null, 'Find ∫ dx/√(x² + 4).', null, '["ln","x + √(x² + 4)","+ C","sinh⁻¹(x/2) + C","Both A and B","None"]', 2, 'Both forms are equivalent.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find ∫ dx/√(x² + 4).', '["ln","x + √(x² + 4)","+ C","sinh⁻¹(x/2) + C","Both A and B","None"]', '<u>Both A and B</u>.', '{"bold":[],"italic":[],"underline":["Both A and B"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cs02x7iy2en7fozyvuudgderc', 'Chemistry', 'JAMB', null, 1986, null, '20cm³ of 0.1mol NH4OH solution when neutralized with 20.05cm³ of 0.1mol HCl liberated 102 Joules of heat. Calculate the heat of neutralization of NH4OH', null, '["-51.0 kJ mol⁻¹","+57.3 kJ mol⁻¹","+57.0 kJ mol⁻¹","+51.0 kJ mol⁻¹"]', 1, 'Moles = 0.002; heat per mole = 102/0.002 = 51000 J = 51 kJ. Key says +57.3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '20cm³ of 0.1mol NH4OH solution when neutralized with 20.05cm³ of 0.1mol HCl liberated 102 Joules of heat. Calculate the heat of neutralization of NH4OH', '["-51.0 kJ mol⁻¹","+57.3 kJ mol⁻¹","+57.0 kJ mol⁻¹","+51.0 kJ mol⁻¹"]', 'Heat per mole = <u>+51 kJ mol⁻¹</u> (key says +57.3).', '{"bold":[],"italic":[],"underline":["+57.3 kJ mol⁻¹"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cs09ndgvj9cdbto3epeg9pnbi', 'Islamic Religious Studies', 'JAMB', null, 2008, null, 'Which of the following is the correct order of authenticity of three of the six sound collections of the Hadith?', null, '["Bukhari, Muslim and Tirmidhi","Ibn Majah, Muslim and Nasa''i","Muslim, Nasa''i and Ibn Majah","Abu Dawud, Tirmidhi and Bukhari"]', 0, 'The order of authenticity is Bukhari, Muslim, then Tirmidhi.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is the correct order of authenticity of three of the six sound collections of the Hadith?', '["<u>Bukhari, Muslim and Tirmidhi</u>","Ibn Majah, Muslim and Nasa''i","Muslim, Nasa''i and Ibn Majah","Abu Dawud, Tirmidhi and Bukhari"]', 'The order of authenticity is <u>Bukhari, Muslim, then Tirmidhi</u>.', '{"bold":[],"italic":[],"underline":["Bukhari, Muslim and Tirmidhi"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cs0flusf2o047ibie2ep3qfr0', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'According to Amos, the type of famine God said He would send upon the people of Israel was', null, '["hunger for baskets of summer fruits","not hearing the word of the LORD","thirst for water","that of bread."]', 1, 'God said He would send a famine of hearing the word of the LORD.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to Amos, the type of famine God said He would send upon the people of Israel was', '["hunger for baskets of summer fruits","<u>not hearing the word of the LORD</u>","thirst for water","that of bread."]', '<u>Not hearing the word of the LORD</u> (Amos 8:11).', '{"bold":[],"italic":[],"underline":["not hearing the word of the LORD"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cs0t1881ekkil6os6f94fbkgn', 'Chemistry', 'JAMB', null, 1983, null, 'The equilibrium reaction between copper(I) chloride and chlorine at 25°C and 1 atmosphere is represented by the equation: 2CuCl + Cl2 ⇌ 2CuCl2, ΔH = -166 kJ. Which of the following statements is TRUE for the reaction, pressure remaining constant?', null, '["More CuCl2 is formed at 40°C","More CuCl2 is formed at 25°C","Less CuCl2 is formed at 25°C","The reaction is endothermic","The reaction is not affected by temperature"]', 1, 'For an exothermic reaction, lower temperature favours product formation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The equilibrium reaction between copper(I) chloride and chlorine at 25°C and 1 atmosphere is represented by the equation: 2CuCl + Cl2 ⇌ 2CuCl2, ΔH = -166 kJ. Which of the following statements is TRUE for the reaction, pressure remaining constant?', '["More CuCl2 is formed at 40°C","More CuCl2 is formed at 25°C","Less CuCl2 is formed at 25°C","The reaction is endothermic","The reaction is not affected by temperature"]', 'For an <u>exothermic reaction</u>, lower temperature favours product formation.', '{"bold":[],"italic":[],"underline":["More CuCl2 is formed at 25°C"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cs0uokgwqqtqks5wifov6m993', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'How did King Solomon demonstrate his wisdom in setting the dispute over the ownership of a baby by the two prostitutes?', null, '["He interrogated them for seven days until the truth was discovered.","He interrogated them for only three days and the truth was revealed.","He asked them to divide the child into two and the mother was known.","He threatened to give the child to a neutral woman and the mother was known."]', 2, 'He asked them to divide the child into two and the real mother was revealed.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'How did King Solomon demonstrate his wisdom in setting the dispute over the ownership of a baby by the two prostitutes?', '["He interrogated them for seven days until the truth was discovered.","He interrogated them for only three days and the truth was revealed.","<u>He asked them to divide the child into two and the mother was known.</u>","He threatened to give the child to a neutral woman and the mother was known."]', '<u>He asked them to divide the child into two and the mother was known</u> (1 Kings 3:16-27).', '{"bold":[],"italic":[],"underline":["He asked them to divide the child into two and the mother was known."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cs18iv4vgmk3i535yluw20g7j', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the quartile deviation of 4, 6, 8, 10, 12, 14, 16.', null, '["4","5","6","7"]', 0, 'Q1 = 6, Q3 = 14; QD = (14-6)/2 = 4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the quartile deviation of 4, 6, 8, 10, 12, 14, 16.', '["4","5","6","7"]', 'QD = <u>4</u>.', '{"bold":[],"italic":[],"underline":["4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cs1fodcv8an7iggex9d8vuptf', 'Chemistry', 'JAMB', null, 1994, null, 'Which of the following atoms represents <b>deuterium</b>?', null, '["1 proton, 0 neutrons, 0 electrons","1 proton, 0 neutrons, 1 electron","1 proton, 1 neutron, 1 electron","1 proton, 2 neutrons, 1 electron"]', 2, 'Deuterium (²H) has 1 proton, 1 neutron, 1 electron.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following atoms represents <b>deuterium</b>?', '["1 proton, 0 neutrons, 0 electrons","1 proton, 0 neutrons, 1 electron","1 proton, 1 neutron, 1 electron","1 proton, 2 neutrons, 1 electron"]', '<u>Deuterium: 1 proton, 1 neutron, 1 electron</u>.', '{"bold":["deuterium"],"italic":[],"underline":["1 proton, 1 neutron, 1 electron"],"fillBlanks":[]}');
