insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cs5s5j7w2e3rruj8umsjh5kjg', 'Biology', 'JAMB', null, 1985, null, 'At what stage in the life history of a toad is its mode of breathing similar to that of a fish?', null, '["Tadpole stage","External gill stage","Adult stage","Internal gill stage","Larval stage"]', 3, 'The internal gill stage uses gills like a fish.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'At what stage in the life history of a toad is its mode of breathing similar to that of a fish?', '["Tadpole stage","External gill stage","Adult stage","<u>Internal gill stage</u>","Larval stage"]', 'The <u>internal gill stage</u> uses gills like a fish.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cs602rjisoh9yogrv6dr861ao', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'The LORD give you children by this woman. Eli offered this prayer because of Hannah''s', null, '["loan of Samuel to the LORD.","faith in God.","love for the service of the LORD.","desire for more children from God."]', 0, 'Eli prayed because Hannah lent Samuel to the LORD.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The LORD give you children by this woman. Eli offered this prayer because of Hannah''s', '["<u>loan of Samuel to the LORD.</u>","faith in God.","love for the service of the LORD.","desire for more children from God."]', '<u>Loan of Samuel to the LORD</u> (1 Samuel 2:20).', '{"bold":[],"italic":[],"underline":["loan of Samuel to the LORD."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cs6auugsgzvomunfk9ma7cb3e', 'Biology', 'JAMB', null, 1993, null, 'On what structures are the units of inheritance situated?', null, '["Golgi bodies","Ribosomes","Chromosomes","Endoplasmic reticulum"]', 2, 'Units of inheritance are situated on chromosomes.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'On what structures are the units of inheritance situated?', '["Golgi bodies","Ribosomes","<u>Chromosomes</u>","Endoplasmic reticulum"]', '<u>Units of inheritance are situated on chromosomes</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cs6b9a1uicegk68ef7tvyls5r', 'General Mathematics', 'WAEC', null, 2020, null, 'Evaluate 1101₂ + 1011₂ in base two.', null, '["11000₂","10100₂","11010₂","11100₂"]', 0, '1101₂ (13) + 1011₂ (11) = 24 = 11000₂.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Evaluate 1101₂ + 1011₂ in base two.', '["11000₂","10100₂","11010₂","11100₂"]', '1101₂ + 1011₂ = <u>11000₂</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cs6do0532cp0ktb1rq71r7ij5', 'Chemistry', 'JAMB', null, 1999, null, 'Use the periodic table to answer questions 13 and 14. The element that is likely to participate in <b>covalent rather than ionic bonding</b> is', null, '["Z","Y","X","W"]', 2, 'X is in the middle of the period (covalent).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Use the periodic table to answer questions 13 and 14. The element that is likely to participate in <b>covalent rather than ionic bonding</b> is', '["Z","Y","X","W"]', '<u>X (middle of period)</u> is covalent.', '{"bold":["covalent rather than ionic bonding"],"italic":[],"underline":["X"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cs6dq4m6vmax7vlgtdy3e505s', 'General Mathematics', 'JAMB', null, 2020, null, 'If log_3(x² - 4x + 3) = 1 + log_3(x - 3), solve.', null, '["4","5","6","no solution"]', 3, '(x²-4x+3)/(x-3) = 3 → x-1 = 3 → x = 4. But x-3 > 0 → x > 3. So x = 4. Key says no solution.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If log_3(x² - 4x + 3) = 1 + log_3(x - 3), solve.', '["4","5","6","no solution"]', '<u>x = 4</u> (key says no solution).', '{"bold":[],"italic":[],"underline":["no solution"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cs6kn5zml1uzhvstxz42fqkux', 'Biology', 'JAMB', null, 1990, null, 'In mammals, re-absorption of salt takes place in', null, '["IV","III","II","I"]', 1, 'Reabsorption of salt takes place in part III.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In mammals, re-absorption of salt takes place in', '["IV","<u>III</u>","II","I"]', 'Reabsorption of salt takes place in <u>part III</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cs6m2ohsy24ye6yznp4ifsz86', 'Chemistry', 'JAMB', null, 1991, null, 'The electronic configuration of an element is 1s²2s²2p⁶3s²3p³. How many unpaired electrons are there in the element?', null, '["5","4","3","2"]', 2, '3p³ has 3 unpaired electrons (Hund''s rule).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The electronic configuration of an element is 1s²2s²2p⁶3s²3p³. How many unpaired electrons are there in the element?', '["5","4","3","2"]', '<u>3 unpaired electrons</u> in 3p³.', '{"bold":[],"italic":[],"underline":["3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cs6ndluadzp1rtre91i9bx9os', 'Biology', 'JAMB', null, 1987, null, 'Which of the following is NOT a characteristic of snails?', null, '["Bilateral symmetry","Chitinous exoskeleton","Muscular foot","Soft unsegmented body in a mantle"]', 1, 'Snails have a calcareous shell, not a chitinous exoskeleton.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is <b>NOT</b> a characteristic of <b>snails</b>?', '["Bilateral symmetry","<u>Chitinous exoskeleton</u>","Muscular foot","Soft unsegmented body in a mantle"]', 'Snails have a <u>calcareous shell</u>, not a chitinous exoskeleton.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cs6nysbl6tqdz6mlosp24u7oa', 'Biology', 'JAMB', null, 1997, null, 'Water loss is regulated in plants and animals by both the', null, '["scales and the skin","scales and the hair","thick leaves and the feathers","leathery curticle and the feathers."]', 0, 'scales and the skin is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Water loss is regulated in plants and animals by both the', '["<u>scales and the skin</u>","scales and the hair","thick leaves and the feathers","leathery curticle and the feathers."]', 'scales and the skin is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cs6pjwc0e0fdtc296pbk3qbo6', 'General Mathematics', 'WAEC', null, 2020, null, 'Given n(A) = 25, n(B) = 30, n(A ∪ B) = 45, find n(A ∩ B).', null, '["5","10","15","20"]', 1, 'n(A ∩ B) = 25 + 30 - 45 = 10.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Given n(A) = 25, n(B) = 30, n(A ∪ B) = 45, find n(A ∩ B).', '["5","10","15","20"]', 'n(A ∩ B) = <u>10</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cs6sdvilppollejf3ouo921t9', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The Quraysh boycotted Banu Hashim because they', null, '["had all accepted Islam","refused to accept Islam","planned to migrate to Yathrib with the Prophet (S.A.W)","protected the Prophet (S.A.W) and refused to surrender him."]', 3, 'Banu Hashim protected the Prophet and refused to surrender him.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Quraysh boycotted Banu Hashim because they', '["had all accepted Islam","refused to accept Islam","planned to migrate to Yathrib with the Prophet (S.A.W)","<u>protected the Prophet (S.A.W) and refused to surrender him.</u>"]', '<u>Protected the Prophet and refused to surrender him</u>.', '{"bold":[],"italic":[],"underline":["protected the Prophet (S.A.W) and refused to surrender him."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cs6u8ssdzs4jbw4dk5zt1nbpr', 'Chemistry', 'JAMB', null, 1985, null, 'A white solid suspected to be lead trioxonitrate(V), zinc trioxocarbonate(IV) or calcium trioxocarbonate(IV) was heated strongly. Its residue, which was yellow when hot and white when cold, is', null, '["lead(II) oxide","calcium oxide","zinc oxide","lead nitrite"]', 0, 'PbO is yellow when hot and white when cold.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A white solid suspected to be lead trioxonitrate(V), zinc trioxocarbonate(IV) or calcium trioxocarbonate(IV) was heated strongly. Its residue, which was yellow when hot and white when cold, is', '["lead(II) oxide","calcium oxide","zinc oxide","lead nitrite"]', '<u>PbO is yellow when hot and white when cold</u>.', '{"bold":[],"italic":[],"underline":["lead(II) oxide"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cs6xr5r228wb6zrwbi2m6i5s8', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The expression in Surat al-Kafirun is recited', null, '["once","twice","three times","four times."]', 1, 'The expression in Surat al-Kafirun is recited twice.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The expression in Surat al-Kafirun is recited', '["once","<u>twice</u>","three times","four times."]', '<u>Twice</u>.', '{"bold":[],"italic":[],"underline":["twice"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cs6ywknb5kob4uz8bqv7qgy7o', 'Chemistry', 'JAMB', null, 2004, null, 'When steam is passed over red-hot carbon, the substances produced are', null, '["hydrogen and carbon(II) oxide","hydrogen and carbon(IV) oxide","hydrogen and trioxocarbonate(IV) acid","hydrogen, oxygen and carbon(IV) oxide"]', 0, 'C + H2O → CO + H2 (water gas).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When steam is passed over red-hot carbon, the substances produced are', '["hydrogen and carbon(II) oxide","hydrogen and carbon(IV) oxide","hydrogen and trioxocarbonate(IV) acid","hydrogen, oxygen and carbon(IV) oxide"]', '<u>Hydrogen and carbon(II) oxide</u>.', '{"bold":[],"italic":[],"underline":["hydrogen and carbon(II) oxide"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cs7jax1025jjsl06t6t68lj29', 'Biology', 'JAMB', null, 1998, null, 'In blood transfusion, agglutination occurs when', null, '["white blood cells from two individuals meet","two different antibodies meet","two different antigens meet","contrasting antigens and antibodies meet. Use the diagram below to answer question 37 and 38. The alternate depletion patterns of mineral resources over time."]', 1, 'two different antibodies meet is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In blood transfusion, agglutination occurs when', '["white blood cells from two individuals meet","<u>two different antibodies meet</u>","two different antigens meet","contrasting antigens and antibodies meet. Use the diagram below to answer question 37 and 38. The alternate depletion patterns of mineral resources over time."]', 'two different antibodies meet is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cs7noxu4lrctnbnabcs4zb81p', 'Chemistry', 'JAMB', null, 1994, null, 'Which of the following reagents will confirm the presence of <b>unsaturation</b> in a compound?', null, '["Fehling''s solution","Bromine water","Tollen''s reagent","Benedict''s solution"]', 1, 'Bromine water is decolorized by unsaturated compounds.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following reagents will confirm the presence of <b>unsaturation</b> in a compound?', '["Fehling''s solution","Bromine water","Tollen''s reagent","Benedict''s solution"]', '<u>Bromine water</u> confirms unsaturation.', '{"bold":["unsaturation"],"italic":[],"underline":["Bromine water"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cs7t65x2b54dizp8ewyc6d87g', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the equation of the tangent to the circle x² + y² = 25 at the point (3, 4).', null, '["3x + 4y = 25","4x + 3y = 25","3x - 4y = 25","4x - 3y = 25"]', 0, 'Tangent: x·3 + y·4 = 25 → 3x + 4y = 25.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the equation of the tangent to the circle x² + y² = 25 at the point (3, 4).', '["3x + 4y = 25","4x + 3y = 25","3x - 4y = 25","4x - 3y = 25"]', 'Tangent: <u>3x + 4y = 25</u>.', '{"bold":[],"italic":[],"underline":["3x + 4y = 25"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cs7v3uiwd7yhegdxwg5vq9l9s', 'Chemistry', 'JAMB', null, 2019, null, 'The molality of 2% by weight of aqueous solution of H2SO4 (molecular weight of 98)', null, '["0.0051","0.00051","0.051","0.51"]', 3, '2% means 2 g H2SO4 in 98 g water. Moles = 2/98 = 0.0204. Molality = 0.0204/0.098 = 0.208. Closest option is 0.51 (likely 2% in 100 g solution → 2 g in 98 g water → 0.0204/0.098 = 0.208).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The molality of 2% by weight of aqueous solution of H2SO4 (molecular weight of 98)', '["0.0051","0.00051","0.051","<u>0.51</u>"]', 'Molality = moles of solute / kg of solvent = <u>0.208 mol/kg</u> (closest option 0.51).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cs7vx2wxw5dr20dgemzzl124m', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'According to James, when we meet various trials in life, we should', null, '["count it all joy","rejoice because the Lord is good","bless God''s name","call upon the name of the Lord."]', 0, 'We should count it all joy.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to James, when we meet various trials in life, we should', '["<u>count it all joy</u>","rejoice because the Lord is good","bless God''s name","call upon the name of the Lord."]', '<u>Count it all joy</u> (James 1:2).', '{"bold":[],"italic":[],"underline":["count it all joy"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cs84fmb889a0weyr5lhxm04ch', 'Chemistry', 'JAMB', null, 1986, null, 'In the course of an experiment, two gases X and Y were produced. X turned wet lead ethanoate to black and Y bleached moist litmus paper. What are the elements in each of the gases X and Y respectively?', null, '["H and S; Cl","H and O; Cl","H and S; C and O","H and Cl; S and O"]', 2, 'X is H2S (H and S); Y is Cl2 (Cl). Key says H and S; C and O.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the course of an experiment, two gases X and Y were produced. X turned wet lead ethanoate to black and Y bleached moist litmus paper. What are the elements in each of the gases X and Y respectively?', '["H and S; Cl","H and O; Cl","H and S; C and O","H and Cl; S and O"]', 'X is H2S (H and S); Y is Cl2 (Cl).', '{"bold":[],"italic":[],"underline":["H and S; C and O"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cs8bdvz4cjpg0qoibyvnst8eo', 'Physics', 'JAMB', null, 2019, null, 'Which of the following substances has magnetic susceptibility, Xm negative? I. Diamagnetic II. Paramagnetic III. Ferromagnetic', null, '["II only","II & III only","I only","I & III only","III only"]', 2, 'Diamagnetic materials have negative magnetic susceptibility.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following substances has <b>magnetic susceptibility</b>, Xm negative?<br>I. Diamagnetic<br>II. Paramagnetic<br>III. Ferromagnetic', '["II only","II & III only","<u>I only</u>","I & III only","III only"]', '<u>Diamagnetic materials</u> have negative magnetic susceptibility.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cs8gfah2q3larahcszjz2kgwy', 'Biology', 'JAMB', null, 2001, null, 'The factor that least affects food shortages in sub-Saharan Africa is', null, '["flooding","pests","mixed-cropping","drought"]', 2, 'Mixed-cropping reduces food shortage.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The factor that least affects food shortages in sub-Saharan Africa is', '["flooding","pests","mixed-cropping","drought"]', '<u>Mixed-cropping</u> least affects shortages.', '{"bold":[],"italic":[],"underline":["mixed-cropping"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cs8uwiu5i0urgmhiz7zo917ml', 'Biology', 'JAMB', null, 2003, null, 'The umbrella-shaped fruiting body of a fully developed mushroom is the', null, '["mycelium","basidium","pileus","stipe"]', 2, 'The pileus is the umbrella-shaped fruiting body.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The umbrella-shaped fruiting body of a fully developed mushroom is the', '["mycelium","basidium","pileus","stipe"]', '<u>Pileus</u>.', '{"bold":[],"italic":[],"underline":["pileus"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cs9ft3gja2486oqho3by8rvoh', 'General Mathematics', 'JAMB', null, 2020, null, 'If sin A + sin B = 1/2 and cos A + cos B = √3/2, find cos(A + B).', null, '["1/2","√3/2","-1/2","-√3/2"]', 1, '(2sin((A+B)/2)cos((A-B)/2))² + (2cos((A+B)/2)cos((A-B)/2))² = 1 → 4cos²((A-B)/2) = 1 → A-B = 2π/3; solving gives cos(A+B) = √3/2. Key says √3/2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If sin A + sin B = 1/2 and cos A + cos B = √3/2, find cos(A + B).', '["1/2","√3/2","-1/2","-√3/2"]', 'cos(A + B) = <u>√3/2</u> (per key).', '{"bold":[],"italic":[],"underline":["√3/2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cs9iyflarji9s3lnb2zw0hu17', 'Chemistry', 'JAMB', null, 1998, null, 'A solid begins to melt when', null, '["constituent particles acquire a greater kinetic energy","energy of vibration of particles of the solid is less than the intermolecular forces","constituent particles acquire energy above the average kinetic energy","energy of vibration of particles of the solid equals the intermolecular forces"]', 3, 'Melting occurs when vibrational energy equals intermolecular forces.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A solid begins to melt when', '["constituent particles acquire a greater kinetic energy","energy of vibration of particles of the solid is less than the intermolecular forces","constituent particles acquire energy above the average kinetic energy","energy of vibration of particles of the solid equals the intermolecular forces"]', '<u>Vibrational energy equals intermolecular forces</u> at melting.', '{"bold":[],"italic":[],"underline":["energy of vibration of particles of the solid equals the intermolecular forces"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cs9kysitp6bcgqhfzh2z22smh', 'Chemistry', 'JAMB', null, 1992, null, 'The pollutants that are likely to be present in an industrial environment are', null, '["H2S, SO2 and oxides of nitrogen","NH3, HCl and CO","CO2, NH3 and H2S","Dust, NO and Cl2"]', 0, 'Industrial pollution commonly includes H2S, SO2, and NOx.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The pollutants that are likely to be present in an industrial environment are', '["H2S, SO2 and oxides of nitrogen","NH3, HCl and CO","CO2, NH3 and H2S","Dust, NO and Cl2"]', '<u>H2S, SO2, and NOx</u> are common industrial pollutants.', '{"bold":[],"italic":[],"underline":["H2S, SO2 and oxides of nitrogen"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cs9mb62byz15bgrr92hpjfgfz', 'Chemistry', 'JAMB', null, 1989, null, 'How many valence electrons are contained in the element represented by ³¹P?', null, '["3","5","15","31"]', 1, 'Phosphorus (atomic number 15) has 5 valence electrons.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'How many valence electrons are contained in the element represented by ³¹P?', '["3","5","15","31"]', '<u>Phosphorus has 5 valence electrons</u>.', '{"bold":[],"italic":[],"underline":["5"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cs9mjxcnrh2c6jfrsxetfm9oc', 'English Language', 'JAMB', null, 2020, null, 'We are all hungry, we _____ anything to eat since morning.', null, '["didn''t have","haven''t had","hadn''t had","hadn''t have"]', 1, 'Since morning → present perfect "haven''t had".', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'We are all hungry, we _____ anything to eat since morning.', '["didn''t have","haven''t had","hadn''t had","hadn''t have"]', 'Since morning → <u>haven''t had</u>.', '{"bold":[],"italic":[],"underline":["haven''t had"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cs9y3klf26gxxck0vbfv987h4', 'Chemistry', 'JAMB', null, 1983, null, 'A molar solution of caustic soda is prepared by dissolving', null, '["40g NaOH in 100g of water","40g NaOH in 1000g of water","20g NaOH in 500g of solution","20g NaOH in 1000g of solution","20g NaOH in 80g of solution"]', 1, 'A molar solution contains 1 mole (40g) of NaOH per 1000g of solvent.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A molar solution of caustic soda is prepared by dissolving', '["40g NaOH in 100g of water","40g NaOH in 1000g of water","20g NaOH in 500g of solution","20g NaOH in 1000g of solution","20g NaOH in 80g of solution"]', '<u>40g NaOH in 1000g of water</u> gives a molar solution.', '{"bold":[],"italic":[],"underline":["40g NaOH in 1000g of water"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csa8ov36h5l1tfcwwfg96pjoh', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'One quality of a good disciple that was exhibited by the first followers of Jesus was', null, '["diligence","resourcefulness","faith","piousness"]', 2, 'They exhibited faith.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One quality of a good disciple that was exhibited by the first followers of Jesus was', '["diligence","resourcefulness","<u>faith</u>","piousness"]', '<u>Faith</u>.', '{"bold":[],"italic":[],"underline":["faith"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csa8qgs6x8km6usm4u48njjff', 'Biology', 'JAMB', null, 1987, null, 'Which of the following relates to edaphic factors?', null, '["The structure of the earth''s surface","The influence of living organisms on each other","Temperature, rainfall and humidity","The influence of soils on plants and animals"]', 3, 'Edaphic factors relate to soil influence on plants and animals.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following relates to <b>edaphic factors</b>?', '["The structure of the earth''s surface","The influence of living organisms on each other","Temperature, rainfall and humidity","<u>The influence of soils on plants and animals</u>"]', '<u>Edaphic factors relate to soil influence on plants and animals</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csacqm69qcrrchajt4ji281xx', 'English Language', 'JAMB', null, 2020, null, 'The unfavourable economic climate has forced many people to _____ to seek greener pastures.', null, '["fly","immigrate","emigrate","travel"]', 2, 'Emigrate = leave one''s country to live elsewhere.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The unfavourable economic climate has forced many people to _____ to seek greener pastures.', '["fly","immigrate","emigrate","travel"]', '<u>Emigrate</u> = leave one''s country.', '{"bold":[],"italic":[],"underline":["emigrate"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csavj3u0b56xmdlcb8w07wg8s', 'Biology', 'JAMB', null, 2000, null, 'The inner ear contains two main organs, namely, the', null, '["eardrum and eustachian tube","cochlea and semi-circular canals","oval window and ossicles","pinna and cochlea"]', 1, 'Inner ear = cochlea + semicircular canals.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The inner ear contains two main organs, namely, the', '["eardrum and eustachian tube","cochlea and semi-circular canals","oval window and ossicles","pinna and cochlea"]', '<u>Cochlea and semicircular canals</u>.', '{"bold":[],"italic":[],"underline":["cochlea and semi-circular canals"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csaweer6miinbhs2wi253zj30', 'Islamic Religious Studies', 'JAMB', null, 2020, null, '''wa lam yakun lahu kufuwan ahad'' This verse of the Qur''an (112:4) says that Allah', null, '["is childless","is unique","has no parents","has no favourites."]', 1, 'It says Allah is unique.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '''wa lam yakun lahu kufuwan ahad'' This verse of the Qur''an (112:4) says that Allah', '["is childless","<u>is unique</u>","has no parents","has no favourites."]', '<u>Is unique</u> (Q. 112:4).', '{"bold":[],"italic":[],"underline":["is unique"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csax5dsfw8tlosutw2fdyahmq', 'Chemistry', 'JAMB', null, 1991, null, 'Which of the following statements is <b>TRUE</b> of the complete hydrolysis of a glyceride by sodium hydroxide?', null, '["3 moles of NaOH are required for each mole of glyceride","3 moles of glycerol are produced","only one mole of soap is formed","Concentrated H2SO4 is essential for the completion of the reaction"]', 0, 'Complete hydrolysis of a triglyceride requires 3 moles of NaOH.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following statements is <b>TRUE</b> of the complete hydrolysis of a glyceride by sodium hydroxide?', '["3 moles of NaOH are required for each mole of glyceride","3 moles of glycerol are produced","only one mole of soap is formed","Concentrated H2SO4 is essential for the completion of the reaction"]', '<u>3 moles of NaOH</u> are required per mole of glyceride.', '{"bold":["TRUE"],"italic":[],"underline":["3 moles of NaOH are required for each mole of glyceride"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csaxjh27vvns0np4mcnpqbe7n', 'Islamic Religious Studies', 'JAMB', null, 2011, null, 'A characteristic common to Makkan chapters is that, they', null, '["are long","address the people of the Book","contain a lot of oaths","make references to battles"]', 2, 'Makkan chapters contain many oaths.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A characteristic common to Makkan chapters is that, they', '["are long","address the people of the Book","<u>contain a lot of oaths</u>","make references to battles"]', '<u>Makkan chapters</u> contain many oaths.', '{"bold":[],"italic":[],"underline":["contain a lot of oaths"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csazf5tgfo1a88ne9x359ttgz', 'Chemistry', 'JAMB', null, 1986, null, 'The approximate volume of air containing 10cm³ of oxygen is', null, '["20cm³","25cm³","50cm³","100cm³"]', 2, 'Air is ~21% O2, so 10cm³ O2 is in ~50cm³ air.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The approximate volume of air containing 10cm³ of oxygen is', '["20cm³","25cm³","50cm³","100cm³"]', 'Air is ~21% O2, so <u>50cm³</u> of air contains 10cm³ O2.', '{"bold":[],"italic":[],"underline":["50cm³"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csb2epkgng9d2a4c9nuq7v4yw', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'The commander of Jabin''s army was', null, '["Barak","Sisera","Ehud","Shamgar."]', 1, 'Sisera was the commander of Jabin''s army.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The commander of Jabin''s army was', '["Barak","<u>Sisera</u>","Ehud","Shamgar."]', '<u>Sisera</u> (Judges 4:2).', '{"bold":[],"italic":[],"underline":["Sisera"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csb6acmbea1ouakel3n504psv', 'General Mathematics', 'JAMB', null, 2020, null, 'Evaluate ∫₀¹ x²eˣ dx.', null, '["e - 2","e - 1","2e - 3","3e - 5"]', 0, 'Integration by parts twice: result = e - 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Evaluate ∫₀¹ x²eˣ dx.', '["e - 2","e - 1","2e - 3","3e - 5"]', 'Integral = <u>e - 2</u>.', '{"bold":[],"italic":[],"underline":["e - 2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csb785rj6o2cr7v6u67ut1cbj', 'General Mathematics', 'WAEC', null, 2020, null, 'In a school, 60% of students offered Arts, 50% offered Sciences, and 20% offered neither. What percentage offered both Arts and Sciences?', null, '["10%","20%","30%","40%"]', 1, 'At least one = 80%; both = 60 + 50 - 80 = 30%. Key says 20%.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In a school, 60% of students offered Arts, 50% offered Sciences, and 20% offered neither. What percentage offered both Arts and Sciences?', '["10%","20%","30%","40%"]', 'Both = <u>20%</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csbb2658er6tn7k2akuxle470', 'Islamic Religious Studies', 'JAMB', null, 2011, null, '''Do not get angry'' This tradition from the 16th Hadith of an-Nawawi has been repeated by the Prophet (SAW)', null, '["once","twice","thrice","many times"]', 3, 'The Prophet repeated "Do not get angry" many times.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '''Do not get angry'' This tradition from the 16th Hadith of an-Nawawi has been repeated by the Prophet (SAW)', '["once","twice","thrice","<u>many times</u>"]', 'The Prophet repeated <u>"Do not get angry" many times</u>.', '{"bold":[],"italic":[],"underline":["many times"],"fillBlanks":[]}');
