insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csdekzyjlkxr6v39d90mtaw1x', 'Islamic Religious Studies', 'JAMB', null, 2002, null, 'The Makkan suwar lay emphasis on oneness of <b>Allah</b> because', null, '["it was the only way to call Makkans to Islam","it is the only article of faith","the pre-Islamic Makkans worshipped many gods","it is the basis of Iman and other articles of faith"]', 2, 'The Makkans were polytheists, so the Qur''an emphasized Tawhid to reform their faith.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Makkan suwar lay emphasis on oneness of <b>Allah</b> because', '["it was the only way to call Makkans to Islam","it is the only article of faith","<u>the pre-Islamic Makkans worshipped many gods</u>","it is the basis of Iman and other articles of faith"]', 'The Makkans were <u>polytheists</u>, so the Qur''an emphasized Tawhid to reform their faith.', '{"bold":["Allah"],"italic":[],"underline":["the pre-Islamic Makkans worshipped many gods"],"fillBlanks":[]}');
