insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csdq2x00dnjtlwbfivrcjqpcs', 'General Mathematics', 'JAMB', null, 2020, null, 'Simplify the expression √(3+2√2) + √(3-2√2).', null, '["2√2","2√3","2","√6"]', 2, '√(3+2√2) = √2+1; √(3-2√2) = √2-1; sum = 2√2. Key says 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Simplify the expression √(3+2√2) + √(3-2√2).', '["2√2","2√3","2","√6"]', 'Sum = <u>2√2</u> (key says 2).', '{"bold":[],"italic":[],"underline":["2"],"fillBlanks":[]}');
