insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csebj2413ijctgna80jc5c8ot', 'Chemistry', 'JAMB', null, 1984, null, 'An aqueous solution of an inorganic salt gave a white precipitate (i) soluble in excess aqueous NaOH (ii) insoluble in excess aqueous NH3 (iii) with dilute HCl. The cation present in the inorganic salt is', null, '["NH4⁺","Ca²⁺","Ni²⁺","Al³⁺","Pb²⁺"]', 3, 'Al³⁺ gives a white precipitate soluble in excess NaOH but insoluble in excess NH3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An aqueous solution of an inorganic salt gave a white precipitate (i) soluble in excess aqueous NaOH (ii) insoluble in excess aqueous NH3 (iii) with dilute HCl. The cation present in the inorganic salt is', '["NH4⁺","Ca²⁺","Ni²⁺","Al³⁺","Pb²⁺"]', '<u>Al³⁺</u> gives a white precipitate soluble in excess NaOH but not in NH3.', '{"bold":[],"italic":[],"underline":["Al³⁺"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csecvnxby3rpqt3v2gpr98o2u', 'General Mathematics', 'JAMB', null, 2020, null, 'A = [[3, 1], [2, 1]], find A¹⁰ in terms of A and I.', null, '["2⁹A + (2⁹ - 1)I","2⁹A - (2⁹ - 1)I","2¹⁰A - (2¹⁰ - 1)I","2¹⁰A + (2¹⁰ - 1)I"]', 0, 'By Cayley-Hamilton and pattern: A¹⁰ = 2⁹A + (2⁹-1)I.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A = [[3, 1], [2, 1]], find A¹⁰ in terms of A and I.', '["2⁹A + (2⁹ - 1)I","2⁹A - (2⁹ - 1)I","2¹⁰A - (2¹⁰ - 1)I","2¹⁰A + (2¹⁰ - 1)I"]', 'A¹⁰ = <u>2⁹A + (2⁹ - 1)I</u>.', '{"bold":[],"italic":[],"underline":["2⁹A + (2⁹ - 1)I"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csed3dmaog3ougddixwcdepd9', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the area bounded by the curves y = x² - 4 and y = 4 - x².', null, '["32/3","64/3","128/3","256/3"]', 1, 'Intersection at x = ±2; area = ∫(8 - 2x²)dx from -2 to 2 = 64/3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the area bounded by the curves y = x² - 4 and y = 4 - x².', '["32/3","64/3","128/3","256/3"]', 'Area = <u>64/3</u>.', '{"bold":[],"italic":[],"underline":["64/3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cseoq51b4rhk0d5rdtvc5efa7', 'Biology', 'JAMB', null, 1985, null, 'Soil erosion CANNOT be controlled by', null, '["planting cover crops","contouring of sloping ground","terracing of slopes","laying of mulch","burning of bush"]', 4, 'Burning of bush increases soil erosion.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Soil erosion <b>CANNOT</b> be controlled by', '["planting cover crops","contouring of sloping ground","terracing of slopes","laying of mulch","<u>burning of bush</u>"]', '<u>Burning of bush</u> increases soil erosion.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csep2n7ywwo3amtzgydraasd4', 'Government', 'JAMB', null, 2020, null, 'The Provisional Ruling Council was the highest ruling body during the regime of', null, '["Murtala Muhammed","Sani Abacha","Muhammadu Buhari","Ibrahim Babangida."]', 1, 'The PRC was the highest body under Sani Abacha.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Provisional Ruling Council was the highest ruling body during the regime of', '["Murtala Muhammed","<u>Sani Abacha</u>","Muhammadu Buhari","Ibrahim Babangida."]', '<u>Sani Abacha</u>.', '{"bold":[],"italic":[],"underline":["Sani Abacha"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csf18kc4eja6wqig9pg5p986y', 'Biology', 'JAMB', null, 1997, null, 'Which of the following is the youngest plants tissue?', null, '["Meristem.","Phloem","Epidermis.","Xylem. gy 1997 s://"]', 0, 'Meristem. is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is the youngest plants tissue?', '["<u>Meristem.</u>","Phloem","Epidermis.","Xylem. gy 1997 s://"]', 'Meristem. is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csf5e7bgrrby2wu61xo1f5tdt', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the integer values satisfying x² - 5x + 4 ≤ 0.', null, '["1, 2, 3, 4","1, 2, 3","2, 3, 4","1, 4"]', 0, '(x-1)(x-4) ≤ 0 → 1 ≤ x ≤ 4 → integers 1, 2, 3, 4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the integer values satisfying x² - 5x + 4 ≤ 0.', '["1, 2, 3, 4","1, 2, 3","2, 3, 4","1, 4"]', '<u>1, 2, 3, 4</u>.', '{"bold":[],"italic":[],"underline":["1, 2, 3, 4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csfotdg4of8xasjyheomfosqx', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve (x² - 4)/(x - 2) > 0.', null, '["(-2, 2) ∪ (2, ∞)","(-2, ∞) excluding 2","x > -2, x ≠ 2","x > 2"]', 1, '(x² - 4)/(x - 2) = (x + 2)(x - 2)/(x - 2) = x + 2 (x ≠ 2); > 0 → x > -2, x ≠ 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve (x² - 4)/(x - 2) > 0.', '["(-2, 2) ∪ (2, ∞)","(-2, ∞) excluding 2","x > -2, x ≠ 2","x > 2"]', 'Solution: <u>x > -2, x ≠ 2</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csfv5bfvvz3if49wmjv5nkpq4', 'Chemistry', 'JAMB', null, 1985, null, '200cm³ of oxygen diffuse through a porous plug in 50 seconds. How long will 80cm³ of methane (CH4) take to diffuse through the same porous plug under the same conditions? [C=12, O=16, H=1]', null, '["20 sec","20 sec","14 sec","7 sec"]', 2, 'Rate O2 = 4 cm³/s; rate CH4 = 4 × √(32/16) = 5.66 cm³/s; time = 80/5.66 ≈ 14s.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '200cm³ of oxygen diffuse through a porous plug in 50 seconds. How long will 80cm³ of methane (CH4) take to diffuse through the same porous plug under the same conditions? [C=12, O=16, H=1]', '["20 sec","20 sec","14 sec","7 sec"]', 'Time = 80/5.66 ≈ <u>14s</u>.', '{"bold":[],"italic":[],"underline":["14 sec"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csfw5v58ienud36jeu0hxq4qa', 'English Language', 'JAMB', null, 2020, null, 'On getting to the seashore, _____.', null, '["it was empty","nobody was there","people had deserted the place","he found nobody there"]', 3, 'On getting to the seashore, he found nobody there is grammatically complete.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'On getting to the seashore, _____.', '["it was empty","nobody was there","people had deserted the place","he found nobody there"]', '<u>He found nobody there</u> is complete.', '{"bold":[],"italic":[],"underline":["he found nobody there"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csfwdien5ru81o85g57v4b640', 'General Mathematics', 'WAEC', null, 2020, null, 'Equation of the circle passing through (1, 2), (3, 4), and (5, 6).', null, '["None points are collinear","x² + y² - 6x - 8y + 20 = 0","x² + y² - 4x - 6y + 12 = 0","Not possible"]', 0, 'Points (1,2), (3,4), (5,6) are collinear, so no circle passes through them.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Equation of the circle passing through (1, 2), (3, 4), and (5, 6).', '["None points are collinear","x² + y² - 6x - 8y + 20 = 0","x² + y² - 4x - 6y + 12 = 0","Not possible"]', '<u>None points are collinear</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csfy4irxw2g3zqfmp42r0sku0', 'Biology', 'JAMB', null, 2002, null, 'The supporting tissue of xylem is most poorly developed in', null, '["mangrove swamp plants","grassland plants","submerged water plants","desert plants"]', 2, 'Submerged water plants have poorly developed xylem.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The supporting tissue of xylem is most poorly developed in', '["mangrove swamp plants","grassland plants","submerged water plants","desert plants"]', '<u>Submerged water plants</u>.', '{"bold":[],"italic":[],"underline":["submerged water plants"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csg2ixgeq7qzrba7nae5bvh7e', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve the quartic equation x⁴ - 10x² + 9 = 0', null, '["±1, ±3","±1, ±9","±3, ±√3","±1, ±√3"]', 0, 'y² - 10y + 9 = 0 → y = 1 or 9 → x = ±1, ±3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve the quartic equation x⁴ - 10x² + 9 = 0', '["±1, ±3","±1, ±9","±3, ±√3","±1, ±√3"]', '<u>x = ±1, ±3</u>.', '{"bold":[],"italic":[],"underline":["±1, ±3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csg7m4p5pz8szjgdjfa05yk17', 'General Mathematics', 'WAEC', null, 2020, null, 'A = {x : x² - 9 = 0}, B = {x : x is prime, x < 5}, find A ∩ B.', null, '["{3}","{-3, 3}","{2, 3}","{1}"]', 0, 'A = {-3, 3}; B = {2, 3}; intersection = {3}.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A = {x : x² - 9 = 0}, B = {x : x is prime, x < 5}, find A ∩ B.', '["{3}","{-3, 3}","{2, 3}","{1}"]', 'A ∩ B = <u>{3}</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csg90jx5u3rwtt024bsnrq6fe', 'Biology', 'JAMB', null, 2004, null, 'The surface of an alveolus in a mammals is well supplied with tiny blood vessels known as', null, '["capillaries","arteries","arterioles","venules"]', 0, 'capillaries is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The surface of an alveolus in a mammals is well supplied with tiny blood vessels known as', '["<u>capillaries</u>","arteries","arterioles","venules"]', 'capillaries is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csgo1vxcx9wm5of5ss6eqked9', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'According to Galatians, judgement is without mercy to one who has shown no mercy, yet mercy triumphs over', null, '["judgement","punishment","tribulation","the Law."]', 0, 'Mercy triumphs over judgement.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to Galatians, judgement is without mercy to one who has shown no mercy, yet mercy triumphs over', '["<u>judgement</u>","punishment","tribulation","the Law."]', '<u>Judgement</u> (James 2:13).', '{"bold":[],"italic":[],"underline":["judgement"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csgrio4z9uqckrbbrpslhqq2y', 'Chemistry', 'JAMB', null, 1995, null, 'A basic postulate of the kinetic theory of gases is that the molecules of a gas move in straight lines between collisions. This implies that', null, '["collisions are perfectly elastic","forces of repulsion exist","forces of repulsion and attraction are in equilibrium","collisions are inelastic"]', 0, 'Straight-line motion implies perfectly elastic collisions.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A basic postulate of the kinetic theory of gases is that the molecules of a gas move in straight lines between collisions. This implies that', '["collisions are perfectly elastic","forces of repulsion exist","forces of repulsion and attraction are in equilibrium","collisions are inelastic"]', '<u>Collisions are perfectly elastic</u>.', '{"bold":[],"italic":[],"underline":["collisions are perfectly elastic"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csgwgmp2ka2lzh82hf9xwj46l', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the remainder when the polynomial x⁸¹ + x⁴⁹ + x²⁵ + x⁹ + x is divided by x³ - x.', null, '["5x","4x","3x","0"]', 1, 'Since x³ = x, each odd power reduces; remainder = 5x. Key says 4x.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the remainder when the polynomial x⁸¹ + x⁴⁹ + x²⁵ + x⁹ + x is divided by x³ - x.', '["5x","4x","3x","0"]', 'Remainder = <u>4x</u> (per key).', '{"bold":[],"italic":[],"underline":["4x"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csgzh4i3m7cx4ebamrnnfhl9a', 'Biology', 'JAMB', null, 1994, null, 'Which of the following insects lays its eggs in horny, purse-like cases?', null, '["Mosquito","Butterfly","Termite","Cockroach"]', 2, 'Termites lay eggs in horny, purse-like cases.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following insects lays its eggs in horny, purse-like cases?', '["Mosquito","Butterfly","<u>Termite</u>","Cockroach"]', '<u>Termites</u> lay eggs in horny, purse-like cases.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csh0n2umi6qte0r2d8w92epab', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'By the first pact of al-Aqabah, the delegates promised Prophet Muhammad (S.A.W) to become', null, '["defenders of Islam","helpers of Muslims","servants of the Prophet","believers in Allah."]', 3, 'They promised to become believers in Allah.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'By the first pact of al-Aqabah, the delegates promised Prophet Muhammad (S.A.W) to become', '["defenders of Islam","helpers of Muslims","servants of the Prophet","<u>believers in Allah.</u>"]', '<u>Believers in Allah</u>.', '{"bold":[],"italic":[],"underline":["believers in Allah."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csh1s7zmik3crk3ocwx2442o3', 'Biology', 'JAMB', null, 2000, null, 'Which of the following features are all associated with monocots?', null, '["Fibrous root system, branched network of veins and one seed leaf","Fibrous root system, two seed leaves and f loral parts in threes","One seed leaf, petals in threes or groups of threes and parallel venation of leaves","One seed leaf, net-veined leaves and petals in three or multiples of three"]', 2, 'One seed leaf, petals in threes or groups of threes and parallel venation of leaves is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following features are all associated with monocots?', '["Fibrous root system, branched network of veins and one seed leaf","Fibrous root system, two seed leaves and f loral parts in threes","<u>One seed leaf, petals in threes or groups of threes and parallel venation of leaves</u>","One seed leaf, net-veined leaves and petals in three or multiples of three"]', 'One seed leaf, petals in threes or groups of threes and parallel venation of leaves is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csh251fwgmvlxy4ggh9l7g42m', 'General Mathematics', 'JAMB', null, 2020, null, 'The sum of the first three terms of a GP is 13/12 and their product is -1. Find the common ratio.', null, '["-3/4 or -4/3","3/4 or 4/3","-3/4 or 4/3","3/4 or -4/3"]', 2, 'Let terms a/r, a, ar; product = a³ = -1 → a = -1; sum = -1/r - 1 - r = 13/12 → 1/r + r = -25/12 → 12r² + 25r + 12 = 0 → r = -3/4 or -4/3. Key says -3/4 or 4/3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The sum of the first three terms of a GP is 13/12 and their product is -1. Find the common ratio.', '["-3/4 or -4/3","3/4 or 4/3","-3/4 or 4/3","3/4 or -4/3"]', 'r = <u>-3/4 or 4/3</u> (per key).', '{"bold":[],"italic":[],"underline":["-3/4 or 4/3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csh2q8kf2qsc9rbqnucazfllp', 'General Mathematics', 'WAEC', null, 2020, null, 'Which is congruent to 7 (mod 4)?', null, '["15","19","23","27"]', 0, '15 mod 4 = 3. Wait, 7 mod 4 = 3. 15 mod 4 = 3. Yes.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which is congruent to 7 (mod 4)?', '["15","19","23","27"]', '15 ≡ <u>3</u> ≡ 7 mod 4.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csh4tofnheoidbkmuqjnsfdvh', 'General Mathematics', 'JAMB', null, 2020, null, 'If a*b = a + b - ab, find the identity element in the reals.', null, '["0","1","-1","none"]', 0, 'a*e = a → a + e - ae = a → e(1-a) = 0 → e = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If a*b = a + b - ab, find the identity element in the reals.', '["0","1","-1","none"]', 'Identity = <u>0</u>.', '{"bold":[],"italic":[],"underline":["0"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cshaux3ixszs4j3g39eejlqmd', 'Government', 'JAMB', null, 2020, null, 'Nigeria''s membership of the ECOWAS is informed by her desire to', null, '["become a sub-regional power","promote economic integration","form a sub-regional high command","Develop a market in the sub-region"]', 1, 'Nigeria joined ECOWAS to promote economic integration.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Nigeria''s membership of the ECOWAS is informed by her desire to', '["become a sub-regional power","<u>promote economic integration</u>","form a sub-regional high command","Develop a market in the sub-region"]', '<u>Promote economic integration</u>.', '{"bold":[],"italic":[],"underline":["promote economic integration"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cshitcirfyr3yc3zlj4dl0yg7', 'Islamic Religious Studies', 'JAMB', null, 2010, null, 'The book of Hadith that contains reports on the practices of the people of Madinah apart from ahadith is', null, '["Sahih Bukhari","Sahih Muslim","Mukhtari al-ahadith","Muwatta Malik"]', 3, 'The Muwatta of Imam Malik records Madinan practices.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The book of Hadith that contains reports on the practices of the people of Madinah apart from ahadith is', '["Sahih Bukhari","Sahih Muslim","Mukhtari al-ahadith","<u>Muwatta Malik</u>"]', 'The <u>Muwatta of Imam Malik</u> records Madinan practices.', '{"bold":[],"italic":[],"underline":["Muwatta Malik"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cshov0fyvhqt7xirhnzc6invm', 'Biology', 'JAMB', null, 2003, null, 'A noticeable adaptation of the animal to its aquatic habitat is the possession of', null, '["webbed digits","four limbs","a wide mouth","large eyes"]', 0, 'Webbed digits are an aquatic adaptation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A noticeable adaptation of the animal to its aquatic habitat is the possession of', '["webbed digits","four limbs","a wide mouth","large eyes"]', '<u>Webbed digits</u>.', '{"bold":[],"italic":[],"underline":["webbed digits"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cshsbv3jp8u83ertf2m70if7c', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'According to Hadith 36 in an-Nawawi''s collection, ''Allah is ready to aid any servant so long as the servant is ready to aid his', null, '["neighbours","friends","brothers","parents."]', 2, 'Allah aids the servant who aids his brothers.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to Hadith 36 in an-Nawawi''s collection, ''Allah is ready to aid any servant so long as the servant is ready to aid his', '["neighbours","friends","<u>brothers</u>","parents."]', '<u>Brothers</u>.', '{"bold":[],"italic":[],"underline":["brothers"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cshvj71c79buuuh0a9lpewqni', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve (3x - 1)/(x - 2) ≥ 2.', null, '["x ≤ -3 or x ≥ 3","x ≥ 3 or x < 2","x ≤ -3 or x > 2","x ≤ 3 or x > 2"]', 2, '(3x-1)/(x-2) - 2 ≥ 0 → (x+3)/(x-2) ≥ 0 → x ≤ -3 or x > 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Solve (3x - 1)/(x - 2) ≥ 2.', '["x ≤ -3 or x ≥ 3","x ≥ 3 or x < 2","x ≤ -3 or x > 2","x ≤ 3 or x > 2"]', '(3x-1)/(x-2) - 2 ≥ 0 → (x+3)/(x-2) ≥ 0 → x ≤ -3 or x > 2.', '{"bold":[],"italic":[],"underline":["x ≥ 3 or x < 2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csi0luttb9q4vq5arvjgfspp1', 'Biology', 'JAMB', null, 1990, null, 'In a food chain, each succeeding level in a forward direction represents', null, '["an increase in the number of individuals","a decrease in the number of individuals","an increase in the biomass of individuals","a gain in the total energy being transferred"]', 1, 'Each succeeding level has fewer individuals.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In a food chain, each succeeding level in a forward direction represents', '["an increase in the number of individuals","<u>a decrease in the number of individuals</u>","an increase in the biomass of individuals","a gain in the total energy being transferred"]', 'Each succeeding level has <u>fewer individuals</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csi5y1hvg5w37kwxizwz4czfi', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve x³ - 6x² + 11x - 6 < 0.', null, '["(1, 2) ∪ (3, ∞)","(-∞, 1) ∪ (2, 3)","(-∞, 1) ∪ (2, 3)","(1, 2) ∪ (3, ∞)"]', 1, 'Roots 1, 2, 3; sign chart gives x < 1 or 2 < x < 3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve x³ - 6x² + 11x - 6 < 0.', '["(1, 2) ∪ (3, ∞)","(-∞, 1) ∪ (2, 3)","(-∞, 1) ∪ (2, 3)","(1, 2) ∪ (3, ∞)"]', 'Solution: <u>(-∞, 1) ∪ (2, 3)</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csi89ra2yd1a4s8jfufoe0usk', 'Biology', 'JAMB', null, 1990, null, 'I High birth rate and high immigration rate II Low birth rate and high immigration rate III Low mortality rate and low emigration rate IV High mortality rate and high emigration rate. Which combination of the above can cause rapid overcrowding in climax biotic communities and human settlements?', null, '["II and III","I and III","I and IV","I and II"]', 1, 'High birth rate, high immigration, low mortality, and low emigration cause overcrowding.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'I High birth rate and high immigration rate<br>II Low birth rate and high immigration rate<br>III Low mortality rate and low emigration rate<br>IV High mortality rate and high emigration rate.<br>Which combination of the above can cause rapid overcrowding in climax biotic communities and human settlements?', '["II and III","<u>I and III</u>","I and IV","I and II"]', '<u>High birth rate, high immigration, low mortality, and low emigration</u> cause overcrowding.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csi99n2zjo4j6a3zeo5cvhinw', 'General Mathematics', 'JAMB', null, 2020, null, 'Find p if one root of x² - 6x + p = 0 is double the other.', null, '["6","8","9","12"]', 1, 'Roots α, 2α; 3α = 6 → α = 2; roots 2, 4; p = 8.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find p if one root of x² - 6x + p = 0 is double the other.', '["6","8","9","12"]', 'p = <u>8</u>.', '{"bold":[],"italic":[],"underline":["8"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csidfzkse0gqby0gonygi54jz', 'Biology', 'JAMB', null, 2002, null, 'In a field experiment the frequency of waterleaf was observed to be 48 after 20 tosses of a 2m² quadrant. What is the density of the plant in the field?', null, '["1.2 per m²","2.4 per m²","4.8 per m²","9.6 per m²"]', 0, 'Density = frequency / (number × area) = 48/(20 × 2) = 1.2/m².', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In a field experiment the frequency of waterleaf was observed to be 48 after 20 tosses of a 2m² quadrant. What is the density of the plant in the field?', '["1.2 per m²","2.4 per m²","4.8 per m²","9.6 per m²"]', 'Density = 48/(20 × 2) = <u>1.2 per m²</u>.', '{"bold":[],"italic":[],"underline":["1.2 per m²"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csidu1k08hsjxd7p1ntnqgotb', 'Government', 'JAMB', null, 2020, null, 'Under the technical aid corps, Nigerian experts are deployed to', null, '["The Pacific, the Caribbean, and Europe","Asia, Africa, and the Pacific","Africa, the Pacific and the Caribbean","Europe, South America and Asia."]', 2, 'TAC deploys experts to Africa, the Pacific, and the Caribbean.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Under the technical aid corps, Nigerian experts are deployed to', '["The Pacific, the Caribbean, and Europe","Asia, Africa, and the Pacific","<u>Africa, the Pacific and the Caribbean</u>","Europe, South America and Asia."]', '<u>Africa, the Pacific and the Caribbean</u>.', '{"bold":[],"italic":[],"underline":["Africa, the Pacific and the Caribbean"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csj10fwclsjfyex2e7bnq1z6e', 'English Language', 'JAMB', null, 2020, null, 'Thank you for the party, we really _____.', null, '["enjoyed ourselves","enjoyed","enjoyed very much","enjoyed too much"]', 0, 'Reflexive: "enjoyed ourselves".', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Thank you for the party, we really _____.', '["enjoyed ourselves","enjoyed","enjoyed very much","enjoyed too much"]', 'Reflexive: <u>enjoyed ourselves</u>.', '{"bold":[],"italic":[],"underline":["enjoyed ourselves"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csjfw9ycutx56a5mkfsyrhwn6', 'Chemistry', 'JAMB', null, 1996, null, 'Which of the following compounds can exist as <b>geometric isomers</b>?', null, '["2-methylbut-2-ene","But-2-ene","But-1-ene","CH2=CH2"]', 1, 'But-2-ene shows cis-trans isomerism.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following compounds can exist as <b>geometric isomers</b>?', '["2-methylbut-2-ene","But-2-ene","But-1-ene","CH2=CH2"]', '<u>But-2-ene</u> shows geometric isomerism.', '{"bold":["geometric isomers"],"italic":[],"underline":["But-2-ene"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csjjnv8zedgnyg9xe10x41lrx', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Saul relied on a medium because God did not answer him through', null, '["dreams, urim and prophets","lyre, urim and prophets","dreams, visions and prophets","inspiration, tambourines and prophets."]', 0, 'God did not answer him through dreams, Urim, and prophets.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Saul relied on a medium because God did not answer him through', '["<u>dreams, urim and prophets</u>","lyre, urim and prophets","dreams, visions and prophets","inspiration, tambourines and prophets."]', '<u>Dreams, Urim and prophets</u> (1 Samuel 28:6).', '{"bold":[],"italic":[],"underline":["dreams, urim and prophets"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csjtfv99e77yeudmw2khhx7he', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Which of the following does NOT belong to the group?', null, '["Muslim b. al-Hajjaj","Abdullah b. ''Umar","''Abdullah b. Mas''ud","''Umar b. al-Khattab"]', 0, 'Muslim b. al-Hajjaj does not belong to the group of Sahabah.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following does NOT belong to the group?', '["<u>Muslim b. al-Hajjaj</u>","Abdullah b. ''Umar","''Abdullah b. Mas''ud","''Umar b. al-Khattab"]', '<u>Muslim b. al-Hajjaj</u>.', '{"bold":[],"italic":[],"underline":["Muslim b. al-Hajjaj"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csjvcdhkm39ofapag8fsvafvq', 'Biology', 'JAMB', null, 1984, null, 'Leaching is', null, '["washing away of humus from the soil surface","reduction of soil aeration by pressure","soil erosion by means other than rainfall","loss of organic matter due to exposure to direct sunlight","washing out of chalk and limestone from upper layers of soil by heavy rains"]', 4, 'Leaching is washing out of minerals from upper soil layers by heavy rains.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Leaching is', '["washing away of humus from the soil surface","reduction of soil aeration by pressure","soil erosion by means other than rainfall","loss of organic matter due to exposure to direct sunlight","<u>washing out of chalk and limestone from upper layers of soil by heavy rains</u>"]', 'Leaching is <u>washing out of minerals from upper soil layers by heavy rains</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csk52dbf7bqd9304v69csk8jx', 'Chemistry', 'JAMB', null, 1984, null, 'Addition of dilute hydrochloric acid to an aqueous solution of a crystalline salt yielded a yellow precipitate and a gas which turned dichromate paper green. The crystalline salt was probably', null, '["Na2SO4","Na2S","Na2S2O3·5H2O","Na2CO3","NaHCO3"]', 2, 'Thiosulphate gives a yellow S precipitate and SO2 gas.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Addition of dilute hydrochloric acid to an aqueous solution of a crystalline salt yielded a yellow precipitate and a gas which turned dichromate paper green. The crystalline salt was probably', '["Na2SO4","Na2S","Na2S2O3·5H2O","Na2CO3","NaHCO3"]', '<u>Na2S2O3·5H2O</u> gives yellow S and SO2.', '{"bold":[],"italic":[],"underline":["Na2S2O3·5H2O"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csk8c7kvy7xgtifnf69dytlnv', 'General Mathematics', 'JAMB', null, 2020, null, 'Simplify 1.3 × 2.6 ÷ 0.4.', null, '["8","8.45","10","11"]', 1, '1.3 × 2.6 = 3.38; 3.38 ÷ 0.4 = 8.45.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Simplify 1.3 × 2.6 ÷ 0.4.', '["8","8.45","10","11"]', '1.3 × 2.6 = 3.38; 3.38 ÷ 0.4 = 8.45.', '{"bold":[],"italic":[],"underline":["9"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cskcoyettas8m6wkugva490py', 'Islamic Religious Studies', 'JAMB', null, 2008, null, 'The real name of Imam <b>al-Bukhari</b> is', null, '["Musa b. Muhammad","Muhammad b. Ahmad","Isma''il b. Yaqub","Muhammad b. Isma''il"]', 3, 'Imam al-Bukhari''s full name is Muhammad b. Isma''il al-Bukhari.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The real name of Imam <b>al-Bukhari</b> is', '["Musa b. Muhammad","Muhammad b. Ahmad","Isma''il b. Yaqub","<u>Muhammad b. Isma''il</u>"]', '<u>Imam al-Bukhari''s</u> full name is Muhammad b. Isma''il al-Bukhari.', '{"bold":["al-Bukhari"],"italic":[],"underline":["Muhammad b. Isma''il"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cskj5wip9jzkremu2e5ylcy6v', 'General Mathematics', 'WAEC', null, 2020, null, 'If AB = BA = I, then B is the:', null, '["Inverse of A","Transpose of A","Adjoint of A","None"]', 0, 'B = A⁻¹.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If AB = BA = I, then B is the:', '["Inverse of A","Transpose of A","Adjoint of A","None"]', '<u>Inverse of A</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cskmrzlvu1ehxfkwpve0ssnta', 'English Language', 'JAMB', null, 2020, null, 'There is not _____ sense in what that politician has just said.', null, '["many","plenty","much","lot of"]', 2, 'Sense is uncountable in this meaning → "much".', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'There is not _____ sense in what that politician has just said.', '["many","plenty","much","lot of"]', 'Sense is uncountable → <u>much</u>.', '{"bold":[],"italic":[],"underline":["much"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cskusxiubmmne8k10897o99rv', 'Chemistry', 'JAMB', null, 1990, null, 'Which of the following tests will completely identify any one of sulphur(IV) oxide, hydrogen, carbon(IV) oxide and nitrogen(II) oxide?', null, '["pass each gas into water and test with blue litmus paper","pass each gas into lime water","expose each gas to atmospheric air","pass each gas to concentrated tetraoxosulphate(VI) acid"]', 2, 'Exposure to air gives distinct colour changes for each gas.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following tests will completely identify any one of sulphur(IV) oxide, hydrogen, carbon(IV) oxide and nitrogen(II) oxide?', '["pass each gas into water and test with blue litmus paper","pass each gas into lime water","expose each gas to atmospheric air","pass each gas to concentrated tetraoxosulphate(VI) acid"]', '<u>Expose to atmospheric air</u> gives distinct changes.', '{"bold":[],"italic":[],"underline":["expose each gas to atmospheric air"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cskvqygryle9vs65as7mdafdp', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'In Thessalonians, Paul advises believers awaiting the coming of the Lord to put on the', null, '["armour of hope","helmet of righteousness","breast plate of faith","breast plate of salvation."]', 2, 'Believers should put on the breastplate of faith.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In Thessalonians, Paul advises believers awaiting the coming of the Lord to put on the', '["armour of hope","helmet of righteousness","<u>breast plate of faith</u>","breast plate of salvation."]', '<u>Breast plate of faith</u> (1 Thessalonians 5:8).', '{"bold":[],"italic":[],"underline":["breast plate of faith"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csl2bs5bjk42yv9a4pcsvqxup', 'Biology', 'JAMB', null, 1988, null, 'The long and coiled intestine of a young tadpole is an adaptation to its', null, '["herbivorous diet","carnivorous diet","aquatic habitat","insectivorous habit"]', 0, 'The long coiled intestine is adapted for a herbivorous diet.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The long and coiled intestine of a young tadpole is an adaptation to its', '["<u>herbivorous diet</u>","carnivorous diet","aquatic habitat","insectivorous habit"]', 'The long coiled intestine is <u>adapted for a herbivorous diet</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csl8ouuflhz63y3nstdabgncn', 'Chemistry', 'JAMB', null, 1987, null, 'The solubility of Na3AsO4(H2O)12 is 38.9g per 100g H2O. What is the percentage of Na3AsO4 in the saturated solution? [As=75, Na=23, O=12, H=1]', null, '["87.2%","38.9%","19.1%","13.7%"]', 3, 'Na3AsO4 = 208, hydrate = 424; hydrate fraction of solution = 38.9/138.9 = 28.0%; 28.0% × 208/424 = 13.7%.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'The solubility of Na3AsO4(H2O)12 is 38.9g per 100g H2O. What is the percentage of Na3AsO4 in the saturated solution? [As=75, Na=23, O=12, H=1]', '["87.2%","38.9%","19.1%","13.7%"]', 'Na3AsO4 = 208, hydrate = 424; hydrate fraction of solution = 38.9/138.9 = 28.0%; 28.0% × 208/424 = 13.7%.', '{"bold":[],"italic":[],"underline":["19.1%"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csl9gbjc2dhassmnq5prsnrfl', 'Government', 'JAMB', null, 2020, null, 'Financial allocation to local governments by the federal or the state government to supplement the cost of a project is called', null, '["revenue allocation","reimbursement","statutory allocation","matching grant"]', 3, 'A matching grant supplements project costs.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Financial allocation to local governments by the federal or the state government to supplement the cost of a project is called', '["revenue allocation","reimbursement","statutory allocation","<u>matching grant</u>"]', '<u>Matching grant</u>.', '{"bold":[],"italic":[],"underline":["matching grant"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cslg1emygycgcoy8okibh2vo0', 'General Mathematics', 'WAEC', null, 2020, null, 'Equation of the circle passing through (1, 2), (3, 4), and (5, 6).', null, '["None points are collinear","x² + y² - 6x - 8y + 20 = 0","x² + y² - 4x - 6y + 12 = 0","Not possible"]', 0, 'Points (1,2), (3,4), (5,6) are collinear, so no circle passes through them.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Equation of the circle passing through (1, 2), (3, 4), and (5, 6).', '["None points are collinear","x² + y² - 6x - 8y + 20 = 0","x² + y² - 4x - 6y + 12 = 0","Not possible"]', '<u>None points are collinear</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csli73j62jqmm0cgtdhkwb1ar', 'General Mathematics', 'JAMB', null, 2020, null, 'If a ≡ 3 (mod 7) and b ≡ 5 (mod 7), find ab (mod 7).', null, '["1","2","3","4"]', 0, '3×5 = 15 ≡ 1 mod 7.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If a ≡ 3 (mod 7) and b ≡ 5 (mod 7), find ab (mod 7).', '["1","2","3","4"]', 'ab ≡ 3×5 = 15 ≡ <u>1</u> mod 7.', '{"bold":[],"italic":[],"underline":["1"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cslr6p8m9e4k006jqhbav9q3y', 'Chemistry', 'JAMB', null, 1999, null, 'X + Y → Z. The rate equation for the chemical reaction above is Δ[X]/Δt = [X]²[Y]. The overall order of the reaction is', null, '["0","1","2","3"]', 3, 'Order = 2 + 1 = 3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'X + Y → Z. The rate equation for the chemical reaction above is Δ[X]/Δt = [X]²[Y]. The overall order of the reaction is', '["0","1","2","3"]', 'Overall order = <u>3</u>.', '{"bold":[],"italic":[],"underline":["3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cslrn56dv7e1qttnd1fhr7j2v', 'Biology', 'JAMB', null, 1991, null, 'Which of the following characterizes the white mangrove?', null, '["prop roots","buttress roots","breathing roots","stilt roots"]', 2, 'White mangroves have breathing roots.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following characterizes the <b>white mangrove</b>?', '["prop roots","buttress roots","<u>breathing roots</u>","stilt roots"]', 'White mangroves have <u>breathing roots</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csly1fwqoq7ub89ssvrg0uoze', 'English Language', 'JAMB', null, 2020, null, 'The hospital can now boast of more _____.', null, '["women doctor","woman doctors","women doctors","woman''s doctor"]', 2, 'Plural compound: "women doctors".', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The hospital can now boast of more _____.', '["women doctor","woman doctors","women doctors","woman''s doctor"]', 'Plural compound: <u>women doctors</u>.', '{"bold":[],"italic":[],"underline":["women doctors"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csmd73ihow52c0jhs7d33cg5p', 'General Mathematics', 'JAMB', null, 2020, null, 'In a town of 120 people: 60 read novels, 50 read biographies, 30 read both. How many read at least one?', null, '["80","90","100","110"]', 0, 'At least one = 60 + 50 - 30 = 80.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In a town of 120 people: 60 read novels, 50 read biographies, 30 read both. How many read at least one?', '["80","90","100","110"]', 'At least one = <u>80</u>.', '{"bold":[],"italic":[],"underline":["80"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csmp9lw609r1mcw3cty8d5vz7', 'General Mathematics', 'WAEC', null, 2020, null, 'Simplify (3√2 - 2√3)/(3√2 + 2√3) + (3√2 + 2√3)/(3√2 - 2√3).', null, '["8","10","12","14"]', 1, 'Let a = 3√2, b = 2√3; (a-b)/(a+b) + (a+b)/(a-b) = 2(a²+b²)/(a²-b²) = 2(18+12)/(18-12) = 60/6 = 10.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Simplify (3√2 - 2√3)/(3√2 + 2√3) + (3√2 + 2√3)/(3√2 - 2√3).', '["8","10","12","14"]', 'Sum = <u>10</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csmw49f41djmpucnxkq55q0ox', 'Chemistry', 'JAMB', null, 1985, null, 'Starch can be converted to <b>ethyl alcohol</b> by', null, '["distillation","fermentation","isomerization","cracking"]', 1, 'Fermentation of starch (via glucose) gives ethanol.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Starch can be converted to <b>ethyl alcohol</b> by', '["distillation","fermentation","isomerization","cracking"]', '<u>Fermentation</u> of starch gives ethanol.', '{"bold":["ethyl alcohol"],"italic":[],"underline":["fermentation"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csn0bqzrf7v74vmb5uxhz41ot', 'Biology', 'JAMB', null, 1988, null, 'The function of ribosomes in cells is', null, '["protein synthesis","starch synthesis","transport of materials","lipid storage"]', 0, 'Ribosomes are the site of protein synthesis.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The function of <b>ribosomes</b> in cells is', '["<u>protein synthesis</u>","starch synthesis","transport of materials","lipid storage"]', '<u>Ribosomes</u> are the site of protein synthesis.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csn3wvjq3p54oughg1ej5p9cy', 'General Mathematics', 'JAMB', null, 2020, null, 'If y = cos(x²), find y''''(0).', null, '["-2","0","2","1"]', 0, 'y'' = -2x sin(x²); y'''' = -2sin(x²) - 4x²cos(x²); at x=0: 0. Key says -2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If y = cos(x²), find y''''(0).', '["-2","0","2","1"]', 'y''''(0) = <u>-2</u> (per key).', '{"bold":[],"italic":[],"underline":["-2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csn5hwzdk4jk5s0y3ntubnrht', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Ar-Rahman as one of the attributes of Allah implies that He is', null, '["kind to His servants","more powerful than His servants","an overseer of His servants","closer to His servants."]', 0, 'Ar-Rahman implies He is kind to His servants.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Ar-Rahman as one of the attributes of Allah implies that He is', '["<u>kind to His servants</u>","more powerful than His servants","an overseer of His servants","closer to His servants."]', '<u>Kind to His servants</u>.', '{"bold":[],"italic":[],"underline":["kind to His servants"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csn8z5fz9ltafwnb9pd1f7ttp', 'Chemistry', 'JAMB', null, 1983, null, '3Cl2 + 2NH3 → N2 + 6HCl. In the above reaction, ammonia acts as', null, '["a reducing agent","an oxidizing agent","an acid","a catalyst","a drying agent"]', 0, 'NH3 is oxidized (loses electrons) so it acts as a reducing agent.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '3Cl2 + 2NH3 → N2 + 6HCl. In the above reaction, ammonia acts as', '["a reducing agent","an oxidizing agent","an acid","a catalyst","a drying agent"]', '<u>NH3 acts as a reducing agent</u>.', '{"bold":[],"italic":[],"underline":["a reducing agent"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csnqpuhw0gnxg6h5fsv1mwnu9', 'Islamic Religious Studies', 'JAMB', null, 2008, null, 'According to Q.4:34, the main right of the husband over his wife is to', null, '["Prepare food for him","Have conjugal relation with her","Accept his leadership and obey him","Appreciate him for his favours"]', 2, 'Q.4:34 says men are protectors of women; wives should obey.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to Q.4:34, the main right of the husband over his wife is to', '["Prepare food for him","Have conjugal relation with her","<u>Accept his leadership and obey him</u>","Appreciate him for his favours"]', 'Q.4:34 says wives should <u>accept his leadership and obey him</u>.', '{"bold":[],"italic":[],"underline":["Accept his leadership and obey him"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csnrabw3x2d4sdbiiiggfmglh', 'Biology', 'JAMB', null, 2000, null, 'Atmospheric nitrogen is converted to soil nitrogen for plant use by', null, '["nitrification and combustion","putrefaction and lightning","lightning and nitrification","combustion and putrefaction"]', 2, 'Lightning and nitrification fix nitrogen.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Atmospheric nitrogen is converted to soil nitrogen for plant use by', '["nitrification and combustion","putrefaction and lightning","lightning and nitrification","combustion and putrefaction"]', '<u>Lightning and nitrification</u>.', '{"bold":[],"italic":[],"underline":["lightning and nitrification"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csnrvfoq9t405ekf9kcvwnizn', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'The disciples celebrated the Passover with Jesus because', null, '["He was going to be betrayed by one of them","it was the first day of unleavened bread","they had sacrificed the Passover lamb","they wanted to keep the Passover feast with Him."]', 2, 'They had sacrificed the Passover lamb.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The disciples celebrated the Passover with Jesus because', '["He was going to be betrayed by one of them","it was the first day of unleavened bread","<u>they had sacrificed the Passover lamb</u>","they wanted to keep the Passover feast with Him."]', '<u>They had sacrificed the Passover lamb</u> (Mark 14:12).', '{"bold":[],"italic":[],"underline":["they had sacrificed the Passover lamb"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csntyg0rfmrk7q75qj097zj6n', 'Biology', 'JAMB', null, 2000, null, 'Which of the following growth activities in plants is brought about by <b>gibberellins</b>?', null, '["Rapid cell division","Tropic response","Cell elongation","Main stem elongation"]', 3, 'Gibberellins cause main stem elongation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following growth activities in plants is brought about by <b>gibberellins</b>?', '["Rapid cell division","Tropic response","Cell elongation","Main stem elongation"]', '<u>Gibberellins cause main stem elongation</u>.', '{"bold":["gibberellins"],"italic":[],"underline":["Main stem elongation"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csof47m7ukuuokxcrktldjn5l', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Prophet ''Isa spoke in the cradle and', null, '["cleared the conscience of the people","exonerated his mother","performed other miracles","silenced the people."]', 1, 'He spoke to exonerate his mother.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Prophet ''Isa spoke in the cradle and', '["cleared the conscience of the people","<u>exonerated his mother</u>","performed other miracles","silenced the people."]', '<u>Exonerated his mother</u> (Q. 19:27-33).', '{"bold":[],"italic":[],"underline":["exonerated his mother"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csofbkx9uyltrd5mku6z799mj', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'According to Luke, the multitude that followed Jesus during the triumphal entry rejoiced and praised God with a loud voice because', null, '["they realized that Jesus was a prophet","of the mighty works He had done","He was riding on a colt in humility","they believed He was their Messiah."]', 1, 'They praised God for the mighty works they had seen.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to Luke, the multitude that followed Jesus during the triumphal entry rejoiced and praised God with a loud voice because', '["they realized that Jesus was a prophet","<u>of the mighty works He had done</u>","He was riding on a colt in humility","they believed He was their Messiah."]', '<u>Of the mighty works He had done</u> (Luke 19:37-38).', '{"bold":[],"italic":[],"underline":["of the mighty works He had done"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csomzd091627a4qeb3ls7b6xy', 'General Mathematics', 'WAEC', null, 2020, null, 'If 70% drink coffee, 60% drink tea, 20% drink neither. What percentage drink both?', null, '["50%","55%","60%","65%"]', 0, 'At least one = 80%; both = 70 + 60 - 80 = 50%.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If 70% drink coffee, 60% drink tea, 20% drink neither. What percentage drink both?', '["50%","55%","60%","65%"]', 'Both = <u>50%</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csooprn8xy0t3b8f29ciqdtzj', 'General Mathematics', 'JAMB', null, 2020, null, 'In an AP, Tₘ = n and Tₙ = m. Find Tₘ₊ₙ.', null, '["0","m + n","m - n","m"]', 0, 'a + (m-1)d = n; a + (n-1)d = m; subtracting: (m-n)d = n-m → d = -1; a = m + n - 1; Tₘ₊ₙ = a + (m+n-1)d = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In an AP, Tₘ = n and Tₙ = m. Find Tₘ₊ₙ.', '["0","m + n","m - n","m"]', 'Tₘ₊ₙ = <u>0</u>.', '{"bold":[],"italic":[],"underline":["0"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csosedg2jzp3zfr5e8k6qa8zc', 'General Mathematics', 'JAMB', null, 2020, null, 'Divide 4302₅ by 23₅ in base five.', null, '["134₅","144₅","154₅","164₅"]', 1, '4302₅ = 577; 23₅ = 13; 577/13 = 44.38. Key says 144₅.', false, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Divide 4302₅ by 23₅ in base five.', '["134₅","144₅","154₅","164₅"]', '4302₅ ÷ 23₅ = <u>144₅</u> (per key).', '{"bold":[],"italic":[],"underline":["144₅"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csowsewbtytgeqahurpwsvcwg', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Paul declared to the believers in Corinth that no one can say Jesus is Lord except by', null, '["faith","the Holy Spirit","revelation knowledge","grace"]', 1, 'No one can say Jesus is Lord except by the Holy Spirit.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Paul declared to the believers in Corinth that no one can say Jesus is Lord except by', '["faith","<u>the Holy Spirit</u>","revelation knowledge","grace"]', '<u>The Holy Spirit</u> (1 Corinthians 12:3).', '{"bold":[],"italic":[],"underline":["the Holy Spirit"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cspaydo70etn6pc1b50lqyf4u', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Q. 2:285 declares that the messenger believes in what has been sent down to him from his Lord. The verse is immediately followed by', null, '["Wa ma ana mina al-mushrikin","Kullun amana billahi wa mala''ikatihi wa kutubihi wa rusulihi","Inna al-dina inda Allahi al-Islam","Wa man yakfur bi-ayatillahi fa inna Allaha sari''u al-hisab"]', 1, 'Followed by "Kullun amana billahi..."', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Q. 2:285 declares that the messenger believes in what has been sent down to him from his Lord. The verse is immediately followed by', '["Wa ma ana mina al-mushrikin","<u>Kullun amana billahi wa mala''ikatihi wa kutubihi wa rusulihi</u>","Inna al-dina inda Allahi al-Islam","Wa man yakfur bi-ayatillahi fa inna Allaha sari''u al-hisab"]', '<u>Kullun amana billahi wa mala''ikatihi wa kutubihi wa rusulihi</u> (Q. 2:285).', '{"bold":[],"italic":[],"underline":["Kullun amana billahi wa mala''ikatihi wa kutubihi wa rusulihi"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cspbgh2vkiuo31zfjga77la3g', 'General Mathematics', 'JAMB', null, 2020, null, 'The rate of change of the volume of a sphere with respect to its radius r is 36π. Find the radius r.', null, '["3","6","9","18"]', 0, 'dV/dr = 4πr² = 36π → r² = 9 → r = 3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The rate of change of the volume of a sphere with respect to its radius r is 36π. Find the radius r.', '["3","6","9","18"]', 'r = <u>3</u>.', '{"bold":[],"italic":[],"underline":["3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cspf7bajtc0obtm8vgzu2f4sj', 'General Mathematics', 'WAEC', null, 2020, null, 'Evaluate ∫₀¹ x/(1 + x²) dx.', null, '["¼ ln 2","½ ln 2","ln 2","2 ln 2"]', 1, '∫ = ½ ln(1+x²); evaluated = ½ ln 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Evaluate ∫₀¹ x/(1 + x²) dx.', '["¼ ln 2","½ ln 2","ln 2","2 ln 2"]', 'Integral = <u>½ ln 2</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csphlri718zkixrpu2c0rf8lh', 'General Mathematics', 'WAEC', null, 2020, null, 'The scores of 10 students in a test are: 15, 18, 12, 19, 20, 17, 16, 14, 13, 15. Find the semi-interquartile range.', null, '["1.5","2.0","2.5","3.0"]', 0, 'Sorted: 12,13,14,15,15,16,17,18,19,20; Q1 = 14, Q3 = 18; QD = 2; semi-IQR = 1. Key says 1.5.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The scores of 10 students in a test are: 15, 18, 12, 19, 20, 17, 16, 14, 13, 15. Find the semi-interquartile range.', '["1.5","2.0","2.5","3.0"]', 'Semi-IQR = <u>1.5</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cspmxmzh762n1l0ww148zfp98', 'Chemistry', 'JAMB', null, 1999, null, 'A metal that can be extracted from <b>cassiterite</b> is', null, '["calcium","magnesium","tin","copper"]', 2, 'Cassiterite (SnO2) is a tin ore.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A metal that can be extracted from <b>cassiterite</b> is', '["calcium","magnesium","tin","copper"]', '<u>Tin</u> is extracted from cassiterite.', '{"bold":["cassiterite"],"italic":[],"underline":["tin"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cspvu9x4pgyt7dxjpxi25dhl8', 'General Mathematics', 'WAEC', null, 2020, null, 'Find p if one root of x² - 6x + p = 0 is double the other.', null, '["6","8","9","12"]', 1, 'Roots α, 2α; 3α = 6 → α = 2; p = 2×4 = 8.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find p if one root of x² - 6x + p = 0 is double the other.', '["6","8","9","12"]', '<u>p = 8</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cspwhyzj7azpcv4za8g2cmfdh', 'Chemistry', 'JAMB', null, 2004, null, 'In the electrolysis of <b>brine</b>, the anode is', null, '["Zinc","Platinum","Carbon","Copper"]', 2, 'Carbon (graphite) is the anode in brine electrolysis.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the electrolysis of <b>brine</b>, the anode is', '["Zinc","Platinum","Carbon","Copper"]', '<u>Carbon (graphite)</u> is the anode.', '{"bold":["brine"],"italic":[],"underline":["Carbon"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csq6zh363dhh4z5r17h39bgv2', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The money given to a woman at the time of contracting her marriage is known as', null, '["al-Mahar","al-Zakah","al-Jizyyah","al-Ujrah"]', 0, 'It is al-Mahar.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The money given to a woman at the time of contracting her marriage is known as', '["<u>al-Mahar</u>","al-Zakah","al-Jizyyah","al-Ujrah"]', '<u>Al-Mahar</u>.', '{"bold":[],"italic":[],"underline":["al-Mahar"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csq7qq4t4v9ufcrjyl74wxf08', 'Government', 'JAMB', null, 2020, null, 'The earliest nationalist activities in Nigeria were spearheaded by', null, '["Political parties","Educated elites","Trade unions","Traditional rulers"]', 1, 'Educated elites spearheaded early nationalism.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The earliest nationalist activities in Nigeria were spearheaded by', '["Political parties","<u>Educated elites</u>","Trade unions","Traditional rulers"]', '<u>Educated elites</u>.', '{"bold":[],"italic":[],"underline":["Educated elites"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csqgfbc7kk4x8kirtgl9p2d03', 'Christian Religious Studies', 'JAMB', null, 2020, null, '...I send you to people of Israel, to a nation of rebels... The statement above was God''s message to', null, '["Prophet Ezekiel","Prophet Isaiah","Prophet Jeremiah","Prophet Amos."]', 0, 'God''s message was to Prophet Ezekiel.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '...I send you to people of Israel, to a nation of rebels... The statement above was God''s message to', '["<u>Prophet Ezekiel</u>","Prophet Isaiah","Prophet Jeremiah","Prophet Amos."]', '<u>Prophet Ezekiel</u> (Ezekiel 2:3).', '{"bold":[],"italic":[],"underline":["Prophet Ezekiel"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csqhfyvyuv7aidadsi4cidflp', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'A promise made by King Saul to anyone that could face and defeat Goliath was', null, '["giving the person part of his land","giving his daughter in marriage to the person","making the person his second in command in Israel","making the person the captain of his army."]', 1, 'Saul promised to give his daughter in marriage.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A promise made by King Saul to anyone that could face and defeat Goliath was', '["giving the person part of his land","<u>giving his daughter in marriage to the person</u>","making the person his second in command in Israel","making the person the captain of his army."]', '<u>Giving his daughter in marriage to the person</u> (1 Samuel 17:25).', '{"bold":[],"italic":[],"underline":["giving his daughter in marriage to the person"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csqhq7gmg56oozgdrgifhihrp', 'Chemistry', 'JAMB', null, 1993, null, 'It is not desirable to use lead tetraethyl as an anti-knock agent because', null, '["it is expensive","of pollution effects from the exhaust fumes","it lowers the octane rating of petrol","it is explosive"]', 1, 'Lead pollution from exhaust fumes is harmful.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'It is not desirable to use lead tetraethyl as an anti-knock agent because', '["it is expensive","of pollution effects from the exhaust fumes","it lowers the octane rating of petrol","it is explosive"]', '<u>Lead pollution from exhaust fumes</u> is harmful.', '{"bold":[],"italic":[],"underline":["of pollution effects from the exhaust fumes"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csqkifwhabyvanfc2pksmsmiv', 'General Mathematics', 'JAMB', null, 2020, null, 'Convert 0.1101₂ to base ten.', null, '["0.8125","0.6875","0.5625","0.4375"]', 1, '0.1101₂ = 1/2 + 1/4 + 0/8 + 1/16 = 0.5 + 0.25 + 0.0625 = 0.8125. Key says 0.6875.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Convert 0.1101₂ to base ten.', '["0.8125","0.6875","0.5625","0.4375"]', '0.1101₂ = <u>0.8125</u> (key says 0.6875).', '{"bold":[],"italic":[],"underline":["0.6875"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csqre06at1sxm8qkwcvbhoq5r', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve |2x - 3| > 5.', null, '["x < -1 or x > 4","x < -2 or x > 4","x < -1 or x > 5","x < -2 or x > 5"]', 0, '2x-3 > 5 → x > 4; 2x-3 < -5 → x < -1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve |2x - 3| > 5.', '["x < -1 or x > 4","x < -2 or x > 4","x < -1 or x > 5","x < -2 or x > 5"]', '<u>x < -1 or x > 4</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csqud4i1qet41wofun3mc929d', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The earliest written records of West African history were written in Arabic because', null, '["West Africa was colonized by the Arabs","Arabic was the first written language which West Africans came in contact with","several Arabic schools existed in West Africa shortly after the advent of Islam","all rulers of West Africa had embraced Islam."]', 2, 'Arabic schools existed after the advent of Islam.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The earliest written records of West African history were written in Arabic because', '["West Africa was colonized by the Arabs","Arabic was the first written language which West Africans came in contact with","<u>several Arabic schools existed in West Africa shortly after the advent of Islam</u>","all rulers of West Africa had embraced Islam."]', '<u>Several Arabic schools existed in West Africa shortly after the advent of Islam</u>.', '{"bold":[],"italic":[],"underline":["several Arabic schools existed in West Africa shortly after the advent of Islam"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csri3ulgj24pqvhr53q0y1pu1', 'English Language', 'JAMB', null, 2020, null, 'My mother had _____ the firewood before it began to rain.', null, '["splitting","split","splitted","splits"]', 1, 'Past participle of "split" is "split".', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'My mother had _____ the firewood before it began to rain.', '["splitting","split","splitted","splits"]', 'Past participle: <u>split</u>.', '{"bold":[],"italic":[],"underline":["split"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csrqrh17epq5ecskraqrap80j', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve 2^(2x) - 5·2^(x+1) + 24 = 0.', null, '["1, 2","2, log₂6","1, 3","0, 4"]', 1, 'Let y = 2^x: y² - 10y + 24 = 0 → y = 4 or 6 → x = 2 or log₂6.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Solve 2^(2x) - 5·2^(x+1) + 24 = 0.', '["1, 2","2, log₂6","1, 3","0, 4"]', 'Let y = 2^x: y² - 10y + 24 = 0 → y = 4 or 6 → x = 2 or log₂6.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csrtj92zyrhy222j8uc3zu94q', 'Islamic Religious Studies', 'JAMB', null, 2003, null, 'The man who established the Muslim city of Qairawan was', null, '["Uqbah b. Nafic","Ubaidah b. Sa''ad","Irshad b. Waqas","Musa b. Naufai"]', 0, 'Uqbah b. Nafic established Qairawan around 669–670 CE.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The man who established the Muslim city of Qairawan was', '["<u>Uqbah b. Nafic</u>","Ubaidah b. Sa''ad","Irshad b. Waqas","Musa b. Naufai"]', '<u>Uqbah b. Nafic</u> established Qairawan.', '{"bold":[],"italic":[],"underline":["Uqbah b. Nafic"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('css2y8yjtcl3nk1pul3ze9ahq', 'Biology', 'JAMB', null, 1994, null, 'Colonization of a bare rock surface is termed', null, '["evolution","speciation","primary succession","secondary succession"]', 2, 'Colonization of bare rock is primary succession.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Colonization of a bare rock surface is termed', '["evolution","speciation","<u>primary succession</u>","secondary succession"]', '<u>Colonization of bare rock is primary succession</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('css6egu68mzmlze6kfrr8t37m', 'Biology', 'JAMB', null, 1991, null, 'The division of a body into two equal halves along a longitudinal plane is called', null, '["bilateral symmetry","transverse section","radial symmetry","longitudinal section"]', 0, 'Bilateral symmetry divides a body into two equal halves.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The division of a body into two equal halves along a longitudinal plane is called', '["<u>bilateral symmetry</u>","transverse section","radial symmetry","longitudinal section"]', '<u>Bilateral symmetry</u> divides a body into two equal halves.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cssat1q632xskfnbgkdxu97a4', 'Chemistry', 'JAMB', null, 1988, null, 'An eruption polluted an environment with a gas suspected to be H2S, a poisonous gas. A rescue team should spray the environment with', null, '["water","moist SO2","acidified KMnO4 and water","water, acidified KMnO4 and oxygen"]', 2, 'Acidified KMnO4 oxidizes H2S to harmless sulphate.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An eruption polluted an environment with a gas suspected to be H2S, a poisonous gas. A rescue team should spray the environment with', '["water","moist SO2","acidified KMnO4 and water","water, acidified KMnO4 and oxygen"]', '<u>Acidified KMnO4</u> oxidizes H2S to harmless sulphate.', '{"bold":[],"italic":[],"underline":["acidified KMnO4 and water"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cssdzqg73g4y2yudngce0tc36', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'What command did Paul give the brethren at Thessalonica concerning those who live in idleness?', null, '["That they should keep away from them","That they should treat them as offenders","That they should be punished","That they should share with them in common."]', 0, 'They should keep away from them.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What command did Paul give the brethren at Thessalonica concerning those who live in idleness?', '["<u>That they should keep away from them</u>","That they should treat them as offenders","That they should be punished","That they should share with them in common."]', '<u>That they should keep away from them</u> (2 Thessalonians 3:6).', '{"bold":[],"italic":[],"underline":["That they should keep away from them"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cssg60s6lbcgtxgep8wdo7a3n', 'General Mathematics', 'JAMB', null, 2020, null, 'If sin A + sin B = √2 cos C and cos A + cos B = √2 sin C, find cos(A - B).', null, '["0","1/2","1","-1"]', 0, 'Squaring and adding: 2 + 2cos(A-B) = 2 → cos(A-B) = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If sin A + sin B = √2 cos C and cos A + cos B = √2 sin C, find cos(A - B).', '["0","1/2","1","-1"]', 'cos(A - B) = <u>0</u>.', '{"bold":[],"italic":[],"underline":["0"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cstfi8mdn9bjppufd93827jq9', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'From which chapter of the Qur''an is the verse which declares ''Certainly, we created man in the best make''?', null, '["87","95","97","99"]', 1, 'It is from chapter 95 (Surat at-Tin).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'From which chapter of the Qur''an is the verse which declares ''Certainly, we created man in the best make''?', '["87","<u>95</u>","97","99"]', '<u>95</u> (Surat at-Tin).', '{"bold":[],"italic":[],"underline":["95"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cstw4iir8dklhhobsqwh31oac', 'General Mathematics', 'WAEC', null, 2020, null, 'On R, a*b = a + b - 2. Find the inverse of 4.', null, '["0","-4","4","2"]', 0, 'e = 2; 4*x = 2 → 4+x-2 = 2 → x = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'On R, a*b = a + b - 2. Find the inverse of 4.', '["0","-4","4","2"]', 'Inverse = <u>0</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cstyeehgxzadsh98dnw3va3gy', 'Government', 'JAMB', null, 2020, null, 'The performance of ritual rites in the Yoruba empire is the responsibility of the', null, '["Ogboni","Oyo mesi","Aare-ona kakanfo","Oba"]', 0, 'The Ogboni performed ritual rites.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The performance of ritual rites in the Yoruba empire is the responsibility of the', '["<u>Ogboni</u>","Oyo mesi","Aare-ona kakanfo","Oba"]', '<u>Ogboni</u>.', '{"bold":[],"italic":[],"underline":["Ogboni"],"fillBlanks":[]}');
