insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csueqpufjs6ktv8joouncywcw', 'Biology', 'JAMB', null, 2001, null, 'Urea formation occurs in the', null, '["heart","liver","lung","kidney"]', 1, 'Urea is formed in the liver.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Urea formation occurs in the', '["heart","liver","lung","kidney"]', '<u>Liver</u> forms urea.', '{"bold":[],"italic":[],"underline":["liver"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csuq0vaunmce7exagpg67jvoo', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the range of m so that x² + (m - 3)x + m = 0 has real roots.', null, '["m ≤ 1 or m ≥ 9","m ≤ -1 or m ≥ 9","m ≤ 1 or m ≥ 8","m ≤ -2 or m ≥ 7"]', 0, 'Discriminant (m-3)² - 4m ≥ 0 → m² - 10m + 9 ≥ 0 → (m-1)(m-9) ≥ 0 → m ≤ 1 or m ≥ 9.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the range of m so that x² + (m - 3)x + m = 0 has real roots.', '["m ≤ 1 or m ≥ 9","m ≤ -1 or m ≥ 9","m ≤ 1 or m ≥ 8","m ≤ -2 or m ≥ 7"]', 'Range = <u>m ≤ 1 or m ≥ 9</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csuu2firaba31oqdq28g90qkn', 'Biology', 'JAMB', null, 1984, null, 'Pepsin is a digestive enzyme which breaks', null, '["cellulose into glucose molecules","carbohydrates into simple sugars","protein into peptones","fats into glycerol and fatty acids","sucrose into glucose and fructose"]', 2, 'Pepsin breaks proteins into peptones.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Pepsin is a digestive enzyme which breaks', '["cellulose into glucose molecules","carbohydrates into simple sugars","<u>protein into peptones</u>","fats into glycerol and fatty acids","sucrose into glucose and fructose"]', 'Pepsin breaks <u>proteins into peptones</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csv0w76vwkilf0tyc67d469jl', 'General Mathematics', 'WAEC', null, 2020, null, 'After spending 20%, then 25% of remainder, then 30% of new remainder, a man has ₦420 left. Original?', null, '["₦1000","₦1200","₦1500","₦1800"]', 3, '420 = 0.8 × 0.75 × 0.7 × x = 0.42x → x = 1000. Key says 1800.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'After spending 20%, then 25% of remainder, then 30% of new remainder, a man has ₦420 left. Original?', '["₦1000","₦1200","₦1500","₦1800"]', '420 = 0.42x → <u>x = 1000</u> (key says 1800).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csv9vpimdkkyrcdmwrc3cgdv2', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the derivative of xˣ at x = 1.', null, '["0","1","2","e"]', 1, 'y = xˣ; ln y = x ln x; y''/y = ln x + 1; y'' = xˣ(ln x + 1); at x=1: 1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the derivative of xˣ at x = 1.', '["0","1","2","e"]', 'Derivative = <u>1</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csvi2kka0z6tzout6n4pi1cst', 'Physics', 'JAMB', null, 2021, null, 'A gun of mass 15kg fires a bullet of mass 150g with a velocity of 1000m/s. Calculate the recoil velocity of the gun', null, '["10m/s","2m/s","25m/s","-10m/s"]', 3, 'Momentum conservation: 0.15×1000 = 15×V → V = -10 m/s (recoil).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A gun of mass 15kg fires a bullet of mass 150g with a velocity of 1000m/s. Calculate the recoil velocity of the gun', '["10m/s","2m/s","25m/s","<u>-10m/s</u>"]', '0.15×1000 = 15×V → <u>V = -10 m/s</u> (recoil).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csvrtxhzxirhqs530mkr89jj3', 'Chemistry', 'JAMB', null, 1999, null, 'What is the temperature of a given mass of a gas initially at 0°C and 9 atm, if the pressure is reduced to 3 atmosphere at constant volume?', null, '["91K","182K","273K","819K"]', 1, 'T2 = T1 × P2/P1 = 273 × 3/9 = 91K. Key says 182.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is the temperature of a given mass of a gas initially at 0°C and 9 atm, if the pressure is reduced to 3 atmosphere at constant volume?', '["91K","182K","273K","819K"]', 'T2 = <u>91K</u> (key says 182).', '{"bold":[],"italic":[],"underline":["182K"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csw0w35w95vt2zychiqtnxu0d', 'Government', 'JAMB', null, 2020, null, 'The central objective of privatization in Nigeria is to', null, '["reduce the retrenchment of workers","encourage prompt payment of salaries","improve standard of living","improve the efficiency of enterprises."]', 3, 'Privatization aims to improve efficiency.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The central objective of privatization in Nigeria is to', '["reduce the retrenchment of workers","encourage prompt payment of salaries","improve standard of living","<u>improve the efficiency of enterprises.</u>"]', '<u>Improve the efficiency of enterprises</u>.', '{"bold":[],"italic":[],"underline":["improve the efficiency of enterprises."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csw17uub47zyi0fds5awq8ovi', 'Biology', 'JAMB', null, 2000, null, 'The order in which organic evolution has progressed in plants is', null, '["thallophyta, schizophyta, bryophyta, pteridophyta and spermatophyta","schizophyta, thallophyta, bryophyta, pteridophyta and spermatophyta","pteridophyta, spermatophyta, thallophyta, schizophyta and bryophyta","bryophyta, pteridophyta, spermatophyta, thallophyta and schizophyta"]', 1, 'Evolutionary order: schizophyta → thallophyta → bryophyta → pteridophyta → spermatophyta.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The order in which organic evolution has progressed in plants is', '["thallophyta, schizophyta, bryophyta, pteridophyta and spermatophyta","schizophyta, thallophyta, bryophyta, pteridophyta and spermatophyta","pteridophyta, spermatophyta, thallophyta, schizophyta and bryophyta","bryophyta, pteridophyta, spermatophyta, thallophyta and schizophyta"]', '<u>Schizophyta → thallophyta → bryophyta → pteridophyta → spermatophyta</u>.', '{"bold":[],"italic":[],"underline":["schizophyta, thallophyta, bryophyta, pteridophyta and spermatophyta"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cswewnsi3pcfzu0u91tuwzpwe', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'What did the blind man by the roadside near Jericho do on receiving his sight?', null, '["He thanked Jesus for healing him","He gave praise to God for making him whole","He jumped for joy and went away","He followed Jesus, glorifying God."]', 3, 'He followed Jesus, glorifying God.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What did the blind man by the roadside near Jericho do on receiving his sight?', '["He thanked Jesus for healing him","He gave praise to God for making him whole","He jumped for joy and went away","<u>He followed Jesus, glorifying God.</u>"]', '<u>He followed Jesus, glorifying God</u> (Luke 18:43).', '{"bold":[],"italic":[],"underline":["He followed Jesus, glorifying God."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cswfkpvyfrn9vwxz71en14ie2', 'General Mathematics', 'JAMB', null, 2020, null, 'If log₁₀((6x - 5)/(x - 3)) = 1, find the value of x.', null, '["5","25/4","8","10"]', 1, '(6x-5)/(x-3) = 10 → 4x = 25 → x = 25/4.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'If log₁₀((6x - 5)/(x - 3)) = 1, find the value of x.', '["5","25/4","8","10"]', '(6x-5)/(x-3) = 10 → 4x = 25 → x = 25/4.', '{"bold":[],"italic":[],"underline":["7"],"fillBlanks":[]}');
