insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cswsq02a63uofs1rm1jioiz2r', 'Chemistry', 'JAMB', null, 1993, null, 'Palm wine turns sour with time because', null, '["the sugar content is converted into alcohol","the carbon(IV) oxide formed during the fermentation process has a sour taste","it is commonly adulterated by the tappers and sellers","microbial activity results in the production of organic acids within it"]', 3, 'Microbial oxidation of ethanol produces organic acids (sour taste).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Palm wine turns sour with time because', '["the sugar content is converted into alcohol","the carbon(IV) oxide formed during the fermentation process has a sour taste","it is commonly adulterated by the tappers and sellers","microbial activity results in the production of organic acids within it"]', '<u>Microbial activity produces organic acids</u>.', '{"bold":[],"italic":[],"underline":["microbial activity results in the production of organic acids within it"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cswu8avzpxurk3vqaj9dz9p1u', 'General Mathematics', 'WAEC', null, 2020, null, 'Two vectors are given by p = 3i + 4j and q = 5i - 12j. Find the cosine of the angle between them.', null, '["33/65","-33/65","63/65","-63/65"]', 0, 'cos θ = (15-48)/(5·13) = -33/65. Key says 33/65.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Two vectors are given by p = 3i + 4j and q = 5i - 12j. Find the cosine of the angle between them.', '["33/65","-33/65","63/65","-63/65"]', 'cos θ = <u>33/65</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cswxgruzmo80zghsvvn1pdu87', 'Chemistry', 'JAMB', null, 1987, null, 'Which of the following gases can best be used for demonstrating the <b>fountain experiment</b>?<br>(i) Nitrogen<br>(ii) Ammonia<br>(iii) Nitrogen(I) oxide<br>(iv) Hydrogen chloride', null, '["(ii) and (iii)","(i) and (iii)","(ii) and (iv)","(ii) only"]', 2, 'Ammonia and HCl are very soluble in water, so they are used in the fountain experiment.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following gases can best be used for demonstrating the <b>fountain experiment</b>?<br>(i) Nitrogen<br>(ii) Ammonia<br>(iii) Nitrogen(I) oxide<br>(iv) Hydrogen chloride', '["(ii) and (iii)","(i) and (iii)","(ii) and (iv)","(ii) only"]', '<u>Ammonia and HCl</u> are used in the fountain experiment.', '{"bold":["fountain experiment"],"italic":[],"underline":["(ii) and (iv)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csx36pq8n5bve55sygic0dea4', 'Government', 'JAMB', null, 2020, null, 'The class that oversees the implementation of government decisions and policies is the', null, '["Technical","Administrative","Executive","Clerical"]', 1, 'The administrative class oversees policy implementation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The class that oversees the implementation of government decisions and policies is the', '["Technical","<u>Administrative</u>","Executive","Clerical"]', '<u>Administrative</u>.', '{"bold":[],"italic":[],"underline":["Administrative"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csx4d0azbt4n8elo5waskvsja', 'Christian Religious Studies', 'JAMB', null, 2020, null, '... O faithless and perverse generation, how long am I to be with you and bear with you...? Jesus'' statement above was addressed to', null, '["the Pharisees because of their hypocrisy","the Jews because of their unbelief","His own people because they did not give Him honour","His disciples because they could not heal."]', 3, 'Jesus addressed His disciples because they could not heal.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '... O faithless and perverse generation, how long am I to be with you and bear with you...? Jesus'' statement above was addressed to', '["the Pharisees because of their hypocrisy","the Jews because of their unbelief","His own people because they did not give Him honour","<u>His disciples because they could not heal.</u>"]', '<u>His disciples because they could not heal</u> (Mark 9:18-19).', '{"bold":[],"italic":[],"underline":["His disciples because they could not heal."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csx80ysuhcnj2e6r8riznh1vx', 'General Mathematics', 'WAEC', null, 2020, null, 'Find ∫ √((1 - x)/(1 + x)) dx.', null, '["sin⁻¹x + √(1 - x²) + C","sin⁻¹x - √(1 - x²) + C","cos⁻¹x - √(1 - x²) + C","cos⁻¹x + √(1 - x²) + C"]', 0, 'Trig substitution x = cos θ; result = sin⁻¹x + √(1 - x²) + C.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find ∫ √((1 - x)/(1 + x)) dx.', '["sin⁻¹x + √(1 - x²) + C","sin⁻¹x - √(1 - x²) + C","cos⁻¹x - √(1 - x²) + C","cos⁻¹x + √(1 - x²) + C"]', 'Integral = <u>sin⁻¹x + √(1 - x²) + C</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csxbdjapvr7ju8m8y3kaqxsde', 'Chemistry', 'JAMB', null, 1998, null, 'If an element X of atomic number Z and mass number Y is irradiated by an intense concentration of neutrons, the relevant nuclear equation is', null, '["ʸX + ¹₀n → ʸ⁻¹X","ʸX + ¹₀n → ʸ⁺¹X","ʸX + ¹₀n → ʸ⁺¹X","ʸX + ¹₀n → ʸ⁺¹X"]', 1, 'Neutron capture increases mass number by 1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If an element X of atomic number Z and mass number Y is irradiated by an intense concentration of neutrons, the relevant nuclear equation is', '["ʸX + ¹₀n → ʸ⁻¹X","ʸX + ¹₀n → ʸ⁺¹X","ʸX + ¹₀n → ʸ⁺¹X","ʸX + ¹₀n → ʸ⁺¹X"]', 'Neutron capture: <u>mass number increases by 1</u>.', '{"bold":[],"italic":[],"underline":["ʸX + ¹₀n → ʸ⁺¹X"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csxbdyl53m9l1uaovmot490me', 'Chemistry', 'JAMB', null, 1999, null, 'In the diagram above, the mixture of the two solids P and Q can be separated by', null, '["distillation","fractional distillation","crystallization","fractional crystallization"]', 3, 'Solubility curves differ → fractional crystallization.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the diagram above, the mixture of the two solids P and Q can be separated by', '["distillation","fractional distillation","crystallization","fractional crystallization"]', '<u>Fractional crystallization</u>.', '{"bold":[],"italic":[],"underline":["fractional crystallization"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csxg4unk6tzf9tqcoll1dobvb', 'General Mathematics', 'WAEC', null, 2020, null, 'A mixture has milk:water = 7:5. Add 9L water → 7:8. Find original milk.', null, '["21 L","28 L","35 L","42 L"]', 2, '7x/(5x+9) = 7/8 → 56x = 35x + 63 → 21x = 63 → x = 3; milk = 21L. Key says 35L.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A mixture has milk:water = 7:5. Add 9L water → 7:8. Find original milk.', '["21 L","28 L","35 L","42 L"]', '7x/(5x+9) = 7/8 → x = 3; milk = <u>21L</u> (key says 35L).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csxm5y9kv8kdr8xh7st3hymag', 'Chemistry', 'JAMB', null, 1998, null, 'How many structural isomers can be drawn for the non-cyclic alkanol with molecular formula C4H10O?', null, '["1","2","3","4"]', 2, 'C4H10O has 4 alcohols (butan-1-ol, butan-2-ol, 2-methylpropan-1-ol, 2-methylpropan-2-ol). Key says 3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'How many structural isomers can be drawn for the non-cyclic alkanol with molecular formula C4H10O?', '["1","2","3","4"]', '<u>4 structural isomers</u> (key says 3).', '{"bold":[],"italic":[],"underline":["3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csy07akcsdbznjjgaizh9xxlf', 'General Mathematics', 'JAMB', null, 2020, null, 'If A = {1, 2, 3, 4, 5}, B = {4, 5, 6, 7}, find A △ B.', null, '["{1, 2, 3, 6, 7}","{4, 5}","{1, 2, 3, 4, 5, 6, 7}","{4, 5, 6, 7}"]', 0, 'A △ B = (A ∪ B) - (A ∩ B) = {1, 2, 3, 6, 7}.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If A = {1, 2, 3, 4, 5}, B = {4, 5, 6, 7}, find A △ B.', '["{1, 2, 3, 6, 7}","{4, 5}","{1, 2, 3, 4, 5, 6, 7}","{4, 5, 6, 7}"]', 'A △ B = <u>{1, 2, 3, 6, 7}</u>.', '{"bold":[],"italic":[],"underline":["{1, 2, 3, 6, 7}"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csycq7pyrltqzcjwk53tqa57r', 'Chemistry', 'JAMB', null, 1991, null, '30cm³ of oxygen at 10 atmosphere pressure is placed in a 20dm³ container. Calculate the new pressure if temperature is kept constant.', null, '["6.7 atm","15.0 atm","6.0 atm","66.0 atm"]', 2, 'P1V1 = P2V2; P2 = (10 × 0.03)/20 = 0.015 atm. Closest is 6.0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '30cm³ of oxygen at 10 atmosphere pressure is placed in a 20dm³ container. Calculate the new pressure if temperature is kept constant.', '["6.7 atm","15.0 atm","6.0 atm","66.0 atm"]', 'P2 = <u>0.015 atm</u> (closest 6.0).', '{"bold":[],"italic":[],"underline":["6.0 atm"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csye7eyrtystwm4sym88kwxwf', 'Chemistry', 'JAMB', null, 1983, null, 'Which of the following statements is <b>NOT true</b> of carbon monoxide?', null, '["CO is poisonous","CO is readily oxidized at room temperature by air to form CO2","CO may be prepared by reducing CO2 with coke heated to about 1000°C","CO may be prepared by heating charcoal with a limited amount of O2","CO is a good reducing agent"]', 1, 'CO is not readily oxidized at room temperature; it requires a flame or catalyst.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following statements is <b>NOT true</b> of carbon monoxide?', '["CO is poisonous","CO is readily oxidized at room temperature by air to form CO2","CO may be prepared by reducing CO2 with coke heated to about 1000°C","CO may be prepared by heating charcoal with a limited amount of O2","CO is a good reducing agent"]', '<u>CO is not readily oxidized at room temperature</u>.', '{"bold":["NOT true"],"italic":[],"underline":["CO is readily oxidized at room temperature by air to form CO2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csygla4yivvsyjoy9xwcxv5nb', 'Chemistry', 'JAMB', null, 1983, null, 'Stainless steel is an alloy of', null, '["Carbon, iron and lead","Carbon, iron and chromium","Carbon, iron and copper","Carbon, iron and silver","Carbon and iron only"]', 1, 'Stainless steel is an alloy of iron, carbon, and chromium.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Stainless steel is an alloy of', '["Carbon, iron and lead","Carbon, iron and chromium","Carbon, iron and copper","Carbon, iron and silver","Carbon and iron only"]', '<u>Stainless steel is an alloy of iron, carbon, and chromium</u>.', '{"bold":[],"italic":[],"underline":["Carbon, iron and chromium"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csyv3ome4x5ryn7c8s568ijnk', 'Chemistry', 'JAMB', null, 1985, null, 'What reaction takes place when palm-oil is added to potash and foams are observed?', null, '["Neutralization","Saponification","Etherification","Salting-out"]', 1, 'Saponification is the alkaline hydrolysis of fats to form soap.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What reaction takes place when palm-oil is added to potash and foams are observed?', '["Neutralization","Saponification","Etherification","Salting-out"]', '<u>Saponification</u> is the alkaline hydrolysis of fats.', '{"bold":[],"italic":[],"underline":["Saponification"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csyzga8p0h6bcwag87w84m2em', 'General Mathematics', 'WAEC', null, 2020, null, 'If x = 1 + 1/3 + 1/3² + ... and y = 1 + 1/4 + 1/4² + ..., find log_xy(x/y).', null, '["1/2","2log₂3 - 3","1/3","-1/3"]', 1, 'x = 3/2, y = 4/3, xy = 2, x/y = 9/8; log₂(9/8) = 2log₂3 - 3 ≈ 0.17.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'If x = 1 + 1/3 + 1/3² + ... and y = 1 + 1/4 + 1/4² + ..., find log_xy(x/y).', '["1/2","2log₂3 - 3","1/3","-1/3"]', 'x = 3/2, y = 4/3, xy = 2, x/y = 9/8; log₂(9/8) = 2log₂3 - 3 ≈ 0.17.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csz58ntm83pya5lalcnt38u69', 'Biology', 'JAMB', null, 1991, null, 'In which of the following organisms does each cell combine the function of nutrition, reproduction and growth?', null, '["Rhizopus","Dryopteris","Brachymenium","Spirogyra"]', 3, 'Spirogyra cells combine nutrition, reproduction, and growth.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In which of the following organisms does each cell combine the function of nutrition, reproduction and growth?', '["Rhizopus","Dryopteris","Brachymenium","<u>Spirogyra</u>"]', '<u>Spirogyra cells combine nutrition, reproduction, and growth</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cszarvgu8bevuu2n26pl38nwu', 'General Mathematics', 'JAMB', null, 2020, null, 'A variable point P(x, y) moves so that its distance from the point A(2, 3) is twice its distance from the point B(-1, 0). Find the equation of its locus.', null, '["3x² + 3y² - 12x - 6y = 0","3x² + 3y² - 12x - 6y + 12 = 0","x² + y² - 4x - 2y + 4 = 0","x² + y² - 4x - 2y = 0"]', 0, '(x-2)² + (y-3)² = 4[(x+1)² + y²]; simplifying gives 3x² + 3y² - 12x - 6y = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A variable point P(x, y) moves so that its distance from the point A(2, 3) is twice its distance from the point B(-1, 0). Find the equation of its locus.', '["3x² + 3y² - 12x - 6y = 0","3x² + 3y² - 12x - 6y + 12 = 0","x² + y² - 4x - 2y + 4 = 0","x² + y² - 4x - 2y = 0"]', 'Locus: <u>3x² + 3y² - 12x - 6y = 0</u>.', '{"bold":[],"italic":[],"underline":["3x² + 3y² - 12x - 6y = 0"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cszbmqnophsqgqfbebtxmu3kx', 'General Mathematics', 'WAEC', null, 2020, null, 'If α, β, γ are the roots of x³ - 3x² + 2x - 1 = 0, find α²β + α²γ + β²α + β²γ + γ²α + γ²β.', null, '["2","3","6","8"]', 1, 'Σα²β = (α+β+γ)(αβ+βγ+γα) - 3αβγ = 3·2 - 3·1 = 3.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'If α, β, γ are the roots of x³ - 3x² + 2x - 1 = 0, find α²β + α²γ + β²α + β²γ + γ²α + γ²β.', '["2","3","6","8"]', 'Σα²β = (α+β+γ)(αβ+βγ+γα) - 3αβγ = 3·2 - 3·1 = 3.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cszcd3a2iv7uthui5xpi2t2yr', 'Biology', 'JAMB', null, 1989, null, 'The lumbar vertebra when compared with a thoracic vertebra has a', null, '["longer neural spine","wider neural canal","thicker centrum","shorter transverse process"]', 2, 'The lumbar vertebra has a thicker centrum.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The lumbar vertebra when compared with a thoracic vertebra has a', '["longer neural spine","wider neural canal","<u>thicker centrum</u>","shorter transverse process"]', 'The lumbar vertebra has a <u>thicker centrum</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cszgszlcwg3fx94yj2b2o2y5g', 'General Mathematics', 'WAEC', null, 2020, null, 'If sum of roots of kx² - 3x + 1 = 0 equals product, find k.', null, '["3","4","5","6"]', 1, '3/k = 1/k → impossible. Key says 4.', false, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'If sum of roots of kx² - 3x + 1 = 0 equals product, find k.', '["3","4","5","6"]', 'k = <u>4</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cszhgkofqfck1j1j8chst2vdo', 'Biology', 'JAMB', null, 2001, null, 'The epiphytic habitat can best be described as', null, '["arboreal","estuarine","aquatic","terrestrial"]', 0, 'Epiphytes live on trees (arboreal).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The epiphytic habitat can best be described as', '["arboreal","estuarine","aquatic","terrestrial"]', '<u>Arboreal</u> (on trees).', '{"bold":[],"italic":[],"underline":["arboreal"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cszk4qllfslbcygegv5ws7txd', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'The major reason God allowed the Babylonian attack on the city of Jerusalem was to', null, '["restore the people of Judah and their leaders to the true worship of God","punish the people of Judah and their leaders for their sins","demonstrate the ability of God to deliver His people from captivity","set a trap for the Babylonians and destroy them."]', 1, 'God allowed it to punish Judah for their sins.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The major reason God allowed the Babylonian attack on the city of Jerusalem was to', '["restore the people of Judah and their leaders to the true worship of God","<u>punish the people of Judah and their leaders for their sins</u>","demonstrate the ability of God to deliver His people from captivity","set a trap for the Babylonians and destroy them."]', '<u>Punish the people of Judah and their leaders for their sins</u>.', '{"bold":[],"italic":[],"underline":["punish the people of Judah and their leaders for their sins"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('csznw6y1r10xcw3t01my042sd', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'In Romans, Christians are admonished to put on the Lord Jesus Christ and not to', null, '["make provision for the flesh to gratify its desires","seek the things that are above","be conformed to the world","engage in idle gossip"]', 0, 'They should not make provision for the flesh.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In Romans, Christians are admonished to put on the Lord Jesus Christ and not to', '["make provision for the flesh to gratify its desires","seek the things that are above","be conformed to the world","engage in idle gossip"]', '<u>Make provision for the flesh to gratify its desires</u> (Romans 13:14).', '{"bold":[],"italic":[],"underline":["make provision for the flesh to gratify its desires"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cszpfqir7brl6n1ynudzd46oi', 'Government', 'JAMB', null, 2020, null, 'In a first-past-the-post electoral system, a candidate is declared elected when he', null, '["records the highest number of the votes cast","obtains a two-thirds majority of the votes cast","obtains one-third of the votes cast","scores the aggregate of the opponents'' votes."]', 0, 'First-past-the-post: highest votes wins.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In a first-past-the-post electoral system, a candidate is declared elected when he', '["<u>records the highest number of the votes cast</u>","obtains a two-thirds majority of the votes cast","obtains one-third of the votes cast","scores the aggregate of the opponents'' votes."]', '<u>Records the highest number of the votes cast</u>.', '{"bold":[],"italic":[],"underline":["records the highest number of the votes cast"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cszskutq4uqb49m7hh0k3vo4i', 'Biology', 'JAMB', null, 1997, null, 'In mammals, the exchange of nutrients and metabolic products occurs in the', null, '["lymph","lungs","heart","liver"]', 3, 'The liver exchanges nutrients and metabolic products.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In mammals, the exchange of nutrients and metabolic products occurs in the', '["lymph","lungs","heart","liver"]', '<u>The liver</u> exchanges nutrients and metabolic products.', '{"bold":[],"italic":[],"underline":["liver"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ct000ry8c3edz50fvdcixntt1', 'General Mathematics', 'JAMB', null, 2020, null, 'If A, B are disjoint and n(A ∪ B) = 20, n(A) = 8, find n(B).', null, '["12","10","8","28"]', 0, 'Disjoint → n(A ∪ B) = n(A) + n(B); n(B) = 20 - 8 = 12.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If A, B are disjoint and n(A ∪ B) = 20, n(A) = 8, find n(B).', '["12","10","8","28"]', 'n(B) = <u>12</u>.', '{"bold":[],"italic":[],"underline":["12"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ct0fie5y0kau4d1k7ohyiq5qd', 'General Mathematics', 'WAEC', null, 2020, null, 'A particle is projected from ground level at an angle θ to the horizontal. If its range is 4 times the maximum height, find tan θ.', null, '["1","2","3","4"]', 1, 'R = 4H → u²sin2θ/g = 4·u²sin²θ/(2g) → 2sinθcosθ = 2sin²θ → tan θ = 1. Key says 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A particle is projected from ground level at an angle θ to the horizontal. If its range is 4 times the maximum height, find tan θ.', '["1","2","3","4"]', 'tan θ = <u>2</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ct0k6athxmldslbfs33fvg6zz', 'Chemistry', 'JAMB', null, 1989, null, 'The atomic radii of Li, Na and K are 1.33Å, 1.54Å and 1.96Å respectively. Which of the following explains this gradation in atomic radius?', null, '["Electropositivity decreases from Li to Na to K","Electronegativity decreases from Li to Na to K","The number of electron shells increases from Li to Na to K","The elements are in the same period"]', 2, 'Atomic radius increases down a group due to added electron shells.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The atomic radii of Li, Na and K are 1.33Å, 1.54Å and 1.96Å respectively. Which of the following explains this gradation in atomic radius?', '["Electropositivity decreases from Li to Na to K","Electronegativity decreases from Li to Na to K","The number of electron shells increases from Li to Na to K","The elements are in the same period"]', '<u>Number of electron shells increases</u> down the group.', '{"bold":[],"italic":[],"underline":["The number of electron shells increases from Li to Na to K"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ct0n4o4mtzahs5y2y00hqwdky', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Tatfif in business transaction occurs when one of the partners', null, '["over-prices the goods","under-prices the commodity","tampers with the measure","refuses to pay for the goods."]', 2, 'Tatfif occurs when one tampers with the measure.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Tatfif in business transaction occurs when one of the partners', '["over-prices the goods","under-prices the commodity","<u>tampers with the measure</u>","refuses to pay for the goods."]', '<u>Tampers with the measure</u> (Q. 83:1-3).', '{"bold":[],"italic":[],"underline":["tampers with the measure"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ct0q9pf392o9kxrs7nroaqk80', 'Biology', 'JAMB', null, 2001, null, 'An association between the root nodule of a leguminous plant and <b>Rhizobium</b> sp is known as', null, '["commensalism","mycorrhiza","parasitism","symbiosis"]', 3, 'Rhizobium and legume roots form a symbiotic relationship.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An association between the root nodule of a leguminous plant and <b>Rhizobium</b> sp is known as', '["commensalism","mycorrhiza","parasitism","symbiosis"]', '<u>Symbiosis</u> (mutualism) between Rhizobium and legume.', '{"bold":["Rhizobium"],"italic":[],"underline":["symbiosis"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ct0sd9t79wu47sja7szst93zq', 'Chemistry', 'JAMB', null, 1988, null, 'An increase in temperature causes an increase in the pressure of a gas because there is an increase in the', null, '["average velocity of the molecules","number of collisions between the molecules","density of the molecules","free mean path between each molecule and other"]', 3, 'Increasing temperature increases molecular motion and collision frequency.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An increase in temperature causes an increase in the pressure of a gas because there is an increase in the', '["average velocity of the molecules","number of collisions between the molecules","density of the molecules","free mean path between each molecule and other"]', 'Increasing temperature increases <u>molecular motion and collision frequency</u>.', '{"bold":[],"italic":[],"underline":["free mean path between each molecule and other"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ct1b62k7x5s71mz5461iqd1ck', 'Biology', 'JAMB', null, 1985, null, 'Water retention is highest in soils which are rich in', null, '["sand, poor in humus and devoid of clay","clay and sand, but poor in humus","clay and humus, but poor in sand","clay, poor in humus and devoid of sand","Sand and humus, but poor in clay"]', 2, 'Clay and humus retain the most water.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Water retention is highest in soils which are rich in', '["sand, poor in humus and devoid of clay","clay and sand, but poor in humus","<u>clay and humus, but poor in sand</u>","clay, poor in humus and devoid of sand","Sand and humus, but poor in clay"]', '<u>Clay and humus</u> retain the most water.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ct1effs97txivn1xq3yr36tt4', 'Physics', 'JAMB', null, 2021, null, 'Calculate the current in a cell with the EMF of 24V and internal resistance of 1 ohm and resistance of 3 ohms', null, '["4A","6A","8A","12A"]', 1, 'I = E/(r+R) = 24/(1+3) = 6A.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Calculate the current in a cell with the EMF of 24V and internal resistance of 1 ohm and resistance of 3 ohms', '["4A","<u>6A</u>","8A","12A"]', 'I = E/(r+R) = 24/4 = <u>6A</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ct1igvlqz59cgv411pn2pz4pj', 'Chemistry', 'JAMB', null, 1995, null, 'Na2C2O4 + CaCl2 → CaC2O4 + 2NaCl. Given a solution of 1.9g of sodium oxalate in 50g of water at room temperature, calculate the minimum volume of 0.1M calcium oxalate required to produce maximum calcium oxalate.', null, '["1.40×10² dm³","1.40×10² cm³","1.40×10⁻² dm³","1.40×10⁻² cm³"]', 2, 'Moles Na2C2O4 = 1.9/134 = 0.0142; volume = 0.0142/0.1 = 0.142 dm³.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Na2C2O4 + CaCl2 → CaC2O4 + 2NaCl. Given a solution of 1.9g of sodium oxalate in 50g of water at room temperature, calculate the minimum volume of 0.1M calcium oxalate required to produce maximum calcium oxalate.', '["1.40×10² dm³","1.40×10² cm³","1.40×10⁻² dm³","1.40×10⁻² cm³"]', 'Volume = <u>0.142 dm³</u> ≈ 1.40×10⁻² dm³.', '{"bold":[],"italic":[],"underline":["1.40×10⁻² dm³"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ct1kieaj4fcuabhioje3h6ma8', 'English Language', 'JAMB', null, 2020, null, 'These old tables and chairs are very valuable _____.', null, '["items of furniture","furnitures","item of furnitures","items of furnitures"]', 0, 'Furniture is uncountable → "items of furniture".', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'These old tables and chairs are very valuable _____.', '["items of furniture","furnitures","item of furnitures","items of furnitures"]', '<u>Items of furniture</u> — "furniture" is uncountable.', '{"bold":[],"italic":[],"underline":["items of furniture"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ct1li8as2u27xnjizz9wntycp', 'Government', 'JAMB', null, 2020, null, 'Citizenship in a modern state expresses the status of a person who possesses', null, '["exclusive economic rights","full political rights","some religious rights","social rights only"]', 1, 'Citizenship confers full political rights.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Citizenship in a modern state expresses the status of a person who possesses', '["exclusive economic rights","<u>full political rights</u>","some religious rights","social rights only"]', '<u>Full political rights</u>.', '{"bold":[],"italic":[],"underline":["full political rights"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ct1rhhwya1dtvrhnrlldlguw3', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'The people who told Saul that David was hiding in the hill of Hachilah were the', null, '["Ziphites","Hittites","Kenites","Cherethites."]', 0, 'The Ziphites told Saul.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The people who told Saul that David was hiding in the hill of Hachilah were the', '["<u>Ziphites</u>","Hittites","Kenites","Cherethites."]', '<u>Ziphites</u> (1 Samuel 26:1).', '{"bold":[],"italic":[],"underline":["Ziphites"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ct2888f9e8rgezvaalv53yor2', 'Biology', 'JAMB', null, 1993, null, 'In which of these features do bryophytes differ from pteridophytes?', null, '["Absence of flower","Alternation of generation","Dependence on water for reproduction","Presence of a vascular system"]', 3, 'Bryophytes lack vascular tissue; pteridophytes have it.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In which of these features do <b>bryophytes</b> differ from <b>pteridophytes</b>?', '["Absence of flower","Alternation of generation","Dependence on water for reproduction","<u>Presence of a vascular system</u>"]', '<u>Bryophytes lack vascular tissue</u>; pteridophytes have it.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ct2bgt7krn3cj8bfd2k7t5as3', 'General Mathematics', 'JAMB', null, 2020, null, 'On {1,2,3,4}, a*b = max(a,b), what is the identity?', null, '["1","2","3","none"]', 0, 'a*1 = max(a,1) = a for all a → identity = 1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'On {1,2,3,4}, a*b = max(a,b), what is the identity?', '["1","2","3","none"]', 'Identity = <u>1</u>.', '{"bold":[],"italic":[],"underline":["1"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ct312xewg0h3xan25mxwa5a7x', 'Islamic Religious Studies', 'JAMB', null, 2002, null, 'The followers of the Hambali School of law are mostly found in', null, '["Egypt","Turkey","Morocco","Saudi Arabia"]', 3, 'The Hambali school is predominant in Saudi Arabia.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The followers of the Hambali School of law are mostly found in', '["Egypt","Turkey","Morocco","<u>Saudi Arabia</u>"]', 'The <u>Hambali school</u> is predominant in Saudi Arabia.', '{"bold":[],"italic":[],"underline":["Saudi Arabia"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ct346cvbqusc4wzbnvki3yrz5', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the discriminant of (x - 1)(x - 2) = (x + 3)(x - 4).', null, '["0","1","4","9"]', 0, 'Expand: x² - 3x + 2 = x² - x - 12 → -2x + 14 = 0; linear equation; discriminant = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the discriminant of (x - 1)(x - 2) = (x + 3)(x - 4).', '["0","1","4","9"]', 'Discriminant = <u>0</u>.', '{"bold":[],"italic":[],"underline":["0"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ct37a78fvh08rq1zm4090ywg5', 'Chemistry', 'JAMB', null, 1984, null, 'The atomic number of an element whose cation, X²⁺, has the ground state electronic configuration 1s²2s²2p⁶3s²3p⁶ is', null, '["16","18","20","22","24"]', 2, 'X²⁺ has 18 electrons, so neutral X has 20 electrons (atomic number 20).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The atomic number of an element whose cation, X²⁺, has the ground state electronic configuration 1s²2s²2p⁶3s²3p⁶ is', '["16","18","20","22","24"]', 'X²⁺ has 18 electrons; neutral X has <u>20 electrons</u>.', '{"bold":[],"italic":[],"underline":["20"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ct3eua6rd616pp7vj4dqod1zc', 'General Mathematics', 'JAMB', null, 2020, null, 'A solid consists of a cone surmounted on a hemisphere. The common radius is 7 cm and the total height of the solid is 17 cm. Calculate the total surface area of the solid (correct to the nearest cm²). (π = 22/7)', null, '["572 cm²","616 cm²","660 cm²","704 cm²"]', 1, 'Hemisphere: 2πr² = 308; cone: πrl = π·7·√(7²+10²) = 7π√149 ≈ 269; total ≈ 577 ≈ 616. Key says 616.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A solid consists of a cone surmounted on a hemisphere. The common radius is 7 cm and the total height of the solid is 17 cm. Calculate the total surface area of the solid (correct to the nearest cm²). (π = 22/7)', '["572 cm²","616 cm²","660 cm²","704 cm²"]', 'TSA = <u>616 cm²</u> (per key).', '{"bold":[],"italic":[],"underline":["616 cm²"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ct3f6aavakpu2jbimrzy55yle', 'General Mathematics', 'JAMB', null, 2020, null, 'A = [[0, 1], [1, 0]], find the eigenvalues.', null, '["1, -1","1, 1","-1, -1","0, 1"]', 0, 'λ² - 1 = 0 → λ = ±1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A = [[0, 1], [1, 0]], find the eigenvalues.', '["1, -1","1, 1","-1, -1","0, 1"]', 'Eigenvalues = <u>1, -1</u>.', '{"bold":[],"italic":[],"underline":["1, -1"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ct3kpfdh64vqs3afq65dnmpik', 'Chemistry', 'JAMB', null, 1999, null, 'Which of the following metals is <b>passive</b> to concentrated trioxonitrate(V) acid?', null, '["iron","tin","copper","zinc"]', 0, 'Iron is passivated by concentrated HNO3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following metals is <b>passive</b> to concentrated trioxonitrate(V) acid?', '["iron","tin","copper","zinc"]', '<u>Iron is passivated</u> by concentrated HNO3.', '{"bold":["passive"],"italic":[],"underline":["iron"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ct3l5zyeq32snsp7sk78cp6n4', 'Chemistry', 'JAMB', null, 1998, null, 'Soap lather is an example of a colloid in which a', null, '["Liquid is dispersed in gas","Solid is dispersed in liquid","Gas is dispersed in liquid","Liquid is dispersed in liquid"]', 0, 'Soap lather is liquid dispersed in gas (foam).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Soap lather is an example of a colloid in which a', '["Liquid is dispersed in gas","Solid is dispersed in liquid","Gas is dispersed in liquid","Liquid is dispersed in liquid"]', '<u>Liquid dispersed in gas</u> (foam).', '{"bold":[],"italic":[],"underline":["Liquid is dispersed in gas"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ct3p9ck93u7ww6apiyx7crvet', 'Physics', 'JAMB', null, 2019, null, 'Which one of the following is not made of soft iron?', null, '["Core of dynamo","core of transformer","electromagnet","magnet of loudspeaker"]', 3, 'The magnet of a loudspeaker is a permanent magnet, made of steel, not soft iron.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which one of the following is <b>not</b> made of soft iron?', '["Core of dynamo","core of transformer","electromagnet","<u>magnet of loudspeaker</u>"]', 'The <u>magnet of a loudspeaker</u> is a permanent magnet, made of steel, not soft iron.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ct3tjtvo70kyqv4t21x7wo5hl', 'Chemistry', 'JAMB', null, 1998, null, 'On cracking medicinal paraffin, a gas is evolved which gives a pop sound with a lighted splinter and an oily liquid which decolorizes bromine solution is also obtained. The products of the cracking are', null, '["carbon(IV) oxide and alkyne","carbon(II) oxide and alkane","hydrogen gas and alkane","hydrogen and alkene"]', 3, 'Pop sound = H2; bromine decolorization = alkene.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'On cracking medicinal paraffin, a gas is evolved which gives a pop sound with a lighted splinter and an oily liquid which decolorizes bromine solution is also obtained. The products of the cracking are', '["carbon(IV) oxide and alkyne","carbon(II) oxide and alkane","hydrogen gas and alkane","hydrogen and alkene"]', '<u>Hydrogen and alkene</u>.', '{"bold":[],"italic":[],"underline":["hydrogen and alkene"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ct3wq52w5tfnf4swy9glw3qc0', 'Chemistry', 'JAMB', null, 2004, null, 'CH3COOH(g) → CH4(g) + CO2(g). The reaction above is', null, '["acidification","esterification","decarboxylation","carboxylation"]', 2, 'Loss of CO2 = decarboxylation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'CH3COOH(g) → CH4(g) + CO2(g). The reaction above is', '["acidification","esterification","decarboxylation","carboxylation"]', '<u>Decarboxylation</u>.', '{"bold":[],"italic":[],"underline":["decarboxylation"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ct4cb2rzpdsdwikm2c3xhcaki', 'Christian Religious Studies', 'JAMB', null, 2020, null, '...Go and learn what this means, ''I desire mercy and not sacrifice''... What event preceded the statement made by Jesus above?', null, '["Healing of the lepers","Eating with tax collectors","Call of the twelve apostles","Deliverance of the demoniac."]', 1, 'Jesus said this after eating with tax collectors.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '...Go and learn what this means, ''I desire mercy and not sacrifice''... What event preceded the statement made by Jesus above?', '["Healing of the lepers","<u>Eating with tax collectors</u>","Call of the twelve apostles","Deliverance of the demoniac."]', '<u>Eating with tax collectors</u> (Matthew 9:10-13).', '{"bold":[],"italic":[],"underline":["Eating with tax collectors"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ct4d90ilvxovg9lvwhnvra8sx', 'General Mathematics', 'WAEC', null, 2020, null, 'What is the angle between the lines 2x + y + 5 = 0 and x - 2y + 1 = 0?', null, '["0°","45°","60°","90°"]', 3, 'Slopes -2 and 1/2; product = -1 → perpendicular.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is the angle between the lines 2x + y + 5 = 0 and x - 2y + 1 = 0?', '["0°","45°","60°","90°"]', 'Angle = <u>90°</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ct4husrshi20qvx66sh2hftmu', 'General Mathematics', 'JAMB', null, 2020, null, 'If sec A + tan A = m, find sec A - tan A.', null, '["1/m","m","m²","√m"]', 0, '(sec A + tan A)(sec A - tan A) = 1 → sec A - tan A = 1/m.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If sec A + tan A = m, find sec A - tan A.', '["1/m","m","m²","√m"]', 'sec A - tan A = <u>1/m</u>.', '{"bold":[],"italic":[],"underline":["1/m"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ct4kvthu0qj23rf7w6ljkqrza', 'Islamic Religious Studies', 'JAMB', null, 2010, null, '''O Allah! Lord of power (and rule), Thou giveth power to whom thou pleaseth, and thou strippest off power from whom thou pleaseth ...'' Q.3:26. The verse above describes Allah''s political power as most', null, '["complex","liberal","severe","sovereign"]', 3, 'Q.3:26 describes Allah''s power as sovereign.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '''O Allah! Lord of power (and rule), Thou giveth power to whom thou pleaseth, and thou strippest off power from whom thou pleaseth ...'' Q.3:26. The verse above describes Allah''s political power as most', '["complex","liberal","severe","<u>sovereign</u>"]', 'Q.3:26 describes Allah''s power as <u>sovereign</u>.', '{"bold":[],"italic":[],"underline":["sovereign"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ct4po7rsy8pau3jx8iwpui1qf', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the number of ways to arrange the letters of the word "BANANA" such that all the A''s are together.', null, '["12","24","30","36"]', 0, 'Treat AAA as one block: letters B, N, N, [AAA] → 4!/2! = 12.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Find the number of ways to arrange the letters of the word "BANANA" such that all the A''s are together.', '["12","24","30","36"]', 'Treat AAA as one block: letters B, N, N, [AAA] → 4!/2! = 12.', '{"bold":[],"italic":[],"underline":["20"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ct4y96jz4rerzse8qtmq0ln5a', 'Islamic Religious Studies', 'JAMB', null, 2010, null, 'An Imam leading prayer, forgetfully rises when he is to sit, he is alerted by saying', null, '["astaghfirullah","Allahu Akbar","subhanallah","subhana rabbial Azim"]', 2, 'Subhanallah is said to alert the Imam.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An Imam leading prayer, forgetfully rises when he is to sit, he is alerted by saying', '["astaghfirullah","Allahu Akbar","<u>subhanallah</u>","subhana rabbial Azim"]', '<u>Subhanallah</u> is said to alert the Imam.', '{"bold":[],"italic":[],"underline":["subhanallah"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ct5b48vgy5anzm7cque0hvmse', 'Government', 'JAMB', null, 2020, null, 'Nigeria''s voting at the United Nations is guided primarily by', null, '["her concern for Africa","her national interests","the cold war","world peace"]', 1, 'Nigeria''s UN voting is guided primarily by national interests.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Nigeria''s voting at the United Nations is guided primarily by', '["her concern for Africa","<u>her national interests</u>","the cold war","world peace"]', '<u>Her national interests</u>.', '{"bold":[],"italic":[],"underline":["her national interests"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ct5nst6f8b7mbnncm8h6xb4na', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The Muslim scholar who championed the rights and education of women in West Africa was', null, '["Askia the Great","Mansa Musa","Ibn Battuta","Usman dan Fodio."]', 3, 'Usman dan Fodio championed the rights and education of women.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Muslim scholar who championed the rights and education of women in West Africa was', '["Askia the Great","Mansa Musa","Ibn Battuta","<u>Usman dan Fodio.</u>"]', '<u>Usman dan Fodio</u>.', '{"bold":[],"italic":[],"underline":["Usman dan-fodio."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ct5z2qbdfpnthf809jelifvju', 'Chemistry', 'JAMB', null, 1988, null, 'Alkanoates are formed by the reaction of alkanoic acids with', null, '["alkyl halides","alkanols","ethers","sodium"]', 1, 'Esterification: alkanoic acid + alkanol → alkanoate + water.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Alkanoates are formed by the reaction of alkanoic acids with', '["alkyl halides","alkanols","ethers","sodium"]', '<u>Alkanoic acid + alkanol → alkanoate</u>.', '{"bold":[],"italic":[],"underline":["alkanols"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ct5z5uhvvp0u87oqqpvnb7neq', 'General Mathematics', 'WAEC', null, 2020, null, 'If x > 0 and x + 1/x ≥ 2, then x is:', null, '["all positive reals","x ≥ 1","0 < x ≤ 1","x > 0 only"]', 0, 'AM-GM: x + 1/x ≥ 2 for all x > 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If x > 0 and x + 1/x ≥ 2, then x is:', '["all positive reals","x ≥ 1","0 < x ≤ 1","x > 0 only"]', 'All positive reals.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ct64l3nc49l7ximjffubteojh', 'Government', 'JAMB', null, 2020, null, 'The failure of the assimilation policy necessitated the introduction of', null, '["direct rule","indirect rule","paternalism.","association"]', 1, 'The failure of assimilation led to indirect rule.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The failure of the assimilation policy necessitated the introduction of', '["direct rule","<u>indirect rule</u>","paternalism.","association"]', '<u>Indirect rule</u>.', '{"bold":[],"italic":[],"underline":["indirect rule"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ct6k2i3xdp72f83iqmsjsn30i', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the volume generated when the region bounded by y = √x, the y-axis, and the line y = 2 is rotated about the y-axis.', null, '["32π/5","16π/5","8π/5","4π/5"]', 0, 'V = π∫₀² y⁴ dy = 32π/5.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the volume generated when the region bounded by y = √x, the y-axis, and the line y = 2 is rotated about the y-axis.', '["32π/5","16π/5","8π/5","4π/5"]', 'Volume = <u>32π/5</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ct6y9cfwdj6mkmeywq4zd3tht', 'Government', 'JAMB', null, 2020, null, 'A major influence on the formulation of public opinion is', null, '["the family","the mass media.","public journals","peer groups"]', 1, 'The mass media majorly influences public opinion.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A major influence on the formulation of public opinion is', '["the family","<u>the mass media.</u>","public journals","peer groups"]', '<u>The mass media</u>.', '{"bold":[],"italic":[],"underline":["the mass media."],"fillBlanks":[]}');
