insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ct7fxvft9hn46ayecw7kirhbe', 'Biology', 'JAMB', null, 1997, null, 'The element that is essential for the <b>coagulation of blood</b> is', null, '["potassium","calcium","phosphorus","iron"]', 1, 'Calcium is essential for blood clotting.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The element that is essential for the <b>coagulation of blood</b> is', '["potassium","calcium","phosphorus","iron"]', '<u>Calcium is essential for blood clotting</u>.', '{"bold":["coagulation of blood"],"italic":[],"underline":["calcium"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ct7iy41avpglrb7hv3kn2au2x', 'Christian Religious Studies', 'JAMB', null, 2020, null, '..Why has Satan filled your heart to lie to the Holy Spirit... Peter rebuked Ananias in the statement above for his sin of', null, '["greed","insincerity","covetousness","partiality"]', 1, 'Peter rebuked Ananias for insincerity.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '..Why has Satan filled your heart to lie to the Holy Spirit... Peter rebuked Ananias in the statement above for his sin of', '["greed","<u>insincerity</u>","covetousness","partiality"]', '<u>Insincerity</u> (Acts 5:1-11).', '{"bold":[],"italic":[],"underline":["insincerity"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ct7pe7aavclboybtxgn4gqblz', 'General Mathematics', 'WAEC', null, 2020, null, 'The sum of the first n terms of a sequence is Sₙ = 3n² - 2n. Find the sum of the first 10 terms of the sequence formed by the reciprocals of the terms of the original sequence.', null, '["10/91","10/21","10/31","10/41"]', 1, 'Tₙ = 6n - 5; reciprocals form telescoping series → 10/21.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The sum of the first n terms of a sequence is Sₙ = 3n² - 2n. Find the sum of the first 10 terms of the sequence formed by the reciprocals of the terms of the original sequence.', '["10/91","10/21","10/31","10/41"]', 'Sum = <u>10/21</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ct81yhzk6436xmeoixpas7qwg', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve 3 ≤ |x - 2| ≤ 5.', null, '["[-3, -1] ∪ [5, 7]","[-3, 7]","[-1, 5]","[-3, -1] ∪ [5, 7]"]', 0, '3 ≤ x-2 ≤ 5 → 5 ≤ x ≤ 7; -5 ≤ x-2 ≤ -3 → -3 ≤ x ≤ -1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve 3 ≤ |x - 2| ≤ 5.', '["[-3, -1] ∪ [5, 7]","[-3, 7]","[-1, 5]","[-3, -1] ∪ [5, 7]"]', 'Solution: <u>[-3, -1] ∪ [5, 7]</u>.', '{"bold":[],"italic":[],"underline":["[-3, -1] ∪ [5, 7]"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ct83lpkzslt1srl6fe1h1jy2h', 'Biology', 'JAMB', null, 2003, null, 'Organisms I, II, III and IV have surface/volume ratios of 1:2, 1:3, 1:4 and 1:5 respectively. The organism that is likely to have the most complex transport system is', null, '["III","IV","II","I"]', 1, 'Lowest S/V ratio (1:5) requires most complex transport.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Organisms I, II, III and IV have surface/volume ratios of 1:2, 1:3, 1:4 and 1:5 respectively. The organism that is likely to have the most complex transport system is', '["III","IV","II","I"]', '<u>IV (1:5)</u> needs the most complex transport.', '{"bold":[],"italic":[],"underline":["IV"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ct8cdwod1mc10pyhdl6mpfkmd', 'Government', 'JAMB', null, 2020, null, 'Associational interest groups are organized to', null, '["further the interests of members","specifically lobby the government","support the government","achieve goals affecting other associations."]', 0, 'Associational interest groups exist to further their members'' interests.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Associational interest groups are organized to', '["<u>further the interests of members</u>","specifically lobby the government","support the government","achieve goals affecting other associations."]', 'They <u>further the interests of members</u>.', '{"bold":[],"italic":[],"underline":["further the interests of members"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ct8hirmocgqkgdbrsqmqsxnel', 'Biology', 'JAMB', null, 1984, null, 'A man with a normal haemoglobin (AA) marries a woman who has sickle-cell haemoglobin (SS). They have a child who has sickle-cell trait. Which of the following genotypes could be associated with the child''s haemoglobin?', null, '["AA","OO","AO","AS","SS"]', 3, 'The child inherits A from father and S from mother, giving AS.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A man with a normal haemoglobin (AA) marries a woman who has sickle-cell haemoglobin (SS). They have a child who has sickle-cell trait. Which of the following genotypes could be associated with the child''s haemoglobin?', '["AA","OO","AO","<u>AS</u>","SS"]', 'The child inherits A from father and S from mother, giving <u>AS</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ct8iel9tkrtkl1k9vzmth7nq1', 'General Mathematics', 'WAEC', null, 2020, null, 'If A = {1, 2, 3, 4, 5}, B = {4, 5, 6, 7}, find A △ B.', null, '["{1, 2, 3, 6, 7}","{4, 5}","{1, 2, 3, 4, 5, 6, 7}","{4, 5, 6, 7}"]', 0, 'A △ B = (A ∪ B) - (A ∩ B) = {1, 2, 3, 6, 7}.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If A = {1, 2, 3, 4, 5}, B = {4, 5, 6, 7}, find A △ B.', '["{1, 2, 3, 6, 7}","{4, 5}","{1, 2, 3, 4, 5, 6, 7}","{4, 5, 6, 7}"]', 'A △ B = <u>{1, 2, 3, 6, 7}</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ct8jlpn7ohuyme2o3n4tailkm', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The verse (Q. 17.23) warns against', null, '["insulting parents","undereeding parents","beating parents","deserting parents."]', 0, 'It warns against insulting parents.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The verse (Q. 17.23) warns against', '["<u>insulting parents</u>","undereeding parents","beating parents","deserting parents."]', '<u>Insulting parents</u> (Q. 17:23).', '{"bold":[],"italic":[],"underline":["insulting parents"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ct8xuoukr9f2ybitjije676mp', 'Chemistry', 'JAMB', null, 1993, null, 'Copper metal will react with concentrated trioxonitrate(V) acid to give', null, '["Cu(NO3)3 + NO + N2O4 + H2O","Cu(NO3)2 + NO + H2O","CuO + NO2 + H2O","Cu(NO3)2 + NO2 + H2O"]', 3, 'Cu + 4HNO3 → Cu(NO3)2 + 2NO2 + 2H2O.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Copper metal will react with concentrated trioxonitrate(V) acid to give', '["Cu(NO3)3 + NO + N2O4 + H2O","Cu(NO3)2 + NO + H2O","CuO + NO2 + H2O","Cu(NO3)2 + NO2 + H2O"]', '<u>Cu(NO3)2 + NO2 + H2O</u>.', '{"bold":[],"italic":[],"underline":["Cu(NO3)2 + NO2 + H2O"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ct96fcgfnx1z8pjhhajaabr4r', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'King Nebuchadnezzar assembled the satraps, the prefects and the governors to', null, '["tell him his dream","send them to the provinces","interpret his dream.","the dedication of the image."]', 3, 'They were assembled for the dedication of the image.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'King Nebuchadnezzar assembled the satraps, the prefects and the governors to', '["tell him his dream","send them to the provinces","interpret his dream.","<u>the dedication of the image.</u>"]', '<u>The dedication of the image</u> (Daniel 3:2).', '{"bold":[],"italic":[],"underline":["the dedication of the image."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ct98vehyx6551k6cf3h861no2', 'Government', 'JAMB', null, 2020, null, 'The commission established to handle the electoral activities in the Second Republic of Nigeria was', null, '["FEDECO","NEC","INEC","NECON"]', 0, 'FEDECO handled elections in the Second Republic.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The commission established to handle the electoral activities in the Second Republic of Nigeria was', '["<u>FEDECO</u>","NEC","INEC","NECON"]', '<u>FEDECO</u>.', '{"bold":[],"italic":[],"underline":["FEDECO"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ct9bj7h35hscsma50cv333r5a', 'Chemistry', 'JAMB', null, 1998, null, 'The lines observed in the simple hydrogen spectrum are due to emission of', null, '["electron from the atom","energy by proton transition","energy by electron transition","neutrons from the atom"]', 2, 'Hydrogen spectrum lines are due to electron transitions.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The lines observed in the simple hydrogen spectrum are due to emission of', '["electron from the atom","energy by proton transition","energy by electron transition","neutrons from the atom"]', '<u>Electron transitions</u> produce the lines.', '{"bold":[],"italic":[],"underline":["energy by electron transition"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ct9dqsr9h6dwokmia5m310h7s', 'Islamic Religious Studies', 'JAMB', null, 2008, null, 'The complete Glorious Qur''an was taken from <b>Lawh al-mahfuz</b> to the lowest of the heavens known as', null, '["Bait al-Izzah","Bait al-Maqdis","Bait al-Haram","Bait al-Hikmah"]', 0, 'The Qur''an descended from Lawh al-Mahfuz to Bait al-Izzah (the lowest heaven).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The complete Glorious Qur''an was taken from <b>Lawh al-mahfuz</b> to the lowest of the heavens known as', '["<u>Bait al-Izzah</u>","Bait al-Maqdis","Bait al-Haram","Bait al-Hikmah"]', 'The Qur''an descended from Lawh al-Mahfuz to <u>Bait al-Izzah</u>.', '{"bold":["Lawh al-mahfuz"],"italic":[],"underline":["Bait al-Izzah"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ct9g3b4v11i7385krarhcpdfs', 'Biology', 'JAMB', null, 1999, null, 'These possession of scales, laying of eggs with shells and bony structure of the head are characteristics s hared by', null, '["birds and reptiles","fishes and birds","reptiles and fishes","birds and molluscs"]', 0, 'birds and reptiles is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'These possession of scales, laying of eggs with shells and bony structure of the head are characteristics s hared by', '["<u>birds and reptiles</u>","fishes and birds","reptiles and fishes","birds and molluscs"]', 'birds and reptiles is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ct9i89eomc2zm41bl4xrv8ns3', 'Biology', 'JAMB', null, 1992, null, 'Pawpaw seeds collected from a tree with many desirable agronomic qualities did not give rise to plants of desirable characters as the parent because', null, '["seeds are not reliable for propagating plants","uncontrolled out-crossing can introduce unwanted variability","vegetative propagation is the best form of reproduction for all crops","seeds were not physiologically mature at harvest"]', 1, 'Uncontrolled out-crossing introduces unwanted variability.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Pawpaw seeds collected from a tree with many desirable agronomic qualities did not give rise to plants of desirable characters as the parent because', '["seeds are not reliable for propagating plants","<u>uncontrolled out-crossing can introduce unwanted variability</u>","vegetative propagation is the best form of reproduction for all crops","seeds were not physiologically mature at harvest"]', '<u>Uncontrolled out-crossing introduces unwanted variability</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ct9r43fjq3o296yu83udj7c8z', 'Islamic Religious Studies', 'JAMB', null, 2011, null, 'The only Surah in the Glorious Qur''an which must be recited in every obligatory prayer is', null, '["al-Baqarah","al-Alaq","al-Fatihah","al-Ikhlas"]', 2, 'Al-Fatihah must be recited in every rak''ah of prayer.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The only Surah in the Glorious Qur''an which must be recited in every obligatory prayer is', '["al-Baqarah","al-Alaq","<u>al-Fatihah</u>","al-Ikhlas"]', '<u>Al-Fatihah</u> must be recited in every rak''ah of prayer.', '{"bold":[],"italic":[],"underline":["al-Fatihah"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ct9s8es0yzz8ndafyq8etuoi2', 'Biology', 'JAMB', null, 2003, null, 'The pioneer organisms in ecological succession are usually the', null, '["lichens","algae","ferns","mosses"]', 0, 'Lichens are pioneer organisms.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The pioneer organisms in ecological succession are usually the', '["lichens","algae","ferns","mosses"]', '<u>Lichens</u>.', '{"bold":[],"italic":[],"underline":["lichens"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ct9ttc2atmk9wo1iswk6uilxy', 'Chemistry', 'JAMB', null, 1993, null, 'Which of these salts will produce its metal, oxygen and nitrogen(IV) oxide on heating?', null, '["Silver trioxonitrate(V)","Sodium trioxonitrate(V)","Calcium trioxonitrate(V)","Lithium trioxonitrate(V)"]', 0, 'AgNO3 → Ag + NO2 + O2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of these salts will produce its metal, oxygen and nitrogen(IV) oxide on heating?', '["Silver trioxonitrate(V)","Sodium trioxonitrate(V)","Calcium trioxonitrate(V)","Lithium trioxonitrate(V)"]', '<u>AgNO3 → Ag + NO2 + O2</u>.', '{"bold":[],"italic":[],"underline":["Silver trioxonitrate(V)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ct9up7umlkypcmsytrfdoskgp', 'General Mathematics', 'JAMB', null, 2020, null, 'On integers mod 5, a*b = (a + b) mod 5, find the inverse of 3.', null, '["2","3","4","1"]', 0, '3*2 = 5 ≡ 0 (mod 5); identity = 0; inverse of 3 = 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'On integers mod 5, a*b = (a + b) mod 5, find the inverse of 3.', '["2","3","4","1"]', 'Inverse = <u>2</u>.', '{"bold":[],"italic":[],"underline":["2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cta1zf36k8erceolirnpajy7m', 'General Mathematics', 'WAEC', null, 2020, null, 'If a ≡ 3 (mod 7) and b ≡ 5 (mod 7), find ab (mod 7).', null, '["1","2","3","4"]', 0, '3×5 = 15 ≡ 1 mod 7.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If a ≡ 3 (mod 7) and b ≡ 5 (mod 7), find ab (mod 7).', '["1","2","3","4"]', 'ab ≡ 3×5 = 15 ≡ <u>1</u> mod 7.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ctania15nftet429rly7mqp0n', 'Chemistry', 'JAMB', null, 1995, null, 'If 10.8g of silver is deposited in a silver coulometer connected in series with a copper coulometer, the volume of oxygen liberated is [Ag=108, Cu=64, G.M.V at s.t.p = 22.40 dm³]', null, '["0.56dm³","5.50dm³","11.20dm³","22.40dm³"]', 0, 'Moles Ag = 0.1; electrons = 0.1; moles O2 = 0.025; volume = 0.56 dm³.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If 10.8g of silver is deposited in a silver coulometer connected in series with a copper coulometer, the volume of oxygen liberated is [Ag=108, Cu=64, G.M.V at s.t.p = 22.40 dm³]', '["0.56dm³","5.50dm³","11.20dm³","22.40dm³"]', 'Volume O2 = <u>0.56 dm³</u>.', '{"bold":[],"italic":[],"underline":["0.56dm³"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ctb36szu2spntn5j9bof8fdoy', 'Chemistry', 'JAMB', null, 1983, null, 'The hybridization of the carbon atom in <b>ethylene</b> is', null, '["sp³","sp³","sp²","sp","s"]', 2, 'Ethylene (C2H4) has sp² hybridized carbons.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The hybridization of the carbon atom in <b>ethylene</b> is', '["sp³","sp³","sp²","sp","s"]', '<u>Ethylene (C2H4)</u> has sp² hybridized carbons.', '{"bold":["ethylene"],"italic":[],"underline":["sp²"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ctbuz1fy997xd4ts5zk8mgx0w', 'Islamic Religious Studies', 'JAMB', null, 2011, null, 'The outcome of the Prophet''s visit to <b>Cave Hira</b> was', null, '["compilation of the Glorious Qur''an","revelation of the Glorious Qur''an","award of chieftaincy title by the Makkan aristocrats","his resolve to migrate to Madinah"]', 1, 'The first revelation came to the Prophet in Cave Hira.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The outcome of the Prophet''s visit to <b>Cave Hira</b> was', '["compilation of the Glorious Qur''an","<u>revelation of the Glorious Qur''an</u>","award of chieftaincy title by the Makkan aristocrats","his resolve to migrate to Madinah"]', '<u>The first revelation</u> came to the Prophet in Cave Hira.', '{"bold":["Cave Hira"],"italic":[],"underline":["revelation of the Glorious Qur''an"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ctc032j3wvbo8ubn07zf28131', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Isaac''s prayer to God for his barren wife showed that he', null, '["truly loved her","sincerely loved his God","had faith in God","was tired of being childless."]', 2, 'Isaac''s prayer showed he had faith in God.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Isaac''s prayer to God for his barren wife showed that he', '["truly loved her","sincerely loved his God","<u>had faith in God</u>","was tired of being childless."]', '<u>Had faith in God</u>.', '{"bold":[],"italic":[],"underline":["had faith in God"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ctc033ti2035js2i0mqlbog68', 'Chemistry', 'JAMB', null, 1995, null, 'Equal volumes of CO, SO2, NO2 and H2S were released into a room at the same point and time. Which of the following gives the order of the room?', null, '["CO2, SO2, NO, H2S","SO2, NO2, H2S, CO","CO, H2S, SO2, NO2","CO, H2S, NO2, SO2"]', 3, 'Lighter gases diffuse faster: CO (28) < H2S (34) < NO2 (46) < SO2 (64).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Equal volumes of CO, SO2, NO2 and H2S were released into a room at the same point and time. Which of the following gives the order of the room?', '["CO2, SO2, NO, H2S","SO2, NO2, H2S, CO","CO, H2S, SO2, NO2","CO, H2S, NO2, SO2"]', '<u>CO < H2S < NO2 < SO2</u>.', '{"bold":[],"italic":[],"underline":["CO, H2S, NO2, SO2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ctc3pafz1ty7fjpjabr4ryeri', 'Government', 'JAMB', null, 2020, null, 'Indirect rule system of administration was more successful in northern Nigeria because', null, '["The natives showed little or no resistance","The people were mainly interested in being governed directly","Of the existence of an organized structure in the area","The Europeans ensured that the farmlands of the natives were not confiscated"]', 2, 'An organized structure made indirect rule succeed in the North.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Indirect rule system of administration was more successful in northern Nigeria because', '["The natives showed little or no resistance","The people were mainly interested in being governed directly","<u>Of the existence of an organized structure in the area</u>","The Europeans ensured that the farmlands of the natives were not confiscated"]', '<u>Existence of an organized structure in the area</u>.', '{"bold":[],"italic":[],"underline":["Of the existence of an organized structure in the area"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ctc5mifuzj765dz8y9ltc47se', 'Biology', 'JAMB', null, 1990, null, 'The chamber of the mammalian heart with the thickest wall is the', null, '["right ventricle","left auricle","right auricle","left ventricle"]', 3, 'The left ventricle has the thickest wall.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The chamber of the mammalian heart with the thickest wall is the', '["right ventricle","left auricle","right auricle","<u>left ventricle</u>"]', 'The <u>left ventricle</u> has the thickest wall.', null);
