insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ctcbpq2micgjizo7ldbymls5w', 'Government', 'JAMB', null, 2020, null, 'Under a parliamentary system of government, the cabinet holds office at the pleasure of the', null, '["opposition","electorate","head of state.","legislature"]', 3, 'The cabinet serves at the pleasure of the legislature.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Under a parliamentary system of government, the cabinet holds office at the pleasure of the', '["opposition","electorate","head of state.","<u>legislature</u>"]', '<u>Legislature</u>.', '{"bold":[],"italic":[],"underline":["legislature"],"fillBlanks":[]}');
