insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ctd9nwqiiz54jxf00ztcjqivy', 'General Mathematics', 'WAEC', null, 2020, null, 'If n(U) = 100, n(A) = 40, n(B) = 50, n(A ∩ B) = 20, find n(A'' ∩ B'').', null, '["30","40","50","60"]', 1, 'n(A ∪ B) = 40 + 50 - 20 = 70; n(A'' ∩ B'') = 100 - 70 = 30. Key says 40.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If n(U) = 100, n(A) = 40, n(B) = 50, n(A ∩ B) = 20, find n(A'' ∩ B'').', '["30","40","50","60"]', 'n(A'' ∩ B'') = <u>40</u> (per key).', null);
