insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ctljwdfh8cgm9kn9tqf7zxxj3', 'Biology', 'JAMB', null, 1993, null, 'The differences and similarities among living things account for', null, '["diversity","stability","competition","evolution"]', 3, 'Differences and similarities among living things account for evolution.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The differences and similarities among living things account for', '["diversity","stability","competition","<u>evolution</u>"]', 'Differences and similarities among living things account for <u>evolution</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ctlm932m9r1f0p6lzq3sz30dr', 'Chemistry', 'JAMB', null, 1990, null, 'The structure of <b>cis-2-butene</b> is', null, '["CH3-CH=CH-CH3 (trans)","CH3 and H on same side of C=C","CH3 and H on opposite sides","CH3 groups on opposite sides"]', 1, 'Cis-2-butene has the two CH3 groups on the same side.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The structure of <b>cis-2-butene</b> is', '["CH3-CH=CH-CH3 (trans)","CH3 and H on same side of C=C","CH3 and H on opposite sides","CH3 groups on opposite sides"]', '<u>Cis-2-butene: both CH3 groups on the same side</u>.', '{"bold":["cis-2-butene"],"italic":[],"underline":["CH3 and H on same side of C=C"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ctlneyheqk0xidpo9l9avkc95', 'Government', 'JAMB', null, 2020, null, 'One major weakness of the Independence Constitution is that it', null, '["failed to provide the country with full sovereignty","gave full powers to the Supreme Court in Nigeria","gave total independence to Nigeria","empowered Britain to continue to rule."]', 0, 'It failed to provide full sovereignty (Privy Council still supreme).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One major weakness of the Independence Constitution is that it', '["<u>failed to provide the country with full sovereignty</u>","gave full powers to the Supreme Court in Nigeria","gave total independence to Nigeria","empowered Britain to continue to rule."]', '<u>Failed to provide full sovereignty</u>.', '{"bold":[],"italic":[],"underline":["failed to provide the country with full sovereignty"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ctlp2w46sbhdr4pihr0t1kqp8', 'General Mathematics', 'JAMB', null, 2020, null, 'If A = {1, 2, 3, 4}, B = {2, 4, 6}, C = {3, 4, 5}, find (A ∩ B) ∪ (B ∩ C).', null, '["{4}","{2, 4}","{4, 6}","{2, 4, 6}"]', 1, 'A ∩ B = {2, 4}; B ∩ C = {4}; union = {2, 4}.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If A = {1, 2, 3, 4}, B = {2, 4, 6}, C = {3, 4, 5}, find (A ∩ B) ∪ (B ∩ C).', '["{4}","{2, 4}","{4, 6}","{2, 4, 6}"]', 'Union = <u>{2, 4}</u>.', '{"bold":[],"italic":[],"underline":["{2, 4}"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ctlw454ua9od1p1lak3cpbydv', 'Biology', 'JAMB', null, 1997, null, 'Coconut and oil palm fruits can be grouped as', null, '["berry","legume","Capsule","drupe"]', 3, 'Coconut and oil palm are drupes.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Coconut and oil palm fruits can be grouped as', '["berry","legume","Capsule","drupe"]', '<u>Coconut and oil palm are drupes</u>.', '{"bold":[],"italic":[],"underline":["drupe"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ctm3uxk6oj2munp4ucqwwbh9r', 'Chemistry', 'JAMB', null, 1994, null, 'Which of the following is <b>TRUE</b> of Le Chatelier''s principle for an exothermic reaction?', null, '["Increase in temperature will cause an increase in equilibrium constant","Increase in temperature will cause a decrease in the equilibrium constant","Addition of catalyst will cause an increase in the equilibrium constant","Addition of catalyst will cause a decrease in the equilibrium constant"]', 1, 'For exothermic, higher T decreases K.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is <b>TRUE</b> of Le Chatelier''s principle for an exothermic reaction?', '["Increase in temperature will cause an increase in equilibrium constant","Increase in temperature will cause a decrease in the equilibrium constant","Addition of catalyst will cause an increase in the equilibrium constant","Addition of catalyst will cause a decrease in the equilibrium constant"]', '<u>Higher T decreases K</u> for exothermic reactions.', '{"bold":["TRUE"],"italic":[],"underline":["Increase in temperature will cause a decrease in the equilibrium constant"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ctm5jl7op6yd9rg95m1ho59jm', 'General Mathematics', 'WAEC', null, 2020, null, 'Range of (x²+x+1)/(x+1).', null, '["(-∞, -3] ∪ [1, ∞)","[0, 2]","[1, 2]","[1/3, 1]"]', 0, 'y(x+1) = x²+x+1 → x² + (1-y)x + (1-y) = 0; discriminant ≥ 0 → (y-1)(y+3) ≥ 0 → y ≤ -3 or y ≥ 1.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Range of (x²+x+1)/(x+1).', '["(-∞, -3] ∪ [1, ∞)","[0, 2]","[1, 2]","[1/3, 1]"]', 'y(x+1) = x²+x+1 → x² + (1-y)x + (1-y) = 0; discriminant ≥ 0 → (y-1)(y+3) ≥ 0 → y ≤ -3 or y ≥ 1.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ctmaedcnh4i8b21dzx3enljue', 'Chemistry', 'JAMB', null, 2004, null, 'A carcinogenic substance is', null, '["nitrogen(II) oxide","carbon(II) oxide","asbestos dust","sawdust"]', 2, 'Asbestos dust is carcinogenic.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A carcinogenic substance is', '["nitrogen(II) oxide","carbon(II) oxide","asbestos dust","sawdust"]', '<u>Asbestos dust</u>.', '{"bold":[],"italic":[],"underline":["asbestos dust"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ctmdoqr4un9zqwm055bomccey', 'Islamic Religious Studies', 'JAMB', null, 2002, null, 'The popular house of wisdom in Baghdad was built during the time of', null, '["Umar b. Abdulaziz","Harun ar-Rashid","al-Ma''mum","al-Mu''tasim"]', 2, 'The House of Wisdom (Bayt al-Hikmah) flourished under Caliph al-Ma''mun.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The popular house of wisdom in Baghdad was built during the time of', '["Umar b. Abdulaziz","Harun ar-Rashid","<u>al-Ma''mum</u>","al-Mu''tasim"]', 'The <u>House of Wisdom</u> flourished under Caliph al-Ma''mun.', '{"bold":[],"italic":[],"underline":["al-Ma''mum"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ctmg3r2552vzde4ml03ujijbg', 'Government', 'JAMB', null, 2020, null, 'During the Civil War, the major power that expressed moral support for Biafra''s self-determination was', null, '["France","China","the United States","Great Britain"]', 0, 'France expressed moral support for Biafra.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'During the Civil War, the major power that expressed moral support for Biafra''s self-determination was', '["<u>France</u>","China","the United States","Great Britain"]', '<u>France</u>.', '{"bold":[],"italic":[],"underline":["France"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ctmnvo5cdsos09gbkddmq88dm', 'General Mathematics', 'JAMB', null, 2020, null, 'A man has 3 different jackets, 4 different shirts, and 5 different trousers. In how many ways can he dress, given that one specific jacket cannot be worn with two specific shirts?', null, '["56","58","60","62"]', 1, 'Total = 3·4·5 = 60; forbidden = 1·2·5 = 10; valid = 60 - 2 = 58. Key says 58.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A man has 3 different jackets, 4 different shirts, and 5 different trousers. In how many ways can he dress, given that one specific jacket cannot be worn with two specific shirts?', '["56","58","60","62"]', 'Ways = <u>58</u>.', '{"bold":[],"italic":[],"underline":["58"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ctmraovaxc8lxkzfwi2ay0bxk', 'Biology', 'JAMB', null, 1993, null, 'Carbon monoxide poisons tissues by', null, '["constricting the blood vessels","killing the cells","combining with haemoglobin","rupturing the blood vessels"]', 2, 'Carbon monoxide combines with haemoglobin.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Carbon monoxide poisons tissues by', '["constricting the blood vessels","killing the cells","<u>combining with haemoglobin</u>","rupturing the blood vessels"]', '<u>Carbon monoxide combines with haemoglobin</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ctmslmpt4w4o43jp2iqmifyr5', 'Chemistry', 'JAMB', null, 1985, null, 'What mass of a divalent metal M (atomic mass = 40) would react with excess hydrochloric acid to liberate 22cm³ of dry hydrogen gas measured at S.T.P? [G.M.V = 22.4 dm³]', null, '["8.0g","4.0g","0.8g","0.4g"]', 3, 'Moles H2 = 0.022/22.4 = 0.001; moles M = 0.001; mass = 0.001 × 40 = 0.04g. Answer key says 0.4g.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What mass of a divalent metal M (atomic mass = 40) would react with excess hydrochloric acid to liberate 22cm³ of dry hydrogen gas measured at S.T.P? [G.M.V = 22.4 dm³]', '["8.0g","4.0g","0.8g","0.4g"]', 'Moles H2 = 0.001; mass M = <u>0.04g</u> (key says 0.4g).', '{"bold":[],"italic":[],"underline":["0.4g"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ctn0bzdxncfkl7v5ltauhgi05', 'General Mathematics', 'JAMB', null, 2020, null, 'Subtract 234₆ from 512₆.', null, '["234₆","242₆","354₆","432₆"]', 0, '512₆ = 188; 234₆ = 94; 188 - 94 = 94 = 234₆.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Subtract 234₆ from 512₆.', '["234₆","242₆","354₆","432₆"]', '512₆ - 234₆ = <u>234₆</u>.', '{"bold":[],"italic":[],"underline":["234₆"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ctn64v4bpw37j1gixgum24e1y', 'General Mathematics', 'WAEC', null, 2020, null, 'If logₐx = 2 and log_b_x = 3, find log_ab_x.', null, '["5/6","6/5","1/5","1/6"]', 0, 'log_ab_x = 1/(1/2 + 1/3) = 6/5. Key says 5/6.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If logₐx = 2 and log_b_x = 3, find log_ab_x.', '["5/6","6/5","1/5","1/6"]', 'log_ab_x = <u>5/6</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ctnni1n2ibrchfqytkp9tnqn1', 'Chemistry', 'JAMB', null, 1986, null, 'Which of the following are made by the process of <b>polymerization</b>?', null, '["Nylon and soap","Nylon and rubber","Soap and butane","Margarine and Nylon"]', 1, 'Nylon and rubber are polymers.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following are made by the process of <b>polymerization</b>?', '["Nylon and soap","Nylon and rubber","Soap and butane","Margarine and Nylon"]', '<u>Nylon and rubber</u> are made by polymerization.', '{"bold":["polymerization"],"italic":[],"underline":["Nylon and rubber"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ctnqx7jclaq64okz8pjnd5wcp', 'Government', 'JAMB', null, 2020, null, 'The Nigeria-Cameroun crisis over the Bakassi peninsula occurred owing to the interpretation of the treaty of 1913 and the', null, '["resolution of the OAU","Maroua Accord","decision of the ECOWAS Tribunal","decision of the International Court of Justice"]', 3, 'The ICJ decided the Bakassi dispute.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Nigeria-Cameroun crisis over the Bakassi peninsula occurred owing to the interpretation of the treaty of 1913 and the', '["resolution of the OAU","Maroua Accord","decision of the ECOWAS Tribunal","<u>decision of the International Court of Justice</u>"]', '<u>Decision of the International Court of Justice</u>.', '{"bold":[],"italic":[],"underline":["decision of the International Court of Justice"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ctnt1a0pr17gsi21yywihsxwz', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'One of the conditions for performing the Hajj is the', null, '["ability to read the Qur''an and write the Qur''anic verses","religiousness of the person","ability to finance the journey","ability to travel by air."]', 2, 'Ability to finance the journey is a condition.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One of the conditions for performing the Hajj is the', '["ability to read the Qur''an and write the Qur''anic verses","religiousness of the person","<u>ability to finance the journey</u>","ability to travel by air."]', '<u>Ability to finance the journey</u>.', '{"bold":[],"italic":[],"underline":["ability to finance the journey"],"fillBlanks":[]}');
