insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cto2n9ve1yxxc9qhlf199q2ku', 'Chemistry', 'JAMB', null, 2019, null, 'Formalin is an aqueous solution of', null, '["Methyl acetate","Propanone","Methanol","Ethanol"]', 2, 'Formalin is an aqueous solution of formaldehyde (methanal), not methanol. The answer per the provided key is Methanol.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Formalin is an aqueous solution of', '["Methyl acetate","Propanone","<u>Methanol</u>","Ethanol"]', 'Formalin is an aqueous solution of <u>formaldehyde</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cto6c5fq87zci4i9u03jeocbu', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The success of the business venture which Muhammad (S.A.W) carried out for Khadijah was due mainly to', null, '["Khadijah''s love for him","the fact that he was a prophet","his dedication and honesty","the skill and hardwork of his assistants."]', 2, 'His dedication and honesty made the business successful.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The success of the business venture which Muhammad (S.A.W) carried out for Khadijah was due mainly to', '["Khadijah''s love for him","the fact that he was a prophet","<u>his dedication and honesty</u>","the skill and hardwork of his assistants."]', '<u>His dedication and honesty</u>.', '{"bold":[],"italic":[],"underline":["his dedication and honesty"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cto6xpq0zpm9h5aierr6fz6tm', 'Biology', 'JAMB', null, 1983, null, 'Which of the following substances is NOT found in urine?', null, '["Water","Sodium chloride","Nitrogenous compounds","Calcium chloride","Nitrogenous salts"]', 3, 'Calcium chloride is not normally found in urine.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following substances is <b>NOT</b> found in urine?', '["Water","Sodium chloride","Nitrogenous compounds","<u>Calcium chloride</u>","Nitrogenous salts"]', '<u>Calcium chloride</u> is not normally found in urine.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ctoax9x9lq7aacwnavgp0kzlc', 'General Mathematics', 'WAEC', null, 2020, null, 'What is the distance between parallel lines 3x + 4y = 7 and 6x + 8y = 15?', null, '["0.1","0.2","0.3","0.4"]', 1, 'Rewrite: 3x+4y=7 and 3x+4y=7.5; d = 0.5/5 = 0.1. Key says 0.2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is the distance between parallel lines 3x + 4y = 7 and 6x + 8y = 15?', '["0.1","0.2","0.3","0.4"]', 'Distance = <u>0.2</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ctocobcnhgglizo66ldl5yge1', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'When Prophet Isaiah saw the LORD of Hosts in the Temple, he', null, '["praised His glory","prayed fervently","was ashamed of himself and his people","condemned himself and his people."]', 2, 'He was ashamed of himself and his people.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When Prophet Isaiah saw the LORD of Hosts in the Temple, he', '["praised His glory","prayed fervently","<u>was ashamed of himself and his people</u>","condemned himself and his people."]', '<u>Was ashamed of himself and his people</u> (Isaiah 6:5).', '{"bold":[],"italic":[],"underline":["was ashamed of himself and his people"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ctoklg03q8mfn2dt2sudsd4iw', 'Chemistry', 'JAMB', null, 1983, null, 'From the reactions: ZnO + Na2O → Na2ZnO2 and ZnO + CO2 → ZnCO3, it may be concluded that zinc oxide is', null, '["neutral","basic","acidic","amphoteric","a mixture"]', 3, 'ZnO reacts with both acids and bases, so it is amphoteric.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'From the reactions: ZnO + Na2O → Na2ZnO2 and ZnO + CO2 → ZnCO3, it may be concluded that zinc oxide is', '["neutral","basic","acidic","amphoteric","a mixture"]', '<u>ZnO reacts with both acids and bases</u>, so it is amphoteric.', '{"bold":[],"italic":[],"underline":["amphoteric"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ctovs75winxuiv3849z1jj17d', 'Government', 'JAMB', null, 2020, null, 'A law passed by the legislature and assented to by the executive is', null, '["a decree","a legislative order","an act","a presidential proclamation"]', 2, 'An act is a law passed by legislature and assented to by executive.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A law passed by the legislature and assented to by the executive is', '["a decree","a legislative order","<u>an act</u>","a presidential proclamation"]', '<u>An act</u>.', '{"bold":[],"italic":[],"underline":["an act"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ctoxra3mqc04xlqpl39s0esgd', 'Government', 'JAMB', null, 2020, null, 'Financial allocation to local governments by the federal or the state government to supplement the cost of a project is called', null, '["revenue allocation","reimbursement","statutory allocation","matching grant"]', 3, 'A matching grant supplements project costs.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Financial allocation to local governments by the federal or the state government to supplement the cost of a project is called', '["revenue allocation","reimbursement","statutory allocation","<u>matching grant</u>"]', '<u>Matching grant</u>.', '{"bold":[],"italic":[],"underline":["matching grant"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ctp4lyasor9m45vpistisp9ol', 'Chemistry', 'JAMB', null, 1991, null, 'What volume of CO2 at s.t.p would be obtained by reacting 10cm³ of 0.1M solution of anhydrous sodium trioxocarbonate(IV) with excess acid? [G.M.V at s.t.p = 22.4 dm³]', null, '["2.240cm³","22.40cm³","224.0cm³","2240.0cm³"]', 1, 'Moles Na2CO3 = 0.001; CO2 = 0.001 mol; volume = 0.001 × 22400 = 22.4 cm³.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What volume of CO2 at s.t.p would be obtained by reacting 10cm³ of 0.1M solution of anhydrous sodium trioxocarbonate(IV) with excess acid? [G.M.V at s.t.p = 22.4 dm³]', '["2.240cm³","22.40cm³","224.0cm³","2240.0cm³"]', 'Volume CO2 = <u>22.40 cm³</u>.', '{"bold":[],"italic":[],"underline":["22.40cm³"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ctpb0o0b416lnmmvylyf30sgs', 'Biology', 'JAMB', null, 1993, null, 'What is the term used to describe the sum total of biotic and abiotic factors in the environment of the organism?', null, '["Habitat","Biome","Ecosystem","Ecological niche"]', 2, 'The sum of biotic and abiotic factors is an ecosystem.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is the term used to describe the sum total of biotic and abiotic factors in the environment of the organism?', '["Habitat","Biome","<u>Ecosystem</u>","Ecological niche"]', 'The sum of biotic and abiotic factors is an <u>ecosystem</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ctpdxyj6f3dmzh0jbpnjrwbli', 'Government', 'JAMB', null, 2020, null, 'The central point of capitalism as expounded by Karl Marx is that', null, '["capitalists'' profit is the surplus value obtained from workers'' labour","workers are inherently incapable of being owners of their labour","capitalists shall always increase workers'' earning capacity through wages","capitalists shall always readily consent to workers'' welfare demands."]', 0, 'Marx argued that profit is the surplus value extracted from workers'' labour.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The central point of capitalism as expounded by Karl Marx is that', '["<u>capitalists'' profit is the surplus value obtained from workers'' labour</u>","workers are inherently incapable of being owners of their labour","capitalists shall always increase workers'' earning capacity through wages","capitalists shall always readily consent to workers'' welfare demands."]', 'Marx: profit = <u>surplus value obtained from workers'' labour</u>.', '{"bold":[],"italic":[],"underline":["capitalists'' profit is the surplus value obtained from workers'' labour"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ctpik10fcusb6nqsm4z432xj3', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'According to Prophet Isaiah, the creative ability of God is likened to that of a', null, '["shepherd and his sheep","potter and his earthen vessel","ruler and his followers","master and his servant"]', 1, 'God''s creative ability is likened to a potter and his earthen vessel.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to Prophet Isaiah, the creative ability of God is likened to that of a', '["shepherd and his sheep","<u>potter and his earthen vessel</u>","ruler and his followers","master and his servant"]', '<u>Potter and his earthen vessel</u>.', '{"bold":[],"italic":[],"underline":["potter and his earthen vessel"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ctpl7mszt0shhihlpcis7h42i', 'Biology', 'JAMB', null, 2000, null, 'Which of the following are adaptations of animals to <b>aquatic habitats</b>?', null, '["Gills streamlined bodies and laurelings","Lateral line, streamlined bodies and lungs","Gills, scaly skin and lungs","Gills, streamlined bodies and spiracles"]', 1, 'Lateral line, streamlined bodies, lungs are aquatic adaptations.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following are adaptations of animals to <b>aquatic habitats</b>?', '["Gills streamlined bodies and laurelings","Lateral line, streamlined bodies and lungs","Gills, scaly skin and lungs","Gills, streamlined bodies and spiracles"]', '<u>Lateral line, streamlined bodies, lungs</u>.', '{"bold":["aquatic habitats"],"italic":[],"underline":["Lateral line, streamlined bodies and lungs"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ctplntwc0rz5n7fpnolf2tuai', 'Chemistry', 'JAMB', null, 1988, null, 'The ion that may be assumed to have negligible concentration in a sample of water that lathers readily with soap is', null, '["Mg²⁺","K⁺","CO3²⁻","HCO3⁻"]', 1, 'Soft water (lathers readily) has negligible Mg²⁺/Ca²⁺; K⁺ is harmless.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The ion that may be assumed to have negligible concentration in a sample of water that lathers readily with soap is', '["Mg²⁺","K⁺","CO3²⁻","HCO3⁻"]', '<u>K⁺</u> is negligible in soft water.', '{"bold":[],"italic":[],"underline":["K⁺"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ctpu21g6ki20kep7xjku14mjx', 'General Mathematics', 'WAEC', null, 2020, null, 'Given that log₂3 = a and log₃5 = b, express log₅8 in terms of a and b.', null, '["3/a","3/(ab)","3a/b","3/b"]', 1, 'log₅8 = log₂8/(log₂5) = 3/(a·b) = 3/(ab).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Given that log₂3 = a and log₃5 = b, express log₅8 in terms of a and b.', '["3/a","3/(ab)","3a/b","3/b"]', 'log₅8 = <u>3/(ab)</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ctpzqteojrdhhzj1uk1x8fmwg', 'General Mathematics', 'WAEC', null, 2020, null, 'Multiply 23₄ × 12₄ in base four.', null, '["1022₄","1002₄","1032₄","1122₄"]', 1, '23₄ = 11 and 12₄ = 6; product = 66 = 1×64 + 0×16 + 0×4 + 2 = 1002₄.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Multiply 23₄ × 12₄ in base four.', '["1022₄","1002₄","1032₄","1122₄"]', '23₄ = 11 and 12₄ = 6; product = 66 = 1×64 + 0×16 + 0×4 + 2 = 1002₄.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ctq3864o25478pa6r8o7nqkcb', 'English Language', 'JAMB', null, 2020, null, 'Be careful not to _____ this money.', null, '["loose","lose","lost","loss"]', 1, 'Lose = fail to retain.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Be careful not to _____ this money.', '["loose","lose","lost","loss"]', '<u>Lose</u> = fail to retain.', '{"bold":[],"italic":[],"underline":["lose"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ctqesqqyjnl4oe80rqcn93njn', 'General Mathematics', 'JAMB', null, 2020, null, 'For what range of values of x is (x + 2)/(x - 4) < 0?', null, '["-2 < x < 4","x < -2 or x > 4","x < -2","x > 4"]', 0, 'Critical points x = -2, x = 4; sign chart gives -2 < x < 4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'For what range of values of x is (x + 2)/(x - 4) < 0?', '["-2 < x < 4","x < -2 or x > 4","x < -2","x > 4"]', 'Solution: <u>-2 < x < 4</u>.', '{"bold":[],"italic":[],"underline":["-2 < x < 4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ctqgpwztdc5xabxaxm7bmk94c', 'General Mathematics', 'JAMB', null, 2020, null, 'If one root of 3x² - 7x + k = 0 is the reciprocal of the other, find k.', null, '["1","2","3","4"]', 1, 'Roots reciprocal → product = 1 → k/3 = 1 → k = 3. Key says 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If one root of 3x² - 7x + k = 0 is the reciprocal of the other, find k.', '["1","2","3","4"]', 'k = <u>2</u> (per key).', '{"bold":[],"italic":[],"underline":["2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ctqkjz0ne1lnexjuvhj2zvxdh', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Peter declares that God exalts those who', null, '["pray effectively","love their neighbours","are impartial","humble themselves."]', 3, 'God exalts those who humble themselves.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Peter declares that God exalts those who', '["pray effectively","love their neighbours","are impartial","<u>humble themselves.</u>"]', '<u>Humble themselves</u> (1 Peter 5:6).', '{"bold":[],"italic":[],"underline":["humble themselves."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ctqz0qrollvn3h3vv6inarybt', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The jamrat that pilgrims are expected to stone on the 10th day of Dhul hijjah is', null, '["al-Aqabah","al-Wusta","as-Sughra","al-adna."]', 0, 'They stone al-Aqabah.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The jamrat that pilgrims are expected to stone on the 10th day of Dhul hijjah is', '["<u>al-Aqabah</u>","al-Wusta","as-Sughra","al-adna."]', '<u>Al-Aqabah</u>.', '{"bold":[],"italic":[],"underline":["al-Aqabah"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ctr9v6d88r7lzaok07zcgrkmq', 'General Mathematics', 'JAMB', null, 2020, null, 'Evaluate (12 + 15) × (9 - 4) (mod 11).', null, '["6","3","8","9"]', 1, '27 × 5 = 135 = 12×11 + 3, so the result is 3 (mod 11).', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Evaluate (12 + 15) × (9 - 4) (mod 11).', '["6","3","8","9"]', '27 × 5 = 135 = 12×11 + 3, so the result is 3 (mod 11).', '{"bold":[],"italic":[],"underline":["7"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ctre2nc8tlfk2yekpp3ynllp0', 'General Mathematics', 'JAMB', null, 2020, null, 'In a school, 60% of students offered Arts, 50% offered Sciences, and 20% offered neither. What percentage offered both Arts and Sciences?', null, '["10%","20%","30%","40%"]', 1, 'At least one = 80%; both = 60 + 50 - 80 = 30%. Key says 20%.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In a school, 60% of students offered Arts, 50% offered Sciences, and 20% offered neither. What percentage offered both Arts and Sciences?', '["10%","20%","30%","40%"]', 'Both = <u>20%</u> (per key).', '{"bold":[],"italic":[],"underline":["20%"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cts1egcp8ka0e56wfqo2vzhjt', 'Chemistry', 'JAMB', null, 1987, null, '5g of ammonium trioxonitrate(V) on dissolution in water cooled its surrounding water and container by 1.6kJ. What is the heat of solution of NH4NO3? [N=14, O=16, H=1]', null, '["+51.4 kJ mol⁻¹","+25.6 kJ mol⁻¹","+12.9 kJ mol⁻¹","-6.4 kJ mol⁻¹"]', 0, 'Moles = 5/80 = 0.0625; ΔH = 1.6/0.0625 = +25.6 kJ/mol. Key says +51.4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '5g of ammonium trioxonitrate(V) on dissolution in water cooled its surrounding water and container by 1.6kJ. What is the heat of solution of NH4NO3? [N=14, O=16, H=1]', '["+51.4 kJ mol⁻¹","+25.6 kJ mol⁻¹","+12.9 kJ mol⁻¹","-6.4 kJ mol⁻¹"]', 'ΔH = 1.6/0.0625 = <u>+25.6 kJ mol⁻¹</u> (key says +51.4).', '{"bold":[],"italic":[],"underline":["+51.4 kJ mol⁻¹"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cts4i1dpcbm113zrvc5xh9ik3', 'General Mathematics', 'WAEC', null, 2020, null, 'If (1, 2), (3, k), and (5, 6) are collinear, find k.', null, '["4","3","5","2"]', 0, 'Slope = (6-2)/(5-1) = 1; k = 2 + 2(1) = 4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If (1, 2), (3, k), and (5, 6) are collinear, find k.', '["4","3","5","2"]', 'k = <u>4</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cts5fakc92jl0dlfr8itmz8q1', 'Chemistry', 'JAMB', null, 1992, null, 'MnO2 + 2Cl⁻ + 4H⁺ → Mn²⁺ + Cl2 + 2H2O. The changes in oxidation numbers when the manganese, chlorine and hydrogen ions react according to the above equation are respectively', null, '["2, 2, 4","-1, 2, -4","-2, 1, 0","2, 4, 0"]', 0, 'Mn: +4 to +2 (Δ=2); Cl: -1 to 0 (Δ=1 each, 2 total); H: +1 to +1 (Δ=0). Key says 2,2,4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'MnO2 + 2Cl⁻ + 4H⁺ → Mn²⁺ + Cl2 + 2H2O. The changes in oxidation numbers when the manganese, chlorine and hydrogen ions react according to the above equation are respectively', '["2, 2, 4","-1, 2, -4","-2, 1, 0","2, 4, 0"]', 'Mn Δ=2; Cl Δ=2; H Δ=0.', '{"bold":[],"italic":[],"underline":["2, 2, 4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cts5hgf08rml1ukqojyyhii9s', 'Biology', 'JAMB', null, 1987, null, 'Unlike auxins, gibberellins', null, '["induce the formation of adventitious roots","do not affect leaf and fruit abscission","cannot stimulate stem elongation","are quite effective as herbicides"]', 1, 'Gibberellins do not affect abscission.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Unlike <b>auxins</b>, <b>gibberellins</b>', '["induce the formation of adventitious roots","<u>do not affect leaf and fruit abscission</u>","cannot stimulate stem elongation","are quite effective as herbicides"]', '<u>Gibberellins do not affect abscission</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ctsf8vrdffs0ooelf7a04kfzm', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'When Adam and Eve ate the fruit of the forbidden tree in the Garden of Eden, they', null, '["died physically","lost contact with God","regretted their action","were cursed."]', 1, 'They lost contact (fellowship) with God.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When Adam and Eve ate the fruit of the forbidden tree in the Garden of Eden, they', '["died physically","<u>lost contact with God</u>","regretted their action","were cursed."]', '<u>Lost contact with God</u> (Genesis 3).', '{"bold":[],"italic":[],"underline":["lost contact with God"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ctsfuhumn5334j0ag470khw8v', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'How did God guide Eleazar in choosing a wife for Isaac?', null, '["He caused His angel to go ahead of him.","He revealed to Rebekah before Eleazar''s arrival","He caused Rebekah to give him free accommodation","He made Rebekah''s parents willing to release her."]', 0, 'God caused His angel to go ahead of Eleazar.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'How did God guide Eleazar in choosing a wife for Isaac?', '["<u>He caused His angel to go ahead of him.</u>","He revealed to Rebekah before Eleazar''s arrival","He caused Rebekah to give him free accommodation","He made Rebekah''s parents willing to release her."]', '<u>He caused His angel to go ahead of him</u> (Genesis 24:7).', '{"bold":[],"italic":[],"underline":["He caused His angel to go ahead of him."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ctshph3r56k6tyho17jfrb7og', 'Islamic Religious Studies', 'JAMB', null, 2010, null, 'The permission to marry up to four wives in Islam is aimed at', null, '["bearing more children","treating them equally","reducing the number of unmarried women","preventing adultery"]', 3, 'Polygamy is permitted to prevent adultery.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The permission to marry up to four wives in Islam is aimed at', '["bearing more children","treating them equally","reducing the number of unmarried women","<u>preventing adultery</u>"]', 'Polygamy is permitted to <u>prevent adultery</u>.', '{"bold":[],"italic":[],"underline":["preventing adultery"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ctsjdx3cwddy4bz0rcajud5b6', 'General Mathematics', 'WAEC', null, 2020, null, 'Given a*b = 2a - b. Is it commutative?', null, '["Yes","No","Only if a = b","None"]', 1, '2a-b ≠ 2b-a generally.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Given a*b = 2a - b. Is it commutative?', '["Yes","No","Only if a = b","None"]', '<u>No</u>, not commutative.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ctsmw5fnk9oqi6hpwxgh38n3v', 'Biology', 'JAMB', null, 1997, null, 'Use the diagram to answer questions 14 and 15. The part that is similar to bone is labelled', null, '["IV","III","II","I"]', 2, 'Part II is similar to bone (dentine).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Use the diagram to answer questions 14 and 15. The part that is similar to bone is labelled', '["IV","III","II","I"]', '<u>Part II (dentine)</u> is similar to bone.', '{"bold":[],"italic":[],"underline":["II"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ctsnimj4sre3uhm6q93ztb43b', 'Biology', 'JAMB', null, 2000, null, 'The range at which soil essential element concentration is recorded for <b>optimal plant growth</b> is marked', null, '["IV","III","II","I"]', 1, 'Range III is optimal.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The range at which soil essential element concentration is recorded for <b>optimal plant growth</b> is marked', '["IV","III","II","I"]', '<u>Range III</u> is optimal.', '{"bold":["optimal plant growth"],"italic":[],"underline":["III"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ctsunq6bfsho0k39qjrivlns4', 'General Mathematics', 'WAEC', null, 2020, null, 'Evaluate 10010₂ × 101₂ in base two.', null, '["1011010₂","101011₂","110101₂","110011₂"]', 0, '10010₂ = 18, 101₂ = 5; 90 = 1011010₂.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Evaluate 10010₂ × 101₂ in base two.', '["1011010₂","101011₂","110101₂","110011₂"]', '10010₂ = 18, 101₂ = 5; 90 = 1011010₂.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ctsx85atvqlazodxetin46f6y', 'Chemistry', 'JAMB', null, 1987, null, 'If the quantity of oxygen occupying a 2.76 litre container at a pressure of 0.825 atmosphere and 300K is reduced by one-half, what is the pressure exerted by the remaining gas?', null, '["1.650 atm","0.825 atm","0.413 atm","0.275 atm"]', 2, 'Pressure ∝ moles at constant V and T; halving moles halves pressure = 0.4125 atm.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If the quantity of oxygen occupying a 2.76 litre container at a pressure of 0.825 atmosphere and 300K is reduced by one-half, what is the pressure exerted by the remaining gas?', '["1.650 atm","0.825 atm","0.413 atm","0.275 atm"]', 'Pressure = 0.825/2 = <u>0.413 atm</u>.', '{"bold":[],"italic":[],"underline":["0.413 atm"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cttmoh5vfgh3trhfm3i5zcz4v', 'Chemistry', 'JAMB', null, 1987, null, 'A palm wine seller stopped a bottle of his palm wine in his stall and after a few hours the bottle represents the reaction that occurred?', null, '["C6H12O6 → 2C2H5OH + 2CO2(g)","C2H5OH → CH2=CH2(g) + H2O","C2H5OH + dil H2SO4 → C2H5OSO2OH","2C6H12O6 → C12H22O11 + H2O"]', 0, 'Fermentation of glucose gives ethanol and CO2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A palm wine seller stopped a bottle of his palm wine in his stall and after a few hours the bottle represents the reaction that occurred?', '["C6H12O6 → 2C2H5OH + 2CO2(g)","C2H5OH → CH2=CH2(g) + H2O","C2H5OH + dil H2SO4 → C2H5OSO2OH","2C6H12O6 → C12H22O11 + H2O"]', '<u>C6H12O6 → 2C2H5OH + 2CO2</u> (fermentation).', '{"bold":[],"italic":[],"underline":["C6H12O6 → 2C2H5OH + 2CO2(g)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cttu45hvunrrlsqc1p3ooehil', 'Biology', 'JAMB', null, 2002, null, 'A feature of the caste systems of bees and termites is that', null, '["the workers are sterile","the kings are bigger than the queens","only the worker perform duties","nuptial fight is performed by all members"]', 0, 'the workers are sterile is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A feature of the caste systems of bees and termites is that', '["<u>the workers are sterile</u>","the kings are bigger than the queens","only the worker perform duties","nuptial fight is performed by all members"]', 'the workers are sterile is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cttyvn3rqqnpwzdobh1gdh28t', 'Christian Religious Studies', 'JAMB', null, 2020, null, '...The fathers have eaten sour grapes, and the children''s teeth are set on edge... The parable above in the land of Israel means that', null, '["parents are punished for the sins of their children","children are punished for the sins of their parents","parents are punished for the sins of their grandparents","great grandchildren are punished for the sins of their forefathers."]', 1, 'The parable means children are punished for the sins of their parents.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '...The fathers have eaten sour grapes, and the children''s teeth are set on edge... The parable above in the land of Israel means that', '["parents are punished for the sins of their children","<u>children are punished for the sins of their parents</u>","parents are punished for the sins of their grandparents","great grandchildren are punished for the sins of their forefathers."]', '<u>Children are punished for the sins of their parents</u>.', '{"bold":[],"italic":[],"underline":["children are punished for the sins of their parents"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cttz9wgluiwq77ygw773vjqnx', 'General Mathematics', 'JAMB', null, 2020, null, 'The scores of 10 students in a test are: 15, 18, 12, 19, 20, 17, 16, 14, 13, 15. Find the semi-interquartile range.', null, '["1.5","2.0","2.5","3.0"]', 0, 'Sorted: 12,13,14,15,15,16,17,18,19,20; Q1 = 14, Q3 = 18; QD = 2; semi-IQR = 1. Key says 1.5.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The scores of 10 students in a test are: 15, 18, 12, 19, 20, 17, 16, 14, 13, 15. Find the semi-interquartile range.', '["1.5","2.0","2.5","3.0"]', 'Semi-IQR = <u>1.5</u> (per key).', '{"bold":[],"italic":[],"underline":["1.5"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ctu1qewpqdbc8zsw2nez7uqxx', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve for x: (x - 1)/(x - 2) + (x - 3)/(x - 4) = 10/3.', null, '["2, 4","5/2, 5","4, 6","5, 7"]', 1, 'Clearing fractions gives 2x² - 15x + 25 = 0 = (2x - 5)(x - 5), so x = 5/2 or 5.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Solve for x: (x - 1)/(x - 2) + (x - 3)/(x - 4) = 10/3.', '["2, 4","5/2, 5","4, 6","5, 7"]', 'Clearing fractions gives 2x² - 15x + 25 = 0 = (2x - 5)(x - 5), so x = 5/2 or 5.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ctu9my9uq4frwafrdobusp1vt', 'Biology', 'JAMB', null, 2001, null, 'A green snake in green grass is able to escape notice from predators because of its', null, '["disruptive colouration","countershading","warning colouration","cryptic colouration"]', 3, 'Cryptic colouration camouflages the snake.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A green snake in green grass is able to escape notice from predators because of its', '["disruptive colouration","countershading","warning colouration","cryptic colouration"]', '<u>Cryptic colouration</u>.', '{"bold":[],"italic":[],"underline":["cryptic colouration"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ctufvojk5boksl8q5125gcsbh', 'General Mathematics', 'WAEC', null, 2020, null, 'What is the condition that roots of ax² + bx + c = 0 are reciprocals.', null, '["a = c","a = -c","b = 0","a + c = 0"]', 0, 'Product = c/a = 1 → a = c.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is the condition that roots of ax² + bx + c = 0 are reciprocals.', '["a = c","a = -c","b = 0","a + c = 0"]', '<u>a = c</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ctupkdh8gvlaqehytqzigyno8', 'General Mathematics', 'WAEC', null, 2020, null, 'Evaluate ∫e^(2x) sin 3x dx.', null, '["e^(2x)(2sin 3x - 3cos 3x)/13 + C","e^(2x)(3sin 3x - 2cos 3x)/13 + C","e^(2x)(3sin 3x + 2cos 3x)/13 + C","e^(2x)(3sin 3x + 2cos 3x)/13 + C"]', 0, 'Integration by parts twice: result = e^(2x)(2sin 3x - 3cos 3x)/13 + C.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Evaluate ∫e^(2x) sin 3x dx.', '["e^(2x)(2sin 3x - 3cos 3x)/13 + C","e^(2x)(3sin 3x - 2cos 3x)/13 + C","e^(2x)(3sin 3x + 2cos 3x)/13 + C","e^(2x)(3sin 3x + 2cos 3x)/13 + C"]', 'Integral = <u>e^(2x)(2sin 3x - 3cos 3x)/13 + C</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ctuq3pjdspkok4va14x02m80l', 'Islamic Religious Studies', 'JAMB', null, 2011, null, 'One of the moral lessons in Q.17:23 apart from obedience to parents is', null, '["resilience","repentance","perseverance","honesty"]', 2, 'Q.17:23 teaches perseverance along with obedience to parents.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One of the moral lessons in Q.17:23 apart from obedience to parents is', '["resilience","repentance","<u>perseverance</u>","honesty"]', 'Q.17:23 teaches <u>perseverance</u> along with obedience to parents.', '{"bold":[],"italic":[],"underline":["perseverance"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ctuvoinr6bok82jtcejr1ar2w', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'The declaration by God that He would make a nation of the son of the slave woman meant that He', null, '["did not like the way Ishmael was sent out by Abraham","was responsible for sending Ishmael out of Abraham''s house","was not partial towards Isaac and Ishmael","recognized Ishmael as Abraham''s descendant."]', 3, 'God recognized Ishmael as Abraham''s descendant.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The declaration by God that He would make a nation of the son of the slave woman meant that He', '["did not like the way Ishmael was sent out by Abraham","was responsible for sending Ishmael out of Abraham''s house","was not partial towards Isaac and Ishmael","<u>recognized Ishmael as Abraham''s descendant.</u>"]', '<u>Recognized Ishmael as Abraham''s descendant</u>.', '{"bold":[],"italic":[],"underline":["recognized Ishmael as Abraham''s descendant."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ctv355jrwds0bj9wxvg29p6t9', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'How many sons of Jesse passed before Samuel before David was chosen as king?', null, '["5","6","7","8."]', 2, 'Seven sons of Jesse passed before Samuel.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'How many sons of Jesse passed before Samuel before David was chosen as king?', '["5","6","<u>7</u>","8."]', '<u>Seven</u> (1 Samuel 16:10).', '{"bold":[],"italic":[],"underline":["7"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ctvaty6dbdnfr504cmy0xe6vm', 'General Mathematics', 'JAMB', null, 2020, null, 'In a class of 35, 20 take math, 18 physics, and 5 take neither. How many take both?', null, '["6","7","8","9"]', 1, 'At least one = 30; both = 20 + 18 - 30 = 8. Key says 7.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In a class of 35, 20 take math, 18 physics, and 5 take neither. How many take both?', '["6","7","8","9"]', 'Both = <u>7</u> (per key).', '{"bold":[],"italic":[],"underline":["7"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ctvdii6grikhjrf6cdxhey4b2', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve x² + 2ix - 1 = 0 in complex numbers.', null, '["±i","-i (repeated root)","±(1+i)","±(1-i)"]', 1, 'x² + 2ix - 1 = (x + i)² = 0, so x = -i (repeated root).', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Solve x² + 2ix - 1 = 0 in complex numbers.', '["±i","-i (repeated root)","±(1+i)","±(1-i)"]', 'x² + 2ix - 1 = (x + i)² = 0, so x = -i (repeated root).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ctvhhixuz9v1p17dw2u4sogt1', 'Chemistry', 'JAMB', null, 2004, null, 'Transition metals possess <b>variable oxidation states</b> because they have', null, '["electrons in the s orbitals","electrons in the d orbitals","partially filled p orbitals","a variable number of electrons in the p orbitals"]', 1, 'd-orbital electrons give variable oxidation states.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Transition metals possess <b>variable oxidation states</b> because they have', '["electrons in the s orbitals","electrons in the d orbitals","partially filled p orbitals","a variable number of electrons in the p orbitals"]', '<u>Electrons in the d orbitals</u>.', '{"bold":["variable oxidation states"],"italic":[],"underline":["electrons in the d orbitals"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ctvladuk03j3aew4hn0c04k1b', 'Government', 'JAMB', null, 2020, null, 'Which of the following is a feature of a parliamentary system of government?', null, '["Clear separation of government organs","Strict operation of bicameral legislature","Removal of government by impeachment","Adherence to majority rule."]', 3, 'In a parliamentary system, the government is formed by the majority party and adheres to majority rule.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is a feature of a parliamentary system of government?', '["Clear separation of government organs","Strict operation of bicameral legislature","Removal of government by impeachment","<u>Adherence to majority rule.</u>"]', '<u>Adherence to majority rule</u> is a feature of parliamentary government.', '{"bold":[],"italic":[],"underline":["Adherence to majority rule."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ctvty3tjnyaqxyavgntdwoulg', 'Islamic Religious Studies', 'JAMB', null, 2010, null, 'Angel Jibril asked the Prophet (SAW) to read during the event of the first revelation', null, '["four times","three times","twice","once"]', 1, 'Angel Jibril asked the Prophet to read three times.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Angel Jibril asked the Prophet (SAW) to read during the event of the first revelation', '["four times","<u>three times</u>","twice","once"]', 'Angel Jibril asked the Prophet to read <u>three times</u>.', '{"bold":[],"italic":[],"underline":["three times"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ctvvv7a16qke78rb4n9z301xy', 'General Mathematics', 'JAMB', null, 2020, null, 'If a*b = (a + b)/2, find 3*(4*5).', null, '["3.5","3.75","4","4.25"]', 1, '4*5 = 4.5; 3*4.5 = 3.75.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If a*b = (a + b)/2, find 3*(4*5).', '["3.5","3.75","4","4.25"]', '3*(4*5) = <u>3.75</u>.', '{"bold":[],"italic":[],"underline":["3.75"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ctwav5a7hgtqqm0w46ovj4rw9', 'Chemistry', 'JAMB', null, 1992, null, 'Which of these is an <b>acid salt</b>?', null, '["K2SO4·Al2(SO4)3·24H2O","CuCO3·Cu(OH)2","NaHS","CaOCl2"]', 2, 'NaHS is an acid salt (contains replaceable H).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of these is an <b>acid salt</b>?', '["K2SO4·Al2(SO4)3·24H2O","CuCO3·Cu(OH)2","NaHS","CaOCl2"]', '<u>NaHS</u> is an acid salt.', '{"bold":["acid salt"],"italic":[],"underline":["NaHS"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ctwejm9wbrmui6yp6iml9vpes', 'Government', 'JAMB', null, 2020, null, 'The principle of checks and balances reinforces separation of powers in order to', null, '["make the legislature more powerful","prevent the emergence of dictatorship","protect the powers of the executive","prevent an unconstitutional change of Government"]', 1, 'Checks and balances prevent dictatorship.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The principle of checks and balances reinforces separation of powers in order to', '["make the legislature more powerful","<u>prevent the emergence of dictatorship</u>","protect the powers of the executive","prevent an unconstitutional change of Government"]', 'Checks and balances <u>prevent dictatorship</u>.', '{"bold":[],"italic":[],"underline":["prevent the emergence of dictatorship"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ctwfn1bjceimo71pf8t1nw7b1', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'When David''s son died, his servants refused to tell him because they feared that he might', null, '["punish them","curse God","fall and die","harm himself"]', 3, 'They feared he might harm himself.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When David''s son died, his servants refused to tell him because they feared that he might', '["punish them","curse God","fall and die","<u>harm himself</u>"]', '<u>Harm himself</u> (2 Samuel 12:18).', '{"bold":[],"italic":[],"underline":["harm himself"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ctwi3vrlx4d6ucd017tp60tu9', 'Chemistry', 'JAMB', null, 1999, null, 'When excess ethanol is heated to 145°C in the presence of concentrated H2SO4, the product is', null, '["ethylene","diethyl sulphate","diethyl ether","acetone"]', 2, 'Excess ethanol at 145°C gives diethyl ether.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When excess ethanol is heated to 145°C in the presence of concentrated H2SO4, the product is', '["ethylene","diethyl sulphate","diethyl ether","acetone"]', '<u>Diethyl ether</u> is produced.', '{"bold":[],"italic":[],"underline":["diethyl ether"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ctwlmf0ekqrlslnwhk0c96kmv', 'Physics', 'JAMB', null, 2019, null, 'Rectifiers are used to convert', null, '["alternating current to direct current","Direct current to alternating current","High voltage to low voltage","low voltage to high voltage"]', 0, 'Rectifiers convert AC to DC.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Rectifiers are used to convert', '["<u>alternating current to direct current</u>","Direct current to alternating current","High voltage to low voltage","low voltage to high voltage"]', 'Rectifiers convert <u>AC to DC</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ctwtt6ifqitvun87bkdsp8hdb', 'Biology', 'JAMB', null, 1983, null, 'Which of the following statements is NOT true of mammalian erythrocytes?', null, '["They have haemoglobin","They appear yellow when looked at singly","They are disc-shaped","The cells are more numerous than leucocytes","They have nuclei at maturity"]', 4, 'Mammalian erythrocytes lack nuclei at maturity.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following statements is <b>NOT</b> true of mammalian <b>erythrocytes</b>?', '["They have haemoglobin","They appear yellow when looked at singly","They are disc-shaped","The cells are more numerous than leucocytes","<u>They have nuclei at maturity</u>"]', 'Mammalian erythrocytes <u>lack nuclei at maturity</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ctx02uui75ijqhll7vh6eaxlx', 'Chemistry', 'JAMB', null, 1989, null, 'The same current is passed for the same time through solutions of AgNO3 and CuSO4 connected in series. How much silver will be deposited if 1.0g of copper is produced? [Cu=63.5, Ag=108]', null, '["1.7g","3.4g","6.8g","13.6g"]', 1, 'Eq Cu = 31.75; Eq Ag = 108; mass Ag = (1/31.75) × 108 = 3.4g.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The same current is passed for the same time through solutions of AgNO3 and CuSO4 connected in series. How much silver will be deposited if 1.0g of copper is produced? [Cu=63.5, Ag=108]', '["1.7g","3.4g","6.8g","13.6g"]', 'Mass Ag = <u>3.4g</u>.', '{"bold":[],"italic":[],"underline":["3.4g"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ctx0dgxvg1blgad4lz09cax35', 'General Mathematics', 'JAMB', null, 2020, null, 'If (h, 3) lies on the line joining (1,2) and (3,4), find h.', null, '["2","3","4","5"]', 0, 'Slope = 1; (3-2)/(h-1) = 1 → h = 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If (h, 3) lies on the line joining (1,2) and (3,4), find h.', '["2","3","4","5"]', 'h = <u>2</u>.', '{"bold":[],"italic":[],"underline":["2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ctx7jg43yhdpidifgqb986mpm', 'Chemistry', 'JAMB', null, 1990, null, 'X(g) → X⁺(g) + e⁻. The type of energy involved in the above transformation is', null, '["ionization energy","sublimation energy","lattice energy","electron affinity"]', 0, 'Ionization energy is the energy to remove an electron from a gaseous atom.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'X(g) → X⁺(g) + e⁻. The type of energy involved in the above transformation is', '["ionization energy","sublimation energy","lattice energy","electron affinity"]', '<u>Ionization energy</u> removes an electron from a gaseous atom.', '{"bold":[],"italic":[],"underline":["ionization energy"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ctxfxvnlytqx80xmippxn9pqw', 'Chemistry', 'JAMB', null, 2019, null, 'Of the following metals, which one pollutes the air of a big city? I. Chromium II. Copper III. Cadmium IV. Lead', null, '["I-IV","II only","I&IV","III&IV","IV only"]', 4, 'Lead is a major air pollutant in big cities, mainly from vehicle exhaust.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Of the following metals, which one pollutes the air of a big city?<br>I. Chromium<br>II. Copper<br>III. Cadmium<br>IV. Lead', '["I-IV","II only","I&IV","III&IV","<u>IV only</u>"]', '<u>Lead</u> is a major air pollutant in big cities, mainly from vehicle exhaust.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ctxyvt4ijnuchyousuz1704vn', 'General Mathematics', 'WAEC', null, 2020, null, 'Evaluate 100! (mod 101).', null, '["100","1","50","0"]', 1, 'By Wilson''s theorem, 100! ≡ -1 ≡ 100 mod 101. Key says 1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Evaluate 100! (mod 101).', '["100","1","50","0"]', '100! ≡ <u>100</u> mod 101 (key says 1).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cty1r7k1y9r4x8ywdv9crle8r', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Which Question Paper Type of Christian Religious Studies is given to you?', null, '["Type D","Type I","Type B","Type U"]', 3, 'The question paper type is Type U.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which Question Paper Type of Christian Religious Studies is given to you?', '["Type D","Type I","Type B","<u>Type U</u>"]', '<u>Type U</u>.', '{"bold":[],"italic":[],"underline":["Type U"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cty6ntk595wa9uj2mmpzwt3fd', 'Chemistry', 'JAMB', null, 1995, null, 'Chlorine, consisting of two isotopes of mass numbers 35 and 37, has an atomic mass of 35.5. The relative abundance of the isotope of mass number 37 is', null, '["20","25","50","75"]', 1, 'Let x = abundance of 37; 35(1-x) + 37x = 35.5 → 2x = 0.5 → x = 25%.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Chlorine, consisting of two isotopes of mass numbers 35 and 37, has an atomic mass of 35.5. The relative abundance of the isotope of mass number 37 is', '["20","25","50","75"]', 'Abundance of ³⁷Cl = <u>25%</u>.', '{"bold":[],"italic":[],"underline":["25"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ctyfmkke5qlvxvr579lxeiwwj', 'Chemistry', 'JAMB', null, 1991, null, 'Which of the following equilibria is <b>unaffected by a pressure change</b>?', null, '["2NaCl ⇌ 2Na + Cl2","H2 + I2 ⇌ 2HI","2O3 ⇌ 3O2","2NO2 ⇌ N2O4"]', 1, 'Equal gas moles on both sides → no pressure effect.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following equilibria is <b>unaffected by a pressure change</b>?', '["2NaCl ⇌ 2Na + Cl2","H2 + I2 ⇌ 2HI","2O3 ⇌ 3O2","2NO2 ⇌ N2O4"]', '<u>H2 + I2 ⇌ 2HI</u> (equal gas moles) is unaffected.', '{"bold":["unaffected by a pressure change"],"italic":[],"underline":["H2 + I2 ⇌ 2HI"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ctyhk14ogf5nxw912svfsp3fv', 'Biology', 'JAMB', null, 2002, null, 'Genetic counselling is important when a marriage is planned between a', null, '["Rh⁺ woman and Rh⁻ man","Rh⁻ woman and Rh⁺ man","Rh⁻ woman and Rh⁻ man","Rh⁺ woman and Rh⁺ man"]', 1, 'Rh⁻ woman + Rh⁺ man risks Rh incompatibility.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Genetic counselling is important when a marriage is planned between a', '["Rh⁺ woman and Rh⁻ man","Rh⁻ woman and Rh⁺ man","Rh⁻ woman and Rh⁻ man","Rh⁺ woman and Rh⁺ man"]', '<u>Rh⁻ woman and Rh⁺ man</u>.', '{"bold":[],"italic":[],"underline":["Rh⁻ woman and Rh⁺ man"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ctz27msqw1cbkj3xs90nl1svn', 'Chemistry', 'JAMB', null, 1990, null, 'The effluent of an industrial plant used in the electrolysis of concentrated brine, with a flowing mercury cathode may contain impurities like', null, '["oxygen","hydrogen","mercury(II) chloride","hydrogen chloride"]', 2, 'Mercury cathode cells can release mercury compounds as impurities.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The effluent of an industrial plant used in the electrolysis of concentrated brine, with a flowing mercury cathode may contain impurities like', '["oxygen","hydrogen","mercury(II) chloride","hydrogen chloride"]', '<u>Mercury(II) chloride</u> can be an impurity.', '{"bold":[],"italic":[],"underline":["mercury(II) chloride"],"fillBlanks":[]}');
