insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ctz3vwmmnzne06d66y8y8hl30', 'Islamic Religious Studies', 'JAMB', null, 2002, null, 'Taftif in business transaction occurs when one of the partners', null, '["over-prices the goods","under-prices the commodity","tampers with the measure","refuses to pay for the goods"]', 2, 'Taftif means giving short measure (Q.83:1-3).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Taftif in business transaction occurs when one of the partners', '["over-prices the goods","under-prices the commodity","<u>tampers with the measure</u>","refuses to pay for the goods"]', '<u>Taftif</u> means giving short measure.', '{"bold":[],"italic":[],"underline":["tampers with the measure"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ctz5lvhu66prljt5ecvjljwzk', 'General Mathematics', 'JAMB', null, 2020, null, 'Find ∫ dx/(1 + sin x).', null, '["-tan x + sec x + C","tan x - sec x + C","tan x + sec x + C","-tan x - sec x + C"]', 0, 'Multiply by (1 - sin x)/(1 - sin x); ∫ = -tan x + sec x + C.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find ∫ dx/(1 + sin x).', '["-tan x + sec x + C","tan x - sec x + C","tan x + sec x + C","-tan x - sec x + C"]', 'Integral = <u>-tan x + sec x + C</u>.', '{"bold":[],"italic":[],"underline":["-tan x + sec x + C"],"fillBlanks":[]}');
