insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ctzcg9cxoi1f7q6nbrj4aybni', 'Biology', 'JAMB', null, 1993, null, 'Osmic acid boiled with a solution of food substance gave a black precipitate. This indicated the presence of', null, '["fats and oils","proteins","amino acids","starch"]', 0, 'A black precipitate with osmic acid indicates fats and oils.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Osmic acid boiled with a solution of food substance gave a black precipitate. This indicated the presence of', '["<u>fats and oils</u>","proteins","amino acids","starch"]', 'A <u>black precipitate with osmic acid indicates fats and oils</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ctzeo38t3pn5j04bjn1ssnj2u', 'Government', 'JAMB', null, 2020, null, 'In a confederation, the constituency that a member of legislature represents is a', null, '["nation-state","region","senatorial district","parliamentary constituency"]', 0, 'Confederal legislators represent nation-states.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In a confederation, the constituency that a member of legislature represents is a', '["<u>nation-state</u>","region","senatorial district","parliamentary constituency"]', '<u>Nation-state</u>.', '{"bold":[],"italic":[],"underline":["nation-state"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ctzjzr4p5vc15v4e3svqwi56r', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Qur''an 22:31 likens one who assigns partners to Allah to that who had fallen from heaven and was snatched up by', null, '["the angels","spirits","the devil","birds"]', 2, 'He was snatched up by the devil.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Qur''an 22:31 likens one who assigns partners to Allah to that who had fallen from heaven and was snatched up by', '["the angels","spirits","<u>the devil</u>","birds"]', '<u>The devil</u> (Q. 22:31).', '{"bold":[],"italic":[],"underline":["the devil"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ctzm2f6ulccn3fq85bfnafgfw', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The verse (Q. 95.8) refers to Allah as', null, '["a good judge?","our judge?","the best of judges?","the Head of all Judges?"]', 2, 'Allah is the best of judges.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The verse (Q. 95.8) refers to Allah as', '["a good judge?","our judge?","<u>the best of judges?</u>","the Head of all Judges?"]', '<u>The best of judges</u> (Q. 95:8).', '{"bold":[],"italic":[],"underline":["the best of judges?"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ctzmdqah4wd156f3s0jssqyf1', 'General Mathematics', 'JAMB', null, 2020, null, 'If A ⊂ B, then A ∪ B = ?', null, '["A","B","A ∩ B","U"]', 1, 'A ⊂ B → A ∪ B = B.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If A ⊂ B, then A ∪ B = ?', '["A","B","A ∩ B","U"]', 'A ∪ B = <u>B</u>.', '{"bold":[],"italic":[],"underline":["B"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ctzt27wkb7blqjgisaump0z1o', 'Biology', 'JAMB', null, 1987, null, 'A severe deficiency of thyroxin results in', null, '["diabetes mellitus","sexual underdevelopment","cretinism","gigantism"]', 2, 'Thyroxin deficiency causes cretinism.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A severe deficiency of <b>thyroxin</b> results in', '["diabetes mellitus","sexual underdevelopment","<u>cretinism</u>","gigantism"]', '<u>Thyroxin deficiency causes cretinism</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ctzv66e91frltzso4rxkm2c42', 'General Mathematics', 'WAEC', null, 2020, null, 'If α, β are roots of x² - 5x + 3 = 0 find α/β + β/α', null, '["19/3","17/3","5/3","7/3"]', 0, '(α²+β²)/αβ = (25-6)/3 = 19/3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If α, β are roots of x² - 5x + 3 = 0 find α/β + β/α', '["19/3","17/3","5/3","7/3"]', null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ctzvt4n1m7wi3t22o4gwcrowe', 'Government', 'JAMB', null, 2020, null, 'The one-time president of the United Nations General Assembly was', null, '["Joseph Garba","Ibrahim Gambari","Arthur Mbanefo.","Maitama Sule"]', 0, 'Joseph Garba served as UNGA President.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The one-time president of the United Nations General Assembly was', '["<u>Joseph Garba</u>","Ibrahim Gambari","Arthur Mbanefo.","Maitama Sule"]', '<u>Joseph Garba</u>.', '{"bold":[],"italic":[],"underline":["Joseph Garba"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ctzwv1nxaxmqsne9ts4rhyzc4', 'General Mathematics', 'JAMB', null, 2020, null, 'If n(A) = 35, n(B) = 45, n(A ∪ B) = 60, find n(A ∩ B).', null, '["20","25","30","35"]', 0, 'n(A ∩ B) = 35 + 45 - 60 = 20.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If n(A) = 35, n(B) = 45, n(A ∪ B) = 60, find n(A ∩ B).', '["20","25","30","35"]', 'n(A ∩ B) = <u>20</u>.', '{"bold":[],"italic":[],"underline":["20"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('ctzxg7zjlm3wgzzt1qeto7oaj', 'Islamic Religious Studies', 'JAMB', null, 2008, null, 'In congregational Salah, a person who comes late is expected to', null, '["pronounce the taslim to indicate his arrival","say subhanallah so that the Imam can note his presence","recite the iqama before joining the congregation","make takbiratul ihram and join the Imam"]', 3, 'A latecomer makes takbiratul ihram and joins the Imam.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In congregational Salah, a person who comes late is expected to', '["pronounce the taslim to indicate his arrival","say subhanallah so that the Imam can note his presence","recite the iqama before joining the congregation","<u>make takbiratul ihram and join the Imam</u>"]', 'A latecomer makes <u>takbiratul ihram and joins the Imam</u>.', '{"bold":[],"italic":[],"underline":["make takbiratul ihram and join the Imam"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cu0286bw0xruxs81b4tcpot1v', 'General Mathematics', 'JAMB', null, 2020, null, 'Evaluate (2/3) ÷ (4/9) + (5/6) × (3/10).', null, '["1.5","1.75","2","2.25"]', 1, '(2/3)×(9/4) + (5/6)×(3/10) = 3/2 + 1/4 = 1.75.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Evaluate (2/3) ÷ (4/9) + (5/6) × (3/10).', '["1.5","1.75","2","2.25"]', '(2/3)÷(4/9) + (5/6)×(3/10) = <u>1.75</u>.', '{"bold":[],"italic":[],"underline":["1.75"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cu044uadwa46bchjgsp8qdmna', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'According to Hosea, what would God abolish from the land after making a covenant with Israel?', null, '["The bow","Famine","Foreign gods","Baal"]', 0, 'God would abolish the bow from the land.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to Hosea, what would God abolish from the land after making a covenant with Israel?', '["<u>The bow</u>","Famine","Foreign gods","Baal"]', '<u>The bow</u> (Hosea 2:17-18).', '{"bold":[],"italic":[],"underline":["The bow"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cu08cu6o09muuupbutdmz55qv', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve x² - 5x + 6 < 0.', null, '["(2, 3)","[2, 3]","(-∞, 2) ∪ (3, ∞)","(-∞, 2] ∪ [3, ∞)"]', 0, '(x-2)(x-3) < 0 → 2 < x < 3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve x² - 5x + 6 < 0.', '["(2, 3)","[2, 3]","(-∞, 2) ∪ (3, ∞)","(-∞, 2] ∪ [3, ∞)"]', '<u>2 < x < 3</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cu0a2xmk12cr9yd5jomyj5v9s', 'General Mathematics', 'WAEC', null, 2020, null, 'The polynomial x⁴ - 6x³ + 13x² - 12x + 4 is a perfect square. Find its square root.', null, '["x² - 3x + 2","x² + 3x + 2","x² - 3x - 2","x² + 3x - 2"]', 0, '(x² - 3x + 2)² = x⁴ - 6x³ + 13x² - 12x + 4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The polynomial x⁴ - 6x³ + 13x² - 12x + 4 is a perfect square. Find its square root.', '["x² - 3x + 2","x² + 3x + 2","x² - 3x - 2","x² + 3x - 2"]', 'Square root = <u>x² - 3x + 2</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cu0nvpcepyd5f367jf0igq0pd', 'Biology', 'JAMB', null, 2002, null, 'One of the adaptations to life on trees by a monkey is its possession of digits which are', null, '["extensible","big","opposable","long"]', 2, 'Monkeys have opposable digits.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One of the adaptations to life on trees by a monkey is its possession of digits which are', '["extensible","big","opposable","long"]', '<u>Opposable digits</u>.', '{"bold":[],"italic":[],"underline":["opposable"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cu0zz25mo6dx17dfx4xc2ofqt', 'General Mathematics', 'JAMB', null, 2020, null, 'If log_a(bc) = x, log_b(ca) = y and log_c(ab) = z, find 1/(x + 1) + 1/(y + 1) + 1/(z + 1).', null, '["0","1","2","3"]', 1, 'Identity: sum = 1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If log_a(bc) = x, log_b(ca) = y and log_c(ab) = z, find 1/(x + 1) + 1/(y + 1) + 1/(z + 1).', '["0","1","2","3"]', 'Sum = <u>1</u>.', '{"bold":[],"italic":[],"underline":["1"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cu13qusoe1t85z7gcrnv1b0px', 'Biology', 'JAMB', null, 1986, null, 'Gestation in mammals is the period', null, '["required for growth after birth","between the formation of the foetus and birth","of development from zygote to birth","before the formation of the zygote"]', 2, 'Gestation is the development period from zygote to birth.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Gestation in mammals is the period', '["required for growth after birth","between the formation of the foetus and birth","<u>of development from zygote to birth</u>","before the formation of the zygote"]', '<u>Gestation</u> is the development period from zygote to birth.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cu13sa7kt9bdvl9eqt6glgnyx', 'Biology', 'JAMB', null, 1989, null, 'Mortar is NOT used for under-water construction because', null, '["It hardens by loss of water","Its hardening does not depend upon evaporation","It requires concrete to harden","It will be washed away by the flow of water"]', 0, 'Mortar hardens by losing water, so it cannot set under water.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Mortar is NOT used for under-water construction because', '["It hardens by loss of water","Its hardening does not depend upon evaporation","It requires concrete to harden","It will be washed away by the flow of water"]', '<u>Mortar hardens by loss of water</u>.', '{"bold":[],"italic":[],"underline":["It hardens by loss of water"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cu172xlu5eapr56bth2u82uan', 'Islamic Religious Studies', 'JAMB', null, 2010, null, 'The correct order of the Caliphs who standardized and compiled the Qur''an is', null, '["Abu Bakr, Umar, Uthman","Umar, Abu Bakr, Uthman","Abu Bakr, Uthman, Umar","Uthman, Abu Bakr, Umar"]', 0, 'Abu Bakr compiled it, Umar suggested it, Uthman standardized it.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The correct order of the Caliphs who standardized and compiled the Qur''an is', '["<u>Abu Bakr, Umar, Uthman</u>","Umar, Abu Bakr, Uthman","Abu Bakr, Uthman, Umar","Uthman, Abu Bakr, Umar"]', '<u>Abu Bakr compiled it, Umar suggested it, Uthman standardized it.</u>', '{"bold":[],"italic":[],"underline":["Abu Bakr, Umar, Uthman"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cu1789jo88ei58sgndw89fxr1', 'Islamic Religious Studies', 'JAMB', null, 2008, null, 'The caliph who introduced stipend for teachers was', null, '["Abu Bakr","Umar","Uthman","Ali"]', 1, 'Umar b. Khattab introduced stipends for teachers and soldiers.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The caliph who introduced stipend for teachers was', '["Abu Bakr","<u>Umar</u>","Uthman","Ali"]', '<u>Umar b. Khattab</u> introduced stipends for teachers and soldiers.', '{"bold":[],"italic":[],"underline":["Umar"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cu17wcyc1u2xnn895m00cy6b7', 'Biology', 'JAMB', null, 1984, null, 'How many nuclei are found in a pollen tube during fertilization?', null, '["2","3","5","6","7"]', 1, 'The pollen tube contains 3 nuclei during fertilization.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'How many nuclei are found in a pollen tube during fertilization?', '["2","<u>3</u>","5","6","7"]', 'The pollen tube contains <u>3 nuclei</u> during fertilization.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cu1b8q4ory7oa3iz7eprki2jf', 'Chemistry', 'JAMB', null, 1985, null, 'The exhaust fumes from a garage in a place that uses petrol of high sulphur content are bound to contain', null, '["CO and SO3","CO and SO2","CO, SO2 and SO3","CO and H2S"]', 1, 'High sulphur petrol produces CO and SO2 in exhaust.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The exhaust fumes from a garage in a place that uses petrol of high sulphur content are bound to contain', '["CO and SO3","CO and SO2","CO, SO2 and SO3","CO and H2S"]', '<u>CO and SO2</u> are produced.', '{"bold":[],"italic":[],"underline":["CO and SO2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cu1darlw1v4f5epfz4xlymfng', 'Government', 'JAMB', null, 2020, null, 'Rule by the old people is known as', null, '["Feudalism","Theocracy","Monarchy","Gerontocracy."]', 3, 'Gerontocracy is rule by the old.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Rule by the old people is known as', '["Feudalism","Theocracy","Monarchy","<u>Gerontocracy.</u>"]', '<u>Gerontocracy</u>.', '{"bold":[],"italic":[],"underline":["Gerontocracy."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cu1km4208l38peemrb5j6tx1q', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve √(4x-3) + √(2x+1) = 4.', null, '["2","26 - 4√37","3","3.5"]', 1, 'Let B = √(2x+1): B² + 8B - 21 = 0 → B = √37 - 4 → x = 26 - 4√37 ≈ 1.67.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Solve √(4x-3) + √(2x+1) = 4.', '["2","26 - 4√37","3","3.5"]', 'Let B = √(2x+1): B² + 8B - 21 = 0 → B = √37 - 4 → x = 26 - 4√37 ≈ 1.67.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cu1noc4v82e06ifsp7l6r6w73', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve (3x - 1)/(x - 2) ≥ 2.', null, '["x ≤ -3 or x ≥ 3","x ≥ 3 or x < 2","x ≤ -3 or x > 2","x ≤ 3 or x > 2"]', 2, '(3x-1)/(x-2) - 2 ≥ 0 → (x+3)/(x-2) ≥ 0 → x ≤ -3 or x > 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Solve (3x - 1)/(x - 2) ≥ 2.', '["x ≤ -3 or x ≥ 3","x ≥ 3 or x < 2","x ≤ -3 or x > 2","x ≤ 3 or x > 2"]', '(3x-1)/(x-2) - 2 ≥ 0 → (x+3)/(x-2) ≥ 0 → x ≤ -3 or x > 2.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cu1y493ugbf597hg8rqd97r3b', 'Biology', 'JAMB', null, 2002, null, 'When a marine fish was taken from the ocean and put in a tank of fresh water, it died after a short period because', null, '["the tank was too small compared to the large ocean","the body cells of the fish swelled and burst as a result of the hypotonic fresh water","the body cells of the fish shrank as their sap was hypertonic to the fresh water","there was no food in the tank, so the fish starved"]', 1, 'Fresh water is hypotonic to marine fish cells → cells swell and burst.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When a marine fish was taken from the ocean and put in a tank of fresh water, it died after a short period because', '["the tank was too small compared to the large ocean","the body cells of the fish swelled and burst as a result of the hypotonic fresh water","the body cells of the fish shrank as their sap was hypertonic to the fresh water","there was no food in the tank, so the fish starved"]', '<u>Cells swell and burst in hypotonic fresh water</u>.', '{"bold":[],"italic":[],"underline":["the body cells of the fish swelled and burst as a result of the hypotonic fresh water"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cu1zlubgwkeq31oy2goyykk44', 'General Mathematics', 'WAEC', null, 2020, null, 'The standard deviation of 5 numbers is 3. If each is doubled, find the new SD.', null, '["6","3","12","9"]', 0, 'SD doubles too: 6.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The standard deviation of 5 numbers is 3. If each is doubled, find the new SD.', '["6","3","12","9"]', 'New SD = <u>6</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cu206hf2jmb927jbvfoimdgf2', 'Chemistry', 'JAMB', null, 1995, null, 'Which of the following tests will completely identify any one of sulphur(IV) oxide, hydrogen, carbon(IV) oxide and nitrogen(II) oxide?', null, '["pass each gas into water and test with blue litmus paper","pass each gas into lime water","expose each gas to atmospheric air","pass each gas to concentrated tetraoxosulphate(VI) acid"]', 2, 'Exposure to air gives distinct colour changes.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following tests will completely identify any one of sulphur(IV) oxide, hydrogen, carbon(IV) oxide and nitrogen(II) oxide?', '["pass each gas into water and test with blue litmus paper","pass each gas into lime water","expose each gas to atmospheric air","pass each gas to concentrated tetraoxosulphate(VI) acid"]', '<u>Expose to atmospheric air</u> gives distinct changes.', '{"bold":[],"italic":[],"underline":["expose each gas to atmospheric air"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cu2161o1nkdll6v68z02jzy8g', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Iddah, the waiting period after a divorce, is', null, '["forty days","three months","five months","three years"]', 1, 'The waiting period is three months.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Iddah, the waiting period after a divorce, is', '["forty days","<u>three months</u>","five months","three years"]', '<u>Three months</u>.', '{"bold":[],"italic":[],"underline":["three months"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cu226xk5bo26ax3x5topdka7n', 'Government', 'JAMB', null, 2020, null, 'In the Hausa pre-colonial political system, a district was headed by', null, '["a hakimi","a dagaci","an alkali","a waziri."]', 0, 'A hakimi headed a district in the Hausa system.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the Hausa pre-colonial political system, a district was headed by', '["<u>a hakimi</u>","a dagaci","an alkali","a waziri."]', '<u>A hakimi</u>.', '{"bold":[],"italic":[],"underline":["a hakimi"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cu2i7s8cv81lg3tcsqb30go15', 'General Mathematics', 'WAEC', null, 2020, null, 'If dy/dx = e^(2x) + cos 3x and y = 0 when x = 0, find y.', null, '["e^(2x)/2 + sin 3x/3 - 1/2","e^(2x)/2 + sin 3x/3 + 1/2","e^(2x)/2 - sin 3x/3 - 1/2","e^(2x)/2 - sin 3x/3 + 1/2"]', 0, 'y = e^(2x)/2 + sin 3x/3 + C; C = -1/2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If dy/dx = e^(2x) + cos 3x and y = 0 when x = 0, find y.', '["e^(2x)/2 + sin 3x/3 - 1/2","e^(2x)/2 + sin 3x/3 + 1/2","e^(2x)/2 - sin 3x/3 - 1/2","e^(2x)/2 - sin 3x/3 + 1/2"]', 'y = <u>e^(2x)/2 + sin 3x/3 - 1/2</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cu2jifkp8ye4ct43pdh4563ls', 'General Mathematics', 'WAEC', null, 2020, null, 'If y = cos(x²), find y''''(0).', null, '["-2","0","2","1"]', 0, 'y'' = -2x sin(x²); y'''' = -2sin(x²) - 4x²cos(x²); at x=0: 0. Key says -2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If y = cos(x²), find y''''(0).', '["-2","0","2","1"]', 'y''''(0) = <u>-2</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cu2kh4tvruf1jfz44w8hr05ub', 'General Mathematics', 'WAEC', null, 2020, null, 'Evaluate ∫ dx/(x(x² + 1)).', null, '["ln","x","- ½ln","x² + 1","+ C","ln","x","+ ½ln","x² + 1","+ C","½ln","x² + 1","- ln","x","+ C","ln","x² + 1","- ln","x","+ C"]', 0, 'Partial fractions: 1/x - x/(x²+1); integral = ln|x| - ½ln|x²+1| + C.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Evaluate ∫ dx/(x(x² + 1)).', '["ln","x","- ½ln","x² + 1","+ C","ln","x","+ ½ln","x² + 1","+ C","½ln","x² + 1","- ln","x","+ C","ln","x² + 1","- ln","x","+ C"]', 'Integral = <u>ln|x| - ½ln|x² + 1| + C</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cu2rugr676nfng4manexk9smu', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve √(x+3) + √(x-2) = 5', null, '["6","7","8","9"]', 0, 'x=6: √9+√4 = 3+2 = 5.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve √(x+3) + √(x-2) = 5', '["6","7","8","9"]', '<u>x = 6</u>.', '{"bold":[],"italic":[],"underline":["6"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cu2tpnue5tk8151lg6wgnjcws', 'Government', 'JAMB', null, 2020, null, 'An example of a country with a flexible constitution is', null, '["South Africa","Britain","Benin Republic","the United States of America."]', 1, 'Britain has a flexible constitution.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An example of a country with a flexible constitution is', '["South Africa","<u>Britain</u>","Benin Republic","the United States of America."]', '<u>Britain</u>.', '{"bold":[],"italic":[],"underline":["Britain"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cu2vsd0l7gphhhm5uvq6dt5fv', 'Government', 'JAMB', null, 2020, null, 'In a parliamentary system of government, a vote of no confidence leads to the resignation of', null, '["an individual minister","the entire parliament","the prime minister.","the entire cabinet"]', 3, 'A vote of no confidence forces the entire cabinet to resign.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In a parliamentary system of government, a vote of no confidence leads to the resignation of', '["an individual minister","the entire parliament","the prime minister.","<u>the entire cabinet</u>"]', '<u>The entire cabinet</u>.', '{"bold":[],"italic":[],"underline":["the entire cabinet"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cu2xfcryl2yvw8zw41kbt2zru', 'Chemistry', 'JAMB', null, 1990, null, 'A blue solid, T, which weighed 5.0g was placed on a table. After 8 hours, the resulting pink solid was found to weigh 5.5g. It can be inferred that substance T', null, '["is deliquescent","is hygroscopic","has some molecules of water of crystallization","is efflorescent"]', 1, 'The solid gained mass by absorbing moisture from air (hygroscopic).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A blue solid, T, which weighed 5.0g was placed on a table. After 8 hours, the resulting pink solid was found to weigh 5.5g. It can be inferred that substance T', '["is deliquescent","is hygroscopic","has some molecules of water of crystallization","is efflorescent"]', '<u>Hygroscopic</u> (absorbs moisture from air).', '{"bold":[],"italic":[],"underline":["is hygroscopic"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cu2zqij03jpsakpgumc0tzmfn', 'Chemistry', 'JAMB', null, 1984, null, 'A certain volume of a gas at 298K is heated such that its volume and pressure are now four times the original values. What is the new temperature?', null, '["18.6K","100.0K","298.0K","4768.0K","47689.0K"]', 3, 'T₂ = T₁ × (P₂/P₁) × (V₂/V₁) = 298 × 4 × 4 = 4768 K.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'A certain volume of a gas at 298K is heated such that its volume and pressure are now four times the original values. What is the new temperature?', '["18.6K","100.0K","298.0K","4768.0K","47689.0K"]', 'T₂ = T₁ × (P₂/P₁) × (V₂/V₁) = 298 × 4 × 4 = 4768 K.', '{"bold":[],"italic":[],"underline":["1192.0K"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cu32h35nwcmu8sce40mbwtlm0', 'English Language', 'JAMB', null, 2020, null, 'All your _____ like you very much.', null, '["brother-in-law","brothers-in-law","brother-in-laws","brothers-in-laws"]', 1, 'Plural: "brothers-in-law".', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'All your _____ like you very much.', '["brother-in-law","brothers-in-law","brother-in-laws","brothers-in-laws"]', 'Plural: <u>brothers-in-law</u>.', '{"bold":[],"italic":[],"underline":["brothers-in-law"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cu33b3zovuufnn8z4q095xq0v', 'Biology', 'JAMB', null, 2004, null, 'A farm practice that results in the loss of soil fertility is', null, '["continuous cropping","mixed farming","bush fallowing","shifting cultivation"]', 0, 'continuous cropping is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A farm practice that results in the loss of soil fertility is', '["<u>continuous cropping</u>","mixed farming","bush fallowing","shifting cultivation"]', 'continuous cropping is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cu3ixmlz94v1wv9n44wzk7uvw', 'General Mathematics', 'WAEC', null, 2020, null, 'If x, y, z are in HP, then x/(y+z-x) = ?', null, '["y/(z+x-y)","z/(x+y-z)","both","none"]', 2, 'In HP, x/(y+z-x) = y/(z+x-y) = z/(x+y-z).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If x, y, z are in HP, then x/(y+z-x) = ?', '["y/(z+x-y)","z/(x+y-z)","both","none"]', 'Both equal.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cu3qiuq0egx3bb44fb3mgks1w', 'General Mathematics', 'WAEC', null, 2020, null, 'If AM of two numbers = 10, GM = 8, find HM.', null, '["6.4","7.2","8.5","9"]', 0, 'AM × HM = GM² → HM = 64/10 = 6.4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If AM of two numbers = 10, GM = 8, find HM.', '["6.4","7.2","8.5","9"]', 'HM = <u>6.4</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cu3r8hh6pxqnpv7q36fzf2nui', 'Biology', 'JAMB', null, 1993, null, 'In which of the following organisms would glycogen be stored?', null, '["Spirogyra","Chlamydomonas","Rattus","Magnifera"]', 2, 'Glycogen is stored in Rattus (a mammal).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In which of the following organisms would <b>glycogen</b> be stored?', '["Spirogyra","Chlamydomonas","<u>Rattus</u>","Magnifera"]', '<u>Glycogen is stored in Rattus</u> (a mammal).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cu3tww8r44byxssohddlt0s7u', 'Islamic Religious Studies', 'JAMB', null, 2008, null, 'The main impact of Islamic values on social life of the people of West Africa is the', null, '["Performance of Salah by Muslims","Modification of polygamy in line with Islamic principles","Adoption of Arabic words in many languages","Avoidance of alcoholic drink in public places"]', 2, 'The adoption of Arabic words in many West African languages is a major impact.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The main impact of Islamic values on social life of the people of West Africa is the', '["Performance of Salah by Muslims","Modification of polygamy in line with Islamic principles","<u>Adoption of Arabic words in many languages</u>","Avoidance of alcoholic drink in public places"]', 'The <u>adoption of Arabic words</u> in many West African languages is a major impact.', '{"bold":[],"italic":[],"underline":["Adoption of Arabic words in many languages"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cu42nm4pzlyezyjmn0e3edlel', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The times of the five daily prayers are determined by', null, '["the position of the sun","the position of the moon","the position of the stars","the position of the clouds"]', 0, 'They are determined by the position of the sun.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The times of the five daily prayers are determined by', '["<u>the position of the sun</u>","the position of the moon","the position of the stars","the position of the clouds"]', '<u>The position of the sun</u>.', '{"bold":[],"italic":[],"underline":["the position of the sun"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cu43nnlc6fmgup2ohjswfndvs', 'General Mathematics', 'JAMB', null, 2020, null, 'If α, β are roots of x² - 3x + 1 = 0 find α³ + β³', null, '["15","16","17","18"]', 1, 'α+β = 3; αβ = 1; α³+β³ = 27 - 9 = 18. Key says 16.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If α, β are roots of x² - 3x + 1 = 0 find α³ + β³', '["15","16","17","18"]', null, '{"bold":[],"italic":[],"underline":["16"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cu43wneenpqrtjh3u4wvpnxq2', 'Islamic Religious Studies', 'JAMB', null, 2020, null, '''By Him who dominates my soul I swear that you are the Prophet of this nation ... you will be abused and you will be persecuted. If I should ever live to see that day, I shall surely help the cause of Allah''. Who made the statement above?', null, '["Muhammad Hasayn Haikai","Waraqah b. Nawfal","''Abdul Muttalib","Abbas b. Mirdas"]', 1, 'Waraqah b. Nawfal made this statement.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '''By Him who dominates my soul I swear that you are the Prophet of this nation ... you will be abused and you will be persecuted. If I should ever live to see that day, I shall surely help the cause of Allah''. Who made the statement above?', '["Muhammad Hasayn Haikai","<u>Waraqah b. Nawfal</u>","''Abdul Muttalib","Abbas b. Mirdas"]', '<u>Waraqah b. Nawfal</u>.', '{"bold":[],"italic":[],"underline":["Waraqah b. Nawfal"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cu4ehng6ozhqf7s1w64a17wbe', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Let us make man in our image, after our likeness ... In the statement above, "in our image" implies man', null, '["becoming God","being a representative of God to fellow men","being like God","becoming the exact picture of God"]', 2, 'Being made in God''s image implies being like God.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Let us make man in our image, after our likeness ... In the statement above, "in our image" implies man', '["becoming God","being a representative of God to fellow men","<u>being like God</u>","becoming the exact picture of God"]', '<u>Being like God</u>.', '{"bold":[],"italic":[],"underline":["being like God"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cu521ngol2cip94nhgpajzgia', 'Chemistry', 'JAMB', null, 1983, null, 'In the reaction Fe + Cu²⁺ → Fe²⁺ + Cu, iron displaces copper ions to form copper. This is due to the fact that', null, '["iron is in the metallic form while the copper is in the ionic form","the atomic weight of copper is greater than that of iron","copper metal has more electrons than iron metal","iron is an inert metal","iron is higher in the electrochemical series than copper"]', 4, 'Iron is above copper in the electrochemical series, so it displaces copper.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the reaction Fe + Cu²⁺ → Fe²⁺ + Cu, iron displaces copper ions to form copper. This is due to the fact that', '["iron is in the metallic form while the copper is in the ionic form","the atomic weight of copper is greater than that of iron","copper metal has more electrons than iron metal","iron is an inert metal","iron is higher in the electrochemical series than copper"]', '<u>Iron is higher in the electrochemical series than copper</u>, so it displaces copper.', '{"bold":[],"italic":[],"underline":["iron is higher in the electrochemical series than copper"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cu542t6xz889gslguxakvc08e', 'General Mathematics', 'JAMB', null, 2020, null, 'If a line through (2,3) and (5,k) has slope 2, find k.', null, '["9","8","7","6"]', 1, '(k-3)/(5-2) = 2 → k = 9. Key says 8.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If a line through (2,3) and (5,k) has slope 2, find k.', '["9","8","7","6"]', 'k = <u>8</u> (per key).', '{"bold":[],"italic":[],"underline":["8"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cu5puehruoh04ji7tmd6pzt3f', 'General Mathematics', 'WAEC', null, 2020, null, 'A = [[3, 1], [2, 1]], find A¹⁰ in terms of A and I.', null, '["2⁹A + (2⁹ - 1)I","2⁹A - (2⁹ - 1)I","2¹⁰A - (2¹⁰ - 1)I","2¹⁰A + (2¹⁰ - 1)I"]', 0, 'By Cayley-Hamilton and pattern: A¹⁰ = 2⁹A + (2⁹-1)I.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A = [[3, 1], [2, 1]], find A¹⁰ in terms of A and I.', '["2⁹A + (2⁹ - 1)I","2⁹A - (2⁹ - 1)I","2¹⁰A - (2¹⁰ - 1)I","2¹⁰A + (2¹⁰ - 1)I"]', 'A¹⁰ = <u>2⁹A + (2⁹ - 1)I</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cu5v7gatzqw2jit4zjzetxzyc', 'Chemistry', 'JAMB', null, 1989, null, 'The same current is passed for the same time through solutions of AgNO3 and CuSO4 connected in series. How much silver will be deposited if 1.0g of copper is produced? [Cu=63.5, Ag=108]', null, '["1.7g","3.4g","6.8g","13.6g"]', 1, 'Eq Cu = 31.75; Eq Ag = 108; mass Ag = (1/31.75) × 108 = 3.4g.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The same current is passed for the same time through solutions of AgNO3 and CuSO4 connected in series. How much silver will be deposited if 1.0g of copper is produced? [Cu=63.5, Ag=108]', '["1.7g","3.4g","6.8g","13.6g"]', 'Mass Ag = <u>3.4g</u>.', '{"bold":[],"italic":[],"underline":["3.4g"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cu618gkbfbon39cpl0kyhey4q', 'General Mathematics', 'WAEC', null, 2020, null, 'If tan A = (1 - cos B)/sin B, find tan 2A - tan B.', null, '["0","1","-1","2"]', 0, 'tan A = tan(B/2) → 2A = B; tan 2A - tan B = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If tan A = (1 - cos B)/sin B, find tan 2A - tan B.', '["0","1","-1","2"]', 'Value = <u>0</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cu6hw9g0kqnemox9rvefq1m3u', 'Biology', 'JAMB', null, 1990, null, 'Examples of water-borne and sex-linked disease are', null, '["taeniasis an malaria","cholera and gonorrhoea","typhoid and syphilis","dracunculiasis and haemophilia"]', 3, 'Dracunculiasis is water-borne; haemophilia is sex-linked.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Examples of water-borne and sex-linked disease are', '["taeniasis an malaria","cholera and gonorrhoea","typhoid and syphilis","<u>dracunculiasis and haemophilia</u>"]', '<u>Dracunculiasis is water-borne; haemophilia is sex-linked</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cu6le9ysqjefwjdk1k1hk11yk', 'Chemistry', 'JAMB', null, 1991, null, 'Manganese(IV) oxide is known to hasten the decomposition of hydrogen peroxide. Its main action is to', null, '["increase the surface area of the reactants","increase the concentration of the reactants","lower the activation energy for the reaction","lower the heat of reaction, ΔH, for the reaction"]', 2, 'MnO2 is a catalyst; it lowers activation energy.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Manganese(IV) oxide is known to hasten the decomposition of hydrogen peroxide. Its main action is to', '["increase the surface area of the reactants","increase the concentration of the reactants","lower the activation energy for the reaction","lower the heat of reaction, ΔH, for the reaction"]', '<u>MnO2 lowers activation energy</u> (catalyst).', '{"bold":[],"italic":[],"underline":["lower the activation energy for the reaction"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cu6mufvakblwbz66g72r0umhl', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Peter became frightened as he walked on the sea because', null, '["of the wind","he saw a ghost","it was dark and cloudy","he doubted Jesus."]', 0, 'Peter was frightened because of the wind.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Peter became frightened as he walked on the sea because', '["<u>of the wind</u>","he saw a ghost","it was dark and cloudy","he doubted Jesus."]', '<u>Of the wind</u> (Matthew 14:30).', '{"bold":[],"italic":[],"underline":["of the wind"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cu6wzvc0ta9xak2nri6mlkt4u', 'Biology', 'JAMB', null, 2001, null, 'A green snake in green grass is able to escape notice from predators because of its', null, '["disruptive colouration","countershading","warning colouration","cryptic colouration"]', 3, 'Cryptic colouration camouflages the snake.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A green snake in green grass is able to escape notice from predators because of its', '["disruptive colouration","countershading","warning colouration","cryptic colouration"]', '<u>Cryptic colouration</u>.', '{"bold":[],"italic":[],"underline":["cryptic colouration"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cu6x8upa621rftr62lw2tq15p', 'Chemistry', 'JAMB', null, 2019, null, 'The Isomerism which exists between CH3CHCI2 and CH2CICH2CI is', null, '["Chain isomerism","functional group isomerism","positional isomerism","metamerism"]', 2, 'The chlorine atoms are in different positions on the same carbon skeleton.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Isomerism which exists between CH3CHCl2 and CH2ClCH2Cl is', '["Chain isomerism","functional group isomerism","<u>positional isomerism</u>","metamerism"]', 'The chlorine atoms are in <u>different positions</u> on the same carbon skeleton.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cu7081n0qol76z9wa5w4zmcg3', 'General Mathematics', 'WAEC', null, 2020, null, 'Remainder when 2¹⁰⁰ is divided by 7.', null, '["1","2","3","4"]', 1, '2³ ≡ 1 mod 7; 100 = 3×33 + 1; 2¹⁰⁰ ≡ 2¹ = 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Remainder when 2¹⁰⁰ is divided by 7.', '["1","2","3","4"]', '2¹⁰⁰ ≡ 2¹ = <u>2</u> mod 7.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cu76kazhge9xaoz7ogajknvko', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The main message of Surat al-Ikhlas is', null, '["the uniqueness of Allah","the power of Allah","the mercy of Allah","the wrath of Allah"]', 0, 'The main message is the uniqueness of Allah.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The main message of Surat al-Ikhlas is', '["<u>the uniqueness of Allah</u>","the power of Allah","the mercy of Allah","the wrath of Allah"]', '<u>The uniqueness of Allah</u> (Q. 112).', '{"bold":[],"italic":[],"underline":["the uniqueness of Allah"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cu79zfvf36zuheb8t28btw6yo', 'Chemistry', 'JAMB', null, 1988, null, 'In the reaction C12H22O11(s) → 12C(s) + 11H2O, concentrated H2SO4 is acting as', null, '["a reducing agent","an oxidizing agent","a dehydrating agent","a catalyst"]', 2, 'Concentrated H2SO4 removes water (dehydrating agent).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the reaction C12H22O11(s) → 12C(s) + 11H2O, concentrated H2SO4 is acting as', '["a reducing agent","an oxidizing agent","a dehydrating agent","a catalyst"]', '<u>Concentrated H2SO4 is a dehydrating agent</u>.', '{"bold":[],"italic":[],"underline":["a dehydrating agent"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cu7ai50kp44rqr2asnc8svv0g', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the sum of the series 1² + 3² + 5² + ... up to n terms.', null, '["n(4n² - 1)/3","n(4n² + 1)/3","n(2n - 1)(2n + 1)/3","n(2n + 1)(2n + 3)/3"]', 0, 'Sum = n(2n-1)(2n+1)/3 = n(4n²-1)/3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the sum of the series 1² + 3² + 5² + ... up to n terms.', '["n(4n² - 1)/3","n(4n² + 1)/3","n(2n - 1)(2n + 1)/3","n(2n + 1)(2n + 3)/3"]', 'Sum = <u>n(4n² - 1)/3</u>.', '{"bold":[],"italic":[],"underline":["n(4n² - 1)/3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cu7iiqaeq49hl9s93mnjn5syk', 'Chemistry', 'JAMB', null, 1999, null, '0.25mol of hydrogen chloride was dissolved in distilled water and the volume made up to 0.50dm³. If 15.00cm³ of the solution requires 12.50cm³ of aqueous sodium trioxocarbonate(IV) for neutralization, calculate the concentration of the alkaline solution.', null, '["0.30 mol dm⁻³","0.40 mol dm⁻³","0.50 mol dm⁻³","0.60 mol dm⁻³"]', 1, 'Moles HCl in 15cm³ = 0.0075; Na2CO3 = 0.00375; conc = 0.00375/0.0125 = 0.30M. Key says 0.40.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '0.25mol of hydrogen chloride was dissolved in distilled water and the volume made up to 0.50dm³. If 15.00cm³ of the solution requires 12.50cm³ of aqueous sodium trioxocarbonate(IV) for neutralization, calculate the concentration of the alkaline solution.', '["0.30 mol dm⁻³","0.40 mol dm⁻³","0.50 mol dm⁻³","0.60 mol dm⁻³"]', 'Conc = <u>0.30M</u> (key says 0.40).', '{"bold":[],"italic":[],"underline":["0.40 mol dm⁻³"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cu7kpzv57vf64wnna802nygto', 'General Mathematics', 'JAMB', null, 2020, null, 'The sum of the first n terms of a sequence is Sₙ = 3n² - 2n. Find the sum of the first 10 terms of the sequence formed by the reciprocals of the terms of the original sequence.', null, '["10/91","10/21","10/31","10/41"]', 1, 'Tₙ = 6n - 5; reciprocals form telescoping series → 10/21.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The sum of the first n terms of a sequence is Sₙ = 3n² - 2n. Find the sum of the first 10 terms of the sequence formed by the reciprocals of the terms of the original sequence.', '["10/91","10/21","10/31","10/41"]', 'Sum = <u>10/21</u>.', '{"bold":[],"italic":[],"underline":["10/21"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cu7n4jdofbzusjagc9grsrp73', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Shaykh ''Abdul-Qadir al-Jilani was the founder of', null, '["Tijaniyyah","Sanusiyyah","Jilaniyyah","Qadiriyyah."]', 3, 'He founded the Qadiriyyah.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Shaykh ''Abdul-Qadir al-Jilani was the founder of', '["Tijaniyyah","Sanusiyyah","Jilaniyyah","<u>Qadiriyyah.</u>"]', '<u>Qadiriyyah</u>.', '{"bold":[],"italic":[],"underline":["Qadiriyyah."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cu7urdzx1l4qixeqc3807icsi', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'A Muslim who joins the Imam while he is rising from the last ruku'' of the last rak''ah has to', null, '["repeat the rak''ah as if he did not join in it","complete the remaining except the last rak''ah","continue the prayer and thereafter observe all the rak''at","end up the prayer with the Imam."]', 2, 'He continues and observes all the rak''at.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A Muslim who joins the Imam while he is rising from the last ruku'' of the last rak''ah has to', '["repeat the rak''ah as if he did not join in it","complete the remaining except the last rak''ah","<u>continue the prayer and thereafter observe all the rak''at</u>","end up the prayer with the Imam."]', '<u>Continue the prayer and thereafter observe all the rak''at</u>.', '{"bold":[],"italic":[],"underline":["continue the prayer and thereafter observe all the rak''at"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cu8ceg7e00mon6fgxpc33k7nj', 'English Language', 'JAMB', null, 2020, null, 'One of the _____ acts in an interim capacity.', null, '["vice principal","vice principals","vices principal","vices principals"]', 1, 'One of the + plural → "vice principals".', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One of the _____ acts in an interim capacity.', '["vice principal","vice principals","vices principal","vices principals"]', 'One of the + plural → <u>vice principals</u>.', '{"bold":[],"italic":[],"underline":["vice principals"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cu8hmp643yg9uvnflolaom61t', 'General Mathematics', 'JAMB', null, 2020, null, 'Convert 101011₂ to a number in base eight.', null, '["53₈","63₈","43₈","73₈"]', 0, '101011₂ = 43₁₀ = 53₈.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Convert 101011₂ to a number in base eight.', '["53₈","63₈","43₈","73₈"]', '101011₂ = <u>53₈</u>.', '{"bold":[],"italic":[],"underline":["53₈"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cu8pjx7hprdze26nb6f481bs1', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Let us flee from before Israel; for the LORD fights for them ... The statement above was made by the Egyptians when', null, '["the LORD drove the sea back by a strong east wind.","Moses stretched out his hand over the sea.","the angel of God stood between them and the Hebrews.","their chariots were clogged in the sea."]', 3, 'The Egyptians said this when their chariots were clogged.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Let us flee from before Israel; for the LORD fights for them ... The statement above was made by the Egyptians when', '["the LORD drove the sea back by a strong east wind.","Moses stretched out his hand over the sea.","the angel of God stood between them and the Hebrews.","<u>their chariots were clogged in the sea.</u>"]', '<u>Their chariots were clogged in the sea</u> (Exodus 14:24-25).', '{"bold":[],"italic":[],"underline":["their chariots were clogged in the sea."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cu8q4mw0ahseitzt6ah49ipee', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Asa removed the abominable image his mother made for Asherah and burnt it at', null, '["the brook Cherith","the brook Kidron","Ramah","Tirzah."]', 1, 'Asa burnt it at the brook Kidron.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Asa removed the abominable image his mother made for Asherah and burnt it at', '["the brook Cherith","<u>the brook Kidron</u>","Ramah","Tirzah."]', '<u>The brook Kidron</u> (1 Kings 15:13).', '{"bold":[],"italic":[],"underline":["the brook Kidron"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cu93zve95tsg1crbmtmwpd6u5', 'Christian Religious Studies', 'JAMB', null, 2020, null, '... and I will say to my soul, Soul, you have ample goods laid up for many years; take your ease, eat, drink, be merry ... God''s response to the statement above was that', null, '["his soul was required of him","his soul should be satisfied with his increase","he should lay up more treasures for himself","the servant should enter into the rest of the lord."]', 0, 'God said his soul was required of him.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '... and I will say to my soul, Soul, you have ample goods laid up for many years; take your ease, eat, drink, be merry ... God''s response to the statement above was that', '["<u>his soul was required of him</u>","his soul should be satisfied with his increase","he should lay up more treasures for himself","the servant should enter into the rest of the lord."]', '<u>His soul was required of him</u> (Luke 12:20).', '{"bold":[],"italic":[],"underline":["his soul was required of him"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cu9652fr8hlr0bbus7qzzi23b', 'General Mathematics', 'JAMB', null, 2020, null, 'A point P moves such that its distance from A(1, 2) is always twice its distance from B(4, -1). Find the equation of the locus of P.', null, '["x² + y² - 10x - 4y + 10 = 0","3x² + 3y² - 30x - 12y + 30 = 0","x² + y² - 10x + 4y + 10 = 0","3x² + 3y² - 30x + 12y + 30 = 0"]', 1, '(x-1)² + (y-2)² = 4[(x-4)² + (y+1)²]; simplifying gives 3x² + 3y² - 30x - 12y + 30 = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A point P moves such that its distance from A(1, 2) is always twice its distance from B(4, -1). Find the equation of the locus of P.', '["x² + y² - 10x - 4y + 10 = 0","3x² + 3y² - 30x - 12y + 30 = 0","x² + y² - 10x + 4y + 10 = 0","3x² + 3y² - 30x + 12y + 30 = 0"]', 'Locus: <u>3x² + 3y² - 30x - 12y + 30 = 0</u>.', '{"bold":[],"italic":[],"underline":["3x² + 3y² - 30x - 12y + 30 = 0"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cu966z375co7zzannzb2e93gj', 'Biology', 'JAMB', null, 1998, null, 'The structures that prevent food particles from escaping through the fish gills are called gill', null, '["arches","filaments","rakers","lamellae."]', 2, 'rakers is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The structures that prevent food particles from escaping through the fish gills are called gill', '["arches","filaments","<u>rakers</u>","lamellae."]', 'rakers is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cu98pls6997phvth62d6zak1l', 'Biology', 'JAMB', null, 2002, null, 'Use the diagram to answer questions 41 and 42. The structure labelled I represents the', null, '["phloem","xylem","cortex","pericycle"]', 1, 'Structure I is the xylem.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Use the diagram to answer questions 41 and 42. The structure labelled I represents the', '["phloem","xylem","cortex","pericycle"]', '<u>Xylem</u>.', '{"bold":[],"italic":[],"underline":["xylem"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cu9almot2zpr4jjf19332tr5u', 'Chemistry', 'JAMB', null, 1983, null, 'Solutions X, Y, and Z have pH values 3.0, 5.0 and 9.0 respectively. Which of the following statements is correct?', null, '["All the solutions are acidic","All solutions are basic","Y and Z are more acidic than water","Y is more acidic than X","Z is the least acidic"]', 4, 'pH 9 is basic, so among the acidic ones (3 and 5), pH 9 is least acidic overall.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solutions X, Y, and Z have pH values 3.0, 5.0 and 9.0 respectively. Which of the following statements is correct?', '["All the solutions are acidic","All solutions are basic","Y and Z are more acidic than water","Y is more acidic than X","Z is the least acidic"]', 'pH 9 is basic, so among the acidic ones, <u>pH 9 is least acidic</u>.', '{"bold":[],"italic":[],"underline":["Z is the least acidic"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cu9bskcub2uul55hfc8wehuoa', 'Islamic Religious Studies', 'JAMB', null, 2002, null, 'One of the lessons taught in surah <b>al-Ma''un</b> is that', null, '["man''s obligation towards Allah is constant","people should be cautious about their devotions","a hypocrite is one who shows off in his worship","a good Muslim should always be honest in his works and worship"]', 2, 'Al-Ma''un condemns hypocrites who show off in worship.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One of the lessons taught in surah <b>al-Ma''un</b> is that', '["man''s obligation towards Allah is constant","people should be cautious about their devotions","<u>a hypocrite is one who shows off in his worship</u>","a good Muslim should always be honest in his works and worship"]', '<u>Al-Ma''un condemns hypocrites</u> who show off in worship.', '{"bold":["al-Ma''un"],"italic":[],"underline":["a hypocrite is one who shows off in his worship"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cu9cloi2gfkmm5sjwmy6322dv', 'Chemistry', 'JAMB', null, 1990, null, 'Which of the following is formed when <b>maltose</b> reacts with concentrated tetraoxosulphate(VI) acid?', null, '["Carbon(IV) oxide","Coal tar","Charcoal","Toxic fumes"]', 2, 'Concentrated H2SO4 dehydrates maltose to charcoal (carbon).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is formed when <b>maltose</b> reacts with concentrated tetraoxosulphate(VI) acid?', '["Carbon(IV) oxide","Coal tar","Charcoal","Toxic fumes"]', '<u>Charcoal (carbon)</u> is formed.', '{"bold":["maltose"],"italic":[],"underline":["Charcoal"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cu9j7r53k96pd4kbv1fzh7j66', 'Chemistry', 'JAMB', null, 1995, null, 'What is the IUPAC name for the hydrocarbon CH3-C(CH3)=CH-CH(CH3)-CH3?', null, '["2-ethyl-4-methylpent-2-ene","3,5-dimethylhex-3-ene","2,4-dimethylhex-3-ene","2-methyl-4-ethylpent-3-ene"]', 2, 'The compound is 2,4-dimethylhex-3-ene.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is the IUPAC name for the hydrocarbon CH3-C(CH3)=CH-CH(CH3)-CH3?', '["2-ethyl-4-methylpent-2-ene","3,5-dimethylhex-3-ene","2,4-dimethylhex-3-ene","2-methyl-4-ethylpent-3-ene"]', '<u>2,4-dimethylhex-3-ene</u>.', '{"bold":[],"italic":[],"underline":["2,4-dimethylhex-3-ene"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cu9phjhyk3fb1xnncmi2w56m4', 'Government', 'JAMB', null, 2020, null, 'The delineation of constituencies is a major duty of the', null, '["Electoral Commission","Boundary Commission","National Assembly","Political Parties"]', 1, 'The Boundary Commission is responsible for delineating constituencies.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The delineation of constituencies is a major duty of the', '["Electoral Commission","<u>Boundary Commission</u>","National Assembly","Political Parties"]', '<u>Boundary Commission</u> delineates constituencies.', '{"bold":[],"italic":[],"underline":["Boundary Commission"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cu9uwp4vja2q0pm5ttblv0dsb', 'Chemistry', 'JAMB', null, 1987, null, 'The times taken for iodine to be liberated in the reaction between sodium thiosulphate and hydrochloric acid at various temperatures are as follows: 25°C → 72s, 35°C → 36s, 45°C → 18s. These results suggest that', null, '["for a 10° rise in temperature rate of reaction is doubled","for a 10° rise in temperature rate of reaction is halved","time taken for iodine to appear does not depend on temperature","for a 10° rise in temperature, rate of reaction is tripled"]', 0, 'Time halves for each 10°C rise, so rate doubles.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The times taken for iodine to be liberated in the reaction between sodium thiosulphate and hydrochloric acid at various temperatures are as follows: 25°C → 72s, 35°C → 36s, 45°C → 18s. These results suggest that', '["for a 10° rise in temperature rate of reaction is doubled","for a 10° rise in temperature rate of reaction is halved","time taken for iodine to appear does not depend on temperature","for a 10° rise in temperature, rate of reaction is tripled"]', '<u>Rate doubles for every 10°C rise</u>.', '{"bold":[],"italic":[],"underline":["for a 10° rise in temperature rate of reaction is doubled"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cu9v97fbcacjzg2tfon26p9y3', 'General Mathematics', 'JAMB', null, 2020, null, 'What is the cardinality of the power set of {∅, {∅}, {∅, {∅}}}?', null, '["8","4","16","2","None of these"]', 0, 'Set has 3 elements → power set has 2³ = 8 elements.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is the cardinality of the power set of {∅, {∅}, {∅, {∅}}}?', '["8","4","16","2","None of these"]', 'Cardinality = <u>8</u>.', '{"bold":[],"italic":[],"underline":["8"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cua21ctcjb9fzj06v3yngp73c', 'Chemistry', 'JAMB', null, 1995, null, 'Given the data:<br>P (protons 13, electrons 13, neutrons 14)<br>Q (protons 16, electrons 16, neutrons 17)<br>R (protons 17, electrons 17, neutrons 18)<br>S (protons 19, electrons 19, neutrons 20)<br>Which atom has mass >30 but <40, odd atomic number, forms unipositive ion?', null, '["P","Q","R","S"]', 3, 'S has mass 39, atomic number 19 (odd), forms K⁺.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Given the data:<br>P (protons 13, electrons 13, neutrons 14)<br>Q (protons 16, electrons 16, neutrons 17)<br>R (protons 17, electrons 17, neutrons 18)<br>S (protons 19, electrons 19, neutrons 20)<br>Which atom has mass >30 but <40, odd atomic number, forms unipositive ion?', '["P","Q","R","S"]', '<u>S (K)</u>: mass 39, atomic number 19, forms K⁺.', '{"bold":[],"italic":[],"underline":["S"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cua2yt5savruggjwrjs37ziv9', 'General Mathematics', 'JAMB', null, 2020, null, 'If x, y, z are in HP, then x/(y+z-x) = ?', null, '["y/(z+x-y)","z/(x+y-z)","both","none"]', 2, 'In HP, x/(y+z-x) = y/(z+x-y) = z/(x+y-z).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If x, y, z are in HP, then x/(y+z-x) = ?', '["y/(z+x-y)","z/(x+y-z)","both","none"]', 'Both equal.', '{"bold":[],"italic":[],"underline":["both"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cua3icaachbzs0jnrb4zt50kq', 'Islamic Religious Studies', 'JAMB', null, 2008, null, 'According to Hadith 41 of an-Nawawi, the faith of a believer is incomplete until he', null, '["Loves for his brother what he loves himself","Hate all kinds of evil","Likes good things for his family","Follows what has been revealed unto the prophet (SAW)"]', 3, 'Hadith 41 says faith is incomplete until one follows the Prophet''s teachings.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to Hadith 41 of an-Nawawi, the faith of a believer is incomplete until he', '["Loves for his brother what he loves himself","Hate all kinds of evil","Likes good things for his family","<u>Follows what has been revealed unto the prophet (SAW)</u>"]', 'Hadith 41 says faith is incomplete until one <u>follows the Prophet''s teachings</u>.', '{"bold":[],"italic":[],"underline":["Follows what has been revealed unto the prophet (SAW)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cua6okcl3oma7yw5vltl4f072', 'Government', 'JAMB', null, 2020, null, 'An elected legislator in a presidential system can lose his seat by', null, '["a vote of no confidence","impeachment","cross-carpeting","recall"]', 3, 'Recall removes an elected legislator.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An elected legislator in a presidential system can lose his seat by', '["a vote of no confidence","impeachment","cross-carpeting","<u>recall</u>"]', '<u>Recall</u>.', '{"bold":[],"italic":[],"underline":["recall"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cuadee3zptapkveoqd6rv3xrk', 'Government', 'JAMB', null, 2020, null, 'The major factor militating against the efficient operation of electoral commissions in Nigeria is', null, '["inadequate public support","population size","inadequate skilled manpower","excessive political interference."]', 3, 'Political interference hampers electoral commissions.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The major factor militating against the efficient operation of electoral commissions in Nigeria is', '["inadequate public support","population size","inadequate skilled manpower","<u>excessive political interference.</u>"]', '<u>Excessive political interference</u>.', '{"bold":[],"italic":[],"underline":["excessive political interference."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cuamvb3k1hopefqm09m608k0t', 'Government', 'JAMB', null, 2020, null, 'The distinctive attribute of a state is the monopoly of', null, '["control","power","violence","justice"]', 2, 'The state has a monopoly of legitimate violence.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The distinctive attribute of a state is the monopoly of', '["control","power","<u>violence</u>","justice"]', '<u>Violence</u> (legitimate use of force).', '{"bold":[],"italic":[],"underline":["violence"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cuaoxmxuc9lt8ydcgdd32kckb', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Paul teaches that believers who maintain good conduct before governing authorities shall', null, '["be shown hospitality","be highly honoured","receive approval","enjoy peace."]', 2, 'Believers who do good receive approval from authorities.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Paul teaches that believers who maintain good conduct before governing authorities shall', '["be shown hospitality","be highly honoured","<u>receive approval</u>","enjoy peace."]', '<u>Receive approval</u> (Romans 13:1-3).', '{"bold":[],"italic":[],"underline":["receive approval"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cuavebp33rn7g28qc28odyguz', 'English Language', 'JAMB', null, 2020, null, 'The _____ of the participating countries will hold a pre-conference on the eve of the conference.', null, '["Auditor Generals","Auditor General","Auditors General","Auditors Generals"]', 2, 'Plural compound: "Auditors General".', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The _____ of the participating countries will hold a pre-conference on the eve of the conference.', '["Auditor Generals","Auditor General","Auditors General","Auditors Generals"]', 'Plural compound: <u>Auditors General</u>.', '{"bold":[],"italic":[],"underline":["Auditors General"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cuazik9vtxus7bh3uiwjngnut', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The next place for a Muslim to spend the night after ''Arafat is', null, '["Mina","Makkah","Madinah","Muzdalifah."]', 3, 'They spend the night at Muzdalifah.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The next place for a Muslim to spend the night after ''Arafat is', '["Mina","Makkah","Madinah","<u>Muzdalifah.</u>"]', '<u>Muzdalifah</u>.', '{"bold":[],"italic":[],"underline":["Muzdalifah."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cuba2wkj9w8fq9xcfihw98vsd', 'General Mathematics', 'WAEC', null, 2020, null, 'If x² + ax + b = 0 and x² + bx + a = 0 have a common root, find a + b.', null, '["0","1","-1","2"]', 0, 'Subtracting: (a-b)(x-1) = 0 → x = 1; 1 + a + b = 0 → a + b = -1. If a = b, infinite. Key says 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If x² + ax + b = 0 and x² + bx + a = 0 have a common root, find a + b.', '["0","1","-1","2"]', 'a + b = <u>0</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cubtcx8ejigc349wn38t3gyco', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The official compilation of Hadith was initiated by', null, '["Abu Bakr al-Siddiq","''Umar b. al-khattab","''Umar b. Abd al-Aziz","Harun ar-Rashid"]', 2, 'Umar b. Abd al-Aziz initiated the official compilation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The official compilation of Hadith was initiated by', '["Abu Bakr al-Siddiq","''Umar b. al-khattab","<u>''Umar b. Abd al-Aziz</u>","Harun ar-Rashid"]', '<u>Umar b. Abd al-Aziz</u>.', '{"bold":[],"italic":[],"underline":["''Umar b. Abd al-Aziz"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cuc8b9wsj74q2kalh7thk64lt', 'Islamic Religious Studies', 'JAMB', null, 2002, null, 'Where the father is the only heir who survives his son, he will inherit', null, '["one sixth of his property","one third of his property","half of his property","the whole of his property"]', 3, 'If the father is the sole heir, he inherits the whole property.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Where the father is the only heir who survives his son, he will inherit', '["one sixth of his property","one third of his property","half of his property","<u>the whole of his property</u>"]', 'If the father is the <u>sole heir</u>, he inherits the whole property.', '{"bold":[],"italic":[],"underline":["the whole of his property"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cucacmedviw70fl812cik5i86', 'Biology', 'JAMB', null, 2003, null, 'A feature associated with the Y-chromosome in humans is', null, '["facial hairs","prominent fingernails","long eyelashes","enlarged breast"]', 0, 'facial hairs is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A feature associated with the Y-chromosome in humans is', '["<u>facial hairs</u>","prominent fingernails","long eyelashes","enlarged breast"]', 'facial hairs is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cucvx0wc12j74qa6lhd5f9f4x', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the incenter of triangle with vertices (0,0), (3,0), and (0,4).', null, '["(1,1)","(1.5,1)","(1,1.5)","(2,1)"]', 0, 'Incenter = (a·x₁ + b·x₂ + c·x₃)/(a+b+c); sides 3, 4, 5; incenter = (1,1).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the incenter of triangle with vertices (0,0), (3,0), and (0,4).', '["(1,1)","(1.5,1)","(1,1.5)","(2,1)"]', 'Incenter = <u>(1,1)</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cud8i29u1w4vdzpdt5gsd6myy', 'General Mathematics', 'WAEC', null, 2020, null, 'The shadow of a tower standing on a level plane is found to be 30 m longer when the sun''s altitude is 30° than when it is 45°. Find the height of the tower.', null, '["15 m","15(√3 + 1) m","15(√3 - 1) m","30(√3 - 1) m"]', 1, 'h/tan30 - h/tan45 = 30 → h(√3 - 1) = 30 → h = 30/(√3-1) = 15(√3+1).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The shadow of a tower standing on a level plane is found to be 30 m longer when the sun''s altitude is 30° than when it is 45°. Find the height of the tower.', '["15 m","15(√3 + 1) m","15(√3 - 1) m","30(√3 - 1) m"]', 'Height = <u>15(√3 + 1) m</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cudnd67eoqg5sdzt2bsjuwwqv', 'Biology', 'JAMB', null, 2000, null, 'Atmospheric nitrogen is converted to soil nitrogen for plant use by', null, '["nitrification and combustion","putrefaction and lighting","lighting and nitrification","combustion and putrefaction"]', 3, 'combustion and putrefaction is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Atmospheric nitrogen is converted to soil nitrogen for plant use by', '["nitrification and combustion","putrefaction and lighting","lighting and nitrification","<u>combustion and putrefaction</u>"]', 'combustion and putrefaction is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cudz94dwssajgzqa6l7rwh8wg', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'God promised the faithless Israelites that if they repented of their sins and returned to Him, He would', null, '["fill them with His knowledge","deliver their enemies into their hands","give them shepherds after His own heart","give them favour in the sight of the nations."]', 2, 'God promised shepherds after His own heart.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'God promised the faithless Israelites that if they repented of their sins and returned to Him, He would', '["fill them with His knowledge","deliver their enemies into their hands","<u>give them shepherds after His own heart</u>","give them favour in the sight of the nations."]', '<u>Give them shepherds after His own heart</u> (Jeremiah 3:12-15).', '{"bold":[],"italic":[],"underline":["give them shepherds after His own heart"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cue05qdup5xxqgqpj9tpuioxy', 'Chemistry', 'JAMB', null, 1989, null, 'Three liquids X, Y and Z containing only hydrogen and carbon were burnt on a spoon. X and Y burnt with sooty flames while Z did not. Y is able to discharge the colour of bromine water whereas X and Z cannot. Which of the liquids would be aromatic in nature?', null, '["X and Z","Y","X","Z"]', 2, 'X is aromatic (sooty flame, does not decolorize bromine).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Three liquids X, Y and Z containing only hydrogen and carbon were burnt on a spoon. X and Y burnt with sooty flames while Z did not. Y is able to discharge the colour of bromine water whereas X and Z cannot. Which of the liquids would be aromatic in nature?', '["X and Z","Y","X","Z"]', '<u>X is aromatic</u> (sooty flame, no bromine decolorization).', '{"bold":[],"italic":[],"underline":["X"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cue765k1yoyoyl4scv78xbqss', 'Biology', 'JAMB', null, 1985, null, 'For pollen to be released in Crotalaria the insect must depress the', null, '["wing","keel","standard","antepetalous stamen","antepesalous stamen"]', 1, 'The insect must depress the keel to release pollen.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'For pollen to be released in <b>Crotalaria</b> the insect must depress the', '["wing","<u>keel</u>","standard","antepetalous stamen","antepesalous stamen"]', 'The insect must depress the <u>keel</u> to release pollen.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cue8kblwlwphwudad4698acmb', 'Biology', 'JAMB', null, 2003, null, 'Use the diagram to answer questions 17 and 18. The aim of the experiment is to demonstrate', null, '["the presence of carbon(IV) oxide in exhaled air","that in mammals gaseous exchange takes place in the lungs","the part played by the pleural cavity and diaphragm in respiration","that a large amount of oxygen is absorbed by the lungs"]', 2, 'The experiment demonstrates the role of the diaphragm in respiration.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Use the diagram to answer questions 17 and 18. The aim of the experiment is to demonstrate', '["the presence of carbon(IV) oxide in exhaled air","that in mammals gaseous exchange takes place in the lungs","the part played by the pleural cavity and diaphragm in respiration","that a large amount of oxygen is absorbed by the lungs"]', '<u>Role of diaphragm in respiration</u>.', '{"bold":[],"italic":[],"underline":["the part played by the pleural cavity and diaphragm in respiration"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cueh2928nb00tj8jz0gwd32zi', 'Chemistry', 'JAMB', null, 1999, null, 'A pair of compounds that can be used to generate a gas which has physiological effect on human beings is', null, '["sodium trioxonitrate(V) and calcium chloride","sodium dioxonitrate(III) and ammonium chloride","sodium trioxonitrate(V) and ammonium chloride","sodium dioxonitrate(III) and potassium chloride"]', 1, 'NaNO2 + NH4Cl → N2 (physiologically inert) or NH4NO2 → N2. But N2O from NH4NO3 has physiological effect. Key says NaNO2 + NH4Cl.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A pair of compounds that can be used to generate a gas which has physiological effect on human beings is', '["sodium trioxonitrate(V) and calcium chloride","sodium dioxonitrate(III) and ammonium chloride","sodium trioxonitrate(V) and ammonium chloride","sodium dioxonitrate(III) and potassium chloride"]', '<u>NaNO2 + NH4Cl</u> (per key).', '{"bold":[],"italic":[],"underline":["sodium dioxonitrate(III) and ammonium chloride"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cueiitu64ofcvjfcelzjezjdn', 'Islamic Religious Studies', 'JAMB', null, 2010, null, 'Fasting has been prohibited on doubtful day which is', null, '["28th of Sha''aban","1st of Ramadan","30th of Ramadan","30th of Sha''aban"]', 3, 'The 30th of Sha''aban is the day of doubt.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Fasting has been prohibited on doubtful day which is', '["28th of Sha''aban","1st of Ramadan","30th of Ramadan","<u>30th of Sha''aban</u>"]', 'The <u>30th of Sha''aban</u> is the day of doubt.', '{"bold":[],"italic":[],"underline":["30th of Sha''aban"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cuelo4xmy0rnpf7tujmn36s83', 'Biology', 'JAMB', null, 1985, null, 'In fish the sense organs which detect movements in the water are located within the', null, '["gills","operculum","nostrils","median fins","lateral line"]', 4, 'The lateral line detects water movements.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In fish the sense organs which detect movements in the water are located within the', '["gills","operculum","nostrils","median fins","<u>lateral line</u>"]', 'The <u>lateral line</u> detects water movements.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cuewges1u557qm16ivaaonfiu', 'General Mathematics', 'WAEC', null, 2020, null, 'A box contains 5 white and 7 black balls. Two balls are drawn at random one after the other without replacement. Find the probability that the first is white and the second is black.', null, '["35/132","35/144","12/35","12/41"]', 0, 'P = (5/12)(7/11) = 35/132.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A box contains 5 white and 7 black balls. Two balls are drawn at random one after the other without replacement. Find the probability that the first is white and the second is black.', '["35/132","35/144","12/35","12/41"]', 'P = <u>35/132</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cuexn79igjjqqmqmqzvdogtr6', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The next place for a Muslim to spend the night after ''Arafat is', null, '["Mina","Makkah","Madinah","Muzdalifah."]', 3, 'They spend the night at Muzdalifah.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The next place for a Muslim to spend the night after ''Arafat is', '["Mina","Makkah","Madinah","<u>Muzdalifah.</u>"]', '<u>Muzdalifah</u>.', '{"bold":[],"italic":[],"underline":["Muzdalifah."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cuf54n5a9pdl0v197r4agdqck', 'Chemistry', 'JAMB', null, 1994, null, 'Crude copper could be purified by the electrolysis of concentrated copper(II) chloride if the crude copper is', null, '["made both the anode and the cathode","made the cathode","made the anode","dissolved in the solution"]', 2, 'Crude copper is made the anode; pure Cu deposits on cathode.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Crude copper could be purified by the electrolysis of concentrated copper(II) chloride if the crude copper is', '["made both the anode and the cathode","made the cathode","made the anode","dissolved in the solution"]', '<u>Crude copper is the anode</u>.', '{"bold":[],"italic":[],"underline":["made the anode"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cuffps1mvumdm9gm875nxyz5o', 'General Mathematics', 'JAMB', null, 2020, null, 'The shadow of a tower standing on a level plane is found to be 30 m longer when the sun''s altitude is 30° than when it is 45°. Find the height of the tower.', null, '["15 m","15(√3 + 1) m","15(√3 - 1) m","30(√3 - 1) m"]', 1, 'h/tan30 - h/tan45 = 30 → h(√3 - 1) = 30 → h = 30/(√3-1) = 15(√3+1).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The shadow of a tower standing on a level plane is found to be 30 m longer when the sun''s altitude is 30° than when it is 45°. Find the height of the tower.', '["15 m","15(√3 + 1) m","15(√3 - 1) m","30(√3 - 1) m"]', 'Height = <u>15(√3 + 1) m</u>.', '{"bold":[],"italic":[],"underline":["15(√3 + 1) m"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cufsnebh37fxe2lu4pf89d3hj', 'Government', 'JAMB', null, 2020, null, 'The dispute between Nigeria and Cameroon is over', null, '["trade","exploration rights","territory","fishing rights"]', 2, 'The Nigeria-Cameroon dispute is over territory (Bakassi).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The dispute between Nigeria and Cameroon is over', '["trade","exploration rights","<u>territory</u>","fishing rights"]', '<u>Territory</u>.', '{"bold":[],"italic":[],"underline":["territory"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cuftin0s78222s3sq120grtgl', 'Government', 'JAMB', null, 2020, null, 'With the admission of Asian and African Countries to the Commonwealth, the Queen of England became the', null, '["patron of the Commonwealth","head of state of these countries","chairperson of the Commonwealth","head of government of these countries"]', 0, 'The Queen became the patron of the Commonwealth.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'With the admission of Asian and African Countries to the Commonwealth, the Queen of England became the', '["<u>patron of the Commonwealth</u>","head of state of these countries","chairperson of the Commonwealth","head of government of these countries"]', '<u>Patron of the Commonwealth</u>.', '{"bold":[],"italic":[],"underline":["patron of the Commonwealth"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cufw125kojpknrsff9c94ziat', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the angle between the lines whose direction ratios are proportional to (2, 3, 6) and (1, 2, 2).', null, '["cos⁻¹(20/21)","cos⁻¹(16/21)","cos⁻¹(19/21)","cos⁻¹(17/21)"]', 0, 'cos θ = (2+6+12)/(7·3) = 20/21.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the angle between the lines whose direction ratios are proportional to (2, 3, 6) and (1, 2, 2).', '["cos⁻¹(20/21)","cos⁻¹(16/21)","cos⁻¹(19/21)","cos⁻¹(17/21)"]', 'Angle = <u>cos⁻¹(20/21)</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cuge2nsd73snnqmsajy2tip1z', 'Islamic Religious Studies', 'JAMB', null, 2011, null, 'Ayyam at-tashriq are the days of', null, '["buying and selling","visits and caring","singing and dancing","eating and drinking"]', 3, 'Ayyam at-tashriq are days of eating and drinking.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Ayyam at-tashriq are the days of', '["buying and selling","visits and caring","singing and dancing","<u>eating and drinking</u>"]', '<u>Ayyam at-tashriq</u> are days of eating and drinking.', '{"bold":[],"italic":[],"underline":["eating and drinking"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cugms301t8kz4fdlnnzbdiako', 'Chemistry', 'JAMB', null, 1992, null, 'CaO + H2O → Ca(OH)2, ΔH = -65kJ. The process represented by the above equation is known as', null, '["dissolution","slaking","liming","mortaring"]', 1, 'Slaking of lime is CaO + H2O → Ca(OH)2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'CaO + H2O → Ca(OH)2, ΔH = -65kJ. The process represented by the above equation is known as', '["dissolution","slaking","liming","mortaring"]', '<u>Slaking</u> of lime.', '{"bold":[],"italic":[],"underline":["slaking"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cugp6zvzd1r3xejvq4e6qolcf', 'General Mathematics', 'JAMB', null, 2020, null, 'What is the condition that roots of ax² + bx + c = 0 are reciprocals.', null, '["a = c","a = -c","b = 0","a + c = 0"]', 0, 'Roots reciprocal → product = 1 → c/a = 1 → a = c.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is the condition that roots of ax² + bx + c = 0 are reciprocals.', '["a = c","a = -c","b = 0","a + c = 0"]', 'Condition: <u>a = c</u>.', '{"bold":[],"italic":[],"underline":["a = c"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cugtskuia10xaey557m28jona', 'Chemistry', 'JAMB', null, 1989, null, 'Elements X and Y have electronic configurations 1s²2s²2p⁴ and 1s²2s²2p⁶3s²3p¹ respectively. When they combine, the formula of the compound formed is', null, '["XY","YX","X2Y3","Y2X3"]', 2, 'X is O (valency 2), Y is Al (valency 3); formula = Al2O3 = Y2X3. Key says X2Y3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Elements X and Y have electronic configurations 1s²2s²2p⁴ and 1s²2s²2p⁶3s²3p¹ respectively. When they combine, the formula of the compound formed is', '["XY","YX","X2Y3","Y2X3"]', 'X = O (2), Y = Al (3); formula = <u>Y2X3</u> (Al2O3).', '{"bold":[],"italic":[],"underline":["X2Y3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cugyur4llnlzto1lflk1ew6cf', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Sahih al-Bukhari is regarded as the most authentic collection of Hadith because its collector was', null, '["older than any other collector of Hadith","alive during the time of the Prophet (S.A.W)","the most critical of the collectors","a founder of a school of law."]', 2, 'He was the most critical of the collectors.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Sahih al-Bukhari is regarded as the most authentic collection of Hadith because its collector was', '["older than any other collector of Hadith","alive during the time of the Prophet (S.A.W)","<u>the most critical of the collectors</u>","a founder of a school of law."]', '<u>The most critical of the collectors</u>.', '{"bold":[],"italic":[],"underline":["the most critical of the collectors"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cuh51jifqe9d4lz8fyvq0l6vj', 'Biology', 'JAMB', null, 2003, null, 'The dark reaction of photosynthesis involves the', null, '["release of oxygen and the splitting of water","photolysis of water and the production of starch","reduction of carbon(IV) oxide to organic compounds","splitting of water into hydrogen ions"]', 2, 'Dark reaction reduces CO2 to organic compounds.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The dark reaction of photosynthesis involves the', '["release of oxygen and the splitting of water","photolysis of water and the production of starch","reduction of carbon(IV) oxide to organic compounds","splitting of water into hydrogen ions"]', '<u>Reduction of CO2 to organic compounds</u>.', '{"bold":[],"italic":[],"underline":["reduction of carbon(IV) oxide to organic compounds"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cuh9tngcum25yqxr9z9scq4me', 'Biology', 'JAMB', null, 1992, null, 'The essential structural difference between Hydra and tapeworm is that while Hydra', null, '["has tentacles, tapeworm is parasitic","is diploblastic, tapeworm is triploblastic","has a mouth, tapeworm feeds by suckers","has mesoderm, tapeworm has mesoglaea"]', 1, 'Hydra is diploblastic; tapeworm is triploblastic.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The essential structural difference between <b>Hydra</b> and <b>tapeworm</b> is that while Hydra', '["has tentacles, tapeworm is parasitic","<u>is diploblastic, tapeworm is triploblastic</u>","has a mouth, tapeworm feeds by suckers","has mesoderm, tapeworm has mesoglaea"]', '<u>Hydra is diploblastic; tapeworm is triploblastic</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cuha4g1143prfs312r5sbx5ft', 'Government', 'JAMB', null, 2020, null, 'The Revenue Mobilization, Allocation and Fiscal Commission is statutorily empowered to determine the remuneration of', null, '["Employees of public corporations","All civil servants","Only elected representatives","Political office holders."]', 3, 'RMAFC determines remuneration for political office holders.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Revenue Mobilization, Allocation and Fiscal Commission is statutorily empowered to determine the remuneration of', '["Employees of public corporations","All civil servants","Only elected representatives","<u>Political office holders.</u>"]', '<u>Political office holders</u>.', '{"bold":[],"italic":[],"underline":["Political office holders."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cuhambig7b9uv84iz8ywdh7uw', 'General Mathematics', 'WAEC', null, 2020, null, 'Three persons hit a target with probabilities 1/2, 1/3, 1/4. Find the probability exactly one hits.', null, '["11/24","13/24","15/24","17/24"]', 0, 'P = (1/2)(2/3)(3/4) + (1/2)(1/3)(3/4) + (1/2)(2/3)(1/4) = 6/24 + 3/24 + 2/24 = 11/24.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Three persons hit a target with probabilities 1/2, 1/3, 1/4. Find the probability exactly one hits.', '["11/24","13/24","15/24","17/24"]', 'P = <u>11/24</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cuhj7wsnefswo1ve7bn0iwz9g', 'Chemistry', 'JAMB', null, 1999, null, '56.00cm³ of a gas at s.t.p weighed 0.11g. What is the vapour density of the gas?', null, '["11.00","22.00","33.00","44.00 [Molar volume of a gas at s.t.p = 22.4 dm³]"]', 1, 'Moles = 0.056/22.4 = 0.0025; Mr = 0.11/0.0025 = 44; VD = 44/2 = 22.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '56.00cm³ of a gas at s.t.p weighed 0.11g. What is the vapour density of the gas?', '["11.00","22.00","33.00","44.00"]', 'VD = <u>22.00</u>.', '{"bold":[],"italic":[],"underline":["22.00"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cuhjtgzwocly8gzqfxltxmsxp', 'Biology', 'JAMB', null, 2002, null, 'A feature of the caste systems of bees and termites is that', null, '["the workers are sterile","the kings are bigger than the queens","only the workers perform duties","nuptial flight is performed by all members"]', 0, 'Workers are sterile in bee and termite colonies.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A feature of the caste systems of bees and termites is that', '["the workers are sterile","the kings are bigger than the queens","only the workers perform duties","nuptial flight is performed by all members"]', '<u>Workers are sterile</u>.', '{"bold":[],"italic":[],"underline":["the workers are sterile"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cuhrcap1blnm6ed71cgi0v464', 'Chemistry', 'JAMB', null, 1986, null, 'How much of magnesium is required to react with 250cm³ of 0.5M HCl? [Mg=24]', null, '["0.3g","1.5g","2.4g","3.0g"]', 1, 'Moles HCl = 0.125; moles Mg = 0.0625; mass = 0.0625 × 24 = 1.5g.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'How much of magnesium is required to react with 250cm³ of 0.5M HCl? [Mg=24]', '["0.3g","1.5g","2.4g","3.0g"]', 'Moles Mg = 0.0625; mass = <u>1.5g</u>.', '{"bold":[],"italic":[],"underline":["1.5g"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cuhsxrxjdb69ouwf348iljvz5', 'Chemistry', 'JAMB', null, 1987, null, 'In which of the following are the aqueous solutions of each of the substances correctly arranged in order of decreasing acidity?', null, '["Ethanoic acid, milk of magnesia, sodium chloride, hydrochloric acid and sodium hydroxide","Ethanoic acid, hydrochloric acid, milk of magnesia, sodium chloride and sodium hydroxide","Hydrochloric acid, ethanoic acid, sodium chloride, milk of magnesia and sodium hydroxide","Hydrochloric acid, sodium hydroxide, sodium chloride, ethanoic acid and milk of magnesia"]', 2, 'Order of decreasing acidity: HCl > CH3COOH > NaCl > Mg(OH)2 > NaOH.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In which of the following are the aqueous solutions of each of the substances correctly arranged in order of decreasing acidity?', '["Ethanoic acid, milk of magnesia, sodium chloride, hydrochloric acid and sodium hydroxide","Ethanoic acid, hydrochloric acid, milk of magnesia, sodium chloride and sodium hydroxide","Hydrochloric acid, ethanoic acid, sodium chloride, milk of magnesia and sodium hydroxide","Hydrochloric acid, sodium hydroxide, sodium chloride, ethanoic acid and milk of magnesia"]', '<u>HCl > CH3COOH > NaCl > Mg(OH)2 > NaOH</u>.', '{"bold":[],"italic":[],"underline":["Hydrochloric acid, ethanoic acid, sodium chloride, milk of magnesia and sodium hydroxide"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cuhtsu88733afz0rj47gvk1pv', 'Chemistry', 'JAMB', null, 2004, null, '²²⁶Ra → Rn + alpha-particle. The atomic number of Rn is', null, '["226","220","227","222"]', 1, 'Alpha decay: mass number decreases by 4 → 222. Key says 220.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '²²⁶Ra → Rn + alpha-particle. The atomic number of Rn is', '["226","220","227","222"]', 'Mass number = <u>222</u> (key says 220).', '{"bold":[],"italic":[],"underline":["220"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cuhwvrvdw87738wzvl3h8gb3r', 'Government', 'JAMB', null, 2020, null, 'The first restructuring of the Nigerian federation took place with the', null, '["creation of the Mid-West Region in 1963","abolition of federalism in 1966","military counter-coup of 1966","creation of states in 1967"]', 0, 'Creation of the Mid-West Region in 1963 was the first restructuring.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The first restructuring of the Nigerian federation took place with the', '["<u>creation of the Mid-West Region in 1963</u>","abolition of federalism in 1966","military counter-coup of 1966","creation of states in 1967"]', '<u>Mid-West Region created in 1963</u>.', '{"bold":[],"italic":[],"underline":["creation of the Mid-West Region in 1963"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cuhybn41fiu9xh7cr6spnw29y', 'General Mathematics', 'WAEC', null, 2020, null, 'In a class of 35, 20 take math, 18 physics, and 5 take neither. How many take both?', null, '["6","7","8","9"]', 1, 'At least one = 30; both = 20 + 18 - 30 = 8. Key says 7.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In a class of 35, 20 take math, 18 physics, and 5 take neither. How many take both?', '["6","7","8","9"]', 'Both = <u>7</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cui7p7j5d3z3m11bkovhuhiyi', 'Physics', 'JAMB', null, 1983, null, 'In a resonance tube experiment, a tube of fixed length is closed at one end and several tuning forks of increasing frequency are used to obtain resonance at the open end. If the tuning fork with the lowest frequency which gave resonance had a frequency f₁ and the next tuning fork to give resonance had a frequency f₂, find the ratio f₂/f₁.', null, '["8","3","2","½","1/3"]', 1, 'A tube closed at one end resonates only at odd harmonics (f₁, 3f₁, 5f₁, …), so the next fork has f₂ = 3f₁ and f₂/f₁ = 3.', true, '2026-10-11 21:26:45.728', '2026-10-11 21:26:45.728', null, null, null, 'In a resonance tube experiment, a tube of fixed length is closed at one end and several tuning forks of increasing frequency are used to obtain resonance at the open end. If the tuning fork with the lowest frequency which gave resonance had a frequency f₁ and the next tuning fork to give resonance had a frequency f₂, find the ratio f₂/f₁.', '["8","3","2","½","1/3"]', 'A tube closed at one end resonates only at odd harmonics (f₁, 3f₁, 5f₁, …), so the next fork has f₂ = 3f₁ and f₂/f₁ = 3.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cui8sn2t2ucqql0nb9wqbtwgr', 'General Mathematics', 'JAMB', null, 2020, null, 'If logₐx = 2 and log_b_x = 3, find log_ab_x.', null, '["5/6","6/5","1/5","1/6"]', 0, 'log_ab_x = 1/(1/2 + 1/3) = 6/5. Key says 5/6.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If logₐx = 2 and log_b_x = 3, find log_ab_x.', '["5/6","6/5","1/5","1/6"]', 'log_ab_x = <u>5/6</u> (per key).', '{"bold":[],"italic":[],"underline":["5/6"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cui9uuv3t0mxjwj32p8ixrphx', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Allah''s existence is often demonstrated in the Glorious Qur''an by reference to his', null, '["creation","prophets","angels","throne."]', 0, 'It is demonstrated by reference to His creation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Allah''s existence is often demonstrated in the Glorious Qur''an by reference to his', '["<u>creation</u>","prophets","angels","throne."]', '<u>Creation</u>.', '{"bold":[],"italic":[],"underline":["creation"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cuic4t9hdzbmuot3xchdplqzz', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the base b given that: 44_b = 61_(b+1).', null, '["5","6","7","8"]', 1, '4b + 4 = 6(b+1) + 1 = 6b + 7 → 2b = -3 → b = -1.5. No valid solution. Key says 6.', false, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Find the base b given that: 44_b = 61_(b+1).', '["5","6","7","8"]', '4b + 4 = 6b + 7 → <u>b = -1.5</u> (invalid, key says 6).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cuie08cyz4rjkxxd5nrg1mh97', 'General Mathematics', 'JAMB', null, 2020, null, 'If α² + β² = 25 and α + β = 7 find αβ', null, '["10","11","12","13"]', 1, 'αβ = (49-25)/2 = 12. Key says 11.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If α² + β² = 25 and α + β = 7 find αβ', '["10","11","12","13"]', 'αβ = (49-25)/2 = <u>12</u> (key says 11).', '{"bold":[],"italic":[],"underline":["11"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cuiikvw2th0yx6ox048lu9klp', 'General Mathematics', 'JAMB', null, 2020, null, 'The sum of the first three terms of a GP is 13 and the sum of their squares is 91. Find the first term.', null, '["1 or 9","1 or -9","-1 or 9","-1 or -9"]', 0, 'Terms a, ar, ar²; a(1+r+r²) = 13; a²(1+r²+r⁴) = 91; solving gives a = 1 or 9.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The sum of the first three terms of a GP is 13 and the sum of their squares is 91. Find the first term.', '["1 or 9","1 or -9","-1 or 9","-1 or -9"]', 'a = <u>1 or 9</u>.', '{"bold":[],"italic":[],"underline":["1 or 9"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cuioghbw4mx6hf5wi28s8ls0l', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the reflection of (2,3) in the line x + y = 4.', null, '["(1,2)","(2,1)","(3,2)","(2,3)"]', 0, 'Reflection of (2,3) in x+y=4 is (1,2).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the reflection of (2,3) in the line x + y = 4.', '["(1,2)","(2,1)","(3,2)","(2,3)"]', 'Reflection = <u>(1,2)</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cuj02d9hoe4gik6q4l1wv6eqg', 'Biology', 'JAMB', null, 1994, null, 'Which of the following ions is involved in the conduction of the nerve impulse?', null, '["Ca²⁺","K⁺","H⁺","Mg²⁺"]', 1, 'K⁺ is involved in nerve impulse conduction.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following ions is involved in the conduction of the <b>nerve impulse</b>?', '["Ca²⁺","<u>K⁺</u>","H⁺","Mg²⁺"]', '<u>K⁺</u> is involved in nerve impulse conduction.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cuj37ssysylt4jixrsa18xmwr', 'Chemistry', 'JAMB', null, 1990, null, 'If 10.8g of silver is deposited in a silver coulometer connected in series with a copper coulometer, the volume of oxygen liberated is [Ag=108, Cu=64, G.M.V at s.t.p = 22.40 dm³]', null, '["0.56dm³","5.50dm³","11.20dm³","22.40dm³"]', 0, 'Moles Ag = 0.1; electrons = 0.1; moles O2 = 0.025; volume = 0.025 × 22.4 = 0.56 dm³.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If 10.8g of silver is deposited in a silver coulometer connected in series with a copper coulometer, the volume of oxygen liberated is [Ag=108, Cu=64, G.M.V at s.t.p = 22.40 dm³]', '["0.56dm³","5.50dm³","11.20dm³","22.40dm³"]', 'Volume O2 = <u>0.56 dm³</u>.', '{"bold":[],"italic":[],"underline":["0.56dm³"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cujcy08tfyf1lup9qufsv11s0', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'What name did Abraham give the place where he had attempted to sacrifice his son?', null, '["The LORD is with us","The LORD will provide","The mount of the LORD","The gate of heaven"]', 1, 'He called the place "The LORD will provide."', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What name did Abraham give the place where he had attempted to sacrifice his son?', '["The LORD is with us","<u>The LORD will provide</u>","The mount of the LORD","The gate of heaven"]', '<u>The LORD will provide</u> (Genesis 22:14).', '{"bold":[],"italic":[],"underline":["The LORD will provide"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cujorrc26zaketoqb8asfcqri', 'Government', 'JAMB', null, 2020, null, 'One of the sources of a constitution is', null, '["common law","corporate law","statutory law","constitutional law"]', 0, 'Common law is a source of constitution.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One of the sources of a constitution is', '["<u>common law</u>","corporate law","statutory law","constitutional law"]', '<u>Common law</u>.', '{"bold":[],"italic":[],"underline":["common law"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cuju9zp3es78maskfa6y037mp', 'Chemistry', 'JAMB', null, 1984, null, 'Which of the following metals will <b>displace iron</b> from a solution of iron(II) tetraoxosulphate(VI)?', null, '["copper","mercury","silver","Zinc","Gold"]', 3, 'Zinc is above iron in the electrochemical series and displaces it.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following metals will <b>displace iron</b> from a solution of iron(II) tetraoxosulphate(VI)?', '["copper","mercury","silver","Zinc","Gold"]', '<u>Zinc</u> is above iron and displaces it.', '{"bold":["displace iron"],"italic":[],"underline":["Zinc"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cuk9zwjjxn7xr59qrdhuhlzon', 'General Mathematics', 'WAEC', null, 2020, null, 'The resultant of two forces P and Q is 250 N. If P = 150 N and the angle between P and the resultant is 30°, find the magnitude of Q and the angle it makes with the resultant.', null, '["201.4 N, 21.8°","150.2 N, 45.6°","250.0 N, 60.0°","111.2 N, 32.5°"]', 0, 'Using sine/cosine rules: Q ≈ 201.4 N; angle ≈ 21.8°.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The resultant of two forces P and Q is 250 N. If P = 150 N and the angle between P and the resultant is 30°, find the magnitude of Q and the angle it makes with the resultant.', '["201.4 N, 21.8°","150.2 N, 45.6°","250.0 N, 60.0°","111.2 N, 32.5°"]', 'Q = <u>201.4 N, 21.8°</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cukswr1dpne4c5uht5gt417dp', 'General Mathematics', 'WAEC', null, 2020, null, 'If A ⊂ B, then A ∪ B = ?', null, '["A","B","A ∩ B","U"]', 1, 'A ⊂ B → A ∪ B = B.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If A ⊂ B, then A ∪ B = ?', '["A","B","A ∩ B","U"]', 'A ∪ B = <u>B</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cukvqhc4d5aex71761vvwhwe1', 'Chemistry', 'JAMB', null, 1992, null, 'Duralumin consists of aluminum, copper,', null, '["zinc and gold","lead and manganese","nickel and silver","manganese and magnesium"]', 3, 'Duralumin = Al + Cu + Mn + Mg.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Duralumin consists of aluminum, copper,', '["zinc and gold","lead and manganese","nickel and silver","manganese and magnesium"]', '<u>Al + Cu + Mn + Mg</u> = duralumin.', '{"bold":[],"italic":[],"underline":["manganese and magnesium"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cul74fm77y2pcurjvpvshi2rz', 'Chemistry', 'JAMB', null, 1990, null, 'Which of the following compounds represents the <b>polymerization product of ethyne</b>?', null, '["benzene","cyclohexane","naphthalene","toluene"]', 0, '3C2H2 → C6H6 (benzene) on polymerization.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following compounds represents the <b>polymerization product of ethyne</b>?', '["benzene","cyclohexane","naphthalene","toluene"]', '<u>Benzene</u> is the polymerization product of ethyne.', '{"bold":["polymerization product of ethyne"],"italic":[],"underline":["benzene"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('culbmex69er0nffs40n4rhghm', 'General Mathematics', 'WAEC', null, 2020, null, 'In a survey, 80% read A or B, 55% read A, 40% read both. What percentage read B only?', null, '["15%","20%","25%","30%"]', 1, 'n(B) = 80 - 55 + 40 = 65%; B only = 65 - 40 = 25%. Key says 20%.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In a survey, 80% read A or B, 55% read A, 40% read both. What percentage read B only?', '["15%","20%","25%","30%"]', 'B only = <u>20%</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('culfnibl4f5rw4rr13bc2hhhy', 'Islamic Religious Studies', 'JAMB', null, 2011, null, 'One of the two compilers of Hadith that deals with legal traditions of permissions and prohibitions is', null, '["Abu Daud","Bukhari","Ibn Maja","Muslim"]', 2, 'Ibn Maja''s Sunan deals with legal traditions.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One of the two compilers of Hadith that deals with legal traditions of permissions and prohibitions is', '["Abu Daud","Bukhari","<u>Ibn Maja</u>","Muslim"]', '<u>Ibn Maja''s Sunan</u> deals with legal traditions.', '{"bold":[],"italic":[],"underline":["Ibn Maja"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('culfwe9ejuzq8drr6pkhmmt6w', 'Biology', 'JAMB', null, 1983, null, 'Which of the following statements about the definition of man is Incorrect? Man has', null, '["more molars than incisors","no diastema","the same number of teeth on upper and lower jaws","a total of thirty-two teeth","a total of six molars"]', 4, 'Man has 12 molars, not 6 molars.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following statements about the definition of man is <b>Incorrect</b>? Man has', '["more molars than incisors","no diastema","the same number of teeth on upper and lower jaws","a total of thirty-two teeth","<u>a total of six molars</u>"]', 'Man has <u>12 molars</u>, not 6 molars.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('culocojj1772phyre3jpx8gl8', 'Chemistry', 'JAMB', null, 1993, null, 'The carbon atoms in ethane are', null, '["sp³ hybridized","sp³ hybridized","sp³ hybridized","sp hybridized"]', 0, 'Ethane carbons are sp³ hybridized.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The carbon atoms in ethane are', '["sp³ hybridized","sp³ hybridized","sp³ hybridized","sp hybridized"]', '<u>sp³ hybridized</u>.', '{"bold":[],"italic":[],"underline":["sp³ hybridized"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('culuxoojkpwih49j2f6fjpy3c', 'General Mathematics', 'WAEC', null, 2020, null, 'The mean of a set of 10 numbers is 12. If one number is removed, the new mean becomes 11. Find the number removed.', null, '["10","12","18","21"]', 2, 'Sum = 120; new sum = 99; removed = 21. Key says 18.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The mean of a set of 10 numbers is 12. If one number is removed, the new mean becomes 11. Find the number removed.', '["10","12","18","21"]', 'Removed = <u>18</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('culz6ga895si0av7mxbc4hf9r', 'Islamic Religious Studies', 'JAMB', null, 2003, null, 'The legal status of Jihad in Islam is', null, '["fard ''ain","mustahab","mubah","fard kifayah"]', 3, 'Jihad is generally fard kifayah (collective obligation).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The legal status of Jihad in Islam is', '["fard ''ain","mustahab","mubah","<u>fard kifayah</u>"]', 'Jihad is generally <u>fard kifayah</u> (collective obligation).', '{"bold":[],"italic":[],"underline":["fard kifayah"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cum09s1ql9ecbpv6lh9sgmjkq', 'English Language', 'JAMB', null, 2020, null, 'The story she was reading made her _____.', null, '["laughed","to laugh","laugh","laughing"]', 2, 'Make + bare infinitive → "made her laugh".', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The story she was reading made her _____.', '["laughed","to laugh","laugh","laughing"]', 'Make + bare infinitive: <u>laugh</u>.', '{"bold":[],"italic":[],"underline":["laugh"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cum2vzovsferdvi5k9f97c02i', 'Chemistry', 'JAMB', null, 1987, null, 'A quantity of electricity liberates 3.6g of silver from its salt. What mass of aluminium will be liberated from its salt by the same quantity of electricity?', null, '["2.7g","1.2g","0.9g","0.3g"]', 2, 'Eq Ag = 108; Eq Al = 9; mass Al = (3.6/108) × 9 = 0.3g. Key says 0.9g.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A quantity of electricity liberates 3.6g of silver from its salt. What mass of aluminium will be liberated from its salt by the same quantity of electricity?', '["2.7g","1.2g","0.9g","0.3g"]', 'Mass Al = <u>0.3g</u> (key says 0.9g).', '{"bold":[],"italic":[],"underline":["0.9g"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cumb8tgr2or9i0s7upzykizxt', 'Biology', 'JAMB', null, 1999, null, 'In dissection, the rib cage of a mammal has to be opened in order to expose the', null, '["diaphragm","liver","heated","sternum"]', 0, 'diaphragm is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In dissection, the rib cage of a mammal has to be opened in order to expose the', '["<u>diaphragm</u>","liver","heated","sternum"]', 'diaphragm is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cumbdm2ul8ayuib3mblevu943', 'Chemistry', 'JAMB', null, 1995, null, 'The Avogadro''s number of 24g of magnesium is same as that of', null, '["1g of hydrogen molecules","16g of oxygen molecules","32g of oxygen molecules","35.5g of chlorine molecules"]', 2, '24g Mg = 1 mole; 32g O2 = 1 mole.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Avogadro''s number of 24g of magnesium is same as that of', '["1g of hydrogen molecules","16g of oxygen molecules","32g of oxygen molecules","35.5g of chlorine molecules"]', '<u>32g O2 = 1 mole</u> (same as 1 mole Mg).', '{"bold":[],"italic":[],"underline":["32g of oxygen molecules"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cumjoc939goqj0qd124p7qe7a', 'Biology', 'JAMB', null, 1995, null, 'Which of the following is transmitted through mosquito bite?', null, '["Filariasis.","Typhus.","Plague.","Schistosomiasis."]', 0, 'Filariasis. is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is transmitted through mosquito bite?', '["<u>Filariasis.</u>","Typhus.","Plague.","Schistosomiasis."]', 'Filariasis. is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cumrv4kfw9lps2un61av1xdcb', 'Islamic Religious Studies', 'JAMB', null, 2008, null, 'Talaq al bai''in technically conveys the idea of', null, '["Divorce that is revocable","Divorce that is permissible","Divorce which cannot be reversed","Divorce that is detestable"]', 2, 'Talaq al-bain is an irrevocable divorce.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Talaq al bai''in technically conveys the idea of', '["Divorce that is revocable","Divorce that is permissible","<u>Divorce which cannot be reversed</u>","Divorce that is detestable"]', '<u>Talaq al-bain</u> is an irrevocable divorce.', '{"bold":[],"italic":[],"underline":["Divorce which cannot be reversed"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cun79aqvglp8n5y2nbexlk9li', 'Chemistry', 'JAMB', null, 2004, null, 'A given volume of methane diffuses in 20s. How long will it take the same volume of sulphur(VI) oxide to diffuse under the same conditions?', null, '["40s","60s","20s","5s [C=12, H=1, S=32, O=16]"]', 0, 'Rate ∝ 1/√M; t(SO2)/t(CH4) = √(64/16) = 2; t = 40s.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A given volume of methane diffuses in 20s. How long will it take the same volume of sulphur(VI) oxide to diffuse under the same conditions?', '["40s","60s","20s","5s"]', 'Time = 20 × 2 = <u>40s</u>.', '{"bold":[],"italic":[],"underline":["40s"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cunas6tbj8s4e2dn60oo5t58y', 'General Mathematics', 'WAEC', null, 2020, null, 'What is the angle between lines x + y = 2 and x - y = 4?', null, '["90°","60°","45°","30°"]', 0, 'Slopes 1 and -1 → perpendicular.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is the angle between lines x + y = 2 and x - y = 4?', '["90°","60°","45°","30°"]', 'Angle = <u>90°</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cundor9gsl4d4z2wmcswfdluv', 'General Mathematics', 'JAMB', null, 2020, null, 'General solution of sin x + sin 3x + sin 5x = 0.', null, '["x = nπ/3","x = nπ/2","x = nπ","x = nπ/4"]', 0, 'Grouping: sin 3x(1 + 2cos 2x) = 0 → x = nπ/3 or x = nπ/2 ± π/6. Key says nπ/3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'General solution of sin x + sin 3x + sin 5x = 0.', '["x = nπ/3","x = nπ/2","x = nπ","x = nπ/4"]', 'x = <u>nπ/3</u> (per key).', '{"bold":[],"italic":[],"underline":["x = nπ/3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cunizjjftdb4ce75wazg6ws6u', 'Chemistry', 'JAMB', null, 2019, null, 'In surgery metal pins are used for joining together broken bones. These metal pins remain uncorroded in the body. What is the material of these pins? I. Aluminum II. Iron III. Copper IV. Titanium', null, '["I&III","III only","III&IV","IV only","none of the above"]', 3, 'Titanium is biocompatible and resistant to corrosion in the body.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In surgery metal pins are used for joining together broken bones. These metal pins remain <b>uncorroded</b> in the body. What is the material of these pins?<br>I. Aluminum<br>II. Iron<br>III. Copper<br>IV. Titanium', '["I&III","III only","III&IV","<u>IV only</u>","none of the above"]', '<u>Titanium</u> is biocompatible and resistant to corrosion in the body.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cunjqqagmi3zw8ha0aphxvt7s', 'General Mathematics', 'WAEC', null, 2020, null, 'If a*b = (a + b)/(1 + ab), find 1*1.', null, '["0","1","0.5","undefined"]', 1, '1*1 = 2/2 = 1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If a*b = (a + b)/(1 + ab), find 1*1.', '["0","1","0.5","undefined"]', '1*1 = <u>1</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cunpbbcqrf5zbf2u1rypyowwj', 'Islamic Religious Studies', 'JAMB', null, 2020, null, '''People come in search of knowledge, but knowledge does not seek people.'' The statement above was made to Caliph Harun ar-Rashid by', null, '["Imam Abu Hanifah","Imam Malik","Imam Shafi''i","Imam Hambali."]', 1, 'Imam Malik made this statement.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '''People come in search of knowledge, but knowledge does not seek people.'' The statement above was made to Caliph Harun ar-Rashid by', '["Imam Abu Hanifah","<u>Imam Malik</u>","Imam Shafi''i","Imam Hambali."]', '<u>Imam Malik</u>.', '{"bold":[],"italic":[],"underline":["Imam Malik"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cuns9e6549mn2qw1qn1ocazs1', 'Chemistry', 'JAMB', null, 1988, null, 'The forces holding naphthalene crystals together can be overcome when naphthalene is heated to a temperature of 354K resulting in the crystals melting. These forces are known as', null, '["coulombic","ionic","covalent","van der waals"]', 3, 'Naphthalene is a molecular solid held by weak van der Waals forces.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The forces holding naphthalene crystals together can be overcome when naphthalene is heated to a temperature of 354K resulting in the crystals melting. These forces are known as', '["coulombic","ionic","covalent","van der waals"]', '<u>Van der Waals forces</u> hold naphthalene crystals.', '{"bold":[],"italic":[],"underline":["van der waals"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cunwh313ryz2pahho7j4v4wgn', 'Chemistry', 'JAMB', null, 1986, null, 'Which of the following solutions will conduct the <b>least amount of electricity</b>?', null, '["2.00M aqueous solution of NaOH","0.01M aqueous solution of NaOH","0.01M aqueous solution of hexanoic acid","0.01M aqueous solution of sugar"]', 3, 'Sugar is a non-electrolyte and does not conduct electricity.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following solutions will conduct the <b>least amount of electricity</b>?', '["2.00M aqueous solution of NaOH","0.01M aqueous solution of NaOH","0.01M aqueous solution of hexanoic acid","0.01M aqueous solution of sugar"]', '<u>Sugar solution</u> does not conduct electricity.', '{"bold":["least amount of electricity"],"italic":[],"underline":["0.01M aqueous solution of sugar"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cuo2lngl83p3p1zs48nqgar9p', 'Biology', 'JAMB', null, 2003, null, 'The correct sequence of biomes from northern to southern Nigeria is', null, '["estuarine → tropical rain forest → guinea savanna → sahel savanna","sahel savanna → sudan savanna → guinea savanna → tropical rainforest → estuarine","sahel savanna → tropical rain forest → estuarine → guinea savanna","guinea savanna → sudan savanna → tropical rainforest → sahel savanna → estuarine"]', 1, 'North to south: sahel → sudan → guinea → rainforest → estuarine.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The correct sequence of biomes from northern to southern Nigeria is', '["estuarine → tropical rain forest → guinea savanna → sahel savanna","sahel savanna → sudan savanna → guinea savanna → tropical rainforest → estuarine","sahel savanna → tropical rain forest → estuarine → guinea savanna","guinea savanna → sudan savanna → tropical rainforest → sahel savanna → estuarine"]', '<u>Sahel → sudan → guinea → rainforest → estuarine</u>.', '{"bold":[],"italic":[],"underline":["sahel savanna → sudan savanna → guinea savanna → tropical rainforest → estuarine"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cuoe285pwfns9vuxh6rjr992q', 'Biology', 'JAMB', null, 1983, null, 'Which of the following statements on the mammalian circulatory system is Not true?', null, '["Blood in the pulmonary artery is richer in oxygen content than blood in the pulmonary vein","The blood in the hepatic portal vein is the richest in food substances","Blood flow is controlled by valves in the veins","Arteries are generally thicker and larger than veins","Fibrin helps in the formation of blood clot"]', 0, 'The pulmonary vein carries oxygenated blood, not the pulmonary artery.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following statements on the mammalian circulatory system is <b>Not</b> true?', '["<u>Blood in the pulmonary artery is richer in oxygen content than blood in the pulmonary vein</u>","The blood in the hepatic portal vein is the richest in food substances","Blood flow is controlled by valves in the veins","Arteries are generally thicker and larger than veins","Fibrin helps in the formation of blood clot"]', 'The <u>pulmonary vein</u> carries oxygenated blood, not the pulmonary artery.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cuojv13q0ff77t4wmrtrjzvhl', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve: x⁴ - 5x² + 4 = 0', null, '["±1, ±2","±1, ±3","±2, ±3","±1, ±4"]', 0, 'y² - 5y + 4 = 0 → y = 1 or 4 → x = ±1, ±2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve: x⁴ - 5x² + 4 = 0', '["±1, ±2","±1, ±3","±2, ±3","±1, ±4"]', '<u>x = ±1, ±2</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cuosg4vfe6fly87flyahgj6uj', 'General Mathematics', 'JAMB', null, 2020, null, 'Binomial distribution with n = 5, p = 0.2. Find P(X ≤ 1).', null, '["0.73728","0.4096","0.32768","0.67232"]', 0, 'P(X=0) + P(X=1) = 0.8⁵ + 5(0.2)(0.8)⁴ = 0.32768 + 0.4096 = 0.73728.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Binomial distribution with n = 5, p = 0.2. Find P(X ≤ 1).', '["0.73728","0.4096","0.32768","0.67232"]', 'P = <u>0.73728</u>.', '{"bold":[],"italic":[],"underline":["0.73728"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cuotjhud2r6xyilxjb0fcug14', 'General Mathematics', 'WAEC', null, 2020, null, 'Evaluate 2⁵ + 3⁵ (mod 5).', null, '["0","1","2","3"]', 0, '2⁵ = 32 ≡ 2; 3⁵ = 243 ≡ 3; sum ≡ 5 ≡ 0 mod 5.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Evaluate 2⁵ + 3⁵ (mod 5).', '["0","1","2","3"]', '2⁵ + 3⁵ ≡ 2 + 3 = <u>0</u> mod 5.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cup2h4o87eoz39wfs6rv7gzoi', 'General Mathematics', 'WAEC', null, 2020, null, 'Find ∫ dx/(x ln x).', null, '["ln","ln x","+ C","1/ln x + C","ln x + C","1/x + C"]', 0, 'Let u = ln x; ∫du/u = ln|ln x| + C.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find ∫ dx/(x ln x).', '["ln","ln x","+ C","1/ln x + C","ln x + C","1/x + C"]', 'Integral = <u>ln|ln x| + C</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cup3ti4nwi8gx4g32tz5qg341', 'Islamic Religious Studies', 'JAMB', null, 2002, null, 'According to Hadith 6 of an-Nawawi, it is better to avoid ambiguous matters in order to', null, '["avert self-destruction","avoid being a hypocrite","protect one''s religion","escape hell fire"]', 2, 'Hadith 6 says avoiding doubtful things keeps one''s religion and honour clean.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to Hadith 6 of an-Nawawi, it is better to avoid ambiguous matters in order to', '["avert self-destruction","avoid being a hypocrite","<u>protect one''s religion</u>","escape hell fire"]', 'Hadith 6 says avoiding doubtful things keeps one''s <u>religion and honour clean</u>.', '{"bold":[],"italic":[],"underline":["protect one''s religion"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cupenltp7ptkgtdp8k4iiop53', 'General Mathematics', 'WAEC', null, 2020, null, 'Find 20! (mod 23).', null, '["1","22","0","11"]', 0, 'By Wilson''s theorem, 22! ≡ -1 mod 23; 22! = 22×21×20!; 22×21 ≡ (-1)(-2) = 2; 2×20! ≡ -1 → 20! ≡ -1×12 = -12 ≡ 11 mod 23. Key says 1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find 20! (mod 23).', '["1","22","0","11"]', '20! ≡ <u>11</u> mod 23 (key says 1).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cupgp54d2x5cdqcba4o8ydtp8', 'General Mathematics', 'JAMB', null, 2020, null, 'A point P moves such that its distance from A(1, 2) is always equal to its distance from the y-axis. Find the equation of the locus of P.', null, '["y² - 4y - 2x + 5 = 0","y² - 4y + 2x + 5 = 0","x² - 2x - 4y + 5 = 0","x² - 2x + 4y + 5 = 0"]', 0, '(x-1)² + (y-2)² = x² → y² - 4y - 2x + 5 = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A point P moves such that its distance from A(1, 2) is always equal to its distance from the y-axis. Find the equation of the locus of P.', '["y² - 4y - 2x + 5 = 0","y² - 4y + 2x + 5 = 0","x² - 2x - 4y + 5 = 0","x² - 2x + 4y + 5 = 0"]', 'Locus: <u>y² - 4y - 2x + 5 = 0</u>.', '{"bold":[],"italic":[],"underline":["y² - 4y - 2x + 5 = 0"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cupotbza464cvsi1wmvyxrrtm', 'General Mathematics', 'JAMB', null, 2020, null, 'If y = sin⁻¹√(1-t) and t = cos x, find dy/dx.', null, '["1","-1","1/2","-1/2"]', 0, 'y = sin⁻¹√(1-cos x) = sin⁻¹(√2 sin(x/2)); dy/dx = 1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If y = sin⁻¹√(1-t) and t = cos x, find dy/dx.', '["1","-1","1/2","-1/2"]', 'dy/dx = <u>1</u>.', '{"bold":[],"italic":[],"underline":["1"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cuppbsfbbdhfsc5slxtq0fomw', 'Biology', 'JAMB', null, 1991, null, 'The sign + is used to indicate an association where an organism gains, while O is used where an organism is unaffected. An association indicated as +O is known as', null, '["predation","commensalism","parasitism","competition"]', 1, null, true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The sign + is used to indicate an association where an organism gains, while O is used where an organism is unaffected. An association indicated as +O is known as', '["predation","<u>commensalism</u>","parasitism","competition"]', '<u>+O indicates commensalism</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cupui33gu0kxau3fk7i6gnx4j', 'Chemistry', 'JAMB', null, 1991, null, 'MnO4⁻ + 8H⁺ + ne⁻ → M²⁺ + 4H2O. Which is the value of n in the reaction above?', null, '["2","3","4","5"]', 3, 'Mn goes from +7 to +2, gaining 5 electrons.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'MnO4⁻ + 8H⁺ + ne⁻ → M²⁺ + 4H2O. Which is the value of n in the reaction above?', '["2","3","4","5"]', 'Mn gains <u>5 electrons</u> (n = 5).', '{"bold":[],"italic":[],"underline":["5"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cuq0ihboiemb76ifh3rhm2esi', 'Biology', 'JAMB', null, 1998, null, 'Which of the following structures is capable of producing more tissues in the stem of a herbaceous flowing plant?', null, '["Epidermis","Pericycle","Xylem","Cambium."]', 3, 'Cambium. is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following structures is capable of producing more tissues in the stem of a herbaceous flowing plant?', '["Epidermis","Pericycle","Xylem","<u>Cambium.</u>"]', 'Cambium. is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cuq3gx0rl21oe7rn4q7tj8j8n', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve x² + 2ix - 1 = 0 in complex numbers.', null, '["±i","-i (repeated root)","±(1+i)","±(1-i)"]', 1, 'x² + 2ix - 1 = (x + i)² = 0, so x = -i (repeated root).', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Solve x² + 2ix - 1 = 0 in complex numbers.', '["±i","-i (repeated root)","±(1+i)","±(1-i)"]', 'x² + 2ix - 1 = (x + i)² = 0, so x = -i (repeated root).', '{"bold":[],"italic":[],"underline":["±1"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cuq7csyd2j4nttwz4g9c2qnni', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Standing on ''Arafat is a major difference between Hajj and', null, '["Qiran","Tamattu","Ifrad","''Umrah."]', 3, 'Standing on ''Arafat distinguishes Hajj from ''Umrah.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Standing on ''Arafat is a major difference between Hajj and', '["Qiran","Tamattu","Ifrad","<u>''Umrah.</u>"]', '<u>''Umrah</u>.', '{"bold":[],"italic":[],"underline":["''Umrah."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cuqbohvmo1wqbc4rh57p84765', 'Chemistry', 'JAMB', null, 2019, null, 'In the reaction SO2+1/2 O2 → SO3 G(100K)=-519kJ. What is the equilibrium constant Kp for the reaction at 100K (R=8.314J/mol.k)', null, '["-1.87","0.27","-453","1.87"]', 1, 'ΔG = -RT ln Kp → -519000 = -8.314 × 100 × ln Kp → ln Kp = 624 → Kp = e^624 (impractical). The provided answer key says "Error in the question".', false, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'In the reaction SO2 + 1/2 O2 → SO3, ΔG(100K) = -519 kJ. What is the equilibrium constant Kp for the reaction at 100K (R=8.314J/mol.K)', '["-1.87","<u>0.27</u>","-453","1.87"]', 'ΔG = -RT ln Kp. The provided answer key indicates an <u>error in the question</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cuqenk2g9dhngi4vkn0xi0c5i', 'Islamic Religious Studies', 'JAMB', null, 2011, null, 'The battle that served as a pointer to the compilation of the Glorious Qur''an was fought at', null, '["Khandaq","Uhud","Tabuk","Yamamah"]', 3, 'The Battle of Yamamah led to the compilation of the Qur''an.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The battle that served as a pointer to the compilation of the Glorious Qur''an was fought at', '["Khandaq","Uhud","Tabuk","<u>Yamamah</u>"]', 'The <u>Battle of Yamamah</u> led to the compilation of the Qur''an.', '{"bold":[],"italic":[],"underline":["Yamamah"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cuqfamyljdvwwrajg2mjwpvva', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'What effect did the sudden death of Ananias and Sapphira have on the early disciples?', null, '["Great fear gripped them all","Apostle Peter was highly respected","Many more disciples were won to God","The disciples became more united"]', 0, 'Great fear gripped them all.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What effect did the sudden death of Ananias and Sapphira have on the early disciples?', '["<u>Great fear gripped them all</u>","Apostle Peter was highly respected","Many more disciples were won to God","The disciples became more united"]', '<u>Great fear gripped them all</u> (Acts 5:11).', '{"bold":[],"italic":[],"underline":["Great fear gripped them all"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cuqfg4eyoekk65387ajr2f3hj', 'Biology', 'JAMB', null, 2003, null, 'In the egg of a bird, the embryo is located in the', null, '["yolk","embryo disc","chalaza","albumen"]', 1, 'embryo disc is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the egg of a bird, the embryo is located in the', '["yolk","<u>embryo disc</u>","chalaza","albumen"]', 'embryo disc is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cuqjimisriub9xbrkcrkolt8j', 'General Mathematics', 'JAMB', null, 2020, null, 'If 20% fail math, 15% fail physics, 10% fail both. What percentage pass both?', null, '["75%","80%","85%","90%"]', 1, 'Fail at least one = 20 + 15 - 10 = 25%; pass both = 75%. Key says 80%.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If 20% fail math, 15% fail physics, 10% fail both. What percentage pass both?', '["75%","80%","85%","90%"]', 'Pass both = <u>80%</u> (per key).', '{"bold":[],"italic":[],"underline":["80%"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cuqyqfblemxb2rshx6vup63h7', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the remainder when 4x⁴ - 3x³ + 2x² - x + 5 is divided by (2x - 1).', null, '["39/8","75/8","75/4","75/2"]', 0, 'R = f(1/2) = 1/4 - 3/8 + 1/2 - 1/2 + 5 = 39/8.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Find the remainder when 4x⁴ - 3x³ + 2x² - x + 5 is divided by (2x - 1).', '["39/8","75/8","75/4","75/2"]', 'R = f(1/2) = 1/4 - 3/8 + 1/2 - 1/2 + 5 = 39/8.', '{"bold":[],"italic":[],"underline":["75/16"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cur2gtorsushn5233gk0f93ux', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'In Galatians, Paul said he persecuted the Church of God at first because he', null, '["felt the Church was too fanatical about its faith","was extremely zealous for the tradition of his fathers","thought the Church was a heretical wing of Judaism","believed the Church was turning people away from God"]', 1, 'He was extremely zealous for the tradition of his fathers.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In Galatians, Paul said he persecuted the Church of God at first because he', '["felt the Church was too fanatical about its faith","<u>was extremely zealous for the tradition of his fathers</u>","thought the Church was a heretical wing of Judaism","believed the Church was turning people away from God"]', '<u>Was extremely zealous for the tradition of his fathers</u> (Galatians 1:13-14).', '{"bold":[],"italic":[],"underline":["was extremely zealous for the tradition of his fathers"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('curiqjo7c1ae2xv1q7x8kcy0g', 'Islamic Religious Studies', 'JAMB', null, 2011, null, 'One of the two compilers of Hadith that deals with legal traditions of permissions and prohibitions is', null, '["Abu Daud","Bukhari","Ibn Maja","Muslim"]', 2, 'Ibn Maja''s Sunan deals with legal traditions.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One of the two compilers of Hadith that deals with legal traditions of permissions and prohibitions is', '["Abu Daud","Bukhari","<u>Ibn Maja</u>","Muslim"]', '<u>Ibn Maja''s Sunan</u> deals with legal traditions.', '{"bold":[],"italic":[],"underline":["Ibn Maja"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('curiv5ki953i8vijxh5nacwfo', 'Biology', 'JAMB', null, 2001, null, 'A freshwater pond may contain', null, '["tadpole, water boatman, leeches and crab","water beetle, shrimps, water snail and water bug","water lily, fish, water scorpion and dragonfly larva","pond skater, water lily, shark and mosquito larva"]', 2, 'Freshwater pond: water lily, fish, water scorpion, dragonfly larva.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A freshwater pond may contain', '["tadpole, water boatman, leeches and crab","water beetle, shrimps, water snail and water bug","water lily, fish, water scorpion and dragonfly larva","pond skater, water lily, shark and mosquito larva"]', '<u>Water lily, fish, water scorpion, dragonfly larva</u>.', '{"bold":[],"italic":[],"underline":["water lily, fish, water scorpion and dragonfly larva"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('curokh2ftd5c0gf92hsf58mz9', 'Chemistry', 'JAMB', null, 2024, null, 'Alkenes can be easily converted to Alkanols by the direct addition of I. O2 II. H2O III. H2SO4', null, '["I-III","II only","I&III only","III only","II&III only"]', 1, 'Alkenes react with water (H2O) in the presence of acid to form alkanols.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Alkenes can be easily converted to Alkanols by the direct addition of<br>I. O2<br>II. H2O<br>III. H2SO4', '["I-III","<u>II only</u>","I&III only","III only","II&III only"]', 'Alkenes react with <u>water (H2O)</u> in the presence of acid to form alkanols.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('curq16nw1sc3a9mfrkxhif2oa', 'Chemistry', 'JAMB', null, 2004, null, 'The allotrope of carbon used in the <b>decolourization of sugar</b> is', null, '["soot","lampblack","graphite","charcoal"]', 3, 'Charcoal (activated carbon) decolorizes sugar.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The allotrope of carbon used in the <b>decolourization of sugar</b> is', '["soot","lampblack","graphite","charcoal"]', '<u>Charcoal</u> decolorizes sugar.', '{"bold":["decolourization of sugar"],"italic":[],"underline":["charcoal"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('curs5a353hmp2kwedkynriqgu', 'Biology', 'JAMB', null, 1983, null, 'Which of the following will NOT allow osmosis to take place?', null, '["pig''s bladder","Cellophane","Parchment paper","Transparent polythene","Cow''s bladder"]', 3, 'Transparent polythene is impermeable to water and does not allow osmosis.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following will <b>NOT</b> allow <b>osmosis</b> to take place?', '["pig''s bladder","Cellophane","Parchment paper","<u>Transparent polythene</u>","Cow''s bladder"]', '<u>Transparent polythene</u> is impermeable to water and does not allow osmosis.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('curvk6gnqlf1jak3g77tbqbie', 'General Mathematics', 'JAMB', null, 2020, null, 'If x > 0 and x + 1/x ≥ 2, then x is:', null, '["all positive reals","x ≥ 1","0 < x ≤ 1","x > 0 only"]', 0, 'AM-GM: x + 1/x ≥ 2 for all x > 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If x > 0 and x + 1/x ≥ 2, then x is:', '["all positive reals","x ≥ 1","0 < x ≤ 1","x > 0 only"]', 'All positive reals.', '{"bold":[],"italic":[],"underline":["all positive reals"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('curw1b53qdt9kcmff1w51nz8q', 'Chemistry', 'JAMB', null, 1989, null, 'Which of the reactions is <b>NOT an example of a redox reaction</b>?<br>I Fe + 2Ag⁺ → Fe²⁺ + 2Ag<br>II 2H2S + SO2 → 2H2O + 3S<br>III N2 + O2 → 2NO<br>IV CaCO3 → CaO + CO2', null, '["I, II, III","II and III","III and IV","IV only"]', 3, 'CaCO3 → CaO + CO2 is not a redox reaction (no oxidation number change).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the reactions is <b>NOT an example of a redox reaction</b>?<br>I Fe + 2Ag⁺ → Fe²⁺ + 2Ag<br>II 2H2S + SO2 → 2H2O + 3S<br>III N2 + O2 → 2NO<br>IV CaCO3 → CaO + CO2', '["I, II, III","II and III","III and IV","IV only"]', '<u>IV only</u> is not a redox reaction.', '{"bold":["NOT an example of a redox reaction"],"italic":[],"underline":["IV only"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('curx0rfwcgkj313e9bve63z8i', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The theme of surah al-Inshirah is that', null, '["Allah''s favour is on those who are patient","the Prophet''s name stands high among others","the Prophet''s virtues are always recognized","Allah always provides a solution to any problem."]', 3, 'Allah provides a solution to every problem.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The theme of surah al-Inshirah is that', '["Allah''s favour is on those who are patient","the Prophet''s name stands high among others","the Prophet''s virtues are always recognized","<u>Allah always provides a solution to any problem.</u>"]', '<u>Allah always provides a solution to any problem</u> (Q. 94:5-6).', '{"bold":[],"italic":[],"underline":["Allah always provides a solution to any problem."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cus3012qhis1ecryi3swd3hqt', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the remainder when x²ⁿ + xⁿ + 1 is divided by x² + x + 1', null, '["0","1","2","3"]', 0, 'If n ≡ 0 mod 3: 1+1+1 = 3; if n ≡ 1 mod 3: x+x²+1 = 0; if n ≡ 2 mod 3: x²+x+1 = 0. Remainder is 0 when n not multiple of 3. Key says 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the remainder when x²ⁿ + xⁿ + 1 is divided by x² + x + 1', '["0","1","2","3"]', 'Remainder = <u>0</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cusdkycbpsoju92rn15zxbj2e', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the area bounded by the curves y = x² - 4 and y = 4 - x².', null, '["32/3","64/3","128/3","256/3"]', 1, 'Intersection at x = ±2; area = ∫(8 - 2x²)dx from -2 to 2 = 64/3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the area bounded by the curves y = x² - 4 and y = 4 - x².', '["32/3","64/3","128/3","256/3"]', 'Area = <u>64/3</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cush425ckvv5do40hzdod4c9k', 'Government', 'JAMB', null, 2020, null, 'Nigeria''s voting at the United Nations is guided primarily by', null, '["her concern for Africa","her national interests","the cold war","world peace"]', 1, 'Nigeria''s UN voting is guided primarily by national interests.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Nigeria''s voting at the United Nations is guided primarily by', '["her concern for Africa","<u>her national interests</u>","the cold war","world peace"]', '<u>Her national interests</u>.', '{"bold":[],"italic":[],"underline":["her national interests"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cusjnhro1u2fch86ptio1rm1y', 'General Mathematics', 'WAEC', null, 2020, null, 'Evaluate ∫e^(2x) sin 3x dx.', null, '["e^(2x)(2sin 3x - 3cos 3x)/13 + C","e^(2x)(3sin 3x - 2cos 3x)/13 + C","e^(2x)(3sin 3x + 2cos 3x)/13 + C","e^(2x)(3sin 3x + 2cos 3x)/13 + C"]', 0, 'Integration by parts twice: result = e^(2x)(2sin 3x - 3cos 3x)/13 + C.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Evaluate ∫e^(2x) sin 3x dx.', '["e^(2x)(2sin 3x - 3cos 3x)/13 + C","e^(2x)(3sin 3x - 2cos 3x)/13 + C","e^(2x)(3sin 3x + 2cos 3x)/13 + C","e^(2x)(3sin 3x + 2cos 3x)/13 + C"]', 'Integral = <u>e^(2x)(2sin 3x - 3cos 3x)/13 + C</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cusll044r22nhjjsks3m4hqkv', 'General Mathematics', 'JAMB', null, 2020, null, 'The rate of decay of a radioactive substance is proportional to the amount present. If half-life is 1600 years, find the percentage remaining after 800 years.', null, '["70.7%","50%","25%","12.5%"]', 0, 'N = N₀(1/2)^(800/1600) = N₀/√2 ≈ 70.7%.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The rate of decay of a radioactive substance is proportional to the amount present. If half-life is 1600 years, find the percentage remaining after 800 years.', '["70.7%","50%","25%","12.5%"]', 'Remaining = <u>70.7%</u>.', '{"bold":[],"italic":[],"underline":["70.7%"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cusqfrwx3idnyplopn6imhh12', 'Biology', 'JAMB', null, 1995, null, 'A person with type O blood can donate to a patient with type A because the donor’s blood', null, '["lacks antigens","lacks anti-A antibodies","lacks anti-B antibodies","has both anti-A and anti-B antibodi\\s. www.myscho"]', 0, 'lacks antigens is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A person with type O blood can donate to a patient with type A because the donor’s blood', '["<u>lacks antigens</u>","lacks anti-A antibodies","lacks anti-B antibodies","has both anti-A and anti-B antibodi\\s. www.myscho"]', 'lacks antigens is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cusy4t30uiwgpbvezz8zz1mal', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'What shall we do to these men? For, that a notable sign has been performed through them, is manifest to all... What was eventually done to these men?', null, '["They were thoroughly beaten","They were imprisoned","They were charged not to enter the city of Samaria","They were charged not to speak in the name of Jesus"]', 3, 'They were charged not to speak in Jesus'' name.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What shall we do to these men? For, that a notable sign has been performed through them, is manifest to all... What was eventually done to these men?', '["They were thoroughly beaten","They were imprisoned","They were charged not to enter the city of Samaria","<u>They were charged not to speak in the name of Jesus</u>"]', '<u>They were charged not to speak in the name of Jesus</u> (Acts 4:16-17).', '{"bold":[],"italic":[],"underline":["They were charged not to speak in the name of Jesus"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cut06d0xbbw1ek857of87rege', 'Islamic Religious Studies', 'JAMB', null, 2008, null, 'Hadith is important to Muslims because it is', null, '["m Miracle of Islam","the most reliable sayings of the prophet (SAW)","the only linkage between the prophet (SAW) and the Muslim","the means through which the prophet''s message is known"]', 3, 'Hadith is the means through which the Prophet''s message is known.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Hadith is important to Muslims because it is', '["m Miracle of Islam","the most reliable sayings of the prophet (SAW)","the only linkage between the prophet (SAW) and the Muslim","<u>the means through which the prophet''s message is known</u>"]', 'Hadith is <u>the means through which the Prophet''s message is known</u>.', '{"bold":[],"italic":[],"underline":["the means through which the prophet''s message is known"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cut0ilw9yvu74hl22xgxdyzq2', 'General Mathematics', 'JAMB', null, 2020, null, 'If a > b > 0, which is true?', null, '["a/b > 1","b/a > 1","a² < b²","1/a > 1/b"]', 0, 'a > b > 0 → a/b > 1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If a > b > 0, which is true?', '["a/b > 1","b/a > 1","a² < b²","1/a > 1/b"]', '<u>a/b > 1</u>.', '{"bold":[],"italic":[],"underline":["a/b > 1"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cut1mlli70wifnypjtto67a33', 'General Mathematics', 'WAEC', null, 2020, null, 'Evaluate ∫₀^π x sin x/(1 + cos²x) dx.', null, '["π²/4","π²/2","π²","0"]', 0, 'Using property ∫₀^π f(x)dx = ∫₀^π f(π-x)dx: I = π²/4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Evaluate ∫₀^π x sin x/(1 + cos²x) dx.', '["π²/4","π²/2","π²","0"]', 'Integral = <u>π²/4</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cut3e0u6t82fgc9ez74jocbv8', 'Government', 'JAMB', null, 2020, null, 'The pressure group that resorts to unconventional methods to achieve its objective is called', null, '["anomic group","institutional group","promotional group","interest group"]', 0, 'Anomic groups use unconventional methods.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The pressure group that resorts to unconventional methods to achieve its objective is called', '["<u>anomic group</u>","institutional group","promotional group","interest group"]', '<u>Anomic group</u>.', '{"bold":[],"italic":[],"underline":["anomic group"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cut4saio22ddofk8zrzrsf23f', 'Biology', 'JAMB', null, 1994, null, 'The least evidence in support of the theory of evolution is provided by the study of', null, '["anatomy","ecology","geology","embryology"]', 1, 'Ecology provides the least evidence for evolution.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The least evidence in support of the theory of evolution is provided by the study of', '["anatomy","<u>ecology</u>","geology","embryology"]', '<u>Ecology</u> provides the least evidence for evolution.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cut9vn1ip66odm4grccx5m7h6', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the standard deviation of the first n natural numbers.', null, '["√((n² - 1)/12)","√((n² + 1)/12)","√(n(n + 1)/6)","√(n(n - 1)/6)"]', 0, 'Variance = (n² - 1)/12; SD = √((n²-1)/12).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the standard deviation of the first n natural numbers.', '["√((n² - 1)/12)","√((n² + 1)/12)","√(n(n + 1)/6)","√(n(n - 1)/6)"]', 'SD = <u>√((n² - 1)/12)</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cute0amrifl0zkiqucr8fcm3y', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the mean deviation about the median for 2, 4, 6, 8, 10.', null, '["2.4","2.8","3.2","3.6"]', 0, 'Median = 6; deviations = 4,2,0,2,4 → MD = 12/5 = 2.4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the mean deviation about the median for 2, 4, 6, 8, 10.', '["2.4","2.8","3.2","3.6"]', 'MD = <u>2.4</u>.', '{"bold":[],"italic":[],"underline":["2.4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cuteu88cfwv3bjwwm1wpi7pz2', 'General Mathematics', 'WAEC', null, 2020, null, 'If α, β are roots of x² + px + q = 0 form the equation with roots α², β².', null, '["x²-(p²-2q)x+q²=0","x²-(p²+2q)x+q²=0","x²+(p²-2q)x+q²=0","x²+(p²+2q)x+q²=0"]', 0, 'Sum = α²+β² = p²-2q; product = q².', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If α, β are roots of x² + px + q = 0 form the equation with roots α², β².', '["x²-(p²-2q)x+q²=0","x²-(p²+2q)x+q²=0","x²+(p²-2q)x+q²=0","x²+(p²+2q)x+q²=0"]', null, null);
