insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cutmag6fctvgkj4ui62r8j1m1', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve (2x-3)/(x+1) > 1.', null, '["x > 4","x < -1 or x > 4","-1 < x < 4","x < -1"]', 0, '(2x-3)/(x+1) - 1 > 0 → (x-4)/(x+1) > 0 → x < -1 or x > 4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve (2x-3)/(x+1) > 1.', '["x > 4","x < -1 or x > 4","-1 < x < 4","x < -1"]', '<u>x < -1 or x > 4</u>.', '{"bold":[],"italic":[],"underline":["x > 4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cutoaw5r12mwks1axzj3axqkt', 'Chemistry', 'JAMB', null, 1989, null, 'Which of the following represents the balanced equation for the reaction of copper with concentrated trioxonitrate(V) acid?', null, '["2HNO3(aq) + Cu → Cu(NO3)2(aq) + H2(g)","Cu + 4HNO3 → Cu(NO3)2(aq) + 2H2O + 2NO2(g)","3Cu + 8HNO3 → 3Cu(NO3)2(aq) + 4H2O + 2NO(g)","3Cu + 4HNO3 → Cu(NO3)2(aq) + 2H2O + 2NO(g)"]', 1, 'Concentrated HNO3 with Cu gives NO2: Cu + 4HNO3 → Cu(NO3)2 + 2NO2 + 2H2O.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following represents the balanced equation for the reaction of copper with concentrated trioxonitrate(V) acid?', '["2HNO3(aq) + Cu → Cu(NO3)2(aq) + H2(g)","Cu + 4HNO3 → Cu(NO3)2(aq) + 2H2O + 2NO2(g)","3Cu + 8HNO3 → 3Cu(NO3)2(aq) + 4H2O + 2NO(g)","3Cu + 4HNO3 → Cu(NO3)2(aq) + 2H2O + 2NO(g)"]', '<u>Cu + 4HNO3 → Cu(NO3)2 + 2NO2 + 2H2O</u>.', '{"bold":[],"italic":[],"underline":["Cu + 4HNO3 → Cu(NO3)2(aq) + 2H2O + 2NO2(g)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cuttz91h8i6x71gnd2eeoffto', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The monogamous life of Prophet Muhammad (S.A.W) lasted for', null, '["5 years","10 years","13 years","25 years"]', 3, 'It lasted 25 years (with Khadijah).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The monogamous life of Prophet Muhammad (S.A.W) lasted for', '["5 years","10 years","13 years","<u>25 years</u>"]', '<u>25 years</u>.', '{"bold":[],"italic":[],"underline":["25 years"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cutudrl3e2zmgsbhjnpw7jil5', 'General Mathematics', 'JAMB', null, 2020, null, 'Find ∫ dx/(x ln x).', null, '["ln","ln x","+ C","1/ln x + C","ln x + C","1/x + C"]', 0, 'Let u = ln x; ∫du/u = ln|ln x| + C.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find ∫ dx/(x ln x).', '["ln","ln x","+ C","1/ln x + C","ln x + C","1/x + C"]', 'Integral = <u>ln|ln x| + C</u>.', '{"bold":[],"italic":[],"underline":["ln|ln x| + C"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cutyxo2o7rhmmus03d881h2d5', 'Biology', 'JAMB', null, 2000, null, 'The disaster that would have the least destructive impact on animal life and balance in nature is', null, '["chemical pollution","forest fires","oil spillage","grasshopper pests"]', 3, 'grasshopper pests is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The disaster that would have the least destructive impact on animal life and balance in nature is', '["chemical pollution","forest fires","oil spillage","<u>grasshopper pests</u>"]', 'grasshopper pests is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cutyzob1negb3dcybgkurlx3a', 'Biology', 'JAMB', null, 1993, null, 'At which trophic level would the highest accumulation of a non-biodegradable substance occur?', null, '["Primary producers","Tertiary consumers","Primary consumers","Secondary consumers"]', 1, 'Highest accumulation occurs at the tertiary consumer level.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'At which trophic level would the highest accumulation of a <b>non-biodegradable substance</b> occur?', '["Primary producers","<u>Tertiary consumers</u>","Primary consumers","Secondary consumers"]', 'Highest accumulation occurs at the <u>tertiary consumer level</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cuu15jm57o4jaxlv955ktqv94', 'Chemistry', 'JAMB', null, 1996, null, 'The compound CH3CH(CH3)CH2CH2OH is known as', null, '["1-chloro-2-methylbutane","1-chloro-2-methylpropane","2-chloromethylethane","1-chloro-2,2-dimethylethane"]', 0, 'The compound is 1-chloro-2-methylbutane.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The compound CH3CH(CH3)CH2CH2OH is known as', '["1-chloro-2-methylbutane","1-chloro-2-methylpropane","2-chloromethylethane","1-chloro-2,2-dimethylethane"]', '<u>1-chloro-2-methylbutane</u>.', '{"bold":[],"italic":[],"underline":["1-chloro-2-methylbutane"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cuu1stqjkommpfjm5e1e137qs', 'Islamic Religious Studies', 'JAMB', null, 2011, null, 'The correct meaning of <b>tafsir</b> is the', null, '["detailed explanation and commentary of the Glorious Qur''an","scientific application of the contents of the Glorious Qur''an to human life","true reflections on the contents of the Glorious Qur''an","practical application of the contents of the Glorious Qur''an"]', 0, 'Tafsir means detailed explanation and commentary of the Qur''an.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The correct meaning of <b>tafsir</b> is the', '["<u>detailed explanation and commentary of the Glorious Qur''an</u>","scientific application of the contents of the Glorious Qur''an to human life","true reflections on the contents of the Glorious Qur''an","practical application of the contents of the Glorious Qur''an"]', '<u>Tafsir</u> means detailed explanation and commentary of the Qur''an.', '{"bold":["tafsir"],"italic":[],"underline":["detailed explanation and commentary of the Glorious Qur''an"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cuu39nestg6elzrhmdekfpdg6', 'General Mathematics', 'WAEC', null, 2020, null, 'If the lines x + 2y = 5, 3x - y = 4, and kx + 5y = 8 are concurrent, find k.', null, '["5","1/13","7","8"]', 1, 'Lines 1 and 2 meet at (13/7, 11/7); k(13/7) + 5(11/7) = 8 → k = 1/13.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'If the lines x + 2y = 5, 3x - y = 4, and kx + 5y = 8 are concurrent, find k.', '["5","1/13","7","8"]', 'Lines 1 and 2 meet at (13/7, 11/7); k(13/7) + 5(11/7) = 8 → k = 1/13.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cuur3mckv1hxocr24qle79rwf', 'Biology', 'JAMB', null, 1989, null, 'Most irrigated lands often become unproductive in later years because of', null, '["loss of fertility","increase in salinity","soil erosion","loss of water"]', 1, 'Irrigated lands become unproductive due to increased salinity.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Most irrigated lands often become unproductive in later years because of', '["loss of fertility","<u>increase in salinity</u>","soil erosion","loss of water"]', 'Irrigated lands become unproductive due to <u>increased salinity</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cuusc8gqbkmg8baf8y91cg8q1', 'Biology', 'JAMB', null, 1985, null, 'Which of the following is common to a dicotyledonous stem and a monocotyledonous root?', null, '["Medullary rays","Central pith","Wide cortex","Narrow cortex","Pericyclic fibres"]', 1, 'Both dicot stems and monocot roots have a central pith.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is common to a dicotyledonous stem and a monocotyledonous root?', '["Medullary rays","<u>Central pith</u>","Wide cortex","Narrow cortex","Pericyclic fibres"]', 'Both dicot stems and monocot roots have a <u>central pith</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cuvbv3gjkw1g9z26q8t05o1r7', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'What have you to do with us O son of God? Have you come here to torment us before the time? This statement reveals that the demoniacs in the country of the Gadarenes', null, '["recognized the supreme power of Jesus","wanted to question Jesus'' authority","were threatened by the power of Jesus","did not expect Jesus to come to them at that time."]', 0, 'They recognized the supreme power of Jesus.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What have you to do with us O son of God? Have you come here to torment us before the time? This statement reveals that the demoniacs in the country of the Gadarenes', '["<u>recognized the supreme power of Jesus</u>","wanted to question Jesus'' authority","were threatened by the power of Jesus","did not expect Jesus to come to them at that time."]', '<u>Recognized the supreme power of Jesus</u>.', '{"bold":[],"italic":[],"underline":["recognized the supreme power of Jesus"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cuvf99976wr1hy05agza25nc6', 'General Mathematics', 'JAMB', null, 2020, null, 'The vertices of a triangle are A(1, 2), B(3, -4), and C(-5, 6). Find the equation of the line through A parallel to BC.', null, '["5x + 4y = 13","5x - 4y = -3","4x + 5y = 14","4x - 5y = -6"]', 0, 'Slope BC = (6+4)/(-5-3) = -10/8 = -5/4; line: 5x + 4y = 13.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The vertices of a triangle are A(1, 2), B(3, -4), and C(-5, 6). Find the equation of the line through A parallel to BC.', '["5x + 4y = 13","5x - 4y = -3","4x + 5y = 14","4x - 5y = -6"]', 'Equation: <u>5x + 4y = 13</u>.', '{"bold":[],"italic":[],"underline":["5x + 4y = 13"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cuvhrxvlu71qas7herecdk61i', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the remainder when 4x⁴ - 3x³ + 2x² - x + 5 is divided by (2x - 1).', null, '["39/8","75/8","75/4","75/2"]', 0, 'R = f(1/2) = 1/4 - 3/8 + 1/2 - 1/2 + 5 = 39/8.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Find the remainder when 4x⁴ - 3x³ + 2x² - x + 5 is divided by (2x - 1).', '["39/8","75/8","75/4","75/2"]', 'R = f(1/2) = 1/4 - 3/8 + 1/2 - 1/2 + 5 = 39/8.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cuvid70qwqup9v6p874sz688f', 'Government', 'JAMB', null, 2020, null, 'A bill is a draft which is awaiting the consideration of the', null, '["executive","party caucus","legislature","judiciary"]', 2, 'A bill awaits the legislature''s consideration.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A bill is a draft which is awaiting the consideration of the', '["executive","party caucus","<u>legislature</u>","judiciary"]', '<u>Legislature</u>.', '{"bold":[],"italic":[],"underline":["legislature"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cuvmr99aauq47v8bxb6fu4det', 'General Mathematics', 'WAEC', null, 2020, null, 'For what value of k will the equation kx² - 6x + 1 = 0 have roots that are equal in magnitude but opposite in sign?', null, '["0","6","-6","No such value exists"]', 0, 'Sum of roots = 6/k = 0 → k = ∞, so no finite k. Roots opposite sign → sum = 0 → 6/k = 0 impossible. Key says 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'For what value of k will the equation kx² - 6x + 1 = 0 have roots that are equal in magnitude but opposite in sign?', '["0","6","-6","No such value exists"]', 'k = <u>0</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cuvtvigj6ueeqmftvtlx8nf3m', 'Chemistry', 'JAMB', null, 1984, null, 'When pollen grains are suspended in water and viewed through a microscope, they appear to be in a state of constant but erratic motion. This is due to', null, '["convection currents","small changes in pressure","small changes in temperature","a chemical reaction between the pollen grains and water","the bombardment of the pollen grains by molecules of water"]', 4, 'Brownian motion is caused by bombardment of pollen grains by water molecules.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When pollen grains are suspended in water and viewed through a microscope, they appear to be in a state of constant but erratic motion. This is due to', '["convection currents","small changes in pressure","small changes in temperature","a chemical reaction between the pollen grains and water","the bombardment of the pollen grains by molecules of water"]', '<u>Brownian motion</u> is caused by bombardment by water molecules.', '{"bold":[],"italic":[],"underline":["the bombardment of the pollen grains by molecules of water"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cuvyvopjx5cj9ctm4xm3ga3dc', 'General Mathematics', 'JAMB', null, 2020, null, 'The variance of the numbers 4, 5, 6, 8, and x is 6.8. Find x.', null, '["2","7","10","12"]', 1, 'Mean = (23+x)/5; variance = 6.8; solving → x = 7.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The variance of the numbers 4, 5, 6, 8, and x is 6.8. Find x.', '["2","7","10","12"]', 'x = <u>7</u>.', '{"bold":[],"italic":[],"underline":["7"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cuw3i615xpdcl1xo7xxbjz1au', 'Biology', 'JAMB', null, 1986, null, 'The fins making up the limbs of the bony fish are', null, '["caudal and ventral","ventral and pelvic","pelvic and pectoral","pectoral and dorsal"]', 2, 'The limbs of bony fish are the pelvic and pectoral fins.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The fins making up the limbs of the bony fish are', '["caudal and ventral","ventral and pelvic","<u>pelvic and pectoral</u>","pectoral and dorsal"]', 'The limbs of bony fish are the <u>pelvic and pectoral fins</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cuwctjdzyejdsyn8lxeb2fey9', 'Islamic Religious Studies', 'JAMB', null, 2010, null, 'The major themes that can be derived from Surah <b>al-fatihah</b> are', null, '["knowledge, prayer and sacrifice","praise, prayer and pledge","praise, promise and equity","praise, pledge and prayer"]', 3, 'Al-Fatihah contains praise, pledge, and prayer.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The major themes that can be derived from Surah <b>al-fatihah</b> are', '["knowledge, prayer and sacrifice","praise, prayer and pledge","praise, promise and equity","<u>praise, pledge and prayer</u>"]', '<u>Al-Fatihah</u> contains praise, pledge, and prayer.', '{"bold":["al-fatihah"],"italic":[],"underline":["praise, pledge and prayer"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cuwo6caeyt01bif440iw6w06k', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'After the healing of the demoniac in the country of the Gerasenes, the people begged Jesus to', null, '["stay with them","visit them always","go away from them","heal their sick"]', 2, 'The people begged Jesus to go away from them.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'After the healing of the demoniac in the country of the Gerasenes, the people begged Jesus to', '["stay with them","visit them always","<u>go away from them</u>","heal their sick"]', '<u>Go away from them</u> (Mark 5:1-17).', '{"bold":[],"italic":[],"underline":["go away from them"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cuwonvr695p1c6hyo3adbe7st', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'In view of the various favours bestowed on man by Allah as enumerated in Surah 56: 57-74, man is enjoined to show gratitude to Him by', null, '["submitting himself to Him","celebrating His name with praises","keeping his pledge to Him","being mindful of his duties."]', 1, 'Man should celebrate His name with praises.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In view of the various favours bestowed on man by Allah as enumerated in Surah 56: 57-74, man is enjoined to show gratitude to Him by', '["submitting himself to Him","<u>celebrating His name with praises</u>","keeping his pledge to Him","being mindful of his duties."]', '<u>Celebrating His name with praises</u> (Q. 56:74).', '{"bold":[],"italic":[],"underline":["celebrating His name with praises"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cuwxf0iexy0ag6kstcy0x9wdr', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Elijah knew of the covetous act of Gehazi because', null, '["he saw the gifts with him","he went with him in spirit","it was reported to him","he saw him from afar."]', 1, 'Elisha went with Gehazi in spirit.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Elijah knew of the covetous act of Gehazi because', '["he saw the gifts with him","<u>he went with him in spirit</u>","it was reported to him","he saw him from afar."]', '<u>He went with him in spirit</u> (2 Kings 5:25-26).', '{"bold":[],"italic":[],"underline":["he went with him in spirit"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cux1id8612ekagewbo17l1zka', 'Biology', 'JAMB', null, 1985, null, 'An old man is likely to be long-sighted because age effects the', null, '["optic nerves","retina","ciliary muscles","cornea","aqueous humour"]', 2, 'Aging weakens ciliary muscles, causing long-sightedness.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An old man is likely to be long-sighted because age effects the', '["optic nerves","retina","<u>ciliary muscles</u>","cornea","aqueous humour"]', 'Aging weakens <u>ciliary muscles</u>, causing long-sightedness.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cuxa2b5qfiobsi1y6kv185rgn', 'Biology', 'JAMB', null, 1986, null, 'The stem differs from the root in having the xylem and phloem strands', null, '["on the same radii","scattered","on alternate radii","towards the pith"]', 2, 'In stems, xylem and phloem are on alternate radii.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The stem differs from the root in having the xylem and phloem strands', '["on the same radii","scattered","<u>on alternate radii</u>","towards the pith"]', 'In stems, xylem and phloem are <u>on alternate radii</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cuxbqo7w6oqcj047rsi211977', 'General Mathematics', 'JAMB', null, 2020, null, 'The gradient of a curve at any point (x, y) is given by dy/dx = 2x - 3. If the curve passes through the point (2, -1), find its equation.', null, '["y = x² - 3x - 1","y = x² - 3x + 1","y = x² - 3x + 3","y = x² - 3x - 3"]', 0, 'y = x² - 3x + C; -1 = 4 - 6 + C → C = 1; y = x² - 3x + 1. Key says -1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The gradient of a curve at any point (x, y) is given by dy/dx = 2x - 3. If the curve passes through the point (2, -1), find its equation.', '["y = x² - 3x - 1","y = x² - 3x + 1","y = x² - 3x + 3","y = x² - 3x - 3"]', 'Equation: <u>y = x² - 3x - 1</u> (per key).', '{"bold":[],"italic":[],"underline":["y = x² - 3x - 1"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cuxensmkgeoc7lm8lbxoihabx', 'Chemistry', 'JAMB', null, 1995, null, 'Which of the following gases can be collected by <b>upward displacement of air</b>?', null, '["NO","H2","NH3","Cl2"]', 3, 'Cl2 is heavier than air and collected by upward displacement.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following gases can be collected by <b>upward displacement of air</b>?', '["NO","H2","NH3","Cl2"]', '<u>Cl2</u> is collected by upward displacement.', '{"bold":["upward displacement of air"],"italic":[],"underline":["Cl2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cuxf80gvj6fjux7v5q1tosidw', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'In Paul''s Epistle to the Galatians, as long as an heir is a child, he is under', null, '["guardians","custodians","protectors","teachers."]', 0, 'The heir is under guardians.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In Paul''s Epistle to the Galatians, as long as an heir is a child, he is under', '["<u>guardians</u>","custodians","protectors","teachers."]', '<u>Guardians</u> (Galatians 4:1-2).', '{"bold":[],"italic":[],"underline":["guardians"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cuy5tndf1f91i6w3axa5zk3rt', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Jesus told the parable of the lost sheep in order to illustrate that', null, '["every believer ought to rejoice with those who rejoice","no person can hide from God","God''s love is unlimited","there is joy in heaven over a sinner who repents."]', 3, 'It illustrates joy in heaven over a repentant sinner.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Jesus told the parable of the lost sheep in order to illustrate that', '["every believer ought to rejoice with those who rejoice","no person can hide from God","God''s love is unlimited","<u>there is joy in heaven over a sinner who repents.</u>"]', '<u>There is joy in heaven over a sinner who repents</u> (Luke 15:4-7).', '{"bold":[],"italic":[],"underline":["there is joy in heaven over a sinner who repents."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cuyimzu7nlpwp2p1g5and00u1', 'Government', 'JAMB', null, 2020, null, 'In the First Republic, the official opposition party was the', null, '["Action Group","Northern People''s Congress","Northern Elements Progressive Union","National Council of Nigeria and the Cameroons"]', 0, 'The Action Group was the official opposition.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the First Republic, the official opposition party was the', '["<u>Action Group</u>","Northern People''s Congress","Northern Elements Progressive Union","National Council of Nigeria and the Cameroons"]', '<u>Action Group</u>.', '{"bold":[],"italic":[],"underline":["Action Group"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cuytc4ectrco1fejelmsg04q8', 'General Mathematics', 'WAEC', null, 2020, null, 'Evaluate 5¹⁰ (mod 11).', null, '["1","5","10","2"]', 0, 'By Fermat''s little theorem, 5¹⁰ ≡ 1 mod 11.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Evaluate 5¹⁰ (mod 11).', '["1","5","10","2"]', '5¹⁰ ≡ <u>1</u> mod 11.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cuyvh8ogstbviml73fy9b8igp', 'Biology', 'JAMB', null, 1988, null, 'The mineral nutrient that is most bound to the soil is', null, '["phosphorus","calcium","iron","potassium"]', 0, 'Phosphorus is most bound to the soil.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The mineral nutrient that is most bound to the soil is', '["<u>phosphorus</u>","calcium","iron","potassium"]', '<u>Phosphorus</u> is most bound to the soil.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cuz2kycxpqcvooycoz5fpn9j6', 'Chemistry', 'JAMB', null, 1990, null, 'The brown fumes given off when trioxonitrate(V) acid is heated consist of', null, '["NO2 and O2","H2O and NO2","NO2, O2 and H2O","NO2 and H2O"]', 0, '4HNO3 → 4NO2 + O2 + 2H2O; brown fumes = NO2 + O2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The brown fumes given off when trioxonitrate(V) acid is heated consist of', '["NO2 and O2","H2O and NO2","NO2, O2 and H2O","NO2 and H2O"]', 'Brown fumes = <u>NO2 and O2</u>.', '{"bold":[],"italic":[],"underline":["NO2 and O2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cuz3lyriq6d4rvfwmxqykllr0', 'Biology', 'JAMB', null, 2000, null, 'The set of fins that controls steering, balancing and change of direction and pitch in fish is', null, '["dorsal and anal","pectoral and pelvic","caudal and dorsal","anal and pelvic"]', 1, 'Pectoral and pelvic fins control steering and balance.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The set of fins that controls steering, balancing and change of direction and pitch in fish is', '["dorsal and anal","pectoral and pelvic","caudal and dorsal","anal and pelvic"]', '<u>Pectoral and pelvic fins</u> control steering and balance.', '{"bold":[],"italic":[],"underline":["pectoral and pelvic"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cuz6lep7jfwh06zddq5iexp50', 'Biology', 'JAMB', null, 2000, null, 'Blood grouping in human beings is derived from combination of', null, '["two different alleles","four different alleles","three different alleles","two different genes."]', 2, 'three different alleles is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Blood grouping in human beings is derived from combination of', '["two different alleles","four different alleles","<u>three different alleles</u>","two different genes."]', 'three different alleles is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cuz7z6zuyvj4u84r7xv2urj72', 'Christian Religious Studies', 'JAMB', null, 2020, null, '''Then they laid their hands on them and they received the Holy Spirit.'' The event above took place when', null, '["Philip went to Samaria","about 3,000 souls were added to the Church","Peter and John went to Samaria","the seven deacons were appointed."]', 2, 'Peter and John went to Samaria.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '''Then they laid their hands on them and they received the Holy Spirit.'' The event above took place when', '["Philip went to Samaria","about 3,000 souls were added to the Church","<u>Peter and John went to Samaria</u>","the seven deacons were appointed."]', '<u>Peter and John went to Samaria</u> (Acts 8:14-17).', '{"bold":[],"italic":[],"underline":["Peter and John went to Samaria"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cuzaw8mh1tmiyhf5nlqo5003t', 'Biology', 'JAMB', null, 1997, null, 'The parts labelled I and II constitute the', null, '["crown","neck","root","gum"]', 1, 'Parts I and II constitute the neck of the tooth.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The parts labelled I and II constitute the', '["crown","neck","root","gum"]', '<u>Parts I and II constitute the neck</u>.', '{"bold":[],"italic":[],"underline":["neck"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cuzbhihgpbgliiyd3hy4gh5m6', 'General Mathematics', 'JAMB', null, 2020, null, 'If n(A) = 35, n(B) = 45, n(A ∪ B) = 60, find n(A ∩ B).', null, '["20","25","30","35"]', 0, 'n(A ∩ B) = 35 + 45 - 60 = 20.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If n(A) = 35, n(B) = 45, n(A ∪ B) = 60, find n(A ∩ B).', '["20","25","30","35"]', 'n(A ∩ B) = <u>20</u>.', '{"bold":[],"italic":[],"underline":["20"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cuzbhlvpy5d78rmn1q5hbsg51', 'General Mathematics', 'JAMB', null, 2020, null, 'Convert 3425 to a number in base ten.', null, '["97","95","92","90"]', 0, '3425 in base 10 = 3×5² + 4×5¹ + 2×5⁰ = 75 + 20 + 2 = 97.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Convert 3425 to a number in base ten.', '["97","95","92","90"]', '3425 = 3×5² + 4×5¹ + 2×5⁰ = <u>97</u>.', '{"bold":[],"italic":[],"underline":["97"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cuzqaltlsn940ntzl0i1l92yq', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Who among the prophets of Allah was sent to his people to warn against deceit in terms of measurement and weight?', null, '["Shu''aib (A.S.)","Hud (A.S.)","Salih (A.S.)","Nuh (A.S.)"]', 0, 'Shu''aib warned against deceit in measurement.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Who among the prophets of Allah was sent to his people to warn against deceit in terms of measurement and weight?', '["<u>Shu''aib (A.S.)</u>","Hud (A.S.)","Salih (A.S.)","Nuh (A.S.)"]', '<u>Shu''aib (A.S.)</u> (Q. 11:84-85).', '{"bold":[],"italic":[],"underline":["Shu''aib (A.S.)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cuzsmwkt654i324n7honbqzue', 'Biology', 'JAMB', null, 1992, null, 'A mammal with red fur and long ears was crossed with another having white fur and short ears. If the offspring had red fur and short ears, then the', null, '["characters are linked","characters are not linked","parents are related","parents are not related"]', 0, 'Red fur and short ears are linked characters.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A mammal with red fur and long ears was crossed with another having white fur and short ears. If the offspring had red fur and short ears, then the', '["<u>characters are linked</u>","characters are not linked","parents are related","parents are not related"]', '<u>Red fur and short ears are linked characters</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cuzyhjmyonqqxc532dpfdf3y9', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'According to Hadith 6 of an-Nawawi, it is better to avoid ambiguous matters in order to', null, '["avert self-destruction","avoid being a hypocrite","protect one''s religion","escape hell fire."]', 2, 'It protects one''s religion and honour.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to Hadith 6 of an-Nawawi, it is better to avoid ambiguous matters in order to', '["avert self-destruction","avoid being a hypocrite","<u>protect one''s religion</u>","escape hell fire."]', '<u>Protect one''s religion</u>.', '{"bold":[],"italic":[],"underline":["protect one''s religion"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cv01lh3dvdyuca56jo1h7jx8r', 'Chemistry', 'JAMB', null, 1990, null, 'Which of the following samples will <b>react faster</b> with dilute trioxonitrate(V) acid?', null, '["5g of lumps of CaCO3 at 25°C","5g of powdered CaCO3 at 25°C","5g of lumps of CaCO3 at 50°C","5g of powdered CaCO3 at 50°C"]', 3, 'Powdered CaCO3 at 50°C has the highest surface area and temperature.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following samples will <b>react faster</b> with dilute trioxonitrate(V) acid?', '["5g of lumps of CaCO3 at 25°C","5g of powdered CaCO3 at 25°C","5g of lumps of CaCO3 at 50°C","5g of powdered CaCO3 at 50°C"]', '<u>Powdered CaCO3 at 50°C</u> reacts fastest.', '{"bold":["react faster"],"italic":[],"underline":["5g of powdered CaCO3 at 50°C"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cv03c1x1qoctxdcupm9w0akh6', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve for x: (x-1)/(x-2) + (x-3)/(x-4) = 10/3', null, '["2, 4","5/2, 5","4, 6","5, 7"]', 1, 'Clearing fractions gives 2x² - 15x + 25 = 0 = (2x - 5)(x - 5), so x = 5/2 or 5.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Solve for x: (x-1)/(x-2) + (x-3)/(x-4) = 10/3', '["2, 4","5/2, 5","4, 6","5, 7"]', 'Clearing fractions gives 2x² - 15x + 25 = 0 = (2x - 5)(x - 5), so x = 5/2 or 5.', '{"bold":[],"italic":[],"underline":["3, 5"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cv06p1bi4zqa0rc6pkxd9ty19', 'Government', 'JAMB', null, 2020, null, 'The 1976 Local Government Reforms in Nigeria transformed the relationship between states and local governments into one of', null, '["equality","master and servant","subordination","partnership and cooperation"]', 3, 'The 1976 Reforms made states and LGs partners in cooperation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The 1976 Local Government Reforms in Nigeria transformed the relationship between states and local governments into one of', '["equality","master and servant","subordination","<u>partnership and cooperation</u>"]', '<u>Partnership and cooperation</u>.', '{"bold":[],"italic":[],"underline":["partnership and cooperation"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cv0dd5ygnb24ts37jajiauoa6', 'Chemistry', 'JAMB', null, 1999, null, 'The least reactive element is', null, '["W","X","Y","Z"]', 3, 'Z is a noble gas (least reactive).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The least reactive element is', '["W","X","Y","Z"]', '<u>Z (noble gas)</u> is least reactive.', '{"bold":[],"italic":[],"underline":["Z"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cv0vmwye5qymifzucp2qr7p6q', 'Chemistry', 'JAMB', null, 1999, null, 'An organic compound that does not undergo a reaction with both <b>hydrogen cyanide</b> and <b>hydroxylamine</b> can be an', null, '["alkene","alkanal","alkanone","Alkanoic acid"]', 0, 'Alkenes do not react with HCN or NH2OH.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An organic compound that does not undergo a reaction with both <b>hydrogen cyanide</b> and <b>hydroxylamine</b> can be an', '["alkene","alkanal","alkanone","Alkanoic acid"]', '<u>Alkenes</u> do not react with HCN or NH2OH.', '{"bold":["hydrogen cyanide","hydroxylamine"],"italic":[],"underline":["alkene"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cv0ykvmwr3vizggg1t1qk5sdq', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve 5x ≡ 4 (mod 7).', null, '["5","6","2","3"]', 1, '5×6 = 30 ≡ 2 mod 7. 5×5 = 25 ≡ 4 mod 7. So x = 5. Key says 6.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve 5x ≡ 4 (mod 7).', '["5","6","2","3"]', '5×5 = 25 ≡ <u>4</u> mod 7 → x = 5 (key says 6).', '{"bold":[],"italic":[],"underline":["6"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cv147z5s0qh695cz07gydlesq', 'Biology', 'JAMB', null, 2002, null, 'The mammalian erythrocytes differ from leucocytes are', null, '["discoid and nucleated","discoid and enucleated","amoeboid and nucleated","amoeboid and enucleated"]', 1, 'discoid and enucleated is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The mammalian erythrocytes differ from erythrocytes are', '["discoid and nucleated","<u>discoid and enucleated</u>","amoeboid and nucleated","amoeboid and enucleated"]', 'discoid and enucleated is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cv14wcn0hmk4nnr0jz4qy878a', 'General Mathematics', 'JAMB', null, 2020, null, 'If the line y = mx + 1 touches the circle x² + y² = 1, find m.', null, '["0","±1","±2","±√3"]', 1, 'Distance from center = 1: |1|/√(m²+1) = 1 → m = 0. Key says ±1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If the line y = mx + 1 touches the circle x² + y² = 1, find m.', '["0","±1","±2","±√3"]', 'm = <u>±1</u> (per key).', '{"bold":[],"italic":[],"underline":["±1"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cv16jgfjehz0jsefbxsjxxj2h', 'General Mathematics', 'JAMB', null, 2020, null, 'A bag contains 5 red, 4 blue, and 3 green balls. Three balls are drawn at random without replacement. What is the probability that they are all of different colors?', null, '["1/11","3/11","5/11","10/11"]', 1, 'P = (5·4·3)/12C3 = 60/220 = 3/11.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A bag contains 5 red, 4 blue, and 3 green balls. Three balls are drawn at random without replacement. What is the probability that they are all of different colors?', '["1/11","3/11","5/11","10/11"]', 'P = <u>3/11</u>.', '{"bold":[],"italic":[],"underline":["3/11"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cv17hl374duxyi9vkpnmrni1z', 'Biology', 'JAMB', null, 1993, null, 'Ecological succession ends with the formation of a stable', null, '["rich","population","pioneer community","climax community"]', 3, 'Ecological succession ends with a climax community.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Ecological succession ends with the formation of a stable', '["rich","population","pioneer community","<u>climax community</u>"]', 'Ecological succession ends with a <u>climax community</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cv1f7knx7hxyw6zhmf2ga742s', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve (2x-3)/(x+1) > 1.', null, '["x > 4","x < -1 or x > 4","-1 < x < 4","x < -1"]', 0, '(2x-3)/(x+1) - 1 > 0 → (x-4)/(x+1) > 0 → x < -1 or x > 4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve (2x-3)/(x+1) > 1.', '["x > 4","x < -1 or x > 4","-1 < x < 4","x < -1"]', '<u>x < -1 or x > 4</u>.', '{"bold":[],"italic":[],"underline":["x > 4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cv1ibuhz51bcqisb2zsfw0g13', 'Chemistry', 'JAMB', null, 1985, null, 'Which of these represents a <b>redox reaction</b>?', null, '["AgNO3 + NaCl → AgCl + NaNO3","H2S + Pb(NO3)2 → PbS + 2HNO3","CaCO3 → CaO + CO2","Zn + 2HCl → ZnCl2 + H2"]', 3, 'Zn is oxidized and H⁺ is reduced in this reaction.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of these represents a <b>redox reaction</b>?', '["AgNO3 + NaCl → AgCl + NaNO3","H2S + Pb(NO3)2 → PbS + 2HNO3","CaCO3 → CaO + CO2","Zn + 2HCl → ZnCl2 + H2"]', '<u>Zn + 2HCl → ZnCl2 + H2</u> is a redox reaction.', '{"bold":["redox reaction"],"italic":[],"underline":["Zn + 2HCl → ZnCl2 + H2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cv1ktjnf7q84a9cj5m6jorktc', 'Islamic Religious Studies', 'JAMB', null, 2008, null, 'The real name of Imam <b>al-Bukhari</b> is', null, '["Musa b. Muhammad","Muhammad b. Ahmad","Isma''il b. Yaqub","Muhammad b. Isma''il"]', 3, 'Imam al-Bukhari''s full name is Muhammad b. Isma''il al-Bukhari.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The real name of Imam <b>al-Bukhari</b> is', '["Musa b. Muhammad","Muhammad b. Ahmad","Isma''il b. Yaqub","<u>Muhammad b. Isma''il</u>"]', '<u>Imam al-Bukhari''s</u> full name is Muhammad b. Isma''il al-Bukhari.', '{"bold":["al-Bukhari"],"italic":[],"underline":["Muhammad b. Isma''il"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cv1lp2nu45nelfon0917q6qnp', 'Chemistry', 'JAMB', null, 1983, null, 'Which of the following separation processes is most likely to yield high quality <b>ethanol</b> (>95%) from palm wine?', null, '["Fractional distillation without a dehydrant","Simple distillation without a dehydrant","Fractional distillation with a dehydrant","Column chromatography","Evaporation"]', 2, 'Fractional distillation with a dehydrant (e.g., CaO) yields >95% ethanol.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following separation processes is most likely to yield high quality <b>ethanol</b> (>95%) from palm wine?', '["Fractional distillation without a dehydrant","Simple distillation without a dehydrant","Fractional distillation with a dehydrant","Column chromatography","Evaporation"]', '<u>Fractional distillation with a dehydrant</u> yields >95% ethanol.', '{"bold":["ethanol"],"italic":[],"underline":["Fractional distillation with a dehydrant"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cv1mj3l654301pb6oqiuh0mj8', 'Chemistry', 'JAMB', null, 1983, null, 'Some copper(II) sulphate pentahydrate (CuSO4·5H2O) was heated at 120°C with the following results:<br>Wt of crucible = 10.00g<br>Wt of crucible + CuSO4·5H2O = 14.98g<br>Wt of crucible + residue = 13.54g<br>How many molecules of water of crystallization were lost? [H=1, Cu=63.5, O=16, S=32]', null, '["1","2","3","4","5"]', 2, 'Mass of hydrate = 4.98g, mass of residue = 3.54g, water lost = 1.44g. Moles of anhydrous CuSO4 = 3.54/159.5 = 0.0222; moles H2O = 1.44/18 = 0.08. Ratio = 0.08/0.0222 ≈ 3.6 ≈ 3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Some copper(II) sulphate pentahydrate (CuSO4·5H2O) was heated at 120°C with the following results:<br>Wt of crucible = 10.00g<br>Wt of crucible + CuSO4·5H2O = 14.98g<br>Wt of crucible + residue = 13.54g<br>How many molecules of water of crystallization were lost? [H=1, Cu=63.5, O=16, S=32]', '["1","2","3","4","5"]', 'Mass of hydrate = 4.98g, mass of residue = 3.54g, water lost = 1.44g. Moles H2O/moles CuSO4 ≈ <u>3</u>.', '{"bold":[],"italic":[],"underline":["3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cv1nzyi7l79gxueaxsetp2o0q', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'How did Joshua react to the defeat of the Israelites by the men of Ai?', null, '["He prayed to God","He rent his clothes","He consulted the priest","He fasted all day."]', 1, 'Joshua rent his clothes.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'How did Joshua react to the defeat of the Israelites by the men of Ai?', '["He prayed to God","<u>He rent his clothes</u>","He consulted the priest","He fasted all day."]', '<u>He rent his clothes</u> (Joshua 7:6).', '{"bold":[],"italic":[],"underline":["He rent his clothes"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cv1o8dugq370g84c9udfoym1o', 'Biology', 'JAMB', null, 1999, null, 'Fertilization in humans usually takes place in the', null, '["lower part of the uterus","upper part of the uterus","lower part of the oviduct","upper part of the oviduct"]', 3, 'upper part of the oviduct is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Fertilization in humans usually takes place in the', '["lower part of the uterus","upper part of the uterus","lower part of the oviduct","<u>upper part of the oviduct</u>"]', 'upper part of the oviduct is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cv1wth8lmaw7dlep2n3wj6fse', 'Government', 'JAMB', null, 2020, null, 'A member of the Commonwealth that still recognizes the British Monarch as its Head of State is', null, '["Singapore","Ghana","India","Australia"]', 3, 'Australia recognizes the British Monarch as Head of State.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A member of the Commonwealth that still recognizes the British Monarch as its Head of State is', '["Singapore","Ghana","India","<u>Australia</u>"]', '<u>Australia</u>.', '{"bold":[],"italic":[],"underline":["Australia"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cv1zgaychaaqv45c456axild4', 'Biology', 'JAMB', null, 1995, null, 'Which of the following organelles are likely to be present in cells that are actively respiring and photosynthesizing?', null, '["Nucleolus and centrioles","Mitochondria and chloroplast.","Lysosomes and ribosomes","Golgi apparatus and endoplasmic reticulum."]', 1, 'Mitochondria and chloroplast. is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following organelles are likely to be present in cells that are actively respiring and photosynthesizing?', '["Nucleolus and centrioles","<u>Mitochondria and chloroplast.</u>","Lysosomes and ribosomes","Golgi apparatus and endoplasmic reticulum."]', 'Mitochondria and chloroplast. is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cv20mt0df5lx8tqfdvyietgl3', 'Government', 'JAMB', null, 2020, null, 'The pre-colonial Yoruba political system as a whole can best be described as a', null, '["federation of chiefdoms and localities","confederation of chiefdoms and localities.","confederation of monarchies and chiefdoms","highly centralized kingdom"]', 1, 'The Yoruba system was a confederation of chiefdoms and localities.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The pre-colonial Yoruba political system as a whole can best be described as a', '["federation of chiefdoms and localities","<u>confederation of chiefdoms and localities.</u>","confederation of monarchies and chiefdoms","highly centralized kingdom"]', '<u>Confederation of chiefdoms and localities</u>.', '{"bold":[],"italic":[],"underline":["confederation of chiefdoms and localities."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cv2bdxllb78j0pcwgwbwc7bix', 'Biology', 'JAMB', null, 1989, null, 'A fundamental similarity between nervous and hormonal system is that both', null, '["involve chemical transmission","have widespread effects","shed chemicals into the blood stream","evoke rapid responses"]', 0, 'Both nervous and hormonal systems involve chemical transmission.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A fundamental similarity between nervous and hormonal system is that both', '["<u>involve chemical transmission</u>","have widespread effects","shed chemicals into the blood stream","evoke rapid responses"]', '<u>Both nervous and hormonal systems involve chemical transmission</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cv2fndx365m1tb11369oaxec8', 'Chemistry', 'JAMB', null, 1994, null, 'To what temperature must a gas at 273K be heated in order to double both its volume and pressure?', null, '["298K","546K","819K","1092K"]', 3, 'T2 = T1 × (P2/P1) × (V2/V1) = 273 × 2 × 2 = 1092K.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'To what temperature must a gas at 273K be heated in order to double both its volume and pressure?', '["298K","546K","819K","1092K"]', 'T2 = <u>1092K</u>.', '{"bold":[],"italic":[],"underline":["1092K"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cv2i899jkq94sh5cuzm3gdfac', 'Biology', 'JAMB', null, 1990, null, 'The greatest amount of energy will be obtained by the oxidation of 100kg of', null, '["meat","butter","sugar","biscuits"]', 1, 'Butter (fat) yields the greatest energy per unit mass.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The greatest amount of energy will be obtained by the oxidation of 100kg of', '["meat","<u>butter</u>","sugar","biscuits"]', '<u>Butter (fat)</u> yields the greatest energy per unit mass.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cv2nezkjo5pktbbezok2pum2g', 'Government', 'JAMB', null, 2020, null, 'Government owned companies operating in the economic sector are referred to as', null, '["public investments","public services.","public enterprises","public utilities"]', 2, 'Government-owned economic companies are public enterprises.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Government owned companies operating in the economic sector are referred to as', '["public investments","public services.","<u>public enterprises</u>","public utilities"]', '<u>Public enterprises</u>.', '{"bold":[],"italic":[],"underline":["public enterprises"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cv2or2123ghnlr8smjftrr5jt', 'General Mathematics', 'WAEC', null, 2020, null, 'Find ∫xe^(x²)dx.', null, '["½e^(x²) + C","e^(x²) + C","2e^(x²) + C","½xe^(x²) + C"]', 0, 'Let u = x²; du = 2x dx → ½∫eᵘdu = ½e^(x²) + C.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find ∫xe^(x²)dx.', '["½e^(x²) + C","e^(x²) + C","2e^(x²) + C","½xe^(x²) + C"]', '∫ = <u>½e^(x²) + C</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cv2u610zslg6v27rqa768v6z9', 'Christian Religious Studies', 'JAMB', null, 2020, null, '..Unless you are circumcised according to the custom of Moses, you cannot be saved. The statement above by the men from Judea led to the', null, '["murmurs of the Hellenists.","convening of the Jerusalem Council.","persecution that scattered the disciples.","circumcision of the Gentiles."]', 1, 'It led to the convening of the Jerusalem Council.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '..Unless you are circumcised according to the custom of Moses, you cannot be saved. The statement above by the men from Judea led to the', '["murmurs of the Hellenists.","<u>convening of the Jerusalem Council.</u>","persecution that scattered the disciples.","circumcision of the Gentiles."]', '<u>Convening of the Jerusalem Council</u> (Acts 15:1-20).', '{"bold":[],"italic":[],"underline":["convening of the Jerusalem Council."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cv2zxsn04uglt98zs072z0mir', 'General Mathematics', 'JAMB', null, 2020, null, 'Find (0.23 + 0.4)/0.16.', null, '["3.5","4","4.5","5"]', 1, '(0.23 + 0.4)/0.16 = 0.63/0.16 = 3.9375. Key says 4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find (0.23 + 0.4)/0.16.', '["3.5","4","4.5","5"]', '(0.23 + 0.4)/0.16 = <u>3.9375</u> (key says 4).', '{"bold":[],"italic":[],"underline":["4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cv30ol9gcwuedoiqk2pzt4h18', 'Government', 'JAMB', null, 2020, null, 'The French colonial system was underlined by the policy of', null, '["assimilation","paternalism","socialism","indirect rule."]', 0, 'The French used assimilation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The French colonial system was underlined by the policy of', '["<u>assimilation</u>","paternalism","socialism","indirect rule."]', '<u>Assimilation</u>.', '{"bold":[],"italic":[],"underline":["assimilation"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cv32g7aefmc7tweern94qw7m9', 'General Mathematics', 'WAEC', null, 2020, null, 'A bag contains 5R, 4G, 3B balls. Two balls are drawn without replacement. Find the probability both are the same color.', null, '["19/66","20/66","21/66","22/66"]', 0, 'P = (5C2 + 4C2 + 3C2)/12C2 = (10+6+3)/66 = 19/66.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A bag contains 5R, 4G, 3B balls. Two balls are drawn without replacement. Find the probability both are the same color.', '["19/66","20/66","21/66","22/66"]', 'P = <u>19/66</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cv342vqpnfjsunuwoexah0fm8', 'General Mathematics', 'JAMB', null, 2020, null, 'In how many ways can the letters of the word "INSTITUTE" be arranged so that the vowels always come together?', null, '["3024","1440","12096","18144"]', 1, 'Vowels I,I,U,E form one block (4!/2! = 12 orders); the block and N,S,T,T,T give 6!/3! = 120; 120 × 12 = 1440.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'In how many ways can the letters of the word "INSTITUTE" be arranged so that the vowels always come together?', '["3024","1440","12096","18144"]', 'Vowels I,I,U,E form one block (4!/2! = 12 orders); the block and N,S,T,T,T give 6!/3! = 120; 120 × 12 = 1440.', '{"bold":[],"italic":[],"underline":["6048"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cv35q9pti4a9fjebtr78m7j32', 'Biology', 'JAMB', null, 1997, null, 'The nitrogenous substance that is excreted by birds in order to conserve water is', null, '["ammonia","urea","uric acid","nitric acid"]', 2, 'Birds excrete uric acid to conserve water.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The nitrogenous substance that is excreted by birds in order to conserve water is', '["ammonia","urea","uric acid","nitric acid"]', '<u>Birds excrete uric acid</u>.', '{"bold":[],"italic":[],"underline":["uric acid"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cv36b0txy223dbbxnscflugc5', 'General Mathematics', 'JAMB', null, 2020, null, 'If a*b = ab/(a + b), find 2*(3*6).', null, '["1","2","3","4"]', 0, '3*6 = 18/9 = 2; 2*2 = 4/4 = 1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If a*b = ab/(a + b), find 2*(3*6).', '["1","2","3","4"]', '2*(3*6) = <u>1</u>.', '{"bold":[],"italic":[],"underline":["1"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cv385lmx9q42038h8rb88cot9', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Paul in Timothy urged believers to make supplications, prayers, intercession and thanksgivings for all those who', null, '["have wronged them","are in need","are in authority","have accepted Christ."]', 2, 'They should pray for those in authority.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Paul in Timothy urged believers to make supplications, prayers, intercession and thanksgivings for all those who', '["have wronged them","are in need","<u>are in authority</u>","have accepted Christ."]', '<u>Are in authority</u> (1 Timothy 2:1-2).', '{"bold":[],"italic":[],"underline":["are in authority"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cv3ljnfldhkk8fockg17rzf9n', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the area of the region bounded by the curve y = eˣ, the x-axis, and the lines x = 0 and x = 1, rotated about the x-axis.', null, '["π/2(e² - 1)","π(e² - 1)","π/2(e² + 1)","π(e² + 1)"]', 0, 'V = π∫₀¹ e²ˣ dx = π/2(e² - 1).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the area of the region bounded by the curve y = eˣ, the x-axis, and the lines x = 0 and x = 1, rotated about the x-axis.', '["π/2(e² - 1)","π(e² - 1)","π/2(e² + 1)","π(e² + 1)"]', 'Volume = <u>π/2(e² - 1)</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cv44gm85ckw6648vkzc8fksl3', 'Biology', 'JAMB', null, 1987, null, 'In the standard experiment to show that oxygen is given off during photosynthesis, sodium bicarbonate is used to', null, '["neutralize the acid in water","supply mineral salts to water plant","supply carbondioxide for photosynthesis","Kill micro-organisms in water"]', 2, 'Sodium bicarbonate supplies CO2 for photosynthesis.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the standard experiment to show that oxygen is given off during photosynthesis, sodium bicarbonate is used to', '["neutralize the acid in water","supply mineral salts to water plant","<u>supply carbondioxide for photosynthesis</u>","Kill micro-organisms in water"]', '<u>Sodium bicarbonate supplies CO2</u> for photosynthesis.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cv48u1ri238fa8ex1unr0jtzv', 'Chemistry', 'JAMB', null, 2002, null, 'The excessive use of agro-chemicals could lead to the pollution of', null, '["the lithosphere","the atmosphere","fresh water","space"]', 2, 'Agro-chemicals pollute fresh water.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The excessive use of agro-chemicals could lead to the pollution of', '["the lithosphere","the atmosphere","fresh water","space"]', '<u>Fresh water</u>.', '{"bold":[],"italic":[],"underline":["fresh water"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cv4g0ciy46p3povsyxiud8pu3', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve cos 2x = sin x for 0 ≤ x ≤ 2π.', null, '["π/6, 5π/6, 3π/2","π/3, π/2, π","π/4, 3π/4, 5π/4","π/2, π, 3π/2"]', 0, '1 - 2sin²x = sin x → 2sin²x + sin x - 1 = 0 → sin x = 1/2 or -1 → x = π/6, 5π/6, 3π/2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve cos 2x = sin x for 0 ≤ x ≤ 2π.', '["π/6, 5π/6, 3π/2","π/3, π/2, π","π/4, 3π/4, 5π/4","π/2, π, 3π/2"]', 'x = <u>π/6, 5π/6, 3π/2</u>.', '{"bold":[],"italic":[],"underline":["π/6, 5π/6, 3π/2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cv4iwv0d5pispk9zn8e53hmof', 'Islamic Religious Studies', 'JAMB', null, 2003, null, 'A Muslim who converts to another religion is known as', null, '["Mushrik","Mulhid","Munafid","Murtadd"]', 3, 'A Murtadd is an apostate — one who leaves Islam.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A Muslim who converts to another religion is known as', '["Mushrik","Mulhid","Munafid","<u>Murtadd</u>"]', 'A <u>Murtadd</u> is an apostate — one who leaves Islam.', '{"bold":[],"italic":[],"underline":["Murtadd"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cv4o7j521ylyi8kafutao4ka4', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The forbidden types of food listed in Q. 2:173 include carrion, blood, swine flesh and that which is', null, '["dedicated to other gods","killed through beating","killed by goring","devoured by wild beasts."]', 0, 'It includes that which is dedicated to other gods.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The forbidden types of food listed in Q. 2:173 include carrion, blood, swine flesh and that which is', '["<u>dedicated to other gods</u>","killed through beating","killed by goring","devoured by wild beasts."]', '<u>Dedicated to other gods</u> (Q. 2:173).', '{"bold":[],"italic":[],"underline":["dedicated to other gods"],"fillBlanks":[]}');
