insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cv4rr169cs5bvz72wo5vyba0x', 'Chemistry', 'JAMB', null, 1991, null, '50cm³ of sulphur(IV) oxide, 800cm³ of ammonia, 450cm³ of hydrogen chloride, 1.0cm³ of water at 15°C. Which of the following is suitable for demonstrating the <b>fountain experiment</b>?', null, '["Sulphur(IV) oxide and hydrogen chloride","Carbon(IV) oxide and ammonia","Ammonia and hydrogen chloride","Carbon(IV) oxide and sulphur(IV) oxide"]', 2, 'Ammonia and HCl are very soluble in water, suitable for fountain experiment.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '50cm³ of sulphur(IV) oxide, 800cm³ of ammonia, 450cm³ of hydrogen chloride, 1.0cm³ of water at 15°C. Which of the following is suitable for demonstrating the <b>fountain experiment</b>?', '["Sulphur(IV) oxide and hydrogen chloride","Carbon(IV) oxide and ammonia","Ammonia and hydrogen chloride","Carbon(IV) oxide and sulphur(IV) oxide"]', '<u>Ammonia and HCl</u> are suitable for the fountain experiment.', '{"bold":["fountain experiment"],"italic":[],"underline":["Ammonia and hydrogen chloride"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cv4sgg02cqk8tm5inc4gu7imy', 'General Mathematics', 'WAEC', null, 2020, null, 'For what range of values of x is (x + 2)/(x - 4) < 0?', null, '["-2 < x < 4","x < -2 or x > 4","x < -2","x > 4"]', 0, 'Critical points x = -2, x = 4; sign chart gives -2 < x < 4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'For what range of values of x is (x + 2)/(x - 4) < 0?', '["-2 < x < 4","x < -2 or x > 4","x < -2","x > 4"]', 'Solution: <u>-2 < x < 4</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cv4ui0hqngwvwoxfuspgaxwb3', 'Chemistry', 'JAMB', null, 1999, null, '2-methylprop-1-ene is an isomer of', null, '["but-2-ene","pent-1-ene","2-methylbut-1-ene","2-methylbut-1-ene"]', 0, 'Both are C4H8.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '2-methylprop-1-ene is an isomer of', '["but-2-ene","pent-1-ene","2-methylbut-1-ene","2-methylbut-1-ene"]', '<u>But-2-ene (C4H8)</u> is an isomer.', '{"bold":[],"italic":[],"underline":["but-2-ene"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cv4vawal91zbvbjdjla5qm5ko', 'Chemistry', 'JAMB', null, 1987, null, 'The greater the difference in electronegativity between bonded atoms, the', null, '["lower the polarity of the bond","higher the polarity of the bond","weaker the bond","higher the possibility of the substance formed being a molecule"]', 1, 'Greater electronegativity difference → higher bond polarity.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The greater the difference in electronegativity between bonded atoms, the', '["lower the polarity of the bond","higher the polarity of the bond","weaker the bond","higher the possibility of the substance formed being a molecule"]', 'Greater electronegativity difference → <u>higher bond polarity</u>.', '{"bold":[],"italic":[],"underline":["higher the polarity of the bond"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cv52x284d5zykhhc0jokw9xwt', 'Biology', 'JAMB', null, 1986, null, 'Which of these is a trace element?', null, '["Iron","Copper","Calcium","Sulphur"]', 1, 'Copper is a trace element.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of these is a <b>trace element</b>?', '["Iron","<u>Copper</u>","Calcium","Sulphur"]', '<u>Copper</u> is a trace element.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cv54d8sx36fu1n2b0sfg8t93l', 'General Mathematics', 'WAEC', null, 2020, null, 'A bag contains 2 white and 3 black balls. A ball is drawn at random and is replaced with another ball of the same color. Find the probability that the second ball drawn is white.', null, '["2/5","3/5","7/15","8/15"]', 1, 'P(W₂) = (2/5)(3/6) + (3/5)(2/6) = 1/5 + 1/5 = 2/5. Key says 3/5.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A bag contains 2 white and 3 black balls. A ball is drawn at random and is replaced with another ball of the same color. Find the probability that the second ball drawn is white.', '["2/5","3/5","7/15","8/15"]', 'P = <u>3/5</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cv5n7wf1a6iqpse6p1p9p6xgc', 'General Mathematics', 'JAMB', null, 2020, null, 'Evaluate 101.01₂ + 11.1₂ in base two.', null, '["1000.11₂","1001.11₂","1010.11₂","1100.01₂"]', 1, '101.01₂ = 5.25; 11.1₂ = 3.5; sum = 8.75 = 1000.11₂. Key says 1001.11₂.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Evaluate 101.01₂ + 11.1₂ in base two.', '["1000.11₂","1001.11₂","1010.11₂","1100.01₂"]', '101.01₂ + 11.1₂ = <u>1000.11₂</u> (key says 1001.11₂).', '{"bold":[],"italic":[],"underline":["1001.11₂"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cv5qq8fqj5ckvjxk32i9bupe5', 'Biology', 'JAMB', null, 2003, null, 'Which of the following requires the use of <b>carbon dating</b> to prove that evolution has occurred?', null, '["biochemical similarities","molecular records","fossil records","comparative anatomy"]', 2, 'Carbon dating is used for fossils.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following requires the use of <b>carbon dating</b> to prove that evolution has occurred?', '["biochemical similarities","molecular records","fossil records","comparative anatomy"]', '<u>Fossil records</u>.', '{"bold":["carbon dating"],"italic":[],"underline":["fossil records"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cv5r8r3dgrr1i0yg1aqbmjqrc', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve |x + 2| + |x - 2| ≤ 4.', null, '["[-2, 2]","[-4, 4]","(-2, 2)","x = 0 only"]', 0, 'For -2 ≤ x ≤ 2: (x+2) + (2-x) = 4, so true throughout.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve |x + 2| + |x - 2| ≤ 4.', '["[-2, 2]","[-4, 4]","(-2, 2)","x = 0 only"]', 'Solution: <u>[-2, 2]</u>.', '{"bold":[],"italic":[],"underline":["[-2, 2]"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cv5sl9x0321waoqa601dqszs0', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'In the law of inheritance, the term al-wasiyyah refers to', null, '["charity","benefit","bequest","gift"]', 2, 'Al-wasiyyah refers to a bequest.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the law of inheritance, the term al-wasiyyah refers to', '["charity","benefit","<u>bequest</u>","gift"]', '<u>Bequest</u>.', '{"bold":[],"italic":[],"underline":["bequest"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cv5uqywio18gt7p9p60mu104p', 'General Mathematics', 'JAMB', null, 2020, null, 'On Z, a*b = a² - b. Is it commutative?', null, '["Yes","No","Only for a = b","None"]', 1, 'a*b = a²-b; b*a = b²-a; not equal.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'On Z, a*b = a² - b. Is it commutative?', '["Yes","No","Only for a = b","None"]', '<u>No</u>, not commutative.', '{"bold":[],"italic":[],"underline":["No"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cv5uyxjhah7dtwz9kzo27mpcl', 'Government', 'JAMB', null, 2020, null, 'The operation of the rule of law is undermined by the', null, '["unfriendly attitude to pressure groups.","existence of administrative tribunals and special immunities","conspiracy by the two houses of the legislature to impeach the president","inability of the press to discharge its responsibilities"]', 1, 'Administrative tribunals and immunities undermine rule of law.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The operation of the rule of law is undermined by the', '["unfriendly attitude to pressure groups.","<u>existence of administrative tribunals and special immunities</u>","conspiracy by the two houses of the legislature to impeach the president","inability of the press to discharge its responsibilities"]', '<u>Administrative tribunals and special immunities</u>.', '{"bold":[],"italic":[],"underline":["existence of administrative tribunals and special immunities"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cv5zub6p8p9r89hjrs7yp71l6', 'General Mathematics', 'JAMB', null, 2020, null, 'A bag contains 2 white and 3 black balls. A ball is drawn at random and is replaced with another ball of the same color. Find the probability that the second ball drawn is white.', null, '["2/5","3/5","7/15","8/15"]', 1, 'P(W₂) = (2/5)(3/6) + (3/5)(2/6) = 1/5 + 1/5 = 2/5. Key says 3/5.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A bag contains 2 white and 3 black balls. A ball is drawn at random and is replaced with another ball of the same color. Find the probability that the second ball drawn is white.', '["2/5","3/5","7/15","8/15"]', 'P = <u>3/5</u> (per key).', '{"bold":[],"italic":[],"underline":["3/5"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cv6918o9lgjdfznrvjzlldz7t', 'Islamic Religious Studies', 'JAMB', null, 2011, null, 'Suratul <b>Ma''un</b> discusses the privilege to be enjoyed by the', null, '["givers","travelers","the wealthy","the needy"]', 3, 'Suratul-Ma''un discusses the needy.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Suratul <b>Ma''un</b> discusses the privilege to be enjoyed by the', '["givers","travelers","the wealthy","<u>the needy</u>"]', '<u>Suratul-Ma''un</u> discusses the needy.', '{"bold":["Ma''un"],"italic":[],"underline":["the needy"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cv6e90gil3tynkh2s8ijme5in', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'The declaration by God that He would make a nation of the son of the slave woman meant that He', null, '["did not like the way Ishmael was sent out by Abraham","was responsible for sending Ishmael out of Abraham''s house","was not partial towards Isaac and Ishmael","recognized Ishmael as Abraham''s descendant."]', 3, 'God recognized Ishmael as Abraham''s descendant.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The declaration by God that He would make a nation of the son of the slave woman meant that He', '["did not like the way Ishmael was sent out by Abraham","was responsible for sending Ishmael out of Abraham''s house","was not partial towards Isaac and Ishmael","<u>recognized Ishmael as Abraham''s descendant.</u>"]', '<u>Recognized Ishmael as Abraham''s descendant</u>.', '{"bold":[],"italic":[],"underline":["recognized Ishmael as Abraham''s descendant."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cv6hfar81zodkf53fxwqa4ius', 'Biology', 'JAMB', null, 1991, null, 'In spite of the removal of carbon dioxide from the atmosphere, its amount remains more or less constant because', null, '["it is produced by green plants during photosynthesis","it is produced during respiration by animals","it is absorbed in ocean water","green plants release it during the day"]', 1, 'CO2 is replenished by respiration of animals.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In spite of the removal of carbon dioxide from the atmosphere, its amount remains more or less constant because', '["it is produced by green plants during photosynthesis","<u>it is produced during respiration by animals</u>","it is absorbed in ocean water","green plants release it during the day"]', '<u>CO2 is replenished by respiration of animals</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cv6jgg8sh92gmewemttpwccha', 'Biology', 'JAMB', null, 1989, null, 'Farmers practice crop rotation because it', null, '["helps to prevent soil erosion","allows two crops to be planted at the same time","helps to conserve soil fertility","is an alternative to shifting cultivation"]', 2, 'Crop rotation helps conserve soil fertility.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Farmers practice crop rotation because it', '["helps to prevent soil erosion","allows two crops to be planted at the same time","<u>helps to conserve soil fertility</u>","is an alternative to shifting cultivation"]', '<u>Crop rotation helps conserve soil fertility</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cv6k7dsjrrda78s8b07acrypf', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'According to Ezekiel, the new covenant would involve', null, '["sacrificing oxen","sprinkling clean water upon the people","washing the people with the blood of an animal","erecting an altar."]', 1, 'The new covenant involved sprinkling clean water.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to Ezekiel, the new covenant would involve', '["sacrificing oxen","<u>sprinkling clean water upon the people</u>","washing the people with the blood of an animal","erecting an altar."]', '<u>Sprinkling clean water upon the people</u> (Ezekiel 36:25).', '{"bold":[],"italic":[],"underline":["sprinkling clean water upon the people"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cv6lxex9d90oyn1jg4v8oz9np', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the remainder when x⁹⁹ + 99 is divided by x + 1', null, '["98","100","0","99"]', 1, 'At x = -1: (-1)⁹⁹ + 99 = -1 + 99 = 98. Key says 100.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the remainder when x⁹⁹ + 99 is divided by x + 1', '["98","100","0","99"]', 'Remainder = <u>98</u> (key says 100).', '{"bold":[],"italic":[],"underline":["100"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cv6osz2z9d17lv5dsf1w2gp5c', 'General Mathematics', 'WAEC', null, 2020, null, 'Find p if one root of x² - 6x + p = 0 is double the other.', null, '["6","8","9","12"]', 1, 'Roots α, 2α; 3α = 6 → α = 2; p = 2×4 = 8.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find p if one root of x² - 6x + p = 0 is double the other.', '["6","8","9","12"]', '<u>p = 8</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cv6s7q51vqmt9oaina5no3423', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve 4^(x+1) + 4^x = 320.', null, '["2","3","4","5"]', 1, '4^x(4+1) = 320 → 4^x = 64 → x = 3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve 4^(x+1) + 4^x = 320.', '["2","3","4","5"]', '4^x(5) = 320 → 4^x = 64 → <u>x = 3</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cv6v4mcp2u3gf51yed5sr0l5j', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'If a husband divorces his wife before the consummation of the marriage, it is considered', null, '["revocable","irrevocable","redeemable","abominable."]', 1, 'It is irrevocable.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If a husband divorces his wife before the consummation of the marriage, it is considered', '["revocable","<u>irrevocable</u>","redeemable","abominable."]', '<u>Irrevocable</u>.', '{"bold":[],"italic":[],"underline":["irrevocable"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cv6wlf676fhlvf2a0ygwl5y43', 'General Mathematics', 'JAMB', null, 2020, null, 'Simplify 2√6/(√2 + √5 - √3 + √5).', null, '["√3+√5-√2","√2+√5-√3","√2+√3-√5","√5+√6-√2"]', 1, 'Rationalize the expression.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Simplify 2√6/(√2 + √5 - √3 + √5).', '["√3+√5-√2","√2+√5-√3","√2+√3-√5","√5+√6-√2"]', null, '{"bold":[],"italic":[],"underline":["√2+√5-√3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cv6xzy841b6g2q7c5l8s3mqql', 'Biology', 'JAMB', null, 2000, null, 'Which of the following are adaptations of animals to <b>aquatic habitats</b>?', null, '["Gills streamlined bodies and laurelings","Lateral line, streamlined bodies and lungs","Gills, scaly skin and lungs","Gills, streamlined bodies and spiracles"]', 1, 'Lateral line, streamlined bodies, lungs are aquatic adaptations.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following are adaptations of animals to <b>aquatic habitats</b>?', '["Gills streamlined bodies and laurelings","Lateral line, streamlined bodies and lungs","Gills, scaly skin and lungs","Gills, streamlined bodies and spiracles"]', '<u>Lateral line, streamlined bodies, lungs</u>.', '{"bold":["aquatic habitats"],"italic":[],"underline":["Lateral line, streamlined bodies and lungs"],"fillBlanks":[]}');
