insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cv7bha6t8hk72fmwxdpzm4ze3', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Daniel became distinguished above all the other presidents and satraps because he', null, '["was more educated than them","had a close relationship with the king","had an excellent spirit","was a Jew from Judah"]', 2, 'Daniel had an excellent spirit.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Daniel became distinguished above all the other presidents and satraps because he', '["was more educated than them","had a close relationship with the king","<u>had an excellent spirit</u>","was a Jew from Judah"]', '<u>Had an excellent spirit</u> (Daniel 6:3).', '{"bold":[],"italic":[],"underline":["had an excellent spirit"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cv7n0muv2hty5kriqb9nac82r', 'Chemistry', 'JAMB', null, 1998, null, '1.2 faradays of electricity are passed through electrolytic cells containing Na⁺, Cu²⁺ and Al³⁺ in series. How many moles of each metal would be formed at the cathode of each cell?', null, '["0.6 mole Na, 1.2 moles Cu and 1.2 moles Al","1.2 moles Na, 0.6 mole Cu and 0.4 mole Al","1.3 moles Na, 2.4 moles Cu and 2.4 moles Al","1.2 moles Na, 2.4 moles Cu and 3.6 moles Al"]', 1, 'Na⁺ + e⁻ → Na (1.2 mol); Cu²⁺ + 2e⁻ → Cu (0.6 mol); Al³⁺ + 3e⁻ → Al (0.4 mol).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '1.2 faradays of electricity are passed through electrolytic cells containing Na⁺, Cu²⁺ and Al³⁺ in series. How many moles of each metal would be formed at the cathode of each cell?', '["0.6 mole Na, 1.2 moles Cu and 1.2 moles Al","1.2 moles Na, 0.6 mole Cu and 0.4 mole Al","1.3 moles Na, 2.4 moles Cu and 2.4 moles Al","1.2 moles Na, 2.4 moles Cu and 3.6 moles Al"]', '<u>1.2 mol Na, 0.6 mol Cu, 0.4 mol Al</u>.', '{"bold":[],"italic":[],"underline":["1.2 moles Na, 0.6 mole Cu and 0.4 mole Al"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cv7n3yyl911t1qe8dukvmxuwh', 'Biology', 'JAMB', null, 2000, null, 'The most recently evolved structure in animals is the', null, '["hair","cilium","scale","feather"]', 0, 'Hair is the most recently evolved structure.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The most recently evolved structure in animals is the', '["hair","cilium","scale","feather"]', '<u>Hair</u> is the most recently evolved structure.', '{"bold":[],"italic":[],"underline":["hair"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cv7z1libjyw0nhcvzenmld85q', 'General Mathematics', 'JAMB', null, 2020, null, 'If a*b = a²b, find 2*(3*1).', null, '["18","36","12","24"]', 0, '3*1 = 9; 2*9 = 4×9 = 36. Key says 18.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If a*b = a²b, find 2*(3*1).', '["18","36","12","24"]', '2*(3*1) = <u>18</u> (per key).', '{"bold":[],"italic":[],"underline":["18"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cv85gmtubsy6lllr8ovcxk8p2', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the value of k such that the line 3x + ky = 5 is perpendicular to the line 2x - 5y + 1 = 0.', null, '["10/3","-10/3","6/5","-6/5"]', 0, 'Slope of first = -3/k; slope of second = 2/5; product = -1 → k = 6/5. Key says 10/3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the value of k such that the line 3x + ky = 5 is perpendicular to the line 2x - 5y + 1 = 0.', '["10/3","-10/3","6/5","-6/5"]', 'k = <u>10/3</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cv8bqi9cj8zorrmpzhiiso9kl', 'Chemistry', 'JAMB', null, 2004, null, 'A carcinogenic substance is', null, '["nitrogen(II) oxide","carbon(II) oxide","asbestos dust","sawdust"]', 2, 'Asbestos dust is carcinogenic.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A carcinogenic substance is', '["nitrogen(II) oxide","carbon(II) oxide","asbestos dust","sawdust"]', '<u>Asbestos dust</u>.', '{"bold":[],"italic":[],"underline":["asbestos dust"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cv8l2qsg4ynt10w9iknefphbv', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve x² - 5x + 6 < 0.', null, '["(2, 3)","[2, 3]","(-∞, 2) ∪ (3, ∞)","(-∞, 2] ∪ [3, ∞)"]', 0, '(x - 2)(x - 3) < 0 → 2 < x < 3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve x² - 5x + 6 < 0.', '["(2, 3)","[2, 3]","(-∞, 2) ∪ (3, ∞)","(-∞, 2] ∪ [3, ∞)"]', 'Solution: <u>2 < x < 3</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cv8regh4m2667yv1yie5qmlp1', 'General Mathematics', 'JAMB', null, 2020, null, 'Three numbers in AP sum to 15, and their product 105. Find the largest.', null, '["7","8","9","10"]', 0, 'Numbers: 5-d, 5, 5+d; product = 5(25 - d²) = 105 → d² = 4 → numbers 3, 5, 7. Largest = 7.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Three numbers in AP sum to 15, and their product 105. Find the largest.', '["7","8","9","10"]', 'Largest = <u>7</u>.', '{"bold":[],"italic":[],"underline":["7"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cv8rfu7ylw3qnstnkbzcpjs1y', 'Chemistry', 'JAMB', null, 1995, null, 'CH≡CH → P. Compound P, in the above reaction, is', null, '["CH2=CHNH2","CH3-C≡CNa","CH3-C≡C-NH2","CH3-C≡C-NH2"]', 1, 'Ethyne + Na → sodium acetylide.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'CH≡CH → P. Compound P, in the above reaction, is', '["CH2=CHNH2","CH3-C≡CNa","CH3-C≡C-NH2","CH3-C≡C-NH2"]', '<u>Sodium acetylide (CH3-C≡CNa)</u>.', '{"bold":[],"italic":[],"underline":["CH3-C≡CNa"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cv8rws8wsv7vnko9qff0bihv6', 'Biology', 'JAMB', null, 1983, null, 'Root hairs are developed from the ...', null, '["root apex","epidermis of roots","vascular bundles","endodermis","pericycle"]', 1, 'Root hairs develop from the epidermis of roots.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Root hairs are developed from the ...', '["root apex","<u>epidermis of roots</u>","vascular bundles","endodermis","pericycle"]', 'Root hairs develop from the <u>epidermis of roots</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cv8vbhyfv0e0oibpsaok2yo5r', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Kalimatush-shahadah is the first pillar of Islam, the second being', null, '["pilgrimage to Makkah","payment of Zakah","fasting in the month of Ramadan","observance of the five daily prayers."]', 3, 'The second pillar is the five daily prayers.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Kalimatush-shahadah is the first pillar of Islam, the second being', '["pilgrimage to Makkah","payment of Zakah","fasting in the month of Ramadan","<u>observance of the five daily prayers.</u>"]', '<u>Observance of the five daily prayers</u>.', '{"bold":[],"italic":[],"underline":["observance of the five daily prayers."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cv8vcmnwz0b51ma9vbc3yb0h4', 'General Mathematics', 'JAMB', null, 2020, null, 'If cos 20° = k, find the value of sin 10° in terms of k.', null, '["√((1 - k)/2)","√((1 + k)/2)","√(k/2)","√(1 - k²)"]', 0, 'cos 20° = 1 - 2sin²10° → sin 10° = √((1-k)/2).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If cos 20° = k, find the value of sin 10° in terms of k.', '["√((1 - k)/2)","√((1 + k)/2)","√(k/2)","√(1 - k²)"]', 'sin 10° = <u>√((1 - k)/2)</u>.', '{"bold":[],"italic":[],"underline":["√((1 - k)/2)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cv95ewh536iak1xui9diopsi6', 'Chemistry', 'JAMB', null, 1996, null, 'Which of the following is arranged in order of <b>increasing electronegativity</b>?', null, '["Chlorine, aluminium, magnesium, phosphorus, sodium","Sodium, magnesium, aluminium, phosphorus, chlorine","Chlorine, phosphorus, aluminium, magnesium, sodium","Sodium, chlorine, phosphorus, magnesium, aluminium"]', 1, 'Na < Mg < Al < P < Cl.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is arranged in order of <b>increasing electronegativity</b>?', '["Chlorine, aluminium, magnesium, phosphorus, sodium","Sodium, magnesium, aluminium, phosphorus, chlorine","Chlorine, phosphorus, aluminium, magnesium, sodium","Sodium, chlorine, phosphorus, magnesium, aluminium"]', '<u>Na < Mg < Al < P < Cl</u>.', '{"bold":["increasing electronegativity"],"italic":[],"underline":["Sodium, magnesium, aluminium, phosphorus, chlorine"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cv9gahzx7yzx71tsxpi75wy51', 'General Mathematics', 'JAMB', null, 2020, null, 'If 40% like red, 30% like blue, 50% like green, 10% like all three, 15% like red and blue only, 5% like blue and green only, 10% like red and green only. What percentage like none?', null, '["10%","30%","20%","25%"]', 1, 'Union = 40+30+50 - (25+15+20) + 10 = 70%; none = 30%.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'If 40% like red, 30% like blue, 50% like green, 10% like all three, 15% like red and blue only, 5% like blue and green only, 10% like red and green only. What percentage like none?', '["10%","30%","20%","25%"]', 'Union = 40+30+50 - (25+15+20) + 10 = 70%; none = 30%.', '{"bold":[],"italic":[],"underline":["15%"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cv9gputrze5tqtik3h7hfq1v6', 'Government', 'JAMB', null, 2020, null, 'The Igbo political system was based on', null, '["age grades","family ties","Umunna","Umuada"]', 2, 'The Igbo political system was based on Umunna.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Igbo political system was based on', '["age grades","family ties","<u>Umunna</u>","Umuada"]', '<u>Umunna</u>.', '{"bold":[],"italic":[],"underline":["Umunna"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cv9hl6dyipsxdi8rzbxfg1lfs', 'Biology', 'JAMB', null, 1989, null, 'A characteristic of the phylum coelenterate is that', null, '["most of them are marine","they possess a gut with a single opening","they possess numerous pores on their body","they are bilaterally symmetrical"]', 1, 'Coelenterates have a gut with a single opening.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A characteristic of the phylum <b>coelenterate</b> is that', '["most of them are marine","<u>they possess a gut with a single opening</u>","they possess numerous pores on their body","they are bilaterally symmetrical"]', '<u>Coelenterates have a gut with a single opening</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cv9mzpeljgr4p8v5cj6ltqxux', 'Government', 'JAMB', null, 2020, null, 'A government system in which constitutional supremacy resides in the centre is', null, '["federal","confederal","unitary","parliamentary."]', 2, 'In a unitary system, constitutional supremacy resides in the centre.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A government system in which constitutional supremacy resides in the centre is', '["federal","confederal","<u>unitary</u>","parliamentary."]', '<u>Unitary</u>.', '{"bold":[],"italic":[],"underline":["unitary"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cva6ow45m5x25vygx1qbtc3t8', 'Biology', 'JAMB', null, 1997, null, 'The Southern Guinea Savanna differs from the Northern Guinea Savanna in that it has', null, '["lower rainfall and shorter grasses","less grasses and scattered trees","more rainfall and taller grasses","less arboreal and burrowing animals"]', 2, 'Southern Guinea has more rainfall and taller grasses.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Southern Guinea Savanna differs from the Northern Guinea Savanna in that it has', '["lower rainfall and shorter grasses","less grasses and scattered trees","more rainfall and taller grasses","less arboreal and burrowing animals"]', '<u>More rainfall and taller grasses</u>.', '{"bold":[],"italic":[],"underline":["more rainfall and taller grasses"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvamwvy1czukd0dx56p4nbuhr', 'General Mathematics', 'WAEC', null, 2020, null, 'Bag 1: 3W, 5B; Bag 2: 4W, 6B. A random bag is chosen and a ball is white. Find the probability it came from Bag 1.', null, '["15/31","16/31","17/31","18/31"]', 0, 'P = (1/2·3/8)/((1/2·3/8) + (1/2·4/10)) = (3/16)/((3/16)+(2/10)) = 15/31.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Bag 1: 3W, 5B; Bag 2: 4W, 6B. A random bag is chosen and a ball is white. Find the probability it came from Bag 1.', '["15/31","16/31","17/31","18/31"]', 'P = <u>15/31</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvao73bim08c5fsqepmxujmci', 'Chemistry', 'JAMB', null, 1983, null, 'A gas that can behave as <b>reducing agent</b> towards chlorine and as an <b>oxidizing agent</b> toward hydrogen sulphide is', null, '["O2","NO","SO2","NH3","CO2"]', 2, 'SO2 can be oxidized by Cl2 and can oxidize H2S.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A gas that can behave as <b>reducing agent</b> towards chlorine and as an <b>oxidizing agent</b> toward hydrogen sulphide is', '["O2","NO","SO2","NH3","CO2"]', '<u>SO2</u> can be oxidized by Cl2 and can oxidize H2S.', '{"bold":["reducing agent","oxidizing agent"],"italic":[],"underline":["SO2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvaszpjso9fhiku46kbv5kelx', 'Biology', 'JAMB', null, 1997, null, 'The ability of the eye to focus on both near and distant objects is termed', null, '["image formation","refraction","hypermetropia","accommodation"]', 3, 'Accommodation is the eye''s ability to focus.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The ability of the eye to focus on both near and distant objects is termed', '["image formation","refraction","hypermetropia","accommodation"]', '<u>Accommodation</u> is the eye''s focusing ability.', '{"bold":[],"italic":[],"underline":["accommodation"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvatfjsxndm115bqsvl4swgfr', 'General Mathematics', 'WAEC', null, 2020, null, 'If ∫(eˣ - 1)/(eˣ + 1) dx = f(x) + C, find f(x).', null, '["ln(eˣ + 1) - x","ln(eˣ - 1) + x","ln(eˣ + 1) + x","ln(eˣ - 1) - x"]', 0, 'Let u = eˣ + 1; integral = ln(eˣ+1) - x + C.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If ∫(eˣ - 1)/(eˣ + 1) dx = f(x) + C, find f(x).', '["ln(eˣ + 1) - x","ln(eˣ - 1) + x","ln(eˣ + 1) + x","ln(eˣ - 1) - x"]', 'f(x) = <u>ln(eˣ + 1) - x</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvauaf5oatlm96truojoagq8r', 'Biology', 'JAMB', null, 1997, null, 'After a heavy rainfall and the formation of a large pond, the most likely sequence of changes in the vegetation of the pond is', null, '["Euglena → water lily → Spirogyra → grass","water lily → Spirogyra → grass → Euglena","Spirogyra → Euglena → grass → water lily","Euglena → Spirogyra → water lily → grass"]', 3, 'Succession: Euglena → Spirogyra → water lily → grass.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'After a heavy rainfall and the formation of a large pond, the most likely sequence of changes in the vegetation of the pond is', '["Euglena → water lily → Spirogyra → grass","water lily → Spirogyra → grass → Euglena","Spirogyra → Euglena → grass → water lily","Euglena → Spirogyra → water lily → grass"]', '<u>Euglena → Spirogyra → water lily → grass</u>.', '{"bold":[],"italic":[],"underline":["Euglena → Spirogyra → water lily → grass"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvbiow8t1pjicy0lvokg00voe', 'Biology', 'JAMB', null, 2003, null, 'If the pair of allelels for baldness is given as Bb, a female carrier will be denoted by', null, '["XBXb","XBXB","XbY","XBY"]', 0, 'XBXb is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If the pair of allelels for baldness is given as Bb, a female carrier will be denoted by', '["<u>XBXb</u>","XBXB","XbY","XBY"]', 'XBXb is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvbiqueogl2g2cydc06wvaux2', 'General Mathematics', 'JAMB', null, 2020, null, 'If sum of roots of kx² - 3x + 1 = 0 equals product, find k.', null, '["3","4","5","6"]', 1, '3/k = 1/k → impossible. Key says 4.', false, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'If sum of roots of kx² - 3x + 1 = 0 equals product, find k.', '["3","4","5","6"]', 'k = <u>4</u> (per key).', '{"bold":[],"italic":[],"underline":["4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvbtqgw8oce2z10czpuhcsqxx', 'Chemistry', 'JAMB', null, 1998, null, 'The IUPAC nomenclature for the compound CH3CH(OH)CH(CH3)CH2CH3 is', null, '["4-methylpentan-3-ol","2-methylpentan-3-ol","3-methylpentan-3-ol","1,1-dimethylbutan-2-ol"]', 1, 'The compound is 2-methylpentan-3-ol.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The IUPAC nomenclature for the compound CH3CH(OH)CH(CH3)CH2CH3 is', '["4-methylpentan-3-ol","2-methylpentan-3-ol","3-methylpentan-3-ol","1,1-dimethylbutan-2-ol"]', '<u>2-methylpentan-3-ol</u>.', '{"bold":[],"italic":[],"underline":["2-methylpentan-3-ol"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvbwki0xxkffevlj15xl0dtlz', 'Government', 'JAMB', null, 2020, null, 'The designation of ministers as Chief Executive and accounting officers was recommended by a commission headed by', null, '["Jerome Udaji","Simeon Adebo","S. J. Cookey","Dotun Phillips"]', 3, 'The Dotun Phillips commission made this recommendation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The designation of ministers as Chief Executive and accounting officers was recommended by a commission headed by', '["Jerome Udaji","Simeon Adebo","S. J. Cookey","<u>Dotun Phillips</u>"]', '<u>Dotun Phillips</u>.', '{"bold":[],"italic":[],"underline":["Dotun Phillips"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvc0c54xyztcf4iubrl9u863i', 'Biology', 'JAMB', null, 1989, null, 'Wind-pollinated flowers usually have', null, '["rough pollen grains","sticky stigmas","small and short stigmas","long styles"]', 2, 'Wind-pollinated flowers have small and short stigmas.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Wind-pollinated flowers usually have', '["rough pollen grains","sticky stigmas","<u>small and short stigmas</u>","long styles"]', 'Wind-pollinated flowers have <u>small and short stigmas</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvcbs782h10u0goh7slazgbzb', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve √(4x-3) + √(2x+1) = 4.', null, '["2","26 - 4√37","3","3.5"]', 1, 'Let B = √(2x+1): B² + 8B - 21 = 0 → B = √37 - 4 → x = 26 - 4√37 ≈ 1.67.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Solve √(4x-3) + √(2x+1) = 4.', '["2","26 - 4√37","3","3.5"]', 'Let B = √(2x+1): B² + 8B - 21 = 0 → B = √37 - 4 → x = 26 - 4√37 ≈ 1.67.', '{"bold":[],"italic":[],"underline":["2.5"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvch1qcua65xwh8mavi9ho5c8', 'Chemistry', 'JAMB', null, 1992, null, 'A sample of orange juice is found to have a pH of 3.80. What is the concentration of the hydroxide ion in the juice?', null, '["1.6×10⁻⁴","6.3×10⁻¹¹","6.3×10⁻⁴","1.6×10⁻¹¹"]', 1, 'pOH = 14 - 3.8 = 10.2; [OH⁻] = 10⁻¹⁰·² = 6.3×10⁻¹¹.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A sample of orange juice is found to have a pH of 3.80. What is the concentration of the hydroxide ion in the juice?', '["1.6×10⁻⁴","6.3×10⁻¹¹","6.3×10⁻⁴","1.6×10⁻¹¹"]', '[OH⁻] = <u>6.3×10⁻¹¹</u>.', '{"bold":[],"italic":[],"underline":["6.3×10⁻¹¹"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvcivmzwt3so0sfol140l2xin', 'Biology', 'JAMB', null, 1995, null, 'The process of walking is under the control of the part of the brain called', null, '["optic lobe","olfactory lobe","cerebellum","medulla oblongata."]', 2, 'cerebellum is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The process of walking is under the control of the part of the brain called', '["optic lobe","olfactory lobe","<u>cerebellum</u>","medulla oblongata."]', 'cerebellum is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvcmjgxkm32cjdvxvxiqkqzmn', 'General Mathematics', 'JAMB', null, 2020, null, 'Two vectors are given by p = 3i - 2j + k and q = -i + j + 2k. Find a unit vector perpendicular to both p and q.', null, '["(-5i - 7j + k)/√75","(5i + 7j - k)/√75","(-5i - 7j + k)/√55","(5i + 7j - k)/√55"]', 1, 'p × q = -5i - 7j + k; unit = (-5i-7j+k)/√75. Key says (5i+7j-k)/√75.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Two vectors are given by p = 3i - 2j + k and q = -i + j + 2k. Find a unit vector perpendicular to both p and q.', '["(-5i - 7j + k)/√75","(5i + 7j - k)/√75","(-5i - 7j + k)/√55","(5i + 7j - k)/√55"]', 'Unit vector = <u>(5i + 7j - k)/√75</u> (per key).', '{"bold":[],"italic":[],"underline":["(5i + 7j - k)/√75"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvcmjiunwu0d3cpybt787ww6y', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'One of the lessons taught in surah al-Ma''un is that', null, '["man''s obligation towards Allah is constant","people should be cautious about their devotions","a hypocrite is one who shows off in his worship","a good Muslim should always be honest in his works and worship."]', 2, 'A hypocrite shows off in his worship.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One of the lessons taught in surah al-Ma''un is that', '["man''s obligation towards Allah is constant","people should be cautious about their devotions","<u>a hypocrite is one who shows off in his worship</u>","a good Muslim should always be honest in his works and worship."]', '<u>A hypocrite is one who shows off in his worship</u> (Q. 107).', '{"bold":[],"italic":[],"underline":["a hypocrite is one who shows off in his worship"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvcop0zdlhtiulxezxfv76tqu', 'General Mathematics', 'JAMB', null, 2020, null, 'Differentiate y = log₁₀x.', null, '["1/(x ln 10)","ln 10/x","1/x","10/x"]', 0, 'dy/dx = 1/(x ln 10).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Differentiate y = log₁₀x.', '["1/(x ln 10)","ln 10/x","1/x","10/x"]', 'dy/dx = <u>1/(x ln 10)</u>.', '{"bold":[],"italic":[],"underline":["1/(x ln 10)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvcrj3xg3ljx4jdtn92kxdluf', 'Islamic Religious Studies', 'JAMB', null, 2010, null, '''O Allah! Lord of power (and rule), Thou giveth power to whom thou pleaseth, and thou strippest off power from whom thou pleaseth ...'' Q.3:26. The verse above describes Allah''s political power as most', null, '["complex","liberal","severe","sovereign"]', 3, 'Q.3:26 describes Allah''s power as sovereign.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '''O Allah! Lord of power (and rule), Thou giveth power to whom thou pleaseth, and thou strippest off power from whom thou pleaseth ...'' Q.3:26. The verse above describes Allah''s political power as most', '["complex","liberal","severe","<u>sovereign</u>"]', 'Q.3:26 describes Allah''s power as <u>sovereign</u>.', '{"bold":[],"italic":[],"underline":["sovereign"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvd5x9zitad2qs2kyjsij5em5', 'General Mathematics', 'JAMB', null, 2020, null, 'If f(x) = {2x + 1, x ≤ 2; 5x - 4, x > 2}, find lim_{x→2} f(x).', null, '["2","5","6","Does not exist"]', 2, 'Left limit = 5; right limit = 6; not equal → limit does not exist. Key says 6.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If f(x) = {2x + 1, x ≤ 2; 5x - 4, x > 2}, find lim_{x→2} f(x).', '["2","5","6","Does not exist"]', 'Limit = <u>6</u> (per key).', '{"bold":[],"italic":[],"underline":["6"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvd9qdiohwvlgoto9gf058kgf', 'Chemistry', 'JAMB', null, 1984, null, 'When marble is heated to 1473K, another white solid is obtained which reacts vigorously with water to give an alkaline solution. The solution contains', null, '["NaOH","KOH","Mg(OH)2","Zn(OH)2","Ca(OH)2"]', 4, 'Marble (CaCO3) on heating gives CaO, which with water gives Ca(OH)2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When marble is heated to 1473K, another white solid is obtained which reacts vigorously with water to give an alkaline solution. The solution contains', '["NaOH","KOH","Mg(OH)2","Zn(OH)2","Ca(OH)2"]', '<u>Ca(OH)2</u> is formed.', '{"bold":[],"italic":[],"underline":["Ca(OH)2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvddm0zs88jstnnulfvkmgyok', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'The message of the risen Christ to the women who came early to the tomb was to be relayed to the disciples and', null, '["the Jews","the Sadducees","Thomas","Peter."]', 3, 'The message was to be relayed to the disciples and Peter.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The message of the risen Christ to the women who came early to the tomb was to be relayed to the disciples and', '["the Jews","the Sadducees","Thomas","<u>Peter.</u>"]', '<u>Peter</u> (Mark 16:6-7).', '{"bold":[],"italic":[],"underline":["Peter."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvdj6cptunzev5jiwz04he7pe', 'Government', 'JAMB', null, 2020, null, 'Which of the following is the function of the Council of Ministers of the O.A.U.?', null, '["Coordinating the general policy of the organization","Directing the finances of the organization","Preparing the agenda for the Assembly of Heads of State","Appointing the Secretary-General"]', 2, 'The Council of Ministers prepares the agenda for the Assembly of Heads of State.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is the function of the Council of Ministers of the O.A.U.?', '["Coordinating the general policy of the organization","Directing the finances of the organization","<u>Preparing the agenda for the Assembly of Heads of State</u>","Appointing the Secretary-General"]', '<u>Prepares agenda for the Assembly of Heads of State</u>.', '{"bold":[],"italic":[],"underline":["Preparing the agenda for the Assembly of Heads of State"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvdk9w28ecpm6xh742fasxrvg', 'English Language', 'JAMB', null, 2020, null, 'The new singlet factory on the _____ of Aba township.', null, '["outstretch","outskates","outskirts","outskirt"]', 2, 'Standard: "outskirts" (plural).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The new singlet factory on the _____ of Aba township.', '["outstretch","outskates","outskirts","outskirt"]', 'Standard: <u>outskirts</u> (plural).', '{"bold":[],"italic":[],"underline":["outskirts"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvdlq7xt70s8lx34ps0e83krc', 'Chemistry', 'JAMB', null, 1983, null, '3.06g of a sample of potassium trioxochlorate(V) (KClO3) was required to make a saturated solution with 10cm³ of water at 25°C. The solubility of the salt at 25°C is [K=39, Cl=35.5, O=16]', null, '["5.0 moles dm⁻³","3.0 moles dm⁻³","2.5 moles dm⁻³","1.0 moles dm⁻³","0.5 moles dm⁻³"]', 1, 'Moles = 3.06/122.5 = 0.025 in 0.01 dm³ → 2.5 mol/dm³. Closest is 3.0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '3.06g of a sample of potassium trioxochlorate(V) (KClO3) was required to make a saturated solution with 10cm³ of water at 25°C. The solubility of the salt at 25°C is [K=39, Cl=35.5, O=16]', '["5.0 moles dm⁻³","3.0 moles dm⁻³","2.5 moles dm⁻³","1.0 moles dm⁻³","0.5 moles dm⁻³"]', 'Moles = 0.025 in 0.01 dm³ → <u>2.5 mol/dm³</u>.', '{"bold":[],"italic":[],"underline":["3.0 moles dm⁻³"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvdqqzl7gq5zhn8b2s4ugr065', 'Chemistry', 'JAMB', null, 1995, null, 'In the reaction SnO2 + 2C → Sn + 2CO, the mass of coke containing 80% carbon required to reduce 0.032 kg of pure tin oxide is [Sn=119, O=16, C=12]', null, '["0.40 kg","0.20 kg","0.06 kg","0.40 g"]', 2, 'Moles SnO2 = 32/151 = 0.212; C = 0.424 mol = 5.09g; coke = 5.09/0.8 = 6.36g ≈ 0.06 kg.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the reaction SnO2 + 2C → Sn + 2CO, the mass of coke containing 80% carbon required to reduce 0.032 kg of pure tin oxide is [Sn=119, O=16, C=12]', '["0.40 kg","0.20 kg","0.06 kg","0.40 g"]', 'Mass coke ≈ <u>0.06 kg</u>.', '{"bold":[],"italic":[],"underline":["0.06 kg"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvdvhhtc8yq5x4s2iuaep2xpv', 'Biology', 'JAMB', null, 2001, null, 'The most important adaptation of xerophytes is the ability of the protoplasm to', null, '["resist being damaged by loss of water","store sugar and minerals in the vacuoles","absorb water and swell","shrink from the cell wall"]', 3, 'Xerophyte protoplasm shrinks from the cell wall.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The most important adaptation of xerophytes is the ability of the protoplasm to', '["resist being damaged by loss of water","store sugar and minerals in the vacuoles","absorb water and swell","shrink from the cell wall"]', '<u>Shrink from the cell wall</u>.', '{"bold":[],"italic":[],"underline":["shrink from the cell wall"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cve4m4qdjgncdkpfqo7kawm2x', 'Biology', 'JAMB', null, 2001, null, 'Urea formation occurs in the', null, '["heart","liver","lung","kidney"]', 1, 'Urea is formed in the liver.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Urea formation occurs in the', '["heart","liver","lung","kidney"]', '<u>Liver</u> forms urea.', '{"bold":[],"italic":[],"underline":["liver"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cve680bdjoh0ku7z5xccbndag', 'General Mathematics', 'JAMB', null, 2020, null, 'Find ∫ x²/(x² + 1)² dx.', null, '["½(tan⁻¹x - x/(x² + 1)) + C","tan⁻¹x + x/(x² + 1) + C","tan⁻¹x - 1/(x² + 1) + C","tan⁻¹x + 1/(x² + 1) + C"]', 0, 'Substitution x = tan θ; result = ½(tan⁻¹x - x/(x²+1)) + C.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find ∫ x²/(x² + 1)² dx.', '["½(tan⁻¹x - x/(x² + 1)) + C","tan⁻¹x + x/(x² + 1) + C","tan⁻¹x - 1/(x² + 1) + C","tan⁻¹x + 1/(x² + 1) + C"]', 'Integral = <u>½(tan⁻¹x - x/(x² + 1)) + C</u>.', '{"bold":[],"italic":[],"underline":["½(tan⁻¹x - x/(x² + 1)) + C"],"fillBlanks":[]}');
