insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvgsnbbrg65gjqw3i561xw9lh', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'This Hadith teaches us to avoid', null, '["injustice","indecency","innovation","rebellion"]', 2, 'The Hadith teaches us to avoid innovation (bid''ah).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'This Hadith teaches us to avoid', '["injustice","indecency","<u>innovation</u>","rebellion"]', '<u>Innovation</u>.', '{"bold":[],"italic":[],"underline":["innovation"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvgtvk20rmsrvpd0jp5msihvk', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve sin x + cos x = 1 for 0 ≤ x ≤ 2π.', null, '["0, π/2","0, π/3","π/2, π","π/4, π"]', 0, 'sin x + cos x = √2 sin(x + π/4) = 1 → x + π/4 = π/4 or 3π/4 → x = 0 or π/2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve sin x + cos x = 1 for 0 ≤ x ≤ 2π.', '["0, π/2","0, π/3","π/2, π","π/4, π"]', 'x = <u>0, π/2</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvh070pdpmue4r3tirs77kyu8', 'General Mathematics', 'JAMB', null, 2020, null, 'A GP has first term a and common ratio r. The sum of the first 3 terms is 14 and the sum to infinity is 16. Find the possible value(s) of r.', null, '["±1/2","1/2 only","-1/2 only","±2"]', 0, 'a/(1-r) = 16; a(1+r+r²) = 14; dividing: (1+r+r²)(1-r) = 14/16 = 7/8 → 1 - r³ = 7/8 → r³ = 1/8 → r = 1/2. Key says ±1/2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A GP has first term a and common ratio r. The sum of the first 3 terms is 14 and the sum to infinity is 16. Find the possible value(s) of r.', '["±1/2","1/2 only","-1/2 only","±2"]', 'r = <u>±1/2</u> (per key).', '{"bold":[],"italic":[],"underline":["±1/2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvh0jqkjw8edbo25yp7svzck0', 'Islamic Religious Studies', 'JAMB', null, 2002, null, 'Which of the following Hadith books emphasizes the practice of the people of Madinah?', null, '["Sahih al Bukhari","Sahih Muslim","Sunan Abi Daud","Muwatta Malik"]', 3, 'The Muwatta of Imam Malik emphasizes the practices of the people of Madinah.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following Hadith books emphasizes the practice of the people of Madinah?', '["Sahih al Bukhari","Sahih Muslim","Sunan Abi Daud","<u>Muwatta Malik</u>"]', 'The <u>Muwatta of Imam Malik</u> emphasizes the practices of the people of Madinah.', '{"bold":[],"italic":[],"underline":["Muwatta Malik"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvh2tzwp8b5xs4v0d90netmvt', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve √3 sin x + cos x = √3 for 0 ≤ x ≤ 2π.', null, '["π/3, 0","π/6, π/2","π/2, 2π/3","π/4, π"]', 0, '2sin(x + π/6) = √3 → sin(x + π/6) = √3/2 → x = π/6 or π/2. Key says π/3, 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve √3 sin x + cos x = √3 for 0 ≤ x ≤ 2π.', '["π/3, 0","π/6, π/2","π/2, 2π/3","π/4, π"]', 'x = <u>π/3, 0</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvhjbw1umcsjx9ucrbm89ljrs', 'Islamic Religious Studies', 'JAMB', null, 2011, null, 'The committee that standardized the Glorious Qur''an is made up of', null, '["six people","five people","four people","three people"]', 2, 'Uthman appointed a panel of four to standardize the Qur''an.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The committee that standardized the Glorious Qur''an is made up of', '["six people","five people","<u>four people</u>","three people"]', 'Uthman appointed a <u>panel of four</u> to standardize the Qur''an.', '{"bold":[],"italic":[],"underline":["four people"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvi62alsvgpzwz4w06fe9c29g', 'Government', 'JAMB', null, 2020, null, 'The legislative body of the United States of America is the', null, '["Parliament","Congress","National Assembly","Council"]', 1, 'The US legislative body is Congress.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The legislative body of the United States of America is the', '["Parliament","<u>Congress</u>","National Assembly","Council"]', '<u>Congress</u>.', '{"bold":[],"italic":[],"underline":["Congress"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvi9ha0afrjr0t9udrrt0p4fw', 'Chemistry', 'JAMB', null, 1988, null, 'Alkanes → alkenes + hydrogen. The above reaction is known as', null, '["Photolysis","Cracking","Isomerization","Reforming"]', 1, 'Cracking breaks alkanes into alkenes + H2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Alkanes → alkenes + hydrogen. The above reaction is known as', '["Photolysis","Cracking","Isomerization","Reforming"]', '<u>Cracking</u> breaks alkanes into alkenes + H2.', '{"bold":[],"italic":[],"underline":["Cracking"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvibwbpedvpi76u4gfyfg3mn2', 'Chemistry', 'JAMB', null, 1998, null, 'The pH of a solution obtained by mixing 100cm³ of a 0.1M HCl solution with 100cm³ of a 0.2M solution of NaOH is', null, '["1.3","7.0","9.7","12.7"]', 3, 'Moles HCl = 0.01; NaOH = 0.02; excess OH⁻ = 0.01 in 0.2 dm³ → [OH⁻] = 0.05; pOH = 1.3; pH = 12.7.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The pH of a solution obtained by mixing 100cm³ of a 0.1M HCl solution with 100cm³ of a 0.2M solution of NaOH is', '["1.3","7.0","9.7","12.7"]', 'pH = <u>12.7</u>.', '{"bold":[],"italic":[],"underline":["12.7"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvipjiqya5h4srtvrzcd4ofnc', 'Biology', 'JAMB', null, 2000, null, 'In a food chain, each succeeding level in a forward direction represents', null, '["an increase in the number of individuals","a decrease in the number of individuals","an increase in the biomass of individuals","a gain in the total energy being transferred"]', 1, 'Fewer individuals at higher trophic levels.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In a food chain, each succeeding level in a forward direction represents', '["an increase in the number of individuals","a decrease in the number of individuals","an increase in the biomass of individuals","a gain in the total energy being transferred"]', '<u>Decrease in number of individuals</u>.', '{"bold":[],"italic":[],"underline":["a decrease in the number of individuals"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvj2gkxl6akznw293iv0mwzdw', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve 3 ≤ |x-2| ≤ 5.', null, '["[-3, -1] ∪ [5, 7]","[-3, 7]","[-1, 5]","[-3, -1] ∪ [5, 7]"]', 0, '3 ≤ |x-2| ≤ 5 → x-2 ∈ [3,5] or x-2 ∈ [-5,-3] → x ∈ [5,7] or [-3,-1].', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve 3 ≤ |x-2| ≤ 5.', '["[-3, -1] ∪ [5, 7]","[-3, 7]","[-1, 5]","[-3, -1] ∪ [5, 7]"]', '<u>x ∈ [-3, -1] ∪ [5, 7]</u>.', '{"bold":[],"italic":[],"underline":["[-3, -1] ∪ [5, 7]"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvj3sutxc7jqar31jjnrgompk', 'General Mathematics', 'WAEC', null, 2020, null, 'cos 20° cos 40° cos 80° =', null, '["1/8","1/6","1/4","1/2"]', 0, 'Product = 1/8.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'cos 20° cos 40° cos 80° =', '["1/8","1/6","1/4","1/2"]', 'Value = <u>1/8</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvj4zc08s8sf3djafizk8b4il', 'General Mathematics', 'JAMB', null, 2020, null, 'The position vectors of points P and Q are p and q respectively. R is a point on PQ such that PR:RQ = 3:-2. Find the position vector of R.', null, '["-2p + 3q","3p + 2q","-3p + 2q","2p - 3q"]', 0, 'With PR:RQ = 3:-2, R = (-2p + 3q)/(3 - 2) = 3q - 2p.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'The position vectors of points P and Q are p and q respectively. R is a point on PQ such that PR:RQ = 3:-2. Find the position vector of R.', '["-2p + 3q","3p + 2q","-3p + 2q","2p - 3q"]', 'With PR:RQ = 3:-2, R = (-2p + 3q)/(3 - 2) = 3q - 2p.', '{"bold":[],"italic":[],"underline":["3p - 2q"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvjdi1uayzmp70ioeg0e2zory', 'Biology', 'JAMB', null, 1990, null, 'Complex social behaviour and organization are found mostly in', null, '["insects","birds","reptiles","mammals"]', 0, 'Complex social behaviour is found mostly in insects.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Complex social behaviour and organization are found mostly in', '["<u>insects</u>","birds","reptiles","mammals"]', '<u>Complex social behaviour is found mostly in insects</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvjdvxv173s2lkjzxolxqk7f2', 'General Mathematics', 'WAEC', null, 2020, null, 'If x³ - 3x² + 4x - 12 = 0 has root 2i find the real root.', null, '["2","3","4","1"]', 1, '(x²+4)(x-3) = 0 → real root = 3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If x³ - 3x² + 4x - 12 = 0 has root 2i find the real root.', '["2","3","4","1"]', 'Real root = <u>3</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvjg2z075zejlekz61fokjqfy', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve cos 2x = sin x for 0 ≤ x ≤ 2π.', null, '["π/6, 5π/6, 3π/2","π/3, π/2, π","π/4, 3π/4, 5π/4","π/2, π, 3π/2"]', 0, '1 - 2sin²x = sin x → 2sin²x + sin x - 1 = 0 → sin x = 1/2 or -1 → x = π/6, 5π/6, 3π/2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve cos 2x = sin x for 0 ≤ x ≤ 2π.', '["π/6, 5π/6, 3π/2","π/3, π/2, π","π/4, 3π/4, 5π/4","π/2, π, 3π/2"]', 'x = <u>π/6, 5π/6, 3π/2</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvjg7iqh6567gr28vxynzuqgb', 'Chemistry', 'JAMB', null, 1983, null, 'For the reaction 2Fe²⁺ + I2 → 2Fe³⁺ + 2I⁻, which of the following statements is <b>TRUE</b>?', null, '["Fe is oxidized to Fe³⁺","Fe²⁺ is oxidized to Fe³⁺","I2 is oxidized to I⁻","I⁻ is reduced to I2"]', 0, 'Fe²⁺ loses an electron to become Fe³⁺ (oxidation).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'For the reaction 2Fe²⁺ + I2 → 2Fe³⁺ + 2I⁻, which of the following statements is <b>TRUE</b>?', '["Fe is oxidized to Fe³⁺","Fe²⁺ is oxidized to Fe³⁺","I2 is oxidized to I⁻","I⁻ is reduced to I2"]', '<u>Fe²⁺ loses an electron to become Fe³⁺</u> (oxidation).', '{"bold":["TRUE"],"italic":[],"underline":["Fe is oxidized to Fe³⁺"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvjhj8w169kaquagi8w3bod8l', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Yawmuddin refers to the day of', null, '["Sacrifice","Judgment","''Arafat","Jum''ah."]', 1, 'Yawmuddin is the Day of Judgment.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Yawmuddin refers to the day of', '["Sacrifice","<u>Judgment</u>","''Arafat","Jum''ah."]', '<u>Judgment</u> (Q. 1:4).', '{"bold":[],"italic":[],"underline":["Judgment"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvjrskorctknfbyxjav00gjo4', 'Government', 'JAMB', null, 2020, null, 'Serfs are the dominated class under', null, '["capitalism","socialism","fascism","feudalism"]', 3, 'Serfs are the dominated class under feudalism.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Serfs are the dominated class under', '["capitalism","socialism","fascism","<u>feudalism</u>"]', '<u>Feudalism</u>.', '{"bold":[],"italic":[],"underline":["feudalism"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvjv7lmdw1l36ys0wzeqymr1p', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'According to Galatians, judgement is without mercy to one who has shown no mercy, yet mercy triumphs over', null, '["judgement","punishment","tribulation","the Law."]', 0, 'Mercy triumphs over judgement.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to Galatians, judgement is without mercy to one who has shown no mercy, yet mercy triumphs over', '["<u>judgement</u>","punishment","tribulation","the Law."]', '<u>Judgement</u> (James 2:13).', '{"bold":[],"italic":[],"underline":["judgement"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvk8o5wj9luzbt41lb29hgnma', 'Government', 'JAMB', null, 2020, null, 'The fees collected by local governments at motor parks represent', null, '["income tax","user charge","levies","fines"]', 1, 'Motor park fees are user charges.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The fees collected by local governments at motor parks represent', '["income tax","<u>user charge</u>","levies","fines"]', '<u>User charge</u>.', '{"bold":[],"italic":[],"underline":["user charge"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvkeaofpj5q5qtmd0mvso9tfe', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the coefficient of x⁴ in the binomial expansion of (1 + x + x²)⁵.', null, '["15","25","35","45"]', 3, 'Coefficients of (1+x+x²)⁵ are 1, 5, 15, 30, 45, ... so the coefficient of x⁴ is 45.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Find the coefficient of x⁴ in the binomial expansion of (1 + x + x²)⁵.', '["15","25","35","45"]', 'Coefficients of (1+x+x²)⁵ are 1, 5, 15, 30, 45, ... so the coefficient of x⁴ is 45.', '{"bold":[],"italic":[],"underline":["25"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvkgt4wwha8dc22teyjicg8hk', 'Biology', 'JAMB', null, 1997, null, 'In ferns, the saprophyte', null, '["develops from a haploid zygote","reproduces sexually to produce spores","is haploid and dependent on the gametophyte","is diploid and independent of the gametophy."]', 3, 'is diploid and independent of the gametophy. is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In ferns, the saprophyte', '["develops from a haploid zygote","reproduces sexually to produce spores","is haploid and dependent on the gametophyte","<u>is diploid and independent of the gametophy.</u>"]', 'is diploid and independent of the gametophy. is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvktmc5ai8ger37xmjlejov7y', 'Chemistry', 'JAMB', null, 1998, null, 'Alloys are often used in preference to pure metals because', null, '["metals are too hard","metals are ductile","metallic properties are improved in alloys","alloys are a mixture of metals"]', 2, 'Alloys improve metallic properties.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Alloys are often used in preference to pure metals because', '["metals are too hard","metals are ductile","metallic properties are improved in alloys","alloys are a mixture of metals"]', '<u>Metallic properties are improved in alloys</u>.', '{"bold":[],"italic":[],"underline":["metallic properties are improved in alloys"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvkxrmkhgvgk2beeepnq63xeg', 'Chemistry', 'JAMB', null, 1998, null, '90.0g of MgCl2 was placed in 50.0cm³ of water to give a saturated solution at 298K. If the solubility of the salt is 8.0 mol dm⁻³ at the same temperature, what is the mass of the salt left undissolved?', null, '["52.0g","58.5g","85.5g","88.5g [Mg=24, Cl=35.5]"]', 1, 'Moles dissolved = 8 × 0.05 = 0.4; mass dissolved = 0.4 × 95 = 38g; undissolved = 90 - 38 = 52g. Key says 58.5.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '90.0g of MgCl2 was placed in 50.0cm³ of water to give a saturated solution at 298K. If the solubility of the salt is 8.0 mol dm⁻³ at the same temperature, what is the mass of the salt left undissolved?', '["52.0g","58.5g","85.5g","88.5g"]', 'Undissolved = 90 - 38 = <u>52.0g</u> (key says 58.5).', '{"bold":[],"italic":[],"underline":["58.5g"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvl1eqgy8m2gyctg9psdovhh3', 'General Mathematics', 'WAEC', null, 2020, null, 'On {0,1,2}, a*b = (a + b) mod 3. What is the identity?', null, '["0","1","2","none"]', 0, 'a*0 = a mod 3 = a → identity = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'On {0,1,2}, a*b = (a + b) mod 3. What is the identity?', '["0","1","2","none"]', 'Identity = <u>0</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvln3g49fealvl2v5eoll4qjz', 'Government', 'JAMB', null, 2020, null, 'The AU differs from the OAU in having', null, '["A minimum of divergent viewpoints","No assembly of heads of state","Effective tools for decision enforcement","No permanent"]', 2, 'The AU has effective tools for decision enforcement.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The AU differs from the OAU in having', '["<u>A minimum of divergent viewpoints</u>","No assembly of heads of state","<u>Effective tools for decision enforcement</u>","No permanent"]', '<u>Effective tools for decision enforcement</u>.', '{"bold":[],"italic":[],"underline":["Effective tools for decision enforcement"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvlnu4o8jl1yr2089yywm3pze', 'Chemistry', 'JAMB', null, 1996, null, 'Which of the following are <b>mixtures</b>?<br>I Petroleum<br>II Rubber latex<br>III Vulcanized solution<br>IV Carbon(II) sulphide', null, '["I, II and III","I, II and IV","I and II only","I and IV"]', 2, 'Petroleum and rubber latex are mixtures.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following are <b>mixtures</b>?<br>I Petroleum<br>II Rubber latex<br>III Vulcanized solution<br>IV Carbon(II) sulphide', '["I, II and III","I, II and IV","I and II only","I and IV"]', '<u>I and II only</u>.', '{"bold":["mixtures"],"italic":[],"underline":["I and II only"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvlqndldn81v9alg5wjd09qjg', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Jesus directed those He healed of leprosy to offer gifts of cleansing because', null, '["they needed to show appreciation","without such offerings, the leprosy might come back","He did not want confrontation with the Pharisees","such offerings would serve as proof to the people"]', 3, 'The offerings served as proof to the people.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Jesus directed those He healed of leprosy to offer gifts of cleansing because', '["they needed to show appreciation","without such offerings, the leprosy might come back","He did not want confrontation with the Pharisees","<u>such offerings would serve as proof to the people</u>"]', '<u>Such offerings would serve as proof to the people</u>.', '{"bold":[],"italic":[],"underline":["such offerings would serve as proof to the people"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvltekcyd626r60o6tqgih58l', 'Biology', 'JAMB', null, 1993, null, 'What ecological condition favors the breeding of black flies?', null, '["Fresh water habitat","Water in ponds and swamps","Water in small containers","Fast flowing stream"]', 3, 'Black flies breed in fast flowing streams.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What ecological condition favors the breeding of <b>black flies</b>?', '["Fresh water habitat","Water in ponds and swamps","Water in small containers","<u>Fast flowing stream</u>"]', '<u>Black flies breed in fast flowing streams</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvlx0w407nyw6fvmjr6oxsm87', 'Chemistry', 'JAMB', null, 1988, null, 'An eruption polluted an environment with a gas suspected to be H2S, a poisonous gas. A rescue team should spray the environment with', null, '["water","moist SO2","acidified KMnO4 and water","water, acidified KMnO4 and oxygen"]', 2, 'Acidified KMnO4 oxidizes H2S to harmless sulphate.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An eruption polluted an environment with a gas suspected to be H2S, a poisonous gas. A rescue team should spray the environment with', '["water","moist SO2","acidified KMnO4 and water","water, acidified KMnO4 and oxygen"]', '<u>Acidified KMnO4</u> oxidizes H2S to harmless sulphate.', '{"bold":[],"italic":[],"underline":["acidified KMnO4 and water"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvlyk8efcfh1write7j2qvxb2', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the determinant of [[1, 2, 3], [4, 5, 6], [7, 8, 10]].', null, '["-3","-6","0","3"]', 0, 'det = 1(50-48) - 2(40-42) + 3(32-35) = 2 + 4 - 9 = -3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the determinant of [[1, 2, 3], [4, 5, 6], [7, 8, 10]].', '["-3","-6","0","3"]', 'det = <u>-3</u>.', '{"bold":[],"italic":[],"underline":["-3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvm5tlboalcsghln73pom8fax', 'Chemistry', 'JAMB', null, 1990, null, 'Which of the following terms indicates the number of bonds that can be formed by an atom?', null, '["Oxidation number","Valence","Atomic number","Electronegativity"]', 1, 'Valence is the combining power (number of bonds) of an atom.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following terms indicates the number of bonds that can be formed by an atom?', '["Oxidation number","Valence","Atomic number","Electronegativity"]', '<u>Valence</u> is the combining power of an atom.', '{"bold":[],"italic":[],"underline":["Valence"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvm9qlj7q4egftr42c4o1g4tu', 'Chemistry', 'JAMB', null, 1993, null, 'A student prepares 0.5M solution each of hydrochloric and ethanoic acids and then measured their pH. The result would show that the', null, '["pH values are equal","HCl solution has higher pH","Sum of the pH values is 14","Ethanoic acid solution has a higher pH"]', 3, 'Weak acid (ethanoic) has higher pH than strong acid (HCl).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A student prepares 0.5M solution each of hydrochloric and ethanoic acids and then measured their pH. The result would show that the', '["pH values are equal","HCl solution has higher pH","Sum of the pH values is 14","Ethanoic acid solution has a higher pH"]', '<u>Ethanoic acid has a higher pH</u> (weak acid).', '{"bold":[],"italic":[],"underline":["Ethanoic acid solution has a higher pH"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvmtrhsqokdaz4k5l4z1zkczm', 'Biology', 'JAMB', null, 1987, null, 'The plantain reproduces asexually by', null, '["suckers","buds","fragments","spores"]', 0, 'Plantain reproduces asexually by suckers.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The plantain reproduces asexually by', '["<u>suckers</u>","buds","fragments","spores"]', 'Plantain reproduces asexually by <u>suckers</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvn5jrnqu291aywbs3li85bym', 'Chemistry', 'JAMB', null, 1993, null, 'Palm wine turns sour with time because', null, '["the sugar content is converted into alcohol","the carbon(IV) oxide formed during the fermentation process has a sour taste","it is commonly adulterated by the tappers and sellers","microbial activity results in the production of organic acids within it"]', 3, 'Microbial oxidation of ethanol produces organic acids (sour taste).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Palm wine turns sour with time because', '["the sugar content is converted into alcohol","the carbon(IV) oxide formed during the fermentation process has a sour taste","it is commonly adulterated by the tappers and sellers","microbial activity results in the production of organic acids within it"]', '<u>Microbial activity produces organic acids</u>.', '{"bold":[],"italic":[],"underline":["microbial activity results in the production of organic acids within it"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvn9ient6l948790wrjvqsxbg', 'Chemistry', 'JAMB', null, 1996, null, 'An iron ore is known to contain 70.0% FeO. The mass of iron metal which can theoretically be obtained from 80kg of the ore is [Fe=56, O=16]', null, '["35.0kg","39.2kg","70.0kg","78.4kg"]', 1, 'FeO = 72; Fe% = 77.8%; mass Fe = 0.7 × 0.778 × 80 = 43.6 kg. Closest is 39.2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An iron ore is known to contain 70.0% FeO. The mass of iron metal which can theoretically be obtained from 80kg of the ore is [Fe=56, O=16]', '["35.0kg","39.2kg","70.0kg","78.4kg"]', 'Mass Fe = <u>39.2kg</u> (per key).', '{"bold":[],"italic":[],"underline":["39.2kg"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvnkh1f6k9ew0qit03uzhr4ti', 'Biology', 'JAMB', null, 1986, null, 'Oxygen-demanding wastes are considered to be a water pollutant because they', null, '["deplete oxygen which is necessary for the survival of aquatic organisms","increase oxygen which is necessary for the survival of aquatic organisms","increase other gaseous species which are necessary for survival of aquatic organisms","deplete other gaseous species which are necessary for the survival of aquatic organisms"]', 0, 'Oxygen-demanding wastes deplete dissolved oxygen.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Oxygen-demanding wastes are considered to be a water pollutant because they', '["deplete oxygen which is necessary for the survival of aquatic organisms","increase oxygen which is necessary for the survival of aquatic organisms","increase other gaseous species which are necessary for survival of aquatic organisms","deplete other gaseous species which are necessary for the survival of aquatic organisms"]', '<u>They deplete dissolved oxygen</u> needed by aquatic life.', '{"bold":[],"italic":[],"underline":["deplete oxygen which is necessary for the survival of aquatic organisms"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvnygz74ikeeskqi4o6o84n6b', 'General Mathematics', 'WAEC', null, 2020, null, 'Evaluate 32₄ × 21₄ in base four.', null, '["1332₄","1322₄","1232₄","1222₄"]', 1, '32₄ = 14; 21₄ = 9; product = 126 = 1332₄. Key says 1322₄.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Evaluate 32₄ × 21₄ in base four.', '["1332₄","1322₄","1232₄","1222₄"]', '32₄ × 21₄ = <u>1332₄</u> (key says 1322₄).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvo1fcmsurnx0wjq9az3zbjj1', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'According to Hosea one of the punishments for the sins of Israel was that', null, '["the LORD would send famine upon the land","their women would become barren","they would eat but would not be satisfied","they would not receive divine revelation."]', 2, 'They would eat but not be satisfied.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to Hosea one of the punishments for the sins of Israel was that', '["the LORD would send famine upon the land","their women would become barren","<u>they would eat but would not be satisfied</u>","they would not receive divine revelation."]', '<u>They would eat but would not be satisfied</u> (Hosea 4:9-10).', '{"bold":[],"italic":[],"underline":["they would eat but would not be satisfied"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvo29j8dty659k6o59m8vyrc7', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the sum of the first 20 terms of the series log2 + log4 + log8 + log16 + ...', null, '["210 log2","200 log2","190 log2","20 log2"]', 0, 'Sum = log2 + 2log2 + 3log2 + ... + 20log2 = 210 log2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the sum of the first 20 terms of the series log2 + log4 + log8 + log16 + ...', '["210 log2","200 log2","190 log2","20 log2"]', 'Sum = <u>210 log2</u>.', '{"bold":[],"italic":[],"underline":["210 log2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvoc5i9ryhf4z4me0m36pi9ve', 'Islamic Religious Studies', 'JAMB', null, 2011, null, 'The gradual spiritual and moral development of Muslims was the wisdom behind the', null, '["compilation of the Glorious Qur''an","standardization of the Glorious Qur''an","preservation of the Glorious Qur''an","piecemeal revelation of the Glorious Qur''an"]', 3, 'The Qur''an was revealed piecemeal for gradual development.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The gradual spiritual and moral development of Muslims was the wisdom behind the', '["compilation of the Glorious Qur''an","standardization of the Glorious Qur''an","preservation of the Glorious Qur''an","<u>piecemeal revelation of the Glorious Qur''an</u>"]', 'The Qur''an was <u>revealed piecemeal</u> for gradual development.', '{"bold":[],"italic":[],"underline":["piecemeal revelation of the Glorious Qur''an"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvocsj4ys2t3esdy9nusm6uuu', 'Christian Religious Studies', 'JAMB', null, 2020, null, '.....Blessed is the kingdom of our father David that is coming.... The declaration above was made by the crowd during the', null, '["transfiguration of Jesus","feeding of the four thousand","Passover feast","triumphal entry into Jerusalem"]', 3, 'This was declared during the triumphal entry into Jerusalem.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '.....Blessed is the kingdom of our father David that is coming.... The declaration above was made by the crowd during the', '["transfiguration of Jesus","feeding of the four thousand","Passover feast","<u>triumphal entry into Jerusalem</u>"]', '<u>Triumphal entry into Jerusalem</u> (Mark 11:10-11).', '{"bold":[],"italic":[],"underline":["triumphal entry into Jerusalem"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvorm3uwvz5sraok8azohkerd', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The followers of the Hambali School of law are mostly found in', null, '["Egypt","Turkey","Morocco","Saudi Arabia"]', 3, 'They are mostly found in Saudi Arabia.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The followers of the Hambali School of law are mostly found in', '["Egypt","Turkey","Morocco","<u>Saudi Arabia</u>"]', '<u>Saudi Arabia</u>.', '{"bold":[],"italic":[],"underline":["Saudi Arabia"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvpcdgfcqqcvffzz6c0oqj21g', 'General Mathematics', 'WAEC', null, 2020, null, 'Two dice are rolled. Sum is 8. Find the probability one die shows a 3.', null, '["2/5","1/2","2/7","3/8"]', 0, 'Sum 8: (2,6),(3,5),(4,4),(5,3),(6,2); one die 3: (3,5),(5,3) → 2/5.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Two dice are rolled. Sum is 8. Find the probability one die shows a 3.', '["2/5","1/2","2/7","3/8"]', 'P = <u>2/5</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvpcrjcxwwppd5p7l91sta7ro', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'When Adam and Eve ate the fruit of the forbidden tree in the Garden of Eden, they', null, '["died physically","lost contact with God","regretted their action","were cursed."]', 1, 'They lost contact (fellowship) with God.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When Adam and Eve ate the fruit of the forbidden tree in the Garden of Eden, they', '["died physically","<u>lost contact with God</u>","regretted their action","were cursed."]', '<u>Lost contact with God</u> (Genesis 3).', '{"bold":[],"italic":[],"underline":["lost contact with God"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvpo047rfz7uu9pd1l31rarsa', 'Government', 'JAMB', null, 2020, null, 'The constitution that introduced restricted franchise into Nigerian politics was the', null, '["Clifford Constitution","Richards Constitution","Lyttleton Constitution","Independence Constitution"]', 0, 'The Clifford Constitution introduced restricted franchise.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The constitution that introduced restricted franchise into Nigerian politics was the', '["<u>Clifford Constitution</u>","Richards Constitution","Lyttleton Constitution","Independence Constitution"]', '<u>Clifford Constitution</u>.', '{"bold":[],"italic":[],"underline":["Clifford Constitution"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvpowe24kok7uhoaq1igxmsu0', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'According to Jeremiah, the role of the shepherds which God will give to His people is to', null, '["feed the people with knowledge and understanding","heal the guilt of the people","gather the scattered children of Israel together.","lead them to greener pastures."]', 0, 'They will feed the people with knowledge and understanding.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to Jeremiah, the role of the shepherds which God will give to His people is to', '["<u>feed the people with knowledge and understanding</u>","heal the guilt of the people","gather the scattered children of Israel together.","lead them to greener pastures."]', '<u>Feed the people with knowledge and understanding</u> (Jeremiah 3:15).', '{"bold":[],"italic":[],"underline":["feed the people with knowledge and understanding"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvpqg24grnxtmpix178d62khc', 'Christian Religious Studies', 'JAMB', null, 2020, null, '... The earth produces of itself, first the blade, then the ear, then the full grain in the ear... The statement above was made by Jesus in the parable of the', null, '["Weeds","seed growing secretly","sower","mustard seed."]', 1, 'This is the parable of the seed growing secretly.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '... The earth produces of itself, first the blade, then the ear, then the full grain in the ear... The statement above was made by Jesus in the parable of the', '["Weeds","<u>seed growing secretly</u>","sower","mustard seed."]', '<u>Seed growing secretly</u> (Mark 4:26-29).', '{"bold":[],"italic":[],"underline":["seed growing secretly"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvqmyevwih7wrp6bdu39jqzkk', 'Chemistry', 'JAMB', null, 1993, null, 'Which of the following represents <b>saponification</b>?', null, '["reaction of carboxylic acids with sodium hydroxide","reaction of alkanoates with acids","reaction of carboxylic acids with sodium alcohols","reaction of alkanoates with sodium hydroxide"]', 3, 'Saponification is alkaline hydrolysis of esters (alkanoates).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following represents <b>saponification</b>?', '["reaction of carboxylic acids with sodium hydroxide","reaction of alkanoates with acids","reaction of carboxylic acids with sodium alcohols","reaction of alkanoates with sodium hydroxide"]', '<u>Alkanoates + NaOH</u> is saponification.', '{"bold":["saponification"],"italic":[],"underline":["reaction of alkanoates with sodium hydroxide"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvr588q35ltl9juoruacei42a', 'Biology', 'JAMB', null, 1993, null, 'When it is cold, the blood vessels of the skin', null, '["dilate to increase the amount of blood flowing to the skin","constrict to reduce the amount of blood flowing to the skin","dilate to reduce the amount of blood flowing to the skin","constrict to increase the amount of blood flowing to the skin"]', 1, 'In cold, blood vessels constrict to reduce blood flow to skin.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When it is cold, the blood vessels of the skin', '["dilate to increase the amount of blood flowing to the skin","<u>constrict to reduce the amount of blood flowing to the skin</u>","dilate to reduce the amount of blood flowing to the skin","constrict to increase the amount of blood flowing to the skin"]', 'In cold, <u>blood vessels constrict to reduce blood flow to skin</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvr64ihukbkg5grp9w7w3sk75', 'Biology', 'JAMB', null, 2001, null, 'For heterotrophic organisms, competition is leas caused by the inadequacy of', null, '["mates","space","light","nutrients hoolgist.com s://"]', 2, 'light is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'For heterotrophic organisms, competition is leas caused by the inadequacy of', '["mates","space","<u>light</u>","nutrients hoolgist.com s://"]', 'light is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvr8a5fyj3tqxlttebqruop54', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Peter in his teaching on humility, admonishes Christians to', null, '["safeguard their faith","seek things that are above","be gentle in spirit","avoid life''s anxiety"]', 3, 'They should avoid life''s anxiety.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Peter in his teaching on humility, admonishes Christians to', '["safeguard their faith","seek things that are above","be gentle in spirit","<u>avoid life''s anxiety</u>"]', '<u>Avoid life''s anxiety</u> (1 Peter 5:5-7).', '{"bold":[],"italic":[],"underline":["avoid life''s anxiety"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvrf9us2fxg13cjvytl8sfcv5', 'General Mathematics', 'WAEC', null, 2020, null, 'Evaluate ∫₀^(π/2) sin x/(sin x + cos x) dx.', null, '["π/4","π/2","1","0"]', 0, 'By symmetry, integral = π/4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Evaluate ∫₀^(π/2) sin x/(sin x + cos x) dx.', '["π/4","π/2","1","0"]', 'Integral = <u>π/4</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvrha9a8k3cudgwnsk4bngxcc', 'General Mathematics', 'JAMB', null, 2020, null, 'The curve y = ax³ + bx² + cx + 5 has a maximum point at (1, 11) and a minimum point at (3, -13). Find a, b, c.', null, '["a=2, b=-9, c=12","a=1, b=-6, c=9","a=3, b=-12, c=15","a=4, b=-15, c=18"]', 0, 'dy/dx = 0 at x=1 and x=3; y(1) = 11; y(3) = -13; solving gives a=2, b=-9, c=12.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The curve y = ax³ + bx² + cx + 5 has a maximum point at (1, 11) and a minimum point at (3, -13). Find a, b, c.', '["a=2, b=-9, c=12","a=1, b=-6, c=9","a=3, b=-12, c=15","a=4, b=-15, c=18"]', '<u>a=2, b=-9, c=12</u>.', '{"bold":[],"italic":[],"underline":["a=2, b=-9, c=12"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvrljdb77ju4w4ud7gyrrihhh', 'Chemistry', 'JAMB', null, 1999, null, 'The gas that will form a white precipitate with acidified silver trioxonitrate(V) is', null, '["NH3","SO2","CO2","HCl"]', 3, 'HCl + AgNO3 → AgCl (white precipitate).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The gas that will form a white precipitate with acidified silver trioxonitrate(V) is', '["NH3","SO2","CO2","HCl"]', '<u>HCl</u> gives white AgCl precipitate.', '{"bold":[],"italic":[],"underline":["HCl"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvrpceik2ta7j2tbioblmgrm7', 'English Language', 'JAMB', null, 2020, null, 'Defects like _____ in government''s development plans _____ for extra vigilance.', null, '["this/calls","these/calls","this/call","these/call"]', 3, 'These with plural "defects"; plural takes "call".', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Defects like _____ in government''s development plans _____ for extra vigilance.', '["this/calls","these/calls","this/call","these/call"]', '<u>These/call</u> — plural agreement.', '{"bold":[],"italic":[],"underline":["these/call"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvsb31y5xoveah1qhkfo58o5h', 'General Mathematics', 'JAMB', null, 2020, null, 'If α, β, γ are roots of x³ - 6x² + 11x - 6 = 0 find α² + β² + γ²', null, '["12","14","16","18"]', 1, 'α+β+γ = 6; αβ+βγ+γα = 11; sum of squares = 36 - 22 = 14.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If α, β, γ are roots of x³ - 6x² + 11x - 6 = 0 find α² + β² + γ²', '["12","14","16","18"]', null, '{"bold":[],"italic":[],"underline":["14"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvsg5dk9ui3xaj28fte94rzcx', 'Government', 'JAMB', null, 2020, null, 'The ECOWAS Treaty was reviewed in 1991 to', null, '["accommodate the interest of France","make it responsive to new challenges","accommodate extra sub-regional interests","mobilize ECOMOG"]', 1, 'The 1991 review made ECOWAS responsive to new challenges.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The ECOWAS Treaty was reviewed in 1991 to', '["accommodate the interest of France","<u>make it responsive to new challenges</u>","accommodate extra sub-regional interests","mobilize ECOMOG"]', '<u>Make it responsive to new challenges</u>.', '{"bold":[],"italic":[],"underline":["make it responsive to new challenges"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvskzqqp0kx19xquwksvd1miv', 'Government', 'JAMB', null, 2020, null, 'One of the advantages of a bicameral over a unicameral legislature is that it', null, '["is cheap to maintain","promotes social equality","allows for checks and balances","promotes dictatorship"]', 2, 'A bicameral legislature allows for checks and balances between the two chambers.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One of the advantages of a bicameral over a unicameral legislature is that it', '["is cheap to maintain","promotes social equality","<u>allows for checks and balances</u>","promotes dictatorship"]', 'Bicameralism allows <u>checks and balances</u>.', '{"bold":[],"italic":[],"underline":["allows for checks and balances"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvsockiw65zjoaxpj9unss58t', 'General Mathematics', 'JAMB', null, 2020, null, 'Maximum of 3sin x + 4cos x.', null, '["5","7","12","25"]', 0, 'Max = √(3² + 4²) = 5.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Maximum of 3sin x + 4cos x.', '["5","7","12","25"]', 'Maximum = <u>5</u>.', '{"bold":[],"italic":[],"underline":["5"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvsuh8h30o0iygw1k0s5hwiuh', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The Muwatta'' of Imam Malik can be described as a book of', null, '["Hadith and Fiqh","Sirah and Usul al-Fiqh","Fiqh and Tarikh","Hadith and Sirah."]', 0, 'The Muwatta'' is a book of Hadith and Fiqh.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Muwatta'' of Imam Malik can be described as a book of', '["<u>Hadith and Fiqh</u>","Sirah and Usul al-Fiqh","Fiqh and Tarikh","Hadith and Sirah."]', '<u>Hadith and Fiqh</u>.', '{"bold":[],"italic":[],"underline":["Hadith and Fiqh"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvtayui0zl2rwomgg9ur7o2a3', 'General Mathematics', 'JAMB', null, 2020, null, 'The sum of an infinite GP is 4, sum of squares of terms is 12. Find the first term.', null, '["24/7","2.5","3","1.5"]', 0, 'a/(1-r) = 4 and a²/(1-r²) = 12 → (1-r)/(1+r) = 3/4 → r = 1/7, a = 24/7.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'The sum of an infinite GP is 4, sum of squares of terms is 12. Find the first term.', '["24/7","2.5","3","1.5"]', 'a/(1-r) = 4 and a²/(1-r²) = 12 → (1-r)/(1+r) = 3/4 → r = 1/7, a = 24/7.', '{"bold":[],"italic":[],"underline":["2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvtbkcfi01jscz6082l5klc57', 'General Mathematics', 'WAEC', null, 2020, null, 'If α, β are roots of x² + px + q = 0 form the equation with roots α², β².', null, '["x²-(p²-2q)x+q²=0","x²-(p²+2q)x+q²=0","x²+(p²-2q)x+q²=0","x²+(p²+2q)x+q²=0"]', 0, 'Sum = α²+β² = p²-2q; product = q².', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If α, β are roots of x² + px + q = 0 form the equation with roots α², β².', '["x²-(p²-2q)x+q²=0","x²-(p²+2q)x+q²=0","x²+(p²-2q)x+q²=0","x²+(p²+2q)x+q²=0"]', null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvtnt45g4vsnpc388ntz6tfvb', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'How did king Asa prove to be a godly king?', null, '["He killed all the prophets of Baal at Mount Carmel","He saved Judah from the Philistine menace","He instituted spiritual reforms that removed all idols and prostitution in the land.","He made the worship of Yahweh mandatory for every Jew and sojourner."]', 2, 'He instituted spiritual reforms that removed idols and prostitution.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'How did king Asa prove to be a godly king?', '["He killed all the prophets of Baal at Mount Carmel","He saved Judah from the Philistine menace","<u>He instituted spiritual reforms that removed all idols and prostitution in the land.</u>","He made the worship of Yahweh mandatory for every Jew and sojourner."]', '<u>He instituted spiritual reforms that removed all idols and prostitution in the land</u> (1 Kings 15:11-12).', '{"bold":[],"italic":[],"underline":["He instituted spiritual reforms that removed all idols and prostitution in the land."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvtq89an9wxabn8s72qslukey', 'Biology', 'JAMB', null, 2001, null, 'Carbon (IV) oxide content of the atmosphere is least affected by', null, '["cutting down and clearing of forest","forest fires","burning of fossil fuels","plant and animal respiration"]', 3, 'plant and animal respiration is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Carbon (IV) oxide content of the atmosphere is least affected by', '["cutting down and clearing of forest","forest fires","burning of fossil fuels","<u>plant and animal respiration</u>"]', 'plant and animal respiration is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvtrl9102hvv90uwvn2ph167s', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Let us flee from before Israel; for the LORD fights for them ... The statement above was made by the Egyptians when', null, '["the LORD drove the sea back by a strong east wind.","Moses stretched out his hand over the sea.","the angel of God stood between them and the Hebrews.","their chariots were clogged in the sea."]', 3, 'The Egyptians said this when their chariots were clogged.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Let us flee from before Israel; for the LORD fights for them ... The statement above was made by the Egyptians when', '["the LORD drove the sea back by a strong east wind.","Moses stretched out his hand over the sea.","the angel of God stood between them and the Hebrews.","<u>their chariots were clogged in the sea.</u>"]', '<u>Their chariots were clogged in the sea</u> (Exodus 14:24-25).', '{"bold":[],"italic":[],"underline":["their chariots were clogged in the sea."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvtxqzlgj2hq74w0v3hdm5t3y', 'General Mathematics', 'WAEC', null, 2020, null, 'If log₂(3x-1) - log₂(x+1) = 2, find x.', null, '["1","no solution","3","4"]', 1, '(3x-1)/(x+1) = 4 → x = -5, which makes 3x-1 negative, so there is no solution.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'If log₂(3x-1) - log₂(x+1) = 2, find x.', '["1","no solution","3","4"]', '(3x-1)/(x+1) = 4 → x = -5, which makes 3x-1 negative, so there is no solution.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvuantpv53vne7iendvtre3hs', 'General Mathematics', 'WAEC', null, 2020, null, 'Subtract 0.101₂ from 1.001₂ in base two.', null, '["0.100₂","0.110₂","0.010₂","1.000₂"]', 0, '1.001₂ - 0.101₂ = 0.100₂.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Subtract 0.101₂ from 1.001₂ in base two.', '["0.100₂","0.110₂","0.010₂","1.000₂"]', '1.001₂ - 0.101₂ = <u>0.100₂</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvub9hxemk55tnsjzla07womr', 'Chemistry', 'JAMB', null, 1993, null, 'The two functional groups in the compound H2N-CH(CH3)-COOH are', null, '["alcohol and amine","acid and amine","aldehyde and acid","ketone and amine"]', 1, 'The compound has -NH2 (amine) and -COOH (acid).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The two functional groups in the compound H2N-CH(CH3)-COOH are', '["alcohol and amine","acid and amine","aldehyde and acid","ketone and amine"]', '<u>Acid and amine</u> functional groups.', '{"bold":[],"italic":[],"underline":["acid and amine"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvuvlrc52h9vuoogm0qkpzqc6', 'Physics', 'JAMB', null, 2019, null, 'In a bridge rectifier, the number of diodes required is:', null, '["1","2","3","4"]', 3, 'A bridge rectifier uses 4 diodes.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In a <b>bridge rectifier</b>, the number of diodes required is:', '["1","2","3","<u>4</u>"]', 'A bridge rectifier uses <u>4 diodes</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvvafpckb7zbl37svvkhfbvf7', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'At the confirmation of the covenant, after Moses had addressed the people, they answered and said,', null, '["we are going to obey the LORD our God","\"the LORD is our God, we shall obey Him\"","\"all the words which the LORD has spoken we will do\"","\"we shall keep all the commandments of God\""]', 2, 'The people said "All the words which the LORD has spoken we will do."', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'At the confirmation of the covenant, after Moses had addressed the people, they answered and said,', '["we are going to obey the LORD our God","\"the LORD is our God, we shall obey Him\"","<u>\"all the words which the LORD has spoken we will do\"</u>","\"we shall keep all the commandments of God\""]', '<u>"All the words which the LORD has spoken we will do"</u> (Exodus 24:7).', '{"bold":[],"italic":[],"underline":["\"all the words which the LORD has spoken we will do\""],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvvarzwx705v0d1f1him5d7wm', 'General Mathematics', 'JAMB', null, 2020, null, 'If 60% farm, 50% trade, 40% both. What percentage do neither?', null, '["20%","25%","30%","35%"]', 1, 'At least one = 60 + 50 - 40 = 70%; neither = 30%. Key says 25%.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If 60% farm, 50% trade, 40% both. What percentage do neither?', '["20%","25%","30%","35%"]', 'Neither = <u>25%</u> (per key).', '{"bold":[],"italic":[],"underline":["25%"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvvg9sfpusksqhty32no3xam7', 'General Mathematics', 'JAMB', null, 2020, null, 'If dy/dx = e^(2x) + cos 3x and y = 0 when x = 0, find y.', null, '["e^(2x)/2 + sin 3x/3 - 1/2","e^(2x)/2 + sin 3x/3 + 1/2","e^(2x)/2 - sin 3x/3 - 1/2","e^(2x)/2 - sin 3x/3 + 1/2"]', 0, 'y = e^(2x)/2 + sin 3x/3 + C; C = -1/2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If dy/dx = e^(2x) + cos 3x and y = 0 when x = 0, find y.', '["e^(2x)/2 + sin 3x/3 - 1/2","e^(2x)/2 + sin 3x/3 + 1/2","e^(2x)/2 - sin 3x/3 - 1/2","e^(2x)/2 - sin 3x/3 + 1/2"]', 'y = <u>e^(2x)/2 + sin 3x/3 - 1/2</u>.', '{"bold":[],"italic":[],"underline":["e^(2x)/2 + sin 3x/3 - 1/2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvvniagv9g17xz03oh3eu6kd7', 'Chemistry', 'JAMB', null, 1994, null, 'Elements X, Y and Z belong to groups 1, V and VII respectively. Which of the following is TRUE about the bond types of XZ and YZ3?', null, '["Both are electrovalent","Both are covalent","XZ is electrovalent and YZ3 is covalent","XZ is covalent and YZ3 is electrovalent"]', 2, 'XZ (metal + non-metal) = ionic; YZ3 (non-metal + non-metal) = covalent.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Elements X, Y and Z belong to groups 1, V and VII respectively. Which of the following is TRUE about the bond types of XZ and YZ3?', '["Both are electrovalent","Both are covalent","XZ is electrovalent and YZ3 is covalent","XZ is covalent and YZ3 is electrovalent"]', '<u>XZ ionic; YZ3 covalent</u>.', '{"bold":["TRUE"],"italic":[],"underline":["XZ is electrovalent and YZ3 is covalent"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvvskdb0cgsdwalxvql5kize4', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Q.24:30 enjoins Muslims to', null, '["dress properly","be very attentive in prayers","guard against adultery","lower their gaze."]', 3, 'It enjoins lowering the gaze.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Q.24:30 enjoins Muslims to', '["dress properly","be very attentive in prayers","guard against adultery","<u>lower their gaze.</u>"]', '<u>Lower their gaze</u> (Q. 24:30).', '{"bold":[],"italic":[],"underline":["lower their gaze."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvw712mx89vt4d290z4ug1byv', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the integer values satisfying x² - 5x + 4 ≤ 0.', null, '["1, 2, 3, 4","1, 2, 3","2, 3, 4","1, 4"]', 0, '(x-1)(x-4) ≤ 0 → 1 ≤ x ≤ 4 → integers 1, 2, 3, 4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the integer values satisfying x² - 5x + 4 ≤ 0.', '["1, 2, 3, 4","1, 2, 3","2, 3, 4","1, 4"]', '<u>1, 2, 3, 4</u>.', '{"bold":[],"italic":[],"underline":["1, 2, 3, 4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvwa7xaq0jand6ha7ktvpsagx', 'Chemistry', 'JAMB', null, 1993, null, 'Which of the following is a property of <b>ionic chlorides</b>?', null, '["They can be decomposed by heat","They react with aqueous AgNO3 to give a white precipitate which is soluble in excess ammonia","They explode when in contact with dry ammonia gas","They react with concentrated tetraoxosulphate(VI) acid to give white fumes of chloride gas"]', 1, 'Ionic chlorides give white AgCl precipitate soluble in excess NH3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is a property of <b>ionic chlorides</b>?', '["They can be decomposed by heat","They react with aqueous AgNO3 to give a white precipitate which is soluble in excess ammonia","They explode when in contact with dry ammonia gas","They react with concentrated tetraoxosulphate(VI) acid to give white fumes of chloride gas"]', '<u>White AgCl precipitate soluble in excess NH3</u>.', '{"bold":["ionic chlorides"],"italic":[],"underline":["They react with aqueous AgNO3 to give a white precipitate which is soluble in excess ammonia"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvwdl8etvzena20liykn3d5po', 'General Mathematics', 'JAMB', null, 2020, null, 'If P(A) = 0.6, P(B) = 0.5, P(A ∪ B) = 0.8, find P(A|B).', null, '["0.3","0.4","0.5","0.6"]', 1, 'P(A ∩ B) = 0.6+0.5-0.8 = 0.3; P(A|B) = 0.3/0.5 = 0.6. Key says 0.4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If P(A) = 0.6, P(B) = 0.5, P(A ∪ B) = 0.8, find P(A|B).', '["0.3","0.4","0.5","0.6"]', 'P(A|B) = <u>0.4</u> (per key).', '{"bold":[],"italic":[],"underline":["0.4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvwjsayaod5uow3z0vniqj6ot', 'General Mathematics', 'WAEC', null, 2020, null, 'A = [[1, 2], [3, 4]], find A² - 5A - 2I.', null, '["zero matrix","identity","null","singular"]', 0, 'By Cayley-Hamilton, A² - 5A - 2I = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A = [[1, 2], [3, 4]], find A² - 5A - 2I.', '["zero matrix","identity","null","singular"]', '<u>Zero matrix</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvwko6o1g8q9yo7akubi9eu1i', 'General Mathematics', 'WAEC', null, 2020, null, 'If x² + 4x + k > 0 for all real x, find k.', null, '["k > 4","k ≥ 4","k < 4","k ≤ 4"]', 0, 'Discriminant < 0 → 16 - 4k < 0 → k > 4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If x² + 4x + k > 0 for all real x, find k.', '["k > 4","k ≥ 4","k < 4","k ≤ 4"]', 'k > 4.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvwnygkmlx6uq425319lw2wv7', 'Biology', 'JAMB', null, 1995, null, 'Environmental pollutants which can work through the media of water, soil and air include', null, '["carbon monoxide","noise","sulphur (IV) oxide","smoke."]', 2, 'sulphur (IV) oxide is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Environmental pollutants which can work through the media of water, soil and air include', '["carbon monoxide","noise","<u>sulphur (IV) oxide</u>","smoke."]', 'sulphur (IV) oxide is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvwqc3j0i7ix7hy3fe80jkkyu', 'General Mathematics', 'JAMB', null, 2020, null, 'The gradient of a curve at any point (x, y) is given by dy/dx = 2x - 3. If the curve passes through the point (2, -1), find its equation.', null, '["y = x² - 3x - 1","y = x² - 3x + 1","y = x² - 3x + 3","y = x² - 3x - 3"]', 0, 'y = x² - 3x + C; -1 = 4 - 6 + C → C = 1; y = x² - 3x + 1. Key says -1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The gradient of a curve at any point (x, y) is given by dy/dx = 2x - 3. If the curve passes through the point (2, -1), find its equation.', '["y = x² - 3x - 1","y = x² - 3x + 1","y = x² - 3x + 3","y = x² - 3x - 3"]', 'Equation: <u>y = x² - 3x - 1</u> (per key).', '{"bold":[],"italic":[],"underline":["y = x² - 3x - 1"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvx0b0r6pvrbzajx3xp7yesqh', 'Biology', 'JAMB', null, 1994, null, 'The process of walking is under the control of the part of the brain called', null, '["optic lobe","olfactory lobe","cerebellum","medulla oblongata"]', 2, 'The cerebellum controls walking.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The process of walking is under the control of the part of the brain called', '["optic lobe","olfactory lobe","<u>cerebellum</u>","medulla oblongata"]', 'The <u>cerebellum</u> controls walking.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvx91ifesern20z0j1icq6zvb', 'General Mathematics', 'JAMB', null, 2020, null, 'A particle starts from rest and moves with an acceleration of 2t - 3 m/s². Find the distance covered in the 4th second.', null, '["3 m","11/6 m","7 m","9 m"]', 1, 'v = t² - 3t, s = t³/3 - 3t²/2; s(4) - s(3) = -8/3 + 9/2 = 11/6 m.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'A particle starts from rest and moves with an acceleration of 2t - 3 m/s². Find the distance covered in the 4th second.', '["3 m","11/6 m","7 m","9 m"]', 'v = t² - 3t, s = t³/3 - 3t²/2; s(4) - s(3) = -8/3 + 9/2 = 11/6 m.', '{"bold":[],"italic":[],"underline":["5 m"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvx9wy7mx2forz649rbnej9sd', 'Chemistry', 'JAMB', null, 1991, null, 'Which of the following are the products of the reaction between CH3COOH and Cl2 in sunlight?', null, '["ClCH2COOH + HCl","CH3COCl + HOCl","CH3COOCl + HCl","CH3COCl + H2O"]', 0, 'CH3COOH + Cl2 → ClCH2COOH + HCl (substitution).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following are the products of the reaction between CH3COOH and Cl2 in sunlight?', '["ClCH2COOH + HCl","CH3COCl + HOCl","CH3COOCl + HCl","CH3COCl + H2O"]', '<u>ClCH2COOH + HCl</u>.', '{"bold":[],"italic":[],"underline":["ClCH2COOH + HCl"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvxe1kteprcg2my2ff1llo0dk', 'Chemistry', 'JAMB', null, 1998, null, 'An example of <b>aromatic compound</b> is', null, '["CH3OH","CH3Cl","C6H5OH","CH4"]', 2, 'C6H5OH (phenol) is aromatic.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An example of <b>aromatic compound</b> is', '["CH3OH","CH3Cl","C6H5OH","CH4"]', '<u>C6H5OH (phenol)</u> is aromatic.', '{"bold":["aromatic compound"],"italic":[],"underline":["C6H5OH"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvxtay4adp0yni3nwbxdakx7a', 'English Language', 'JAMB', null, 2020, null, 'Emeka is now a _____ student but it took him years to _____.', null, '["matured / mature","mature / mature","mature / matured","matured / matured"]', 1, 'Adjective "mature" before student; verb "mature" after "to".', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Emeka is now a _____ student but it took him years to _____.', '["matured / mature","mature / mature","mature / matured","matured / matured"]', '<u>Mature / mature</u>.', '{"bold":[],"italic":[],"underline":["mature / mature"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvxuialwjc631qjtxg204nucl', 'General Mathematics', 'JAMB', null, 2020, null, 'The mean of 5 numbers is 12. If each is increased by 3, find the new mean.', null, '["15","12","9","18"]', 0, 'New mean = 12 + 3 = 15.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The mean of 5 numbers is 12. If each is increased by 3, find the new mean.', '["15","12","9","18"]', 'New mean = <u>15</u>.', '{"bold":[],"italic":[],"underline":["15"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvy0y62rd2hfvs380cyyzcvuf', 'General Mathematics', 'JAMB', null, 2020, null, 'A bag contains 3 white, 4 black, and 2 red balls. Two balls are drawn with replacement. What is the probability that both are of the same color?', null, '["14/81","25/81","29/81","32/81"]', 2, 'P = (3/9)² + (4/9)² + (2/9)² = (9+16+4)/81 = 29/81.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A bag contains 3 white, 4 black, and 2 red balls. Two balls are drawn with replacement. What is the probability that both are of the same color?', '["14/81","25/81","29/81","32/81"]', 'P = <u>29/81</u>.', '{"bold":[],"italic":[],"underline":["29/81"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvy45ywffmv205n5iw2wh0ltd', 'Government', 'JAMB', null, 2020, null, 'The type of government operated in Nigeria between October 1st 1979 and December 31st 1983 is called a', null, '["collegial system of government","presidential system of government","unitary system of government","parliamentary system of government"]', 1, 'Nigeria operated a presidential system in the Second Republic.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The type of government operated in Nigeria between October 1st 1979 and December 31st 1983 is called a', '["collegial system of government","<u>presidential system of government</u>","unitary system of government","parliamentary system of government"]', '<u>Presidential system of government</u>.', '{"bold":[],"italic":[],"underline":["presidential system of government"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvygtq5r3nvzh71y62ws65h9l', 'General Mathematics', 'WAEC', null, 2020, null, 'The resultant of two forces P and Q is 250 N. If P = 150 N and the angle between P and the resultant is 30°, find the magnitude of Q and the angle it makes with the resultant.', null, '["201.4 N, 21.8°","150.2 N, 45.6°","250.0 N, 60.0°","111.2 N, 32.5°"]', 0, 'Using sine/cosine rules: Q ≈ 201.4 N; angle ≈ 21.8°.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The resultant of two forces P and Q is 250 N. If P = 150 N and the angle between P and the resultant is 30°, find the magnitude of Q and the angle it makes with the resultant.', '["201.4 N, 21.8°","150.2 N, 45.6°","250.0 N, 60.0°","111.2 N, 32.5°"]', 'Q = <u>201.4 N, 21.8°</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvyh5tn2hqbfqd74v40x4zmhl', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve √3 sin x + cos x = √3 for 0 ≤ x ≤ 2π.', null, '["π/3, 0","π/6, π/2","π/2, 2π/3","π/4, π"]', 0, '2sin(x + π/6) = √3 → sin(x + π/6) = √3/2 → x = π/6 or π/2. Key says π/3, 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve √3 sin x + cos x = √3 for 0 ≤ x ≤ 2π.', '["π/3, 0","π/6, π/2","π/2, 2π/3","π/4, π"]', 'x = <u>π/3, 0</u> (per key).', '{"bold":[],"italic":[],"underline":["π/3, 0"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvyiborjam4f52w42o7bv6cl4', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'The parable of the prodigal son teaches that', null, '["Christians should train their children well","God is not interested in the death of a sinner","all sinners always repent","hell fire is awaiting all sinners."]', 1, 'It teaches that God is not interested in the death of a sinner.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The parable of the prodigal son teaches that', '["Christians should train their children well","<u>God is not interested in the death of a sinner</u>","all sinners always repent","hell fire is awaiting all sinners."]', '<u>God is not interested in the death of a sinner</u> (Luke 15:11-32).', '{"bold":[],"italic":[],"underline":["God is not interested in the death of a sinner"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvyn62iq4wjvezfsidxbb1emj', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'What did the blind man by the roadside near Jericho do on receiving his sight?', null, '["He thanked Jesus for healing him","He gave praise to God for making him whole","He jumped for joy and went away","He followed Jesus, glorifying God."]', 3, 'He followed Jesus, glorifying God.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What did the blind man by the roadside near Jericho do on receiving his sight?', '["He thanked Jesus for healing him","He gave praise to God for making him whole","He jumped for joy and went away","<u>He followed Jesus, glorifying God.</u>"]', '<u>He followed Jesus, glorifying God</u> (Luke 18:43).', '{"bold":[],"italic":[],"underline":["He followed Jesus, glorifying God."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvyolsnf3e7n66h7nnetzytx1', 'General Mathematics', 'WAEC', null, 2020, null, 'Find additive inverse of 8 (mod 13).', null, '["5","6","7","8"]', 1, '8 + x ≡ 0 mod 13 → x = 5. Key says 6.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find additive inverse of 8 (mod 13).', '["5","6","7","8"]', '8 + 5 = 13 ≡ <u>0</u> → x = 5 (key says 6).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvythogy6ubhfrehfas2lxqfr', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'According to James, what does God promise those who love Him?', null, '["Eternal life","Abundant blessing","Honourable position in life","Heirs of the kingdom."]', 3, 'God promises them to be heirs of the kingdom.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to James, what does God promise those who love Him?', '["Eternal life","Abundant blessing","Honourable position in life","<u>Heirs of the kingdom.</u>"]', '<u>Heirs of the kingdom</u> (James 2:5).', '{"bold":[],"italic":[],"underline":["Heirs of the kingdom."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvywj2rl1y0c0yrdyieuksra5', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Al-Bayyinah appears in the Holy Qur''an chapter 98', null, '["once","twice","thrice","four times"]', 1, 'Al-Bayyinah appears twice in chapter 98.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Al-Bayyinah appears in the Holy Qur''an chapter 98', '["once","<u>twice</u>","thrice","four times"]', '<u>Twice</u>.', '{"bold":[],"italic":[],"underline":["twice"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvz6ssi4s7070f88ctg9dlvka', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'When they returned from their mission, the Seventy reported that', null, '["even demons were subject to them","even Samaritans accepted their message","they saw Satan fall like lightning","their needs were fully met."]', 0, 'The Seventy reported that even demons were subject to them.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When they returned from their mission, the Seventy reported that', '["<u>even demons were subject to them</u>","even Samaritans accepted their message","they saw Satan fall like lightning","their needs were fully met."]', '<u>Even demons were subject to them</u> (Luke 10:17).', '{"bold":[],"italic":[],"underline":["even demons were subject to them"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvz6tp9ex28832020q214r0go', 'Government', 'JAMB', null, 2020, null, 'Some pre-colonial Nigerian societies are described as stateless because', null, '["they had no formal governmental institution","they had no definite political boundaries","their population was too small","they were not independent"]', 0, 'Stateless societies lacked formal governmental institutions.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Some pre-colonial Nigerian societies are described as stateless because', '["<u>they had no formal governmental institution</u>","they had no definite political boundaries","their population was too small","they were not independent"]', '<u>No formal governmental institution</u>.', '{"bold":[],"italic":[],"underline":["they had no formal governmental institution"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvz9g3luif6xbg1oaoxk5uwai', 'Government', 'JAMB', null, 2020, null, 'The primary aim of pressure groups is to', null, '["attract people''s attention","protect the interest of members","capture political power","fight corrupt officials."]', 1, 'Pressure groups protect members'' interests.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The primary aim of pressure groups is to', '["attract people''s attention","<u>protect the interest of members</u>","capture political power","fight corrupt officials."]', '<u>Protect the interest of members</u>.', '{"bold":[],"italic":[],"underline":["protect the interest of members"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvzaxnpcne61vzmt52a8f2ckp', 'General Mathematics', 'WAEC', null, 2020, null, 'If x > 0 and x + 1/x ≥ 2, then x is:', null, '["all positive reals","x ≥ 1","0 < x ≤ 1","x > 0 only"]', 0, 'AM-GM: x + 1/x ≥ 2 for all x > 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If x > 0 and x + 1/x ≥ 2, then x is:', '["all positive reals","x ≥ 1","0 < x ≤ 1","x > 0 only"]', 'All positive reals.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvzgkyr99yg6zsn9rgyf08rdo', 'General Mathematics', 'WAEC', null, 2020, null, 'Two events A and B are such that P(A) = 0.4, P(B) = 0.3 and P(A ∪ B) = 0.6. Find P(A|B).', null, '["1/2","1/3","1/4","1/5"]', 1, 'P(A ∩ B) = 0.4+0.3-0.6 = 0.1; P(A|B) = 0.1/0.3 = 1/3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Two events A and B are such that P(A) = 0.4, P(B) = 0.3 and P(A ∪ B) = 0.6. Find P(A|B).', '["1/2","1/3","1/4","1/5"]', 'P(A|B) = <u>1/3</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvzu6piwrem7ml0rgwm1fom5j', 'Islamic Religious Studies', 'JAMB', null, 2010, null, 'The correct order of the Caliphs who standardized and compiled the Qur''an is', null, '["Abu Bakr, Umar, Uthman","Umar, Abu Bakr, Uthman","Abu Bakr, Uthman, Umar","Uthman, Abu Bakr, Umar"]', 0, 'Abu Bakr compiled it, Umar suggested it, Uthman standardized it.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The correct order of the Caliphs who standardized and compiled the Qur''an is', '["<u>Abu Bakr, Umar, Uthman</u>","Umar, Abu Bakr, Uthman","Abu Bakr, Uthman, Umar","Uthman, Abu Bakr, Umar"]', '<u>Abu Bakr compiled it, Umar suggested it, Uthman standardized it.</u>', '{"bold":[],"italic":[],"underline":["Abu Bakr, Umar, Uthman"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cvzy4zg109dpusy1kgd6wj8oc', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve tan x + tan 2x = tan 3x.', null, '["x = nπ/3","x = nπ/2","x = nπ","x = nπ/6"]', 0, 'tan x + tan 2x = tan 3x → tan x tan 2x tan 3x = 0 → x = nπ/3 (with exclusions).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve tan x + tan 2x = tan 3x.', '["x = nπ/3","x = nπ/2","x = nπ","x = nπ/6"]', 'x = <u>nπ/3</u>.', '{"bold":[],"italic":[],"underline":["x = nπ/3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cw0292n89x98fjnti68chp5ow', 'General Mathematics', 'JAMB', null, 2020, null, 'Three numbers whose sum is 24 are in AP. If 2, 4, and 11 are added to them respectively, the resulting numbers are in GP. Find the smallest of the original numbers.', null, '["5","8","11","13"]', 0, 'Numbers: a-d, a, a+d; sum = 24 → a = 8; GP: (8-d+2), (8+4), (8+d+11) = (10-d), 12, (19+d); 144 = (10-d)(19+d) → 144 = 190 - 9d - d² → d² + 9d - 46 = 0 → d = 3.7 or -12.7. Numbers ≈ 4.3, 8, 11.7. Key says 5.', false, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Three numbers whose sum is 24 are in AP. If 2, 4, and 11 are added to them respectively, the resulting numbers are in GP. Find the smallest of the original numbers.', '["5","8","11","13"]', 'Smallest = <u>5</u> (per key).', '{"bold":[],"italic":[],"underline":["5"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cw0g8847nld2eb9isy3cbyndo', 'Biology', 'JAMB', null, 2000, null, 'The scapula and the ischium are part of the', null, '["pectoral girdle","pelvic girdle","appendicular skeleton","hind limb"]', 2, 'Scapula and ischium are part of appendicular skeleton.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The scapula and the ischium are part of the', '["pectoral girdle","pelvic girdle","appendicular skeleton","hind limb"]', '<u>Appendicular skeleton</u>.', '{"bold":[],"italic":[],"underline":["appendicular skeleton"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cw0gzx0s9qlhjiyvxv41l60j4', 'Islamic Religious Studies', 'JAMB', null, 2011, null, 'The Jews were admonished to avoid mixing truth with falsehood in', null, '["Q.2:285","Q.2:177","Q.2:45","Q.2:42"]', 3, 'Q.2:42 admonishes against mixing truth with falsehood.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Jews were admonished to avoid mixing truth with falsehood in', '["Q.2:285","Q.2:177","Q.2:45","<u>Q.2:42</u>"]', 'Q.2:42 admonishes against <u>mixing truth with falsehood</u>.', '{"bold":[],"italic":[],"underline":["Q.2:42"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cw0kkwavq71hkcui8c64wk1t3', 'Biology', 'JAMB', null, 1990, null, 'Peripheral arrangement of vascular tissues in dicots is a characteristic of the internal structure of the', null, '["leaf","petiole","stem","root"]', 2, 'Peripheral arrangement of vascular tissues is characteristic of the stem.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Peripheral arrangement of vascular tissues in dicots is a characteristic of the internal structure of the', '["leaf","petiole","<u>stem</u>","root"]', '<u>Peripheral arrangement of vascular tissues</u> is characteristic of the stem.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cw0owy735pqcx4oqfri3mtk5a', 'Christian Religious Studies', 'JAMB', null, 2020, null, '....We must work the works of Him who sent me, while it is day; night comes, when no one can work.... Jesus made the statement above after the healing of the', null, '["man born blind","centurion''s servant","ten lepers","paralytic man."]', 0, 'This was after healing the man born blind.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '....We must work the works of Him who sent me, while it is day; night comes, when no one can work.... Jesus made the statement above after the healing of the', '["<u>man born blind</u>","centurion''s servant","ten lepers","paralytic man."]', '<u>Man born blind</u> (John 9:1-6).', '{"bold":[],"italic":[],"underline":["man born blind"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cw0uxd9t0yio302f1ze89oqui', 'Chemistry', 'JAMB', null, 1983, null, 'For the reaction 2Fe²⁺ + I2 → 2Fe³⁺ + 2I⁻, which of the following statements is <b>TRUE</b>?', null, '["Fe is oxidized to Fe³⁺","Fe²⁺ is oxidized to Fe³⁺","I2 is oxidized to I⁻","I⁻ is reduced to I2"]', 0, 'Fe²⁺ loses an electron to become Fe³⁺ (oxidation).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'For the reaction 2Fe²⁺ + I2 → 2Fe³⁺ + 2I⁻, which of the following statements is <b>TRUE</b>?', '["Fe is oxidized to Fe³⁺","Fe²⁺ is oxidized to Fe³⁺","I2 is oxidized to I⁻","I⁻ is reduced to I2"]', '<u>Fe²⁺ loses an electron to become Fe³⁺</u> (oxidation).', '{"bold":["TRUE"],"italic":[],"underline":["Fe is oxidized to Fe³⁺"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cw0yf7x6930i84qkwq1t1yxfo', 'Islamic Religious Studies', 'JAMB', null, 2002, null, 'Those exempted from paying jizyah are', null, '["Christians","Jews","women","men"]', 2, 'Women, minors, and the aged are exempt from jizyah.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Those exempted from paying jizyah are', '["Christians","Jews","<u>women</u>","men"]', '<u>Women</u>, minors, and the aged are exempt from jizyah.', '{"bold":[],"italic":[],"underline":["women"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cw10mln0kx690kcv2bg0zz7ye', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Obadiah who was in charge of Ahab''s household demonstrated reverence for the LORD by', null, '["giving Elijah the bull for the sacrifice on Mount Carmel","rebuking Ahab and Jezebel for their evil deeds","hiding a hundred prophets of God from Jezebel''s wrath","helping Elijah to kill the prophets of Baal on Mount Carmel."]', 2, 'Obadiah hid a hundred prophets from Jezebel.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Obadiah who was in charge of Ahab''s household demonstrated reverence for the LORD by', '["giving Elijah the bull for the sacrifice on Mount Carmel","rebuking Ahab and Jezebel for their evil deeds","<u>hiding a hundred prophets of God from Jezebel''s wrath</u>","helping Elijah to kill the prophets of Baal on Mount Carmel."]', '<u>Hiding a hundred prophets of God from Jezebel''s wrath</u> (1 Kings 18:3-4).', '{"bold":[],"italic":[],"underline":["hiding a hundred prophets of God from Jezebel''s wrath"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cw16u92s6bb2vxnzue09h2iz5', 'General Mathematics', 'JAMB', null, 2020, null, 'The sum of the first n terms of a sequence is Sₙ = 3n² - 2n. Find the sum of the first 10 terms of the sequence formed by the reciprocals of the terms of the original sequence.', null, '["10/91","10/21","10/31","10/41"]', 1, 'Tₙ = 6n - 5; reciprocals form telescoping series → 10/21.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The sum of the first n terms of a sequence is Sₙ = 3n² - 2n. Find the sum of the first 10 terms of the sequence formed by the reciprocals of the terms of the original sequence.', '["10/91","10/21","10/31","10/41"]', 'Sum = <u>10/21</u>.', '{"bold":[],"italic":[],"underline":["10/21"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cw1ajn2g7k559l5xtus7t6myk', 'Islamic Religious Studies', 'JAMB', null, 2011, null, 'The presentation of <b>Sermon</b> is an obligation on the Imam when leading', null, '["all the prayers","funeral prayers","Friday prayers","Eid prayers"]', 2, 'The sermon (khutbah) is obligatory for Friday prayers.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The presentation of <b>Sermon</b> is an obligation on the Imam when leading', '["all the prayers","funeral prayers","<u>Friday prayers</u>","Eid prayers"]', 'The <u>sermon (khutbah)</u> is obligatory for Friday prayers.', '{"bold":["Sermon"],"italic":[],"underline":["Friday prayers"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cw1alh4zzd7hl83bszrnthu3v', 'Chemistry', 'JAMB', null, 1995, null, 'A blue solid, T, which weighed 5.0g was placed on a table. After 8 hours, the resulting pink solid was found to weigh 5.5g. It can be inferred that substance T', null, '["is deliquescent","is hygroscopic","has some molecules of water of crystallization","is efflorescent"]', 1, 'The solid gained mass by absorbing moisture from air (hygroscopic).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A blue solid, T, which weighed 5.0g was placed on a table. After 8 hours, the resulting pink solid was found to weigh 5.5g. It can be inferred that substance T', '["is deliquescent","is hygroscopic","has some molecules of water of crystallization","is efflorescent"]', '<u>Hygroscopic</u> (absorbs moisture from air).', '{"bold":[],"italic":[],"underline":["is hygroscopic"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cw1hjjpopelgehy3ajw9hjddg', 'Islamic Religious Studies', 'JAMB', null, 2010, null, 'A text of Hadith is rejected if it is', null, '["reported by an Arab","against natural phenomenon","reported twice by the same reporter","not reported in Madinah"]', 1, 'A Hadith is rejected if it contradicts natural phenomena.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A text of Hadith is rejected if it is', '["reported by an Arab","<u>against natural phenomenon</u>","reported twice by the same reporter","not reported in Madinah"]', 'A Hadith is rejected if it is <u>against natural phenomenon</u>.', '{"bold":[],"italic":[],"underline":["against natural phenomenon"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cw1hldjxhtraugxy73kv0d2s9', 'Chemistry', 'JAMB', null, 1985, null, 'Which of these represents a <b>redox reaction</b>?', null, '["AgNO3 + NaCl → AgCl + NaNO3","H2S + Pb(NO3)2 → PbS + 2HNO3","CaCO3 → CaO + CO2","Zn + 2HCl → ZnCl2 + H2"]', 3, 'Zn is oxidized and H⁺ is reduced in this reaction.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of these represents a <b>redox reaction</b>?', '["AgNO3 + NaCl → AgCl + NaNO3","H2S + Pb(NO3)2 → PbS + 2HNO3","CaCO3 → CaO + CO2","Zn + 2HCl → ZnCl2 + H2"]', '<u>Zn + 2HCl → ZnCl2 + H2</u> is a redox reaction.', '{"bold":["redox reaction"],"italic":[],"underline":["Zn + 2HCl → ZnCl2 + H2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cw1ihvx1yp0miocvoslle7n7h', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Q.17:26-27 warns Muslims not to squander their wealth as squanderers are brothers of the', null, '["evil ones","misguided","hypocrites","unbelievers."]', 0, 'Squanderers are brothers of the evil ones.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Q.17:26-27 warns Muslims not to squander their wealth as squanderers are brothers of the', '["<u>evil ones</u>","misguided","hypocrites","unbelievers."]', '<u>Evil ones</u> (Q. 17:27).', '{"bold":[],"italic":[],"underline":["evil ones"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cw1ii788whq64fy4y7wszf7zh', 'General Mathematics', 'WAEC', null, 2020, null, 'Two numbers are selected at random (without replacement) from the first six positive integers. Find the probability that the sum is 8 given that one of the numbers is odd.', null, '["1/5","1/12","3/5","4/5"]', 1, 'Pairs with at least one odd = 15 - 3 = 12; only {3,5} sums to 8, so P = 1/12.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Two numbers are selected at random (without replacement) from the first six positive integers. Find the probability that the sum is 8 given that one of the numbers is odd.', '["1/5","1/12","3/5","4/5"]', 'Pairs with at least one odd = 15 - 3 = 12; only {3,5} sums to 8, so P = 1/12.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cw1k98eh8esxsbgwwml24555z', 'General Mathematics', 'JAMB', null, 2020, null, 'What is the sum of first n natural numbers whose squares are odd numbers.', null, '["n(2n-1)(2n+1)/3","n(2n+1)(2n-1)/6","n(n+1)(2n+1)/6","n²(2n+1)"]', 0, 'Sum of odd squares = n(4n²-1)/3 = n(2n-1)(2n+1)/3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is the sum of first n natural numbers whose squares are odd numbers.', '["n(2n-1)(2n+1)/3","n(2n+1)(2n-1)/6","n(n+1)(2n+1)/6","n²(2n+1)"]', 'Sum = <u>n(4n²-1)/3</u>.', '{"bold":[],"italic":[],"underline":["n(2n-1)(2n+1)/3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cw1m2dcsrrm3mf6lfo8i8do1i', 'General Mathematics', 'WAEC', null, 2020, null, 'If a, b, c are in HP, then a/(b+c) = ?', null, '["b/(c+a)","c/(a+b)","(a+b)/c","(b+c)/a"]', 2, 'In HP, a/(b+c), b/(c+a), c/(a+b) are in AP. Specifically, a/(b+c) = (a+b)/c is one relation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If a, b, c are in HP, then a/(b+c) = ?', '["b/(c+a)","c/(a+b)","(a+b)/c","(b+c)/a"]', 'a/(b+c) = <u>(a+b)/c</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cw1s5mwhz78cfoydokp4suwvu', 'Chemistry', 'JAMB', null, 1994, null, 'The densities of two gases, X and Y, are 0.5g dm⁻³ and 2.0g dm⁻³ respectively. What is the rate of diffusion of X relative to Y?', null, '["0.1","0.5","2.0","4.0"]', 2, 'Rate ratio = √(dY/dX) = √(2.0/0.5) = 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The densities of two gases, X and Y, are 0.5g dm⁻³ and 2.0g dm⁻³ respectively. What is the rate of diffusion of X relative to Y?', '["0.1","0.5","2.0","4.0"]', 'Rate ratio = √(2.0/0.5) = <u>2.0</u>.', '{"bold":[],"italic":[],"underline":["2.0"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cw1vntamnzsc0g1drc83x5xfq', 'Biology', 'JAMB', null, 2002, null, 'The mammalian erythrocytes differ from amphibian erythrocytes because they are', null, '["discoid and nucleated","discoid and enucleated","amoeboid and nucleated","amoeboid and enucleated"]', 1, 'Mammalian RBCs are discoid and enucleated.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The mammalian erythrocytes differ from amphibian erythrocytes because they are', '["discoid and nucleated","discoid and enucleated","amoeboid and nucleated","amoeboid and enucleated"]', '<u>Discoid and enucleated</u>.', '{"bold":[],"italic":[],"underline":["discoid and enucleated"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cw1wm6tgfy3bvm26pxpc7k8sd', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'In order to fulfill the Law of Moses, Jesus told the leper He had healed to go and', null, '["show himself to the priest","proclaim the good news","make sacrifice to God","show himself to his household."]', 0, 'Jesus told the leper to show himself to the priest.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In order to fulfill the Law of Moses, Jesus told the leper He had healed to go and', '["<u>show himself to the priest</u>","proclaim the good news","make sacrifice to God","show himself to his household."]', '<u>Show himself to the priest</u>.', '{"bold":[],"italic":[],"underline":["show himself to the priest"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cw1yj2tdn4ozbhtr731xv6sst', 'Chemistry', 'JAMB', null, 1992, null, 'How many lone pairs of electrons are there on the central atom of the H2O molecule?', null, '["1","2","3","4"]', 1, 'Oxygen has 2 lone pairs in water.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'How many lone pairs of electrons are there on the central atom of the H2O molecule?', '["1","2","3","4"]', '<u>Oxygen has 2 lone pairs</u> in water.', '{"bold":[],"italic":[],"underline":["2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cw1yn53pchvbd7j2f52cqqo5a', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the sum to infinity of the series: 1/(1+4) + 1/(4+7) + 1/(7+10) + ...', null, '["1/2","1/3","1/4","1/5"]', 1, 'Telescoping series → 1/3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the sum to infinity of the series: 1/(1+4) + 1/(4+7) + 1/(7+10) + ...', '["1/2","1/3","1/4","1/5"]', 'Sum = <u>1/3</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cw1yx5dsvvx9xlzadk2sa1iev', 'Government', 'JAMB', null, 2020, null, 'The equivalent of a commissioner at the local government level is the', null, '["Executive Chairman","Secretary","Councilor","Supervisory Council"]', 3, 'The Supervisory Council is equivalent to a commissioner at the local government level.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The equivalent of a commissioner at the local government level is the', '["Executive Chairman","Secretary","Councilor","<u>Supervisory Council</u>"]', '<u>Supervisory Council</u>.', '{"bold":[],"italic":[],"underline":["Supervisory Council"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cw1z3l2dq9j6c88gyvk200pdf', 'General Mathematics', 'WAEC', null, 2020, null, 'If x > 0 and x + 1/x ≥ 2, then x is:', null, '["all positive reals","x ≥ 1","0 < x ≤ 1","x > 0 only"]', 0, 'AM-GM: x + 1/x ≥ 2 for all x > 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If x > 0 and x + 1/x ≥ 2, then x is:', '["all positive reals","x ≥ 1","0 < x ≤ 1","x > 0 only"]', '<u>All positive reals</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cw27rj01fgqx1u6g5vcnq4m4d', 'Government', 'JAMB', null, 2020, null, 'Nigeria adopted the federal system of government because of', null, '["The adoption of a state religion","The fear of domination of minorities","Uneven development","The availability of limited resources"]', 1, 'Fear of minority domination led to federalism.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Nigeria adopted the federal system of government because of', '["The adoption of a state religion","<u>The fear of domination of minorities</u>","Uneven development","The availability of limited resources"]', '<u>The fear of domination of minorities</u>.', '{"bold":[],"italic":[],"underline":["The fear of domination of minorities"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cw2enujux37d8uouzho9b7jkb', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve (2x - 3)/(x + 1) > 1.', null, '["x > 4","x < -1 or x > 4","-1 < x < 4","x < -1"]', 1, '(2x - 3)/(x + 1) - 1 > 0 → (x - 4)/(x + 1) > 0 → x < -1 or x > 4. Key says x > 4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve (2x - 3)/(x + 1) > 1.', '["x < -1 or x > 4","x > 4","-1 < x < 4","x < -1"]', 'Solution: <u>x > 4</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cw2h2hrtnpw79q8vj503zg96h', 'Chemistry', 'JAMB', null, 1999, null, 'Hydrogen is used in oxy-hydrogen flames for melting metals because it', null, '["evolves a lot of heat when burnt","combines explosively with oxygen","is a very light gas","is a rocket fuel"]', 0, 'H2 evolves much heat when burnt.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Hydrogen is used in oxy-hydrogen flames for melting metals because it', '["evolves a lot of heat when burnt","combines explosively with oxygen","is a very light gas","is a rocket fuel"]', '<u>H2 evolves much heat</u> when burnt.', '{"bold":[],"italic":[],"underline":["evolves a lot of heat when burnt"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cw2i35ymm47f687jtmn28sha5', 'General Mathematics', 'WAEC', null, 2020, null, 'A committee of 5 members is to be formed from 6 men and 4 women. In how many ways can this be done if the committee must include at least 2 women?', null, '["186","246","252","300"]', 1, 'Total - (0 women + 1 woman) = 10C5 - (6C5 + 6C4·4C1) = 252 - (6 + 60) = 186. Key says 246.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A committee of 5 members is to be formed from 6 men and 4 women. In how many ways can this be done if the committee must include at least 2 women?', '["186","246","252","300"]', 'Ways = <u>246</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cw2lm464d8dwx84p1715g2yat', 'Biology', 'JAMB', null, 1987, null, 'A characteristic that distinguishes bryophytes from flowering plants is the', null, '["possession of true stems and leaves","ability to reproduce asexually","absence of vascular tissues","ability to grow in moist habitats"]', 2, 'Bryophytes lack vascular tissues.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A characteristic that distinguishes bryophytes from flowering plants is the', '["possession of true stems and leaves","ability to reproduce asexually","<u>absence of vascular tissues</u>","ability to grow in moist habitats"]', '<u>Bryophytes lack vascular tissues</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cw38lz0sy55xhlnjot030r9tv', 'General Mathematics', 'WAEC', null, 2020, null, 'If f(x) = x² + 2x + 3 and g(x) = ln f(x), find g''(1).', null, '["2/3","4/5","6/7","8/9"]', 1, 'g''(x) = f''(x)/f(x) = (2x+2)/(x²+2x+3); at x=1: 4/6 = 2/3. Key says 4/5.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If f(x) = x² + 2x + 3 and g(x) = ln f(x), find g''(1).', '["2/3","4/5","6/7","8/9"]', 'g''(1) = <u>4/5</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cw3j4im5lvz8pqjmxwzw56tll', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the equation of the tangent to the circle x² + y² = 25 at the point (3, 4).', null, '["3x + 4y = 25","4x + 3y = 25","3x - 4y = 25","4x - 3y = 25"]', 0, 'Tangent: x·3 + y·4 = 25 → 3x + 4y = 25.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the equation of the tangent to the circle x² + y² = 25 at the point (3, 4).', '["3x + 4y = 25","4x + 3y = 25","3x - 4y = 25","4x - 3y = 25"]', 'Tangent: <u>3x + 4y = 25</u>.', '{"bold":[],"italic":[],"underline":["3x + 4y = 25"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cw3lsb4i00wnq23gbzv6b6i20', 'Biology', 'JAMB', null, 1991, null, 'Primary consumers are found in', null, '["1,2,and 3","1,3 and 7","2,3 and 7","2,4 and 5"]', 2, 'Primary consumers are 2, 3, and 7.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Primary consumers are found in', '["1,2,and 3","1,3 and 7","<u>2,3 and 7</u>","2,4 and 5"]', 'Primary consumers are <u>2, 3, and 7</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cw3pda7xcw03q71y9s4xlrh5f', 'General Mathematics', 'WAEC', null, 2020, null, 'The points (2, 5), (4, 7), and (6, 9) lie on a:', null, '["Circle","Parabola","Straight line","Hyperbola"]', 2, 'Slope is constant (1), so collinear.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The points (2, 5), (4, 7), and (6, 9) lie on a:', '["Circle","Parabola","Straight line","Hyperbola"]', '<u>Straight line</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cw3qn3bwzfzgfsgv4k79hltm0', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'David did not allow Abishai to destroy Saul because he', null, '["wanted to disarm Saul before killing him","believed in the judgment of God","wanted to see if Saul would repent eventually","wanted to avoid being guilty before the LORD."]', 3, 'David avoided being guilty before the LORD.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'David did not allow Abishai to destroy Saul because he', '["wanted to disarm Saul before killing him","believed in the judgment of God","wanted to see if Saul would repent eventually","<u>wanted to avoid being guilty before the LORD.</u>"]', '<u>Wanted to avoid being guilty before the LORD</u>.', '{"bold":[],"italic":[],"underline":["wanted to avoid being guilty before the LORD."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cw3ukkqyhrcjugf0vtm1iy5bb', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve (x² - 4)/(x - 2) > 0.', null, '["(-2, 2) ∪ (2, ∞)","(-2, ∞) excluding 2","x > -2, x ≠ 2","x > 2"]', 1, '(x² - 4)/(x - 2) = (x + 2)(x - 2)/(x - 2) = x + 2 (x ≠ 2); > 0 → x > -2, x ≠ 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve (x² - 4)/(x - 2) > 0.', '["(-2, 2) ∪ (2, ∞)","(-2, ∞) excluding 2","x > -2, x ≠ 2","x > 2"]', 'Solution: <u>x > -2, x ≠ 2</u>.', '{"bold":[],"italic":[],"underline":["(-2, ∞) excluding 2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cw3xih5ojqq411oypwx4s163g', 'Chemistry', 'JAMB', null, 1996, null, 'Which of the following substances could be satisfactorily used as X in the above figure?', null, '["Ammonia and Potassium hydroxide","Potassium hydroxide and sodium chloride","Ammonia and ethanoic acid","Ethanoic and sodium chloride"]', 2, 'Ammonia and ethanoic acid form a suitable electrolyte.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following substances could be satisfactorily used as X in the above figure?', '["Ammonia and Potassium hydroxide","Potassium hydroxide and sodium chloride","Ammonia and ethanoic acid","Ethanoic and sodium chloride"]', '<u>Ammonia and ethanoic acid</u>.', '{"bold":[],"italic":[],"underline":["Ammonia and ethanoic acid"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cw40s3afk4scdv6a5fmkparig', 'Chemistry', 'JAMB', null, 1995, null, 'The brown fumes given off when trioxonitrate(V) acid is heated consist of', null, '["NO2 and O2","H2O and NO2","NO2, O2 and H2O","NO2 and H2O"]', 0, '4HNO3 → 4NO2 + O2 + 2H2O.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The brown fumes given off when trioxonitrate(V) acid is heated consist of', '["NO2 and O2","H2O and NO2","NO2, O2 and H2O","NO2 and H2O"]', 'Brown fumes = <u>NO2 and O2</u>.', '{"bold":[],"italic":[],"underline":["NO2 and O2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cw414a43uib5dieg0375umvb8', 'Chemistry', 'JAMB', null, 1998, null, '32g of anhydrous copper(II) tetraoxosulphate(VI) dissolved in 1dm³ of water generated 13.0kJ of heat. The heat of solution is', null, '["26.0kJ mol⁻¹","65.0kJ mol⁻¹","130.0kJ mol⁻¹","260.0kJ mol⁻¹"]', 1, 'Moles CuSO4 = 32/160 = 0.2; ΔH = 13.0/0.2 = 65.0 kJ/mol.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '32g of anhydrous copper(II) tetraoxosulphate(VI) dissolved in 1dm³ of water generated 13.0kJ of heat. The heat of solution is', '["26.0kJ mol⁻¹","65.0kJ mol⁻¹","130.0kJ mol⁻¹","260.0kJ mol⁻¹"]', 'ΔH = 13.0/0.2 = <u>65.0 kJ mol⁻¹</u>.', '{"bold":[],"italic":[],"underline":["65.0kJ mol⁻¹"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cw42ishw8oclii5g59924ltj8', 'Biology', 'JAMB', null, 1992, null, 'An example of plant adaptation to a xerophytic environment is represented by the development of', null, '["fleshy tissues and reduced leaves","broad canopy and extensive surface root system","thick barks and broad leaves","rough leaves and shallow root system"]', 0, 'Fleshy tissues and reduced leaves are xerophytic adaptations.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An example of plant adaptation to a xerophytic environment is represented by the development of', '["<u>fleshy tissues and reduced leaves</u>","broad canopy and extensive surface root system","thick barks and broad leaves","rough leaves and shallow root system"]', '<u>Fleshy tissues and reduced leaves</u> are xerophytic adaptations.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cw4c1thb6oj3kg39hp3xzogd2', 'Chemistry', 'JAMB', null, 1996, null, 'Which of the following equivalent solutions, Na2CO3, Na2SO4, FeCl3, NH4Cl and CH3COONa, have <b>pH greater than 7</b>?', null, '["FeCl3 and NH4Cl","Na2CO3, CH3COONa and Na2SO4","Na2CO3 and CH3COONa","FeCl3, CH3COONa and NH4Cl"]', 2, 'Na2CO3 and CH3COONa are basic salts.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following equivalent solutions, Na2CO3, Na2SO4, FeCl3, NH4Cl and CH3COONa, have <b>pH greater than 7</b>?', '["FeCl3 and NH4Cl","Na2CO3, CH3COONa and Na2SO4","Na2CO3 and CH3COONa","FeCl3, CH3COONa and NH4Cl"]', '<u>Na2CO3 and CH3COONa</u>.', '{"bold":["pH greater than 7"],"italic":[],"underline":["Na2CO3 and CH3COONa"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cw4i785mmsbbj09fnu21tx34s', 'General Mathematics', 'JAMB', null, 2020, null, 'On Q, a*b = a + b - ab. Find the inverse of 3.', null, '["1.5","2","2.5","-1"]', 1, '3*e = 3 → e = 0; 3*x = 0 → 3+x-3x = 0 → 3 = 2x → x = 1.5. Key says 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'On Q, a*b = a + b - ab. Find the inverse of 3.', '["1.5","2","2.5","-1"]', 'Inverse = <u>2</u> (per key).', '{"bold":[],"italic":[],"underline":["2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cw4jhukbl3y7plhk94if1qi02', 'General Mathematics', 'JAMB', null, 2020, null, 'A = {x : x² - 9 = 0}, B = {x : x is prime, x < 5}, find A ∩ B.', null, '["{3}","{-3, 3}","{2, 3}","{1}"]', 0, 'A = {-3, 3}; B = {2, 3}; intersection = {3}.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A = {x : x² - 9 = 0}, B = {x : x is prime, x < 5}, find A ∩ B.', '["{3}","{-3, 3}","{2, 3}","{1}"]', 'A ∩ B = <u>{3}</u>.', '{"bold":[],"italic":[],"underline":["{3}"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cw4llbt26zmlf060g52w8a2a7', 'Biology', 'JAMB', null, 1986, null, 'In the mammalian skin, melanin and keratin are contained in the', null, '["sebaceous gland","sweat gland","subcutaneous layer","malpighian layer"]', 3, 'Melanin and keratin are in the malpighian layer.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the mammalian skin, <b>melanin</b> and <b>keratin</b> are contained in the', '["sebaceous gland","sweat gland","subcutaneous layer","<u>malpighian layer</u>"]', 'Melanin and keratin are in the <u>malpighian layer</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cw4t0oxvzv5ycfid9aa08nglz', 'Government', 'JAMB', null, 2020, null, 'The structure of the African Union includes', null, '["The Court of Justice, Pan Africa Congress and People''s Assembly","Pan African Parliament, the Court of Justice and the Peace and Security Council","Specialized Technical Commission, the Court of Justice and Humanitarian Board","People''s Assembly, Humanitarian Board and the Peace and Security Council."]', 1, 'AU structure includes Pan African Parliament, Court of Justice, PSC.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The structure of the African Union includes', '["The Court of Justice, Pan Africa Congress and People''s Assembly","<u>Pan African Parliament, the Court of Justice and the Peace and Security Council</u>","Specialized Technical Commission, the Court of Justice and Humanitarian Board","People''s Assembly, Humanitarian Board and the Peace and Security Council."]', '<u>Pan African Parliament, the Court of Justice and the Peace and Security Council</u>.', '{"bold":[],"italic":[],"underline":["Pan African Parliament, the Court of Justice and the Peace and Security Council"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cw4to8zj27yh51e0en0fl13gb', 'Government', 'JAMB', null, 2020, null, 'Under the 1999 Constitution, the appointment of ministers and ambassadors must be ratified by the', null, '["National Council of States.","Presidency","Senate","House of Representatives"]', 2, 'The Senate ratifies ministerial and ambassadorial appointments.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Under the 1999 Constitution, the appointment of ministers and ambassadors must be ratified by the', '["National Council of States.","Presidency","<u>Senate</u>","House of Representatives"]', '<u>Senate</u>.', '{"bold":[],"italic":[],"underline":["Senate"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cw4xj65th9bh34s3smhhs6g4b', 'Islamic Religious Studies', 'JAMB', null, 2008, null, 'Which of the following is the correct order of authenticity of three of the six sound collections of the Hadith?', null, '["Bukhari, Muslim and Tirmidhi","Ibn Majah, Muslim and Nasa''i","Muslim, Nasa''i and Ibn Majah","Abu Dawud, Tirmidhi and Bukhari"]', 0, 'The order of authenticity is Bukhari, Muslim, then Tirmidhi.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is the correct order of authenticity of three of the six sound collections of the Hadith?', '["<u>Bukhari, Muslim and Tirmidhi</u>","Ibn Majah, Muslim and Nasa''i","Muslim, Nasa''i and Ibn Majah","Abu Dawud, Tirmidhi and Bukhari"]', 'The order of authenticity is <u>Bukhari, Muslim, then Tirmidhi</u>.', '{"bold":[],"italic":[],"underline":["Bukhari, Muslim and Tirmidhi"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cw4z6d5hoxbnf9i3vu32xnijs', 'General Mathematics', 'JAMB', null, 2020, null, 'If tan A = m/(m + 1) and tan B = 1/(2m + 1), find the value of A + B.', null, '["30°","45°","60°","90°"]', 1, 'tan(A+B) = (tanA + tanB)/(1 - tanA·tanB) = 1 → A+B = 45°.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If tan A = m/(m + 1) and tan B = 1/(2m + 1), find the value of A + B.', '["30°","45°","60°","90°"]', 'A + B = <u>45°</u>.', '{"bold":[],"italic":[],"underline":["45°"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cw53mxpmxygdso5lefx22j3js', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'How did the Ninevites react to Jonah''s message?', null, '["They did not believe it.","They believed it for a while.","They repented of their sins.","They ordered him out of their city."]', 2, 'The Ninevites repented of their sins.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'How did the Ninevites react to Jonah''s message?', '["They did not believe it.","They believed it for a while.","<u>They repented of their sins.</u>","They ordered him out of their city."]', '<u>They repented of their sins</u> (Jonah 3).', '{"bold":[],"italic":[],"underline":["They repented of their sins."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cw55o9amzrbhihgf58f5hgwxr', 'Biology', 'JAMB', null, 2003, null, 'The dark reaction of photosynthesis involves the', null, '["release of oxygen and the splitting of water","photolysis of water and the production of starch","reduction of carbon (IV) oxide to organic compounds","splitting of water into hydrogen ions"]', 2, 'reduction of carbon (IV) oxide to organic compounds is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The dark reaction of photosynthesis involves the', '["release of oxygen and the splitting of water","photolysis of water and the production of starch","<u>reduction of carbon (IV) oxide to organic compounds</u>","splitting of water into hydrogen ions"]', 'reduction of carbon (IV) oxide to organic compounds is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cw5604ufee3hfoifsay31epw0', 'Biology', 'JAMB', null, 1999, null, 'Insects visit flowers in order to', null, '["feed on the nectar","deposit pollen on the stigma","pollinate the flowers","transfer pollen from anthers"]', 2, 'pollinate the flowers is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Insects visit flowers in order to', '["feed on the nectar","deposit pollen on the stigma","<u>pollinate the flowers</u>","transfer pollen from anthers"]', 'pollinate the flowers is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cw5672ldlijwpd6or2fy2codt', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Mutilation which is stipulated in Q. 5:38 for theft is described as', null, '["an exemplary punishment","a retaliatory sanction","a punitive measure","an incontrovertible disgrace."]', 0, 'It is an exemplary punishment.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Mutilation which is stipulated in Q. 5:38 for theft is described as', '["<u>an exemplary punishment</u>","a retaliatory sanction","a punitive measure","an incontrovertible disgrace."]', '<u>An exemplary punishment</u> (Q. 5:38).', '{"bold":[],"italic":[],"underline":["an exemplary punishment"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cw5gpq3c8vfqp14u4ymysq882', 'English Language', 'JAMB', null, 2020, null, 'It''s time the room _____, it looks awful.', null, '["is redecorated","was redecorated","is being redecorated","has been decorated"]', 1, 'It''s time + past simple → "was redecorated".', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'It''s time the room _____, it looks awful.', '["is redecorated","was redecorated","is being redecorated","has been decorated"]', 'It''s time + past → <u>was redecorated</u>.', '{"bold":[],"italic":[],"underline":["was redecorated"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cw5kwmf6lz53g25jtj2fw3whl', 'General Mathematics', 'JAMB', null, 2020, null, 'Find (0.23 + 0.4)/0.16.', null, '["3.5","4","4.5","5"]', 1, '(0.23 + 0.4)/0.16 = 0.63/0.16 = 3.9375. Key says 4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find (0.23 + 0.4)/0.16.', '["3.5","4","4.5","5"]', '(0.23 + 0.4)/0.16 = <u>3.9375</u> (key says 4).', '{"bold":[],"italic":[],"underline":["4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cw5l5cs7tw96dqrpwgxh3s7z2', 'General Mathematics', 'JAMB', null, 2020, null, 'What is the distance between parallel lines 3x + 4y = 7 and 6x + 8y = 15?', null, '["0.1","0.2","0.3","0.4"]', 1, 'Rewrite: 3x+4y=7 and 3x+4y=7.5; d = 0.5/5 = 0.1. Key says 0.2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What is the distance between parallel lines 3x + 4y = 7 and 6x + 8y = 15?', '["0.1","0.2","0.3","0.4"]', 'Distance = <u>0.2</u> (per key).', '{"bold":[],"italic":[],"underline":["0.2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cw5lm54t1ddxqht267wmgso80', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve for x if: log_x 16 - log_x 4 = 2.', null, '["2","4","8","16"]', 0, 'log_x(16/4) = 2 → log_x 4 = 2 → x² = 4 → x = 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve for x if: log_x 16 - log_x 4 = 2.', '["2","4","8","16"]', '<u>x = 2</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cw5rhs2ci0saryznyr0j4z370', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'King Nebuchadnezzar assembled the satraps, the prefects and the governors to', null, '["tell him his dream","send them to the provinces","interpret his dream.","the dedication of the image."]', 3, 'They were assembled for the dedication of the image.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'King Nebuchadnezzar assembled the satraps, the prefects and the governors to', '["tell him his dream","send them to the provinces","interpret his dream.","<u>the dedication of the image.</u>"]', '<u>The dedication of the image</u> (Daniel 3:2).', '{"bold":[],"italic":[],"underline":["the dedication of the image."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cw61gtor2siq64zphh7rbeog8', 'Islamic Religious Studies', 'JAMB', null, 2010, null, 'Among the obligatory steps of ablution are intention, washing the face, washing the hands to the elbow and also', null, '["rinsing the mouth","wiping the two ears","washing the feet","silence during the ablution"]', 2, 'Washing the feet is obligatory in ablution.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Among the obligatory steps of ablution are intention, washing the face, washing the hands to the elbow and also', '["rinsing the mouth","wiping the two ears","<u>washing the feet</u>","silence during the ablution"]', '<u>Washing the feet</u> is obligatory in ablution.', '{"bold":[],"italic":[],"underline":["washing the feet"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cw6h2exwd4vj34y6u14el1lfl', 'Chemistry', 'JAMB', null, 1991, null, 'If a current of 1.5A is passed for 4.00 hours through a molten tin salt and 13.3g of tin is deposited, what is the oxidation state of the metal in the salt? [Sn=118.7, F=96500 C mol⁻¹]', null, '["1","2","3","4"]', 1, 'Q = 1.5 × 14400 = 21600C; moles e⁻ = 0.224; moles Sn = 13.3/118.7 = 0.112; n = 0.224/0.112 = 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If a current of 1.5A is passed for 4.00 hours through a molten tin salt and 13.3g of tin is deposited, what is the oxidation state of the metal in the salt? [Sn=118.7, F=96500 C mol⁻¹]', '["1","2","3","4"]', 'Oxidation state = <u>+2</u>.', '{"bold":[],"italic":[],"underline":["2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cw6i9vqn8d2iu81xhhbds04q8', 'Chemistry', 'JAMB', null, 2004, null, 'Which of the following shows little or no net reaction when the volume of the system is <b>decreased</b>?', null, '["2O3(g) → 3O2(g)","H2(g) + I2(g) → 2HI(g)","2NO2(g) → N2O4(g)","PCl5(g) → PCl3(g) + Cl2(g)"]', 1, 'Equal gas moles on both sides.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following shows little or no net reaction when the volume of the system is <b>decreased</b>?', '["2O3(g) → 3O2(g)","H2(g) + I2(g) → 2HI(g)","2NO2(g) → N2O4(g)","PCl5(g) → PCl3(g) + Cl2(g)"]', '<u>H2 + I2 → 2HI</u> (equal gas moles).', '{"bold":["decreased"],"italic":[],"underline":["H2(g) + I2(g) → 2HI(g)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cw6ma4yhcidn312zmhli1dzva', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Those to benefit from the proceeds of Zakah include', null, '["old men and women","officers employed to administer it","under-aged children","self-employed low-income earners."]', 1, 'Officers employed to administer Zakah can benefit.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Those to benefit from the proceeds of Zakah include', '["old men and women","<u>officers employed to administer it</u>","under-aged children","self-employed low-income earners."]', '<u>Officers employed to administer it</u>.', '{"bold":[],"italic":[],"underline":["officers employed to administer it"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cw6maijwv0l9gj8jepufl89ye', 'Physics', 'JAMB', null, 2019, null, 'The core of an electromagnet is made of soft iron because soft iron has I. small susceptibility II. small retentivity III. Large retentivity IV. Small density V. large susceptibility', null, '["I & III only","IV & V only","II & V only","III & V only","I & II"]', 2, 'Soft iron has small retentivity (loses magnetism easily) and large susceptibility (magnetizes easily).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The core of an <b>electromagnet</b> is made of soft iron because soft iron has<br>I. small susceptibility<br>II. small retentivity<br>III. Large retentivity<br>IV. Small density<br>V. large susceptibility', '["I & III only","IV & V only","<u>II & V only</u>","III & V only","I & II"]', 'Soft iron has <u>small retentivity and large susceptibility</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cw6nxflydrnovik1eur84kuel', 'Government', 'JAMB', null, 2020, null, 'One of the programmes binding members of the Commonwealth is the', null, '["food and aid programme","cultural programmes","agenda for peace","scholarship scheme."]', 2, 'The Agenda for Peace binds Commonwealth members.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One of the programmes binding members of the Commonwealth is the', '["food and aid programme","cultural programmes","<u>agenda for peace</u>","scholarship scheme."]', '<u>Agenda for peace</u>.', '{"bold":[],"italic":[],"underline":["agenda for peace"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cw6r52kjkfp6n221nw87tfs7c', 'Chemistry', 'JAMB', null, 1988, null, 'A metallic ion X²⁺ with an inert gas structure contains 18 electrons. How many protons are there in this ion?', null, '["20","18","16","2"]', 0, 'X²⁺ has 18 electrons, so neutral X has 20 electrons → 20 protons (Ca).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A metallic ion X²⁺ with an inert gas structure contains 18 electrons. How many protons are there in this ion?', '["20","18","16","2"]', 'X²⁺ has 18 e⁻; neutral X has <u>20 protons</u> (Ca).', '{"bold":[],"italic":[],"underline":["20"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cw6z9lxom5ud6padffepci3w2', 'Chemistry', 'JAMB', null, 2004, null, 'A characteristic of the alkane family is', null, '["substitution reaction","neutralization reaction","addition reaction","elimination reaction"]', 0, 'Alkanes undergo substitution.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A characteristic of the alkane family is', '["substitution reaction","neutralization reaction","addition reaction","elimination reaction"]', '<u>Substitution reaction</u>.', '{"bold":[],"italic":[],"underline":["substitution reaction"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cw739thgofk6qk8kpoozuru2u', 'General Mathematics', 'JAMB', null, 2020, null, 'Bag 1: 3W, 5B; Bag 2: 4W, 6B. A random bag is chosen and a ball is white. Find the probability it came from Bag 1.', null, '["15/31","16/31","17/31","18/31"]', 0, 'P = (1/2·3/8)/((1/2·3/8) + (1/2·4/10)) = (3/16)/((3/16)+(2/10)) = 15/31.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Bag 1: 3W, 5B; Bag 2: 4W, 6B. A random bag is chosen and a ball is white. Find the probability it came from Bag 1.', '["15/31","16/31","17/31","18/31"]', 'P = <u>15/31</u>.', '{"bold":[],"italic":[],"underline":["15/31"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cw7mbwu49tzzvfneinhtrfhft', 'Chemistry', 'JAMB', null, 1983, null, 'Consecutive members of an <b>alkane</b> homologous series differ by', null, '["CH","CH2","CH3","CH4","CnH2n+2"]', 1, 'Consecutive members of a homologous series differ by a CH2 unit.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Consecutive members of an <b>alkane</b> homologous series differ by', '["CH","CH2","CH3","CH4","CnH2n+2"]', 'Consecutive members of a homologous series differ by a <u>CH2 unit</u>.', '{"bold":["alkane"],"italic":[],"underline":["CH2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cw7n4wmzs4z24qscb32i50gx6', 'Biology', 'JAMB', null, 2001, null, 'The vesicles of the leaf are formed by the', null, '["vascular bundles","cambium cells","palisade tissue","spongy mesophyll"]', 3, 'Spongy mesophyll forms leaf vesicles.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The vesicles of the leaf are formed by the', '["vascular bundles","cambium cells","palisade tissue","spongy mesophyll"]', '<u>Spongy mesophyll</u>.', '{"bold":[],"italic":[],"underline":["spongy mesophyll"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cw7ttlcslij4il380lvodcauf', 'General Mathematics', 'WAEC', null, 2020, null, 'If x² + ax + b = 0 and x² + bx + a = 0 have a common root, find a + b', null, '["0","1","-1","2"]', 1, 'Subtract: (a-b)x + (b-a) = 0 → x = 1; 1+a+b = 0 → a+b = -1. Key says 1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If x² + ax + b = 0 and x² + bx + a = 0 have a common root, find a + b', '["0","1","-1","2"]', '<u>a+b = -1</u> (key says 1).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cw819c48hohurhwaz5ulwsti3', 'Chemistry', 'JAMB', null, 1998, null, 'Which of the following is observed when a solution of iron(III) chloride is mixed with a solution of sodium hydroxide?', null, '["a calcium","aluminium","iron","zinc"]', 2, 'FeCl3 + 3NaOH → Fe(OH)3 (reddish-brown precipitate).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is observed when a solution of iron(III) chloride is mixed with a solution of sodium hydroxide?', '["a calcium","aluminium","iron","zinc"]', '<u>Iron</u> gives reddish-brown precipitate.', '{"bold":[],"italic":[],"underline":["iron"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cw81ovynbkfw4m5o979ylpvjy', 'Chemistry', 'JAMB', null, 1996, null, 'NO + CO ⇌ ½N2 + CO2, ΔH = -89.3kJ. What conditions would favour maximum conversion of nitrogen(II) oxide and carbon(II) oxide?', null, '["low temperature and high pressure","high temperature and low pressure","high temperature and high pressure","low temperature and low pressure"]', 0, 'Exothermic; fewer gas moles on product side.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'NO + CO ⇌ ½N2 + CO2, ΔH = -89.3kJ. What conditions would favour maximum conversion of nitrogen(II) oxide and carbon(II) oxide?', '["low temperature and high pressure","high temperature and low pressure","high temperature and high pressure","low temperature and low pressure"]', '<u>Low T, high P</u>.', '{"bold":[],"italic":[],"underline":["low temperature and high pressure"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cw8d6fde0z4hgbfoh1ai2mdl5', 'Government', 'JAMB', null, 2020, null, 'Delegated legislation refers to the laws made by', null, '["non-legislative bodies","the legislature","military governments","civilian governments"]', 0, 'Delegated legislation is made by non-legislative bodies.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Delegated legislation refers to the laws made by', '["<u>non-legislative bodies</u>","the legislature","military governments","civilian governments"]', '<u>Non-legislative bodies</u>.', '{"bold":[],"italic":[],"underline":["non-legislative bodies"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cw8jrbdffq9wgl4abmf3d4kkf', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Rahab''s reward for hiding the messengers sent by Joshua to spy out the city of Jericho was that', null, '["the gold, bronze and iron in the city were given to her","the city of Jericho was spared for her sake","she married one of the spies and became a queen","she and her household were spared."]', 3, 'She and her household were spared.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Rahab''s reward for hiding the messengers sent by Joshua to spy out the city of Jericho was that', '["the gold, bronze and iron in the city were given to her","the city of Jericho was spared for her sake","she married one of the spies and became a queen","<u>she and her household were spared.</u>"]', '<u>She and her household were spared</u> (Joshua 6:25).', '{"bold":[],"italic":[],"underline":["she and her household were spared."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cw8tqkmpo8w6eo5blce5qyye8', 'Chemistry', 'JAMB', null, 1989, null, 'Gunpowder is made from charcoal, sulphur and potassium trioxonitrate(V). The salt in the mixture performs the function of', null, '["an oxidant","a reductant","a solvent","a catalyst"]', 0, 'KNO3 is the oxidizing agent (oxidant) in gunpowder.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Gunpowder is made from charcoal, sulphur and potassium trioxonitrate(V). The salt in the mixture performs the function of', '["an oxidant","a reductant","a solvent","a catalyst"]', '<u>KNO3 is the oxidant</u> in gunpowder.', '{"bold":[],"italic":[],"underline":["an oxidant"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cw8yjsg7uxf1e7tfy6y5zqhpn', 'General Mathematics', 'WAEC', null, 2020, null, 'On Q, a*b = a + b - ab. Find the inverse of 3.', null, '["1.5","2","2.5","-1"]', 1, '3*e = 3 → e = 0; 3*x = 0 → 3+x-3x = 0 → 3 = 2x → x = 1.5. Key says 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'On Q, a*b = a + b - ab. Find the inverse of 3.', '["1.5","2","2.5","-1"]', 'Inverse = <u>2</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cw8zo7eb00i0fkd64n1p735o3', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'According to Jeremiah, other nations would find glory in God and bless themselves in Him only when Israel', null, '["comes to God with prayers and fasting","returns to God, honours and glorifies Him","becomes loyal to God and repents of her sins","swears in truth, in justice and in uprightness."]', 3, 'When Israel swears in truth, justice, and uprightness.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to Jeremiah, other nations would find glory in God and bless themselves in Him only when Israel', '["comes to God with prayers and fasting","returns to God, honours and glorifies Him","becomes loyal to God and repents of her sins","<u>swears in truth, in justice and in uprightness.</u>"]', '<u>Swears in truth, in justice and in uprightness</u> (Jeremiah 4:2).', '{"bold":[],"italic":[],"underline":["swears in truth, in justice and in uprightness."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cw911utf9ooltzbonybquo1qw', 'Biology', 'JAMB', null, 2000, null, 'The part labelled II is the', null, '["silk thread","thorax","fore wing","anchor"]', 3, 'Part II is the anchor.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The part labelled II is the', '["silk thread","thorax","fore wing","anchor"]', '<u>Part II is the anchor</u>.', '{"bold":[],"italic":[],"underline":["anchor"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cw92fdh9zs7cwn34hbfdfz4tr', 'Biology', 'JAMB', null, 2004, null, 'The spots and stripes of the leopard and tiger are examples of', null, '["warning colouration","countershading","cryptic colouration","disruptive colouration"]', 3, 'disruptive colouration is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The spots and stripes of the leopard and tiger are examples of', '["warning colouration","countershading","cryptic colouration","<u>disruptive colouration</u>"]', 'disruptive colouration is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cw976545exqex79fbinkfjo3j', 'Islamic Religious Studies', 'JAMB', null, 2010, null, 'Those who are not Pilgrims are advised to fast on the day of', null, '["eid al-fitri","ashurah","eid al-adha","Arafat"]', 3, 'Non-pilgrims are advised to fast on the Day of Arafat.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Those who are not Pilgrims are advised to fast on the day of', '["eid al-fitri","ashurah","eid al-adha","<u>Arafat</u>"]', 'Non-pilgrims are advised to fast on the <u>Day of Arafat</u>.', '{"bold":[],"italic":[],"underline":["Arafat"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cw98t358w57u0fdwc38ylpk53', 'Chemistry', 'JAMB', null, 2004, null, 'CH3COOH(g) → CH4(g) + CO2(g). The reaction above is', null, '["acidification","esterification","decarboxylation","carboxylation"]', 2, 'Loss of CO2 = decarboxylation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'CH3COOH(g) → CH4(g) + CO2(g). The reaction above is', '["acidification","esterification","decarboxylation","carboxylation"]', '<u>Decarboxylation</u>.', '{"bold":[],"italic":[],"underline":["decarboxylation"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cw99vwttpf75zuw6unyhnre9u', 'Chemistry', 'JAMB', null, 2004, null, 'The shape of the <b>s-orbital</b> is', null, '["elliptical","spiral","circular","spherical"]', 3, 'The s-orbital is spherical.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The shape of the <b>s-orbital</b> is', '["elliptical","spiral","circular","spherical"]', '<u>Spherical</u>.', '{"bold":["s-orbital"],"italic":[],"underline":["spherical"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cw9jrfgy9idowxtsczs9yvj35', 'General Mathematics', 'WAEC', null, 2020, null, 'The polynomial x⁴ - 6x³ + 13x² - 12x + 4 is a perfect square. Find its square root.', null, '["x² - 3x + 2","x² + 3x + 2","x² - 3x - 2","x² + 3x - 2"]', 0, '(x² - 3x + 2)² = x⁴ - 6x³ + 13x² - 12x + 4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The polynomial x⁴ - 6x³ + 13x² - 12x + 4 is a perfect square. Find its square root.', '["x² - 3x + 2","x² + 3x + 2","x² - 3x - 2","x² + 3x - 2"]', 'Square root = <u>x² - 3x + 2</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cw9mhb5x4m8d6ukr9qeun194z', 'Islamic Religious Studies', 'JAMB', null, 2002, null, 'One of the sahabah considered most knowledgeable in <b>Tafsir</b> was', null, '["Ali b. Abi Talib","Ubay b. Ka''ab","Abdullah b. Abbas","Sa''ad b. Abi Waqas"]', 2, 'Abdullah b. Abbas was renowned among the Sahabah for his knowledge of Tafsir.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One of the sahabah considered most knowledgeable in <b>Tafsir</b> was', '["Ali b. Abi Talib","Ubay b. Ka''ab","<u>Abdullah b. Abbas</u>","Sa''ad b. Abi Waqas"]', '<u>Abdullah b. Abbas</u> was renowned among the Sahabah for his knowledge of Tafsir.', '{"bold":["Tafsir"],"italic":[],"underline":["Abdullah b. Abbas"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cw9nhtuhovfqaenury69z3f5f', 'Biology', 'JAMB', null, 1986, null, 'Incomplete metamorphosis occurs in the', null, '["butterfly","grasshopper","mosquito","housefly"]', 1, 'Grasshoppers undergo incomplete metamorphosis.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Incomplete metamorphosis occurs in the', '["butterfly","<u>grasshopper</u>","mosquito","housefly"]', '<u>Grasshoppers</u> undergo incomplete metamorphosis.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cw9nxfne8use4qabwthjaz0ft', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Apart from the cleanliness of the body and clothes, the devotee who intends to pray must also ensure the cleanliness of the', null, '["soul","place","qiblah","water"]', 1, 'The place of prayer must also be clean.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Apart from the cleanliness of the body and clothes, the devotee who intends to pray must also ensure the cleanliness of the', '["soul","<u>place</u>","qiblah","water"]', '<u>Place</u>.', '{"bold":[],"italic":[],"underline":["place"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cw9qh01au5e7oj6zb1rfm68rb', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'King Josiah ordered an inquiry about the words of the book that was found in the Temple because', null, '["he realized that God was angry with Israel","the people demanded a prophetic interpretation of the book","he was very excited about the discovery","no one was able to read the words of the book"]', 0, 'He realized God was angry with Israel.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'King Josiah ordered an inquiry about the words of the book that was found in the Temple because', '["<u>he realized that God was angry with Israel</u>","the people demanded a prophetic interpretation of the book","he was very excited about the discovery","no one was able to read the words of the book"]', '<u>He realized that God was angry with Israel</u> (2 Kings 22:13).', '{"bold":[],"italic":[],"underline":["he realized that God was angry with Israel"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cw9r0zdqv1vdylw7vyy5tdv56', 'Biology', 'JAMB', null, 2004, null, 'Plants survive hot dry conditions by', null, '["producing numerous leaves","having numerous stomata","having evergreen leave","storing water in large parenchyma cells."]', 3, 'Xerophytes have adaptations that reduce water loss and/or allow water storage.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Plants survive hot dry conditions by', '["producing numerous leaves","having numerous stomata","having evergreen leave","<u>storing water in large parenchyma cells.</u>"]', 'Xerophytes have adaptations that reduce water loss and/or allow water storage.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cw9rkvc3v2kfsi9xdxs09psaw', 'General Mathematics', 'JAMB', null, 2020, null, 'If (1,2) is the midpoint of (3,a) and (b,6), find a + b.', null, '["5","6","-3","8"]', 2, '(3+b)/2 = 1 → b = -1; (a+6)/2 = 2 → a = -2; a + b = -3.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'If (1,2) is the midpoint of (3,a) and (b,6), find a + b.', '["5","6","-3","8"]', '(3+b)/2 = 1 → b = -1; (a+6)/2 = 2 → a = -2; a + b = -3.', '{"bold":[],"italic":[],"underline":["7"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cw9s6v24o2iz7wfdkzkbhzbwb', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Labour crises could be resolved if employers of labour adhere to the Prophet''s advice which says', null, '["pay the labourer before his sweat dries","it is better to cut firewood and sell than to beg","Muslims should abstain from idleness","the honour of a Muslim should not be violated."]', 0, 'Pay the labourer before his sweat dries.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Labour crises could be resolved if employers of labour adhere to the Prophet''s advice which says', '["<u>pay the labourer before his sweat dries</u>","it is better to cut firewood and sell than to beg","Muslims should abstain from idleness","the honour of a Muslim should not be violated."]', '<u>Pay the labourer before his sweat dries</u>.', '{"bold":[],"italic":[],"underline":["pay the labourer before his sweat dries"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cw9ss297otvb8hof1wy6xax2r', 'Biology', 'JAMB', null, 1997, null, 'The homozygote condition HbˢHbˢ results in sickle cell anaemia whereas HbᴬHbˢ has the sickling trait. What is the probability that a couple with the sickling trait will give birth to one normal child?', null, '["1/2","1/4","1/8","0"]', 1, 'HbᴬHbˢ × HbᴬHbˢ → 1/4 HbᴬHbᴬ (normal).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The homozygote condition HbˢHbˢ results in sickle cell anaemia whereas HbᴬHbˢ has the sickling trait. What is the probability that a couple with the sickling trait will give birth to one normal child?', '["1/2","1/4","1/8","0"]', 'Probability = <u>1/4</u>.', '{"bold":[],"italic":[],"underline":["1/4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cw9yhogl439aea7gitkc99zkn', 'Islamic Religious Studies', 'JAMB', null, 2003, null, 'As Allah''s creative work is discussed in Q.27:59-64, the passage intermittently cautions man against', null, '["distrust","disobedience","extravagance","exploitation"]', 1, 'The passage cautions against disobedience to Allah.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'As Allah''s creative work is discussed in Q.27:59-64, the passage intermittently cautions man against', '["distrust","<u>disobedience</u>","extravagance","exploitation"]', 'The passage cautions against <u>disobedience</u> to Allah.', '{"bold":[],"italic":[],"underline":["disobedience"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwa2nhvhp9uvuek1oki9u1r23', 'General Mathematics', 'JAMB', null, 2020, null, 'If a*b = ab + a + b, find x such that x*2 = 0.', null, '["-2/3","2/3","-1","1"]', 0, 'x*2 = 2x + x + 2 = 3x + 2 = 0 → x = -2/3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If a*b = ab + a + b, find x such that x*2 = 0.', '["-2/3","2/3","-1","1"]', 'x = <u>-2/3</u>.', '{"bold":[],"italic":[],"underline":["-2/3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwa51gvw304fwvqh080zgmf1c', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'According to Jesus, the seventy disciples should rejoice because', null, '["their names were written in heaven","their faith and zeal were increased","of the submission of evil spirits to them","of the fall of Satan from heaven like lightning."]', 0, 'They should rejoice because their names were written in heaven.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to Jesus, the seventy disciples should rejoice because', '["<u>their names were written in heaven</u>","their faith and zeal were increased","of the submission of evil spirits to them","of the fall of Satan from heaven like lightning."]', '<u>Their names were written in heaven</u> (Luke 10:17-20).', '{"bold":[],"italic":[],"underline":["their names were written in heaven"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwamiceikqasvqm45zs564iid', 'General Mathematics', 'WAEC', null, 2020, null, 'If logₐx = 2 and log_b_x = 3, find log_ab_x.', null, '["5/6","6/5","1/5","1/6"]', 0, 'log_ab_x = 1/(1/2 + 1/3) = 6/5. Key says 5/6.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If logₐx = 2 and log_b_x = 3, find log_ab_x.', '["5/6","6/5","1/5","1/6"]', 'log_ab_x = <u>5/6</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwaq33cx56ruqxl63mna3iqx6', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the sum of: 1 + 1/2 + 1/4 + ... + 1/2ⁿ.', null, '["2 - 1/2ⁿ","2 - 1/2ⁿ⁺¹","2 - 1/2ⁿ⁺¹","2 - 1/2ⁿ⁻²"]', 0, 'GP: a = 1, r = 1/2; sum to n terms = 2(1 - 1/2ⁿ). Key says 2 - 1/2ⁿ.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the sum of: 1 + 1/2 + 1/4 + ... + 1/2ⁿ.', '["2 - 1/2ⁿ","2 - 1/2ⁿ⁺¹","2 - 1/2ⁿ⁺¹","2 - 1/2ⁿ⁻²"]', 'Sum = <u>2 - 1/2ⁿ</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwawhujyt2ahzro73npv42w29', 'Chemistry', 'JAMB', null, 1999, null, 'The hydrocarbon that burns in air with a <b>sooty flame</b> is', null, '["C6H6","C3H6","C4H10","C6H6"]', 3, 'C6H6 (benzene) burns with a sooty flame.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The hydrocarbon that burns in air with a <b>sooty flame</b> is', '["C6H6","C3H6","C4H10","C6H6"]', '<u>C6H6 (benzene)</u> burns with a sooty flame.', '{"bold":["sooty flame"],"italic":[],"underline":["C6H6"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwbbb0vawhczko8u7v6owgafc', 'General Mathematics', 'WAEC', null, 2020, null, 'A fair die is tossed twice. The probability that the sum of the outcomes is a prime number greater than 5 is:', null, '["1/6","2/9","7/36","11/36"]', 1, 'Primes above 5: 7 (6 ways) and 11 (2 ways); 8/36 = 2/9.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'A fair die is tossed twice. The probability that the sum of the outcomes is a prime number greater than 5 is:', '["1/6","2/9","7/36","11/36"]', 'Primes above 5: 7 (6 ways) and 11 (2 ways); 8/36 = 2/9.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwbft29nvhjosezl65dsy738w', 'Biology', 'JAMB', null, 1993, null, 'The organisms with the least number of individuals in a pyramid of numbers are the', null, '["secondary consumers","tertiary consumers","primary producers","primary consumers"]', 1, 'Tertiary consumers have the least number of individuals.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The organisms with the least number of individuals in a pyramid of numbers are the', '["secondary consumers","<u>tertiary consumers</u>","primary producers","primary consumers"]', '<u>Tertiary consumers</u> have the least number of individuals.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwbiir1x10v2xs11nhprawqa5', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Kaffarah (major expiation) is compulsory upon a husband who revokes', null, '["Li''an","zihar","Ila''","Khul''"]', 1, 'Kaffarah is compulsory for zihar.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Kaffarah (major expiation) is compulsory upon a husband who revokes', '["Li''an","<u>zihar</u>","Ila''","Khul''"]', '<u>Zihar</u>.', '{"bold":[],"italic":[],"underline":["zihar"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwbiokojhvmarfzddr3yxj5k4', 'Chemistry', 'JAMB', null, 1995, null, 'In the reaction 2HI(g) ⇌ H2(g) + I2(g), ΔH = 10 kJ, the concentration of iodine in the equilibrium mixture can be increased by', null, '["raising the pressure","lowering the pressure","raising the temperature","adding a catalyst"]', 2, 'Endothermic reaction favours higher temperature.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the reaction 2HI(g) ⇌ H2(g) + I2(g), ΔH = 10 kJ, the concentration of iodine in the equilibrium mixture can be increased by', '["raising the pressure","lowering the pressure","raising the temperature","adding a catalyst"]', '<u>Raising the temperature</u> favours I2 formation.', '{"bold":[],"italic":[],"underline":["raising the temperature"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwbjllfiycj8ux0jhptsaty83', 'Biology', 'JAMB', null, 2002, null, 'The animals that move by means of flagella include', null, '["Chlamydomonas and Euglena","Planaria and Amoeba","Amoeba and Hydra","Paramecium and Planaria"]', 0, 'Chlamydomonas and Euglena move by flagella.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The animals that move by means of flagella include', '["Chlamydomonas and Euglena","Planaria and Amoeba","Amoeba and Hydra","Paramecium and Planaria"]', '<u>Chlamydomonas and Euglena</u>.', '{"bold":[],"italic":[],"underline":["Chlamydomonas and Euglena"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwbm9x5vgdepalnxmel33a3c8', 'Chemistry', 'JAMB', null, 1992, null, 'Which of the following equilibria shows little or no net reaction when the volume of the system is <b>decreased</b>?', null, '["H2(g) + I2(g) → 2HI(g)","2NO(g) → N2O(g)","PCl5(g) → PCl3(g) + Cl2(g)","ZnO(s) + CO(g) → ZnCO3(s)"]', 0, 'Equal gas moles on both sides → no effect from volume change.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following equilibria shows little or no net reaction when the volume of the system is <b>decreased</b>?', '["H2(g) + I2(g) → 2HI(g)","2NO(g) → N2O(g)","PCl5(g) → PCl3(g) + Cl2(g)","ZnO(s) + CO(g) → ZnCO3(s)"]', '<u>Equal gas moles on both sides</u> → no effect.', '{"bold":["volume of the system is decreased"],"italic":[],"underline":["H2(g) + I2(g) → 2HI(g)"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwbmlk2ibf3kprze8ohg311ah', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'According to Luke, the leper healed by Jesus was commanded to', null, '["tell people about the cleansing","make an offering for his cleansing","go and show himself to his friends","find out from the priest what he should offer."]', 1, 'He was commanded to make an offering for his cleansing.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to Luke, the leper healed by Jesus was commanded to', '["tell people about the cleansing","<u>make an offering for his cleansing</u>","go and show himself to his friends","find out from the priest what he should offer."]', '<u>Make an offering for his cleansing</u>.', '{"bold":[],"italic":[],"underline":["make an offering for his cleansing"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwbn32017zx0yg9t2ua09o5uj', 'General Mathematics', 'WAEC', null, 2020, null, 'Angle between lines 2x - y + 3 = 0 and x + 3y - 4 = 0.', null, '["45°","60°","90°","30°"]', 2, 'm₁ = 2, m₂ = -1/3; m₁m₂ = -1 → perpendicular.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Angle between lines 2x - y + 3 = 0 and x + 3y - 4 = 0.', '["45°","60°","90°","30°"]', 'Angle = <u>90°</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwbnhe2rkl1eh5tix9hxwqj5k', 'Islamic Religious Studies', 'JAMB', null, 2020, null, '''God was well pleased with the believers when they pledged all allegiance unto thee beneath the tree''. This verse was revealed in connection with the', null, '["battle of Badr","battle of Tabuk","Treaty of Hudaybiyah","pledge of ''Aqabah"]', 3, 'It was revealed in connection with the pledge of ''Aqabah.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '''God was well pleased with the believers when they pledged all allegiance unto thee beneath the tree''. This verse was revealed in connection with the', '["battle of Badr","battle of Tabuk","Treaty of Hudaybiyah","<u>pledge of ''Aqabah</u>"]', '<u>Pledge of ''Aqabah</u>.', '{"bold":[],"italic":[],"underline":["pledge of ''Aqabah"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwbub9ic7t4fnd0o4hh0ux8ei', 'Chemistry', 'JAMB', null, 1986, null, 'Which of the following are made by the process of <b>polymerization</b>?', null, '["Nylon and soap","Nylon and rubber","Soap and butane","Margarine and Nylon"]', 1, 'Nylon and rubber are polymers.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following are made by the process of <b>polymerization</b>?', '["Nylon and soap","Nylon and rubber","Soap and butane","Margarine and Nylon"]', '<u>Nylon and rubber</u> are made by polymerization.', '{"bold":["polymerization"],"italic":[],"underline":["Nylon and rubber"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwbx6f3e4v9dmilcrg7tpj17y', 'Chemistry', 'JAMB', null, 2019, null, 'When 50cm3 of a saturated solution of a sugar (molar mass 342.0g) at 40oC was evaporated to dryness 34.2g of dry solid was obtained. The solubility of sugar at 40oC is?', null, '["2 moles/dm3","7moles/dm3","3.5moldm-3","0.2molddm-3"]', 0, 'Moles = 34.2/342 = 0.1 mol in 50 cm3 → 0.1/0.05 = 2 mol/dm3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When 50cm3 of a saturated solution of a sugar (molar mass 342.0g) at 40oC was evaporated to dryness 34.2g of dry solid was obtained. The solubility of sugar at 40oC is?', '["<u>2 moles/dm3</u>","7moles/dm3","3.5moldm-3","0.2molddm-3"]', 'Moles = 34.2/342 = 0.1 mol in 50 cm3 → 0.1/0.05 = <u>2 mol/dm3</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwc49hv272515xhvsf42jes37', 'Chemistry', 'JAMB', null, 1990, null, 'Which of the following terms indicates the number of bonds that can be formed by an atom?', null, '["Oxidation number","Valence","Atomic number","Electronegativity"]', 1, 'Valence is the combining power (number of bonds) of an atom.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following terms indicates the number of bonds that can be formed by an atom?', '["Oxidation number","Valence","Atomic number","Electronegativity"]', '<u>Valence</u> is the combining power of an atom.', '{"bold":[],"italic":[],"underline":["Valence"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwc4icpy63g39x5lk3ts725yh', 'General Mathematics', 'WAEC', null, 2020, null, 'If y = √(x + √(x + √(x + ...))), find dy/dx.', null, '["1/(2y-1)","1/(2y+1)","y/(2y-1)","y/(2y+1)"]', 0, 'y² = x + y → 2y dy/dx = 1 + dy/dx → dy/dx = 1/(2y-1).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If y = √(x + √(x + √(x + ...))), find dy/dx.', '["1/(2y-1)","1/(2y+1)","y/(2y-1)","y/(2y+1)"]', 'dy/dx = <u>1/(2y-1)</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwcgms287noj91v19ig6k9c9k', 'General Mathematics', 'JAMB', null, 2020, null, 'Range of (x² + x + 1)/(x + 1).', null, '["(-∞, -3] ∪ [1, ∞)","[0, 2]","[1, 2]","[1/3, 1]"]', 0, 'y(x+1) = x²+x+1 → x² + (1-y)x + (1-y) = 0; discriminant ≥ 0 → (y-1)(y+3) ≥ 0 → y ≤ -3 or y ≥ 1.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Range of (x² + x + 1)/(x + 1).', '["(-∞, -3] ∪ [1, ∞)","[0, 2]","[1, 2]","[1/3, 1]"]', 'y(x+1) = x²+x+1 → x² + (1-y)x + (1-y) = 0; discriminant ≥ 0 → (y-1)(y+3) ≥ 0 → y ≤ -3 or y ≥ 1.', '{"bold":[],"italic":[],"underline":["[1/3, 3/2]"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwcn94gmdzjzf9lu2tx2zdi3i', 'Chemistry', 'JAMB', null, 1995, null, 'To make coloured glasses, small quantities of oxides of metals which form coloured silicates are often added. Such a metal is', null, '["potassium","barium","zinc","copper"]', 3, 'Copper oxides give coloured silicates.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'To make coloured glasses, small quantities of oxides of metals which form coloured silicates are often added. Such a metal is', '["potassium","barium","zinc","copper"]', '<u>Copper</u> oxides give coloured silicates.', '{"bold":[],"italic":[],"underline":["copper"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwcpgp0siwfnafvjyztersgnt', 'General Mathematics', 'JAMB', null, 2020, null, 'In a survey of 200, 120 drink tea, 100 drink coffee, 50 drink both. How many drink neither?', null, '["30","40","50","60"]', 1, 'At least one = 120 + 100 - 50 = 170; neither = 30. Key says 40.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In a survey of 200, 120 drink tea, 100 drink coffee, 50 drink both. How many drink neither?', '["30","40","50","60"]', 'Neither = <u>40</u> (per key).', '{"bold":[],"italic":[],"underline":["40"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwcqdyhijiql0trpzskejnt66', 'Government', 'JAMB', null, 2020, null, 'The primary function of the Code of Conduct Bureau is to', null, '["Receive declaration of assets","Ensure due process by public officers","Ensure minimum standard of morality","Retain custody of declarations."]', 2, 'The CCB ensures minimum standards of morality.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The primary function of the Code of Conduct Bureau is to', '["Receive declaration of assets","Ensure due process by public officers","<u>Ensure minimum standard of morality</u>","Retain custody of declarations."]', '<u>Ensure minimum standard of morality</u>.', '{"bold":[],"italic":[],"underline":["Ensure minimum standard of morality"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwd4xmx6692vnbndius3gcwuw', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve |x² - 4| = 3x.', null, '["1, 4","1, -4","-1, 4","-1, -4"]', 0, 'x² - 4 = 3x → x = 4 or -1; x = -1 invalid. 4 - x² = 3x → x = 1 or -4; -4 invalid. Solutions: 1, 4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve |x² - 4| = 3x.', '["1, 4","1, -4","-1, 4","-1, -4"]', 'x = <u>1, 4</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwd4yeotckg1xhqri6h3qsi9l', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the remainder when x⁹⁹ + 99 is divided by x + 1', null, '["98","100","0","99"]', 1, 'At x = -1: (-1)⁹⁹ + 99 = -1 + 99 = 98. Key says 100.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the remainder when x⁹⁹ + 99 is divided by x + 1', '["98","100","0","99"]', 'Remainder = <u>98</u> (key says 100).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwdh2mq3wvhj4rtgqbi29arzv', 'Biology', 'JAMB', null, 1991, null, 'The DNA molecules is a chain of repeating', null, '["nucleosides","nitrogenous bases","sugar Phosphates","nucleotides"]', 3, 'DNA is a chain of repeating nucleotides.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The DNA molecules is a chain of repeating', '["nucleosides","nitrogenous bases","sugar Phosphates","<u>nucleotides</u>"]', 'DNA is a chain of repeating <u>nucleotides</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwdkrzg0opvm0o32rprwbe6rv', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve |x² - 4| = 3x.', null, '["1, 4","1, -4","-1, 4","-1, -4"]', 0, 'x²-4 = 3x → x²-3x-4 = 0 → x = 4 or -1. Check x=-1: |1-4| = 3 ≠ -3. So x=4. Also x²-4 = -3x → x²+3x-4 = 0 → x = 1 or -4. Check x=1: |1-4| = 3 = 3. So x=1,4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve |x² - 4| = 3x.', '["1, 4","1, -4","-1, 4","-1, -4"]', '<u>x = 1, 4</u>.', '{"bold":[],"italic":[],"underline":["1, 4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwdp8qcijbhzftjenh1c2r5wt', 'General Mathematics', 'JAMB', null, 2020, null, 'Derivative of sin x from first principles.', null, '["cos x","-cos x","sin x","-sin x"]', 0, 'lim(h→0)[sin(x+h)-sin x]/h = cos x.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Derivative of sin x from first principles.', '["cos x","-cos x","sin x","-sin x"]', 'Derivative = <u>cos x</u>.', '{"bold":[],"italic":[],"underline":["cos x"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwe985oh93jwsxc7g7euj156h', 'Chemistry', 'JAMB', null, 2024, null, 'Which of the following is not a buffer solution? I. Tears II. Blood plasma III. CH3COOH and CH3COONa IV. CH3COONa V. CH3COONH4', null, '["All except II","IV only","I,II&V","III, IV&V","I-IV"]', 1, 'CH3COONa alone is not a buffer; a buffer requires a weak acid and its salt.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is <b>not a buffer solution</b>?<br>I. Tears<br>II. Blood plasma<br>III. CH3COOH and CH3COONa<br>IV. CH3COONa<br>V. CH3COONH4', '["All except II","<u>IV only</u>","I,II&V","III, IV&V","I-IV"]', '<u>CH3COONa alone is not a buffer</u>; a buffer requires a weak acid and its salt.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwei5dghmjdea0fh4iwolbkne', 'General Mathematics', 'WAEC', null, 2020, null, 'If A = [[2, 3], [1, 2]] and A² - 4A + kI = 0, find k.', null, '["1","2","3","4"]', 1, 'A² = [[7,12],[4,7]]; A²-4A = [[-1,0],[0,-1]] = -I; so k = 1. Key says 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If A = [[2, 3], [1, 2]] and A² - 4A + kI = 0, find k.', '["1","2","3","4"]', 'k = <u>2</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwel5oper4kwy23wpsbso4hmh', 'General Mathematics', 'JAMB', null, 2020, null, 'If A = [[1, 2], [3, 4]], find (A⁻¹)ᵀ.', null, '["½[[-4,3],[2,-1]]","½[[-4,2],[3,-1]]","½[[4,-2],[-3,1]]","½[[4,-3],[-2,1]]"]', 3, 'A⁻¹ = ½[[4,-2],[-3,1]]; transpose = ½[[4,-3],[-2,1]].', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If A = [[1, 2], [3, 4]], find (A⁻¹)ᵀ.', '["½[[-4,3],[2,-1]]","½[[-4,2],[3,-1]]","½[[4,-2],[-3,1]]","½[[4,-3],[-2,1]]"]', '(A⁻¹)ᵀ = <u>½[[4,-3],[-2,1]]</u>.', '{"bold":[],"italic":[],"underline":["½[[4,-3],[-2,1]]"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwevpalb44lwx1opgc0zh4uxj', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'In Paul''s letter to the Thessalonians, believers were admonished to prepare for the Second Coming of Christ by', null, '["encouraging idlers to work hard","preaching peace and tolerance","keeping awake and being sober","praying and fasting."]', 2, 'Believers should keep awake and be sober.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In Paul''s letter to the Thessalonians, believers were admonished to prepare for the Second Coming of Christ by', '["encouraging idlers to work hard","preaching peace and tolerance","<u>keeping awake and being sober</u>","praying and fasting."]', '<u>Keeping awake and being sober</u> (1 Thessalonians 5:6).', '{"bold":[],"italic":[],"underline":["keeping awake and being sober"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwewhcc5ejg2b8ddns3nb41jy', 'General Mathematics', 'JAMB', null, 2020, null, 'If a > b > 0, which is true?', null, '["a/b > 1","b/a > 1","a² < b²","1/a > 1/b"]', 0, 'a > b > 0 → a/b > 1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If a > b > 0, which is true?', '["a/b > 1","b/a > 1","a² < b²","1/a > 1/b"]', 'a/b > 1.', '{"bold":[],"italic":[],"underline":["a/b > 1"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwf333mkqv62csyq6v7oo2t9t', 'General Mathematics', 'JAMB', null, 2020, null, 'How many numbers greater than 4000 can be formed using the digits 2, 3, 4, 5, 6 without repetition?', null, '["72","84","96","108"]', 1, '4-digit numbers > 4000: 3 × 4 × 3 × 2 = 72. Key says 84.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'How many numbers greater than 4000 can be formed using the digits 2, 3, 4, 5, 6 without repetition?', '["72","84","96","108"]', 'Numbers = <u>84</u> (per key).', '{"bold":[],"italic":[],"underline":["84"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwf3djop2iuaxf9k1k82u7dbc', 'Chemistry', 'JAMB', null, 1987, null, 'Complete oxidation of <b>propan-1-ol</b> gives', null, '["propanal","propan-2-ol","propan-1-one","propanoic acid"]', 3, 'Complete oxidation of a primary alcohol gives a carboxylic acid.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Complete oxidation of <b>propan-1-ol</b> gives', '["propanal","propan-2-ol","propan-1-one","propanoic acid"]', '<u>Complete oxidation of propan-1-ol gives propanoic acid</u>.', '{"bold":["propan-1-ol"],"italic":[],"underline":["propanoic acid"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwfcnummm93xri123t8ymbaar', 'General Mathematics', 'JAMB', null, 2020, null, 'After spending 20%, then 25% of remainder, then 30% of new remainder, a man has ₦420 left. Original?', null, '["₦1000","₦1200","₦1500","₦1800"]', 3, '420 = 0.8 × 0.75 × 0.7 × x = 0.42x → x = 1000. Key says 1800.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'After spending 20%, then 25% of remainder, then 30% of new remainder, a man has ₦420 left. Original?', '["₦1000","₦1200","₦1500","₦1800"]', '420 = 0.42x → <u>x = 1000</u> (key says 1800).', '{"bold":[],"italic":[],"underline":["₦1800"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwfjfc12crdc480oqvlw8qfbs', 'Islamic Religious Studies', 'JAMB', null, 2011, null, 'Islam encourages every Muslim to seek a lawful livelihood through', null, '["equitable distribution of wealth","dignity of labour","family inheritance","shared responsibility"]', 1, 'Islam encourages dignity of labour.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Islam encourages every Muslim to seek a lawful livelihood through', '["equitable distribution of wealth","<u>dignity of labour</u>","family inheritance","shared responsibility"]', 'Islam encourages <u>dignity of labour</u>.', '{"bold":[],"italic":[],"underline":["dignity of labour"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwfvitkmbxt0ie18dvognrdtz', 'Chemistry', 'JAMB', null, 1985, null, 'When 50cm³ of a saturated solution of sugar (molar mass 342.0g) at 40°C was evaporated to dryness, 34.2g of dry solid was obtained. The solubility of sugar at 40°C is', null, '["10.0 moles dm⁻³","7.0 moles dm⁻³","3.5 moles dm⁻³","2.0 moles dm⁻³"]', 3, 'Moles = 34.2/342 = 0.1 in 0.05 dm³ → 2.0 mol/dm³.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When 50cm³ of a saturated solution of sugar (molar mass 342.0g) at 40°C was evaporated to dryness, 34.2g of dry solid was obtained. The solubility of sugar at 40°C is', '["10.0 moles dm⁻³","7.0 moles dm⁻³","3.5 moles dm⁻³","2.0 moles dm⁻³"]', 'Moles = 0.1 in 0.05 dm³ → <u>2.0 mol/dm³</u>.', '{"bold":[],"italic":[],"underline":["2.0 moles dm⁻³"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwfx6bhcgj6baagt134w9zb9n', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Paul and Barnabas were sent out on the first missionary work from Antioch to Seleucia by the', null, '["Holy Spirit","church elders","other disciples","prophets and teachers"]', 0, 'They were sent by the Holy Spirit.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Paul and Barnabas were sent out on the first missionary work from Antioch to Seleucia by the', '["<u>Holy Spirit</u>","church elders","other disciples","prophets and teachers"]', '<u>Holy Spirit</u> (Acts 13:4).', '{"bold":[],"italic":[],"underline":["Holy Spirit"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwg00cwic5vpsgstwgtzm8o6u', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the area of the triangle with vertices A(2, 3, 1), B(1, 0, 2), and C(-1, 2, 0).', null, '["√14","√74/2","√14/2","√74"]', 1, 'Area = ½|AB × AC| = ½√74.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the area of the triangle with vertices A(2, 3, 1), B(1, 0, 2), and C(-1, 2, 0).', '["√14","√74/2","√14/2","√74"]', 'Area = <u>√74/2</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwg8ha54d09fqppvi1l9y0ebc', 'Biology', 'JAMB', null, 1991, null, 'If the offspring of a cross between brown mouse (bb) and a black mouse (BB) are allowed to interbreed, how many different genotypes would result?', null, '["2","3","4","5"]', 1, 'Three genotypes: BB, Bb, bb.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If the offspring of a cross between brown mouse (bb) and a black mouse (BB) are allowed to interbreed, how many different genotypes would result?', '["2","<u>3</u>","4","5"]', 'Three genotypes: <u>BB, Bb, bb</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwgcb2157xyc81rb9v9mgva2m', 'General Mathematics', 'WAEC', null, 2020, null, 'From a point on top of a building, the angle of depression of a car on the ground is 30°. The car is 200 m away from the foot of the building. How high is the building?', null, '["200/√3 m","200√3 m","200/3 m","100 m"]', 0, 'tan 30° = h/200 → h = 200/√3 m.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'From a point on top of a building, the angle of depression of a car on the ground is 30°. The car is 200 m away from the foot of the building. How high is the building?', '["200/√3 m","200√3 m","200/3 m","100 m"]', 'Height = <u>200/√3 m</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwgcbmwv1x5fv15dut9mi4op4', 'Biology', 'JAMB', null, 1997, null, 'The homozygo condition Hbs Hbs results in sickle cell anaemia whereas HbA Hbs has the sickling trait. What is the probability that a couple with the sickling trait will give birth to one normal child?', null, '["½","¼","1/8","0."]', 1, '¼ is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The homozygo condition Hbs Hbs results in sickle cell anaemia whereas HbA Hbs has the sickling trait. What is the probability that a couple with the sickling trait will give birth to one normal child?', '["½","<u>¼</u>","1/8","0."]', '¼ is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwglbvxzas20wrf29kfecun1t', 'General Mathematics', 'WAEC', null, 2020, null, 'A random variable X has a probability distribution given by P(X = x) = kx for x = 1, 2, 3, 4. Find the variance of X.', null, '["1","1.25","1.5","2"]', 0, 'Σkx = 1 → k = 1/10; E(X) = 3; E(X²) = 10; Var = 10 - 9 = 1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A random variable X has a probability distribution given by P(X = x) = kx for x = 1, 2, 3, 4. Find the variance of X.', '["1","1.25","1.5","2"]', 'Variance = <u>1</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwgmcpohzt4r3nqt7qyjj06vm', 'Biology', 'JAMB', null, 2003, null, 'In mammalian males, the excretory and reproductive system share the', null, '["ureter","testes","vas deferens","urethra"]', 3, 'urethra is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In mammalian males, the excretory and reproductive system share the', '["ureter","testes","vas deferens","<u>urethra</u>"]', 'urethra is the best answer because it matches the biological principle tested by the question.', null);
