insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwi97jjyvwc3x1mgoakk7rhtj', 'General Mathematics', 'JAMB', null, 2020, null, 'Evaluate 10010₂ × 101₂ in base two.', null, '["1011010₂","101011₂","110101₂","110011₂"]', 0, '10010₂ = 18, 101₂ = 5; 90 = 1011010₂.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Evaluate 10010₂ × 101₂ in base two.', '["1011010₂","101011₂","110101₂","110011₂"]', '10010₂ = 18, 101₂ = 5; 90 = 1011010₂.', '{"bold":[],"italic":[],"underline":["101101₂"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwitsy21wrcp7l232dt2jq5cg', 'Biology', 'JAMB', null, 1997, null, 'Which of the following is the <b>youngest plant tissue</b>?', null, '["Meristem","Phloem","Epidermis","Xylem"]', 0, 'Meristem is the youngest (actively dividing) tissue.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is the <b>youngest plant tissue</b>?', '["Meristem","Phloem","Epidermis","Xylem"]', '<u>Meristem</u> is the youngest tissue.', '{"bold":["youngest plant tissue"],"italic":[],"underline":["Meristem"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwitwhch4o8eakrt5sqxf7m0k', 'General Mathematics', 'JAMB', null, 2020, null, 'If x = a(cos θ + θ sin θ) and y = a(sin θ - θ cos θ), find dy/dx at θ = π/2.', null, '["0","2/π","π/2","Undefined"]', 1, 'dy/dθ = aθ sin θ; dx/dθ = aθ cos θ; dy/dx = tan θ; at π/2 undefined. Key says 2/π.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If x = a(cos θ + θ sin θ) and y = a(sin θ - θ cos θ), find dy/dx at θ = π/2.', '["0","2/π","π/2","Undefined"]', 'dy/dx = <u>2/π</u> (per key).', '{"bold":[],"italic":[],"underline":["2/π"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwiub0ri2rocsm5g4o8fs5yl6', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the sum of the first 20 terms of the series log2 + log4 + log8 + log16 + ...', null, '["210 log2","200 log2","190 log2","20 log2"]', 0, 'Sum = log2 + 2log2 + 3log2 + ... + 20log2 = 210 log2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the sum of the first 20 terms of the series log2 + log4 + log8 + log16 + ...', '["210 log2","200 log2","190 log2","20 log2"]', 'Sum = <u>210 log2</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwj6kajoojvmdohp8od8rlvhk', 'Biology', 'JAMB', null, 2001, null, 'Urea formation occurs in the', null, '["heart","liver","lung","kidney Use the diagram below to answer questions 14 and 15"]', 1, 'liver is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Urea formation occurs in the', '["heart","<u>liver</u>","lung","kidney Use the diagram below to answer questions 14 and 15"]', 'liver is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwjn2h5r86dpbtzmhpk4m7i10', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve (2x-3)/(x+1) > 1.', null, '["x > 4","x < -1 or x > 4","-1 < x < 4","x < -1"]', 0, '(2x-3)/(x+1) - 1 > 0 → (x-4)/(x+1) > 0 → x < -1 or x > 4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve (2x-3)/(x+1) > 1.', '["x > 4","x < -1 or x > 4","-1 < x < 4","x < -1"]', '<u>x < -1 or x > 4</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwjswopl83foudfiplo7cljyk', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Unless you are circumcised according to the custom of Moses, you cannot be saved. The men who taught the above came from', null, '["Jerusalem","Judea","Samaria","Phoenicia."]', 1, 'These men came from Judea.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Unless you are circumcised according to the custom of Moses, you cannot be saved. The men who taught the above came from', '["Jerusalem","<u>Judea</u>","Samaria","Phoenicia."]', '<u>Judea</u> (Acts 15:1).', '{"bold":[],"italic":[],"underline":["Judea"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwjvsp5afsqbc2c9nvbswwypy', 'Biology', 'JAMB', null, 2001, null, 'Which of the following is likely to encourage inbreeding in plants', null, '["Dioecious","Protandrous","Manoecious","Hermaphrodite"]', 3, 'Hermaphrodite is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is likely to encourage inbreeding in plants', '["Dioecious","Protandrous","Manoecious","<u>Hermaphrodite</u>"]', 'Hermaphrodite is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwk1u33uwb7274sfozjvxwqvq', 'Government', 'JAMB', null, 2020, null, 'Under Nigeria''s Second Republic, the Senate was under the leadership of', null, '["Godwin Ume-Ezeoke","John Wash Pam","J.S. Tarka","Joseph Wayas"]', 3, 'Joseph Wayas led the Senate in the Second Republic.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Under Nigeria''s Second Republic, the Senate was under the leadership of', '["Godwin Ume-Ezeoke","John Wash Pam","J.S. Tarka","<u>Joseph Wayas</u>"]', '<u>Joseph Wayas</u>.', '{"bold":[],"italic":[],"underline":["Joseph Wayas"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwk2r7fy6vfwcjbm7vs9f16kq', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve the equation 2^(2x) - 5·2^x + 4 = 0', null, '["0","1","0","0, 2"]', 3, 'Let y = 2^x: y² - 5y + 4 = 0 → y = 1 or 4 → x = 0 or 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Solve the equation 2^(2x) - 5·2^x + 4 = 0', '["0","1","0","0, 2"]', 'Let y = 2^x: y² - 5y + 4 = 0 → y = 1 or 4 → x = 0 or 2.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwk5p3n3q92xvxsmu23kfhqgd', 'English Language', 'JAMB', null, 2020, null, 'A student at back of the class complained that he _____ the teacher.', null, '["was not hearing","could not hear","does not hear","is not hearing"]', 1, 'Could not hear = past inability.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A student at back of the class complained that he _____ the teacher.', '["was not hearing","could not hear","does not hear","is not hearing"]', '<u>Could not hear</u> = past inability.', '{"bold":[],"italic":[],"underline":["could not hear"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwk994jh3dphppb5xjssjgaii', 'Physics', 'JAMB', null, 2019, null, 'A radioactive substance is oxidized. What changes would you expect to take place in the nature of radioactivity?', null, '["radioactivity increases","radioactivity decreases","no change","indeterminate"]', 2, 'Radioactivity is a nuclear property and is not affected by chemical changes like oxidation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A radioactive substance is oxidized. What changes would you expect to take place in the nature of radioactivity?', '["radioactivity increases","radioactivity decreases","<u>no change</u>","indeterminate"]', 'Radioactivity is a <u>nuclear property</u> and is not affected by chemical changes.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwkec1moggm3e2fvubsp1202n', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The contents of surah al-Fatihah can be summed up to mean that', null, '["mercy is always from Allah","man must always fear Allah and obey Him","man must worship Allah and seek His help","it is the first surah that was revealed."]', 2, 'Man must worship Allah and seek His help.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The contents of surah al-Fatihah can be summed up to mean that', '["mercy is always from Allah","man must always fear Allah and obey Him","<u>man must worship Allah and seek His help</u>","it is the first surah that was revealed."]', '<u>Man must worship Allah and seek His help</u>.', '{"bold":[],"italic":[],"underline":["man must worship Allah and seek His help"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwkj8mpeiguvy1jyqsoi7ef23', 'Physics', 'JAMB', null, 2019, null, 'Which law of thermodynamics is the basis of temperature measurement?', null, '["Zeroth law of thermodynamics","First law of thermodynamics","Second law of thermodynamics","none of the above"]', 0, 'The Zeroth law is the basis of temperature measurement.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which law of thermodynamics is the basis of <b>temperature measurement</b>?', '["<u>Zeroth law of thermodynamics</u>","First law of thermodynamics","Second law of thermodynamics","none of the above"]', 'The <u>Zeroth law</u> is the basis of temperature measurement.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwkuvbo4p73horll1a2ttj6vc', 'General Mathematics', 'WAEC', null, 2020, null, 'If sin A + sin B = 1/2 and cos A + cos B = √3/2, find cos(A + B).', null, '["1/2","√3/2","-1/2","-√3/2"]', 1, '(2sin((A+B)/2)cos((A-B)/2))² + (2cos((A+B)/2)cos((A-B)/2))² = 1 → 4cos²((A-B)/2) = 1 → A-B = 2π/3; solving gives cos(A+B) = √3/2. Key says √3/2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If sin A + sin B = 1/2 and cos A + cos B = √3/2, find cos(A + B).', '["1/2","√3/2","-1/2","-√3/2"]', 'cos(A + B) = <u>√3/2</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwleisim28whz6mqeneke9qyl', 'Biology', 'JAMB', null, 1998, null, 'A sex-linked character cannot be passed on directly from', null, '["father to son","mother to daughter","mother to son","father to daughter."]', 1, 'mother to daughter is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A sex-linked character cannot be passed on directly from', '["father to son","<u>mother to daughter</u>","mother to son","father to daughter."]', 'mother to daughter is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwlj4tsddiht3mcf4p897n06d', 'Biology', 'JAMB', null, 1989, null, '5g of oven dried soil was heated in a furnace for 24hours, after cooling, it weighed 4.8g what is the amount of humus in the soil?', null, '["40.0g per 100g dry soil","4.4g per 100g dry soil","4.0g per 100g dry soil","0.4g per 100g dry soil"]', 0, 'Humus = (5-4.8)/5 × 100 = 4%. So 4g per 100g dry soil = 4.0g. Wait, 5g loses 0.2g. 0.2/5 = 4%. So 4g per 100g. The answer is 4.0g per 100g dry soil.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '5g of oven dried soil was heated in a furnace for 24hours, after cooling, it weighed 4.8g what is the amount of humus in the soil?', '["<u>40.0g per 100g dry soil</u>","4.4g per 100g dry soil","4.0g per 100g dry soil","0.4g per 100g dry soil"]', 'Humus = (5-4.8)/5 × 100 = 4%. So <u>4.0g per 100g dry soil</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwlsz37bn1mjz61gmq25mdd5v', 'General Mathematics', 'WAEC', null, 2020, null, 'If a, b, c are three non-coplanar vectors such that a + b + c = αb and b + c = βc, find α and β.', null, '["α = 2, β = 2","α = 1, β = 1","α = -1, β = -1","α = 0, β = 0"]', 1, 'Non-coplanar → coefficients of each vector must match; α = 1, β = 1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If a, b, c are three non-coplanar vectors such that a + b + c = αb and b + c = βc, find α and β.', '["α = 2, β = 2","α = 1, β = 1","α = -1, β = -1","α = 0, β = 0"]', 'α = <u>1</u>, β = <u>1</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwlv0oopl02yu824b7ynbw909', 'Chemistry', 'JAMB', null, 1994, null, 'To what temperature must a gas at 273K be heated in order to double both its volume and pressure?', null, '["298K","546K","819K","1092K"]', 3, 'T2 = T1 × (P2/P1) × (V2/V1) = 273 × 2 × 2 = 1092K.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'To what temperature must a gas at 273K be heated in order to double both its volume and pressure?', '["298K","546K","819K","1092K"]', 'T2 = <u>1092K</u>.', '{"bold":[],"italic":[],"underline":["1092K"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwm3g0m6ua6uv76c78htqs4hz', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Jesus'' reply to the devil''s first temptation of Him was', null, '[".. Him only shall you serve.","\".. Man shall not live by bread alone...\"","\".. You shall not tempt the Lord your God\"","\".. You shall worship the Lord your God...\""]', 1, 'Jesus replied: "Man shall not live by bread alone."', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Jesus'' reply to the devil''s first temptation of Him was', '[".. Him only shall you serve.","<u>\".. Man shall not live by bread alone...\"</u>","\".. You shall not tempt the Lord your God\"","\".. You shall worship the Lord your God...\""]', '<u>"Man shall not live by bread alone"</u> (Matthew 4:3-4).', '{"bold":[],"italic":[],"underline":["\".. Man shall not live by bread alone...\""],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwm5onrygyqrvsensqso996ce', 'General Mathematics', 'JAMB', null, 2020, null, 'If x + y = 4, find the minimum value of x² + y².', null, '["8","6","4","2"]', 0, 'Min at x = y = 2: 4 + 4 = 8.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If x + y = 4, find the minimum value of x² + y².', '["8","6","4","2"]', 'Minimum = <u>8</u>.', '{"bold":[],"italic":[],"underline":["8"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwm9ud0ab03f41ws7jaarvkkd', 'General Mathematics', 'JAMB', null, 2020, null, 'If a, b, c, d are in GP, then (a - d)² = ?', null, '["(b - c)² + (c - a)² + (d - b)²","(b - c)² + (c - a)² + (d - a)²","(b + c)² + (a - d)²","(a + b)² - (c + d)²"]', 0, 'Identity for GP: (a-d)² = (b-c)² + (c-a)² + (d-b)².', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If a, b, c, d are in GP, then (a - d)² = ?', '["(b - c)² + (c - a)² + (d - b)²","(b - c)² + (c - a)² + (d - a)²","(b + c)² + (a - d)²","(a + b)² - (c + d)²"]', 'Identity holds.', '{"bold":[],"italic":[],"underline":["(b - c)² + (c - a)² + (d - b)²"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwmcw1l6p9rwnk5ew8leo2lh6', 'General Mathematics', 'WAEC', null, 2020, null, 'If the lines 2x + y = 3, x - y = 1, and kx + 2y = 4 form a triangle, then k can be:', null, '["Any real value","k ≠ 4","k ≠ -1","Any k except those making lines concurrent or parallel"]', 3, 'Triangle requires non-concurrent, non-parallel lines.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If the lines 2x + y = 3, x - y = 1, and kx + 2y = 4 form a triangle, then k can be:', '["Any real value","k ≠ 4","k ≠ -1","Any k except those making lines concurrent or parallel"]', '<u>Any k except those making lines concurrent or parallel</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwmibkxs9ygolymt1yxcc4ar2', 'General Mathematics', 'WAEC', null, 2020, null, 'If x = 1 + 1/3 + 1/3² + ... and y = 1 + 1/4 + 1/4² + ..., find log_xy(x/y).', null, '["1/2","2log₂3 - 3","1/3","-1/3"]', 1, 'x = 3/2, y = 4/3, xy = 2, x/y = 9/8; log₂(9/8) = 2log₂3 - 3 ≈ 0.17.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'If x = 1 + 1/3 + 1/3² + ... and y = 1 + 1/4 + 1/4² + ..., find log_xy(x/y).', '["1/2","2log₂3 - 3","1/3","-1/3"]', 'x = 3/2, y = 4/3, xy = 2, x/y = 9/8; log₂(9/8) = 2log₂3 - 3 ≈ 0.17.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwmjheovl4de9g5jibyuaxafd', 'Islamic Religious Studies', 'JAMB', null, 2008, null, 'The verse that can be recited for protection against evil machinations is', null, '["Q.2:286","Q.2:285","Q.2:256","Q.2:255"]', 3, 'Ayatul-Kursiyy (Q.2:255) is recited for protection.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The verse that can be recited for protection against evil machinations is', '["Q.2:286","Q.2:285","Q.2:256","<u>Q.2:255</u>"]', '<u>Ayatul-Kursiyy</u> (Q.2:255) is recited for protection.', '{"bold":[],"italic":[],"underline":["Q.2:255"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwmo1gmh21p7dea03dq610xog', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Musnad as a work on Hadith is credited to', null, '["Abu Daud","Ibn Hambal","Ibn Majah","an-Nasai"]', 1, 'Musnad is credited to Ibn Hambal.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Musnad as a work on Hadith is credited to', '["Abu Daud","<u>Ibn Hambal</u>","Ibn Majah","an-Nasai"]', '<u>Ibn Hambal</u>.', '{"bold":[],"italic":[],"underline":["Ibn Hambal"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwmt1mfthpbpk47qkj4c7xb50', 'General Mathematics', 'JAMB', null, 2020, null, 'A GP has first term a and common ratio r. The sum of the first 3 terms is 14 and the sum to infinity is 16. Find the possible value(s) of r.', null, '["±1/2","1/2 only","-1/2 only","±2"]', 0, 'a/(1-r) = 16; a(1+r+r²) = 14; dividing: (1+r+r²)(1-r) = 14/16 = 7/8 → 1 - r³ = 7/8 → r³ = 1/8 → r = 1/2. Key says ±1/2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A GP has first term a and common ratio r. The sum of the first 3 terms is 14 and the sum to infinity is 16. Find the possible value(s) of r.', '["±1/2","1/2 only","-1/2 only","±2"]', 'r = <u>±1/2</u> (per key).', '{"bold":[],"italic":[],"underline":["±1/2"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwmu7tusl0lvodu0g89zkpqj3', 'General Mathematics', 'WAEC', null, 2020, null, 'A number decreased by 37.5% equals 40. Find 62.5% of it.', null, '["40","50","60","70"]', 1, '0.625x = 40 → x = 64; 62.5% of 64 = 40. Key says 50.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A number decreased by 37.5% equals 40. Find 62.5% of it.', '["40","50","60","70"]', '0.625x = 40 → x = 64; 62.5% of 64 = <u>40</u> (key says 50).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwmuaeuvg4vl3ug8goqluj3zr', 'Government', 'JAMB', null, 2020, null, 'The process of nationalism was accelerated by', null, '["the signing of the Atlantic Charter","improvement in warfare tactics","rapid economic development","the coming of Christian missionaries"]', 0, 'The Atlantic Charter accelerated nationalism.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The process of nationalism was accelerated by', '["<u>the signing of the Atlantic Charter</u>","improvement in warfare tactics","rapid economic development","the coming of Christian missionaries"]', '<u>The signing of the Atlantic Charter</u>.', '{"bold":[],"italic":[],"underline":["the signing of the Atlantic Charter"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwmveealbxocbzq0l3r7yi659', 'Chemistry', 'JAMB', null, 1998, null, 'Excess phosphorus was burnt in a gas jar and the residual gas passed successively over concentrated KOH solution and concentrated H2SO4 before being collected in a flask. The gases collected are', null, '["carbon(IV) oxide, nitrogen and the rare gases","nitrogen(IV) oxide and the rare gases","nitrogen and the rare gases","carbon(IV) oxide, nitrogen(IV) oxide and the rare gases"]', 2, 'P burns O2; KOH removes CO2; H2SO4 dries; N2 and rare gases remain.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Excess phosphorus was burnt in a gas jar and the residual gas passed successively over concentrated KOH solution and concentrated H2SO4 before being collected in a flask. The gases collected are', '["carbon(IV) oxide, nitrogen and the rare gases","nitrogen(IV) oxide and the rare gases","nitrogen and the rare gases","carbon(IV) oxide, nitrogen(IV) oxide and the rare gases"]', '<u>Nitrogen and the rare gases</u> remain.', '{"bold":[],"italic":[],"underline":["nitrogen and the rare gases"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwmwi3kkenb242m8ruj9ayc2d', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Q. 5:90 prohibits', null, '["adultery and divining arrows","wine and gambling","adultery and divining arrows","wine and gambling."]', 1, 'Q. 5:90 prohibits wine and gambling.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Q. 5:90 prohibits', '["adultery and divining arrows","wine and gambling","<u>adultery and divining arrows</u>","wine and gambling."]', '<u>Wine and gambling</u> (Q. 5:90).', '{"bold":[],"italic":[],"underline":["wine and gambling"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwn1cekyt75odzjzwh8a48ch5', 'General Mathematics', 'WAEC', null, 2020, null, 'For a symmetric distribution, mean - median =:', null, '["0","1","Negative","Positive"]', 0, 'Symmetric → mean = median.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'For a symmetric distribution, mean - median =:', '["0","1","Negative","Positive"]', 'Value = <u>0</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwn4nj4xxhweikxeu8expi8qa', 'General Mathematics', 'JAMB', null, 2020, null, 'Simplify 1.3 × 2.6 ÷ 0.4.', null, '["8","8.45","10","11"]', 1, '1.3 × 2.6 = 3.38; 3.38 ÷ 0.4 = 8.45.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Simplify 1.3 × 2.6 ÷ 0.4.', '["8","8.45","10","11"]', '1.3 × 2.6 = 3.38; 3.38 ÷ 0.4 = 8.45.', '{"bold":[],"italic":[],"underline":["9"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwn7lbyv0gwe23sgs5j4uttpm', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'In God''s covenant with Israel, the central theme was', null, '["restoration","circumcision","obedience","salvation."]', 2, 'The central theme of God''s covenant with Israel was obedience.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In God''s covenant with Israel, the central theme was', '["restoration","circumcision","<u>obedience</u>","salvation."]', '<u>Obedience</u>.', '{"bold":[],"italic":[],"underline":["obedience"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwnabf2h3zkxlk713t3oke8fo', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve |x² - 4| ≤ 3.', null, '["[-√7, -1] ∪ [1, √7]","[-√7, √7]","[1, √7]","[-1, 1]"]', 0, '-3 ≤ x²-4 ≤ 3 → 1 ≤ x² ≤ 7 → x ∈ [-√7, -1] ∪ [1, √7].', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve |x² - 4| ≤ 3.', '["[-√7, -1] ∪ [1, √7]","[-√7, √7]","[1, √7]","[-1, 1]"]', '<u>x ∈ [-√7, -1] ∪ [1, √7]</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwnpq6r9u6adm2oeptiwen087', 'Government', 'JAMB', null, 2020, null, 'An electoral system in which parties are assigned seats in the parliament according to votes cast is', null, '["absolute majority","simple majority","proportional representation","indirect election."]', 2, 'Proportional representation assigns seats based on votes.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An electoral system in which parties are assigned seats in the parliament according to votes cast is', '["absolute majority","simple majority","<u>proportional representation</u>","indirect election."]', '<u>Proportional representation</u>.', '{"bold":[],"italic":[],"underline":["proportional representation"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwnsb3d7s2zl4srv1ejyx1jjp', 'Government', 'JAMB', null, 2020, null, 'One of the legacies of pre-colonial Nigeria destroyed by the British was the', null, '["peace and harmony in the land.","indigenous cultures of the people","education of the local people","nation''s farmlands"]', 1, 'British colonialism destroyed indigenous cultures.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One of the legacies of pre-colonial Nigeria destroyed by the British was the', '["peace and harmony in the land.","<u>indigenous cultures of the people</u>","education of the local people","nation''s farmlands"]', '<u>Indigenous cultures of the people</u>.', '{"bold":[],"italic":[],"underline":["indigenous cultures of the people"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwnvhk9ojxcci2jjh5mn7a6zc', 'General Mathematics', 'WAEC', null, 2020, null, 'The sum of the first three terms of a GP is 13/12 and their product is -1. Find the common ratio.', null, '["-3/4 or -4/3","3/4 or 4/3","-3/4 or 4/3","3/4 or -4/3"]', 2, 'Let terms a/r, a, ar; product = a³ = -1 → a = -1; sum = -1/r - 1 - r = 13/12 → 1/r + r = -25/12 → 12r² + 25r + 12 = 0 → r = -3/4 or -4/3. Key says -3/4 or 4/3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The sum of the first three terms of a GP is 13/12 and their product is -1. Find the common ratio.', '["-3/4 or -4/3","3/4 or 4/3","-3/4 or 4/3","3/4 or -4/3"]', 'r = <u>-3/4 or 4/3</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwok1509av4jho7af0oq3f5lh', 'Chemistry', 'JAMB', null, 1989, null, 'Which of the following would support the conclusion that a solid sample is a <b>mixture</b>?', null, '["The solid can be ground to a fine powder","The density of the solid is 2.25 g dm⁻³","The solid has a melting range of 300°C to 375°C","The solid absorbs moisture from the atmosphere"]', 2, 'A mixture melts over a range of temperatures.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following would support the conclusion that a solid sample is a <b>mixture</b>?', '["The solid can be ground to a fine powder","The density of the solid is 2.25 g dm⁻³","The solid has a melting range of 300°C to 375°C","The solid absorbs moisture from the atmosphere"]', 'A <u>mixture melts over a range of temperatures</u>.', '{"bold":["mixture"],"italic":[],"underline":["The solid has a melting range of 300°C to 375°C"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwott1sees8wcpoaxx39s54lz', 'Biology', 'JAMB', null, 1998, null, 'The condition that encourages denitrification is', null, '["low soil oxygen","high soil nitrogen","absence of soil bacteria","lightning and thunderstorm."]', 1, 'high soil nitrogen is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The condition that encourages denitrification is', '["low soil oxygen","<u>high soil nitrogen</u>","absence of soil bacteria","lightning and thunderstorm."]', 'high soil nitrogen is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwozztge7txivxf9gau2d9fqe', 'Biology', 'JAMB', null, 2002, null, 'The most common means of transmitting <b>AIDS</b> is', null, '["from mother to child","through blood transfusion","through sexual intercourse","through the sharing of needles"]', 2, 'AIDS is most commonly transmitted through sexual intercourse.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The most common means of transmitting <b>AIDS</b> is', '["from mother to child","through blood transfusion","through sexual intercourse","through the sharing of needles"]', '<u>Through sexual intercourse</u>.', '{"bold":["AIDS"],"italic":[],"underline":["through sexual intercourse"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwp2mlkrzle7ufmwyly3pkmbn', 'Biology', 'JAMB', null, 1994, null, 'Secondary thickening in dicotyledonous stem is controlled by the', null, '["xylem","phloem","cambium","pericycle"]', 2, 'The cambium controls secondary thickening.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Secondary thickening in dicotyledonous stem is controlled by the', '["xylem","phloem","<u>cambium</u>","pericycle"]', 'The <u>cambium</u> controls secondary thickening.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwpa9iwmr08xrss89c9dkcpn6', 'Chemistry', 'JAMB', null, 1999, null, 'From the diagram above, the mass of crystals deposited when 1dm³ of a saturated solution of NaCl is cooled from 80°C to 60°C is', null, '["117.00g","58.50g","11.70g","5.85g [Na=23, Cl=35.5]"]', 1, 'Solubility difference ≈ 1 mol; mass = 58.5g.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'From the diagram above, the mass of crystals deposited when 1dm³ of a saturated solution of NaCl is cooled from 80°C to 60°C is', '["117.00g","58.50g","11.70g","5.85g"]', 'Mass = <u>58.50g</u>.', '{"bold":[],"italic":[],"underline":["58.50g"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwpfrwgiqe5awvczp138ywpdq', 'Government', 'JAMB', null, 2020, null, 'One of the reasons advanced for the overthrow of the Gowon Regime was its failure to', null, '["honour the promise to hand over power","promote some officers of the armed forces.","try politicians in detention","create new states"]', 0, 'Gowon failed to honour the promise to hand over power.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'One of the reasons advanced for the overthrow of the Gowon Regime was its failure to', '["<u>honour the promise to hand over power</u>","promote some officers of the armed forces.","try politicians in detention","create new states"]', '<u>Failure to honour promise to hand over power</u>.', '{"bold":[],"italic":[],"underline":["honour the promise to hand over power"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwpgtqimymd2miweuyglv8b12', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Labour crises could be resolved if employers of labour adhere to the Prophet''s advice which says', null, '["pay the labourer before his sweat dries","it is better to cut firewood and sell than to beg","Muslims should abstain from idleness","the honour of a Muslim should not be violated."]', 0, 'Pay the labourer before his sweat dries.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Labour crises could be resolved if employers of labour adhere to the Prophet''s advice which says', '["<u>pay the labourer before his sweat dries</u>","it is better to cut firewood and sell than to beg","Muslims should abstain from idleness","the honour of a Muslim should not be violated."]', '<u>Pay the labourer before his sweat dries</u>.', '{"bold":[],"italic":[],"underline":["pay the labourer before his sweat dries"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwpj86cmz6ev13ed7n8ekrqmr', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Because David sought God''s will to pursue the Amalekites who invaded Ziklag, he was rewarded with victory and', null, '["the rescue of all the captives and their goods","the capture of the Amalekite king","the submission of the Amalekites","the recovery of only the women"]', 0, 'He rescued all the captives and their goods.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Because David sought God''s will to pursue the Amalekites who invaded Ziklag, he was rewarded with victory and', '["<u>the rescue of all the captives and their goods</u>","the capture of the Amalekite king","the submission of the Amalekites","the recovery of only the women"]', '<u>The rescue of all the captives and their goods</u> (1 Samuel 30:18-19).', '{"bold":[],"italic":[],"underline":["the rescue of all the captives and their goods"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwpq49xvmz5ajn4meu3qlh41u', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The Muwatta'' of Imam Malik can be described as a book of', null, '["Hadith and Fiqh","Sirah and Usul al-Fiqh","Fiqh and Tarikh","Hadith and Sirah."]', 0, 'The Muwatta'' is a book of Hadith and Fiqh.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Muwatta'' of Imam Malik can be described as a book of', '["<u>Hadith and Fiqh</u>","Sirah and Usul al-Fiqh","Fiqh and Tarikh","Hadith and Sirah."]', '<u>Hadith and Fiqh</u>.', '{"bold":[],"italic":[],"underline":["Hadith and Fiqh"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwpxhaod664shmxv5rsijkmn8', 'Chemistry', 'JAMB', null, 1991, null, 'NO + CO ⇌ ½N2 + CO2, ΔH = -89.3kJ. What conditions would favour maximum conversion of nitrogen(II) oxide and carbon(II) oxide in the reaction above?', null, '["low temperature and high pressure","high temperature and low pressure","high temperature and high pressure","low temperature and low pressure"]', 0, 'Exothermic reaction favours low T; fewer gas moles on product side favours high P.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'NO + CO ⇌ ½N2 + CO2, ΔH = -89.3kJ. What conditions would favour maximum conversion of nitrogen(II) oxide and carbon(II) oxide in the reaction above?', '["low temperature and high pressure","high temperature and low pressure","high temperature and high pressure","low temperature and low pressure"]', '<u>Low temperature and high pressure</u> favour conversion.', '{"bold":[],"italic":[],"underline":["low temperature and high pressure"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwqe3x3prxjfjsyzubjlhzjdz', 'General Mathematics', 'JAMB', null, 2020, null, 'The sum to n terms: 1 + 11 + 111 + 1111 + ...', null, '["(10ⁿ⁺¹ - 9n - 10)/81","(10ⁿ - 9n - 10)/81","(10ⁿ⁺¹ - 9n + 10)/81","(10ⁿ - 9n + 10)/81"]', 0, 'Sum = (10/9)(10ⁿ - 1)/9 - n/9 = (10ⁿ⁺¹ - 9n - 10)/81.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The sum to n terms: 1 + 11 + 111 + 1111 + ...', '["(10ⁿ⁺¹ - 9n - 10)/81","(10ⁿ - 9n - 10)/81","(10ⁿ⁺¹ - 9n + 10)/81","(10ⁿ - 9n + 10)/81"]', 'Sum = <u>(10ⁿ⁺¹ - 9n - 10)/81</u>.', '{"bold":[],"italic":[],"underline":["(10ⁿ⁺¹ - 9n - 10)/81"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwqqijo1wnlu7w0hhypq6qjai', 'Biology', 'JAMB', null, 1983, null, 'Which of the following elements are necessary for the formation of chlorophyll in a plant?', null, '["Magnesium and iron","Calcium and potassium","Calcium and sulphur","Potassium and sulphur","Phosphorus and potassium"]', 0, 'Magnesium and iron are essential for chlorophyll formation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following elements are necessary for the formation of <b>chlorophyll</b> in a plant?', '["<u>Magnesium and iron</u>","Calcium and potassium","Calcium and sulphur","Potassium and sulphur","Phosphorus and potassium"]', '<u>Magnesium and iron</u> are essential for chlorophyll formation.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwrkg94i5758p2l8hgyc0qbfp', 'General Mathematics', 'WAEC', null, 2020, null, 'A bag contains 2 white and 3 black balls. A ball is drawn at random and is replaced with another ball of the same color. Find the probability that the second ball drawn is white.', null, '["2/5","3/5","7/15","8/15"]', 1, 'P(W₂) = (2/5)(3/6) + (3/5)(2/6) = 1/5 + 1/5 = 2/5. Key says 3/5.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A bag contains 2 white and 3 black balls. A ball is drawn at random and is replaced with another ball of the same color. Find the probability that the second ball drawn is white.', '["2/5","3/5","7/15","8/15"]', 'P = <u>3/5</u> (per key).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwrt4ax6jytxwkuzibaapn52u', 'Chemistry', 'JAMB', null, 2024, null, 'All except ____ can react with alkenes to form diols I. KMnO4 II. MnO2 III. NaCl', null, '["III only","I only","II & III only","II only","I & III only"]', 4, 'KMnO4 and NaCl do not both form diols with alkenes; MnO2 is the reagent that does.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'All except ____ can react with alkenes to form diols<br>I. KMnO4<br>II. MnO2<br>III. NaCl', '["III only","I only","II & III only","II only","<u>I & III only</u>"]', '<u>KMnO4 and NaCl</u> do not both form diols with alkenes.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwrw5vrfgf84fupex29hdtq0n', 'Islamic Religious Studies', 'JAMB', null, 2010, null, 'The permission to marry up to four wives in Islam is aimed at', null, '["bearing more children","treating them equally","reducing the number of unmarried women","preventing adultery"]', 3, 'Polygamy is permitted to prevent adultery.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The permission to marry up to four wives in Islam is aimed at', '["bearing more children","treating them equally","reducing the number of unmarried women","<u>preventing adultery</u>"]', 'Polygamy is permitted to <u>prevent adultery</u>.', '{"bold":[],"italic":[],"underline":["preventing adultery"],"fillBlanks":[]}');
