insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwsh46vx1m6q8wj1fi89vv6r1', 'Biology', 'JAMB', null, 1997, null, 'The element that is essential for the coagulation of blood is', null, '["potassium","calcium","phosphorus","iron."]', 1, 'calcium is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The element that is essential for the coagulation of blood is', '["potassium","<u>calcium</u>","phosphorus","iron."]', 'calcium is the best answer because it matches the biological principle tested by the question.', null);
