insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwslktuh4lzl91d37kk3mb7ec', 'Biology', 'JAMB', null, 1987, null, 'Most cells in higher animals retain their power of division EXCEPT', null, '["lymphocytes","nerve cells","malpighian cells","germ cells"]', 1, 'Nerve cells lose their power of division.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Most cells in higher animals retain their power of division <b>EXCEPT</b>', '["lymphocytes","<u>nerve cells</u>","malpighian cells","germ cells"]', '<u>Nerve cells lose their power of division</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwsodbxtvihwjqbx8j1785plv', 'Biology', 'JAMB', null, 2001, null, 'In man, the ability to roll the tongue is a variation classified as', null, '["anatomical","physiological","structural","morphological"]', 1, 'Tongue rolling is a physiological variation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In man, the ability to roll the tongue is a variation classified as', '["anatomical","physiological","structural","morphological"]', '<u>Physiological</u> variation.', '{"bold":[],"italic":[],"underline":["physiological"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwsr7ktfdyh7qlae4xzteeqiw', 'General Mathematics', 'WAEC', null, 2020, null, 'Evaluate (2/3) ÷ (4/9) + (5/6) × (3/10).', null, '["1.5","1.75","2","2.25"]', 1, '(2/3)×(9/4) + (5/6)×(3/10) = 3/2 + 1/4 = 1.75.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Evaluate (2/3) ÷ (4/9) + (5/6) × (3/10).', '["1.5","1.75","2","2.25"]', '(2/3)÷(4/9) + (5/6)×(3/10) = <u>1.75</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwsu7jyjdmzhw6swn7xjjcjt5', 'General Mathematics', 'JAMB', null, 2020, null, 'tan⁻¹(1) + tan⁻¹(2) + tan⁻¹(3) =', null, '["π","π/2","2π","0"]', 0, 'tan⁻¹(1) + tan⁻¹(2) + tan⁻¹(3) = π.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'tan⁻¹(1) + tan⁻¹(2) + tan⁻¹(3) =', '["π","π/2","2π","0"]', 'Sum = <u>π</u>.', '{"bold":[],"italic":[],"underline":["π"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwsw3f6prw429v8y77cx8836l', 'Biology', 'JAMB', null, 1991, null, 'Floating microscopic heterotrophs are mostly grouped as', null, '["phytoplankton","zooplankton","microbes","netkon"]', 1, 'Floating microscopic heterotrophs are zooplankton.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Floating microscopic heterotrophs are mostly grouped as', '["phytoplankton","<u>zooplankton</u>","microbes","netkon"]', 'Floating microscopic heterotrophs are <u>zooplankton</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwswd0d6h2d24c7co21r5egdh', 'General Mathematics', 'JAMB', null, 2020, null, 'A committee of 5 is to be formed from 4 men and 6 women. If the committee must consist of at least 3 men, find the number of ways of forming the committee.', null, '["60","66","100","186"]', 1, 'At least 3 men: 4C3·6C2 + 4C4·6C1 = 60 + 6 = 66.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A committee of 5 is to be formed from 4 men and 6 women. If the committee must consist of at least 3 men, find the number of ways of forming the committee.', '["60","66","100","186"]', 'Ways = <u>66</u>.', '{"bold":[],"italic":[],"underline":["66"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwsx9gyiwu7rpihpv7vqqc1qq', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve for x and y: 4ˣ · 2ʸ = 16 · 2³ˣ and 9ˣ⁺ʸ = 27ʸ⁻¹.', null, '["x = 1, y = 5","x = 2, y = -5","x = 2, y = 5","x = -2, y = -5"]', 0, '2x + y = 4 + 3x → y = x + 4; 2x + 2y = 3y - 3 → y = 2x + 3; so x = 1, y = 5.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Solve for x and y: 4ˣ · 2ʸ = 16 · 2³ˣ and 9ˣ⁺ʸ = 27ʸ⁻¹.', '["x = 1, y = 5","x = 2, y = -5","x = 2, y = 5","x = -2, y = -5"]', '2x + y = 4 + 3x → y = x + 4; 2x + 2y = 3y - 3 → y = 2x + 3; so x = 1, y = 5.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwsxqelh6zehd7k47dby1ga8n', 'General Mathematics', 'JAMB', null, 2020, null, 'Poisson distribution with λ = 4. Find P(X = 2).', null, '["8e⁻⁴","4e⁻⁴","2e⁻⁴","e⁻⁴"]', 0, 'P(X=2) = e⁻⁴·4²/2! = 8e⁻⁴.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Poisson distribution with λ = 4. Find P(X = 2).', '["8e⁻⁴","4e⁻⁴","2e⁻⁴","e⁻⁴"]', 'P = <u>8e⁻⁴</u>.', '{"bold":[],"italic":[],"underline":["8e⁻⁴"],"fillBlanks":[]}');
