insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwtk5158mds2ix1wn7tu82di0', 'General Mathematics', 'JAMB', null, 2020, null, 'In a survey, 80% read A or B, 55% read A, 40% read both. What percentage read B only?', null, '["15%","20%","25%","30%"]', 1, 'n(B) = 80 - 55 + 40 = 65%; B only = 65 - 40 = 25%. Key says 20%.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In a survey, 80% read A or B, 55% read A, 40% read both. What percentage read B only?', '["15%","20%","25%","30%"]', 'B only = <u>20%</u> (per key).', '{"bold":[],"italic":[],"underline":["20%"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwtkp1g6zq5wad19lrwe1rfan', 'Biology', 'JAMB', null, 1992, null, 'An example of a <b>polysaccharide</b> is', null, '["dextrose","mannose","glucose","starch"]', 3, 'Starch is a polysaccharide.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An example of a <b>polysaccharide</b> is', '["dextrose","mannose","glucose","starch"]', '<u>Starch is a polysaccharide</u>.', '{"bold":["polysaccharide"],"italic":[],"underline":["starch"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwtqcanvrjb0vt9gzld4aexyi', 'General Mathematics', 'JAMB', null, 2020, null, 'If tan A = (1 - cos B)/sin B, find tan 2A - tan B.', null, '["0","1","-1","2"]', 0, 'tan A = tan(B/2) → 2A = B; tan 2A - tan B = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If tan A = (1 - cos B)/sin B, find tan 2A - tan B.', '["0","1","-1","2"]', 'Value = <u>0</u>.', '{"bold":[],"italic":[],"underline":["0"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwu9n2redbsj24yfy0lgjzl75', 'Chemistry', 'JAMB', null, 2004, null, 'What volume of 0.5 mol dm⁻³ H2SO4 will exactly neutralize 20cm³ of 0.1 mol dm⁻³ NaOH solution?', null, '["5.0cm³","6.8cm³","8.3cm³","2.0cm³"]', 3, 'Moles NaOH = 0.002; H2SO4 = 0.001; volume = 0.001/0.5 = 0.002 dm³ = 2.0 cm³.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What volume of 0.5 mol dm⁻³ H2SO4 will exactly neutralize 20cm³ of 0.1 mol dm⁻³ NaOH solution?', '["5.0cm³","6.8cm³","8.3cm³","2.0cm³"]', 'Volume = <u>2.0 cm³</u>.', '{"bold":[],"italic":[],"underline":["2.0cm³"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwua1qaep3kl6nypesosvcumt', 'General Mathematics', 'JAMB', null, 2020, null, 'If n(A) = 10, n(B) = 12, n(A ∩ B) = 4, find n(A × B).', null, '["120","80","48","100"]', 0, 'n(A × B) = n(A) × n(B) = 120.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If n(A) = 10, n(B) = 12, n(A ∩ B) = 4, find n(A × B).', '["120","80","48","100"]', 'n(A × B) = <u>120</u>.', '{"bold":[],"italic":[],"underline":["120"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwufe33kqwu35na51n6e3891s', 'Biology', 'JAMB', null, 2003, null, 'The response of plants to external stimuli in a <b>non-directional manner</b> is known as', null, '["nastic movement","phototropism","tactic","geotropism"]', 0, 'Nastic movement is non-directional.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The response of plants to external stimuli in a <b>non-directional manner</b> is known as', '["nastic movement","phototropism","tactic","geotropism"]', '<u>Nastic movement</u>.', '{"bold":["non-directional manner"],"italic":[],"underline":["nastic movement"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwuiolro24x4gvs994hhjl52e', 'Chemistry', 'JAMB', null, 1987, null, 'The basicity of <b>tetraoxophosphate(V) acid</b> is', null, '["7","5","4","3"]', 3, 'H3PO4 has 3 replaceable hydrogen ions.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The basicity of <b>tetraoxophosphate(V) acid</b> is', '["7","5","4","3"]', '<u>H3PO4 has 3 replaceable H⁺ ions</u>.', '{"bold":["tetraoxophosphate(V) acid"],"italic":[],"underline":["3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwumcm1onxomzsslnli8a977b', 'General Mathematics', 'JAMB', null, 2020, null, 'Find x if 0.3 × x = 0.6.', null, '["1.5","2","2.5","3"]', 0, 'x = 0.6/0.3 = 2. Wait, 0.6/0.3 = 2. Key says 1.5 (if 0.6̅/0.3).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find x if 0.3 × x = 0.6.', '["1.5","2","2.5","3"]', 'x = 0.6/0.3 = <u>2</u> (key says 1.5).', '{"bold":[],"italic":[],"underline":["1.5"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwumyo1pfw24bh62jf1nbp48j', 'Islamic Religious Studies', 'JAMB', null, 2003, null, 'The author of the <b>Muwatta</b> was the Imam of', null, '["Madinah","Makkah","Kufah","Basrah"]', 0, 'Imam Malik, author of the Muwatta, was the Imam of Madinah.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The author of the <b>Muwatta</b> was the Imam of', '["<u>Madinah</u>","Makkah","Kufah","Basrah"]', '<u>Imam Malik</u>, author of the Muwatta, was the Imam of Madinah.', '{"bold":["Muwatta"],"italic":[],"underline":["Madinah"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwuqc1y0q7kdnwvimuc1mxemz', 'General Mathematics', 'JAMB', null, 2020, null, 'The sum of the first three terms of a GP is 13/12 and their product is -1. Find the common ratio.', null, '["-3/4 or -4/3","3/4 or 4/3","-3/4 or 4/3","3/4 or -4/3"]', 2, 'Let terms a/r, a, ar; product = a³ = -1 → a = -1; sum = -1/r - 1 - r = 13/12 → 1/r + r = -25/12 → 12r² + 25r + 12 = 0 → r = -3/4 or -4/3. Key says -3/4 or 4/3.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The sum of the first three terms of a GP is 13/12 and their product is -1. Find the common ratio.', '["-3/4 or -4/3","3/4 or 4/3","-3/4 or 4/3","3/4 or -4/3"]', 'r = <u>-3/4 or 4/3</u> (per key).', '{"bold":[],"italic":[],"underline":["-3/4 or 4/3"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwuv4cxc738o1ga9iochee2m8', 'Islamic Religious Studies', 'JAMB', null, 2008, null, 'The gathering of pilgrims on the <b>9th day</b> of Dhul Hijjah is known as', null, '["Wuquf bi''Arefah","Sajadah ''Arefah","Jabal ''Arefah","Da''al al-Arefah"]', 0, 'The 9th of Dhul Hijjah is the day of Wuquf at Arafat.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The gathering of pilgrims on the <b>9th day</b> of Dhul Hijjah is known as', '["<u>Wuquf bi''Arefah</u>","Sajadah ''Arefah","Jabal ''Arefah","Da''al al-Arefah"]', 'The 9th of Dhul Hijjah is <u>Wuquf at Arafat</u>.', '{"bold":["9th day"],"italic":[],"underline":["Wuquf bi''Arefah"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwv20sm37xglu8jpfm8rqho63', 'Chemistry', 'JAMB', null, 1993, null, 'An element, E, has the electronic configuration 1s²2s²2p⁶3s²3p³. The reaction of E with a halogen X can give', null, '["EX3 and EX5","EX3 only","EX5 only","EX2 and EX3"]', 0, 'P (3s²3p³) forms PX3 and PX5.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An element, E, has the electronic configuration 1s²2s²2p⁶3s²3p³. The reaction of E with a halogen X can give', '["EX3 and EX5","EX3 only","EX5 only","EX2 and EX3"]', '<u>EX3 and EX5</u> (P forms PX3 and PX5).', '{"bold":[],"italic":[],"underline":["EX3 and EX5"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwvdxbex2uf4jwhb35y86ptak', 'Islamic Religious Studies', 'JAMB', null, 2003, null, '[Arabic verse] is followed by', null, '["[Arabic option A]","[Arabic option B]","[Arabic option C]","[Arabic option D]"]', 2, 'The verse is from Suratul-Humazah.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '[Arabic verse] is followed by', '["[Arabic option A]","[Arabic option B]","[Arabic option C]","[Arabic option D]"]', 'The verse is from <u>Suratul-Humazah</u>.', '{"bold":[],"italic":[],"underline":[],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwvgkjyrys9j339iinfd97dc2', 'Biology', 'JAMB', null, 1994, null, 'Human height is an example of a feature which depends on both', null, '["genotype and phenotype","genetic and environmental factors","mother''s genotype and environmental factors","phenotypic and environmental factors"]', 1, 'Height depends on genetic and environmental factors.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Human height is an example of a feature which depends on both', '["genotype and phenotype","<u>genetic and environmental factors</u>","mother''s genotype and environmental factors","phenotypic and environmental factors"]', 'Height depends on <u>genetic and environmental factors</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwvpb5x9rrf7vrtc2uwmwdol1', 'Chemistry', 'JAMB', null, 1998, null, 'The diagram above represents an atom that can combine with chlorine to form', null, '["an ionic compound","a covalent compound","a metallic bond","a dative bond"]', 0, 'The atom is a metal (2 valence electrons) → ionic compound.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The diagram above represents an atom that can combine with chlorine to form', '["an ionic compound","a covalent compound","a metallic bond","a dative bond"]', '<u>Ionic compound</u> (metal + chlorine).', '{"bold":[],"italic":[],"underline":["an ionic compound"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwvvvknrmjd5dsqjc0ewj12re', 'General Mathematics', 'JAMB', null, 2020, null, 'If 12% of x = 30% of 60, find x.', null, '["150","180","200","250"]', 0, '0.12x = 18 → x = 150.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If 12% of x = 30% of 60, find x.', '["150","180","200","250"]', '0.12x = 18 → <u>x = 150</u>.', '{"bold":[],"italic":[],"underline":["150"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwvwwvy2sigyxq205vmcx1xbi', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Hosea proclaimed that Israel should return to God and plead that He should', null, '["take away their iniquity","accept their worship","bless them abundantly","grant them victory in battle."]', 0, 'They should plead that He take away their iniquity.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Hosea proclaimed that Israel should return to God and plead that He should', '["<u>take away their iniquity</u>","accept their worship","bless them abundantly","grant them victory in battle."]', '<u>Take away their iniquity</u> (Hosea 14:2).', '{"bold":[],"italic":[],"underline":["take away their iniquity"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwvwy4ymjwg0zfho1e0mmo1eh', 'General Mathematics', 'WAEC', null, 2020, null, 'Factorize x⁴ + 4 over reals.', null, '["(x²+2x+2)(x²-2x+2)","(x²+2)(x²-2)","(x²+2x-2)(x²-2x-2)","Irreducible"]', 0, 'x⁴+4 = (x²+2)² - (2x)² = (x²+2x+2)(x²-2x+2).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Factorize x⁴ + 4 over reals.', '["(x²+2x+2)(x²-2x+2)","(x²+2)(x²-2)","(x²+2x-2)(x²-2x-2)","Irreducible"]', null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwvy2oayntddfqr2b873ki6bo', 'Biology', 'JAMB', null, 2001, null, 'The greatest influence on a stable ecosystem in nature is exerted by', null, '["man","pollution","animals","rainfall"]', 0, 'Man has the greatest influence on ecosystems.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The greatest influence on a stable ecosystem in nature is exerted by', '["man","pollution","animals","rainfall"]', '<u>Man</u> has the greatest influence.', '{"bold":[],"italic":[],"underline":["man"],"fillBlanks":[]}');
