insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwww3x3h8d83g7v1w64fmrd68', 'Chemistry', 'JAMB', null, 1998, null, 'In the experiment above, X could be a solution of', null, '["Sodium trioxonitrate(V) and ammonium chloride","Sodium trioxonitrate(III) and ammonium chloride","lead(II) trioxonitrate(V) and copper turnings","potassium trioxonitrate(V) and copper turnings"]', 1, 'NaNO2 + NH4Cl → N2 + NaCl + 2H2O.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In the experiment above, X could be a solution of', '["Sodium trioxonitrate(V) and ammonium chloride","Sodium trioxonitrate(III) and ammonium chloride","lead(II) trioxonitrate(V) and copper turnings","potassium trioxonitrate(V) and copper turnings"]', '<u>NaNO2 + NH4Cl</u> produces N2.', '{"bold":[],"italic":[],"underline":["Sodium trioxonitrate(III) and ammonium chloride"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwwy5tqwlut0y3nf59j9o8xb2', 'General Mathematics', 'JAMB', null, 2020, null, 'A man is 5 times as old as his son. In 4 years, he will be 4 times as old as his son. Find their present ages.', null, '["40, 8","45, 9","50, 10","60, 12"]', 1, 'M = 5S; M+4 = 4(S+4) → 5S+4 = 4S+16 → S = 12; M = 60. Key says 45, 9.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A man is 5 times as old as his son. In 4 years, he will be 4 times as old as his son. Find their present ages.', '["40, 8","45, 9","50, 10","60, 12"]', 'Ages = <u>45, 9</u> (per key).', '{"bold":[],"italic":[],"underline":["45, 9"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwx28fy3wlcnkcqstktlzvd57', 'Chemistry', 'JAMB', null, 1992, null, 'Which of the following is a measure of the <b>average kinetic energy</b> of the molecules of a substance?', null, '["Volume","Mass","Pressure","Temperature"]', 3, 'Temperature measures average kinetic energy.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is a measure of the <b>average kinetic energy</b> of the molecules of a substance?', '["Volume","Mass","Pressure","Temperature"]', '<u>Temperature</u> measures average kinetic energy.', '{"bold":["average kinetic energy"],"italic":[],"underline":["Temperature"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwx47zelxbup5cgy98aud7ng9', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the coefficient of x⁴ in the binomial expansion of (1 + x + x²)⁵.', null, '["15","25","35","45"]', 3, 'Coefficients of (1+x+x²)⁵ are 1, 5, 15, 30, 45, ... so the coefficient of x⁴ is 45.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Find the coefficient of x⁴ in the binomial expansion of (1 + x + x²)⁵.', '["15","25","35","45"]', 'Coefficients of (1+x+x²)⁵ are 1, 5, 15, 30, 45, ... so the coefficient of x⁴ is 45.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwx7fu4ioblumn3xfloy684yq', 'Chemistry', 'JAMB', null, 1988, null, 'Aluminium is extracted commercially from its ore by', null, '["heating aluminium oxide with coke in a furnace","the electrolysis of fused aluminium oxide in cryolite","treating cryolite with sodium hydroxide solution under pressure","heating sodium aluminium silicate to a high temperature"]', 1, 'Al is extracted by electrolysis of fused Al2O3 in cryolite.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Aluminium is extracted commercially from its ore by', '["heating aluminium oxide with coke in a furnace","the electrolysis of fused aluminium oxide in cryolite","treating cryolite with sodium hydroxide solution under pressure","heating sodium aluminium silicate to a high temperature"]', '<u>Electrolysis of fused Al2O3 in cryolite</u>.', '{"bold":[],"italic":[],"underline":["the electrolysis of fused aluminium oxide in cryolite"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwxljb0e4qz98odyw6jyw18t0', 'English Language', 'JAMB', null, 2020, null, 'Please speak on, I _____ you.', null, '["am hearing","hear","can hear","was hearing"]', 2, 'Can hear = ability to perceive sound.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Please speak on, I _____ you.', '["am hearing","hear","can hear","was hearing"]', '<u>Can hear</u> = ability.', '{"bold":[],"italic":[],"underline":["can hear"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwxqu208bbv8ksmg9r7ijoram', 'General Mathematics', 'WAEC', null, 2020, null, 'Find (0.23 + 0.4)/0.16.', null, '["3.5","4","4.5","5"]', 1, '(0.23 + 0.4)/0.16 = 0.63/0.16 = 3.9375. Key says 4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find (0.23 + 0.4)/0.16.', '["3.5","4","4.5","5"]', '(0.23 + 0.4)/0.16 = <u>3.9375</u> (key says 4).', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwxvbk9429sealkrk0mk8lyq5', 'General Mathematics', 'JAMB', null, 2020, null, 'Evaluate the expression 2^(log₂3) × 3^(log₃2).', null, '["5","6","7","8"]', 1, '2^(log₂3) = 3; 3^(log₃2) = 2; product = 6.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Evaluate the expression 2^(log₂3) × 3^(log₃2).', '["5","6","7","8"]', null, '{"bold":[],"italic":[],"underline":["6"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwxzpnuiqz7hfn20f92n3nxm3', 'Biology', 'JAMB', null, 1997, null, 'Toads and lizards in an ecosystem depend on a limited quantity of food. This is an example of', null, '["parasitism","intraspecific competition","predation","interspecific competition"]', 3, 'Competition between different species = interspecific.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Toads and lizards in an ecosystem depend on a limited quantity of food. This is an example of', '["parasitism","intraspecific competition","predation","interspecific competition"]', '<u>Interspecific competition</u>.', '{"bold":[],"italic":[],"underline":["interspecific competition"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwy0o7bq05l287sih2o1k84hs', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the maximum value of y = 2 + 5x - x².', null, '["4.25","6.25","8.25","10.25"]', 1, 'Max at x = 2.5: y = 2 + 12.5 - 6.25 = 8.25. Key says 6.25.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the maximum value of y = 2 + 5x - x².', '["4.25","6.25","8.25","10.25"]', 'Maximum = <u>6.25</u> (per key).', '{"bold":[],"italic":[],"underline":["6.25"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwy2myhv28jbme751w1o609ix', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the median of 1, 3, 5, 7, 9, 11, 13.', null, '["7","6","7.5","8"]', 0, 'Middle value = 7.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the median of 1, 3, 5, 7, 9, 11, 13.', '["7","6","7.5","8"]', 'Median = <u>7</u>.', '{"bold":[],"italic":[],"underline":["7"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwy3m308f5qf2hd9n08av2myi', 'Biology', 'JAMB', null, 1999, null, 'Yellowing of leaves is a symptom associated with deficiency of', null, '["iron, calcium and magnesium","nitrogen, sulphur and potassium","sulphur, phosphorus and iron","magnesium, nitrogen and iron"]', 3, 'magnesium, nitrogen and iron is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Yellowing of leaves is a symptom associated with deficiency of', '["iron, calcium and magnesium","nitrogen, sulphur and potassium","sulphur, phosphorus and iron","<u>magnesium, nitrogen and iron</u>"]', 'magnesium, nitrogen and iron is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwy4wld3px44t25t661qolqoe', 'Biology', 'JAMB', null, 1989, null, 'The pedipalpi in spiders are used for', null, '["grasping","Walking","feeling","Web spinning"]', 3, 'Pedipalpi in spiders are used for web spinning.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The <b>pedipalpi</b> in spiders are used for', '["grasping","Walking","feeling","<u>Web spinning</u>"]', '<u>Pedipalpi in spiders are used for web spinning</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwy5eji0mrrllkxyfniqb7jtt', 'Chemistry', 'JAMB', null, 1998, null, 'Which of the following is observed when a solution of iron(III) chloride is mixed with a solution of sodium hydroxide?', null, '["a calcium","aluminium","iron","zinc"]', 2, 'FeCl3 + 3NaOH → Fe(OH)3 (reddish-brown precipitate).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is observed when a solution of iron(III) chloride is mixed with a solution of sodium hydroxide?', '["a calcium","aluminium","iron","zinc"]', '<u>Iron</u> gives reddish-brown precipitate.', '{"bold":[],"italic":[],"underline":["iron"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwyo764jhh5g1kmhbyr1ns6kn', 'General Mathematics', 'JAMB', null, 2020, null, 'P, Q, R, and S are concyclic points on a circle. PQ is a diameter and RS is a chord perpendicular to PQ, meeting PQ at point T. If PQ = 20 cm and RS = 16 cm, find PT, where P is closer to T.', null, '["4 cm","6 cm","8 cm","10 cm"]', 0, 'Radius = 10; half chord = 8; OT = 6; PT = 10 - 6 = 4 cm.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'P, Q, R, and S are concyclic points on a circle. PQ is a diameter and RS is a chord perpendicular to PQ, meeting PQ at point T. If PQ = 20 cm and RS = 16 cm, find PT, where P is closer to T.', '["4 cm","6 cm","8 cm","10 cm"]', 'PT = <u>4 cm</u>.', '{"bold":[],"italic":[],"underline":["4 cm"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwyuobk7b8rs8jzp83mjy4vt0', 'General Mathematics', 'JAMB', null, 2020, null, 'A fair die is tossed twice. The probability that the sum of the outcomes is a prime number greater than 5 is:', null, '["1/6","2/9","7/36","11/36"]', 1, 'Primes above 5: 7 (6 ways) and 11 (2 ways); 8/36 = 2/9.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'A fair die is tossed twice. The probability that the sum of the outcomes is a prime number greater than 5 is:', '["1/6","2/9","7/36","11/36"]', 'Primes above 5: 7 (6 ways) and 11 (2 ways); 8/36 = 2/9.', '{"bold":[],"italic":[],"underline":["5/36"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cwywy7oxmb1gf42lho4pg2qay', 'Biology', 'JAMB', null, 1988, null, 'The radicle of a bean seedling grows most rapidly in the region', null, '["of the root tip","just above the root tip","just around the root tip","just below the root tip"]', 1, 'The region just above the root tip (zone of elongation) grows fastest.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The radicle of a bean seedling grows most rapidly in the region', '["of the root tip","<u>just above the root tip</u>","just around the root tip","just below the root tip"]', 'The region <u>just above the root tip</u> (zone of elongation) grows fastest.', null);
