insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cx0snvz2ixuxdw2rdozy2f3qj', 'Chemistry', 'JAMB', null, 1989, null, 'The catalyst used in the <b>contact process</b> for the manufacture of tetraoxosulphate(VI) acid is', null, '["Manganese(IV) oxide","Manganese(II) tetraoxosulphate(IV)","Vanadium(V) oxide","Iron metal"]', 2, 'V2O5 is the catalyst in the contact process.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The catalyst used in the <b>contact process</b> for the manufacture of tetraoxosulphate(VI) acid is', '["Manganese(IV) oxide","Manganese(II) tetraoxosulphate(IV)","Vanadium(V) oxide","Iron metal"]', '<u>V2O5</u> is the catalyst in the contact process.', '{"bold":["contact process"],"italic":[],"underline":["Vanadium(V) oxide"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cx0zsozcli5w2b7y1ilg5mj2v', 'Chemistry', 'JAMB', null, 1999, null, 'Which of the following will have its mass increased when heated in air?', null, '["Helium","Magnesium","Copper pyrites","Glass"]', 1, 'Mg + O2 → MgO (mass increases).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following will have its mass increased when heated in air?', '["Helium","Magnesium","Copper pyrites","Glass"]', '<u>Magnesium</u> gains mass on heating in air.', '{"bold":[],"italic":[],"underline":["Magnesium"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cx10zy6808zr5z7koi6didnd3', 'Government', 'JAMB', null, 2020, null, 'In a unitary system of government, power is concentrated at the centre', null, '["with devolution","without residual functions","without devolution","with residual functions."]', 0, 'Unitary systems concentrate power at the centre with devolution.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'In a unitary system of government, power is concentrated at the centre', '["<u>with devolution</u>","without residual functions","without devolution","with residual functions."]', '<u>With devolution</u>.', '{"bold":[],"italic":[],"underline":["with devolution"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cx1baulg9qqojpm5y7gtpiuj7', 'Government', 'JAMB', null, 2020, null, 'Nigeria became a federation of thirty-six states during the era of', null, '["Abdulsalami Abubakar","Yakubu Gowon","Ibrahim Babangida","Sani Abacha"]', 3, 'Sani Abacha created the 36-state structure.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Nigeria became a federation of thirty-six states during the era of', '["Abdulsalami Abubakar","Yakubu Gowon","Ibrahim Babangida","<u>Sani Abacha</u>"]', '<u>Sani Abacha</u>.', '{"bold":[],"italic":[],"underline":["Sani Abacha"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cx1c5cwcx9hps54anhkbrq876', 'General Mathematics', 'WAEC', null, 2020, null, 'Evaluate the expression 2^(log₂3) × 3^(log₃2).', null, '["5","6","7","8"]', 1, '2^(log₂3) = 3; 3^(log₃2) = 2; product = 6.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Evaluate the expression 2^(log₂3) × 3^(log₃2).', '["5","6","7","8"]', null, null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cx1f2famwvtds37yn88ikex9t', 'Biology', 'JAMB', null, 1993, null, 'A biome where small mammals undergo aestivation for long periods is', null, '["1","2","3","4"]', 0, 'Small mammals aestivate in the desert biome (1).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A biome where small mammals undergo aestivation for long periods is', '["<u>1</u>","2","3","4"]', 'Small mammals aestivate in the <u>desert biome (1)</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cx1iaga9w8c4s9bhx0wyxvxzi', 'General Mathematics', 'JAMB', null, 2020, null, 'If 60% play football, 50% play cricket, 30% play both. What percentage play at least one?', null, '["80%","85%","90%","95%"]', 0, 'At least one = 60 + 50 - 30 = 80%.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If 60% play football, 50% play cricket, 30% play both. What percentage play at least one?', '["80%","85%","90%","95%"]', 'At least one = <u>80%</u>.', '{"bold":[],"italic":[],"underline":["80%"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cx1oqrzwjpxwwyg24bf3kagq8', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Where the father is the only heir who survives his son, he will inherit', null, '["one sixth of his property","one third of his property","half of his property","the whole of his property."]', 3, 'He inherits the whole property.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Where the father is the only heir who survives his son, he will inherit', '["one sixth of his property","one third of his property","half of his property","<u>the whole of his property.</u>"]', '<u>The whole of his property</u>.', '{"bold":[],"italic":[],"underline":["the whole of his property."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cx1r2ujapssvzk730qqveme1t', 'Chemistry', 'JAMB', null, 1992, null, 'Calculate the mass, in kilograms, of magnesium produced by the electrolysis of magnesium(II) chloride in a cell operating for 24 hours at 500 amperes. [F=96500C, Mg=24]', null, '["2.7","5.4","10.8","21.7"]', 1, 'Q = 500 × 86400 = 4.32×10⁷ C; moles e⁻ = 447.7; moles Mg = 223.8; mass = 5.37 kg.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Calculate the mass, in kilograms, of magnesium produced by the electrolysis of magnesium(II) chloride in a cell operating for 24 hours at 500 amperes. [F=96500C, Mg=24]', '["2.7","5.4","10.8","21.7"]', 'Mass ≈ <u>5.4 kg</u>.', '{"bold":[],"italic":[],"underline":["5.4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cx2a8qt3z22ml2t62e131pdit', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'The consequence of Hiel''s building of Jericho was that he', null, '["lost two of his sons","was highly respected by his tribe","was killed by Ahab","was made a commander in Ahab''s army."]', 0, 'Hiel lost two of his sons.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The consequence of Hiel''s building of Jericho was that he', '["<u>lost two of his sons</u>","was highly respected by his tribe","was killed by Ahab","was made a commander in Ahab''s army."]', '<u>Lost two of his sons</u> (1 Kings 16:34).', '{"bold":[],"italic":[],"underline":["lost two of his sons"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cx2g5e0mse7v6ifx0ki5mqiqm', 'General Mathematics', 'JAMB', null, 2020, null, 'The variance of the numbers 4, 5, 6, 8, and x is 6.8. Find x.', null, '["2","7","10","12"]', 1, 'Mean = (23+x)/5; variance = 6.8; solving → x = 7.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The variance of the numbers 4, 5, 6, 8, and x is 6.8. Find x.', '["2","7","10","12"]', 'x = <u>7</u>.', '{"bold":[],"italic":[],"underline":["7"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cx2ikrfk989b9dd3p855fknhp', 'Biology', 'JAMB', null, 1984, null, 'Which of the following sequences represents the process of blood clotting? 1. Fibrin forms a network of threads 2. Red blood cells are caught and a clot is formed 3. Fibrinogen in plasma changes into soluble fibrin 4. Blood is exposed to air', null, '["4,3,2,1","4,3,1,2","3,1,4,2","1,2,3,4","3,1,2,4"]', 1, 'Blood clotting: 4 (exposure to air) → 3 (fibrinogen to fibrin) → 1 (fibrin network) → 2 (clot formed) = 4,3,1,2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following sequences represents the process of blood clotting?<br>1. Fibrin forms a network of threads<br>2. Red blood cells are caught and a clot is formed<br>3. Fibrinogen in plasma changes into soluble fibrin<br>4. Blood is exposed to air', '["4,3,2,1","<u>4,3,1,2</u>","3,1,4,2","1,2,3,4","3,1,2,4"]', 'Blood clotting: 4 (exposure to air) → 3 (fibrinogen to fibrin) → 1 (fibrin network) → 2 (clot formed) = <u>4,3,1,2</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cx2kdsx6x56zazs2hjnnvz3ug', 'Chemistry', 'JAMB', null, 1985, null, 'What reaction takes place when palm-oil is added to potash and foams are observed?', null, '["Neutralization","Saponification","Etherification","Salting-out"]', 1, 'Saponification is the alkaline hydrolysis of fats to form soap.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'What reaction takes place when palm-oil is added to potash and foams are observed?', '["Neutralization","Saponification","Etherification","Salting-out"]', '<u>Saponification</u> is the alkaline hydrolysis of fats.', '{"bold":[],"italic":[],"underline":["Saponification"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cx2nug1epcj8dfzi787f32r9f', 'Islamic Religious Studies', 'JAMB', null, 2020, null, '''If anyone sees an abomination ...'' The Hadith above saddles man with the responsibility of', null, '["killing his enemies","fighting idolaters","resisting evil practices","only preaching against the abomination."]', 2, 'It saddles man with resisting evil practices.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '''If anyone sees an abomination ...'' The Hadith above saddles man with the responsibility of', '["killing his enemies","fighting idolaters","<u>resisting evil practices</u>","only preaching against the abomination."]', '<u>Resisting evil practices</u>.', '{"bold":[],"italic":[],"underline":["resisting evil practices"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cx2qh4wn6lqnhittn0330iett', 'Biology', 'JAMB', null, 1983, null, 'When a Spirogyra cell is immersed in a salt solution more concentrated than its cell sap, it', null, '["remains unchanged","takes up water and burst","absorbs a little water","loses water and shrivel","becomes turgid"]', 3, 'In a hypertonic solution, the cell loses water and shrivels.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'When a <b>Spirogyra</b> cell is immersed in a salt solution more concentrated than its cell sap, it', '["remains unchanged","takes up water and burst","absorbs a little water","<u>loses water and shrivel</u>","becomes turgid"]', 'In a hypertonic solution, the cell <u>loses water and shrivels</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cx2tvtmovhnyzs1n1jh1hzya2', 'Chemistry', 'JAMB', null, 1987, null, 'The best treatment for a student who accidentally poured concentrated tetraoxosulphate(VI) acid on his skin in the laboratory is to wash the skin with', null, '["cold water","sodium trioxocarbonate(IV) solution","Iodine solution","Sodium trioxocabonate(IV) solution"]', 3, 'Wash with Na2CO3 solution to neutralize the acid.', true, '2026-10-11 07:17:11.699', '2026-10-24 17:05:39.089', null, null, null, 'The best treatment for a student who accidentally poured concentrated tetraoxosulphate(VI) acid on his skin in the laboratory is to wash the skin with', '["cold water","sodium trioxocarbonate(IV) solution","Iodine solution","Sodium trioxocarbonate(IV) solution"]', '<u>Wash with Na2CO3 solution</u> to neutralize the acid.', '{"bold":[],"italic":[],"underline":["sodium trioxocarbonate(IV) solution"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cx3335p6ttvgj4gwcqyese0xe', 'Biology', 'JAMB', null, 1991, null, 'Vaccination is carried out in order to', null, '["check the production of poison","increase the activity of white blood cells","increase the number of red blood cell","stimulate the production of antibodies"]', 3, 'Vaccination stimulates antibody production.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Vaccination is carried out in order to', '["check the production of poison","increase the activity of white blood cells","increase the number of red blood cell","<u>stimulate the production of antibodies</u>"]', 'Vaccination <u>stimulates antibody production</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cx35mtfy2sbeqi0ye2lkgsoms', 'General Mathematics', 'JAMB', null, 2020, null, 'Express 0.125 as a percentage of 0.05.', null, '["200%","250%","300%","400%"]', 1, '0.125/0.05 = 2.5 = 250%.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Express 0.125 as a percentage of 0.05.', '["200%","250%","300%","400%"]', '0.125/0.05 = <u>250%</u>.', '{"bold":[],"italic":[],"underline":["250%"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cx36who9aowritywsew43gbfu', 'General Mathematics', 'WAEC', null, 2020, null, 'The median of a set of 10 numbers is 12.5. The 5th and 6th terms (when arranged in ascending order) are in the ratio 4:5. Find the 6th term.', null, '["10","12.5","15","20"]', 2, 'Let terms 4x, 5x; median = (4x+5x)/2 = 12.5 → 4.5x = 12.5 → x = 2.78; 6th = 13.9 ≈ 15. Key says 15.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The median of a set of 10 numbers is 12.5. The 5th and 6th terms (when arranged in ascending order) are in the ratio 4:5. Find the 6th term.', '["10","12.5","15","20"]', '6th term = <u>15</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cx3ejhbmk1ujvv52nctuj1t08', 'Biology', 'JAMB', null, 1993, null, 'Soil fertility can be conserved and renewed by', null, '["yearly mono cropping","crop rotation and cover crops","bush burning to remove unwanted debris","avoiding artificial manures"]', 1, 'Crop rotation and cover crops conserve soil fertility.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Soil fertility can be conserved and renewed by', '["yearly mono cropping","<u>crop rotation and cover crops</u>","bush burning to remove unwanted debris","avoiding artificial manures"]', '<u>Crop rotation and cover crops</u> conserve soil fertility.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cx3noaesvz4yrlhyhdsm9umw5', 'Chemistry', 'JAMB', null, 1999, null, 'The entropy and enthalpy of a system are a measure of', null, '["degree of disorderliness and heat content respectively","heat content and degree of disorderliness respectively","heat content of a system only","degree of disorderliness only"]', 0, 'Entropy = disorder; enthalpy = heat content.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The entropy and enthalpy of a system are a measure of', '["degree of disorderliness and heat content respectively","heat content and degree of disorderliness respectively","heat content of a system only","degree of disorderliness only"]', '<u>Entropy = disorder; enthalpy = heat content</u>.', '{"bold":[],"italic":[],"underline":["degree of disorderliness and heat content respectively"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cx3o7nnsioetsesbp2ec4ywdu', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'The crowd joined in attacking them; and the magistrates tore the garments off them and gave orders to beat them with rods. The people attacked in the statement above were', null, '["Peter and Paul","Barnabas and Paul","Paul and John Mark","Paul and Silas."]', 3, 'Paul and Silas were attacked.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The crowd joined in attacking them; and the magistrates tore the garments off them and gave orders to beat them with rods. The people attacked in the statement above were', '["Peter and Paul","Barnabas and Paul","Paul and John Mark","<u>Paul and Silas.</u>"]', '<u>Paul and Silas</u> (Acts 16:22).', '{"bold":[],"italic":[],"underline":["Paul and Silas."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cx3rqdewl8c9dmwuh8s4m5dxr', 'General Mathematics', 'JAMB', null, 2020, null, 'If lines 2x + 3y = 5 and kx + 6y = 10 are parallel, find k.', null, '["4","3","2","1"]', 0, 'Slopes equal: -2/3 = -k/6 → k = 4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If lines 2x + 3y = 5 and kx + 6y = 10 are parallel, find k.', '["4","3","2","1"]', 'k = <u>4</u>.', '{"bold":[],"italic":[],"underline":["4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cx3tjppofsxuws3p5yv3ufzs0', 'General Mathematics', 'JAMB', null, 2020, null, 'Two numbers are selected at random (without replacement) from the first six positive integers. Find the probability that the sum is 8 given that one of the numbers is odd.', null, '["1/5","1/12","3/5","4/5"]', 1, 'Pairs with at least one odd = 15 - 3 = 12; only {3,5} sums to 8, so P = 1/12.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Two numbers are selected at random (without replacement) from the first six positive integers. Find the probability that the sum is 8 given that one of the numbers is odd.', '["1/5","1/12","3/5","4/5"]', 'Pairs with at least one odd = 15 - 3 = 12; only {3,5} sums to 8, so P = 1/12.', '{"bold":[],"italic":[],"underline":["2/5"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cx3yw1d7bn92gttb30kcyx2ye', 'General Mathematics', 'JAMB', null, 2020, null, 'A particle is projected vertically upwards with a velocity of 20 m/s. Find the time taken to return to the point of projection. (g = 10 m/s²)', null, '["2 s","4 s","6 s","8 s"]', 1, 'Time = 2u/g = 40/10 = 4 s.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A particle is projected vertically upwards with a velocity of 20 m/s. Find the time taken to return to the point of projection. (g = 10 m/s²)', '["2 s","4 s","6 s","8 s"]', 'Time = <u>4 s</u>.', '{"bold":[],"italic":[],"underline":["4 s"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cx4969ttw18ngit3k8qstedgg', 'Biology', 'JAMB', null, 1997, null, 'Coconut and oil palm fruits can be grouped as', null, '["berry","legume","Capsule","drupe."]', 3, 'drupe. is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Coconut and oil palm fruits can be grouped as', '["berry","legume","Capsule","<u>drupe.</u>"]', 'drupe. is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cx4u932u899qqclucske1l0cd', 'Chemistry', 'JAMB', null, 1985, null, 'Which of the following is an <b>acid salt</b>?', null, '["NaHSO4","Na2SO4","CH3CO2Na","Na2S"]', 0, 'NaHSO4 is an acid salt (contains replaceable H).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Which of the following is an <b>acid salt</b>?', '["NaHSO4","Na2SO4","CH3CO2Na","Na2S"]', '<u>NaHSO4</u> is an acid salt.', '{"bold":["acid salt"],"italic":[],"underline":["NaHSO4"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cx4x4eua60161hkkontethbwy', 'General Mathematics', 'JAMB', null, 2020, null, 'If α and β are the roots of x² - 5x + 2 = 0, find the equation whose roots are α²/β and β²/α.', null, '["2x² - 21x + 4 = 0","2x² + 21x + 4 = 0","4x² - 21x + 2 = 0","4x² + 21x + 2 = 0"]', 0, 'α+β = 5, αβ = 2; new sum = (α³+β³)/αβ = (125-30)/2 = 95/2; new product = αβ = 2; equation: 2x² - 21x + 4 = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If α and β are the roots of x² - 5x + 2 = 0, find the equation whose roots are α²/β and β²/α.', '["2x² - 21x + 4 = 0","2x² + 21x + 4 = 0","4x² - 21x + 2 = 0","4x² + 21x + 2 = 0"]', 'Equation: <u>2x² - 21x + 4 = 0</u>.', '{"bold":[],"italic":[],"underline":["2x² - 21x + 4 = 0"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cx4yb6udosmxiaur3b3ln0zi0', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'Jihad against carnal self is a', null, '["minor jihad","major jihad","compulsory jihad","desirable jihad"]', 1, 'It is a major jihad.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Jihad against carnal self is a', '["minor jihad","<u>major jihad</u>","compulsory jihad","desirable jihad"]', '<u>Major jihad</u>.', '{"bold":[],"italic":[],"underline":["major jihad"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cx56gecisnn6f4pf1dz3gvl6y', 'General Mathematics', 'WAEC', null, 2020, null, 'Solve (x-2)/(x+3) ≤ 0.', null, '["(-3, 2)","[-3, 2)","(-3, 2]","[-3, 2]"]', 2, '(x-2)/(x+3) ≤ 0: critical points x = 2 and x = -3; sign chart gives -3 < x ≤ 2.', true, '2026-10-11 07:17:11.699', '2026-10-11 21:10:57.289', null, null, null, 'Solve (x-2)/(x+3) ≤ 0.', '["(-3, 2)","[-3, 2)","(-3, 2]","[-3, 2]"]', '(x-2)/(x+3) ≤ 0: critical points x = 2 and x = -3; sign chart gives -3 < x ≤ 2.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cx5961uug1zfglwmdvez7116t', 'General Mathematics', 'WAEC', null, 2020, null, 'Find the integer values satisfying x² - 5x + 4 ≤ 0.', null, '["1, 2, 3, 4","1, 2, 3","2, 3, 4","1, 4"]', 0, '(x-1)(x-4) ≤ 0 → 1 ≤ x ≤ 4 → integers 1, 2, 3, 4.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the integer values satisfying x² - 5x + 4 ≤ 0.', '["1, 2, 3, 4","1, 2, 3","2, 3, 4","1, 4"]', '<u>1, 2, 3, 4</u>.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cx5cklthtdt9htdemuja40i8y', 'Biology', 'JAMB', null, 2004, null, 'The <b>alkyl group</b> can be represented by the general formula', null, '["CnH2n","CnH2n-2","CnH2n+1","CnH2n+2"]', 2, 'Alkyl group = CnH2n+1.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The <b>alkyl group</b> can be represented by the general formula', '["CnH2n","CnH2n-2","CnH2n+1","CnH2n+2"]', '<u>CnH2n+1</u>.', '{"bold":["alkyl group"],"italic":[],"underline":["CnH2n+1"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cx5cnrc0cddvbjflowhfideg5', 'Chemistry', 'JAMB', null, 1987, null, 'An isotope has an atomic number of 17 and a mass number of 36. Which of the following gives the correct number of neutrons and protons in an atom of the isotope?', null, '["Neutrons 19, Protons 17","Neutrons 17, Protons 36","Neutrons 19, Protons 17","Neutrons 36, Protons 17"]', 2, 'Protons = atomic number = 17; neutrons = mass number - atomic number = 36 - 17 = 19.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An isotope has an atomic number of 17 and a mass number of 36. Which of the following gives the correct number of neutrons and protons in an atom of the isotope?', '["Neutrons 19, Protons 17","Neutrons 17, Protons 36","Neutrons 19, Protons 17","Neutrons 36, Protons 17"]', 'Protons = 17; neutrons = <u>19</u>.', '{"bold":[],"italic":[],"underline":["Neutrons 19, Protons 17"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cx5f9toag1gseknypixr96c8q', 'Chemistry', 'JAMB', null, 1994, null, 'MnO4⁻(aq) + 8H⁺(aq) + 5Fe²⁺(aq) → Mn²⁺(aq) + 5Fe³⁺ + 4H2O(l). The oxidation number of manganese in the above reaction changes from', null, '["+7 to +2","+6 to +2","+5 to +2","+4 to +2"]', 0, 'Mn goes from +7 (MnO4⁻) to +2 (Mn²⁺).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'MnO4⁻(aq) + 8H⁺(aq) + 5Fe²⁺(aq) → Mn²⁺(aq) + 5Fe³⁺ + 4H2O(l). The oxidation number of manganese in the above reaction changes from', '["+7 to +2","+6 to +2","+5 to +2","+4 to +2"]', 'Mn changes from <u>+7 to +2</u>.', '{"bold":[],"italic":[],"underline":["+7 to +2"],"fillBlanks":[]}');
