insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cx5i58l8kb3mtqa1p294emwic', 'Government', 'JAMB', null, 2020, null, 'The bringing of a session of a parliament to an end through royal proclamation is known as', null, '["political impasse","dissolution of parliament","vote of no confidence","prorogation of parliament."]', 3, 'Prorogation ends a parliamentary session by royal proclamation.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The bringing of a session of a parliament to an end through royal proclamation is known as', '["political impasse","dissolution of parliament","vote of no confidence","<u>prorogation of parliament.</u>"]', '<u>Prorogation of parliament</u>.', '{"bold":[],"italic":[],"underline":["prorogation of parliament."],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cx603w0c1rtlnhwozfza6jusy', 'Christian Religious Studies', 'JAMB', null, 2020, null, '... The earth produces of itself, first the blade, then the ear, then the full grain in the ear... The statement above was made by Jesus in the parable of the', null, '["Weeds","seed growing secretly","sower","mustard seed."]', 1, 'This is the parable of the seed growing secretly.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '... The earth produces of itself, first the blade, then the ear, then the full grain in the ear... The statement above was made by Jesus in the parable of the', '["Weeds","<u>seed growing secretly</u>","sower","mustard seed."]', '<u>Seed growing secretly</u> (Mark 4:26-29).', '{"bold":[],"italic":[],"underline":["seed growing secretly"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cx6420nc7mbderatzmyo6pg7i', 'Government', 'JAMB', null, 2020, null, 'A true democracy in the modern sense exists where the', null, '["elected representatives rule","majority of the people vote","majority of the people rule","elite rules."]', 0, 'Modern democracy operates through elected representatives.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A true democracy in the modern sense exists where the', '["<u>elected representatives rule</u>","majority of the people vote","majority of the people rule","elite rules."]', '<u>Elected representatives rule</u>.', '{"bold":[],"italic":[],"underline":["elected representatives rule"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cx66kc4dexnyplak9j276z9tj', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Are you the only visitor to Jerusalem who does not know the things that have happened there in these days? The things being referred to in the statement above are the', null, '["triumphal entry and cleansing of the Temple","arrest, trials and judgment of Jesus","crucifixion, death and resurrection of Jesus","birth and presentation of Jesus"]', 2, 'The things were the crucifixion, death, and resurrection of Jesus.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Are you the only visitor to Jerusalem who does not know the things that have happened there in these days? The things being referred to in the statement above are the', '["triumphal entry and cleansing of the Temple","arrest, trials and judgment of Jesus","<u>crucifixion, death and resurrection of Jesus</u>","birth and presentation of Jesus"]', '<u>Crucifixion, death and resurrection of Jesus</u> (Luke 24:18-23).', '{"bold":[],"italic":[],"underline":["crucifixion, death and resurrection of Jesus"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cx67xot3vk5st1ip4x8n7w0gw', 'General Mathematics', 'JAMB', null, 2020, null, 'Find the equation of the circle with a diameter from (1, 2) to (3, 4).', null, '["x² + y² - 4x - 6y + 11 = 0","x² + y² - 4x - 6y + 13 = 0","x² + y² - 4x - 6y + 9 = 0","x² + y² - 4x - 6y + 7 = 0"]', 0, 'Center (2, 3), r² = 2; equation: (x-2)² + (y-3)² = 2 → x² + y² - 4x - 6y + 11 = 0.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Find the equation of the circle with a diameter from (1, 2) to (3, 4).', '["x² + y² - 4x - 6y + 11 = 0","x² + y² - 4x - 6y + 13 = 0","x² + y² - 4x - 6y + 9 = 0","x² + y² - 4x - 6y + 7 = 0"]', 'Equation: <u>x² + y² - 4x - 6y + 11 = 0</u>.', '{"bold":[],"italic":[],"underline":["x² + y² - 4x - 6y + 11 = 0"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cx67yeyy3odkhqe1nhaaj906i', 'Chemistry', 'JAMB', null, 1983, null, 'Naphthalene when heated melts at 354K (81°C). At this temperature the molecules of naphthalene', null, '["decompose into smaller molecules","change their shape","are oxidized by atmospheric oxygen","contract","become mobile as the intermolecular forces are broken"]', 4, 'Melting breaks intermolecular forces, making molecules mobile.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Naphthalene when heated melts at 354K (81°C). At this temperature the molecules of naphthalene', '["decompose into smaller molecules","change their shape","are oxidized by atmospheric oxygen","contract","become mobile as the intermolecular forces are broken"]', '<u>Melting breaks intermolecular forces</u>, making molecules mobile.', '{"bold":[],"italic":[],"underline":["become mobile as the intermolecular forces are broken"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cx69628fyfowzi4cbwvo1e82d', 'Biology', 'JAMB', null, 1994, null, 'The DNA molecules is a chain of repeating', null, '["nucleosides","nitrogenous bases","sugar Phosphates","nucleotides"]', 3, 'DNA is a chain of repeating nucleotides.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The DNA molecules is a chain of repeating', '["nucleosides","nitrogenous bases","sugar Phosphates","<u>nucleotides</u>"]', 'DNA is a chain of repeating <u>nucleotides</u>.', null);
