insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cx6j6hy9jibdiadbadjzkm2en', 'Chemistry', 'JAMB', null, 1984, null, 'An organic compound contains 72% carbon, 12% hydrogen and 16% oxygen by mass. The empirical formula of the compound is', null, '["C6H22O3","C6H10O3","C12H12O","C6H12O","C3CH10"]', 3, 'Moles ratio C:H:O = 72/12 : 12/1 : 16/16 = 6:12:1 → C6H12O.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'An organic compound contains 72% carbon, 12% hydrogen and 16% oxygen by mass. The empirical formula of the compound is', '["C6H22O3","C6H10O3","C12H12O","C6H12O","C3CH10"]', 'Moles ratio = <u>C6H12O</u>.', '{"bold":[],"italic":[],"underline":["C6H12O"],"fillBlanks":[]}');
