insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cx6y9bz58yn9mpmxpnqirxi9r', 'Biology', 'JAMB', null, 1997, null, 'The part of the stomach nearer the gullet is called the', null, '["epiglottis","cardiac sphincter","duodenum","pyloric sphincter."]', 1, 'cardiac sphincter is the best answer because it matches the biological principle tested by the question.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The part of the stomach nearer the gullet is called the', '["epiglottis","<u>cardiac sphincter</u>","duodenum","pyloric sphincter."]', 'cardiac sphincter is the best answer because it matches the biological principle tested by the question.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cx6yrxh3uplshgspz1i3lihqs', 'Chemistry', 'JAMB', null, 1988, null, 'Crude copper can be purified by the electrolysis of CuSO4(aq) if', null, '["platinum electrodes are used","the crude copper is made the anode of the cell","the crude copper is made the cathode of the cell","crude copper electrodes are used"]', 1, 'Crude copper is the anode; pure copper deposits on the cathode.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Crude copper can be purified by the electrolysis of CuSO4(aq) if', '["platinum electrodes are used","the crude copper is made the anode of the cell","the crude copper is made the cathode of the cell","crude copper electrodes are used"]', '<u>Crude copper is the anode</u>; pure Cu deposits on cathode.', '{"bold":[],"italic":[],"underline":["the crude copper is made the anode of the cell"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cx72cbn2k1qnyi4ar91y7zs3i', 'Chemistry', 'JAMB', null, 1995, null, 'If a gas occupies a container of volume 146cm³ at 18°C and 0.971 atm, its volume in cm³ at s.t.p is', null, '["133","146","266","292"]', 0, 'V2 = (0.971×146×273)/(1×291) = 133 cm³.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'If a gas occupies a container of volume 146cm³ at 18°C and 0.971 atm, its volume in cm³ at s.t.p is', '["133","146","266","292"]', 'V2 = <u>133 cm³</u>.', '{"bold":[],"italic":[],"underline":["133"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cx72dlbc97nhhcy7c2m4hifp0', 'Christian Religious Studies', 'JAMB', null, 2020, null, 'Before his call, Amos was a', null, '["farmer","prophet","herdsman","seer."]', 2, 'Amos was a herdsman.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Before his call, Amos was a', '["farmer","prophet","<u>herdsman</u>","seer."]', '<u>Herdsman</u> (Amos 7:14).', '{"bold":[],"italic":[],"underline":["herdsman"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cx73cxpabyvy6ma9k95k9ktd7', 'Chemistry', 'JAMB', null, 1996, null, 'A sample of temporary hard water can be prepared in the laboratory by', null, '["dissolving calcium chloride in distilled water","saturating lime water with carbon(IV) oxide","saturating distilled water with calcium hydroxide","dissolving sodium hydrogen trioxocarbonate(IV) in some distilled water"]', 1, 'Temporary hard water contains Ca(HCO3)2.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'A sample of temporary hard water can be prepared in the laboratory by', '["dissolving calcium chloride in distilled water","saturating lime water with carbon(IV) oxide","saturating distilled water with calcium hydroxide","dissolving sodium hydrogen trioxocarbonate(IV) in some distilled water"]', '<u>Saturating lime water with CO2</u> gives temporary hard water.', '{"bold":[],"italic":[],"underline":["saturating lime water with carbon(IV) oxide"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cx798nb2cocns1iwj8wajph7k', 'Biology', 'JAMB', null, 1983, null, '''Joined skeleton'' is absent in the', null, '["cockroach","spider","millipede","snail","dragon fly"]', 3, 'Snails have a shell (exoskeleton) but not a jointed skeleton.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, '''Joined skeleton'' is absent in the', '["cockroach","spider","millipede","<u>snail</u>","dragon fly"]', '<u>Snails</u> have a shell (exoskeleton) but not a jointed skeleton.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cx7a7eojx8ey8m2nqmvprubvv', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'The Surah that tells us the story of how the Ka''abah was delivered from destruction is', null, '["al-Fatihah","al-''Alaq","al-Fil","''Abasa"]', 2, 'Surat al-Fil tells the story of the Ka''abah''s deliverance.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The Surah that tells us the story of how the Ka''abah was delivered from destruction is', '["al-Fatihah","al-''Alaq","<u>al-Fil</u>","''Abasa"]', '<u>Al-Fil</u>.', '{"bold":[],"italic":[],"underline":["al-Fil"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cx7bt6q694kaaz327hsqe10ch', 'Islamic Religious Studies', 'JAMB', null, 2020, null, 'According to Hadith 6 of an-Nawawi, it is better to avoid ambiguous matters in order to', null, '["avert self-destruction","avoid being a hypocrite","protect one''s religion","escape hell fire."]', 2, 'It protects one''s religion and honour.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'According to Hadith 6 of an-Nawawi, it is better to avoid ambiguous matters in order to', '["avert self-destruction","avoid being a hypocrite","<u>protect one''s religion</u>","escape hell fire."]', '<u>Protect one''s religion</u>.', '{"bold":[],"italic":[],"underline":["protect one''s religion"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cx7gn5866474w4ki9ce4d2wdn', 'General Mathematics', 'JAMB', null, 2020, null, 'Solve |x+2| + |x-2| ≤ 4.', null, '["[-2, 2]","[-4, 4]","(-2, 2)","x = 0 only"]', 0, 'For x in [-2, 2]: (x+2) + (2-x) = 4. So all x in [-2, 2].', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'Solve |x+2| + |x-2| ≤ 4.', '["[-2, 2]","[-4, 4]","(-2, 2)","x = 0 only"]', '<u>[-2, 2]</u>.', '{"bold":[],"italic":[],"underline":["[-2, 2]"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cx7wv61183laye5f3btlheexr', 'Chemistry', 'JAMB', null, 1991, null, 'The data in the table above shows the rate of reaction of nitrogen(II) oxide with chlorine at 25°C. It can be concluded that doubling the initial concentration of NO increases the rate of reaction by a factor of', null, '["two","three","four","five"]', 2, 'Rate ∝ [NO]², so doubling [NO] quadruples rate.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The data in the table above shows the rate of reaction of nitrogen(II) oxide with chlorine at 25°C. It can be concluded that doubling the initial concentration of NO increases the rate of reaction by a factor of', '["two","three","four","five"]', 'Doubling [NO] increases rate by <u>4</u>.', '{"bold":[],"italic":[],"underline":["four"],"fillBlanks":[]}');
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cx7y2knan4vkb1bghkir6jthk', 'Biology', 'JAMB', null, 1999, null, 'The organism that has a hydrostatic skeleton is', null, '["Tilapia","Hydra","Mosquito larva","Earthworm"]', 1, 'An earthworm uses fluid pressure within its body as a hydrostatic skeleton.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The organism that has a hydrostatic skeleton is', '["Tilapia","<u>Hydra</u>","Mosquito larva","Earthworm"]', 'An earthworm uses fluid pressure within its body as a hydrostatic skeleton.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cx7y7alw0wcxkapiay07k483d', 'Physics', 'JAMB', null, 2021, null, 'X-rays are deflected by I. Magnetic field II. Gravitational field III. Electric field IV. None of the above', null, '["I only","II only","III only","IV only"]', 3, 'X-rays are electromagnetic waves and are not deflected by magnetic or electric fields.', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'X-rays are deflected by<br>I. Magnetic field<br>II. Gravitational field<br>III. Electric field<br>IV. None of the above', '["I only","II only","III only","<u>IV only</u>"]', 'X-rays are <u>not deflected</u> by magnetic or electric fields.', null);
insert into "Question" ("id", "subject", "examType", "institution", "year", "topic", "text", "imageUrl", "options", "correctOption", "explanation", "isActive", "createdAt", "updatedAt", "groupId", "groupOrder", "groupType", "textHtml", "optionsHtml", "explanationHtml", "formatting") overriding system value values ('cx82l7xlf1ow2garq3xu3sdm4', 'Chemistry', 'JAMB', null, 1988, null, 'The formula of the compound formed in a reaction between a trivalent metal M and a tetravalent non-metal X is', null, '["MX","M4X3","M3X4","M2X3"]', 2, 'Trivalent M and tetravalent X give M3X4 (cross-multiply valencies).', true, '2026-10-11 07:17:11.699', '2026-10-11 07:17:11.699', null, null, null, 'The formula of the compound formed in a reaction between a trivalent metal M and a tetravalent non-metal X is', '["MX","M4X3","M3X4","M2X3"]', '<u>M3X4</u> (cross-multiply valencies 3 and 4).', '{"bold":[],"italic":[],"underline":["M3X4"],"fillBlanks":[]}');
